/**
 * Comprehensive Test Suite — METARDU Survey Computation Engine
 * 
 * Validates all P0 corrections against known values and published formulas.
 * Every test case uses independently verifiable reference data.
 */

// Jest globals (describe, it, expect) are available without import.
// Previously imported from 'vitest' — converted for Jest compatibility.

// ─── Atmospheric Corrections ─────────────────────────────────────
import {
  applyAtmosphericCorrection,
  computeVaporPressure,
  getAtmosphericPPM,
  validateAtmosphericConditions,
  STANDARD_CONDITIONS,
  KENYA_CONDITIONS,
} from '../lib/survey/corrections/atmospheric';

// ─── Curvature & Refraction ──────────────────────────────────────
import {
  applyCurvatureRefractionCorrection,
  computeCRCorrection,
  computeMeanEarthRadius,
  maxDistanceWithoutCR,
} from '../lib/survey/corrections/curvature-refraction';

// ─── Grid Scale Factor ───────────────────────────────────────────
import {
  computeUTMPointScaleFactor,
  computeLineScaleFactor,
} from '../lib/survey/corrections/grid-scale-factor';

// ─── Sea Level Reduction ────────────────────────────────────────
import {
  applySeaLevelReduction,
  computeReductionFactor,
  quickSeaLevelReduction,
} from '../lib/survey/corrections/sea-level-reduction';

// ─── Slope Reduction ─────────────────────────────────────────────
import {
  reduceSlopeByAngle,
  reduceSlopeByHeight,
} from '../lib/survey/corrections/slope-reduction';

// ─── Projection Convergence ──────────────────────────────────────
import {
  computeConvergence,
  gridBearingToTrue,
  trueBearingToGrid,
} from '../lib/survey/corrections/projection-convergence';

// ─── Coordinate Transformation ───────────────────────────────────
import {
  arc1960ToWGS84,
  wgs84ToArc1960,
  geodeticToCartesian,
  cartesianToGeodetic,
  computeUTMZone,
} from '../lib/survey/coordinates/transform';

// ─── Traverse ────────────────────────────────────────────────────
import {
  bowditchAdjustment,
  computeBearing,
  computeDistance,
  ORDER_REQUIREMENTS,
} from '../lib/survey/traverse/engine';

// ─── COGO ────────────────────────────────────────────────────────
import {
  computeBearingAndDistance,
  computePoint,
  lineLineIntersection,
  lineCircleIntersection,
} from '../lib/survey/cogo/engine';

// ─── Area ────────────────────────────────────────────────────────
import {
  computeAreaByShoelace,
  computeAreaByDMD,
  convertArea,
} from '../lib/survey/area/computation';

// ─── Error Propagation ───────────────────────────────────────────
import {
  propagateSum,
  propagateScale,
  propagateGeneral,
  propagateCoordinate,
} from '../lib/survey/error-propagation/engine';

// ═════════════════════════════════════════════════════════════════
// ATMOSPHERIC CORRECTION TESTS
// ═════════════════════════════════════════════════════════════════

describe('Atmospheric Correction', () => {
  it('should return zero correction at standard conditions', () => {
    const result = applyAtmosphericCorrection(1000, STANDARD_CONDITIONS);
    expect(result.ppmCorrection).toBeCloseTo(0, 0); // Within ~1 ppm
    expect(result.correctedDistance).toBeCloseTo(1000, 2);
  });

  it('should compute significant correction at Nairobi conditions (~50 ppm)', () => {
    // Nairobi: 20°C, 830 hPa, 60% humidity
    // Lower pressure at altitude causes significant correction
    // Actual value is ~50 ppm (not 22 as originally estimated)
    const result = applyAtmosphericCorrection(1000, {
      temperature: 20,
      pressure: 830,
      humidity: 60,
    });
    expect(Math.abs(result.ppmCorrection)).toBeGreaterThan(40);
    expect(Math.abs(result.ppmCorrection)).toBeLessThan(200);
    // Lower pressure at altitude: air is less dense, light travels faster,
    // EDM reads SHORT → correction is POSITIVE (adds distance back)
    expect(result.correctedDistance).toBeGreaterThan(1000);
  });

  it('should compute correct vapor pressure', () => {
    // At 20°C, 100% humidity: saturation vapor pressure ≈ 23.4 hPa
    const e = computeVaporPressure(20, 100);
    expect(e).toBeCloseTo(23.4, 0);
    
    // At 0°C, 100% humidity: ≈ 6.1 hPa
    const e0 = computeVaporPressure(0, 100);
    expect(e0).toBeCloseTo(6.1, 0);
    
    // At 50% humidity: half the saturation
    const e50 = computeVaporPressure(20, 50);
    expect(e50).toBeCloseTo(11.7, 0);
  });

  it('should validate atmospheric conditions', () => {
    const valid = validateAtmosphericConditions({
      temperature: 25,
      pressure: 900,
      humidity: 60,
    });
    expect(valid.valid).toBe(true);
    
    const extreme = validateAtmosphericConditions({
      temperature: 60,
      pressure: 500,
      humidity: 100,
    });
    expect(extreme.valid).toBe(false);
    expect(extreme.warnings.length).toBeGreaterThan(0);
  });

  it('should throw on invalid inputs', () => {
    expect(() => applyAtmosphericCorrection(-100, STANDARD_CONDITIONS)).toThrow();
    expect(() => computeVaporPressure(100, 50)).toThrow();
  });
});

// ═════════════════════════════════════════════════════════════════
// CURVATURE & REFRACTION TESTS
// ═════════════════════════════════════════════════════════════════

describe('Curvature & Refraction', () => {
  it('should compute ~67.5mm correction at 1km', () => {
    const correction = computeCRCorrection(1000, 0, 0.13);
    expect(correction).toBeCloseTo(0.0675, 2); // ~67.5mm
  });

  it('should compute ~6.75mm correction at 316m (~√0.1 km)', () => {
    // C&R scales as D², so at 316m (~√0.1 km): 0.0675 × 0.1 = 6.75mm
    const correction = computeCRCorrection(316, 0, 0.13);
    expect(correction).toBeCloseTo(0.00675, 2);
  });

  it('should compute correct Earth radius at equator', () => {
    const R = computeMeanEarthRadius(0);
    // At equator, R ≈ 6378 km (close to equatorial radius)
    expect(R).toBeGreaterThan(6350000);
    expect(R).toBeLessThan(6400000);
  });

  it('should compute correct Earth radius at 45° latitude', () => {
    const R = computeMeanEarthRadius(45);
    expect(R).toBeGreaterThan(6350000);
    expect(R).toBeLessThan(6380000);
  });

  it('should apply full C&R correction with heights', () => {
    const result = applyCurvatureRefractionCorrection({
      slopeDistance: 1000,
      verticalAngle: 90, // Horizontal sight
      instrumentHeight: 1.5,
      targetHeight: 1.5,
      latitude: 0,
      refractionCoefficient: 0.13,
    });
    
    // For horizontal sight, height difference should be ~C&R correction
    expect(result.crCorrection).toBeCloseTo(0.0675, 2);
    expect(result.isSignificant).toBe(true); // > 10mm
  });

  it('should compute max distance without C&R exceeding threshold', () => {
    const maxDist = maxDistanceWithoutCR(10, 0, 0.13);
    // Should be around 270m for 10mm threshold
    expect(maxDist).toBeGreaterThan(200);
    expect(maxDist).toBeLessThan(400);
  });
});

// ═════════════════════════════════════════════════════════════════
// GRID SCALE FACTOR TESTS
// ═════════════════════════════════════════════════════════════════

describe('Grid Scale Factor', () => {
  it('should compute scale factor ≈ 0.9996 at UTM central meridian', () => {
    // At the central meridian of UTM Zone 37S (39°E)
    // Easting = 500000 (central meridian), scale factor = k0 = 0.9996
    const result = computeUTMPointScaleFactor(500000, 9900000, 'UTM37S');
    expect(result.scaleFactor).toBeCloseTo(0.9996, 3);
  });

  it('should compute scale factor > 1.0 at 180km from central meridian', () => {
    // At 180km from CM: scale factor ≈ 1.0004
    const result = computeUTMPointScaleFactor(680000, 9900000, 'UTM37S');
    expect(result.scaleFactor).toBeGreaterThan(1.000);
    expect(result.scaleFactor).toBeLessThan(1.001);
  });

  it('should compute line scale factor using Simpson rule', () => {
    // Line from CM to 100km east
    const result = computeLineScaleFactor(
      500000, 9900000,
      600000, 9900000,
      'UTM37S'
    );
    expect(result.lineScaleFactor).toBeGreaterThan(0.9996);
    expect(result.lineScaleFactor).toBeLessThan(1.0005);
    expect(result.ppmCorrection).toBeDefined();
  });

  it('should report ppm from unity', () => {
    const result = computeUTMPointScaleFactor(500000, 9900000, 'UTM37S');
    expect(result.ppmFromUnity).toBeCloseTo(-400, 0); // 0.9996 → -400 ppm
  });
});

// ═════════════════════════════════════════════════════════════════
// SEA LEVEL REDUCTION TESTS
// ═════════════════════════════════════════════════════════════════

describe('Sea Level Reduction', () => {
  it('should compute ~267 ppm reduction at Nairobi altitude (1700m)', () => {
    const result = applySeaLevelReduction({
      horizontalDistance: 1000,
      heightAboveEllipsoid: 1700,
      latitude: 0,
    });
    
    expect(result.reductionPPM).toBeCloseTo(267, -1); // ~267 ppm
    expect(result.ellipsoidalDistance).toBeLessThan(1000);
    expect(result.reductionMeters).toBeCloseTo(0.267, 1); // ~267mm
  });

  it('should compute negligible reduction at sea level', () => {
    const result = applySeaLevelReduction({
      horizontalDistance: 1000,
      heightAboveEllipsoid: 0,
      latitude: 0,
    });
    
    expect(result.reductionPPM).toBeCloseTo(0, 0);
    expect(result.ellipsoidalDistance).toBeCloseTo(1000, 4);
  });

  it('should compute correct reduction factor', () => {
    const { factor, ppm } = computeReductionFactor(1700, 0);
    expect(factor).toBeLessThan(1);
    expect(ppm).toBeCloseTo(267, -1);
  });

  it('should handle orthometric height with geoid undulation', () => {
    const result = applySeaLevelReduction({
      horizontalDistance: 1000,
      orthometricHeight: 1700,
      geoidUndulation: -12,
      latitude: -1,
    });
    
    // Ellipsoidal height = 1700 + (-12) = 1688m
    expect(result.meanHeight).toBeCloseTo(1688, 0);
    expect(result.ellipsoidalDistance).toBeLessThan(1000);
  });
});

// ═════════════════════════════════════════════════════════════════
// SLOPE REDUCTION TESTS
// ═════════════════════════════════════════════════════════════════

describe('Slope Reduction', () => {
  it('should return same distance for horizontal sight (90°)', () => {
    const result = reduceSlopeByAngle({
      slopeDistance: 100,
      verticalAngle: 90,
    });
    expect(result.horizontalDistance).toBeCloseTo(100, 5);
    expect(result.verticalComponent).toBeCloseTo(0, 5);
  });

  it('should correctly reduce 30° slope', () => {
    const result = reduceSlopeByAngle({
      slopeDistance: 200,
      verticalAngle: 90 - 30, // 60° zenith = 30° elevation
    });
    expect(result.horizontalDistance).toBeCloseTo(200 * Math.sin(60 * Math.PI / 180), 5);
    expect(result.verticalComponent).toBeCloseTo(200 * Math.cos(60 * Math.PI / 180), 5);
  });

  it('should reduce by height difference', () => {
    const result = reduceSlopeByHeight({
      slopeDistance: 100,
      heightDifference: 0, // Horizontal
    });
    expect(result.horizontalDistance).toBeCloseTo(100, 5);
  });

  it('should throw when height difference exceeds slope distance', () => {
    expect(() => reduceSlopeByHeight({
      slopeDistance: 100,
      heightDifference: 150,
    })).toThrow();
  });
});

// ═════════════════════════════════════════════════════════════════
// PROJECTION CONVERGENCE TESTS
// ═════════════════════════════════════════════════════════════════

describe('Projection Convergence', () => {
  it('should be zero at central meridian', () => {
    const result = computeConvergence({
      latitude: -1,
      longitude: 39, // Central meridian of UTM Zone 37S
      centralMeridian: 39,
    });
    expect(result.convergence).toBeCloseTo(0, 5);
    expect(result.sign).toBe('on_meridian');
  });

  it('should be negative east of central meridian in southern hemisphere', () => {
    // In the southern hemisphere, convergence is NEGATIVE east of CM
    // This is because sin(φ) < 0 for southern latitudes
    const result = computeConvergence({
      latitude: -1,    // Southern hemisphere
      longitude: 40,   // 1° east of CM
      centralMeridian: 39,
    });
    expect(result.convergence).toBeLessThan(0);
  });

  it('should be positive west of central meridian in southern hemisphere', () => {
    const result = computeConvergence({
      latitude: -1,    // Southern hemisphere
      longitude: 38,   // 1° west of CM
      centralMeridian: 39,
    });
    expect(result.convergence).toBeGreaterThan(0);
  });

  it('should be positive east of central meridian in northern hemisphere', () => {
    const result = computeConvergence({
      latitude: 1,     // Northern hemisphere
      longitude: 40,   // 1° east of CM
      centralMeridian: 39,
    });
    expect(result.convergence).toBeGreaterThan(0);
    expect(result.sign).toBe('E');
  });

  it('should correctly convert grid/true bearings', () => {
    const trueBearing = 45;
    const convergence = 0.5; // 0.5° convergence
    
    const gridBearing = trueBearingToGrid(trueBearing, convergence);
    expect(gridBearing).toBeCloseTo(45.5, 3);
    
    const backToTrue = gridBearingToTrue(gridBearing, convergence);
    expect(backToTrue).toBeCloseTo(45, 3);
  });
});

// ═════════════════════════════════════════════════════════════════
// COORDINATE TRANSFORMATION TESTS
// ═════════════════════════════════════════════════════════════════

describe('Coordinate Transformation', () => {
  it('should compute correct UTM zone', () => {
    expect(computeUTMZone(38.5)).toBe(37);  // Kenya east
    expect(computeUTMZone(32.5)).toBe(36);  // Kenya west
    expect(computeUTMZone(0)).toBe(31);     // Prime meridian
  });

  it('should round-trip geodetic ↔ Cartesian', () => {
    const original = { latitude: -1.2921, longitude: 36.8219, height: 1700 }; // Nairobi
    const cartesian = geodeticToCartesian(original);
    const recovered = cartesianToGeodetic(cartesian);
    
    expect(recovered.latitude).toBeCloseTo(original.latitude, 6);
    expect(recovered.longitude).toBeCloseTo(original.longitude, 6);
    expect(recovered.height!).toBeCloseTo(original.height, 1);
  });

  it('should round-trip Arc 1960 ↔ WGS84', () => {
    const arc1960 = { latitude: -1.2921, longitude: 36.8219, height: 1700 };
    const wgs84 = arc1960ToWGS84(arc1960);
    const recovered = wgs84ToArc1960(wgs84);
    
    // Should recover original within ~0.1 arc-second (~3m)
    expect(recovered.latitude).toBeCloseTo(arc1960.latitude, 4);
    expect(recovered.longitude).toBeCloseTo(arc1960.longitude, 4);
  });
});

// ═════════════════════════════════════════════════════════════════
// COGO TESTS
// ═════════════════════════════════════════════════════════════════

describe('COGO Engine', () => {
  it('should compute correct bearing and distance', () => {
    const from = { easting: 0, northing: 0 };
    const to = { easting: 100, northing: 100 };
    
    const result = computeBearingAndDistance(from, to);
    expect(result.bearing).toBeCloseTo(45, 5); // NE
    expect(result.distance).toBeCloseTo(141.421, 2);
  });

  it('should compute correct point from bearing and distance', () => {
    const from = { easting: 0, northing: 0 };
    const result = computePoint(from, 45, 141.421356);
    
    expect(result.easting).toBeCloseTo(100, 2);
    expect(result.northing).toBeCloseTo(100, 2);
  });

  it('should compute line-line intersection', () => {
    // Two perpendicular lines crossing at origin
    const result = lineLineIntersection(
      { easting: -100, northing: 0 },
      90, // East
      { easting: 0, northing: -100 },
      0,  // North
    );
    
    expect(result.exists).toBe(true);
    expect(result.point.easting).toBeCloseTo(0, 3);
    expect(result.point.northing).toBeCloseTo(0, 3);
  });

  it('should detect parallel lines (no intersection)', () => {
    const result = lineLineIntersection(
      { easting: 0, northing: 0 },
      45,
      { easting: 10, northing: 10 },
      45, // Same bearing = parallel
    );
    
    expect(result.exists).toBe(false);
  });

  it('should compute line-circle intersection', () => {
    // Line going east from origin, circle at (50, 0) radius 30
    const results = lineCircleIntersection(
      { easting: 0, northing: 0 },
      90, // East
      { easting: 50, northing: 0 },
      30
    );
    
    expect(results.length).toBe(2);
    // Intersections at E=20 and E=80
    expect(results[0].easting).toBeCloseTo(20, 1);
    expect(results[1].easting).toBeCloseTo(80, 1);
  });

  it('should round-trip inverse/forward COGO', () => {
    const from = { easting: 250000, northing: 9850000 };
    const bearing = 127.354;
    const distance = 543.210;
    
    const to = computePoint(from, bearing, distance);
    const inverse = computeBearingAndDistance(from, to);
    
    expect(inverse.bearing).toBeCloseTo(bearing, 4);
    expect(inverse.distance).toBeCloseTo(distance, 2);
  });
});

// ═════════════════════════════════════════════════════════════════
// AREA COMPUTATION TESTS
// ═════════════════════════════════════════════════════════════════

describe('Area Computation', () => {
  it('should compute correct area for a square (100m × 100m)', () => {
    const square = [
      { easting: 0, northing: 0 },
      { easting: 100, northing: 0 },
      { easting: 100, northing: 100 },
      { easting: 0, northing: 100 },
    ];
    
    const result = computeAreaByShoelace(square);
    expect(result.areaSqM).toBeCloseTo(10000, 2);
    expect(result.areaHa).toBeCloseTo(1, 3);
  });

  it('should compute correct area for a triangle', () => {
    const triangle = [
      { easting: 0, northing: 0 },
      { easting: 100, northing: 0 },
      { easting: 0, northing: 100 },
    ];
    
    const result = computeAreaByShoelace(triangle);
    expect(result.areaSqM).toBeCloseTo(5000, 2);
  });

  it('should compute perimeter', () => {
    const square = [
      { easting: 0, northing: 0 },
      { easting: 100, northing: 0 },
      { easting: 100, northing: 100 },
      { easting: 0, northing: 100 },
    ];
    
    const result = computeAreaByShoelace(square);
    expect(result.perimeter).toBeCloseTo(400, 2);
  });

  it('should convert area units correctly', () => {
    expect(convertArea(10000, 'sqm', 'ha')).toBeCloseTo(1, 3);
    expect(convertArea(1, 'ha', 'sqm')).toBeCloseTo(10000, 3);
    expect(convertArea(1, 'acre', 'sqm')).toBeCloseTo(4046.856, 2);
  });

  it('should compute area by DMD', () => {
    // Same square as above, using bearings and distances
    const bearings = [90, 0, 270, 180]; // E, N, W, S
    const distances = [100, 100, 100, 100];
    
    const result = computeAreaByDMD(bearings, distances);
    expect(result.areaSqM).toBeCloseTo(10000, 2);
  });

  it('should throw for less than 3 points', () => {
    expect(() => computeAreaByShoelace([{ easting: 0, northing: 0 }])).toThrow();
  });
});

// ═════════════════════════════════════════════════════════════════
// ERROR PROPAGATION TESTS
// ═════════════════════════════════════════════════════════════════

describe('Error Propagation', () => {
  it('should propagate sum uncertainty', () => {
    const values = [
      { value: 100, stdDev: 5, units: 'm' },
      { value: 200, stdDev: 8, units: 'm' },
    ];
    
    const result = propagateSum(values);
    expect(result.computedValue).toBe(300);
    expect(result.stdDev).toBeCloseTo(Math.sqrt(25 + 64), 3); // √(5² + 8²)
  });

  it('should propagate scale uncertainty', () => {
    const value = { value: 100, stdDev: 2, units: 'm' };
    const result = propagateScale(value, 3);
    
    expect(result.computedValue).toBe(300);
    expect(result.stdDev).toBeCloseTo(6, 3); // 3 × 2
  });

  it('should propagate coordinate uncertainty', () => {
    const result = propagateCoordinate(
      { value: 250000, stdDev: 0.02, units: 'm' },
      { value: 9850000, stdDev: 0.02, units: 'm' },
      { value: 500, stdDev: 0.01, units: 'm' },
      { value: 45 * Math.PI / 180, stdDev: 5 / 3600 * Math.PI / 180, units: 'rad' }
    );
    
    // Easting and northing should have propagated uncertainty
    expect(result.easting.stdDev).toBeGreaterThan(0);
    expect(result.northing.stdDev).toBeGreaterThan(0);
    // 95% confidence should be ~1.96× stdDev
    expect(result.easting.confidence95).toBeCloseTo(1.96 * result.easting.stdDev, 2);
  });

  it('should compute contributors percentages', () => {
    const values = [
      { value: 100, stdDev: 10, units: 'm', description: 'A' },
      { value: 200, stdDev: 0, units: 'm', description: 'B' },
    ];
    
    const result = propagateSum(values);
    expect(result.contributors[0].percentage).toBeCloseTo(100, 0);
    expect(result.contributors[1].percentage).toBeCloseTo(0, 0);
  });
});

// ═════════════════════════════════════════════════════════════════
// TRAVERSE ENGINE TESTS
// ═════════════════════════════════════════════════════════════════

describe('Traverse Engine', () => {
  it('should compute correct bearing between points', () => {
    expect(computeBearing(0, 0, 100, 100)).toBeCloseTo(45, 5);
    expect(computeBearing(0, 0, 0, 100)).toBeCloseTo(0, 5); // North
    expect(computeBearing(0, 0, 100, 0)).toBeCloseTo(90, 5); // East
    expect(computeBearing(0, 0, -100, 0)).toBeCloseTo(270, 5); // West
  });

  it('should compute correct distance', () => {
    expect(computeDistance(0, 0, 300, 400)).toBeCloseTo(500, 2);
  });

  it('should have correct order requirements', () => {
    expect(ORDER_REQUIREMENTS[1]).toBe(100000);
    expect(ORDER_REQUIREMENTS[3]).toBe(10000);
  });

  it('should perform Bowditch adjustment on closed traverse', () => {
    const stations = [
      { name: 'A', easting: 0, northing: 0, isFixed: true },
      { name: 'B', isFixed: false },
      { name: 'C', isFixed: false },
      { name: 'D', easting: 0, northing: 0, isFixed: true }, // Closes back
    ];
    
    const legs = [
      { fromStation: 'A', toStation: 'B', bearing: 0, distance: 100 },
      { fromStation: 'B', toStation: 'C', bearing: 90, distance: 100 },
      { fromStation: 'C', toStation: 'D', bearing: 180, distance: 100 },
      { fromStation: 'D', toStation: 'A', bearing: 270, distance: 100 }, // This won't close perfectly
    ];
    
    // This test verifies the framework works — a proper closed traverse
    // with exact bearings would have zero misclosure
    const result = bowditchAdjustment(stations, legs, 3);
    expect(result.adjustmentMethod).toBe('bowditch');
    expect(result.stations.length).toBe(4);
  });
});

// ═════════════════════════════════════════════════════════════════
// INTEGRATION: CORRECTION PIPELINE
// ═════════════════════════════════════════════════════════════════

describe('Correction Pipeline Integration', () => {
  it('should process a typical Kenya observation through all stages', async () => {
    const { processObservation, KENYA_DEFAULT_CONFIG } = await import('../lib/survey/pipeline/correction-pipeline');
    
    const result = processObservation({
      fromStation: 'A',
      toStation: 'B',
      rawSlopeDistance: 500.123,
      verticalAngle: 90.05, // Slightly upward
      horizontalAngle: 45.1234,
      edmConstant: 0.003,
      temperature: 22,
      pressure: 840,
      humidity: 60,
      instrumentHeight: 1.55,
      targetHeight: 1.60,
      heightAboveEllipsoid: 1700,
      fromEasting: 250000,
      fromNorthing: 9850000,
      toEasting: 250350,
      toNorthing: 9850350,
      latitude: -1.0,
      longitude: 37.5,
      edmWavelength: 0.850,
    }, KENYA_DEFAULT_CONFIG);
    
    // Should have all correction stages applied
    expect(result.correctionLog.length).toBeGreaterThan(0);
    expect(result.gridDistance).toBeDefined();
    expect(result.rawSlopeDistance).toBe(500.123);
    // Grid distance should be different from raw due to corrections
    expect(result.gridDistance).not.toBeCloseTo(500.123, 1);
    // Should have audit trail
    expect(result.correctionLog.length).toBeGreaterThanOrEqual(3);
  });

  it('should generate correction report', async () => {
    const { processObservation, processObservations, generateCorrectionReport, KENYA_DEFAULT_CONFIG } = await import('../lib/survey/pipeline/correction-pipeline');
    
    const observations = [{
      fromStation: 'A',
      toStation: 'B',
      rawSlopeDistance: 300.5,
      verticalAngle: 90.0,
      temperature: 25,
      pressure: 830,
      humidity: 55,
    }];
    
    const processed = processObservations(observations, KENYA_DEFAULT_CONFIG);
    const report = generateCorrectionReport(processed);
    
    expect(report).toContain('CORRECTION PIPELINE AUDIT REPORT');
    expect(report).toContain('A → B');
  });
});

'use client';

import { useState } from 'react';

export default function ComputePage() {
  const [method, setMethod] = useState<'bowditch' | 'least_squares'>('bowditch');
  const [order, setOrder] = useState(3);
  const [result, setResult] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const runComputation = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/survey/traverse', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          observations: [
            {
              fromStation: 'A', toStation: 'B',
              rawSlopeDistance: 150.25, verticalAngle: 90.0,
              temperature: 22, pressure: 840, humidity: 60,
              edmConstant: 0.003, instrumentHeight: 1.55, targetHeight: 1.60,
              heightAboveEllipsoid: 1700,
              fromEasting: 250000, fromNorthing: 9850000,
              toEasting: 250150, toNorthing: 9850000,
              latitude: -1.0, longitude: 37.5,
            },
            {
              fromStation: 'B', toStation: 'C',
              rawSlopeDistance: 200.50, verticalAngle: 90.0,
              temperature: 22, pressure: 840, humidity: 60,
              edmConstant: 0.003, instrumentHeight: 1.55, targetHeight: 1.60,
              heightAboveEllipsoid: 1700,
              fromEasting: 250150, fromNorthing: 9850000,
              toEasting: 250150, toNorthing: 9850200,
              latitude: -1.0, longitude: 37.5,
            },
          ],
          stations: [
            { name: 'A', easting: 250000, northing: 9850000, isFixed: true },
            { name: 'B', isFixed: false },
            { name: 'C', isFixed: false },
          ],
          method,
          order,
        }),
      });
      setResult(await res.json());
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h1 style={{ fontSize: '24px', fontWeight: 700, marginBottom: '4px' }}>Traverse Computation</h1>
      <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>
        Run traverse adjustment with all P0 corrections applied automatically
      </p>

      <div style={{ display: 'flex', gap: '16px', marginBottom: '24px', alignItems: 'center' }}>
        <div>
          <label style={{ fontSize: '12px', color: 'var(--text-muted)', display: 'block', marginBottom: '4px' }} htmlFor="adjustment-method">Adjustment Method</label>
          <select id="adjustment-method" className="input-field" value={method} onChange={e => setMethod(e.target.value as any)} style={{ width: '200px' }}>
            <option value="bowditch">Bowditch (3rd/4th Order)</option>
            <option value="least_squares">Least Squares (1st/2nd Order)</option>
          </select>
        </div>
        <div>
          <label style={{ fontSize: '12px', color: 'var(--text-muted)', display: 'block', marginBottom: '4px' }} htmlFor="accuracy-order">Accuracy Order</label>
          <select className="input-field" value={order} onChange={e => setOrder(parseInt(e.target.value))} style={{ width: '200px' }}>
            <option value={1}>1st Order (1:100,000)</option>
            <option value={2}>2nd Order (1:20,000)</option>
            <option value={3}>3rd Order (1:10,000)</option>
            <option value={4}>4th Order (1:5,000)</option>
          </select>
        </div>
        <button className="btn-primary" onClick={runComputation} disabled={loading} style={{ marginTop: '18px' }}>
          {loading ? 'Computing...' : 'Run Adjustment'}
        </button>
      </div>

      {result && (
        <div style={{ display: 'grid', gap: '16px' }}>
          {/* Misclosure */}
          {result.adjustmentResult?.misclosure && (
            <div className="card">
              <h2 style={{ fontSize: '16px', fontWeight: 600, marginBottom: '12px', color: 'var(--accent)' }}>Misclosure Analysis</h2>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', gap: '12px' }}>
                <div style={{ padding: '10px', background: 'var(--bg-secondary)', borderRadius: '6px' }}>
                  <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>dE</div>
                  <div style={{ fontSize: '18px', fontWeight: 700 }}>{result.adjustmentResult.misclosure.easting?.toFixed(4)}</div>
                </div>
                <div style={{ padding: '10px', background: 'var(--bg-secondary)', borderRadius: '6px' }}>
                  <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>dN</div>
                  <div style={{ fontSize: '18px', fontWeight: 700 }}>{result.adjustmentResult.misclosure.northing?.toFixed(4)}</div>
                </div>
                <div style={{ padding: '10px', background: 'var(--bg-secondary)', borderRadius: '6px' }}>
                  <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>Linear</div>
                  <div style={{ fontSize: '18px', fontWeight: 700 }}>{result.adjustmentResult.misclosure.linear?.toFixed(4)}</div>
                </div>
                <div style={{ padding: '10px', background: 'var(--bg-secondary)', borderRadius: '6px' }}>
                  <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>Ratio</div>
                  <div style={{ fontSize: '18px', fontWeight: 700, color: 'var(--accent)' }}>{result.adjustmentResult.misclosure.ratio}</div>
                </div>
              </div>
            </div>
          )}

          {/* Corrections Applied */}
          {result.correctionsApplied && (
            <div className="card">
              <h2 style={{ fontSize: '16px', fontWeight: 600, marginBottom: '12px', color: 'var(--accent)' }}>Corrections Applied</h2>
              <div style={{ fontSize: '13px', overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                  <thead>
                    <tr style={{ borderBottom: '1px solid var(--border)' }}>
                      <th style={{ padding: '8px', textAlign: 'left', fontSize: '11px', color: 'var(--text-muted)' }}>Leg</th>
                      <th style={{ padding: '8px', textAlign: 'right', fontSize: '11px', color: 'var(--text-muted)' }}>Raw Dist</th>
                      <th style={{ padding: '8px', textAlign: 'right', fontSize: '11px', color: 'var(--text-muted)' }}>Grid Dist</th>
                      <th style={{ padding: '8px', textAlign: 'right', fontSize: '11px', color: 'var(--text-muted)' }}>Atm PPM</th>
                      <th style={{ padding: '8px', textAlign: 'right', fontSize: '11px', color: 'var(--text-muted)' }}>SL PPM</th>
                      <th style={{ padding: '8px', textAlign: 'right', fontSize: '11px', color: 'var(--text-muted)' }}>Scale F</th>
                    </tr>
                  </thead>
                  <tbody>
                    {result.correctionsApplied.map((c: any, i: number) => (
                      <tr key={`item-${i}`} style={{ borderBottom: '1px solid var(--border)' }}>
                        <td style={{ padding: '8px' }}>{c.from} → {c.to}</td>
                        <td style={{ padding: '8px', textAlign: 'right' }}>{c.rawDistance?.toFixed(4)}</td>
                        <td style={{ padding: '8px', textAlign: 'right', color: 'var(--accent)' }}>{c.gridDistance?.toFixed(4)}</td>
                        <td style={{ padding: '8px', textAlign: 'right' }}>{c.atmosphericPPM?.toFixed(1)}</td>
                        <td style={{ padding: '8px', textAlign: 'right' }}>{c.seaLevelPPM?.toFixed(1)}</td>
                        <td style={{ padding: '8px', textAlign: 'right' }}>{c.lineScaleFactor?.toFixed(6)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';

interface Observation {
  fromStationId: string;
  toStationId: string;
  rawSlopeDistance: number;
  rawHorizontalAngle?: number;
  rawVerticalAngle?: number;
  edmConstant?: number;
  temperature?: number;
  pressure?: number;
  humidity?: number;
  instrumentHeight?: number;
  targetHeight?: number;
}

export default function ObservationsPage() {
  const { id } = { id: 'demo' }; // useParams would go here
  const [observations, setObservations] = useState<Observation[]>([
    { fromStationId: 'A', toStationId: 'B', rawSlopeDistance: 0, rawVerticalAngle: 90 },
  ]);
  const [syncing, setSyncing] = useState(false);

  const addObservation = () => {
    setObservations([...observations, {
      fromStationId: '',
      toStationId: '',
      rawSlopeDistance: 0,
      rawVerticalAngle: 90,
    }]);
  };

  const removeObservation = (index: number) => {
    setObservations(observations.filter((_, i) => i !== index));
  };

  const updateObs = (index: number, field: keyof Observation, value: any) => {
    const updated = [...observations];
    updated[index] = { ...updated[index], [field]: value };
    setObservations(updated);
  };

  const syncToServer = async () => {
    setSyncing(true);
    try {
      const res = await fetch('/api/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          surveyId: id,
          observations: observations,
          surveyorId: 'demo',
          surveyorName: 'Demo Surveyor',
        }),
      });
      const data = await res.json();
      alert(`Synced ${data.count} observations`);
    } catch (err) {
      console.error(err);
    } finally {
      setSyncing(false);
    }
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <div>
          <h1 style={{ fontSize: '24px', fontWeight: 700 }}>Observations</h1>
          <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginTop: '4px' }}>
            Enter field observations with atmospheric conditions for correction pipeline
          </p>
        </div>
        <div style={{ display: 'flex', gap: '8px' }}>
          <button className="btn-secondary" onClick={addObservation}>+ Add Observation</button>
          <button className="btn-primary" onClick={syncToServer} disabled={syncing}>
            {syncing ? 'Syncing...' : 'Sync to Server'}
          </button>
        </div>
      </div>

      {/* Observation entries */}
      {observations.map((obs, i) => (
        <div key={`${obs}-${i}`} className="card" style={{ marginBottom: '12px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
            <h3 style={{ fontSize: '14px', fontWeight: 600, color: 'var(--accent)' }}>
              Observation {i + 1}
            </h3>
            {observations.length > 1 && (
              <button className="btn-secondary" style={{ fontSize: '12px', padding: '2px 8px' }} onClick={() => removeObservation(i)}>
                Remove
              </button>
            )}
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', gap: '10px' }}>
            <div>
              <label htmlFor={`obs-${i}-from`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>From Station</label>
              <input id={`obs-${i}-from`} className="input-field" value={obs.fromStationId} onChange={e => updateObs(i, 'fromStationId', e.target.value)} placeholder="A" />
            </div>
            <div>
              <label htmlFor={`obs-${i}-to`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>To Station</label>
              <input id={`obs-${i}-to`} className="input-field" value={obs.toStationId} onChange={e => updateObs(i, 'toStationId', e.target.value)} placeholder="B" />
            </div>
            <div>
              <label htmlFor={`obs-${i}-slope`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>Slope Distance (m)</label>
              <input id={`obs-${i}-slope`} className="input-field" type="number" step="0.001" value={obs.rawSlopeDistance} onChange={e => updateObs(i, 'rawSlopeDistance', parseFloat(e.target.value) || 0)} />
            </div>
            <div>
              <label htmlFor={`obs-${i}-vert`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>Vertical Angle (deg)</label>
              <input id={`obs-${i}-vert`} className="input-field" type="number" step="0.0001" value={obs.rawVerticalAngle} onChange={e => updateObs(i, 'rawVerticalAngle', parseFloat(e.target.value))} />
            </div>
            <div>
              <label htmlFor={`obs-${i}-temp`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>Temp (C)</label>
              <input id={`obs-${i}-temp`} className="input-field" type="number" value={obs.temperature ?? ''} onChange={e => updateObs(i, 'temperature', parseFloat(e.target.value))} placeholder="22" />
            </div>
            <div>
              <label htmlFor={`obs-${i}-press`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>Pressure (hPa)</label>
              <input id={`obs-${i}-press`} className="input-field" type="number" value={obs.pressure ?? ''} onChange={e => updateObs(i, 'pressure', parseFloat(e.target.value))} placeholder="840" />
            </div>
            <div>
              <label htmlFor={`obs-${i}-hum`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>Humidity (%)</label>
              <input id={`obs-${i}-hum`} className="input-field" type="number" value={obs.humidity ?? ''} onChange={e => updateObs(i, 'humidity', parseFloat(e.target.value))} placeholder="60" />
            </div>
            <div>
              <label htmlFor={`obs-${i}-inst`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>Inst. Height (m)</label>
              <input id={`obs-${i}-inst`} className="input-field" type="number" step="0.01" value={obs.instrumentHeight ?? ''} onChange={e => updateObs(i, 'instrumentHeight', parseFloat(e.target.value))} placeholder="1.55" />
            </div>
            <div>
              <label htmlFor={`obs-${i}-target`} style={{ fontSize: '11px', color: 'var(--text-muted)', display: 'block', marginBottom: '2px' }}>Target Height (m)</label>
              <input id={`obs-${i}-target`} className="input-field" type="number" step="0.01" value={obs.targetHeight ?? ''} onChange={e => updateObs(i, 'targetHeight', parseFloat(e.target.value))} placeholder="1.60" />
            </div>
          </div>
        </div>
      ))}

      {/* Info card */}
      <div className="card" style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>
        <strong style={{ color: 'var(--accent)' }}>Tip:</strong> Temperature and pressure are critical for atmospheric correction.
        At Nairobi altitude (~840 hPa), missing these values introduces ~50 ppm error per measurement.
        Enter them for every observation to achieve 2nd-order accuracy.
      </div>
    </div>
  );
}

'use client';
import { useEffect, useState, useCallback, useMemo } from 'react'
import Link from 'next/link'
import { createClient, type BrowserSession } from '@/lib/api-client/client'
import type { PlanId } from '@/lib/subscription/catalog'
import type { CurrencyCode } from '@/lib/subscription/catalog'
import { z } from 'zod'
import { apiGet, apiPost, ApiError } from '@/lib/api/client'

// ---------------------------------------------------------------------------
// Schemas
// ---------------------------------------------------------------------------

const subscriptionResponseSchema = z.object({
  plan: z.string().optional(),
  status: z.string().optional(),
  paymentMethod: z.string().optional(),
  currency: z.string().optional(),
  periodStart: z.string().optional(),
  periodEnd: z.string().optional(),
  trialEndsAt: z.string().nullable().optional(),
}).passthrough()

const paymentMutationSchema = z.object({}).passthrough()

interface PaymentRecord {
  id: string
  amount: number
  currency: CurrencyCode
  status: string
  payment_method: string
  transaction_id: string | null
  plan_id: PlanId
  created_at: string
}

interface SubscriptionRecord {
  plan_id: PlanId
  status: string
  payment_method: string
  currency: string
  current_period_start: string
  current_period_end: string
  trial_ends_at: string | null
}

const CURRENCY_SYMBOLS: Record<CurrencyCode, string> = {
  KES: 'KSh ', UGX: 'USh ', TZS: 'TSh ', NGN: '₦ ',
  GHS: 'GH₵ ', ZAR: 'R ', USD: '$ ', EUR: '€ ',
  GBP: '£ ', INR: '₹ ', IDR: 'Rp ', BRL: 'R$ ', AUD: 'A$ ',
}

const STATUS_COLORS: Record<string, string> = {
  completed: 'text-green-400',
  pending: 'text-amber-400',
  failed: 'text-red-400',
  refunded: 'text-gray-400',
  active: 'text-green-400',
  cancelled: 'text-red-400',
  expired: 'text-gray-400',
  trial: 'text-blue-400',
}

export default function BillingPage() {
  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), [])
  const [user, setUser] = useState<any>(null)
  const [subscription, setSubscription] = useState<SubscriptionRecord | null>(null)
  const [payments, setPayments] = useState<PaymentRecord[]>([])
  const [loading, setLoading] = useState(true)
  const [cancelling, setCancelling] = useState(false)
  const [message, setMessage] = useState('')

  const loadData = useCallback(async () => {
    const { data: { session } } = await dbClient.auth.getSession()
    const user = (session as BrowserSession | null)?.user ?? null
    setUser(user)

    if (user) {
      const subPromise = apiGet(
        '/api/subscription',
        subscriptionResponseSchema,
        { ttlMs: 0 },
      ).catch(() => null)
      const payPromise = dbClient
        .from('payment_history')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(10)
      const [subRes, { data: pay }] = await Promise.all([subPromise, payPromise])
      // Map API response to SubscriptionRecord format
      if (subRes) {
        setSubscription({
          plan_id: subRes.plan as PlanId,
          status: subRes.status || 'active',
          payment_method: subRes.paymentMethod || '',
          currency: subRes.currency || 'KES',
          current_period_start: subRes.periodStart || new Date().toISOString(),
          current_period_end: subRes.periodEnd || new Date(Date.now() + 30 * 86400000).toISOString(),
          trial_ends_at: subRes.trialEndsAt || null,
        })
      }
      setPayments((pay || []) as any)
    }
    setLoading(false)
  }, [dbClient])

  useEffect(() => {
    loadData()
  }, [loadData])

  async function handleCancel() {
    if (!confirm('Are you sure you want to cancel your subscription? You will retain access until the end of the billing period.')) return
    setCancelling(true)
    setMessage('')

    const provider = subscription?.payment_method || 'stripe'

    try {
      await apiPost(
        '/api/payments',
        paymentMutationSchema,
        { provider, action: 'cancel-subscription' },
      )
      setMessage('Subscription cancelled. You retain access until the end of your billing period.')
      await loadData()
    } catch (err) {
      if (err instanceof ApiError) {
        setMessage(`Error: ${err.message}`)
      } else {
        setMessage('Error: Failed to cancel')
      }
    }
    setCancelling(false)
  }

  async function handleReactivate() {
    setCancelling(true)
    setMessage('')

    const provider = subscription?.payment_method || 'stripe'

    try {
      await apiPost(
        '/api/payments',
        paymentMutationSchema,
        { provider, action: 'reactivate-subscription' },
      )
      setMessage('Subscription reactivated.')
      await loadData()
    } catch (err) {
      if (err instanceof ApiError) {
        setMessage(`Error: ${err.message}`)
      } else {
        setMessage('Error: Failed to reactivate')
      }
    }
    setCancelling(false)
  }

  const formatAmount = (amount: number, currency: CurrencyCode) =>
    `${CURRENCY_SYMBOLS[currency] || `${currency} `}${amount.toLocaleString()}`

  const formatDate = (date: string) =>
    new Date(date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })

  if (loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-[var(--accent)]">Loading...</div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] py-12">
      <div className="max-w-3xl mx-auto px-6">
        <div className="flex items-center justify-between mb-8">
          <h1 className="text-3xl font-bold text-[var(--text-primary)]">Billing</h1>
          <Link href="/pricing" className="text-[var(--accent)] hover:underline text-sm">
            View Plans
          </Link>
        </div>

        {message && (
          <div className="mb-6 rounded-lg border px-4 py-3 text-sm bg-[var(--bg-secondary)] border-[var(--border-color)]">
            {message}
          </div>
        )}

        <div className="space-y-6">
          <Section title="Current Plan">
            {subscription ? (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-[var(--text-primary)] font-bold text-xl capitalize">
                      {subscription.plan_id} Plan
                    </p>
                    <p className="text-[var(--text-secondary)] text-sm">
                      {subscription.status === 'trial'
                        ? `Free trial ends ${formatDate(subscription.trial_ends_at || '')}`
                        : subscription.status === 'active'
                        ? `Renews ${formatDate(subscription.current_period_end)}`
                        : subscription.status === 'cancelled'
                        ? `Cancels ${formatDate(subscription.current_period_end)} — access ends then`
                        : `Status: ${subscription.status}`}
                    </p>
                    {subscription.payment_method && (
                      <p className="text-[var(--text-muted)] text-xs mt-1">
                        Paid via {subscription.payment_method}
                      </p>
                    )}
                  </div>
                  <span className={`text-sm font-bold px-3 py-1 rounded-full bg-[var(--bg-tertiary)] ${STATUS_COLORS[subscription.status] || 'text-white'}`}>
                    {subscription.status.toUpperCase()}
                  </span>
                </div>

                {subscription.status === 'active' && (
                  <div className="flex gap-3">
                    <button
                      onClick={handleCancel}
                      disabled={cancelling}
                      className="px-4 py-2 border border-red-800 text-red-400 rounded-lg text-sm hover:bg-red-900/20 disabled:opacity-50"
                    >
                      {cancelling ? 'Cancelling...' : 'Cancel Subscription'}
                    </button>
                  </div>
                )}

                {subscription.status === 'cancelled' && (
                  <div className="flex gap-3">
                    <button
                      onClick={handleReactivate}
                      disabled={cancelling}
                      className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-50"
                    >
                      {cancelling ? 'Reactivating...' : 'Reactivate Subscription'}
                    </button>
                  </div>
                )}

                {subscription.status === 'trial' && (
                  <div className="flex gap-3">
                    <Link
                      href="/checkout"
                      className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-semibold hover:bg-[var(--accent-dim)]"
                    >
                      Upgrade Now
                    </Link>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-[var(--text-primary)] font-bold text-xl">Free Plan</p>
                  <p className="text-[var(--text-secondary)] text-sm">No active subscription</p>
                </div>
                <Link
                  href="/pricing"
                  className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-semibold hover:bg-[var(--accent-dim)]"
                >
                  Upgrade
                </Link>
              </div>
            )}
          </Section>

          <Section title="Payment History">
            {payments.length > 0 ? (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-[var(--text-muted)] border-b border-[var(--border-color)]">
                      <th className="pb-2 font-medium">Date</th>
                      <th className="pb-2 font-medium">Plan</th>
                      <th className="pb-2 font-medium">Amount</th>
                      <th className="pb-2 font-medium">Method</th>
                      <th className="pb-2 font-medium">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {payments.map((pay) => (
                      <tr key={pay.id} className="border-b border-[var(--border-color)]/50 text-[var(--text-primary)]">
                        <td className="py-3">{formatDate(pay.created_at)}</td>
                        <td className="py-3 capitalize">{pay.plan_id}</td>
                        <td className="py-3">{formatAmount(pay.amount, pay.currency)}</td>
                        <td className="py-3 capitalize">{pay.payment_method || '—'}</td>
                        <td className={`py-3 font-medium ${STATUS_COLORS[pay.status] || 'text-white'}`}>
                          {pay.status}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <p className="text-[var(--text-secondary)]">No payment history yet.</p>
            )}
          </Section>

          <Section title="Billing Address">
            <p className="text-[var(--text-secondary)] text-sm">
              Contact <a href="mailto:billing@metardu.app" className="text-[var(--accent)] hover:underline">billing@metardu.app</a> to update your billing address or request invoices.
            </p>
          </Section>
        </div>
      </div>
    </div>
  )
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
      <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-4">{title}</h2>
      {children}
    </div>
  )
}

'use client';
import { useEffect, useState } from 'react'
import { useSession } from 'next-auth/react'
import { createClient } from '@/lib/api-client/client'
import { z } from 'zod'
import { apiGet, apiPost, ApiError } from '@/lib/api/client'

// ── Schemas ────────────────────────────────────────────────────────────────
const subscriptionResponseSchema = z.object({
  plan: z.string().optional(),
  status: z.string().optional(),
  trialEndsAt: z.string().optional(),
  periodEnd: z.string().optional(),
}).passthrough()
const updatePasswordMutationSchema = z.object({}).passthrough()

interface Subscription {
  plan_id: string
  status: string
  trial_ends_at: string
  current_period_end: string
  subscription_plans?: { name: string }
}

export default function AccountPage() {
  const { data: session, status } = useSession()
  const dbClient = createClient()
  const [subscription, setSubscription] = useState<Subscription | null>(null)
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState('')

  const user = session?.user ?? null
  const loading = status === 'loading'

  useEffect(() => {
    if (!user?.id) return
    async function loadSubscription() {
      try {
        const data = await apiGet(
          '/api/subscription',
          subscriptionResponseSchema,
          { ttlMs: 0 },
        )
        setSubscription({
          plan_id: data.plan || 'free',
          status: data.status || 'active',
          trial_ends_at: data.trialEndsAt || '',
          current_period_end: data.periodEnd || new Date(Date.now() + 30 * 86400000).toISOString(),
        })
      } catch (err) {
        if (err instanceof ApiError) {
          // Subscription fetch failed — keep default
        }
      }
    }
    loadSubscription()
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id])

  async function updatePassword(newPassword: string) {
    setSaving(true)
    setMessage('')
    try {
      await apiPost(
        '/api/auth/update-password',
        updatePasswordMutationSchema,
        { password: newPassword },
      )
      setMessage('Password updated successfully!')
    } catch (err) {
      if (err instanceof ApiError) {
        setMessage('Error: ' + err.message)
      } else {
        setMessage('Error: Password update failed')
      }
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-[var(--accent)]">Loading...</div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] py-16">
      <div className="max-w-3xl mx-auto px-6">
        <h1 className="text-3xl font-bold text-[var(--text-primary)] mb-8">Account Settings</h1>

        <div className="space-y-8">
          <Section title="Profile">
            <div className="space-y-4">
              <div>
                <label htmlFor="account-email" className="block text-sm text-[var(--text-secondary)] mb-1">Email</label>
                <input id="account-email"
                  type="email"
                  value={user?.email || ''}
                  disabled
                  className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg px-4 py-2 text-[var(--text-muted)]"
                />
              </div>
            </div>
          </Section>

          <Section title="Change Password">
            <form
              onSubmit={(e) => {
                e.preventDefault()
                const form = e.target as HTMLFormElement
                const newPassword = (form.elements.namedItem('newPassword') as HTMLInputElement).value
                updatePassword(newPassword)
              }}
              className="space-y-4"
            >
              <div>
                <label htmlFor="account-new-password" className="block text-sm text-[var(--text-secondary)] mb-1">New Password</label>
                <input id="account-new-password"
                  name="newPassword"
                  type="password"
                  required
                  minLength={6}
                  className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg px-4 py-2 text-[var(--text-primary)]"
                />
              </div>
              <button
                type="submit"
                disabled={saving}
                className="bg-[var(--accent)] text-black px-6 py-2 rounded-lg font-medium hover:bg-[var(--accent-dim)] disabled:opacity-50"
              >
                {saving ? 'Updating...' : 'Update Password'}
              </button>
              {message && (
                <p className={`text-sm ${message.includes('Error') ? 'text-red-500' : 'text-green-500'}`}>
                  {message}
                </p>
              )}
            </form>
          </Section>

          <Section title="Subscription">
            {subscription ? (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-[var(--text-primary)] font-medium capitalize">
                      {subscription.subscription_plans?.name || subscription.plan_id} Plan
                    </p>
                    <p className="text-[var(--text-secondary)] text-sm">
                      {subscription.status === 'trial' 
                        ? `Trial ends ${new Date(subscription.trial_ends_at).toLocaleDateString()}`
                        : `Renews ${new Date(subscription.current_period_end).toLocaleDateString()}`
                      }
                    </p>
                  </div>
                  <span className={`text-xs px-2 py-1 rounded ${
                    subscription.plan_id === 'enterprise' ? 'bg-amber-900/50 text-amber-400' :
                    subscription.plan_id === 'firm' ? 'bg-purple-900/50 text-purple-400' :
                    subscription.plan_id === 'team' ? 'bg-blue-900/50 text-blue-400' :
                    subscription.plan_id === 'pro' ? 'bg-green-900/50 text-green-400' :
                    'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'
                  }`}>
                    {subscription.plan_id.toUpperCase()}
                  </span>
                </div>
                <a
                  href="/pricing"
                  className="inline-block bg-[var(--accent)] text-black px-6 py-2 rounded-lg font-medium hover:bg-[var(--accent-dim)]"
                >
                  {subscription.plan_id === 'free' ? 'Upgrade Plan' : 'Manage Plan'}
                </a>
              </div>
            ) : (
              <p className="text-[var(--text-secondary)]">No active subscription</p>
            )}
          </Section>

          <Section title="Payment History">
            <p className="text-[var(--text-secondary)]">No payment history yet.</p>
          </Section>

          <Section title="Danger Zone">
            <div className="bg-red-900/20 border border-red-800 rounded-lg p-4">
              <h4 className="text-red-400 font-medium mb-2">Delete Account</h4>
              <p className="text-[var(--text-secondary)] text-sm mb-4">
                Once you delete your account, there is no going back. All your projects and data will be permanently deleted.
              </p>
              <button className="bg-red-900 text-red-400 px-4 py-2 rounded-lg text-sm hover:bg-red-800">
                Delete My Account
              </button>
            </div>
          </Section>
        </div>
      </div>
    </div>
  )
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
      <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">{title}</h2>
      {children}
    </div>
  )
}

