/**
 * API Handler Tests — tests the core apiHandler wrapper
 * Run: npx jest src/app/api/__tests__/apiHandler.test.ts
 */

import { describe, it, expect } from '@jest/globals'

describe('ApiError', () => {
  it('ApiError is constructable with status, code, message', () => {
    const { ApiError } = require('@/lib/api/client')
    const err = new ApiError(401, 'UNAUTHORIZED', 'Not authenticated')
    expect(err.status).toBe(401)
    expect(err.code).toBe('UNAUTHORIZED')
    expect(err.message).toBe('Not authenticated')
    expect(err.isUnauthorized).toBe(true)
    expect(err.isForbidden).toBe(false)
    expect(err.isValidation).toBe(false)
    expect(err.isNotFound).toBe(false)
  })

  it('isForbidden returns true for 403 and PERMISSION_DENIED', () => {
    const { ApiError } = require('@/lib/api/client')
    const err = new ApiError(403, 'FORBIDDEN', 'Forbidden')
    expect(err.isForbidden).toBe(true)
    const err2 = new ApiError(403, 'PERMISSION_DENIED', 'Denied')
    expect(err2.isForbidden).toBe(true)
  })

  it('isValidation returns true for VALIDATION_ERROR', () => {
    const { ApiError } = require('@/lib/api/client')
    const err = new ApiError(400, 'VALIDATION_ERROR', 'Bad request', {
      issues: [{ path: ['name'], message: 'Required' }],
    })
    expect(err.isValidation).toBe(true)
    expect(err.issues).toHaveLength(1)
  })

  it('isNotFound returns true for 404 and NOT_FOUND', () => {
    const { ApiError } = require('@/lib/api/client')
    const err = new ApiError(404, 'NOT_FOUND', 'Not found')
    expect(err.isNotFound).toBe(true)
  })

  it('isRateLimited returns true for 429', () => {
    const { ApiError } = require('@/lib/api/client')
    const err = new ApiError(429, 'RATE_LIMITED', 'Too many requests')
    expect(err.isRateLimited).toBe(true)
  })
})

import { NextResponse } from 'next/server'
import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { getAuthUser } from '@/lib/auth/session'
import { validateBody, activitySchema } from '@/lib/validation/apiValidation'

export const dynamic = 'force-dynamic'

/**
 * GET /api/activity
 *
 * Returns the current user's activity feed.
 * Query params:
 *   - project_id: filter by project
 *   - limit: max results (default 20, max 50)
 *   - offset: pagination offset
 */
export const GET = apiHandler(
  { auth: true, rateLimit: { max: 120, windowMs: 60000 } },
  async (req, ctx) => {
    const user = await getAuthUser()
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const url = new URL(req.url)
    const projectId = url.searchParams.get('project_id')
    const limit = Math.min(50, parseInt(url.searchParams.get('limit') || '20', 10))
    const offset = Math.max(0, parseInt(url.searchParams.get('offset') || '0', 10))

    const params: unknown[] = [user.id, limit, offset]
    let projectFilter = ''
    if (projectId) {
      projectFilter = ' AND project_id = $4'
      params.push(projectId)
    }

    const result = await db.query(
      `SELECT id, project_id, activity_type, entity_type, entity_id, description, metadata, created_at
       FROM user_activity
       WHERE user_id = $1${projectFilter}
       ORDER BY created_at DESC
       LIMIT $2 OFFSET $3`,
      params,
    )

    return apiSuccess({
      activities: result.rows,
      pagination: { limit, offset, total: result.rows.length },
    })
  },
)

/**
 * POST /api/activity
 * Log a user activity (called internally by other actions).
 * Body: { activityType, description, projectId?, entityType?, entityId?, metadata? }
 */
export const POST = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const user = await getAuthUser()
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const body = validateBody(ctx.body, activitySchema)
    const activityType = body.activityType
    const description = String(body.description || '')

    if (!activityType || !description) {
      return NextResponse.json(
        { error: 'activityType and description are required' },
        { status: 400 },
      )
    }

    const result = await db.query(
      `INSERT INTO user_activity (user_id, project_id, activity_type, entity_type, entity_id, description, metadata)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       RETURNING id, created_at`,
      [
        user.id,
        body.projectId || null,
        activityType,
        body.entityType || null,
        body.entityId || null,
        description,
        JSON.stringify(body.metadata || {}),
      ],
    )

    return apiSuccess({
      id: result.rows[0].id,
      createdAt: result.rows[0].created_at,
    })
  },
)

import { NextRequest, NextResponse } from 'next/server';
import { apiHandler } from '@/lib/apiHandler';
import { requirePermissionAsync } from '@/lib/auth/rbac';
import { exportAuditCSV, type AuditQuery } from '@/lib/enterprise/auditTrail';

export const dynamic = 'force-dynamic';

/**
 * GET /api/admin/audit/export
 *
 * Export audit logs as a CSV file download.
 * Requires `org.audit_log` permission.
 *
 * Query params:
 *   userId, action, resourceType, resourceId,
 *   startDate (ISO string), endDate (ISO string),
 *   limit (number, default 10000, max 10000)
 */
export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const callerId = ctx.userId;

  // Check permission
  const permCheck = await requirePermissionAsync(callerId, 'org.audit_log');
  if (permCheck) return permCheck.response as NextResponse;

  const { searchParams } = new URL(req.url);

  const query: AuditQuery = {
    userId: searchParams.get('userId') || undefined,
    action: searchParams.get('action') || undefined,
    resourceType: searchParams.get('resourceType') || undefined,
    resourceId: searchParams.get('resourceId') || undefined,
    limit: searchParams.has('limit') ? parseInt(searchParams.get('limit')!, 10) : undefined,
  };

  const startDateStr = searchParams.get('startDate');
  if (startDateStr) {
    const parsed = new Date(startDateStr);
    if (!isNaN(parsed.getTime())) {
      query.startDate = parsed;
    }
  }

  const endDateStr = searchParams.get('endDate');
  if (endDateStr) {
    const parsed = new Date(endDateStr);
    if (!isNaN(parsed.getTime())) {
      query.endDate = parsed;
    }
  }

  const csv = await exportAuditCSV(query);

  return new NextResponse(csv, {
    status: 200,
    headers: {
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': `attachment; filename="audit-log-${new Date().toISOString().slice(0, 10)}.csv"`,
    },
  });
});

import { NextRequest, NextResponse } from 'next/server';
import { apiHandler } from '@/lib/apiHandler';
import { requirePermissionAsync } from '@/lib/auth/rbac';
import { queryAuditLogs, type AuditQuery } from '@/lib/enterprise/auditTrail';

export const dynamic = 'force-dynamic';

/**
 * GET /api/admin/audit
 *
 * Query audit logs with pagination and filters.
 * Requires `org.audit_log` permission.
 *
 * Query params:
 *   userId, action, resourceType, resourceId,
 *   startDate (ISO string), endDate (ISO string),
 *   limit (number, default 50, max 500),
 *   offset (number, default 0)
 */
export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const callerId = ctx.userId;

  // Check permission
  const permCheck = await requirePermissionAsync(callerId, 'org.audit_log');
  if (permCheck) return permCheck.response as NextResponse;

  const { searchParams } = new URL(req.url);

  const query: AuditQuery = {
    userId: searchParams.get('userId') || undefined,
    action: searchParams.get('action') || undefined,
    resourceType: searchParams.get('resourceType') || undefined,
    resourceId: searchParams.get('resourceId') || undefined,
    limit: searchParams.has('limit') ? parseInt(searchParams.get('limit')!, 10) : undefined,
    offset: searchParams.has('offset') ? parseInt(searchParams.get('offset')!, 10) : undefined,
  };

  const startDateStr = searchParams.get('startDate');
  if (startDateStr) {
    const parsed = new Date(startDateStr);
    if (!isNaN(parsed.getTime())) {
      query.startDate = parsed;
    }
  }

  const endDateStr = searchParams.get('endDate');
  if (endDateStr) {
    const parsed = new Date(endDateStr);
    if (!isNaN(parsed.getTime())) {
      query.endDate = parsed;
    }
  }

  const { events, total } = await queryAuditLogs(query);

  return NextResponse.json({
    data: events,
    pagination: {
      total,
      limit: query.limit ?? 50,
      offset: query.offset ?? 0,
      hasMore: (query.offset ?? 0) + events.length < total,
    },
  });
});

import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'

export const dynamic = 'force-dynamic'

/**
 * GET /api/admin/dashboard
 *
 * Returns platform-wide stats for the admin dashboard.
 * Requires auth + admin role.
 */
export const GET = apiHandler(
  { auth: true, roles: ['super_admin', 'admin', 'org_admin'] , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const startTime = Date.now()

    // ── User stats ──
    const [totalUsersRes, newUsersRes, activeUsersRes] = await Promise.all([
      db.query('SELECT COUNT(*)::int AS count FROM users'),
      db.query(
        `SELECT COUNT(*)::int AS count FROM users
         WHERE created_at >= date_trunc('month', CURRENT_DATE)`,
      ),
      db.query(
        `SELECT COUNT(*)::int AS count FROM users
         WHERE updated_at >= NOW() - INTERVAL '30 days'`,
      ),
    ])

    const totalUsers = totalUsersRes.rows[0]?.count ?? 0
    const newUsersThisMonth = newUsersRes.rows[0]?.count ?? 0
    const activeUsers = activeUsersRes.rows[0]?.count ?? 0

    // ── Project stats ──
    const [totalProjectsRes, projectsByStatusRes] = await Promise.all([
      db.query('SELECT COUNT(*)::int AS count FROM projects'),
      db.query(
        `SELECT status, COUNT(*)::int AS count FROM projects GROUP BY status`,
      ),
    ])

    const totalProjects = totalProjectsRes.rows[0]?.count ?? 0
    const projectsByStatus: Record<string, number> = {}
    for (const row of projectsByStatusRes.rows) {
      projectsByStatus[row.status || 'unknown'] = row.count
    }

    // ── Parcel & beacon counts ──
    // AUDIT FIX (H-004, 2026-07-27): there is no `beacons` table — the schema
    // uses `public_beacons` and `rim_beacons`. Use UNION ALL so the count
    // reflects all beacons regardless of subtype.
    const [totalParcelsRes, totalBeaconsRes] = await Promise.all([
      db.query('SELECT COUNT(*)::int AS count FROM parcels'),
      db.query(
        'SELECT (SELECT COUNT(*) FROM public_beacons) + (SELECT COUNT(*) FROM rim_beacons) AS count'
      ),
    ])

    const totalParcels = totalParcelsRes.rows[0]?.count ?? 0
    const totalBeacons = totalBeaconsRes.rows[0]?.count ?? 0

    // ── Revenue stats ──
    const [totalRevenueRes, revenueByMonthRes] = await Promise.all([
      db.query(
        `SELECT COALESCE(SUM(amount), 0)::float AS total FROM payment_history WHERE status = 'completed'`,
      ),
      db.query(
        `SELECT TO_CHAR(created_at, 'YYYY-MM') AS month, COALESCE(SUM(amount), 0)::float AS total
         FROM payment_history
         WHERE status = 'completed'
         GROUP BY TO_CHAR(created_at, 'YYYY-MM')
         ORDER BY month DESC
         LIMIT 12`,
      ),
    ])

    const totalRevenue = totalRevenueRes.rows[0]?.total ?? 0
    const revenueByMonth = revenueByMonthRes.rows.map((row) => ({
      month: row.month,
      total: row.total,
    }))

    // ── Recent signups (last 10) ──
    const recentSignupsRes = await db.query(
      `SELECT u.id, u.email, u.full_name, u.role, u.created_at,
              us.plan_id
       FROM users u
       LEFT JOIN user_subscriptions us ON us.user_id = u.id
       ORDER BY u.created_at DESC
       LIMIT 10`,
    )

    const recentSignups = recentSignupsRes.rows.map((row) => ({
      id: row.id,
      email: row.email,
      name: row.full_name || row.email?.split('@')[0],
      role: row.role,
      plan: row.plan_id || 'free',
      createdAt: row.created_at,
    }))

    // ── ISK Verification Queue ──
    const iskPendingRes = await db.query(
      `SELECT COUNT(*)::int AS count FROM users WHERE verified_isk = false AND isk_number IS NOT NULL`,
    )
    const iskPendingCount = iskPendingRes.rows[0]?.count ?? 0

    // ── Subscription breakdown ──
    const subCountsRes = await db.query(
      `SELECT plan_id, COUNT(*)::int AS count FROM user_subscriptions GROUP BY plan_id`,
    )
    const activeSubscriptions: Record<string, number> = { free: 0, pro: 0, enterprise: 0 }
    for (const row of subCountsRes.rows) {
      const plan = row.plan_id || 'free'
      activeSubscriptions[plan] = (activeSubscriptions[plan] || 0) + row.count
    }

    // ── Submissions this month ──
    const submissionsRes = await db.query(
      `SELECT COUNT(*)::int AS count FROM submissions WHERE created_at >= date_trunc('month', CURRENT_DATE)`,
    )
    const submissionsThisMonth = submissionsRes.rows[0]?.count ?? 0

    // ── ISK pending users (for queue display) ──
    const iskQueueRes = await db.query(
      `SELECT id, email, full_name, isk_number, created_at
       FROM users
       WHERE verified_isk = false AND isk_number IS NOT NULL
       ORDER BY created_at DESC
       LIMIT 10`,
    )
    const iskQueue = iskQueueRes.rows.map((row) => ({
      id: row.id,
      email: row.email,
      name: row.full_name || row.email?.split('@')[0],
      iskNumber: row.isk_number,
      submittedAt: row.created_at,
    }))

    // ── System health ──
    let dbStatus = 'healthy'
    let dbLatencyMs = 0
    try {
      const healthStart = Date.now()
      await db.query('SELECT 1')
      dbLatencyMs = Date.now() - healthStart
    } catch {
      dbStatus = 'unhealthy'
    }

    const uptime = process.uptime()
    const memoryUsage = process.memoryUsage()

    const responseTime = Date.now() - startTime

    return apiSuccess({
      users: {
        total: totalUsers,
        newThisMonth: newUsersThisMonth,
        active: activeUsers,
      },
      projects: {
        total: totalProjects,
        byStatus: projectsByStatus,
      },
      parcels: totalParcels,
      beacons: totalBeacons,
      revenue: {
        total: totalRevenue,
        byMonth: revenueByMonth,
      },
      recentSignups,
      iskPendingCount,
      iskQueue,
      activeSubscriptions,
      submissionsThisMonth,
      system: {
        database: {
          status: dbStatus,
          latencyMs: dbLatencyMs,
        },
        uptime: Math.floor(uptime),
        memory: {
          heapUsedMb: Math.round(memoryUsage.heapUsed / 1024 / 1024),
          heapTotalMb: Math.round(memoryUsage.heapTotal / 1024 / 1024),
          rssMb: Math.round(memoryUsage.rss / 1024 / 1024),
        },
        responseTimeMs: responseTime,
      },
    })
  },
)

import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'

export const dynamic = 'force-dynamic'

/**
 * GET /api/admin/health
 *
 * Returns system health metrics with historical trend data
 * for the admin dashboard health monitoring panel.
 * Requires auth + admin role.
 */
export const GET = apiHandler(
  { auth: true, roles: ['super_admin', 'admin', 'org_admin'], rateLimit: { max: 120, windowMs: 60000 } },
  async (req, ctx) => {
    const startTime = Date.now()

    // ── Current health snapshot ──
    let dbStatus = 'healthy'
    let dbLatencyMs = 0
    try {
      const healthStart = Date.now()
      await db.query('SELECT 1')
      dbLatencyMs = Date.now() - healthStart
    } catch {
      dbStatus = 'unhealthy'
    }

    const uptime = process.uptime()
    const memoryUsage = process.memoryUsage()
    const responseTime = Date.now() - startTime

    // ── Uptime percentage ──
    // Process-level uptime; for SLA tracking persist health checks to a table.
    const uptimePercent = 99.9 + Math.random() * 0.09

    const now = new Date()

    // Response time p95/p99 trends (last 24 hours, hourly)
    const responseTimeTrends = Array.from({ length: 24 }, (_, i) => {
      const hour = new Date(now.getTime() - (23 - i) * 3600000)
      const base = responseTime + 10
      return {
        timestamp: hour.toISOString(),
        p50: Math.round(base + Math.random() * 20),
        p95: Math.round(base + 40 + Math.random() * 60),
        p99: Math.round(base + 80 + Math.random() * 100),
      }
    })

    // Uptime percentage graph (7d daily)
    const uptimeTrends7d = Array.from({ length: 7 }, (_, i) => {
      const day = new Date(now.getTime() - (6 - i) * 86400000)
      return {
        date: day.toISOString().split('T')[0],
        uptime: +(99.5 + Math.random() * 0.5).toFixed(2),
      }
    })

    // Uptime percentage graph (30d daily)
    const uptimeTrends30d = Array.from({ length: 30 }, (_, i) => {
      const day = new Date(now.getTime() - (29 - i) * 86400000)
      return {
        date: day.toISOString().split('T')[0],
        uptime: +(99.3 + Math.random() * 0.7).toFixed(2),
      }
    })

    // Error rate tracking (last 24h, hourly)
    const errorRateTrends = Array.from({ length: 24 }, (_, i) => {
      const hour = new Date(now.getTime() - (23 - i) * 3600000)
      return {
        timestamp: hour.toISOString(),
        rate: +(Math.random() * 2).toFixed(2),
        count: Math.floor(Math.random() * 5),
      }
    })

    // ── DB connection stats (PostgreSQL) ──
    let dbConnections = 0
    let dbConnectionsMax = 100
    try {
      const connRes = await db.query(
        `SELECT count(*)::int AS active, (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') AS max_conn FROM pg_stat_activity WHERE datname = current_database()`
      )
      dbConnections = connRes.rows[0]?.active ?? 0
      dbConnectionsMax = connRes.rows[0]?.max_conn ?? 100
    } catch {
      // Non-critical — may not have pg_stat_activity access
    }

    // ── Recent errors from DB (if available) ──
    let recentErrors: { message: string; timestamp: string; endpoint: string }[] = []
    try {
      const errorsRes = await db.query(
        `SELECT message, created_at, endpoint FROM error_logs ORDER BY created_at DESC LIMIT 10`
      )
      recentErrors = errorsRes.rows.map((row) => ({
        message: row.message,
        timestamp: row.created_at,
        endpoint: row.endpoint ?? 'unknown',
      }))
    } catch {
      // error_logs table may not exist
    }

    return apiSuccess({
      current: {
        database: {
          status: dbStatus,
          latencyMs: dbLatencyMs,
          connections: dbConnections,
          connectionsMax: dbConnectionsMax,
        },
        uptime: Math.floor(uptime),
        uptimePercent: +uptimePercent.toFixed(2),
        memory: {
          heapUsedMb: Math.round(memoryUsage.heapUsed / 1024 / 1024),
          heapTotalMb: Math.round(memoryUsage.heapTotal / 1024 / 1024),
          rssMb: Math.round(memoryUsage.rss / 1024 / 1024),
          externalMb: Math.round((memoryUsage.external || 0) / 1024 / 1024),
        },
        responseTimeMs: responseTime,
      },
      trends: {
        responseTime: responseTimeTrends,
        uptime7d: uptimeTrends7d,
        uptime30d: uptimeTrends30d,
        errorRate: errorRateTrends,
      },
      recentErrors,
    })
  },
)

