})

import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'

export const dynamic = 'force-dynamic'

/**
 * GET /api/admin/payments
 *
 * Returns paginated payment records and summary stats.
 * Requires auth + admin role.
 */
export const GET = apiHandler(
  { auth: true, roles: ['super_admin', 'admin', 'org_admin'] , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, _ctx) => {
    const { searchParams } = new URL(req.url)
    const page = Math.max(1, parseInt(searchParams.get('page') || '1', 10))
    const limit = Math.min(100, Math.max(1, parseInt(searchParams.get('limit') || '25', 10)))
    const offset = (page - 1) * limit

    // ── Fetch payments with user info ──
    const [paymentsRes, countRes] = await Promise.all([
      db.query(
        `SELECT ph.id, ph.user_id, u.email AS user_email,
                COALESCE(u.full_name, SPLIT_PART(u.email, '@', 1)) AS user_name,
                ph.amount, ph.currency, ph.status, ph.payment_method AS method, ph.plan_id, ph.created_at
         FROM payment_history ph
         LEFT JOIN users u ON u.id = ph.user_id
         ORDER BY ph.created_at DESC
         LIMIT $1 OFFSET $2`,
        [limit, offset],
      ),
      db.query('SELECT COUNT(*)::int AS count FROM payment_history'),
    ])

    const payments = paymentsRes.rows.map((row) => ({
      id: row.id,
      userId: row.user_id,
      userEmail: row.user_email,
      userName: row.user_name,
      amount: parseFloat(row.amount) || 0,
      currency: row.currency || 'KES',
      status: row.status || 'pending',
      method: row.method || 'unknown',
      planId: row.plan_id || 'free',
      createdAt: row.created_at,
    }))

    const total = countRes.rows[0]?.count ?? 0
    const totalPages = Math.ceil(total / limit)

    // ── Summary stats ──
    const [totalRevenueRes, thisMonthRes, pendingRes] = await Promise.all([
      db.query(
        `SELECT COALESCE(SUM(amount), 0)::float AS total
         FROM payment_history
         WHERE status = 'completed'`,
      ),
      db.query(
        `SELECT COALESCE(SUM(amount), 0)::float AS total
         FROM payment_history
         WHERE status = 'completed'
           AND created_at >= date_trunc('month', CURRENT_DATE)`,
      ),
      db.query(
        `SELECT COALESCE(SUM(amount), 0)::float AS total
         FROM payment_history
         WHERE status = 'pending'`,
      ),
    ])

    const summary = {
      totalRevenue: totalRevenueRes.rows[0]?.total ?? 0,
      thisMonth: thisMonthRes.rows[0]?.total ?? 0,
      pendingPayouts: pendingRes.rows[0]?.total ?? 0,
    }

    return apiSuccess({
      payments,
      pagination: {
        page,
        limit,
        total,
        totalPages,
        hasMore: page < totalPages,
      },
      summary,
    })
  },
)

import { NextRequest, NextResponse } from 'next/server';
import { apiHandler } from '@/lib/apiHandler';
import { db } from '@/lib/db';
import { assignRole, requirePermissionAsync, type Role, ROLE_HIERARCHY } from '@/lib/auth/rbac';
import { logAuditEvent } from '@/lib/enterprise/auditTrail';
import { z } from 'zod';

export const dynamic = 'force-dynamic';

const assignRoleSchema = z.object({
  role: z.enum(['super_admin', 'org_admin', 'project_manager', 'surveyor', 'viewer']),
});

/**
 * PUT /api/admin/users/[userId]/role
 *
 * Assign a role to a user. Requires `users.invite` permission.
 * Body: { role: Role }
 */
export const PUT = apiHandler(
  { auth: true, schema: assignRoleSchema , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const callerId = ctx.userId;
    const targetUserId = ctx.params.userId;
    const { role } = ctx.body as z.infer<typeof assignRoleSchema>;

    // Check caller has permission to manage users
    const permCheck = await requirePermissionAsync(callerId, 'users.invite');
    if (permCheck) return permCheck.response as NextResponse;

    // Caller can only assign roles at or below their own level
    // Resolve caller role from DB
    const { rows: callerRows } = await db.query(
      `SELECT role FROM user_roles WHERE user_id = $1 AND revoked_at IS NULL
       UNION
       SELECT role FROM surveyor_profiles WHERE user_id = $1
       LIMIT 1`,
      [callerId],
    );

    if (callerRows.length === 0) {
      return NextResponse.json(
        { error: 'Caller role could not be determined', code: 'FORBIDDEN' },
        { status: 403 },
      );
    }

    const callerRoleRaw = callerRows[0].role as string;
    // Map legacy 'admin' → 'org_admin'
    const callerRole = (callerRoleRaw === 'admin' ? 'org_admin' : callerRoleRaw) as Role;
    const callerLevel = ROLE_HIERARCHY.indexOf(callerRole);
    const targetLevel = ROLE_HIERARCHY.indexOf(role);

    if (callerLevel === -1 || targetLevel === -1) {
      return NextResponse.json(
        { error: 'Invalid role', code: 'BAD_REQUEST' },
        { status: 400 },
      );
    }

    // Can only assign roles at or below your level
    if (targetLevel < callerLevel) {
      return NextResponse.json(
        { error: `Cannot assign role '${role}' — insufficient privilege. You can only assign roles at or below '${callerRole}'.`, code: 'FORBIDDEN' },
        { status: 403 },
      );
    }

    // Cannot change your own role
    if (callerId === targetUserId) {
      return NextResponse.json(
        { error: 'Cannot change your own role', code: 'BAD_REQUEST' },
        { status: 400 },
      );
    }

    // Assign the role
    await assignRole(targetUserId, role, callerId);

    // Audit log
    const clientIp = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';
    const userAgent = req.headers.get('user-agent') || undefined;
    await logAuditEvent({
      userId: callerId,
      action: 'user.role.assign',
      resourceType: 'user',
      resourceId: targetUserId,
      details: { newRole: role, previousRole: callerRoleRaw },
      ipAddress: clientIp,
      userAgent,
      timestamp: new Date(),
    });

    return NextResponse.json({
      success: true,
      data: {
        userId: targetUserId,
        newRole: role,
        assignedBy: callerId,
      },
    });
  },
);

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

/**
 * PATCH /api/admin/users/[userId]
 *
 * Update a user's profile fields with optimistic locking.
 * Requires auth + admin or super_admin role.
 *
 * Frontend MUST send `updated_at` in the request body — the value should be
 * the `updated_at` timestamp from the most recent GET/fetch of this user.
 * If the DB row's `updated_at` differs (another admin edited it), returns 409.
 *
 * Body fields are split across two tables:
 *   users table:             full_name, email
 *   surveyor_profiles table: firm_name, license_number, phone
 */
const patchUserProfileSchema = z.object({
  // users table fields
  full_name: z.string().min(1).optional(),
  email: z.string().email().optional(),
  // surveyor_profiles table fields
  firm_name: z.string().nullable().optional(),
  license_number: z.string().nullable().optional(),
  phone: z.string().nullable().optional(),
  // Optimistic locking: frontend must send the updated_at value it last read
  updated_at: z.string(),
})

export const PATCH = apiHandler(
  { auth: true, roles: ['super_admin', 'admin', 'org_admin'], optimisticLock: true, schema: patchUserProfileSchema, rateLimit: { max: 60, windowMs: 60000 } },
  async (_req, ctx) => {
    const { userId } = ctx.params
    const body = ctx.body as z.infer<typeof patchUserProfileSchema>

    // Fetch current user row for optimistic lock check
    const { rows } = await db.query(
      'SELECT id, updated_at FROM users WHERE id = $1',
      [userId]
    )

    if (rows.length === 0) {
      return NextResponse.json(
        { error: 'User not found', code: 'NOT_FOUND' },
        { status: 404 }
      )
    }

    // T1.8 FIX (2026-07-09): Optimistic lock guard moved to the SQL WHERE clause.

    // Build dynamic UPDATE for users table
    const userFields: string[] = []
    const userValues: unknown[] = []
    let userParamIdx = 1

    const userAllowedFields: Record<string, string> = {
      full_name: 'full_name',
      email: 'email',
    }

    for (const [bodyKey, colName] of Object.entries(userAllowedFields)) {
      if (bodyKey in body && body[bodyKey as keyof typeof body] !== undefined) {
        userFields.push(`${colName} = $${userParamIdx++}`)
        userValues.push(body[bodyKey as keyof typeof body])
      }
    }

    // Build dynamic UPDATE for surveyor_profiles table
    const profileFields: string[] = []
    const profileValues: unknown[] = []
    let profileParamIdx = 1

    const profileAllowedFields: Record<string, string> = {
      firm_name: 'firm_name',
      license_number: 'license_number',
      phone: 'phone',
    }

    for (const [bodyKey, colName] of Object.entries(profileAllowedFields)) {
      if (bodyKey in body && body[bodyKey as keyof typeof body] !== undefined) {
        profileFields.push(`${colName} = $${profileParamIdx++}`)
        profileValues.push(body[bodyKey as keyof typeof body])
      }
    }

    if (userFields.length === 0 && profileFields.length === 0) {
      return NextResponse.json(
        { error: 'No fields to update', code: 'NO_FIELDS' },
        { status: 400 }
      )
    }

    // Update users table if there are user fields to update
    if (userFields.length > 0) {
      userFields.push(`updated_at = NOW()`)
      userValues.push(userId)
      // T1.8: Add optimistic lock guard to WHERE clause
      userValues.push(body.updated_at)
      const userResult = await db.query(
        `UPDATE users SET ${userFields.join(', ')} WHERE id = $${userParamIdx} AND updated_at = $${userParamIdx + 1} RETURNING id`,
        userValues
      )
      if (userResult.rows.length === 0) {
        return NextResponse.json(
          { error: 'This user was modified by another admin. Please refresh and try again.', code: 'CONFLICT' },
          { status: 409 }
        )
      }
    }

    // Update surveyor_profiles table if there are profile fields to update
    if (profileFields.length > 0) {
      profileFields.push(`updated_at = NOW()`)
      profileValues.push(userId)
      await db.query(
        `UPDATE surveyor_profiles SET ${profileFields.join(', ')} WHERE user_id = $${profileParamIdx}`,
        profileValues
      )
    }

    // Fetch and return the updated user
    const updated = await db.query(
      `SELECT u.id, u.email, u.full_name, u.updated_at,
              sp.firm_name, sp.license_number, sp.phone
       FROM users u
       LEFT JOIN surveyor_profiles sp ON sp.user_id = u.id
       WHERE u.id = $1`,
      [userId]
    )

    return NextResponse.json({ data: updated.rows[0] })
  }
)

import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { logAuditEvent } from '@/lib/enterprise/auditTrail'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const suspendSchema = z.object({
  reason: z.string().min(1, 'Suspension reason is required'),
})

/**
 * POST /api/admin/users/[userId]/suspend
 *
 * Suspend a user account.
 * Requires auth + admin role.
 */
export const POST = apiHandler(
  { auth: true, roles: ['super_admin', 'admin', 'org_admin'], schema: suspendSchema , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const { userId } = ctx.params
    const { reason } = ctx.body as z.infer<typeof suspendSchema>

    // Check user exists
    const { rows: userRows } = await db.query(
      'SELECT id, email, full_name FROM users WHERE id = $1',
      [userId],
    )
    if (userRows.length === 0) {
      return apiSuccess({ error: 'User not found' }, 404)
    }

    // Suspend the user via surveyor_profiles
    await db.query(
      `INSERT INTO surveyor_profiles (id, user_id, role, is_suspended, suspension_reason)
       VALUES (gen_random_uuid(), $1, 'surveyor', true, $2)
       ON CONFLICT (user_id) DO UPDATE
       SET is_suspended = true, suspension_reason = $2`,
      [userId, reason],
    )

    // Audit log
    const clientIp = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
    await logAuditEvent({
      userId: ctx.userId,
      action: 'user.suspend',
      resourceType: 'user',
      resourceId: userId,
      details: { reason, targetEmail: userRows[0].email },
      ipAddress: clientIp,
      timestamp: new Date(),
    })

    return apiSuccess({ success: true, userId, suspended: true })
  },
)

/**
 * DELETE /api/admin/users/[userId]/suspend
 *
 * Unsuspend a user account.
 * Requires auth + admin role.
 */
export const DELETE = apiHandler(
  { auth: true, roles: ['super_admin', 'admin', 'org_admin'] , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const { userId } = ctx.params

    // Check user exists
    const { rows: userRows } = await db.query(
      'SELECT id, email FROM users WHERE id = $1',
      [userId],
    )
    if (userRows.length === 0) {
      return apiSuccess({ error: 'User not found' }, 404)
    }

    // Unsuspend the user
    await db.query(
      `UPDATE surveyor_profiles
       SET is_suspended = false, suspension_reason = NULL
       WHERE user_id = $1`,
      [userId],
    )

    // Audit log
    const clientIp = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
    await logAuditEvent({
      userId: ctx.userId,
      action: 'user.unsuspend',
      resourceType: 'user',
      resourceId: userId,
      details: { targetEmail: userRows[0].email },
      ipAddress: clientIp,
      timestamp: new Date(),
    })

    return apiSuccess({ success: true, userId, suspended: false })
  },
)

