import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { generateTraverseDXF } from '@/lib/export/traverseDXF'

export const dynamic = 'force-dynamic'

/**
 * POST /api/compute/export/traverse-dxf
 *
 * Accepts `{ projectId }`, fetches traverse data from the database,
 * and returns a downloadable DXF file containing a professional traverse plan.
 *
 * Flow:
 * 1. Verify project ownership
 * 2. Fetch project metadata (name, lr_number, county, datum, surveyor_name)
 * 3. Fetch traverse coordinates and observations for all parcels in the project
 * 4. Build station/leg arrays and misclosure data
 * 5. Call generateTraverseDXF() to produce the DXF string
 * 6. Return as a downloadable DXF response
 */
export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const body = ctx.body as { projectId?: string }
  const { projectId } = body

  if (!projectId) {
    return NextResponse.json(
      { error: 'projectId is required' },
      { status: 400 },
    )
  }

  // ── Verify project ownership ────────────────────────────────────────────
  const { rows: projects } = await db.query(
    `SELECT p.id, p.name, p.location, p.project_type,
            p.surveyor_name,
            sd.scheme_number, sd.datum, sd.county
     FROM projects p
     LEFT JOIN scheme_details sd ON sd.project_id = p.id
     WHERE p.id = $1 AND p.user_id = $2`,
    [projectId, ctx.userId],
  )

  if (projects.length === 0) {
    return NextResponse.json(
      { error: 'Project not found' },
      { status: 404 },
    )
  }

  const project = projects[0]

  // ── Fetch traverse data for all parcels in this project ─────────────────
  const { rows: traverses } = await db.query(
    `SELECT pt.id AS traverse_id,
            pt.parcel_id,
            pt.is_closed,
            pt.linear_error,
            pt.precision_ratio,
            pt.total_perimeter,
            pt.accuracy_order,
            p.parcel_number,
            p.lr_number_proposed,
            b.block_number
     FROM parcel_traverses pt
     JOIN parcels p ON p.id = pt.parcel_id
     JOIN blocks b ON b.id = p.block_id
     WHERE b.project_id = $1
       AND pt.status IN ('computed', 'approved')
     ORDER BY b.block_number, p.parcel_number`,
    [projectId],
  )

  if (traverses.length === 0) {
    return NextResponse.json(
      { error: 'No computed traverses found for this project' },
      { status: 404 },
    )
  }

  // ── Fetch coordinates and observations for each traverse ────────────────
  const stations: Array<{
    name: string
    easting: number
    northing: number
    adjustedEasting?: number
    adjustedNorthing?: number
  }> = []

  const legs: Array<{
    from: string
    to: string
    bearing: number
    distance: number
  }> = []

  let totalAngularMisclosure = 0
  let totalLinearError = 0
  let worstPrecisionRatio = 0

  // Track station names to avoid duplicates across parcels
  const seenStations = new Set<string>()

  for (const traverse of traverses) {
    // Fetch coordinates for this traverse
    const { rows: coords } = await db.query(
      `SELECT station, easting, northing, rl
       FROM traverse_coordinates
       WHERE traverse_id = $1
       ORDER BY station`,
      [traverse.traverse_id],
    )

    // Fetch observations for this traverse
    const { rows: observations } = await db.query(
      `SELECT station, bs, fs,
              hcl_deg, hcl_min, hcl_sec,
              hcr_deg, hcr_min, hcr_sec,
              slope_dist
       FROM traverse_observations
       WHERE traverse_id = $1
       ORDER BY observation_order`,
      [traverse.traverse_id],
    )

    // Build station entries (unique by name)
    for (const c of coords) {
      const stationName = `${c.station}`
      // Prefix with block-parcel to avoid name collisions across parcels
      const uniqueKey = `${traverse.block_number}-${traverse.parcel_number}-${c.station}`
      const displayName = traverses.length > 1
        ? `${traverse.block_number}/${traverse.parcel_number}:${c.station}`
        : c.station

      stations.push({
        name: seenStations.has(stationName) ? displayName : stationName,
        easting: Number(c.easting),
        northing: Number(c.northing),
      })
      seenStations.add(stationName)
    }

    // Build leg entries from observations
    for (let i = 0; i < observations.length; i++) {
      const obs = observations[i]
      const fromStation = obs.station
      const toStation = obs.fs

      // Compute forward bearing from horizontal circle readings (CR - CL)
      const clTotal = (obs.hcl_deg || 0) + (obs.hcl_min || 0) / 60 + (obs.hcl_sec || 0) / 3600
      const crTotal = (obs.hcr_deg || 0) + (obs.hcr_min || 0) / 60 + (obs.hcr_sec || 0) / 3600
      let bearing = crTotal - clTotal
      if (bearing < 0) bearing += 360

      legs.push({
        from: fromStation,
        to: toStation,
        bearing: bearing,
        distance: Number(obs.slope_dist) || 0,
      })
    }

    // Accumulate misclosure data
    if (traverse.linear_error != null) {
      totalLinearError += Number(traverse.linear_error)
    }
    if (traverse.precision_ratio != null) {
      const ratio = Number(traverse.precision_ratio)
      if (ratio > worstPrecisionRatio) worstPrecisionRatio = ratio
    }
  }

  // Compute angular misclosure (sum of bearings around a closed traverse)
  if (legs.length >= 3) {
    const bearingSum = legs.reduce((sum, leg) => sum + leg.bearing, 0)
    // Theoretical sum for a closed traverse: (n - 2) * 180
    const n = legs.length
    const theoreticalSum = (n - 2) * 180
    totalAngularMisclosure = bearingSum - theoreticalSum
  }

  // ── Determine datum string ──────────────────────────────────────────────
  const datum = project.datum || 'Arc 1960 / UTM Zone 37S'

  // ── Generate DXF ───────────────────────────────────────────────────────
  const dxfString = generateTraverseDXF({
    stations,
    legs,
    misclosure: {
      angular: totalAngularMisclosure,
      linear: totalLinearError,
      precisionRatio: worstPrecisionRatio || 0,
    },
    projectInfo: {
      name: project.name,
      lrNumber: project.scheme_number || project.name,
      county: project.county || '—',
      datum,
      surveyor: project.surveyor_name || '—',
    },
  })

  // ── Build filename ──────────────────────────────────────────────────────
  const safeName = (project.name || 'traverse').replace(/[^a-zA-Z0-9_\-]/g, '_')
  const date = new Date().toISOString().split('T')[0]
  const filename = `Traverse_${safeName}_${date}.dxf`

  // ── Return as downloadable DXF response ─────────────────────────────────
  return new NextResponse(dxfString, {
    status: 200,
    headers: {
      'Content-Type': 'application/dxf',
      'Content-Disposition': `attachment; filename="${filename}"`,
    },
  })
})

/**
 * GET /api/compute/export/traverse-dxf
 *
 * Returns endpoint metadata.
 */
export const GET = apiHandler({ auth: false, rateLimit: { max: 20, windowMs: 60000 } }, async () => {
  return NextResponse.json({
    endpoint: '/api/compute/export/traverse-dxf',
    method: 'POST',
    description: 'Generate a traverse-specific DXF export for a project.',
    python_required: false,
    accepts: { projectId: 'string (required)' },
    produces: 'application/dxf (binary download)',
  })
})

export const dynamic = 'force-dynamic'

/**
 * Level Network Adjustment API
 *
 * POST /api/compute/level-network
 *
 * Accepts leveling observations and control points, runs weighted LSQ
 * adjustment, and returns adjusted RLs with residuals and misclosure check.
 */

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { z } from 'zod'
import { adjustLevelNetwork } from '@/lib/survey/digitalLevel/levelNetworkAdjustment'
import { generateBenchmarkSheet, validateBenchmarkSheet } from '@/lib/survey/digitalLevel/benchmarkSheet'
import { LevelObservation, LevelControlPoint } from '@/lib/survey/digitalLevel/digitalLevelTypes'

const LevelObservationSchema = z.object({
  fromId: z.string().min(1),
  toId: z.string().min(1),
  heightDifference: z.number(),
  distance: z.number().optional(),
  order: z.enum(['first', 'second', 'third']).optional(),
})

const LevelControlPointSchema = z.object({
  id: z.string().min(1),
  rl: z.number(),
  name: z.string().optional(),
  description: z.string().optional(),
})

const LevelNetworkRequestSchema = z.object({
  observations: z.array(LevelObservationSchema).min(1),
  controlPoints: z.array(LevelControlPointSchema).min(1),
  order: z.enum(['first', 'second', 'third']).optional(),
  metadata: z.object({
    projectName: z.string().optional(),
    surveyor: z.string().optional(),
    date: z.string().optional(),
    instrument: z.string().optional(),
    staff: z.string().optional(),
    remarks: z.string().optional(),
  }).optional(),
})

export const POST = apiHandler(
  { auth: true, schema: LevelNetworkRequestSchema, audit: 'compute_level_network' , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const data = ctx.body as z.infer<typeof LevelNetworkRequestSchema>

    // Run adjustment
    const result = adjustLevelNetwork(
      data.observations as LevelObservation[],
      data.controlPoints as LevelControlPoint[],
      data.order || 'third'
    )

    // Generate benchmark sheet
    const sheet = generateBenchmarkSheet(result, data.controlPoints as LevelControlPoint[], {
      projectName: data.metadata?.projectName,
      surveyor: data.metadata?.surveyor,
      date: data.metadata?.date,
      instrument: data.metadata?.instrument,
      staff: data.metadata?.staff,
      remarks: data.metadata?.remarks,
    })

    // Validate sheet
    const validation = validateBenchmarkSheet(sheet)

    return NextResponse.json({
      adjustment: result,
      benchmarkSheet: sheet,
      validation,
    })
  }
)

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { requireAuth } from '@/lib/auth/requireAuth'
import { computeRasterAnalysis, validateRasterRequest } from '@/lib/compute/rasterAnalysis'
import { callPythonCompute } from '@/lib/compute/pythonService'
import { apiSuccess, apiError } from '@/lib/api/response'

export async function POST(request: NextRequest) {
  const { session, error } = await requireAuth()
  if (error) return error

  const body = await request.json().catch(() => null)

  // Try native TS processing first
  const validated = validateRasterRequest(body)
  if (validated) {
    try {
      const result = await computeRasterAnalysis({
        project_id: (body as Record<string, unknown>)?.project_id as string ?? 'unknown',
        ...validated,
      })
      return NextResponse.json(apiSuccess({
        ...result,
        python_required: false,
      }))
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Raster analysis failed'
      return NextResponse.json(apiError(message), { status: 500 })
    }
  }

  // Fallback to Python service for complex raster ops
  const python = await callPythonCompute<unknown>('/raster/analyze', body, { timeoutMs: 30000 })
  if (!python.ok) {
    const err = python as { ok: false; status: number; error: string; fallback?: boolean; details?: unknown }
    return NextResponse.json(
      apiError(err.error, { fallback: err.fallback ?? true, details: err.details, python_required: true }),
      { status: err.status }
    )
  }
  return NextResponse.json(python.value)
}

export async function GET() {
  const { error } = await requireAuth()
  if (error) return error

  return NextResponse.json(apiSuccess({
    endpoint: '/api/compute/raster-analysis',
    description: 'Raster/DEM analysis (native TypeScript with Python fallback for advanced ops).',
    python_required: false,
    supported_types: ['hillshade', 'slope', 'aspect', 'contour', 'statistics'],
  }))
}

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler, ValidationError, NotFoundError } from '@/lib/api/handler'
import { z } from 'zod'
import { ComputeRequestSchema } from '@/lib/validation/apiSchemas'

const TINPointSchema = z.object({ id: z.string(), x: z.number(), y: z.number(), z: z.number() })
const TINPayloadSchema = z.object({
  points: z.array(TINPointSchema).min(3).max(50000),
  query_points: z.array(z.object({ x: z.number(), y: z.number() })).optional(),
})

const volumeCrossSchema = z.object({
  kind: z.literal('cross_section'),
  method: z.enum(['end_area', 'prismoidal', 'cut_fill']),
  sections: z.array(z.object({ chainage: z.number(), area: z.number() })).min(2),
})

const volumeSurfaceSchema = z.object({
  kind: z.literal('surface'),
  method: z.literal('grid_idw').default('grid_idw'),
  gridSpacing: z.number().positive(),
  power: z.number().positive().optional(),
  maxDistance: z.number().positive().optional(),
  existing: z.array(z.object({ easting: z.number(), northing: z.number(), elevation: z.number() })).min(3),
  design: z.array(z.object({ easting: z.number(), northing: z.number(), elevation: z.number() })).min(3),
})

export const POST = apiHandler({
  requireAuth: true,
  schema: ComputeRequestSchema,
  rateLimit: { max: 50, windowMs: 60000 },
  handler: async (ctx) => {
    const { task, payload } = ctx.input

    if (task === 'tin') {
      const parsed = TINPayloadSchema.safeParse(payload)
      if (!parsed.success) {
        throw new ValidationError('Invalid TIN payload', parsed.error.issues)
      }
      const { generateTIN, interpolateElevation } = await import('@/lib/compute/tin')
      const triangles = generateTIN(parsed.data.points as any[])
      let interpolations: any[] = []
      if (parsed.data.query_points) {
        interpolations = parsed.data.query_points.map(qp => ({
          x: qp.x, y: qp.y,
          elevation: interpolateElevation(triangles, qp.x, qp.y),
        }))
      }
      return NextResponse.json({
        triangle_count: triangles.length,
        point_count: parsed.data.points.length,
        triangles: triangles.slice(0, 1000),
        interpolations,
      })
    }

    if (task === 'volume') {
      const cross = volumeCrossSchema.safeParse(payload)
      if (cross.success) {
        const { cutFillVolumeFromSignedSections, volumeFromSections } = await import('@/lib/engine/volume')
        const { method, sections } = cross.data
        if (method === 'cut_fill') {
          const r = cutFillVolumeFromSignedSections(sections as any[])
          return NextResponse.json({
            task, kind: 'cross_section', method, cutVolume: r.cutVolume,
            fillVolume: r.fillVolume, netVolume: r.netVolume, segments: r.segments,
          })
        }
        const r = volumeFromSections(sections as any[], method === 'end_area' ? 'end_area' : 'prismoidal')
        return NextResponse.json({
          task, kind: 'cross_section', method: r.method,
          totalVolume: r.totalVolume, segments: r.segments,
        })
      }

      const surface = volumeSurfaceSchema.safeParse(payload)
      if (surface.success) {
        const { surfaceCutFillVolumeGrid } = await import('@/lib/engine/volume')
        const r = surfaceCutFillVolumeGrid({
          existing: surface.data.existing,
          design: surface.data.design,
          gridSpacing: surface.data.gridSpacing,
          power: surface.data.power,
          maxDistance: surface.data.maxDistance,
        } as any)
        return NextResponse.json({
          task, kind: 'surface', method: r.method,
          cutVolume: r.cutVolume, fillVolume: r.fillVolume, netVolume: r.netVolume,
          cellCount: r.cellCount, bbox: r.bbox, warnings: r.warnings,
        })
      }

      throw new ValidationError('Invalid volume payload. Supported: cross_section or surface.')
    }

    if (task === 'export_dxf') {
      const schema = z.object({
        projectName: z.string().min(1),
        includeElevations: z.boolean().optional(),
        points: z.array(z.object({
          name: z.string().min(1),
          easting: z.number(),
          northing: z.number(),
          elevation: z.number().optional(),
          is_control: z.boolean().optional(),
        })),
        traverseLegs: z.array(z.object({
          from: z.string().min(1),
          to: z.string().min(1),
          distance: z.number().optional().default(0),
          bearing: z.number().optional().default(0),
        })).optional(),
      })
      const parsed = schema.safeParse(payload)
      if (!parsed.success) {
        throw new ValidationError('Invalid export_dxf payload', parsed.error.issues)
      }
      const { generateDXF } = await import('@/lib/export/generateDXF')
      const dxf = generateDXF(parsed.data as any)
      return NextResponse.json({
        task, kind: 'dxf',
        filename: `${parsed.data.projectName.replace(/\s+/g, '_')}.dxf`,
        dxf, python_required: false,
      })
    }

    if (task === 'export_geojson') {
      const schema = z.object({
        projectName: z.string().min(1),
        utmZone: z.number().int().min(1).max(60).optional(),
        hemisphere: z.enum(['N', 'S']).optional(),
        points: z.array(z.object({
          id: z.string().optional(),
          name: z.string().min(1),
          easting: z.number(),
          northing: z.number(),
          elevation: z.number().nullable().optional(),
          is_control: z.boolean().optional(),
          control_order: z.string().optional(),
        })),
      })
      const parsed = schema.safeParse(payload)
      if (!parsed.success) {
        throw new ValidationError('Invalid export_geojson payload', parsed.error.issues)
      }
      const { generateGeoJSON } = await import('@/lib/export/generateGeoJSON')
      const geojson = generateGeoJSON(parsed.data.points as any[], parsed.data.projectName, parsed.data.utmZone, parsed.data.hemisphere)
      return NextResponse.json({
        task, kind: 'geojson',
        filename: `${parsed.data.projectName.replace(/\s+/g, '_')}.geojson`,
        geojson, python_required: false,
      })
    }

    if (task === 'raster_analysis' || task === 'contours') {
      return NextResponse.json(
        {
          error: `Task '${task}' is not yet implemented. It is on the roadmap and will be available in a future release.`,
          code: 'NOT_IMPLEMENTED',
        },
        { status: 501 }
      )
    }

    throw new NotFoundError('Unknown compute task')
  },
})

export const GET = apiHandler({
  requireAuth: true,
  handler: async () => {
    return NextResponse.json({
      endpoint: '/api/compute',
      description: 'Compute Gateway: routes heavy tasks to Python, keeps deterministic survey math in TS.',
      tasks: ['volume', 'tin', 'contours', 'raster_analysis', 'export_dxf', 'export_geojson'],
      native_tasks: ['volume', 'tin', 'export_dxf', 'export_geojson'],
    })
  },
})

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { z } from 'zod'
import { generateTIN, interpolateElevation, type TINPoint } from '@/lib/compute/tin'

const TINPointSchema = z.object({
  id: z.string(),
  x: z.number(),
  y: z.number(),
  z: z.number(),
})

const TINRequestSchema = z.object({
  project_id: z.string().uuid().optional(),
  points: z.array(TINPointSchema).min(3).max(50000),
  query_points: z.array(z.object({ x: z.number(), y: z.number() })).optional(),
})

export const POST = apiHandler(
  { auth: true, schema: TINRequestSchema, audit: 'compute_tin' , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const data = ctx.body as z.infer<typeof TINRequestSchema>

    const triangles = generateTIN(data.points as TINPoint[])

    let interpolations: Array<{ x: number; y: number; elevation: number | null }> = []
    if (data.query_points) {
      interpolations = data.query_points.map((qp): { x: number; y: number; elevation: number | null } => ({
        x: qp.x,
        y: qp.y,
        elevation: interpolateElevation(triangles, qp.x, qp.y),
      }))
    }

    return NextResponse.json(apiSuccess({
      triangle_count: triangles.length,
      point_count: data.points.length,
      triangles: triangles.slice(0, 1000), // Cap response size — client can paginate
      interpolations,
      python_required: false,
    }))
  }
)

