  return NextResponse.json({
    endpoint: '/api/compute/traverse',
    description: 'Run traverse computations: forward traverse and adjustment (Bowditch or Transit)',
    tasks: ['forward', 'adjust'],
    methods: ['bowditch', 'transit'],
  })
})

