export const POST = apiHandler({ auth: true, schema: ProcessGNSSSchema, rateLimit: { max: 60, windowMs: 60000 } }, async (request, ctx) => {
  const { projectId, files, stationLabels } = ctx.body as z.infer<typeof ProcessGNSSSchema>

  // Create session record
  const sessionRes = await db.query(
    `INSERT INTO gnss_sessions (
      project_id, user_id, status, input_files
    ) VALUES ($1, $2, $3, $4)
    RETURNING id`,
    [projectId, ctx.userId, 'processing', JSON.stringify(files)]
  )
  const gnssSessionId = sessionRes.rows[0].id

  // Call Python service for processing
  const result = await callPythonCompute<any>('/gnss/process', {
    files,
    stationLabels
  })

  let results: any[] = []
  let status: 'complete' | 'failed' | 'simulated' = 'complete'
  let errorMsg: string | undefined

  if (result.ok) {
    results = result.value?.baselines || []
  } else if ((result as { ok: false; fallback?: boolean }).fallback) {
    // Simulation mode - generate mock results
    status = 'simulated'
    results = generateMockBaselines(stationLabels ?? [])
    errorMsg = (result as { error: string }).error
  } else {
    status = 'failed'
    errorMsg = (result as { error: string }).error
  }

  // Update session with results
  await db.query(
    `UPDATE gnss_sessions SET
      status = $1,
      results = $2,
      error_msg = $3,
      updated_at = $4
    WHERE id = $5`,
    [
      results.length > 0 ? 'complete' : 'failed',
      JSON.stringify(results),
      errorMsg,
      new Date().toISOString(),
      gnssSessionId
    ]
  )

  return NextResponse.json({
    sessionId: gnssSessionId,
    results,
    status,
    message: status === 'simulated' ? 'Simulation mode — upload valid RINEX for real processing' : undefined
  })
})

function generateMockBaselines(stationLabels: string[]): any[] {
  // No fabricated baseline data — return empty result
  return []
}

export const dynamic = 'force-dynamic'

/**
 * Enhanced Health Check Endpoint
 *
 * Returns comprehensive application health status including:
 * - Database connectivity (ping query)
 * - Redis connectivity (if configured)
 * - Memory usage
 * - Uptime
 * - PM2 status (if available)
 * - Version from package.json
 *
 * 200 — { status: "ok", ...checks }
 * 503 — { status: "degraded", ...checks }
 */

import { NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { execSync } from 'child_process'
import { readFileSync } from 'fs'
import { join } from 'path'

interface HealthCheck {
  status: 'ok' | 'degraded'
  timestamp: string
  uptime: number
  version: string
  db: { status: string; latencyMs?: number; error?: string }
  redis: { status: string; latencyMs?: number; error?: string }
  memory: {
    rss: string
    heapTotal: string
    heapUsed: string
    external: string
    arrayBuffers: string
  }
  pm2?: {
    status: string
    instances?: number
    error?: string
  }
}

function formatBytes(bytes: number): string {
  return `${(bytes / 1024 / 1024).toFixed(2)} MB`
}

async function checkDb(): Promise<{ status: string; latencyMs?: number; error?: string }> {
  const start = Date.now()
  try {
    await db.query('SELECT 1 AS health_check')
    return { status: 'connected', latencyMs: Date.now() - start }
  } catch (error) {
    return { status: 'error', latencyMs: Date.now() - start, error: String(error) }
  }
}

async function checkRedis(): Promise<{ status: string; latencyMs?: number; error?: string }> {
  const redisUrl = process.env.REDIS_URL
  if (!redisUrl) {
    return { status: 'not_configured' }
  }

  const start = Date.now()
  try {
    // Dynamic import to avoid loading redis when not configured
    const { createClient } = await import('redis')
    const client = createClient({ url: redisUrl, socket: { reconnectStrategy: false } })
    await client.connect()
    const pong = await client.ping()
    await client.quit()
    return { status: pong === 'PONG' ? 'connected' : 'error', latencyMs: Date.now() - start }
  } catch (error) {
    return { status: 'error', latencyMs: Date.now() - start, error: String(error) }
  }
}

function checkPm2(): { status: string; instances?: number; error?: string } {
  try {
    const output = execSync('pm2 jlist 2>/dev/null', {
      timeout: 3000,
      encoding: 'utf-8',
    })
    const processes = JSON.parse(output)
    const metarduProcesses = processes.filter(
      (p: any) => p.name === 'metardu' || p.name === 'metardu-worker'
    )
    const onlineCount = metarduProcesses.filter(
      (p: any) => p.pm2_env?.status === 'online'
    ).length
    return {
      status: onlineCount === metarduProcesses.length ? 'healthy' : 'degraded',
      instances: metarduProcesses.length,
    }
  } catch {
    return { status: 'unavailable' }
  }
}

function getVersion(): string {
  try {
    const pkg = JSON.parse(readFileSync(join(process.cwd(), 'package.json'), 'utf-8'))
    return pkg.version || 'unknown'
  } catch {
    return 'unknown'
  }
}

function getMemoryUsage() {
  const mem = process.memoryUsage()
  return {
    rss: formatBytes(mem.rss),
    heapTotal: formatBytes(mem.heapTotal),
    heapUsed: formatBytes(mem.heapUsed),
    external: formatBytes(mem.external),
    arrayBuffers: formatBytes(mem.arrayBuffers),
  }
}

export async function GET() {
  const timestamp = new Date().toISOString()
  const uptime = process.uptime()

  const [dbHealth, redisHealth] = await Promise.all([checkDb(), checkRedis()])
  const pm2Health = checkPm2()

  const memory = getMemoryUsage()
  const version = getVersion()

  const isHealthy = dbHealth.status === 'connected'
  const status: HealthCheck['status'] = isHealthy ? 'ok' : 'degraded'

  const response: HealthCheck = {
    status,
    timestamp,
    uptime,
    version,
    db: dbHealth,
    redis: redisHealth,
    memory,
  }

  if (pm2Health.status !== 'unavailable') {
    response.pm2 = pm2Health
  }

  return NextResponse.json(response, {
    status: isHealthy ? 200 : 503,
    headers: {
      'Cache-Control': 'no-cache, no-store, must-revalidate',
      'Content-Type': 'application/json',
    },
  })
}

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
interface CommitEntry {
  station: string
  bearing?: number
  distance?: number
  deltaE?: number
  deltaN?: number
  description?: string
  from?: string
}

interface AdjustedLeg {
  from: string
  to: string
  length: number
  bearing: number
  correctedLat?: number
  correctedDep?: number
}

export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { projectId, entries, adjustedLegs, fileName, relativePrecision } = ctx.body as {
    projectId?: string
    entries?: CommitEntry[]
    adjustedLegs?: AdjustedLeg[]
    fileName?: string
    relativePrecision?: string
  }

  if (!projectId || !entries || entries.length === 0) {
    return NextResponse.json({ error: 'Missing projectId or entries' }, { status: 400 })
  }

  const projectRes = await db.query(
    'SELECT id FROM projects WHERE id = $1 AND user_id = $2',
    [projectId, ctx.userId]
  )
  if (projectRes.rows.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  const sessionRes = await db.query(
    `INSERT INTO import_sessions (
      project_id, file_name, format, row_count, status
    ) VALUES ($1, $2, $3, $4, $5)
    RETURNING id`,
    [projectId, fileName ?? 'unknown', 'csv', entries.length, 'committed']
  )
  const importSessionId = sessionRes.rows[0]?.id as string | undefined

  const existingRes = await db.query(
    'SELECT row_index FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index DESC LIMIT 1',
    [projectId]
  )
  const startIndex = ((existingRes.rows[0]?.row_index as number | undefined) ?? -1) + 1

  await db.transaction(async (client) => {
    for (let i = 0; i < entries.length; i++) {
      const entry = entries[i]
      const adjusted = adjustedLegs?.[i]
      const rowIndex = startIndex + i

      await client.query(
        `INSERT INTO project_fieldbook_entries (
          project_id, row_index, station, bearing, distance, raw_data, import_session_id, updated_at
        ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
        ON CONFLICT (project_id, row_index) DO UPDATE SET
          station = EXCLUDED.station,
          bearing = EXCLUDED.bearing,
          distance = EXCLUDED.distance,
          raw_data = EXCLUDED.raw_data,
          import_session_id = EXCLUDED.import_session_id,
          updated_at = EXCLUDED.updated_at`,
        [
          projectId,
          rowIndex,
          entry.station || entry.from || `P${i + 1}`,
          adjusted?.bearing ?? entry.bearing ?? 0,
          adjusted?.length ?? entry.distance ?? 0,
          JSON.stringify({
            ...entry,
            correctedLat: adjusted?.correctedLat,
            correctedDep: adjusted?.correctedDep,
            relativePrecision,
          }),
          importSessionId,
          new Date().toISOString(),
        ]
      )
    }

    await client.query(
      'UPDATE projects SET last_fieldbook_update = $1 WHERE id = $2',
      [new Date().toISOString(), projectId]
    )
  })

  return NextResponse.json({
    success: true,
    imported: entries.length,
    message: `Committed ${entries.length} entries. Precision: ${relativePrecision ?? 'N/A'}`,
  })
})

