    shortCode: 'NDRB',
    county: 'Nyeri',
    latitude: -0.4197,
    longitude: 36.9553,
    elevation: 1759.0,
    status: 'OFFLINE',
    lastHeartbeat: new Date(Date.now() - 86400000).toISOString(),
    mountPoints: [
      { name: 'NDRB0', format: 'RTCM3', navSystem: 'GPS+GLO+GAL', network: 'KENYANET' }
    ]
  }
]

export async function GET(request: NextRequest) {
  try {
    // Parse and validate query parameters
    const { searchParams } = new URL(request.url)
    const queryParams: Record<string, unknown> = {}

    const bboxParam = searchParams.get('bbox')
    if (bboxParam) {
      try {
        queryParams.bbox = JSON.parse(bboxParam)
      } catch {
        return NextResponse.json({ error: 'Invalid bbox parameter — must be JSON array of 4 numbers' }, { status: 400 })
      }
    }
    const statusParam = searchParams.get('status')
    if (statusParam) queryParams.status = statusParam
    const countyParam = searchParams.get('county')
    if (countyParam) queryParams.county = countyParam

    const parsed = KenCORSQuerySchema.safeParse(queryParams)
    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid query parameters', details: parsed.error.issues }, { status: 400 })
    }

    const { bbox, status, county } = parsed.data

    const apiKey = process.env.KENCORS_API_KEY

    let stations: KenCORSStation[] = DEFAULT_STATIONS

    if (apiKey) {
      try {
        const response = await fetch('https://kencors.go.ke/api/v1/stations', {
          headers: {
            'Authorization': `Bearer ${apiKey}`
          }
        })

        if (response.ok) {
          const data: unknown = await response.json()
          if (Array.isArray(data)) {
            stations = data as KenCORSStation[]
          }
        }
      } catch (apiError) {
        console.error('KenCORS API error:', apiError)
      }
    }

    // Apply filters
    if (bbox) {
      const [minLon, minLat, maxLon, maxLat] = bbox
      stations = stations.filter(s =>
        s.longitude >= minLon && s.longitude <= maxLon &&
        s.latitude >= minLat && s.latitude <= maxLat
      )
    }

    if (status) {
      stations = stations.filter(s => s.status === status)
    }

    if (county) {
      stations = stations.filter(s => s.county.toLowerCase() === county.toLowerCase())
    }

    return NextResponse.json({ stations })

  } catch (error) {
    console.error('KenCORS stations error:', error)
    return NextResponse.json(
      { error: 'Failed to fetch KenCORS stations', stations: DEFAULT_STATIONS },
      { status: 200 }
    )
  }
}

/**
 * /api/marketplace/inquiries
 *
 * GET  — Get inquiries for a listing (owner only)
 * POST — Send an inquiry to a listing (any authenticated user)
 */

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { apiSuccess, apiError } from '@/lib/api/response'
import { db } from '@/lib/db'
export const dynamic = 'force-dynamic'

// ── GET ────────────────────────────────────────────────────────────────────

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { searchParams } = new URL(req.url)
  const listingId = searchParams.get('listingId')

  if (!listingId) {
    return NextResponse.json(apiError('listingId query parameter is required'), { status: 400 })
  }

  // Verify the requesting user owns the listing
  const { rows: listingRows } = await db.query(
    'SELECT user_id FROM instrument_listings WHERE id = $1',
    [listingId]
  )
  if (listingRows.length === 0) {
    return NextResponse.json(apiError('Listing not found'), { status: 404 })
  }
  if (listingRows[0].user_id !== ctx.userId) {
    return NextResponse.json(apiError('Only the listing owner can view inquiries'), { status: 403 })
  }

  const { rows } = await db.query(
    'SELECT * FROM instrument_inquiries WHERE listing_id = $1 ORDER BY created_at DESC',
    [listingId]
  )

  const inquiries = rows.map((row: Record<string, unknown>) => ({
    id: row.id,
    listingId: row.listing_id,
    buyerName: row.buyer_name,
    buyerContact: row.buyer_contact,
    message: row.message,
    sentAt: row.created_at,
  }))

  return NextResponse.json(apiSuccess(inquiries))
})

// ── POST ───────────────────────────────────────────────────────────────────

export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const body = ctx.body as Record<string, unknown>

  const listingId = String(body.listingId ?? '')
  const buyerName = String(body.buyerName ?? '').trim()
  const buyerContact = String(body.buyerContact ?? '').trim()
  const message = String(body.message ?? '').trim()

  if (!listingId) return NextResponse.json(apiError('Listing ID is required'), { status: 400 })
  if (!buyerName) return NextResponse.json(apiError('Your name is required'), { status: 400 })
  if (!buyerContact) return NextResponse.json(apiError('Your contact is required'), { status: 400 })
  if (!message) return NextResponse.json(apiError('Message is required'), { status: 400 })

  // Verify listing exists
  const { rows: listingRows } = await db.query(
    'SELECT id FROM instrument_listings WHERE id = $1 AND NOT sold',
    [listingId]
  )
  if (listingRows.length === 0) {
    return NextResponse.json(apiError('Listing not found or already sold'), { status: 404 })
  }

  const { rows } = await db.query(
    `INSERT INTO instrument_inquiries (listing_id, buyer_name, buyer_contact, message)
     VALUES ($1, $2, $3, $4)
     RETURNING *`,
    [listingId, buyerName, buyerContact, message]
  )

  const row = rows[0] as Record<string, unknown>
  return NextResponse.json(apiSuccess({
    id: row.id,
    listingId: row.listing_id,
    buyerName: row.buyer_name,
    buyerContact: row.buyer_contact,
    message: row.message,
    sentAt: row.created_at,
  }), { status: 201 })
})

