/**
 * License Application Portfolio Generator
 *
 * Generates a portfolio package for Kenya Land Surveyors' Board license
 * application. Based on the official "Requirements for Land Survey License
 * Application" (effective March 2025) from the uploaded PDF.
 *
 * Requirements from the PDF:
 *   1. SCHEME CADASTRAL SURVEY — min 10 plots in 1-3 schemes
 *   2. TOPOGRAPHICAL SURVEY — 2-10 ha depending on density
 *   3. CONTROL SURVEY — GNSS (3 pts in 20km²) or theodolite (4+ pts)
 *   4. ELECTIVE (one of):
 *      a. Sectional Property — 30+ units
 *      b. Perimeter/Farm Survey — 4-5 ha, georeferenced
 *      c. Earth Observation & Remote Sensing — 20 ha
 *      d. Setting Out — 1km linear or 0.1 ha buildings
 *
 * The generator checks the user's projects against these requirements,
 * identifies gaps, and generates the declaration forms (Form A, Form B).
 */

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface PortfolioRequirement {
  id: string
  category: string
  description: string
  minimumRequired: string
  userHas: string
  met: boolean
  projects: Array<{
    id: string
    name: string
    survey_type: string
    created_at: string
    details: string
  }>
}

export interface PortfolioReport {
  requirements: PortfolioRequirement[]
  electives: PortfolioRequirement[]
  allMandatoryMet: boolean
  atLeastOneElectiveMet: boolean
  summary: string
  missingItems: string[]
  declarationFormA: string
  declarationFormB: string
  timestamp: string
}

// ─── API ────────────────────────────────────────────────────────────────────

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 10, windowMs: 60000 } },
  async (_req, ctx) => {
    const userId = ctx.userId!

    // Fetch the user's projects grouped by survey type
    const { rows: projects } = await db.query(
      `SELECT id, name, survey_type, location, area_ha, created_at,
              (SELECT COUNT(*) FROM survey_points WHERE project_id = projects.id AND is_control = true) as control_point_count,
              (SELECT COUNT(*) FROM deed_plans WHERE project_id = projects.id) as deed_plan_count,
              (SELECT COUNT(*) FROM parcels WHERE project_id = projects.id) as parcel_count
       FROM projects
       WHERE user_id = $1
       ORDER BY created_at DESC`,
      [userId],
    )

    // Get user profile for declaration forms
    const { rows: profile } = await db.query(
      `SELECT u.email, u.full_name, sp.firm_name, sp.license_number
       FROM users u
       LEFT JOIN surveyor_profiles sp ON sp.user_id = u.id
       WHERE u.id = $1`,
      [userId],
    )

    const user = profile[0] || { email: '', full_name: 'Unknown', firm_name: '', license_number: '' }

    // ─── Check each requirement ───

    // 1. Scheme Cadastral: min 10 plots in 1-3 schemes
    const cadastralProjects = projects.filter((p: any) =>
      p.survey_type === 'cadastral' || p.survey_type === 'Cadastral'
    )
    const totalParcels = cadastralProjects.reduce((sum: number, p: any) => sum + parseInt(p.parcel_count || '0', 10), 0)
    const cadastralReq: PortfolioRequirement = {
      id: 'cadastral',
      category: 'Scheme Cadastral Survey',
      description: 'A minimum of 10 plots either in one scheme or at most in 3 schemes based on newly established control(s).',
      minimumRequired: '≥ 10 plots in 1-3 schemes',
      userHas: `${totalParcels} plots in ${cadastralProjects.length} scheme(s)`,
      met: totalParcels >= 10 && cadastralProjects.length <= 3 && cadastralProjects.length >= 1,
      projects: cadastralProjects.map((p: any) => ({
        id: p.id, name: p.name, survey_type: p.survey_type,
        created_at: p.created_at,
        details: `${p.parcel_count || 0} plots`,
      })),
    }

    // 2. Topographical: 2-10 ha depending on density
    const topoProjects = projects.filter((p: any) =>
      p.survey_type === 'topographic' || p.survey_type === 'Topographic'
    )
    const totalTopoArea = topoProjects.reduce((sum: number, p: any) => sum + (p.area_ha || 0), 0)
    const topoReq: PortfolioRequirement = {
      id: 'topographic',
      category: 'Topographical Survey',
      description: 'a) 2 ha (high density, 60%+ coverage), b) 4 ha (medium, 40-60%), or c) 10 ha (low density, 20%+).',
      minimumRequired: '≥ 2 ha (high density) / 4 ha (medium) / 10 ha (low)',
      userHas: `${totalTopoArea.toFixed(2)} ha in ${topoProjects.length} survey(s)`,
      met: totalTopoArea >= 2 && topoProjects.length >= 1,
      projects: topoProjects.map((p: any) => ({
        id: p.id, name: p.name, survey_type: p.survey_type,
        created_at: p.created_at,
        details: `${(p.area_ha || 0).toFixed(2)} ha`,
      })),
    }

    // 3. Control Survey: GNSS (3 pts in 20km²) or theodolite (4+ pts)
    const controlProjects = projects.filter((p: any) =>
      p.survey_type === 'control' || p.survey_type === 'Control' ||
      parseInt(p.control_point_count || '0', 10) >= 3
    )
    const totalControlPoints = controlProjects.reduce((sum: number, p: any) => sum + parseInt(p.control_point_count || '0', 10), 0)
    const controlReq: PortfolioRequirement = {
      id: 'control',
      category: 'Control Survey',
      description: 'a) GNSS: at least 3 points within ~20km² by static mode, OR b) Theodolite/TS: at least 4 points established.',
      minimumRequired: '≥ 3 GNSS points (20km²) OR ≥ 4 theodolite points',
      userHas: `${totalControlPoints} control points in ${controlProjects.length} survey(s)`,
      met: totalControlPoints >= 3 && controlProjects.length >= 1,
      projects: controlProjects.map((p: any) => ({
        id: p.id, name: p.name, survey_type: p.survey_type,
        created_at: p.created_at,
        details: `${p.control_point_count || 0} control points`,
      })),
    }

    // 4. Electives (select one)
    const sectionalProjects = projects.filter((p: any) => p.survey_type === 'sectional')
    const perimeterProjects = projects.filter((p: any) => p.survey_type === 'perimeter' || (p.area_ha >= 4 && p.survey_type === 'cadastral'))
    const settingOutProjects = projects.filter((p: any) => p.survey_type === 'engineering' || p.survey_type === 'construction')

    const electives: PortfolioRequirement[] = [
      {
        id: 'sectional',
        category: 'Sectional Property Survey',
        description: 'A project consisting of at least 30 units.',
        minimumRequired: '≥ 30 units',
        userHas: `${sectionalProjects.length} project(s)`,
        met: false, // Would need unit count from sectional_properties table
        projects: [],
      },
      {
        id: 'perimeter',
        category: 'Perimeter (Farm) Survey',
        description: 'New perimeter survey beacons of a new parcel. Minimum 4 ha (production) or 5 ha (supervised). Must be georeferenced.',
        minimumRequired: '≥ 4 ha, georeferenced',
        userHas: `${perimeterProjects.length} project(s), ${(perimeterProjects.reduce((s: number, p: any) => s + (p.area_ha || 0), 0)).toFixed(2)} ha`,
        met: perimeterProjects.length >= 1 && perimeterProjects.reduce((s: number, p: any) => s + (p.area_ha || 0), 0) >= 4,
        projects: perimeterProjects.map((p: any) => ({
          id: p.id, name: p.name, survey_type: p.survey_type, created_at: p.created_at,
          details: `${(p.area_ha || 0).toFixed(2)} ha`,
        })),
      },
      {
        id: 'setting_out',
        category: 'Setting Out Works',
        description: 'Setting out of not less than 1km (linear) or 0.1 ha (buildings).',
        minimumRequired: '≥ 1km linear OR ≥ 0.1 ha buildings',
        userHas: `${settingOutProjects.length} project(s)`,
        met: settingOutProjects.length >= 1,
        projects: settingOutProjects.map((p: any) => ({
          id: p.id, name: p.name, survey_type: p.survey_type, created_at: p.created_at,
          details: p.location || '',
        })),
      },
    ]

    // ─── Summary ───
    const mandatoryReqs = [cadastralReq, topoReq, controlReq]
    const allMandatoryMet = mandatoryReqs.every(r => r.met)
    const atLeastOneElectiveMet = electives.some(e => e.met)

    const missingItems: string[] = []
    if (!cadastralReq.met) missingItems.push(`Cadastral: need ≥10 plots in 1-3 schemes (have ${totalParcels})`)
    if (!topoReq.met) missingItems.push(`Topographic: need ≥2 ha (have ${totalTopoArea.toFixed(2)} ha)`)
    if (!controlReq.met) missingItems.push(`Control: need ≥3 GNSS or ≥4 theodolite points (have ${totalControlPoints})`)
    if (!atLeastOneElectiveMet) missingItems.push('Elective: need at least one of: Sectional (30 units), Perimeter (4 ha), Setting Out (1km/0.1 ha)')

    let summary: string
    if (allMandatoryMet && atLeastOneElectiveMet) {
      summary = 'Portfolio meets ALL requirements for Land Survey License application. Ready to generate declaration forms.'
    } else {
      summary = `Portfolio is INCOMPLETE. ${missingItems.length} requirement(s) not met: ${missingItems.join('; ')}.`
    }

    // ─── Declaration Forms ───
    const declarationFormA = generateFormA(user, projects)
    const declarationFormB = generateFormB(user)

    const report: PortfolioReport = {
      requirements: mandatoryReqs,
      electives,
      allMandatoryMet,
      atLeastOneElectiveMet,
      summary,
      missingItems,
      declarationFormA,
      declarationFormB,
      timestamp: new Date().toISOString(),
    }

    return NextResponse.json({ data: report })
  },
)

// ─── Form Generators ────────────────────────────────────────────────────────

/**
 * Generate Form A (Declaration of employment/supervision) per Third Schedule.
 */
function generateFormA(user: any, projects: any[]): string {
  const surveyorName = user.full_name || '___________________________'
  const firmName = user.firm_name || '___________________________'
  const licenseNumber = user.license_number || '___________________________'

  return `FORM A (rr. 13, 14)
THIRD SCHEDULE — DECLARATION

I, ${surveyorName}, solemnly and sincerely declare that the candidate
___________________________ has served regularly and faithfully with
${firmName} as a student surveyor/surveyor for a period of
____ years and ____ months from ____________ to ____________.

The nature of this employment during the period specified is as follows:

SUMMARY OF EMPLOYMENT:
${projects.slice(0, 10).map((p, i) => `${i + 1}. ${p.name} (${p.survey_type}) — ${p.location || 'Kenya'}`).join('\n')}

Declared at ___________________________ this ______ day of ________________, 20____

Signature: ___________________________
Name: ${surveyorName}
License No: ${licenseNumber}

NOTE: This form must be signed by the Principal/Licensed Surveyor who supervised
the candidate's work. The Director of Surveys may verify any of the declared work.`
}

/**
 * Generate Form B (Declaration of qualifications) per Third Schedule.
 */
function generateFormB(user: any): string {
  const surveyorName = user.full_name || '___________________________'

  return `FORM B (r. 14)
THIRD SCHEDULE — DECLARATION

I, ${surveyorName}, of ___________________________ solemnly and sincerely
declare that I am a graduate of the University of ___________________________
and I have taken a degree in ___________________________ and that I have pursued
the courses of study and have had practical experience in land surveying as set
out in the summary below.

SUMMARY:
Course(s) of study at ___________________________ from ___________________________
to ___________________________

Period of practical experience at ___________________________
From ___________________________ to ___________________________

Declared at ___________________________
this ______ day of ________________, 20____

Signature: ___________________________
Name: ${surveyorName}`
}

/**
 * /api/professional-memberships/[id]/verify
 *
 * POST — Admin-only: verify or reject a professional membership.
 *
 * Body:
 *   { status: 'VERIFIED' | 'FAILED', notes?: string, rejectionReason?: string }
 *
 * AUDIT FIX (H10, 2026-07-03): Admin review endpoint for the
 * documentary-proof workflow. Only admins can verify/reject.
 */

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { apiHandler } from '@/lib/apiHandler'
import db from '@/lib/db'

const VerifySchema = z.object({
  status: z.enum(['VERIFIED', 'FAILED']),
  notes: z.string().max(1000).optional(),
  rejectionReason: z.string().max(1000).optional(),
})

export const POST = apiHandler(
  { auth: true, roles: ['super_admin', 'admin'], schema: VerifySchema, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const { id } = ctx.params
    const input = ctx.body as z.infer<typeof VerifySchema>

    if (input.status === 'FAILED' && !input.rejectionReason?.trim()) {
      return NextResponse.json(
        { error: 'rejectionReason is required when status is FAILED', code: 'MISSING_REASON' },
        { status: 400 },
      )
    }

    const { rows } = await db.query(
      `UPDATE professional_memberships
          SET verification_status = $1,
              verification_notes = $2,
              rejection_reason = $3,
              verified_by = $4,
              verified_at = NOW(),
              updated_at = NOW()
        WHERE id = $5
       RETURNING *`,
      [
        input.status,
        input.notes || null,
        input.rejectionReason || null,
        ctx.userId,
        id,
      ],
    )

    if (rows.length === 0) {
      return NextResponse.json(
        { error: 'Membership not found', code: 'NOT_FOUND' },
        { status: 404 },
      )
    }

    // If verified, update the user's surveyor_profiles.verified_isk
    // for backward compat (old code reads that column)
    if (input.status === 'VERIFIED' && rows[0].body === 'ISK') {
      await db.query(
        `UPDATE surveyor_profiles SET verified_isk = true WHERE user_id = $1`,
        [rows[0].user_id],
      ).catch(() => {})  // non-critical
    }

    return NextResponse.json({ data: rows[0] })
  },
)

/**
 * /api/professional-memberships
 *
 * GET  — List the authenticated user's professional memberships
 * POST — Submit a new membership for verification (documentary proof)
 *
 * AUDIT FIX (H10, 2026-07-03): Replaces the self-attested
 * `surveyor_profiles.verified_isk` boolean with a proper documentary-
 * proof workflow: surveyor uploads their practising certificate,
 * an admin reviews it, and only VERIFIED memberships unlock
 * statutory document generation.
 */

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { apiHandler } from '@/lib/apiHandler'
import db from '@/lib/db'
import { validateMembershipNumber, PROFESSIONAL_BODY_NAMES } from '@/types/professionalBody'

const SubmitMembershipSchema = z.object({
  body: z.enum(['ISK', 'EBK', 'ISU', 'RICS', 'FIG', 'OTHER']),
  membershipNumber: z.string().min(1).max(100),
  membershipGrade: z.string().max(50).optional(),
  expiresAt: z.string().optional(),  // ISO date
  supportingDocPath: z.string().max(500).optional(),
  supportingDocHash: z.string().max(64).optional(),
})

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (_req, ctx) => {
    const { rows } = await db.query(
      `SELECT id, body, membership_number, membership_grade,
              verification_status, verification_method, verified_at,
              verification_notes, rejection_reason, expires_at,
              supporting_doc_path, created_at, updated_at
         FROM professional_memberships
        WHERE user_id = $1
        ORDER BY created_at DESC`,
      [ctx.userId],
    )
    return NextResponse.json({ data: rows })
  },
)

export const POST = apiHandler(
  {
    auth: true,
    schema: SubmitMembershipSchema,
    rateLimit: { max: 10, windowMs: 60000 },
    // P0-3 (2026-07-24): Wire membership submissions into the tamper-evident
    // audit chain. ISK/EBK membership claims are a fraud vector — a surveyor
    // could submit a fake membership number, get verified, then generate
    // statutory documents. The chain entry proves who submitted what and
    // when, and is tamper-detectable if anyone later alters the record.
    auditChain: {
      entityType: 'system',
      action: 'submit',
      reason: 'professional membership submission (pending admin verification)',
    },
  },
  async (_req, ctx) => {
    const input = ctx.body as z.infer<typeof SubmitMembershipSchema>

    // Validate the membership number format
    const validation = validateMembershipNumber(input.body, input.membershipNumber)
    if (!validation.valid) {
      return NextResponse.json(
        { error: validation.warning || 'Invalid membership number', code: 'INVALID_FORMAT' },
        { status: 400 },
      )
    }

    // Check for duplicate (same body + number for this user)
    const existing = await db.query(
      `SELECT id FROM professional_memberships
        WHERE user_id = $1 AND body = $2 AND membership_number = $3`,
      [ctx.userId, input.body, input.membershipNumber],
    )
    if (existing.rows.length > 0) {
      return NextResponse.json(
        { error: 'You have already submitted this membership number', code: 'DUPLICATE' },
        { status: 409 },
      )
    }

    // Insert — status starts as PENDING
    const { rows } = await db.query(
      `INSERT INTO professional_memberships
         (user_id, body, membership_number, membership_grade,
          verification_status, verification_method, expires_at,
          supporting_doc_path, supporting_doc_hash)
       VALUES ($1, $2, $3, $4, 'PENDING', 'DOCUMENT', $5, $6, $7)
       RETURNING *`,
      [
        ctx.userId,
        input.body,
        input.membershipNumber,
        input.membershipGrade || null,
        input.expiresAt || null,
        input.supportingDocPath || null,
        input.supportingDocHash || null,
      ],
    )

    return NextResponse.json(
      {
        data: rows[0],
        warning: validation.warning,
        message: `Membership submitted for review. An administrator will verify your ${PROFESSIONAL_BODY_NAMES[input.body]} certificate. You'll be notified when verification is complete.`,
      },
      { status: 201 },
    )
  },
)

/**
 * /api/profile/settings — Profile + Company + Notification Preferences
 *
 * GET    /api/profile/settings       → Load all settings
 * PATCH  /api/profile/settings       → Update profile fields, firm info, or notification preferences
 *
 * Body shape (any subset of fields):
 *   {
 *     full_name?: string,
 *     firm_name?: string,
 *     isk_number?: string,
 *     license_number?: string,
 *     phone?: string,
 *     address?: string,
 *     bio?: string,
 *     avatar_url?: string,
 *     notification_preferences?: { email?, sms?, push?, in_app? }
 *   }
 *
 * Updates both `profiles` and `surveyor_profiles` so firm info
 * appears on Deed Plans, Form No.4 certificates, and the surveyor registry.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { setCurrentUserId, db } from '@/lib/db'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const NotificationChannelsSchema = z.object({
  project_updates: z.boolean().optional(),
  field_sync_complete: z.boolean().optional(),
  document_generated: z.boolean().optional(),
  billing_reminders: z.boolean().optional(),
  security_alerts: z.boolean().optional(),
  marketing: z.boolean().optional(),
  weekly_digest: z.boolean().optional(),
  team_mentions: z.boolean().optional(),
}).passthrough().optional()

const NotificationPreferencesSchema = z.object({
  email: NotificationChannelsSchema,
  sms: NotificationChannelsSchema,
  push: NotificationChannelsSchema,
  in_app: NotificationChannelsSchema,
}).passthrough().optional()

const UpdateProfileSettingsSchema = z.object({
  full_name: z.string().min(2).max(255).trim().optional(),
  firm_name: z.string().max(255).trim().optional(),
  isk_number: z.string().max(50).trim().optional(),
  license_number: z.string().max(100).trim().optional(),
  phone: z.string().max(50).trim().optional(),
  address: z.string().max(1000).trim().optional(),
  bio: z.string().max(2000).trim().optional(),
  avatar_url: z.string().max(500).trim().optional(),
  notification_preferences: NotificationPreferencesSchema,
}).strict()

async function requireSession() {
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) return null
  const userId = String(session.user.id)
  setCurrentUserId(userId)
  return { userId, session }
}

export async function GET() {
  const auth = await requireSession()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { userId } = auth

  const { rows } = await db.query(
    `SELECT
       p.id, p.full_name, p.firm_name, p.isk_number, p.phone,
       p.address, p.bio, p.avatar_url,
       p.notification_preferences,
       p.notification_preferences_updated_at,
       sp.license_number,
       sp.verified_isk,
       sp.is_suspended,
       u.email, u.role, u.created_at
     FROM profiles p
     LEFT JOIN surveyor_profiles sp ON sp.user_id = p.id
     LEFT JOIN users u ON u.id = p.id
     WHERE p.id = $1`,
    [userId],
  )

  if (rows.length === 0) {
    return NextResponse.json({ error: 'Profile not found' }, { status: 404 })
  }

  return NextResponse.json({ data: rows[0] })
}

export async function PATCH(request: NextRequest) {
  const auth = await requireSession()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { userId } = auth

  let rawBody: unknown
  try {
    rawBody = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const parsed = UpdateProfileSettingsSchema.safeParse(rawBody)
  if (!parsed.success) {
    return NextResponse.json(
      { error: 'Validation failed', details: parsed.error.issues },
      { status: 422 },
    )
  }

  const updates = parsed.data

  // Build SET clauses for profiles table
  const profileFields: string[] = []
  const profileValues: unknown[] = []
  let paramIdx = 1

  const profileFieldMap: Record<string, unknown> = {
    full_name: updates.full_name,
    firm_name: updates.firm_name,
    isk_number: updates.isk_number,
    phone: updates.phone,
    address: updates.address,
    bio: updates.bio,
    avatar_url: updates.avatar_url,
  }

  for (const [field, value] of Object.entries(profileFieldMap)) {
    if (value !== undefined) {
      profileFields.push(`${field} = $${paramIdx++}`)
      profileValues.push(value)
    }
  }

  // Merge notification preferences using JSONB deep merge
  if (updates.notification_preferences) {
    profileFields.push(`notification_preferences = COALESCE(notification_preferences, '{}'::jsonb) || $${paramIdx++}::jsonb`)
    profileValues.push(JSON.stringify(updates.notification_preferences))
    profileFields.push(`notification_preferences_updated_at = NOW()`)
  }

  if (profileFields.length === 0) {
    return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
  }

  profileValues.push(userId)

  await db.query(
    `UPDATE profiles SET ${profileFields.join(', ')} WHERE id = $${paramIdx}`,
    profileValues,
  )

  // Also sync firm_name, isk_number, phone, license_number to surveyor_profiles
  const surveyorFields: string[] = []
  const surveyorValues: unknown[] = []
  let sIdx = 1

  if (updates.firm_name !== undefined) {
    surveyorFields.push(`firm_name = $${sIdx++}`)
    surveyorValues.push(updates.firm_name)
  }
  if (updates.isk_number !== undefined) {
    surveyorFields.push(`isk_number = $${sIdx++}`)
    surveyorValues.push(updates.isk_number)
  }
  if (updates.phone !== undefined) {
    surveyorFields.push(`phone = $${sIdx++}`)
    surveyorValues.push(updates.phone)
  }
  if (updates.license_number !== undefined) {
    surveyorFields.push(`license_number = $${sIdx++}`)
    surveyorValues.push(updates.license_number)
  }

  if (surveyorFields.length > 0) {
    surveyorValues.push(userId)
    await db.query(
      `UPDATE surveyor_profiles SET ${surveyorFields.join(', ')}, updated_at = NOW() WHERE user_id = $${sIdx}`,
      surveyorValues,
    ).catch(() => {
      // Surveyor profile may not exist yet — create on the fly
    })
  }

  // Re-fetch the updated profile
  const { rows } = await db.query(
    `SELECT
       p.full_name, p.firm_name, p.isk_number, p.phone,
       p.address, p.bio, p.avatar_url,
       p.notification_preferences,
       p.notification_preferences_updated_at,
       sp.license_number,
       u.email
     FROM profiles p
     LEFT JOIN surveyor_profiles sp ON sp.user_id = p.id
     LEFT JOIN users u ON u.id = p.id
     WHERE p.id = $1`,
    [userId],
  )

  return NextResponse.json({ data: rows[0] })
}

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'

/**
 * GET /api/project/[id]/cross-sections
 *
 * Fetch cross-section data for a project. Returns survey points grouped
 * by chainage station (parsed from point_name), suitable for direct
 * consumption by the earthworks calculator.
 *
 * Query params:
 *   ?interval=20     — group points into chainage bins of this width (m).
 *                      Default: 0 (no binning; return raw chainage values).
 *
 * Returns: { data: CrossSection[] }
 *   where CrossSection = {
 *     chainage: number,           // metres
 *     centerline_rl: number,      // metres (elevation of centreline point)
 *     points: Array<{
 *       point_name: string,
 *       easting: number,
 *       northing: number,
 *       elevation: number,
 *       offset: number,           // metres, +right of centreline
 *       code: string | null,
 *       description: string | null
 *     }>
 *   }
 *
 * Chainage parsing:
 *   The function attempts to parse a chainage value from each point's
 *   `point_name` using common survey formats:
 *     - "0+020"      → 20 m
 *     - "1+200.5"    → 1200.5 m
 *     - "STA 20"     → 20 m
 *     - "CH 1200"    → 1200 m
 *     - "20"         → 20 m
 *
 *   Points whose names cannot be parsed are returned in a separate
 *   "unmatched" array in the response, so the client can decide how
 *   to handle them.
 *
 * Note: full cross-section auto-population (with computed left/right
 * offsets) requires the baseline alignment geometry, which is a future
 * feature. For now, offset is 0 for all matched points; the surveyor
 * must enter offset shots manually or via CSV upload in the tool UI.
 */

interface SurveyPoint {
  id: string
  point_name: string
  easting: number
  northing: number
  elevation: number | null
  code: string | null
  description: string | null
  // CRS fields (migration 027) — nullable for backward compat
  datum?: string | null
  utm_zone?: number | null
  hemisphere?: string | null
  source?: string | null
  is_control?: boolean
}

/**
 * Attempt to extract a chainage value (in metres) from a point name.
 * Handles formats: "0+020", "0+020.5", "20", "STA 20", "CH 1200"
 */
function parseChainageFromName(name: string): number | null {
  if (!name) return null
  const upper = name.toUpperCase().trim()

  // Format: "0+020" or "1+200.5" (km+m)
  const kmMatch = upper.match(/(\d+)\+(\d+(?:\.\d+)?)/)
  if (kmMatch) {
    return parseInt(kmMatch[1]) * 1000 + parseFloat(kmMatch[2])
  }

  // Format: "STA 20" or "CH 1200" or just "20"
  const staMatch = upper.match(/(?:STA|CH|CHAINAGE)?\s*(\d+(?:\.\d+)?)/)
  if (staMatch) {
    return parseFloat(staMatch[1])
  }

  return null
}

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const { id } = ctx.params
    const url = new URL(req.url)
    const interval = parseFloat(url.searchParams.get('interval') || '0')

    // AUDIT FIX (C5, 2026-07-02): Include CRS columns so consumers know
    // the datum/zone of the returned coordinates.
    const { rows } = await db.query(
      `SELECT id, point_name, easting, northing, elevation, code, description,
              datum, utm_zone, hemisphere, source, is_control
       FROM survey_points
       WHERE project_id = $1
         AND easting IS NOT NULL
         AND northing IS NOT NULL
         AND elevation IS NOT NULL
       ORDER BY point_name ASC`,
      [id]
    )

    const points = rows as SurveyPoint[]

    // Group points by chainage
    const chainageMap = new Map<number, SurveyPoint[]>()
    const unmatched: SurveyPoint[] = []

    for (const p of points) {
      const ch = parseChainageFromName(p.point_name)
      if (ch === null) {
        unmatched.push(p)
        continue
      }
      // Apply binning if requested
      const binKey = interval > 0 ? Math.round(ch / interval) * interval : ch
      if (!chainageMap.has(binKey)) chainageMap.set(binKey, [])
      chainageMap.get(binKey)!.push(p)
    }

    // Build cross-section array sorted by chainage
    const crossSections = Array.from(chainageMap.entries())
      .sort(([a], [b]) => a - b)
      .map(([chainage, pts]) => ({
        chainage,
        centerline_rl: pts[0].elevation as number,
        points: pts.map(p => ({
          point_name: p.point_name,
          easting: p.easting,
          northing: p.northing,
          elevation: p.elevation as number,
          offset: 0, // requires alignment geometry to compute
          code: p.code,
          description: p.description,
        })),
      }))

    return NextResponse.json({
      data: crossSections,
      meta: {
        project_id: id,
        total_points: points.length,
        matched_points: points.length - unmatched.length,
        unmatched_points: unmatched.length,
        chainage_count: crossSections.length,
        interval,
      },
      unmatched,
    })
  }
)

