export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server';
import { apiHandler } from '@/lib/apiHandler';
import { db } from '@/lib/db';
import { generateIFC4 } from '@/lib/export/generateIFC';
import type { IFCExportOptions, IFCParcel, IFCControlPoint, IFCTraverseLine, IFCEquipmentRecord } from '@/types/ifc';

/**
 * GET /api/project/[id]/export/ifc?format=ifc4
 *
 * Reads all survey / cadastral data for the given project from the database
 * and returns a complete IFC4 STEP file as an attachment download.
 *
 * Query parameters:
 *   format  – must be "ifc4" (default if omitted)
 *
 * Response headers:
 *   Content-Type:        application/x-step
 *   Content-Disposition: attachment; filename="<project>_export.ifc"
 */
export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (_req, ctx) => {
  const { id } = ctx.params;

  // ── Fetch project row ──────────────────────────────────────────────────
  const { rows: projRows } = await db.query(
    `SELECT name, utm_zone, hemisphere, datum, survey_type,
            client_name, surveyor_name, surveyor_license
       FROM projects WHERE id = $1 AND user_id = $2`,
    [id, ctx.userId],
  );

  if (projRows.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 });
  }

  const proj = projRows[0];

  // ── Fetch survey control points ────────────────────────────────────────
  const { rows: cpRows } = await db.query(
    `SELECT id, name AS label, easting, northing, elevation,
            beacon_type, description
       FROM survey_points
      WHERE project_id = $1 AND is_control = true
      ORDER BY name`,
    [id],
  );

  // ── Fetch parcel polygons ──────────────────────────────────────────────
  const { rows: parcelRows } = await db.query(
    `SELECT p.id, p.label, p.parcel_number, p.area_m2,
            (
              SELECT jsonb_agg(
                jsonb_build_object('easting', pv.easting, 'northing', pv.northing, 'elevation', pv.elevation)
                ORDER BY pv.vertex_order
              )
              FROM parcel_vertices pv WHERE pv.parcel_id = p.id
            ) AS vertices
       FROM parcels p
      WHERE p.project_id = $1
      ORDER BY p.label`,
    [id],
  );

  // ── Fetch traverse lines ───────────────────────────────────────────────
  const { rows: traverseRows } = await db.query(
    `SELECT ts.from_point, ts.to_point, ts.distance
       FROM traverse_stations ts
      WHERE ts.project_id = $1
      ORDER BY ts.id`,
    [id],
  );

  // ── Fetch equipment records ────────────────────────────────────────────
  const { rows: equipRows } = await db.query(
    `SELECT id, make, model, serial_number, last_calibration_date
       FROM equipment
      WHERE user_id = $1
      ORDER BY make, model`,
    [ctx.userId],
  );

  // ── Build IFC export options ──────────────────────────────────────────

  // Derive EPSG code from UTM zone + hemisphere
  const utmZone = proj.utm_zone ?? 37;
  const hemisphere = (proj.hemisphere ?? 'S').toUpperCase();
  const epsgCode = hemisphere === 'N' ? 32600 + utmZone : 32700 + utmZone;

  const parcels: IFCParcel[] = (parcelRows ?? []).map((r: Record<string, unknown>) => ({
    id: r.id as string,
    label: (r.label as string) ?? r.parcel_number ?? 'Unnamed',
    vertices: (Array.isArray(r.vertices) ? r.vertices : []) as IFCParcel['vertices'],
    areaM2: (r.area_m2 as number) ?? undefined,
    parcelNumber: (r.parcel_number as string) ?? undefined,
  }));

  const controlPoints: IFCControlPoint[] = (cpRows ?? []).map((r: Record<string, unknown>) => ({
    id: r.id as string,
    label: (r.label as string) ?? (r.name as string) ?? '',
    easting: r.easting as number,
    northing: r.northing as number,
    elevation: (r.elevation as number) ?? undefined,
    beaconType: (r.beacon_type as string) ?? undefined,
    description: (r.description as string) ?? undefined,
  }));

  const traverseLines: IFCTraverseLine[] = (traverseRows ?? []).map((r: Record<string, unknown>) => ({
    fromPoint: (r.from_point as string) ?? '',
    toPoint: (r.to_point as string) ?? '',
    distance: (r.distance as number) ?? undefined,
  }));

  const equipment: IFCEquipmentRecord[] = (equipRows ?? []).map((r: Record<string, unknown>) => ({
    id: r.id as string,
    make: (r.make as string) ?? '',
    model: (r.model as string) ?? '',
    serialNumber: (r.serial_number as string) ?? undefined,
    lastCalibration: (r.last_calibration_date as string) ?? undefined,
  }));

  const ifcOpts: IFCExportOptions = {
    projectName: proj.name,
    projectNumber: proj.name,
    surveyorName: (proj.surveyor_name as string) ?? undefined,
    surveyorLicense: (proj.surveyor_license as string) ?? undefined,
    coordinateSystem: `UTM_${utmZone}${hemisphere}`,
    epsgCode,
    parcels: parcels.length > 0 ? parcels : undefined,
    controlPoints: controlPoints.length > 0 ? controlPoints : undefined,
    traverseLines: traverseLines.length > 0 ? traverseLines : undefined,
    equipment: equipment.length > 0 ? equipment : undefined,
  };

  // ── Generate IFC4 content ─────────────────────────────────────────────
  const ifcContent = generateIFC4(ifcOpts);

  const safeName = proj.name.replace(/[^a-zA-Z0-9_.-]/g, '_');
  const filename = `${safeName}_export.ifc`;

  return new NextResponse(ifcContent, {
    status: 200,
    headers: {
      'Content-Type': 'application/x-step',
      'Content-Disposition': `attachment; filename="${filename}"`,
      'Content-Length': String(Buffer.byteLength(ifcContent, 'utf-8')),
    },
  });
});

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Field-to-Finish API Route
// ──────────────────────────────────────────────────────────────────────────
// POST /api/project/[id]/field-to-finish
//
// The ONE endpoint a surveyor needs after fieldwork.
//
// Takes the project's raw observations → runs the full pipeline:
//   1. EDM corrections
//   2. Traverse adjustment
//   3. Closure check
//   4. Area computation
//   5. Pre-submission validation
//
// Returns everything the surveyor needs to know:
//   - Did the traverse close?
//   - What's the area?
//   - Is it ready for submission?
//   - What's blocking submission?
//
// Usage:
//   const res = await fetch(`/api/project/${id}/field-to-finish`, { method: 'POST' });
//   const result = await res.json();
//   // result.instantFeedback.passes → true/false
//   // result.area.hectares → 0.4523
//   // result.preSubmit.ready → true/false
//   // result.preSubmit.issues → [...]
// ──────────────────────────────────────────────────────────────────────────

import { NextRequest, NextResponse } from 'next/server';
import { getToken } from 'next-auth/jwt';
import { db } from '@/lib/db';
import { fieldToFinish, type FieldObservation, type FieldToFinishInput } from '@/lib/survey/field-to-finish';
import { preSubmitCheck } from '@/lib/submission/pre-submit-check';

export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } },
) {
  // Auth
  const token = await getToken({ req: request, secret: process.env.AUTH_SECRET });
  if (!token?.email) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const projectId = params.id;

  try {
    // ── Load project data ──
    const projectResult = await db.query(
      'SELECT * FROM projects WHERE id = $1',
      [projectId],
    );

    if (projectResult.rows.length === 0) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 });
    }

    const project = projectResult.rows[0];

    // ── Load survey points ──
    const pointsResult = await db.query(
      `SELECT * FROM survey_points
       WHERE project_id = $1
       ORDER BY name`,
      [projectId],
    );

    const surveyPoints = pointsResult.rows;

    // ── Load field book observations ──
    const obsResult = await db.query(
      `SELECT * FROM field_book_entries
       WHERE project_id = $1
       ORDER BY created_at`,
      [projectId],
    );

    const fieldObs: FieldObservation[] = obsResult.rows.map((row: Record<string, unknown>) => ({
      fromStation: String(row.from_station || row.station_from || ''),
      toStation: String(row.to_station || row.station_to || ''),
      bearing: row.bearing != null ? parseFloat(String(row.bearing)) : undefined,
      slopeDistance: parseFloat(String(row.slope_distance || row.slope_distance_m || 0)),
      verticalAngle: row.vertical_angle != null ? parseFloat(String(row.vertical_angle)) : undefined,
      ih: row.instrument_height != null ? parseFloat(String(row.instrument_height)) : undefined,
      th: row.target_height != null ? parseFloat(String(row.target_height)) : undefined,
      temperature: row.temperature != null ? parseFloat(String(row.temperature)) : undefined,
      pressure: row.pressure != null ? parseFloat(String(row.pressure)) : undefined,
      humidity: row.humidity != null ? parseFloat(String(row.humidity)) : undefined,
    }));

    // ── Run field-to-finish pipeline ──
    const input: FieldToFinishInput = {
      observations: fieldObs,
      startStation: {
        name: surveyPoints[0]?.name || 'P1',
        easting: parseFloat(surveyPoints[0]?.easting || 0),
        northing: parseFloat(surveyPoints[0]?.northing || 0),
      },
      closeStation: project.close_easting ? {
        name: 'CLOSE',
        easting: parseFloat(project.close_easting),
        northing: parseFloat(project.close_northing),
      } : undefined,
      mode: project.close_easting ? 'link' : 'closed',
      surveyType: project.survey_type || 'cadastral',
      adjustmentMethod: 'bowditch',
      lrNumber: project.lr_number,
    };

    const pipelineResult = await fieldToFinish(input);

    // ── Run pre-submission check ──
    const preSubmit = preSubmitCheck(
      {
        ...project,
        survey_points: surveyPoints,
      },
      surveyPoints.map((p: Record<string, unknown>) => ({
        name: String(p.name),
        easting: parseFloat(String(p.easting || 0)),
        northing: parseFloat(String(p.northing || 0)),
        type: p.type ? String(p.type) : undefined,
      })),
      pipelineResult.status !== 'failed'
        ? {
            precisionRatio: pipelineResult.instantFeedback.precisionRatio,
            passes: pipelineResult.instantFeedback.passes,
            totalDistance: pipelineResult.instantFeedback.perimeter,
            linearError: pipelineResult.instantFeedback.linearMisclosure,
          }
        : undefined,
    );

    // ── Save computed results back to project ──
    if (pipelineResult.status !== 'failed') {
      await db.query(
        `UPDATE projects SET
           precision_ratio = $1,
           linear_misclosure = $2,
           closing_error_e = $3,
           closing_error_n = $4,
           area_m2 = $5,
           perimeter_m = $6,
           updated_at = NOW()
         WHERE id = $7`,
        [
          pipelineResult.instantFeedback.precisionFormatted,
          pipelineResult.instantFeedback.linearMisclosure,
          pipelineResult.instantFeedback.closingErrorE,
          pipelineResult.instantFeedback.closingErrorN,
          pipelineResult.area.squareMetres,
          pipelineResult.closureCheck.perimeter,
          projectId,
        ],
      );
    }

    // ── Return everything ──
    return NextResponse.json({
      ...pipelineResult,
      preSubmit: {
        ready: preSubmit.ready,
        score: preSubmit.score,
        summary: preSubmit.summary,
        blockers: preSubmit.blockers,
        warnings: preSubmit.warnings,
        categories: preSubmit.categories,
      },
    });
  } catch (err) {
    console.error('[Field-to-Finish] Error:', err);
    return NextResponse.json(
      { error: 'Pipeline failed', details: String(err) },
      { status: 500 },
    );
  }
}

