/**
 * DELETE /api/project/[id]
 *
 * Deletes a project and ALL related data in a single statement.
 * All child tables have ON DELETE CASCADE, so PostgreSQL handles
 * the full cleanup automatically — no manual DELETE per table needed.
 *
 * Steps:
 * 1. Verify authentication and ownership
 * 2. Log the deletion in audit_logs (before the project disappears)
 * 3. Execute: DELETE FROM projects WHERE id = $1 AND user_id = $2
 *    → CASCADE propagates to every child row
 */
export const DELETE = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { id } = ctx.params

  // ── Verify project exists and belongs to the authenticated user ──
  const { rows: projectRows } = await db.query(
    'SELECT id, name FROM projects WHERE id = $1 AND user_id = $2',
    [id, ctx.userId]
  )
  if (projectRows.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  const projectName = projectRows[0].name

  // ── Audit log before deletion (non-blocking — never fail the delete if audit fails) ──
  try {
    await db.query(
      `INSERT INTO audit_logs (action, table_name, record_id, user_id, details)
       VALUES ($1, $2, $3, $4, $5)`,
      [
        'DELETE',
        'projects',
        id,
        ctx.userId,
        JSON.stringify({ project_name: projectName, message: 'Project deleted with CASCADE' }),
      ]
    )
  } catch (auditErr) {
    console.warn('[DELETE /api/project] audit_logs insert failed (non-fatal):', auditErr)
  }

  // ── Single DELETE — CASCADE handles all child tables automatically ──
  const { rowCount } = await db.query(
    'DELETE FROM projects WHERE id = $1 AND user_id = $2',
    [id, ctx.userId]
  )

  if (rowCount === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  return NextResponse.json({ success: true })
})

/**
 * GET /api/project/[id]/validate
 *
 * Runs the statutory validation gate against a project and returns the
 * full result. Used by the SubmissionClient UI to show surveyors
 * whether their project is ready for export BEFORE they hit Generate.
 *
 * SECURITY: Verifies the requesting user owns the project before
 * running validation. The gate result exposes surveyor profile info,
 * traverse accuracy, and parcel geometry — sensitive data.
 *
 * Response shape (200):
 *   {
 *     gate: StatutoryGateResult,
 *     formatted: string  // human-readable summary
 *   }
 *
 * Response shape (403): project belongs to another user (IDOR protection)
 * Response shape (404): project not found
 *
 * The route never throws on validation failure — that's the gate's job.
 * It only throws on infrastructure errors (DB unavailable, etc).
 */

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { requireProjectOwnership } from '@/lib/auth/ownership'
import { runStatutoryGate, formatGateResult } from '@/lib/validation/statutoryGate'
import { loadGateInputForProject, mergeGateInput } from '@/lib/validation/statutoryGateLoader'
import { fetchSurveyorProfile } from '@/lib/survey/fetchSurveyorProfile'

export const GET = apiHandler(
  { auth: true, rateLimit: { max: 30, windowMs: 60000 } },
  async (_req, ctx) => {
    const { id } = ctx.params

    // IDOR protection — verify project ownership
    const ownership = await requireProjectOwnership(id, ctx.userId)
    if (!ownership.ok) return ownership.error!

    // Load gate input from DB
    const loadedInput = await loadGateInputForProject(id)
    if (!loadedInput) {
      return NextResponse.json(
        { error: 'Project not found' },
        { status: 404 }
      )
    }

    // Merge in surveyor profile (loaded from project + surveyor_profiles)
    const profile = await fetchSurveyorProfile(id)
    const gateInput = mergeGateInput(loadedInput, {
      surveyor: {
        name: profile.surveyorName || loadedInput.surveyor.name,
        licenseNumber: profile.iskNumber || loadedInput.surveyor.licenseNumber,
      },
    })

    // Run the gate (pure function — no side effects)
    const gateResult = runStatutoryGate(gateInput)

    return apiSuccess({
      gate: gateResult,
      formatted: formatGateResult(gateResult),
    })
  }
)

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import {
  getWorkflowStatus,
  advanceWorkflow,
  type ProjectWorkflowData,
} from '@/lib/workflows/projectWorkflowEngine'

/**
 * GET /api/project/[id]/workflow
 * Returns the full workflow status for a project.
 */
export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (_req, ctx) => {
  const { id } = ctx.params

  // Fetch project data
  const { rows } = await db.query(
    `SELECT p.id, p.name, p.survey_type, p.location, p.utm_zone, p.hemisphere,
            p.workflow_step, p.workflow_max_unlocked
     FROM projects p
     WHERE p.id = $1 AND p.user_id = $2`,
    [id, ctx.userId]
  )

  if (rows.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  const project = rows[0]

  // Fetch related counts
  const [pointsRes, fieldbookRes, computationsRes, deedPlanRes, submissionRes] = await Promise.all([
    db.query('SELECT COUNT(*)::int AS cnt FROM survey_points WHERE project_id = $1', [id]),
    db.query('SELECT COUNT(*)::int AS cnt FROM fieldbook_entries WHERE project_id = $1 AND deleted_at IS NULL', [id]).catch(() => ({ rows: [{ cnt: 0 }] })),
    db.query("SELECT COUNT(*)::int AS cnt FROM computations WHERE project_id = $1 AND status = 'completed'", [id]).catch(() => ({ rows: [{ cnt: 0 }] })),
    db.query('SELECT COUNT(*)::int AS cnt FROM deed_plans WHERE project_id = $1', [id]).catch(() => ({ rows: [{ cnt: 0 }] })),
    db.query('SELECT COUNT(*)::int AS cnt FROM submissions WHERE project_id = $1', [id]).catch(() => ({ rows: [{ cnt: 0 }] })),
  ])

  const pointCount = pointsRes.rows[0]?.cnt ?? 0
  const fieldbookEntryCount = fieldbookRes.rows[0]?.cnt ?? 0
  const hasComputationResults = (computationsRes.rows[0]?.cnt ?? 0) > 0
  const hasDeedPlan = (deedPlanRes.rows[0]?.cnt ?? 0) > 0
  const hasSubmissionPackage = (submissionRes.rows[0]?.cnt ?? 0) > 0

  // Check tolerance from quality_checks table (or derive from computations)
  let toleranceCheckPassed: boolean | null = null
  let toleranceAcknowledged = false
  try {
    const qcRes = await db.query(
      'SELECT passed, acknowledged FROM quality_checks WHERE project_id = $1 ORDER BY created_at DESC LIMIT 1',
      [id]
    )
    if (qcRes.rows.length > 0) {
      toleranceCheckPassed = qcRes.rows[0].passed
      toleranceAcknowledged = !!qcRes.rows[0].acknowledged
    }
  } catch {
    // quality_checks table may not exist yet — that's OK
  }

  const workflowData: ProjectWorkflowData = {
    id: project.id,
    name: project.name,
    surveyType: project.survey_type,
    location: project.location,
    utmZone: project.utm_zone,
    hemisphere: project.hemisphere,
    currentStep: project.workflow_step ?? 1,
    maxUnlocked: project.workflow_max_unlocked ?? 1,
    pointCount,
    fieldbookEntryCount,
    hasComputationResults,
    toleranceCheckPassed,
    toleranceAcknowledged,
    hasDeedPlan,
    hasSubmissionPackage,
  }

  const status = getWorkflowStatus(workflowData)

  return NextResponse.json({ data: status })
})

/**
 * POST /api/project/[id]/workflow/advance
 * Advance the workflow to the next step if conditions are met.
 * Body: { acknowledgeTolerance?: boolean }
 */
export const POST = apiHandler({ auth: true, rateLimit: { max: 30, windowMs: 60000 } }, async (_req, ctx) => {
  const { id } = ctx.params
  const body = ctx.body as { acknowledgeTolerance?: boolean } | undefined

  // Fetch project data
  const { rows } = await db.query(
    `SELECT p.id, p.name, p.survey_type, p.location, p.utm_zone, p.hemisphere,
            p.workflow_step, p.workflow_max_unlocked
     FROM projects p
     WHERE p.id = $1 AND p.user_id = $2`,
    [id, ctx.userId]
  )

  if (rows.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  const project = rows[0]

  // If acknowledging tolerance, save that first
  if (body?.acknowledgeTolerance) {
    try {
      await db.query(
        `INSERT INTO quality_checks (project_id, passed, acknowledged, created_at)
         VALUES ($1, false, true, NOW())
         ON CONFLICT (project_id) DO UPDATE SET acknowledged = true`,
        [id]
      )
    } catch {
      // If table doesn't exist, we can still proceed with in-memory state
    }
  }

  // Fetch related counts
  const [pointsRes, fieldbookRes, computationsRes, deedPlanRes, submissionRes] = await Promise.all([
    db.query('SELECT COUNT(*)::int AS cnt FROM survey_points WHERE project_id = $1', [id]),
    db.query('SELECT COUNT(*)::int AS cnt FROM fieldbook_entries WHERE project_id = $1 AND deleted_at IS NULL', [id]).catch(() => ({ rows: [{ cnt: 0 }] })),
    db.query("SELECT COUNT(*)::int AS cnt FROM computations WHERE project_id = $1 AND status = 'completed'", [id]).catch(() => ({ rows: [{ cnt: 0 }] })),
    db.query('SELECT COUNT(*)::int AS cnt FROM deed_plans WHERE project_id = $1', [id]).catch(() => ({ rows: [{ cnt: 0 }] })),
    db.query('SELECT COUNT(*)::int AS cnt FROM submissions WHERE project_id = $1', [id]).catch(() => ({ rows: [{ cnt: 0 }] })),
  ])

  let toleranceCheckPassed: boolean | null = null
  let toleranceAcknowledged = !!body?.acknowledgeTolerance
  try {
    const qcRes = await db.query(
      'SELECT passed, acknowledged FROM quality_checks WHERE project_id = $1 ORDER BY created_at DESC LIMIT 1',
      [id]
    )
    if (qcRes.rows.length > 0) {
      toleranceCheckPassed = qcRes.rows[0].passed
      toleranceAcknowledged = qcRes.rows[0].acknowledged || !!body?.acknowledgeTolerance
    }
  } catch {
    // OK
  }

  const workflowData: ProjectWorkflowData = {
    id: project.id,
    name: project.name,
    surveyType: project.survey_type,
    location: project.location,
    utmZone: project.utm_zone,
    hemisphere: project.hemisphere,
    currentStep: project.workflow_step ?? 1,
    maxUnlocked: project.workflow_max_unlocked ?? 1,
    pointCount: pointsRes.rows[0]?.cnt ?? 0,
    fieldbookEntryCount: fieldbookRes.rows[0]?.cnt ?? 0,
    hasComputationResults: (computationsRes.rows[0]?.cnt ?? 0) > 0,
    toleranceCheckPassed,
    toleranceAcknowledged,
    hasDeedPlan: (deedPlanRes.rows[0]?.cnt ?? 0) > 0,
    hasSubmissionPackage: (submissionRes.rows[0]?.cnt ?? 0) > 0,
  }

  const newStep = advanceWorkflow(workflowData)

  if (newStep === null) {
    const status = getWorkflowStatus(workflowData)
    return NextResponse.json(
      { error: 'Cannot advance workflow', blockers: status.blockers },
      { status: 400 }
    )
  }

  // Update project in DB
  const newMax = Math.max(workflowData.maxUnlocked, newStep)
  await db.query(
    'UPDATE projects SET workflow_step = $1, workflow_max_unlocked = $2, updated_at = NOW() WHERE id = $3',
    [newStep, newMax, id]
  )

  // Return updated status
  const updatedData = { ...workflowData, currentStep: newStep, maxUnlocked: newMax }
  const status = getWorkflowStatus(updatedData)

  return NextResponse.json({ data: { newStep, status } })
})

export const dynamic = 'force-dynamic'

/**
 * POST /api/projects/[id]/approve
 *
 * Approve & Lock a project.
 *
 * Only a LICENSED surveyor with verified ISK credentials can invoke this.
 * The handler:
 *   1. Resolves the caller's role from surveyor_profiles
 *   2. Checks RBAC via canApproveAndLock()
 *   3. Builds a canonical JSON of all control_points + parcels
 *   4. Computes a SHA-256 cryptographic seal
 *   5. Sets project status to 'LOCKED' and stores the seal
 */

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { createHash } from 'crypto'
import { getRoleFromProfile, canApproveAndLock } from '@/lib/rbac'
import { notifyProjectLocked } from '@/lib/notifications/africasTalking'

export const POST = apiHandler({ auth: true, audit: 'project:approve_lock', rateLimit: { max: 60, windowMs: 60000 },
  auditChain: { entityType: 'parcel', action: 'lock', entityIdParam: 'id' } }, async (_req, ctx) => {
  const projectId = ctx.params.id

  if (!projectId) {
    return NextResponse.json(
      { error: 'Project ID is required', code: 'VALIDATION_ERROR' },
      { status: 400 }
    )
  }

  // ── 1. Resolve role from surveyor_profiles ──────────────────────────
  const email = ctx.session?.user?.email
  if (!email) {
    return NextResponse.json(
      { error: 'Cannot determine user email from session', code: 'UNAUTHORIZED' },
      { status: 401 }
    )
  }

  const { rows: profileRows } = await db.query(
    `SELECT role, verified_isk, phone
     FROM surveyor_profiles
     WHERE email = $1
     LIMIT 1`,
    [email]
  )

  if (profileRows.length === 0) {
    return NextResponse.json(
      { error: 'Surveyor profile not found. Please complete your profile.', code: 'PROFILE_MISSING' },
      { status: 403 }
    )
  }

  const profile = profileRows[0]
  const role = getRoleFromProfile({ role: profile.role, verified_isk: profile.verified_isk })
  const verifiedIsk = !!profile.verified_isk

  // ── 2. RBAC check ───────────────────────────────────────────────────
  if (!canApproveAndLock(role, verifiedIsk)) {
    return NextResponse.json(
      { error: 'Only licensed surveyors with verified ISK can approve and lock projects.', code: 'FORBIDDEN' },
      { status: 403 }
    )
  }

  // ── 3. Verify project exists and is not already locked ──────────────
  const { rows: projectRows } = await db.query(
    `SELECT id, status, name, lr_number FROM projects WHERE id = $1`,
    [projectId]
  )

  if (projectRows.length === 0) {
    return NextResponse.json(
      { error: 'Project not found', code: 'NOT_FOUND' },
      { status: 404 }
    )
  }

  if (projectRows[0].status === 'LOCKED') {
    return NextResponse.json(
      { error: 'Project is already locked and approved.', code: 'ALREADY_LOCKED' },
      { status: 409 }
    )
  }

  // ── 4. Fetch all control points and parcels for canonical hashing ────
  // AUDIT FIX (2026-07-03): control_points table doesn't exist → use
  // survey_points WHERE is_control=true. survey_points.name → point_name.
  // parcels.area_sqm → area_ha. Removed non-existent geometry_type/
  // description columns.
  const [pointsResult, parcelsResult] = await Promise.all([
    db.query(
      `SELECT point_name, easting, northing, elevation, description
       FROM survey_points
       WHERE project_id = $1 AND is_control = true
       ORDER BY point_name ASC`,
      [projectId]
    ),
    db.query(
      `SELECT parcel_number, area_ha, status
       FROM parcels
       WHERE project_id = $1
       ORDER BY parcel_number ASC`,
      [projectId]
    ),
  ])

  // ── 5. Build canonical JSON and compute SHA-256 seal ─────────────────
  const canonicalPayload = {
    projectId,
    control_points: pointsResult.rows,
    parcels: parcelsResult.rows,
  }

  const canonicalJson = JSON.stringify(canonicalPayload, Object.keys(canonicalPayload).sort())
  const seal = createHash('sha256').update(canonicalJson).digest('hex')

  // ── 6. Lock the project with the cryptographic seal ──────────────────
  const { rows: updatedRows } = await db.query(
    `UPDATE projects
     SET status = 'LOCKED',
         cryptographic_seal = $1,
         updated_at = NOW()
     WHERE id = $2 AND status != 'LOCKED'
     RETURNING id, status, cryptographic_seal, updated_at`,
    [seal, projectId]
  )

  if (updatedRows.length === 0) {
    // Race condition: another request locked it first
    return NextResponse.json(
      { error: 'Project was locked by another request.', code: 'ALREADY_LOCKED' },
      { status: 409 }
    )
  }

  // ── 7. Notify surveyor via SMS (non-blocking) ───────────────────
  try {
    const projectName = projectRows[0].name || projectId
    const lrNumber = projectRows[0].lr_number || undefined
    const surveyorName = ctx.session?.user?.name || email
    const surveyorPhone = profile.phone || undefined

    await notifyProjectLocked({
      projectName,
      lrNumber,
      surveyorName,
      surveyorPhone,
      seal,
      projectId,
    })
  } catch (notifyErr) {
    console.error('[project:approve] Notification failed (non-blocking):', notifyErr)
  }

  return NextResponse.json({
    success: true,
    seal,
    lockedAt: updatedRows[0].updated_at
      ? new Date(updatedRows[0].updated_at).toISOString()
      : new Date().toISOString(),
  })
})

import { NextResponse } from 'next/server'
import { apiHandler, apiSuccess } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { getAuthUser } from '@/lib/auth/session'
import { computeAreaWithPrecision } from '@/lib/engine/computationalAccuracy'

export const dynamic = 'force-dynamic'

interface BatchParcelInput {
  parcelNumber: string
  ownerName?: string
  ownerId?: string
  lrNumber?: string
  areaHa?: number
  vertices: Array<{ easting: number; northing: number }>
}

/**
 * POST /api/projects/[id]/parcels/batch
 *
 * Bulk import parcels to a project.
 * Accepts an array of parcels with vertices and owner data.
 * Creates parcel records + beacon records in a single transaction.
 *
 * Body:
 *   parcels: BatchParcelInput[]
 *
 * Returns:
 *   { imported: number, failed: number, errors: string[] }
 */
export const POST = apiHandler(
  { auth: true, rateLimit: { max: 10, windowMs: 60000 } },
  async (req, ctx) => {
    const user = await getAuthUser()
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const projectId = ctx.params?.id as string
    if (!projectId) {
      return NextResponse.json({ error: 'Project ID is required' }, { status: 400 })
    }

    // Verify project ownership
    const projectRes = await db.query(
      'SELECT id, user_id FROM projects WHERE id = $1',
      [projectId],
    )
    if (projectRes.rows.length === 0) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 })
    }
    if (projectRes.rows[0].user_id !== user.id) {
      return NextResponse.json({ error: 'Access denied' }, { status: 403 })
    }

    const body = ctx.body as { parcels: BatchParcelInput[] }
    const parcels = body.parcels

    if (!Array.isArray(parcels) || parcels.length === 0) {
      return NextResponse.json({ error: 'No parcels provided' }, { status: 400 })
    }

    if (parcels.length > 1000) {
      return NextResponse.json(
        { error: 'Maximum 1000 parcels per batch' },
        { status: 400 },
      )
    }

    let imported = 0
    let failed = 0
    const errors: string[] = []

    // Process each parcel
    for (let i = 0; i < parcels.length; i++) {
      const parcel = parcels[i]
      try {
        // Validate
        if (!parcel.parcelNumber?.trim()) {
          errors.push(`Parcel ${i + 1}: Missing parcel number`)
          failed++
          continue
        }
        if (!parcel.vertices || parcel.vertices.length < 3) {
          errors.push(`Parcel ${parcel.parcelNumber}: Needs at least 3 vertices`)
          failed++
          continue
        }

        // Compute area if not provided
        let areaHa = parcel.areaHa
        if (!areaHa) {
          const areaResult = computeAreaWithPrecision(parcel.vertices)
          areaHa = parseFloat(areaResult.areaHectares.toFixed(4))
        }

        // Check for duplicate parcel number in this project
        const existing = await db.query(
          `SELECT id FROM parcels WHERE project_id = $1 AND parcel_number = $2`,
          [projectId, parcel.parcelNumber],
        )
        if (existing.rows.length > 0) {
          errors.push(`Parcel ${parcel.parcelNumber}: Already exists in project`)
          failed++
          continue
        }

        // Insert parcel
        // AUDIT FIX (2026-07-03): geometry → geom, removed non-existent
        // owner_name/owner_id/lr_number (lr goes into lr_number_proposed).
        const parcelResult = await db.query(
          `INSERT INTO parcels (project_id, parcel_number, lr_number_proposed, area_ha, geom, created_at)
           VALUES ($1, $2, $3, $4, ST_GeomFromText($5, 21037), NOW())
           RETURNING id`,
          [
            projectId,
            parcel.parcelNumber,
            parcel.lrNumber || null,
            areaHa,
            `POLYGON((${parcel.vertices.map(v => `${v.easting} ${v.northing}`).join(', ')}, ${parcel.vertices[0].easting} ${parcel.vertices[0].northing}))`,
          ],
        )

        const parcelId = parcelResult.rows[0].id

        // Insert beacons for each vertex
        // AUDIT FIX: survey_points has no parcel_id/point_type → use code='BEACON'
        for (let v = 0; v < parcel.vertices.length; v++) {
          const vertex = parcel.vertices[v]
          const beaconNumber = `${parcel.parcelNumber}/B${v + 1}`
          await db.query(
            `INSERT INTO survey_points (project_id, point_name, easting, northing, code, created_at)
             VALUES ($1, $2, $3, $4, 'BEACON', NOW())`,
            [projectId, beaconNumber, vertex.easting, vertex.northing],
          )
        }

        imported++
      } catch (err) {
        errors.push(`Parcel ${parcel.parcelNumber || i + 1}: ${err instanceof Error ? err.message : 'Unknown error'}`)
        failed++
      }
    }

    // Log activity
    await db.query(
      `INSERT INTO user_activity (user_id, project_id, activity_type, description, metadata, created_at)
       VALUES ($1, $2, 'batch_import', $3, $4, NOW())`,
      [
        user.id,
        projectId,
        `Batch imported ${imported} parcels (${failed} failed)`,
        JSON.stringify({ imported, failed, total: parcels.length }),
      ],
    ).catch(() => {}) // Non-critical

    return apiSuccess({
      imported,
      failed,
      errors: errors.slice(0, 20), // Limit error messages
      total: parcels.length,
    })
  },
)

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { getAuthUser } from '@/lib/auth/session'
import { apiHandler } from '@/lib/apiHandler'
import { z } from 'zod'

/**
 * DELETE /api/projects/[id]
 *
 * Deletes a project and ALL associated data from every table that references
 * project_id, in reverse dependency order, wrapped in a transaction.
 *
 * Tables WITH CASCADE FK (already handled by DB but we delete explicitly
 * for safety in case some child tables have their own children without CASCADE):
 *   alignments, beacons, chainage_points, engineering_compute_results,
 *   mining_surveys, network_adjustments, parcels, scheme_details,
 *   submissions, supporting_documents, survey_points
 *
 * Tables WITHOUT FK (must be deleted manually to avoid orphans):
 *   bathymetric_surveys, benchmarks, cadastra_validations, cleaned_datasets,
 *   deed_plans, documents, field_books, gnss_sessions, history,
 *   leveling_runs, mine_twins, presence, project_attachments,
 *   project_beacons, project_fieldbook_entries, project_members,
 *   project_notes, project_submissions, rim_sections, safety_incidents,
 *   submission_documents, survey_epochs, survey_photos, survey_reports,
 *   usv_missions
 */

// Deduplicated list of all tables to delete from (child-first order)
const UNIQUE_TABLES = [
  'survey_photos', 'submission_documents', 'project_attachments',
  'project_beacons', 'project_fieldbook_entries', 'project_notes',
  'project_members', 'project_submissions', 'presence',
  'safety_incidents', 'history', 'documents', 'survey_epochs',
  'rim_sections', 'cleaned_datasets', 'cadastra_validations',
  'survey_points', 'chainage_points', 'alignments', 'beacons',
  'network_adjustments', 'engineering_compute_results', 'mining_surveys',
  'parcels', 'submissions', 'supporting_documents', 'scheme_details',
  'bathymetric_surveys', 'benchmarks', 'deed_plans', 'field_books',
  'gnss_sessions', 'leveling_runs', 'mine_twins', 'survey_reports',
]

/**
 * PATCH /api/projects/[id]
 *
 * Update a project's mutable fields with optimistic locking.
 * Frontend MUST send `updated_at` in the request body — the value should be
 * the `updated_at` timestamp from the most recent GET/fetch of this project.
 * If the DB row's `updated_at` differs (another surveyor edited it), returns 409.
 */
const patchProjectSchema = z.object({
  name: z.string().min(1).optional(),
  survey_type: z.string().optional(),
  client_name: z.string().nullable().optional(),
  location: z.string().nullable().optional(),
  lr_number: z.string().nullable().optional(),
  utm_zone: z.number().int().min(1).max(60).optional(),
  hemisphere: z.enum(['N', 'S']).optional(),
  datum: z.string().optional(),
  area_ha: z.number().nullable().optional(),
  status: z.enum(['active', 'draft', 'review', 'LOCKED']).optional(),
  // Optimistic locking: frontend must send the updated_at value it last read
  updated_at: z.string(),
})

export const PATCH = apiHandler(
  { auth: true, optimisticLock: true, schema: patchProjectSchema },
  async (_req, ctx) => {
    const { id } = ctx.params
    const body = ctx.body as z.infer<typeof patchProjectSchema>

    // Fetch current row for ownership check + optimistic lock
    const { rows } = await db.query(
      'SELECT id, user_id, updated_at FROM projects WHERE id = $1',
      [id]
    )

    if (rows.length === 0) {
      return NextResponse.json({ error: 'Project not found', code: 'NOT_FOUND' }, { status: 404 })
    }

    if (rows[0].user_id !== ctx.userId) {
      return NextResponse.json({ error: 'Forbidden — you do not own this project', code: 'FORBIDDEN' }, { status: 403 })
    }

    // T1.8 FIX (2026-07-09): Optimistic lock guard moved to the SQL WHERE clause.
    // The old checkOptimisticLock() did SELECT → JS check → UPDATE without the guard.

    // Build dynamic UPDATE — only SET fields that were provided
    const fields: string[] = []
    const values: unknown[] = []
    let paramIdx = 1

    const allowedFields: Record<string, string> = {
      name: 'name',
      survey_type: 'survey_type',
      client_name: 'client_name',
      location: 'location',
      lr_number: 'lr_number',
      utm_zone: 'utm_zone',
      hemisphere: 'hemisphere',
      datum: 'datum',
      area_ha: 'area_ha',
      status: 'status',
    }

    for (const [bodyKey, colName] of Object.entries(allowedFields)) {
      if (bodyKey in body && body[bodyKey as keyof typeof body] !== undefined) {
        fields.push(`${colName} = $${paramIdx++}`)
        values.push(body[bodyKey as keyof typeof body])
      }
    }

    if (fields.length === 0) {
      return NextResponse.json({ error: 'No fields to update', code: 'NO_FIELDS' }, { status: 400 })
    }

    // Always bump updated_at
    fields.push(`updated_at = NOW()`)
    values.push(id)
    // T1.8: Add the optimistic lock guard to the WHERE clause
    values.push(body.updated_at)

    const result = await db.query(
      `UPDATE projects SET ${fields.join(', ')} WHERE id = $${paramIdx} AND updated_at = $${paramIdx + 1} RETURNING *`,
      values
    )

    if (result.rows.length === 0) {
      return NextResponse.json(
        { error: 'This project was modified by another user. Please refresh and try again.', code: 'CONFLICT' },
        { status: 409 }
      )
    }

    return NextResponse.json({ data: result.rows[0] })
  }
)

export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const user = await getAuthUser()
    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { id } = await params

    if (!id || typeof id !== 'string') {
      return NextResponse.json({ error: 'Invalid project ID' }, { status: 400 })
    }

    // Verify project exists and belongs to the current user
    const ownership = await db.query(
      'SELECT id, user_id FROM projects WHERE id = $1',
      [id]
    )

    if (ownership.rows.length === 0) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 })
    }

    const project = ownership.rows[0]
    if (project.user_id !== user.id) {
      return NextResponse.json({ error: 'Forbidden — you do not own this project' }, { status: 403 })
    }

    // Delete from all related tables in a single transaction
    const deletedTables: string[] = []
    const skippedTables: string[] = []
    const errors: string[] = []

    await db.transaction(async (client) => {
      for (const table of UNIQUE_TABLES) {
        try {
          await client.query(
            `DELETE FROM ${table} WHERE project_id = $1`,
            [id]
          )
          deletedTables.push(table)
        } catch (err: unknown) {
          // Table might not exist — skip it gracefully
          const msg = (((err as Error)?.message) || '').toLowerCase()
          if (msg.includes('does not exist') || msg.includes('relation') || msg.includes('not exist')) {
            skippedTables.push(table)
          } else {
            // Log but continue — don't abort the entire transaction for one table
            console.warn(`[DELETE /api/projects/${id}] Failed to delete from ${table}:`, (err as Error).message)
            errors.push(`${table}: ${(err as Error).message}`)
          }
        }
      }

      // Finally delete the project itself
      const result = await client.query(
        'DELETE FROM projects WHERE id = $1 AND user_id = $2 RETURNING id',
        [id, user.id]
      )

      if (result.rows.length === 0) {
        throw new Error('Project was deleted by another request or ownership changed')
      }
    })

    return NextResponse.json({
      success: true,
      deletedFrom: deletedTables,
      skipped: skippedTables,
      ...(errors.length > 0 && { warnings: errors }),
    })
  } catch (error: unknown) {
    console.error('[DELETE /api/projects] Error:', error)
    return NextResponse.json(
      {
        error: (error as Error).message || 'Failed to delete project',
        details: process.env.NODE_ENV === 'development' ? (error as Error).stack : undefined,
      },
      { status: 500 }
    )
  }
}

