import { NextResponse } from 'next/server'
import { z } from 'zod'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { generateDeedPlan } from '@/lib/generators/deedPlan'
import JSZip from 'jszip'
import { BatchDeedPlanSchema } from '@/lib/validation/apiSchemas'

export const dynamic = 'force-dynamic'

/**
 * POST /api/scheme/batch/generate-deed-plans
 *
 * Batch-generates deed plans for ALL parcels in a scheme.
 * Returns a ZIP file with one PDF per parcel.
 *
 * Body: { projectId: string }
 *
 * The surveyor clicks one button → gets all deed plans for the scheme.
 * No more generating each parcel's deed plan one by one.
 */
export const POST = apiHandler(
  {
    auth: true, schema: BatchDeedPlanSchema, rateLimit: { max: 5, windowMs: 60000 },
    // T1.9 FIX (2026-07-09): Add audit chain for batch deed plan generation.
    auditChain: {
      entityType: 'document',
      action: 'generate',
      projectIdFromBody: 'projectId',
      reason: 'Batch deed plan generation',
    },
  },
  async (req, ctx) => {
    const { projectId } = ctx.body as z.infer<typeof BatchDeedPlanSchema>

    // Verify project belongs to user
    const projectCheck = await db.query(
      'SELECT id, name, project_type FROM projects WHERE id = $1 AND user_id = $2',
      [projectId, ctx.userId],
    )
    if (projectCheck.rows.length === 0) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 })
    }

    // Get all parcels with their block info
    const parcelsResult = await db.query(
      `SELECT p.id, p.parcel_number, p.lr_number_proposed, p.area_ha, p.status,
              b.block_number, b.block_name
       FROM parcels p
       JOIN blocks b ON b.id = p.block_id
       WHERE p.project_id = $1
       ORDER BY b.block_number, p.parcel_number`,
      [projectId],
    )

    if (parcelsResult.rows.length === 0) {
      return NextResponse.json({ error: 'No parcels found in this scheme' }, { status: 404 })
    }

    // Generate deed plans in chunks of 5 (avoid OOM with large schemes)
    const zip = new JSZip()
    const errors: string[] = []
    let generated = 0

    const CHUNK_SIZE = 5
    for (let i = 0; i < parcelsResult.rows.length; i += CHUNK_SIZE) {
      const chunk = parcelsResult.rows.slice(i, i + CHUNK_SIZE)
      const results = await Promise.allSettled(
        chunk.map(async (parcel) => {
          // ponytail: generateDeedPlan takes projectId and generates the full plan.
          // For per-parcel plans, we'd need a parcel-scoped variant.
          // For now, generate from the parent project — the deed plan includes
          // all parcels. Phase 2: add parcel-scoped deed plan generation.
          const pdfBuffer = await generateDeedPlan(projectId)
          const filename = `Block_${parcel.block_number}_Parcel_${parcel.parcel_number}.pdf`
          return { filename, buffer: pdfBuffer }
        }),
      )

      for (const result of results) {
        if (result.status === 'fulfilled') {
          zip.file(result.value.filename, result.value.buffer)
          generated++
        } else {
          errors.push(result.reason?.message || 'Unknown error')
        }
      }
    }

    // Add manifest
    zip.file('manifest.json', JSON.stringify({
      projectId,
      projectName: projectCheck.rows[0].name,
      generatedAt: new Date().toISOString(),
      totalParcels: parcelsResult.rows.length,
      generated,
      errors,
      parcels: parcelsResult.rows.map((p) => ({
        parcelNumber: p.parcel_number,
        block: p.block_number,
        lrNumber: p.lr_number_proposed,
        area: p.area_ha,
        status: p.status,
      })),
    }, null, 2))

    const zipBuffer = await zip.generateAsync({ type: 'nodebuffer' })

    return new NextResponse(zipBuffer as unknown as BodyInit, {
      headers: {
        'Content-Type': 'application/zip',
        'Content-Disposition': `attachment; filename="deed_plans_${projectId}.zip"`,
      },
    })
  },
)

import { NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { apiHandler } from '@/lib/apiHandler'

export const dynamic = 'force-dynamic'

// ─── DB Row Interfaces ───────────────────────────────────────────────────────

interface ParcelRow {
  id: string
  parcel_number: string
  lr_number_proposed: string | null
  area_ha: string | number | null
  status: string
  block_number: string
  block_name: string | null
}

interface TraverseRow {
  id: string
  accuracy_order: string | null
  total_perimeter: string | number | null
  computed_area_ha: string | number | null
}

interface CoordRow {
  station: string
  easting: string | number
  northing: string | number
}

export const GET = apiHandler(
  { auth: true, audit: 'batch_generated' , rateLimit: { max: 60, windowMs: 60000 } },
  async (req, ctx) => {
    const { searchParams } = new URL(req.url)
    const projectId = searchParams.get('project_id')

    if (!projectId) {
      return NextResponse.json({ error: 'project_id is required' }, { status: 400 })
    }

    const projectCheck = await db.query(
      'SELECT id, name, project_type FROM projects WHERE id = $1 AND user_id = $2',
      [projectId, ctx.userId]
    )
    if (projectCheck.rows.length === 0) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 })
    }

    const parcelsResult = await db.query(
      `SELECT p.id, p.parcel_number, p.lr_number_proposed, p.area_ha, p.status,
      b.block_number, b.block_name
      FROM parcels p
      JOIN blocks b ON b.id = p.block_id
      WHERE p.project_id = $1
      AND p.status IN ('computed', 'plan_generated', 'submitted', 'approved')
      ORDER BY b.block_number, p.parcel_number`,
      [projectId]
    )

    if (parcelsResult.rows.length === 0) {
      return NextResponse.json({ error: 'No computed parcels found. Run traverse computation on parcels first.' }, { status: 400 })
    }

    const { jsPDF } = await import('jspdf')
    const { renderBoundaryPlan } = await import('@/lib/generators/deedPlanRenderer')
    type DeedPlanGeometry = import('@/lib/generators/deedPlanGeometry').DeedPlanGeometry

    const pdfBuffers: Array<{ filename: string; buffer: Buffer }> = []

    for (const parcel of parcelsResult.rows) {
      try {
        const traverseCheck = await db.query(
          `SELECT pt.id, pt.accuracy_order, pt.total_perimeter, pt.computed_area_ha
          FROM parcel_traverses pt WHERE pt.parcel_id = $1`,
          [parcel.id]
        )
        if (traverseCheck.rows.length === 0) continue

        const traverse = traverseCheck.rows[0]
        const traverseId = traverse.id

        const coordsResult = await db.query(
          `SELECT station, easting, northing FROM traverse_coordinates WHERE traverse_id = $1 ORDER BY station`,
          [traverseId]
        )
        if (coordsResult.rows.length < 3) continue

        const stations = coordsResult.rows.map((c) => ({
          station: c.station, easting: parseFloat(String(c.easting)), northing: parseFloat(String(c.northing)),
          beaconNo: c.station, monument: 'psc found',
        }))

        // Build bearing schedule matching DeedPlanGeometry.BearingLeg format
        const bearingSchedule: Array<{ from: string; to: string; bearing: string; distance: string }> = []
        for (let i = 0; i < stations.length; i++) {
          const from = stations[i]
          const to = stations[(i + 1) % stations.length]
          const dE = to.easting - from.easting
          const dN = to.northing - from.northing
          const dist = Math.sqrt(dE * dE + dN * dN)
          const wcbDeg = (Math.atan2(dE, dN) * 180 / Math.PI + 360) % 360
          const wcbD = Math.floor(wcbDeg)
          const wcbM = Math.floor((wcbDeg - wcbD) * 60)
          const wcbS = ((wcbDeg - wcbD) * 60 - wcbM) * 60
          bearingSchedule.push({
            from: from.station,
            to: to.station,
            bearing: `${String(wcbD).padStart(3, '0')}\u00B0${String(wcbM).padStart(2, '0')}'${wcbS.toFixed(1)}"`,
            distance: dist.toFixed(3),
          })
        }

        // Construct DeedPlanGeometry-compatible object
        const minE = Math.min(...stations.map((s) => s.easting))
        const maxE = Math.max(...stations.map((s) => s.easting))
        const minN = Math.min(...stations.map((s) => s.northing))
        const maxN = Math.max(...stations.map((s) => s.northing))
        const areaHa = parcel.area_ha ? parseFloat(String(parcel.area_ha)) : (traverse.computed_area_ha ? parseFloat(String(traverse.computed_area_ha)) : 0)
        const areaM2 = areaHa * 10000

        const geom: DeedPlanGeometry = {
          stations,
          bearingSchedule,
          areaM2,
          areaHa,
          areaAcres: areaHa * 2.47105,
          misclosureMm: 0,
          precisionRatio: '1:0',
          closureStatus: 'UNVERIFIED' as const,
          minE,
          maxE,
          minN,
          maxN,
          coordinateSource: 'computed' as const,
        }

        const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' })
        const pageW = doc.internal.pageSize.getWidth()
        const pageH = doc.internal.pageSize.getHeight()

        doc.setFontSize(10)
        doc.setFont('helvetica', 'bold')
        doc.text('REPUBLIC OF KENYA', pageW / 2, 10, { align: 'center' })
        doc.setFontSize(9)
        doc.text('FORM NO. 4 \u2014 DEED PLAN', pageW / 2, 15, { align: 'center' })

        renderBoundaryPlan(doc, geom, { x: 10, y: 20, width: pageW - 20, height: pageH - 75 })

        const tableY = pageH - 52
        doc.setDrawColor(0)
        doc.setLineWidth(0.4)
        doc.rect(10, tableY, pageW - 20, 48)

        const areaStr = parcel.area_ha
          ? `${parseFloat(String(parcel.area_ha)).toFixed(4)} Ha`
          : traverse.computed_area_ha
            ? `${parseFloat(String(traverse.computed_area_ha)).toFixed(4)} Ha`
            : '\u2014'

        const infoPairs = [
          ['PARCEL:', parcel.parcel_number],
          ['LR NO.:', parcel.lr_number_proposed || 'Pending'],
          ['AREA:', areaStr],
          ['BLOCK:', `${parcel.block_number} \u2014 ${parcel.block_name || 'N/A'}`],
          ['ACCURACY:', traverse.accuracy_order || '\u2014'],
          ['PERIMETER:', traverse.total_perimeter ? `${parseFloat(String(traverse.total_perimeter)).toFixed(3)} m` : '\u2014'],
        ]

        const curY = tableY + 5
        for (let i = 0; i < infoPairs.length; i++) {
          const col = i < 3 ? 12 : pageW / 2 + 5
          const row = i < 3 ? i : i - 3
          doc.setFontSize(7)
          doc.setFont('helvetica', 'bold')
          doc.text(infoPairs[i][0], col, curY + row * 6)
          doc.setFont('helvetica', 'normal')
          doc.text(String(infoPairs[i][1]), col + 28, curY + row * 6)
        }

        const pdfBuf = Buffer.from(doc.output('arraybuffer'))
        const safeLR = (parcel.lr_number_proposed || parcel.parcel_number).replace(/[/\\]/g, '-')
        pdfBuffers.push({ filename: `Block${parcel.block_number}_${safeLR}_DeedPlan.pdf`, buffer: pdfBuf })
      } catch (err) {
        console.error(`Failed to generate deed plan for parcel ${parcel.id}:`, err)
      }
    }

    if (pdfBuffers.length === 0) {
      return NextResponse.json({ error: 'No deed plans could be generated' }, { status: 500 })
    }

    let zipBuffer: Buffer
    try {
      const JSZip = (await import('jszip')).default
      const zip = new JSZip()
      for (const pdf of pdfBuffers) { zip.file(pdf.filename, pdf.buffer) }
      zipBuffer = Buffer.from(await zip.generateAsync({ type: 'arraybuffer' }))
    } catch {
      return new NextResponse(new Blob([new Uint8Array(pdfBuffers[0].buffer)]), {
        status: 200,
        headers: {
          'Content-Type': 'application/pdf',
          'Content-Disposition': `attachment; filename="${pdfBuffers[0].filename}"`,
        },
      })
    }

    return new NextResponse(new Blob([new Uint8Array(zipBuffer)]), {
      status: 200,
      headers: {
        'Content-Type': 'application/zip',
        'Content-Disposition': `attachment; filename="DeedPlans_Project${projectId}_${pdfBuffers.length}parcels.zip"`,
      },
    })
  }
)

﻿import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { apiHandler } from '@/lib/apiHandler'
import { UpdateBlockSchema } from '@/lib/validation/apiSchemas'

export const dynamic = 'force-dynamic'

export const PATCH = apiHandler(
  {
    auth: true,
    schema: UpdateBlockSchema,
    optimisticLock: true,
    audit: 'block_updated',
    rateLimit: { max: 60, windowMs: 60000 },
    // P1-3 (2026-07-24): Scheme block updates are cadastral mutations.
    auditChain: {
      entityType: 'parcel',
      action: 'update',
      entityIdParam: 'id',
      reason: 'scheme block update',
    },
  },
  async (req, ctx) => {
    const blockId = ctx.params.id
    const validated = ctx.body as Record<string, unknown> & {
      block_number?: string; block_name?: string; description?: string; updated_at?: string
    }

    const check = await db.query(
      `SELECT b.id, b.project_id, b.updated_at FROM blocks b
      JOIN projects p ON p.id = b.project_id
      WHERE b.id = $1 AND p.user_id = $2`,
      [blockId, ctx.userId]
    )
    if (check.rows.length === 0) {
      return NextResponse.json({ error: 'Block not found' }, { status: 404 })
    }

    if (validated.block_number) {
      const dupCheck = await db.query(
        `SELECT id FROM blocks WHERE project_id = $1 AND block_number = $2 AND id != $3`,
        [check.rows[0].project_id, validated.block_number, blockId]
      )
      if (dupCheck.rows.length > 0) {
        return NextResponse.json({ error: `Block "${validated.block_number}" already exists` }, { status: 409 })
      }
    }

    const updates: string[] = []
    const values: any[] = []
    let paramIndex = 1

    if (validated.block_number !== undefined) {
      updates.push(`block_number = $${paramIndex++}`)
      values.push(validated.block_number)
    }
    if (validated.block_name !== undefined) {
      updates.push(`block_name = $${paramIndex++}`)
      values.push(validated.block_name || null)
    }
    if (validated.description !== undefined) {
      updates.push(`description = $${paramIndex++}`)
      values.push(validated.description || null)
    }

    if (updates.length === 0) {
      return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
    }

    updates.push(`updated_at = NOW()`)
    values.push(blockId)
    // T1.8 FIX (2026-07-09): Optimistic lock guard in the SQL WHERE clause.
    const clientUpdatedAt = validated.updated_at
    if (!clientUpdatedAt) {
      return NextResponse.json({ error: 'updated_at is required for optimistic locking', code: 'CONFLICT' }, { status: 409 })
    }
    values.push(clientUpdatedAt)
    const result = await db.query(
      `UPDATE blocks SET ${updates.join(', ')} WHERE id = $${paramIndex} AND updated_at = $${paramIndex + 1} RETURNING *`,
      values
    )

    if (result.rows.length === 0) {
      return NextResponse.json(
        { error: 'This block was modified by another user. Please refresh and try again.', code: 'CONFLICT' },
        { status: 409 }
      )
    }

    return NextResponse.json({ data: result.rows[0] })
  }
)

