    }

    let schemeDetails: Record<string, unknown> = {}
    try {
      const sd = await db.query('SELECT * FROM scheme_details WHERE project_id = $1', [parcel.project_id])
      if (sd.rows.length > 0) schemeDetails = sd.rows[0] as Record<string, unknown>
    } catch {}

