    const { renderBoundaryPlan } = await import('@/lib/generators/deedPlanRenderer')

    const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' })
    const pageW = doc.internal.pageSize.getWidth()
    const pageH = doc.internal.pageSize.getHeight()

    const stations = coordsResult.rows.map((c: Record<string, unknown>) => ({
      station: c.station as string,
      easting: parseFloat(String(c.easting)),
      northing: parseFloat(String(c.northing)),
      beaconNo: c.station as string,
      monument: 'psc found',
    }))

    const bearingSchedule: Array<{ bearing: string; distance: string }> = []
    for (let i = 0; i < stations.length; i++) {
      const from = stations[i]
      const to = stations[(i + 1) % stations.length]
      const dE = to.easting - from.easting
      const dN = to.northing - from.northing
      const dist = Math.sqrt(dE * dE + dN * dN)
      let wcbDeg = (Math.atan2(dE, dN) * 180 / Math.PI + 360) % 360
      const wcbD = Math.floor(wcbDeg)
      const wcbM = Math.floor((wcbDeg - wcbD) * 60)
      const wcbS = ((wcbDeg - wcbD) * 60 - wcbM) * 60
      bearingSchedule.push({
        bearing: `${String(wcbD).padStart(3, '0')}\u00B0${String(wcbM).padStart(2, '0')}'${wcbS.toFixed(1)}"`,
        distance: dist.toFixed(3),
      })
    }

    const geom = {
      stations, bearingSchedule,
      minE: Math.min(...stations.map((s) => s.easting)),
      maxE: Math.max(...stations.map((s) => s.easting)),
      minN: Math.min(...stations.map((s) => s.northing)),
      maxN: Math.max(...stations.map((s) => s.northing)),
    }

    doc.setFontSize(10)
    doc.setFont('helvetica', 'bold')
    doc.text('REPUBLIC OF KENYA', pageW / 2, 10, { align: 'center' })
    doc.setFontSize(9)
    doc.text('FORM NO. 4 \u2014 DEED PLAN', pageW / 2, 15, { align: 'center' })

    renderBoundaryPlan(doc, geom as any, { x: 10, y: 20, width: pageW - 20, height: pageH - 75 })

    const tableY = pageH - 52
    doc.setDrawColor(0)
    doc.setLineWidth(0.4)
    doc.rect(10, tableY, pageW - 20, 48)

    const col1X = 12
    const col2X = pageW / 2 + 5
    const rowH = 6
    const curY = tableY + 5

    const areaStr = parcel.area_ha
      ? `${parseFloat(parcel.area_ha).toFixed(4)} Ha`
      : traverse.computed_area_ha
        ? `${parseFloat(traverse.computed_area_ha).toFixed(4)} Ha`
        : '\u2014'

    const infoPairs = [
      ['PARCEL:', parcel.parcel_number],
      ['LR NO.:', parcel.lr_number_proposed || 'Pending'],
      ['AREA:', areaStr],
      ['BLOCK:', `${parcel.block_number} \u2014 ${parcel.block_name || 'N/A'}`],
      ['SCHEME:', schemeDetails.scheme_number || '\u2014'],
      ['LOCATION:', parcel.location || schemeDetails.county || '\u2014'],
      ['SURVEYOR:', parcel.surveyor_name || '\u2014'],
      ['ACCURACY:', traverse.accuracy_order || '\u2014'],
      ['PERIMETER:', traverse.total_perimeter ? `${parseFloat(traverse.total_perimeter).toFixed(3)} m` : '\u2014'],
      ['DATE:', new Date().toLocaleDateString('en-GB')],
      ['DATUM:', 'ARC 1960'],
      ['PROJECTION:', 'UTM Zone 37S'],
    ]

    for (let i = 0; i < infoPairs.length; i++) {
      const col = i < 6 ? col1X : col2X
      const row = i < 6 ? i : i - 6
      const y = curY + row * rowH
      doc.setFontSize(7)
      doc.setFont('helvetica', 'bold')
      doc.text(infoPairs[i][0], col, y)
      doc.setFont('helvetica', 'normal')
      doc.text(String(infoPairs[i][1]), col + 28, y)
    }

    const pdfBase64 = doc.output('datauristring').split(',')[1]

    return new NextResponse(
      Buffer.from(pdfBase64, 'base64'),
      {
        status: 200,
        headers: {
          'Content-Type': 'application/pdf',
          'Content-Disposition': `inline; filename="DeedPlan_${parcel.parcel_number}_${(parcel.lr_number_proposed || 'PENDING').replace(/\//g, '-')}.pdf"`,
        },
      }
    )
  }
)

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'

export const dynamic = 'force-dynamic'

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { searchParams } = new URL(req.url)
  const projectId = searchParams.get('project_id')
  if (!projectId) {
    return NextResponse.json({ error: 'project_id is required' }, { status: 400 })
  }

  // Fetch all parcels with coordinates
  const { rows: parcels } = await db.query(
    `SELECT p.parcel_number, p.lr_number_proposed, p.area_ha, p.status,
      b.block_number,
      tc.station_name, tc.easting, tc.northing, tc.elevation
     FROM parcels p
     JOIN blocks b ON b.id = p.block_id
     LEFT JOIN traverse_coordinates tc ON tc.traverse_id = (
       SELECT id FROM parcel_traverses WHERE parcel_id = p.id AND status IN ('computed', 'approved')
       ORDER BY computed_at DESC LIMIT 1
     )
     WHERE b.project_id = $1
     ORDER BY b.block_number, p.parcel_number`,
    [projectId]
  )

  // Group coordinates by parcel
  const parcelData = new Map<string, { info: any; coords: any[] }>()
  parcels.forEach((row: any) => {
    const key = `${row.block_number}-${row.parcel_number}`
    if (!parcelData.has(key)) {
      parcelData.set(key, {
        info: row,
        coords: [],
      })
    }
    if (row.easting !== null && row.northing !== null) {
      parcelData.get(key)!.coords.push({
        station: row.station_name,
        x: Number(row.easting),
        y: Number(row.northing),
        z: row.elevation ? Number(row.elevation) : 0,
      })
    }
  })

  // Generate DXF content
  const dxfLines: string[] = []

  // HEADER section
  dxfLines.push('0', 'SECTION', '2', 'HEADER')
  dxfLines.push('9', '$ACADVER', '1', 'AC1009') // AutoCAD R12
  dxfLines.push('9', '$INSUNITS', '70', '6') // Meters
  dxfLines.push('0', 'ENDSEC')

  // TABLES section with layers
  dxfLines.push('0', 'SECTION', '2', 'TABLES')
  dxfLines.push('0', 'TABLE', '2', 'LAYER', '70', String(parcelData.size + 3))

  // Define layers
  const layers = [
    { name: '0', color: 7 }, // White (default)
    { name: 'BOUNDARY', color: 1 }, // Red
    { name: 'POINTS', color: 3 }, // Green
    { name: 'TEXT', color: 7 }, // White
    ...Array.from(parcelData.entries()).map(([key, _]) => ({
      name: key.replace(/[^A-Za-z0-9_]/g, '_').substring(0, 31),
      color: 4, // Cyan
    }))
  ]

  layers.forEach(layer => {
    dxfLines.push('0', 'LAYER', '2', layer.name, '70', '0', '62', String(layer.color), '6', 'CONTINUOUS')
  })
  dxfLines.push('0', 'ENDTAB', '0', 'ENDSEC')

  // ENTITIES section
  dxfLines.push('0', 'SECTION', '2', 'ENTITIES')

  // Draw parcel boundaries
  parcelData.forEach((data, key) => {
    const coords = data.coords

    if (coords.length < 2) return

    // Draw boundary lines
    for (let i = 0; i < coords.length; i++) {
      const from = coords[i]
      const to = coords[(i + 1) % coords.length] // close polygon

      dxfLines.push('0', 'LINE', '8', 'BOUNDARY')
      dxfLines.push('10', String(from.x.toFixed(3)), '20', String(from.y.toFixed(3)), '30', '0')
      dxfLines.push('11', String(to.x.toFixed(3)), '21', String(to.y.toFixed(3)), '31', '0')
    }

    // Draw points
    coords.forEach(c => {
      dxfLines.push('0', 'POINT', '8', 'POINTS')
      dxfLines.push('10', String(c.x.toFixed(3)), '20', String(c.y.toFixed(3)), '30', String(c.z.toFixed(3)))
    })

    // Add parcel label at centroid
    if (coords.length > 0) {
      const cx = coords.reduce((s, c) => s + c.x, 0) / coords.length
      const cy = coords.reduce((s, c) => s + c.y, 0) / coords.length

      dxfLines.push('0', 'TEXT', '8', 'TEXT')
      dxfLines.push('10', String(cx.toFixed(3)), '20', String(cy.toFixed(3)), '30', '0')
      dxfLines.push('40', '5') // Text height 5m
      dxfLines.push('1', `${data.info.parcel_number}`)

      dxfLines.push('0', 'TEXT', '8', 'TEXT')
      dxfLines.push('10', String(cx.toFixed(3)), '20', String((cy - 8).toFixed(3)), '30', '0')
      dxfLines.push('40', '3') // Text height 3m
      dxfLines.push('1', `${data.info.area_ha ? Number(data.info.area_ha).toFixed(4) + ' ha' : ''}`)
    }
  })

  dxfLines.push('0', 'ENDSEC', '0', 'EOF')

  const dxfContent = dxfLines.join('\n')
  const project = await db.query('SELECT name, scheme_number FROM projects p LEFT JOIN scheme_details sd ON sd.project_id = p.id WHERE p.id = $1', [projectId])
  const fileName = `Scheme_${project.rows[0]?.scheme_number || project.rows[0]?.name || projectId}.dxf`

  return new NextResponse(dxfContent, {
    headers: {
      'Content-Type': 'application/dxf',
      'Content-Disposition': `attachment; filename="${fileName}"`,
    },
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'

export const dynamic = 'force-dynamic'

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { searchParams } = new URL(req.url)
  const projectId = searchParams.get('project_id')
  if (!projectId) {
    return NextResponse.json({ error: 'project_id is required' }, { status: 400 })
  }

  const { rows: parcels } = await db.query(
    `SELECT
      p.id, p.parcel_number, p.lr_number_proposed, p.area_ha, p.status,
      p.revision_number,
      b.id as block_id, b.block_number, b.block_name,
      pt.is_closed, pt.perimeter, pt.linear_error, pt.precision_ratio,
      pt.accuracy_order, pt.computed_area_ha,
      tc.station_name, tc.easting, tc.northing, tc.elevation
     FROM parcels p
     JOIN blocks b ON b.id = p.block_id
     LEFT JOIN parcel_traverses pt ON pt.parcel_id = p.id AND pt.status IN ('computed', 'approved')
     LEFT JOIN traverse_coordinates tc ON tc.traverse_id = pt.id
     WHERE b.project_id = $1
     ORDER BY b.block_number, p.parcel_number`,
    [projectId]
  )

  // Group by parcel
  const parcelMap = new Map<string, any>()
  parcels.forEach((row: any) => {
    if (!parcelMap.has(row.id)) {
      parcelMap.set(row.id, {
        ...row,
        coordinates: [],
      })
    }
    if (row.easting !== null && row.northing !== null) {
      parcelMap.get(row.id).coordinates.push({
        station: row.station_name,
        easting: Number(row.easting),
        northing: Number(row.northing),
        elevation: row.elevation ? Number(row.elevation) : null,
      })
    }
  })

  const features = Array.from(parcelMap.values()).map(p => {
    const coords = p.coordinates
    let geometry: any

    if (coords.length >= 3) {
      const ring = coords.map((c: any) => [c.easting, c.northing])
      ring.push(ring[0]) // close
      geometry = { type: 'Polygon', coordinates: [ring] }
    } else if (coords.length > 0) {
      geometry = { type: 'MultiPoint', coordinates: coords.map((c: any) => [c.easting, c.northing]) }
    } else {
      geometry = null
    }

    return {
      type: 'Feature',
      properties: {
        parcel_number: p.parcel_number,
        lr_number: p.lr_number_proposed,
        block_number: p.block_number,
        block_name: p.block_name,
        area_ha: p.computed_area_ha || p.area_ha,
        status: p.status,
        revision: p.revision_number,
        is_closed: p.is_closed,
        perimeter: p.perimeter,
        linear_error: p.linear_error,
        precision_ratio: p.precision_ratio,
        accuracy_order: p.accuracy_order,
        coordinate_count: coords.length,
      },
      geometry,
    }
  }).filter(f => f.geometry !== null)

  return NextResponse.json({
    type: 'FeatureCollection',
    features,
    name: 'metardu_scheme_export',
    crs: {
      type: 'name',
      properties: { name: 'urn:ogc:def:crs:EPSG::21037' }, // Arc 1960 / UTM Zone 37S (Kenya cadastral datum)
    },
  })
})

import { NextRequest, NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { jsPDF } from 'jspdf'

export const dynamic = 'force-dynamic'

export const GET = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const { searchParams } = new URL(req.url)
  const projectId = searchParams.get('project_id')

  if (!projectId) {
    return NextResponse.json({ error: 'project_id is required' }, { status: 400 })
  }

  // Fetch project and scheme details
  const { rows: projects } = await db.query(
    `SELECT p.*, sd.scheme_number, sd.county, sd.sub_county, sd.ward, 
            sd.adjudication_section, sd.planned_parcels
     FROM projects p
     LEFT JOIN scheme_details sd ON sd.project_id = p.id
     WHERE p.id = $1`,
    [projectId]
  )

  if (projects.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  const project = projects[0]
  const { rows: parcels } = await db.query(
    `SELECT p.*, b.block_number
     FROM parcels p
     JOIN blocks b ON b.id = p.block_id
     WHERE b.project_id = $1
     ORDER BY b.block_number, p.parcel_number`,
    [projectId]
  )

  // Generate Form No. 4 PDF
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a3' })
  const pageWidth = doc.internal.pageSize.getWidth()
  const pageHeight = doc.internal.pageSize.getHeight()
  const margin = 15

  // Title
  doc.setFontSize(16)
  doc.setFont('helvetica', 'bold')
  doc.text('FORM NO. 4 — SURVEY PLAN', pageWidth / 2, 25, { align: 'center' })
  doc.setFontSize(10)
  doc.setFont('helvetica', 'normal')
  doc.text('(Regulation 13(1) of the Survey Act, Cap 299)', pageWidth / 2, 32, { align: 'center' })

  // Scheme info table
  let y = 45
  doc.setFontSize(11)
  doc.setFont('helvetica', 'bold')
  doc.text('PARTICULARS OF THE SURVEY', margin, y)
  y += 8

  const info = [
    ['Scheme Number', project.scheme_number || '-'],
    ['County', project.county || '-'],
    ['Sub-County', project.sub_county || '-'],
    ['Ward', project.ward || '-'],
    ['Adjudication Section', project.adjudication_section || '-'],
    ['Total Parcels', String(project.planned_parcels || parcels.length)],
    ['Project Name', project.name],
    ['Survey Type', project.survey_type || '-'],
    ['Datum', project.datum || 'ARC 1960'],
    ['UTM Zone', `${project.utm_zone || '37S'}`],
  ]

  doc.setFontSize(9)
  info.forEach(([label, value]) => {
    doc.setFont('helvetica', 'bold')
    doc.text(`${label}:`, margin, y)
    doc.setFont('helvetica', 'normal')
    doc.text(value, margin + 60, y)
    y += 6
  })

  // Parcel summary table
  y += 5
  doc.setFontSize(11)
  doc.setFont('helvetica', 'bold')
  doc.text('PARCEL SUMMARY', margin, y)
  y += 8

  doc.setFontSize(8)
  const tableHeaders = ['Block', 'Parcel No.', 'LR No.', 'Area (ha)', 'Status']
  const colWidths = [25, 30, 40, 30, 30]
  let x = margin

  // Header row
  doc.setFillColor(50, 50, 50)
  doc.rect(x, y - 4, colWidths.reduce((a, b) => a + b, 0), 7, 'F')
  doc.setTextColor(255, 255, 255)
  doc.setFont('helvetica', 'bold')
  tableHeaders.forEach((h, i) => {
    doc.text(h, x + 2, y)
    x += colWidths[i]
  })
  doc.setTextColor(0, 0, 0)
  y += 7

  // Data rows
  doc.setFont('helvetica', 'normal')
  parcels.forEach((p: any) => {
    if (y > pageHeight - 30) {
      doc.addPage()
      y = 20
    }
    x = margin
    const row = [p.block_number, p.parcel_number, p.lr_number_proposed || '-', 
                 p.area_ha ? Number(p.area_ha).toFixed(4) : '-', p.status || 'pending']
    row.forEach((val, i) => {
      doc.text(String(val), x + 2, y)
      x += colWidths[i]
    })
    y += 5
  })

  // Certificate section
  y += 15
  if (y > pageHeight - 60) {
    doc.addPage()
    y = 20
  }

  doc.setFontSize(11)
  doc.setFont('helvetica', 'bold')
  doc.text('CERTIFICATE', margin, y)
  y += 10
  doc.setFontSize(9)
  doc.setFont('helvetica', 'normal')
  doc.text('I certify that the survey described above has been carried out by me in accordance', margin, y)
  y += 5
  doc.text('with the Survey Act (Cap 299) and the Regulations made thereunder, and that all', margin, y)
  y += 5
  doc.text('particulars shown on this plan are correct to the best of my knowledge and belief.', margin, y)

  y += 20
  doc.text('.....................................................', margin + 20, y)
  doc.text('.....................................................', margin + 180, y)
  y += 5
  doc.text('Licensed Surveyor', margin + 20, y)
  doc.text('Date', margin + 180, y)
  y += 5
  doc.text(`Name: ${ctx.session!.user.name || 'Surveyor'}`, margin + 20, y)
  y += 5
  doc.text(`ISK No: ${(ctx.session!.user as any).isk_number || '...................'}`, margin + 20, y)

  const pdfBuffer = Buffer.from(doc.output('arraybuffer'))
  return new NextResponse(pdfBuffer, {
    headers: {
      'Content-Type': 'application/pdf',
      'Content-Disposition': `attachment; filename="Form_4_${project.scheme_number || project.name}.pdf"`,
    },
  })
})

﻿import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { apiHandler } from '@/lib/apiHandler'

export const dynamic = 'force-dynamic'

export const POST = apiHandler(
  {
    auth: true, rawBody: true, audit: 'csv_import', rateLimit: { max: 60, windowMs: 60000 },
    // T1.9 FIX (2026-07-09): Add audit chain for bulk parcel imports.
    // Bulk imports can create/modify many parcels at once — needs tamper-evident logging.
    auditChain: {
      entityType: 'parcel',
      action: 'import',
      reason: 'Bulk CSV parcel import',
    },
  },
  async (req, ctx) => {
    const formData = await req.formData()
    const projectId = formData.get('project_id')
    const blockId = formData.get('block_id')
    const csvFile = formData.get('file') as File | null

    if (!projectId || !blockId) {
      return NextResponse.json({ error: 'project_id and block_id are required' }, { status: 400 })
    }

    if (!csvFile) {
      return NextResponse.json({ error: 'No CSV file provided' }, { status: 400 })
    }

    const check = await db.query(
      `SELECT b.id, b.project_id FROM blocks b
      JOIN projects p ON p.id = b.project_id
      WHERE b.id = $1 AND p.user_id = $2`,
      [blockId, ctx.userId]
    )
    if (check.rows.length === 0) {
      return NextResponse.json({ error: 'Block not found' }, { status: 404 })
    }

    const csvText = await csvFile.text()
    const lines = csvText.trim().split(/\r?\n/)
    if (lines.length < 2) {
      return NextResponse.json({ error: 'CSV file is empty or has no data rows' }, { status: 400 })
    }

    const headers = lines[0].split(',').map(h => h.trim().toLowerCase().replace(/"/g, ''))

    const findCol = (names: string[]): number => {
      for (const name of names) {
        const idx = headers.indexOf(name)
        if (idx >= 0) return idx
      }
      return -1
    }

    const parcelNumCol = findCol(['parcel_number', 'parcel', 'parcel_no', 'plot_number', 'plot_no', 'number'])
    const lrCol = findCol(['lr_number_proposed', 'lr_number', 'lr_no', 'lr_proposed', 'lr', 'proposed_lr'])
    const areaCol = findCol(['area_ha', 'area', 'size_ha', 'hectares'])
    const notesCol = findCol(['notes', 'description', 'remarks', 'comment'])

    if (parcelNumCol === -1) {
      return NextResponse.json({
        error: 'Missing required column "parcel_number". Expected headers: parcel_number, lr_number_proposed, area_ha, notes',
      }, { status: 400 })
    }

    const results = { created: 0, skipped: 0, errors: [] as string[] }
    const maxParcels = 500

    // Wrap all inserts/updates in a single transaction so partial failures
    // don't leave half-imported parcels. CSV import must be atomic.
    await db.transaction(async (client) => {
      for (let i = 1; i < lines.length && results.created < maxParcels; i++) {
        const line = lines[i].trim()
        if (!line) continue

        const values = line.split(',').map(v => v.trim().replace(/"/g, ''))
        if (values.length <= 1) continue

        const parcelNumber = values[parcelNumCol]?.trim()
        if (!parcelNumber) {
          results.skipped++
          results.errors.push(`Row ${i + 1}: empty parcel number`)
          continue
        }

        const lrNumber = lrCol >= 0 ? (values[lrCol]?.trim() || null) : null
        const areaHa = areaCol >= 0 ? (parseFloat(values[areaCol]) || null) : null
        const notes = notesCol >= 0 ? (values[notesCol]?.trim() || null) : null

        const dupCheck = await client.query(
          'SELECT id FROM parcels WHERE block_id = $1 AND parcel_number = $2',
          [blockId, parcelNumber]
        )

        if (dupCheck.rows.length > 0) {
          await client.query(
            `UPDATE parcels SET
              lr_number_proposed = $3, area_ha = $4, notes = $5, updated_at = NOW()
            WHERE block_id = $1 AND parcel_number = $2`,
            [blockId, parcelNumber, lrNumber, areaHa, notes]
          )
          results.skipped++
        } else {
          await client.query(
            `INSERT INTO parcels (project_id, block_id, parcel_number, lr_number_proposed, area_ha, status, notes)
            VALUES ($1, $2, $3, $4, $5, 'pending', $6)`,
            [parseInt(projectId as string), parseInt(blockId as string), parcelNumber, lrNumber, areaHa, notes]
          )
          results.created++
        }
      }
    })

    return NextResponse.json({
      data: {
        total_rows: lines.length - 1,
        created: results.created,
        skipped: results.skipped,
        errors: results.errors.slice(0, 20),
      },
    })
  }
)

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
