import { getActiveSurveyorProfile } from '@/lib/submission/surveyorProfile'
import { generateSubmissionRef } from '@/lib/submission/revisionNumber'

export async function GET(req: NextRequest) {
  const { session, error } = await requireAuth()
  if (error) return error

  try {
    const projectId = req.nextUrl.searchParams.get('projectId')
    if (!projectId) {
      return NextResponse.json({ error: 'projectId required' }, { status: 400 })
    }

    const surveyor = await getActiveSurveyorProfile()
    if (!surveyor) {
      // AUDIT FIX (H-010, 2026-07-27): the underlying helper throws on missing
      // profile; we caught it above (line 18-23 of surveyorProfile.ts). Return
      // a 404 with a helpful message instead of letting it bubble up as 500.
      return NextResponse.json(
        { error: 'Surveyor profile not found. Please complete your profile before generating a submission.', code: 'PROFILE_REQUIRED' },
        { status: 404 }
      )
    }

    // IDOR protection — verify project ownership before returning
    // full project data (survey points, traverse, parcel info)
    const userId = (session?.user as { id?: string })?.id
    const ownership = await requireProjectOwnership(projectId, userId)
    if (!ownership.ok) return ownership.error!

    const { rows: projectRows } = await db.query(
      'SELECT * FROM projects WHERE id = $1 LIMIT 1',
      [projectId]
    )

    if (projectRows.length === 0) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 })
    }

    const project = projectRows[0]

    // Simulate joined relations for survey_points (supporting_docs doesn't exist on projects table usually, mock if needed)
    const { rows: pointsRows } = await db.query(
      'SELECT * FROM survey_points WHERE project_id = $1',
      [projectId]
    )

    project.survey_points = pointsRows
    project.supporting_documents = [] // Fallback since it's not a standard table

    const { ref, revision } = await generateSubmissionRef(
      projectId,
      surveyor.registration_number
    )

    const pkg = {
      submissionRef: ref,
      projectId,
      surveyor,
      subtype: project.survey_type || 'cadastral_subdivision',
      parcel: {
        lrNumber: project.lr_number || '',
        county: project.county || '',
        district: project.district || '',
        locality: project.locality || '',
        areaM2: project.area_m2 || 0,
        perimeterM: project.perimeter_m || 0
      },
      traverse: {
        points: (project.survey_points || []).map((pt: any) => ({
          pointName: pt.name || `P${pt.id}`,
          easting: pt.easting || 0,
          northing: pt.northing || 0,
          adjustedEasting: pt.adjusted_easting || pt.easting || 0,
          adjustedNorthing: pt.adjusted_northing || pt.northing || 0,
          observedBearing: pt.observed_bearing || 0,
          observedDistance: pt.observed_distance || 0
        })),
        angularMisclosure: project.angular_misclosure || 0,
        linearMisclosure: project.linear_misclosure || 0,
        precisionRatio: project.precision_ratio || '1:1',
        closingErrorE: project.closing_error_e || 0,
        closingErrorN: project.closing_error_n || 0,
        adjustmentMethod: 'bowditch',
        areaM2: project.area_m2 || 0,
        perimeterM: project.perimeter_m || 0
      },
      supportingDocs: project.supporting_documents || [],
      generatedAt: new Date().toISOString(),
      revision
    }

    return NextResponse.json(pkg)
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Server error'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

export const dynamic = 'force-dynamic'

/**
 * POST /api/submission/sequence
 * Atomically increments the submission sequence number for a surveyor/year pair.
 * Uses direct PostgreSQL with advisory lock instead of DbClient RPC.
 */

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (req, ctx) => {
  const body = ctx.body as { surveyorProfileId?: string; year?: number } | null

  if (!body?.surveyorProfileId || !body.year) {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 })
  }

  const { surveyorProfileId, year } = body

  // Atomic upsert — INSERT with ON CONFLICT to atomically increment
  const { rows } = await db.query(
    `INSERT INTO submission_sequences (surveyor_profile_id, year, current_sequence)
     VALUES ($1, $2, 1)
     ON CONFLICT (surveyor_profile_id, year)
     DO UPDATE SET current_sequence = submission_sequences.current_sequence + 1
     RETURNING current_sequence`,
    [surveyorProfileId, year]
  )

  const sequence = rows[0]?.current_sequence ?? 1
  const referenceNumber = `ISK_${year}_${String(sequence).padStart(3, '0')}_R00`

  return NextResponse.json({
    sequence,
    reference_number: referenceNumber,
    revision: 0,
    year
  })
})

/**
 * /api/submissions/create
 *
 * POST — Create a new submission record for a project.
 *
 * AUDIT FIX (2026-07-03): The documents page (src/app/project/[id]/
 * documents/page.tsx) calls `/api/submissions/create` (plural) with
 * body `{ projectId }` and expects `{ success, submissionNumber }`.
 * Only `/api/submission/generate` (singular, different shape) existed.
 *
 * This route creates a row in the `submissions` table and returns
 * a human-readable submission number (format: SUB-YYYY-NNNNN) that
 * the UI displays to the surveyor.
 *
 * Body:  { projectId: string (UUID) }
 * Response (201): { success: true, submissionNumber: string, submissionId: string }
 */

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { z } from 'zod'
import { apiHandler } from '@/lib/apiHandler'
import db from '@/lib/db'

const CreateSubmissionSchema = z.object({
  projectId: z.string().uuid(),
})

export const POST = apiHandler(
  {
    auth: true,
    schema: CreateSubmissionSchema,
    rateLimit: { max: 30, windowMs: 60000 },
    // T1.9 FIX (2026-07-09): Add audit chain for submission creation.
    auditChain: {
      entityType: 'document',
      action: 'submit',
      projectIdFromBody: 'projectId',
      reason: 'Submission created',
    },
  },
  async (_req, ctx) => {
    const { projectId } = ctx.body as z.infer<typeof CreateSubmissionSchema>

    // ── Verify project exists + user owns it ───────────────────────────────
    const { rows: projectRows } = await db.query(
      'SELECT id, survey_type FROM projects WHERE id = $1 AND user_id = $2',
      [projectId, ctx.userId],
    )
    if (projectRows.length === 0) {
      return NextResponse.json(
        { error: 'Project not found or access denied', code: 'NOT_FOUND' },
        { status: 404 },
      )
    }

    const project = projectRows[0] as { id: string; survey_type: string }

    // ── Generate a sequential submission number for the current year ───────
    // Format: SUB-YYYY-NNNNN  (zero-padded sequence within the year)
    const year = new Date().getFullYear()
    const { rows: seqRows } = await db.query(
      `SELECT COUNT(*)::int AS count
         FROM submissions
        WHERE project_id = $1
          AND EXTRACT(YEAR FROM created_at) = $2`,
      [projectId, year],
    )
    const seq = (seqRows[0]?.count ?? 0) + 1
    const submissionNumber = `SUB-${year}-${String(seq).padStart(5, '0')}`

    // ── Insert the submissions row ─────────────────────────────────────────
    const { rows: insertRows } = await db.query(
      `INSERT INTO submissions (project_id, submission_type, status)
       VALUES ($1, $2, 'draft')
       RETURNING id, created_at`,
      [projectId, project.survey_type || 'cadastral'],
    )

    if (insertRows.length === 0) {
      return NextResponse.json(
        { error: 'Failed to create submission', code: 'INSERT_FAILED' },
        { status: 500 },
      )
    }

    const submissionId = insertRows[0].id as string

    return NextResponse.json(
      {
        success: true,
        submissionId,
        submissionNumber,
        createdAt: insertRows[0].created_at,
      },
      { status: 201 },
    )
  },
)

import { NextResponse } from 'next/server'
