    // Step 2: Build traverse legs from processed observations
    const legs: TraverseLeg[] = processedObservations.map(obs => ({
      fromStation: obs.fromStation,
      toStation: obs.toStation,
      bearing: obs.gridBearing ?? obs.trueBearing ?? 0,
      distance: obs.gridDistance,
      stdDevDistance: 0.005 + obs.gridDistance * 0.00002, // 5mm + 20ppm
      stdDevBearing: 5, // 5 arc-seconds
    }))

    // Step 3: Perform traverse adjustment
    let result;

    if (method === 'bowditch') {
      result = bowditchAdjustment(stations as TraverseStation[], legs, order)
    } else {
      // Build least squares inputs from processed observations
      const lsStations: LSStation[] = stations.map(s => ({
        name: s.name,
        easting: s.easting ?? 0,
        northing: s.northing ?? 0,
        isFixed: s.isFixed ?? false,
      }))

      const lsObservations: LSObservation[] = processedObservations.map(obs => ({
        type: 'distance' as const,
        fromStation: obs.fromStation,
        toStation: obs.toStation,
        value: obs.gridDistance,
        stdDev: 0.005 + obs.gridDistance * 0.00002, // 5mm + 20ppm
      }))

      result = leastSquaresAdjustment(lsStations, lsObservations)
    }

    return NextResponse.json({
      processedObservations,
      adjustmentResult: result,
      pipelineConfig,
      correctionsApplied: processedObservations.map(obs => ({
        from: obs.fromStation,
        to: obs.toStation,
        rawDistance: obs.rawSlopeDistance,
        gridDistance: obs.gridDistance,
        atmosphericPPM: obs.atmosphericPPM,
        seaLevelPPM: obs.seaLevelPPM,
        lineScaleFactor: obs.lineScaleFactor,
        convergence: obs.convergence,
        warnings: obs.warnings,
      })),
    })
  } catch (error) {
    console.error('Traverse computation error:', error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Computation failed' },
      { status: 500 }
    );
  }
}

export const dynamic = 'force-dynamic'

/**
 * Field Data Sync API Route
 *
 * Handles batch upload of observations collected offline in the field.
 * Surveyors work all day offline (IndexedDB), then sync at end of day.
 *
 * SECURITY (audit C2, fixed 2026-07-02):
 *   Previously this route accepted `surveyorId` and `surveyorName` from
 *   the request body and wrote them to the audit log without verifying
 *   the session. Any authenticated user could impersonate any surveyor.
 *   Now the route uses `getServerSession` to derive the user identity
 *   from the JWT, ignoring any client-supplied surveyorId/surveyorName.
 *
 * RESOLVED (audit H1, fixed 2026-07-02): The previous TODO noted that
 *   this route used Prisma models (Survey, Observation) that didn't
 *   match the actual SQL schema. That has been fixed — the route now
 *   queries the real `projects` table via raw SQL (see line ~57). The
 *   Prisma client was deleted on 2026-07-05 because it had 0 importers.
 *
 * REMAINING WORK: The `observations` payload from the client is still
 *   shape-compatible with the old Prisma Observation model, which doesn't
 *   match the real `traverse_observations` / `level_observations` tables.
 *   The batchCreateObservations() helper in src/lib/db/queries/observations.ts
 *   is responsible for routing each observation to the correct table.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { batchCreateObservations, getObservations } from '@/lib/db/queries/observations'
import { createAuditLog } from '@/lib/db/queries/audit'
import { db } from '@/lib/db'
import { FieldSyncSchema } from '@/lib/validation/apiSchemas'
import { appendAuditEntry } from '@/lib/audit/auditLog'

export async function POST(request: NextRequest) {
  // ── Auth: derive identity from session, never from body ───────────────
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json(
      { error: 'Authentication required' },
      { status: 401 }
    )
  }
  const userId = session.user.id
  const userName = (session.user as { name?: string }).name ?? session.user.email ?? 'Unknown'

  try {
    const rawBody = await request.json().catch(() => null)
    const parsed = FieldSyncSchema.safeParse(rawBody)
    if (!parsed.success) {
      return NextResponse.json(
        { error: 'Validation failed', details: parsed.error.issues },
        { status: 422 }
      )
    }

    // surveyorId/surveyorName from body are IGNORED — identity comes from session.
    const { surveyId, observations } = parsed.data

    // AUDIT FIX (H1, 2026-07-02): Replaced prisma.survey.findUnique with
    // raw SQL against the real `projects` table. The Prisma `Survey`
    // model never existed in the SQL schema. `surveyId` is treated as
    // a project ID (the caller's convention).
    const surveyResult = await db.query(
      `SELECT id, user_id, organization_id FROM projects WHERE id = $1`,
      [surveyId]
    )

    if (surveyResult.rows.length === 0) {
      return NextResponse.json(
        { error: 'Project not found' },
        { status: 404 }
      )
    }

    const project = surveyResult.rows[0]
    // Ownership check: the session user must own the project OR be a
    // member of the project's organization.
    if (project.user_id && project.user_id !== userId) {
      // Check org membership if the project belongs to an org
      if (project.organization_id) {
        const orgMemberResult = await db.query(
          `SELECT 1 FROM organization_members
           WHERE user_id = $1 AND organization_id = $2 AND is_active = TRUE`,
          [userId, project.organization_id]
        )
        if (orgMemberResult.rows.length === 0) {
          return NextResponse.json(
            { error: 'Forbidden: project belongs to another user' },
            { status: 403 }
          )
        }
      } else {
        return NextResponse.json(
          { error: 'Forbidden: project belongs to another user' },
          { status: 403 }
        )
      }
    }

    // Batch create all observations
    const result = await batchCreateObservations({
      surveyId,
      observations: observations.map(obs => ({
        surveyId,
        fromStationId: obs.fromStationId,
        toStationId: obs.toStationId,
        rawHorizontalAngle: obs.rawHorizontalAngle,
        rawVerticalAngle: obs.rawVerticalAngle,
        rawSlopeDistance: obs.rawSlopeDistance,
        edmConstant: obs.edmConstant,
        ppmSetting: obs.ppmSetting,
        temperature: obs.temperature,
        pressure: obs.pressure,
        humidity: obs.humidity,
        instrumentHeight: obs.instrumentHeight,
        targetHeight: obs.targetHeight,
        observationDate: obs.observationDate ? new Date(obs.observationDate) : undefined,
      })),
    })

    // Audit log — identity from session, never from body
    await createAuditLog({
      entityType: 'Survey',
      entityId: surveyId,
      action: 'SYNC_OBSERVATIONS',
      userId,
      userName,
      changes: JSON.stringify({ count: observations.length }),
    })

    // Tamper-evident audit chain (audit C3 — wire into more routes)
    try {
      await appendAuditEntry({
        projectId: surveyId,
        userId,
        entityType: 'custom',
        entityId: surveyId,
        action: 'import',
        payload: {
          metadata: {
            operation: 'SYNC_OBSERVATIONS',
            count: observations.length,
            syncedAt: new Date().toISOString(),
          },
        },
      })
    } catch {
      // Audit chain failure should NOT block the sync — log and continue.
      console.warn('[sync] appendAuditEntry failed — chain integrity check recommended')
    }

    return NextResponse.json({
      success: true,
      count: result.count,
      message: `Synced ${result.count} observations`,
    })
  } catch (error) {
    console.error('Sync error:', error)
    return NextResponse.json(
      { error: error instanceof Error ? error.message : 'Sync failed' },
      { status: 500 }
    )
  }
}

/**
 * GET: Retrieve synced observations for a survey.
 * Used by the client to verify what was synced.
 */
export async function GET(request: NextRequest) {
  // ── Auth: same fix as POST ────────────────────────────────────────────
  const session = await getServerSession(authOptions)
  if (!session?.user?.id) {
    return NextResponse.json(
      { error: 'Authentication required' },
      { status: 401 }
    )
  }

  try {
    const { searchParams } = new URL(request.url)
    const surveyId = searchParams.get('surveyId')

    if (!surveyId) {
      return NextResponse.json({ error: 'surveyId required' }, { status: 400 })
    }

    const observations = await getObservations(surveyId)

    return NextResponse.json({ observations, count: observations.length })
  } catch (error) {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { db, setCurrentUserId } from '@/lib/db'
import { generateStatutoryWorkbook, type WorkbookInput } from '@/lib/submission/workbook/statutoryWorkbook'
import { StatutoryWorkbookSchema } from '@/lib/validation/apiSchemas'

interface RequestBody {
  projectId?: string
  projectName?: string
  lrNumber?: string
  parcelNumber?: string
  county?: string
  locality?: string
  surveyType?: WorkbookInput['project']['surveyType']
  surveyDate?: string
  surveyorName?: string
  iskNumber?: string
  firmName?: string
  referenceNumber?: string
}

/**
 * AUDIT FIX (2026-07-03): Previously this route used hardcoded sample data
 * (stations A, B, C, D with fake coordinates and traverse observations).
 * Now, when `projectId` is provided, it loads real project data from the DB:
 *   - Project details (name, lr_number, locality, survey_type, etc.)
 *   - Survey points (as traverse stations)
 *   - Traverse observations (bearing + distance legs)
 *   - Surveyor profile (name, ISK number, firm)
 *
 * When `projectId` is NOT provided, falls back to the sample data (clearly
 * marked as SAMPLE in the project name) so the tool remains usable as a demo.
 */
async function buildWorkbookInput(body: RequestBody, userId: string): Promise<WorkbookInput> {
  const surveyDate = body.surveyDate || new Date().toISOString().slice(0, 10)

  // If projectId is provided, load real data from the database
  if (body.projectId) {
    try {
      // Load project
      const { rows: projRows } = await db.query(
        `SELECT id, name, lr_number, locality, survey_type, datum, utm_zone,
                hemisphere, client_name, surveyor_name, surveyor_licence,
                firm_name, area_ha
         FROM projects WHERE id = $1 AND user_id = $2`,
        [body.projectId, userId]
      )

      if (projRows.length === 0) {
        throw new Error('Project not found or access denied')
      }

      const proj = projRows[0]

      // Load survey points as traverse stations
      const { rows: pointRows } = await db.query(
        `SELECT point_name, easting, northing, elevation, code
         FROM survey_points
         WHERE project_id = $1 AND easting IS NOT NULL AND northing IS NOT NULL
         ORDER BY point_name ASC`,
        [body.projectId]
      )

      // Load traverse observations
      const { rows: obsRows } = await db.query(
        `SELECT station_from, station_to, bearing, distance
         FROM traverse_observations obs
         JOIN parcel_traverses pt ON pt.id = obs.traverse_id
         WHERE pt.project_id = $1
         ORDER BY obs.id`,
        [body.projectId]
      )

      // Load surveyor profile
      const { rows: profileRows } = await db.query(
        `SELECT full_name, isk_number, firm_name FROM surveyor_profiles WHERE user_id = $1`,
        [userId]
      )
      const profile = profileRows[0]

      // Build stations from survey points
      const stations = pointRows.map((p: Record<string, unknown>) => ({
        label: String(p.point_name || ''),
        easting: parseFloat(String(p.easting)),
        northing: parseFloat(String(p.northing)),
        elevation: p.elevation ? parseFloat(String(p.elevation)) : undefined,
      }))

      // Build field observations from traverse_observations
      const fieldObs = obsRows.map((o: Record<string, unknown>) => ({
        stationFrom: String(o.station_from || ''),
        stationTo: String(o.station_to || ''),
        observedBearingDeg: parseFloat(String(o.bearing || 0)),
        observedDistanceM: parseFloat(String(o.distance || 0)),
        reducedLevelM: 0,
        remarks: 'Traverse leg',
      }))

      // Build legs from observations
      const legs = fieldObs.map(o => ({
        fromLabel: o.stationFrom,
        toLabel: o.stationTo,
        bearing: o.observedBearingDeg,
        distance: o.observedDistanceM,
      }))

      // Compute area via shoelace if we have ≥3 stations
      let areaM2 = 0
      let perimeterM = 0
      if (stations.length >= 3) {
        for (let i = 0; i < stations.length; i++) {
          const j = (i + 1) % stations.length
          areaM2 += stations[i].easting * stations[j].northing
          areaM2 -= stations[j].easting * stations[i].northing
          const dx = stations[j].easting - stations[i].easting
          const dy = stations[j].northing - stations[i].northing
          perimeterM += Math.sqrt(dx * dx + dy * dy)
        }
        areaM2 = Math.abs(areaM2 / 2)
      }

      return {
        project: {
          name: body.projectName || proj.name,
          lrNumber: body.lrNumber || proj.lr_number || '',
          parcelNumber: body.parcelNumber || '',
          county: body.county || '',
          division: '',
          district: '',
          locality: body.locality || proj.locality || '',
          surveyType: body.surveyType || (proj.survey_type as WorkbookInput['project']['surveyType']) || 'cadastral',
          surveyDate,
          scaleDenominator: 1000,
        },
        surveyor: {
          name: body.surveyorName || proj.surveyor_name || profile?.full_name || '',
          iskNumber: body.iskNumber || proj.surveyor_licence || profile?.isk_number || '',
          firmName: body.firmName || proj.firm_name || profile?.firm_name || '',
        },
        submission: {
          referenceNumber: body.referenceNumber || `MET-WB-${surveyDate.replace(/-/g, '')}`,
          revision: 0,
          status: 'DRAFT',
        },
        fieldObservations: fieldObs.length > 0 ? fieldObs : [],
        traverse: {
          method: 'bowditch',
          stations: [],
          angularMisclosureSec: 0,
          angularToleranceSec: 30,
          angularPassesQA: true,
          linearMisclosureM: 0,
          perimeterM,
          precisionRatio: perimeterM > 0 ? perimeterM / 0.001 : 0,
          precisionMinimum: 5000,
          linearPassesQA: true,
        },
        adjustedStations: stations,
        levelling: [],
        levellingClosureMM: 0,
        levellingToleranceMM: 10,
        levellingDistanceKm: 0,
        areaComputation: {
          stations: stations.map(s => ({ label: s.label, easting: s.easting, northing: s.northing })),
          areaM2,
          areaHa: areaM2 / 10000,
          perimeterM,
        },
        legs,
        cogoResults: [
          { type: 'Area', description: 'Coordinate area by shoelace method', inputs: { stations: stations.length }, outputs: { areaHa: areaM2 / 10000, perimeterM } },
        ],
      }
    } catch (err) {
      console.warn('[statutory-workbook] Failed to load project data, falling back to sample:', err)
      // Fall through to sample data
    }
  }

  // ── Sample data fallback (clearly marked) ──────────────────────────────
  const sampleStations = [
    { label: 'A', easting: 250000.000, northing: 9950000.000, elevation: 1560.125 },
    { label: 'B', easting: 250124.375, northing: 9950048.220, elevation: 1561.084 },
    { label: 'C', easting: 250185.640, northing: 9949925.730, elevation: 1559.862 },
    { label: 'D', easting: 250042.810, northing: 9949878.440, elevation: 1560.006 },
  ]

  return {
    project: {
      name: body.projectName || 'METARDU Sample Workbook (no project selected)',
      lrNumber: body.lrNumber || '',
      parcelNumber: body.parcelNumber || '',
      county: body.county || '',
      division: '',
      district: '',
      locality: body.locality || '',
      surveyType: body.surveyType || 'cadastral',
      surveyDate,
      scaleDenominator: 1000,
    },
    surveyor: {
      name: body.surveyorName || '',
      iskNumber: body.iskNumber || '',
      firmName: body.firmName || '',
    },
    submission: {
      referenceNumber: body.referenceNumber || `MET-WB-${surveyDate.replace(/-/g, '')}`,
      revision: 0,
      status: 'DRAFT',
    },
    fieldObservations: [
      { stationFrom: 'A', stationTo: 'B', observedBearingDeg: 68.8056, observedDistanceM: 133.381, reducedLevelM: 1561.084, remarks: 'Sample traverse leg' },
      { stationFrom: 'B', stationTo: 'C', observedBearingDeg: 153.4349, observedDistanceM: 136.977, reducedLevelM: 1559.862, remarks: 'Sample traverse leg' },
      { stationFrom: 'C', stationTo: 'D', observedBearingDeg: 251.6914, observedDistanceM: 150.457, reducedLevelM: 1560.006, remarks: 'Sample traverse leg' },
      { stationFrom: 'D', stationTo: 'A', observedBearingDeg: 343.8851, observedDistanceM: 126.437, reducedLevelM: 1560.125, remarks: 'Sample closing leg' },
    ],
    traverse: {
      method: 'bowditch',
      stations: [],
      angularMisclosureSec: 8,
      angularToleranceSec: 30,
      angularPassesQA: true,
      linearMisclosureM: 0.018,
      perimeterM: 547.252,
      precisionRatio: 30402,
      precisionMinimum: 5000,
      linearPassesQA: true,
    },
    adjustedStations: sampleStations,
    levelling: [],
    levellingClosureMM: 4,
    levellingToleranceMM: 10,
    levellingDistanceKm: 1,
    areaComputation: {
      stations: sampleStations.map(({ label, easting, northing }) => ({ label, easting, northing })),
      areaM2: 18148.07,
      areaHa: 1.8148,
      perimeterM: 547.252,
    },
    legs: [],
    cogoResults: [],
  }
}

export async function POST(request: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user) {
    return NextResponse.json({ error: 'Authentication required', code: 'UNAUTHORIZED' }, { status: 401 })
  }
  const userId = (session.user as { id?: string }).id
  if (userId) setCurrentUserId(String(userId))

  const rawBody = await request.json().catch(() => null)
  const parsed = StatutoryWorkbookSchema.safeParse(rawBody)
  if (!parsed.success) {
    return NextResponse.json(
      { error: 'Validation failed', details: parsed.error.issues },
      { status: 422 }
    )
  }

  const body = parsed.data as unknown as RequestBody
  const input = await buildWorkbookInput(body, String(userId))
  const workbook = await generateStatutoryWorkbook(input)
  return new NextResponse(new Uint8Array(workbook), {
    headers: {
      'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'Content-Disposition': 'attachment; filename="metardu-statutory-workbook.xlsx"',
    },
  })
}

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { setCurrentUserId } from '@/lib/db'
import Drawing from 'dxf-writer'
import {
  initialiseSokDXFLayers,
  DXF_LAYERS
} from '@/lib/drawing/dxfLayers'
import type { ContourLine } from '@/lib/topo/contourGenerator'

export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user) {
    return NextResponse.json({ error: 'Authentication required', code: 'UNAUTHORIZED' }, { status: 401 })
  }
  const userId = (session.user as any).id
  if (userId) setCurrentUserId(String(userId))

  try {
    const { projectId, contours, spotHeights } = await req.json()

    const drawing = new Drawing()
    initialiseSokDXFLayers(drawing)

    contours.forEach((contour: ContourLine) => {
      const layerName = contour.isIndex
        ? DXF_LAYERS.CONTOUR_I.name
        : DXF_LAYERS.CONTOURS.name

      drawing.setActiveLayer(layerName)

      contour.coordinates.forEach((ring: [number, number][]) => {
        for (let i = 0; i < ring.length - 1; i++) {
          drawing.drawLine(ring[i][0], ring[i][1], ring[i + 1][0], ring[i + 1][1])
        }
        if (ring.length > 1) {
          drawing.drawLine(ring[ring.length - 1][0], ring[ring.length - 1][1], ring[0][0], ring[0][1])
        }

        if (contour.isIndex && ring.length > 4) {
          const mid = ring[Math.floor(ring.length / 4)]
          drawing.drawText(mid[0], mid[1], 0.5, 0, `${contour.elevation.toFixed(1)}`)
        }
      })
    })

    drawing.setActiveLayer(DXF_LAYERS.SPOT.name)
    spotHeights.forEach((pt: { e: number; n: number; z: number; label?: string }) => {
      drawing.drawCircle(pt.e, pt.n, 0.2)
      drawing.drawText(pt.e + 0.3, pt.n + 0.3, 0.4, 0, pt.z.toFixed(2))
    })

    const dxfString = drawing.toDxfString()

    return new NextResponse(dxfString, {
      headers: {
        'Content-Type': 'application/dxf',
        'Content-Disposition': `attachment; filename="topo_${projectId}.dxf"`
      }
    })
  } catch (error) {
    return NextResponse.json({ error: 'DXF generation failed' }, { status: 500 })
  }
}

export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { setCurrentUserId } from '@/lib/db'
import type { ContourLine } from '@/lib/topo/contourGenerator'

interface SpotHeightInput {
  e: number
  n: number
  z: number
  label?: string
}

export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions)
  if (!session?.user) {
    return NextResponse.json({ error: 'Authentication required', code: 'UNAUTHORIZED' }, { status: 401 })
  }
  const userId = (session.user as any).id
  if (userId) setCurrentUserId(String(userId))

  try {
    const { contours, spotHeights, projectId } = await req.json() as {
      contours: ContourLine[]
      spotHeights: SpotHeightInput[]
      projectId?: string
    }

    const contourFeatures = contours.flatMap((contour) =>
      contour.coordinates.map((ring) => ({
        type: 'Feature' as const,
        properties: {
          ELEVATION: contour.elevation,
          IS_INDEX: contour.isIndex ? 1 : 0,
        },
        geometry: {
          type: 'LineString' as const,
          coordinates: ring,
        },
      }))
    )

    const spotFeatures = spotHeights.map((pt) => ({
      type: 'Feature' as const,
      properties: {
        ELEVATION: pt.z,
        LABEL: pt.label ?? '',
      },
      geometry: {
        type: 'Point' as const,
        coordinates: [pt.e, pt.n],
      },
    }))

    const geojson = {
      type: 'FeatureCollection' as const,
      features: [...contourFeatures, ...spotFeatures],
    }

    const shpwriteModule = await import('shp-write')
    const shpwrite = (shpwriteModule as any).default ?? shpwriteModule

    if (typeof shpwrite.zip !== 'function') {
      throw new Error('shp-write zip() is unavailable')
    }

    const zipResult = await shpwrite.zip(geojson, {
      folder: `contours_${projectId ?? 'export'}`,
      types: {
        point: 'spot_heights',
        line: 'contours',
        polygon: 'polygons',
      },
    })

    const zipBuffer = Buffer.isBuffer(zipResult)
      ? zipResult
      : Buffer.from(zipResult)

    return new NextResponse(zipBuffer, {
      headers: {
        'Content-Type': 'application/zip',
        'Content-Disposition': `attachment; filename="contours_${projectId ?? 'export'}.zip"`,
      },
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Shapefile generation failed'
    console.error('Shapefile export error:', message)
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (request, ctx) => {
  const { projectId, points } = ctx.body as {
    projectId?: string
    points?: Array<{ easting: number; northing: number; elevation: number; name?: string }>
  }

  if (!projectId || !points || !Array.isArray(points)) {
    return NextResponse.json({ error: 'Invalid request: projectId and points array required' }, { status: 400 })
  }

  const { rows: projectRows } = await db.query(
    'SELECT id FROM projects WHERE id = $1 AND user_id = $2 LIMIT 1',
    [projectId, ctx.userId]
  )

  if (projectRows.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  const validPoints = points
    .filter((p) =>
      typeof p.easting === 'number' &&
      typeof p.northing === 'number' &&
      typeof p.elevation === 'number'
    )

  if (validPoints.length === 0) {
    return NextResponse.json({ error: 'No valid points provided' }, { status: 400 })
  }

  // Bulk import — wrap all inserts in a single transaction so partial
  // failures don't leave orphan survey points in the database.
  // (DB best practice: multi-row writes must be atomic.)
  const inserted: any[] = []
  await db.transaction(async (client) => {
    for (const p of validPoints) {
      try {
        const { rows } = await client.query(
          `INSERT INTO survey_points (project_id, point_type, easting, northing, elevation, name, created_by)
           VALUES ($1, $2, $3, $4, $5, $6, $7)
           ON CONFLICT (project_id, point_type, name) DO UPDATE
           SET easting = EXCLUDED.easting, northing = EXCLUDED.northing, elevation = EXCLUDED.elevation
           RETURNING *`,
          [projectId, 'spot_height', p.easting, p.northing, p.elevation, p.name || null, ctx.userId]
        )
        if (rows[0]) inserted.push(rows[0])
      } catch (err: unknown) {
        // Fallback for init-test-db schema which might use point_name and lack point_type/created_by
        if ((err as Error).message && (err as Error).message.includes('column "point_type" of relation "survey_points" does not exist')) {
          const { rows } = await client.query(
            `INSERT INTO survey_points (project_id, easting, northing, elevation, point_name)
             VALUES ($1, $2, $3, $4, $5)
             RETURNING *`,
            [projectId, p.easting, p.northing, p.elevation, p.name || null]
          )
          if (rows[0]) inserted.push(rows[0])
        } else {
          throw err
        }
      }
    }
  })

  return NextResponse.json({
    success: true,
    imported: inserted.length,
    points: inserted
  })
})

