  const [success, setSuccess] = useState(false)

  const strength = getPasswordStrength(password)

  useEffect(() => {
    document.title = 'Reset Password - METARDU'
    const t = searchParams.get('token') || searchParams.get('code') || ''
    setToken(t)
  }, [searchParams])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')

    if (password.length < 8) {
      setError('Password must be at least 8 characters')
      return
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match')
      return
    }
    if (!token) {
      setError('Invalid reset link. Request a new one from login.')
      return
    }

    setLoading(true)
    try {
      const res = await fetch('/api/auth/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, password }),
      })
      const json = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(json.error || 'Password update failed. Your reset link may have expired.')
        setLoading(false)
        return
      }
    } catch {
      setError('Password update failed. Please try again.')
      setLoading(false)
      return
    }

    setSuccess(true)
    setTimeout(() => router.push('/login'), 2000)
  }

  if (!token) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center p-8">
        <div className="max-w-md w-full text-center">
          <XCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Invalid reset link</h2>
          <p className="text-[var(--text-secondary)] mb-6">This link is invalid or has expired.</p>
          <a href="/login" className="text-[var(--accent)] hover:underline">Request a new reset link</a>
        </div>
      </div>
    )
  }

  if (success) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center p-8">
        <div className="max-w-md w-full text-center">
          <CheckCircle2 className="w-16 h-16 text-green-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Password updated</h2>
          <p className="text-[var(--text-secondary)]">Redirecting to login...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center p-8">
      <div className="max-w-md w-full">
        <a href="/" className="text-2xl font-bold text-[var(--accent)] block mb-8">METARDU</a>
        <h2 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Set new password</h2>
        <p className="text-[var(--text-secondary)] mb-8">Choose a strong password for your account.</p>

        <form onSubmit={handleSubmit} className="space-y-5">
          {error && (
            <div className="p-3 bg-red-900/30 border border-red-700/50 rounded-lg text-red-400 text-sm">{error}</div>
          )}

          <div>
            <label htmlFor="reset-password" className="block text-sm text-[var(--text-primary)] mb-2">New password</label>
            <div className="relative">
              <input id="reset-password"
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={e => setPassword(e.target.value)}
                className="w-full px-4 py-3 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)] pr-10"
                autoComplete="new-password"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-300"
              >
                {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
            {password && (
              <div className="mt-2">
                <div className="h-1 bg-gray-700 rounded-full overflow-hidden">
                  <div className={`h-full ${strength.color} ${strength.width} transition-all`} />
                </div>
                <p className="text-xs text-[var(--text-muted)] mt-1">{strength.label}</p>
              </div>
            )}
          </div>

          <div>
            <label htmlFor="reset-confirm" className="block text-sm text-[var(--text-primary)] mb-2">Confirm password</label>
            <div className="relative">
              <input id="reset-confirm"
                type={showConfirm ? 'text' : 'password'}
                value={confirmPassword}
                onChange={e => setConfirmPassword(e.target.value)}
                className="w-full px-4 py-3 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)] pr-10"
                autoComplete="new-password"
              />
              <button
                type="button"
                onClick={() => setShowConfirm(!showConfirm)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-300"
              >
                {showConfirm ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
            {confirmPassword && password !== confirmPassword && (
              <p className="text-red-400 text-xs mt-1">Passwords do not match</p>
            )}
          </div>

          <button
            type="submit"
            disabled={loading || password !== confirmPassword || password.length < 8}
            className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {loading && <span className="w-4 h-4 border-2 border-black border-t-transparent rounded-full animate-spin" />}
            {loading ? 'Updating...' : 'Update Password'}
          </button>
        </form>
      </div>
    </div>
  )
}

export default function ResetPasswordPage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
          <div className="w-6 h-6 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
        </div>
      }
    >
      <ResetPasswordContent />
    </Suspense>
  )
}

'use client';

import { useState } from 'react'
import dynamic from 'next/dynamic'
import { executeWorkflow, generateReport } from '@/lib/compute/workflowEngine'
import { Play, FileText, Loader2 } from 'lucide-react'
import type { Node, Edge } from 'reactflow'

const WorkflowCanvas = dynamic(
  () => import('@/components/automator/WorkflowCanvas'),
  { ssr: false, loading: () => <div className="animate-pulse bg-[var(--bg-secondary)] rounded-lg h-96">Loading workflow...</div> }
)

export default function AutomatorPage() {
  const [running, setRunning] = useState(false)
  const [results, setResults] = useState<any>(null)
  
  const handleRunWorkflow = async (nodes: Node[], edges: Edge[]) => {
    setRunning(true)
    try {
      const result = await executeWorkflow(nodes as any[], edges as any[])
      setResults(result)
    } catch (err) {
      console.error(err)
    } finally {
      setRunning(false)
    }
  }
  
  const handleGenerateReport = async () => {
    setRunning(true)
    try {
      const report = await generateReport(
        { project: 'test' },
        ['summary', 'methodology', 'results', 'recommendations'],
        'technical'
      )
      setResults({ report })
    } catch (err) {
      console.error(err)
    } finally {
      setRunning(false)
    }
  }
  
  return (
    <div className="container mx-auto py-8">
      <h1 className="text-3xl font-bold mb-8">SurveyFlow Automator</h1>
      
      <div className="bg-white dark:bg-gray-800 rounded-lg p-6 mb-6">
        <div className="flex gap-4 mb-4">
          <button
            onClick={() => handleRunWorkflow([], [])}
            disabled={running}
            className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50"
          >
            {running ? <Loader2 className="h-5 w-5 animate-spin" /> : <Play className="h-5 w-5" />}
            Run Workflow
          </button>
          
          <button
            onClick={handleGenerateReport}
            disabled={running}
            className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
          >
            <FileText className="h-5 w-5" />
            Generate Report
          </button>
        </div>
      </div>
      
      <div className="h-[600px] bg-white dark:bg-gray-800 rounded-lg overflow-hidden">
        <WorkflowCanvas onSave={handleRunWorkflow} />
      </div>
      
      {results && (
        <div className="mt-6 bg-white dark:bg-gray-800 rounded-lg p-6">
          <h3 className="text-lg font-semibold mb-4">Results</h3>
          <pre className="bg-gray-100 dark:bg-gray-900 p-4 rounded overflow-x-auto">
            {JSON.stringify(results, null, 2)}
          </pre>
        </div>
      )}
    </div>
  )
}

'use client';
import React from 'react'

import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import { createClient } from '@/lib/api-client/client'
import { utmToGeographic } from '@/lib/geodesy/coordinates'
import Link from 'next/link'
import { BeaconRegistryPanel } from '@/components/beacons/BeaconRegistryPanel'
import { ControlPointRegistry } from '@/components/survey/ControlPointRegistry'
// ponytail: Phase 6 — use typed imports from ol (which ships its own .d.ts files)
// instead of dynamic imports + `as any` casts. Same bundle (Next.js code-splits
// these automatically), but now TypeScript can catch API misuse.
import Map from 'ol/Map'
import View from 'ol/View'
import TileLayer from 'ol/layer/Tile'
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import OSM from 'ol/source/OSM'
import Style from 'ol/style/Style'
import CircleStyle from 'ol/style/Circle'
import Fill from 'ol/style/Fill'
import Stroke from 'ol/style/Stroke'
import Text from 'ol/style/Text'
import Feature from 'ol/Feature'
import Point from 'ol/geom/Point'
import { fromLonLat } from 'ol/proj'
import Overlay from 'ol/Overlay'
import type { Map as MapType, Overlay as OverlayType } from 'ol'

interface Beacon {
  id: string
  name: string
  easting: number
  northing: number
  elevation?: number
  utm_zone: number
  hemisphere: string
  authority?: string
  beacon_type: string
  description?: string
  datum?: string  // T1.5d: added for beacon import
}

interface Project {
  id: string
  name: string
  location?: string
  survey_type?: string
  created_at: string
}

function getMarkerIcon(type: string) {
  const icons: Record<string, string> = {
    trig: '▲',
    control: '●',
    boundary: '■',
    benchmark: '◆',
    gnss: '',
    other: '●'
  }
  return icons[type] || '●'
}

function getMarkerColor(type: string) {
  const colors: Record<string, string> = {
    trig: '#ef4444',
    control: '#f97316',
    boundary: '#eab308',
    benchmark: '#22c55e',
    gnss: '#3b82f6',
    other: '#6b7280'
  }
  return colors[type] || '#6b7280'
}

export default function BeaconsPage() {
  const [importMsg, setImportMsg] = React.useState<{text:string;ok:boolean}|null>(null)
  // AUDIT FIX (2026-07-03): Removed 'activity' view — it placed projects
  // at Math.random() positions (pins jumped on every refresh). Only
  // the 'beacons' view is real.
  const [beacons, setBeacons] = useState<Beacon[]>([])
  const [projects, setProjects] = useState<Project[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<string>('all')
  const [search, setSearch] = useState('')
  const [importProject, setImportProject] = useState('')
  const [importBeacon, setImportBeacon] = useState<Beacon | null>(null)
  const [importLoading, setImportLoading] = useState(false)

  const mapRef = useRef<HTMLDivElement>(null)
  const popupRef = useRef<HTMLDivElement>(null)
  const mapInstance = useRef<MapType | null>(null)
  const overlayRef = useRef<OverlayType | null>(null)

  // AUDIT FIX (H-007, 2026-07-27): useMemo to prevent infinite loop on /beacons.
  // Same pattern as H-003 in /fieldbook.
  const dbClient = useMemo(() => createClient(), [])

  const fetchData = useCallback(async () => {
    setLoading(true)
    
    const [beaconsRes, projectsRes] = await Promise.all([
      dbClient.from('public_beacons').select('*').eq('status', 'verified'),
      dbClient.from('projects').select('id, name, location, survey_type, created_at')
    ])

    if (beaconsRes.data) setBeacons(beaconsRes.data as unknown as Beacon[])
    if (projectsRes.data) setProjects(projectsRes.data as unknown as Project[])
    setLoading(false)
  }, [dbClient])

  useEffect(() => {
    fetchData()
  }, [fetchData])

  // Initialize map once (typed ol imports — Next.js still code-splits)
  useEffect(() => {
    if (!mapRef.current) return

    let cancelled = false

    async function initMap() {
      try {
        // ponytail: imports are now at module top-level (typed). The async
        // wrapper is kept for the cancelled-flag pattern.
        await Promise.resolve() // keep async signature for callers
        if (cancelled || !mapRef.current) return

        const map = new Map({
          target: mapRef.current,
          layers: [new TileLayer({ source: new OSM() })],
          view: new View({
            center: fromLonLat([36.8219, -1.2921]),
            zoom: 6,
          }),
        })

        if (popupRef.current) {
          const overlay = new Overlay({
            element: popupRef.current,
            autoPan: { animation: { duration: 250 } },
          })
          map.addOverlay(overlay)
          overlayRef.current = overlay
        }

        mapInstance.current = map

        // Click handler for popup
        // ponytail: use a structural type for evt; cast handler when
        // registering with map.on() so TS doesn't complain about the
        // ol MapBrowserEvent<UIEvent> signature mismatch.
        const handleClick = (evt: { pixel: [number, number]; coordinate: [number, number] }) => {
          const overlay = overlayRef.current
          if (!overlay || !popupRef.current) return

          const feature = map.forEachFeatureAtPixel(evt.pixel, (f) => f as Feature)
          const popupData = feature?.get('popupData') as
            | { color: string; icon: string; name: string; authority?: string; beacon_type: string; easting: number; northing: number; elevation?: number; utm_zone: number; hemisphere: string }
            | undefined
          if (feature && popupData && popupRef.current) {
            // VULN-002 FIX: render with textContent, never innerHTML.
            const el = popupRef.current
            el.replaceChildren()

            const wrap = document.createElement('div')
            wrap.className = 'text-sm min-w-[200px]'
            wrap.style.color = 'var(--text-primary)'

            const title = document.createElement('div')
            title.style.cssText = 'font-weight:bold;font-size:1.1rem;color:' + popupData.color
            title.textContent = `${popupData.icon} ${popupData.name}`
            wrap.append(title)

            if (popupData.authority) {
              const authority = document.createElement('div')
              authority.style.cssText = 'color:var(--text-muted);margin-top:4px'
              authority.textContent = `Authority: ${popupData.authority}`
              wrap.append(authority)
            }

            const typeRow = document.createElement('div')
            typeRow.style.cssText = 'color:var(--text-muted);text-transform:capitalize'
            typeRow.textContent = `Type: ${popupData.beacon_type}`
            wrap.append(typeRow)

            const coords = document.createElement('div')
            // white-space:pre-line preserves the \n line break (textContent
            // would otherwise collapse it to a space, unlike the old <br/>).
            coords.style.cssText = 'font-family:monospace;margin-top:8px;white-space:pre-line'
            coords.textContent = `E: ${popupData.easting.toFixed(4)}\nN: ${popupData.northing.toFixed(4)}`
            wrap.append(coords)

            if (popupData.elevation) {
              const elev = document.createElement('div')
              elev.style.cssText = 'color:var(--text-muted)'
              elev.textContent = `Elev: ${popupData.elevation.toFixed(3)} m`
              wrap.append(elev)
            }

            const utm = document.createElement('div')
            utm.style.cssText = 'color:var(--text-muted);font-size:0.75rem;margin-top:4px'
            utm.textContent = `UTM Zone ${popupData.utm_zone}${popupData.hemisphere}`
            wrap.append(utm)

            el.append(wrap)
            overlay.setPosition(evt.coordinate)
          } else {
            overlay.setPosition(undefined)
          }
        }
        map.on('click', handleClick as (e: unknown) => void)
      } catch (err) {
        console.error('Beacons map init failed:', err)
      }
    }

    initMap()

    return () => {
      cancelled = true
      if (mapInstance.current) mapInstance.current.setTarget(undefined)
      overlayRef.current = null
    }
  }, [])

  // Update map features when data changes
  useEffect(() => {
    const map = mapInstance.current
    if (!map || loading) return

    let cancelled = false

    async function updateFeatures() {
      try {
        // ponytail: re-assert map is non-null inside async closure (TS can't
        // track the outer null check across the async boundary)
        if (!map || cancelled) return

        const vectorSource = new VectorSource()

      const filteredBeacons = beacons.filter((b) => {
        if (filter !== 'all' && b.beacon_type !== filter) return false
        if (search && !b.name.toLowerCase().includes(search.toLowerCase()) &&
            !b.authority?.toLowerCase().includes(search.toLowerCase())) return false
        return true
      })

      filteredBeacons.forEach((beacon) => {
        const coords = utmToGeographic(beacon.easting, beacon.northing, beacon.utm_zone, beacon.hemisphere as 'N' | 'S')
        const color = getMarkerColor(beacon.beacon_type)
        const icon = getMarkerIcon(beacon.beacon_type)

        const feature = new Feature({
          geometry: new Point(fromLonLat([coords.lon, coords.lat])),
        })
        feature.setStyle(new Style({
          image: new CircleStyle({
            radius: 8,
            fill: new Fill({ color }),
            stroke: new Stroke({ color: '#fff', width: 2 }),
          }),
          text: new Text({ text: icon, font: '12px sans-serif', fill: new Fill({ color: '#fff' }) }),
        }))
        // VULN-002 FIX (security review 2026-08-03): store structured data
        // instead of an HTML string — beacon names/authorities are
        // user-entered and would otherwise execute as stored XSS. The popup
        // is rendered with textContent in the click handler below.
        feature.set('popupData', {
          color,
          icon,
          name: beacon.name,
          authority: beacon.authority,
          beacon_type: beacon.beacon_type,
          easting: beacon.easting,
          northing: beacon.northing,
          elevation: beacon.elevation,
          utm_zone: beacon.utm_zone,
          hemisphere: beacon.hemisphere,
        })
        feature.set('beaconId', beacon.id)
        vectorSource.addFeature(feature)
      })

      // Pan to Kenya/East Africa if beacons exist
      if (filteredBeacons.length > 0) {
        const extent = vectorSource.getExtent()
        if (extent && (extent[2] - extent[0] > 0 || extent[3] - extent[1] > 0)) {
          map.getView().fit(extent, { padding: [50, 50, 50, 50], maxZoom: 10 })
        }
      } else {
        map.getView().setCenter(fromLonLat([36.8219, -1.2921]))
        map.getView().setZoom(6)
      }

        // Remove old vector layers, add new one
        const existing = map.getLayers().getArray().find((l) => l instanceof VectorLayer)
        if (existing) map.removeLayer(existing)
        map.addLayer(new VectorLayer({ source: vectorSource }))
      } catch (err) {
        console.error('Beacons map feature update failed:', err)
      }
    }

    updateFeatures()

    return () => {
      cancelled = true
    }
  }, [beacons, projects, filter, search, loading])

  const handleImport = async () => {
    if (!importBeacon || !importProject) return
    
    setImportLoading(true)
    
    try {
      const { error } = await dbClient.from('survey_points').insert({
        project_id: importProject,
        point_name: importBeacon.name,  // T1.5d FIX: was 'name' (column doesn't exist)
        easting: importBeacon.easting,
        northing: importBeacon.northing,
        elevation: importBeacon.elevation,
        is_control: true,
        // T1.5d: control_order and locked columns don't exist — removed.
        // The beacon's datum/utm_zone could be carried over here too.
        datum: importBeacon.datum || 'Arc 1960',
        utm_zone: importBeacon.utm_zone || 37,
        source: 'beacon_registry',
      })

      if (error) throw error
      
      setImportMsg({text:'Beacon imported successfully!', ok:true}); setTimeout(()=>setImportMsg(null),3000)
      setImportBeacon(null)
      setImportProject('')
    } catch (err: unknown) {
      const msg = err instanceof Error ? (err as Error).message : String(err)
      setImportMsg({text:'Error: '+msg, ok:false}); setTimeout(()=>setImportMsg(null),4000)
    }
    
    setImportLoading(false)
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] flex flex-col">
      <header className="bg-[var(--bg-secondary)] border-b border-[var(--border-color)] px-4 py-4">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-2xl font-bold text-[var(--text-primary)]">Community Beacons</h1>
              <p className="text-sm text-[var(--text-secondary)]">East Africa Control Network</p>
            </div>
            <div className="flex gap-3">
              <Link
                href="/beacons/submit"
                className="px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg"
              >
                + Submit Beacon
              </Link>
            </div>
          </div>

          <div className="flex gap-4 items-center">
              <input
                type="text"
                placeholder="Search by name or authority..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="flex-1 px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)]"
              />
              <div className="flex gap-2">
                {['all', 'trig', 'control', 'boundary', 'benchmark'].map((f) => (
                  <button
                    key={f}
                    onClick={() => setFilter(f)}
                    className={`px-3 py-2 rounded text-sm capitalize ${
                      filter === f ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                    }`}
                  >
                    {f}
                  </button>
                ))}
              </div>
            </div>
        </div>
      </header>

      <main className="flex-1 relative">
        {loading ? (
          <div className="flex items-center justify-center h-full">
            <div className="animate-spin w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full"></div>
          </div>
        ) : (
          <div className="h-full" style={{ height: 'calc(100vh - 140px)' }}>
            <div ref={mapRef} className="w-full h-full" />
            <div ref={popupRef} className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 rounded p-2 text-sm shadow-lg" style={{ display: 'none' }}></div>
          </div>
        )}
      </main>

      {/* Import Modal */}
      {importBeacon && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl p-6 max-w-md w-full mx-4">
            <h3 className="text-lg font-bold text-[var(--text-primary)] mb-4">Import Beacon</h3>
            <p className="text-[var(--text-primary)] mb-4">
              Import {importBeacon.name} as a locked Primary control point?
            </p>
            
            <div className="mb-4">
              <label htmlFor="beacon-project" className="block text-sm text-[var(--text-secondary)] mb-2">Select Project</label>
              <select
                id="beacon-project"
                value={importProject}
                onChange={e => setImportProject(e.target.value)}
                className="w-full px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]"
              >
                <option value="">Choose project...</option>
                {projects.map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setImportBeacon(null)}
                className="flex-1 px-4 py-2 bg-[var(--bg-tertiary)] text-[var(--text-primary)] rounded"
              >
                Cancel
              </button>
              <button
                onClick={handleImport}
                disabled={!importProject || importLoading}
                className="flex-1 px-4 py-2 bg-[var(--accent)] text-black font-semibold rounded disabled:opacity-50"
              >
                {importLoading ? 'Importing...' : 'Import'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Beacon Registry — searchable global database */}
      <div className="max-w-7xl mx-auto w-full px-4 py-6">
        <BeaconRegistryPanel />
      </div>

      {/* Control Point Registry — SoK Trig stations, KENCORS, benchmarks */}
      <div className="max-w-7xl mx-auto w-full px-4 pb-6">
        <ControlPointRegistry />
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react'
import BoundaryUploader from '@/components/cadastra/BoundaryUploader'
import ComparisonPanel from '@/components/cadastra/ComparisonPanel'
import ValidationReport from '@/components/cadastra/ValidationReport'
import { validateBoundary } from '@/lib/compute/cadastraValidator'
import type { BoundaryPolygon, ValidationResult } from '@/types/cadastra'

export default function CadastraValidatorPage() {
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<ValidationResult | null>(null)
  // AUDIT FIX (2026-07-03): Was hardcoded 'default-project'. Now reads
  // projectId from URL query (?project=X) or null for standalone mode.
  const [projectId, setProjectId] = useState<string | null>(null)

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const pid = params.get('project') || params.get('projectId')
    if (pid) setProjectId(pid)
  }, [])
  
  const handleValidate = async (boundary: BoundaryPolygon) => {
    setLoading(true)
    try {
      const response = await validateBoundary(projectId, boundary)
      setResult(response.validation)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }
  
  return (
    <div className="container mx-auto py-8">
      <h1 className="text-3xl font-bold mb-8">CadastraAI Validator</h1>
      
      <div className="space-y-6">
        <BoundaryUploader onUpload={handleValidate} loading={loading} />
        
        {result && (
          <>
            <ComparisonPanel result={result} />
            <ValidationReport result={result} projectId={projectId ?? 'standalone'} />
          </>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { useSearchParams } from 'next/navigation'

/**
 * Cadastral Workflow Hub — v0.3
 *
 * Connects the existing cadastral tools into a visible 5-step workflow.
 * A surveyor lands here, sees the full process, and can track progress.
 *
 * Steps:
 * 1. Search parcel → /parcel
 * 2. Validate boundary → /cadastra
 * 3. Record beacons → /beacons
 * 4. Generate deed plan → /deed-plan
 * 5. Create mutation / submit → /tools/mutation-plan
 *
 * Status tracking via localStorage (no DB needed — zero paying customers).
 * When real persistence is needed, swap localStorage for a Supabase table.
 */

interface WorkflowState {
  parcelSearched: boolean
  boundaryValidated: boolean
  beaconsRecorded: boolean
  deedPlanGenerated: boolean
  submissionReady: boolean
  parcelNumber?: string
  updatedAt: string
}

const STORAGE_KEY = 'metardu:cadastral-workflow'

const EMPTY_STATE: WorkflowState = {
  parcelSearched: false,
  boundaryValidated: false,
  beaconsRecorded: false,
  deedPlanGenerated: false,
  submissionReady: false,
  updatedAt: new Date().toISOString(),
}

const STEPS = [
  {
    id: 'parcelSearched' as const,
    num: '01',
    title: 'Search the parcel',
    desc: 'Look up the LR number, title number, or parcel ID in the NLIMS / county registry. Confirm the registered owner, approximate area, and existing boundaries before heading to the field.',
    href: '/parcel',
    cta: 'Search parcel',
    reference: 'Land Registration Act 2012 · NLIMS',
    hints: [
      'Note the LR number (e.g. 2090/42) and registration section',
      'Check for existing beacons on the registry map',
      'Identify adjoining landowners — you will need their consent for mutations',
    ],
  },
  {
    id: 'boundaryValidated' as const,
    num: '02',
    title: 'Validate the boundary',
    desc: 'Run a topological pre-flight check on your surveyed boundary polygon. Catches self-intersections, sliver polygons, area violations, and winding-order issues before NLIMS / ArdhiSasa submission. Also check for overlaps with adjoining parcels.',
    href: '/tools/topology-check',
    cta: 'Run topology check',
    reference: 'Survey Act Cap 299 § 22 · NLIMS submission requirements · GeoJSON RFC 7946',
    hints: [
      'Compare surveyed area vs registered area — tolerance is ±2% for cadastral',
      'Check for encroachment on adjoining parcels',
      'Flag any beacon discrepancies (found vs set vs referenced)',
    ],
  },
  {
    id: 'beaconsRecorded' as const,
    num: '03',
    title: 'Record beacons',
    desc: 'Register every boundary beacon with its type (PSC, SSC, iron pin, concrete), coordinates (UTM), and status (found, set, referenced). This is your evidence base for the deed plan and any future disputes.',
    href: '/beacons',
    cta: 'Open beacon registry',
    reference: 'Survey Regulations 1994 · Form LRA 67',
    hints: [
      'Every beacon needs: type, UTM coordinates, status, description',
      'Photo-document each beacon (field record evidence)',
      'Reference destroyed beacons to permanent features',
    ],
  },
  {
    id: 'deedPlanGenerated' as const,
    num: '04',
    title: 'Generate the deed plan',
    desc: 'Draft the Form No. 4 deed plan from your computed coordinates. Include the parcel outline, bearings and distances, area, north arrow, scale bar, beacon schedule, and abuttals. This is the primary survey output.',
    href: '/deed-plan',
    cta: 'Generate deed plan',
    reference: 'Survey Act Cap 299 · Form No. 4 · RDM 1.1',
    hints: [
      'Scale: 1:500, 1:1000, 1:2500, or 1:5000 depending on parcel size',
      'Bearings in WCB (whole circle bearing), distances in metres',
      'Area computed by double meridian distance (DMD) or coordinate method',
      'Include abuttals on all four sides (N, S, E, W)',
    ],
  },
  {
    id: 'submissionReady' as const,
    num: '05',
    title: 'Create mutation & submit',
    desc: 'If this is a subdivision, amalgamation, or boundary adjustment, generate the mutation plan and assemble the NLIMS submission package. Include the deed plan, beacon certificate, computation workbook, and statutory forms.',
    href: '/tools/mutation-plan',
    cta: 'Create mutation plan',
    reference: 'Land Registration Act § 38 · NLIMS submission workflow',
    hints: [
      'Mutation types: subdivision, amalgamation, boundary adjustment, change of user',
      'Neighbour consent (Form LRA 52) required for boundary adjustments',
      'Submission package: deed plan + beacon certificate + workbook + CLA forms',
      'Survey of Kenya review takes 2-6 weeks — track status in your project',
    ],
  },
]

export default function CadastralWorkflowPage() {
  const searchParams = useSearchParams()
  const [state, setState] = useState<WorkflowState>(EMPTY_STATE)
  const [mounted, setMounted] = useState(false)

  // Load from localStorage on mount
  useEffect(() => {
    setMounted(true)
    try {
      const saved = localStorage.getItem(STORAGE_KEY)
      if (saved) {
        setState(JSON.parse(saved))
      }
    } catch {
      // ignore parse errors
    }
  }, [])

  // Check URL params for step completion (e.g. ?completed=parcelSearched)
  useEffect(() => {
    if (!mounted) return
    const completed = searchParams.get('completed')
    const parcel = searchParams.get('parcel')
    if (completed && completed in state) {
      const newState = {
        ...state,
        [completed]: true,
        ...(parcel ? { parcelNumber: parcel } : {}),
        updatedAt: new Date().toISOString(),
      }
      setState(newState)
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newState))
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mounted, searchParams])

  const toggleStep = (stepId: keyof WorkflowState) => {
    const newState = {
      ...state,
      [stepId]: !state[stepId],
      updatedAt: new Date().toISOString(),
    }
    setState(newState)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(newState))
  }

  const resetWorkflow = () => {
    setState(EMPTY_STATE)
    localStorage.setItem(STORAGE_KEY, JSON.stringify(EMPTY_STATE))
  }

  const completedCount = STEPS.filter(s => state[s.id]).length
  const progress = Math.round((completedCount / STEPS.length) * 100)

  if (!mounted) {
    return <div className="max-w-5xl mx-auto px-4 py-8" style={{ minHeight: '50vh' }} />
  }

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-10 py-6 md:py-10">
      {/* Header */}
      <div className="mb-8 pb-5 border-b border-[var(--border-color)]">
        <div className="font-mono text-[11px] text-[var(--accent)] tracking-[0.12em] uppercase mb-2">
          Cadastral survey · 5-step workflow
        </div>
        <h1 className="font-display text-4xl md:text-5xl text-[var(--text-primary)] tracking-[-0.025em] leading-[1.05]">
          From parcel search <span className="text-[var(--accent)] italic">to filed plan.</span>
        </h1>
        <p className="text-sm text-[var(--text-secondary)] mt-3 max-w-[60ch] leading-relaxed">
          The complete cadastral survey workflow for Kenyan land surveyors. Each step
          links to the relevant tool. Track your progress as you go — your status saves
          locally and persists across sessions.
        </p>
      </div>

      {/* Progress bar */}
      <div className="mb-10 flex items-center gap-4">
        <div className="flex-1 h-2 bg-[var(--bg-tertiary)] rounded-sm overflow-hidden">
          <div
            className="h-full bg-[var(--accent)] transition-all duration-300"
            style={{ width: `${progress}%` }}
          />
        </div>
        <span className="font-mono text-xs text-[var(--text-muted)] tracking-[0.04em]">
          {completedCount}/{STEPS.length} complete
        </span>
        {completedCount > 0 && (
          <button
            onClick={resetWorkflow}
            className="font-mono text-[10px] text-[var(--text-muted)] hover:text-[var(--error)] tracking-[0.06em] uppercase transition-colors"
          >
            Reset
          </button>
        )}
      </div>

      {/* Steps */}
      <div className="space-y-0 border border-[var(--border-color)] bg-[var(--bg-card)]">
        {STEPS.map((step, idx) => {
          const isComplete = state[step.id]
          const isLocked = idx > 0 && !state[STEPS[idx - 1].id]

          return (
            <div
              key={step.id}
              className={`border-b border-[var(--border-color)] last:border-b-0 ${isLocked ? 'opacity-50' : ''}`}
            >
              <div className="p-5 md:p-6">
                <div className="flex items-start gap-4">
                  {/* Step number / checkbox */}
                  <button
                    onClick={() => !isLocked && toggleStep(step.id)}
                    disabled={isLocked}
                    className={`shrink-0 w-10 h-10 border flex items-center justify-center transition-all ${
                      isComplete
                        ? 'bg-[var(--accent)] border-[var(--accent)] text-[var(--bg-primary)]'
                        : 'border-[var(--border-color)] text-[var(--text-muted)] hover:border-[var(--accent)]'
                    } ${isLocked ? 'cursor-not-allowed' : 'cursor-pointer'}`}
                    aria-label={isComplete ? `Mark step ${step.num} as incomplete` : `Mark step ${step.num} as complete`}
                  >
                    {isComplete ? (
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
                      </svg>
                    ) : (
                      <span className="font-mono text-xs tracking-[0.04em]">{step.num}</span>
                    )}
                  </button>

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-4 mb-2">
                      <div>
                        <h2 className={`font-display text-xl text-[var(--text-primary)] tracking-[-0.015em] leading-tight ${isComplete ? 'line-through opacity-60' : ''}`}>
                          {step.title}
                        </h2>
                        <p className="font-mono text-[10px] text-[var(--text-muted)] tracking-[0.04em] mt-1">
                          {step.reference}
                        </p>
                      </div>
                      {!isLocked && (
                        <Link
                          href={step.href}
                          className="shrink-0 font-mono text-[11px] text-[var(--accent)] hover:opacity-80 tracking-[0.04em] uppercase border-b border-[var(--accent)] pb-0.5 no-underline"
                        >
                          {step.cta} →
                        </Link>
                      )}
                    </div>

                    <p className="text-sm text-[var(--text-secondary)] leading-relaxed mb-4">
                      {step.desc}
                    </p>

                    {/* Hints */}
                    <ul className="space-y-1.5">
                      {step.hints.map((hint, i) => (
                        <li key={`${hint}-${i}`} className="flex items-start gap-2 text-xs text-[var(--text-muted)]">
                          <span className="text-[var(--accent)] mt-0.5">·</span>
                          <span className="font-mono leading-relaxed">{hint}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            </div>
          )
        })}
      </div>

      {/* Bottom: contextual info */}
      <div className="mt-8 grid md:grid-cols-3 gap-4">
        <div className="border border-[var(--border-color)] bg-[var(--bg-card)] p-5">
          <div className="font-mono text-[10px] text-[var(--accent)] tracking-[0.08em] uppercase mb-3">
            Regulatory framework
          </div>
          <ul className="space-y-2 text-xs text-[var(--text-secondary)]">
            <li className="font-mono">Survey Act Cap 299 — primary surveying law</li>
            <li className="font-mono">Survey Regulations 1994 — operational rules</li>
            <li className="font-mono">RDM 1.1 (2025) — accuracy standards</li>
            <li className="font-mono">Land Registration Act 2012 — registration</li>
            <li className="font-mono">NLIMS — National Land Information System</li>
          </ul>
        </div>
        <div className="border border-[var(--border-color)] bg-[var(--bg-card)] p-5">
          <div className="font-mono text-[10px] text-[var(--accent)] tracking-[0.08em] uppercase mb-3">
            Key documents
          </div>
          <ul className="space-y-2 text-xs text-[var(--text-secondary)]">
            <li className="font-mono">Form No. 4 — deed plan (primary output)</li>
            <li className="font-mono">Form LRA 52 — neighbour consent (mutations)</li>
            <li className="font-mono">Form LRA 67 — beacon certificate</li>
            <li className="font-mono">CLA forms — computation workbook schedules</li>
            <li className="font-mono">Mutation form — subdivision / amalgamation</li>
          </ul>
        </div>
        <div className="border border-[var(--border-color)] bg-[var(--bg-card)] p-5">
          <div className="font-mono text-[10px] text-[var(--accent)] tracking-[0.08em] uppercase mb-3">
            Geodesy tools
          </div>
          <ul className="space-y-2 text-xs">
            <li><Link href="/tools/scale-factor" className="text-[var(--text-secondary)] hover:text-[var(--accent)] font-mono no-underline">Scale factor (grid → ground area)</Link></li>
            <li><Link href="/tools/site-calibration" className="text-[var(--text-secondary)] hover:text-[var(--accent)] font-mono no-underline">Site calibration (WGS84 → Arc 1960)</Link></li>
            <li><Link href="/tools/cassini-utm" className="text-[var(--text-secondary)] hover:text-[var(--accent)] font-mono no-underline">Cassini ↔ UTM converter</Link></li>
            <li><Link href="/tools/topology-check" className="text-[var(--text-secondary)] hover:text-[var(--accent)] font-mono no-underline">Topology pre-flight validator</Link></li>
            <li><Link href="/tools/cogo-reconstruct" className="text-[var(--text-secondary)] hover:text-[var(--accent)] font-mono no-underline">COGO deed plan reconstructor</Link></li>
          </ul>
        </div>
      </div>

      {/* Last updated */}
      {state.updatedAt && (
        <div className="mt-6 text-center font-mono text-[10px] text-[var(--text-muted)] tracking-[0.04em]">
          Last updated {new Date(state.updatedAt).toLocaleString('en-KE')}
        </div>
      )}
    </div>
  )
}

'use client';

import { Suspense, useEffect, useMemo, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import type { CurrencyCode, PlanId } from '@/lib/subscription/catalog'
import { PLAN_CATALOG } from '@/lib/subscription/catalog'
import {
  checkMpesaPaymentStatus,
  getCurrencyForCountry,
  getPaymentMethods,
  startSubscriptionPayment,
  type PaymentMethod,
} from '@/lib/enterprise'

// PayPal only supports these currencies
const PAYPAL_CURRENCIES = new Set(['USD', 'EUR', 'GBP', 'AUD', 'CAD', 'CHF', 'CZK', 'DKK', 'HKD', 'HUF', 'ILS', 'JPY', 'MXN', 'NOK', 'NZD', 'PHP', 'PLN', 'SEK', 'SGD', 'THB', 'TWD'])

function CheckoutContent() {
  const searchParams = useSearchParams()
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1)
  const [selectedPlanId, setSelectedPlanId] = useState<PlanId>(() => {
    const planParam = searchParams.get('plan') as PlanId | null
    if (planParam && PLAN_CATALOG.some(p => p.id === planParam)) return planParam
    return 'pro'
  })
  const [country, setCountry] = useState('Kenya')
  const [currency, setCurrency] = useState<CurrencyCode>('KES')
  const [method, setMethod] = useState<PaymentMethod['type']>('mpesa')
  const [phoneNumber, setPhoneNumber] = useState('')
  const [email, setEmail] = useState('')
  const [processing, setProcessing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [mpesa, setMpesa] = useState<{ paymentId: string; checkoutRequestId: string } | null>(null)

  const plan = useMemo(
    () => PLAN_CATALOG.find((p) => p.id === selectedPlanId)!,
    [selectedPlanId]
  )

  const paymentMethods = useMemo(() => getPaymentMethods(country), [country])

  useEffect(() => {
    if (!paymentMethods.some((m) => m.type === method)) {
      setMethod(paymentMethods[0]?.type ?? 'card')
    }
  }, [paymentMethods, method])

  const formatPrice = (amount: number) => {
    const symbols: Partial<Record<CurrencyCode, string>> = {
      KES: 'KSh ',
      UGX: 'USh ',
      TZS: 'TSh ',
      NGN: '₦ ',
      GHS: 'GH₵ ',
      ZAR: 'R ',
      USD: '$ ',
      EUR: '€ ',
      GBP: '£ ',
      INR: '₹ ',
      IDR: 'Rp ',
      BRL: 'R$ ',
      AUD: 'A$ ',
    }
    return `${symbols[currency] ?? `${currency} `}${amount.toLocaleString()}`
  }

  const onStart = async () => {
    setError(null)
    setProcessing(true)
    try {
      const res = await startSubscriptionPayment({
        planId: plan.id,
        currency,
        method,
        email,
        phoneNumber: phoneNumber || undefined,
        country,
      })

      if (res.kind === 'activated') {
        window.location.href = '/dashboard'
        return
      }

      if (res.kind === 'redirect') {
        window.location.href = res.url
        return
      }

      if (res.kind === 'mpesa') {
        setMpesa({ paymentId: res.paymentId, checkoutRequestId: res.checkoutRequestId })
        setStep(4)
        return
      }

      setError('Unexpected payment response.')
    } catch (e: unknown) {
      setError(((e as Error)?.message) ?? 'Payment failed.')
    } finally {
      setProcessing(false)
    }
  }

  const canContinueDetails =
    !!email && (method !== 'mpesa' || !!phoneNumber) && paymentMethods.some((m) => m.type === method)

  return (
    <div className="min-h-screen">
      <div className="max-w-4xl mx-auto px-4 py-8 md:py-10">
        <h1 className="text-2xl md:text-3xl font-bold text-[var(--text-primary)] mb-2">Checkout</h1>
        <p className="text-[var(--text-secondary)] mb-8">Choose a plan and complete payment.</p>

        <div className="flex gap-2 mb-8">
          {[1, 2, 3].map((s) => (
            <div
              key={s}
              className={`flex-1 h-2 rounded ${step >= (s as any) ? 'bg-[var(--accent)]' : 'bg-[var(--bg-tertiary)]'}`}
            />
          ))}
        </div>

        {error && (
          <div className="mb-6 rounded-lg border border-red-900/50 bg-red-900/10 px-4 py-3 text-sm text-red-200">
            {error}
          </div>
        )}

        {step === 1 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">1) Select Plan</h2>

            <div className="mb-4">
              <label htmlFor="checkout-country" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Country</label>
              <select
                id="checkout-country"
                value={country}
                onChange={(e) => {
                  const c = e.target.value
                  setCountry(c)
                  setCurrency(getCurrencyForCountry(c))
                }}
                className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
              >
                <option value="Kenya">Kenya</option>
                <option value="Uganda">Uganda</option>
                <option value="Tanzania">Tanzania</option>
                <option value="Nigeria">Nigeria</option>
                <option value="Ghana">Ghana</option>
                <option value="South Africa">South Africa</option>
                <option value="Germany">Germany</option>
                <option value="UK">UK</option>
                <option value="US">US</option>
              </select>
              <p className="text-xs text-[var(--text-muted)] mt-2">Currency auto-selects from country, and you can still pay via card globally.</p>
            </div>

            <div className="space-y-3">
              {PLAN_CATALOG.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => setSelectedPlanId(p.id)}
                  className={`w-full text-left p-4 border-2 rounded-lg transition min-h-[56px] ${
                    selectedPlanId === p.id ? 'border-[var(--accent)] bg-[var(--accent)]/10' : 'border-[var(--border-color)] hover:border-[var(--border-hover)]'
                  }`}
                >
                  <div className="flex items-center justify-between gap-4">
                    <div>
                      <div className="text-[var(--text-primary)] font-semibold text-lg">{p.name}</div>
                      <div className="text-[var(--text-muted)] text-sm">{p.features.slice(0, 2).join(' • ')}</div>
                    </div>
                    <div className="text-right">
                      <div className="text-[var(--accent)] font-bold text-2xl">{formatPrice(p.prices[currency])}</div>
                      <div className="text-[var(--text-muted)] text-xs">/month</div>
                    </div>
                  </div>
                </button>
              ))}
            </div>

            <button
              onClick={() => setStep(2)}
              className="w-full mt-6 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] font-medium min-h-[44px]"
            >
              Continue
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">2) Payment Details</h2>

            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <label htmlFor="checkout-email" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Email</label>
                <input
                  id="checkout-email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="you@example.com"
                  className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
                />
              </div>
              <div>
                <label htmlFor="checkout-phone" className="block text-sm font-medium text-[var(--text-primary)] mb-2">Phone (M-Pesa only)</label>
                <input
                  id="checkout-phone"
                  type="tel"
                  value={phoneNumber}
                  onChange={(e) => setPhoneNumber(e.target.value)}
                  placeholder="e.g. 254712345678"
                  className="w-full p-3 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] min-h-[44px]"
                />
                <p className="text-xs text-[var(--text-muted)] mt-2">Required only for M-Pesa STK Push.</p>
              </div>
            </div>

            <div className="mt-6">
              <div className="block text-sm font-medium text-[var(--text-primary)] mb-2">Payment Method</div>
              <div className="space-y-2">
                {paymentMethods.map((pm) => (
                  <label
                    key={pm.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer min-h-[44px] ${
                      method === pm.type ? 'border-[var(--accent)] bg-[var(--accent)]/10' : 'border-[var(--border-color)]'
                    }`}
                  >
                    <input aria-label="Paymentmethod"
                      type="radio"
                      name="paymentMethod"
                      value={pm.type}
                      checked={method === pm.type}
                      onChange={() => setMethod(pm.type)}
                    />
                    <span className="text-[var(--text-primary)]">{pm.name}</span>
                  </label>
                ))}
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setStep(1)}
                className="flex-1 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
              >
                Back
              </button>
              <button
                onClick={() => setStep(3)}
                disabled={!canContinueDetails}
                className="flex-1 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
              >
                Review Order
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-4">3) Confirm & Pay</h2>

            <div className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-primary)] p-4 mb-6">
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Plan</span>
                <span className="font-semibold">{plan.name}</span>
              </div>
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Currency</span>
                <span className="font-semibold">{currency}</span>
              </div>
              <div className="flex items-center justify-between text-[var(--text-primary)] mb-2">
                <span>Method</span>
                <span className="font-semibold">{paymentMethods.find((p) => p.type === method)?.name ?? method}</span>
              </div>
              <div className="flex items-center justify-between border-t border-[var(--border-color)] pt-2 mt-2 text-[var(--text-primary)]">
                <span className="font-semibold">Total</span>
                <span className="font-bold text-lg text-[var(--accent)]">{formatPrice(plan.prices[currency])}</span>
              </div>
            </div>

            <div className="text-xs text-[var(--text-muted)] mb-6">
              Card payments use Stripe Checkout (Visa/Mastercard). PayPal redirects to PayPal approval. M-Pesa triggers STK push.
              {method === 'paypal' && !PAYPAL_CURRENCIES.has(currency) && (
                <span className="block mt-2 text-amber-400">
                  PayPal does not support {currency}. You will be charged the USD equivalent.
                </span>
              )}
            </div>

            <div className="flex gap-3">
              <button
                onClick={() => setStep(2)}
                className="flex-1 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
              >
                Back
              </button>
              <button
                onClick={onStart}
                disabled={processing}
                className="flex-1 py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
              >
                {processing ? 'Starting payment…' : 'Pay Now'}
              </button>
            </div>
          </div>
        )}

        {step === 4 && mpesa && (
          <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6">
            <h2 className="text-xl font-semibold text-[var(--text-primary)] mb-2">M-Pesa STK Push Sent</h2>
            <p className="text-[var(--text-secondary)] mb-6">Complete payment on your phone, then verify to activate your plan.</p>

            <button
              onClick={async () => {
                setProcessing(true)
                setError(null)
                try {
                  const r = await checkMpesaPaymentStatus(mpesa)
                  if (r.status === 'completed') {
                    window.location.href = '/dashboard'
                    return
                  }
                  if (r.status === 'failed') setError('Payment failed. Please try again.')
                  if (r.status === 'pending') setError('Still pending. If you have paid, wait a moment then try again.')
                } catch (e: unknown) {
                  setError(((e as Error)?.message) ?? 'Failed to verify payment.')
                } finally {
                  setProcessing(false)
                }
              }}
              disabled={processing}
              className="w-full py-3.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:bg-gray-700 disabled:text-[var(--text-primary)] font-medium min-h-[44px]"
            >
              {processing ? 'Checking…' : 'Verify Payment'}
            </button>

            <button
              onClick={() => {
                setMpesa(null)
                setStep(2)
              }}
              className="w-full mt-3 py-3.5 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)] font-medium min-h-[44px]"
            >
              Change method
            </button>
          </div>
        )}
      </div>
    </div>
  )
}

export default function CheckoutPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-6 h-6 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    }>
      <CheckoutContent />
    </Suspense>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { Search, ChevronRight, MapPin } from 'lucide-react'
import { PageHeader } from '@/components/shared/PageHeader'

interface SurveyorProfile {
  id: string
  fullName: string
  iskNumber?: string
  verifiedIsk: boolean
  firmName?: string
  county?: string
  specialty?: string
  avatarUrl?: string
  projectsCount: number
}

export default function SurveyorDirectoryPage() {
  const [surveyors, setSurveyors] = useState<SurveyorProfile[]>([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [countyFilter, setCountyFilter] = useState('')

  useEffect(() => {
    let cancelled = false
    const params = new URLSearchParams({ limit: '50' })
    if (search) params.set('q', search)
    if (countyFilter) params.set('county', countyFilter)

    fetch(`/api/community/surveyors?${params}`)
      .then(r => r.ok ? r.json() : null)
      .then(data => {
        if (!cancelled && data?.data) setSurveyors(data.data)
      })
      .catch(() => { if (!cancelled) setSurveyors([]) })
      .finally(() => { if (!cancelled) setLoading(false) })

    return () => { cancelled = true }
  }, [search, countyFilter])

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title="Surveyor Directory"
        subtitle="Verified land surveyors across East Africa"
        reference="ISK-verified professionals · Public profiles"
      />

      {/* Search + filter bar */}
      <div className="flex flex-col sm:flex-row gap-3 mb-6">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--text-muted)]" />
          <input
            type="text"
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search by name, firm, or ISK number..."
            className="w-full pl-10 pr-4 py-2.5 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] placeholder-[var(--text-muted)] focus:outline-none focus:border-[var(--accent)]/40"
          />
        </div>
        <input
          type="text"
          value={countyFilter}
          onChange={e => setCountyFilter(e.target.value)}
          placeholder="Filter by county..."
          className="sm:w-48 px-4 py-2.5 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] placeholder-[var(--text-muted)] focus:outline-none focus:border-[var(--accent)]/40"
        />
      </div>

      {/* Results count */}
      <p className="text-xs text-[var(--text-muted)] mb-4">
        {loading ? 'Loading...' : `${surveyors.length} surveyor${surveyors.length !== 1 ? 's' : ''} found`}
      </p>

      {/* Surveyor grid */}
      {loading ? (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3, 4, 5, 6].map(i => (
            <div key={i} className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6 animate-pulse">
              <div className="flex items-center gap-4 mb-4">
                <div className="w-12 h-12 rounded-xl bg-[var(--bg-tertiary)]" />
                <div className="flex-1 space-y-2">
                  <div className="h-3 bg-[var(--bg-tertiary)] rounded w-2/3" />
                  <div className="h-2 bg-[var(--bg-tertiary)] rounded w-1/2" />
                </div>
              </div>
              <div className="h-2 bg-[var(--bg-tertiary)] rounded w-full mb-2" />
              <div className="h-2 bg-[var(--bg-tertiary)] rounded w-3/4" />
            </div>
          ))}
        </div>
      ) : surveyors.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-[var(--border-color)] bg-[var(--bg-card)]/50 p-12 text-center">
          <Search className="w-10 h-10 text-[var(--text-muted)] mx-auto mb-3 opacity-50" />
          <h3 className="text-sm font-semibold text-[var(--text-primary)]">No surveyors found</h3>
          <p className="text-xs text-[var(--text-muted)] mt-1 max-w-md mx-auto">
            {search || countyFilter
              ? 'Try adjusting your search or filters.'
              : 'Verified ISK surveyors who create a public profile will appear here. Be the first — add your firm info in Settings.'}
          </p>
          {!search && !countyFilter && (
            <Link
              href="/settings/profile"
              className="inline-flex items-center gap-1 mt-4 text-xs font-semibold text-[var(--accent)] hover:underline"
            >
              Set up your profile <ChevronRight className="w-3 h-3" />
            </Link>
          )}
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {surveyors.map((s) => {
            const hue = s.fullName.split('').reduce((acc, c) => acc + c.charCodeAt(0), 0) % 360
            return (
              <div
                key={s.id}
                className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-5 hover:border-[var(--accent)]/30 transition-all"
              >
                <div className="flex items-start gap-3 mb-3">
                  <div
                    className="w-11 h-11 rounded-xl flex items-center justify-center text-white text-sm font-bold shrink-0"
                    style={{
                      background: `linear-gradient(135deg, hsl(${hue}, 70%, 50%), hsl(${hue + 40}, 70%, 35%))`,
                    }}
                  >
                    {s.fullName.split(' ').map(n => n[0]).join('').slice(0, 2)}
                  </div>
                  <div className="min-w-0 flex-1">
                    <h3 className="text-sm font-bold text-[var(--text-primary)] truncate">
                      {s.fullName}
                    </h3>
                    {s.county && (
                      <p className="text-xs text-[var(--text-muted)] flex items-center gap-1 mt-0.5">
                        <MapPin className="w-3 h-3" /> {s.county}
                      </p>
                    )}
                  </div>
                  {s.verifiedIsk && (
                    <span className="text-[10px] font-semibold text-emerald-400 bg-emerald-500/10 px-2 py-1 rounded border border-emerald-500/20">
                      Verified
                    </span>
                  )}
                </div>

                {s.iskNumber && (
                  <p className="text-[10px] font-mono text-[var(--text-muted)] mb-2">
                    ISK {s.iskNumber}
                  </p>
                )}

                {s.firmName && (
                  <p className="text-xs text-[var(--text-secondary)] mb-2">{s.firmName}</p>
                )}

                {s.specialty && (
                  <span
                    className="inline-block px-2 py-1 rounded text-[10px] font-semibold mb-3"
                    style={{
                      background: `hsl(${hue}, 60%, 15%)`,
                      color: `hsl(${hue}, 80%, 70%)`,
                    }}
                  >
                    {s.specialty}
                  </span>
                )}

                <div className="pt-3 border-t border-[var(--border-color)] flex items-center justify-between text-[11px]">
                  <span className="text-[var(--text-muted)]">
                    {s.projectsCount} project{s.projectsCount !== 1 ? 's' : ''}
                  </span>
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* Back to community */}
      <div className="mt-8">
        <Link
          href="/community"
          className="text-xs text-[var(--accent)] hover:underline flex items-center gap-1"
        >
          ← Back to Community
        </Link>
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import {
  ArrowRight,
  Search,
  FileCheck2,
  ChevronRight,
  ArrowUpRight,
  Sparkles,
} from 'lucide-react'

// ---------------------------------------------------------------------------
// Data
// ---------------------------------------------------------------------------

interface CommunityStats {
  stats: {
    totalSurveyors: number
    totalReviewsCompleted: number
    totalCPDPointsAwarded: number
  }
  openPeerReviews: number
  surveyorsCount: number
}

/**
 * AUDIT FIX (2026-07-05): Removed hardcoded fake surveyor directory,
 * equipment listings, peer review queue, discussion topics, and regional
 * coverage. These were all fabricated data that gave a false impression
 * of an active community. Now fetched from real APIs:
 *   - /api/community/surveyors (verified ISK users + project counts)
 *   - /api/marketplace/listings (real equipment listings)
 *   - /api/community/stats (real aggregate counts)
 * If no data exists yet, the UI shows honest empty states instead of fake
 * surveyors with fabricated ratings and license numbers.
 */

interface SurveyorProfile {
  id: string
  fullName: string
  iskNumber?: string
  verifiedIsk: boolean
  firmName?: string
  county?: string
  specialty?: string
  avatarUrl?: string
  projectsCount: number
}

interface EquipmentListing {
  id: string
  title: string
  type: string // 'sale' | 'rent'
  condition: string // 'new' | 'excellent' | 'good' | 'fair' | 'for_parts'
  location: string
  price: number
  currency: string
  rentPeriod?: string
  brand?: string
  model?: string
}

function formatCount(value: number | undefined) {
  return (value ?? 0).toLocaleString()
}

function formatPrice(price: number, currency: string, type: string, rentPeriod?: string) {
  const symbols: Record<string, string> = {
    KES: 'KSh', USD: '$', UGX: 'USh', TZS: 'TSh', NGN: '₦', GHS: '₵', ZAR: 'R',
  }
  const sym = symbols[currency] || currency
  if (type === 'rent' && rentPeriod) {
    return `${sym} ${price.toLocaleString()}/${rentPeriod}`
  }
  return `${sym} ${price.toLocaleString()}`
}

/**
 * Countries METARDU supports. The counts shown are fetched from the
 * stats API — these are just the country metadata (flag + description).
 */
const SUPPORTED_COUNTRIES = [
  { region: 'Kenya', flag: 'KE', detail: 'ISK, county & registry workflows' },
  { region: 'Uganda', flag: 'UG', detail: 'Control & infrastructure' },
  { region: 'Tanzania', flag: 'TZ', detail: 'Field crews & equipment' },
  { region: 'Rwanda', flag: 'RW', detail: 'GNSS & topographic teams' },
]

