      <div className="flex flex-wrap gap-2 mb-6">
        {CATEGORIES.map(cat => {
          const Icon = cat === 'All' ? BookOpen : CATEGORY_ICONS[cat]
          return (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                activeCategory === cat
                  ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)]'
                  : 'bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)] text-gray-400 hover:text-gray-300'
              }`}
            >
              {Icon && <Icon className="w-3.5 h-3.5" />}
              {cat}
            </button>
          )
        })}
      </div>

      {/* FAQ list */}
      <div className="space-y-2">
        {filteredFaqs.length === 0 ? (
          <div className="text-center py-12">
            <Search className="w-8 h-8 text-gray-600 mx-auto mb-2" />
            <p className="text-sm text-gray-500">No results found</p>
            <p className="text-xs text-gray-600 mt-1">Try a different search term or category</p>
          </div>
        ) : (
          filteredFaqs.map((faq, idx) => {
            const id = `${faq.category}-${idx}`
            const isExpanded = expandedId === id
            const Icon = CATEGORY_ICONS[faq.category] || BookOpen
            return (
              <div
                key={id}
                className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden"
              >
                <button
                  onClick={() => setExpandedId(isExpanded ? null : id)}
                  className="w-full flex items-center gap-3 px-4 py-3 hover:bg-[var(--bg-tertiary)]/50 transition-colors text-left"
                >
                  <Icon className="w-4 h-4 text-[var(--accent)] shrink-0" />
                  <span className="flex-1 text-sm font-medium text-[var(--text-primary)]">{faq.question}</span>
                  {isExpanded ? <ChevronDown className="w-4 h-4 text-gray-500" /> : <ChevronRight className="w-4 h-4 text-gray-500" />}
                </button>
                {isExpanded && (
                  <div className="px-4 pb-4 pt-1">
                    <div className="flex gap-3">
                      <div className="w-4 shrink-0" />
                      <p className="text-xs text-[var(--text-secondary)] leading-relaxed">{faq.answer}</p>
                    </div>
                  </div>
                )}
              </div>
            )
          })
        )}
      </div>

      {/* Quick links */}
      <div className="mt-12 grid grid-cols-2 md:grid-cols-4 gap-3">
        <QuickLink href="/docs" icon={BookOpen} label="Documentation" />
        <QuickLink href="/docs/quick-start" icon={Compass} label="Quick Start" />
        <QuickLink href="/docs/api" icon={FileText} label="API Reference" />
        <QuickLink href="/community" icon={MessageSquare} label="Community" />
      </div>

      {/* Contact support */}
      <div className="mt-8 rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-5">
        <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-3">Still need help?</h3>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          <a href="mailto:support@metardu.com" className="flex items-center gap-2 p-3 rounded-lg bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors">
            <Mail className="w-4 h-4 text-[var(--accent)] shrink-0" />
            <div>
              <p className="text-xs font-medium text-[var(--text-primary)]">Email Support</p>
              <p className="text-[10px] text-gray-500">support@metardu.com</p>
            </div>
          </a>
          <a href="/community" className="flex items-center gap-2 p-3 rounded-lg bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors">
            <MessageSquare className="w-4 h-4 text-[var(--accent)] shrink-0" />
            <div>
              <p className="text-xs font-medium text-[var(--text-primary)]">Community Forum</p>
              <p className="text-[10px] text-gray-500">Ask other surveyors</p>
            </div>
          </a>
          <div className="flex items-center gap-2 p-3 rounded-lg bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)]">
            <Phone className="w-4 h-4 text-gray-500 shrink-0" />
            <div>
              <p className="text-xs font-medium text-[var(--text-primary)]">Enterprise</p>
              <p className="text-[10px] text-gray-500">Priority support</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function QuickLink({ href, icon: Icon, label }: { href: string; icon: typeof BookOpen; label: string }) {
  return (
    <Link
      href={href}
      className="flex items-center gap-2 p-3 rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] hover:border-[var(--accent)]/30 hover:bg-[var(--bg-tertiary)]/30 transition-colors"
    >
      <Icon className="w-4 h-4 text-[var(--accent)]" />
      <span className="text-xs font-medium text-[var(--text-primary)]">{label}</span>
    </Link>
  )
}

'use client';
import { useState, useCallback, useEffect } from 'react'
import { AlertTriangle } from 'lucide-react'
import { createClient } from '@/lib/api-client/client'
import { detectTotalStationFormat, TotalStationFormat } from '@/lib/import/totalStation/detectFormat'
import { parseGSI } from '@/lib/import/totalStation/parseGSI'
import { parseJobXML } from '@/lib/import/totalStation/parseJobXML'
import { parseTopcon } from '@/lib/import/totalStation/parseTopcon'
import { parseSDR } from '@/lib/import/totalStation/parseSDR'

interface ParsedPoint {
  pointId: string
  easting?: number
  northing?: number
  elevation?: number
  selected: boolean
}

interface Project {
  id: string
  name: string
}

export default function ImportPage() {
  const dbClient = createClient()
  const [file, setFile] = useState<File | null>(null)
  const [content, setContent] = useState<string>('')
  const [format, setFormat] = useState<TotalStationFormat>('unknown')
  const [points, setPoints] = useState<ParsedPoint[]>([])
  const [warnings, setWarnings] = useState<string[]>([])
  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProject, setSelectedProject] = useState<string>('')
  const [importing, setImporting] = useState(false)
  const [imported, setImported] = useState<number | null>(null)
  const [loadingProjects, setLoadingProjects] = useState(true)

  useEffect(() => {
    async function loadProjects() {
      const { data: { session } } = await dbClient.auth.getSession()
      const user = session?.user
      if (!user) return

      const { data } = await dbClient
        .from('projects')
        .select('id, name')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(20)

      if (data) setProjects(data)
      setLoadingProjects(false)
    }
    loadProjects()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0]
    if (!selectedFile) return

    setFile(selectedFile)
    setImported(null)

    const text = await selectedFile.text()
    setContent(text)

    const detectedFormat = detectTotalStationFormat(text, selectedFile.name)
    setFormat(detectedFormat)

    let parsed: any = { records: [], warnings: [] }

    switch (detectedFormat) {
      case 'gsi':
        parsed = parseGSI(text)
        break
      case 'jobxml':
        parsed = parseJobXML(text)
        break
      case 'topcon':
        parsed = parseTopcon(text)
        break
      case 'sokkia':
        parsed = parseSDR(text)
        break
      default:
        setWarnings(['Unknown format. Please try CSV import instead.'])
        return
    }

    setWarnings(parsed.warnings || [])
    setPoints(parsed.records.map((r: any) => ({
      pointId: r.pointId,
      easting: r.easting,
      northing: r.northing,
      elevation: r.elevation,
      selected: true
    })))
  }, [])

  const toggleAll = (select: boolean) => {
    setPoints(points.map((p: any) => ({ ...p, selected: select })))
  }

  const togglePoint = (idx: number) => {
    setPoints(points.map((p, i) => i === idx ? { ...p, selected: !p.selected } : p))
  }

  const handleImport = async () => {
    if (!selectedProject) return

    setImporting(true)
    const selectedPoints = points.filter((p: any) => p.selected)

    const insertData = selectedPoints.map((p: any) => ({
      project_id: selectedProject,
      name: p.pointId,
      easting: p.easting || 0,
      northing: p.northing || 0,
      elevation: p.elevation || 0,
      is_control: false
    }))

    const { error } = await dbClient.from('survey_points').insert(insertData)

    if (error) {
      console.error('Import error:', error)
      setImporting(false)
      return
    }

    setImported(selectedPoints.length)
    setImporting(false)
  }

  const formatNames: Record<TotalStationFormat, string> = {
    gsi: 'Leica GSI',
    jobxml: 'Trimble JobXML',
    topcon: 'Topcon GTS',
    sokkia: 'Sokkia SDR',
    south: 'South NTS/Galaxy',
    csv: 'CSV',
    unknown: 'Unknown'
  }

  const selectedCount = points.filter((p: any) => p.selected).length
  const projectName = projects.find((p: any) => p.id === selectedProject)?.name

  return (
    <div className="min-h-screen py-12">
      <div className="max-w-4xl mx-auto px-6">
        <div className="mb-8 pb-5 border-b border-[var(--border-color)]">
          <div className="font-mono text-[11px] text-[var(--accent)] tracking-[0.12em] uppercase mb-2">
            Field data → Metardu
          </div>
          <h1 className="font-display text-3xl text-[var(--text-primary)] tracking-[-0.025em]">Import field data</h1>
          <p className="text-sm text-[var(--text-secondary)] mt-2">
            Import from any total station, GNSS rover, or drone software. Metardu auto-detects the format.
          </p>
        </div>

        {imported !== null ? (
          <div className="bg-[var(--success)]/10 border border-[var(--success)]/30 rounded-lg p-8 text-center">
            <div className="w-12 h-12 mx-auto mb-4 border border-[var(--success)] flex items-center justify-center">
              <svg className="w-7 h-7 text-[var(--success)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
              </svg>
            </div>
            <h2 className="font-display text-2xl text-[var(--success)] tracking-[-0.02em] mb-2">
              {imported} points imported
            </h2>
            <p className="text-sm text-[var(--text-secondary)] mb-6">
              Successfully imported to {projectName}
            </p>
            <div className="flex gap-3 justify-center">
              <a
                href={`/project/${selectedProject}`}
                className="px-5 py-2.5 bg-[var(--accent)] text-[var(--bg-primary)] font-medium rounded-md hover:bg-[var(--accent-dim)] transition-colors text-sm no-underline"
              >
                Open project →
              </a>
              <button
                onClick={() => { setFile(null); setPoints([]); setImported(null); }}
                className="px-5 py-2.5 border border-[var(--border-color)] text-[var(--text-primary)] font-medium rounded-md hover:bg-[var(--bg-tertiary)] transition-colors text-sm"
              >
                Import More
              </button>
            </div>
          </div>
        ) : (
          <>
            <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-6 mb-8">
              <h2 className="font-display text-xl text-[var(--text-primary)] tracking-[-0.015em] mb-4">Supported formats</h2>
              <p className="text-sm text-[var(--text-secondary)] mb-4">
                Import data directly from your total station, GNSS rover, or drone processing software.
                Metardu auto-detects the format.
              </p>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <FormatBadge color="var(--accent)" name="Leica GSI (.gsi)" />
                <FormatBadge color="var(--accent)" name="Trimble JobXML (.job, .jxl)" />
                <FormatBadge color="var(--accent)" name="Trimble RW5 (.rw5)" />
                <FormatBadge color="var(--accent)" name="Sokkia SDR (.sdr)" />
                <FormatBadge color="var(--accent)" name="Topcon GTS (.gtl, .raw)" />
                <FormatBadge color="var(--accent)" name="South NTS (.dat)" />
                <FormatBadge color="var(--accent)" name="CSV / TXT (.csv, .txt)" />
                <FormatBadge color="var(--accent)" name="DXF (.dxf)" />
                <FormatBadge color="var(--accent)" name="GeoJSON (.geojson)" />
                <FormatBadge color="var(--accent)" name="KML (.kml)" />
                <FormatBadge color="var(--accent)" name="XYZ Point Cloud (.xyz)" />
                <FormatBadge color="var(--accent)" name="LAS / LAZ (.las, .laz)" />
                <FormatBadge color="var(--accent)" name="RINEX (.rnx, .obs)" />
                <FormatBadge color="var(--accent)" name="Pix4D (.p4d)" />
                <FormatBadge color="var(--accent)" name="PLY Mesh (.ply)" />
                <FormatBadge color="var(--accent)" name="XML (.xml)" />
              </div>

              <div className="mt-8">
                <label htmlFor="import-file" className="block">
                  <div aria-label="Drop your file here or click to browse" className="border-2 border-dashed border-[var(--border-hover)] rounded-lg p-12 text-center cursor-pointer hover:border-[var(--accent)] transition-colors">
                    <div className="font-mono text-[10px] text-[var(--text-muted)] tracking-[0.1em] uppercase mb-4">
                      {file ? file.name : 'Drop your file here or click to browse'}
                    </div>
                    <p className="text-sm text-[var(--text-secondary)] font-mono">
                      .gsi · .job · .jxl · .rw5 · .sdr · .csv · .txt · .dxf · .geojson · .kml · .xyz · .las · .laz · .rnx · .p4d · .ply · .xml
                    </p>
                  </div>
                  <input
                    id="import-file"
                    type="file"
                    accept=".gsi,.job,.jxl,.rw5,.sdr,.gtl,.raw,.dat,.csv,.txt,.dxf,.geojson,.json,.kml,.xyz,.las,.laz,.rnx,.obs,.p4d,.ply,.xml"
                    onChange={handleFileChange}
                    className="hidden"
                  />
                </label>
              </div>
            </div>

            {format !== 'unknown' && points.length > 0 && (
              <div className="bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)] p-6 mb-8">
                <div className="flex items-center justify-between mb-4">
                  <div>
                    <h3 className="text-[var(--text-primary)] font-semibold">
                      Format detected: {formatNames[format]}
                    </h3>
                    <p className="text-[var(--text-secondary)] text-sm">
                      {points.length} points found
                    </p>
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => toggleAll(true)}
                      className="text-sm text-amber-500 hover:underline"
                    >
                      Select All
                    </button>
                    <button
                      onClick={() => toggleAll(false)}
                      className="text-sm text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
                    >
                      Deselect All
                    </button>
                  </div>
                </div>

                {warnings.length > 0 && (
                  <div className="bg-amber-900/20 border border-amber-500/50 rounded p-3 mb-4">
                    {warnings.map((w, i) => (
                      <p key={`${w}-${i}`} className="text-amber-400 text-sm"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {w}</p>
                    ))}
                  </div>
                )}

                <div className="max-h-64 overflow-y-auto space-y-2 mb-6">
                  {points.map((p, i) => (
                    <div
                      key={`${p}-${i}`}
                      onClick={() => togglePoint(i)}
                      className={`flex items-center gap-3 p-2 rounded cursor-pointer ${
                        p.selected ? 'bg-amber-500/10' : 'bg-[var(--bg-card)]'
                      }`}
                    >
                      <input aria-label="Selected"
                        type="checkbox"
                        checked={p.selected}
                        onChange={() => togglePoint(i)}
                        className="accent-amber-500"
                      />
                      <span className="text-[var(--text-primary)] font-mono text-sm w-16">{p.pointId}</span>
                      {p.easting !== undefined ? (
                        <span className="text-[var(--text-secondary)] text-xs">
                          E: {p.easting.toFixed(4)} N: {p.northing?.toFixed(4)} Z: {p.elevation?.toFixed(3)}
                        </span>
                      ) : (
                        <span className="text-red-400 text-xs">No coordinates</span>
                      )}
                    </div>
                  ))}
                </div>

                <div className="mb-6">
                  <label htmlFor="import-project" className="block text-sm text-[var(--text-secondary)] mb-2">
                    Import to project:
                  </label>
                  <select
                    id="import-project"
                    value={selectedProject}
                    onChange={(e) => setSelectedProject(e.target.value)}
                    className="w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-4 py-2 text-[var(--text-primary)]"
                  >
                    <option value="">Select a project...</option>
                    {projects.map((proj: any) => (
                      <option key={proj.id} value={proj.id}>{proj.name}</option>
                    ))}
                  </select>
                </div>

                <button
                  onClick={handleImport}
                  disabled={!selectedProject || selectedCount === 0 || importing}
                  className="w-full py-3 bg-amber-500 text-black font-bold rounded hover:bg-amber-400 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {importing ? 'Importing...' : `Import ${selectedCount} Points`}
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  )
}

function FormatBadge({ color, name }: { color: string; name: string }) {
  return (
    <div
      className="p-3 rounded-md border text-center font-mono text-xs"
      style={{
        background: `${color}15`,
        color: color,
        borderColor: `${color}40`,
      }}
    >
      {name}
    </div>
  )
}

'use client';

import { useEffect, useState, Suspense } from 'react'
import { useSearchParams } from 'next/navigation'
import { signIn } from 'next-auth/react'
import { Eye, EyeOff, ArrowLeft, CheckCircle2, ShieldCheck, WifiOff , AlertTriangle } from 'lucide-react'
import MetarduLogo from '@/components/MetarduLogo'
import Image from 'next/image'

type View = 'login' | 'forgot' | 'sent'

/* ── OAuth provider SVG icons (inline for zero-dependency rendering) ── */

function GoogleIcon({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
      <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4" />
      <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
      <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
      <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
    </svg>
  )
}

function MicrosoftIcon({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
      <rect x="1" y="1" width="10" height="10" fill="#F25022" />
      <rect x="13" y="1" width="10" height="10" fill="#7FBA00" />
      <rect x="1" y="13" width="10" height="10" fill="#00A4EF" />
      <rect x="13" y="13" width="10" height="10" fill="#FFB900" />
    </svg>
  )
}

function LoginForm() {
  const searchParams = useSearchParams()

  const [view, setView] = useState<View>('login')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [rememberMe, setRememberMe] = useState(false)
  const [loading, setLoading] = useState(false)
  const [oauthLoading, setOauthLoading] = useState<string | null>(null)
  const [error, setError] = useState('')
  const [emailError, setEmailError] = useState('')
  const [passwordError, setPasswordError] = useState('')
  const [emailTouched, setEmailTouched] = useState(false)
  const [passwordTouched, setPasswordTouched] = useState(false)
  const [imageLoaded, setImageLoaded] = useState(false)

  useEffect(() => { document.title = 'Login — METARDU' }, [])

  useEffect(() => {
    const saved = localStorage.getItem('metardu_remember')
    if (saved === 'true') setRememberMe(true)
  }, [])

  const getRedirectTo = () => {
    const param = searchParams.get('next') || searchParams.get('redirectTo')
    if (param) return decodeURIComponent(param)
    if (typeof window !== 'undefined') {
      return localStorage.getItem('auth:redirect') || '/dashboard'
    }
    return '/dashboard'
  }

  const validateEmail = (value: string) => {
    if (!value) return 'Please enter your email address'
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return 'Please enter a valid email address'
    return ''
  }

  const validatePassword = (value: string) => {
    if (!value) return 'Please enter your password'
    return ''
  }

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setEmailTouched(true)
    setPasswordTouched(true)

    const emailErr = validateEmail(email)
    const passErr = validatePassword(password)
    setEmailError(emailErr)
    setPasswordError(passErr)
    if (emailErr || passErr) {
      return
    }

    setError('')
    setLoading(true)

    try {
      const result = await signIn('credentials', {
        email,
        password,
        redirect: false,
      })

      setLoading(false)

      if (result?.error) {
        // Check if the database is available — if not, show a service-unavailable message
        try {
          const healthRes = await fetch('/api/public/health')
          const healthData = await healthRes.json()
          if (healthData.checks?.database === 'error') {
            setError('Service temporarily unavailable. The database is not reachable. Please try again later.')
            return
          }
        } catch {
          // Health check itself failed — likely a network issue
        }
        setError('Incorrect email or password. Please try again.')
        return
      }
      if (rememberMe) {
        localStorage.setItem('metardu_remember', 'true')
      } else {
        localStorage.removeItem('metardu_remember')
      }

      localStorage.removeItem('auth:redirect')
      window.location.href = getRedirectTo()
    } catch (err) {
      console.error('Login error:', err)
      setLoading(false)
      setError('An error occurred. Please try again.')
    }
  }

  const handleOAuthSignIn = async (provider: 'google' | 'azure-ad') => {
    setError('')
    setOauthLoading(provider)
    try {
      await signIn(provider, {
        callbackUrl: getRedirectTo(),
      })
    } catch (err) {
      console.error('OAuth sign-in error:', err)
      setOauthLoading(null)
      setError('Unable to sign in with this provider. Please try again.')
    }
  }

  const handleForgotPassword = async (e: React.FormEvent) => {
    e.preventDefault()
    setEmailTouched(true)

    const emailErr = validateEmail(email)
    setEmailError(emailErr)
    if (emailErr) return

    setLoading(true)
    try {
      const res = await fetch('/api/auth/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      })
      if (res.ok) {
        setView('sent')
      } else {
        setError('Unable to send reset link. Please try again.')
      }
    } catch {
      setError('A network error occurred. Please check your connection and try again.')
    }
    setLoading(false)
  }

  return (
    <div className="relative min-h-screen w-full overflow-hidden">
      {/* ──────────────────────────────────────────────────────────────
          LIGHT TOPOGRAPHIC MAP BACKGROUND
          Subtle overlays preserve the delicate contour detail while
          giving the dark glass card maximum contrast.
         ────────────────────────────────────────────────────────────── */}
      <div className="absolute inset-0 -z-10">
        {/* Pre-loaded topographic PNG — optimized with next/image */}
        <Image
          src="/images/signin-topo.jpg"
          alt="World topographic contour map"
          onLoad={() => setImageLoaded(true)}
          fill
          priority
          sizes="100vw"
          className={[
            'object-cover transition-opacity duration-700',
            imageLoaded ? 'opacity-100' : 'opacity-0',
          ].join(' ')}
        />
        {/* Fallback background color while image loads */}
        <div
          aria-hidden
          className="absolute inset-0 bg-[var(--bg-secondary)]"
          style={{ zIndex: -1 }}
        />
        {/* Very subtle warm tint — lets contour lines shine through */}
        <div className="absolute inset-0 bg-gradient-to-br from-[var(--bg-primary)]/30 via-[var(--bg-secondary)]/20 to-[var(--bg-primary)]/35" />
        {/* Bottom darkening so card/badges contrast cleanly */}
        <div className="absolute inset-0 bg-gradient-to-t from-[var(--bg-primary)]/60 via-transparent to-[var(--bg-primary)]/15" />
        {/* Soft vignette */}
        <div
          aria-hidden
          className="absolute inset-0"
          style={{
            background:
              'radial-gradient(ellipse at center, transparent 45%, rgba(26,24,22,0.35) 100%)',
          }}
        />
      </div>

      {/* Top brand bar */}
      <header className="relative z-10 flex items-center justify-between px-5 sm:px-8 lg:px-12 py-5">
        <a
          href="/"
          className="group inline-flex items-center gap-3 drop-shadow-lg"
        >
          <MetarduLogo size={36} showWordmark={true} color="#FFFFFF" />
        </a>
        <div className="hidden sm:flex items-center gap-2 text-xs text-white/90 px-3 py-1.5 rounded-full bg-[var(--bg-card)]/50 border border-white/20 backdrop-blur-md drop-shadow-md">
          <ShieldCheck className="w-3.5 h-3.5 text-[var(--accent)]" />
          <span>East Africa Survey Platform</span>
        </div>
      </header>

      {/* Main content */}
      <main className="relative z-10 flex min-h-[calc(100vh-88px)] items-center justify-center px-4 sm:px-6 pb-12">
        <div className="w-full max-w-md">
          {/* Dark frosted-glass card — pops against the light topo map */}
          <div className="relative rounded-2xl border border-white/10 bg-[var(--bg-card)]/80 backdrop-blur-2xl shadow-[0_24px_80px_-12px_rgba(0,0,0,0.7)] overflow-hidden">
            {/* Top accent stripe */}
            <div className="h-1 w-full bg-gradient-to-r from-[var(--accent)] via-orange-400 to-[var(--accent)]" />

            <div className="px-6 sm:px-8 py-8 sm:py-10">
              {view === 'login' && (
                <>
                  <div className="mb-8">
                    <h2 className="text-2xl sm:text-3xl font-bold text-white">
                      Welcome back
                    </h2>
                    <p className="text-sm text-white/60 mt-1.5">
                      Sign in to your METARDU account
                    </p>
                  </div>

                  {/* ── OAuth Buttons (shown first for prominence) ── */}
                  <div className="space-y-3">
                    <button
                      type="button"
                      onClick={() => handleOAuthSignIn('google')}
                      disabled={oauthLoading !== null}
                      className="w-full py-3 px-4 bg-white/[0.07] border border-white/15 hover:bg-white/[0.12] hover:border-white/25 text-white font-medium rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3"
                    >
                      {oauthLoading === 'google' ? (
                        <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                      ) : (
                        <GoogleIcon className="w-5 h-5 shrink-0" />
                      )}
                      {oauthLoading === 'google' ? 'Connecting...' : 'Continue with Google'}
                    </button>

                    <button
                      type="button"
                      onClick={() => handleOAuthSignIn('azure-ad')}
                      disabled={oauthLoading !== null}
                      className="w-full py-3 px-4 bg-white/[0.07] border border-white/15 hover:bg-white/[0.12] hover:border-white/25 text-white font-medium rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3"
                    >
                      {oauthLoading === 'azure-ad' ? (
                        <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                      ) : (
                        <MicrosoftIcon className="w-5 h-5 shrink-0" />
                      )}
                      {oauthLoading === 'azure-ad' ? 'Connecting...' : 'Continue with Microsoft'}
                    </button>
                  </div>

                  {/* ── Divider ── */}
                  <div className="relative my-6">
                    <div className="absolute inset-0 flex items-center">
                      <div className="w-full border-t border-white/10" />
                    </div>
                    <div className="relative flex justify-center text-xs">
                      <span className="px-3 bg-transparent text-white/40 uppercase tracking-wider">
                        or sign in with email
                      </span>
                    </div>
                  </div>

                  {/* ── Credentials Form ── */}
                  <form onSubmit={handleLogin} className="space-y-5">
                    {error && (
                      <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-lg text-red-300 text-sm flex items-start gap-2">
                        <span className="mt-0.5"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /></span>
                        <span>{error}</span>
                      </div>
                    )}

                    <div>
                      <label htmlFor="login-email" className="block text-xs font-medium uppercase tracking-wider text-white/60 mb-2">
                        Email
                      </label>
                      <input
                        id="login-email"
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        onBlur={() => {
                          setEmailTouched(true)
                          setEmailError(validateEmail(email))
                        }}
                        className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-lg text-white placeholder-white/30 focus:border-[var(--accent)] focus:bg-white/10 focus:ring-2 focus:ring-[var(--accent)]/30 focus:outline-none transition-all"
                        autoComplete="email"
                        placeholder="you@example.com"
                      />
                      {emailTouched && emailError && (
                        <p className="text-red-300 text-xs mt-1.5">{emailError}</p>
                      )}
                    </div>

                    <div>
                      <label htmlFor="login-password" className="block text-xs font-medium uppercase tracking-wider text-white/60 mb-2">
                        Password
                      </label>
                      <div className="relative">
                        <input
                          id="login-password"
                          type={showPassword ? 'text' : 'password'}
                          value={password}
                          onChange={(e) => setPassword(e.target.value)}
                          onBlur={() => {
                            setPasswordTouched(true)
                            setPasswordError(validatePassword(password))
                          }}
                          className="w-full px-4 py-3 pr-11 bg-white/5 border border-white/10 rounded-lg text-white placeholder-white/30 focus:border-[var(--accent)] focus:bg-white/10 focus:ring-2 focus:ring-[var(--accent)]/30 focus:outline-none transition-all"
                          autoComplete="current-password"
                          placeholder="••••••••"
                        />
                        <button
                          type="button"
                          onClick={() => setShowPassword(!showPassword)}
                          className="absolute right-3 top-1/2 -translate-y-1/2 text-white/40 hover:text-white/80 transition-colors p-1"
                          aria-label={showPassword ? 'Hide password' : 'Show password'}
                        >
                          {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                        </button>
                      </div>
                      {passwordTouched && passwordError && (
                        <p className="text-red-300 text-xs mt-1.5">{passwordError}</p>
                      )}
                    </div>

                    <div className="flex items-center justify-between">
                      <label className="flex items-center gap-2 cursor-pointer group">
                        <input aria-label="Rememberme"
                          type="checkbox"
                          checked={rememberMe}
                          onChange={(e) => setRememberMe(e.target.checked)}
                          className="w-4 h-4 rounded border-white/20 bg-white/5 text-[var(--accent)] focus:ring-[var(--accent)]/50"
                        />
                        <span className="text-sm text-white/70 group-hover:text-white/90 transition-colors">
                          Remember me
                        </span>
                      </label>
                      <button
                        type="button"
                        onClick={() => {
                          setView('forgot')
                          setError('')
                        }}
                        className="text-sm text-[var(--accent)] hover:text-amber-300 hover:underline transition-colors"
                      >
                        Forgot password?
                      </button>
                    </div>

                    <button
                      type="submit"
                      disabled={loading}
                      className="w-full py-3.5 bg-gradient-to-r from-[var(--accent)] to-[var(--accent-dim)] hover:from-amber-400 hover:to-[var(--accent)] text-black font-semibold rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-lg shadow-[var(--accent)]/25"
                    >
                      {loading && (
                        <span className="w-4 h-4 border-2 border-black/40 border-t-black rounded-full animate-spin" />
                      )}
                      {loading ? 'Signing in...' : 'Sign In'}
                    </button>
                  </form>

                  <p className="text-center mt-6 text-white/60 text-sm">
                    Don&apos;t have an account?{' '}
                    <a
                      href="/register"
                      className="text-[var(--accent)] hover:text-amber-300 hover:underline font-medium transition-colors"
                    >
                      Create one
                    </a>
                  </p>
                </>
              )}

              {view === 'forgot' && (
                <>
                  <div className="mb-8">
                    <h2 className="text-2xl sm:text-3xl font-bold text-white">
                      Reset your password
                    </h2>
                    <p className="text-sm text-white/60 mt-1.5">
                      Enter your email and we&apos;ll send you a reset link.
                    </p>
                  </div>

                  <form onSubmit={handleForgotPassword} className="space-y-5">
                    <div>
                      <label htmlFor="forgot-email" className="block text-xs font-medium uppercase tracking-wider text-white/60 mb-2">
                        Email
                      </label>
                      <input
                        id="forgot-email"
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        onBlur={() => {
                          setEmailTouched(true)
                          setEmailError(validateEmail(email))
                        }}
                        className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-lg text-white placeholder-white/30 focus:border-[var(--accent)] focus:bg-white/10 focus:ring-2 focus:ring-[var(--accent)]/30 focus:outline-none transition-all"
                        autoComplete="email"
                        placeholder="you@example.com"
                      />
                      {emailTouched && emailError && (
                        <p className="text-red-300 text-xs mt-1.5">{emailError}</p>
                      )}
                    </div>

                    <button
                      type="submit"
                      disabled={loading}
                      className="w-full py-3.5 bg-gradient-to-r from-[var(--accent)] to-[var(--accent-dim)] hover:from-amber-400 hover:to-[var(--accent)] text-black font-semibold rounded-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-lg shadow-[var(--accent)]/25"
                    >
                      {loading && (
                        <span className="w-4 h-4 border-2 border-black/40 border-t-black rounded-full animate-spin" />
                      )}
                      {loading ? 'Sending...' : 'Send Reset Link'}
                    </button>
                  </form>

                  <button
                    onClick={() => {
                      setView('login')
                      setError('')
                      setEmailTouched(false)
                      setPasswordTouched(false)
                    }}
                    className="flex items-center gap-2 text-sm text-[var(--accent)] hover:text-amber-300 hover:underline mt-6 transition-colors"
                  >
                    <ArrowLeft className="w-4 h-4" /> Back to sign in
                  </button>
                </>
              )}

              {view === 'sent' && (
                <div className="text-center py-2">
                  <div className="grid place-items-center w-16 h-16 rounded-full bg-[var(--accent)]/15 ring-1 ring-[var(--accent)]/30 mx-auto mb-5">
                    <svg className="w-8 h-8 text-[var(--accent)]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                    </svg>
                  </div>
                  <h2 className="text-2xl font-bold text-white mb-2">Check your email</h2>
                  <p className="text-white/60 mb-1">We&apos;ve sent a password reset link to:</p>
                  <p className="text-white font-medium mb-6">{email}</p>

                  <button
                    onClick={() => {
                      setView('login')
                      setError('')
                      setEmailTouched(false)
                      setPasswordTouched(false)
                    }}
                    className="flex items-center gap-2 text-sm text-[var(--accent)] hover:text-amber-300 hover:underline mx-auto transition-colors"
                  >
                    <ArrowLeft className="w-4 h-4" /> Back to sign in
                  </button>
                </div>
              )}
            </div>
          </div>

          {/* Trust badges below the card — float over world map */}
          <div className="mt-6 flex flex-wrap items-center justify-center gap-2.5">
            {[
              { icon: CheckCircle2, text: 'Kenya Survey Compliant' },
              { icon: WifiOff, text: 'Works Offline' },
              { icon: ShieldCheck, text: 'Trusted Across East Africa' },
            ].map((item) => (
              <div
                key={item.text}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-white/[0.04] border border-white/10 backdrop-blur-md text-xs text-white/75"
              >
                <item.icon className="w-3.5 h-3.5 text-[var(--accent)] shrink-0" />
                <span>{item.text}</span>
              </div>
            ))}
          </div>
        </div>
      </main>
    </div>
  )
}

export default function LoginPage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
          <div className="w-6 h-6 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
        </div>
      }
    >
      <LoginForm />
    </Suspense>
  )
}

'use client'
/**
 * METARDU Global Map Page — Premium OpenLayers Interface
 *
 * ┌──────────────────────────────────────────────────────────────┐
 * │  ARCHITECTURE: Split into sub-components for maintainability │
 * │                                                              │
 * │  MapClient.tsx    → Orchestrator (state + wiring)           │
 * │  ├─ hooks/useMapInit.ts        → Map initialization         │
 * │  ├─ hooks/useMapBasemaps.ts    → Basemap layer management   │
 * │  ├─ hooks/useMapState.ts       → View persistence           │
 * │  ├─ hooks/useMapInteractions.ts → Draw/Measure/GPS/Export   │
 * │  ├─ components/MapToolbar.tsx   → Left sidebar (context)    │
 * │  ├─ components/MapOverlays.tsx  → Zoom/GPS/Stakeout (ctx)   │
 * │  ├─ components/MapStatusBar.tsx → Bottom coord bar (ctx)    │
 * │  ├─ components/MapLoadingOverlay.tsx → Loading/Error (ctx)  │
 * │  ├─ components/MapNotifications.tsx  → Toast (context)      │
 * │  ├─ components/MapCoordSearch.tsx   → Coord search (ctx)    │
 * │  ├─ components/CogoInfoPanel.tsx    → COGO traverse (ctx)   │
 * │  ├─ components/CogoToolsPanel.tsx   → COGO compute (ctx)    │
 * │  ├─ components/RotationControl.tsx  → North arrow reset     │
 * │  ├─ components/MapPrintButton.tsx   → Print button (ctx)    │
 * │  ├─ LayerControl (reusable, props)  → Grid/XYZ/WMS/Opacity │
 * │  ├─ VertexEditToolbar (ctx version) → Vertex editing + snap │
 * │  ├─ ProjectionSwitcher (context)    → CRS switching         │
 * │  ├─ StakeoutPanel (context)         → GPS stakeout HUD      │
 * │  ├─ SchemeLayerPanel (context)      → Scheme layer controls │
 * │  ├─ OfflineTileDownloader (context) → Offline tile dialog   │
 * │  ├─ SheetLayout (dynamic)           → Print layout overlay  │
 * │  └─ MapReactContext                 → Zero-prop data bus    │
 * │                                                              │
 * │  Performance optimizations:                                  │
 * │  - All sub-components wrapped in React.memo                 │
 * │  - useMemo for stable object references                     │
 * │  - useCallback for all interaction handlers                 │
 * │  - 100ms mouse position throttle                            │
 * │  - Dynamic imports for all OpenLayers modules               │
 * │  - Tile cache size 2048 for all basemaps                    │
 * │  - Map state persistence every 10s (not per move)           │
 * │  - Safety timeout: force ready after 5s                     │
 * └──────────────────────────────────────────────────────────────┘
 *
 * Features:
 *  - Draw interaction (Point, Line, Polygon, Circle)
 *  - Modify interaction (vertex editing)
 *  - Select interaction + Popup overlays
 *  - Undo / Redo history (via useMapHistory hook)
 *  - Measurement (Distance & Area with bearing)
 *  - GeoJSON / KML / WKT import & export (DXF/LandXML export only — no import)
 *  - Drag & Drop file import
 *  - MousePosition (live EPSG:21037 coords)
 *  - Geolocation (GPS tracking)
 *  - GPS Stakeout mode (Pro+)
 *  - Cluster source for project markers
 *  - Multiple basemaps (OSM, Satellite, Dark, Terrain)
 *  - Bearing/distance annotations on drawn features
 *  - Save drawn features to project
 *  - Offline tile download (Pro+)
 *  - URL param ?projectId=xxx deep linking
 *  - Keyboard shortcuts (Ctrl+Z/Y, Del, Esc)
 *  - Map state persistence (localStorage)
 *  - Coordinate search (lat/lon, UTM, DMS)
 */

import React, { useEffect, useRef, useState, useCallback, useMemo } from 'react'
