  activeDigitizingTool: 'draw' | 'split' | 'merge' | 'reshape' | 'rotate' | 'offset' | null
  setActiveDigitizingTool: (tool: 'draw' | 'split' | 'merge' | 'reshape' | 'rotate' | 'offset' | null) => void
