  handleOpacityChange: (val: number) => void
  handleCoordSearch: (input: string) => Promise<void>
  stakeoutInfo: () => { distance: number; bearing: number; dE: number; dN: number } | null
  deactivateStakeout: () => void
  getMapExtent: () => Promise<any>

  // ── Scheme actions ──
  loadSchemeData: () => void
