}

// ─── Context Creation ────────────────────────────────────────────────────

const MapReactContext = createContext<MapContextValue | null>(null)

// ─── Provider Component ──────────────────────────────────────────────────

export function MapProvider({
  value,
  children,
}: {
  value: MapContextValue
  children: React.ReactNode
}) {
  return (
    <MapReactContext.Provider value={value}>
      {children}
    </MapReactContext.Provider>
  )
}

// ─── Consumer Hook ───────────────────────────────────────────────────────

/**
 * useMapContext — Access the map state and actions from any child component.
 *
 * Must be used within a <MapProvider>.
 *
 * @example
 * ```tsx
 * function MyMapWidget() {
 *   const { drawMode, featureCount, toggleDraw } = useMapContext()
 *   return <button onClick={() => toggleDraw('Point')}>Draw Point ({featureCount})</button>
 * }
 * ```
 */
export function useMapContext(): MapContextValue {
  const ctx = useContext(MapReactContext)
  if (!ctx) {
    throw new Error('useMapContext must be used within a <MapProvider>')
  }
  return ctx
}

'use client'
/**
 * BookmarkPanel — Save and restore map view presets
 *
 * Saves current center, zoom, and rotation to localStorage.
 * Lists saved bookmarks with click-to-navigate and delete buttons.
 */

import React, { memo, useState, useCallback, useEffect } from 'react'
import { Bookmark, Trash2, Navigation, ChevronDown } from 'lucide-react'
import { useMapContext } from '@/app/map/MapReactContext'

const STORAGE_KEY = 'metardu-bookmarks'

interface BookmarkEntry {
  id: string
  label: string
  center: [number, number]
  zoom: number
  rotation: number
  createdAt: string
}

function loadBookmarks(): BookmarkEntry[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    return raw ? JSON.parse(raw) : []
  } catch {
    return []
  }
}

function saveBookmarks(entries: BookmarkEntry[]) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(entries))
}

export const BookmarkPanel = memo(function BookmarkPanel() {
  const { mapInstance } = useMapContext()
  const [bookmarks, setBookmarks] = useState<BookmarkEntry[]>([])
  const [label, setLabel] = useState('')
  const [collapsed, setCollapsed] = useState(false)

  // Load bookmarks on mount
  useEffect(() => {
    setBookmarks(loadBookmarks())
  }, [])

  const saveCurrentView = useCallback(() => {
    if (!mapInstance.current) return

    const view = mapInstance.current.getView()
    const center = view.getCenter()
    const zoom = view.getZoom()
    const rotation = view.getRotation()

    if (!center || zoom == null) return

    const entry: BookmarkEntry = {
      id: `bm-${Date.now()}`,
      label: label.trim() || `View ${bookmarks.length + 1}`,
      center: [center[0], center[1]],
      zoom,
      rotation: rotation || 0,
      createdAt: new Date().toISOString(),
    }

    const updated = [...bookmarks, entry]
    setBookmarks(updated)
    saveBookmarks(updated)
    setLabel('')
  }, [mapInstance, label, bookmarks])

  const navigateToBookmark = useCallback((entry: BookmarkEntry) => {
    if (!mapInstance.current) return
    const view = mapInstance.current.getView()
    view.animate({
      center: entry.center,
      zoom: entry.zoom,
      rotation: entry.rotation,
      duration: 600,
    })
  }, [mapInstance])

  const deleteBookmark = useCallback((id: string) => {
    const updated = bookmarks.filter(b => b.id !== id)
    setBookmarks(updated)
    saveBookmarks(updated)
  }, [bookmarks])

  return (
    <div className="bg-[var(--bg-secondary)]/90 backdrop-blur-xl border border-[var(--border-color)]/[0.06] rounded-lg w-56">
      {/* Header */}
      <div
        className="flex items-center justify-between px-3 py-2 cursor-pointer select-none"
        onClick={() => setCollapsed(!collapsed)}
      >
        <div className="flex items-center gap-2">
          <Bookmark className="w-3.5 h-3.5 text-[var(--accent)]" />
          <span className="text-[10px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold">
            Bookmarks
          </span>
        </div>
        <ChevronDown className={`w-3 h-3 text-[var(--text-muted)] transition-transform ${collapsed ? '-rotate-90' : ''}`} />
      </div>

      {!collapsed && (
        <div className="px-3 pb-3 space-y-2">
          {/* Save current view */}
          <div className="flex gap-1.5">
            <input
              type="text"
              value={label}
              onChange={(e) => setLabel(e.target.value)}
              aria-label="Bookmark name" placeholder="Bookmark name"
              className="flex-1 h-7 px-2 text-[10px] bg-[var(--bg-card)]/5 border border-[var(--border-color)]/[0.08] rounded text-[var(--text-primary)] placeholder-gray-600 focus:outline-none focus:border-[var(--accent)]/40"
              onKeyDown={(e) => { if (e.key === 'Enter') saveCurrentView() }}
            />
            <button
              onClick={saveCurrentView}
              className="h-7 px-2 text-[10px] bg-[var(--accent)]/20 text-[var(--accent)] border border-[var(--accent)]/30 rounded hover:bg-[var(--accent)]/30 transition-colors"
              title="Save current view"
            >
              Save
            </button>
          </div>

          {/* Bookmark list */}
          {bookmarks.length === 0 ? (
            <div className="text-[9px] text-[var(--text-muted)] text-center py-1">
              No saved views
            </div>
          ) : (
            <div className="space-y-1 max-h-32 overflow-y-auto">
              {bookmarks.map((entry) => (
                <div
                  key={entry.id}
                  className="flex items-center justify-between px-2 py-1 bg-[var(--bg-card)]/[0.03] rounded group hover:bg-[var(--bg-card)]/[0.06] transition-colors"
                >
                  <button
                    onClick={() => navigateToBookmark(entry)}
                    className="flex items-center gap-1.5 flex-1 min-w-0 text-left"
                  >
                    <Navigation className="w-3 h-3 text-[var(--text-muted)] flex-shrink-0" />
                    <span className="text-[10px] text-[var(--text-secondary)] truncate">{entry.label}</span>
                  </button>
                  <button
                    onClick={() => deleteBookmark(entry.id)}
                    className="p-0.5 text-[var(--text-muted)] hover:text-[var(--error)] opacity-0 group-hover:opacity-100 transition-opacity"
                    title="Delete bookmark"
                  >
                    <Trash2 className="w-3 h-3" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  )
})

'use client'
/**
 * CogoInfoPanel — Survey of Kenya compliant COGO readout
 *
 * Computes and displays traverse legs (bearing + distance) between
 * consecutive parcel vertices, plus total perimeter and enclosed area.
 *
 * Uses:
 *   - distanceBearing from @/lib/engine/distance (WCB 0-360°)
 *   - coordinateArea  from @/lib/engine/area    (Shoelace method)
 *   - vertexEditingVertices from MapReactContext
 *
 * SoK formatting:
 *   - Bearings in DMS  (DDD° MM' SS.SSS")
 *   - Distances in metres (3 dp)
 *   - Area in m², Ha, Acres
 */

import React, { useMemo, useState, memo } from 'react'
import { ChevronDown, ChevronUp, X, Ruler, MapPin } from 'lucide-react'
import { useMapContext } from '@/app/map/MapReactContext'
import { distanceBearing } from '@/lib/engine/distance'
import { coordinateArea } from '@/lib/engine/area'
import type { Point2D } from '@/lib/engine/types'

// ─── Types ────────────────────────────────────────────────────────────────

interface TraverseLegDisplay {
  fromIndex: number
  toIndex: number
  bearing: number
  bearingDMS: string
  quadrant: string
  distance: number
  deltaE: number
  deltaN: number
}

// ─── Computation helpers ──────────────────────────────────────────────────

function computeTraverseLegs(
  vertices: Array<{ easting: number; northing: number }>
): TraverseLegDisplay[] {
  if (vertices.length < 2) return []

  const legs: TraverseLegDisplay[] = []
  const n = vertices.length

  for (let i = 0; i < n; i++) {
    const from: Point2D = { easting: vertices[i].easting, northing: vertices[i].northing }
    const to: Point2D = {
      easting: vertices[(i + 1) % n].easting,
      northing: vertices[(i + 1) % n].northing,
    }
    const result = distanceBearing(from, to)
    legs.push({
      fromIndex: i,
      toIndex: (i + 1) % n,
      bearing: result.bearing,
      bearingDMS: result.bearingDMS,
      quadrant: result.quadrant,
      distance: result.distance,
      deltaE: result.deltaE,
      deltaN: result.deltaN,
    })
  }

  return legs
}

function computeAreaInfo(
  vertices: Array<{ easting: number; northing: number }>
) {
  const points: Point2D[] = vertices.map(v => ({
    easting: v.easting,
    northing: v.northing,
  }))
  return coordinateArea(points)
}

// ─── Component ────────────────────────────────────────────────────────────

function CogoInfoPanelInner() {
  const { vertexEditingVertices } = useMapContext()
  const [expanded, setExpanded] = useState(true)
  const [showDetails, setShowDetails] = useState(false)

  const legs = useMemo(
    () => computeTraverseLegs(vertexEditingVertices),
    [vertexEditingVertices]
  )

  const areaInfo = useMemo(
    () => computeAreaInfo(vertexEditingVertices),
    [vertexEditingVertices]
  )

  const totalDistance = useMemo(
    () => legs.reduce((sum, leg) => sum + leg.distance, 0),
    [legs]
  )

  // ── No vertices: show minimal placeholder ──
  if (vertexEditingVertices.length === 0) {
    return (
      <div
        className="bg-[var(--bg-card)] rounded-lg shadow-lg border border-[var(--border-color)] select-none"
        style={{ fontFamily: 'Calibri, sans-serif', minWidth: 260 }}
      >
        <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--border-color)]">
          <div className="flex items-center gap-2">
            <Ruler className="w-4 h-4 text-[#1B3A5C]" />
            <span className="text-sm font-semibold text-[#1B3A5C]">
              COGO Traverse
            </span>
          </div>
        </div>
        <div className="px-3 py-3 text-xs text-[var(--text-muted)] text-center">
          Load a scheme to view traverse data
        </div>
      </div>
    )
  }

  return (
    <div
      className="bg-[var(--bg-card)] rounded-lg shadow-lg border border-[var(--border-color)] select-none"
      style={{ fontFamily: 'Calibri, sans-serif', minWidth: 300, maxWidth: 400 }}
    >
      {/* ── Header ── */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <Ruler className="w-4 h-4 text-[#1B3A5C]" />
          <span className="text-sm font-semibold text-[#1B3A5C]">
            COGO Traverse
          </span>
          <span className="text-[10px] text-[var(--text-secondary)] ml-1">
            {vertexEditingVertices.length} vertices
          </span>
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={() => setExpanded(v => !v)}
            className="p-1 hover:bg-[var(--bg-secondary)] rounded transition-colors"
            title={expanded ? 'Collapse' : 'Expand'}
          >
            {expanded ? (
              <ChevronUp className="w-3.5 h-3.5 text-[var(--text-muted)]" />
            ) : (
              <ChevronDown className="w-3.5 h-3.5 text-[var(--text-muted)]" />
            )}
          </button>
        </div>
      </div>

      {expanded && (
        <>
          {/* ── Traverse legs table ── */}
          <div className="max-h-64 overflow-y-auto">
            <table className="w-full text-[11px]">
              <thead className="bg-[var(--bg-secondary)] sticky top-0">
                <tr className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider">
                  <th className="px-2 py-1.5 text-left font-semibold">Leg</th>
                  <th className="px-2 py-1.5 text-left font-semibold">Bearing</th>
                  <th className="px-2 py-1.5 text-right font-semibold">Distance</th>
                </tr>
              </thead>
              <tbody>
                {legs.map((leg, idx) => (
                  <tr
                    key={`${leg}-${idx}`}
                    className={idx % 2 === 0 ? 'bg-[var(--bg-card)]' : 'bg-[var(--bg-secondary)]/50'}
                  >
                    <td className="px-2 py-1 text-[var(--text-muted)] font-mono">
                      V{leg.fromIndex + 1}&rarr;V{leg.toIndex + 1}
                    </td>
                    <td className="px-2 py-1 font-mono text-[#1B3A5C]">
                      {leg.bearingDMS}
                    </td>
