              <div className="text-[10px] font-mono text-[var(--text-secondary)]">
                <span className="text-[var(--text-secondary)] mr-0.5">E</span>
                {areaInfo.centroid.easting.toFixed(3)}
                <span className="text-[var(--text-secondary)] mx-1">|</span>
                <span className="text-[var(--text-secondary)] mr-0.5">N</span>
                {areaInfo.centroid.northing.toFixed(3)}
              </div>
              <div className="text-[9px] text-[var(--text-secondary)] mt-0.5">
                Method: {areaInfo.method}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  )
}

export const CogoInfoPanel = memo(CogoInfoPanelInner)

'use client'
/**
 * CogoToolsPanel — Interactive COGO computation tools for surveyors
 *
 * Provides four SoK-compliant computation methods:
 * 1. Radiation — compute point from station + bearing + distance
 * 2. Bearing Intersection — intersect two rays from known stations
 * 3. Distance Intersection — intersect two circles (trilateration)
 * 4. Resection (Tienstra) — compute position from 3 known points + angles
 *
 * All inputs accept bearings in DDD.MMSS (Kenya field book convention)
 * or decimal degrees. Results displayed in DMS with SoK formatting.
 * Computed points can be added to the map as features.
 *
 * Reads mapInstance from MapReactContext for adding result features.
 */

import React, { useState, useCallback, memo } from 'react'
import { Crosshair, Circle, Triangle, Target, Plus, RotateCcw } from 'lucide-react'
import { useMapContext } from '@/app/map/MapReactContext'
import { radiation } from '@/lib/engine/cogo'
import { bearingIntersection } from '@/lib/engine/cogo'
import { distanceIntersection } from '@/lib/engine/cogo'
import { tienstraResection } from '@/lib/engine/cogo'
import { distanceBearing } from '@/lib/engine/distance'
import { bearingToString, parseFieldAngle } from '@/lib/engine/angles'
import type { Point2D } from '@/lib/engine/types'

// ─── Shared Helpers ──────────────────────────────────────────────────────

/** Parse bearing input — accepts DDD.MMSS, decimal degrees, or DMS string */
function parseBearing(input: string): number | null {
  const trimmed = input.trim()
  if (!trimmed) return null
  return parseFieldAngle(trimmed)
}

/** Format a computed point for display */
function formatPoint(p: Point2D): string {
  return `E ${p.easting.toFixed(3)}  N ${p.northing.toFixed(3)}`
}

/** Input field with label */
function Field({ label, value, onChange, placeholder, type = 'text' }: {
  label: string
  value: string
  onChange: (v: string) => void
  placeholder?: string
  type?: string
}) {
  const id = React.useId()
  return (
    <div className="flex items-center gap-2">
      <label htmlFor={id} className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider w-12 shrink-0">
        {label}
      </label>
      <input id={id}
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="flex-1 px-2 py-1 text-xs font-mono bg-[var(--bg-card)] border border-[var(--border-color)] rounded
                   focus:border-[#1B3A5C] focus:outline-none focus:ring-1 focus:ring-[#1B3A5C]/30
                   transition-colors"
      />
    </div>
  )
}

/** Compute button */
function ComputeButton({ onClick, disabled }: { onClick: () => void; disabled?: boolean }) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className="w-full py-1.5 text-xs font-semibold rounded-lg transition-colors
                 bg-[#1B3A5C] text-[var(--text-primary)] hover:bg-[#142d49]
                 disabled:bg-gray-300 disabled:text-[var(--text-muted)] disabled:cursor-not-allowed"
    >
      Compute
    </button>
  )
}

/** Result display */
function ResultDisplay({ children }: { children: React.ReactNode }) {
  return (
    <div className="bg-[var(--primary-blue)]/10 border border-blue-100 rounded-lg px-3 py-2 space-y-1">
      {children}
    </div>
  )
}

// ─── Tab Definitions ─────────────────────────────────────────────────────

type TabId = 'radiation' | 'bearing-int' | 'distance-int' | 'resection'

const TABS: { id: TabId; label: string; icon: React.ReactNode }[] = [
  { id: 'radiation', label: 'Radiation', icon: <Crosshair className="w-3.5 h-3.5" /> },
  { id: 'bearing-int', label: 'Bearing Int', icon: <Target className="w-3.5 h-3.5" /> },
  { id: 'distance-int', label: 'Dist Int', icon: <Circle className="w-3.5 h-3.5" /> },
  { id: 'resection', label: 'Resection', icon: <Triangle className="w-3.5 h-3.5" /> },
]

// ─── Radiation Panel ─────────────────────────────────────────────────────

function RadiationPanel({ onAddPoint }: { onAddPoint: (p: Point2D, label: string) => void }) {
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [bearing, setBearing] = useState('')
  const [distance, setDistance] = useState('')
  const [result, setResult] = useState<{ point: Point2D; bearing: number; distance: number } | null>(null)
  const [error, setError] = useState('')

  const compute = useCallback(() => {
    setError('')
    setResult(null)
    const e = parseFloat(easting)
    const n = parseFloat(northing)
    const b = parseBearing(bearing)
    const d = parseFloat(distance)

    if (isNaN(e) || isNaN(n)) { setError('Invalid station coordinates'); return }
    if (b === null) { setError('Invalid bearing (use DDD.MMSS or decimal)'); return }
    if (isNaN(d) || d <= 0) { setError('Distance must be positive'); return }

    const res = radiation({ easting: e, northing: n }, b, d)
    setResult({ point: res.point, bearing: res.bearing, distance: res.distance })
  }, [easting, northing, bearing, distance])

  return (
    <div className="space-y-2.5">
      <div className="text-[10px] text-[var(--text-secondary)] leading-relaxed">
        Compute a new point from a known station, bearing (WCB), and distance.
      </div>
      <div className="space-y-1.5">
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold">Station</div>
        <Field label="E" value={easting} onChange={setEasting} placeholder="e.g. 512345.678" />
        <Field label="N" value={northing} onChange={setNorthing} placeholder="e.g. 9834567.890" />
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold pt-1">Observation</div>
        <Field label="Brg" value={bearing} onChange={setBearing} placeholder="e.g. 47.2314 or 47.3861" />
        <Field label="Dist" value={distance} onChange={setDistance} placeholder="e.g. 125.450" type="number" />
      </div>
      <ComputeButton onClick={compute} />
      {error && <div className="text-[10px] text-[var(--error)]">{error}</div>}
      {result && (
        <ResultDisplay>
          <div className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider font-semibold">Computed Point</div>
          <div className="text-xs font-mono text-[#1B3A5C]">{formatPoint(result.point)}</div>
          <div className="text-[10px] text-[var(--text-muted)]">
            Bearing: {bearingToString(result.bearing)} &middot; Dist: {result.distance.toFixed(3)} m
          </div>
          <button
            onClick={() => onAddPoint(result.point, 'Rad')}
            className="flex items-center gap-1 mt-1 px-2 py-0.5 text-[10px] font-semibold
                       bg-[#1B3A5C] text-[var(--text-primary)] rounded hover:bg-[#142d49] transition-colors"
          >
            <Plus className="w-3 h-3" /> Add to Map
          </button>
        </ResultDisplay>
      )}
    </div>
  )
}

// ─── Bearing Intersection Panel ──────────────────────────────────────────

function BearingIntersectionPanel({ onAddPoint }: { onAddPoint: (p: Point2D, label: string) => void }) {
  const [eA, setEA] = useState('')
  const [nA, setNA] = useState('')
  const [brgA, setBrgA] = useState('')
  const [eB, setEB] = useState('')
  const [nB, setNB] = useState('')
  const [brgB, setBrgB] = useState('')
  const [result, setResult] = useState<{ point: Point2D; distA: number; distB: number } | null>(null)
  const [error, setError] = useState('')

  const compute = useCallback(() => {
    setError('')
    setResult(null)
    const ea = parseFloat(eA), na = parseFloat(nA), ba = parseBearing(brgA)
    const eb = parseFloat(eB), nb = parseFloat(nB), bb = parseBearing(brgB)

    if ([ea, na, eb, nb].some(isNaN)) { setError('Invalid station coordinates'); return }
    if (ba === null || bb === null) { setError('Invalid bearing (use DDD.MMSS or decimal)'); return }

    const res = bearingIntersection(
      { easting: ea, northing: na }, ba,
      { easting: eb, northing: nb }, bb,
    )
    if (!res) { setError('Bearings are parallel — no intersection'); return }
    setResult({ point: res.point, distA: res.distanceFromA, distB: res.distanceFromB })
  }, [eA, nA, brgA, eB, nB, brgB])

  return (
    <div className="space-y-2.5">
      <div className="text-[10px] text-[var(--text-secondary)] leading-relaxed">
        Intersect two rays defined by station + bearing (WCB). Returns the intersection point.
      </div>
      <div className="space-y-1.5">
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold">Station A</div>
        <Field label="E" value={eA} onChange={setEA} placeholder="512345.678" />
        <Field label="N" value={nA} onChange={setNA} placeholder="9834567.890" />
        <Field label="Brg" value={brgA} onChange={setBrgA} placeholder="47.2314" />
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold pt-1">Station B</div>
        <Field label="E" value={eB} onChange={setEB} placeholder="512500.000" />
        <Field label="N" value={nB} onChange={setNB} placeholder="9834600.000" />
        <Field label="Brg" value={brgB} onChange={setBrgB} placeholder="312.1500" />
      </div>
      <ComputeButton onClick={compute} />
      {error && <div className="text-[10px] text-[var(--error)]">{error}</div>}
      {result && (
        <ResultDisplay>
          <div className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider font-semibold">Intersection</div>
          <div className="text-xs font-mono text-[#1B3A5C]">{formatPoint(result.point)}</div>
          <div className="text-[10px] text-[var(--text-muted)]">
            Dist from A: {result.distA.toFixed(3)} m &middot; Dist from B: {result.distB.toFixed(3)} m
          </div>
          <button
            onClick={() => onAddPoint(result.point, 'Int')}
            className="flex items-center gap-1 mt-1 px-2 py-0.5 text-[10px] font-semibold
                       bg-[#1B3A5C] text-[var(--text-primary)] rounded hover:bg-[#142d49] transition-colors"
          >
            <Plus className="w-3 h-3" /> Add to Map
          </button>
        </ResultDisplay>
      )}
    </div>
  )
}

// ─── Distance Intersection Panel ─────────────────────────────────────────

function DistanceIntersectionPanel({ onAddPoint }: { onAddPoint: (p: Point2D, label: string) => void }) {
  const [eA, setEA] = useState('')
  const [nA, setNA] = useState('')
  const [distA, setDistA] = useState('')
  const [eB, setEB] = useState('')
  const [nB, setNB] = useState('')
  const [distB, setDistB] = useState('')
  const [result, setResult] = useState<[Point2D, Point2D] | null>(null)
  const [selectedIdx, setSelectedIdx] = useState<0 | 1>(0)
  const [error, setError] = useState('')

  const compute = useCallback(() => {
    setError('')
    setResult(null)
    const ea = parseFloat(eA), na = parseFloat(nA), da = parseFloat(distA)
    const eb = parseFloat(eB), nb = parseFloat(nB), db = parseFloat(distB)

    if ([ea, na, da, eb, nb, db].some(isNaN)) { setError('Invalid inputs'); return }
    if (da <= 0 || db <= 0) { setError('Distances must be positive'); return }

    const res = distanceIntersection(
      { easting: ea, northing: na }, da,
      { easting: eb, northing: nb }, db,
    )
    if (!res) { setError('Circles do not intersect'); return }
    setResult(res)
  }, [eA, nA, distA, eB, nB, distB])

  const selected = result ? result[selectedIdx] : null

  return (
    <div className="space-y-2.5">
      <div className="text-[10px] text-[var(--text-secondary)] leading-relaxed">
        Intersect two circles (trilateration). Returns two possible points — select the correct one.
      </div>
      <div className="space-y-1.5">
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold">Station A</div>
        <Field label="E" value={eA} onChange={setEA} placeholder="512345.678" />
        <Field label="N" value={nA} onChange={setNA} placeholder="9834567.890" />
        <Field label="Dist" value={distA} onChange={setDistA} placeholder="125.450" type="number" />
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold pt-1">Station B</div>
        <Field label="E" value={eB} onChange={setEB} placeholder="512500.000" />
        <Field label="N" value={nB} onChange={setNB} placeholder="9834600.000" />
        <Field label="Dist" value={distB} onChange={setDistB} placeholder="98.760" type="number" />
      </div>
      <ComputeButton onClick={compute} />
      {error && <div className="text-[10px] text-[var(--error)]">{error}</div>}
      {result && (
        <ResultDisplay>
          <div className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider font-semibold">Two Solutions</div>
          <div className="flex gap-2">
            {([0, 1] as const).map((idx) => (
              <button
                key={`btn-${idx}`}
                onClick={() => setSelectedIdx(idx)}
                className={`flex-1 px-2 py-1 text-[10px] font-mono rounded border transition-colors ${
                  selectedIdx === idx
                    ? 'border-[#1B3A5C] bg-[#1B3A5C] text-[var(--text-primary)]'
                    : 'border-[var(--border-color)] bg-[var(--bg-card)] text-[var(--text-muted)] hover:border-gray-300'
                }`}
              >
                P{idx + 1}: {formatPoint(result[idx])}
              </button>
            ))}
          </div>
          {selected && (
            <button
              onClick={() => onAddPoint(selected, 'DistInt')}
              className="flex items-center gap-1 mt-1 px-2 py-0.5 text-[10px] font-semibold
                         bg-[#1B3A5C] text-[var(--text-primary)] rounded hover:bg-[#142d49] transition-colors"
            >
              <Plus className="w-3 h-3" /> Add P{selectedIdx + 1} to Map
            </button>
          )}
        </ResultDisplay>
      )}
    </div>
  )
}

// ─── Resection Panel ─────────────────────────────────────────────────────

function ResectionPanel({ onAddPoint }: { onAddPoint: (p: Point2D, label: string) => void }) {
  const [e1, setE1] = useState(''), [n1, setN1] = useState('')
  const [e2, setE2] = useState(''), [n2, setN2] = useState('')
  const [e3, setE3] = useState(''), [n3, setN3] = useState('')
  const [a12, setA12] = useState(''), [a23, setA23] = useState('')
  const [result, setResult] = useState<{ point: Point2D; d1: number; d2: number; d3: number } | null>(null)
  const [error, setError] = useState('')

  const compute = useCallback(() => {
    setError('')
    setResult(null)
    const pe1 = parseFloat(e1), pn1 = parseFloat(n1)
    const pe2 = parseFloat(e2), pn2 = parseFloat(n2)
    const pe3 = parseFloat(e3), pn3 = parseFloat(n3)
    const ang12 = parseFloat(a12), ang23 = parseFloat(a23)

    if ([pe1, pn1, pe2, pn2, pe3, pn3, ang12, ang23].some(isNaN)) {
      setError('Invalid inputs'); return
    }
    if (ang12 <= 0 || ang23 <= 0 || (ang12 + ang23) >= 360) {
      setError('Angles must be positive and sum < 360°'); return
    }

    const res = tienstraResection(
      { easting: pe1, northing: pn1 },
      { easting: pe2, northing: pn2 },
      { easting: pe3, northing: pn3 },
      ang12, ang23,
    )
    if (!res) { setError('Resection failed — check geometry'); return }
    setResult({ point: res.point, d1: res.distanceToP1, d2: res.distanceToP2, d3: res.distanceToP3 })
  }, [e1, n1, e2, n2, e3, n3, a12, a23])

  return (
    <div className="space-y-2.5">
      <div className="text-[10px] text-[var(--text-secondary)] leading-relaxed">
        Tienstra three-point resection. Angles measured at unknown station between rays to control points.
      </div>
      <div className="space-y-1.5">
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold">Control P1</div>
        <Field label="E" value={e1} onChange={setE1} placeholder="512345.678" />
        <Field label="N" value={n1} onChange={setN1} placeholder="9834567.890" />
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold pt-1">Control P2</div>
        <Field label="E" value={e2} onChange={setE2} placeholder="512500.000" />
        <Field label="N" value={n2} onChange={setN2} placeholder="9834600.000" />
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold pt-1">Control P3</div>
        <Field label="E" value={e3} onChange={setE3} placeholder="512600.000" />
        <Field label="N" value={n3} onChange={setN3} placeholder="9834700.000" />
        <div className="text-[9px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold pt-1">Observed Angles</div>
        <Field label="∠12" value={a12} onChange={setA12} placeholder="e.g. 45.5000 (45°30')" />
        <Field label="∠23" value={a23} onChange={setA23} placeholder="e.g. 52.1500 (52°15')" />
      </div>
      <ComputeButton onClick={compute} />
      {error && <div className="text-[10px] text-[var(--error)]">{error}</div>}
      {result && (
        <ResultDisplay>
          <div className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider font-semibold">Resection Point</div>
          <div className="text-xs font-mono text-[#1B3A5C]">{formatPoint(result.point)}</div>
          <div className="text-[10px] text-[var(--text-muted)] space-y-0.5">
            <div>Dist to P1: {result.d1.toFixed(3)} m</div>
            <div>Dist to P2: {result.d2.toFixed(3)} m</div>
            <div>Dist to P3: {result.d3.toFixed(3)} m</div>
          </div>
          <button
            onClick={() => onAddPoint(result.point, 'Res')}
            className="flex items-center gap-1 mt-1 px-2 py-0.5 text-[10px] font-semibold
                       bg-[#1B3A5C] text-[var(--text-primary)] rounded hover:bg-[#142d49] transition-colors"
          >
            <Plus className="w-3 h-3" /> Add to Map
          </button>
        </ResultDisplay>
      )}
    </div>
  )
}

// ─── Main CogoToolsPanel ─────────────────────────────────────────────────

function CogoToolsPanelInner() {
  const { mapInstance } = useMapContext()
  const [activeTab, setActiveTab] = useState<TabId>('radiation')
  const [expanded, setExpanded] = useState(true)

  // ── Add computed point to map as a vector feature ──
  const handleAddPoint = useCallback(async (point: Point2D, labelPrefix: string) => {
    const map = mapInstance.current
    if (!map) return

    try {
      const { default: Feature } = await import('ol/Feature')
      const { default: Point } = await import('ol/geom/Point')
      const { default: VectorSource } = await import('ol/source/Vector')
      const { default: VectorLayer } = await import('ol/layer/Vector')
      const { default: Style } = await import('ol/style/Style')
      const { default: Circle } = await import('ol/style/Circle')
      const { default: Fill } = await import('ol/style/Fill')
      const { default: Stroke } = await import('ol/style/Stroke')
      const { transform } = await import('ol/proj')
      const { to21037, SRID_21037, SRID_3857 } = await import('@/lib/map/projection')

      // Transform from EPSG:21037 to map projection (3857)
      const coord3857 = transform([point.easting, point.northing], SRID_21037, SRID_3857)

      const feature = new Feature({
        geometry: new Point(coord3857),
        name: `${labelPrefix} ${point.easting.toFixed(1)}/${point.northing.toFixed(1)}`,
        easting: point.easting,
        northing: point.northing,
      })

      // Check if COGO results layer already exists
      const layers = map.getLayers().getArray()
      let cogoLayer = layers.find((l: any) => l.get('cogoResults') === true)

      if (!cogoLayer) {
        const source = new VectorSource({ features: [feature] })
        cogoLayer = new VectorLayer({
          source,
          style: new Style({
            image: new Circle({
              radius: 6,
              fill: new Fill({ color: '#D17B47' }),
              stroke: new Stroke({ color: '#fff', width: 2 }),
            }),
          }),
        })
        ;(cogoLayer as any).set('cogoResults', true)
        ;(cogoLayer as any).set('name', 'COGO Results')
        map.addLayer(cogoLayer)
      } else {
        ;(cogoLayer as any).getSource().addFeature(feature)
      }

      // Zoom to the new point
      map.getView().animate({ center: coord3857, zoom: 17, duration: 500 })
    } catch (err) {
      console.error('[CogoToolsPanel] Failed to add point to map:', err)
    }
  }, [mapInstance])

  return (
    <div
      className="bg-[var(--bg-card)] rounded-lg shadow-lg border border-[var(--border-color)] select-none"
      style={{ fontFamily: 'Calibri, sans-serif', width: 300 }}
    >
      {/* ── Header ── */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <Crosshair className="w-4 h-4 text-[#1B3A5C]" />
          <span className="text-sm font-semibold text-[#1B3A5C]">
            COGO Tools
          </span>
        </div>
        <button
          onClick={() => setExpanded(v => !v)}
          className="p-1 hover:bg-[var(--bg-secondary)] rounded transition-colors text-[var(--text-muted)]"
          title={expanded ? 'Collapse' : 'Expand'}
        >
          <RotateCcw className={`w-3.5 h-3.5 transition-transform ${expanded ? 'rotate-180' : ''}`} />
        </button>
      </div>

      {expanded && (
        <>
          {/* ── Tab bar ── */}
          <div className="flex border-b border-[var(--border-color)]">
            {TABS.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`flex-1 flex items-center justify-center gap-1 px-1 py-1.5 text-[9px] font-semibold
                           transition-colors border-b-2 ${
                             activeTab === tab.id
                               ? 'text-[#1B3A5C] border-[#1B3A5C] bg-[var(--primary-blue)]/10/50'
                               : 'text-[var(--text-secondary)] border-transparent hover:text-[var(--text-muted)] hover:bg-[var(--bg-secondary)]'
                           }`}
                title={tab.label}
              >
                {tab.icon}
                <span className="hidden sm:inline">{tab.label}</span>
              </button>
            ))}
          </div>

          {/* ── Tab content ── */}
          <div className="px-3 py-2.5 max-h-[60vh] overflow-y-auto">
            {activeTab === 'radiation' && <RadiationPanel onAddPoint={handleAddPoint} />}
            {activeTab === 'bearing-int' && <BearingIntersectionPanel onAddPoint={handleAddPoint} />}
            {activeTab === 'distance-int' && <DistanceIntersectionPanel onAddPoint={handleAddPoint} />}
            {activeTab === 'resection' && <ResectionPanel onAddPoint={handleAddPoint} />}
          </div>

          {/* ── Footer hint ── */}
          <div className="px-3 py-1.5 border-t border-[var(--border-color)] bg-[var(--bg-secondary)]/50">
            <div className="text-[9px] text-[var(--text-secondary)]">
              Bearings: DDD.MMSS (e.g. 47.2314 = 47° 23' 14") or decimal degrees
            </div>
          </div>
        </>
      )}
    </div>
  )
}

export const CogoToolsPanel = memo(CogoToolsPanelInner)

'use client'
/**
 * GpsTrackPanel — GPS track logging panel
 *
 * Start/Stop GPS track logging. When started, accumulates GPS positions from
 * context. When stopped, creates a LineString feature from the accumulated
 * positions and adds it to the map as a vector layer (orange line, 3px).
 * Shows total track distance and point count.
 */

import React, { memo, useState, useCallback, useRef, useEffect } from 'react'
import { Play, Square, MapPin, ChevronDown } from 'lucide-react'
import { useMapContext } from '@/app/map/MapReactContext'

export const GpsTrackPanel = memo(function GpsTrackPanel() {
  const { mapInstance, gpsPos, gpsTracking } = useMapContext()
  const [isTracking, setIsTracking] = useState(false)
  const [trackPoints, setTrackPoints] = useState<Array<[number, number]>>([])
  const [pointCount, setPointCount] = useState(0)
  const [totalDistance, setTotalDistance] = useState(0)
  const trackLayerRef = useRef<any>(null)

  // Accumulate GPS positions when tracking is active
  useEffect(() => {
    if (!isTracking || !gpsPos || !mapInstance.current) return

    // Capture current GPS position for the async closure
    const currentGpsPos = gpsPos
    let cancelled = false

    async function addTrackPoint() {
      if (cancelled) return
      try {
        const { fromLonLat } = await import('ol/proj')
        const coord = fromLonLat([currentGpsPos.lon, currentGpsPos.lat]) as [number, number]

        setTrackPoints((prev) => {
          const updated = [...prev, coord]

          // Calculate distance increment
          if (updated.length >= 2) {
            const last = updated[updated.length - 2]
            const dx = coord[0] - last[0]
            const dy = coord[1] - last[1]
            const dist = Math.sqrt(dx * dx + dy * dy)
            // Convert from meters (EPSG:3857 units at equator) — approximate
            const distMeters = dist * Math.cos((currentGpsPos.lat * Math.PI) / 180)
            setTotalDistance((d) => d + Math.abs(distMeters))
          }

          setPointCount(updated.length)
          return updated
        })
      } catch {
        // Skip this point
      }
    }

    addTrackPoint()
    return () => { cancelled = true }
  }, [isTracking, gpsPos, mapInstance])

  const startTracking = useCallback(() => {
    setTrackPoints([])
    setPointCount(0)
    setTotalDistance(0)
    setIsTracking(true)
  }, [])

  const stopTracking = useCallback(async () => {
    setIsTracking(false)

    if (trackPoints.length < 2 || !mapInstance.current) return

    try {
      const [
        { default: VectorSource },
        { default: VectorLayer },
        { default: LineString },
        { default: Feature },
        { default: Style },
        { default: Stroke },
        { default: GeoJSONFormat },
      ] = await Promise.all([
        import('ol/source/Vector'),
        import('ol/layer/Vector'),
        import('ol/geom/LineString'),
        import('ol/Feature'),
        import('ol/style/Style'),
        import('ol/style/Stroke'),
        import('ol/format/GeoJSON'),
      ])

      const geometry = new LineString(trackPoints)
      const feature = new Feature({ geometry })
      const trackDate = new Date().toISOString()
      feature.set('trackLog', true)
      feature.set('trackDate', trackDate)
      feature.set('trackPointCount', trackPoints.length)

      // Remove previous track layer if it exists
      if (trackLayerRef.current) {
        mapInstance.current.removeLayer(trackLayerRef.current)
      }

      const source = new VectorSource({ features: [feature] })
      const layer = new VectorLayer({
        source,
        style: new Style({
          stroke: new Stroke({
            color: '#D17B47',
            width: 3,
          }),
        }),
        zIndex: 60,
      })

      mapInstance.current.addLayer(layer)
      trackLayerRef.current = layer

      // ── Persist track to localStorage (survives reload) ──
      try {
        const fmt = new GeoJSONFormat()
        const geojson = fmt.writeFeatureObject(feature, {
          featureProjection: 'EPSG:3857',
          dataProjection: 'EPSG:4326',
        })
        const trackKey = `metardu:gps-track:${trackDate}`
        const trackData = {
          date: trackDate,
          pointCount: trackPoints.length,
          geojson,
          totalDistance: totalDistance.toFixed(1),
        }
        // Store in a list of tracks
        const existingTracks = JSON.parse(localStorage.getItem('metardu:gps-tracks') || '[]')
        existingTracks.push(trackData)
        // Keep last 50 tracks
        if (existingTracks.length > 50) existingTracks.shift()
        localStorage.setItem('metardu:gps-tracks', JSON.stringify(existingTracks))
        localStorage.setItem(trackKey, JSON.stringify(trackData))
      } catch {
        // localStorage might be full — track still visible on map
      }
    } catch (err) {
      console.error('[GpsTrackPanel] Failed to create track layer:', err)
    }
  }, [trackPoints, mapInstance, totalDistance])

  const formatDistance = (meters: number): string => {
    if (meters >= 1000) {
      return `${(meters / 1000).toFixed(2)} km`
    }
    return `${meters.toFixed(0)} m`
  }

  return (
    <div className="bg-[var(--bg-secondary)]/90 backdrop-blur-xl border border-[var(--border-color)]/[0.06] rounded-lg w-56">
      {/* Header */}
      <div className="flex items-center justify-between px-3 py-2">
        <div className="flex items-center gap-2">
          <MapPin className="w-3.5 h-3.5 text-[var(--accent)]" />
          <span className="text-[10px] text-[var(--text-secondary)] uppercase tracking-wider font-semibold">
            GPS Track
          </span>
        </div>
      </div>

      <div className="px-3 pb-3 space-y-2">
        {/* Start/Stop buttons */}
        <div className="flex gap-2">
          {!isTracking ? (
            <button
              onClick={startTracking}
              disabled={!gpsTracking}
              className="flex-1 h-7 flex items-center justify-center gap-1.5 text-[10px] bg-[var(--accent)]/20 text-[var(--accent)] border border-[var(--accent)]/30 rounded hover:bg-[var(--accent)]/30 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              title={gpsTracking ? 'Start track logging' : 'Enable GPS first'}
            >
              <Play className="w-3 h-3" />
              Start
            </button>
          ) : (
            <button
              onClick={stopTracking}
              className="flex-1 h-7 flex items-center justify-center gap-1.5 text-[10px] bg-[var(--error)]/20 text-[var(--error)] border border-red-500/30 rounded hover:bg-[var(--error)]/30 transition-colors"
              title="Stop track logging and save"
            >
              <Square className="w-3 h-3" />
              Stop &amp; Save
            </button>
          )}
        </div>

        {/* Stats */}
        {isTracking && (
          <div className="flex items-center justify-between px-2 py-1.5 bg-[var(--bg-card)]/[0.03] rounded">
            <div className="flex items-center gap-1">
              <div className="w-1.5 h-1.5 rounded-full bg-[var(--error)] animate-pulse" />
              <span className="text-[10px] text-[var(--text-secondary)]">Recording</span>
            </div>
            <span className="text-[10px] text-[var(--text-secondary)] font-mono">{pointCount} pts</span>
          </div>
        )}

        {(pointCount > 0 || totalDistance > 0) && (
          <div className="flex items-center justify-between px-2 py-1.5 bg-[var(--bg-card)]/[0.03] rounded">
            <span className="text-[10px] text-[var(--text-secondary)]">Distance</span>
            <span className="text-[10px] text-[var(--text-secondary)] font-mono">{formatDistance(totalDistance)}</span>
          </div>
        )}

        {!gpsTracking && !isTracking && (
          <div className="text-[9px] text-[var(--text-muted)] text-center py-0.5">
            Enable GPS tracking to log tracks
          </div>
        )}
      </div>
    </div>
  )
})

'use client'

/**
 * MapInteractionToggle — Mobile gesture lock for the OpenLayers map
 *
 * Problem: On mobile, single-finger drag pans the map, which hijacks page scroll.
 * Solution: Require two-finger drag to pan/zoom the map on touch devices.
 *
 * T1.5g FIX (2026-07-10): Migrated from raw absolute positioning to
 * MapOverlaySlot. The gesture-lock button was at 'absolute bottom-20 left-3
 * z-[1000]' which collided with other bottom-left overlays. Now uses
 * bottom-left anchor with order=50 (above other controls).
 */

import { useEffect, useState, useCallback } from 'react'
import { Lock, Unlock, Hand } from 'lucide-react'
import { MapOverlaySlot } from '@/app/map/components/MapOverlayManager'

type LockState = 'locked' | 'unlocked'
const STORAGE_KEY = 'metardu:map-gesture-lock'

export function MapInteractionToggle({ mapInstance }: { mapInstance: React.MutableRefObject<any> }) {
  const [lockState, setLockState] = useState<LockState>('locked')
  const [isMobile, setIsMobile] = useState(false)
  const [showHint, setShowHint] = useState(true)

  useEffect(() => {
    const checkMobile = () => {
      const mobile = window.matchMedia('(max-width: 1023px)').matches ||
        'ontouchstart' in window ||
        navigator.maxTouchPoints > 0
      setIsMobile(mobile)
      if (!mobile) setLockState('unlocked')
    }
    checkMobile()
    window.addEventListener('resize', checkMobile)
    const saved = localStorage.getItem(STORAGE_KEY) as LockState | null
    if (saved) setLockState(saved)
    const hintTimer = setTimeout(() => setShowHint(false), 5000)
    return () => {
      window.removeEventListener('resize', checkMobile)
      clearTimeout(hintTimer)
    }
  }, [])

  const applyLock = useCallback(async (locked: boolean) => {
    if (!mapInstance.current) return
    try {
      const map = mapInstance.current
      const interactions = map.getInteractions()
      const { default: DragPan } = await import('ol/interaction/DragPan')
      const { platformModifierKeyOnly } = await import('ol/events/condition')
      let dragPan: any = null
      interactions.forEach((interaction: any) => {
        if (interaction instanceof DragPan) dragPan = interaction
      })
      if (!dragPan) return
      // OL 10.x dropped the public setCondition() method — the pan condition is
      // a private `condition_` field assigned in the constructor. Assign it
      // directly (the field is read on every pointer event), while still
      // supporting the older setCondition() API for other OL versions.
      const applyCondition = (fn: any) => {
        if (typeof (dragPan as any).setCondition === 'function') {
          ;(dragPan as any).setCondition(fn)
        } else {
          ;(dragPan as any).condition_ = fn
        }
      }
      if (locked) {
        applyCondition((event: any) => {
          if (event.originalEvent && event.originalEvent.touches) {
            return event.originalEvent.touches.length >= 2
          }
          if (event.originalEvent && event.originalEvent.ctrlKey) return true
          if (!('ontouchstart' in window) && navigator.maxTouchPoints === 0) return true
          return false
        })
      } else {
        applyCondition(platformModifierKeyOnly)
      }
    } catch (err) {
      console.warn('[MapInteractionToggle] Failed to apply lock:', err)
    }
  }, [mapInstance])

  useEffect(() => {
    if (isMobile) applyLock(lockState === 'locked')
  }, [lockState, isMobile, applyLock])

  useEffect(() => {
    if (!isMobile) return
    const interval = setInterval(() => {
      if (mapInstance.current && lockState === 'locked') applyLock(true)
    }, 2000)
    return () => clearInterval(interval)
  }, [isMobile, lockState, mapInstance, applyLock])

  const toggleLock = useCallback(() => {
    setLockState(prev => {
      const next = prev === 'locked' ? 'unlocked' : 'locked'
      localStorage.setItem(STORAGE_KEY, next)
      setShowHint(true)
      setTimeout(() => setShowHint(false), 3000)
      return next
    })
  }, [])

  if (!isMobile) return null

  return (
    <>
      <MapOverlaySlot id="gesture-lock" anchor="bottom-left" order={50} layer="STAKEOUT">
        <button
          onClick={toggleLock}
          className={`flex items-center justify-center w-12 h-12 rounded-xl backdrop-blur-xl border transition-all duration-200 shadow-lg ${
            lockState === 'locked'
              ? 'bg-[var(--accent)]/15 border-[var(--accent)]/30 text-[var(--accent)]'
              : 'bg-[var(--bg-secondary)]/80 border-[var(--border-color)]/[0.06] text-[var(--text-secondary)]'
          }`}
          title={lockState === 'locked' ? 'Map locked — tap to unlock single-finger pan' : 'Map unlocked — tap to lock'}
          aria-label={lockState === 'locked' ? 'Unlock map gestures' : 'Lock map gestures'}
        >
          {lockState === 'locked' ? <Lock className="w-5 h-5" /> : <Unlock className="w-5 h-5" />}
        </button>
      </MapOverlaySlot>
      {lockState === 'locked' && showHint && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[999] pointer-events-none">
          <div className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-[var(--bg-secondary)]/90 backdrop-blur-xl border border-[var(--accent)]/20 shadow-2xl animate-in fade-in duration-300">
            <Hand className="w-4 h-4 text-[var(--accent)]" />
            <span className="text-xs text-[var(--text-primary)] font-medium">Use two fingers to pan the map</span>
          </div>
        </div>
      )}
    </>
  )
}

'use client'

/**
 * MapOverlayManager — Anchor-based overlay positioning system
 *
 * PROBLEM
 * -------
 * The previous approach let every floating overlay component set its own
 * `absolute top-X right-Y z-N` pixels. Result: 28 floating elements across
 * 9 z-index bands with no shared logic. Panels overlapped, a compass rendered
 * behind the Layers panel, a print icon floated orphaned, and every "fix"
 * just relocated the collision.
 *
 * SOLUTION
 * --------
 * A single overlay context that manages anchor zones. Every overlay registers
 * { id, anchor, order, priority } and the manager positions it within its zone
 * using MEASURED heights (not assumed fixed heights) so panels of different
 * sizes stack without overlapping.
 *
 * Anchor zones:
 *   top-left      — panel toggle, hamburger
 *   top-right     — zoom controls, projection switcher, rotation, north arrow, layers panel
 *   top-center    — survey workflow badge, project count
 *   bottom-left   — offline tiles, vertex edit toolbar, GPS badge
 *   bottom-right  — print button, stakeout HUD
 *   bottom-center — coordinate status bar (full width)
 *
 * Z-index layers (shared enum — no component sets its own z):
 *   BASE       = 10   — coordinate bar, watermark
 *   CONTROLS   = 20   — zoom, GPS, rotation, offline tiles, vertex toolbar
 *   PANELS     = 30   — layers panel, scheme panel, snapping options
 *   DOCK       = 40   — tool dock (left sidebar)
 *   STAKEOUT   = 50   — stakeout HUD (above panels when active)
 *   MODAL      = 1000 — loading overlay, error overlay, stakeout radar
 *   TOAST      = 1001 — notifications
 *
 * USAGE
 * -----
 * Wrap the map in <MapOverlayProvider> and render <MapOverlayZone> for each
 * anchor. Each overlay uses <MapOverlaySlot> instead of raw absolute positioning:
 *
 *   <MapOverlaySlot id="layers-panel" anchor="top-right" order={5} layer="PANELS">
 *     <SchemeLayerPanel />
 *   </MapOverlaySlot>
 *
 * The slot measures its rendered height with a ref and reports it to the zone.
 * The zone stacks children with a gap, top-down (for top anchors) or
 * bottom-up (for bottom anchors).
 */

import React, {
  createContext,
  useContext,
  useRef,
  useState,
  useCallback,
  useMemo,
  type ReactNode,
} from 'react'

// ─── Z-Index Layers (shared enum) ───────────────────────────────────────────

export const OVERLAY_Z = {
  BASE: 10,
  CONTROLS: 20,
  PANELS: 30,
  DOCK: 40,
  STAKEOUT: 50,
  MODAL: 1000,
  TOAST: 1001,
} as const

export type OverlayLayer = keyof typeof OVERLAY_Z

// ─── Anchor Zones ───────────────────────────────────────────────────────────

export type OverlayAnchor =
  | 'top-left'
  | 'top-right'
  | 'top-center'
  | 'bottom-left'
  | 'bottom-right'
  | 'bottom-center'

// ─── Registration Types ─────────────────────────────────────────────────────

interface OverlayRegistration {
  id: string
  anchor: OverlayAnchor
  order: number // lower = closer to the anchor edge
  layer: OverlayLayer
  height: number // measured height in px (updated by the slot ref)
}

interface OverlayContextValue {
  /** Register an overlay — returns an unregister function */
  register: (reg: Omit<OverlayRegistration, 'height'>) => () => void
  /** Update the measured height of an overlay (called by the slot ref) */
  setHeight: (id: string, height: number) => void
  /** Get all registrations for a given anchor, sorted by order */
  getZone: (anchor: OverlayAnchor) => OverlayRegistration[]
}

const OverlayContext = createContext<OverlayContextValue | null>(null)

// ─── Provider ───────────────────────────────────────────────────────────────

export function MapOverlayProvider({ children }: { children: ReactNode }) {
  const registrations = useRef<Map<string, OverlayRegistration>>(new Map())
  // T1.5i FIX (2026-07-10): Replace forceUpdate({}) with a version counter.
  // The old pattern caused infinite re-renders: ResizeObserver fires →
  // setHeight → forceUpdate → re-render → layout → ResizeObserver fires again.
  // Now: version only increments on register/unregister (mount/unmount), NOT
  // on every height change. Height changes are read directly from the ref
  // during render — no state update needed.
  const [version, setVersion] = useState(0)
  const heightDirtyRef = useRef(false)

  const register = useCallback((reg: Omit<OverlayRegistration, 'height'>) => {
    registrations.current.set(reg.id, { ...reg, height: 0 })
    setVersion(v => v + 1)
    return () => {
      registrations.current.delete(reg.id)
      setVersion(v => v + 1)
    }
  }, [])

  const setHeight = useCallback((id: string, height: number) => {
    const existing = registrations.current.get(id)
    if (existing && existing.height !== height) {
      existing.height = height
      // Mark dirty but don't force re-render immediately.
      // The next render (triggered by other state changes) will pick up
      // the new height from the ref. This breaks the render loop.
      heightDirtyRef.current = true
    }
  }, [])

  const getZone = useCallback((anchor: OverlayAnchor) => {
    return Array.from(registrations.current.values())
      .filter((r) => r.anchor === anchor)
      .sort((a, b) => a.order - b.order)
  }, [])

  // If heights changed but no other state triggered a re-render, schedule
  // a single deferred re-render via requestAnimationFrame. This prevents
  // the infinite loop while still updating positions after resize.
  React.useEffect(() => {
    if (heightDirtyRef.current) {
      heightDirtyRef.current = false
      const raf = requestAnimationFrame(() => setVersion(v => v + 1))
      return () => cancelAnimationFrame(raf)
    }
  }) // runs on every render — checks if heights need propagation

  const value = useMemo(
    () => ({ register, setHeight, getZone }),
    [register, setHeight, getZone],
  )

  // version is read to trigger re-renders; the actual data is in the ref
  void version

  return <OverlayContext.Provider value={value}>{children}</OverlayContext.Provider>
}

// ─── useOverlay hook ────────────────────────────────────────────────────────

export function useOverlay(): OverlayContextValue {
  const ctx = useContext(OverlayContext)
  if (!ctx) {
    throw new Error('useOverlay must be used within <MapOverlayProvider>')
  }
  return ctx
}

// ─── MapOverlaySlot — wraps an overlay and positions it in a zone ───────────

interface MapOverlaySlotProps {
  id: string
  anchor: OverlayAnchor
  /** Lower order = closer to the anchor edge. Defaults to the registration order. */
  order: number
  /** Z-index layer from the shared enum */
  layer: OverlayLayer
  /** Gap between this slot and its neighbors in the zone (px). Default 8. */
  gap?: number
  /** Margin from the viewport edge (px). Default 12. */
  edgeMargin?: number
  children: ReactNode
  /** Extra className for the slot wrapper */
  className?: string
}

/**
 * Wraps an overlay component and positions it within its anchor zone.
 * Measures its own height with a ref and reports it to the manager so
 * siblings can stack without overlapping.
 */
export function MapOverlaySlot({
  id,
  anchor,
  order,
  layer,
  gap = 8,
  edgeMargin = 12,
  children,
  className = '',
}: MapOverlaySlotProps) {
  const { register, setHeight, getZone } = useOverlay()
  const ref = useRef<HTMLDivElement>(null)

  // Register on mount, unregister on unmount
  React.useEffect(() => {
    const unregister = register({ id, anchor, order, layer })
    return unregister
  }, [id, anchor, order, layer, register])

  // Measure height and report to the manager
  React.useEffect(() => {
    const el = ref.current
    if (!el) return

    const measure = () => {
      const h = el.offsetHeight
      setHeight(id, h)
    }
    measure()

    // Re-measure on resize (panel content may change)
    const observer = new ResizeObserver(measure)
    observer.observe(el)
    return () => observer.disconnect()
  }, [id, setHeight])

  // Compute the position based on anchor and the measured heights of siblings
  const zoneSiblings = getZone(anchor)
  const myIndex = zoneSiblings.findIndex((r) => r.id === id)
  const zIndex = OVERLAY_Z[layer]

  // Calculate the offset from the anchor edge.
  // For top anchors: stack downward (sum heights of siblings with lower order)
  // For bottom anchors: stack upward (sum heights of siblings with higher order)
  let offset = edgeMargin
  if (anchor.startsWith('top')) {
    for (let i = 0; i < myIndex; i++) {
      offset += zoneSiblings[i].height + gap
    }
  } else if (anchor.startsWith('bottom')) {
    for (let i = myIndex + 1; i < zoneSiblings.length; i++) {
      offset += zoneSiblings[i].height + gap
    }
  }

  // Build the positioning style
  const positionStyle: React.CSSProperties = {
    position: 'absolute',
    zIndex,
  }

  // Edge margin constants (match the old values for visual continuity)
  const smEdgeMargin = 16 // sm: right-4 / left-4

  if (anchor === 'top-left') {
    positionStyle.top = `${offset}px`
    positionStyle.left = `${edgeMargin}px`
  } else if (anchor === 'top-right') {
    positionStyle.top = `${offset}px`
    positionStyle.right = `${edgeMargin}px`
  } else if (anchor === 'top-center') {
    positionStyle.top = `${offset}px`
    positionStyle.left = '50%'
    positionStyle.transform = 'translateX(-50%)'
  } else if (anchor === 'bottom-left') {
    positionStyle.bottom = `${offset}px`
    positionStyle.left = `${edgeMargin}px`
  } else if (anchor === 'bottom-right') {
    positionStyle.bottom = `${offset}px`
    positionStyle.right = `${edgeMargin}px`
  } else if (anchor === 'bottom-center') {
    positionStyle.bottom = `${offset}px`
    positionStyle.left = `${edgeMargin}px`
    positionStyle.right = `${edgeMargin}px`
  }

  return (
    <div ref={ref} style={positionStyle} className={className}>
      {children}
    </div>
  )
}

// ─── Convenience: MapOverlayZone (renders all slots in a zone) ──────────────
//
// This is optional — components can use MapOverlaySlot directly. But if you
// want to render a whole zone in one place (useful for the bottom-center
// coordinate bar which is a single full-width element), this helps.

export function MapOverlayZone({
  anchor,
  children,
}: {
  anchor: OverlayAnchor
  children: ReactNode
}) {
  // This is just a semantic wrapper — the actual positioning is done by
  // MapOverlaySlot instances. This component exists so the MapClient render
  // tree reads clearly: <MapOverlayZone anchor="top-right">...</MapOverlayZone>
  return <>{children}</>
}

