'use client';

/**
 * OSM Buildings Overlay — fetches building footprints from the local PBF
 * via the Python worker and renders them as an OpenLayers vector layer.
 *
 * Usage:
 *   <OsmBuildingsLayer map={map} visible={true} />
 *
 * Requires:
 *   - Python worker running with Pyrosm installed
 *   - Kenya PBF file at data/kenya-latest.osm.pbf
 *
 * The layer fetches context on map move/end (debounced) and displays
 * them as semi-transparent cyan/orange polygons/lines — matching METARDU's brand.
 */

import { useEffect, useRef, useState } from 'react'
import { Loader2, Building2 } from 'lucide-react'

interface OsmBuildingsLayerProps {
  map: any  // OpenLayers Map
  visible: boolean
}

export function OsmBuildingsLayer({ map, visible }: OsmBuildingsLayerProps) {
  const layerRef = useRef<any>(null)
  const sourceRef = useRef<any>(null)
  const [loading, setLoading] = useState(false)
  const [featureCount, setFeatureCount] = useState(0)
  const [error, setError] = useState<string | null>(null)

  // Initialize the OpenLayers vector layer once
  useEffect(() => {
    if (!map || layerRef.current) return

    let cancelled = false

    // AUDIT FIX (H-006, 2026-07-27): switched from `window.ol.*` (a legacy
    // global that isn't loaded — caused "Cannot read properties of undefined
    // (reading 'source')") to dynamic `ol/*` imports, matching every other
    // map component in this codebase.
    ;(async () => {
      try {
        const { default: VectorSource } = await import('ol/source/Vector')
        const { default: VectorLayer } = await import('ol/layer/Vector')
        const { default: GeoJSON } = await import('ol/format/GeoJSON')
        const { default: Style } = await import('ol/style/Style')
        const { default: Fill } = await import('ol/style/Fill')
        const { default: Stroke } = await import('ol/style/Stroke')

        if (cancelled) return

        const source = new VectorSource({})
        const layer = new VectorLayer({
          source,
          style: new Style({
            fill: new Fill({ color: 'rgba(209, 123, 71, 0.15)' }),  // accent at 15% opacity
            stroke: new Stroke({ color: 'rgba(209, 123, 71, 0.6)', width: 1 }),
          }),
          zIndex: 15,  // above basemap, below survey data
        })

        map.addLayer(layer)
        sourceRef.current = source
        layerRef.current = layer
        // Store GeoJSON format for later use
        ;(layerRef.current as any).geoJSONFormat = new GeoJSON()
      } catch (err) {
        if (!cancelled) {
          console.error('[osm-buildings] Failed to init layer:', err)
        }
      }
    })()

    return () => {
      cancelled = true
      if (layerRef.current) {
        map.removeLayer(layerRef.current)
        layerRef.current = null
        sourceRef.current = null
      }
    }
  }, [map])

  // Toggle visibility
  useEffect(() => {
    if (layerRef.current) {
      layerRef.current.setVisible(visible)
    }
  }, [visible])

  // Fetch buildings on map move (debounced)
  useEffect(() => {
    if (!map || !visible || !sourceRef.current) return

    let timeoutId: any
    let cancelled = false

    const fetchBuildings = async () => {
      if (cancelled) return
      setLoading(true)
      setError(null)

      try {
        const view = map.getView()
        const extent = view.calculateExtent(map.getSize())

        // Transform extent from map projection to WGS84
        const proj4 = (window as any).proj4
        const fromProj = view.getProjection().getCode()
        let minLon: number, minLat: number, maxLon: number, maxLat: number

        if (fromProj === 'EPSG:4326') {
          ;[minLon, minLat, maxLon, maxLat] = extent
        } else if (fromProj === 'EPSG:3857' && proj4) {
          // Web Mercator → WGS84
          const [minX, minY, maxX, maxY] = extent
          const min = proj4('EPSG:3857', 'EPSG:4326', [minX, minY])
          const max = proj4('EPSG:3857', 'EPSG:4326', [maxX, maxY])
          minLon = min[0]; minLat = min[1]
          maxLon = max[0]; maxLat = max[1]
        } else {
          // UTM → WGS84 via proj4 (registered globally)
          if (proj4) {
            const [minX, minY, maxX, maxY] = extent
            const min = proj4(fromProj, 'EPSG:4326', [minX, minY])
            const max = proj4(fromProj, 'EPSG:4326', [maxX, maxY])
            minLon = min[0]; minLat = min[1]
            maxLon = max[0]; maxLat = max[1]
          } else {
            return  // no proj4 available
          }
        }

        const params = {
          lat: (minLat + maxLat) / 2,
          lon: (minLon + maxLon) / 2,
          radius: 500, // strict 500m radius to save performance
        }

        const res = await fetch(`/api/osm/context-geojson`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(params),
        })
        if (!res.ok) {
          if (res.status === 503) {
            setError('Python worker offline')
          }
          return
        }

        const data = await res.json()
        if (cancelled) return

        if (data && data.features) {
          // Clear and reload
          sourceRef.current.clear()
          const format = (layerRef.current as any).geoJSONFormat
          const features = format.readFeatures(data, {
            featureProjection: view.getProjection(),
            dataProjection: 'EPSG:4326',
          })
          sourceRef.current.addFeatures(features)
          setFeatureCount(features.length)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Fetch failed')
        }
      } finally {
        if (!cancelled) setLoading(false)
      }
    }

    const onMoveEnd = () => {
      clearTimeout(timeoutId)
      timeoutId = setTimeout(fetchBuildings, 500)  // debounce 500ms
    }

    map.on('moveend', onMoveEnd)
    fetchBuildings()  // initial fetch

    return () => {
      cancelled = true
      clearTimeout(timeoutId)
      map.un('moveend', onMoveEnd)
    }
  }, [map, visible])

  if (!visible) return null

  return (
    <div className="absolute top-3 right-3 z-30 bg-[#050505]/90 backdrop-blur-xl border border-[rgba(255,255,255,0.1)] rounded-xl px-3 py-2 text-xs flex items-center gap-2 shadow-[0_4px_24px_rgba(0,0,0,0.5)]">
      <Building2 className="w-3.5 h-3.5 text-cyan-400" />
      {loading ? (
        <>
          <Loader2 className="w-3 h-3 animate-spin text-[var(--text-muted)]" />
          <span className="text-[var(--text-muted)]">Loading Context…</span>
        </>
      ) : error ? (
        <span className="text-[var(--error)]">{error}</span>
      ) : (
        <span className="text-[var(--text-secondary)] font-medium">
          {featureCount} context features
        </span>
      )}
    </div>
  )
}

'use client'
/**
 * RotationControl — Map rotation indicator & north-reset button
 *
 * Shows the current map rotation angle and provides a one-click
 * "reset to north" button. The compass needle rotates in sync with
 * the map so surveyors always know their orientation.
 *
 * Reads map instance from MapReactContext.
 * Uses OL view.animate() for smooth reset.
 */

import React, { useState, useEffect, useCallback, memo } from 'react'
import { useMapContext } from '@/app/map/MapReactContext'

function RotationControlInner() {
  const { mapInstance } = useMapContext()
  const [rotation, setRotation] = useState(0)

  // ── Track rotation changes from the map view ──
  useEffect(() => {
    const map = mapInstance.current
    if (!map) return

    const view = map.getView()
    if (!view) return

    // Initial value
    setRotation(view.getRotation() || 0)

    // Listen for rotation changes
    const onRotationChange = () => {
      setRotation(view.getRotation() || 0)
    }

    view.on('change:rotation', onRotationChange)

    return () => {
      view.un('change:rotation', onRotationChange)
    }
  }, [mapInstance])

  // ── Reset rotation to north (0) ──
  const handleResetNorth = useCallback(() => {
    const map = mapInstance.current
    if (!map) return

    const view = map.getView()
    if (!view) return

    view.animate({
      rotation: 0,
      duration: 300,
    })
  }, [mapInstance])

  // Convert radians to degrees for display
  const rotationDeg = Math.round((rotation * 180) / Math.PI)
  const isRotated = Math.abs(rotation) > 0.001

  // Don't render if map not available
  if (!mapInstance.current) return null

  return (
    <button
      onClick={handleResetNorth}
      className={[
        'relative w-10 h-10 rounded-lg border bg-[var(--bg-card)] shadow-sm transition-all',
        'flex items-center justify-center',
        isRotated
          ? 'border-[#1B3A5C] hover:bg-[var(--primary-blue)]/10 cursor-pointer'
          : 'border-[var(--border-color)] cursor-default opacity-50',
      ].join(' ')}
      title={isRotated ? `Reset North (rotated ${rotationDeg}°)` : 'North (0°)'}
      disabled={!isRotated}
      style={{ fontFamily: 'Calibri, sans-serif' }}
    >
      {/* Compass needle — rotates with map */}
      <svg
        className="w-6 h-6 transition-transform"
        style={{
          transform: `rotate(${rotationDeg}deg)`,
          transformOrigin: 'center',
        }}
        viewBox="0 0 24 24"
        fill="none"
      >
        {/* North needle (red) */}
        <path
          d="M12 2 L14 12 L12 10 L10 12 Z"
          fill={isRotated ? '#c0392b' : '#999'}
        />
        {/* South needle (dark) */}
        <path
          d="M12 22 L14 12 L12 14 L10 12 Z"
          fill={isRotated ? '#1B3A5C' : '#bbb'}
        />
        {/* Center dot */}
        <circle cx="12" cy="12" r="1.5" fill="#1B3A5C" />
      </svg>

      {/* Rotation badge */}
      {isRotated && (
        <span className="absolute -top-1 -right-1 bg-[#1B3A5C] text-[var(--text-primary)] text-[8px] font-bold px-1 py-0.5 rounded-full leading-none">
          {rotationDeg}°
        </span>
      )}
    </button>
  )
}

export const RotationControl = memo(RotationControlInner)

'use client'

/**
 * SnappingOptions — Configurable snapping for precise digitizing
 *
 * QGIS-inspired snapping configuration:
 * - Snap to: vertices, edges, intersections
 * - Tolerance: adjustable in meters
 * - Enabled/disabled per layer
 * - Snap mode: vertex, segment, vertex+segment
 */

import { useState, useCallback } from 'react'
import { Magnet, Settings2, X } from 'lucide-react'

type SnapMode = 'vertex' | 'segment' | 'vertex_segment'
type SnapType = 'osm' | 'parcels' | 'beacons' | 'grid' | 'all'

interface SnappingOptionsProps {
  open: boolean
  onClose: () => void
  enabled: boolean
  onToggleEnabled: () => void
  mode?: SnapMode
  onModeChange?: (mode: SnapMode) => void
  tolerance?: number
  onToleranceChange?: (tolerance: number) => void
  snapTypes?: Set<SnapType>
  onSnapTypeToggle?: (type: SnapType) => void
}

const SNAP_MODE_LABELS: Record<SnapMode, string> = {
  vertex: 'Vertex only',
  segment: 'Segment only',
  vertex_segment: 'Vertex + Segment',
}

const SNAP_TYPE_LABELS: Record<SnapType, string> = {
  osm: 'Basemap features',
  parcels: 'Parcels',
  beacons: 'Beacons',
  grid: 'Grid intersections',
  all: 'All layers',
}

export function SnappingOptions({
  open,
  onClose,
  enabled,
  onToggleEnabled,
  mode = 'vertex_segment',
  onModeChange,
  tolerance = 0.1,
  onToleranceChange,
  snapTypes = new Set(['parcels', 'beacons']),
  onSnapTypeToggle,
}: SnappingOptionsProps) {
  const [localMode, setLocalMode] = useState(mode)
  const [localTolerance, setLocalTolerance] = useState(tolerance)
  const [localSnapTypes, setLocalSnapTypes] = useState(snapTypes)

  const handleModeChange = useCallback((newMode: SnapMode) => {
    setLocalMode(newMode)
    onModeChange?.(newMode)
  }, [onModeChange])

  const handleToleranceChange = useCallback((newTolerance: number) => {
    setLocalTolerance(newTolerance)
    onToleranceChange?.(newTolerance)
  }, [onToleranceChange])

  const handleSnapTypeToggle = useCallback((type: SnapType) => {
    setLocalSnapTypes(prev => {
      const next = new Set(prev)
      if (next.has(type)) next.delete(type)
      else next.add(type)
      onSnapTypeToggle?.(type)
      return next
    })
  }, [onSnapTypeToggle])

  if (!open) return null

  return (
    <div className="absolute top-[340px] right-3 z-30 w-72 bg-[var(--bg-secondary)]/95 backdrop-blur-2xl border border-[var(--border-color)]/[0.08] rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-right-2 duration-200">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]/[0.06]">
        <div className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${enabled ? 'bg-[var(--success)]/10' : 'bg-[var(--bg-tertiary)]/10'}`}>
            <Magnet className={`w-4 h-4 ${enabled ? 'text-[var(--success)]' : 'text-[var(--text-muted)]'}`} />
          </div>
          <div>
            <span className="text-sm font-semibold text-[var(--text-primary)]">Snapping</span>
            <p className="text-[9px] text-[var(--text-muted)] uppercase tracking-wider">
              {enabled ? 'Enabled' : 'Disabled'}
            </p>
          </div>
        </div>
        <button
          onClick={onClose}
          className="w-7 h-7 flex items-center justify-center rounded-lg text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card)]/[0.06]"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="p-4 space-y-4">
        {/* Enable toggle */}
        <button
          onClick={onToggleEnabled}
          className={`w-full flex items-center justify-between p-2.5 rounded-lg border transition-colors ${
            enabled
              ? 'bg-[var(--success)]/5 border-emerald-500/30'
              : 'bg-[var(--bg-card)]/[0.02] border-[var(--border-color)]/[0.06]'
          }`}
        >
          <span className="text-xs text-[var(--text-primary)]">Enable Snapping</span>
          <div className={`w-9 h-5 rounded-full p-0.5 transition-colors ${enabled ? 'bg-[var(--success)]' : 'bg-gray-700'}`}>
            <div className={`w-4 h-4 rounded-full bg-[var(--bg-card)] transition-transform ${enabled ? 'translate-x-4' : ''}`} />
          </div>
        </button>

        {/* Snap mode */}
        <div>
          <div className="block text-[9px] text-[var(--text-muted)] uppercase tracking-wider mb-1.5">Snap Mode</div>
          <div className="grid grid-cols-3 gap-1">
            {(['vertex', 'segment', 'vertex_segment'] as SnapMode[]).map(m => (
              <button
                key={m}
                onClick={() => handleModeChange(m)}
                disabled={!enabled}
                className={`px-2 py-1.5 rounded-lg text-[9px] font-medium transition-colors disabled:opacity-30 ${
                  localMode === m
                    ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)]'
                    : 'bg-[var(--bg-card)]/[0.02] border border-[var(--border-color)]/[0.06] text-[var(--text-secondary)] hover:text-[var(--text-secondary)]'
                }`}
              >
                {m === 'vertex' ? 'Vertex' : m === 'segment' ? 'Segment' : 'Both'}
              </button>
            ))}
          </div>
        </div>

        {/* Tolerance */}
        <div>
          <div className="flex items-center justify-between mb-1.5">
            <label htmlFor="snap-tolerance" className="text-[9px] text-[var(--text-muted)] uppercase tracking-wider">Tolerance</label>
            <span className="text-[10px] text-[var(--text-secondary)] font-mono">{localTolerance.toFixed(2)} m</span>
          </div>
          <input id="snap-tolerance"
            type="range"
            min="0.01"
            max="5"
            step="0.01"
            value={localTolerance}
            onChange={e => handleToleranceChange(parseFloat(e.target.value))}
            disabled={!enabled}
            className="w-full h-1.5 accent-[#D17B47] cursor-pointer disabled:opacity-30"
          />
          <div className="flex items-center justify-between mt-0.5 text-[8px] text-[var(--text-muted)]">
            <span>1cm</span>
            <span>1m</span>
            <span>5m</span>
          </div>
        </div>

        {/* Snap to layers */}
        <div>
          <div className="block text-[9px] text-[var(--text-muted)] uppercase tracking-wider mb-1.5">Snap To</div>
          <div className="space-y-1">
            {(['parcels', 'beacons', 'grid', 'osm'] as SnapType[]).map(type => (
              <label
                key={type}
                className={`flex items-center gap-2 p-1.5 rounded-lg cursor-pointer transition-colors ${
                  enabled ? 'hover:bg-[var(--bg-card)]/[0.04]' : 'opacity-50'
                }`}
              >
                <input aria-label="Snap type"
                  type="checkbox"
                  checked={localSnapTypes.has(type)}
                  onChange={() => handleSnapTypeToggle(type)}
                  disabled={!enabled}
                  className="w-3.5 h-3.5 rounded border-[var(--border-hover)] accent-[#D17B47]"
                />
                <span className="text-[11px] text-[var(--text-secondary)]">{SNAP_TYPE_LABELS[type]}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Info */}
        <div className="flex items-start gap-1.5 p-2 rounded-lg bg-blue-500/5 border border-blue-500/10">
          <Settings2 className="w-3 h-3 text-[var(--primary-blue)] shrink-0 mt-0.5" />
          <p className="text-[9px] text-[var(--primary-blue)]/70 leading-relaxed">
            Snapping ensures precise digitizing by aligning new features to existing vertices and edges.
            Lower tolerance = more precise but harder to snap. Higher tolerance = easier but less precise.
          </p>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useEffect } from 'react';
import Link from 'next/link';

export default function MapErrorPage({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error('[Map Error]', error)
    import('@sentry/nextjs').then(({ captureException }) => captureException(error)).catch(() => {})
  }, [error])
  return (
    <div className="h-[calc(100vh-4rem)] bg-[var(--bg-primary)] flex items-center justify-center">
      <div className="text-center max-w-lg px-6">
        <div className="w-12 h-12 mx-auto mb-4 rounded-xl bg-[var(--error)]/10 flex items-center justify-center">
          <svg className="w-6 h-6 text-[var(--error)]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
        </div>
        <h3 className="text-[var(--text-primary)] font-semibold text-lg mb-2">Map failed to load</h3>
        <p className="text-[var(--text-secondary)] text-sm mb-1">
          {error?.message || 'An unexpected error occurred while loading the map.'}
        </p>
        <p className="text-[var(--text-muted)] text-xs mb-6">
          This is usually a temporary issue with map libraries loading.
        </p>
        <div className="flex gap-3 justify-center">
          <button
            onClick={reset}
            className="px-5 py-2 bg-[#D17B47] hover:bg-[#D17B47]/80 text-[var(--text-primary)] text-sm rounded-lg transition-colors"
          >
            Try Again
          </button>
          <Link
            href="/dashboard"
            className="px-5 py-2 bg-gray-700 hover:bg-gray-600 text-[var(--text-primary)] text-sm rounded-lg transition-colors"
          >
            Go to Dashboard
          </Link>
        </div>
        {error.digest && (
          <p className="text-xs text-[var(--text-muted)] mt-4 font-mono">Error ref: {error.digest}</p>
        )}
      </div>
    </div>
  );
}

'use client'
/**
 * useMapBasemaps — Hook for basemap layer management
 *
 * Creates and manages the 4 basemap tile layers (OSM, Satellite, Dark, Terrain).
 * Extracted from MapClient for maintainability.
 *
 * Performance notes:
 * - All tile layers created once during initialization
 * - Terrain uses OpenTopoMap with cacheSize for better tile caching
 * - Caching headers enabled for tile requests
 */

import { useRef, useCallback } from 'react'
import type { BasemapMode } from '@/app/map/mapTypes'

interface UseMapBasemapsReturn {
  basemapsRef: React.MutableRefObject<Record<string, any>>
  createBasemaps: (olModules: any) => Record<string, any>
  toggleBasemap: (mapInstance: React.MutableRefObject<any>, mode: BasemapMode, setBasemap: (m: BasemapMode) => void) => void
}

export function useMapBasemaps(): UseMapBasemapsReturn {
  const basemapsRef = useRef<Record<string, any>>({})

  const createBasemaps = useCallback((olModules: any) => {
    const { TileLayer, OSM, XYZ } = olModules

    const basemaps: Record<string, any> = {
      osm: new TileLayer({
        source: new OSM({ crossOrigin: 'anonymous' }),
        visible: true,
        zIndex: 0,
      }),
      satellite: new TileLayer({
        source: new XYZ({
          url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
          crossOrigin: 'anonymous',
          maxZoom: 19,
          attributions: 'Tiles \u00A9 Esri',
          cacheSize: 2048,
        }),
        visible: false,
        zIndex: 0,
      }),
      dark: new TileLayer({
        source: new XYZ({
          url: 'https://{a-d}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',
          crossOrigin: 'anonymous',
          maxZoom: 19,
          attributions: '\u00A9 CartoDB',
          cacheSize: 2048,
        }),
        visible: false,
        zIndex: 0,
      }),
      terrain: new TileLayer({
        source: new XYZ({
          // Primary: OpenTopoMap (topographic contours + hill shading)
          // Fallback handled by OpenLayers tile error event
          url: 'https://{a-c}.tile.opentopomap.org/{z}/{x}/{y}.png',
          crossOrigin: 'anonymous',
          maxZoom: 17,
          attributions: '\u00A9 OpenTopoMap (CC-BY-SA)',
          cacheSize: 2048,
          // Retry failed tiles
          tileLoadFunction: (imageTile: any, src: string) => {
            const img = imageTile.getImage()
            img.onerror = () => {
              // Fallback to Esri terrain if OpenTopoMap is rate-limited
              const z = imageTile.getTileCoord()[0]
              const x = imageTile.getTileCoord()[1]
              const y = imageTile.getTileCoord()[2]
              img.src = `https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/${z}/${y}/${x}`
              img.onerror = () => {
                // Final fallback: OSM (at least show something)
                img.src = `https://tile.openstreetmap.org/${z}/${x}/${y}.png`
              }
            }
            img.src = src
          },
        }),
        visible: false,
        zIndex: 0,
      }),
      // Land cover overlay (Sentinel-2 NDVI/NDBI)
      ndvi: new TileLayer({
        source: new XYZ({
          url: 'https://services.arcgisonline.com/arcgis/rest/services/Sentinel2/ImageServer/tile/{z}/{y}/{x}',
          crossOrigin: 'anonymous',
          maxZoom: 16,
          attributions: '\u00A9 Esri Sentinel-2',
          cacheSize: 1024,
        }),
        visible: false,
        zIndex: 1,  // Above basemaps
        opacity: 0.7,
      }),
      // Satellite imagery for NDBI/NDWI visual reference
      imagery: new TileLayer({
        source: new XYZ({
          url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
          crossOrigin: 'anonymous',
          maxZoom: 19,
          attributions: '\u00A9 Esri World Imagery',
          cacheSize: 2048,
        }),
        visible: false,
        zIndex: 1,
        opacity: 0.7,
      }),
    }

    // Tag each layer for basemap lookup
    Object.entries(basemaps).forEach(([id, layer]) => layer.set('basemapId', id))
    basemapsRef.current = basemaps
    return basemaps
  }, [])

  const toggleBasemap = useCallback((
    mapInstance: React.MutableRefObject<any>,
    mode: BasemapMode,
    setBasemap: (m: BasemapMode) => void
  ) => {
    if (!mapInstance.current) return
    const basemapIds = ['osm', 'satellite', 'dark', 'terrain']
    for (const layer of mapInstance.current.getLayers().getArray()) {
      const id = layer.get('basemapId')
      if (id && basemapIds.includes(id)) {
        layer.setVisible(id === mode)
      }
    }
    setBasemap(mode)
  }, [])

  return { basemapsRef, createBasemaps, toggleBasemap }
}

'use client'
/**
 * useMapInit — Core map initialization hook
 *
 * Handles the entire map initialization lifecycle:
 * - Dynamic imports of all OpenLayers modules
 * - Projection registration
 * - Layer creation (basemaps, draw, measure, cluster)
 * - Project data fetching and marker placement
 * - Interaction setup (select, snap, drag-and-drop)
 * - View state restoration from localStorage
 * - Proper cleanup on unmount
 *
 * Performance optimizations:
 * - All OL modules loaded in parallel via Promise.all
 * - Project markers use Cluster source (distance: 40, minDistance: 20)
 * - Mouse position throttled to 100ms
 * - Map view state saved every 10s (not on every move)
 * - Tile cache size set to 2048 for better caching
 */

import { useEffect, useRef } from 'react'
import type { BasemapMode } from '@/hooks/useMapTypes'
import type { MapCleanupRefs } from '@/lib/map/olTypes'

interface UseMapInitParams {
  mapRef: React.RefObject<HTMLDivElement | null>
  setMapReady: (v: boolean) => void
  setInitError: (v: string) => void
  setProjectCount: (v: number) => void
  setMouseCoord: (v: { lon: number; lat: number; e: number; n: number } | null) => void
  setFeatureCount: (v: number) => void
  setImportMsg: (v: string) => void
  setSelectedFeature: (v: any) => void
  setFeatureName: (v: string) => void
  mouseCoordThrottleRef: React.MutableRefObject<number>
  searchParams: URLSearchParams
  pushHistory: () => void
  drawSourceRef: React.MutableRefObject<unknown>
  drawLayerRef: React.MutableRefObject<unknown>
  measureSourceRef: React.MutableRefObject<unknown>
  measureLayerRef: React.MutableRefObject<unknown>
  selectInteractionRef: React.MutableRefObject<unknown>
  mapInstance: React.MutableRefObject<unknown>
  cleanupRef: React.MutableRefObject<MapCleanupRefs | null>
  popupRef: React.MutableRefObject<HTMLDivElement | null>
  createBasemaps: (olModules: any) => Record<string, any>
  onPopupRender: (popupElement: HTMLDivElement, data: any, hidePopup: () => void) => void
  /** T1.5 FIX (2026-07-09): UTM EPSG for mouse position coordinate display */
  currentUtmEpsg?: string
}

export function useMapInit(params: UseMapInitParams) {
  const {
    mapRef, setMapReady, setInitError, setProjectCount,
    setMouseCoord, setFeatureCount, setImportMsg,
    setSelectedFeature, setFeatureName, mouseCoordThrottleRef,
    searchParams, pushHistory,
    drawSourceRef, drawLayerRef, measureSourceRef, measureLayerRef,
    selectInteractionRef, mapInstance, cleanupRef, popupRef,
    createBasemaps, onPopupRender,
  } = params

  useEffect(() => {
    if (!mapRef.current || mapInstance.current) return

    let map: any = null
    let cancelled = false
    const olModules: any = {}

    async function initMap() {
      try {
        // Register projections with error handling
        try {
          const { registerProjections } = await import('@/lib/map/projection')
          await registerProjections()
        } catch (projErr) {
          console.warn('Projection registration failed, using defaults:', projErr)
        }

        // Parallel import of all OL modules for performance
        const imports = await Promise.all([
          import('ol/Map'),
          import('ol/View'),
          import('ol/layer/Tile'),
          import('ol/layer/Vector'),
          import('ol/layer/Group'),
          import('ol/source/OSM'),
          import('ol/source/XYZ'),
          import('ol/source/Vector'),
          import('ol/source/Cluster'),
          import('ol/Feature'),
          import('ol/geom/Point'),
          import('ol/geom/Polygon'),
          import('ol/geom/Circle'),
          import('ol/geom/LineString'),
          import('ol/style/Style'),
          import('ol/style/Fill'),
          import('ol/style/Stroke'),
          import('ol/style/Circle'),
          import('ol/style/Text'),
          import('ol/style/Icon'),
          import('ol/control/ScaleLine'),
          import('ol/control/Attribution'),
          import('ol/control/MousePosition'),
          import('ol/interaction/Draw'),
          import('ol/interaction/Select'),
          import('ol/interaction/Snap'),
          import('ol/interaction/Modify'),
          import('ol/interaction/DragAndDrop'),
          import('ol/interaction/DragRotate'),
          import('ol/interaction/PinchRotate'),
          import('ol/Overlay'),
          import('ol/Geolocation'),
          import('ol/format/GeoJSON'),
          import('ol/format/KML'),
          import('ol/format/WKT'),
        ])

        const [projModule] = await Promise.all([import('ol/proj')])
        const proj = projModule as typeof import('ol/proj')

        const [Map, View, TileLayer, VectorLayer, LayerGroup, OSM, XYZ, VectorSource,
          Cluster, Feature, Point, Polygon, CircleGeom, LineString, Style, Fill, Stroke,
          CircleStyle, Text, Icon, ScaleLine, Attribution, MousePosition,
          Draw, Select, Snap, Modify, DragAndDrop, DragRotate, PinchRotate, Overlay, Geolocation,
          GeoJSONFormat, KMLFormat, WKTFormat] = imports.map(i => ('default' in i ? i.default : i)) as any[]

        olModules.VectorSource = VectorSource
        olModules.VectorLayer = VectorLayer
        olModules.Feature = Feature
        olModules.Point = Point
        olModules.Polygon = Polygon
        olModules.LineString = LineString
        olModules.CircleGeom = CircleGeom
        olModules.Style = Style
        olModules.Fill = Fill
        olModules.Stroke = Stroke
        olModules.CircleStyle = CircleStyle
        olModules.Text = Text
        olModules.proj = proj
        olModules.Draw = Draw
        olModules.Modify = Modify
        olModules.Snap = Snap
        olModules.TileLayer = TileLayer
        olModules.OSM = OSM
        olModules.XYZ = XYZ
        olModules.Cluster = Cluster

        if (cancelled || !mapRef.current) return

        // ── Basemap layers ──
        const basemaps = createBasemaps(olModules)

        // ── Draw layer — using enhanced SoK-compliant styles ──
        const drawSource = new VectorSource()
        drawSourceRef.current = drawSource

        // Dynamic import of enhanced styles (SoK-compliant, zoom-aware)
        const { getStyleForFeature } = await import('@/lib/map/enhancedStyles')

        const drawLayer = new VectorLayer({
          source: drawSource,
          // Use a style function that adapts to feature type + zoom
          style: (feature: any, resolution: number) => {
            // For drawn features, use the enhanced SoK style
            const geomType = feature.getGeometry()?.getType()
            if (geomType === 'Polygon') {
              return getStyleForFeature(feature, resolution)
            }
            // Default style for points/lines being drawn
            return new Style({
              fill: new Fill({ color: 'rgba(209, 123, 71, 0.15)' }),
              stroke: new Stroke({ color: '#D17B47', width: 2.5 }),
              image: new CircleStyle({ radius: 7, fill: new Fill({ color: '#D17B47' }), stroke: new Stroke({ color: '#fff', width: 2 }) }),
            })
          },
          zIndex: 50,
        })
        drawLayerRef.current = drawLayer

        // ── Measure layer ──
        const measureSource = new VectorSource()
        measureSourceRef.current = measureSource
        const measureLayer = new VectorLayer({
          source: measureSource,
          style: new Style({
            fill: new Fill({ color: 'rgba(96, 165, 250, 0.15)' }),
            stroke: new Stroke({ color: '#60a5fa', width: 2, lineDash: [6, 4] }),
            image: new CircleStyle({ radius: 5, fill: new Fill({ color: '#60a5fa' }), stroke: new Stroke({ color: '#fff', width: 1.5 }) }),
          }),
          zIndex: 45,
        })
        measureLayerRef.current = measureLayer

        // ── Cluster layer for projects ──
        const projectSource = new VectorSource()
        const clusterSource = new Cluster({
          distance: 40,
          minDistance: 20,
          source: projectSource,
        })
        const clusterLayer = new VectorLayer({
          source: clusterSource,
          style: (feature: any) => {
            const size = feature.get('features')?.length || 1
            return new Style({
              image: new CircleStyle({
                radius: size > 1 ? 12 + Math.min(size * 2, 20) : 8,
                fill: new Fill({ color: size > 1 ? 'rgba(209, 123, 71,0.8)' : '#D17B47' }),
                stroke: new Stroke({ color: '#fff', width: 2 }),
              }),
              text: new Text({
                text: size > 1 ? String(size) : '',
                font: 'bold 12px sans-serif',
                fill: new Fill({ color: '#fff' }),
              }),
            })
          },
          zIndex: 10,
        })

        // ── Fetch projects ──
        try {
          const { createClient } = await import('@/lib/api-client/client')
          const dbClient = createClient()
          const { data: { session } } = await dbClient.auth.getSession()

          if (session?.user) {
            const { data } = await dbClient
              .from('projects')
              .select('id, name, location, utm_zone, hemisphere, survey_type, boundary_data')
              .eq('user_id', session.user.id)
              .order('created_at', { ascending: false })

            const projects = data || []
            setProjectCount(projects.length)

            for (const project of projects) {
              const bd = project.boundary_data
              const adjustedStations = bd?.adjustedStations || bd?.stations || []
              if (adjustedStations.length === 0) continue

              const projCode = 'EPSG:21037'
              const validCoords = adjustedStations
                .map((s: any) => [parseFloat(s.easting || s.E || s.e), parseFloat(s.northing || s.N || s.n)])
                .filter((c: number[]) => !isNaN(c[0]) && !isNaN(c[1]))

              if (validCoords.length === 0) continue
              const avgE = validCoords.reduce((s: number, c: number[]) => s + c[0], 0) / validCoords.length
              const avgN = validCoords.reduce((s: number, c: number[]) => s + c[1], 0) / validCoords.length

              try {
                const coords3857 = proj.transform([avgE, avgN], projCode, 'EPSG:3857')
                const feature = new Feature({
                  geometry: new Point(coords3857),
                  projectName: project.name,
                  stationCount: validCoords.length,
                  surveyType: project.survey_type || 'cadastral',
                })
                feature.set('projectId', project.id)
                projectSource.addFeature(feature)
              } catch { /* skip */ }
            }
          }
        } catch (err) {
          console.warn('DbClient query failed:', err)
        }

        // ── Popup overlay ──
        const popupElement = document.createElement('div')
        popupElement.className = 'hidden'
        popupRef.current = popupElement

        const popupOverlay = new Overlay({
          element: popupElement,
          autoPan: { animation: { duration: 250 } },
          positioning: 'bottom-center',
          offset: [0, -10],
        })

        const hidePopup = () => {
          popupOverlay.setPosition(undefined)
          popupElement.className = 'hidden'
          popupElement.replaceChildren()
          setSelectedFeature(null)
          // ponytail: selectInteractionRef.current is unknown (was any); cast minimally
          const si = selectInteractionRef.current as { getFeatures?: () => { clear?: () => void } } | null
          const features = si?.getFeatures?.()
          features?.clear?.()
        }

        // ── Create the map ──
        map = new Map({
          target: mapRef.current,
          layers: [basemaps.osm, basemaps.satellite, basemaps.dark, basemaps.terrain, clusterLayer, drawLayer, measureLayer],
          view: new View({
            center: proj.fromLonLat([37.91, 0.02]),
            zoom: 6,
            minZoom: 6,
            maxZoom: 20,
            extent: [-2.2e7, -1.2e7, 2.2e7, 1.5e7],
          }),
          controls: [
            new ScaleLine({ units: 'metric' }),
            new Attribution({ collapsible: true }),
            new MousePosition({
              coordinateFormat: (coord: number[]) => {
                if (coord[0] == null || coord[1] == null || isNaN(coord[0]) || isNaN(coord[1])) return ''
                try {
                  const utmEpsg = params.currentUtmEpsg || 'EPSG:21037'
                  // T1.5b FIX (2026-07-10): Transform to BOTH geographic (EPSG:4326) and
                  // the active UTM zone. Previously, lon/lat were stored as raw EPSG:3857
                  // Web Mercator meters — labeled "Lon/Lat" but actually eastings/northings
                  // in meters. That's a statutory-accuracy bug: a surveyor reading
                  // "Lon: 4105720" would be misled into thinking the data is corrupt or
                  // would copy a Mercator meter value into a statutory form.
                  const [lon, lat] = proj.transform(coord, 'EPSG:3857', 'EPSG:4326')
                  const [e, n] = proj.transform(coord, 'EPSG:3857', utmEpsg)
                  const eSafe = (e != null && !isNaN(e)) ? e : 0
                  const nSafe = (n != null && !isNaN(n)) ? n : 0
                  const lonSafe = (lon != null && !isNaN(lon)) ? lon : 0
                  const latSafe = (lat != null && !isNaN(lat)) ? lat : 0
                  const now = Date.now()
                  if (now - mouseCoordThrottleRef.current > 100) {
                    mouseCoordThrottleRef.current = now
                    setMouseCoord({ lon: lonSafe, lat: latSafe, e: eSafe, n: nSafe })
                  }
                  return `Lon: ${lonSafe.toFixed(6)}  Lat: ${latSafe.toFixed(6)}  E: ${eSafe.toFixed(1)}  N: ${nSafe.toFixed(1)}`
                } catch {
                  const now = Date.now()
                  if (now - mouseCoordThrottleRef.current > 100) {
                    mouseCoordThrottleRef.current = now
                    setMouseCoord({ lon: 0, lat: 0, e: 0, n: 0 })
                  }
                  return ''
                }
              },
              projection: 'EPSG:3857',
              className: 'ol-mouse-position',
            }),
          ],
          overlays: [popupOverlay],
        })

        mapInstance.current = map

        // Restore saved map view state
        try {
          const savedView = localStorage.getItem('metardu-map-view')
          if (savedView) {
            const { center, zoom } = JSON.parse(savedView)
            if (center && zoom) {
              map.getView().setCenter(center)
              map.getView().setZoom(zoom)
            }
          }
        } catch { /* ignore */ }

        // Restore saved drawn features
        try {
          const savedFeatures = localStorage.getItem('metardu-map-features')
          if (savedFeatures) {
            const { default: GeoJSONFmt } = await import('ol/format/GeoJSON')
            const fmt = new GeoJSONFmt()
            const parsed = JSON.parse(savedFeatures)
            const features = fmt.readFeatures(parsed, {
              dataProjection: 'EPSG:4326',
              featureProjection: 'EPSG:3857',
            })
            drawSource.addFeatures(features)
            setFeatureCount(drawSource.getFeatures().length)
          }
        } catch { /* ignore */ }

        // ── Select interaction ──
        const select = new Select({
          style: new Style({
            fill: new Fill({ color: 'rgba(209, 123, 71,0.3)' }),
            stroke: new Stroke({ color: '#D17B47', width: 3 }),
            image: new CircleStyle({ radius: 10, fill: new Fill({ color: '#D17B47' }), stroke: new Stroke({ color: '#fff', width: 3 }) }),
          }),
          hitTolerance: 5,
          layers: [drawLayer],
        })
        selectInteractionRef.current = select
        map.addInteraction(select)

        select.on('select', (evt: any) => {
          const selected = evt.selected
          if (selected.length > 0) {
            const feature = selected[0]
            const coord = feature.getGeometry()?.getClosestPoint(evt.mapBrowserEvent.coordinate)
            const geometry = feature.getGeometry()
            const geomType = geometry?.getType?.() || 'unknown'
            const props = feature.getProperties()

            const clusterFeatures = feature.get('features')
            if (clusterFeatures && clusterFeatures.length > 1) {
              const extent = feature.getGeometry()?.getExtent()
              if (extent) map.getView().fit(extent, { padding: [100, 100, 100, 100], duration: 500, maxZoom: 15 })
              return
            }

            const projectName = props.projectName || (clusterFeatures?.[0]?.get?.('projectName')) || ''
            const stationName = props.stationName || props.label || props.name || ''
            const projectId = props.projectId || (clusterFeatures?.[0]?.get?.('projectId')) || ''

            setSelectedFeature(feature)
            setFeatureName(stationName || projectName || geomType)

            onPopupRender(popupElement, {
              coordinate: coord,
              projectName: projectName || undefined,
              stationName: stationName || undefined,
              geometryType: geomType,
              projectId: projectId || undefined,
            }, hidePopup)

            if (coord) popupOverlay.setPosition(coord)
          } else {
            popupElement.className = 'hidden'
            popupElement.replaceChildren()
            popupOverlay.setPosition(undefined)
            setSelectedFeature(null)
          }
        })

        // ── Snap interaction — snaps to drawn features AND scheme parcels/beacons ──
        // Collect all vector sources for snapping (draw + scheme parcel + scheme beacon)
        const snapSources: any[] = [drawSource]
        // Scheme layers are added later by MapClient; we use a dynamic approach:
        // The Snap interaction can be reconfigured when scheme layers load.
        // For now, snap to the draw source. MapClient will add scheme sources via
        // the snap interaction's setSource() or by creating additional Snap interactions.
        const snap = new Snap({ source: drawSource })
        map.addInteraction(snap)

        // Store snap reference on the map for later source addition
        ;(map as any)._snapInteraction = snap

        // ── DragRotate interaction (Alt + drag to rotate map) ──
        const dragRotate = new DragRotate({
          condition: (mapBrowserEvent: any) => {
            // Alt key (or Option on Mac) must be held
            const altKey = mapBrowserEvent.originalEvent?.altKey
            return !!altKey
          },
        })
        map.addInteraction(dragRotate)

        // ── PinchRotate interaction (two-finger rotation on mobile) ──
        const pinchRotate = new PinchRotate()
        map.addInteraction(pinchRotate)

        // ── Geolocation ──
        const geolocation = new Geolocation({
          trackingOptions: { enableHighAccuracy: true },
          projection: 'EPSG:3857',
        })

        // ── Drag & Drop ──
        const dragAndDrop = new DragAndDrop({
          formatConstructors: [GeoJSONFormat, KMLFormat, WKTFormat],
        })
        dragAndDrop.on('addfeatures', (evt: any) => {
          const features = evt.features
          if (features && features.length > 0) {
            drawSource.addFeatures(features)
            setFeatureCount(drawSource.getFeatures().length)
            const extent = drawSource.getExtent()
            if (extent[0] !== Infinity) {
              map.getView().fit(extent, { padding: [80, 80, 80, 80], maxZoom: 18, duration: 500 })
            }
            setImportMsg(`Imported ${features.length} feature(s)`)
            setTimeout(() => setImportMsg(''), 3000)
            pushHistory()
          }
        })
        map.addInteraction(dragAndDrop)

        // ── Track feature count ──
        drawSource.on('addfeature', () => {
          setFeatureCount(drawSource.getFeatures().length)
        })
        drawSource.on('removefeature', () => {
          setFeatureCount(drawSource.getFeatures().length)
        })

        // ── Zoom to data ──
        if (projectSource.getFeatures().length > 0) {
          try {
            const extent = projectSource.getExtent()
            if (extent[0] !== Infinity) {
              map.getView().fit(extent, { padding: [80, 80, 80, 80], maxZoom: 18 })
            }
          } catch { /* keep default */ }
        }

        // Auto-load specific project from URL param
        const projectIdParam = searchParams.get('projectId')
        if (projectIdParam) {
          const projectFeature = projectSource.getFeatures().find((f: any) => f.get('projectId') === projectIdParam)
          if (projectFeature) {
            const extent = projectFeature.getGeometry()?.getExtent()
            if (extent && extent[0] !== Infinity) {
              map.getView().fit(extent, { padding: [200, 200, 200, 200], maxZoom: 17, duration: 800 })
            }
          }
        }

        // Store cleanup refs in dedicated ref (not on map object)
        cleanupRef.current = { geolocation, snap, dragAndDrop }

        if (!cancelled) setMapReady(true)
      } catch (err: unknown) {
        console.error('Map initialization failed:', err)
        if (!cancelled) setInitError(err instanceof Error ? (err as Error).message : 'Map failed to load')
      }
    }

    initMap()

    return () => {
      cancelled = true
      if (map) {
        try {
          if (cleanupRef.current?.geolocation) {
            cleanupRef.current.geolocation.setTracking(false)
          }
        } catch { /* ignore */ }
        try { map.setTarget(undefined) } catch { /* ignore */ }
        mapInstance.current = null
        cleanupRef.current = null
      }
    }
  
  }, [])
}

'use client'
/**
 * useMapInteractions — Map interaction hooks (draw, measure, edit, export, GPS, stakeout)
 *
 * All interaction logic extracted from MapClient for maintainability.
 * Uses useCallback for stable references to prevent unnecessary re-renders.
 *
 * Stakeout mode: Full GPS-guided point navigation with overlay, audio alerts,
 * bearing/distance computation, and proximity color-coding.
 */

import { useCallback, useRef, useEffect } from 'react'
import type { DrawMode, MeasureMode } from '@/app/map/mapTypes'
import { downloadDXF, type SurveyPoint } from '@/lib/export/generateDXF'
import { downloadLandXML, type LandXMLProject, type LandXMLPoint } from '@/lib/export/generateLandXML'
import {
  createStakeoutOverlay,
  updateStakeoutDirection,
  updateTargetProximityStyle,
  createStakeoutAudioAlert,
  stopStakeoutAudio,
  computeStakeoutState,
  formatBearingWCB,
  type StakeoutTarget,
  type StakeoutState,
  type StakeoutPosition,
} from '@/lib/map/stakeout'

interface UseMapInteractionsParams {
  mapInstance: React.MutableRefObject<any>
  drawSourceRef: React.MutableRefObject<any>
  drawLayerRef: React.MutableRefObject<any>
  drawInteractionRef: React.MutableRefObject<any>
  selectInteractionRef: React.MutableRefObject<any>
  modifyInteractionRef: React.MutableRefObject<any>
  measureInteractionRef: React.MutableRefObject<any>
  measureSourceRef: React.MutableRefObject<any>
  measureLayerRef: React.MutableRefObject<any>
  annotationLayerRef: React.MutableRefObject<any>
  cleanupRef: React.MutableRefObject<import('@/lib/map/olTypes').MapCleanupRefs | null>
  drawMode: DrawMode
  editMode: boolean
  measureMode: MeasureMode
  showAnnotations: boolean
  gpsTracking: boolean
  stakeoutActive: boolean
  stakeoutTarget: { e: number; n: number } | null
  gpsPos: { lon: number; lat: number; accuracy: number } | null
  /** GPS position already transformed to EPSG:21037 (UTM 37S). Used for precise stakeout. */
  gpsPos21037: { easting: number; northing: number; accuracy: number } | null
  hasFeature: (feature: string) => boolean
  setDrawMode: (m: DrawMode) => void
  setEditMode: (m: boolean) => void
  setMeasureMode: (m: MeasureMode) => void
  setMeasureResult: (s: string) => void
  setFeatureCount: (n: number) => void
  setSelectedFeature: (f: any) => void
  setFeatureName: (s: string) => void
  setGpsTracking: (v: boolean) => void
  setGpsPos: (v: { lon: number; lat: number; accuracy: number } | null) => void
  setStakeoutTarget: (v: { e: number; n: number } | null) => void
  setStakeoutActive: (v: boolean) => void
  setStakeoutState: (v: StakeoutState | null) => void
  setShowAnnotations: (v: boolean) => void
  setSaveMsg: (s: string) => void
  /** Current project ID from URL params (null = no project linked) */
  projectId: string | null
  /** T1.5 FIX (2026-07-09): Active UTM EPSG for geometry transforms. Derived from ProjectionSwitcher. */
  currentUtmEpsg: string
  /** Called when a feature is drawn — used to compute live area/perimeter */
  onDrawEnd?: (areaSqM: number, perimeterM: number, featureType: string) => void
  /** Called when a feature is identified by single-click */
  onIdentify?: (feature: any) => void
  pushHistory: () => void
  clearHistory: () => void
  popupRef: React.MutableRefObject<HTMLDivElement | null>
  toggleGPS: () => void
}

export function useMapInteractions(p: UseMapInteractionsParams) {
  // T1.5 FIX (2026-07-09): Use the project's actual UTM zone for all geometry
  // transforms, not a hardcoded 'EPSG:21037'. Falls back to 'EPSG:21037' if
  // the caller didn't pass currentUtmEpsg (backwards compat).
  const epsg = p.currentUtmEpsg || 'EPSG:21037'

  // ── SINGLE-CLICK IDENTIFY: click any feature → show its attributes ──
  useEffect(() => {
    if (!p.mapInstance.current) return
    const map = p.mapInstance.current

    const handleClick = (evt: any) => {
      // Don't interfere when drawing or measuring
      if (p.drawMode !== 'none' || p.measureMode !== 'none') return

      const features: any[] = []
      map.forEachFeatureAtPixel(evt.pixel, (f: any) => {
        features.push(f)
        return false // collect all
      }, {
        hitTolerance: 5,
      })

      if (features.length > 0) {
        const feature = features[0]
        if (p.onIdentify) p.onIdentify(feature)

        // Show popup with basic info
        // VULN-002 FIX (security review 2026-08-03): render the popup with
        // textContent, never innerHTML — point/parcel names and codes are
        // user-entered and would otherwise execute as stored XSS. Matches
        // the safe renderSchemePopup() pattern in schemeLayer.ts.
        if (p.popupRef.current) {
          const el = p.popupRef.current
          const name = feature.get('pointName') || feature.get('parcelNumber') || feature.get('name') || feature.get('projectName') || ''
          const code = feature.get('code') || ''
          const elev = feature.get('elevation')
          const isControl = feature.get('isControl')
          const type = feature.get('pointType') || feature.get('featureType') || ''

          el.replaceChildren()
          const addRow = (text: string, css: string) => {
            const row = document.createElement('div')
            row.style.cssText = css
            row.textContent = text
            el.append(row)
          }

          if (name) addRow(name, 'font-weight:600;color:#E8E4DE;font-size:13px;margin-bottom:4px')
          if (code) addRow(`Code: ${code}`, 'color:#A89E92;font-size:11px;font-family:monospace')
          if (elev != null) addRow(`Elevation: ${elev.toFixed(3)} m`, 'color:#A89E92;font-size:11px;font-family:monospace')
          if (isControl) addRow('Control point', 'color:#D17B47;font-size:10px;font-family:monospace;text-transform:uppercase;letter-spacing:0.04em')
          if (type) addRow(type, 'color:#787774;font-size:10px;font-family:monospace;text-transform:uppercase')
          if (el.childElementCount === 0) addRow('Feature (no attributes)', 'color:#787774;font-size:11px')

          el.className = 'ol-popup'
          el.style.cssText = `
            background: #1F1C19; border: 1px solid #332E29; border-radius: 6px;
            padding: 10px 14px; font-family: 'Geist', sans-serif; font-size: 12px;
            box-shadow: 0 4px 16px rgba(0,0,0,0.4); min-width: 120px; max-width: 240px;
            color: #E8E4DE; cursor: pointer;
          `
          el.onclick = () => { el.className = 'hidden'; el.onclick = null }
        }
      } else {
        // Clicked empty space — clear selection
        if (p.onIdentify) p.onIdentify(null)
        if (p.popupRef.current) p.popupRef.current.className = 'hidden'
      }
    }

    map.on('singleclick', handleClick)
    return () => map.un('singleclick', handleClick)
  }, [p.drawMode, p.measureMode, p.onIdentify, p.popupRef])

  // ── Stakeout overlay refs (persist across renders) ──
  const stakeoutOverlayRef = useRef<any>(null)         // OL Overlay
  const stakeoutTargetSourceRef = useRef<any>(null)     // Vector source for target marker
  const stakeoutTargetLayerRef = useRef<any>(null)      // Vector layer for target marker
  const stakeoutDirectionSourceRef = useRef<any>(null)  // Vector source for direction line
  const stakeoutDirectionLayerRef = useRef<any>(null)   // Vector layer for direction line
  const stakeoutCleanupDone = useRef(false)

  // ── DRAW ──
  const toggleDraw = useCallback(async (mode: DrawMode) => {
    if (!p.mapInstance.current) return
    const { default: Draw } = await import('ol/interaction/Draw')
    const { default: Style } = await import('ol/style/Style')
    const { default: Fill } = await import('ol/style/Fill')
    const { default: Stroke } = await import('ol/style/Stroke')
    const { default: CircleStyle } = await import('ol/style/Circle')

    if (p.measureMode !== 'none') {
      if (p.measureInteractionRef.current) {
        p.mapInstance.current.removeInteraction(p.measureInteractionRef.current)
        p.measureInteractionRef.current = null
      }
      if (p.measureSourceRef.current) p.measureSourceRef.current.clear()
      p.setMeasureMode('none')
      p.setMeasureResult('')
    }
    if (p.editMode) {
      if (p.modifyInteractionRef.current) {
        p.mapInstance.current.removeInteraction(p.modifyInteractionRef.current)
        p.modifyInteractionRef.current = null
      }
      p.setEditMode(false)
    }

    if (p.drawInteractionRef.current) {
      p.mapInstance.current.removeInteraction(p.drawInteractionRef.current)
      p.drawInteractionRef.current = null
    }

    if (mode === 'none' || mode === p.drawMode) {
      p.setDrawMode('none')
      return
    }

    const source = p.drawSourceRef.current
    if (!source) return

    const geomType = mode as 'Point' | 'LineString' | 'Polygon' | 'Circle'
    const draw = new Draw({
      source,
      type: geomType,
      style: new Style({
        fill: new Fill({ color: 'rgba(209, 123, 71,0.3)' }),
        stroke: new Stroke({ color: '#D17B47', width: 2, lineDash: [8, 4] }),
        image: new CircleStyle({ radius: 6, fill: new Fill({ color: '#D17B47' }), stroke: new Stroke({ color: '#fff', width: 2 }) }),
      }),
    })

    draw.on('drawend', (e: any) => {
      // Compute live area/perimeter for the drawn feature
      if (p.onDrawEnd && e.feature) {
        const geom = e.feature.getGeometry()
        if (geom) {
          const type = geom.getType()
          if (type === 'Polygon' || type === 'MultiPolygon') {
            const area = Math.abs(geom.getArea())
            const coords = type === 'Polygon' ? geom.getCoordinates()[0] : geom.getCoordinates()[0][0]
            const perimeter = coords ? coords.reduce((sum: number, c: number[], i: number, arr: number[][]) => {
              if (i === 0) return 0
              const prev = arr[i - 1]
              return sum + Math.sqrt((c[0] - prev[0]) ** 2 + (c[1] - prev[1]) ** 2)
            }, 0) : 0
            p.onDrawEnd(area, perimeter, 'Polygon')
          } else if (type === 'LineString') {
            p.onDrawEnd(0, geom.getLength(), 'LineString')
          } else if (type === 'Point') {
            p.onDrawEnd(0, 0, 'Point')
          }
        }
      }
      setTimeout(() => p.selectInteractionRef.current?.getFeatures()?.clear(), 100)
      setTimeout(p.pushHistory, 150)
    })

    p.mapInstance.current.addInteraction(draw)
    p.drawInteractionRef.current = draw
    p.setDrawMode(mode)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [p.drawMode, p.editMode, p.measureMode, p.pushHistory])

  // ── EDIT / MODIFY ──
  const toggleEdit = useCallback(async () => {
    if (!p.mapInstance.current) return

    if (p.editMode) {
      if (p.modifyInteractionRef.current) {
        p.mapInstance.current.removeInteraction(p.modifyInteractionRef.current)
        p.modifyInteractionRef.current = null
      }
      p.setEditMode(false)
      return
    }

    if (p.drawInteractionRef.current) {
      p.mapInstance.current.removeInteraction(p.drawInteractionRef.current)
      p.drawInteractionRef.current = null
    }
    p.setDrawMode('none')
    if (p.measureMode !== 'none') {
      if (p.measureInteractionRef.current) {
        p.mapInstance.current.removeInteraction(p.measureInteractionRef.current)
        p.measureInteractionRef.current = null
      }
      if (p.measureSourceRef.current) p.measureSourceRef.current.clear()
      p.setMeasureMode('none')
      p.setMeasureResult('')
    }

    const { default: Modify } = await import('ol/interaction/Modify')
    const source = p.drawSourceRef.current
    if (!source) return

    const modify = new Modify({ source })
    modify.on('modifyend', async (e: any) => {
      setTimeout(p.pushHistory, 100)

      // ── Vertex editing persistence: save modified geometry to project ──
      if (p.projectId && e.features) {
        try {
          const features = e.features.getArray?.() || []
          for (const feature of features) {
            const geom = feature.getGeometry()
            if (!geom) continue

            const type = geom.getType()
            const { transform } = await import('ol/proj')
            const { default: GeoJSONFormat } = await import('ol/format/GeoJSON')
            const fmt = new GeoJSONFormat()

            // Convert modified feature to GeoJSON
            const geojson = fmt.writeFeatureObject(feature, {
              featureProjection: 'EPSG:3857',
              dataProjection: 'EPSG:4326',
            })

            // Update the project's boundary_data with the modified feature
            const { createClient } = await import('@/lib/api-client/client')
            const dbClient = createClient()
            const { data: projData } = await dbClient
              .from('projects')
              .select('boundary_data')
              .eq('id', p.projectId)
              .single()

            const bd: Record<string, unknown> = (projData as any)?.boundary_data || {}
            const drawnFeatures: any[] = ((bd as any).drawnFeatures)?.features || []

            // Find and replace the modified feature (by id if available)
            const featureId = feature.getId?.() || feature.get('ol_uid') || String(Date.now())
            const idx = drawnFeatures.findIndex((f: any) =>
              f.id === featureId || f.properties?.ol_uid === featureId
            )

            if (idx >= 0) {
              drawnFeatures[idx] = geojson
            } else {
              drawnFeatures.push(geojson)
            }

            await dbClient
              .from('projects')
              .update({
                boundary_data: {
                  ...bd,
                  drawnFeatures: { type: 'FeatureCollection', features: drawnFeatures },
                  lastModifiedAt: new Date().toISOString(),
                },
              })
              .eq('id', p.projectId)

            if (p.setSaveMsg) {
              p.setSaveMsg(`Vertex edited — saved to project`)
              setTimeout(() => p.setSaveMsg?.(''), 3000)
            }
          }
        } catch (err) {
          console.error('[VertexEdit] Failed to persist:', err)
        }
      }
    })
    p.mapInstance.current.addInteraction(modify)
    p.modifyInteractionRef.current = modify
    p.setEditMode(true)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [p.editMode, p.measureMode, p.pushHistory])

  // ── DELETE SELECTED ──
  const deleteSelected = useCallback(() => {
    if (!p.selectInteractionRef.current || !p.drawSourceRef.current) return
    const features = p.selectInteractionRef.current.getFeatures().getArray()
    features.forEach((f: any) => p.drawSourceRef.current.removeFeature(f))
    p.selectInteractionRef.current.getFeatures().clear()
    p.setSelectedFeature(null)
    p.pushHistory()
  }, [p.pushHistory])

  // ── MEASURE ──
  const toggleMeasure = useCallback(async (mode: MeasureMode) => {
    if (!p.mapInstance.current) return
    const { default: Draw } = await import('ol/interaction/Draw')
    const { default: Style } = await import('ol/style/Style')
    const { default: Fill } = await import('ol/style/Fill')
    const { default: Stroke } = await import('ol/style/Stroke')
    const { default: CircleStyle } = await import('ol/style/Circle')

    if (p.drawInteractionRef.current) {
      p.mapInstance.current.removeInteraction(p.drawInteractionRef.current)
      p.drawInteractionRef.current = null
    }
    p.setDrawMode('none')
    if (p.editMode) {
      if (p.modifyInteractionRef.current) {
        p.mapInstance.current.removeInteraction(p.modifyInteractionRef.current)
        p.modifyInteractionRef.current = null
      }
      p.setEditMode(false)
    }

    if (p.measureInteractionRef.current) {
      p.mapInstance.current.removeInteraction(p.measureInteractionRef.current)
      p.measureInteractionRef.current = null
    }
    if (p.measureSourceRef.current) p.measureSourceRef.current.clear()
    p.setMeasureResult('')

    if (mode === 'none' || mode === p.measureMode) {
      p.setMeasureMode('none')
      return
    }

    const source = p.measureSourceRef.current
    if (!source) return

    const geomType = mode === 'distance' ? 'LineString' as const : 'Polygon' as const
    const draw = new Draw({
      source,
      type: geomType,
      style: new Style({
        fill: new Fill({ color: 'rgba(96,165,250,0.2)' }),
        stroke: new Stroke({ color: '#60a5fa', width: 2, lineDash: [6, 4] }),
        image: new CircleStyle({ radius: 5, fill: new Fill({ color: '#60a5fa' }), stroke: new Stroke({ color: '#fff', width: 1.5 }) }),
      }),
    })

    draw.on('drawabort', () => {
      p.setMeasureMode('none')
      p.setMeasureResult('')
    })

    draw.on('drawend', async (evt: any) => {
      const geom = evt.feature.getGeometry()
      if (mode === 'distance') {
        const length = geom.getLength()
        const coords = geom.getCoordinates()
        let bearingStr = ''
        if (coords.length >= 2) {
          try {
            const { transform } = await import('ol/proj')
            const first = transform(coords[0], 'EPSG:3857', epsg)
            const last = transform(coords[coords.length - 1], 'EPSG:3857', epsg)
            const dE = last[0] - first[0]
            const dN = last[1] - first[1]
            let bearing = (Math.atan2(dE, dN) * 180) / Math.PI
            if (bearing < 0) bearing += 360
            bearingStr = ` | Brg: ${bearing.toFixed(2)}\u00B0`
          } catch { /* skip bearing */ }
        }
        if (length > 1000) {
          p.setMeasureResult(`Distance: ${(length / 1000).toFixed(3)} km${bearingStr}`)
        } else {
          p.setMeasureResult(`Distance: ${length.toFixed(2)} m${bearingStr}`)
        }
      } else {
        const area = geom.getArea()
        if (area > 1000000) {
          p.setMeasureResult(`Area: ${(area / 1000000).toFixed(4)} km\u00B2`)
        } else {
          p.setMeasureResult(`Area: ${area.toFixed(2)} m\u00B2`)
        }
      }
      p.setMeasureMode('none')
    })

    p.mapInstance.current.addInteraction(draw)
    p.measureInteractionRef.current = draw
    p.setMeasureMode(mode)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [p.drawMode, p.editMode, p.measureMode])

  // ── EXPORT ──
  const exportFeatures = useCallback(async (format: 'GeoJSON' | 'KML' | 'WKT' | 'DXF' | 'LandXML') => {
    if (!p.drawSourceRef.current || p.drawSourceRef.current.getFeatures().length === 0) return

    if (format === 'DXF') {
      if (!p.hasFeature('dxf_export')) return
      const features = p.drawSourceRef.current.getFeatures()
      const { transform } = await import('ol/proj')
      const points: SurveyPoint[] = []
      for (const f of features) {
        const geom = f.getGeometry()
        if (!geom) continue
        const geomType = geom.getType()
        if (geomType === 'Point') {
          const coord = geom.getCoordinates()
          try {
            const [e, n] = transform(coord, 'EPSG:3857', epsg)
            points.push({ name: f.get('name') || f.get('label') || `P${points.length + 1}`, easting: e, northing: n, is_control: false })
          } catch { /* skip */ }
        }
      }
      if (points.length === 0) {
        for (const f of features) {
          const geom = f.getGeometry()
          if (!geom) continue
          const geomType = geom.getType()
          let coords: number[][] = []
          if (geomType === 'LineString') coords = geom.getCoordinates()
          else if (geomType === 'Polygon') coords = geom.getCoordinates()[0] || []
          for (const coord of coords) {
            try {
              const [e, n] = transform(coord, 'EPSG:3857', epsg)
              points.push({ name: `V${points.length + 1}`, easting: e, northing: n, is_control: false })
            } catch { /* skip */ }
          }
        }
      }
      downloadDXF({ projectName: 'metardu-map-export', points })
      return
    }

    if (format === 'LandXML') {
      if (!p.hasFeature('landxml')) return
      const features = p.drawSourceRef.current.getFeatures()
      const { transform } = await import('ol/proj')
      const points: LandXMLPoint[] = []
      for (const f of features) {
        const geom = f.getGeometry()
        if (!geom) continue
        const geomType = geom.getType()
        if (geomType === 'Point') {
          const coord = geom.getCoordinates()
          try {
            const [e, n] = transform(coord, 'EPSG:3857', epsg)
            points.push({ name: f.get('name') || f.get('label') || `P${points.length + 1}`, easting: e, northing: n, is_control: false })
          } catch { /* skip */ }
        } else if (geomType === 'LineString' || geomType === 'Polygon') {
          const coords = geomType === 'Polygon' ? (geom.getCoordinates()[0] || []) : geom.getCoordinates()
          for (const coord of coords) {
            try {
              const [e, n] = transform(coord, 'EPSG:3857', epsg)
              points.push({ name: `V${points.length + 1}`, easting: e, northing: n, is_control: false })
            } catch { /* skip */ }
          }
        }
      }
      const project: LandXMLProject = { name: 'metardu-map-export', utm_zone: 37, hemisphere: 'S' }
      downloadLandXML(project, points)
      return
    }

    let output = ''
    let filename = ''
    let mimeType = ''

    if (format === 'GeoJSON') {
      const { default: GeoJSONFormat } = await import('ol/format/GeoJSON')
      const fmt = new GeoJSONFormat()
      output = JSON.stringify(fmt.writeFeatures(p.drawSourceRef.current.getFeatures(), {
        featureProjection: 'EPSG:3857', dataProjection: 'EPSG:4326',
      }), null, 2)
      filename = 'metardu-export.geojson'
      mimeType = 'application/geo+json'
    } else if (format === 'KML') {
      const { default: KMLFormat } = await import('ol/format/KML')
      const fmt = new KMLFormat()
      output = fmt.writeFeatures(p.drawSourceRef.current.getFeatures(), {
        featureProjection: 'EPSG:3857', dataProjection: 'EPSG:4326',
      })
      filename = 'metardu-export.kml'
      mimeType = 'application/vnd.google-earth.kml+xml'
    } else {
      const { default: WKTFormat } = await import('ol/format/WKT')
      const fmt = new WKTFormat()
      const features = p.drawSourceRef.current.getFeatures()
      output = features.map((f: any) => fmt.writeGeometry(f.getGeometry(), {
        dataProjection: 'EPSG:4326', featureProjection: 'EPSG:3857', rightHanded: true,
      })).join('\n')
      filename = 'metardu-export.wkt'
      mimeType = 'text/plain'
    }

    const blob = new Blob([output], { type: mimeType })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = filename
    a.click()
    URL.revokeObjectURL(url)
  }, [p.hasFeature])

  // ── CLEAR DRAWN ──
  const clearDrawn = useCallback(() => {
    if (p.drawSourceRef.current) {
      p.drawSourceRef.current.clear()
      p.setFeatureCount(0)
    }
    if (p.measureSourceRef.current) p.measureSourceRef.current.clear()
    p.setSelectedFeature(null)
    if (p.popupRef.current && p.mapInstance.current) {
      p.mapInstance.current.getOverlays().forEach((o: any) => o.setPosition(undefined))
    }
    p.clearHistory()
  }, [])

  // ── GPS ──
  const toggleGPSInternal = useCallback(() => {
    if (!p.mapInstance.current) return
    if (!p.cleanupRef.current?.geolocation) return

    if (p.gpsTracking) {
      p.cleanupRef.current.geolocation.setTracking(false)
      p.setGpsTracking(false)
      p.setStakeoutActive(false)
    } else {
      p.cleanupRef.current.geolocation.setTracking(true)
      p.setGpsTracking(true)
      p.cleanupRef.current.geolocation.once('change:position', () => {
        const pos = p.cleanupRef.current?.geolocation?.getPosition()
        if (pos) p.mapInstance.current.getView().animate({ center: pos, zoom: 16, duration: 1000 })
      })
    }
  }, [p.gpsTracking])

  // ── STAKEOUT: Activate with full overlay ──
  const activateStakeout = useCallback(async (target: StakeoutTarget) => {
    if (!p.hasFeature('gps_stakeout')) return
    if (!p.mapInstance.current) return

    // Deactivate any existing stakeout first
    await deactivateStakeout()

    try {
      const { overlay, targetSource, targetLayer, directionSource, directionLayer } =
        await createStakeoutOverlay(target, epsg)

      // Store refs
      stakeoutOverlayRef.current = overlay
      stakeoutTargetSourceRef.current = targetSource
      stakeoutTargetLayerRef.current = targetLayer
      stakeoutDirectionSourceRef.current = directionSource
      stakeoutDirectionLayerRef.current = directionLayer

      // Add overlay and layers to the map
      p.mapInstance.current.addOverlay(overlay)
      p.mapInstance.current.addLayer(targetLayer)
      p.mapInstance.current.addLayer(directionLayer)

      // Set the target state
      p.setStakeoutTarget({ e: target.easting, n: target.northing })
      p.setStakeoutActive(true)

      // Initialize stakeoutState immediately so the panel shows live data
      // without waiting for the first GPS position update.
      // If we have a GPS position, compute initial distance/bearing.
      // If not yet, show ARRIVED status so the panel renders correctly.
      if (p.gpsPos) {
        const { transform } = await import('ol/proj')
        const [gpsE, gpsN] = transform(
          [p.gpsPos.lon, p.gpsPos.lat],
          'EPSG:4326',
          epsg
        ) as [number, number]
        const initialPos: StakeoutPosition = {
          easting: gpsE,
          northing: gpsN,
          accuracy: p.gpsPos.accuracy,
        }
        const targetPt: StakeoutTarget = {
          easting: target.easting,
          northing: target.northing,
        }
        const initialState = computeStakeoutState(initialPos, targetPt)
        p.setStakeoutState(initialState)
      } else {
        // No GPS fix yet — set ARRIVED so the panel renders in "searching" mode
        // (proximityColor amber, label SEARCHING). First GPS fix will overwrite this.
        p.setStakeoutState({
          distance: 0,
          bearing: 0,
          bearingWCB: formatBearingWCB(0),
          dE: 0,
          dN: 0,
          elevationDiff: null,
          proximityColor: 'amber',
          proximityLabel: 'SEARCHING',
        })
      }

      stakeoutCleanupDone.current = false

      // Enable GPS if not already tracking
      if (!p.gpsTracking) p.toggleGPS()

      // Zoom to target
      const { transform } = await import('ol/proj')
      const targetCoord = transform([target.easting, target.northing], epsg, 'EPSG:3857')
      p.mapInstance.current.getView().animate({ center: targetCoord, zoom: 18, duration: 800 })
    } catch (err) {
      console.error('[activateStakeout] Failed:', err)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [p.hasFeature, p.gpsTracking, p.toggleGPS, p.gpsPos])

  // ── STAKEOUT: Deactivate and clean up ──
  const deactivateStakeout = useCallback(async () => {
    if (stakeoutCleanupDone.current) return
    stakeoutCleanupDone.current = true

    stopStakeoutAudio()

    if (p.mapInstance.current) {
      // Remove overlay
      if (stakeoutOverlayRef.current) {
        try {
          p.mapInstance.current.removeOverlay(stakeoutOverlayRef.current)
        } catch { /* already removed */ }
        stakeoutOverlayRef.current = null
      }

      // Remove target layer
      if (stakeoutTargetLayerRef.current) {
        try {
          stakeoutTargetSourceRef.current?.clear()
          p.mapInstance.current.removeLayer(stakeoutTargetLayerRef.current)
        } catch { /* already removed */ }
        stakeoutTargetLayerRef.current = null
        stakeoutTargetSourceRef.current = null
      }

      // Remove direction layer
      if (stakeoutDirectionLayerRef.current) {
        try {
          stakeoutDirectionSourceRef.current?.clear()
          p.mapInstance.current.removeLayer(stakeoutDirectionLayerRef.current)
        } catch { /* already removed */ }
        stakeoutDirectionLayerRef.current = null
        stakeoutDirectionSourceRef.current = null
      }
    }

    p.setStakeoutTarget(null)
    p.setStakeoutActive(false)
    p.setStakeoutState(null)
  }, [])

  // ── STAKEOUT: Update on GPS position change ──
  const updateStakeoutOnGPS = useCallback(async () => {
    if (!p.stakeoutActive || !p.stakeoutTarget || !p.gpsPos) return
    if (!stakeoutDirectionSourceRef.current) return

    try {
      const { transform } = await import('ol/proj')
      const [gpsE, gpsN] = transform(
        [p.gpsPos.lon, p.gpsPos.lat],
        'EPSG:4326',
        epsg
      ) as [number, number]

      const currentPos: StakeoutPosition = {
        easting: gpsE,
        northing: gpsN,
        accuracy: p.gpsPos.accuracy,
      }

      const target: StakeoutTarget = {
        easting: p.stakeoutTarget.e,
        northing: p.stakeoutTarget.n,
      }

      // Update direction line on the map
      const state = await updateStakeoutDirection(
        stakeoutDirectionSourceRef.current,
        currentPos,
        target,
        epsg,
      )

      // Update target marker proximity color
      await updateTargetProximityStyle(
        stakeoutTargetSourceRef.current,
        state.proximityColor
      )

      // Update state for the panel
      p.setStakeoutState(state)

      // Trigger audio alert
      createStakeoutAudioAlert(state.distance)
    } catch { /* skip update */ }
  }, [p.stakeoutActive, p.stakeoutTarget, p.gpsPos, p.setStakeoutState])

  // ── STAKEOUT: Legacy toggle (for backward compat) ──
  const toggleStakeout = useCallback(() => {
    if (!p.hasFeature('gps_stakeout')) return
    if (!p.stakeoutTarget) {
      if (!p.mapInstance.current) return
      const center = p.mapInstance.current.getView().getCenter()
      if (center) {
        import('ol/proj').then(({ transform }) => {
          const [e, n] = transform(center, 'EPSG:3857', epsg)
          activateStakeout({ easting: e, northing: n })
        })
      }
    } else {
      deactivateStakeout()
    }
  }, [p.hasFeature, p.stakeoutTarget, activateStakeout, deactivateStakeout])

  // ── STAKEOUT INFO (uses pre-transformed UTM position — no require()) ──
  const stakeoutInfo = useCallback(() => {
    if (!p.stakeoutTarget || !p.gpsPos21037) return null

    // Use the already-transformed UTM coordinates (set by async import in MapClient)
    const gpsE = p.gpsPos21037.easting
    const gpsN = p.gpsPos21037.northing

    const dE = p.stakeoutTarget.e - gpsE
    const dN = p.stakeoutTarget.n - gpsN
    const dist = Math.sqrt(dE * dE + dN * dN)
    let bearing = (Math.atan2(dE, dN) * 180) / Math.PI
    if (bearing < 0) bearing += 360
    return { distance: dist, bearing, dE, dN }
  }, [p.stakeoutTarget, p.gpsPos21037])

  // ── SAVE TO PROJECT — saves drawn features to current project (not throwaway) ──
  const saveToProject = useCallback(async () => {
    if (!p.drawSourceRef.current) return
    const features = p.drawSourceRef.current.getFeatures()
    if (features.length === 0) {
      p.setSaveMsg('Nothing to save — draw something first')
      setTimeout(() => p.setSaveMsg(''), 3000)
      return
    }

    try {
      const { transform } = await import('ol/proj')
      const { createClient } = await import('@/lib/api-client/client')
      const dbClient = createClient()
      const { data: { session } } = await dbClient.auth.getSession()
      if (!session?.user) {
        p.setSaveMsg('Not authenticated')
        setTimeout(() => p.setSaveMsg(''), 3000)
        return
      }

      // Convert features to GeoJSON in EPSG:4326
      const { default: GeoJSONFormat } = await import('ol/format/GeoJSON')
      const fmt = new GeoJSONFormat()
      const geojson = fmt.writeFeatures(features, {
        featureProjection: 'EPSG:3857',
        dataProjection: 'EPSG:4326',
      })
      const featuresJson = JSON.parse(geojson)

      // Compute total area and perimeter for polygons
      let totalArea = 0
      let totalPerimeter = 0
      for (const f of features) {
        const geom = f.getGeometry()
        if (!geom) continue
        const type = geom.getType()
        if (type === 'Polygon' || type === 'MultiPolygon') {
          try {
            const area = Math.abs(geom.getArea())
            totalArea += area
            const perimeter = type === 'Polygon'
              ? new (await import('ol/geom/LineString')).default(geom.getCoordinates()[0]).getLength()
              : 0
            totalPerimeter += perimeter
          } catch { /* skip */ }
        } else if (type === 'LineString') {
          totalPerimeter += geom.getLength()
        }
      }

      if (p.projectId) {
        // ── Save to current project ──
        // Fetch existing boundary_data to merge
        const { data: existing } = await dbClient
          .from('projects')
          .select('name, boundary_data')
          .eq('id', p.projectId)
          .single()

        const existingBd = existing?.boundary_data || {}
        const existingDrawn = existingBd.drawnFeatures?.features || []
        const newFeatures = featuresJson.features || []

        const { error } = await dbClient
          .from('projects')
          .update({
            boundary_data: {
              ...existingBd,
              source: 'map-drawing',
              drawnFeatures: {
                type: 'FeatureCollection',
                features: [...existingDrawn, ...newFeatures],
              },
              lastDrawnAt: new Date().toISOString(),
              drawnAreaSqM: totalArea,
              drawnPerimeterM: totalPerimeter,
            },
          })
          .eq('id', p.projectId)

        if (error) {
          p.setSaveMsg(`Error: ${error.message}`)
        } else {
          const areaStr = totalArea > 0 ? ` · ${totalArea.toFixed(1)} m²` : ''
          p.setSaveMsg(`Saved ${features.length} feature(s) to "${existing?.name || 'project'}"${areaStr}`)
        }
      } else {
        // ── No project linked — create a new one ──
        const projectName = prompt('Enter a name for the new project:', `Map Drawing — ${new Date().toLocaleDateString()}`)
        if (!projectName) {
          p.setSaveMsg('Save cancelled')
          setTimeout(() => p.setSaveMsg(''), 3000)
          return
        }

        const { data: newProject, error } = await dbClient
          .from('projects')
          .insert({
            user_id: session.user.id,
            name: projectName,
            survey_type: 'cadastral',
            location: 'Drawn on map',
            utm_zone: 37,
            hemisphere: 'S',
            boundary_data: {
              source: 'map-drawing',
              drawnFeatures: featuresJson,
              createdFrom: 'map-client',
              drawnAreaSqM: totalArea,
              drawnPerimeterM: totalPerimeter,
            },
          })
          .select('id, name')
          .single()

        if (error) {
          p.setSaveMsg(`Error: ${error.message}`)
        } else {
          const areaStr = totalArea > 0 ? ` · ${totalArea.toFixed(1)} m²` : ''
          p.setSaveMsg(`Saved to "${newProject?.name}"${areaStr}`)
        }
      }
      setTimeout(() => p.setSaveMsg(''), 5000)
    } catch (err: unknown) {
      p.setSaveMsg(`Error: ${err instanceof Error ? (err as Error).message : 'Save failed'}`)
      setTimeout(() => p.setSaveMsg(''), 4000)
    }
  }, [p.projectId])

  // ── ANNOTATIONS ──
  const toggleAnnotations = useCallback(async () => {
    if (!p.mapInstance.current) return

    if (p.annotationLayerRef.current) {
      // Remove ALL annotation layers (not just the first one)
      const allLayers = (p.annotationLayerRef.current as any)._allAnnotationLayers as import('ol/layer/Vector').default[] | undefined
      if (allLayers && p.mapInstance.current) {
        for (const layer of allLayers) {
          try { p.mapInstance.current.removeLayer(layer) } catch { /* already removed */ }
        }
      } else {
        p.mapInstance.current.removeLayer(p.annotationLayerRef.current)
      }
      p.annotationLayerRef.current = null
    }

    if (p.showAnnotations) {
      p.setShowAnnotations(false)
      return
    }

    if (!p.drawSourceRef.current) return
    const features = p.drawSourceRef.current.getFeatures()
    if (features.length === 0) { p.setShowAnnotations(false); return }

    try {
      const { createDrawAnnotationLayer } = await import('@/app/map/utils/drawAnnotations')
      // Create annotation layers for ALL LineString and Polygon features, not just the first one
      const allAnnotationLayers: import('ol/layer/Vector').default[] = []

      for (const f of features) {
        const geom = f.getGeometry()
        if (!geom) continue
        const type = geom.getType()
        if (type !== 'LineString' && type !== 'Polygon') continue

        let coords: Array<[number, number]>
        if (type === 'LineString') {
          coords = geom.getCoordinates()
        } else {
          coords = geom.getCoordinates()[0] || []
        }

        if (coords.length < 2) continue

        try {
          const layer = await createDrawAnnotationLayer({
            coords3857: coords,
            geomType: type as 'LineString' | 'Polygon',
            epsg, // T1.5: pass the active UTM EPSG
          })
          allAnnotationLayers.push(layer)
        } catch {
          // Skip features that fail to annotate
        }
      }

      if (allAnnotationLayers.length === 0) {
        p.setShowAnnotations(false)
        return
      }

      // Add all annotation layers to the map
      // Store the first layer as the ref for cleanup; store all others via a closure
      for (const layer of allAnnotationLayers) {
        p.mapInstance.current.addLayer(layer)
      }

      // Use a composite cleanup: store the first layer in the ref,
      // and track all layers via a closure
      p.annotationLayerRef.current = allAnnotationLayers[0]
      // Store all layers on the ref for complete cleanup
      ;(p.annotationLayerRef.current as any)._allAnnotationLayers = allAnnotationLayers

      p.setShowAnnotations(true)
    } catch (err) {
      console.warn('Failed to create annotations:', err)
      p.setShowAnnotations(false)
    }
  }, [p.showAnnotations])

  // ── NAVIGATION ──
  const fitToKenya = useCallback(async () => {
    if (!p.mapInstance.current) return
    try {
      const { fromLonLat, toLonLat } = await import('ol/proj')
      const extent = [
        ...fromLonLat([33.9, -4.7]),
        ...fromLonLat([41.9, 5.5]),
      ]
      p.mapInstance.current.getView().fit(extent, { padding: [50, 50, 50, 50], duration: 600 })

      setTimeout(() => {
        try {
          const view = p.mapInstance.current?.getView()
          if (!view) return
          const center = view.getCenter()
          if (!center) return
          const lonLat = toLonLat(center)
          const lon = lonLat[0]
          const lat = lonLat[1]
          if (lon < 30 || lon > 45 || lat < -10 || lat > 10) {
            console.warn('[fitToKenya] View center out of Kenya bounds, falling back')
            view.setCenter(fromLonLat([37.0, -1.0]))
            view.setZoom(7)
          }
        } catch { /* ignore */ }
      }, 700)
    } catch (err) {
      console.error('[fitToKenya] Extent transform failed, falling back:', err)
      try {
        const { fromLonLat } = await import('ol/proj')
        p.mapInstance.current.getView().setCenter(fromLonLat([37.0, -1.0]))
        p.mapInstance.current.getView().setZoom(7)
      } catch { /* absolute fallback */ }
    }
  }, [])

  const fitToDrawn = useCallback(() => {
    if (!p.mapInstance.current || !p.drawSourceRef.current) return
    const extent = p.drawSourceRef.current.getExtent()
    if (extent[0] !== Infinity) {
      p.mapInstance.current.getView().fit(extent, { padding: [80, 80, 80, 80], duration: 400 })
    }
  }, [])

  const resetToKenya = useCallback(() => {
    if (!p.mapInstance.current) return
    const KENYA_EXTENT = p.mapInstance.current.getView().getExtent()
    p.mapInstance.current.getView().fit(KENYA_EXTENT, { duration: 400, padding: [0, 0, 0, 0] })
  }, [])

  const getMapExtent = useCallback(async () => {
    if (!p.mapInstance.current) return null
    try {
      const view = p.mapInstance.current.getView()
      const size = p.mapInstance.current.getSize()
      if (!size) return null
      const extent = view.calculateExtent(size)
      const { transform } = await import('ol/proj')
      const [minLon, minLat] = transform([extent[0], extent[1]], 'EPSG:3857', 'EPSG:4326')
      const [maxLon, maxLat] = transform([extent[2], extent[3]], 'EPSG:3857', 'EPSG:4326')
      return { minLat, minLon, maxLat, maxLon }
    } catch { return null }
  }, [])

  const handleCoordSearchLocal = useCallback(async (searchInput: string) => {
    const { handleCoordSearch } = await import('@/app/map/utils/coordSearch')
    await handleCoordSearch(searchInput, p.mapInstance, epsg)
  }, [epsg])

  const updateFeatureName = useCallback((name: string, selectedFeature: any) => {
    if (selectedFeature) {
      selectedFeature.set('name', name)
      selectedFeature.set('label', name)
    }
  }, [])

  const handleOpacityChange = useCallback((val: number, setLayerOpacity: (v: number) => void) => {
    setLayerOpacity(val)
    if (p.drawLayerRef.current) {
      p.drawLayerRef.current.setOpacity(val / 100)
    }
  }, [])

  return {
    toggleDraw,
    toggleEdit,
    deleteSelected,
    toggleMeasure,
    exportFeatures,
    clearDrawn,
    toggleGPS: toggleGPSInternal,
    toggleStakeout,
    stakeoutInfo,
    activateStakeout,
    deactivateStakeout,
    updateStakeoutOnGPS,
    saveToProject,
    toggleAnnotations,
    fitToKenya,
    fitToDrawn,
    resetToKenya,
    getMapExtent,
    handleCoordSearchLocal,
    updateFeatureName,
    handleOpacityChange,
  }
}

'use client'
/**
 * useMapState — Map view/feature persistence hook
 *
 * Saves map center/zoom and drawn features to localStorage:
 * - Every 10 seconds (interval)
 * - On unmount
 *
 * Uses JSON+GeoJSON format for feature serialization.
 * Only runs when map is ready.
 *
 * Note: Uses dynamic import() instead of require() for ESM compatibility.
 */

import { useEffect } from 'react'

export function useMapState(
  mapInstance: React.MutableRefObject<any>,
  drawSourceRef: React.MutableRefObject<any>,
  mapReady: boolean
) {
  useEffect(() => {
    if (!mapInstance.current) return

    const saveViewState = () => {
      try {
        const view = mapInstance.current?.getView()
        if (view) {
          const center = view.getCenter()
          const zoom = view.getZoom()
          if (center && zoom != null) {
            localStorage.setItem('metardu-map-view', JSON.stringify({ center, zoom }))
          }
        }
      } catch { /* ignore */ }
    }

    const saveFeatures = async () => {
      try {
        if (drawSourceRef.current) {
          const features = drawSourceRef.current.getFeatures()
          if (features.length > 0) {
            const { default: GeoJSONFormat } = await import('ol/format/GeoJSON')
            const fmt = new GeoJSONFormat()
            const geojson = fmt.writeFeatures(features, {
              featureProjection: 'EPSG:3857',
              dataProjection: 'EPSG:4326',
            })
            localStorage.setItem('metardu-map-features', JSON.stringify(geojson))
          } else {
            localStorage.removeItem('metardu-map-features')
          }
        }
      } catch { /* ignore */ }
    }

    const interval = setInterval(() => {
      saveViewState()
      saveFeatures()
    }, 10000)

    return () => {
      clearInterval(interval)
      saveViewState()
    }
  }, [mapReady])
}

'use client'

/**
 * useViewportQuery — Dynamic spatial data loading based on map viewport
 *
 * When the surveyor pans or zooms the map, this hook:
 * 1. Captures the current bounding box (view extent)
 * 2. Transforms from map projection (EPSG:3857) to WGS84 (EPSG:4326)
 * 3. Sends a debounced request to the spatial API
 * 4. Loads nearby parcels, beacons, and field records into the map
 *
 * Uses performance utilities:
 * - useDebouncedCallback for 500ms debounce
 * - Deduplication to skip identical extents
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { useDebouncedCallback } from '@/lib/performance'

export interface ViewportFeature {
  id: string
  type: 'parcel' | 'beacon' | 'field_record' | 'control_point'
  geometry: {
    type: 'Point' | 'Polygon' | 'LineString'
    coordinates: number[] | number[][] | number[][][]
  }
  properties: Record<string, unknown>
}

interface UseViewportQueryOptions {
  mapInstance: React.MutableRefObject<any>
  mapReady: boolean
  enabled?: boolean
  debounceMs?: number
  onFeaturesLoaded?: (features: ViewportFeature[]) => void
}

export function useViewportQuery({
  mapInstance,
  mapReady,
  enabled = true,
  debounceMs = 500,
  onFeaturesLoaded,
}: UseViewportQueryOptions) {
  const [isLoading, setIsLoading] = useState(false)
  const [featureCount, setFeatureCount] = useState(0)
  const [lastExtent, setLastExtent] = useState<string>('')
  const lastRequestRef = useRef<string>('')

  const fetchViewport = useCallback(async () => {
    if (!mapInstance.current || !enabled) return

    try {
      const map = mapInstance.current
      const view = map.getView()
      const extent = view.calculateExtent(map.getSize())

      if (!extent || extent.length !== 4) return

      // Deduplicate: skip if extent hasn't changed meaningfully
      const extentKey = `${extent[0].toFixed(0)},${extent[1].toFixed(0)},${extent[2].toFixed(0)},${extent[3].toFixed(0)}`
      if (extentKey === lastRequestRef.current) return
      lastRequestRef.current = extentKey
      setLastExtent(extentKey)

      // Transform to WGS84 for the API
      const { transformExtent } = await import('ol/proj')
      const wgs84Extent = transformExtent(extent, 'EPSG:3857', 'EPSG:4326')
      const [minLng, minLat, maxLng, maxLat] = wgs84Extent

      setIsLoading(true)

      // Fetch spatial features in viewport
      const params = new URLSearchParams({
        west: minLng.toFixed(6),
        south: minLat.toFixed(6),
        east: maxLng.toFixed(6),
        north: maxLat.toFixed(6),
        limit: '200',
      })

      const res = await fetch(`/api/spatial-index?${params}`)
      if (!res.ok) {
        setIsLoading(false)
        return
      }

      const data = await res.json()
      const features = (data.data?.features || []) as ViewportFeature[]
      setFeatureCount(features.length)
      onFeaturesLoaded?.(features)
    } catch (err) {
      // Silent fail — viewport queries are non-critical
    } finally {
      setIsLoading(false)
    }
  }, [mapInstance, enabled, onFeaturesLoaded])

  // Use performance utility for debounced fetch
  const debouncedFetch = useDebouncedCallback(fetchViewport, debounceMs)

  // Listen for moveend events
  useEffect(() => {
    if (!mapReady || !enabled || !mapInstance.current) return

    const map = mapInstance.current

    map.on('moveend', debouncedFetch)

    // Initial fetch
    fetchViewport()

    return () => {
      map.un('moveend', debouncedFetch)
    }
  }, [mapReady, enabled, mapInstance, fetchViewport, debounceMs])

  return {
    isLoading,
    featureCount,
    lastExtent,
    refresh: fetchViewport,
  }
}

import type { MutableRefObject } from 'react'

/**
 * Navigates the map to coordinates parsed from a search string.
 *
 * Accepts formats:
 *  - Lat/Lon decimal (e.g. "-1.0, 37.0" or "-1.0 37.0")
 *  - DMS format (e.g. "1°15'30"S 37°45'20"E" or "1 15 30 S 37 45 20 E")
 *  - UTM Easting/Northing in EPSG:21037 (large numbers, e.g. "500000 9800000")
 *  - Beacon names (e.g. "Beacon 5" or "BM12")
 *  - Parcel numbers (e.g. "LR12345" or "Parcel 5")
 *
 * Note: The caller is responsible for clearing the search input after
 * this resolves, since the setter lives in component state.
 */

interface DMSResult {
  decimal: number
  hemisphere: string
}

/**
 * Parse a single DMS (Degrees, Minutes, Seconds) string.
 * Examples:
 *   "1°15'30"S" → { decimal: -1.258333, hemisphere: 'S' }
 *   "37°45'20"E" → { decimal: 37.755556, hemisphere: 'E' }
 *   "1 15 30" → { decimal: 1.258333, hemisphere: '' }
 */
function parseDMS(dmsStr: string): DMSResult | null {
  // Pattern: degrees°minutes'seconds"hemisphere (or variations)
  // Handles: 1°15'30"S, 1° 15' 30" S, 1 15 30 S, S1°15'30"
  const dmsRegex = /([NSEW])?\s*(\d+(?:\.\d+)?)\s*[°\s]\s*(\d+(?:\.\d+)?)\s*['′\s]\s*(\d+(?:\.\d+)?)\s*["″]?\s*([NSEW])?/i
  const match = dmsStr.trim().match(dmsRegex)

  if (!match) return null

  const prefixHem = (match[1] || '').toUpperCase()
  const degrees = parseFloat(match[2])
  const minutes = parseFloat(match[3])
  const seconds = parseFloat(match[4])
  const suffixHem = (match[5] || '').toUpperCase()

  if (isNaN(degrees) || isNaN(minutes) || isNaN(seconds)) return null
  if (degrees < 0 || degrees > 180 || minutes < 0 || minutes >= 60 || seconds < 0 || seconds >= 60) return null

  const hemisphere = suffixHem || prefixHem
  let decimal = degrees + minutes / 60 + seconds / 3600

  if (hemisphere === 'S' || hemisphere === 'W') decimal = -decimal

  return { decimal, hemisphere }
}

/**
 * Try to parse a full coordinate string as DMS.
 * Supports patterns like:
 *   "1°15'30"S 37°45'20"E"
 *   "S1°15'30" E37°45'20""
 *   "1 15 30 S 37 45 20 E"
 *   "1°15'30" 37°45'20"" (assumes Kenya: S lat, E lon)
 */
function tryParseDMS(input: string): { lat: number; lon: number } | null {
  // Try splitting by comma or whitespace between two DMS groups
  // Pattern: two DMS groups separated by comma or space

  // First, try comma-separated
  const commaParts = input.split(',').map(s => s.trim()).filter(Boolean)
  if (commaParts.length === 2) {
    const lat = parseDMS(commaParts[0])
    const lon = parseDMS(commaParts[1])
    if (lat && lon) {
      let latVal = lat.decimal
      let lonVal = lon.decimal
      // Kenya default: if no hemisphere specified, assume S for lat, E for lon
      if (!lat.hemisphere && latVal > 0) latVal = -latVal
      if (!lon.hemisphere && lonVal < 0) lonVal = Math.abs(lonVal)
      return { lat: latVal, lon: lonVal }
    }
  }

  // Try space-separated with hemisphere indicators
  // e.g. "1°15'30"S 37°45'20"E"
  const spaceParts = input.trim().split(/\s+/)

  // Try to find two DMS groups
  // Strategy: try different split points
  for (let splitAt = 1; splitAt < spaceParts.length; splitAt++) {
    const leftStr = spaceParts.slice(0, splitAt).join(' ')
    const rightStr = spaceParts.slice(splitAt).join(' ')
    const lat = parseDMS(leftStr)
    const lon = parseDMS(rightStr)
    if (lat && lon) {
      let latVal = lat.decimal
      let lonVal = lon.decimal
      if (!lat.hemisphere && latVal > 0) latVal = -latVal
      if (!lon.hemisphere && lonVal < 0) lonVal = Math.abs(lonVal)
      return { lat: latVal, lon: lonVal }
    }
  }

  // Try the whole string as two DMS groups without spaces between them
  // This handles "S1°15'30"E37°45'20"
  const twoGroupsRegex = /([NSEW])?\s*(\d+)\s*[°]\s*(\d+)\s*['′]\s*(\d+(?:\.\d+)?)\s*["″]?\s*([NSEW])?\s*([NSEW])?\s*(\d+)\s*[°]\s*(\d+)\s*['′]\s*(\d+(?:\.\d+)?)\s*["″]?\s*([NSEW])?/i
  const twoMatch = input.match(twoGroupsRegex)
  if (twoMatch) {
    const lat = parseDMS(`${twoMatch[1] || ''}${twoMatch[2]}°${twoMatch[3]}'${twoMatch[4]}"${twoMatch[5] || ''}`)
    const lon = parseDMS(`${twoMatch[6] || ''}${twoMatch[7]}°${twoMatch[8]}'${twoMatch[9]}"${twoMatch[10] || ''}`)
    if (lat && lon) {
      let latVal = lat.decimal
      let lonVal = lon.decimal
      if (!lat.hemisphere && latVal > 0) latVal = -latVal
      if (!lon.hemisphere && lonVal < 0) lonVal = Math.abs(lonVal)
      return { lat: latVal, lon: lonVal }
    }
  }

  return null
}

/**
 * Flash a feature on the map by briefly toggling its style.
 * Creates a highlight overlay that fades after a short duration.
 */
async function flashFeature(mapInstance: MutableRefObject<any>, feature: any): Promise<void> {
  try {
    const [{ default: Style }, { default: Stroke }, { default: Fill }, { default: CircleStyle }] =
      await Promise.all([
        import('ol/style/Style'),
        import('ol/style/Stroke'),
        import('ol/style/Fill'),
        import('ol/style/Circle'),
      ])

    const originalStyle = feature.getStyle()
    const flashStyle = new Style({
      stroke: new Stroke({ color: '#D17B47', width: 4 }),
      fill: new Fill({ color: 'rgba(209, 123, 71, 0.3)' }),
      image: new CircleStyle({
        radius: 12,
        fill: new Fill({ color: 'rgba(209, 123, 71, 0.5)' }),
        stroke: new Stroke({ color: '#D17B47', width: 3 }),
      }),
    })

    feature.setStyle(flashStyle)
    setTimeout(() => {
      feature.setStyle(originalStyle || undefined)
    }, 1500)
  } catch {
    // Flash is best-effort
  }
}

/**
 * Search all VectorLayer sources on the map for a feature whose label/name/number
 * matches the given search term.
 */
async function searchFeatureOnMap(
  mapInstance: MutableRefObject<any>,
  searchTerm: string,
  options: { parcelOnly?: boolean; beaconOnly?: boolean } = {},
): Promise<any | null> {
  if (!mapInstance.current) return null

  const { default: VectorLayer } = await import('ol/layer/Vector')
  const layers = mapInstance.current.getLayers().getArray()
  const term = searchTerm.toLowerCase().trim()

  for (const layer of layers) {
    if (!(layer instanceof VectorLayer)) continue
    const source = layer.getSource()
    if (!source || typeof source.getFeatures !== 'function') continue

    const features = source.getFeatures()
    for (const feature of features) {
      // Check various feature properties for a match
      const props = feature.getProperties() || {}
      const label = (props.label || props.name || props.beacon_name || props.stationName || '')
        .toString()
        .toLowerCase()
      const parcelNumber = (props.parcelNumber || props.parcel_number || props.parcelNo || '')
        .toString()
        .toLowerCase()

      if (options.beaconOnly) {
        // Match beacon-like names: "Beacon 5", "BM12", etc.
        if (label && (label === term || label.includes(term))) {
          return feature
        }
      } else if (options.parcelOnly) {
        // Match parcel numbers: "LR12345", "Parcel 5", etc.
        if (
          parcelNumber &&
          (parcelNumber === term || parcelNumber.includes(term) || term.includes(parcelNumber))
        ) {
          return feature
        }
        if (label && (label === term || label.includes(term))) {
          return feature
        }
      }
    }
  }

  return null
}

/**
 * Check if the search term looks like a beacon name (e.g. "Beacon 5", "BM12").
 */
function looksLikeBeaconName(input: string): boolean {
  const t = input.trim()
  return /^(beacon|bm|b)\s*\d+/i.test(t) || /^bm\d+/i.test(t)
}

/**
 * Check if the search term looks like a parcel number (e.g. "LR12345", "Parcel 5").
 */
function looksLikeParcelNumber(input: string): boolean {
  const t = input.trim()
  return /^(parcel|lot|lr|plot)\s*\d+/i.test(t) || /^lr\d+/i.test(t)
}

export async function handleCoordSearch(
  searchInput: string,
  mapInstance: MutableRefObject<any>,
  epsg: string = 'EPSG:21037',
): Promise<void> {
  if (!mapInstance.current || !searchInput.trim()) return

  // ── Try beacon name search ──
  if (looksLikeBeaconName(searchInput)) {
    const feature = await searchFeatureOnMap(mapInstance, searchInput, { beaconOnly: true })
    if (feature) {
      const geom = feature.getGeometry()
      if (geom) {
        const coord = geom.getType() === 'Point'
          ? geom.getCoordinates()
          : geom.getClosestPoint(mapInstance.current.getView().getCenter())
        mapInstance.current.getView().animate({ center: coord, zoom: 18, duration: 600 })
        flashFeature(mapInstance, feature)
        return
      }
    }
  }

  // ── Try parcel number search ──
  if (looksLikeParcelNumber(searchInput)) {
    const feature = await searchFeatureOnMap(mapInstance, searchInput, { parcelOnly: true })
    if (feature) {
      const geom = feature.getGeometry()
      if (geom) {
        const extent = geom.getExtent()
        if (extent && extent[0] !== Infinity) {
          mapInstance.current.getView().fit(extent, { padding: [100, 100, 100, 100], maxZoom: 18, duration: 600 })
        }
        flashFeature(mapInstance, feature)
        return
      }
    }
  }

  // ── Try DMS format ──
  const dmsResult = tryParseDMS(searchInput)
  if (dmsResult) {
    const { fromLonLat } = await import('ol/proj')
    const center = fromLonLat([dmsResult.lon, dmsResult.lat])
    mapInstance.current.getView().animate({ center, zoom: 16, duration: 600 })
    return
  }

  // ── Try decimal lat/lon or UTM ──
  const parts = searchInput.trim().split(/[,\s]+/).map(Number).filter(n => !isNaN(n))

  if (parts.length >= 2) {
    let lon = parts[1]
    let lat = parts[0]

    // If values look like Eastings/Northings (large numbers), treat differently
    if (Math.abs(parts[0]) > 100 && Math.abs(parts[1]) > 100) {
      // Likely UTM coordinates - try to transform from the active UTM zone
      try {
        const { transform } = await import('ol/proj')
        const [x, y] = transform([parts[0], parts[1]], epsg, 'EPSG:3857')
        mapInstance.current.getView().animate({ center: [x, y], zoom: 16, duration: 600 })
      } catch { /* fallback */ }
    } else {
      if (lon > lat) { [lon, lat] = [lat, lon] } // common swap
      const { fromLonLat } = await import('ol/proj')
      const center = fromLonLat([lon, lat])
      mapInstance.current.getView().animate({ center, zoom: 16, duration: 600 })
    }
  }
}

