        {/* Recent Observations */}
        {recentObservations.length > 0 && (
          <div className="px-4 pb-4">
            <div className="text-xs text-gray-500 uppercase tracking-wider font-medium mb-2">Recent Observations</div>
            <div className="space-y-1.5">
