// ── Main page ─────────────────────────────────────────────────────────────────

interface PageProps { params: { id: string } }

export default function DocumentsPage({ params }: PageProps) {
  const { plan } = useSubscription()
  const [project, setProject] = useState<ProjectData | null>(null)
  const [points, setPoints]   = useState<PointData[]>([])
  const [traverse, setTraverse] = useState<TraverseData | undefined>()
  const [area, setArea]         = useState<AreaData | undefined>()
  const [loading, setLoading]   = useState(true)
  const [surveyorDetails, setSurveyorDetails] = useState<Record<string,string>>({})
  const [activeTab, setActiveTab] = useState<'docs' | 'plan'>('docs')
  const [activeDoc, setActiveDoc] = useState<SurveyDocType | null>(null)
  const [extraFields, setExtraFields] = useState<Record<string,Record<string,string>>>({})
  const [submissionNumber, setSubmissionNumber] = useState<string>('')
  const [isCreatingSubmission, setIsCreatingSubmission] = useState(false)
  const [generated, setGenerated] = useState<Set<SurveyDocType>>(new Set())
  const [adjacentParcels, setAdjacentParcels] = useState<Array<{ id: string; lrNumber: string; planReference: string; boundaryPoints: Array<{ easting: number; northing: number }> }>>([])

  const load = useCallback(async () => {
    const dbClient = createClient()
    const { data: { session } } = await dbClient.auth.getSession()
    if (!session?.user) {
      window.location.replace(`/login?next=/project/${params.id}/documents`)
      return
    }

    const [{ data: proj }, { data: pts }, { data: parcels }] = await Promise.all([
      dbClient.from('projects').select('*').eq('id', params.id).single(),
      dbClient.from('survey_points').select('*').eq('project_id', params.id).order('created_at'),
      dbClient.from('parcels').select('*').eq('project_id', params.id).limit(1).single(),
    ])

    if (proj) setProject(proj)
     if (pts) setPoints(pts.map((p: SurveyPoint) => ({
       name: p.name, easting: p.easting, northing: p.northing,
       elevation: p.elevation ?? undefined, is_control: p.is_control,
     })))
    setLoading(false)
  }, [params.id])

  useEffect(() => { load() }, [load])

  // Fetch submission number if available
  useEffect(() => {
    if (params.id) {
      const dbClient = createClient()
      dbClient.from('project_submissions')
        .select('submission_number')
        .eq('project_id', params.id)
        .order('created_at', { ascending: false })
        .limit(1)
        .then(({ data }) => {
          if (data?.[0]?.submission_number) {
            setSubmissionNumber(data[0].submission_number)
          }
        })
    }
  }, [params.id])

  // Fetch adjacent parcels (other parcels in the same block/scheme)
  useEffect(() => {
    if (!project) return
    const dbClient = createClient()
    // Fetch parcels in the same project that are not the subject parcel
    dbClient.from('parcels')
      .select('id, parcel_number, lr_number_proposed, boundary_geojson')
      .eq('project_id', params.id)
      .then(({ data }) => {
        if (data && data.length > 1) {
          const adjLots = data.slice(0, 5).map((p: any) => {
            // Parse boundary coordinates from GeoJSON if available
            let bdyPts: Array<{ easting: number; northing: number }> = []
            if (p.boundary_geojson) {
              try {
                const geojson = typeof p.boundary_geojson === 'string'
                  ? JSON.parse(p.boundary_geojson)
                  : p.boundary_geojson
                if (geojson?.features?.[0]?.geometry?.coordinates) {
                  const coords = geojson.features[0].geometry.coordinates[0] || geojson.features[0].geometry.coordinates
                  bdyPts = coords.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
                } else if (geojson?.geometry?.coordinates) {
                  const coords = geojson.geometry.coordinates[0] || geojson.geometry.coordinates
                  bdyPts = coords.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
                } else if (Array.isArray(geojson?.coordinates)) {
                  const coords = geojson.coordinates[0] || geojson.coordinates
                  bdyPts = coords.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
                }
              } catch { /* ignore parse errors */ }
            }
            return {
              id: p.lr_number_proposed || p.parcel_number || `Parcel ${p.id}`,
              lrNumber: p.lr_number_proposed || '',
              planReference: p.parcel_number || '',
              boundaryPoints: bdyPts,
            }
          }).filter((lot: any) => lot.boundaryPoints.length >= 2)
          setAdjacentParcels(adjLots)
        }
      })
  }, [project, params.id])



  const getExtra = (docId: SurveyDocType) => extraFields[docId] || {}
  const setExtra = (docId: SurveyDocType, d: Record<string,string>) =>
    setExtraFields(prev => ({ ...prev, [docId]: d }))

  const generateDoc = (docId: SurveyDocType) => {
    if (!project) return
    const extra = getExtra(docId)
    let html = ''
    const args = [project, surveyorDetails] as const

    switch (docId) {
      case 'cover_letter':
        html = generateCoverLetter(...args, extra); break
      case 'computation_sheet':
        html = generateComputationSheet(...args, points, traverse, area); break
      case 'area_certificate':
        html = generateAreaCertificate(...args, area, extra); break
      case 'field_notes':
        html = generateFieldNotes(...args, points, extra); break
      case 'beacon_descriptions':
        html = generateBeaconDescriptions(...args, points, extra); break
      case 'completion_certificate':
      case 'as_built_certificate':
        html = generateCompletionCertificate(...args, extra); break
      case 'mutation_form':
        html = generateMutationForm(...args, points, area, extra); break
      case 'leveling_summary':
        html = generateLevelingSummary(...args, points, extra); break
      case 'control_submission':
        html = generateControlSubmission(...args, points, extra); break
      default:
        html = generateComputationSheet(...args, points, traverse, area)
    }

    openPrint(html, `${project.name} — ${docId.replace(/_/g,' ')}.pdf`)
    setGenerated(prev => { const s = new Set(Array.from(prev)); s.add(docId); return s })
  }

  if (loading) return (
    <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
      <div className="w-6 h-6 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
    </div>
  )

  if (!project) return (
    <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
      <div className="text-center"><p className="text-[var(--text-muted)] mb-4">Project not found</p>
        <Link href="/dashboard" className="btn btn-primary">Dashboard</Link></div>
    </div>
  )

  const docs = getDocsForType(project.survey_type)

  // Build SurveyPlanData from project
  const buildSurveyPlanData = (): SurveyPlanData | null => {
    if (!project) return null
     const controlPts: ControlPoint[] = points
       .filter((p: SurveyPoint) => p.is_control)
       .map((p: SurveyPoint) => ({
        name: p.name,
        easting: p.easting,
        northing: p.northing,
        // Canonical SurveyPoint.elevation is `number | null | undefined`;
        // ControlPoint.elevation is `number | undefined`. Coerce null to undefined.
        elevation: p.elevation ?? undefined,
        monumentType: 'found' as const,
      }))
    const boundaryPts = controlPts.length >= 3
      ? controlPts
      : [
          { name: '1', easting: 5000, northing: 5000 },
          { name: '2', easting: 5100, northing: 5000 },
          { name: '3', easting: 5100, northing: 5050 },
          { name: '4', easting: 5000, northing: 5050 },
        ]
    const area_sqm = shoelaceArea(boundaryPts)
    const perimeter_m = shoelacePerimeter(boundaryPts)
    const bearingSchedule = boundaryPts.map((pt, i) => {
      const next = boundaryPts[(i + 1) % boundaryPts.length]
      const dE = next.easting - pt.easting
      const dN = next.northing - pt.northing
      return {
        from: pt.name,
        to: next.name,
        bearing: formatBearingDegMinSec(bearingFromDelta(dE, dN)),
        distance: distance(pt.easting, pt.northing, next.easting, next.northing),
      }
    })
    const linearError = traverse?.linearError
    const traverseAccuracyResult = linearError != null
      ? computeTraverseAccuracy(linearError, perimeter_m)
      : null
    const proj = project as any
    return {
      project: {
        name: project.name,
        location: project.location || '',
        municipality: surveyorDetails['address']?.split(',')[0] || undefined,
        utm_zone: project.utm_zone || 37,
        hemisphere: (project.hemisphere || 'S') as 'N' | 'S',
        datum: 'ARC1960',
        client_name: project.client_name || undefined,
        surveyor_name: surveyorDetails['name'] || undefined,
        surveyor_licence: surveyorDetails['licence'] || undefined,
        firm_name: surveyorDetails['name'] || undefined,
        firm_address: surveyorDetails['address'] || undefined,
        firm_phone: surveyorDetails['phone'] || undefined,
        firm_email: surveyorDetails['email'] || undefined,
        drawing_no: `MD-${Date.now().toString().slice(-6)}`,
        plan_title: 'Boundary Identification Plan',
        northRotationDeg: 0,
        bearingSchedule,
        revisions: [],
        iskRegNo: surveyorDetails['licence'] || '',
        // Form No. 4 / Kenya submission fields
        lrNumber: proj.lr_number || undefined,
        folioNumber: proj.folio_number || undefined,
        registerNumber: proj.register_number || undefined,
        plotParcelNumber: proj.plot_parcel_number || undefined,
        registrationDistrict: proj.registration_district || undefined,
        locality: proj.locality || undefined,
      },
      parcel: {
        boundaryPoints: boundaryPts,
        area_sqm,
        perimeter_m,
      },
      traverse: traverseAccuracyResult ? {
        linearError: linearError ?? undefined,
      } : undefined,
      controlPoints: controlPts,
      fenceOffsets: [],
      // Adjacent lots — populated from other parcels in the same project
      // Used to draw adjacent LR numbers on boundary lines per Cap. 299 practice
      adjacentLots: adjacentParcels.map(ap => ({
        id: ap.lrNumber || ap.id,
        boundaryPoints: ap.boundaryPoints,
        planReference: ap.planReference,
      })),
    }
  }

  const planData = buildSurveyPlanData()
  const traverseAccuracy = traverse && traverse.linearError != null && planData?.parcel?.perimeter_m
    ? computeTraverseAccuracy(traverse.linearError, planData.parcel.perimeter_m)
    : null

  const handleCreateSubmission = async () => {
    if (!project || isCreatingSubmission) return
    
    setIsCreatingSubmission(true)
    try {
      const response = await fetch('/api/submissions/create', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ projectId: params.id })
      })
      
      const result = await response.json()
      
      if (result.success && result.submissionNumber) {
        setSubmissionNumber(result.submissionNumber)
        alert(`Submission created: ${result.submissionNumber}`)
      } else {
        alert(result.error || 'Failed to create submission')
      }
    } catch (error) {
      console.error('Error creating submission:', error)
      alert('Error creating submission. Please try again.')
    } finally {
      setIsCreatingSubmission(false)
    }
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-4xl mx-auto px-4 py-8">

{/* Header */}
        <div className="flex items-start justify-between mb-6">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Link href={`/project/${params.id}`} className="text-xs text-[var(--text-muted)] hover:text-[var(--accent)]">← Back to project</Link>
            </div>
            <h1 className="text-2xl font-bold text-[var(--text-primary)]">Documents & Plans</h1>
            <p className="text-sm text-[var(--text-muted)] mt-1">
              {project.name} · {project.survey_type || 'Survey'} · {project.location || ''}
            </p>
          </div>

          {/* Submission Actions */}
          <div className="flex flex-col items-end gap-2">
            {submissionNumber ? (
              <div className="bg-green-50 border border-green-200 rounded-lg px-3 py-2">
                <p className="text-xs text-green-600 font-mono">Submission: {submissionNumber}</p>
              </div>
            ) : (
              <button
                onClick={handleCreateSubmission}
                disabled={isCreatingSubmission || !project}
                className="flex items-center gap-2 px-4 py-2 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm hover:bg-[var(--accent-dim)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {isCreatingSubmission ? (
                  <>
                    <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin" />
                    Creating...
                  </>
                ) : (
                  <>
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4" />
                    </svg>
                    Create Submission
                  </>
                )}
              </button>
            )}

            {submissionNumber && (
              <button
                onClick={() => alert('Download full submission package coming soon!')}
                className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white font-semibold rounded-lg text-sm hover:bg-green-700 transition-colors"
              >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
                Download Package
              </button>
            )}
          </div>
        </div>

        <MobileDesktopNotice>
          Document generation and review involve long forms, tables, previews, and export checks. Use desktop for the best experience; mobile is suitable for viewing and minor edits.
        </MobileDesktopNotice>

        {/* Tab bar */}
        <div className="flex gap-1 mb-6 border-b border-[var(--border-color)]">
          <button onClick={() => setActiveTab('docs')}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px ${
              activeTab === 'docs'
                ? 'border-[var(--accent)] text-[var(--accent)]'
                : 'border-transparent text-[var(--text-muted)] hover:text-[var(--text-primary)]'
            }`}>
            Document Package
          </button>
          <button onClick={() => setActiveTab('plan')}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px ${
              activeTab === 'plan'
                ? 'border-[var(--accent)] text-[var(--accent)]'
                : 'border-transparent text-[var(--text-muted)] hover:text-[var(--text-primary)]'
            }`}>
            Survey Plan
          </button>
        </div>

        {/* Survey Plan tab */}
        {activeTab === 'plan' && (
          <div className="space-y-4">
            <div className="bg-[var(--accent)]/5 border border-[var(--accent)]/20 rounded-xl p-4 text-sm">
              <p className="text-[var(--text-secondary)]">
                <strong className="text-[var(--text-primary)]">Boundary Identification Plan</strong> — A professional A3 survey plan rendered from your project coordinates, ready to print and sign.
              </p>
              <p className="text-[var(--text-muted)] mt-1 text-xs">
                Requires at least 3 control points marked on the parcel boundary.
              </p>
            </div>
            {traverseAccuracy && traverse && (
              <div className="flex items-center gap-3 px-4 py-3 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl">
                <span className="text-xs text-[var(--text-secondary)] uppercase tracking-wider">Traverse Accuracy</span>
                <span className={`px-2.5 py-1 rounded text-xs font-semibold ${getAccuracyBadgeClass(traverseAccuracy)}`}>
                  {getAccuracyBadgeLabel(traverseAccuracy)}
                </span>
                <span className="text-xs text-[var(--text-secondary)]">
                  Linear Error: {traverse.linearError?.toFixed(4)}m
                </span>
                <span className="text-xs text-[var(--text-secondary)]">
                  Precision: 1:{traverseAccuracy.K_km > 0 ? Math.round(traverseAccuracy.K_km * traverseAccuracy.C_mm / traverseAccuracy.allowed) : '—'}
                </span>
                <span className="text-xs text-[var(--text-muted)] font-mono ml-auto">
                  {traverseAccuracy.formula}
                </span>
              </div>
            )}
<div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl overflow-hidden" style={{ height: '70vh' }}>
          {planData ? (
            <SurveyPlanViewer 
              data={planData} 
              className="h-full" 
              submissionNumber={submissionNumber}
            />
          ) : (
            <div className="flex items-center justify-center h-full text-[var(--text-muted)]">Loading...</div>
          )}
        </div>
        <div className="flex justify-end gap-3">
          {planData && (
            <>
              <ShapefileExport 
                data={{
                  beacons: planData.controlPoints.map(cp => ({
                    station: cp.name,
                    easting: cp.easting,
                    northing: cp.northing,
                    elevation: cp.elevation,
                    beacon_class: cp.monumentType,
                    description: cp.beaconDescription
                  })),
                  boundaries: (planData.project.bearingSchedule || []).map(b => ({
                    from: b.from,
                    to: b.to,
                    from_easting: 0, // Will be populated from actual data
                    from_northing: 0,
                    to_easting: 0,
                    to_northing: 0,
                    bearing: b.bearing,
                    distance: b.distance
                  })),
                  parcels: [{
                    id: planData.project.parcel_id || 'P1',
                    lr_number: planData.project.lrNumber,
                    area_sqm: planData.parcel.area_sqm,
                    area_ha: planData.parcel.area_sqm / 10000,
                    coordinates: planData.parcel.boundaryPoints.map(p => [p.easting, p.northing] as [number, number])
                  }],
                  projection: {
                    zone: planData.project.utm_zone || 37,
                    hemisphere: planData.project.hemisphere || 'S',
                    datum: planData.project.datum || 'ARC1960',
                    ellipsoid: 'WGS84'
                  }
                }}
                projectName={project?.name || 'survey'}
              />
              <SurveyPlanExport data={planData} projectId={params.id} plan={plan} />
            </>
          )}
        </div>
          </div>
        )}

        {/* Document package tab */}
        {activeTab === 'docs' && (
        <>

        {/* Info banner */}
        <div className="bg-[var(--accent)]/5 border border-[var(--accent)]/20 rounded-xl p-4 mb-6 text-sm">
          <p className="text-[var(--text-secondary)]">
            <strong className="text-[var(--text-primary)]">{docs.filter((d: any) =>d.required).length} required documents</strong> for a {(project.survey_type||'boundary').toLowerCase()} survey — pre-filled with your project data.
            Fill in the extra fields for each document, then click <strong>Generate &amp; Print</strong>. Each opens in a new tab ready to print as PDF.
          </p>
        </div>

        {/* Professional disclaimer */}
        <ProfessionalDisclaimer />

        {/* Surveyor details */}
        <SurveyorDetailsPanel details={surveyorDetails} onChange={setSurveyorDetails} saveState="saved" />

        {/* Document list */}
        <div className="space-y-3">
          {docs.map((doc: any) => {
            const isActive = activeDoc === doc.id
            const isDone = generated.has(doc.id)

            return (
              <div key={doc.id}
                className={`bg-[var(--bg-card)] border rounded-xl overflow-hidden transition-colors ${
                  isDone ? 'border-green-700/40' : isActive ? 'border-[var(--accent)]/40' : 'border-[var(--border-color)]'
                }`}>

                {/* Document header */}
                <div className="flex items-center gap-3 px-5 py-4 cursor-pointer hover:bg-[var(--bg-secondary)] transition-colors"
                  onClick={() => setActiveDoc(isActive ? null : doc.id)}>
                  {/* Status icon */}
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${
                    isDone ? 'bg-green-900/40 border border-green-700/40' : 'bg-[var(--bg-tertiary)] border border-[var(--border-color)]'
                  }`}>
                    {isDone
                      ? <svg className="w-4 h-4 text-green-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5"/></svg>
                      : <svg className="w-4 h-4 text-[var(--text-muted)]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}><path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m2.25 0H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z"/></svg>
                    }
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <p className="text-sm font-semibold text-[var(--text-primary)]">{doc.title}</p>
                      {doc.required && <span className="text-[10px] px-1.5 py-0.5 rounded bg-[var(--accent)]/10 text-[var(--accent)] border border-[var(--accent)]/20">Required</span>}
                      {isDone && <span className="text-[10px] text-green-400"> Generated</span>}
                    </div>
                    <p className="text-xs text-[var(--text-muted)] mt-0.5">{doc.description}</p>
                  </div>

                  {/* Generate button — inline for quick access */}
                  <button onClick={e => { e.stopPropagation(); generateDoc(doc.id) }}
                    className={`flex-shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                      isDone
                        ? 'bg-green-900/30 text-green-400 hover:bg-green-900/50 border border-green-700/30'
                        : 'bg-[var(--accent)] text-black hover:bg-[var(--accent-dim)]'
                    }`}>
                    <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M6.72 13.829c-.24.03-.48.062-.72.096m.72-.096a42.415 42.415 0 0110.56 0m-10.56 0L6.34 18m10.94-4.171c.24.03.48.062.72.096m-.72-.096L17.66 18m0 0l.229 2.523a1.125 1.125 0 01-1.12 1.227H7.231c-.662 0-1.18-.568-1.12-1.227L6.34 18m11.318 0h1.091A2.25 2.25 0 0021 15.75V9.456c0-1.081-.768-2.015-1.837-2.175a48.055 48.055 0 00-1.913-.247M6.34 18H5.25A2.25 2.25 0 013 15.75V9.456c0-1.081.768-2.015 1.837-2.175a48.041 48.041 0 011.913-.247m10.5 0a48.536 48.536 0 00-10.5 0m10.5 0V3.375c0-.621-.504-1.125-1.125-1.125h-4.5c-.621 0-1.125.504-1.125 1.125v3.659M18 10.5h.008v.008H18V10.5zm-3 0h.008v.008H15V10.5z" />
                    </svg>
                    {isDone ? 'Re-print' : 'Generate & Print'}
                  </button>

                  <svg className={`w-4 h-4 text-[var(--text-muted)] transition-transform flex-shrink-0 ${isActive ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5"/></svg>
                </div>

                {/* Expanded extra fields */}
                {isActive && (
                  <div className="px-5 pb-5 border-t border-[var(--border-color)] pt-4">
                    <p className="text-xs text-[var(--text-muted)] mb-3">
                      Fill in any additional details before generating. Project data is already included automatically.
                    </p>
                    <ExtraFieldsForm
                      docId={doc.id}
                      extraFields={getExtra(doc.id)}
                      onChange={d => setExtra(doc.id, d)}
                      points={points}
                    />
                    <button onClick={() => generateDoc(doc.id)}
                      className="btn btn-primary w-full mt-4">
                      Generate &amp; Print — {doc.title}
                    </button>
                  </div>
                )}
              </div>
            )
          })}
        </div>

        {/* Generate all button */}
        {docs.filter((d: any) => !generated.has(d.id)).length > 0 && (
          <div className="mt-6 pt-6 border-t border-[var(--border-color)]">
            <button onClick={() => docs.forEach((d, i) => setTimeout(() => generateDoc(d.id), i * 300))}
              className="btn btn-secondary w-full">
              Generate all {docs.length} documents at once
            </button>
            <p className="text-xs text-center text-[var(--text-muted)] mt-2">Opens each document in a separate tab for printing</p>
          </div>
        )}

        </>
        )}

      </div>
    </div>
  )
}

'use client'

import { useRouter } from 'next/navigation'
import dynamic from 'next/dynamic'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import type { SurveyorProfileSubmission } from '@/lib/api-client/community'
import { EngineeringPanelSkeleton, type EngineeringProject } from './shared'

/* ── Lazy-loaded engineering panels for the Quick Compute tab ─── */
const HorizontalCurvePanel = dynamic(() => import('@/components/engineering/HorizontalCurvePanel').then(m => ({ default: m.HorizontalCurvePanel })), {
  ssr: false, loading: () => <EngineeringPanelSkeleton />
})
const SuperelevationPanel = dynamic(() => import('@/components/engineering/SuperelevationPanel'), {
  ssr: false, loading: () => <EngineeringPanelSkeleton />
})
const VolumesPanel = dynamic(() => import('@/components/engineering/VolumesPanel').then(m => ({ default: m.VolumesPanel })), {
  ssr: false, loading: () => <EngineeringPanelSkeleton />
})
const NetworkAdjustmentPanel = dynamic(() => import('@/components/compute/NetworkAdjustmentPanel').then(m => ({ default: m.NetworkAdjustmentPanel })), {
  ssr: false, loading: () => <EngineeringPanelSkeleton />
})
const RoadReservePanel = dynamic(() => import('@/components/engineering/RoadReservePanel'), {
  ssr: false, loading: () => <EngineeringPanelSkeleton />
})

const QUICK_COMPUTE_TABS = [
  { id: 'curves', label: 'Horizontal Curves' },
  { id: 'chainage', label: 'Chainage' },
  { id: 'tacheometry', label: 'Tacheometry' },
  { id: 'cross_sections', label: 'Cross Sections' },
  { id: 'setting_out', label: 'Setting Out' },
  { id: 'superelevation', label: 'Superelevation' },
  { id: 'volumes', label: 'Volumes' },
  { id: 'network', label: 'Network Adjustment' },
  { id: 'road_reserve', label: 'Road Reserve' },
  { id: 'workflow', label: '← Back to Workflow' },
] as const

/**
 * Quick Compute tab — secondary tab bar of the engineering page that hosts
 * the standalone compute panels (horizontal curves, superelevation, volumes,
 * network adjustment, road reserve).
 *
 * Extracted verbatim from src/app/project/[id]/engineering/page.tsx —
 * the JSX, the dynamic() panel imports, and the tab array are unchanged.
 */
export function QuickComputeTab({
  projectId,
  project,
  surveyorProfile,
  activeTab,
}: {
  projectId: string
  project: EngineeringProject
  surveyorProfile: SurveyorProfileSubmission | null
  activeTab: string
}) {
  const router = useRouter()

  const projectData = {
    lr_number: project.lr_number,
    county: project.county,
    district: project.district,
    locality: project.locality,
  }

  return (
    <div className="min-h-screen bg-black text-white p-6">
      <div className="max-w-6xl mx-auto">
        <div className="mb-4">
          <MobileDesktopNotice>
            Engineering compute panels use dense tables, diagrams, and exports. Mobile is useful for quick field checks; desktop is recommended for final design review.
          </MobileDesktopNotice>
        </div>
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-4">
            <button onClick={() => router.push(`/project/${projectId}`)} className="text-zinc-500 hover:text-zinc-300">← Back</button>
            <h1 className="text-xl font-bold">Engineering Compute</h1>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => router.push(`/project/${projectId}/engineering?tab=workflow`)}
              className={`px-4 py-2 rounded-lg text-sm font-medium ${activeTab === 'workflow' ? 'bg-orange-500 text-white' : 'bg-zinc-800 text-zinc-300'}`}
            >
              Workflow
            </button>
          </div>
        </div>

        <div className="flex gap-2 mb-6 border-b border-zinc-800 pb-2">
          {QUICK_COMPUTE_TABS.map(tab => (
            <button
              key={tab.id}
              onClick={() => router.push(`/project/${projectId}/engineering?tab=${tab.id}`)}
              className={`px-4 py-2 rounded-t-lg text-sm font-medium ${
                activeTab === tab.id
                  ? 'bg-zinc-800 text-white border-t border-l border-r border-zinc-700'
                  : 'text-zinc-500 hover:text-zinc-300'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div className="bg-zinc-900 rounded-xl p-6">
          {activeTab === 'curves' && <HorizontalCurvePanel projectId={projectId} projectData={projectData} surveyorProfile={surveyorProfile} />}
          {activeTab === 'superelevation' && <SuperelevationPanel projectId={projectId} projectData={projectData} surveyorProfile={surveyorProfile} />}
          {activeTab === 'volumes' && <VolumesPanel projectId={projectId} projectData={projectData} surveyorProfile={surveyorProfile} />}
          {activeTab === 'network' && <NetworkAdjustmentPanel projectId={projectId} projectData={project as unknown as Record<string, any>} />}
          {activeTab === 'road_reserve' && <RoadReservePanel
            roadClass={project.engineering_data?.road?.roadClass || 'C'}
            roadLength={undefined}
            existingRoadWidth={project.engineering_data?.road?.crossSectionTemplate?.carriagewayWidth ? project.engineering_data.road.crossSectionTemplate.carriagewayWidth + (project.engineering_data.road.crossSectionTemplate.shoulderWidth ?? 1) * 2 : undefined}
          />}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useEffect, useState, useCallback } from 'react'
import { useParams, useRouter, useSearchParams } from 'next/navigation'
import { createClient } from '@/lib/api-client/client'
import { z } from 'zod'
import { apiGet, apiPost, ApiError } from '@/lib/api/client'
import type {
  EngineeringData,
  EngineeringMode,
  EngineeringStandard,
  RoadDesignData,
  DrainageData,
  StationData,
  IntersectionPoint,
  VerticalIP,
  CrossSectionTemplate,
} from '@/types/engineering'
import type { SurveyorProfileSubmission } from '@/lib/api-client/community'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import type { EngineeringProject, EngineeringStepId } from './shared'
import { getEngineeringSteps } from './getEngineeringSteps'
import { renderStepContent } from './steps/renderStepContent'
import { QuickComputeTab } from './QuickComputeTab'

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

// GET /api/engineering/alignment returns { data: <alignment row or null> }.
// Use z.union([schema, z.null()]) instead of .nullable() so we keep .passthrough() on the inner object.
const alignmentRowSchema = z.object({
  id: z.union([z.string(), z.number()]),
  road_name: z.string().nullable().optional(),
  start_chainage: z.union([z.number(), z.string(), z.null()]).optional(),
  datum: z.string().nullable().optional(),
  coordinate_system: z.string().nullable().optional(),
  design_speed: z.union([z.number(), z.string(), z.null()]).optional(),
  road_class: z.string().nullable().optional(),
  standard: z.string().nullable().optional(),
  cross_section_template: z.any().optional(),
  ips: z.array(z.any()).optional(),
  vips: z.array(z.any()).optional(),
  stations: z.array(z.any()).optional(),
}).passthrough()

const alignmentResponseSchema = z.object({
  data: z.union([alignmentRowSchema, z.null()]),
}).passthrough()

// POST /api/engineering/alignment returns { data: { id, ... } }
const alignmentMutationSchema = z.object({
  data: alignmentRowSchema,
}).passthrough()

// The three sub-resource POSTs return various shapes — accept any object payload.
const subResourceMutationSchema = z.record(z.any())

export default function EngineeringWorkspacePage() {
  const params = useParams<{ id: string }>()
  const router = useRouter()
  const searchParams = useSearchParams()
  const dbClient = createClient()

  const [project, setProject] = useState<EngineeringProject | null>(null)
  const [surveyorProfile, setSurveyorProfile] = useState<SurveyorProfileSubmission | null>(null)
  const [loading, setLoading] = useState(true)
  const [loadingEngineering, setLoadingEngineering] = useState(false)
  const [activeStep, setActiveStep] = useState<EngineeringStepId>('setup')
  const [saving, setSaving] = useState(false)
  const [quickMode, setQuickMode] = useState(false)
  const [alignmentId, setAlignmentId] = useState<string | null>(null)

  // Sub-tab for quick compute panels
  const activeTab = searchParams.get('tab') || 'workflow'

  // --- Load engineering data from the relational DB backend ---
  const loadEngineeringData = useCallback(async (projectId: string) => {
    setLoadingEngineering(true)
    try {
      const result = await apiGet(
        `/api/engineering/alignment?project_id=${projectId}`,
        alignmentResponseSchema,
        { ttlMs: 0 },
      )
      const dbData = result.data

      if (!dbData) {
        // No alignment row yet — nothing to hydrate
        setLoadingEngineering(false)
        return
      }

      // Store the alignment ID for subsequent saves (IPs, VIPs, stations)
      setAlignmentId(String(dbData.id))

      // Map DB column names → TypeScript shape
      const crossSectionTemplate: CrossSectionTemplate | undefined = dbData.cross_section_template
        ? {
            carriagewayWidth: Number(dbData.cross_section_template.carriageway_width ?? dbData.cross_section_template.carriagewayWidth ?? 6.0),
            shoulderWidth: Number(dbData.cross_section_template.shoulder_width ?? dbData.cross_section_template.shoulderWidth ?? 1.0),
            cutSlope: String(dbData.cross_section_template.cut_slope ?? dbData.cross_section_template.cutSlope ?? '1:1'),
            fillSlope: String(dbData.cross_section_template.fill_slope ?? dbData.cross_section_template.fillSlope ?? '1:1.5'),
            camber: Number(dbData.cross_section_template.camber ?? 3),
            subgradeDepth: Number(dbData.cross_section_template.subgrade_depth ?? dbData.cross_section_template.subgradeDepth ?? 0.5),
          }
        : undefined

      const ips: IntersectionPoint[] = (dbData.ips || []).map((row: any) => ({
        id: String(row.id),
        name: String(row.name),
        easting: Number(row.easting),
        northing: Number(row.northing),
        radius: Number(row.radius),
        deflectionAngle: row.deflection_angle != null ? Number(row.deflection_angle) : undefined,
        tangentLength: row.tangent_length != null ? Number(row.tangent_length) : undefined,
        arcLength: row.arc_length != null ? Number(row.arc_length) : undefined,
        chainageTC: row.chainage_tc != null ? Number(row.chainage_tc) : undefined,
        chainageMC: row.chainage_mc != null ? Number(row.chainage_mc) : undefined,
        chainageCT: row.chainage_ct != null ? Number(row.chainage_ct) : undefined,
        sortOrder: row.sort_order != null ? Number(row.sort_order) : undefined,
      }))

      const vips: VerticalIP[] = (dbData.vips || []).map((row: any) => ({
        id: String(row.id),
        chainage: Number(row.chainage),
        reducedLevel: Number(row.reduced_level),
        kValue: row.k_value != null ? Number(row.k_value) : undefined,
      }))

      const stations: StationData[] = (dbData.stations || []).map((row: any) => ({
        chainage: Number(row.chainage),
        groundLevel: Number(row.ground_level),
      }))

      // Build a RoadDesignData object from the DB row
      const roadFromDb: RoadDesignData = {
        roadName: String(dbData.road_name || ''),
        startChainage: Number(dbData.start_chainage ?? 0),
        datum: String(dbData.datum || 'Arc 1960'),
        coordinateSystem: String(dbData.coordinate_system || 'UTM Zone 37S'),
        designSpeed: Number(dbData.design_speed ?? 60),
        roadClass: String(dbData.road_class || 'C') as any,
        standard: (dbData.standard || 'KRDM2017') as EngineeringStandard,
        ips,
        vips,
        crossSectionTemplate: crossSectionTemplate || {
          carriagewayWidth: 6.0,
          shoulderWidth: 1.0,
          cutSlope: '1:1',
          fillSlope: '1:1.5',
          camber: 3,
          subgradeDepth: 0.5,
        },
        stations,
      }

      // Merge into the existing engineering_data, preserving mode/drainage
      setProject(prev => {
        if (!prev) return prev
        const current: EngineeringData = prev.engineering_data || { mode: 'road', standard: 'KRDM2017' }
        return {
          ...prev,
          engineering_data: {
            ...current,
            road: roadFromDb,
          },
        }
      })
    } catch (err) {
      if (err instanceof ApiError && err.isNotFound) {
        // No alignment row yet — nothing to hydrate
        setLoadingEngineering(false)
        return
      }
      console.error('[loadEngineeringData] Error:', err)
    } finally {
      setLoadingEngineering(false)
    }
  }, [])

  const fetchProject = useCallback(async () => {
    setLoading(true)
    const { data, error } = await dbClient
      .from('projects')
      .select('*')
      .eq('id', params.id)
      .single()

    if (error || !data) {
      setLoading(false)
      return
    }

    const engData = (data as any).engineering_data as EngineeringData | null
    setProject({ ...data, engineering_data: engData } as EngineeringProject)

    const { data: profile } = await dbClient
      .from('surveyor_profiles')
      .select('isk_number, verified_isk, full_name, name, firm_name, company')
      .eq('user_id', (data as any).user_id)
      .single()

    if (profile) {
      setSurveyorProfile({
        registrationNumber: profile.isk_number ?? '',
        iskNumber: profile.isk_number ?? '',
        verifiedIsk: profile.verified_isk ?? false,
        fullName: profile.full_name ?? profile.name ?? '',
        firmName: profile.firm_name ?? profile.company ?? '',
        isKMemberActive: profile.verified_isk ?? true
      })
    }

    setLoading(false)
  }, [params.id, dbClient])

  useEffect(() => {
    fetchProject()
  }, [fetchProject])

  // Load engineering data from the relational backend after project is fetched
  const projectId = project?.id
  useEffect(() => {
    if (projectId && !loading) {
      loadEngineeringData(projectId)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId, loading, loadEngineeringData])

  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' } | null>(null)

  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type })
    setTimeout(() => setToast(null), 3000)
  }

  const handleModeChange = async (newMode: EngineeringMode) => {
    if (!project) return
    setSaving(true)

    try {
      const current = project.engineering_data || { mode: 'road' as EngineeringMode, standard: 'KRDM2017' as EngineeringStandard }
      const updated: EngineeringData = {
        ...current,
        mode: newMode,
        standard: current.standard || 'KRDM2017'
      }

      await dbClient
        .from('projects')
        .update({ engineering_data: updated })
        .eq('id', project.id)

      setProject({ ...project, engineering_data: updated })
      setActiveStep('setup')
      showToast('Mode switched successfully')
    } catch (err) {
      showToast('Failed to save. Check your connection and try again.', 'error')
      console.error('Save failed:', err)
    } finally {
      setSaving(false)
    }
  }

  // --- Save the entire current engineering state to the relational backend ---
  const saveToBackend = useCallback(async (engData: EngineeringData): Promise<boolean> => {
    if (!project) return false
    const road = engData.road
    if (!road) return false

    try {
      // Step 1: Upsert alignment header → get alignment_id
      const templateForDb = road.crossSectionTemplate
        ? {
            carriagewayWidth: road.crossSectionTemplate.carriagewayWidth,
            shoulderWidth: road.crossSectionTemplate.shoulderWidth,
            cutSlope: road.crossSectionTemplate.cutSlope,
            fillSlope: road.crossSectionTemplate.fillSlope,
            camber: road.crossSectionTemplate.camber,
            subgradeDepth: road.crossSectionTemplate.subgradeDepth,
          }
        : {}

      const alignResult = await apiPost(
        '/api/engineering/alignment',
        alignmentMutationSchema,
        {
          project_id: project.id,
          road_name: road.roadName || 'Unnamed Road',
          start_chainage: road.startChainage ?? 0,
          datum: road.datum || 'Arc 1960',
          coordinate_system: road.coordinateSystem || 'UTM Zone 37S',
          design_speed: road.designSpeed ?? 60,
          road_class: road.roadClass || 'C',
          standard: road.standard || 'KRDM2017',
          cross_section_template: templateForDb,
        },
      )
      const aId = alignResult.data?.id
      if (!aId) throw new Error('No alignment ID returned')
      setAlignmentId(String(aId))

      // Step 2: Save IPs (if any)
      if (road.ips && road.ips.length > 0) {
        await apiPost(
          '/api/engineering/ips',
          subResourceMutationSchema,
          {
            alignment_id: aId,
            ips: road.ips.map(ip => ({
              name: ip.name,
              easting: ip.easting,
              northing: ip.northing,
              radius: ip.radius,
            })),
          },
        )
      }

      // Step 3: Save VIPs (if any)
      if (road.vips && road.vips.length > 0) {
        await apiPost(
          '/api/engineering/vips',
          subResourceMutationSchema,
          {
            alignment_id: aId,
            vips: road.vips.map(v => ({
              chainage: v.chainage,
              reduced_level: v.reducedLevel,
              k_value: v.kValue ?? null,
            })),
          },
        )
      }

      // Step 4: Save stations (if any)
      if (road.stations && road.stations.length > 0) {
        await apiPost(
          '/api/engineering/stations',
          subResourceMutationSchema,
          {
            alignment_id: aId,
            stations: road.stations.map(s => ({
              chainage: s.chainage,
              ground_level: s.groundLevel,
            })),
          },
        )
      }

      return true
    } catch (err) {
      console.error('[saveToBackend] Error:', err)
      return false
    }
  }, [project])

  const handleSave = async (data: Partial<EngineeringData>) => {
    if (!project) return
    setSaving(true)

    try {
      const current = project.engineering_data || { mode: 'road' as EngineeringMode, standard: 'KRDM2017' as EngineeringStandard }

      let updated: EngineeringData
      if (data.mode) {
        updated = {
          ...current,
          mode: data.mode,
          standard: data.standard || current.standard || 'KRDM2017'
        }
      } else {
        updated = {
          ...current,
          mode: current.mode || 'road',
          standard: current.standard || 'KRDM2017',
          road: { ...current.road, ...data.road } as RoadDesignData,
          drainage: { ...current.drainage, ...data.drainage } as DrainageData
        }
      }

      // Save to database (engineering_data JSONB column)
      await dbClient
        .from('projects')
        .update({ engineering_data: updated })
        .eq('id', project.id)

      setProject({ ...project, engineering_data: updated })

      // Also persist to relational backend for road mode
      if (updated.road) {
        const backendOk = await saveToBackend(updated)
        if (backendOk) {
          showToast('Saved successfully')
        } else {
          showToast('Saved locally, but backend sync failed.', 'error')
        }
      } else {
        showToast('Saved successfully')
      }
    } catch (err) {
      showToast('Failed to save. Check your connection and try again.', 'error')
      console.error('Save failed:', err)
    } finally {
      setSaving(false)
    }
  }

  // Save All handler — persists the full current state to the backend
  const handleSaveAll = async () => {
    if (!project || !project.engineering_data) return
    setSaving(true)
    try {
      // First ensure local state is up to date
      await dbClient
        .from('projects')
        .update({ engineering_data: project.engineering_data })
        .eq('id', project.id)

      if (project.engineering_data.road) {
        const backendOk = await saveToBackend(project.engineering_data)
        if (backendOk) {
          showToast('All engineering data saved to backend')
        } else {
          showToast('Backend sync failed. Local data is preserved.', 'error')
        }
      } else {
        showToast('All data saved')
      }
    } catch (err) {
      showToast('Failed to save. Check your connection and try again.', 'error')
      console.error('Save All failed:', err)
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-zinc-500 animate-pulse">Loading...</div>
      </div>
    )
  }

  if (!project) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center">
        <div className="text-red-400">Project not found</div>
        <button onClick={() => router.push('/dashboard')} className="text-amber-500 mt-4">Back to Dashboard</button>
      </div>
    )
  }

  const steps = getEngineeringSteps(project.engineering_data || null)
  const currentStep = steps.find((s) => s.id === activeStep) || steps[0]
  const mode = project.engineering_data?.mode || 'road'

  // Quick Compute Panel Mode
  if (activeTab !== 'workflow') {
    return (
      <QuickComputeTab
        projectId={params.id}
        project={project}
        surveyorProfile={surveyorProfile}
        activeTab={activeTab}
      />
    )
  }

  return (
    <div className="min-h-screen bg-black text-white">
      <div className="border-b border-zinc-800 bg-zinc-950">
        <div className="max-w-7xl mx-auto px-4 py-3 flex items-center gap-4">
          <button onClick={() => router.push('/dashboard')} className="text-zinc-500 hover:text-zinc-300 text-sm">← Projects</button>
          <div className="flex-1">
            <h1 className="text-sm font-semibold text-white">{project.name}</h1>
            <div className="text-xs text-zinc-500">Engineering Mode • {mode === 'road' ? 'Road Design' : 'Drainage Survey'}</div>
          </div>
          <span className="text-xs px-2 py-1 bg-amber-500/20 text-amber-400 rounded">{mode === 'road' ? 'Road Design' : 'Drainage Survey'}</span>
          <button
            onClick={handleSaveAll}
            disabled={saving || loadingEngineering}
            className="text-xs px-3 py-1 bg-emerald-500/20 text-emerald-400 rounded hover:bg-emerald-500/30 disabled:opacity-40 disabled:cursor-not-allowed font-medium"
          >
            {saving ? 'Saving...' : 'Save All ↓'}
          </button>
          <button
            onClick={() => router.push(`/project/${params.id}/engineering?tab=curves`)}
            className="text-xs px-3 py-1 bg-orange-500/20 text-orange-400 rounded hover:bg-orange-500/30"
          >
            Quick Compute →
          </button>
        </div>
      </div>

      {/* Toast notification */}
      {toast && (
        <div className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-lg shadow-lg text-sm font-medium transition-all ${
          toast.type === 'success' ? 'bg-green-900/90 text-green-300 border border-green-700' : 'bg-red-900/90 text-red-300 border border-red-700'
        }`}>
          {toast.type === 'success' ? ' ' : '[x] '}{toast.message}
        </div>
      )}

      {/* Saving indicator */}
      {(saving || loadingEngineering) && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-50 bg-zinc-800 border border-zinc-600 text-zinc-300 px-4 py-2 rounded-lg text-sm flex items-center gap-2 shadow-lg">
          <svg className="animate-spin h-4 w-4" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/></svg>
          {loadingEngineering ? 'Loading engineering data...' : 'Saving...'}
        </div>
      )}

      <div className="max-w-7xl mx-auto flex flex-col lg:flex-row">
        <nav className="w-full lg:w-64 shrink-0 border-b lg:border-b-0 lg:border-r border-zinc-800">
          <div className="p-4">
            <div className="text-xs font-semibold text-zinc-500 uppercase tracking-widest mb-3">Workflow</div>
            <ol className="space-y-1">
              {steps.map((step, idx) => {
                const isActive = step.id === activeStep
                const isLocked = step.status === 'locked'
                return (
                  <li key={step.id}>
                    <button
                      disabled={isLocked}
                      onClick={() => setActiveStep(step.id)}
                      className={`w-full text-left rounded-lg px-3 py-2.5 flex items-start gap-3 ${
                        isActive ? 'bg-zinc-800 border border-zinc-700' :
                        isLocked ? 'opacity-40 cursor-not-allowed' :
                        'hover:bg-zinc-900 border border-transparent'
                      }`}
                    >
                      <span className={`shrink-0 w-6 h-6 rounded-full text-xs flex items-center justify-center mt-0.5 ${
                        step.status === 'complete' ? 'bg-amber-500 text-black' :
                        step.status === 'in_progress' ? 'bg-blue-500 text-white' :
                        step.status === 'locked' ? 'bg-zinc-800 text-zinc-600' :
                        'bg-zinc-700 text-zinc-300'
                      }`}>
                        {step.status === 'complete' ? '' : isLocked ? '[Lock]' : idx + 1}
                      </span>
                      <div className="min-w-0">
                        <div className={`text-sm font-medium ${isLocked ? 'text-zinc-600' : isActive ? 'text-white' : 'text-zinc-300'}`}>
                          {step.label}
                        </div>
                        <div className="text-xs text-zinc-600 truncate">{step.description}</div>
                      </div>
                    </button>
                  </li>
                )
              })}
            </ol>
          </div>
        </nav>

        <main className="flex-1 min-w-0 p-4 lg:p-8">
          <div className="mb-4">
            <MobileDesktopNotice>
              Engineering workflows are desktop-first because they include alignments, long sections, cross sections, and export review. Use mobile for quick reference only.
            </MobileDesktopNotice>
          </div>
          <div className="mb-6">
            <h2 className="text-lg font-semibold text-white">{currentStep?.label}</h2>
          </div>
          <div className="rounded-xl border border-zinc-800 bg-zinc-950 p-6">
            {renderStepContent(currentStep?.id || 'setup', project, project.engineering_data || null, handleSave, handleModeChange)}
          </div>
        </main>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import type { DrainageData, Manhole } from '@/types/engineering'

/**
 * Drainage Step 1 — Manholes.
 *
 * Extracted verbatim from src/app/project/[id]/engineering/page.tsx.
 */
export function DrainageStep1Manholes({
  data,
  onSave
}: {
  data: DrainageData | null
  onSave: (manholes: Manhole[]) => void
}) {
  const [manholes, setManholes] = useState<Manhole[]>(data?.manholes || [])

  const addManhole = () => {
    const newMh: Manhole = {
      id: `MH${manholes.length + 1}`,
      name: `MH${manholes.length + 1}`,
      chainage: manholes.length > 0 ? manholes[manholes.length - 1].chainage + 30 : 0,
      coverLevel: 0,
      invertLevelIn: 0,
      invertLevelOut: 0,
      pipeDiameterOut: 450,
      pipeMaterial: 'Concrete'
    }
    setManholes([...manholes, newMh])
  }

  const updateManhole = (index: number, field: keyof Manhole, value: any) => {
    const updated = [...manholes]
    updated[index] = { ...updated[index], [field]: value }
    setManholes(updated)
  }

  const removeManhole = (index: number) => {
    setManholes(manholes.filter((_, i) => i !== index))
  }

  const handleSave = () => {
    onSave(manholes)
  }

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-white mb-1">Manholes</h3>
        <p className="text-zinc-400 text-sm">Define manhole locations, cover and invert levels.</p>
      </div>

      {manholes.length === 0 ? (
        <div className="text-center py-8 text-zinc-500">
          <p>No manholes defined. Add at least 2 manholes for a drainage line.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {manholes.map((mh, idx) => (
            <div key={mh.id} className="border border-zinc-700 rounded-lg p-4">
              <div className="flex items-center justify-between mb-3">
                <span className="font-medium text-white">Manhole {idx + 1}</span>
                <button
                  onClick={() => removeManhole(idx)}
                  className="text-red-400 text-sm hover:text-red-300"
                >
                  Remove
                </button>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <div>
                  <label htmlFor={`mh-${idx}-name`} className="block text-xs text-zinc-500 mb-1">Name</label>
                  <input id={`mh-${idx}-name`}
                    type="text"
                    value={mh.name}
                    onChange={e => updateManhole(idx, 'name', e.target.value)}
                    className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-sm"
                  />
                </div>
                <div>
                  <label htmlFor={`mh-${idx}-chainage`} className="block text-xs text-zinc-500 mb-1">Chainage (m)</label>
                  <input id={`mh-${idx}-chainage`}
                    type="number"
                    value={mh.chainage}
                    onChange={e => updateManhole(idx, 'chainage', Number(e.target.value))}
                    className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-sm"
                  />
                </div>
                <div>
                  <label htmlFor={`mh-${idx}-cover`} className="block text-xs text-zinc-500 mb-1">Cover Level (m)</label>
                  <input id={`mh-${idx}-cover`}
                    type="number"
                    step="0.001"
                    value={mh.coverLevel}
                    onChange={e => updateManhole(idx, 'coverLevel', Number(e.target.value))}
                    className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-sm"
                  />
                </div>
                <div>
                  <label htmlFor={`mh-${idx}-invert`} className="block text-xs text-zinc-500 mb-1">Invert Out (m)</label>
                  <input id={`mh-${idx}-invert`}
                    type="number"
                    step="0.001"
                    value={mh.invertLevelOut}
                    onChange={e => updateManhole(idx, 'invertLevelOut', Number(e.target.value))}
                    className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-sm"
                  />
                </div>
                <div>
                  <label htmlFor={`mh-${idx}-pipeDia`} className="block text-xs text-zinc-500 mb-1">Pipe Dia (mm)</label>
                  <input id={`mh-${idx}-pipeDia`}
                    type="number"
                    value={mh.pipeDiameterOut}
                    onChange={e => updateManhole(idx, 'pipeDiameterOut', Number(e.target.value))}
                    className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-sm"
                  />
                </div>
                <div>
                  <label htmlFor={`mh-${idx}-material`} className="block text-xs text-zinc-500 mb-1">Material</label>
                  <select
                    id={`mh-${idx}-material`}
                    value={mh.pipeMaterial}
                    onChange={e => updateManhole(idx, 'pipeMaterial', e.target.value)}
                    className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-sm"
                  >
                    <option value="Concrete">Concrete</option>
                    <option value="HDPE">HDPE</option>
                    <option value="uPVC">uPVC</option>
                    <option value="VCP">VCP</option>
                  </select>
                </div>
                <div>
                  <label htmlFor={`mh-${idx}-depth`} className="block text-xs text-zinc-500 mb-1">Depth (m)</label>
                  <input id={`mh-${idx}-depth`}
                    type="number"
                    step="0.01"
                    value={mh.coverLevel - mh.invertLevelOut}
                    disabled
                    className="w-full bg-zinc-900 border border-zinc-800 rounded px-2 py-1.5 text-zinc-500 text-sm"
                  />
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <button
        onClick={addManhole}
        className="px-4 py-2 border border-zinc-700 text-zinc-300 rounded-lg hover:bg-zinc-800"
      >
        + Add Manhole
      </button>

      {manholes.length >= 2 && (
        <button
          onClick={handleSave}
          className="px-6 py-2.5 bg-amber-500 text-black font-semibold rounded-lg hover:bg-amber-400"
        >
          Save Manholes
        </button>
      )}
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import type { EngineeringMode, EngineeringStandard, RoadDesignData } from '@/types/engineering'
import { KRDM2017, KeRRA, getCarriagewayWidth } from '@/lib/standards/engineering'
import type { EngineeringProject } from '../shared'
import { ROAD_CLASSES } from '../shared'

/**
 * Step 1 — Project Setup.
 *
 * Extracted verbatim from src/app/project/[id]/engineering/page.tsx.
 * Same props, same behavior.
 */
export function Step1Setup({
  project,
  data,
  onSave,
  mode,
  onModeChange
}: {
  project: EngineeringProject
  data: RoadDesignData | null
  onSave: (data: Partial<RoadDesignData>) => void
  mode: EngineeringMode
  onModeChange: (mode: EngineeringMode) => void
}) {
  const [roadName, setRoadName] = useState(data?.roadName || '')
  const [startChainage, setStartChainage] = useState(data?.startChainage || 0)
  const [designSpeed, setDesignSpeed] = useState(data?.designSpeed || 60)
  const [roadClass, setRoadClass] = useState<string>(data?.roadClass || 'C')
  const [standard, setStandard] = useState<EngineeringStandard>(data?.standard || 'KRDM2017')
  const [datum, setDatum] = useState(data?.datum || 'Arc 1960')
  const [coordSys, setCoordSys] = useState(data?.coordinateSystem || 'UTM Zone 37S')

  const standardObj = standard === 'KRDM2017' ? KRDM2017 : KeRRA
  const speedRange = standardObj.designSpeeds[roadClass as keyof typeof standardObj.designSpeeds]

  useEffect(() => {
    if (speedRange && (designSpeed < speedRange[0] || designSpeed > speedRange[1])) {
      setDesignSpeed(speedRange[0])
    }
  }, [roadClass, standard, speedRange, designSpeed])

  const [error, setError] = useState<string | null>(null)

  const handleSave = () => {
    if (!roadName.trim()) {
      setError('Road name is required')
      return
    }
    if (designSpeed <= 0) {
      setError('Design speed must be greater than 0')
      return
    }
    setError(null)
    onSave({
      roadName: roadName.trim(),
      startChainage,
      designSpeed,
      roadClass: roadClass as any,
      standard,
      datum,
      coordinateSystem: coordSys
    })
  }

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-white mb-1">Project Setup</h3>
        <p className="text-zinc-400 text-sm">Define road parameters per {standard} standard.</p>
      </div>

      {error && (
        <div className="bg-red-900/30 border border-red-700 rounded-lg px-4 py-3 text-red-400 text-sm">{error}</div>
      )}

      <div className="border border-zinc-700 rounded-lg p-4">
        <div className="block text-sm text-zinc-400 mb-2">Engineering Mode</div>
        <div className="flex gap-3">
          <button
            type="button"
            onClick={() => onModeChange('road')}
            className={`flex-1 py-3 px-4 rounded-lg border text-sm font-medium transition ${
              mode === 'road'
                ? 'bg-amber-500/20 border-amber-500 text-amber-400'
                : 'border-zinc-700 text-zinc-400 hover:bg-zinc-800'
            }`}
          >
            [WIP] Road Design
          </button>
          <button
            type="button"
            onClick={() => onModeChange('drainage')}
            className={`flex-1 py-3 px-4 rounded-lg border text-sm font-medium transition ${
              mode === 'drainage'
                ? 'bg-amber-500/20 border-amber-500 text-amber-400'
                : 'border-zinc-700 text-zinc-400 hover:bg-zinc-800'
            }`}
          >
            [Rain] Drainage Survey
          </button>
        </div>
      </div>

      {mode === 'road' && (
        <>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label htmlFor="roadName" className="block text-sm text-zinc-400 mb-1">Road Name</label>
          <input
            id="roadName"
            type="text"
            value={roadName}
            onChange={e => setRoadName(e.target.value)}
            className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-white"
            placeholder="e.g. Nairobi-Mombasa Highway"
          />
        </div>

        <div>
          <label htmlFor="startChainage" className="block text-sm text-zinc-400 mb-1">Start Chainage (m)</label>
          <input id="startChainage"
            type="number"
            value={startChainage}
            onChange={e => setStartChainage(Number(e.target.value))}
            className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-white"
          />
        </div>

        <div>
          <label htmlFor="roadClass" className="block text-sm text-zinc-400 mb-1">Road Class (per {standard})</label>
          <select
            id="roadClass"
            value={roadClass}
            onChange={e => setRoadClass(e.target.value)}
            className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-white"
          >
            {ROAD_CLASSES.map((c) => (
              <option key={c} value={c}>Class {c} {standard === 'KRDM2017' ? '- ' + (c === 'A' ? 'Major Arterial' : c === 'D' ? 'Minor Collector' : '') : ''}</option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="designSpeed" className="block text-sm text-zinc-400 mb-1">Design Speed (km/h)</label>
          <input id="designSpeed"
            type="number"
            value={designSpeed}
            onChange={e => setDesignSpeed(Number(e.target.value))}
            className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-white"
            min={speedRange?.[0] || 30}
            max={speedRange?.[1] || 120}
          />
          <p className="text-xs text-zinc-500 mt-1">Valid range: {speedRange?.[0] || 30} - {speedRange?.[1] || 120} km/h</p>
        </div>

        <div>
          <label htmlFor="standard" className="block text-sm text-zinc-400 mb-1">Standard</label>
          <select
            id="standard"
            value={standard}
            onChange={e => setStandard(e.target.value as EngineeringStandard)}
            className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-white"
          >
            <option value="KRDM2017">KRDM 2017</option>
            <option value="KeRRA">KeRRA (Rural Roads)</option>
          </select>
        </div>

        <div>
          <label htmlFor="carriagewayWidth" className="block text-sm text-zinc-400 mb-1">Carriageway Width (m)</label>
          <input id="carriagewayWidth"
            type="number"
            step="0.1"
            value={getCarriagewayWidth(standard, roadClass as any)}
            disabled
            className="w-full bg-zinc-900 border border-zinc-800 rounded-lg px-3 py-2 text-zinc-500"
          />
        </div>

        <div>
          <label htmlFor="datum" className="block text-sm text-zinc-400 mb-1">Datum</label>
          <select
            id="datum"
            value={datum}
            onChange={e => setDatum(e.target.value)}
            className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-white"
          >
            <option value="Arc 1960">Arc 1960</option>
            <option value="WGS84">WGS84</option>
          </select>
        </div>

        <div>
          <label htmlFor="coordSys" className="block text-sm text-zinc-400 mb-1">Coordinate System</label>
          <select
            id="coordSys"
            value={coordSys}
            onChange={e => setCoordSys(e.target.value)}
            className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-white"
          >
            <option value="UTM Zone 37S">UTM Zone 37S</option>
            <option value="UTM Zone 36S">UTM Zone 36S</option>
            <option value="UTM Zone 38S">UTM Zone 38S</option>
          </select>
        </div>
      </div>
      </>
      )}

      <button
        onClick={handleSave}
        className="px-6 py-2.5 bg-amber-500 text-black font-semibold rounded-lg hover:bg-amber-400"
      >
        Save Setup
      </button>
    </div>
  )
}

'use client'

import { useState } from 'react'
import type { IntersectionPoint, RoadDesignData } from '@/types/engineering'

/**
 * Step 2 — Horizontal Alignment (IPs and circular curve radii).
 *
 * Extracted verbatim from src/app/project/[id]/engineering/page.tsx.
 */
export function Step2Horizontal({
  data,
  onSave
}: {
  data: RoadDesignData | null
  onSave: (ips: IntersectionPoint[]) => void
}) {
  const [ips, setIps] = useState<IntersectionPoint[]>(data?.ips || [])

  const addIP = () => {
    const newIp: IntersectionPoint = {
      id: `IP${ips.length + 1}`,
      name: `IP${ips.length + 1}`,
      easting: 0,
      northing: 0,
      radius: 100
    }
    setIps([...ips, newIp])
  }

  const updateIP = (index: number, field: keyof IntersectionPoint, value: any) => {
    const updated = [...ips]
    updated[index] = { ...updated[index], [field]: value }
    setIps(updated)
  }

  const removeIP = (index: number) => {
    setIps(ips.filter((_, i) => i !== index))
  }

  const handleSave = () => {
    onSave(ips)
  }

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-white mb-1">Horizontal Alignment</h3>
        <p className="text-zinc-400 text-sm">Define intersection points (IPs) and circular curve radii.</p>
      </div>

      {ips.length === 0 ? (
        <div className="text-center py-8 text-zinc-500">
          <p>No IPs defined. Add at least 2 IPs for a valid alignment.</p>
        </div>
      ) : (
        <div className="space-y-4">
          {ips.map((ip, idx) => (
            <div key={ip.id} className="border border-zinc-700 rounded-lg p-4">
