'use client';

import dynamic from 'next/dynamic';
import { useEffect, useState, useCallback } from 'react';
import { createClient } from '@/lib/api-client/client';
import type { AdjustedStation } from '@/lib/engine/planGeometry';

const SurveyMap = dynamic(() => import('@/components/map/SurveyMap'), { ssr: false });

interface MapPageProps {
  params: { id: string };
}

export default function MapPage({ params }: MapPageProps) {
  const [stations, setStations] = useState<AdjustedStation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedBeacon, setSelectedBeacon] = useState<{ label: string; easting: number; northing: number } | null>(null);
  const [editingEnabled, setEditingEnabled] = useState(false);
  const [savingVertices, setSavingVertices] = useState(false);
  const [saveMsg, setSaveMsg] = useState<string | null>(null);
  const [projectInfo, setProjectInfo] = useState<{
    name: string;
    lrNumber: string;
    surveyorName: string;
    surveyorLicense: string;
    clientName: string;
    county: string;
  } | null>(null);
  const dbClient = createClient();

  useEffect(() => {
    async function load() {
      const { data: { session } } = await dbClient.auth.getSession();
      if (!session) { setError('Not authenticated'); return; }

      const { data: project, error: projErr } = await dbClient
        .from('projects')
        .select('boundary_data, id, name, lr_number, surveyor_name, surveyor_license, client_name, county')
        .eq('id', params.id)
        .single();

      if (projErr || !project) {
        setError('Project not found');
        setLoading(false);
        return;
      }

      // Store project metadata for sheet layout
      setProjectInfo({
        name: project.name ?? '',
        lrNumber: project.lr_number ?? '',
        surveyorName: project.surveyor_name ?? '',
        surveyorLicense: project.surveyor_license ?? '',
        clientName: project.client_name ?? '',
        county: project.county ?? '',
      });

      const raw = project.boundary_data?.adjustedStations ?? [];
      if (raw.length < 3) {
        setError('No adjusted traverse data found. Complete the traverse computation first.');
        setLoading(false);
        return;
      }

      const mapped: AdjustedStation[] = raw.map((s: any) => ({
        pointName: s.pointName ?? s.label ?? s.id ?? String(s.station),
        originalEasting: Number(s.originalEasting ?? s.easting ?? 0),
        originalNorthing: Number(s.originalNorthing ?? s.northing ?? 0),
        adjustedEasting: Number(s.adjustedEasting ?? s.easting ?? 0),
        adjustedNorthing: Number(s.adjustedNorthing ?? s.northing ?? 0),
      }));

      setStations(mapped);
      setLoading(false);
    }

    load();
  }, [params.id]);

  // ── Handle beacon click from the map ─────────────────────────────────────
  const handleBeaconClick = useCallback((label: string, easting: number, northing: number) => {
    setSelectedBeacon({ label, easting, northing });
    // Auto-dismiss after 5 seconds
    setTimeout(() => setSelectedBeacon(null), 5000);
  }, []);

  // ── Handle vertex edits from the map → save back to project ──────────────
  const handleVerticesChange = useCallback(async (updated: Array<{ easting: number; northing: number }>) => {
    if (stations.length === 0 || updated.length === 0) return;

    setSavingVertices(true);
    setSaveMsg(null);

    try {
      // Rebuild adjustedStations with updated coordinates
      const newStations = stations.map((s, i) => {
        if (i < updated.length) {
          return {
            ...s,
            adjustedEasting: updated[i].easting,
            adjustedNorthing: updated[i].northing,
          };
        }
        return s;
      });

      // Fetch current boundary_data to preserve other fields
      const { data: project } = await dbClient
        .from('projects')
        .select('boundary_data')
        .eq('id', params.id)
        .single();

      const currentBoundaryData = project?.boundary_data ?? {};
      const updatedBoundaryData = {
        ...currentBoundaryData,
        adjustedStations: newStations.map(s => ({
          pointName: s.pointName,
          originalEasting: s.originalEasting,
          originalNorthing: s.originalNorthing,
          adjustedEasting: s.adjustedEasting,
          adjustedNorthing: s.adjustedNorthing,
        })),
      };

      const { error: updateErr } = await dbClient
        .from('projects')
        .update({ boundary_data: updatedBoundaryData })
        .eq('id', params.id);

      if (updateErr) {
        setSaveMsg('Failed to save vertex changes');
      } else {
        setStations(newStations);
        setSaveMsg('Vertices saved');
      }
    } catch {
      setSaveMsg('Error saving vertex changes');
    } finally {
      setSavingVertices(false);
      setTimeout(() => setSaveMsg(null), 3000);
    }
  }, [stations, params.id, dbClient]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full text-sm text-gray-500">
        Loading traverse data...
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-center">
          <p className="text-sm text-red-600 font-medium">{error}</p>
          <p className="text-xs text-gray-500 mt-1">
            Ensure the traverse has been computed and adjusted before viewing the map.
          </p>
        </div>
      </div>
    );
  }

  const sumE = stations.reduce((sum, s) => sum + s.adjustedEasting, 0);
  const sumN = stations.reduce((sum, s) => sum + s.adjustedNorthing, 0);
  const centroidEasting = sumE / stations.length;
  const centroidNorthing = sumN / stations.length;

  return (
    <div className="h-full flex flex-col">
      {/* ── Toolbar strip ──────────────────────────────────────────────── */}
      <div className="flex items-center gap-2 px-3 py-1.5 bg-gray-50 border-b border-gray-200 text-xs">
        <button
          onClick={() => setEditingEnabled(v => !v)}
          className={`px-3 py-1.5 rounded font-medium transition-colors ${
            editingEnabled
              ? 'bg-amber-500 text-white'
              : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-100'
          }`}
          title={editingEnabled ? 'Disable vertex editing' : 'Enable vertex editing — drag vertices to adjust parcel boundary'}
        >
          {editingEnabled ? 'Editing On' : 'Edit Vertices'}
        </button>
        {editingEnabled && (
          <span className="text-amber-600">
            Drag vertices to adjust. Changes save automatically.
          </span>
        )}
        {savingVertices && (
          <span className="text-blue-600">Saving...</span>
        )}
        {saveMsg && (
          <span className={saveMsg.includes('Failed') || saveMsg.includes('Error') ? 'text-red-600' : 'text-green-600'}>
            {saveMsg}
          </span>
        )}
        <div className="flex-1" />
        {selectedBeacon && (
          <div className="flex items-center gap-2 px-2 py-1 bg-blue-50 border border-blue-200 rounded">
            <span className="font-semibold text-blue-800">{selectedBeacon.label}</span>
            <span className="text-blue-600 font-mono">
              E {selectedBeacon.easting.toFixed(3)} | N {selectedBeacon.northing.toFixed(3)}
            </span>
          </div>
        )}
      </div>

      {/* ── Survey Map ─────────────────────────────────────────────────── */}
      <div className="flex-1">
        <SurveyMap
          projectId={params.id}
          adjustedStations={stations}
          centroidEasting={centroidEasting}
          centroidNorthing={centroidNorthing}
          readOnly={!editingEnabled}
          enableEditing={editingEnabled}
          onBeaconClick={handleBeaconClick}
          onVerticesChange={handleVerticesChange}
          lrNumber={projectInfo?.lrNumber}
          projectName={projectInfo?.name}
          surveyorName={projectInfo?.surveyorName}
          surveyorLicense={projectInfo?.surveyorLicense}
          clientName={projectInfo?.clientName}
          county={projectInfo?.county}
        />
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/api-client/client';
import Link from 'next/link';
import { computeChainageTable } from '@/lib/engine/chainage'
import { generateLongitudinalProfileSvg } from '@/lib/reports/profileSvg'

interface PageProps {
  params: { id: string }
}

interface Project {
  id: string;
  name: string;
  location: string | null;
  utm_zone: number;
  hemisphere: string;
}

interface SurveyPoint {
  id: string;
  name: string;
  easting: number;
  northing: number;
  elevation: number | null;
}

interface Alignment {
  id: string;
  name: string;
  description: string | null;
}

interface ChainagePoint {
  id: string;
  point_name: string;
  chainage: number;
  easting: number;
  northing: number;
  elevation: number;
}

interface CrossSection {
  id: string;
  chainage: number;
  offset_distance: number;
  offset_direction: string;
  elevation: number;
}

export default function ProfilesPage({ params }: PageProps) {
  const dbClient = createClient();
  const [profileError, setProfileError] = useState<string|null>(null)
  const [project, setProject] = useState<Project | null>(null);
  const [points, setPoints] = useState<SurveyPoint[]>([]);
  const [loading, setLoading] = useState(true);
  
  const [alignments, setAlignments] = useState<Alignment[]>([]);
  const [selectedAlignment, setSelectedAlignment] = useState<Alignment | null>(null);
  const [chainagePoints, setChainagePoints] = useState<ChainagePoint[]>([]);
  const [crossSections, setCrossSections] = useState<CrossSection[]>([]);
  
  const [newAlignmentName, setNewAlignmentName] = useState('');
  const [selectedPoints, setSelectedPoints] = useState<SurveyPoint[]>([]);
  const [activeTab, setActiveTab] = useState<'create' | 'profile' | 'cross-sections'>('create');

  const [svgModalOpen, setSvgModalOpen] = useState(false);
  const [svgPage, setSvgPage] = useState<'A3' | 'A4'>('A3');
  const [svgOrientation, setSvgOrientation] = useState<'landscape' | 'portrait'>('landscape');
  const [svgHScale, setSvgHScale] = useState<number>(1000);
  const [svgVScale, setSvgVScale] = useState<number>(100);

  // Close the SVG preview on Escape (document-level, works regardless of focus)
  useEffect(() => {
    if (!svgModalOpen) return
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') setSvgModalOpen(false) }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [svgModalOpen])

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const { data: projectData } = await dbClient
        .from('projects')
        .select('*')
        .eq('id', params.id)
        .single();
      if (projectData) setProject(projectData);

      const { data: pointsData } = await dbClient
        .from('survey_points')
        .select('*')
        .eq('project_id', params.id)
        .order('name');
      if (pointsData) setPoints(pointsData);

      const { data: alignmentsData } = await dbClient
        .from('alignments')
        .select('*')
        .eq('project_id', params.id)
        .order('created_at', { ascending: false });
      if (alignmentsData) setAlignments(alignmentsData);
    } catch (err) {
      console.error('Error loading data:', err);
    } finally {
      setLoading(false);
    }
  }, [dbClient, params.id]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const loadAlignmentData = async (alignmentId: string) => {
    const { data: cpData } = await dbClient
      .from('chainage_points')
      .select('*')
      .eq('alignment_id', alignmentId)
      .order('chainage');
    if (cpData) setChainagePoints(cpData);

    const { data: csData } = await dbClient
      .from('cross_sections')
      .select('*')
      .eq('alignment_id', alignmentId)
      .order('chainage');
    if (csData) setCrossSections(csData);
  };

  const createAlignment = async () => {
    if (!newAlignmentName || selectedPoints.length < 2) return;

    try {
      const { data: alignment, error } = await dbClient
        .from('alignments')
        .insert({
          project_id: params.id,
          name: newAlignmentName
        })
        .select()
        .single();

      if (error) throw error;

      const first = selectedPoints[0]
      const table = computeChainageTable({
        start: { easting: first.easting, northing: first.northing },
        startName: first.name,
        startChainage: 0,
        alignment: selectedPoints.slice(1).map((p) => ({ name: p.name, easting: p.easting, northing: p.northing })),
      })

      const byName = new Map(selectedPoints.map((p) => [p.name, p]))
      const chainageData = table.map((row) => {
        const source = byName.get(row.pointName)
        return {
          alignment_id: alignment.id,
          project_id: params.id,
          point_name: row.pointName,
          chainage: row.chainage,
          easting: row.easting,
          northing: row.northing,
          elevation: source?.elevation ?? 0,
        }
      })

      await dbClient.from('chainage_points').insert(chainageData)

      setNewAlignmentName('');
      setSelectedPoints([]);
      await loadData();
      setSelectedAlignment(alignment);
      await loadAlignmentData(alignment.id);
      setActiveTab('profile');
    } catch (err) {
      console.error('Error creating alignment:', err);
      setProfileError('Failed to create alignment. Please try again.');
    }
  };

  const togglePointSelection = (point: SurveyPoint) => {
    if (selectedPoints.find((p) => p.id === point.id)) {
      setSelectedPoints(selectedPoints.filter((p) => p.id !== point.id));
    } else {
      setSelectedPoints([...selectedPoints, point]);
    }
  };

  const handleAlignmentSelect = async (alignment: Alignment) => {
    setSelectedAlignment(alignment);
    await loadAlignmentData(alignment.id);
    setActiveTab('profile');
  };

  const addCrossSection = async (chainage: number) => {
    if (!selectedAlignment) return;

    const centerPoint = chainagePoints.find((cp) => Math.abs(cp.chainage - chainage) < 0.001);
    
    await dbClient.from('cross_sections').insert({
      alignment_id: selectedAlignment.id,
      chainage,
      offset_distance: 0,
      offset_direction: 'center',
      elevation: centerPoint?.elevation || 0
    });

    await loadAlignmentData(selectedAlignment.id);
  };

  const formatChainage = (value: number): string => {
    const km = Math.floor(value / 1000);
    const m = value % 1000;
    return `${km}+${m.toFixed(3).padStart(3, '0')}`;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-[var(--accent)]">Loading...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] text-[var(--text-primary)]">
      <div className="border-b border-[var(--border-color)] bg-[var(--bg-card)]">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div>
              <Link href={`/project/${params.id}`} className="text-[var(--accent)] hover:underline text-sm">
                ← Back to Project
              </Link>
              <h1 className="text-2xl font-bold mt-1">Profile Generator</h1>
              <p className="text-[var(--text-muted)] text-sm">{project?.name}</p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={() => setActiveTab('create')}
                className={`px-4 py-2 rounded text-sm font-medium ${
                  activeTab === 'create' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                }`}
              >
                Create Alignment
              </button>
              <button
                onClick={() => setActiveTab('profile')}
                disabled={!selectedAlignment}
                className={`px-4 py-2 rounded text-sm font-medium ${
                  activeTab === 'profile' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                } disabled:opacity-50`}
              >
                Longitudinal Profile
              </button>
              <button
                onClick={() => setActiveTab('cross-sections')}
                disabled={!selectedAlignment}
                className={`px-4 py-2 rounded text-sm font-medium ${
                  activeTab === 'cross-sections' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'
                } disabled:opacity-50`}
              >
                Cross Sections
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-6">
        {activeTab === 'create' && (
          <div className="space-y-6">
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h2 className="text-lg font-semibold mb-4">Create New Alignment</h2>
              <div className="grid md:grid-cols-3 gap-4">
                <div>
                  <label className="label" htmlFor="alignment-name">Alignment Name</label>
                  <input id="alignment-name"
                    className="input"
                    value={newAlignmentName}
                    onChange={e => setNewAlignmentName(e.target.value)}
                    aria-label="e.g., Main Road Centerline" placeholder="e.g., Main Road Centerline"
                  />
                </div>
                <div className="md:col-span-2 flex items-end">
                  <button
                    onClick={createAlignment}
                    disabled={!newAlignmentName || selectedPoints.length < 2}
                    className="px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded disabled:opacity-50"
                  >
                    Create Alignment
                  </button>
                </div>
              </div>
            </div>

            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h3 className="font-semibold mb-4">Select Points for Alignment (in order)</h3>
              <p className="text-sm text-[var(--text-muted)] mb-4">Click points in the order they appear along the centerline</p>
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-2 max-h-64 overflow-y-auto">
                {points.map((point) => (
                  <button
                    key={point.id}
                    onClick={() => togglePointSelection(point)}
                    className={`p-3 rounded text-left transition-colors ${
                      selectedPoints.find((p) => p.id === point.id)
                        ? 'bg-[var(--accent)] text-black'
                        : 'bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)]'
                    }`}
                  >
                    <div className="font-medium">{point.name}</div>
                    <div className="text-xs opacity-75">
                      E: {point.easting.toFixed(0)}
                    </div>
                    <div className="text-xs opacity-75">
                      N: {point.northing.toFixed(0)}
                    </div>
                    {point.elevation && (
                      <div className="text-xs opacity-75">
                        RL: {point.elevation.toFixed(2)}
                      </div>
                    )}
                  </button>
                ))}
              </div>
              {selectedPoints.length > 0 && (
                <div className="mt-4 p-3 bg-[var(--bg-tertiary)]/50 rounded">
                  <span className="text-sm text-[var(--text-secondary)]">Selected: </span>
                  <span className="text-[var(--accent)]">
                    {selectedPoints.map((p) => p.name).join(' → ')}
                  </span>
                </div>
              )}
            </div>

            {alignments.length > 0 && (
              <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
                <h3 className="font-semibold mb-4">Existing Alignments</h3>
                <div className="space-y-2">
                  {alignments.map((alignment) => (
                    <button
                      key={alignment.id}
                      onClick={() => handleAlignmentSelect(alignment)}
                      className="w-full p-3 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] rounded text-left flex justify-between items-center"
                    >
                      <span className="font-medium">{alignment.name}</span>
                      <span className="text-[var(--accent)]">View →</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'profile' && selectedAlignment && (
          <div className="space-y-6">
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-semibold">Longitudinal Profile - {selectedAlignment.name}</h2>
                <button
                  onClick={() => setSvgModalOpen(true)}
                  className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm"
                >
                  Export SVG
                </button>
              </div>

              {chainagePoints.length > 0 ? (
                <>
                  <ProfileChart points={chainagePoints} />

                  {svgModalOpen && (
                    <div className="fixed inset-0 z-50 bg-black/70 flex items-center justify-center p-4">
                      <button type="button" aria-label="Close preview" tabIndex={-1} className="absolute inset-0 cursor-pointer border-0 p-0" onClick={() => setSvgModalOpen(false)} />
                      <div className="relative w-full max-w-2xl rounded-2xl border border-[var(--border-color)] bg-[var(--bg-secondary)] p-5 shadow-2xl" role="dialog" aria-modal="true" aria-label="Export profile SVG">
                        <div className="flex items-center justify-between mb-4">
                          <div className="text-lg font-semibold text-[var(--text-primary)]">Export profile SVG (to-scale)</div>
                          <button onClick={() => setSvgModalOpen(false)} className="px-3 py-1 rounded bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)]">
                            [x]
                          </button>
                        </div>

                        <div className="grid md:grid-cols-2 gap-4">
                          <div className="rounded-xl bg-[var(--bg-primary)]/40 border border-[var(--border-color)] p-4">
                            <div className="text-xs text-[var(--text-muted)] uppercase tracking-wider mb-2">Page</div>
                            <div className="flex gap-2">
                              <select value={svgPage} onChange={(e) => setSvgPage(e.target.value as any)} className="flex-1 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-[var(--text-primary)]">
                                <option value="A3">A3</option>
                                <option value="A4">A4</option>
                              </select>
                              <select value={svgOrientation} onChange={(e) => setSvgOrientation(e.target.value as any)} className="flex-1 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-[var(--text-primary)]">
                                <option value="landscape">Landscape</option>
                                <option value="portrait">Portrait</option>
                              </select>
                            </div>
                            <p className="text-xs text-[var(--text-muted)] mt-2">Print at 100% for true scale.</p>
                          </div>

                          <div className="rounded-xl bg-[var(--bg-primary)]/40 border border-[var(--border-color)] p-4">
                            <div className="text-xs text-[var(--text-muted)] uppercase tracking-wider mb-2">Scales</div>
                            <div className="grid grid-cols-2 gap-2">
                              <label className="text-xs text-[var(--text-secondary)]">
                                Horizontal (1:)
                                <input aria-label="Horizontal scale" inputMode="numeric" value={svgHScale} onChange={(e) => setSvgHScale(parseInt(e.target.value || '1000', 10) || 1000)} className="mt-1 w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-[var(--text-primary)] font-mono" />
                              </label>
                              <label className="text-xs text-[var(--text-secondary)]">
                                Vertical (1:)
                                <input aria-label="Vertical scale" inputMode="numeric" value={svgVScale} onChange={(e) => setSvgVScale(parseInt(e.target.value || '100', 10) || 100)} className="mt-1 w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded px-3 py-2 text-[var(--text-primary)] font-mono" />
                              </label>
                            </div>
                            <p className="text-xs text-[var(--text-muted)] mt-2">If a scale won’t fit, METARDU will auto-fit to the nearest standard scale.</p>
                          </div>
                        </div>

                        <div className="mt-5 flex items-center justify-end gap-2">
                          <button onClick={() => setSvgModalOpen(false)} className="px-4 py-2 rounded bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)]">
                            Cancel
                          </button>
                          <button
                            onClick={() => {
                              const svgText = generateLongitudinalProfileSvg(
                                chainagePoints.map((p) => ({ chainage: p.chainage, elevation: p.elevation, label: p.point_name })),
                                {
                                  page: svgPage,
                                  orientation: svgOrientation,
                                  horizontalScaleDenom: svgHScale,
                                  verticalScaleDenom: svgVScale,
                                  title: 'LONGITUDINAL PROFILE',
                                  subtitle: `${project?.name ?? ''} — ${selectedAlignment.name}`.trim(),
                                }
                              );
                              const blob = new Blob([svgText], { type: 'image/svg+xml;charset=utf-8' });
                              const url = URL.createObjectURL(blob);
                              const a = document.createElement('a');
                              a.href = url;
                              a.download = `${selectedAlignment.name}_profile_${svgPage}_${svgOrientation}_H${svgHScale}_V${svgVScale}.svg`;
                              a.click();
                              URL.revokeObjectURL(url);
                              setSvgModalOpen(false);
                            }}
                            className="px-4 py-2 rounded bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold"
                          >
                            Download SVG
                          </button>
                        </div>
                      </div>
                    </div>
                  )}
                  
                  <div className="mt-6 grid grid-cols-4 gap-4">
                    <div className="bg-[var(--bg-tertiary)]/50 p-3 rounded">
                      <div className="text-xs text-[var(--text-muted)]">Start Chainage</div>
                      <div className="text-[var(--accent)] font-mono">{formatChainage(chainagePoints[0]?.chainage || 0)}</div>
                    </div>
                    <div className="bg-[var(--bg-tertiary)]/50 p-3 rounded">
                      <div className="text-xs text-[var(--text-muted)]">End Chainage</div>
                      <div className="text-[var(--accent)] font-mono">{formatChainage(chainagePoints[chainagePoints.length - 1]?.chainage || 0)}</div>
                    </div>
                    <div className="bg-[var(--bg-tertiary)]/50 p-3 rounded">
                      <div className="text-xs text-[var(--text-muted)]">Lowest Point</div>
                      <div className="text-[var(--text-primary)] font-mono">
                        {Math.min(...chainagePoints.map((p) => p.elevation)).toFixed(3)} m
                      </div>
                    </div>
                    <div className="bg-[var(--bg-tertiary)]/50 p-3 rounded">
                      <div className="text-xs text-[var(--text-muted)]">Highest Point</div>
                      <div className="text-[var(--text-primary)] font-mono">
                        {Math.max(...chainagePoints.map((p) => p.elevation)).toFixed(3)} m
                      </div>
                    </div>
                  </div>
                </>
              ) : (
                <p className="text-[var(--text-muted)]">No chainage points found</p>
              )}
            </div>

            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h3 className="font-semibold mb-4">Chainage Points Table</h3>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--border-color)]">
                      <th className="text-left py-2 text-[var(--text-secondary)]">Point</th>
                      <th className="text-right py-2 text-[var(--text-secondary)]">Chainage</th>
                      <th className="text-right py-2 text-[var(--text-secondary)]">Easting</th>
                      <th className="text-right py-2 text-[var(--text-secondary)]">Northing</th>
                      <th className="text-right py-2 text-[var(--text-secondary)]">Elevation</th>
                    </tr>
                  </thead>
                  <tbody>
                    {chainagePoints.map((cp, idx) => (
                      <tr key={cp.id} className="border-b border-[var(--border-color)]">
                        <td className="py-2 text-[var(--text-primary)]">{cp.point_name}</td>
                        <td className="py-2 text-right font-mono text-[var(--accent)]">{formatChainage(cp.chainage)}</td>
                        <td className="py-2 text-right font-mono text-[var(--text-primary)]">{cp.easting.toFixed(3)}</td>
                        <td className="py-2 text-right font-mono text-[var(--text-primary)]">{cp.northing.toFixed(3)}</td>
                        <td className="py-2 text-right font-mono text-[var(--text-primary)]">{cp.elevation.toFixed(3)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'cross-sections' && selectedAlignment && (
          <div className="space-y-6">
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h2 className="text-lg font-semibold mb-4">Cross Sections - {selectedAlignment.name}</h2>
              <p className="text-sm text-[var(--text-muted)] mb-4">
                Select a chainage station to add cross section observations
              </p>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-2 mb-6">
                {chainagePoints.map((cp) => {
                  const hasCrossSection = crossSections.some((cs) => Math.abs(cs.chainage - cp.chainage) < 0.001);
                  return (
                    <button
                      key={cp.id}
                      onClick={() => addCrossSection(cp.chainage)}
                      className={`p-3 rounded text-center transition-colors ${
                        hasCrossSection
                          ? 'bg-green-900/30 border border-green-700 text-green-400'
                          : 'bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)]'
                      }`}
                    >
                      <div className="font-mono text-[var(--accent)]">{formatChainage(cp.chainage)}</div>
                      <div className="text-xs mt-1">
                        {hasCrossSection ? 'Has Data' : 'Add XS'}
                      </div>
                    </button>
                  );
                })}
              </div>

              <CrossSectionTable crossSections={crossSections} chainagePoints={chainagePoints} />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function ProfileChart({ points }: { points: ChainagePoint[] }) {
  const width = 800;
  const height = 300;
  const padding = 60;

  if (points.length === 0) return null;

  const elevations = points.map((p) => p.elevation);
  const minElev = Math.min(...elevations);
  const maxElev = Math.max(...elevations);
  const minCh = Math.min(...points.map((p) => p.chainage));
  const maxCh = Math.max(...points.map((p) => p.chainage));
  const chRange = maxCh - minCh || 1;
  const elevRange = maxElev - minElev || 1;

  function toX(ch: number) {
    return padding + ((ch - minCh) / chRange) * (width - padding * 2);
  }

  function toY(elev: number) {
    return height - padding - ((elev - minElev) / elevRange) * (height - padding * 2);
  }

  const pathData = points
    .map((p, i) => `${i === 0 ? 'M' : 'L'} ${toX(p.chainage)} ${toY(p.elevation)}`)
    .join(' ');

  return (
    <svg
      id="profile-svg"
      viewBox={`0 0 ${width} ${height}`}
      preserveAspectRatio="xMidYMid meet"
      fontFamily={'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace'}
      className="bg-[var(--bg-secondary)] rounded border border-amber-500/30 w-full"
    >
      <defs>
        <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
          <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#ffffff" strokeOpacity="0.08" strokeWidth="0.6" />
        </pattern>
      </defs>
      <rect width={width} height={height} fill="#0b1020" />
      <rect width={width} height={height} fill="url(#grid)" />
      
      <path d={pathData} stroke="#D17B47" strokeWidth={2} fill="none"/>
      
      {points.map((p) => (
        <g key={p.id}>
          <circle cx={toX(p.chainage)} cy={toY(p.elevation)} r={4} fill="#D17B47"/>
          <text x={toX(p.chainage)} y={height - 10} fill="white" fontSize={9} textAnchor="middle">
            {Math.round(p.chainage)}
          </text>
          <text x={toX(p.chainage)} y={toY(p.elevation) - 8} fill="white" fontSize={7} textAnchor="middle">
            {p.elevation.toFixed(2)}
          </text>
        </g>
      ))}
      
      <line x1={padding} y1={padding} x2={padding} y2={height - padding} stroke="white" strokeWidth={1}/>
      <line x1={padding} y1={height - padding} x2={width - padding} y2={height - padding} stroke="white" strokeWidth={1}/>
      
      <text x={width / 2} y={height - 5} fill="gray" fontSize={10} textAnchor="middle">
        Chainage (m)
      </text>
      <text x={15} y={height / 2} fill="gray" fontSize={10} textAnchor="middle" transform={`rotate(-90, 15, ${height / 2})`}>
        Elevation (m)
      </text>
      
      <text x={width - padding} y={padding} fill="#D17B47" fontSize={10} fontWeight="bold">
        PROFILE
      </text>
    </svg>
  );
}

function CrossSectionTable({ crossSections, chainagePoints }: { crossSections: CrossSection[]; chainagePoints: ChainagePoint[] }) {
  const groupedSections: { [key: number]: CrossSection[] } = {};
  
  crossSections.forEach((cs) => {
    if (!groupedSections[cs.chainage]) {
      groupedSections[cs.chainage] = [];
    }
    groupedSections[cs.chainage].push(cs);
  });

  const formatChainage = (value: number): string => {
    const km = Math.floor(value / 1000);
    const m = value % 1000;
    return `${km}+${m.toFixed(3).padStart(3, '0')}`;
  };

  if (Object.keys(groupedSections).length === 0) {
    return (
      <div className="text-center py-8 text-[var(--text-muted)]">
        <p>No cross sections added yet.</p>
        <p className="text-sm">Click on a chainage station above to add cross section data.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {Object.entries(groupedSections).map(([ch, sections]) => {
        const center = sections.find((s) => s.offset_direction === 'center');
        const left = sections.find((s) => s.offset_direction === 'left');
        const right = sections.find((s) => s.offset_direction === 'right');
        
        return (
          <div key={ch} className="bg-[var(--bg-tertiary)]/50 rounded-lg p-4">
            <h4 className="text-[var(--accent)] font-mono mb-2">{formatChainage(parseFloat(ch))}</h4>
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--border-color)]">
                  <th className="text-left py-1 text-[var(--text-secondary)]">Position</th>
                  <th className="text-right py-1 text-[var(--text-secondary)]">Offset (m)</th>
                  <th className="text-right py-1 text-[var(--text-secondary)]">Elevation (m)</th>
                </tr>
              </thead>
              <tbody>
                <tr className="border-b border-[var(--border-color)]">
                  <td className="py-1 text-[var(--text-primary)]">Left</td>
                  <td className="py-1 text-right font-mono text-[var(--text-primary)]">
                    {left ? left.offset_distance.toFixed(3) : '—'}
                  </td>
                  <td className="py-1 text-right font-mono text-[var(--text-primary)]">
                    {left ? left.elevation.toFixed(3) : '—'}
                  </td>
                </tr>
                <tr className="border-b border-[var(--border-color)] bg-[var(--accent)]/10">
                  <td className="py-1 text-[var(--accent)] font-medium">Center</td>
                  <td className="py-1 text-right font-mono text-[var(--accent)]">0.000</td>
                  <td className="py-1 text-right font-mono text-[var(--accent)]">
                    {center ? center.elevation.toFixed(3) : '—'}
                  </td>
                </tr>
                <tr>
                  <td className="py-1 text-[var(--text-primary)]">Right</td>
                  <td className="py-1 text-right font-mono text-[var(--text-primary)]">
                    {right ? right.offset_distance.toFixed(3) : '—'}
                  </td>
                  <td className="py-1 text-right font-mono text-[var(--text-primary)]">
                    {right ? right.elevation.toFixed(3) : '—'}
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        );
      })}
    </div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import {
  ArrowLeft, Plus, Trash2, Edit3, Check, X, FileText,
  AlertCircle, Loader2, Download
} from 'lucide-react'
import { z } from 'zod'
import { apiGet, apiPost, apiPatch, apiDelete, apiInvalidate, ApiError } from '@/lib/api/client'
import { PARCEL_STATUS_LABELS, PARCEL_STATUS_COLORS, type ParcelStatus } from '@/types/scheme'
import TraverseComputePanel from '@/components/scheme/TraverseComputePanel'
import CsvImportPanel from '@/components/scheme/CsvImportPanel'

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

const blocksListResponseSchema = z.object({
  data: z.array(z.any()),
}).passthrough()

const parcelsResponseSchema = z.object({
  data: z.array(z.any()),
}).passthrough()

const parcelMutationResponseSchema = z.object({
  data: z.any().optional(),
}).passthrough()

interface ParcelRow {
  id: number
  project_id: number
  block_id: number
  parcel_number: string
  lr_number_proposed: string | null
  lr_number_confirmed: string | null
  area_ha: number | null
  status: ParcelStatus
  assigned_surveyor: number | null
  notes: string | null
  block_number?: string
  block_name?: string
}

interface BlockInfo {
  id: number
  block_number: string
  block_name: string | null
  description: string | null
}

export default function BlockDetailPage() {
  const params = useParams()
  const router = useRouter()
  const projectId = params.id as string
  const blockId = params.blockId as string

  const [block, setBlock] = useState<BlockInfo | null>(null)
  const [parcels, setParcels] = useState<ParcelRow[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [showCreateParcel, setShowCreateParcel] = useState(false)
  const [editingId, setEditingId] = useState<number | null>(null)
  const [selectedParcelId, setSelectedParcelId] = useState<number | null>(null)

  // Create form
  const [newParcel, setNewParcel] = useState({
    parcel_number: '', lr_number_proposed: '', area_ha: '', notes: ''
  })
  const [creating, setCreating] = useState(false)

  // Edit form
  const [editForm, setEditForm] = useState({
    parcel_number: '', lr_number_proposed: '', lr_number_confirmed: '',
    area_ha: '', status: 'pending' as ParcelStatus, notes: ''
  })
  const [updating, setUpdating] = useState(false)
  const [deleting, setDeleting] = useState<number | null>(null)

  const fetchData = useCallback(async () => {
    try {
      setLoading(true)
      const [blocksJson, parcelJson] = await Promise.all([
        apiGet(`/api/scheme/blocks?project_id=${projectId}`, blocksListResponseSchema, { ttlMs: 30_000 }),
        apiGet(`/api/scheme/parcels?block_id=${blockId}`, parcelsResponseSchema, { ttlMs: 0 }),
      ])

      const found = blocksJson.data.find((b: any) => String(b.id) === String(blockId))
      if (found) setBlock(found)

      setParcels(parcelJson.data || [])
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to load block data')
    } finally {
      setLoading(false)
    }
  }, [projectId, blockId])

  useEffect(() => { void fetchData() }, [fetchData])

  const handleCreateParcel = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!newParcel.parcel_number.trim()) return
    setCreating(true)
    setError('')
    try {
      await apiPost(
        '/api/scheme/parcels',
        parcelMutationResponseSchema,
        {
          project_id: parseInt(projectId),
          block_id: parseInt(blockId),
          parcel_number: newParcel.parcel_number,
          lr_number_proposed: newParcel.lr_number_proposed || null,
          area_ha: newParcel.area_ha ? parseFloat(newParcel.area_ha) : null,
          notes: newParcel.notes || null,
        },
      )
      apiInvalidate(`/api/scheme/parcels?block_id=${blockId}`)
      setNewParcel({ parcel_number: '', lr_number_proposed: '', area_ha: '', notes: '' })
      setShowCreateParcel(false)
      void fetchData()
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to create parcel')
    } finally {
      setCreating(false)
    }
  }

  const handleUpdateParcel = async (e: React.FormEvent) => {
    e.preventDefault()
    if (editingId === null) return
    setUpdating(true)
    setError('')
    try {
      await apiPatch(
        `/api/scheme/parcels/${editingId}`,
        parcelMutationResponseSchema,
        {
          ...editForm,
          lr_number_proposed: editForm.lr_number_proposed || null,
          lr_number_confirmed: editForm.lr_number_confirmed || null,
          area_ha: editForm.area_ha ? parseFloat(editForm.area_ha) : null,
          notes: editForm.notes || null,
        },
      )
      apiInvalidate(`/api/scheme/parcels?block_id=${blockId}`)
      setEditingId(null)
      void fetchData()
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to update parcel')
    } finally {
      setUpdating(false)
    }
  }

  const handleDeleteParcel = async (parcelId: number, parcelNumber: string) => {
    if (!confirm(`Delete Parcel "${parcelNumber}"? This cannot be undone.`)) return
    setDeleting(parcelId)
    try {
      await apiDelete(`/api/scheme/parcels/${parcelId}`)
      apiInvalidate(`/api/scheme/parcels?block_id=${blockId}`)
      void fetchData()
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Failed to delete parcel')
    } finally {
      setDeleting(null)
    }
  }

  const startEdit = (parcel: ParcelRow) => {
    setEditingId(parcel.id)
    setEditForm({
      parcel_number: parcel.parcel_number,
      lr_number_proposed: parcel.lr_number_proposed || '',
      lr_number_confirmed: parcel.lr_number_confirmed || '',
      area_ha: parcel.area_ha ? String(parcel.area_ha) : '',
      status: parcel.status,
      notes: parcel.notes || '',
    })
  }

  const nextParcelSuggestion = parcels.length > 0
    ? String(parseInt(parcels[parcels.length - 1].parcel_number) + 1 || parcels.length + 1)
    : '1'

  const totalArea = parcels.reduce((sum, p) => sum + (parseFloat(String(p.area_ha)) || 0), 0)
  const completedCount = parcels.filter(p => ['approved', 'submitted'].includes(p.status)).length

  const inputClass = 'w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] placeholder-[var(--text-muted)] focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)] focus:outline-none transition-colors'
  const labelClass = 'block text-xs font-medium text-[var(--text-secondary)] mb-1'

  return (
    <div className="min-h-[calc(100vh-8rem)] bg-[var(--bg-primary)]">
      <main className="max-w-5xl mx-auto px-4 py-8">

        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-[var(--text-muted)] mb-6">
          <Link href="/dashboard" className="hover:text-[var(--accent)] transition-colors">Dashboard</Link>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
          <Link href={`/project/${projectId}/scheme`} className="hover:text-[var(--accent)] transition-colors">Scheme</Link>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
          <Link href={`/project/${projectId}/scheme/blocks`} className="hover:text-[var(--accent)] transition-colors">Blocks</Link>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
          <span className="text-[var(--text-primary)]">{block?.block_number || blockId}</span>
        </div>

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4 mb-8">
          <div className="flex items-center gap-4">
            <button
              onClick={() => router.push(`/project/${projectId}/scheme/blocks`)}
              className="p-2 hover:bg-[var(--bg-secondary)] rounded-lg transition-colors"
            >
              <ArrowLeft className="w-5 h-5 text-[var(--text-secondary)]" />
            </button>
            <div>
              <div className="flex items-center gap-3 mb-1">
                <span className="px-3 py-1 bg-orange-500/10 border border-orange-500/20 text-orange-400 font-mono font-bold text-sm rounded-lg">
                  {block?.block_number || '...'}
                </span>
                <h1 className="text-xl font-bold text-[var(--text-primary)]">
                  {block?.block_name || `Block ${block?.block_number || ''}`}
                </h1>
              </div>
              {block?.description && (
                <p className="text-sm text-[var(--text-muted)]">{block.description}</p>
              )}
              <div className="flex items-center gap-4 mt-2 text-xs text-[var(--text-muted)]">
                <span>{parcels.length} parcel{parcels.length !== 1 ? 's' : ''}</span>
                <span>{totalArea.toFixed(4)} ha total</span>
                <span className="text-emerald-400">{completedCount} done</span>
              </div>
            </div>
          </div>
          <button
            onClick={() => setShowCreateParcel(true)}
            className="px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black text-sm font-semibold rounded-lg transition-all flex items-center gap-2 shrink-0"
          >
            <Plus className="w-4 h-4" />
            Add Parcel
          </button>
        </div>

        {/* Traverse compute panel — shown when a parcel is selected */}
        {selectedParcelId && (
          <div className="mb-6">
            <TraverseComputePanel parcelId={selectedParcelId} />
          </div>
        )}

        {/* Error Banner */}
        {error && (
          <div className="mb-6 p-3.5 bg-red-900/20 border border-red-500/30 rounded-lg text-sm text-red-400 flex items-center gap-2">
            <AlertCircle className="w-5 h-5 shrink-0" />
            {error}
            <button onClick={() => setError('')} className="ml-auto"><X className="w-4 h-4" /></button>
          </div>
        )}

        {/* Create Parcel Form */}
        {showCreateParcel && (
          <div className="mb-6 p-5 bg-[var(--bg-card)] rounded-xl border border-[var(--accent)]/30 space-y-4">
            <h3 className="text-sm font-semibold text-[var(--text-primary)] flex items-center gap-2">
              <FileText className="w-4 h-4 text-[var(--accent)]" />
              New Parcel
            </h3>
            <form onSubmit={handleCreateParcel} className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              <div>
                <label htmlFor="new-parcel-number" className={labelClass}>Parcel Number <span className="text-orange-400">*</span></label>
                <input id="new-parcel-number"
                  type="text"
                  value={newParcel.parcel_number}
                  onChange={e => setNewParcel(prev => ({ ...prev, parcel_number: e.target.value }))}
                  className={inputClass}
                  placeholder={nextParcelSuggestion}
                  // eslint-disable-next-line jsx-a11y/no-autofocus -- focus into the revealed create form (WCAG 2.4.3)
                  autoFocus
                  required
                />
              </div>
              <div>
                <label htmlFor="new-parcel-lr" className={labelClass}>Proposed LR No.</label>
                <input
                  id="new-parcel-lr"
                  type="text"
                  value={newParcel.lr_number_proposed}
                  onChange={e => setNewParcel(prev => ({ ...prev, lr_number_proposed: e.target.value }))}
                  className={inputClass}
                  placeholder="e.g., MN/III/1234"
                />
              </div>
              <div>
                <label htmlFor="new-parcel-area" className={labelClass}>Area (ha)</label>
                <input
                  id="new-parcel-area"
                  type="number"
                  step="0.0001"
                  value={newParcel.area_ha}
                  onChange={e => setNewParcel(prev => ({ ...prev, area_ha: e.target.value }))}
                  className={inputClass}
                  placeholder="e.g., 0.0625"
                />
              </div>
              <div>
                <label htmlFor="new-parcel-notes" className={labelClass}>Notes</label>
                <input
                  id="new-parcel-notes"
                  type="text"
                  value={newParcel.notes}
                  onChange={e => setNewParcel(prev => ({ ...prev, notes: e.target.value }))}
                  className={inputClass}
                  placeholder="Optional"
                />
              </div>
            </form>
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={() => { setShowCreateParcel(false); setNewParcel({ parcel_number: '', lr_number_proposed: '', area_ha: '', notes: '' }) }}
                className="px-4 py-2 text-xs border border-[var(--border-color)] rounded-lg text-[var(--text-secondary)] hover:bg-[var(--bg-secondary)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleCreateParcel}
                disabled={creating || !newParcel.parcel_number.trim()}
                className="px-4 py-2 text-xs bg-[var(--accent)] text-black font-semibold rounded-lg hover:bg-[var(--accent-dim)] transition-all disabled:opacity-40 flex items-center gap-1"
              >
                {creating ? <Loader2 className="w-3 h-3 animate-spin" /> : <Check className="w-3 h-3" />}
                Add Parcel
              </button>
            </div>
          </div>
        )}

        {/* Parcels Table or Empty State */}
        {loading ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="w-6 h-6 animate-spin text-[var(--text-muted)]" />
          </div>
        ) : parcels.length === 0 && !showCreateParcel ? (
          <div className="space-y-4">
            <div className="text-center py-12">
              <FileText className="w-12 h-12 text-[var(--text-muted)] mx-auto mb-4 opacity-20" />
              <p className="text-[var(--text-secondary)] mb-1">No parcels yet</p>
              <p className="text-xs text-[var(--text-muted)] mb-4">Add parcels individually or import from CSV.</p>
              <button
                onClick={() => setShowCreateParcel(true)}
                className="px-4 py-2 bg-[var(--accent)] text-black text-sm font-semibold rounded-lg hover:bg-[var(--accent-dim)] transition-all inline-flex items-center gap-2"
              >
                <Plus className="w-4 h-4" />
                Add First Parcel
              </button>
            </div>
            {/* CSV Import — shown even on empty state */}
            <CsvImportPanel
              projectId={projectId}
              blockId={blockId}
              blockName={block?.block_number || ''}
              onImportComplete={fetchData}
            />
          </div>
        ) : (
          <div className="space-y-4">
            <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-xs text-[var(--text-muted)] border-b border-[var(--border-color)]">
                      <th className="px-4 py-3 font-medium">Parcel #</th>
                      <th className="px-4 py-3 font-medium">Proposed LR</th>
                      <th className="px-4 py-3 font-medium">Confirmed LR</th>
                      <th className="px-4 py-3 font-medium">Area (ha)</th>
                      <th className="px-4 py-3 font-medium">Status</th>
                      <th className="px-4 py-3 font-medium text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {parcels.map((parcel) => (
                      <tr key={parcel.id} className="border-b border-[var(--border-color)]/50 hover:bg-[var(--bg-secondary)] transition-colors">
                        {editingId === parcel.id ? (
                          <>
                            <td className="px-4 py-2">
                              <input aria-label="Parcel number" type="text" value={editForm.parcel_number}
                                onChange={e => setEditForm(p => ({ ...p, parcel_number: e.target.value }))}
                                className={inputClass} required />
                            </td>
                            <td className="px-4 py-2">
                              <input aria-label="Lr number proposed" type="text" value={editForm.lr_number_proposed}
                                onChange={e => setEditForm(p => ({ ...p, lr_number_proposed: e.target.value }))}
                                className={inputClass} />
                            </td>
                            <td className="px-4 py-2">
                              <input aria-label="Lr number confirmed" type="text" value={editForm.lr_number_confirmed}
                                onChange={e => setEditForm(p => ({ ...p, lr_number_confirmed: e.target.value }))}
                                className={inputClass} />
                            </td>
                            <td className="px-4 py-2">
                              <input aria-label="Area ha" type="number" step="0.0001" value={editForm.area_ha}
                                onChange={e => setEditForm(p => ({ ...p, area_ha: e.target.value }))}
                                className={inputClass} />
                            </td>
                            <td className="px-4 py-2">
                              <select value={editForm.status}
                                onChange={e => setEditForm(p => ({ ...p, status: e.target.value as ParcelStatus }))}
                                className={inputClass}>
                                {(Object.entries(PARCEL_STATUS_LABELS) as [ParcelStatus, string][]).map(
                                  ([val, label]) => <option key={val} value={val}>{label}</option>
                                )}
                              </select>
                            </td>
                            <td className="px-4 py-2">
                              <div className="flex justify-end gap-1">
                                <button onClick={handleUpdateParcel} disabled={updating}
                                  className="p-1.5 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] transition-colors">
                                  {updating ? <Loader2 className="w-3 h-3 animate-spin" /> : <Check className="w-3 h-3" />}
                                </button>
                                <button onClick={() => setEditingId(null)}
                                  className="p-1.5 border border-[var(--border-color)] rounded-lg text-[var(--text-secondary)] hover:bg-[var(--bg-secondary)] transition-colors">
                                  <X className="w-3 h-3" />
                                </button>
                              </div>
                            </td>
                          </>
                        ) : (
                          <>
                            <td className="px-4 py-3 font-mono text-[var(--accent)] font-medium">{parcel.parcel_number}</td>
                            <td className="px-4 py-3 text-[var(--text-primary)] font-mono text-xs">{parcel.lr_number_proposed || '—'}</td>
                            <td className="px-4 py-3 text-[var(--text-primary)] font-mono text-xs">{parcel.lr_number_confirmed || '—'}</td>
                            <td className="px-4 py-3 text-[var(--text-secondary)]">{parcel.area_ha ? Number(parcel.area_ha).toFixed(4) : '—'}</td>
                            <td className="px-4 py-3">
                              <span className={`inline-flex px-2 py-0.5 text-xs font-medium rounded-full border ${PARCEL_STATUS_COLORS[parcel.status]}`}>
                                {PARCEL_STATUS_LABELS[parcel.status]}
                              </span>
                            </td>
                            <td className="px-4 py-3">
                              <div className="flex justify-end gap-1">
                                <button
                                  onClick={() => setSelectedParcelId(selectedParcelId === parcel.id ? null : parcel.id)}
                                  className={`p-1.5 rounded-lg transition-colors text-[var(--text-muted)] ${selectedParcelId === parcel.id ? 'bg-[var(--accent)]/20 text-[var(--accent)]' : 'hover:bg-[var(--bg-tertiary)] hover:text-[var(--accent)]'}`}
                                  title="Compute Traverse"
                                >
                                  <FileText className="w-3.5 h-3.5" />
                                </button>
                                <a
                                  href={`/api/scheme/deed-plan?parcel_id=${parcel.id}`}
                                  target="_blank"
                                  className="p-1.5 hover:bg-[var(--bg-tertiary)] rounded-lg transition-colors text-[var(--text-muted)] hover:text-emerald-400"
                                  title="Download Deed Plan"
                                  onClick={e => {
                                    if (parcel.status === 'pending') {
                                      e.preventDefault()
                                      alert('Compute traverse first before generating a deed plan.')
                                    }
                                  }}
                                >
                                  <Download className="w-3.5 h-3.5" />
                                </a>
                                <button onClick={() => startEdit(parcel)}
                                  className="p-1.5 hover:bg-[var(--bg-tertiary)] rounded-lg transition-colors text-[var(--text-muted)] hover:text-[var(--text-primary)]"
                                  title="Edit">
                                  <Edit3 className="w-3.5 h-3.5" />
                                </button>
                                <button
                                  onClick={() => handleDeleteParcel(parcel.id, parcel.parcel_number)}
                                  disabled={deleting === parcel.id}
                                  className="p-1.5 hover:bg-red-900/20 rounded-lg transition-colors text-[var(--text-muted)] hover:text-red-400"
                                  title="Delete">
                                  {deleting === parcel.id
                                    ? <Loader2 className="w-3.5 h-3.5 animate-spin" />
                                    : <Trash2 className="w-3.5 h-3.5" />}
                                </button>
                              </div>
                            </td>
                          </>
                        )}
                      </tr>
                    ))}
                  </tbody>
                  {parcels.length > 0 && (
                    <tfoot>
                      <tr className="border-t-2 border-[var(--border-color)]">
                        <td colSpan={3} className="px-4 py-3 text-xs font-semibold text-[var(--text-secondary)]">
                          {parcels.length} parcel{parcels.length !== 1 ? 's' : ''}
                        </td>
                        <td className="px-4 py-3 text-xs font-semibold text-[var(--text-primary)]">
                          {totalArea.toFixed(4)}
                        </td>
                        <td colSpan={2} className="px-4 py-3 text-xs font-medium text-emerald-400">
                          {completedCount} completed
                        </td>
                      </tr>
                    </tfoot>
                  )}
                </table>
              </div>
            </div>

            {/* CSV Import always available when there are existing parcels too */}
            <CsvImportPanel
              projectId={projectId}
              blockId={blockId}
              blockName={block?.block_number || ''}
              onImportComplete={fetchData}
            />
          </div>
        )}
      </main>
    </div>
  )
}

'use client';

/*
 * PERFORMANCE NOTE — OpenLayers static imports (~700KB vendor-ol chunk)
 * These 14 OL modules are intentionally imported at the top level rather than
 * dynamically imported because the webpack splitChunks config already isolates
 * them into a separate `vendor-ol` chunk.  This page is only navigated to
 * explicitly (not on the initial load path), so the OL chunk is never part of
 * the critical-path bundle.  Dynamic imports would add complexity without
 * measurable benefit since the chunk is already code-split.
 */

import { useEffect, useState, useRef } from 'react'
import { useParams } from 'next/navigation'
import Link from 'next/link'
import Map from 'ol/Map'
import View from 'ol/View'
import TileLayer from 'ol/layer/Tile'
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import XYZ from 'ol/source/XYZ'
import GeoJSON from 'ol/format/GeoJSON'
import { fromLonLat } from 'ol/proj'
import { Style, Fill, Stroke, Text } from 'ol/style'
import CircleStyle from 'ol/style/Circle'
import Overlay from 'ol/Overlay'
import { ArrowLeft, Download } from 'lucide-react'
import type Feature from 'ol/Feature'
import { registerProjections } from '@/lib/map/projection'

const STATUS_COLORS: Record<string, string> = {
  pending: '#6b7280',
  field_complete: '#3b82f6',
  computed: '#22c55e',
  plan_generated: '#f59e0b',
  submitted: '#8b5cf6',
  approved: '#10b981',
}

export default function SchemeMapPage() {
  const params = useParams()
  const projectId = params.id as string
  const mapRef = useRef<HTMLDivElement>(null)
  const mapInstance = useRef<Map | null>(null)
  const popupRef = useRef<HTMLDivElement>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [parcelCount, setParcelCount] = useState(0)

  useEffect(() => {
    if (!mapRef.current || !projectId) return

    setLoading(true)

    // Register EPSG:21037 (Arc 1960 / UTM Zone 37S) before using it for GeoJSON reprojection
    registerProjections()

    // Create map
    const vectorSource = new VectorSource()

    const map = new Map({
      target: mapRef.current,
      layers: [
        new TileLayer({
          source: new XYZ({
            url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
            maxZoom: 19,
            crossOrigin: 'anonymous',
          }),
        }),
        new VectorLayer({
          source: vectorSource,
          style: ((feature: any) => {
            const props = feature.getProperties()
            const status = props.status as string || 'pending'
            const color = STATUS_COLORS[status] || '#6b7280'
            const geomType = feature.getGeometry()?.getType()

            if (geomType === 'Polygon') {
              return new Style({
                fill: new Fill({ color: color + '40' }), // 25% opacity
                stroke: new Stroke({ color, width: 2.5 }),
                text: new Text({
                  text: String(props.parcel_number || ''),
                  font: 'bold 12px sans-serif',
                  fill: new Fill({ color: '#ffffff' }),
                  stroke: new Stroke({ color: '#000000', width: 3 }),
                }),
              })
            }

            if (geomType === 'Point' && props.type === 'block_label') {
              return new Style({
                text: new Text({
                  text: `Block ${props.block_number}\n(${props.parcel_count} parcels)`,
                  font: 'bold 14px sans-serif',
                  fill: new Fill({ color: '#1e40af' }),
                  stroke: new Stroke({ color: '#ffffff', width: 4 }),
                  textAlign: 'center',
                }),
              })
            }

            return new Style({
              image: new CircleStyle({
                radius: 5,
                fill: new Fill({ color }),
                stroke: new Stroke({ color: '#000', width: 1 }),
              }),
            })
          }) as any,
        }),
      ],
      view: new View({
        center: fromLonLat([37.0, -1.3]), // Default: central Kenya
        zoom: 15,
      }),
    })

    // Popup overlay
    const overlay = new Overlay({
      element: popupRef.current || undefined,
      autoPan: true,
    })
    map.addOverlay(overlay)

    map.on('click', (evt) => {
      const feature = map.forEachFeatureAtPixel(evt.pixel, f => f)
      if (feature && popupRef.current) {
        const props = feature.getProperties()
        // VULN-002 FIX (security review 2026-08-03): block/parcel numbers and
        // LR numbers are user-entered — render with textContent, never innerHTML.
        const el = popupRef.current
        el.replaceChildren()

        const wrap = document.createElement('div')
        wrap.style.cssText = 'font-size:12px;'

        const title = document.createElement('strong')
        title.textContent = `Block ${String(props.block_number ?? '')} — Parcel ${String(props.parcel_number || '')}`
        wrap.append(title)
        wrap.append(document.createElement('br'))

        if (props.lr_number) {
          const lr = document.createElement('div')
          lr.textContent = `LR: ${String(props.lr_number)}`
          wrap.append(lr)
        }
        if (props.area_ha) {
          const area = document.createElement('div')
          area.textContent = `Area: ${Number(props.area_ha).toFixed(4)} ha`
          wrap.append(area)
        }

        const statusRow = document.createElement('div')
        const statusLabel = document.createTextNode('Status: ')
        const statusSpan = document.createElement('span')
        statusSpan.style.color = STATUS_COLORS[props.status as string] || '#999'
        statusSpan.textContent = String(props.status || 'pending')
        statusRow.append(statusLabel, statusSpan)
        wrap.append(statusRow)

        el.append(wrap)
        el.style.display = 'block'
        overlay.setPosition(evt.coordinate)
      } else if (popupRef.current) {
        popupRef.current.style.display = 'none'
      }
    })

    mapInstance.current = map

    // Fetch scheme GeoJSON
    fetch(`/api/scheme/map?project_id=${projectId}`)
      .then(res => res.json())
      .then(data => {
        if (data.features && data.features.length > 0) {
          const format = new GeoJSON()
          const features = format.readFeatures(data, {
            dataProjection: 'EPSG:21037', // Arc 1960 / UTM Zone 37S (Kenya cadastral datum)
            featureProjection: 'EPSG:3857', // Web Mercator
          })
          vectorSource.addFeatures(features)
          setParcelCount(features.filter(f => f.getGeometry()?.getType() === 'Polygon').length)

          // Zoom to extent
          const extent = vectorSource.getExtent()
          if (extent && extent[0] !== Infinity) {
            map.getView().fit(extent, { padding: [50, 50, 50, 50], maxZoom: 18 })
          }
        }
        setLoading(false)
      })
      .catch(() => {
        setError('Failed to load scheme data')
        setLoading(false)
      })

    return () => {
      map.setTarget(undefined)
    }
  }, [projectId])

  return (
    <div className="min-h-screen bg-gray-950 text-white">
      <div className="flex items-center justify-between px-6 py-4 border-b border-gray-800">
        <div className="flex items-center gap-4">
          <Link
            href={`/project/${projectId}/scheme`}
            className="p-2 hover:bg-gray-800 rounded-lg transition-colors"
          >
            <ArrowLeft className="w-5 h-5 text-gray-400" />
          </Link>
          <div>
            <h1 className="text-xl font-bold">Scheme Map</h1>
            <p className="text-sm text-gray-400">
              {loading ? 'Loading parcels...' : `${parcelCount} parcels shown`}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <a
            href={`/api/scheme/export/geojson?project_id=${projectId}`}
            className="inline-flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white text-sm rounded-lg transition-colors"
          >
            <Download className="w-4 h-4" />
            GeoJSON
          </a>
          <a
            href={`/api/scheme/export/dxf?project_id=${projectId}`}
            className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg transition-colors"
          >
            <Download className="w-4 h-4" />
            DXF
          </a>
        </div>
      </div>

      {error && (
        <div className="mx-6 mt-4 p-3 bg-red-900/50 border border-red-800 rounded-lg text-red-300 text-sm">
          {error}
        </div>
      )}

      <div className="relative" style={{ height: 'calc(100vh - 80px)' }}>
        <div ref={mapRef} className="w-full h-full" />

        {loading && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-950/60">
            <div className="flex items-center gap-3 text-gray-300">
              <svg className="w-6 h-6 animate-spin" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
              </svg>
              Loading scheme parcels...
            </div>
          </div>
        )}

        <div
          ref={popupRef}
          className="absolute bg-gray-800 border border-gray-600 rounded-lg p-3 shadow-xl"
          style={{ display: 'none', minWidth: 200 }}
        />

        {/* Legend */}
        <div className="absolute bottom-4 right-4 bg-gray-900/90 backdrop-blur border border-gray-700 rounded-lg p-3">
          <h4 className="text-xs font-semibold text-gray-400 mb-2">STATUS LEGEND</h4>
          {Object.entries(STATUS_COLORS).map(([status, color]) => (
            <div key={status} className="flex items-center gap-2 mb-1">
              <div className="w-3 h-3 rounded-full" style={{ backgroundColor: color }} />
              <span className="text-xs text-gray-300 capitalize">{status.replace('_', ' ')}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useEffect, useState, useCallback } from 'react'
import { useParams, useRouter } from 'next/navigation'
import Link from 'next/link'
import {
  ArrowLeft, Plus, LayoutGrid, MapPin, FileText,
  AlertCircle, CheckCircle2, Clock, BarChart3, Download, FolderArchive, Package, Map, Users
} from 'lucide-react'
import { z } from 'zod'
import { apiGet, ApiError } from '@/lib/api/client'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import type { SchemeDetails, Block, ParcelStatus } from '@/types/scheme'
import { SCHEME_STATUS_LABELS, PARCEL_STATUS_LABELS, PARCEL_STATUS_COLORS } from '@/types/scheme'

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

// /api/project/:id may return { data: project } | { project } | bare project
const projectRowSchema = z.object({
  id: z.union([z.number(), z.string()]),
  name: z.string(),
  survey_type: z.string().optional().default(''),
  location: z.string().optional().default(''),
  project_type: z.string().optional().default(''),
  utm_zone: z.union([z.number(), z.string()]).optional().default(37),
  hemisphere: z.string().optional().default('S'),
}).passthrough()

const projectEnvelopeSchema = z.union([
  z.object({ data: projectRowSchema }).passthrough(),
  z.object({ project: projectRowSchema }).passthrough(),
  projectRowSchema,
])

const blocksResponseSchema = z.object({
  data: z.array(z.any()),
}).passthrough()

const parcelsResponseSchema = z.object({
  data: z.array(z.any()),
}).passthrough()

const traverseSummarySchema = z.object({
  data: z.array(z.any()),
  summary: z.object({
    total: z.union([z.number(), z.string()]),
    passed: z.union([z.number(), z.string()]),
    failed: z.union([z.number(), z.string()]),
  }).passthrough(),
}).passthrough()

interface ProjectRow {
  id: number
  name: string
  survey_type: string
  location: string
  project_type: string
  utm_zone: number
  hemisphere: string
}

interface BlockWithCounts extends Block {
  parcel_count: number
  completed_count: number
}

export default function SchemeWorkspacePage() {
  const params = useParams()
  const router = useRouter()
  const projectId = params.id as string

  const [project, setProject] = useState<ProjectRow | null>(null)
  const [schemeDetails, setSchemeDetails] = useState<SchemeDetails | null>(null)
  const [blocks, setBlocks] = useState<BlockWithCounts[]>([])
  const [parcelCounts, setParcelCounts] = useState<Record<ParcelStatus, number>>({
    pending: 0, field_complete: 0, computed: 0, plan_generated: 0, submitted: 0, approved: 0
  })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  const fetchSchemeData = useCallback(async () => {
    try {
      setLoading(true)

      // Fetch project via /api/project/:id (accepts 3 envelope shapes)
      let proj: ProjectRow | null = null
      try {
        const pj = await apiGet(`/api/project/${projectId}`, projectEnvelopeSchema, { ttlMs: 30_000 })
        proj = ('data' in pj ? pj.data : 'project' in pj ? pj.project : pj) as ProjectRow
      } catch (err) {
        // 404 / not-ok → fall through to the blocks-existence fallback below
        if (err instanceof ApiError && !err.isNotFound && !err.isUnauthorized) {
          // unexpected error — surface it, but keep trying the fallback so the page can still load
          console.error('[scheme] project fetch failed:', (err as Error).message)
        }
      }

      if (!proj) {
        // Fallback: probe blocks endpoint — if it returns ok, treat projectId as a scheme project
        try {
          await apiGet(`/api/scheme/blocks?project_id=${projectId}`, blocksResponseSchema, { ttlMs: 0 })
        } catch {
          throw new Error('Failed to load project')
        }
        setProject({ id: parseInt(projectId), name: 'Scheme Project', survey_type: '', location: '', project_type: 'scheme', utm_zone: 37, hemisphere: 'S' } as ProjectRow)
      } else {
        setProject(proj)
      }

      // Fetch blocks with counts via API
      const blocksJson = await apiGet(`/api/scheme/blocks?project_id=${projectId}`, blocksResponseSchema, { ttlMs: 30_000 })
      const blks = (blocksJson.data || []) as BlockWithCounts[]
      setBlocks(blks)

      // Fetch all parcels across all blocks for status counts
      if (blks.length > 0) {
        try {
          const parcelsJson = await apiGet(`/api/scheme/parcels?project_id=${projectId}`, parcelsResponseSchema, { ttlMs: 30_000 })
          const parcels = parcelsJson.data || []

          const counts: Record<ParcelStatus, number> = {
            pending: 0, field_complete: 0, computed: 0, plan_generated: 0, submitted: 0, approved: 0
          }
          for (const p of parcels) {
            counts[p.status as ParcelStatus] = (counts[p.status as ParcelStatus] || 0) + 1
          }
          setParcelCounts(counts)
        } catch {
          // Non-fatal — counts just stay zeroed
        }
      }

      // Fetch scheme details (if the API existed — for now we load via blocks endpoint context)
      // The scheme details are loaded when the project was created
    } catch (err: unknown) {
      setError(err instanceof ApiError ? (err as Error).message : ((err as Error).message || 'Failed to load scheme data'))
    } finally {
      setLoading(false)
    }
  }, [projectId])

  useEffect(() => { void fetchSchemeData() }, [fetchSchemeData])

  // Fetch traverse accuracy summary
  useEffect(() => {
    if (!project?.id) return

    apiGet(`/api/scheme/traverse/summary?project_id=${project.id}`, traverseSummarySchema, { ttlMs: 0 })
      .then(result => {
        const { data, summary } = result

        // Update stat cards
        const totalEl = document.getElementById('summary-total')
        const passedEl = document.getElementById('summary-passed')
        const warningEl = document.getElementById('summary-warning')
        const failedEl = document.getElementById('summary-failed')
        if (totalEl) totalEl.textContent = String(summary.total)
        if (passedEl) passedEl.textContent = String(summary.passed)
        if (warningEl) warningEl.textContent = String(data.filter((r: any) => r.accuracy_class === 'warning').length + data.filter((r: any) => r.accuracy_class === 'pending').length)
        if (failedEl) failedEl.textContent = String(summary.failed)

        // Render table
        // VULN-002 FIX (security review 2026-08-03): block/parcel numbers and
        // statuses are user-entered — build the table with createElement +
        // textContent, never innerHTML (stored-XSS guard).
        const tableEl = document.getElementById('traverse-table')
        if (tableEl && data.length > 0) {
          tableEl.replaceChildren()

          const table = document.createElement('table')
          table.className = 'w-full text-sm'

          const thead = document.createElement('thead')
          const headRow = document.createElement('tr')
          headRow.className = 'text-left text-gray-400 border-b border-gray-700'
          for (const header of ['Block', 'Parcel', 'Order', 'Precision', 'Area (ha)', 'Status']) {
            const th = document.createElement('th')
            th.className = 'pb-2'
            th.textContent = header
            headRow.append(th)
          }
          thead.append(headRow)
          table.append(thead)

          const tbody = document.createElement('tbody')
          const colorMap: Record<string, string> = { pass: 'text-green-400', warning: 'text-yellow-400', fail: 'text-red-400', pending: 'text-gray-500' }
          for (const r of data) {
            const color = colorMap[r.accuracy_class] || 'text-gray-500'
            const tr = document.createElement('tr')
            tr.className = 'border-b border-gray-800'

            const td = (text: string, cls: string) => {
              const cell = document.createElement('td')
              cell.className = cls
              cell.textContent = text
              return cell
            }

            tr.append(td(String(r.block_number ?? ''), 'py-2 text-white'))
            tr.append(td(String(r.parcel_number ?? ''), 'py-2 text-white'))
            tr.append(td(String(r.accuracy_order || 'Not computed'), `py-2 ${color} font-medium`))
            tr.append(td(r.precision_ratio ? '1:' + Number(r.precision_ratio).toLocaleString() : '-', 'py-2 text-gray-300'))
            tr.append(td(r.computed_area_ha ? Number(r.computed_area_ha).toFixed(4) : '-', 'py-2 text-gray-300'))

            const statusTd = document.createElement('td')
            statusTd.className = 'py-2'
            const badge = document.createElement('span')
            badge.className = `px-2 py-1 rounded text-xs ${
              r.status === 'computed' ? 'bg-green-900 text-green-300'
                : r.status === 'draft' ? 'bg-gray-700 text-gray-300'
                  : 'bg-blue-900 text-blue-300'
            }`
            badge.textContent = String(r.status || 'draft')
            statusTd.append(badge)
            tr.append(statusTd)

            tbody.append(tr)
          }
          table.append(tbody)
          tableEl.append(table)
        } else if (tableEl) {
          tableEl.replaceChildren()
          const p = document.createElement('p')
          p.className = 'text-gray-500 text-sm'
          p.textContent = 'No traverses computed yet'
          tableEl.append(p)
        }
      })
      .catch(() => {
        const tableEl = document.getElementById('traverse-table')
        if (tableEl) {
          tableEl.replaceChildren()
          const p = document.createElement('p')
          p.className = 'text-red-400 text-sm'
          p.textContent = 'Failed to load traverse summary'
          tableEl.append(p)
        }
      })
  }, [project?.id])

  if (loading) {
    return (
      <div className="min-h-[calc(100vh-8rem)] bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="flex items-center gap-3 text-[var(--text-muted)]">
          <svg className="w-6 h-6 animate-spin" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
          </svg>
          Loading scheme workspace...
        </div>
      </div>
    )
  }

  if (error && !project) {
    return (
      <div className="min-h-[calc(100vh-8rem)] bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="text-center space-y-3">
          <AlertCircle className="w-10 h-10 text-red-400 mx-auto" />
          <p className="text-[var(--text-secondary)]">{error}</p>
          <Link href="/dashboard" className="text-sm text-[var(--accent)] hover:underline">Back to Dashboard</Link>
        </div>
      </div>
    )
  }

  const totalParcels = Object.values(parcelCounts).reduce((a, b) => a + b, 0)

  return (
    <div className="min-h-[calc(100vh-8rem)] bg-[var(--bg-primary)]">
      <main className="max-w-6xl mx-auto px-4 py-8">
        <div className="mb-4">
          <MobileDesktopNotice>
            Scheme workspaces include block tables, parcel status review, batch deed plan ZIPs, and submission packages. Use mobile for monitoring; use desktop for final generation and review.
          </MobileDesktopNotice>
        </div>
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-[var(--text-muted)] mb-6">
          <Link href="/dashboard" className="hover:text-[var(--accent)] transition-colors">Dashboard</Link>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
          <span className="text-[var(--text-primary)]">{project?.name || 'Scheme Project'}</span>
        </div>

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4 mb-8">
          <div>
            <div className="flex items-center gap-3 mb-1">
              <h1 className="text-2xl font-bold text-[var(--text-primary)]">{project?.name}</h1>
              <span className="px-2.5 py-0.5 bg-orange-500/10 border border-orange-500/30 text-orange-400 text-xs font-medium rounded-full">
                Scheme
              </span>
            </div>
            {project?.location && (
              <p className="text-sm text-[var(--text-secondary)]">{project.location}</p>
            )}
            <div className="flex items-center gap-4 mt-2 text-xs text-[var(--text-muted)]">
              <span className="flex items-center gap-1">
                <LayoutGrid className="w-3 h-3" />
                {blocks.length} block{blocks.length !== 1 ? 's' : ''}
              </span>
              <span className="flex items-center gap-1">
                <BarChart3 className="w-3 h-3" />
                {totalParcels} parcel{totalParcels !== 1 ? 's' : ''}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Link
              href={`/project/${projectId}/scheme/blocks`}
              className="px-4 py-2 text-sm bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg transition-all flex items-center gap-2"
            >
              <Plus className="w-4 h-4" />
              Manage Blocks
            </Link>
            <Link
              href={`/project/${projectId}/scheme/map`}
              className="inline-flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg text-sm font-medium transition-colors"
            >
              <Map className="w-4 h-4" />
              View Scheme Map
            </Link>
            <Link
              href={`/project/${projectId}/scheme/team`}
              className="inline-flex items-center gap-2 px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-sm font-medium transition-colors"
            >
              <Users className="w-4 h-4" />
              Team & Workflow
            </Link>
            {totalParcels > 0 && (
              <div className="flex items-center gap-2">
                <a
                  href={`/api/scheme/batch?project_id=${projectId}`}
                  className="px-3 py-2 text-sm border border-[var(--border-color)] rounded-lg text-[var(--text-secondary)] hover:bg-[var(--bg-secondary)] transition-colors flex items-center gap-2"
                  title="Download all deed plans as ZIP"
                >
                  <FolderArchive className="w-4 h-4" />
                  Batch Deed Plans
                </a>
                <a
                  href={`/api/scheme/rim?project_id=${projectId}`}
                  target="_blank"
                  className="px-3 py-2 text-sm border border-orange-500/30 text-orange-400 rounded-lg hover:bg-orange-500/5 transition-colors flex items-center gap-2"
                  title="Download Registry Index Map"
                >
                  <Download className="w-4 h-4" />
                  RIM
                </a>
                <a
                  href={`/api/scheme/submission?project_id=${projectId}`}
                  className="px-3 py-2 text-sm bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 rounded-lg hover:bg-emerald-500/20 transition-colors flex items-center gap-2"
                  title="Download complete submission package (ZIP with all deed plans, forms, RIM, summary)"
                >
                  <Package className="w-4 h-4" />
                  Full Submission
                </a>
              </div>
            )}
          </div>
        </div>

        {/* Stats Row */}
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3 mb-8">
          <StatCard
            label="Blocks"
            value={String(blocks.length)}
            icon={<LayoutGrid className="w-4 h-4" />}
            color="text-blue-400"
          />
          <StatCard
            label="Total Parcels"
            value={String(totalParcels)}
            icon={<BarChart3 className="w-4 h-4" />}
            color="text-[var(--accent)]"
          />
          {(Object.entries(PARCEL_STATUS_LABELS) as [ParcelStatus, string][]).map(([status, label]) => {
            if (parcelCounts[status] === 0) return null
            return (
              <StatCard
                key={status}
                label={label}
                value={String(parcelCounts[status])}
                icon={<CheckCircle2 className="w-4 h-4" />}
                color={status === 'approved' ? 'text-emerald-400' : status === 'submitted' ? 'text-purple-400' : status === 'plan_generated' ? 'text-green-400' : status === 'computed' ? 'text-yellow-400' : 'text-[var(--text-secondary)]'}
              />
            )
          })}
        </div>

        {/* Error Banner */}
        {error && (
          <div className="mb-6 p-3.5 bg-red-900/20 border border-red-500/30 rounded-lg text-sm text-red-400 flex items-center gap-2">
            <AlertCircle className="w-5 h-5 shrink-0" />
            {error}
          </div>
        )}

        {/* Traverse Accuracy Summary */}
        {blocks.length > 0 && (
          <div className="mt-6 bg-gray-900 border border-gray-800 rounded-xl p-6">
            <h3 className="text-lg font-semibold text-white mb-4">Traverse Accuracy Summary</h3>
            <div id="traverse-summary" className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="bg-gray-800 rounded-lg p-4 text-center">
                <div className="text-2xl font-bold text-blue-400" id="summary-total">--</div>
                <div className="text-sm text-gray-400">Total Parcels</div>
              </div>
              <div className="bg-gray-800 rounded-lg p-4 text-center">
                <div className="text-2xl font-bold text-green-400" id="summary-passed">--</div>
                <div className="text-sm text-gray-400">Passed</div>
              </div>
              <div className="bg-gray-800 rounded-lg p-4 text-center">
                <div className="text-2xl font-bold text-yellow-400" id="summary-warning">--</div>
                <div className="text-sm text-gray-400">Review Needed</div>
              </div>
              <div className="bg-gray-800 rounded-lg p-4 text-center">
                <div className="text-2xl font-bold text-red-400" id="summary-failed">--</div>
                <div className="text-sm text-gray-400">Failed</div>
              </div>
            </div>
            <div id="traverse-table" className="mt-4 overflow-x-auto">
              <p className="text-gray-500 text-sm">Loading traverse summary...</p>
            </div>
          </div>
        )}

        {/* Blocks Table */}
        <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] overflow-hidden">
          <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--border-color)]">
            <h2 className="text-sm font-semibold text-[var(--text-primary)] flex items-center gap-2">
              <LayoutGrid className="w-4 h-4 text-orange-400" />
              Blocks
            </h2>
            {blocks.length === 0 ? (
              <Link
                href={`/project/${projectId}/scheme/blocks`}
                className="text-xs text-[var(--accent)] hover:underline flex items-center gap-1"
              >
                <Plus className="w-3 h-3" />
                Add First Block
              </Link>
            ) : (
              <Link
                href={`/project/${projectId}/scheme/blocks`}
                className="text-xs text-[var(--accent)] hover:underline"
              >
                Manage All
              </Link>
            )}
          </div>

          {blocks.length === 0 ? (
            <div className="px-5 py-12 text-center">
              <LayoutGrid className="w-10 h-10 text-[var(--text-muted)] mx-auto mb-3 opacity-30" />
              <p className="text-sm text-[var(--text-secondary)] mb-1">No blocks created yet</p>
              <p className="text-xs text-[var(--text-muted)] mb-4">
                Blocks group parcels together. Start by creating your first block.
              </p>
              <Link
                href={`/project/${projectId}/scheme/blocks`}
                className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black text-sm font-semibold rounded-lg transition-all"
              >
                <Plus className="w-4 h-4" />
                Create Block
              </Link>
            </div>
          ) : (
            <>
            {/* Mobile card view */}
            <div className="md:hidden space-y-3">
              {blocks.map((block) => {
                const progress = block.parcel_count > 0
                  ? Math.round((block.completed_count / block.parcel_count) * 100)
                  : 0
                return (
                  <div key={block.id} className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-3">
                    <div className="flex items-center justify-between mb-2">
                      <span className="font-mono text-[var(--accent)] text-sm font-bold">{block.block_number}</span>
                      <span className="text-xs text-[var(--text-muted)]">{block.parcel_count} parcels</span>
                    </div>
                    <div className="text-sm text-[var(--text-primary)] mb-2">{block.block_name || '—'}</div>
                    <div className="flex items-center gap-2">
                      <div className="flex-1 h-1.5 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
                        <div className="h-full bg-emerald-400 rounded-full" style={{ width: `${progress}%` }} />
                      </div>
                      <span className="text-xs text-[var(--text-muted)] tabular-nums">{progress}%</span>
                    </div>
                    <div className="mt-2 flex gap-2">
                      <Link href={`/project/${projectId}/scheme/blocks/${block.id}`} className="text-xs text-[var(--accent)] hover:underline">Open →</Link>
                      <Link href={`/project/${projectId}/scheme/blocks`} className="text-xs text-[var(--text-muted)] hover:underline">All blocks</Link>
                    </div>
                  </div>
                )
              })}
            </div>

            {/* Desktop table view */}
            <div className="hidden md:block overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-[var(--text-muted)] border-b border-[var(--border-color)]">
                    <th className="px-5 py-3 font-medium">Block</th>
                    <th className="px-5 py-3 font-medium">Name</th>
                    <th className="px-5 py-3 font-medium">Parcels</th>
                    <th className="px-5 py-3 font-medium">Progress</th>
                    <th className="px-5 py-3 font-medium text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {blocks.map((block) => {
                    const progress = block.parcel_count > 0
                      ? Math.round((block.completed_count / block.parcel_count) * 100)
                      : 0

                    return (
                      <tr key={block.id} className="border-b border-[var(--border-color)]/50 hover:bg-[var(--bg-secondary)] transition-colors">
                        <td className="px-5 py-3 font-mono text-[var(--accent)]">{block.block_number}</td>
                        <td className="px-5 py-3 text-[var(--text-primary)]">{block.block_name || '—'}</td>
                        <td className="px-5 py-3 text-[var(--text-secondary)]">{block.parcel_count}</td>
                        <td className="px-5 py-3">
                          <div className="flex items-center gap-2">
                            <div className="w-16 h-1.5 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
                              <div
                                className="h-full bg-emerald-400 rounded-full transition-all"
                                style={{ width: `${progress}%` }}
                              />
                            </div>
                            <span className="text-xs text-[var(--text-muted)]">{progress}%</span>
                          </div>
                        </td>
                        <td className="px-5 py-3 text-right">
                          <Link
                            href={`/project/${projectId}/scheme/blocks/${block.id}`}
                            className="text-xs text-[var(--accent)] hover:underline"
                          >
                            Manage Parcels
                          </Link>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
            </>
          )}
        </div>
      </main>
    </div>
  )
}

function StatCard({ label, value, icon, color }: {
  label: string
  value: string
  icon: React.ReactNode
  color: string
}) {
  return (
    <div className="bg-[var(--bg-card)] rounded-lg border border-[var(--border-color)] p-4">
      <div className="flex items-center gap-2 mb-2">
        <span className={color}>{icon}</span>
        <span className="text-xs text-[var(--text-muted)]">{label}</span>
      </div>
      <p className="text-xl font-bold text-[var(--text-primary)]">{value}</p>
    </div>
  )
}

'use client';

import { useEffect, useState, useCallback } from 'react'
import { useParams } from 'next/navigation'
import {
  Users, ArrowLeft, Loader2, XCircle, UserPlus
} from 'lucide-react'
import { z } from 'zod'
import { apiGet, apiPost, apiDelete, apiInvalidate, ApiError } from '@/lib/api/client'

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

const blockStatsSchema = z.object({
  total_parcels: z.number(),
  approved: z.number(),
  in_progress: z.number(),
  pending: z.number(),
}).passthrough()

const teamMemberSchema = z.object({
  user: z.object({
    id: z.union([z.string(), z.number()]),
    email: z.string(),
    full_name: z.string(),
    role: z.string(),
  }).passthrough(),
  blocks: z.array(z.object({
    block_id: z.union([z.string(), z.number()]),
    block_number: z.string(),
    block_name: z.string().nullable(),
    assigned_at: z.string(),
    stats: blockStatsSchema,
  }).passthrough()),
}).passthrough()

const unassignedBlockSchema = z.object({
  id: z.union([z.string(), z.number()]),
  block_number: z.string(),
  block_name: z.string().nullable(),
  stats: blockStatsSchema,
}).passthrough()

const teamResponseSchema = z.object({
  data: z.object({
    owner: z.any().nullable(),
    team: z.array(teamMemberSchema),
    unassigned_blocks: z.array(unassignedBlockSchema),
  }).passthrough(),
}).passthrough()

const statusResponseSchema = z.object({
  data: z.object({
    current_status: z.string(),
  }).passthrough(),
}).passthrough()

const activityResponseSchema = z.object({
  data: z.array(z.any()),
}).passthrough()

const assignMutationSchema = z.object({ ok: z.boolean().optional() }).passthrough()

interface TeamMember {
  user: { id: string; email: string; full_name: string; role: string }
  blocks: {
    block_id: string
    block_number: string
    block_name: string | null
    assigned_at: string
    stats: { total_parcels: number; approved: number; in_progress: number; pending: number }
  }[]
}

interface UnassignedBlock {
  id: string
  block_number: string
  block_name: string | null
  stats: { total_parcels: number; approved: number; in_progress: number; pending: number }
}

export default function TeamPage() {
  const params = useParams()
  const projectId = params.id as string
  const [team, setTeam] = useState<TeamMember[]>([])
  const [unassignedBlocks, setUnassignedBlocks] = useState<UnassignedBlock[]>([])
  const [owner, setOwner] = useState<any>(null)
  const [schemeStatus, setSchemeStatus] = useState('')
  const [loading, setLoading] = useState(true)
  const [assigning, setAssigning] = useState<string | null>(null)
  const [activityLog, setActivityLog] = useState<any[]>([])
  const [showActivity, setShowActivity] = useState(false)
  const [fetchError, setFetchError] = useState('')

  const fetchTeam = useCallback(async () => {
    try {
      const result = await apiGet(
        `/api/scheme/team?project_id=${projectId}`,
        teamResponseSchema,
        { ttlMs: 0 },
      )
      setOwner(result.data.owner)
      setTeam(result.data.team as unknown as TeamMember[])
      setUnassignedBlocks(result.data.unassigned_blocks as unknown as UnassignedBlock[])
    } catch (err) {
      if (err instanceof ApiError && err.isUnauthorized) {
        setFetchError('You must be signed in to view this team.')
      } else {
        setFetchError(err instanceof Error ? err.message : 'Failed to load team')
      }
    }
  }, [projectId])

  const fetchStatus = useCallback(async () => {
    try {
      const result = await apiGet(
        `/api/scheme/status?project_id=${projectId}`,
        statusResponseSchema,
        { ttlMs: 0 },
      )
      setSchemeStatus(result.data.current_status)
    } catch {
      // Non-fatal — status badge just stays empty
    }
  }, [projectId])

  const fetchActivity = useCallback(async () => {
    try {
      const result = await apiGet(
        `/api/scheme/activity?project_id=${projectId}`,
        activityResponseSchema,
        { ttlMs: 0 },
      )
      setActivityLog(result.data.slice(0, 20))
    } catch {
      // Non-fatal — activity log just stays empty
    }
  }, [projectId])

  useEffect(() => {
    Promise.all([fetchTeam(), fetchStatus(), fetchActivity()])
      .finally(() => setLoading(false))
  }, [fetchTeam, fetchStatus, fetchActivity])

  const handleAssign = async (blockId: string, surveyorId: string) => {
    setAssigning(blockId)
    try {
      await apiPost(
        '/api/scheme/assign',
        assignMutationSchema,
        { project_id: projectId, block_id: blockId, assigned_to: surveyorId },
      )
      apiInvalidate(`/api/scheme/team?project_id=${projectId}`)
      apiInvalidate(`/api/scheme/activity?project_id=${projectId}`)
      await fetchTeam()
      await fetchActivity()
    } catch (err) {
      setFetchError(err instanceof ApiError ? err.message : 'Failed to assign block')
    } finally {
      setAssigning(null)
    }
  }

  const handleUnassign = async (blockId: string) => {
    setAssigning(blockId)
    try {
      await apiDelete(`/api/scheme/assign?block_id=${blockId}`)
      apiInvalidate(`/api/scheme/team?project_id=${projectId}`)
      apiInvalidate(`/api/scheme/activity?project_id=${projectId}`)
      await fetchTeam()
      await fetchActivity()
    } catch (err) {
      setFetchError(err instanceof ApiError ? err.message : 'Failed to unassign block')
    } finally {
      setAssigning(null)
    }
  }

  const statusColors: Record<string, string> = {
    planning: 'bg-gray-600',
    in_progress: 'bg-blue-600',
    review: 'bg-yellow-600',
    approved: 'bg-green-600',
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center text-gray-400">
        <Loader2 className="w-6 h-6 animate-spin mr-2" />
        Loading team data...
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-950 text-white">
      <main className="max-w-6xl mx-auto px-4 py-8">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-gray-500 mb-6">
          <a href={`/project/${projectId}/scheme`} className="hover:text-gray-300 transition-colors">
            Scheme
          </a>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
          <span className="text-gray-300">Team & Workflow</span>
        </div>

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <Users className="w-6 h-6 text-purple-400" />
              Team & Workflow
            </h1>
            <p className="text-sm text-gray-400 mt-1">Manage surveyor assignments and scheme status</p>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-sm text-gray-400">Scheme Status:</span>
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${statusColors[schemeStatus] || 'bg-gray-600'}`}>
              {schemeStatus.replace('_', ' ').toUpperCase()}
            </span>
            <button
              onClick={() => setShowActivity(!showActivity)}
              className="px-4 py-2 bg-gray-800 hover:bg-gray-700 text-sm rounded-lg transition-colors border border-gray-700"
            >
              {showActivity ? 'Hide Activity' : 'Show Activity'}
            </button>
          </div>
        </div>

        {/* Error Banner */}
        {fetchError && (
          <div className="mb-6 p-3.5 bg-red-900/20 border border-red-500/30 rounded-lg text-sm text-red-400 flex items-center gap-2">
            <XCircle className="w-5 h-5 shrink-0" />
            {fetchError}
            <button onClick={() => setFetchError('')} className="ml-auto text-red-400/70 hover:text-red-300">
              <XCircle className="w-4 h-4" />
            </button>
          </div>
        )}

        {/* Activity Log */}
        {showActivity && (
          <div className="mb-6 bg-gray-900 border border-gray-800 rounded-xl p-4 max-h-64 overflow-y-auto">
            <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Recent Activity</h3>
            {activityLog.length === 0 ? (
              <p className="text-gray-600 text-sm">No activity yet</p>
            ) : (
              <div className="space-y-2">
                {activityLog.map((a: any, i: number) => (
                  <div key={`item-${i}`} className="flex items-start gap-3 text-sm">
                    <span className="text-gray-600 whitespace-nowrap text-xs">
                      {new Date(a.created_at).toLocaleString()}
                    </span>
                    <span className="text-gray-300">{a.action.replace(/_/g, ' ')}</span>
                    <span className="text-gray-600 text-xs">by {a.user_name || a.user_email || 'user'}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Owner Card */}
        <div className="mb-6 bg-gray-900 border border-gray-800 rounded-xl p-4">
          <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Project Owner</h3>
          {owner && (
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center text-lg font-bold">
                {owner.full_name?.[0]?.toUpperCase() || '?'}
              </div>
              <div>
                <div className="font-medium">{owner.full_name}</div>
                <div className="text-sm text-gray-400">{owner.email}</div>
              </div>
            </div>
          )}
        </div>

        {/* Two Column Layout */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Team Members */}
          <div>
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              Assigned Surveyors
              <span className="text-sm font-normal text-gray-500">({team.length})</span>
            </h3>
            {team.length === 0 ? (
              <div className="bg-gray-900 border border-gray-800 rounded-xl p-8 text-center">
                <Users className="w-8 h-8 text-gray-700 mx-auto mb-3" />
                <p className="text-gray-500 text-sm">No surveyors assigned yet.</p>
                <p className="text-gray-600 text-xs mt-1">Assign blocks from the panel on the right.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {team.map((member, idx) => (
                  <div key={`${member}-${idx}`} className="bg-gray-900 border border-gray-800 rounded-xl p-4">
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-green-600 rounded-full flex items-center justify-center text-sm font-bold">
                          {member.user.full_name?.[0]?.toUpperCase() || '?'}
                        </div>
                        <div>
                          <div className="font-medium text-sm">{member.user.full_name}</div>
                          <div className="text-xs text-gray-500">{member.user.email}</div>
                        </div>
                      </div>
                      <span className="text-xs bg-gray-800 px-2 py-1 rounded border border-gray-700">
                        {member.blocks.length} block{member.blocks.length !== 1 ? 's' : ''}
                      </span>
                    </div>
                    <div className="space-y-2">
                      {member.blocks.map((block) => (
                        <div key={block.block_id} className="flex items-center justify-between bg-gray-800/50 rounded-lg px-3 py-2 border border-gray-700/50">
                          <div>
                            <span className="text-sm font-medium text-gray-200">Block {block.block_number}</span>
                            {block.block_name && (
                              <span className="text-xs text-gray-500 ml-2">{block.block_name}</span>
                            )}
                            <div className="text-xs text-gray-500 mt-0.5">
                              {block.stats.total_parcels} parcels &mdash;{' '}
                              <span className="text-green-400">{block.stats.approved} approved</span>,{' '}
                              <span className="text-yellow-400">{block.stats.in_progress} in progress</span>,{' '}
                              <span className="text-gray-400">{block.stats.pending} pending</span>
                            </div>
                          </div>
                          <button
                            onClick={() => handleUnassign(block.block_id)}
                            disabled={assigning === block.block_id}
                            className="flex items-center gap-1 text-xs text-red-400 hover:text-red-300 transition-colors disabled:opacity-50"
                          >
                            {assigning === block.block_id ? (
                              <Loader2 className="w-3 h-3 animate-spin" />
                            ) : (
                              <XCircle className="w-3.5 h-3.5" />
                            )}
                            {assigning === block.block_id ? '' : 'Remove'}
                          </button>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Unassigned Blocks */}
          <div>
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              Unassigned Blocks
              <span className="text-sm font-normal text-gray-500">({unassignedBlocks.length})</span>
            </h3>
            {unassignedBlocks.length === 0 ? (
              <div className="bg-gray-900 border border-green-800/30 rounded-xl p-8 text-center">
                <span className="text-green-400 text-sm">All blocks are assigned!</span>
              </div>
            ) : (
              <div className="space-y-2">
                {unassignedBlocks.map((block) => (
                  <div key={block.id} className="bg-gray-900 border border-gray-800 rounded-xl p-4">
                    <div className="flex items-center justify-between mb-3">
                      <div>
                        <span className="font-medium text-gray-200">Block {block.block_number}</span>
                        {block.block_name && (
                          <span className="text-sm text-gray-500 ml-2">{block.block_name}</span>
                        )}
                      </div>
                      <span className="text-xs text-gray-500">
                        {block.stats.total_parcels} parcel{block.stats.total_parcels !== 1 ? 's' : ''}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      {team.length > 0 ? (
                        team.map((member, idx) => (
                          <button
                            key={`${member}-${idx}`}
                            onClick={() => handleAssign(block.id, member.user.id)}
                            disabled={assigning === block.id}
                            className="flex-1 flex items-center justify-center gap-1 text-xs px-3 py-1.5 bg-blue-600 hover:bg-blue-500 disabled:bg-gray-700 disabled:text-gray-500 rounded-lg transition-colors truncate"
                            title={`Assign to ${member.user.full_name}`}
                          >
                            {assigning === block.id ? (
                              <Loader2 className="w-3 h-3 animate-spin" />
                            ) : (
                              <UserPlus className="w-3 h-3" />
                            )}
                            {member.user.full_name.split(' ')[0]}
                          </button>
                        ))
                      ) : (
                        <p className="text-xs text-gray-600">No team members to assign</p>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Back link */}
        <div className="mt-8 pt-6 border-t border-gray-800">
          <a
            href={`/project/${projectId}/scheme`}
            className="inline-flex items-center gap-2 text-sm text-gray-400 hover:text-gray-200 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            Back to Scheme Overview
          </a>
        </div>
      </main>
    </div>
  )
}

'use client';

import { useState, useCallback, useEffect } from 'react';
import { CheckCircle2 } from 'lucide-react'
import { z } from 'zod';
import { createClient } from '@/lib/api-client/client';
import { apiGet, apiPost, apiInvalidate, ApiError } from '@/lib/api/client';
import { DocumentStatus, ProjectDocument } from '@/types/submission';
import { getDocumentsForSurveyType } from '@/lib/submission/submissionDocuments';
import { SurveyType } from '@/types/project';
import { SupportingDocUpload } from '@/components/submission/SupportingDocUpload';
import { FormNo4Preview } from '@/components/drawing/FormNo4Preview';
import { NLIMSExportPanel } from '@/components/submission/NLIMSExportPanel';
import { StatutoryGatePanel } from '@/components/validation/StatutoryGatePanel';

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

const previewSchema = z.object({
  submissionRef: z.string().optional(),
  projectId: z.string().optional(),
  surveyor: z.any().optional(),
  subtype: z.string().optional(),
  parcel: z.any().optional(),
  traverse: z.any().optional(),
  supportingDocs: z.array(z.any()).optional(),
  generatedAt: z.string().optional(),
  revision: z.number().optional(),
}).passthrough();

const generateResponseSchema = z.object({
  success: z.boolean().optional(),
  fileUrl: z.string().optional(),
  downloadUrl: z.string().optional(),
}).passthrough();

const packageResponseSchema = z.object({
  downloadUrl: z.string().optional(),
}).passthrough();

interface Props {
  project: { id: string; name: string; survey_type: string };
  existingDocs: ProjectDocument[];
  projectId: string;
}

interface DocState {
  id: string;
  status: DocumentStatus;
  progress: number;
  error?: string;
  fileUrl?: string;
  generatedAt?: string;
}

interface SubmissionPackage {
  submissionRef: string;
  projectId: string;
  surveyor: { registrationNumber: string; iskNumber: string; verifiedIsk: boolean; fullName: string; firmName: string; isKMemberActive: boolean };
  subtype: 'cadastral_subdivision' | 'cadastral_amalgamation' | 'cadastral_resurvey' | 'cadastral_mutation';
  parcel: { lrNumber: string; parcelNumber: string; county: string; division: string; district: string; locality: string; areaM2: number; perimeterM: number };
  traverse: {
    points: { pointName: string; easting: number; northing: number; adjustedEasting: number; adjustedNorthing: number; observedBearing: number; observedDistance: number }[];
    angularMisclosure: number;
    linearMisclosure: number;
    precisionRatio: string;
    closingErrorE: number;
    closingErrorN: number;
    adjustmentMethod: 'bowditch' | 'transit';
    areaM2: number;
    perimeterM: number;
  };
  supportingDocs: { type: 'ppa2' | 'lcb_consent' | 'mutation_form' | 'beacon_cert'; label: string; required: boolean; fileUrl: string | null; uploadedAt: string | null }[];
  generatedAt: string;
  revision: number;
}

export default function SubmissionClient({ project, existingDocs, projectId }: Props) {
  const dbClient = createClient();
  const [previewPkg, setPreviewPkg] = useState<SubmissionPackage | null>(null);
  // Statutory gate block state — when true, Generate buttons are disabled
  // because the project would fail ArdhiSasa pre-flight. Lifted up from
  // StatutoryGatePanel via the onResult callback.
  const [gateBlocked, setGateBlocked] = useState(false);
  const [docStates, setDocStates] = useState<Record<string, DocState>>(() => {
    const initial: Record<string, DocState> = {};
    getDocumentsForSurveyType(project.survey_type).forEach((doc) => {
      const existing = existingDocs.find((d) => d.document_id === doc.id);
      initial[doc.id] = {
        id: doc.id,
        status: existing?.status ?? 'pending',
        progress: existing?.status === 'ready' ? 100 : 0,
        fileUrl: existing?.file_url ?? undefined,
        generatedAt: existing?.generated_at ?? undefined,
      };
    });
    return initial;
  });

  const documents = getDocumentsForSurveyType(project.survey_type as SurveyType);
  const readyCount = Object.values(docStates).filter((d) => d.status === 'ready').length;
  const totalCount = documents.length;
  const progressPct = totalCount > 0 ? (readyCount / totalCount) * 100 : 0;

  const [assembling, setAssembling] = useState(false);
  const [packageResult, setPackageResult] = useState<{
    passed: boolean;
    ref: string;
    blockers: string[];
    warnings: string[];
  } | null>(null);

  useEffect(() => {
    async function loadPreview() {
      try {
        const pkg = await apiGet(
          `/api/submission/preview?projectId=${projectId}`,
          previewSchema,
          { ttlMs: 0 },
        );
        setPreviewPkg(pkg as unknown as SubmissionPackage);
      } catch (err) {
        // Preview is best-effort; surface non-auth errors to console only
        if (err instanceof ApiError && err.isUnauthorized) {
          console.error('Preview load: unauthorized');
        } else {
          console.error('Failed to load preview:', err);
        }
      }
    }
    loadPreview();
  }, [projectId]);

  const generateDocument = useCallback(async (docId: string) => {
    setDocStates((prev) => ({
      ...prev,
      [docId]: { ...prev[docId], status: 'generating', progress: 10, error: undefined },
    }));

    try {
      const doc = documents.find((d) => d.id === docId);
      if (!doc) throw new Error('Document not found');

      setDocStates((prev) => ({
        ...prev,
        [docId]: { ...prev[docId], progress: 30 },
      }));

      const result = await apiPost(
        '/api/submission/generate',
        generateResponseSchema,
        {
          projectId: project.id,
          documentId: docId,
          documentType: doc.id,
          format: doc.format,
        },
      );

      setDocStates((prev) => ({
        ...prev,
        [docId]: { ...prev[docId], progress: 70 },
      }));

      const downloadUrl = result.downloadUrl ?? result.fileUrl;

      await dbClient.from('submission_documents').upsert({
        project_id: project.id,
        document_id: docId,
        status: 'ready',
        file_url: downloadUrl,
        generated_at: new Date().toISOString(),
      }, { onConflict: 'project_id,document_id' });

      setDocStates((prev) => ({
        ...prev,
        [docId]: {
          ...prev[docId],
          status: 'ready',
          progress: 100,
          fileUrl: downloadUrl,
          generatedAt: new Date().toISOString(),
        },
      }));

      apiInvalidate(`/api/submission/preview?projectId=${project.id}`);
    } catch (err) {
      const errorMessage = err instanceof ApiError
        ? err.message
        : err instanceof Error
          ? err.message
          : 'Unknown error';
      setDocStates((prev) => ({
        ...prev,
        [docId]: {
          ...prev[docId],
          status: 'error',
          error: errorMessage,
        },
      }));
    }
  }, [documents, project.id, dbClient]);

  const retryDocument = useCallback((docId: string) => {
    generateDocument(docId);
  }, [generateDocument]);

  const downloadDocument = useCallback((docId: string) => {
    const doc = docStates[docId];
    if (doc?.fileUrl) {
      window.open(doc.fileUrl, '_blank');
    }
  }, [docStates]);

  const getStatusIcon = (status: DocumentStatus) => {
    switch (status) {
      case 'ready':
        return <CheckCircle2 className="w-3.5 h-3.5 inline shrink-0 text-green-500" />;
      case 'generating':
        return <span className="text-amber-500">⟳</span>;
      case 'error':
        return <span className="text-red-500">✕</span>;
      default:
        return <span className="text-zinc-400">…</span>;
    }
  };

  const getStatusLabel = (status: DocumentStatus) => {
    switch (status) {
      case 'ready':
        return 'Ready';
      case 'generating':
        return 'Generating...';
      case 'error':
        return 'Failed';
      default:
        return 'Pending';
    }
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-[var(--text-primary)]">{project.name}</h1>
        <p className="text-sm text-[var(--text-secondary)] mt-1">
          Submission Package —{' '}
          <span className="font-medium text-[var(--text-primary)]">{readyCount} of {totalCount}</span> documents ready
        </p>
        <div className="mt-3 h-2 bg-gray-800 rounded-full overflow-hidden">
          <div 
            className="h-full bg-green-500 transition-all duration-500" 
            style={{ width: `${progressPct}%` }} 
          />
        </div>
        {progressPct === 100 && (
          <p className="mt-2 text-sm text-green-400 font-medium">
             All documents ready for submission
          </p>
        )}
      </div>

      {/* Statutory Validation Gate — pre-export compliance check.
          Shows blocking violations before the surveyor hits Generate,
          so they can fix issues in the field book or traverse adjustment
          instead of getting a rejection at export time.
          onResult lifts the block state up so Generate buttons can be
          disabled client-side when the gate is blocked. */}
      <StatutoryGatePanel
        projectId={project.id}
        onResult={(result) => setGateBlocked(result ? result.summary.block > 0 : false)}
      />

      {documents.length === 0 ? (
        <p className="text-[var(--text-muted)] text-sm">
          No documents configured for survey type: {project.survey_type}
        </p>
      ) : (
        <div className="space-y-4">
          {documents.map((doc) => {
            const state: DocState = docStates[doc.id] ?? { id: doc.id, status: 'pending' as DocumentStatus, progress: 0 };
            const isGenerating = state.status === 'generating';
            const isReady = state.status === 'ready';
            const isError = state.status === 'error';

            return (
              <div
                key={doc.id}
                className={`border rounded-lg p-4 ${
                  isReady 
                    ? 'border-green-800/40 bg-green-950/20' 
                    : isError 
                      ? 'border-red-800/40 bg-red-950/20' 
                      : 'border-[var(--border-color)] bg-[var(--bg-secondary)]'
                }`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <span className="text-lg">{getStatusIcon(state.status)}</span>
                      <h3 className="font-semibold text-[var(--text-primary)]">{doc.label}</h3>
                      <span className={`text-xs px-2 py-0.5 rounded ${
                        isReady 
                          ? 'bg-green-900/40 text-green-400' 
                          : isError 
                            ? 'bg-red-900/40 text-red-400' 
                            : 'bg-gray-800 text-gray-400'
                      }`}>
                        {getStatusLabel(state.status)}
                      </span>
                    </div>
                    <p className="text-sm text-[var(--text-secondary)] mt-1">{doc.description}</p>
                    <p className="text-xs text-[var(--text-muted)] mt-1">
                      Format: {doc.format.toUpperCase()} | Required: {doc.requiredData.join(', ')}
                    </p>
                    
                    {isGenerating && (
                      <div className="mt-3">
                        <div className="flex items-center gap-2">
                          <div className="flex-1 h-2 bg-gray-800 rounded-full overflow-hidden">
                            <div 
                              className="h-full bg-blue-500 transition-all duration-300"
                              style={{ width: `${state.progress}%` }}
                            />
                          </div>
                          <span className="text-xs text-[var(--text-muted)]">{state.progress}%</span>
                        </div>
                      </div>
                    )}

                    {isError && state.error && (
                      <div className="mt-3 p-2 bg-red-900/30 border border-red-800/40 rounded text-sm text-red-400">
                        <strong>Error:</strong> {state.error}
                      </div>
                    )}

                    {isReady && state.generatedAt && (
                      <p className="mt-2 text-xs text-[var(--text-muted)]">
                        Generated: {new Date(state.generatedAt).toLocaleString()}
                      </p>
                    )}
                  </div>

                  <div className="ml-4 flex flex-col gap-2">
                    {!isReady && (
                      <button
                        onClick={() => generateDocument(doc.id)}
                        disabled={isGenerating || gateBlocked}
                        title={gateBlocked ? 'Statutory validation is blocking — fix violations and re-run validation first' : undefined}
                        className={`px-4 py-2 text-sm font-medium rounded transition ${
                          isGenerating || gateBlocked
                            ? 'bg-gray-800 text-gray-500 cursor-not-allowed'
                            : 'bg-blue-600 text-white hover:bg-blue-700'
                        }`}
                      >
                        {isGenerating ? 'Generating...' : gateBlocked ? 'Blocked' : 'Generate'}
                      </button>
                    )}

                    {isReady && (
                      <button
                        onClick={() => downloadDocument(doc.id)}
                        className="px-4 py-2 text-sm font-medium rounded bg-green-600 text-white hover:bg-green-700 transition"
                      >
                        Download
                      </button>
                    )}

                    {isError && (
                      <button
                        onClick={() => retryDocument(doc.id)}
                        className="px-4 py-2 text-sm font-medium rounded bg-red-600 text-white hover:bg-red-700 transition"
                      >
                        Retry
                      </button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {readyCount > 0 && readyCount < totalCount && (
        <div className="mt-8 p-4 bg-amber-950/20 border border-amber-800/40 rounded-lg">
          <h3 className="font-semibold text-amber-400">Submission Incomplete</h3>
          <p className="text-sm text-amber-300 mt-1">
            {totalCount - readyCount} document(s) still pending. Generate all remaining documents to complete your submission package.
          </p>
          <button
            onClick={() => {
              documents.forEach((doc) => {
                const state = docStates[doc.id];
                if (!state || state.status !== 'ready') {
                  generateDocument(doc.id);
                }
              });
            }}
            disabled={gateBlocked}
            title={gateBlocked ? 'Statutory validation is blocking — fix violations and re-run validation first' : undefined}
            className={`mt-3 px-4 py-2 text-white text-sm font-medium rounded transition ${
              gateBlocked
                ? 'bg-gray-700 cursor-not-allowed'
                : 'bg-amber-600 hover:bg-amber-700'
            }`}
          >
            {gateBlocked ? 'Blocked — fix violations first' : 'Generate All Missing'}
          </button>
        </div>
      )}

      {readyCount === totalCount && totalCount > 0 && (
        <div className="mt-8 p-4 bg-green-950/20 border border-green-800/40 rounded-lg">
          <h3 className="font-semibold text-green-400">Submission Package Complete</h3>
          <p className="text-sm text-green-300 mt-1">
            All {totalCount} documents are ready. You can now submit your survey package to the relevant authority.
          </p>
          <div className="mt-4 flex gap-3">
            <button
              onClick={async () => {
                try {
                  const result = await apiPost(
                    '/api/submission/package',
                    packageResponseSchema,
                    { projectId: project.id },
                  );
                  if (result.downloadUrl) {
                    window.open(result.downloadUrl, '_blank');
                  }
                } catch (err) {
                  if (err instanceof ApiError) {
                    console.error('Package download failed:', err.message);
                  } else {
                    console.error('Package download failed:', err);
                  }
                }
              }}
              className="px-4 py-2 bg-green-600 text-white text-sm font-medium rounded hover:bg-green-700 transition"
            >
              Download Full Package (ZIP)
            </button>
          </div>
        </div>
      )}

      <SupportingDocUpload projectId={project.id} />

      {previewPkg && (
        <div className="space-y-2">
          <h3 className="font-semibold text-lg">Form No. 4 Preview</h3>
          <p className="text-xs text-[var(--text-muted)]">
            Verify geometry before generating package. The DXF export matches this preview exactly.
          </p>
          <FormNo4Preview pkg={previewPkg} width={760} height={500} />
        </div>
      )}

      <div className="mt-8 p-4 border border-orange-800/40 bg-orange-950/20 rounded-lg">
        <h3 className="font-semibold text-orange-400">Generate Compliant Submission Package</h3>
        <p className="text-sm text-orange-300 mt-1">
          Generate a complete submission package with Form No. 4 DXF, computation workbook, and supporting documents.
        </p>
        <button
          onClick={async () => {
            setAssembling(true);
            try {
              // ponytail: binary download bypasses typed client (ZIP response with custom headers, not JSON)
              const res = await fetch('/api/submission/assemble', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ projectId: project.id })
              });

              if (!res.ok) {
                const err = await res.json();
                setPackageResult({
                  passed: false,
                  ref: '',
                  blockers: err.blockers ?? ['Unknown error'],
                  warnings: err.warnings ?? []
                });
                return;
              }

              const blob = await res.blob();
              const url = URL.createObjectURL(blob);
              const a = document.createElement('a');
              a.href = url;
              a.download = res.headers.get('X-Submission-Ref') + '.zip';
              a.click();
              URL.revokeObjectURL(url);

              setPackageResult({
                passed: true,
                ref: res.headers.get('X-Submission-Ref') ?? '',
                blockers: [],
                warnings: []
              });
            } catch (err) {
              setPackageResult({
                passed: false,
                ref: '',
                blockers: [err instanceof Error ? err.message : 'Unknown error'],
                warnings: []
              });
            } finally {
              setAssembling(false);
            }
          }}
          disabled={assembling}
          className="mt-4 px-4 py-2 bg-orange-500 hover:bg-orange-600 disabled:opacity-50 text-white font-semibold rounded transition"
        >
          {assembling ? 'Generating Package...' : 'Generate Submission Package'}
        </button>

        {packageResult && !packageResult.passed && (
          <div className="mt-4 p-3 bg-red-900/30 border border-red-800/40 rounded">
            <h4 className="font-medium text-red-400">QA Gate Failed</h4>
            <ul className="mt-2 text-sm text-red-300 list-disc list-inside">
              {packageResult.blockers.map((msg, i) => (
                <li key={`${msg}-${i}`}>{msg}</li>
              ))}
            </ul>
            {packageResult.warnings.length > 0 && (
              <div className="mt-2">
                <p className="text-sm text-amber-300">Warnings:</p>
                <ul className="text-sm text-amber-400 list-disc list-inside">
                  {packageResult.warnings.map((msg, i) => (
                    <li key={`${msg}-${i}`}>{msg}</li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}

        {packageResult?.passed && (
          <div className="mt-4 p-3 bg-green-900/30 border border-green-800/40 rounded">
            <p className="text-green-400 font-medium">
              Package generated: {packageResult.ref}
            </p>
            <p className="text-sm text-green-300 mt-1">
              Your submission ZIP has downloaded. Submit to the Director of Surveys office.
            </p>
          </div>
        )}
      </div>

      {/* NLIMS / ArdhiSasa Export Panel */}
      <NLIMSExportPanel projectId={project.id} />
    </div>
  );
}

'use client';

import { useCallback, useEffect, useState } from 'react'
import Link from 'next/link'
import { useParams } from 'next/navigation'
import dynamic from 'next/dynamic'
import { createClient } from '@/lib/api-client/client'
import { generateContours } from '@/lib/topo/contourGenerator'
import { runIDW as computeIDW } from '@/lib/topo/idwEngine'
import type { SpotHeight } from '@/components/drawing/TopoCanvas'
import type { ContourLine } from '@/lib/topo/contourGenerator'

const TopoCanvas = dynamic(() => import('@/components/drawing/TopoCanvas').then(m => ({ default: m.TopoCanvas })), {
  ssr: false,
  loading: () => <div className="animate-pulse bg-gray-200 rounded h-64" />,
})

const INTERVAL_OPTIONS = [0.25, 0.5, 1, 2, 5, 10]
const RESOLUTION_OPTIONS = [0.5, 1, 2, 5]

export default function TopoPage() {
  const { id } = useParams()
  const [dbClient] = useState(() => createClient())

  const [spotHeights, setSpotHeights] = useState<SpotHeight[]>([])
  const [contours, setContours] = useState<ContourLine[]>([])
  const [interval, setInterval] = useState(1)
  const [resolution, setResolution] = useState(1)
  const [status, setStatus] = useState<'idle' | 'loading' | 'computing' | 'done' | 'error'>('idle')
  const [progress, setProgress] = useState(0)
  const [pointCount, setPointCount] = useState(0)

  const loadSpotHeights = useCallback(async () => {
    setStatus('loading')

    const { data, error } = await dbClient
      .from('survey_points')
      .select('*')
      .eq('project_id', id)
      .eq('point_type', 'spot_height')
      .not('elevation', 'is', null)

    if (error || !data) {
      setStatus('error')
      return
    }

    const points: SpotHeight[] = data.map((point: any) => ({
      e: point.easting,
      n: point.northing,
      z: point.elevation,
      label: point.point_name ?? point.name ?? '',
    }))

    setSpotHeights(points)
    setPointCount(points.length)
    setStatus('idle')
  }, [id, dbClient])

  useEffect(() => {
    void loadSpotHeights()
  }, [loadSpotHeights])

  function handleCompute() {
    if (spotHeights.length < 3) return

    setStatus('computing')
    setProgress(0)
    setContours([])

    setTimeout(() => {
      try {
        const points = spotHeights.map(p => ({ x: p.e, y: p.n, z: p.z }))

        const minE = Math.min(...points.map(p => p.x))
        const maxE = Math.max(...points.map(p => p.x))
        const minN = Math.min(...points.map(p => p.y))
        const maxN = Math.max(...points.map(p => p.y))
        const cols = Math.ceil((maxE - minE) / resolution) + 1
        const rows = Math.ceil((maxN - minN) / resolution) + 1

        setProgress(20)

        const idwGrid = computeIDW(points, { power: 2, resolution: Math.max(cols, rows) })

        setProgress(80)

        const lines = generateContours(
          {
            grid: idwGrid.grid,
            gridMinE: idwGrid.minX,
            gridMinN: idwGrid.minY,
            gridResolution: idwGrid.cellSize,
            cols: idwGrid.cols,
            rows: idwGrid.rows,
          },
          { interval, indexInterval: 5 }
        )
        setContours(lines)
        setProgress(100)
        setStatus('done')
      } catch (err) {
        console.error('IDW error:', err)
        setStatus('error')
      }
    }, 0)
  }

  async function exportDXF() {
    // ponytail: binary download bypasses typed client
    const response = await fetch('/api/topo/export/dxf', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectId: id, contours, spotHeights }),
    })

    if (!response.ok) {
      return
    }

    const blob = await response.blob()
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = `topo_${id}.dxf`
    anchor.click()
  }

  async function exportGeoJSON() {
    const features = contours.flatMap((contour) =>
      contour.coordinates.map((ring) => ({
        type: 'Feature',
        properties: { elevation: contour.elevation, isIndex: contour.isIndex },
        geometry: { type: 'LineString', coordinates: ring.map(([e, n]) => [e, n]) },
      }))
    )

    const geojson = { type: 'FeatureCollection', features }
    const blob = new Blob([JSON.stringify(geojson, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = `contours_${id}.geojson`
    anchor.click()
  }

  async function exportShapefile() {
    // ponytail: binary download bypasses typed client
    const response = await fetch('/api/topo/export/shapefile', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ projectId: id, contours, spotHeights }),
    })

    if (!response.ok) {
      return
    }

    const blob = await response.blob()
    const url = URL.createObjectURL(blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = `contours_${id}.zip`
    anchor.click()
  }

  return (
    <div className="space-y-6 p-4">
      <div>
        <div className="flex items-center justify-between gap-4 flex-wrap">
          <div>
            <h2 className="text-xl font-bold">Topographic Map</h2>
            <p className="text-sm text-[var(--text-muted)]">{pointCount} spot heights loaded</p>
          </div>
          <Link
            href={`/project/${id}`}
            prefetch={false}
            className="text-sm text-orange-400 hover:text-orange-300"
          >
            Back to workspace
          </Link>
        </div>
      </div>

      <div className="flex flex-wrap gap-4 items-end">
        <div>
          <label className="text-xs text-[var(--text-muted)] block mb-1" htmlFor="contour-interval-m">Contour Interval (m)</label>
          <select id="contour-interval-m"
            value={interval}
            onChange={(event) => setInterval(Number(event.target.value))}
            className="bg-[var(--bg-secondary)] border rounded px-3 py-1.5 text-sm"
          >
            {INTERVAL_OPTIONS.map((value) => (
              <option key={value} value={value}>
                {value}m
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="text-xs text-[var(--text-muted)] block mb-1" htmlFor="grid-resolution-m">Grid Resolution (m)</label>
          <select
            value={resolution}
            onChange={(event) => setResolution(Number(event.target.value))}
            className="bg-[var(--bg-secondary)] border rounded px-3 py-1.5 text-sm"
          >
            {RESOLUTION_OPTIONS.map((value) => (
              <option key={value} value={value}>
                {value}m
              </option>
            ))}
          </select>
        </div>

        <button
          onClick={handleCompute}
          disabled={spotHeights.length < 3 || status === 'computing'}
          className="bg-orange-500 hover:bg-orange-600 disabled:opacity-50 text-white px-4 py-1.5 rounded text-sm font-medium"
        >
          {status === 'computing' ? `Computing... ${progress}%` : 'Generate Contours'}
        </button>

        {status === 'done' && (
          <span className="text-sm text-green-400">OK {contours.length} contour levels generated</span>
        )}
      </div>

      {status === 'computing' && (
        <div className="w-full bg-[var(--bg-secondary)] rounded-full h-1.5">
          <div
            className="bg-orange-500 h-1.5 rounded-full transition-all duration-200"
            style={{ width: `${progress}%` }}
          />
        </div>
      )}

      <TopoCanvas
        spotHeights={spotHeights}
        contours={contours}
        width={880}
        height={620}
        showLabels
        showSpotHeights
      />

      {status === 'done' && contours.length > 0 && (
        <div className="flex gap-3">
          <button
            onClick={exportDXF}
            className="border rounded px-4 py-2 text-sm hover:bg-[var(--bg-secondary)]"
          >
            Export DXF
          </button>
          <button
            onClick={exportGeoJSON}
            className="border rounded px-4 py-2 text-sm hover:bg-[var(--bg-secondary)]"
          >
            Export GeoJSON
          </button>
          <button
            onClick={exportShapefile}
            className="border rounded px-4 py-2 text-sm hover:bg-[var(--bg-secondary)]"
          >
            Export Shapefile
          </button>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { BoundarySelectorMap } from '@/components/project/BoundarySelectorMap'
import { getUTMZoneFromLatLng } from '@/lib/geodesy/utmZones'
import { useCountry, ALL_COUNTRIES } from '@/lib/country'
import type { SurveyingCountry } from '@/lib/country'
import { SURVEY_TYPE_LABELS, SurveyType } from '@/types/project'
import type { ProjectType } from '@/types/scheme'

export default function NewProjectPage() {
  const { country: defaultCountry, setCountry: setContextCountry } = useCountry()
  const router = useRouter()

  const [name, setName] = useState('')
  const [location, setLocation] = useState('')
  const [selectedCountry, setSelectedCountry] = useState<SurveyingCountry>(defaultCountry)
  const [utmZone, setUtmZone] = useState(() => {
    const c = ALL_COUNTRIES.find((c: any) => c.id === defaultCountry)
    return c?.id === 'us' ? '17' : c?.id === 'uk' ? '30' : c?.id === 'australia' ? '51' : '37'
  })
  const [hemisphere, setHemisphere] = useState<'N' | 'S'>('S')
  const [surveyType, setSurveyType] = useState<SurveyType>('topographic')
  const [clientName, setClientName] = useState('')
  const [surveyorName, setSurveyorName] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [detecting, setDetecting] = useState(false)
  
  const [polygonCoordinates, setPolygonCoordinates] = useState<number[][]>([])
  const [estimatedArea, setEstimatedArea] = useState<number | null>(null)

  // Phase 25: Project scale selector
  const [projectType, setProjectType] = useState<ProjectType>('small')
  const [schemeNumber, setSchemeNumber] = useState('')
  const [schemeCounty, setSchemeCounty] = useState('')
  const [schemeSubCounty, setSchemeSubCounty] = useState('')
  const [schemeWard, setSchemeWard] = useState('')
  const [plannedParcels, setPlannedParcels] = useState('')
  const [adjudicationSection, setAdjudicationSection] = useState('')

  const handleCountryChange = (newCountry: SurveyingCountry) => {
    setSelectedCountry(newCountry)
    const zoneMap: Partial<Record<SurveyingCountry, [string, 'N' | 'S']>> = {
      us: ['17', 'N'], uk: ['30', 'N'], australia: ['51', 'S'],
      new_zealand: ['59', 'S'], south_africa: ['35', 'S'],
      bahrain: ['39', 'N'], nigeria: ['31', 'N'], ghana: ['30', 'N'],
      tanzania: ['37', 'S'], uganda: ['36', 'N'], india: ['44', 'N'],
      indonesia: ['48', 'S'], brazil: ['23', 'S'],
      saudi_arabia: ['39', 'N'], oman: ['40', 'N'], uae: ['40', 'N'],
    }
    const [zone, hemi] = zoneMap[newCountry] || ['37', 'S']
    setUtmZone(zone)
    setHemisphere(hemi)
  }

  const detectZoneFromGPS = () => {
    if (!navigator.geolocation) { setError('GPS not supported'); return }
    setDetecting(true); setError('')
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { zone, hemisphere: hem, description } = getUTMZoneFromLatLng(pos.coords.latitude, pos.coords.longitude)
        setUtmZone(String(zone)); setHemisphere(hem as 'N' | 'S')
        setDetecting(false)
        setError(`Detected: Zone ${zone}${hem} — ${description}`)
        setTimeout(() => setError(''), 5000)
      },
      () => { setDetecting(false); setError('Could not get location. Check GPS permissions.') }
    )
  }

  const datumLabels: Record<SurveyingCountry, string> = {
    kenya: 'ARC1960', uganda: 'ARC1960', tanzania: 'ARC1960',
    nigeria: 'Minna', ghana: 'Gold Coast 1920', south_africa: 'Hartebeesthoek94',
    bahrain: 'Ain Al-Abd 1970', saudi_arabia: 'IGM 1969', oman: 'OTM / GRS80',
    uae: 'NAD83(CSRS)', new_zealand: 'NZGD2000', us: 'NAD83(2011)',
    uk: 'OSGB36', australia: 'GDA2020', india: 'WGS84', indonesia: 'WGS84',
    brazil: 'WGS84', rwanda: 'ARC1960', burundi: 'ARC1960',
    south_sudan: 'ARC1960', zambia: 'ARC1960', other: 'WGS84',
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setLoading(true)

    try {
      const payload: Record<string, any> = {
        name,
        survey_type: surveyType,
        location,
        utm_zone: parseInt(utmZone) || 37,
        hemisphere,
        project_type: projectType,
        client_name: clientName || undefined,
        surveyor_name: surveyorName || undefined,
        country: selectedCountry,
        datum: datumLabels[selectedCountry],
        boundary: polygonCoordinates.length > 0 ? { type: 'Polygon', coordinates: [polygonCoordinates] } : undefined,
        area_sqm: estimatedArea || undefined,
      }

      if (projectType === 'scheme') {
        Object.assign(payload, {
          scheme_number: schemeNumber || undefined,
          county: schemeCounty || undefined,
          sub_county: schemeSubCounty || undefined,
          ward: schemeWard || undefined,
          planned_parcels: plannedParcels ? parseInt(plannedParcels) : undefined,
          adjudication_section: adjudicationSection || undefined,
        })
      }

      const res = await fetch('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      const json = await res.json()

      if (!res.ok) {
        setError(json.error || 'Failed to create project')
        setLoading(false)
        return
      }

      const project = json.data
      setContextCountry(selectedCountry)

      if (projectType === 'scheme') {
        router.push(`/project/${project.id}/scheme`)
      } else {
        router.push(`/project/${project.id}`)
      }
    } catch (err: unknown) {
      setError((err as Error).message || 'Network error — please try again')
      setLoading(false)
    }
  }

  const currentCountry = ALL_COUNTRIES.find((c: any) => c.id === selectedCountry)
  const inputClass = 'w-full px-4 py-3 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] placeholder-[var(--text-muted)] focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)] focus:outline-none transition-colors text-sm'
  const labelClass = 'block text-sm font-medium text-[var(--text-secondary)] mb-1.5'

  const kenyaCounties = [
    'Mombasa','Kilifi','Kwale','Lamu','Tana River','Taita Taveta',
    'Garissa','Wajir','Mandera','Marsabit','Isiolo','Meru',
    'Tharaka Nithi','Embu','Kitui','Machakos','Makueni','Nyandarua',
    'Nyeri','Kirinyaga','Muranga','Kiambu','Turkana','West Pokot',
    'Samburu','Trans Nzoia','Uasin Gishu','Elgeyo Marakwet','Nandi',
    'Baringo','Laikipia','Nakuru','Narok','Kajiado','Kericho',
    'Bomet','Kakamega','Vihiga','Bungoma','Busia','Siaya',
    'Kisumu','Homa Bay','Migori','Kisii','Nyamira','Nairobi',
  ]

  return (
    <div className="min-h-[calc(100vh-8rem)] bg-[var(--bg-primary)]">
      <main className="max-w-2xl mx-auto px-4 py-10">

        {/* Breadcrumb */}
        <div className="flex items-center gap-2 text-sm text-[var(--text-muted)] mb-6">
          <Link href="/dashboard" className="hover:text-[var(--accent)] transition-colors">Dashboard</Link>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
          <span className="text-[var(--text-primary)]">New Project</span>
        </div>

        <div className="mb-8">
          <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-1">Create New Project</h1>
          <p className="text-sm text-[var(--text-secondary)]">Set up your survey project parameters and coordinate system.</p>

          {/* 1-Click Survey Type Presets */}
          <div className="mt-4 p-4 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl">
            <span className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider block mb-2">⚡ 1-Click Survey Presets</span>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
              <button
                type="button"
                onClick={() => {
                  setSurveyType('cadastral')
                  setProjectType('scheme')
                  setName(name || 'Cadastral Parcel Subdivision')
                }}
                className="px-3 py-2 text-xs font-medium bg-cyan-500/10 text-cyan-400 border border-cyan-500/30 rounded-lg hover:bg-cyan-500/20 text-left transition"
              >
                📜 <strong>Cadastral Subdivision</strong>
                <span className="block text-[10px] opacity-70 mt-0.5">Cap 299, Beacon tables, Mutation export</span>
              </button>

              <button
                type="button"
                onClick={() => {
                  setSurveyType('engineering')
                  setProjectType('medium')
                  setName(name || 'Road Corridor Alignment')
                }}
                className="px-3 py-2 text-xs font-medium bg-amber-500/10 text-amber-400 border border-amber-500/30 rounded-lg hover:bg-amber-500/20 text-left transition"
              >
                🛣️ <strong>Road Engineering</strong>
                <span className="block text-[10px] opacity-70 mt-0.5">RDM 1.3 Curves, Cross-sections, Chainage</span>
              </button>

              <button
                type="button"
                onClick={() => {
                  setSurveyType('topographic')
                  setProjectType('small')
                  setName(name || 'Topographic Site Survey')
                }}
                className="px-3 py-2 text-xs font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/30 rounded-lg hover:bg-emerald-500/20 text-left transition"
              >
                ⛰️ <strong>Topographic Survey</strong>
                <span className="block text-[10px] opacity-70 mt-0.5">TIN Contours, Point cloud, DXF Plot</span>
              </button>
            </div>
          </div>
        </div>

        {/* Error / Info Banner */}
        {error && (
          <div className={`mb-6 p-3.5 border rounded-lg text-sm flex items-start gap-2 ${
            error.startsWith('Detected')
              ? 'bg-green-900/20 border-green-500/30 text-green-400'
              : 'bg-red-900/20 border-red-500/30 text-red-400'
          }`}>
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Project Scale Toggle */}
          <div>
            <div className={labelClass}>Project Scale <span className="text-[var(--accent)]">*</span></div>
            <div className="grid grid-cols-2 gap-0 rounded-lg border border-[var(--border-color)] overflow-hidden">
              <button type="button" onClick={() => setProjectType('small')}
                className={`py-3.5 px-4 text-sm font-medium transition-all flex flex-col items-center gap-1 ${
                  projectType === 'small'
                    ? 'bg-[var(--accent)] text-black'
                    : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)]'
                }`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m3.75 9v6m3-3H9m1.5-12H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z" />
                </svg>
                <span>Small Project</span>
                <span className="text-[10px] opacity-70">Individual parcel / site</span>
              </button>
              <button type="button" onClick={() => { setProjectType('scheme'); setSurveyType('cadastral') }}
                className={`py-3.5 px-4 text-sm font-medium transition-all flex flex-col items-center gap-1 ${
                  projectType === 'scheme'
                    ? 'bg-orange-500 text-white'
                    : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)]'
                }`}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6A2.25 2.25 0 016 3.75h2.25A2.25 2.25 0 0110.5 6v2.25a2.25 2.25 0 01-2.25 2.25H6a2.25 2.25 0 01-2.25-2.25V6zM3.75 15.75A2.25 2.25 0 016 13.5h2.25a2.25 2.25 0 012.25 2.25V18a2.25 2.25 0 01-2.25 2.25H6A2.25 2.25 0 013.75 18v-2.25zM13.5 6a2.25 2.25 0 012.25-2.25H18A2.25 2.25 0 0120.25 6v2.25A2.25 2.25 0 0118 10.5h-2.25a2.25 2.25 0 01-2.25-2.25V6zM13.5 15.75a2.25 2.25 0 012.25-2.25H18a2.25 2.25 0 012.25 2.25V18A2.25 2.25 0 0118 20.25h-2.25A2.25 2.25 0 0113.5 18v-2.25z" />
                </svg>
                <span>Scheme / Large Project</span>
                <span className="text-[10px] opacity-70">Subdivision, adjudication</span>
              </button>
            </div>
            {projectType === 'scheme' && (
              <p className="mt-2 text-xs text-orange-400">
                Scheme mode enables blocks, parcel management, batch deed plans, and Registry Index Maps.
              </p>
            )}
          </div>

          {/* Project Name */}
          <div>
            <label htmlFor="project-name" className={labelClass}>Project Name <span className="text-[var(--accent)]">*</span></label>
            <input id="project-name" type="text" value={name} onChange={e => setName(e.target.value)}
              className={inputClass} required
              placeholder={projectType === 'scheme' ? 'e.g., Mwavumbo Ward Cadastral Subdivision' : 'e.g., Karen Estate Boundary Survey'} />
          </div>

          {/* Interactive Boundary Selector */}
          <div>
            <div className={labelClass}>Project Boundary Map</div>
            <BoundarySelectorMap 
              className="w-full h-64 mb-2"
              onBoundaryChange={(coords, area, center) => {
                setPolygonCoordinates(coords)
                setEstimatedArea(area)
                // Auto-detect UTM zone from drawn center
                const { zone, hemisphere: hem } = getUTMZoneFromLatLng(center[1], center[0])
                setUtmZone(String(zone))
                setHemisphere(hem as 'N' | 'S')
              }}
            />
            {estimatedArea && (
              <p className="text-xs text-green-600 dark:text-green-400">
                Estimated Area: {(estimatedArea / 10000).toFixed(4)} Hectares ({(estimatedArea / 4046.86).toFixed(4)} Acres)
              </p>
            )}
          </div>

          {/* Location */}
          <div>
            <label htmlFor="project-location" className={labelClass}>Location / Description</label>
            <textarea id="project-location" value={location} onChange={e => setLocation(e.target.value)}
              className={`${inputClass} h-20 resize-none`}
              placeholder={projectType === 'scheme' ? 'e.g., Mariakani, Kilifi County' : 'e.g., Mombasa, along Diani Beach Road'} />
          </div>

          {/* Scheme-specific fields */}
          {projectType === 'scheme' && (
            <div className="p-5 bg-orange-500/5 border border-orange-500/20 rounded-xl space-y-4">
              <h3 className="text-sm font-semibold text-[var(--text-primary)]">Scheme Details</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label htmlFor="scheme-number" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Scheme Number</label>
                  <input id="scheme-number" type="text" value={schemeNumber} onChange={e => setSchemeNumber(e.target.value)}
                    className={inputClass} placeholder="e.g., CRS/MWK/001/2026" />
                </div>
                <div>
                  <label htmlFor="adjudication-section" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Adjudication Section</label>
                  <input id="adjudication-section" type="text" value={adjudicationSection} onChange={e => setAdjudicationSection(e.target.value)}
                    className={inputClass} placeholder="e.g., Mwavumbo Section" />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div>
                  <label htmlFor="scheme-county" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">County</label>
                  <select id="scheme-county" value={schemeCounty} onChange={e => setSchemeCounty(e.target.value)} className={inputClass}>
                    <option value="">Select county</option>
                    {kenyaCounties.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div>
                  <label htmlFor="scheme-sub-county" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Sub-County</label>
                  <input id="scheme-sub-county" type="text" value={schemeSubCounty} onChange={e => setSchemeSubCounty(e.target.value)}
                    className={inputClass} placeholder="e.g., Mariakani" />
                </div>
                <div>
                  <label htmlFor="scheme-ward" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Ward</label>
                  <input id="scheme-ward" type="text" value={schemeWard} onChange={e => setSchemeWard(e.target.value)}
                    className={inputClass} placeholder="e.g., Mwavumbo" />
                </div>
              </div>
              <div>
                <label htmlFor="planned-parcels" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Planned Parcels</label>
                <input id="planned-parcels" type="number" value={plannedParcels} onChange={e => setPlannedParcels(e.target.value)}
                  className={inputClass} min={1} placeholder="e.g., 250" />
              </div>
            </div>
          )}

          {/* UTM Zone */}
          <div>
            <label htmlFor="utm-zone" className={labelClass}>UTM Zone (1–60)</label>
            <div className="grid grid-cols-2 gap-4">
              <input id="utm-zone" type="number" value={utmZone} onChange={e => setUtmZone(e.target.value)}
                className={inputClass} min={1} max={60} required />
              <div className="flex rounded-lg border border-[var(--border-color)] overflow-hidden">
                {(['N', 'S'] as const).map(h => (
                  <button key={h} type="button" onClick={() => setHemisphere(h)}
                    className={`flex-1 py-3 text-sm font-medium transition-colors ${
                      hemisphere === h ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-secondary)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
                    }`}>
                    {h === 'N' ? <><span className="sm:hidden">N</span><span className="hidden sm:inline">N — Northern</span></> : <><span className="sm:hidden">S</span><span className="hidden sm:inline">S — Southern</span></>}
                  </button>
                ))}
              </div>
            </div>
            <button type="button" onClick={detectZoneFromGPS} disabled={detecting}
              className="mt-2 text-xs text-[var(--text-muted)] hover:text-[var(--accent)] flex items-center gap-1.5 transition-colors disabled:opacity-50">
              <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M15 10.5a3 3 0 11-6 0 3 3 0 016 0z" />
                <path strokeLinecap="round" strokeLinejoin="round" d="M19.5 10.5c0 7.142-7.5 11.25-7.5 11.25S4.5 17.642 4.5 10.5a7.5 7.5 0 1115 0z" />
              </svg>
              {detecting ? 'Detecting...' : 'Detect zone from GPS'}
            </button>
          </div>

          {/* Country */}
          <div>
            <label htmlFor="country" className={labelClass}>Country / Jurisdiction</label>
            <select id="country" value={selectedCountry} onChange={e => handleCountryChange(e.target.value as SurveyingCountry)} className={inputClass}>
              {ALL_COUNTRIES.map((c: any) => (
                <option key={c.id} value={c.id}>{c.flag} {c.name}</option>
              ))}
            </select>
            {currentCountry && (
              <div className="mt-2 p-3 bg-[var(--bg-tertiary)] rounded-lg border border-[var(--border-color)]/50 text-xs text-[var(--text-secondary)]">
                Datum: <span className="text-[var(--text-primary)]">{datumLabels[selectedCountry]}</span>
              </div>
            )}
          </div>

          {/* Survey Type */}
          <div>
            <label htmlFor="survey-type" className={labelClass}>Survey Type</label>
            <select id="survey-type" value={surveyType} onChange={e => setSurveyType(e.target.value as SurveyType)} className={inputClass}>
              {(Object.entries(SURVEY_TYPE_LABELS) as [SurveyType, string][]).map(([val, label]) => (
                <option key={val} value={val}>{label}</option>
              ))}
            </select>
          </div>

          {/* Client + Surveyor */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label htmlFor="client-name" className={labelClass}>Client Name</label>
              <input id="client-name" type="text" value={clientName} onChange={e => setClientName(e.target.value)}
                className={inputClass} placeholder="e.g., Kilifi County Government" />
            </div>
            <div>
              <label htmlFor="surveyor-name" className={labelClass}>Surveyor Name</label>
              <input id="surveyor-name" type="text" value={surveyorName} onChange={e => setSurveyorName(e.target.value)}
                className={inputClass} placeholder="Your name or company" />
            </div>
          </div>

          {/* Actions */}
          <div className="flex items-center gap-3 pt-4 border-t border-[var(--border-color)]">
            <Link href="/dashboard"
              className="px-5 py-2.5 text-sm text-[var(--text-secondary)] border border-[var(--border-color)] rounded-lg hover:border-[var(--border-hover)] transition-colors">
              Cancel
            </Link>
            <button type="submit" disabled={loading || !name.trim()}
              className="flex-1 sm:flex-none sm:px-8 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black text-sm font-semibold rounded-lg transition-all disabled:opacity-40 disabled:cursor-not-allowed">
              {loading ? 'Creating...' : projectType === 'scheme' ? 'Create Scheme Project' : 'Create Project'}
            </button>
          </div>
        </form>
      </main>
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react'
import { signIn } from 'next-auth/react'
import { Eye, EyeOff, CheckCircle2, Mail } from 'lucide-react'

function getPasswordStrength(password: string): { label: string; color: string; width: string } {
  if (password.length < 8) return { label: 'Weak', color: 'bg-red-500', width: 'w-1/3' }
  const hasUpper = /[A-Z]/.test(password)
  const hasLower = /[a-z]/.test(password)
  const hasNumber = /[0-9]/.test(password)
  const hasSpecial = /[^A-Za-z0-9]/.test(password)
  const score = [hasUpper, hasLower, hasNumber, hasSpecial].filter(Boolean).length
  if (password.length >= 8 && score >= 3) return { label: 'Strong', color: 'bg-green-500', width: 'w-full' }
  if (password.length >= 8 && score >= 2) return { label: 'Fair', color: 'bg-amber-500', width: 'w-2/3' }
  return { label: 'Weak', color: 'bg-red-500', width: 'w-1/3' }
}

export default function RegisterPage() {
  useEffect(() => { document.title = 'Create Account — METARDU' }, [])

  const [fullName, setFullName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirm, setShowConfirm] = useState(false)
  const [agreeTerms, setAgreeTerms] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState(false)

  const strength = getPasswordStrength(password)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')

    if (password.length < 8) {
      setError('Password must be at least 8 characters')
      return
    }
    if (password !== confirmPassword) {
      setError('Passwords do not match')
      return
    }

    setLoading(true)

    try {
      const res = await fetch('/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, fullName }),
      })

      const data = await res.json()

      if (!res.ok) {
        setError(data.error || 'Registration failed. Please try again.')
        setLoading(false)
        return
      }

      // Auto-login after successful registration
      const loginResult = await signIn('credentials', {
        email,
        password,
        redirect: false,
      })

      if (loginResult?.error) {
        // Registration succeeded but auto-login failed — send to login page
        setSuccess(true)
        setLoading(false)
        return
      }

      // Redirect to dashboard
      window.location.href = '/dashboard'
    } catch {
      setError('Registration failed. Please try again.')
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen flex">
      {/* Left panel */}
      <div className="hidden md:flex md:w-1/2 bg-gray-900 text-white flex-col justify-center p-12">
        <a href="/" className="text-4xl font-bold mb-4 text-[var(--accent)]">METARDU</a>
        <p className="text-xl text-gray-300 mb-8">From field data to finished documents.</p>
        <ul className="space-y-4 text-gray-400">
          <li className="flex items-center gap-3">
            <CheckCircle2 className="w-5 h-5 text-green-500" />
            Kenya Survey Regulations compliant
          </li>
          <li className="flex items-center gap-3">
            <CheckCircle2 className="w-5 h-5 text-green-500" />
            Works offline in the field
          </li>
          <li className="flex items-center gap-3">
            <CheckCircle2 className="w-5 h-5 text-green-500" />
            Trusted by surveyors across East Africa
          </li>
        </ul>
      </div>

      {/* Right panel */}
      <div className="w-full md:w-1/2 flex items-center justify-center p-8 bg-[var(--bg-primary)]">
        <div className="w-full max-w-md">
          <a href="/" className="text-2xl font-bold text-[var(--accent)] md:hidden block mb-8">METARDU</a>

          {success ? (
            <div className="text-center">
              <Mail className="w-16 h-16 text-[var(--accent)] mx-auto mb-4" />
              <h2 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Account created!</h2>
              <p className="text-[var(--text-secondary)] mb-4">Your account has been created successfully.</p>
              <a href="/login" className="inline-block px-6 py-3 bg-[var(--accent)] text-black font-semibold rounded-lg hover:bg-[var(--accent-dim)] transition-colors">
                Sign in now
              </a>
            </div>
          ) : (
            <>
              <h2 className="text-2xl font-bold text-[var(--text-primary)]">Create your account</h2>
              <p className="text-[var(--text-secondary)] mb-8">Start your free trial. No credit card required.</p>

              <form onSubmit={handleSubmit} className="space-y-5">
                {error && (
                  <div className="p-3 bg-red-900/30 border border-red-700/50 rounded-lg text-red-400 text-sm">{error}</div>
                )}

                <div>
                  <label htmlFor="register-name" className="block text-sm text-[var(--text-primary)] mb-2">Full name</label>
                  <input id="register-name"
                    type="text"
                    value={fullName}
                    onChange={e => setFullName(e.target.value)}
                    className="w-full px-4 py-3 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)]"
                    autoComplete="name"
                    required
                  />
                </div>

                <div>
                  <label htmlFor="register-email" className="block text-sm text-[var(--text-primary)] mb-2">Email</label>
                  <input id="register-email"
                    type="email"
                    value={email}
                    onChange={e => setEmail(e.target.value)}
                    className="w-full px-4 py-3 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)]"
                    autoComplete="email"
                    required
                  />
                </div>

                <div>
                  <label htmlFor="register-password" className="block text-sm text-[var(--text-primary)] mb-2">Password</label>
                  <div className="relative">
                    <input id="register-password"
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={e => setPassword(e.target.value)}
                      className="w-full px-4 py-3 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)] pr-10"
                      autoComplete="new-password"
                      required
                      minLength={8}
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-300"
                    >
                      {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>
                  {password && (
                    <div className="mt-2">
                      <div className="h-1 bg-gray-700 rounded-full overflow-hidden">
                        <div className={`h-full ${strength.color} ${strength.width} transition-all`} />
                      </div>
                      <p className="text-xs text-[var(--text-muted)] mt-1">{strength.label}</p>
                    </div>
                  )}
                </div>

                <div>
                  <label htmlFor="register-confirm" className="block text-sm text-[var(--text-primary)] mb-2">Confirm password</label>
                  <div className="relative">
                    <input id="register-confirm"
                      type={showConfirm ? 'text' : 'password'}
                      value={confirmPassword}
                      onChange={e => setConfirmPassword(e.target.value)}
                      className="w-full px-4 py-3 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)] pr-10"
                      autoComplete="new-password"
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowConfirm(!showConfirm)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-300"
                    >
                      {showConfirm ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>
                  {confirmPassword && password !== confirmPassword && (
                    <p className="text-red-400 text-xs mt-1">Passwords do not match</p>
                  )}
                </div>

                <label className="flex items-start gap-3 cursor-pointer">
                  <input aria-label="Agreeterms"
                    type="checkbox"
                    checked={agreeTerms}
                    onChange={e => setAgreeTerms(e.target.checked)}
                    className="mt-1 rounded border-gray-600 bg-[var(--bg-secondary)]"
                  />
                  <span className="text-sm text-[var(--text-secondary)]">
                    I agree to the <a href="/docs/terms" className="text-[var(--accent)] hover:underline">Terms of Service</a> and <a href="/docs/privacy" className="text-[var(--accent)] hover:underline">Privacy Policy</a>
                  </span>
                </label>

                <button
                  type="submit"
                  disabled={loading || !agreeTerms || password !== confirmPassword}
                  className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {loading && <span className="w-4 h-4 border-2 border-black border-t-transparent rounded-full animate-spin" />}
                  {loading ? 'Creating account...' : 'Create Account'}
                </button>
              </form>

              <p className="text-center mt-6 text-[var(--text-secondary)] text-sm">
                Already have an account?{' '}
                <a href="/login" className="text-[var(--accent)] hover:underline">Sign in</a>
              </p>
            </>
          )}
        </div>
      </div>
    </div>
  )
}

'use client';

import {
  AlertCircle,
  X,
  CheckCircle2,
  Building2,
  Trees,
  Mountain,
  Users,
  Waves,
  Factory,
  Gem,
} from 'lucide-react';

// ────────────────────────────────────────────────────────────────
// Category icon helper (uses JSX → must live in a .tsx file)
// ────────────────────────────────────────────────────────────────

export function getCategoryIcon(category: string) {
  const icons: Record<string, any> = {
    urban: Building2,
    agricultural: Trees,
    pastoral: Mountain,
    institutional: Users,
    coastal: Waves,
    special: Factory,
  };
  const Icon = icons[category] || Gem;
  return <Icon className="w-4 h-4" />;
}

// ────────────────────────────────────────────────────────────────
// Toast helper (inline, no external deps)
// ────────────────────────────────────────────────────────────────

export function Toast({
  message,
  type,
  onDismiss,
}: {
  message: string;
  type: 'success' | 'error' | 'info';
  onDismiss: () => void;
}) {
  const colors = {
    success: 'border-green-500/40 bg-green-500/10 text-green-300',
    error: 'border-red-500/40 bg-red-500/10 text-red-300',
    info: 'border-sky-500/40 bg-sky-500/10 text-sky-300',
  };
  const icons = {
    success: <CheckCircle2 className="w-4 h-4 shrink-0" />,
    error: <AlertCircle className="w-4 h-4 shrink-0" />,
    info: <AlertCircle className="w-4 h-4 shrink-0" />,
  };
  return (
    <div className={`flex items-center gap-2 px-4 py-3 rounded-lg border text-sm ${colors[type]}`}>
      {icons[type]}
      <span className="flex-1">{message}</span>
      <button onClick={onDismiss} className="opacity-60 hover:opacity-100 transition-opacity">
        <X className="w-3.5 h-3.5" />
      </button>
    </div>
  );
}

// ────────────────────────────────────────────────────────────────
// Empty state component
// ────────────────────────────────────────────────────────────────

export function EmptyState({
  icon,
  title,
  description,
  action,
}: {
  icon: React.ReactNode;
  title: string;
  description: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="flex flex-col items-center justify-center py-16 px-4 text-center">
      <div className="p-4 rounded-2xl bg-[var(--accent-subtle)] mb-4 text-[var(--accent)]">
        {icon}
      </div>
      <h3 className="text-base font-medium text-[var(--text-primary)] mb-1">{title}</h3>
      <p className="text-sm text-[var(--text-muted)] max-w-md mb-4">{description}</p>
      {action}
    </div>
  );
}

// ────────────────────────────────────────────────────────────────
// Confirmation modal
// ────────────────────────────────────────────────────────────────

export function ConfirmDialog({
  open,
  title,
  message,
  confirmLabel,
  cancelLabel,
  variant,
  onConfirm,
  onCancel,
}: {
  open: boolean;
  title: string;
  message: string;
  confirmLabel: string;
  cancelLabel: string;
  variant: 'danger' | 'primary';
  onConfirm: () => void;
  onCancel: () => void;
}) {
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="w-full max-w-md rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6 space-y-4 shadow-2xl">
        <h3 className="text-lg font-semibold text-[var(--text-primary)]">{title}</h3>
        <p className="text-sm text-[var(--text-secondary)]">{message}</p>
        <div className="flex gap-3 justify-end pt-2">
          <button
            onClick={onCancel}
            className="btn btn-secondary"
          >
            {cancelLabel}
          </button>
          <button
            onClick={onConfirm}
            className={`btn text-white ${
              variant === 'danger'
                ? 'bg-red-600 hover:bg-red-700 border-red-600'
                : 'bg-[var(--accent)] hover:bg-[var(--accent-dim)] border-[var(--accent)]'
            }`}
          >
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { apiGet, apiPost, apiPut, apiDelete, apiInvalidate, ApiError } from '@/lib/api/client';
import {
  authSessionSchema,
  projectsListSchema,
  rimListSchema,
  rimTemplatesListSchema,
  rimMutationSchema,
  rimTemplateApplySchema,
  type Project,
  type RimSection,
  type RimParcel,
  type RimBeacon,
  type RimTemplate,
} from './types';

// ────────────────────────────────────────────────────────────────
// ConfirmDialog state shape (shared with page)
// ────────────────────────────────────────────────────────────────

export interface ConfirmDialogState {
  open: boolean;
  title: string;
  message: string;
  variant: 'danger' | 'primary';
  onConfirm: () => void;
}

// ────────────────────────────────────────────────────────────────
// useRimState — encapsulates all state + handlers for the RIM page
// ────────────────────────────────────────────────────────────────

export function useRimState() {
  const router = useRouter();

  // ── Auth ──
  const [authChecked, setAuthChecked] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // ── Toast ──
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' | 'info' } | null>(null);

  // ── Projects ──
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState('');
  const [projectsLoading, setProjectsLoading] = useState(true);
  const [projectSearch, setProjectSearch] = useState('');

  // ── RIM Sections ──
  const [sections, setSections] = useState<RimSection[]>([]);
  const [sectionsLoading, setSectionsLoading] = useState(false);

  // ── Active section ──
  const [activeSection, setActiveSection] = useState<RimSection | null>(null);
  const [sectionForm, setSectionForm] = useState<Partial<RimSection>>({});
  const [sectionSaving, setSectionSaving] = useState(false);

  // ── Parcels ──
  const [parcels, setParcels] = useState<RimParcel[]>([]);
  const [parcelsLoading, setParcelsLoading] = useState(false);
  const [showAddParcel, setShowAddParcel] = useState(false);
  const [newParcel, setNewParcel] = useState({
    parcel_number: '',
    area: '',
    land_use: '',
    owner_name: '',
    beacon_count: '',
  });

  // ── Beacons ──
  const [beacons, setBeacons] = useState<RimBeacon[]>([]);
  const [beaconsLoading, setBeaconsLoading] = useState(false);
  const [showAddBeacon, setShowAddBeacon] = useState(false);
  const [newBeacon, setNewBeacon] = useState({
    beacon_number: '',
    easting: '',
    northing: '',
    description: '',
    type: 'Pillar',
    survey_status: 'Original',
  });

  // ── Templates ──
  const [templates, setTemplates] = useState<RimTemplate[]>([]);
  const [showTemplates, setShowTemplates] = useState(false);
  const [templateSearch, setTemplateSearch] = useState('');
  const [templatesLoading, setTemplatesLoading] = useState(false);

  // ── Confirm dialog ──
  const [confirmDialog, setConfirmDialog] = useState<ConfirmDialogState>({
    open: false,
    title: '',
    message: '',
    variant: 'danger',
    onConfirm: () => {},
  });

  // ── PDF Generation ──
  const [pdfGenerating, setPdfGenerating] = useState(false);

  // ── Auth check ──
  useEffect(() => {
    (async () => {
      try {
        const data = await apiGet('/api/auth/session', authSessionSchema, { ttlMs: 0 })
        if (data?.user) {
          setIsAuthenticated(true);
        } else {
          router.push('/login');
          return;
        }
      } catch (err) {
        if (err instanceof ApiError && err.isUnauthorized) {
          router.push('/login');
          return;
        }
        // Other errors (server hiccup, etc.) — also bail to login
        router.push('/login');
        return;
      }
      setAuthChecked(true);
    })();
  }, [router]);

  // ── Toast helper ──
  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
    setToast({ message, type });
  }, []);

  // ── Load projects ──
  useEffect(() => {
    if (!isAuthenticated) return;
    (async () => {
      try {
        setProjectsLoading(true);
        const data = await apiGet('/api/projects', projectsListSchema, { ttlMs: 30_000 })
        setProjects(data.data || []);
      } catch (err) {
        showToast(err instanceof ApiError ? (err as Error).message : 'Failed to load projects', 'error');
      } finally {
        setProjectsLoading(false);
      }
    })();
  }, [isAuthenticated, showToast]);

  // ── Load sections when project changes ──
  const loadSections = useCallback(async (projectId: string) => {
    if (!projectId) {
      setSections([]);
      return;
    }
    try {
      setSectionsLoading(true);
      const data = await apiGet(`/api/rim?projectId=${projectId}`, rimListSchema, { ttlMs: 0 })
      setSections(data.data || []);
    } catch (err) {
      showToast(err instanceof ApiError ? (err as Error).message : 'Failed to load RIM sections', 'error');
    } finally {
      setSectionsLoading(false);
    }
  }, [showToast]);

  useEffect(() => {
    loadSections(selectedProjectId);
  }, [selectedProjectId, loadSections]);

  // ── Load templates ──
  const loadTemplates = useCallback(async () => {
    try {
      setTemplatesLoading(true);
      const data = await apiGet('/api/rim-templates', rimTemplatesListSchema, { ttlMs: 300_000 })
      setTemplates(data.data || []);
    } catch (err) {
      showToast(err instanceof ApiError ? (err as Error).message : 'Failed to load templates', 'error');
    } finally {
      setTemplatesLoading(false);
    }
  }, [showToast]);

  // ── Select project ──
  const handleSelectProject = (id: string) => {
    setSelectedProjectId(id);
    setActiveSection(null);
    setParcels([]);
    setBeacons([]);
  };

  // ── Select a section ──
  const handleSelectSection = async (section: RimSection) => {
    setActiveSection(section);
    setSectionForm({
      section_name: section.section_name,
      registry: section.registry,
      district: section.district,
      map_sheet_number: section.map_sheet_number,
      scale: section.scale,
      datum: section.datum,
      projection: section.projection,
      total_area: section.total_area,
      status: section.status,
      notes: section.notes,
    });

    // Load parcels and beacons
    setParcelsLoading(true);
    setBeaconsLoading(true);
    try {
      // Parcels: fetch via separate logic (API returns section list, not parcels inline)
      // The parcels/beacons for a section are added via POST, so we track them locally
      // We need to use the API to get them — but the GET endpoint only returns sections with counts
      // For now, we'll store them in local state as they're added
      setParcels([]);
      setBeacons([]);
    } finally {
      setParcelsLoading(false);
      setBeaconsLoading(false);
    }
  };

  // ── Create blank section ──
  const handleCreateSection = async () => {
    if (!selectedProjectId) return;
    try {
      const result = await apiPost(
        '/api/rim',
        rimMutationSchema,
        {
          action: 'create_section',
          data: {
            project_id: selectedProjectId,
            section_name: '',
            registry: '',
            district: '',
            map_sheet_number: '',
            scale: '1:2500',
            datum: 'Arc 1960',
            projection: 'UTM Zone 37S',
          },
        },
      );
      apiInvalidate(`/api/rim?projectId=${selectedProjectId}`)
      const newSection = result.data;
      showToast('RIM section created', 'success');
      await loadSections(selectedProjectId);
      handleSelectSection(newSection);
    } catch (err: unknown) {
      showToast(err instanceof ApiError ? (err as Error).message : ((err as Error).message || 'Failed to create section'), 'error');
    }
  };

  // ── Create from template ──
  const handleCreateFromTemplate = async (templateId: string) => {
    if (!selectedProjectId) return;
    try {
      // Get template data from the API
      const tplData = await apiPost(
        '/api/rim-templates',
        rimTemplateApplySchema,
        { templateId, customizations: {} },
      );
      const tpl = tplData.data;

      // Create the section with template defaults
      const result = await apiPost(
        '/api/rim',
        rimMutationSchema,
        {
          action: 'create_section',
          data: {
            project_id: selectedProjectId,
            section_name: tpl.section?.section_name || '',
            registry: tpl.defaults?.registry || '',
            district: '',
            map_sheet_number: '',
            scale: tpl.defaults?.scale || '1:2500',
            datum: tpl.defaults?.datum || 'Arc 1960',
            projection: tpl.defaults?.projection || 'UTM Zone 37S',
          },
        },
      );
      const newSection = result.data;

      // Add sample parcels
      if (tpl.sampleParcels?.length) {
        for (const p of tpl.sampleParcels) {
          await apiPost(
            '/api/rim',
            rimMutationSchema,
            {
              action: 'add_parcel',
              data: {
                rimSectionId: newSection.id,
                parcel_number: p.parcelNumber || '',
                area: p.area || 0,
                land_use: p.landUse || '',
                owner_name: p.ownerName || '',
                beacon_count: 0,
              },
            },
          );
        }
      }

      // Add sample beacons
      if (tpl.sampleBeacons?.length) {
        for (const b of tpl.sampleBeacons) {
          await apiPost(
            '/api/rim',
            rimMutationSchema,
            {
              action: 'add_beacon',
              data: {
                rimSectionId: newSection.id,
                beacon_number: b.beaconNumber || '',
                easting: b.easting || 0,
                northing: b.northing || 0,
                description: b.description || '',
                type: b.type || 'Pillar',
                survey_status: 'Original',
              },
            },
          );
        }
      }

      apiInvalidate(`/api/rim?projectId=${selectedProjectId}`)
      setShowTemplates(false);
      showToast('RIM section created from template', 'success');
      await loadSections(selectedProjectId);
      handleSelectSection(newSection);
    } catch (err: unknown) {
      showToast(err instanceof ApiError ? (err as Error).message : ((err as Error).message || 'Failed to create from template'), 'error');
    }
  };

  // ── Update section ──
  const handleUpdateSection = async () => {
    if (!activeSection) return;
    try {
      setSectionSaving(true);
      const result = await apiPut(
        '/api/rim',
        rimMutationSchema,
        {
          action: 'update_section',
          id: activeSection.id,
          data: {
            section_name: sectionForm.section_name || '',
            registry: sectionForm.registry || '',
            district: sectionForm.district || '',
            map_sheet_number: sectionForm.map_sheet_number || '',
            scale: sectionForm.scale || '1:2500',
            datum: sectionForm.datum || 'Arc 1960',
            projection: sectionForm.projection || 'UTM Zone 37S',
            total_area: sectionForm.total_area || 0,
            status: sectionForm.status || 'draft',
            notes: sectionForm.notes || '',
          },
        },
      );
      apiInvalidate(`/api/rim?projectId=${selectedProjectId}`)
      setActiveSection(result.data);
      showToast('Section updated', 'success');
      await loadSections(selectedProjectId);
    } catch (err: unknown) {
      showToast(err instanceof ApiError ? (err as Error).message : ((err as Error).message || 'Failed to update section'), 'error');
    } finally {
      setSectionSaving(false);
    }
  };

  // ── Delete section ──
  const handleDeleteSection = (section: RimSection) => {
    setConfirmDialog({
      open: true,
      title: 'Delete RIM Section',
      message: `Are you sure you want to delete "${section.section_name || 'Untitled Section'}"? This will permanently remove the section and all its parcels and beacons.`,
      variant: 'danger',
      onConfirm: async () => {
        setConfirmDialog((prev) => ({ ...prev, open: false }));
        try {
          await apiDelete(`/api/rim?rimSectionId=${section.id}`);
          apiInvalidate(`/api/rim?projectId=${selectedProjectId}`)
          showToast('Section deleted', 'success');
          if (activeSection?.id === section.id) {
            setActiveSection(null);
            setParcels([]);
            setBeacons([]);
          }
          await loadSections(selectedProjectId);
        } catch (err: unknown) {
          showToast(err instanceof ApiError ? (err as Error).message : ((err as Error).message || 'Failed to delete section'), 'error');
        }
      },
    });
  };

  // ── Add parcel ──
  const handleAddParcel = async () => {
    if (!activeSection || !newParcel.parcel_number.trim()) {
      showToast('Parcel number is required', 'error');
      return;
    }
    try {
      const result = await apiPost(
        '/api/rim',
        rimMutationSchema,
        {
          action: 'add_parcel',
          data: {
            rimSectionId: activeSection.id,
            parcel_number: newParcel.parcel_number.trim(),
            area: parseFloat(newParcel.area) || 0,
            land_use: newParcel.land_use.trim(),
            owner_name: newParcel.owner_name.trim(),
            beacon_count: parseInt(newParcel.beacon_count) || 0,
          },
        },
      );
      apiInvalidate(`/api/rim?projectId=${selectedProjectId}`)
      setParcels((prev) => [...prev, result.data]);
      setNewParcel({ parcel_number: '', area: '', land_use: '', owner_name: '', beacon_count: '' });
      setShowAddParcel(false);
      showToast('Parcel added', 'success');
      await loadSections(selectedProjectId);
    } catch (err: unknown) {
      showToast(err instanceof ApiError ? (err as Error).message : ((err as Error).message || 'Failed to add parcel'), 'error');
    }
  };

  // ── Add beacon ──
  const handleAddBeacon = async () => {
    if (!activeSection || !newBeacon.beacon_number.trim()) {
      showToast('Beacon number is required', 'error');
      return;
    }
    try {
      const result = await apiPost(
        '/api/rim',
        rimMutationSchema,
        {
          action: 'add_beacon',
          data: {
            rimSectionId: activeSection.id,
            beacon_number: newBeacon.beacon_number.trim(),
            easting: parseFloat(newBeacon.easting) || 0,
            northing: parseFloat(newBeacon.northing) || 0,
            description: newBeacon.description.trim(),
            type: newBeacon.type,
            survey_status: newBeacon.survey_status,
          },
        },
      );
      apiInvalidate(`/api/rim?projectId=${selectedProjectId}`)
      setBeacons((prev) => [...prev, result.data]);
      setNewBeacon({
        beacon_number: '',
        easting: '',
        northing: '',
        description: '',
        type: 'Pillar',
        survey_status: 'Original',
      });
      setShowAddBeacon(false);
      showToast('Beacon added', 'success');
      await loadSections(selectedProjectId);
    } catch (err: unknown) {
      showToast(err instanceof ApiError ? (err as Error).message : ((err as Error).message || 'Failed to add beacon'), 'error');
    }
  };

  // ── Generate PDF ──
  const handleGeneratePdf = async () => {
    if (!activeSection) return;
    try {
      setPdfGenerating(true);
      // ponytail: binary download bypasses typed client
      const res = await fetch('/api/rim', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'generate_pdf',
          rimSectionId: activeSection.id,
        }),
      });
      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error?.message || 'Failed to generate PDF');
      }
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      const contentDisposition = res.headers.get('Content-Disposition');
      const filenameMatch = contentDisposition?.match(/filename="(.+)"/);
      a.download = filenameMatch?.[1] || `RIM_${activeSection.section_name || 'draft'}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      showToast('PDF generated and downloaded', 'success');
    } catch (err: unknown) {
      showToast((err as Error).message || 'Failed to generate PDF', 'error');
    } finally {
      setPdfGenerating(false);
    }
  };

  // ── Open templates modal ──
  const handleOpenTemplates = async () => {
    setShowTemplates(true);
    if (templates.length === 0) {
      await loadTemplates();
    }
  };

  // ── Filtered projects ──
  const filteredProjects = projectSearch
    ? projects.filter(
        (p) =>
          p.name.toLowerCase().includes(projectSearch.toLowerCase()) ||
          p.survey_type?.toLowerCase().includes(projectSearch.toLowerCase()) ||
          p.location?.toLowerCase().includes(projectSearch.toLowerCase())
      )
    : projects;

  // ── Filtered templates ──
  const filteredTemplates = templateSearch
    ? templates.filter(
        (t) =>
          t.name.toLowerCase().includes(templateSearch.toLowerCase()) ||
          t.description.toLowerCase().includes(templateSearch.toLowerCase()) ||
          t.category.toLowerCase().includes(templateSearch.toLowerCase()) ||
          t.tags.some((tag) => tag.toLowerCase().includes(templateSearch.toLowerCase()))
      )
    : templates;

  return {
    // state
    authChecked,
    isAuthenticated,
    toast,
    setToast,
    projects,
    selectedProjectId,
    projectsLoading,
    projectSearch,
    setProjectSearch,
    sections,
    sectionsLoading,
    activeSection,
    setActiveSection,
    sectionForm,
    setSectionForm,
    sectionSaving,
    parcels,
    parcelsLoading,
    setParcels,
    showAddParcel,
    setShowAddParcel,
    newParcel,
    setNewParcel,
    beacons,
    beaconsLoading,
    setBeacons,
    showAddBeacon,
    setShowAddBeacon,
    newBeacon,
    setNewBeacon,
    templates,
    showTemplates,
    setShowTemplates,
    templateSearch,
    setTemplateSearch,
    templatesLoading,
    confirmDialog,
    setConfirmDialog,
    pdfGenerating,
    // derived
    filteredProjects,
    filteredTemplates,
    // handlers
    showToast,
    loadSections,
    loadTemplates,
    handleSelectProject,
    handleCreateSection,
    handleCreateFromTemplate,
    handleSelectSection,
    handleUpdateSection,
    handleDeleteSection,
    handleAddParcel,
    handleAddBeacon,
    handleGeneratePdf,
    handleOpenTemplates,
  };
}

export type RimState = ReturnType<typeof useRimState>;

'use client';

import { useState, useEffect, useCallback } from 'react'
import { createClient, type BrowserSession } from '@/lib/api-client/client'
import {
  JobSchedule, JobScheduleWithAlerts, SchedulePriority, ScheduleStatus,
  getSchedules, createSchedule, updateSchedule, deleteSchedule,
  markScheduleCompleted, markScheduleCancelled, getDueReminders,
  getScheduleStats, enrichWithAlerts, formatDate, formatTime,
  getRelativeDate, STATUS_LABELS, PRIORITY_COLORS, SURVEY_TYPES, EQUIPMENT_OPTIONS,
} from '@/lib/schedule/schedule'

/* ── Helpers ────────────────────────────────────────────────────────────── */

function statusColor(s: ScheduleStatus): string {
  switch (s) {
    case 'upcoming': return 'bg-green-900/40 text-green-300 border-green-700/40'
    case 'in_progress': return 'bg-blue-900/40 text-blue-300 border-blue-700/40'
    case 'completed': return 'bg-gray-700/40 text-gray-400 border-gray-600/40'
    case 'cancelled': return 'bg-red-900/30 text-red-400 border-red-700/30'
    case 'postponed': return 'bg-amber-900/40 text-amber-300 border-amber-700/40'
    default: return 'bg-gray-700/40 text-gray-400 border-gray-600/40'
  }
}

const TODAY = new Date().toISOString().split('T')[0]

/* ── Schedule Form Modal ────────────────────────────────────────────────── */

const BLANK = {
  title: '', description: '', scheduled_date: '', scheduled_time: '',
  location: '', client_name: '', client_contact: '',
  estimated_duration_hours: 1, survey_type: '',
  equipment_needed: [] as string[], team_members: [] as string[],
  reminder_enabled: true, reminder_days_before: [1] as number[],
  priority: 'normal' as SchedulePriority, notes: '',
}

function ScheduleFormModal({
  initial, onSave, onClose,
}: {
  initial?: Partial<JobSchedule>
  onSave: (data: any) => Promise<void>
  onClose: () => void
}) {
  const [form, setForm] = useState({ ...BLANK, ...initial })
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [equipInput, setEquipInput] = useState('')
  const [memberInput, setMemberInput] = useState('')
  const f = (k: string, v: any) => setForm(p => ({ ...p, [k]: v }))

  const toggleReminderDay = (d: number) => {
    setForm(p => ({
      ...p,
      reminder_days_before: p.reminder_days_before.includes(d)
        ? p.reminder_days_before.filter(x => x !== d)
        : [...p.reminder_days_before, d].sort((a, b) => b - a),
    }))
  }

  const addEquipment = (item: string) => {
    const v = item.trim()
    if (v && !form.equipment_needed.includes(v)) f('equipment_needed', [...form.equipment_needed, v])
    setEquipInput('')
  }

  const addMember = (name: string) => {
    const v = name.trim()
    if (v && !form.team_members.includes(v)) f('team_members', [...form.team_members, v])
    setMemberInput('')
  }

  const handleSubmit = async () => {
    if (!form.title.trim()) { setError('Job title is required'); return }
    if (!form.scheduled_date) { setError('Scheduled date is required'); return }
    setError('')
    setSaving(true)
    try { await onSave(form) }
    catch (err: unknown) { setError((err as Error).message || 'Failed to save') }
    finally { setSaving(false) }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm px-4"
      onClick={e => { if (e.target === e.currentTarget) onClose() }}>
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-2xl w-full max-w-xl max-h-[90vh] flex flex-col shadow-2xl"
        onClick={e => e.stopPropagation()}>
        <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--border-color)]">
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">
            {initial?.id ? 'Edit Scheduled Job' : 'Schedule New Job'}
          </h2>
          <button onClick={onClose} className="text-[var(--text-muted)] hover:text-[var(--text-primary)] text-xl leading-none p-1">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>
        <div className="overflow-y-auto p-6 space-y-4 flex-1">
          {error && (
            <div className="text-sm text-red-400 bg-red-900/20 border border-red-700/40 rounded-lg px-3 py-2">{error}</div>
          )}
          <div>
            <label htmlFor="job-title" className="block text-xs text-[var(--text-muted)] mb-1">Job Title *</label>
            <input id="job-title" value={form.title} onChange={e => f('title', e.target.value)}
              placeholder="e.g. Boundary Survey - Karen Plot L.R. No. 123/456" className="input w-full" />
          </div>
          <div>
            <label htmlFor="job-description" className="block text-xs text-[var(--text-muted)] mb-1">Description</label>
            <textarea id="job-description" value={form.description ?? ''} onChange={e => f('description', e.target.value)} rows={2}
              placeholder="Brief description of the work..." className="input w-full resize-none" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="job-date" className="block text-xs text-[var(--text-muted)] mb-1">Scheduled Date *</label>
              <input id="job-date" type="date" min={TODAY} value={form.scheduled_date}
                onChange={e => f('scheduled_date', e.target.value)} className="input w-full" />
            </div>
            <div>
              <label htmlFor="job-time" className="block text-xs text-[var(--text-muted)] mb-1">Time</label>
              <input id="job-time" type="time" value={form.scheduled_time || ''}
                onChange={e => f('scheduled_time', e.target.value || null)} className="input w-full" />
            </div>
            <div>
              <label htmlFor="job-duration" className="block text-xs text-[var(--text-muted)] mb-1">Duration (hours)</label>
              <input id="job-duration" type="number" min={1} max={24} value={form.estimated_duration_hours}
                onChange={e => f('estimated_duration_hours', parseInt(e.target.value) || 1)} className="input w-full" />
            </div>
            <div>
              <label htmlFor="job-survey-type" className="block text-xs text-[var(--text-muted)] mb-1">Survey Type</label>
              <select id="job-survey-type" value={form.survey_type ?? ''} onChange={e => f('survey_type', e.target.value)} className="input w-full">
                <option value="">Select type...</option>
                {SURVEY_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
            <div>
              <label htmlFor="job-priority" className="block text-xs text-[var(--text-muted)] mb-1">Priority</label>
              <select id="job-priority" value={form.priority} onChange={e => f('priority', e.target.value as SchedulePriority)} className="input w-full">
                <option value="low">Low</option>
                <option value="normal">Normal</option>
                <option value="high">High</option>
                <option value="urgent">Urgent</option>
              </select>
            </div>
            <div>
              <label htmlFor="job-location" className="block text-xs text-[var(--text-muted)] mb-1">Location</label>
              <input id="job-location" value={form.location ?? ''} onChange={e => f('location', e.target.value)}
                placeholder="e.g. Karen, Nairobi" className="input w-full" />
            </div>
            <div>
              <label htmlFor="job-client-name" className="block text-xs text-[var(--text-muted)] mb-1">Client Name</label>
              <input id="job-client-name" value={form.client_name ?? ''} onChange={e => f('client_name', e.target.value)} className="input w-full" />
            </div>
            <div>
              <label htmlFor="job-client-contact" className="block text-xs text-[var(--text-muted)] mb-1">Client Contact</label>
              <input id="job-client-contact" value={form.client_contact ?? ''} onChange={e => f('client_contact', e.target.value)} className="input w-full" />
            </div>
          </div>
          <div>
            <label htmlFor="equipment-input" className="block text-xs text-[var(--text-muted)] mb-1">Equipment Needed</label>
            <div className="flex gap-2 mb-2">
              <input id="equipment-input" value={equipInput} onChange={e => setEquipInput(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addEquipment(equipInput) } }}
                placeholder="Type + Enter" className="input flex-1 text-sm py-1.5" />
              <button onClick={() => addEquipment(equipInput)} className="btn btn-secondary text-sm py-1.5 px-3">Add</button>
            </div>
            <div className="flex flex-wrap gap-1.5 mb-2">
              {EQUIPMENT_OPTIONS.filter(e => !form.equipment_needed.includes(e)).slice(0, 6).map(e => (
                <button key={e} onClick={() => addEquipment(e)}
                  className="text-xs px-2 py-0.5 rounded border border-[var(--border-color)] text-[var(--text-muted)] hover:border-[var(--accent)]/50 hover:text-[var(--accent)] transition-colors">
                  + {e}
                </button>
              ))}
            </div>
            {form.equipment_needed.length > 0 && (
              <div className="flex flex-wrap gap-1.5">
                {form.equipment_needed.map(e => (
                  <span key={e} className="text-xs px-2 py-0.5 rounded bg-[var(--accent)]/10 text-[var(--accent)] border border-[var(--accent)]/20 flex items-center gap-1">
                    {e}
                    <button onClick={() => f('equipment_needed', form.equipment_needed.filter(x => x !== e))} className="hover:text-red-400">x</button>
                  </span>
                ))}
              </div>
            )}
          </div>
          <div>
            <label htmlFor="member-input" className="block text-xs text-[var(--text-muted)] mb-1">Team Members</label>
            <div className="flex gap-2">
              <input id="member-input" value={memberInput} onChange={e => setMemberInput(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addMember(memberInput) } }}
                placeholder="Name + Enter" className="input flex-1 text-sm py-1.5" />
              <button onClick={() => addMember(memberInput)} className="btn btn-secondary text-sm py-1.5 px-3">Add</button>
            </div>
            {form.team_members.length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-2">
                {form.team_members.map(m => (
                  <span key={m} className="text-xs px-2 py-0.5 rounded bg-blue-500/10 text-blue-300 border border-blue-500/20 flex items-center gap-1">
                    {m}
                    <button onClick={() => f('team_members', form.team_members.filter(x => x !== m))} className="hover:text-red-400">x</button>
                  </span>
                ))}
              </div>
            )}
          </div>
          <div className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg p-4">
            <div className="flex items-center justify-between mb-3">
              <span className="text-sm font-medium text-[var(--text-primary)]">Reminders</span>
              <button onClick={() => f('reminder_enabled', !form.reminder_enabled)}
                className={`w-10 h-5 rounded-full transition-colors relative ${form.reminder_enabled ? 'bg-[var(--accent)]' : 'bg-gray-600'}`}>
                <span className={`absolute top-0.5 w-4 h-4 rounded-full bg-white transition-transform ${form.reminder_enabled ? 'translate-x-5' : 'translate-x-0.5'}`} />
              </button>
            </div>
            {form.reminder_enabled && (
              <div className="flex flex-wrap gap-2">
                {[1, 2, 3, 7, 14].map(d => (
                  <button key={d} onClick={() => toggleReminderDay(d)}
                    className={`text-xs px-3 py-1 rounded border transition-colors ${
                      form.reminder_days_before.includes(d)
                        ? 'border-[var(--accent)]/50 bg-[var(--accent)]/10 text-[var(--accent)]'
                        : 'border-[var(--border-color)] text-[var(--text-muted)] hover:border-[var(--accent)]/30'
                    }`}>
                    {d === 1 ? '1 day before' : `${d} days before`}
                  </button>
                ))}
              </div>
            )}
          </div>
          <div>
            <label htmlFor="job-notes" className="block text-xs text-[var(--text-muted)] mb-1">Notes</label>
            <textarea id="job-notes" value={form.notes ?? ''} onChange={e => f('notes', e.target.value)} rows={2}
              placeholder="Any additional notes..." className="input w-full resize-none" />
          </div>
        </div>
        <div className="px-6 py-4 border-t border-[var(--border-color)] flex gap-3">
          <button onClick={onClose} disabled={saving}
            className="flex-1 px-4 py-2.5 text-sm font-medium rounded-lg border border-[var(--border-color)] text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors disabled:opacity-50">
            Cancel
          </button>
          <button onClick={handleSubmit} disabled={saving}
            className="flex-1 px-4 py-2.5 text-sm font-medium rounded-lg bg-[var(--accent)] text-white hover:opacity-90 transition-colors disabled:opacity-50 flex items-center justify-center gap-2">
            {saving ? (
              <><svg className="w-4 h-4 animate-spin" viewBox="0 0 24 24" fill="none"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/></svg>Saving...</>
            ) : (initial?.id ? 'Update Schedule' : 'Schedule Job')}
          </button>
        </div>
      </div>
    </div>
  )
}

/* ── Delete Confirmation Modal ──────────────────────────────────────────── */

function DeleteConfirmModal({ title, onConfirm, onCancel }: {
  title: string; onConfirm: () => void; onCancel: () => void
}) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm px-4"
      onClick={e => { if (e.target === e.currentTarget) onCancel() }}>
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-2xl w-full max-w-sm p-6 shadow-2xl">
        <div className="flex items-center gap-3 mb-4">
          <div className="w-10 h-10 rounded-full bg-red-500/10 border border-red-500/20 flex items-center justify-center">
            <svg className="w-5 h-5 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.8}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z"/>
            </svg>
          </div>
          <div>
            <h3 className="font-semibold text-[var(--text-primary)]">Remove Schedule</h3>
            <p className="text-sm text-[var(--text-muted)]">This cannot be undone</p>
          </div>
        </div>
        <p className="text-sm text-[var(--text-secondary)] mb-4">
          Remove <span className="font-semibold text-[var(--text-primary)]">"{title}"</span> from your schedule?
        </p>
        <div className="flex gap-3">
          <button onClick={onCancel}
            className="flex-1 px-4 py-2 text-sm rounded-lg border border-[var(--border-color)] text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors">
            Cancel
          </button>
          <button onClick={onConfirm}
            className="flex-1 px-4 py-2 text-sm rounded-lg bg-red-600 text-white hover:bg-red-700 transition-colors">
            Remove
          </button>
        </div>
      </div>
    </div>
  )
}

/* ── Main Schedule Page ─────────────────────────────────────────────────── */

export default function SchedulePage() {
  const [userId, setUserId] = useState<string | null>(null)
  const [authLoading, setAuthLoading] = useState(true)
  const [schedules, setSchedules] = useState<JobScheduleWithAlerts[]>([])
  const [stats, setStats] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<'all' | 'upcoming' | 'completed' | 'overdue'>('all')
  const [showForm, setShowForm] = useState(false)
  const [editItem, setEditItem] = useState<JobSchedule | null>(null)
  const [deleteTarget, setDeleteTarget] = useState<JobSchedule | null>(null)
  const [reminders, setReminders] = useState<JobScheduleWithAlerts[]>([])

  // Get user on mount
  useEffect(() => {
    createClient().auth.getSession().then(({ data }) => {
      const session = data?.session as BrowserSession | null | undefined
      if (session?.user?.id) {
        setUserId(session.user.id)
      }
      setAuthLoading(false)
    }).catch(() => setAuthLoading(false))
  }, [])

  const load = useCallback(async () => {
    if (!userId) return
    setLoading(true)
    try {
      const [allScheds, schedStats, dueReminders] = await Promise.all([
        getSchedules(userId),
        getScheduleStats(userId),
        getDueReminders(userId),
      ])
      setSchedules(allScheds.map(enrichWithAlerts))
      setStats(schedStats)
      setReminders(dueReminders)
    } catch (err) {
      console.error('Failed to load schedules', err)
    } finally {
      setLoading(false)
    }
  }, [userId])

  useEffect(() => { load() }, [load])

  if (authLoading) return <div className="flex items-center justify-center min-h-screen text-[var(--text-muted)]">Loading...</div>
  if (!userId) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen gap-4">
        <p className="text-[var(--text-muted)]">Please sign in to manage your schedule</p>
        <a href="/login" className="btn btn-primary">Sign In</a>
      </div>
    )
  }

  const handleSave = async (formData: any) => {
    if (editItem) {
      await updateSchedule(editItem.id, formData)
    } else {
      await createSchedule({ ...formData, user_id: userId })
    }
    setShowForm(false)
    setEditItem(null)
    load()
  }

  const handleDelete = async () => {
    if (!deleteTarget) return
    await deleteSchedule(deleteTarget.id)
    setDeleteTarget(null)
    load()
  }

  const handleStatusChange = async (id: string, status: ScheduleStatus) => {
    if (status === 'completed') await markScheduleCompleted(id)
    else if (status === 'cancelled') await markScheduleCancelled(id)
    else await updateSchedule(id, { status })
    load()
  }

  const filtered = schedules.filter(s => {
    if (filter === 'upcoming') return s.status === 'upcoming' && !s.isOverdue
    if (filter === 'completed') return s.status === 'completed'
    if (filter === 'overdue') return s.isOverdue
    return true
  })

  return (
    <div className="max-w-5xl mx-auto px-4 py-8 pb-24 md:pb-8">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-[var(--text-primary)]">Job Schedule</h1>
          <p className="text-sm text-[var(--text-muted)] mt-1">Plan and track your upcoming survey jobs</p>
        </div>
        <button onClick={() => { setEditItem(null); setShowForm(true) }}
          className="btn btn-primary flex items-center gap-2">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4"/>
          </svg>
          Schedule Job
        </button>
      </div>

      {/* Due Reminders Banner */}
      {reminders.length > 0 && (
        <div className="mb-6 bg-amber-500/10 border border-amber-500/30 rounded-xl p-4">
          <div className="flex items-center gap-2 mb-2">
            <svg className="w-5 h-5 text-amber-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M14.857 17.082a23.848 23.848 0 005.454-1.31A8.967 8.967 0 0118 9.75v-.7V9A6 6 0 006 9v.75a8.967 8.967 0 01-2.312 6.022c1.733.64 3.56 1.085 5.455 1.31m5.714 0a24.255 24.255 0 01-5.714 0m5.714 0a3 3 0 11-5.714 0"/>
            </svg>
            <span className="font-semibold text-amber-300 text-sm">Reminders Due ({reminders.length})</span>
          </div>
          <div className="space-y-1">
            {reminders.slice(0, 3).map(r => (
              <p key={r.id} className="text-xs text-amber-200/70">
                <strong>{r.title}</strong> — {getRelativeDate(r.scheduled_date)} {formatTime(r.scheduled_time ?? null)}
              </p>
            ))}
            {reminders.length > 3 && (
              <p className="text-xs text-amber-200/50">+ {reminders.length - 3} more reminder{reminders.length - 3 > 1 ? 's' : ''}</p>
            )}
          </div>
        </div>
      )}

      {/* Stats */}
      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
          {[
            { label: 'Today', value: stats.today, color: 'text-[var(--accent)]' },
            { label: 'This Week', value: stats.thisWeek, color: 'text-blue-400' },
            { label: 'Overdue', value: stats.overdue, color: 'text-red-400' },
            { label: 'Completed', value: stats.completed, color: 'text-green-400' },
          ].map(s => (
            <div key={s.label} className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-3 text-center">
              <div className={`text-2xl font-bold ${s.color}`}>{s.value}</div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">{s.label}</div>
            </div>
          ))}
        </div>
      )}

      {/* Filter Tabs */}
      <div className="flex gap-2 mb-6 overflow-x-auto pb-1">
        {(['all', 'upcoming', 'overdue', 'completed'] as const).map(f => (
          <button key={f} onClick={() => setFilter(f)}
            className={`px-4 py-1.5 text-sm rounded-lg border transition-colors whitespace-nowrap capitalize ${
              filter === f
                ? 'border-[var(--accent)]/50 bg-[var(--accent)]/10 text-[var(--accent)]'
                : 'border-[var(--border-color)] text-[var(--text-muted)] hover:border-[var(--accent)]/30'
            }`}>
            {f === 'all' ? 'All Jobs' : f === 'overdue' ? `Overdue${stats?.overdue ? ` (${stats.overdue})` : ''}` : `${f}`}
          </button>
        ))}
      </div>

      {/* Schedule List */}
      {loading ? (
        <div className="text-center py-12 text-[var(--text-muted)]">Loading schedules...</div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16">
          <div className="w-16 h-16 rounded-full bg-[var(--bg-tertiary)] border border-[var(--border-color)] flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-[var(--text-muted)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5"/>
            </svg>
          </div>
          <h3 className="font-medium text-[var(--text-primary)] mb-1">No scheduled jobs</h3>
          <p className="text-sm text-[var(--text-muted)] mb-4">Start by scheduling your first survey job</p>
          <button onClick={() => { setEditItem(null); setShowForm(true) }} className="btn btn-primary">
            Schedule Your First Job
          </button>
        </div>
      ) : (
        <div className="space-y-3">
          {filtered.map(schedule => (
            <div key={schedule.id}
              className={`rounded-xl border p-4 transition-all ${
                schedule.isOverdue ? 'border-red-500/30 bg-red-500/5' :
                schedule.isToday ? 'border-[var(--accent)]/30 bg-[var(--accent)]/5' :
                'border-[var(--border-color)] bg-[var(--bg-card)]'
              }`}>
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1 flex-wrap">
                    <h3 className={`font-semibold ${schedule.status === 'completed' ? 'text-[var(--text-muted)] line-through' : 'text-[var(--text-primary)]'}`}>
                      {schedule.title}
                    </h3>
                    <span className={`badge text-[10px] border ${statusColor(schedule.status)}`}>{STATUS_LABELS[schedule.status]}</span>
                    <span className={`badge text-[10px] border ${PRIORITY_COLORS[schedule.priority]}`}>{schedule.priority}</span>
                    {schedule.isOverdue && <span className="badge text-[10px] bg-red-500/20 text-red-300 border border-red-500/30">OVERDUE</span>}
                    {schedule.isToday && <span className="badge text-[10px] bg-green-500/20 text-green-300 border border-green-500/30">TODAY</span>}
                  </div>
                  <div className="flex items-center gap-4 text-sm text-[var(--text-secondary)] flex-wrap">
                    <span className="flex items-center gap-1">
                      <svg className="w-3.5 h-3.5 text-[var(--text-muted)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5"/>
                      </svg>
                      <span className={schedule.isOverdue ? 'text-red-400 font-medium' : ''}>{formatDate(schedule.scheduled_date)}</span>
                    </span>
                    {schedule.scheduled_time && (
                      <span>{formatTime(schedule.scheduled_time)}</span>
                    )}
                    {schedule.location && <span className="text-[var(--text-muted)]">{schedule.location}</span>}
                    <span className="text-[var(--text-muted)]">{schedule.estimated_duration_hours}h</span>
                  </div>
                  <div className="flex flex-wrap gap-1.5 mt-2">
                    {schedule.survey_type && (
                      <span className="text-[10px] px-2 py-0.5 rounded bg-purple-500/10 text-purple-300 border border-purple-500/20">{schedule.survey_type}</span>
                    )}
                    {schedule.client_name && (
                      <span className="text-[10px] px-2 py-0.5 rounded bg-blue-500/10 text-blue-300 border border-blue-500/20">{schedule.client_name}</span>
                    )}
                    {schedule.equipment_needed?.slice(0, 3).map(e => (
                      <span key={e} className="text-[10px] px-2 py-0.5 rounded bg-gray-500/10 text-gray-300 border border-gray-500/20">{e}</span>
                    ))}
                    {schedule.team_members?.length > 0 && (
                      <span className="text-[10px] px-2 py-0.5 rounded bg-cyan-500/10 text-cyan-300 border border-cyan-500/20">
                        {schedule.team_members.length} team member{schedule.team_members.length > 1 ? 's' : ''}
                      </span>
                    )}
                  </div>
                  {schedule.reminder_enabled && schedule.status === 'upcoming' && (
                    <p className="text-[10px] text-[var(--text-muted)] mt-1.5">
                      Reminder: {schedule.reminder_days_before.map(d => d === 1 ? '1 day' : `${d} days`).join(', ')} before
                    </p>
                  )}
                </div>
                <div className="flex items-center gap-1 shrink-0">
                  {schedule.status === 'upcoming' && (
                    <>
                      <button onClick={() => handleStatusChange(schedule.id, 'in_progress')} title="Start"
                        className="p-1.5 rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-green-400 transition-colors">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M5.25 5.653c0-.856.917-1.398 1.667-.986l11.54 6.348a1.125 1.125 0 010 1.971l-11.54 6.347a1.125 1.125 0 01-1.667-.985V5.653z"/>
                        </svg>
                      </button>
                      <button onClick={() => handleStatusChange(schedule.id, 'completed')} title="Complete"
                        className="p-1.5 rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-green-400 transition-colors">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
                        </svg>
                      </button>
                    </>
                  )}
                  {schedule.status === 'in_progress' && (
                    <button onClick={() => handleStatusChange(schedule.id, 'completed')} title="Complete"
                      className="p-1.5 rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-green-400 transition-colors">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
                      </svg>
                    </button>
                  )}
                  <button onClick={() => { setEditItem(schedule); setShowForm(true) }} title="Edit"
                    className="p-1.5 rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M16.862 4.487l1.687-1.688a1.875 1.875 0 112.652 2.652L10.582 16.07a4.5 4.5 0 01-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 011.13-1.897l8.932-8.931zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0115.75 21H5.25A2.25 2.25 0 013 18.75V8.25A2.25 2.25 0 015.25 6H10"/>
                    </svg>
                  </button>
                  <button onClick={() => setDeleteTarget(schedule)} title="Delete"
                    className="p-1.5 rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-red-400 transition-colors">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M14.74 9l-.346 9m-4.788 0L9.26 9m9.968-3.21c.342.052.682.107 1.022.166m-1.022-.165L18.16 19.673a2.25 2.25 0 01-2.244 2.077H8.084a2.25 2.25 0 01-2.244-2.077L4.772 5.79m14.456 0a48.108 48.108 0 00-3.478-.397m-12 .562c.34-.059.68-.114 1.022-.165m0 0a48.11 48.11 0 013.478-.397m7.5 0v-.916c0-1.18-.91-2.164-2.09-2.201a51.964 51.964 0 00-3.32 0c-1.18.037-2.09 1.022-2.09 2.201v.916m7.5 0a48.667 48.667 0 00-7.5 0"/>
                    </svg>
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {showForm && (
        <ScheduleFormModal
          initial={editItem || undefined}
          onSave={handleSave}
          onClose={() => { setShowForm(false); setEditItem(null) }}
        />
      )}
      {deleteTarget && (
        <DeleteConfirmModal
          title={deleteTarget.title}
          onConfirm={handleDelete}
          onCancel={() => setDeleteTarget(null)}
        />
      )}
    </div>
  )
}

'use client'

import { useState, useRef, useCallback } from 'react'

interface AvatarUploaderProps {
  currentAvatar: string | null
  fullName: string
  email: string
  userId: string
  onUploaded: (url: string) => void
}

const MAX_FILE_SIZE = 5 * 1024 * 1024 // 5MB
const ACCEPTED_TYPES = ['image/png', 'image/jpeg', 'image/webp', 'image/gif']

export default function AvatarUploader({
  currentAvatar,
  fullName,
  email,
  onUploaded,
}: AvatarUploaderProps) {
  const [uploading, setUploading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [previewUrl, setPreviewUrl] = useState<string | null>(currentAvatar)
  const inputRef = useRef<HTMLInputElement>(null)

  const initials = (fullName || email || '?')
    .split(/\s+/)
    .slice(0, 2)
    .map((s) => s[0]?.toUpperCase())
    .join('')

  const handleFile = useCallback(
    async (file: File) => {
      setError(null)

      // Client-side validation
      if (!ACCEPTED_TYPES.includes(file.type)) {
        setError('Please upload a PNG, JPEG, WebP, or GIF image.')
        return
      }
      if (file.size > MAX_FILE_SIZE) {
        setError('Image must be 5MB or smaller.')
        return
      }

      setUploading(true)

      try {
        // Local preview
        const localUrl = URL.createObjectURL(file)
        setPreviewUrl(localUrl)

        // Upload via /api/storage (multipart)
        const formData = new FormData()
        formData.append('file', file)
        formData.append('bucket', 'avatars')

        const res = await fetch('/api/storage', {
          method: 'POST',
          body: formData,
        })

        if (!res.ok) {
          const err = await res.json().catch(() => ({ error: 'Upload failed' }))
          throw new Error(err.error || `Upload failed (status ${res.status})`)
        }

        const json = await res.json()
        const storedPath = json.data?.path as string | undefined
        if (!storedPath) throw new Error('Storage did not return a file path')

        // The avatar URL is the storage endpoint with the path
        const avatarUrl = `/api/storage?path=${encodeURIComponent(storedPath)}`
        setPreviewUrl(avatarUrl)
        onUploaded(avatarUrl)
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Upload failed')
        // Revert preview on failure
        setPreviewUrl(currentAvatar)
      } finally {
        setUploading(false)
        // Reset input so selecting the same file again triggers onChange
        if (inputRef.current) inputRef.current.value = ''
      }
    },
    [currentAvatar, onUploaded],
  )

  const handleDrop = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault()
      const file = e.dataTransfer.files?.[0]
      if (file) handleFile(file)
    },
    [handleFile],
  )

  return (
    <div className="mb-6 p-5 sm:p-6 bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)]">
      <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-1">Avatar</h2>
      <p className="text-sm text-[var(--text-secondary)] mb-4">
        Shown in the navbar, dashboard, and on shared projects. PNG, JPEG, WebP, or GIF up to 5MB.
      </p>

      <div className="flex flex-col sm:flex-row sm:items-center gap-4">
        {/* Avatar preview */}
        <div className="flex-shrink-0">
          <div
            className="w-20 h-20 sm:w-24 sm:h-24 rounded-full overflow-hidden bg-[var(--bg-tertiary)] border-2 border-[var(--border-color)] flex items-center justify-center text-2xl font-semibold text-[var(--text-secondary)]"
            onDragOver={(e) => e.preventDefault()}
            onDrop={handleDrop}
          >
            {previewUrl ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={previewUrl}
                alt={fullName || 'Your avatar'}
                className="w-full h-full object-cover"
              />
            ) : (
              <span aria-hidden>{initials || '?'}</span>
            )}
          </div>
        </div>

        {/* Controls */}
        <div className="flex-1 space-y-2">
          <div className="flex flex-wrap gap-2">
            <input
              ref={inputRef}
              type="file"
              accept={ACCEPTED_TYPES.join(',')}
              className="sr-only"
              onChange={(e) => {
                const file = e.target.files?.[0]
                if (file) handleFile(file)
              }}
              disabled={uploading}
            />
            <button
              type="button"
              onClick={() => inputRef.current?.click()}
              disabled={uploading}
              className="px-4 py-2 text-sm font-medium bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {uploading ? 'Uploading…' : 'Upload new image'}
            </button>
            {currentAvatar && (
              <button
                type="button"
                onClick={() => {
                  setPreviewUrl(null)
                  onUploaded('')
                }}
                disabled={uploading}
                className="px-4 py-2 text-sm font-medium border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg hover:bg-[var(--bg-tertiary)] disabled:opacity-50 transition-colors"
              >
                Remove
              </button>
            )}
          </div>
          <p className="text-xs text-[var(--text-muted)]">
            Tip: Drag and drop an image onto the circle above.
          </p>
          {error && (
            <p className="text-xs text-red-600 dark:text-red-400" role="alert">
              {error}
            </p>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'

interface SecuritySectionProps {
  email: string
}

export default function SecuritySection({ email }: SecuritySectionProps) {
  const [currentPassword, setCurrentPassword] = useState('')
  const [newPassword, setNewPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [status, setStatus] = useState<{ state: 'idle' | 'saving' | 'saved' | 'error'; message?: string }>({ state: 'idle' })
  const [showPasswords, setShowPasswords] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (newPassword.length < 8) {
      setStatus({ state: 'error', message: 'New password must be at least 8 characters.' })
      return
    }
    if (newPassword !== confirmPassword) {
      setStatus({ state: 'error', message: 'New passwords do not match.' })
      return
    }
    if (newPassword === currentPassword) {
      setStatus({ state: 'error', message: 'New password must be different from the current one.' })
      return
    }

    setStatus({ state: 'saving' })

    try {
      const res = await fetch('/api/auth/update-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          currentPassword,
          password: newPassword,
        }),
      })

      if (!res.ok) {
        const err = await res.json().catch(() => ({ error: 'Password update failed' }))
        throw new Error(err.error || `Failed (status ${res.status})`)
      }

      setStatus({ state: 'saved', message: 'Password updated successfully.' })
      setCurrentPassword('')
      setNewPassword('')
      setConfirmPassword('')
    } catch (err) {
      setStatus({
        state: 'error',
        message: err instanceof Error ? err.message : 'Password update failed',
      })
    }
  }

  const passwordStrength = (() => {
    if (!newPassword) return { score: 0, label: '', color: '' }
    let score = 0
    if (newPassword.length >= 8) score++
    if (newPassword.length >= 12) score++
    if (/[A-Z]/.test(newPassword) && /[a-z]/.test(newPassword)) score++
    if (/\d/.test(newPassword)) score++
    if (/[^A-Za-z0-9]/.test(newPassword)) score++

    if (score <= 1) return { score, label: 'Weak', color: 'bg-red-500' }
    if (score <= 2) return { score, label: 'Fair', color: 'bg-amber-500' }
    if (score <= 3) return { score, label: 'Good', color: 'bg-blue-500' }
    return { score, label: 'Strong', color: 'bg-green-500' }
  })()

  return (
    <div className="space-y-6">
      {/* Change Password */}
      <form
        onSubmit={handleSubmit}
        className="space-y-5 p-5 sm:p-6 bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)]"
      >
        <div>
          <h2 className="text-lg font-semibold text-[var(--text-primary)]">Change Password</h2>
          <p className="text-sm text-[var(--text-secondary)] mt-1">
            Use at least 8 characters with a mix of letters, numbers, and symbols.
          </p>
        </div>

        <div>
          <label htmlFor="current_password" className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
            Current Password
          </label>
          <input
            id="current_password" aria-label="Current password"
            type={showPasswords ? 'text' : 'password'}
            value={currentPassword}
            onChange={(e) => setCurrentPassword(e.target.value)}
            required
            autoComplete="current-password"
            className="w-full px-3 py-2 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] focus:ring-2 focus:ring-[var(--accent)] focus:border-[var(--accent)]"
          />
        </div>

        <div>
          <label htmlFor="new_password" className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
            New Password
          </label>
          <input
            id="new_password" aria-label="New password"
            type={showPasswords ? 'text' : 'password'}
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            required
            minLength={8}
            autoComplete="new-password"
            className="w-full px-3 py-2 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] focus:ring-2 focus:ring-[var(--accent)] focus:border-[var(--accent)]"
          />
          {newPassword && (
            <div className="mt-2 flex items-center gap-2">
              <div className="flex-1 h-1.5 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
                <div
                  className={`h-full ${passwordStrength.color} transition-all`}
                  style={{ width: `${(passwordStrength.score / 5) * 100}%` }}
                />
              </div>
              <span className="text-xs text-[var(--text-secondary)] font-medium min-w-[3.5rem]">
                {passwordStrength.label}
              </span>
            </div>
          )}
        </div>

        <div>
          <label htmlFor="confirm_password" className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
            Confirm New Password
          </label>
          <input
            id="confirm_password" aria-label="Confirm password"
            type={showPasswords ? 'text' : 'password'}
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            required
            minLength={8}
            autoComplete="new-password"
            className={`w-full px-3 py-2 bg-[var(--bg-primary)] border rounded-lg text-[var(--text-primary)] focus:ring-2 focus:ring-[var(--accent)] focus:border-[var(--accent)] ${
              confirmPassword && confirmPassword !== newPassword
                ? 'border-red-400 dark:border-red-700'
                : 'border-[var(--border-color)]'
            }`}
          />
          {confirmPassword && confirmPassword !== newPassword && (
            <p className="mt-1 text-xs text-red-600 dark:text-red-400">Passwords do not match.</p>
          )}
        </div>

        <label className="flex items-center gap-2 text-sm text-[var(--text-secondary)]">
          <input aria-label="Showpasswords"
            type="checkbox"
            checked={showPasswords}
            onChange={(e) => setShowPasswords(e.target.checked)}
            className="rounded border-[var(--border-color)]"
          />
          Show passwords
        </label>

        <div className="flex items-center gap-3 pt-2">
          <button
            type="submit"
            disabled={status.state === 'saving' || !currentPassword || !newPassword || !confirmPassword}
            className="px-5 py-2 text-sm font-medium bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            {status.state === 'saving' ? 'Updating…' : 'Update Password'}
          </button>
          {status.state === 'saved' && (
            <span className="text-sm text-green-600 dark:text-green-400" role="status">
              {status.message}
            </span>
          )}
          {status.state === 'error' && (
            <span className="text-sm text-red-600 dark:text-red-400" role="alert">
              {status.message}
            </span>
          )}
        </div>
      </form>

      {/* Active Sessions */}
      <div className="p-5 sm:p-6 bg-[var(--bg-secondary)] rounded-xl border border-[var(--border-color)]">
        <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-1">Active Sessions</h2>
        <p className="text-sm text-[var(--text-secondary)] mb-4">
          You&apos;re currently signed in on this device.
        </p>
        <div className="space-y-3">
          <div className="flex items-start gap-3 p-3 rounded-lg bg-[var(--bg-tertiary)]">
            <svg className="w-5 h-5 text-[var(--accent)] flex-shrink-0 mt-0.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M9.75 17L9 20l-1 1h8l-1-1-.75-3M3 13h18M5 17h14a2 2 0 002-2V5a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
            </svg>
            <div className="flex-1">
              <p className="text-sm font-medium text-[var(--text-primary)]">Current device</p>
              <p className="text-xs text-[var(--text-muted)]">{email}</p>
            </div>
            <span className="text-xs px-2 py-1 rounded bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 font-medium">
              Active now
            </span>
          </div>
        </div>
      </div>

      {/* Danger Zone */}
      <div className="p-5 sm:p-6 bg-[var(--bg-secondary)] rounded-xl border border-red-200 dark:border-red-900/50">
        <h2 className="text-lg font-semibold text-red-700 dark:text-red-400 mb-1">Danger Zone</h2>
        <p className="text-sm text-[var(--text-secondary)] mb-4">
          These actions are permanent and cannot be undone.
        </p>

        <div className="space-y-3">
          <div className="flex items-center justify-between gap-3 p-3 rounded-lg border border-[var(--border-color)] flex-wrap">
            <div className="flex-1 min-w-[200px]">
              <p className="text-sm font-medium text-[var(--text-primary)]">Sign out of all other devices</p>
              <p className="text-xs text-[var(--text-muted)]">
                Revoke all active sessions except this one.
              </p>
            </div>
            <button
              type="button"
              className="px-3 py-1.5 text-xs font-medium border border-[var(--border-color)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-tertiary)]"
              onClick={() => {
                // Defer to NextAuth signOut flow — not yet wired in this prototype
                alert('This will sign you out everywhere. Feature coming soon.')
              }}
            >
              Sign out everywhere
            </button>
          </div>

          <div className="flex items-center justify-between gap-3 p-3 rounded-lg border border-red-200 dark:border-red-900/50 flex-wrap">
            <div className="flex-1 min-w-[200px]">
              <p className="text-sm font-medium text-red-700 dark:text-red-400">Delete account</p>
              <p className="text-xs text-[var(--text-muted)]">
                Permanently delete all projects, observations, and documents. This cannot be reversed.
              </p>
            </div>
            <button
              type="button"
              className="px-3 py-1.5 text-xs font-medium bg-red-600 text-white rounded-lg hover:bg-red-700"
              onClick={() => {
                if (confirm('Are you sure? This will permanently delete all your data.')) {
                  alert('Account deletion requires admin verification. Please contact support@metardu.com.')
                }
              }}
            >
              Delete account
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback, useRef } from 'react'
import { useSession } from 'next-auth/react'
import AvatarUploader from './AvatarUploader'
import ProfileSection from './ProfileSection'
import CompanySection from './CompanySection'
import NotificationsSection from './NotificationsSection'
import SecuritySection from './SecuritySection'

export interface ProfileData {
  id: string
  full_name?: string
  firm_name?: string
  isk_number?: string
  phone?: string
  address?: string
  bio?: string
  avatar_url?: string
  notification_preferences?: NotificationPreferences
  notification_preferences_updated_at?: string
  license_number?: string
  verified_isk?: boolean
  is_suspended?: boolean
  sp_firm_name?: string
  sp_isk_number?: string
  sp_phone?: string
  email?: string
  role?: string
  created_at?: string
}

export interface NotificationPreferences {
  email?: Record<string, boolean>
  sms?: Record<string, boolean>
  push?: Record<string, boolean>
  in_app?: Record<string, boolean>
}

interface SettingsTabsProps {
  initialProfile: ProfileData | null
  sessionEmail: string
}

type TabId = 'profile' | 'company' | 'notifications' | 'security'

const TABS: { id: TabId; label: string; icon: string }[] = [
  { id: 'profile', label: 'Profile', icon: 'M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z' },
  { id: 'company', label: 'Company', icon: 'M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4' },
  { id: 'notifications', label: 'Notifications', icon: 'M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9' },
  { id: 'security', label: 'Security', icon: 'M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z' },
]

export default function SettingsTabs({ initialProfile, sessionEmail }: SettingsTabsProps) {
  const [activeTab, setActiveTab] = useState<TabId>('profile')
  const [profile, setProfile] = useState<ProfileData | null>(initialProfile)
  const [saveState, setSaveState] = useState<{ status: 'idle' | 'saving' | 'saved' | 'error'; message?: string }>({ status: 'idle' })
  const { update: updateSession } = useSession()
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

  const handlePatch = useCallback(async (patch: Partial<ProfileData>) => {
    setSaveState({ status: 'saving' })
    try {
      const res = await fetch('/api/profile/settings', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(patch),
      })
      if (!res.ok) {
        const err = await res.json().catch(() => ({ error: 'Update failed' }))
        throw new Error(err.error || `Failed (status ${res.status})`)
      }
      const json = await res.json()
      setProfile(prev => ({ ...prev, ...json.data }))
      setSaveState({ status: 'saved', message: 'Changes saved' })

      // Refresh session so navbar avatar/name updates immediately
      await updateSession()

      if (saveTimer.current) clearTimeout(saveTimer.current)
      saveTimer.current = setTimeout(() => setSaveState({ status: 'idle' }), 2500)
    } catch (err) {
      setSaveState({
        status: 'error',
        message: err instanceof Error ? err.message : 'Save failed',
      })
      if (saveTimer.current) clearTimeout(saveTimer.current)
      saveTimer.current = setTimeout(() => setSaveState({ status: 'idle' }), 4000)
    }
  }, [updateSession])

  return (
    <div className="space-y-6">
      {/* Tabs */}
      <div
        role="tablist"
        aria-label="Settings sections"
        className="flex gap-1 sm:gap-2 border-b border-[var(--border-color)] overflow-x-auto scrollbar-none -mx-4 px-4 sm:mx-0 sm:px-0"
      >
        {TABS.map((tab) => {
          const isActive = activeTab === tab.id
          return (
            <button
              key={tab.id}
              role="tab"
              aria-selected={isActive}
              aria-controls={`panel-${tab.id}`}
              id={`tab-${tab.id}`}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-2 px-3 sm:px-4 py-3 text-sm font-medium whitespace-nowrap border-b-2 transition-colors ${
                isActive
                  ? 'border-[var(--accent)] text-[var(--accent)]'
                  : 'border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
              }`}
            >
              <svg className="w-4 h-4 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
                <path strokeLinecap="round" strokeLinejoin="round" d={tab.icon} />
              </svg>
              {tab.label}
            </button>
          )
        })}
      </div>

      {/* Save status banner */}
      {saveState.status !== 'idle' && (
        <div
          role="status"
          aria-live="polite"
          className={`flex items-center gap-2 px-4 py-2.5 rounded-lg text-sm border ${
            saveState.status === 'saving'
              ? 'bg-blue-50 border-blue-200 text-blue-700 dark:bg-blue-900/20 dark:border-blue-800 dark:text-blue-300'
              : saveState.status === 'saved'
              ? 'bg-green-50 border-green-200 text-green-700 dark:bg-green-900/20 dark:border-green-800 dark:text-green-300'
              : 'bg-red-50 border-red-200 text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-300'
          }`}
        >
          {saveState.status === 'saving' && (
            <svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
            </svg>
          )}
          {saveState.status === 'saved' && (
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
            </svg>
          )}
          {saveState.status === 'error' && (
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          )}
          <span>
            {saveState.status === 'saving' ? 'Saving…' : saveState.message}
          </span>
        </div>
      )}

      {/* Tab Panels */}
      <div
        id="panel-profile"
        role="tabpanel"
        aria-labelledby="tab-profile"
        hidden={activeTab !== 'profile'}
        className={activeTab === 'profile' ? 'block' : 'hidden'}
      >
        <AvatarUploader
          currentAvatar={profile?.avatar_url ?? null}
          fullName={profile?.full_name ?? ''}
          email={sessionEmail}
          userId={profile?.id ?? ''}
          onUploaded={(url) => handlePatch({ avatar_url: url })}
        />
        <ProfileSection profile={profile} onPatch={handlePatch} />
      </div>

      <div
        id="panel-company"
        role="tabpanel"
        aria-labelledby="tab-company"
        hidden={activeTab !== 'company'}
        className={activeTab === 'company' ? 'block' : 'hidden'}
      >
        <CompanySection profile={profile} onPatch={handlePatch} />
      </div>

      <div
        id="panel-notifications"
        role="tabpanel"
        aria-labelledby="tab-notifications"
        hidden={activeTab !== 'notifications'}
        className={activeTab === 'notifications' ? 'block' : 'hidden'}
      >
        <NotificationsSection
          preferences={profile?.notification_preferences ?? null}
          lastUpdated={profile?.notification_preferences_updated_at ?? null}
          onPatch={(prefs) => handlePatch({ notification_preferences: prefs })}
        />
      </div>

      <div
        id="panel-security"
        role="tabpanel"
        aria-labelledby="tab-security"
        hidden={activeTab !== 'security'}
        className={activeTab === 'security' ? 'block' : 'hidden'}
      >
        <SecuritySection email={sessionEmail} />
      </div>
    </div>
  )
}

'use client';

import { useEffect, useMemo, useState } from 'react'
import Link from 'next/link'

type Status = 'processing' | 'completed' | 'failed'

export default function SubscriptionSuccessPage({
  searchParams,
}: {
  searchParams: Record<string, string | string[] | undefined>
}) {
  const provider = String(searchParams.provider || '')
  const paymentId = String(searchParams.paymentId || '')
  const planId = String(searchParams.planId || '')
  const stripeSessionId = String(searchParams.session_id || '')
  const paypalOrderId = String(searchParams.token || searchParams.orderId || '')

  const [status, setStatus] = useState<Status>('processing')
  const [message, setMessage] = useState<string>('Verifying payment…')

  const canVerify = useMemo(() => {
    if (!provider || !paymentId || !planId) return false
    if (provider === 'stripe') return !!stripeSessionId
    if (provider === 'paypal') return !!paypalOrderId
    return false
  }, [provider, paymentId, planId, stripeSessionId, paypalOrderId])

  useEffect(() => {
    if (!canVerify) {
      setStatus('failed')
      setMessage('Missing payment details. If you paid, contact support.')
      return
    }

    const run = async () => {
      try {
        const payload =
          provider === 'stripe'
            ? { provider: 'stripe', action: 'confirm-session', sessionId: stripeSessionId, paymentId, planId }
            : { provider: 'paypal', action: 'capture-order', orderId: paypalOrderId, paymentId, planId }

        const res = await fetch('/api/payments', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        })

        const data = await res.json().catch(() => ({}))
        if (!res.ok) {
          if (res.status === 401) {
            // Redirect to login preserving all payment params so user can retry after auth
            const params = new URLSearchParams()
            params.set('provider', provider)
            params.set('paymentId', paymentId)
            params.set('planId', planId)
            if (stripeSessionId) params.set('session_id', stripeSessionId)
            if (paypalOrderId) params.set('token', paypalOrderId)
            const callbackUrl = `/subscription/success?${params.toString()}`
            setStatus('failed')
            setMessage(`Please log in to verify your payment. Redirecting to login...`)
            // Auto-redirect to login with callback
            setTimeout(() => {
              const loginUrl = new URL('/login', window.location.origin)
              loginUrl.searchParams.set('callbackUrl', callbackUrl)
              window.location.href = loginUrl.toString()
            }, 2000)
            return
          }
          throw new Error(data?.error || 'Verification failed')
        }

        if (data.status === 'completed') {
          setStatus('completed')
          setMessage('Payment completed. Your subscription is now active.')
          return
        }

        if (data.status === 'pending') {
          setStatus('processing')
          setMessage('Payment still pending. If you were charged, wait a moment and refresh.')
          return
        }

        setStatus('failed')
        setMessage('Payment not completed.')
      } catch (e: unknown) {
        setStatus('failed')
        setMessage(((e as Error)?.message) ?? 'Verification failed.')
      }
    }

    run()
  }, [canVerify, provider, paymentId, planId, stripeSessionId, paypalOrderId])

  return (
    <div className="min-h-screen flex items-center justify-center px-6">
      <div className="w-full max-w-lg bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-2xl p-8">
        <div className="text-center mb-6">
          {status === 'completed' ? (
            <div className="w-16 h-16 rounded-full bg-green-900/30 border border-green-700/50 flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
              </svg>
            </div>
          ) : status === 'processing' ? (
            <div className="w-16 h-16 rounded-full bg-yellow-900/30 border border-yellow-700/50 flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-yellow-400 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
            </div>
          ) : (
            <div className="w-16 h-16 rounded-full bg-red-900/30 border border-red-700/50 flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </div>
          )}
        </div>

        <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2 text-center">METARDU</h1>
        <p className="text-[var(--text-secondary)] mb-6">{message}</p>

        <div
          className={`rounded-lg border px-4 py-3 text-sm ${
            status === 'completed'
              ? 'border-green-900/40 bg-green-900/10 text-green-200'
              : status === 'processing'
                ? 'border-yellow-900/40 bg-yellow-900/10 text-yellow-200'
                : 'border-red-900/40 bg-red-900/10 text-red-200'
          }`}
        >
          Status: <span className="font-semibold">{status.toUpperCase()}</span>
        </div>

        <div className="mt-6 flex gap-3">
          <Link
            href="/dashboard"
            className="flex-1 text-center py-3 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)]"
          >
            Go to Dashboard
          </Link>
          <Link
            href="/checkout"
            className="flex-1 text-center py-3 border border-[var(--border-hover)] text-[var(--text-primary)] rounded-lg hover:bg-[var(--bg-primary)]"
          >
            Back to Checkout
          </Link>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import { Point2D } from '@/lib/engine/types';
import { PageHeader } from '@/components/shared/PageHeader';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer';
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder';
import { coordinateAreaSolution, offsetAreaSolution } from '@/lib/engine/solution/wrappers/area';
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers';
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface PointInput {
  id: number;
  n: string;
  e: string;
}

export default function AreaCalculator() {
  const { t } = useLanguage()
  const [points, setPoints] = useState<PointInput[]>([
    { id: 1, n: '5000', e: '3000' },
    { id: 2, n: '5234.5678', e: '3156.7890' },
    { id: 3, n: '5100', e: '3400' },
    { id: 4, n: '4800', e: '3200' },
  ]);
  const [method, setMethod] = useState<'coordinate' | 'trapezoidal' | 'simpsons'>('coordinate');
  const [offsets, setOffsets] = useState('10, 15, 18, 22, 20, 16');
  const [interval, setInterval] = useState('20');
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const addPoint = () => {
    setPoints([...points, { id: Date.now(), n: '', e: '' }]);
  };

  const removePoint = (id: number) => {
    setPoints(points.filter((p: any) => p.id !== id));
  };

  const updatePoint = (id: number, field: 'n' | 'e', value: string) => {
    setPoints(points.map((p: any) => p.id === id ? { ...p, [field]: value } : p));
  };

  const calculate = () => {
    try {
      setCalcError(null);
      if (method === 'coordinate') {
        const pts: Point2D[] = points
          .map((p: any) => ({ northing: parseFloat(p.n), easting: parseFloat(p.e) }))
          .filter((p: any) => !isNaN(p.northing) && !isNaN(p.easting));
        if (pts.length >= 3) {
          const out = coordinateAreaSolution(pts);
          setSteps(out.steps);
          setSolutionTitle(out.solution.title);
        } else {
          setCalcError('Please enter at least 3 valid coordinate points.');
        }
      } else {
        const ord = offsets.split(',').map((s: any) => parseFloat(s.trim())).filter((n: any) => !isNaN(n));
        if (ord.length < 2) { setCalcError('Please enter at least 2 valid ordinates.'); return; }
        const int = parseFloat(interval);
        if (isNaN(int) || int <= 0) { setCalcError('Please enter a valid interval.'); return; }
        const out = offsetAreaSolution({ ordinates: ord, interval: int, method: method === 'trapezoidal' ? 'trapezoidal' : 'simpsons' });
        setSteps(out.steps);
        setSolutionTitle(out.solution.title);
      }
    } catch (err: unknown) {
      setCalcError((err as Error).message || 'An error occurred during calculation.');
      setSteps(null);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.area')}
        subtitle={t('tools.areaDesc')}
        reference="Survey Regulations 1994 | Survey Act Cap 299 | RDM 1.1 (2025)"
      />

      <div className="flex gap-4 mb-6 flex-wrap">
        <button onClick={() => { setMethod('coordinate'); setSteps(null); setSolutionTitle(undefined); }} className={`btn ${method === 'coordinate' ? 'btn-primary' : 'btn-secondary'}`}>
          Coordinate Method
        </button>
        <button onClick={() => { setMethod('trapezoidal'); setSteps(null); setSolutionTitle(undefined); }} className={`btn ${method === 'trapezoidal' ? 'btn-primary' : 'btn-secondary'}`}>
          Trapezoidal
        </button>
        <button onClick={() => { setMethod('simpsons'); setSteps(null); setSolutionTitle(undefined); }} className={`btn ${method === 'simpsons' ? 'btn-primary' : 'btn-secondary'}`}>
          Simpson&apos;s Rule
        </button>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        <div className="space-y-6">
          {method === 'coordinate' ? (
            <div className="card">
              <div className="card-header flex justify-between items-center">
                <span className="label">Polygon Coordinates</span>
                <span className="text-xs text-[var(--text-muted)]">Enter points in order (CW or CCW)</span>
              </div>
              <div className="card-body">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Pt</th>
                      <th>Northing (m)</th>
                      <th>Easting (m)</th>
                      <th></th>
                    </tr>
                  </thead>
                  <tbody>
                    {points.map((p, i) => (
                      <tr key={p.id}>
                        <td className="text-left font-semibold">{String.fromCharCode(65 + i)}</td>
                        <td><input className="input" value={p.n} onChange={e => updatePoint(p.id, 'n', e.target.value)} onFocus={e => e.target.select()} aria-label="e.g. 5000" placeholder="e.g. 5000" /></td>
                        <td><input className="input" value={p.e} onChange={e => updatePoint(p.id, 'e', e.target.value)} onFocus={e => e.target.select()} aria-label="e.g. 3000" placeholder="e.g. 3000" /></td>
                        <td><button onClick={() => removePoint(p.id)} className="text-[var(--error)] p-2 hover:bg-[var(--error)]/10 rounded">×</button></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                <button onClick={addPoint} className="btn btn-secondary w-full mt-4">{t('toolUI.addPoint')}</button>
              </div>
            </div>
          ) : (
            <div className="card">
              <div className="card-header"><span className="label">Offset Method</span></div>
              <div className="card-body space-y-4">
                <div>
                  <label className="label" htmlFor="ordinates-comma-separated-m">Ordinates (comma-separated, m)</label>
                  <input id="ordinates-comma-separated-m" className="input" value={offsets} onChange={e => setOffsets(e.target.value)} aria-label="10, 15, 18, 22, 20, 16" placeholder="10, 15, 18, 22, 20, 16" />
                </div>
                <div>
                  <label className="label" htmlFor="interval-m">Interval (m)</label>
                  <input className="input" value={interval} onChange={e => setInterval(e.target.value)} aria-label="20" placeholder="20" />
                </div>
              </div>
            </div>
          )}

          {calcError && <div className="text-red-500 bg-red-950/20 p-4 rounded mt-4">{calcError}</div>}
          <button onClick={calculate} className="btn btn-primary w-full mt-4">Calculate Area</button>
          {steps && (
            <div className="flex gap-2 mt-4">
              <button
                onClick={() => {
                  generatePDF(
                    { title: 'Area Computation Certificate', reference: 'Survey Regulations 1994 | Survey Act Cap 299 | RDM 1.1 (2025)' },
                    [
                      { title: 'Computation Steps', rows: steps.map((s: SolutionStep) => ({ label: s.label, value: s.result || s.computation || '—' })) },
                    ],
                    method === 'coordinate' ? [
                      { title: 'Coordinate List', headers: ['Point', 'Northing (m)', 'Easting (m)'], rows: points.filter(p => p.n && p.e).map((p, i) => [String.fromCharCode(65 + i), p.n, p.e]) },
                    ] : [
                      { title: 'Offset Data', headers: ['Ordinate (m)', 'Interval (m)'], rows: offsets.split(',').map(s => s.trim()).filter(Boolean).map(o => [o, interval]) },
                    ],
                  )
                }}
                className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
              >
                <Download className="w-4 h-4" /> {t('toolUI.exportPdf')}
              </button>
              <button
                onClick={() => {
                  if (method === 'coordinate') {
                    const csv = toCSV(
                      ['Point', 'Northing (m)', 'Easting (m)'],
                      points.filter(p => p.n && p.e).map((p, i) => [String.fromCharCode(65 + i), p.n, p.e]),
                    )
                    downloadCSV(csv, 'area-coordinates')
                  } else {
                    const csv = toCSV(
                      ['Ordinate (m)', 'Interval (m)', 'Method'],
                      offsets.split(',').map(s => s.trim()).filter(Boolean).map(o => [o, interval, method]),
                    )
                    downloadCSV(csv, 'area-offsets')
                  }
                }}
                className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
              >
                <Download className="w-4 h-4" /> {t('toolUI.exportCsv')}
              </button>
            </div>
          )}
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client';

import type { BeaconType, BeaconStatus } from '@/types/deedPlan'
import { BEACON_DEFINITIONS, getBeaconSymbolSVG, BEACON_CATEGORIES, BEACON_IMAGES } from '@/lib/compute/beaconSymbols'
import Image from 'next/image'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'

const STATUSES: BeaconStatus[] = ['FOUND', 'SET', 'DESTROYED', 'NOT_FOUND']

interface CategoryGroup {
  title: string
  types: readonly BeaconType[]
}

const CATEGORIES: CategoryGroup[] = [
  { title: 'Control Marks', types: BEACON_CATEGORIES.CONTROL },
  { title: 'Boundary Marks', types: BEACON_CATEGORIES.BOUNDARY },
  { title: 'Level Marks', types: BEACON_CATEGORIES.LEVEL },
