'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { chainageTableSolved, computeChainageTable, reverseChainageSolved } from '@/lib/engine/solution/wrappers/chainage'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface AlignmentPoint {
  id: string;
  name: string;
  easting: string;
  northing: string;
}

interface ChainageResult {
  pointName: string;
  easting: number;
  northing: number;
  chainage: number;
  distance: number;
}

export default function ChainageCalculator() {
  const { t } = useLanguage()
  const [startStation, setStartStation] = useState({ easting: '', northing: '' });
  const [startChainage, setStartChainage] = useState('0');
  const [alignmentPoints, setAlignmentPoints] = useState<AlignmentPoint[]>([
    { id: '1', name: 'A', easting: '', northing: '' },
    { id: '2', name: 'B', easting: '', northing: '' },
  ]);
  const [reverseChainage, setReverseChainage] = useState('');
  const [reverseResult, setReverseResult] = useState<{ easting: number; northing: number } | null>(null);
  const [results, setResults] = useState<ChainageResult[]>([]);
  const [steps, setSteps] = useState<SolutionStep[] | null>(null)
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined)
  const [reverseSteps, setReverseSteps] = useState<SolutionStep[] | null>(null)
  const [reverseTitle, setReverseTitle] = useState<string | undefined>(undefined)

  const addPoint = () => {
    const newId = Date.now().toString();
    const lastPoint = alignmentPoints[alignmentPoints.length - 1];
    const newLetter = String.fromCharCode(65 + alignmentPoints.length);
    setAlignmentPoints([
      ...alignmentPoints,
      { id: newId, name: newLetter, easting: lastPoint.easting, northing: lastPoint.northing }
    ]);
  };

  const removePoint = (id: string) => {
    if (alignmentPoints.length > 2) {
      setAlignmentPoints(alignmentPoints.filter((p: any) => p.id !== id));
    }
  };

  const updatePoint = (id: string, field: keyof AlignmentPoint, value: string) => {
    setAlignmentPoints(alignmentPoints.map((p: any) => p.id === id ? { ...p, [field]: value } : p));
  };

  const calculate = () => {
    const startE = parseFloat(startStation.easting);
    const startN = parseFloat(startStation.northing);
    const startCh = parseFloat(startChainage) || 0;

    if (isNaN(startE) || isNaN(startN)) return;

    const alignment = alignmentPoints
      .map((p: any) => ({ name: p.name, easting: parseFloat(p.easting), northing: parseFloat(p.northing) }))
      .filter((p: any) => !isNaN(p.easting) && !isNaN(p.northing))

    const table = computeChainageTable({
      start: { easting: startE, northing: startN },
      startChainage: startCh,
      alignment,
    })

    setResults(table)
    const s = chainageTableSolved({ startChainage: startCh, start: { easting: startE, northing: startN }, alignmentCount: alignment.length, table })
    setSteps(s.steps)
    setSolutionTitle(s.solution.title)
    setReverseResult(null)
    setReverseSteps(null)
    setReverseTitle(undefined)
  };

  const calculateReverse = () => {
    const targetCh = parseFloat(reverseChainage);
    if (isNaN(targetCh) || results.length === 0) return;

    const s = reverseChainageSolved({ targetChainage: targetCh, table: results })
    setReverseResult(s.result)
    setReverseSteps(s.steps)
    setReverseTitle(s.solution.title)
  };

  const formatChainage = (value: number): string => {
    const km = Math.floor(value / 1000);
    const m = value % 1000;
    return `${km}+${m.toFixed(3).padStart(3, '0')}`;
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.chainage')}
        subtitle={t('tools.chainageDesc')}
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            <h3 className="font-semibold text-[var(--text-primary)] mb-4">Starting Station</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="label" htmlFor="easting-m">Easting (m)</label>
                <input id="easting-m" aria-label="Easting" className="input" value={startStation.easting} onChange={e => setStartStation({...startStation, easting: e.target.value})} />
              </div>
              <div>
                <label className="label" htmlFor="northing-m">Northing (m)</label>
                <input id="northing-m" aria-label="Northing" className="input" value={startStation.northing} onChange={e => setStartStation({...startStation, northing: e.target.value})} />
              </div>
            </div>
            <div className="mt-4">
              <label className="label" htmlFor="starting-chainage-m">Starting Chainage (m)</label>
              <input className="input" value={startChainage} onChange={e => setStartChainage(e.target.value)} aria-label="0" placeholder="0" />
            </div>
          </div>

          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold text-[var(--text-primary)]">Alignment Points</h3>
              <button onClick={addPoint} className="text-sm px-3 py-1 bg-[var(--bg-tertiary)] text-[var(--text-primary)] rounded hover:bg-[var(--border-hover)]">{t('toolUI.addPoint')}</button>
            </div>
            <div className="space-y-3">
              {alignmentPoints.map((point, idx) => (
                <div key={point.id} className="flex gap-2 items-center">
                  <input aria-label="Name" className="input w-16 text-center" value={point.name} onChange={e => updatePoint(point.id, 'name', e.target.value)} />
                  <input className="input flex-1" value={point.easting} onChange={e => updatePoint(point.id, 'easting', e.target.value)} aria-label="Easting" placeholder="Easting" />
                  <input className="input flex-1" value={point.northing} onChange={e => updatePoint(point.id, 'northing', e.target.value)} aria-label="Northing" placeholder="Northing" />
                  {alignmentPoints.length > 2 && (
                    <button onClick={() => removePoint(point.id)} className="text-red-400 hover:text-red-300 px-2">[x]</button>
                  )}
                </div>
              ))}
            </div>
          </div>

          <button onClick={calculate} className="w-full px-6 py-4 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-bold rounded-lg">
            Calculate Chainages
          </button>

          {results.length > 0 && (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h3 className="font-semibold text-[var(--text-primary)] mb-4">Reverse Calculation</h3>
              <p className="text-xs text-[var(--text-muted)] mb-3">Find coordinates at a given chainage</p>
              <div className="flex gap-2">
                <input className="input flex-1" value={reverseChainage} onChange={e => setReverseChainage(e.target.value)} aria-label="Chainage (m)" placeholder="Chainage (m)" />
                <button onClick={calculateReverse} className="px-4 py-2 bg-[var(--bg-tertiary)] text-[var(--text-primary)] rounded hover:bg-[var(--border-hover)]">Find</button>
              </div>
              {reverseResult && (
                <div className="mt-4 p-3 bg-[var(--bg-tertiary)]/50 rounded-lg">
                  <p className="text-sm text-[var(--text-secondary)]">Coordinates at {reverseChainage}m:</p>
                  <p className="font-mono text-[var(--text-primary)]">E: {reverseResult.easting.toFixed(4)} m</p>
                  <p className="font-mono text-[var(--text-primary)]">N: {reverseResult.northing.toFixed(4)} m</p>
                </div>
              )}
              {reverseSteps ? (
                <div className="mt-4">
                  <SolutionStepsRenderer title={reverseTitle} steps={reverseSteps} />
                </div>
              ) : null}
            </div>
          )}
        </div>

        {results.length > 0 && (
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            {steps ? (
              <div className="mb-6">
                <SolutionStepsRenderer title={solutionTitle} steps={steps} />
              </div>
            ) : null}
            <h3 className="font-semibold text-[var(--text-primary)] mb-4">Chainage Table</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--border-color)]">
                    <th className="text-left py-2 text-[var(--text-secondary)]">Point</th>
                    <th className="text-right py-2 text-[var(--text-secondary)]">Easting</th>
                    <th className="text-right py-2 text-[var(--text-secondary)]">Northing</th>
                    <th className="text-right py-2 text-[var(--text-secondary)]">Chainage</th>
                    <th className="text-right py-2 text-[var(--text-secondary)]">Distance</th>
                  </tr>
                </thead>
                <tbody>
                  {results.map((r, idx) => (
                    <tr key={r.pointName} className="border-b border-[var(--border-color)]">
                      <td className="py-2 text-[var(--text-primary)] font-medium">{r.pointName}</td>
                      <td className="py-2 text-right font-mono text-[var(--text-primary)]">{r.easting.toFixed(3)}</td>
                      <td className="py-2 text-right font-mono text-[var(--text-primary)]">{r.northing.toFixed(3)}</td>
                      <td className="py-2 text-right font-mono text-[var(--accent)]">{formatChainage(r.chainage)}</td>
                      <td className="py-2 text-right font-mono text-[var(--text-secondary)]">
                        {r.distance > 0 ? r.distance.toFixed(3) + ' m' : '—'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="mt-6 p-4 bg-[var(--bg-tertiary)]/30 rounded-lg">
              <h4 className="text-sm font-semibold text-[var(--text-primary)] mb-2">Summary</h4>
              <div className="grid grid-cols-2 gap-2 text-sm">
                <span className="text-[var(--text-secondary)]">Total Points:</span>
                <span className="text-[var(--text-primary)] font-mono">{results.length}</span>
                <span className="text-[var(--text-secondary)]">Start Chainage:</span>
                <span className="text-[var(--text-primary)] font-mono">{formatChainage(results[0].chainage)}</span>
                <span className="text-[var(--text-secondary)]">End Chainage:</span>
                <span className="text-[var(--text-primary)] font-mono">{formatChainage(results[results.length - 1].chainage)}</span>
                <span className="text-[var(--text-secondary)]">Total Length:</span>
                <span className="text-[var(--text-primary)] font-mono">{(results[results.length - 1].chainage - results[0].chainage).toFixed(3)} m</span>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react'
import { createClient } from '@/lib/api-client/client'
import { exportCivil, CIVIL_FORMATS, CivilFormat, CivilPoint } from '@/lib/export/civilHandoff'
import { PageHeader } from '@/components/shared/PageHeader'
import Link from 'next/link'
import { useLanguage } from '@/lib/i18n/LanguageContext'

function download(content: string, filename: string) {
  const a = document.createElement('a')
  a.href = URL.createObjectURL(new Blob([content], { type: 'text/plain' }))
  a.download = filename; a.click()
}

function CivilExportPage() {
  const { t } = useLanguage()
  const [projects, setProjects]   = useState<any[]>([])
  const [projectId, setProjectId] = useState('')
  const [allPoints, setAllPoints] = useState<CivilPoint[]>([])
  const [format, setFormat]       = useState<CivilFormat>('civil3d')
  const [filter, setFilter]       = useState<'all' | 'control' | 'survey'>('all')
  const [loading, setLoading]     = useState(false)
  const [preview, setPreview]     = useState('')

  useEffect(() => {
    const sb = createClient()
    sb.auth.getSession().then(({ data: { session } }) => {
      const user = session?.user
      if (!user) return
      sb.from('projects').select('id,name,utm_zone,hemisphere').eq('user_id', user.id)
        .order('created_at', { ascending: false })
        .then(({ data }) => { if (data) setProjects(data) })
    })
  }, [])

  useEffect(() => {
    if (!projectId) { setAllPoints([]); return }
    setLoading(true)
    const sb = createClient()
    sb.from('survey_points').select('*').eq('project_id', projectId)
      .then(({ data }) => {
        if (data) setAllPoints(data.map((p: any) => ({
          name: p.name, easting: p.easting, northing: p.northing,
          elevation: p.elevation ?? 0, is_control: p.is_control, code: p.code,
        })))
        setLoading(false)
      })
  }, [projectId])

  const project = projects.find((p: any) => p.id === projectId)

  const filteredPoints = allPoints.filter((p: any) =>
    filter === 'all' ? true : filter === 'control' ? p.is_control : !p.is_control
  )

  useEffect(() => {
    if (!filteredPoints.length || !project) { setPreview(''); return }
    try {
      const { content } = exportCivil(filteredPoints, format, project.name, project.utm_zone, project.hemisphere)
      setPreview(content.slice(0, 1000) + (content.length > 1000 ? '\n…' : ''))
    } catch { setPreview('Error') }
  }, [filteredPoints, format, project])

  const handleExport = () => {
    if (!filteredPoints.length || !project) return
    const fmt = CIVIL_FORMATS.find((f: any) => f.id === format)!
    const { content, ext } = exportCivil(filteredPoints, format, project.name, project.utm_zone, project.hemisphere)
    download(content, `${project.name}_${fmt.label.replace(/[\s/]/g, '_')}.${ext}`)
  }

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-7xl mx-auto px-4 py-8">
        <PageHeader
          title={t('tools.civilExport')}
          subtitle={t('tools.civilExportDesc')}
        />

        <div className="grid lg:grid-cols-2 gap-6">
          <div className="space-y-5">

            {/* Project */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
              <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3 flex items-center gap-2">
                <span className="w-5 h-5 rounded-full bg-[var(--accent)] text-black text-xs font-bold flex items-center justify-center">1</span>
                Project
              </h2>
              {projects.length === 0
                ? <p className="text-sm text-[var(--text-muted)]">No projects. <Link href="/project/new" className="text-[var(--accent)]">Create one →</Link></p>
                : <select value={projectId} onChange={e => setProjectId(e.target.value)} className="input w-full">
                    <option value="">— Choose project —</option>
                    {projects.map((p: any) => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </select>}
              {project && (
                <p className="text-xs text-[var(--text-muted)] mt-2">
                  UTM Zone {project.utm_zone}{project.hemisphere} · {allPoints.length} points total
                  ({allPoints.filter((p: any) => p.is_control).length} control, {allPoints.filter((p: any) => !p.is_control).length} survey)
                </p>
              )}
            </div>

            {/* Point filter */}
            {allPoints.length > 0 && (
              <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
                <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3 flex items-center gap-2">
                  <span className="w-5 h-5 rounded-full bg-[var(--accent)] text-black text-xs font-bold flex items-center justify-center">2</span>
                  Points to export
                </h2>
                <div className="flex gap-2 mb-3">
                  {([
                    { k:'all',     l:`All (${allPoints.length})` },
                    { k:'control', l:`Control (${allPoints.filter((p: any) =>p.is_control).length})` },
                    { k:'survey',  l:`Survey (${allPoints.filter((p: any) =>!p.is_control).length})` },
                  ] as const).map(({ k, l }) => (
                    <button key={k} onClick={() => setFilter(k)}
                      className={`flex-1 py-2 rounded-lg text-xs font-medium border transition-colors ${filter === k ? 'bg-[var(--accent)] text-black border-[var(--accent)]' : 'bg-[var(--bg-secondary)] text-[var(--text-muted)] border-[var(--border-color)]'}`}>
                      {l}
                    </button>
                  ))}
                </div>
                <p className="text-xs text-[var(--text-muted)]">
                  {filteredPoints.length} points will be exported. For Civil 3D surface creation, export all points with elevation.
                </p>
              </div>
            )}

            {/* Format */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
              <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3 flex items-center gap-2">
                <span className="w-5 h-5 rounded-full bg-[var(--accent)] text-black text-xs font-bold flex items-center justify-center">3</span>
                Export format
              </h2>
              <div className="space-y-2">
                {CIVIL_FORMATS.map((f: any) => (
                  <label key={f.id} className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${format === f.id ? 'bg-[var(--accent)]/5 border-[var(--accent)]/30' : 'bg-[var(--bg-secondary)] border-[var(--border-color)] hover:border-[var(--accent)]/20'}`}>
                    <input aria-label="Fmt" type="radio" name="fmt" value={f.id} checked={format === f.id} onChange={() => setFormat(f.id)} className="mt-0.5 flex-shrink-0" />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-semibold text-[var(--text-primary)]">{f.label}</p>
                      <p className="text-xs text-[var(--text-muted)]">{f.software}</p>
                      <p className="text-xs text-[var(--text-secondary)] mt-0.5">{f.desc}</p>
                    </div>
                    <span className="text-xs text-[var(--text-muted)] flex-shrink-0">.{f.ext}</span>
                  </label>
                ))}
              </div>
            </div>

            <button onClick={handleExport} disabled={!filteredPoints.length}
              className="btn btn-primary w-full text-base py-3 disabled:opacity-50">
              Download {filteredPoints.length > 0 ? `${filteredPoints.length} points` : ''} — {CIVIL_FORMATS.find((f: any) => f.id === format)?.label}
            </button>
          </div>

          <div className="space-y-5">
            {/* Preview */}
            {preview && (
              <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
                <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">File preview</h2>
                <pre className="text-xs font-mono text-[var(--text-secondary)] bg-[var(--bg-primary)] rounded-lg p-4 overflow-x-auto whitespace-pre-wrap max-h-64">{preview}</pre>
              </div>
            )}

            {/* Instructions per format */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
              <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">Import instructions</h2>
              <div className="text-sm text-[var(--text-muted)] leading-relaxed space-y-2">
                {format === 'civil3d' && <>
                  <p><strong className="text-[var(--text-primary)]">AutoCAD Civil 3D:</strong></p>
                  <ol className="list-decimal list-inside space-y-1 text-xs">
                    <li>Home tab → Create Ground Data → Points → Import Points</li>
                    <li>Format: PENZD (comma delimited)</li>
                    <li>Browse to the downloaded CSV file</li>
                    <li>Points will appear in the drawing at correct coordinates</li>
                  </ol>
                </>}
                {format === '12d' && <>
                  <p><strong className="text-[var(--text-primary)]">12d Model:</strong></p>
                  <ol className="list-decimal list-inside space-y-1 text-xs">
                    <li>File → Import → Survey ASCII Import</li>
                    <li>Select format: Name,E,N,RL,String</li>
                    <li>Import into a new or existing model</li>
                    <li>Points appear as a survey string in the 3D view</li>
                  </ol>
                </>}
                {format === 'shapefile_csv' && <>
                  <p><strong className="text-[var(--text-primary)]">QGIS:</strong></p>
                  <ol className="list-decimal list-inside space-y-1 text-xs">
                    <li>Layer → Add Layer → Add Delimited Text Layer</li>
                    <li>X field: Lon_WGS84 · Y field: Lat_WGS84</li>
                    <li>CRS: EPSG:4326 (WGS84)</li>
                    <li>Then reproject to project CRS using Vector → Data Management Tools → Reproject</li>
                  </ol>
                  <p className="text-xs mt-2"><strong className="text-[var(--text-primary)]">ArcGIS Pro:</strong> Add Data → XY Point Data, set X = Lon_WGS84, Y = Lat_WGS84.</p>
                </>}
                {format === 'landxml_surface' && <>
                  <p><strong className="text-[var(--text-primary)]">Civil 3D Existing Ground:</strong></p>
                  <ol className="list-decimal list-inside space-y-1 text-xs">
                    <li>Toolspace → Prospector → Surfaces → right-click → Import LandXML</li>
                    <li>The surface imports as a TIN surface with all survey points as breaklines</li>
                    <li>Use for cut/fill volumes against a design surface</li>
                  </ol>
                </>}
                {format === 'pointcloud' && <>
                  <p><strong className="text-[var(--text-primary)]">CloudCompare:</strong></p>
                  <ol className="list-decimal list-inside space-y-1 text-xs">
                    <li>File → Open → select the .txt file</li>
                    <li>Columns: X Y Z Intensity (skip Name)</li>
                    <li>View the survey as a 3D point cloud</li>
                  </ol>
                  <p className="text-xs mt-2"><strong className="text-[var(--text-primary)]">Civil 3D:</strong> Insert → Point Cloud — import the .txt as an ASCII point cloud.</p>
                </>}
                {format === 'moss' && <>
                  <p><strong className="text-[var(--text-primary)]">MOSS / Microdrainage:</strong></p>
                  <ol className="list-decimal list-inside space-y-1 text-xs">
                    <li>Survey menu → Import Points → ASCII format</li>
                    <li>Select the .def file</li>
                    <li>Columns are pre-formatted for MOSS standard import</li>
                  </ol>
                </>}
              </div>
            </div>

            {/* Value prop for engineers */}
            <div className="bg-[var(--accent)]/5 border border-[var(--accent)]/20 rounded-xl p-4 text-sm">
              <p className="text-[var(--text-secondary)] leading-relaxed">
                <strong className="text-[var(--text-primary)]">For civil engineers:</strong> Survey data from METARDU is always correctly georeferenced in UTM with the datum declared. 
                You won't receive DXF files in unknown coordinate systems or CSV with missing elevations. 
                The LandXML Surface format creates an existing ground surface in Civil 3D ready for road design and earthwork volumes immediately.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

// P0-2 (2026-07-24): Wrap in <ToolGate> so direct-URL access can't
// bypass the plan check. The catalog page (/tools) shows lock badges,
// but those are display-only — this gate enforces the same check at
// the page level. Server-side enforcement for any export API this
// tool calls happens via the requirePlan() decorator on the route.
import { ToolGate } from '@/components/shared/ToolGate'

export default function CivilExportPageGated() {
  return (
    <ToolGate toolPath="/tools/civil-export">
      <CivilExportPage />
    </ToolGate>
  )
}

'use client'
import { useState } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { createCompositePlan, type CompositePlanParcel } from '@/lib/cadastral/p2Modules'

export default function CompositePlansPage() {
  const [csv, setCsv] = useState('LR/1,500,500100,9800100\nLR/2,800,500200,9800200\nLR/3,300,500050,9800050\nLR/4,1200,500300,9800300\nLR/5,650,500150,9800150')
  const [paperSize, setPaperSize] = useState<'A4'|'A3'|'A2'|'A1'|'A0'>('A1')
  const [result, setResult] = useState<ReturnType<typeof createCompositePlan> | null>(null)
  const compute = () => {
    const parcels: CompositePlanParcel[] = csv.trim().split('\n').map(l => { const [lr, area, e, n] = l.split(',').map(s => s.trim()); return { lrNumber: lr, area: parseFloat(area) || 0, easting: parseFloat(e) || 0, northing: parseFloat(n) || 0 } })
    setResult(createCompositePlan(parcels, paperSize))
  }
  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <PageHeader title="Composite Plans" subtitle="Multi-parcel layout on A1/A0 sheets, registry index" reference="Survey of Kenya: Registry Index Map Standards" />
