// DXF / SVG / CSV / GeoJSON export generators for the contour generator tool.
//
// Extracted from src/app/tools/contour-generator/page.tsx — pure functions,
// no React, no hooks, so this file does not need 'use client'.

import type { ContourLine, SpotHeight } from '@/lib/engine/contours';
import { MARGIN, SVG_HEIGHT, SVG_WIDTH } from './constants';
import { elevationToColor, computeHypsometricBands, fmt } from './helpers';

type Bounds2D = { minE: number; maxE: number; minN: number; maxN: number };

export function generateDXF(contours: ContourLine[], bounds: Bounds2D): string {
  const lines: string[] = [];
  lines.push('0');
  lines.push('SECTION');
  lines.push('2');
  lines.push('HEADER');
  lines.push('0');
  lines.push('ENDSEC');
  lines.push('0');
  lines.push('SECTION');
  lines.push('2');
  lines.push('TABLES');
  lines.push('0');
  lines.push('TABLE');
  lines.push('2');
  lines.push('LAYER');
  lines.push('70');
  lines.push(String(contours.length));

  const uniqueElevations = [...new Set(contours.map(c => c.elevation))].sort((a, b) => a - b);
  for (const elev of uniqueElevations) {
    lines.push('0');
    lines.push('LAYER');
    lines.push('2');
    lines.push(`C${elev.toFixed(1)}`);
    lines.push('70');
    lines.push('0');
    lines.push('62');
    lines.push('7');
    lines.push('6');
    lines.push('CONTINUOUS');
  }

  lines.push('0');
  lines.push('ENDTAB');
  lines.push('0');
  lines.push('ENDSEC');

  lines.push('0');
  lines.push('SECTION');
  lines.push('2');
  lines.push('ENTITIES');

  for (const contour of contours) {
    const layerName = `C${contour.elevation.toFixed(1)}`;
    lines.push('0');
    lines.push('LWPOLYLINE');
    lines.push('8');
    lines.push(layerName);
    lines.push('62');
    lines.push('7');
    lines.push('90');
    lines.push(String(contour.points.length));

    if (contour.points[0].easting === contour.points[contour.points.length - 1].easting &&
        contour.points[0].northing === contour.points[contour.points.length - 1].northing) {
      lines.push('70');
      lines.push('1');
    } else {
      lines.push('70');
      lines.push('0');
    }

    for (const pt of contour.points) {
      lines.push('10');
      lines.push(fmt(pt.easting, 4));
      lines.push('20');
      lines.push(fmt(pt.northing, 4));
    }
  }

  lines.push('0');
  lines.push('ENDSEC');
  lines.push('0');
  lines.push('EOF');
  return lines.join('\n');
}

export function generateSVGExport(
  contours: ContourLine[],
  bounds: Bounds2D,
  points: SpotHeight[]
): string {
  const usableW = SVG_WIDTH - 2 * MARGIN;
  const usableH = SVG_HEIGHT - 2 * MARGIN;
  const rangeE = bounds.maxE - bounds.minE || 1;
  const rangeN = bounds.maxN - bounds.minN || 1;

  const elevations = contours.map(c => c.elevation);
  const minElev = Math.min(...elevations);
  const maxElev = Math.max(...elevations);

  function toSvgX(e: number) { return MARGIN + ((e - bounds.minE) / rangeE) * usableW; }
  function toSvgY(n: number) { return MARGIN + ((bounds.maxN - n) / rangeN) * usableH; }

  const svgLines: string[] = [];
  svgLines.push(`<?xml version="1.0" encoding="UTF-8"?>`);
  svgLines.push(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${SVG_WIDTH} ${SVG_HEIGHT}" width="${SVG_WIDTH}" height="${SVG_HEIGHT}">`);
  svgLines.push(`<rect width="${SVG_WIDTH}" height="${SVG_HEIGHT}" fill="#1a1a2e"/>`);
  svgLines.push(`<rect x="${MARGIN}" y="${MARGIN}" width="${usableW}" height="${usableH}" fill="#0d1117" stroke="#30363d" stroke-width="1"/>`);

  // Hypsometric tint bands — discrete relief background.
  {
    const indexContours = contours.filter(c => c.isIndex).map(c => c.elevation).sort((a, b) => a - b);
    let ci = 1;
    if (indexContours.length >= 2) {
      const gaps: number[] = [];
      for (let i = 1; i < indexContours.length; i++) gaps.push(indexContours[i] - indexContours[i - 1]);
      ci = gaps.reduce((s, v) => s + v, 0) / gaps.length;
    } else {
      const sorted = contours.map(c => c.elevation).sort((a, b) => a - b);
      const gaps: number[] = [];
      for (let i = 1; i < sorted.length; i++) gaps.push(sorted[i] - sorted[i - 1]);
      ci = gaps.length ? gaps.reduce((s, v) => s + v, 0) / gaps.length : 1;
    }
    const bands = computeHypsometricBands(minElev, maxElev, ci);
    for (const band of bands) {
      const yTop = toSvgY(bounds.minN + (rangeN * (band.toElev - minElev)) / (maxElev - minElev || 1));
      const yBot = toSvgY(bounds.minN + (rangeN * (band.fromElev - minElev)) / (maxElev - minElev || 1));
      const h = Math.max(0, yBot - yTop);
      svgLines.push(`<rect x="${MARGIN}" y="${yTop.toFixed(2)}" width="${usableW}" height="${h.toFixed(2)}" fill="${band.color}" opacity="${band.isIndex ? 0.22 : 0.14}"/>`);
    }
  }

  // Contour lines
  for (const contour of contours) {
    const color = elevationToColor(contour.elevation, minElev, maxElev);
    const sw = contour.isIndex ? 2.0 : 0.8;
    const pts = contour.points.map(p => `${toSvgX(p.easting).toFixed(2)},${toSvgY(p.northing).toFixed(2)}`).join(' ');
    svgLines.push(`<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="${sw}" stroke-linejoin="round"/>`);

    if (contour.isIndex && contour.points.length > 5) {
      const midIdx = Math.floor(contour.points.length / 2);
      const midPt = contour.points[midIdx];
      const x = toSvgX(midPt.easting);
      const y = toSvgY(midPt.northing);
      svgLines.push(`<text x="${x.toFixed(2)}" y="${(y - 3).toFixed(2)}" fill="#e0e0e0" font-size="10" font-family="monospace" text-anchor="middle">${contour.elevation.toFixed(1)}</text>`);
    }
  }

  // Spot height crosses
  for (const pt of points) {
    const x = toSvgX(pt.easting);
    const y = toSvgY(pt.northing);
    svgLines.push(`<line x1="${(x - 3).toFixed(2)}" y1="${(y - 3).toFixed(2)}" x2="${(x + 3).toFixed(2)}" y2="${(y + 3).toFixed(2)}" stroke="#666" stroke-width="0.5"/>`);
    svgLines.push(`<line x1="${(x + 3).toFixed(2)}" y1="${(y - 3).toFixed(2)}" x2="${(x - 3).toFixed(2)}" y2="${(y + 3).toFixed(2)}" stroke="#666" stroke-width="0.5"/>`);
  }

  // Coordinate labels
  const numTicksE = 5;
  const numTicksN = 5;
  for (let i = 0; i <= numTicksE; i++) {
    const e = bounds.minE + (rangeE * i) / numTicksE;
    const x = toSvgX(e);
    svgLines.push(`<text x="${x.toFixed(2)}" y="${(SVG_HEIGHT - MARGIN / 3).toFixed(2)}" fill="#888" font-size="9" font-family="monospace" text-anchor="middle">${e.toFixed(1)}</text>`);
  }
  for (let i = 0; i <= numTicksN; i++) {
    const n = bounds.minN + (rangeN * i) / numTicksN;
    const y = toSvgY(n);
    svgLines.push(`<text x="${(MARGIN / 2).toFixed(2)}" y="${(y + 3).toFixed(2)}" fill="#888" font-size="9" font-family="monospace" text-anchor="middle">${n.toFixed(1)}</text>`);
  }

  // North arrow
  svgLines.push(`<g transform="translate(${SVG_WIDTH - 40}, ${MARGIN + 30})">`);
  svgLines.push(`<line x1="0" y1="20" x2="0" y2="0" stroke="#aaa" stroke-width="1.5"/>`);
  svgLines.push(`<polygon points="0,0 -4,8 4,8" fill="#aaa"/>`);
  svgLines.push(`<text x="0" y="30" fill="#aaa" font-size="10" text-anchor="middle" font-family="sans-serif">N</text>`);
  svgLines.push(`</g>`);

  // Scale bar
  const scaleBarWorldLen = rangeE / 5;
  const scaleBarSvgLen = usableW / 5;
  const sbX = MARGIN;
  const sbY = SVG_HEIGHT - 18;
  svgLines.push(`<line x1="${sbX}" y1="${sbY}" x2="${sbX + scaleBarSvgLen}" y2="${sbY}" stroke="#aaa" stroke-width="1.5"/>`);
  svgLines.push(`<line x1="${sbX}" y1="${sbY - 3}" x2="${sbX}" y2="${sbY + 3}" stroke="#aaa" stroke-width="1"/>`);
  svgLines.push(`<line x1="${(sbX + scaleBarSvgLen).toFixed(2)}" y1="${sbY - 3}" x2="${(sbX + scaleBarSvgLen).toFixed(2)}" y2="${sbY + 3}" stroke="#aaa" stroke-width="1"/>`);
  svgLines.push(`<text x="${(sbX + scaleBarSvgLen / 2).toFixed(2)}" y="${(sbY - 5).toFixed(2)}" fill="#aaa" font-size="9" text-anchor="middle" font-family="monospace">${scaleBarWorldLen.toFixed(1)} m</text>`);

  svgLines.push(`</svg>`);
  return svgLines.join('\n');
}

export function generateContourCSV(contours: ContourLine[]): string {
  const lines: string[] = [];
  lines.push('contour_id,elevation,is_index,point_index,easting,northing');
  let contourId = 0;
  for (const contour of contours) {
    contourId++;
    for (let i = 0; i < contour.points.length; i++) {
      const pt = contour.points[i];
      lines.push(
        `${contourId},${contour.elevation.toFixed(4)},${contour.isIndex ? 'true' : 'false'},${i},${pt.easting.toFixed(4)},${pt.northing.toFixed(4)}`
      );
    }
  }
  return lines.join('\n');
}

export function generateGeoJSON(contours: ContourLine[]): string {
  const features = contours.map((contour, idx) => ({
    type: 'Feature' as const,
    properties: {
      id: idx + 1,
      elevation: contour.elevation,
      is_index: contour.isIndex,
    },
    geometry: {
      type: 'MultiLineString' as const,
      coordinates: [
        contour.points.map(p => [p.easting, p.northing]),
      ],
    },
  }));
  const geojson = {
    type: 'FeatureCollection' as const,
    features,
  };
  return JSON.stringify(geojson, null, 2);
}

// Helper utilities for parsing XYZ text, generating demo data, computing
// colors, and downloading blobs.
//
// Extracted from src/app/tools/contour-generator/page.tsx — pure functions
// (no React, no hooks) so this file does not need 'use client'.

import type { SpotHeight } from '@/lib/engine/contours';
import type { ColMapping, ParseError, ParsedPoint } from './types';

export function fmt(n: number, d: number = 3): string {
  return n.toFixed(d);
}

export function detectDelimiter(text: string): string {
  const firstLines = text.split('\n').slice(0, 5);
  let commaCount = 0;
  let tabCount = 0;
  let semicolonCount = 0;
  let spaceCount = 0;

  for (const line of firstLines) {
    if (line.startsWith('#') || line.trim() === '') continue;
    commaCount += (line.match(/,/g) || []).length;
    tabCount += (line.match(/\t/g) || []).length;
    semicolonCount += (line.match(/;/g) || []).length;
    spaceCount += (line.match(/ {2,}/g) || []).length;
  }

  const counts: [string, number][] = [
    ['\t', tabCount],
    [',', commaCount],
    [';', semicolonCount],
    [' ', spaceCount],
  ];
  counts.sort((a, b) => b[1] - a[1]);
  return counts[0][0];
}

export function isHeaderLine(line: string): boolean {
  const lower = line.toLowerCase();
  const headerKeywords = [
    'easting', 'northing', 'elevation', 'name', 'point', 'id',
    'x', 'y', 'z', 'e', 'n', 'rl', 'height',
  ];
  const tokens = lower.split(/[\t,; ]+/).filter(t => t.length > 0);
  if (tokens.length === 0) return false;
  const matchCount = tokens.filter(t =>
    headerKeywords.some(kw => t === kw || t.includes(kw))
  ).length;
  return matchCount >= Math.ceil(tokens.length * 0.5);
}

export function guessColumnIndices(headers: string[]): ColMapping {
  const lower = headers.map(h => h.toLowerCase().trim());

  const eastingIdx = lower.findIndex(h =>
    h === 'easting' || h === 'e' || h === 'x' || h.includes('east') || h.includes('easting')
  );
  const northingIdx = lower.findIndex(h =>
    h === 'northing' || h === 'n' || h === 'y' || h.includes('north') || h.includes('northing')
  );
  const elevIdx = lower.findIndex(h =>
    h === 'elevation' || h === 'z' || h === 'rl' || h === 'height' ||
    h.includes('elev') || h.includes('height') || h === 'level'
  );
  const nameIdx = lower.findIndex(h =>
    h === 'name' || h === 'id' || h === 'point' || h === 'pointname' ||
    h === 'point_name' || h === 'code' || h.includes('name') || h.includes('id')
  );

  return {
    name: nameIdx >= 0 ? nameIdx : -1,
    easting: eastingIdx >= 0 ? eastingIdx : 0,
    northing: northingIdx >= 0 ? northingIdx : 1,
    elevation: elevIdx >= 0 ? elevIdx : 2,
  };
}

export function parseXYZText(text: string): {
  points: ParsedPoint[];
  errors: ParseError[];
  delimiter: string;
  hasHeader: boolean;
} {
  const delimiter = detectDelimiter(text);
  const lines = text.split('\n');
  const errors: ParseError[] = [];
  const points: ParsedPoint[] = [];
  const splitRe = delimiter === ' ' ? /\s+/ : new RegExp(`(?:${delimiter === '\t' ? '\\t' : delimiter})+`);
  let startIdx = 0;
  let hasHeader = false;

  if (lines.length > 0 && isHeaderLine(lines[0])) {
    hasHeader = true;
    startIdx = 1;
  }

  let colMapping: ColMapping | null = null;
  if (hasHeader) {
    const headers = lines[0].split(splitRe).map(h => h.trim());
    colMapping = guessColumnIndices(headers);
  }

  // Determine column count from first data row
  let colCount = 3;
  for (let i = startIdx; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const parts = trimmed.split(splitRe);
    if (parts.length >= 3) {
      colCount = parts.length;
      break;
    }
  }

  if (!colMapping) {
    if (colCount === 3) {
      colMapping = { name: -1, easting: 0, northing: 1, elevation: 2 };
    } else if (colCount >= 4) {
      colMapping = { name: 0, easting: 1, northing: 2, elevation: 3 };
    } else {
      colMapping = { name: -1, easting: 0, northing: 1, elevation: 2 };
    }
  }

  for (let i = startIdx; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    const parts = trimmed.split(splitRe).map(s => s.trim());
    if (parts.length < 3) {
      errors.push({ row: i + 1, message: `Too few columns (${parts.length})` });
      continue;
    }

    const mapping = colMapping!;
    const easting = parseFloat(parts[mapping.easting]);
    const northing = parseFloat(parts[mapping.northing]);
    const elevation = parseFloat(parts[mapping.elevation]);

    if (isNaN(easting) || isNaN(northing) || isNaN(elevation)) {
      errors.push({ row: i + 1, message: 'Non-numeric coordinate value' });
      continue;
    }

    const pointName =
      mapping.name >= 0 && mapping.name < parts.length
        ? parts[mapping.name]
        : `P${points.length + 1}`;

    points.push({ name: pointName, easting, northing, elevation });
  }

  return {
    points,
    errors: errors.slice(0, 50),
    delimiter,
    hasHeader,
  };
}

export function generateDemoData(): SpotHeight[] {
  const points: SpotHeight[] = [];
  const gridSize = 20;
  const spacing = 5.0;
  const originE = 484000;
  const originN = 9863100;

  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      const e = originE + i * spacing;
      const n = originN + j * spacing;

      // Two gaussian hills
      const cx1 = originE + 7 * spacing;
      const cy1 = originN + 7 * spacing;
      const cx2 = originE + 14 * spacing;
      const cy2 = originN + 12 * spacing;

      const d1 = Math.sqrt((e - cx1) ** 2 + (n - cy1) ** 2);
      const d2 = Math.sqrt((e - cx2) ** 2 + (n - cy2) ** 2);

      const hill1 = 15.0 * Math.exp(-(d1 * d1) / (2 * 12 * 12));
      const hill2 = 10.0 * Math.exp(-(d2 * d2) / (2 * 8 * 8));

      // Gentle base slope
      const baseSlope = 100.0 + 0.3 * i + 0.2 * j;

      // Add slight noise
      const noise = Math.sin(i * 1.3) * Math.cos(j * 1.7) * 0.3;

      const elevation = baseSlope + hill1 + hill2 + noise;

      points.push({
        name: `D${i * gridSize + j + 1}`,
        easting: e,
        northing: n,
        elevation: Math.round(elevation * 100) / 100,
      });
    }
  }

  return points;
}

export function elevationToColor(elevation: number, minElev: number, maxElev: number): string {
  const range = maxElev - minElev || 1;
  const t = Math.max(0, Math.min(1, (elevation - minElev) / range));
  // HSL gradient: green (120) -> yellow (60) -> brown (30)
  const hue = 120 - t * 90; // 120 (green) to 30 (brown/orange)
  const saturation = 55 + t * 25;
  const lightness = 40 + (1 - Math.abs(t - 0.5) * 2) * 15;
  return `hsl(${hue}, ${saturation}%, ${lightness}%)`;
}

/**
 * Discrete hypsometric tint bands for professional contour maps.
 * Uses an even-step quantized elevation model (QEM) — each band spans
 * `bandWidth` meters and gets a single color, so the map reads as a
 * graded color relief (like USGS/National Map style) rather than a
 * continuous gradient. Index contours (every 5th band) get a darker shade.
 *
 * @returns array of { fromElev, toElev, color, isIndex } bands covering
 *          [minElev, maxElev]. Used by MapTab to render a tinted rectangle
 *          per band as the relief background, and to render a discrete
 *          legend with swatches.
 */
export interface HypsometricBand {
  fromElev: number;
  toElev: number;
  color: string;
  isIndex: boolean;
}

export function computeHypsometricBands(
  minElev: number,
  maxElev: number,
  contourInterval: number,
): HypsometricBand[] {
  const bands: HypsometricBand[] = [];
  if (maxElev <= minElev) {
    return [{ fromElev: minElev, toElev: maxElev, color: elevationToColor(minElev, minElev, maxElev), isIndex: true }];
  }
  // Each band = one contour interval wide. Every 5th band is an "index" band.
  let elev = minElev;
  let idx = 0;
  while (elev < maxElev) {
    const to = Math.min(elev + contourInterval, maxElev);
    const mid = (elev + to) / 2;
    const color = elevationToColor(mid, minElev, maxElev);
    bands.push({ fromElev: elev, toElev: to, color, isIndex: idx % 5 === 0 });
    elev = to;
    idx++;
  }
  return bands;
}

export function downloadBlob(content: string, filename: string, mime = 'text/plain') {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

'use client';

import { useState, useCallback, useRef, useMemo, useEffect } from 'react';
import { Mountain } from 'lucide-react';
import { useSearchParams } from 'next/navigation';
import {
  generateContours,
  buildTINSurface,
  computeVolumeFromTIN,
  type SpotHeight,
  type ContourLine,
  type TINSurface,
  type Breakline,
} from '@/lib/engine/contours';
import {
  generateContoursAsync,
  buildTINSurfaceAsync,
  isWorkerAvailable,
} from '@/lib/workers/tinWorkerClient';

import type { TabId, Bounds, ImportStats, ParseError, VolumeResult } from './types';
import { MARGIN, SVG_HEIGHT, SVG_WIDTH } from './constants';
import {
  fmt,
  parseXYZText,
  generateDemoData,
  downloadBlob,
} from './helpers';
import {
  generateDXF,
  generateSVGExport,
  generateContourCSV,
  generateGeoJSON,
} from './generators';
import { ImportTab } from './ImportTab';
import { SettingsTab } from './SettingsTab';
import { MapTab, type SvgElements } from './MapTab';
import { ExportTab } from './ExportTab';
import { BreaklineTab } from './BreaklineTab';
import { useLanguage } from '@/lib/i18n/LanguageContext'
import { ComputeLimitNotice } from '@/components/tools/ComputeLimitNotice'

// ─── Component ──────────────────────────────────────────────────────────────

export default function ContourGeneratorPage() {
  const { t } = useLanguage()
  const [activeTab, setActiveTab] = useState<TabId>('import');

  // Tab 1: Import state
  const [rawText, setRawText] = useState('');
  const [fileName, setFileName] = useState('');
  const [points, setPoints] = useState<SpotHeight[]>([]);
  const [parseErrors, setParseErrors] = useState<ParseError[]>([]);
  const [importStats, setImportStats] = useState<ImportStats | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Tab 2: Settings state
  const [contourInterval, setContourInterval] = useState(1.0);
  const [indexMultiplier, setIndexMultiplier] = useState(5);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generateError, setGenerateError] = useState('');
  const [generateProgress, setGenerateProgress] = useState(0);
  const [usingWorker, setUsingWorker] = useState(false);

  // Breaklines (AUDIT FIX 2026-07-03: expose engine's breakline support in UI)
  const [breaklines, setBreaklines] = useState<Breakline[]>([]);

  // Results
  const [contours, setContours] = useState<ContourLine[]>([]);
  const [tinSurface, setTinSurface] = useState<TINSurface | null>(null);
  const [volumeResult, setVolumeResult] = useState<VolumeResult | null>(null);

  // ─── Project integration: auto-load points from project survey data ──────
  const searchParams = useSearchParams();
  const projectId = searchParams.get('project');
  const [projectLoaded, setProjectLoaded] = useState(false);

  useEffect(() => {
    if (!projectId || projectLoaded) return;
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(`/api/project/${projectId}/points`)
        if (!res.ok) return
        const json = await res.json()
        const pts: SpotHeight[] = (json.data || [])
          .filter((p: any) => p.elevation != null)
          .map((p: any) => ({
            name: p.point_name || p.id,
            easting: p.easting,
            northing: p.northing,
            elevation: p.elevation,
          }))
        if (!cancelled && pts.length > 0) {
          setPoints(pts)
          setImportStats({
            delimiter: 'auto',
            hasHeader: false,
          })
        }
      } catch {
        // silent fail — user can import manually
      } finally {
        if (!cancelled) setProjectLoaded(true)
      }
    })()
    return () => { cancelled = true }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId, projectLoaded])

  // ─── Bounding box computation ────────────────────────────────────────────

  const bounds = useMemo<Bounds | null>(() => {
    if (points.length === 0) return null;
    let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity, minZ = Infinity, maxZ = -Infinity;
    for (const p of points) {
      if (p.easting < minE) minE = p.easting;
      if (p.easting > maxE) maxE = p.easting;
      if (p.northing < minN) minN = p.northing;
      if (p.northing > maxN) maxN = p.northing;
      if (p.elevation < minZ) minZ = p.elevation;
      if (p.elevation > maxZ) maxZ = p.elevation;
    }
    return { minE, maxE, minN, maxN, minZ, maxZ };
  }, [points]);

  // ─── File upload handler ──────────────────────────────────────────────────

  const handleFileUpload = useCallback(async (file: File) => {
    setFileName(file.name);
    setIsParsing(true);
    setParseErrors([]);
    setContours([]);
    setTinSurface(null);
    setVolumeResult(null);

    try {
      const text = await file.text();
      setRawText(text);
      processText(text);
    } catch (err) {
      setParseErrors([{ row: 0, message: `Failed to read file: ${err instanceof Error ? err.message : 'Unknown error'}` }]);
    } finally {
      setIsParsing(false);
    }
  }, []);

  const processText = useCallback((text: string) => {
    setIsParsing(true);
    setParseErrors([]);
    setContours([]);
    setTinSurface(null);
    setVolumeResult(null);

    try {
      const result = parseXYZText(text);
      const spotHeights: SpotHeight[] = result.points.map(p => ({
        name: p.name,
        easting: p.easting,
        northing: p.northing,
        elevation: p.elevation,
      }));
      setPoints(spotHeights);
      setParseErrors(result.errors);
      setImportStats({
        delimiter: result.delimiter === '\t' ? 'tab' : result.delimiter === ',' ? 'comma' : result.delimiter === ';' ? 'semicolon' : 'space',
        hasHeader: result.hasHeader,
      });
    } catch (err) {
      setParseErrors([{ row: 0, message: `Parse error: ${err instanceof Error ? err.message : 'Unknown error'}` }]);
    } finally {
      setIsParsing(false);
    }
  }, []);

  const handleDropZone = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const file = e.dataTransfer.files[0];
    if (file) handleFileUpload(file);
  }, [handleFileUpload]);

  const handleFileInput = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) handleFileUpload(file);
  }, [handleFileUpload]);

  const handlePasteParse = useCallback(() => {
    if (!rawText.trim()) return;
    processText(rawText);
  }, [rawText, processText]);

  const handleLoadDemo = useCallback(() => {
    const demoPoints = generateDemoData();
    setPoints(demoPoints);
    setContours([]);
    setTinSurface(null);
    setVolumeResult(null);
    setParseErrors([]);
    setFileName('demo_terrain.csv');
    setImportStats({ delimiter: 'comma', hasHeader: true });
    // Build a demo CSV text for display
    const csvLines = ['Name,Easting,Northing,Elevation'];
    for (const p of demoPoints.slice(0, 10)) {
      csvLines.push(`${p.name},${fmt(p.easting, 3)},${fmt(p.northing, 3)},${fmt(p.elevation, 2)}`);
    }
    csvLines.push(`... (${demoPoints.length} points total)`);
    setRawText(csvLines.join('\n'));
  }, []);

  // ─── Generate contours ───────────────────────────────────────────────────

  const handleGenerate = useCallback(async () => {
    if (points.length < 3) {
      setGenerateError('At least 3 points are required to generate contours.');
      return;
    }
    if (contourInterval <= 0) {
      setGenerateError('Contour interval must be positive.');
      return;
    }

    setIsGenerating(true);
    setGenerateError('');
    setGenerateProgress(0);
    setUsingWorker(isWorkerAvailable());

    try {
      const indexInterval = contourInterval * indexMultiplier;

      // Use Web Worker with auto-fallback to sync engine.
      // For large datasets (≥ 5000 pts) this keeps the UI responsive;
      // for small datasets the worker overhead is negligible thanks to
      // the 30 s timeout + sync fallback in tinWorkerClient.
      //
      // AUDIT FIX (2026-07-05): DTM filtering — classify ground vs non-ground
      // before contour generation. Vegetation and buildings distort contours
      // if not filtered. Uses CSF algorithm (only if enough points).
      let groundPoints = points;
      try {
        if (points.length >= 20) {
          const { classifyPointCloud, extractGroundPoints } = await import('@/lib/topo/pointCloudClassification');
          const classified = classifyPointCloud(points.map(p => ({
            x: p.easting, y: p.northing, z: p.elevation,
          })));
          const ground = extractGroundPoints(classified);
          if (ground.length >= 3) {
            groundPoints = ground.map((p, i) => ({
              name: `G${i}`,
              easting: p.x, northing: p.y, elevation: p.z,
            }));
          }
        }
      } catch {
        // DTM filtering failed — use all points
      }

      // AUDIT FIX (2026-07-03): Pass breaklines to both the contour
      // generator and the TIN builder so triangles don't cross terrain
      // discontinuities.
      const result = await generateContoursAsync(groundPoints, contourInterval, {
        indexInterval,
        breaklines: breaklines.length > 0 ? breaklines : undefined,
        onProgress: p => setGenerateProgress(p),
      });
      setContours(result);

      const surface = await buildTINSurfaceAsync(
        groundPoints,
        breaklines.length > 0 ? breaklines : undefined,
        {
          onProgress: p => setGenerateProgress(p),
        },
      );
      setTinSurface(surface);

      // Compute volume relative to minimum elevation
      const minElev = Math.min(...groundPoints.map(p => p.elevation));
      const vol = computeVolumeFromTIN(surface, minElev);
      setVolumeResult(vol);
    } catch (err) {
      setGenerateError(err instanceof Error ? err.message : 'Contour generation failed.');
    } finally {
      setIsGenerating(false);
      setGenerateProgress(1);
      setUsingWorker(false);
    }
  }, [points, contourInterval, indexMultiplier, breaklines]);

  // ─── Export handlers ─────────────────────────────────────────────────────

  const exportDXF = useCallback(() => {
    if (!contours.length || !bounds) return;
    const dxf = generateDXF(contours, bounds);
    downloadBlob(dxf, 'contours.dxf', 'application/dxf');
  }, [contours, bounds]);

  const exportSVG = useCallback(() => {
    if (!contours.length || !bounds) return;
    const svg = generateSVGExport(contours, bounds, points);
    downloadBlob(svg, 'contours.svg', 'image/svg+xml');
  }, [contours, bounds, points]);

  const exportCSV = useCallback(() => {
    if (!contours.length) return;
    const csv = generateContourCSV(contours);
    downloadBlob(csv, 'contours.csv', 'text/csv');
  }, [contours]);

  const exportGeoJSON = useCallback(() => {
    if (!contours.length) return;
    const geojson = generateGeoJSON(contours);
    downloadBlob(geojson, 'contours.geojson', 'application/geo+json');
  }, [contours]);

  // ─── SVG rendering computations ──────────────────────────────────────────

  const svgElements = useMemo<SvgElements | null>(() => {
    if (!contours.length || !bounds) return null;

    const usableW = SVG_WIDTH - 2 * MARGIN;
    const usableH = SVG_HEIGHT - 2 * MARGIN;
    const minE = bounds.minE;
    const maxE = bounds.maxE;
    const minN = bounds.minN;
    const maxN = bounds.maxN;
    const rangeE = maxE - minE || 1;
    const rangeN = maxN - minN || 1;

    const contourElevations = contours.map(c => c.elevation);
    const minElev = Math.min(...contourElevations);
    const maxElev = Math.max(...contourElevations);

    function toSvgX(e: number) { return MARGIN + ((e - minE) / rangeE) * usableW; }
    function toSvgY(n: number) { return MARGIN + ((maxN - n) / rangeN) * usableH; }

    // Subsample spot height points for rendering if too many
    const spotStep = Math.max(1, Math.floor(points.length / 2000));
    const spotSampled = points.filter((_, i) => i % spotStep === 0);

    return {
      usableW, usableH, rangeE, rangeN, minElev, maxElev, toSvgX, toSvgY, spotSampled,
      viewBox: `0 0 ${SVG_WIDTH} ${SVG_HEIGHT}`,
    };
  }, [contours, bounds, points]);

  // ─── Tab definitions ──────────────────────────────────────────────────────

  const tabs: { id: TabId; label: string; disabled?: boolean }[] = [
    { id: 'import', label: 'Import Points' },
    { id: 'breaklines', label: `Breaklines${breaklines.length > 0 ? ` (${breaklines.length})` : ''}`, disabled: points.length < 3 },
    { id: 'settings', label: 'Settings & Generate', disabled: points.length < 3 },
    { id: 'map', label: 'Contour Map', disabled: contours.length === 0 },
    { id: 'export', label: 'Export', disabled: contours.length === 0 },
  ];

  // ─── Render ───────────────────────────────────────────────────────────────

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      {/* Custom header (mutation-plan pattern) */}
      <div className="flex items-center gap-3 mb-2">
        <div className="p-2 bg-emerald-500/10 rounded-lg">
          <Mountain className="h-6 w-6 text-emerald-500" />
        </div>
        <div>
          <h1 className="text-2xl font-bold">{t('tools.contourGenerator')}</h1>
          <p className="text-sm text-zinc-400">
            {t('tools.contourGeneratorDesc')}
          </p>
        </div>
      </div>

      <ComputeLimitNotice
        tool="Contour generation"
        message="The web contour engine runs in a browser worker and is tuned for typical field datasets. For very large point clouds, dense contours, or batch terrain processing, the METARDU desktop app runs the full engine locally — no size limits, no uploads."
      />

      {/* Tab bar */}
      <div className="flex gap-2 mt-6 mb-6 flex-wrap">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            disabled={tab.disabled}
            className={`px-4 py-2 rounded text-sm font-medium transition-colors ${
              tab.disabled
                ? 'opacity-40 cursor-not-allowed bg-[var(--bg-tertiary)] text-zinc-600'
                : activeTab === tab.id
                  ? 'bg-[var(--accent)] text-black'
                  : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)] hover:text-[var(--accent)]'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* ═══════════════════ TAB 1: Import Points ═══════════════════ */}
      {activeTab === 'import' && (
        <ImportTab
          rawText={rawText}
          setRawText={setRawText}
          fileName={fileName}
          points={points}
          parseErrors={parseErrors}
          importStats={importStats}
          isParsing={isParsing}
          bounds={bounds}
          fileInputRef={fileInputRef}
          handleDropZone={handleDropZone}
          handleFileInput={handleFileInput}
          handlePasteParse={handlePasteParse}
          handleLoadDemo={handleLoadDemo}
        />
      )}

      {/* ═══════════════════ TAB 1.5: Breaklines ═══════════════════ */}
      {activeTab === 'breaklines' && (
        <BreaklineTab
          points={points}
          breaklines={breaklines}
          setBreaklines={setBreaklines}
        />
      )}

      {/* ═══════════════════ TAB 2: Settings & Generate ═══════════════════ */}
      {activeTab === 'settings' && (
        <SettingsTab
          contourInterval={contourInterval}
          setContourInterval={setContourInterval}
          indexMultiplier={indexMultiplier}
          setIndexMultiplier={setIndexMultiplier}
          points={points}
          bounds={bounds}
          isGenerating={isGenerating}
          generateError={generateError}
          handleGenerate={handleGenerate}
          contours={contours}
          tinSurface={tinSurface}
          volumeResult={volumeResult}
          generateProgress={generateProgress}
          usingWorker={usingWorker}
          breaklineCount={breaklines.length}
        />
      )}

      {/* ═══════════════════ TAB 3: Contour Map ═══════════════════ */}
      {activeTab === 'map' && svgElements && bounds && (
        <MapTab
          contours={contours}
          bounds={bounds}
          points={points}
          contourInterval={contourInterval}
          svgElements={svgElements}
        />
      )}

      {/* ═══════════════════ TAB 4: Export ═══════════════════ */}
      {activeTab === 'export' && (
        <ExportTab
          exportDXF={exportDXF}
          exportSVG={exportSVG}
          exportCSV={exportCSV}
          exportGeoJSON={exportGeoJSON}
          volumeResult={volumeResult}
          bounds={bounds}
        />
      )}
    </div>
  );
}

