'use client'

import { useState, useCallback } from 'react'
import { Route, AlertCircle, Map as MapIcon } from 'lucide-react'
import { buildAlignment, enToChainageOffset, organizeShotsByChainage, formatChainage, type PIPoint, type FieldShot, type CrossSectionGroup } from '@/lib/survey/corridorEngine'

export default function CorridorPage() {
  const [piInput, setPiInput] = useState('')
  const [shotsInput, setShotsInput] = useState('')
  const [interval, setInterval] = useState('20')
  const [crossSections, setCrossSections] = useState<CrossSectionGroup[]>([])
  const [alignmentLength, setAlignmentLength] = useState(0)
  const [error, setError] = useState('')

  const handleOrganize = useCallback(() => {
    setError(''); setCrossSections([]); setAlignmentLength(0)
    try {
      // Parse PI points: id,easting,northing
      const pis: PIPoint[] = piInput.trim().split('\n').map(line => {
        const cols = line.split(',').map(c => c.trim())
        return { id: cols[0], e: parseFloat(cols[1]), n: parseFloat(cols[2]) }
      }).filter(p => p.id && !isNaN(p.e) && !isNaN(p.n))

      if (pis.length < 2) { setError('Need at least 2 PI points (format: id,easting,northing)'); return }

      // Parse field shots: easting,northing,rl
      const shots: FieldShot[] = shotsInput.trim().split('\n').map(line => {
        const cols = line.split(',').map(c => parseFloat(c.trim()))
        return { e: cols[0], n: cols[1], rl: cols[2] }
      }).filter(s => !isNaN(s.e) && !isNaN(s.n) && !isNaN(s.rl))

      if (shots.length < 3) { setError('Need at least 3 field shots (format: easting,northing,rl)'); return }

      const alignment = buildAlignment(pis)
      const groups = organizeShotsByChainage(shots, alignment, parseFloat(interval))
      setCrossSections(groups)
      setAlignmentLength(alignment.totalLength)
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed') }
  }, [piInput, shotsInput, interval])

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"

  return (
    <div className="min-h-screen p-6 max-w-6xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Corridor / Chainage Mode</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Define an alignment from PI points → auto-organize field shots into cross-sections by chainage station. Designed for KeNHA road corridors.</p>

      <div className="grid grid-cols-2 gap-4 mb-4">
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Route className="w-4 h-4" /> PI Points (id,easting,northing)</h2>
          <textarea value={piInput} onChange={e => setPiInput(e.target.value)} className={inputCls + ' h-40 font-mono'} placeholder="PI1,264000,9861000&#10;PI2,264100,9861100&#10;PI3,264200,9861200" />
        </div>
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><MapIcon className="w-4 h-4" /> Field Shots (easting,northing,rl)</h2>
          <textarea value={shotsInput} onChange={e => setShotsInput(e.target.value)} className={inputCls + ' h-40 font-mono'} placeholder="264000,9861000,1500&#10;264010,9861000,1500.1&#10;263990,9861000,1499.9" />
        </div>
      </div>

      <div className="flex gap-4 items-end mb-4">
        <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="cross-section-interval-m">Cross-section interval (m)</label><input value={interval} onChange={e => setInterval(e.target.value)} className={inputCls + ' w-32'} /></div>
        <button onClick={handleOrganize} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Organize by Chainage</button>
      </div>

      {error && <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-4 text-xs text-red-400 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}

      {crossSections.length > 0 && (
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <div className="flex justify-between items-center mb-3">
            <h2 className="text-sm font-semibold">Cross-Sections ({crossSections.length} stations)</h2>
            <span className="text-[10px] text-[var(--text-muted)]">Alignment length: {alignmentLength.toFixed(1)} m</span>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead><tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                <th className="text-left py-2 px-1">Chainage</th><th className="text-right">Shots</th><th className="text-right">Left (m)</th><th className="text-right">Right (m)</th><th className="text-right">CL RL</th>
              </tr></thead>
              <tbody>
                {crossSections.map(cs => (
                  <tr key={cs.chainage} className="border-b border-[var(--border-color)]/30 text-[var(--text-secondary)]">
                    <td className="py-1.5 px-1 font-mono font-bold text-[var(--accent)]">{cs.label}</td>
                    <td className="text-right font-mono">{cs.shots.length}</td>
                    <td className="text-right font-mono">{cs.leftOffset.toFixed(1)}</td>
                    <td className="text-right font-mono">{cs.rightOffset.toFixed(1)}</td>
                    <td className="text-right font-mono">{cs.centrelineRL !== null ? cs.centrelineRL.toFixed(3) : '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="mt-3 text-[10px] text-[var(--text-muted)]">
            {crossSections.reduce((sum, cs) => sum + cs.shots.length, 0)} total shots organized into {crossSections.length} cross-sections
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { compoundCurveSolved, reverseCurveSolved, simpleCurveSolved } from '@/lib/engine/solution/wrappers/curves'
import { PageHeader } from '@/components/shared/PageHeader'
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers'
import { useLanguage } from '@/lib/i18n/LanguageContext'
import { SpiralAlignmentTab } from '@/components/tools/SpiralAlignmentTab'
import { SimpleCurveDiagram } from '@/components/tools/SimpleCurveDiagram'
import { VerticalCurveProfile } from '@/components/tools/VerticalCurveProfile'

type CurveType = 'simple' | 'compound' | 'reverse' | 'vertical' | 'spiral-alignment';

export default function CurvesCalculator() {
  const { t } = useLanguage()
  const [curveType, setCurveType] = useState<CurveType>('simple');
  const [input, setInput] = useState({
    radius: '300',
    defDeg: '20',
    defMin: '00',
    defSec: '00',
    piChain: '2500.00',
    interval: '20',
    r1: '200',
    r2: '400',
    delta1: '15',
    delta2: '15',
    commonChainage: '1000',
    r1_rev: '250',
    r2_rev: '300',
    abDistance: '150'
  });
  const [result, setResult] = useState<null | { type: CurveType; title?: string; steps: SolutionStep[]; stakePoints?: any[]; stakeout?: any }>(null);
  const [rdmValidation, setRdmValidation] = useState<any>(null);

  const [vInput, setVInput] = useState({
    g1: '-4.0',
    g2: '2.5',
    vpiChainageKm: '2',
    vpiChainageM: '500',
    vpiRL: '1890.00',
    kValue: '40',
    useLength: false,
    length: '200',
  });
  const [vResult, setVResult] = useState<any>(null);
  const [vError, setVError] = useState('');

  const MIN_K: Record<number, number> = {
    120: 160, 110: 130, 100: 100, 90: 80, 80: 50,
    70: 35, 65: 25, 60: 20, 50: 15, 40: 9, 30: 5,
  };
  const designSpeedOptions = [30, 40, 50, 60, 65, 70, 80, 90, 100, 110, 120];
  const [designSpeed, setDesignSpeed] = useState(80);

  const calcVertical = () => {
    setVError('');
    const G1 = parseFloat(vInput.g1);
    const G2 = parseFloat(vInput.g2);
    const vpiKm = parseInt(vInput.vpiChainageKm) || 0;
    const vpiM = parseFloat(vInput.vpiChainageM) || 0;
    const vpiChainage = vpiKm * 1000 + vpiM;
    const vpiRL = parseFloat(vInput.vpiRL);
    const K = parseFloat(vInput.kValue);
    const L = parseFloat(vInput.length);

    if (isNaN(G1) || isNaN(G2) || isNaN(vpiChainage) || isNaN(vpiRL)) {
      setVError('Enter all numeric values.'); return;
    }
    if (G1 === G2) { setVError('G1 and G2 cannot be equal.'); return; }

    const A = G2 - G1;
    const curveLen = vInput.useLength && !isNaN(L) ? L : K * Math.abs(A);
    if (curveLen <= 0) { setVError('Curve length must be positive.'); return; }

    const BVC_chainage = vpiChainage - curveLen / 2;
    const EVC_chainage = vpiChainage + curveLen / 2;
    const BVC_RL = vpiRL - G1 * (curveLen / 2) / 100;
    const EVC_RL = vpiRL + G2 * (curveLen / 2) / 100;

    const rlAtEVC = BVC_RL + (G1 / 100) * curveLen + (A / (200 * curveLen)) * curveLen * curveLen;
    const arithmeticCheck = Math.abs(rlAtEVC - EVC_RL);
    const arithPass = arithmeticCheck < 0.001;

    const isCrest = A < 0;
    let peakPoint: { chainage: number; RL: number } | null = null;
    if (isCrest) {
      const xPeak = -G1 * curveLen / A;
      if (xPeak > 0 && xPeak < curveLen) {
        const RL_peak = BVC_RL + (G1 / 100) * xPeak + (A / (200 * curveLen)) * xPeak * xPeak;
        peakPoint = { chainage: BVC_chainage + xPeak, RL: RL_peak };
      }
    }

    const interval = 20;
    const tableRows: Array<{ chainage: number; x: number; RL: number; grade: number }> = [];
    for (let x = 0; x <= curveLen; x += interval) {
      const ch = BVC_chainage + x;
      const RL = BVC_RL + (G1 / 100) * x + (A / (200 * curveLen)) * x * x;
      const grade = G1 + (A / curveLen) * x;
      tableRows.push({ chainage: ch, x, RL, grade });
    }
    if (tableRows.length > 0 && tableRows[tableRows.length - 1].x !== curveLen) {
      const x = curveLen;
      const ch = BVC_chainage + x;
      const RL = BVC_RL + (G1 / 100) * x + (A / (200 * curveLen)) * x * x;
      const grade = G2;
      tableRows.push({ chainage: ch, x, RL, grade });
    }

    const minK = MIN_K[designSpeed] ?? 40;
    const kPass = curveLen / Math.abs(A) >= minK;

    const steps: SolutionStep[] = [
      { label: 'Algebraic grade difference', formula: 'A = G2 - G1', computation: `${A.toFixed(4)} %` },
      { label: 'Curve length', formula: vInput.useLength ? 'L given directly' : 'L = K × |A|', computation: `${curveLen.toFixed(4)} m` },
      { label: 'BVC chainage', formula: 'VPI - L/2', computation: `${BVC_chainage.toFixed(3)} m` },
      { label: 'EVC chainage', formula: 'VPI + L/2', computation: `${EVC_chainage.toFixed(3)} m` },
      { label: 'BVC reduced level', formula: 'VPI RL - G1×(L/2)/100', computation: `${BVC_RL.toFixed(4)} m` },
      { label: 'EVC reduced level (grade)', formula: 'VPI RL + G2×(L/2)/100', computation: `${EVC_RL.toFixed(4)} m` },
      { label: 'EVC RL from parabola', formula: 'y = BVC_RL + G1×x/100 + A×x²/(200L)', computation: `${rlAtEVC.toFixed(4)} m` },
      { label: 'Arithmetic check', formula: '|EVC_grade - EVC_formula| < 0.001 m', result: `${arithmeticCheck.toFixed(6)} m — ${arithPass ? 'PASS' : 'FAIL'}` },
      { label: 'K-value', formula: 'L / |A|', result: `${(curveLen / Math.abs(A)).toFixed(2)} m/%` },
      { label: `RDM 1.3 min K @ ${designSpeed} km/h`, formula: 'RDM 1.3 Table 3-1', result: `min K = ${minK} — ${kPass ? 'PASS' : 'FAIL'}` },
    ];

    setVResult({
      steps,
      A, curveLen, BVC_chainage, EVC_chainage, BVC_RL, EVC_RL,
      vpiChainage, vpiRL,
      arithmeticCheck, arithPass, peakPoint, tableRows, minK, kPass,
      K_computed: curveLen / Math.abs(A),
      isCrest,
      designSpeed,
    });
  };

  const calculate = async () => {
    if (curveType === 'simple') {
      const R = parseFloat(input.radius);
      const piChainage = parseFloat(input.piChain);
      const interval = parseFloat(input.interval);
      const deflectionDec = (parseFloat(input.defDeg) || 0) + (parseFloat(input.defMin) || 0) / 60 + (parseFloat(input.defSec) || 0) / 3600
      if (isNaN(R) || isNaN(deflectionDec) || isNaN(piChainage) || isNaN(interval)) return;
      const s = simpleCurveSolved({ radius: R, deflectionDeg: deflectionDec, piChainage, interval });
      setResult({ type: 'simple', title: s.solution.title, steps: s.steps, stakePoints: s.result.points, stakeout: s.result });
    } else if (curveType === 'compound') {
      const R1 = parseFloat(input.r1);
      const R2 = parseFloat(input.r2);
      const delta1 = parseFloat(input.delta1);
      const delta2 = parseFloat(input.delta2);
      const commonChainage = parseFloat(input.commonChainage);
      if ([R1, R2, delta1, delta2, commonChainage].some((n: any) => isNaN(n))) return;
      const s = compoundCurveSolved({ R1, R2, delta1Deg: delta1, delta2Deg: delta2, junctionChainage: commonChainage });
      setResult({ type: 'compound', title: s.solution.title, steps: s.steps });
    } else if (curveType === 'reverse') {
      const R1 = parseFloat(input.r1_rev);
      const R2 = parseFloat(input.r2_rev);
      const AB = parseFloat(input.abDistance);
      if (isNaN(R1) || isNaN(R2) || isNaN(AB)) return;
      const s = reverseCurveSolved({ R1, R2, AB });
      setResult({ type: 'reverse', title: s.solution.title, steps: s.steps });
    }

    try {
      const radius = curveType === 'simple'
        ? parseFloat(input.radius || '0')
        : curveType === 'compound'
        ? Math.min(parseFloat(input.r1 || '0'), parseFloat(input.r2 || '0'))
        : Math.min(parseFloat(input.r1_rev || '0'), parseFloat(input.r2_rev || '0'))
      const rdmRes = await fetch('/api/validate-geometry', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ radius, designSpeed: 80, terrain: 'rolling', gradient: 0 })
      });
      const rdmData = await rdmRes.json();
      setRdmValidation(rdmData);
    } catch {}
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.curves')}
        subtitle={t('tools.curvesDesc')}
        reference="RDM 1.1 (2025) Geometric Design | Kenya Highway Design Manual"
      />

      <div className="flex gap-2 mb-6 flex-wrap">
        <button onClick={() => { setCurveType('simple'); setResult(null); setVResult(null); }} className={`px-4 py-2 rounded-lg font-medium ${curveType === 'simple' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'}`}>Simple Curve</button>
        <button onClick={() => { setCurveType('compound'); setResult(null); setVResult(null); }} className={`px-4 py-2 rounded-lg font-medium ${curveType === 'compound' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'}`}>Compound Curve</button>
        <button onClick={() => { setCurveType('reverse'); setResult(null); setVResult(null); }} className={`px-4 py-2 rounded-lg font-medium ${curveType === 'reverse' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'}`}>Reverse Curve</button>
        <button onClick={() => { setCurveType('vertical'); setResult(null); setVResult(null); }} className={`px-4 py-2 rounded-lg font-medium ${curveType === 'vertical' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'}`}>Vertical Curve</button>
        <button onClick={() => { setCurveType('spiral-alignment'); setResult(null); setVResult(null); }} className={`px-4 py-2 rounded-lg font-medium ${curveType === 'spiral-alignment' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-[var(--text-primary)]'}`} title="Tier 2: Spiral-to-curve alignment engine (clothoid transitions)">Spiral Alignment</button>
      </div>

      {curveType === 'spiral-alignment' ? (
        <SpiralAlignmentTab />
      ) : (
      <div className="grid md:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-6">
            {curveType === 'simple' && (
              <>
                <div className="grid grid-cols-2 gap-4">
                  <div><label htmlFor="cv-radius" className="label">Radius (m)</label><input id="cv-radius" className="input" value={input.radius} onChange={e => setInput({...input, radius: e.target.value})} /></div>
                  <div><div className="label">Deflection (DMS)</div>
                    <div className="grid grid-cols-3 gap-1">
                      <input aria-label="Deflection degrees" className="input" value={input.defDeg} onChange={e => setInput({...input, defDeg: e.target.value})} />
                      <input aria-label="Deflection minutes" className="input" value={input.defMin} onChange={e => setInput({...input, defMin: e.target.value})} />
                      <input aria-label="Deflection seconds" className="input" value={input.defSec} onChange={e => setInput({...input, defSec: e.target.value})} />
                    </div>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4 mt-4">
                  <div><label htmlFor="cv-pi-chain" className="label">PI Chainage (m)</label><input id="cv-pi-chain" className="input" value={input.piChain} onChange={e => setInput({...input, piChain: e.target.value})} /></div>
                  <div><label htmlFor="cv-interval" className="label">Interval (m)</label><input id="cv-interval" className="input" value={input.interval} onChange={e => setInput({...input, interval: e.target.value})} /></div>
                </div>
              </>
            )}
            {curveType === 'compound' && (
              <>
                <div className="grid grid-cols-2 gap-4">
                  <div><label htmlFor="cv-r1" className="label">Radius R1 (m)</label><input id="cv-r1" className="input" value={input.r1} onChange={e => setInput({...input, r1: e.target.value})} /></div>
                  <div><label htmlFor="cv-r2" className="label">Radius R2 (m)</label><input id="cv-r2" className="input" value={input.r2} onChange={e => setInput({...input, r2: e.target.value})} /></div>
                </div>
                <div className="grid grid-cols-2 gap-4 mt-4">
                  <div><label htmlFor="cv-delta1" className="label">Δ1 (degrees)</label><input id="cv-delta1" className="input" value={input.delta1} onChange={e => setInput({...input, delta1: e.target.value})} /></div>
                  <div><label htmlFor="cv-delta2" className="label">Δ2 (degrees)</label><input id="cv-delta2" className="input" value={input.delta2} onChange={e => setInput({...input, delta2: e.target.value})} /></div>
                </div>
                <div className="mt-4"><label htmlFor="cv-common-chain" className="label">Junction Chainage (m)</label><input id="cv-common-chain" className="input" value={input.commonChainage} onChange={e => setInput({...input, commonChainage: e.target.value})} /></div>
              </>
            )}
            {curveType === 'reverse' && (
              <>
                <div className="grid grid-cols-2 gap-4">
                  <div><label htmlFor="cv-r1-rev" className="label">Radius R1 (m)</label><input id="cv-r1-rev" className="input" value={input.r1_rev} onChange={e => setInput({...input, r1_rev: e.target.value})} /></div>
                  <div><label htmlFor="cv-r2-rev" className="label">Radius R2 (m)</label><input id="cv-r2-rev" className="input" value={input.r2_rev} onChange={e => setInput({...input, r2_rev: e.target.value})} /></div>
                </div>
                <div className="mt-4"><label htmlFor="cv-ab-dist" className="label">Distance AB (m)</label><input id="cv-ab-dist" className="input" value={input.abDistance} onChange={e => setInput({...input, abDistance: e.target.value})} /></div>
              </>
            )}
            {curveType === 'vertical' && (
              <>
                <p className="text-xs text-[var(--text-muted)] mb-3">Source: RDM 1.3 Kenya August 2023, Section 5.4 | Ghilani &amp; Wolf, Elementary Surveying 16th Ed., Chapter 25</p>
                <div className="grid grid-cols-2 gap-4">
                  <div><label htmlFor="cv-g1" className="label">G1 — Entry Grade (%)</label><input id="cv-g1" className="input" value={vInput.g1} onChange={e => setVInput({...vInput, g1: e.target.value})} /></div>
                  <div><label htmlFor="cv-g2" className="label">G2 — Exit Grade (%)</label><input id="cv-g2" className="input" value={vInput.g2} onChange={e => setVInput({...vInput, g2: e.target.value})} /></div>
                </div>
                <div className="grid grid-cols-3 gap-2 mt-4">
                  <div><label htmlFor="cv-vpi-km" className="label">VPI km</label><input id="cv-vpi-km" className="input" value={vInput.vpiChainageKm} onChange={e => setVInput({...vInput, vpiChainageKm: e.target.value})} /></div>
                  <div><label htmlFor="cv-vpi-m" className="label">VPI m</label><input id="cv-vpi-m" className="input" value={vInput.vpiChainageM} onChange={e => setVInput({...vInput, vpiChainageM: e.target.value})} /></div>
                  <div><label htmlFor="cv-vpi-rl" className="label">VPI RL (m)</label><input id="cv-vpi-rl" className="input" value={vInput.vpiRL} onChange={e => setVInput({...vInput, vpiRL: e.target.value})} /></div>
                </div>
                <div className="mt-4">
                  <label className="flex items-center gap-2 text-sm cursor-pointer">
                    <input type="checkbox" checked={vInput.useLength} onChange={e => setVInput({...vInput, useLength: e.target.checked})} className="accent-[var(--accent)]" />
                    <span>Enter curve length directly</span>
                  </label>
                </div>
                {vInput.useLength ? (
                  <div className="mt-2"><label htmlFor="cv-length" className="label">Curve Length L (m)</label><input id="cv-length" className="input" value={vInput.length} onChange={e => setVInput({...vInput, length: e.target.value})} /></div>
                ) : (
                  <div className="mt-2"><label htmlFor="cv-kvalue" className="label">K-value (m/%)</label><input id="cv-kvalue" className="input" value={vInput.kValue} onChange={e => setVInput({...vInput, kValue: e.target.value})} /></div>
                )}
                <div className="mt-4">
                  <div className="label">Design Speed (km/h) — for K compliance</div>
                  <div className="flex flex-wrap gap-2 mt-1">
                    {designSpeedOptions.map((s: any) => (
                      <button key={s} onClick={() => setDesignSpeed(s)}
                        className={`px-2 py-1 text-xs rounded border ${designSpeed === s ? 'bg-[var(--accent)] text-black border-[var(--accent)]' : 'border-[var(--border-color)] text-[var(--text-secondary)]'}`}>
                        {s}
                      </button>
                    ))}
                  </div>
                </div>
              </>
            )}
          </div>
          <div className="space-y-3">
            <button
              onClick={curveType === 'vertical' ? calcVertical : calculate}
              className="w-full px-6 py-4 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-bold rounded-lg">
              {curveType === 'vertical' ? 'Calculate Vertical Curve' : t('toolUI.calculate')}
            </button>
            {(result || vResult) && (
              <div className="flex gap-2">
                <button
                  onClick={() => {
                    if (curveType === 'vertical' && vResult) {
                      generatePDF(
                        { title: 'Vertical Curve Computation', reference: 'RDM 1.3 Kenya | RDM 1.1 (2025)' },
                        [
                          { title: 'Vertical Curve Parameters', rows: [
                            { label: 'Curve Type', value: vResult.isCrest ? 'Crest' : 'Sag' },
                            { label: 'Curve Length L', value: `${vResult.curveLen.toFixed(3)} m` },
                            { label: 'Algebraic A', value: `${vResult.A.toFixed(4)} %` },
                            { label: 'K-value', value: `${vResult.K_computed.toFixed(2)} m/%` },
                            { label: 'BVC Chainage', value: `${vResult.BVC_chainage.toFixed(3)} m` },
                            { label: 'EVC Chainage', value: `${vResult.EVC_chainage.toFixed(3)} m` },
                            { label: 'BVC RL', value: `${vResult.BVC_RL.toFixed(4)} m` },
                            { label: 'EVC RL', value: `${vResult.EVC_RL.toFixed(4)} m` },
                            { label: 'Arithmetic Check', value: vResult.arithPass ? 'PASS' : 'FAIL' },
                            { label: 'K-Compliance', value: vResult.kPass ? 'PASS' : 'FAIL' },
                          ]},
                        ],
                        [
                          { title: 'RL Table — 20m Intervals', headers: ['Chainage (m)', 'x from BVC (m)', 'RL (m)', 'Grade (%)'], rows: vResult.tableRows.map((r: any) => [r.chainage.toFixed(3), r.x.toFixed(3), r.RL.toFixed(4), r.grade.toFixed(4)]) },
                        ],
                      )
                    } else if (result && result.steps) {
                      generatePDF(
                        { title: `${curveType.charAt(0).toUpperCase() + curveType.slice(1)} Curve Data Sheet`, reference: 'RDM 1.1 (2025) | Kenya Highway Design Manual' },
                        [
                          { title: 'Computation Steps', rows: result.steps.map((s: SolutionStep) => ({ label: s.label, value: s.result || s.computation || '—' })) },
                        ],
                        result.stakePoints ? [
                          { title: 'Stakeout Table', headers: ['Chainage', 'Chord (m)', 'Deflection'], rows: result.stakePoints.map((p: any) => [p.chainage.toFixed(3), p.chordLength?.toFixed(3) ?? '—', p.totalDeflection ?? p.deflectionAngle ?? '—']) },
                        ] : [],
                      )
                    }
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportPdf')}
                </button>
                <button
                  onClick={() => {
                    if (curveType === 'vertical' && vResult) {
                      const csv = toCSV(
                        ['Chainage (m)', 'x from BVC (m)', 'RL (m)', 'Grade (%)'],
                        vResult.tableRows.map((r: any) => [r.chainage.toFixed(3), r.x.toFixed(3), r.RL.toFixed(4), r.grade.toFixed(4)]),
                      )
                      downloadCSV(csv, 'vertical-curve-data')
                    } else if (result) {
                      const csv = toCSV(
                        ['Parameter', 'Value'],
                        result.steps.map((s: SolutionStep) => [s.label, s.result || s.computation || '—']),
                      )
                      downloadCSV(csv, `${curveType}-curve-data`)
                    }
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportCsv')}
                </button>
              </div>
            )}
          </div>
        </div>

        {vError && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{vError}</div>}

        {result && curveType !== 'vertical' && (
          <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-6">
            <SolutionStepsRenderer title={result.title} steps={result.steps} />
            {result.type === 'simple' && result.stakeout?.elements && (
              <div className="mt-6">
                <SimpleCurveDiagram
                  radius={result.stakeout.elements.radius}
                  deflectionDeg={result.stakeout.elements.deflectionAngle}
                  tangentLength={result.stakeout.elements.tangentLength}
                  arcLength={result.stakeout.elements.arcLength}
                  longChord={result.stakeout.elements.longChord}
                  externalDistance={result.stakeout.elements.externalDistance}
                  midOrdinate={result.stakeout.elements.midOrdinate}
                  pcChainage={result.stakeout.pcChainage}
                  piChainage={result.stakeout.piChainage}
                  ptChainage={result.stakeout.ptChainage}
                />
              </div>
            )}
            {result.type === 'simple' && result.stakePoints && result.stakePoints.length > 0 ? (
              <div className="mt-6">
                <h3 className="font-semibold text-[var(--text-primary)] mb-3">Stakeout Table</h3>
                <div className="max-h-56 overflow-y-auto text-sm border border-[var(--border-color)] rounded">
                  <table className="w-full">
                    <thead>
                      <tr className="bg-gray-950/40">
                        <th className="text-left px-3 py-2">Chainage</th>
                        <th className="text-right px-3 py-2">Chord (m)</th>
                        <th className="text-right px-3 py-2">Deflection</th>
                      </tr>
                    </thead>
                    <tbody>
                      {result.stakePoints.map((p: any, i: number) => (
                        <tr key={`item-${i}`} className="border-t border-[var(--border-color)]">
                          <td className="px-3 py-2 font-mono">{p.chainage.toFixed(3)}</td>
                          <td className="px-3 py-2 text-right font-mono">{p.chordLength?.toFixed?.(3) ?? '—'}</td>
                          <td className="px-3 py-2 text-right font-mono">{p.totalDeflection ?? p.deflectionAngle ?? '—'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ) : null}
            {rdmValidation && (
              <div className="mt-6 p-4 border rounded-lg" style={{ backgroundColor: rdmValidation.status === 'GREEN' ? '#10b98120' : rdmValidation.status === 'YELLOW' ? '#f59e0b20' : '#ef444420' }}>
                <h4 className="font-bold mb-2">RDM 1.3 Compliance: <span style={{ color: rdmValidation.status === 'GREEN' ? '#10b981' : rdmValidation.status === 'YELLOW' ? '#f59e0b' : '#ef4444' }}>{rdmValidation.status}</span></h4>
                {rdmValidation.flags.map((flag: string, i: number) => (
                  <p key={`item-${i}`} className="text-sm mb-1">{flag}</p>
                ))}
              </div>
            )}
          </div>
        )}

        {vResult && curveType === 'vertical' && (
          <div className="space-y-4">
            <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-6">
              <SolutionStepsRenderer title="Vertical Curve Computation" steps={vResult.steps} />
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {[
                ['Curve Type', vResult.isCrest ? 'Crest' : 'Sag'],
                ['Length L', `${vResult.curveLen.toFixed(3)} m`],
                ['Algebraic A', `${vResult.A.toFixed(4)} %`],
                ['K-value', `${vResult.K_computed.toFixed(2)} m/%`],
                ['BVC Ch', `${vResult.BVC_chainage.toFixed(3)} m`],
                ['EVC Ch', `${vResult.EVC_chainage.toFixed(3)} m`],
                ['BVC RL', `${vResult.BVC_RL.toFixed(4)} m`],
                ['EVC RL', `${vResult.EVC_RL.toFixed(4)} m`],
              ].map(([label, value]) => (
                <div key={label} className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded p-3">
                  <p className="text-xs text-[var(--text-muted)]">{label}</p>
                  <p className="text-sm font-mono text-[var(--text-primary)]">{value}</p>
                </div>
              ))}
            </div>

            {vResult.tableRows && vResult.tableRows.length > 0 && (
              <VerticalCurveProfile
                rows={vResult.tableRows}
                bvcChainage={vResult.BVC_chainage}
                evcChainage={vResult.EVC_chainage}
                vpiChainage={vResult.vpiChainage}
                bvcRL={vResult.BVC_RL}
                evcRL={vResult.EVC_RL}
                vpiRL={vResult.vpiRL}
                g1={parseFloat(vInput.g1) || 0}
                g2={parseFloat(vInput.g2) || 0}
                isCrest={vResult.isCrest}
                peakPoint={vResult.peakPoint}
              />
            )}

            <div className="flex gap-3 flex-wrap">
              <div className="px-3 py-2 rounded border font-medium text-sm" style={{ backgroundColor: vResult.arithPass ? '#10b98120' : '#ef444420', borderColor: vResult.arithPass ? '#10b981' : '#ef4444', color: vResult.arithPass ? '#10b981' : '#ef4444' }}>
                Arithmetic Check {vResult.arithPass ? 'PASS' : 'FAIL'} ({vResult.arithmeticCheck.toFixed(6)} m)
              </div>
              <div className="px-3 py-2 rounded border font-medium text-sm" style={{ backgroundColor: vResult.kPass ? '#10b98120' : '#ef444420', borderColor: vResult.kPass ? '#10b981' : '#ef4444', color: vResult.kPass ? '#10b981' : '#ef4444' }}>
                K-Compliance @ {vResult.designSpeed} km/h {vResult.kPass ? 'PASS' : 'FAIL'} (min K = {vResult.minK})
              </div>
            </div>

            {vResult.peakPoint && (
              <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
                <h4 className="font-semibold text-sm mb-2">{vResult.isCrest ? 'Crest Peak' : 'Sag Low Point'}</h4>
                <div className="grid grid-cols-2 gap-3">
                  <div><p className="text-xs text-[var(--text-muted)]">Chainage</p><p className="font-mono text-sm">{vResult.peakPoint.chainage.toFixed(3)} m</p></div>
                  <div><p className="text-xs text-[var(--text-muted)]">Reduced Level</p><p className="font-mono text-sm">{vResult.peakPoint.RL.toFixed(4)} m</p></div>
                </div>
              </div>
            )}

            <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl overflow-hidden">
              <div className="px-4 py-3 border-b border-[var(--border-color)]">
                <h4 className="font-semibold text-sm">RL Table — 20m Intervals</h4>
              </div>
              <div className="overflow-x-auto max-h-64">
                <table className="w-full text-xs font-mono">
                  <thead>
                    <tr className="bg-[var(--bg-tertiary)]">
                      <th className="px-3 py-2 text-left text-[var(--text-secondary)]">Chainage (m)</th>
                      <th className="px-3 py-2 text-left text-[var(--text-secondary)]">x from BVC (m)</th>
                      <th className="px-3 py-2 text-right text-[var(--text-secondary)]">RL (m)</th>
                      <th className="px-3 py-2 text-right text-[var(--text-secondary)]">Grade (%)</th>
                    </tr>
                  </thead>
                  <tbody>
                    {vResult.tableRows.map((r: any, i: number) => {
                      const isBVC = i === 0;
                      const isEVC = i === vResult.tableRows.length - 1;
                      const isPeak = !!(vResult.peakPoint && Math.abs(r.chainage - vResult.peakPoint.chainage) < 1);
                      return (
                        <tr key={`item-${i}`} className={`border-t border-[var(--border-color)]/30 ${isPeak ? 'bg-[var(--accent)]/10' : ''}`}>
                          <td className="px-3 py-1">{r.chainage.toFixed(3)}</td>
                          <td className="px-3 py-1">{r.x.toFixed(3)}</td>
                          <td className={`px-3 py-1 text-right font-semibold ${isBVC || isEVC || isPeak ? 'text-[var(--accent)]' : ''}`}>{r.RL.toFixed(4)}</td>
                          <td className="px-3 py-1 text-right">{r.grade.toFixed(4)}</td>
                        </tr>
                      )
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </div>
      )}
    </div>
  );
}

'use client'
import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { DeformationTrackerPanel } from '@/components/survey/DeformationTrackerPanel'
import { PageHeader } from '@/components/shared/PageHeader'

export default function DeformationPage() {
  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <PageHeader title="Deformation Monitoring" subtitle="Epoch comparison and structural displacement tracking" reference="Time-series analysis | Mining, dams, structures" />
      <div className="mt-6"><DeformationTrackerPanel /></div>
    </div>
  )
}

'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react';
import { PageHeader } from '@/components/shared/PageHeader';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer';
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder';
import { distanceBearingSolvedFromCoords, slopeReductionSolved } from '@/lib/engine/solution/wrappers/distance';
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function DistanceCalculator() {
  const { t } = useLanguage()
  const [mode, setMode] = useState<'coords' | 'slope'>('coords');
  const [p1, setP1] = useState({ n: '', e: '' });
  const [p2, setP2] = useState({ n: '', e: '' });
  const [slope, setSlope] = useState({ dist: '', angle: '' });
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    if (mode === 'coords') {
      const n1 = parseFloat(p1.n), e1 = parseFloat(p1.e);
      const n2 = parseFloat(p2.n), e2 = parseFloat(p2.e);
      if (isNaN(n1) || isNaN(e1) || isNaN(n2) || isNaN(e2)) return;
      const s = distanceBearingSolvedFromCoords({ e1, n1, e2, n2 })
      setSteps(s.steps); setSolutionTitle(s.solution.title)
    } else {
      const sd = parseFloat(slope.dist), va = parseFloat(slope.angle);
      if (isNaN(sd) || isNaN(va)) return;
      const s = slopeReductionSolved({ slopeDistance: sd, verticalAngleDeg: va })
      setSteps(s.steps); setSolutionTitle(s.solution.title)
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.distance')}
        subtitle={t('tools.distanceDesc')}
        reference="Survey Regulations 1994 | Survey Act Cap 299 | WCB (Whole Circle Bearing)"
      />

      <div className="flex gap-4 mb-6">
        <button onClick={() => { setMode('coords'); setSteps(null); setSolutionTitle(undefined); }} className={`btn ${mode === 'coords' ? 'btn-primary' : 'btn-secondary'}`}>
          By Coordinates
        </button>
        <button onClick={() => { setMode('slope'); setSteps(null); setSolutionTitle(undefined); }} className={`btn ${mode === 'slope' ? 'btn-primary' : 'btn-secondary'}`}>
          By Slope Distance
        </button>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        <div className="space-y-6">
          {mode === 'coords' ? (
            <div className="card">
              <div className="card-header"><span className="label">Point A → Point B</span></div>
              <div className="card-body space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="label" htmlFor="point-a-northing-m">Point A Northing (m)</label>
                    <input id="point-a-northing-m" className="input" value={p1.n} onChange={e => setP1({...p1, n: e.target.value})} aria-label="5000.0000" placeholder="5000.0000" />
                  </div>
                  <div>
                    <label className="label" htmlFor="point-a-easting-m">Point A Easting (m)</label>
                    <input id="point-a-easting-m" className="input" value={p1.e} onChange={e => setP1({...p1, e: e.target.value})} aria-label="3000.0000" placeholder="3000.0000" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="label" htmlFor="point-b-northing-m">Point B Northing (m)</label>
                    <input id="point-b-northing-m" className="input" value={p2.n} onChange={e => setP2({...p2, n: e.target.value})} aria-label="5234.5678" placeholder="5234.5678" />
                  </div>
                  <div>
                    <label className="label" htmlFor="point-b-easting-m">Point B Easting (m)</label>
                    <input id="point-b-easting-m" className="input" value={p2.e} onChange={e => setP2({...p2, e: e.target.value})} aria-label="3156.7890" placeholder="3156.7890" />
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="card">
              <div className="card-header"><span className="label">Slope Measurement</span></div>
              <div className="card-body space-y-4">
                <div>
                  <label className="label" htmlFor="slope-distance-m">Slope Distance (m)</label>
                  <input id="slope-distance-m" className="input" value={slope.dist} onChange={e => setSlope({...slope, dist: e.target.value})} aria-label="150.2345" placeholder="150.2345" />
                </div>
                <div>
                  <label className="label" htmlFor="vertical-angle-degrees">Vertical Angle (degrees)</label>
                  <input className="input" value={slope.angle} onChange={e => setSlope({...slope, angle: e.target.value})} aria-label="5.5" placeholder="5.5" />
                </div>
              </div>
            </div>
          )}

          <button onClick={calculate} className="btn btn-primary w-full">{t('toolUI.calculate')}</button>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { PageHeader } from '@/components/shared/PageHeader';
import { printDroneReport, type DroneReportInput } from '@/lib/print/droneReportPrint';
import { PrintMetaPanel, defaultPrintMeta, type PrintMeta } from '@/components/shared/PrintMetaPanel';
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface GCPPoint {
  id: number;
  name: string;
  easting: string;
  northing: string;
  elevation: string;
  status: 'planned' | 'placed' | 'measured';
}

interface AccuracyPoint {
  id: number;
  name: string;
  surveyE: string;
  surveyN: string;
  surveyZ: string;
  droneE: string;
  droneN: string;
  droneZ: string;
}

interface AccuracyClass {
  name: string;
  horizontal: number;
  vertical: number;
  scale: string;
}

const accuracyClasses: AccuracyClass[] = [
  { name: 'Class I', horizontal: 0.075, vertical: 0.15, scale: '1:500' },
  { name: 'Class II', horizontal: 0.150, vertical: 0.30, scale: '1:1000' },
  { name: 'Class III', horizontal: 0.375, vertical: 0.75, scale: '1:2500' },
];

function formatNumber(n: number, decimals: number = 4): string {
  return n.toFixed(decimals);
}

function calculateRMSE(errors: number[]): number {
  if (errors.length === 0) return 0;
  const sumSquared = errors.reduce((sum, e) => sum + e * e, 0);
  return Math.sqrt(sumSquared / errors.length);
}

function DroneSurveyPage() {
  const { t } = useLanguage()
  const [activeTab, setActiveTab] = useState<'planning' | 'settingout' | 'accuracy' | 'report'>('planning');
  const [printMeta, setPrintMeta] = useState<PrintMeta>(defaultPrintMeta);
  const [flightParams, setFlightParams] = useState({ height: '', gsd: '', overlapFront: '', overlapSide: '' });

  const [surveyArea, setSurveyArea] = useState({
    minE: '484500',
    maxE: '485000',
    minN: '9863000',
    maxN: '9863500',
  });

  const [gcpCount, setGcpCount] = useState('9');
  const [gcps, setGcps] = useState<GCPPoint[]>([]);

  const [accuracyPoints, setAccuracyPoints] = useState<AccuracyPoint[]>([
    { id: 1, name: 'CP1', surveyE: '484500.0000', surveyN: '9863100.0000', surveyZ: '120.5000', droneE: '484500.0125', droneN: '9863100.0080', droneZ: '120.4850' },
    { id: 2, name: 'CP2', surveyE: '484750.0000', surveyN: '9863250.0000', surveyZ: '118.2500', droneE: '484750.0180', droneN: '9863249.9950', droneZ: '118.2350' },
  ]);

  const [accuracyResults, setAccuracyResults] = useState<any>(null);
  const [selectedClass, setSelectedClass] = useState<AccuracyClass>(accuracyClasses[0]);

  const generateGCPs = () => {
    const count = parseInt(gcpCount);
    if (isNaN(count) || count < 3) return;

    const minE = parseFloat(surveyArea.minE);
    const maxE = parseFloat(surveyArea.maxE);
    const minN = parseFloat(surveyArea.minN);
    const maxN = parseFloat(surveyArea.maxN);

    const cols = Math.ceil(Math.sqrt(count * (maxE - minE) / (maxN - minN)));
    const rows = Math.ceil(count / cols);

    const gcps: GCPPoint[] = [];
    let idx = 1;

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        if (idx > count) break;
        
        const marginE = (maxE - minE) * 0.1;
        const marginN = (maxN - minN) * 0.1;
        
        const e = minE + marginE + (c / (cols - 1 || 1)) * (maxE - minE - 2 * marginE);
        const n = minN + marginN + (r / (rows - 1 || 1)) * (maxN - minN - 2 * marginN);
        
        gcps.push({
          id: idx,
          name: `GCP-${String(idx).padStart(2, '0')}`,
          easting: formatNumber(e, 4),
          northing: formatNumber(n, 4),
          elevation: '',
          status: 'planned',
        });
        idx++;
      }
    }

    setGcps(gcps);
  };

  const updateGCP = (id: number, field: keyof GCPPoint, value: string) => {
    setGcps(gcps.map((g) => g.id === id ? { ...g, [field]: value } : g));
  };

  const exportGCPCSV = () => {
    const csv = 'Name,Easting,Northing,Elevation,Status\n' + 
      gcps.map((g) => `${g.name},${g.easting},${g.northing},${g.elevation},${g.status}`).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'gcp_coordinates.csv';
    a.click();
  };

  const addAccuracyPoint = () => {
    const last = accuracyPoints[accuracyPoints.length - 1];
    const num = parseInt(last?.name?.replace(/\D/g, '') || '0') + 1;
    setAccuracyPoints([...accuracyPoints, { 
      id: Date.now(), 
      name: `CP${num}`, 
      surveyE: '', surveyN: '', surveyZ: '', 
      droneE: '', droneN: '', droneZ: '' 
    }]);
  };

  const updateAccuracyPoint = (id: number, field: keyof AccuracyPoint, value: string) => {
    setAccuracyPoints(accuracyPoints.map((p) => p.id === id ? { ...p, [field]: value } : p));
  };

  const calculateAccuracy = () => {
    const results = accuracyPoints.map((p) => {
      const se = parseFloat(p.surveyE);
      const sn = parseFloat(p.surveyN);
      const sz = parseFloat(p.surveyZ);
      const de = parseFloat(p.droneE);
      const dn = parseFloat(p.droneN);
      const dz = parseFloat(p.droneZ);

      if (isNaN(se) || isNaN(sn) || isNaN(sz) || isNaN(de) || isNaN(dn) || isNaN(dz)) return null;

      const dE = de - se;
      const dN = dn - sn;
      const dZ = dz - sz;
      const horizontalError = Math.sqrt(dE * dE + dN * dN);
      const error3D = Math.sqrt(dE * dE + dN * dN + dZ * dZ);

      return { name: p.name, se, sn, sz, de, dn, dz, dE, dN, dZ, horizontalError, error3D };
    }).filter(Boolean);

    const validResults = results.filter((r): r is NonNullable<typeof r> => r !== null);

    if (validResults.length === 0) return;

    const horizontalErrors = validResults.map((r) => r.horizontalError);
    const verticalErrors = validResults.map((r) => Math.abs(r.dZ));
    const errors3D = validResults.map((r) => r.error3D);

    const hRMSE = calculateRMSE(horizontalErrors);
    const vRMSE = calculateRMSE(verticalErrors);
    const maxHorizontal = Math.max(...horizontalErrors);
    const maxVertical = Math.max(...verticalErrors);
    const max3D = Math.max(...errors3D);

    const horizontalPass = hRMSE <= selectedClass.horizontal;
    const verticalPass = vRMSE <= selectedClass.vertical;

    setAccuracyResults({
      points: validResults,
      hRMSE,
      vRMSE,
      maxHorizontal,
      maxVertical,
      max3D,
      horizontalPass,
      verticalPass,
      pass: horizontalPass && verticalPass,
    });
  };

  const handlePrint = () => {
    const inp: DroneReportInput = {
      gcps,
      accuracyResults,
      selectedClass,
      flightParams,
      meta: { ...printMeta, title: 'Drone Survey Report' }
    };
    printDroneReport(inp);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.drone')}
        subtitle={t('tools.droneDesc')}
      />

      <div className="flex gap-2 mb-6 flex-wrap">
        {[
          { id: 'planning', label: 'GCP Planning' },
          { id: 'settingout', label: 'Setting Out' },
          { id: 'accuracy', label: 'Accuracy Check' },
          { id: 'report', label: 'Report' },
        ].map((tab: any) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-4 py-2 rounded text-sm font-medium transition-colors ${
              activeTab === tab.id 
                ? 'bg-[var(--accent)] text-white' 
                : 'bg-[var(--card-bg)] text-[var(--text-secondary)] hover:text-[var(--accent)]'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {activeTab === 'planning' && (
        <div className="space-y-6">
          <div className="card">
            <div className="card-header">
              <span className="label">Survey Area Boundary</span>
            </div>
            <p className="text-sm text-[var(--text-secondary)] mb-4">
              Enter the survey area boundaries. METARDU will suggest optimal GCP distribution.
            </p>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="min-easting">Min Easting</label>
                <input id="min-easting" aria-label="Mine" 
                  className="input" 
                  type="number"
                  value={surveyArea.minE}
                  onChange={e => setSurveyArea({...surveyArea, minE: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="max-easting">Max Easting</label>
                <input id="max-easting" aria-label="Maxe" 
                  className="input" 
                  type="number"
                  value={surveyArea.maxE}
                  onChange={e => setSurveyArea({...surveyArea, maxE: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="min-northing">Min Northing</label>
                <input id="min-northing" aria-label="Minn" 
                  className="input" 
                  type="number"
                  value={surveyArea.minN}
                  onChange={e => setSurveyArea({...surveyArea, minN: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="max-northing">Max Northing</label>
                <input id="max-northing" aria-label="Maxn" 
                  className="input" 
                  type="number"
                  value={surveyArea.maxN}
                  onChange={e => setSurveyArea({...surveyArea, maxN: e.target.value})}
                />
              </div>
            </div>
          </div>

          <div className="card">
            <div className="card-header">
              <span className="label">GCP Configuration</span>
            </div>
            <div className="flex gap-4 items-end mb-4">
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="number-of-gcps-min-5">Number of GCPs (min 5)</label>
                <input id="number-of-gcps-min-5" aria-label="Number of GCPs (min 5)" 
                  className="input w-32" 
                  type="number"
                  min="5"
                  value={gcpCount}
                  onChange={e => setGcpCount(e.target.value)}
                />
              </div>
              <button onClick={generateGCPs} className="btn btn-primary">Generate GCP Positions</button>
            </div>
          </div>

          {gcps.length > 0 && (
            <div className="card">
              <div className="card-header flex justify-between items-center">
                <span className="label">Planned GCP Positions ({gcps.length} points)</span>
                <button onClick={exportGCPCSV} className="btn btn-secondary text-sm">Export CSV</button>
              </div>
              <div className="overflow-x-auto max-h-96">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Name</th>
                      <th>Easting (m)</th>
                      <th>Northing (m)</th>
                      <th>Elevation (m)</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {gcps.map((g) => (
                      <tr key={g.id}>
                        <td className="font-semibold">{g.name}</td>
                        <td><input aria-label="Easting" className="input w-32 font-mono" value={g.easting} onChange={e => updateGCP(g.id, 'easting', e.target.value)} /></td>
                        <td><input aria-label="Northing" className="input w-32 font-mono" value={g.northing} onChange={e => updateGCP(g.id, 'northing', e.target.value)} /></td>
                        <td><input className="input w-24 font-mono" value={g.elevation} onChange={e => updateGCP(g.id, 'elevation', e.target.value)} aria-label="RL" placeholder="RL" /></td>
                        <td>
                          <select 
                            className="input w-28" 
                            value={g.status}
                            onChange={e => updateGCP(g.id, 'status', e.target.value)}
                          >
                            <option value="planned">Planned</option>
                            <option value="placed">Placed</option>
                            <option value="measured">Measured</option>
                          </select>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="mt-4 p-4 bg-[var(--bg-tertiary)] rounded">
                <h4 className="font-semibold mb-2">GCP Distribution Map</h4>
                <svg viewBox="0 0 400 250" className="w-full h-48 bg-[var(--bg-secondary)] rounded">
                  <rect x="20" y="20" width="360" height="210" fill="none" stroke="#444" strokeWidth="2" />
                  {gcps.map((g) => {
                    const minE = parseFloat(surveyArea.minE);
                    const maxE = parseFloat(surveyArea.maxE);
                    const minN = parseFloat(surveyArea.minN);
                    const maxN = parseFloat(surveyArea.maxN);
                    const x = 20 + ((parseFloat(g.easting) - minE) / (maxE - minE)) * 360;
                    const y = 230 - ((parseFloat(g.northing) - minN) / (maxN - minN)) * 210;
                    return (
                      <g key={g.id}>
                        <circle cx={x} cy={y} r="8" fill={g.status === 'measured' ? '#22c55e' : g.status === 'placed' ? '#eab308' : '#D17B47'} />
                        <text x={x} y={y - 12} textAnchor="middle" fill="#fff" fontSize="8">{g.name}</text>
                      </g>
                    );
                  })}
                </svg>
              </div>
            </div>
          )}
        </div>
      )}

      {activeTab === 'settingout' && (
        <div className="space-y-6">
          <div className="card">
            <div className="card-header">
              <span className="label">GCP Setting Out</span>
            </div>
            <p className="text-sm text-[var(--text-secondary)] mb-4">
              Navigate to each GCP position and mark the physical target on the ground.
            </p>

            {gcps.length === 0 ? (
              <div className="text-center py-8 text-[var(--text-secondary)]">
                <p>No GCPs planned yet.</p>
                <p className="text-sm">Go to GCP Planning to generate points.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {gcps.filter((g) => g.status !== 'measured').map((g, idx) => (
                  <div key={g.id} className="p-4 bg-[var(--bg-tertiary)] rounded flex justify-between items-center">
                    <div>
                      <div className="font-semibold text-lg">{g.name}</div>
                      <div className="font-mono text-sm text-[var(--text-secondary)]">
                        E: {g.easting} m | N: {g.northing} m
                      </div>
                    </div>
                    <button 
                      onClick={() => updateGCP(g.id, 'status', 'measured')}
                      className="btn btn-secondary"
                    >
                      Navigate & Mark →
                    </button>
                  </div>
                ))}

                <div className="p-4 bg-green-900/30 border border-green-600 rounded">
                  <span className="text-green-400 font-semibold">
                    {gcps.filter((g) => g.status === 'measured').length} / {gcps.length} GCPs measured
                  </span>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'accuracy' && (
        <div className="space-y-6">
          <div className="card">
            <div className="card-header">
              <span className="label">Accuracy Check Points</span>
            </div>
            <p className="text-sm text-[var(--text-secondary)] mb-4">
              Enter independently surveyed coordinates and drone-computed coordinates to compare.
            </p>
            <div className="overflow-x-auto">
              <table className="table">
                <thead>
                  <tr>
                    <th rowSpan={2}>Point</th>
                    <th colSpan={3}>Survey (Ground Truth)</th>
                    <th colSpan={3}>Drone Computed</th>
                  </tr>
                  <tr>
                    <th>E (m)</th>
                    <th>N (m)</th>
                    <th>Z (m)</th>
                    <th>E (m)</th>
                    <th>N (m)</th>
                    <th>Z (m)</th>
                  </tr>
                </thead>
                <tbody>
                  {accuracyPoints.map((p) => (
                    <tr key={p.id}>
                      <td><input aria-label="Name" className="input w-16" value={p.name} onChange={e => updateAccuracyPoint(p.id, 'name', e.target.value)} /></td>
                      <td><input aria-label="Surveye" className="input w-28" value={p.surveyE} onChange={e => updateAccuracyPoint(p.id, 'surveyE', e.target.value)} /></td>
                      <td><input aria-label="Surveyn" className="input w-28" value={p.surveyN} onChange={e => updateAccuracyPoint(p.id, 'surveyN', e.target.value)} /></td>
                      <td><input aria-label="Surveyz" className="input w-24" value={p.surveyZ} onChange={e => updateAccuracyPoint(p.id, 'surveyZ', e.target.value)} /></td>
                      <td><input aria-label="Dronee" className="input w-28" value={p.droneE} onChange={e => updateAccuracyPoint(p.id, 'droneE', e.target.value)} /></td>
                      <td><input aria-label="Dronen" className="input w-28" value={p.droneN} onChange={e => updateAccuracyPoint(p.id, 'droneN', e.target.value)} /></td>
                      <td><input aria-label="Dronez" className="input w-24" value={p.droneZ} onChange={e => updateAccuracyPoint(p.id, 'droneZ', e.target.value)} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div className="p-4 flex gap-4">
              <button onClick={addAccuracyPoint} className="btn btn-secondary">{t('toolUI.addPoint')}</button>
              <button onClick={calculateAccuracy} className="btn btn-primary">Calculate Accuracy</button>
            </div>
          </div>

          <div className="card">
            <div className="card-header">
              <span className="label">Accuracy Standard</span>
            </div>
            <div className="flex gap-2 flex-wrap">
              {accuracyClasses.map((c) => (
                <button
                  key={c.name}
                  onClick={() => { setSelectedClass(c); setAccuracyResults(null); }}
                  className={`px-4 py-2 rounded text-sm ${
                    selectedClass.name === c.name 
                      ? 'bg-[var(--accent)] text-white' 
                      : 'bg-[var(--bg-tertiary)]'
                  }`}
                >
                  {c.name} ({c.scale})
                </button>
              ))}
            </div>
            <div className="mt-4 text-sm text-[var(--text-secondary)]">
              <div>Horizontal limit: ≤ {selectedClass.horizontal} m</div>
              <div>Vertical limit: ≤ {selectedClass.vertical} m</div>
            </div>
          </div>

          {accuracyResults && (
            <div className="card">
              <div className="card-header">
                <span className="label">Accuracy Results</span>
              </div>
              <div className="overflow-x-auto">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Point</th>
                      <th>Survey E</th>
                      <th>Drone E</th>
                      <th>ΔE (m)</th>
                      <th>Survey N</th>
                      <th>Drone N</th>
                      <th>ΔN (m)</th>
                      <th>ΔZ (m)</th>
                      <th>Horiz. Error</th>
                      <th>3D Error</th>
                    </tr>
                  </thead>
                  <tbody>
                    {accuracyResults.points.map((p: any, i: number) => (
                      <tr key={`gcp-${p.name}-${i}`}>
                        <td className="font-semibold">{p.name}</td>
                        <td className="font-mono">{formatNumber(p.se, 4)}</td>
                        <td className="font-mono">{formatNumber(p.de, 4)}</td>
                        <td className={Math.abs(p.dE) > selectedClass.horizontal ? 'text-red-400' : 'text-green-400'}>{formatNumber(p.dE, 4)}</td>
                        <td className="font-mono">{formatNumber(p.sn, 4)}</td>
                        <td className="font-mono">{formatNumber(p.dn, 4)}</td>
                        <td className={Math.abs(p.dN) > selectedClass.horizontal ? 'text-red-400' : 'text-green-400'}>{formatNumber(p.dN, 4)}</td>
                        <td className={Math.abs(p.dZ) > selectedClass.vertical ? 'text-red-400' : 'text-green-400'}>{formatNumber(p.dZ, 4)}</td>
                        <td className={p.horizontalError > selectedClass.horizontal ? 'text-red-400 font-semibold' : ''}>{formatNumber(p.horizontalError, 4)}</td>
                        <td className="font-mono">{formatNumber(p.error3D, 4)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="mt-4 grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-[var(--bg-tertiary)] rounded">
                <div>
                  <span className="text-[var(--text-secondary)] text-sm">Horizontal RMSE</span>
                  <div className={`font-mono text-xl ${accuracyResults.horizontalPass ? 'text-green-400' : 'text-red-400'}`}>
                    {formatNumber(accuracyResults.hRMSE, 4)} m
                  </div>
                </div>
                <div>
                  <span className="text-[var(--text-secondary)] text-sm">Vertical RMSE</span>
                  <div className={`font-mono text-xl ${accuracyResults.verticalPass ? 'text-green-400' : 'text-red-400'}`}>
                    {formatNumber(accuracyResults.vRMSE, 4)} m
                  </div>
                </div>
                <div>
                  <span className="text-[var(--text-secondary)] text-sm">Max Horizontal</span>
                  <div className="font-mono text-xl">{formatNumber(accuracyResults.maxHorizontal, 4)} m</div>
                </div>
                <div>
                  <span className="text-[var(--text-secondary)] text-sm">Max 3D Error</span>
                  <div className="font-mono text-xl">{formatNumber(accuracyResults.max3D, 4)} m</div>
                </div>
              </div>

              <div className={`mt-4 p-4 rounded text-center text-lg font-semibold ${
                accuracyResults.pass ? 'bg-green-900/50 text-green-400' : 'bg-red-900/50 text-red-400'
              }`}>
                {accuracyResults.pass ? ' PASS' : '[x] FAIL'} — {selectedClass.name} ({selectedClass.scale})
              </div>
            </div>
          )}
        </div>
      )}

      {activeTab === 'report' && (
        <div className="space-y-6">
          <div className="card">
            <div className="card-header">
              <span className="label">Drone Survey Report</span>
            </div>
            <p className="text-sm text-[var(--text-secondary)] mb-4">
              Generate a professional drone survey report with GCP list, accuracy check, and statistics.
            </p>

            <div className="space-y-4">
              <div className="p-4 bg-[var(--bg-tertiary)] rounded">
                <h4 className="font-semibold mb-2">1. GCP Summary</h4>
                <div className="grid grid-cols-3 gap-4 text-sm">
                  <div>
                    <span className="text-[var(--text-secondary)]">Total GCPs:</span>
                    <span className="ml-2">{gcps.length || '—'}</span>
                  </div>
                  <div>
                    <span className="text-[var(--text-secondary)]">Measured:</span>
                    <span className="ml-2">{gcps.filter((g) => g.status === 'measured').length}</span>
                  </div>
                  <div>
                    <span className="text-[var(--text-secondary)]">Planned:</span>
                    <span className="ml-2">{gcps.filter((g) => g.status === 'planned').length}</span>
                  </div>
                </div>
              </div>

              {accuracyResults && (
                <div className="p-4 bg-[var(--bg-tertiary)] rounded">
                  <h4 className="font-semibold mb-2">2. Accuracy Assessment</h4>
                  <div className="grid grid-cols-2 gap-4 text-sm mb-4">
                    <div>
                      <span className="text-[var(--text-secondary)]">Accuracy Class:</span>
                      <span className="ml-2">{selectedClass.name} ({selectedClass.scale})</span>
                    </div>
                    <div>
                      <span className="text-[var(--text-secondary)]">Result:</span>
                      <span className={`ml-2 font-semibold ${accuracyResults.pass ? 'text-green-400' : 'text-red-400'}`}>
                        {accuracyResults.pass ? 'PASS' : 'FAIL'}
                      </span>
                    </div>
                    <div>
                      <span className="text-[var(--text-secondary)]">Horizontal RMSE:</span>
                      <span className="ml-2">{formatNumber(accuracyResults.hRMSE, 4)} m</span>
                    </div>
                    <div>
                      <span className="text-[var(--text-secondary)]">Vertical RMSE:</span>
                      <span className="ml-2">{formatNumber(accuracyResults.vRMSE, 4)} m</span>
                    </div>
                  </div>
                </div>
              )}

              <div className="p-4 bg-[var(--bg-tertiary)] rounded">
                <h4 className="font-semibold mb-2">3. Flight Parameters</h4>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                  <div>
                    <label className="block text-[var(--text-secondary)] mb-1" htmlFor="flying-height-m">Flying Height (m)</label>
                    <input id="flying-height-m" className="input" type="number" placeholder="120" value={flightParams.height} onChange={e => setFlightParams({...flightParams, height: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[var(--text-secondary)] mb-1" htmlFor="gsd-cm-px">GSD (cm/px)</label>
                    <input id="gsd-cm-px" className="input" type="number" placeholder="3.0" value={flightParams.gsd} onChange={e => setFlightParams({...flightParams, gsd: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[var(--text-secondary)] mb-1" htmlFor="overlap-front">Overlap Front (%)</label>
                    <input id="overlap-front" className="input" type="number" placeholder="80" value={flightParams.overlapFront} onChange={e => setFlightParams({...flightParams, overlapFront: e.target.value})} />
                  </div>
                  <div>
                    <label className="block text-[var(--text-secondary)] mb-1" htmlFor="overlap-side">Overlap Side (%)</label>
                    <input className="input" type="number" placeholder="70" value={flightParams.overlapSide} onChange={e => setFlightParams({...flightParams, overlapSide: e.target.value})} />
                  </div>
                </div>
              </div>

              <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                <PrintMetaPanel meta={printMeta} onChange={setPrintMeta} />
              </div>

              <button onClick={handlePrint} className="btn btn-primary w-full py-3 text-base shadow-lg">Generate PDF Report</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

