'use client';

// State + handlers for the GCP residual validation tool.
//
// Extracted from src/app/tools/gcp-validation/page.tsx as a custom hook so
// the page component stays a thin orchestrator. All React state, refs and
// event handlers live here.

import { useState, useRef, useCallback } from 'react';
import type {
  AccuracyClass,
  KnownGCP,
  ResidualFormat,
  ResidualRow,
  TabId,
  ValidationSummary,
} from './types';
import {
  SAMPLE_AGISOFT,
  SAMPLE_GCPS,
  accuracyClasses,
} from './constants';
import {
  detectFormat,
  fmt,
  parseResiduals,
  runValidation,
} from './helpers';

export function useGCPValidation() {
  const [activeTab, setActiveTab] = useState<TabId>('gcp');
  const [utmZone, setUtmZone] = useState<number>(36);
  const [selectedClass, setSelectedClass] = useState<AccuracyClass>(accuracyClasses[0]);

  // Tab 1: Known GCPs
  const [knownGCPs, setKnownGCPs] = useState<KnownGCP[]>(SAMPLE_GCPS);

  // Tab 2: Residuals
  const [residualText, setResidualText] = useState('');
  const [residualFormat, setResidualFormat] = useState<ResidualFormat>('auto');
  const [detectedFormat, setDetectedFormat] = useState<ResidualFormat | null>(null);
  const [parsedResiduals, setParsedResiduals] = useState<ResidualRow[]>([]);
  const [parseError, setParseError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);

  // Tab 3: Validation
  const [validationSummary, setValidationSummary] = useState<ValidationSummary | null>(null);

  /* ── GCP Helpers ── */

  const addGCP = useCallback(() => {
    const last = knownGCPs[knownGCPs.length - 1];
    const num = last ? parseInt(last.name.replace(/\D/g, '') || '0') + 1 : 1;
    setKnownGCPs(prev => [...prev, {
      id: Date.now(),
      name: `GCP-${String(num).padStart(2, '0')}`,
      easting: '', northing: '', elevation: '',
    }]);
  }, [knownGCPs]);

  const removeGCP = useCallback((id: number) => {
    setKnownGCPs(prev => prev.filter(g => g.id !== id));
  }, []);

  const updateGCP = useCallback((id: number, field: keyof KnownGCP, value: string) => {
    setKnownGCPs(prev => prev.map(g => g.id === id ? { ...g, [field]: value } : g));
  }, []);

  const clearGCPs = useCallback(() => {
    setKnownGCPs([]);
  }, []);

  const loadSampleGCPs = useCallback(() => {
    setKnownGCPs(SAMPLE_GCPS.map(g => ({ ...g, id: Date.now() + Math.random() })));
  }, []);

  const parseCSVText = useCallback((text: string) => {
    const lines = text.trim().split('\n');
    const imported: KnownGCP[] = [];
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.toLowerCase().startsWith('name')) continue;
      const parts = trimmed.split(',').map(s => s.trim());
      if (parts.length >= 4) {
        const name = parts[0];
        const easting = parseFloat(parts[1]);
        const northing = parseFloat(parts[2]);
        const elevation = parseFloat(parts[3]);
        if (!isNaN(easting) && !isNaN(northing)) {
          imported.push({
            id: Date.now() + Math.random(),
            name,
            easting: fmt(easting, 4),
            northing: fmt(northing, 4),
            elevation: isNaN(elevation) ? '' : fmt(elevation, 4),
          });
        }
      }
    }
    if (imported.length > 0) {
      setKnownGCPs(prev => [...prev, ...imported]);
    }
  }, []);

  const handleCSVFileUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const text = evt.target?.result as string;
      parseCSVText(text);
    };
    reader.readAsText(file);
    e.target.value = '';
  }, [parseCSVText]);

  const handleGeoJSONUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const json = JSON.parse(evt.target?.result as string);
        const features = json.features || [];
        const imported: KnownGCP[] = [];
        for (const f of features) {
          if (f.geometry?.type !== 'Point') continue;
          const coords = f.geometry.coordinates;
          const props = f.properties || {};
          const name = props.name || props.id || `GCP-${imported.length + 1}`;
          // GeoJSON is WGS84, but we just take the UTM props if available
          const easting = props.easting || (coords.length > 0 ? coords[0] : '');
          const northing = props.northing || (coords.length > 1 ? coords[1] : '');
          const elevation = props.elevation || (coords.length > 2 ? coords[2] : '');
          if (typeof easting === 'number' && typeof northing === 'number') {
            imported.push({
              id: Date.now() + Math.random(),
              name: String(name),
              easting: fmt(easting, 4),
              northing: fmt(northing, 4),
              elevation: typeof elevation === 'number' ? fmt(elevation, 4) : '',
            });
          }
        }
        if (imported.length > 0) {
          setKnownGCPs(prev => [...prev, ...imported]);
        }
      } catch {
        /* ignore invalid JSON */
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  }, []);

  /* ── Residual Helpers ── */

  const handleParseResiduals = useCallback(() => {
    setParseError(null);
    setParsedResiduals([]);
    if (!residualText.trim()) {
      setParseError('No residual data to parse. Paste a residual table from Agisoft Metashape or Pix4D.');
      return;
    }
    try {
      const rows = parseResiduals(residualText, residualFormat);
      if (rows.length === 0) {
        setParseError('Could not parse any valid rows. Check the format and try again.');
        return;
      }
      const detected = residualFormat === 'auto' ? detectFormat(residualText) : residualFormat;
      setDetectedFormat(detected === 'auto' ? 'agisoft' : detected);
      setParsedResiduals(rows);
    } catch (err) {
      setParseError(`Parse error: ${err instanceof Error ? err.message : 'Unknown error'}`);
    }
  }, [residualText, residualFormat]);

  const handleResidualFileUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const text = evt.target?.result as string;
      setResidualText(text);
    };
    reader.readAsText(file);
    e.target.value = '';
  }, []);

  const loadSampleResiduals = useCallback(() => {
    setResidualText(SAMPLE_AGISOFT);
    setResidualFormat('auto');
  }, []);

  const clearResiduals = useCallback(() => {
    setResidualText('');
    setParsedResiduals([]);
    setDetectedFormat(null);
    setParseError(null);
  }, []);

  /* ── Validation ── */

  const handleRunValidation = useCallback(() => {
    const validKnown = knownGCPs.filter(g =>
      g.name.trim() && !isNaN(parseFloat(g.easting)) && !isNaN(parseFloat(g.northing))
    );
    if (validKnown.length === 0) return;
    if (parsedResiduals.length === 0) return;
    const result = runValidation(validKnown, parsedResiduals, selectedClass, utmZone);
    setValidationSummary(result);
    setActiveTab('results');
  }, [knownGCPs, parsedResiduals, selectedClass, utmZone]);

  const clearAll = useCallback(() => {
    setKnownGCPs([]);
    setResidualText('');
    setParsedResiduals([]);
    setDetectedFormat(null);
    setParseError(null);
    setValidationSummary(null);
  }, []);

  /* ── Report ── */

  const generateReportText = useCallback((): string => {
    const now = new Date().toLocaleString('en-KE', { timeZone: 'Africa/Nairobi' });
    const lines: string[] = [];
    lines.push('════════════════════════════════════════════════════════════════');
    lines.push('           GCP RESIDUAL VALIDATION REPORT');
    lines.push('           METARDU Survey Platform');
    lines.push('════════════════════════════════════════════════════════════════');
    lines.push('');
    lines.push(`Date:                 ${now}`);
    lines.push(`UTM Zone:             ${utmZone}S`);
    lines.push(`Accuracy Standard:    ${selectedClass.name} (${selectedClass.scale})`);
    lines.push(`Horizontal Limit:     ≤ ${selectedClass.horizontal} m`);
    lines.push(`Vertical Limit:       ≤ ${selectedClass.vertical} m`);
    lines.push('');

    if (!validationSummary) {
      lines.push('No validation has been run yet.');
      return lines.join('\n');
    }

    const s = validationSummary;
    lines.push('──────────────────────────────────────────────────────────────');
    lines.push('SUMMARY');
    lines.push('──────────────────────────────────────────────────────────────');
    lines.push(`Total GCPs in residual file:   ${s.totalGCPs}`);
    lines.push(`Matched against known GCPs:    ${s.matchedGCPs}`);
    if (s.unmatchedNames.length > 0) {
      lines.push(`Unmatched GCP names:           ${s.unmatchedNames.join(', ')}`);
    }
    lines.push('');
    lines.push(`Horizontal RMSE:               ${fmt(s.hRMSE)} m    ${s.hPass ? ' PASS' : '[x] FAIL'}`);
    lines.push(`Vertical RMSE:                 ${fmt(s.vRMSE)} m    ${s.vPass ? ' PASS' : '[x] FAIL'}`);
    lines.push(`Max Horizontal Error:          ${fmt(s.maxHorizontal)} m`);
    lines.push(`Max Vertical Error:            ${fmt(s.maxVertical)} m`);
    lines.push(`Max 3D Error:                  ${fmt(s.max3D)} m`);
    lines.push(`Pass Rate:                     ${s.matchedGCPs > 0 ? ((s.passCount / s.matchedGCPs) * 100).toFixed(1) : '0.0'}% (${s.passCount}/${s.matchedGCPs})`);
    lines.push('');
    lines.push(`OVERALL RESULT:                 ${s.pass ? ' PASS' : '[x] FAIL'}`);
    lines.push('');

    lines.push('──────────────────────────────────────────────────────────────');
    lines.push('PER-GCP DETAILS');
    lines.push('──────────────────────────────────────────────────────────────');
    lines.push('');
    lines.push(
      'Point'.padEnd(12) +
      'Known E'.padStart(15) +
      'Software E'.padStart(15) +
      'ΔE(m)'.padStart(12) +
      'Known N'.padStart(15) +
      'Software N'.padStart(15) +
      'ΔN(m)'.padStart(12) +
      'ΔZ(m)'.padStart(12) +
      'Horiz Err'.padStart(12) +
      '3D Err'.padStart(12) +
      'Status'.padStart(10)
    );
    lines.push('─'.repeat(140));

    for (const p of s.points) {
      lines.push(
        p.name.padEnd(12) +
        fmt(p.knownE).padStart(15) +
        fmt(p.softwareE).padStart(15) +
        fmt(p.deltaE).padStart(12) +
        fmt(p.knownN).padStart(15) +
        fmt(p.softwareN).padStart(15) +
        fmt(p.deltaN).padStart(12) +
        fmt(p.deltaZ).padStart(12) +
        fmt(p.horizontalError).padStart(12) +
        fmt(p.error3D).padStart(12) +
        (p.overallPass ? 'PASS'.padStart(10) : 'FAIL'.padStart(10))
      );
    }

    lines.push('');
    lines.push('════════════════════════════════════════════════════════════════');
    lines.push('  End of Report');
    lines.push('════════════════════════════════════════════════════════════════');
    return lines.join('\n');
  }, [validationSummary, selectedClass, utmZone]);

  const handleCopyReport = useCallback(() => {
    const text = generateReportText();
    navigator.clipboard.writeText(text).catch(() => {
      /* fallback */
    });
  }, [generateReportText]);

  const handleExportCSV = useCallback(() => {
    if (!validationSummary) return;
    const header = 'Name,Known_E,Known_N,Known_Z,Software_E,Software_N,Software_Z,Delta_E,Delta_N,Delta_Z,Horizontal_Error,Error_3D,Status';
    const rows = validationSummary.points.map(p =>
      `${p.name},${fmt(p.knownE)},${fmt(p.knownN)},${fmt(p.knownZ)},${fmt(p.softwareE)},${fmt(p.softwareN)},${fmt(p.softwareZ)},${fmt(p.deltaE)},${fmt(p.deltaN)},${fmt(p.deltaZ)},${fmt(p.horizontalError)},${fmt(p.error3D)},${p.overallPass ? 'PASS' : 'FAIL'}`
    );
    const csv = [header, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'gcp_validation_report.csv';
    a.click();
    URL.revokeObjectURL(url);
  }, [validationSummary]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  return {
    // state
    activeTab,
    setActiveTab,
    utmZone,
    setUtmZone,
    selectedClass,
    setSelectedClass,
    knownGCPs,
    setKnownGCPs,
    residualText,
    setResidualText,
    residualFormat,
    setResidualFormat,
    detectedFormat,
    setDetectedFormat,
    parsedResiduals,
    setParsedResiduals,
    parseError,
    validationSummary,
    setValidationSummary,
    // refs
    fileInputRef,
    csvInputRef,
    // GCP handlers
    addGCP,
    removeGCP,
    updateGCP,
    clearGCPs,
    loadSampleGCPs,
    handleCSVFileUpload,
    handleGeoJSONUpload,
    // Residual handlers
    handleParseResiduals,
    handleResidualFileUpload,
    loadSampleResiduals,
    clearResiduals,
    // Validation handlers
    handleRunValidation,
    clearAll,
    // Report handlers
    generateReportText,
    handleCopyReport,
    handleExportCSV,
    handlePrint,
  };
}

export type UseGCPValidationReturn = ReturnType<typeof useGCPValidation>;

'use client';

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/api-client/client'
import { generateGeoJSON } from '@/lib/export/generateGeoJSON'
import { generateLandXML } from '@/lib/export/generateLandXML'
import { utmToGeographic } from '@/lib/geodesy/coordinates'
import { PageHeader } from '@/components/shared/PageHeader'
import Link from 'next/link'
import { useLanguage } from '@/lib/i18n/LanguageContext'

function download(content: string, filename: string, mime = 'text/plain') {
  const a = document.createElement('a')
  a.href = URL.createObjectURL(new Blob([content], { type: mime }))
  a.download = filename; a.click()
}

// ── WKT projection string generator ─────────────────────────────────────────
function getWKT(utmZone: number, hemisphere: 'N' | 'S'): string {
  const zoneNum = utmZone
  const isNorth = hemisphere === 'N'
  const centralMeridian = -183 + zoneNum * 6
  return `PROJCS["WGS 84 / UTM zone ${zoneNum}${hemisphere}",
  GEOGCS["WGS 84",
    DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],
    PRIMEM["Greenwich",0],UNIT["degree",0.0174532925199433]],
  PROJECTION["Transverse_Mercator"],
  PARAMETER["latitude_of_origin",0],
  PARAMETER["central_meridian",${centralMeridian}],
  PARAMETER["scale_factor",0.9996],
  PARAMETER["false_easting",500000],
  PARAMETER["false_northing",${isNorth ? 0 : 10000000}],
  UNIT["metre",1],AUTHORITY["EPSG","${isNorth ? 32600 + zoneNum : 32700 + zoneNum}"]]`
}

// ── PRJ file for shapefiles ──────────────────────────────────────────────────
function getPRJ(utmZone: number, hemisphere: 'N' | 'S'): string {
  return getWKT(utmZone, hemisphere)
}

// ── MapInfo TAB-compatible CSV ───────────────────────────────────────────────
function generateMapInfoCSV(points: any[], utmZone: number, hemisphere: 'N' | 'S', projectName: string): string {
  const lines = [`"Name","Easting","Northing","Elevation","Type","Lat_WGS84","Lon_WGS84"`]
  points.forEach((p: any) => {
    const { lat, lon } = utmToGeographic(p.easting, p.northing, utmZone, hemisphere)
    lines.push(`"${p.name}",${p.easting.toFixed(4)},${p.northing.toFixed(4)},${(p.elevation||0).toFixed(4)},"${p.is_control?'Control':'Survey'}",${lat.toFixed(8)},${lon.toFixed(8)}`)
  })
  return lines.join('\n')
}

// ── KML for Google Earth / Maps ──────────────────────────────────────────────
function generateKML(points: any[], utmZone: number, hemisphere: 'N' | 'S', projectName: string): string {
  const placemarks = points.map((p: any) => {
    const { lat, lon } = utmToGeographic(p.easting, p.northing, utmZone, hemisphere)
    const color = p.is_control ? 'ff0080ff' : 'ff00ff80'
    return `  <Placemark>
    <name>${p.name}</name>
    <description>E: ${p.easting.toFixed(4)} N: ${p.northing.toFixed(4)} Z: ${(p.elevation||0).toFixed(3)} — ${p.is_control?'Control':'Survey'}</description>
    <Style><IconStyle><color>${color}</color><scale>1.0</scale></IconStyle></Style>
    <Point><coordinates>${lon.toFixed(8)},${lat.toFixed(8)},${(p.elevation||0).toFixed(3)}</coordinates></Point>
  </Placemark>`
  }).join('\n')
  return `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2">
<Document>
  <name>${projectName}</name>
  <description>Survey points exported from METARDU. Orange = Control, Green = Survey</description>
${placemarks}
</Document>
</kml>`
}

function GISExportPage() {
  const { t } = useLanguage()
  const [projects, setProjects]   = useState<any[]>([])
  const [projectId, setProjectId] = useState('')
  const [points, setPoints]       = useState<any[]>([])
  const [loading, setLoading]     = useState(false)
  const [exports, setExports]     = useState<Set<string>>(new Set())

  useEffect(() => {
    const sb = createClient()
    sb.auth.getSession().then(({ data: { session } }) => {
      const user = session?.user
      if (!user) return
      sb.from('projects').select('id,name,utm_zone,hemisphere').eq('user_id', user.id)
        .order('created_at', { ascending: false }).then(({ data }) => { if (data) setProjects(data) })
    })
  }, [])

  useEffect(() => {
    if (!projectId) { setPoints([]); return }
    setLoading(true)
    createClient().from('survey_points').select('*').eq('project_id', projectId)
      .then(({ data }) => { if (data) setPoints(data); setLoading(false) })
  }, [projectId])

  const project = projects.find((p: any) => p.id === projectId)
  const ptsMapped = points.map((p: any) => ({
    name: p.name, easting: p.easting, northing: p.northing,
    elevation: p.elevation ?? 0, is_control: p.is_control,
  }))

  const markExported = (key: string) => setExports(prev => { const s = new Set(Array.from(prev)); s.add(key); return s })

  const doExport = (type: string) => {
    if (!project || !points.length) return
    const z = project.utm_zone; const h = project.hemisphere as 'N'|'S'
    const name = project.name

    switch(type) {
      case 'geojson':
        download(generateGeoJSON(ptsMapped, name, z, h), `${name}_WGS84.geojson`, 'application/geo+json')
        break
      case 'kml':
        download(generateKML(ptsMapped, z, h, name), `${name}.kml`, 'application/vnd.google-earth.kml+xml')
        break
      case 'landxml':
        download(generateLandXML({ name, utm_zone: z, hemisphere: h }, ptsMapped), `${name}.xml`, 'application/xml')
        break
      case 'csv':
        download(generateMapInfoCSV(ptsMapped, z, h, name), `${name}_points.csv`)
        break
      case 'prj':
        download(getPRJ(z, h), `${name}_UTM${z}${h}.prj`)
        break
      case 'wkt':
        download(getWKT(z, h), `${name}_CRS.wkt`)
        break
      // AUDIT FIX (2026-07-03): Added DXF + Shapefile exports.
      // The API routes existed but weren't exposed in the UI.
      case 'dxf':
        // Call the server-side DXF export route
        fetch('/api/compute/export/dxf', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ points: ptsMapped, projectName: name, utmZone: z, hemisphere: h }),
        }).then(r => r.text()).then(dxf => {
          download(dxf, `${name}_survey.dxf`, 'application/dxf')
        }).catch(() => alert('DXF export failed — try the server-side export route'))
        break
      case 'shapefile':
        // Call the server-side Shapefile export route (returns a ZIP)
        fetch('/api/compute/export/shapefile', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ points: ptsMapped, projectName: name, utmZone: z, hemisphere: h }),
        }).then(r => r.blob()).then(blob => {
          const url = URL.createObjectURL(blob)
          const a = document.createElement('a')
          a.href = url; a.download = `${name}_shapefile.zip`; a.click()
          URL.revokeObjectURL(url)
        }).catch(() => alert('Shapefile export failed — try the server-side export route'))
        break
    }
    markExported(type)
  }

  const exportAll = () => {
    ['geojson','dxf','shapefile','kml','landxml','csv','prj','wkt'].forEach((t, i) =>
      setTimeout(() => doExport(t), i * 200)
    )
  }

  const EXPORT_ITEMS = [
    {
      key: 'geojson', icon: '{}',
      title: 'GeoJSON (WGS84)',
      desc: 'Universal format — drop directly into QGIS, ArcGIS, Mapbox, Leaflet, PostGIS.',
      note: 'Coordinates converted to WGS84 lat/lon as required by spec.',
      software: 'QGIS · ArcGIS · Mapbox · PostGIS',
    },
    // AUDIT FIX (2026-07-03): Added DXF + Shapefile export cards.
    {
      key: 'dxf', icon: '△',
      title: 'DXF (AutoCAD/Civil 3D)',
      desc: 'Drawing Exchange Format — the standard for CAD interoperability. Points as POINT entities with layer separation.',
      note: 'Control points on CONTROL layer, survey points on SURVEY layer.',
      software: 'AutoCAD · Civil 3D · MicroStation · BricsCAD',
    },
    {
      key: 'shapefile', icon: '▦',
      title: 'Shapefile (ESRI)',
      desc: 'Industry-standard GIS format. Includes .shp, .shx, .dbf, and .prj files bundled as a ZIP.',
      note: 'Point geometry with attributes (name, elevation, type).',
      software: 'ArcGIS · QGIS · MapInfo · Global Mapper',
    },
    {
      key: 'kml', icon: '◉',
      title: 'KML — Google Earth',
      desc: 'Open in Google Earth Pro to verify positions on satellite imagery before submitting.',
      note: 'Orange pins = control points, green = survey.',
      software: 'Google Earth Pro · Google Maps · QGIS',
    },
    {
      key: 'landxml', icon: '</>',
      title: 'LandXML',
      desc: 'ISO standard for survey data exchange between CAD/GIS systems.',
      note: 'Includes CgPoints with full coordinate metadata.',
      software: 'Civil 3D · 12d · QGIS · Trimble Business Center',
    },
    {
      key: 'csv', icon: '≡',
      title: 'CSV with WGS84',
      desc: 'Spreadsheet-compatible with both UTM and WGS84 columns.',
      note: 'Import into MapInfo, QGIS, ArcGIS, or share with clients.',
      software: 'QGIS · ArcGIS · MapInfo · Excel · Google Sheets',
    },
    {
      key: 'prj', icon: '⊕',
      title: '.prj CRS file',
      desc: 'Projection file for your UTM zone. Attach to shapefile exports to declare coordinate system.',
      note: 'Prevents "unknown coordinate system" errors in GIS software.',
      software: 'ArcGIS · QGIS · MapInfo (attach alongside .shp)',
    },
    {
      key: 'wkt', icon: '◻',
      title: 'WKT Projection String',
      desc: 'Well-Known Text definition of your project coordinate system for database import.',
      note: `EPSG:${project ? (project.hemisphere === 'S' ? 32700 : 32600) + project.utm_zone : '327xx'}`,
      software: 'PostGIS · SpatiaLite · Oracle Spatial',
    },
  ]

  return (
    <div className="min-h-screen bg-[var(--bg-primary)]">
      <div className="max-w-7xl mx-auto px-4 py-8">

        <PageHeader
          title={t('tools.gisExport')}
          subtitle={t('tools.gisExportDesc')}
        />

        {/* Project selector */}
        <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5 mb-6">
          <div className="flex items-center gap-4 flex-wrap">
            <div className="flex-1 min-w-48">
              {projects.length === 0
                ? <p className="text-sm text-[var(--text-muted)]">No projects. <Link href="/project/new" className="text-[var(--accent)]">Create one →</Link></p>
                : <select value={projectId} onChange={e => setProjectId(e.target.value)} className="input w-full">
                    <option value="">— Select project —</option>
                    {projects.map((p: any) => <option key={p.id} value={p.id}>{p.name}</option>)}
                  </select>
              }
            </div>
            {project && (
              <div className="text-sm text-[var(--text-muted)] flex-shrink-0">
                UTM Zone {project.utm_zone}{project.hemisphere} ·
                EPSG:{(project.hemisphere === 'S' ? 32700 : 32600) + project.utm_zone} ·
                {loading ? ' loading…' : ` ${points.length} points`}
              </div>
            )}
            {points.length > 0 && (
              <button onClick={exportAll} className="btn btn-primary flex-shrink-0">
                Download all 8 formats
              </button>
            )}
          </div>
        </div>

        {/* Export grid */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
          {EXPORT_ITEMS.map((item: any) => {
            const done = exports.has(item.key)
            return (
              <div key={item.key}
                className={`bg-[var(--bg-card)] border rounded-xl p-5 transition-colors ${done ? 'border-green-700/40' : 'border-[var(--border-color)]'}`}>
                <div className="flex items-start justify-between mb-3">
                  <div className="w-9 h-9 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] flex items-center justify-center text-sm font-mono text-[var(--accent)] font-bold flex-shrink-0">
                    {item.icon}
                  </div>
                  {done && (
                    <span className="text-xs text-green-400 flex items-center gap-1">
                      <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}><path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5"/></svg>
                      Downloaded
                    </span>
                  )}
                </div>
                <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-1">{item.title}</h3>
                <p className="text-xs text-[var(--text-secondary)] leading-relaxed mb-2">{item.desc}</p>
                <p className="text-[10px] text-[var(--text-muted)] mb-3">{item.note}</p>
                <div className="flex items-center justify-between">
                  <p className="text-[10px] text-[var(--text-muted)] truncate">{item.software}</p>
                  <button
                    onClick={() => doExport(item.key)}
                    disabled={!points.length}
                    className={`ml-2 flex-shrink-0 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors disabled:opacity-50 ${
                      done
                        ? 'bg-green-900/30 text-green-400 border border-green-700/30'
                        : 'bg-[var(--accent)] text-black hover:bg-[var(--accent-dim)]'
                    }`}>
                    {done ? 'Re-download' : 'Download'}
                  </button>
                </div>
              </div>
            )
          })}
        </div>

        {/* CRS explainer */}
        {project && (
          <div className="mt-6 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-5">
            <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">Coordinate system for this project</h2>
            <div className="grid md:grid-cols-3 gap-4 text-sm">
              {[
                { label: 'Projected CRS', value: `UTM Zone ${project.utm_zone}${project.hemisphere}` },
                { label: 'EPSG code', value: `EPSG:${(project.hemisphere === 'S' ? 32700 : 32600) + project.utm_zone}` },
                { label: 'Geographic CRS', value: 'WGS84 (EPSG:4326)' },
                { label: 'Units', value: 'Metres (projected) / Degrees (geographic)' },
                { label: 'False Easting', value: '500,000 m' },
                { label: 'False Northing', value: project.hemisphere === 'S' ? '10,000,000 m' : '0 m' },
              ].map(({ label, value }) => (
                <div key={label} className="bg-[var(--bg-secondary)] rounded-lg p-3">
                  <p className="text-xs text-[var(--text-muted)]">{label}</p>
                  <p className="text-sm font-medium text-[var(--text-primary)] mt-0.5 font-mono">{value}</p>
                </div>
              ))}
            </div>
            <p className="text-xs text-[var(--text-muted)] mt-3">
              Include this information when sending data to GIS teams so they can correctly set the coordinate system in their software without guessing.
            </p>
          </div>
        )}

        {points.length === 0 && projectId && !loading && (
          <div className="mt-4 bg-amber-900/20 border border-amber-700/30 rounded-xl p-4 text-sm text-amber-400">
            No survey points found in this project. Add points in the workspace first.
          </div>
        )}
      </div>
    </div>
  )
}

