'use client'

import { useState, useCallback } from 'react'
import { Upload, Satellite, AlertCircle, CheckCircle2 } from 'lucide-react'
import type { GNSSPositionResult } from '@/lib/gnss/rinexProcessor'
import { computeConfidenceEllipse } from '@/lib/gnss/rinexProcessor'

export default function GNSSRinexPage() {
  const [obsFile, setObsFile] = useState<File | null>(null)
  const [navFile, setNavFile] = useState<File | null>(null)
  const [usePrecise, setUsePrecise] = useState(false)
  const [stationName, setStationName] = useState('')
  const [result, setResult] = useState<GNSSPositionResult | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const handleObsFile = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setObsFile(e.target.files?.[0] || null)
  }, [])

  const handleNavFile = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setNavFile(e.target.files?.[0] || null)
  }, [])

  const handleProcess = async () => {
    if (!obsFile) { setError('RINEX observation file is required'); return }
    setLoading(true); setError(''); setResult(null)
    try {
      // Read files as base64
      const obsB64 = await fileToBase64(obsFile)
      const navB64 = navFile ? await fileToBase64(navFile) : undefined

      const res = await fetch('/api/gnss/process-rinex', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          rinex_obs: obsB64,
          rinex_nav: navB64,
          use_precise_ephemeris: usePrecise,
          station_name: stationName || 'unknown',
        }),
      })
      if (!res.ok) { const e = await res.json(); throw new Error(e.error || `Failed (${res.status})`) }
      const data = await res.json()
      setResult(data.data)
    } catch (e) { setError(e instanceof Error ? e.message : 'Processing failed') }
    finally { setLoading(false) }
  }

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"

  const ellipse = result?.covariance ? computeConfidenceEllipse(result.covariance) : null

  return (
    <div className="min-h-screen p-6 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">GNSS RINEX Processing</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Upload RINEX observation files for PPP (Precise Point Positioning) processing. Works without RTK — just a RINEX file + IGS precise ephemeris.</p>

      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="rinex-observation-file-rnx-obs">RINEX Observation File (*.rnx, *.obs)</label>
            <input id="rinex-observation-file-rnx-obs" type="file" accept=".rnx,.obs,.RNX,.O" onChange={handleObsFile} className="w-full text-xs text-[var(--text-secondary)]" />
            {obsFile && <div className="mt-1 text-[10px] text-green-400 flex items-center gap-1"><CheckCircle2 className="w-3 h-3" /> {obsFile.name}</div>}
          </div>
          <div>
            <label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="rinex-navigation-file-optional">RINEX Navigation File (optional)</label>
            <input id="rinex-navigation-file-optional" type="file" accept=".nav,.rnx,.N" onChange={handleNavFile} className="w-full text-xs text-[var(--text-secondary)]" />
            {navFile && <div className="mt-1 text-[10px] text-green-400 flex items-center gap-1"><CheckCircle2 className="w-3 h-3" /> {navFile.name}</div>}
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4 mt-3">
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="station-name">Station Name</label><input id="station-name" value={stationName} onChange={e => setStationName(e.target.value)} className={inputCls} placeholder="NALR" /></div>
          <div className="flex items-end">
            <label className="flex items-center gap-2 text-xs text-[var(--text-secondary)] cursor-pointer">
              <input type="checkbox" checked={usePrecise} onChange={e => setUsePrecise(e.target.checked)} className="w-4 h-4" />
              Use IGS Precise Ephemeris (sub-meter accuracy)
            </label>
          </div>
        </div>
        <button onClick={handleProcess} disabled={loading || !obsFile} className="mt-3 flex items-center gap-2 px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-50">
          <Satellite className="w-4 h-4" /> {loading ? 'Processing...' : 'Process RINEX'}
        </button>
      </div>

      {error && <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-4 text-xs text-red-400 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}

      {result && (
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-3 flex items-center gap-2"><Satellite className="w-4 h-4" /> Position Result ({result.method})</h2>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <div className="text-xs"><span className="text-[var(--text-muted)]">Latitude:</span> <span className="font-mono text-[var(--text-primary)]">{result.latitude.toFixed(8)}°</span></div>
              <div className="text-xs"><span className="text-[var(--text-muted)]">Longitude:</span> <span className="font-mono text-[var(--text-primary)]">{result.longitude.toFixed(8)}°</span></div>
              <div className="text-xs"><span className="text-[var(--text-muted)]">Height:</span> <span className="font-mono text-[var(--text-primary)]">{result.height.toFixed(4)} m</span></div>
              <div className="text-xs"><span className="text-[var(--text-muted)]">ECEF:</span> <span className="font-mono text-[var(--text-primary)]">[{result.ecef.map(v => v.toFixed(2)).join(', ')}]</span></div>
            </div>
            <div className="space-y-2">
              <div className="text-xs"><span className="text-[var(--text-muted)]">RMS:</span> <span className="font-mono text-[var(--text-primary)]">{result.rms.toFixed(4)} m</span></div>
              <div className="text-xs"><span className="text-[var(--text-muted)]">Satellites:</span> <span className="font-mono text-[var(--text-primary)]">{result.n_satellites}</span></div>
              <div className="text-xs"><span className="text-[var(--text-muted)]">Epochs:</span> <span className="font-mono text-[var(--text-primary)]">{result.n_epochs}</span></div>
              {ellipse && (
                <div className="text-xs"><span className="text-[var(--text-muted)]">95% Ellipse:</span> <span className="font-mono text-[var(--text-primary)]">a={ellipse.semiMajor.toFixed(3)}m b={ellipse.semiMinor.toFixed(3)}m θ={ellipse.orientation.toFixed(1)}°</span></div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

async function fileToBase64(file: File): Promise<string> {
  const arrayBuffer = await file.arrayBuffer()
  const bytes = new Uint8Array(arrayBuffer)
  let binary = ''
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i])
  return btoa(binary)
}

'use client';

import { useState } from 'react';
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'
import { 
  geodeticToECEF,
  ecefToGeodetic, 
  ecefToENU, 
  computeBaseline, 
  processGNSSNetwork,
  utmToGeodetic
} from '@/lib/geodesy/gnss';

interface Observation {
  id: number;
  name: string;
  lat: string;
  lon: string;
  h: string;
  sigma: string;
}

export default function GNSSProcessor() {
  const { t } = useLanguage()
  const [baseStation, setBaseStation] = useState({
    name: 'BASE01',
    lat: '-1.2921',
    lon: '36.8219',
    h: '1798.5'
  });
  
  const [origin, setOrigin] = useState({
    lat: '-1.2921',
    lon: '36.8219'
  });
  
  const [observations, setObservations] = useState<Observation[]>([
    { id: 1, name: 'ROVER1', lat: '-1.2915', lon: '36.8225', h: '1800.2', sigma: '0.015' },
    { id: 2, name: 'ROVER2', lat: '-1.2930', lon: '36.8210', h: '1795.8', sigma: '0.018' },
  ]);
  
  const [result, setResult] = useState<any>(null);
  const [mode, setMode] = useState<'baseline' | 'network'>('baseline');

  const addObservation = () => {
    setObservations([
      ...observations,
      { id: Date.now(), name: `POINT${observations.length + 1}`, lat: '', lon: '', h: '', sigma: '0.015' }
    ]);
  };

  const updateObservation = (id: number, field: keyof Observation, value: string) => {
    setObservations(observations.map((o: any) => o.id === id ? { ...o, [field]: value } : o));
  };

  const removeObservation = (id: number) => {
    setObservations(observations.filter((o: any) => o.id !== id));
  };

  const calculate = () => {
    try {
      const baseECEF = geodeticToECEF(
        parseFloat(baseStation.lat),
        parseFloat(baseStation.lon),
        parseFloat(baseStation.h)
      );
      baseECEF.name = baseStation.name;

      if (mode === 'baseline') {
        const obs = observations[0];
        if (!obs.lat || !obs.lon) return;
        const obsECEF = geodeticToECEF(
          parseFloat(obs.lat),
          parseFloat(obs.lon),
          parseFloat(obs.h) || 0
        );
        obsECEF.name = obs.name;
        const baseline = computeBaseline(
          { pointName: baseStation.name, ...baseECEF },
          { pointName: obs.name, x: obsECEF.x, y: obsECEF.y, z: obsECEF.z, sigmaX: parseFloat(obs.sigma) }
        );
        const enu = ecefToENU(obsECEF.x, obsECEF.y, obsECEF.z, parseFloat(origin.lat), parseFloat(origin.lon), 0);
        setResult({ baseline, enu, baseECEF, obsECEF });
      } else {
        const obsData = observations.map((o: any) => ({
          pointName: o.name,
          x: 0, y: 0, z: 0,
          sigmaX: parseFloat(o.sigma)
        })).map((o, i) => {
          const ecef = geodeticToECEF(
            parseFloat(observations[i].lat),
            parseFloat(observations[i].lon),
            parseFloat(observations[i].h) || 0
          );
          return { ...o, x: ecef.x, y: ecef.y, z: ecef.z };
        });
        const network = processGNSSNetwork(
          baseECEF as any,
          obsData,
          parseFloat(origin.lat),
          parseFloat(origin.lon),
          0
        );
        setResult(network);
      }
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader title={t('tools.gnss')} subtitle={t('tools.gnssDesc')} reference="Survey Regulations 1994  |  RDM 1.1 (2025) Section 5.6  |  WGS84 / SRID 21037" />

      <div className="flex gap-4 mb-6">
        <button onClick={() => { setMode('baseline'); setResult(null); }} className={`btn ${mode === 'baseline' ? 'btn-primary' : 'btn-secondary'}`}>
          Single Baseline
        </button>
        <button onClick={() => { setMode('network'); setResult(null); }} className={`btn ${mode === 'network' ? 'btn-primary' : 'btn-secondary'}`}>
          Network Adjustment
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="bg-[var(--card)] border border-[var(--border)] rounded-lg p-4">
            <h3 className="font-semibold mb-4">Base Station</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm mb-1" htmlFor="name">Name</label>
                <input id="name" aria-label="Name" type="text" value={baseStation.name} onChange={e => setBaseStation({...baseStation, name: e.target.value})} className="input w-full" />
              </div>
              <div>
                <label className="block text-sm mb-1" htmlFor="ellipsoidal-height-m">Ellipsoidal Height (m)</label>
                <input id="ellipsoidal-height-m" aria-label="H" type="text" value={baseStation.h} onChange={e => setBaseStation({...baseStation, h: e.target.value})} className="input w-full" />
              </div>
              <div>
                <label className="block text-sm mb-1" htmlFor="latitude-decimal">Latitude (decimal °)</label>
                <input id="latitude-decimal" type="text" value={baseStation.lat} onChange={e => setBaseStation({...baseStation, lat: e.target.value})} className="input w-full" aria-label="-1.2921" placeholder="-1.2921" />
              </div>
              <div>
                <label className="block text-sm mb-1" htmlFor="longitude-decimal">Longitude (decimal °)</label>
                <input id="longitude-decimal" type="text" value={baseStation.lon} onChange={e => setBaseStation({...baseStation, lon: e.target.value})} className="input w-full" aria-label="36.8219" placeholder="36.8219" />
              </div>
            </div>
          </div>

          <div className="bg-[var(--card)] border border-[var(--border)] rounded-lg p-4">
            <h3 className="font-semibold mb-4">Local Origin (for ENU)</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm mb-1" htmlFor="latitude">Latitude</label>
                <input id="latitude" aria-label="Lat" type="text" value={origin.lat} onChange={e => setOrigin({...origin, lat: e.target.value})} className="input w-full" />
              </div>
              <div>
                <label className="block text-sm mb-1" htmlFor="longitude">Longitude</label>
                <input id="longitude" aria-label="Lon" type="text" value={origin.lon} onChange={e => setOrigin({...origin, lon: e.target.value})} className="input w-full" />
              </div>
            </div>
          </div>

          <div className="bg-[var(--card)] border border-[var(--border)] rounded-lg p-4">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold">Rover Observations</h3>
              <button onClick={addObservation} className="btn btn-secondary text-sm">{t('toolUI.addPoint')}</button>
            </div>
            <div className="space-y-3">
              {observations.map((obs: any) => (
                <div key={obs.id} className="grid grid-cols-6 gap-2 items-end">
                  <div className="col-span-1">
                    <label className="block text-xs mb-1" htmlFor="name-2">Name</label>
                    <input id="name-2" aria-label="Name" type="text" value={obs.name} onChange={e => updateObservation(obs.id, 'name', e.target.value)} className="input w-full text-sm" />
                  </div>
                  <div className="col-span-1">
                    <label className="block text-xs mb-1" htmlFor="lat">Lat</label>
                    <input id="lat" aria-label="Lat" type="text" value={obs.lat} onChange={e => updateObservation(obs.id, 'lat', e.target.value)} className="input w-full text-sm" />
                  </div>
                  <div className="col-span-1">
                    <label className="block text-xs mb-1" htmlFor="lon">Lon</label>
                    <input id="lon" aria-label="Lon" type="text" value={obs.lon} onChange={e => updateObservation(obs.id, 'lon', e.target.value)} className="input w-full text-sm" />
                  </div>
                  <div className="col-span-1">
                    <label className="block text-xs mb-1" htmlFor="ht-m">Ht (m)</label>
                    <input id="ht-m" aria-label="H" type="text" value={obs.h} onChange={e => updateObservation(obs.id, 'h', e.target.value)} className="input w-full text-sm" />
                  </div>
                  <div className="col-span-1">
                    <label className="block text-xs mb-1" htmlFor="m">σ (m)</label>
                    <input aria-label="Sigma" type="text" value={obs.sigma} onChange={e => updateObservation(obs.id, 'sigma', e.target.value)} className="input w-full text-sm" />
                  </div>
                  <button onClick={() => removeObservation(obs.id)} className="text-red-500 text-sm mb-1">[x]</button>
                </div>
              ))}
            </div>
          </div>

          <button onClick={calculate} className="btn btn-primary w-full">
            Calculate {mode === 'baseline' ? 'Baseline' : 'Network'}
          </button>
        </div>

        <div>
          {result && (
            <div className="bg-[var(--card)] border border-[var(--border)] rounded-lg p-4">
              <h3 className="font-semibold mb-4">Results</h3>
              
              {mode === 'baseline' && result.baseline && (
                <div className="space-y-4">
                  <div className="bg-[var(--bg)] p-3 rounded">
                    <h4 className="text-sm font-medium mb-2">Baseline Vector</h4>
                    <div className="grid grid-cols-2 gap-2 text-sm">
                      <div><span className="text-[var(--text-secondary)]">From:</span> {result.baseline.from}</div>
                      <div><span className="text-[var(--text-secondary)]">To:</span> {result.baseline.to}</div>
                      <div><span className="text-[var(--text-secondary)]">ΔX:</span> {result.baseline.deltaX.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">ΔY:</span> {result.baseline.deltaY.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">ΔZ:</span> {result.baseline.deltaZ.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">Distance 3D:</span> {result.baseline.distance3D.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">Distance 2D:</span> {result.baseline.distance2D.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">Azimuth:</span> {result.baseline.azimuth.toFixed(4)}°</div>
                      <div><span className="text-[var(--text-secondary)]">Elev. Angle:</span> {result.baseline.elevationAngle.toFixed(4)}°</div>
                      <div><span className="text-[var(--text-secondary)]">Sigma:</span> ±{result.baseline.sigma.toFixed(4)} m</div>
                    </div>
                  </div>
                  <div className="bg-[var(--bg)] p-3 rounded">
                    <h4 className="text-sm font-medium mb-2">Local ENU Coordinates</h4>
                    <div className="grid grid-cols-2 gap-2 text-sm">
                      <div><span className="text-[var(--text-secondary)]">Easting:</span> {result.enu.easting.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">Northing:</span> {result.enu.northing.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">Up:</span> {result.enu.up.toFixed(4)} m</div>
                    </div>
                  </div>
                  <div className="bg-[var(--bg)] p-3 rounded">
                    <h4 className="text-sm font-medium mb-2">ECEF Coordinates</h4>
                    <div className="grid grid-cols-3 gap-2 text-sm">
                      <div><span className="text-[var(--text-secondary)]">X:</span> {result.obsECEF.x.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">Y:</span> {result.obsECEF.y.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">Z:</span> {result.obsECEF.z.toFixed(4)} m</div>
                    </div>
                  </div>
                </div>
              )}

              {mode === 'network' && result.points && (
                <div className="space-y-4">
                  <div className="bg-[var(--bg)] p-3 rounded">
                    <h4 className="text-sm font-medium mb-2">Adjusted Points</h4>
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="text-left text-[var(--text-secondary)]">
                          <th className="pb-2">Name</th>
                          <th className="pb-2">Easting</th>
                          <th className="pb-2">Northing</th>
                          <th className="pb-2">Elev</th>
                          <th className="pb-2">σ (m)</th>
                        </tr>
                      </thead>
                      <tbody>
                        {result.points.map((p: any, i: number) => (
                          <tr key={`item-${i}`} className="border-t border-[var(--border)]">
                            <td className="py-2">{p.name}</td>
                            <td>{p.easting.toFixed(4)}</td>
                            <td>{p.northing.toFixed(4)}</td>
                            <td>{p.elevation.toFixed(4)}</td>
                            <td>±{p.sigmaEasting.toFixed(4)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <div className="bg-[var(--bg)] p-3 rounded">
                    <h4 className="text-sm font-medium mb-2">Adjustment Statistics</h4>
                    <div className="grid grid-cols-2 gap-2 text-sm">
                      <div><span className="text-[var(--text-secondary)]">RMS:</span> {result.adjustmentStats.rms.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">Max Residual:</span> {result.adjustmentStats.maxResidual.toFixed(4)} m</div>
                      <div><span className="text-[var(--text-secondary)]">DoF:</span> {result.adjustmentStats.degreesOfFreedom}</div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react';
import { PageHeader } from '@/components/shared/PageHeader'
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { gradeSolved } from '@/lib/engine/solution/wrappers/grade'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function GradeCalculator() {
  const { t } = useLanguage()
  const [elev1, setElev1] = useState('');
  const [elev2, setElev2] = useState('');
  const [distance, setDistance] = useState('');
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    const e1 = parseFloat(elev1);
    const e2 = parseFloat(elev2);
    const d = parseFloat(distance);
    if (isNaN(e1) || isNaN(e2) || isNaN(d) || d === 0) return;
    const s = gradeSolved({ elev1: e1, elev2: e2, horizontalDistance: d })
    setSteps(s.steps); setSolutionTitle(s.solution.title)
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.grade')}
        subtitle={t('tools.gradeDesc')}
        reference="Survey Regulations 1994 | RDM 1.1 (2025) | Survey Act Cap 299"
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="card">
          <div className="card-header"><span className="label">Elevations &amp; Distance</span></div>
          <div className="card-body space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="label" htmlFor="elevation-1-rl-m">Elevation 1 — RL (m)</label>
                <input id="elevation-1-rl-m" className="input" value={elev1} onChange={e => setElev1(e.target.value)} aria-label="100.000" placeholder="100.000" />
              </div>
              <div>
                <label className="label" htmlFor="elevation-2-rl-m">Elevation 2 — RL (m)</label>
                <input id="elevation-2-rl-m" className="input" value={elev2} onChange={e => setElev2(e.target.value)} aria-label="105.500" placeholder="105.500" />
              </div>
            </div>
            <div>
              <label className="label" htmlFor="horizontal-distance-m">Horizontal Distance (m)</label>
              <input className="input" value={distance} onChange={e => setDistance(e.target.value)} aria-label="50.000" placeholder="50.000" />
            </div>
            <button onClick={calculate} className="btn btn-primary w-full">Calculate Gradient</button>
          </div>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react';
import { PageHeader } from '@/components/shared/PageHeader'
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { heightOfObjectSolved } from '@/lib/engine/solution/wrappers/heightOfObject'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function HeightOfObjectCalculator() {
  const { t } = useLanguage()
  const [inputs, setInputs] = useState({
    distance: '',
    angleTop:  { d: '', m: '', s: '' },
    angleBase: { d: '', m: '', s: '' },
    hi: ''
  });
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    const D = parseFloat(inputs.distance);
    const HI = parseFloat(inputs.hi) || 0;
    const degTop  = parseFloat(inputs.angleTop.d)  || 0
    const minTop  = parseFloat(inputs.angleTop.m)  || 0
    const secTop  = parseFloat(inputs.angleTop.s)  || 0
    const degBase = parseFloat(inputs.angleBase.d) || 0
    const minBase = parseFloat(inputs.angleBase.m) || 0
    const secBase = parseFloat(inputs.angleBase.s) || 0
    if (isNaN(D)) return;
    const s = heightOfObjectSolved({
      horizontalDistance: D,
      angleTop:  { degrees: degTop,  minutes: minTop,  seconds: secTop,  direction: 'N' },
      angleBase: { degrees: degBase, minutes: minBase, seconds: secBase, direction: 'N' },
      instrumentHeight: HI,
    })
    setSteps(s.steps); setSolutionTitle(s.solution.title)
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.heightOfObject')}
        subtitle={t('tools.heightOfObjectDesc')}
        reference="Survey Regulations 1994 | Survey Act Cap 299 | RDM 1.1 (2025)"
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="card">
          <div className="card-header"><span className="label">Measurements</span></div>
          <div className="card-body space-y-4">
            <div>
              <label className="label" htmlFor="horizontal-distance-to-base-m">Horizontal Distance to Base (m)</label>
              <input id="horizontal-distance-to-base-m" className="input" value={inputs.distance} onChange={e => setInputs({...inputs, distance: e.target.value})} aria-label="50.000" placeholder="50.000" />
            </div>
            <div>
              <div className="label">Vertical Angle to Top (D° M&apos; S&quot;)</div>
              <div className="flex gap-2">
                <input className="input flex-1" value={inputs.angleTop.d} onChange={e => setInputs({...inputs, angleTop: {...inputs.angleTop, d: e.target.value}})} aria-label="30°" placeholder="30°" />
                <input className="input flex-1" value={inputs.angleTop.m} onChange={e => setInputs({...inputs, angleTop: {...inputs.angleTop, m: e.target.value}})} aria-label="15'" placeholder="15'" />
                <input className="input flex-1" value={inputs.angleTop.s} onChange={e => setInputs({...inputs, angleTop: {...inputs.angleTop, s: e.target.value}})} aria-label="00&quot;" placeholder="00&quot;" />
              </div>
            </div>
            <div>
              <div className="label">Vertical Angle to Base (D° M&apos; S&quot;)</div>
              <div className="flex gap-2">
                <input className="input flex-1" value={inputs.angleBase.d} onChange={e => setInputs({...inputs, angleBase: {...inputs.angleBase, d: e.target.value}})} aria-label="02°" placeholder="02°" />
                <input className="input flex-1" value={inputs.angleBase.m} onChange={e => setInputs({...inputs, angleBase: {...inputs.angleBase, m: e.target.value}})} aria-label="30'" placeholder="30'" />
                <input className="input flex-1" value={inputs.angleBase.s} onChange={e => setInputs({...inputs, angleBase: {...inputs.angleBase, s: e.target.value}})} aria-label="00&quot;" placeholder="00&quot;" />
              </div>
            </div>
            <div>
              <label className="label" htmlFor="height-of-instrument-above-ground-h-i-m">Height of Instrument above Ground, h.i. (m)</label>
              <input className="input" value={inputs.hi} onChange={e => setInputs({...inputs, hi: e.target.value})} aria-label="1.500" placeholder="1.500" />
            </div>
            <button onClick={calculate} className="btn btn-primary w-full">Calculate Height</button>
          </div>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import { riseAndFall, heightOfCollimation } from '@/lib/engine/leveling';
import { trackEvent } from '@/lib/analytics/events';
import type { LevelingInput } from '@/lib/engine/leveling'
import type { LevelingReading } from '@/lib/engine/types';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { levelingSolved } from '@/lib/engine/solution/wrappers/leveling'
import { PageHeader } from '@/components/shared/PageHeader'
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface Reading {
  id: number;
  station: string;
  bs: string;
  fs: string;
}

export default function LevelingCalculator() {
  const { t } = useLanguage()
  const [bm, setBm] = useState('100.0000');
  const [closingBm, setClosingBm] = useState('');
  const [distanceKm, setDistanceKm] = useState('1');
  const [method, setMethod] = useState<'rf' | 'hoc'>('rf');
  const [readings, setReadings] = useState<Reading[]>([
    { id: 1, station: '1', bs: '1.523', fs: '' },
    { id: 2, station: '2', bs: '', fs: '1.234' },
    { id: 3, station: '3', bs: '', fs: '1.456' },
    { id: 4, station: '4', bs: '', fs: '1.789' },
  ]);
  const [result, setResult] = useState<any>(null);
  const [steps, setSteps] = useState<SolutionStep[] | null>(null)
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined)
  const [showProfile, setShowProfile] = useState(false);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false)
  const [calculating, setCalculating] = useState(false);

  const addReading = () => {
    setReadings([...readings, { id: Date.now(), station: String(readings.length + 1), bs: '', fs: '' }]);
  };

  const updateReading = (id: number, field: 'bs' | 'fs', value: string) => {
    setReadings(readings.map((r: any) => r.id === id ? { ...r, [field]: value } : r));
  };

  // method label helper — HPC = Height of Plane of Collimation (British/East African convention)
  const methodLabel = method === 'rf' ? 'Rise & Fall' : 'Height of Collimation (HPC)';

  const copyResults = () => {
    if (!result) return
    const lines = [
      `METARDU Levelling — ${methodLabel}`,
      `Opening RL: ${bm} m`,
      `Misclosure: ${result.misclosure.toFixed(6)} m`,
      `Allowable (10√K mm, K=${distanceKm} km): ±${(result.allowableMisclosure * 1000).toFixed(3)} mm`,
      `Check: ${result.isAcceptable ? 'PASS' : 'FAIL'}`,
      '',
      ...result.readings.map((r: any) =>
        `${r.station.padEnd(8)} ${r.reducedLevel !== undefined ? r.reducedLevel.toFixed(4) : '      '}${r.adjustedRL !== undefined ? ` (adj ${r.adjustedRL.toFixed(4)})` : ''}`
      ),
    ]
    navigator.clipboard.writeText(lines.join('\n'))
      .then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000) })
      .catch(() => {})
  }

  const calculate = () => {
    setCalculating(true);
    setCalcError(null);
    const openingRL = parseFloat(bm);
    const closing = closingBm ? parseFloat(closingBm) : undefined;
    if (isNaN(openingRL)) { setCalculating(false); return; }

    const obs = readings.map((r: any) => ({
      station: r.station,
      bs: r.bs ? parseFloat(r.bs) : undefined,
      fs: r.fs ? parseFloat(r.fs) : undefined
    }));

    const levelingInput: LevelingInput =
      method === 'rf'
        ? { readings: obs, openingRL, closingRL: closing, method: 'rise_and_fall', distanceKm: parseFloat(distanceKm) || 1 }
        : { readings: obs, openingRL, closingRL: closing, method: 'height_of_collimation', distanceKm: parseFloat(distanceKm) || 1 }

    const r = method === 'rf' ? riseAndFall(levelingInput) : heightOfCollimation(levelingInput);

    // BLOCK RESULTS if arithmetic check fails (Basak rule)
    if (!r.arithmeticCheck) {
      setCalcError(
        'Arithmetic check failed — results cannot be displayed. ' +
        'Per Basak standards: ΣBS − ΣFS must equal ΣRise − ΣFall. ' +
        'Check your readings for entry errors.'
      );
      setResult(null);
      setCalculating(false);
      return;
    }

    setCalcError(null);
    setResult(r);
    trackEvent('tool_used', { tool: 'leveling', method });
    const s = levelingSolved(levelingInput, r)
    setSteps(s.steps)
    setSolutionTitle(s.solution.title)
    setCalculating(false);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.leveling')}
        subtitle={t('tools.levelingDesc')}
        reference="RDM 1.1 (2025) Table 5.1 | Survey Act Cap 299 | Survey Regulations 1994"
      />

      <div className="grid md:grid-cols-3 gap-4 mb-6">
        <div className="card p-4">
          <label className="label" htmlFor="opening-benchmark-m">Opening Benchmark (m)</label>
          <input id="opening-benchmark-m" aria-label="Opening Benchmark (m)" className="input" value={bm} onChange={e => setBm(e.target.value)} />
        </div>
        <div className="card p-4">
          <label className="label" htmlFor="closing-benchmark-m">Closing Benchmark (m)</label>
          <input id="closing-benchmark-m" className="input" value={closingBm} onChange={e => setClosingBm(e.target.value)} aria-label="Optional" placeholder="Optional" />
        </div>
        <div className="card p-4">
          <label className="label" htmlFor="distance-km-for-allowable-error">Distance (km) for allowable error</label>
          <input id="distance-km-for-allowable-error" className="input" value={distanceKm} onChange={e => setDistanceKm(e.target.value)} aria-label="1" placeholder="1" />
        </div>
        <div className="card p-4">
          <div className="label">Method</div>
          <div className="flex gap-2 mt-2">
            <button onClick={() => { setMethod('rf'); setResult(null); setSteps(null); setSolutionTitle(undefined); setCalcError(null); }} className={`flex-1 btn text-xs ${method === 'rf' ? 'btn-primary' : 'btn-secondary'}`}>
              Rise &amp; Fall
            </button>
            {/* "Height of Collimation" = HPC method; British/East African convention */}
            <button onClick={() => { setMethod('hoc'); setResult(null); setSteps(null); setSolutionTitle(undefined); setCalcError(null); }} className={`flex-1 btn text-xs ${method === 'hoc' ? 'btn-primary' : 'btn-secondary'}`}>
              Height of Collimation
            </button>
          </div>
        </div>
      </div>

      {calcError && (
        <div className="mb-6 rounded-lg border border-red-500/40 bg-red-500/10 p-4 text-sm text-red-300">
          <p className="font-semibold mb-1">Arithmetic check failed</p>
          <p>{calcError}</p>
        </div>
      )}

      <div className="card mb-6">
        <div className="card-header">
          <span className="label">Level Book — {methodLabel}</span>
        </div>
        <div className="overflow-x-auto">
          <table className="table">
            <thead>
              <tr>
                <th>Station</th>
                <th>BS (m)</th>
                <th>FS (m)</th>
                <th>Rise (m)</th>
                <th>Fall (m)</th>
                <th>RL (m)</th>
                {result && <th>Adj RL (m)</th>}
              </tr>
            </thead>
            <tbody>
              <tr>
                <td className="text-left font-semibold">BM</td>
                <td colSpan={2} className="text-left text-[var(--text-muted)]">{bm}</td>
                <td></td>
                <td></td>
                <td className="font-mono">{bm}</td>
                <td className="font-mono">{bm}</td>
              </tr>
              {readings.map((r, i) => (
                <tr key={r.id}>
                  <td className="text-left">{r.station}</td>
                  <td><input className="input" value={r.bs} onChange={e => updateReading(r.id, 'bs', e.target.value)} aria-label="0.000" placeholder="0.000" /></td>
                  <td><input className="input" value={r.fs} onChange={e => updateReading(r.id, 'fs', e.target.value)} aria-label="0.000" placeholder="0.000" /></td>
                  {result ? (
                    <>
                      <td className="font-mono">{result.readings[i + 1]?.rise?.toFixed(4) || '—'}</td>
                      <td className="font-mono">{result.readings[i + 1]?.fall?.toFixed(4) || '—'}</td>
                      <td className="font-mono">{result.readings[i + 1]?.reducedLevel?.toFixed(4) || '—'}</td>
                      <td className="font-mono">{result.readings[i + 1]?.adjustedRL?.toFixed(4) || '—'}</td>
                    </>
                  ) : (
                    <td colSpan={4}></td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="p-4">
          <button onClick={addReading} className="btn btn-secondary">{t('toolUI.addReading')}</button>
        </div>
      </div>

      <div className="flex flex-wrap gap-3 mb-6">
        <button onClick={calculate} disabled={calculating} className="btn btn-primary disabled:opacity-60 disabled:cursor-not-allowed">
          {calculating ? (
            <><svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8z"/></svg>{t('toolUI.calculating')}</>
          ) : t('toolUI.calculate')}
        </button>
        {result && (
          <>
            <button
              onClick={() => {
                if (!result) return
                generatePDF(
                  { title: 'Levelling Computation Sheet', reference: 'RDM 1.1 (2025) Table 5.1 | Survey Act Cap 299' },
                  [
                    { title: 'Computation Summary', rows: [
                      { label: 'Method', value: methodLabel },
                      { label: 'Opening RL', value: `${bm} m` },
                      { label: 'Misclosure', value: `${result.misclosure.toFixed(6)} m` },
                      { label: 'Allowable (10√K mm)', value: `±${(result.allowableMisclosure * 1000).toFixed(3)} mm` },
                      { label: 'Arithmetic Check', value: result.arithmeticCheck ? 'PASS' : 'FAIL' },
                      { label: 'Status', value: result.isAcceptable ? 'Acceptable' : 'Unacceptable' },
                    ]},
                  ],
                  [
                    { title: 'Level Book Observations', headers: ['Station', 'BS (m)', 'FS (m)', 'Rise (m)', 'Fall (m)', 'RL (m)', 'Adj RL (m)'], rows: result.readings.map((r: any) => [
                      r.station || '—', r.bs?.toFixed(4) || '—', r.fs?.toFixed(4) || '—',
                      r.rise?.toFixed(4) || '—', r.fall?.toFixed(4) || '—',
                      r.reducedLevel?.toFixed(4) || '—', r.adjustedRL?.toFixed(4) || '—',
                    ]) },
                  ],
                )
              }}
              className="btn btn-secondary inline-flex items-center gap-2"
            >
              <Download className="w-4 h-4" /> {t('toolUI.exportPdf')}
            </button>
            <button
              onClick={() => {
                if (!result) return
                const csv = toCSV(
                  ['Station', 'BS (m)', 'FS (m)', 'Rise (m)', 'Fall (m)', 'RL (m)', 'Adj RL (m)', 'Remarks'],
                  result.readings.map((r: any) => [
                    r.station || '', r.bs?.toFixed(4) || '', r.fs?.toFixed(4) || '',
                    r.rise?.toFixed(4) || '', r.fall?.toFixed(4) || '',
                    r.reducedLevel?.toFixed(4) || '', r.adjustedRL?.toFixed(4) || '', '',
                  ]),
                )
                downloadCSV(csv, 'levelling-observations')
              }}
              className="btn btn-secondary inline-flex items-center gap-2"
            >
              <Download className="w-4 h-4" /> {t('toolUI.exportCsv')}
            </button>
          </>
        )}
      </div>

      {result && (
        <div className="grid md:grid-cols-2 gap-6">
          <div className="card">
            <div className="card-header flex justify-between items-center">
              <span className="label">Results — {methodLabel}</span>
              <div className="flex items-center gap-2">
                <span className={`badge ${result.isAcceptable ? 'badge-success' : 'badge-error'}`}>
                  {result.isAcceptable ? 'Acceptable' : 'Unacceptable'}
                </span>
                <button
                  onClick={copyResults}
                  className="text-xs text-[var(--accent)] hover:text-[var(--accent-dim)] transition-colors"
                >
                  {copied ? t('toolUI.copied') : 'Copy'}
                </button>
              </div>
            </div>
            <div className="card-body space-y-3">
              <ResultRow label="Method" value={methodLabel} />
              <ResultRow label="Misclosure" value={`${result.misclosure.toFixed(6)} m`} />
              <ResultRow label="Allowable (C = 10√K mm)" value={`±${(result.allowableMisclosure * 1000).toFixed(3)} mm`} />
              <ResultRow
                label="Arithmetic Check (ΣBS − ΣFS = Last RL − First RL)"
                value={result.arithmeticCheck ? 'PASS ' : 'FAIL [x]'}
                highlight={result.arithmeticCheck}
              />
            </div>
          </div>

          <div className="card">
            <div className="card-header">
              <span className="label">Summary</span>
            </div>
            <div className="card-body space-y-2 text-sm">
              <div className="flex justify-between py-2 border-b border-[var(--border-color)]">
                <span className="text-[var(--text-secondary)]">Opening RL</span>
                <span className="font-mono">{bm} m</span>
              </div>
              {result.readings.length > 0 && (
                <div className="flex justify-between py-2 border-b border-[var(--border-color)]">
                  <span className="text-[var(--text-secondary)]">Final RL (Raw)</span>
                  <span className="font-mono">{result.readings[result.readings.length - 1]?.reducedLevel?.toFixed(4)} m</span>
                </div>
              )}
              {result.readings.some((r: LevelingReading) => r.adjustedRL) && (
                <div className="flex justify-between py-2 border-b border-[var(--border-color)]">
                  <span className="text-[var(--text-secondary)]">Final RL (Adjusted)</span>
                  <span className="font-mono result-accent">
                    {result.readings[result.readings.length - 1]?.adjustedRL?.toFixed(4)} m
                  </span>
                </div>
              )}
            </div>
          </div>

          {steps ? (
            <div className="md:col-span-2">
              <SolutionStepsRenderer title={solutionTitle} steps={steps} />
            </div>
          ) : null}

          {result && result.readings.length > 0 && (
            <div className="mt-4">
              <button
                onClick={() => setShowProfile(!showProfile)}
                className="w-full px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded"
              >
                {showProfile ? 'Hide Profile' : 'View Longitudinal Profile'}
              </button>

              {showProfile && (
                <div className="mt-4 bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
                  <h3 className="font-semibold text-[var(--text-primary)] mb-4">Longitudinal Profile</h3>
                  <LevelingProfile readings={result.readings} />
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function ResultRow({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
  return (
    <div className="flex justify-between items-center py-2 border-b border-[var(--border-color)]">
      <span className="text-sm text-[var(--text-secondary)]">{label}</span>
      <span className={`font-mono ${highlight !== undefined ? (highlight ? 'result-positive' : 'result-negative') : ''}`}>
        {value}
      </span>
    </div>
  );
}

function LevelingProfile({ readings }: { readings: any[] }) {
  const width = 600;
  const height = 250;
  const padding = 50;

  const validReadings = readings.filter((r: any) => r.reducedLevel !== undefined);
  if (validReadings.length === 0) return null;

  const rls = validReadings.map((r: any) => r.adjustedRL || r.reducedLevel);
  const minRL = Math.min(...rls) - 0.5;
  const maxRL = Math.max(...rls) + 0.5;
  const maxIdx = validReadings.length - 1;

  const toX = (idx: number) => padding + (idx / maxIdx) * (width - padding * 2);
  const toY = (rl: number) => height - padding - ((rl - minRL) / (maxRL - minRL)) * (height - padding * 2);

  const pathData = validReadings.map((r, i) => {
    const rl = r.adjustedRL || r.reducedLevel;
    return `${i === 0 ? 'M' : 'L'} ${toX(i)} ${toY(rl)}`;
  }).join(' ');

  return (
    <svg width="100%" viewBox={`0 0 ${width} ${height}`} className="bg-[var(--bg-secondary)] rounded border border-amber-500/30">
      <defs>
        <pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse">
          <path d="M 20 0 L 0 0 0 20" fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth="0.5"/>
        </pattern>
      </defs>
      <rect width={width} height={height} fill="url(#grid)"/>
      <path d={pathData} stroke="#D17B47" strokeWidth={2} fill="none"/>
      {validReadings.map((r, i) => {
        const rl = r.adjustedRL || r.reducedLevel;
        return (
          <g key={r.station}>
            <circle cx={toX(i)} cy={toY(rl)} r={4} fill="#D17B47"/>
            <text x={toX(i)} y={height - 10} fill="white" fontSize={9} textAnchor="middle">{r.station}</text>
            <text x={toX(i)} y={toY(rl) - 8} fill="white" fontSize={7} textAnchor="middle">{rl.toFixed(2)}</text>
          </g>
        );
      })}
      <line x1={padding} y1={padding} x2={padding} y2={height - padding} stroke="white" strokeWidth={1}/>
      <line x1={padding} y1={height - padding} x2={width - padding} y2={height - padding} stroke="white" strokeWidth={1}/>
      <text x={width/2} y={height - 2} fill="gray" fontSize={9} textAnchor="middle">Station</text>
      <text x={12} y={height/2} fill="gray" fontSize={9} textAnchor="middle" transform={`rotate(-90, 12, ${height/2})`}>Reduced Level (m)</text>
    </svg>
  );
}

'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react';
import { PageHeader } from '@/components/shared/PageHeader'
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { distanceBearingSolvedFromCoords } from '@/lib/engine/solution/wrappers/distance'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function MissingLineCalculator() {
  const { t } = useLanguage()
  const [pointA, setPointA] = useState({ e: '', n: '' });
  const [pointB, setPointB] = useState({ e: '', n: '' });
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    const e1 = parseFloat(pointA.e);
    const n1 = parseFloat(pointA.n);
    const e2 = parseFloat(pointB.e);
    const n2 = parseFloat(pointB.n);
    if (isNaN(e1) || isNaN(n1) || isNaN(e2) || isNaN(n2)) return;
    const s = distanceBearingSolvedFromCoords({ e1, n1, e2, n2 })
    setSteps(s.steps); setSolutionTitle(s.solution.title)
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.missingLine')}
        subtitle={t('tools.missingLineDesc')}
        reference="Survey Regulations 1994 | Survey Act Cap 299 | WCB (Whole Circle Bearing)"
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="card">
          <div className="card-header"><span className="label">Point A → Point B</span></div>
          <div className="card-body space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="label" htmlFor="point-a-easting-m">Point A Easting (m)</label>
                <input id="point-a-easting-m" className="input" value={pointA.e} onChange={e => setPointA({...pointA, e: e.target.value})} aria-label="500000.0000" placeholder="500000.0000" />
              </div>
              <div>
                <label className="label" htmlFor="point-a-northing-m">Point A Northing (m)</label>
                <input id="point-a-northing-m" className="input" value={pointA.n} onChange={e => setPointA({...pointA, n: e.target.value})} aria-label="9500000.0000" placeholder="9500000.0000" />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="label" htmlFor="point-b-easting-m">Point B Easting (m)</label>
                <input id="point-b-easting-m" className="input" value={pointB.e} onChange={e => setPointB({...pointB, e: e.target.value})} aria-label="500050.0000" placeholder="500050.0000" />
              </div>
              <div>
                <label className="label" htmlFor="point-b-northing-m">Point B Northing (m)</label>
                <input className="input" value={pointB.n} onChange={e => setPointB({...pointB, n: e.target.value})} aria-label="9500030.0000" placeholder="9500030.0000" />
              </div>
            </div>
            <button onClick={calculate} className="btn btn-primary w-full">Calculate Missing Line</button>
          </div>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      {steps && <ToolExportButtons title="missing-line" rows={steps.map(s => ({ label: s.label, value: s.result || s.computation || "" }))} csvRows={steps.map(s => [s.label, s.result || ""])} disabled={!steps} />}
      </div>
    </div>
  );
}

