function formatArea(sqm: number): string {
  if (sqm >= 1_000_000) {
    return (sqm / 1_000_000).toFixed(2) + 'M';
  }
  if (sqm >= 10_000) {
    return (sqm / 1_000).toFixed(1) + 'K';
  }
  return sqm.toFixed(2);
}

