'use client'

/**
 * VolumeTab — Volume computation from point clouds.
 *
 * Wired to src/lib/compute/pointCloudVolume.ts
 *
 * Computes cut/fill volumes between two surfaces using:
 *   - Grid method (IDW interpolation to regular grid)
 *   - TIN-to-TIN method (adaptive cell size)
 *   - Stockpile volume (single surface + base plane)
 *
 * Includes cross-check: grid vs. TIN should agree within 2%.
 */

import { useState, useCallback } from 'react'
import {
  gridMethodVolume,
  tinToTinVolume,
  stockpileVolume,
  crossCheckVolume,
  type Point3D,
  type VolumeResult,
} from '@/lib/compute/pointCloudVolume'
import { Layers, TrendingDown, TrendingUp, ArrowDownToLine, AlertCircle, CheckCircle2 } from 'lucide-react'

interface VolumeTabProps {
  /** Points from the imported point cloud */
  points: Array<{ easting: number; northing: number; elevation: number }>
}

export function VolumeTab({ points }: VolumeTabProps) {
  const [mode, setMode] = useState<'cutfill' | 'stockpile'>('cutfill')
  const [cellSize, setCellSize] = useState(1.0)
  const [baseElevation, setBaseElevation] = useState(0)
  const [result, setResult] = useState<VolumeResult | null>(null)
  const [crossCheck, setCrossCheck] = useState<ReturnType<typeof crossCheckVolume> | null>(null)
  const [loading, setLoading] = useState(false)

  const compute = useCallback(async () => {
    setLoading(true)
    try {
      // Use a small timeout to let the UI update (computation can take a moment for large datasets)
      await new Promise(r => setTimeout(r, 50))

      const pts = points as Point3D[]

      if (mode === 'stockpile') {
        const r = stockpileVolume(pts, baseElevation)
        setResult(r)
        setCrossCheck(null)
      } else {
        // Cut/Fill: we need two surfaces. For a single point cloud,
        // we use the grid method with the imported surface as "surface1"
        // and a flat base plane as "surface2".
        const baseSurface: Point3D[] = pts.map(p => ({ ...p, elevation: baseElevation }))
        const r = gridMethodVolume(pts, baseSurface, cellSize)
        setResult(r)

        // Also compute via TIN method for cross-check
        const cc = crossCheckVolume(pts, baseSurface)
        setCrossCheck(cc)
      }
    } finally {
      setLoading(false)
    }
  }, [points, mode, cellSize, baseElevation])

  if (points.length < 3) {
    return (
      <div className="flex flex-col items-center justify-center h-64 text-center">
        <Layers className="w-10 h-10 text-[var(--text-muted)] mb-3 opacity-50" />
        <p className="text-sm text-[var(--text-muted)]">
          Import a point cloud first to compute volumes.
        </p>
        <p className="text-xs text-[var(--text-muted)] mt-1">
          Need at least 3 points with elevation data.
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Mode selector */}
      <div className="flex gap-2">
        <button
          onClick={() => setMode('cutfill')}
          className={`flex-1 py-2 rounded-lg text-xs font-medium transition-all ${
            mode === 'cutfill'
              ? 'bg-[var(--accent)] text-black'
              : 'bg-[var(--bg-tertiary)] text-[var(--text-muted)]'
          }`}
        >
          Cut / Fill (vs. Base)
        </button>
        <button
          onClick={() => setMode('stockpile')}
          className={`flex-1 py-2 rounded-lg text-xs font-medium transition-all ${
            mode === 'stockpile'
              ? 'bg-[var(--accent)] text-black'
              : 'bg-[var(--bg-tertiary)] text-[var(--text-muted)]'
          }`}
        >
          Stockpile Volume
        </button>
      </div>

      {/* Parameters */}
      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="base-elevation-m">
            Base Elevation (m)
          </label>
          <input id="base-elevation-m"
            type="number"
            step="0.1"
            value={baseElevation}
            onChange={e => setBaseElevation(parseFloat(e.target.value) || 0)}
            className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm text-[var(--text-primary)]"
          />
        </div>
        {mode === 'cutfill' && (
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="grid-cell-size-m">
              Grid Cell Size (m)
            </label>
            <input
              type="number"
              step="0.5"
              min="0.5"
              value={cellSize}
              onChange={e => setCellSize(parseFloat(e.target.value) || 1)}
              className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-sm text-[var(--text-primary)]"
            />
          </div>
        )}
      </div>

      {/* Compute button */}
      <button
        onClick={compute}
        disabled={loading}
        className="w-full py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 text-sm flex items-center justify-center gap-2"
      >
        {loading ? 'Computing...' : `Compute ${mode === 'cutfill' ? 'Cut/Fill' : 'Stockpile'} Volume`}
      </button>

      {/* Results */}
      {result && (
        <div className="space-y-4">
          {/* Volume summary */}
          <div className="grid grid-cols-3 gap-3">
            <div className="rounded-xl border border-red-500/20 bg-red-500/5 p-3 text-center">
              <TrendingDown className="w-5 h-5 text-red-400 mx-auto mb-1" />
              <p className="text-lg font-bold text-red-400">{result.cut.toFixed(1)}</p>
              <p className="text-[10px] text-[var(--text-muted)] uppercase">Cut (m³)</p>
            </div>
            <div className="rounded-xl border border-emerald-500/20 bg-emerald-500/5 p-3 text-center">
              <TrendingUp className="w-5 h-5 text-emerald-400 mx-auto mb-1" />
              <p className="text-lg font-bold text-emerald-400">{result.fill.toFixed(1)}</p>
              <p className="text-[10px] text-[var(--text-muted)] uppercase">Fill (m³)</p>
            </div>
            <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-3 text-center">
              <ArrowDownToLine className="w-5 h-5 text-[var(--accent)] mx-auto mb-1" />
              <p className={`text-lg font-bold ${result.net >= 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                {result.net.toFixed(1)}
              </p>
              <p className="text-[10px] text-[var(--text-muted)] uppercase">Net (m³)</p>
            </div>
          </div>

          {/* Method + area */}
          <div className="flex items-center justify-between text-xs text-[var(--text-muted)]">
            <span>Method: {result.method}</span>
            <span>Area: {(result.area / 10000).toFixed(4)} ha ({result.area.toFixed(1)} m²)</span>
          </div>

          {/* Cross-check result */}
          {crossCheck && (
            <div className={`rounded-xl border p-3 flex items-center gap-3 ${
              crossCheck.agree
                ? 'border-emerald-500/20 bg-emerald-500/5'
                : 'border-amber-500/20 bg-amber-500/5'
            }`}>
              {crossCheck.agree
                ? <CheckCircle2 className="w-5 h-5 text-emerald-400 shrink-0" />
                : <AlertCircle className="w-5 h-5 text-amber-400 shrink-0" />
              }
              <div className="flex-1">
                <p className="text-xs font-semibold text-[var(--text-primary)]">
                  Cross-check: {crossCheck.agree ? 'Methods agree' : 'Methods disagree'}
                </p>
                <p className="text-[10px] text-[var(--text-muted)]">
                  Grid: {crossCheck.gridResult.net.toFixed(1)}m³ vs TIN: {crossCheck.tinResult.net.toFixed(1)}m³
                  (diff: {crossCheck.differencePercent.toFixed(2)}%)
                </p>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { MAX_POINTS } from './constants';
import type { ColumnMapping, ImportedPoint, ParseError } from './types';

export function fmt(n: number, d: number = 4): string {
  return n.toFixed(d);
}

export function detectDelimiter(text: string): string {
  const firstLines = text.split('\n').slice(0, 5);
  let commaCount = 0;
  let tabCount = 0;
  let semicolonCount = 0;
  let spaceCount = 0;

  for (const line of firstLines) {
    if (line.startsWith('#') || line.trim() === '') continue;
    commaCount += (line.match(/,/g) || []).length;
    tabCount += (line.match(/\t/g) || []).length;
    semicolonCount += (line.match(/;/g) || []).length;
    spaceCount += (line.match(/ {2,}/g) || []).length;
  }

  const counts: [string, number][] = [
    ['\t', tabCount],
    [',', commaCount],
    [';', semicolonCount],
    [' ', spaceCount],
  ];
  counts.sort((a, b) => b[1] - a[1]);
  return counts[0][0];
}

export function isHeaderLine(line: string): boolean {
  const lower = line.toLowerCase();
  const headerKeywords = [
    'easting', 'northing', 'elevation', 'name', 'point', 'id',
    'x', 'y', 'z', 'e', 'n', 'rl', 'height', 'lat', 'lon',
  ];
  const tokens = lower.split(/[\t,; ]+/).filter(t => t.length > 0);
  if (tokens.length === 0) return false;

  // If more than half the tokens are header-like keywords, it's a header
  const matchCount = tokens.filter(t =>
    headerKeywords.some(kw => t === kw || t.includes(kw))
  ).length;
  return matchCount >= Math.ceil(tokens.length * 0.5);
}

export function guessColumnIndices(headers: string[]): ColumnMapping {
  const lower = headers.map(h => h.toLowerCase().trim());

  const eastingIdx = lower.findIndex(h =>
    h === 'easting' || h === 'e' || h === 'x' || h.includes('east') || h.includes('easting')
  );
  const northingIdx = lower.findIndex(h =>
    h === 'northing' || h === 'n' || h === 'y' || h.includes('north') || h.includes('northing')
  );
  const elevIdx = lower.findIndex(h =>
    h === 'elevation' || h === 'z' || h === 'rl' || h === 'height' ||
    h.includes('elev') || h.includes('height') || h === 'level'
  );
  const nameIdx = lower.findIndex(h =>
    h === 'name' || h === 'id' || h === 'point' || h === 'pointname' ||
    h === 'point_name' || h === 'code' || h.includes('name') || h.includes('id')
  );

  return {
    id: lower.indexOf('id') >= 0 ? lower.indexOf('id') : -1,
    easting: eastingIdx >= 0 ? eastingIdx : 0,
    northing: northingIdx >= 0 ? northingIdx : 1,
    elevation: elevIdx >= 0 ? elevIdx : 2,
    name: nameIdx >= 0 ? nameIdx : -1,
  };
}

export function parseXYZText(text: string): {
  points: ImportedPoint[];
  errors: ParseError[];
  totalLines: number;
  delimiter: string;
  hasHeader: boolean;
} {
  const delimiter = detectDelimiter(text);
  const lines = text.split('\n');
  const errors: ParseError[] = [];
  const points: ImportedPoint[] = [];
  const splitRe = delimiter === ' ' ? /\s+/ : new RegExp(`(?:${delimiter === '\t' ? '\\t' : delimiter})+`);
  let startIdx = 0;
  let hasHeader = false;

  // Detect header
  if (lines.length > 0 && isHeaderLine(lines[0])) {
    hasHeader = true;
    startIdx = 1;
  }

  // Detect comment lines
  while (startIdx < lines.length && lines[startIdx].trim().startsWith('#')) {
    startIdx++;
  }

  let colMapping: ColumnMapping | null = null;
  if (hasHeader) {
    const headers = lines[0].split(splitRe).map(h => h.trim());
    colMapping = guessColumnIndices(headers);
  }

  // Check the first data row to determine column count
  const firstDataRowIdx = startIdx;
  let colCount = 3;
  for (let i = startIdx; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const parts = trimmed.split(splitRe);
    if (parts.length >= 3) {
      colCount = parts.length;
      break;
    }
  }

  // Default column mapping for 3-column data
  if (!colMapping) {
    if (colCount === 3) {
      colMapping = { id: -1, easting: 0, northing: 1, elevation: 2, name: -1 };
    } else if (colCount >= 4) {
      colMapping = { id: -1, easting: 1, northing: 2, elevation: 3, name: 0 };
    }
  }

  for (let i = startIdx; i < lines.length && points.length < MAX_POINTS; i++) {
    const trimmed = lines[i].trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;

    const parts = trimmed.split(splitRe).map(s => s.trim());

    if (parts.length < 3) {
      errors.push({ row: i + 1, message: `Too few columns (${parts.length})` });
      continue;
    }

    const mapping = colMapping!;
    const eIdx = mapping.easting;
    const nIdx = mapping.northing;
    const zIdx = mapping.elevation;
    const nameIdx = mapping.name;

    const easting = parseFloat(parts[eIdx]);
    const northing = parseFloat(parts[nIdx]);
    const elevation = parseFloat(parts[zIdx]);

    if (isNaN(easting) || isNaN(northing) || isNaN(elevation)) {
      errors.push({ row: i + 1, message: 'Non-numeric coordinate value' });
      continue;
    }

    const pointName = nameIdx >= 0 && nameIdx < parts.length
      ? parts[nameIdx]
      : `P${points.length + 1}`;

    points.push({
      id: `pt-${points.length}`,
      name: pointName,
      easting,
      northing,
      elevation,
    });
  }

  return {
    points,
    errors: errors.slice(0, 50), // Cap displayed errors
    totalLines: lines.length,
    delimiter,
    hasHeader,
  };
}

export function downloadCSV(filename: string, csvString: string) {
  const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

