  { date: '2025-03-01', phase: 'Mapping', event: 'Working diagram draft started', type: 'task' },
]

const STATUS_CONFIG: Record<PhaseProgress['status'], { icon: React.ReactNode; color: string; label: string }> = {
  completed: { icon: <CheckCircle2 className="w-4 h-4" />, color: 'text-emerald-400', label: 'Completed' },
  in_progress: { icon: <PlayCircle className="w-4 h-4" />, color: 'text-amber-400', label: 'In Progress' },
  pending: { icon: <Clock className="w-4 h-4" />, color: 'text-gray-400', label: 'Pending' },
  delayed: { icon: <AlertTriangle className="w-4 h-4" />, color: 'text-red-400', label: 'Delayed' },
}

function ProgressMonitorPage() {
  const { t } = useLanguage()
  const [activeTab, setActiveTab] = useState<'overview' | 'inspections'>('overview')
  const searchParams = useSearchParams()
  const projectId = searchParams.get('project') || undefined

  // If project is linked, don't show demo data — let ProgressMonitorPanel load real data
  const phases = projectId ? [] : DEMO_PHASES
  const timeline = projectId ? [] : DEMO_TIMELINE

  const overallProgress = useMemo(() => {
    const total = phases.reduce((sum, p) => sum + p.progress, 0)
    return Math.round(total / phases.length)
  }, [phases])

  const completedTasks = useMemo(() => {
    return phases.reduce((sum, p) => sum + p.tasks.filter(t => t.done).length, 0)
  }, [phases])

  const totalTasks = useMemo(() => {
    return phases.reduce((sum, p) => sum + p.tasks.length, 0)
  }, [phases])

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-6">
      {/* ── HEADER ──────────────────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-[var(--text-primary)]">{t('tools.progressMonitor')}</h1>
          <p className="text-sm text-[var(--text-muted)] mt-1">{t('tools.progressMonitorDesc')}</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => {
              generatePDF(
                { title: 'Project Progress Report', reference: 'KENHA Supervision Manual | RDM 1.3 §10' },
                [
                  { title: 'Overall Summary', rows: [
                    { label: 'Overall Progress', value: `${overallProgress}%` },
                    { label: 'Tasks Completed', value: `${completedTasks} / ${totalTasks}` },
                    { label: 'Phases In Progress', value: String(phases.filter(p => p.status === 'in_progress').length) },
                    { label: 'Phases Completed', value: String(phases.filter(p => p.status === 'completed').length) },
                  ]},
                  ...phases.map(p => ({
                    title: `${p.name} — ${p.progress}%`,
                    rows: p.tasks.map(t => ({ label: t.name, value: t.done ? ' Done' : 'Pending' })),
                  })),
                ],
              )
            }}
            className="btn btn-secondary inline-flex items-center gap-2"
          >
            <Download className="w-4 h-4" /> PDF
          </button>
          <button
            onClick={() => {
              const csv = toCSV(
                ['Phase', 'Progress %', 'Status', 'Start Date', 'End Date', 'Task', 'Task Status'],
                phases.flatMap(p =>
                  p.tasks.map(t => [p.name, String(p.progress), p.status, p.startDate, p.endDate, t.name, t.done ? 'Done' : 'Pending']),
                ),
              )
              downloadCSV(csv, 'progress-report')
            }}
            className="btn btn-secondary inline-flex items-center gap-2"
          >
            <Download className="w-4 h-4" /> CSV
          </button>
        </div>
      </div>

      {/* ── OVERALL PROGRESS BAR ─────────────────────────────────────────────── */}
      <div className="card p-6">
        <div className="flex items-center justify-between mb-3">
          <span className="text-sm font-semibold text-[var(--text-primary)]">Overall Progress</span>
          <span className="text-2xl font-bold font-mono text-[var(--accent)]">{overallProgress}%</span>
        </div>
        <div className="w-full bg-[var(--bg-tertiary)] rounded-full h-4 overflow-hidden">
          <div
            className="h-full bg-[var(--accent)] rounded-full transition-all duration-500"
            style={{ width: `${overallProgress}%` }}
          />
        </div>
        <div className="flex justify-between mt-2 text-xs text-[var(--text-muted)]">
          <span>{completedTasks} of {totalTasks} tasks completed</span>
          <span>{phases.filter(p => p.status === 'in_progress').length} phases in progress</span>
        </div>
      </div>

      {/* ── TAB BAR ──────────────────────────────────────────────────────────── */}
      <div className="flex gap-1 border-b border-[var(--border-color)]">
        <button
          onClick={() => setActiveTab('overview')}
          className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
            activeTab === 'overview'
              ? 'border-[var(--accent)] text-[var(--accent)]'
              : 'border-transparent text-[var(--text-muted)]'
          }`}
        >
          <BarChart3 className="w-4 h-4 inline mr-1.5" />Phase Overview
        </button>
        <button
          onClick={() => setActiveTab('inspections')}
          className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
            activeTab === 'inspections'
              ? 'border-[var(--accent)] text-[var(--accent)]'
              : 'border-transparent text-[var(--text-muted)]'
          }`}
        >
          <CheckCircle2 className="w-4 h-4 inline mr-1.5" />Inspection Checkpoints
        </button>
      </div>

      {/* ── PHASE OVERVIEW TAB ───────────────────────────────────────────────── */}
      {activeTab === 'overview' && (
        <div className="grid md:grid-cols-2 gap-6">
          {/* Phase cards */}
          <div className="space-y-4">
            {phases.map(phase => {
              const config = STATUS_CONFIG[phase.status]
              const doneCount = phase.tasks.filter(t => t.done).length
              return (
                <div key={phase.id} className="card overflow-hidden">
                  <div className="p-4">
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-2">
                        <span className={`flex items-center gap-1.5 text-xs font-semibold ${config.color}`}>
                          {config.icon} {config.label}
                        </span>
                        <h3 className="text-sm font-semibold text-[var(--text-primary)]">{phase.name}</h3>
                      </div>
                      <span className="text-lg font-bold font-mono text-[var(--accent)]">{phase.progress}%</span>
                    </div>

                    {/* Progress bar */}
                    <div className="w-full bg-[var(--bg-tertiary)] rounded-full h-2.5 mb-3 overflow-hidden">
                      <div
                        className={`h-full rounded-full transition-all duration-500 ${
                          phase.status === 'completed' ? 'bg-emerald-500' :
                          phase.status === 'delayed' ? 'bg-red-500' : 'bg-[var(--accent)]'
                        }`}
                        style={{ width: `${phase.progress}%` }}
                      />
                    </div>

                    <p className="text-xs text-[var(--text-muted)] mb-2">{phase.description}</p>

                    <div className="flex justify-between text-xs text-[var(--text-muted)] mb-3">
                      <span>{phase.startDate} → {phase.endDate}</span>
                      <span>{doneCount}/{phase.tasks.length} tasks</span>
                    </div>

                    {/* Task checklist */}
                    <div className="space-y-1">
                      {phase.tasks.map((task, i) => (
                        <div key={`${task}-${i}`} className="flex items-center gap-2 text-xs">
                          <span className={`w-4 h-4 rounded border flex items-center justify-center shrink-0 ${
                            task.done
                              ? 'bg-emerald-900/40 border-emerald-700 text-emerald-400'
                              : 'border-[var(--border-color)] text-[var(--text-muted)]'
                          }`}>
                            {task.done && ''}
                          </span>
                          <span className={task.done ? 'text-[var(--text-muted)] line-through' : 'text-[var(--text-secondary)]'}>
                            {task.name}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )
            })}
          </div>

          {/* Timeline */}
          <div className="card p-4">
            <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-4">Project Timeline</h3>
            <div className="space-y-0">
              {timeline.map((event, i) => (
                <div key={`${event}-${i}`} className="flex gap-3 relative">
                  {/* Timeline line */}
                  <div className="flex flex-col items-center">
                    <div className={`w-3 h-3 rounded-full shrink-0 ${
                      event.type === 'milestone' ? 'bg-[var(--accent)]' :
                      event.type === 'issue' ? 'bg-red-500' : 'bg-[var(--text-muted)]'
                    }`} />
                    {i < timeline.length - 1 && (
                      <div className="w-0.5 flex-1 bg-[var(--border-color)]" />
                    )}
                  </div>
                  {/* Content */}
                  <div className="pb-4 flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                      <span className="text-xs font-mono text-[var(--text-muted)]">{event.date}</span>
                      <span className="text-xs px-1.5 py-0.5 rounded bg-[var(--bg-tertiary)] text-[var(--text-muted)]">{event.phase}</span>
                    </div>
                    <p className="text-sm text-[var(--text-primary)]">{event.event}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* ── INSPECTIONS TAB (delegate to existing panel) ──────────────────────── */}
      {activeTab === 'inspections' && (
        <ProgressMonitorPanel projectId={projectId || ''} />
      )}
    </div>
  )
}

// P0-2 (2026-07-24): Wrap in <ToolGate> so direct-URL access can't
// bypass the plan check. The catalog page (/tools) shows lock badges,
// but those are display-only — this gate enforces the same check at
// the page level. Server-side enforcement for any export API this
// tool calls happens via the requirePlan() decorator on the route.
import { ToolGate } from '@/components/shared/ToolGate'

export default function ProgressMonitorPageGated() {
  return (
    <ToolGate toolPath="/tools/progress-monitor">
      <ProgressMonitorPage />
    </ToolGate>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Scale, Wrench, FileCheck, Map, Award, Download, AlertCircle, CheckCircle2 } from 'lucide-react'

export default function RegulatoryChecklistPage() {
  const [data, setData] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  // Instrument check
  const [brand, setBrand] = useState('')
  const [model, setModel] = useState('')
  const [requiredOrder, setRequiredOrder] = useState('Second Order Class II')
  const [instrumentResult, setInstrumentResult] = useState<any>(null)

  // Scale check
  const [areaHa, setAreaHa] = useState('')
  const [scaleResult, setScaleResult] = useState<any>(null)

  // Certificate
  const [surveyorName, setSurveyorName] = useState('')
  const [surveyorLicense, setSurveyorLicense] = useState('')
  const [surveyType, setSurveyType] = useState('cadastral')
  const [locality, setLocality] = useState('')
  const [certResult, setCertResult] = useState('')

  // Elective check
  const [electiveId, setElectiveId] = useState('setting_out')
  const [electiveArea, setElectiveArea] = useState('')
  const [electiveUnits, setElectiveUnits] = useState('')
  const [electiveLinear, setElectiveLinear] = useState('')
  const [electiveResult, setElectiveResult] = useState<any>(null)

  useEffect(() => { loadData() }, [])

  const loadData = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/regulations')
      if (res.ok) { const d = await res.json(); setData(d.data) }
    } catch {} finally { setLoading(false) }
  }

  const checkInstrument = async () => {
    const res = await fetch('/api/regulations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ check_type: 'instrument', brand, model, requiredOrder }),
    })
    if (res.ok) { const d = await res.json(); setInstrumentResult(d.data) }
  }

  const checkScale = async () => {
    const res = await fetch('/api/regulations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ check_type: 'scale', areaHa: parseFloat(areaHa) }),
    })
    if (res.ok) { const d = await res.json(); setScaleResult(d.data) }
  }

  const generateCert = async () => {
    const res = await fetch('/api/regulations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        check_type: 'certificate', surveyorName, surveyorLicense,
        surveyType, locality, areaHa: parseFloat(areaHa) || 0, scale: scaleResult?.label || '1:1250',
      }),
    })
    if (res.ok) { const d = await res.json(); setCertResult(d.data) }
  }

  const checkElective = async () => {
    const body: any = { check_type: 'elective', electiveId }
    if (electiveArea) body.areaHa = parseFloat(electiveArea)
    if (electiveUnits) body.unitCount = parseInt(electiveUnits)
    if (electiveLinear) body.linearLengthKm = parseFloat(electiveLinear)
    const res = await fetch('/api/regulations', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
    })
    if (res.ok) { const d = await res.json(); setElectiveResult(d.data) }
  }

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"

  if (loading) return <div className="min-h-screen flex items-center justify-center text-sm text-[var(--text-muted)]">Loading...</div>

  return (
    <div className="min-h-screen p-6 max-w-5xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Regulatory Checklist</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Survey Regulations 1994 — instrument approval, field notes, scales, areas, certificates, and elective survey types</p>

      {/* Instrument Approval (Reg 55) */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Wrench className="w-4 h-4" /> Reg 55(2): Instrument Approval</h2>
        <div className="grid grid-cols-3 gap-2 mb-2">
          <input value={brand} onChange={e => setBrand(e.target.value)} className={inputCls} placeholder="Brand (e.g. Leica)" />
          <input value={model} onChange={e => setModel(e.target.value)} className={inputCls} placeholder="Model (e.g. TS16)" />
          <select value={requiredOrder} onChange={e => setRequiredOrder(e.target.value)} className={inputCls}>
            <option>First Order Class I</option><option>First Order Class II</option>
            <option>Second Order Class I</option><option>Second Order Class II</option>
            <option>Third Order</option><option>Fourth Order</option>
          </select>
        </div>
        <button onClick={checkInstrument} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Check Approval</button>
        {instrumentResult && (
          <div className={`mt-2 p-2 rounded text-xs ${instrumentResult.approved ? 'text-green-400 bg-green-500/10' : 'text-red-400 bg-red-500/10'}`}>
            {instrumentResult.approved ? '✓' : '✗'} {instrumentResult.message}
          </div>
        )}
        {data?.instruments && (
          <div className="mt-3 text-[10px] text-[var(--text-muted)]">
            <div className="font-semibold mb-1">Approved Instruments ({data.instruments.length}):</div>
            <div className="grid grid-cols-3 gap-1 max-h-32 overflow-y-auto">
              {data.instruments.map((inst: any, i: number) => (
                <div key={i} className="px-2 py-0.5 rounded bg-[var(--bg-tertiary)]">
                  {inst.brand} {inst.model} <span className="opacity-50">({inst.type})</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Standard Scales (Reg 89) */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Scale className="w-4 h-4" /> Reg 89: Standard Plotting Scale</h2>
        <div className="flex gap-2 items-end mb-2">
          <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="area-ha">Area (ha)</label><input value={areaHa} onChange={e => setAreaHa(e.target.value)} className={inputCls + ' w-32'} placeholder="0.5" /></div>
          <button onClick={checkScale} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Select Scale</button>
        </div>
        {scaleResult && (
          <div className="mt-2 p-2 rounded text-xs text-green-400 bg-green-500/10">
            ✓ Recommended scale: <span className="font-bold">{scaleResult.label}</span> — {scaleResult.useCase}
          </div>
        )}
        <div className="mt-2 grid grid-cols-3 gap-1 text-[10px] text-[var(--text-muted)]">
          {data?.standardScales?.map((s: any) => (
            <div key={s.scale} className="px-2 py-0.5 rounded bg-[var(--bg-tertiary)]">{s.label} — ≤{s.maxAreaHa}ha</div>
          ))}
        </div>
      </div>

      {/* Surveyor Certificate (Reg 97) */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><FileCheck className="w-4 h-4" /> Reg 97: Surveyor Certificate</h2>
        <div className="grid grid-cols-2 gap-2 mb-2">
          <input value={surveyorName} onChange={e => setSurveyorName(e.target.value)} className={inputCls} placeholder="Surveyor Name" />
          <input value={surveyorLicense} onChange={e => setSurveyorLicense(e.target.value)} className={inputCls} placeholder="ISK License No." />
          <input value={locality} onChange={e => setLocality(e.target.value)} className={inputCls} placeholder="Locality" />
          <select value={surveyType} onChange={e => setSurveyType(e.target.value)} className={inputCls}>
            <option value="cadastral">Cadastral</option><option value="topographic">Topographic</option>
            <option value="engineering">Engineering</option><option value="control">Control</option>
            <option value="sectional">Sectional Property</option><option value="perimeter">Perimeter/Farm</option>
          </select>
        </div>
        <button onClick={generateCert} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Generate Certificate</button>
        {certResult && (
          <div className="mt-2">
            <pre className="text-[9px] text-[var(--text-secondary)] whitespace-pre-wrap font-mono bg-[var(--bg-tertiary)] p-3 rounded-lg max-h-60 overflow-y-auto">{certResult}</pre>
            <button onClick={() => { const blob = new Blob([certResult], { type: 'text/plain' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'survey_certificate.txt'; a.click(); URL.revokeObjectURL(url) }} className="mt-2 flex items-center gap-1.5 px-3 py-1.5 bg-[var(--accent)]/15 border border-[var(--accent)]/30 text-[var(--accent)] text-[10px] font-semibold rounded-lg">
              <Download className="w-3 h-3" /> Download Certificate
            </button>
          </div>
        )}
      </div>

      {/* Elective Survey Types (License Application) */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Award className="w-4 h-4" /> License Elective Survey Types</h2>
        <div className="grid grid-cols-2 gap-2 mb-2">
          <select value={electiveId} onChange={e => setElectiveId(e.target.value)} className={inputCls}>
            {data?.electives?.map((e: any) => <option key={e.id} value={e.id}>{e.name}</option>)}
          </select>
          <div className="grid grid-cols-3 gap-1">
            <input value={electiveArea} onChange={e => setElectiveArea(e.target.value)} className={inputCls} placeholder="Area (ha)" />
            <input value={electiveUnits} onChange={e => setElectiveUnits(e.target.value)} className={inputCls} placeholder="Units" />
            <input value={electiveLinear} onChange={e => setElectiveLinear(e.target.value)} className={inputCls} placeholder="Linear (km)" />
          </div>
        </div>
        <button onClick={checkElective} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Check Requirement</button>
        {electiveResult && (
          <div className="mt-2 space-y-2">
            <div className={`p-2 rounded text-xs ${electiveResult.check.met ? 'text-green-400 bg-green-500/10' : 'text-red-400 bg-red-500/10'}`}>
              {electiveResult.check.met ? '✓' : '✗'} {electiveResult.check.details}
            </div>
            {electiveResult.elective && (
              <div className="text-[10px] text-[var(--text-muted)]">
                <div className="font-semibold">{electiveResult.elective.description}</div>
                <div className="mt-1"><span className="opacity-60">Required:</span> {electiveResult.elective.minimumRequirement}</div>
                <div className="mt-1"><span className="opacity-60">Deliverables:</span></div>
                {electiveResult.elective.deliverables.map((d: string, i: number) => <div key={i} className="ml-3">• {d}</div>)}
                <div className="mt-1"><span className="opacity-60">Regulations:</span></div>
                {electiveResult.elective.regulations.map((r: string, i: number) => <div key={i} className="ml-3">• {r}</div>)}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { useState } from 'react'
import HorizontalCurveCalculator from '@/components/road-design/HorizontalCurveCalculator'
import { PageHeader } from '@/components/shared/PageHeader'
import VerticalCurveCalculator from '@/components/road-design/VerticalCurveCalculator'
import SuperelevationCalculator from '@/components/road-design/SuperelevationCalculator'
import SightDistanceChecker from '@/components/road-design/SightDistanceChecker'
import { useLanguage } from '@/lib/i18n/LanguageContext'

type Tab = 'horizontal' | 'vertical' | 'superelevation' | 'sight'

const TABS: Array<{ id: Tab; label: string; desc: string }> = [
  { id: 'horizontal', label: 'Horizontal Curve', desc: 'T, L, C, M, E, D — TC/CC/CT chainages — set-out table' },
  { id: 'vertical', label: 'Vertical Curve', desc: 'BVC/EVC chainages+RLs, RL at any point, peak/sag point' },
  { id: 'superelevation', label: 'Superelevation', desc: 'Required e, design e (capped 8%), transition length Ls' },
  { id: 'sight', label: 'Sight Distance', desc: 'SSD, PSD, minimum radius compliance (RDM 1.3 Tables 3-3 to 3-6)' },
]

export default function RoadDesignPage() {
  const { t } = useLanguage()
  const [tab, setTab] = useState<Tab>('horizontal')

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.roadDesign')}
        subtitle={t('tools.roadDesignDesc')}
      />

      <div className="flex gap-1 border-b border-[var(--border-color)] mb-6 overflow-x-auto">
        {TABS.map((t: any) => (
          <button key={t.id} onClick={() => setTab(t.id)}
            className={`px-4 py-2.5 text-sm font-medium whitespace-nowrap rounded-t border-b-2 transition-all ${tab === t.id ? 'border-[var(--accent)] text-[var(--accent)]' : 'border-transparent text-[var(--text-muted)] hover:text-[var(--text-primary)]'}`}>
            {t.label}
          </button>
        ))}
      </div>

      <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6">
        {tab === 'horizontal' && (
          <>
            <h2 className="text-lg font-semibold mb-1">Horizontal Curve Elements &amp; Set-Out</h2>
            <p className="text-xs text-[var(--text-muted)] mb-4">Source: RDM 1.3 §5.2 | Ghilani &amp; Wolf Ch.24 | Basak Ch.14-16 | Schofield &amp; Breach Ch.11</p>
            <HorizontalCurveCalculator />
          </>
        )}
        {tab === 'vertical' && (
          <>
            <h2 className="text-lg font-semibold mb-1">Vertical Curve Design</h2>
            <p className="text-xs text-[var(--text-muted)] mb-4">Source: RDM 1.3 §5.4 | Ghilani &amp; Wolf Ch.25</p>
            <VerticalCurveCalculator />
          </>
        )}
        {tab === 'superelevation' && (
          <>
            <h2 className="text-lg font-semibold mb-1">Superelevation Design</h2>
            <p className="text-xs text-[var(--text-muted)] mb-4">Source: RDM 1.3 §5.3 | RDM 1.3 Table 3-4 (friction factors)</p>
            <SuperelevationCalculator />
          </>
        )}
        {tab === 'sight' && (
          <>
            <h2 className="text-lg font-semibold mb-1">Sight Distance &amp; Radius Compliance</h2>
            <p className="text-xs text-[var(--text-muted)] mb-4">Source: RDM 1.3 §3.3 | Tables 3-3 to 3-6</p>
            <SightDistanceChecker />
          </>
        )}
      </div>
    </div>
  )
}

'use client';

/**
 * NTRIP / RTK Corrections Client
 *
 * AUDIT FIX (2026-07-03): Real-time GNSS correction client for receiving
 * RTK corrections from CORS networks (KENCORS, TANZACORS, etc.) via NTRIP.
 */

import { useState, useEffect, useRef, useCallback } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { Satellite, Wifi, WifiOff, Activity, Zap } from 'lucide-react'
import { CORS_NETWORKS, RTCM_TYPE_NAMES, type RTCMMessage } from '@/lib/gnss/ntripClient'

export default function NTRIPClientPage() {
  const [network, setNetwork] = useState(CORS_NETWORKS[0].id)
  const [host, setHost] = useState(CORS_NETWORKS[0].host)
  const [port, setPort] = useState(CORS_NETWORKS[0].port)
  const [mountpoint, setMountpoint] = useState('')
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [connected, setConnected] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [messages, setMessages] = useState<RTCMMessage[]>([])
  const [messageCount, setMessageCount] = useState(0)
  const [lastMessageAt, setLastMessageAt] = useState<string | null>(null)
  const [statusMsg, setStatusMsg] = useState('')

  const eventSourceRef = useRef<EventSource | null>(null)

  useEffect(() => {
    const net = CORS_NETWORKS.find(n => n.id === network)
    if (net) { setHost(net.host); setPort(net.port) }
  }, [network])

  const connect = useCallback(() => {
    if (!host || !mountpoint) { setError('Host and mountpoint are required'); return }
    setError(null); setStatusMsg('Connecting...'); setMessages([]); setMessageCount(0)
    const params = new URLSearchParams({ host, port: String(port), mountpoint })
    if (username) params.set('user', username)
    if (password) params.set('pass', password)
    const es = new EventSource(`/api/gnss/ntrip?${params}`)
    eventSourceRef.current = es
    es.addEventListener('status', (e) => {
      const data = JSON.parse((e as MessageEvent).data)
      setStatusMsg(data.message || data.error || '')
      if (data.connected) { setConnected(true); setError(null) }
      else { setConnected(false); if (data.error) setError(data.error) }
    })
    es.addEventListener('rtcm', (e) => {
      const data = JSON.parse((e as MessageEvent).data)
      setMessageCount(data.messageCount); setLastMessageAt(data.lastMessageAt)
      setMessages(prev => [...prev, { type: data.type, length: data.length, receivedAt: data.receivedAt }].slice(-50))
    })
    es.onerror = () => { setConnected(false); setError('Connection lost'); es.close() }
  }, [host, port, mountpoint, username, password])

  const disconnect = useCallback(() => {
    if (eventSourceRef.current) { eventSourceRef.current.close(); eventSourceRef.current = null }
    setConnected(false); setStatusMsg('Disconnected')
  }, [])

  useEffect(() => { return () => { if (eventSourceRef.current) eventSourceRef.current.close() } }, [])

  const correctionAge = lastMessageAt ? Math.round((Date.now() - new Date(lastMessageAt).getTime()) / 1000) : null
  const messageTypeCounts = messages.reduce((acc, m) => { acc[m.type] = (acc[m.type] || 0) + 1; return acc }, {} as Record<number, number>)
  const selectedNetwork = CORS_NETWORKS.find(n => n.id === network)

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <PageHeader title="RTK Corrections (NTRIP)" subtitle="Real-time GNSS correction stream from CORS networks" reference="NTRIP v2 (RTCM 10410.1) | RTCM 3.3 | KENCORS" />
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
            <h2 className="text-sm font-semibold text-white mb-4">Connection Settings</h2>
            <div className="space-y-3">
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="cors-network">CORS Network</label>
                <select id="cors-network" value={network} onChange={e => setNetwork(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white">
                  {CORS_NETWORKS.map(n => <option key={n.id} value={n.id}>{n.name}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div className="col-span-2">
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="caster-host">Caster Host</label>
                  <input id="caster-host" type="text" value={host} onChange={e => setHost(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
                </div>
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="port">Port</label>
                  <input id="port" type="number" value={port} onChange={e => setPort(parseInt(e.target.value) || 2101)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
                </div>
              </div>
              <div>
                <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="mountpoint">Mountpoint</label>
                <input id="mountpoint" type="text" value={mountpoint} onChange={e => setMountpoint(e.target.value)} placeholder="NBI0" className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white font-mono" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="username-optional">Username (optional)</label>
                  <input id="username-optional" type="text" value={username} onChange={e => setUsername(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white" />
                </div>
                <div>
                  <label className="block text-sm text-[var(--text-secondary)] mb-1" htmlFor="password">Password</label>
                  <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-white" />
                </div>
              </div>
              <div className="flex gap-2 pt-2">
                {!connected ? (
                  <button onClick={connect} disabled={!host || !mountpoint} className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-semibold disabled:opacity-40 hover:bg-green-700">
                    <Wifi className="w-4 h-4" /> Connect
                  </button>
                ) : (
                  <button onClick={disconnect} className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-semibold hover:bg-red-700">
                    <WifiOff className="w-4 h-4" /> Disconnect
                  </button>
                )}
              </div>
            </div>
          </div>
          {selectedNetwork?.description && (
            <div className="bg-blue-500/5 border border-blue-500/15 rounded-xl p-4">
              <h3 className="text-sm font-semibold text-blue-400 mb-1">{selectedNetwork.name}</h3>
              <p className="text-xs text-[var(--text-muted)] leading-relaxed">{selectedNetwork.description}</p>
            </div>
          )}
        </div>
        <div className="space-y-4">
          <div className={`rounded-xl p-6 border ${connected ? 'bg-green-500/5 border-green-500/20' : 'bg-[var(--bg-card)] border-[var(--border-color)]'}`}>
            <div className="flex items-center gap-3 mb-4">
              {connected ? <Satellite className="w-6 h-6 text-green-400 animate-pulse" /> : <Satellite className="w-6 h-6 text-[var(--text-muted)]" />}
              <div>
                <div className="text-sm font-semibold text-white">{connected ? 'Connected' : 'Disconnected'}</div>
                <div className="text-xs text-[var(--text-muted)]">{statusMsg}</div>
              </div>
            </div>
            {error && <div className="p-3 rounded-lg bg-red-900/20 border border-red-700/40 text-red-400 text-xs mb-3">{error}</div>}
            <div className="grid grid-cols-3 gap-3">
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className="text-2xl font-bold text-white">{messageCount}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Messages</div>
              </div>
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className={`text-2xl font-bold ${correctionAge !== null && correctionAge > 10 ? 'text-red-400' : 'text-white'}`}>{correctionAge !== null ? `${correctionAge}s` : '—'}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Corr. Age</div>
              </div>
              <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg text-center">
                <div className="text-2xl font-bold text-white">{Object.keys(messageTypeCounts).length}</div>
                <div className="text-[10px] text-[var(--text-muted)] uppercase">Msg Types</div>
              </div>
            </div>
          </div>
          {messages.length > 0 && (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-4">
              <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2"><Activity className="w-4 h-4 text-[var(--accent)]" />RTCM Message Types</h3>
              <div className="space-y-1 max-h-[200px] overflow-y-auto">
                {Object.entries(messageTypeCounts).sort((a, b) => b[1] - a[1]).map(([type, count]) => (
                  <div key={type} className="flex items-center justify-between text-xs">
                    <span className="font-mono text-[var(--text-muted)]">Type {type}</span>
                    <span className="text-white">{RTCM_TYPE_NAMES[parseInt(type)] || 'Unknown'}</span>
                    <span className="font-mono text-[var(--accent)]">{count}×</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'
import { useState } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { createSectionalPlan, type SectionalFloor, type SectionalUnit } from '@/lib/cadastral/sectionalAndEncumbrance'

export default function SectionalPropertiesPage() {
  const [buildingName, setBuildingName] = useState('Riverside Apartments')
  const [lrNumber, setLrNumber] = useState('NAIROBI/BLOCK 72/1234')
  const [units, setUnits] = useState<Array<{ unitNumber: string; floor: number; type: SectionalUnit['type']; area: number; description: string }>>([
    { unitNumber: 'A1', floor: 0, type: 'residential', area: 85, description: '2-bedroom' },
    { unitNumber: 'A2', floor: 0, type: 'residential', area: 85, description: '2-bedroom' },
    { unitNumber: 'B1', floor: 1, type: 'residential', area: 90, description: '3-bedroom' },
    { unitNumber: 'P1', floor: -1, type: 'parking', area: 12, description: 'Parking bay' },
  ])
  const [plan, setPlan] = useState<ReturnType<typeof createSectionalPlan> | null>(null)

  const addUnit = () => setUnits([...units, { unitNumber: `U${units.length + 1}`, floor: 0, type: 'residential', area: 50, description: '' }])
  const removeUnit = (i: number) => setUnits(units.filter((_, idx) => idx !== i))

  const generate = () => {
    const floors: SectionalFloor[] = []
    const floorMap = new Map<number, typeof units>()
    for (const u of units) {
      if (!floorMap.has(u.floor)) floorMap.set(u.floor, [])
      floorMap.get(u.floor)!.push(u)
    }
    for (const [floor, floorUnits] of floorMap) {
      const sectionUnits: SectionalUnit[] = floorUnits.map((u, i) => ({
        id: `unit-${i}`, unitNumber: u.unitNumber, floor, type: u.type, area: u.area, description: u.description,
      }))
      const totalArea = sectionUnits.reduce((s, u) => s + u.area, 0) + 20 // +20 for common
      floors.push({ floor, name: floor === 0 ? 'Ground Floor' : floor > 0 ? `Floor ${floor}` : `Basement ${-floor}`, totalArea, units: sectionUnits })
    }
    floors.sort((a, b) => a.floor - b.floor)
    setPlan(createSectionalPlan(buildingName, lrNumber, floors))
  }

  return (
    <div className="max-w-5xl mx-auto px-4 py-8">
      <PageHeader title="Sectional Properties" subtitle="Apartment units, parking, common areas per Act 2020" reference="Sectional Properties Act 2020 (Kenya)" />
      <div className="grid lg:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="building-name">Building Name</label><input id="building-name" value={buildingName} onChange={e => setBuildingName(e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="lr-number">LR Number</label><input id="lr-number" value={lrNumber} onChange={e => setLrNumber(e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
          </div>
          <div>
            <div className="flex justify-between items-center mb-2"><div className="text-sm text-zinc-400">Units</div><button onClick={addUnit} className="text-xs px-2 py-1 bg-[var(--accent)] text-black rounded">+ Add Unit</button></div>
            <div className="space-y-2 max-h-64 overflow-y-auto">{units.map((u, i) => (
              <div key={i} className="flex gap-2 items-center">
                <input value={u.unitNumber} onChange={e => { const v = [...units]; v[i].unitNumber = e.target.value; setUnits(v) }} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-xs" />
                <input type="number" value={u.floor} onChange={e => { const v = [...units]; v[i].floor = +e.target.value; setUnits(v) }} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-xs" />
                <select value={u.type} onChange={e => { const v = [...units]; v[i].type = e.target.value as SectionalUnit['type']; setUnits(v) }} className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-xs"><option value="residential">Residential</option><option value="commercial">Commercial</option><option value="parking">Parking</option><option value="common">Common</option></select>
                <input type="number" value={u.area} onChange={e => { const v = [...units]; v[i].area = +e.target.value; setUnits(v) }} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-2 py-1.5 text-white text-xs" />
                <button onClick={() => removeUnit(i)} className="text-red-400 text-xs px-1">×</button>
              </div>
            ))}</div>
          </div>
          <button onClick={generate} className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent)]/90 text-black font-semibold rounded-lg">Generate Sectional Plan</button>
        </div>
        <div>
          {plan ? (
            <div className="space-y-4">
              <div className="grid grid-cols-3 gap-3">
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">Total Area</div><div className="text-lg font-bold text-white">{plan.totalArea.toFixed(0)} m²</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">Unit Area</div><div className="text-lg font-bold text-amber-400">{plan.totalUnitArea.toFixed(0)} m²</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">Common Area</div><div className="text-lg font-bold text-blue-400">{plan.totalCommonArea.toFixed(0)} m²</div></div>
              </div>
              <div className="overflow-x-auto"><h3 className="text-sm font-semibold text-white mb-2">Participation Quotas</h3><table className="w-full text-sm"><thead><tr className="text-zinc-500 border-b border-zinc-700"><th className="text-left py-2">Unit</th><th className="text-right py-2">Quota (%)</th></tr></thead><tbody>{plan.participationQuotas.map((q, i) => (<tr key={i} className="border-b border-zinc-800"><td className="py-1.5 font-mono text-amber-400">{q.unitNumber}</td><td className="py-1.5 text-right font-mono text-white">{q.quota.toFixed(4)}%</td></tr>))}</tbody></table></div>
            </div>
          ) : <div className="p-6 bg-zinc-900 rounded-lg border border-zinc-700 text-center text-sm text-zinc-500">Add units and click Generate.</div>}
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { Upload, Download, FileSpreadsheet, AlertCircle, CheckCircle2 } from 'lucide-react'
import { getAvailableFormats, exportStakeout, type InstrumentFormat } from '@/lib/survey/instrumentWriters'
import { computeSettingOut, type SettingOutResult, type InstrumentStation, type Backsight } from '@/lib/computations/settingOutEngine'
import { extractDesignPointsFromDXF } from '@/lib/survey/dxfDesignExtractor'
import { compareAsBuiltToDesign, type ComparisonReport } from '@/lib/survey/asBuiltComparison'

export default function SettingOutPage() {
  const [dxfContent, setDxfContent] = useState('')
  const [stationE, setStationE] = useState('')
  const [stationN, setStationN] = useState('')
  const [stationRL, setStationRL] = useState('0')
  const [backsightE, setBacksightE] = useState('')
  const [backsightN, setBacksightN] = useState('')
  const [result, setResult] = useState<SettingOutResult | null>(null)
  const [warnings, setWarnings] = useState<string[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [exportFormat, setExportFormat] = useState<InstrumentFormat>('CSV')
  const [comparison, setComparison] = useState<ComparisonReport | null>(null)
  const [asBuiltInput, setAsBuiltInput] = useState('')

  const handleFileUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => setDxfContent(reader.result as string)
    reader.readAsText(file)
  }, [])

  const handleImport = async () => {
    if (!dxfContent || !stationE || !stationN || !backsightE || !backsightN) {
      setError('DXF file and station/backsight coordinates are required')
      return
    }
    setLoading(true); setError(''); setResult(null); setWarnings([])
    try {
      // Run the parsing completely on the client (offline-first)
      const extraction = extractDesignPointsFromDXF(dxfContent, { layerFilter: [] })
      if (extraction.points.length === 0) {
        throw new Error('No design points found in DXF')
      }

      const station: InstrumentStation = {
        e: parseFloat(stationE),
        n: parseFloat(stationN),
        rl: parseFloat(stationRL || '0'),
        ih: 1.5,
      }
      const backsight: Backsight = {
        e: parseFloat(backsightE),
        n: parseFloat(backsightN),
      }

      const computedResult = computeSettingOut(station, backsight, extraction.points)
      setResult(computedResult)
      setWarnings(extraction.warnings || [])
    } catch (e) { 
      setError(e instanceof Error ? e.message : 'Failed to process DXF locally') 
    }
    finally { setLoading(false) }
  }

  const handleExport = async () => {
    if (!result) return
    try {
      // Generate export locally
      const exportData = exportStakeout(result, exportFormat, { stationName: 'STN1' })
      const blob = new Blob([exportData.content], { type: exportData.mimeType })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url; a.download = exportData.filename; a.click()
      URL.revokeObjectURL(url)
    } catch (e) { 
      setError(e instanceof Error ? e.message : 'Export failed locally') 
    }
  }

  const handleCompare = () => {
    if (!result) return
    try {
      const asBuiltPoints = asBuiltInput.trim().split('\n').map(line => {
        const cols = line.split(',').map(c => c.trim())
        return { id: cols[0], e: parseFloat(cols[1]), n: parseFloat(cols[2]), rl: parseFloat(cols[3] || '0') }
      }).filter(p => p.id && !isNaN(p.e) && !isNaN(p.n))

      const designPoints = result.rows.map(r => ({
        id: r.id, e: r.designE, n: r.designN, rl: r.designRL, th: r.TH,
      }))

      const report = compareAsBuiltToDesign({ designPoints, asBuiltPoints })
      setComparison(report)
    } catch { setError('Failed to parse as-built CSV. Use: id,easting,northing,rl') }
  }

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"

  return (
    <div className="min-h-screen p-6 max-w-6xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Setting Out</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Import design from DXF → compute stakeout list → export to instrument → compare as-built</p>

      {/* Step 1: Import DXF */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">1. Import Design from DXF</h2>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="dxf-file">DXF File</label>
            <input id="dxf-file" type="file" accept=".dxf" onChange={handleFileUpload}
              className="w-full text-xs text-[var(--text-secondary)]" />
            {dxfContent && <CheckCircle2 className="w-4 h-4 text-green-500 inline ml-2" />}
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="station-e">Station E</label><input id="station-e" value={stationE} onChange={e => setStationE(e.target.value)} className={inputCls} placeholder="264000" /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="station-n">Station N</label><input id="station-n" value={stationN} onChange={e => setStationN(e.target.value)} className={inputCls} placeholder="9861000" /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="station-rl">Station RL</label><input id="station-rl" value={stationRL} onChange={e => setStationRL(e.target.value)} className={inputCls} /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="ih">IH</label><input id="ih" defaultValue="1.5" className={inputCls} /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="backsight-e">Backsight E</label><input id="backsight-e" value={backsightE} onChange={e => setBacksightE(e.target.value)} className={inputCls} /></div>
            <div><label className="text-[10px] text-[var(--text-muted)] block mb-1" htmlFor="backsight-n">Backsight N</label><input value={backsightN} onChange={e => setBacksightN(e.target.value)} className={inputCls} /></div>
          </div>
        </div>
        <button onClick={handleImport} disabled={loading} className="mt-3 px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-50">
          {loading ? 'Computing...' : 'Compute Stakeout List'}
        </button>
      </div>

      {warnings.length > 0 && (
        <div className="bg-yellow-500/10 border border-yellow-500/20 rounded-lg p-3 mb-4 text-xs text-yellow-400">
          {warnings.map((w, i) => <div key={i}>⚠ {w}</div>)}
        </div>
      )}
      {error && <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-4 text-xs text-red-400 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}

      {/* Step 2: Stakeout List */}
      {result && (
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
          <div className="flex justify-between items-center mb-3">
            <h2 className="text-sm font-semibold text-[var(--text-primary)]">2. Stakeout List ({result.totalPoints} points)</h2>
            <div className="flex gap-2 items-center">
              <select value={exportFormat} onChange={e => setExportFormat(e.target.value as InstrumentFormat)} className={inputCls + ' w-auto'}>
                {getAvailableFormats().map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
              </select>
              <button onClick={handleExport} className="flex items-center gap-1.5 px-3 py-1.5 bg-[var(--accent)]/15 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-semibold rounded-lg hover:bg-[var(--accent)]/25">
                <Download className="w-3.5 h-3.5" /> Export
              </button>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead><tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                <th className="text-left py-2 px-1">ID</th><th className="text-right">Hz Angle</th><th className="text-right">HD (m)</th><th className="text-right">SD (m)</th><th className="text-right">Design E</th><th className="text-right">Design N</th><th className="text-right">RL</th>
              </tr></thead>
              <tbody>
                {result.rows.map((row) => (
                  <tr key={row.id} className="border-b border-[var(--border-color)]/30 text-[var(--text-secondary)]">
                    <td className="py-1.5 px-1 font-mono">{row.id}</td>
                    <td className="text-right font-mono">{row.HzAngle}</td>
                    <td className="text-right font-mono">{row.HD.toFixed(3)}</td>
                    <td className="text-right font-mono">{row.SD.toFixed(3)}</td>
                    <td className="text-right font-mono">{row.designE.toFixed(3)}</td>
                    <td className="text-right font-mono">{row.designN.toFixed(3)}</td>
                    <td className="text-right font-mono">{row.designRL.toFixed(3)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="mt-2 text-[10px] text-[var(--text-muted)]">BS bearing: {result.bsBearing} | {result.rows.length} points</div>
        </div>
      )}

      {/* Step 3: As-Built Comparison */}
      {result && (
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
          <h2 className="text-sm font-semibold text-[var(--text-primary)] mb-3">3. As-Built Comparison</h2>
          <p className="text-[10px] text-[var(--text-muted)] mb-2">Paste as-built shots (one per line: id,easting,northing,rl)</p>
          <textarea value={asBuiltInput} onChange={e => setAsBuiltInput(e.target.value)} placeholder="P1,264100.010,9861100.005,1500.002" className={inputCls + ' h-20 font-mono mb-2'} />
          <button onClick={handleCompare} className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)]">Compare As-Built vs Design</button>

          {comparison && (
            <div className="mt-4">
              <div className={`p-3 rounded-lg mb-3 text-sm font-semibold ${comparison.verdict === 'PASS' ? 'bg-green-500/10 text-green-400 border border-green-500/20' : comparison.verdict === 'FAIL' ? 'bg-red-500/10 text-red-400 border border-red-500/20' : 'bg-yellow-500/10 text-yellow-400 border border-yellow-500/20'}`}>
                {comparison.summary}
              </div>
              <table className="w-full text-xs">
                <thead><tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                  <th className="text-left py-1">ID</th><th className="text-right">dE (mm)</th><th className="text-right">dN (mm)</th><th className="text-right">dH (mm)</th><th className="text-right">|H| (mm)</th><th className="text-center">Status</th>
                </tr></thead>
                <tbody>
                  {comparison.rows.map((row) => (
                    <tr key={row.designId} className={`border-b border-[var(--border-color)]/30 ${row.passed ? 'text-[var(--text-secondary)]' : 'text-red-400'}`}>
                      <td className="py-1 font-mono">{row.designId}</td>
                      <td className="text-right font-mono">{(row.deltaE * 1000).toFixed(1)}</td>
                      <td className="text-right font-mono">{(row.deltaN * 1000).toFixed(1)}</td>
                      <td className="text-right font-mono">{row.deltaRL !== null ? (row.deltaRL * 1000).toFixed(1) : '—'}</td>
                      <td className="text-right font-mono">{(row.horizontalOffset * 1000).toFixed(1)}</td>
                      <td className="text-center">{row.passed ? '✓' : '✗'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'
import { useState } from 'react'
import { PageHeader } from '@/components/shared/PageHeader'
import { ToolExportButtons } from '@/components/shared/ToolExportButtons'
import { computeCurveElements, generateChainageTable, generateStakingTable, type HorizontalCurveData } from '@/lib/engineering/stakingTable'

export default function StakingTablePage() {
  const [ipE, setIpE] = useState(500000)
  const [ipN, setIpN] = useState(9800000)
  const [deflection, setDeflection] = useState(30)
  const [radius, setRadius] = useState(200)
  const [ipChainage, setIpChainage] = useState(1000)
  const [incomingBearing, setIncomingBearing] = useState(45)
  const [interval, setInterval] = useState(20)
  const [offsets, setOffsets] = useState('-3.5,0,3.5')
  const [computed, setComputed] = useState<{ elements: any; chainageTable: any[]; stakingTable: any[] } | null>(null)

  const compute = () => {
    const data: HorizontalCurveData = { ipE, ipN, deflectionAngle: deflection, radius, ipChainage, incomingBearing }
    const elements = computeCurveElements(data)
    const chainageTable = generateChainageTable(data, elements, ipChainage + elements.tangent + 100)
    const offsetArr = offsets.split(',').map(s => parseFloat(s.trim())).filter(n => !isNaN(n))
    const stakingTable = generateStakingTable(data, elements, interval, undefined, undefined, offsetArr)
    setComputed({ elements, chainageTable, stakingTable })
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader title="Staking Table" subtitle="Batch staking + chainage schedule for setting out" reference="Route Surveying Ch.6 | RDM 1.3" />
      <div className="grid lg:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-easting">IP Easting</label><input id="ip-easting" type="number" value={ipE} onChange={e => setIpE(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-northing">IP Northing</label><input id="ip-northing" type="number" value={ipN} onChange={e => setIpN(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="deflection-angle">Deflection Angle (°)</label><input id="deflection-angle" type="number" step="0.1" value={deflection} onChange={e => setDeflection(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="radius-m">Radius (m)</label><input id="radius-m" type="number" value={radius} onChange={e => setRadius(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="ip-chainage-m">IP Chainage (m)</label><input id="ip-chainage-m" type="number" value={ipChainage} onChange={e => setIpChainage(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="incoming-bearing">Incoming Bearing (°)</label><input id="incoming-bearing" type="number" step="0.1" value={incomingBearing} onChange={e => setIncomingBearing(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="stake-interval-m">Stake Interval (m)</label><input id="stake-interval-m" type="number" value={interval} onChange={e => setInterval(+e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
            <div><label className="block text-sm text-zinc-400 mb-2" htmlFor="offsets-comma-sep-m">Offsets (comma-sep, m)</label><input type="text" value={offsets} onChange={e => setOffsets(e.target.value)} className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-4 py-3 text-white" /></div>
          </div>
          <button onClick={compute} className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent)]/90 text-black font-semibold rounded-lg">Generate Staking Table</button>
        </div>
        <div>
          {computed ? (
            <div className="space-y-6">
              <div className="grid grid-cols-4 gap-3">
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">T (m)</div><div className="text-lg font-bold text-amber-400">{computed.elements.tangent.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">L (m)</div><div className="text-lg font-bold text-blue-400">{computed.elements.curveLength.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">E (m)</div><div className="text-lg font-bold text-green-400">{computed.elements.external.toFixed(3)}</div></div>
                <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700 text-center"><div className="text-xs text-zinc-400">M (m)</div><div className="text-lg font-bold text-violet-400">{computed.elements.midOrdinate.toFixed(3)}</div></div>
              </div>
              <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="text-zinc-500 border-b border-zinc-700"><th className="text-left py-2">Point</th><th className="text-left py-2">Description</th><th className="text-right py-2">Chainage</th><th className="text-right py-2">Easting</th><th className="text-right py-2">Northing</th><th className="text-right py-2">Bearing</th></tr></thead><tbody>{computed.chainageTable.map((r, i) => (<tr key={i} className="border-b border-zinc-800"><td className="py-2 font-mono text-amber-400">{r.point}</td><td className="py-2 text-zinc-300">{r.description}</td><td className="py-2 text-right font-mono text-white">{r.chainageLabel}</td><td className="py-2 text-right font-mono text-white">{r.easting.toFixed(3)}</td><td className="py-2 text-right font-mono text-white">{r.northing.toFixed(3)}</td><td className="py-2 text-right font-mono text-white">{r.bearing.toFixed(2)}°</td></tr>))}</tbody></table></div>
              <div className="overflow-x-auto"><h3 className="text-sm font-semibold text-white mb-2">Staking Table ({computed.stakingTable.length} stakes)</h3><table className="w-full text-sm"><thead><tr className="text-zinc-500 border-b border-zinc-700"><th className="text-right py-2">Chainage</th><th className="text-right py-2">Easting</th><th className="text-right py-2">Northing</th><th className="text-right py-2">Bearing</th><th className="text-right py-2">Segment</th></tr></thead><tbody>{computed.stakingTable.map((s, i) => (<tr key={i} className="border-b border-zinc-800"><td className="py-1.5 text-right font-mono text-amber-400">{s.chainageLabel}</td><td className="py-1.5 text-right font-mono text-white">{s.easting.toFixed(3)}</td><td className="py-1.5 text-right font-mono text-white">{s.northing.toFixed(3)}</td><td className="py-1.5 text-right font-mono text-white">{s.bearing.toFixed(2)}°</td><td className="py-1.5 text-right text-zinc-400">{s.segment}</td></tr>))}</tbody></table></div>
            </div>
          ) : <div className="p-6 bg-zinc-900 rounded-lg border border-zinc-700 text-center text-sm text-zinc-500">Enter curve data and click Generate.</div>}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect, useMemo, Suspense } from 'react'
import { useSearchParams } from 'next/navigation'
import { useSession } from 'next-auth/react'
import { createClient } from '@/lib/api-client/client'
import SurveyReportBuilder from '@/components/surveyreport/SurveyReportBuilder'
import MobileDesktopNotice from '@/components/MobileDesktopNotice'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface Project {
  id: string
  name: string
  location: string | null
}

function SurveyReportBuilderContent() {
  const params = useSearchParams()
  const projectId = params.get('projectId') || ''
  const reportId = params.get('reportId') || undefined
  const { data: session, status: sessionStatus } = useSession()
  const { t } = useLanguage()

  const [projects, setProjects] = useState<Project[]>([])
  const [selectedProjectId, setSelectedProjectId] = useState('')
  const [loading, setLoading] = useState(true)

  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), [])

  useEffect(() => {
    if (sessionStatus === 'loading') return
    if (!session?.user) {
      setLoading(false)
      return
    }

    async function load() {
      const { data } = await dbClient
        .from('projects')
        .select('id, name, location')
        .order('created_at', { ascending: false })
        .limit(50)

      setProjects(data || [])
      setLoading(false)
    }

    load()
  }, [session, sessionStatus, dbClient])

  if (sessionStatus === 'loading' || loading) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!session?.user) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center p-4">
        <div className="text-center max-w-sm">
          <div className="w-16 h-16 rounded-2xl bg-[var(--accent)]/10 flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-[var(--accent)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z" />
            </svg>
          </div>
          <h2 className="text-lg font-semibold text-[var(--text-primary)] mb-2">Sign in Required</h2>
          <p className="text-sm text-[var(--text-muted)] mb-6">
            You need to be signed in to create survey reports.
          </p>
          <a
            href="/login"
            className="inline-block px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm hover:bg-[var(--accent-dim)] transition-colors"
          >
            Sign In
          </a>
        </div>
      </div>
    )
  }

  if (!projectId) {
    return (
      <div className="min-h-screen bg-[var(--bg-primary)] p-8">
        <div className="max-w-2xl mx-auto">
          <div className="mb-4">
            <MobileDesktopNotice>
              Report assembly has long forms, tables, previews, and export checks. Mobile is fine for selecting a project, but desktop is recommended before generating final documents.
            </MobileDesktopNotice>
          </div>
          <PageHeader
            title={t('tools.surveyReportBuilder')}
            subtitle={t('tools.surveyReportBuilderDesc')}
          />
          
          {projects.length === 0 ? (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-8 text-center">
              <p className="text-[var(--text-muted)] mb-4">No projects found.</p>
              <a
                href="/project/new"
                className="inline-block px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm"
              >
                Create New Project
              </a>
            </div>
          ) : (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-xl p-6">
              <h2 className="text-lg font-semibold mb-4">Select Project</h2>
              <div className="space-y-2">
                {projects.map((p: any) => (
                  <button
                    key={p.id}
                    onClick={() => setSelectedProjectId(p.id)}
                    className={`w-full text-left px-4 py-3 rounded-lg border transition-colors ${
                      selectedProjectId === p.id
                        ? 'border-[var(--accent)] bg-[var(--accent)]/5'
                        : 'border-[var(--border-color)] hover:border-[var(--accent)]/50'
                    }`}
                  >
                    <div className="font-medium">{p.name}</div>
                    <div className="text-xs text-[var(--text-muted)]">{p.location || 'No location'}</div>
                  </button>
                ))}
              </div>
              <div className="flex justify-end mt-6">
                <a
                  href={`/tools/survey-report-builder?projectId=${selectedProjectId}`}
                  className={`px-6 py-2.5 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm ${
                    !selectedProjectId ? 'opacity-40 pointer-events-none' : ''
                  }`}
                >
                  Continue →
                </a>
              </div>
            </div>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="px-4 pt-4">
        <MobileDesktopNotice>
          Report assembly has long forms, tables, previews, and export checks. Use desktop before issuing final documents.
        </MobileDesktopNotice>
      </div>
      <SurveyReportBuilder projectId={projectId} existingReportId={reportId} />
    </div>
  )
}

export default function SurveyReportBuilderPage() {
  const { t } = useLanguage()
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-[var(--bg-primary)] flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin" />
      </div>
    }>
      <SurveyReportBuilderContent />
    </Suspense>
  )
}

'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { tacheometrySolved } from '@/lib/engine/solution/wrappers/tacheometry'
import { PageHeader } from '@/components/shared/PageHeader'
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function TacheometryCalculator() {
  const { t } = useLanguage()
  const [inputs, setInputs] = useState({
    hi: '',           // instrument height above ground (h.i.)
    upper: '',        // upper staff reading
    middle: '',       // middle staff reading
    lower: '',        // lower staff reading
    vertDeg: '',      // vertical angle degrees
    vertMin: '',      // vertical angle minutes
    vertSec: '',      // vertical angle seconds
    k: '100',         // multiplying constant
    c: '0'            // additive constant
  });
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    const HI = parseFloat(inputs.hi);
    const upper = parseFloat(inputs.upper);
    const middle = parseFloat(inputs.middle);
    const lower = parseFloat(inputs.lower);
    const K = parseFloat(inputs.k) || 100;
    const C = parseFloat(inputs.c) || 0;

    const deg = parseFloat(inputs.vertDeg) || 0
    const min = parseFloat(inputs.vertMin) || 0
    const sec = parseFloat(inputs.vertSec) || 0

    if (isNaN(HI) || isNaN(upper) || isNaN(middle) || isNaN(lower)) return;

    const s = tacheometrySolved({
      instrumentHeight: HI,
      upper,
      middle,
      lower,
      verticalAngle: { degrees: deg, minutes: min, seconds: sec, direction: 'N' },
      K,
      C,
    })
    setSteps(s.steps)
    setSolutionTitle(s.solution.title)
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.tacheometry')}
        subtitle={t('tools.tacheometryDesc')}
        reference="Survey Regulations 1994 | RDM 1.1 (2025) Section 5.6 | Survey Act Cap 299"
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="card">
          <div className="card-header"><span className="label">Tacheometry Data</span></div>
          <div className="card-body space-y-4">
            <div>
              {/* h.i. = height of instrument above ground (not HPC — different context) */}
              <label className="label" htmlFor="instrument-height-above-ground-h-i-m">Instrument Height above Ground, h.i. (m)</label>
              <input id="instrument-height-above-ground-h-i-m" className="input" value={inputs.hi} onChange={e => setInputs({...inputs, hi: e.target.value})} aria-label="1.500" placeholder="1.500" />
            </div>
            <div>
              <div className="label">Staff Readings (m)</div>
              <div className="grid grid-cols-3 gap-2">
                <div>
                  <label className="label text-xs" htmlFor="upper">Upper</label>
                  <input id="upper" className="input" value={inputs.upper} onChange={e => setInputs({...inputs, upper: e.target.value})} aria-label="1.850" placeholder="1.850" />
                </div>
                <div>
                  <label className="label text-xs" htmlFor="middle">Middle</label>
                  <input id="middle" className="input" value={inputs.middle} onChange={e => setInputs({...inputs, middle: e.target.value})} aria-label="1.500" placeholder="1.500" />
                </div>
                <div>
                  <label className="label text-xs" htmlFor="lower">Lower</label>
                  <input id="lower" className="input" value={inputs.lower} onChange={e => setInputs({...inputs, lower: e.target.value})} aria-label="1.150" placeholder="1.150" />
                </div>
              </div>
            </div>
            <div>
              <div className="label">Vertical Angle (D° M&apos; S&quot;)</div>
              <div className="flex gap-2">
                <input className="input flex-1" value={inputs.vertDeg} onChange={e => setInputs({...inputs, vertDeg: e.target.value})} aria-label="05°" placeholder="05°" />
                <input className="input flex-1" value={inputs.vertMin} onChange={e => setInputs({...inputs, vertMin: e.target.value})} aria-label="30'" placeholder="30'" />
                <input className="input flex-1" value={inputs.vertSec} onChange={e => setInputs({...inputs, vertSec: e.target.value})} aria-label="00&quot;" placeholder="00&quot;" />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="label" htmlFor="multiplying-constant-k">Multiplying Constant K</label>
                <input id="multiplying-constant-k" className="input" value={inputs.k} onChange={e => setInputs({...inputs, k: e.target.value})} aria-label="100" placeholder="100" />
              </div>
              <div>
                <label className="label" htmlFor="additive-constant-c">Additive Constant C</label>
                <input className="input" value={inputs.c} onChange={e => setInputs({...inputs, c: e.target.value})} aria-label="0" placeholder="0" />
              </div>
            </div>
            {calcError && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{calcError}</div>}
            <button onClick={calculate} className="btn btn-primary w-full">{t('toolUI.calculate')}</button>
            {steps && (
              <div className="flex gap-2 mt-2">
                <button
                  onClick={() => {
                    generatePDF(
                      { title: 'Tacheometric Computation Sheet', reference: 'Survey Regulations 1994 | RDM 1.1 (2025) Section 5.6' },
                      [
                        { title: 'Observations', rows: [
                          { label: 'Instrument Height (h.i.)', value: `${inputs.hi} m` },
                          { label: 'Upper Staff Reading', value: `${inputs.upper} m` },
                          { label: 'Middle Staff Reading', value: `${inputs.middle} m` },
                          { label: 'Lower Staff Reading', value: `${inputs.lower} m` },
                          { label: 'Vertical Angle', value: `${inputs.vertDeg}° ${inputs.vertMin}' ${inputs.vertSec}"` },
                          { label: 'K (multiplying constant)', value: inputs.k },
                          { label: 'C (additive constant)', value: inputs.c },
                        ]},
                        { title: 'Computation Steps', rows: steps.map((s: SolutionStep) => ({ label: s.label, value: s.result || s.computation || '—' })) },
                      ],
                    )
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportPdf')}
                </button>
                <button
                  onClick={() => {
                    const csv = toCSV(
                      ['Parameter', 'Value'],
                      [
                        ['Instrument Height (m)', inputs.hi],
                        ['Upper Staff (m)', inputs.upper],
                        ['Middle Staff (m)', inputs.middle],
                        ['Lower Staff (m)', inputs.lower],
                        ['Vertical Angle', `${inputs.vertDeg}° ${inputs.vertMin}' ${inputs.vertSec}"`],
                        ['K', inputs.k],
                        ['C', inputs.c],
                        ...steps.map((s: SolutionStep) => [s.label, s.result || s.computation || '']),
                      ],
                    )
                    downloadCSV(csv, 'tacheometry-data')
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportCsv')}
                </button>
              </div>
            )}
          </div>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client'

import { useState, useMemo, useCallback } from 'react'
import { Mountain, Download, FileSpreadsheet, AlertCircle, CheckCircle2, Layers, Search } from 'lucide-react'
import { KENYA_TOPO_CODES } from '@/lib/topo/featureCodes'

interface TopoPoint {
  pointNumber: string; easting: number; northing: number; rl: number
  code: string; description: string
}

interface BreaklineInput {
  points: Array<{ x: number; y: number; z: number }>
  type: 'hard' | 'soft' | 'ridge' | 'valley'
}

export default function TopographicSurveyPage() {
  const [points, setPoints] = useState<TopoPoint[]>([])
  const [breaklines, setBreaklines] = useState<BreaklineInput[]>([])
  const [pointInput, setPointInput] = useState('')
  const [breaklineInput, setBreaklineInput] = useState('')
  const [contourInterval, setContourInterval] = useState('1.0')
  const [contours, setContours] = useState<any>(null)
  const [sanity, setSanity] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [codeFilter, setCodeFilter] = useState('')

  // Feature code lookup
  const codeMap = useMemo(() => {
    const m = new Map<string, string>()
    for (const def of KENYA_TOPO_CODES) m.set(def.code.toUpperCase(), def.description)
    return m
  }, [])

  const filteredCodes = useMemo(() => {
    if (!codeFilter) return KENYA_TOPO_CODES.slice(0, 30)
    return KENYA_TOPO_CODES.filter(c =>
      c.code.toLowerCase().includes(codeFilter.toLowerCase()) ||
      c.description.toLowerCase().includes(codeFilter.toLowerCase())
    ).slice(0, 30)
  }, [codeFilter])

  const handleParsePoints = useCallback(() => {
    const parsed = pointInput.trim().split('\n').map(line => {
      const cols = line.split(',').map(c => c.trim())
      return {
        pointNumber: cols[0] || `PT${Date.now()}`,
        easting: parseFloat(cols[1]), northing: parseFloat(cols[2]),
        rl: parseFloat(cols[3]),
        code: cols[4] || '', description: cols[5] || codeMap.get((cols[4] || '').toUpperCase()) || '',
      }
    }).filter(p => !isNaN(p.easting) && !isNaN(p.northing) && !isNaN(p.rl))
    setPoints(parsed)
  }, [pointInput, codeMap])

  const handleParseBreaklines = useCallback(() => {
    // Format: type,x1,y1,z1,x2,y2,z2,...
    const lines = breaklineInput.trim().split('\n')
    const parsed: BreaklineInput[] = []
    for (const line of lines) {
      const cols = line.split(',').map(c => c.trim())
      const type = (cols[0] as BreaklineInput['type']) || 'hard'
      const pts: Array<{ x: number; y: number; z: number }> = []
      for (let i = 1; i < cols.length - 2; i += 3) {
        const x = parseFloat(cols[i]), y = parseFloat(cols[i + 1]), z = parseFloat(cols[i + 2])
        if (!isNaN(x) && !isNaN(y) && !isNaN(z)) pts.push({ x, y, z })
      }
      if (pts.length >= 2) parsed.push({ points: pts, type })
    }
    setBreaklines(parsed)
  }, [breaklineInput])

  const handleGenerateContours = async () => {
    if (points.length < 3) { setError('Need ≥3 points'); return }
    setLoading(true); setError(''); setContours(null); setSanity(null)
    try {
      const res = await fetch('/api/topo/generate-contours', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          points: points.map(p => ({ x: p.easting, y: p.northing, z: p.rl })),
          breaklines,
          interval: parseFloat(contourInterval),
        }),
      })
      if (!res.ok) { const e = await res.json(); throw new Error(e.error || 'Failed') }
      const data = await res.json()
      setContours(data.data.contours)
      setSanity(data.data.sanity)
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed') }
    finally { setLoading(false) }
  }

  const handleExportDXF = async () => {
    if (points.length === 0) return
    try {
      const res = await fetch('/api/topo/export-dxf', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          points: points.map(p => ({
            easting: p.easting, northing: p.northing, elevation: p.rl,
            code: p.code, pointNumber: p.pointNumber,
          })),
          projectName: 'Topographic Survey',
        }),
      })
      if (!res.ok) throw new Error('Export failed')
      const data = await res.json()
      const blob = new Blob([data.content], { type: data.mimeType })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url; a.download = data.filename; a.click()
      URL.revokeObjectURL(url)
    } catch (e) { setError(e instanceof Error ? e.message : 'Export failed') }
  }

  const handleExportSpotHeights = async () => {
    if (points.length === 0) return
    try {
      const res = await fetch('/api/topo/spot-height-schedule', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          points: points.map(p => ({
            pointNumber: p.pointNumber, easting: p.easting, northing: p.northing,
            rl: p.rl, code: p.code, description: p.description,
          })),
          projectName: 'Topographic Survey',
          surveyorName: 'METARDU User',
        }),
      })
      if (!res.ok) throw new Error('Export failed')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url; a.download = 'spot_height_schedule.xlsx'; a.click()
      URL.revokeObjectURL(url)
    } catch (e) { setError(e instanceof Error ? e.message : 'Export failed') }
  }

  const inputCls = "w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"

  return (
    <div className="min-h-screen p-6 max-w-6xl mx-auto">
      <h1 className="text-2xl font-bold text-[var(--text-primary)] mb-2">Topographic Survey</h1>
      <p className="text-sm text-[var(--text-muted)] mb-6">Feature-coded points → breakline-aware TIN → contour generation → DXF + Spot Height Schedule export</p>

      <div className="grid grid-cols-2 gap-4 mb-4">
        {/* Point Input */}
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-2">1. Survey Points</h2>
          <p className="text-[10px] text-[var(--text-muted)] mb-1">Format: point_no, easting, northing, RL, code, description</p>
          <textarea value={pointInput} onChange={e => setPointInput(e.target.value)}
            className={inputCls + ' h-40 font-mono'}
            placeholder={'1,264000,9861000,1500.00,SH,Spot height&#10;2,264010,9861000,1500.15,RD,Road edge&#10;3,264020,9861000,1500.30,RD,Road edge&#10;4,264030,9861000,1500.50,BLD,Building corner'} />
          <button onClick={handleParsePoints} className="mt-2 px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-secondary)] hover:bg-[var(--border-hover)]">
            Parse Points ({points.length} loaded)
          </button>
        </div>

        {/* Breakline Input */}
        <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h2 className="text-sm font-semibold mb-2">2. Breaklines (optional)</h2>
          <p className="text-[10px] text-[var(--text-muted)] mb-1">Format: type,x1,y1,z1,x2,y2,z2,...</p>
          <textarea value={breaklineInput} onChange={e => setBreaklineInput(e.target.value)}
            className={inputCls + ' h-40 font-mono'}
            placeholder={'hard,264010,9861000,1500.15,264020,9861000,1500.30,264030,9861000,1500.50'} />
          <button onClick={handleParseBreaklines} className="mt-2 px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-secondary)] hover:bg-[var(--border-hover)]">
            Parse Breaklines ({breaklines.length} loaded)
          </button>
        </div>
      </div>

      {/* Feature Code Library */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <h2 className="text-sm font-semibold mb-2 flex items-center gap-2"><Layers className="w-4 h-4" /> Kenya Feature Code Library ({KENYA_TOPO_CODES.length} codes)</h2>
        <div className="flex gap-2 mb-2">
          <div className="relative flex-1">
            <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[var(--text-muted)]" />
            <input value={codeFilter} onChange={e => setCodeFilter(e.target.value)} placeholder="Search codes..."
              className={inputCls + ' pl-7'} />
          </div>
        </div>
        <div className="grid grid-cols-4 gap-1 max-h-32 overflow-y-auto">
          {filteredCodes.map(def => (
            <div key={def.code} className="text-[10px] px-2 py-1 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)]/30">
              <span className="font-mono font-bold text-[var(--accent)]">{def.code}</span>
              <span className="text-[var(--text-muted)] ml-1">{def.description}</span>
              <span className="text-[var(--text-muted)]/50 ml-1">→ {def.dxfLayer}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Contour Generation */}
      <div className="bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4 mb-4">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-sm font-semibold">3. Contour Generation</h2>
          <div className="flex gap-2 items-center">
            <label className="text-[10px] text-[var(--text-muted)]" htmlFor="interval-m">Interval (m):</label>
            <input value={contourInterval} onChange={e => setContourInterval(e.target.value)} className={inputCls + ' w-20'} />
            <button onClick={handleGenerateContours} disabled={loading || points.length < 3}
              className="px-4 py-2 bg-[var(--accent)] text-black text-xs font-semibold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-50">
              {loading ? 'Generating...' : 'Generate Contours'}
            </button>
          </div>
        </div>

        {error && <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-3 mb-3 text-xs text-red-400 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}

        {sanity && (
          <div className={`p-3 rounded-lg mb-3 text-xs ${sanity.passed ? 'bg-green-500/10 text-green-400 border border-green-500/20' : 'bg-red-500/10 text-red-400 border border-red-500/20'}`}>
            <div className="flex items-center gap-2 font-semibold">
              {sanity.passed ? <CheckCircle2 className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
              Contour Sanity Check
            </div>
            <p className="mt-1 opacity-80">{sanity.summary}</p>
            {sanity.issues.length > 0 && (
              <div className="mt-2 space-y-1">
                {sanity.issues.map((issue: any, i: number) => (
                  <div key={i} className="text-[10px]">
                    <span className={issue.severity === 'error' ? 'text-red-400' : 'text-yellow-400'}>[{issue.severity.toUpperCase()}]</span>
                    {' '}{issue.message}
                    <span className="text-[var(--text-muted)] block ml-4">→ {issue.suggestion}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {contours && (
          <div className="text-xs text-[var(--text-secondary)]">
            Generated {contours.length} contour lines at {contourInterval}m interval
          </div>
        )}
      </div>

      {/* Export */}
      <div className="flex gap-3">
        <button onClick={handleExportDXF} disabled={points.length === 0}
          className="flex items-center gap-2 px-4 py-2 bg-[var(--accent)]/15 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-semibold rounded-lg hover:bg-[var(--accent)]/25 disabled:opacity-50">
          <Download className="w-4 h-4" /> Export Topo DXF
        </button>
        <button onClick={handleExportSpotHeights} disabled={points.length === 0}
          className="flex items-center gap-2 px-4 py-2 bg-[var(--accent)]/15 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-semibold rounded-lg hover:bg-[var(--accent)]/25 disabled:opacity-50">
          <FileSpreadsheet className="w-4 h-4" /> Spot Height Schedule (Excel)
        </button>
      </div>

      {/* Points Table */}
      {points.length > 0 && (
        <div className="mt-4 bg-[var(--bg-secondary)]/50 border border-[var(--border-color)] rounded-xl p-4">
          <h3 className="text-sm font-semibold mb-2">Loaded Points ({points.length})</h3>
          <div className="overflow-x-auto max-h-60">
            <table className="w-full text-xs">
              <thead><tr className="text-[var(--text-muted)] border-b border-[var(--border-color)] sticky top-0 bg-[var(--bg-secondary)]">
                <th className="text-left py-1 px-1">Pt No</th><th className="text-right">Easting</th><th className="text-right">Northing</th><th className="text-right">RL</th><th className="text-left">Code</th><th className="text-left">Description</th>
              </tr></thead>
              <tbody>
                {points.map((p, i) => (
                  <tr key={i} className="border-b border-[var(--border-color)]/30 text-[var(--text-secondary)]">
                    <td className="py-1 px-1 font-mono">{p.pointNumber}</td>
                    <td className="text-right font-mono">{p.easting.toFixed(3)}</td>
                    <td className="text-right font-mono">{p.northing.toFixed(3)}</td>
                    <td className="text-right font-mono">{p.rl.toFixed(3)}</td>
                    <td className="font-mono text-[var(--accent)]">{p.code}</td>
                    <td>{p.description}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react'
import { AlertTriangle } from 'lucide-react'
import { useSearchParams } from 'next/navigation'
import { bowditchAdjustment, transitAdjustment } from '@/lib/engine/traverse'
import { trackEvent } from '@/lib/analytics/events'
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { bowditchAdjustmentSolvedFromResult, transitAdjustmentSolvedFromResult } from '@/lib/engine/solution/wrappers/traverse'
import { computeTraverseAccuracy } from '@/lib/reports/traverseAccuracy'
import { buildPrintDocument, openPrint } from '@/lib/print/buildPrintDocument'
import { PrintMetaPanel, defaultPrintMeta, type PrintMeta } from '@/components/shared/PrintMetaPanel'
import { PageHeader } from '@/components/shared/PageHeader'
import { useLanguage } from '@/lib/i18n/LanguageContext'
import { TraverseDiagram } from '@/components/traverse/TraverseDiagram'

// ── Types ──────────────────────────────────────────────────────────────────

interface Leg {
  id: number
  name: string
  n: string
  e: string
  dist: string
  bearingD: string
  bearingM: string
  bearingS: string
}

interface DMS { d: string; m: string; s: string }

interface AzmResult {
  totalMisclosureSec: number
  misclosurePerStationSec: number
  numStations: number
  passes: boolean
  numCourses: number
  coursesWarning: boolean
}

// ── Helpers ────────────────────────────────────────────────────────────────

function dmsToDecimal(d: string, m: string, s: string): number {
  return (parseFloat(d) || 0) + (parseFloat(m) || 0) / 60 + (parseFloat(s) || 0) / 3600
}

/**
 * Compute angular (azimuth) misclosure.
 * RDM 1.1 (2025) Table 5.1: ≤ 3.0″ per station, max 15 courses without intermediate check.
 */
function computeAzmMisclosure(
  init: DMS,
  close: DMS,
  numStations: number,
): AzmResult | null {
  const iD = parseFloat(init.d), cD = parseFloat(close.d)
  if (isNaN(iD) || isNaN(cD)) return null

  const initialDeg = dmsToDecimal(init.d, init.m, init.s)
  const closingDeg = dmsToDecimal(close.d, close.m, close.s)

  let diffSec = Math.abs(initialDeg - closingDeg) * 3600
  // Handle 360° wrap-around
  if (diffSec > 648000) diffSec = 1296000 - diffSec

  const perStation = numStations > 0 ? diffSec / numStations : 0

  return {
    totalMisclosureSec:     diffSec,
    misclosurePerStationSec: perStation,
    numStations,
    passes:         perStation <= 3.0,
    numCourses:     numStations,
    coursesWarning: numStations > 15,
  }
}

// ── Component ──────────────────────────────────────────────────────────────

export default function TraverseCalculator() {
  const { t } = useLanguage()
  // Traverse legs
  const [legs, setLegs] = useState<Leg[]>([
    { id: 1, name: 'A', n: '5000', e: '3000', dist: '250.0',  bearingD: '45',  bearingM: '32', bearingS: '08' },
    { id: 2, name: 'B', n: '',     e: '',     dist: '180.5',  bearingD: '120', bearingM: '07', bearingS: '24' },
    { id: 3, name: 'C', n: '',     e: '',     dist: '220.75', bearingD: '200', bearingM: '20', bearingS: '44' },
    { id: 4, name: 'D', n: '5020', e: '3050', dist: '190.25', bearingD: '290', bearingM: '34', bearingS: '04' },
  ])
  const [method, setMethod]       = useState<'bowditch' | 'transit'>('bowditch')
  const [result, setResult]       = useState<any>(null)
  const [steps,  setSteps]        = useState<SolutionStep[] | null>(null)
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined)
  const [calcError, setCalcError] = useState<string | null>(null)
  const [calculating, setCalculating] = useState(false)

  // Angular misclosure (RDM 1.1 Table 5.1)
  const [initBearing,  setInitBearing]  = useState<DMS>({ d: '', m: '', s: '' })
  const [closeBearing, setCloseBearing] = useState<DMS>({ d: '', m: '', s: '' })
  const [azmResult, setAzmResult]       = useState<AzmResult | null>(null)

  // Print
  const [printMeta, setPrintMeta] = useState<PrintMeta>(defaultPrintMeta)

  // ── Project integration: auto-load survey points as traverse legs ──
  const searchParams = useSearchParams()
  const projectId = searchParams.get('project')
  const [projectLoaded, setProjectLoaded] = useState(false)

  useEffect(() => {
    if (!projectId || projectLoaded) return
    let cancelled = false
    ;(async () => {
      try {
        const res = await fetch(`/api/project/${projectId}/points`)
        if (!res.ok) return
        const json = await res.json()
        const points = json.data || []
        if (points.length < 2 || cancelled) return

        // Convert survey points to traverse legs
        // First point gets known E/N, rest get empty (to be computed)
        const projectLegs: Leg[] = points.map((p: any, i: number) => ({
          id: i + 1,
          name: p.point_name || String.fromCharCode(65 + i),
          n: i === 0 ? String(p.northing) : '',
          e: i === 0 ? String(p.easting) : '',
          dist: '',
          bearingD: '',
          bearingM: '',
          bearingS: '',
        }))

        // If there's a closing point (last point has same name as first or is_control),
        // give it known coordinates too
        if (points.length > 1) {
          const last = points[points.length - 1]
          if (last.is_control || last.point_name === points[0].point_name) {
            projectLegs[projectLegs.length - 1].n = String(last.northing)
            projectLegs[projectLegs.length - 1].e = String(last.easting)
          }
        }

        if (!cancelled && projectLegs.length >= 2) {
          setLegs(projectLegs)
        }
      } catch {
        // silent fail — user can enter manually
      } finally {
        if (!cancelled) setProjectLoaded(true)
      }
    })()
    return () => { cancelled = true }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projectId, projectLoaded])

  // ── Leg management ───────────────────────────────────────────────────────

  const addLeg = () => {
    const nextChar = String.fromCharCode(65 + legs.length)
    setLegs([...legs, { id: Date.now(), name: nextChar, n: '', e: '', dist: '', bearingD: '', bearingM: '', bearingS: '' }])
  }

  const updateLeg = (id: number, field: keyof Leg, value: string) =>
    setLegs(legs.map(l => l.id === id ? { ...l, [field]: value } : l))

  // ── Calculate ────────────────────────────────────────────────────────────

  const calculate = () => {
    setCalcError(null)
    setCalculating(true)
    try {
      const points   = legs.filter(l => l.n && l.e).map(l => ({ name: l.name, northing: parseFloat(l.n), easting: parseFloat(l.e) }))
      const distances = legs.map(l => parseFloat(l.dist)).filter(d => !isNaN(d))
      const bearings  = legs.map(l => dmsToDecimal(l.bearingD, l.bearingM, l.bearingS)).filter(b => !isNaN(b))

      if (points.length < 2 || distances.length < 2 || bearings.length < 2) {
        setCalcError('Enter at least 2 legs with valid distances, bearings, and at least TWO known coordinates (first and last rows N & E). Per Survey Regulations Reg. 60 & 67, a traverse requires both opening and closing control points — swinging/hanging traverses are prohibited.')
        return
      }

      const r = method === 'bowditch'
        ? bowditchAdjustment({ points, distances, bearings })
        : transitAdjustment({ points, distances, bearings })

      // Map engine property names to display property names for compatibility
      const mappedResult = {
        ...r,
        legs: r.legs.map((leg: any) => ({
          ...leg,
          departure: leg.rawDeltaE,
          latitude: leg.rawDeltaN,
          correctedDeparture: leg.adjDeltaE,
          correctedLatitude: leg.adjDeltaN,
        }))
      }
      setResult(mappedResult)
      trackEvent('tool_used', { tool: 'traverse', method })

      try {
        const s = method === 'bowditch'
          ? bowditchAdjustmentSolvedFromResult(r)
          : transitAdjustmentSolvedFromResult(r)
        setSteps(s.steps)
        setSolutionTitle(s.solution.title)
      } catch { setSteps(null); setSolutionTitle(undefined) }

      // Angular misclosure — RDM 1.1 Table 5.1
      if (initBearing.d && closeBearing.d) {
        setAzmResult(computeAzmMisclosure(initBearing, closeBearing, legs.length))
      } else {
        setAzmResult(null)
      }

    } catch (err: unknown) {
      setCalcError(((err as Error)?.message) || 'Calculation failed. Check your inputs.')
      setResult(null); setSteps(null)
    } finally {
      setCalculating(false)
    }
  }

  // ── Print ────────────────────────────────────────────────────────────────

  const handlePrint = () => {
    if (!result) return
    const mLabel = method === 'bowditch' ? 'Bowditch Rule' : 'Transit Rule'

    const table1Rows = result.legs.map((l: any) => `
<tr>
  <td class="bold">${l.from} → ${l.to}</td>
  <td class="mono">${l.bearingDMS}</td>
  <td class="right mono">${l.distance.toFixed(4)}</td>
  <td class="right mono">${l.departure >= 0 ? '+' : ''}${l.departure.toFixed(4)}</td>
  <td class="right mono">${l.latitude >= 0 ? '+' : ''}${l.latitude.toFixed(4)}</td>
</tr>`).join('')

    const table2Rows = result.legs.map((l: any) => `
<tr>
  <td class="bold">${l.from} → ${l.to}</td>
  <td class="right mono">${l.distance.toFixed(4)}</td>
  <td class="right mono">${(l.correctedDeparture - l.departure).toFixed(4)}</td>
  <td class="right mono">${(l.correctedLatitude  - l.latitude ).toFixed(4)}</td>
  <td class="right mono bold">${l.correctedDeparture.toFixed(4)}</td>
  <td class="right mono bold">${l.correctedLatitude.toFixed(4)}</td>
</tr>`).join('')

    const table3Rows = result.legs.map((l: any) => `
<tr>
  <td class="bold">${l.to}</td>
  <td class="right mono bold">${l.adjEasting.toFixed(4)}</td>
  <td class="right mono bold">${l.adjNorthing.toFixed(4)}</td>
</tr>`).join('')

    const acc = computeTraverseAccuracy(result.linearError, result.totalDistance)

    const azmSection = azmResult ? `
<h2>Table 4 — Angular Misclosure — RDM 1.1 (2025) Table 5.1</h2>
<div class="summary-box">
  <div class="summary-row"><span class="summary-label">Number of Stations</span><span class="summary-value">${azmResult.numStations}</span></div>
  <div class="summary-row"><span class="summary-label">Total Misclosure</span><span class="summary-value">${azmResult.totalMisclosureSec.toFixed(1)}&#8243;</span></div>
  <div class="summary-row"><span class="summary-label">Misclosure per Station</span><span class="summary-value">${azmResult.misclosurePerStationSec.toFixed(2)}&#8243;</span></div>
  <div class="summary-row"><span class="summary-label">Allowable (RDM 1.1 Table 5.1)</span><span class="summary-value">&#8804; 3.0&#8243; per station</span></div>
  <div class="summary-row"><span class="summary-label">Maximum Courses Without Check</span><span class="summary-value">15</span></div>
  <div class="summary-row"><span class="summary-label">Status</span><span class="summary-value ${azmResult.passes ? 'pass' : 'fail'}">${azmResult.passes ? 'ACCEPTABLE' : 'EXCEEDS TOLERANCE'}</span></div>
  ${azmResult.coursesWarning ? '<div class="summary-row"><span class="summary-label warn">&#9888; Intermediate azimuth check required (&gt;15 courses)</span></div>' : ''}
</div>` : `
<h2>Angular Misclosure</h2>
<p style="color:#666;font-size:9pt;font-style:italic">No closing azimuth provided. RDM 1.1 (2025) Table 5.1 requires an azimuth check (&#8804;3.0&#8243;/station) for formal survey submissions.</p>`

    const bodyHtml = `
<h2>Table 1 — Traverse Computation (${mLabel})</h2>
<table>
  <tr>
    <th>Line</th>
    <th>WCB</th>
    <th class="right">HD (m)</th>
    <th class="right">Departure (m)</th>
    <th class="right">Latitude (m)</th>
  </tr>
  ${table1Rows}
  <tfoot>
    <tr>
      <td colspan="3" class="right">&#931;</td>
      <td class="right mono">${result.legs.reduce((s: number, l: any) => s + l.departure, 0).toFixed(4)}</td>
      <td class="right mono">${result.legs.reduce((s: number, l: any) => s + l.latitude,  0).toFixed(4)}</td>
    </tr>
  </tfoot>
</table>

<h2>Table 2 — ${mLabel} Corrections</h2>
<table>
  <tr>
    <th>Line</th>
    <th class="right">HD (m)</th>
    <th class="right">Corr-Dep</th>
    <th class="right">Corr-Lat</th>
    <th class="right">Adj-Dep</th>
    <th class="right">Adj-Lat</th>
  </tr>
  ${table2Rows}
</table>

<h2>Table 3 — Adjusted Coordinates</h2>
<table>
  <tr>
    <th>Point</th>
    <th class="right">Easting (m)</th>
    <th class="right">Northing (m)</th>
  </tr>
  ${table3Rows}
</table>

<div class="summary-box">
  <h2 style="border:none;margin:0 0 8px">Linear Misclosure &amp; Accuracy — RDM 1.1 (2025) Table 5.1</h2>
  <div class="summary-row"><span class="summary-label">Method</span><span class="summary-value">${mLabel}</span></div>
  <div class="summary-row"><span class="summary-label">Total Distance (Perimeter)</span><span class="summary-value">${result.totalDistance.toFixed(4)} m</span></div>
  <div class="summary-row"><span class="summary-label">&#931; Departures</span><span class="summary-value">${result.legs.reduce((s: number, l: any) => s + l.departure, 0).toFixed(4)} m</span></div>
  <div class="summary-row"><span class="summary-label">&#931; Latitudes</span><span class="summary-value">${result.legs.reduce((s: number, l: any) => s + l.latitude,  0).toFixed(4)} m</span></div>
  <div class="summary-row"><span class="summary-label">Linear Misclosure</span><span class="summary-value">${result.linearError.toFixed(6)} m</span></div>
  <div class="summary-row"><span class="summary-label">Precision Ratio</span><span class="summary-value">1 : ${Math.round(result.precisionRatio)}</span></div>
  <div class="summary-row"><span class="summary-label">Allowable (RDM 1.1 Table 5.1)</span><span class="summary-value">1 : 10 000</span></div>
  ${acc ? `<div class="summary-row"><span class="summary-label">Survey Order</span><span class="summary-value">${acc.order}</span></div>` : ''}
</div>

${azmSection}`

    const doc = buildPrintDocument(bodyHtml, {
      title:     `Traverse Computation — ${mLabel}`,
      reference: 'RDM 1.1 (2025) Table 5.1 &nbsp;|&nbsp; Survey Regulations 1994 &nbsp;|&nbsp; Survey Act Cap 299',
      ...printMeta,
    })
    openPrint(doc)
  }

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <div className="w-full max-w-7xl mx-auto px-3 md:px-4 py-4 md:py-8">

      <PageHeader
        title={t('tools.traverse')}
        subtitle={t('tools.traverseDesc')}
        reference="RDM 1.1 (2025) Table 5.1 | Survey Regulations 1994 | Survey Act Cap 299"
      />

      {/* Hint bar */}
      <div className="mb-4 px-4 py-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-muted)] flex flex-wrap gap-x-6 gap-y-1">
        <span><span className="text-[var(--text-secondary)] font-medium">Bearings</span> — WCB in Degrees°Minutes′Seconds″ as read from instrument</span>
        <span><span className="text-[var(--text-secondary)] font-medium">Distances</span> — horizontal distances in metres</span>
        <span><span className="text-[var(--text-secondary)] font-medium">First row</span> — must have known Northing &amp; Easting</span>
      </div>

      {/* Method buttons */}
      <div className="flex gap-4 mb-6">
        <button onClick={() => { setMethod('bowditch'); setResult(null); setSteps(null); setSolutionTitle(undefined) }}
          className={`btn ${method === 'bowditch' ? 'btn-primary' : 'btn-secondary'}`}>
          Bowditch Rule
        </button>
        <button onClick={() => { setMethod('transit'); setResult(null); setSteps(null); setSolutionTitle(undefined) }}
          className={`btn ${method === 'transit' ? 'btn-primary' : 'btn-secondary'}`}>
          Transit Rule
        </button>
      </div>

      <div className="grid gap-6 mb-6">
        {/* Leg table */}
        <div className="card">
          <div className="card-header">
            <span className="label">Traverse Computation Table — {method === 'bowditch' ? 'Bowditch' : 'Transit'} Adjustment</span>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-[550px] table">
              <thead>
                <tr>
                  <th>Line</th>
                  <th>Dist (m)</th>
                  <th>WCB</th>
                  <th>N (m)</th>
                  <th>E (m)</th>
                </tr>
              </thead>
              <tbody>
                {legs.map((l, i) => (
                  <tr key={l.id}>
                    <td className="text-left font-semibold">{l.name}</td>
                    <td>
                      <input className="input" value={l.dist} aria-label="Distance" placeholder="e.g. 250.00"
                        onChange={e => updateLeg(l.id, 'dist', e.target.value)} />
                    </td>
                    <td>
                      <div className="flex items-center gap-0.5 md:gap-1">
                        <input className="input w-10 md:w-12 text-center text-xs md:text-sm" value={l.bearingD} aria-label="Bearing (Deg)" placeholder="DDD" maxLength={3}
                          onChange={e => updateLeg(l.id, 'bearingD', e.target.value)} />
                        <span className="text-[var(--text-muted)] text-xs">°</span>
                        <input className="input w-8 md:w-10 text-center text-xs md:text-sm" value={l.bearingM} aria-label="Bearing (Min)" placeholder="MM" maxLength={2}
                          onChange={e => updateLeg(l.id, 'bearingM', e.target.value)} />
                        <span className="text-[var(--text-muted)] text-xs">&apos;</span>
                        <input className="input w-10 md:w-12 text-center text-xs md:text-sm" value={l.bearingS} aria-label="Bearing (Sec)" placeholder="SS" maxLength={5}
                          onChange={e => updateLeg(l.id, 'bearingS', e.target.value)} />
                        <span className="text-[var(--text-muted)] text-xs">&quot;</span>
                      </div>
                    </td>
                    <td>
                      <input aria-label="N" className="input" value={l.n} placeholder={i === 0 ? 'required' : 'auto'}
                        onChange={e => updateLeg(l.id, 'n', e.target.value)} />
                    </td>
                    <td>
                      <input aria-label="E" className="input" value={l.e} placeholder={i === 0 ? 'required' : 'auto'}
                        onChange={e => updateLeg(l.id, 'e', e.target.value)} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="p-4">
            <button onClick={addLeg} className="btn btn-secondary">+ Add Leg</button>
          </div>
        </div>

        {/* ── Angular Misclosure Check (RDM 1.1 Table 5.1) ─────────────── */}
        <div className="card">
          <div className="card-header">
            <span className="label">Angular Misclosure Check</span>
            <span className="text-xs text-[var(--text-muted)] ml-2">RDM 1.1 Table 5.1 — ≤ 3.0″ per station | max 15 courses</span>
          </div>
          <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
            {([
              ['Initial Reference Bearing (WCB)', initBearing,  setInitBearing ] as const,
              ['Computed Closing Bearing (WCB)',  closeBearing, setCloseBearing] as const,
            ]).map(([label, val, setVal]) => (
              <div key={label}>
                <label className="block text-xs text-[var(--text-muted)] mb-1.5">{label}</label>
                <div className="flex items-center gap-1">
                  <input className="input w-12 text-center text-xs" aria-label="Bearing (Deg)" placeholder="DDD" value={val.d}
                    onChange={e => setVal(p => ({ ...p, d: e.target.value }))} />
                  <span className="text-[var(--text-muted)] text-xs">°</span>
                  <input className="input w-10 text-center text-xs" aria-label="Bearing (Min)" placeholder="MM" value={val.m}
                    onChange={e => setVal(p => ({ ...p, m: e.target.value }))} />
                  <span className="text-[var(--text-muted)] text-xs">&apos;</span>
                  <input className="input w-14 text-center text-xs" aria-label="Bearing (Sec)" placeholder="SS.ss" value={val.s}
                    onChange={e => setVal(p => ({ ...p, s: e.target.value }))} />
                  <span className="text-[var(--text-muted)] text-xs">&quot;</span>
                </div>
              </div>
            ))}
          </div>
          <p className="px-4 pb-4 text-xs text-[var(--text-muted)]">
            Enter the initial reference bearing and the bearing computed back to the reference line.
            Leave blank if no closing azimuth check was performed (noted in print output).
          </p>
        </div>

        {/* Calculate button */}
        <button onClick={calculate} disabled={calculating}
          className="btn btn-primary disabled:opacity-60 disabled:cursor-not-allowed">
          {calculating ? (
            <><svg className="w-4 h-4 animate-spin" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"/>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8z"/>
            </svg> {t('toolUI.calculating')}</>
          ) : 'Calculate Adjustment'}
        </button>
      </div>

      {/* Error */}
      {calcError && (
        <div className="rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-800 mb-6 dark:border-red-800 dark:bg-red-950 dark:text-red-200">
          <p className="font-semibold">Error</p>
          <p>{calcError}</p>
        </div>
      )}

      {/* ── Results ────────────────────────────────────────────────────── */}
      {result && (
        <div className="grid md:grid-cols-2 gap-6">

          {/* Traverse Diagram — full width */}
          <div className="md:col-span-2 card">
            <div className="card-header flex justify-between items-center">
              <span className="label">Traverse Diagram — Adjusted vs Raw</span>
              <span className="text-xs text-[var(--text-muted)] font-mono">
                Closing error: {result.linearError.toFixed(4)} m · Precision 1:{Math.round(result.precisionRatio)}
              </span>
            </div>
            <div className="p-4">
              <TraverseDiagram result={result} />
            </div>
          </div>

          {/* Linear Misclosure */}
          <div className="card">
            <div className="card-header flex justify-between items-center">
              <span className="label">Linear Misclosure Analysis</span>
              <span className={`badge ${result.isClosed ? 'badge-success' : 'badge-warning'}`}>
                {result.isClosed ? 'Closed' : 'Not Closed'}
              </span>
            </div>
            <div className="card-body space-y-3">
              <ResultRow label="Method" value={method === 'bowditch' ? 'Bowditch Rule' : 'Transit Rule'} />
              <ResultRow label="Total Distance" value={`${result.totalDistance.toFixed(4)} m`} />
              <ResultRow label="Σ Departures" value={`${result.legs.reduce((s: number, l: any) => s + l.departure, 0).toFixed(4)} m`} />
              <ResultRow label="Σ Latitudes"  value={`${result.legs.reduce((s: number, l: any) => s + l.latitude,  0).toFixed(4)} m`} />
              <ResultRow label="Linear Misclosure" value={`${result.linearError.toFixed(6)} m`} />
              <ResultRow label="Precision Ratio"   value={`1 : ${Math.round(result.precisionRatio)}`} highlight />
            </div>
          </div>

          {/* RDM 1.1 Accuracy Order */}
          {(() => {
            const acc = computeTraverseAccuracy(result.linearError, result.totalDistance)
            if (!acc) return null
            const badgeClass = acc.order === 'FIRST ORDER CLASS I'  ? 'bg-emerald-700 text-white'
              : acc.order === 'FIRST ORDER CLASS II' ? 'bg-emerald-600 text-white'
              : acc.order === 'SECOND ORDER CLASS I' ? 'bg-amber-500 text-black'
              : acc.order === 'SECOND ORDER CLASS II'? 'bg-orange-600 text-white'
              : 'bg-red-600 text-white'
            return (
              <div className="card">
                <div className="card-header">
                  <span className="label">Traverse Accuracy — RDM 1.1 Table 5.1</span>
                </div>
                <div className="card-body space-y-3">
                  <ResultRow label="Total Perimeter"   value={`${result.totalDistance.toFixed(4)} m`} />
                  <ResultRow label="Linear Misclosure" value={`${result.linearError.toFixed(6)} m`} />
                  <ResultRow label="Precision Ratio"   value={`1 : ${Math.round(result.precisionRatio)}`} />
                  <ResultRow label="Allowable (RDM 1.1 Table 5.1)" value="1 : 10 000" />
                  <div className="mt-3 p-4 rounded-lg text-center">
                    <p className="text-xs text-[var(--text-muted)] mb-2">TRAVERSE ACCURACY ORDER</p>
                    <span className={`inline-block px-4 py-2 rounded-lg font-bold text-sm ${badgeClass}`}>
                      {acc.order}
                    </span>
                    <p className="text-xs text-[var(--text-muted)] mt-2 font-mono">{acc.formula}</p>
                  </div>
                </div>
              </div>
            )
          })()}

          {/* ── Angular Misclosure Result ───────────────────────────────── */}
          {azmResult ? (
            <div className="card">
              <div className="card-header flex justify-between items-center">
                <span className="label">Angular Misclosure — RDM 1.1 Table 5.1</span>
                <span className={`badge ${azmResult.passes ? 'badge-success' : 'badge-error'}`}>
                  {azmResult.passes ? 'PASSES' : 'FAILS'}
                </span>
              </div>
              <div className="card-body space-y-3">
                <ResultRow label="Stations"                value={String(azmResult.numStations)} />
                <ResultRow label="Total Misclosure"        value={`${azmResult.totalMisclosureSec.toFixed(1)}″`} />
                <ResultRow label="Misclosure per Station"  value={`${azmResult.misclosurePerStationSec.toFixed(2)}″`} highlight />
                <ResultRow label="Allowable (RDM 1.1)"    value="≤ 3.0″ per station" />
                {azmResult.coursesWarning && (
                  <div className="rounded p-3 bg-amber-900/20 border border-amber-700 text-xs text-amber-300">
                    <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> {azmResult.numCourses} courses — RDM 1.1 requires an azimuth check every 15 courses maximum.
                  </div>
                )}
                <div className={`mt-1 p-3 rounded-lg text-center ${azmResult.passes
                  ? 'bg-emerald-900/20 border border-emerald-700'
                  : 'bg-red-900/20 border border-red-700'}`}>
                  <p className="text-xs text-[var(--text-muted)] mb-1">RDM 1.1 TABLE 5.1 — AZIMUTH CHECK</p>
                  <p className={`font-bold text-sm ${azmResult.passes ? 'text-emerald-400' : 'text-red-400'}`}>
                    {azmResult.misclosurePerStationSec.toFixed(2)}″/station —{' '}
                    {azmResult.passes ? 'ACCEPTABLE ≤ 3.0″' : 'EXCEEDS 3.0″ LIMIT'}
                  </p>
                </div>
              </div>
            </div>
          ) : result ? (
            <div className="card border-dashed opacity-60">
              <div className="card-body text-center py-6">
                <p className="text-xs text-[var(--text-muted)]">Enter initial and closing bearings above to compute angular misclosure</p>
                <p className="text-xs text-[var(--text-muted)] mt-1 font-mono">RDM 1.1 Table 5.1 — ≤ 3.0″ per station required</p>
              </div>
            </div>
          ) : null}

          {/* Table 1 — Traverse Computation */}
          <div className="card">
            <div className="card-header">
              <span className="label">Table 1 — Traverse Computation</span>
            </div>
            <div className="overflow-x-auto">
              <table className="min-w-[550px] table">
                <thead>
                  <tr>
                    <th>Line</th>
                    <th>WCB</th>
                    <th className="text-right">HD</th>
                    <th className="text-right">Departure</th>
                    <th className="text-right">Latitude</th>
                  </tr>
                </thead>
                <tbody>
                  {result.legs.map((l: any, i: number) => (
                    <tr key={`item-${i}`}>
                      <td className="font-semibold">{l.from} → {l.to}</td>
                      <td className="font-mono">{l.bearingDMS}</td>
                      <td className="text-right font-mono">{l.distance.toFixed(4)}</td>
                      <td className="text-right font-mono">{l.departure >= 0 ? '+' : ''}{l.departure.toFixed(4)}</td>
                      <td className="text-right font-mono">{l.latitude >= 0 ? '+' : ''}{l.latitude.toFixed(4)}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  <tr className="font-semibold bg-[var(--bg-tertiary)]">
                    <td colSpan={3} className="text-right">Σ</td>
                    <td className="text-right font-mono">{result.legs.reduce((s: number, l: any) => s + l.departure, 0).toFixed(4)}</td>
                    <td className="text-right font-mono">{result.legs.reduce((s: number, l: any) => s + l.latitude,  0).toFixed(4)}</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>

          {/* Table 2 — Corrections */}
          <div className="card">
            <div className="card-header">
              <span className="label">Table 2 — {method === 'bowditch' ? 'Bowditch' : 'Transit'} Corrections</span>
            </div>
            <div className="overflow-x-auto">
              <table className="min-w-[650px] table">
                <thead>
                  <tr>
                    <th>Line</th>
                    <th className="text-right">HD</th>
                    <th className="text-right">C-Dep</th>
                    <th className="text-right">C-Lat</th>
                    <th className="text-right">A-Dep</th>
                    <th className="text-right">A-Lat</th>
                  </tr>
                </thead>
                <tbody>
                  {result.legs.map((l: any, i: number) => (
                    <tr key={`item-${i}`}>
                      <td className="font-semibold">{l.from} → {l.to}</td>
                      <td className="text-right font-mono">{l.distance.toFixed(4)}</td>
                      <td className="text-right font-mono">{(l.correctedDeparture - l.departure).toFixed(4)}</td>
                      <td className="text-right font-mono">{(l.correctedLatitude  - l.latitude ).toFixed(4)}</td>
                      <td className="text-right font-mono font-semibold">{l.correctedDeparture.toFixed(4)}</td>
                      <td className="text-right font-mono font-semibold">{l.correctedLatitude.toFixed(4)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Table 3 — Adjusted Coordinates */}
          <div className="card">
            <div className="card-header">
              <span className="label">Table 3 — Adjusted Coordinates</span>
            </div>
            <div className="overflow-x-auto">
              <table className="table">
                <thead>
                  <tr>
                    <th>Point</th>
                    <th className="text-right">Easting (m)</th>
                    <th className="text-right">Northing (m)</th>
                  </tr>
                </thead>
                <tbody>
                  {result.legs.map((l: any, i: number) => (
                    <tr key={`item-${i}`}>
                      <td className="font-semibold">{l.to}</td>
                      <td className="text-right font-mono font-semibold text-[var(--accent)]">{l.adjEasting.toFixed(4)}</td>
                      <td className="text-right font-mono font-semibold text-[var(--accent)]">{l.adjNorthing.toFixed(4)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Print section */}
          <div className="md:col-span-2">
            <div className="card">
              <div className="card-header">
                <span className="label">Print Computation Sheet</span>
              </div>
              <div className="p-4 space-y-4">
                <PrintMetaPanel meta={printMeta} onChange={setPrintMeta} />
                <div className="text-xs text-[var(--text-muted)] space-y-0.5 mb-2">
                  <p>Sheet includes: standard document header · Tables 1–3 · Linear misclosure · Angular misclosure (RDM 1.1 Table 5.1) · Surveyor's Certificate</p>
                </div>
                <button onClick={handlePrint}
                  className="btn btn-primary w-full md:w-auto">
                  Print Traverse Computation Sheet
                </button>
              </div>
            </div>
          </div>

          {/* Solution steps */}
          {steps && (
            <div className="md:col-span-2">
              <SolutionStepsRenderer title={solutionTitle} steps={steps} />
            </div>
          )}
        </div>
      )}
    </div>
  )
}

function ResultRow({ label, value, highlight }: { label: string; value: string; highlight?: boolean }) {
  return (
    <div className="flex justify-between items-center py-2 border-b border-[var(--border-color)]">
      <span className="text-sm text-[var(--text-secondary)]">{label}</span>
      <span className={`font-mono ${highlight ? 'result-accent font-bold' : ''}`}>{value}</span>
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Download } from 'lucide-react';
import SolutionStepsRenderer from '@/components/SolutionStepsRenderer'
import type { SolutionStep } from '@/lib/engine/solution/solutionBuilder'
import { twoPegTestSolved } from '@/lib/engine/solution/wrappers/twoPegTest'
import { PageHeader } from '@/components/shared/PageHeader'
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export default function TwoPegTestCalculator() {
  const { t } = useLanguage()
  const [inputs, setInputs] = useState({
    a1: '',  // Staff at A from position 1
    b1: '',  // Staff at B from position 1
    a2: '',  // Staff at A from position 2
    b2: '',  // Staff at B from position 2
    // AUDIT FIX (2026-07-03): Add baseline distance + tolerance inputs.
    // Previously the baseline was hardcoded to 100m and the allowable
    // error to 10mm/100m — surveyors couldn't change them for non-standard
    // setups (e.g., 50m baseline, 2mm/100m digital level tolerance).
    baseline: '100',    // Distance between pegs A and B (metres)
    allowable: '10',    // Allowable collimation error (mm per 100m)
  });
  const [steps, setSteps] = useState<SolutionStep[] | null>(null);
  const [calcError, setCalcError] = useState<string | null>(null);
  const [solutionTitle, setSolutionTitle] = useState<string | undefined>(undefined);

  const calculate = () => {
    const A1 = parseFloat(inputs.a1);
    const B1 = parseFloat(inputs.b1);
    const A2 = parseFloat(inputs.a2);
    const B2 = parseFloat(inputs.b2);
    const baseline = parseFloat(inputs.baseline) || 100;
    const allowable = parseFloat(inputs.allowable) || 10;

    if (isNaN(A1) || isNaN(B1) || isNaN(A2) || isNaN(B2)) return;

    const s = twoPegTestSolved({ A1, B1, A2, B2, baselineMeters: baseline, allowableMmPer100m: allowable })
    setSteps(s.steps)
    setSolutionTitle(s.solution.title)
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <PageHeader
        title={t('tools.twoPegTest')}
        subtitle={t('tools.twoPegTestDesc')}
        reference="Survey Regulations 1994 | Survey Act Cap 299 | RDM 1.1 (2025)"
      />

      <div className="grid md:grid-cols-2 gap-8">
        <div className="card">
          <div className="card-header"><span className="label">Staff Readings</span></div>
          <div className="card-body space-y-4">
            <div className="border-b border-[var(--border-color)] pb-4 mb-4">
              <div className="text-sm text-[var(--text-secondary)] mb-3">Instrument Position 1</div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label" htmlFor="staff-at-a-m">Staff at A (m)</label>
                  <input id="staff-at-a-m" className="input" value={inputs.a1} onChange={e => setInputs({...inputs, a1: e.target.value})} aria-label="1.525" placeholder="1.525" />
                </div>
                <div>
                  <label className="label" htmlFor="staff-at-b-m">Staff at B (m)</label>
                  <input id="staff-at-b-m" className="input" value={inputs.b1} onChange={e => setInputs({...inputs, b1: e.target.value})} aria-label="1.415" placeholder="1.415" />
                </div>
              </div>
            </div>
            <div>
              <div className="text-sm text-[var(--text-secondary)] mb-3">Instrument Position 2</div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label" htmlFor="staff-at-a-m-2">Staff at A (m)</label>
                  <input id="staff-at-a-m-2" className="input" value={inputs.a2} onChange={e => setInputs({...inputs, a2: e.target.value})} aria-label="1.530" placeholder="1.530" />
                </div>
                <div>
                  <label className="label" htmlFor="staff-at-b-m-2">Staff at B (m)</label>
                  <input id="staff-at-b-m-2" className="input" value={inputs.b2} onChange={e => setInputs({...inputs, b2: e.target.value})} aria-label="1.420" placeholder="1.420" />
                </div>
              </div>
            </div>
            {/* AUDIT FIX (2026-07-03): Baseline + tolerance inputs */}
            <div className="border-b border-[var(--border-color)] pb-4 mb-4">
              <div className="text-sm text-[var(--text-secondary)] mb-3">Setup Parameters</div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="label" htmlFor="baseline-a-b-distance-m">Baseline A–B distance (m)</label>
                  <input id="baseline-a-b-distance-m" className="input" value={inputs.baseline} onChange={e => setInputs({...inputs, baseline: e.target.value})} aria-label="100" placeholder="100" type="number" />
                </div>
                <div>
                  <label className="label" htmlFor="allowable-error-mm-100m">Allowable error (mm/100m)</label>
                  <input className="input" value={inputs.allowable} onChange={e => setInputs({...inputs, allowable: e.target.value})} aria-label="10" placeholder="10" type="number" />
                </div>
              </div>
              <p className="text-xs text-[var(--text-muted)] mt-2">
                Typical: 100m baseline, 10mm/100m for optical levels. Digital levels may use 2mm/100m. Adjust per your instrument's specs and RDM 1.1 requirements.
              </p>
            </div>
            <button onClick={calculate} className="btn btn-primary w-full">Run Two Peg Test</button>
            {steps && (
              <div className="flex gap-2 mt-2">
                <button
                  onClick={() => {
                    generatePDF(
                      { title: 'Two Peg Test Certificate', reference: 'Survey Regulations 1994 | Survey Act Cap 299 | RDM 1.1 (2025)' },
                      [
                        { title: 'Staff Readings', rows: [
                          { label: 'Staff at A (Pos 1)', value: `${inputs.a1} m` },
                          { label: 'Staff at B (Pos 1)', value: `${inputs.b1} m` },
                          { label: 'Staff at A (Pos 2)', value: `${inputs.a2} m` },
                          { label: 'Staff at B (Pos 2)', value: `${inputs.b2} m` },
                        ]},
                        { title: 'Computation Steps', rows: steps.map((s: SolutionStep) => ({ label: s.label, value: s.result || s.computation || '—' })) },
                      ],
                    )
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportPdf')}
                </button>
                <button
                  onClick={() => {
                    const csv = toCSV(
                      ['Reading', 'Value (m)'],
                      [
                        ['Staff at A (Position 1)', inputs.a1],
                        ['Staff at B (Position 1)', inputs.b1],
                        ['Staff at A (Position 2)', inputs.a2],
                        ['Staff at B (Position 2)', inputs.b2],
                        ...steps.map((s: SolutionStep) => [s.label, s.result || s.computation || '']),
                      ],
                    )
                    downloadCSV(csv, 'two-peg-test-results')
                  }}
                  className="btn btn-secondary flex-1 inline-flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" /> {t('toolUI.exportCsv')}
                </button>
              </div>
            )}
          </div>
        </div>

        {steps ? <SolutionStepsRenderer title={solutionTitle} steps={steps} /> : null}
      </div>
    </div>
  );
}

'use client';

import type React from 'react';
import type { BBox, GridCell, Method } from './types';
import type { SurfacePoint } from '@/lib/engine/volume';

interface AnalysisTabProps {
  surveyAPoints: SurfacePoint[];
  surveyBPoints: SurfacePoint[];
  overlapBBox: BBox | null;
  gridSpacing: number;
  setGridSpacing: (n: number) => void;
  method: Method;
  setMethod: (m: Method) => void;
  computing: boolean;
  handleCompute: () => void;
  computeErrors: string[];
  computeWarnings: string[];
  cutVolume: number | null;
  fillVolume: number | null;
  netVolume: number | null;
  overlapArea: number | null;
  balancePoint: number | null;
  gridCells: GridCell[];
  gridBBox: BBox;
  showGrid: boolean;
  setShowGrid: (b: boolean) => void;
  hasComputedRef: React.MutableRefObject<boolean>;
  inputClass: string;
}

export default function AnalysisTab({
  surveyAPoints,
  surveyBPoints,
  overlapBBox,
  gridSpacing,
  setGridSpacing,
  method,
  setMethod,
  computing,
  handleCompute,
  computeErrors,
  computeWarnings,
  cutVolume,
  fillVolume,
  netVolume,
  overlapArea,
  balancePoint,
  gridCells,
  gridBBox,
  showGrid,
  setShowGrid,
  hasComputedRef,
  inputClass,
}: AnalysisTabProps) {
  const total = (cutVolume ?? 0) + (fillVolume ?? 0);
  const cutPct = total > 0 ? ((cutVolume ?? 0) / total) * 100 : 0;
  const fillPct = total > 0 ? ((fillVolume ?? 0) / total) * 100 : 0;
  const maxAbsDiff = gridCells.length > 0 ? Math.max(...gridCells.map(c => Math.abs(c.diff)), 0.001) : 1;

  return (
    <div className="space-y-6">
      {/* Configuration panel */}
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
        <h3 className="text-lg font-semibold mb-4">Computation Settings</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
          <div>
            <label className="block text-sm text-[var(--text-secondary)] mb-2" htmlFor="grid-spacing-m">Grid Spacing (m)</label>
            <input id="grid-spacing-m" aria-label="Grid Spacing (m)"
              type="number"
              min={0.1}
              max={5.0}
              step={0.1}
              value={gridSpacing}
              onChange={e => setGridSpacing(Math.max(0.1, Math.min(5.0, Number(e.target.value))))}
              className={inputClass}
            />
            <p className="text-xs text-[var(--text-muted)] mt-1">Range: 0.1 — 5.0 m (default: 1.0)</p>
          </div>
          <div>
            <div className="block text-sm text-[var(--text-secondary)] mb-2">Method</div>
            <div className="flex gap-2">
              <button
                onClick={() => setMethod('tin')}
                className={`flex-1 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${method === 'tin' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)]'}`}
              >
                TIN Interpolation
              </button>
              <button
                onClick={() => setMethod('idw')}
                className={`flex-1 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${method === 'idw' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)]'}`}
              >
                IDW Grid
              </button>
            </div>
            <p className="text-xs text-[var(--text-muted)] mt-1">
              {method === 'tin' ? 'Delaunay TIN with barycentric interpolation' : 'Inverse Distance Weighting (power=2)'}
            </p>
          </div>
          <div>
            <button
              onClick={handleCompute}
              disabled={computing || surveyAPoints.length < 3 || surveyBPoints.length < 3 || !overlapBBox}
              className="w-full px-4 py-3 bg-[var(--accent)] text-black rounded-lg text-sm font-bold hover:opacity-90 transition-opacity disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {computing ? 'Computing...' : 'Compute Volume'}
            </button>
            {!overlapBBox && surveyAPoints.length >= 3 && surveyBPoints.length >= 3 && (
              <p className="text-xs text-red-400 mt-1">Surveys do not overlap.</p>
            )}
          </div>
        </div>
      </div>

      {/* Errors */}
      {computeErrors.length > 0 && (
        <div className="p-4 bg-red-900/20 border border-red-800/30 rounded-lg">
          <h4 className="text-sm font-medium text-red-400 mb-1">Computation Errors</h4>
          <ul className="text-xs text-red-300/80 space-y-0.5">
            {computeErrors.map((err, i) => <li key={`${err}-${i}`}>{err}</li>)}
          </ul>
        </div>
      )}

      {/* Warnings */}
      {computeWarnings.length > 0 && (
        <div className="p-4 bg-amber-900/20 border border-amber-800/30 rounded-lg">
          <h4 className="text-sm font-medium text-amber-400 mb-1">Warnings</h4>
          <ul className="text-xs text-amber-300/80 space-y-0.5">
            {computeWarnings.map((w, i) => <li key={`${w}-${i}`}>{w}</li>)}
          </ul>
        </div>
      )}

      {/* Results */}
      {cutVolume !== null && fillVolume !== null && netVolume !== null && (
        <>
          {/* Volume Summary Cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="p-4 bg-[#8B4513]/15 border border-[#8B4513]/40 rounded-lg">
              <div className="text-xs text-[#D2691E] mb-1">Cut Volume</div>
              <div className="text-2xl font-bold font-mono text-[#D2691E]">{cutVolume.toFixed(2)} m³</div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">
                Material removed ({cutPct.toFixed(1)}%)
              </div>
            </div>
            <div className="p-4 bg-[#4169E1]/15 border border-[#4169E1]/40 rounded-lg">
              <div className="text-xs text-[#6495ED] mb-1">Fill Volume</div>
              <div className="text-2xl font-bold font-mono text-[#6495ED]">{fillVolume.toFixed(2)} m³</div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">
                Material added ({fillPct.toFixed(1)}%)
              </div>
            </div>
            <div className={`p-4 border rounded-lg ${netVolume >= 0 ? 'bg-amber-900/20 border-amber-800/30' : 'bg-blue-900/20 border-blue-800/30'}`}>
              <div className={`text-xs mb-1 ${netVolume >= 0 ? 'text-amber-400' : 'text-blue-400'}`}>Net Volume</div>
              <div className={`text-2xl font-bold font-mono ${netVolume >= 0 ? 'text-amber-400' : 'text-blue-400'}`}>
                {netVolume >= 0 ? '+' : ''}{netVolume.toFixed(2)} m³
              </div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">
                {netVolume >= 0 ? 'Cut dominant — surplus material' : 'Fill dominant — borrow needed'}
              </div>
            </div>
            <div className="p-4 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg">
              <div className="text-xs text-[var(--text-secondary)] mb-1">Area Overlap</div>
              <div className="text-2xl font-bold font-mono text-[var(--text-primary)]">{overlapArea?.toFixed(2)} m²</div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">
                Grid: {gridSpacing}m spacing
              </div>
            </div>
          </div>

          {/* Cut/Fill Bar */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
            <h3 className="text-lg font-semibold mb-4">Cut / Fill Balance</h3>
            <div className="relative h-12 rounded-lg overflow-hidden flex">
              {cutPct > 0 && (
                <div
                  className="flex items-center justify-center transition-all duration-500"
                  style={{
                    width: `${cutPct}%`,
                    backgroundColor: '#8B4513',
                    minWidth: cutVolume > 0 ? '40px' : '0',
                  }}
                >
                  <span className="text-white text-xs font-mono font-bold drop-shadow">
                    Cut {cutPct.toFixed(0)}%
                  </span>
                </div>
              )}
              {fillPct > 0 && (
                <div
                  className="flex items-center justify-center transition-all duration-500"
                  style={{
                    width: `${fillPct}%`,
                    backgroundColor: '#4169E1',
                    minWidth: fillVolume > 0 ? '40px' : '0',
                  }}
                >
                  <span className="text-white text-xs font-mono font-bold drop-shadow">
                    Fill {fillPct.toFixed(0)}%
                  </span>
                </div>
              )}
              {total === 0 && (
                <div className="w-full flex items-center justify-center bg-gray-600">
                  <span className="text-white text-xs">No volume</span>
                </div>
              )}
            </div>
            <div className="flex justify-between mt-2 text-xs text-[var(--text-muted)]">
              <span className="flex items-center gap-1">
                <span className="w-3 h-3 rounded-sm inline-block" style={{ backgroundColor: '#8B4513' }} />
                Cut (Survey A &gt; B)
              </span>
              <span className="flex items-center gap-1">
                <span className="w-3 h-3 rounded-sm inline-block" style={{ backgroundColor: '#4169E1' }} />
                Fill (Survey B &gt; A)
              </span>
            </div>
          </div>

          {/* Additional metrics */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {fillVolume > 0 && (
              <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Cut/Fill Ratio</div>
                <div className="text-xl font-bold font-mono text-[var(--text-primary)]">{(cutVolume! / fillVolume!).toFixed(3)}</div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  {Math.abs(cutVolume! / fillVolume! - 1) < 0.05
                    ? 'Nearly balanced — minimal import/export'
                    : cutVolume! / fillVolume! > 1
                      ? 'Cut surplus — export material needed'
                      : 'Fill deficit — import material needed'}
                </div>
              </div>
            )}
            {balancePoint !== null && (
              <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Balance Point (Datum)</div>
                <div className="text-xl font-bold font-mono text-[var(--text-primary)]">{balancePoint.toFixed(3)} m</div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Elevation where cut = fill
                </div>
              </div>
            )}
            <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
              <div className="text-xs text-[var(--text-secondary)] mb-1">Computation Method</div>
              <div className="text-xl font-bold font-mono text-[var(--text-primary)]">
                {method === 'tin' ? 'TIN' : 'IDW'}
              </div>
              <div className="text-xs text-[var(--text-muted)] mt-0.5">
                Grid spacing: {gridSpacing}m | {gridCells.length} cells evaluated
              </div>
            </div>
          </div>

          {/* Per-cell grid visualization */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold">Per-Cell Analysis Grid</h3>
              <button
                onClick={() => setShowGrid(!showGrid)}
                className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg text-xs hover:border-[var(--accent)] transition-colors"
              >
                {showGrid ? 'Hide Grid' : 'Show Grid'}
              </button>
            </div>

            {showGrid && gridCells.length > 0 && (
              <div className="overflow-x-auto">
                <svg
                  viewBox={`${gridBBox.minE} ${gridBBox.minN} ${gridBBox.maxE - gridBBox.minE} ${gridBBox.maxN - gridBBox.minN}`}
                  className="w-full border border-[var(--border-color)] rounded bg-[#1a1a1a]"
                  style={{ minHeight: 300, maxHeight: 600 }}
                >
                  {gridCells.map((cell, i) => {
                    const opacity = Math.min(1, (Math.abs(cell.diff) / maxAbsDiff) * 0.85 + 0.15);
                    let color: string;
                    if (cell.type === 'cut') color = `rgba(139, 69, 19, ${opacity})`;
                    else if (cell.type === 'fill') color = `rgba(65, 105, 225, ${opacity})`;
                    else color = `rgba(128, 128, 128, 0.15)`;

                    return (
                      <g key={`${cell}-${i}`}>
                        <rect
                          x={cell.easting}
                          y={cell.northing}
                          width={gridSpacing}
                          height={gridSpacing}
                          fill={color}
                          stroke="#333"
                          strokeWidth={0.5}
                        />
                      </g>
                    );
                  })}
                  {/* Scale reference */}
                  <rect
                    x={gridBBox.minE + 2}
                    y={gridBBox.minN + 2}
                    width={10 * gridSpacing}
                    height={5 * gridSpacing}
                    fill="none"
                    stroke="#fff"
                    strokeWidth={1}
                    rx={2}
                  />
                  <text
                    x={gridBBox.minE + 2 + 5 * gridSpacing}
                    y={gridBBox.minN + 2 + 5 * gridSpacing + 4}
                    fill="#fff"
                    fontSize={gridSpacing * 2}
                    textAnchor="middle"
                  >
                    {10 * gridSpacing}m
                  </text>
                </svg>

                {/* Legend */}
                <div className="flex items-center gap-6 mt-3 text-xs text-[var(--text-muted)] justify-center">
                  <div className="flex items-center gap-1.5">
                    <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: '#8B4513' }} />
                    <span>Cut (A higher)</span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: '#4169E1' }} />
                    <span>Fill (B higher)</span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: 'rgba(128, 128, 128, 0.15)', border: '1px solid #555' }} />
                    <span>No change</span>
                  </div>
                  <div className="flex items-center gap-1.5">
                    <span className="text-[var(--text-secondary)]">Opacity ∝ magnitude</span>
                  </div>
                </div>

                {/* Grid stats */}
                <div className="grid grid-cols-3 gap-3 mt-4">
                  <div className="p-3 bg-[var(--bg-tertiary)] rounded text-center">
                    <div className="text-xs text-[var(--text-muted)]">Cut Cells</div>
                    <div className="text-lg font-bold font-mono text-[#D2691E]">
                      {gridCells.filter(c => c.type === 'cut').length}
                    </div>
                  </div>
                  <div className="p-3 bg-[var(--bg-tertiary)] rounded text-center">
                    <div className="text-xs text-[var(--text-muted)]">Fill Cells</div>
                    <div className="text-lg font-bold font-mono text-[#6495ED]">
                      {gridCells.filter(c => c.type === 'fill').length}
                    </div>
                  </div>
                  <div className="p-3 bg-[var(--bg-tertiary)] rounded text-center">
                    <div className="text-xs text-[var(--text-muted)]">No Change</div>
                    <div className="text-lg font-bold font-mono text-[var(--text-secondary)]">
                      {gridCells.filter(c => c.type === 'none').length}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {!showGrid && gridCells.length > 0 && (
              <p className="text-sm text-[var(--text-secondary)]">
                Click &quot;Show Grid&quot; to display {gridCells.length} color-coded cells.
              </p>
            )}

            {gridCells.length === 0 && hasComputedRef.current && (
              <p className="text-sm text-[var(--text-muted)]">
                No grid cells were computed. Ensure both surveys have overlapping extents.
              </p>
            )}
          </div>
        </>
      )}

      {/* Not yet computed */}
      {cutVolume === null && computeErrors.length === 0 && (
        <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-12 text-center">
          <div className="text-4xl mb-3 opacity-40">[Chart]</div>
          <p className="text-[var(--text-secondary)]">
            Configure settings and click &quot;Compute Volume&quot; to see results.
          </p>
          <p className="text-sm text-[var(--text-muted)] mt-1">
            Load data for both Survey A and Survey B first.
          </p>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useMemo, useCallback, useRef } from 'react';
import { PageHeader } from '@/components/shared/PageHeader';
import {
  buildTINSurface,
  interpolateElevation,
  computeVolumeBetweenSurfaces,
  type SpotHeight,
  type TINSurface,
} from '@/lib/engine/contours';
import {
  surfaceCutFillVolumeGrid,
  type SurfacePoint,
  type SurfaceVolumeGridInput,
  type SurfaceVolumeGridResult,
} from '@/lib/engine/volume';
import { useLanguage } from '@/lib/i18n/LanguageContext'

// ─── Type conversions ────────────────────────────────────────────────────────

const toSurfacePoints = (spots: SpotHeight[]): SurfacePoint[] =>
  spots.map(p => ({ easting: p.easting, northing: p.northing, elevation: p.elevation }));

const toSpotHeights = (pts: { easting: number; northing: number; elevation: number }[]): SpotHeight[] =>
  pts.map((p, i) => ({ name: `P${i + 1}`, ...p }));

// ─── CSV / text parsing ─────────────────────────────────────────────────────

function detectDelimiter(text: string): string {
  const firstLine = text.trim().split('\n')[0] ?? '';
  const tabCount = (firstLine.match(/\t/g) || []).length;
  const commaCount = (firstLine.match(/,/g) || []).length;
  const semiCount = (firstLine.match(/;/g) || []).length;
  const spaceCount = (firstLine.match(/  +/g) || []).length;
  if (tabCount >= 2) return '\t';
  if (commaCount >= 2) return ',';
  if (semiCount >= 2) return ';';
  if (spaceCount >= 2) return '  ';
  return ',';
}

function parsePointData(text: string): { points: SurfacePoint[]; errors: string[] } {
  const errors: string[] = [];
  const lines = text.trim().split(/\r?\n/).filter(l => l.trim() && !l.trim().startsWith('#'));
  if (lines.length === 0) return { points: [], errors: ['No data rows found.'] };

  const delim = detectDelimiter(text);
  const points: SurfacePoint[] = [];
  let startIndex = 0;

  // Check if first line is a header
  const firstLine = lines[0].trim().toLowerCase();
  if (firstLine.includes('easting') || firstLine.includes('name') || firstLine.includes('point') || firstLine.includes('x')) {
    startIndex = 1;
  }

  for (let i = startIndex; i < lines.length; i++) {
    const parts = lines[i].trim().split(delim).map(s => s.trim()).filter(Boolean);
    // Try to handle multi-space delimiters
    const fields = parts.length >= 3 ? parts : lines[i].trim().split(/\s+/).map(s => s.trim()).filter(Boolean);
    if (fields.length < 3) { errors.push(`Row ${i + 1}: fewer than 3 fields`); continue; }

    const nameIdx = fields.length >= 4 ? (isNaN(Number(fields[0])) ? 0 : -1) : -1;
    const numericStart = nameIdx === 0 ? 1 : 0;

    const e = Number(fields[numericStart]);
    const n = Number(fields[numericStart + 1]);
    const z = Number(fields[numericStart + 2]);

    if (isNaN(e) || isNaN(n) || isNaN(z)) {
      errors.push(`Row ${i + 1}: non-numeric values`);
      continue;
    }
    points.push({ easting: e, northing: n, elevation: z });
  }

  return { points, errors };
}

// ─── Bounding box helpers ────────────────────────────────────────────────────

interface BBox {
  minE: number; maxE: number; minN: number; maxN: number;
}

function computeBBox(points: SurfacePoint[]): BBox {
  let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity;
  for (const p of points) {
    if (p.easting < minE) minE = p.easting;
    if (p.easting > maxE) maxE = p.easting;
    if (p.northing < minN) minN = p.northing;
    if (p.northing > maxN) maxN = p.northing;
  }
  return { minE, maxE, minN, maxN };
}

function bboxOverlap(a: BBox, b: BBox): BBox | null {
  const minE = Math.max(a.minE, b.minE);
  const maxE = Math.min(a.maxE, b.maxE);
  const minN = Math.max(a.minN, b.minN);
  const maxN = Math.min(a.maxN, b.maxN);
  if (maxE <= minE || maxN <= minN) return null;
  return { minE, maxE, minN, maxN };
}

function overlapPercent(a: BBox, b: BBox): number {
  const overlap = bboxOverlap(a, b);
  if (!overlap) return 0;
  const aArea = (a.maxE - a.minE) * (a.maxN - a.minN);
  const oArea = (overlap.maxE - overlap.minE) * (overlap.maxN - overlap.minN);
  return (oArea / aArea) * 100;
}

// ─── Demo data generators ────────────────────────────────────────────────────

function generateDemoA(): SurfacePoint[] {
  const points: SurfacePoint[] = [];
  const gridSize = 25;
  const spacing = 2;
  const centerE = 484600;
  const centerN = 9863100;
  const halfGrid = (gridSize * spacing) / 2;

  for (let row = 0; row < gridSize; row++) {
    for (let col = 0; col < gridSize; col++) {
      const e = centerE - halfGrid + col * spacing;
      const n = centerN - halfGrid + row * spacing;
      // Base elevation 120m with gentle sine wave slopes
      const dx = (e - centerE) / halfGrid;
      const dy = (n - centerN) / halfGrid;
      const z = 120 + 3 * Math.sin(dx * Math.PI) + 2 * Math.cos(dy * Math.PI) + 0.5 * Math.sin(dx * dy * Math.PI * 2);
      points.push({ easting: Math.round(e * 100) / 100, northing: Math.round(n * 100) / 100, elevation: Math.round(z * 1000) / 1000 });
    }
  }
  return points;
}

function generateDemoB(demoA: SurfacePoint[]): SurfacePoint[] {
  const centerE = 484600;
  const centerN = 9863100;

  return demoA.map(p => {
    const dx = p.easting - centerE;
    const dy = p.northing - centerN;
    let mod = 0;

    // Excavation pit: -5m depression in a 20×20m area (bottom-left quadrant)
    if (dx < 0 && dy < 0 && Math.abs(dx) <= 10 && Math.abs(dy) <= 10) {
      const r = Math.sqrt(dx * dx + dy * dy) / 10;
      mod -= 5 * Math.cos(r * Math.PI / 2); // Bowl shape
    }

    // Embankment: +3m mound in a 15×15m area (right-center)
    const ex = dx - 8;
    if (Math.abs(ex) <= 7.5 && Math.abs(dy) <= 7.5) {
      const r = Math.sqrt(ex * ex + dy * dy) / 7.5;
      mod += 3 * Math.cos(r * Math.PI / 2); // Dome shape
    }

    return { ...p, elevation: p.elevation + mod };
  });
}

// ─── Grid cell for visualization ────────────────────────────────────────────

interface GridCell {
  easting: number;
  northing: number;
  diff: number;
  type: 'cut' | 'fill' | 'none';
}

// ─── Balance point computation ──────────────────────────────────────────────

function computeBalancePoint(surface1: TINSurface, surface2: TINSurface, gridSpacing: number): number | null {
  const minE = Math.max(surface1.bounds.minE, surface2.bounds.minE);
  const maxE = Math.min(surface1.bounds.maxE, surface2.bounds.maxE);
  const minN = Math.max(surface1.bounds.minN, surface2.bounds.minN);
  const maxN = Math.min(surface1.bounds.maxN, surface2.bounds.maxN);
  if (minE >= maxE || minN >= maxN) return null;

  // Get elevation range from both surfaces
  const allElevs = [
    ...surface1.points.map(p => p.elevation),
    ...surface2.points.map(p => p.elevation),
  ];
  const minZ = Math.min(...allElevs);
  const maxZ = Math.max(...allElevs);
  const padding = (maxZ - minZ) * 0.1;
  let lo = minZ - padding;
  let hi = maxZ + padding;

  // Binary search for datum where cut = fill
  for (let iter = 0; iter < 64; iter++) {
    const mid = (lo + hi) / 2;
    let cut = 0;
    let fill = 0;
    const cellArea = gridSpacing * gridSpacing;

    for (let e = minE; e <= maxE; e += gridSpacing) {
      for (let n = minN; n <= maxN; n += gridSpacing) {
        const z1 = interpolateElevation(surface1, e, n);
        const z2 = interpolateElevation(surface2, e, n);
        if (z1 === null || z2 === null) continue;

        const diff1 = z1 - mid;
        const diff2 = z2 - mid;
        if (diff1 > 0) cut += diff1 * cellArea;
        else fill += -diff1 * cellArea;
        if (diff2 > 0) cut += diff2 * cellArea;
        else fill += -diff2 * cellArea;
      }
    }

    if (cut > fill) hi = mid;
    else lo = mid;
  }

  return (lo + hi) / 2;
}

// ─── Compute per-cell analysis grid ─────────────────────────────────────────

function computeGridCells(
  method: 'tin' | 'idw',
  surface1: TINSurface | null,
  surface2: TINSurface | null,
  surveyA: SurfacePoint[],
  surveyB: SurfacePoint[],
  gridSpacing: number
): { cells: GridCell[]; bbox: BBox } {
  const bboxA = computeBBox(surveyA);
  const bboxB = computeBBox(surveyB);
  const overlap = bboxOverlap(bboxA, bboxB);
  if (!overlap) return { cells: [], bbox: { minE: 0, maxE: 0, minN: 0, maxN: 0 } };

  const startE = Math.ceil(overlap.minE / gridSpacing) * gridSpacing;
  const startN = Math.ceil(overlap.minN / gridSpacing) * gridSpacing;
  const endE = Math.floor(overlap.maxE / gridSpacing) * gridSpacing;
  const endN = Math.floor(overlap.maxN / gridSpacing) * gridSpacing;

  const cells: GridCell[] = [];

  for (let e = startE; e <= endE; e += gridSpacing) {
    for (let n = startN; n <= endN; n += gridSpacing) {
      const x = e + gridSpacing / 2;
      const y = n + gridSpacing / 2;

      let z1: number | null = null;
      let z2: number | null = null;

      if (method === 'tin' && surface1 && surface2) {
        z1 = interpolateElevation(surface1, x, y);
        z2 = interpolateElevation(surface2, x, y);
      } else {
        // IDW fallback
        z1 = idwInterp(surveyA, x, y, 2, gridSpacing * 3);
        z2 = idwInterp(surveyB, x, y, 2, gridSpacing * 3);
      }

      if (z1 === null || z2 === null) continue;

      const diff = z1 - z2;
      cells.push({
        easting: e,
        northing: n,
        diff,
        type: diff > 0.001 ? 'cut' : diff < -0.001 ? 'fill' : 'none',
      });
    }
  }

  return { cells, bbox: overlap };
}

function idwInterp(points: SurfacePoint[], x: number, y: number, power: number, maxDist: number): number | null {
  let wSum = 0, wzSum = 0, nearestD2 = Infinity, nearestZ = 0;
  const maxD2 = maxDist * maxDist;
  for (const p of points) {
    const dx = p.easting - x, dy = p.northing - y;
    const d2 = dx * dx + dy * dy;
    if (d2 === 0) return p.elevation;
    if (d2 < nearestD2) { nearestD2 = d2; nearestZ = p.elevation; }
    if (d2 > maxD2) continue;
    const d = Math.sqrt(d2);
    const w = 1 / Math.pow(d, power);
    wSum += w;
    wzSum += w * p.elevation;
  }
  if (wSum > 0) return wzSum / wSum;
  if (nearestD2 < Infinity) return nearestZ;
  return null;
}

// ─── Main Page Component ────────────────────────────────────────────────────

type TabId = 'surveyA' | 'surveyB' | 'analysis' | 'export';

export default function VolumeComparisonPage() {
  const { t } = useLanguage()
  const [activeTab, setActiveTab] = useState<TabId>('surveyA');

  // Survey A state
  const [surveyAPoints, setSurveyAPoints] = useState<SurfacePoint[]>([]);
  const [surveyAText, setSurveyAText] = useState('');
  const [surveyAErrors, setSurveyAErrors] = useState<string[]>([]);

  // Survey B state
  const [surveyBPoints, setSurveyBPoints] = useState<SurfacePoint[]>([]);
  const [surveyBText, setSurveyBText] = useState('');
  const [surveyBErrors, setSurveyBErrors] = useState<string[]>([]);

  // Analysis state
  const [gridSpacing, setGridSpacing] = useState(1.0);
  const [method, setMethod] = useState<'tin' | 'idw'>('tin');
  const [computing, setComputing] = useState(false);
  const [computeErrors, setComputeErrors] = useState<string[]>([]);
  const [computeWarnings, setComputeWarnings] = useState<string[]>([]);
  const [cutVolume, setCutVolume] = useState<number | null>(null);
  const [fillVolume, setFillVolume] = useState<number | null>(null);
  const [netVolume, setNetVolume] = useState<number | null>(null);
  const [overlapArea, setOverlapArea] = useState<number | null>(null);
  const [balancePoint, setBalancePoint] = useState<number | null>(null);
  const [gridCells, setGridCells] = useState<GridCell[]>([]);
  const [gridBBox, setGridBBox] = useState<BBox>({ minE: 0, maxE: 0, minN: 0, maxN: 0 });
  const [showGrid, setShowGrid] = useState(false);
  const hasComputed = useRef(false);

  // File input refs
  const fileInputARef = useRef<HTMLInputElement>(null);
  const fileInputBRef = useRef<HTMLInputElement>(null);

  // ─── Computed bounding boxes ───────────────────────────────────────────

  const bboxA = useMemo(() => (surveyAPoints.length > 0 ? computeBBox(surveyAPoints) : null), [surveyAPoints]);
  const bboxB = useMemo(() => (surveyBPoints.length > 0 ? computeBBox(surveyBPoints) : null), [surveyBPoints]);

  const overlapBBox = useMemo(() => {
    if (!bboxA || !bboxB) return null;
    return bboxOverlap(bboxA, bboxB);
  }, [bboxA, bboxB]);

  const overlapPct = useMemo(() => {
    if (!bboxA || !bboxB) return 0;
    return overlapPercent(bboxA, bboxB);
  }, [bboxA, bboxB]);

  // ─── Data loading handlers ─────────────────────────────────────────────

  const handleLoadFromText = useCallback((text: string, survey: 'A' | 'B') => {
    const { points, errors } = parsePointData(text);
    if (survey === 'A') {
      setSurveyAPoints(points);
      setSurveyAErrors(errors);
    } else {
      setSurveyBPoints(points);
      setSurveyBErrors(errors);
    }
  }, []);

  const handleFileUpload = useCallback((file: File, survey: 'A' | 'B') => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      if (survey === 'A') {
        setSurveyAText(text);
        handleLoadFromText(text, 'A');
      } else {
        setSurveyBText(text);
        handleLoadFromText(text, 'B');
      }
    };
    reader.readAsText(file);
  }, [handleLoadFromText]);

  const handleLoadDemoA = useCallback(() => {
    const points = generateDemoA();
    setSurveyAPoints(points);
    setSurveyAErrors([]);
    // Generate a CSV preview for the textarea
    const lines = ['Name,Easting,Northing,Elevation'];
    points.forEach((p, i) => lines.push(`P${i + 1},${p.easting},${p.northing},${p.elevation}`));
    setSurveyAText(lines.slice(0, 20).join('\n') + `\n... (${points.length} total points)`);
  }, []);

  const handleLoadDemoB = useCallback(() => {
    const demoA = generateDemoA();
    const points = generateDemoB(demoA);
    setSurveyBPoints(points);
    setSurveyBErrors([]);
    const lines = ['Name,Easting,Northing,Elevation'];
    points.forEach((p, i) => lines.push(`P${i + 1},${p.easting},${p.northing},${p.elevation}`));
    setSurveyBText(lines.slice(0, 20).join('\n') + `\n... (${points.length} total points)`);
  }, []);

  const clearSurvey = useCallback((survey: 'A' | 'B') => {
    if (survey === 'A') {
      setSurveyAPoints([]);
      setSurveyAText('');
      setSurveyAErrors([]);
    } else {
      setSurveyBPoints([]);
      setSurveyBText('');
      setSurveyBErrors([]);
    }
  }, []);

  // ─── Volume computation ───────────────────────────────────────────────

  const handleCompute = useCallback(() => {
    setComputing(true);
    setComputeErrors([]);
    setComputeWarnings([]);

    try {
      if (surveyAPoints.length < 3) {
        setComputeErrors(['Survey A requires at least 3 points.']);
        setComputing(false);
        return;
      }
      if (surveyBPoints.length < 3) {
        setComputeErrors(['Survey B requires at least 3 points.']);
        setComputing(false);
        return;
      }
      if (!overlapBBox) {
        setComputeErrors(['Survey extents do not overlap. Cannot compute volume.']);
        setComputing(false);
        return;
      }

      const spacing = Math.max(0.1, Math.min(5.0, gridSpacing));
      const oArea = (overlapBBox.maxE - overlapBBox.minE) * (overlapBBox.maxN - overlapBBox.minN);

      if (method === 'tin') {
        const spotsA = toSpotHeights(surveyAPoints);
        const spotsB = toSpotHeights(surveyBPoints);
        const tinA = buildTINSurface(spotsA);
        const tinB = buildTINSurface(spotsB);

        if (tinA.triangles.length === 0) {
          setComputeErrors(['Survey A: TIN triangulation failed (possibly collinear points).']);
          setComputing(false);
          return;
        }
        if (tinB.triangles.length === 0) {
          setComputeErrors(['Survey B: TIN triangulation failed (possibly collinear points).']);
          setComputing(false);
          return;
        }

        const result = computeVolumeBetweenSurfaces(tinA, tinB, spacing);
        setCutVolume(result.cut);
        setFillVolume(result.fill);
        setNetVolume(result.net);
        setOverlapArea(oArea);

        // Compute balance point
        const bp = computeBalancePoint(tinA, tinB, spacing);
        setBalancePoint(bp);

        // Compute grid cells
        const grid = computeGridCells('tin', tinA, tinB, surveyAPoints, surveyBPoints, spacing);
        setGridCells(grid.cells);
        setGridBBox(grid.bbox);
      } else {
        const input: SurfaceVolumeGridInput = {
          existing: surveyAPoints,
          design: surveyBPoints,
          gridSpacing: spacing,
          power: 2,
        };
        const result: SurfaceVolumeGridResult = surfaceCutFillVolumeGrid(input);
        setCutVolume(result.cutVolume);
        setFillVolume(result.fillVolume);
        setNetVolume(result.netVolume);
        setOverlapArea(oArea);
        setComputeWarnings(result.warnings);
        setBalancePoint(null);

        // Compute grid cells for visualization
        const spotsA = toSpotHeights(surveyAPoints);
        const spotsB = toSpotHeights(surveyBPoints);
        const tinA = buildTINSurface(spotsA);
        const tinB = buildTINSurface(spotsB);
        const grid = computeGridCells('idw', tinA, tinB, surveyAPoints, surveyBPoints, spacing);
        setGridCells(grid.cells);
        setGridBBox(grid.bbox);
      }

      hasComputed.current = true;
    } catch (err: unknown) {
      setComputeErrors([(err as Error).message || 'An unknown error occurred during computation.']);
    } finally {
      setComputing(false);
    }
  }, [surveyAPoints, surveyBPoints, method, gridSpacing, overlapBBox]);

  // ─── Export functions ───────────────────────────────────────────────────

  const exportResultsCSV = useCallback(() => {
    if (cutVolume === null || fillVolume === null || netVolume === null) return;
    const now = new Date().toISOString();
    const header = [
      'Volume Comparison Report',
      `Generated: ${now}`,
      `Method: ${method === 'tin' ? 'TIN Interpolation' : 'IDW Grid'}`,
      `Grid Spacing: ${gridSpacing}m`,
      '',
      'Survey A Points,Count',
      `${surveyAPoints.length}`,
      `Survey A BBox,MinE,${bboxA?.minE ?? ''},MaxE,${bboxA?.maxE ?? ''},MinN,${bboxA?.minN ?? ''},MaxN,${bboxA?.maxN ?? ''}`,
      '',
      'Survey B Points,Count',
      `${surveyBPoints.length}`,
      `Survey B BBox,MinE,${bboxB?.minE ?? ''},MaxE,${bboxB?.maxE ?? ''},MinN,${bboxB?.minN ?? ''},MaxN,${bboxB?.maxN ?? ''}`,
      '',
      'Volume Results',
      `Cut Volume (m³),${cutVolume.toFixed(3)}`,
      `Fill Volume (m³),${fillVolume.toFixed(3)}`,
      `Net Volume (m³),${netVolume.toFixed(3)}`,
      `Overlap Area (m²),${overlapArea?.toFixed(3) ?? ''}`,
      `Cut/Fill Ratio,${fillVolume > 0 ? (cutVolume / fillVolume).toFixed(3) : 'N/A'}`,
      `Balance Point (m),${balancePoint !== null ? balancePoint.toFixed(3) : 'N/A'}`,
    ];
    const csv = header.join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'volume_comparison_report.csv';
    a.click();
    URL.revokeObjectURL(url);
  }, [cutVolume, fillVolume, netVolume, method, gridSpacing, surveyAPoints, surveyBPoints, bboxA, bboxB, overlapArea, balancePoint]);

  const exportGridCSV = useCallback(() => {
    if (gridCells.length === 0) return;
    const header = 'Easting,Northing,Difference (m),Type';
    const rows = gridCells.map(c =>
      `${c.easting},${c.northing},${c.diff.toFixed(4)},${c.type}`
    );
    const csv = [header, ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'cut_fill_grid.csv';
    a.click();
    URL.revokeObjectURL(url);
  }, [gridCells]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  // ─── CSS classes ────────────────────────────────────────────────────────

  const inputClass = 'w-full px-4 py-3 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg text-[var(--text-primary)] focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)] outline-none transition-colors';

  const tabs: { id: TabId; label: string; badge?: string }[] = [
    { id: 'surveyA', label: 'Survey A (Existing)', badge: surveyAPoints.length > 0 ? `${surveyAPoints.length} pts` : undefined },
    { id: 'surveyB', label: 'Survey B (As-Built)', badge: surveyBPoints.length > 0 ? `${surveyBPoints.length} pts` : undefined },
    { id: 'analysis', label: 'Analysis Results' },
    { id: 'export', label: 'Export' },
  ];

  // ─── Render helpers ────────────────────────────────────────────────────

  const renderSurveyImport = (survey: 'A' | 'B') => {
    const points = survey === 'A' ? surveyAPoints : surveyBPoints;
    const text = survey === 'A' ? surveyAText : surveyBText;
    const setText = survey === 'A' ? setSurveyAText : setSurveyBText;
    const errors = survey === 'A' ? surveyAErrors : surveyBErrors;
    const bbox = survey === 'A' ? bboxA : bboxB;
    const fileRef = survey === 'A' ? fileInputARef : fileInputBRef;

    const elevations = points.map(p => p.elevation);
    const minElev = elevations.length > 0 ? Math.min(...elevations) : 0;
    const maxElev = elevations.length > 0 ? Math.max(...elevations) : 0;

    return (
      <div className="space-y-6">
        {/* File upload */}
        <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold">
              Import {survey === 'A' ? 'Survey A' : 'Survey B'} Point Data
            </h3>
            <div className="flex gap-2">
              <button
                onClick={() => fileRef.current?.click()}
                className="px-3 py-2 bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg text-sm hover:border-[var(--accent)] hover:text-[var(--accent)] transition-colors"
              >
                Upload File (CSV/TXT/XYZ)
              </button>
              <input
                ref={fileRef}
                type="file"
                accept=".csv,.txt,.xyz"
                className="hidden"
                onChange={e => {
                  const file = e.target.files?.[0];
                  if (file) handleFileUpload(file, survey);
                }}
              />
              <button
                onClick={() => survey === 'A' ? handleLoadDemoA() : handleLoadDemoB()}
                className="px-3 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium hover:opacity-90 transition-opacity"
              >
                Load Demo {survey}
              </button>
            </div>
          </div>

          <p className="text-sm text-[var(--text-secondary)] mb-3">
            Paste point data below or upload a file. Expected columns: <span className="font-mono text-[var(--text-primary)]">Name, Easting, Northing, Elevation</span> (or just 3 numeric columns: E, N, Z). Auto-detects comma, tab, semicolon, or space delimiters.
          </p>

          <textarea
            className={inputClass}
            rows={10}
            placeholder={`Name,Easting,Northing,Elevation\nP1,484575.00,9863075.00,121.500\nP2,484577.00,9863075.00,121.350\n...`}
            value={text}
            onChange={e => setText(e.target.value)}
          />

          <div className="flex gap-3 mt-3">
            <button
              onClick={() => handleLoadFromText(text, survey)}
              className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium hover:opacity-90 transition-opacity"
            >
              Parse Data
            </button>
            <button
              onClick={() => clearSurvey(survey)}
              className="px-4 py-2 bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg text-sm hover:text-red-400 transition-colors"
            >
              Clear
            </button>
          </div>

          {errors.length > 0 && (
            <div className="mt-3 p-3 bg-red-900/20 border border-red-800/30 rounded-lg">
              <h4 className="text-sm font-medium text-red-400 mb-1">Parse Errors</h4>
              <ul className="text-xs text-red-300/80 space-y-0.5">
                {errors.map((err, i) => <li key={`${err}-${i}`}>{err}</li>)}
              </ul>
            </div>
          )}
        </div>

        {/* Stats panel */}
        {points.length > 0 && bbox && (
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
            <h3 className="text-lg font-semibold mb-4">Survey {survey} Statistics</h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="p-4 bg-[var(--bg-tertiary)] rounded">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Point Count</div>
                <div className="text-2xl font-bold font-mono text-[var(--text-primary)]">{points.length}</div>
              </div>
              <div className="p-4 bg-[var(--bg-tertiary)] rounded">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Elevation Range</div>
                <div className="text-lg font-bold font-mono text-[var(--text-primary)]">
                  {minElev.toFixed(1)} — {maxElev.toFixed(1)} m
                </div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">Δ = {(maxElev - minElev).toFixed(2)} m</div>
              </div>
              <div className="p-4 bg-[var(--bg-tertiary)] rounded">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Easting Range</div>
                <div className="text-sm font-mono text-[var(--text-primary)]">
                  {bbox.minE.toFixed(1)} — {bbox.maxE.toFixed(1)}
                </div>
                <div className="text-xs text-[var(--text-muted)]">Width: {(bbox.maxE - bbox.minE).toFixed(1)} m</div>
              </div>
              <div className="p-4 bg-[var(--bg-tertiary)] rounded">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Northing Range</div>
                <div className="text-sm font-mono text-[var(--text-primary)]">
                  {bbox.minN.toFixed(1)} — {bbox.maxN.toFixed(1)}
                </div>
                <div className="text-xs text-[var(--text-muted)]">Height: {(bbox.maxN - bbox.minN).toFixed(1)} m</div>
              </div>
            </div>

            {/* Overlap indicator for Survey B */}
            {survey === 'B' && bboxA && overlapBBox && (
              <div className={`mt-4 p-4 rounded-lg border ${overlapPct > 50 ? 'bg-emerald-900/20 border-emerald-800/30' : overlapPct > 10 ? 'bg-amber-900/20 border-amber-800/30' : 'bg-red-900/20 border-red-800/30'}`}>
                <div className="flex items-center justify-between">
                  <div>
                    <div className="text-sm font-medium">Overlap with Survey A</div>
                    <div className="text-xs text-[var(--text-muted)]">
                      ({overlapBBox.minE.toFixed(1)}, {overlapBBox.minN.toFixed(1)}) to ({overlapBBox.maxE.toFixed(1)}, {overlapBBox.maxN.toFixed(1)})
                    </div>
                  </div>
                  <div className={`text-2xl font-bold font-mono ${overlapPct > 50 ? 'text-emerald-400' : overlapPct > 10 ? 'text-amber-400' : 'text-red-400'}`}>
                    {overlapPct.toFixed(1)}%
                  </div>
                </div>
              </div>
            )}

            {/* Point preview table */}
            <div className="mt-4">
              <h4 className="text-sm font-medium text-[var(--text-secondary)] mb-2">
                Point Preview (first 10 of {points.length})
              </h4>
              <div className="overflow-x-auto max-h-64">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-[var(--text-muted)] border-b border-[var(--border-color)]">
                      <th className="text-left py-1.5 px-2">#</th>
                      <th className="text-right py-1.5 px-2">Easting</th>
                      <th className="text-right py-1.5 px-2">Northing</th>
                      <th className="text-right py-1.5 px-2">Elevation</th>
                    </tr>
                  </thead>
                  <tbody>
                    {points.slice(0, 10).map((p, i) => (
                      <tr key={`${p}-${i}`} className="border-b border-[var(--border-color)]/30">
                        <td className="py-1.5 px-2 text-[var(--text-muted)]">{i + 1}</td>
                        <td className="py-1.5 px-2 text-right font-mono">{p.easting.toFixed(2)}</td>
                        <td className="py-1.5 px-2 text-right font-mono">{p.northing.toFixed(2)}</td>
                        <td className="py-1.5 px-2 text-right font-mono">{p.elevation.toFixed(3)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {points.length === 0 && (
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-12 text-center">
            <div className="text-4xl mb-3 opacity-40">[Compass]</div>
            <p className="text-[var(--text-secondary)]">
              No data loaded for Survey {survey}.
            </p>
            <p className="text-sm text-[var(--text-muted)] mt-1">
              Upload a CSV/TXT/XYZ file, paste data, or load demo data.
            </p>
          </div>
        )}
      </div>
    );
  };

  const renderAnalysis = () => {
    const total = (cutVolume ?? 0) + (fillVolume ?? 0);
    const cutPct = total > 0 ? ((cutVolume ?? 0) / total) * 100 : 0;
    const fillPct = total > 0 ? ((fillVolume ?? 0) / total) * 100 : 0;
    const maxAbsDiff = gridCells.length > 0 ? Math.max(...gridCells.map(c => Math.abs(c.diff)), 0.001) : 1;

    return (
      <div className="space-y-6">
        {/* Configuration panel */}
        <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
          <h3 className="text-lg font-semibold mb-4">Computation Settings</h3>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
            <div>
              <label className="block text-sm text-[var(--text-secondary)] mb-2" htmlFor="grid-spacing-m">Grid Spacing (m)</label>
              <input id="grid-spacing-m" aria-label="Grid Spacing (m)"
                type="number"
                min={0.1}
                max={5.0}
                step={0.1}
                value={gridSpacing}
                onChange={e => setGridSpacing(Math.max(0.1, Math.min(5.0, Number(e.target.value))))}
                className={inputClass}
              />
              <p className="text-xs text-[var(--text-muted)] mt-1">Range: 0.1 — 5.0 m (default: 1.0)</p>
            </div>
            <div>
              <div className="block text-sm text-[var(--text-secondary)] mb-2">Method</div>
              <div className="flex gap-2">
                <button
                  onClick={() => setMethod('tin')}
                  className={`flex-1 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${method === 'tin' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)]'}`}
                >
                  TIN Interpolation
                </button>
                <button
                  onClick={() => setMethod('idw')}
                  className={`flex-1 px-4 py-3 rounded-lg text-sm font-medium transition-colors ${method === 'idw' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-card)] border border-[var(--border-color)] text-[var(--text-secondary)]'}`}
                >
                  IDW Grid
                </button>
              </div>
              <p className="text-xs text-[var(--text-muted)] mt-1">
                {method === 'tin' ? 'Delaunay TIN with barycentric interpolation' : 'Inverse Distance Weighting (power=2)'}
              </p>
            </div>
            <div>
              <button
                onClick={handleCompute}
                disabled={computing || surveyAPoints.length < 3 || surveyBPoints.length < 3 || !overlapBBox}
                className="w-full px-4 py-3 bg-[var(--accent)] text-black rounded-lg text-sm font-bold hover:opacity-90 transition-opacity disabled:opacity-40 disabled:cursor-not-allowed"
              >
                {computing ? 'Computing...' : 'Compute Volume'}
              </button>
              {!overlapBBox && surveyAPoints.length >= 3 && surveyBPoints.length >= 3 && (
                <p className="text-xs text-red-400 mt-1">Surveys do not overlap.</p>
              )}
            </div>
          </div>
        </div>

        {/* Errors */}
        {computeErrors.length > 0 && (
          <div className="p-4 bg-red-900/20 border border-red-800/30 rounded-lg">
            <h4 className="text-sm font-medium text-red-400 mb-1">Computation Errors</h4>
            <ul className="text-xs text-red-300/80 space-y-0.5">
              {computeErrors.map((err, i) => <li key={`${err}-${i}`}>{err}</li>)}
            </ul>
          </div>
        )}

        {/* Warnings */}
        {computeWarnings.length > 0 && (
          <div className="p-4 bg-amber-900/20 border border-amber-800/30 rounded-lg">
            <h4 className="text-sm font-medium text-amber-400 mb-1">Warnings</h4>
            <ul className="text-xs text-amber-300/80 space-y-0.5">
              {computeWarnings.map((w, i) => <li key={`${w}-${i}`}>{w}</li>)}
            </ul>
          </div>
        )}

        {/* Results */}
        {cutVolume !== null && fillVolume !== null && netVolume !== null && (
          <>
            {/* Volume Summary Cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="p-4 bg-[#8B4513]/15 border border-[#8B4513]/40 rounded-lg">
                <div className="text-xs text-[#D2691E] mb-1">Cut Volume</div>
                <div className="text-2xl font-bold font-mono text-[#D2691E]">{cutVolume.toFixed(2)} m³</div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Material removed ({cutPct.toFixed(1)}%)
                </div>
              </div>
              <div className="p-4 bg-[#4169E1]/15 border border-[#4169E1]/40 rounded-lg">
                <div className="text-xs text-[#6495ED] mb-1">Fill Volume</div>
                <div className="text-2xl font-bold font-mono text-[#6495ED]">{fillVolume.toFixed(2)} m³</div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Material added ({fillPct.toFixed(1)}%)
                </div>
              </div>
              <div className={`p-4 border rounded-lg ${netVolume >= 0 ? 'bg-amber-900/20 border-amber-800/30' : 'bg-blue-900/20 border-blue-800/30'}`}>
                <div className={`text-xs mb-1 ${netVolume >= 0 ? 'text-amber-400' : 'text-blue-400'}`}>Net Volume</div>
                <div className={`text-2xl font-bold font-mono ${netVolume >= 0 ? 'text-amber-400' : 'text-blue-400'}`}>
                  {netVolume >= 0 ? '+' : ''}{netVolume.toFixed(2)} m³
                </div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  {netVolume >= 0 ? 'Cut dominant — surplus material' : 'Fill dominant — borrow needed'}
                </div>
              </div>
              <div className="p-4 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Area Overlap</div>
                <div className="text-2xl font-bold font-mono text-[var(--text-primary)]">{overlapArea?.toFixed(2)} m²</div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Grid: {gridSpacing}m spacing
                </div>
              </div>
            </div>

            {/* Cut/Fill Bar */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
              <h3 className="text-lg font-semibold mb-4">Cut / Fill Balance</h3>
              <div className="relative h-12 rounded-lg overflow-hidden flex">
                {cutPct > 0 && (
                  <div
                    className="flex items-center justify-center transition-all duration-500"
                    style={{
                      width: `${cutPct}%`,
                      backgroundColor: '#8B4513',
                      minWidth: cutVolume > 0 ? '40px' : '0',
                    }}
                  >
                    <span className="text-white text-xs font-mono font-bold drop-shadow">
                      Cut {cutPct.toFixed(0)}%
                    </span>
                  </div>
                )}
                {fillPct > 0 && (
                  <div
                    className="flex items-center justify-center transition-all duration-500"
                    style={{
                      width: `${fillPct}%`,
                      backgroundColor: '#4169E1',
                      minWidth: fillVolume > 0 ? '40px' : '0',
                    }}
                  >
                    <span className="text-white text-xs font-mono font-bold drop-shadow">
                      Fill {fillPct.toFixed(0)}%
                    </span>
                  </div>
                )}
                {total === 0 && (
                  <div className="w-full flex items-center justify-center bg-gray-600">
                    <span className="text-white text-xs">No volume</span>
                  </div>
                )}
              </div>
              <div className="flex justify-between mt-2 text-xs text-[var(--text-muted)]">
                <span className="flex items-center gap-1">
                  <span className="w-3 h-3 rounded-sm inline-block" style={{ backgroundColor: '#8B4513' }} />
                  Cut (Survey A &gt; B)
                </span>
                <span className="flex items-center gap-1">
                  <span className="w-3 h-3 rounded-sm inline-block" style={{ backgroundColor: '#4169E1' }} />
                  Fill (Survey B &gt; A)
                </span>
              </div>
            </div>

            {/* Additional metrics */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {fillVolume > 0 && (
                <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                  <div className="text-xs text-[var(--text-secondary)] mb-1">Cut/Fill Ratio</div>
                  <div className="text-xl font-bold font-mono text-[var(--text-primary)]">{(cutVolume / fillVolume).toFixed(3)}</div>
                  <div className="text-xs text-[var(--text-muted)] mt-0.5">
                    {Math.abs(cutVolume / fillVolume - 1) < 0.05
                      ? 'Nearly balanced — minimal import/export'
                      : cutVolume / fillVolume > 1
                        ? 'Cut surplus — export material needed'
                        : 'Fill deficit — import material needed'}
                  </div>
                </div>
              )}
              {balancePoint !== null && (
                <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                  <div className="text-xs text-[var(--text-secondary)] mb-1">Balance Point (Datum)</div>
                  <div className="text-xl font-bold font-mono text-[var(--text-primary)]">{balancePoint.toFixed(3)} m</div>
                  <div className="text-xs text-[var(--text-muted)] mt-0.5">
                    Elevation where cut = fill
                  </div>
                </div>
              )}
              <div className="p-4 bg-[var(--bg-tertiary)] rounded border border-[var(--border-color)]">
                <div className="text-xs text-[var(--text-secondary)] mb-1">Computation Method</div>
                <div className="text-xl font-bold font-mono text-[var(--text-primary)]">
                  {method === 'tin' ? 'TIN' : 'IDW'}
                </div>
                <div className="text-xs text-[var(--text-muted)] mt-0.5">
                  Grid spacing: {gridSpacing}m | {gridCells.length} cells evaluated
                </div>
              </div>
            </div>

            {/* Per-cell grid visualization */}
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold">Per-Cell Analysis Grid</h3>
                <button
                  onClick={() => setShowGrid(!showGrid)}
                  className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[var(--text-secondary)] rounded-lg text-xs hover:border-[var(--accent)] transition-colors"
                >
                  {showGrid ? 'Hide Grid' : 'Show Grid'}
                </button>
              </div>

              {showGrid && gridCells.length > 0 && (
                <div className="overflow-x-auto">
                  <svg
                    viewBox={`${gridBBox.minE} ${gridBBox.minN} ${gridBBox.maxE - gridBBox.minE} ${gridBBox.maxN - gridBBox.minN}`}
                    className="w-full border border-[var(--border-color)] rounded bg-[#1a1a1a]"
                    style={{ minHeight: 300, maxHeight: 600 }}
                  >
                    {gridCells.map((cell, i) => {
                      const opacity = Math.min(1, (Math.abs(cell.diff) / maxAbsDiff) * 0.85 + 0.15);
                      let color: string;
                      if (cell.type === 'cut') color = `rgba(139, 69, 19, ${opacity})`;
                      else if (cell.type === 'fill') color = `rgba(65, 105, 225, ${opacity})`;
                      else color = `rgba(128, 128, 128, 0.15)`;

                      return (
                        <g key={`${cell}-${i}`}>
                          <rect
                            x={cell.easting}
                            y={cell.northing}
                            width={gridSpacing}
                            height={gridSpacing}
                            fill={color}
                            stroke="#333"
                            strokeWidth={0.5}
                          />
                        </g>
                      );
                    })}
                    {/* Scale reference */}
                    <rect
                      x={gridBBox.minE + 2}
                      y={gridBBox.minN + 2}
                      width={10 * gridSpacing}
                      height={5 * gridSpacing}
                      fill="none"
                      stroke="#fff"
                      strokeWidth={1}
                      rx={2}
                    />
                    <text
                      x={gridBBox.minE + 2 + 5 * gridSpacing}
                      y={gridBBox.minN + 2 + 5 * gridSpacing + 4}
                      fill="#fff"
                      fontSize={gridSpacing * 2}
                      textAnchor="middle"
                    >
                      {10 * gridSpacing}m
                    </text>
                  </svg>

                  {/* Legend */}
                  <div className="flex items-center gap-6 mt-3 text-xs text-[var(--text-muted)] justify-center">
                    <div className="flex items-center gap-1.5">
                      <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: '#8B4513' }} />
                      <span>Cut (A higher)</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: '#4169E1' }} />
                      <span>Fill (B higher)</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <span className="w-4 h-4 rounded-sm" style={{ backgroundColor: 'rgba(128, 128, 128, 0.15)', border: '1px solid #555' }} />
                      <span>No change</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <span className="text-[var(--text-secondary)]">Opacity ∝ magnitude</span>
                    </div>
                  </div>

                  {/* Grid stats */}
                  <div className="grid grid-cols-3 gap-3 mt-4">
                    <div className="p-3 bg-[var(--bg-tertiary)] rounded text-center">
