'use client';

/**
 * Integrated Topographic Survey Pipeline
 *
 * AUDIT FIX (2026-07-03): Previously a surveyor had to hop between 4-5
 * separate tool pages to produce a topographic map. This page provides
 * a single guided workflow that chains:
 *   1. Import field data (CSV / project points)
 *   2. Generate contours (TIN + marching triangles)
 *   3. Analyze slope (optional)
 *   4. Compute volumes (optional)
 *   5. Generate cross-sections (optional)
 *   6. Auto-draw topo plan (feature codes → DXF)
 *   7. Export (DXF / Shapefile / GeoJSON / KML)
 *
 * Each step links to the full-featured tool page for advanced options,
 * but the surveyor can see the whole pipeline in one place and track
 * progress.
 */

import { useState, useEffect } from 'react'
import Link from 'next/link'
import {
  Upload, Mountain, TrendingUp, Box, Scissors, FileCode, Download,
  CheckCircle2, Circle, ArrowRight, Loader2,
} from 'lucide-react'
import { PageHeader } from '@/components/shared/PageHeader'

interface PipelineStep {
  id: string
  number: number
  title: string
  description: string
  href: string
  icon: typeof Upload
  optional?: boolean
  status: string
}

const PIPELINE_STEPS: PipelineStep[] = [
  {
    id: 'import',
    number: 1,
    title: 'Import Field Data',
    description: 'Upload total station CSV, GNSS RINEX, GSI, RW5, or point cloud (LAS/PLY). Or load points from an existing project.',
    href: '/import',
    icon: Upload,
    status: 'pending' as const,
  },
  {
    id: 'contours',
    number: 2,
    title: 'Generate Contours',
    description: 'Delaunay TIN + marching-triangles contour generation. Set interval, add breaklines, export DXF/SVG/CSV/GeoJSON.',
    href: '/tools/contour-generator',
    icon: Mountain,
    status: 'pending' as const,
  },
  {
    id: 'slope',
    number: 3,
    title: 'Slope Analysis',
    description: 'IDW grid + Horn\'s method. Aspect, KENHA road classification, balance-point binary search.',
    href: '/tools/slope-analysis',
    icon: TrendingUp,
    status: 'pending' as const,
    optional: true,
  },
  {
    id: 'volumes',
    number: 4,
    title: 'Volume Computation',
    description: 'End-area, prismoidal, grid, or TIN-vs-TIN. Cut/fill volumes with mass-haul diagrams.',
    href: '/tools/volume-comparison',
    icon: Box,
    status: 'pending' as const,
    optional: true,
  },
  {
    id: 'sections',
    number: 5,
    title: 'Cross-Sections',
    description: 'TIN sampling along centerline at chainage intervals. CSV/DXF/PDF output.',
    href: '/tools/cross-sections',
    icon: Scissors,
    status: 'pending' as const,
    optional: true,
  },
  {
    id: 'drawing',
    number: 6,
    title: 'Topo Plan Drawing',
    description: 'Auto-generate DXF with Survey of Kenya feature codes, spot heights, north arrow, scale bar, title block.',
    href: '/tools/topo-drawing',
    icon: FileCode,
    status: 'pending' as const,
  },
  {
    id: 'export',
    number: 7,
    title: 'Export',
    description: 'DXF (AutoCAD/Civil 3D), Shapefile (QGIS/ArcGIS), GeoJSON, KML, LandXML.',
    href: '/tools/gis-export',
    icon: Download,
    status: 'pending' as const,
  },
]

export default function TopographicWorkflowPage() {
  const [steps, setSteps] = useState<PipelineStep[]>(PIPELINE_STEPS)
  const [projectId, setProjectId] = useState<string | null>(null)

  // Load progress from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('metardu_topo_pipeline')
    if (saved) {
      try {
        const data = JSON.parse(saved)
        if (data.steps) {
          setSteps(prev => prev.map(s => {
            const savedStep = data.steps.find((ss: PipelineStep) => ss.id === s.id)
            return savedStep ? { ...s, status: savedStep.status } : s
          }))
        }
        if (data.projectId) setProjectId(data.projectId)
      } catch { /* ignore */ }
    }
  }, [])

  const saveProgress = (newSteps: PipelineStep[]) => {
    localStorage.setItem('metardu_topo_pipeline', JSON.stringify({ steps: newSteps, projectId }))
  }

  const toggleStepDone = (id: string) => {
    const newSteps: PipelineStep[] = steps.map(s =>
      s.id === id
        ? { ...s, status: s.status === 'done' ? 'pending' as const : 'done' as const }
        : s
    )
    setSteps(newSteps)
    saveProgress(newSteps)
  }

  const completedCount = steps.filter(s => s.status === 'done').length
  const requiredSteps = steps.filter(s => !s.optional)
  const requiredCompleted = requiredSteps.filter(s => s.status === 'done').length
  const progressPct = Math.round((completedCount / steps.length) * 100)

  return (
    <div className="max-w-5xl mx-auto px-4 md:px-6 py-8">
      <PageHeader
        title="Topographic Survey Pipeline"
        subtitle="Complete workflow: field data → contours → analysis → topo plan → export"
        reference="Survey Act Cap. 299 | RDM 1.1 | Survey Regulations 1994"
      />

      {/* Progress bar */}
      <div className="mb-8">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-[var(--text-secondary)]">
            {completedCount} of {steps.length} steps complete ({requiredCompleted}/{requiredSteps.length} required)
          </span>
          <span className="text-sm font-bold text-[var(--accent)]">{progressPct}%</span>
        </div>
        <div className="w-full bg-[var(--bg-tertiary)] rounded-full h-2.5 overflow-hidden">
          <div
            className="bg-[var(--accent)] h-2.5 rounded-full transition-all duration-500"
            style={{ width: `${progressPct}%` }}
          />
        </div>
      </div>

      {/* Pipeline steps */}
      <div className="space-y-3">
        {steps.map((step, index) => {
          const Icon = step.icon
          const isDone = step.status === 'done'
          const isLast = index === steps.length - 1

          return (
            <div key={step.id}>
              <div
                className={`flex items-start gap-4 p-4 rounded-xl border transition-all ${
                  isDone
                    ? 'bg-[var(--accent)]/5 border-[var(--accent)]/30'
                    : 'bg-[var(--bg-card)] border-[var(--border-color)] hover:border-[var(--accent)]/20'
                }`}
              >
                {/* Step number / checkmark */}
                <button
                  onClick={() => toggleStepDone(step.id)}
                  className="mt-0.5 shrink-0"
                  title={isDone ? 'Mark as not done' : 'Mark as done'}
                >
                  {isDone ? (
                    <CheckCircle2 className="w-6 h-6 text-[var(--accent)]" />
                  ) : (
                    <Circle className="w-6 h-6 text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors" />
                  )}
                </button>

                {/* Icon */}
                <div className={`w-10 h-10 rounded-lg flex items-center justify-center shrink-0 ${
                  isDone ? 'bg-[var(--accent)]/15' : 'bg-[var(--bg-tertiary)]'
                }`}>
                  <Icon className={`w-5 h-5 ${isDone ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'}`} />
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className={`font-semibold text-sm ${isDone ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>
                      {step.number}. {step.title}
                    </h3>
                    {step.optional && (
                      <span className="text-[10px] px-1.5 py-0.5 rounded bg-[var(--bg-tertiary)] text-[var(--text-muted)]">
                        optional
                      </span>
                    )}
                  </div>
                  <p className="text-xs text-[var(--text-muted)] leading-relaxed mb-2">
                    {step.description}
                  </p>
                  <Link
                    href={step.href}
                    className="inline-flex items-center gap-1 text-xs font-medium text-[var(--accent)] hover:gap-2 transition-all"
                  >
                    Open tool
                    <ArrowRight className="w-3 h-3" />
                  </Link>
                </div>
              </div>

              {/* Connector arrow */}
              {!isLast && (
                <div className="flex justify-center py-1">
                  <ArrowRight className="w-4 h-4 text-[var(--text-muted)] rotate-90" />
                </div>
              )}
            </div>
          )
        })}
      </div>

      {/* Reset button */}
      <div className="mt-6 flex justify-end">
        <button
          onClick={() => {
            const reset = steps.map(s => ({ ...s, status: 'pending' as const }))
            setSteps(reset)
            saveProgress(reset)
          }}
          className="text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
        >
          Reset progress
        </button>
      </div>

      {/* Info box */}
      <div className="mt-8 p-4 rounded-xl bg-blue-500/5 border border-blue-500/15">
        <h4 className="text-sm font-semibold text-blue-400 mb-2">How to use this pipeline</h4>
        <ol className="text-xs text-[var(--text-muted)] space-y-1 list-decimal list-inside">
          <li>Start at step 1 — import your field data (CSV, RINEX, or point cloud)</li>
          <li>Proceed through each step in order — click "Open tool" to use the full-featured tool page</li>
          <li>Mark each step as done by clicking the circle on the left</li>
          <li>Optional steps (slope, volumes, cross-sections) can be skipped for simple topo jobs</li>
          <li>Your progress is saved automatically — you can leave and come back</li>
          <li>Final export produces DXF/SHP/GeoJSON/KML for AutoCAD, Civil 3D, QGIS, or ArcGIS</li>
        </ol>
      </div>
    </div>
  )
}

'use client';

import { useState, useMemo, useRef } from 'react';
import { useRouter } from 'next/navigation';

export interface FieldbookEntry {
  row_index: number;
  station:   string | null;
  raw_data:  Record<string, unknown> | null;
  bs:        number | null;
  remark:    string | null;
}

export interface ProjectInfo {
  id:                   string;
  name:                 string;
  survey_type:          string;
  lr_number?:           string | null;
  locality?:            string | null;
  registration_district?: string | null;
  utm_zone?:            number | null;
  hemisphere?:          string | null;
  datum?:               string | null;
}

interface Props {
  project:   ProjectInfo;
  entries:   FieldbookEntry[];
  projectId: string;
}

function parseBearing(raw: unknown): number {
  if (typeof raw === 'number') return raw;
  const s = String(raw ?? '');
  const m = s.match(/(\d+)[°\-\s](\d+)['\-\s](\d+\.?\d*)/);
  if (m) return Number(m[1]) + Number(m[2]) / 60 + Number(m[3]) / 3600;
  return parseFloat(s) || 0;
}

function decimalToDMS(deg: number): string {
  const d = Math.floor(deg);
  const mf = (deg - d) * 60;
  const m  = Math.floor(mf);
  const s  = ((mf - m) * 60).toFixed(1);
  return `${String(d).padStart(3, '0')}°${String(m).padStart(2, '0')}'${s.padStart(4, '0')}"`;
}

interface GaleRow {
  station:  string;
  bearing:  string;
  distance: string;
  dE:       string;
  dN:       string;
  E:        string;
  N:        string;
  corr_dE:  string;
  corr_dN:  string;
  adjE:     string;
  adjN:     string;
  beaconNo: string;
  monument: string;
}

interface DiagramData {
  rows:           GaleRow[];
  totalDist:      number;
  closureE:       number;
  closureN:       number;
  misclosureMm:   number;
  precisionRatio: number;
  closureStatus:  'PASS' | 'FAIL' | 'UNVERIFIED';
  minE: number; maxE: number;
  minN: number; maxN: number;
}

function computeDiagram(entries: FieldbookEntry[]): DiagramData | null {
  const legs = entries
    .map((e) => ({
      station:  String(e.station ?? e.raw_data?.station ?? ''),
      bearing:  parseBearing(e.raw_data?.bearing ?? 0),
      distance: parseFloat(String(e.raw_data?.distance ?? e.raw_data?.hd ?? 0)) || 0,
      beaconNo: String(e.raw_data?.beacon_no ?? ''),
      monument: String(e.raw_data?.monument_type ?? ''),
    }))
    .filter((l) => l.distance > 0);

  if (legs.length < 3) return null;

  const totalDist = legs.reduce((s, l) => s + l.distance, 0);

  let E = 0, N = 0;
  const rawPts: { dE: number; dN: number; E: number; N: number }[] = [];
  for (const leg of legs) {
    const rad = (leg.bearing * Math.PI) / 180;
    const dE  = leg.distance * Math.sin(rad);
    const dN  = leg.distance * Math.cos(rad);
    E += dE;
    N += dN;
    rawPts.push({ dE, dN, E, N });
  }

  const closureE = E;
  const closureN = N;
  const closureLinear = Math.sqrt(closureE ** 2 + closureN ** 2);
  const misclosureMm  = closureLinear * 1000;
  const ratio = totalDist > 0 && closureLinear > 0 ? Math.round(totalDist / closureLinear) : 999999;

  let cumDist = 0;
  let adjE = 0, adjN = 0;
  const rows: GaleRow[] = legs.map((leg, i) => {
    cumDist += leg.distance;
    const corrE = closureLinear > 0 ? -(closureE / totalDist) * cumDist : 0;
    const corrN = closureLinear > 0 ? -(closureN / totalDist) * cumDist : 0;
    adjE = rawPts[i].E + corrE;
    adjN = rawPts[i].N + corrN;
    const dCorrE = (closureLinear > 0 ? -(closureE / totalDist) : 0) * leg.distance;
    const dCorrN = (closureLinear > 0 ? -(closureN / totalDist) : 0) * leg.distance;
    return {
      station:  leg.station,
      bearing:  decimalToDMS(leg.bearing),
      distance: leg.distance.toFixed(3),
      dE:       rawPts[i].dE.toFixed(3),
      dN:       rawPts[i].dN.toFixed(3),
      E:        rawPts[i].E.toFixed(3),
      N:        rawPts[i].N.toFixed(3),
      corr_dE:  dCorrE.toFixed(4),
      corr_dN:  dCorrN.toFixed(4),
      adjE:     adjE.toFixed(3),
      adjN:     adjN.toFixed(3),
      beaconNo: leg.beaconNo,
      monument: leg.monument,
    };
  });

  const eastings  = rows.map((r) => parseFloat(r.adjE));
  const northings = rows.map((r) => parseFloat(r.adjN));

  return {
    rows,
    totalDist,
    closureE,
    closureN,
    misclosureMm,
    precisionRatio: ratio,
    closureStatus: ratio >= 5000 ? 'PASS' : ratio > 0 ? 'FAIL' : 'UNVERIFIED',
    minE: Math.min(...eastings),
    maxE: Math.max(...eastings),
    minN: Math.min(...northings),
    maxN: Math.max(...northings),
  };
}

function TraverseSVG({
  data,
  width,
  height,
}: {
  data: DiagramData;
  width: number;
  height: number;
}) {
  const pad = 40;
  const spanE = data.maxE - data.minE || 1;
  const spanN = data.maxN - data.minN || 1;
  const scale = Math.min((width - pad * 2) / spanE, (height - pad * 2) / spanN) * 0.85;
  const cx    = width / 2;
  const cy    = height / 2;
  const centreE = (data.minE + data.maxE) / 2;
  const centreN = (data.minN + data.maxN) / 2;

  const toSvg = (e: number, n: number): [number, number] => [
    cx + (e - centreE) * scale,
    cy - (n - centreN) * scale,
  ];

  const pts = data.rows.map((r) => toSvg(parseFloat(r.adjE), parseFloat(r.adjN)));
  const polyline = [...pts, pts[0]].map(([x, y]) => `${x},${y}`).join(' ');

  return (
    <svg width={width} height={height} className="bg-white">
      {[-2, -1, 0, 1, 2].map((i) => (
        <g key={`${i}-${i}`}>
          <line x1={0} y1={cy + i * 50} x2={width} y2={cy + i * 50} stroke="#e5e7eb" strokeWidth="0.5" />
          <line x1={cx + i * 50} y1={0} x2={cx + i * 50} y2={height} stroke="#e5e7eb" strokeWidth="0.5" />
        </g>
      ))}
      <polyline points={polyline} fill="rgba(30,80,100,0.06)" stroke="#1e5064" strokeWidth="1.5" strokeLinejoin="round" />
      {data.rows.map((row, i) => {
        const [x1, y1] = pts[i];
        const [x2, y2] = pts[(i + 1) % pts.length];
        const mx = (x1 + x2) / 2;
        const my = (y1 + y2) / 2;
        const angle = Math.atan2(y2 - y1, x2 - x1) * (180 / Math.PI);
        const rot   = angle > 90 || angle < -90 ? angle + 180 : angle;
        return (
          <text key={`${row}-${i}`} x={mx} y={my - 3} fontSize={8} fill="#1e5064" textAnchor="middle" transform={`rotate(${-rot}, ${mx}, ${my})`}>
            {row.bearing}  {row.distance}m
          </text>
        );
      })}
      {data.rows.map((row, i) => {
        const [px, py] = pts[i];
        return (
          <g key={row.station}>
            <circle cx={px} cy={py} r={5} fill="white" stroke="#1e5064" strokeWidth="1.5" />
            <circle cx={px} cy={py} r={1.5} fill="#1e5064" />
            <text x={px + 7} y={py - 4} fontSize={9} fontWeight="bold" fill="#111">{row.station}</text>
            {row.beaconNo && <text x={px + 7} y={py + 6} fontSize={7.5} fill="#6b7280">({row.beaconNo})</text>}
          </g>
        );
      })}
      {data.closureStatus !== 'UNVERIFIED' && (
        <g>
          <line
            x1={pts[pts.length - 1][0]}
            y1={pts[pts.length - 1][1]}
            x2={pts[pts.length - 1][0] + data.closureE * scale * 50}
            y2={pts[pts.length - 1][1] - data.closureN * scale * 50}
            stroke="#ef4444" strokeWidth="1.5" strokeDasharray="3 2"
          />
          <text
            x={pts[pts.length - 1][0] + data.closureE * scale * 50 + 4}
            y={pts[pts.length - 1][1] - data.closureN * scale * 50 - 4}
            fontSize={7.5} fill="#ef4444"
          >
            e={data.misclosureMm.toFixed(1)}mm (×50)
          </text>
        </g>
      )}
      <g transform={`translate(${width - 28}, ${height - 45})`}>
        <polygon points="0,-14 4,0 0,-4 -4,0" fill="#1e5064" />
        <text x={0} y={8} fontSize={10} fontWeight="bold" fill="#1e5064" textAnchor="middle">N</text>
      </g>
    </svg>
  );
}

export default function WorkingDiagramClient({ project, entries, projectId }: Props) {
  const router    = useRouter();
  const printRef  = useRef<HTMLDivElement>(null);
  const [generating, setGenerating] = useState(false);
  const [pdfUrl, setPdfUrl]         = useState<string | null>(null);
  const [pdfError, setPdfError]     = useState<string | null>(null);

  const data = useMemo(() => computeDiagram(entries), [entries]);

  const handleGeneratePdf = async () => {
    setGenerating(true);
    setPdfError(null);
    try {
      const res = await fetch('/api/submission/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ projectId, documentId: 'working-diagram' }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error ?? 'Generation failed');
      setPdfUrl(json.fileUrl);
    } catch (err: unknown) {
      setPdfError(err instanceof Error ? (err as Error).message : 'Unknown error');
    } finally {
      setGenerating(false);
    }
  };

  const handlePrint = () => window.print();

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="bg-white border-b border-gray-200 px-4 py-3 flex items-center justify-between no-print">
        <div>
          <button onClick={() => router.back()} className="text-sm text-gray-500 hover:text-gray-800 mr-3">← Back</button>
          <span className="font-semibold text-gray-900">{project.name}</span>
          <span className="text-sm text-gray-400 ml-2">Working Diagram</span>
        </div>
        <div className="flex gap-2">
          <button onClick={handlePrint} className="px-3 py-1.5 text-sm border border-gray-300 rounded hover:bg-gray-50">Print</button>
          <button onClick={handleGeneratePdf} disabled={generating || !data} className="px-3 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50">
            {generating ? 'Generating…' : 'Download PDF'}
          </button>
          {pdfUrl && (
            <a href={pdfUrl} target="_blank" rel="noopener noreferrer" className="px-3 py-1.5 text-sm bg-green-600 text-white rounded hover:bg-green-700">Open PDF</a>
          )}
        </div>
      </div>

      {pdfError && (
        <div className="mx-4 mt-3 p-3 bg-red-50 border border-red-200 rounded text-sm text-red-600 no-print">{pdfError}</div>
      )}

      {!data ? (
        <div className="flex items-center justify-center h-64 text-gray-400 text-sm">
          Insufficient traverse data. Add at least 3 bearing/distance observations in the Field Book.
        </div>
      ) : (
        <div ref={printRef} className="flex gap-0 bg-white mx-4 mt-4 mb-4 rounded-lg border border-gray-200 overflow-hidden print-container">
          <div className="flex-[62] border-r border-gray-200 p-3">
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Traverse Plan — {project.name}</p>
            <TraverseSVG data={data} width={520} height={460} />
            <div className="mt-2 flex gap-4 text-xs text-gray-500">
              <span>UTM Zone {project.utm_zone}{project.hemisphere}</span>
              <span>{project.datum ?? 'Arc 1960'}</span>
              {project.lr_number && <span>LR: {project.lr_number}</span>}
            </div>
          </div>
          <div className="flex-[38] p-3 overflow-x-auto">
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Gale&apos;s Table</p>
            <table className="w-full text-xs border-collapse">
              <thead>
                <tr className="bg-[#1e5064] text-white">
                  {['Stn', 'Bearing', 'Dist (m)', 'ΔE', 'ΔN', 'Adj E', 'Adj N', 'Beacon'].map((h) => (
                    <th key={h} className="px-1.5 py-1 text-left font-medium whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {data.rows.map((row, i) => (
                  <tr key={row.station} className={i % 2 === 0 ? 'bg-[#f0f5f8]' : 'bg-white'}>
                    <td className="px-1.5 py-1 font-medium">{row.station}</td>
                    <td className="px-1.5 py-1 font-mono text-[10px]">{row.bearing}</td>
                    <td className="px-1.5 py-1 text-right">{row.distance}</td>
                    <td className={`px-1.5 py-1 text-right ${parseFloat(row.dE) < 0 ? 'text-red-600' : ''}`}>{row.dE}</td>
                    <td className={`px-1.5 py-1 text-right ${parseFloat(row.dN) < 0 ? 'text-red-600' : ''}`}>{row.dN}</td>
                    <td className="px-1.5 py-1 text-right font-medium">{row.adjE}</td>
                    <td className="px-1.5 py-1 text-right font-medium">{row.adjN}</td>
                    <td className="px-1.5 py-1 text-gray-500">{row.beaconNo}</td>
                  </tr>
                ))}
                <tr className="bg-[#1e5064] text-white font-medium">
                  <td className="px-1.5 py-1">Σ</td><td />
                  <td className="px-1.5 py-1 text-right">{data.totalDist.toFixed(3)}</td>
                  <td className="px-1.5 py-1 text-right">{data.closureE.toFixed(3)}</td>
                  <td className="px-1.5 py-1 text-right">{data.closureN.toFixed(3)}</td>
                  <td colSpan={3} />
                </tr>
              </tbody>
            </table>
            <div className="mt-4 border border-gray-200 rounded p-3 text-xs space-y-1.5">
              <p className="font-semibold text-gray-700 mb-2">Closure Summary</p>
              <div className="flex justify-between"><span className="text-gray-500">Misclosure</span><span className="font-medium">{data.misclosureMm.toFixed(1)} mm</span></div>
              <div className="flex justify-between"><span className="text-gray-500">Precision ratio</span><span className="font-medium">1:{data.precisionRatio.toLocaleString()}</span></div>
              <div className="flex justify-between"><span className="text-gray-500">Min. standard</span><span className="text-gray-500">1:5000 (Cap 299)</span></div>
              <div className="flex justify-between mt-1 pt-1 border-t border-gray-100">
                <span className="font-medium">Status</span>
                <span className={`font-bold ${data.closureStatus === 'PASS' ? 'text-green-600' : data.closureStatus === 'FAIL' ? 'text-red-600' : 'text-gray-400'}`}>{data.closureStatus}</span>
              </div>
            </div>
            <p className="mt-3 text-[10px] text-gray-400">Generated {new Date().toLocaleDateString('en-KE', { day: '2-digit', month: 'long', year: 'numeric' })}</p>
          </div>
        </div>
      )}
      <style jsx global>{`
        @media print { .no-print { display: none !important; } .print-container { margin: 0 !important; border: none !important; } body { background: white; } }
      `}</style>
    </div>
  );
}

import { createClient } from '@/lib/api-client/server';
import { cookies } from 'next/headers';
import { redirect } from 'next/navigation';
import WorkingDiagramClient, { type ProjectInfo, type FieldbookEntry } from './WorkingDiagramClient';

interface Props {
  searchParams: { projectId?: string };
}

export default async function WorkingDiagramPage({ searchParams }: Props) {
  const { projectId } = searchParams;
  if (!projectId) redirect('/projects');

  const dbClient = await createClient();

  const { data: { session } } = await dbClient.auth.getSession();
  if (!session) redirect('/login');

  const { data: project } = await dbClient
    .from('projects')
    .select(`
      id, name, survey_type, lr_number, locality,
      registration_district, utm_zone, hemisphere, datum
    `)
    .eq('id', projectId)
    .eq('user_id', (session as { user?: { id?: string } } | null)?.user?.id as string)
    .single();

  if (!project) redirect('/projects');

  const { data: entries } = await dbClient
    .from('project_fieldbook_entries')
    .select('row_index, station, raw_data, bs, remark')
    .eq('project_id', projectId)
    .order('row_index', { ascending: true });

  return (
    <WorkingDiagramClient
      project={project as unknown as ProjectInfo}
      entries={(entries ?? []) as unknown as FieldbookEntry[]}
      projectId={projectId}
    />
  );
}

'use client';

import { useState, useEffect } from 'react'
import { geographicToUTM } from '@/lib/geodesy/coordinates'

interface AddPointModalProps {
  isOpen: boolean
  onClose: () => void
  projectId: string
  utmZone: number
  hemisphere: 'N' | 'S'
  prefillEasting?: number
  prefillNorthing?: number
  onPointAdded: () => void
  editPointId?: string
  editPointName?: string
  editPointEasting?: number
  editPointNorthing?: number
  editPointElevation?: number
  editPointIsControl?: boolean
  editPointControlOrder?: string
  editPointLocked?: boolean
  editPointUpdatedAt?: string
}

export default function AddPointModal({
  isOpen,
  onClose,
  projectId,
  utmZone,
  hemisphere,
  prefillEasting,
  prefillNorthing,
  onPointAdded,
  editPointId,
  editPointName,
  editPointEasting,
  editPointNorthing,
  editPointElevation,
  editPointIsControl,
  editPointControlOrder,
  editPointLocked,
  editPointUpdatedAt,
}: AddPointModalProps) {
  const [name, setName] = useState('')
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [elevation, setElevation] = useState('0')
  const [isControl, setIsControl] = useState(false)
  const [controlOrder, setControlOrder] = useState<'primary' | 'secondary' | 'temporary'>('secondary')
  const [locked, setLocked] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [successMsg, setSuccessMsg] = useState<string | null>(null)

  const isEditMode = !!editPointId
  const isLocked = isEditMode && editPointLocked

  useEffect(() => {
    // Reset form when modal opens/closes or edit point changes
    if (isEditMode && editPointName) {
      setName(editPointName)
      setEasting(editPointEasting?.toFixed(4) || '')
      setNorthing(editPointNorthing?.toFixed(4) || '')
      setElevation(editPointElevation?.toString() || '0')
      setIsControl(editPointIsControl || false)
      setControlOrder((editPointControlOrder as any) || 'secondary')
      setLocked(editPointLocked || false)
    } else if (prefillEasting !== undefined) {
      setEasting(prefillEasting.toFixed(4))
    }
    if (prefillNorthing !== undefined) {
      setNorthing(prefillNorthing.toFixed(4))
    }
    if (!isEditMode) {
      setName('')
      setElevation('0')
      setIsControl(false)
      setControlOrder('secondary')
      setLocked(false)
    }
    setError(null)
    setSuccessMsg(null)
  }, [isOpen, prefillEasting, prefillNorthing, isEditMode, editPointName, editPointEasting, editPointNorthing, editPointElevation, editPointIsControl, editPointControlOrder, editPointLocked])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setSuccessMsg(null)
    setLoading(true)

    try {
      // T1.5g FIX (2026-07-10): Use the REST API instead of direct Supabase client.
      // Previously this bypassed the API layer (no auth, no audit, no optimistic locking).
      // Now uses POST /api/survey-points (create) and PATCH /api/survey-points/[id] (update).

      const pointData = {
        point_name: name.trim(),
        easting: Number(parseFloat(easting).toFixed(4)),
        northing: Number(parseFloat(northing).toFixed(4)),
        elevation: Number(parseFloat(elevation || '0').toFixed(4)),
        is_control: Boolean(isControl),
      }

      if (isEditMode) {
        // PATCH requires updated_at for optimistic locking.
        // T1.5i FIX (2026-07-10): If editPointUpdatedAt is not provided by the
        // caller, omit it from the request. The API will skip the optimistic
        // lock guard (treat it as an unconditional update). This prevents the
        // 409 Conflict that occurred when the fallback used new Date().toISOString().
        const patchBody: Record<string, unknown> = { ...pointData }
        if (editPointUpdatedAt) {
          patchBody.updated_at = editPointUpdatedAt
        }
        const res = await fetch(`/api/survey-points/${editPointId}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(patchBody),
        })
        if (!res.ok) {
          const err = await res.json().catch(() => ({ error: res.statusText }))
          throw new Error(err.error || `Failed to update point (${res.status})`)
        }
      } else {
        // POST to create
        const res = await fetch('/api/survey-points', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            project_id: projectId,
            ...pointData,
          }),
        })
        if (!res.ok) {
          const err = await res.json().catch(() => ({ error: res.statusText }))
          if (res.status === 409 && err.error?.includes('already exists')) {
            throw new Error(`Point "${name}" already exists in this project. Use a different name.`)
          }
          throw new Error(err.error || `Failed to add point (${res.status})`)
        }
      }

      // Success
      setLoading(false)
      onPointAdded()
      onClose()

    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unexpected error. Please try again.')
      setLoading(false)
    }
  }

  const handleSaveAndAddAnother = async () => {
    if (isEditMode) return // Only for new points

    setError(null)
    setSuccessMsg(null)
    setLoading(true)

    try {
      const res = await fetch('/api/survey-points', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          project_id: projectId,
          point_name: name.trim(),
          easting: Number(parseFloat(easting).toFixed(4)),
          northing: Number(parseFloat(northing).toFixed(4)),
          elevation: Number(parseFloat(elevation || '0').toFixed(4)),
          is_control: Boolean(isControl),
        }),
      })

      if (!res.ok) {
        const err = await res.json().catch(() => ({ error: res.statusText }))
        throw new Error(err.error || `Failed to add point (${res.status})`)
      }

      // Success - clear fields but keep checkbox state
      setLoading(false)
      setSuccessMsg(` ${name} saved`)
      setName('')
      setEasting('')
      setNorthing('')
      setElevation('0')
      onPointAdded()
      
      // Clear success message after 2 seconds
      setTimeout(() => setSuccessMsg(null), 2000)

    } catch (err) {
      setError('Unexpected error. Please try again.')
      setLoading(false)
    }
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center" onKeyDown={(e) => { if (e.key === 'Escape') onClose() }}>
      <button type="button" aria-label="Close dialog" tabIndex={-1} className="absolute inset-0 bg-black/70 cursor-pointer border-0 p-0" onClick={onClose}></button>
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6 w-full max-w-md" role="dialog" aria-modal="true" aria-label={isEditMode ? 'Edit Survey Point' : 'Add Survey Point'}>
        <h2 className="text-xl font-bold text-[var(--text-primary)] mb-4">
          {isEditMode ? 'Edit Survey Point' : 'Add Survey Point'}
        </h2>
        
        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <div className="text-red-400 text-sm p-2 bg-red-900/20 rounded border border-red-800">
              {error}
            </div>
          )}

          <div>
            <label className="block text-sm text-[var(--text-primary)] mb-1" htmlFor="point-name">Point Name *</label>
            <input
              id="point-name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)] font-mono"
              placeholder="e.g., TP01, BM1"
              required
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-[var(--text-primary)] mb-1" htmlFor="point-easting">Easting (m) *</label>
              <input id="point-easting"
                type="number"
                step="0.0001"
                value={easting}
                onChange={(e) => setEasting(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)] font-mono"
                required
              />
            </div>
            <div>
              <label className="block text-sm text-[var(--text-primary)] mb-1" htmlFor="point-northing">Northing (m) *</label>
              <input id="point-northing"
                type="number"
                step="0.0001"
                value={northing}
                onChange={(e) => setNorthing(e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)] font-mono"
                required
              />
            </div>
          </div>

          <div>
            <label className="block text-sm text-[var(--text-primary)] mb-1" htmlFor="point-elevation">Elevation (m)</label>
            <input id="point-elevation"
              type="number"
              step="0.001"
              value={elevation}
              onChange={(e) => setElevation(e.target.value)}
              className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)] font-mono"
            />
          </div>

          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="isControl"
              checked={isControl}
              onChange={(e) => setIsControl(e.target.checked)}
              className="w-4 h-4 rounded bg-[var(--bg-tertiary)] border-[var(--border-color)] text-[var(--accent)] focus:ring-[#D17B47]"
            />
            <label htmlFor="isControl" className="text-sm text-[var(--text-primary)]">
              This is a control point
            </label>
          </div>

          {isControl && (
            <div className="pl-6 space-y-3 border-l-2 border-[var(--border-color)]">
              <div>
                <label className="block text-sm text-[var(--text-primary)] mb-1" htmlFor="control-classification">Control Classification</label>
                <select id="control-classification"
                  value={controlOrder}
                  onChange={(e) => setControlOrder(e.target.value as any)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded focus:border-[var(--accent)] focus:outline-none text-[var(--text-primary)]"
                >
                  <option value="primary">Primary Control</option>
                  <option value="secondary">Secondary Control</option>
                  <option value="temporary">Temporary Control</option>
                </select>
              </div>
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  id="locked"
                  checked={locked}
                  onChange={(e) => setLocked(e.target.checked)}
                  className="w-4 h-4 rounded bg-[var(--bg-tertiary)] border-[var(--border-color)] text-[var(--accent)] focus:ring-[#D17B47]"
                />
                <label htmlFor="locked" className="text-sm text-[var(--text-primary)]">
                  [Lock] Lock this point (prevent edit/delete)
                </label>
              </div>
            </div>
          )}

          {successMsg && (
            <div className="text-green-400 text-sm p-2 bg-green-900/20 rounded border border-green-800">
              {successMsg}
            </div>
          )}

          <div className="flex gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded transition-colors"
            >
              Cancel
            </button>
            {!isEditMode && (
              <button
                type="button"
                onClick={handleSaveAndAddAnother}
                disabled={loading || !name || !easting || !northing}
                className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded transition-colors disabled:opacity-50"
              >
                Save & Add Another
              </button>
            )}
            <button
              type="submit"
              disabled={loading}
              className="flex-1 px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded transition-colors disabled:opacity-50"
            >
              {loading ? (isEditMode ? 'Saving...' : 'Adding...') : (isEditMode ? 'Save Changes' : 'Add Point')}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

'use client';

import { useState, useRef } from 'react'
import { createClient } from '@/lib/api-client/client'
import { parseDelimitedFile, validatePoints } from '@/lib/engine/parser'

interface CSVUploadModalProps {
  isOpen: boolean
  onClose: () => void
  projectId: string
  onUploadComplete: () => void
}

interface ParsedPoint {
  name: string
  easting: number
  northing: number
  elevation: number
}

export default function CSVUploadModal({
  isOpen,
  onClose,
  projectId,
  onUploadComplete
}: CSVUploadModalProps) {
  const [parsedPoints, setParsedPoints] = useState<ParsedPoint[]>([])
  const [warnings, setWarnings] = useState<string[]>([])
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [step, setStep] = useState<'upload' | 'preview' | 'importing'>('upload')
  const fileInputRef = useRef<HTMLInputElement>(null)
  const dbClient = createClient()

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    setError('')
    setLoading(true)

    try {
      const content = await file.text()
      const result = parseDelimitedFile(content, ',')
      
      if (result.points.length === 0) {
        setError('No valid points found in file')
        setLoading(false)
        return
      }

      const validationWarnings = validatePoints(result.points)
      setParsedPoints(result.points.map((p: any) => ({
        name: p.name,
        easting: p.easting,
        northing: p.northing,
        elevation: p.elevation || 0
      })))
      setWarnings([...result.warnings, ...validationWarnings])
      setStep('preview')
    } catch (err) {
      // AUDIT FIX (M15, 2026-07-02): Actionable error message.
      const msg = err instanceof Error ? err.message : String(err)
      setError(`Could not parse the file. ${msg}. Check that the file is a valid CSV with columns: name, easting, northing, elevation (or N, E, Z). If the file uses a different delimiter (tab, semicolon), try converting to comma-separated first.`)
    }

    setLoading(false)
  }

  const handleImport = async () => {
    setStep('importing')
    setLoading(true)

    try {
      const pointsToInsert = parsedPoints.map((p: any) => ({
        project_id: projectId,
        point_name: p.name,  // T1.5d FIX: was 'name' (column doesn't exist)
        easting: p.easting,
        northing: p.northing,
        elevation: p.elevation,
        is_control: false
      }))

      const { error } = await dbClient.from('survey_points').insert(pointsToInsert)

      if (error) {
        setError(error.message)
        setLoading(false)
        return
      }

      onUploadComplete()
      handleClose()
    } catch (err) {
      setError('Failed to import points')
    }

    setLoading(false)
  }

  const handleClose = () => {
    setParsedPoints([])
    setWarnings([])
    setError('')
    setStep('upload')
    if (fileInputRef.current) {
      fileInputRef.current.value = ''
    }
    onClose()
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/70" onClick={handleClose}></div>
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6 w-full max-w-2xl max-h-[80vh] overflow-hidden flex flex-col">
        <h2 className="text-xl font-bold text-[var(--text-primary)] mb-4">Upload CSV</h2>

        {error && (
          <div className="mb-4 p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
            {error}
          </div>
        )}

        {step === 'upload' && (
          <div className="space-y-4">
            <p className="text-[var(--text-secondary)] text-sm">
              Upload a CSV file with columns: Point Name, Easting, Northing, Elevation (optional)
            </p>
            <div className="border-2 border-dashed border-[var(--border-color)] rounded-lg p-8 text-center">
              <input
                ref={fileInputRef}
                type="file"
                accept=".csv,.txt"
                onChange={handleFileChange}
                className="hidden"
                id="csv-upload"
              />
              <label
                htmlFor="csv-upload"
                className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded transition-colors"
              >
                {loading ? 'Parsing...' : 'Choose File'}
              </label>
              <p className="text-[var(--text-muted)] text-sm mt-2">or drag and drop</p>
            </div>
            <div className="text-xs text-[var(--text-muted)]">
              <p className="font-semibold text-[var(--text-secondary)] mb-1">Expected format:</p>
              <code className="block bg-[var(--bg-tertiary)] p-2 rounded">
                POINT,EASTING,NORTHING,ELEVATION<br />
                TP01,123456.7890,9876543.210,100.5<br />
                TP02,123478.9012,9876565.432,101.2
              </code>
            </div>
          </div>
        )}

        {step === 'preview' && (
          <div className="space-y-4 flex-1 overflow-hidden flex flex-col">
            <div className="flex items-center justify-between">
              <p className="text-[var(--text-primary)]">
                Found <span className="text-[var(--accent)] font-bold">{parsedPoints.length}</span> points
              </p>
              <button
                onClick={handleClose}
                className="text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
              >
                ×
              </button>
            </div>

            {warnings.length > 0 && (
              <div className="bg-yellow-900/30 border border-yellow-600 rounded p-3 max-h-24 overflow-y-auto">
                <p className="text-yellow-400 text-sm font-semibold mb-1">Warnings:</p>
                {warnings.slice(0, 5).map((w, i) => (
                  <p key={`${w}-${i}`} className="text-yellow-300 text-xs">{w}</p>
                ))}
                {warnings.length > 5 && (
                  <p className="text-yellow-300 text-xs">...and {warnings.length - 5} more</p>
                )}
              </div>
            )}

            <div className="flex-1 overflow-auto border border-[var(--border-color)] rounded">
              <table className="w-full text-sm">
                <thead className="bg-[var(--bg-tertiary)] sticky top-0">
                  <tr>
                    <th className="px-3 py-2 text-left text-[var(--text-primary)] font-semibold">Point</th>
                    <th className="px-3 py-2 text-left text-[var(--text-primary)] font-semibold">Easting</th>
                    <th className="px-3 py-2 text-left text-[var(--text-primary)] font-semibold">Northing</th>
                    <th className="px-3 py-2 text-left text-[var(--text-primary)] font-semibold">Elevation</th>
                  </tr>
                </thead>
                <tbody>
                  {parsedPoints.slice(0, 50).map((point, idx) => (
                    <tr key={point.name} className="border-t border-[var(--border-color)]">
                      <td className="px-3 py-2 font-mono text-[var(--text-primary)]">{point.name}</td>
                      <td className="px-3 py-2 font-mono text-[var(--text-primary)]">{point.easting.toFixed(4)}</td>
                      <td className="px-3 py-2 font-mono text-[var(--text-primary)]">{point.northing.toFixed(4)}</td>
                      <td className="px-3 py-2 font-mono text-[var(--text-primary)]">{point.elevation.toFixed(3)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {parsedPoints.length > 50 && (
                <p className="text-center text-[var(--text-muted)] py-2 text-sm">
                  ...and {parsedPoints.length - 50} more points
                </p>
              )}
            </div>

            <div className="flex gap-3">
              <button
                onClick={handleClose}
                className="flex-1 px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleImport}
                disabled={loading}
                className="flex-1 px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded transition-colors disabled:opacity-50"
              >
                Import {parsedPoints.length} Points
              </button>
            </div>
          </div>
        )}

        {step === 'importing' && (
          <div className="py-12 text-center">
            <div className="animate-spin w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full mx-auto mb-4"></div>
            <p className="text-[var(--text-primary)]">Importing points...</p>
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { Component, type ReactNode } from 'react'

interface Props {
  children: ReactNode
  toolName?: string
}

interface State {
  hasError: boolean
  message: string
}

export class CalculatorErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props)
    this.state = { hasError: false, message: '' }
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, message: error.message }
  }

  componentDidCatch(error: Error) {
    console.error(`[METARDU] Calculator error${this.props.toolName ? ` (${this.props.toolName})` : ''}:`, error)
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="max-w-lg mx-auto mt-12 rounded-lg border border-red-200 bg-red-50 p-6 text-sm text-red-800 dark:border-red-800 dark:bg-red-950 dark:text-red-200">
          <p className="text-base font-semibold mb-2">Calculation error</p>
          <p className="text-red-700 dark:text-red-300 mb-4">
            {this.state.message || 'An unexpected error occurred. Check your inputs and try again.'}
          </p>
          <button
            className="rounded bg-red-600 px-4 py-2 text-white hover:bg-red-700 transition-colors"
            onClick={() => this.setState({ hasError: false, message: '' })}
          >
            Reset calculator
          </button>
        </div>
      )
    }
    return this.props.children
  }
}

'use client';

import { useState } from 'react'
import type { SurveyPlanData } from '@/lib/reports/surveyPlan/types'

interface ComplianceItem {
  key: string
  label: string
  pass: boolean
}

interface ComplianceChecklistModalProps {
  isOpen: boolean
  onClose: () => void
  data: SurveyPlanData
  onExport: () => void
}

export default function ComplianceChecklistModal({
  isOpen,
  onClose,
  data,
  onExport,
}: ComplianceChecklistModalProps) {
  if (!isOpen) return null

  const p = data.project
  const parcel = data.parcel
  const pts = parcel?.boundaryPoints || []

  const items: ComplianceItem[] = [
    {
      key: 'beacons',
      label: 'Boundary beacons are present (minimum 3 corners)',
      pass: pts.length >= 3,
    },
    {
      key: 'coordinates',
      label: 'All boundary coordinates tabulated in schedule',
      pass: pts.length >= 3,
    },
    {
      key: 'area',
      label: 'Parcel area is inscribed on the plan',
      pass: (p.area_sqm || 0) > 0,
    },
    {
      key: 'north',
      label: 'North point / arrow is shown',
      pass: true,
    },
    {
      key: 'scale',
      label: 'Scale bar and numeric scale are shown',
      pass: true,
    },
    {
      key: 'boundary',
      label: 'Boundary lengths and bearings are labeled',
      pass: (p.bearingSchedule?.length || 0) >= 3,
    },
    {
      key: 'adjacent',
      label: 'Adjacent lot references are noted',
      pass: !!(p.reference || p.plan_title),
    },
    {
      key: 'surveyor',
      label: 'Surveyor name and LSK licence number are shown',
      pass: !!(p.surveyor_name && p.surveyor_licence),
    },
    {
      key: 'authentication',
      label: 'Authentication space is reserved on the plan',
      pass: true,
    },
    {
      key: 'drawing_no',
      label: 'Drawing number / plan reference is assigned',
      pass: !!p.drawing_no,
    },
    {
      key: 'datum',
      label: 'Datum set to ARC1960 (required for KeNHA submissions per RDM 1.1 §5.2)',
      pass: p.datum === 'ARC1960' || !p.datum,
    },
  ]

  const passed = items.filter((i: any) => i.pass).length
  const total = items.length
  const allPassed = passed === total

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/70" onClick={onClose} />
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl p-6 w-full max-w-lg max-h-[90vh] overflow-y-auto shadow-2xl">
        <div className="flex items-center justify-between mb-5">
          <div>
            <h2 className="text-lg font-bold text-[var(--text-primary)]">
              METARDU Compliance Checklist
            </h2>
            <p className="text-xs text-[var(--text-muted)] mt-0.5">
              RDM 1.1 — Boundary Identification Plan
            </p>
          </div>
          <button
            onClick={onClose}
            className="text-[var(--text-muted)] hover:text-[var(--text-primary)] text-xl leading-none"
          >
            ×
          </button>
        </div>

        {/* Progress bar */}
        <div className="mb-4">
          <div className="flex items-center justify-between text-xs mb-1.5">
            <span className="text-[var(--text-secondary)]">
              {passed}/{total} items compliant
            </span>
            <span className={`font-semibold ${allPassed ? 'text-green-400' : 'text-amber-400'}`}>
              {allPassed ? 'READY TO EXPORT' : 'ACTION REQUIRED'}
            </span>
          </div>
          <div className="h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div
              className={`h-full transition-all duration-300 ${allPassed ? 'bg-green-500' : 'bg-amber-500'}`}
              style={{ width: `${(passed / total) * 100}%` }}
            />
          </div>
        </div>

        {/* Checklist items */}
        <div className="space-y-2 mb-6">
          {items.map((item: any) => (
            <div
              key={item.key}
              className={`flex items-start gap-3 px-3 py-2.5 rounded-lg border transition-colors ${
                item.pass
                  ? 'border-green-800/40 bg-green-900/10'
                  : 'border-amber-800/40 bg-amber-900/10'
              }`}
            >
              <div className={`mt-0.5 w-5 h-5 rounded-full flex items-center justify-center flex-shrink-0 ${
                item.pass
                  ? 'bg-green-900/50 border border-green-600'
                  : 'bg-amber-900/50 border border-amber-600'
              }`}>
                {item.pass ? (
                  <svg className="w-3 h-3 text-green-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
                  </svg>
                ) : (
                  <svg className="w-3 h-3 text-amber-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3m0 3h.01M12 3a9 9 0 100 18A9 9 0 0012 3z" />
                  </svg>
                )}
              </div>
              <span className={`text-sm flex-1 ${
                item.pass ? 'text-green-300' : 'text-amber-300'
              }`}>
                {item.label}
              </span>
            </div>
          ))}
        </div>

        {/* Warning for non-compliant items */}
        {!allPassed && (
          <div className="mb-4 p-3 bg-amber-900/20 border border-amber-700/30 rounded-lg">
            <p className="text-xs text-amber-300">
              <strong>Note:</strong> The plan can still be exported, but may not meet KeNHA submission requirements. Address the flagged items above before formal submission.
            </p>
          </div>
        )}

        {/* Actions */}
        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="flex-1 px-4 py-2.5 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded-lg text-sm font-medium transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={() => {
              onExport()
              onClose()
            }}
            disabled={false}
            className="flex-1 px-4 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded-lg text-sm transition-colors disabled:opacity-50"
          >
            {allPassed ? 'Export Plan' : 'Export Anyway'}
          </button>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback } from 'react'
import { useSession } from 'next-auth/react'
import {
  type FeedbackCategory,
  buildFeedbackPayload,
  markFeedbackSubmitted,
  canSubmitFeedback,
  drainStoredErrors,
} from '@/lib/feedback/feedbackCollector'
import { ChangelogPanel } from '@/components/feedback/ChangelogPanel'

type Tab = 'feedback' | 'changelog'

/**
 * FeedbackWidget — floating button that opens a feedback form.
 *
 * AUDIT FIX (2026-07-05): Complete rewrite. Previously:
 *   - Used the deprecated createClient() which tried dbClient.from('feedback')
 *     but no feedback table existed → insert failed silently
 *   - Fallback was console.warn() — feedback was lost
 *   - Screenshot capture tried to import html2canvas (not installed) → always null
 *
 * Now:
 *   - POSTs to /api/feedback (real endpoint that saves to the feedback table)
 *   - Uses useSession() for the user ID (not the deprecated auth.getSession())
 *   - Sends error logs from sessionStorage as JSON
 *   - Screenshot capture removed (was always failing silently — html2canvas
 *     not installed and is too heavy to add). Users can still describe
 *     what they see in the message field.
 *   - Rate limited server-side: 5 submissions per 15 minutes per user
 */
export default function FeedbackWidget() {
  const { data: session } = useSession()
  const [isOpen, setIsOpen] = useState(false)
  const [tab, setTab] = useState<Tab>('feedback')
  const [type, setType] = useState<FeedbackCategory>('bug')
  const [message, setMessage] = useState('')
  const [email, setEmail] = useState('')
  const [submitted, setSubmitted] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const resetForm = useCallback(() => {
    setSubmitted(false)
    setMessage('')
    setEmail('')
    setError(null)
    setType('bug')
  }, [])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!message.trim()) return
    if (!canSubmitFeedback()) {
      setError('Please wait 30 seconds before submitting again.')
      return
    }

    setLoading(true)
    setError(null)

    try {
      const payload = buildFeedbackPayload(type, message, email || undefined)

      const res = await fetch('/api/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type,
          message,
          email: email || undefined,
          includeErrors: true,
          errors: payload.errorEntries,
        }),
      })

      if (!res.ok) {
        const data = await res.json().catch(() => ({}))
        throw new Error(data.error || `Server returned ${res.status}`)
      }

      markFeedbackSubmitted()
      setSubmitted(true)
      setTimeout(() => {
        setIsOpen(false)
        resetForm()
      }, 2500)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to submit feedback')
    } finally {
      setLoading(false)
    }
  }

  if (!isOpen) {
    return (
      <button
        onClick={() => setIsOpen(true)}
        aria-label="Send feedback"
        // AUDIT FIX (2026-07-05): Repositioned to avoid overlap with
        // QuickCompute (bottom-20 md:bottom-6 right-4) and FieldModeToggle
        // (bottom-6 right-6). The feedback button now sits ABOVE QuickCompute
        // on both mobile and desktop:
        //   Mobile:  bottom-[168px] (above MobileNav 64px + QuickCompute 104px)
        //   Desktop: bottom-32      (above QuickCompute at bottom-6 + its height)
        className="fixed bottom-[168px] right-4 md:bottom-32 bg-[var(--accent)] text-black px-3 py-2 rounded-full shadow-lg text-xs font-semibold z-40 hover:bg-[var(--accent-dim)] transition-colors flex items-center gap-1.5"
      >
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M7.5 8.25h9m-9 3H12m-9.75 1.51c0 1.6 1.123 2.994 2.707 3.227 1.129.166 2.27.293 3.423.379.35.026.67.21.865.501L12 21l2.755-4.133a1.14 1.14 0 01.865-.501 48.172 48.172 0 003.423-.379c1.584-.233 2.707-1.626 2.707-3.228V6.741c0-1.602-1.123-2.995-2.707-3.228A48.394 48.394 0 0012 3c-2.392 0-4.744.175-7.043.513C3.373 3.746 2.25 5.14 2.25 6.741v6.018z" />
        </svg>
        Feedback
      </button>
    )
  }

  return (
    <div className="fixed bottom-[168px] right-4 left-4 sm:bottom-32 sm:left-auto bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl shadow-2xl w-[calc(100vw-2rem)] sm:w-[22rem] max-h-[70vh] z-50 flex flex-col overflow-hidden">
      {/* Header */}
      <div className="bg-[var(--accent)] px-4 py-3 flex justify-between items-center flex-shrink-0">
        <h3 className="text-black font-bold text-sm">Feedback</h3>
        <div className="flex items-center gap-2">
          <div className="flex bg-black/10 rounded-md overflow-hidden">
            <button
              onClick={() => setTab('feedback')}
              className={`px-2.5 py-1 text-xs font-medium transition-colors ${
                tab === 'feedback' ? 'bg-black text-[var(--accent)]' : 'text-black/70 hover:text-black'
              }`}
            >
              Report
            </button>
            <button
              onClick={() => setTab('changelog')}
              className={`px-2.5 py-1 text-xs font-medium transition-colors ${
                tab === 'changelog' ? 'bg-black text-[var(--accent)]' : 'text-black/70 hover:text-black'
              }`}
            >
              What&apos;s New
            </button>
          </div>
          <button onClick={() => { setIsOpen(false); resetForm() }} className="text-black hover:text-black/60 ml-1" aria-label="Close feedback">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto min-h-0">
        {tab === 'changelog' ? (
          <ChangelogPanel />
        ) : submitted ? (
          <div className="text-center py-10 px-4">
            <div className="w-12 h-12 rounded-full bg-green-500/15 flex items-center justify-center mx-auto mb-3">
              <svg className="w-6 h-6 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M4.5 12.75l6 6 9-13.5" />
              </svg>
            </div>
            <p className="text-green-400 font-semibold mb-1">Thank you!</p>
            <p className="text-[var(--text-muted)] text-xs">Your feedback has been submitted and will help improve METARDU.</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-4 space-y-3">
            {/* Auth notice */}
            {!session?.user && (
              <p className="text-xs text-[var(--text-muted)] bg-[var(--bg-tertiary)] rounded-lg p-2">
                You need to be signed in to submit feedback.
              </p>
            )}

            {/* Type selector */}
            <div className="flex gap-1.5">
              {([
                { key: 'bug' as FeedbackCategory, label: 'Bug' },
                { key: 'feature' as FeedbackCategory, label: 'Feature' },
                { key: 'performance' as FeedbackCategory, label: 'Slow' },
                { key: 'general' as FeedbackCategory, label: 'Other' },
              ]).map(({ key, label }) => (
                <button
                  key={key}
                  type="button"
                  onClick={() => setType(key)}
                  className={`flex-1 py-3 rounded-lg text-[10px] font-medium transition-all ${
                    type === key
                      ? 'bg-[var(--accent)] text-black shadow-md shadow-[var(--accent)]/20'
                      : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:text-white hover:bg-[var(--border-color)]'
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>

            {/* Message */}
            <div>
              <textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder={
                  type === 'bug'
                    ? 'What went wrong? Steps to reproduce...'
                    : type === 'feature'
                      ? 'What feature would you like?'
                      : type === 'performance'
                        ? 'What is slow? When does it happen?'
                        : 'How can we improve METARDU?'
                }
                rows={5}
                className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm resize-none focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
                required
                minLength={10}
                maxLength={2000}
              />
              <p className="text-[10px] text-[var(--text-muted)] mt-1 text-right">
                {message.length}/2000
              </p>
            </div>

            {/* Email (optional) */}
            <div>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                aria-label="Email (optional — for follow-up)"
                placeholder="Email (optional — for follow-up)"
                className="w-full bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-lg px-3 py-2 text-[var(--text-primary)] text-sm focus:border-[var(--accent)] focus:ring-1 focus:ring-[var(--accent)]/30 outline-none transition-all"
              />
            </div>

            {/* Error notice */}
            {error && (
              <p className="text-xs text-red-400 bg-red-500/10 rounded-lg p-2">
                {error}
              </p>
            )}

            {/* Submit */}
            <button
              type="submit"
              disabled={loading || !message.trim() || !session?.user}
              className="w-full py-2.5 bg-[var(--accent)] text-black font-bold rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-40 transition-colors text-sm"
            >
              {loading ? 'Sending...' : 'Submit Feedback'}
            </button>
          </form>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import DepartureWarning from './DepartureWarning'

interface ValidationResult {
  status: 'GREEN' | 'YELLOW' | 'RED' | 'ERROR' | null
  flags: string[]
  details?: Record<string, unknown>
  road_class?: string
  terrain?: string
}

export default function GeometryValidationPanel() {
  const [roadClass, setRoadClass] = useState('')
  const [terrain, setTerrain] = useState('flat')
  const [designSpeed, setDesignSpeed] = useState(80)
  const [gradient, setGradient] = useState(3)
  const [radius, setRadius] = useState(240)
  const [ssd, setSsd] = useState<number | ''>('')
  const [result, setResult] = useState<ValidationResult>({ status: null, flags: [] })
  const [loading, setLoading] = useState(false)

  const handleValidate = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/validate-geometry', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          road_class: roadClass || 'DR1',
          terrain,
          design_speed: designSpeed,
          proposed_gradient: gradient,
          proposed_radius: radius,
          proposed_ssd: ssd !== '' ? ssd : undefined,
        }),
      })
      const data = await res.json()
      setResult({ ...data, road_class: roadClass, terrain })
    } catch {
      setResult({ status: 'ERROR', flags: ['Failed to connect to validation service'] })
    } finally {
      setLoading(false)
    }
  }

  const statusColors: Record<string, string> = {
    GREEN: 'text-green-400',
    YELLOW: 'text-yellow-400',
    RED: 'text-red-400',
    ERROR: 'text-red-400',
  }
  const statusColor = result.status ? statusColors[result.status] || 'text-gray-400' : 'text-gray-400'

  return (
    <div className="bg-[var(--bg-secondary)] rounded-lg border border-[var(--border-color)] p-4 space-y-4">
      <h3 className="text-sm font-bold text-[var(--text-primary)]">Road Geometric Validation — RDM 1.3</h3>
      
      {result.status === 'RED' && <DepartureWarning result={result as any} />}

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="block text-xs text-[var(--text-secondary)] mb-1" htmlFor="road-class">Road Class</label>
          <select id="road-class" value={roadClass} onChange={e => setRoadClass(e.target.value)} className="w-full px-2 py-1.5 text-xs bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]">
            <option value="DR1">DR1 — Motorway</option>
            <option value="DR2">DR2 — Arterial</option>
            <option value="DR3">DR3 — Collector</option>
            <option value="DR4">DR4 — Minor Collector</option>
            <option value="DR5">DR5 — Major Local</option>
            <option value="DR6">DR6 — Minor Local</option>
            <option value="DR7">DR7 — Local Access</option>
            <option value="Urban_Arterial">Urban Arterial</option>
            <option value="Urban_Collector">Urban Collector</option>
            <option value="Urban_Local">Urban Local</option>
          </select>
        </div>
        <div>
          <label className="block text-xs text-[var(--text-secondary)] mb-1" htmlFor="terrain">Terrain</label>
          <select id="terrain" value={terrain} onChange={e => setTerrain(e.target.value)} className="w-full px-2 py-1.5 text-xs bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]">
            <option value="flat">Flat</option>
            <option value="rolling">Rolling</option>
            <option value="mountainous">Mountainous</option>
            <option value="escarpment">Escarpment</option>
          </select>
        </div>
        <div>
          <label className="block text-xs text-[var(--text-secondary)] mb-1" htmlFor="design-speed-km-h">Design Speed (km/h)</label>
          <input id="design-speed-km-h" aria-label="Design Speed (km/h)" type="number" value={designSpeed} onChange={e => setDesignSpeed(Number(e.target.value))} className="w-full px-2 py-1.5 text-xs bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-secondary)] mb-1" htmlFor="proposed-gradient">Proposed Gradient (%)</label>
          <input id="proposed-gradient" aria-label="Proposed Gradient (%)" type="number" value={gradient} onChange={e => setGradient(Number(e.target.value))} step="0.1" className="w-full px-2 py-1.5 text-xs bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-secondary)] mb-1" htmlFor="proposed-radius-m">Proposed Radius (m)</label>
          <input id="proposed-radius-m" aria-label="Proposed Radius (m)" type="number" value={radius} onChange={e => setRadius(Number(e.target.value))} className="w-full px-2 py-1.5 text-xs bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
        </div>
        <div>
          <label className="block text-xs text-[var(--text-secondary)] mb-1" htmlFor="stop-sight-dist-m-opt">Stop Sight Dist. (m, opt.)</label>
          <input aria-label="Stop Sight Dist. (m, opt.)" type="number" value={ssd} onChange={e => setSsd(e.target.value !== '' ? Number(e.target.value) : '')} className="w-full px-2 py-1.5 text-xs bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
        </div>
      </div>

      <button onClick={handleValidate} disabled={loading} className="w-full px-3 py-2 text-xs bg-amber-500 text-black font-bold rounded hover:bg-amber-400 disabled:opacity-50">
        {loading ? 'Validating...' : 'Validate Geometry (RDM 1.3)'}
      </button>

      {result.status && result.status !== 'ERROR' && (
        <div className="text-center">
          <span className={`text-2xl font-bold ${statusColor}`}>{result.status}</span>
        </div>
      )}

      {result.flags.length > 0 && (
        <ul className="space-y-1">
          {result.flags.map((flag, i) => (
            <li key={`${flag}-${i}`} className={`text-xs px-2 py-1 rounded ${result.status === 'RED' ? 'bg-red-900/20 text-red-300' : result.status === 'YELLOW' ? 'bg-yellow-900/20 text-yellow-300' : 'bg-green-900/20 text-green-300'}`}>
              {flag}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

/**
 * METARDU — Instrument Connection Panel
 * =======================================
 * React component providing a UI to connect to surveying instruments
 * via Web Serial API or Bluetooth LE. Includes:
 *
 * - Transport selector (USB Serial / Bluetooth LE)
 * - Instrument preset selector (Leica, Trimble, Topcon, etc.)
 * - Custom baud rate / serial config
 * - Connection status indicator with live stats
 * - Real-time streaming point display
 * - Points table with count
 * - Import streamed points to current project
 *
 * The BLE path uses @capacitor-community/bluetooth-le on native
 * and Web Bluetooth API in the browser, with NUS + Location+NMEA
 * service support for surveying instruments.
 */

'use client'

import { useState, useCallback } from 'react'
import { useInstrumentConnection, type StreamedPoint } from '@/hooks/useInstrumentConnection'
import { INSTRUMENT_PRESETS, BRAND_INFO, type InstrumentBrand } from '@/lib/serial'
import {
  Cable,
  Wifi,
  WifiOff,
  Radio,
  Circle,
  Download,
  Settings,
  Trash2,
  Satellite,
  Crosshair,
  Activity,
  ChevronDown,
  ChevronUp,
  Target,
  RotateCcw,
  Ruler,
  Play,
  Square,
  Bluetooth,
  BluetoothOff,
  Usb,
} from 'lucide-react'
import { Capacitor } from '@capacitor/core'
import { WebBluetoothGNSS } from '@/lib/gnss/bluetooth'
import { CapacitorBLEGNSS, type CapacitorGNSSDevice } from '@/lib/gnss/capacitor-ble'
import { useInstrumentStore, type InstrumentDevice, type ConnectionTransport } from '@/stores/instrumentStore'
import type { NMEAPosition } from '@/lib/gnss/nmea-parser'

type TransportMode = 'serial' | 'ble'

interface InstrumentConnectionPanelProps {
  /** Called when user clicks "Import Points" to add streamed points to the project */
  onImportPoints?: (points: StreamedPoint[]) => void
  /** Called when a new point is received in real-time */
  onPointReceived?: (point: StreamedPoint) => void
  /** Default transport mode (auto-detected if not specified) */
  defaultTransport?: TransportMode
  className?: string
}

export function InstrumentConnectionPanel({
  onImportPoints,
  onPointReceived,
  defaultTransport,
  className = '',
}: InstrumentConnectionPanelProps) {
  const {
    connect,
    connectWithPreset,
    disconnect,
    status,
    isStreaming,
    isSupported: isSerialSupported,
    instrumentInfo,
    points,
    lastPoint,
    messagesParsed,
    errorCount,
    clearPoints,
    sendCommand: hookSendCommand,
    error,
  } = useInstrumentConnection()

  // Instrument store for BLE state
  const instrumentStore = useInstrumentStore()

  // Transport mode
  const isNative = typeof window !== 'undefined' && Capacitor.isNativePlatform()
  const [transportMode, setTransportMode] = useState<TransportMode>(
    defaultTransport || (isNative ? 'ble' : 'serial')
  )
  const [bleConnecting, setBleConnecting] = useState(false)
  const [bleError, setBleError] = useState<string | null>(null)
  const [bleScannedDevices, setBleScannedDevices] = useState<CapacitorGNSSDevice[]>([])
  const [bleSelectedDevice, setBleSelectedDevice] = useState<string | null>(null)
  const [bleService, setBleService] = useState<CapacitorBLEGNSS | WebBluetoothGNSS | null>(null)

  const isSupported = transportMode === 'ble' ? true : isSerialSupported

  const [showConfig, setShowConfig] = useState(false)
  const [selectedPreset, setSelectedPreset] = useState('generic-gnss')
  const [customBaud, setCustomBaud] = useState('9600')
  const [connecting, setConnecting] = useState(false)
  const [isTracking, setIsTracking] = useState(false)

  // Determine brand from preset key
  const getBrandFromPresetKey = (key: string): InstrumentBrand => {
    if (key.startsWith('leica')) return 'leica'
    if (key.startsWith('topcon')) return 'topcon'
    if (key.startsWith('trimble')) return 'trimble'
    if (key.startsWith('sokkia')) return 'sokkia'
    return 'leica'
  }

  // Send a brand-specific instrument command
  const sendCommand = useCallback(async (commandType: string, ...args: unknown[]) => {
    try {
      await hookSendCommand(commandType, ...args)
    } catch (err) {
      console.error('Command failed:', err)
    }
  }, [hookSendCommand])

  const toggleTracking = useCallback(async () => {
    const commandType = isTracking ? 'stopTracking' : 'startTracking'
    await sendCommand(commandType)
    setIsTracking(!isTracking)
  }, [isTracking, sendCommand])

  const handleConnect = async () => {
    setConnecting(true)
    try {
      await connectWithPreset(selectedPreset)
    } catch {
      // Error is handled by the hook
    } finally {
      setConnecting(false)
    }
  }

  const handleCustomConnect = async () => {
    setConnecting(true)
    try {
      await connect({ baudRate: parseInt(customBaud, 10) || 9600 })
    } catch {
      // Error is handled by the hook
    } finally {
      setConnecting(false)
    }
  }

  const handleImport = () => {
    if (points.length > 0 && onImportPoints) {
      onImportPoints(points)
    }
  }

  // Status color mapping
  const statusColors: Record<string, string> = {
    disconnected: 'text-gray-400',
    connecting: 'text-yellow-400',
    connected: 'text-blue-400',
    streaming: 'text-green-400',
    error: 'text-red-400',
    reconnecting: 'text-orange-400',
  }

  const statusBgColors: Record<string, string> = {
    disconnected: 'bg-gray-500/20 border-gray-600/30',
    connecting: 'bg-yellow-500/10 border-yellow-500/30',
    connected: 'bg-blue-500/10 border-blue-500/30',
    streaming: 'bg-green-500/10 border-green-500/30',
    error: 'bg-red-500/10 border-red-500/30',
    reconnecting: 'bg-orange-500/10 border-orange-500/30',
  }

  // ─── BLE connection handlers ──────────────────────────
  const handleBleScan = useCallback(async () => {
    setBleError(null)
    try {
      let service: CapacitorBLEGNSS | WebBluetoothGNSS
      if (isNative) {
        const ble = new CapacitorBLEGNSS()
        await ble.initialize()
        service = ble
      } else {
        service = new WebBluetoothGNSS()
      }
      setBleService(service)

      if (isNative && service instanceof CapacitorBLEGNSS) {
        const devices = await service.scanForDevices(5000)
        setBleScannedDevices(devices)
      } else if (service instanceof WebBluetoothGNSS) {
        const devices = await service.scanForDevices()
        setBleScannedDevices(
          devices.map((d) => ({
            deviceId: d.id,
            name: d.name,
            type: d.type === 'generic' ? 'unknown' as const : undefined,
          }))
        )
      }
    } catch (err) {
      setBleError((err as Error).message)
    }
  }, [isNative])

  const handleBleConnect = useCallback(async () => {
    if (!bleService || !bleSelectedDevice) return
    setBleConnecting(true)
    setBleError(null)
    try {
      // Set up position + connection callbacks before connecting
      bleService.onPosition((pos: NMEAPosition) => {
        instrumentStore.addPoint({
          id: `ble-${Date.now()}`,
          pointName: `PT${instrumentStore.points.length + 1}`,
          latitude: pos.latitude,
          longitude: pos.longitude,
          northing: 0,
          easting: 0,
          elevation: pos.altitude,
          timestamp: pos.timestamp,
          source: pos.quality >= 4 ? 'nmea' : 'nmea',
          quality: pos.quality,
          satellites: pos.satellites,
          hdop: pos.hdop,
        })
      })

      bleService.onConnectionChange((connected, err) => {
        if (connected) {
          const transport: ConnectionTransport = isNative ? 'capacitor-ble' : 'web-bluetooth'
          const device: InstrumentDevice = {
            id: bleSelectedDevice,
            name: bleScannedDevices.find(d => d.deviceId === bleSelectedDevice)?.name || 'Unknown',
            kind: 'gnss-receiver',
            transport,
          }
          instrumentStore.setConnected(device, transport)
          instrumentStore.setInstrumentInfo({
            manufacturer: device.name.split(' ')[0],
            protocol: 'nmea',
          })
        } else {
          instrumentStore.setDisconnected()
          if (err) setBleError(err)
        }
      })

      await bleService.connect(bleSelectedDevice)
    } catch (err) {
      setBleError((err as Error).message)
    } finally {
      setBleConnecting(false)
    }
  }, [bleService, bleSelectedDevice, bleScannedDevices, isNative, instrumentStore])

  const handleBleDisconnect = useCallback(async () => {
    if (bleService) {
      try {
        await bleService.disconnect()
      } catch { /* ignore */ }
    }
    instrumentStore.setDisconnected()
    setBleScannedDevices([])
    setBleSelectedDevice(null)
    setBleError(null)
  }, [bleService, instrumentStore])

  if (!isSupported && transportMode === 'serial') {
    return (
      <div className={`rounded-lg border border-yellow-600/30 bg-yellow-900/10 p-4 ${className}`}>
        <div className="flex items-center gap-2 mb-2">
          <WifiOff className="w-4 h-4 text-yellow-400" />
          <span className="text-sm font-medium text-yellow-300">Browser Not Supported</span>
        </div>
        <p className="text-xs text-yellow-200/70">
          The Web Serial API requires Google Chrome or Microsoft Edge.
          Switch to Bluetooth LE mode or use a supported browser.
        </p>
        <button
          onClick={() => setTransportMode('ble')}
          className="mt-2 text-xs text-blue-400 hover:text-blue-300"
        >
          Switch to Bluetooth LE →
        </button>
      </div>
    )
  }

  return (
    <div className={`rounded-lg border ${statusBgColors[status] || 'bg-gray-900/50 border-gray-700/50'} ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between p-3 border-b border-white/5">
        <div className="flex items-center gap-2">
          {transportMode === 'serial' ? (
            <Cable className="w-4 h-4 text-blue-400" />
          ) : (
            <Bluetooth className="w-4 h-4 text-blue-400" />
          )}
          <span className="text-sm font-medium">Instrument Connection</span>
        </div>
        <div className="flex items-center gap-2">
          {/* Transport toggle */}
          <div className="flex bg-black/20 rounded-md p-0.5">
            <button
              onClick={() => setTransportMode('serial')}
              className={`flex items-center gap-1 px-2 py-1 rounded text-[10px] transition-colors ${
                transportMode === 'serial'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-400 hover:text-gray-300'
              }`}
              title="USB Serial"
            >
              <Usb className="w-3 h-3" />
              Serial
            </button>
            <button
              onClick={() => setTransportMode('ble')}
              className={`flex items-center gap-1 px-2 py-1 rounded text-[10px] transition-colors ${
                transportMode === 'ble'
                  ? 'bg-blue-600 text-white'
                  : 'text-gray-400 hover:text-gray-300'
              }`}
              title="Bluetooth LE"
            >
              <Bluetooth className="w-3 h-3" />
              BLE
            </button>
          </div>
          <Circle
            className={`w-2 h-2 ${isStreaming ? 'fill-green-400 text-green-400 animate-pulse' : statusColors[status]}`}
          />
          <span className={`text-xs capitalize ${statusColors[status]}`}>
            {status === 'streaming' ? 'Live' : status}
          </span>
        </div>
      </div>

      <div className="p-3 space-y-3">
        {/* BLE Error */}
        {bleError && transportMode === 'ble' && (
          <p className="text-xs text-red-400 bg-red-900/20 rounded px-2 py-1">
            {bleError}
          </p>
        )}

        {/* ── BLE Mode ── */}
        {transportMode === 'ble' && status === 'disconnected' && (
          <>
            {!bleSelectedDevice && bleScannedDevices.length === 0 && (
              <button
                onClick={handleBleScan}
                className="w-full flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-500 text-white text-xs font-medium rounded-md px-4 py-2.5 transition-colors"
              >
                <Bluetooth className="w-3 h-3" />
                Scan for BLE Instruments
              </button>
            )}

            {bleScannedDevices.length > 0 && !bleSelectedDevice && (
              <div className="space-y-1.5">
                <div className="text-[9px] text-gray-400 uppercase tracking-wider">
                  Found {bleScannedDevices.length} device{bleScannedDevices.length !== 1 ? 's' : ''}
                </div>
                {bleScannedDevices.map((device) => (
                  <button
                    key={device.deviceId}
                    onClick={() => setBleSelectedDevice(device.deviceId)}
                    className="w-full p-2 text-left bg-black/20 border border-white/5 rounded-md hover:border-blue-500/30 transition-colors"
                  >
                    <div className="text-xs font-medium">{device.name}</div>
                    <div className="text-[9px] text-gray-400">
                      {device.deviceId.slice(0, 12)}… • {device.type || 'unknown'} • RSSI: {device.rssi ?? '—'}
                    </div>
                  </button>
                ))}
                <button
                  onClick={handleBleScan}
                  className="text-[9px] text-blue-400 hover:text-blue-300"
                >
                  Rescan
                </button>
              </div>
            )}

            {bleSelectedDevice && (
              <div className="space-y-2">
                <div className="p-2 bg-black/20 rounded-md">
                  <div className="text-xs font-medium">
                    {bleScannedDevices.find(d => d.deviceId === bleSelectedDevice)?.name || 'Unknown'}
                  </div>
                  <div className="text-[9px] text-gray-400">{bleSelectedDevice.slice(0, 16)}…</div>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={handleBleConnect}
                    disabled={bleConnecting}
                    className="flex-1 flex items-center justify-center gap-1 bg-green-600 hover:bg-green-500 disabled:bg-green-600/50 text-white text-xs font-medium rounded-md px-3 py-2 transition-colors"
                  >
                    {bleConnecting ? (
                      <><Activity className="w-3 h-3 animate-spin" /> Connecting…</>
                    ) : (
                      <><Bluetooth className="w-3 h-3" /> Connect</>
                    )}
                  </button>
                  <button
                    onClick={() => setBleSelectedDevice(null)}
                    className="px-3 py-2 text-xs text-gray-400 border border-white/10 rounded-md"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}
          </>
        )}

        {/* BLE Connected State */}
        {transportMode === 'ble' && (status === 'connected' || status === 'streaming') && instrumentStore.device && (
          <>
            <div className="p-2 bg-green-500/10 border border-green-500/20 rounded-md">
              <div className="flex items-center gap-2">
                <Bluetooth className="w-3 h-3 text-green-400" />
                <span className="text-xs font-medium text-green-300">{instrumentStore.device.name}</span>
                <span className="text-[9px] text-gray-400 ml-auto">BLE</span>
              </div>
            </div>
            <div className="grid grid-cols-3 gap-2">
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-blue-300">{instrumentStore.points.length}</div>
                <div className="text-[9px] text-gray-400 uppercase">Points</div>
              </div>
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-green-300">{instrumentStore.metrics.messagesParsed}</div>
                <div className="text-[9px] text-gray-400 uppercase">Messages</div>
              </div>
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-orange-300">{instrumentStore.metrics.errorsCount}</div>
                <div className="text-[9px] text-gray-400 uppercase">Errors</div>
              </div>
            </div>
            {instrumentStore.latestPoint && (
              <div className="bg-black/20 rounded-md p-2 border border-green-500/20">
                <div className="flex items-center gap-1 mb-1">
                  <Crosshair className="w-3 h-3 text-green-400" />
                  <span className="text-xs font-medium text-green-300">Latest Reading</span>
                </div>
                <div className="text-[9px] font-mono text-gray-300">
                  Lat: {instrumentStore.latestPoint.latitude.toFixed(7)} Lon: {instrumentStore.latestPoint.longitude.toFixed(7)}
                </div>
              </div>
            )}
            <div className="flex gap-2">
              <button
                onClick={() => handleBleDisconnect()}
                className="flex-1 flex items-center justify-center gap-1 bg-red-900/30 hover:bg-red-900/50 border border-red-700/30 text-red-300 text-xs rounded-md px-3 py-2 transition-colors"
              >
                <BluetoothOff className="w-3 h-3" />
                Disconnect
              </button>
              <button
                onClick={handleImport}
                disabled={instrumentStore.points.length === 0}
                className="flex-1 flex items-center justify-center gap-1 bg-green-900/30 hover:bg-green-900/50 border border-green-700/30 disabled:opacity-40 text-green-300 text-xs rounded-md px-3 py-2 transition-colors"
              >
                <Download className="w-3 h-3" />
                Import ({instrumentStore.points.length})
              </button>
            </div>
          </>
        )}

        {/* ── Serial Mode (existing UI) ── */}
        {transportMode === 'serial' && status === 'disconnected' && (
          <>
            <div>
              <label className="text-xs text-gray-400 uppercase tracking-wider mb-1 block" htmlFor="instrument-preset">
                Instrument Preset
              </label>
              <select id="instrument-preset"
                value={selectedPreset}
                onChange={(e) => setSelectedPreset(e.target.value)}
                className="w-full bg-black/30 border border-white/10 rounded-md px-3 py-2 text-xs focus:outline-none focus:border-blue-500/50"
              >
                {Object.entries(INSTRUMENT_PRESETS).map(([key, preset]) => (
                  <option key={key} value={key}>
                    {preset.name} ({preset.config.baudRate} baud)
                  </option>
                ))}
              </select>
            </div>

            {/* Custom Config Toggle */}
            <button
              onClick={() => setShowConfig(!showConfig)}
              className="flex items-center gap-1 text-xs text-gray-400 hover:text-gray-300 transition-colors"
            >
              <Settings className="w-3 h-3" />
              Advanced Configuration
              {showConfig ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
            </button>

            {showConfig && (
              <div className="space-y-2 p-2 rounded-md bg-black/20 border border-white/5">
                <div>
                  <label className="text-xs text-gray-400 mb-1 block" htmlFor="baud-rate">Baud Rate</label>
                  <select
                    value={customBaud}
                    onChange={(e) => setCustomBaud(e.target.value)}
                    className="w-full bg-black/30 border border-white/10 rounded px-2 py-1 text-xs"
                  >
                    {[4800, 9600, 19200, 38400, 57600, 115200].map(rate => (
                      <option key={rate} value={rate}>{rate}</option>
                    ))}
                  </select>
                </div>
                <button
                  onClick={handleCustomConnect}
                  disabled={connecting}
                  className="w-full text-xs text-blue-400 hover:text-blue-300 py-1"
                >
                  Connect with Custom Settings
                </button>
              </div>
            )}

            {/* Connect Button */}
            <button
              onClick={handleConnect}
              disabled={connecting}
              className="w-full flex items-center justify-center gap-2 bg-blue-600 hover:bg-blue-500 disabled:bg-blue-600/50 text-white text-xs font-medium rounded-md px-4 py-2.5 transition-colors"
            >
              {connecting ? (
                <>
                  <Activity className="w-3 h-3 animate-spin" />
                  Connecting...
                </>
              ) : (
                <>
                  <Cable className="w-3 h-3" />
                  Connect Instrument
                </>
              )}
            </button>

            {error && (
              <p className="text-xs text-red-400 bg-red-900/20 rounded px-2 py-1">
                {error}
              </p>
            )}
          </>
        )}

        {/* Connected / Streaming State — Serial mode only (BLE has its own above) */}
        {transportMode === 'serial' && (status === 'connected' || status === 'streaming') && (
          <>
            {/* Stats Grid */}
            <div className="grid grid-cols-3 gap-2">
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-blue-300">{points.length}</div>
                <div className="text-[9px] text-gray-400 uppercase">Points</div>
              </div>
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-green-300">{messagesParsed}</div>
                <div className="text-[9px] text-gray-400 uppercase">Messages</div>
              </div>
              <div className="bg-black/20 rounded-md p-2 text-center">
                <div className="text-lg font-mono font-bold text-orange-300">{errorCount}</div>
                <div className="text-[9px] text-gray-400 uppercase">Errors</div>
              </div>
            </div>

            {/* Instrument Info */}
            {instrumentInfo && (
              <div className="flex items-center gap-2 bg-black/20 rounded-md px-3 py-2">
                <Satellite className="w-3 h-3 text-purple-400" />
                <div>
                  <div className="text-xs font-medium">{instrumentInfo.manufacturer}</div>
                  <div className="text-[9px] text-gray-400">
                    Protocol: {instrumentInfo.protocol.toUpperCase()}
                    {instrumentInfo.model && ` / ${instrumentInfo.model}`}
                  </div>
                </div>
              </div>
            )}

            {/* Last Point Preview */}
            {lastPoint && (
              <div className="bg-black/20 rounded-md p-2 border border-green-500/20">
                <div className="flex items-center gap-1 mb-1">
                  <Crosshair className="w-3 h-3 text-green-400" />
                  <span className="text-xs font-medium text-green-300">
                    Latest: {lastPoint.pointName}
                  </span>
                </div>
                {lastPoint.source === 'nmea' ? (
                  <div className="text-[9px] font-mono text-gray-300 space-y-0.5">
                    <div>Lat: {lastPoint.latitude.toFixed(8)}&deg; Lng: {lastPoint.longitude.toFixed(8)}&deg;</div>
                    <div>Elev: {lastPoint.elevation !== null ? `${lastPoint.elevation.toFixed(3)}m` : 'N/A'}</div>
                    <div className="text-gray-400">
                      Quality: {lastPoint.quality} / Satellites: {lastPoint.satellites} / HDOP: {lastPoint.hdop?.toFixed(1)}
                    </div>
                  </div>
                ) : (
                  <div className="text-[9px] font-mono text-gray-300 space-y-0.5">
                    <div>N: {lastPoint.northing.toFixed(4)} E: {lastPoint.easting.toFixed(4)}</div>
                    {lastPoint.elevation !== null && <div>Elev: {lastPoint.elevation.toFixed(4)}m</div>}
                  </div>
                )}
              </div>
            )}

            {/* Instrument Commands */}
            <div className="space-y-1.5">
              <div className="text-[9px] text-gray-400 uppercase tracking-wider">Quick Commands</div>
              <div className="grid grid-cols-4 gap-1.5">
                <button
                  onClick={() => sendCommand('measureAndRecord')}
                  className="flex flex-col items-center gap-0.5 bg-blue-900/20 hover:bg-blue-900/40 border border-blue-700/20 text-blue-300 rounded-md px-2 py-1.5 text-[9px] transition-colors"
                  title="Measure and Record"
                >
                  <Target className="w-3.5 h-3.5" />
                  Measure
                </button>
                <button
                  onClick={() => sendCommand('getAngles')}
                  className="flex flex-col items-center gap-0.5 bg-purple-900/20 hover:bg-purple-900/40 border border-purple-700/20 text-purple-300 rounded-md px-2 py-1.5 text-[9px] transition-colors"
                  title="Read Angles"
                >
                  <RotateCcw className="w-3.5 h-3.5" />
                  Angles
                </button>
                <button
                  onClick={() => sendCommand('getCoordinate')}
                  className="flex flex-col items-center gap-0.5 bg-green-900/20 hover:bg-green-900/40 border border-green-700/20 text-green-300 rounded-md px-2 py-1.5 text-[9px] transition-colors"
                  title="Get Coordinate"
                >
                  <Ruler className="w-3.5 h-3.5" />
                  Coord
                </button>
                <button
                  onClick={() => toggleTracking()}
                  className={`flex flex-col items-center gap-0.5 rounded-md px-2 py-1.5 text-[9px] transition-colors ${
                    isTracking
                      ? 'bg-orange-900/30 border border-orange-500/30 text-orange-300'
                      : 'bg-gray-800/40 border border-gray-600/20 text-gray-300'
                  }`}
                  title={isTracking ? 'Stop Tracking' : 'Start Tracking'}
                >
                  {isTracking ? <Square className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5" />}
                  {isTracking ? 'Stop' : 'Track'}
                </button>
              </div>
              <div className="grid grid-cols-2 gap-1.5">
                <button
                  onClick={() => sendCommand('setPrismTarget', 0)}
                  className="bg-gray-800/30 hover:bg-gray-700/40 border border-gray-600/20 text-gray-300 rounded-md px-2 py-1 text-[9px] transition-colors"
                >
                  Prism Target
                </button>
                <button
                  onClick={() => sendCommand('setRLTarget')}
                  className="bg-gray-800/30 hover:bg-gray-700/40 border border-gray-600/20 text-gray-300 rounded-md px-2 py-1 text-[9px] transition-colors"
                >
                  Reflectorless
                </button>
              </div>
              {selectedPreset && (
                <div className="text-[8px] text-gray-500">
                  {BRAND_INFO[getBrandFromPresetKey(selectedPreset)]?.protocol || 'Auto-detect'}
                </div>
              )}
            </div>

            {/* Action Buttons */}
            <div className="flex gap-2">
              <button
                onClick={disconnect}
                className="flex-1 flex items-center justify-center gap-1 bg-red-900/30 hover:bg-red-900/50 border border-red-700/30 text-red-300 text-xs rounded-md px-3 py-2 transition-colors"
              >
                <WifiOff className="w-3 h-3" />
                Disconnect
              </button>
              <button
                onClick={handleImport}
                disabled={points.length === 0}
                className="flex-1 flex items-center justify-center gap-1 bg-green-900/30 hover:bg-green-900/50 border border-green-700/30 disabled:opacity-40 text-green-300 text-xs rounded-md px-3 py-2 transition-colors"
              >
                <Download className="w-3 h-3" />
                Import ({points.length})
              </button>
              <button
                onClick={clearPoints}
                disabled={points.length === 0}
                className="flex items-center justify-center bg-gray-800 hover:bg-gray-700 border border-gray-600/30 disabled:opacity-40 text-gray-300 text-xs rounded-md px-2 py-2 transition-colors"
                title="Clear points"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import { computeLevelBook } from '@/lib/computations/traverseEngine'
import { printLevelBookSheet, type LevelBookPrintInput } from '@/lib/print/levelBookPrint'
import { PrintMetaPanel, defaultPrintMeta, type PrintMeta } from '@/components/shared/PrintMetaPanel'

interface LevelBookProps {
  projectId?: string
}

export default function LevelBook({ projectId }: LevelBookProps) {
  const [rows, setRows] = useState<Array<{
    station: string; bs: string; is: string; fs: string; distance: string; remarks: string
  }>>([
    { station: 'BM1', bs: '1.523', is: '', fs: '', distance: '', remarks: 'Benchmark' },
    { station: '1',   bs: '',      is: '', fs: '1.234', distance: '', remarks: '' },
    { station: '2',   bs: '',      is: '1.456', fs: '', distance: '', remarks: 'IS' },
    { station: '3',   bs: '',      is: '', fs: '1.789', distance: '', remarks: '' },
    { station: '4',   bs: '',      is: '1.234', fs: '', distance: '', remarks: 'IS' },
    { station: '5',   bs: '',      is: '', fs: '1.567', distance: '', remarks: '' },
  ])
  const [openingRL,   setOpeningRL]   = useState('100.000')
  const [closingRL,   setClosingRL]   = useState('')
  const [distanceKm,  setDistanceKm]  = useState('0.5')
  const [method,      setMethod]      = useState<'rise_and_fall' | 'height_of_collimation'>('rise_and_fall')
  const [result,      setResult]      = useState<ReturnType<typeof computeLevelBook> | null>(null)
  const [error,       setError]       = useState('')
  const [activeTab,   setActiveTab]   = useState<'input' | 'compute' | 'print'>('input')
  const [printMeta,   setPrintMeta]   = useState<PrintMeta>(defaultPrintMeta)

  const addRow = () => setRows(prev => [
    ...prev,
    { station: String(prev.length + 1), bs: '', is: '', fs: '', distance: '', remarks: '' }
  ])

  const removeRow = (i: number) => setRows(prev => prev.filter((_, idx) => idx !== i))

  const updateRow = (i: number, field: string, value: string) =>
    setRows(prev => prev.map((r, idx) => idx === i ? { ...r, [field]: value } : r))

  const handleCompute = () => {
    setError('')
    if (!openingRL) { setError('Enter opening benchmark RL'); return }
    const obsRows = rows.map(r => ({
      station:  r.station,
      bs:       r.bs       ? parseFloat(r.bs)       : undefined,
      is:       r.is       ? parseFloat(r.is)        : undefined,
      fs:       r.fs       ? parseFloat(r.fs)        : undefined,
      distance: r.distance ? parseFloat(r.distance)  : undefined,
      remarks:  r.remarks,
    }))
    try {
      const res = computeLevelBook({
        openingRL:  parseFloat(openingRL),
        closingRL:  closingRL ? parseFloat(closingRL) : undefined,
        distanceKm: parseFloat(distanceKm) || 0.5,
        method,
        rows: obsRows,
      })
      setResult(res)
      setActiveTab('compute')
    } catch (err: unknown) {
      setError((err as Error).message || 'Computation failed')
    }
  }

  const handlePrint = () => {
    if (!result) return
    const inp: LevelBookPrintInput = {
      result,
      meta: { ...printMeta, title: `Level Book — ${method === 'rise_and_fall' ? 'Rise & Fall' : 'Height of Collimation'}` }
    }
    printLevelBookSheet(inp)
  }

  // ── RENDER ─────────────────────────────────────────────────────────────────
  return (
    <div className="space-y-4">

      {/* Tabs + Method switch */}
      <div className="flex items-center gap-2 border-b border-[var(--border-color)] pb-2 flex-wrap">
        {(['input', 'compute', 'print'] as const).map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)}
            className={`px-3 py-1.5 rounded text-sm font-medium capitalize transition-colors ${
              activeTab === tab
                ? 'bg-[var(--accent)] text-black'
                : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:bg-[var(--border-hover)]'
            }`}>
            {tab === 'input' ? 'Field Book' : tab === 'compute' ? 'Results' : 'Print'}
          </button>
        ))}
        <div className="flex-1" />
        <button
          onClick={() => { setMethod('rise_and_fall'); setResult(null) }}
          className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
            method === 'rise_and_fall'
              ? 'bg-[var(--accent)] text-black'
              : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'
          }`}>
          Rise &amp; Fall
        </button>
        <button
          onClick={() => { setMethod('height_of_collimation'); setResult(null) }}
          className={`px-3 py-1.5 rounded text-xs font-medium transition-colors ${
            method === 'height_of_collimation'
              ? 'bg-[var(--accent)] text-black'
              : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'
          }`}>
          Height of Collimation
        </button>
      </div>

      {error && (
        <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{error}</div>
      )}

      {/* ── INPUT TAB ──────────────────────────────────────────────────────── */}
      {activeTab === 'input' && (
        <div className="space-y-4">
          {/* Setup fields */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 p-3 md:p-4 bg-[var(--bg-tertiary)]/50 rounded border border-[var(--border-color)]">
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="opening-bm-rl-m">Opening BM RL (m)</label>
              <input id="opening-bm-rl-m" aria-label="Opening BM RL (m)" value={openingRL} onChange={e => setOpeningRL(e.target.value)}
                type="number" step="0.001"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="closing-bm-rl-m">Closing BM RL (m)</label>
              <input id="closing-bm-rl-m" value={closingRL} onChange={e => setClosingRL(e.target.value)}
                type="number" step="0.001" aria-label="Optional" placeholder="Optional"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="total-distance-km">Total Distance (km)</label>
              <input aria-label="Total Distance (km)" value={distanceKm} onChange={e => setDistanceKm(e.target.value)}
                type="number" step="0.001"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
            </div>
          </div>

          {/* Field book table */}
          <div className="overflow-x-auto -mx-4 px-4 sm:mx-0 sm:px-0">
            <table className="min-w-[700px] w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                  <th className="px-1.5 py-2 text-left text-[var(--text-muted)] w-8">#</th>
                  <th className="px-1.5 py-2 text-left text-[var(--text-secondary)]">Station</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">BS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">IS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">FS</th>
                  <th className="px-1.5 py-2 text-right text-[var(--text-secondary)]">Dist (m)</th>
                  <th className="px-1.5 py-2 text-left text-[var(--text-secondary)]">Remarks</th>
                  <th className="w-6"></th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row, i) => (
                  <tr key={row.station} className="border-b border-[var(--border-color)]/30">
                    <td className="px-1.5 py-1 text-[var(--text-muted)]">{i + 1}</td>
                    <td className="px-1 py-1">
                      <input value={row.station} onChange={e => updateRow(i, 'station', e.target.value)}
                        aria-label="BM1" placeholder="BM1"
                        className="w-full px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.bs} onChange={e => updateRow(i, 'bs', e.target.value)}
                        type="number" step="0.001" aria-label="0.000" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.is} onChange={e => updateRow(i, 'is', e.target.value)}
                        type="number" step="0.001" aria-label="0.000" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.fs} onChange={e => updateRow(i, 'fs', e.target.value)}
                        type="number" step="0.001" aria-label="0.000" placeholder="0.000"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.distance} onChange={e => updateRow(i, 'distance', e.target.value)}
                        type="number" step="0.01" aria-label="0.00" placeholder="0.00"
                        className="w-16 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td className="px-1 py-1">
                      <input value={row.remarks} onChange={e => updateRow(i, 'remarks', e.target.value)}
                        aria-label="IS / BM / CP" placeholder="IS / BM / CP"
                        className="w-full px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]" />
                    </td>
                    <td>
                      <button onClick={() => removeRow(i)}
                        className="text-red-400 hover:text-red-300 text-lg leading-none px-1">×</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <button onClick={addRow}
            className="px-3 py-1.5 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-xs">
            + Add Row
          </button>

          <div className="flex justify-end">
            <button onClick={handleCompute}
              className="px-6 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded text-sm">
              Compute Level Book →
            </button>
          </div>
        </div>
      )}

      {/* ── RESULTS TAB ────────────────────────────────────────────────────── */}
      {activeTab === 'compute' && result && (
        <div className="space-y-4">

          {/* Closure summary cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
              <p className="text-xs text-[var(--text-secondary)]">ΣBS</p>
              <p className="text-lg font-mono">{result.sumBS.toFixed(3)} m</p>
            </div>
            <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
              <p className="text-xs text-[var(--text-secondary)]">ΣFS</p>
              <p className="text-lg font-mono">{result.sumFS.toFixed(3)} m</p>
            </div>
            <div className={`rounded p-3 ${result.arithmeticPass ? 'bg-green-900/30' : 'bg-red-900/30'}`}>
              <p className="text-xs text-[var(--text-secondary)]">Arithmetic Check</p>
              <p className={`text-lg font-semibold ${result.arithmeticPass ? 'text-green-400' : 'text-red-400'}`}>
                {result.arithmeticPass ? 'PASS' : 'FAIL'}
              </p>
            </div>
            <div className={`rounded p-3 ${result.isAcceptable ? 'bg-green-900/30' : 'bg-red-900/30'}`}>
              <p className="text-xs text-[var(--text-secondary)]">Closure (10√K mm)</p>
              <p className={`text-lg font-semibold ${result.isAcceptable ? 'text-green-400' : 'text-red-400'}`}>
                {result.isAcceptable ? 'OK' : 'FAIL'}
              </p>
            </div>
          </div>

          <p className="text-xs text-[var(--text-muted)] font-mono">{result.formula}</p>

          {/* Results table — HPC not HI */}
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/50">
                  <th className="px-2 py-2 text-left">Station</th>
                  <th className="px-2 py-2 text-right">BS</th>
                  <th className="px-2 py-2 text-right">IS</th>
                  <th className="px-2 py-2 text-right">FS</th>
                  {/* HPC = Height of Plane of Collimation — British/East African convention */}
                  <th className="px-2 py-2 text-right">HPC (m)</th>
                  {method === 'rise_and_fall' && <th className="px-2 py-2 text-right">Rise</th>}
                  {method === 'rise_and_fall' && <th className="px-2 py-2 text-right">Fall</th>}
                  <th className="px-2 py-2 text-right">RL (m)</th>
                </tr>
              </thead>
              <tbody>
                {result.rows.map((row: any, i: number) => (
                  <tr key={`item-${i}`} className="border-b border-[var(--border-color)]/30">
                    <td className="px-2 py-1.5 font-mono">{row.station}</td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.bs !== undefined ? row.bs.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.is !== undefined ? row.is.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {row.fs !== undefined ? row.fs.toFixed(3) : ''}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono text-[var(--text-secondary)]">
                      {/* row.hi is the data property (Height of Collimation value); displayed as HPC */}
                      {row.hi !== undefined ? row.hi.toFixed(3) : ''}
                    </td>
                    {method === 'rise_and_fall' && (
                      <td className="px-2 py-1.5 text-right font-mono text-green-400">
                        {row.rise !== undefined ? row.rise.toFixed(3) : ''}
                      </td>
                    )}
                    {method === 'rise_and_fall' && (
                      <td className="px-2 py-1.5 text-right font-mono text-red-400">
                        {row.fall !== undefined ? row.fall.toFixed(3) : ''}
                      </td>
                    )}
                    <td className="px-2 py-1.5 text-right font-mono font-bold text-[var(--accent)]">
                      {row.rl !== undefined ? row.rl.toFixed(3) : ''}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex justify-between">
            <button onClick={() => setActiveTab('input')}
              className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm">
              ← Back to Input
            </button>
            <button onClick={() => setActiveTab('print')}
              className="px-5 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded text-sm">
              Print Sheet →
            </button>
          </div>
        </div>
      )}

      {/* ── PRINT TAB ──────────────────────────────────────────────────────── */}
      {activeTab === 'print' && (
        <div className="space-y-4">
          {!result && (
            <div className="p-4 bg-amber-900/20 border border-amber-700 rounded text-amber-300 text-sm">
              Compute the level book first (Field Book tab) before printing.
            </div>
          )}

          <PrintMetaPanel meta={printMeta} onChange={setPrintMeta} />

          <div className="p-4 bg-[var(--bg-tertiary)]/50 rounded border border-[var(--border-color)] text-sm space-y-1.5">
            <p className="font-semibold text-[var(--text-primary)]">The printed sheet will include:</p>
            <ul className="text-[var(--text-muted)] text-xs space-y-0.5 list-disc list-inside">
              <li>Standard 6-field document header (project · client · date · surveyor · reg/ISK · instrument)</li>
              <li>Table 1 — Field Observations (Station, BS, IS, FS, HPC, Rise, Fall, RL, Dist, Remarks)</li>
              <li>Table 2 — Arithmetic Checks &amp; Closure (ΣBS, ΣFS, ΣRise, ΣFall, 10√K misclosure)</li>
              <li>Surveyor&apos;s Certificate block — Survey Regulations 1994, Regulation 3(2)</li>
            </ul>
            <p className="text-xs text-[var(--text-muted)] font-mono mt-2">
              HPC = Height of Plane of Collimation (British/East African convention)
            </p>
          </div>

          <button
            onClick={handlePrint}
            disabled={!result}
            className="w-full py-3 bg-[var(--accent)] hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed text-black font-bold rounded text-sm">
            Print Level Book Computation Sheet
          </button>
        </div>
      )}
    </div>
  )
}

import Link from 'next/link'
import Image from 'next/image'

interface MetarduLogoProps {
  color?: string
  size?: number
  showWordmark?: boolean
  className?: string
}

/**
 * METARDU Logo Component
 *
 * Uses the official METARDU logo image (public/metardu-icon.png) — a
 * square PNG cropped from the original metardu-logo.jpg.
 *
 * The wordmark text color is controlled by the `color` prop.
 */
export default function MetarduLogo({
  color = 'currentColor',
  size = 32,
  showWordmark = true,
  className = '',
}: MetarduLogoProps) {
  return (
    <div className={`flex items-center gap-2 ${className}`}>
      {/* Official METARDU logo image */}
      <Image
        src="/metardu-icon.png"
        alt="METARDU logo"
        width={size}
        height={size}
        className="shrink-0 rounded"
        priority
      />

      {showWordmark && (
        <span
          className="font-bold tracking-tight"
          style={{
            fontSize: `${size * 0.47}px`,
            letterSpacing: '0.05em',
            color: color === 'currentColor' ? 'inherit' : color,
          }}
        >
          METARDU
        </span>
      )}
    </div>
  )
}

'use client';

import { useEffect, useState } from 'react'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useSession } from 'next-auth/react'
import {
  FolderKanban, LayoutDashboard, MapPinned, UserRound, UsersRound, Wrench, FileText,
  CalendarDays, Radar, Store, ChevronRight, X, AlertTriangle, Clock,
  BookOpen, Compass, MapPin, ShieldCheck
} from 'lucide-react'
import { PRIMARY_NAV_ITEMS, isNavItemActive } from '@/lib/navigation-shell'

const iconMap: Record<string, any> = {
  dashboard: LayoutDashboard,
  projects: FolderKanban,
  tools: Wrench,
  map: MapPinned,
  reports: FileText,
  community: UsersRound,
  profile: UserRound,
}

/** Pages hidden from the bottom tab bar — shown in the "More" drawer */
const MORE_PAGES = [
  { href: '/fieldbook', label: 'Field Book', icon: BookOpen, color: 'text-orange-400' },
  { href: '/field', label: 'Field Mode', icon: Compass, color: 'text-cyan-400' },
  { href: '/beacons', label: 'Beacon Registry', icon: MapPin, color: 'text-amber-400' },
  { href: '/schedule', label: 'Job Schedule', icon: CalendarDays, color: 'text-blue-400' },
  { href: '/equipment', label: 'Equipment Tracker', icon: Radar, color: 'text-green-400' },
  { href: '/marketplace', label: 'Equipment Marketplace', icon: Store, color: 'text-amber-400' },
]

export default function MobileNav() {
  const pathname = usePathname()
  const [mounted, setMounted] = useState(false)
  const [showMore, setShowMore] = useState(false)
  const { data: session, status: authStatus } = useSession()
  const isAuthenticated = !!session

  useEffect(() => { setMounted(true) }, [])

  // Show the unified 5-item navigation + "More" button
  const mobileNavItems = PRIMARY_NAV_ITEMS

  // Check if current page is in the "More" drawer (for active highlighting)
  const isMoreActive = MORE_PAGES.some(p => pathname === p.href || pathname.startsWith(p.href + '/'))

  return (
    <>
      <nav
        className="fixed bottom-0 left-0 right-0 bg-[var(--bg-primary)] border-t border-[var(--border-color)] md:hidden z-50"
        style={{
          paddingBottom: 'env(safe-area-inset-bottom, 0px)',
          // AUDIT FIX (2026-07-05): Use real safe-area inset instead of CSS class
          // (the class was a no-op). On notched Android devices this prevents
          // the nav from being obscured by the gesture bar.
        }}
        role="navigation"
        aria-label="Primary mobile navigation"
      >
        <div className="flex justify-around items-stretch">
          {mobileNavItems.slice(0, 4).map((item) => {
            const isActive = isNavItemActive(pathname, item.href)
            const iconName = item.icon || item.href.replace('/', '')
            const Icon = iconMap[iconName] || LayoutDashboard
            return (
              <Link
                key={item.href}
                href={item.href}
                aria-current={isActive ? 'page' : undefined}
                // AUDIT FIX (2026-07-05): min-h-[48px] + py-3 to meet Android
                // Material Design tap target guideline (48dp minimum).
                className={`flex flex-col items-center justify-center gap-0.5 px-2 min-h-[48px] py-2 text-[10px] font-medium tracking-wide transition-colors min-w-0 flex-1 ${
                  isActive ? 'text-[var(--accent)]' : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
                }`}
              >
                <Icon className={`h-5 w-5 transition-colors ${isActive ? 'text-[var(--accent)]' : ''}`} strokeWidth={1.9} />
                <span className="truncate">{item.label}</span>
              </Link>
            )
          })}

          {/* Reports */}
          {(() => {
            const reportsItem = mobileNavItems[4]
            const isActive = isNavItemActive(pathname, reportsItem.href)
            const Icon = iconMap['reports'] || FileText
            return (
              <Link
                key={reportsItem.href}
                href={reportsItem.href}
                aria-current={isActive ? 'page' : undefined}
                className={`flex flex-col items-center justify-center gap-0.5 px-2 min-h-[48px] py-2 text-[10px] font-medium tracking-wide transition-colors min-w-0 flex-1 ${
                  isActive ? 'text-[var(--accent)]' : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
                }`}
              >
                <Icon className={`h-5 w-5 transition-colors ${isActive ? 'text-[var(--accent)]' : ''}`} strokeWidth={1.9} />
                <span className="truncate">{reportsItem.label}</span>
              </Link>
            )
          })()}

          {/* More button */}
          <button
            onClick={() => setShowMore(true)}
            aria-label="Show more navigation options"
            aria-expanded={showMore}
            className={`flex flex-col items-center justify-center gap-0.5 px-2 min-h-[48px] py-2 text-[10px] font-medium tracking-wide transition-colors min-w-0 flex-1 ${
              isMoreActive ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'
            }`}
          >
            <div className={`h-5 w-5 flex items-center justify-center ${isMoreActive ? 'text-[var(--accent)]' : ''}`}>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.9}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25H12" />
              </svg>
            </div>
            <span>More</span>
          </button>
        </div>
      </nav>

      {/* More Drawer */}
      {showMore && (
        <div className="fixed inset-0 z-[60] flex md:hidden" onKeyDown={(e) => { if (e.key === 'Escape') setShowMore(false) }}>
          {/* Backdrop */}
          <button type="button" aria-label="Close menu" tabIndex={-1} className="flex-1 bg-black/60 backdrop-blur-sm cursor-pointer border-0 p-0" onClick={() => setShowMore(false)} />

          {/* Panel slides up from bottom */}
          <div
            className="w-full bg-[var(--bg-primary)] border-t border-[var(--border-color)] rounded-t-2xl max-h-[70vh] overflow-y-auto animate-slide-up"
            onClick={e => e.stopPropagation()}
          >
            {/* Handle bar */}
            <div className="flex justify-center pt-3 pb-1">
              <div className="w-10 h-1 rounded-full bg-[var(--text-muted)]/30" />
            </div>

            {/* Header */}
            <div className="flex items-center justify-between px-5 py-3 border-b border-[var(--border-color)]">
              <h2 className="text-base font-semibold text-[var(--text-primary)]">More Tools</h2>
              <button onClick={() => setShowMore(false)} className="p-1 text-[var(--text-muted)] hover:text-[var(--text-primary)]">
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Quick Actions Section */}
            <div className="px-5 pt-4 pb-2">
              <p className="text-[10px] font-semibold text-[var(--text-muted)] uppercase tracking-[0.15em] mb-2">Field Operations</p>
              <div className="space-y-1">
                {MORE_PAGES.map((page) => {
                  const isActive = pathname === page.href || pathname.startsWith(page.href + '/')
                  return (
                    <Link
                      key={page.href}
                      href={page.href}
                      onClick={() => setShowMore(false)}
                      className={`flex items-center gap-3 px-3 py-3 rounded-xl transition-all ${
                        isActive
                          ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/20'
                          : 'hover:bg-[var(--bg-tertiary)] border border-transparent'
                      }`}
                    >
                      <div className={`w-9 h-9 rounded-lg flex items-center justify-center ${
                        isActive ? 'bg-[var(--accent)]/15' : 'bg-[var(--bg-tertiary)]'
                      }`}>
                        <page.icon className={`w-4.5 h-4.5 ${isActive ? 'text-[var(--accent)]' : page.color}`} strokeWidth={1.8} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <span className={`text-sm font-medium ${isActive ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>
                          {page.label}
                        </span>
                      </div>
                      <ChevronRight className={`w-4 h-4 ${isActive ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'}`} />
                    </Link>
                  )
                })}
              </div>
            </div>

            {/* Admin Section (only for admin users) */}
            {mounted && isAuthenticated && (() => {
              const userRole = (session?.user as { role?: string })?.role
              const isAdmin = userRole === 'super_admin' || userRole === 'admin' || userRole === 'org_admin'
              if (!isAdmin) return null
              return (
                <div className="px-5 pt-4 pb-2">
                  <p className="text-[10px] font-semibold text-[var(--text-muted)] uppercase tracking-[0.15em] mb-2">Administration</p>
                  <div className="space-y-1">
                    <Link
                      href="/admin"
                      onClick={() => setShowMore(false)}
                      className={`flex items-center gap-3 px-3 py-3 rounded-xl transition-all ${
                        pathname === '/admin' || pathname.startsWith('/admin/')
                          ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/20'
                          : 'hover:bg-[var(--bg-tertiary)] border border-transparent'
                      }`}
                    >
                      <div className={`w-9 h-9 rounded-lg flex items-center justify-center ${
                        pathname === '/admin' ? 'bg-[var(--accent)]/15' : 'bg-[var(--bg-tertiary)]'
                      }`}>
                        <ShieldCheck className={`w-4.5 h-4.5 ${pathname === '/admin' ? 'text-[var(--accent)]' : 'text-[var(--accent)]'}`} strokeWidth={1.8} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <span className={`text-sm font-medium ${pathname === '/admin' ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>
                          Admin Dashboard
                        </span>
                      </div>
                      <ChevronRight className={`w-4 h-4 ${pathname === '/admin' ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'}`} />
                    </Link>
                  </div>
                </div>
              )
            })()}

            {/* Settings Section */}
            <div className="px-5 pt-4 pb-6">
              <p className="text-[10px] font-semibold text-[var(--text-muted)] uppercase tracking-[0.15em] mb-2">Settings</p>
              <div className="space-y-1">
                {[
                  { href: '/account', label: 'Account & Billing', icon: 'account' },
                  { href: '/pricing', label: 'Pricing Plans', icon: 'pricing' },
                  { href: '/docs', label: 'Documentation', icon: 'docs' },
                ].map((item) => (
                  <Link
                    key={item.href}
                    href={item.href}
                    onClick={() => setShowMore(false)}
                    className="flex items-center gap-3 px-3 py-3 rounded-xl hover:bg-[var(--bg-tertiary)] transition-all"
                  >
                    <div className="w-9 h-9 rounded-lg flex items-center justify-center bg-[var(--bg-tertiary)]">
                      <svg className="w-4 h-4 text-[var(--text-muted)]" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.8}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M9.594 3.94c.09-.542.56-.94 1.11-.94h2.593c.55 0 1.02.398 1.11.94l.213 1.281c.063.374.313.686.645.87.074.04.147.083.22.127.324.196.72.257 1.075.124l1.217-.456a1.125 1.125 0 011.37.49l1.296 2.247a1.125 1.125 0 01-.26 1.431l-1.003.827c-.293.24-.438.613-.431.992a6.759 6.759 0 010 .255c-.007.378.138.75.43.99l1.005.828c.424.35.534.954.26 1.43l-1.298 2.247a1.125 1.125 0 01-1.369.491l-1.217-.456c-.355-.133-.75-.072-1.076.124a6.57 6.57 0 01-.22.128c-.331.183-.581.495-.644.869l-.213 1.28c-.09.543-.56.941-1.11.941h-2.594c-.55 0-1.02-.398-1.11-.94l-.213-1.281c-.062-.374-.312-.686-.644-.87a6.52 6.52 0 01-.22-.127c-.325-.196-.72-.257-1.076-.124l-1.217.456a1.125 1.125 0 01-1.369-.49l-1.297-2.247a1.125 1.125 0 01.26-1.431l1.004-.827c.292-.24.437-.613.43-.992a6.932 6.932 0 010-.255c.007-.378-.138-.75-.43-.99l-1.004-.828a1.125 1.125 0 01-.26-1.43l1.297-2.247a1.125 1.125 0 011.37-.491l1.216.456c.356.133.751.072 1.076-.124.072-.044.146-.087.22-.128.332-.183.582-.495.644-.869l.214-1.281z" />
                        <path strokeLinecap="round" strokeLinejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                      </svg>
                    </div>
                    <span className="flex-1 text-sm text-[var(--text-primary)]">{item.label}</span>
                    <ChevronRight className="w-4 h-4 text-[var(--text-muted)]" />
                  </Link>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      <style jsx global>{`
        @keyframes slideUp {
          from {
            transform: translateY(100%);
            opacity: 0;
          }
          to {
            transform: translateY(0);
            opacity: 1;
          }
        }
        .animate-slide-up {
          animation: slideUp 0.25s ease-out;
        }
      `}</style>
    </>
  )
}

