  )
}

'use client';

import { useState } from 'react'
import { coordinateArea } from '@/lib/engine/area'
import { distanceBearing } from '@/lib/engine/distance'
import type { SurveyPoint } from '@/types/surveyPoint'

interface ParcelAreaModalProps {
  isOpen: boolean
  onClose: () => void
  points: SurveyPoint[]
  onAreaResult?: (result: { squareMeters: number; hectares: number; acres: number; perimeter: number }) => void
}

export default function ParcelAreaModal({ isOpen, onClose, points, onAreaResult }: ParcelAreaModalProps) {
  const [selectedPoints, setSelectedPoints] = useState<SurveyPoint[]>([])
  const [result, setResult] = useState<{
    areaSqm: number
    areaHa: number
    areaAcres: number
    perimeter: number
  } | null>(null)

  const handlePointClick = (point: SurveyPoint) => {
    // Check if clicking first point to close
    if (selectedPoints.length >= 3 && selectedPoints[0].id === point.id) {
      calculateArea()
      return
    }
    
    // Add point if not already selected
    if (!selectedPoints.some((p: any) => p.id === point.id)) {
      setSelectedPoints([...selectedPoints, point])
    }
  }

  const calculateArea = () => {
    if (selectedPoints.length < 3) return

    const coords = selectedPoints.map((p: any) => ({
      easting: p.easting,
      northing: p.northing
    }))

    const areaResult = coordinateArea(coords)
    setResult(areaResult)
    if (onAreaResult) {
      onAreaResult({
        squareMeters: areaResult.areaSqm,
        hectares: areaResult.areaHa,
        acres: areaResult.areaAcres,
        perimeter: areaResult.perimeter
      })
    }
  }

  const clearSelection = () => {
    setSelectedPoints([])
    setResult(null)
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/70" onClick={onClose}></div>
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6 w-full max-w-md">
        <h2 className="text-xl font-bold text-[var(--text-primary)] mb-4">Compute Parcel Area</h2>

        <p className="text-[var(--text-secondary)] text-sm mb-4">
          Click points on the map in boundary order. Click the first point again to close the polygon.
        </p>

        {/* Selected points list */}
        <div className="mb-4">
          <div className="flex justify-between items-center mb-2">
            <span className="text-sm text-[var(--text-primary)]">Selected Points ({selectedPoints.length})</span>
            <button
              onClick={clearSelection}
              className="text-xs text-red-400 hover:text-red-300"
            >
              Clear
            </button>
          </div>
          <div className="flex flex-wrap gap-2">
            {selectedPoints.map((p, i) => (
              <span
                key={p.id}
                className="px-2 py-1 bg-[var(--bg-tertiary)] rounded text-xs font-mono text-[var(--text-primary)]"
              >
                {i + 1}. {p.name}
              </span>
            ))}
          </div>
        </div>

        {/* Result */}
        {result && (
          <div className="mb-4 p-4 bg-[var(--bg-tertiary)]/50 rounded-lg border border-[var(--border-color)]">
            <h3 className="text-lg font-semibold text-[var(--accent)] mb-3">Parcel Area</h3>
            <div className="space-y-2 font-mono">
              <div className="flex justify-between">
                <span className="text-[var(--text-secondary)]">Area:</span>
                <span className="text-[var(--text-primary)]">{result.areaSqm.toFixed(4)} m²</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[var(--text-secondary)]">Hectares:</span>
                <span className="text-[var(--text-primary)]">{result.areaHa.toFixed(6)} ha</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[var(--text-secondary)]">Acres:</span>
                <span className="text-[var(--text-primary)]">{result.areaAcres.toFixed(6)} acres</span>
              </div>
              <div className="border-t border-[var(--border-color)] pt-2 mt-2 flex justify-between">
                <span className="text-[var(--text-secondary)]">Perimeter:</span>
                <span className="text-[var(--accent)] font-semibold">{result.perimeter.toFixed(4)} m</span>
              </div>
            </div>
          </div>
        )}

        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="px-6 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded"
          >
            Close
          </button>
          {selectedPoints.length >= 3 && !result && (
            <button
              onClick={calculateArea}
              className="flex-1 px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded"
            >
              Calculate Area
            </button>
          )}
          {result && (
            <button
              onClick={onClose}
              className="flex-1 px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded"
            >
              Done
            </button>
          )}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient, type BrowserSession } from '@/lib/api-client/client';
import { coordinateArea } from '@/lib/engine/area';
import { distanceBearing } from '@/lib/engine/distance';

interface Point {
  id: string;
  name: string;
  easting: number;
  northing: number;
  elevation?: number | null;
  is_control?: boolean;
  locked?: boolean;
}

interface ParcelBuilderModalProps {
  projectId: string;
  points: Point[];
  onClose: () => void;
  onParcelCreated: (parcel?: { id: string; name: string | null; boundary_points: Array<{ name?: string; easting: number; northing: number }>; created_at?: string }) => void;
  onDraftBoundaryChange?: (boundary: Array<{ easting: number; northing: number }> | null) => void;
}

interface BoundaryPoint {
  id: string;
  name: string;
  easting: number;
  northing: number;
}

interface BoundaryLine {
  from: string;
  to: string;
  bearing: string;
  bearingDeg: number;
  distance: number;
}

export default function ParcelBuilderModal({ projectId, points, onClose, onParcelCreated, onDraftBoundaryChange }: ParcelBuilderModalProps) {
  const [parcelName, setParcelName] = useState('');
  const [selectedPoints, setSelectedPoints] = useState<BoundaryPoint[]>([]);
  const [isSelecting, setIsSelecting] = useState(true);
  const [boundaryLines, setBoundaryLines] = useState<BoundaryLine[]>([]);
  const [areaResult, setAreaResult] = useState<{
    areaSqm: number;
    areaHa: number;
    areaAcres: number;
    perimeter: number;
  } | null>(null);
  const [saving, setSaving] = useState(false);
  const dbClient = createClient();

  const computeParcel = useCallback(() => {
    if (selectedPoints.length < 3) {
      setBoundaryLines([]);
      setAreaResult(null);
      return;
    }

    const coords = selectedPoints.map((p: any) => ({ easting: p.easting, northing: p.northing }));
    const areaData = coordinateArea(coords);

    const lines: BoundaryLine[] = [];
    for (let i = 0; i < selectedPoints.length; i++) {
      const from = selectedPoints[i];
      const to = selectedPoints[(i + 1) % selectedPoints.length];
      const db = distanceBearing(from, to);
      lines.push({
        from: from.name,
        to: to.name,
        bearing: db.bearingDMS,
        bearingDeg: db.bearing,
        distance: db.distance
      });
    }

    setBoundaryLines(lines);
    setAreaResult({
      areaSqm: areaData.areaSqm,
      areaHa: areaData.areaHa,
      areaAcres: areaData.areaAcres,
      perimeter: areaData.perimeter
    });
  }, [selectedPoints]);

  useEffect(() => {
    if (selectedPoints.length >= 3) {
      computeParcel();
    } else {
      setBoundaryLines([]);
      setAreaResult(null);
    }
  }, [selectedPoints, computeParcel]);

  const handlePointClick = (point: Point) => {
    if (!isSelecting) return;

    const firstPoint = selectedPoints[0]
    if (selectedPoints.length > 0 && firstPoint && firstPoint.id === point.id) {
      if (selectedPoints.length >= 3) setIsSelecting(false);
      return;
    }

    if (selectedPoints.find((p: any) => p.id === point.id)) return;

    setSelectedPoints([
      ...selectedPoints,
      {
        id: point.id,
        name: point.name,
        easting: point.easting,
        northing: point.northing
      }
    ]);
  };

  const handleSave = async () => {
    if (!parcelName || selectedPoints.length < 3 || !areaResult) return;

    setSaving(true);
    try {
      const { data: { session } } = await dbClient.auth.getSession();
      const user = (session as BrowserSession | null)?.user;

      const { data, error } = await dbClient.from('parcels').insert({
        project_id: projectId,
        name: parcelName,
        point_ids: selectedPoints.map((p: any) => p.id),
        boundary_points: selectedPoints.map((p: any) => ({
          name: p.name,
          easting: p.easting,
          northing: p.northing
        })),
        area_sqm: areaResult.areaSqm,
        area_ha: areaResult.areaHa,
        area_acres: areaResult.areaAcres,
        perimeter_m: areaResult.perimeter,
        created_by: user?.id
      }).select('id, name, boundary_points, created_at').single();

      if (error) throw error;

      onParcelCreated((data as any) ?? undefined);
      onClose();
    } catch (err) {
      console.error('Error saving parcel:', err);
      alert('Failed to save parcel');
    } finally {
      setSaving(false);
    }
  };

  const handleReset = () => {
    setSelectedPoints([]);
    setIsSelecting(true);
    setBoundaryLines([]);
    setAreaResult(null);
    setParcelName('');
  };

  return (
    <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4">
      <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6 border-b border-[var(--border-color)] flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold text-white">Build Parcel</h2>
            <p className="text-sm text-[var(--text-secondary)]">Click points in boundary order. Click first point to close.</p>
          </div>
          <button onClick={onClose} className="text-[var(--text-secondary)] hover:text-white text-2xl">&times;</button>
        </div>

        <div className="p-6 space-y-6">
          <div className="grid md:grid-cols-2 gap-6">
            <div>
              <h3 className="font-semibold text-[var(--text-primary)] mb-3">Available Points</h3>
              <div className="bg-[var(--bg-tertiary)] rounded-lg p-3 max-h-64 overflow-y-auto">
                {points.filter((p: any) => !p.locked).length === 0 ? (
                  <p className="text-[var(--text-muted)] text-sm">No points available</p>
                ) : (
                  <div className="grid grid-cols-2 gap-2">
                    {points.filter((p: any) => !p.locked).map((point: any) => {
                      const isAlreadySelected = selectedPoints.some((p: any) => p.id === point.id)
                      const isFirst = selectedPoints.length > 0 && selectedPoints[0].id === point.id
                      const canClose = isFirst && selectedPoints.length >= 3
                      const disabled = !isSelecting || (isAlreadySelected && !canClose)

                      return (
                        <button
                          key={point.id}
                          onClick={() => handlePointClick(point)}
                          disabled={disabled}
                          className={`px-3 py-2 rounded text-sm font-mono text-left transition-colors ${
                            isAlreadySelected
                              ? canClose
                                ? 'bg-green-900/40 border border-green-700 text-green-200 hover:bg-green-900/60'
                                : 'bg-[var(--accent)] text-black'
                              : isSelecting
                                ? 'bg-gray-700 hover:bg-[var(--border-hover)] text-[var(--text-primary)]'
                                : 'bg-[var(--bg-tertiary)] text-[var(--text-muted)] cursor-not-allowed'
                          }`}
                          title={canClose ? 'Click to close boundary' : undefined}
                        >
                          <div className="flex items-center justify-between gap-2">
                            <span>{point.name}</span>
                            {canClose ? <span className="text-xs font-sans">Close</span> : null}
                          </div>
                          <span className="text-xs text-[var(--text-secondary)] ml-1 block">
                            {point.easting.toFixed(0)}, {point.northing.toFixed(0)}
                          </span>
                        </button>
                      )
                    })}
                  </div>
                )}
              </div>

              {isSelecting && selectedPoints.length > 0 && (
                <div className="mt-4">
                  <h4 className="text-sm font-semibold text-[var(--text-primary)] mb-2">Selected Boundary ({selectedPoints.length})</h4>
                  <div className="flex flex-wrap gap-2">
                    {selectedPoints.map((p, idx) => (
                      <span key={p.id} className="px-2 py-1 bg-[var(--accent)]/20 text-[var(--accent)] rounded text-sm">
                        {p.name}
                        {idx < selectedPoints.length - 1 && ' → '}
                      </span>
                    ))}
                  </div>
                  <div className="mt-3 flex items-center gap-2">
                    <button
                      onClick={() => {
                        if (selectedPoints.length >= 3) setIsSelecting(false)
                      }}
                      disabled={selectedPoints.length < 3}
                      className="px-3 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm disabled:opacity-50"
                    >
                      Close boundary
                    </button>
                    <span className="text-xs text-[var(--text-muted)]">
                      or click the first point again
                    </span>
                  </div>
                </div>
              )}
            </div>

            <div>
              {areaResult ? (
                <div className="bg-[var(--bg-tertiary)] rounded-xl p-6">
                  <h3 className="font-bold text-white text-lg mb-4">PARCEL SUMMARY</h3>
                  {isSelecting ? (
                    <div className="mb-3 rounded border border-amber-700/50 bg-amber-900/10 px-3 py-2 text-xs text-amber-200">
                      Preview only — close the boundary (click the first point again) to enter a name and save.
                    </div>
                  ) : null}
                  <div className="border-b border-[var(--border-color)] pb-2 mb-3">
                    <span className="text-[var(--text-secondary)] text-sm">Boundary: </span>
                    <span className="text-[var(--text-primary)]">
                      {selectedPoints.map((p: any) => p.name).join(' → ')}
                    </span>
                  </div>

                  <div className="overflow-x-auto">
                  <table className="w-full text-sm mb-4 min-w-[300px]">
                    <thead>
                      <tr className="border-b border-[var(--border-color)]">
                        <th className="text-left py-2 text-[var(--text-secondary)]">Line</th>
                        <th className="text-right py-2 text-[var(--text-secondary)]">Bearing</th>
                        <th className="text-right py-2 text-[var(--text-secondary)]">Distance</th>
                      </tr>
                    </thead>
                    <tbody>
                      {boundaryLines.map((line, idx) => (
                        <tr key={`${line}-${idx}`} className="border-b border-[var(--border-color)]">
                          <td className="py-2 text-[var(--text-primary)]">{line.from}→{line.to}</td>
                          <td className="py-2 text-right font-mono text-[var(--text-primary)]">{line.bearing}</td>
                          <td className="py-2 text-right font-mono text-[var(--text-primary)]">{line.distance.toFixed(3)} m</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  </div>

                  <div className="space-y-2 pt-4 border-t border-[var(--border-color)]">
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]">Area:</span>
                      <span className="font-mono text-white">{areaResult.areaSqm.toFixed(4)} m²</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]"></span>
                      <span className="font-mono text-white">{areaResult.areaHa.toFixed(6)} ha</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-[var(--text-secondary)]"></span>
                      <span className="font-mono text-white">{areaResult.areaAcres.toFixed(4)} acres</span>
                    </div>
                    <div className="flex justify-between pt-2 border-t border-[var(--border-color)]">
                      <span className="text-[var(--text-secondary)]">Perimeter:</span>
                      <span className="font-mono text-white">{areaResult.perimeter.toFixed(3)} m</span>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="bg-[var(--bg-tertiary)]/50 rounded-xl p-6 text-center">
                  <p className="text-[var(--text-muted)]">
                    {selectedPoints.length < 3
                      ? `Select at least 3 points (${3 - selectedPoints.length} more)`
                      : 'Click the first point again to close the boundary'}
                  </p>
                </div>
              )}
            </div>
          </div>

          {!isSelecting && areaResult && (
            <div className="border-t border-[var(--border-color)] pt-6">
              <div className="max-w-md">
                <label className="label" htmlFor="parcel-name">Parcel Name</label>
                <input
                  className="input"
                  value={parcelName}
                  onChange={e => setParcelName(e.target.value)}
                  aria-label="e.g., Plot A, Parcel 1" placeholder="e.g., Plot A, Parcel 1"
                />
              </div>
            </div>
          )}
        </div>

        <div className="p-6 border-t border-[var(--border-color)] flex gap-3 justify-end">
          <button onClick={handleReset} className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded">
            Reset
          </button>
          <button onClick={onClose} className="px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded">
            Cancel
          </button>
          {!isSelecting && areaResult && (
            <button
              onClick={handleSave}
              disabled={!parcelName || saving}
              className="px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded disabled:opacity-50"
            >
              {saving ? 'Saving...' : 'Save Parcel'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';
/**
 * Performance Dashboard Component
 * Admin panel for monitoring and optimizing application performance
 */


import { useState, useEffect } from 'react'
import { performanceMonitor } from '@/lib/performance/monitor'
import { PERFORMANCE_BUDGETS } from '@/lib/performance/config'

interface PerformanceReport {
  webVitals?: {
    FCP?: number
    LCP?: number
    FID?: number
    CLS?: number
    TTFB?: number
  }
  customMetrics?: Record<string, number>
  errors?: { message: string; timestamp: number }[]
}

export default function PerformanceDashboard() {
  const [report, setReport] = useState<PerformanceReport | null>(null)
  const [dbStats, setDbStats] = useState<Record<string, { avg: number; count: number }>>({})
  const [isOptimizing, setIsOptimizing] = useState(false)
  const [optimizationResult, setOptimizationResult] = useState<Record<string, unknown> | null>(null)

  useEffect(() => {
    loadStats()
    const interval = setInterval(loadStats, 30000)
    return () => clearInterval(interval)
  }, [])

  const loadStats = () => {
    setReport(performanceMonitor.getReport())
    // In real implementation, fetch from server
    setDbStats({})
  }

  const runOptimization = async () => {
    setIsOptimizing(true)
    try {
      const res = await fetch('/api/admin/optimize', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'full_optimization' }),
      })
      const result = await res.json()
      setOptimizationResult(result)
    } catch (error) {
      console.error('Optimization failed:', error)
    } finally {
      setIsOptimizing(false)
    }
  }

  const getScoreColor = (score: number) => {
    if (score >= 90) return 'text-green-500'
    if (score >= 70) return 'text-yellow-500'
    return 'text-red-500'
  }

  const score = performanceMonitor.getScore()

  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <div className="max-w-6xl mx-auto">
        <h1 className="text-3xl font-bold mb-8">Performance Dashboard</h1>

        {/* Score Card */}
        <div className="bg-gray-800 rounded-xl p-6 mb-6">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold mb-2">Performance Score</h2>
              <p className="text-gray-400">Based on Web Vitals and custom metrics</p>
            </div>
            <div className={`text-5xl font-bold ${getScoreColor(score)}`}>
              {score}
            </div>
          </div>
        </div>

        {/* Web Vitals */}
        {report?.webVitals && (
          <div className="bg-gray-800 rounded-xl p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4">Web Vitals</h2>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {Object.entries(report.webVitals).map(([name, value]) => {
                const budget = PERFORMANCE_BUDGETS[name as keyof typeof PERFORMANCE_BUDGETS]
                const isGood = budget && (value as number) < budget
                return (
                  <div key={name} className="bg-gray-700 rounded-lg p-4">
                    <p className="text-sm text-gray-400 uppercase">{name}</p>
                    <p className={`text-2xl font-bold ${isGood ? 'text-green-400' : 'text-red-400'}`}>
                      {name === 'CLS' ? (value as number).toFixed(3) : `${(value as number).toFixed(0)}ms`}
                    </p>
                    <p className="text-xs text-gray-500">
                      Budget: {name === 'CLS' ? budget : `${budget}ms`}
                    </p>
                  </div>
                )
              })}
            </div>
          </div>
        )}

        {/* Custom Metrics */}
        {report?.customMetrics && Object.keys(report.customMetrics).length > 0 && (
          <div className="bg-gray-800 rounded-xl p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4">API Performance</h2>
            <div className="space-y-2">
              {Object.entries(report.customMetrics).map(([name, value]) => (
                <div key={name} className="flex justify-between items-center py-2 border-b border-gray-700">
                  <span className="text-gray-300">{name}</span>
                  <span className="font-mono text-blue-400">{(value as number).toFixed(2)}ms</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Database Stats */}
        {Object.keys(dbStats).length > 0 && (
          <div className="bg-gray-800 rounded-xl p-6 mb-6">
            <h2 className="text-xl font-semibold mb-4">Database Performance</h2>
            <div className="space-y-2">
              {Object.entries(dbStats).map(([query, stats]) => (
                <div key={query} className="flex justify-between items-center py-2 border-b border-gray-700">
                  <span className="text-gray-300 font-mono text-sm">{query}</span>
                  <div className="text-right">
                    <span className="font-mono text-blue-400">{stats.avg.toFixed(2)}ms</span>
                    <span className="text-gray-500 text-sm ml-2">({stats.count} queries)</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Optimization Actions */}
        <div className="bg-gray-800 rounded-xl p-6 mb-6">
          <h2 className="text-xl font-semibold mb-4">Optimization Actions</h2>
          <div className="flex gap-4">
            <button
              onClick={runOptimization}
              disabled={isOptimizing}
              className="px-6 py-3 bg-blue-600 rounded-lg font-semibold disabled:opacity-50"
            >
              {isOptimizing ? 'Running...' : 'Run Full Optimization'}
            </button>
            <button
              onClick={() => performanceMonitor.clearStats()}
              className="px-6 py-3 bg-gray-700 rounded-lg font-semibold"
            >
              Clear Stats
            </button>
          </div>

          {optimizationResult && (
            <div className="mt-4 p-4 bg-gray-700 rounded-lg">
              <h3 className="font-semibold mb-2">Optimization Result</h3>
              <pre className="text-sm text-green-400 overflow-auto">
                {JSON.stringify(optimizationResult, null, 2)}
              </pre>
            </div>
          )}
        </div>

        {/* Errors */}
        {report?.errors && report.errors.length > 0 && (
          <div className="bg-gray-800 rounded-xl p-6">
            <h2 className="text-xl font-semibold mb-4 text-red-400">Recent Errors ({report.errors.length})</h2>
            <div className="space-y-2 max-h-64 overflow-auto">
              {report.errors.map((error, idx) => (
                <div key={`${error}-${idx}`} className="p-3 bg-red-900/30 rounded-lg text-sm">
                  <p className="text-red-300">{error.message}</p>
                  <p className="text-gray-500 text-xs mt-1">
                    {new Date(error.timestamp).toLocaleString()}
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState, useRef } from 'react'
import Image from 'next/image'
import type { Photo } from '@/lib/reports/surveyReport/types'

interface PhotoUploaderProps {
  projectId: string
  photos: Photo[]
  onChange: (photos: Photo[]) => void
  maxPhotos?: number
}

export default function PhotoUploader({ projectId, photos, onChange, maxPhotos = 8 }: PhotoUploaderProps) {
  const [uploading, setUploading] = useState(false)
  const [dragOver, setDragOver] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  const handleFiles = async (files: FileList | null) => {
    if (!files || files.length === 0) return
    if (photos.length >= maxPhotos) return

    setUploading(true)
    const remaining = maxPhotos - photos.length
    const toUpload = Array.from(files).slice(0, remaining)

    try {
      for (const file of toUpload) {
        const ext = file.name.split('.').pop()
        const filename = `${projectId}_${Date.now()}_${Math.random().toString(36).slice(2)}.${ext}`

        const formData = new FormData()
        formData.append('file', file)
        formData.append('bucket', `survey_photos/${projectId}`)

        const res = await fetch('/api/storage', {
          method: 'POST',
          body: formData
        })

        if (!res.ok) {
          console.error('Upload failed:', res.statusText)
          continue
        }

        const json = await res.json()
        const url = json.url

        const newPhoto: Photo = {
          filename,
          url,
          caption: file.name.replace(/\.[^.]+$/, ''),
          orientation: '',
          dateTaken: new Date().toISOString().slice(0, 10),
        }

        onChange([...photos, newPhoto])
      }
    } catch (err) {
      console.error('Upload failed:', err)
    } finally {
      setUploading(false)
    }
  }

  const removePhoto = (index: number) => {
    const updated = [...photos]
    updated.splice(index, 1)
    onChange(updated)
  }

  const updatePhoto = (index: number, field: keyof Photo, value: string) => {
    const updated = [...photos]
    updated[index] = { ...updated[index], [field]: value }
    onChange(updated)
  }

  return (
    <div className="space-y-3">
      {photos.length < maxPhotos && (
        <div
          onDragOver={e => { e.preventDefault(); setDragOver(true) }}
          onDragLeave={() => setDragOver(false)}
          onDrop={e => {
            e.preventDefault()
            setDragOver(false)
            handleFiles(e.dataTransfer.files)
          }}
          onClick={() => inputRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-colors ${
            dragOver
              ? 'border-[var(--accent)] bg-[var(--accent)]/5'
              : 'border-[var(--border-color)] hover:border-[var(--accent)]/50'
          }`}
        >
          <input
            ref={inputRef}
            type="file"
            accept="image/*"
            multiple
            className="hidden"
            onChange={e => handleFiles(e.target.files)}
          />
          <div className="flex flex-col items-center gap-2">
            <svg className="w-8 h-8 text-[var(--text-muted)]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M2.25 15.75l5.159-5.159a2.25 2.25 0 013.182 0l5.159 5.159m-1.5-1.5l1.409-1.409a2.25 2.25 0 013.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 001.5-1.5V6a1.5 1.5 0 00-1.5-1.5H3.75A1.5 1.5 0 002.25 6v12a1.5 1.5 0 001.5 1.5zm10.5-11.25h.008v.008h-.008V8.25zm.375 0a.375.375 0 11-.75 0 .375.375 0 01.75 0z" />
            </svg>
            <div>
              <p className="text-sm text-[var(--text-primary)] font-medium">
                {uploading ? 'Uploading...' : 'Drop photos here or click to upload'}
              </p>
              <p className="text-xs text-[var(--text-muted)] mt-1">
                {photos.length}/{maxPhotos} photos · JPG, PNG, WebP
              </p>
            </div>
          </div>
        </div>
      )}

      {photos.length > 0 && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {photos.map((photo, i) => (
            <div key={`${photo}-${i}`} className="border border-[var(--border-color)] rounded-lg p-3 bg-[var(--bg-tertiary)]/30">
              <div className="flex gap-2">
                <div className="w-16 h-16 rounded overflow-hidden flex-shrink-0 bg-[var(--bg-tertiary)]">
                  <Image src={photo.url} alt={photo.caption || ''} fill className="object-cover" />
                </div>
                <div className="flex-1 min-w-0 space-y-1.5">
                  <input
                    value={photo.caption || ''}
                    onChange={e => updatePhoto(i, 'caption', e.target.value)}
                    aria-label="Caption" placeholder="Caption"
                    className="w-full px-2 py-1 text-xs bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]"
                  />
                  <input
                    value={photo.orientation || ''}
                    onChange={e => updatePhoto(i, 'orientation', e.target.value)}
                    aria-label="View direction (e.g. Looking North)" placeholder="View direction (e.g. Looking North)"
                    className="w-full px-2 py-1 text-xs bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]"
                  />
                  <button
                    onClick={() => removePhoto(i)}
                    className="text-xs text-red-400 hover:text-red-300"
                  >
                    Remove
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client';

import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { useState, useRef, useEffect, useCallback } from 'react'
import ProjectWorkflowBadge from '@/components/shared/ProjectWorkflowBadge'

/* ── Delete Confirmation Modal ──────────────────────────────────────────── */
function DeleteConfirmModal({
  projectName,
  pointCount,
  parcelCount,
  onConfirm,
  onCancel,
  isDeleting,
  deleteError,
}: {
  projectName: string
  pointCount: number
  parcelCount: number
  onConfirm: () => void
  onCancel: () => void
  isDeleting: boolean
  deleteError: string
}) {
  const modalRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => { if (e.key === 'Escape') onCancel() }
    document.addEventListener('keydown', handleEsc)
    return () => document.removeEventListener('keydown', handleEsc)
  }, [onCancel])

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm px-4 animate-in fade-in duration-200"
      onClick={(e) => { if (e.target === e.currentTarget) onCancel() }}
    >
      <div ref={modalRef}
        className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-2xl w-full max-w-md shadow-2xl overflow-hidden"
        onClick={e => e.stopPropagation()}
      >
        {/* Header with warning */}
        <div className="px-6 pt-6 pb-4">
          <div className="flex items-center gap-3 mb-4">
            <div className="w-10 h-10 rounded-full bg-red-500/10 border border-red-500/20 flex items-center justify-center shrink-0">
              <svg className="w-5 h-5 text-red-400" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.8}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
              </svg>
            </div>
            <div>
              <h3 className="text-lg font-semibold text-[var(--text-primary)]">Delete Project</h3>
              <p className="text-sm text-[var(--text-muted)]">This action cannot be undone</p>
            </div>
          </div>
        </div>

        {/* Body */}
        <div className="px-6 pb-4">
          <div className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg p-4 mb-4">
            <p className="text-sm text-[var(--text-secondary)]">
              Are you sure you want to permanently delete{' '}
              <span className="font-semibold text-[var(--text-primary)]">"{projectName}"</span>?
            </p>
            {(pointCount > 0 || parcelCount > 0) && (
              <div className="mt-3 pt-3 border-t border-[var(--border-color)] space-y-1">
                {pointCount > 0 && (
                  <p className="text-xs text-red-400 flex items-center gap-1.5">
                    <svg className="w-3.5 h-3.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                    <span><strong>{pointCount}</strong> survey point{pointCount > 1 ? 's' : ''} will be permanently deleted</span>
                  </p>
                )}
                {parcelCount > 0 && (
                  <p className="text-xs text-red-400 flex items-center gap-1.5">
                    <svg className="w-3.5 h-3.5 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                    </svg>
                    <span><strong>{parcelCount}</strong> parcel{parcelCount > 1 ? 's' : ''} will be permanently deleted</span>
                  </p>
                )}
              </div>
            )}
            <p className="text-xs text-[var(--text-muted)] mt-2">
              All associated data including points, parcels, alignments, chainage data, and submissions will be removed.
            </p>
          </div>

          {/* Error display */}
          {deleteError && (
            <div className="mb-4 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-sm text-red-400 flex items-start gap-2">
              <svg className="w-4 h-4 shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9.303 3.376c-.866 1.5-.217 3.374-1.948 3.374H4.645c-1.73 0-2.813-1.874-1.948-3.374L10.051 3.378c.866-1.5 3.032-1.5 3.898 0l7.354 13.122zM12 15.75h.007v.008H12v-.008z" />
              </svg>
              <span>{deleteError}</span>
            </div>
          )}
        </div>

        {/* Footer with actions */}
        <div className="px-6 pb-6 flex gap-3">
          <button
            type="button"
            onClick={onCancel}
            disabled={isDeleting}
            className="flex-1 px-4 py-2.5 text-sm font-medium rounded-lg border border-[var(--border-color)] text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={onConfirm}
            disabled={isDeleting}
            className="flex-1 px-4 py-2.5 text-sm font-medium rounded-lg bg-red-600 text-white hover:bg-red-700 transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {isDeleting ? (
              <>
                <svg className="w-4 h-4 animate-spin" viewBox="0 0 24 24" fill="none">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
                Deleting...
              </>
            ) : (
              <>
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
                Yes, Delete
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  )
}

/* ── ProjectCard ─────────────────────────────────────────────────────────── */
export default function ProjectCard({ project, openLabel }: { project: any; openLabel: string }) {
  const router = useRouter()
  const [menuOpen, setMenuOpen] = useState(false)
  const [showDeleteModal, setShowDeleteModal] = useState(false)
  const [isDeleting, setIsDeleting] = useState(false)
  const [deleteError, setDeleteError] = useState('')
  const menuRef = useRef<HTMLDivElement>(null)

  const getSurveyBadgeLabel = (type?: string): string => {
    switch ((type || '').toLowerCase()) {
      case 'road': return 'ROAD'
      case 'boundary': return 'BOUNDARY'
      case 'topographic': return 'TOPO'
      case 'control': return 'CONTROL'
      case 'construction': return 'CONSTRUCTION'
      case 'leveling': return 'LEVELING'
      case 'drone': return 'DRONE'
      case 'gnss': return 'GNSS'
      default: return (type || 'TOPO').toUpperCase()
    }
  }

  const surveyType = getSurveyBadgeLabel(project.survey_type)

  const pointCount = project.point_count ?? project._pointCount ?? 0
  const parcelCount = project.parcel_count ?? project._parcelCount ?? 0

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setMenuOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const handleCardClick = (e: React.MouseEvent) => {
    // Ignore clicks on any interactive element: menu, delete, links, buttons
    const target = e.target as HTMLElement
    if (
      target.closest('.menu-trigger') ||
      target.closest('.menu-dropdown') ||
      target.closest('.delete-trigger') ||
      target.closest('a') ||
      target.closest('button')
    ) return
    router.push(`/project/${project.id}`)
  }

  const handleDelete = useCallback(async () => {
    setIsDeleting(true)
    setDeleteError('')
    try {
      const res = await fetch(`/api/project/${project.id}`, { method: 'DELETE' })
      const data = await res.json()
      if (!res.ok) {
        setDeleteError(data.error || 'Failed to delete project')
        setIsDeleting(false)
      } else {
        setShowDeleteModal(false)
        // Force a full page reload to guarantee the deleted project disappears
        // router.refresh() alone is unreliable for Server Component data
        window.location.href = window.location.pathname
      }
    } catch (err: unknown) {
      setDeleteError((err as Error).message || 'Failed to delete project — check your connection and try again')
      setIsDeleting(false)
    }
  }, [project.id])

  const badgeColor = (() => {
    const type = project.survey_type?.toLowerCase() || 'topo'
    if (type === 'road') return 'bg-blue-500/20 text-blue-400 border-blue-500/30'
    if (type === 'boundary') return 'bg-green-500/20 text-green-400 border-green-500/30'
    if (type === 'control') return 'bg-purple-500/20 text-purple-400 border-purple-500/30'
    if (type === 'topographic') return 'bg-amber-500/20 text-amber-400 border-amber-500/30'
    return 'bg-gray-500/20 text-gray-400 border-gray-500/30'
  })()

  return (
    <>
      <div
        onClick={handleCardClick}
        className="group block h-full card p-6 hover:border-[var(--border-hover)] hover:bg-[var(--bg-tertiary)] transition-premium cursor-pointer relative"
      >
        <div className="flex items-start justify-between gap-3 mb-3">
          <h3 className="font-semibold text-[var(--text-primary)] group-hover:text-[var(--accent)] transition-colors leading-snug flex-1 truncate">
            {project.name}
          </h3>
          <span className={`badge shrink-0 text-[10px] border ${badgeColor}`}>{surveyType}</span>
        </div>

        <p className="text-sm text-[var(--text-muted)] mb-3 truncate">
          {project.location || 'No location set'}
        </p>

        {/* Workflow badge */}
        <div className="mb-3">
          <ProjectWorkflowBadge project={project} />
        </div>

        <div className="grid grid-cols-3 gap-2 text-xs text-[var(--text-secondary)] mb-3">
          <div>
            <span className="text-[var(--text-muted)]">Points:</span>{' '}
            <span className="font-mono text-[var(--text-primary)]">{pointCount}</span>
          </div>
          <div>
            <span className="text-[var(--text-muted)]">Parcels:</span>{' '}
            <span className="font-mono text-[var(--text-primary)]">{parcelCount}</span>
          </div>
          <div>
            <span className="text-[var(--text-muted)]">UTM</span>{' '}
            <span className="font-mono text-[var(--text-primary)]">{project.utm_zone}{project.hemisphere}</span>
          </div>
        </div>

        <div className="text-xs text-[var(--text-muted)] mb-4">
          Created: {new Date(project.created_at).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}
        </div>

        <div className="pt-3 border-t border-[var(--border-color)] flex items-center justify-between">
          <Link
            href={`/project/${project.id}`}
            prefetch={false}
            onClick={e => e.stopPropagation()}
            className="text-xs text-[var(--accent)] font-medium hover:text-[var(--accent-dim)] transition-colors"
          >
            {openLabel} →
          </Link>

          <div className="flex items-center gap-2 relative" ref={menuRef}>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                e.preventDefault()
                setMenuOpen(false)
                setShowDeleteModal(true)
              }}
              className="delete-trigger w-9 h-9 flex items-center justify-center rounded hover:bg-red-500/10 text-[var(--text-muted)] hover:text-red-400 transition-colors"
              title="Delete project"
              aria-label="Delete project"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.8}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
            <Link
              href={`/project/${project.id}/generate-plan`}
              prefetch={false}
              onClick={e => e.stopPropagation()}
              className="text-[10px] text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors px-2 py-2 rounded hover:bg-[var(--bg-secondary)]"
            >
              Generate Plan
            </Link>

            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation()
                e.preventDefault()
                setMenuOpen(!menuOpen)
              }}
              className="menu-trigger w-9 h-9 flex items-center justify-center rounded hover:bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
              aria-label="More options"
            >
              •••
            </button>

            {menuOpen && (
              <div className="menu-dropdown absolute right-0 top-full mt-1 z-50 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg shadow-xl py-1 min-w-[160px]">
                <Link
                  href={`/project/${project.id}`}
                  prefetch={false}
                  onClick={(e) => { e.stopPropagation(); setMenuOpen(false) }}
                  className="block px-4 py-3 text-sm text-[var(--text-primary)] hover:bg-[var(--border-hover)] transition-colors"
                >
                  Open
                </Link>
                <Link
                  href={`/project/${project.id}/generate-plan`}
                  prefetch={false}
                  onClick={(e) => { e.stopPropagation(); setMenuOpen(false) }}
                  className="block px-4 py-3 text-sm text-[var(--text-primary)] hover:bg-[var(--border-hover)] transition-colors"
                >
                  Generate Plan
                </Link>
                <Link
                  href={`/project/${project.id}/documents`}
                  onClick={(e) => { e.stopPropagation(); setMenuOpen(false) }}
                  className="block px-4 py-3 text-sm text-[var(--text-primary)] hover:bg-[var(--border-hover)] transition-colors"
                >
                  Generate Report
                </Link>
                <div className="border-t border-[var(--border-color)] my-1"></div>
                <Link
                  href={`/project/${project.id}/contours`}
                  onClick={(e) => { e.stopPropagation(); setMenuOpen(false) }}
                  className="block px-4 py-3 text-sm text-[var(--text-primary)] hover:bg-[var(--border-hover)] transition-colors"
                >
                  Contours
                </Link>
                <Link
                  href={`/project/${project.id}/profiles`}
                  onClick={(e) => { e.stopPropagation(); setMenuOpen(false) }}
                  className="block px-4 py-3 text-sm text-[var(--text-primary)] hover:bg-[var(--border-hover)] transition-colors"
                >
                  Profiles
                </Link>
                <div className="border-t border-[var(--border-color)] my-1"></div>
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    setMenuOpen(false)
                    setShowDeleteModal(true)
                  }}
                  className="w-full text-left px-4 py-3 text-sm text-red-400 hover:bg-red-500/10 transition-colors flex items-center gap-2"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.8}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                  </svg>
                  Delete Project
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      {showDeleteModal && (
        <DeleteConfirmModal
          projectName={project.name}
          pointCount={pointCount}
          parcelCount={parcelCount}
          onConfirm={handleDelete}
          onCancel={() => { setShowDeleteModal(false); setDeleteError('') }}
          isDeleting={isDeleting}
          deleteError={deleteError}
        />
      )}
    </>
  )
}

'use client';

import { useState, useRef, useEffect } from 'react'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface RIMParcel {
  id: string
  number: string
  x: number
  y: number
  width: number
  height: number
  area: string
  description: string
  color: string
  subParcelIds?: string[]
}

interface RIMAmendment {
  id: string
  date: string
  reference: string
  description: string
  edition: string
  affectedPlots: string
}

interface RIMSheetIndex {
  rows: number
  cols: number
  currentRow: number
  currentCol: number
}

interface RegistryIndexMapProps {
  isOpen: boolean
  onClose: () => void
  initialData?: {
    district?: string
    location?: string
    subLocation?: string
    registrationUnit?: string
    sheetNumber?: string
    edition?: string
    scale?: string
    parcels?: RIMParcel[]
  }
}

const PARCEL_COLORS = [
  '#fef3c7', '#d1fae5', '#dbeafe', '#ede9fe',
  '#fce7f3', '#ffedd5', '#f0fdf4', '#fafafa',
]

export default function RegistryIndexMap({ isOpen, onClose, initialData }: RegistryIndexMapProps) {
  const { t } = useLanguage()
  const printRef = useRef<HTMLDivElement>(null)

  const [district, setDistrict] = useState(initialData?.district ?? '')
  const [location, setLocation] = useState(initialData?.location ?? '')
  const [subLocation, setSubLocation] = useState(initialData?.subLocation ?? '')
  const [registrationUnit, setRegistrationUnit] = useState(initialData?.registrationUnit ?? '')
  const [sheetNumber, setSheetNumber] = useState(initialData?.sheetNumber ?? '1')
  const [edition, setEdition] = useState(initialData?.edition ?? '1st EDITION')
  const [scale, setScale] = useState(initialData?.scale ?? '1:2,500')
  const [amendments, setAmendments] = useState<RIMAmendment[]>([])
  const [parcels, setParcels] = useState<RIMParcel[]>(initialData?.parcels ?? [])
  const [selectedParcel, setSelectedParcel] = useState<string | null>(null)
  const [nextParcelNum, setNextParcelNum] = useState(1)
  const [mode, setMode] = useState<'view' | 'edit'>('view')

  const [sheetIndex, setSheetIndex] = useState<RIMSheetIndex>({
    rows: 3, cols: 3, currentRow: 1, currentCol: 1,
  })

  useEffect(() => {
    if (!isOpen) return
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [isOpen, onClose])

  const sheetId = [district.toUpperCase(), location.toUpperCase(), registrationUnit.toUpperCase(), `SHEET ${sheetNumber}`]
    .filter(Boolean).join(' / ')

  const addParcel = () => {
    const gridCols = 4
    const row = Math.floor((nextParcelNum - 1) / gridCols)
    const col = (nextParcelNum - 1) % gridCols
    const cellW = 180
    const cellH = 120
    const padding = 8
    const newParcel: RIMParcel = {
      id: crypto.randomUUID(),
      number: String(nextParcelNum),
      x: padding + col * (cellW + padding),
      y: padding + row * (cellH + padding),
      width: cellW,
      height: cellH,
      area: '',
      description: '',
      color: PARCEL_COLORS[(nextParcelNum - 1) % PARCEL_COLORS.length],
    }
    setParcels(prev => [...prev, newParcel])
    setNextParcelNum(n => n + 1)
  }

  const updateParcel = (id: string, updates: Partial<RIMParcel>) => {
    setParcels(prev => prev.map((p: any) => p.id === id ? { ...p, ...updates } : p))
  }

  const removeParcel = (id: string) => {
    setParcels(prev => prev.filter((p: any) => p.id !== id))
    setSelectedParcel(null)
  }

  const addAmendment = () => {
    const prevEdition = amendments.length > 0
      ? amendments[amendments.length - 1].edition
      : edition
    const nextEd = parseInt(prevEdition.replace(/\D/g, '')) || 1
    setAmendments(prev => [...prev, {
      id: crypto.randomUUID(),
      date: new Date().toLocaleDateString('en-GB'),
      reference: '',
      description: '',
      edition: `${nextEd + 1}TH ED`,
      affectedPlots: '',
    }])
  }

  const updateAmendment = (id: string, updates: Partial<RIMAmendment>) => {
    setAmendments(prev => prev.map((a: any) => a.id === id ? { ...a, ...updates } : a))
  }

  const handlePrint = () => {
    const content = printRef.current
    if (!content) return
    const win = window.open('', '_blank')
    if (!win) return
    win.document.write(`<!DOCTYPE html>
<html>
<head>
  <title>RIM - ${sheetId}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Courier New', monospace; background: white; padding: 20px; }
    .sheet {
      width: 210mm; min-height: 297mm;
      border: 2px solid #000;
      padding: 12mm;
      position: relative;
      background: white;
      page-break-after: always;
    }
    .sheet-header {
      text-align: center;
      border-bottom: 2px solid #000;
      padding-bottom: 6px;
      margin-bottom: 8px;
    }
    .sheet-title {
      font-size: 16pt;
      font-weight: bold;
      text-decoration: underline;
      letter-spacing: 1px;
    }
    .sheet-id {
      font-size: 11pt;
      margin-top: 2px;
    }
    .meta-row {
      display: flex;
      gap: 12px;
      margin-bottom: 6px;
      font-size: 9pt;
      flex-wrap: wrap;
    }
    .meta-item { display: flex; gap: 4px; }
    .meta-label { font-weight: bold; }
    .grid-area {
      display: grid;
      grid-template-columns: repeat(${sheetIndex.cols}, 1fr);
      grid-template-rows: repeat(${sheetIndex.rows}, 40px);
      border: 1px solid #999;
      margin-bottom: 8px;
    }
    .grid-cell {
      border: 1px solid #999;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 7pt;
      background: #f9f9f9;
    }
    .grid-cell.current {
      background: #000;
      color: white;
      font-weight: bold;
    }
    .parcel-map {
      border: 1px solid #000;
      min-height: 400px;
      position: relative;
      background: #f5f5f5;
      margin-bottom: 8px;
    }
    .parcel {
      position: absolute;
      border: 1.5px solid #000;
      background: #fff;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }
    .parcel.selected { outline: 2px solid #2563eb; }
    .parcel-num { font-size: 9pt; font-weight: bold; }
    .parcel-area { font-size: 7pt; color: #555; }
    .parcel-sub { font-size: 6pt; color: #888; }
    .history-table {
      width: 100%;
      border-collapse: collapse;
      font-size: 7pt;
      margin-bottom: 6px;
    }
    .history-table th, .history-table td {
      border: 1px solid #000;
      padding: 3px 5px;
      text-align: left;
    }
    .history-table th { background: #000; color: #fff; }
    .footer-row {
      display: flex;
      justify-content: space-between;
      font-size: 7pt;
      margin-top: 4px;
      border-top: 1px solid #000;
      padding-top: 4px;
    }
    @media print {
      body { padding: 0; }
      .sheet { border: none; margin: 0; }
    }
  </style>
</head>
<body>
  ${content.innerHTML}
</body>
</html>`)
    win.document.close()
    win.focus()
    setTimeout(() => { win.print(); win.close() }, 500)
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 overflow-y-auto p-4">
      <div className="w-full max-w-5xl bg-white rounded-lg shadow-2xl overflow-hidden">
        {/* Toolbar */}
        <div className="bg-gray-800 text-white px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-lg font-bold tracking-wide">[Clip]</span>
            <h2 className="font-semibold">Registry Index Map (RIM)</h2>
            <span className="text-xs bg-amber-600 px-2 py-0.5 rounded">Kenya — General Boundaries</span>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setMode(m => m === 'view' ? 'edit' : 'view')}
              className="px-3 py-1 text-xs bg-gray-700 hover:bg-gray-600 rounded"
            >
              {mode === 'view' ? '[Edit] Edit Sheet' : ' View'}
            </button>
            <button
              onClick={handlePrint}
              className="px-3 py-1 text-xs bg-blue-600 hover:bg-blue-500 rounded"
            >
               Print / Export
            </button>
            <button
              onClick={onClose}
              className="px-3 py-1 text-xs bg-gray-700 hover:bg-gray-600 rounded"
            >
              [x] Close
            </button>
          </div>
        </div>

        <div className="flex">
          {/* Sidebar controls */}
          {mode === 'edit' && (
            <div className="w-72 border-r border-gray-200 bg-gray-50 p-4 overflow-y-auto max-h-[90vh]">
              <h3 className="text-sm font-bold mb-3 text-gray-700 uppercase tracking-wide">Sheet Details</h3>

              <div className="space-y-3">
                <div>
                  <label className="text-xs font-semibold text-gray-600" htmlFor="district">District</label>
                  <input id="district" value={district} onChange={e => setDistrict(e.target.value)}
                    className="w-full px-2 py-1 border rounded text-sm uppercase" aria-label="e.g. KAJIADO" placeholder="e.g. KAJIADO" />
                </div>
                <div>
                  <label className="text-xs font-semibold text-gray-600" htmlFor="location">Location</label>
                  <input id="location" value={location} onChange={e => setLocation(e.target.value)}
                    className="w-full px-2 py-1 border rounded text-sm uppercase" aria-label="e.g. ILKISONGO" placeholder="e.g. ILKISONGO" />
                </div>
                <div>
                  <label className="text-xs font-semibold text-gray-600" htmlFor="sub-location-registration-unit">Sub-Location / Registration Unit</label>
                  <input id="sub-location-registration-unit" value={registrationUnit} onChange={e => setRegistrationUnit(e.target.value)}
                    className="w-full px-2 py-1 border rounded text-sm uppercase" aria-label="e.g. ENTARARA" placeholder="e.g. ENTARARA" />
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <label className="text-xs font-semibold text-gray-600" htmlFor="sheet-no">Sheet No.</label>
                    <input id="sheet-no" aria-label="Sheet No." type="number" value={sheetNumber} onChange={e => setSheetNumber(e.target.value)}
                      className="w-full px-2 py-1 border rounded text-sm" min={1} />
                  </div>
                  <div>
                    <label className="text-xs font-semibold text-gray-600" htmlFor="edition">Edition</label>
                    <input id="edition" value={edition} onChange={e => setEdition(e.target.value)}
                      className="w-full px-2 py-1 border rounded text-sm" aria-label="e.g. 1ST EDITION" placeholder="e.g. 1ST EDITION" />
                  </div>
                </div>
                <div>
                  <label className="text-xs font-semibold text-gray-600" htmlFor="scale">Scale</label>
                  <select value={scale} onChange={e => setScale(e.target.value)}
                    className="w-full px-2 py-1 border rounded text-sm">
                    <option value="1:2,500">1:2,500 (Land Consolidation / Adjudication)</option>
                    <option value="1:5,000">1:5,000 (Large-scale farms / Settlement)</option>
                    <option value="1:10,000">1:10,000 (Subdivision of large farms)</option>
                    <option value="1:50,000">1:50,000 (Pastoral / Range Provisional)</option>
                  </select>
                </div>

                <div className="border-t pt-3">
                  <h4 className="text-xs font-bold text-gray-700 mb-2">Sheet Index (Adjacent Sheets)</h4>
                  <div className="grid grid-cols-3 gap-1 mb-2">
                    {[[0,0],[0,1],[0,2],[1,0],[1,1,'●'],[1,2],[2,0],[2,1],[2,2]].map(([r,c,label],i) => (
                      <button key={`item-${i}`}
                        onClick={() => setSheetIndex(s => ({...s, currentRow: r as number, currentCol: c as number}))}
                        className={`h-8 text-xs rounded border ${r===sheetIndex.currentRow&&c===sheetIndex.currentCol?'bg-black text-white':'bg-gray-100 hover:bg-gray-200'}`}
                      >
                        {label ?? `${Number(r!)+1}-${Number(c!)+1}`}
                      </button>
                    ))}
                  </div>
                  <input type="text" aria-label="Index notes" placeholder="e.g. Sheet 2 to North"
                    className="w-full px-2 py-1 border rounded text-xs" />
                </div>

                <div className="border-t pt-3">
                  <div className="flex items-center justify-between mb-2">
                    <h4 className="text-xs font-bold text-gray-700">Parcels ({parcels.length})</h4>
                    <button onClick={addParcel}
                      className="px-2 py-1 text-xs bg-green-600 text-white rounded hover:bg-green-700">
                      + Add Parcel
                    </button>
                  </div>
                  <div className="space-y-1 max-h-48 overflow-y-auto">
                    {parcels.map((p: any) => (
                      <div key={p.id}
                        className={`flex items-center gap-1 p-1 rounded border cursor-pointer text-xs ${selectedParcel === p.id ? 'bg-blue-50 border-blue-400' : 'border-gray-200 hover:bg-gray-50'}`}
                        onClick={() => setSelectedParcel(p.id)}
                      >
                        <div className="w-4 h-4 rounded border" style={{background: p.color, borderColor: '#000'}} />
                        <span className="font-bold w-6">{p.number}.</span>
                        <input value={p.area} onChange={e => updateParcel(p.id, {area: e.target.value})}
                          onClick={e => e.stopPropagation()}
                          aria-label="Area (ha)" placeholder="Area (ha)"
                          className="flex-1 px-1 border rounded text-xs" />
                        <button onClick={e => { e.stopPropagation(); removeParcel(p.id) }}
                          className="text-red-500 hover:text-red-700 font-bold px-1">[x]</button>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="border-t pt-3">
                  <div className="flex items-center justify-between mb-2">
                    <h4 className="text-xs font-bold text-gray-700">Sheet History ({amendments.length})</h4>
                    <button onClick={addAmendment}
                      className="px-2 py-1 text-xs bg-gray-700 text-white rounded hover:bg-gray-600">
                      + Amendment
                    </button>
                  </div>
                  <div className="space-y-2">
                    {amendments.map((a: any) => (
                      <div key={a.id} className="border rounded p-2 bg-white text-xs space-y-1">
                        <div className="grid grid-cols-2 gap-1">
                          <input value={a.date} onChange={e => updateAmendment(a.id, {date: e.target.value})}
                            className="px-1 border rounded" aria-label="Date" placeholder="Date" />
                          <input value={a.edition} onChange={e => updateAmendment(a.id, {edition: e.target.value})}
                            className="px-1 border rounded" aria-label="Edition" placeholder="Edition" />
                        </div>
                        <input value={a.reference} onChange={e => updateAmendment(a.id, {reference: e.target.value})}
                          className="w-full px-1 border rounded" aria-label="Reference (e.g. MUT/2/1036/1/88)" placeholder="Reference (e.g. MUT/2/1036/1/88)" />
                        <input value={a.description} onChange={e => updateAmendment(a.id, {description: e.target.value})}
                          className="w-full px-1 border rounded" aria-label="Description (e.g. SUBDIV 904 INTO 3054-3061)" placeholder="Description (e.g. SUBDIV 904 INTO 3054-3061)" />
                        <input value={a.affectedPlots} onChange={e => updateAmendment(a.id, {affectedPlots: e.target.value})}
                          className="w-full px-1 border rounded" aria-label="Affected parcels" placeholder="Affected parcels" />
                        <button onClick={() => setAmendments(prev => prev.filter((x: any) => x.id !== a.id))}
                          className="text-red-500 hover:text-red-700 text-xs">Remove</button>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Print area */}
          <div className="flex-1 bg-gray-100 p-4 overflow-auto max-h-[90vh]">
            <div ref={printRef} className="bg-white">
              <RIMSheetContent
                sheetId={sheetId}
                district={district}
                location={location}
                subLocation={subLocation}
                registrationUnit={registrationUnit}
                sheetNumber={sheetNumber}
                edition={edition}
                scale={scale}
                parcels={parcels}
                selectedParcel={selectedParcel}
                amendments={amendments}
                sheetIndex={sheetIndex}
                mode={mode}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function RIMSheetContent({
  sheetId, district, location, registrationUnit, sheetNumber, edition, scale,
  parcels, selectedParcel, amendments, sheetIndex, mode
}: {
  sheetId: string
  district: string; location: string; subLocation: string; registrationUnit: string
  sheetNumber: string; edition: string; scale: string
  parcels: RIMParcel[]; selectedParcel: string | null
  amendments: RIMAmendment[]
  sheetIndex: RIMSheetIndex
  mode: 'view' | 'edit'
}) {
  return (
    <div className="w-[210mm] min-h-[297mm] p-[12mm] border-2 border-black bg-white relative font-mono">
      {/* Header */}
      <div className="text-center border-b-2 border-black pb-2 mb-3">
        <div className="text-base font-bold underline tracking-widest uppercase">
          REGISTRY INDEX MAP
        </div>
        <div className="text-xs mt-1 tracking-wider">
          {sheetId || 'DISTRICT / LOCATION / REGISTRATION UNIT / SHEET N'}
        </div>
      </div>

      {/* Scale + Edition */}
      <div className="flex justify-between text-xs mb-2 px-1">
        <div><span className="font-bold">Scale:</span> {scale}</div>
        <div><span className="font-bold">Edition:</span> {edition || '—'}</div>
        <div><span className="font-bold">Sheet:</span> {sheetNumber || '1'}</div>
      </div>

      {/* Sheet Index (mini grid of adjacent sheets) */}
      <div className="flex items-start gap-2 mb-3">
        <div>
          <div className="text-[7pt] font-bold mb-0.5 uppercase">Sheet Index</div>
          <div className={`grid gap-px bg-gray-400 border border-gray-400`}
            style={{gridTemplateColumns: `repeat(${sheetIndex.cols}, 18px)`, gridTemplateRows: `repeat(${sheetIndex.rows}, 14px)`}}>
            {Array.from({length: sheetIndex.rows * sheetIndex.cols}).map((_, i) => {
              const r = Math.floor(i / sheetIndex.cols)
              const c = i % sheetIndex.cols
              const isCurrent = r === sheetIndex.currentRow && c === sheetIndex.currentCol
              const adjSheets = ['NW', 'N', 'NE', 'W', '●', 'E', 'SW', 'S', 'SE']
              return (
                <div key={`${_}-${i}`}
                  className={`flex items-center justify-center text-[6pt] ${isCurrent ? 'bg-black text-white font-bold' : 'bg-gray-100'}`}
                  title={adjSheets[i] ?? `${r+1}-${c+1}`}
                >
                  {isCurrent ? '●' : adjSheets[i]}
                </div>
              )
            })}
          </div>
          <div className="text-[6pt] text-gray-500 mt-0.5">
            {sheetIndex.currentRow === 0 ? 'North' : ''} {sheetIndex.currentCol === 0 ? 'West' : ''}
          </div>
        </div>

        {/* Sub-location / Location */}
        <div className="text-xs flex-1 border border-gray-300 p-1 bg-gray-50">
          <div className="font-bold text-[8pt] mb-1">Location Reference</div>
          <div className="grid grid-cols-2 gap-x-4 text-[7pt]">
            <div><span className="font-bold">District:</span> {district || '—'}</div>
            <div><span className="font-bold">Location:</span> {location || '—'}</div>
            <div><span className="font-bold">Sub-Location:</span> {(location as any)?.subLocation || '—'}</div>
            <div><span className="font-bold">Reg. Unit:</span> {registrationUnit || '—'}</div>
          </div>
        </div>
      </div>

      {/* North Arrow */}
      <div className="absolute top-[38mm] right-[12mm] text-center">
        <div className="text-[8pt] font-bold">N</div>
        <svg width="28" height="36" viewBox="0 0 28 36">
          <polygon points="14,2 4,30 14,24 24,30" fill="#000" />
          <line x1="14" y1="8" x2="14" y2="34" stroke="#000" strokeWidth="1" />
          <text x="16" y="8" fontSize="7" fontWeight="bold" fill="#000">N</text>
        </svg>
        <div className="text-[6pt] text-gray-500">↑ Heading</div>
      </div>

      {/* Parcel Map Area */}
      <div className="border border-black mb-3 min-h-[360px] relative bg-gray-50/50"
        style={{height: 'auto', minHeight: '360px'}}>
        {/* Grid overlay */}
        <div className="absolute inset-0 pointer-events-none"
          style={{
            backgroundImage: 'linear-gradient(#ccc 1px, transparent 1px), linear-gradient(90deg, #ccc 1px, transparent 1px)',
            backgroundSize: '40px 40px',
          }} />

        {parcels.length === 0 ? (
          <div className="flex items-center justify-center h-full min-h-[360px] text-gray-400 text-sm">
            {mode === 'edit' ? '← Add parcels using the panel →' : 'No parcels on this sheet'}
          </div>
        ) : (
          parcels.map((p: any) => (
            <div key={p.id}
              className={`absolute flex flex-col items-center justify-center cursor-pointer ${selectedParcel === p.id ? 'outline-2 outline-blue-500' : ''}`}
              style={{
                left: p.x, top: p.y, width: p.width, height: p.height,
                background: p.color,
              }}
            >
              <span className="text-[9pt] font-bold leading-none">{p.number}</span>
              {p.area && <span className="text-[7pt] text-gray-600">{p.area} ha</span>}
              <div className="border-t border-black/30 w-3/4 mt-0.5" />
            </div>
          ))
        )}
      </div>

      {/* Parcel List Table */}
      {parcels.length > 0 && (
        <div className="mb-3">
          <div className="text-[7pt] font-bold border-b border-black pb-0.5 mb-1">PARCEL REGISTER</div>
          <table className="w-full border-collapse text-[7pt]">
            <thead>
              <tr className="bg-black text-white">
