import { getTraverseValidation } from '@/lib/engine/country-math'
import type { TraverseLeg as EngineTraverseLeg } from '@/lib/engine/types'

interface BlunderResult {
  legName: string
  correction: string
  contribution: string
  isBlunder: boolean
  distanceMismatch: boolean
  warning: string | null
}

function detectBlunders(legs: EngineTraverseLeg[], totalDistance: number): BlunderResult[] {
  const corrections = legs.map((l) => Math.sqrt(l.correctionE ** 2 + l.correctionN ** 2))
  const avgCorrection = corrections.reduce((a, b) => a + b, 0) / corrections.length

  return legs.map((leg, i) => {
    const correction = Math.sqrt(leg.correctionE ** 2 + leg.correctionN ** 2)
    const contribution = (correction / totalDistance) * 100
    const isBlunder = avgCorrection > 0 && correction > avgCorrection * 3

    const computedDist = Math.sqrt(leg.rawDeltaE ** 2 + leg.rawDeltaN ** 2)
    const distanceMismatch = Math.abs(computedDist - leg.distance) > 1.0

    let bearingJumpWarning = false
    if (i > 0) {
      const prevBearing = legs[i - 1].bearing
      const currBearing = leg.bearing
      const diff = Math.abs(currBearing - prevBearing)
      bearingJumpWarning = diff > 150 && diff < 210
    }

    let warning: string | null = null
    if (isBlunder) {
      warning = `Correction ${correction.toFixed(3)}m is ${(correction / avgCorrection).toFixed(1)}× average — check bearing and distance`
    } else if (distanceMismatch) {
      warning = `Computed distance ${computedDist.toFixed(3)}m differs by ${Math.abs(computedDist - leg.distance).toFixed(3)}m`
    } else if (bearingJumpWarning) {
      warning = `Large bearing change of ${Math.abs(legs[i-1].bearing - leg.bearing).toFixed(1)}° — verify field reading`
    }

    return {
      legName: `${leg.from} → ${leg.to}`,
      correction: correction.toFixed(4),
      contribution: contribution.toFixed(1),
      isBlunder,
      distanceMismatch,
      warning
    }
  })
}

interface NamedPoint2D {
  name: string
  easting: number
  northing: number
}

function TraverseDiagram({ stations, closingError }: {
  stations: NamedPoint2D[]
  closingError: { e: number, n: number }
}) {
  const width = 500
  const height = 400
  const padding = 50

  const eastings = stations.map((s) => s.easting)
  const northings = stations.map((s) => s.northing)
  const minE = Math.min(...eastings)
  const maxE = Math.max(...eastings)
  const minN = Math.min(...northings)
  const maxN = Math.max(...northings)

  const scaleE = (width - padding * 2) / (maxE - minE || 1)
  const scaleN = (height - padding * 2) / (maxN - minN || 1)
  const scale = Math.min(scaleE, scaleN)

  function toScreen(e: number, n: number) {
    return {
      x: padding + (e - minE) * scale,
      y: height - padding - (n - minN) * scale
    }
  }

  const points = stations.map((s) => ({
    ...s,
    ...toScreen(s.easting, s.northing)
  }))

  return (
    <svg width={width} height={height} className="bg-[var(--bg-secondary)] rounded border border-amber-500/30 w-full">
      {points.slice(0, -1).map((p, i) => (
        <line
          key={`${p}-${i}`}
          x1={p.x} y1={p.y}
          x2={points[i+1].x} y2={points[i+1].y}
          stroke="#D17B47"
          strokeWidth={2}
        />
      ))}

      {(() => {
        const last = points[points.length - 1]
        const first = points[0]
        return (
          <line
            x1={last.x} y1={last.y}
            x2={first.x} y2={first.y}
            stroke="#ef4444"
            strokeWidth={2}
            strokeDasharray="5,5"
          />
        )
      })()}

      {points.map((p, i) => (
        <g key={p.name}>
          <circle
            cx={p.x} cy={p.y} r={6}
            fill={i === 0 ? '#ef4444' : '#D17B47'}
            stroke="white"
            strokeWidth={1.5}
          />
          <text
            x={p.x + 10} y={p.y - 8}
            fill="white"
            fontSize={11}
            fontFamily="monospace"
          >
            {p.name}
          </text>
        </g>
      ))}

      <g transform={`translate(${width - 30}, 30)`}>
        <line x1={0} y1={20} x2={0} y2={0} stroke="white" strokeWidth={2}/>
        <polygon points="0,-5 -4,5 4,5" fill="white"/>
        <text x={-4} y={30} fill="white" fontSize={10}>N</text>
      </g>

      <text x={10} y={height - 10} fill="#ef4444" fontSize={9} fontFamily="monospace">
        Misclosure vector (dashed red)
      </text>
    </svg>
  )
}

interface RadialComputedPoint {
  name: string
  easting: number
  northing: number
  distance: number
  bearing: number
  cumulativeDist: number
}

interface OpenTraverseStation {
  name: string
  easting: number
  northing: number
  distance: number
  bearing: number | null
  bearingDMS: string
  cumulativeDist: number
}

interface TraverseResultData {
  type?: 'closed' | 'link' | 'open' | 'radial'
  legs?: EngineTraverseLeg[]
  points?: RadialComputedPoint[]
  stations?: OpenTraverseStation[]
  station?: ControlPoint
  openingPoint?: { name: string; easting: number; northing: number }
  closingErrorE: number
  closingErrorN: number
  linearError: number
  precisionRatio: number
  precisionGrade: 'excellent' | 'good' | 'acceptable' | 'poor' | 'N/A'
  totalDistance: number
  isClosed: boolean
}

interface TraverseModalProps {
  isOpen: boolean
  onClose: () => void
  projectId: string
  onTraverseComplete: () => void
  onTraverseResult?: (result: TraverseResultData) => void
}

interface ControlPoint {
  id: string
  name: string
  easting: number
  northing: number
}

interface TraverseLeg {
  id: number
  stationName: string
  distance: string
  bearingDeg: string
  bearingMin: string
  bearingSec: string
}

type TraverseType = 'closed' | 'link' | 'open' | 'radial'

interface RadialObservation {
  id: number
  pointName: string
  bearingDeg: string
  bearingMin: string
  bearingSec: string
  distance: string
}

function CountryPrecisionBadge({ country, totalDistance, linearError }: {
  country: string; totalDistance: number; linearError: number
}) {
  const { getTraverseOrder } = useCountry()
  const order = getTraverseOrder('default')
  if (!order || totalDistance === 0) return null
  const achieved = linearError > 0 ? totalDistance / linearError : Infinity
  const passes = achieved >= order.minPrecision
  return (
    <span className={`px-2 py-1 rounded text-xs font-semibold ${passes ? 'bg-green-900/50 text-green-400' : 'bg-red-900/50 text-red-400'}`}>
      {passes ? '' : '[x]'} Req 1:{order.minPrecision.toLocaleString()}
    </span>
  )
}

export default function TraverseModal({
  isOpen,
  onClose,
  projectId,
  onTraverseComplete,
  onTraverseResult
}: TraverseModalProps) {
  const { country, standard, getTraverseOrder } = useCountry()
  const [controlPoints, setControlPoints] = useState<ControlPoint[]>([])
  const [loading, setLoading] = useState(false)
  const [step, setStep] = useState<'input' | 'results'>('input')
  
  // Traverse type selector
  const [traverseType, setTraverseType] = useState<TraverseType>('closed')
  
  // Radial observations
  const [radialStationId, setRadialStationId] = useState('')
  const [radialObservations, setRadialObservations] = useState<RadialObservation[]>([
    { id: 1, pointName: '', bearingDeg: '', bearingMin: '', bearingSec: '', distance: '' }
  ])
  
  // Opening control
  const [openingUseExisting, setOpeningUseExisting] = useState(true)
  const [openingPointId, setOpeningPointId] = useState('')
  const [openingName, setOpeningName] = useState('')
  const [openingEasting, setOpeningEasting] = useState('')
  const [openingNorthing, setOpeningNorthing] = useState('')
  
  // Traverse legs
  const [legs, setLegs] = useState<TraverseLeg[]>([
    { id: 1, stationName: '', distance: '', bearingDeg: '', bearingMin: '', bearingSec: '' },
    { id: 2, stationName: '', distance: '', bearingDeg: '', bearingMin: '', bearingSec: '' }
  ])
  
  // Closing control
  const [closingUseExisting, setClosingUseExisting] = useState(true)
  const [closingPointId, setClosingPointId] = useState('')
  const [closingName, setClosingName] = useState('')
  const [closingEasting, setClosingEasting] = useState('')
  const [closingNorthing, setClosingNorthing] = useState('')
  const [hasClosingControl, setHasClosingControl] = useState(true)
  
  // Results
  const [results, setResults] = useState<TraverseResultData | null>(null)
  const [blunderResults, setBlunderResults] = useState<BlunderResult[]>([])
  const [diagramStations, setDiagramStations] = useState<NamedPoint2D[]>([])
  const [saveMessage, setSaveMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)
  const [error, setError] = useState('')
  
  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), [])

  const fetchControlPoints = useCallback(async () => {
    const { data } = await dbClient
      .from('survey_points')
      .select('id, point_name as name, easting, northing')  // T1.5d FIX: alias point_name as name for backwards-compat with this component
      .eq('project_id', projectId)
      .eq('is_control', true)
      .order('point_name')  // T1.5d FIX: was 'name'
    
    if (data) {
      setControlPoints(data)
      if (data.length > 0) {
        setOpeningPointId(data[0].id)
        // FIX: Default closing to SECOND control point — cadastral traverses require minimum 2
        // distinct known control points per Survey Regulations Reg. 60 & 67 (Basak Ch.10-11).
        // Defaulting to the same point as opening creates a 1-point traverse (swinging),
        // which has no absolute position check.
        setClosingPointId(data.length > 1 ? data[1].id : '')
      }
    }
  }, [dbClient, projectId])

  useEffect(() => {
    if (isOpen) {
      fetchControlPoints()
      setStep('input')
      setResults(null)
      setSaveMessage(null)
    }
  }, [isOpen, fetchControlPoints])

  const addLeg = () => {
    const newId = legs.length > 0 ? Math.max(...legs.map((l) => l.id)) + 1 : 1
    setLegs([...legs, { id: newId, stationName: '', distance: '', bearingDeg: '', bearingMin: '', bearingSec: '' }])
  }

  const removeLeg = (id: number) => {
    if (legs.length > 2) {
      setLegs(legs.filter((l) => l.id !== id))
    }
  }

  const updateLeg = (id: number, field: keyof TraverseLeg, value: string) => {
    setLegs(legs.map((l) => l.id === id ? { ...l, [field]: value } : l))
  }

  const handleCalculate = async () => {
    setError('')
    setLoading(true)

    try {
      // Validate: closed/link traverses require closing control point per Survey Regulations Reg 60 & 67
      if ((traverseType === 'closed' || traverseType === 'link') && !hasClosingControl) {
        throw new Error('Closing control point is required for closed/link traverses per Survey Regulations Reg. 60(2)(c) and Reg. 67. Swinging/hanging traverses are prohibited.')
      }

      // Validate: cadastral closed/link traverses require 2 DISTINCT known control points
      // Source: Basak Ch.10-11 — A closed traverse "begins and ends at points whose positions
      // on plan are known." With only 1 known point, the traverse has no absolute position
      // check — it could be shifted/rotated from true position. Minimum 2 known points required.
      if (traverseType === 'closed' || traverseType === 'link') {
        // Will validate after resolving opening/closing coordinates (see below)
      }

      // Handle Radial Survey
      if (traverseType === 'radial') {
        if (!radialStationId) {
          throw new Error('Select instrument station')
        }
        
        const station = controlPoints.find((p) => p.id === radialStationId)
        if (!station) throw new Error('Instrument station not found')
        
        const computedPoints: RadialComputedPoint[] = []
        let cumulativeDist = 0
        
        for (const obs of radialObservations) {
          if (!obs.pointName || !obs.distance || !obs.bearingDeg) continue
          
          const dist = parseFloat(obs.distance)
          const bearing = dmsToDecimal({
            degrees: parseInt(obs.bearingDeg) || 0,
            minutes: parseInt(obs.bearingMin) || 0,
            seconds: parseFloat(obs.bearingSec) || 0,
            direction: 'N'
          })
          
          const rad = bearing * Math.PI / 180
          const easting = station.easting + dist * Math.sin(rad)
          const northing = station.northing + dist * Math.cos(rad)
          cumulativeDist += dist
          
          computedPoints.push({
            name: obs.pointName,
            easting,
            northing,
            distance: dist,
            bearing,
            cumulativeDist
          })
        }
        
        setResults({
          type: 'radial',
          station,
          points: computedPoints,
          totalDistance: cumulativeDist,
          closingErrorE: 0,
          closingErrorN: 0,
          linearError: 0,
          precisionRatio: 0,
          precisionGrade: 'N/A',
          isClosed: false
        })
        
        setStep('results')
        setLoading(false)
        return
      }
      
      // Handle Open Traverse (no closing control)
      if (traverseType === 'open') {
        let openingE: number, openingN: number, openingPtName: string
        
        if (openingUseExisting && openingPointId) {
          const pt = controlPoints.find((p) => p.id === openingPointId)
          if (!pt) throw new Error('Select opening control point')
          openingE = pt.easting
          openingN = pt.northing
          openingPtName = pt.name
        } else {
          if (!openingEasting || !openingNorthing || !openingName) {
            throw new Error('Enter opening point coordinates')
          }
          openingE = parseFloat(openingEasting)
          openingN = parseFloat(openingNorthing)
          openingPtName = openingName
        }
        
        const computedStations: OpenTraverseStation[] = []
        let currentE = openingE
        let currentN = openingN
        let cumulativeDist = 0
        
        computedStations.push({
          name: openingPtName,
          easting: currentE,
          northing: currentN,
          distance: 0,
          bearing: null,
          bearingDMS: '—',
          cumulativeDist: 0
        })
        
        for (const leg of legs) {
          if (!leg.distance || !leg.bearingDeg) continue
          
          const dist = parseFloat(leg.distance)
          const bearing = dmsToDecimal({
            degrees: parseInt(leg.bearingDeg) || 0,
            minutes: parseInt(leg.bearingMin) || 0,
            seconds: parseFloat(leg.bearingSec) || 0,
            direction: 'N'
          })
          
          cumulativeDist += dist
          const rad = bearing * Math.PI / 180
          currentE = currentE + dist * Math.sin(rad)
          currentN = currentN + dist * Math.cos(rad)
          
          computedStations.push({
            name: leg.stationName || `T${computedStations.length}`,
            easting: currentE,
            northing: currentN,
            distance: dist,
            bearing,
            bearingDMS: bearingToString(bearing),
            cumulativeDist
          })
        }
        
        setResults({
          type: 'open',
          stations: computedStations,
          openingPoint: { name: openingPtName, easting: openingE, northing: openingN },
          closingErrorE: 0,
          closingErrorN: 0,
          linearError: 0,
          precisionRatio: 0,
          precisionGrade: 'N/A',
          totalDistance: cumulativeDist,
          isClosed: false
        })
        
        setStep('results')
        setLoading(false)
        return
      }
      
      // Existing closed/link traverse logic...
      let openingE: number, openingN: number, openingPtName: string
      
      if (openingUseExisting && openingPointId) {
        const pt = controlPoints.find((p) => p.id === openingPointId)
        if (!pt) throw new Error('Select opening control point')
        openingE = pt.easting
        openingN = pt.northing
        openingPtName = pt.name
      } else {
        if (!openingEasting || !openingNorthing || !openingName) {
          throw new Error('Enter opening point coordinates')
        }
        openingE = parseFloat(openingEasting)
        openingN = parseFloat(openingNorthing)
        openingPtName = openingName
      }

      // Validate: for closed/link traverses, opening and closing must be DIFFERENT known points.
      // Source: Basak Ch.10-11 — A cadastral traverse must begin and end at points whose
      // positions are known. Using the same point for both gives a 1-point traverse with
      // no absolute position check — the traverse could be rotated/shifted undetected.
      // Minimum 2 distinct known control points are required per Survey Regulations Reg. 60 & 67.
      if (traverseType === 'closed' || traverseType === 'link') {
        if (hasClosingControl) {
          let closingECheck: number | undefined, closingNCheck: number | undefined
          if (closingUseExisting && closingPointId) {
            const pt = controlPoints.find((p) => p.id === closingPointId)
            if (pt) { closingECheck = pt.easting; closingNCheck = pt.northing }
          } else if (closingEasting && closingNorthing) {
            closingECheck = parseFloat(closingEasting)
            closingNCheck = parseFloat(closingNorthing)
          }
          if (closingECheck !== undefined && closingNCheck !== undefined) {
            const coordDiff = Math.abs(closingECheck - openingE) + Math.abs(closingNCheck - openingN)
            if (coordDiff < 0.001) {
              throw new Error('Closing control point must be DIFFERENT from opening control point. A cadastral traverse requires minimum 2 distinct known control points for position verification per Survey Regulations Reg. 60(2)(c) and Reg. 67. A 1-point traverse has no absolute position check — the entire traverse could be shifted/rotated from its true position undetected.')
            }
          }
        }
      }

      // Build traverse points - each leg's bearing is from previous point to this leg's point
      const points: { name: string; easting: number; northing: number }[] = [
        { name: openingPtName, easting: openingE, northing: openingN }
      ]
      const distances: number[] = []
      const bearings: number[] = []

      let currentE = openingE
      let currentN = openingN

      for (const leg of legs) {
        if (!leg.distance || !leg.bearingDeg) continue
        
        const dist = parseFloat(leg.distance)
        const bearing = dmsToDecimal({
          degrees: parseInt(leg.bearingDeg) || 0,
          minutes: parseInt(leg.bearingMin) || 0,
          seconds: parseFloat(leg.bearingSec) || 0,
          direction: 'N'
        })
        
        distances.push(dist)
        bearings.push(bearing)
        

        
        // Calculate next point position using this leg's bearing
        const rad = bearing * Math.PI / 180
        currentE = currentE + dist * Math.sin(rad)
        currentN = currentN + dist * Math.cos(rad)
        
        points.push({
          name: leg.stationName || `P${points.length}`,
          easting: currentE,
          northing: currentN
        })
      }

      let closingPoint: { easting: number; northing: number } | undefined

      // Add closing control if provided
      if (hasClosingControl) {
        let closingE: number, closingN: number
        
        if (closingUseExisting && closingPointId) {
          const pt = controlPoints.find((p) => p.id === closingPointId)
          if (!pt) throw new Error('Select closing control point')
          closingE = pt.easting
          closingN = pt.northing
        } else {
          if (!closingEasting || !closingNorthing) {
            throw new Error('Enter closing point coordinates')
          }
          closingE = parseFloat(closingEasting)
          closingN = parseFloat(closingNorthing)
        }
        
        // Use known closing control as a constraint (do not append as an extra computed station)
        // Bowditch will distribute the misclosure across the measured legs.
        closingPoint = { easting: closingE, northing: closingN }
      }

      // Run Bowditch adjustment
      const traverseInput = {
        points,
        distances,
        bearings,
        closingPoint,
      }

      const traverseResult = bowditchAdjustment(traverseInput)
      setResults(traverseResult)
      if (onTraverseResult) {
        onTraverseResult(traverseResult)
      }

      // Run blunder detection
      const blunders = detectBlunders(traverseResult.legs, traverseResult.totalDistance)
      setBlunderResults(blunders)

      // Build diagram stations
      const diagramPts: NamedPoint2D[] = points.map((p) => ({
        name: p.name,
        easting: p.easting,
        northing: p.northing
      }))
      setDiagramStations(diagramPts)

      setStep('results')
    } catch (err: unknown) {
      const message = err instanceof Error ? (err as Error).message : String(err)
      setError(message || 'Calculation failed')
    }

    setLoading(false)
  }

  const loadTestData = () => {
    setOpeningUseExisting(true)
    // Will need to find CP1 from controlPoints
    setTimeout(() => {
      const cp1 = controlPoints.find((p) => p.name === 'CP1')
      if (cp1) {
        setOpeningPointId(cp1.id)
      }
    }, 100)
    setLegs([
      { id: 1, stationName: 'P1', distance: '100', bearingDeg: '0', bearingMin: '0', bearingSec: '0' },
      { id: 2, stationName: 'P2', distance: '100', bearingDeg: '90', bearingMin: '0', bearingSec: '0' },
      { id: 3, stationName: 'P3', distance: '100', bearingDeg: '180', bearingMin: '0', bearingSec: '0' },
      { id: 4, stationName: 'P4', distance: '100', bearingDeg: '270', bearingMin: '0', bearingSec: '0' },
      { id: 5, stationName: 'P5', distance: '100', bearingDeg: '0', bearingMin: '0', bearingSec: '0' },
    ])
    setHasClosingControl(true)
  }

  const handleClose = () => {
    setLegs([
      { id: 1, stationName: '', distance: '', bearingDeg: '', bearingMin: '', bearingSec: '' },
      { id: 2, stationName: '', distance: '', bearingDeg: '', bearingMin: '', bearingSec: '' }
    ])
    setResults(null)
    setError('')
    setSaveMessage(null)
    onClose()
  }

  const handleSaveAndClose = async () => {
    if (!results) return

    // Check precision grade - don't save if POOR
    if (results.precisionGrade === 'poor') {
      setSaveMessage({ 
        type: 'error', 
        text: 'Precision is too low to save. Check your measurements and recalculate.' 
      })
      return
    }

    setLoading(true)

    try {
      // Delete existing non-control traverse stations first
      await dbClient
        .from('survey_points')
        .delete()
        .eq('project_id', projectId)
        .eq('is_control', false)

      // Get the adjusted points from results
      // Results legs have: from, to, adjEasting, adjNorthing
      const adjustedPoints = (results.legs ?? []).map((leg) => ({
        name: leg.to,
        easting: leg.adjEasting,
        northing: leg.adjNorthing
      }))

      // Insert fresh adjusted points (skip opening point as it's the control)
      if (adjustedPoints.length > 0) {
        const pointsToInsert = adjustedPoints
          .filter((p) => p.name)
          .map((p) => ({
            project_id: projectId,
            name: p.name,
            easting: Number(p.easting.toFixed(4)),
            northing: Number(p.northing.toFixed(4)),
            elevation: 0,
            is_control: false
          }))

        const { error: insertError } = await dbClient
          .from('survey_points')
          .insert(pointsToInsert)

        if (insertError) {
          setSaveMessage({ type: 'error', text: `Error saving: ${insertError.message}` })
          setLoading(false)
          return
        }

        setSaveMessage({ 
          type: 'success', 
          text: `${pointsToInsert.length} points saved to project` 
        })
      }

      setLoading(false)
      setTimeout(() => {
        onTraverseComplete()
        handleClose()
      }, 1500)
    } catch (err: unknown) {
      const message = err instanceof Error ? (err as Error).message : String(err)
      setSaveMessage({ type: 'error', text: `Error: ${message}` })
      setLoading(false)
    }
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/70" onClick={handleClose}></div>
      <div className="relative bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6 w-full max-w-4xl max-h-[90vh] overflow-y-auto">
        <h2 className="text-xl font-bold text-[var(--text-primary)] mb-4">Run Traverse</h2>

        {error && (
          <div className="mb-4 p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
            {error}
          </div>
        )}

        {step === 'input' && (
          <div className="space-y-6">
            {/* Traverse Type Selector */}
            <div className="border border-[var(--border-color)] rounded-lg p-4">
              <h3 className="text-lg font-semibold text-[var(--text-primary)] mb-4">Traverse Type</h3>
              
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-4">
                <button
                  type="button"
                  onClick={() => setTraverseType('closed')}
                  className={`p-3 rounded-lg border text-center transition-colors ${
                    traverseType === 'closed' 
                      ? 'border-[var(--accent)] bg-[var(--accent)]/10' 
                      : 'border-[var(--border-color)] hover:border-gray-600'
                  }`}
                >
                  <div className="font-medium text-[var(--text-primary)]">Closed Loop</div>
                </button>
                <button
                  type="button"
                  onClick={() => setTraverseType('link')}
                  className={`p-3 rounded-lg border text-center transition-colors ${
                    traverseType === 'link' 
                      ? 'border-[var(--accent)] bg-[var(--accent)]/10' 
                      : 'border-[var(--border-color)] hover:border-gray-600'
                  }`}
                >
                  <div className="font-medium text-[var(--text-primary)]">Link</div>
                </button>
                <button
                  type="button"
                  onClick={() => setTraverseType('open')}
                  className={`p-3 rounded-lg border text-center transition-colors ${
                    traverseType === 'open' 
                      ? 'border-[var(--accent)] bg-[var(--accent)]/10' 
                      : 'border-[var(--border-color)] hover:border-gray-600'
                  }`}
                >
                  <div className="font-medium text-[var(--text-primary)]">Open</div>
                </button>
                <button
                  type="button"
                  onClick={() => setTraverseType('radial')}
                  className={`p-3 rounded-lg border text-center transition-colors ${
                    traverseType === 'radial' 
                      ? 'border-[var(--accent)] bg-[var(--accent)]/10' 
                      : 'border-[var(--border-color)] hover:border-gray-600'
                  }`}
                >
                  <div className="font-medium text-[var(--text-primary)]">Radial</div>
                </button>
              </div>
              
              <div className="text-sm text-[var(--text-secondary)] bg-[var(--bg-tertiary)]/50 rounded p-3">
                {traverseType === 'closed' && 'Link Traverse (Closed): Connects two different known control points. The traverse is Bowditch-adjusted to distribute the closing error. Both opening AND closing control points are mandatory and must be DIFFERENT — minimum 2 distinct known points per Survey Regulations Reg. 60 & 67. A 1-point traverse has no absolute position check.'}
                {traverseType === 'link' && 'Link Traverse: Connects two known control points. Precision checked against closing control. Both opening AND closing control points are mandatory and must be DIFFERENT per Survey Regulations Reg. 60 & 67. Minimum 2 distinct known control points required.'}
                {traverseType === 'open' && 'Open Traverse: Starts at known control, no closing control. Used for roads/pipelines where no check is available. Running coordinates only — NOT acceptable for cadastral surveys per Reg. 67 (swinging traverses prohibited).'}
                {traverseType === 'radial' && 'Radial Survey: One instrument station observing multiple detail points. Compute coordinates for each ray. Requires at least one known control point with backsight orientation.'}
              </div>
            </div>

            {/* Radial Survey Input */}
            {traverseType === 'radial' && (
              <div className="border border-[var(--border-color)] rounded-lg p-4">
                <h3 className="text-lg font-semibold text-[var(--text-primary)] mb-4">Radial Survey</h3>
                
                <div className="mb-4">
                  <label className="block text-sm text-[var(--text-secondary)] mb-2" htmlFor="instrument-station">Instrument Station</label>
                  <select id="instrument-station"
                    value={radialStationId}
                    onChange={(e) => setRadialStationId(e.target.value)}
                    className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]"
                  >
                    <option value="">Select station...</option>
                    {controlPoints.map((p) => (
                      <option key={p.id} value={p.id}>{p.name}</option>
                    ))}
                  </select>
                </div>
                
                <div className="space-y-3">
                  {radialObservations.map((obs, idx) => (
                    <div key={obs.id} className="grid grid-cols-5 gap-2 items-end">
                      <div>
                        <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor={`rad-point-${idx}`}>Point</label>
                        <input id={`rad-point-${idx}`}
                          type="text"
                          value={obs.pointName}
                          onChange={(e) => {
                            const updated = [...radialObservations]
                            updated[idx].pointName = e.target.value
                            setRadialObservations(updated)
                          }}
                          className="w-full px-2 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
                          placeholder="P1"
                        />
                      </div>
                      <div>
                        <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor={`rad-deg-${idx}`}>Deg</label>
                        <input id={`rad-deg-${idx}`}
                          type="number"
                          value={obs.bearingDeg}
                          onChange={(e) => {
                            const updated = [...radialObservations]
                            updated[idx].bearingDeg = e.target.value
                            setRadialObservations(updated)
                          }}
                          className="w-full px-2 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
                          placeholder="000"
                        />
                      </div>
                      <div>
                        <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor={`rad-min-${idx}`}>Min</label>
                        <input id={`rad-min-${idx}`}
                          type="number"
                          value={obs.bearingMin}
                          onChange={(e) => {
                            const updated = [...radialObservations]
                            updated[idx].bearingMin = e.target.value
                            setRadialObservations(updated)
                          }}
                          className="w-full px-2 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
                          placeholder="00"
                        />
                      </div>
                      <div>
                        <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor={`rad-sec-${idx}`}>Sec</label>
                        <input id={`rad-sec-${idx}`}
                          type="number"
                          value={obs.bearingSec}
                          onChange={(e) => {
                            const updated = [...radialObservations]
                            updated[idx].bearingSec = e.target.value
                            setRadialObservations(updated)
                          }}
                          className="w-full px-2 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
                          placeholder="00"
                        />
                      </div>
                      <div>
                        <div className="block text-xs text-[var(--text-muted)] mb-1">Dist (m)</div>
                        <div className="flex gap-1">
                          <input
                            type="number"
                            value={obs.distance}
                            onChange={(e) => {
                              const updated = [...radialObservations]
                              updated[idx].distance = e.target.value
                              setRadialObservations(updated)
                            }}
                            className="flex-1 px-2 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
                            aria-label="Distance (m)" placeholder="0.000"
                          />
                          {radialObservations.length > 1 && (
                            <button
                              type="button"
                              onClick={() => setRadialObservations(radialObservations.filter((_, i) => i !== idx))}
                              className="px-2 py-2 bg-red-900/50 hover:bg-red-900 text-red-400 rounded text-sm"
                            >
                              ×
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                
                <button
                  type="button"
                  onClick={() => setRadialObservations([...radialObservations, { 
                    id: radialObservations.length + 1, 
                    pointName: '', 
                    bearingDeg: '', 
                    bearingMin: '', 
                    bearingSec: '', 
                    distance: '' 
                  }])}
                  className="mt-3 px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded text-sm"
                >
                  + Add Point
                </button>
              </div>
            )}

            {/* Section 1: Opening Control Point */}
            {traverseType !== 'radial' && (
            <div className="border border-[var(--border-color)] rounded-lg p-4">
              <div className="flex items-center justify-between mb-3">
                <h3 className="text-lg font-semibold text-[var(--text-primary)]">Opening Control Point</h3>
                {process.env.NODE_ENV === 'development' && (
                  <button
                    type="button"
                    onClick={loadTestData}
                    className="text-xs text-[var(--text-muted)] underline hover:text-[var(--text-secondary)]"
                  >
                    Load test data
                  </button>
                )}
              </div>
              
              <div className="flex gap-4 mb-4">
                <label className="flex items-center gap-2 text-[var(--text-primary)]">
                  <input aria-label="Use existing opening coordinates"
                    type="radio"
                    checked={openingUseExisting}
                    onChange={() => setOpeningUseExisting(true)}
                    className="text-[var(--accent)]"
                  />
                  Select from project
                </label>
                <label className="flex items-center gap-2 text-[var(--text-primary)]">
                  <input aria-label="Enter opening coordinates manually"
                    type="radio"
                    checked={!openingUseExisting}
                    onChange={() => setOpeningUseExisting(false)}
                    className="text-[var(--accent)]"
                  />
                  Manual entry
                </label>
              </div>

              {openingUseExisting ? (
                <select
                  value={openingPointId}
                  onChange={(e) => setOpeningPointId(e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]"
                >
                  {controlPoints.map((p) => (
                    <option key={p.id} value={p.id}>{p.name} (E: {p.easting.toFixed(4)}, N: {p.northing.toFixed(4)})</option>
                  ))}
                </select>
              ) : (
                <div className="grid grid-cols-3 gap-3">
                  <input
                    type="text"
                    aria-label="Point Name" placeholder="e.g. TP01"
                    value={openingName}
                    onChange={(e) => setOpeningName(e.target.value)}
                    className="px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                  />
                  <input
                    type="number"
                    aria-label="Easting" placeholder="e.g. 500000.000"
                    value={openingEasting}
                    onChange={(e) => setOpeningEasting(e.target.value)}
                    className="px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                  />
                  <input
                    type="number"
                    aria-label="Northing" placeholder="e.g. 9900000.000"
                    value={openingNorthing}
                    onChange={(e) => setOpeningNorthing(e.target.value)}
                    className="px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                  />
                </div>
              )}

            </div>
            )}

            {/* Section 2: Traverse Legs */}
            <div className="border border-[var(--border-color)] rounded-lg p-4">
              <h3 className="text-lg font-semibold text-[var(--text-primary)] mb-3">Traverse Legs</h3>
              
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--border-color)]">
                      <th className="px-2 py-2 text-left text-[var(--text-primary)]">Station</th>
                      <th className="px-2 py-2 text-left text-[var(--text-primary)]">Distance (m)</th>
                      <th className="px-2 py-2 text-left text-[var(--text-primary)]" colSpan={3}>Bearing (DMS)</th>
                      <th className="px-2 py-2"></th>
                    </tr>
                  </thead>
                  <tbody>
                    {legs.map((leg) => (
                      <tr key={leg.id} className="border-b border-[var(--border-color)]/50">
                        <td className="px-2 py-2">
                          <input
                            type="text"
                            value={leg.stationName}
                            onChange={(e) => updateLeg(leg.id, 'stationName', e.target.value)}
                            aria-label="Station" placeholder="TP01"
                            className="w-full px-2 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                          />
                        </td>
                        <td className="px-2 py-2">
                          <input aria-label="Distance (m)"
                            type="number"
                            step="0.001"
                            value={leg.distance}
                            onChange={(e) => updateLeg(leg.id, 'distance', e.target.value)}
                            className="w-28 px-2 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                          />
                        </td>
                        <td className="px-1 py-2">
                          <input
                            type="number"
                            aria-label="Bearing (DMS) — Deg" placeholder="D"
                            value={leg.bearingDeg}
                            onChange={(e) => updateLeg(leg.id, 'bearingDeg', e.target.value)}
                            className="w-14 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                          />
                        </td>
                        <td className="px-1 py-2">
                          <input
                            type="number"
                            aria-label="Bearing (DMS) — Min" placeholder="M"
                            value={leg.bearingMin}
                            onChange={(e) => updateLeg(leg.id, 'bearingMin', e.target.value)}
                            className="w-12 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                          />
                        </td>
                        <td className="px-1 py-2">
                          <input
                            type="number"
                            aria-label="Bearing (DMS) — Sec" placeholder="S"
                            value={leg.bearingSec}
                            onChange={(e) => updateLeg(leg.id, 'bearingSec', e.target.value)}
                            className="w-14 px-1 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                          />
                        </td>
                        <td className="px-2 py-2">
                          {legs.length > 2 && (
                            <button
                              onClick={() => removeLeg(leg.id)}
                              className="text-red-400 hover:text-red-300"
                            >
                              ×
                            </button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <button
                onClick={addLeg}
                className="mt-3 px-3 py-1 text-sm bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded"
              >
                + Add Row
              </button>
            </div>

            {/* Section 3: Closing Control - MANDATORY for closed/link per Survey Regulations Reg 60 & 67 */}
            {(traverseType === 'closed' || traverseType === 'link') && (
            <div className="border border-[var(--border-color)] rounded-lg p-4">
              <div className="flex items-center gap-2 mb-3">
                <h3 className="text-lg font-semibold text-[var(--text-primary)]">Closing Control Point</h3>
                <span className="ml-2 px-2 py-0.5 bg-red-900/50 text-red-400 text-xs rounded font-semibold">REQUIRED — 2+ Known Points</span>
              </div>

              <div className="mb-3 p-3 bg-blue-900/20 border border-blue-700/50 rounded text-blue-300 text-xs">
                <strong>Survey Principle (Basak Ch.10-11):</strong> A cadastral traverse must begin and end at points whose positions are known — minimum 2 distinct known control points. Using only 1 known point creates a swinging traverse with no absolute position check: the entire traverse could be shifted or rotated from its true position without detection. The closing control point must be a DIFFERENT known station from the opening.
              </div>
              
              {hasClosingControl && (
                <>
                  <div className="flex gap-4 mb-4">
                    <label className="flex items-center gap-2 text-[var(--text-primary)]">
                      <input aria-label="Use existing closing coordinates"
                        type="radio"
                        checked={closingUseExisting}
                        onChange={() => setClosingUseExisting(true)}
                        className="text-[var(--accent)]"
                      />
                      Select from project
                    </label>
                    <label className="flex items-center gap-2 text-[var(--text-primary)]">
                      <input aria-label="Enter closing coordinates manually"
                        type="radio"
                        checked={!closingUseExisting}
                        onChange={() => setClosingUseExisting(false)}
                        className="text-[var(--accent)]"
                      />
                      Manual entry
                    </label>
                  </div>

                  {closingUseExisting ? (
                    <select
                      value={closingPointId}
                      onChange={(e) => setClosingPointId(e.target.value)}
                      className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)]"
                    >
                      <option value="">Select closing control point...</option>
                      {controlPoints.map((p) => (
                        <option key={p.id} value={p.id}>{p.name} (E: {p.easting.toFixed(4)}, N: {p.northing.toFixed(4)})</option>
                      ))}
                    </select>
                  ) : (
                    <div className="grid grid-cols-3 gap-3">
                      <input
                        type="text"
                        aria-label="Point Name" placeholder="e.g. TP01"
                        value={closingName}
                        onChange={(e) => setClosingName(e.target.value)}
                        className="px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                      />
                      <input
                        type="number"
                        aria-label="Easting" placeholder="e.g. 500000.000"
                        value={closingEasting}
                        onChange={(e) => setClosingEasting(e.target.value)}
                        className="px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                      />
                      <input
                        type="number"
                        aria-label="Northing" placeholder="e.g. 9900000.000"
                        value={closingNorthing}
                        onChange={(e) => setClosingNorthing(e.target.value)}
                        className="px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] font-mono"
                      />
                    </div>
                  )}
                </>
              )}

              {!hasClosingControl && (
                <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
                  <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> Without a closing control point, this becomes a swinging/hanging traverse — prohibited by Survey Regulations Reg. 67 and Reg. 60(2)(c). A traverse must close between two previously fixed stations.
                </div>
              )}
            </div>
            )}

            <div className="flex gap-3">
              <button
                onClick={handleClose}
                className="px-6 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded"
              >
                Cancel
              </button>
              <button
                onClick={handleCalculate}
                disabled={loading}
                className="flex-1 px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded disabled:opacity-50"
              >
                {loading ? 'Calculating...' : 'Calculate'}
              </button>
            </div>
          </div>
        )}

        {step === 'results' && results && (
          <div className="space-y-6">
            {/* Summary Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
                <p className="text-[var(--text-secondary)] text-xs">Closing Error E</p>
                <p className="text-xl font-mono text-[var(--text-primary)]">{results.closingErrorE.toFixed(4)} m</p>
              </div>
              <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
                <p className="text-[var(--text-secondary)] text-xs">Closing Error N</p>
                <p className="text-xl font-mono text-[var(--text-primary)]">{results.closingErrorN.toFixed(4)} m</p>
              </div>
              <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
                <p className="text-[var(--text-secondary)] text-xs">Linear Misclosure</p>
                <p className="text-xl font-mono text-[var(--text-primary)]">{results.linearError.toFixed(4)} m</p>
              </div>
              <div className="bg-[var(--bg-tertiary)]/50 rounded p-3">
                <p className="text-[var(--text-secondary)] text-xs">Precision</p>
                <p className="text-xl font-mono text-[var(--text-primary)]">1 : {results.precisionRatio > 0 ? Math.round(results.precisionRatio).toLocaleString() : '—'}</p>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <span className="text-[var(--text-primary)]">Grade:</span>
              <span className={`px-2 py-1 rounded text-sm font-semibold ${
                results.precisionGrade === 'excellent' ? 'bg-green-900/50 text-green-400' :
                results.precisionGrade === 'good' ? 'bg-blue-900/50 text-blue-400' :
                results.precisionGrade === 'acceptable' ? 'bg-yellow-900/50 text-yellow-400' :
                'bg-red-900/50 text-red-400'
              }`}>
                {results.precisionGrade.toUpperCase()}
              </span>
              <span className="px-2 py-1 rounded text-xs bg-blue-900/50 text-blue-400">
                {standard.isoCode} · {standard.name}
              </span>
              <CountryPrecisionBadge country={country} totalDistance={results.totalDistance} linearError={results.linearError} />
            </div>

            {saveMessage && (
              <div className={`p-3 rounded text-sm ${
                saveMessage.type === 'success' 
                  ? 'bg-green-900/30 border border-green-600 text-green-400' 
                  : 'bg-red-900/30 border border-red-600 text-red-400'
              }`}>
                {saveMessage.text}
              </div>
            )}

            {/* Gale's Table */}
            <div className="overflow-x-auto">
              <table className="w-full text-xs">
                <thead>
                  <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/50">
                    <th className="px-2 py-2 text-left text-[var(--text-primary)]">Line</th>
                    <th className="px-2 py-2 text-right text-[var(--text-primary)]">Distance</th>
                    <th className="px-2 py-2 text-left text-[var(--text-primary)]">Bearing</th>
                    <th className="px-2 py-2 text-right text-[var(--text-primary)]">Lat(+N)</th>
                    <th className="px-2 py-2 text-right text-[var(--text-primary)]">Lat(-S)</th>
                    <th className="px-2 py-2 text-right text-[var(--text-primary)]">Dep(+E)</th>
                    <th className="px-2 py-2 text-right text-[var(--text-primary)]">Dep(-W)</th>
                    <th className="px-2 py-2 text-right text-[var(--text-primary)]">Adj Lat</th>
                    <th className="px-2 py-2 text-right text-[var(--text-primary)]">Adj Dep</th>
                  </tr>
                </thead>
                <tbody>
                  {(results.legs ?? []).map((leg, idx) => {
                    const blunder = blunderResults[idx]
                    const isBlunderRow = blunder?.isBlunder || blunder?.distanceMismatch
                    return (
                      <tr key={`${leg}-${idx}`} className={`border-b border-[var(--border-color)]/50 ${isBlunderRow ? 'bg-red-900/30' : ''}`}>
                        <td className={`px-2 py-2 font-mono ${isBlunderRow ? 'text-red-400' : 'text-[var(--text-primary)]'}`}>
                          {leg.from} → {leg.to}
                          {isBlunderRow && <span className="ml-2 text-red-400"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /></span>}
                        </td>
                        <td className="px-2 py-2 text-right font-mono text-[var(--text-primary)]">{leg.distance.toFixed(3)}</td>
                        <td className="px-2 py-2 font-mono text-[var(--text-primary)]">{leg.bearingDMS}</td>
                        <td className="px-2 py-2 text-right font-mono text-[var(--text-primary)]">{leg.rawDeltaN > 0 ? leg.rawDeltaN.toFixed(4) : '-'}</td>
                        <td className="px-2 py-2 text-right font-mono text-[var(--text-primary)]">{leg.rawDeltaN < 0 ? Math.abs(leg.rawDeltaN).toFixed(4) : '-'}</td>
                        <td className="px-2 py-2 text-right font-mono text-[var(--text-primary)]">{leg.rawDeltaE > 0 ? leg.rawDeltaE.toFixed(4) : '-'}</td>
                        <td className="px-2 py-2 text-right font-mono text-[var(--text-primary)]">{leg.rawDeltaE < 0 ? Math.abs(leg.rawDeltaE).toFixed(4) : '-'}</td>
                        <td className="px-2 py-2 text-right font-mono text-[var(--accent)]">{leg.adjDeltaN.toFixed(4)}</td>
                        <td className="px-2 py-2 text-right font-mono text-[var(--accent)]">{leg.adjDeltaE.toFixed(4)}</td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>

            {/* Traverse Diagram */}
            {diagramStations.length > 0 && (
              <div className="mt-4">
                <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-2">Traverse Diagram</h3>
                <div className="flex justify-center">
                  <TraverseDiagram 
                    stations={diagramStations} 
                    closingError={{ e: results.closingErrorE, n: results.closingErrorN }} 
                  />
                </div>
              </div>
            )}

            {/* Blunder Analysis */}
            {blunderResults.length > 0 && (
              <div className="mt-4 p-3 bg-[var(--bg-tertiary)]/50 rounded border border-[var(--border-color)]">
                <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-2">Blunder Detection Analysis</h3>
                <div className="space-y-2">
                  {blunderResults.map((b, i) => (
                    <div key={`${b}-${i}`} className={`flex items-center gap-2 text-xs ${b.isBlunder || b.distanceMismatch ? 'text-red-400' : 'text-[var(--text-secondary)]'}`}>
                      <span className="font-mono">{b.legName}</span>
                      <div className="flex-1 h-2 bg-[var(--bg-tertiary)] rounded overflow-hidden">
                        <div 
                          className={`h-full ${b.isBlunder ? 'bg-red-500' : 'bg-green-600'}`} 
                          style={{ width: `${Math.min(parseFloat(b.contribution), 100)}%` }}
                        />
                      </div>
                      <span className="w-12 text-right">{b.contribution}%</span>
                      {b.isBlunder && <span className="text-red-400"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> CHECK</span>}
                      {!b.isBlunder && !b.distanceMismatch && <span className="text-green-400"> OK</span>}
                    </div>
                  ))}
                </div>
                {blunderResults.some((b) => b.warning) && (
                  <div className="mt-3 pt-2 border-t border-[var(--border-color)]">
                    <p className="text-xs text-[var(--text-secondary)] mb-1">Warnings:</p>
                    {blunderResults.filter((b) => b.warning).map((b, i) => (
                      <p key={`${b}-${i}`} className="text-xs text-red-400">• {b.warning}</p>
                    ))}
                  </div>
                )}
              </div>
            )}

            <div className="flex gap-3">
              <button
                onClick={() => {
                  setStep('input')
                  setSaveMessage(null)
                }}
                className="px-6 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] text-[var(--text-primary)] rounded"
              >
                Back
              </button>
              <button
                onClick={handleSaveAndClose}
                className="flex-1 px-6 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold rounded"
              >
                Save & Close
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { useState, useRef, useCallback } from 'react'
import { Upload, File, AlertCircle, CheckCircle, Loader2 } from 'lucide-react'

interface UploadZoneProps {
  onUploadComplete?: (result: UploadResult) => void
  accept?: string
  maxSize?: number
}

interface UploadResult {
  success: boolean
  type: string
  confidence: number
  hasBuilding: boolean
  hasBoq: boolean
  errors: string[]
  warnings: string[]
  building?: {
    floors: number
    walls: number
    rooms: number
    doors: number
    windows: number
  }
  boq?: {
    items: number
    total: number
  }
}

export default function UploadZone({ 
  onUploadComplete,
  accept = '.dxf,.dwg,.ifc,.pdf,.jpg,.jpeg,.png,.webp,.glb,.gltf,.obj,.xlsx,.xls,.csv',
  maxSize = 100 * 1024 * 1024
}: UploadZoneProps) {
  const [isDragging, setIsDragging] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [progress, setProgress] = useState('')
  const [result, setResult] = useState<UploadResult | null>(null)
  const [error, setError] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const handleFile = useCallback(async (file: File) => {
    if (file.size > maxSize) {
      setError(`File too large. Max size is ${maxSize / 1024 / 1024}MB`)
      return
    }

    setUploading(true)
    setError(null)
    setResult(null)
    setProgress('Reading file...')

    try {
      const formData = new FormData()
      formData.append('file', file)
      formData.append('enhanceWithAI', 'true')

      setProgress('Parsing...')
      
      const response = await fetch('/api/parsers/upload', {
        method: 'POST',
        body: formData,
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.error || 'Upload failed')
      }

      setResult(data)
      onUploadComplete?.(data)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed')
    } finally {
      setUploading(false)
      setProgress('')
    }
  }, [maxSize, onUploadComplete])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
    
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }, [handleFile])

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(true)
  }, [])

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
  }, [])

  const handleChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) handleFile(file)
  }, [handleFile])

  const getFileIcon = (filename: string) => {
    const ext = filename.split('.').pop()?.toLowerCase()
    const colors: Record<string, string> = {
      dxf: 'text-blue-400',
      dwg: 'text-blue-500',
      ifc: 'text-purple-400',
      pdf: 'text-red-400',
      jpg: 'text-green-400',
      jpeg: 'text-green-400',
      png: 'text-green-400',
      webp: 'text-green-400',
      glb: 'text-amber-400',
      gltf: 'text-amber-400',
      obj: 'text-amber-500',
      xlsx: 'text-emerald-400',
      xls: 'text-emerald-500',
      csv: 'text-emerald-600',
    }
    return colors[ext || ''] || 'text-gray-400'
  }

  return (
    <div className="space-y-4">
      <div
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onClick={() => inputRef.current?.click()}
        className={`
          border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-all
          ${isDragging 
            ? 'border-[var(--accent)] bg-[var(--accent)]/10' 
            : 'border-[var(--border-color)] hover:border-[var(--accent)] hover:bg-[var(--bg-secondary)]/50'}
        `}
      >
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          onChange={handleChange}
          className="hidden"
        />
        
        <div className="flex flex-col items-center gap-3">
          {uploading ? (
            <>
              <Loader2 className="w-10 h-10 text-[var(--accent)] animate-spin" />
              <p className="text-sm text-[var(--text-secondary)]">{progress || 'Processing...'}</p>
            </>
          ) : (
            <>
              <Upload className={`w-10 h-10 ${isDragging ? 'text-[var(--accent)]' : 'text-[var(--text-muted)]'}`} />
              <div>
                <p className="text-sm font-medium text-[var(--text-primary)]">
                  Drop file here or click to upload
                </p>
                <p className="text-xs text-[var(--text-muted)] mt-1">
                  DXF, DWG, IFC, PDF, Images, 3D Models, BOQ (max 100MB)
                </p>
              </div>
            </>
          )}
        </div>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-900/20 border border-red-700/40">
          <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0" />
          <p className="text-sm text-red-400">{error}</p>
        </div>
      )}

      {result && (
        <div className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-secondary)]/50 p-4 space-y-3">
          <div className="flex items-center gap-2">
            {result.success ? (
              <CheckCircle className="w-5 h-5 text-green-400" />
            ) : (
              <AlertCircle className="w-5 h-5 text-yellow-400" />
            )}
            <span className="font-medium text-[var(--text-primary)]">
              {result.success ? 'Parse Complete' : 'Parse with Issues'}
            </span>
            <span className="ml-auto text-sm text-[var(--text-muted)]">
              {result.type}
            </span>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-sm">
            <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
              <div className="text-[var(--text-muted)] text-xs">Confidence</div>
              <div className="font-medium text-[var(--text-primary)]">
                {Math.round(result.confidence * 100)}%
              </div>
            </div>
            {result.building && (
              <>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">Walls</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.building.walls}</div>
                </div>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">Rooms</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.building.rooms}</div>
                </div>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">Floors</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.building.floors}</div>
                </div>
              </>
            )}
            {result.boq && (
              <>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">BOQ Items</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.boq.items}</div>
                </div>
                <div className="bg-[var(--bg-tertiary)]/50 rounded p-2">
                  <div className="text-[var(--text-muted)] text-xs">Total</div>
                  <div className="font-medium text-[var(--text-primary)]">{result.boq.total.toLocaleString()}</div>
                </div>
              </>
            )}
          </div>

          {result.warnings.length > 0 && (
            <div className="text-xs text-[var(--text-muted)]">
              <span className="font-medium">Warnings:</span> {result.warnings.join(', ')}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * PerformanceMonitor — Core Web Vitals tracking for admins
 *
 * Tracks:
 * - LCP (Largest Contentful Paint)
 * - FID/INP (First Input Delay / Interaction to Next Paint)
 * - CLS (Cumulative Layout Shift)
 * - TTFB (Time to First Byte)
 * - FC (Fetch Count)
 *
 * Sends metrics to /api/admin/performance for aggregation
 * Only active for admin users to avoid overhead for regular users.
 */

import { useEffect, useState, useCallback } from 'react'
import { Activity, Gauge, Zap, Clock, AlertTriangle } from 'lucide-react'

interface WebVital {
  name: string
  value: number
  rating: 'good' | 'needs-improvement' | 'poor'
  label: string
  unit: string
  icon: typeof Activity
}

const VITAL_THRESHOLDS: Record<string, { good: number; poor: number; label: string; unit: string; icon: typeof Activity }> = {
  LCP: { good: 2500, poor: 4000, label: 'Largest Contentful Paint', unit: 'ms', icon: Gauge },
  FID: { good: 100, poor: 300, label: 'First Input Delay', unit: 'ms', icon: Zap },
  INP: { good: 200, poor: 500, label: 'Interaction to Next Paint', unit: 'ms', icon: Zap },
  CLS: { good: 0.1, poor: 0.25, label: 'Cumulative Layout Shift', unit: '', icon: Activity },
  TTFB: { good: 800, poor: 1800, label: 'Time to First Byte', unit: 'ms', icon: Clock },
}

function getRating(name: string, value: number): 'good' | 'needs-improvement' | 'poor' {
  const thresholds = VITAL_THRESHOLDS[name]
  if (!thresholds) return 'good'
  if (value <= thresholds.good) return 'good'
  if (value >= thresholds.poor) return 'poor'
  return 'needs-improvement'
}

const RATING_COLORS: Record<string, string> = {
  good: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/30',
  'needs-improvement': 'text-amber-400 bg-amber-500/10 border-amber-500/30',
  poor: 'text-red-400 bg-red-500/10 border-red-500/30',
}

export function PerformanceMonitor({ visible = false }: { visible?: boolean }) {
  const [vitals, setVitals] = useState<WebVital[]>([])
  const [fetchCount, setFetchCount] = useState(0)

  // Track Core Web Vitals
  useEffect(() => {
    if (!visible) return

    // Use Performance Observer API
    const observers: PerformanceObserver[] = []

    try {
      // LCP
      const lcpObserver = new PerformanceObserver((list) => {
        const entries = list.getEntries()
        const lastEntry = entries[entries.length - 1]
        if (lastEntry) {
          const value = lastEntry.startTime
          setVitals(prev => [
            ...prev.filter(v => v.name !== 'LCP'),
            { name: 'LCP', value, rating: getRating('LCP', value), label: VITAL_THRESHOLDS.LCP.label, unit: VITAL_THRESHOLDS.LCP.unit, icon: VITAL_THRESHOLDS.LCP.icon },
          ])
        }
      })
      lcpObserver.observe({ type: 'largest-contentful-paint', buffered: true })
      observers.push(lcpObserver)

      // FID / INP
      const fidObserver = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          const value = (entry as any).processingStart - entry.startTime
          const name = 'INP'
          setVitals(prev => [
            ...prev.filter(v => v.name !== name),
            { name, value, rating: getRating(name, value), label: VITAL_THRESHOLDS[name].label, unit: VITAL_THRESHOLDS[name].unit, icon: VITAL_THRESHOLDS[name].icon },
          ])
        }
      })
      fidObserver.observe({ type: 'first-input', buffered: true })
      observers.push(fidObserver)

      // CLS
      let clsValue = 0
      const clsObserver = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (!(entry as any).hadRecentInput) {
            clsValue += (entry as any).value
          }
        }
        setVitals(prev => [
          ...prev.filter(v => v.name !== 'CLS'),
          { name: 'CLS', value: clsValue, rating: getRating('CLS', clsValue), label: VITAL_THRESHOLDS.CLS.label, unit: VITAL_THRESHOLDS.CLS.unit, icon: VITAL_THRESHOLDS.CLS.icon },
        ])
      })
      clsObserver.observe({ type: 'layout-shift', buffered: true })
      observers.push(clsObserver)

      // TTFB
      const navEntries = performance.getEntriesByType('navigation')
      if (navEntries.length > 0) {
        const navEntry = navEntries[0] as PerformanceNavigationTiming
        const value = navEntry.responseStart - navEntry.requestStart
        setVitals(prev => [
          ...prev.filter(v => v.name !== 'TTFB'),
          { name: 'TTFB', value, rating: getRating('TTFB', value), label: VITAL_THRESHOLDS.TTFB.label, unit: VITAL_THRESHOLDS.TTFB.unit, icon: VITAL_THRESHOLDS.TTFB.icon },
        ])
      }
    } catch (err) {
      console.warn('[PerformanceMonitor] Observer error:', err)
    }

    // Track fetch count
    const originalFetch = window.fetch
    window.fetch = function (...args) {
      setFetchCount(prev => prev + 1)
      return originalFetch.apply(this, args)
    }

    return () => {
      observers.forEach(o => o.disconnect())
      window.fetch = originalFetch
    }
  }, [visible])

  // Send metrics to server (debounced)
  const sendMetrics = useCallback(async () => {
    if (vitals.length === 0) return
    try {
      await fetch('/api/admin/performance', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          vitals: vitals.map(v => ({ name: v.name, value: v.value })),
          url: window.location.pathname,
          timestamp: Date.now(),
        }),
      }).catch(() => {}) // Silent fail
    } catch {}
  }, [vitals])

  useEffect(() => {
    if (!visible || vitals.length === 0) return
    const timer = setTimeout(sendMetrics, 5000)
    return () => clearTimeout(timer)
  }, [vitals, visible, sendMetrics])

  if (!visible) return null

  return (
    <div className="fixed bottom-4 right-4 z-[999] bg-[#0d0d14]/95 backdrop-blur-xl border border-white/[0.1] rounded-xl shadow-2xl p-3 w-[280px]">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5">
          <Activity className="w-3.5 h-3.5 text-[var(--accent)]" />
          <span className="text-[10px] font-semibold text-white uppercase tracking-wider">Performance</span>
        </div>
        <span className="text-[9px] text-gray-500">{fetchCount} requests</span>
      </div>

      <div className="space-y-1.5">
        {vitals.map(vital => {
          const Icon = vital.icon
          return (
            <div key={vital.name} className="flex items-center gap-2">
              <div className={`shrink-0 w-6 h-6 rounded flex items-center justify-center ${RATING_COLORS[vital.rating]}`}>
                <Icon className="w-3 h-3" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] text-gray-400">{vital.name}</span>
                  <span className={`text-[10px] font-mono font-bold ${
                    vital.rating === 'good' ? 'text-emerald-400' :
                    vital.rating === 'poor' ? 'text-red-400' : 'text-amber-400'
                  }`}>
                    {vital.value.toFixed(vital.unit === '' ? 3 : 0)}{vital.unit}
                  </span>
                </div>
                <div className="text-[8px] text-gray-600">{vital.label}</div>
              </div>
            </div>
          )
        })}

        {vitals.length === 0 && (
          <div className="flex items-center justify-center py-3">
            <AlertTriangle className="w-4 h-4 text-gray-600 mr-1" />
            <span className="text-[10px] text-gray-600">Collecting metrics...</span>
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import {
  Search,
  User,
  Crown,
  Rocket,
  Building2,
  Clock,
  CalendarDays,
  Infinity,
  FileText,
  CheckCircle2,
  AlertTriangle,
  Loader2,
  ArrowRight,
  ShieldCheck,
  History,
  X,
} from 'lucide-react'
import { apiPatch, ApiError } from '@/lib/api/client'
import { z } from 'zod'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from '@/components/ui/dialog'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type PlanTier = 'free' | 'pro' | 'enterprise'

type DurationOption = '7' | '30' | '90' | '365' | 'custom' | 'forever'

interface UserInfo {
  id: string
  email: string
  name: string
  plan: PlanTier
  subscriptionStatus: 'active' | 'past_due' | 'canceled' | 'trialing' | 'none'
  createdAt: string
}

interface PromotionRecord {
  id: string
  email: string
  userName: string
  plan: PlanTier
  days: number | null
  reason: string | null
  appliedBy: string
  appliedAt: string
}

// ---------------------------------------------------------------------------
// Schemas
// ---------------------------------------------------------------------------

const overridePlanResponseSchema = z.object({
  success: z.boolean(),
  message: z.string().optional(),
})

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const PLAN_LABELS: Record<PlanTier, string> = {
  free: 'Free',
  pro: 'Pro',
  enterprise: 'Enterprise',
}

const PLAN_ICONS: Record<PlanTier, React.ReactNode> = {
  free: <User className="w-4 h-4" />,
  pro: <Rocket className="w-4 h-4" />,
  enterprise: <Building2 className="w-4 h-4" />,
}

const STATUS_COLORS: Record<string, string> = {
  active: 'bg-green-500/15 text-green-400',
  trialing: 'bg-blue-500/15 text-blue-400',
  past_due: 'bg-yellow-500/15 text-yellow-400',
  canceled: 'bg-red-500/15 text-red-400',
  none: 'bg-[var(--bg-tertiary)] text-[var(--text-muted)]',
}

function formatAccountAge(isoDate: string): string {
  const created = new Date(isoDate)
  const now = new Date()
  const diffMs = now.getTime() - created.getTime()
  const days = Math.floor(diffMs / (1000 * 60 * 60 * 24))
  if (days < 1) return 'Today'
  if (days < 30) return `${days} day${days !== 1 ? 's' : ''}`
  const months = Math.floor(days / 30)
  if (months < 12) return `${months} month${months !== 1 ? 's' : ''}`
  const years = Math.floor(months / 12)
  const remainingMonths = months % 12
  return remainingMonths > 0
    ? `${years}y ${remainingMonths}m`
    : `${years} year${years !== 1 ? 's' : ''}`
}

function formatDurationLabel(key: DurationOption): string {
  switch (key) {
    case '7': return '7 days'
    case '30': return '30 days'
    case '90': return '90 days'
    case '365': return '1 year'
    case 'custom': return 'Custom'
    case 'forever': return 'Forever'
  }
}

function durationToDays(option: DurationOption, customDays: number): number | null {
  if (option === 'forever') return null
  if (option === 'custom') return customDays
  return Number(option)
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function PlanPromotionPanel() {
  // --- User lookup ---
  const [searchEmail, setSearchEmail] = useState('')
  const [user, setUser] = useState<UserInfo | null>(null)
  const [lookupLoading, setLookupLoading] = useState(false)
  const [lookupError, setLookupError] = useState<string | null>(null)
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // --- Plan override form ---
  const [selectedPlan, setSelectedPlan] = useState<PlanTier>('pro')
  const [durationOption, setDurationOption] = useState<DurationOption>('30')
  const [customDays, setCustomDays] = useState<number>(1)
  const [reason, setReason] = useState('')

  // --- Confirmation dialog ---
  const [confirmOpen, setConfirmOpen] = useState(false)

  // --- Submission state ---
  const [submitting, setSubmitting] = useState(false)
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null)

  // --- Recent promotions ---
  const [recentPromotions, setRecentPromotions] = useState<PromotionRecord[]>([])

  // ---------------------------------------------------------------------------
  // Debounced user lookup
  // ---------------------------------------------------------------------------
  const lookupUser = useCallback(async (email: string) => {
    if (!email || !email.includes('@')) {
      setUser(null)
      setLookupError(null)
      return
    }
    try {
      setLookupLoading(true)
      setLookupError(null)
      const res = await fetch(`/api/admin/users?search=${encodeURIComponent(email)}`)
      if (!res.ok) {
        const body = await res.json().catch(() => ({}))
        throw new Error(body.error ?? 'User not found')
      }
      const data = await res.json()
      const users: UserInfo[] = data.users ?? data.data ?? (Array.isArray(data) ? data : [])
      if (users.length === 0) {
        setUser(null)
        setLookupError('No user found with that email')
        return
      }
      setUser(users[0])
      setLookupError(null)
    } catch (err) {
      setUser(null)
      setLookupError(err instanceof Error ? err.message : 'Lookup failed')
    } finally {
      setLookupLoading(false)
    }
  }, [])

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      lookupUser(searchEmail.trim())
    }, 350)
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current)
    }
  }, [searchEmail, lookupUser])

  // ---------------------------------------------------------------------------
  // Submit handler
  // ---------------------------------------------------------------------------
  const handleSubmit = () => {
    setFeedback(null)
    setConfirmOpen(true)
  }

  const confirmAndApply = async () => {
    if (!user) return
    const days = durationToDays(durationOption, customDays)
    setSubmitting(true)
    setFeedback(null)
    try {
      await apiPatch(
        '/api/admin/users/override-plan',
        overridePlanResponseSchema,
        {
          email: user.email,
          plan: selectedPlan,
          days,
          ...(reason.trim() ? { reason: reason.trim() } : {}),
        },
      )
      // Add to recent promotions list (prepend)
      const record: PromotionRecord = {
        id: crypto.randomUUID(),
        email: user.email,
        userName: user.name,
        plan: selectedPlan,
        days,
        reason: reason.trim() || null,
        appliedBy: 'You',
        appliedAt: new Date().toISOString(),
      }
      setRecentPromotions((prev) => [record, ...prev].slice(0, 5))
      // Update displayed user plan
      setUser((prev) => (prev ? { ...prev, plan: selectedPlan } : prev))
      setFeedback({ type: 'success', message: `Plan updated to ${PLAN_LABELS[selectedPlan]}${days !== null ? ` for ${days} day${days !== 1 ? 's' : ''}` : ' forever'}` })
      setReason('')
    } catch (err) {
      const msg = err instanceof ApiError
        ? err.message
        : err instanceof Error
          ? err.message
          : 'Failed to update plan'
      setFeedback({ type: 'error', message: msg })
    } finally {
      setSubmitting(false)
      setConfirmOpen(false)
    }
  }

  // ---------------------------------------------------------------------------
  // Derived
  // ---------------------------------------------------------------------------
  const canSubmit =
    user !== null &&
    !submitting &&
    (durationOption !== 'custom' || customDays >= 1)

  const resolvedDays = durationToDays(durationOption, customDays)

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------
  return (
    <div className="card">
      {/* Header */}
      <div className="card-header">
        <div className="flex items-center gap-2">
          <Crown className="w-5 h-5 text-[var(--accent)]" />
          <h2 className="text-base font-semibold text-[var(--text-primary)]">
            Plan Promotion
          </h2>
        </div>
      </div>

      <div className="p-5 space-y-6">
        {/* ── User Lookup ──────────────────────────────────────────────── */}
        <section>
          <div className="block text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider mb-2">
            <Search className="w-3.5 h-3.5 inline mr-1 -mt-0.5" />
            User Lookup
          </div>
          <div className="relative">
            <Input
              type="email"
              placeholder="Search by email…"
              value={searchEmail}
              onChange={(e) => {
                setSearchEmail(e.target.value)
                setFeedback(null)
              }}
              className="pr-9"
            />
            {lookupLoading && (
              <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[var(--accent)] animate-spin" />
            )}
            {!lookupLoading && searchEmail && (
              <button
                onClick={() => {
                  setSearchEmail('')
                  setUser(null)
                  setLookupError(null)
                  setFeedback(null)
                }}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            )}
          </div>
          {lookupError && (
            <p className="mt-1.5 text-xs text-red-400 flex items-center gap-1">
              <AlertTriangle className="w-3 h-3" />
              {lookupError}
            </p>
          )}
        </section>

        {/* ── User Info Card ───────────────────────────────────────────── */}
        {user && (
          <section className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-tertiary)]/40 p-4 space-y-3">
            <div className="flex items-center gap-3">
              <div className="flex items-center justify-center w-9 h-9 rounded-full bg-[var(--accent)]/15 text-[var(--accent)]">
                {PLAN_ICONS[user.plan]}
              </div>
              <div className="min-w-0">
                <p className="text-sm font-medium text-[var(--text-primary)] truncate">
                  {user.name || user.email}
                </p>
                <p className="text-xs text-[var(--text-muted)] truncate">{user.email}</p>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-3">
              {/* Current Plan */}
              <div className="rounded-md bg-[var(--bg-tertiary)] p-2.5 text-center">
                <p className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider mb-0.5">
                  Current Plan
                </p>
                <p className="text-sm font-semibold text-[var(--text-primary)] capitalize flex items-center justify-center gap-1">
                  {PLAN_ICONS[user.plan]}
                  {PLAN_LABELS[user.plan]}
                </p>
              </div>

              {/* Subscription Status */}
              <div className="rounded-md bg-[var(--bg-tertiary)] p-2.5 text-center">
                <p className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider mb-0.5">
                  Status
                </p>
                <span
                  className={`inline-block text-xs px-2 py-0.5 rounded-full font-medium capitalize ${
                    STATUS_COLORS[user.subscriptionStatus] ?? STATUS_COLORS.none
                  }`}
                >
                  {user.subscriptionStatus.replace('_', ' ')}
                </span>
              </div>

              {/* Account Age */}
              <div className="rounded-md bg-[var(--bg-tertiary)] p-2.5 text-center">
                <p className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider mb-0.5">
                  Account Age
                </p>
                <p className="text-sm font-semibold text-[var(--text-primary)] flex items-center justify-center gap-1">
                  <CalendarDays className="w-3.5 h-3.5 text-[var(--text-muted)]" />
                  {formatAccountAge(user.createdAt)}
                </p>
              </div>
            </div>
          </section>
        )}

        {/* ── Plan Selection ───────────────────────────────────────────── */}
        {user && (
          <section>
            <div className="block text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider mb-2">
              <ShieldCheck className="w-3.5 h-3.5 inline mr-1 -mt-0.5" />
              New Plan
            </div>
            <RadioGroup
              value={selectedPlan}
              onValueChange={(v) => setSelectedPlan(v as PlanTier)}
              className="grid grid-cols-3 gap-3"
            >
              {(['free', 'pro', 'enterprise'] as PlanTier[]).map((plan) => (
                <label
                  key={plan}
                  aria-label={PLAN_LABELS[plan]}
                  className={`flex items-center gap-2.5 rounded-lg border p-3 cursor-pointer transition-colors ${
                    selectedPlan === plan
                      ? 'border-[var(--accent)] bg-[var(--accent)]/10'
                      : 'border-[var(--border-color)] bg-[var(--bg-tertiary)]/30 hover:border-[var(--accent)]/40'
                  }`}
                >
                  <RadioGroupItem value={plan} id={`plan-${plan}`} />
                  <div className="flex items-center gap-1.5">
                    <span className={`text-[var(--text-primary)] ${selectedPlan === plan ? 'text-[var(--accent)]' : ''}`}>
                      {PLAN_ICONS[plan]}
                    </span>
                    <span
                      className={`text-sm font-medium ${
                        selectedPlan === plan ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'
                      }`}
                    >
                      {PLAN_LABELS[plan]}
                    </span>
                  </div>
                </label>
              ))}
            </RadioGroup>
          </section>
        )}

        {/* ── Duration ─────────────────────────────────────────────────── */}
        {user && (
          <section>
            <div className="block text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider mb-2">
              <Clock className="w-3.5 h-3.5 inline mr-1 -mt-0.5" />
              Duration
            </div>
            <RadioGroup
              value={durationOption}
              onValueChange={(v) => setDurationOption(v as DurationOption)}
              className="grid grid-cols-3 sm:grid-cols-6 gap-2"
            >
              {(['7', '30', '90', '365', 'custom', 'forever'] as DurationOption[]).map((opt) => (
                <label
                  key={opt}
                  className={`flex items-center gap-2 rounded-lg border p-2.5 cursor-pointer transition-colors ${
                    durationOption === opt
                      ? 'border-[var(--accent)] bg-[var(--accent)]/10'
                      : 'border-[var(--border-color)] bg-[var(--bg-tertiary)]/30 hover:border-[var(--accent)]/40'
                  }`}
                >
                  <RadioGroupItem value={opt} id={`dur-${opt}`} />
                  <span
                    className={`text-xs font-medium flex items-center gap-1 ${
                      durationOption === opt ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'
                    }`}
                  >
                    {opt === 'forever' && <Infinity className="w-3.5 h-3.5" />}
                    {formatDurationLabel(opt)}
                  </span>
                </label>
              ))}
            </RadioGroup>

            {/* Custom days input */}
            {durationOption === 'custom' && (
              <div className="mt-2 flex items-center gap-2">
                <Input
                  type="number"
                  min={1}
                  max={3650}
                  value={customDays}
                  onChange={(e) => setCustomDays(Math.max(1, parseInt(e.target.value) || 1))}
                  className="w-28"
                  placeholder="Days"
                />
                <span className="text-xs text-[var(--text-muted)]">days</span>
              </div>
            )}
          </section>
        )}

        {/* ── Reason / Note ────────────────────────────────────────────── */}
        {user && (
          <section>
            <div className="block text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider mb-2">
              <FileText className="w-3.5 h-3.5 inline mr-1 -mt-0.5" />
              Reason / Note
              <span className="normal-case font-normal text-[var(--text-muted)] ml-1">(audit trail)</span>
            </div>
            <Textarea
              placeholder="e.g. Promotional upgrade for partner onboarding…"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              rows={2}
              className="text-sm"
            />
          </section>
        )}

        {/* ── Feedback ─────────────────────────────────────────────────── */}
        {feedback && (
          <div
            className={`flex items-start gap-2 rounded-lg border p-3 text-sm ${
              feedback.type === 'success'
                ? 'border-green-500/30 bg-green-500/10 text-green-400'
                : 'border-red-500/30 bg-red-500/10 text-red-400'
            }`}
          >
            {feedback.type === 'success' ? (
              <CheckCircle2 className="w-4 h-4 shrink-0 mt-0.5" />
            ) : (
              <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
            )}
            <p>{feedback.message}</p>
            <button
              onClick={() => setFeedback(null)}
              className="ml-auto shrink-0 opacity-60 hover:opacity-100 transition-opacity"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        )}

        {/* ── Submit ───────────────────────────────────────────────────── */}
        {user && (
          <button
            onClick={handleSubmit}
            disabled={!canSubmit}
            className="w-full flex items-center justify-center gap-2 rounded-lg bg-[var(--accent)] text-white font-medium text-sm py-2.5 transition-colors hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {submitting ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <ArrowRight className="w-4 h-4" />
            )}
            {submitting ? 'Applying…' : 'Apply Plan Override'}
          </button>
        )}

        {/* ── Recent Promotions ────────────────────────────────────────── */}
        {recentPromotions.length > 0 && (
          <section>
            <h3 className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider mb-2 flex items-center gap-1.5">
              <History className="w-3.5 h-3.5" />
              Recent Promotions
            </h3>
            <div className="overflow-x-auto rounded-lg border border-[var(--border-color)]">
              <table className="w-full text-xs">
                <thead>
                  <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/40">
                    <th className="text-left py-2 px-3 font-semibold text-[var(--text-muted)]">User</th>
                    <th className="text-left py-2 px-3 font-semibold text-[var(--text-muted)]">Plan</th>
                    <th className="text-left py-2 px-3 font-semibold text-[var(--text-muted)]">Duration</th>
                    <th className="text-left py-2 px-3 font-semibold text-[var(--text-muted)]">Reason</th>
                    <th className="text-left py-2 px-3 font-semibold text-[var(--text-muted)]">Applied</th>
                  </tr>
                </thead>
                <tbody>
                  {recentPromotions.map((rec) => (
                    <tr
                      key={rec.id}
                      className="border-b border-[var(--border-color)] last:border-b-0 hover:bg-[var(--bg-tertiary)]/20 transition-colors"
                    >
                      <td className="py-2 px-3">
                        <div className="font-medium text-[var(--text-primary)] truncate max-w-[140px]">
                          {rec.userName || rec.email}
                        </div>
                        <div className="text-[var(--text-muted)] truncate max-w-[140px]">{rec.email}</div>
                      </td>
                      <td className="py-2 px-3 capitalize">
                        <span className="inline-flex items-center gap-1 font-medium text-[var(--text-primary)]">
                          {PLAN_ICONS[rec.plan]}
                          {PLAN_LABELS[rec.plan]}
                        </span>
                      </td>
                      <td className="py-2 px-3 text-[var(--text-secondary)]">
                        {rec.days === null ? (
                          <span className="inline-flex items-center gap-1">
                            <Infinity className="w-3 h-3" />
                            Forever
                          </span>
                        ) : (
                          `${rec.days}d`
                        )}
                      </td>
                      <td className="py-2 px-3 text-[var(--text-muted)] max-w-[160px] truncate">
                        {rec.reason ?? '—'}
                      </td>
                      <td className="py-2 px-3 text-[var(--text-muted)] whitespace-nowrap">
                        {new Date(rec.appliedAt).toLocaleString()}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        )}
      </div>

      {/* ── Confirmation Dialog ────────────────────────────────────────── */}
      <Dialog open={confirmOpen} onOpenChange={setConfirmOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <ShieldCheck className="w-5 h-5 text-[var(--accent)]" />
              Confirm Plan Override
            </DialogTitle>
            <DialogDescription>
              This action will change the user&apos;s subscription plan. It will be recorded in the audit trail.
            </DialogDescription>
          </DialogHeader>

          {user && (
            <div className="space-y-3 py-2">
              {/* User summary */}
              <div className="rounded-lg bg-[var(--bg-tertiary)]/50 p-3 space-y-2 text-sm">
                <div className="flex justify-between">
                  <span className="text-[var(--text-muted)]">User</span>
                  <span className="font-medium text-[var(--text-primary)]">{user.name || user.email}</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-[var(--text-muted)]">Current Plan</span>
                  <span className="font-medium text-[var(--text-primary)] capitalize flex items-center gap-1">
                    {PLAN_ICONS[user.plan]}
                    {PLAN_LABELS[user.plan]}
                  </span>
                </div>
                <div className="flex items-center justify-center py-1">
                  <ArrowRight className="w-4 h-4 text-[var(--accent)]" />
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-[var(--text-muted)]">New Plan</span>
                  <span className="font-semibold text-[var(--accent)] capitalize flex items-center gap-1">
                    {PLAN_ICONS[selectedPlan]}
                    {PLAN_LABELS[selectedPlan]}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-[var(--text-muted)]">Duration</span>
                  <span className="font-medium text-[var(--text-primary)] flex items-center gap-1">
                    {resolvedDays === null ? (
                      <>
                        <Infinity className="w-3.5 h-3.5" />
                        Forever
                      </>
                    ) : (
                      `${resolvedDays} day${resolvedDays !== 1 ? 's' : ''}`
                    )}
                  </span>
                </div>
                {reason.trim() && (
                  <div className="flex justify-between">
                    <span className="text-[var(--text-muted)]">Reason</span>
                    <span className="font-medium text-[var(--text-primary)] max-w-[200px] truncate">
                      {reason.trim()}
                    </span>
                  </div>
                )}
              </div>
            </div>
          )}

          <DialogFooter>
            <DialogClose asChild>
              <button className="px-4 py-2 text-sm rounded-lg border border-[var(--border-color)] text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] transition-colors">
                Cancel
              </button>
            </DialogClose>
            <button
              onClick={confirmAndApply}
              disabled={submitting}
              className="px-4 py-2 text-sm rounded-lg bg-[var(--accent)] text-white font-medium hover:opacity-90 transition-colors disabled:opacity-50 flex items-center gap-2"
            >
              {submitting && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
              Confirm Override
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import {
  Database, Clock, HardDrive, Activity,
  Cpu, RefreshCw, ChevronDown, ChevronUp,
  AlertTriangle,
} from 'lucide-react'
import {
  UptimeChart,
  ResponseTimeChart,
  ErrorRateChart,
  Sparkline,
} from '@/components/admin/charts/AdminCharts'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface HealthData {
  current: {
    database: {
      status: string
      latencyMs: number
      connections: number
      connectionsMax: number
    }
    uptime: number
    uptimePercent: number
    memory: {
      heapUsedMb: number
      heapTotalMb: number
      rssMb: number
      externalMb: number
    }
    responseTimeMs: number
  }
  trends: {
    responseTime: {
      timestamp: string
      p50: number
      p95: number
      p99: number
    }[]
    uptime7d: { date: string; uptime: number }[]
    uptime30d: { date: string; uptime: number }[]
    errorRate: { timestamp: string; rate: number; count: number }[]
  }
  recentErrors: { message: string; timestamp: string; endpoint: string }[]
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatUptime(seconds: number): string {
  const days = Math.floor(seconds / 86400)
  const hrs = Math.floor((seconds % 86400) / 3600)
  const mins = Math.floor((seconds % 3600) / 60)
  if (days > 0) return `${days}d ${hrs}h`
  if (hrs > 0) return `${hrs}h ${mins}m`
  return `${mins}m`
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function SystemHealthPanel() {
  const [data, setData] = useState<HealthData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [expanded, setExpanded] = useState(false)
  const [uptimeRange, setUptimeRange] = useState<'7d' | '30d'>('7d')

  const fetchHealth = async () => {
    try {
      setLoading(true)
      setError(null)
      const res = await fetch('/api/admin/health')
      if (!res.ok) throw new Error('Failed to fetch health data')
      const json = await res.json()
      setData(json.data ?? json)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load health data')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchHealth()
    const interval = setInterval(fetchHealth, 60000) // refresh every 60s
    return () => clearInterval(interval)
  }, [])

  if (loading && !data) {
    return (
      <div className="card">
        <div className="card-header">
          <div className="flex items-center gap-2">
            <Cpu className="w-5 h-5 text-[var(--accent)]" />
            <h2 className="text-base font-semibold text-[var(--text-primary)]">
              System Health
            </h2>
          </div>
        </div>
        <div className="p-5 flex items-center justify-center min-h-[120px]">
          <RefreshCw className="w-5 h-5 text-[var(--accent)] animate-spin" />
        </div>
      </div>
    )
  }

  if (error && !data) {
    return (
      <div className="card">
        <div className="card-header">
          <div className="flex items-center gap-2">
            <Cpu className="w-5 h-5 text-[var(--accent)]" />
            <h2 className="text-base font-semibold text-[var(--text-primary)]">
              System Health
            </h2>
          </div>
        </div>
        <div className="p-5 text-center">
          <AlertTriangle className="w-8 h-8 text-red-400 mx-auto mb-2" />
          <p className="text-sm text-red-400">{error}</p>
          <button
            onClick={fetchHealth}
            className="mt-3 text-xs text-[var(--accent)] hover:underline"
          >
            Retry
          </button>
        </div>
      </div>
    )
  }

  if (!data) return null

  const d = data.current
  const uptimeTrends = uptimeRange === '7d' ? data.trends.uptime7d : data.trends.uptime30d

  return (
    <div className="card" id="system">
      <div className="card-header">
        <div className="flex items-center justify-between w-full">
          <div className="flex items-center gap-2">
            <Cpu className="w-5 h-5 text-[var(--accent)]" />
            <h2 className="text-base font-semibold text-[var(--text-primary)]">
              System Health
            </h2>
            <span
              className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                d.database.status === 'healthy'
                  ? 'bg-green-500/15 text-green-400'
                  : 'bg-red-500/15 text-red-400'
              }`}
            >
              {d.database.status === 'healthy' ? 'Operational' : 'Degraded'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={fetchHealth}
              className="p-1.5 rounded-md hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
              title="Refresh"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
            </button>
            <button
              onClick={() => setExpanded(!expanded)}
              className="p-1.5 rounded-md hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors lg:hidden"
            >
              {expanded ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
            </button>
          </div>
        </div>
      </div>

      <div className="p-5 space-y-4">
        {/* Quick Status Row */}
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
          {/* Database */}
          <div className="flex items-center gap-3 p-2.5 rounded-lg bg-[var(--bg-tertiary)]/50">
            <div
              className={`w-2.5 h-2.5 rounded-full shrink-0 ${
                d.database.status === 'healthy' ? 'bg-green-400' : 'bg-red-400'
              }`}
            />
            <div className="min-w-0">
              <p className="text-xs text-[var(--text-muted)]">Database</p>
              <p className="text-sm font-medium text-[var(--text-primary)]">
                {d.database.latencyMs}ms
                {d.database.connections > 0 && (
                  <span className="text-[var(--text-muted)] text-xs ml-1">
                    ({d.database.connections}/{d.database.connectionsMax})
                  </span>
                )}
              </p>
            </div>
          </div>

          {/* Uptime */}
          <div className="flex items-center gap-3 p-2.5 rounded-lg bg-[var(--bg-tertiary)]/50">
            <div className="w-2.5 h-2.5 rounded-full shrink-0 bg-green-400" />
            <div className="min-w-0">
              <p className="text-xs text-[var(--text-muted)]">Uptime</p>
              <p className="text-sm font-medium text-[var(--text-primary)]">
                {d.uptimePercent}%
                <span className="text-[var(--text-muted)] text-xs ml-1">
                  ({formatUptime(d.uptime)})
                </span>
              </p>
            </div>
          </div>

          {/* Memory */}
          <div className="flex items-center gap-3 p-2.5 rounded-lg bg-[var(--bg-tertiary)]/50">
            <div className="w-2.5 h-2.5 rounded-full shrink-0 bg-yellow-400" />
            <div className="min-w-0">
              <p className="text-xs text-[var(--text-muted)]">Memory</p>
              <p className="text-sm font-medium text-[var(--text-primary)]">
                {d.memory.heapUsedMb}MB / {d.memory.heapTotalMb}MB
              </p>
            </div>
          </div>

          {/* API Response */}
          <div className="flex items-center gap-3 p-2.5 rounded-lg bg-[var(--bg-tertiary)]/50">
            <div className="w-2.5 h-2.5 rounded-full shrink-0 bg-blue-400" />
            <div className="min-w-0">
              <p className="text-xs text-[var(--text-muted)]">API Response</p>
              <p className="text-sm font-medium text-[var(--text-primary)]">
                {d.responseTimeMs}ms
              </p>
            </div>
          </div>
        </div>

        {/* Expandable Charts — always visible on lg, toggle on mobile */}
        <div className={`${expanded ? 'block' : 'hidden lg:block'} space-y-4`}>
          {/* Uptime Graph with range toggle */}
          <div className="rounded-lg border border-[var(--border-color)] p-3">
            <div className="flex items-center justify-between mb-2">
              <h3 className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">
                Uptime Percentage
              </h3>
              <div className="flex gap-1">
                <button
                  onClick={() => setUptimeRange('7d')}
                  className={`px-2 py-0.5 rounded text-xs font-medium transition-colors ${
                    uptimeRange === '7d'
                      ? 'bg-[var(--accent)]/15 text-[var(--accent)]'
                      : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
                  }`}
                >
                  7d
                </button>
                <button
                  onClick={() => setUptimeRange('30d')}
                  className={`px-2 py-0.5 rounded text-xs font-medium transition-colors ${
                    uptimeRange === '30d'
                      ? 'bg-[var(--accent)]/15 text-[var(--accent)]'
                      : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
                  }`}
                >
                  30d
                </button>
              </div>
            </div>
            <UptimeChart data={uptimeTrends} />
          </div>

          {/* Response Time P95/P99 */}
          <div className="rounded-lg border border-[var(--border-color)] p-3">
            <h3 className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider mb-2">
              Response Time (p50 / p95 / p99)
            </h3>
            <ResponseTimeChart data={data.trends.responseTime} />
          </div>

          {/* Error Rate */}
          <div className="rounded-lg border border-[var(--border-color)] p-3">
            <h3 className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider mb-2">
              Error Rate
            </h3>
            <ErrorRateChart data={data.trends.errorRate} />
          </div>

          {/* Recent Errors */}
          {data.recentErrors.length > 0 && (
            <div className="rounded-lg border border-red-500/20 bg-red-500/5 p-3">
              <h3 className="text-xs font-semibold text-red-400 uppercase tracking-wider mb-2">
                Recent Errors ({data.recentErrors.length})
              </h3>
              <div className="space-y-1.5 max-h-32 overflow-y-auto">
                {data.recentErrors.map((err, i) => (
                  <div key={`${err}-${i}`} className="flex items-start gap-2 text-xs">
                    <AlertTriangle className="w-3 h-3 text-red-400 shrink-0 mt-0.5" />
                    <div className="min-w-0">
                      <p className="text-red-300 truncate">{err.message}</p>
                      <p className="text-[var(--text-muted)]">
                        {err.endpoint} &middot; {new Date(err.timestamp).toLocaleString()}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import {
  LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip, ResponsiveContainer, Area, AreaChart,
} from 'recharts'
import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from '@/components/ui/chart'

// ---------------------------------------------------------------------------
// Revenue Line Chart
// ---------------------------------------------------------------------------

interface RevenueData {
  month: string
  total: number
}

const revenueChartConfig: ChartConfig = {
  total: {
    label: 'Revenue (KES)',
    color: 'hsl(var(--accent))',
  },
}

export function RevenueLineChart({ data }: { data: RevenueData[] }) {
  const sorted = [...data].sort((a, b) => a.month.localeCompare(b.month))

  return (
    <ChartContainer config={revenueChartConfig} className="min-h-[240px] w-full">
      <AreaChart data={sorted} margin={{ top: 8, right: 8, bottom: 0, left: 0 }}>
        <defs>
          <linearGradient id="revenueGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="hsl(var(--accent))" stopOpacity={0.3} />
            <stop offset="95%" stopColor="hsl(var(--accent))" stopOpacity={0} />
          </linearGradient>
        </defs>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" opacity={0.3} />
        <XAxis
          dataKey="month"
          tick={{ fontSize: 11, fill: 'var(--text-muted)' }}
          tickFormatter={(v: string) => {
            const parts = v.split('-')
            const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
            return parts[1] ? months[+parts[1] - 1] : v
          }}
        />
        <YAxis
          tick={{ fontSize: 11, fill: 'var(--text-muted)' }}
          tickFormatter={(v: number) => v >= 1000 ? `${(v / 1000).toFixed(0)}K` : String(v)}
        />
        <ChartTooltip content={<ChartTooltipContent />} />
        <Area
          type="monotone"
          dataKey="total"
          stroke="hsl(var(--accent))"
          strokeWidth={2}
          fill="url(#revenueGrad)"
          dot={false}
          activeDot={{ r: 4, strokeWidth: 0 }}
        />
      </AreaChart>
    </ChartContainer>
  )
}

// ---------------------------------------------------------------------------
// Uptime Percentage Chart
// ---------------------------------------------------------------------------

interface UptimeData {
  date: string
  uptime: number
}

const uptimeChartConfig: ChartConfig = {
  uptime: {
    label: 'Uptime %',
    color: '#4ade80',
  },
}

export function UptimeChart({ data }: { data: UptimeData[] }) {
  return (
    <ChartContainer config={uptimeChartConfig} className="min-h-[160px] w-full">
      <AreaChart data={data} margin={{ top: 4, right: 4, bottom: 0, left: 0 }}>
        <defs>
          <linearGradient id="uptimeGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="#4ade80" stopOpacity={0.3} />
            <stop offset="95%" stopColor="#4ade80" stopOpacity={0} />
          </linearGradient>
        </defs>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" opacity={0.2} />
        <XAxis
          dataKey="date"
          tick={{ fontSize: 10, fill: 'var(--text-muted)' }}
          tickFormatter={(v: string) => v.split('-').slice(1).join('/')}
        />
        <YAxis
          domain={[99, 100]}
          tick={{ fontSize: 10, fill: 'var(--text-muted)' }}
          tickFormatter={(v: number) => `${v}%`}
        />
        <ChartTooltip content={<ChartTooltipContent />} />
        <Area
          type="monotone"
          dataKey="uptime"
          stroke="#4ade80"
          strokeWidth={2}
          fill="url(#uptimeGrad)"
          dot={false}
        />
      </AreaChart>
    </ChartContainer>
  )
}

// ---------------------------------------------------------------------------
// Response Time P95/P99 Chart
// ---------------------------------------------------------------------------

interface ResponseTimeData {
  timestamp: string
  p50: number
  p95: number
  p99: number
}

const responseTimeChartConfig: ChartConfig = {
  p50: { label: 'p50', color: '#60a5fa' },
  p95: { label: 'p95', color: '#f59e0b' },
  p99: { label: 'p99', color: '#ef4444' },
}

export function ResponseTimeChart({ data }: { data: ResponseTimeData[] }) {
  return (
    <ChartContainer config={responseTimeChartConfig} className="min-h-[180px] w-full">
      <LineChart data={data} margin={{ top: 4, right: 4, bottom: 0, left: 0 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" opacity={0.2} />
        <XAxis
          dataKey="timestamp"
          tick={{ fontSize: 10, fill: 'var(--text-muted)' }}
          tickFormatter={(v: string) => {
            const d = new Date(v)
            return `${d.getHours()}:00`
          }}
          interval={3}
        />
        <YAxis
          tick={{ fontSize: 10, fill: 'var(--text-muted)' }}
          tickFormatter={(v: number) => `${v}ms`}
        />
        <ChartTooltip content={<ChartTooltipContent />} />
        <Line type="monotone" dataKey="p50" stroke="#60a5fa" strokeWidth={1.5} dot={false} />
        <Line type="monotone" dataKey="p95" stroke="#f59e0b" strokeWidth={1.5} dot={false} />
        <Line type="monotone" dataKey="p99" stroke="#ef4444" strokeWidth={1.5} dot={false} />
      </LineChart>
    </ChartContainer>
  )
}

// ---------------------------------------------------------------------------
// Error Rate Chart
// ---------------------------------------------------------------------------

interface ErrorRateData {
  timestamp: string
  rate: number
  count: number
}

const errorRateChartConfig: ChartConfig = {
  rate: { label: 'Error Rate %', color: '#ef4444' },
  count: { label: 'Error Count', color: '#f97316' },
}

export function ErrorRateChart({ data }: { data: ErrorRateData[] }) {
  return (
    <ChartContainer config={errorRateChartConfig} className="min-h-[160px] w-full">
      <AreaChart data={data} margin={{ top: 4, right: 4, bottom: 0, left: 0 }}>
        <defs>
          <linearGradient id="errorGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="#ef4444" stopOpacity={0.3} />
            <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
          </linearGradient>
        </defs>
        <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color)" opacity={0.2} />
        <XAxis
          dataKey="timestamp"
          tick={{ fontSize: 10, fill: 'var(--text-muted)' }}
          tickFormatter={(v: string) => {
            const d = new Date(v)
            return `${d.getHours()}:00`
          }}
          interval={3}
        />
        <YAxis
          tick={{ fontSize: 10, fill: 'var(--text-muted)' }}
          tickFormatter={(v: number) => `${v}%`}
        />
        <ChartTooltip content={<ChartTooltipContent />} />
        <Area
          type="monotone"
          dataKey="rate"
          stroke="#ef4444"
          strokeWidth={1.5}
          fill="url(#errorGrad)"
          dot={false}
        />
      </AreaChart>
    </ChartContainer>
  )
}

// ---------------------------------------------------------------------------
// Subscription Donut Chart
// ---------------------------------------------------------------------------

import { PieChart, Pie, Cell } from 'recharts'

interface SubData {
  name: string
  value: number
}

const SUB_COLORS = ['#94a3b8', '#60a5fa', '#a855f7'] // free, pro, enterprise

const subChartConfig: ChartConfig = {
  free: { label: 'Free', color: '#94a3b8' },
  pro: { label: 'Pro', color: '#60a5fa' },
  enterprise: { label: 'Enterprise', color: '#a855f7' },
}

export function SubscriptionDonutChart({ data }: { data: SubData[] }) {
  const total = data.reduce((sum, d) => sum + d.value, 0)

  return (
    <div className="flex items-center gap-4">
      <ChartContainer config={subChartConfig} className="min-h-[160px] w-[160px]">
        <PieChart>
          <Pie
            data={data}
            cx="50%"
            cy="50%"
            innerRadius={40}
            outerRadius={65}
            paddingAngle={2}
            dataKey="value"
            stroke="none"
          >
            {data.map((_, index) => (
              <Cell key={`cell-${index}`} fill={SUB_COLORS[index % SUB_COLORS.length]} />
            ))}
          </Pie>
          <ChartTooltip content={<ChartTooltipContent />} />
        </PieChart>
      </ChartContainer>
      <div className="space-y-2 text-sm">
        {data.map((d, i) => (
          <div key={d.name} className="flex items-center gap-2">
            <div
              className="w-3 h-3 rounded-sm shrink-0"
              style={{ backgroundColor: SUB_COLORS[i % SUB_COLORS.length] }}
            />
            <span className="text-[var(--text-secondary)] capitalize">{d.name}</span>
            <span className="text-[var(--text-primary)] font-medium ml-auto">
              {d.value}
              <span className="text-[var(--text-muted)] text-xs ml-1">
                ({total > 0 ? Math.round((d.value / total) * 100) : 0}%)
              </span>
            </span>
          </div>
        ))}
        <div className="border-t border-[var(--border-color)] pt-1 mt-1 flex items-center gap-2">
          <span className="text-[var(--text-muted)]">Total</span>
          <span className="text-[var(--text-primary)] font-medium ml-auto">{total}</span>
        </div>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Sparkline (for trend indicators in stat cards)
// ---------------------------------------------------------------------------

interface SparklineProps {
  data: number[]
  color?: string
  width?: number
  height?: number
}

export function Sparkline({ data, color = 'hsl(var(--accent))', width = 80, height = 28 }: SparklineProps) {
  if (!data.length) return null

  const min = Math.min(...data)
  const max = Math.max(...data)
  const range = max - min || 1

  const points = data.map((v, i) => {
    const x = (i / (data.length - 1)) * width
    const y = height - ((v - min) / range) * (height - 4) - 2
    return `${x},${y}`
  }).join(' ')

  return (
    <svg width={width} height={height} className="inline-block">
      <polyline
        points={points}
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

'use client'

import { useState, useRef, useEffect, useCallback } from 'react'
import { smartChat } from '@/lib/ai/smartAiService'
import { localLlmService } from '@/lib/ai/localLlmService'
import type { InitProgressReport } from '@mlc-ai/web-llm'
import { MessageSquare, Send, Bot, User, Wifi, WifiOff, Loader2, Sparkles, X, Cpu, AlertTriangle } from 'lucide-react'

interface Message {
  role: 'user' | 'assistant'
  content: string
}

const SUGGESTIONS = [
  'What are the traverse misclosure limits for a rural cadastral survey?',
  'What must a survey plan include for submission to the Director?',
  'Explain the mutation form process for RIM amendment.',
  'What equipment checks are required under Regulation 25?',
  'How do I prepare a digital submission per SRVY2025-1?',
  'What are the angular misclosure rules for Class A traverses?',
]

export default function SurveyAssistant() {
  const [messages, setMessages] = useState<Message[]>([
    {
      role: 'assistant',
      content: `👋 Welcome to METARDU Survey Assistant. I'm powered by the offline WebGPU LLM (Phi-3-mini) with full Survey Act Cap 299, Survey Regulations LN 168/1994, and SRVY2025-1 Submission Standards knowledge.

Ask me anything about Kenyan cadastral surveying, or try one of the suggestions below.`,
    },
  ])
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const [modelStatus, setModelStatus] = useState<'idle' | 'loading' | 'ready' | 'error'>('idle')
  const [loadProgress, setLoadProgress] = useState(0)
  const [isOnline, setIsOnline] = useState(true)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLTextAreaElement>(null)

  useEffect(() => {
    setIsOnline(navigator.onLine)
    const handler = () => setIsOnline(navigator.onLine)
    window.addEventListener('online', handler)
    window.addEventListener('offline', handler)
    return () => {
      window.removeEventListener('online', handler)
      window.removeEventListener('offline', handler)
    }
  }, [])

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const warmUpModel = useCallback(async () => {
    if (modelStatus === 'ready' || modelStatus === 'loading') return
    setModelStatus('loading')
    try {
      await localLlmService.initialize(undefined, (report: InitProgressReport) => {
        setLoadProgress(Math.round(report.progress * 100))
      })
      setModelStatus('ready')
    } catch {
      setModelStatus('error')
    }
  }, [modelStatus])

  useEffect(() => {
    warmUpModel()
  }, [warmUpModel])

  const handleSend = useCallback(async () => {
    const text = input.trim()
    if (!text || loading) return
    setInput('')
    setLoading(true)

    const userMsg: Message = { role: 'user', content: text }
    setMessages((prev) => [...prev, userMsg])

    const assistantMsg: Message = { role: 'assistant', content: '' }
    setMessages((prev) => [...prev, assistantMsg])

    let accumulated = ''
    try {
      await smartChat({
        messages: [
          {
            role: 'system',
            content: `You are METARDU Survey Assistant, an expert cadastral survey AI trained on the full Survey Act Cap 299, Survey Regulations LN 168/1994, SRVY2025-1 Submission Standards, and Kenyan cadastral practice. Answer precisely and cite regulation numbers where possible. Keep answers concise but complete. If asked about something outside surveying, politely redirect.`,
          },
          { role: 'user', content: text },
        ],
        onToken: (token) => {
          accumulated += token
          setMessages((prev) => {
            const updated = [...prev]
            updated[updated.length - 1] = { role: 'assistant', content: accumulated }
            return updated
          })
        },
      })
    } catch (err) {
