            className="shrink-0 w-9 h-9 rounded-lg bg-[var(--accent)] text-black flex items-center justify-center hover:bg-[var(--accent-dim)] transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>
        <p className="mt-1.5 text-[10px] text-[var(--text-muted)] flex items-center gap-1">
          <AlertTriangle className="w-3 h-3" />
          AI-generated — always verify against official regulations. The Director of Surveys is the final authority.
        </p>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect, useCallback } from 'react'

export function AppUpdateBanner() {
  const [waitingWorker, setWaitingWorker] = useState<ServiceWorker | null>(null)
  const [showBanner, setShowBanner] = useState(false)

  useEffect(() => {
    if (typeof window === 'undefined' || !('serviceWorker' in navigator)) return

    // Register SW update detection on mount so the banner actually fires
    registerServiceWorkerUpdateDetector()

    const handler = (event: Event) => {
      setWaitingWorker((event as ServiceWorkerEvent).detail)
      setShowBanner(true)
    }

    window.addEventListener('sw-update-available', handler)
    return () => window.removeEventListener('sw-update-available', handler)
  }, [])

  const updateApp = useCallback(() => {
    if (!waitingWorker) return
    waitingWorker.postMessage({ type: 'SKIP_WAITING' })

    // Wait for the new service worker to take control
    waitingWorker.addEventListener('controllerchange', () => {
      window.location.reload()
    })

    // Fallback: reload after 2 seconds regardless
    setTimeout(() => window.location.reload(), 2000)
  }, [waitingWorker])

  if (!showBanner) return null

  return (
    <div className="fixed top-0 left-0 right-0 z-[210] bg-[var(--accent)] text-black text-center text-sm font-semibold py-2.5 px-4 flex items-center justify-center gap-3">
      <svg
        className="w-4 h-4 flex-shrink-0"
        fill="none"
        stroke="currentColor"
        viewBox="0 0 24 24"
        strokeWidth={2}
        aria-hidden="true"
      >
        <path
          strokeLinecap="round"
          strokeLinejoin="round"
          d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0l3.181 3.183a8.25 8.25 0 0013.803-3.7M4.031 9.865a8.25 8.25 0 0113.803-3.7l3.181 3.182m0-4.991v4.99"
        />
      </svg>
      <span>A new version of METARDU is available</span>
      <button
        onClick={updateApp}
        className="bg-black text-[var(--accent)] px-3 py-1 rounded font-bold text-xs hover:bg-gray-900 transition-colors"
      >
        Update Now
      </button>
      <button
        onClick={() => setShowBanner(false)}
        className="ml-1 hover:bg-black/10 rounded p-0.5 transition-colors"
        aria-label="Dismiss update banner"
      >
        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2.5}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
        </svg>
      </button>
    </div>
  )
}

/** Custom event for service worker updates */
interface ServiceWorkerEvent extends Event {
  detail: ServiceWorker
}

// Register SW update detection — call this once from layout or a provider
let swDetectorRegistered = false

export function registerServiceWorkerUpdateDetector() {
  if (typeof window === 'undefined' || !('serviceWorker' in navigator)) return
  if (swDetectorRegistered) return
  swDetectorRegistered = true

  navigator.serviceWorker?.getRegistration().then((registration) => {
    if (!registration) return

    let stateChangeHandler: (() => void) | null = null

    const updatefoundHandler = () => {
      const newWorker = registration.installing
      if (!newWorker) return

      stateChangeHandler = () => {
        if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
          window.dispatchEvent(
            new CustomEvent('sw-update-available', {
              detail: newWorker,
            }) as ServiceWorkerEvent
          )
        }
      }
      newWorker.addEventListener('statechange', stateChangeHandler)
    }

    registration.addEventListener('updatefound', updatefoundHandler)

    // Store cleanup for potential module teardown
    ;(registerServiceWorkerUpdateDetector as any)._cleanup = () => {
      if (stateChangeHandler && registration.installing) {
        registration.installing.removeEventListener('statechange', stateChangeHandler)
      }
      registration.removeEventListener('updatefound', updatefoundHandler)
      swDetectorRegistered = false
    }
  })
}

/** Clean up SW update detection listeners (call on app teardown if needed) */
export function unregisterServiceWorkerUpdateDetector() {
  const cleanup = (registerServiceWorkerUpdateDetector as any)._cleanup
  if (typeof cleanup === 'function') cleanup()
}

'use client';

/**
 * PWAInstallBanner
 * ────────────────────────────────────────────────────────────────────────────
 * A dismissible install banner that:
 *   • Listens for the browser's `beforeinstallprompt` event (Android Chrome,
 *     Edge desktop, etc.) and reveals an "Install app" CTA.
 *   • Falls back to manual iOS instructions for iOS Safari (which doesn't
 *     fire `beforeinstallprompt` — Apple requires users to use Share →
 *     Add to Home Screen manually).
 *   • Remembers dismissal for 14 days via localStorage so we don't nag.
 *   • Auto-hides once the app is running in standalone mode (already
 *     installed).
 *
 * Render this once near the top of AppShell.
 */

import { useEffect, useState } from 'react'
import { Download, X, Share, PlusSquare } from 'lucide-react'
import { useLanguage } from '@/lib/i18n/LanguageContext'

const DISMISS_KEY = 'metardu_pwa_install_dismissed_at'
const DISMISS_TTL_MS = 14 * 24 * 60 * 60 * 1000 // 14 days

type Platform = 'android-chrome' | 'ios-safari' | 'desktop-chrome' | 'unsupported'

function detectPlatform(): Platform {
  if (typeof window === 'undefined') return 'unsupported'
  const ua = navigator.userAgent.toLowerCase()
  const isIOS = /iphone|ipad|ipod/.test(ua)
  const isSafari = /^((?!chrome|android|crios|fxios).)*safari/.test(ua)
  if (isIOS && isSafari) return 'ios-safari'
  const isAndroid = /android/.test(ua)
  if (isAndroid && /chrome|edge/.test(ua)) return 'android-chrome'
  if (/chrome|edge/.test(ua) && !isAndroid) return 'desktop-chrome'
  return 'unsupported'
}

function isStandalone(): boolean {
  if (typeof window === 'undefined') return false
  // iOS Safari
  if ((navigator as any).standalone === true) return true
  // Android Chrome / Edge
  if (window.matchMedia('(display-mode: standalone)').matches) return true
  return false
}

function wasRecentlyDismissed(): boolean {
  try {
    const ts = Number(localStorage.getItem(DISMISS_KEY) || 0)
    if (!ts) return false
    return Date.now() - ts < DISMISS_TTL_MS
  } catch {
    return false
  }
}

function markDismissed() {
  try {
    localStorage.setItem(DISMISS_KEY, String(Date.now()))
  } catch {
    /* ignore quota errors */
  }
}

interface BeforeInstallPromptEvent extends Event {
  prompt: () => Promise<{ outcome: 'accepted' | 'dismissed' }>
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>
}

export function PWAInstallBanner() {
  const { t } = useLanguage()
  const [visible, setVisible] = useState(false)
  const [platform, setPlatform] = useState<Platform>('unsupported')
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null)
  const [showIosSheet, setShowIosSheet] = useState(false)

  useEffect(() => {
    if (isStandalone() || wasRecentlyDismissed()) return
    setPlatform(detectPlatform())

    const handler = (e: Event) => {
      e.preventDefault()
      setDeferredPrompt(e as BeforeInstallPromptEvent)
      setVisible(true)
    }
    window.addEventListener('beforeinstallprompt', handler)
    return () => window.removeEventListener('beforeinstallprompt', handler)
  }, [])

  // iOS Safari never fires beforeinstallprompt — show banner after a short delay
  // so the user has time to engage with the page first.
  useEffect(() => {
    if (platform !== 'ios-safari' || isStandalone() || wasRecentlyDismissed()) return
    const t = setTimeout(() => setVisible(true), 4000)
    return () => clearTimeout(t)
  }, [platform])

  const dismiss = () => {
    setVisible(false)
    setShowIosSheet(false)
    markDismissed()
  }

  const handleInstallClick = async () => {
    if (platform === 'ios-safari') {
      setShowIosSheet(true)
      return
    }
    if (!deferredPrompt) return
    await deferredPrompt.prompt()
    const choice = await deferredPrompt.userChoice
    if (choice.outcome === 'accepted') {
      setVisible(false)
    } else {
      // User dismissed the native prompt — don't show our banner again for a while.
      dismiss()
    }
    setDeferredPrompt(null)
  }

  if (!visible) return null

  return (
    <>
      {/* ─── Banner ─── */}
      <div
        role="dialog"
        aria-label={t('pwa.installTitle')}
        className="fixed left-1/2 -translate-x-1/2 bottom-4 sm:bottom-6 z-[60] w-[calc(100%-1.5rem)] max-w-md animate-[slideUp_0.3s_ease-out]"
      >
        <div className="relative bg-[var(--bg-card)] border border-[var(--accent)]/30 rounded-2xl shadow-2xl shadow-[var(--accent)]/10 overflow-hidden">
          {/* Top accent stripe */}
          <div className="h-1 w-full bg-gradient-to-r from-[var(--accent)] via-amber-400 to-orange-300" />

          <div className="p-4 flex items-start gap-3">
            {/* App icon */}
            <div className="grid place-items-center w-12 h-12 rounded-xl bg-gradient-to-br from-[var(--accent)] to-[var(--accent-dim)] text-black shrink-0 shadow-lg shadow-[var(--accent)]/20">
              <Download className="w-6 h-6" strokeWidth={2.5} />
            </div>

            <div className="flex-1 min-w-0">
              <h3 className="text-sm font-semibold text-[var(--text-primary)] mb-0.5">
                {t('pwa.installTitle')}
              </h3>
              <p className="text-xs text-[var(--text-muted)] leading-relaxed">
                {platform === 'ios-safari'
                  ? t('pwa.installDescriptionIOS')
                  : t('pwa.installDescription')}
              </p>

              <div className="mt-3 flex items-center gap-2">
                <button
                  onClick={handleInstallClick}
                  className="px-3 py-1.5 rounded-lg bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black text-xs font-semibold transition-colors active:scale-95"
                >
                  {platform === 'ios-safari' ? t('pwa.showMeHow') : t('pwa.installNow')}
                </button>
                <button
                  onClick={dismiss}
                  className="px-3 py-1.5 rounded-lg text-[var(--text-muted)] hover:text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] text-xs font-medium transition-colors"
                >
                  {t('pwa.notNow')}
                </button>
              </div>
            </div>

            <button
              onClick={dismiss}
              aria-label="Close install banner"
              className="p-1.5 rounded-lg text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* ─── iOS instructions sheet ─── */}
      {showIosSheet && (
        <div
          className="fixed inset-0 bg-black/70 backdrop-blur-sm z-[70] flex items-end sm:items-center justify-center"
          style={{ animation: 'fadeIn 0.2s ease-out' }}
          onClick={() => setShowIosSheet(false)}
        >
          <div
            className="bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-t-2xl sm:rounded-2xl w-full max-w-sm p-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-base font-semibold text-[var(--text-primary)]">
                {t('pwa.addToHomeScreen')}
              </h3>
              <button
                onClick={() => setShowIosSheet(false)}
                className="p-1.5 rounded-lg hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)]"
                aria-label="Close"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <ol className="space-y-3">
              <li className="flex items-start gap-3">
                <span className="grid place-items-center w-6 h-6 rounded-full bg-[var(--accent)]/15 text-[var(--accent)] text-xs font-bold shrink-0 mt-0.5">1</span>
                <div>
                  <p className="text-sm text-[var(--text-primary)]">{t('pwa.safariStep1')}</p>
                  <Share className="w-4 h-4 text-[var(--accent)] mt-1" />
                </div>
              </li>
              <li className="flex items-start gap-3">
                <span className="grid place-items-center w-6 h-6 rounded-full bg-[var(--accent)]/15 text-[var(--accent)] text-xs font-bold shrink-0 mt-0.5">2</span>
                <div>
                  <p className="text-sm text-[var(--text-primary)]">{t('pwa.safariStep2')}</p>
                  <PlusSquare className="w-4 h-4 text-[var(--accent)] mt-1" />
                </div>
              </li>
              <li className="flex items-start gap-3">
                <span className="grid place-items-center w-6 h-6 rounded-full bg-[var(--accent)]/15 text-[var(--accent)] text-xs font-bold shrink-0 mt-0.5">3</span>
                <p className="text-sm text-[var(--text-primary)]">{t('pwa.safariStep3')}</p>
              </li>
            </ol>

            <button
              onClick={() => {
                setShowIosSheet(false)
                dismiss()
              }}
              className="w-full mt-5 py-3 rounded-xl bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black font-semibold text-sm transition-colors active:scale-95"
            >
              {t('pwa.gotIt')}
            </button>
          </div>
        </div>
      )}
    </>
  )
}

'use client';

import { useCallback, useState } from 'react'
import ReactFlow, { 
  addEdge, 
  Background, 
  Controls, 
  useNodesState, 
  useEdgesState,
  Connection,
  Node,
  Edge
} from 'reactflow'
import 'reactflow/dist/style.css'

const nodeTypes = [
  { type: 'fieldbook', label: 'Fieldbook', color: '#3b82f6' },
  { type: 'fieldguard', label: 'FieldGuard AI', color: '#10b981' },
  { type: 'cadastra', label: 'Cadastra Validator', color: '#8b5cf6' },
  { type: 'developPlan', label: 'Develop Plan', color: '#f59e0b' },
  { type: 'validate', label: 'Validate', color: '#ef4444' },
  { type: 'approve', label: 'Approve', color: '#ec4899' },
  { type: 'export', label: 'Export', color: '#06b6d4' }
]

interface WorkflowCanvasProps {
  onSave?: (nodes: Node[], edges: Edge[]) => void
}

export default function WorkflowCanvas({ onSave }: WorkflowCanvasProps) {
  const [nodes, setNodes, onNodesChange] = useNodesState([])
  const [edges, setEdges, onEdgesChange] = useEdgesState([])
  
  const onConnect = useCallback((params: Connection) => {
    setEdges((eds) => addEdge(params, eds))
  }, [setEdges])
  
  const handleSave = () => {
    onSave?.(nodes, edges)
  }
  
  return (
    <div className="flex h-full">
      <div className="w-64 bg-gray-100 dark:bg-gray-800 p-4 border-r">
        <h3 className="font-semibold mb-4">Node Types</h3>
        <div className="space-y-2">
          {nodeTypes.map((nt) => (
            <div
              key={nt.type}
              className="p-2 rounded cursor-move text-white text-sm"
              style={{ backgroundColor: nt.color }}
            >
              {nt.label}
            </div>
          ))}
        </div>
        
        <button
          onClick={handleSave}
          className="mt-4 w-full px-4 py-2 bg-blue-600 text-white rounded-lg"
        >
          Save Workflow
        </button>
      </div>
      
      <div className="flex-1">
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onConnect={onConnect}
          fitView
        >
          <Background />
          <Controls />
        </ReactFlow>
      </div>
    </div>
  )
}

'use client'

/**
 * BeaconRegistryPanel — Searchable global beacon database
 *
 * Features:
 * - Text search by beacon number
 * - Proximity search by coordinate + radius
 * - Filter by county and beacon type
 * - Add new beacon to registry
 * - Click beacon to view details and copy coordinates
 */

import { useState, useCallback, useEffect } from 'react'
import {
  Search, MapPin, Plus, Loader2, Copy, Check,
  Ruler, Building2, Navigation, X,
} from 'lucide-react'

interface Beacon {
  id: string
  beacon_number: string
  beacon_type: string
  easting: number
  northing: number
  elevation?: number | null
  county?: string | null
  sub_county?: string | null
  locality?: string | null
  sheet_number?: string | null
  condition?: string | null
  description?: string | null
  distance_m?: number
}

type SearchMode = 'text' | 'proximity'

export function BeaconRegistryPanel() {
  const [mode, setMode] = useState<SearchMode>('text')
  const [query, setQuery] = useState('')
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [radius, setRadius] = useState('500')
  const [county, setCounty] = useState('')
  const [beaconType, setBeaconType] = useState('')
  const [results, setResults] = useState<Beacon[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [copiedId, setCopiedId] = useState<string | null>(null)

  const search = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const params = new URLSearchParams()
      if (mode === 'text') {
        if (query) params.set('q', query)
      } else {
        if (!easting || !northing) {
          setError('Enter easting and northing for proximity search')
          setLoading(false)
          return
        }
        params.set('easting', easting)
        params.set('northing', northing)
        params.set('radius', radius)
      }
      if (county) params.set('county', county)
      if (beaconType) params.set('beacon_type', beaconType)
      params.set('limit', '50')

      const res = await fetch(`/api/beacons?${params}`)
      if (!res.ok) throw new Error('Search failed')
      const data = await res.json()
      setResults(data.data?.beacons || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Search failed')
    } finally {
      setLoading(false)
    }
  }, [mode, query, easting, northing, radius, county, beaconType])

  // Auto-search on mount
  useEffect(() => {
    search()
  }, [])

  const handleCopy = useCallback((beacon: Beacon) => {
    const text = `${beacon.beacon_number} E:${beacon.easting.toFixed(3)} N:${beacon.northing.toFixed(3)}`
    navigator.clipboard.writeText(text)
    setCopiedId(beacon.id)
    setTimeout(() => setCopiedId(null), 2000)
  }, [])

  return (
    <div className="space-y-4">
      {/* Search header */}
      <div className="card p-4 space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
              <MapPin className="w-4 h-4 text-[var(--accent)]" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-[var(--text-primary)]">Beacon Registry</h2>
              <p className="text-[10px] text-gray-500">Search the global survey beacon database</p>
            </div>
          </div>
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-medium hover:bg-[var(--accent)]/20 transition-colors"
          >
            <Plus className="w-3.5 h-3.5" />
            Add Beacon
          </button>
        </div>

        {/* Mode toggle */}
        <div className="flex gap-1 p-1 bg-[var(--bg-tertiary)]/50 rounded-lg">
          <button
            onClick={() => setMode('text')}
            className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
              mode === 'text' ? 'bg-[var(--accent)]/15 text-[var(--accent)]' : 'text-gray-400 hover:text-gray-300'
            }`}
          >
            <Search className="w-3.5 h-3.5" />
            Search by Name
          </button>
          <button
            onClick={() => setMode('proximity')}
            className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
              mode === 'proximity' ? 'bg-[var(--accent)]/15 text-[var(--accent)]' : 'text-gray-400 hover:text-gray-300'
            }`}
          >
            <Navigation className="w-3.5 h-3.5" />
            Search by Location
          </button>
        </div>

        {/* Search inputs */}
        {mode === 'text' ? (
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
            <input
              type="text"
              value={query}
              onChange={e => setQuery(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && search()}
              aria-label="Enter beacon number (e.g., KP/12/345, MB/001)..." placeholder="Enter beacon number (e.g., KP/12/345, MB/001)..."
              className="w-full h-10 pl-9 pr-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>
        ) : (
          <div className="grid grid-cols-3 gap-2">
            <div>
              <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="easting">Easting</label>
              <input id="easting"
                type="number"
                value={easting}
                onChange={e => setEasting(e.target.value)}
                aria-label="257412" placeholder="257412"
                className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="northing">Northing</label>
              <input id="northing"
                type="number"
                value={northing}
                onChange={e => setNorthing(e.target.value)}
                aria-label="9857641" placeholder="9857641"
                className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="radius-m">Radius (m)</label>
              <input id="radius-m" aria-label="Radius (m)"
                type="number"
                value={radius}
                onChange={e => setRadius(e.target.value)}
                className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono focus:border-[var(--accent)]/30 focus:outline-none"
              />
            </div>
          </div>
        )}

        {/* Filters */}
        <div className="grid grid-cols-2 gap-2">
          <input
            type="text"
            value={county}
            onChange={e => setCounty(e.target.value)}
            aria-label="County (optional)" placeholder="County (optional)"
            className="h-9 px-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
          />
          <select
            value={beaconType}
            onChange={e => setBeaconType(e.target.value)}
            className="h-9 px-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] focus:border-[var(--accent)]/30 focus:outline-none"
          >
            <option value="">All Types</option>
            <option value="concrete">Concrete Beacon</option>
            <option value="iron_pin">Iron Pin</option>
            <option value="stone">Stone</option>
            <option value="pipe">Pipe</option>
            <option value="reference_object">Reference Object</option>
          </select>
        </div>

        <button
          onClick={search}
          disabled={loading}
          className="w-full flex items-center justify-center gap-2 h-9 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] transition-colors disabled:opacity-50"
        >
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
          Search Beacons
        </button>
      </div>

      {/* Add form */}
      {showAddForm && (
        <AddBeaconForm
          onClose={() => setShowAddForm(false)}
          onAdded={() => { setShowAddForm(false); search() }}
        />
      )}

      {/* Error */}
      {error && (
        <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 text-xs text-red-400">
          {error}
        </div>
      )}

      {/* Results */}
      <div className="card p-4">
        <div className="flex items-center justify-between mb-3">
          <span className="text-xs font-medium text-[var(--text-primary)]">
            {results.length} beacon{results.length !== 1 ? 's' : ''} found
          </span>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 text-gray-500 animate-spin" />
          </div>
        ) : results.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-8 text-center">
            <MapPin className="w-8 h-8 text-gray-600 mb-2" />
            <p className="text-sm text-gray-500">No beacons found</p>
            <p className="text-[10px] text-gray-600 mt-1">
              Try a different search or add a new beacon to the registry.
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {results.map(beacon => (
              <div
                key={beacon.id}
                className="flex items-start gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors group"
              >
                <div className="shrink-0 w-10 h-10 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
                  <MapPin className="w-4 h-4 text-[var(--accent)]" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium text-[var(--text-primary)] font-mono">
                      {beacon.beacon_number}
                    </span>
                    <span className="text-[9px] px-1.5 py-0.5 rounded bg-white/[0.04] text-gray-400 uppercase">
                      {beacon.beacon_type}
                    </span>
                    {beacon.condition && (
                      <span className={`text-[9px] px-1.5 py-0.5 rounded ${
                        beacon.condition === 'good' ? 'bg-emerald-500/10 text-emerald-400' :
                        beacon.condition === 'disturbed' ? 'bg-amber-500/10 text-amber-400' :
                        'bg-red-500/10 text-red-400'
                      }`}>
                        {beacon.condition}
                      </span>
                    )}
                  </div>
                  <div className="text-[10px] text-gray-500 font-mono mt-0.5">
                    E: {beacon.easting.toFixed(3)} | N: {beacon.northing.toFixed(3)}
                    {beacon.elevation != null && ` | Elev: ${beacon.elevation.toFixed(2)}m`}
                    {beacon.distance_m != null && (
                      <span className="text-[var(--accent)] ml-2">
                        ({beacon.distance_m.toFixed(1)}m away)
                      </span>
                    )}
                  </div>
                  {beacon.county && (
                    <div className="flex items-center gap-1 mt-0.5 text-[10px] text-gray-600">
                      <Building2 className="w-2.5 h-2.5" />
                      {beacon.county}
                      {beacon.locality && ` — ${beacon.locality}`}
                      {beacon.sheet_number && ` (Sheet: ${beacon.sheet_number})`}
                    </div>
                  )}
                </div>
                <button
                  onClick={() => handleCopy(beacon)}
                  className="shrink-0 w-8 h-8 flex items-center justify-center rounded-lg text-gray-500 hover:text-[var(--accent)] hover:bg-[var(--accent)]/5 opacity-0 group-hover:opacity-100 transition-all"
                  title="Copy coordinates"
                >
                  {copiedId === beacon.id ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

// ─── Add Beacon Form ─────────────────────────────────────────────────────

function AddBeaconForm({ onClose, onAdded }: { onClose: () => void; onAdded: () => void }) {
  const [beaconNumber, setBeaconNumber] = useState('')
  const [beaconType, setBeaconType] = useState('concrete')
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [county, setCounty] = useState('')
  const [locality, setLocality] = useState('')
  const [condition, setCondition] = useState('good')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSave = useCallback(async () => {
    setSaving(true)
    setError(null)
    try {
      const res = await fetch('/api/beacons', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          beaconNumber, beaconType,
          easting: parseFloat(easting), northing: parseFloat(northing),
          county, locality, condition,
        }),
      })
      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed to add beacon')
      }
      onAdded()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed')
    } finally {
      setSaving(false)
    }
  }, [beaconNumber, beaconType, easting, northing, county, locality, condition, onAdded])

  return (
    <div className="card p-4 space-y-3">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold text-[var(--text-primary)]">Add Beacon to Registry</h3>
        <button onClick={onClose} className="w-7 h-7 flex items-center justify-center rounded text-gray-400 hover:text-white">
          <X className="w-4 h-4" />
        </button>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="beacon-number">Beacon Number</label>
          <input id="beacon-number" type="text" value={beaconNumber} onChange={e => setBeaconNumber(e.target.value)} aria-label="KP/12/345" placeholder="KP/12/345" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs font-mono text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="type">Type</label>
          <select id="type" value={beaconType} onChange={e => setBeaconType(e.target.value)} className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)]">
            <option value="concrete">Concrete</option>
            <option value="iron_pin">Iron Pin</option>
            <option value="stone">Stone</option>
            <option value="pipe">Pipe</option>
            <option value="reference_object">Reference Object</option>
          </select>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="easting-m">Easting (m)</label>
          <input id="easting-m" type="number" step="0.001" value={easting} onChange={e => setEasting(e.target.value)} aria-label="257412.800" placeholder="257412.800" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs font-mono text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="northing-m">Northing (m)</label>
          <input type="number" step="0.001" value={northing} onChange={e => setNorthing(e.target.value)} aria-label="9857641.200" placeholder="9857641.200" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs font-mono text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-2">
        <input type="text" value={county} onChange={e => setCounty(e.target.value)} aria-label="County" placeholder="County" className="h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
        <select value={condition} onChange={e => setCondition(e.target.value)} className="h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)]">
          <option value="good">Good Condition</option>
          <option value="disturbed">Disturbed</option>
          <option value="damaged">Damaged</option>
          <option value="missing">Missing</option>
        </select>
      </div>

      {error && <p className="text-xs text-red-400">{error}</p>}

      <div className="flex gap-2">
        <button onClick={onClose} className="flex-1 h-9 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400 hover:text-gray-200">Cancel</button>
        <button
          onClick={handleSave}
          disabled={saving || !beaconNumber || !easting || !northing}
          className="flex-1 h-9 rounded-lg bg-[var(--accent)] text-black text-xs font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40"
        >
          {saving ? 'Saving...' : 'Add Beacon'}
        </button>
      </div>
    </div>
  )
}

'use client';

/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * METARDU CAD Editor — In-Browser Survey Plan Editor
 * ═══════════════════════════════════════════════════════════════════════════════
 *
 * Replaces AutoCAD for final deed plan adjustments:
 * - Drag beacons to reposition
 * - Click text to edit labels, bearings, distances
 * - Drag north arrow to reposition
 * - Drag scale bar to reposition
 * - Add custom annotations (text boxes, lines)
 * - Export to SVG, PDF, or DXF
 *
 * The surveyor's workflow becomes:
 *   Compute → Review in CAD Editor → Adjust → Export
 * No AutoCAD needed.
 */

import React, { useState, useRef, useCallback, useMemo } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  MousePointer2, Move, Type, Ruler, Compass, Download,
  Undo2, Redo2, Trash2, Plus, Minus, RotateCw, Lock, Unlock, X
} from 'lucide-react'

// ─── Types ─────────────────────────────────────────────────────────────────

export interface CADBeacon {
  id: string
  label: string
  x: number        // SVG coordinates
  y: number
  easting?: number  // real-world UTM (read-only, for reference)
  northing?: number
  symbol?: string   // 'concrete_beacon' | 'iron_peg' | etc.
  locked?: boolean
}

export interface CADBoundary {
  id: string
  fromId: string
  toId: string
  bearing: string    // display text (e.g. "45°30'00\"")
  distance: string   // display text (e.g. "125.450")
  type: 'standard' | 'road' | 'water' | 'fence'
  roadLabel?: string
}

export interface CADAnnotation {
  id: string
  type: 'text' | 'line'
  x: number
  y: number
  text?: string
  x2?: number
  y2?: number
}

export interface CADNorthArrow {
  x: number
  y: number
  rotation: number   // degrees
  type: 'grid' | 'true' | 'magnetic'
  bearing: string
}

export interface CADScaleBar {
  x: number
  y: number
  scaleMeters: number  // length of scale bar in real-world meters
}

export interface CADTitleBlock {
  projectName: string
  lrNumber: string
  surveyor: string
  regNo: string
  date: string
  scale: string
  sheet: string
}

export interface CADDocument {
  beacons: CADBeacon[]
  boundaries: CADBoundary[]
  annotations: CADAnnotation[]
  northArrow: CADNorthArrow
  scaleBar: CADScaleBar
  titleBlock: CADTitleBlock
  width: number
  height: number
}

interface CADEditorProps {
  initialDocument: CADDocument
  onSave?: (doc: CADDocument) => void
  onExportSVG?: (svg: string) => void
  onExportPDF?: () => void
  onExportDXF?: () => void
}

type Tool = 'select' | 'pan' | 'annotate-text' | 'annotate-line' | 'line' | 'text'
type SelectedItem = { type: 'beacon' | 'annotation' | 'north' | 'scale'; id: string } | null

// ─── Component ─────────────────────────────────────────────────────────────

export default function CADEditor({
  initialDocument,
  onSave,
  onExportSVG,
  onExportPDF,
  onExportDXF,
}: CADEditorProps) {
  const svgRef = useRef<SVGSVGElement>(null)
  const [doc, setDoc] = useState<CADDocument>(initialDocument)
  const [history, setHistory] = useState<CADDocument[]>([initialDocument])
  const [historyIdx, setHistoryIdx] = useState(0)
  const [tool, setTool] = useState<Tool>('select')
  const [selected, setSelected] = useState<SelectedItem>(null)
  const [cmdInput, setCmdInput] = useState('')
  const [cmdLog, setCmdLog] = useState<string>('Command: Type L, T, REC, DEL, or ZE to execute commands')
  
  const [zoom, setZoom] = useState(1)
  const [pan, setPan] = useState({ x: 0, y: 0 })
  const [editingText, setEditingText] = useState<string | null>(null)
  const dragRef = useRef<{ type: string; id: string; startX: number; startY: number; origX: number; origY: number } | null>(null)

  const handleCommandSubmit = useCallback((e: React.FormEvent) => {
    e.preventDefault()
    const raw = cmdInput.trim().toUpperCase()
    if (!raw) return

    setCmdInput('')

    if (raw === 'L' || raw === 'LINE') {
      setTool('line')
      setCmdLog('Command: LINE > Click start point')
    } else if (raw === 'T' || raw === 'TEXT') {
      setTool('text')
      setCmdLog('Command: TEXT > Click canvas to place text')
    } else if (raw === 'PAN' || raw === 'P') {
      setTool('pan')
      setCmdLog('Command: PAN > Drag view to pan canvas')
    } else if (raw === 'ZE' || raw === 'ZOOM') {
      setZoom(1)
      setPan({ x: 0, y: 0 })
      setCmdLog('Command: ZOOM > Extents reset to 100%')
    } else if (raw === 'DEL' || raw === 'ERASE') {
      setCmdLog('Command: ERASE > Removed selected item')
    } else {
      setCmdLog(`Command: Unknown command "${raw}". Try L, T, PAN, ZE, DEL`)
    }
  }, [cmdInput])

  const pushHistory = useCallback((newDoc: CADDocument) => {
    const newHistory = history.slice(0, historyIdx + 1)
    newHistory.push(newDoc)
    if (newHistory.length > 50) newHistory.shift()
    setHistory(newHistory)
    setHistoryIdx(newHistory.length - 1)
    setDoc(newDoc)
  }, [history, historyIdx])

  const undo = useCallback(() => {
    if (historyIdx > 0) {
      setHistoryIdx(historyIdx - 1)
      setDoc(history[historyIdx - 1])
    }
  }, [history, historyIdx])

  const redo = useCallback(() => {
    if (historyIdx < history.length - 1) {
      setHistoryIdx(historyIdx + 1)
      setDoc(history[historyIdx + 1])
    }
  }, [history, historyIdx])

  // ─── Drag handling ───────────────────────────────────────────────────────

  const handleMouseDown = useCallback((e: React.MouseEvent<SVGSVGElement>) => {
    if (tool === 'pan') {
      dragRef.current = { type: 'pan', id: '', startX: e.clientX, startY: e.clientY, origX: pan.x, origY: pan.y }
      return
    }
    // Click empty space → deselect
    if (e.target === e.currentTarget || (e.target as SVGElement).tagName === 'rect') {
      setSelected(null)
      setEditingText(null)
    }
  }, [tool, pan])

  const handleItemMouseDown = useCallback((e: React.MouseEvent, type: string, id: string) => {
    e.stopPropagation()
    if (tool === 'select' || tool === 'pan') {
      const item = type === 'beacon' ? doc.beacons.find(b => b.id === id)
        : type === 'north' ? doc.northArrow
        : type === 'scale' ? doc.scaleBar
        : doc.annotations.find(a => a.id === id)

      if (item && !('locked' in item && item.locked) && type !== 'title') {
        dragRef.current = {
          type, id,
          startX: e.clientX, startY: e.clientY,
          origX: (item as { x: number }).x,
          origY: (item as { y: number }).y,
        }
        setSelected({ type: type as 'beacon' | 'annotation' | 'north' | 'scale', id })
      }
    }
  }, [tool, doc])

  const handleMouseMove = useCallback((e: React.MouseEvent<SVGSVGElement>) => {
    if (!dragRef.current) return
    const d = dragRef.current
    const dx = (e.clientX - d.startX) / zoom
    const dy = (e.clientY - d.startY) / zoom

    if (d.type === 'pan') {
      setPan({ x: d.origX + dx, y: d.origY + dy })
      return
    }

    const newX = d.origX + dx
    const newY = d.origY + dy

    setDoc(prev => {
      const next = { ...prev }
      if (d.type === 'beacon') {
        next.beacons = prev.beacons.map(b => b.id === d.id ? { ...b, x: newX, y: newY } : b)
      } else if (d.type === 'annotation') {
        next.annotations = prev.annotations.map(a => a.id === d.id ? { ...a, x: newX, y: newY } : a)
      } else if (d.type === 'north') {
        next.northArrow = { ...prev.northArrow, x: newX, y: newY }
      } else if (d.type === 'scale') {
        next.scaleBar = { ...prev.scaleBar, x: newX, y: newY }
      }
      return next
    })
  }, [zoom])

  const handleMouseUp = useCallback(() => {
    if (dragRef.current && dragRef.current.type !== 'pan') {
      pushHistory(doc)
    }
    dragRef.current = null
  }, [doc, pushHistory])

  // ─── Beacon operations ───────────────────────────────────────────────────

  const updateBeaconLabel = useCallback((id: string, label: string) => {
    setDoc(prev => ({
      ...prev,
      beacons: prev.beacons.map(b => b.id === id ? { ...b, label } : b),
    }))
    pushHistory({ ...doc, beacons: doc.beacons.map(b => b.id === id ? { ...b, label } : b) })
  }, [doc, pushHistory])

  const toggleBeaconLock = useCallback((id: string) => {
    setDoc(prev => ({
      ...prev,
      beacons: prev.beacons.map(b => b.id === id ? { ...b, locked: !b.locked } : b),
    }))
  }, [])

  const deleteSelected = useCallback(() => {
    if (!selected) return
    if (selected.type === 'beacon') {
      const newDoc = {
        ...doc,
        beacons: doc.beacons.filter(b => b.id !== selected.id),
        boundaries: doc.boundaries.filter(b => b.fromId !== selected.id && b.toId !== selected.id),
      }
      pushHistory(newDoc)
    } else if (selected.type === 'annotation') {
      pushHistory({ ...doc, annotations: doc.annotations.filter(a => a.id !== selected.id) })
    }
    setSelected(null)
  }, [selected, doc, pushHistory])

  // ─── Annotations ─────────────────────────────────────────────────────────

  const addTextAnnotation = useCallback((e: React.MouseEvent<SVGSVGElement>) => {
    if (tool !== 'annotate-text') return
    const pt = svgRef.current?.createSVGPoint()
    if (!pt) return
    pt.x = e.clientX
    pt.y = e.clientY
    const ctm = svgRef.current?.getScreenCTM()
    if (!ctm) return
    const svgPt = pt.matrixTransform(ctm.inverse())

    const newAnn: CADAnnotation = {
      id: `ann-${Date.now()}`,
      type: 'text',
      x: svgPt.x,
      y: svgPt.y,
      text: 'New annotation',
    }
    pushHistory({ ...doc, annotations: [...doc.annotations, newAnn] })
    setTool('select')
    setSelected({ type: 'annotation', id: newAnn.id })
    setEditingText(newAnn.id)
  }, [tool, doc, pushHistory])

  const updateAnnotationText = useCallback((id: string, text: string) => {
    setDoc(prev => ({
      ...prev,
      annotations: prev.annotations.map(a => a.id === id ? { ...a, text } : a),
    }))
  }, [])

  // ─── SVG export ──────────────────────────────────────────────────────────

  const exportSVG = useCallback(() => {
    if (!svgRef.current) return
    const svgString = new XMLSerializer().serializeToString(svgRef.current)
    const blob = new Blob([svgString], { type: 'image/svg+xml' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `survey_plan_${Date.now()}.svg`
    a.click()
    URL.revokeObjectURL(url)
    onExportSVG?.(svgString)
  }, [onExportSVG])

  // ─── Computed ────────────────────────────────────────────────────────────

  const scaleBarPixels = useMemo(() => {
    // ponytail: convert real-world meters to SVG pixels using the diagram's scale
    // For now, use a simple 50px = scaleMeters mapping
    return 50
  }, [doc.scaleBar.scaleMeters])

  const selectedBeacon = selected?.type === 'beacon' ? doc.beacons.find(b => b.id === selected.id) : null
  const selectedAnnotation = selected?.type === 'annotation' ? doc.annotations.find(a => a.id === selected.id) : null

  // ─── Render ──────────────────────────────────────────────────────────────

  return (
    <div className="flex flex-col h-full bg-gray-900">
      {/* Toolbar */}
      <div className="flex items-center gap-1 px-3 py-2 bg-gray-800 border-b border-gray-700 flex-wrap">
        <ToolButton active={tool === 'select'} onClick={() => setTool('select')} icon={MousePointer2} label="Select" />
        <ToolButton active={tool === 'pan'} onClick={() => setTool('pan')} icon={Move} label="Pan" />
        <ToolButton active={tool === 'annotate-text'} onClick={() => setTool('annotate-text')} icon={Type} label="Add Text" />

        <div className="w-px h-6 bg-gray-600 mx-1" />

        <ToolButton onClick={undo} icon={Undo2} label="Undo" disabled={historyIdx === 0} />
        <ToolButton onClick={redo} icon={Redo2} label="Redo" disabled={historyIdx >= history.length - 1} />
        <ToolButton onClick={deleteSelected} icon={Trash2} label="Delete" disabled={!selected} />

        <div className="w-px h-6 bg-gray-600 mx-1" />

        <ToolButton onClick={() => setZoom(z => Math.max(0.25, z - 0.1))} icon={Minus} label="Zoom Out" />
        <span className="text-xs text-gray-400 px-2 tabular-nums">{Math.round(zoom * 100)}%</span>
        <ToolButton onClick={() => setZoom(z => Math.min(4, z + 0.1))} icon={Plus} label="Zoom In" />

        <div className="flex-1" />

        <Button variant="outline" size="sm" onClick={() => onSave?.(doc)} className="text-xs">
          Save
        </Button>
        <Button variant="outline" size="sm" onClick={exportSVG} className="text-xs">
          <Download className="w-3 h-3 mr-1" /> SVG
        </Button>
        {onExportPDF && (
          <Button variant="outline" size="sm" onClick={onExportPDF} className="text-xs">
            <Download className="w-3 h-3 mr-1" /> PDF
          </Button>
        )}
        {onExportDXF && (
          <Button variant="outline" size="sm" onClick={onExportDXF} className="text-xs">
            <Download className="w-3 h-3 mr-1" /> DXF
          </Button>
        )}
      </div>

      <div className="flex flex-1 overflow-hidden relative">
        {/* Canvas */}
        <div className="flex-1 overflow-auto bg-gray-950 relative">
          <svg
            ref={svgRef}
            width={doc.width * zoom}
            height={doc.height * zoom}
            viewBox={`0 0 ${doc.width} ${doc.height}`}
            style={{
              transform: `translate(${pan.x}px, ${pan.y}px)`,
              cursor: tool === 'pan' ? 'grab' : tool === 'annotate-text' ? 'crosshair' : 'default',
            }}
            className="bg-white"
            onMouseDown={(e) => { handleMouseDown(e); addTextAnnotation(e) }}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
          >
            {/* White background */}
            <rect width={doc.width} height={doc.height} fill="white" />

            {/* Boundary lines */}
            {doc.boundaries.map(b => {
              const from = doc.beacons.find(bn => bn.id === b.fromId)
              const to = doc.beacons.find(bn => bn.id === b.toId)
              if (!from || !to) return null
              const midX = (from.x + to.x) / 2
              const midY = (from.y + to.y) / 2
              const angle = Math.atan2(to.y - from.y, to.x - from.x) * 180 / Math.PI
              return (
                <g key={b.id}>
                  <line
                    x1={from.x} y1={from.y} x2={to.x} y2={to.y}
                    stroke={b.type === 'road' ? '#888' : '#000'}
                    strokeWidth={b.type === 'road' ? 3 : 1.5}
                    strokeDasharray={b.type === 'water' ? '8 4' : b.type === 'fence' ? '2 2' : undefined}
                  />
                  {/* Bearing + distance label */}
                  <g transform={`translate(${midX}, ${midY}) rotate(${angle > 90 || angle < -90 ? angle + 180 : angle})`}>
                    <rect x={-40} y={-18} width={80} height={14} fill="white" fillOpacity={0.85} rx={2} />
                    <text x={0} y={-7} textAnchor="middle" fontSize={8} fontFamily="monospace" fill="#333">
                      {b.bearing} {b.distance}m
                    </text>
                  </g>
                  {/* Road label */}
                  {b.roadLabel && (
                    <text x={midX} y={midY + 12} textAnchor="middle" fontSize={7} fill="#666" fontStyle="italic">
                      {b.roadLabel}
                    </text>
                  )}
                </g>
              )
            })}

            {/* Beacons */}
            {doc.beacons.map(b => {
              const isSelected = selected?.type === 'beacon' && selected.id === b.id
              return (
                <g
                  key={b.id}
                  transform={`translate(${b.x}, ${b.y})`}
                  onMouseDown={(e) => handleItemMouseDown(e, 'beacon', b.id)}
                  style={{ cursor: b.locked ? 'not-allowed' : 'move' }}
                >
                  {/* Selection highlight */}
                  {isSelected && <circle r={14} fill="none" stroke="#3b82f6" strokeWidth={2} strokeDasharray="3 2" />}
                  {/* Beacon symbol */}
                  <circle r={5} fill={b.locked ? '#ccc' : '#1a1a1a'} stroke="#000" strokeWidth={1} />
                  <circle r={2} fill="white" />
                  {/* Label */}
                  <text x={10} y={4} fontSize={9} fontFamily="monospace" fontWeight="bold" fill="#1a1a1a">
                    {b.label}
                  </text>
                  {/* Lock icon */}
                  {b.locked && (
                    <text x={-12} y={-8} fontSize={8} fill="#888">[Lock]</text>
                  )}
                </g>
              )
            })}

            {/* Annotations */}
            {doc.annotations.map(a => {
              const isSelected = selected?.type === 'annotation' && selected.id === a.id
              if (a.type === 'text') {
                return (
                  <g
                    key={a.id}
                    transform={`translate(${a.x}, ${a.y})`}
                    onMouseDown={(e) => handleItemMouseDown(e, 'annotation', a.id)}
                    style={{ cursor: 'move' }}
                    onDoubleClick={() => setEditingText(a.id)}
                  >
                    {isSelected && <rect x={-2} y={-12} width={(a.text?.length ?? 4) * 6 + 4} height={16} fill="none" stroke="#3b82f6" strokeWidth={1} strokeDasharray="2 2" rx={2} />}
                    <text fontSize={10} fontFamily="sans-serif" fill="#333">{a.text}</text>
                  </g>
                )
              }
              return null
            })}

            {/* North Arrow */}
            <g
              transform={`translate(${doc.northArrow.x}, ${doc.northArrow.y}) rotate(${doc.northArrow.rotation})`}
              onMouseDown={(e) => handleItemMouseDown(e, 'north', '')}
              style={{ cursor: 'move' }}
            >
              <line x1={0} y1={25} x2={0} y2={-25} stroke="#111" strokeWidth={1.5} />
              <polygon points="0,-25 -4,-8 4,-8" fill="#111" />
              <text x={0} y={-30} textAnchor="middle" fontSize={10} fontWeight="bold" fontFamily="monospace">N</text>
              <text x={0} y={38} textAnchor="middle" fontSize={7} fontFamily="monospace">
                {doc.northArrow.type === 'grid' ? 'GN' : doc.northArrow.type === 'true' ? 'TN' : 'MN'}
              </text>
            </g>

            {/* Scale Bar */}
            <g
              transform={`translate(${doc.scaleBar.x}, ${doc.scaleBar.y})`}
              onMouseDown={(e) => handleItemMouseDown(e, 'scale', '')}
              style={{ cursor: 'move' }}
            >
              <line x1={0} y1={0} x2={scaleBarPixels} y2={0} stroke="#111" strokeWidth={2} />
              <line x1={0} y1={-3} x2={0} y2={3} stroke="#111" strokeWidth={1} />
              <line x1={scaleBarPixels} y1={-3} x2={scaleBarPixels} y2={3} stroke="#111" strokeWidth={1} />
              <text x={scaleBarPixels / 2} y={-6} textAnchor="middle" fontSize={8} fontFamily="monospace">
                {doc.scaleBar.scaleMeters} m
              </text>
            </g>

            {/* Title Block */}
            <g transform={`translate(${doc.width - 280}, ${doc.height - 80})`}>
              <rect width={270} height={70} fill="white" stroke="#000" strokeWidth={1} />
              <text x={10} y={16} fontSize={8} fontFamily="monospace" fontWeight="bold">{doc.titleBlock.projectName}</text>
              <text x={10} y={30} fontSize={7} fontFamily="monospace">LR: {doc.titleBlock.lrNumber}</text>
              <text x={10} y={42} fontSize={7} fontFamily="monospace">Surveyor: {doc.titleBlock.surveyor}</text>
              <text x={10} y={54} fontSize={7} fontFamily="monospace">Reg No: {doc.titleBlock.regNo}</text>
              <text x={140} y={30} fontSize={7} fontFamily="monospace">Scale: {doc.titleBlock.scale}</text>
              <text x={140} y={42} fontSize={7} fontFamily="monospace">Date: {doc.titleBlock.date}</text>
              <text x={140} y={54} fontSize={7} fontFamily="monospace">Sheet: {doc.titleBlock.sheet}</text>
            </g>
          </svg>
        </div>

        {/* Properties Panel — sidebar on desktop, bottom sheet on mobile */}
        {/* Desktop sidebar */}
        <div className="hidden md:block w-64 bg-gray-800 border-l border-gray-700 p-3 overflow-y-auto text-sm">
          {renderPropertiesPanel()}
        </div>

        {/* Mobile bottom sheet */}
        {selected && (
          <div className="md:hidden fixed bottom-0 left-0 right-0 bg-gray-800 border-t border-gray-700 p-3 max-h-[50vh] overflow-y-auto text-sm z-50"
               style={{ paddingBottom: 'env(safe-area-inset-bottom, 0px)' }}>
            <div className="flex items-center justify-between mb-2">
              <h3 className="text-xs font-semibold text-gray-400 uppercase">
                {selectedBeacon ? 'Beacon' : selectedAnnotation ? 'Text' : 'Properties'}
              </h3>
              <button onClick={() => setSelected(null)} className="text-gray-500 hover:text-white">
                <X className="w-4 h-4" />
              </button>
            </div>
            {renderPropertiesPanel()}
          </div>
        )}
      </div>
    </div>
  )

  // ─── Properties panel renderer (shared between desktop sidebar + mobile bottom sheet) ───
  function renderPropertiesPanel() {
    if (selectedBeacon) {
      return (
        <div className="space-y-3">
          <h3 className="text-xs font-semibold text-gray-400 uppercase">Beacon Properties</h3>
          <div>
            <label htmlFor="cade-label" className="text-xs text-gray-500">Label</label>
            <Input
              id="cade-label"
              value={selectedBeacon.label}
              onChange={(e) => updateBeaconLabel(selectedBeacon.id, e.target.value)}
              className="h-7 text-xs mt-1"
            />
          </div>
          <div>
            <label htmlFor="cade-easting" className="text-xs text-gray-500">Easting (UTM)</label>
            <Input id="cade-easting" value={selectedBeacon.easting?.toFixed(3) ?? '—'} disabled className="h-7 text-xs mt-1 font-mono" />
          </div>
          <div>
            <label htmlFor="cade-northing" className="text-xs text-gray-500">Northing (UTM)</label>
            <Input id="cade-northing" value={selectedBeacon.northing?.toFixed(3) ?? '—'} disabled className="h-7 text-xs mt-1 font-mono" />
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={() => toggleBeaconLock(selectedBeacon.id)}
            className="w-full text-xs"
          >
            {selectedBeacon.locked ? <Unlock className="w-3 h-3 mr-1" /> : <Lock className="w-3 h-3 mr-1" />}
            {selectedBeacon.locked ? 'Unlock' : 'Lock'}
          </Button>
        </div>
      )
    }

    if (selectedAnnotation) {
      return (
        <div className="space-y-3">
          <h3 className="text-xs font-semibold text-gray-400 uppercase">Text Annotation</h3>
          <div>
            <label htmlFor="cade-text" className="text-xs text-gray-500">Text</label>
            <Input
              id="cade-text"
              value={selectedAnnotation.text ?? ''}
              onChange={(e) => updateAnnotationText(selectedAnnotation.id, e.target.value)}
              className="h-7 text-xs mt-1"
            />
          </div>
        </div>
      )
    }

    return (
      <div className="space-y-3">
        <h3 className="text-xs font-semibold text-gray-400 uppercase">CAD Editor</h3>
        <p className="text-xs text-gray-500">
          Click a tool above, then click on the plan to interact.
        </p>
        <div className="space-y-1 text-xs text-gray-400">
          <p><b>Select</b> — click and drag items</p>
          <p><b>Pan</b> — drag to move the view</p>
          <p><b>Add Text</b> — click to place annotation</p>
          <p><b>Double-click text</b> — edit annotation</p>
          <p><b>Delete</b> — remove selected item</p>
        </div>
        <div className="pt-3 border-t border-gray-700">
          <h4 className="text-xs font-semibold text-cyan-400 uppercase mb-1">💻 AutoCAD Command Line</h4>
          <form onSubmit={handleCommandSubmit} className="mt-1">
            <div className="text-[11px] font-mono text-gray-300 mb-1 truncate bg-black/40 p-1 rounded border border-gray-700">
              {cmdLog}
            </div>
            <div className="flex gap-1">
              <input
                type="text"
                value={cmdInput}
                onChange={e => setCmdInput(e.target.value)}
                placeholder="Command: L, T, ZE..."
                className="w-full bg-gray-900 border border-gray-700 text-xs px-2 py-1 rounded text-white font-mono placeholder:text-gray-600 focus:outline-none focus:border-cyan-400"
              />
              <button
                type="submit"
                className="px-2 py-1 bg-cyan-600 hover:bg-cyan-500 text-white text-xs rounded font-bold"
              >
                Run
              </button>
            </div>
          </form>
        </div>

        <div className="pt-3 border-t border-gray-700">
          <h4 className="text-xs font-semibold text-gray-400 uppercase mb-2">Plan Info</h4>
          <div className="text-xs text-gray-500 space-y-1">
            <p>Beacons: {doc.beacons.length}</p>
            <p>Boundaries: {doc.boundaries.length}</p>
            <p>Annotations: {doc.annotations.length}</p>
            <p>Size: {doc.width} × {doc.height}px</p>
          </div>
        </div>
      </div>
    )
  }
}

// ─── Helper Components ─────────────────────────────────────────────────────

function ToolButton({
  active, onClick, icon: Icon, label, disabled,
}: {
  active?: boolean
  onClick: () => void
  icon: React.ComponentType<{ className?: string }>
  label: string
  disabled?: boolean
}) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      title={label}
      className={`p-1.5 rounded text-xs flex items-center gap-1 transition-colors ${
        active ? 'bg-blue-600 text-white' : 'text-gray-400 hover:bg-gray-700 hover:text-white'
      } ${disabled ? 'opacity-30 cursor-not-allowed' : 'cursor-pointer'}`}
    >
      <Icon className="w-3.5 h-3.5" />
    </button>
  )
}

'use client';

import { useState } from 'react'
import { Upload, Loader2 } from 'lucide-react'
import type { BoundaryPolygon } from '@/types/cadastra'

interface BoundaryUploaderProps {
  onUpload: (boundary: BoundaryPolygon) => void
  loading?: boolean
}

export default function BoundaryUploader({ onUpload, loading }: BoundaryUploaderProps) {
  const [mode, setMode] = useState<'csv' | 'json'>('csv')
  
  const handleFileUpload = async (file: File) => {
    const text = await file.text()
    let boundary: BoundaryPolygon
    
    if (file.name.endsWith('.json') || file.name.endsWith('.geojson')) {
      const data = JSON.parse(text)
      boundary = data.features ? data.features[0].geometry : data
    } else {
      const lines = text.trim().split('\n')
      const points = lines.map((line: any) => {
        const [easting, northing] = line.split(',').map(Number)
        return { easting, northing }
      }).filter((p: any) => !isNaN(p.easting) && !isNaN(p.northing))
      boundary = { points }
    }
    
    onUpload(boundary)
  }
  
  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg p-6">
      <h2 className="text-xl font-semibold mb-4">CadastraAI Validator</h2>
      
      <div className="flex gap-4 mb-4">
        <button
          onClick={() => setMode('csv')}
          className={`px-4 py-2 rounded-lg ${mode === 'csv' ? 'bg-blue-600 text-white' : 'bg-gray-200 dark:bg-gray-700'}`}
        >
          CSV Upload
        </button>
        <button
          onClick={() => setMode('json')}
          className={`px-4 py-2 rounded-lg ${mode === 'json' ? 'bg-blue-600 text-white' : 'bg-gray-200 dark:bg-gray-700'}`}
        >
          JSON/GeoJSON
        </button>
      </div>
      
      <label className="flex items-center gap-2 px-4 py-3 bg-blue-600 text-white rounded-lg cursor-pointer hover:bg-blue-700 w-fit">
        <Upload className="h-5 w-5" />
        Upload Boundary File
        <input
          type="file"
          accept={mode === 'csv' ? '.csv' : '.json,.geojson'}
          className="hidden"
          onChange={(e) => e.target.files?.[0] && handleFileUpload(e.target.files[0])}
          disabled={loading}
        />
      </label>
      
      {loading && (
        <div className="mt-4 flex items-center gap-2">
          <Loader2 className="h-5 w-5 animate-spin" />
          <span>Validating boundary...</span>
        </div>
      )}
      
      <p className="mt-4 text-sm text-gray-500">
        CSV format: easting,northing (one point per line)
      </p>
    </div>
  )
}

'use client';

import { Download } from 'lucide-react'
// ponytail: lazy-load jspdf to keep ~400KB out of the initial client bundle
import type { ValidationResult } from '@/types/cadastra'
import { usePrint, PrintButton, PrintHeader } from '@/hooks/usePrint'

interface ValidationReportProps {
  result: ValidationResult
  projectId: string
}

export default function ValidationReport({ result, projectId }: ValidationReportProps) {
  const { print, isPrinting, paperSize, setPaperSize, orientation, setOrientation } = usePrint({ title: 'Cadastral Validation Report' })
  const generatePDF = async () => {
    const [{ jsPDF }, autoTableModule] = await Promise.all([
      import('jspdf'),
      import('jspdf-autotable'),
    ])
    const autoTable = autoTableModule.default
    const doc = new jsPDF()
    
    doc.setFontSize(18)
    doc.text('CadastraAI Validator Report', 14, 20)
    
    doc.setFontSize(11)
    doc.text(`Project: ${projectId}`, 14, 30)
    doc.text(`Date: ${new Date().toLocaleDateString()}`, 14, 36)
    doc.text(`Dispute Probability Score: ${result.score}/100`, 14, 42)
    doc.text(`Risk Level: ${result.summary.risk_level.toUpperCase()}`, 14, 48)
    
    doc.setFontSize(12)
    doc.text('Summary', 14, 60)
    doc.setFontSize(10)
    doc.text(`Total Boundary Area: ${result.summary.boundary_area} m²`, 14, 68)
    doc.text(`Total Overlap Area: ${result.summary.total_overlap_area} m²`, 14, 74)
    doc.text(`Total Gap Area: ${result.summary.total_gap_area} m²`, 14, 80)
    
    if (result.overlaps.length > 0) {
      doc.setFontSize(12)
      doc.text('Overlaps Detected', 14, 94)
      autoTable(doc, {
        startY: 100,
        head: [['ID', 'Area (m²)', 'Severity', 'Description']],
        body: result.overlaps.map((o: any) => [o.id, String(o.area), o.severity, o.description])
      })
    }
    
    if (result.gaps.length > 0) {
      const startY = result.overlaps.length > 0 ? (doc as any).lastAutoTable.finalY + 15 : 120
      doc.setFontSize(12)
      doc.text('Gaps Detected', 14, startY)
      autoTable(doc, {
        startY: startY + 6,
        head: [['ID', 'Area (m²)', 'Severity', 'Description']],
        body: result.gaps.map((g: any) => [g.id, String(g.area), g.severity, g.description])
      })
    }
    
    doc.setFontSize(8)
    doc.text('Generated by Metardu - CadastraAI Validator', 14, 280)
    doc.text('This report is for informational purposes only.', 14, 286)
    
    doc.save('cadastra-validation-report.pdf')
  }
  
  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg p-6">
      <PrintHeader title="Cadastral Validation Report" subtitle={`Project: ${projectId}`} />
      <h3 className="text-lg font-semibold mb-4">Generate Report</h3>
      
      <div className="flex items-center gap-3 no-print print-hide">
        <button
          onClick={generatePDF}
          className="flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
        >
          <Download className="h-5 w-5" />
          Download PDF Report
        </button>
        <PrintButton
          print={print}
          isPrinting={isPrinting}
          paperSize={paperSize}
          setPaperSize={setPaperSize}
          orientation={orientation}
          setOrientation={setOrientation}
          printTitle="Cadastral Validation Report"
          printSubtitle={`Project: ${projectId}`}
        />
      </div>
    </div>
  )
}

'use client';

import { useState, useId } from 'react'
import { Download , AlertTriangle } from 'lucide-react'
import { inverseComputation, polarComputation, intersectionComputation, resectionComputation, areaComputation, joinComputation, distanceDistanceIntersection, bearingDistanceIntersection, arcByRadiusAndChord, type InverseStep, type DistDistResult, type BearingDistResult, type ArcResult } from '@/lib/computations/cogoEngine'
import { downloadCSV, toCSV } from '@/lib/export/helpers'

type Tab = 'inverse' | 'polar' | 'intersection' | 'distDist' | 'bearingDist' | 'arcBoundary' | 'resection' | 'area' | 'join'

interface Props {
  compact?: boolean
}

function DMSField({ label, deg, min, sec, onChange }: { label: string; deg: string; min: string; sec: string; onChange: (f: 'd' | 'm' | 's', v: string) => void }) {
  const degId = useId()
  return (
    <div>
      <label htmlFor={degId} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
      <div className="flex gap-1">
        <input id={degId} value={deg} onChange={e => onChange('d', e.target.value)} type="number" min="0" max="359" placeholder="Deg"
          className="w-10 md:w-14 px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
        <input value={min} onChange={e => onChange('m', e.target.value)} type="number" min="0" max="59" aria-label={`${label} — minutes`} placeholder="Min"
          className="w-8 md:w-12 px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
        <input value={sec} onChange={e => onChange('s', e.target.value)} type="number" step="0.001" min="0" max="59.999" aria-label={`${label} — seconds`} placeholder="Sec"
          className="flex-1 min-w-[50px] px-1 md:px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-xs md:text-sm" />
      </div>
    </div>
  )
}

function DMSState() {
  return { d: '', m: '', s: '' }
}

function DMSGet(d: ReturnType<typeof DMSState>) {
  return { deg: parseInt(d.d) || 0, min: parseInt(d.m) || 0, sec: parseFloat(d.s) || 0 }
}

function StepsDisplay({ steps, title }: { steps: InverseStep[]; title?: string }) {
  if (!steps || steps.length === 0) return null
  return (
    <div className="space-y-2">
      {title && <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider">{title}</h3>}
      <div className="space-y-1">
        {steps.map((step, i) => (
          <div key={step.value} className="grid grid-cols-[1fr_auto_1fr] md:grid-cols-[1fr_auto_1fr_auto] gap-x-1 md:gap-x-2 text-xs font-mono py-1 border-b border-[var(--border-color)]/20">
            <span className="text-[var(--text-secondary)]">{step.description}</span>
            <span className="text-[var(--text-muted)]">=</span>
            <span className="text-[var(--text-primary)] text-right">{step.value}</span>
            <span className="hidden md:block text-[var(--text-muted)] text-right min-w-[120px] text-right">{step.formula}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

function CoordField({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
  const id = useId()
  return (
    <div>
      <label htmlFor={id} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
      <input id={id} value={value} onChange={e => onChange(e.target.value)} type="number" step="0.001"
        className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
    </div>
  )
}

function ResultCard({ label, value, accent }: { label: string; value: string; accent?: boolean }) {
  return (
    <div className={`px-3 py-2 rounded border ${accent ? 'border-[var(--accent)] bg-[var(--accent)]/10' : 'border-[var(--border-color)] bg-[var(--bg-tertiary)]/50'}`}>
      <p className="text-xs text-[var(--text-secondary)]">{label}</p>
      <p className={`text-sm font-mono font-semibold ${accent ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]'}`}>{value}</p>
    </div>
  )
}

export default function COGOCalculator({ compact = false }: Props) {
  const [activeTab, setActiveTab] = useState<Tab>('inverse')
  const [error, setError] = useState('')

  // ── INVERSE ──────────────────────────────────────────────────────────────────
  const [invE1, setInvE1] = useState('')
  const [invN1, setInvN1] = useState('')
  const [invE2, setInvE2] = useState('')
  const [invN2, setInvN2] = useState('')
  const [invL1, setInvL1] = useState('A')
  const [invL2, setInvL2] = useState('B')
  const [invResult, setInvResult] = useState<ReturnType<typeof inverseComputation> | null>(null)

  // ── POLAR ───────────────────────────────────────────────────────────────────
  const [polE1, setPolE1] = useState('')
  const [polN1, setPolN1] = useState('')
  const [polD, setPolD] = useState('')
  const [polBear, setPolBear] = useState(DMSState())
  const [polResult, setPolResult] = useState<ReturnType<typeof polarComputation> | null>(null)

  // ── INTERSECTION ─────────────────────────────────────────────────────────────
  const [intE1, setIntE1] = useState('')
  const [intN1, setIntN1] = useState('')
  const [intE2, setIntE2] = useState('')
  const [intN2, setIntN2] = useState('')
  const [intBear1, setIntBear1] = useState(DMSState())
  const [intBear2, setIntBear2] = useState(DMSState())
  const [intResult, setIntResult] = useState<ReturnType<typeof intersectionComputation> | null>(null)

  // ── RESECTION ────────────────────────────────────────────────────────────────
  const [resEA, setResEA] = useState(''); const [resNA, setResNA] = useState('')
  const [resEB, setResEB] = useState(''); const [resNB, setResNB] = useState('')
  const [resEC, setResEC] = useState(''); const [resNC, setResNC] = useState('')
  const [resAlpha, setResAlpha] = useState(DMSState())
  const [resBeta, setResBeta] = useState(DMSState())
  const [resResult, setResResult] = useState<ReturnType<typeof resectionComputation> | null>(null)

  // ── AREA ────────────────────────────────────────────────────────────────────
  const [areaText, setAreaText] = useState('')
  const [areaResult, setAreaResult] = useState<ReturnType<typeof areaComputation> | null>(null)

  // ── JOIN ────────────────────────────────────────────────────────────────────
  const [joinText, setJoinText] = useState('')
  const [joinResult, setJoinResult] = useState<ReturnType<typeof joinComputation> | null>(null)

  // ── DISTANCE-DISTANCE ──────────────────────────────────────────────────────
  const [ddE1, setDdE1] = useState(''); const [ddN1, setDdN1] = useState('')
  const [ddE2, setDdE2] = useState(''); const [ddN2, setDdN2] = useState('')
  const [ddD1, setDdD1] = useState(''); const [ddD2, setDdD2] = useState('')
  const [ddResult, setDdResult] = useState<DistDistResult | null>(null)
  const [ddSel, setDdSel] = useState(0)

  // ── BEARING-DISTANCE ───────────────────────────────────────────────────────
  const [bdE1, setBdE1] = useState(''); const [bdN1, setBdN1] = useState('')
  const [bdE2, setBdE2] = useState(''); const [bdN2, setBdN2] = useState('')
  const [bdBear, setBdBear] = useState(DMSState())
  const [bdDist, setBdDist] = useState('')
  const [bdResult, setBdResult] = useState<BearingDistResult | null>(null)
  const [bdSel, setBdSel] = useState(0)

  // ── ARC BOUNDARY ──────────────────────────────────────────────────────────
  const [arcSE, setArcSE] = useState(''); const [arcSN, setArcSN] = useState('')
  const [arcEE, setArcEE] = useState(''); const [arcEN, setArcEN] = useState('')
  const [arcR, setArcR] = useState(''); const [arcCW, setArcCW] = useState(true)
  const [arcResult, setArcResult] = useState<ArcResult | null>(null)

  // ── COMPUTE HANDLERS ────────────────────────────────────────────────────────
  const handleInverse = () => {
    setError('')
    if (!invE1 || !invN1 || !invE2 || !invN2) { setError('Enter all coordinates'); return }
    try {
      setInvResult(inverseComputation({
        e1: parseFloat(invE1), n1: parseFloat(invN1),
        e2: parseFloat(invE2), n2: parseFloat(invN2),
        label1: invL1, label2: invL2,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handlePolar = () => {
    setError('')
    if (!polE1 || !polN1 || !polD) { setError('Enter all fields'); return }
    const b = DMSGet(polBear)
    try {
      setPolResult(polarComputation({
        e1: parseFloat(polE1), n1: parseFloat(polN1),
        bearingDeg: b.deg, bearingMin: b.min, bearingSec: b.sec,
        distance: parseFloat(polD),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleIntersection = () => {
    setError('')
    const b1 = DMSGet(intBear1)
    const b2 = DMSGet(intBear2)
    try {
      setIntResult(intersectionComputation({
        e1: parseFloat(intE1), n1: parseFloat(intN1),
        e2: parseFloat(intE2), n2: parseFloat(intN2),
        bearingDeg1: b1.deg, bearingMin1: b1.min, bearingSec1: b1.sec,
        bearingDeg2: b2.deg, bearingMin2: b2.min, bearingSec2: b2.sec,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleResection = () => {
    setError('')
    const a = DMSGet(resAlpha)
    const b = DMSGet(resBeta)
    try {
      setResResult(resectionComputation({
        eA: parseFloat(resEA), nA: parseFloat(resNA),
        eB: parseFloat(resEB), nB: parseFloat(resNB),
        eC: parseFloat(resEC), nC: parseFloat(resNC),
        alphaDeg: a.deg, alphaMin: a.min, alphaSec: a.sec,
        betaDeg: b.deg, betaMin: b.min, betaSec: b.sec,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleArea = () => {
    setError('')
    const lines = areaText.trim().split('\n').filter((l) => l.trim())
    const points = lines.map((line: any) => {
      const parts = line.split(/[,\t]+/)
      if (parts.length < 3) return null
      return { label: parts[0].trim(), easting: parseFloat(parts[1]), northing: parseFloat(parts[2]) }
    }).filter(Boolean) as Array<{ label: string; easting: number; northing: number }>
    if (points.length < 3) { setError('At least 3 points required'); return }
    try {
      setAreaResult(areaComputation({ points }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleJoin = () => {
    setError('')
    const lines = joinText.trim().split('\n').filter((l) => l.trim())
    const points = lines.map((line: any) => {
      const parts = line.split(/[,\t]+/)
      if (parts.length < 3) return null
      return { label: parts[0].trim(), easting: parseFloat(parts[1]), northing: parseFloat(parts[2]) }
    }).filter(Boolean) as Array<{ label: string; easting: number; northing: number }>
    if (points.length < 2) { setError('At least 2 points required'); return }
    try {
      setJoinResult(joinComputation({ points }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleDistDist = () => {
    setError('')
    if (!ddE1 || !ddN1 || !ddE2 || !ddN2 || !ddD1 || !ddD2) { setError('Enter all fields'); return }
    try {
      setDdResult(distanceDistanceIntersection({
        e1: parseFloat(ddE1), n1: parseFloat(ddN1),
        e2: parseFloat(ddE2), n2: parseFloat(ddN2),
        distance1: parseFloat(ddD1), distance2: parseFloat(ddD2),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleBearingDist = () => {
    setError('')
    const b = DMSGet(bdBear)
    if (!bdE1 || !bdN1 || !bdE2 || !bdN2 || !bdDist) { setError('Enter all fields'); return }
    try {
      setBdResult(bearingDistanceIntersection({
        e1: parseFloat(bdE1), n1: parseFloat(bdN1),
        e2: parseFloat(bdE2), n2: parseFloat(bdN2),
        bearingDeg: b.deg, bearingMin: b.min, bearingSec: b.sec,
        distance: parseFloat(bdDist),
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const handleArcBoundary = () => {
    setError('')
    if (!arcSE || !arcSN || !arcEE || !arcEN || !arcR) { setError('Enter all fields'); return }
    try {
      setArcResult(arcByRadiusAndChord({
        startPoint: { easting: parseFloat(arcSE), northing: parseFloat(arcSN) },
        endPoint: { easting: parseFloat(arcEE), northing: parseFloat(arcEN) },
        radius: parseFloat(arcR),
        isClockwise: arcCW,
      }))
    } catch (e: unknown) { setError((e instanceof Error ? (e as Error).message : String(e))) }
  }

  const clearAll = () => {
    setError('')
    setInvResult(null); setPolResult(null); setIntResult(null)
    setResResult(null); setAreaResult(null); setJoinResult(null)
    setDdResult(null); setBdResult(null); setArcResult(null)
  }

  const handleExportPDF = async () => {
    try {
      const { default: jsPDF } = await import('jspdf')
      const { default: autoTable } = await import('jspdf-autotable')
      const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })

      doc.setFontSize(16)
      doc.text('METARDU — COGO Computation Report', 14, 14)
      doc.setFontSize(10)
      doc.text(`Computation Type: ${TABS.find((t) => t.id === activeTab)?.label || activeTab}`, 14, 22)
      doc.setFontSize(8)
      doc.text(`Generated: ${new Date().toLocaleString()} | Survey Act Cap. 299 | RDM 1.1 (2025)`, 14, 28)
      doc.setDrawColor(150)
      doc.line(14, 30, 196, 30)

      if (activeTab === 'inverse' && invResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value', 'Formula']],
          body: [
            ['Point 1', invL1, ''],
            ['Point 2', invL2, ''],
            ['Delta Easting', `${invResult.deltaE.toFixed(4)} m`, ''],
            ['Delta Northing', `${invResult.deltaN.toFixed(4)} m`, ''],
            ['WCB', invResult.wcbDMS, ''],
            ['Distance', `${invResult.distance.toFixed(4)} m`, ''],
            ['Reduced Bearing', invResult.reducedBearing, ''],
            ['Back Bearing', invResult.backBearingDMS, ''],
            ['Quadrant', invResult.quadrant, ''],
            ['Arithmetic Check', invResult.arithmeticCheck.passed ? 'PASS' : 'FAIL', invResult.arithmeticCheck.value.toFixed(6)],
          ],
          styles: { fontSize: 9 },
          columnStyles: { 2: { cellWidth: 60 } },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'polar' && polResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['WCB Used', polResult.wcbDMS],
            ['E2 (m)', polResult.e2.toFixed(4)],
            ['N2 (m)', polResult.n2.toFixed(4)],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'intersection' && intResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Intersection Easting E3 (m)', intResult.e3.toFixed(4)],
            ['Intersection Northing N3 (m)', intResult.n3.toFixed(4)],
            ['Distance from P1 (m)', intResult.distanceFrom1.toFixed(4)],
            ['Distance from P2 (m)', intResult.distanceFrom2.toFixed(4)],
            ['Check Difference (m)', intResult.checkDiff.toFixed(4)],
            ['Within Tolerance', intResult.isWithinTolerance ? 'PASS' : 'FLAG'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'resection' && resResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Station E (m)', resResult.eP.toFixed(4)],
            ['Station N (m)', resResult.nP.toFixed(4)],
            ['Distance to A (m)', resResult.distToA.toFixed(4)],
            ['Distance to B (m)', resResult.distToB.toFixed(4)],
            ['Distance to C (m)', resResult.distToC.toFixed(4)],
            ['Danger Circle', resResult.isDangerCircle ? 'WARNING' : 'No'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'area' && areaResult) {
        autoTable(doc, {
          startY: 34,
          head: [['Parameter', 'Value']],
          body: [
            ['Area (m\u00B2)', areaResult.areaSqm.toFixed(4)],
            ['Area (ha)', areaResult.areaHa.toFixed(4)],
            ['Perimeter (m)', areaResult.perimeter.toFixed(4)],
            ['Centroid E (m)', areaResult.centroid.easting.toFixed(4)],
            ['Centroid N (m)', areaResult.centroid.northing.toFixed(4)],
            ['Arithmetic Check', areaResult.arithmeticCheck.passed ? 'PASS' : 'FAIL'],
          ],
          styles: { fontSize: 9 },
          headStyles: { fillColor: [34, 197, 94] },
        })
      } else if (activeTab === 'join' && joinResult) {
        autoTable(doc, {
          startY: 34,
          head: [['From', 'To', 'Delta E (m)', 'Delta N (m)', 'Distance (m)', 'WCB', 'Back Bearing']],
          body: joinResult.rows.map((r) => [r.from, r.to, r.deltaE.toFixed(4), r.deltaN.toFixed(4), r.distance.toFixed(4), r.wcbDMS, r.backBearingDMS]),
          styles: { fontSize: 8 },
          headStyles: { fillColor: [34, 197, 94] },
        })
        const finalY = (doc as any).lastAutoTable.finalY + 6
        doc.setFontSize(9)
        doc.text(`Total Perimeter: ${joinResult.totalPerimeter.toFixed(4)} m`, 14, finalY)
      } else {
        doc.setFontSize(10)
        doc.text('No computation results to export. Run a calculation first.', 14, 34)
      }

      doc.setFontSize(7)
      doc.setTextColor(120)
      doc.text('Source: Ghilani & Wolf, Elementary Surveying 16th Ed. | N.N. Basak, Surveying and Levelling | Survey Act Cap. 299 | RDM 1.1 (2025)', 14, doc.internal.pageSize.height - 8)
      doc.setTextColor(0)

      const date = new Date().toISOString().slice(0, 10)
      const tabName = TABS.find((t) => t.id === activeTab)?.label.replace(/[^a-zA-Z]/g, '_') || activeTab
      doc.save(`METARDU_COGO_${tabName}_${date}.pdf`)
    } catch (err) {
      console.error('PDF export error:', err)
      setError('Failed to export PDF. Please try again.')
    }
  }

  const handleExportCSV = () => {
    try {
      let headers: string[] = ['Parameter', 'Value']
      let rows: string[][] = []

      if (activeTab === 'inverse' && invResult) {
        headers = ['Parameter', 'Value', 'Formula']
        rows = [
          ['Point 1', invL1, ''],
          ['Point 2', invL2, ''],
          ['Delta Easting (m)', invResult.deltaE.toFixed(4), ''],
          ['Delta Northing (m)', invResult.deltaN.toFixed(4), ''],
          ['WCB', invResult.wcbDMS, ''],
          ['Distance (m)', invResult.distance.toFixed(4), ''],
          ['Reduced Bearing', invResult.reducedBearing, ''],
          ['Back Bearing', invResult.backBearingDMS, ''],
          ['Quadrant', invResult.quadrant, ''],
          ['Arithmetic Check', invResult.arithmeticCheck.passed ? 'PASS' : 'FAIL', invResult.arithmeticCheck.value.toFixed(6)],
        ]
      } else if (activeTab === 'polar' && polResult) {
        rows = [
          ['WCB Used', polResult.wcbDMS],
          ['E2 (m)', polResult.e2.toFixed(4)],
          ['N2 (m)', polResult.n2.toFixed(4)],
        ]
      } else if (activeTab === 'intersection' && intResult) {
        rows = [
          ['Intersection E3 (m)', intResult.e3.toFixed(4)],
          ['Intersection N3 (m)', intResult.n3.toFixed(4)],
          ['Distance from P1 (m)', intResult.distanceFrom1.toFixed(4)],
          ['Distance from P2 (m)', intResult.distanceFrom2.toFixed(4)],
        ]
      } else if (activeTab === 'resection' && resResult) {
        rows = [
          ['Station E (m)', resResult.eP.toFixed(4)],
          ['Station N (m)', resResult.nP.toFixed(4)],
          ['Distance to A (m)', resResult.distToA.toFixed(4)],
          ['Distance to B (m)', resResult.distToB.toFixed(4)],
          ['Distance to C (m)', resResult.distToC.toFixed(4)],
        ]
      } else if (activeTab === 'area' && areaResult) {
        rows = [
          ['Area (m²)', areaResult.areaSqm.toFixed(4)],
          ['Area (ha)', areaResult.areaHa.toFixed(4)],
          ['Perimeter (m)', areaResult.perimeter.toFixed(4)],
          ['Centroid E (m)', areaResult.centroid.easting.toFixed(4)],
          ['Centroid N (m)', areaResult.centroid.northing.toFixed(4)],
        ]
      } else if (activeTab === 'join' && joinResult) {
        headers = ['From', 'To', 'Delta E (m)', 'Delta N (m)', 'Distance (m)', 'WCB', 'Back Bearing']
        rows = joinResult.rows.map(r => [r.from, r.to, r.deltaE.toFixed(4), r.deltaN.toFixed(4), r.distance.toFixed(4), r.wcbDMS, r.backBearingDMS])
      } else {
        setError('No data to export')
        return
      }

      const csv = toCSV(headers, rows)
      const tabName = TABS.find(t => t.id === activeTab)?.label.replace(/[^a-zA-Z]/g, '_') || activeTab
      downloadCSV(csv, `METARDU_COGO_${tabName}`)
    } catch (err) {
      console.error('CSV export error:', err)
      setError('Failed to export CSV. Please try again.')
    }
  }

  const TABS: { id: Tab; label: string }[] = [
    { id: 'inverse', label: 'Distance & Bearing' },
    { id: 'polar', label: 'Radiation' },
    { id: 'intersection', label: 'Brg-Brg Intersection' },
    { id: 'distDist', label: 'Dist-Dist Intersection' },
    { id: 'bearingDist', label: 'Brg-Dist Intersection' },
    { id: 'arcBoundary', label: 'Arc Boundary' },
    { id: 'resection', label: 'Resection' },
    { id: 'area', label: 'Area by Coordinates' },
    { id: 'join', label: 'Missing Line' },
  ]

  return (
    <div className={compact ? '' : 'w-full max-w-7xl mx-auto px-3 md:px-4 py-4 md:py-8'}>
      {!compact && (
        <>
          <h1 className="text-3xl font-bold mb-2">COGO Calculator</h1>
          <p className="text-sm text-[var(--text-muted)] mb-6">
            Coordinate Geometry — Inverse, Polar, Intersection, Resection, Area, Join | Survey Act Cap 299 | RDM 1.1 (2025)
          </p>
        </>
      )}

      {/* Tab Bar */}
      <div className="flex items-center gap-1 border-b border-[var(--border-color)] mb-4 overflow-x-auto">
        {TABS.map((tab: any) => (
          <button key={tab.id} onClick={() => { setActiveTab(tab.id); clearAll() }}
            className={`px-4 py-2 text-sm font-medium whitespace-nowrap border-b-2 transition-colors ${
              activeTab === tab.id
                ? 'border-[var(--accent)] text-[var(--accent)]'
                : 'border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)]'
            }`}>
            {tab.label}
          </button>
        ))}
        <div className="flex-1" />
        <button onClick={handleExportPDF}
          className="px-3 py-1.5 text-xs text-[var(--text-secondary)] hover:text-[var(--accent)] border border-[var(--border-color)] hover:border-[var(--accent)] rounded inline-flex items-center gap-1">
          <Download className="w-3 h-3" /> PDF
        </button>
        <button onClick={handleExportCSV}
          className="px-3 py-1.5 text-xs text-[var(--text-secondary)] hover:text-[var(--accent)] border border-[var(--border-color)] hover:border-[var(--accent)] rounded inline-flex items-center gap-1">
          <Download className="w-3 h-3" /> CSV
        </button>
        <button onClick={clearAll}
          className="px-3 py-1.5 text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)]">
          Clear
        </button>
      </div>

      {error && <div className="mb-4 p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{error}</div>}

      <div className="grid md:grid-cols-2 gap-6">
        {/* ── INPUT PANEL ── */}
        <div className="space-y-4">
          {/* INVERSE */}
          {activeTab === 'inverse' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Inverse Computation — Given two points, compute bearing and distance</h2>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Point 1 Easting (m)" value={invE1} onChange={setInvE1} />
                <CoordField label="Point 1 Northing (m)" value={invN1} onChange={setInvN1} />
                <div>
                  <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="point-1-label">Point 1 Label</label>
                  <input id="point-1-label" value={invL1} onChange={e => setInvL1(e.target.value)}
                    className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Point 2 Easting (m)" value={invE2} onChange={setInvE2} />
                <CoordField label="Point 2 Northing (m)" value={invN2} onChange={setInvN2} />
                <div>
                  <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="point-2-label">Point 2 Label</label>
                  <input id="point-2-label" value={invL2} onChange={e => setInvL2(e.target.value)}
                    className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                </div>
              </div>
              <button onClick={handleInverse} className="btn btn-primary w-full">Compute Inverse →</button>
            </div>
          )}

          {/* RADIATION */}
          {activeTab === 'polar' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Radiation — Station + bearing/dist → coordinates</h2>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Known Easting (m)" value={polE1} onChange={setPolE1} />
                <CoordField label="Known Northing (m)" value={polN1} onChange={setPolN1} />
              </div>
              <DMSField label="WCB Bearing" deg={polBear.d} min={polBear.m} sec={polBear.s}
                onChange={(f, v) => setPolBear(p => ({ ...p, [f]: v }))} />
              <CoordField label="Distance (m)" value={polD} onChange={setPolD} />
              <button onClick={handlePolar} className="btn btn-primary w-full">Compute Polar →</button>
            </div>
          )}

          {/* INTERSECTION */}
          {activeTab === 'intersection' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Bearing Intersection — Compute intersection of two bearings</h2>
              <p className="text-xs text-[var(--text-muted)]">Known Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Easting (m)" value={intE1} onChange={setIntE1} />
                <CoordField label="Northing (m)" value={intN1} onChange={setIntN1} />
              </div>
              <DMSField label="Bearing from Point 1 (DMS)" deg={intBear1.d} min={intBear1.m} sec={intBear1.s}
                onChange={(f, v) => setIntBear1(p => ({ ...p, [f]: v }))} />
              <p className="text-xs text-[var(--text-muted)]">Known Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="Easting (m)" value={intE2} onChange={setIntE2} />
                <CoordField label="Northing (m)" value={intN2} onChange={setIntN2} />
              </div>
              <DMSField label="Bearing from Point 2 (DMS)" deg={intBear2.d} min={intBear2.m} sec={intBear2.s}
                onChange={(f, v) => setIntBear2(p => ({ ...p, [f]: v }))} />
              <button onClick={handleIntersection} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* RESECTION */}
          {activeTab === 'resection' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Three-Point Resection (Tienstra/Pothenot)</h2>
              <div className="grid grid-cols-3 gap-2">
                <div />
                <div className="text-xs text-center font-semibold text-[var(--text-secondary)]">Easting</div>
                <div className="text-xs text-center font-semibold text-[var(--text-secondary)]">Northing</div>
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point A</div>
                <input aria-label="Result easting A" value={resEA} onChange={e => setResEA(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing A" value={resNA} onChange={e => setResNA(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point B</div>
                <input aria-label="Result easting B" value={resEB} onChange={e => setResEB(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing B" value={resNB} onChange={e => setResNB(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <div className="text-xs text-[var(--text-secondary)] flex items-center">Point C</div>
                <input aria-label="Result easting C" value={resEC} onChange={e => setResEC(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
                <input aria-label="Result northing C" value={resNC} onChange={e => setResNC(e.target.value)} type="number" step="0.001"
                  className="px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
              </div>
              <DMSField label="Angle α = ∠APB (DMS)" deg={resAlpha.d} min={resAlpha.m} sec={resAlpha.s}
                onChange={(f, v) => setResAlpha(p => ({ ...p, [f]: v }))} />
              <DMSField label="Angle β = ∠BPC (DMS)" deg={resBeta.d} min={resBeta.m} sec={resBeta.s}
                onChange={(f, v) => setResBeta(p => ({ ...p, [f]: v }))} />
              <button onClick={handleResection} className="btn btn-primary w-full">Compute Resection →</button>
            </div>
          )}

          {/* AREA */}
          {activeTab === 'area' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Area by Coordinates (Shoelace)</h2>
              <p className="text-xs text-[var(--text-muted)]">Enter one point per line: Label, Easting, Northing</p>
              <textarea value={areaText} onChange={e => setAreaText(e.target.value)}
                className="w-full h-48 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm font-mono"
                placeholder='Label, Easting, Northing (one point per line)' />
              <button onClick={handleArea} className="btn btn-primary w-full">Compute Area →</button>
            </div>
          )}

          {/* DISTANCE-DISTANCE */}
          {activeTab === 'distDist' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Distance-Distance Intersection — Circle-circle</h2>
              <p className="text-xs text-[var(--text-muted)]">Known Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₁ (m)" value={ddE1} onChange={setDdE1} />
                <CoordField label="N₁ (m)" value={ddN1} onChange={setDdN1} />
              </div>
              <CoordField label="Distance from P1 (m)" value={ddD1} onChange={setDdD1} />
              <p className="text-xs text-[var(--text-muted)]">Known Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₂ (m)" value={ddE2} onChange={setDdE2} />
                <CoordField label="N₂ (m)" value={ddN2} onChange={setDdN2} />
              </div>
              <CoordField label="Distance from P2 (m)" value={ddD2} onChange={setDdD2} />
              <button onClick={handleDistDist} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* BEARING-DISTANCE */}
          {activeTab === 'bearingDist' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Bearing-Distance Intersection — Ray meets circle</h2>
              <p className="text-xs text-[var(--text-muted)]">Bearing from Point 1</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₁ (m)" value={bdE1} onChange={setBdE1} />
                <CoordField label="N₁ (m)" value={bdN1} onChange={setBdN1} />
              </div>
              <DMSField label="WCB Bearing from P1" deg={bdBear.d} min={bdBear.m} sec={bdBear.s}
                onChange={(f, v) => setBdBear(p => ({ ...p, [f]: v }))} />
              <p className="text-xs text-[var(--text-muted)]">Distance from Point 2</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E₂ (m)" value={bdE2} onChange={setBdE2} />
                <CoordField label="N₂ (m)" value={bdN2} onChange={setBdN2} />
              </div>
              <CoordField label="Distance from P2 (m)" value={bdDist} onChange={setBdDist} />
              <button onClick={handleBearingDist} className="btn btn-primary w-full">Compute Intersection →</button>
            </div>
          )}

          {/* ARC BOUNDARY */}
          {activeTab === 'arcBoundary' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Arc Boundary — Radius + Chord endpoints</h2>
              <p className="text-xs text-[var(--text-muted)]">Start Point</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E start (m)" value={arcSE} onChange={setArcSE} />
                <CoordField label="N start (m)" value={arcSN} onChange={setArcSN} />
              </div>
              <p className="text-xs text-[var(--text-muted)]">End Point</p>
              <div className="grid grid-cols-2 gap-3">
                <CoordField label="E end (m)" value={arcEE} onChange={setArcEE} />
                <CoordField label="N end (m)" value={arcEN} onChange={setArcEN} />
              </div>
              <CoordField label="Radius (m)" value={arcR} onChange={setArcR} />
              <label className="flex items-center gap-2 text-sm text-[var(--text-secondary)]">
                <input type="checkbox" checked={arcCW} onChange={e => setArcCW(e.target.checked)} /> Clockwise arc
              </label>
              <button onClick={handleArcBoundary} className="btn btn-primary w-full">Compute Arc →</button>
            </div>
          )}

          {/* JOIN */}
          {activeTab === 'join' && (
            <div className="card p-4 space-y-3">
              <h2 className="font-semibold text-sm">Join Computation — Traverse summary table</h2>
              <p className="text-xs text-[var(--text-muted)]">Enter points in order: Label, Easting, Northing</p>
              <textarea value={joinText} onChange={e => setJoinText(e.target.value)}
                className="w-full h-48 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm font-mono"
                placeholder='Label, Easting, Northing (one point per line)' />
              <button onClick={handleJoin} className="btn btn-primary w-full">Compute Joins →</button>
            </div>
          )}
        </div>

        {/* ── RESULTS PANEL ── */}
        <div className="space-y-4">
          {/* INVERSE RESULTS */}
          {activeTab === 'inverse' && invResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Inverse</h2>
              <StepsDisplay steps={invResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="ΔE" value={`${invResult.deltaE.toFixed(4)} m`} />
                  <ResultCard label="ΔN" value={`${invResult.deltaN.toFixed(4)} m`} />
                  <ResultCard label="WCB" value={invResult.wcbDMS} accent />
                  <ResultCard label="Distance" value={`${invResult.distance.toFixed(4)} m`} accent />
                  <ResultCard label="Reduced Bearing θ" value={invResult.reducedBearing} />
                  <ResultCard label="Back Bearing" value={invResult.backBearingDMS} />
                  <ResultCard label="Quadrant" value={invResult.quadrant} />
                  <ResultCard label="Arithmetic Check"
                    value={`${invResult.arithmeticCheck.passed ? 'PASS ' : 'FAIL [x]'} (${invResult.arithmeticCheck.value.toFixed(6)})`}
                    accent={invResult.arithmeticCheck.passed} />
                </div>
              </div>
            </div>
          )}

          {/* POLAR RESULTS */}
          {activeTab === 'polar' && polResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Polar</h2>
              <StepsDisplay steps={polResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="WCB Used" value={polResult.wcbDMS} accent />
                  <ResultCard label="E₂ (m)" value={polResult.e2.toFixed(4)} accent />
                  <ResultCard label="N₂ (m)" value={polResult.n2.toFixed(4)} accent />
                </div>
              </div>
            </div>
          )}

          {/* INTERSECTION RESULTS */}
          {activeTab === 'intersection' && intResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Bearing Intersection</h2>
              <StepsDisplay steps={intResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E₃ (m)" value={intResult.e3.toFixed(4)} accent />
                  <ResultCard label="N₃ (m)" value={intResult.n3.toFixed(4)} accent />
                  <ResultCard label="Dist from P1" value={`${intResult.distanceFrom1.toFixed(4)} m`} />
                  <ResultCard label="Dist from P2" value={`${intResult.distanceFrom2.toFixed(4)} m`} />
                  <ResultCard label="Check Difference"
                    value={`${intResult.checkDiff.toFixed(4)} m  ${intResult.isWithinTolerance ? ' PASS' : '[x] FLAG'}`}
                    accent={intResult.isWithinTolerance} />
                </div>
              </div>
            </div>
          )}

          {/* RESECTION RESULTS */}
          {activeTab === 'resection' && resResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Tienstra Resection</h2>
              {resResult.isDangerCircle && (
                <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
                  <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> DANGER CIRCLE WARNING — K₁+K₂+K₃ ≈ 0. Point P is approximately on the circumcircle of triangle ABC. Results may be unreliable. Consider changing observation setup.
                </div>
              )}
              <StepsDisplay steps={resResult.steps} />
              <div className="border-t border-[var(--border-color)] pt-4">
                <h3 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">Result</h3>
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="Eₚ (m)" value={resResult.eP.toFixed(4)} accent />
                  <ResultCard label="Nₚ (m)" value={resResult.nP.toFixed(4)} accent />
                  <ResultCard label="Dist to A" value={`${resResult.distToA.toFixed(4)} m`} />
                  <ResultCard label="Dist to B" value={`${resResult.distToB.toFixed(4)} m`} />
                  <ResultCard label="Dist to C" value={`${resResult.distToC.toFixed(4)} m`} />
                </div>
              </div>
            </div>
          )}

          {/* AREA RESULTS */}
          {activeTab === 'area' && areaResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Area by Coordinates</h2>
              {!areaResult.arithmeticCheck.passed && (
                <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">
                  Arithmetic check failed. Difference: {areaResult.arithmeticCheck.diff.toFixed(4)} m². Recheck coordinate entries.
                </div>
              )}
              <div className="overflow-x-auto">
                <table className="w-full text-xs font-mono">
                  <thead>
                    <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">From</th>
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">To</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">E×Nₙ₊₁</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">N×Eₙ₊₁</th>
                    </tr>
                  </thead>
                  <tbody>
                    {areaResult.diagonalRows.map((row, i) => (
                      <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/20">
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.from}</td>
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.to}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.posProduct.toFixed(2)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.negProduct.toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="font-semibold">
                      <td colSpan={2} className="px-2 py-1 text-[var(--text-primary)]">Σ</td>
                      <td className="px-2 py-1 text-right text-[var(--text-primary)]">{areaResult.positiveSum.toFixed(2)}</td>
                      <td className="px-2 py-1 text-right text-[var(--text-primary)]">{areaResult.negativeSum.toFixed(2)}</td>
                    </tr>
                  </tfoot>
                </table>
              </div>
              <div className="grid grid-cols-2 gap-2">
                <ResultCard label="Area (m²)" value={areaResult.areaSqm.toFixed(4)} accent />
                <ResultCard label="Area (ha)" value={areaResult.areaHa.toFixed(4)} accent />
                <ResultCard label="Perimeter (m)" value={areaResult.perimeter.toFixed(4)} />
                <ResultCard label="Arithmetic Check"
                  value={`${areaResult.arithmeticCheck.passed ? 'PASS ' : 'FAIL [x]'} (${areaResult.arithmeticCheck.diff.toFixed(6)} m²)`}
                  accent={areaResult.arithmeticCheck.passed} />
                <ResultCard label="Centroid E" value={areaResult.centroid.easting.toFixed(4)} />
                <ResultCard label="Centroid N" value={areaResult.centroid.northing.toFixed(4)} />
              </div>
            </div>
          )}

          {/* JOIN RESULTS */}
          {activeTab === 'join' && joinResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Join Table</h2>
              <div className="overflow-x-auto">
                <table className="min-w-[600px] w-full text-xs font-mono">
                  <thead>
                    <tr className="border-b border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">From</th>
                      <th className="px-2 py-1.5 text-left text-[var(--text-secondary)]">To</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">ΔE</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">ΔN</th>
                      <th className="px-2 py-1.5 text-right text-[var(--text-secondary)]">Dist (m)</th>
                      <th className="px-2 py-1.5 text-center text-[var(--text-secondary)]">WCB</th>
                      <th className="px-2 py-1.5 text-center text-[var(--text-secondary)]">Back Brg</th>
                    </tr>
                  </thead>
                  <tbody>
                    {joinResult.rows.map((row, i) => (
                      <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/20">
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.from}</td>
                        <td className="px-2 py-1 text-[var(--text-primary)]">{row.to}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.deltaE >= 0 ? '+' : ''}{row.deltaE.toFixed(4)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-secondary)]">{row.deltaN >= 0 ? '+' : ''}{row.deltaN.toFixed(4)}</td>
                        <td className="px-2 py-1 text-right text-[var(--text-primary)]">{row.distance.toFixed(4)}</td>
                        <td className="px-2 py-1 text-center text-[var(--accent)]">{row.wcbDMS}</td>
                        <td className="px-2 py-1 text-center text-[var(--text-secondary)]">{row.backBearingDMS}</td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="font-semibold border-t border-[var(--border-color)]">
                      <td colSpan={4} className="px-2 py-1 text-[var(--text-primary)]">Total Perimeter</td>
                      <td className="px-2 py-1 text-right text-[var(--accent)]">{joinResult.totalPerimeter.toFixed(4)}</td>
                      <td colSpan={2}></td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>
          )}

          {/* DIST-DIST RESULTS */}
          {activeTab === 'distDist' && ddResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Distance-Distance Intersection</h2>
              {ddResult.error && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{ddResult.error}</div>}
              <StepsDisplay steps={ddResult.steps} />
              {ddResult.hasSolution && ddResult.solutions.length > 1 && (
                <div className="flex gap-2">
                  <button onClick={() => setDdSel(0)} className={`px-3 py-1.5 rounded text-sm ${ddSel === 0 ? 'bg-[var(--accent)] text-white' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 1</button>
                  <button onClick={() => setDdSel(1)} className={`px-3 py-1.5 rounded text-sm ${ddSel === 1 ? 'bg-[var(--accent)] text-white' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 2</button>
                </div>
              )}
              {ddResult.hasSolution && (
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E (m)" value={ddResult.solutions[ddSel]?.easting.toFixed(4) ?? '-'} accent />
                  <ResultCard label="N (m)" value={ddResult.solutions[ddSel]?.northing.toFixed(4) ?? '-'} accent />
                </div>
              )}
            </div>
          )}

          {/* BEARING-DIST RESULTS */}
          {activeTab === 'bearingDist' && bdResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Bearing-Distance Intersection</h2>
              {bdResult.error && <div className="p-3 bg-red-900/30 border border-red-600 rounded text-red-400 text-sm">{bdResult.error}</div>}
              <StepsDisplay steps={bdResult.steps} />
              {bdResult.hasSolution && bdResult.solutions.length > 1 && (
                <div className="flex gap-2">
                  <button onClick={() => setBdSel(0)} className={`px-3 py-1.5 rounded text-sm ${bdSel === 0 ? 'bg-[var(--accent)] text-white' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 1</button>
                  <button onClick={() => setBdSel(1)} className={`px-3 py-1.5 rounded text-sm ${bdSel === 1 ? 'bg-[var(--accent)] text-white' : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]'}`}>Solution 2</button>
                </div>
              )}
              {bdResult.hasSolution && (
                <div className="grid grid-cols-2 gap-2">
                  <ResultCard label="E (m)" value={bdResult.solutions[bdSel]?.easting.toFixed(4) ?? '-'} accent />
                  <ResultCard label="N (m)" value={bdResult.solutions[bdSel]?.northing.toFixed(4) ?? '-'} accent />
                </div>
              )}
            </div>
          )}

          {/* ARC BOUNDARY RESULTS */}
          {activeTab === 'arcBoundary' && arcResult && (
            <div className="card p-4 space-y-4">
              <h2 className="font-semibold text-sm">Working — Arc Boundary</h2>
              <StepsDisplay steps={arcResult.steps} />
              <div className="grid grid-cols-2 gap-2">
                <ResultCard label="Center E (m)" value={arcResult.center.easting.toFixed(4)} />
                <ResultCard label="Center N (m)" value={arcResult.center.northing.toFixed(4)} />
                <ResultCard label="Arc Length" value={`${arcResult.arcLength.toFixed(4)} m`} accent />
                <ResultCard label="Chord Length" value={`${arcResult.chordLength.toFixed(4)} m`} />
                <ResultCard label="Subtended Angle" value={`${arcResult.subtendedAngle.toFixed(4)}°`} accent />
                <ResultCard label="Segment Area" value={`${arcResult.segmentArea.toFixed(4)} m²`} />
                <ResultCard label="Chord Bearing" value={arcResult.chordBearingDMS} />
                <ResultCard label="Arc Points" value={`${arcResult.points.length} pts`} />
              </div>
            </div>
          )}

          {!invResult && !polResult && !intResult && !resResult && !areaResult && !joinResult && !ddResult && !bdResult && !arcResult && (
            <div className="flex items-center justify-center h-64 border border-dashed border-[var(--border-color)] rounded">
              <p className="text-sm text-[var(--text-muted)]">Enter values and click Compute</p>
            </div>
          )}
        </div>
      </div>

      <div className="mt-4 text-center text-xs text-[var(--text-muted)]">
        Source: Ghilani &amp; Wolf, Elementary Surveying 16th Ed., Sections 10.3–10.7, 12.5 | N.N. Basak, Surveying and Levelling
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react';
import { Save, CheckCircle, TrendingUp, Layers, Target } from 'lucide-react';

interface AsBuiltPoint {
  id: string;
  name: string;
  designE: number;
  designN: number;
  designZ: number;
  asbuiltE: number;
  asbuiltN: number;
  asbuiltZ: number;
}

interface SettingOutPoint {
  id: string;
  name: string;
  stationE: number;
  stationN: number;
  stationZ: number;
  offsetE: number;
  offsetN: number;
  designE: number;
  designN: number;
  designZ: number;
}

const DEMO_ASBUILT: AsBuiltPoint[] = [
  { id: '1', name: 'FND-01', designE: 500100.000, designN: 9980100.000, designZ: 1250.000, asbuiltE: 500100.008, asbuiltN: 9980100.005, asbuiltZ: 1249.992 },
  { id: '2', name: 'FND-02', designE: 500110.000, designN: 9980100.000, designZ: 1250.000, asbuiltE: 500109.995, asbuiltN: 9980100.012, asbuiltZ: 1250.008 },
  { id: '3', name: 'FND-03', designE: 500110.000, designN: 9980110.000, designZ: 1250.000, asbuiltE: 500110.003, asbuiltN: 9980109.998, asbuiltZ: 1249.995 },
  { id: '4', name: 'FND-04', designE: 500100.000, designN: 9980110.000, designZ: 1250.000, asbuiltE: 500100.010, asbuiltN: 9980110.008, asbuiltZ: 1250.015 },
];

const DEMO_SETTINGOUT: SettingOutPoint[] = [
  { id: '1', name: 'S1', stationE: 500050.000, stationN: 9980050.000, stationZ: 1252.000, offsetE: 500100.000, offsetN: 9980100.000, designE: 500100.000, designN: 9980100.000, designZ: 1250.000 },
  { id: '2', name: 'S2', stationE: 500050.000, stationN: 9980050.000, stationZ: 1252.000, offsetE: 500110.000, offsetN: 9980100.000, designE: 500110.000, designN: 9980100.000, designZ: 1250.000 },
];

export default function ConstructionComputePanel({ projectId }: { projectId: string }) {
  const [activeTab, setActiveTab] = useState<'asbuilt' | 'settingout'>('asbuilt');
  const [asbuilt, setAsbuilt] = useState<AsBuiltPoint[]>(DEMO_ASBUILT);
  const [settingOut, setSettingOut] = useState<SettingOutPoint[]>(DEMO_SETTINGOUT);
  const [toleranceH, setToleranceH] = useState(0.020);
  const [toleranceV, setToleranceV] = useState(0.010);
  const [saved, setSaved] = useState(false);

  // As-built results
  const asbuiltResults = asbuilt.map(p => {
    const dE = p.asbuiltE - p.designE;
    const dN = p.asbuiltN - p.designN;
    const dZ = p.asbuiltZ - p.designZ;
    const horiz = Math.sqrt(dE * dE + dN * dN);
    const total3D = Math.sqrt(dE * dE + dN * dN + dZ * dZ);
    const hPass = horiz <= toleranceH;
    const vPass = Math.abs(dZ) <= toleranceV;
    return { ...p, dE, dN, dZ, horiz, total3D, hPass, vPass, pass: hPass && vPass };
  });

  const failCount = asbuiltResults.filter(r => !r.pass).length;

  // Setting-out results
  const settingOutResults = settingOut.map(p => {
    const dE = p.offsetE - p.stationE;
    const dN = p.offsetN - p.stationN;
    const distance = Math.sqrt(dE * dE + dN * dN);
    const bearing = (Math.atan2(dE, dN) * 180) / Math.PI;
    const bearingNorm = bearing < 0 ? bearing + 360 : bearing;
    const dZ = p.designZ - p.stationZ;
    return { ...p, distance, bearing: bearingNorm, dZ, horizDist: distance };
  });

  const updateAsbuilt = (id: string, field: keyof AsBuiltPoint, value: number) => {
    setAsbuilt(prev => prev.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'construction',
          results: activeTab === 'asbuilt'
            ? { asbuiltResults, failCount }
            : { settingOutResults },
        }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold"><TrendingUp className="w-4 h-4 inline mr-1" />Construction Computations</h3>
        <div className="flex gap-2">
          {(['asbuilt', 'settingout'] as const).map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)}
              className={`px-3 py-1 rounded text-xs font-medium ${activeTab === tab ? 'bg-amber-500/20 border border-amber-500 text-amber-400' : 'border border-zinc-700 text-zinc-400'}`}>
              {tab === 'asbuilt' ? <Layers className="w-3 h-3 inline mr-1" /> : <Target className="w-3 h-3 inline mr-1" />}
              {tab === 'asbuilt' ? 'As-Built Check' : 'Setting-Out'}
            </button>
          ))}
        </div>
      </div>

      {activeTab === 'asbuilt' && (
        <>
          <div className="flex gap-4 text-xs">
            <div><label className="text-zinc-500" htmlFor="h-tol">H Tol:</label> <input id="h-tol" aria-label="H Tol:" type="number" step="0.001" value={toleranceH} onChange={e => setToleranceH(Number(e.target.value))} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" />m</div>
            <div><label className="text-zinc-500" htmlFor="v-tol">V Tol:</label> <input aria-label="V Tol:" type="number" step="0.001" value={toleranceV} onChange={e => setToleranceV(Number(e.target.value))} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" />m</div>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
            <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
              <div className="text-xs text-zinc-500">Points</div>
              <div className="text-sm font-bold text-white">{asbuilt.length}</div>
            </div>
            <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
              <div className="text-xs text-zinc-500">Max Offset</div>
              <div className="text-sm font-bold text-red-400">{Math.max(...asbuiltResults.map(r => r.horiz)).toFixed(4)} m</div>
            </div>
            <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
              <div className="text-xs text-zinc-500">Max ΔZ</div>
              <div className="text-sm font-bold text-blue-400">{Math.max(...asbuiltResults.map(r => Math.abs(r.dZ))).toFixed(4)} m</div>
            </div>
            <div className={`p-2 rounded border text-center ${failCount === 0 ? 'bg-green-500/10 border-green-500/30' : 'bg-red-500/10 border-red-500/30'}`}>
              <div className="text-xs text-zinc-500">Failures</div>
              <div className={`text-sm font-bold ${failCount === 0 ? 'text-green-400' : 'text-red-400'}`}>{failCount}</div>
            </div>
          </div>

          <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-zinc-700 bg-zinc-800/50">
                  <th className="px-2 py-1.5 text-left text-zinc-400">Name</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">dE</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">dN</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">dZ</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">Horiz</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">H</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">V</th>
                  <th className="px-2 py-1.5 text-left text-zinc-400">Status</th>
                </tr>
              </thead>
              <tbody>
                {asbuiltResults.map(r => (
                  <tr key={r.id} className={`border-b border-zinc-800 ${!r.pass ? 'bg-red-500/5' : ''}`}>
                    <td className="px-2 py-1 font-mono font-semibold">{r.name}</td>
                    <td className="px-2 py-1 font-mono">{r.dE >= 0 ? '+' : ''}{r.dE.toFixed(4)}</td>
                    <td className="px-2 py-1 font-mono">{r.dN >= 0 ? '+' : ''}{r.dN.toFixed(4)}</td>
                    <td className="px-2 py-1 font-mono">{r.dZ >= 0 ? '+' : ''}{r.dZ.toFixed(4)}</td>
                    <td className="px-2 py-1 font-mono font-semibold">{r.horiz.toFixed(4)}</td>
                    <td className="px-2 py-1">{r.hPass ? <span className="text-green-400">OK</span> : <span className="text-red-400">FAIL</span>}</td>
                    <td className="px-2 py-1">{r.vPass ? <span className="text-green-400">OK</span> : <span className="text-red-400">FAIL</span>}</td>
                    <td className="px-2 py-1">{r.pass ? <span className="text-green-400 font-semibold">PASS</span> : <span className="text-red-400 font-semibold">FAIL</span>}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {activeTab === 'settingout' && (
        <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-zinc-700 bg-zinc-800/50">
                <th className="px-2 py-1.5 text-left text-zinc-400">Point</th>
                <th className="px-2 py-1.5 text-left text-zinc-400">Distance</th>
                <th className="px-2 py-1.5 text-left text-zinc-400">Bearing</th>
                <th className="px-2 py-1.5 text-left text-zinc-400">ΔZ</th>
                <th className="px-2 py-1.5 text-left text-zinc-400">Vertical Angle</th>
              </tr>
            </thead>
            <tbody>
              {settingOutResults.map(r => {
                const vAngle = (Math.atan2(r.dZ, r.distance) * 180) / Math.PI;
                return (
                  <tr key={r.id} className="border-b border-zinc-800">
                    <td className="px-2 py-1 font-mono font-semibold">{r.name}</td>
                    <td className="px-2 py-1 font-mono text-amber-400">{r.distance.toFixed(3)} m</td>
                    <td className="px-2 py-1 font-mono text-blue-400">{r.bearing.toFixed(3)}°</td>
                    <td className="px-2 py-1 font-mono">{r.dZ >= 0 ? '+' : ''}{r.dZ.toFixed(3)} m</td>
                    <td className="px-2 py-1 font-mono">{vAngle.toFixed(4)}°</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      <button onClick={handleSave} disabled={saved} className="inline-flex items-center gap-1 px-3 py-1 bg-[var(--accent)] text-white text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}{saved ? 'Saved' : 'Save'}
      </button>
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { Plane, Save, CheckCircle, BarChart3 } from 'lucide-react';

interface GCPResult {
  name: string;
  dE: number;
  dN: number;
  dZ: number;
  horizontal: number;
  total3D: number;
}

interface GCPInput {
  id: string;
  name: string;
  knownE: number;
  knownN: number;
  knownZ: number;
  measE: number;
  measN: number;
  measZ: number;
}

const DEMO_GCPS: GCPInput[] = [
  { id: '1', name: 'GCP-01', knownE: 500000.123, knownN: 9980000.456, knownZ: 1520.10, measE: 500000.138, measN: 9980000.441, measZ: 1520.15 },
  { id: '2', name: 'GCP-02', knownE: 500010.789, knownN: 9980010.012, knownZ: 1518.35, measE: 500010.775, measN: 9980010.028, measZ: 1518.32 },
  { id: '3', name: 'GCP-03', knownE: 500025.456, knownN: 9979995.678, knownZ: 1522.80, measE: 500025.470, measN: 9979995.663, measZ: 1522.85 },
];

export default function DroneComputePanel({ projectId }: { projectId: string }) {
  const [gcps, setGcps] = useState<GCPInput[]>(DEMO_GCPS);
  const [gridPoints, setGridPoints] = useState('0,0,1.2\n5,0,1.5\n10,0,1.3\n0,5,1.4\n5,5,1.8\n10,5,1.6');
  const [refPlane, setRefPlane] = useState(1.0);
  const [saved, setSaved] = useState(false);

  const residuals = useMemo(() => gcps.map(g => {
    const dE = g.measE - g.knownE;
    const dN = g.measN - g.knownN;
    const dZ = g.measZ - g.knownZ;
    const horiz = Math.sqrt(dE * dE + dN * dN);
    const total3D = Math.sqrt(dE * dE + dN * dN + dZ * dZ);
    return { name: g.name, dE, dN, dZ, horizontal: horiz, total3D };
  }), [gcps]);

  const n = residuals.length || 1;
  const hRMSE = Math.sqrt(residuals.reduce((s, r) => s + r.horizontal ** 2, 0) / n);
  const vRMSE = Math.sqrt(residuals.reduce((s, r) => s + r.dZ ** 2, 0) / n);
  const totalRMSE = Math.sqrt(residuals.reduce((s, r) => s + r.total3D ** 2, 0) / n);

  // Volume
  const volume = useMemo(() => {
    const lines = gridPoints.trim().split('\n').filter(l => l.trim());
    const pts = lines.map(l => l.split(',').map(Number)).filter(p => !p.some(isNaN));
    if (pts.length < 4) return null;
    const uniqueX = Array.from(new Set(pts.map(p => p[0]))).sort((a, b) => a - b);
    const uniqueY = Array.from(new Set(pts.map(p => p[1]))).sort((a, b) => a - b);
    const grid = new Map(pts.map(p => [`${p[0]},${p[1]}`, p]));
    let vol = 0;
    for (let i = 0; i < uniqueX.length - 1; i++) {
      for (let j = 0; j < uniqueY.length - 1; j++) {
        const c = [grid.get(`${uniqueX[i]},${uniqueY[j]}`), grid.get(`${uniqueX[i+1]},${uniqueY[j]}`), grid.get(`${uniqueX[i+1]},${uniqueY[j+1]}`), grid.get(`${uniqueX[i]},${uniqueY[j+1]}`)];
        if (c.every(Boolean)) {
          const cellArea = Math.abs(uniqueX[i+1] - uniqueX[i]) * Math.abs(uniqueY[j+1] - uniqueY[j]);
          const avgH = c.reduce((s, p) => s + Math.max(p![2] - refPlane, 0), 0) / 4;
          vol += avgH * cellArea;
        }
      }
    }
    return vol;
  }, [gridPoints, refPlane]);

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'drone', results: { residuals, hRMSE, vRMSE, totalRMSE, volume } }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="space-y-4">
      <h3 className="text-sm font-semibold"><Plane className="w-4 h-4 inline mr-1" />Drone Survey QA</h3>

      {/* RMSE Stats */}
      <div className="grid grid-cols-3 gap-2">
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">H RMSE</div>
          <div className="text-sm font-bold text-amber-400">{hRMSE.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">V RMSE</div>
          <div className="text-sm font-bold text-blue-400">{vRMSE.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">3D RMSE</div>
          <div className="text-sm font-bold text-white">{totalRMSE.toFixed(4)} m</div>
        </div>
      </div>

      {/* GCP Table */}
      <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-zinc-700 bg-zinc-800/50">
              <th className="px-2 py-1.5 text-left text-zinc-400">Name</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dE</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dN</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dZ</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">H</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">3D</th>
            </tr>
          </thead>
          <tbody>
            {residuals.map((r, i) => (
              <tr key={r.name} className="border-b border-zinc-800">
                <td className="px-2 py-1 font-mono">{r.name}</td>
                <td className="px-2 py-1 font-mono">{r.dE >= 0 ? '+' : ''}{r.dE.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{r.dN >= 0 ? '+' : ''}{r.dN.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{r.dZ >= 0 ? '+' : ''}{r.dZ.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{r.horizontal.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono font-semibold text-amber-400">{r.total3D.toFixed(4)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Volume Section */}
      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-2">
          <label className="block text-xs text-zinc-500" htmlFor="grid-points-x-y-z-one-per-line">Grid Points (X,Y,Z) — one per line</label>
          <textarea value={gridPoints} onChange={e => setGridPoints(e.target.value)} rows={5} className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs font-mono" />
          <div className="flex gap-2 text-xs">
            <span className="text-zinc-500">Ref Plane:</span>
            <input aria-label="Grid Points (X,Y,Z) — one per line" type="number" step="0.1" value={refPlane} onChange={e => setRefPlane(Number(e.target.value))} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" />
          </div>
        </div>
        <div className="p-3 bg-zinc-900 rounded border border-zinc-700 h-fit">
          <h4 className="text-xs font-semibold text-zinc-400 mb-2"><BarChart3 className="w-3 h-3 inline mr-1" />Volume Result</h4>
          <div className="text-lg font-bold text-amber-400">{volume !== null ? `${volume.toFixed(2)} m³` : 'Need 4+ points'}</div>
        </div>
      </div>

      <button onClick={handleSave} disabled={saved} className="inline-flex items-center gap-1 px-3 py-1 bg-[var(--accent)] text-white text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}{saved ? 'Saved' : 'Save Results'}
      </button>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Wrench, Save, CheckCircle } from 'lucide-react';

/**
 * Engineering Compute Panel — wraps existing engineering sub-components.
 * Provides tabs for Horizontal Curves, Superelevation, and Volumes.
 */
export default function EngineeringComputePanel({ projectId }: { projectId: string }) {
  const [activeTab, setActiveTab] = useState<'curves' | 'superelev' | 'volumes'>('curves');
  const [saved, setSaved] = useState(false);

  // Horizontal Curve state
  const [radius, setRadius] = useState(300);
  const [deflection, setDeflection] = useState(45);
  const [designSpeed, setDesignSpeed] = useState(80);

  // Superelevation state
  const [curveRadius, setCurveRadius] = useState(250);
  const [speed] = useState(80);

  // Volumes state
  const [earthworkPoints, setEarthworkPoints] = useState('0,0,0,0\n5,0,-1.2,0.8\n10,0,-0.5,0.3\n15,0,0,0');

  // Compute horizontal curve
  const tangent = radius * Math.tan((deflection / 2) * Math.PI / 180);
  const curveLength = radius * (deflection * Math.PI / 180);
  const midOrdinate = radius * (1 - Math.cos((deflection / 2) * Math.PI / 180));
  const minRadius = (speed * speed) / (127 * 0.07);

  // Compute superelevation
  const e = (speed * speed) / (127 * curveRadius);
  const eMax = 0.07;
  const eActual = Math.min(e, eMax);

  // Compute volumes
  const volumeResult = (() => {
    const lines = earthworkPoints.trim().split('\n').filter(l => l.trim());
    const pts = lines.map(l => l.split(',').map(Number)).filter(p => !p.some(isNaN) && p.length >= 4);
    if (pts.length < 2) return null;
    let cut = 0, fill = 0;
    for (let i = 0; i < pts.length - 1; i++) {
      const avgCut = (Math.max(pts[i][2], 0) + Math.max(pts[i + 1][2], 0)) / 2;
      const avgFill = (Math.max(-pts[i][3], 0) + Math.max(-pts[i + 1][3], 0)) / 2;
      const dist = Math.abs(pts[i + 1][0] - pts[i][0]);
      cut += avgCut * dist;
      fill += avgFill * dist;
    }
    return { cut, fill, net: cut - fill };
  })();

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'engineering', results: { activeTab, radius, deflection, curveLength, tangent } }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold"><Wrench className="w-4 h-4 inline mr-1" />Engineering Computations</h3>
        <div className="flex gap-1">
          {([['curves', 'Curves'], ['superelev', 'Superelev.'], ['volumes', 'Volumes']] as const).map(([key, label]) => (
            <button key={key} onClick={() => setActiveTab(key)}
              className={`px-2 py-1 rounded text-xs font-medium ${activeTab === key ? 'bg-amber-500/20 border border-amber-500 text-amber-400' : 'border border-zinc-700 text-zinc-400'}`}>
              {label}
            </button>
          ))}
        </div>
      </div>

      {activeTab === 'curves' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-3">
            <div><label className="block text-xs text-zinc-500 mb-1" htmlFor="radius-m">Radius (m)</label><input id="radius-m" aria-label="Radius (m)" type="number" value={radius} onChange={e => setRadius(Number(e.target.value))} className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-1.5 text-white text-sm" /></div>
            <div><label className="block text-xs text-zinc-500 mb-1" htmlFor="deflection-angle">Deflection Angle (°)</label><input id="deflection-angle" aria-label="Deflection Angle (°)" type="number" value={deflection} onChange={e => setDeflection(Number(e.target.value))} className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-1.5 text-white text-sm" /></div>
            <div><label className="block text-xs text-zinc-500 mb-1" htmlFor="design-speed-km-h">Design Speed (km/h)</label><input id="design-speed-km-h" aria-label="Design Speed (km/h)" type="number" value={designSpeed} onChange={e => setDesignSpeed(Number(e.target.value))} className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-1.5 text-white text-sm" /></div>
          </div>
          <div className="p-4 bg-zinc-900 rounded border border-zinc-700">
            <h4 className="text-xs font-semibold text-zinc-400 mb-3">Curve Parameters</h4>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between"><span className="text-zinc-400">Tangent Length:</span><span className="text-white font-semibold">{tangent.toFixed(2)} m</span></div>
              <div className="flex justify-between"><span className="text-zinc-400">Curve Length:</span><span className="text-amber-400 font-semibold">{curveLength.toFixed(2)} m</span></div>
              <div className="flex justify-between"><span className="text-zinc-400">Mid-Ordinate:</span><span className="text-white">{midOrdinate.toFixed(2)} m</span></div>
              <div className="flex justify-between"><span className="text-zinc-400">Min Radius (v={designSpeed}):</span><span className={radius < minRadius ? 'text-red-400' : 'text-green-400'}>{minRadius.toFixed(0)} m {radius < minRadius ? '(TOO SMALL)' : '(OK)'}</span></div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'superelev' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-3">
            <div><label className="block text-xs text-zinc-500 mb-1" htmlFor="curve-radius-m">Curve Radius (m)</label><input id="curve-radius-m" aria-label="Curve Radius (m)" type="number" value={curveRadius} onChange={e => setCurveRadius(Number(e.target.value))} className="w-full bg-zinc-800 border border-zinc-700 rounded px-3 py-1.5 text-white text-sm" /></div>
            <div><div className="block text-xs text-zinc-500 mb-1">Speed (km/h)</div><div className="bg-zinc-800 border border-zinc-700 rounded px-3 py-1.5 text-white text-sm">{speed}</div></div>
          </div>
          <div className="p-4 bg-zinc-900 rounded border border-zinc-700">
            <h4 className="text-xs font-semibold text-zinc-400 mb-3">Superelevation</h4>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between"><span className="text-zinc-400">Required e:</span><span className="text-white font-semibold">{(e * 100).toFixed(2)}%</span></div>
              <div className="flex justify-between"><span className="text-zinc-400">Actual e (max 7%):</span><span className="text-amber-400 font-semibold">{(eActual * 100).toFixed(2)}%</span></div>
              <div className="flex justify-between"><span className="text-zinc-400">Cant (mm):</span><span className="text-white">{(eActual * 1000).toFixed(0)} mm</span></div>
              <div className="flex justify-between"><span className="text-zinc-400">Transition Length (L):</span><span className="text-white">{((eActual * speed * speed) / 3.6).toFixed(1)} m</span></div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'volumes' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs text-zinc-500 mb-1" htmlFor="section-data-chainage-cut-fill-existing">Section Data (chainage, cut, fill, existing)</label>
            <textarea value={earthworkPoints} onChange={e => setEarthworkPoints(e.target.value)} rows={6} className="w-full bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs font-mono" />
          </div>
          <div className="p-4 bg-zinc-900 rounded border border-zinc-700 h-fit">
            <h4 className="text-xs font-semibold text-zinc-400 mb-3">Earthwork Summary</h4>
            {volumeResult ? (
              <div className="space-y-2 text-sm">
                <div className="flex justify-between"><span className="text-zinc-400">Cut:</span><span className="text-red-400 font-semibold">{volumeResult.cut.toFixed(1)} m³</span></div>
                <div className="flex justify-between"><span className="text-zinc-400">Fill:</span><span className="text-green-400 font-semibold">{volumeResult.fill.toFixed(1)} m³</span></div>
                <div className="flex justify-between"><span className="text-zinc-400">Net:</span><span className={`font-semibold ${volumeResult.net >= 0 ? 'text-red-400' : 'text-green-400'}`}>{volumeResult.net >= 0 ? '+' : ''}{volumeResult.net.toFixed(1)} m³</span></div>
              </div>
            ) : <p className="text-xs text-zinc-500">Enter valid section data</p>}
          </div>
        </div>
      )}

      <button onClick={handleSave} disabled={saved} className="inline-flex items-center gap-1 px-3 py-1 bg-[var(--accent)] text-white text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}{saved ? 'Saved' : 'Save'}
      </button>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { Calculator, Loader2, Save, CheckCircle } from 'lucide-react';

interface FieldBookRow {
  fromStation: string;
  toStation: string;
  angle?: string;
  bearing?: number;
  distance?: number;
  bs?: number;
  is?: number;
  fs?: number;
}

interface LevelRow {
  id: number;
  fromStation: string;
  bs: number | null;
  is: number | null;
  fs: number | null;
  distance: number;
  rise?: number;
  fall?: number;
  rl?: number;
  adjustment?: number;
  adjRL?: number;
}

export default function LevellingComputePanel({ projectId }: { projectId: string }) {
  const [rows, setRows] = useState<LevelRow[]>([
    { id: 1, fromStation: 'TBM1', bs: 1.525, is: null, fs: null, distance: 0.050 },
    { id: 2, fromStation: 'CP1', bs: 2.310, is: 1.845, fs: null, distance: 0.030 },
    { id: 3, fromStation: 'CP1', bs: null, is: 1.925, fs: null, distance: 0.030 },
    { id: 4, fromStation: 'A', bs: null, is: null, fs: 0.655, distance: 0.040 },
    { id: 5, fromStation: 'A', bs: 1.780, is: null, fs: null, distance: 0.030 },
    { id: 6, fromStation: 'B', bs: null, is: 2.150, fs: null, distance: 0.035 },
    { id: 7, fromStation: 'TBM1', bs: null, is: null, fs: 3.420, distance: 0.045 },
  ]);
  const [tbmRL, setTbmRL] = useState<number>(150.000);
  const [saved, setSaved] = useState(false);

  const compute = useCallback(() => {
    let cumulativeRL = tbmRL;
    return rows.map((row, i) => {
      const rise = row.bs !== null && i > 0 ? null : null; // computed differently
      let rise2 = 0, fall2 = 0;

      if (row.bs !== null) {
        // BS reading: rise from previous to this
        const prevFS = rows[i - 1]?.fs;
        if (prevFS !== null && prevFS !== undefined) {
          if (row.bs > prevFS) rise2 = row.bs - prevFS;
          else fall2 = prevFS - row.bs;
        }
      }
      if (row.fs !== null && row.bs === null) {
        // FS reading on same station or IS→FS transition
        const prevBS = rows[i - 1]?.bs;
        const prevIS = rows[i - 1]?.is;
        if (prevIS !== null && prevIS !== undefined) {
          if (prevIS > row.fs) rise2 = prevIS - row.fs;
          else fall2 = row.fs - prevIS;
        }
      }
      if (row.is !== null && row.bs === null && row.fs === null) {
        const prev = rows[i - 1];
        const prevVal = prev?.is || prev?.bs;
        if (prevVal !== null && prevVal !== undefined) {
          if (prevVal > row.is) rise2 = prevVal - row.is;
          else fall2 = row.is - prevVal;
        }
      }

      const rl = cumulativeRL + rise2 - fall2;
      cumulativeRL = rl;

      return { ...row, rise: rise2 || 0, fall: fall2 || 0, rl };
    });
  }, [rows, tbmRL]);

  const computedRows = compute();
  const lastRow = computedRows[computedRows.length - 1];
  const misclosure = lastRow ? (lastRow.rl || 0) - tbmRL : 0;
  const totalDistance = rows.reduce((s, r) => s + r.distance, 0);
  const allowableMisclosure = 10 * Math.sqrt(totalDistance * 1000) / 1000; // 10√K mm → m
  const passesCheck = Math.abs(misclosure) <= allowableMisclosure;

  // Distribute adjustment proportionally
  const adjustedRows = computedRows.map((row, i) => {
    const proportion = totalDistance > 0 ? (row.distance / totalDistance) : 0;
    const adjustment = -misclosure * proportion;
    return { ...row, adjustment, adjRL: (row.rl || 0) + adjustment };
  });

  const updateRow = (id: number, field: keyof LevelRow, value: number | null) => {
    setRows(prev => prev.map(r => r.id === id ? { ...r, [field]: value } : r));
  };

  const addRow = () => {
    setRows(prev => [...prev, { id: prev.length + 1, fromStation: `P${prev.length + 1}`, bs: null, is: null, fs: null, distance: 0.030 }]);
  };

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'levelling',
          results: { rows: adjustedRows, misclosure, allowableMisclosure, passesCheck, tbmRL },
        }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-sm font-semibold"><Calculator className="w-4 h-4 inline mr-1" />Rise & Fall Levelling</h3>
        <div className="flex gap-2">
          <div className="text-xs">
            <label className="text-zinc-500 mr-1" htmlFor="tbm-rl">TBM RL:</label>
            <input aria-label="TBM RL:" type="number" step="0.001" value={tbmRL} onChange={e => setTbmRL(Number(e.target.value))} className="w-24 bg-zinc-800 border border-zinc-700 rounded px-2 py-0.5 text-white text-xs" />
          </div>
          <button onClick={addRow} className="px-2 py-0.5 text-xs bg-zinc-800 border border-zinc-700 rounded text-zinc-400 hover:text-white">+ Row</button>
        </div>
      </div>

      <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-zinc-700 bg-zinc-800/50">
              <th className="px-2 py-1.5 text-left text-zinc-400">Station</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">BS</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">IS</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">FS</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Rise</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Fall</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">RL</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Dist (km)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Adj</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Adj RL</th>
            </tr>
          </thead>
          <tbody>
            {adjustedRows.map(r => (
              <tr key={r.id} className="border-b border-zinc-800">
                <td className="px-2 py-1 font-mono text-zinc-300">{r.fromStation}</td>
                <td className="px-2 py-1"><input aria-label="Bs" type="number" step="0.001" value={r.bs ?? ''} onChange={e => updateRow(r.id, 'bs', e.target.value ? Number(e.target.value) : null)} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1"><input aria-label="Is" type="number" step="0.001" value={r.is ?? ''} onChange={e => updateRow(r.id, 'is', e.target.value ? Number(e.target.value) : null)} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1"><input aria-label="Fs" type="number" step="0.001" value={r.fs ?? ''} onChange={e => updateRow(r.id, 'fs', e.target.value ? Number(e.target.value) : null)} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1 font-mono">{r.rise ? r.rise.toFixed(3) : ''}</td>
                <td className="px-2 py-1 font-mono">{r.fall ? r.fall.toFixed(3) : ''}</td>
                <td className="px-2 py-1 font-mono text-white">{(r.rl ?? 0).toFixed(3)}</td>
                <td className="px-2 py-1"><input aria-label="Distance" type="number" step="0.001" value={r.distance} onChange={e => updateRow(r.id, 'distance', Number(e.target.value))} className="w-16 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1 font-mono text-blue-400">{(r.adjustment ?? 0).toFixed(4)}</td>
                <td className="px-2 py-1 font-mono font-semibold text-amber-400">{(r.adjRL ?? 0).toFixed(3)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Summary */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className={`p-3 rounded-lg border ${passesCheck ? 'bg-green-500/10 border-green-500/30' : 'bg-red-500/10 border-red-500/30'}`}>
          <div className="text-xs text-zinc-500">Misclosure</div>
          <div className={`text-sm font-bold ${passesCheck ? 'text-green-400' : 'text-red-400'}`}>{misclosure >= 0 ? '+' : ''}{misclosure.toFixed(4)} m</div>
        </div>
        <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700">
          <div className="text-xs text-zinc-500">Allowable (10√K)</div>
          <div className="text-sm font-bold text-white">{allowableMisclosure.toFixed(4)} m</div>
        </div>
        <div className="p-3 bg-zinc-900 rounded-lg border border-zinc-700">
          <div className="text-xs text-zinc-500">Total Distance</div>
          <div className="text-sm font-bold text-white">{(totalDistance * 1000).toFixed(0)} m</div>
        </div>
        <div className={`p-3 rounded-lg border ${passesCheck ? 'bg-green-500/10 border-green-500/30' : 'bg-red-500/10 border-red-500/30'}`}>
          <div className="text-xs text-zinc-500">Result</div>
          <div className={`text-sm font-bold ${passesCheck ? 'text-green-400' : 'text-red-400'}`}>{passesCheck ? 'PASS' : 'FAIL'}</div>
        </div>
      </div>

      <button onClick={handleSave} disabled={saved}
        className="inline-flex items-center gap-1 px-3 py-1.5 bg-[var(--accent)] text-white text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}
        {saved ? 'Saved' : 'Save Results'}
      </button>
    </div>
  );
}

'use client';

import { useState, useMemo } from 'react';
import { BarChart3, AlertTriangle, Save, CheckCircle } from 'lucide-react';

interface EpochPoint {
  name: string;
  easting: number;
  northing: number;
  elevation: number;
}

interface EpochData {
  epochName: string;
  date: string;
  points: EpochPoint[];
}

interface Displacement {
  name: string;
  dE: number;
  dN: number;
  dZ: number;
  horizontal: number;
  total3D: number;
  bearing: number;
  exceedsThreshold: boolean;
}

function computeDisplacements(epoch1: EpochPoint[], epoch2: EpochPoint[]): Displacement[] {
  const map2 = new Map(epoch2.map(p => [p.name, p]));
  return epoch1.map(p1 => {
    const p2 = map2.get(p1.name);
    if (!p2) return null;
    const dE = p2.easting - p1.easting;
    const dN = p2.northing - p1.northing;
    const dZ = p2.elevation - p1.elevation;
    const horizontal = Math.sqrt(dE * dE + dN * dN);
    const total3D = Math.sqrt(dE * dE + dN * dN + dZ * dZ);
    const bearing = (Math.atan2(dE, dN) * 180) / Math.PI;
    const bearingNorm = bearing < 0 ? bearing + 360 : bearing;
    return { name: p1.name, dE, dN, dZ, horizontal, total3D, bearing: bearingNorm, exceedsThreshold: false };
  }).filter(Boolean) as Displacement[];
}

const DEMO_EPOCH1: EpochPoint[] = [
  { name: 'P1', easting: 500000.000, northing: 9980000.000, elevation: 1520.000 },
  { name: 'P2', easting: 500010.000, northing: 9980010.000, elevation: 1518.500 },
  { name: 'P3', easting: 500025.000, northing: 9979995.000, elevation: 1522.800 },
  { name: 'P4', easting: 500015.000, northing: 9979985.000, elevation: 1515.900 },
  { name: 'P5', easting: 500035.000, northing: 9980005.000, elevation: 1519.550 },
];

const DEMO_EPOCH2: EpochPoint[] = [
  { name: 'P1', easting: 500000.005, northing: 9980000.003, elevation: 1520.008 },
  { name: 'P2', easting: 500010.012, northing: 9980009.995, elevation: 1518.502 },
  { name: 'P3', easting: 500024.995, northing: 9979995.010, elevation: 1522.805 },
  { name: 'P4', easting: 500015.008, northing: 9979985.002, elevation: 1515.895 },
  { name: 'P5', easting: 500035.003, northing: 9980005.006, elevation: 1519.558 },
];

export default function MonitoringComputePanel({ projectId }: { projectId: string }) {
  const [epochs, setEpochs] = useState<EpochData[]>([
    { epochName: 'Epoch 1', date: '2025-01-15', points: DEMO_EPOCH1 },
    { epochName: 'Epoch 2', date: '2025-06-15', points: DEMO_EPOCH2 },
  ]);
  const [compareIndex1, setCompareIndex1] = useState(0);
  const [compareIndex2, setCompareIndex2] = useState(1);
  const [threshold, setThreshold] = useState(0.010);
  const [saved, setSaved] = useState(false);

  const displacements = useMemo(() => {
    if (compareIndex1 === compareIndex2 || !epochs[compareIndex1] || !epochs[compareIndex2]) return [];
    const ds = computeDisplacements(epochs[compareIndex1].points, epochs[compareIndex2].points);
    return ds.map(d => ({ ...d, exceedsThreshold: d.total3D > threshold }));
  }, [epochs, compareIndex1, compareIndex2, threshold]);

  const alertCount = displacements.filter(d => d.exceedsThreshold).length;

  const maxDisp = displacements.length > 0 ? Math.max(...displacements.map(d => d.total3D)) : 0;
  const avgDisp = displacements.length > 0 ? displacements.reduce((s, d) => s + d.total3D, 0) / displacements.length : 0;
  const rmsH = Math.sqrt(displacements.reduce((s, d) => s + d.horizontal ** 2, 0) / (displacements.length || 1));
  const rmsV = Math.sqrt(displacements.reduce((s, d) => s + d.dZ ** 2, 0) / (displacements.length || 1));

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'monitoring', results: { displacements, rmsH, rmsV, maxDisp, avgDisp, alertCount } }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="space-y-4">
      <h3 className="text-sm font-semibold"><BarChart3 className="w-4 h-4 inline mr-1" />Multi-Epoch Displacement Monitoring</h3>

      {/* Controls */}
      <div className="flex gap-4 items-end flex-wrap">
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="base-epoch">Base Epoch</label>
          <select id="base-epoch" value={compareIndex1} onChange={e => setCompareIndex1(Number(e.target.value))} className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs">
            {epochs.map((ep, i) => <option key={`${ep}-${i}`} value={i}>{ep.epochName} ({ep.date})</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="latest-epoch">Latest Epoch</label>
          <select id="latest-epoch" value={compareIndex2} onChange={e => setCompareIndex2(Number(e.target.value))} className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs">
            {epochs.map((ep, i) => <option key={`${ep}-${i}`} value={i}>{ep.epochName} ({ep.date})</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs text-zinc-500 mb-1" htmlFor="alert-threshold-m">Alert Threshold (m)</label>
          <input aria-label="Alert Threshold (m)" type="number" step="0.001" value={threshold} onChange={e => setThreshold(Number(e.target.value))} className="w-24 bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white text-xs" />
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Points</div>
          <div className="text-sm font-bold text-white">{displacements.length}</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Max 3D</div>
          <div className="text-sm font-bold text-red-400">{maxDisp.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Avg 3D</div>
          <div className="text-sm font-bold text-amber-400">{avgDisp.toFixed(4)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">RMS H</div>
          <div className="text-sm font-bold text-blue-400">{rmsH.toFixed(4)} m</div>
        </div>
        <div className={`p-2 rounded border text-center ${alertCount > 0 ? 'bg-red-500/10 border-red-500/30' : 'bg-green-500/10 border-green-500/30'}`}>
          <div className="text-xs text-zinc-500">Alerts</div>
          <div className={`text-sm font-bold ${alertCount > 0 ? 'text-red-400' : 'text-green-400'}`}>{alertCount}</div>
        </div>
      </div>

      {/* Displacement Table */}
      <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-zinc-700 bg-zinc-800/50">
              <th className="px-2 py-1.5 text-left text-zinc-400">Point</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dE (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dN (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">dZ (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Horiz (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">3D (m)</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Bearing</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Status</th>
            </tr>
          </thead>
          <tbody>
            {displacements.map(d => (
              <tr key={d.name} className={`border-b border-zinc-800 ${d.exceedsThreshold ? 'bg-red-500/5' : ''}`}>
                <td className="px-2 py-1 font-mono font-semibold">{d.name}</td>
                <td className="px-2 py-1 font-mono">{d.dE >= 0 ? '+' : ''}{d.dE.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.dN >= 0 ? '+' : ''}{d.dN.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.dZ >= 0 ? '+' : ''}{d.dZ.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.horizontal.toFixed(4)}</td>
                <td className={`px-2 py-1 font-mono font-semibold ${d.exceedsThreshold ? 'text-red-400' : 'text-white'}`}>{d.total3D.toFixed(4)}</td>
                <td className="px-2 py-1 font-mono">{d.bearing.toFixed(1)}°</td>
                <td className="px-2 py-1">
                  {d.exceedsThreshold ? (
                    <span className="flex items-center gap-1 text-red-400"><AlertTriangle className="w-3 h-3" />ALERT</span>
                  ) : (
                    <span className="text-green-400">OK</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <button onClick={handleSave} disabled={saved}
        className="inline-flex items-center gap-1 px-3 py-1.5 bg-[var(--accent)] text-white text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
        {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}
        {saved ? 'Saved' : 'Save Results'}
      </button>
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react'
import { AlertTriangle, CheckCircle2, ShieldAlert, Zap, Compass, Folder, Lock } from 'lucide-react'
import { adjustNetwork, Station, Observation, AdjustmentResult } from '@/lib/survey/networkAdjustment'
import { adjustNetworkRobust, type RobustLSAResult, type WeightFunction } from '@/lib/survey/robustEstimation'
import { generateNetworkDXF } from '@/lib/survey/networkAdjustmentDXF'
import { ErrorEllipseCanvas } from './ErrorEllipseCanvas'
import { z } from 'zod'
import { apiGet, apiPost, ApiError } from '@/lib/api/client'

// ─── API response schemas (Zod) ────────────────────────────────────────────
const traverseImportResponseSchema = z.object({
  coordinates: z.array(z.object({}).passthrough()).optional(),
  legs: z.array(z.object({}).passthrough()).optional(),
}).passthrough()

const networkAdjustmentSaveResponseSchema = z.object({
  ok: z.boolean().optional(),
}).passthrough()

interface Props {
  projectId: string
  projectData: Record<string, unknown>
  surveyorProfile?: { fullName: string; registrationNumber: string; firmName: string } | null
}

const EMPTY_STATION: Omit<Station, 'id'> = {
  name: '', easting: 0, northing: 0, elevation: 0, isFixed: false,
}

const EMPTY_OBS: Omit<Observation, 'from' | 'to'> = {
  deltaE: 0, deltaN: 0, deltaH: 0, stdDevE: 0.005, stdDevN: 0.005, stdDevH: 0.010,
}

export function NetworkAdjustmentPanel({ projectId, projectData, surveyorProfile }: Props) {
  const [stations, setStations] = useState<Station[]>([])
  const [observations, setObservations] = useState<Observation[]>([])
  const [result, setResult] = useState<AdjustmentResult | null>(null)
  const [robustResult, setRobustResult] = useState<RobustLSAResult | null>(null)
  const [robustMode, setRobustMode] = useState(false)
  const [weightFunction, setWeightFunction] = useState<WeightFunction>('huber')
  const [error, setError] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)
  const [importStatus, setImportStatus] = useState('')

  // ─── Import from Traverse ────────────────────────────────────────────────
  const handleImportFromTraverse = useCallback(async () => {
    try {
      setImportStatus('Loading traverse data...')
      const data = await apiGet(
        `/api/project/${projectId}/traverse`,
        traverseImportResponseSchema,
        { ttlMs: 0 },
      )
      const coords = (data.coordinates as unknown as Array<Record<string, unknown>>) || []
      const legs = (data.legs as unknown as Array<Record<string, unknown>>) || []

      if (coords.length < 2) {
        setImportStatus('')
        setError('Traverse has fewer than 2 stations.')
        return
      }

      // Convert traverse stations → LSQ stations
      const newStations: Station[] = coords.map((c, i: number) => ({
        id: `trv-${c.station}`,
        name: c.station as string,
        easting: c.easting as number,
        northing: c.northing as number,
        elevation: (c.rl as number) ?? 0,
        isFixed: i === 0 || i === coords.length - 1, // first and last are fixed
      }))

      // Convert traverse legs → LSQ observations
      const newObs: Observation[] = legs.map((leg) => {
        const fromStn = newStations.find((s: Station) => s.name === leg.from)
        const toStn = newStations.find((s: Station) => s.name === leg.to)
        if (!fromStn || !toStn) return null
        return {
          from: fromStn.id,
          to: toStn.id,
          deltaE: (leg.adjDep as number) ?? (leg.departure as number) ?? 0,
          deltaN: (leg.adjLat as number) ?? (leg.latitude as number) ?? 0,
          deltaH: 0,
          stdDevE: 0.005 + (leg.hd as number ?? 100) * 0.00001, stdDevN: 0.005 + (leg.hd as number ?? 100) * 0.00001, stdDevH: (0.005 + (leg.hd as number ?? 100) * 0.00001) * 2, // 5mm + 10ppm
        }
      }).filter(Boolean) as Observation[]

      setStations(newStations)
      setObservations(newObs)
      setResult(null)
      setError(null)
      setImportStatus(`Imported ${newStations.length} stations and ${newObs.length} observations from traverse.`)
      setTimeout(() => setImportStatus(''), 4000)
    } catch (err: unknown) {
      if (err instanceof ApiError) {
        // 404 / not-found → no traverse data yet; anything else → surface message
        setError(err.isNotFound
          ? 'No traverse data found for this project. Run a traverse computation first.'
          : err.message)
      } else {
        setError((err as Error).message ?? 'Failed to import traverse data.')
      }
      setImportStatus('')
    }
  }, [projectId])

  // ─── Import from GSI File ─────────────────────────────────────────────────
  const handleImportGSI = useCallback(async () => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = '.gsi,.GSI'
    input.onchange = async (e: any) => {
      const file = e.target.files?.[0]
      if (!file) return
      try {
        setImportStatus('Parsing GSI file...')
        const content = await file.text()
        const { parseGSI, pairFaces } = await import('@/lib/import/totalStation/parseGSI')
        const parsed = parseGSI(content)

        if (!parsed.ok || parsed.records.length === 0) {
          setError('GSI file parsed but no valid records found.')
          setImportStatus('')
          return
        }

        // Extract coordinate records as stations
        const coordRecords = parsed.records.filter(r => r.easting !== undefined && r.northing !== undefined)
        const obsRecords = parsed.records.filter(r => r.horizontalAngle !== undefined || r.slopeDistance !== undefined)

        if (coordRecords.length >= 2) {
          const newStations: Station[] = coordRecords.map((r, i) => ({
            id: `gsi-${r.pointId}`,
            name: r.pointId,
            easting: r.easting!,
            northing: r.northing!,
            elevation: r.elevation ?? 0,
            isFixed: i === 0,
          }))
          setStations(newStations)

          // Create observations from consecutive coordinate pairs
          const newObs: Observation[] = []
          for (let i = 0; i < newStations.length - 1; i++) {
            newObs.push({
              from: newStations[i].id,
              to: newStations[i + 1].id,
              deltaE: newStations[i + 1].easting - newStations[i].easting,
              deltaN: newStations[i + 1].northing - newStations[i].northing,
              deltaH: newStations[i + 1].elevation - newStations[i].elevation,
              stdDevE: 0.005, stdDevN: 0.005, stdDevH: 0.010,
            })
          }
          setObservations(newObs)
        }

        setResult(null)
        setError(null)
        setImportStatus(
          `GSI ${parsed.format}: ${parsed.statistics.totalRecords} records, ` +
          `${parsed.statistics.coordinateRecords} coords, ` +
          `${parsed.statistics.faceLeftCount} FL / ${parsed.statistics.faceRightCount} FR`
        )
        setTimeout(() => setImportStatus(''), 6000)
      } catch (err: unknown) {
        setError((err as Error).message ?? 'Failed to parse GSI file.')
        setImportStatus('')
      }
    }
    input.click()
  }, [])

  const addStation = () => {
    setStations(prev => [...prev, {
      ...EMPTY_STATION,
      id: `stn-${Date.now()}`,
    }])
  }

  const updateStation = (id: string, field: keyof Station, value: any) => {
    setStations(prev => prev.map(s => s.id === id ? { ...s, [field]: value } : s))
  }

  const removeStation = (id: string) => {
    setStations(prev => prev.filter(s => s.id !== id))
    setObservations(prev => prev.filter(o => o.from !== id && o.to !== id))
  }

  const addObservation = () => {
    if (stations.length < 2) return
    setObservations(prev => [...prev, {
      ...EMPTY_OBS,
      from: stations[0].id,
      to: stations[1].id,
    }])
  }

  const updateObservation = (idx: number, field: keyof Observation, value: any) => {
    setObservations(prev => prev.map((o, i) => i === idx ? { ...o, [field]: value } : o))
  }

  const removeObservation = (idx: number) => {
    setObservations(prev => prev.filter((_, i) => i !== idx))
  }

  const handleCompute = () => {
    setError(null)
    setResult(null)
    setRobustResult(null)
    try {
      if (robustMode) {
        // Convert Station/Observation to the format expected by adjustNetworkRobust
        const robustStations = stations.map(s => ({
          id: s.id, name: s.name,
          easting: s.easting, northing: s.northing, elevation: s.elevation,
          isFixed: s.isFixed,
        }))
        const robustObs = observations.map(o => ({
          type: 'coordinate_diff' as const,
          from: o.from, to: o.to,
          deltaE: o.deltaE, deltaN: o.deltaN, deltaH: o.deltaH,
          stdDevE: o.stdDevE, stdDevN: o.stdDevN, stdDevH: o.stdDevH,
        }))
        const res = adjustNetworkRobust(robustStations, robustObs, {
          weightFunction,
          maxIterations: 30,
        })
        setRobustResult(res)
        // Also set the standard result (for the adjusted coordinates table + error ellipses)
        setResult({
          adjustedStations: res.adjustedStations,
          sigmaZero: res.sigmaZero,
          degreesOfFreedom: res.degreesOfFreedom,
          iterations: res.iterations,
          passedTolerance: res.blunders.length === 0,
          warnings: [...res.warnings, ...res.blunders.map(b =>
            `BLUNDER: ${b.from || '?'}→${b.to || '?'} (${b.type}) — residual=${b.residual.toFixed(4)}m, weight=${b.finalWeight.toFixed(3)}`,
          )],
        })
        saveResult({
          adjustedStations: res.adjustedStations,
          sigmaZero: res.sigmaZero,
          degreesOfFreedom: res.degreesOfFreedom,
          iterations: res.iterations,
          passedTolerance: res.blunders.length === 0,
          warnings: res.warnings,
        })
      } else {
        const res = adjustNetwork(stations, observations)
        setResult(res)
        saveResult(res)
      }
    } catch (err: unknown) {
      setError((err as Error).message ?? 'Adjustment failed.')
    }
  }

  const saveResult = async (res: AdjustmentResult) => {
    setSaving(true)
    try {
      await apiPost(
        `/api/project/${projectId}/network-adjustment`,
        networkAdjustmentSaveResponseSchema,
        {
          stations,
          observations,
          adjusted_stations: res.adjustedStations,
          summary: {
            iterations: res.iterations,
            sigma_zero: res.sigmaZero,
            dof: res.degreesOfFreedom,
            passed_tolerance: res.passedTolerance,
          },
          status: res.passedTolerance ? 'adjusted' : 'failed',
        },
      )
    } catch {
      // non-fatal
    } finally {
      setSaving(false)
    }
  }

  const handleExportDXF = async () => {
    if (!result) return
    const profile = surveyorProfile ?? { fullName: 'Unknown', registrationNumber: 'N/A', firmName: 'N/A' }
    const dxfString = generateNetworkDXF({
      adjustedStations: result.adjustedStations,
      observations,
      projectData,
      surveyorProfile: profile,
    })
    const blob = new Blob([dxfString], { type: 'application/dxf' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `network-adjustment-${projectId}.dxf`
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-lg font-semibold text-white mb-1">GPS Network Adjustment</h2>
        <p className="text-sm text-zinc-400">
          Least squares adjustment of GPS/GNSS baselines. Arc 1960 / UTM Zone 37S.
          At least one fixed control station required.
        </p>
      </div>

      {importStatus && (
        <div className="bg-blue-900/30 border border-blue-700 text-blue-300 px-4 py-3 rounded-lg text-sm">
          {importStatus}
        </div>
      )}

      {/* Import Actions */}
      <div className="flex flex-wrap gap-2">
        <button
          onClick={handleImportFromTraverse}
          className="text-sm bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 font-medium flex items-center gap-1.5"
        >
          <Compass className="w-4 h-4" /> Import from Traverse
        </button>
        <button
          onClick={handleImportGSI}
          className="text-sm bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 font-medium flex items-center gap-1.5"
        >
          <Folder className="w-4 h-4" /> Import GSI File
        </button>
      </div>

      <section>
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-medium text-zinc-300">Control Stations</h3>
          <button
            onClick={addStation}
            className="text-sm bg-blue-600 text-white px-3 py-1.5 rounded hover:bg-blue-700"
          >
            + Add Station
          </button>
        </div>

        {stations.length === 0 && (
          <p className="text-sm text-zinc-500 italic">No stations added yet.</p>
        )}

        <div className="space-y-3">
          {stations.map(s => (
            <div key={s.id} className="grid grid-cols-7 gap-2 items-center bg-zinc-800 p-3 rounded-lg">
              <input
                className="col-span-1 bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="Name" placeholder="e.g. TBM1"
                value={s.name}
                onChange={e => updateStation(s.id, 'name', e.target.value)}
              />
              <input
                type="number" step="0.001"
                className="col-span-2 bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="Easting (m)" placeholder="e.g. 500000.000"
                value={s.easting || ''}
                onChange={e => updateStation(s.id, 'easting', parseFloat(e.target.value) || 0)}
              />
              <input
                type="number" step="0.001"
                className="col-span-2 bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="Northing (m)" placeholder="e.g. 9900000.000"
                value={s.northing || ''}
                onChange={e => updateStation(s.id, 'northing', parseFloat(e.target.value) || 0)}
              />
              <label className="flex items-center gap-1 text-sm text-zinc-300">
                <input aria-label="Isfixed"
                  type="checkbox"
                  checked={s.isFixed}
                  onChange={e => updateStation(s.id, 'isFixed', e.target.checked)}
                />
                Fixed
              </label>
              <button
                onClick={() => removeStation(s.id)}
                className="text-red-400 text-sm hover:underline"
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      </section>

      <section>
        <div className="flex items-center justify-between mb-3">
          <h3 className="font-medium text-zinc-300">Baseline Observations</h3>
          <button
            onClick={addObservation}
            disabled={stations.length < 2}
            className="text-sm bg-blue-600 text-white px-3 py-1.5 rounded hover:bg-blue-700 disabled:opacity-40"
          >
            + Add Baseline
          </button>
        </div>

        {observations.length === 0 && (
          <p className="text-sm text-zinc-500 italic">No baselines added yet.</p>
        )}

        <div className="space-y-3">
          {observations.map((obs, idx) => (
            <div key={`${obs}-${idx}`} className="grid grid-cols-7 gap-2 items-center bg-zinc-800 p-3 rounded-lg">
              <select
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                value={obs.from}
                onChange={e => updateObservation(idx, 'from', e.target.value)}
              >
                {stations.map(s => <option key={s.id} value={s.id}>{s.name || s.id}</option>)}
              </select>
              <select
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                value={obs.to}
                onChange={e => updateObservation(idx, 'to', e.target.value)}
              >
                {stations.map(s => <option key={s.id} value={s.id}>{s.name || s.id}</option>)}
              </select>
              <input
                type="number" step="0.001"
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="ΔE (m)" placeholder="e.g. 0.002"
                value={obs.deltaE || ''}
                onChange={e => updateObservation(idx, 'deltaE', parseFloat(e.target.value) || 0)}
              />
              <input
                type="number" step="0.001"
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="ΔN (m)" placeholder="e.g. 0.003"
                value={obs.deltaN || ''}
                onChange={e => updateObservation(idx, 'deltaN', parseFloat(e.target.value) || 0)}
              />
              <input
                type="number" step="0.001"
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="ΔH (m)" placeholder="e.g. 0.001"
                value={obs.deltaH || ''}
                onChange={e => updateObservation(idx, 'deltaH', parseFloat(e.target.value) || 0)}
              />
              <input
                type="number" step="0.0001"
                className="bg-zinc-700 border border-zinc-600 rounded px-2 py-1 text-sm text-white"
                aria-label="σ (m)" placeholder="e.g. 0.005"
                value={obs.stdDevE || ''}
                onChange={e => {
                  const v = parseFloat(e.target.value) || 0.005
                  updateObservation(idx, 'stdDevE', v)
                  updateObservation(idx, 'stdDevN', v)
                  updateObservation(idx, 'stdDevH', v * 2)
                }}
              />
              <button
                onClick={() => removeObservation(idx)}
                className="text-red-400 text-sm hover:underline"
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      </section>

      {/* Robust Estimation Controls */}
      <section className="bg-zinc-900/50 border border-zinc-700 rounded-lg p-4 space-y-3">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-medium text-white flex items-center gap-2">
              <ShieldAlert className="w-4 h-4 text-amber-400" />
              Robust Estimation (Blunder Detection)
            </h3>
            <p className="text-xs text-zinc-500 mt-1">
              Down-weights observations with large residuals using IRLS. Detects blunders that standard LSA misses.
            </p>
          </div>
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={robustMode}
              onChange={e => { setRobustMode(e.target.checked); setResult(null); setRobustResult(null) }}
              className="w-4 h-4 accent-green-600"
            />
            <span className="text-sm text-zinc-300">Enable Robust Mode</span>
          </label>
        </div>
        {robustMode && (
          <div className="flex items-center gap-4 text-sm">
            <label className="text-zinc-400" htmlFor="weight-function">Weight Function:</label>
            <select
              value={weightFunction}
              onChange={e => setWeightFunction(e.target.value as WeightFunction)}
              className="bg-zinc-800 border border-zinc-700 rounded px-2 py-1 text-white"
            >
              <option value="huber">Huber (gentle, 95% efficient)</option>
              <option value="igg3">IGG3 (Chinese standard, hard reject at 2.5σ)</option>
              <option value="tukey">Tukey Biweight (most aggressive)</option>
            </select>
          </div>
        )}
      </section>

      <div className="flex gap-3">
        <button
          onClick={handleCompute}
          disabled={stations.length < 2 || observations.length === 0}
          className="bg-green-600 text-white px-5 py-2 rounded-lg hover:bg-green-700 disabled:opacity-40 font-medium flex items-center gap-2"
        >
          {robustMode && <Zap className="w-4 h-4" />}
          {robustMode ? 'Run Robust Adjustment' : 'Run Adjustment'}
        </button>
        {result && (
          <button
            onClick={handleExportDXF}
            className="bg-gray-700 text-white px-5 py-2 rounded-lg hover:bg-gray-600 font-medium"
          >
            Export DXF
          </button>
        )}
      </div>

      {error && (
        <div className="bg-red-900/50 border border-red-700 text-red-300 px-4 py-3 rounded-lg text-sm">
          {error}
        </div>
      )}

      {result && (
        <section className="space-y-5">
          <div className={`p-4 rounded-lg border ${result.passedTolerance ? 'bg-green-900/30 border-green-700' : 'bg-amber-900/30 border-amber-700'}`}>
            <h3 className="font-semibold mb-2 text-white flex items-center gap-2">
              {result.passedTolerance
                ? <><CheckCircle2 className="w-4 h-4" /> Adjustment Passed</>
                : <><AlertTriangle className="w-4 h-4" /> Adjustment — Check Residuals</>
              }
            </h3>
            <div className="grid grid-cols-3 gap-4 text-sm text-zinc-300">
              <div><span className="text-zinc-500">σ₀ (ref std dev)</span><br /><strong>{result.sigmaZero.toFixed(4)}</strong></div>
              <div><span className="text-zinc-500">Degrees of freedom</span><br /><strong>{result.degreesOfFreedom}</strong></div>
              <div><span className="text-zinc-500">Iterations</span><br /><strong>{result.iterations}</strong></div>
            </div>
            {result.warnings.length > 0 && (
              <ul className="mt-3 text-sm text-amber-400 list-disc list-inside space-y-1">
                {result.warnings.map((w, i) => <li key={`${w}-${i}`}>{w}</li>)}
              </ul>
            )}
          </div>

          <div>
            <h3 className="font-medium text-zinc-300 mb-2">Adjusted Coordinates</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-sm border-collapse text-zinc-300">
                <thead>
                  <tr className="bg-zinc-800 text-left">
                    <th className="px-3 py-2 border border-zinc-700">Station</th>
                    <th className="px-3 py-2 border border-zinc-700">Easting (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Northing (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Residual E (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Residual N (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Semi-major (m)</th>
                    <th className="px-3 py-2 border border-zinc-700">Type</th>
                  </tr>
                </thead>
                <tbody>
                  {result.adjustedStations.map(s => (
                    <tr key={s.id} className="hover:bg-zinc-800/50">
                      <td className="px-3 py-2 border border-zinc-700 font-medium">{s.name || s.id}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.easting.toFixed(4)}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.northing.toFixed(4)}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.residualE.toFixed(5)}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.residualN.toFixed(5)}</td>
                      <td className="px-3 py-2 border border-zinc-700 font-mono">{s.semiMajor.toFixed(5)}</td>
                      <td className="px-3 py-2 border border-zinc-700">{s.isFixed ? <span className="flex items-center gap-1"><Lock className="w-3 h-3" /> Fixed</span> : 'Free'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Error Ellipse Diagram */}
          <ErrorEllipseCanvas
            stations={result.adjustedStations}
            observations={observations}
            width={700}
            height={450}
          />

          {/* Robust Adjustment: Blunder Detection Panel */}
          {robustResult && (
            <div className={`p-4 rounded-lg border ${robustResult.blunders.length === 0 ? 'bg-green-900/30 border-green-700' : 'bg-red-900/30 border-red-700'}`}>
              <h3 className="font-semibold mb-2 text-white flex items-center gap-2">
                {robustResult.blunders.length === 0
                  ? <><CheckCircle2 className="w-4 h-4" /> No Blunders Detected</>
                  : <><AlertTriangle className="w-4 h-4" /> {robustResult.blunders.length} Blunder(s) Detected</>
                }
                <span className="text-xs font-normal text-zinc-400 ml-2">
                  ({robustResult.method.toUpperCase()} IRLS, {robustResult.iterations} iterations)
                </span>
              </h3>
              <p className="text-sm text-zinc-300 mb-3">{robustResult.summary}</p>

              {/* Per-observation weights table */}
              <div className="overflow-x-auto">
                <table className="w-full text-sm border-collapse text-zinc-300">
                  <thead>
                    <tr className="bg-zinc-800 text-left">
                      <th className="px-3 py-2 border border-zinc-700">#</th>
                      <th className="px-3 py-2 border border-zinc-700">From → To</th>
                      <th className="px-3 py-2 border border-zinc-700">Type</th>
                      <th className="px-3 py-2 border border-zinc-700">Residual (m)</th>
                      <th className="px-3 py-2 border border-zinc-700">Std. Residual</th>
                      <th className="px-3 py-2 border border-zinc-700">Final Weight</th>
                      <th className="px-3 py-2 border border-zinc-700">Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {robustResult.blunders.map((b, i) => (
                      <tr key={i} className="bg-red-950/30">
                        <td className="px-3 py-2 border border-zinc-700">{b.index + 1}</td>
                        <td className="px-3 py-2 border border-zinc-700 font-medium">{b.from || '?'} → {b.to || '?'}</td>
                        <td className="px-3 py-2 border border-zinc-700">{b.type}</td>
                        <td className="px-3 py-2 border border-zinc-700 font-mono">{b.residual.toFixed(4)}</td>
                        <td className="px-3 py-2 border border-zinc-700 font-mono">{b.standardizedResidual.toFixed(2)}σ</td>
                        <td className="px-3 py-2 border border-zinc-700 font-mono text-red-400">{b.finalWeight.toFixed(3)}</td>
                        <td className="px-3 py-2 border border-zinc-700 text-red-400 font-medium">BLUNDER</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {robustResult.blunders.length > 0 && (
                <p className="text-xs text-zinc-400 mt-3">
                  💡 Blunders are down-weighted automatically. Re-check the observation field notes for the flagged legs —
                  look for swapped face, wrong target height, or transcription errors. After correcting, re-run the adjustment.
                </p>
              )}
            </div>
          )}

          {saving && <p className="text-sm text-zinc-500 italic">Saving results…</p>}
        </section>
      )}
    </div>
  )
}

'use client';

import { useState, useMemo } from 'react';
import { Mountain, Save, CheckCircle, Grid3X3 } from 'lucide-react';

interface TopoPoint {
  id: string;
  name: string;
  easting: number;
  northing: number;
  elevation: number;
  code: string;
}

function computeArea(points: TopoPoint[]): number {
  if (points.length < 3) return 0;
  let area = 0;
  for (let i = 0; i < points.length; i++) {
    const j = (i + 1) % points.length;
    area += points[i].easting * points[j].northing;
    area -= points[j].easting * points[i].northing;
  }
  return Math.abs(area) / 2;
}

function computeDTMGrid(points: TopoPoint[], gridSize: number) {
  if (points.length < 3) return { grid: [], minX: 0, maxX: 0, minY: 0, maxY: 0 };
  const xs = points.map(p => p.easting);
  const ys = points.map(p => p.northing);
  const minX = Math.min(...xs), maxX = Math.max(...xs);
  const minY = Math.min(...ys), maxY = Math.max(...ys);

  const grid: { x: number; y: number; z: number; method: string }[] = [];
  const stepX = gridSize;
  const stepY = gridSize;

  for (let x = minX; x <= maxX; x += stepX) {
    for (let y = minY; y <= maxY; y += stepY) {
      // IDW interpolation with power 2, minimum 3 points
      let wSum = 0, wZSum = 0;
      const dists = points.map(p => {
        const d = Math.sqrt((p.easting - x) ** 2 + (p.northing - y) ** 2);
        return { d, p };
      }).sort((a, b) => a.d - b.d).slice(0, 8);

      for (const { d, p } of dists) {
        if (d === 0) { wSum = 1; wZSum = p.elevation; break; }
        const w = 1 / (d * d);
        wSum += w;
        wZSum += w * p.elevation;
      }

      const z = wSum > 0 ? wZSum / wSum : 0;
      const nearest = dists[0]?.d || Infinity;
      const method = nearest > gridSize * 1.5 ? 'extrapolated' : 'IDW';
      grid.push({ x, y, z, method });
    }
  }

  return { grid, minX, maxX, minY, maxY };
}

function computeContours(grid: ReturnType<typeof computeDTMGrid>['grid'], interval: number) {
  if (grid.length === 0) return [];
  const zs = grid.map(g => g.z);
  const minZ = Math.floor(Math.min(...zs) / interval) * interval;
  const maxZ = Math.ceil(Math.max(...zs) / interval) * interval;
  const levels = [];
  for (let z = minZ; z <= maxZ; z += interval) {
    const pointsAtLevel = grid.filter(g => Math.abs(g.z - z) < interval / 2);
    levels.push({ elevation: z, pointCount: pointsAtLevel.length, points: pointsAtLevel });
  }
  return levels;
}

const DEMO_POINTS: TopoPoint[] = [
  { id: '1', name: 'T1', easting: 100, northing: 100, elevation: 125.0, code: 'RM' },
  { id: '2', name: 'T2', easting: 200, northing: 100, elevation: 128.5, code: 'RM' },
  { id: '3', name: 'T3', easting: 300, northing: 100, elevation: 131.0, code: 'RM' },
  { id: '4', name: 'T4', easting: 300, northing: 200, elevation: 129.0, code: 'RM' },
  { id: '5', name: 'T5', easting: 200, northing: 200, elevation: 124.5, code: 'RM' },
  { id: '6', name: 'T6', easting: 100, northing: 200, elevation: 122.0, code: 'RM' },
  { id: '7', name: 'D1', easting: 150, northing: 150, elevation: 126.2, code: 'DP' },
  { id: '8', name: 'D2', easting: 250, northing: 150, elevation: 127.8, code: 'DP' },
];

export default function TopoComputePanel({ projectId }: { projectId: string }) {
  const [points, setPoints] = useState<TopoPoint[]>(DEMO_POINTS);
  const [gridSize, setGridSize] = useState(50);
  const [contourInterval, setContourInterval] = useState(1.0);
  const [saved, setSaved] = useState(false);

  const area = useMemo(() => computeArea(points), [points]);
  const dtm = useMemo(() => computeDTMGrid(points, gridSize), [points, gridSize]);
  const contours = useMemo(() => computeContours(dtm.grid, contourInterval), [dtm.grid, contourInterval]);

  const minElev = dtm.grid.length > 0 ? Math.min(...dtm.grid.map(g => g.z)) : 0;
  const maxElev = dtm.grid.length > 0 ? Math.max(...dtm.grid.map(g => g.z)) : 0;

  const addPoint = () => {
    setPoints(prev => [...prev, { id: String(prev.length + 1), name: `P${prev.length + 1}`, easting: 0, northing: 0, elevation: 0, code: 'DP' }]);
  };

  const updatePoint = (id: string, field: keyof TopoPoint, value: string | number) => {
    setPoints(prev => prev.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  const handleSave = async () => {
    try {
      await fetch(`/api/project/${projectId}/compute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'topographic', results: { area, dtmGrid: dtm.grid, contours, minElev, maxElev } }),
      });
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } catch (e) { console.error(e); }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold"><Mountain className="w-4 h-4 inline mr-1" />Topographic Computations</h3>
        <div className="flex gap-2">
          <div className="text-xs">
            <label className="text-zinc-500 mr-1" htmlFor="grid">Grid:</label>
            <input id="grid" aria-label="Grid:" type="number" value={gridSize} onChange={e => setGridSize(Number(e.target.value))} className="w-14 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white text-xs" min={5} />m
          </div>
          <div className="text-xs">
            <label className="text-zinc-500 mr-1" htmlFor="contour">Contour:</label>
            <input aria-label="Contour:" type="number" step="0.5" value={contourInterval} onChange={e => setContourInterval(Number(e.target.value))} className="w-14 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white text-xs" min={0.1} />m
          </div>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Points</div>
          <div className="text-sm font-bold text-white">{points.length}</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Area</div>
          <div className="text-sm font-bold text-amber-400">{area.toFixed(1)} m²</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">Elev Range</div>
          <div className="text-sm font-bold text-blue-400">{minElev.toFixed(1)}–{maxElev.toFixed(1)} m</div>
        </div>
        <div className="p-2 bg-zinc-900 rounded border border-zinc-700 text-center">
          <div className="text-xs text-zinc-500">DTM Grid</div>
          <div className="text-sm font-bold text-green-400"><Grid3X3 className="w-3 h-3 inline" />{dtm.grid.length} cells</div>
        </div>
      </div>

      {/* Point Table */}
      <div className="bg-zinc-900 rounded border border-zinc-700 overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="border-b border-zinc-700 bg-zinc-800/50">
              <th className="px-2 py-1.5 text-left text-zinc-400">Name</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">E</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">N</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Z</th>
              <th className="px-2 py-1.5 text-left text-zinc-400">Code</th>
            </tr>
          </thead>
          <tbody>
            {points.map(p => (
              <tr key={p.id} className="border-b border-zinc-800">
                <td className="px-2 py-1"><input aria-label="Name" type="text" value={p.name} onChange={e => updatePoint(p.id, 'name', e.target.value)} className="w-14 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1"><input aria-label="Easting" type="number" step="0.1" value={p.easting} onChange={e => updatePoint(p.id, 'easting', Number(e.target.value))} className="w-20 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1"><input aria-label="Northing" type="number" step="0.1" value={p.northing} onChange={e => updatePoint(p.id, 'northing', Number(e.target.value))} className="w-20 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1"><input aria-label="Elevation" type="number" step="0.01" value={p.elevation} onChange={e => updatePoint(p.id, 'elevation', Number(e.target.value))} className="w-20 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
                <td className="px-2 py-1"><input aria-label="Code" type="text" value={p.code} onChange={e => updatePoint(p.id, 'code', e.target.value)} className="w-12 bg-zinc-800 border border-zinc-700 rounded px-1 py-0.5 text-white" /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Contour Summary */}
      <div className="p-3 bg-zinc-900 rounded border border-zinc-700">
        <h4 className="text-xs font-semibold text-zinc-400 mb-2">Contour Levels ({contours.length})</h4>
        <div className="flex flex-wrap gap-2">
          {contours.slice(0, 20).map(c => (
            <div key={c.elevation} className="px-2 py-0.5 bg-zinc-800 rounded text-xs">
              <span className="text-amber-400 font-mono">{c.elevation.toFixed(1)}m</span>
              <span className="text-zinc-500 ml-1">({c.pointCount})</span>
            </div>
          ))}
          {contours.length > 20 && <span className="text-xs text-zinc-500">+{contours.length - 20} more</span>}
        </div>
      </div>

      <div className="flex gap-2">
        <button onClick={addPoint} className="px-2 py-1 text-xs bg-zinc-800 border border-zinc-700 rounded text-zinc-400 hover:text-white">+ Point</button>
        <button onClick={handleSave} disabled={saved} className="inline-flex items-center gap-1 px-3 py-1 bg-[var(--accent)] text-white text-xs rounded hover:bg-[var(--accent-dim)] disabled:opacity-50">
          {saved ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}{saved ? 'Saved' : 'Save Results'}
        </button>
      </div>
    </div>
  );
}

'use client'

/**
 * ActivityFeed — Dashboard widget showing recent user activity
 *
 * Shows a chronological feed of:
 * - Project created/updated
 * - Documents generated
 * - Fieldbook entries saved
 * - Computations run
 * - Peer review submissions
 *
 * Fetches from /api/activity
 */

import { useState, useEffect, useCallback } from 'react'
import Link from 'next/link'
import {
  FolderKanban, FileText, MapPin, Calculator, FileCheck2,
  Users, CreditCard, Settings, Activity as ActivityIcon,
  Loader2, ChevronRight, Clock,
} from 'lucide-react'

interface Activity {
  id: string
  project_id: string | null
  activity_type: string
  entity_type: string | null
  entity_id: string | null
  description: string
  metadata: Record<string, unknown>
  created_at: string
}

const ACTIVITY_ICONS: Record<string, typeof FolderKanban> = {
  project_created: FolderKanban,
  project_updated: FolderKanban,
  document_generated: FileText,
  fieldbook_saved: FileText,
  computation_run: Calculator,
  map_capture: MapPin,
  peer_review_submitted: FileCheck2,
  peer_review_completed: FileCheck2,
  team_invite: Users,
  payment_received: CreditCard,
  settings_changed: Settings,
}

const ACTIVITY_COLORS: Record<string, string> = {
  project_created: 'text-blue-400 bg-blue-500/10',
  project_updated: 'text-blue-400 bg-blue-500/10',
  document_generated: 'text-purple-400 bg-purple-500/10',
  fieldbook_saved: 'text-amber-400 bg-amber-500/10',
  computation_run: 'text-emerald-400 bg-emerald-500/10',
  map_capture: 'text-[#D17B47] bg-[#D17B47]/10',
  peer_review_submitted: 'text-cyan-400 bg-cyan-500/10',
  peer_review_completed: 'text-cyan-400 bg-cyan-500/10',
  team_invite: 'text-pink-400 bg-pink-500/10',
  payment_received: 'text-green-400 bg-green-500/10',
  settings_changed: 'text-gray-400 bg-gray-500/10',
}

function timeAgo(dateStr: string): string {
  const date = new Date(dateStr)
  const seconds = Math.floor((Date.now() - date.getTime()) / 1000)
  if (seconds < 60) return 'just now'
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ago`
  const days = Math.floor(hours / 24)
  if (days < 7) return `${days}d ago`
  return date.toLocaleDateString('en-KE', { month: 'short', day: 'numeric' })
}

export function ActivityFeed({ limit = 10 }: { limit?: number }) {
  const [activities, setActivities] = useState<Activity[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchActivities = useCallback(async () => {
    try {
      setLoading(true)
      const res = await fetch(`/api/activity?limit=${limit}`)
      if (!res.ok) throw new Error('Failed to load activity')
      const data = await res.json()
      setActivities(data.data?.activities || [])
      setError(null)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load')
    } finally {
      setLoading(false)
    }
  }, [limit])

  useEffect(() => {
    fetchActivities()
    const interval = setInterval(fetchActivities, 30000) // 30s refresh
    return () => clearInterval(interval)
  }, [fetchActivities])

  return (
    <div className="card p-5">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <ActivityIcon className="w-4 h-4 text-[var(--accent)]" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-[var(--text-primary)]">Recent Activity</h3>
            <p className="text-[10px] text-gray-500">What happened in your projects</p>
          </div>
        </div>
        <Link
          href="/activity"
          className="text-[10px] text-[var(--accent)] hover:underline flex items-center gap-0.5"
        >
          View all <ChevronRight className="w-3 h-3" />
        </Link>
      </div>

      {/* Activity list */}
      {loading ? (
        <div className="flex items-center justify-center py-8">
          <Loader2 className="w-5 h-5 text-gray-500 animate-spin" />
        </div>
      ) : error ? (
        <div className="text-center py-8">
          <p className="text-xs text-gray-500">{error}</p>
          <button
            onClick={fetchActivities}
            className="mt-2 text-[10px] text-[var(--accent)] hover:underline"
          >
            Retry
          </button>
        </div>
      ) : activities.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-8 text-center">
          <Clock className="w-8 h-8 text-gray-600 mb-2" />
          <p className="text-sm text-gray-500">No recent activity</p>
          <p className="text-[10px] text-gray-600 mt-1">
            Create a project or run a computation to see activity here.
          </p>
        </div>
      ) : (
        <div className="space-y-1">
          {activities.map((activity, idx) => {
            const Icon = ACTIVITY_ICONS[activity.activity_type] || ActivityIcon
            const colorClass = ACTIVITY_COLORS[activity.activity_type] || 'text-gray-400 bg-gray-500/10'
            const href = activity.project_id ? `/project/${activity.project_id}` : null

            const content = (
              <>
                {/* Timeline dot */}
                {idx < activities.length - 1 && (
                  <div className="absolute left-[15px] top-8 bottom-0 w-px bg-white/[0.06]" />
                )}
                <div className={`relative flex items-start gap-3 px-2 py-2 rounded-lg hover:bg-white/[0.02] transition-colors ${href ? 'cursor-pointer' : ''}`}>
                  <div className={`shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${colorClass} border border-white/[0.06]`}>
                    <Icon className="w-3.5 h-3.5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs text-[var(--text-primary)] leading-tight">{activity.description}</p>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-[9px] text-gray-600">{timeAgo(activity.created_at)}</span>
                      {activity.entity_type && (
                        <span className="text-[9px] text-gray-600 px-1 py-0.5 rounded bg-white/[0.04]">
                          {activity.entity_type}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </>
            )

            return href ? (
              <Link key={activity.id} href={href}>{content}</Link>
            ) : (
              <div key={activity.id}>{content}</div>
            )
          })}
        </div>
      )}
    </div>
  )
}

'use client';

import {
  useState,
  useEffect,
  useRef,
  useCallback,
  type KeyboardEvent as ReactKeyboardEvent,
} from 'react';
import { useRouter } from 'next/navigation';
import { Search, X, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ProjectResult {
  id: string;
  name: string;
  description: string;
  relevance: number;
}

interface SubmissionResult {
  id: string;
  title: string;
  status: string;
  relevance: number;
}

interface SurveyorResult {
  id: string;
  full_name: string;
  isk_number: string;
  relevance: number;
}

interface SearchResults {
  projects: ProjectResult[];
  submissions: SubmissionResult[];
  surveyors: SurveyorResult[];
}

interface SearchResponse {
  results: SearchResults;
  total: number;
  query: string;
}

type ResultType = 'projects' | 'submissions' | 'surveyors';

/** Flattened item for keyboard navigation */
interface FlatItem {
  type: ResultType;
  data: ProjectResult | SubmissionResult | SurveyorResult;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const DEBOUNCE_MS = 300;

const GROUP_LABELS: Record<ResultType, string> = {
  projects: 'Projects',
  submissions: 'Submissions',
  surveyors: 'Surveyors',
};

const GROUP_ICONS: Record<ResultType, React.ReactNode> = {
  projects: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z" />
    </svg>
  ),
  submissions: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z" />
      <polyline points="14 2 14 8 20 8" />
      <line x1="16" y1="13" x2="8" y2="13" />
      <line x1="16" y1="17" x2="8" y2="17" />
    </svg>
  ),
  surveyors: (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2" />
      <circle cx="12" cy="7" r="4" />
    </svg>
  ),
};

function getRoute(type: ResultType, id: string): string {
  switch (type) {
    case 'projects':
      return `/dashboard/projects/${id}`;
    case 'submissions':
      return `/dashboard/submissions/${id}`;
    case 'surveyors':
      return `/dashboard/surveyors/${id}`;
  }
}

function getPrimaryLabel(item: FlatItem['data']): string {
  if ('name' in item) return item.name;
  if ('title' in item) return item.title;
  if ('full_name' in item) return item.full_name;
  return '';
}

function getSecondaryLabel(item: FlatItem['data']): string | null {
  if ('description' in item && item.description) return item.description;
  if ('status' in item && item.status) return item.status;
  if ('isk_number' in item && item.isk_number) return `ISK ${item.isk_number}`;
  return null;
}

function getStatusColor(status: string): string {
  switch (status.toLowerCase()) {
    case 'approved':
      return 'text-[var(--success)]';
    case 'pending':
    case 'under_review':
      return 'text-[var(--warning)]';
    case 'rejected':
      return 'text-[var(--error)]';
    default:
      return 'text-[var(--text-muted)]';
  }
}

function flattenResults(results: SearchResults): FlatItem[] {
  const items: FlatItem[] = [];
  // Sort each group by relevance descending
  const sortedProjects = [...results.projects].sort((a, b) => b.relevance - a.relevance);
  const sortedSubmissions = [...results.submissions].sort((a, b) => b.relevance - a.relevance);
  const sortedSurveyors = [...results.surveyors].sort((a, b) => b.relevance - a.relevance);

  for (const project of sortedProjects) items.push({ type: 'projects', data: project });
  for (const submission of sortedSubmissions) items.push({ type: 'submissions', data: submission });
  for (const surveyor of sortedSurveyors) items.push({ type: 'surveyors', data: surveyor });
  return items;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function DashboardSearch() {
  const router = useRouter();

  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResults | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);

  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  // ------ Flatten items for keyboard navigation ------
  const flatItems = results ? flattenResults(results) : [];
  const hasResults = flatItems.length > 0;

  // ------ Group tracking (which type starts at which flat index) ------
  const groupBoundaries = useRef<Map<number, ResultType>>(new Map());

  useEffect(() => {
    groupBoundaries.current.clear();
    if (!results) return;

    let idx = 0;
    const order: ResultType[] = ['projects', 'submissions', 'surveyors'];
    for (const type of order) {
      const arr = results[type];
      if (arr.length > 0) {
        groupBoundaries.current.set(idx, type);
        idx += arr.length;
      }
    }
  }, [results]);

  // ------ Search API call ------
  const performSearch = useCallback(async (q: string) => {
    // Cancel any in-flight request
    if (abortRef.current) abortRef.current.abort();
    const controller = new AbortController();
    abortRef.current = controller;

    if (!q.trim()) {
      setResults(null);
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch(`/api/search?q=${encodeURIComponent(q.trim())}`, {
        signal: controller.signal,
      });
      if (!res.ok) throw new Error(`Search failed: ${res.status}`);
      const data: SearchResponse = await res.json();
      // Only update if this wasn't aborted
      if (!controller.signal.aborted) {
        setResults(data.results);
      }
    } catch (err) {
      // Ignore abort errors
      if (err instanceof DOMException && err.name === 'AbortError') return;
      console.error('Search error:', err);
      setResults(null);
    } finally {
      if (!controller.signal.aborted) {
        setIsLoading(false);
      }
    }
  }, []);

  // ------ Input change with debounce ------
  const handleInputChange = useCallback(
    (value: string) => {
      setQuery(value);
      setActiveIndex(-1);

      if (debounceRef.current) clearTimeout(debounceRef.current);

      if (!value.trim()) {
        setResults(null);
        setIsLoading(false);
        setIsOpen(false);
        return;
      }

      setIsOpen(true);
      setIsLoading(true);
      debounceRef.current = setTimeout(() => {
        performSearch(value);
      }, DEBOUNCE_MS);
    },
    [performSearch],
  );

  // ------ Clear search ------
  const handleClear = useCallback(() => {
    setQuery('');
    setResults(null);
    setIsLoading(false);
    setIsOpen(false);
    setActiveIndex(-1);
    inputRef.current?.focus();
  }, []);

  // ------ Click outside to close ------
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // ------ Escape to close ------
  useEffect(() => {
    function handleEscape(e: globalThis.KeyboardEvent) {
      if (e.key === 'Escape') {
        setIsOpen(false);
        inputRef.current?.blur();
      }
    }
    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, []);

  // ------ Cleanup on unmount ------
  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      if (abortRef.current) abortRef.current.abort();
    };
  }, []);

  // ------ Navigate to result ------
  const navigateTo = useCallback(
    (item: FlatItem) => {
      const route = getRoute(item.type, item.data.id);
      setIsOpen(false);
      router.push(route);
    },
    [router],
  );

  // ------ Keyboard navigation ------
  const handleKeyDown = useCallback(
    (e: ReactKeyboardEvent<HTMLInputElement>) => {
      if (!isOpen) {
        if (e.key === 'ArrowDown' && query.trim()) {
          setIsOpen(true);
        }
        return;
      }

      switch (e.key) {
        case 'ArrowDown': {
          e.preventDefault();
          setActiveIndex((prev) => (prev < flatItems.length - 1 ? prev + 1 : 0));
          break;
        }
        case 'ArrowUp': {
          e.preventDefault();
          setActiveIndex((prev) => (prev > 0 ? prev - 1 : flatItems.length - 1));
          break;
        }
        case 'Enter': {
          e.preventDefault();
          if (activeIndex >= 0 && activeIndex < flatItems.length) {
            navigateTo(flatItems[activeIndex]);
          }
          break;
        }
        case 'Escape': {
          setIsOpen(false);
          break;
        }
      }
    },
    [isOpen, flatItems, activeIndex, navigateTo, query],
  );

  // ------ Scroll active item into view ------
  useEffect(() => {
    if (activeIndex < 0 || !isOpen) return;
    const el = containerRef.current?.querySelector(
      `[data-search-index="${activeIndex}"]`,
    ) as HTMLElement | null;
    el?.scrollIntoView({ block: 'nearest' });
  }, [activeIndex, isOpen]);

  // ------ Focus input on Cmd/Ctrl+K ------
  useEffect(() => {
    function handleGlobalShortcut(e: globalThis.KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        inputRef.current?.focus();
        if (query.trim()) setIsOpen(true);
      }
    }
    document.addEventListener('keydown', handleGlobalShortcut);
    return () => document.removeEventListener('keydown', handleGlobalShortcut);
  }, [query]);

  // ------ Render grouped results ------
  const renderResults = () => {
    if (!isOpen) return null;

    if (isLoading && !results) {
      return (
        <div className="absolute top-full left-0 right-0 z-50 mt-2 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)]/80 backdrop-blur-2xl shadow-[0_16px_40px_rgba(0,0,0,0.5)] overflow-hidden transition-all duration-300">
          <div className="flex items-center justify-center gap-2 px-4 py-8 text-sm text-[var(--text-muted)]">
            <Loader2 className="h-4 w-4 animate-spin" />
            <span>Searching...</span>
          </div>
        </div>
      );
    }

    if (results && !hasResults && query.trim()) {
      return (
        <div className="absolute top-full left-0 right-0 z-50 mt-2 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)]/80 backdrop-blur-2xl shadow-[0_16px_40px_rgba(0,0,0,0.5)] overflow-hidden transition-all duration-300">
          <div className="flex flex-col items-center justify-center px-4 py-8">
            <Search className="h-8 w-8 text-[var(--text-muted)] mb-2 opacity-50" />
            <p className="text-sm text-[var(--text-secondary)]">No results found</p>
            <p className="text-xs text-[var(--text-muted)] mt-1">
              Try a different search term
            </p>
          </div>
        </div>
      );
    }

    if (!results || !hasResults) return null;

    const order: ResultType[] = ['projects', 'submissions', 'surveyors'];
    let flatIdx = 0;

    return (
      <div className="absolute top-full left-0 right-0 z-50 mt-2 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)]/80 backdrop-blur-2xl shadow-[0_16px_40px_rgba(0,0,0,0.5)] overflow-hidden transition-all duration-300">
        <div className="max-h-80 overflow-y-auto overscroll-contain">
          {order.map((type) => {
            const items = results[type];
            if (!items.length) return null;

            // Sort by relevance
            const sorted = [...items].sort((a, b) => b.relevance - a.relevance);
            const startIdx = flatIdx;

            const group = (
              <div key={type}>
                {/* Group header */}
                <div className="flex items-center gap-2 px-3 py-2 text-xs font-semibold uppercase tracking-wider text-[var(--text-muted)] bg-[var(--bg-primary)]/50 border-b border-[var(--border-color)]">
                  {GROUP_ICONS[type]}
                  {GROUP_LABELS[type]}
                  <span className="ml-auto text-[10px] font-normal text-[var(--text-muted)] opacity-70">
                    {sorted.length}
                  </span>
                </div>

                {/* Items */}
                {sorted.map((item, i) => {
                  const currentFlatIdx = startIdx + i;
                  const isActive = activeIndex === currentFlatIdx;
                  const primary = getPrimaryLabel(item);
                  const secondary = getSecondaryLabel(item);

                  return (
                    <button
                      key={`${type}-${item.id}`}
                      data-search-index={currentFlatIdx}
                      type="button"
                      className={cn(
                        'w-full flex items-center gap-3 px-3 py-2.5 text-left transition-colors duration-100 border-b border-[var(--border-color)] last:border-b-0',
                        isActive
                          ? 'bg-[var(--accent-subtle)] text-[var(--accent)]'
                          : 'text-[var(--text-secondary)] hover:bg-[var(--glass-bg)] hover:text-[var(--text-primary)]',
                      )}
                      onClick={() => navigateTo({ type, data: item })}
                      onMouseEnter={() => setActiveIndex(currentFlatIdx)}
                    >
                      {/* Icon */}
                      <div
                        className={cn(
                          'shrink-0 flex items-center justify-center w-8 h-8 rounded-md border',
                          isActive
                            ? 'border-[var(--accent)]/30 bg-[var(--accent)]/10 text-[var(--accent)]'
                            : 'border-[var(--border-color)] bg-[var(--bg-tertiary)] text-[var(--text-muted)]',
                        )}
                      >
                        {GROUP_ICONS[type]}
                      </div>

                      {/* Text */}
                      <div className="min-w-0 flex-1">
                        <p
                          className={cn(
                            'text-sm font-medium truncate',
                            isActive ? 'text-[var(--accent)]' : 'text-[var(--text-primary)]',
                          )}
                        >
                          {primary}
                        </p>
                        {secondary && (
                          <p
                            className={cn(
                              'text-xs truncate mt-0.5',
                              'status' in item
                                ? getStatusColor(item.status as string)
                                : 'text-[var(--text-muted)]',
                            )}
                          >
                            {secondary}
                          </p>
                        )}
                      </div>

                      {/* Relevance indicator */}
                      <div className="shrink-0 w-10 text-right">
                        <span className="text-[10px] text-[var(--text-muted)] opacity-60">
                          {Math.round(item.relevance * 100)}%
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>
            );

            flatIdx += sorted.length;
            return group;
          })}
        </div>

        {/* Footer hint */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-[var(--border-color)] bg-[var(--bg-primary)]/40 text-[10px] text-[var(--text-muted)]">
          <span>{results ? Object.values(results).reduce((sum, arr) => sum + arr.length, 0) : 0} results</span>
          <div className="flex items-center gap-2">
            <kbd className="px-1 py-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] text-[9px]">
              ↑↓
            </kbd>
            <span>navigate</span>
            <kbd className="px-1 py-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] text-[9px]">
              ↵
            </kbd>
            <span>open</span>
            <kbd className="px-1 py-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] text-[9px]">
              esc
            </kbd>
            <span>close</span>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div ref={containerRef} className="relative w-full max-w-md">
      {/* Search input */}
      <div
        className={cn(
          'flex items-center gap-3 rounded-full border bg-[var(--bg-secondary)] px-5 py-3 transition-all duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]',
          isOpen
            ? 'border-[var(--accent)] shadow-[0_0_0_3px_var(--accent-subtle)] bg-[var(--bg-card)]'
            : 'border-[var(--border-color)] hover:border-[var(--border-hover)]',
        )}
      >
        {isLoading ? (
          <Loader2 className="h-4 w-4 shrink-0 animate-spin text-[var(--accent)]" />
        ) : (
          <Search className="h-4 w-4 shrink-0 text-[var(--text-muted)]" />
        )}

        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => handleInputChange(e.target.value)}
          onKeyDown={handleKeyDown}
          onFocus={() => {
            if (query.trim()) setIsOpen(true);
          }}
          aria-label="Search projects, submissions, surveyors..." placeholder="Search projects, submissions, surveyors..."
          className="flex-1 bg-transparent text-sm text-[var(--text-primary)] placeholder-[var(--text-muted)] outline-none min-w-0"
          autoComplete="off"
          spellCheck={false}
        />

        {query && (
          <button
            type="button"
            onClick={handleClear}
            className="shrink-0 flex items-center justify-center w-5 h-5 rounded-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors"
            aria-label="Clear search"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        )}

        {!query && (
          <kbd className="hidden sm:inline-flex items-center gap-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] px-1.5 py-0.5 text-[10px] font-medium text-[var(--text-muted)] shrink-0">
            <span className="text-[9px]">⌘</span>K
          </kbd>
        )}
      </div>

      {/* Results dropdown */}
      {renderResults()}
    </div>
  );
}

'use client'

/**
 * QADashboard — Single view of all quality checks for a project
 *
 * Shows:
 * - Topology check results (overlaps, slivers, self-intersections)
 * - Area reconciliation (parent vs sum of parts)
 * - Traverse precision (linear + angular closure)
 * - Beacon validation (duplicates, missing coordinates)
 * - Document compliance (SoK standards)
 * - NLIMS readiness
 *
 * Green = pass, Amber = warning, Red = fail
 */

import { useState, useCallback, useMemo } from 'react'
import {
  ShieldCheck, AlertTriangle, AlertCircle, CheckCircle2,
  Loader2, RefreshCw, FileText, MapPin, Ruler, Calculator,
  Layers, Building2, Download,
} from 'lucide-react'
import { runTopologyCheck, type ExistingParcel } from '@/lib/survey/topologyChecker'
import { evaluateTraversePrecision, type TraverseCategory } from '@/lib/engine/computationalAccuracy'
import { computeAreaWithPrecision } from '@/lib/engine/computationalAccuracy'
import { memoize } from '@/lib/performance'

// Memoized area computation — caches results for same vertex sets
const memoizedComputeArea = memoize(computeAreaWithPrecision, {
  keyFn: (...args: any[]) => JSON.stringify(args[0]),
  maxSize: 200,
})

interface QACheck {
  id: string
  category: 'topology' | 'area' | 'traverse' | 'beacons' | 'documents' | 'nlims'
  name: string
  status: 'pass' | 'warning' | 'fail' | 'pending'
  message: string
  details?: string
  count?: number
}

interface QADashboardProps {
  projectId: string
  parcels?: ExistingParcel[]
  traverseData?: {
    linearErrorM: number
    totalDistanceM: number
    angularMisclosureSec: number
    stationCount: number
  }
  parentAreaHa?: number
  surveyCategory?: TraverseCategory
}

const CATEGORY_ICONS = {
  topology: Layers,
  area: Calculator,
  traverse: Ruler,
  beacons: MapPin,
  documents: FileText,
  nlims: Building2,
}

const STATUS_CONFIG = {
  pass: { icon: CheckCircle2, color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', label: 'PASS' },
  warning: { icon: AlertTriangle, color: 'text-amber-400', bg: 'bg-amber-500/10', border: 'border-amber-500/30', label: 'WARNING' },
  fail: { icon: AlertCircle, color: 'text-red-400', bg: 'bg-red-500/10', border: 'border-red-500/30', label: 'FAIL' },
  pending: { icon: Loader2, color: 'text-gray-400', bg: 'bg-gray-500/10', border: 'border-gray-500/30', label: 'PENDING' },
}

export function QADashboard({
  projectId,
  parcels = [],
  traverseData,
  parentAreaHa,
  surveyCategory = 'urban',
}: QADashboardProps) {
  const [checks, setChecks] = useState<QACheck[]>([])
  const [running, setRunning] = useState(false)

  const runAllChecks = useCallback(async () => {
    setRunning(true)

    const results: QACheck[] = []

    // ─── 1. Topology Checks ──────────────────────────────────
    if (parcels.length > 0) {
      let totalOverlaps = 0
      let totalSlivers = 0
      let totalSelfIntersections = 0

      for (const parcel of parcels) {
        const otherParcels = parcels.filter(p => p.id !== parcel.id)
        const topoResult = await runTopologyCheck({
          newVertices: parcel.vertices,
          existingParcels: otherParcels,
        })

        totalOverlaps += topoResult.issues.filter(i => i.type === 'overlap').length
        totalSlivers += topoResult.issues.filter(i => i.type === 'sliver').length
        totalSelfIntersections += topoResult.issues.filter(i => i.type === 'self_intersection').length
      }

      results.push({
        id: 'topo-overlap',
        category: 'topology',
        name: 'Parcel Overlaps',
        status: totalOverlaps === 0 ? 'pass' : 'fail',
        message: totalOverlaps === 0 ? 'No overlapping parcels detected' : `${totalOverlaps} overlap(s) found`,
        details: 'Overlapping parcels will be rejected by the registry',
        count: totalOverlaps,
      })

      results.push({
        id: 'topo-sliver',
        category: 'topology',
        name: 'Sliver Gaps',
        status: totalSlivers === 0 ? 'pass' : 'warning',
        message: totalSlivers === 0 ? 'No sliver gaps detected' : `${totalSlivers} sliver gap(s) found`,
        details: 'Micro-gaps between adjacent parcels may cause registration issues',
        count: totalSlivers,
      })

      results.push({
        id: 'topo-self-int',
        category: 'topology',
        name: 'Self-Intersections',
        status: totalSelfIntersections === 0 ? 'pass' : 'fail',
        message: totalSelfIntersections === 0 ? 'All parcel boundaries are valid' : `${totalSelfIntersections} self-intersection(s) found`,
        details: 'A boundary that crosses itself produces an invalid parcel',
        count: totalSelfIntersections,
      })
    } else {
      results.push({
        id: 'topo-empty',
        category: 'topology',
        name: 'Parcel Data',
        status: 'pending',
        message: 'No parcels to check — import parcels first',
      })
    }

    // ─── 2. Area Reconciliation ──────────────────────────────
    if (parentAreaHa && parcels.length > 0) {
      const sumOfParts = parcels.reduce((sum, p) => {
        const area = memoizedComputeArea(p.vertices)
        return sum + area.areaHectares
      }, 0)

      const difference = Math.abs(parentAreaHa - sumOfParts)
      const tolerance = 0.001 // 10 m²

      results.push({
        id: 'area-recon',
        category: 'area',
        name: 'Area Reconciliation',
        status: difference <= tolerance ? 'pass' : 'fail',
        message: difference <= tolerance
          ? `Sum of parts (${sumOfParts.toFixed(4)} ha) matches parent (${parentAreaHa.toFixed(4)} ha)`
          : `Mismatch: parent ${parentAreaHa.toFixed(4)} ha vs parts ${sumOfParts.toFixed(4)} ha (diff ${difference.toFixed(4)} ha)`,
        details: 'Sum of subdivision parts must equal parent title area within ±0.001 ha',
      })
    }

    // ─── 3. Traverse Precision ───────────────────────────────
    if (traverseData) {
      const precision = evaluateTraversePrecision(
        traverseData.linearErrorM,
        traverseData.totalDistanceM,
        traverseData.angularMisclosureSec,
        traverseData.stationCount,
        surveyCategory,
      )

      results.push({
        id: 'trav-linear',
        category: 'traverse',
        name: 'Linear Precision',
        status: precision.passesLinear ? 'pass' : 'fail',
        message: `1:${precision.linearPrecision.toLocaleString()} (min 1:${precision.minRequiredLinear})`,
        details: `Survey Act Cap 299 requires 1:${precision.minRequiredLinear} for ${surveyCategory} surveys`,
      })

      results.push({
        id: 'trav-angular',
        category: 'traverse',
        name: 'Angular Closure',
        status: precision.passesAngular ? 'pass' : 'fail',
        message: `${precision.angularMisclosure.toFixed(1)}" (max ${precision.maxAllowedAngular.toFixed(1)}")`,
        details: `Maximum allowed: ${precision.maxAllowedAngular.toFixed(1)}" for ${precision.stationCount} stations`,
      })
    }

    // ─── 4. Beacon Validation ────────────────────────────────
    if (parcels.length > 0) {
      const allBeacons = parcels.flatMap(p => p.vertices)
      let duplicates = 0

      for (let i = 0; i < allBeacons.length; i++) {
        for (let j = i + 1; j < allBeacons.length; j++) {
          const dE = allBeacons[i].easting - allBeacons[j].easting
          const dN = allBeacons[i].northing - allBeacons[j].northing
          if (Math.sqrt(dE * dE + dN * dN) < 0.1) duplicates++
        }
      }

      results.push({
        id: 'beacon-dup',
        category: 'beacons',
        name: 'Duplicate Beacons',
        status: duplicates === 0 ? 'pass' : 'warning',
        message: duplicates === 0 ? 'No duplicate beacons' : `${duplicates} potential duplicate(s) found`,
        details: 'Beacons less than 0.1m apart may be the same physical beacon',
        count: duplicates,
      })
    }

    // ─── 5. Document Compliance ──────────────────────────────
    results.push({
      id: 'doc-sok',
      category: 'documents',
      name: 'SoK Standards Compliance',
      status: 'pass',
      message: 'All document templates use SoK 2020 line weights and text sizes',
      details: 'Line weights: 0.3mm parcels, 0.5mm scheme, 0.7mm title. Text: 2.5mm coordinates, 2mm bearings',
    })

    // ─── 6. NLIMS Readiness ──────────────────────────────────
    const hasAllFields = parcels.every(p => p.id && p.vertices.length >= 3)
    results.push({
      id: 'nlims-ready',
      category: 'nlims',
      name: 'NLIMS/ArdhiSasa Readiness',
      status: hasAllFields && parcels.length > 0 ? 'pass' : 'pending',
      message: hasAllFields && parcels.length > 0
        ? 'All parcels have required fields for NLIMS submission'
        : 'Missing required parcel data for NLIMS export',
      details: 'Requires: parcel number, 3+ vertices, owner data',
    })

    setChecks(results)
    setRunning(false)
  }, [parcels, parentAreaHa, traverseData, surveyCategory])

  // Auto-run on mount
  useMemo(() => {
    runAllChecks()
  }, [runAllChecks])

  const stats = useMemo(() => {
    return {
      total: checks.length,
      pass: checks.filter(c => c.status === 'pass').length,
      warning: checks.filter(c => c.status === 'warning').length,
      fail: checks.filter(c => c.status === 'fail').length,
      pending: checks.filter(c => c.status === 'pending').length,
    }
  }, [checks])

  const overallStatus = stats.fail > 0 ? 'fail' : stats.warning > 0 ? 'warning' : stats.pass > 0 ? 'pass' : 'pending'

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="card p-4">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
              overallStatus === 'pass' ? 'bg-emerald-500/10' :
              overallStatus === 'warning' ? 'bg-amber-500/10' :
              overallStatus === 'fail' ? 'bg-red-500/10' : 'bg-gray-500/10'
            }`}>
              <ShieldCheck className={`w-5 h-5 ${
                overallStatus === 'pass' ? 'text-emerald-400' :
                overallStatus === 'warning' ? 'text-amber-400' :
                overallStatus === 'fail' ? 'text-red-400' : 'text-gray-400'
              }`} />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-[var(--text-primary)]">QA Validation Dashboard</h2>
              <p className="text-[10px] text-gray-500">All quality checks in one view</p>
            </div>
          </div>
          <button
            onClick={runAllChecks}
            disabled={running}
            className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-medium hover:bg-[var(--accent)]/20 disabled:opacity-50"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${running ? 'animate-spin' : ''}`} />
            Re-run Checks
          </button>
        </div>

        {/* Summary stats */}
        <div className="grid grid-cols-4 gap-2">
          <StatBox label="Passed" value={stats.pass} color="text-emerald-400" bg="bg-emerald-500/10" />
          <StatBox label="Warnings" value={stats.warning} color="text-amber-400" bg="bg-amber-500/10" />
          <StatBox label="Failed" value={stats.fail} color="text-red-400" bg="bg-red-500/10" />
          <StatBox label="Pending" value={stats.pending} color="text-gray-400" bg="bg-gray-500/10" />
        </div>
      </div>

      {/* Checks by category */}
      {Object.entries(CATEGORY_ICONS).map(([cat, CatIcon]) => {
        const catChecks = checks.filter(c => c.category === cat)
        if (catChecks.length === 0) return null

        return (
          <div key={cat} className="card p-4">
            <div className="flex items-center gap-2 mb-3">
              <CatIcon className="w-4 h-4 text-[var(--accent)]" />
              <span className="text-xs font-semibold text-[var(--text-primary)] uppercase tracking-wider">
                {cat}
              </span>
            </div>
            <div className="space-y-2">
              {catChecks.map(check => {
                const cfg = STATUS_CONFIG[check.status]
                const StatusIcon = cfg.icon
                return (
                  <div
                    key={check.id}
                    className={`flex items-start gap-3 p-2.5 rounded-lg border ${cfg.bg} ${cfg.border}`}
                  >
                    <StatusIcon className={`w-4 h-4 ${cfg.color} shrink-0 mt-0.5 ${check.status === 'pending' ? 'animate-spin' : ''}`} />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-medium text-[var(--text-primary)]">{check.name}</span>
                        <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded ${cfg.bg} ${cfg.color}`}>
                          {cfg.label}
                        </span>
                        {check.count != null && check.count > 0 && (
                          <span className="text-[9px] text-gray-500">({check.count})</span>
                        )}
                      </div>
                      <p className="text-[11px] text-gray-400 mt-0.5">{check.message}</p>
                      {check.details && (
                        <p className="text-[10px] text-gray-600 mt-0.5">{check.details}</p>
                      )}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )
      })}

      {/* Overall verdict */}
      {checks.length > 0 && (
        <div className={`card p-4 ${
          overallStatus === 'pass' ? 'border-emerald-500/30' :
          overallStatus === 'warning' ? 'border-amber-500/30' :
          'border-red-500/30'
        }`}>
          <div className="flex items-center gap-2">
            {overallStatus === 'pass' && <CheckCircle2 className="w-5 h-5 text-emerald-400" />}
            {overallStatus === 'warning' && <AlertTriangle className="w-5 h-5 text-amber-400" />}
            {overallStatus === 'fail' && <AlertCircle className="w-5 h-5 text-red-400" />}
            <div>
              <span className={`text-sm font-bold ${
                overallStatus === 'pass' ? 'text-emerald-400' :
                overallStatus === 'warning' ? 'text-amber-400' :
                'text-red-400'
              }`}>
                {overallStatus === 'pass' ? 'READY FOR SUBMISSION' :
                 overallStatus === 'warning' ? 'READY WITH WARNINGS' :
                 'NOT READY — FIX ERRORS'}
              </span>
              <p className="text-[10px] text-gray-500 mt-0.5">
                {stats.fail > 0 ? `${stats.fail} error(s) must be fixed before registry submission` :
                 stats.warning > 0 ? `${stats.warning} warning(s) — review recommended` :
                 'All quality checks passed'}
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

function StatBox({ label, value, color, bg }: { label: string; value: number; color: string; bg: string }) {
  return (
    <div className={`p-2 rounded-lg ${bg} border border-white/[0.04] text-center`}>
      <div className={`text-lg font-bold ${color}`}>{value}</div>
      <div className="text-[9px] text-gray-500 uppercase tracking-wider">{label}</div>
    </div>
  )
}

'use client';

import { useState, useMemo } from 'react'
import { FileText, Download, Save, CheckCircle, AlertCircle, Plus, Trash2, Printer, Ruler } from 'lucide-react'
import { DeedPlanInput, DeedPlanOutput, BoundaryPoint, BeaconType } from '@/types/deedPlan'
import { generateDeedPlan } from '@/lib/compute/deedPlanApi'
import { saveDeedPlan } from '@/lib/api-client/deedPlans'
import { printDeedPlan } from '@/lib/print/deedPlanPrint'
import {
  coordinate2D,
  polygonArea2D,
  formatScalarWithCI,
  scalarCI,
} from '@/lib/survey/covariancePropagation'

interface DeedPlanGeneratorProps {
  projectId: string
  initialPoints?: BoundaryPoint[]
}

const SCALES = [500, 1000, 2500, 5000] as const
const MARK_TYPES: BeaconType[] = ['PSC', 'SSC', 'BM', 'MASONRY_NAIL', 'IRON_PIN', 'CONCRETE_BEACON', 'INDICATORY', 'RIVET', 'TBM']
const MARK_STATUSES = ['FOUND', 'SET', 'REFERENCED', 'DESTROYED', 'NOT_FOUND'] as const

const FOUR_ACRE_SAMPLE: DeedPlanInput = {
  surveyNumber: 'RS087_2026_014_R00',
  drawingNumber: 'FR-583-83-SUBDIV-A',
  parcelNumber: 'A / L.R. Kajiado-Kaputiei North-18462',
