  drawnBy: 'SKM',
  checkedBy: 'METARDU QA',
}

export default function DeedPlanGenerator({ projectId, initialPoints = [] }: DeedPlanGeneratorProps) {
  const [step, setStep] = useState<'input' | 'preview' | 'export'>('input')
  const [isGenerating, setIsGenerating] = useState(false)
  const [output, setOutput] = useState<DeedPlanOutput | null>(null)
  const [error, setError] = useState<string | null>(null)

  const [input, setInput] = useState<DeedPlanInput>({
    surveyNumber: '',
    drawingNumber: '',
    parcelNumber: '',
    locality: '',
    area: 0,
    registrationSection: '',
    county: '',
    utmZone: 37,
    hemisphere: 'S',
    scale: 1000,
    datum: 'ARC1960',
    projectionType: 'UTM',
    boundaryPoints: initialPoints.length > 0 ? initialPoints : [],
    abuttalNorth: '',
    abuttalSouth: '',
    abuttalEast: '',
    abuttalWest: '',
    surveyorName: '',
    iskNumber: '',
    firmName: '',
    firmAddress: '',
    surveyDate: new Date().toISOString().split('T')[0],
    signatureDate: new Date().toISOString().split('T')[0]
  })

  // Compute area with confidence interval from boundary points.
  // Uses covariance propagation: assumes each boundary point has ~5mm std dev
  // (typical for cadastral traverse). If the surveyor has LSA covariances,
  // those would be wired in here from the network adjustment result.
  const areaWithUncertainty = useMemo(() => {
    if (input.boundaryPoints.length < 3) return null
    // Default per-point accuracy: 5mm in E and N (typical for closed traverse)
    // Future: wire in actual LSA covariances from the network adjustment
    const sigmaPoint = 0.005
    const vertices = input.boundaryPoints.map(p =>
      coordinate2D(p.easting, p.northing, sigmaPoint, sigmaPoint, 0),
    )
    return polygonArea2D(vertices)
  }, [input.boundaryPoints])

  const handleGenerate = async () => {
    setIsGenerating(true)
    setError(null)
    try {
      const result = await generateDeedPlan(input)
      setOutput(result)
      setStep('preview')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to generate deed plan')
    } finally {
      setIsGenerating(false)
    }
  }

  const handleSave = async () => {
    if (!output) return
    try {
      await saveDeedPlan(projectId, input, output)
      alert('Deed plan saved successfully!')
    } catch (err) {
      alert(err instanceof Error ? err.message : 'Failed to save')
    }
  }

  const handleDownloadSVG = () => {
    if (!output) return
    const blob = new Blob([output.svg], { type: 'image/svg+xml' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `${input.parcelNumber || 'deed-plan'}.svg`
    a.click()
    URL.revokeObjectURL(url)
  }

  const handleDownloadPNG = async () => {
    if (!output) return
    try {
      // A1 at 300 DPI: 9933 x 7016 pixels — use 12x for high quality
      const SCALE = 12
      const svgW = 841
      const svgH = 594
      const imgW = svgW * SCALE
      const imgH = svgH * SCALE

      const svgBlob = new Blob([output.svg], { type: 'image/svg+xml;charset=utf-8' })
      const url = URL.createObjectURL(svgBlob)

      const img = new Image()
      img.onload = () => {
        const canvas = document.createElement('canvas')
        canvas.width = imgW
        canvas.height = imgH
        const ctx = canvas.getContext('2d')
        if (!ctx) {
          URL.revokeObjectURL(url)
          alert('Canvas not supported in this browser')
          return
        }
        // White background
        ctx.fillStyle = 'white'
        ctx.fillRect(0, 0, imgW, imgH)
        // Draw SVG preserving aspect ratio — center if dimensions differ
        const svgAspect = svgW / svgH
        const canvasAspect = imgW / imgH
        let drawW, drawH, drawX, drawY
        if (canvasAspect > svgAspect) {
          // Canvas is wider — fit height
          drawH = imgH
          drawW = imgH * svgAspect
          drawX = (imgW - drawW) / 2
          drawY = 0
        } else {
          // Canvas is taller — fit width
          drawW = imgW
          drawH = imgW / svgAspect
          drawX = 0
          drawY = (imgH - drawH) / 2
        }
        ctx.drawImage(img, drawX, drawY, drawW, drawH)
        URL.revokeObjectURL(url)

        canvas.toBlob((blob) => {
          if (!blob) {
            alert('Failed to create PNG image')
            return
          }
          const pngUrl = URL.createObjectURL(blob)
          const a = document.createElement('a')
          a.href = pngUrl
          a.download = `${input.parcelNumber || 'deed-plan'}_A1_300dpi.png`
          a.click()
          URL.revokeObjectURL(pngUrl)
        }, 'image/png', 1.0)
      }
      img.onerror = () => {
        URL.revokeObjectURL(url)
        alert('Failed to render SVG. Try downloading as SVG instead.')
      }
      img.src = url
    } catch (err) {
      alert('PNG download failed. Try downloading as SVG instead.')
    }
  }

  const handlePrintA3 = () => {
    if (input.boundaryPoints.length < 3) {
      setError('At least 3 boundary points are required to print a deed plan.')
      return
    }
    setError(null)
    printDeedPlan({ input })
  }

  const addBoundaryPoint = () => {
    const index = input.boundaryPoints.length + 1
    setInput({
      ...input,
      boundaryPoints: [
        ...input.boundaryPoints,
        {
          id: `P${index}`,
          easting: 0,
          northing: 0,
          markType: 'CONCRETE_BEACON',
          markStatus: 'SET',
          description: '',
        },
      ],
    })
  }

  const removeBoundaryPoint = (index: number) => {
    setInput({
      ...input,
      boundaryPoints: input.boundaryPoints.filter((_, i) => i !== index),
    })
  }

  return (
    <div className="container mx-auto py-8">
      <h1 className="text-3xl font-bold mb-8">Deed Plan / Survey Plan (Form No. 4)</h1>

      {/* Step Tabs */}
      <div className="flex gap-4 mb-6">
        <button
          onClick={() => setStep('input')}
          className={`px-4 py-2 rounded-lg transition-colors ${step === 'input' ? 'bg-[var(--accent)] text-black font-semibold' : 'border border-[var(--border-color)] text-[var(--text-secondary)] hover:border-[var(--accent)]'}`}
        >
          1. Input
        </button>
        <button
          onClick={() => output && setStep('preview')}
          disabled={!output}
          className={`px-4 py-2 rounded-lg transition-colors ${step === 'preview' ? 'bg-[var(--accent)] text-black font-semibold' : 'border border-[var(--border-color)] text-[var(--text-secondary)] hover:border-[var(--accent)]'} ${!output ? 'opacity-50' : ''}`}
        >
          2. Preview
        </button>
        <button
          onClick={() => output && setStep('export')}
          disabled={!output}
          className={`px-4 py-2 rounded-lg transition-colors ${step === 'export' ? 'bg-[var(--accent)] text-black font-semibold' : 'border border-[var(--border-color)] text-[var(--text-secondary)] hover:border-[var(--accent)]'} ${!output ? 'opacity-50' : ''}`}
        >
          3. Export
        </button>
      </div>

      {error && (
        <div className="mb-6 p-4 border border-red-800/60 bg-red-950/30 text-red-300 rounded-lg flex items-center gap-2">
          <AlertCircle className="h-5 w-5 text-red-400" />
          <span>{error}</span>
        </div>
      )}

      {/* INPUT STEP */}
      {step === 'input' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Project Info */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
            <h2 className="text-xl font-semibold mb-4">Project Information</h2>
            <div className="space-y-4">
              <div>
                <label htmlFor="dpg-survey-number" className="block text-sm font-medium mb-1">Survey Number</label>
                <input
                  id="dpg-survey-number"
                  type="text"
                  value={input.surveyNumber}
                  onChange={(e) => setInput({ ...input, surveyNumber: e.target.value })}
                  className="input w-full text-sm"
                  placeholder="ISK/2024/001"
                />
              </div>
              <div>
                <label htmlFor="dpg-drawing-number" className="block text-sm font-medium mb-1">Drawing Number</label>
                <input id="dpg-drawing-number"
                  type="text"
                  value={input.drawingNumber}
                  onChange={(e) => setInput({ ...input, drawingNumber: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-parcel-number" className="block text-sm font-medium mb-1">Parcel Number</label>
                <input
                  id="dpg-parcel-number"
                  type="text"
                  value={input.parcelNumber}
                  onChange={(e) => setInput({ ...input, parcelNumber: e.target.value })}
                  className="input w-full text-sm"
                  placeholder="LOT 1234/NAIROBI"
                />
              </div>
              <div>
                <label htmlFor="dpg-locality" className="block text-sm font-medium mb-1">Locality</label>
                <input id="dpg-locality"
                  type="text"
                  value={input.locality}
                  onChange={(e) => setInput({ ...input, locality: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-registration-section" className="block text-sm font-medium mb-1">Registration Section</label>
                <input id="dpg-registration-section"
                  type="text"
                  value={input.registrationSection}
                  onChange={(e) => setInput({ ...input, registrationSection: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-county" className="block text-sm font-medium mb-1">County</label>
                <input id="dpg-county"
                  type="text"
                  value={input.county}
                  onChange={(e) => setInput({ ...input, county: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-scale" className="block text-sm font-medium mb-1">Scale</label>
                <select
                  id="dpg-scale"
                  value={input.scale}
                  onChange={(e) => setInput({ ...input, scale: Number(e.target.value) as 500 | 1000 | 2500 | 5000 })}
                  className="input w-full text-sm"
                >
                  {SCALES.map((s: any) => (
                    <option key={s} value={s}>1 : {s}</option>
                  ))}
                </select>
              </div>
              <div>
                <label htmlFor="dpg-datum" className="block text-sm font-medium mb-1">Datum</label>
                <select
                  id="dpg-datum"
                  value={input.datum}
                  onChange={(e) => setInput({ ...input, datum: e.target.value as 'ARC1960' | 'WGS84' })}
                  className="input w-full text-sm"
                >
                  <option value="WGS84">WGS84</option>
                  <option value="ARC1960">ARC1960</option>
                </select>
              </div>
              <div className="mt-4 p-3 border border-[var(--border-color)] rounded">
                <p className="text-xs font-semibold mb-2 text-[var(--text-secondary)] uppercase tracking-wide">SRVY2025-1 & Grid Corrections</p>
                <div className="space-y-3">
                  <div>
                    <label htmlFor="dpg-submission-number" className="block text-xs font-medium mb-1">Submission Number (SRVY2025-1)</label>
                    <input
                      id="dpg-submission-number"
                      type="text"
                      value={input.submissionNumber || ''}
                      onChange={(e) => setInput({ ...input, submissionNumber: e.target.value })}
                      className="input w-full text-sm"
                      placeholder="RS149_2025_001_R00"
                    />
                    <p className="text-xs text-[var(--text-muted)] mt-1">Format: RS###_YYYY_###_R## — from SRVY2025-1</p>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label htmlFor="dpg-sheet-number" className="block text-xs font-medium mb-1">Sheet No.</label>
                      <input
                        id="dpg-sheet-number"
                        type="number"
                        min="1"
                        value={input.sheetNumber || ''}
                        onChange={(e) => setInput({ ...input, sheetNumber: e.target.value ? Number(e.target.value) : undefined })}
                        className="input w-full text-sm"
                        placeholder="1"
                      />
                    </div>
                    <div>
                      <label htmlFor="dpg-total-sheets" className="block text-xs font-medium mb-1">Total Sheets</label>
                      <input
                        id="dpg-total-sheets"
                        type="number"
                        min="1"
                        value={input.totalSheets || ''}
                        onChange={(e) => setInput({ ...input, totalSheets: e.target.value ? Number(e.target.value) : undefined })}
                        className="input w-full text-sm"
                        placeholder="1"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label htmlFor="dpg-scale-factor" className="block text-xs font-medium mb-1">Scale Factor (SF)</label>
                      <input
                        id="dpg-scale-factor"
                        type="number"
                        step="0.000001"
                        value={input.scaleFactor || ''}
                        onChange={(e) => setInput({ ...input, scaleFactor: e.target.value ? Number(e.target.value) : undefined })}
                        className="input w-full text-sm"
                        placeholder="0.99979"
                      />
                      <p className="text-xs text-[var(--text-muted)] mt-1">Grid-to-Ground correction</p>
                    </div>
                    <div>
                      <label htmlFor="dpg-mean-elevation" className="block text-xs font-medium mb-1">Mean Elevation (m)</label>
                      <input
                        id="dpg-mean-elevation"
                        type="number"
                        step="0.1"
                        value={input.meanElevation ?? ''}
                        onChange={(e) => setInput({ ...input, meanElevation: e.target.value ? Number(e.target.value) : undefined })}
                        className="input w-full text-sm"
                        placeholder="1820.0"
                      />
                    </div>
                  </div>
                  <div>
                    <label htmlFor="dpg-grid-area" className="block text-xs font-medium mb-1">Grid Area (m²)</label>
                    <input
                      id="dpg-grid-area"
                      type="number"
                      step="0.01"
                      value={input.gridArea || ''}
                      onChange={(e) => setInput({ ...input, gridArea: e.target.value ? Number(e.target.value) : undefined })}
                      className="input w-full text-sm"
                      placeholder="Leave blank if not applicable"
                    />
                    <p className="text-xs text-[var(--text-muted)] mt-1">Area from UTM coordinates before SF correction</p>
                  </div>
                  <div>
                    <label htmlFor="dpg-control-class" className="block text-xs font-medium mb-1">Control Class</label>
                    <select
                      id="dpg-control-class"
                      value={input.controlClass || ''}
                      onChange={(e) => setInput({ ...input, controlClass: e.target.value as 'FIRST' | 'SECOND' | 'THIRD' | 'FOURTH' | undefined })}
                      className="input w-full text-sm"
                    >
                      <option value="">Select accuracy class...</option>
                      <option value="FIRST">First Order — 1:50,000 precision</option>
                      <option value="SECOND">Second Order — 1:20,000 precision</option>
                      <option value="THIRD">Third Order — 1:10,000 precision</option>
                      <option value="FOURTH">Fourth Order — 1:5,000 precision</option>
                    </select>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Surveyor Info */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
            <h2 className="text-xl font-semibold mb-4">Surveyor's Certificate</h2>
            <div className="space-y-4">
              <div>
                <label htmlFor="dpg-client-name" className="block text-sm font-medium mb-1">Client Name</label>
                <input
                  id="dpg-client-name"
                  type="text"
                  value={input.clientName || ''}
                  onChange={(e) => setInput({ ...input, clientName: e.target.value })}
                  className="input w-full text-sm"
                  placeholder="Name of the client/owner"
                />
              </div>
              <div>
                <label htmlFor="dpg-surveyor-name" className="block text-sm font-medium mb-1">Surveyor Name</label>
                <input id="dpg-surveyor-name"
                  type="text"
                  value={input.surveyorName}
                  onChange={(e) => setInput({ ...input, surveyorName: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-isk-number" className="block text-sm font-medium mb-1">ISK Number</label>
                <input id="dpg-isk-number"
                  type="text"
                  value={input.iskNumber}
                  onChange={(e) => setInput({ ...input, iskNumber: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-title-deed-number" className="block text-sm font-medium mb-1">Title Deed Number</label>
                <input
                  id="dpg-title-deed-number"
                  type="text"
                  value={input.titleDeedNumber || ''}
                  onChange={(e) => setInput({ ...input, titleDeedNumber: e.target.value })}
                  className="input w-full text-sm"
                  placeholder="e.g. FR No. 583/83"
                />
              </div>
              <div>
                <label htmlFor="dpg-firm-name" className="block text-sm font-medium mb-1">Firm Name</label>
                <input id="dpg-firm-name"
                  type="text"
                  value={input.firmName}
                  onChange={(e) => setInput({ ...input, firmName: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-survey-date" className="block text-sm font-medium mb-1">Survey Date</label>
                <input id="dpg-survey-date"
                  type="date"
                  value={input.surveyDate}
                  onChange={(e) => setInput({ ...input, surveyDate: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
            </div>

            <h3 className="text-lg font-semibold mt-6 mb-4">Abuttals</h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="dpg-abuttal-north" className="block text-sm font-medium mb-1">North</label>
                <input id="dpg-abuttal-north"
                  type="text"
                  value={input.abuttalNorth}
                  onChange={(e) => setInput({ ...input, abuttalNorth: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-abuttal-south" className="block text-sm font-medium mb-1">South</label>
                <input id="dpg-abuttal-south"
                  type="text"
                  value={input.abuttalSouth}
                  onChange={(e) => setInput({ ...input, abuttalSouth: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-abuttal-east" className="block text-sm font-medium mb-1">East</label>
                <input id="dpg-abuttal-east"
                  type="text"
                  value={input.abuttalEast}
                  onChange={(e) => setInput({ ...input, abuttalEast: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
              <div>
                <label htmlFor="dpg-abuttal-west" className="block text-sm font-medium mb-1">West</label>
                <input id="dpg-abuttal-west"
                  type="text"
                  value={input.abuttalWest}
                  onChange={(e) => setInput({ ...input, abuttalWest: e.target.value })}
                  className="input w-full text-sm"
                />
              </div>
            </div>
          </div>

          {/* Boundary Points */}
          <div className="lg:col-span-2 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
            <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
              <h2 className="text-xl font-semibold">Boundary Points</h2>
              <div className="flex flex-wrap gap-2">
                <button
                  type="button"
                  onClick={() => setInput(FOUR_ACRE_SAMPLE)}
                  className="flex items-center gap-2 px-3 py-2 bg-[var(--bg-tertiary)] text-[var(--text-secondary)] border border-[var(--border-color)] rounded-lg hover:border-[var(--accent)] text-sm"
                >
                  <FileText className="h-4 w-4" />
                  Load 4-Acre Sample
                </button>
                <button
                  type="button"
                  onClick={addBoundaryPoint}
                  className="flex items-center gap-2 px-3 py-2 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] text-sm font-semibold"
                >
                  <Plus className="h-4 w-4" />
                  Add Point
                </button>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="text-left py-2">ID</th>
                    <th className="text-left py-2">Easting</th>
                    <th className="text-left py-2">Northing</th>
                    <th className="text-left py-2">Mark Type</th>
                    <th className="text-left py-2">Status</th>
                    <th className="text-left py-2">Description</th>
                    <th className="w-12 py-2"></th>
                  </tr>
                </thead>
                <tbody>
                  {input.boundaryPoints.map((point, i) => (
                    <tr key={point.id} className="border-b">
                      <td className="py-2">
                        <input aria-label="Id"
                          type="text"
                          value={point.id}
                          onChange={(e) => {
                            const newPoints = [...input.boundaryPoints]
                            newPoints[i] = { ...point, id: e.target.value }
                            setInput({ ...input, boundaryPoints: newPoints })
                          }}
                          className="w-24 px-2 py-1 border rounded"
                        />
                      </td>
                      <td className="py-2">
                        <input aria-label="Easting"
                          type="number"
                          value={point.easting}
                          onChange={(e) => {
                            const newPoints = [...input.boundaryPoints]
                            newPoints[i] = { ...point, easting: parseFloat(e.target.value) }
                            setInput({ ...input, boundaryPoints: newPoints })
                          }}
                          className="w-32 px-2 py-1 border rounded"
                        />
                      </td>
                      <td className="py-2">
                        <input aria-label="Northing"
                          type="number"
                          value={point.northing}
                          onChange={(e) => {
                            const newPoints = [...input.boundaryPoints]
                            newPoints[i] = { ...point, northing: parseFloat(e.target.value) }
                            setInput({ ...input, boundaryPoints: newPoints })
                          }}
                          className="w-32 px-2 py-1 border rounded"
                        />
                      </td>
                      <td className="py-2">
                        <select
                          value={point.markType}
                          onChange={(e) => {
                            const newPoints = [...input.boundaryPoints]
                            newPoints[i] = { ...point, markType: e.target.value as BeaconType }
                            setInput({ ...input, boundaryPoints: newPoints })
                          }}
                          className="px-2 py-1 border rounded"
                        >
                          {MARK_TYPES.map((t: any) => (
                            <option key={t} value={t}>{t}</option>
                          ))}
                        </select>
                      </td>
                      <td className="py-2">
                        <select
                          value={point.markStatus}
                          onChange={(e) => {
                            const newPoints = [...input.boundaryPoints]
                            newPoints[i] = { ...point, markStatus: e.target.value as 'FOUND' | 'SET' | 'REFERENCED' }
                            setInput({ ...input, boundaryPoints: newPoints })
                          }}
                          className="px-2 py-1 border rounded"
                        >
                          {MARK_STATUSES.map((s: any) => (
                            <option key={s} value={s}>{s}</option>
                          ))}
                        </select>
                      </td>
                      <td className="py-2">
                        <input
                          type="text"
                          value={point.description || ''}
                          onChange={(e) => {
                            const newPoints = [...input.boundaryPoints]
                            newPoints[i] = { ...point, description: e.target.value }
                            setInput({ ...input, boundaryPoints: newPoints })
                          }}
                          className="w-48 px-2 py-1 border rounded"
                          aria-label="Beacon description" placeholder="Beacon description"
                        />
                      </td>
                      <td className="py-2 text-right">
                        <button
                          type="button"
                          onClick={() => removeBoundaryPoint(i)}
                          className="inline-flex h-8 w-8 items-center justify-center rounded border text-red-600 hover:bg-red-50"
                          aria-label={`Remove ${point.id}`}
                        >
                          <Trash2 className="h-4 w-4" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="lg:col-span-2 flex justify-end gap-3">
            <button
              onClick={handlePrintA3}
              disabled={input.boundaryPoints.length < 3}
              className="flex items-center gap-2 px-6 py-3 bg-[var(--bg-tertiary)] text-[var(--text-primary)] border border-[var(--border-color)] rounded-lg hover:border-[var(--accent)] disabled:opacity-50"
            >
              <Printer className="h-5 w-5" />
              Print A3 Deed Plan
            </button>
            <button
              onClick={handleGenerate}
              disabled={isGenerating}
              className="flex items-center gap-2 px-6 py-3 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] disabled:opacity-50 font-bold"
            >
              {isGenerating ? (
                <>Generating...</>
              ) : (
                <>
                  <FileText className="h-5 w-5" />
                  Generate Deed Plan
                </>
              )}
            </button>
          </div>
        </div>
      )}

      {/* PREVIEW STEP */}
      {step === 'preview' && output && (
        <div className="space-y-6">
          {/* Closure Check Badge */}
          <div className={`flex items-center gap-4 p-4 rounded-lg border ${output.closureCheck.passes ? 'border-green-700/60 bg-green-950/30 text-green-300' : 'border-red-700/60 bg-red-950/30 text-red-300'}`}>
            {output.closureCheck.passes ? (
              <CheckCircle className="h-6 w-6 text-green-500" />
            ) : (
              <AlertCircle className="h-6 w-6 text-red-500" />
            )}
            <div>
              <span className="font-semibold">Precision Ratio: {output.closureCheck.precisionRatio}</span>
              <span className="ml-2 text-sm text-gray-600">
                ({output.closureCheck.passes ? 'PASSES' : 'FAILS'} - minimum 1:5000 required)
              </span>
            </div>
            <div className="ml-auto text-sm">
              Perimeter: {output.closureCheck.perimeter.toFixed(2)}m
            </div>
          </div>

          {/* Area with Confidence Interval — for statutory submissions */}
          {areaWithUncertainty && (
            <div className="flex items-center gap-4 p-4 rounded-lg border border-blue-700/60 bg-blue-950/20">
              <Ruler className="h-6 w-6 text-blue-400 shrink-0" />
              <div className="flex-1">
                <div className="font-semibold text-blue-200">
                  Computed Area: {formatScalarWithCI(areaWithUncertainty, { unit: 'm²', decimals: 2 })}
                </div>
                <div className="text-xs text-gray-500 mt-1">
                  Confidence interval derived from boundary point uncertainties via covariance propagation (Var(A) = J·Σ·Jᵀ).
                  Assumes 5mm per-point accuracy — replace with LSA covariances for sub-cm precision.
                </div>
              </div>
              <div className="text-right text-xs">
                <div className="text-gray-400">Std Dev</div>
                <div className="font-mono text-blue-300">
                  ±{scalarCI(areaWithUncertainty).stdDev.toFixed(4)} m²
                </div>
              </div>
            </div>
          )}

          {/* SVG Preview */}
          <div className="bg-white rounded-lg p-4 border overflow-auto">
            <div
              className="mx-auto"
              dangerouslySetInnerHTML={{ __html: output.svg }}
            />
          </div>

          <div className="flex gap-4">
            <button
              onClick={() => setStep('export')}
              className="flex items-center gap-2 px-6 py-3 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] font-bold"
            >
              Continue to Export
            </button>
          </div>
        </div>
      )}

      {/* EXPORT STEP */}
      {step === 'export' && output && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <button
              onClick={handlePrintA3}
              className="flex items-center justify-center gap-2 px-6 py-4 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] font-bold"
            >
              <Printer className="h-5 w-5" />
              Print A3 Deed Plan
            </button>
            <button
              onClick={handleDownloadPNG}
              className="flex items-center justify-center gap-2 px-6 py-4 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] font-bold"
            >
              <Download className="h-5 w-5" />
              Download PNG (A1 300dpi)
            </button>
            <button
              onClick={handleDownloadSVG}
              className="flex items-center justify-center gap-2 px-6 py-4 bg-[var(--bg-tertiary)] text-[var(--text-primary)] border border-[var(--border-color)] rounded-lg hover:border-[var(--accent)]"
            >
              <Download className="h-5 w-5" />
              Download SVG
            </button>
            <button
              onClick={handleSave}
              className="flex items-center justify-center gap-2 px-6 py-4 bg-[var(--accent)] text-black rounded-lg hover:bg-[var(--accent-dim)] font-bold"
            >
              <Save className="h-5 w-5" />
              Save to Project
            </button>
          </div>

          {/* Bearing Schedule */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
            <h3 className="text-lg font-semibold mb-4">Bearing Schedule</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-sm min-w-[480px]">
                <thead>
                  <tr className="border-b">
                    <th className="text-left py-2">Leg</th>
                    <th className="text-left py-2">From</th>
                    <th className="text-left py-2">To</th>
                    <th className="text-left py-2">Bearing (WCB)</th>
                    <th className="text-right py-2">Distance (m)</th>
                  </tr>
                </thead>
                <tbody>
                  {output.bearingSchedule.map((leg, i) => (
                    <tr key={`${leg}-${i}`} className="border-b">
                      <td className="py-2">{i + 1}</td>
                      <td className="py-2">{leg.fromPoint}</td>
                      <td className="py-2">{leg.toPoint}</td>
                      <td className="py-2 font-mono">{leg.bearing}</td>
                      <td className="py-2 text-right">{leg.distance.toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Beacon Description Schedule */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
            <h3 className="text-lg font-semibold mb-4">Beacon Description Schedule</h3>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b">
                    <th className="text-left py-2">Beacon ID</th>
                    <th className="text-left py-2">Mark Type</th>
                    <th className="text-left py-2">Status</th>
                    <th className="text-left py-2">Description</th>
                  </tr>
                </thead>
                <tbody>
                  {input.boundaryPoints.map((point) => (
                    <tr key={point.id} className="border-b">
                      <td className="py-2 font-semibold">{point.id}</td>
                      <td className="py-2">{point.markType}</td>
                      <td className="py-2">{point.markStatus || '—'}</td>
                      <td className="py-2">{point.description || '—'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import DeedPlanGenerator from '@/components/deedplan/DeedPlanGenerator'
import type { BoundaryPoint } from '@/types/deedPlan'
import type { BeaconType, BeaconStatus } from '@/types/deedPlan'

/**
 * ProjectDeedPlan — wrapper that connects DeedPlanGenerator to a real project.
 *
 * Fetches the project's survey points from /api/project/[id]/points and
 * converts them to BoundaryPoint[] format for DeedPlanGenerator's initialPoints.
 *
 * This is the "missing wire" — previously the deed plan page used
 * projectId="new" with no project data. Now a surveyor can:
 * 1. Run traverse adjustment in their project
 * 2. Go to the deed plan step
 * 3. See their adjusted coordinates auto-populated
 *
 * Usage:
 *   <ProjectDeedPlan projectId="abc-123" />
 *   // or as a route: /deed-plan?project=abc-123
 */

interface ProjectDeedPlanProps {
  projectId: string
}

interface SurveyPoint {
  id: string
  point_name: string
  easting: number
  northing: number
  elevation: number | null
  code: string | null
  description: string | null
  is_control: boolean
}

// Default beacon type/status when converting survey points to boundary points
const DEFAULT_MARK_TYPE: BeaconType = 'CONCRETE_BEACON'
const DEFAULT_MARK_STATUS: BeaconStatus = 'SET'

function surveyPointToBoundaryPoint(p: SurveyPoint): BoundaryPoint {
  return {
    id: p.point_name || p.id,
    easting: p.easting,
    northing: p.northing,
    elevation: p.elevation ?? undefined,
    markType: DEFAULT_MARK_TYPE,
    markStatus: DEFAULT_MARK_STATUS,
    description: p.description || p.code || undefined,
  }
}

export default function ProjectDeedPlan({ projectId }: ProjectDeedPlanProps) {
  const [points, setPoints] = useState<BoundaryPoint[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false

    async function fetchPoints() {
      try {
        setLoading(true)
        setError(null)
        const res = await fetch(`/api/project/${projectId}/points`)
        if (!res.ok) {
          throw new Error(`Failed to load project points (${res.status})`)
        }
        const json = await res.json()
        const surveyPoints: SurveyPoint[] = json.data || []
        const boundaryPoints = surveyPoints.map(surveyPointToBoundaryPoint)
        if (!cancelled) {
          setPoints(boundaryPoints)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to load project points')
        }
      } finally {
        if (!cancelled) {
          setLoading(false)
        }
      }
    }

    if (projectId && projectId !== 'new') {
      fetchPoints()
    } else {
      setLoading(false)
    }

    return () => {
      cancelled = true
    }
  }, [projectId])

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-12">
        <div className="font-mono text-xs text-[var(--text-muted)] tracking-[0.04em] uppercase">
          Loading project coordinates...
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-12">
        <div className="border border-[var(--error)]/30 bg-[var(--error)]/5 p-4 rounded-md">
          <p className="font-mono text-xs text-[var(--error)] tracking-[0.04em] uppercase mb-2">
            Could not load project points
          </p>
          <p className="text-sm text-[var(--text-secondary)] mb-4">{error}</p>
          <p className="text-xs text-[var(--text-muted)]">
            You can still create a deed plan manually — your project coordinates
            will not be auto-populated.
          </p>
        </div>
        <div className="mt-6">
          <DeedPlanGenerator projectId={projectId} initialPoints={[]} />
        </div>
      </div>
    )
  }

  return (
    <div>
      {points.length > 0 && (
        <div className="max-w-7xl mx-auto px-4 mb-4">
          <div className="border border-[var(--accent)]/30 bg-[var(--accent)]/5 p-3 rounded-md flex items-center gap-3">
            <svg className="w-4 h-4 text-[var(--accent)] shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <p className="text-xs text-[var(--text-secondary)]">
              <span className="font-mono text-[var(--accent)]">{points.length} points</span>{' '}
              auto-populated from project survey data. Adjust beacon types and statuses
              below before generating the plan.
            </p>
          </div>
        </div>
      )}
      <DeedPlanGenerator projectId={projectId} initialPoints={points} />
    </div>
  )
}

'use client';

/**
 * LogoUpload Component
 *
 * Drag & drop or click to upload company logo.
 * - Shows plan restriction for free users (upgrade CTA)
 * - Preview current logo
 * - Remove logo button
 * - Validates: max 2MB, PNG/JPG/SVG only
 * - Crop/resize to fit document header (max 200x60px in document)
 */

import { useCallback, useRef, useState } from 'react';
import type { PlanId } from '@/lib/subscription/catalog';
import SubscriptionBadge from '@/components/SubscriptionBadge';

interface LogoInfo {
  id: string;
  filename: string;
  mimeType: string;
  fileSize: number;
  widthPx?: number;
  heightPx?: number;
  createdAt: string;
}

interface LogoUploadProps {
  /** Current plan of the user */
  plan: PlanId;
  /** Existing logo (if any), fetched server-side */
  existingLogo?: LogoInfo | null;
  /** Callback after successful upload */
  onUploadSuccess?: (logo: LogoInfo) => void;
  /** Callback after successful delete */
  onDeleteSuccess?: () => void;
}

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB
const ALLOWED_TYPES = ['image/png', 'image/jpeg', 'image/svg+xml'];
const ALLOWED_EXTENSIONS = '.png, .jpg, .jpeg, .svg';

export default function LogoUpload({
  plan,
  existingLogo,
  onUploadSuccess,
  onDeleteSuccess,
}: LogoUploadProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [logo, setLogo] = useState<LogoInfo | null>(existingLogo ?? null);
  const [preview, setPreview] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const isFree = plan === 'free';

  // Read file and create preview
  const processFile = useCallback((file: File) => {
    setError(null);

    if (!ALLOWED_TYPES.includes(file.type)) {
      setError(`Invalid format. Allowed: ${ALLOWED_EXTENSIONS}`);
      return;
    }

    if (file.size > MAX_FILE_SIZE) {
      setError('File too large. Maximum size: 2MB.');
      return;
    }

    // Create preview URL
    const reader = new FileReader();
    reader.onload = (e) => {
      setPreview(e.target?.result as string);
    };
    reader.readAsDataURL(file);

    // Upload the file
    uploadLogo(file);
  }, []);

  const uploadLogo = async (file: File) => {
    setUploading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('logo', file);

      const res = await fetch('/api/documents/logo', {
        method: 'POST',
        body: formData,
      });

      const data = await res.json();

      if (!res.ok) {
        if (data.upgradeRequired) {
          setError('Upgrade to Pro or higher to upload your company logo.');
        } else {
          setError(data.error || 'Upload failed');
        }
        setPreview(null);
        return;
      }

      // Fetch the updated logo metadata
      const metaRes = await fetch('/api/documents/logo');
      const metaData = await metaRes.json();

      if (metaData.logo) {
        setLogo(metaData.logo);
        onUploadSuccess?.(metaData.logo);
      }
    } catch (err) {
      console.error('[LogoUpload] Upload error:', err);
      setError('Upload failed. Please try again.');
      setPreview(null);
    } finally {
      setUploading(false);
    }
  };

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setDragOver(false);

      if (isFree) return;

      const file = e.dataTransfer.files[0];
      if (file) processFile(file);
    },
    [isFree, processFile]
  );

  const handleDragOver = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      if (!isFree) setDragOver(true);
    },
    [isFree]
  );

  const handleDragLeave = useCallback(() => {
    setDragOver(false);
  }, []);

  const handleFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) processFile(file);
    },
    [processFile]
  );

  const handleDelete = async () => {
    setDeleting(true);
    setError(null);

    try {
      const res = await fetch('/api/documents/logo', { method: 'DELETE' });

      if (!res.ok) {
        const data = await res.json();
        setError(data.error || 'Delete failed');
        return;
      }

      setLogo(null);
      setPreview(null);
      onDeleteSuccess?.();
    } catch (err) {
      console.error('[LogoUpload] Delete error:', err);
      setError('Delete failed. Please try again.');
    } finally {
      setDeleting(false);
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  // ─── Free tier: locked state ─────────────────────────────────────
  if (isFree) {
    return (
      <div className="rounded-lg border border-dashed border-[var(--border-color)] p-6 text-center">
        <div className="flex items-center justify-center gap-2 mb-3">
          <svg
            className="w-8 h-8 text-[var(--text-secondary)]"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={1.5}
              d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
            />
          </svg>
          <SubscriptionBadge plan={plan} compact />
        </div>
        <p className="text-sm text-[var(--text-secondary)] mb-2">
          Custom company logos are available on Pro and higher plans.
        </p>
        <p className="text-xs text-[var(--text-tertiary)] mb-4">
          Free tier documents use the METARDU watermark.
        </p>
        <a
          href="/pricing"
          className="inline-flex items-center gap-1 px-4 py-2 text-sm font-semibold rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-colors"
        >
          Upgrade to Pro
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
          </svg>
        </a>
      </div>
    );
  }

  // ─── Paid tier: upload interface ──────────────────────────────────
  const displaySrc = preview || (logo ? `/api/documents/logo/data` : null);

  return (
    <div className="space-y-4">
      {/* Current logo preview */}
      {displaySrc && (
        <div className="flex items-center gap-4 p-4 rounded-lg bg-[var(--bg-secondary)] border border-[var(--border-color)]">
          <div className="flex-shrink-0 w-[200px] h-[60px] bg-white rounded border border-gray-200 flex items-center justify-center overflow-hidden">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={displaySrc}
              alt="Company logo preview"
              className="max-w-full max-h-full object-contain"
              style={{ maxWidth: '200px', maxHeight: '60px' }}
            />
          </div>
          <div className="flex-1 min-w-0">
            {logo && (
              <div className="text-sm">
                <p className="font-medium truncate">{logo.filename}</p>
                <p className="text-xs text-[var(--text-secondary)]">
                  {formatFileSize(logo.fileSize)}
                  {logo.widthPx && logo.heightPx && (
                    <> &middot; {logo.widthPx}×{logo.heightPx}px</>
                  )}
                </p>
              </div>
            )}
            <p className="text-xs text-[var(--text-tertiary)] mt-1">
              Document size: 200×60px max
            </p>
          </div>
          <button
            type="button"
            onClick={handleDelete}
            disabled={deleting}
            className="flex-shrink-0 px-3 py-1.5 text-sm rounded-md border border-red-300 text-red-600 hover:bg-red-50 dark:hover:bg-red-950/30 transition-colors disabled:opacity-50"
          >
            {deleting ? 'Removing…' : 'Remove'}
          </button>
        </div>
      )}

      {/* Drop zone */}
      {!displaySrc && (
        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onClick={() => fileInputRef.current?.click()}
          className={`
            rounded-lg border-2 border-dashed p-8 text-center cursor-pointer transition-colors
            ${dragOver
              ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/20'
              : 'border-[var(--border-color)] hover:border-emerald-400 hover:bg-[var(--bg-secondary)]'
            }
          `}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              fileInputRef.current?.click();
            }
          }}
          aria-label="Upload company logo"
        >
          <svg
            className="w-10 h-10 mx-auto text-[var(--text-secondary)] mb-3"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={1.5}
              d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
            />
          </svg>
          <p className="text-sm font-medium text-[var(--text-primary)]">
            {uploading ? 'Uploading…' : 'Drop your logo here or click to browse'}
          </p>
          <p className="text-xs text-[var(--text-secondary)] mt-1">
            PNG, JPG, or SVG &middot; Max 2MB
          </p>
        </div>
      )}

      {/* Change logo link when logo exists */}
      {displaySrc && (
        <button
          type="button"
          onClick={() => fileInputRef.current?.click()}
          disabled={uploading}
          className="text-sm text-emerald-600 hover:text-emerald-700 font-medium disabled:opacity-50"
        >
          {uploading ? 'Uploading…' : 'Change logo'}
        </button>
      )}

      {/* Hidden file input */}
      <input
        ref={fileInputRef}
        type="file"
        accept={ALLOWED_EXTENSIONS}
        onChange={handleFileChange}
        className="hidden"
        aria-hidden="true"
      />

      {/* Error display */}
      {error && (
        <div className="flex items-start gap-2 p-3 rounded-md bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800">
          <svg
            className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            aria-hidden="true"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <p className="text-sm text-red-700 dark:text-red-400">{error}</p>
        </div>
      )}
    </div>
  );
}

'use client'

/**
 * VersionHistory — Survey plan version tracking with diff viewer
 *
 * Features:
 * - Shows chronological list of document/plan versions
 * - Compare two versions side-by-side
 * - Highlights what changed (added/removed/modified fields)
 * - Restore previous version
 *
 * Each version tracks:
 * - Version number, timestamp, author
 * - What changed (area, boundaries, beacons, surveyor)
 * - PDF preview link
 */

import { useState, useMemo, useCallback } from 'react'
import {
  History, GitBranch, FileText, Clock, Check, X,
  ArrowRight, Loader2, Download, RotateCcw, Eye,
  Plus, Minus, Edit3,
} from 'lucide-react'

export interface PlanVersion {
  id: string
  versionNumber: number
  timestamp: string
  author: string
  changes: string[]
  // Document data at this version
  data: {
    parcelNumber?: string
    areaHectares?: number
    surveyorName?: string
    surveyorLicense?: string
    beaconCount?: number
    boundaryLength?: number
    status?: string
  }
  pdfUrl?: string
}

interface VersionHistoryProps {
  versions: PlanVersion[]
  onRestore?: (version: PlanVersion) => void
}

export function VersionHistory({ versions, onRestore }: VersionHistoryProps) {
  const [selectedVersions, setSelectedVersions] = useState<[string | null, string | null]>([null, null])
  const [showDiff, setShowDiff] = useState(false)

  const sortedVersions = useMemo(() =>
    [...versions].sort((a, b) => b.versionNumber - a.versionNumber),
    [versions]
  )

  const handleSelect = useCallback((id: string) => {
    setSelectedVersions(prev => {
      if (prev[0] === null) return [id, null]
      if (prev[1] === null && prev[0] !== id) return [prev[0], id]
      if (prev[0] === id) return [null, prev[1]]
      if (prev[1] === id) return [prev[0], null]
      return [id, null]
    })
  }, [])

  const canCompare = selectedVersions[0] && selectedVersions[1]

  const v1 = sortedVersions.find(v => v.id === selectedVersions[0])
  const v2 = sortedVersions.find(v => v.id === selectedVersions[1])

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="card p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
              <History className="w-4 h-4 text-[var(--accent)]" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-[var(--text-primary)]">Version History</h2>
              <p className="text-[10px] text-gray-500">{versions.length} versions — select 2 to compare</p>
            </div>
          </div>
          {canCompare && (
            <button
              onClick={() => setShowDiff(!showDiff)}
              className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-medium hover:bg-[var(--accent)]/20"
            >
              <GitBranch className="w-3.5 h-3.5" />
              {showDiff ? 'Hide Diff' : 'Compare'}
            </button>
          )}
        </div>
      </div>

      {/* Diff viewer */}
      {showDiff && v1 && v2 && (
        <VersionDiff v1={v1} v2={v2} />
      )}

      {/* Version list */}
      <div className="card p-4">
        {sortedVersions.length === 0 ? (
          <div className="text-center py-8">
            <History className="w-8 h-8 text-gray-600 mx-auto mb-2" />
            <p className="text-sm text-gray-500">No version history yet</p>
            <p className="text-[10px] text-gray-600 mt-1">Versions are created when you save changes to a plan.</p>
          </div>
        ) : (
          <div className="space-y-2">
            {sortedVersions.map((version, idx) => {
              const isSelected = selectedVersions.includes(version.id)
              const isLatest = idx === 0
              return (
                <div
                  key={version.id}
                  onClick={() => handleSelect(version.id)}
                  className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all ${
                    isSelected
                      ? 'border-[var(--accent)]/30 bg-[var(--accent)]/5'
                      : 'border-[var(--border-color)] hover:border-[var(--accent)]/20'
                  }`}
                >
                  {/* Version badge */}
                  <div className={`shrink-0 w-10 h-10 rounded-lg flex items-center justify-center ${
                    isLatest ? 'bg-emerald-500/10' : 'bg-[var(--bg-tertiary)]'
                  }`}>
                    <span className={`text-xs font-bold ${isLatest ? 'text-emerald-400' : 'text-gray-400'}`}>
                      v{version.versionNumber}
                    </span>
                  </div>

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      {isLatest && (
                        <span className="text-[9px] px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-400 font-medium uppercase">
                          Current
                        </span>
                      )}
                      <span className="text-xs font-medium text-[var(--text-primary)]">
                        {version.author}
                      </span>
                      <span className="text-[10px] text-gray-500 flex items-center gap-0.5">
                        <Clock className="w-2.5 h-2.5" />
                        {new Date(version.timestamp).toLocaleDateString('en-KE', {
                          month: 'short', day: 'numeric', year: 'numeric',
                          hour: '2-digit', minute: '2-digit',
                        })}
                      </span>
                    </div>

                    {/* Changes */}
                    {version.changes.length > 0 && (
                      <div className="mt-1 space-y-0.5">
                        {version.changes.map((change, i) => (
                          <div key={`${change}-${i}`} className="flex items-center gap-1 text-[10px] text-gray-500">
                            <Edit3 className="w-2.5 h-2.5 text-gray-600" />
                            {change}
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Data summary */}
                    <div className="flex items-center gap-3 mt-1.5 text-[10px] text-gray-600">
                      {version.data.areaHectares != null && (
                        <span>{version.data.areaHectares.toFixed(4)} ha</span>
                      )}
                      {version.data.beaconCount != null && (
                        <span>{version.data.beaconCount} beacons</span>
                      )}
                      {version.data.surveyorName && (
                        <span className="truncate">{version.data.surveyorName}</span>
                      )}
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-1 shrink-0">
                    {version.pdfUrl && (
                      <a
                        href={version.pdfUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        onClick={e => e.stopPropagation()}
                        className="w-7 h-7 flex items-center justify-center rounded text-gray-400 hover:text-[var(--accent)]"
                        title="View PDF"
                      >
                        <Eye className="w-3.5 h-3.5" />
                      </a>
                    )}
                    {!isLatest && onRestore && (
                      <button
                        onClick={(e) => { e.stopPropagation(); onRestore(version) }}
                        className="w-7 h-7 flex items-center justify-center rounded text-gray-400 hover:text-amber-400"
                        title="Restore this version"
                      >
                        <RotateCcw className="w-3.5 h-3.5" />
                      </button>
                    )}
                    {isSelected && (
                      <Check className="w-3.5 h-3.5 text-[var(--accent)]" />
                    )}
                  </div>
                </div>
              )
            })}
          </div>
        )}
      </div>
    </div>
  )
}

// ─── Version Diff Viewer ─────────────────────────────────────────────

function VersionDiff({ v1, v2 }: { v1: PlanVersion; v2: PlanVersion }) {
  const diffs = useMemo(() => {
    const result: Array<{
      field: string
      v1Value: string
      v2Value: string
      type: 'added' | 'removed' | 'modified'
    }> = []

    const fields: Array<{ key: keyof PlanVersion['data']; label: string; format?: (v: any) => string }> = [
      { key: 'parcelNumber', label: 'Parcel Number' },
      { key: 'areaHectares', label: 'Area (ha)', format: (v: number) => v.toFixed(4) },
      { key: 'surveyorName', label: 'Surveyor' },
      { key: 'surveyorLicense', label: 'License' },
      { key: 'beaconCount', label: 'Beacons' },
      { key: 'boundaryLength', label: 'Boundary Length (m)', format: (v: number) => v.toFixed(2) },
      { key: 'status', label: 'Status' },
    ]

    for (const field of fields) {
      const val1 = v1.data[field.key]
      const val2 = v2.data[field.key]
      const fmt = field.format || ((v: any) => String(v))

      if (val1 === val2) continue

      if (val1 == null && val2 != null) {
        result.push({ field: field.label, v1Value: '—', v2Value: fmt(val2), type: 'added' })
      } else if (val1 != null && val2 == null) {
        result.push({ field: field.label, v1Value: fmt(val1), v2Value: '—', type: 'removed' })
      } else if (val1 != null && val2 != null) {
        result.push({ field: field.label, v1Value: fmt(val1), v2Value: fmt(val2), type: 'modified' })
      }
    }

    return result
  }, [v1, v2])

  // Ensure v2 is the newer version
  const newer = v2.versionNumber > v1.versionNumber ? v2 : v1
  const older = v2.versionNumber > v1.versionNumber ? v1 : v2

  return (
    <div className="card p-4">
      <div className="flex items-center gap-2 mb-3">
        <GitBranch className="w-4 h-4 text-[var(--accent)]" />
        <span className="text-sm font-semibold text-[var(--text-primary)]">
          Comparing v{older.versionNumber} → v{newer.versionNumber}
        </span>
      </div>

      {diffs.length === 0 ? (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20">
          <Check className="w-4 h-4 text-emerald-400" />
          <p className="text-xs text-emerald-400">No differences — versions are identical</p>
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-[var(--border-color)]">
                <th className="px-3 py-2 text-left text-[9px] text-gray-500 uppercase tracking-wider">Field</th>
                <th className="px-3 py-2 text-left text-[9px] text-gray-500 uppercase tracking-wider">v{older.versionNumber}</th>
                <th className="px-3 py-2 text-left text-[9px] text-gray-500 uppercase tracking-wider">v{newer.versionNumber}</th>
                <th className="px-3 py-2 text-center text-[9px] text-gray-500 uppercase tracking-wider">Change</th>
              </tr>
            </thead>
            <tbody>
              {diffs.map((diff, i) => (
                <tr key={diff.field} className="border-b border-[var(--border-color)]/50">
                  <td className="px-3 py-2 text-xs text-[var(--text-primary)] font-medium">{diff.field}</td>
                  <td className="px-3 py-2 text-xs text-gray-400 font-mono">
                    {diff.type === 'added' ? '—' : diff.v1Value}
                  </td>
                  <td className="px-3 py-2 text-xs text-[var(--text-primary)] font-mono">
                    {diff.type === 'removed' ? '—' : diff.v2Value}
                  </td>
                  <td className="px-3 py-2 text-center">
                    {diff.type === 'added' && (
                      <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-emerald-500/10 text-emerald-400 text-[9px] font-medium">
                        <Plus className="w-2.5 h-2.5" /> Added
                      </span>
                    )}
                    {diff.type === 'removed' && (
                      <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-red-500/10 text-red-400 text-[9px] font-medium">
                        <Minus className="w-2.5 h-2.5" /> Removed
                      </span>
                    )}
                    {diff.type === 'modified' && (
                      <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-amber-500/10 text-amber-400 text-[9px] font-medium">
                        <Edit3 className="w-2.5 h-2.5" /> Modified
                      </span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, useEffect, useMemo } from 'react';
import { z } from 'zod';
import Konva from 'konva';
import { logEngineeringCompute } from '@/lib/engineering/compute';
import { initialiseDXFLayers, addStandardTitleBlock, DXF_LAYERS } from '@/lib/drawing/dxfLayers';

const CrossSectionSchema = z.object({
  stations: z.array(z.object({
    chainage: z.number(),
    groundLevel: z.number(),
    formationLevel: z.number(),
  })),
  sideSlope: z.number().min(1).default(1.5),
});

export interface CrossSectionProps {
  stations: Array<{ chainage: number; groundLevel: number; formationLevel: number }>;
  projectId?: string;
  sideSlope?: number;
  width?: number;
  height?: number;
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
}

export function CrossSection({
  stations,
  projectId,
  sideSlope = 1.5,
  width = 920,
  height = 520,
  projectData,
  surveyorProfile,
}: CrossSectionProps) {
  const [selectedStation, setSelectedStation] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const validated = useMemo(() => {
    try {
      return CrossSectionSchema.parse({ stations, sideSlope });
    } catch {
      return null;
    }
  }, [stations, sideSlope]);

  const sections = useMemo(() => {
    if (!validated) return [];
    
    return validated.stations.map((station, i) => {
      const prev = validated.stations[i - 1];
      if (!prev) return { ...station, cutFillArea: 0, cutVolume: 0, fillVolume: 0 };

      const leftCut = Math.max(0, prev.groundLevel - prev.formationLevel);
      const rightCut = Math.max(0, station.groundLevel - station.formationLevel);

      const area = ((leftCut + rightCut) / 2) * (station.chainage - prev.chainage);
      const cutVolume = Math.max(0, area);
      const fillVolume = Math.max(0, -area);

      return { 
        ...station, 
        cutFillArea: area, 
        cutVolume, 
        fillVolume 
      };
    });
  }, [validated]);

  const totalCut = useMemo(() => sections.reduce((sum, s) => sum + s.cutVolume, 0), [sections]);
  const totalFill = useMemo(() => sections.reduce((sum, s) => sum + s.fillVolume, 0), [sections]);

  useEffect(() => {
    if (!containerRef.current || stations.length === 0 || !validated) return;

    const stage = new Konva.Stage({
      container: containerRef.current,
      width,
      height,
    });
    const layer = new Konva.Layer();
    stage.add(layer);

    const spacing = width / stations.length;
    const baseLevel = 1600;
    const vScale = 8;

    stations.forEach((station, i) => {
      const x = spacing * i + spacing / 2;
      const groundY = height / 2 - (station.groundLevel - baseLevel) * vScale;
      const formationY = height / 2 - (station.formationLevel - baseLevel) * vScale;

      layer.add(new Konva.Line({
        points: [x - 40, groundY, x + 40, groundY],
        stroke: '#22c55e',
        strokeWidth: 3,
      }));

      layer.add(new Konva.Line({
        points: [x - 40, formationY, x + 40, formationY],
        stroke: '#eab308',
        strokeWidth: 3,
      }));

      const slopeOffset = 40 / sideSlope;
      layer.add(new Konva.Line({
        points: [x - 40, groundY, x - 40 - slopeOffset, formationY],
        stroke: '#666',
        strokeWidth: 2,
      }));
      layer.add(new Konva.Line({
        points: [x + 40, groundY, x + 40 + slopeOffset, formationY],
        stroke: '#666',
        strokeWidth: 2,
      }));

      layer.add(new Konva.Text({
        x: x - 25,
        y: height - 40,
        text: `CH ${station.chainage.toFixed(0)}`,
        fontSize: 11,
        fill: '#aaa',
      }));
    });

    layer.draw();
    return () => {
      stage.destroy();
    };
  }, [stations, sideSlope, width, height, validated]);

  const exportBatchDXF = async () => {
    const { default: Drawing } = await import('dxf-writer');
    const drawing = new Drawing();
    initialiseDXFLayers(drawing);

    addStandardTitleBlock(drawing, {
      drawingTitle: 'CROSS SECTION SURVEY',
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00',
    });

    const baseLevel = 1600;
    const hScale = 1 / 100;
    const vScale = 1 / 100;

    sections.forEach((station, i) => {
      const xOffset = i * 50;
      const groundY = (station.groundLevel - baseLevel) * vScale;
      const formationY = (station.formationLevel - baseLevel) * vScale;

      drawing.setActiveLayer(DXF_LAYERS.PROFILE.name);
      drawing.drawLine(
        xOffset, groundY,
        xOffset + 20, groundY
      );

      drawing.setActiveLayer(DXF_LAYERS.CENTRELINE.name);
      drawing.drawLine(
        xOffset, formationY,
        xOffset + 20, formationY
      );

      drawing.setActiveLayer(DXF_LAYERS.CHAIN.name);
      drawing.drawText(
        xOffset, groundY + 1,
        0.15, 0,
        `CH${station.chainage.toFixed(0)}`
      );
    });

    logEngineeringCompute('cross_section_batch', { stations: stations.length, sideSlope },
      { totalCut, totalFill }, { projectId });

    const dxfString = drawing.toDxfString();
    const blob = new Blob([dxfString], { type: 'application/dxf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `cross_sections_batch_${projectId || 'export'}.dxf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  if (!validated) {
    return <div className="p-4 text-red-400">Invalid cross-section data</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-lg font-semibold text-[var(--text-primary)]">Cross-Section Batch Renderer</h3>
        <button
          onClick={exportBatchDXF}
          className="bg-orange-500 hover:bg-orange-600 px-5 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
          </svg>
          Export All Stations to DXF
        </button>
      </div>

      <div ref={containerRef} className="bg-[#111] rounded-xl overflow-hidden border border-[var(--border-color)]" />

      <div className="overflow-x-auto border border-[var(--border-color)] rounded-xl">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-[var(--bg-secondary)]">
              <th className="text-left py-3 px-6 text-[var(--text-muted)]">Chainage</th>
              <th className="text-right py-3 px-6 text-[var(--text-muted)]">Ground RL</th>
              <th className="text-right py-3 px-6 text-[var(--text-muted)]">Formation RL</th>
              <th className="text-right py-3 px-6 text-[var(--text-muted)]">Cut (m³)</th>
              <th className="text-right py-3 px-6 text-[var(--text-muted)]">Fill (m³)</th>
            </tr>
          </thead>
          <tbody>
            {sections.map((s, i) => (
              <tr key={`${s}-${i}`} 
                className="border-t border-[var(--border-color)] hover:bg-[var(--bg-secondary)] cursor-pointer"
                onClick={() => setSelectedStation(i)}
              >
                <td className="py-3 px-6 font-medium">{s.chainage.toFixed(0)}</td>
                <td className="py-3 px-6 text-right">{s.groundLevel.toFixed(3)}</td>
                <td className="py-3 px-6 text-right">{s.formationLevel.toFixed(3)}</td>
                <td className="py-3 px-6 text-right text-red-400">{s.cutVolume.toFixed(2)}</td>
                <td className="py-3 px-6 text-right text-green-400">{s.fillVolume.toFixed(2)}</td>
              </tr>
            ))}
          </tbody>
          {sections.length > 0 && (
            <tfoot>
              <tr className="bg-[var(--bg-secondary)] font-semibold">
                <td className="py-3 px-6">Total</td>
                <td></td>
                <td></td>
                <td className="py-3 px-6 text-right text-red-400">{totalCut.toFixed(2)}</td>
                <td className="py-3 px-6 text-right text-green-400">{totalFill.toFixed(2)}</td>
              </tr>
            </tfoot>
          )}
        </table>
      </div>

      <div className="text-xs text-[var(--text-muted)]">
        Side slope 1:{sideSlope} • Prismoidal + end-area method • RDM 1.1 compliant
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react'
import { Download, FileText, Map, Copy, Check, Loader2 } from 'lucide-react'

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

interface ExportPoint {
  name: string
  easting: number
  northing: number
  elevation?: number
}

interface ExportLeg {
  from: string
  to: string
  bearing: number
  distance: number
}

interface DrawingExportToolbarProps {
  projectName: string
  points: ExportPoint[]
  legs?: ExportLeg[]
  className?: string
  /** UTM zone (default 37 for Kenya) */
  utmZone?: number
  /** UTM hemisphere (default 'S' for Kenya) */
  hemisphere?: 'N' | 'S'
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

function triggerDownload(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  URL.revokeObjectURL(url)
}

function safeFileName(name: string, ext: string) {
  const date = new Date().toISOString().split('T')[0]
  return `${name.replace(/\s+/g, '_')}_${date}.${ext}`
}

/* ------------------------------------------------------------------ */
/*  Export handlers                                                    */
/* ------------------------------------------------------------------ */

async function exportDXF(
  projectName: string,
  points: ExportPoint[],
  legs?: ExportLeg[],
): Promise<void> {
  const resp = await fetch('/api/compute/export/dxf', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      projectName,
      points: points.map(p => ({
        name: p.name,
        easting: p.easting,
        northing: p.northing,
        elevation: p.elevation ?? undefined,
        is_control: false,
      })),
      traverseLegs: (legs ?? []).map(l => ({
        from: l.from,
        to: l.to,
        distance: l.distance,
        bearing: l.bearing,
      })),
    }),
  })
  const data = await resp.json()
  if (!resp.ok) throw new Error(data.error || 'DXF export failed')
  const blob = new Blob([data.dxf], { type: 'application/dxf' })
  triggerDownload(blob, data.filename || safeFileName(projectName, 'dxf'))
}

/**
 * UTM to geographic (WGS84) conversion for client-side GeoJSON export.
 * Uses the Karney series expansion — equivalent to Metardu's server-side
 * utmToGeographic() but inline so the toolbar stays a pure client component.
 */
function utmToLatLon(
  easting: number,
  northing: number,
  zone: number,
  hemisphere: 'N' | 'S'
): { lat: number; lon: number } {
  const a = 6378137.0
  const f = 1 / 298.257223563
  const k0 = 0.9996
  const e = Math.sqrt(2 * f - f * f)
  const e2 = e * e
  const e1 = (1 - Math.sqrt(1 - e2)) / (1 + Math.sqrt(1 - e2))
  const falseE = 500000.0
  const falseN = hemisphere === 'S' ? 10000000.0 : 0.0
  const x = easting - falseE
  const y = northing - falseN
  const M = y / k0
  const mu = M / (a * (1 - e2 / 4 - 3 * e2 * e2 / 64 - 5 * e2 * e2 * e2 / 256))
  const e1_2 = e1 * e1
  const e1_3 = e1_2 * e1
  const e1_4 = e1_3 * e1
  const phi1 = mu + (3 * e1 / 2 - 27 * e1_3 / 32) * Math.sin(2 * mu)
    + (21 * e1_2 / 16 - 55 * e1_4 / 32) * Math.sin(4 * mu)
    + (151 * e1_3 / 96) * Math.sin(6 * mu)
    + (1097 * e1_4 / 512) * Math.sin(8 * mu)
  const N1 = a / Math.sqrt(1 - e2 * Math.sin(phi1) * Math.sin(phi1))
  const T1 = Math.tan(phi1) * Math.tan(phi1)
  const C1 = e2 * Math.cos(phi1) * Math.cos(phi1) / (1 - e2)
  const R1 = a * (1 - e2) / Math.pow(1 - e2 * Math.sin(phi1) * Math.sin(phi1), 1.5)
  const D = x / (N1 * k0)
  let lat = phi1 - (N1 * Math.tan(phi1) / R1)
    * (D * D / 2 - (5 + 3 * T1 + 10 * C1 - 4 * C1 * C1 - 9 * e2)
      * D * D * D * D / 24 + (61 + 90 * T1 + 298 * C1 + 45 * T1 * T1
        - 252 * e2 - 3 * C1 * C1) * D * D * D * D * D * D / 720)
  const lon0 = ((zone - 1) * 6 - 180 + 3) * Math.PI / 180
  let lon = lon0 + (D - (1 + 2 * T1 + C1) * D * D * D / 6
    + (5 - 2 * C1 + 28 * T1 - 3 * C1 * C1 + 8 * e2 + 24 * T1 * T1)
    * D * D * D * D * D / 120) / Math.cos(phi1)
  return { lat: lat * 180 / Math.PI, lon: lon * 180 / Math.PI }
}

function exportGeoJSON(
  projectName: string,
  points: ExportPoint[],
  utmZone = 37,
  hemisphere: 'N' | 'S' = 'S',
): void {
  // Convert UTM coordinates to WGS84 (RFC 7946 requires WGS84)
  const wgs84Coords = points.map(p => {
    const ll = utmToLatLon(p.easting, p.northing, utmZone, hemisphere)
    return [ll.lon, ll.lat] as [number, number]
  })
  const isClosed = wgs84Coords.length > 2
  if (isClosed) {
    wgs84Coords.push(wgs84Coords[0]) // close the polygon
  }

  const geojson = {
    type: 'FeatureCollection' as const,
    name: `${projectName}_WGS84`,
    crs: {
      type: 'name',
      properties: {
        name: `urn:ogc:def:crs:EPSG::4326`,
      },
    },
    features: [
      {
        type: 'Feature' as const,
        properties: {
          name: projectName,
          source_crs: `EPSG:${32600 + utmZone}${hemisphere === 'S' ? 0 : 0}`,
          source_zone: `${utmZone}${hemisphere}`,
        },
        geometry: {
          type: isClosed ? ('Polygon' as const) : ('LineString' as const),
          coordinates: isClosed ? [wgs84Coords] : wgs84Coords,
        },
      },
    ],
  }

  const blob = new Blob([JSON.stringify(geojson, null, 2)], {
    type: 'application/geo+json',
  })
  triggerDownload(blob, safeFileName(`${projectName}_WGS84`, 'geojson'))
}

async function exportPDF(
  projectName: string,
  points: ExportPoint[],
): Promise<void> {
  const { default: jsPDF } = await import('jspdf')
  const { default: autoTable } = await import('jspdf-autotable')

  const doc = new jsPDF({ orientation: 'landscape' })

  doc.setFontSize(16)
  doc.text(projectName, 14, 18)

  doc.setFontSize(9)
  doc.setTextColor(120)
  doc.text(`Generated by METARDU  •  ${new Date().toLocaleString()}`, 14, 25)

  const head = [['#', 'Station', 'Easting (m)', 'Northing (m)', 'Elevation (m)']] as any
  const body = points.map((p, i) => [
    i + 1,
    p.name,
    p.easting.toFixed(4),
    p.northing.toFixed(4),
    p.elevation != null ? p.elevation.toFixed(4) : '—',
  ])

  autoTable(doc, {
    startY: 30,
    head,
    body,
    theme: 'grid',
    styles: { fontSize: 9 },
    headStyles: { fillColor: [34, 34, 34] },
  })

  doc.save(safeFileName(projectName, 'pdf'))
}

async function copyCoordinates(points: ExportPoint[]): Promise<void> {
  const header = 'Station\tEasting\tNorthing'
  const rows = points.map(
    p => `${p.name}\t${p.easting.toFixed(4)}\t${p.northing.toFixed(4)}`,
  )
  const text = [header, ...rows].join('\n')

  try {
    await navigator.clipboard.writeText(text)
  } catch {
    const ta = document.createElement('textarea')
    ta.value = text
    document.body.appendChild(ta)
    ta.select()
    document.execCommand('copy')
    document.body.removeChild(ta)
  }
}

