'use client';

import { useMemo } from 'react'
import dynamic from 'next/dynamic'
import type { CanvasPoint, CanvasLine } from './CoordinateCanvas'
import type { SubmissionPackage } from '@/lib/submission/types'

import { formatPlanDate, formatBearingDMS, formatDistanceM } from '@/lib/drawing/dxfLayers'

const CoordinateCanvas = dynamic(() => import('./CoordinateCanvas').then(m => ({ default: m.CoordinateCanvas })), {
  ssr: false,
  loading: () => <div className="animate-pulse bg-gray-200 rounded h-64" />,
})

interface FormNo4PreviewProps {
  pkg: SubmissionPackage
  width?: number
  height?: number
}

function formatPlanDateLocal(date: string): string {
  return formatPlanDate(date)
}

export function FormNo4Preview({
  pkg,
  width = 800,
  height = 600
}: FormNo4PreviewProps) {
  const adjustedAreaHa = pkg.traverse.areaM2 / 10000
  const scale = useMemo(() => {
    const pts = pkg.traverse.points
    if (pts.length < 2) return 2500
    let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity
    pts.forEach(p => {
      minE = Math.min(minE, p.adjustedEasting)
      maxE = Math.max(maxE, p.adjustedEasting)
      minN = Math.min(minN, p.adjustedNorthing)
      maxN = Math.max(maxN, p.adjustedNorthing)
    })
    const w = maxE - minE, h = maxN - minN
    const scales = [500, 1000, 2500, 5000, 10000, 25000]
    for (const s of scales) {
      if (w / s <= 0.315 && h / s <= 0.222) return s
    }
    return 25000
  }, [pkg.traverse.points])

  const { points, lines } = useMemo(() => {
    const pts: CanvasPoint[] = pkg.traverse.points.map(p => ({
      id: p.pointName,
      name: p.pointName,
      easting: p.adjustedEasting,
      northing: p.adjustedNorthing,
      type: 'beacon' as const
    }))

    const lns: CanvasLine[] = pts.map((pt, i) => ({
      from: pt.id,
      to: pts[(i + 1) % pts.length].id,
      style: 'solid' as const
    }))

    return { points: pts, lines: lns }
  }, [pkg])

  const legs = useMemo(() => {
    return pkg.traverse.points.map((from, i) => {
      const to = pkg.traverse.points[(i + 1) % pkg.traverse.points.length]
      const dE = to.adjustedEasting - from.adjustedEasting
      const dN = to.adjustedNorthing - from.adjustedNorthing
      let bearing = Math.atan2(dE, dN) * (180 / Math.PI)
      if (bearing < 0) bearing += 360
      const distance = Math.sqrt(dE * dE + dN * dN)
      return {
        from: from.pointName,
        to: to.pointName,
        bearing,
        distance,
        midE: (from.adjustedEasting + to.adjustedEasting) / 2,
        midN: (from.adjustedNorthing + to.adjustedNorthing) / 2
      }
    })
  }, [pkg.traverse.points])

  return (
    <div className="space-y-3">
      <div className="bg-[#1a1a1a] border rounded-t-lg px-4 py-3 flex items-center justify-between text-sm">
        <div>
          <p className="font-semibold">FORM NO. 4 — SURVEY PLAN</p>
          <p className="text-[var(--text-muted)] text-xs mt-0.5">
            LR No: {pkg.parcel.lrNumber} · Parcel No: {pkg.parcel.parcelNumber || pkg.parcel.lrNumber}
          </p>
          <p className="text-[var(--text-muted)] text-xs">
            {pkg.parcel.county} · {pkg.parcel.division || '-'} · {pkg.parcel.district}
          </p>
        </div>
        <div className="text-right text-xs text-[var(--text-muted)]">
          <p>{pkg.surveyor.fullName}</p>
          <p>ISK No: {pkg.surveyor.iskNumber || pkg.surveyor.registrationNumber}</p>
          <p>{pkg.surveyor.firmName}</p>
          <p>Date: {formatPlanDateLocal(pkg.generatedAt)}</p>
        </div>
      </div>

      <CoordinateCanvas
        points={points}
        lines={lines}
        width={width}
        height={height}
        showNorthArrow
        showScaleBar
        showGrid
        showAreaAnnotation
        areaAnnotation={`Area = ${adjustedAreaHa.toFixed(4)} Ha`}
        legs={legs.map(l => ({
          from: l.from,
          to: l.to,
          bearing: l.bearing,
          distance: l.distance,
          midX: l.midE,
          midY: l.midN
        }))}
      />

      <div className="bg-[#1a1a1a] border rounded-b-lg px-4 py-3 grid grid-cols-4 gap-4 text-sm">
        <div>
          <p className="text-[var(--text-muted)] text-xs">Area</p>
          <p className="font-medium">{adjustedAreaHa.toFixed(4)} Ha</p>
          <p className="text-[var(--text-muted)] text-xs">{pkg.traverse.areaM2.toFixed(2)} m²</p>
        </div>
        <div>
          <p className="text-[var(--text-muted)] text-xs">Perimeter</p>
          <p className="font-medium">{pkg.traverse.perimeterM.toFixed(3)} m</p>
        </div>
        <div>
          <p className="text-[var(--text-muted)] text-xs">Scale</p>
          <p className="font-medium">1:{scale}</p>
        </div>
        <div>
          <p className="text-[var(--text-muted)] text-xs">Ref</p>
          <p className="font-medium">{pkg.submissionRef}</p>
          <p className="text-[var(--text-muted)] text-xs">R{pkg.revision.toString().padStart(2, '0')}</p>
        </div>
        {pkg.scaleFactor && (
          <div>
            <p className="text-[var(--text-muted)] text-xs">Scale Factor</p>
            <p className="font-medium">{pkg.scaleFactor.toFixed(6)}</p>
          </div>
        )}
        {pkg.meanElevation != null && (
          <div>
            <p className="text-[var(--text-muted)] text-xs">Mean Elevation</p>
            <p className="font-medium">{pkg.meanElevation.toFixed(2)} m</p>
          </div>
        )}
        {pkg.controlClass && (
          <div>
            <p className="text-[var(--text-muted)] text-xs">Control Class</p>
            <p className="font-medium">{pkg.controlClass} Order</p>
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

import { useEffect, useRef, useMemo, useState } from 'react'
import Konva from 'konva'
import { logEngineeringCompute } from '@/lib/engineering/compute'
import { initialiseDXFLayers, addStandardTitleBlock, DXF_LAYERS } from '@/lib/drawing/dxfLayers'

export interface ProfilePoint {
  chainage: number
  groundLevel: number
  formationLevel?: number
}

export interface StationLevel {
  chainage: number
  groundLevel: number
  formationLevel: number
  cut: number
  fill: number
}

interface LongitudinalSectionProps {
  points: ProfilePoint[]
  title?: string
  hScale?: number
  vScale?: number
  width?: number
  height?: number
  showTable?: boolean
  projectId?: string
  editable?: boolean
  projectData?: {
    lr_number?: string;
    county?: string;
    district?: string;
    locality?: string;
  };
  surveyorProfile?: {
    fullName: string;
    registrationNumber: string;
    firmName: string;
  } | null;
}

export function LongitudinalSection({
  points,
  title = 'LONGITUDINAL SECTION',
  hScale = 2000,
  vScale = 200,
  width = 900,
  height = 500,
  showTable = false,
  projectId,
  editable = false,
  projectData,
  surveyorProfile,
}: LongitudinalSectionProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const [designLevels, setDesignLevels] = useState<number[]>(
    points.map(p => p.formationLevel ?? p.groundLevel)
  )

  const pointsWithDesign = useMemo(() => {
    return points.map((p, i) => ({
      ...p,
      formationLevel: designLevels[i]
    }))
  }, [points, designLevels])

  const stationLevels: StationLevel[] = useMemo(() => {
    return pointsWithDesign.map(p => ({
      chainage: p.chainage,
      groundLevel: p.groundLevel,
      formationLevel: p.formationLevel ?? p.groundLevel,
      cut: p.formationLevel != null ? Math.max(0, p.groundLevel - p.formationLevel) : 0,
      fill: p.formationLevel != null ? Math.max(0, p.formationLevel - p.groundLevel) : 0
    }))
  }, [pointsWithDesign])

  const totalCut = useMemo(() => stationLevels.reduce((sum, s) => sum + s.cut, 0), [stationLevels])
  const totalFill = useMemo(() => stationLevels.reduce((sum, s) => sum + s.fill, 0), [stationLevels])

  useEffect(() => {
    setDesignLevels(points.map(p => p.formationLevel ?? p.groundLevel))
  }, [points])

  useEffect(() => {
    if (!containerRef.current || pointsWithDesign.length < 2) return

    const stage = new Konva.Stage({ container: containerRef.current, width, height })
    const layer = new Konva.Layer()
    stage.add(layer)

    const marginLeft = 80
    const marginRight = 40
    const marginTop = 40
    const drawHeight = height - 80

    const minCh = Math.min(...pointsWithDesign.map(p => p.chainage))
    const maxCh = Math.max(...pointsWithDesign.map(p => p.chainage))
    const minGL = Math.min(...pointsWithDesign.map(p => Math.min(p.groundLevel, p.formationLevel ?? p.groundLevel)))
    const maxGL = Math.max(...pointsWithDesign.map(p => Math.max(p.groundLevel, p.formationLevel ?? p.groundLevel)))
    const glRange = maxGL - minGL || 1

    const drawWidth = width - marginLeft - marginRight
    const chRange = maxCh - minCh || 1

    const hPPM = drawWidth / chRange
    const vPPM = drawHeight / (glRange * (hScale / vScale))

    function toCanvas(chainage: number, elevation: number) {
      return {
        x: marginLeft + (chainage - minCh) * hPPM,
        y: marginTop + drawHeight - (elevation - minGL) * vPPM * (hScale / vScale)
      }
    }

    const elevStep = 5
    const firstElev = Math.ceil(minGL / elevStep) * elevStep
    for (let el = firstElev; el <= maxGL + elevStep; el += elevStep) {
      const { y } = toCanvas(minCh, el)
      if (y < marginTop || y > marginTop + drawHeight) continue
      layer.add(new Konva.Line({
        points: [marginLeft, y, marginLeft + drawWidth, y],
        stroke: '#2a2a2a', strokeWidth: 0.5, dash: [4, 4]
      }))
      layer.add(new Konva.Text({
        x: 2, y: y - 6,
        text: `${el.toFixed(0)}`,
        fontSize: 9, fill: '#666'
      }))
    }

    layer.add(new Konva.Line({
      points: [marginLeft, marginTop, marginLeft, marginTop + drawHeight],
      stroke: '#555', strokeWidth: 1
    }))
    layer.add(new Konva.Line({
      points: [marginLeft, marginTop + drawHeight, marginLeft + drawWidth, marginTop + drawHeight],
      stroke: '#555', strokeWidth: 1
    }))

    const groundPts: number[] = []
    pointsWithDesign.forEach(p => {
      const { x, y } = toCanvas(p.chainage, p.groundLevel)
      groundPts.push(x, y)
    })
    layer.add(new Konva.Line({
      points: groundPts, stroke: '#66cc66', strokeWidth: 2
    }))

    const formationPts = pointsWithDesign.filter(p => p.formationLevel != null)
    if (formationPts.length >= 2) {
      const fPts: number[] = []
      formationPts.forEach(p => {
        const { x, y } = toCanvas(p.chainage, p.formationLevel!)
        fPts.push(x, y)
      })
      layer.add(new Konva.Line({
        points: fPts, stroke: '#e8a020', strokeWidth: 1.5, dash: [6, 3]
      }))
    }

    for (let i = 0; i < pointsWithDesign.length - 1; i++) {
      const p1 = pointsWithDesign[i]
      const p2 = pointsWithDesign[i + 1]
      if (p1.formationLevel == null || p2.formationLevel == null) continue

      const g1 = toCanvas(p1.chainage, p1.groundLevel)
      const f1 = toCanvas(p1.chainage, p1.formationLevel)
      const g2 = toCanvas(p2.chainage, p2.groundLevel)
      const f2 = toCanvas(p2.chainage, p2.formationLevel)

      const isCut = p1.groundLevel > p1.formationLevel

      layer.add(new Konva.Line({
        points: [g1.x, g1.y, g2.x, g2.y, f2.x, f2.y, f1.x, f1.y],
        closed: true,
        fill: isCut ? 'rgba(255,100,0,0.15)' : 'rgba(80,160,255,0.15)',
        stroke: 'transparent'
      }))
    }

    const tableY = marginTop + drawHeight + 10
    const chainStep = Math.ceil(chRange / 10 / 100) * 100
    for (let ch = Math.ceil(minCh / chainStep) * chainStep; ch <= maxCh; ch += chainStep) {
      const { x } = toCanvas(ch, minGL)
      layer.add(new Konva.Line({
        points: [x, marginTop, x, marginTop + drawHeight],
        stroke: '#1a1a1a', strokeWidth: 0.5
      }))
      layer.add(new Konva.Text({
        x: x - 15, y: tableY,
        text: `${ch.toFixed(0)}`,
        fontSize: 9, fill: '#888'
      }))
    }

    layer.add(new Konva.Text({
      x: marginLeft, y: 8,
      text: `${title}  |  H: 1:${hScale}  V: 1:${vScale}`,
      fontSize: 11, fill: '#aaa', fontStyle: 'bold'
    }))

    layer.add(new Konva.Line({
      points: [marginLeft, height - 15, marginLeft + 20, height - 15],
      stroke: '#66cc66', strokeWidth: 2
    }))
    layer.add(new Konva.Text({
      x: marginLeft + 24, y: height - 21,
      text: 'Ground', fontSize: 9, fill: '#66cc66'
    }))
    layer.add(new Konva.Line({
      points: [marginLeft + 80, height - 15, marginLeft + 100, height - 15],
      stroke: '#e8a020', strokeWidth: 1.5, dash: [6, 3]
    }))
    layer.add(new Konva.Text({
      x: marginLeft + 104, y: height - 21,
      text: 'Formation', fontSize: 9, fill: '#e8a020'
    }))
    layer.add(new Konva.Rect({
      x: marginLeft + 180, y: height - 19,
      width: 12, height: 8,
      fill: 'rgba(255,100,0,0.3)'
    }))
    layer.add(new Konva.Text({
      x: marginLeft + 196, y: height - 21,
      text: 'Cut', fontSize: 9, fill: '#ffaa66'
    }))
    layer.add(new Konva.Rect({
      x: marginLeft + 230, y: height - 19,
      width: 12, height: 8,
      fill: 'rgba(80,160,255,0.3)'
    }))
    layer.add(new Konva.Text({
      x: marginLeft + 246, y: height - 21,
      text: 'Fill', fontSize: 9, fill: '#66aaff'
    }))

    layer.draw()
    return () => { stage.destroy() }
  }, [pointsWithDesign, title, hScale, vScale, width, height])

  const exportDXF = async () => {
    const { default: Drawing } = await import('dxf-writer')
    const drawing = new Drawing()
    initialiseDXFLayers(drawing)

    addStandardTitleBlock(drawing, {
      drawingTitle: 'LONGITUDINAL SECTION SURVEY',
      lrNumber: projectData?.lr_number ?? 'N/A',
      county: projectData?.county ?? 'N/A',
      district: projectData?.district ?? 'N/A',
      locality: projectData?.locality ?? 'N/A',
      areaHa: 0,
      perimeterM: 0,
      surveyorName: surveyorProfile?.fullName ?? 'N/A',
      registrationNumber: surveyorProfile?.registrationNumber ?? 'N/A',
      firmName: surveyorProfile?.firmName ?? 'N/A',
      date: new Date().toLocaleDateString('en-KE'),
      submissionRef: 'N/A',
      coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
      scale: '1:2500',
      sheetNumber: '1 of 1',
      revision: 'R00',
    })

    const minCh = Math.min(...pointsWithDesign.map(p => p.chainage))
    const minGL = Math.min(...pointsWithDesign.map(p => p.groundLevel))
    const hScaleFactor = 1 / hScale
    const vScaleFactor = 1 / vScale

    drawing.setActiveLayer(DXF_LAYERS.PROFILE.name)
    for (let i = 0; i < pointsWithDesign.length - 1; i++) {
      const p1 = pointsWithDesign[i]
      const p2 = pointsWithDesign[i + 1]
      drawing.drawLine(
        (p1.chainage - minCh) * hScaleFactor,
        (p1.groundLevel - minGL) * vScaleFactor,
        (p2.chainage - minCh) * hScaleFactor,
        (p2.groundLevel - minGL) * vScaleFactor
      )
    }

    const formPts = pointsWithDesign.filter(p => p.formationLevel != null)
    if (formPts.length >= 2) {
      drawing.setActiveLayer(DXF_LAYERS.CENTRELINE.name)
      for (let i = 0; i < formPts.length - 1; i++) {
        const p1 = formPts[i]
        const p2 = formPts[i + 1]
        drawing.drawLine(
          (p1.chainage - minCh) * hScaleFactor,
          (p1.formationLevel! - minGL) * vScaleFactor,
          (p2.chainage - minCh) * hScaleFactor,
          (p2.formationLevel! - minGL) * vScaleFactor
        )
      }
    }

    drawing.setActiveLayer(DXF_LAYERS.CHAIN.name)
    pointsWithDesign.forEach(p => {
      drawing.drawText(
        (p.chainage - minCh) * hScaleFactor,
        -0.005,
        0.002,
        0,
        `${p.chainage.toFixed(0)}`
      )
    })

    logEngineeringCompute('longitudinal_section', { points: pointsWithDesign.length }, 
      { totalCut, totalFill }, { projectId })

    const dxfString = drawing.toDxfString()
    const blob = new Blob([dxfString], { type: 'application/dxf' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `profile_${projectId || 'export'}.dxf`
    a.click()
    URL.revokeObjectURL(url)
  }

  const updateDesignLevel = (index: number, value: number) => {
    const newLevels = [...designLevels]
    newLevels[index] = value
    setDesignLevels(newLevels)
  }

  return (
    <div className="space-y-2">
      <div className="flex justify-between items-center">
        <div ref={containerRef} className="rounded-lg overflow-hidden bg-[#111]" style={{ width, height }} />
      </div>
      
      <div className="flex justify-end gap-2">
        <button
          onClick={exportDXF}
          className="bg-orange-500 hover:bg-orange-600 px-4 py-2 rounded-lg text-white text-sm font-medium flex items-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
          </svg>
          Export DXF
        </button>
      </div>

      {showTable && stationLevels.length > 0 && (
        <div className="overflow-x-auto border border-[var(--border-color)] rounded-lg">
          <div className="flex justify-between items-center px-3 py-2 bg-[var(--bg-secondary)] border-b border-[var(--border-color)]">
            <span className="text-sm font-medium">Station Levels</span>
            <div className="flex gap-4 text-xs">
              <span className="text-orange-400">Total Cut: {totalCut.toFixed(2)} m³/area</span>
              <span className="text-blue-400">Total Fill: {totalFill.toFixed(2)} m³/area</span>
            </div>
          </div>
          <table className="w-full text-sm font-mono">
            <thead>
              <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)] text-xs">
                <th className="text-left py-1.5 px-3">Ch.</th>
                <th className="text-right py-1.5 px-3">G.L.</th>
                <th className="text-right py-1.5 px-3">F.L.</th>
                <th className="text-right py-1.5 px-3">Cut</th>
                <th className="text-right py-1.5 px-3">Fill</th>
              </tr>
            </thead>
            <tbody>
              {stationLevels.slice(0, 15).map((row, i) => (
                <tr key={`${row}-${i}`} className="border-b border-[var(--border-color)]/30">
                  <td className="py-1.5 px-3">{row.chainage.toFixed(0)}</td>
                  <td className="py-1.5 px-3 text-right">{row.groundLevel.toFixed(2)}</td>
                  <td className="py-1.5 px-3 text-right">
                    {editable ? (
                      <input aria-label="Design level (F.L.)"
                        type="number"
                        step={0.01}
                        value={designLevels[i]}
                        onChange={(e) => updateDesignLevel(i, Number(e.target.value))}
                        className="w-20 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-1 py-0.5 text-right text-sm"
                      />
                    ) : (
                      row.formationLevel.toFixed(2)
                    )}
                  </td>
                  <td className="py-1.5 px-3 text-right text-orange-400">{row.cut > 0 ? row.cut.toFixed(2) : '-'}</td>
                  <td className="py-1.5 px-3 text-right text-blue-400">{row.fill > 0 ? row.fill.toFixed(2) : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, Fragment, useId } from 'react'
import { computeCrossSection, computeEarthwork, parseEarthworkCSV, type CrossSectionInput, type CrossSectionComputed, type RoadTemplate, type EarthworkResult, type GroundShot } from '@/lib/computations/earthworksEngine'
import CrossSectionDrawing from './CrossSectionDrawing'
import EarthworkQuantitiesTable from './EarthworkQuantitiesTable'
import MassHaulDiagram from './MassHaulDiagram'
import { printEarthworksBoQ, type EarthworksBoQInput } from '@/lib/print/earthworksBoQ'
import { PrintMetaPanel, type PrintMeta } from '@/components/shared/PrintMetaPanel'

const DEFAULT_TEMPLATE: RoadTemplate = {
  carriagewayWidth: 7.0,
  shoulderWidth: 1.5,
  camber: 2.5,
  cutSlopeH: 1,
  fillSlopeH: 1.5,
}

interface SectionRow {
  id: string
  chainageKm: string
  chainageM: string
  clRL: string
  formRL: string
  leftShots: Array<{ off: string; rl: string }>
  rightShots: Array<{ off: string; rl: string }>
}

const EMPTY_ROW = (): SectionRow => ({
  id: crypto.randomUUID(),
  chainageKm: '0',
  chainageM: '0',
  clRL: '',
  formRL: '',
  leftShots: [{ off: '', rl: '' }, { off: '', rl: '' }],
  rightShots: [{ off: '', rl: '' }, { off: '', rl: '' }],
})

export default function EarthworksCalculator() {
  const uid = useId()
  const [sections, setSections] = useState<SectionRow[]>([EMPTY_ROW()])
  const [template, setTemplate] = useState<RoadTemplate>(DEFAULT_TEMPLATE)
  const [shrinkage, setShrinkage] = useState('0.85')
  const [computedSections, setComputedSections] = useState<CrossSectionComputed[]>([])
  const [earthworkResult, setEarthworkResult] = useState<EarthworkResult | null>(null)
  const [activeSection, setActiveSection] = useState(0)
  const [csvError, setCsvError] = useState('')
  const fileRef = useRef<HTMLInputElement>(null)
  const [printMeta, setPrintMeta] = useState<PrintMeta>({
    projectName: '', clientName: '', surveyorName: '', surveyorEmail: '', clientEmail: '', regNo: '', iskNo: '',
    date: new Date().toISOString().split('T')[0], instrument: '', weather: '', observer: '', submissionNo: '',
  })
  const [roadName, setRoadName] = useState('')

  function chainageToNum(row: SectionRow): number {
    return (parseFloat(row.chainageKm) || 0) * 1000 + (parseFloat(row.chainageM) || 0)
  }

  function toInput(row: SectionRow): CrossSectionInput {
    return {
      chainage: chainageToNum(row),
      centrelineRL: parseFloat(row.clRL) || 0,
      formationRL: parseFloat(row.formRL) || 0,
      leftShots: row.leftShots
        .filter((s) => s.off && s.rl)
        .map((s) => ({ offset: -(parseFloat(s.off) || 0), rl: parseFloat(s.rl) || 0 }))
        .sort((a: any, b: any) => a.offset - b.offset),
      rightShots: row.rightShots
        .filter((s) => s.off && s.rl)
        .map((s) => ({ offset: parseFloat(s.off) || 0, rl: parseFloat(s.rl) || 0 }))
        .sort((a: any, b: any) => a.offset - b.offset),
    }
  }

  function compute() {
    const inputs = sections.map(toInput).sort((a: any, b: any) => a.chainage - b.chainage)
    const computed = inputs.map((s) => computeCrossSection(s, template))
    const ew = computeEarthwork(computed, parseFloat(shrinkage) || 0.85)
    setComputedSections(computed)
    setEarthworkResult(ew)
  }

  function handlePrintBoQ() {
    if (!earthworkResult || computedSections.length === 0) return
    const inp: EarthworksBoQInput = {
      sections: computedSections,
      result: earthworkResult,
      template,
      roadName,
      startChainage: '',
      endChainage: '',
      meta: { ...printMeta, title: 'Earthworks Bill of Quantities' },
    }
    printEarthworksBoQ(inp)
  }

  function addRow() {
    setSections(prev => [...prev, EMPTY_ROW()])
  }

  function removeRow(id: string) {
    setSections(prev => prev.filter((r) => r.id !== id))
  }

  function updateRow(id: string, field: keyof SectionRow, value: unknown) {
    setSections(prev => prev.map((r) => r.id === id ? { ...r, [field]: value } : r))
  }

  function updateShot(id: string, side: 'left' | 'right', idx: number, field: 'off' | 'rl', value: string) {
    setSections(prev => prev.map((r) => {
      if (r.id !== id) return r
      const shots = [...r[(side + 'Shots') as 'leftShots' | 'rightShots']]
      shots[idx] = { ...shots[idx], [field]: value }
      return { ...r, [side + 'Shots']: shots }
    }))
  }

  function handleCSVUpload(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    setCsvError('')
    const reader = new FileReader()
    reader.onload = ev => {
      try {
        const text = ev.target?.result as string
        const parsed = parseEarthworkCSV(text)
        if (parsed.length === 0) { setCsvError('No valid sections found in CSV'); return }
          const rows: SectionRow[] = parsed.map((s) => {
            const km = Math.floor(s.chainage / 1000)
            const m = s.chainage % 1000
            return {
              id: crypto.randomUUID(),
              chainageKm: String(km),
              chainageM: m.toFixed(3),
              clRL: s.centrelineRL.toFixed(3),
              formRL: s.formationRL.toFixed(3),
              leftShots: s.leftShots.map((sh) => ({ off: Math.abs(sh.offset).toFixed(3), rl: sh.rl.toFixed(3) })),
              rightShots: s.rightShots.map((sh) => ({ off: sh.offset.toFixed(3), rl: sh.rl.toFixed(3) })),
            }
          })
        setSections(rows)
      } catch {
        setCsvError('Failed to parse CSV. Check format.')
      }
    }
    reader.readAsText(file)
  }

  function fmtCh(ch: number) {
    const km = Math.floor(ch / 1000)
    const m = ch % 1000
    return km > 0 ? `${km}+${m.toFixed(3)}` : `${m.toFixed(3)}`
  }

  return (
    <div className="space-y-8">
      {/* Template Settings */}
      <div className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg p-4">
        <h3 className="text-sm font-semibold mb-3">Road Template Settings</h3>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          {[
            { label: 'Carriageway Width (m)', key: 'carriagewayWidth' as keyof RoadTemplate },
            { label: 'Shoulder Width (m)', key: 'shoulderWidth' as keyof RoadTemplate },
            { label: 'Camber (%)', key: 'camber' as keyof RoadTemplate },
            { label: 'Cut Slope H:V', key: 'cutSlopeH' as keyof RoadTemplate },
            { label: 'Fill Slope H:V', key: 'fillSlopeH' as keyof RoadTemplate },
          ].map(({ label, key }) => (
            <div key={key}>
              <label htmlFor={`${uid}-tpl-${key}`} className="block text-xs text-[var(--text-muted)] mb-1">{label}</label>
              <input id={`${uid}-tpl-${key}`}
                type="number"
                step="0.01"
                value={template[key] as number}
                onChange={e => setTemplate(prev => ({ ...prev, [key]: parseFloat(e.target.value) || 0 }))}
                className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
              />
            </div>
          ))}
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="shrinkage-factor">Shrinkage Factor</label>
            <input id="shrinkage-factor" type="number" step="0.01" value={shrinkage} onChange={e => setShrinkage(e.target.value)}
              className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
          </div>
        </div>
      </div>

      {/* Data Entry Table */}
      <div className="overflow-x-auto">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold">Cross Section Data</h3>
          <div className="flex gap-2">
            <input ref={fileRef} type="file" accept=".csv" onChange={handleCSVUpload} className="hidden" />
            <button onClick={() => fileRef.current?.click()} className="px-3 py-1.5 text-xs border border-[var(--border-color)] rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)]">
              Import CSV
            </button>
            <button onClick={addRow} className="px-3 py-1.5 text-xs bg-[var(--accent)] text-white rounded hover:opacity-90">
              + Add Section
            </button>
            <button onClick={compute} className="px-4 py-1.5 text-xs bg-[var(--accent)] text-white rounded font-medium hover:opacity-90">
              Compute All
            </button>
            {earthworkResult && (
              <button onClick={handlePrintBoQ} className="px-4 py-1.5 text-xs bg-amber-600 text-white rounded font-medium hover:bg-amber-700">
                 Print BoQ
              </button>
            )}
          </div>
        </div>
        {csvError && <p className="text-xs text-red-400 mb-2">{csvError}</p>}
        <p className="text-xs text-[var(--text-muted)] mb-2">
          Format: Chainage (km), Chainage (m), CL RL, Form RL, then L4_off, L4_rl, L3_off, L3_rl, L2_off, L2_rl, L1_off, L1_rl, R1_off, R1_rl, R2_off, R2_rl, R3_off, R3_rl, R4_off, R4_rl
        </p>
        <table className="w-full text-xs font-mono border-collapse">
          <thead>
            <tr className="bg-[var(--bg-tertiary)]">
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">Ch km</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">Ch m</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">CL RL</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">Form RL</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium" colSpan={8}>Left Shots (outer→CL)</th>
              <th className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium" colSpan={8}>Right Shots (CL→outer)</th>
              <th className="px-2 py-2 border border-[var(--border-color)]"></th>
            </tr>
            <tr className="bg-[var(--bg-tertiary)]/50">
              <th className="border border-[var(--border-color)]"></th>
              <th className="border border-[var(--border-color)]"></th>
              <th className="border border-[var(--border-color)]"></th>
              <th className="border border-[var(--border-color)]"></th>
              {['L1 Off', 'L1 RL', 'L2 Off', 'L2 RL', 'L3 Off', 'L3 RL', 'L4 Off', 'L4 RL', 'R1 Off', 'R1 RL', 'R2 Off', 'R2 RL', 'R3 Off', 'R3 RL', 'R4 Off', 'R4 RL'].map((h, i) => (
                <th key={`${h}-${i}`} className="px-2 py-1 border border-[var(--border-color)] text-[var(--text-muted)] font-medium text-[10px]">{h}</th>
              ))}
              <th className="border border-[var(--border-color)]"></th>
            </tr>
          </thead>
          <tbody>
            {sections.map((row) => (
              <tr key={row.id} className="hover:bg-[var(--bg-tertiary)]/30">
                <td className="px-1 py-1 border border-[var(--border-color)]/50"><input aria-label="Ch km" value={row.chainageKm} onChange={e => updateRow(row.id, 'chainageKm', e.target.value)} type="number" min="0" className="w-full px-1 py-1 bg-transparent text-[var(--text-primary)]" /></td>
                <td className="px-1 py-1 border border-[var(--border-color)]/50"><input aria-label="Ch m" value={row.chainageM} onChange={e => updateRow(row.id, 'chainageM', e.target.value)} type="number" min="0" className="w-full px-1 py-1 bg-transparent text-[var(--text-primary)]" /></td>
                <td className="px-1 py-1 border border-[var(--border-color)]/50"><input aria-label="CL RL" value={row.clRL} onChange={e => updateRow(row.id, 'clRL', e.target.value)} type="number" step="0.001" className="w-full px-1 py-1 bg-transparent text-[var(--text-primary)]" /></td>
                <td className="px-1 py-1 border border-[var(--border-color)]/50"><input aria-label="Form RL" value={row.formRL} onChange={e => updateRow(row.id, 'formRL', e.target.value)} type="number" step="0.001" className="w-full px-1 py-1 bg-transparent text-[var(--text-primary)]" /></td>
                {[0, 1, 2, 3].map((i) => (
                  <Fragment key={'ls' + i}>
                    <td className="px-1 py-1 border border-[var(--border-color)]/50"><input value={row.leftShots[i]?.off || ''} onChange={e => updateShot(row.id, 'left', i, 'off', e.target.value)} type="number" step="0.001" className="w-14 px-1 py-1 bg-transparent text-[var(--text-primary)]" aria-label="Off" placeholder="Off" /></td>
                    <td className="px-1 py-1 border border-[var(--border-color)]/50"><input value={row.leftShots[i]?.rl || ''} onChange={e => updateShot(row.id, 'left', i, 'rl', e.target.value)} type="number" step="0.001" className="w-14 px-1 py-1 bg-transparent text-[var(--text-primary)]" aria-label="RL" placeholder="RL" /></td>
                  </Fragment>
                ))}
                {[0, 1, 2, 3].map((i) => (
                  <Fragment key={'rs' + i}>
                    <td className="px-1 py-1 border border-[var(--border-color)]/50"><input value={row.rightShots[i]?.off || ''} onChange={e => updateShot(row.id, 'right', i, 'off', e.target.value)} type="number" step="0.001" className="w-14 px-1 py-1 bg-transparent text-[var(--text-primary)]" aria-label="Off" placeholder="Off" /></td>
                    <td className="px-1 py-1 border border-[var(--border-color)]/50"><input value={row.rightShots[i]?.rl || ''} onChange={e => updateShot(row.id, 'right', i, 'rl', e.target.value)} type="number" step="0.001" className="w-14 px-1 py-1 bg-transparent text-[var(--text-primary)]" aria-label="RL" placeholder="RL" /></td>
                  </Fragment>
                ))}
                <td className="px-1 py-1 border border-[var(--border-color)]/50">
                  <button onClick={() => removeRow(row.id)} className="text-red-400 hover:text-red-300 text-xs px-1">[x]</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Results */}
      {computedSections.length > 0 && (
        <>
          {/* Summary */}
          <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
            {[
              ['Total Sections', String(computedSections.length)],
              ['Total Cut (Prismoidal)', `${earthworkResult?.totalCutPrismoidal.toFixed(2) || 0} m³`],
              ['Total Fill (Prismoidal)', `${earthworkResult?.totalFillPrismoidal.toFixed(2) || 0} m³`],
              ['Adjusted Cut (× Shrinkage)', `${earthworkResult?.adjustedCut.toFixed(2) || 0} m³`],
              ['Net Balance', `${((earthworkResult?.adjustedCut || 0) - (earthworkResult?.totalFillPrismoidal || 0)).toFixed(2)} m³`],
            ].map(([label, value]) => (
              <div key={label} className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded p-3">
                <p className="text-xs text-[var(--text-muted)]">{label}</p>
                <p className="text-base font-mono text-[var(--text-primary)]">{value}</p>
              </div>
            ))}
          </div>

          {/* Print Header + Print BoQ */}
          <div className="space-y-3">
            <div className="flex items-center gap-3">
              <div className="flex-1">
                <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="road-name-description">Road Name / Description</label>
                <input value={roadName} onChange={e => setRoadName(e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm"
                  aria-label="e.g. Kitengela Access Road — A104" placeholder="e.g. Kitengela Access Road — A104" />
              </div>
              <button onClick={handlePrintBoQ}
                className="px-5 py-2 bg-amber-600 text-white rounded-lg font-medium hover:bg-amber-700 text-sm whitespace-nowrap mt-5">
                 Print Earthworks BoQ
              </button>
            </div>
            <PrintMetaPanel meta={printMeta} onChange={setPrintMeta} />
          </div>

          {/* Section drawings + quantities */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div>
              <div className="flex gap-2 mb-3 overflow-x-auto pb-1">
                {computedSections.map((s, i) => (
                  <button key={`${s}-${i}`} onClick={() => setActiveSection(i)}
                    className={`px-3 py-1.5 text-xs rounded whitespace-nowrap ${i === activeSection ? 'bg-[var(--accent)] text-white' : 'border border-[var(--border-color)] text-[var(--text-muted)]'}`}>
                    {fmtCh(s.chainage)}
                  </button>
                ))}
              </div>
              {computedSections[activeSection] && (
                <CrossSectionDrawing section={computedSections[activeSection]} template={template} />
              )}
            </div>

            <div>
              <EarthworkQuantitiesTable result={earthworkResult} sections={computedSections} />
            </div>
          </div>

          {/* Mass Haul Diagram */}
          {earthworkResult && earthworkResult.massOrdinates.length > 1 && (
            <MassHaulDiagram result={earthworkResult} />
          )}
        </>
      )}
    </div>
  )
}

'use client';

import { type EarthworkResult } from '@/lib/computations/earthworksEngine'

interface Props {
  result: EarthworkResult
}

export default function MassHaulDiagram({ result }: Props) {
  const { massOrdinates, shrinkageFactor } = result

  if (massOrdinates.length < 2) return null

  const minCh = massOrdinates[0].chainage
  const maxCh = massOrdinates[massOrdinates.length - 1].chainage
  const chRange = maxCh - minCh || 1

  const maxOrd = Math.max(...massOrdinates.map((o: any) => o.ordinate), 0)
  const minOrd = Math.min(...massOrdinates.map((o: any) => o.ordinate), 0)
  const ordRange = Math.max(maxOrd - minOrd, 1)

  const svgW = 800
  const svgH = 300
  const padX = 60
  const padY = 30
  const plotW = svgW - padX * 2
  const plotH = svgH - padY * 2

  function toSvgX(ch: number): number {
    return padX + ((ch - minCh) / chRange) * plotW
  }
  function toSvgY(ord: number): number {
    return padY + ((maxOrd - ord) / ordRange) * plotH
  }

  // Build path
  const pathPts = massOrdinates.map((o, i) =>
    `${i === 0 ? 'M' : 'L'} ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)}`
  ).join(' ')

  // Balance line (zero)
  const zeroY = toSvgY(0)

  // Fill surplus (above zero)
  let surplusPath = `M ${toSvgX(minCh).toFixed(1)} ${zeroY.toFixed(1)} `
  for (const o of massOrdinates) {
    if (o.ordinate >= 0) {
      surplusPath += `L ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)} `
    }
  }
  surplusPath += `L ${toSvgX(maxCh).toFixed(1)} ${zeroY.toFixed(1)} Z`

  // Fill deficit (below zero)
  let deficitPath = `M ${toSvgX(minCh).toFixed(1)} ${zeroY.toFixed(1)} `
  for (const o of massOrdinates) {
    if (o.ordinate <= 0) {
      deficitPath += `L ${toSvgX(o.chainage).toFixed(1)} ${toSvgY(o.ordinate).toFixed(1)} `
    }
  }
  deficitPath += `L ${toSvgX(maxCh).toFixed(1)} ${zeroY.toFixed(1)} Z`

  // X axis ticks
  const numTicks = Math.min(10, massOrdinates.length)
  const tickStep = chRange / numTicks
  const xTicks: number[] = []
  for (let i = 0; i <= numTicks; i++) {
    xTicks.push(minCh + (i / numTicks) * chRange)
  }

  // Y axis ticks
  const ordStep = ordRange / 5
  const yTicks: number[] = []
  for (let i = 0; i <= 5; i++) {
    yTicks.push(minOrd + i * ordStep)
  }

  const fmtCh = (ch: number) => {
    const km = Math.floor(ch / 1000)
    const m = ch % 1000
    return km > 0 ? `${km}+${m.toFixed(0)}` : `${m.toFixed(0)}`
  }

  const maxIdx = massOrdinates.reduce((maxI, o, i, arr) => o.ordinate > arr[maxI].ordinate ? i : maxI, 0)
  const minIdx = massOrdinates.reduce((minI, o, i, arr) => o.ordinate < arr[minI].ordinate ? i : minI, 0)
  const peakOrd = massOrdinates[maxIdx]
  const troughOrd = massOrdinates[minIdx]

  return (
    <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg overflow-hidden">
      <div className="px-3 py-2 bg-[var(--bg-tertiary)] border-b border-[var(--border-color)]">
        <h3 className="text-sm font-semibold">Mass Haul Diagram</h3>
        <p className="text-xs text-[var(--text-muted)]">
          Adjusted cut (&times; {shrinkageFactor} shrinkage) &minus; fill | Source: Ghilani &amp; Wolf Ch.26, Section 26.6
        </p>
      </div>

      <div className="p-4">
        <svg viewBox={`0 0 ${svgW} ${svgH}`} className="w-full" style={{ background: '#fafafa' }}>
          {/* Y axis */}
          <line x1={padX} y1={padY} x2={padX} y2={svgH - padY} stroke="#333" strokeWidth="1" />
          {/* X axis */}
          <line x1={padX} y1={svgH - padY} x2={svgW - padX} y2={svgH - padY} stroke="#333" strokeWidth="1" />

          {/* Balance line */}
          <line x1={padX} y1={zeroY} x2={svgW - padX} y2={zeroY} stroke="#888" strokeWidth="1" strokeDasharray="5,3" />

          {/* Surplus area */}
          <path d={surplusPath} fill="#ff660018" stroke="none" />
          {/* Deficit area */}
          <path d={deficitPath} fill="#0066ff18" stroke="none" />

          {/* Curve */}
          <path d={pathPts} fill="none" stroke="#333" strokeWidth="2" />

          {/* Peak annotation */}
          <circle cx={toSvgX(peakOrd.chainage)} cy={toSvgY(peakOrd.ordinate)} r="4" fill="#ff6600" />
          <text x={toSvgX(peakOrd.chainage) + 5} y={toSvgY(peakOrd.ordinate) - 5} fontSize="9" fill="#ff6600" fontFamily="monospace">
            Max: {peakOrd.ordinate.toFixed(1)} m&sup3;
          </text>

          {/* Trough annotation */}
          <circle cx={toSvgX(troughOrd.chainage)} cy={toSvgY(troughOrd.ordinate)} r="4" fill="#0066ff" />
          <text x={toSvgX(troughOrd.chainage) + 5} y={toSvgY(troughOrd.ordinate) + 14} fontSize="9" fill="#0066ff" fontFamily="monospace">
            Min: {troughOrd.ordinate.toFixed(1)} m&sup3;
          </text>

          {/* X axis ticks */}
          {xTicks.map((ch, i) => (
            <g key={`${ch}-${i}`}>
              <line x1={toSvgX(ch)} y1={svgH - padY} x2={toSvgX(ch)} y2={svgH - padY + 5} stroke="#333" strokeWidth="0.5" />
              <text x={toSvgX(ch)} y={svgH - padY + 15} fontSize="8" fill="#666" textAnchor="middle" fontFamily="monospace">
                {fmtCh(ch)}
              </text>
            </g>
          ))}

          {/* Y axis ticks */}
          {yTicks.map((ord, i) => (
            <g key={`${ord}-${i}`}>
              <line x1={padX - 5} y1={toSvgY(ord)} x2={padX} y2={toSvgY(ord)} stroke="#333" strokeWidth="0.5" />
              <text x={padX - 8} y={toSvgY(ord) + 3} fontSize="8" fill="#666" textAnchor="end" fontFamily="monospace">
                {ord >= 1000 ? `${(ord / 1000).toFixed(1)}k` : ord.toFixed(0)}
              </text>
            </g>
          ))}

          {/* Axis labels */}
          <text x={svgW / 2} y={svgH - 2} fontSize="9" fill="#333" textAnchor="middle" fontFamily="monospace">
            Chainage
          </text>
          <text x={12} y={svgH / 2} fontSize="9" fill="#333" textAnchor="middle" fontFamily="monospace" transform={`rotate(-90, 12, ${svgH / 2})`}>
            Mass Ordinate (m&sup3;)
          </text>
        </svg>

        <div className="mt-3 grid grid-cols-2 md:grid-cols-4 gap-3 text-xs font-mono">
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Peak Ordinate</p>
            <p className="text-orange-400 text-sm">{peakOrd.ordinate.toFixed(2)} m&sup3;</p>
            <p className="text-[var(--text-muted)] text-[10px]">at {fmtCh(peakOrd.chainage)}</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Trough Ordinate</p>
            <p className="text-blue-400 text-sm">{troughOrd.ordinate.toFixed(2)} m&sup3;</p>
            <p className="text-[var(--text-muted)] text-[10px]">at {fmtCh(troughOrd.chainage)}</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Free Haul Distance</p>
            <p className="text-[var(--text-primary)] text-sm">100 m (RDM 1.3)</p>
          </div>
          <div className="bg-[var(--bg-tertiary)] rounded p-2">
            <p className="text-[var(--text-muted)]">Net Balance</p>
            <p className={`text-sm ${peakOrd.ordinate - Math.abs(troughOrd.ordinate) >= 0 ? 'text-yellow-400' : 'text-blue-400'}`}>
              {(peakOrd.ordinate - Math.abs(troughOrd.ordinate)).toFixed(2)} m&sup3;
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import CrossSectionInput from '@/components/earthworks/CrossSectionInput'

/**
 * ProjectCrossSections — wrapper that connects CrossSectionInput to a project.
 *
 * Fetches the project's survey points and attempts to match point names to
 * chainage stations (e.g. "0+020", "20", "STA 20" → chainage 20m).
 * Uses the elevation as the centreline reduced level (clRL).
 *
 * Limitation: full cross-section auto-population (with left/right offset shots)
 * requires the baseline alignment geometry, which is a future feature.
 * For now, this populates centreline levels only — the surveyor still enters
 * offset shots manually or via CSV.
 *
 * Usage:
 *   <ProjectCrossSections projectId="abc-123" />
 *   // or as a route: /tools/cross-sections?project=abc-123
 */

interface ProjectCrossSectionsProps {
  projectId: string
}

interface SurveyPoint {
  id: string
  point_name: string
  easting: number
  northing: number
  elevation: number | null
  code: string | null
  description: string | null
}

/**
 * Attempt to extract a chainage value (in metres) from a point name.
 * Handles formats: "0+020", "0+020.5", "20", "STA 20", "CH 1200"
 */
function parseChainageFromName(name: string): number | null {
  if (!name) return null
  const upper = name.toUpperCase().trim()

  // Format: "0+020" or "1+200.5" (km+m)
  const kmMatch = upper.match(/(\d+)\+(\d+(?:\.\d+)?)/)
  if (kmMatch) {
    return parseInt(kmMatch[1]) * 1000 + parseFloat(kmMatch[2])
  }

  // Format: "STA 20" or "CH 1200" or just "20"
  const staMatch = upper.match(/(?:STA|CH|CHAINAGE)?\s*(\d+(?:\.\d+)?)/)
  if (staMatch) {
    return parseFloat(staMatch[1])
  }

  return null
}

export default function ProjectCrossSections({ projectId }: ProjectCrossSectionsProps) {
  const [loading, setLoading] = useState(true)
  const [matchedCount, setMatchedCount] = useState(0)
  const [loaded, setLoaded] = useState(false)
  const inputRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    let cancelled = false

    async function fetchPoints() {
      try {
        const res = await fetch(`/api/project/${projectId}/points`)
        if (!res.ok) return
        const json = await res.json()
        const points: SurveyPoint[] = json.data || []

        // Try to match points to chainage stations
        const matched: { chainage: number; rl: number; name: string }[] = []
        for (const p of points) {
          if (p.elevation == null) continue
          const ch = parseChainageFromName(p.point_name)
          if (ch !== null) {
            matched.push({ chainage: ch, rl: p.elevation, name: p.point_name })
          }
        }

        if (!cancelled && matched.length > 0) {
          // Sort by chainage
          matched.sort((a, b) => a.chainage - b.chainage)
          // Store in sessionStorage as CSV for the CrossSectionInput's CSV import
          // Format: chainage,centrelineRL,formationRL,leftOffsets,rightOffsets
          // We only have centreline RL — formation RL and offsets are blank
          const csvLines = matched.map(m => {
            const km = Math.floor(m.chainage / 1000)
            const m2 = m.chainage % 1000
            return `${km}+${m2.toFixed(3)},${m.rl.toFixed(3)},,,`
          })
          const csv = `chainage,centrelineRL,formationRL,left,right\n` + csvLines.join('\n')
          sessionStorage.setItem(`metardu:cross-sections:csv:${projectId}`, csv)
          setMatchedCount(matched.length)
        }
      } catch {
        // silent fail
      } finally {
        if (!cancelled) {
          setLoading(false)
          setLoaded(true)
        }
      }
    }

    if (projectId && projectId !== 'new') {
      fetchPoints()
    } else {
      setLoading(false)
      setLoaded(true)
    }

    return () => { cancelled = true }
  }, [projectId])

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="font-mono text-xs text-[var(--text-muted)] tracking-[0.04em] uppercase">
          Loading project data...
        </div>
      </div>
    )
  }

  return (
    <div ref={inputRef}>
      {matchedCount > 0 && (
        <div className="max-w-7xl mx-auto px-4 mb-4">
          <div className="border border-[var(--accent)]/30 bg-[var(--accent)]/5 p-3 rounded-md flex items-center gap-3">
            <svg className="w-4 h-4 text-[var(--accent)] shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <p className="text-xs text-[var(--text-secondary)]">
              <span className="font-mono text-[var(--accent)]">{matchedCount} centreline levels</span>{' '}
              matched from project survey points (by chainage name). Use the CSV import
              below to load them. Offset shots and formation levels need manual entry.
            </p>
          </div>
        </div>
      )}
      {loaded && matchedCount === 0 && projectId !== 'new' && (
        <div className="max-w-7xl mx-auto px-4 mb-4">
          <div className="border border-[var(--border-color)] bg-[var(--bg-card)] p-3 rounded-md flex items-center gap-3">
            <svg className="w-4 h-4 text-[var(--text-muted)] shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M11.25 11.25l.041-.02a.75.75 0 011.063.852l-.708 2.836a.75.75 0 001.063.853l.041-.021M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9-3.75h.008v.008H12V8.25z" />
            </svg>
            <p className="text-xs text-[var(--text-muted)]">
              No chainage-matched points found in project. Name your survey points
              as &quot;0+020&quot; or &quot;20&quot; (chainage in metres) to auto-populate centreline levels.
            </p>
          </div>
        </div>
      )}
      <CrossSectionInput />
    </div>
  )
}

'use client';

import React, { useState, useMemo, useRef } from 'react'
import type { DesignPoint, AsBuiltPoint, ToleranceBand, AsBuiltSurveyResult } from '@/lib/engineering/asBuiltSurvey'
import { compareDesignVsAsBuilt, parseAsBuiltCSV, TOLERANCE_BANDS } from '@/lib/engineering/asBuiltSurvey'

interface AsBuiltSurveyPanelProps {
  projectId?: string
  roadClass?: string
  surfaceType?: 'paved' | 'gravel' | 'earth'
  designPoints?: DesignPoint[]
  onImport?: (points: AsBuiltPoint[]) => void
}

const SURFACE_TYPES: Array<{ key: 'paved' | 'gravel' | 'earth'; label: string; tolerance: ToleranceBand }> = [
  { key: 'paved', label: 'Paved (Asphalt/Concrete)', tolerance: TOLERANCE_BANDS.paved },
  { key: 'gravel', label: 'Gravel', tolerance: TOLERANCE_BANDS.gravel },
  { key: 'earth', label: 'Earth', tolerance: TOLERANCE_BANDS.earth },
]

export default function AsBuiltSurveyPanel({ roadClass, surfaceType = 'paved', designPoints = [] }: AsBuiltSurveyPanelProps) {
  const [activeSurface, setActiveSurface] = useState<'paved' | 'gravel' | 'earth'>(surfaceType)
  const [csvInput, setCsvInput] = useState('')
  const [asBuiltPoints, setAsBuiltPoints] = useState<AsBuiltPoint[]>([])
  const [result, setResult] = useState<AsBuiltSurveyResult | null>(null)
  const [csvError, setCsvError] = useState<string | null>(null)
  const [nanWarning, setNanWarning] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const tolerance = SURFACE_TYPES.find(s => s.key === activeSurface)!.tolerance

  const handleImport = () => {
    setCsvError(null)
    const points = parseAsBuiltCSV(csvInput)
    if (points.length === 0) {
      setCsvError('Invalid CSV format. Expected: chainage, level, easting, northing (E/N optional).')
      return
    }
    setAsBuiltPoints(points)
    setNanWarning(false)
    const r = compareDesignVsAsBuilt(designPoints, points, tolerance)
    setResult(r)
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (event) => {
      const text = event.target?.result as string
      setCsvInput(text)
      setCsvError(null)
      const points = parseAsBuiltCSV(text)
      if (points.length === 0) {
        setCsvError('Invalid CSV format. Expected: chainage, level, easting, northing (E/N optional).')
        return
      }
      setAsBuiltPoints(points)
      setNanWarning(false)
      const r = compareDesignVsAsBuilt(designPoints, points, tolerance)
      setResult(r)
    }
    reader.readAsText(file)
    // Reset so same file can be re-uploaded
    e.target.value = ''
  }

  const handleExportCSV = () => {
    if (!result) return
    const header = 'chainage,design_level,as_built_level,deviation,tolerance,status'
    const rows = result.comparisons.map(r =>
      `${r.chainage},${r.designLevel.toFixed(4)},${r.asBuiltLevel.toFixed(4)},${r.deviation.toFixed(1)},${r.tolerance},${r.pass ? 'PASS' : 'FAIL'}`
    )
    const csvContent = [header, ...rows].join('\n')
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = `as_built_survey_results_${Date.now()}.csv`
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }

  // Generate synthetic design points for demo
  const demoDesignPoints = useMemo(() => {
    if (designPoints.length > 0) return designPoints
    return Array.from({ length: 51 }, (_, i) => ({
      chainage: i * 20,
      designLevel: 100 + Math.sin(i * 0.15) * 3,
    }))
  }, [designPoints])

  const runComparison = () => {
    if (asBuiltPoints.length < 2) return
    setNanWarning(false)
    const r = compareDesignVsAsBuilt(demoDesignPoints, asBuiltPoints, tolerance)
    // Check for NaN deviations
    const hasNan = r.comparisons.some(c => isNaN(c.deviation))
    if (hasNan) setNanWarning(true)
    setResult(r)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h3 className="text-lg font-semibold text-white">As-Built Survey Analysis</h3>
        <p className="text-sm text-zinc-400 mt-1">Compare design levels against as-built survey data</p>
      </div>

      {/* Surface Type & Tolerance */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h4 className="font-medium text-white mb-3">Surface Type & Tolerances</h4>
        <div className="grid grid-cols-3 gap-3">
          {SURFACE_TYPES.map(st => (
            <button
              key={st.key}
              onClick={() => setActiveSurface(st.key)}
              className={`p-3 rounded-lg border-2 text-left transition-colors ${
                activeSurface === st.key
                  ? 'border-blue-500 bg-blue-900/30'
                  : 'border-zinc-700 hover:border-zinc-600'
              }`}
            >
              <div className="font-medium text-sm text-white">{st.label}</div>
              <div className="text-xs text-zinc-400 mt-1">
                Level: ±{st.tolerance.level}mm | Horiz: ±{st.tolerance.horizontal}mm
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* CSV Import */}
      <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
        <h4 className="font-medium text-white mb-3">Import As-Built Data (CSV)</h4>
        <p className="text-xs text-zinc-400 mb-2">Format: chainage, level, easting, northing (one point per line)</p>

        {/* File upload button */}
        <div className="mb-3">
          <input
            ref={fileInputRef}
            type="file"
            accept=".csv,.txt"
            onChange={handleFileUpload}
            className="hidden"
          />
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            className="inline-flex items-center gap-2 px-4 py-2 bg-zinc-800 border border-zinc-600 text-zinc-300 rounded-lg text-sm font-medium hover:bg-zinc-700 hover:text-white transition-colors"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
            </svg>
            Upload CSV File
          </button>
        </div>

        {/* Textarea fallback */}
        <textarea
          className="w-full h-32 bg-zinc-800 border border-zinc-600 rounded-lg p-3 font-mono text-sm text-zinc-200 placeholder-zinc-500 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          placeholder={`0, 100.025, 123456.789, 9876543.210\n20, 100.032, 123466.521, 9876550.102\n40, 99.988, 123476.213, 9876556.834\n...`}
          value={csvInput}
          onChange={e => setCsvInput(e.target.value)}
        />

        {/* CSV error message */}
        {csvError && (
          <div className="mt-2 px-3 py-2 bg-red-900/30 border border-red-700 rounded-lg text-sm text-red-400">
            <span className="font-medium">Import Error:</span> {csvError}
          </div>
        )}

        <div className="flex gap-3 mt-3">
          <button
            onClick={handleImport}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700"
          >
            Import & Compare
          </button>
          {designPoints.length === 0 && (
            <button
              onClick={() => {
                const demoAB = demoDesignPoints.map(d => ({
                  chainage: d.chainage,
                  surveyedLevel: d.designLevel + (Math.random() - 0.5) * 0.06,
                  surveyedEasting: 123456.789 + d.chainage * 0.5,
                  surveyedNorthing: 9876543.21 + d.chainage * 0.7,
                }))
                setAsBuiltPoints(demoAB)
                setNanWarning(false)
                const r = compareDesignVsAsBuilt(demoDesignPoints, demoAB, tolerance)
                setResult(r)
              }}
              className="px-4 py-2 bg-zinc-700 text-zinc-200 rounded-lg text-sm font-medium hover:bg-zinc-600 transition-colors"
            >
              Load Demo Data
            </button>
          )}
        </div>
      </div>

      {/* Validation: Compare button area */}
      {asBuiltPoints.length > 0 && (
        <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
          <div className="flex items-center gap-4">
            <div>
              <span className="text-sm text-zinc-400">
                {asBuiltPoints.length} as-built point{asBuiltPoints.length !== 1 ? 's' : ''} loaded
              </span>
              {asBuiltPoints.length < 2 && (
                <span className="ml-2 text-xs text-amber-400">
                  — Need at least 2 points to compare
                </span>
              )}
            </div>
            <button
              onClick={runComparison}
              disabled={asBuiltPoints.length < 2}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                asBuiltPoints.length >= 2
                  ? 'bg-blue-600 text-white hover:bg-blue-700'
                  : 'bg-zinc-800 text-zinc-500 cursor-not-allowed'
              }`}
            >
              Compare
            </button>
          </div>
        </div>
      )}

      {/* Results */}
      {result && (
        <>
          {/* Summary Cards */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className={`rounded-xl border-2 p-4 ${result.summary.isCompliant ? 'border-green-500 bg-green-900/20' : 'border-red-500 bg-red-900/20'}`}>
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Pass Rate</div>
              <div className={`text-2xl font-bold ${result.summary.isCompliant ? 'text-green-400' : 'text-red-400'}`}>
                {result.summary.passRate.toFixed(1)}%
              </div>
              <div className="text-xs text-zinc-400">{result.summary.passCount} / {result.summary.totalPoints} points</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Max Deviation</div>
              <div className="text-2xl font-bold text-white">{result.summary.maxLevelDeviation.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Tolerance: ±{tolerance.level}mm</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">RMS Error</div>
              <div className="text-2xl font-bold text-white">{result.summary.rmsError.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Root Mean Square</div>
            </div>
            <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-4">
              <div className="text-xs text-zinc-400 uppercase tracking-wider">Mean Deviation</div>
              <div className="text-2xl font-bold text-white">{result.summary.meanLevelDeviation.toFixed(1)} mm</div>
              <div className="text-xs text-zinc-400">Std Dev: {result.summary.standardDeviation.toFixed(1)}mm</div>
            </div>
          </div>

          {/* Compliance Badge */}
          <div className={`rounded-xl p-4 flex items-center gap-3 ${result.summary.certificationReady ? 'bg-green-900/20 border border-green-800' : 'bg-amber-900/20 border border-amber-800'}`}>
            {result.summary.certificationReady ? (
              <svg className="w-6 h-6 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            ) : (
              <svg className="w-6 h-6 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 16.5c-.77.833.192 2.5 1.732 2.5z" /></svg>
            )}
            <div>
              <div className={`font-medium ${result.summary.certificationReady ? 'text-green-400' : 'text-amber-400'}`}>
                {result.summary.certificationReady ? 'Certificate Ready' : 'Not Ready for Certification'}
              </div>
              {result.summary.issues.length > 0 && (
                <ul className="text-xs text-zinc-300 mt-1">
                  {result.summary.issues.map((issue, i) => <li key={`${issue}-${i}`}>• {issue}</li>)}
                </ul>
              )}
            </div>
          </div>

          {/* Deviation Profile SVG */}
          <div className="bg-zinc-900 rounded-xl border border-zinc-700 p-6">
            <div className="flex items-center justify-between mb-3">
              <h4 className="font-medium text-white">Deviation Profile</h4>
              <button
                onClick={handleExportCSV}
                className="inline-flex items-center gap-2 px-3 py-1.5 bg-zinc-800 border border-zinc-600 text-zinc-300 rounded-lg text-xs font-medium hover:bg-zinc-700 hover:text-white transition-colors"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
                Download Results CSV
              </button>
            </div>
            {nanWarning && (
              <div className="mb-3 px-3 py-2 bg-amber-900/30 border border-amber-700 rounded-lg text-xs text-amber-400">
                <span className="font-medium">Warning:</span> Some deviation values contained NaN and were replaced with 0.
              </div>
            )}
            <DeviationProfileSvg comparisons={result.comparisons} tolerance={tolerance.level} />
          </div>

          {/* Data Table */}
          <div className="bg-zinc-900 rounded-xl border border-zinc-700 overflow-hidden">
            <div className="px-6 py-4 border-b border-zinc-700 flex items-center justify-between">
              <h4 className="font-medium text-white">As-Built Comparison Table</h4>
              <span className="text-xs text-zinc-400">{result.comparisons.length} rows</span>
            </div>
            <div className="overflow-x-auto max-h-96 overflow-y-auto">
              <table className="w-full text-sm">
                <thead className="bg-zinc-800 sticky top-0">
                  <tr>
                    <th className="px-4 py-2 text-left text-xs font-medium text-zinc-400">Chainage</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Design RL</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">As-Built RL</th>
                    <th className="px-4 py-2 text-right text-xs font-medium text-zinc-400">Deviation</th>
                    <th className="px-4 py-2 text-center text-xs font-medium text-zinc-400">Tolerance</th>
                    <th className="px-4 py-2 text-center text-xs font-medium text-zinc-400">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {result.comparisons.map((row, i) => (
                    <tr key={`${row}-${i}`} className={`border-t border-zinc-800 ${row.pass ? 'bg-zinc-900' : 'bg-red-900/15'}`}>
                      <td className="px-4 py-2 font-mono text-xs text-zinc-300">{row.chainage.toFixed(0)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.designLevel.toFixed(4)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.asBuiltLevel.toFixed(4)}</td>
                      <td className="px-4 py-2 text-right font-mono text-xs text-zinc-300">{row.deviation > 0 ? '+' : ''}{row.deviation.toFixed(1)} mm</td>
                      <td className="px-4 py-2 text-center text-xs text-zinc-400">±{row.tolerance}</td>
                      <td className="px-4 py-2 text-center">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${row.pass ? 'bg-green-900/40 text-green-400' : 'bg-red-900/40 text-red-400'}`}>
                          {row.pass ? 'PASS' : 'FAIL'}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  )
}

// ─── DEVIATION PROFILE SVG ────────────────────────────────────────────────────

function DeviationProfileSvg({ comparisons, tolerance }: { comparisons: Array<{ chainage: number; deviation: number; pass: boolean }>; tolerance: number }) {
  if (comparisons.length === 0) return null

  // NaN guard: replace NaN deviations with 0
  const sanitizedComparisons = comparisons.map(c => ({
    ...c,
    deviation: isNaN(c.deviation) ? 0 : c.deviation,
  }))

  const width = 900
  const height = 200
  const margin = { top: 20, right: 20, bottom: 40, left: 60 }

  const plotW = width - margin.left - margin.right
  const plotH = height - margin.top - margin.bottom

  const maxCh = Math.max(...sanitizedComparisons.map(c => c.chainage))
  const minCh = Math.min(...sanitizedComparisons.map(c => c.chainage))
  const maxDev = Math.max(tolerance * 1.5, Math.max(...sanitizedComparisons.map(c => Math.abs(c.deviation))))

  const scaleX = (ch: number) => margin.left + ((ch - minCh) / (maxCh - minCh || 1)) * plotW
  const scaleY = (dev: number) => margin.top + plotH / 2 - (dev / maxDev) * (plotH / 2)

  const polyline = sanitizedComparisons.map(c => `${scaleX(c.chainage)},${scaleY(c.deviation)}`).join(' ')

  return (
    <svg viewBox={`0 0 ${width} ${height}`} className="w-full">
      {/* Tolerance band */}
      <rect x={margin.left} y={scaleY(tolerance)} width={plotW} height={scaleY(-tolerance) - scaleY(tolerance)} fill="rgba(34,197,94,0.15)" />
      <line x1={margin.left} y1={scaleY(0)} x2={width - margin.right} y2={scaleY(0)} stroke="#71717a" strokeWidth={1} strokeDasharray="4,2" />
      <line x1={margin.left} y1={scaleY(tolerance)} x2={width - margin.right} y2={scaleY(tolerance)} stroke="#16a34a" strokeWidth={1} strokeDasharray="4,2" />
      <line x1={margin.left} y1={scaleY(-tolerance)} x2={width - margin.right} y2={scaleY(-tolerance)} stroke="#16a34a" strokeWidth={1} strokeDasharray="4,2" />

      {/* Data line */}
      <polyline fill="none" stroke="#3b82f6" strokeWidth={1.5} points={polyline} />

      {/* Points */}
      {sanitizedComparisons.map((c, i) => (
        <circle key={`${c}-${i}`} cx={scaleX(c.chainage)} cy={scaleY(c.deviation)} r={3}
          fill={c.pass ? '#16a34a' : '#dc2626'} />
      ))}

      {/* Labels */}
      <text x={width / 2} y={height - 5} textAnchor="middle" className="text-xs" fill="#a1a1aa">Chainage (m)</text>
      <text x={10} y={height / 2} textAnchor="middle" className="text-xs" fill="#a1a1aa" transform={`rotate(-90, 10, ${height / 2})`}>Deviation (mm)</text>
      <text x={margin.left + 4} y={scaleY(tolerance) - 4} className="text-xs" fill="#16a34a">+{tolerance}</text>
      <text x={margin.left + 4} y={scaleY(-tolerance) + 12} className="text-xs" fill="#16a34a">-{tolerance}</text>
    </svg>
  )
}

'use client';

import React, { useMemo } from 'react'
import {
  computeCamberProfile,
  computeDetailedFormationLine,
  computeCutFillArea,
  parseSlopeRatio,
  determineSectionType,
  interpolateGroundAtCentre,
  formatChainage,
  type ProfilePoint,
  type RoadTemplate,
} from '@/lib/engineering/crossSectionGeometry'

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface CrossSectionProps {
  chainage: number
  groundPoints: Array<{ offset: number; level: number }>
  template: RoadTemplate
  formationLevel?: number
  cutArea?: number
  fillArea?: number
  width?: number
  height?: number
  showLabels?: boolean
}

// ─── COLOUR CONSTANTS ──────────────────────────────────────────────────────────

const COLORS = {
  groundLine: '#92400E',         // brown
  groundFill: '#FEF3C7',         // tan
  carriageway: '#374151',        // dark grey
  shoulder: '#6B7280',           // lighter grey
  cutSlope: '#92400E',           // red-brown
  fillSlope: '#1E40AF',          // blue-grey
  subgrade: '#9CA3AF',           // grey dashed
  centreLine: '#6B7280',         // grey dashed
  cutFill: '#DC2626',            // red
  gridLine: '#E5E7EB',          // light grey
  offsetMarker: '#D1D5DB',       // light grey
  labelPrimary: '#111827',       // near black
  labelSecondary: '#6B7280',     // grey
  cutLabel: '#DC2626',           // red
  fillLabel: '#2563EB',          // blue
  dimensionLine: '#4B5563',      // medium grey
  dimensionArrow: '#374151',     // dark grey
  background: '#FAFAFA',         // near white
} as const

// ─── ARROW HEAD COMPONENT ──────────────────────────────────────────────────────

function ArrowHead({
  id,
  color = COLORS.dimensionArrow,
}: {
  id: string
  color?: string
}) {
  return (
    <defs>
      <marker
        id={id}
        viewBox="0 0 10 10"
        refX="5"
        refY="5"
        markerWidth="6"
        markerHeight="6"
        orient="auto-start-reverse"
      >
        <path d="M 0 0 L 10 5 L 0 10 z" fill={color} />
      </marker>
    </defs>
  )
}

// ─── DIMENSION LINE ────────────────────────────────────────────────────────────

function DimensionLine({
  x1,
  y1,
  x2,
  y2,
  label,
  offsetDir = 15,
  id,
}: {
  x1: number
  y1: number
  x2: number
  y2: number
  label: string
  offsetDir?: number
  id: string
}) {
  const dx = x2 - x1
  const dy = y2 - y1
  const len = Math.sqrt(dx * dx + dy * dy)
  if (len < 1) return null

  // Perpendicular direction for label offset
  const nx = -dy / len
  const ny = dx / len

  const midX = (x1 + x2) / 2 + nx * offsetDir
  const midY = (y1 + y2) / 2 + ny * offsetDir

  return (
    <g>
      <line
        x1={x1 + nx * 4}
        y1={y1 + ny * 4}
        x2={x2 + nx * 4}
        y2={y2 + ny * 4}
        stroke={COLORS.dimensionLine}
        strokeWidth={0.5}
        markerStart={`url(#arrow-${id})`}
        markerEnd={`url(#arrow-${id})`}
      />
      <text
        x={midX}
        y={midY + 2.5}
        fontSize="7"
        fill={COLORS.dimensionArrow}
        textAnchor="middle"
        fontFamily="monospace"
      >
        {label}
      </text>
    </g>
  )
}

// ─── MAIN COMPONENT ────────────────────────────────────────────────────────────

export function CrossSectionRenderer({
  chainage,
  groundPoints,
  template,
  formationLevel: propFormationLevel,
  cutArea: propCutArea,
  fillArea: propFillArea,
  width = 800,
  height = 400,
  showLabels = true,
}: CrossSectionProps) {
  const sectionType = useMemo(
    () => determineSectionType(groundPoints, propFormationLevel ?? 0),
    [groundPoints, propFormationLevel]
  )

  const computedFormationLevel = useMemo(() => {
    if (propFormationLevel !== undefined) return propFormationLevel
    // Default: ground level at centre
    const gl = interpolateGroundAtCentre(groundPoints)
    return gl !== null ? gl + 0.5 : 100
  }, [propFormationLevel, groundPoints])

  const isCut = sectionType === 'cut' || sectionType === 'mixed'
  const isFill = sectionType === 'fill' || sectionType === 'mixed'

  // Compute formation line
  const formationLine = useMemo(
    () =>
      computeDetailedFormationLine(
        template,
        computedFormationLevel,
        groundPoints,
        isCut
      ),
    [template, computedFormationLevel, groundPoints, isCut]
  )

  // Compute camber profile for carriageway detail
  const camberProfile = useMemo(
    () => computeCamberProfile(template.carriagewayWidth, template.camber, computedFormationLevel),
    [template.carriagewayWidth, template.camber, computedFormationLevel]
  )

  // Compute areas
  const areas = useMemo(() => {
    if (propCutArea !== undefined && propFillArea !== undefined) {
      return { cutArea: propCutArea, fillArea: propFillArea }
    }
    const netArea = computeCutFillArea(groundPoints, formationLine)
    if (netArea >= 0) {
      return { cutArea: netArea, fillArea: 0 }
    }
    return { cutArea: 0, fillArea: -netArea }
  }, [propCutArea, propFillArea, groundPoints, formationLine])

  // Compute subgrade line
  const subgradeLevel = computedFormationLevel - template.subgradeDepth

  // Auto-scale computation
  const { viewBox, toSvgX, toSvgY } = useMemo(() => {
    const allPoints: ProfilePoint[] = [
      ...groundPoints,
      ...formationLine,
    ]

    // Also consider subgrade
    const minOffset = Math.min(...allPoints.map(p => p.offset)) - 3
    const maxOffset = Math.max(...allPoints.map(p => p.offset)) + 3
    const minLevel = Math.min(
      ...allPoints.map(p => p.level),
      subgradeLevel
    ) - 1.5
    const maxLevel = Math.max(...allPoints.map(p => p.level)) + 1.5

    const dataWidth = maxOffset - minOffset
    const dataHeight = maxLevel - minLevel

    // Add 15% padding
    const padding = 0.15
    const paddedWidth = dataWidth * (1 + padding)
    const paddedHeight = dataHeight * (1 + padding)

    const vbX = minOffset - dataWidth * padding / 2
    const vbY = minLevel - dataHeight * padding / 2

    // Maintain aspect ratio matching the SVG element
    const aspectRatio = width / height
    const dataAspect = paddedWidth / paddedHeight

    let finalVbW: number
    let finalVbH: number
    if (dataAspect > aspectRatio) {
      // Data is wider — fit width, expand height
      finalVbW = paddedWidth
      finalVbH = paddedWidth / aspectRatio
    } else {
      // Data is taller — fit height, expand width
      finalVbH = paddedHeight
      finalVbW = paddedHeight * aspectRatio
    }

    // Centre the data in the viewBox
    const centerX = vbX + dataWidth / 2
    const centerY = vbY + dataHeight / 2
    const finalVbX = centerX - finalVbW / 2
    const finalVbY = centerY - finalVbH / 2

    const scaleX = (offset: number) =>
      ((offset - finalVbX) / finalVbW) * width
    const scaleY = (level: number) =>
      height - ((level - finalVbY) / finalVbH) * height

    return {
      viewBox: `${finalVbX} ${finalVbY} ${finalVbW} ${finalVbH}`,
      toSvgX: scaleX,
      toSvgY: scaleY,
    }
  }, [groundPoints, formationLine, subgradeLevel, width, height])

  // Sorted ground points for polyline
  const sortedGround = useMemo(
    () => [...groundPoints].sort((a, b) => a.offset - b.offset),
    [groundPoints]
  )

  // Centre ground level for cut/fill depth computation
  const centreGroundLevel = interpolateGroundAtCentre(groundPoints)
  const centreDepth =
    centreGroundLevel !== null
      ? centreGroundLevel - computedFormationLevel
      : 0

  // Formation template offsets
  const halfCW = template.carriagewayWidth / 2
  const shoulderEndOffset = halfCW + template.shoulderWidth

  // Slope ratios for labels
  const activeSlopeStr = isCut ? template.cutSlope : template.fillSlope
  let activeSlopeRatio = 0
  try {
    activeSlopeRatio = parseSlopeRatio(activeSlopeStr)
  } catch {
    // fallback
  }

  // Ground polygon points for fill below ground line
  const groundFillPoints = useMemo(() => {
    if (sortedGround.length < 2) return ''
    const yBottom = toSvgY(
      Math.min(...sortedGround.map(p => p.level)) - 2
    )
    const pts = sortedGround
      .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
      .join(' ')
    // Close the polygon at the bottom
    return `${pts} ${toSvgX(sortedGround[sortedGround.length - 1].offset).toFixed(1)},${yBottom.toFixed(1)} ${toSvgX(sortedGround[0].offset).toFixed(1)},${yBottom.toFixed(1)}`
  }, [sortedGround, toSvgX, toSvgY])

  // Ground polyline points
  const groundPolyline = useMemo(
    () =>
      sortedGround
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [sortedGround, toSvgX, toSvgY]
  )

  // Formation polyline points (carriageway only)
  const carriagewayPolyline = useMemo(
    () =>
      camberProfile
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [camberProfile, toSvgX, toSvgY]
  )

  // Full formation line polyline
  const formationPolyline = useMemo(
    () =>
      formationLine
        .map(p => `${toSvgX(p.offset).toFixed(1)},${toSvgY(p.level).toFixed(1)}`)
        .join(' '),
    [formationLine, toSvgX, toSvgY]
  )

  // Slope lines — separate left and right slope segments
  const leftSlopePoints = useMemo(() => {
    const leftShoulder = formationLine.find(
      p => Math.abs(p.offset - (-(halfCW + template.shoulderWidth))) < 0.01
    )
    const leftIntercept = formationLine[0]
    if (!leftShoulder || !leftIntercept) return null
    return {
      x1: toSvgX(leftShoulder.offset),
      y1: toSvgY(leftShoulder.level),
      x2: toSvgX(leftIntercept.offset),
      y2: toSvgY(leftIntercept.level),
    }
  }, [formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  const rightSlopePoints = useMemo(() => {
    const rightShoulder = formationLine.find(
      p => Math.abs(p.offset - (halfCW + template.shoulderWidth)) < 0.01
    )
    const rightIntercept = formationLine[formationLine.length - 1]
    if (!rightShoulder || !rightIntercept) return null
    return {
      x1: toSvgX(rightShoulder.offset),
      y1: toSvgY(rightShoulder.level),
      x2: toSvgX(rightIntercept.offset),
      y2: toSvgY(rightIntercept.level),
    }
  }, [formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  // Shoulder lines
  const leftShoulderLine = useMemo(() => {
    const edge = camberProfile.find(p => Math.abs(p.offset - (-halfCW)) < 0.01)
    const shoulder = formationLine.find(
      p => Math.abs(p.offset - (-(halfCW + template.shoulderWidth))) < 0.01
    )
    if (!edge || !shoulder) return null
    return {
      x1: toSvgX(edge.offset),
      y1: toSvgY(edge.level),
      x2: toSvgX(shoulder.offset),
      y2: toSvgY(shoulder.level),
    }
  }, [camberProfile, formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  const rightShoulderLine = useMemo(() => {
    const edge = camberProfile.find(p => Math.abs(p.offset - halfCW) < 0.01)
    const shoulder = formationLine.find(
      p => Math.abs(p.offset - (halfCW + template.shoulderWidth)) < 0.01
    )
    if (!edge || !shoulder) return null
    return {
      x1: toSvgX(edge.offset),
      y1: toSvgY(edge.level),
      x2: toSvgX(shoulder.offset),
      y2: toSvgY(shoulder.level),
    }
  }, [camberProfile, formationLine, halfCW, template.shoulderWidth, toSvgX, toSvgY])

  // Centreline SVG X position
  const clX = toSvgX(0)
  const formSvgY = toSvgY(computedFormationLevel)
  const subgradeSvgY = toSvgY(subgradeLevel)

  // Section type label
  const sectionLabel = useMemo(() => {
    if (areas.cutArea > 0.01 && areas.fillArea > 0.01) {
      return 'CUT/FILL'
    }
    if (areas.cutArea > 0.01) {
      return 'CUT'
    }
    if (areas.fillArea > 0.01) {
      return 'FILL'
    }
    return 'LEVEL'
  }, [areas])

  const sectionLabelColor = useMemo(() => {
    if (areas.cutArea > 0.01 && areas.fillArea > 0.01) return '#7C3AED'
    if (areas.cutArea > 0.01) return COLORS.cutLabel
    if (areas.fillArea > 0.01) return COLORS.fillLabel
    return COLORS.labelSecondary
  }, [areas])

  return (
    <svg
      width={width}
      height={height}
      viewBox={viewBox}
      className="block"
      style={{ background: COLORS.background }}
      role="img"
      aria-label={`Cross-section at chainage ${formatChainage(chainage)}`}
    >
      {/* Arrow markers for dimensions */}
      <ArrowHead id="dim-start" />
      <ArrowHead id="dim-end" />
      <ArrowHead id="dim-v-start" />
      <ArrowHead id="dim-v-end" />

      {/* ── Grid: centreline ── */}
      <line
        x1={clX}
        y1={0}
        x2={clX}
        y2={height}
        stroke={COLORS.centreLine}
        strokeWidth={0.5}
        strokeDasharray="6,4"
      />

      {/* ── Offset markers ── */}
      {showLabels && (
        <>
          {[10, 20, 30, 40, 50].forEach(offset => {
            // Only render if within the view
            const svgXLeft = toSvgX(-offset)
            const svgXRight = toSvgX(offset)
            if (svgXLeft < 0 && svgXRight > width) return
            return (
              <g key={offset}>
                {svgXLeft > 0 && (
                  <>
                    <line
                      x1={svgXLeft}
                      y1={height - 8}
                      x2={svgXLeft}
                      y2={height - 2}
                      stroke={COLORS.offsetMarker}
                      strokeWidth={0.5}
                    />
                    <text
                      x={svgXLeft}
                      y={height - 0.5}
                      fontSize="5"
                      fill={COLORS.labelSecondary}
                      textAnchor="middle"
                      fontFamily="monospace"
                    >
                      {offset}
                    </text>
                  </>
                )}
                {svgXRight < width && (
                  <>
                    <line
                      x1={svgXRight}
                      y1={height - 8}
                      x2={svgXRight}
                      y2={height - 2}
                      stroke={COLORS.offsetMarker}
                      strokeWidth={0.5}
                    />
                    <text
                      x={svgXRight}
                      y={height - 0.5}
                      fontSize="5"
                      fill={COLORS.labelSecondary}
                      textAnchor="middle"
                      fontFamily="monospace"
                    >
                      {offset}
                    </text>
                  </>
                )}
              </g>
            )
          })}
        </>
      )}

      {/* ── Ground profile fill (below ground line) ── */}
      {groundFillPoints && (
        <polygon
          points={groundFillPoints}
          fill={COLORS.groundFill}
          stroke="none"
        />
      )}

      {/* ── Ground profile line ── */}
      <polyline
        points={groundPolyline}
        fill="none"
        stroke={COLORS.groundLine}
        strokeWidth={2}
        strokeLinejoin="round"
      />

      {/* ── Fill slope (right side if fill) ── */}
      {isFill && rightSlopePoints && (
        <line
          x1={rightSlopePoints.x1}
          y1={rightSlopePoints.y1}
          x2={rightSlopePoints.x2}
          y2={rightSlopePoints.y2}
          stroke={COLORS.fillSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}
      {isFill && leftSlopePoints && (
        <line
          x1={leftSlopePoints.x1}
          y1={leftSlopePoints.y1}
          x2={leftSlopePoints.x2}
          y2={leftSlopePoints.y2}
          stroke={COLORS.fillSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}

      {/* ── Cut slope (left side if cut) ── */}
      {isCut && leftSlopePoints && (
        <line
          x1={leftSlopePoints.x1}
          y1={leftSlopePoints.y1}
          x2={leftSlopePoints.x2}
          y2={leftSlopePoints.y2}
          stroke={COLORS.cutSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}
      {isCut && rightSlopePoints && (
        <line
          x1={rightSlopePoints.x1}
          y1={rightSlopePoints.y1}
          x2={rightSlopePoints.x2}
          y2={rightSlopePoints.y2}
          stroke={COLORS.cutSlope}
          strokeWidth={1.5}
          strokeDasharray="4,2"
        />
      )}

      {/* ── Shoulders ── */}
      {leftShoulderLine && (
        <line
          x1={leftShoulderLine.x1}
          y1={leftShoulderLine.y1}
          x2={leftShoulderLine.x2}
          y2={leftShoulderLine.y2}
          stroke={COLORS.shoulder}
          strokeWidth={2.5}
          strokeLinecap="round"
        />
      )}
      {rightShoulderLine && (
        <line
          x1={rightShoulderLine.x1}
          y1={rightShoulderLine.y1}
          x2={rightShoulderLine.x2}
          y2={rightShoulderLine.y2}
          stroke={COLORS.shoulder}
          strokeWidth={2.5}
          strokeLinecap="round"
        />
      )}

      {/* ── Carriageway with camber ── */}
      <polyline
        points={carriagewayPolyline}
        fill="none"
        stroke={COLORS.carriageway}
        strokeWidth={3}
        strokeLinejoin="round"
        strokeLinecap="round"
      />

      {/* ── Subgrade (dashed) ── */}
      {template.subgradeDepth > 0 && (
        <line
          x1={toSvgX(-shoulderEndOffset - 2)}
          y1={subgradeSvgY}
          x2={toSvgX(shoulderEndOffset + 2)}
          y2={subgradeSvgY}
          stroke={COLORS.subgrade}
          strokeWidth={0.8}
          strokeDasharray="6,3"
        />
      )}

      {/* ── DIMENSIONS ── */}
      {showLabels && (
        <>
          {/* Carriageway width dimension */}
          <DimensionLine
            x1={toSvgX(-halfCW)}
            y1={formSvgY}
            x2={toSvgX(halfCW)}
            y2={formSvgY}
            label={`${template.carriagewayWidth.toFixed(1)}m`}
            offsetDir={12}
            id="cw"
          />

          {/* Left shoulder width dimension */}
          <DimensionLine
            x1={toSvgX(-halfCW)}
            y1={formSvgY}
            x2={toSvgX(-(halfCW + template.shoulderWidth))}
            y2={formSvgY}
            label={`${template.shoulderWidth.toFixed(1)}m`}
            offsetDir={-10}
            id="ls"
          />

          {/* Right shoulder width dimension */}
          <DimensionLine
            x1={toSvgX(halfCW)}
            y1={formSvgY}
            x2={toSvgX(halfCW + template.shoulderWidth)}
            y2={formSvgY}
            label={`${template.shoulderWidth.toFixed(1)}m`}
            offsetDir={10}
            id="rs"
          />

          {/* Cut/fill depth arrow at centreline */}
          {centreGroundLevel !== null && Math.abs(centreDepth) > 0.01 && (
            <g>
              <line
                x1={clX}
                y1={toSvgY(centreGroundLevel)}
                x2={clX}
                y2={formSvgY}
                stroke={centreDepth > 0 ? COLORS.cutLabel : COLORS.fillLabel}
                strokeWidth={0.8}
                markerStart={
                  centreDepth > 0
                    ? 'url(#dim-v-start)'
                    : 'url(#dim-v-end)'
                }
                markerEnd={
                  centreDepth > 0
                    ? 'url(#dim-v-end)'
                    : 'url(#dim-v-start)'
                }
              />
              <text
                x={clX + 6}
                y={(toSvgY(centreGroundLevel) + formSvgY) / 2 + 2.5}
                fontSize="7"
                fill={centreDepth > 0 ? COLORS.cutLabel : COLORS.fillLabel}
                fontFamily="monospace"
              >
                {Math.abs(centreDepth).toFixed(3)}m
              </text>
            </g>
          )}
        </>
      )}

      {/* ── LABELS ── */}
      {showLabels && (
        <>
          {/* Chainage label (top-left) */}
          <g>
            <rect
              x={8}
              y={8}
              width={90}
              height={18}
              rx={3}
              fill="white"
              fillOpacity={0.9}
              stroke="#E5E7EB"
              strokeWidth={0.5}
            />
            <text
              x={14}
              y={21}
              fontSize="9"
              fill={COLORS.labelPrimary}
              fontFamily="monospace"
              fontWeight="600"
            >
              CH {formatChainage(chainage)}
            </text>
          </g>

          {/* Cut/Fill area label (top-right) */}
          <g>
            <rect
              x={width - 140}
              y={8}
              width={132}
              height={18}
              rx={3}
              fill={sectionLabelColor}
              fillOpacity={0.1}
              stroke={sectionLabelColor}
              strokeWidth={0.5}
            />
            <text
              x={width - 134}
              y={21}
              fontSize="9"
              fill={sectionLabelColor}
              fontFamily="monospace"
              fontWeight="600"
            >
              {sectionLabel}{' '}
              {(sectionLabel === 'CUT' || sectionLabel === 'CUT/FILL') &&
                areas.cutArea.toFixed(2) + 'm\u00B2'}
              {sectionLabel === 'CUT/FILL' && ' / '}
              {(sectionLabel === 'FILL' || sectionLabel === 'CUT/FILL') &&
                areas.fillArea.toFixed(2) + 'm\u00B2'}
            </text>
          </g>

          {/* Formation level label */}
          <text
            x={clX + 4}
            y={formSvgY - 4}
            fontSize="6"
            fill={COLORS.labelSecondary}
            fontFamily="monospace"
          >
            FL {computedFormationLevel.toFixed(3)}
          </text>

          {/* Subgrade level label */}
          {template.subgradeDepth > 0 && (
            <text
              x={toSvgX(shoulderEndOffset + 3)}
              y={subgradeSvgY + 3}
              fontSize="6"
              fill={COLORS.labelSecondary}
              fontFamily="monospace"
            >
              SG {subgradeLevel.toFixed(3)}
            </text>
          )}

          {/* Slope ratio labels */}
          {leftSlopePoints && activeSlopeRatio > 0 && (
            <text
              x={(leftSlopePoints.x1 + leftSlopePoints.x2) / 2}
              y={Math.min(leftSlopePoints.y1, leftSlopePoints.y2) - 4}
              fontSize="6"
              fill={COLORS.labelSecondary}
              textAnchor="middle"
              fontFamily="monospace"
            >
              {activeSlopeStr}
            </text>
          )}
          {rightSlopePoints && activeSlopeRatio > 0 && (
            <text
              x={(rightSlopePoints.x1 + rightSlopePoints.x2) / 2}
              y={Math.min(rightSlopePoints.y1, rightSlopePoints.y2) - 4}
              fontSize="6"
              fill={COLORS.labelSecondary}
              textAnchor="middle"
              fontFamily="monospace"
            >
              {activeSlopeStr}
            </text>
          )}

          {/* Camber label */}
          <text
            x={clX}
            y={formSvgY + 12}
            fontSize="6"
            fill={COLORS.labelSecondary}
            textAnchor="middle"
            fontFamily="monospace"
          >
            {template.camber}% camber
          </text>

          {/* Ground level at centreline */}
          {centreGroundLevel !== null && (
            <text
              x={clX - 4}
              y={toSvgY(centreGroundLevel) - 4}
              fontSize="6"
              fill={COLORS.groundLine}
              textAnchor="end"
              fontFamily="monospace"
            >
              GL {centreGroundLevel.toFixed(3)}
            </text>
          )}

          {/* CL label */}
          <text
            x={clX}
            y={height - 12}
            fontSize="6"
            fill={COLORS.labelSecondary}
            textAnchor="middle"
            fontFamily="monospace"
            fontWeight="500"
          >
            CL
          </text>
        </>
      )}
    </svg>
  )
}

export default CrossSectionRenderer

'use client';

import React, { useState, useMemo, useCallback, useRef } from 'react'
import { cn } from '@/lib/utils'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import { Badge } from '@/components/ui/badge'
import CrossSectionRenderer, { type CrossSectionProps } from './CrossSectionRenderer'

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface SectionData {
  chainage: number
  groundPoints: Array<{ offset: number; level: number }>
  formationLevel: number
  cutArea?: number
  fillArea?: number
}

export interface CrossSectionSeriesProps {
  sections: SectionData[]
  template: CrossSectionProps['template']
  interval?: number
}

interface SectionSummary {
  chainage: number
  cutArea: number
  fillArea: number
  isMaxCut: boolean
  isMaxFill: boolean
  sectionType: 'cut' | 'fill' | 'level' | 'mixed'
}

// ─── THUMBNAIL CROSS-SECTION ──────────────────────────────────────────────────

function ThumbnailSection({
  section,
  template,
  summary,
  isSelected,
  onClick,
}: {
  section: SectionData
  template: CrossSectionProps['template']
  summary: SectionSummary
  isSelected: boolean
  onClick: () => void
}) {
  const borderColor = summary.isMaxCut
    ? 'border-red-500 ring-2 ring-red-500/30'
    : summary.isMaxFill
      ? 'border-blue-500 ring-2 ring-blue-500/30'
      : isSelected
        ? 'border-amber-500 ring-2 ring-amber-500/30'
        : 'border-border'

  const bgColor = summary.isMaxCut
    ? 'bg-red-50 dark:bg-red-950/30'
    : summary.isMaxFill
      ? 'bg-blue-50 dark:bg-blue-950/30'
      : 'bg-white dark:bg-zinc-900'

  const typeColor =
    summary.sectionType === 'cut'
      ? 'bg-red-100 text-red-700 dark:bg-red-900/50 dark:text-red-300'
      : summary.sectionType === 'fill'
        ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/50 dark:text-blue-300'
        : summary.sectionType === 'mixed'
          ? 'bg-purple-100 text-purple-700 dark:bg-purple-900/50 dark:text-purple-300'
          : 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400'

  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        'flex-shrink-0 rounded-lg border-2 overflow-hidden transition-all duration-200',
        'hover:shadow-md hover:scale-[1.02] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
        borderColor,
        bgColor
      )}
      aria-label={`Cross-section at chainage ${section.chainage}`}
    >
      <div className="w-[200px] h-[100px]">
        <CrossSectionRenderer
          chainage={section.chainage}
          groundPoints={section.groundPoints}
          template={template}
          formationLevel={section.formationLevel}
          cutArea={section.cutArea}
          fillArea={section.fillArea}
          width={200}
          height={100}
          showLabels={false}
        />
      </div>
      <div className="px-2 py-1.5 border-t border-border">
        <div className="flex items-center justify-between gap-1">
          <span className="text-[10px] font-mono font-semibold truncate">
            CH {(section.chainage / 1000).toFixed(1)}+{(section.chainage % 1000).toFixed(0).padStart(3, '0')}
          </span>
          <span
            className={cn(
              'text-[9px] px-1.5 py-0.5 rounded font-medium',
              typeColor
            )}
          >
            {summary.sectionType.toUpperCase()}
          </span>
        </div>
        <div className="flex items-center justify-between mt-0.5 text-[9px] font-mono text-muted-foreground">
          <span className="text-red-600 dark:text-red-400">
            C:{summary.cutArea.toFixed(1)}
          </span>
          <span className="text-blue-600 dark:text-blue-400">
            F:{summary.fillArea.toFixed(1)}
          </span>
        </div>
      </div>
    </button>
  )
}

// ─── MAIN SERIES COMPONENT ────────────────────────────────────────────────────

export function CrossSectionSeries({
  sections,
  template,
  interval = 20,
}: CrossSectionSeriesProps) {
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null)
  const scrollRef = useRef<HTMLDivElement>(null)

  // Compute summaries for each section
  const summaries = useMemo<SectionSummary[]>(() => {
    if (sections.length === 0) return []

    let maxCutArea = 0
    let maxFillArea = 0

    const computed = sections.map((section) => {
      let cutArea = section.cutArea ?? 0
      let fillArea = section.fillArea ?? 0

      // Determine section type from areas
      let sectionType: SectionSummary['sectionType'] = 'level'
      if (cutArea > 0.01 && fillArea > 0.01) {
        sectionType = 'mixed'
      } else if (cutArea > 0.01) {
        sectionType = 'cut'
      } else if (fillArea > 0.01) {
        sectionType = 'fill'
      }

      if (cutArea > maxCutArea) maxCutArea = cutArea
      if (fillArea > maxFillArea) maxFillArea = fillArea

      return {
        chainage: section.chainage,
        cutArea,
        fillArea,
        isMaxCut: false,
        isMaxFill: false,
        sectionType,
      }
    })

    // Mark max cut and max fill sections
    // In case of ties, mark all sections with the max value
    for (const s of computed) {
      if (s.cutArea > 0 && Math.abs(s.cutArea - maxCutArea) < 0.01) {
        s.isMaxCut = true
      }
      if (s.fillArea > 0 && Math.abs(s.fillArea - maxFillArea) < 0.01) {
        s.isMaxFill = true
      }
    }

    return computed
  }, [sections])

  // Aggregate stats
  const stats = useMemo(() => {
    const totalCut = summaries.reduce((s, v) => s + v.cutArea, 0)
    const totalFill = summaries.reduce((s, v) => s + v.fillArea, 0)
    const cutCount = summaries.filter(s => s.sectionType === 'cut' || s.sectionType === 'mixed').length
    const fillCount = summaries.filter(s => s.sectionType === 'fill' || s.sectionType === 'mixed').length
    const maxCutSection = summaries.find(s => s.isMaxCut)
    const maxFillSection = summaries.find(s => s.isMaxFill)

    return {
      totalCut,
      totalFill,
      netArea: totalCut - totalFill,
      cutCount,
      fillCount,
      maxCutSection,
      maxFillSection,
      sectionCount: sections.length,
    }
  }, [summaries, sections.length])

  const selectedSection = selectedIdx !== null ? sections[selectedIdx] : null
  const selectedSummary = selectedIdx !== null ? summaries[selectedIdx] : null

  const handleSelect = useCallback((idx: number) => {
    setSelectedIdx(idx)
  }, [])

  const handleClose = useCallback(() => {
    setSelectedIdx(null)
  }, [])

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (selectedIdx === null) return
      if (e.key === 'ArrowRight' && selectedIdx < sections.length - 1) {
        setSelectedIdx(selectedIdx + 1)
        // Scroll the selected thumbnail into view
        const container = scrollRef.current
        if (container) {
          const thumbnailWidth = 208 // 200 + 8 gap
          container.scrollLeft += thumbnailWidth
        }
      } else if (e.key === 'ArrowLeft' && selectedIdx > 0) {
        setSelectedIdx(selectedIdx - 1)
        const container = scrollRef.current
        if (container) {
          const thumbnailWidth = 208
          container.scrollLeft -= thumbnailWidth
        }
      } else if (e.key === 'Escape') {
        setSelectedIdx(null)
      }
    },
    [selectedIdx, sections.length]
  )

  if (sections.length === 0) {
    return (
      <div className="flex items-center justify-center p-12 text-muted-foreground">
        <div className="text-center">
          <svg
            className="mx-auto h-12 w-12 mb-3 opacity-40"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={1.5}
              d="M4 6h16M4 10h16M4 14h16M4 18h16"
            />
          </svg>
          <p className="text-sm font-medium">No cross-section data</p>
          <p className="text-xs mt-1">
            Add ground profile points and formation levels to generate cross-sections.
          </p>
        </div>
      </div>
    )
  }

  return (
    <div
      className="space-y-4"
      onKeyDown={handleKeyDown}
      tabIndex={0}
      role="listbox"
      aria-label="Cross-section series"
    >
      {/* ── Summary Stats Bar ── */}
      <div className="flex flex-wrap items-center gap-3 px-1">
        <Badge variant="outline" className="text-xs font-mono">
          {stats.sectionCount} sections
        </Badge>
        <Badge variant="outline" className="text-xs font-mono text-red-600 border-red-200 dark:text-red-400 dark:border-red-800">
          Cut: {stats.totalCut.toFixed(1)} m&sup2; ({stats.cutCount})
        </Badge>
        <Badge variant="outline" className="text-xs font-mono text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800">
          Fill: {stats.totalFill.toFixed(1)} m&sup2; ({stats.fillCount})
        </Badge>
        <Badge
          variant="outline"
          className={cn(
            'text-xs font-mono',
            stats.netArea >= 0
              ? 'text-red-600 border-red-200 dark:text-red-400 dark:border-red-800'
              : 'text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800'
          )}
        >
          Net: {Math.abs(stats.netArea).toFixed(1)} m&sup2;{' '}
          {stats.netArea >= 0 ? '(cut)' : '(fill)'}
        </Badge>
        {stats.maxCutSection && (
          <Badge variant="outline" className="text-xs font-mono text-red-700 bg-red-50 dark:text-red-300 dark:bg-red-950/50">
            Max cut: CH {stats.maxCutSection.chainage.toFixed(0)} ({stats.maxCutSection.cutArea.toFixed(1)} m&sup2;)
          </Badge>
        )}
        {stats.maxFillSection && (
          <Badge variant="outline" className="text-xs font-mono text-blue-700 bg-blue-50 dark:text-blue-300 dark:bg-blue-950/50">
            Max fill: CH {stats.maxFillSection.chainage.toFixed(0)} ({stats.maxFillSection.fillArea.toFixed(1)} m&sup2;)
          </Badge>
        )}
        <div className="ml-auto text-xs text-muted-foreground">
          Interval: {interval}m
        </div>
      </div>

      {/* ── Thumbnail Strip ── */}
      <div
        ref={scrollRef}
        className="flex gap-2 overflow-x-auto pb-2 snap-x snap-mandatory scrollbar-thin"
        role="list"
      >
        {sections.map((section, idx) => (
          <div
            key={section.chainage}
            className="snap-start"
            role="option"
            aria-selected={selectedIdx === idx}
          >
            <ThumbnailSection
              section={section}
              template={template}
              summary={summaries[idx]}
              isSelected={selectedIdx === idx}
              onClick={() => handleSelect(idx)}
            />
          </div>
        ))}
      </div>

      {/* ── Navigation Hints ── */}
      <div className="flex items-center justify-between px-1 text-[10px] text-muted-foreground">
        <span>Click a section to view details</span>
        {selectedIdx !== null && (
          <span className="font-mono">
            Use &larr; &rarr; arrow keys to navigate &bull; Esc to close
          </span>
        )}
      </div>

      {/* ── Expanded Detail Dialog ── */}
      <Dialog
        open={selectedIdx !== null}
        onOpenChange={(open) => {
          if (!open) handleClose()
        }}
      >
        <DialogContent className="sm:max-w-4xl max-h-[90vh] overflow-y-auto p-0">
          {selectedSection && selectedSummary && (
            <>
              <DialogHeader className="px-6 pt-6 pb-2">
                <DialogTitle className="flex items-center gap-3">
                  <span className="font-mono">
                    Cross-Section at CH{' '}
                    {selectedSection.chainage.toFixed(1)}
                  </span>
                  <Badge
                    variant="outline"
                    className={cn(
                      'text-xs',
                      selectedSummary.sectionType === 'cut' &&
                        'text-red-600 border-red-200 dark:text-red-400',
                      selectedSummary.sectionType === 'fill' &&
                        'text-blue-600 border-blue-200 dark:text-blue-400',
                      selectedSummary.sectionType === 'mixed' &&
                        'text-purple-600 border-purple-200 dark:text-purple-400'
                    )}
                  >
                    {selectedSummary.sectionType.toUpperCase()}
                  </Badge>
                  {selectedSummary.isMaxCut && (
                    <Badge className="text-xs bg-red-100 text-red-700 dark:bg-red-900/50 dark:text-red-300">
                      MAX CUT
                    </Badge>
                  )}
                  {selectedSummary.isMaxFill && (
                    <Badge className="text-xs bg-blue-100 text-blue-700 dark:bg-blue-900/50 dark:text-blue-300">
                      MAX FILL
                    </Badge>
                  )}
                </DialogTitle>
                <DialogDescription className="sr-only">
                  Detailed cross-section view for chainage{' '}
                  {selectedSection.chainage}
                </DialogDescription>
              </DialogHeader>

              {/* Full-size renderer */}
              <div className="px-4 pb-2">
                <CrossSectionRenderer
                  chainage={selectedSection.chainage}
                  groundPoints={selectedSection.groundPoints}
                  template={template}
                  formationLevel={selectedSection.formationLevel}
                  cutArea={selectedSection.cutArea}
                  fillArea={selectedSection.fillArea}
                  width={800}
                  height={400}
                  showLabels={true}
                />
              </div>

              {/* Detail data table */}
              <div className="px-6 pb-6">
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-2">
                  <div className="space-y-1">
                    <span className="text-xs text-muted-foreground block">
                      Formation Level
                    </span>
                    <span className="text-sm font-mono font-semibold">
                      {selectedSection.formationLevel.toFixed(3)} m
                    </span>
                  </div>
                  <div className="space-y-1">
                    <span className="text-xs text-muted-foreground block">
                      Cut Area
                    </span>
                    <span className="text-sm font-mono font-semibold text-red-600 dark:text-red-400">
                      {selectedSummary.cutArea.toFixed(3)} m&sup2;
                    </span>
                  </div>
                  <div className="space-y-1">
                    <span className="text-xs text-muted-foreground block">
                      Fill Area
                    </span>
                    <span className="text-sm font-mono font-semibold text-blue-600 dark:text-blue-400">
                      {selectedSummary.fillArea.toFixed(3)} m&sup2;
                    </span>
                  </div>
                  <div className="space-y-1">
                    <span className="text-xs text-muted-foreground block">
                      Net Area
                    </span>
                    <span
                      className={cn(
                        'text-sm font-mono font-semibold',
                        (selectedSummary.cutArea - selectedSummary.fillArea) >= 0
                          ? 'text-red-600 dark:text-red-400'
                          : 'text-blue-600 dark:text-blue-400'
                      )}
                    >
                      {Math.abs(
                        selectedSummary.cutArea - selectedSummary.fillArea
                      ).toFixed(3)}{' '}
                      m&sup2;{' '}
                      {(selectedSummary.cutArea - selectedSummary.fillArea) >= 0
                        ? '(cut)'
                        : '(fill)'}
                    </span>
                  </div>
                </div>

                {/* Template info */}
                <div className="mt-4 pt-3 border-t">
                  <span className="text-xs text-muted-foreground block mb-2">
                    Road Template
                  </span>
                  <div className="grid grid-cols-3 sm:grid-cols-6 gap-2 text-xs font-mono">
                    <div>
                      <span className="text-muted-foreground">CW: </span>
                      {template.carriagewayWidth}m
                    </div>
                    <div>
                      <span className="text-muted-foreground">SH: </span>
                      {template.shoulderWidth}m
                    </div>
                    <div>
                      <span className="text-muted-foreground">Cut: </span>
                      {template.cutSlope}
                    </div>
                    <div>
                      <span className="text-muted-foreground">Fill: </span>
                      {template.fillSlope}
                    </div>
                    <div>
                      <span className="text-muted-foreground">Camber: </span>
                      {template.camber}%
                    </div>
                    <div>
                      <span className="text-muted-foreground">SG: </span>
                      {template.subgradeDepth}m
                    </div>
                  </div>
                </div>

                {/* Prev/Next navigation */}
                <div className="flex items-center justify-between mt-4 pt-3 border-t">
                  <button
                    type="button"
                    onClick={() =>
                      selectedIdx !== null &&
                      selectedIdx > 0 &&
                      setSelectedIdx(selectedIdx - 1)
                    }
                    disabled={selectedIdx === 0}
                    className="text-xs font-medium px-3 py-1.5 rounded-md border border-border hover:bg-accent disabled:opacity-40 disabled:pointer-events-none transition-colors"
                  >
                    &larr; Previous Section
                  </button>
                  <span className="text-xs text-muted-foreground font-mono">
                    {selectedIdx !== null ? selectedIdx + 1 : 0} of{' '}
                    {sections.length}
