  })
}

// ────────────────────────────────────────────────────────────
// SVG Cross-Section Diagram
// ────────────────────────────────────────────────────────────

interface CrossSectionSVGProps {
  reserveWidth: number
  carriagewayWidth: number
  shoulderWidth: number
  wayleaveWidth?: number
}

function CrossSectionDiagram({
  reserveWidth,
  carriagewayWidth,
  shoulderWidth,
  wayleaveWidth,
}: CrossSectionSVGProps) {
  const svgWidth = 700
  const svgHeight = 220
  const padding = 30
  const usableWidth = svgWidth - padding * 2
  const groundY = 110
  const groundLineY = groundY + 50

  // Scale factor: reserveWidth maps to usableWidth
  const scale = usableWidth / reserveWidth
  const centreX = svgWidth / 2

  const cw = carriagewayWidth * scale
  const sw = shoulderWidth * scale
  const rw = reserveWidth * scale

  // Wayleave bands (from reserve edge inward)
  const wlW = wayleaveWidth ? wayleaveWidth * scale : 0

  return (
    <svg
      viewBox={`0 0 ${svgWidth} ${svgHeight}`}
      className="w-full h-auto rounded-lg border bg-muted/30"
      role="img"
      aria-label="Road reserve cross-section diagram"
    >
      {/* Title */}
      <text x={svgWidth / 2} y={22} textAnchor="middle" className="text-[11px] font-semibold fill-foreground">
        Road Reserve Cross-Section (Not to Scale)
      </text>

      {/* Ground fill */}
      <rect
        x={centreX - rw / 2}
        y={groundY}
        width={rw}
        height={groundLineY - groundY + 30}
        fill="#e2e8f0"
        opacity={0.5}
        rx={2}
      />

      {/* Wayleave bands (left and right) */}
      {wlW > 0 && (
        <>
          <rect
            x={centreX - rw / 2}
            y={groundY}
            width={wlW}
            height={groundLineY - groundY}
            fill="#bae6fd"
            opacity={0.5}
            rx={1}
          />
          <rect
            x={centreX + rw / 2 - wlW}
            y={groundY}
            width={wlW}
            height={groundLineY - groundY}
            fill="#bae6fd"
            opacity={0.5}
            rx={1}
          />
          {/* Wayleave label left */}
          <text x={centreX - rw / 2 + wlW / 2} y={groundLineY + 16} textAnchor="middle" className="text-[9px] fill-sky-700">
            Wayleave
          </text>
          <text x={centreX - rw / 2 + wlW / 2} y={groundLineY + 28} textAnchor="middle" className="text-[9px] fill-sky-700">
            {wayleaveWidth}m
          </text>
          {/* Wayleave label right */}
          <text x={centreX + rw / 2 - wlW / 2} y={groundLineY + 16} textAnchor="middle" className="text-[9px] fill-sky-700">
            Wayleave
          </text>
          <text x={centreX + rw / 2 - wlW / 2} y={groundLineY + 28} textAnchor="middle" className="text-[9px] fill-sky-700">
            {wayleaveWidth}m
          </text>
        </>
      )}

      {/* Left reserve area (green) */}
      <rect
        x={centreX - rw / 2 + (wlW > 0 ? wlW : 0)}
        y={groundY}
        width={rw / 2 - cw / 2 - sw + (wlW > 0 ? -wlW : 0)}
        height={groundLineY - groundY}
        fill="#bbf7d0"
        opacity={0.7}
      />
      {/* Right reserve area (green) */}
      <rect
        x={centreX + cw / 2 + sw}
        y={groundY}
        width={rw / 2 - cw / 2 - sw - (wlW > 0 ? wlW : 0)}
        height={groundLineY - groundY}
        fill="#bbf7d0"
        opacity={0.7}
      />

      {/* Left shoulder */}
      <rect
        x={centreX - cw / 2 - sw}
        y={groundY}
        width={sw}
        height={groundLineY - groundY}
        fill="#94a3b8"
        rx={1}
      />
      {/* Right shoulder */}
      <rect
        x={centreX + cw / 2}
        y={groundY}
        width={sw}
        height={groundLineY - groundY}
        fill="#94a3b8"
        rx={1}
      />

      {/* Carriageway */}
      <rect
        x={centreX - cw / 2}
        y={groundY}
        width={cw}
        height={groundLineY - groundY}
        fill="#64748b"
        rx={2}
      />

      {/* Centreline (dashed) */}
      <line
        x1={centreX}
        y1={groundY - 10}
        x2={centreX}
        y2={groundLineY + 5}
        stroke="#f59e0b"
        strokeWidth={2}
        strokeDasharray="6 4"
      />

      {/* Carriageway edge lines */}
      <line x1={centreX - cw / 2} y1={groundY} x2={centreX - cw / 2} y2={groundLineY} stroke="white" strokeWidth={2} />
      <line x1={centreX + cw / 2} y1={groundY} x2={centreX + cw / 2} y2={groundLineY} stroke="white" strokeWidth={2} />

      {/* Shoulder edge lines */}
      <line x1={centreX - cw / 2 - sw} y1={groundY} x2={centreX - cw / 2 - sw} y2={groundLineY} stroke="#cbd5e1" strokeWidth={1} strokeDasharray="4 3" />
      <line x1={centreX + cw / 2 + sw} y1={groundY} x2={centreX + cw / 2 + sw} y2={groundLineY} stroke="#cbd5e1" strokeWidth={1} strokeDasharray="4 3" />

      {/* Reserve boundary lines */}
      <line x1={centreX - rw / 2} y1={groundY - 5} x2={centreX - rw / 2} y2={groundLineY + 5} stroke="#16a34a" strokeWidth={2.5} />
      <line x1={centreX + rw / 2} y1={groundY - 5} x2={centreX + rw / 2} y2={groundLineY + 5} stroke="#16a34a" strokeWidth={2.5} />

      {/* Width dimension lines and labels */}
      {/* Reserve width — top */}
      <line x1={centreX - rw / 2} y1={groundY - 8} x2={centreX + rw / 2} y2={groundY - 8} stroke="#16a34a" strokeWidth={1} markerStart="url(#arrowStart)" markerEnd="url(#arrowEnd)" />
      <rect x={centreX - 35} y={groundY - 22} width={70} height={14} rx={2} fill="white" opacity={0.9} />
      <text x={centreX} y={groundY - 12} textAnchor="middle" className="text-[10px] font-semibold fill-green-700">
        Reserve {reserveWidth}m
      </text>

      {/* Carriageway — bottom */}
      <line x1={centreX - cw / 2} y1={groundLineY + 8} x2={centreX + cw / 2} y2={groundLineY + 8} stroke="#475569" strokeWidth={1} />
      <rect x={centreX - 40} y={groundLineY + 12} width={80} height={14} rx={2} fill="white" opacity={0.9} />
      <text x={centreX} y={groundLineY + 23} textAnchor="middle" className="text-[10px] font-medium fill-slate-600">
        Carriageway {carriagewayWidth}m
      </text>

      {/* Left shoulder label */}
      <text x={centreX - cw / 2 - sw / 2} y={groundY + (groundLineY - groundY) / 2 + 4} textAnchor="middle" className="text-[9px] fill-white font-medium">
        {shoulderWidth}m
      </text>
      {/* Right shoulder label */}
      <text x={centreX + cw / 2 + sw / 2} y={groundY + (groundLineY - groundY) / 2 + 4} textAnchor="middle" className="text-[9px] fill-white font-medium">
        {shoulderWidth}m
      </text>

      {/* Centreline label */}
      <text x={centreX} y={groundY - 2} textAnchor="middle" className="text-[8px] fill-amber-700 font-semibold">CL</text>

      {/* Legend */}
      <rect x={padding} y={svgHeight - 30} width={12} height={8} rx={1} fill="#bbf7d0" stroke="#16a34a" strokeWidth={0.5} />
      <text x={padding + 16} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Reserve</text>
      <rect x={padding + 65} y={svgHeight - 30} width={12} height={8} rx={1} fill="#94a3b8" />
      <text x={padding + 81} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Shoulder</text>
      <rect x={padding + 145} y={svgHeight - 30} width={12} height={8} rx={1} fill="#64748b" />
      <text x={padding + 161} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Carriageway</text>
      <line x1={padding + 235} y1={svgHeight - 26} x2={padding + 255} y2={svgHeight - 26} stroke="#f59e0b" strokeWidth={2} strokeDasharray="4 3" />
      <text x={padding + 259} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Centreline</text>
      {wlW > 0 && (
        <>
          <rect x={padding + 325} y={svgHeight - 30} width={12} height={8} rx={1} fill="#bae6fd" opacity={0.5} />
          <text x={padding + 341} y={svgHeight - 23} className="text-[9px] fill-muted-foreground">Wayleave</text>
        </>
      )}

      {/* Arrow markers */}
      <defs>
        <marker id="arrowStart" markerWidth="6" markerHeight="6" refX="6" refY="3" orient="auto">
          <path d="M6 0 L0 3 L6 6" fill="none" stroke="#16a34a" strokeWidth={1} />
        </marker>
        <marker id="arrowEnd" markerWidth="6" markerHeight="6" refX="0" refY="3" orient="auto">
          <path d="M0 0 L6 3 L0 6" fill="none" stroke="#16a34a" strokeWidth={1} />
        </marker>
      </defs>
    </svg>
  )
}

// ────────────────────────────────────────────────────────────
// Placeholder parcel list for future integration
// ────────────────────────────────────────────────────────────

interface PlaceholderParcel {
  id: string
  lrNo: string
  owner: string
  overlapPct: number
  hasBuilding: boolean
}

const PLACEHOLDER_PARCELS: PlaceholderParcel[] = [
  { id: '1', lrNo: 'LR 12345/456', owner: 'Kamau J.', overlapPct: 95, hasBuilding: true },
  { id: '2', lrNo: 'LR 12345/457', owner: 'Ochieng W.', overlapPct: 45, hasBuilding: false },
  { id: '3', lrNo: 'LR 12345/458', owner: 'Wanjiku M.', overlapPct: 12, hasBuilding: false },
  { id: '4', lrNo: 'LR 12345/459', owner: 'Kipruto D.', overlapPct: 62, hasBuilding: true },
  { id: '5', lrNo: 'LR 12345/460', owner: 'Hassan A.', overlapPct: 5, hasBuilding: false },
]

// ────────────────────────────────────────────────────────────
// Main Component
// ────────────────────────────────────────────────────────────

export default function RoadReservePanel({
  roadClass,
  roadLength,
  existingRoadWidth: propExistingWidth,
}: RoadReservePanelProps) {
  // ── State ──
  const standards = ROAD_RESERVE_STANDARDS[roadClass]
  const reserveInfo = getRoadReserveWidth(roadClass)

  const [proposedWidth, setProposedWidth] = useState<string>(
    String(reserveInfo.standard),
  )
  const [roadLengthInput, setRoadLengthInput] = useState<string>(
    String(roadLength ?? 1000),
  )
  const [existingWidth, setExistingWidth] = useState<string>(
    String(propExistingWidth ?? 0),
  )
  const [wayleaveWidth, setWayleaveWidth] = useState<string>('3.0')
  const [showWayleave, setShowWayleave] = useState(true)

  // ── Computed values ──
  const proposedNum = parseFloat(proposedWidth) || 0
  const roadLengthNum = parseFloat(roadLengthInput) || 0
  const existingNum = parseFloat(existingWidth) || 0
  const wayleaveNum = parseFloat(wayleaveWidth) || 0

  const compliance = useMemo(
    () => checkRoadReserveCompliance(roadClass, proposedNum),
    [roadClass, proposedNum],
  )

  const acquisition = useMemo(
    () => estimateAcquisitionArea(roadLengthNum, proposedNum, existingNum),
    [roadLengthNum, proposedNum, existingNum],
  )

  const compliancePercent = useMemo(() => {
    if (compliance.required === 0) return 0
    return Math.min(100, (proposedNum / compliance.required) * 100)
  }, [proposedNum, compliance.required])

  const handleProposedWidthChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value
      if (v === '' || /^\d*\.?\d*$/.test(v)) {
        setProposedWidth(v)
      }
    },
    [],
  )

  const handleLengthChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value
      if (v === '' || /^\d*\.?\d*$/.test(v)) {
        setRoadLengthInput(v)
      }
    },
    [],
  )

  const handleExistingWidthChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value
      if (v === '' || /^\d*\.?\d*$/.test(v)) {
        setExistingWidth(v)
      }
    },
    [],
  )

  const handleWayleaveChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const v = e.target.value
      if (v === '' || /^\d*\.?\d*$/.test(v)) {
        setWayleaveWidth(v)
      }
    },
    [],
  )

  // ── Render ──
  if (!standards) {
    return (
      <Card>
        <CardContent className="p-6">
          <p className="text-muted-foreground text-sm">
            Select a valid road class to view road reserve information.
          </p>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-4">
      {/* ────────────────────────────────────────────────── */}
      {/* Card 1: Road Reserve Standard                     */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Ruler className="h-4 w-4 text-primary" />
            <CardTitle>Road Reserve Standard</CardTitle>
          </div>
          <CardDescription>
            Class {roadClass} — {standards.description}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="rounded-lg border p-3">
              <p className="text-xs text-muted-foreground mb-1">Minimum Reserve</p>
              <p className="text-lg font-bold">{standards.reserveWidthMin}m</p>
            </div>
            <div className="rounded-lg border p-3">
              <p className="text-xs text-muted-foreground mb-1">Standard Reserve</p>
              <p className="text-lg font-bold">{standards.reserveWidthStd}m</p>
            </div>
            <div className="rounded-lg border p-3">
              <p className="text-xs text-muted-foreground mb-1">Carriageway</p>
              <p className="text-lg font-bold">{standards.carriagewayStd}m</p>
            </div>
            <div className="rounded-lg border p-3">
              <p className="text-xs text-muted-foreground mb-1">Shoulder</p>
              <p className="text-lg font-bold">{standards.shoulderStd}m</p>
            </div>
          </div>

          {/* Quick reference for all classes */}
          <details className="text-sm">
            <summary className="cursor-pointer text-muted-foreground hover:text-foreground transition-colors">
              View all road classes
            </summary>
            <div className="mt-2 rounded-lg border overflow-hidden">
              <table className="w-full text-xs">
                <thead>
                  <tr className="bg-muted/50">
                    <th className="text-left px-3 py-1.5 font-medium">Class</th>
                    <th className="text-left px-3 py-1.5 font-medium">Description</th>
                    <th className="text-right px-3 py-1.5 font-medium">Min (m)</th>
                    <th className="text-right px-3 py-1.5 font-medium">Std (m)</th>
                    <th className="text-right px-3 py-1.5 font-medium">CW (m)</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.values(ROAD_RESERVE_STANDARDS).map((s) => (
                    <tr
                      key={s.class}
                      className={
                        s.class === roadClass
                          ? 'bg-primary/5 font-semibold'
                          : 'border-t'
                      }
                    >
                      <td className="px-3 py-1.5">{s.class}</td>
                      <td className="px-3 py-1.5">{s.description}</td>
                      <td className="text-right px-3 py-1.5">{s.reserveWidthMin}</td>
                      <td className="text-right px-3 py-1.5">{s.reserveWidthStd}</td>
                      <td className="text-right px-3 py-1.5">{s.carriagewayStd}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </details>
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 2: Compliance Check                          */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-primary" />
              <CardTitle>Reserve Width Compliance</CardTitle>
            </div>
            {compliance.compliant ? (
              <Badge className="bg-emerald-100 text-emerald-800 dark:bg-emerald-900/40 dark:text-emerald-300 border-emerald-200 dark:border-emerald-800">
                <CheckCircle2 className="h-3 w-3 mr-1" />
                Compliant
              </Badge>
            ) : (
              <Badge className="bg-red-100 text-red-800 dark:bg-red-900/40 dark:text-red-300 border-red-200 dark:border-red-800">
                <XCircle className="h-3 w-3 mr-1" />
                Non-Compliant
              </Badge>
            )}
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="proposed-width">Proposed Reserve Width (m)</Label>
              <Input
                id="proposed-width"
                type="text"
                inputMode="decimal"
                value={proposedWidth}
                onChange={handleProposedWidthChange}
                placeholder={String(reserveInfo.standard)}
              />
              <p className="text-xs text-muted-foreground">
                Minimum required: <span className="font-semibold">{standards.reserveWidthMin}m</span>
                {' · '}Standard: <span className="font-semibold">{standards.reserveWidthStd}m</span>
              </p>
            </div>
            <div className="space-y-2">
              <Label>Compliance Status</Label>
              <div className="h-9 flex items-center">
                {compliance.compliant ? (
                  <div className="flex items-center gap-2 text-emerald-700 dark:text-emerald-400">
                    <CheckCircle2 className="h-5 w-5" />
                    <span className="text-sm font-medium">
                      Meets minimum ({formatNumber(proposedNum)}m ≥ {standards.reserveWidthMin}m)
                    </span>
                  </div>
                ) : (
                  <div className="flex items-center gap-2 text-red-700 dark:text-red-400">
                    <XCircle className="h-5 w-5" />
                    <span className="text-sm font-medium">
                      Deficit of {formatNumber(compliance.deficit)}m
                    </span>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Progress bar */}
          <div className="space-y-1">
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>0m</span>
              <span>Min: {standards.reserveWidthMin}m</span>
              <span>Std: {standards.reserveWidthStd}m</span>
            </div>
            <div className="relative h-3 rounded-full bg-muted overflow-hidden">
              {/* Standard zone marker */}
              <div
                className="absolute top-0 h-full w-px bg-foreground/30 z-10"
                style={{
                  left: `${Math.min(100, (standards.reserveWidthStd / (standards.reserveWidthStd * 1.5)) * 100)}%`,
                }}
              />
              {/* Minimum zone marker */}
              <div
                className="absolute top-0 h-full w-px bg-destructive/50 z-10"
                style={{
                  left: `${Math.min(100, (standards.reserveWidthMin / (standards.reserveWidthStd * 1.5)) * 100)}%`,
                }}
              />
              {/* Fill */}
              <div
                className={`h-full rounded-full transition-all duration-300 ${
                  compliance.compliant ? 'bg-emerald-500' : 'bg-red-500'
                }`}
                style={{
                  width: `${Math.min(100, (proposedNum / (standards.reserveWidthStd * 1.5)) * 100)}%`,
                }}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 3: Cross-Section Diagram                     */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <ArrowRightLeft className="h-4 w-4 text-primary" />
            <CardTitle>Corridor Cross-Section</CardTitle>
          </div>
          <CardDescription>
            Visual representation of the road reserve, carriageway, and shoulders
          </CardDescription>
        </CardHeader>
        <CardContent>
          <CrossSectionDiagram
            reserveWidth={proposedNum || standards.reserveWidthStd}
            carriagewayWidth={standards.carriagewayStd}
            shoulderWidth={standards.shoulderStd}
            wayleaveWidth={showWayleave ? wayleaveNum : undefined}
          />
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 4: Acquisition Estimate                      */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <LandPlot className="h-4 w-4 text-primary" />
            <CardTitle>Land Acquisition Estimate</CardTitle>
          </div>
          <CardDescription>
            Estimated area required for the road reserve corridor
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="road-length">Road Length (m)</Label>
              <Input
                id="road-length"
                type="text"
                inputMode="decimal"
                value={roadLengthInput}
                onChange={handleLengthChange}
                placeholder="1000"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="existing-width">Existing Road Width (m)</Label>
              <Input
                id="existing-width"
                type="text"
                inputMode="decimal"
                value={existingWidth}
                onChange={handleExistingWidthChange}
                placeholder="0"
              />
              <p className="text-xs text-muted-foreground">
                Width of existing carriageway + shoulders already acquired
              </p>
            </div>
            <div className="space-y-2">
              <Label>Reserve Width</Label>
              <div className="h-9 flex items-center rounded-md border bg-muted/50 px-3">
                <span className="text-sm font-medium">{formatNumber(proposedNum)}m</span>
              </div>
            </div>
          </div>

          <Separator />

          {roadLengthNum > 0 && proposedNum > 0 ? (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="rounded-lg border p-4 bg-muted/30">
                <p className="text-xs text-muted-foreground mb-1">Total Reserve Area</p>
                <p className="text-xl font-bold">{formatNumber(acquisition.totalReserveArea)}</p>
                <p className="text-xs text-muted-foreground">sqm</p>
              </div>
              <div className="rounded-lg border p-4 bg-muted/30">
                <p className="text-xs text-muted-foreground mb-1">New Acquisition</p>
                <p className="text-xl font-bold text-amber-700 dark:text-amber-400">
                  {formatNumber(acquisition.newAcquisitionArea)}
                </p>
                <p className="text-xs text-muted-foreground">sqm</p>
              </div>
              <div className="rounded-lg border p-4 bg-muted/30">
                <p className="text-xs text-muted-foreground mb-1">Total Acres</p>
                <p className="text-xl font-bold">{formatNumber(acquisition.totalAcres)}</p>
                <p className="text-xs text-muted-foreground">ac</p>
              </div>
              <div className="rounded-lg border p-4 bg-muted/30">
                <p className="text-xs text-muted-foreground mb-1">Total Hectares</p>
                <p className="text-xl font-bold">{formatNumber(acquisition.totalHectares)}</p>
                <p className="text-xs text-muted-foreground">ha</p>
              </div>
            </div>
          ) : (
            <p className="text-sm text-muted-foreground text-center py-4">
              Enter road length and reserve width to see acquisition estimates.
            </p>
          )}

          {existingNum > 0 && acquisition.newAcquisitionArea > 0 && (
            <div className="rounded-lg border border-amber-200 dark:border-amber-800 bg-amber-50 dark:bg-amber-950/30 p-3 flex items-start gap-2">
              <AlertTriangle className="h-4 w-4 text-amber-600 dark:text-amber-400 mt-0.5 shrink-0" />
              <p className="text-xs text-amber-800 dark:text-amber-200">
                {formatNumber(acquisition.newAcquisitionArea)} sqm of new land acquisition required beyond the
                existing {formatNumber(existingNum)}m road width.
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 5: Property Impact Summary                   */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center gap-2">
            <Building2 className="h-4 w-4 text-primary" />
            <CardTitle>Property Impact Assessment</CardTitle>
          </div>
          <CardDescription>
            Affected parcels and acquisition classification
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="rounded-lg border overflow-hidden">
            <div className="max-h-72 overflow-y-auto custom-scrollbar">
              <table className="w-full text-sm">
                <thead className="sticky top-0 bg-muted/80 backdrop-blur-sm">
                  <tr>
                    <th className="text-left px-4 py-2.5 font-medium text-xs text-muted-foreground">LR No.</th>
                    <th className="text-left px-4 py-2.5 font-medium text-xs text-muted-foreground">Owner</th>
                    <th className="text-right px-4 py-2.5 font-medium text-xs text-muted-foreground">Overlap</th>
                    <th className="text-center px-4 py-2.5 font-medium text-xs text-muted-foreground">Structure</th>
                    <th className="text-left px-4 py-2.5 font-medium text-xs text-muted-foreground">Classification</th>
                  </tr>
                </thead>
                <tbody>
                  {PLACEHOLDER_PARCELS.map((parcel) => {
                    const acqType = determineAcquisitionType(parcel.overlapPct, parcel.hasBuilding)
                    const style = ACQUISITION_STYLES[acqType]
                    return (
                      <tr key={parcel.id} className="border-t hover:bg-muted/30 transition-colors">
                        <td className="px-4 py-2.5 font-mono text-xs">{parcel.lrNo}</td>
                        <td className="px-4 py-2.5">{parcel.owner}</td>
                        <td className="text-right px-4 py-2.5">
                          <div className="flex items-center justify-end gap-2">
                            <Progress value={parcel.overlapPct} className="w-16 h-1.5" />
                            <span className="text-xs tabular-nums w-10 text-right">
                              {parcel.overlapPct}%
                            </span>
                          </div>
                        </td>
                        <td className="text-center px-4 py-2.5">
                          {parcel.hasBuilding ? (
                            <Building2 className="h-3.5 w-3.5 inline text-muted-foreground" />
                          ) : (
                            <LandPlot className="h-3.5 w-3.5 inline text-muted-foreground/50" />
                          )}
                        </td>
                        <td className="px-4 py-2.5">
                          <span
                            className={`inline-flex items-center rounded-md border px-2 py-0.5 text-xs font-medium ${style.bg} ${style.color}`}
                          >
                            {style.label}
                          </span>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          </div>
          <div className="flex flex-wrap gap-3 mt-3">
            {(
              Object.entries(ACQUISITION_STYLES) as [AcquisitionType, (typeof ACQUISITION_STYLES)[AcquisitionType]][]
            ).map(([key, style]) => (
              <div key={key} className="flex items-center gap-1.5">
                <div className={`h-2.5 w-2.5 rounded-sm border ${style.bg}`} />
                <span className="text-xs text-muted-foreground">{style.label}</span>
              </div>
            ))}
          </div>
          <p className="text-xs text-muted-foreground mt-2 italic">
            Parcel data is placeholder for future GIS integration.
          </p>
        </CardContent>
      </Card>

      {/* ────────────────────────────────────────────────── */}
      {/* Card 6: Wayleave Section                          */}
      {/* ────────────────────────────────────────────────── */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Zap className="h-4 w-4 text-primary" />
              <CardTitle>Wayleave / Utility Corridor</CardTitle>
            </div>
            <label className="flex items-center gap-2 cursor-pointer">
              <input aria-label="Showwayleave"
                type="checkbox"
                checked={showWayleave}
                onChange={(e) => setShowWayleave(e.target.checked)}
                className="rounded border-input h-4 w-4"
              />
              <span className="text-xs text-muted-foreground">Show on diagram</span>
            </label>
          </div>
          <CardDescription>
            Utility wayleaves are accommodated within the road reserve corridor
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="wayleave-width">Wayleave Width (m)</Label>
              <Input
                id="wayleave-width"
                type="text"
                inputMode="decimal"
                value={wayleaveWidth}
                onChange={handleWayleaveChange}
                placeholder="3.0"
              />
            </div>
            <div className="space-y-2">
              <Label>Typical Wayleave Widths</Label>
              <div className="flex flex-wrap gap-2">
                {[
                  { label: 'Water', width: 3 },
                  { label: 'Power', width: 4 },
                  { label: 'Fibre', width: 3 },
                  { label: 'Gas', width: 6 },
                  { label: 'Sewer', width: 5 },
                ].map((w) => (
                  <button
                    key={w.label}
                    type="button"
                    onClick={() => setWayleaveWidth(String(w.width))}
                    className="inline-flex items-center gap-1 rounded-md border px-2 py-1 text-xs hover:bg-muted/50 transition-colors cursor-pointer"
                  >
                    {w.label}
                    <span className="text-muted-foreground">{w.width}m</span>
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="rounded-lg border border-sky-200 dark:border-sky-800 bg-sky-50 dark:bg-sky-950/30 p-3 flex items-start gap-2">
            <Zap className="h-4 w-4 text-sky-600 dark:text-sky-400 mt-0.5 shrink-0" />
            <div className="text-xs text-sky-800 dark:text-sky-200 space-y-1">
              <p>
                Wayleaves are utility easements within the road reserve. They do not require separate
                land acquisition but must be within the gazetted reserve width.
              </p>
              <p>
                Standard wayleave widths: 3–6m depending on utility type. Multiple utilities
                may share a common wayleave corridor.
              </p>
            </div>
          </div>

          {/* Wayleave vs reserve check */}
          {wayleaveNum > 0 && proposedNum > 0 && (
            <div className="text-xs">
              {wayleaveNum * 2 <= proposedNum ? (
                <div className="flex items-center gap-1.5 text-emerald-700 dark:text-emerald-400">
                  <CheckCircle2 className="h-3.5 w-3.5" />
                  <span>
                    Wayleave ({wayleaveNum}m × 2 = {formatNumber(wayleaveNum * 2)}m) fits within
                    reserve ({formatNumber(proposedNum)}m)
                  </span>
                </div>
              ) : (
                <div className="flex items-center gap-1.5 text-red-700 dark:text-red-400">
                  <XCircle className="h-3.5 w-3.5" />
                  <span>
                    Wayleave ({wayleaveNum}m × 2 = {formatNumber(wayleaveNum * 2)}m) exceeds reserve width ({formatNumber(proposedNum)}m).
                    Reserve may need widening.
                  </span>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

'use client';

import React, { useState, useCallback, useMemo, useRef } from 'react';
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  type DTMPoint,
  type SlopeAnalysisResult,
  type CutFillDatumResult,
  analyzeSlopeFromPoints,
  computeCutFillDatum,
  slopeAnalysisToCSV,
  computeAreaBetweenPoints,
} from '@/lib/engineering/slopeAnalysis';

// ─── Props ──────────────────────────────────────────────────────────────────

interface SlopeAnalysisPanelProps {
  projectId?: string;
}

// ─── Constants ──────────────────────────────────────────────────────────────

const SLOPE_CLASS_COLORS: Record<string, { bg: string; fill: string; label: string; range: string }> = {
  flat: { bg: 'bg-green-500', fill: '#22c55e', label: 'Flat', range: '0 – 2%' },
  gentle: { bg: 'bg-yellow-400', fill: '#facc15', label: 'Gentle', range: '2 – 5%' },
  moderate: { bg: 'bg-orange-500', fill: '#f97316', label: 'Moderate', range: '5 – 15%' },
  steep: { bg: 'bg-red-500', fill: '#ef4444', label: 'Steep', range: '15 – 35%' },
  very_steep: { bg: 'bg-red-800', fill: '#991b1b', label: 'Very Steep', range: '35 – 60%' },
  cliff: { bg: 'bg-[#800020]', fill: '#800020', label: 'Cliff', range: '> 60%' },
};

const CLASS_ORDER = ['flat', 'gentle', 'moderate', 'steep', 'very_steep', 'cliff'] as const;

// ─── Helpers ────────────────────────────────────────────────────────────────

function downloadBlob(content: string, filename: string, mimeType: string) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function parseDTMCSV(text: string): DTMPoint[] {
  const lines = text
    .trim()
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#') && !l.startsWith('E') && !l.startsWith('Point'));

  const points: DTMPoint[] = [];
  for (const line of lines) {
    // Try comma, tab, space, semicolon separators
    const parts = line.split(/[,;\t]+/).map((s) => s.trim());
    if (parts.length < 2) continue;

    const e = parseFloat(parts[0]);
    const n = parseFloat(parts[1]);
    const z = parts.length >= 3 ? parseFloat(parts[2]) : 0;

    if (isNaN(e) || isNaN(n)) continue;

    points.push({ easting: e, northing: n, elevation: isNaN(z) ? 0 : z });
  }

  return points;
}

function parsePolygonCSV(text: string): DTMPoint[] {
  const lines = text
    .trim()
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#') && !l.startsWith('E'));

  const points: DTMPoint[] = [];
  for (const line of lines) {
    const parts = line.split(/[,;\t]+/).map((s) => s.trim());
    if (parts.length < 2) continue;

    const e = parseFloat(parts[0]);
    const n = parseFloat(parts[1]);

    if (isNaN(e) || isNaN(n)) continue;

    points.push({ easting: e, northing: n, elevation: 0 });
  }

  return points;
}

function generateDemoData(): DTMPoint[] {
  const points: DTMPoint[] = [];
  const baseE = 357600;
  const baseN = 9988200;
  const spacing = 5;

  // Create a 20×20 grid with synthetic terrain
  for (let r = 0; r < 20; r++) {
    for (let c = 0; c < 20; c++) {
      const e = baseE + c * spacing;
      const n = baseN + r * spacing;

      // Gentle slope + hill + valley
      const x = (c - 10) / 10;
      const y = (r - 10) / 10;

      // Gentle overall slope (north to south)
      let z = 1500 - r * 0.8;

      // Hill in the center-right area
      const hillDist = Math.sqrt(Math.pow(c - 14, 2) + Math.pow(r - 7, 2));
      z += 8 * Math.exp(-hillDist * hillDist / 25);

      // Valley running diagonally
      const valleyDist = Math.abs(2 * (c - 10) - (r - 10));
      z -= 4 * Math.exp(-valleyDist * valleyDist / 10);

      // Small random variation
      z += (Math.sin(c * 1.3) * Math.cos(r * 1.7)) * 0.5;

      points.push({ easting: e, northing: n, elevation: z });
    }
  }

  return points;
}

function fmt(val: number, decimals = 2): string {
  return val.toLocaleString('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

function fmtShort(val: number): string {
  if (Math.abs(val) >= 1_000_000) return (val / 1_000_000).toFixed(2) + 'M';
  if (Math.abs(val) >= 1_000) return (val / 1_000).toFixed(1) + 'K';
  return fmt(val, 1);
}

// ─── Component ──────────────────────────────────────────────────────────────

export default function SlopeAnalysisPanel({ projectId }: SlopeAnalysisPanelProps) {
  // Data state
  const [rawText, setRawText] = useState('');
  const [points, setPoints] = useState<DTMPoint[]>([]);
  const [pointCount, setPointCount] = useState(0);

  // Settings
  const [gridRes, setGridRes] = useState<string>('auto');
  const [minElev, setMinElev] = useState<string>('');
  const [maxElev, setMaxElev] = useState<string>('');

  // Analysis results
  const [slopeResult, setSlopeResult] = useState<SlopeAnalysisResult | null>(null);
  const [cutFillResult, setCutFillResult] = useState<CutFillDatumResult | null>(null);
  const [cutFillDatum, setCutFillDatum] = useState<string>('1500');
  const [areaResult, setAreaResult] = useState<number | null>(null);

  // Polygon area
  const [polyText, setPolyText] = useState('');
  const [polyPoints, setPolyPoints] = useState<DTMPoint[]>([]);

  // Loading
  const [analyzing, setAnalyzing] = useState(false);
  const [cutFillLoading, setCutFillLoading] = useState(false);

  // Error
  const [error, setError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // ── Point extent ──

  const extent = useMemo(() => {
    if (points.length === 0) return null;
    let minE = Infinity, minN = Infinity, maxE = -Infinity, maxN = -Infinity;
    let minZ = Infinity, maxZ = -Infinity;
    for (const p of points) {
      if (p.easting < minE) minE = p.easting;
      if (p.northing < minN) minN = p.northing;
      if (p.easting > maxE) maxE = p.easting;
      if (p.northing > maxN) maxN = p.northing;
      if (p.elevation < minZ) minZ = p.elevation;
      if (p.elevation > maxZ) maxZ = p.elevation;
    }
    return { minE, minN, maxE, maxN, minZ, maxZ };
  }, [points]);

  // ── Filter points by elevation ──

  const filteredPoints = useMemo(() => {
    let pts = points;
    const minE = minElev !== '' ? parseFloat(minElev) : null;
    const maxE = maxElev !== '' ? parseFloat(maxElev) : null;
    if (minE !== null && !isNaN(minE)) pts = pts.filter((p) => p.elevation >= minE);
    if (maxE !== null && !isNaN(maxE)) pts = pts.filter((p) => p.elevation <= maxE);
    return pts;
  }, [points, minElev, maxElev]);

  // ── CSV file import ──

  const handleFileImport = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const text = ev.target?.result as string;
      setRawText(text);
      const pts = parseDTMCSV(text);
      setPoints(pts);
      setPointCount(pts.length);
      setError(null);
      setSlopeResult(null);
      setCutFillResult(null);
    };
    reader.readAsText(file);
    // Reset the input so the same file can be re-selected
    e.target.value = '';
  }, []);

  // ── Parse textarea ──

  const handleParseText = useCallback(() => {
    const pts = parseDTMCSV(rawText);
    setPoints(pts);
    setPointCount(pts.length);
    setError(null);
    setSlopeResult(null);
    setCutFillResult(null);
  }, [rawText]);

  // ── Load demo data ──

  const handleLoadDemo = useCallback(() => {
    const demo = generateDemoData();
    const csvLines = ['Easting,Northing,Elevation', ...demo.map((p) => `${p.easting},${p.northing},${p.elevation.toFixed(3)}`)];
    const csv = csvLines.join('\n');
    setRawText(csv);
    setPoints(demo);
    setPointCount(demo.length);
    setError(null);
    setSlopeResult(null);
    setCutFillResult(null);
  }, []);

  // ── Slope Analysis ──

  const handleSlopeAnalysis = useCallback(() => {
    if (filteredPoints.length < 3) {
      setError('At least 3 DTM points are required for slope analysis.');
      return;
    }
    setAnalyzing(true);
    setError(null);
    try {
      const res = gridRes === 'auto' || isNaN(parseFloat(gridRes))
        ? analyzeSlopeFromPoints(filteredPoints)
        : analyzeSlopeFromPoints(filteredPoints, parseFloat(gridRes));
      setSlopeResult(res);
    } catch (err: unknown) {
      setError(err instanceof Error ? (err as Error).message : 'Slope analysis failed.');
    } finally {
      setAnalyzing(false);
    }
  }, [filteredPoints, gridRes]);

  // ── Cut/Fill Analysis ──

  const handleCutFill = useCallback(() => {
    const datum = parseFloat(cutFillDatum);
    if (isNaN(datum)) {
      setError('Please enter a valid datum RL.');
      return;
    }
    if (filteredPoints.length < 3) {
      setError('At least 3 DTM points are required for cut/fill analysis.');
      return;
    }
    setCutFillLoading(true);
    setError(null);
    try {
      const res = gridRes === 'auto' || isNaN(parseFloat(gridRes))
        ? computeCutFillDatum(filteredPoints, datum)
        : computeCutFillDatum(filteredPoints, datum, parseFloat(gridRes));
      setCutFillResult(res);
    } catch (err: unknown) {
      setError(err instanceof Error ? (err as Error).message : 'Cut/fill analysis failed.');
    } finally {
      setCutFillLoading(false);
    }
  }, [filteredPoints, cutFillDatum, gridRes]);

  // ── Area Computation ──

  const handleAreaCompute = useCallback(() => {
    const pts = parsePolygonCSV(polyText);
    if (pts.length < 3) {
      setError('At least 3 polygon points are required for area computation.');
      return;
    }
    setPolyPoints(pts);
    const area = computeAreaBetweenPoints(pts);
    setAreaResult(area);
    setError(null);
  }, [polyText]);

  // ── Export CSVs ──

  const handleExportSlopeCSV = useCallback(() => {
    if (!slopeResult) return;
    const csv = slopeAnalysisToCSV(slopeResult);
    downloadBlob(csv, `slope_analysis_${projectId || 'export'}.csv`, 'text/csv');
  }, [slopeResult, projectId]);

  const handleExportCutFillCSV = useCallback(() => {
    if (!cutFillResult) return;
    const lines: string[] = [
      'Easting,Northing,Existing RL,Design RL,Difference,Classification',
      ...cutFillResult.points.map((p) => {
        const cls = p.difference > 0 ? 'Cut' : p.difference < 0 ? 'Fill' : 'On Grade';
        return `${p.easting.toFixed(4)},${p.northing.toFixed(4)},${p.existingRL.toFixed(4)},${p.designRL.toFixed(4)},${p.difference.toFixed(4)},${cls}`;
      }),
      '',
      'SUMMARY',
      `Cut Volume (m³),${cutFillResult.totalCutVolume.toFixed(3)}`,
      `Fill Volume (m³),${cutFillResult.totalFillVolume.toFixed(3)}`,
      `Net Volume (m³),${cutFillResult.netVolume.toFixed(3)}`,
      `Cut Area (m²),${cutFillResult.cutArea.toFixed(2)}`,
      `Fill Area (m²),${cutFillResult.fillArea.toFixed(2)}`,
      `Balance Point RL,${cutFillResult.balancePoint.toFixed(3)}`,
    ];
    downloadBlob(lines.join('\n'), `cutfill_analysis_${projectId || 'export'}.csv`, 'text/csv');
  }, [cutFillResult, projectId]);

  // ── SVG Slope Heatmap ──

  const slopeHeatmapSVG = useMemo(() => {
    if (!slopeResult || slopeResult.slopePoints.length === 0) return null;

    const bb = slopeResult.boundingBox;
    const rangeE = bb.maxE - bb.minE || 1;
    const rangeN = bb.maxN - bb.minN || 1;

    // Determine grid dimensions from unique E/N values
    const eValues = Array.from(new Set(slopeResult.slopePoints.map((p) => p.easting))).sort((a, b) => a - b);
    const nValues = Array.from(new Set(slopeResult.slopePoints.map((p) => p.northing))).sort((a, b) => b - a);

    const cols = eValues.length;
    const rows = nValues.length;
    if (rows < 2 || cols < 2) return null;

    const svgW = 600;
    const svgH = Math.min(400, (rows / cols) * 600);
    const pad = 40;
    const cellW = (svgW - pad * 2) / (cols - 1 || 1);
    const cellH = (svgH - pad * 2) / (rows - 1 || 1);

    const mapE = (v: number) => pad + ((v - bb.minE) / rangeE) * (svgW - pad * 2);
    const mapN = (v: number) => pad + ((bb.maxN - v) / rangeN) * (svgH - pad * 2);

    // Build a lookup map for fast access
    const pointMap = new Map<string, typeof slopeResult.slopePoints[0]>();
    for (const sp of slopeResult.slopePoints) {
      const key = `${sp.easting.toFixed(3)},${sp.northing.toFixed(3)}`;
      pointMap.set(key, sp);
    }

    const rects: React.ReactNode[] = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const e = eValues[c];
        const n = nValues[r];
        const key = `${e.toFixed(3)},${n.toFixed(3)}`;
        const sp = pointMap.get(key);
        if (!sp) continue;

        const color = SLOPE_CLASS_COLORS[sp.slopeClass]?.fill || '#666';
        const x = mapE(e) - cellW / 2;
        const y = mapN(n) - cellH / 2;

        rects.push(
          <rect
            key={`${r}-${c}`}
            x={x}
            y={y}
            width={cellW + 0.5}
            height={cellH + 0.5}
            fill={color}
            opacity={0.85}
            stroke="#1a1a2e"
            strokeWidth={0.3}
          />
        );
      }
    }

    return (
      <svg
        viewBox={`0 0 ${svgW} ${svgH}`}
        className="w-full max-w-2xl mx-auto rounded-lg border border-zinc-700 bg-zinc-900"
        role="img"
        aria-label="Slope classification heatmap"
      >
        {/* Grid border */}
        <rect
          x={pad - cellW / 2}
          y={pad - cellH / 2}
          width={svgW - pad * 2 + cellW}
          height={svgH - pad * 2 + cellH}
          fill="none"
          stroke="#444"
          strokeWidth={1}
        />

        {/* Heatmap cells */}
        {rects}

        {/* Legend */}
        <g transform={`translate(${svgW - 160}, ${svgH - 30})`}>
          <text x="0" y="0" fill="#aaa" fontSize="10" fontFamily="monospace">0%</text>
          <rect x="25" y="-8" width="20" height="10" fill={SLOPE_CLASS_COLORS.flat.fill} />
          <rect x="45" y="-8" width="20" height="10" fill={SLOPE_CLASS_COLORS.gentle.fill} />
          <rect x="65" y="-8" width="20" height="10" fill={SLOPE_CLASS_COLORS.moderate.fill} />
          <rect x="85" y="-8" width="20" height="10" fill={SLOPE_CLASS_COLORS.steep.fill} />
          <rect x="105" y="-8" width="20" height="10" fill={SLOPE_CLASS_COLORS.very_steep.fill} />
          <rect x="125" y="-8" width="20" height="10" fill={SLOPE_CLASS_COLORS.cliff.fill} />
          <text x="148" y="0" fill="#aaa" fontSize="10" fontFamily="monospace">&gt;60%</text>
        </g>

        {/* Grid resolution label */}
        <text x="pad" y={svgH - 8} fill="#666" fontSize="9" fontFamily="monospace">
          Grid: {slopeResult.gridResolution.toFixed(1)} m
        </text>
      </svg>
    );
  }, [slopeResult]);

  // ── Slope distribution for stacked bar ──

  const slopeDistribution = useMemo(() => {
    if (!slopeResult) return null;
    const dist = slopeResult.statistics.slopeDistribution;
    const areas = slopeResult.statistics.areaByClass;
    const total = slopeResult.statistics.totalArea || 1;

    return CLASS_ORDER.map((cls) => ({
      cls,
      count: dist[cls],
      area: areas[cls],
      pct: ((areas[cls] / total) * 100),
    }));
  }, [slopeResult]);

  // ── Cut/fill table sample ──

  const cutFillSample = useMemo(() => {
    if (!cutFillResult) return [];
    // Show a subset of points (max 50)
    const pts = cutFillResult.points;
    if (pts.length <= 50) return pts;
    const step = Math.ceil(pts.length / 50);
    return pts.filter((_, i) => i % step === 0);
  }, [cutFillResult]);

  // ── Area conversions ──

  const areaConversions = useMemo(() => {
    if (areaResult === null) return null;
    return {
      sqm: areaResult,
      hectares: areaResult / 10000,
      acres: areaResult / 4046.8564224,
    };
  }, [areaResult]);

  // ══════════════════════════════════════════════════════════════════════════
  // Render
  // ══════════════════════════════════════════════════════════════════════════

  return (
    <div className="max-w-7xl mx-auto space-y-6 p-4 md:p-6">
      {/* ── Header ── */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-zinc-100 tracking-tight">
            Slope &amp; Area Analysis
          </h2>
          <p className="text-sm text-zinc-400 mt-1">
            DTM slope classification, cut/fill volumes, and area computation
          </p>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={handleLoadDemo}
          className="border-zinc-600 text-zinc-300 hover:bg-zinc-800 hover:text-blue-400 w-fit"
        >
          <svg viewBox="0 0 16 16" className="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M2 11h4l3-8 3 5 2-3h2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          Load Demo Data
        </Button>
      </div>

      {/* ── Error ── */}
      {error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}

      {/* ── Data Input ── */}
      <Card className="border-zinc-700 bg-zinc-800/50">
        <CardHeader>
          <CardTitle className="text-zinc-100 text-base">Data Input</CardTitle>
          <CardDescription className="text-zinc-400">
            Import DTM points via CSV or paste coordinates (Easting,Northing,Elevation)
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex flex-col sm:flex-row gap-3">
            <input
              ref={fileInputRef}
              type="file"
              accept=".csv,.txt,.xyz"
              onChange={handleFileImport}
              className="hidden"
            />
            <Button
              variant="outline"
              size="sm"
              onClick={() => fileInputRef.current?.click()}
              className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400 w-fit"
            >
              <svg viewBox="0 0 16 16" className="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" strokeWidth="1.5">
                <path d="M8 2v8m0 0l-3-3m3 3l3-3M2 12v2h12v-2" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
              Import CSV
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={handleParseText}
              disabled={!rawText.trim()}
              className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400 w-fit"
            >
              Parse Text
            </Button>
            <div className="flex-1" />
            <Badge variant="secondary" className="font-mono text-xs bg-zinc-700 text-zinc-300 border-zinc-600">
              {pointCount} points loaded
            </Badge>
          </div>

          <Textarea
            value={rawText}
            onChange={(e) => setRawText(e.target.value)}
            placeholder="Easting,Northing,Elevation&#10;357600.0,9988200.0,1500.5&#10;357605.0,9988205.0,1501.2&#10;..."
            className="font-mono text-xs bg-zinc-900 border-zinc-600 text-zinc-300 min-h-[120px] max-h-[200px]"
          />

          {/* Extent info */}
          {extent && (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-2 text-xs font-mono">
              <div className="bg-zinc-900/60 rounded px-2 py-1.5 border border-zinc-700">
                <span className="text-zinc-500">E min: </span>
                <span className="text-zinc-300">{fmt(extent.minE, 2)}</span>
              </div>
              <div className="bg-zinc-900/60 rounded px-2 py-1.5 border border-zinc-700">
                <span className="text-zinc-500">E max: </span>
                <span className="text-zinc-300">{fmt(extent.maxE, 2)}</span>
              </div>
              <div className="bg-zinc-900/60 rounded px-2 py-1.5 border border-zinc-700">
                <span className="text-zinc-500">N min: </span>
                <span className="text-zinc-300">{fmt(extent.minN, 2)}</span>
              </div>
              <div className="bg-zinc-900/60 rounded px-2 py-1.5 border border-zinc-700">
                <span className="text-zinc-500">N max: </span>
                <span className="text-zinc-300">{fmt(extent.maxN, 2)}</span>
              </div>
              <div className="bg-zinc-900/60 rounded px-2 py-1.5 border border-zinc-700">
                <span className="text-zinc-500">Z min: </span>
                <span className="text-blue-400">{fmt(extent.minZ, 2)}</span>
              </div>
              <div className="bg-zinc-900/60 rounded px-2 py-1.5 border border-zinc-700">
                <span className="text-zinc-500">Z max: </span>
                <span className="text-blue-400">{fmt(extent.maxZ, 2)}</span>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* ── Settings ── */}
      <Card className="border-zinc-700 bg-zinc-800/50">
        <CardHeader>
          <CardTitle className="text-zinc-100 text-base">Analysis Settings</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="space-y-1.5">
              <Label className="text-zinc-400 text-xs">Grid Resolution (m)</Label>
              <Input
                value={gridRes}
                onChange={(e) => setGridRes(e.target.value)}
                placeholder="auto"
                className="font-mono text-sm bg-zinc-900 border-zinc-600 text-zinc-300"
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-zinc-400 text-xs">Min Elevation Filter</Label>
              <Input
                value={minElev}
                onChange={(e) => setMinElev(e.target.value)}
                placeholder="(none)"
                type="number"
                className="font-mono text-sm bg-zinc-900 border-zinc-600 text-zinc-300"
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-zinc-400 text-xs">Max Elevation Filter</Label>
              <Input
                value={maxElev}
                onChange={(e) => setMaxElev(e.target.value)}
                placeholder="(none)"
                type="number"
                className="font-mono text-sm bg-zinc-900 border-zinc-600 text-zinc-300"
              />
            </div>
          </div>
          {minElev !== '' || maxElev !== '' ? (
            <p className="text-xs text-zinc-500 mt-2">
              Using {filteredPoints.length} of {points.length} points after elevation filter
            </p>
          ) : null}
        </CardContent>
      </Card>

      {/* ── Main Tabs ── */}
      <Tabs defaultValue="slope" className="space-y-4">
        <TabsList className="bg-zinc-800 border border-zinc-700">
          <TabsTrigger value="slope" className="data-[state=active]:bg-zinc-700 data-[state=active]:text-blue-400 text-zinc-400">
            Slope Analysis
          </TabsTrigger>
          <TabsTrigger value="cutfill" className="data-[state=active]:bg-zinc-700 data-[state=active]:text-blue-400 text-zinc-400">
            Cut / Fill
          </TabsTrigger>
          <TabsTrigger value="area" className="data-[state=active]:bg-zinc-700 data-[state=active]:text-blue-400 text-zinc-400">
            Area Computation
          </TabsTrigger>
        </TabsList>

        {/* ══════════════════════════════════════════════════════════════════ */}
        {/*  TAB 1: SLOPE ANALYSIS                                           */}
        {/* ══════════════════════════════════════════════════════════════════ */}
        <TabsContent value="slope" className="space-y-6">
          <div className="flex items-center gap-3">
            <Button
              onClick={handleSlopeAnalysis}
              disabled={filteredPoints.length < 3 || analyzing}
              className="bg-blue-600 hover:bg-blue-500 text-white"
            >
              {analyzing ? (
                <>
                  <svg className="animate-spin w-4 h-4 mr-1.5" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2">
                    <circle cx="8" cy="8" r="6" strokeOpacity="0.3" />
                    <path d="M14 8a6 6 0 01-6 6" />
                  </svg>
                  Analyzing...
                </>
              ) : (
                <>
                  <svg viewBox="0 0 16 16" className="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" strokeWidth="1.5">
                    <path d="M2 14l4-8 4 5 4-7" strokeLinecap="round" strokeLinejoin="round" />
                  </svg>
                  Run Analysis
                </>
              )}
            </Button>
            {slopeResult && (
              <Button
                variant="outline"
                size="sm"
                onClick={handleExportSlopeCSV}
                className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400"
              >
                <svg viewBox="0 0 16 16" className="w-4 h-4 mr-1.5" fill="none" stroke="currentColor" strokeWidth="1.5">
                  <path d="M8 2v8m0 0l-3-3m3 3l3-3M2 12v2h12v-2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
                Export CSV
              </Button>
            )}
          </div>

          {slopeResult && (
            <>
              {/* ── Summary Cards ── */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <SummaryCard label="Mean Slope" value={`${fmt(slopeResult.statistics.meanSlopePercent)}%`} accent />
                <SummaryCard label="Max Slope" value={`${fmt(slopeResult.statistics.maxSlopePercent)}%`} accent />
                <SummaryCard label="Min Slope" value={`${fmt(slopeResult.statistics.minSlopePercent)}%`} accent />
                <SummaryCard label="Total Area" value={`${fmtShort(slopeResult.statistics.totalArea)} m²`} accent />
              </div>

              {/* ── Slope Classification Distribution ── */}
              <Card className="border-zinc-700 bg-zinc-800/50">
                <CardHeader>
                  <CardTitle className="text-zinc-100 text-sm">Slope Classification Distribution</CardTitle>
                  <CardDescription className="text-zinc-500 text-xs">
                    Horizontal stacked bar — per KENHA / RDM 1.3 standards
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  {/* Stacked bar */}
                  {slopeDistribution && (
                    <div className="space-y-3">
                      {/* Full bar */}
                      <div className="flex rounded-full overflow-hidden h-8 w-full">
                        {slopeDistribution.map((item) => (
                          <div
                            key={item.cls}
                            className="flex items-center justify-center transition-all"
                            style={{
                              width: `${item.pct}%`,
                              backgroundColor: SLOPE_CLASS_COLORS[item.cls]?.fill,
                              minWidth: item.pct > 0 ? '2px' : '0px',
                            }}
                            title={`${SLOPE_CLASS_COLORS[item.cls]?.label}: ${fmt(item.area)} m² (${item.pct.toFixed(1)}%)`}
                          >
                            {item.pct > 5 && (
                              <span className="text-[10px] font-mono text-white font-semibold drop-shadow">
                                {item.pct.toFixed(1)}%
                              </span>
                            )}
                          </div>
                        ))}
                      </div>

                      {/* Legend */}
                      <div className="flex flex-wrap gap-3">
                        {slopeDistribution.map((item) => (
                          <div key={item.cls} className="flex items-center gap-1.5">
                            <div
                              className="w-3 h-3 rounded-sm"
                              style={{ backgroundColor: SLOPE_CLASS_COLORS[item.cls]?.fill }}
                            />
                            <span className="text-xs text-zinc-400">
                              {SLOPE_CLASS_COLORS[item.cls]?.label} ({item.pct.toFixed(1)}%)
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>

              {/* ── Area by Class Table ── */}
              <Card className="border-zinc-700 bg-zinc-800/50">
                <CardHeader>
                  <CardTitle className="text-zinc-100 text-sm">Area by Class</CardTitle>
                </CardHeader>
                <CardContent className="max-h-72 overflow-y-auto">
                  <Table>
                    <TableHeader>
                      <TableRow className="border-zinc-700 hover:bg-transparent">
                        <TableHead className="text-zinc-400 text-xs">Class</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Range</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Points</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Area (m²)</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Percentage</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {slopeDistribution?.map((item) => (
                        <TableRow key={item.cls} className="border-zinc-700/50">
                          <TableCell>
                            <div className="flex items-center gap-2">
                              <div
                                className="w-2.5 h-2.5 rounded-sm"
                                style={{ backgroundColor: SLOPE_CLASS_COLORS[item.cls]?.fill }}
                              />
                              <span className="font-mono text-sm text-zinc-200">
                                {SLOPE_CLASS_COLORS[item.cls]?.label}
                              </span>
                            </div>
                          </TableCell>
                          <TableCell className="font-mono text-xs text-zinc-400">
                            {SLOPE_CLASS_COLORS[item.cls]?.range}
                          </TableCell>
                          <TableCell className="font-mono text-xs text-zinc-300 text-right">
                            {item.count}
                          </TableCell>
                          <TableCell className="font-mono text-xs text-zinc-300 text-right">
                            {fmt(item.area)}
                          </TableCell>
                          <TableCell className="font-mono text-xs text-blue-400 text-right">
                            {item.pct.toFixed(2)}%
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </CardContent>
              </Card>

              {/* ── Slope Heatmap Visualization ── */}
              <Card className="border-zinc-700 bg-zinc-800/50">
                <CardHeader>
                  <CardTitle className="text-zinc-100 text-sm">Slope Classification Map</CardTitle>
                  <CardDescription className="text-zinc-500 text-xs">
                    Color-coded grid cells per slope class — North is up
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  {slopeHeatmapSVG || (
                    <div className="flex items-center justify-center h-48 text-zinc-500 text-sm">
                      Insufficient data for heatmap visualization
                    </div>
                  )}
                </CardContent>
              </Card>
            </>
          )}

          {!slopeResult && !analyzing && (
            <div className="flex flex-col items-center justify-center py-16 text-zinc-500">
              <svg viewBox="0 0 48 48" className="w-12 h-12 mb-3 opacity-40" fill="none" stroke="currentColor" strokeWidth="1.5">
                <path d="M6 36L18 12l12 18 12-6" strokeLinecap="round" strokeLinejoin="round" />
                <circle cx="18" cy="12" r="2" fill="currentColor" />
                <circle cx="30" cy="30" r="2" fill="currentColor" />
              </svg>
              <p className="text-sm">Load DTM points and run analysis to view results</p>
            </div>
          )}
        </TabsContent>

        {/* ══════════════════════════════════════════════════════════════════ */}
        {/*  TAB 2: CUT / FILL                                              */}
        {/* ══════════════════════════════════════════════════════════════════ */}
        <TabsContent value="cutfill" className="space-y-6">
          <Card className="border-zinc-700 bg-zinc-800/50">
            <CardHeader>
              <CardTitle className="text-zinc-100 text-base">Datum Settings</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-end">
                <div className="space-y-1.5">
                  <Label className="text-zinc-400 text-xs">Datum RL (m)</Label>
                  <Input
                    value={cutFillDatum}
                    onChange={(e) => setCutFillDatum(e.target.value)}
                    type="number"
                    step="0.01"
                    placeholder="e.g. 1500.00"
                    className="font-mono text-sm bg-zinc-900 border-zinc-600 text-zinc-300 w-40"
                  />
                </div>
                <Button
                  onClick={handleCutFill}
                  disabled={filteredPoints.length < 3 || cutFillLoading || isNaN(parseFloat(cutFillDatum))}
                  className="bg-blue-600 hover:bg-blue-500 text-white"
                >
                  {cutFillLoading ? (
                    <>
                      <svg className="animate-spin w-4 h-4 mr-1.5" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2">
                        <circle cx="8" cy="8" r="6" strokeOpacity="0.3" />
                        <path d="M14 8a6 6 0 01-6 6" />
                      </svg>
                      Computing...
                    </>
                  ) : (
                    'Run Cut/Fill Analysis'
                  )}
                </Button>
                {cutFillResult && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleExportCutFillCSV}
                    className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400"
                  >
                    Export CSV
                  </Button>
                )}
              </div>
            </CardContent>
          </Card>

          {cutFillResult && (
            <>
              {/* ── Summary Cards ── */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <SummaryCard
                  label="Cut Volume"
                  value={`${fmtShort(cutFillResult.totalCutVolume)} m³`}
                  accent
                />
                <SummaryCard
                  label="Fill Volume"
                  value={`${fmtShort(cutFillResult.totalFillVolume)} m³`}
                  accent
                />
                <SummaryCard
                  label="Net Volume"
                  value={`${fmtShort(cutFillResult.netVolume)} m³`}
                  accent
                  valueColor={cutFillResult.netVolume > 0 ? 'text-green-400' : cutFillResult.netVolume < 0 ? 'text-red-400' : 'text-zinc-200'}
                />
                <SummaryCard
                  label="Balance Point"
                  value={`${fmt(cutFillResult.balancePoint, 3)} m`}
                  accent
                />
              </div>

              {/* ── Area Breakdown ── */}
              <div className="grid grid-cols-2 gap-3">
                <Card className="border-zinc-700 bg-zinc-800/50">
                  <CardContent className="p-4">
                    <p className="text-xs text-zinc-500 mb-1">Cut Area</p>
                    <p className="text-lg font-bold font-mono text-amber-400">
                      {fmt(cutFillResult.cutArea)} m²
                    </p>
                  </CardContent>
                </Card>
                <Card className="border-zinc-700 bg-zinc-800/50">
                  <CardContent className="p-4">
                    <p className="text-xs text-zinc-500 mb-1">Fill Area</p>
                    <p className="text-lg font-bold font-mono text-blue-400">
                      {fmt(cutFillResult.fillArea)} m²
                    </p>
                  </CardContent>
                </Card>
              </div>

              {/* ── Sample Points Table ── */}
              <Card className="border-zinc-700 bg-zinc-800/50">
                <CardHeader>
                  <CardTitle className="text-zinc-100 text-sm">
                    Grid Points ({cutFillResult.points.length} total{cutFillSample.length < cutFillResult.points.length ? `, showing ${cutFillSample.length}` : ''})
                  </CardTitle>
                </CardHeader>
                <CardContent className="max-h-80 overflow-y-auto">
                  <Table>
                    <TableHeader>
                      <TableRow className="border-zinc-700 hover:bg-transparent">
                        <TableHead className="text-zinc-400 text-xs">Easting</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Northing</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Existing RL</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Design RL</TableHead>
                        <TableHead className="text-zinc-400 text-xs text-right">Difference</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Class</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {cutFillSample.map((p, i) => {
                        const cls = p.difference > 0 ? 'Cut' : p.difference < 0 ? 'Fill' : 'On Grade';
                        return (
                          <TableRow key={`${p}-${i}`} className="border-zinc-700/50">
                            <TableCell className="font-mono text-xs text-zinc-300">
                              {p.easting.toFixed(3)}
                            </TableCell>
                            <TableCell className="font-mono text-xs text-zinc-300">
                              {p.northing.toFixed(3)}
                            </TableCell>
                            <TableCell className="font-mono text-xs text-zinc-300 text-right">
                              {p.existingRL.toFixed(3)}
                            </TableCell>
                            <TableCell className="font-mono text-xs text-zinc-300 text-right">
                              {p.designRL.toFixed(3)}
                            </TableCell>
                            <TableCell className={`font-mono text-xs text-right font-semibold ${p.difference > 0 ? 'text-amber-400' : p.difference < 0 ? 'text-blue-400' : 'text-zinc-400'}`}>
                              {p.difference > 0 ? '+' : ''}{p.difference.toFixed(3)}
                            </TableCell>
                            <TableCell>
                              <Badge
                                variant="outline"
                                className={`text-[10px] font-mono ${
                                  cls === 'Cut'
                                    ? 'border-amber-500/40 text-amber-400 bg-amber-500/10'
                                    : cls === 'Fill'
                                    ? 'border-blue-500/40 text-blue-400 bg-blue-500/10'
                                    : 'border-zinc-600 text-zinc-400'
                                }`}
                              >
                                {cls}
                              </Badge>
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </CardContent>
              </Card>
            </>
          )}

          {!cutFillResult && !cutFillLoading && (
            <div className="flex flex-col items-center justify-center py-16 text-zinc-500">
              <svg viewBox="0 0 48 48" className="w-12 h-12 mb-3 opacity-40" fill="none" stroke="currentColor" strokeWidth="1.5">
                <rect x="8" y="12" width="32" height="24" rx="2" />
                <line x1="8" y1="24" x2="40" y2="24" strokeDasharray="4 2" />
                <path d="M8 24l6-6 4 4 4-8 6 10 14-10" strokeLinejoin="round" />
              </svg>
              <p className="text-sm">Enter a datum RL and run analysis to view cut/fill results</p>
            </div>
          )}
        </TabsContent>

        {/* ══════════════════════════════════════════════════════════════════ */}
        {/*  TAB 3: AREA COMPUTATION                                         */}
        {/* ══════════════════════════════════════════════════════════════════ */}
        <TabsContent value="area" className="space-y-6">
          <Card className="border-zinc-700 bg-zinc-800/50">
            <CardHeader>
              <CardTitle className="text-zinc-100 text-base">Polygon Points</CardTitle>
              <CardDescription className="text-zinc-400">
                Paste or import polygon vertices (Easting,Northing) — minimum 3 points
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex gap-3">
                <input
                  type="file"
                  accept=".csv,.txt"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (!file) return;
                    const reader = new FileReader();
                    reader.onload = (ev) => setPolyText(ev.target?.result as string || '');
                    reader.readAsText(file);
                    e.target.value = '';
                  }}
                  className="hidden"
                  id="poly-file"
                />
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => document.getElementById('poly-file')?.click()}
                  className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400"
                >
                  Import Polygon CSV
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleAreaCompute}
                  disabled={!polyText.trim()}
                  className="border-zinc-600 text-zinc-300 hover:bg-zinc-700 hover:text-blue-400"
                >
                  Compute Area
                </Button>
              </div>
              <Textarea
                value={polyText}
                onChange={(e) => setPolyText(e.target.value)}
                placeholder="Easting,Northing&#10;100.0,100.0&#10;200.0,100.0&#10;200.0,200.0&#10;100.0,200.0"
                className="font-mono text-xs bg-zinc-900 border-zinc-600 text-zinc-300 min-h-[120px] max-h-[200px]"
              />
            </CardContent>
          </Card>

          {areaConversions && (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <SummaryCard label="Area" value={`${fmt(areaConversions.sqm, 2)} m²`} accent />
                <SummaryCard label="Area" value={`${fmt(areaConversions.hectares, 4)} ha`} accent />
                <SummaryCard label="Area" value={`${fmt(areaConversions.acres, 4)} acres`} accent />
              </div>

              <Card className="border-zinc-700 bg-zinc-800/50">
                <CardHeader>
                  <CardTitle className="text-zinc-100 text-sm">
                    Polygon Vertices ({polyPoints.length} points)
                  </CardTitle>
                </CardHeader>
                <CardContent className="max-h-60 overflow-y-auto">
                  <Table>
                    <TableHeader>
                      <TableRow className="border-zinc-700 hover:bg-transparent">
                        <TableHead className="text-zinc-400 text-xs w-12">#</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Easting</TableHead>
                        <TableHead className="text-zinc-400 text-xs">Northing</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {polyPoints.map((p, i) => (
                        <TableRow key={`${p}-${i}`} className="border-zinc-700/50">
                          <TableCell className="font-mono text-xs text-zinc-500">{i + 1}</TableCell>
                          <TableCell className="font-mono text-xs text-zinc-300">{p.easting.toFixed(4)}</TableCell>
                          <TableCell className="font-mono text-xs text-zinc-300">{p.northing.toFixed(4)}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </CardContent>
              </Card>
            </>
          )}

          {!areaConversions && (
            <div className="flex flex-col items-center justify-center py-16 text-zinc-500">
              <svg viewBox="0 0 48 48" className="w-12 h-12 mb-3 opacity-40" fill="none" stroke="currentColor" strokeWidth="1.5">
                <polygon points="24,6 42,16 38,38 10,38 6,16" />
                <text x="24" y="26" textAnchor="middle" fontSize="10" fill="currentColor" stroke="none">m²</text>
              </svg>
              <p className="text-sm">Enter polygon points and compute area to see results</p>
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

