import { Crosshair } from 'lucide-react'

'use client';

/**
 * FieldMeasureButton — large one-tap measurement capture button
 *
 * Designed for field use:
 *   - Large touch target (min 120×120px) — works with gloves
 *   - High contrast — visible in sunlight
 *   - Haptic feedback on press (vibration)
 *   - Audio cue on successful capture
 *   - Shows point ID being measured
 *   - Disabled state when no instrument connected
 *
 * After capture:
 *   - Flashes green
 *   - Auto-increments point ID (P1 → P2 → P3…)
 *   - Shows last measurement summary for 2 seconds
 */

import { useState, useCallback, useRef } from 'react'
import { Crosshair, CheckCircle, AlertTriangle, Loader2 } from 'lucide-react'
import { useInstrumentStore } from '@/stores/instrumentStore'

interface FieldMeasureButtonProps {
  onCapture: (pointId: string) => Promise<boolean>
  disabled?: boolean
  pointIdPrefix?: string  // e.g., 'P', 'BP', 'STN'
  stationSetup?: boolean  // is station set up?
}

export function FieldMeasureButton({
  onCapture,
  disabled = false,
  pointIdPrefix = 'P',
  stationSetup = false,
}: FieldMeasureButtonProps) {
  const [pointNumber, setPointNumber] = useState(1)
  const [isCapturing, setIsCapturing] = useState(false)
  const [lastResult, setLastResult] = useState<'success' | 'error' | null>(null)
  const [lastPointId, setLastPointId] = useState<string | null>(null)
  const flashTimer = useRef<any>(null)

  const { status, latestPoint } = useInstrumentStore()
  const isConnected = status === 'connected' || status === 'streaming'
  const isDisabled = disabled || !isConnected || !stationSetup || isCapturing

  const pointId = `${pointIdPrefix}${pointNumber}`

  const handleMeasure = useCallback(async () => {
    if (isDisabled) return

    // Haptic feedback
    if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
      navigator.vibrate(30)
    }

    setIsCapturing(true)
    setLastResult(null)

    try {
      const success = await onCapture(pointId)
      if (success) {
        setLastResult('success')
        setLastPointId(pointId)
        setPointNumber(n => n + 1)

        // Audio cue: short high beep
        try {
          const ctx = new (window.AudioContext || (window as any).webkitAudioContext)()
          const osc = ctx.createOscillator()
          const gain = ctx.createGain()
          osc.connect(gain)
          gain.connect(ctx.destination)
          osc.frequency.value = 880  // A5
          gain.gain.setValueAtTime(0.15, ctx.currentTime)
          gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15)
          osc.start()
          osc.stop(ctx.currentTime + 0.15)
        } catch {}

        // Clear flash after 2s
        if (flashTimer.current) clearTimeout(flashTimer.current)
        flashTimer.current = setTimeout(() => setLastResult(null), 2000)
      } else {
        setLastResult('error')
        // Error buzz: low tone
        if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
          navigator.vibrate([100, 50, 100])
        }
        if (flashTimer.current) clearTimeout(flashTimer.current)
        flashTimer.current = setTimeout(() => setLastResult(null), 3000)
      }
    } catch (err) {
      setLastResult('error')
      console.error('[field-measure] Capture failed:', err)
    } finally {
      setIsCapturing(false)
    }
  }, [isDisabled, onCapture, pointId])

  // Button styles based on state
  const baseClass = 'relative w-32 h-32 rounded-full flex flex-col items-center justify-center gap-1 transition-all duration-150 select-none font-bold'

  let buttonClass = baseClass
  let icon = <Crosshair className="w-8 h-8" />
  let label = 'MEASURE'

  if (isCapturing) {
    buttonClass += ' bg-[var(--accent)]/30 border-4 border-[var(--accent)] text-[var(--accent)]'
    icon = <Loader2 className="w-8 h-8 animate-spin" />
    label = 'CAPTURING…'
  } else if (lastResult === 'success') {
    buttonClass += ' bg-[var(--success)]/30 border-4 border-[var(--success)] text-[var(--success)] scale-105'
    icon = <CheckCircle className="w-8 h-8" />
    label = 'CAPTURED'
  } else if (lastResult === 'error') {
    buttonClass += ' bg-[var(--error)]/30 border-4 border-[var(--error)] text-[var(--error)]'
    icon = <AlertTriangle className="w-8 h-8" />
    label = 'FAILED'
  } else if (isDisabled) {
    buttonClass += ' bg-[var(--bg-tertiary)] border-4 border-[var(--border-color)] text-[var(--text-muted)] opacity-50 cursor-not-allowed'
    if (!isConnected) label = 'NO INSTRUMENT'
    else if (!stationSetup) label = 'SETUP FIRST'
  } else {
    buttonClass += ' bg-[var(--accent)]/15 border-4 border-[var(--accent)] text-[var(--accent)] hover:bg-[var(--accent)]/25 active:scale-95 cursor-pointer'
  }

  return (
    <div className="flex flex-col items-center gap-2">
      <button
        onClick={handleMeasure}
        disabled={isDisabled}
        className={buttonClass}
        aria-label={`Measure point ${pointId}`}
      >
        {icon}
        <span className="text-sm tracking-wider">{label}</span>
      </button>

      {/* Point ID display */}
      <div className="text-center">
        <div className="text-xs text-[var(--text-muted)] uppercase tracking-wider">Next Point</div>
        <div className="text-lg font-mono font-bold text-[var(--text-primary)]">{pointId}</div>
      </div>

      {/* Last measurement summary */}
      {lastResult === 'success' && lastPointId && latestPoint && (
        <div className="text-center text-xs text-[var(--success)] animate-fade-in">
          ✓ {lastPointId}: {
            latestPoint.source === 'nmea'
              ? `${latestPoint.latitude?.toFixed(6)}, ${latestPoint.longitude?.toFixed(6)}`
              : `${latestPoint.easting?.toFixed(3)}, ${latestPoint.northing?.toFixed(3)}`
          }
        </div>
      )}

      {/* Quick point ID controls */}
      <div className="flex items-center gap-2 mt-1">
        <button
          onClick={() => setPointNumber(n => Math.max(1, n - 1))}
          className="px-2 py-0.5 text-xs rounded bg-[var(--bg-tertiary)] hover:bg-[var(--bg-secondary)] text-[var(--text-secondary)]"
        >
          −
        </button>
        <input
          type="text"
          value={pointId}
          onChange={(e) => {
            const match = e.target.value.match(/(\D+)(\d+)/)
            if (match) {
              setPointNumber(parseInt(match[2]) || 1)
            }
          }}
          className="w-20 text-center text-xs font-mono bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded px-1 py-0.5 text-[var(--text-primary)]"
        />
        <button
          onClick={() => setPointNumber(n => n + 1)}
          className="px-2 py-0.5 text-xs rounded bg-[var(--bg-tertiary)] hover:bg-[var(--bg-secondary)] text-[var(--text-secondary)]"
        >
          +
        </button>
      </div>
    </div>
  )
}

'use client';
import { useState } from 'react';
import { renderPDFPageToDataURL } from '@/lib/field/geopdf';
import { GeoPDFLayer, GCP } from '@/types/field';
import { Upload, MapPin, CheckCircle, AlertCircle } from 'lucide-react';

interface Props {
  onLayerReady: (layer: GeoPDFLayer) => void;
}

const GCP_LABELS = ['TL', 'TR', 'BL', 'BR'] as const;
const GCP_NAMES = {
  TL: 'Top-Left corner',
  TR: 'Top-Right corner',
  BL: 'Bottom-Left corner',
  BR: 'Bottom-Right corner',
};

export default function GeoPDFImport({ onLayerReady }: Props) {
  const [step, setStep] = useState<'idle' | 'rendering' | 'gcp' | 'done'>('idle');
  const [rendered, setRendered] = useState<{ dataUrl: string; w: number; h: number } | null>(null);
  const [gcps, setGCPs] = useState<Partial<GCP>[]>(
    GCP_LABELS.map(label => ({ id: label, label, pixelX: 0, pixelY: 0, lat: undefined, lng: undefined }))
  );
  const [fileName, setFileName] = useState('');
  const [error, setError] = useState<string | null>(null);

  async function handleFileSelect(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file || !file.name.toLowerCase().endsWith('.pdf')) {
      setError('Please select a PDF file.');
      return;
    }
    setFileName(file.name);
    setError(null);
    setStep('rendering');
    try {
      const result = await renderPDFPageToDataURL(file, 1, 2.0);
      // Default pixel positions: corners at 5% inset from edges
      const insetX = Math.round(result.widthPx * 0.05);
      const insetY = Math.round(result.heightPx * 0.05);
      setGCPs([
        { id: 'TL', label: 'TL', pixelX: insetX,                   pixelY: insetY },
        { id: 'TR', label: 'TR', pixelX: result.widthPx - insetX,   pixelY: insetY },
        { id: 'BL', label: 'BL', pixelX: insetX,                   pixelY: result.heightPx - insetY },
        { id: 'BR', label: 'BR', pixelX: result.widthPx - insetX,   pixelY: result.heightPx - insetY },
      ]);
      setRendered({ dataUrl: result.dataUrl, w: result.widthPx, h: result.heightPx });
      setStep('gcp');
    } catch (err) {
      setError(`Failed to render PDF: ${(err as Error).message}`);
      setStep('idle');
    }
  }

  function updateGCP(label: string, field: 'lat' | 'lng', value: string) {
    setGCPs(prev => prev.map(g =>
      g.label === label ? { ...g, [field]: parseFloat(value) || 0 } : g
    ));
  }

  function handleSubmit() {
    if (!rendered) return;
    const complete = gcps.filter(g => g.lat !== undefined && g.lng !== undefined && g.lat !== 0);
    if (complete.length < 4) {
      setError('Enter latitude and longitude for all 4 corners.');
      return;
    }
    const layer: GeoPDFLayer = {
      id: `geopdf_${Date.now()}`,
      name: fileName,
      dataUrl: rendered.dataUrl,
      widthPx: rendered.w,
      heightPx: rendered.h,
      gcps: gcps as GCP[],
      visible: true,
      loadedAt: Date.now(),
    };
    onLayerReady(layer);
    setStep('done');
  }

  if (step === 'idle' || step === 'rendering') return (
    <div className="p-4 space-y-3 text-white">
      <label className="flex items-center gap-2 bg-purple-700 hover:bg-purple-600 text-white px-4 py-2 rounded-lg cursor-pointer w-fit">
        <Upload className="w-4 h-4" />
        {step === 'rendering' ? 'Rendering PDF…' : 'Import GeoPDF'}
        <input type="file" accept=".pdf" className="hidden" onChange={handleFileSelect} disabled={step === 'rendering'} />
      </label>
      {error && <p className="text-red-400 text-sm flex items-center gap-1"><AlertCircle className="w-4 h-4" />{error}</p>}
      <p className="text-gray-500 text-xs">You will enter the WGS84 coordinates of the 4 map corners after import.</p>
    </div>
  );

  if (step === 'done') return (
    <div className="p-4 flex items-center gap-2 text-green-400">
      <CheckCircle className="w-5 h-5" />
      <span className="text-sm">GeoPDF layer added to map.</span>
    </div>
  );

  // GCP registration step
  return (
    <div className="p-4 space-y-4 overflow-y-auto max-h-[80vh] text-white">
      <h3 className="font-semibold text-sm">Enter map corner coordinates — <span className="text-gray-400 font-normal">WGS84 decimal degrees</span></h3>
      {error && <p className="text-red-400 text-sm">{error}</p>}
      <div className="grid grid-cols-1 gap-3">
        {gcps.map(g => (
          <div key={g.label} className="bg-gray-800 rounded-lg p-3 space-y-2">
            <div className="flex items-center gap-2">
              <MapPin className="w-4 h-4 text-purple-400" />
              <span className="text-sm font-mono font-bold">{g.label}</span>
              <span className="text-xs text-gray-400">{GCP_NAMES[g.label as keyof typeof GCP_NAMES]}</span>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <input
                type="number" step="0.000001" aria-label="Latitude" placeholder="e.g. -1.2921"
                className="bg-gray-700 text-sm px-2 py-1.5 rounded border border-gray-600 text-white"
                onChange={e => updateGCP(g.label!, 'lat', e.target.value)}
              />
              <input
                type="number" step="0.000001" aria-label="Longitude" placeholder="e.g. 36.8219"
                className="bg-gray-700 text-sm px-2 py-1.5 rounded border border-gray-600 text-white"
                onChange={e => updateGCP(g.label!, 'lng', e.target.value)}
              />
            </div>
          </div>
        ))}
      </div>
      <button onClick={handleSubmit}
        className="w-full bg-purple-600 hover:bg-purple-500 text-white font-semibold py-2 rounded-lg text-sm">
        Add to Map
      </button>
    </div>
  );
}

'use client';
import { useEffect, useRef, forwardRef, useImperativeHandle, useCallback } from 'react';
import { MapLayer, FieldBeacon, FieldParcel, GeoPDFLayer, MBTilesSession } from '@/types/field';



export interface MapHandle {
  zoomIn: () => void;
  zoomOut: () => void;
  resetToKenya: () => void;
  fitToData: () => void;
  getView: () => { center: number[]; zoom: number } | null;
}

interface Props {
  layers: MapLayer[];
  beacons: FieldBeacon[];
  parcels: FieldParcel[];
  geoPDFLayers?: GeoPDFLayer[];
  mbtilesSessions?: MBTilesSession[];
  onMapClick?: (lat: number, lng: number) => void;
  onGPSUpdate?: (lat: number, lng: number, accuracy: number) => void;
  onPerimeterWalk?: () => void;
  gpsLocation?: { lat: number; lng: number } | null;
  gpsAccuracy?: number | null;
}

const MapViewer = forwardRef<MapHandle, Props>(function MapViewer(
  { layers, beacons, parcels, geoPDFLayers, mbtilesSessions, onMapClick, onGPSUpdate, onPerimeterWalk, gpsLocation, gpsAccuracy },
  ref
) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const kenyaCenterRef = useRef<number[]>([0, 0]);
  const gpsFeatureRef = useRef<any>(null);
  const olHelpersRef = useRef<any>(null);


  /* ---- Expose imperative handle to parent ---- */
  useImperativeHandle(ref, () => ({
    zoomIn() {
      const map = mapRef.current;
      if (!map) return;
      const view = map.getView();
      view.animate({ zoom: view.getZoom()! + 1, duration: 250 });
    },
    zoomOut() {
      const map = mapRef.current;
      if (!map) return;
      const view = map.getView();
      view.animate({ zoom: view.getZoom()! - 1, duration: 250 });
    },
    resetToKenya() {
      const map = mapRef.current;
      if (!map) return;
      const view = map.getView();
      view.animate({ center: kenyaCenterRef.current, zoom: 6, duration: 400 });
    },
    fitToData() {
      const map = mapRef.current;
      if (!map) return;
      const layers = map.getLayers().getArray();
      // Try beacon / parcel layers first, then geojson
      for (let i = layers.length - 1; i >= 0; i--) {
        const l = layers[i] as any;
        const src = l?.getSource?.();
        if (src && src.getFeatures && src.getFeatures().length > 0) {
          const ext = src.getExtent();
          if (ext && ext[0] !== Infinity && ext[1] !== Infinity) {
            map.getView().fit(ext, { padding: [80, 80, 80, 80], maxZoom: 17, duration: 400 });
            return;
          }
        }
      }
    },
    getView() {
      const map = mapRef.current;
      if (!map) return null;
      const v = map.getView();
      return { center: v.getCenter() ?? [], zoom: v.getZoom() ?? 6 };
    },
  }), []);

  /* ---- Stable callback refs so OL event handlers stay valid ---- */
  const onMapClickRef = useRef(onMapClick);
  onMapClickRef.current = onMapClick;

  useEffect(() => {
    if (!containerRef.current) return;
    let mounted = true;

    async function initMap() {
      try {
        // Inject OpenLayers CSS via link tag (dynamic import of CSS crashes in Next.js)
        if (!document.querySelector('link[href*="ol/ol.css"]')) {
          try {
            await import('ol/ol.css' as any);
          } catch {
            const link = document.createElement('link');
            link.rel = 'stylesheet';
            link.href = 'https://cdn.jsdelivr.net/npm/ol@10.8.0/ol.css';
            document.head.appendChild(link);
          }
        }

        // Import OpenLayers modules individually
        const { default: Map } = await import('ol/Map');
        const { default: View } = await import('ol/View');
        const { default: TileLayer } = await import('ol/layer/Tile');
        const { default: VectorLayer } = await import('ol/layer/Vector');
        const { default: OSM } = await import('ol/source/OSM');
        const { default: VectorSource } = await import('ol/source/Vector');
        const { default: GeoJSONFormat } = await import('ol/format/GeoJSON');
        const { default: Feature } = await import('ol/Feature');
        const { default: Point } = await import('ol/geom/Point');
        const { default: Polygon } = await import('ol/geom/Polygon');
        const { default: Style } = await import('ol/style/Style');
        const { default: CircleStyle } = await import('ol/style/Circle');
        const { default: Fill } = await import('ol/style/Fill');
        const { default: Stroke } = await import('ol/style/Stroke');
        const { default: TextStyle } = await import('ol/style/Text');
        const { fromLonLat, toLonLat } = await import('ol/proj');
        const { default: Attribution } = await import('ol/control/Attribution');
        const olControl = await import('ol/control');
        const defaultControls = olControl.defaults;

        olHelpersRef.current = { Point, fromLonLat };

        if (!mounted || !containerRef.current) return;

        // Cleanup previous map
        if (mapRef.current) {
          mapRef.current.setTarget(undefined);
          mapRef.current = null;
        }

        // Default center at Kenya
        const kenyaCenter = fromLonLat([37.91, 0.02]);
        kenyaCenterRef.current = kenyaCenter;

        // Base OSM tile layer
        const baseLayer = new TileLayer({ source: new OSM() });

        // GeoJSON vector layers (from imported KML/KMZ)
        const vectorLayers = layers
          .filter(l => l.visible && l.geojson)
          .map(l => {
            const features = new GeoJSONFormat().readFeatures(l.geojson, {
              dataProjection: 'EPSG:4326',
              featureProjection: 'EPSG:3857',
            });
            return new VectorLayer({
              source: new VectorSource({ features }),
              style: new Style({
                stroke: new Stroke({ color: '#3b82f6', width: 2 }),
                fill: new Fill({ color: 'rgba(59,130,246,0.1)' }),
              }),
            });
          });

        // Beacon point layer
        const beaconFeatures = beacons.map(b => {
          const f = new Feature({
            geometry: new Point(fromLonLat([b.coordinate.lng, b.coordinate.lat])),
          });
          f.set('label', b.label);
          return f;
        });

        const beaconLayer = new VectorLayer({
          source: new VectorSource({ features: beaconFeatures }),
          style: (feature: any) => new Style({
            image: new CircleStyle({
              radius: 8,
              fill: new Fill({ color: '#f59e0b' }),
              stroke: new Stroke({ color: '#ffffff', width: 2 }),
            }),
            text: new TextStyle({
              text: feature.get('label') || '',
              offsetY: -16,
              fill: new Fill({ color: '#f59e0b' }),
              stroke: new Stroke({ color: '#000', width: 3 }),
              font: 'bold 12px monospace',
            }),
          }),
        });

        // Parcel polygon layer
        const parcelFeatures = parcels
          .filter(p => p.walkPoints.length >= 3)
          .map(p => {
            const coords = p.walkPoints.map(wp =>
              fromLonLat([wp.coordinate.lng, wp.coordinate.lat])
            );
            coords.push(coords[0]);
            const f = new Feature({ geometry: new Polygon([coords]) });
            f.set('label', p.label);
            return f;
          });

        const parcelLayer = new VectorLayer({
          source: new VectorSource({ features: parcelFeatures }),
          style: new Style({
            stroke: new Stroke({ color: '#10b981', width: 2 }),
            fill: new Fill({ color: 'rgba(16,185,129,0.08)' }),
          }),
        });

        // GPS Layer
        const gpsFeature = new Feature();
        gpsFeatureRef.current = gpsFeature;
        
        const gpsLayer = new VectorLayer({
          source: new VectorSource({ features: [gpsFeature] }),
          style: (feature: any) => {
            const acc = feature.get('accuracy') || 10;
            let color = 'rgba(239,68,68,0.4)'; // Red (Single) > 3m
            let strokeColor = '#ef4444';
            
            if (acc <= 0.05) {
              color = 'rgba(16,185,129,0.4)'; // Green (Fixed)
              strokeColor = '#10b981';
            } else if (acc <= 3) {
              color = 'rgba(234,179,8,0.4)'; // Yellow (Float)
              strokeColor = '#eab308';
            }
            
            // Map accuracy in meters to roughly pixels for the circle
            // OL CircleStyle radius is in pixels. For a true physical cone, we'd use a Polygon.
            // But a dynamic styled circle based on zoom is acceptable here.
            const mapObj = mapRef.current;
            let radiusPx = 10;
            if (mapObj) {
              const res = mapObj.getView().getResolution() || 1;
              radiusPx = Math.max(5, acc / res);
            }

            return new Style({
              image: new CircleStyle({
                radius: radiusPx,
                fill: new Fill({ color }),
                stroke: new Stroke({ color: strokeColor, width: 2 }),
              })
            });
          }
        });

        const map = new Map({
          target: containerRef.current,
          layers: [baseLayer, ...vectorLayers, parcelLayer, beaconLayer, gpsLayer],
          view: new View({
            center: kenyaCenter,
            zoom: 6,
            minZoom: 6,
            maxZoom: 20,
            extent: [-2.2e7, -1.2e7, 2.2e7, 1.5e7],
          }),
          controls: defaultControls({ attribution: false }),
        });

        // Fit to data extent (if we have beacons or parcels)
        if (beaconFeatures.length > 0) {
          const src = beaconLayer.getSource();
          if (src) {
            const ext = src.getExtent();
            if (ext && ext[0] !== Infinity) {
              map.getView().fit(ext, { padding: [80, 80, 80, 80], maxZoom: 17 });
            }
          }
        } else if (parcelFeatures.length > 0) {
          const src = parcelLayer.getSource();
          if (src) {
            const ext = src.getExtent();
            if (ext && ext[0] !== Infinity) {
              map.getView().fit(ext, { padding: [80, 80, 80, 80], maxZoom: 17 });
            }
          }
        }

        // Map click handler — uses ref for stable callback
        map.on('click', (e: any) => {
          const cb = onMapClickRef.current;
          if (cb) {
            const [lng, lat] = toLonLat(e.coordinate);
            cb(lat, lng);
          }
        });

        // GeoPDF layers
        if (geoPDFLayers?.length) {
          const { buildOLGeoPDFLayer } = await import('@/lib/field/geopdf');
          geoPDFLayers.filter(g => g.visible && g.gcps.length === 4).forEach(g => {
            map.addLayer(buildOLGeoPDFLayer(g));
          });
        }

        // MBTiles layers
        if (mbtilesSessions?.length) {
          const { buildOLMBTilesLayer } = await import('@/lib/field/mbtiles');
          mbtilesSessions.forEach(s => {
            map.addLayer(buildOLMBTilesLayer(s));
          });
        }

        mapRef.current = map;
      } catch (err) {
        console.error('[MapViewer] Init error:', err);
      }
    }

    initMap();

    return () => {
      mounted = false;
      if (mapRef.current) {
        mapRef.current.setTarget(undefined);
        mapRef.current = null;
      }
    };
  }, [layers, beacons, parcels, geoPDFLayers, mbtilesSessions]);

  useEffect(() => {
    // Dynamic GPS update without re-initializing the whole map
    if (gpsFeatureRef.current && olHelpersRef.current) {
      const feature = gpsFeatureRef.current;
      const { Point, fromLonLat } = olHelpersRef.current;

      if (gpsLocation) {
        feature.setGeometry(new Point(fromLonLat([gpsLocation.lng, gpsLocation.lat])));
        feature.set('accuracy', gpsAccuracy || 10);
      } else {
        feature.setGeometry(undefined);
      }
    }
  }, [gpsLocation, gpsAccuracy]);

  return (
    <div
      ref={containerRef}
      style={{ width: '100%', height: '100%' }}
      className="absolute inset-0"
    />
  );
});

MapViewer.displayName = 'MapViewer';
export default MapViewer;

'use client';

/**
 * ProjectPicker — project selection screen for field tools
 *
 * Shows a list of the user's projects and lets them pick one
 * to start a field session. Also lets them pick the survey type.
 */

import { useState, useEffect } from 'react'
import { FolderKanban, ChevronRight, Loader2, MapPin } from 'lucide-react'
import { createClient } from '@/lib/api-client/client'

interface Project {
  id: string
  name: string
  survey_type?: string
  county?: string
  created_at?: string
}

interface ProjectPickerProps {
  onPick: (projectId: string, surveyType?: string) => void
  title: string
  subtitle: string
}

export function ProjectPicker({ onPick, title, subtitle }: ProjectPickerProps) {
  const [projects, setProjects] = useState<Project[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    async function loadProjects() {
      try {
        const db = createClient()
        const { data, error } = await db
          .from('projects')
          .select('id, name, survey_type, county, created_at')
          .order('created_at', { ascending: false })
          .limit(50)

        if (error) throw error
        setProjects(data || [])
      } catch (err) {
        console.error('[project-picker] Failed to load projects:', err)
        setError('Failed to load projects. Check your connection.')
      } finally {
        setLoading(false)
      }
    }

    loadProjects()
  }, [])

  return (
    <div className="min-h-screen bg-[var(--bg-primary)] flex flex-col">
      {/* Header */}
      <div className="px-4 py-6 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2 mb-1">
          <MapPin className="w-5 h-5 text-[var(--accent)]" />
          <h1 className="text-xl font-bold text-[var(--text-primary)]">{title}</h1>
        </div>
        <p className="text-sm text-[var(--text-muted)]">{subtitle}</p>
      </div>

      {/* Project List */}
      <div className="flex-1 overflow-y-auto p-4">
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin text-[var(--accent)]" />
          </div>
        ) : error ? (
          <div className="text-center py-12">
            <p className="text-sm text-[var(--error)]">{error}</p>
          </div>
        ) : projects.length === 0 ? (
          <div className="text-center py-12">
            <FolderKanban className="w-12 h-12 text-[var(--text-muted)] mx-auto mb-3" />
            <p className="text-sm text-[var(--text-muted)]">No projects yet</p>
            <p className="text-xs text-[var(--text-muted)] mt-1">
              Create a project from the dashboard first
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {projects.map((project) => (
              <button
                key={project.id}
                onClick={() => onPick(project.id, project.survey_type)}
                className="w-full flex items-center gap-3 p-4 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg hover:border-[var(--accent)]/30 hover:bg-[var(--bg-secondary)] transition-all text-left"
              >
                <FolderKanban className="w-5 h-5 text-[var(--accent)] shrink-0" />
                <div className="flex-1 min-w-0">
                  <div className="font-medium text-[var(--text-primary)] truncate">
                    {project.name}
                  </div>
                  <div className="text-xs text-[var(--text-muted)] flex items-center gap-2 mt-0.5">
                    {project.survey_type && (
                      <span className="capitalize">{project.survey_type}</span>
                    )}
                    {project.county && <span>· {project.county}</span>}
                    {project.created_at && (
                      <span>· {new Date(project.created_at).toLocaleDateString('en-KE')}</span>
                    )}
                  </div>
                </div>
                <ChevronRight className="w-4 h-4 text-[var(--text-muted)] shrink-0" />
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

'use client';

/**
 * BeaconPhotoCapture
 * ────────────────────────────────────────────────────────────────────────────
 * Photo capture widget for field observations. Records a beacon / site
 * photo and extracts EXIF GPS data immediately so the surveyor can:
 *   • see the captured location on a map chip
 *   • embed the GPS coords into the row's remarks / metadata
 *   • keep an immutable evidence chain for cadastral / legal work
 *
 * Uses the existing /lib/engineering/exifPhoto.ts parser (zero deps).
 */

import { useState, useRef, useCallback } from 'react'
import { Camera, X, MapPin, Loader2, CheckCircle2, AlertTriangle, ImageOff } from 'lucide-react'
import { extractEXIFGPS, isEXIFSupported, type EXIFGPSData } from '@/lib/engineering/exifPhoto'
import { useLanguage } from '@/lib/i18n/LanguageContext'

export interface CapturedBeaconPhoto {
  /** object URL for preview — revoke on unmount */
  previewUrl: string
  file: File
  exif: EXIFGPSData | null
  /** True if EXIF parsing ran but found no GPS tag */
  missingGps: boolean
  caption: string
}

interface BeaconPhotoCaptureProps {
  photos: CapturedBeaconPhoto[]
  onChange: (photos: CapturedBeaconPhoto[]) => void
  maxPhotos?: number
}

export function BeaconPhotoCapture({ photos, onChange, maxPhotos = 4 }: BeaconPhotoCaptureProps) {
  const { t } = useLanguage()
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const exifSupported = isEXIFSupported()

  const handleFiles = useCallback(
    async (files: FileList | null) => {
      if (!files || files.length === 0) return
      if (photos.length >= maxPhotos) {
        setError(t('photoCapture.maxPhotosReached', { count: maxPhotos }))
        return
      }
      setError(null)
      setBusy(true)

      const remaining = maxPhotos - photos.length
      const toProcess = Array.from(files).slice(0, remaining)
      const additions: CapturedBeaconPhoto[] = []

      for (const file of toProcess) {
        // Basic type guard — only JPEG / HEIC / PNG
        if (!/^image\/(jpeg|png|heic|heif)$/i.test(file.type) && !/\.(jpe?g|heic|heif|png)$/i.test(file.name)) {
          setError(t('photoCapture.unsupportedFormat', { name: file.name }))
          continue
        }

        try {
          let exif: EXIFGPSData | null = null
          let missingGps = false
          try {
            exif = await extractEXIFGPS(file)
            if (!exif) missingGps = true
          } catch (err) {
            console.warn('EXIF parse failed for', file.name, err)
            missingGps = true
          }

          additions.push({
            previewUrl: URL.createObjectURL(file),
            file,
            exif,
            missingGps,
            caption: '',
          })
        } catch (err) {
          console.error('Photo capture failed:', err)
          setError(t('photoCapture.captureFailed', { name: file.name }))
        }
      }

      if (additions.length > 0) {
        onChange([...photos, ...additions])
      }
      setBusy(false)
      // Reset input so the same file can be re-captured if needed
      if (inputRef.current) inputRef.current.value = ''
    },
    [photos, maxPhotos, onChange, t]
  )

  const removePhoto = (idx: number) => {
    const next = [...photos]
    const [removed] = next.splice(idx, 1)
    if (removed?.previewUrl) URL.revokeObjectURL(removed.previewUrl)
    onChange(next)
  }

  const updateCaption = (idx: number, caption: string) => {
    const next = [...photos]
    next[idx] = { ...next[idx], caption }
    onChange(next)
  }

  const slotsLeft = maxPhotos - photos.length

  return (
    <div className="space-y-2">
      {/* Capture button */}
      {slotsLeft > 0 && (
        <>
          <input
            ref={inputRef}
            type="file"
            accept="image/jpeg,image/png,image/heic,image/heif"
            capture="environment"
            multiple
            className="hidden"
            onChange={(e) => handleFiles(e.target.files)}
          />
          <button
            type="button"
            onClick={() => inputRef.current?.click()}
            disabled={busy}
            className="w-full p-4 border-2 border-dashed border-[var(--border-color)] rounded-xl flex items-center justify-center gap-2 text-[var(--text-secondary)] hover:border-[var(--accent)]/50 hover:text-[var(--accent)] hover:bg-[var(--accent)]/5 transition active:scale-[0.99] disabled:opacity-50"
          >
            {busy ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
                <span className="text-sm font-medium">{t('photoCapture.processing')}</span>
              </>
            ) : (
              <>
                <Camera className="w-5 h-5" />
                <span className="text-sm font-medium">
                  {t('photoCapture.captureButton')}
                </span>
              </>
            )}
          </button>
          {!exifSupported && (
            <p className="text-[10px] text-[var(--text-muted)] flex items-center gap-1">
              <AlertTriangle className="w-3 h-3" />
              {t('photoCapture.exifNotSupported')}
            </p>
          )}
        </>
      )}

      {/* Error */}
      {error && (
        <div className="flex items-center gap-1.5 text-xs text-red-400 px-1">
          <AlertTriangle className="w-3.5 h-3.5" />
          {error}
        </div>
      )}

      {/* Captured photos grid */}
      {photos.length > 0 && (
        <div className="grid grid-cols-2 gap-2">
          {photos.map((photo, idx) => (
            <div
              key={`${photo}-${idx}`}
              className="relative rounded-lg overflow-hidden border border-[var(--border-color)] bg-[var(--bg-secondary)]"
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={photo.previewUrl}
                alt={photo.caption || `Beacon photo ${idx + 1}`}
                className="w-full h-24 object-cover"
              />

              {/* GPS badge */}
              <div className="absolute top-1.5 left-1.5">
                {photo.exif ? (
                  <span className="flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-emerald-500/90 text-white text-[9px] font-mono backdrop-blur-sm">
                    <MapPin className="w-2.5 h-2.5" />
                    {photo.exif.latitude.toFixed(5)}, {photo.exif.longitude.toFixed(5)}
                  </span>
                ) : photo.missingGps ? (
                  <span className="flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-amber-500/90 text-black text-[9px] font-medium backdrop-blur-sm">
                    <AlertTriangle className="w-2.5 h-2.5" />
                    {t('photoCapture.noGPS')}
                  </span>
                ) : null}
              </div>

              {/* Remove button */}
              <button
                type="button"
                onClick={() => removePhoto(idx)}
                className="absolute top-1.5 right-1.5 grid place-items-center w-6 h-6 rounded-md bg-black/70 text-white hover:bg-red-500/80 transition"
                aria-label="Remove photo"
              >
                <X className="w-3.5 h-3.5" />
              </button>

              {/* Caption */}
              <input aria-label="Caption"
                type="text"
                value={photo.caption}
                onChange={(e) => updateCaption(idx, e.target.value)}
                placeholder={t('photoCapture.captionPlaceholder')}
                className="w-full px-2 py-1.5 text-xs bg-transparent text-[var(--text-primary)] placeholder-[var(--text-muted)] border-t border-[var(--border-color)] focus:outline-none"
              />
            </div>
          ))}
        </div>
      )}

      {/* Empty state */}
      {photos.length === 0 && !busy && (
        <div className="flex items-center gap-2 text-[10px] text-[var(--text-muted)] px-1">
          <ImageOff className="w-3 h-3" />
          {t('photoCapture.emptyState', { count: maxPhotos })}
        </div>
      )}

      {/* GPS detail line */}
      {photos.length > 0 && photos.some((p) => p.exif) && (
        <div className="flex items-center gap-1 text-[10px] text-emerald-400 px-1">
          <CheckCircle2 className="w-3 h-3" />
          {t('photoCapture.gpsEvidence', { count: photos.filter((p) => p.exif).length })}
        </div>
      )}
    </div>
  )
}

/**
 * Free object URLs held by captured photos. Call on parent unmount
 * to avoid memory leaks.
 */
export function revokeCapturedPhotos(photos: CapturedBeaconPhoto[]) {
  for (const p of photos) {
    try {
      URL.revokeObjectURL(p.previewUrl)
    } catch {
      /* ignore */
    }
  }
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { Wifi, WifiOff, CloudUpload, CheckCircle, AlertTriangle } from 'lucide-react';
import {
  getObservationsOffline,
  saveObservationOffline,
  syncProject,
  isOnline,
  registerNetworkListeners,
  type OfflineObservation,
} from '@/lib/offline';
import { QuickAddModal } from './QuickAddModal';

interface FieldBookMobileProps {
  projectId: string;
  surveyType: string;
  surveyorId: string;
}

export function FieldBookMobile({ projectId, surveyType, surveyorId }: FieldBookMobileProps) {
  const [online, setOnline] = useState(isOnline());
  const [observations, setObservations] = useState<OfflineObservation[]>([]);
  const [syncing, setSyncing] = useState(false);
  const [syncResult, setSyncResult] = useState<{ synced: number; failed: number } | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [lastSync, setLastSync] = useState<Date | null>(null);

  useEffect(() => {
    loadObservations();
  }, [projectId]);

  useEffect(() => {
    const cleanup = registerNetworkListeners(
      () => setOnline(true),
      () => setOnline(false)
    );
    return cleanup;
  }, []);

  const loadObservations = async () => {
    const obs = await getObservationsOffline(projectId);
    setObservations(obs);
  };

  const handleSync = useCallback(async () => {
    if (!online || syncing) return;
    
    setSyncing(true);
    setSyncResult(null);
    
    try {
      const result = await syncProject(projectId);
      setSyncResult({ synced: result.synced, failed: result.failed });
      setLastSync(new Date());
      await loadObservations();
    } catch (err) {
      console.error('Sync failed:', err);
    } finally {
      setSyncing(false);
    }
  }, [projectId, online, syncing]);

  const handleAddObservation = async (obs: Omit<OfflineObservation, 'id' | 'project_id' | 'timestamp' | 'synced'>) => {
    const newObs: OfflineObservation = {
      ...obs,
      id: crypto.randomUUID(),
      project_id: projectId,
      timestamp: new Date().toISOString(),
      synced: false,
    };
    
    await saveObservationOffline(newObs);
    await loadObservations();
    setShowAddModal(false);
  };

  const unsyncedCount = observations.filter(o => !o.synced).length;

  return (
    <div className="flex flex-col h-screen bg-gray-50">
      <div className="sticky top-0 z-10 flex items-center justify-between px-4 py-3 bg-white border-b shadow-sm">
        <div className="flex items-center gap-2">
          {online ? (
            <>
              <Wifi className="w-5 h-5 text-green-600" />
              <span className="text-sm font-medium text-green-700">Online</span>
            </>
          ) : (
            <>
              <WifiOff className="w-5 h-5 text-gray-400" />
              <span className="text-sm font-medium text-gray-500">Offline</span>
            </>
          )}
        </div>
        
        <div className="flex items-center gap-3">
          {lastSync && (
            <span className="text-xs text-gray-500">
              Last sync: {lastSync.toLocaleTimeString()}
            </span>
          )}
          
          <button
            onClick={handleSync}
            disabled={!online || syncing || unsyncedCount === 0}
            className={[
              'flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-sm transition-colors',
              online && !syncing && unsyncedCount > 0
                ? 'bg-blue-600 text-white hover:bg-blue-700'
                : 'bg-gray-200 text-gray-400 cursor-not-allowed',
            ].join(' ')}
          >
            {syncing ? (
              <>
                <CloudUpload className="w-4 h-4 animate-pulse" />
                Syncing...
              </>
            ) : (
              <>
                <CloudUpload className="w-4 h-4" />
                Sync ({unsyncedCount})
              </>
            )}
          </button>
        </div>
      </div>

      {syncResult && (
        <div className={[
          'flex items-center gap-2 px-4 py-2 text-sm',
          syncResult.failed === 0 ? 'bg-green-50 text-green-700' : 'bg-yellow-50 text-yellow-700',
        ].join(' ')}>
          {syncResult.failed === 0 ? (
            <>
              <CheckCircle className="w-4 h-4" />
              Synced {syncResult.synced} observations
            </>
          ) : (
            <>
              <AlertTriangle className="w-4 h-4" />
              Synced {syncResult.synced}, failed {syncResult.failed}
            </>
          )}
        </div>
      )}

      <div className="flex-1 overflow-auto p-4">
        {observations.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-gray-500">
            <p className="text-lg font-medium">No observations yet</p>
            <p className="text-sm">Tap the + button to add your first observation</p>
          </div>
        ) : (
          <div className="space-y-2">
            {observations.map((obs, idx) => (
              <ObservationCard 
                key={obs.id} 
                observation={obs} 
                index={observations.length - idx}
              />
            ))}
          </div>
        )}
      </div>

      <div className="sticky bottom-0 p-4 bg-white border-t">
        <button
          onClick={() => setShowAddModal(true)}
          className="w-full py-4 bg-blue-600 text-white rounded-lg font-semibold text-lg flex items-center justify-center gap-2 active:bg-blue-700"
        >
          <span className="text-2xl">+</span>
          Add Observation
        </button>
      </div>

      {showAddModal && (
        <QuickAddModal
          onAdd={handleAddObservation}
          onClose={() => setShowAddModal(false)}
        />
      )}
    </div>
  );
}

function ObservationCard({ observation, index }: { observation: OfflineObservation; index: number }) {
  return (
    <div className="bg-white rounded-lg p-4 shadow-sm border">
      <div className="flex items-center justify-between mb-2">
        <span className="font-mono font-bold text-lg">
          {observation.station_from} → {observation.station_to}
        </span>
        <span className="text-xs text-gray-500">#{index}</span>
      </div>
      
      <div className="grid grid-cols-3 gap-2 text-sm">
        <div>
          <span className="text-gray-500">HA</span>
          <span className="font-mono ml-1">{observation.horizontal_angle.toFixed(4)}°</span>
        </div>
        <div>
          <span className="text-gray-500">VA</span>
          <span className="font-mono ml-1">{observation.vertical_angle.toFixed(4)}°</span>
        </div>
        <div>
          <span className="text-gray-500">Dist</span>
          <span className="font-mono ml-1">{observation.slope_distance.toFixed(3)}m</span>
        </div>
      </div>
      
      <div className="flex items-center justify-between mt-2 text-xs">
        <span className="text-gray-400">
          {new Date(observation.timestamp).toLocaleTimeString()}
        </span>
        {observation.synced ? (
          <span className="text-green-600 flex items-center gap-1">
            <CheckCircle className="w-3 h-3" />
            Synced
          </span>
        ) : (
          <span className="text-yellow-600">Pending sync</span>
        )}
      </div>
      
      {observation.remarks && (
        <p className="mt-2 text-sm text-gray-600 italic">{observation.remarks}</p>
      )}
    </div>
  );
}

'use client';

/**
 * FieldbookAuditDrawer
 * ────────────────────────────────────────────────────────────────────────────
 * Bottom-sheet drawer that shows the fieldbook audit event stream
 * for the current user. Each row shows:
 *   • action chip (INSERT / UPDATE / SOFT_DELETE / RESTORE / DELETE)
 *   • table name + row id
 *   • who (email) + when (relative time)
 *   • SHA-256 hash (truncated) with copy button
 *   • expandable payload preview (JSON)
 *
 * Pulls from /api/fieldbook/audit.
 */

import { useEffect, useState, useCallback } from 'react'
import { X, ShieldCheck, ShieldAlert, Copy, Check, ChevronDown, ChevronRight, Hash, User, Clock } from 'lucide-react'
import { useLanguage } from '@/lib/i18n/LanguageContext'

interface AuditEvent {
  id: string
  table_name: string
  row_id: string
  user_id: string | null
  user_email: string | null
  action: 'INSERT' | 'UPDATE' | 'DELETE' | 'SOFT_DELETE' | 'RESTORE'
  summary: string
  prev_hash: string | null
  hash: string
  created_at: string
  payload: Record<string, unknown> | null
}

interface FieldbookAuditDrawerProps {
  open: boolean
  onClose: () => void
  projectId?: string
}

const ACTION_STYLES: Record<AuditEvent['action'], { bg: string; text: string; i18nKey: string }> = {
  INSERT:     { bg: 'bg-emerald-500/15',  text: 'text-emerald-300', i18nKey: 'audit.created' },
  UPDATE:     { bg: 'bg-blue-500/15',     text: 'text-blue-300',    i18nKey: 'audit.updated' },
  SOFT_DELETE:{ bg: 'bg-amber-500/15',    text: 'text-amber-300',   i18nKey: 'audit.softDeleted' },
  RESTORE:    { bg: 'bg-purple-500/15',   text: 'text-purple-300',  i18nKey: 'audit.restored' },
  DELETE:     { bg: 'bg-red-500/15',      text: 'text-red-300',     i18nKey: 'audit.deleted' },
}

function relTime(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime()
  if (diff < 60_000) return 'just now'
  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}m ago`
  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)}h ago`
  if (diff < 7 * 86_400_000) return `${Math.floor(diff / 86_400_000)}d ago`
  return new Date(iso).toLocaleDateString()
}

export function FieldbookAuditDrawer({ open, onClose, projectId }: FieldbookAuditDrawerProps) {
  const { t } = useLanguage()
  const [events, setEvents] = useState<AuditEvent[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [expanded, setExpanded] = useState<Set<string>>(new Set())
  const [copied, setCopied] = useState<string | null>(null)

  const load = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const url = new URL('/api/fieldbook/audit', window.location.origin)
      url.searchParams.set('limit', '100')
      if (projectId) url.searchParams.set('project_id', projectId)
      const res = await fetch(url.toString())
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const data = await res.json()
      setEvents(data.events || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load audit log')
    } finally {
      setLoading(false)
    }
  }, [projectId])

  useEffect(() => {
    if (open) load()
  }, [open, load])

  const toggleExpand = (id: string) => {
    setExpanded((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const copyHash = async (hash: string) => {
    try {
      await navigator.clipboard.writeText(hash)
      setCopied(hash)
      setTimeout(() => setCopied(null), 1500)
    } catch {
      /* clipboard blocked — ignore */
    }
  }

  if (!open) return null

  return (
    <div
      className="fixed inset-0 bg-black/70 backdrop-blur-sm z-[70] flex items-end sm:items-center justify-center"
      style={{ animation: 'fadeIn 0.2s ease-out' }}
      onClick={onClose}
    >
      <div
        className="bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-t-2xl sm:rounded-2xl w-full max-w-2xl max-h-[90vh] flex flex-col shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-[var(--border-color)] bg-[var(--bg-secondary)]/50">
          <div className="flex items-center gap-3">
            <div className="grid place-items-center w-10 h-10 rounded-lg bg-emerald-500/15 ring-1 ring-emerald-500/30">
              <ShieldCheck className="w-5 h-5 text-emerald-400" />
            </div>
            <div>
              <h2 className="text-base font-semibold text-[var(--text-primary)]">{t('audit.title')}</h2>
              <p className="text-xs text-[var(--text-muted)]">
                Hash-chained evidence log · {events.length} event{events.length !== 1 ? 's' : ''}
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)]"
            aria-label="Close"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto p-3">
          {loading && (
            <div className="flex items-center justify-center py-12 text-[var(--text-muted)]">
              <div className="w-5 h-5 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin mr-2" />
              {t('common.loading')}
            </div>
          )}

          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-300 text-sm">
              <ShieldAlert className="w-4 h-4" />
              {error}
            </div>
          )}

          {!loading && !error && events.length === 0 && (
            <div className="text-center py-12 text-[var(--text-muted)]">
              <ShieldCheck className="w-10 h-10 mx-auto mb-3 opacity-50" />
              <p className="text-sm">{t('audit.noEvents')}</p>
            </div>
          )}

          {!loading && !error && events.length > 0 && (
            <ol className="relative">
              {/* vertical timeline line */}
              <div className="absolute left-[19px] top-2 bottom-2 w-px bg-[var(--border-color)]" />
              {events.map((ev) => {
                const style = ACTION_STYLES[ev.action]
                const isExpanded = expanded.has(ev.id)
                return (
                  <li key={ev.id} className="relative pl-12 pb-3">
                    {/* timeline dot */}
                    <div className={`absolute left-[12px] top-2.5 w-3.5 h-3.5 rounded-full ring-4 ring-[var(--bg-primary)] ${style.bg}`} />

                    <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-3">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2 flex-wrap mb-1">
                            <span className={`px-1.5 py-0.5 rounded text-[10px] font-mono uppercase tracking-wider ${style.bg} ${style.text}`}>
                              {t(style.i18nKey)}
                            </span>
                            <span className="text-xs text-[var(--text-muted)] font-mono">
                              {ev.table_name === 'project_fieldbook_entries' ? 'fieldbook' : 'survey_point'}
                            </span>
                          </div>
                          <p className="text-sm text-[var(--text-primary)] truncate">
                            {ev.summary || ev.action}
                          </p>
                          <div className="flex items-center gap-3 mt-1.5 text-[10px] text-[var(--text-muted)]">
                            <span className="flex items-center gap-1">
                              <User className="w-2.5 h-2.5" />
                              {ev.user_email || ev.user_id?.slice(0, 8) || 'system'}
                            </span>
                            <span className="flex items-center gap-1">
                              <Clock className="w-2.5 h-2.5" />
                              {relTime(ev.created_at)}
                            </span>
                          </div>
                        </div>

                        <button
                          onClick={() => toggleExpand(ev.id)}
                          className="p-1 rounded text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)]"
                          aria-label={t('audit.viewDetails')}
                        >
                          {isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                        </button>
                      </div>

                      {/* Hash row */}
                      <div className="flex items-center gap-1.5 mt-2 pt-2 border-t border-[var(--border-color)]">
                        <Hash className="w-3 h-3 text-[var(--text-muted)] shrink-0" />
                        <code className="text-[10px] font-mono text-[var(--text-muted)] truncate flex-1">
                          {ev.hash.slice(0, 16)}…{ev.hash.slice(-8)}
                        </code>
                        <button
                          onClick={() => copyHash(ev.hash)}
                          className="p-1 rounded text-[var(--text-muted)] hover:text-[var(--accent)]"
                          aria-label={t('audit.copyHash')}
                        >
                          {copied === ev.hash ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
                        </button>
                      </div>

                      {/* Expanded payload */}
                      {isExpanded && ev.payload && (
                        <pre className="mt-2 p-2 rounded bg-[var(--bg-secondary)] text-[10px] font-mono text-[var(--text-secondary)] overflow-x-auto max-h-48">
                          {JSON.stringify(ev.payload, null, 2)}
                        </pre>
                      )}
                    </div>
                  </li>
                )
              })}
            </ol>
          )}
        </div>

        {/* Footer — integrity notice */}
        <div className="p-3 border-t border-[var(--border-color)] bg-[var(--bg-secondary)]/50">
          <p className="text-[10px] text-[var(--text-muted)] flex items-center gap-1.5">
            <ShieldCheck className="w-3 h-3 text-emerald-400" />
            {t('audit.integrityValid')}
          </p>
        </div>
      </div>
    </div>
  )
}

'use client';

/**
 * FieldbookQuickActions
 * ----------------------
 * A suite of innovative quick-action features for field book data entry:
 *
 *   - Quick Duplicate Detection: warns when a similar reading already exists
 *   - Smart Bearing Parser Badge: interprets DDD.MMSS, quadrant, or DMS input
 *   - Field Weather Note: tag weather conditions with timestamps
 *   - Instrument Check Reminder: periodic 30-min reminder for instrument checks
 *   - Computation Preview Card: shows computed result before user clicks compute
 */

import { useState, useEffect, useCallback, useMemo } from 'react';
import {
  AlertTriangle,
  CloudSun,
  Copy,
  Eye,
  Sun,
  Cloud,
  CloudRain,
  Wind,
  CheckCircle2,
  ThermometerSun,
  Calculator,
  ArrowRight,
} from 'lucide-react';
import { parseFieldAngle, normalizeBearing, bearingToString, wcbToQuadrant } from '@/lib/engine/angles';

// ─── Types ──────────────────────────────────────────────────────────────

export type WeatherCondition = 'sunny' | 'cloudy' | 'rainy' | 'windy';

export interface WeatherNote {
  id: string;
  timestamp: string;
  condition: WeatherCondition;
}

export interface DuplicateWarning {
  isDuplicate: boolean;
  existingIndex: number | null;
  similarity: number;
}

export interface ComputationPreview {
  type: 'mean_angle' | 'radiation_coord' | 'running_rl' | 'tide_corrected' | null;
  label: string;
  value: string;
  detail?: string;
}

interface FieldbookQuickActionsProps {
  /** Current survey type */
  surveyType: 'leveling' | 'traverse' | 'control' | 'hydrographic' | 'mining';

  /** Current rows in the field book */
  rows: Array<{ id: string; [key: string]: string }>;

  /** New row being entered (partial) */
  currentEntry: Record<string, string>;

  /** Bearing text the user is currently typing */
  bearingInput?: string;

  /** Current computation result (from the page) */
  computed: any;

  /** Callback to save a weather note with the fieldbook data */
  onWeatherNote?: (note: WeatherNote) => void;

  /** Callback to dismiss the instrument check reminder */
  onDismissInstrumentCheck?: () => void;

  /** Whether the component is rendered on mobile */
  isMobile?: boolean;
}

// ─── Helpers ────────────────────────────────────────────────────────────

const WEATHER_CONFIG: Record<WeatherCondition, { icon: typeof Sun; label: string; color: string }> = {
  sunny: { icon: Sun, label: 'Sunny', color: 'text-amber-400' },
  cloudy: { icon: Cloud, label: 'Cloudy', color: 'text-slate-400' },
  rainy: { icon: CloudRain, label: 'Rainy', color: 'text-blue-400' },
  windy: { icon: Wind, label: 'Windy', color: 'text-teal-400' },
};

function parseBearingForBadge(input: string): { display: string; decimal: number | null; format: string } {
  if (!input || !input.trim()) return { display: '', decimal: null, format: '' };

  const trimmed = input.trim().toUpperCase();

  // Quadrant bearing: NE, NW, SE, SW (maps to 45, 315, 135, 225)
  const quadrantMap: Record<string, number> = {
    'N': 0, 'NNE': 22.5, 'NE': 45, 'ENE': 67.5,
    'E': 90, 'ESE': 112.5, 'SE': 135, 'SSE': 157.5,
    'S': 180, 'SSW': 202.5, 'SW': 225, 'WSW': 247.5,
    'W': 270, 'WNW': 292.5, 'NW': 315, 'NNW': 337.5,
  };

  if (quadrantMap[trimmed] !== undefined) {
    const deg = quadrantMap[trimmed];
    return {
      display: `${deg.toFixed(0)}\u00B000'00" (${trimmed} quadrant)`,
      decimal: deg,
      format: 'Quadrant',
    };
  }

  // Try parseFieldAngle which handles DDD.MMSS and DMS
  const parsed = parseFieldAngle(trimmed);
  if (parsed !== null) {
    const normalized = normalizeBearing(parsed);
    const dmsDisplay = bearingToString(normalized);
    const quadrant = wcbToQuadrant(normalized);

    // Detect format
    let format = 'DDD.MMSS';
    if (/[°'"]/.test(trimmed)) format = 'DMS';
    else if (/^\d+\.?\d*$/.test(trimmed) && !trimmed.includes('.')) format = 'Decimal';

    return {
      display: `${dmsDisplay} (${quadrant})`,
      decimal: normalized,
      format,
    };
  }

  return { display: 'Invalid bearing', decimal: null, format: '' };
}

function checkDuplicate(
  currentEntry: Record<string, string>,
  rows: Array<{ id: string; [key: string]: string }>,
  _surveyType: string
): DuplicateWarning {
  const station = (currentEntry.station || currentEntry.pointId || '').trim().toUpperCase();
  if (!station) return { isDuplicate: false, existingIndex: null, similarity: 0 };

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowStation = (row.station || row.pointId || '').trim().toUpperCase();

    if (rowStation === station) {
      // Check if bearing and distance are also similar
      const currentBearing = currentEntry.bearing || '';
      const rowBearing = row.bearing || '';
      const currentDist = currentEntry.slopeDist || currentEntry.slopeDistance || '';
      const rowDist = row.slopeDist || row.slopeDistance || '';

      if (currentBearing && rowBearing && currentDist && rowDist) {
        const bearingSimilar = Math.abs(parseFloat(currentBearing) - parseFloat(rowBearing)) < 0.01;
        const distSimilar = Math.abs(parseFloat(currentDist) - parseFloat(rowDist)) < 0.01;
        if (bearingSimilar && distSimilar) {
          return { isDuplicate: true, existingIndex: i, similarity: 1.0 };
        }
      }

      return { isDuplicate: true, existingIndex: i, similarity: 0.6 };
    }
  }

  return { isDuplicate: false, existingIndex: null, similarity: 0 };
}

function buildComputationPreview(
  surveyType: string,
  rows: Array<{ id: string; [key: string]: string }>,
  currentEntry: Record<string, string>,
  computed: any
): ComputationPreview | null {
  if (!rows.length && !Object.keys(currentEntry).length) return null;

  try {
    if (surveyType === 'leveling' && computed?.ok) {
      const lastReading = computed.calc?.readings?.[computed.calc.readings.length - 1];
      if (lastReading) {
        return {
          type: 'running_rl',
          label: 'Running RL',
          value: `${(lastReading.reducedLevel ?? 0).toFixed(4)} m`,
          detail: `Station: ${lastReading.station || '—'}`,
        };
      }
    }

    if (surveyType === 'traverse' && computed?.ok) {
      const legs = computed.mode === 'open' ? computed.raw?.legs : computed.adjusted?.legs;
      if (legs?.length) {
        const lastLeg = legs[legs.length - 1];
        return {
          type: 'mean_angle',
          label: 'Last Point Coords',
          value: `E: ${(lastLeg.easting ?? lastLeg.adjEasting ?? 0).toFixed(4)}  N: ${(lastLeg.northing ?? lastLeg.adjNorthing ?? 0).toFixed(4)}`,
          detail: `Bearing: ${lastLeg.bearingDMS || '—'}`,
        };
      }
    }

    if ((surveyType === 'control' || surveyType === 'mining') && computed?.ok && computed.rows?.length) {
      const lastRow = computed.rows[computed.rows.length - 1];
      if (lastRow?.computed) {
        return {
          type: 'radiation_coord',
          label: 'Computed Point',
          value: `E: ${lastRow.computed.easting.toFixed(4)}  N: ${lastRow.computed.northing.toFixed(4)}`,
          detail: `RL: ${lastRow.computed.elevation.toFixed(4)} m`,
        };
      }
    }

    if (surveyType === 'hydrographic' && computed?.ok && computed.rows?.length) {
      const lastRow = computed.rows[computed.rows.length - 1];
      if (lastRow?.corrected !== null && lastRow?.corrected !== undefined) {
        return {
          type: 'tide_corrected',
          label: 'Corrected Depth',
          value: `${lastRow.corrected.toFixed(4)} m`,
          detail: `Sounding: ${lastRow.soundingId || '—'}`,
        };
      }
    }
  } catch {
    // Silently fail — preview is best-effort
  }

  return null;
}

