          <AlertTriangle className="w-3.5 h-3.5" />
          Calculation Errors
        </div>
        {computed?.errors?.map((e: string, i: number) => (
          <div key={i} className="ml-4 list-item text-red-400/80">{e}</div>
        )) ?? <div className="text-[var(--text-muted)]">Enter station & data to compute</div>}
      </div>
    );
  }

