'use client';

import { useState } from 'react'
import { Calculator, Plus, Trash2, CheckCircle, XCircle, AlertCircle, Clock, FileText } from 'lucide-react'
import { computeAdversePossession, getRequiredEvidenceTypes } from '@/lib/compute/adversePossession'
import type { AdversePossessionAnalysis, AdversePossessionEvidenceInput } from '@/lib/compute/adversePossession'

export default function AdversePossessionCalc() {
  const [parcelId, setParcelId] = useState('')
  const [startDate, setStartDate] = useState('')
  const [endDate, setEndDate] = useState('')
  const [evidence, setEvidence] = useState<AdversePossessionEvidenceInput[]>([])
  const [analysis, setAnalysis] = useState<AdversePossessionAnalysis | null>(null)

  const evidenceTypes = getRequiredEvidenceTypes()

  const addEvidence = (type: AdversePossessionEvidenceInput['type']) => {
    setEvidence([
      ...evidence,
      {
        type,
        description: '',
        date: startDate || new Date().toISOString().split('T')[0]
      }
    ])
  }

  const updateEvidence = (index: number, field: keyof AdversePossessionEvidenceInput, value: string) => {
    const updated = [...evidence]
    updated[index] = { ...updated[index], [field]: value }
    setEvidence(updated)
  }

  const removeEvidence = (index: number) => {
    setEvidence(evidence.filter((_, i) => i !== index))
  }

  const handleCalculate = () => {
    if (!parcelId || !startDate) return

    const result = computeAdversePossession({
      parcelId,
      startDate,
      endDate: endDate || undefined,
      evidence
    })
    setAnalysis(result)
  }

  const getStrengthColor = (strength: string) => {
    switch (strength) {
      case 'STRONG': return 'text-green-600 bg-green-50'
      case 'MODERATE': return 'text-yellow-600 bg-yellow-50'
      case 'WEAK': return 'text-red-600 bg-red-50'
      default: return 'text-gray-600 bg-gray-50'
    }
  }

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-r from-indigo-50 to-purple-50 rounded-lg p-4 border border-indigo-200">
        <h3 className="font-semibold text-indigo-900 flex items-center gap-2">
          <Calculator className="w-5 h-5" />
          Adverse Possession Calculator
        </h3>
        <p className="text-sm text-indigo-700 mt-1">
          Calculate whether you meet requirements for acquiring land through adverse possession under Kenyan law
        </p>
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1" htmlFor="parcel-id-lr-number">
              Parcel ID / LR Number
            </label>
            <input id="parcel-id-lr-number"
              type="text"
              value={parcelId}
              onChange={e => setParcelId(e.target.value)}
              aria-label="e.g., NAIROBI BLOCK 2/1234" placeholder="e.g., NAIROBI BLOCK 2/1234"
              className="w-full p-2 border rounded-lg"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1" htmlFor="possession-start-date">
                Possession Start Date
              </label>
              <input id="possession-start-date" aria-label="Possession Start Date"
                type="date"
                value={startDate}
                onChange={e => setStartDate(e.target.value)}
                className="w-full p-2 border rounded-lg"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1" htmlFor="end-date-if-ended">
                End Date (if ended)
              </label>
              <input id="end-date-if-ended" aria-label="End Date (if ended)"
                type="date"
                value={endDate}
                onChange={e => setEndDate(e.target.value)}
                className="w-full p-2 border rounded-lg"
              />
            </div>
          </div>

          <div>
            <div className="flex items-center justify-between mb-2">
              <div className="block text-sm font-medium text-gray-700">
                Evidence Collection
              </div>
              <span className="text-xs text-gray-500">Add evidence to strengthen your case</span>
            </div>

            <div className="flex flex-wrap gap-2 mb-3">
              {evidenceTypes.map((type: any) => (
                <button
                  key={type.type}
                  onClick={() => addEvidence(type.type as AdversePossessionEvidenceInput['type'])}
                  className={`text-xs px-2 py-1 rounded-full border ${
                    type.priority === 'HIGH'
                      ? 'border-red-300 text-red-700 hover:bg-red-50'
                      : type.priority === 'MEDIUM'
                      ? 'border-yellow-300 text-yellow-700 hover:bg-yellow-50'
                      : 'border-gray-300 text-gray-700 hover:bg-gray-50'
                  }`}
                >
                  + {type.type.replace('_', ' ')}
                </button>
              ))}
            </div>

            <div className="space-y-2 max-h-64 overflow-y-auto">
              {evidence.map((ev, index) => (
                <div key={`${ev}-${index}`} className="p-3 bg-gray-50 rounded-lg border">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium">{ev.type.replace('_', ' ')}</span>
                    <button
                      onClick={() => removeEvidence(index)}
                      className="text-red-500 hover:text-red-700"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <input aria-label="Date"
                      type="date"
                      value={ev.date}
                      onChange={e => updateEvidence(index, 'date', e.target.value)}
                      className="text-sm p-1 border rounded"
                    />
                    <input
                      type="text"
                      value={ev.description}
                      onChange={e => updateEvidence(index, 'description', e.target.value)}
                      aria-label="Description of evidence" placeholder="Description of evidence"
                      className="text-sm p-1 border rounded"
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>

          <button
            onClick={handleCalculate}
            disabled={!parcelId || !startDate}
            className="w-full py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50"
          >
            Calculate Adverse Possession
          </button>
        </div>

        <div>
          {analysis ? (
            <div className="space-y-4">
              <div className={`p-4 rounded-lg border ${
                analysis.meetsRequirements 
                  ? 'bg-green-50 border-green-300' 
                  : analysis.duration >= 10
                  ? 'bg-yellow-50 border-yellow-300'
                  : 'bg-red-50 border-red-300'
              }`}>
                <div className="flex items-center gap-3">
                  {analysis.meetsRequirements ? (
                    <CheckCircle className="w-8 h-8 text-green-600" />
                  ) : analysis.duration >= 10 ? (
                    <Clock className="w-8 h-8 text-yellow-600" />
                  ) : (
                    <XCircle className="w-8 h-8 text-red-600" />
                  )}
                  <div>
                    <h4 className="font-semibold">
                      {analysis.meetsRequirements 
                        ? 'Ready to File!' 
                        : analysis.duration >= 10
                        ? 'Case Developing'
                        : 'Not Eligible Yet'}
                    </h4>
                    <p className="text-sm">
                      {analysis.duration} years of possession • {analysis.yearsRemaining} years remaining
                    </p>
                  </div>
                </div>
                <p className="mt-3 text-sm">{analysis.recommendation}</p>
              </div>

              <div className="flex items-center gap-2 p-3 bg-gray-100 rounded-lg">
                <FileText className="w-5 h-5 text-gray-600" />
                <span className="text-sm font-medium">Evidence Strength: </span>
                <span className={`px-2 py-0.5 rounded text-sm font-medium ${getStrengthColor(analysis.strength)}`}>
                  {analysis.strength}
                </span>
              </div>

              <div className="space-y-2">
                <h4 className="font-medium text-gray-700">Requirements Analysis</h4>
                {analysis.requirements.map((req, index) => (
                  <div key={req.name} className="p-3 border rounded-lg">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        {req.met ? (
                          <CheckCircle className="w-4 h-4 text-green-600" />
                        ) : (
                          <XCircle className="w-4 h-4 text-red-500" />
                        )}
                        <span className="font-medium text-sm">{req.name}</span>
                      </div>
                      <span className={`text-xs px-2 py-0.5 rounded ${getStrengthColor(req.strength)}`}>
                        {req.strength}
                      </span>
                    </div>
                    {req.evidence.length > 0 && (
                      <ul className="mt-2 ml-6 text-xs text-gray-600">
                        {req.evidence.map((ev, i) => (
                          <li key={`${ev}-${i}`}>• {ev}</li>
                        ))}
                      </ul>
                    )}
                  </div>
                ))}
              </div>

              <div className="space-y-2">
                <h4 className="font-medium text-gray-700">Analysis Steps</h4>
                {analysis.steps.map((step, index) => (
                  <div key={step.title} className="flex items-start gap-3 p-2">
                    <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs ${
                      step.passed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                    }`}>
                      {step.passed ? '' : '[x]'}
                    </div>
                    <div className="flex-1">
                      <p className="text-sm font-medium">{step.title}</p>
                      <p className="text-xs text-gray-600">{step.description}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="text-center py-12 text-gray-500">
              <Calculator className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p>Enter details and add evidence to calculate</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

'use client';

import { useState } from 'react'
import { Route, ChevronRight, Plus, X, MapPin } from 'lucide-react'
import { getEasementByType, getAllEasementTypes, searchEasements } from '@/lib/data/easementLaw'
import type { EasementGuidance, EasementType } from '@/types/landLaw'
import { EASEMENT_TYPE_LABELS } from '@/types/landLaw'

export default function EasementGuide() {
  const [selectedType, setSelectedType] = useState<EasementType | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [searchResults, setSearchResults] = useState<EasementGuidance[]>([])
  const [showSearch, setShowSearch] = useState(false)

  const easementTypes = getAllEasementTypes()

  const selectedEasement = selectedType ? getEasementByType(selectedType) : null

  const handleSearch = () => {
    if (searchQuery.trim()) {
      setSearchResults(searchEasements(searchQuery))
    }
  }

  const handleSelectEasement = (type: EasementType) => {
    setSelectedType(type)
    setShowSearch(false)
    setSearchQuery('')
    setSearchResults([])
  }

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-r from-green-50 to-emerald-50 rounded-lg p-4 border border-green-200">
        <h3 className="font-semibold text-green-900 flex items-center gap-2">
          <Route className="w-5 h-5" />
          Easement Guidance
        </h3>
        <p className="text-sm text-green-700 mt-1">
          Understand easements and rights of way under Kenyan law
        </p>
      </div>

      <div className="flex gap-2">
        <button
          onClick={() => setShowSearch(!showSearch)}
          className="px-4 py-2 bg-gray-100 rounded-lg text-sm hover:bg-gray-200"
        >
          {showSearch ? 'Browse by Type' : 'Search Easements'}
        </button>
      </div>

      {showSearch && (
        <div className="flex gap-2">
          <input
            type="text"
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSearch()}
            aria-label="Search easement topics..." placeholder="Search easement topics..."
            className="flex-1 p-2 border rounded-lg"
          />
          <button
            onClick={handleSearch}
            className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
          >
            Search
          </button>
        </div>
      )}

      {searchResults.length > 0 && (
        <div className="space-y-2">
          <p className="text-sm text-gray-600">Search results ({searchResults.length})</p>
          {searchResults.map((easement: any) => (
            <button
              key={easement.id}
              onClick={() => handleSelectEasement(easement.easementType)}
              className="w-full text-left p-3 border rounded-lg hover:border-green-300"
            >
              <span className="font-medium">{easement.title}</span>
            </button>
          ))}
        </div>
      )}

      {!showSearch && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
          {easementTypes.map(({ type }) => (
            <button
              key={type}
              onClick={() => setSelectedType(type)}
              className={`p-3 text-sm rounded-lg border transition-colors ${
                selectedType === type
                  ? 'border-green-500 bg-green-50'
                  : 'border-gray-200 hover:border-green-300'
              }`}
            >
              {EASEMENT_TYPE_LABELS[type]}
            </button>
          ))}
        </div>
      )}

      {selectedEasement ? (
        <div className="space-y-4">
          <div className="p-4 bg-white rounded-lg border">
            <h4 className="font-semibold text-lg text-gray-900">{selectedEasement.title}</h4>
            <p className="text-gray-600 mt-2">{selectedEasement.description}</p>

            {selectedEasement.kenyaSpecific && (
              <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-lg">
                <p className="text-sm font-medium text-amber-900">Kenya-Specific Notes</p>
                <p className="text-sm text-amber-800 mt-1">{selectedEasement.kenyaSpecific}</p>
              </div>
            )}
          </div>

          <div className="grid md:grid-cols-2 gap-4">
            <div className="p-4 bg-white rounded-lg border">
              <h5 className="font-medium text-gray-700 mb-3">Creation Methods</h5>
              <ul className="space-y-2">
                {selectedEasement.creationMethods.map((method, index) => (
                  <li key={`${method}-${index}`} className="flex items-start gap-2 text-sm">
                    <Plus className="w-4 h-4 text-green-500 mt-0.5" />
                    <span>{method}</span>
                  </li>
                ))}
              </ul>
            </div>

            <div className="p-4 bg-white rounded-lg border">
              <h5 className="font-medium text-gray-700 mb-3">Termination Methods</h5>
              <ul className="space-y-2">
                {selectedEasement.terminationMethods.map((method, index) => (
                  <li key={`${method}-${index}`} className="flex items-start gap-2 text-sm">
                    <X className="w-4 h-4 text-red-500 mt-0.5" />
                    <span>{method}</span>
                  </li>
                ))}
              </ul>
            </div>
          </div>

          <div className="p-4 bg-white rounded-lg border">
            <h5 className="font-medium text-gray-700 mb-3">Typical Disputes</h5>
            <div className="flex flex-wrap gap-2">
              {selectedEasement.typicalDisputes.map((dispute, index) => (
                <span key={`${dispute}-${index}`} className="px-3 py-1 text-sm bg-red-50 text-red-700 rounded-full">
                  {dispute}
                </span>
              ))}
            </div>
          </div>

          <div className="p-4 bg-white rounded-lg border">
            <h5 className="font-medium text-gray-700 mb-3">Surveyor Tasks</h5>
            <ul className="space-y-2">
              {selectedEasement.surveyorTasks.map((task, index) => (
                <li key={`${task}-${index}`} className="flex items-start gap-2 text-sm">
                  <MapPin className="w-4 h-4 text-blue-500 mt-0.5" />
                  <span>{task}</span>
                </li>
              ))}
            </ul>
          </div>

          <div className="p-4 bg-gray-50 rounded-lg">
            <h5 className="font-medium text-gray-700 mb-3">Legal Requirements</h5>
            <ul className="space-y-2">
              {selectedEasement.legalRequirements.map((req, index) => (
                <li key={`${req}-${index}`} className="flex items-start gap-2 text-sm text-gray-600">
                  <ChevronRight className="w-4 h-4 text-gray-400 mt-0.5" />
                  <span>{req}</span>
                </li>
              ))}
            </ul>
          </div>
        </div>
      ) : (
        <div className="text-center py-12 text-gray-500">
          <Route className="w-12 h-12 mx-auto mb-3 opacity-50" />
          <p>Select an easement type to view guidance</p>
        </div>
      )}
    </div>
  )
}

'use client'

import { usePathname } from 'next/navigation'
import { ReactNode, useEffect, useState } from 'react'
import NavBar from '@/components/NavBar'
import Footer from '@/components/Footer'
import FeedbackWidget from '@/components/FeedbackWidget'
import { QuickCompute } from '@/components/layout/QuickCompute'
import MobileNav from '@/components/MobileNav'
import { HotkeyHelpOverlay } from '@/components/shared/HotkeyHelpOverlay'
import { AppUpdateBanner } from '@/components/app/AppUpdateBanner'
import { OfflineIndicator } from '@/components/app/OfflineIndicator'
import { PWAInstallBanner } from '@/components/app/PWAInstallBanner'
import { ProjectionInit } from '@/components/layout/ProjectionInit'
import FieldModeToggle from '@/components/shared/FieldModeToggle'
import { LanguageProvider } from '@/lib/i18n/LanguageContext'
import { CountryProvider } from '@/lib/country'
import { SubscriptionProvider } from '@/lib/subscription/subscriptionContext'
import SkipToContent from '@/components/shared/SkipToContent'
import { NotificationBell } from '@/components/notifications/NotificationBell'
import { CommandPalette } from '@/components/search/CommandPalette'
import { OnboardingTour } from '@/components/onboarding/OnboardingTour'
import { LoadingScreen } from '@/components/shared/LoadingScreen'
import dynamic from 'next/dynamic'

const NotificationToast = dynamic(
  () => import('@/components/ui/NotificationToast').then(m => ({ default: m.NotificationToast })),
  { ssr: false }
)

/* ── Route classification ─────────────────────────────────────────── */

function isFullScreenRoute(pathname: string): boolean {
  return pathname === '/field/map' || pathname.startsWith('/field/map/')
}

function isAdminRoute(pathname: string): boolean {
  return pathname === '/admin' || pathname.startsWith('/admin/')
}

function isAuthRoute(pathname: string): boolean {
  return pathname === '/login' || pathname === '/register' || pathname.startsWith('/login/') || pathname.startsWith('/register/')
}

function isDashboardRoute(pathname: string): boolean {
  // Dashboard routes use sidebar navigation, not the top NavBar
  return pathname === '/dashboard' || pathname.startsWith('/dashboard/') ||
         pathname.startsWith('/survey/') || pathname.startsWith('/project/')
}

function isHiddenShellRoute(pathname: string): boolean {
  return isFullScreenRoute(pathname) || isAdminRoute(pathname)
}

function isMapRoute(pathname: string): boolean {
  return pathname === '/map' || pathname.startsWith('/map/')
}

function isFieldbookRoute(pathname: string): boolean {
  return pathname === '/fieldbook' || pathname.startsWith('/fieldbook/')
}

/* ── Shell Component ─────────────────────────────────────────────── */

// Only show the loading screen once per browser session (not on every route change)
let _hasShownLoadingScreen = false

export default function AppShell({ children }: { children: ReactNode }) {
  const pathname = usePathname()
  const fullScreen = isFullScreenRoute(pathname)
  const admin = isAdminRoute(pathname)
  const hidden = isHiddenShellRoute(pathname)
  const auth = isAuthRoute(pathname)
  const dashboard = isDashboardRoute(pathname) // Uses sidebar nav, not top NavBar
  const mapPage = isMapRoute(pathname)
  const fieldbookPage = isFieldbookRoute(pathname)
  // Map and fieldbook are full-data-entry surfaces — the global overlays
  // (Footer, FeedbackWidget, QuickCompute, MobileNav, CommandPalette)
  // overlap the entry form and steal taps from the surveyor on a phone.
  const hideGlobalOverlays = mapPage || fieldbookPage
  const [initialLoading, setInitialLoading] = useState(!_hasShownLoadingScreen)

  // UI-12 (2026-07-24): Removed the OnboardingModal state + localStorage
  // 'metardu_onboarding_seen' key. The modal was redundant with the
  // OnboardingChecklist (rendered via OnboardingWrapper in the dashboard)
  // and the OnboardingTour (rendered below). Three onboarding flows
  // firing independently with 3 different localStorage keys created a
  // confusing first-run experience. Now there are exactly two:
  //   1. OnboardingChecklist (dashboard) — persistent progress tracker
  //   2. OnboardingTour (AppShell) — guided walk-through, respects the
  //      checklist's dismissed state so it doesn't fire before the
  //      user has seen the checklist.

  // Show branded loading screen only on very first app load
  useEffect(() => {
    if (_hasShownLoadingScreen) {
      setInitialLoading(false)
      return
    }
    const timer = setTimeout(() => {
      setInitialLoading(false)
      _hasShownLoadingScreen = true
    }, 1500)
    return () => clearTimeout(timer)
  }, [])

  useEffect(() => {
    if (isAuthRoute(pathname)) return
    // UI-12: OnboardingModal removed — see comment above.
  }, [pathname])

  // Auth routes (login/register): bare page, no chrome
  if (auth) {
    return (
      <>
        <SkipToContent />
        <OfflineIndicator />
        <ProjectionInit />
        <LanguageProvider>
          <CountryProvider>
            <SubscriptionProvider>
              <main id="main-content" className="min-h-screen max-w-full overflow-x-hidden">
                {children}
              </main>
              <NotificationToast />
            </SubscriptionProvider>
          </CountryProvider>
        </LanguageProvider>
      </>
    )
  }

  // Full-screen routes (field map): no chrome at all, but field mode toggle is always available
  if (fullScreen) {
    return (
      <>
        <SkipToContent />
        <AppUpdateBanner />
        <OfflineIndicator />
        <PWAInstallBanner />
        <ProjectionInit />
        <LanguageProvider>
          <CountryProvider>
            <SubscriptionProvider>
              <main id="main-content" className="overflow-hidden">
                {children}
              </main>
              <div className="fixed bottom-6 right-6 z-50">
                <FieldModeToggle />
              </div>
              <div className="fixed top-4 right-4 z-50 flex items-center gap-2">
                <NotificationBell />
              </div>
              <CommandPalette />
              <HotkeyHelpOverlay />
              <NotificationToast />
              
            </SubscriptionProvider>
          </CountryProvider>
        </LanguageProvider>
      </>
    )
  }

  // Admin routes: hide NavBar, Footer, QuickCompute, FeedbackWidget, MobileNav
  if (admin) {
    return (
      <>
        <SkipToContent />
        <AppUpdateBanner />
        <OfflineIndicator />
        <PWAInstallBanner />
        <ProjectionInit />
        <LanguageProvider>
          <CountryProvider>
            <SubscriptionProvider>
              <main id="main-content" className="min-h-screen max-w-full overflow-x-hidden">
                {children}
              </main>
              <div className="fixed top-4 right-4 z-50 flex items-center gap-2">
                <NotificationBell />
                <FieldModeToggle />
              </div>
              <CommandPalette />
              <HotkeyHelpOverlay />
              <NotificationToast />
              
            </SubscriptionProvider>
          </CountryProvider>
        </LanguageProvider>
      </>
    )
  }

  // Default: full app shell
  return (
    <>
      <LoadingScreen
        visible={initialLoading}
        message="Initializing METARDU"
        subMessage="Loading survey engine, map projections, and field tools..."
        autoDismiss={1500}
        onDismiss={() => setInitialLoading(false)}
      />
      <SkipToContent />
      <AppUpdateBanner />
      <OfflineIndicator />
      <PWAInstallBanner />
      <ProjectionInit />
      <LanguageProvider>
        <CountryProvider>
          <SubscriptionProvider>
            {/* AUDIT FIX: Hide top NavBar on dashboard routes — they use
                sidebar navigation via (dashboard)/layout.tsx. Showing both
                NavBar + sidebar header = double navigation bar. */}
            {!dashboard && <NavBar />}
            <main id="main-content" className={`min-h-screen max-w-full overflow-x-hidden ${dashboard ? '' : 'pb-40 md:pb-0 mobile-nav-spacer'}`}>
              {children}
            </main>
            <Footer />
            {!hideGlobalOverlays && <FeedbackWidget />}
            <HotkeyHelpOverlay />
            {/* Hide QuickCompute and FeedbackWidget on map + fieldbook pages — they overlap entry controls */}
            {!hideGlobalOverlays && <QuickCompute />}
            {!dashboard && !hideGlobalOverlays && <MobileNav />}
            {!hideGlobalOverlays && <CommandPalette />}
            <NotificationToast />
            <OnboardingTour />
            
          </SubscriptionProvider>
        </CountryProvider>
      </LanguageProvider>
    </>
  )
}

'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useSession } from 'next-auth/react'
import {
  FolderKanban, Wrench, Compass, FileText,
  LayoutDashboard, Users, ShieldCheck, CreditCard,
  Settings2, Activity, ChevronLeft, BarChart3,
  Map, Building2, HelpCircle, LayoutTemplate, Boxes,
  RoadIcon, Mountain, Sparkles,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { OutdoorModeToggle } from '@/components/shared/OutdoorModeToggle'
import MetarduLogo from '@/components/MetarduLogo'

// ---------------------------------------------------------------------------
// Navigation items by role
// ---------------------------------------------------------------------------

interface NavItem {
  href: string
  label: string
  icon: React.ComponentType<{ className?: string }>
  exact?: boolean
  hash?: string
}

const userNavItems: NavItem[] = [
  { href: '/dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { href: '/cadastral-workflow', label: 'Cadastral', icon: Compass },
  { href: '/engineering-workflow', label: 'Engineering', icon: RoadIcon },
  { href: '/topographic-workflow', label: 'Topographic', icon: Mountain },
  { href: '/projects', label: 'Projects', icon: FolderKanban },
  { href: '/process', label: 'Corrections', icon: Wrench },
  { href: '/tools/all', label: 'Toolbox', icon: Boxes },
  { href: '/tools/cogo', label: 'COGO', icon: Compass },
  { href: '/map', label: 'Map', icon: Map },
  { href: '/documents', label: 'Documents', icon: FileText },
  { href: '/report-templates', label: 'Templates', icon: LayoutTemplate },
  { href: '/sectional', label: 'Sectional', icon: Building2 },
  { href: '/analytics', label: 'Analytics', icon: BarChart3 },
  { href: '/assistant', label: 'Assistant', icon: Sparkles },
  { href: '/help', label: 'Help', icon: HelpCircle },
]

const adminNavItems: NavItem[] = [
  { href: '/admin', label: 'Dashboard', icon: LayoutDashboard, exact: true },
  { href: '/admin/users', label: 'Users', icon: Users },
  { href: '/admin/payments', label: 'Payments', icon: CreditCard },
  { href: '/audit-logs', label: 'Audit Logs', icon: ShieldCheck },
  { href: '/admin', label: 'System Health', icon: Settings2, hash: '#system' },
  { href: '/analytics', label: 'Analytics', icon: BarChart3 },
]

// ---------------------------------------------------------------------------
// Sidebar component
// ---------------------------------------------------------------------------

interface AppSidebarProps {
  variant: 'user' | 'admin'
  className?: string
  onNavigate?: () => void
}

export default function AppSidebar({ variant, className, onNavigate }: AppSidebarProps) {
  const pathname = usePathname()
  const { data: session } = useSession()

  const navItems = variant === 'admin' ? adminNavItems : userNavItems
  const userRole = (session?.user as { role?: string })?.role ?? ''

  return (
    <aside
      className={cn(
        'h-full flex flex-col bg-[var(--bg-secondary)] border-r border-[var(--border-color)]',
        className,
      )}
    >
      {/* Logo */}
      <div className="flex items-center justify-between px-4 py-4 border-b border-[var(--border-color)]">
        <Link
          href="/"
          onClick={onNavigate}
          className="flex items-center gap-2 no-underline"
        >
          <MetarduLogo size={28} showWordmark={true} color="var(--text-primary)" />
        </Link>
      </div>

      {/* Navigation */}
      <nav className="flex-1 p-3 space-y-0.5 overflow-y-auto">
        {navItems.map((item) => {
          const isActive = item.exact
            ? pathname === item.href
            : item.hash
              ? pathname === item.href && typeof window !== 'undefined' && window.location.hash === item.hash
              : pathname.startsWith(item.href)

          const href = item.hash ? `${item.href}${item.hash}` : item.href

          return (
            <Link
              key={`${item.href}${item.hash ?? ''}`}
              href={href}
              onClick={onNavigate}
              className={cn(
                'flex items-center gap-3 px-3 py-2 rounded-md text-sm transition-colors no-underline',
                isActive
                  ? 'bg-[var(--accent)] text-[var(--bg-primary)] font-medium'
                  : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)]',
              )}
            >
              <item.icon className="w-4 h-4 shrink-0" />
              {item.label}
            </Link>
          )
        })}
      </nav>

      {/* Footer */}
      <div className="p-3 border-t border-[var(--border-color)] space-y-1">
        {/* Outdoor mode toggle */}
        <div className="flex items-center justify-between px-3 py-1.5">
          <span className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider">
            Outdoor Mode
          </span>
          <OutdoorModeToggle />
        </div>
        {/* Role badge */}
        <div className="px-3 py-1.5">
          <p className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider">
            {variant === 'admin' ? 'Admin Panel' : 'Kenya Cadastral'}
          </p>
          <p className="text-xs text-[var(--text-secondary)] capitalize">{userRole || 'Surveyor'}</p>
        </div>

        {/* Switch between admin/user dashboards */}
        {variant === 'admin' ? (
          <Link
            href="/dashboard"
            onClick={onNavigate}
            className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-tertiary)] transition-colors no-underline"
          >
            <ChevronLeft className="w-4 h-4" />
            Back to App
          </Link>
        ) : (
          (userRole === 'super_admin' || userRole === 'admin' || userRole === 'org_admin') && (
            <Link
              href="/admin"
              onClick={onNavigate}
              className="flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-[var(--accent)] hover:bg-[var(--accent)]/5 transition-colors no-underline"
            >
              <ShieldCheck className="w-4 h-4" />
              Admin Panel
            </Link>
          )
        )}
      </div>
    </aside>
  )
}

'use client';
/**
 * METARDU Layer Control Panel
 *
 * UI panel for managing map layers:
 * - Basemap toggle (OSM / Satellite / Blank)
 * - Custom XYZ orthophoto layer
 * - Kenya Grid overlay with configurable intervals
 * - Opacity control for tile overlays
 * - Active layer list with visibility toggles
 *
 * Follows the SubdivisionPanel collapsible panel pattern.
 * Style: Tailwind CSS, #1B3A5C primary, Calibri font.
 */


import { useState, useEffect, useCallback, useRef } from 'react';
import {
  Layers,
  ChevronDown,
  MapIcon,
  Satellite,
  Square,
  Plus,
  Eye,
  EyeOff,
  Grid3X3,
  Link2,
  Trash2,
  AlertCircle,
  SlidersHorizontal,
} from 'lucide-react';
import {
  createOSMLayer,
  createSatelliteLayer,
  createBlankLayer,
  createCustomXYZLayer,
  createWMSLayer,
} from '@/lib/map/basemaps';
import {
  createGridOverlayLayer,
  updateGridOverlay,
  GRID_LAYER_ID,
  type GridInterval,
} from '@/lib/map/gridOverlay';
import type Map from 'ol/Map';

interface LayerControlProps {
  map: Map | null;
  /** Callback when basemap changes, for external state sync */
  onBasemapChange?: (basemap: 'osm' | 'satellite' | 'blank') => void;
  /** Hide the basemap selector section (when parent already manages basemaps) */
  hideBasemap?: boolean;
  /** Start collapsed (default false) */
  defaultCollapsed?: boolean;
  className?: string;
}

interface CustomLayerEntry {
  id: string;
  label: string;
  url: string;
  type?: 'xyz' | 'wms';
}

const CUSTOM_LAYERS_STORAGE_KEY = 'metardu-custom-layers';

function loadPersistedLayers(): CustomLayerEntry[] {
  try {
    const raw = localStorage.getItem(CUSTOM_LAYERS_STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function persistLayers(entries: CustomLayerEntry[]) {
  try {
    localStorage.setItem(CUSTOM_LAYERS_STORAGE_KEY, JSON.stringify(entries));
  } catch {
    // localStorage may be full or unavailable
  }
}

type BasemapType = 'osm' | 'satellite' | 'blank';

export function LayerControl({ map, onBasemapChange, hideBasemap = false, defaultCollapsed = false, className = '' }: LayerControlProps) {
  const [isCollapsed, setIsCollapsed] = useState(defaultCollapsed);
  const [activeBasemap, setActiveBasemap] = useState<BasemapType>('osm');
  const [gridEnabled, setGridEnabled] = useState(false);
  const [gridInterval, setGridInterval] = useState<GridInterval>('auto');
  const [overlayOpacity, setOverlayOpacity] = useState(80);
  const [customLayers, setCustomLayers] = useState<CustomLayerEntry[]>([]);
  const [customUrl, setCustomUrl] = useState('');
  const [customLabel, setCustomLabel] = useState('');
  const [customError, setCustomError] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [initialized, setInitialized] = useState(false);

  // WMS layer state
  const [wmsUrl, setWmsUrl] = useState('');
  const [wmsLayerName, setWmsLayerName] = useState('');
  const [wmsLabel, setWmsLabel] = useState('');
  const [wmsError, setWmsError] = useState('');
  const [isAddingWms, setIsAddingWms] = useState(false);
  const [tileLayerVisibility, setTileLayerVisibility] = useState<Record<string, boolean>>({});

  // Store cleanup for the async init effect
  const moveendCleanupRef = useRef<(() => void) | null>(null);

  // ─── Initialize basemap layers on map ─────────────────────────────────
  useEffect(() => {
    if (!map || initialized) return;
    const mapInstance = map; // non-null capture for async closure
    let cancelled = false;

    async function init() {
      // Check if layers already exist (from parent map init)
      const existingLayers = mapInstance.getLayers().getArray();
      const hasExistingOSM = existingLayers.some((l: any) => l.get('basemapId') === 'osm');
      const hasExistingSatellite = existingLayers.some((l: any) => l.get('basemapId') === 'satellite');
      const hasExistingBlank = existingLayers.some((l: any) => l.get('basemapId') === 'blank');
      const hasExistingGrid = existingLayers.some((l: any) => l.get('layerId') === GRID_LAYER_ID);

      // Only create basemap layers that don't already exist
      let osmLayer: Awaited<ReturnType<typeof createOSMLayer>> | null = null;
      let satelliteLayer: Awaited<ReturnType<typeof createSatelliteLayer>> | null = null;
      let blankLayer: Awaited<ReturnType<typeof createBlankLayer>> | null = null;

      const layerPromises: Promise<any>[] = [];
      const layerNames: string[] = [];

      if (!hasExistingOSM) { layerPromises.push(createOSMLayer()); layerNames.push('osm'); }
      if (!hasExistingSatellite) { layerPromises.push(createSatelliteLayer()); layerNames.push('satellite'); }
      if (!hasExistingBlank) { layerPromises.push(createBlankLayer()); layerNames.push('blank'); }

      const createdLayers = await Promise.all(layerPromises);
      if (cancelled) return;

      for (let i = 0; i < createdLayers.length; i++) {
        if (layerNames[i] === 'osm') osmLayer = createdLayers[i];
        if (layerNames[i] === 'satellite') satelliteLayer = createdLayers[i];
        if (layerNames[i] === 'blank') blankLayer = createdLayers[i];
      }

      let gridLayer: Awaited<ReturnType<typeof createGridOverlayLayer>> | null = null;
      if (!hasExistingGrid) {
        gridLayer = await createGridOverlayLayer();
      }

      // Insert new basemap layers at the beginning
      const layers = mapInstance.getLayers();
      if (blankLayer) {
        layers.insertAt(0, blankLayer);
        blankLayer.setVisible(false);
      }
      if (satelliteLayer) {
        layers.insertAt(layers.getLength() > 0 ? 1 : 0, satelliteLayer);
        satelliteLayer.setVisible(false);
      }
      if (osmLayer) {
        layers.insertAt(layers.getLength() > 0 ? 2 : 0, osmLayer);
        osmLayer.setVisible(true);
      }

      if (gridLayer) {
        layers.push(gridLayer);
      }

      setInitialized(true);

      // ── Restore persisted custom layers from localStorage ──
      const persisted = loadPersistedLayers();
      if (persisted.length > 0) {
        const restored: CustomLayerEntry[] = [];
        for (const entry of persisted) {
          try {
            let layer: any = null;
            if (entry.type === 'wms') {
              // WMS layers need a layer name which we stored in the url field
              // Format: url|layerName  (we stored it combined)
              const parts = entry.url.split('|');
              if (parts.length >= 2) {
                layer = await createWMSLayer(parts[0], parts[1], entry.label);
              }
            } else {
              layer = await createCustomXYZLayer(entry.url, entry.label);
            }
            if (layer) {
              (layer as any).setOpacity(overlayOpacity / 100);
              mapInstance.addLayer(layer);
              const id = layer.get('basemapId') as string;
              restored.push({ id, label: entry.label, url: entry.url, type: entry.type });
            }
          } catch {
            // Skip layers that fail to restore
          }
        }
        if (restored.length > 0) {
          setCustomLayers(restored);
          const visibilityMap: Record<string, boolean> = {};
          restored.forEach((e) => { visibilityMap[e.id] = true; });
          setTileLayerVisibility((prev) => ({ ...prev, ...visibilityMap }));
        }
      }

      // Update grid on view changes (debounced)
      let debounceTimer: ReturnType<typeof setTimeout> | null = null;
      const onMoveEnd = () => {
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = setTimeout(async () => {
          if (gridEnabled) {
            await updateGridOverlay(mapInstance, gridInterval);
          }
        }, 150);
      };
      mapInstance.on('moveend', onMoveEnd);

      // Store cleanup for later use
      moveendCleanupRef.current = () => {
        if (debounceTimer) clearTimeout(debounceTimer);
        mapInstance.un('moveend', onMoveEnd);
      };

      // Initial grid update if enabled
      if (gridEnabled) {
        await updateGridOverlay(mapInstance, gridInterval);
      }
    }

    init();

    return () => {
      cancelled = true;
      moveendCleanupRef.current?.();
      moveendCleanupRef.current = null;
    };
  }, [map, initialized, gridEnabled, gridInterval]);

  // ─── Sync overlay opacity to layers ───────────────────────────────────
  useEffect(() => {
    if (!map) return;

    const layers = map.getLayers().getArray();
    for (const layer of layers) {
      const basemapId = layer.get('basemapId');
      if (basemapId === 'satellite' || basemapId?.startsWith('custom-')) {
        (layer as any).setOpacity(overlayOpacity / 100);
      }
    }
  }, [map, overlayOpacity]);

  // ─── Switch basemap ───────────────────────────────────────────────────
  const switchBasemap = useCallback(
    (target: BasemapType) => {
      if (!map) return;
      setActiveBasemap(target);
      onBasemapChange?.(target);

      const layers = map.getLayers().getArray();
      for (const layer of layers) {
        const basemapId = layer.get('basemapId');
        if (basemapId === 'osm') {
          layer.setVisible(target === 'osm');
        } else if (basemapId === 'satellite') {
          layer.setVisible(target === 'satellite');
          (layer as any).setOpacity(overlayOpacity / 100);
        } else if (basemapId === 'blank') {
          layer.setVisible(target === 'blank');
        }
      }
    },
    [map, onBasemapChange, overlayOpacity]
  );

  // ─── Toggle grid overlay ──────────────────────────────────────────────
  const toggleGrid = useCallback(async () => {
    if (!map) return;

    const newEnabled = !gridEnabled;
    setGridEnabled(newEnabled);

    const layers = map.getLayers().getArray();
    for (const layer of layers) {
      if (layer.get('layerId') === GRID_LAYER_ID) {
        layer.setVisible(newEnabled);
        if (newEnabled) {
          await updateGridOverlay(map, gridInterval);
        }
        break;
      }
    }
  }, [map, gridEnabled, gridInterval]);

  // ─── Change grid interval ─────────────────────────────────────────────
  const changeGridInterval = useCallback(
    async (newInterval: GridInterval) => {
      setGridInterval(newInterval);
      if (!map || !gridEnabled) return;
      await updateGridOverlay(map, newInterval);
    },
    [map, gridEnabled]
  );

  // ─── Add custom XYZ layer ─────────────────────────────────────────────
  const addCustomLayer = useCallback(async () => {
    if (!map || !customUrl.trim()) return;

    setCustomError('');
    setIsAdding(true);

    try {
      const label = customLabel.trim() || `Orthophoto ${customLayers.length + 1}`;
      const layer = await createCustomXYZLayer(customUrl.trim(), label);
      (layer as any).setOpacity(overlayOpacity / 100);

      map.addLayer(layer);
      const id = layer.get('basemapId') as string;
      const newEntry = { id, label, url: customUrl.trim(), type: 'xyz' as const };
      setCustomLayers((prev) => {
        const updated = [...prev, newEntry];
        persistLayers(updated);
        return updated;
      });
      setTileLayerVisibility((prev) => ({ ...prev, [id]: true }));
      setCustomUrl('');
      setCustomLabel('');
    } catch (err: unknown) {
      setCustomError(((err as Error)?.message) || 'Failed to add layer');
    } finally {
      setIsAdding(false);
    }
  }, [map, customUrl, customLabel, customLayers.length, overlayOpacity]);

  // ─── Add WMS layer (GeoServer / MapServer) ──────────────────────────
  const addWmsLayer = useCallback(async () => {
    if (!map || !wmsUrl.trim() || !wmsLayerName.trim()) return;

    setWmsError('');
    setIsAddingWms(true);

    try {
      const label = wmsLabel.trim() || wmsLayerName.trim();
      const layer = await createWMSLayer(wmsUrl.trim(), wmsLayerName.trim(), label);
      (layer as any).setOpacity(overlayOpacity / 100);

      map.addLayer(layer);
      const id = layer.get('basemapId') as string;
      const newEntry = { id, label, url: `${wmsUrl.trim()}|${wmsLayerName.trim()}`, type: 'wms' as const };
      setCustomLayers((prev) => {
        const updated = [...prev, newEntry];
        persistLayers(updated);
        return updated;
      });
      setTileLayerVisibility((prev) => ({ ...prev, [id]: true }));
      setWmsUrl('');
      setWmsLayerName('');
      setWmsLabel('');
    } catch (err: unknown) {
      setWmsError(((err as Error)?.message) || 'Failed to add WMS layer');
    } finally {
      setIsAddingWms(false);
    }
  }, [map, wmsUrl, wmsLayerName, wmsLabel, customLayers.length, overlayOpacity]);

  // ─── Remove custom layer ──────────────────────────────────────────────
  const removeCustomLayer = useCallback(
    (id: string) => {
      if (!map) return;

      const layers = map.getLayers().getArray();
      for (let i = 0; i < layers.length; i++) {
        if (layers[i].get('basemapId') === id) {
          map.getLayers().removeAt(i);
          break;
        }
      }
      setCustomLayers((prev) => {
        const updated = prev.filter((l) => l.id !== id);
        persistLayers(updated);
        return updated;
      });
      setTileLayerVisibility((prev) => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    },
    [map]
  );

  // ─── Toggle custom layer visibility ───────────────────────────────────
  const toggleCustomLayerVisibility = useCallback(
    (id: string) => {
      if (!map) return;

      const layers = map.getLayers().getArray();
      for (const layer of layers) {
        if (layer.get('basemapId') === id) {
          const current = layer.getVisible();
          layer.setVisible(!current);
          setTileLayerVisibility((prev) => ({ ...prev, [id]: !current }));
          break;
        }
      }
    },
    [map]
  );

  const basemapOptions: Array<{
    id: BasemapType;
    icon: React.ReactNode;
    label: string;
  }> = [
    { id: 'osm', icon: <MapIcon className="w-4 h-4" />, label: 'OSM' },
    { id: 'satellite', icon: <Satellite className="w-4 h-4" />, label: 'Satellite' },
    { id: 'blank', icon: <Square className="w-4 h-4" />, label: 'Blank' },
  ];

  const gridIntervals: Array<{ value: GridInterval; label: string }> = [
    { value: 'auto', label: 'Auto' },
    { value: 100, label: '100m' },
    { value: 500, label: '500m' },
    { value: 1000, label: '1km' },
  ];

  return (
    <div
      className={`bg-white rounded-lg shadow-lg border border-gray-200 w-64 ${className}`}
    >
      {/* ─── Header ──────────────────────────────────────────────────── */}
      <div
        className="flex items-center justify-between px-4 py-2.5 border-b border-gray-200 cursor-pointer select-none"
        onClick={() => setIsCollapsed(!isCollapsed)}
      >
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded bg-[#1B3A5C] flex items-center justify-center text-white">
            <Layers className="w-4 h-4" />
          </div>
          <div>
            <div className="text-sm font-semibold text-gray-900">Layers</div>
            <div className="text-[10px] text-gray-500">
              {!hideBasemap ? `${activeBasemap === 'osm' ? 'Street Map' : activeBasemap === 'satellite' ? 'Satellite' : 'Blank'} · ` : ''}
              {customLayers.length} overlay{customLayers.length !== 1 ? 's' : ''}
            </div>
          </div>
        </div>
        <ChevronDown
          className={`w-4 h-4 text-gray-400 transition-transform ${isCollapsed ? '-rotate-90' : ''}`}
        />
      </div>

      {isCollapsed ? null : (
        <div className="divide-y divide-gray-100 max-h-[70vh] overflow-y-auto">
          {/* ─── Basemap Selector ──────────────────────────────────────── */}
          {!hideBasemap && (
          <div className="p-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
              <MapIcon className="w-3 h-3 inline mr-1" />
              Basemap
            </div>
            <div className="grid grid-cols-3 gap-1.5">
              {basemapOptions.map((opt) => (
                <button
                  key={opt.id}
                  onClick={() => switchBasemap(opt.id)}
                  className={`flex items-center gap-1.5 px-2.5 py-2 rounded-md text-xs font-medium transition-colors ${
                    activeBasemap === opt.id
                      ? 'bg-[#1B3A5C] text-white shadow-sm'
                      : 'bg-gray-50 text-gray-700 hover:bg-gray-100 border border-gray-200'
                  }`}
                >
                  {opt.icon}
                  <span>{opt.label}</span>
                </button>
              ))}
            </div>
          </div>
          )}

          {/* ─── Grid Overlay ──────────────────────────────────────────── */}
          <div className="p-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
              <Grid3X3 className="w-3 h-3 inline mr-1" />
              Kenya Grid Overlay
            </div>

            <div className="flex items-center justify-between mb-2">
              <button
                onClick={toggleGrid}
                className={`flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md transition-colors ${
                  gridEnabled
                    ? 'bg-[#1B3A5C] text-white shadow-sm'
                    : 'bg-gray-50 text-gray-700 hover:bg-gray-100 border border-gray-200'
                }`}
              >
                {gridEnabled ? <Eye className="w-3.5 h-3.5" /> : <EyeOff className="w-3.5 h-3.5" />}
                {gridEnabled ? 'Grid On' : 'Grid Off'}
              </button>

              <div className="flex items-center gap-1">
                {gridIntervals.map((gi) => (
                  <button
                    key={String(gi.value)}
                    onClick={() => changeGridInterval(gi.value)}
                    disabled={!gridEnabled}
                    className={`px-2 py-1 text-[10px] rounded transition-colors ${
                      gridInterval === gi.value
                        ? 'bg-[#1B3A5C] text-white'
                        : gridEnabled
                          ? 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                          : 'bg-gray-50 text-gray-300'
                    }`}
                  >
                    {gi.label}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* ─── Custom XYZ / Orthophoto ───────────────────────────────── */}
          <div className="p-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
              <Link2 className="w-3 h-3 inline mr-1" />
              Custom Orthophoto / XYZ Tiles
            </div>

            <div className="space-y-2">
              <input
                type="text"
                aria-label="Tile URL (XYZ template)" placeholder="https://.../{z}/{x}/{y}.png"
                value={customUrl}
                onChange={(e) => {
                  setCustomUrl(e.target.value);
                  setCustomError('');
                }}
                className="w-full px-2.5 py-1.5 text-xs border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none font-mono"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') addCustomLayer();
                }}
              />
              <input
                type="text"
                aria-label="Layer label" placeholder="Layer label (optional)"
                value={customLabel}
                onChange={(e) => setCustomLabel(e.target.value)}
                className="w-full px-2.5 py-1.5 text-xs border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') addCustomLayer();
                }}
              />
              <button
                onClick={addCustomLayer}
                disabled={!customUrl.trim() || isAdding}
                className="flex items-center justify-center gap-1.5 w-full px-3 py-1.5 text-xs bg-[#1B3A5C] text-white rounded-md hover:bg-[#142d49] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {isAdding ? (
                  <span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                  <Plus className="w-3.5 h-3.5" />
                )}
                Add Layer
              </button>
            </div>

            {customError && (
              <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded-md flex items-start gap-1.5">
                <AlertCircle className="w-3.5 h-3.5 text-red-600 mt-0.5 flex-shrink-0" />
                <span className="text-[10px] text-red-700">{customError}</span>
              </div>
            )}
          </div>

          {/* ─── WMS / GeoServer Overlay ───────────────────────────────── */}
          <div className="p-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
              <Link2 className="w-3 h-3 inline mr-1" />
              WMS / GeoServer Overlay
            </div>

            <div className="space-y-2">
              <input
                type="text"
                aria-label="WMS URL" placeholder="e.g. https://geoserver.example.com/wms"
                value={wmsUrl}
                onChange={(e) => {
                  setWmsUrl(e.target.value);
                  setWmsError('');
                }}
                className="w-full px-2.5 py-1.5 text-xs border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none font-mono"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') addWmsLayer();
                }}
              />
              <input
                type="text"
                aria-label="WMS layer name" placeholder="e.g. workspace:parcels"
                value={wmsLayerName}
                onChange={(e) => {
                  setWmsLayerName(e.target.value);
                  setWmsError('');
                }}
                className="w-full px-2.5 py-1.5 text-xs border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') addWmsLayer();
                }}
              />
              <input
                type="text"
                aria-label="WMS layer label" placeholder="Label (optional)"
                value={wmsLabel}
                onChange={(e) => setWmsLabel(e.target.value)}
                className="w-full px-2.5 py-1.5 text-xs border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') addWmsLayer();
                }}
              />
              <button
                onClick={addWmsLayer}
                disabled={!wmsUrl.trim() || !wmsLayerName.trim() || isAddingWms}
                className="flex items-center justify-center gap-1.5 w-full px-3 py-1.5 text-xs bg-[#1B3A5C] text-white rounded-md hover:bg-[#142d49] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {isAddingWms ? (
                  <span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                  <Plus className="w-3.5 h-3.5" />
                )}
                Add WMS Layer
              </button>
              <p className="text-[10px] text-gray-400">
                Paste a WMS endpoint URL and layer name from your GeoServer or MapServer to overlay parcels on the map.
              </p>
            </div>

            {wmsError && (
              <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded-md flex items-start gap-1.5">
                <AlertCircle className="w-3.5 h-3.5 text-red-600 mt-0.5 flex-shrink-0" />
                <span className="text-[10px] text-red-700">{wmsError}</span>
              </div>
            )}
          </div>

          {/* ─── Opacity Control ───────────────────────────────────────── */}
          <div className="px-3 py-2.5">
            <label htmlFor="lc-opacity" className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 flex items-center gap-1">
              <SlidersHorizontal className="w-3 h-3" />
              Overlay Opacity
            </label>
            <div className="flex items-center gap-2">
              <input id="lc-opacity"
                type="range"
                min={0}
                max={100}
                value={overlayOpacity}
                onChange={(e) => setOverlayOpacity(parseInt(e.target.value))}
                className="flex-1 h-1.5 bg-gray-200 rounded-full appearance-none cursor-pointer accent-[#1B3A5C]"
              />
              <span className="text-xs font-mono text-gray-600 w-9 text-right">
                {overlayOpacity}%
              </span>
            </div>
          </div>

          {/* ─── Active Layers List ────────────────────────────────────── */}
          <div className="px-3 pb-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
              Active Layers
            </div>

            <div className="space-y-1">
              {/* Basemap entry */}
              {!hideBasemap && (
              <div className="flex items-center justify-between px-2.5 py-1.5 bg-gray-50 rounded-md text-xs">
                <div className="flex items-center gap-2">
                  <Eye className="w-3.5 h-3.5 text-green-600" />
                  <span className="font-medium text-gray-700">
                    {activeBasemap === 'osm' ? 'Street Map' : activeBasemap === 'satellite' ? 'Satellite' : 'Blank'}
                  </span>
                </div>
                <span className="text-[10px] text-gray-400">basemap</span>
              </div>
              )}

              {/* Grid entry */}
              <div className="flex items-center justify-between px-2.5 py-1.5 bg-gray-50 rounded-md text-xs">
                <div className="flex items-center gap-2">
                  {gridEnabled ? (
                    <Eye className="w-3.5 h-3.5 text-green-600" />
                  ) : (
                    <EyeOff className="w-3.5 h-3.5 text-gray-400" />
                  )}
                  <span className={`font-medium ${gridEnabled ? 'text-gray-700' : 'text-gray-400'}`}>
                    Kenya Grid
                  </span>
                </div>
                <span className="text-[10px] text-gray-400">
                  {gridInterval === 'auto' ? 'auto' : gridInterval >= 1000 ? `${gridInterval / 1000}km` : `${gridInterval}m`}
                </span>
              </div>

              {/* Custom layer entries */}
              {customLayers.map((cl) => (
                <div
                  key={cl.id}
                  className="flex items-center justify-between px-2.5 py-1.5 bg-gray-50 rounded-md text-xs group"
                >
                  <button
                    onClick={() => toggleCustomLayerVisibility(cl.id)}
                    className="flex items-center gap-2 flex-1 min-w-0"
                  >
                    {tileLayerVisibility[cl.id] !== false ? (
                      <Eye className="w-3.5 h-3.5 text-green-600 flex-shrink-0" />
                    ) : (
                      <EyeOff className="w-3.5 h-3.5 text-gray-400 flex-shrink-0" />
                    )}
                    <span className="font-medium text-gray-700 truncate">{cl.label}</span>
                  </button>
                  <button
                    onClick={() => removeCustomLayer(cl.id)}
                    className="p-0.5 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                    title="Remove layer"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              ))}

              {customLayers.length === 0 && (
                <div className="text-[10px] text-gray-400 text-center py-2">
                  No custom layers added
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Ruler, Square, Compass, MapPin, X, Check } from 'lucide-react';
import { useMeasurement, type MeasurementMode } from '@/hooks/useMeasurement';
import type Map from 'ol/Map';

interface MeasurementToolProps {
  map: Map | null;
}

export function MeasurementTool({ map }: MeasurementToolProps) {
  const {
    state,
    startMeasurement,
    finishAreaMeasurement,
    cancelMeasurement,
    clearMeasurement,
    getFormattedResult,
  } = useMeasurement(map);

  const [hoverTool, setHoverTool] = useState<MeasurementMode | null>(null);

  const tools: Array<{
    mode: MeasurementMode;
    icon: React.ReactNode;
    label: string;
    description: string;
  }> = [
    {
      mode: 'distance',
      icon: <Ruler className="w-5 h-5" />,
      label: 'Distance',
      description: 'Click two points to measure distance',
    },
    {
      mode: 'area',
      icon: <Square className="w-5 h-5" />,
      label: 'Area',
      description: 'Click points to draw polygon, then finish',
    },
    {
      mode: 'bearing',
      icon: <Compass className="w-5 h-5" />,
      label: 'Bearing',
      description: 'Click two points to measure bearing',
    },
    {
      mode: 'coordinate',
      icon: <MapPin className="w-5 h-5" />,
      label: 'Coordinate',
      description: 'Click to get coordinate',
    },
  ];

  const handleToolClick = (mode: MeasurementMode) => {
    if (state.isActive && state.mode !== mode) {
      cancelMeasurement();
    }
    startMeasurement(mode);
  };

  const result = getFormattedResult();

  return (
    <div className="bg-white rounded-lg shadow-lg border w-56">
      <div className="flex items-center border-b">
        {tools.map((tool) => (
          <button
            key={tool.mode}
            onClick={() => handleToolClick(tool.mode)}
            onMouseEnter={() => setHoverTool(tool.mode)}
            onMouseLeave={() => setHoverTool(null)}
            className={[
              'flex-1 p-2 flex flex-col items-center gap-1 transition-colors',
              state.mode === tool.mode && state.isActive
                ? 'bg-blue-600 text-white'
                : 'hover:bg-gray-100',
            ].join(' ')}
            title={tool.description}
          >
            {tool.icon}
            <span className="text-[10px]">{tool.label}</span>
          </button>
        ))}
      </div>

      {state.isActive && (
        <div className="px-3 py-2 bg-blue-50 text-xs text-blue-700">
          {state.mode === 'distance' && state.points.length === 0 && 'Click first point'}
          {state.mode === 'distance' && state.points.length === 1 && 'Click second point'}
          {state.mode === 'area' && state.points.length < 3 && `Click points (${state.points.length}/3 min)`}
          {state.mode === 'area' && state.points.length >= 3 && `${state.points.length} pts - Finish or add`}
          {state.mode === 'bearing' && state.points.length === 0 && 'Click first point'}
          {state.mode === 'bearing' && state.points.length === 1 && 'Click second point'}
          {state.mode === 'coordinate' && 'Click to get coordinate'}
        </div>
      )}

      {result && (
        <div className="px-4 py-3 border-t">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-[10px] text-gray-500 uppercase">{result.type}</div>
              <div className="text-base font-semibold font-mono">
                {result.formatted}
              </div>
            </div>
            <button
              onClick={clearMeasurement}
              className="p-1.5 hover:bg-gray-100 rounded"
              title="Clear"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {state.points.length > 0 && (
            <div className="mt-2 text-[10px] text-gray-500">
              {state.points.map((p, i) => (
                <div key={`${p}-${i}`}>Pt {i + 1}: E {p.easting.toFixed(0)} N {p.northing.toFixed(0)}</div>
              ))}
            </div>
          )}
        </div>
      )}

      {state.isActive && !result && (
        <div className="px-4 py-2 border-t">
          {state.mode === 'area' && state.points.length >= 3 ? (
            <button
              onClick={finishAreaMeasurement}
              className="w-full py-1.5 bg-green-600 text-white text-sm rounded flex items-center justify-center gap-1"
            >
              <Check className="w-4 h-4" />
              Finish
            </button>
          ) : (
            <button
              onClick={cancelMeasurement}
              className="w-full py-1.5 text-sm text-red-600 hover:bg-red-50 rounded"
            >
              Cancel
            </button>
          )}
        </div>
      )}
    </div>
  );
}

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  Download,
  X,
  MapPin,
  Loader2,
  CheckCircle2,
  AlertTriangle,
  Layers,
  ZoomIn,
  HardDrive,
} from 'lucide-react'
import { useMapContext } from '@/app/map/MapReactContext'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Slider } from '@/components/ui/slider'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Progress } from '@/components/ui/progress'
import {
  calculateTileCount,
  estimateStorageSize,
  downloadTilesForBounds,
  type DownloadProgress,
} from '@/lib/offline/tileCache'

// ─── Constants ──────────────────────────────────────────────────────────────

const TILE_SOURCES = [
  {
    id: 'osm',
    label: 'OpenStreetMap',
    url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
    type: 'osm' as const,
  },
  {
    id: 'esri-satellite',
    label: 'ESRI Satellite',
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    type: 'satellite' as const,
  },
] as const

type SourceType = 'osm' | 'satellite' | 'custom'

interface Bounds {
  minLat: number
  minLon: number
  maxLat: number
  maxLon: number
}

interface OfflineTileDownloaderProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Current map extent, if available — lets users use the current view as bounds */
  mapExtent?: Bounds | null
}

type DownloadState = 'idle' | 'estimating' | 'downloading' | 'complete' | 'error'

// ─── Helpers ────────────────────────────────────────────────────────────────

function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 B'
  const units = ['B', 'KB', 'MB', 'GB']
  const k = 1024
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  return `${(bytes / Math.pow(k, i)).toFixed(1)} ${units[i]}`
}

function formatNumber(n: number): string {
  return n.toLocaleString()
}

// ─── Component ──────────────────────────────────────────────────────────────

export function OfflineTileDownloader() {
  const {
    offlineDialogOpen: open,
    toggleOfflineDialog: onOpenChange,
    offlineMapExtent: mapExtent,
  } = useMapContext()
  // Source selection
  const [sourceType, setSourceType] = useState<string>('osm')
  const [customUrl, setCustomUrl] = useState('')
  const [customLabel, setCustomLabel] = useState('')

  // Bounds
  const [minLat, setMinLat] = useState('-1.5')
  const [maxLat, setMaxLat] = useState('-1.2')
  const [minLon, setMinLon] = useState('36.6')
  const [maxLon, setMaxLon] = useState('37.0')

  // Zoom
  const [zoomRange, setZoomRange] = useState([10, 15])

  // State
  const [downloadState, setDownloadState] = useState<DownloadState>('idle')
  const [estimate, setEstimate] = useState<{ tiles: number; sizeBytes: number } | null>(null)
  const [progress, setProgress] = useState<DownloadProgress | null>(null)
  const [errorMsg, setErrorMsg] = useState<string | null>(null)
  const abortRef = useRef<AbortController | null>(null)

  // Reset state when dialog opens
  useEffect(() => {
    if (open) {
      setDownloadState('idle')
      setEstimate(null)
      setProgress(null)
      setErrorMsg(null)
    }
  }, [open])

  // Fill bounds from map extent
  const useMapExtent = useCallback(() => {
    if (!mapExtent) return
    setMinLat(mapExtent.minLat.toFixed(6))
    setMaxLat(mapExtent.maxLat.toFixed(6))
    setMinLon(mapExtent.minLon.toFixed(6))
    setMaxLon(mapExtent.maxLon.toFixed(6))
  }, [mapExtent])

  // Get the current source config
  const getCurrentSource = useCallback(() => {
    if (sourceType === 'custom') {
      return {
        id: `custom-${customLabel || Date.now()}`,
        label: customLabel || 'Custom',
        url: customUrl,
        type: 'custom' as SourceType,
      }
    }
    const preset = TILE_SOURCES.find((s) => s.id === sourceType)
    return preset
      ? { id: preset.id, label: preset.label, url: preset.url, type: preset.type as SourceType }
      : { id: 'osm', label: 'OpenStreetMap', url: TILE_SOURCES[0].url, type: 'osm' as SourceType }
  }, [sourceType, customUrl, customLabel])

  // Estimate tiles
  const estimateTiles = useCallback(() => {
    const bounds: Bounds = {
      minLat: parseFloat(minLat),
      maxLat: parseFloat(maxLat),
      minLon: parseFloat(minLon),
      maxLon: parseFloat(maxLon),
    }

    if (isNaN(bounds.minLat) || isNaN(bounds.maxLat) || isNaN(bounds.minLon) || isNaN(bounds.maxLon)) {
      setErrorMsg('Invalid coordinates. Please enter valid latitude/longitude values.')
      return
    }

    if (bounds.minLat >= bounds.maxLat || bounds.minLon >= bounds.maxLon) {
      setErrorMsg('Invalid bounds: min values must be less than max values.')
      return
    }

    const source = getCurrentSource()
    const { total } = calculateTileCount(bounds, zoomRange[0], zoomRange[1])
    const sizeBytes = estimateStorageSize(total, source.type)

    if (total > 500000) {
      setErrorMsg(`Estimated ${formatNumber(total)} tiles exceeds the 500K safety limit. Please reduce the area or zoom range.`)
      setEstimate(null)
      return
    }

    setErrorMsg(null)
    setEstimate({ tiles: total, sizeBytes })
  }, [minLat, maxLat, minLon, maxLon, zoomRange, getCurrentSource])

  // Start download
  const startDownload = useCallback(async () => {
    const bounds: Bounds = {
      minLat: parseFloat(minLat),
      maxLat: parseFloat(maxLat),
      minLon: parseFloat(minLon),
      maxLon: parseFloat(maxLon),
    }

    if (isNaN(bounds.minLat) || isNaN(bounds.maxLat) || isNaN(bounds.minLon) || isNaN(bounds.maxLon)) {
      setErrorMsg('Invalid coordinates.')
      return
    }

    const source = getCurrentSource()

    if (sourceType === 'custom') {
      const hasPlaceholders = /\{z\}/.test(source.url) && /\{x\}/.test(source.url) && /\{y\}/.test(source.url)
      if (!hasPlaceholders) {
        setErrorMsg('Custom URL must contain {z}, {x}, and {y} placeholders.')
        return
      }
    }

    const abortController = new AbortController()
    abortRef.current = abortController

    setDownloadState('downloading')
    setErrorMsg(null)
    setProgress(null)

    try {
      const result = await downloadTilesForBounds(
        source.id,
        source.url,
        bounds,
        zoomRange[0],
        zoomRange[1],
        source.type,
        (p: DownloadProgress) => setProgress({ ...p }),
        abortController.signal,
      )

      if (!abortController.signal.aborted) {
        setProgress(result)
        setDownloadState('complete')
      }
    } catch (err: unknown) {
      if (((err as Error)?.name) !== 'AbortError') {
        setErrorMsg((err as Error).message ?? 'Download failed')
        setDownloadState('error')
      }
    }
  }, [minLat, maxLat, minLon, maxLon, zoomRange, sourceType, getCurrentSource])

  // Cancel download
  const cancelDownload = useCallback(() => {
    abortRef.current?.abort()
    setDownloadState('idle')
  }, [])

  // Close dialog
  const handleClose = useCallback(() => {
    if (downloadState === 'downloading') {
      cancelDownload()
    }
    onOpenChange(false)
  }, [downloadState, cancelDownload, onOpenChange])

  const isDownloading = downloadState === 'downloading'
  const isComplete = downloadState === 'complete'

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="bg-[var(--bg-card)] border-[var(--border-color)] text-[var(--text-primary)] sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-[var(--text-primary)]">
            <Download className="w-5 h-5 text-[var(--accent)]" />
            Download Offline Tiles
          </DialogTitle>
          <DialogDescription className="text-[var(--text-muted)]">
            Select a tile source, area, and zoom range to cache map tiles for offline use.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-2">
          {/* ─── Tile Source ─────────────────────────────────────────── */}
          <section>
            <div className="block text-sm font-medium text-[var(--text-secondary)] mb-2">
              <Layers className="w-4 h-4 inline mr-1.5" />
              Tile Source
            </div>
            <Select value={sourceType} onValueChange={setSourceType} disabled={isDownloading}>
              <SelectTrigger className="w-full bg-[var(--bg-secondary)] border-[var(--border-color)] text-[var(--text-primary)]">
                <SelectValue placeholder="Select tile source" />
              </SelectTrigger>
              <SelectContent className="bg-[var(--bg-secondary)] border-[var(--border-color)]">
                {TILE_SOURCES.map((s) => (
                  <SelectItem key={s.id} value={s.id}>
                    {s.label}
                  </SelectItem>
                ))}
                <SelectItem value="custom">Custom XYZ URL</SelectItem>
              </SelectContent>
            </Select>

            {sourceType === 'custom' && (
              <div className="mt-3 space-y-3">
                <Input
                  placeholder="Label (e.g. Kenya Topo)"
                  value={customLabel}
                  onChange={(e) => setCustomLabel(e.target.value)}
                  disabled={isDownloading}
                  className="bg-[var(--bg-secondary)] border-[var(--border-color)] text-[var(--text-primary)] placeholder-[var(--text-muted)]"
                />
                <Input
                  placeholder="https://tiles.example.com/{z}/{x}/{y}.png"
                  value={customUrl}
                  onChange={(e) => setCustomUrl(e.target.value)}
                  disabled={isDownloading}
                  className="bg-[var(--bg-secondary)] border-[var(--border-color)] text-[var(--text-primary)] placeholder-[var(--text-muted)] font-mono text-xs"
                />
              </div>
            )}
          </section>

          {/* ─── Bounding Box ────────────────────────────────────────── */}
          <section>
            <div className="flex items-center justify-between mb-2">
              <div className="text-sm font-medium text-[var(--text-secondary)]">
                <MapPin className="w-4 h-4 inline mr-1.5" />
                Bounding Box (WGS84)
              </div>
              {mapExtent && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={useMapExtent}
                  disabled={isDownloading}
                  className="text-xs border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
                >
                  Use current map view
                </Button>
              )}
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label htmlFor="otd-min-lat" className="block text-xs text-[var(--text-muted)] mb-1">Min Latitude</label>
                <Input
                  id="otd-min-lat"
                  type="number"
                  step="0.000001"
                  value={minLat}
                  onChange={(e) => setMinLat(e.target.value)}
                  disabled={isDownloading}
                  className="bg-[var(--bg-secondary)] border-[var(--border-color)] text-[var(--text-primary)] font-mono text-sm"
                />
              </div>
              <div>
                <label htmlFor="otd-max-lat" className="block text-xs text-[var(--text-muted)] mb-1">Max Latitude</label>
                <Input
                  id="otd-max-lat"
                  type="number"
                  step="0.000001"
                  value={maxLat}
                  onChange={(e) => setMaxLat(e.target.value)}
                  disabled={isDownloading}
                  className="bg-[var(--bg-secondary)] border-[var(--border-color)] text-[var(--text-primary)] font-mono text-sm"
                />
              </div>
              <div>
                <label htmlFor="otd-min-lon" className="block text-xs text-[var(--text-muted)] mb-1">Min Longitude</label>
                <Input
                  id="otd-min-lon"
                  type="number"
                  step="0.000001"
                  value={minLon}
                  onChange={(e) => setMinLon(e.target.value)}
                  disabled={isDownloading}
                  className="bg-[var(--bg-secondary)] border-[var(--border-color)] text-[var(--text-primary)] font-mono text-sm"
                />
              </div>
              <div>
                <label htmlFor="otd-max-lon" className="block text-xs text-[var(--text-muted)] mb-1">Max Longitude</label>
                <Input
                  id="otd-max-lon"
                  type="number"
                  step="0.000001"
                  value={maxLon}
                  onChange={(e) => setMaxLon(e.target.value)}
                  disabled={isDownloading}
                  className="bg-[var(--bg-secondary)] border-[var(--border-color)] text-[var(--text-primary)] font-mono text-sm"
                />
              </div>
            </div>
          </section>

          {/* ─── Zoom Range ──────────────────────────────────────────── */}
          <section>
            <div className="block text-sm font-medium text-[var(--text-secondary)] mb-2">
              <ZoomIn className="w-4 h-4 inline mr-1.5" />
              Zoom Range: {zoomRange[0]} – {zoomRange[1]}
            </div>
            <Slider
              value={zoomRange}
              onValueChange={setZoomRange}
              min={0}
              max={20}
              step={1}
              disabled={isDownloading}
              className="py-2"
            />
            <div className="flex justify-between text-xs text-[var(--text-muted)] mt-1">
              <span>0 (world)</span>
              <span>20 (street)</span>
            </div>
          </section>

          {/* ─── Error Message ───────────────────────────────────────── */}
          {errorMsg && (
            <div className="flex items-start gap-2 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-red-400 text-sm">
              <AlertTriangle className="w-4 h-4 mt-0.5 shrink-0" />
              {errorMsg}
            </div>
          )}

          {/* ─── Estimate & Download Button ──────────────────────────── */}
          {!isComplete && !isDownloading && (
            <div className="flex flex-col gap-4">
              <Button
                variant="outline"
                onClick={estimateTiles}
                disabled={isDownloading}
                className="w-full border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)] hover:border-[var(--accent)]"
              >
                <HardDrive className="w-4 h-4 mr-2" />
                Estimate Tile Count
              </Button>

              {estimate && (
                <div className="rounded-lg bg-[var(--bg-secondary)] border border-[var(--border-color)] p-4 space-y-2">
                  <div className="flex justify-between text-sm">
                    <span className="text-[var(--text-muted)]">Estimated tiles</span>
                    <span className="text-[var(--text-primary)] font-mono font-semibold">
                      {formatNumber(estimate.tiles)}
                    </span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-[var(--text-muted)]">Estimated size</span>
                    <span className="text-[var(--text-primary)] font-mono font-semibold">
                      {formatBytes(estimate.sizeBytes)}
                    </span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-[var(--text-muted)]">Source</span>
                    <span className="text-[var(--text-primary)]">
                      {getCurrentSource().label}
                    </span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-[var(--text-muted)]">Zoom levels</span>
                    <span className="text-[var(--text-primary)] font-mono">
                      {zoomRange[0]} – {zoomRange[1]}
                    </span>
                  </div>
                </div>
              )}

              {estimate && (
                <Button
                  onClick={startDownload}
                  disabled={isDownloading}
                  className="w-full bg-[var(--accent)] text-black font-semibold hover:brightness-110"
                >
                  <Download className="w-4 h-4 mr-2" />
                  Download {formatNumber(estimate.tiles)} Tiles
                </Button>
              )}
            </div>
          )}

          {/* ─── Download Progress ───────────────────────────────────── */}
          {isDownloading && progress && (
            <div className="space-y-4">
              <div className="space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--text-muted)]">
                    Downloading zoom level {progress.currentZoom}…
                  </span>
                  <span className="text-[var(--text-primary)] font-mono">
                    {Math.round((progress.downloaded / progress.total) * 100)}%
                  </span>
                </div>
                <Progress
                  value={Math.round((progress.downloaded / progress.total) * 100)}
                  className="h-2 bg-[var(--bg-secondary)]"
                />
              </div>

              <div className="grid grid-cols-3 gap-3 text-center">
                <div className="rounded-lg bg-[var(--bg-secondary)] border border-[var(--border-color)] p-3">
                  <div className="text-lg font-bold text-[var(--accent)] font-mono">
                    {formatNumber(progress.downloaded)}
                  </div>
                  <div className="text-xs text-[var(--text-muted)]">Downloaded</div>
                </div>
                <div className="rounded-lg bg-[var(--bg-secondary)] border border-[var(--border-color)] p-3">
                  <div className="text-lg font-bold text-[var(--text-primary)] font-mono">
                    {formatNumber(progress.skipped)}
                  </div>
                  <div className="text-xs text-[var(--text-muted)]">Cached</div>
                </div>
                <div className="rounded-lg bg-[var(--bg-secondary)] border border-[var(--border-color)] p-3">
                  <div className="text-lg font-bold text-[var(--text-primary)] font-mono">
                    {formatBytes(progress.bytesDownloaded)}
                  </div>
                  <div className="text-xs text-[var(--text-muted)]">Size</div>
                </div>
              </div>

              {progress.failed > 0 && (
                <p className="text-xs text-yellow-500 text-center">
                  {progress.failed} tile{progress.failed !== 1 ? 's' : ''} failed to download
                </p>
              )}
            </div>
          )}

          {isDownloading && !progress && (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-[var(--accent)]" />
              <span className="ml-3 text-sm text-[var(--text-muted)]">Starting download…</span>
            </div>
          )}

          {/* ─── Complete Summary ────────────────────────────────────── */}
          {isComplete && progress && (
            <div className="space-y-4">
              <div className="flex items-center gap-2 text-green-400">
                <CheckCircle2 className="w-5 h-5" />
                <span className="font-semibold">Download Complete</span>
              </div>

              <div className="rounded-lg bg-[var(--bg-secondary)] border border-[var(--border-color)] p-4 space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--text-muted)]">Tiles downloaded</span>
                  <span className="text-[var(--text-primary)] font-mono font-semibold">
                    {formatNumber(progress.downloaded)}
                  </span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--text-muted)]">Tiles already cached</span>
                  <span className="text-[var(--text-primary)] font-mono">
                    {formatNumber(progress.skipped)}
                  </span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--text-muted)]">Failed</span>
                  <span className="text-[var(--text-primary)] font-mono">
                    {formatNumber(progress.failed)}
                  </span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--text-muted)]">Total data downloaded</span>
                  <span className="text-[var(--text-primary)] font-mono font-semibold">
                    {formatBytes(progress.bytesDownloaded)}
                  </span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--text-muted)]">Source</span>
                  <span className="text-[var(--text-primary)]">
                    {getCurrentSource().label}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>

        <DialogFooter className="gap-2">
          {isDownloading ? (
            <Button
              variant="destructive"
              onClick={cancelDownload}
              className="bg-red-600 hover:bg-red-500 text-white"
            >
              <X className="w-4 h-4 mr-2" />
              Cancel Download
            </Button>
          ) : isComplete ? (
            <Button
              onClick={() => onOpenChange(false)}
              className="bg-[var(--accent)] text-black font-semibold hover:brightness-110"
            >
              Done
            </Button>
          ) : null}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import {
  Trash2,
  HardDrive,
  RefreshCw,
  AlertTriangle,
  Layers,
  Clock,
  Database,
  WifiOff,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Progress } from '@/components/ui/progress'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import {
  listCachedSources,
  deleteCachedTiles,
  clearAllTileCache,
  type CachedSourceInfo,
} from '@/lib/offline/tileCache'

// ─── Helpers ────────────────────────────────────────────────────────────────

function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 B'
  const units = ['B', 'KB', 'MB', 'GB']
  const k = 1024
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  return `${(bytes / Math.pow(k, i)).toFixed(1)} ${units[i]}`
}

function formatDate(timestamp: number | null): string {
  if (!timestamp) return '—'
  return new Date(timestamp).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

function getSourceIcon(sourceId: string): string {
  if (sourceId.includes('osm') || sourceId.includes('openstreetmap')) return '[Map]'
  if (sourceId.includes('satellite') || sourceId.includes('esri')) return '[Sat]'
  return ''
}

// ─── Component ──────────────────────────────────────────────────────────────

export function OfflineTileManager() {
  const [sources, setSources] = useState<CachedSourceInfo[]>([])
  const [loading, setLoading] = useState(true)
  const [deleting, setDeleting] = useState<string | null>(null)
  const [clearing, setClearing] = useState(false)

  const refreshSources = useCallback(async () => {
    setLoading(true)
    try {
      const data = await listCachedSources()
      setSources(data)
    } catch (err) {
      console.error('Failed to list cached sources:', err)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    refreshSources()
  }, [refreshSources])

  const handleDeleteSource = useCallback(
    async (sourceId: string) => {
      setDeleting(sourceId)
      try {
        await deleteCachedTiles(sourceId)
        await refreshSources()
      } catch (err) {
        console.error('Failed to delete source:', err)
      } finally {
        setDeleting(null)
      }
    },
    [refreshSources],
  )

  const handleClearAll = useCallback(async () => {
    setClearing(true)
    try {
      await clearAllTileCache()
      await refreshSources()
    } catch (err) {
      console.error('Failed to clear cache:', err)
    } finally {
      setClearing(false)
    }
  }, [refreshSources])

  const totalSizeBytes = sources.reduce((sum, s) => sum + s.stats.sizeBytes, 0)
  const totalTiles = sources.reduce((sum, s) => sum + s.stats.count, 0)

  // Rough storage quota (most browsers allow ~50MB–unlimited for persistent storage)
  const estimatedQuota = 500 * 1024 * 1024 // 500 MB estimate
  const usagePercent = Math.min(100, Math.round((totalSizeBytes / estimatedQuota) * 100))

  return (
    <div className="space-y-6">
      {/* ─── Storage Overview ──────────────────────────────────────── */}
      <div className="rounded-xl bg-[var(--bg-secondary)] border border-[var(--border-color)] p-5">
        <div className="flex items-center gap-3 mb-4">
          <div className="w-10 h-10 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <HardDrive className="w-5 h-5 text-[var(--accent)]" />
          </div>
          <div>
            <h3 className="font-semibold text-[var(--text-primary)]">Offline Storage</h3>
            <p className="text-xs text-[var(--text-muted)]">
              {formatBytes(totalSizeBytes)} used across {sources.length} source{sources.length !== 1 ? 's' : ''}
            </p>
          </div>
        </div>

        <div className="space-y-1.5">
          <div className="flex justify-between text-xs text-[var(--text-muted)]">
            <span>{formatBytes(totalSizeBytes)} used</span>
            <span>~{formatBytes(estimatedQuota)} estimated quota</span>
          </div>
          <Progress
            value={usagePercent}
            className="h-2 bg-[var(--bg-primary)]"
          />
        </div>

        <div className="grid grid-cols-2 gap-3 mt-4">
          <div className="rounded-lg bg-[var(--bg-primary)] border border-[var(--border-color)] p-3 text-center">
            <div className="text-xl font-bold font-mono text-[var(--accent)]">
              {totalTiles.toLocaleString()}
            </div>
            <div className="text-xs text-[var(--text-muted)]">Total Tiles</div>
          </div>
          <div className="rounded-lg bg-[var(--bg-primary)] border border-[var(--border-color)] p-3 text-center">
            <div className="text-xl font-bold font-mono text-[var(--text-primary)]">
              {sources.length}
            </div>
            <div className="text-xs text-[var(--text-muted)]">Sources</div>
          </div>
        </div>
      </div>

      {/* ─── Action Buttons ────────────────────────────────────────── */}
      <div className="flex items-center gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={refreshSources}
          disabled={loading}
          className="border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
        >
          <RefreshCw className={`w-3.5 h-3.5 mr-1.5 ${loading ? 'animate-spin' : ''}`} />
          Refresh
        </Button>

        {sources.length > 0 && (
          <AlertDialog>
            <AlertDialogTrigger asChild>
              <Button
                variant="outline"
                size="sm"
                disabled={clearing}
                className="border-red-500/30 bg-red-500/5 text-red-400 hover:bg-red-500/10 hover:text-red-300"
              >
                <Trash2 className="w-3.5 h-3.5 mr-1.5" />
                Clear All
              </Button>
            </AlertDialogTrigger>
            <AlertDialogContent className="bg-[var(--bg-card)] border-[var(--border-color)] text-[var(--text-primary)]">
              <AlertDialogHeader>
                <AlertDialogTitle className="flex items-center gap-2">
                  <AlertTriangle className="w-5 h-5 text-red-400" />
                  Clear All Cached Tiles?
                </AlertDialogTitle>
                <AlertDialogDescription className="text-[var(--text-muted)]">
                  This will permanently delete all {totalTiles.toLocaleString()} cached tiles
                  ({formatBytes(totalSizeBytes)}) from {sources.length} source{sources.length !== 1 ? 's' : ''}.
                  This action cannot be undone.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel className="border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)]">
                  Cancel
                </AlertDialogCancel>
                <AlertDialogAction
                  onClick={handleClearAll}
                  className="bg-red-600 text-white hover:bg-red-500"
                >
                  {clearing ? 'Clearing…' : 'Clear All'}
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        )}
      </div>

      {/* ─── Source List ───────────────────────────────────────────── */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="w-5 h-5 animate-spin text-[var(--accent)]" />
          <span className="ml-3 text-sm text-[var(--text-muted)]">Loading cache info…</span>
        </div>
      ) : sources.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-12 text-center">
          <div className="w-16 h-16 rounded-full bg-[var(--bg-secondary)] border border-[var(--border-color)] flex items-center justify-center mb-4">
            <WifiOff className="w-8 h-8 text-[var(--text-muted)]" />
          </div>
          <p className="text-[var(--text-secondary)] font-medium mb-1">No offline tiles cached</p>
          <p className="text-sm text-[var(--text-muted)] max-w-xs">
            Download map tiles for offline use by selecting an area and zoom range.
          </p>
        </div>
      ) : (
        <div className="space-y-3 max-h-96 overflow-y-auto pr-1">
          {sources.map((source) => (
            <div
              key={source.sourceId}
              className="group rounded-xl bg-[var(--bg-secondary)] border border-[var(--border-color)] p-4 transition-all hover:border-[var(--accent)]/20"
            >
              <div className="flex items-start justify-between gap-3">
                <div className="flex items-start gap-3 min-w-0">
                  <span className="text-xl mt-0.5">{getSourceIcon(source.sourceId)}</span>
                  <div className="min-w-0">
                    <h4 className="font-medium text-[var(--text-primary)] truncate">
                      {source.sourceId}
                    </h4>
                    <div className="flex flex-wrap gap-x-4 gap-y-1 mt-1.5 text-xs text-[var(--text-muted)]">
                      <span className="flex items-center gap-1">
                        <Layers className="w-3 h-3" />
                        {source.stats.count.toLocaleString()} tiles
                      </span>
                      <span className="flex items-center gap-1">
                        <Database className="w-3 h-3" />
                        {formatBytes(source.stats.sizeBytes)}
                      </span>
                      <span className="flex items-center gap-1">
                        <Clock className="w-3 h-3" />
                        {formatDate(source.stats.newestTimestamp)}
                      </span>
                    </div>
                  </div>
                </div>

                <AlertDialog>
                  <AlertDialogTrigger asChild>
                    <Button
                      variant="ghost"
                      size="icon"
                      disabled={deleting === source.sourceId}
                      className="shrink-0 opacity-0 group-hover:opacity-100 transition-opacity text-[var(--text-muted)] hover:text-red-400 hover:bg-red-500/10 h-8 w-8"
                    >
                      {deleting === source.sourceId ? (
                        <RefreshCw className="w-4 h-4 animate-spin" />
                      ) : (
                        <Trash2 className="w-4 h-4" />
                      )}
                    </Button>
                  </AlertDialogTrigger>
                  <AlertDialogContent className="bg-[var(--bg-card)] border-[var(--border-color)] text-[var(--text-primary)]">
                    <AlertDialogHeader>
                      <AlertDialogTitle>Delete &ldquo;{source.sourceId}&rdquo;?</AlertDialogTitle>
                      <AlertDialogDescription className="text-[var(--text-muted)]">
                        This will delete {source.stats.count.toLocaleString()} cached tiles
                        ({formatBytes(source.stats.sizeBytes)}). This cannot be undone.
                      </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                      <AlertDialogCancel className="border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)]">
                        Cancel
                      </AlertDialogCancel>
                      <AlertDialogAction
                        onClick={() => handleDeleteSource(source.sourceId)}
                        className="bg-red-600 text-white hover:bg-red-500"
                      >
                        Delete
                      </AlertDialogAction>
                    </AlertDialogFooter>
                  </AlertDialogContent>
                </AlertDialog>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client'

import { useEffect, useRef, useState, useCallback, useMemo } from 'react'
import Konva from 'konva'
import { shoelaceArea } from '@/lib/engine/area'
import { formatBearingDegMinSec, bearingFromDelta, distance } from '@/lib/reports/surveyPlan/geometry'

export interface ParcelVertex {
  id: string
  label: string
  easting: number
  northing: number
}

export type DrawingMode = 'draw' | 'edit' | 'select'

export interface ParcelCanvasProps {
  width?: number
  height?: number
  /** Initial parcels (pre-defined boundaries to show as reference) */
  existingParcels?: Array<{
    id: string
    vertices: ParcelVertex[]
    fill?: string
    stroke?: string
  }>
  /** Currently selected parcel being edited */
  activeParcel?: ParcelVertex[]
  /** Drawing mode */
  mode?: DrawingMode
  /** CRS origin for coordinate display */
  originEasting?: number
  originNorthing?: number
  /** Called when the user finishes drawing (closes polygon or clicks Done) */
  onParcelComplete?: (vertices: ParcelVertex[]) => void
  /** Called on every vertex add */
  onVerticesChange?: (vertices: ParcelVertex[]) => void
  /** Whether to show live area while drawing */
  showLiveArea?: boolean
  /** Whether to show bearing/distance labels on legs */
  showLegAnnotations?: boolean
  className?: string
}

interface CanvasTransform {
  scale: number
  originE: number
  originN: number
}

function computeTransform(
  vertices: ParcelVertex[],
  canvasWidth: number,
  canvasHeight: number,
  padding = 60
): CanvasTransform {
  if (vertices.length === 0) {
    return { scale: 1, originE: 0, originN: 0 }
  }

  const eastings = vertices.map(v => v.easting)
  const northings = vertices.map(v => v.northing)

  const minE = Math.min(...eastings)
  const maxE = Math.max(...eastings)
  const minN = Math.min(...northings)
  const maxN = Math.max(...northings)

  const rangeE = maxE - minE || 1
  const rangeN = maxN - minN || 1

  const availW = canvasWidth - padding * 2
  const availH = canvasHeight - padding * 2

  const scale = Math.min(availW / rangeE, availH / rangeN, 50)

  const originE = minE - (availW / scale - rangeE) / 2 - padding / scale
  const originN = maxN + (availH / scale - rangeN) / 2 + padding / scale

  return { scale, originE, originN }
}

function w2c(
  e: number,
  n: number,
  t: CanvasTransform,
  canvasHeight: number
): { x: number; y: number } {
  return {
    x: (e - t.originE) * t.scale,
    y: canvasHeight - (n - t.originN) * t.scale,
  }
}

const BEACON_RADIUS = 6
const BEACON_COLOR = '#E63946'
const VERTEX_RADIUS = 5
const VERTEX_COLOR = '#1B3A5C'
const EDGE_COLOR = '#1B3A5C'
const PREVIEW_EDGE_COLOR = '#6BA3D6'
const AREA_BOX_COLOR = '#F0F4F8'
const AREA_TEXT_COLOR = '#1B3A5C'

function formatArea(sqM: number): string {
  if (sqM >= 10000) return `${(sqM / 10000).toFixed(4)} Ha`
  if (sqM >= 1) return `${sqM.toFixed(2)} m²`
  return `${(sqM * 10000).toFixed(4)} m²`
}

export default function ParcelCanvas({
  width = 800,
  height = 600,
  existingParcels = [],
  activeParcel = [],
  mode = 'draw',
  originEasting = 0,
  originNorthing = 0,
  onParcelComplete,
  onVerticesChange,
  showLiveArea = true,
  showLegAnnotations = true,
  className = '',
}: ParcelCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const stageRef = useRef<Konva.Stage | null>(null)
  const layerRef = useRef<Konva.Layer | null>(null)

  const [vertices, setVertices] = useState<ParcelVertex[]>(activeParcel)
  const [hoveredVertex, setHoveredVertex] = useState<string | null>(null)
  const [selectedVertex, setSelectedVertex] = useState<string | null>(null)
  const [mouseWorld, setMouseWorld] = useState<{ e: number; n: number } | null>(null)

  const t = useMemo(
    () => computeTransform(vertices, width, height),
    [vertices, width, height]
  )

  const currentArea = useMemo(() => {
    if (vertices.length < 3) return 0
    return shoelaceArea(vertices.map(v => ({ easting: v.easting, northing: v.northing })))
  }, [vertices])

  const isClosed = vertices.length >= 3

  const legData = useMemo(() => {
    if (vertices.length < 2) return []
    const legs: Array<{
      from: ParcelVertex
      to: ParcelVertex
      bearing: string
      distance: number
      midX: number
      midY: number
    }> = []

    const pts = isClosed ? vertices : vertices
    for (let i = 0; i < pts.length; i++) {
      const a = pts[i]
      const b = pts[(i + 1) % pts.length]
      if (isClosed === false && i === pts.length - 1) break
      const bearing = bearingFromDelta(b.easting - a.easting, b.northing - a.northing)
      const dist = distance(a.easting, a.northing, b.easting, b.northing)
      const cA = w2c(a.easting, a.northing, t, height)
      const cB = w2c(b.easting, b.northing, t, height)
      legs.push({
        from: a,
        to: b,
        bearing: formatBearingDegMinSec(bearing),
        distance: dist,
        midX: (cA.x + cB.x) / 2,
        midY: (cA.y + cB.y) / 2,
      })
    }
    return legs
  }, [vertices, isClosed, t, height])

  const initStage = useCallback(() => {
    if (!containerRef.current) return

    const existing = containerRef.current.querySelector('.konva-container')
    if (existing) existing.remove()

    const stage = new Konva.Stage({
      container: containerRef.current,
      width,
      height,
    })
    stageRef.current = stage

    const layer = new Konva.Layer()
    stage.add(layer)
    layerRef.current = layer

    stage.on('mousemove', () => {
      const pos = stage.getPointerPosition()
      if (!pos) return
      const e = pos.x / t.scale + t.originE
      const n = (height - pos.y) / t.scale + t.originN
      setMouseWorld({ e, n })
    })

    stage.on('click', (e) => {
      if (mode !== 'draw') return

      const pos = stage.getPointerPosition()
      if (!pos) return

      const wE = pos.x / t.scale + t.originE
      const wN = (height - pos.y) / t.scale + t.originN

      const newVertex: ParcelVertex = {
        id: `v_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
        label: `P${vertices.length + 1}`,
        easting: Math.round(wE * 1000) / 1000,
        northing: Math.round(wN * 1000) / 1000,
      }

      const next = [...vertices, newVertex]
      setVertices(next)
      onVerticesChange?.(next)
    })

    return () => stage.destroy()
  }, [width, height, mode, t, vertices, onVerticesChange])

  useEffect(() => {
    const destroy = initStage()
    return () => { destroy?.() }
  }, [initStage])

  const draw = useCallback(() => {
    const layer = layerRef.current
    const stage = stageRef.current
    if (!layer || !stage) return

    layer.destroyChildren()

    layer.add(
      new Konva.Rect({
        x: 0,
        y: 0,
        width,
        height,
        fill: '#FAFCFF',
      })
    )

    if (mode === 'draw' && mouseWorld) {
      const mc = w2c(mouseWorld.e, mouseWorld.n, t, height)
      layer.add(
        new Konva.Circle({
          x: mc.x,
          y: mc.y,
          radius: 4,
          fill: PREVIEW_EDGE_COLOR,
          opacity: 0.6,
          dash: [3, 3],
        })
      )
    }

    for (const parcel of existingParcels) {
      if (parcel.vertices.length < 2) continue
      const pts = parcel.vertices.map(v => w2c(v.easting, v.northing, t, height))
      const flatPts = pts.flatMap(p => [p.x, p.y])

      const poly = new Konva.Line({
        points: flatPts,
        fill: parcel.fill || '#e8f4fd',
        stroke: parcel.stroke || '#94c3d9',
        strokeWidth: 1.5,
        closed: true,
        opacity: 0.7,
      })
      layer.add(poly)
    }

    if (vertices.length >= 2) {
      const pts = vertices.map(v => w2c(v.easting, v.northing, t, height))
      const flatPts = pts.flatMap(p => [p.x, p.y])

      layer.add(
        new Konva.Line({
          points: flatPts,
          stroke: isClosed ? EDGE_COLOR : PREVIEW_EDGE_COLOR,
          strokeWidth: isClosed ? 2 : 1.5,
          dash: isClosed ? [] : [6, 3],
          closed: isClosed,
        })
      )
    }

    if (mode === 'draw' && vertices.length >= 1) {
      const pts = vertices.map(v => w2c(v.easting, v.northing, t, height))
      const flatPts = pts.flatMap(p => [p.x, p.y])

      const previewLine: number[] = []
      const last = pts[pts.length - 1]
      if (!isClosed && mouseWorld) {
        previewLine.push(last.x, last.y)
        const mp = w2c(mouseWorld.e, mouseWorld.n, t, height)
        previewLine.push(mp.x, mp.y)
      }

      if (previewLine.length >= 4) {
        layer.add(
          new Konva.Line({
            points: previewLine,
            stroke: PREVIEW_EDGE_COLOR,
            strokeWidth: 1,
            dash: [4, 4],
          })
        )
      }
    }

    if (showLegAnnotations && isClosed) {
      for (const leg of legData) {
        const labelText = `${leg.bearing}\n${leg.distance.toFixed(3)}m`
        const label = new Konva.Text({
          x: leg.midX,
          y: leg.midY - 12,
          text: labelText,
          fontSize: 9,
          fill: '#555',
          fontFamily: 'monospace',
          align: 'center',
        })
        label.offsetX(label.width() / 2)
        layer.add(label)
      }
    }

    if (isClosed && showLiveArea) {
      const pts = vertices.map(v => w2c(v.easting, v.northing, t, height))
      const xs = pts.map(p => p.x)
      const ys = pts.map(p => p.y)
      const cx = xs.reduce((a, b) => a + b, 0) / xs.length
      const cy = ys.reduce((a, b) => a + b, 0) / ys.length

      const areaText = formatArea(currentArea)
      const labelW = areaText.length * 7 + 16
      const labelH = 22

      layer.add(
        new Konva.Rect({
          x: cx - labelW / 2,
          y: cy - labelH / 2,
          width: labelW,
          height: labelH,
          fill: AREA_BOX_COLOR,
          stroke: AREA_TEXT_COLOR,
          strokeWidth: 1,
          cornerRadius: 3,
        })
      )
      const areaLabel = new Konva.Text({
        x: cx,
        y: cy,
        text: areaText,
        fontSize: 12,
        fill: AREA_TEXT_COLOR,
        fontFamily: 'Calibri, sans-serif',
        fontStyle: 'bold',
        align: 'center',
      })
      areaLabel.offsetX(areaLabel.width() / 2)
      areaLabel.offsetY(areaLabel.height() / 2)
      layer.add(areaLabel)
    }

    for (let i = 0; i < vertices.length; i++) {
      const v = vertices[i]
      const c = w2c(v.easting, v.northing, t, height)
      const isHov = hoveredVertex === v.id
      const isSel = selectedVertex === v.id

      const group = new Konva.Group({ x: c.x, y: c.y })

      if (isSel || isHov || mode === 'edit') {
        group.add(
          new Konva.Circle({
            x: 0,
            y: 0,
            radius: BEACON_RADIUS + (isHov || isSel ? 3 : 0),
            fill: isSel ? '#E63946' : BEACON_COLOR,
            stroke: isSel ? '#fff' : isHov ? '#1B3A5C' : 'transparent',
            strokeWidth: isSel ? 2 : 1,
          })
        )
      } else {
        group.add(
          new Konva.Circle({
            x: 0,
            y: 0,
            radius: VERTEX_RADIUS,
            fill: VERTEX_COLOR,
          })
        )
      }

      if (mode === 'edit') {
        group.add(
          new Konva.Text({
            x: BEACON_RADIUS + 4,
            y: -10,
            text: v.label,
            fontSize: 10,
            fill: '#333',
            fontFamily: 'monospace',
          })
        )
      }

      group.on('mouseenter', () => {
        setHoveredVertex(v.id)
        stage.container().style.cursor = 'pointer'
      })
      group.on('mouseleave', () => {
        setHoveredVertex(null)
        stage.container().style.cursor = 'default'
      })
      group.on('click', (evt) => {
        evt.cancelBubble = true
        if (mode === 'edit') {
          setSelectedVertex(selectedVertex === v.id ? null : v.id)
        }
      })

      if (mode === 'edit') {
        let dragStart = { e: 0, n: 0 }
        group.draggable(true)
        group.on('dragstart', () => {
          dragStart = { e: v.easting, n: v.northing }
        })
        group.on('dragmove', () => {
          const pos = group.position()
          const newE = pos.x / t.scale + t.originE
          const newN = (height - pos.y) / t.scale + t.originN
          const updated = vertices.map(vx =>
            vx.id === v.id
              ? { ...vx, easting: Math.round(newE * 1000) / 1000, northing: Math.round(newN * 1000) / 1000 }
              : vx
          )
          setVertices(updated)
          onVerticesChange?.(updated)
        })
        group.on('dragend', () => {
          const pos = group.position()
          const newE = pos.x / t.scale + t.originE
          const newN = (height - pos.y) / t.scale + t.originN
          const updated = vertices.map(vx =>
            vx.id === v.id
              ? { ...vx, easting: Math.round(newE * 1000) / 1000, northing: Math.round(newN * 1000) / 1000 }
              : vx
          )
          setVertices(updated)
          onVerticesChange?.(updated)
        })
      }

      layer.add(group)
    }

    layer.draw()
  }, [
    vertices, t, width, height, isClosed, currentArea, mode,
    hoveredVertex, selectedVertex, mouseWorld, existingParcels,
    showLegAnnotations, legData, showLiveArea, onVerticesChange,
  ])

  useEffect(() => {
    draw()
  }, [draw])

  const handleCloseParcel = () => {
    if (vertices.length >= 3) {
      onParcelComplete?.(vertices)
    }
  }

  const handleUndo = () => {
    const next = vertices.slice(0, -1)
    setVertices(next)
    onVerticesChange?.(next)
  }

  const handleClear = () => {
    setVertices([])
    onVerticesChange?.([])
  }

  const handleDeleteVertex = () => {
    if (!selectedVertex) return
    const next = vertices.filter(v => v.id !== selectedVertex)
    setVertices(next)
    setSelectedVertex(null)
    onVerticesChange?.(next)
  }

  return (
    <div className={className}>
      <div className="relative">
        <div ref={containerRef} className="w-full h-full" />

        {mouseWorld && mode === 'draw' && (
          <div
            className="absolute top-2 right-2 bg-white/90 border border-gray-200 rounded px-2 py-1 text-xs font-mono text-gray-700 pointer-events-none"
          >
            E{mouseWorld.e.toFixed(3)} N{mouseWorld.n.toFixed(3)}
          </div>
        )}

        <div className="absolute bottom-2 left-2 bg-white/90 border border-gray-200 rounded px-3 py-1.5 text-xs font-mono text-[#1B3A5C]">
          {mode === 'draw' && (
            <span>
              {vertices.length === 0
                ? 'Click to place first vertex'
                : vertices.length === 1
                ? 'Click to add more vertices'
                : `${vertices.length} vertices — ${isClosed ? 'Parcel closed' : 'Click to add or close'}`}
            </span>
          )}
          {mode === 'edit' && (
            <span>
              {selectedVertex ? `Selected: ${vertices.find(v => v.id === selectedVertex)?.label}` : 'Click a vertex to select, drag to move'}
            </span>
          )}
        </div>

        {isClosed && showLiveArea && (
          <div className="absolute top-2 left-2 bg-white border border-[#1B3A5C] rounded px-3 py-1.5 text-sm font-semibold text-[#1B3A5C]">
            Area: {formatArea(currentArea)}
          </div>
        )}
      </div>

      <div className="flex items-center gap-2 mt-2">
        {mode === 'draw' && (
          <>
            <button
              onClick={handleUndo}
              disabled={vertices.length === 0}
              className="px-3 py-1.5 text-xs bg-gray-100 hover:bg-gray-200 disabled:opacity-40 rounded border border-gray-300 text-gray-700"
            >
              Undo
            </button>
            <button
              onClick={handleClear}
              disabled={vertices.length === 0}
              className="px-3 py-1.5 text-xs bg-gray-100 hover:bg-gray-200 disabled:opacity-40 rounded border border-gray-300 text-gray-700"
            >
              Clear
            </button>
            <button
              onClick={handleCloseParcel}
              disabled={vertices.length < 3}
              className="px-3 py-1.5 text-xs bg-[#1B3A5C] hover:bg-[#142d49] disabled:opacity-40 rounded text-white font-semibold"
            >
              Done — Close Parcel
            </button>
          </>
        )}
        {mode === 'edit' && (
          <>
            <button
              onClick={handleDeleteVertex}
              disabled={!selectedVertex}
              className="px-3 py-1.5 text-xs bg-red-50 hover:bg-red-100 disabled:opacity-40 rounded border border-red-200 text-red-700"
            >
              Delete Vertex
            </button>
            <button
              onClick={() => { setSelectedVertex(null); setVertices([]); onVerticesChange?.([]) }}
              className="px-3 py-1.5 text-xs bg-gray-100 hover:bg-gray-200 rounded border border-gray-300 text-gray-700"
            >
              Clear
            </button>
            <button
              onClick={handleCloseParcel}
              disabled={vertices.length < 3}
              className="px-3 py-1.5 text-xs bg-[#1B3A5C] hover:bg-[#142d49] disabled:opacity-40 rounded text-white font-semibold"
            >
              Save Parcel
            </button>
          </>
        )}
      </div>
    </div>
  )
}

