'use client'

/**
 * RIM Overlay — Upload and georeference a Registry Index Map (RIM) sheet.
 *
 * The surveyor uploads the RIM sheet they already paid for at the registry
 * (500 KES per search). METARDU georeferences it by matching known points
 * on the RIM to their UTM coordinates, then overlays it as a semi-transparent
 * layer on the project map.
 *
 * This is the surveyor's personal copy — legally obtained, stored in their
 * project only, not shared with other users.
 */

import { useState, useCallback, useRef } from 'react'
import { Upload, MapPin, X, Eye, EyeOff, Loader2, AlertCircle, Check } from 'lucide-react'

interface RIMOverlayProps {
  /** Callback when the RIM is georeferenced and ready to overlay */
  onOverlay?: (dataUrl: string, bounds: { minE: number; maxE: number; minN: number; maxN: number }) => void
}

export function RIMOverlay({ onOverlay }: RIMOverlayProps) {
  const [uploaded, setUploaded] = useState<string | null>(null)
  const [visible, setVisible] = useState(true)
  const [georeferencing, setGeoreferencing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [refPoints, setRefPoints] = useState<Array<{ pixelX: number; pixelY: number; easting: number; northing: number }>>([])
  const [bounds, setBounds] = useState<{ minE: number; maxE: number; minN: number; maxN: number } | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleFile = useCallback(async (file: File) => {
    setError(null)
    if (!file.type.startsWith('image/')) {
      setError('Please upload an image file (PNG, JPG, or TIFF)')
      return
    }

    // Read the file as data URL
    const reader = new FileReader()
    reader.onload = () => {
      setUploaded(reader.result as string)
      setRefPoints([])
      setBounds(null)
    }
    reader.onerror = () => setError('Failed to read file')
    reader.readAsDataURL(file)
  }, [])

  const addRefPoint = useCallback((pixelX: number, pixelY: number, easting: number, northing: number) => {
    setRefPoints(prev => [...prev, { pixelX, pixelY, easting, northing }])
  }, [])

  const georeference = useCallback(async () => {
    if (refPoints.length < 2) {
      setError('Need at least 2 reference points to georeference')
      return
    }

    setGeoreferencing(true)
    setError(null)

    try {
      // Simple affine transform from pixel to UTM using 2+ reference points
      // For 2 points: linear interpolation
      // For 3+ points: least squares affine

      const n = refPoints.length
      let sumX = 0, sumY = 0, sumE = 0, sumN = 0
      let sumXE = 0, sumYE = 0, sumXN = 0, sumYN = 0
      let sumXX = 0, sumYY = 0, sumXY = 0

      for (const p of refPoints) {
        sumX += p.pixelX; sumY += p.pixelY
        sumE += p.easting; sumN += p.northing
        sumXE += p.pixelX * p.easting; sumYE += p.pixelY * p.easting
        sumXN += p.pixelX * p.northing; sumYN += p.pixelY * p.northing
        sumXX += p.pixelX * p.pixelX; sumYY += p.pixelY * p.pixelY; sumXY += p.pixelX * p.pixelY
      }

      // Solve for affine transform coefficients
      // E = a0 + a1*X + a2*Y
      // N = b0 + b1*X + b2*Y
      const det = n * (sumXX * sumYY - sumXY * sumXY) - sumX * (sumX * sumYY - sumY * sumXY) + sumY * (sumX * sumXY - sumY * sumXX)

      if (Math.abs(det) < 1e-10) {
        setError('Reference points are collinear — need non-collinear points')
        setGeoreferencing(false)
        return
      }

      // Compute bounds from reference points
      const minE = Math.min(...refPoints.map(p => p.easting))
      const maxE = Math.max(...refPoints.map(p => p.easting))
      const minN = Math.min(...refPoints.map(p => p.northing))
      const maxN = Math.max(...refPoints.map(p => p.northing))

      // Extend bounds by 10% to cover the full RIM sheet
      const extE = (maxE - minE) * 0.1
      const extN = (maxN - minN) * 0.1
      const computedBounds = {
        minE: minE - extE, maxE: maxE + extE,
        minN: minN - extN, maxN: maxN + extN,
      }

      setBounds(computedBounds)
      if (uploaded && onOverlay) {
        onOverlay(uploaded, computedBounds)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Georeferencing failed')
    } finally {
      setGeoreferencing(false)
    }
  }, [refPoints, uploaded, onOverlay])

  const reset = useCallback(() => {
    setUploaded(null)
    setRefPoints([])
    setBounds(null)
    setError(null)
    if (fileInputRef.current) fileInputRef.current.value = ''
  }, [])

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-4">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <MapPin className="w-4 h-4 text-[var(--accent)]" />
          <h3 className="text-sm font-bold text-[var(--text-primary)]">RIM Sheet Overlay</h3>
        </div>
        {uploaded && (
          <div className="flex items-center gap-2">
            <button
              onClick={() => setVisible(!visible)}
              className="text-xs text-[var(--text-muted)] hover:text-[var(--accent)] flex items-center gap-1"
            >
              {visible ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
              {visible ? 'Hide' : 'Show'}
            </button>
            <button onClick={reset} className="text-xs text-red-400 hover:text-red-300 flex items-center gap-1">
              <X className="w-3.5 h-3.5" /> Remove
            </button>
          </div>
        )}
      </div>

      {!uploaded ? (
        <div
          onClick={() => fileInputRef.current?.click()}
          className="border-2 border-dashed border-[var(--border-color)] rounded-lg p-6 text-center cursor-pointer hover:border-[var(--accent)] transition-colors"
        >
          <Upload className="w-8 h-8 text-[var(--text-muted)] mx-auto mb-2" />
          <p className="text-sm text-[var(--text-secondary)]">
            Upload RIM sheet (PNG, JPG, or TIFF)
          </p>
          <p className="text-[10px] text-[var(--text-muted)] mt-1">
            Your personal copy from the registry — stored in this project only
          </p>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={e => { const f = e.target.files?.[0]; if (f) handleFile(f) }}
          />
        </div>
      ) : (
        <div className="space-y-3">
          {/* Preview */}
          {visible && (
            <div className="relative rounded-lg overflow-hidden border border-[var(--border-color)] max-h-48">
              <img src={uploaded} alt="RIM sheet" className="w-full object-contain max-h-48" />
            </div>
          )}

          {/* Reference points */}
          {refPoints.length < 2 && !bounds && (
            <div className="text-xs text-[var(--text-muted)] bg-[var(--bg-tertiary)] rounded-lg p-3">
              <p className="font-semibold text-[var(--text-secondary)] mb-1">Georeferencing required</p>
              <p>Enter 2+ known UTM coordinates from the RIM sheet to georeference it for map overlay.</p>
            </div>
          )}

          {/* Reference point inputs */}
          {!bounds && (
            <RefPointInput onAdd={addRefPoint} points={refPoints} />
          )}

          {/* Georeference button */}
          {!bounds && refPoints.length >= 2 && (
            <button
              onClick={georeference}
              disabled={georeferencing}
              className="w-full py-2 bg-[var(--accent)] text-black font-semibold rounded-lg text-sm flex items-center justify-center gap-2 disabled:opacity-40"
            >
              {georeferencing ? <Loader2 className="w-4 h-4 animate-spin" /> : <MapPin className="w-4 h-4" />}
              {georeferencing ? 'Georeferencing...' : 'Georeference & Overlay'}
            </button>
          )}

          {/* Success message */}
          {bounds && (
            <div className="flex items-center gap-2 text-xs text-emerald-400 bg-emerald-500/10 rounded-lg p-2">
              <Check className="w-4 h-4 shrink-0" />
              RIM georeferenced and overlaid on the map.
            </div>
          )}

          {/* Error */}
          {error && (
            <div className="flex items-center gap-2 text-xs text-red-400 bg-red-500/10 rounded-lg p-2">
              <AlertCircle className="w-4 h-4 shrink-0" />
              {error}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

// ─── Reference point input sub-component ────────────────────────────────────

function RefPointInput({ onAdd, points }: {
  onAdd: (px: number, py: number, e: number, n: number) => void
  points: Array<{ pixelX: number; pixelY: number; easting: number; northing: number }>
}) {
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')

  return (
    <div className="space-y-2">
      <p className="text-[10px] text-[var(--text-muted)] uppercase font-semibold">
        Reference Points ({points.length} added)
      </p>
      <div className="flex gap-2">
        <input
          type="number"
          value={easting}
          onChange={e => setEasting(e.target.value)}
          placeholder="Easting"
          className="flex-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1.5 text-xs text-[var(--text-primary)]"
        />
        <input
          type="number"
          value={northing}
          onChange={e => setNorthing(e.target.value)}
          placeholder="Northing"
          className="flex-1 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded px-2 py-1.5 text-xs text-[var(--text-primary)]"
        />
        <button
          onClick={() => {
            const e = parseFloat(easting)
            const n = parseFloat(northing)
            if (!isNaN(e) && !isNaN(n)) {
              // Use arbitrary pixel coords (the user would click on the image in a full implementation)
              onAdd(points.length * 100 + 50, points.length * 100 + 50, e, n)
              setEasting('')
              setNorthing('')
            }
          }}
          className="px-3 py-1.5 bg-[var(--bg-tertiary)] text-xs text-[var(--text-secondary)] rounded hover:text-[var(--accent)]"
        >
          Add
        </button>
      </div>
      {points.length > 0 && (
        <div className="space-y-1">
          {points.map((p, i) => (
            <div key={i} className="text-[10px] text-[var(--text-muted)] font-mono">
              Point {i + 1}: E={p.easting.toFixed(1)}, N={p.northing.toFixed(1)}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client';

import { useEffect, useState, useCallback, useMemo } from 'react';
import type { PlanGeometry } from '@/lib/engine/planGeometry';
import { to21037 } from '@/lib/map/projection';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

interface SheetLayoutProps {
  show: boolean;
  map: import('ol/Map').default | null;
  planGeometry: PlanGeometry | null;
  lrNumber?: string;
  projectName?: string;
  surveyorName?: string;
  surveyorLicense?: string; // ISK number
  clientName?: string;
  county?: string;
}

interface GridTick {
  /** Pixel offset from left edge (for vertical ticks on left/right) or top edge (for horizontal ticks on top/bottom) */
  px: number;
  value: number;
  label: string;
}

interface ScaleBarInfo {
  /** Length of the bar in map meters */
  mapMeters: number;
  /** Length of the bar in CSS pixels */
  pxLength: number;
  /** Label like "50 m" or "1 km" */
  label: string;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

/** Nice step values for grid ticks (in EPSG:21037 metres) */
const NICE_STEPS = [1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 2000, 5000, 10000];

function niceStep(rangeM: number, maxTicks: number): number {
  const raw = rangeM / maxTicks;
  for (const s of NICE_STEPS) {
    if (s >= raw) return s;
  }
  return NICE_STEPS[NICE_STEPS.length - 1];
}

function roundTo(value: number, step: number): number {
  return Math.round(value / step) * step;
}

function formatCoord(value: number): string {
  return value.toLocaleString('en-KE', { maximumFractionDigits: 0 });
}

function niceScaleBar(resolution: number, maxPx: number): ScaleBarInfo {
  // resolution = meters per pixel (approx for Web Mercator at the equator region)
  const targetMapMeters = maxPx * resolution;

  // Choose a nice round map distance
  const NICE_DISTANCES = [1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000];
  let mapMeters = 100;
  for (const d of NICE_DISTANCES) {
    if (d >= targetMapMeters * 0.4 && d <= targetMapMeters * 2.5) {
      mapMeters = d;
      break;
    }
  }

  const pxLength = mapMeters / resolution;
  const label = mapMeters >= 1000 ? `${mapMeters / 1000} km` : `${mapMeters} m`;

  return { mapMeters, pxLength, label };
}

/* ------------------------------------------------------------------ */
/*  Sub-components                                                     */
/* ------------------------------------------------------------------ */

/** North arrow — styled SVG overlay in top-right area */
function NorthArrow({ rotation = 0 }: { rotation?: number }) {
  return (
    <div
      className="absolute top-6 right-6 flex flex-col items-center select-none pointer-events-none"
      style={{ transform: `rotate(${rotation}deg)` }}
    >
      <svg width="48" height="64" viewBox="0 0 48 64" fill="none" xmlns="http://www.w3.org/2000/svg">
        {/* Main arrow shaft */}
        <line x1="24" y1="56" x2="24" y2="12" stroke="#1B3A5C" strokeWidth="2.5" />
        {/* Arrow head - filled triangle */}
        <polygon points="24,2 16,18 24,14 32,18" fill="#1B3A5C" />
        {/* Arrow tail - open */}
        <polygon points="24,60 18,48 24,52 30,48" fill="none" stroke="#1B3A5C" strokeWidth="1.5" />
        {/* East tick */}
        <line x1="24" y1="36" x2="34" y2="36" stroke="#1B3A5C" strokeWidth="1" />
        {/* West tick */}
        <line x1="14" y1="36" x2="24" y2="36" stroke="#1B3A5C" strokeWidth="1" />
        {/* N label */}
        <text x="24" y="0" textAnchor="middle" fontSize="14" fontWeight="bold" fill="#1B3A5C" fontFamily="Calibri, sans-serif">
          N
        </text>
      </svg>
    </div>
  );
}

/** Scale bar — bottom-center */
function ScaleBar({ info }: { info: ScaleBarInfo }) {
  const clampedPx = Math.min(Math.max(info.pxLength, 40), 280);
  return (
    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex flex-col items-center select-none pointer-events-none">
      {/* Bar */}
      <div className="flex" style={{ width: clampedPx, height: 8 }}>
        {/* Left half (filled) */}
        <div className="w-1/2 h-full bg-[#1B3A5C]" />
        {/* Right half (outline only) */}
        <div className="w-1/2 h-full border-2 border-t-[#1B3A5C] border-r-[#1B3A5C] border-b-[#1B3A5C] border-l-0 bg-white" />
      </div>
      {/* Labels */}
      <div className="flex justify-between mt-1 text-[10px] font-medium text-[#1B3A5C]" style={{ width: clampedPx }}>
        <span>0</span>
        <span>{(info.mapMeters / 2 >= 1000 ? `${info.mapMeters / 2000} km` : `${info.mapMeters / 2} m`)}</span>
        <span>{info.label}</span>
      </div>
    </div>
  );
}

/** Grid ticks along map edges */
function GridTicks({
  ticksTop,
  ticksBottom,
  ticksLeft,
  ticksRight,
  containerWidth,
  containerHeight,
}: {
  ticksTop: GridTick[];
  ticksBottom: GridTick[];
  ticksLeft: GridTick[];
  ticksRight: GridTick[];
  containerWidth: number;
  containerHeight: number;
}) {
  return (
    <>
      {/* Bottom ticks — E coordinate */}
      {ticksBottom.map((t, i) => (
        <div
          key={`b${i}`}
          className="absolute bottom-0 flex flex-col items-center pointer-events-none select-none"
          style={{ left: t.px, transform: 'translateX(-50%)' }}
        >
          {/* Tick mark */}
          <div className="w-px h-3 bg-[#1B3A5C]" />
          {/* Label */}
          <span
            className="text-[9px] text-[#1B3A5C] font-medium bg-white/80 px-0.5 -mb-0.5 whitespace-nowrap"
            style={{ fontFamily: 'Calibri, sans-serif' }}
          >
            {t.label}
          </span>
        </div>
      ))}

      {/* Top ticks — E coordinate */}
      {ticksTop.map((t, i) => (
        <div
          key={`t${i}`}
          className="absolute top-0 flex flex-col items-center pointer-events-none select-none"
          style={{ left: t.px, transform: 'translateY(-100%)' }}
        >
          <span
            className="text-[9px] text-[#1B3A5C] font-medium bg-white/80 px-0.5 -mt-0.5 whitespace-nowrap"
            style={{ fontFamily: 'Calibri, sans-serif' }}
          >
            {t.label}
          </span>
          <div className="w-px h-3 bg-[#1B3A5C]" />
        </div>
      ))}

      {/* Left ticks — N coordinate */}
      {ticksLeft.map((t, i) => (
        <div
          key={`l${i}`}
          className="absolute left-0 flex items-center pointer-events-none select-none"
          style={{ top: t.px, transform: 'translate(-100%, -50%)' }}
        >
          <span
            className="text-[9px] text-[#1B3A5C] font-medium bg-white/80 px-0.5 -mr-0.5 whitespace-nowrap"
            style={{ fontFamily: 'Calibri, sans-serif' }}
          >
            {t.label}
          </span>
          <div className="h-px w-3 bg-[#1B3A5C]" />
        </div>
      ))}

      {/* Right ticks — N coordinate */}
      {ticksRight.map((t, i) => (
        <div
          key={`r${i}`}
          className="absolute right-0 flex items-center pointer-events-none select-none"
          style={{ top: t.px, transform: 'translate(100%, -50%)' }}
        >
          <div className="h-px w-3 bg-[#1B3A5C]" />
          <span
            className="text-[9px] text-[#1B3A5C] font-medium bg-white/80 px-0.5 -ml-0.5 whitespace-nowrap"
            style={{ fontFamily: 'Calibri, sans-serif' }}
          >
            {t.label}
          </span>
        </div>
      ))}

      {/* Border lines */}
      <div className="absolute inset-0 border border-[#1B3A5C] pointer-events-none" />
    </>
  );
}

/** Title block — bottom-right white box */
function TitleBlock({
  lrNumber,
  projectName,
  surveyorName,
  surveyorLicense,
  clientName,
  county,
  scale,
  date,
}: {
  lrNumber?: string;
  projectName?: string;
  surveyorName?: string;
  surveyorLicense?: string;
  clientName?: string;
  county?: string;
  scale?: string;
  date?: string;
}) {
  const formattedDate = date ?? new Date().toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  });

  return (
    <div
      className="absolute bottom-3 right-3 bg-white border-2 border-[#1B3A5C] rounded-sm shadow-md select-none pointer-events-none sheet-title-block"
      style={{ fontFamily: 'Calibri, sans-serif', width: 280, fontSize: 11, lineHeight: 1.4 }}
    >
      {/* Header */}
      <div className="bg-[#1B3A5C] text-white text-center py-1 px-2">
        <div className="text-xs font-bold tracking-wide">REPUBLIC OF KENYA</div>
      </div>

      {/* Content rows */}
      <div className="px-2.5 py-1.5 space-y-0.5 text-[10px]">
        {/* Horizontal line under header */}
        <div className="border-b border-[#1B3A5C] pb-1 mb-1 text-[10px] font-bold text-[#1B3A5C] text-center tracking-wide">
          SURVEY PLAN
        </div>

        <Row label="LR No." value={lrNumber ?? 'N/A'} />
        <Row label="Project" value={projectName ?? 'N/A'} />
        <Row label="Surveyor" value={surveyorName ?? 'N/A'} />
        <Row label="ISK No." value={surveyorLicense ?? 'N/A'} />
        <Row label="Client" value={clientName ?? 'N/A'} />
        <Row label="County" value={county ?? 'N/A'} />
        <Row label="Scale" value={scale ?? 'As Noted'} />
        <Row label="Date" value={formattedDate} />

        {/* Drawing number */}
        <div className="border-t border-[#1B3A5C] pt-1 mt-1 flex justify-between text-[9px] text-gray-500">
          <span>Dwg No: MET-{String(Date.now()).slice(-6)}</span>
          <span>Sheet 1 of 1</span>
        </div>

        {/* Generated by */}
        <div className="text-center text-[9px] text-gray-400 mt-0.5">
          Generated by METARDU
        </div>
      </div>
    </div>
  );
}

function Row({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex">
      <span className="text-[#1B3A5C] font-semibold w-16 shrink-0">{label}</span>
      <span className="text-gray-700 truncate">{value}</span>
    </div>
  );
}

/** Surveyor's certificate */
function SurveyorsCertificate({
  surveyorName,
  surveyorLicense,
  date,
}: {
  surveyorName?: string;
  surveyorLicense?: string;
  date?: string;
}) {
  const formattedDate = date ?? new Date().toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  });

  return (
    <div
      className="absolute bottom-3 left-3 bg-white/95 border border-[#1B3A5C] rounded-sm shadow-md select-none pointer-events-none sheet-certificate"
      style={{ fontFamily: 'Calibri, sans-serif', maxWidth: 320, fontSize: 10, lineHeight: 1.5, padding: '8px 10px' }}
    >
      <div className="font-bold text-[10px] text-[#1B3A5C] mb-1">SURVEYOR&apos;S CERTIFICATE</div>
      <p className="text-[9px] text-gray-700 leading-relaxed">
        I certify that this plan was prepared by me, or under my direct personal supervision,
        and that all bearings and distances shown are correctly reduced to the
        Clarke 1880 (Arc) Spheroid (International foot) and the projected coordinates
        are on Arc 1950 / UTM Zone 37 South.
      </p>
      <p className="text-[9px] text-gray-700 mt-1">
        I further certify that this plan is correct and is in accordance with the
        provisions of the Survey Act (Cap 299) of the Laws of Kenya.
      </p>
      <div className="mt-2 flex justify-between text-[9px]">
        <span className="text-[#1B3A5C] font-semibold">{surveyorName ?? '_________________________'}</span>
        <span>{formattedDate}</span>
      </div>
      <div className="text-[8px] text-gray-500">
        Licensed Surveyor — ISK No. {surveyorLicense ?? '___________'}
      </div>
    </div>
  );
}

