/*  Main SheetLayout component                                         */
/* ------------------------------------------------------------------ */

export default function SheetLayout({
  show,
  map,
  planGeometry,
  lrNumber,
  projectName,
  surveyorName,
  surveyorLicense,
  clientName,
  county,
}: SheetLayoutProps) {
  const [resolution, setResolution] = useState(0);
  const [containerSize, setContainerSize] = useState({ w: 0, h: 0 });
  const [gridTicks, setGridTicks] = useState<{
    top: GridTick[];
    bottom: GridTick[];
    left: GridTick[];
    right: GridTick[];
  }>({ top: [], bottom: [], left: [], right: [] });
  const [viewExtent21037, setViewExtent21037] = useState<{
    minE: number;
    maxE: number;
    minN: number;
    maxN: number;
  } | null>(null);

  /* ── Observe map size and resolution ────────────────────────────── */
  useEffect(() => {
    if (!map || !show) return;

    const updateSize = () => {
      const target = map.getTargetElement();
      if (target) {
        setContainerSize({ w: target.clientWidth, h: target.clientHeight });
      }
    };

    const updateResolution = () => {
      const view = map.getView();
      setResolution(view.getResolution() ?? 0);
    };

    // Observe map target resize
    const resizeObserver = new ResizeObserver(() => updateSize());
    const target = map.getTargetElement();
    if (target) {
      resizeObserver.observe(target);
      updateSize();
    }

    // Observe view changes (zoom/pan)
    const view = map.getView();
    view.on('change:resolution', updateResolution);
    view.on('change:center', () => {
      updateResolution();
    });

    updateResolution();

    return () => {
      resizeObserver.disconnect();
      view.un('change:resolution', updateResolution);
      view.un('change:center', updateResolution);
    };
  }, [map, show]);

  /* ── Compute grid ticks when view changes ──────────────────────── */
  const computeGridTicks = useCallback(async () => {
    if (!map || !show || containerSize.w === 0) return;

    const view = map.getView();
    const extent3857 = view.calculateExtent(map.getSize());
    const [x1, y1, x2, y2] = extent3857;

    // Convert corners to EPSG:21037
    const [[e1, n1], [e2, n2]] = await Promise.all([
      to21037(x1, y1),
      to21037(x2, y2),
    ]);

    const minE = Math.min(e1, e2);
    const maxE = Math.max(e1, e2);
    const minN = Math.min(n1, n2);
    const maxN = Math.max(n1, n2);

    setViewExtent21037({ minE, maxE, minN, maxN });

    const rangeE = maxE - minE;
    const rangeN = maxN - minN;

    const stepE = niceStep(rangeE, 6);
    const stepN = niceStep(rangeN, 6);

    const startE = roundTo(minE, stepE);
    const startN = roundTo(minN, stepN);

    // Horizontal ticks (bottom/top — E values)
    const ticksH: GridTick[] = [];
    for (let e = startE; e <= maxE + stepE * 0.01; e += stepE) {
      const frac = (e - minE) / rangeE;
      const px = frac * containerSize.w;
      if (px >= -5 && px <= containerSize.w + 5) {
        ticksH.push({ px, value: e, label: `E ${formatCoord(e)}` });
      }
    }

    // Vertical ticks (left/right — N values)
    const ticksV: GridTick[] = [];
    for (let n = startN; n <= maxN + stepN * 0.01; n += stepN) {
      const frac = 1 - (n - minN) / rangeN; // Invert because screen Y is down
      const px = frac * containerSize.h;
      if (px >= -5 && px <= containerSize.h + 5) {
        ticksV.push({ px, value: n, label: `N ${formatCoord(n)}` });
      }
    }

    setGridTicks({
      top: ticksH,
      bottom: ticksH,
      left: ticksV,
      right: ticksV,
    });
  }, [map, show, containerSize]);

  useEffect(() => {
    computeGridTicks();
  }, [computeGridTicks]);

  /* ── Scale bar ──────────────────────────────────────────────────── */
  const scaleBar = useMemo(() => {
    if (resolution <= 0) return { mapMeters: 0, pxLength: 0, label: '' };
    return niceScaleBar(resolution, 200);
  }, [resolution]);

  /* ── Scale label (e.g. "1:1000") ───────────────────────────────── */
  const scaleLabel = planGeometry ? `1:${planGeometry.scale.toLocaleString()}` : 'As Noted';

  /* ── Don't render when hidden ───────────────────────────────────── */
  if (!show) return null;

  return (
    <div
      className="absolute inset-0 overflow-hidden sheet-layout-overlay"
      style={{ zIndex: 20 }}
    >
      {/* North Arrow */}
      <NorthArrow />

      {/* Scale Bar */}
      <ScaleBar info={scaleBar} />

      {/* Grid Ticks */}
      <GridTicks
        ticksTop={gridTicks.top}
        ticksBottom={gridTicks.bottom}
        ticksLeft={gridTicks.left}
        ticksRight={gridTicks.right}
        containerWidth={containerSize.w}
        containerHeight={containerSize.h}
      />

      {/* Title Block */}
      <TitleBlock
        lrNumber={lrNumber}
        projectName={projectName}
        surveyorName={surveyorName}
        surveyorLicense={surveyorLicense}
        clientName={clientName}
        county={county}
        scale={scaleLabel}
      />

      {/* Surveyor's Certificate */}
      <SurveyorsCertificate
        surveyorName={surveyorName}
        surveyorLicense={surveyorLicense}
      />
    </div>
  );
}

'use client'
/**
 * StakeoutPanel — Floating stakeout info panel for GPS-guided point navigation
 *
 * Positioned at bottom-center of the map for mobile field use.
 * Shows distance, bearing, accuracy, elevation diff, and proximity progress.
 * Includes audio mute toggle and cancel stakeout button.
 * Auto-hides when arrived (<1m for 3 seconds).
 *
 * Touch-friendly with large text for field use.
 *
 * Now consumes all state from MapReactContext via useMapContext().
 * Previously received 9 props from MapClient — now reads from context directly.
 */

import React, { memo, useState, useEffect, useRef } from 'react'
import { useMapContext } from '@/app/map/MapReactContext'

export const StakeoutPanel = memo(function StakeoutPanel() {
  const {
    stakeoutActive: active,
    stakeoutTarget,
    stakeoutState,
    gpsPos21037,
    gpsPos,
    deactivateStakeout,
    audioMuted,
    setAudioMuted,
    isMobile,
  } = useMapContext()

  // Derive target in StakeoutTarget format
  const target = stakeoutTarget
    ? { easting: stakeoutTarget.e, northing: stakeoutTarget.n }
    : null

  const gpsAccuracy = gpsPos?.accuracy ?? 0

  const [arrivedStartTime, setArrivedStartTime] = useState<number | null>(null)
  const [autoHidden, setAutoHidden] = useState(false)
  const panelRef = useRef<HTMLDivElement>(null)

  // Auto-hide when arrived (<1m) for 3 continuous seconds
  useEffect(() => {
    if (!stakeoutState) return

    if (stakeoutState.proximityColor === 'green') {
      if (!arrivedStartTime) {
        setArrivedStartTime(Date.now())
      } else if (Date.now() - arrivedStartTime > 3000) {
        setAutoHidden(true)
      }
    } else {
      setArrivedStartTime(null)
      setAutoHidden(false)
    }
  }, [stakeoutState, arrivedStartTime])

  // Reset auto-hide when stakeout changes
  useEffect(() => {
    setAutoHidden(false)
    setArrivedStartTime(null)
  }, [target])

  if (!active || !target || autoHidden) return null

  const proximityColorMap = {
    green: {
      bg: 'bg-green-500/15',
      border: 'border-green-500/40',
      text: 'text-green-400',
      barBg: 'bg-green-500/20',
      barFill: 'bg-green-500',
      glow: 'shadow-green-500/20',
    },
    amber: {
      bg: 'bg-amber-500/15',
      border: 'border-amber-500/40',
      text: 'text-amber-400',
      barBg: 'bg-amber-500/20',
      barFill: 'bg-amber-500',
      glow: 'shadow-amber-500/20',
    },
    red: {
      bg: 'bg-[#D17B47]/15',
      border: 'border-[#D17B47]/40',
      text: 'text-[#D17B47]',
      barBg: 'bg-[#D17B47]/20',
      barFill: 'bg-[#D17B47]',
      glow: 'shadow-[#D17B47]/20',
    },
  }

  const colors = stakeoutState
    ? proximityColorMap[stakeoutState.proximityColor]
    : proximityColorMap.red

  // Progress bar: 0-3m range mapped to 0-100%
  const progressPercent = stakeoutState
    ? Math.max(0, Math.min(100, ((3 - Math.min(stakeoutState.distance, 3)) / 3) * 100))
    : 0

  const onToggleAudio = () => setAudioMuted(m => !m)

  return (
    <div
      ref={panelRef}
      className={`
        fixed z-[1001] left-1/2 -translate-x-1/2
        ${isMobile ? 'bottom-[72px] w-[calc(100%-24px)] max-w-[360px]' : 'bottom-4 w-[380px]'}
        ${colors.bg} backdrop-blur-xl ${colors.border} border rounded-2xl
        shadow-2xl ${colors.glow} overflow-hidden
        transition-all duration-300 ease-out
      `}
      role="region"
      aria-label="Stakeout navigation panel"
    >
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2.5 border-b border-white/[0.06]">
        <div className="flex items-center gap-2">
          {/* Pulsing dot */}
          <div className="relative">
            <div
              className={`w-2.5 h-2.5 rounded-full ${
                stakeoutState?.proximityColor === 'green'
                  ? 'bg-green-500'
                  : stakeoutState?.proximityColor === 'amber'
                  ? 'bg-amber-500'
                  : 'bg-[#D17B47]'
              }`}
            />
            <div
              className={`absolute inset-0 rounded-full animate-ping opacity-50 ${
                stakeoutState?.proximityColor === 'green'
                  ? 'bg-green-500'
                  : stakeoutState?.proximityColor === 'amber'
                  ? 'bg-amber-500'
                  : 'bg-[#D17B47]'
              }`}
            />
          </div>
          <span className="text-[11px] font-bold text-gray-300 uppercase tracking-[0.15em]">
            Stakeout
          </span>
          {stakeoutState && (
            <span className={`text-[10px] font-semibold ${colors.text} uppercase`}>
              {stakeoutState.proximityLabel}
            </span>
          )}
        </div>

        <div className="flex items-center gap-1.5">
          {/* Audio mute toggle */}
          <button
            onClick={onToggleAudio}
            className="w-7 h-7 flex items-center justify-center rounded-lg
                       bg-white/[0.06] border border-white/[0.08] text-gray-400
                       hover:text-white hover:bg-white/[0.10] transition-colors"
            title={audioMuted ? 'Unmute audio alerts' : 'Mute audio alerts'}
            aria-label={audioMuted ? 'Unmute audio alerts' : 'Mute audio alerts'}
          >
            {audioMuted ? (
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                <path strokeLinecap="round" strokeLinejoin="round" d="M17 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2" />
              </svg>
            ) : (
              <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
              </svg>
            )}
          </button>

          {/* Cancel button */}
          <button
            onClick={deactivateStakeout}
            className="w-7 h-7 flex items-center justify-center rounded-lg
                       bg-red-500/10 border border-red-500/20 text-red-400
                       hover:text-red-300 hover:bg-red-500/20 transition-colors"
            title="Cancel stakeout"
            aria-label="Cancel stakeout"
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="px-4 py-3">
        {/* Target info */}
        <div className="mb-3">
          <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
            Target
          </div>
          <div className="text-sm text-white font-semibold truncate">
            Point
          </div>
          <div className="text-[11px] text-gray-400 font-mono">
            E: {target.easting.toFixed(2)} &nbsp; N: {target.northing.toFixed(2)}
          </div>
        </div>

        {/* Distance — large, bold, prominent */}
        {stakeoutState ? (
          <div className="mb-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
              Distance
            </div>
            <div className={`text-3xl font-bold font-mono ${colors.text} tabular-nums leading-tight`}>
              {stakeoutState.distance < 1000
                ? `${stakeoutState.distance.toFixed(2)} m`
                : `${(stakeoutState.distance / 1000).toFixed(3)} km`}
            </div>
          </div>
        ) : (
          <div className="mb-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
              Distance
            </div>
            <div className="text-sm text-gray-600">Waiting for GPS...</div>
          </div>
        )}

        {/* Bearing */}
        {stakeoutState && (
          <div className="mb-3 grid grid-cols-2 gap-3">
            <div>
              <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
                Bearing (WCB)
              </div>
              <div className="text-base font-semibold font-mono text-blue-300 tabular-nums">
                {stakeoutState.bearingWCB}
              </div>
            </div>
            <div>
              <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
                Azimuth
              </div>
              <div className="text-base font-semibold font-mono text-blue-300 tabular-nums">
                {stakeoutState.bearing.toFixed(4)}&deg;
              </div>
            </div>
          </div>
        )}

        {/* Accuracy & Elevation */}
        <div className="mb-3 grid grid-cols-2 gap-3">
          <div>
            <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
              Accuracy
            </div>
            <div className="text-[11px] font-mono text-gray-300">
              {'\u00B1'}{gpsAccuracy.toFixed(1)} m
            </div>
          </div>
          {stakeoutState?.elevationDiff != null && (
            <div>
              <div className="text-[10px] text-gray-500 uppercase tracking-wider mb-0.5">
                Elevation Diff
              </div>
              <div className="text-[11px] font-mono text-gray-300">
                {stakeoutState.elevationDiff >= 0 ? '+' : ''}
                {stakeoutState.elevationDiff.toFixed(2)} m
              </div>
            </div>
          )}
        </div>

        {/* dE / dN */}
        {stakeoutState && (
          <div className="mb-3 text-[10px] text-gray-500 font-mono">
            dE: {stakeoutState.dE >= 0 ? '+' : ''}{stakeoutState.dE.toFixed(2)} &nbsp;|&nbsp;
            dN: {stakeoutState.dN >= 0 ? '+' : ''}{stakeoutState.dN.toFixed(2)}
          </div>
        )}

        {/* Progress bar (0–3m tolerance) */}
        <div className="mb-1">
          <div className="flex items-center justify-between mb-1">
            <span className="text-[10px] text-gray-500 uppercase tracking-wider">Proximity</span>
            <span className="text-[10px] text-gray-500 tabular-nums">
              {stakeoutState ? `${stakeoutState.distance.toFixed(1)}m / 1.0m` : '---'}
            </span>
          </div>
          <div className={`h-2 rounded-full ${colors.barBg} overflow-hidden`}>
            <div
              className={`h-full rounded-full ${colors.barFill} transition-all duration-300 ease-out`}
              style={{ width: `${progressPercent}%` }}
            />
          </div>
          <div className="flex justify-between mt-0.5">
            <span className="text-[9px] text-gray-600">3m</span>
            <span className="text-[9px] text-gray-600">1m</span>
            <span className="text-[9px] text-gray-600">0m</span>
          </div>
        </div>
      </div>
    </div>
  )
})

'use client';

import { useEffect, useRef, useState, useCallback, useMemo } from 'react';
import { registerProjections, arrayTo3857, to21037, SRID_3857 } from '@/lib/map/projection';
import { nearestKenCORSStations, type KenCORSStation } from '@/lib/map/kencors';
import type { AdjustedStation, PlanGeometry } from '@/lib/engine/planGeometry';
import { computePlanGeometry } from '@/lib/engine/planGeometry';
import { createAnnotationLayer } from '@/lib/map/annotations';
import { MeasurementTool } from './MeasurementTool';
import { VertexEditToolbar } from './VertexEditToolbar';
import MapAccessibility from './MapAccessibility';
import { useVertexEditing } from '@/hooks/useVertexEditing';
import { LayerControl } from './LayerControl';
import { exportMapPDF } from '@/lib/export/exportMapPDF';

interface SurveyMapProps {
  projectId: string;
  adjustedStations: AdjustedStation[];
  centroidEasting: number;
  centroidNorthing: number;
  onBeaconClick?: (label: string, easting: number, northing: number) => void;
  readOnly?: boolean;
  /** Enable the vertex editing toolbar and interactions */
  enableEditing?: boolean;
  /** Callback with updated vertices (EPSG:21037) after each edit */
  onVerticesChange?: (updated: Array<{ easting: number; northing: number }>) => void;
  /** Sheet layout props */
  lrNumber?: string;
  projectName?: string;
  surveyorName?: string;
  surveyorLicense?: string;
  clientName?: string;
  county?: string;
  /** Unique container ID for PDF print targeting */
  mapContainerId?: string;
  /** T1.5 FIX (2026-07-09): UTM EPSG for coordinate transforms (default 'EPSG:21037') */
  epsg?: string;
}

interface NearestStation extends KenCORSStation {
  distanceKm: number;
}

export default function SurveyMap({
  projectId,
  adjustedStations,
  centroidEasting,
  centroidNorthing,
  onBeaconClick,
  readOnly = true,
  enableEditing = false,
  onVerticesChange,
  lrNumber,
  projectName,
  surveyorName,
  surveyorLicense,
  clientName,
  county,
  mapContainerId = 'metardu-map-container',
  epsg = 'EPSG:21037',
}: SurveyMapProps) {
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<import('ol/Map').default | null>(null);
  const [mapReady, setMapReady] = useState(false);
  const [nearestStations, setNearestStations] = useState<NearestStation[]>([]);
  const [clickedCoord, setClickedCoord] = useState<{ easting: number; northing: number } | null>(null);
  const [basemap, setBasemap] = useState<'osm' | 'satellite' | 'blank'>('osm');

  // ── Sheet layout state ────────────────────────────────────────
  const [showSheetLayout, setShowSheetLayout] = useState(false);
  const [sheetLayoutReady, setSheetLayoutReady] = useState(false);

  // ── Compute plan geometry for sheet layout ─────────────────────
  const planGeometry: PlanGeometry | null = useMemo(() => {
    if (adjustedStations.length < 3) return null;
    return computePlanGeometry(adjustedStations);
  }, [adjustedStations]);

  // ── Dynamically import SheetLayout to avoid SSR issues ─────────
  const [SheetLayoutComponent, setSheetLayoutComponent] = useState<React.ComponentType<any> | null>(null);

  useEffect(() => {
    import('./SheetLayout').then((mod) => {
      setSheetLayoutComponent(() => mod.default);
      setSheetLayoutReady(true);
    });
  }, []);

  // ── Vertex editing state ──────────────────────────────────────
  const [vertexEditingEnabled, setVertexEditingEnabled] = useState(false);
  const [snapEnabled, setSnapEnabled] = useState(true);
  const [snapTolerance, setSnapTolerance] = useState(10);

  // Derive the editable vertices from adjustedStations
  const editableVertices = adjustedStations.map(s => ({
    easting: s.adjustedEasting,
    northing: s.adjustedNorthing,
  }));

  const { state: vertexEditState } = useVertexEditing({
    map: mapInstanceRef.current,
    vertices: editableVertices,
    enabled: enableEditing && vertexEditingEnabled,
    onVerticesChange: onVerticesChange ?? (() => {}),
    snapTolerance,
    snapEnabled,
  });

  async function to3857Single(e: number, n: number): Promise<[number, number]> {
    const { transform } = await import('ol/proj');
    return transform([e, n], epsg, SRID_3857) as [number, number];
  }

  useEffect(() => {
    if (!mapRef.current || mapInstanceRef.current) return;

    let map: import('ol/Map').default;
    let cancelled = false;

    // Store handler references for cleanup
    let viewChangeHandler: (() => void) | null = null;
    let mapClickHandler: ((evt: any) => void) | null = null;

    async function initMap() {
      await registerProjections();

      const { default: Map }  = await import('ol/Map');
      const { default: View } = await import('ol/View');
      const { transform }     = await import('ol/proj');

      if (cancelled) return;

      const storageKey = `metardu_map_${projectId}`;
      const saved = localStorage.getItem(storageKey);
      const savedState = saved ? JSON.parse(saved) : null;

      const center3857 = transform(
        [centroidEasting, centroidNorthing],
        epsg,
        SRID_3857
      ) as [number, number];

      const { createOSMLayer, createParcelLayer, createBeaconLayer, createKenCORSLayer }
        = await import('@/lib/map/layers');

      if (cancelled) return;

      const closed = [...adjustedStations, adjustedStations[0]];
      const coords3857 = await arrayTo3857(
        closed.map(s => [s.adjustedEasting, s.adjustedNorthing] as [number, number])
      );

      const beaconCoords = await Promise.all(
        adjustedStations.map(async s => ({
          label: s.pointName,
          coord3857: await to3857Single(s.adjustedEasting, s.adjustedNorthing),
        }))
      );

      const nearest = nearestKenCORSStations(centroidEasting, centroidNorthing, 3);
      setNearestStations(nearest);

      const kenCORSWithCoords = await Promise.all(
        nearest.map(async st => ({
          ...st,
          coord3857: await to3857Single(st.easting, st.northing),
        }))
      );

      if (cancelled) return;

      const [osmLayer, parcelLayer, beaconLayer, kenCORSLayer] = await Promise.all([
        createOSMLayer(),
        createParcelLayer(coords3857),
        createBeaconLayer(beaconCoords),
        createKenCORSLayer(kenCORSWithCoords),
      ]);

      // Tag the OSM layer so LayerControl can find it
      osmLayer.set('basemapId', 'osm');

      // Create annotation layer with bearings, distances, and area
      const stations21037 = adjustedStations.map(s => ({
        pointName: s.pointName,
        easting: s.adjustedEasting,
        northing: s.adjustedNorthing,
      }));
      const annotationLayer = await createAnnotationLayer({
        coords3857,
        stations21037,
      });

      if (cancelled) return;

      map = new Map({
        target: mapRef.current!,
        layers: [osmLayer, kenCORSLayer, parcelLayer, beaconLayer, annotationLayer],
        view: new View({
          center: savedState?.center ?? center3857,
          zoom: savedState?.zoom ?? 16,
          projection: SRID_3857,
        }),
        controls: [],
      });

      viewChangeHandler = () => {
        const state = {
          center: map.getView().getCenter(),
          zoom: map.getView().getZoom(),
        };
        localStorage.setItem(storageKey, JSON.stringify(state));
      };
      map.getView().on('change', viewChangeHandler);

      mapClickHandler = async (evt: any) => {
        const [x, y] = evt.coordinate as [number, number];
        const [e, n] = await to21037(x, y);
        setClickedCoord({ easting: e, northing: n });

        // ── Check if a beacon feature was clicked ─────────────────
        if (onBeaconClick) {
          const { default: Feature } = await import('ol/Feature');
          const hitFeature = map.forEachFeatureAtPixel(evt.pixel, (f: any) => f, {
            hitTolerance: 8,
          });
          if (hitFeature) {
            const label = hitFeature.get('label') || hitFeature.get('name') || hitFeature.get('stationName');
            if (label) {
              const geom = hitFeature.getGeometry();
              if (geom && geom.getType() === 'Point') {
                const coord = geom.getCoordinates();
                const [be, bn] = await to21037(coord[0], coord[1]);
                onBeaconClick(label, be, bn);
              }
            }
          }
        }
      };
      map.on('click', mapClickHandler);

      mapInstanceRef.current = map;
      setMapReady(true);
    }

    initMap();

    return () => {
      cancelled = true;
      const instance = mapInstanceRef.current;
      if (instance) {
        // Remove event listeners before destroying
        try {
          const view = instance.getView();
          if (view && viewChangeHandler) {
            view.un('change', viewChangeHandler);
          }
        } catch { /* ignore */ }
        try {
          if (mapClickHandler) {
            instance.un('click', mapClickHandler);
          }
        } catch { /* ignore */ }
        instance.setTarget(undefined);
        mapInstanceRef.current = null;
      }
    };
  }, [projectId, centroidEasting, centroidNorthing]);

  const toggleBasemap = useCallback(async () => {
    if (!mapInstanceRef.current) return;
    const map = mapInstanceRef.current;

    if (basemap === 'osm') {
      map.getLayers().getArray()
        .filter(l => l.get('basemapId'))
        .forEach(l => l.setVisible(false));
      setBasemap('blank');
    } else {
      map.getLayers().getArray()
        .filter(l => l.get('basemapId') === 'osm')
        .forEach(l => l.setVisible(true));
      setBasemap('osm');
    }
  }, [basemap]);

  const fitToParcel = useCallback(async () => {
    if (!mapInstanceRef.current || adjustedStations.length < 3) return;
    const { transform } = await import('ol/proj');
    const coords = adjustedStations.map(s =>
      transform([s.adjustedEasting, s.adjustedNorthing], epsg, SRID_3857)
    );
    const xs = coords.map(c => c[0]);
    const ys = coords.map(c => c[1]);
    const extent = [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)] as [number, number, number, number];
    mapInstanceRef.current.getView().fit(extent, { padding: [60, 60, 60, 60], duration: 400 });
  }, [adjustedStations]);

  const handlePrint = useCallback(() => {
    if (!showSheetLayout) {
      setShowSheetLayout(true);
    }
    // Small delay to ensure sheet layout renders before print
    setTimeout(() => {
      exportMapPDF(mapContainerId, { paperSize: 'a3', orientation: 'landscape' });
    }, 500);
  }, [showSheetLayout, mapContainerId]);

  return (
    <div id={mapContainerId} className="flex flex-col h-full" role="application" aria-label="Cadastral survey map">
      <div className="flex items-center gap-2 px-3 py-2 bg-white border-b border-gray-200 text-sm">
        <button
          onClick={fitToParcel}
          className="px-3 py-1.5 bg-[#1B3A5C] text-white rounded text-xs font-medium hover:bg-[#142d49]"
        >
          Fit to Parcel
        </button>
        <button
          onClick={() => setShowSheetLayout(v => !v)}
          className={`px-3 py-1.5 rounded text-xs font-medium border transition-colors ${
            showSheetLayout
              ? 'bg-[#1B3A5C] text-white border-[#1B3A5C]'
              : 'bg-white text-[#1B3A5C] border-[#1B3A5C] hover:bg-[#1B3A5C]/5'
          }`}
          title="Toggle sheet layout overlay (north arrow, scale bar, grid ticks, title block)"
        >
          {showSheetLayout ? ' Sheet Layout On' : ' Sheet Layout'}
        </button>
        <button
          onClick={handlePrint}
          className="px-3 py-1.5 bg-white text-[#1B3A5C] border border-[#1B3A5C] rounded text-xs font-medium hover:bg-[#1B3A5C]/5 transition-colors"
          title="Export current map view to PDF (A3 landscape)"
        >
          ⎙ Print / PDF
        </button>
        <div className="flex-1" />
        <div className="flex items-center gap-3 text-xs text-gray-600">
          <span className="font-medium">Nearest KenCORS:</span>
          {nearestStations.map(st => (
            <span key={st.id} className={st.status === 'active' ? 'text-green-700' : 'text-gray-400'}>
              {st.id} ({st.distanceKm.toFixed(0)} km)
            </span>
          ))}
        </div>
      </div>

      <div className="relative flex-1">
        <div ref={mapRef} className="w-full h-full" />

        {/* Screen reader live region for map state changes */}
        <MapAccessibility mapReady={mapReady} schemeDataLoaded={mapReady && adjustedStations.length > 0} />

        <div className="absolute top-3 right-3 z-10 flex flex-col gap-3 items-end">
          {enableEditing && (
            <VertexEditToolbar
              enabled={vertexEditingEnabled}
              onToggle={() => setVertexEditingEnabled(v => !v)}
              snapEnabled={snapEnabled}
              onSnapToggle={() => setSnapEnabled(v => !v)}
              snapTolerance={snapTolerance}
              onToleranceChange={setSnapTolerance}
              editState={vertexEditState}
            />
          )}
          <MeasurementTool map={mapInstanceRef.current} />
          <LayerControl
            map={mapInstanceRef.current}
            onBasemapChange={setBasemap}
          />
        </div>

        {clickedCoord && (
          <div className="absolute bottom-3 left-3 bg-white border border-gray-200 rounded px-3 py-2 text-xs font-mono shadow">
            <span className="text-gray-500 mr-1">E</span>
            <span className="font-semibold">{clickedCoord.easting.toFixed(3)}</span>
            <span className="text-gray-300 mx-2">|</span>
            <span className="text-gray-500 mr-1">N</span>
            <span className="font-semibold">{clickedCoord.northing.toFixed(3)}</span>
            <span className="ml-2 text-gray-400">SRID 21037</span>
          </div>
        )}

        {/* Sheet Layout Overlay */}
        {showSheetLayout && sheetLayoutReady && SheetLayoutComponent && (
          <SheetLayoutComponent
            show={true}
            map={mapInstanceRef.current}
            planGeometry={planGeometry}
            lrNumber={lrNumber}
            projectName={projectName}
            surveyorName={surveyorName}
            surveyorLicense={surveyorLicense}
            clientName={clientName}
            county={county}
          />
        )}

        {!mapReady && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-50">
            <div className="text-sm text-gray-500">Loading map...</div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client'

/**
 * AttributeTable — Spreadsheet view of parcel/beacon data
 *
 * Inspired by QGIS Attribute Table. Shows all features in a project
 * as rows with their attributes as columns. Supports:
 * - Inline editing of attribute values
 * - Sort by any column
 * - Filter/search
 * - Select row to highlight on map
 * - Bulk operations (delete, export)
 * - Add new parcels from the table
 */

import { useState, useMemo, useCallback } from 'react'
import {
  Search, ArrowUpDown, Trash2, Download, Plus,
  CheckCircle2, AlertTriangle, MapPin,
} from 'lucide-react'

export interface AttributeRow {
  id: string
  parcelNumber: string
  ownerName: string
  lrNumber: string
  areaHa: number
  perimeterM: number
  beaconCount: number
  status: 'registered' | 'pending' | 'disputed' | 'cancelled'
  easting: number  // centroid
  northing: number
}

interface AttributeTableProps {
  rows: AttributeRow[]
  onSelectRow?: (row: AttributeRow) => void
  onDeleteRow?: (id: string) => void
  onExport?: () => void
}

type SortField = keyof AttributeRow
type SortDirection = 'asc' | 'desc'

const STATUS_COLORS: Record<string, string> = {
  registered: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30',
  pending: 'bg-amber-500/10 text-amber-400 border-amber-500/30',
  disputed: 'bg-red-500/10 text-red-400 border-red-500/30',
  cancelled: 'bg-gray-500/10 text-gray-400 border-gray-500/30',
}

export function AttributeTable({ rows, onSelectRow, onDeleteRow, onExport }: AttributeTableProps) {
  const [query, setQuery] = useState('')
  const [sortField, setSortField] = useState<SortField>('parcelNumber')
  const [sortDir, setSortDir] = useState<SortDirection>('asc')
  const [selectedRows, setSelectedRows] = useState<Set<string>>(new Set())
  const [editingCell, setEditingCell] = useState<{ id: string; field: string } | null>(null)
  const [editValue, setEditValue] = useState('')

  // Filter
  const filteredRows = useMemo(() => {
    if (!query.trim()) return rows
    const q = query.toLowerCase()
    return rows.filter(r =>
      r.parcelNumber.toLowerCase().includes(q) ||
      r.ownerName.toLowerCase().includes(q) ||
      r.lrNumber.toLowerCase().includes(q) ||
      r.status.toLowerCase().includes(q)
    )
  }, [rows, query])

  // Sort
  const sortedRows = useMemo(() => {
    const sorted = [...filteredRows].sort((a, b) => {
      const aVal = a[sortField]
      const bVal = b[sortField]
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        return sortDir === 'asc' ? aVal - bVal : bVal - aVal
      }
      const aStr = String(aVal || '')
      const bStr = String(bVal || '')
      return sortDir === 'asc' ? aStr.localeCompare(bStr) : bStr.localeCompare(aStr)
    })
    return sorted
  }, [filteredRows, sortField, sortDir])

  const handleSort = useCallback((field: SortField) => {
    if (sortField === field) {
      setSortDir(prev => prev === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortDir('asc')
    }
  }, [sortField])

  const toggleRowSelection = useCallback((id: string) => {
    setSelectedRows(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  const selectAll = useCallback(() => {
    if (selectedRows.size === sortedRows.length) {
      setSelectedRows(new Set())
    } else {
      setSelectedRows(new Set(sortedRows.map(r => r.id)))
    }
  }, [selectedRows, sortedRows])

  const handleCellEdit = useCallback((id: string, field: string, currentValue: string) => {
    setEditingCell({ id, field })
    setEditValue(currentValue)
  }, [])

  const saveCellEdit = useCallback(() => {
    // In a real implementation, this would call an API to update the record
    setEditingCell(null)
    setEditValue('')
  }, [])

  const columns: Array<{ key: SortField; label: string; width: string; align?: 'left' | 'right' | 'center' }> = [
    { key: 'parcelNumber', label: 'Parcel No.', width: '120px' },
    { key: 'ownerName', label: 'Owner', width: '150px' },
    { key: 'lrNumber', label: 'LR Number', width: '120px' },
    { key: 'areaHa', label: 'Area (ha)', width: '90px', align: 'right' },
    { key: 'perimeterM', label: 'Perimeter (m)', width: '100px', align: 'right' },
    { key: 'beaconCount', label: 'Beacons', width: '70px', align: 'center' },
    { key: 'status', label: 'Status', width: '100px', align: 'center' },
  ]

  return (
    <div className="card overflow-hidden">
      {/* Toolbar */}
      <div className="flex items-center justify-between p-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <span className="text-sm font-semibold text-[var(--text-primary)]">
            Attribute Table
          </span>
          <span className="text-[10px] text-gray-500">
            {sortedRows.length} of {rows.length} parcels
          </span>
          {selectedRows.size > 0 && (
            <span className="text-[10px] text-[var(--accent)]">
              {selectedRows.size} selected
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-500" />
            <input
              type="text"
              value={query}
              onChange={e => setQuery(e.target.value)}
              aria-label="Filter..." placeholder="Filter..."
              className="h-7 pl-7 pr-2 w-40 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>

          {/* Export */}
          {onExport && (
            <button
              onClick={onExport}
              className="flex items-center gap-1 px-2.5 h-7 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400 hover:text-gray-200"
            >
              <Download className="w-3.5 h-3.5" />
              Export
            </button>
          )}

          {/* Bulk delete */}
          {selectedRows.size > 0 && onDeleteRow && (
            <button
              onClick={() => {
                selectedRows.forEach(id => onDeleteRow(id))
                setSelectedRows(new Set())
              }}
              className="flex items-center gap-1 px-2.5 h-7 rounded-lg bg-red-500/10 border border-red-500/30 text-xs text-red-400 hover:bg-red-500/20"
            >
              <Trash2 className="w-3.5 h-3.5" />
              Delete ({selectedRows.size})
            </button>
          )}
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto max-h-[400px] overflow-y-auto">
        <table className="w-full">
          <thead className="sticky top-0 bg-[var(--bg-card)] z-10">
            <tr className="border-b border-[var(--border-color)]">
              <th className="px-2 py-2 w-8">
                <input aria-label="Select all rows"
                  type="checkbox"
                  checked={selectedRows.size === sortedRows.length && sortedRows.length > 0}
                  onChange={selectAll}
                  className="w-3.5 h-3.5 rounded border-[var(--border-color)] accent-[var(--accent)]"
                />
              </th>
              {columns.map(col => (
                <th
                  key={col.key}
                  onClick={() => handleSort(col.key)}
                  className={`px-2 py-2 cursor-pointer hover:bg-white/[0.04] transition-colors ${
                    col.align === 'right' ? 'text-right' : col.align === 'center' ? 'text-center' : 'text-left'
                  }`}
                  style={{ width: col.width }}
                >
                  <div className={`flex items-center gap-1 ${col.align === 'right' ? 'justify-end' : col.align === 'center' ? 'justify-center' : ''}`}>
                    <span className="text-[9px] text-gray-500 uppercase tracking-wider font-semibold">{col.label}</span>
                    <ArrowUpDown className={`w-2.5 h-2.5 ${sortField === col.key ? 'text-[var(--accent)]' : 'text-gray-600'}`} />
                  </div>
                </th>
              ))}
              <th className="px-2 py-2 w-8"></th>
            </tr>
          </thead>
          <tbody>
            {sortedRows.length === 0 ? (
              <tr>
                <td colSpan={columns.length + 2} className="px-4 py-8 text-center">
                  <MapPin className="w-8 h-8 text-gray-600 mx-auto mb-2" />
                  <p className="text-sm text-gray-500">No parcels found</p>
                  <p className="text-[10px] text-gray-600 mt-1">Import parcels or adjust your filter</p>
                </td>
              </tr>
            ) : (
              sortedRows.map(row => (
                <tr
                  key={row.id}
                  onClick={() => onSelectRow?.(row)}
                  className={`border-b border-[var(--border-color)]/30 cursor-pointer transition-colors ${
                    selectedRows.has(row.id) ? 'bg-[var(--accent)]/5' : 'hover:bg-white/[0.02]'
                  }`}
                >
                  <td className="px-2 py-1.5" onClick={(e) => { e.stopPropagation(); toggleRowSelection(row.id) }}>
                    <input aria-label="Select row"
                      type="checkbox"
                      checked={selectedRows.has(row.id)}
                      onChange={() => toggleRowSelection(row.id)}
                      className="w-3.5 h-3.5 rounded border-[var(--border-color)] accent-[var(--accent)]"
                    />
                  </td>
                  {columns.map(col => (
                    <td
                      key={col.key}
                      className={`px-2 py-1.5 text-xs ${
                        col.align === 'right' ? 'text-right font-mono' : col.align === 'center' ? 'text-center' : ''
                      }`}
                      onDoubleClick={() => handleCellEdit(row.id, col.key, String(row[col.key] || ''))}
                    >
                      {editingCell?.id === row.id && editingCell.field === col.key ? (
                        <input aria-label="Search filter"
                          // eslint-disable-next-line jsx-a11y/no-autofocus -- focus into the editing cell (inline edit)
                          autoFocus
                          type="text"
                          value={editValue}
                          onChange={e => setEditValue(e.target.value)}
                          onBlur={saveCellEdit}
                          onKeyDown={e => { if (e.key === 'Enter') saveCellEdit(); if (e.key === 'Escape') setEditingCell(null) }}
                          className="w-full h-6 px-1 bg-white border border-[var(--accent)] rounded text-xs text-black"
                        />
                      ) : col.key === 'status' ? (
                        <span className={`inline-flex items-center px-1.5 py-0.5 rounded text-[9px] font-medium border ${STATUS_COLORS[row[col.key]]}`}>
                          {row[col.key]}
                        </span>
                      ) : col.key === 'areaHa' || col.key === 'perimeterM' ? (
                        <span className="text-[var(--text-secondary)]">
                          {typeof row[col.key] === 'number' ? (row[col.key] as number).toFixed(col.key === 'areaHa' ? 4 : 2) : ''}
                        </span>
                      ) : (
                        <span className="text-[var(--text-primary)]">{row[col.key]}</span>
                      )}
                    </td>
                  ))}
                  <td className="px-2 py-1.5">
                    {onDeleteRow && (
                      <button
                        onClick={(e) => { e.stopPropagation(); onDeleteRow(row.id) }}
                        className="w-6 h-6 flex items-center justify-center rounded text-gray-500 hover:text-red-400 hover:bg-red-500/5"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Footer */}
      <div className="flex items-center justify-between p-2 border-t border-[var(--border-color)] text-[10px] text-gray-500">
        <span>
          {sortedRows.length} parcel{sortedRows.length !== 1 ? 's' : ''}
          {selectedRows.size > 0 && ` · ${selectedRows.size} selected`}
        </span>
        <span>Double-click any cell to edit</span>
      </div>
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react';
import dynamic from 'next/dynamic';

const DashboardSearch = dynamic(
  () => import('@/components/dashboard/DashboardSearch').then(m => m.default || m),
  { ssr: false }
);

export type Page = 'home' | 'dashboard' | 'projects' | 'pricing' | 'community' | 'account' | 'survey-marks';

interface HeaderProps {
  currentPage: Page;
  onNavigate: (page: Page) => void;
}

export default function Header({ currentPage, onNavigate }: HeaderProps) {
  const [scrolled, setScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 0);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems: { page: Page; label: string }[] = [
    { page: 'dashboard', label: 'Dashboard' },
    { page: 'projects', label: 'Projects' },
    { page: 'survey-marks', label: 'Survey Marks' },
    { page: 'community', label: 'Community' },
