                          {reconciliation.discrepancy >= 0 ? '+' : ''}{reconciliation.discrepancy.toFixed(4)}
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </div>

          {/* SVG Preview */}
          <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg overflow-auto">
            <div className="p-2">
              {svgOutput ? (
                <div dangerouslySetInnerHTML={{ __html: svgOutput }} />
              ) : (
                <div className="text-center py-12 text-zinc-500">
                  <Eye className="h-10 w-10 mx-auto mb-3 opacity-30" />
                  <p className="text-sm">Click Generate Plan to create the SVG preview</p>
                </div>
              )}
            </div>
          </div>

          {/* Export buttons */}
          <div className="grid grid-cols-1 sm:grid-cols-5 gap-4">
            <button
              onClick={handleDownloadSVG}
              disabled={!svgOutput}
              className="flex items-center justify-center gap-2 px-6 py-4 bg-[var(--accent)] text-black rounded-lg font-semibold disabled:opacity-40"
            >
              <Download className="h-5 w-5" />
              Download SVG
            </button>
            <button
              onClick={handleDownloadPNG}
              disabled={!svgOutput}
              className="flex items-center justify-center gap-2 px-6 py-4 bg-[var(--accent)] text-black rounded-lg font-semibold disabled:opacity-40"
            >
              <Download className="h-5 w-5" />
              Download PNG (A1 300dpi)
            </button>
            <button
              onClick={handleDownloadDXF}
              disabled={plots.length === 0}
              className="flex items-center justify-center gap-2 px-6 py-4 bg-[var(--accent)] text-black rounded-lg font-semibold disabled:opacity-40"
            >
              <Download className="h-5 w-5" />
              Download DXF
            </button>
            <button
              onClick={handleDownloadPDF}
              disabled={!svgOutput}
              className="flex items-center justify-center gap-2 px-6 py-4 border border-[var(--border-color)] rounded-lg text-zinc-300 hover:border-[var(--accent)]/50 disabled:opacity-40"
            >
              <Printer className="h-5 w-5" />
              Download PDF (Print)
            </button>
            <button
              onClick={() => { const w = window.open('', '_blank'); if (w) { w.document.write(svgOutput); w.document.close(); } }}
              disabled={!svgOutput}
              className="flex items-center justify-center gap-2 px-6 py-4 border border-[var(--border-color)] rounded-lg text-zinc-300 hover:border-[var(--accent)]/50 disabled:opacity-40"
            >
              <Eye className="h-5 w-5" />
              Open in New Tab
            </button>
          </div>

          {/* Bearing schedule */}
          {computedBearingSchedule.length > 0 && (
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-6">
              <h3 className="text-lg font-semibold mb-4">Bearing Schedule ({computedBearingSchedule.length} lines)</h3>
              <div className="overflow-x-auto max-h-96">
                <table className="w-full text-sm min-w-[500px]">
                  <thead className="sticky top-0 bg-zinc-900">
                    <tr className="border-b">
                      <th className="text-left py-2 px-2">Line</th>
                      <th className="text-left py-2 px-2">From</th>
                      <th className="text-left py-2 px-2">To</th>
                      <th className="text-left py-2 px-2">Bearing</th>
                      <th className="text-right py-2 px-2">Distance (m)</th>
                    </tr>
                  </thead>
                  <tbody>
                    {computedBearingSchedule.slice(0, 80).map((entry, i) => (
                      <tr key={`${entry}-${i}`} className="border-b border-zinc-800/50">
                        <td className="py-1.5 px-2 text-xs">{entry.lineId}</td>
                        <td className="py-1.5 px-2 text-xs">{entry.from}</td>
                        <td className="py-1.5 px-2 text-xs">{entry.to}</td>
                        <td className="py-1.5 px-2 text-xs font-mono">{entry.bearing_dms}</td>
                        <td className="py-1.5 px-2 text-xs text-right">{entry.distance_m.toFixed(2)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {computedBearingSchedule.length > 80 && (
                  <p className="text-xs text-zinc-500 mt-2 text-center">
                    Showing 80 of {computedBearingSchedule.length} entries
                  </p>
                )}
              </div>
            </div>
          )}

          <button
            onClick={prevStep}
            className="flex items-center gap-2 px-6 py-3 border border-[var(--border-color)] rounded-lg text-zinc-300 hover:border-[var(--accent)]/50"
          >
            <ChevronLeft className="h-4 w-4" />
            Back to Edit
          </button>
        </div>
      )}
    </div>
  );
}

'use client'

import { useState, useEffect } from 'react'
import MutationPlanGenerator from '@/components/mutationplan/MutationPlanGenerator'
import type { MutationPlot } from '@/lib/reports/surveyPlan/formNo3Types'

/**
 * ProjectMutationPlan — wrapper that connects MutationPlanGenerator to a project.
 *
 * Fetches the project's most recent deed plan from /api/project/[id]/deed-plans
 * and converts its boundary points into a MutationPlot[] passed directly to
 * MutationPlanGenerator via the `initialPlots` prop.
 *
 * This is the cadastral integration: a surveyor generates a deed plan,
 * then creates a mutation (subdivision, amalgamation) from that deed plan's
 * boundary without re-entering coordinates.
 *
 * Usage:
 *   <ProjectMutationPlan projectId="abc-123" />
 *   // or as a route: /tools/mutation-plan?project=abc-123
 */

interface ProjectMutationPlanProps {
  projectId: string
}

interface DeedPlanRecord {
  id: string
  survey_number: string | null
  parcel_number: string | null
  locality: string | null
  area_sqm: number | null
  scale: number | null
  input_data: {
    boundaryPoints?: Array<{
      id: string
      easting: number
      northing: number
      markType?: string
      markStatus?: string
      description?: string
    }>
    surveyNumber?: string
    parcelNumber?: string
    locality?: string
    scale?: number
    utmZone?: number
    hemisphere?: string
  } | null
  created_at: string
}

export default function ProjectMutationPlan({ projectId }: ProjectMutationPlanProps) {
  const [loaded, setLoaded] = useState(false)
  const [initialPlots, setInitialPlots] = useState<MutationPlot[] | null>(null)
  const [deedPlanInfo, setDeedPlanInfo] = useState<{
    parcelNumber: string | null
    surveyNumber: string | null
    areaHa: number | null
  } | null>(null)

  useEffect(() => {
    let cancelled = false

    async function fetchDeedPlan() {
      try {
        const res = await fetch(`/api/project/${projectId}/deed-plans`)
        if (!res.ok) {
          if (!cancelled) setLoaded(true)
          return
        }
        const json = await res.json()
        const plans: DeedPlanRecord[] = json.data || []
        if (plans.length === 0) {
          if (!cancelled) setLoaded(true)
          return
        }

        // Take the most recent deed plan (already ordered DESC by API)
        const latest = plans[0]
        const boundaryPoints = latest.input_data?.boundaryPoints || []

        if (boundaryPoints.length < 3) {
          if (!cancelled) setLoaded(true)
          return
        }

        // Build a MutationPlot directly — no sessionStorage bridge needed.
        const plot: MutationPlot = {
          id: latest.parcel_number || latest.survey_number || 'parent',
          boundaryPoints: boundaryPoints.map(p => ({
            easting: p.easting,
            northing: p.northing,
            beacon: p.id,
          })),
          area_ha: latest.area_sqm ? latest.area_sqm / 10000 : 0,
          isApprox: false,
          seriesLabel: latest.parcel_number || 'Parent',
        }

        if (!cancelled) {
          setInitialPlots([plot])
          setDeedPlanInfo({
            parcelNumber: latest.parcel_number,
            surveyNumber: latest.survey_number,
            areaHa: latest.area_sqm ? latest.area_sqm / 10000 : null,
          })
          setLoaded(true)
        }
      } catch {
        // silent fail — generator runs without initial plots
        if (!cancelled) setLoaded(true)
      }
    }

    if (projectId && projectId !== 'new') {
      fetchDeedPlan()
    } else {
      setLoaded(true)
    }

    return () => { cancelled = true }
  }, [projectId])

  if (!loaded) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="font-mono text-xs text-[var(--text-muted)] tracking-[0.04em] uppercase">
          Loading project deed plan data...
        </div>
      </div>
    )
  }

  return (
    <div>
      {deedPlanInfo && (
        <div className="max-w-7xl mx-auto px-4 mb-4">
          <div className="border border-[var(--accent)]/30 bg-[var(--accent)]/5 p-3 rounded-md flex items-center gap-3">
            <svg className="w-4 h-4 text-[var(--accent)] shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M13.16 6.02a3 3 0 11-1.59 5.79 3 3 0 011.59-5.79zM12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
            </svg>
            <p className="text-xs text-[var(--text-secondary)]">
              <span className="font-mono text-[var(--accent)]">Project linked.</span>{' '}
              Deed plan
              {deedPlanInfo.parcelNumber && ` ${deedPlanInfo.parcelNumber}`}
              {deedPlanInfo.surveyNumber && ` (Survey ${deedPlanInfo.surveyNumber})`}
              {deedPlanInfo.areaHa !== null && ` · ${deedPlanInfo.areaHa.toFixed(4)} ha`}
              {' '}boundary pre-loaded as the parent plot on step 2.
              Proceed to subdivide or amalgamate directly — no CSV import needed.
            </p>
          </div>
        </div>
      )}
      <MutationPlanGenerator initialPlots={initialPlots ?? undefined} />
    </div>
  )
}

'use client'

/**
 * NotificationBell — Floating notification icon with unread count badge
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { useRouter } from 'next/navigation'
import {
  Bell, CheckCheck, Trash2, Loader2,
  Info, AlertTriangle, CheckCircle2, XCircle,
  FileText, MessageSquare, CreditCard, Users, Settings as SettingsIcon,
} from 'lucide-react'

interface Notification {
  id: string
  type: 'info' | 'success' | 'warning' | 'error'
  category: string
  title: string
  message: string
  action_url?: string | null
  action_label?: string | null
  read_at: string | null
  created_at: string
}

const TYPE_ICONS: Record<string, typeof Info> = {
  info: Info, success: CheckCircle2, warning: AlertTriangle, error: XCircle,
}

const CATEGORY_ICONS: Record<string, typeof Info> = {
  peer_review: FileText, payment: CreditCard, project_share: Users,
  message: MessageSquare, system: SettingsIcon,
}

function timeAgo(dateStr: string): string {
  const date = new Date(dateStr)
  const seconds = Math.floor((Date.now() - date.getTime()) / 1000)
  if (seconds < 60) return 'just now'
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ago`
  const days = Math.floor(hours / 24)
  if (days < 7) return `${days}d ago`
  return date.toLocaleDateString('en-KE', { month: 'short', day: 'numeric' })
}

export function NotificationBell() {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [unreadCount, setUnreadCount] = useState(0)
  const [loading, setLoading] = useState(false)
  const dropdownRef = useRef<HTMLDivElement>(null)

  const fetchNotifications = useCallback(async () => {
    try {
      const res = await fetch('/api/notifications?limit=20')
      if (!res.ok) return
      const data = await res.json()
      setNotifications(data.data?.notifications || [])
      setUnreadCount(data.data?.unreadCount || 0)
    } catch (err) {}
  }, [])

  useEffect(() => {
    fetchNotifications()
    const interval = setInterval(fetchNotifications, 60000)
    return () => clearInterval(interval)
  }, [fetchNotifications])

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const handleMarkRead = useCallback(async (id: string, actionUrl?: string | null) => {
    try {
      await fetch('/api/notifications', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id }),
      })
      setNotifications(prev =>
        prev.map(n => n.id === id ? { ...n, read_at: new Date().toISOString() } : n)
      )
      setUnreadCount(prev => Math.max(0, prev - 1))
      if (actionUrl) {
        router.push(actionUrl)
        setOpen(false)
      }
    } catch (err) {}
  }, [router])

  const handleMarkAllRead = useCallback(async () => {
    try {
      await fetch('/api/notifications', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ all: true }),
      })
      setNotifications(prev => prev.map(n => ({ ...n, read_at: n.read_at || new Date().toISOString() })))
      setUnreadCount(0)
    } catch (err) {}
  }, [])

  const handleDelete = useCallback(async (id: string, e: React.MouseEvent) => {
    e.stopPropagation()
    try {
      await fetch(`/api/notifications?id=${id}`, { method: 'DELETE' })
      setNotifications(prev => prev.filter(n => n.id !== id))
    } catch (err) {}
  }, [])

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => { setOpen(!open); if (!open) fetchNotifications() }}
        className="relative w-10 h-10 flex items-center justify-center rounded-lg text-gray-400 hover:text-white hover:bg-white/[0.06] transition-colors"
        aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ''}`}
      >
        <Bell className="w-5 h-5" />
        {unreadCount > 0 && (
          <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] flex items-center justify-center px-1 rounded-full bg-red-500 text-white text-[9px] font-bold animate-in zoom-in duration-200">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div className="absolute right-0 top-12 w-[360px] max-w-[calc(100vw-2rem)] bg-[#0d0d14]/95 backdrop-blur-2xl border border-white/[0.08] rounded-xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
          <div className="flex items-center justify-between px-4 py-3 border-b border-white/[0.06]">
            <span className="text-sm font-semibold text-white">Notifications</span>
            {unreadCount > 0 && (
              <button
                onClick={handleMarkAllRead}
                className="flex items-center gap-1 text-[10px] text-gray-400 hover:text-white transition-colors"
              >
                <CheckCheck className="w-3 h-3" />
                Mark all read
              </button>
            )}
          </div>

          <div className="max-h-[400px] overflow-y-auto">
            {loading && (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="w-5 h-5 text-gray-500 animate-spin" />
              </div>
            )}

            {!loading && notifications.length === 0 && (
              <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
                <Bell className="w-8 h-8 text-gray-600 mb-2" />
                <p className="text-sm text-gray-500">No notifications yet</p>
                <p className="text-[10px] text-gray-600 mt-1">
                  You&apos;ll see peer review requests, payment confirmations, and updates here.
                </p>
              </div>
            )}

            {!loading && notifications.map(notif => {
              const TypeIcon = TYPE_ICONS[notif.type] || Info
              const CatIcon = CATEGORY_ICONS[notif.category] || TypeIcon
              const Icon = CatIcon
              const isUnread = !notif.read_at

              return (
                <div
                  key={notif.id}
                  onClick={() => handleMarkRead(notif.id, notif.action_url)}
                  className={`flex items-start gap-3 px-4 py-3 border-b border-white/[0.04] cursor-pointer hover:bg-white/[0.03] transition-colors group ${
                    isUnread ? 'bg-blue-500/[0.03]' : ''
                  }`}
                >
                  <div className={`shrink-0 w-8 h-8 rounded-lg flex items-center justify-center ${
                    notif.type === 'error' ? 'bg-red-500/10' :
                    notif.type === 'warning' ? 'bg-amber-500/10' :
                    notif.type === 'success' ? 'bg-emerald-500/10' :
                    'bg-blue-500/10'
                  }`}>
                    <Icon className={`w-4 h-4 ${
                      notif.type === 'error' ? 'text-red-400' :
                      notif.type === 'warning' ? 'text-amber-400' :
                      notif.type === 'success' ? 'text-emerald-400' :
                      'text-blue-400'
                    }`} />
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-medium text-white truncate">{notif.title}</span>
                      {isUnread && (
                        <span className="w-2 h-2 rounded-full bg-blue-400 shrink-0" />
                      )}
                    </div>
                    <p className="text-[11px] text-gray-400 mt-0.5 line-clamp-2">{notif.message}</p>
                    <div className="flex items-center justify-between mt-1">
                      <span className="text-[9px] text-gray-600">{timeAgo(notif.created_at)}</span>
                      {notif.action_label && (
                        <span className="text-[9px] text-blue-400 font-medium">{notif.action_label} →</span>
                      )}
                    </div>
                  </div>

                  <button
                    onClick={(e) => handleDelete(notif.id, e)}
                    className="shrink-0 w-6 h-6 flex items-center justify-center rounded text-gray-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-all"
                    title="Delete"
                  >
                    <Trash2 className="w-3 h-3" />
                  </button>
                </div>
              )
            })}
          </div>

          {notifications.length > 0 && (
            <div className="border-t border-white/[0.06] px-4 py-2.5">
              <button
                onClick={() => { router.push('/notifications'); setOpen(false) }}
                className="w-full text-center text-xs text-gray-400 hover:text-white transition-colors"
              >
                View all notifications
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * OnboardingTour — Interactive guided walkthrough for new users
 *
 * Features:
 * - Step-by-step tour with spotlight overlay
 * - Highlights key UI elements with descriptions
 * - Progress indicator (step X of Y)
 * - Skip / Next / Back navigation
 * - Persists completion in localStorage
 * - Auto-starts on first visit to dashboard
 *
 * Tour steps:
 * 1. Welcome to METARDU
 * 2. Dashboard — your projects
 * 3. Map — survey workflow
 * 4. Field Book — capture observations
 * 5. Tools — COGO, traverse, leveling
 * 6. Documents — generate deed plans
 * 7. Community — connect with surveyors
 * 8. Search (Cmd+K) — quick navigation
 * 9. Notifications — stay updated
 */

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import {
  X, ChevronLeft, ChevronRight, Check,
  LayoutDashboard, Map, FileText, Wrench, Users, Search, Bell,
} from 'lucide-react'

interface TourStep {
  title: string
  description: string
  icon: typeof LayoutDashboard
  href?: string
  highlight?: string // CSS selector to highlight
}

const TOUR_STEPS: TourStep[] = [
  {
    title: 'Welcome to METARDU',
    description: 'East Africa\'s professional surveying platform. This quick tour will show you the key features. You can skip this anytime and come back later.',
    icon: LayoutDashboard,
  },
  {
    title: 'Your Dashboard',
    description: 'This is your home base. Create new projects, view recent activity, and track your survey work. Each project contains its own map, field book, and documents.',
    icon: LayoutDashboard,
    href: '/dashboard',
  },
  {
    title: 'The Survey Map',
    description: 'The map is where you draw parcels, measure distances, and run COGO computations. Use the floating dock on the left to access tools. On mobile, use two fingers to pan.',
    icon: Map,
    href: '/map',
  },
  {
    title: 'Digital Field Book',
    description: 'Capture traverse, leveling, and control observations directly in the field. Works offline — your data syncs when you\'re back online. On mobile, use the bottom bar to take measurements.',
    icon: FileText,
    href: '/fieldbook',
  },
  {
    title: 'Survey Tools',
    description: '60+ calculation tools for every survey workflow: COGO, traverse adjustment, leveling, coordinate transformation, curves, areas, volumes, and more.',
    icon: Wrench,
    href: '/tools/cogo',
  },
  {
    title: 'Document Generation',
    description: 'Generate Kenya-compliant deed plans, Form C-22, beacon certificates, and traverse sheets. Free tier includes METARDU watermark; paid plans can add a company logo.',
    icon: FileText,
    href: '/documents',
  },
  {
    title: 'Surveyor Community',
    description: 'Connect with peers, submit plans for review, browse the equipment market, and track your CPD progress.',
    icon: Users,
    href: '/community',
  },
  {
    title: 'Quick Search',
    description: 'Press Cmd+K (Mac) or Ctrl+K (Windows) anywhere to open the command palette. Search across projects, parcels, tools, and pages instantly.',
    icon: Search,
  },
  {
    title: 'Notifications',
    description: 'Click the bell icon to see peer review requests, payment confirmations, and system updates. You\'re all set — welcome aboard!',
    icon: Bell,
  },
]

const STORAGE_KEY = 'metardu:onboarding-completed'

export function OnboardingTour() {
  const router = useRouter()
  const [active, setActive] = useState(false)
  const [step, setStep] = useState(0)

  // Check if tour should auto-start
  // UI-12 (2026-07-24): Also check the checklist's dismissed state so
  // the tour doesn't fire before the user has seen the checklist.
  useEffect(() => {
    if (typeof window === 'undefined') return
    const completed = localStorage.getItem(STORAGE_KEY)
    const skipped = localStorage.getItem('metardu:onboarding-skipped')
    const checklistDismissed = localStorage.getItem('metardu_onboarding_dismissed')
    if (!completed && !skipped && checklistDismissed) {
      // Only start the tour AFTER the checklist has been dismissed —
      // otherwise the user gets two onboarding overlays at once.
      const timer = setTimeout(() => setActive(true), 1500)
      return () => clearTimeout(timer)
    }
  }, [])

  const handleClose = useCallback(() => {
    setActive(false)
  }, [])

  const handleSkip = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, new Date().toISOString())
    localStorage.setItem('metardu:onboarding-skipped', 'true')
    // AUDIT FIX (M18, 2026-07-02): Persist to server so cross-device users
    // don't see the tour again. Fire-and-forget — localStorage is the
    // immediate source of truth; the server record prevents the tour from
    // reappearing on a new device.
    fetch('/api/user/onboarding', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'skip' }),
      credentials: 'include',
    }).catch(() => { /* silent fail — localStorage is enough */ })
    setActive(false)
  }, [])

  const handleComplete = useCallback(() => {
    localStorage.setItem(STORAGE_KEY, new Date().toISOString())
    // AUDIT FIX (M18, 2026-07-02): Persist completion to server.
    fetch('/api/user/onboarding', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'complete' }),
      credentials: 'include',
    }).catch(() => { /* silent fail — localStorage is enough */ })
    setActive(false)
  }, [])

  const handleNext = useCallback(() => {
    const currentStep = TOUR_STEPS[step]
    if (step < TOUR_STEPS.length - 1) {
      // Navigate to the step's href if provided
      if (currentStep.href) {
        router.push(currentStep.href)
      }
      setStep(prev => prev + 1)
    } else {
      handleComplete()
    }
  }, [step, router, handleComplete])

  const handleBack = useCallback(() => {
    if (step > 0) {
      const prevStep = TOUR_STEPS[step - 1]
      if (prevStep.href) {
        router.push(prevStep.href)
      }
      setStep(prev => prev - 1)
    }
  }, [step, router])

  // Close the tour with Escape regardless of focus location
  // (handled at document level — the dialog element itself is not
  // focusable, so a local onKeyDown would only fire from child buttons)
  useEffect(() => {
    if (!active) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handleSkip()
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [active, handleSkip])

  if (!active) return null

  const currentStep = TOUR_STEPS[step]
  const Icon = currentStep.icon
  const isLast = step === TOUR_STEPS.length - 1
  const isFirst = step === 0

  return (
    <>
      {/* AUDIT FIX (M16, 2026-07-02): Added ARIA attributes for accessibility.
          - role="dialog" + aria-modal on the tour card (screen readers announce it as a dialog)
          - aria-labelledby pointing to the step title
          - aria-label on the close button
          - The backdrop no longer dismisses on click (prevents accidental dismissal)
            — users must click Skip or press Escape. */}

      {/* Backdrop overlay — no onClick (prevents accidental dismissal) */}
      <div
        className="fixed inset-0 z-[9990] bg-black/70 backdrop-blur-sm"
        aria-hidden="true"
      />

      {/* Tour card */}
      <div
        className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[9991] w-[440px] max-w-[calc(100vw-2rem)]"
        role="dialog"
        aria-modal="true"
        aria-labelledby="tour-title"
      >
        <div className="bg-[#0d0d14]/95 backdrop-blur-2xl border border-[#D17B47]/30 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
          {/* Progress bar */}
          <div className="h-1 bg-white/[0.06]">
            <div
              className="h-full bg-[#D17B47] transition-all duration-300"
              style={{ width: `${((step + 1) / TOUR_STEPS.length) * 100}%` }}
            />
          </div>

          {/* Header */}
          <div className="flex items-center justify-between px-5 pt-4 pb-2">
            <div className="flex items-center gap-2">
              <span className="text-[10px] text-gray-500 uppercase tracking-wider font-semibold">
                Step {step + 1} of {TOUR_STEPS.length}
              </span>
            </div>
            <button
              onClick={handleSkip}
              className="w-7 h-7 flex items-center justify-center rounded-lg text-gray-400 hover:text-white hover:bg-white/[0.06] transition-colors"
              title="Skip tour"
              aria-label="Skip onboarding tour"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Content */}
          <div className="px-5 pb-5 space-y-3">
            <div className="flex items-start gap-3">
              <div className="shrink-0 w-12 h-12 rounded-xl bg-[#D17B47]/10 border border-[#D17B47]/20 flex items-center justify-center">
                <Icon className="w-6 h-6 text-[#D17B47]" />
              </div>
              <div className="flex-1 pt-1">
                <h3 id="tour-title" className="text-base font-bold text-white">{currentStep.title}</h3>
                <p className="text-xs text-gray-400 mt-1 leading-relaxed">{currentStep.description}</p>
              </div>
            </div>

            {/* Step dots */}
            <div className="flex items-center justify-center gap-1.5 pt-2">
              {TOUR_STEPS.map((_, i) => (
                <div
                  key={i}
                  className={`h-1.5 rounded-full transition-all duration-300 ${
                    i === step ? 'w-6 bg-[#D17B47]' : i < step ? 'w-1.5 bg-[#D17B47]/50' : 'w-1.5 bg-white/10'
                  }`}
                />
              ))}
            </div>

            {/* Actions */}
            <div className="flex items-center justify-between pt-2">
              <button
                onClick={handleSkip}
                className="text-[11px] text-gray-500 hover:text-gray-300 transition-colors"
              >
                Skip tour
              </button>
              <div className="flex items-center gap-2">
                {!isFirst && (
                  <button
                    onClick={handleBack}
                    className="flex items-center gap-1 px-3 h-8 rounded-lg bg-white/[0.04] border border-white/[0.06] text-xs text-gray-300 hover:bg-white/[0.08] transition-colors"
                  >
                    <ChevronLeft className="w-3.5 h-3.5" />
                    Back
                  </button>
                )}
                <button
                  onClick={handleNext}
                  className="flex items-center gap-1 px-4 h-8 rounded-lg bg-[#D17B47] hover:bg-[#FFB84D] text-black text-xs font-semibold transition-colors"
                >
                  {isLast ? (
                    <>
                      <Check className="w-3.5 h-3.5" />
                      Get Started
                    </>
                  ) : (
                    <>
                      Next
                      <ChevronRight className="w-3.5 h-3.5" />
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

/**
 * Hook to check if onboarding has been completed
 */
export function useOnboardingStatus() {
  const [completed, setCompleted] = useState(false)

  useEffect(() => {
    setCompleted(!!localStorage.getItem(STORAGE_KEY))
  }, [])

  return completed
}

/**
 * Reset onboarding (for testing or re-triggering)
 */
export function resetOnboarding() {
  localStorage.removeItem(STORAGE_KEY)
  localStorage.removeItem('metardu:onboarding-skipped')
}

'use client';

import { useState } from 'react'
import { ArrowRightLeft, Copy, Check } from 'lucide-react'
import type { DatumCode, TransformedCoord } from '@/types/gnss'

const DATUM_OPTIONS: { value: DatumCode; label: string }[] = [
  { value: 'WGS84', label: 'WGS84 (GPS)' },
  { value: 'ARC1960', label: 'ARC1960 (Kenya National)' },
  { value: 'CASSINI', label: 'Cassini-Soldner (Legacy)' },
  { value: 'GEOGRAPHIC_WGS84', label: 'Lat/Lon WGS84' },
  { value: 'GEOGRAPHIC_ARC', label: 'Lat/Lon ARC1960' },
  { value: 'UTM', label: 'UTM (specify zone)' },
]

export default function CoordinateTransformer() {
  const [mode, setMode] = useState<'single' | 'batch'>('single')
  const [fromDatum, setFromDatum] = useState<DatumCode>('WGS84')
  const [toDatum, setToDatum] = useState<DatumCode>('ARC1960')
  const [fromZone, setFromZone] = useState('37')
  const [toZone, setToZone] = useState('37')
  const [fromHemisphere, setFromHemisphere] = useState<'N' | 'S'>('S')
  const [toHemisphere, setToHemisphere] = useState<'N' | 'S'>('S')
  
  // Single mode
  const [x, setX] = useState('')
  const [y, setY] = useState('')
  const [z, setZ] = useState('')
  
  // Batch mode
  const [batchInput, setBatchInput] = useState('')
  
  const [results, setResults] = useState<TransformedCoord[]>([])
  const [loading, setLoading] = useState(false)
  const [copied, setCopied] = useState(false)

  const transform = async () => {
    setLoading(true)
    try {
      let coords: { id?: string; x: number; y: number; z?: number }[] = []
      
      if (mode === 'single') {
        coords = [{ x: parseFloat(x), y: parseFloat(y), z: z ? parseFloat(z) : undefined }]
      } else {
        // Parse batch input (CSV: id,x,y,z)
        coords = batchInput.split('\n')
          .filter((line: any) => line.trim())
          .map((line, i) => {
            const parts = line.split(',')
            return {
              id: parts[0] || String(i + 1),
              x: parseFloat(parts[1]),
              y: parseFloat(parts[2]),
              z: parts[3] ? parseFloat(parts[3]) : undefined
            }
          })
      }

      const response = await fetch('/api/transform', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          coordinates: coords,
          fromDatum,
          toDatum,
          fromZone: fromDatum === 'UTM' ? parseInt(fromZone) : undefined,
          fromHemisphere: fromDatum === 'UTM' ? fromHemisphere : undefined,
          toZone: toDatum === 'UTM' ? parseInt(toZone) : undefined,
          toHemisphere: toDatum === 'UTM' ? toHemisphere : undefined
        })
      })

      const data = await response.json()
      if (!response.ok) throw new Error(data.error)
      
      setResults(data.results || [])
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const copyResults = () => {
    const text = results.map((r: any) => 
      `${r.id || ''},${r.x?.toFixed(4)},${r.y?.toFixed(4)}${r.z !== undefined ? ',' + r.z.toFixed(3) : ''}`
    ).join('\n')
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <div className="space-y-6">
      {/* Mode Toggle */}
      <div className="flex gap-2">
        <button
          onClick={() => setMode('single')}
          className={`px-4 py-2 rounded-lg text-sm ${mode === 'single' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)]'}`}
        >
          Single
        </button>
        <button
          onClick={() => setMode('batch')}
          className={`px-4 py-2 rounded-lg text-sm ${mode === 'batch' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)]'}`}
        >
          Batch (CSV)
        </button>
      </div>

      {/* Datum Selectors */}
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium mb-2" htmlFor="from-datum">From Datum</label>
          <select id="from-datum"
            value={fromDatum}
            onChange={e => setFromDatum(e.target.value as DatumCode)}
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg"
          >
            {DATUM_OPTIONS.map((d: any) => (
              <option key={d.value} value={d.value}>{d.label}</option>
            ))}
          </select>
          {fromDatum === 'UTM' && (
            <div className="flex gap-2 mt-2">
              <input
                type="number"
                aria-label="UTM Zone" placeholder="Zone"
                value={fromZone}
                onChange={e => setFromZone(e.target.value)}
                className="w-20 px-2 py-1 bg-[var(--bg-tertiary)] border rounded text-sm"
              />
              <select
                value={fromHemisphere}
                onChange={e => setFromHemisphere(e.target.value as 'N' | 'S')}
                className="px-2 py-1 bg-[var(--bg-tertiary)] border rounded text-sm"
              >
                <option value="N">N</option>
                <option value="S">S</option>
              </select>
            </div>
          )}
        </div>
        
        <div>
          <label className="block text-sm font-medium mb-2" htmlFor="to-datum">To Datum</label>
          <select id="to-datum"
            value={toDatum}
            onChange={e => setToDatum(e.target.value as DatumCode)}
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg"
          >
            {DATUM_OPTIONS.map((d: any) => (
              <option key={d.value} value={d.value}>{d.label}</option>
            ))}
          </select>
          {toDatum === 'UTM' && (
            <div className="flex gap-2 mt-2">
              <input
                type="number"
                aria-label="UTM Zone" placeholder="Zone"
                value={toZone}
                onChange={e => setToZone(e.target.value)}
                className="w-20 px-2 py-1 bg-[var(--bg-tertiary)] border rounded text-sm"
              />
              <select
                value={toHemisphere}
                onChange={e => setToHemisphere(e.target.value as 'N' | 'S')}
                className="px-2 py-1 bg-[var(--bg-tertiary)] border rounded text-sm"
              >
                <option value="N">N</option>
                <option value="S">S</option>
              </select>
            </div>
          )}
        </div>
      </div>

      {/* Input */}
      {mode === 'single' ? (
        <div className="grid grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium mb-2" htmlFor="x-easting">X / Easting</label>
            <input id="x-easting"
              type="number"
              value={x}
              onChange={e => setX(e.target.value)}
              aria-label="500000" placeholder="500000"
              className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg"
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-2" htmlFor="y-northing">Y / Northing</label>
            <input id="y-northing"
              type="number"
              value={y}
              onChange={e => setY(e.target.value)}
              aria-label="9900000" placeholder="9900000"
              className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg"
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-2" htmlFor="z-elev-opt">Z / Elev (opt)</label>
            <input id="z-elev-opt"
              type="number"
              value={z}
              onChange={e => setZ(e.target.value)}
              aria-label="1500" placeholder="1500"
              className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg"
            />
          </div>
        </div>
      ) : (
        <div>
          <label className="block text-sm font-medium mb-2" htmlFor="paste-csv-id-x-y-z-per-line">Paste CSV (id,x,y,z per line)</label>
          <textarea
            value={batchInput}
            onChange={e => setBatchInput(e.target.value)}
            placeholder="1,500000,9900000,1500&#10;2,500100,9900100,1510"
            rows={6}
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg font-mono text-sm"
          />
        </div>
      )}

      {/* Transform Button */}
      <button
        onClick={transform}
        disabled={loading || (mode === 'single' ? !x || !y : !batchInput)}
        className="w-full py-3 bg-[var(--accent)] text-black font-semibold rounded-lg disabled:opacity-50 flex items-center justify-center gap-2"
      >
        <ArrowRightLeft className="w-4 h-4" />
        {loading ? 'Transforming...' : 'Transform'}
      </button>

      {/* Results */}
      {results.length > 0 && (
        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <h3 className="font-semibold">Results</h3>
            <button
              onClick={copyResults}
              className="px-3 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm flex items-center gap-1"
            >
              {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
              {copied ? 'Copied!' : 'Copy CSV'}
            </button>
          </div>
          
          <div className="overflow-x-auto max-h-64 overflow-y-auto">
            <table className="w-full text-sm">
              <thead className="bg-[var(--bg-tertiary)] sticky top-0">
                <tr>
                  <th className="text-left p-2">ID</th>
                  <th className="text-right p-2">X</th>
                  <th className="text-right p-2">Y</th>
                  <th className="text-right p-2">Z</th>
                  <th className="text-right p-2">Round-trip</th>
                </tr>
              </thead>
              <tbody>
                {results.map((r, i) => (
                  <tr key={r.id} className="border-b border-[var(--border-color)]">
                    <td className="p-2">{r.id || i + 1}</td>
                    <td className="p-2 text-right font-mono">{r.x?.toFixed(4)}</td>
                    <td className="p-2 text-right font-mono">{r.y?.toFixed(4)}</td>
                    <td className="p-2 text-right font-mono">{r.z?.toFixed(3) || '-'}</td>
                    <td className="p-2 text-right font-mono text-[var(--text-muted)]">
                      {r.roundTripError ? `${r.roundTripError.toFixed(2)}mm` : '-'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Upload, FileText, MapPin, Download, Loader2 , AlertTriangle } from 'lucide-react'
import type { GNSSBaseline } from '@/types/gnss'

interface FileWithLabel {
  file: File
  stationLabel: string
}

export default function GNSSProcessor({ projectId = '' }: { projectId?: string }) {
  const router = useRouter()
  const [files, setFiles] = useState<FileWithLabel[]>([])
  const [processing, setProcessing] = useState(false)
  const [status, setStatus] = useState('')
  const [results, setResults] = useState<GNSSBaseline[]>([])
  const [error, setError] = useState('')

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files).map((file: any) => ({
        file,
        stationLabel: ''
      }))
      setFiles(prev => [...prev, ...newFiles])
    }
  }

  const updateStationLabel = (index: number, label: string) => {
    setFiles(prev => prev.map((f, i) => 
      i === index ? { ...f, stationLabel: label } : f
    ))
  }

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index))
  }

  const processBaselines = async () => {
    const hasLabels = files.every(f => f.stationLabel.trim())
    if (!hasLabels) {
      setError('Please label all stations before processing')
      return
    }

    setProcessing(true)
    setStatus('Uploading files...')
    setError('')

    try {
      setStatus('Processing baselines...')
      
      const formData = new FormData()
      files.forEach((f: any) => formData.append('files', f.file))
      formData.append('projectId', projectId)
      formData.append('stationLabels', JSON.stringify(files.map((f: any) => f.stationLabel)))

      const response = await fetch('/api/gnss/process', {
        method: 'POST',
        body: JSON.stringify({
          projectId,
          files: files.map((f: any) => ({
            filename: f.file.name,
            stationId: f.stationLabel,
            fileType: f.file.name.endsWith('.nav') ? 'NAV' : 'OBS',
            sizeBytes: f.file.size,
            storagePath: ''
          })),
          stationLabels: files.map((f: any) => f.stationLabel)
        })
      })

      const data = await response.json()
      
      if (!response.ok) {
        throw new Error(data.error || 'Processing failed')
      }

      setResults(data.results || [])
      
      if (data.status === 'simulated') {
        setError('Simulation mode — upload valid RINEX files for real processing')
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Processing failed')
    } finally {
      setProcessing(false)
      setStatus('')
    }
  }

  const fixedCount = results.filter((r: any) => r.fixed).length
  const rmsValues = results.map((r: any) => r.rmsError)
  const bestRms = rmsValues.length ? Math.min(...rmsValues) : 0
  const worstRms = rmsValues.length ? Math.max(...rmsValues) : 0

  return (
    <div className="space-y-6">
      {/* Upload Section */}
      <div className="border-2 border-dashed border-[var(--border-color)] rounded-xl p-6 text-center">
        <Upload className="w-10 h-10 mx-auto mb-3 text-[var(--text-muted)]" />
        <p className="text-sm mb-3">Drop RINEX files (.obs, .nav, .rnx, .21o)</p>
        <input
          type="file"
          multiple
          accept=".obs,.nav,.rnx,.21o,.24o"
          onChange={handleFileUpload}
          className="hidden"
          id="rinex-upload"
        />
        <label
          htmlFor="rinex-upload"
          className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm cursor-pointer inline-block"
        >
          Select Files
        </label>
      </div>

      {/* File List */}
      {files.length > 0 && (
        <div className="space-y-2">
          <h3 className="font-semibold text-sm">Uploaded Files</h3>
          {files.map((f, i) => (
            <div key={`${f}-${i}`} className="flex items-center gap-3 p-3 bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg">
              <FileText className="w-5 h-5 text-[var(--text-muted)]" />
              <div className="flex-1">
                <div className="text-sm font-medium">{f.file.name}</div>
                <div className="text-xs text-[var(--text-muted)]">
                  {(f.file.size / 1024).toFixed(1)} KB
                </div>
              </div>
              <input
                type="text"
                aria-label="Station label" placeholder="e.g. BASE, ROVER1"
                value={f.stationLabel}
                onChange={e => updateStationLabel(i, e.target.value)}
                className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm w-48"
              />
              <button
                onClick={() => removeFile(i)}
                className="text-red-500 hover:text-red-600"
              >
                [x]
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Process Button */}
      <button
        onClick={processBaselines}
        disabled={processing || files.length < 2}
        className="w-full py-3 bg-[var(--accent)] text-black font-semibold rounded-lg disabled:opacity-50"
      >
        {processing ? (
          <span className="flex items-center justify-center gap-2">
            <Loader2 className="w-4 h-4 animate-spin" />
            {status || 'Processing...'}
          </span>
        ) : (
          'Process Baselines'
        )}
      </button>

      {/* Error */}
      {error && (
        <div className="p-4 bg-amber-50 border border-amber-200 rounded-lg text-amber-700 text-sm">
          {error}
        </div>
      )}

      {/* Results */}
      {results.length > 0 && (
        <div className="space-y-4">
          {/* Summary Cards */}
          <div className="grid grid-cols-4 gap-4">
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-4 text-center">
              <div className="text-2xl font-bold">{results.length}</div>
              <div className="text-xs text-[var(--text-muted)]">Baselines</div>
            </div>
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-4 text-center">
              <div className="text-2xl font-bold text-green-600">{fixedCount}</div>
              <div className="text-xs text-[var(--text-muted)]">Fixed</div>
            </div>
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-4 text-center">
              <div className="text-2xl font-bold">{(bestRms * 1000).toFixed(1)}mm</div>
              <div className="text-xs text-[var(--text-muted)]">Best RMS</div>
            </div>
            <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-4 text-center">
              <div className="text-2xl font-bold">{(worstRms * 1000).toFixed(1)}mm</div>
              <div className="text-xs text-[var(--text-muted)]">Worst RMS</div>
            </div>
          </div>

          {/* Accuracy Banner */}
          <div className={`p-4 rounded-lg ${fixedCount === results.length ? 'bg-green-50 border border-green-200' : 'bg-amber-50 border border-amber-200'}`}>
            {fixedCount === results.length ? (
              <span className="text-green-700"> All baselines fixed — First Order accuracy achieved</span>
            ) : (
              <span className="text-amber-700"><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> Some baselines are float solutions — not suitable for cadastral work</span>
            )}
          </div>

          {/* Results Table */}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-[var(--bg-tertiary)]">
                <tr>
                  <th className="text-left p-3">FROM</th>
                  <th className="text-left p-3">TO</th>
                  <th className="text-right p-3">DIST (m)</th>
                  <th className="text-right p-3">RMS</th>
                  <th className="text-right p-3">RATIO</th>
                  <th className="text-center p-3">FIXED</th>
                  <th className="text-center p-3">CLASS</th>
                </tr>
              </thead>
              <tbody>
                {results.map((r, i) => (
                  <tr key={`${r}-${i}`} className={`border-b border-[var(--border-color)] ${r.fixed ? 'bg-green-50' : 'bg-amber-50'}`}>
                    <td className="p-3">{r.fromStation}</td>
                    <td className="p-3">{r.toStation}</td>
                    <td className="p-3 text-right font-mono">{r.distance.toFixed(3)}</td>
                    <td className="p-3 text-right font-mono">{(r.rmsError * 1000).toFixed(1)}mm</td>
                    <td className="p-3 text-right font-mono">{r.ratio.toFixed(1)}</td>
                    <td className="p-3 text-center">{r.fixed ? '' : <AlertTriangle className="w-3.5 h-3.5 inline shrink-0 text-amber-500" />}</td>
                    <td className="p-3 text-center">{r.qualityClass}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * BatchParcelImport — Bulk import parcels from CSV/GeoJSON
 *
 * Solves the Mwavumbo Ward problem: importing 200+ parcels with owner data.
 */

import { useState, useCallback, useRef } from 'react'
import {
  Upload, Loader2, CheckCircle2, AlertTriangle,
  Download, Table, Layers, Users,
} from 'lucide-react'
import { processWithProgress } from '@/lib/performance'

interface ParsedParcel {
  id: string
  parcelNumber: string
  ownerName?: string
  ownerId?: string
  lrNumber?: string
  areaHa?: number
  vertices: Array<{ easting: number; northing: number }>
  valid: boolean
  errors: string[]
}

interface BatchParcelImportProps {
  projectId: string
  onImport?: (parcels: ParsedParcel[]) => void
}

export function BatchParcelImport({ projectId, onImport }: BatchParcelImportProps) {
  const [parcels, setParcels] = useState<ParsedParcel[]>([])
  const [parsing, setParsing] = useState(false)
  const [importing, setImporting] = useState(false)
  const [importProgress, setImportProgress] = useState(0)
  const [dragOver, setDragOver] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [importResult, setImportResult] = useState<{ success: number; failed: number } | null>(null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const parseCSV = useCallback((text: string): ParsedParcel[] => {
    const lines = text.split('\n').filter(l => l.trim())
    if (lines.length < 2) return []

    const header = lines[0].split(',').map(h => h.trim().toLowerCase())
    const parcelsMap = new Map<string, ParsedParcel>()

    const colIdx = {
      parcelNumber: header.findIndex(h => h.includes('parcel') || h.includes('plot')),
      easting: header.findIndex(h => h.includes('easting') || h === 'e'),
      northing: header.findIndex(h => h.includes('northing') || h === 'n'),
      ownerName: header.findIndex(h => h.includes('owner') && h.includes('name')),
      ownerId: header.findIndex(h => h.includes('owner') && h.includes('id')),
      lrNumber: header.findIndex(h => h.includes('lr') || h.includes('title')),
      areaHa: header.findIndex(h => h.includes('area') || h.includes('ha')),
    }

    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split(',').map(c => c.trim())
      const parcelNum = colIdx.parcelNumber >= 0 ? cols[colIdx.parcelNumber] : `PARCEL-${i}`
      const easting = colIdx.easting >= 0 ? parseFloat(cols[colIdx.easting]) : NaN
      const northing = colIdx.northing >= 0 ? parseFloat(cols[colIdx.northing]) : NaN

      if (!parcelNum || !isFinite(easting) || !isFinite(northing)) continue

      if (!parcelsMap.has(parcelNum)) {
        parcelsMap.set(parcelNum, {
          id: crypto.randomUUID(),
          parcelNumber: parcelNum,
          ownerName: colIdx.ownerName >= 0 ? cols[colIdx.ownerName] : undefined,
          ownerId: colIdx.ownerId >= 0 ? cols[colIdx.ownerId] : undefined,
          lrNumber: colIdx.lrNumber >= 0 ? cols[colIdx.lrNumber] : undefined,
          areaHa: colIdx.areaHa >= 0 ? parseFloat(cols[colIdx.areaHa]) : undefined,
          vertices: [],
          valid: true,
          errors: [],
        })
      }

      parcelsMap.get(parcelNum)!.vertices.push({ easting, northing })
    }

    const parcels = Array.from(parcelsMap.values())
    for (const parcel of parcels) {
      if (parcel.vertices.length < 3) {
        parcel.errors.push('Needs at least 3 vertices')
        parcel.valid = false
      }
      if (!parcel.parcelNumber) {
        parcel.errors.push('Missing parcel number')
        parcel.valid = false
      }
    }

    return parcels
  }, [])

  const parseGeoJSON = useCallback((text: string): ParsedParcel[] => {
    const geojson = JSON.parse(text)
    if (!geojson.features || !Array.isArray(geojson.features)) return []

    return geojson.features.map((feature: any, idx: number) => {
      const props = feature.properties || {}
      const geom = feature.geometry

      let vertices: Array<{ easting: number; northing: number }> = []

      if (geom.type === 'Polygon') {
        const ring = geom.coordinates[0] || []
        const verts = ring.slice(0, -1)
        vertices = verts.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
      } else if (geom.type === 'MultiPolygon') {
        const ring = geom.coordinates[0]?.[0] || []
        const verts = ring.slice(0, -1)
        vertices = verts.map((c: number[]) => ({ easting: c[0], northing: c[1] }))
      }

      const errors: string[] = []
      if (vertices.length < 3) errors.push('Needs at least 3 vertices')

      return {
        id: crypto.randomUUID(),
        parcelNumber: props.parcel_number || props.parcelNumber || props.name || `PARCEL-${idx + 1}`,
        ownerName: props.owner_name || props.ownerName || props.owner,
        ownerId: props.owner_id || props.ownerId || props.national_id,
        lrNumber: props.lr_number || props.lrNumber || props.title_deed,
        areaHa: props.area_ha ? parseFloat(props.area_ha) : props.area ? parseFloat(props.area) : undefined,
        vertices,
        valid: errors.length === 0,
        errors,
      }
    })
  }, [])

  const handleFile = useCallback(async (file: File) => {
    setParsing(true)
    setError(null)
    setImportResult(null)

    try {
      const text = await file.text()
      const ext = file.name.split('.').pop()?.toLowerCase()

      let parsed: ParsedParcel[] = []
      if (ext === 'geojson' || ext === 'json') {
        parsed = parseGeoJSON(text)
      } else {
        parsed = parseCSV(text)
      }

      setParcels(parsed)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to parse file')
    } finally {
      setParsing(false)
    }
  }, [parseCSV, parseGeoJSON])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragOver(false)
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }, [handleFile])

  const handleImport = useCallback(async () => {
    if (parcels.length === 0) return
    setImporting(true)
    setImportProgress(0)
    setError(null)

    try {
      // For large imports (100+ parcels), process in chunks to avoid UI freeze
      if (parcels.length > 100) {
        const validParcels = parcels.filter(p => p.valid)
        const chunkSize = 50
        const totalChunks = Math.ceil(validParcels.length / chunkSize)

        let totalSuccess = 0
        let totalFailed = 0

        for (let i = 0; i < validParcels.length; i += chunkSize) {
          const chunk = validParcels.slice(i, i + chunkSize)
          const currentChunk = Math.floor(i / chunkSize) + 1

          setImportProgress((currentChunk / totalChunks) * 100)

          try {
            const res = await fetch(`/api/projects/${projectId}/parcels/batch`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                parcels: chunk.map(p => ({
                  parcelNumber: p.parcelNumber,
                  ownerName: p.ownerName,
                  ownerId: p.ownerId,
                  lrNumber: p.lrNumber,
                  areaHa: p.areaHa,
                  vertices: p.vertices,
                })),
              }),
            })
            if (res.ok) {
              const data = await res.json()
              totalSuccess += data.data?.imported || chunk.length
              totalFailed += data.data?.failed || 0
            } else {
              totalFailed += chunk.length
            }
          } catch {
            totalFailed += chunk.length
          }

          // Yield to event loop so UI can update
          await new Promise(resolve => setTimeout(resolve, 0))
        }

        setImportProgress(100)
        setImportResult({ success: totalSuccess, failed: totalFailed })
        onImport?.(parcels)
      } else {
        // Small import — single request
        const res = await fetch(`/api/projects/${projectId}/parcels/batch`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            parcels: parcels.map(p => ({
              parcelNumber: p.parcelNumber,
              ownerName: p.ownerName,
              ownerId: p.ownerId,
              lrNumber: p.lrNumber,
              areaHa: p.areaHa,
              vertices: p.vertices,
            })),
          }),
        })

        if (!res.ok) {
          const data = await res.json()
          throw new Error(data.error || 'Import failed')
        }

        const data = await res.json()
        setImportResult({
          success: data.data?.imported || parcels.length,
          failed: data.data?.failed || 0,
        })
        setImportProgress(100)
        onImport?.(parcels)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed')
    } finally {
      setImporting(false)
    }
  }, [parcels, projectId, onImport])

  const downloadTemplate = useCallback(() => {
    const csv = `parcel_number,easting,northing,owner_name,owner_id,lr_number,area_ha
MWAVUMBO/001,534850.123,9574220.456,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534852.456,9574221.789,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534854.789,9574222.123,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/001,534850.123,9574220.456,John Doe,12345678,LR/12345/678,0.5000
MWAVUMBO/002,534860.000,9574230.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534862.000,9574231.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534864.000,9574232.000,Jane Smith,87654321,LR/12345/679,0.7500
MWAVUMBO/002,534860.000,9574230.000,Jane Smith,87654321,LR/12345/679,0.7500`
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'metardu-parcel-template.csv'
    a.click()
    URL.revokeObjectURL(url)
  }, [])

  const validCount = parcels.filter(p => p.valid).length
  const invalidCount = parcels.length - validCount

  return (
    <div className="space-y-4">
      <div
        onDragOver={(e) => { e.preventDefault(); setDragOver(true) }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
        className={`rounded-xl border-2 border-dashed p-8 text-center cursor-pointer transition-all ${
          dragOver ? 'border-[var(--accent)] bg-[var(--accent)]/5' : 'border-[var(--border-color)] hover:border-[var(--accent)]/50'
        }`}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept=".csv,.geojson,.json"
          onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
          className="hidden"
        />
        {parsing ? (
          <div className="flex flex-col items-center">
            <Loader2 className="w-8 h-8 text-[var(--accent)] animate-spin mb-2" />
            <p className="text-sm text-gray-400">Parsing file...</p>
          </div>
        ) : (
          <div className="flex flex-col items-center">
            <div className="w-12 h-12 rounded-xl bg-[var(--accent)]/10 flex items-center justify-center mb-3">
              <Upload className="w-6 h-6 text-[var(--accent)]" />
            </div>
            <p className="text-sm font-medium text-[var(--text-primary)]">
              Drop CSV or GeoJSON here, or click to browse
            </p>
            <p className="text-[10px] text-gray-500 mt-1">
              Supports parcel boundaries with owner data — up to 1000 parcels
            </p>
          </div>
        )}
      </div>

      <div className="flex items-center justify-between">
        <button
          onClick={downloadTemplate}
          className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400 hover:text-gray-200"
        >
          <Download className="w-3.5 h-3.5" />
          Download CSV Template
        </button>
        {parcels.length > 0 && (
          <button onClick={() => setParcels([])} className="text-[10px] text-gray-500 hover:text-gray-300">
            Clear
          </button>
        )}
      </div>

      {error && (
        <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 flex items-start gap-2">
          <AlertTriangle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
          <p className="text-xs text-red-400">{error}</p>
        </div>
      )}

      {importResult && (
        <div className="p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20 flex items-start gap-2">
          <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0 mt-0.5" />
          <div>
            <p className="text-xs text-emerald-400 font-medium">
              Import complete: {importResult.success} parcels imported
            </p>
            {importResult.failed > 0 && (
              <p className="text-[10px] text-amber-400">{importResult.failed} failed</p>
            )}
          </div>
        </div>
      )}

      {parcels.length > 0 && (
        <div className="card p-4">
          <div className="flex items-center justify-between mb-3">
            <div className="flex items-center gap-2">
              <Table className="w-4 h-4 text-[var(--accent)]" />
              <span className="text-sm font-semibold text-[var(--text-primary)]">
                Preview ({parcels.length} parcels)
              </span>
            </div>
            <div className="flex items-center gap-3 text-[10px]">
              <span className="flex items-center gap-1 text-emerald-400">
                <CheckCircle2 className="w-3 h-3" />
                {validCount} valid
              </span>
              {invalidCount > 0 && (
                <span className="flex items-center gap-1 text-red-400">
                  <AlertTriangle className="w-3 h-3" />
                  {invalidCount} errors
                </span>
              )}
            </div>
          </div>

          <div className="max-h-[300px] overflow-y-auto">
            <table className="w-full">
              <thead className="sticky top-0 bg-[var(--bg-card)]">
                <tr className="border-b border-[var(--border-color)]">
                  <th className="px-2 py-2 text-left text-[9px] text-gray-500 uppercase">Parcel No.</th>
                  <th className="px-2 py-2 text-left text-[9px] text-gray-500 uppercase">Owner</th>
                  <th className="px-2 py-2 text-center text-[9px] text-gray-500 uppercase">Vertices</th>
                  <th className="px-2 py-2 text-right text-[9px] text-gray-500 uppercase">Area (ha)</th>
                  <th className="px-2 py-2 text-center text-[9px] text-gray-500 uppercase">Status</th>
                </tr>
              </thead>
              <tbody>
                {parcels.map(parcel => (
                  <tr key={parcel.id} className="border-b border-[var(--border-color)]/50">
                    <td className="px-2 py-2 text-xs font-mono text-[var(--text-primary)]">{parcel.parcelNumber}</td>
                    <td className="px-2 py-2 text-xs text-gray-400">{parcel.ownerName || '—'}</td>
                    <td className="px-2 py-2 text-xs text-center text-gray-400">{parcel.vertices.length}</td>
                    <td className="px-2 py-2 text-xs text-right font-mono text-gray-400">{parcel.areaHa ? parcel.areaHa.toFixed(4) : '—'}</td>
                    <td className="px-2 py-2 text-center">
                      {parcel.valid ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 inline" /> : <AlertTriangle className="w-3.5 h-3.5 text-red-400 inline" />}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <button
            onClick={handleImport}
            disabled={importing || validCount === 0}
            className="w-full mt-3 flex items-center justify-center gap-2 h-10 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {importing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Layers className="w-4 h-4" />}
            {importing ? `${importProgress > 0 ? Math.round(importProgress) + '%' : 'Importing...'}` : `Import ${validCount} Parcels to Project`}
          </button>
        </div>
      )}

      <div className="flex items-start gap-2 p-3 rounded-lg bg-blue-500/5 border border-blue-500/10">
        <Users className="w-3.5 h-3.5 text-blue-400 shrink-0 mt-0.5" />
        <div className="text-[10px] text-blue-400/70 leading-relaxed">
          <p className="font-medium mb-1">CSV Format:</p>
          <p>Each row = one vertex. Multiple rows with the same parcel_number = one parcel&apos;s vertices.</p>
          <p className="mt-1">Columns: parcel_number, easting, northing, owner_name, owner_id, lr_number, area_ha</p>
          <p className="mt-1 font-medium">GeoJSON: Polygon features with properties for owner data.</p>
        </div>
      </div>
    </div>
  )
}

'use client';

import { useEffect, useRef, useState } from 'react';
import Map from 'ol/Map';
import View from 'ol/View';
import TileLayer from 'ol/layer/Tile';
import OSM from 'ol/source/OSM';
import VectorLayer from 'ol/layer/Vector';
import VectorSource from 'ol/source/Vector';
import { Draw } from 'ol/interaction';
import { fromLonLat, toLonLat } from 'ol/proj';
import { getArea } from 'ol/sphere';
import type { Polygon } from 'ol/geom';

interface BoundarySelectorMapProps {
  onBoundaryChange: (polygonCoordinates: number[][], areaSqm: number, centerLonLat: [number, number]) => void;
  className?: string;
}

export function BoundarySelectorMap({ onBoundaryChange, className = '' }: BoundarySelectorMapProps) {
  const mapRef = useRef<HTMLDivElement>(null);
  const [mapObj, setMapObj] = useState<Map | null>(null);

  // Inject OpenLayers CSS dynamically (a static `import 'ol/ol.css'` breaks
  // Next.js static export — same pattern as src/components/field/MapViewer.tsx).
  useEffect(() => {
    if (!document.querySelector('link[href*="ol/ol.css"]')) {
      try {
        void import('ol/ol.css' as any)
      } catch {
        const link = document.createElement('link')
        link.rel = 'stylesheet'
        link.href = 'https://cdn.jsdelivr.net/npm/ol@10.8.0/ol.css'
        document.head.appendChild(link)
      }
    }
  }, [])

  useEffect(() => {
    if (!mapRef.current || mapObj) return;

    // Source for drawn polygon
    const source = new VectorSource({ wrapX: false });
    
    // Vector layer for polygon
    const vector = new VectorLayer({
      source: source,
      style: {
        'fill-color': 'rgba(255, 165, 0, 0.2)',
        'stroke-color': '#ff9800',
        'stroke-width': 2,
        'circle-radius': 5,
        'circle-fill-color': '#ff9800',
      },
    });

    const map = new Map({
      target: mapRef.current,
      layers: [
        new TileLayer({
          source: new OSM(),
        }),
        vector,
      ],
      view: new View({
        center: fromLonLat([36.8219, -1.2921]), // Default to Nairobi
        zoom: 12,
      }),
    });

    // Drawing interaction
    const draw = new Draw({
      source: source,
      type: 'Polygon',
    });

    draw.on('drawstart', () => {
      // Clear previous drawing
      source.clear();
    });

    draw.on('drawend', (e) => {
      const geometry = e.feature.getGeometry() as Polygon;
      
      // Calculate area in square meters (geodesic)
      const areaSqm = getArea(geometry);

      // Get center point (for UTM zone extraction)
      const extent = geometry.getExtent();
      const center = [
        (extent[0] + extent[2]) / 2,
        (extent[1] + extent[3]) / 2
      ];
      
      const centerLonLat = toLonLat(center);
      
      // Convert boundary points to EPSG:4326
      const coords = geometry.getCoordinates()[0].map(pt => toLonLat(pt));
      
      onBoundaryChange(coords, areaSqm, centerLonLat as [number, number]);
    });

    map.addInteraction(draw);
    setMapObj(map);

    return () => {
      map.setTarget(undefined);
    };
  }, [mapObj, onBoundaryChange]);

  // Handle getting user location to center map initially
  useEffect(() => {
    if (navigator.geolocation && mapObj) {
      navigator.geolocation.getCurrentPosition((pos) => {
        const coords = fromLonLat([pos.coords.longitude, pos.coords.latitude]);
        mapObj.getView().animate({ center: coords, zoom: 15 });
      });
    }
  }, [mapObj]);

  return (
    <div className={`relative ${className}`}>
      <div ref={mapRef} className="absolute inset-0 rounded-lg overflow-hidden border border-[var(--border-color)]" />
      <div className="absolute top-2 left-2 z-10 bg-white/90 dark:bg-black/90 p-2 rounded shadow-md text-xs font-semibold backdrop-blur pointer-events-none">
        Draw a boundary around your project site
      </div>
    </div>
  );
}

'use client'

/**
 * CollaborationPanel — Combined presence + chat panel for project workspaces
 *
 * Features:
 * - Online collaborators with avatars
 * - Live chat messages
 * - Send messages
 * - Conflict warnings
 * - Collapsible panel
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  MessageSquare, Send, Users, ChevronDown, ChevronUp,
  AlertTriangle, X,
} from 'lucide-react'
import { PresenceIndicator } from './PresenceIndicator'
import type { Collaborator } from '@/lib/realtime/useCollaboration'

interface ChatMessage {
  id: string
  userId: string
  userName: string
  message: string
  timestamp: number
}

interface CollaborationPanelProps {
  collaborators: Collaborator[]
  isConnected: boolean
  messages: ChatMessage[]
  onSend: (message: string) => void
  conflictWarnings?: string[]
}

export function CollaborationPanel({
  collaborators,
  isConnected,
  messages,
  onSend,
  conflictWarnings = [],
}: CollaborationPanelProps) {
  const [expanded, setExpanded] = useState(true)
  const [input, setInput] = useState('')
  const messagesEndRef = useRef<HTMLDivElement>(null)

  // Auto-scroll to bottom on new message
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  const handleSend = useCallback(() => {
    if (!input.trim()) return
    onSend(input.trim())
    setInput('')
  }, [input, onSend])

  const handleKeyPress = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }, [handleSend])

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-[var(--bg-tertiary)]/50 transition-colors"
      >
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <Users className="w-4 h-4 text-[var(--accent)]" />
          </div>
          <div className="text-left">
            <span className="text-sm font-semibold text-[var(--text-primary)]">Team Collaboration</span>
            <p className="text-[10px] text-gray-500">
              {isConnected
                ? `${collaborators.length + 1} online`
                : 'Disconnected'}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <PresenceIndicator collaborators={collaborators} isConnected={isConnected} max={4} />
          {expanded ? <ChevronUp className="w-4 h-4 text-gray-500" /> : <ChevronDown className="w-4 h-4 text-gray-500" />}
        </div>
      </button>

      {expanded && (
        <div className="border-t border-[var(--border-color)]">
          {/* Conflict warnings */}
          {conflictWarnings.length > 0 && (
            <div className="p-2 bg-amber-500/5 border-b border-amber-500/10">
              {conflictWarnings.map((warning, i) => (
                <div key={`${warning}-${i}`} className="flex items-center gap-1.5 text-[10px] text-amber-400">
                  <AlertTriangle className="w-3 h-3 shrink-0" />
                  {warning}
                </div>
              ))}
            </div>
          )}

          {/* Chat messages */}
          <div className="max-h-[200px] overflow-y-auto p-3 space-y-2">
            {messages.length === 0 ? (
              <div className="text-center py-4">
                <MessageSquare className="w-6 h-6 text-gray-600 mx-auto mb-1" />
                <p className="text-[10px] text-gray-500">No messages yet</p>
                <p className="text-[9px] text-gray-600">Start a conversation with your team</p>
              </div>
            ) : (
              messages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2">
                  <div className="shrink-0 w-6 h-6 rounded-full bg-[var(--accent)]/10 flex items-center justify-center text-[9px] font-bold text-[var(--accent)]">
                    {msg.userName.split(' ').map(n => n[0]).slice(0, 2).join('').toUpperCase()}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-baseline gap-1.5">
                      <span className="text-[10px] font-medium text-[var(--text-primary)]">{msg.userName}</span>
                      <span className="text-[8px] text-gray-600">
                        {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                    <p className="text-[11px] text-[var(--text-secondary)] break-words">{msg.message}</p>
                  </div>
                </div>
              ))
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <div className="border-t border-[var(--border-color)] p-2 flex items-center gap-2">
            <input aria-label="Type a message"
              type="text"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder={isConnected ? 'Type a message...' : 'Disconnected'}
              disabled={!isConnected}
              className="flex-1 h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none disabled:opacity-50"
            />
            <button
              onClick={handleSend}
              disabled={!isConnected || !input.trim()}
              aria-label="Send message"
              className="w-8 h-8 flex items-center justify-center rounded-lg bg-[var(--accent)] text-black disabled:opacity-40 disabled:cursor-not-allowed hover:bg-[var(--accent-dim)]"
            >
              <Send className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * ProjectPresencePanel — Lightweight presence indicator for project workspaces.
 *
 * Shows who else is online on the same project with live polling.
 * Uses the existing /api/realtime/poll endpoint.
 */

import { useState, useEffect } from 'react'
import { Users } from 'lucide-react'

interface ProjectPresencePanelProps {
  projectId: string
  currentUserId: string
}

const ROLE_COLORS = ['#e8841a', '#3b82f6', '#10b981', '#8b5cf6', '#ec4899', '#f59e0b']

export function ProjectPresencePanel({ projectId, currentUserId }: ProjectPresencePanelProps) {
  const [collaborators, setCollaborators] = useState<Array<{ userId: string; name: string; status: string; color: string }>>([])
  const [expanded, setExpanded] = useState(false)

  useEffect(() => {
    if (!projectId) return

    const poll = async () => {
      try {
        const res = await fetch(`/api/realtime/poll?table=projects&projectId=${projectId}`)
        if (res.ok) {
          const data = await res.json()
          const seen = new Map<string, { userId: string; name: string; status: string; color: string }>()
          for (const row of data.data || []) {
            const userId = row.user_id || row.userId
            if (!userId || userId === currentUserId) continue
            if (!seen.has(userId)) {
              const colorIdx = seen.size % ROLE_COLORS.length
              const ageMs = Date.now() - new Date(row.updated_at).getTime()
              seen.set(userId, {
                userId,
                name: row.user_name || `Surveyor ${userId.slice(0, 4)}`,
                status: ageMs < 60000 ? 'active' : 'idle',
                color: ROLE_COLORS[colorIdx],
              })
            }
          }
          setCollaborators(Array.from(seen.values()))
        }
      } catch { /* non-blocking */ }
    }

    poll()
    const interval = setInterval(poll, 10000)
    return () => clearInterval(interval)
  }, [projectId, currentUserId])

  if (collaborators.length === 0) return null

  const activeCount = collaborators.filter(c => c.status === 'active').length

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between p-3 hover:bg-[var(--bg-tertiary)] transition-colors"
      >
        <div className="flex items-center gap-2">
          <div className="relative">
            <Users className="w-4 h-4 text-[var(--accent)]" />
            {activeCount > 0 && (
              <span className="absolute -top-1 -right-1 w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
            )}
          </div>
          <span className="text-xs font-semibold text-[var(--text-primary)]">
            {collaborators.length} collaborator{collaborators.length !== 1 ? 's' : ''}
          </span>
        </div>
        <span className="text-[10px] text-[var(--text-muted)]">{activeCount} active now</span>
      </button>

      {expanded && (
        <div className="border-t border-[var(--border-color)] divide-y divide-[var(--border-color)]">
          {collaborators.map(c => (
            <div key={c.userId} className="flex items-center gap-2 p-2.5">
              <div className="relative shrink-0">
                <div className="w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold text-white" style={{ backgroundColor: c.color }}>
                  {c.name.charAt(0).toUpperCase()}
                </div>
                <span className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-[var(--bg-card)] ${c.status === 'active' ? 'bg-emerald-400' : 'bg-amber-400'}`} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-xs font-medium text-[var(--text-primary)] truncate">{c.name}</div>
                <div className="text-[10px] text-[var(--text-muted)]">{c.status === 'active' ? 'active now' : 'idle'}</div>
              </div>
              <div className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: c.color }} />
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

'use client';

import { useState } from 'react'
import { Search, Building2, AlertTriangle, Info, Check, Download } from 'lucide-react'
import type { NLIMSParcel, NLIMSSearchResult } from '@/types/nlims'

interface NLIMSLookupProps {
  initialParcel?: string
  onParcelVerified?: (parcel: NLIMSParcel) => void
}

export default function NLIMSLookup({ initialParcel = '', onParcelVerified }: NLIMSLookupProps) {
  const [parcelNumber, setParcelNumber] = useState(initialParcel)
  const [county, setCounty] = useState('')
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<NLIMSSearchResult | null>(null)

  const handleSearch = async () => {
    if (!parcelNumber.trim()) return

    setLoading(true)
    setResult(null)

    try {
      const params = new URLSearchParams({ parcel: parcelNumber })
      if (county) params.append('county', county)

      const res = await fetch(`/api/nlims/lookup?${params}`)
      const data = await res.json()
      setResult(data)
    } catch (error) {
      console.error('NLIMS lookup error:', error)
      setResult({ found: false, error: 'Failed to search registry', isMockData: false })
    }

    setLoading(false)
  }

  const handleUseInProject = () => {
    if (result?.parcel && onParcelVerified) {
      onParcelVerified(result.parcel)
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row flex-wrap gap-4">
        <div className="flex-1">
          <label className="block text-sm font-medium text-[var(--text-muted)] mb-1" htmlFor="parcel-number">
            Parcel Number
          </label>
          <input id="parcel-number"
            type="text"
            value={parcelNumber}
            onChange={e => setParcelNumber(e.target.value.toUpperCase())}
            aria-label="e.g., NAIROBI BLOCK 2/1234" placeholder="e.g., NAIROBI BLOCK 2/1234"
            className="w-full p-2 border rounded-lg"
          />
        </div>
        <div className="w-full md:w-48">
          <label className="block text-sm font-medium text-[var(--text-muted)] mb-1" htmlFor="county">
            County
          </label>
          <input
            type="text"
            value={county}
            onChange={e => setCounty(e.target.value)}
            aria-label="e.g., Nairobi" placeholder="e.g., Nairobi"
            className="w-full p-2 border rounded-lg"
          />
        </div>
        <div className="flex items-end">
          <button
            onClick={handleSearch}
            disabled={loading || !parcelNumber.trim()}
            className="flex items-center gap-2 px-4 py-2 bg-sky-600 text-white rounded-lg hover:bg-sky-700 disabled:opacity-50"
          >
            {loading ? (
              <span className="animate-spin">[Wait]</span>
            ) : (
              <Search className="w-4 h-4" />
            )}
            Search Registry
          </button>
        </div>
      </div>

      {result && result.found && result.parcel && (
        <div className="border rounded-xl overflow-hidden">
          <div className={`p-4 ${
            result.parcel.status === 'REGISTERED' ? 'bg-green-50' :
            result.parcel.status === 'DISPUTED' ? 'bg-red-50' :
            'bg-yellow-50'
          }`}>
            <div className="flex items-center gap-2">
              {result.parcel.status === 'REGISTERED' && (
                <>
                  <Check className="w-5 h-5 text-green-600" />
                  <span className="font-semibold text-green-800">REGISTERED</span>
                </>
              )}
              {result.parcel.status === 'DISPUTED' && (
                <>
                  <AlertTriangle className="w-5 h-5 text-red-600" />
                  <span className="font-semibold text-red-800">DISPUTED</span>
                </>
              )}
              {result.parcel.status === 'PENDING' && (
                <>
                  <Info className="w-5 h-5 text-yellow-600" />
                  <span className="font-semibold text-yellow-800">PENDING REGISTRATION</span>
                </>
              )}
              {result.parcel.status === 'CANCELLED' && (
                <>
                  <AlertTriangle className="w-5 h-5 text-red-600" />
                  <span className="font-semibold text-red-800">CANCELLED</span>
                </>
              )}
            </div>
          </div>

          {result.parcel.status === 'DISPUTED' && (
            <div className="p-4 bg-red-100 border-b border-red-200">
              <p className="text-red-800 font-medium">
                <AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /> This parcel has a registered dispute. Proceed only with written 
                instruction from client. Cite: Survey Act Cap 299 s.22
              </p>
            </div>
          )}

          <div className="p-4 bg-white">
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <p className="text-sm text-[var(--text-muted)]">Parcel</p>
                <p className="font-medium">{result.parcel.parcelNumber}</p>
              </div>
              <div>
                <p className="text-sm text-[var(--text-muted)]">Title Deed</p>
                <p className="font-medium">{result.parcel.titleDeedNumber}</p>
              </div>
              <div>
                <p className="text-sm text-[var(--text-muted)]">Area</p>
                <p className="font-medium">
                  {result.parcel.area.toFixed(4)} m² ({result.parcel.areaHectares.toFixed(6)} ha)
                </p>
              </div>
              <div>
                <p className="text-sm text-[var(--text-muted)]">Owner Type</p>
                <p className="font-medium">{result.parcel.ownerType}</p>
              </div>
              <div>
                <p className="text-sm text-[var(--text-muted)]">County</p>
                <p className="font-medium">{result.parcel.county}</p>
              </div>
              <div>
                <p className="text-sm text-[var(--text-muted)]">Last Transaction</p>
                <p className="font-medium">
                  {result.parcel.lastTransactionType} — {result.parcel.lastTransactionDate}
                </p>
              </div>
            </div>

            {result.parcel.encumbrances.length > 0 && (
              <div className="mt-4 p-4 bg-amber-50 rounded-lg">
                <h4 className="font-medium text-amber-800 mb-2">Encumbrances</h4>
                <ul className="space-y-2">
                  {result.parcel.encumbrances.map((enc, i) => (
                    <li key={`${enc}-${i}`} className="text-sm">
                      <span className="font-medium">{enc.type}:</span> {enc.description}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {result.parcel.encumbrances.length === 0 && (
              <div className="mt-4 p-4 bg-gray-50 rounded-lg">
                <p className="text-sm text-[var(--text-muted)]">No encumbrances registered</p>
              </div>
            )}

            {result.isMockData && (
              <div className="mt-4 p-3 bg-gray-100 rounded-lg flex items-start gap-2">
                <Info className="w-4 h-4 text-gray-600 mt-0.5" />
                <p className="text-sm text-gray-600">
                  Registry data pending live verification. Confirm with Land Registry 
                  before finalising survey.
                </p>
              </div>
            )}
          </div>

          <div className="p-4 bg-gray-50 border-t flex gap-3">
            <button
              onClick={handleUseInProject}
              className="flex items-center gap-2 px-4 py-2 bg-sky-600 text-white rounded-lg hover:bg-sky-700"
            >
              <Building2 className="w-4 h-4" />
              Use in Project
            </button>
            <button className="flex items-center gap-2 px-4 py-2 border rounded-lg hover:bg-gray-100">
              <Download className="w-4 h-4" />
              Download Certificate
            </button>
          </div>
        </div>
      )}

      {result && !result.found && (
        <div className="p-4 bg-red-50 border border-red-200 rounded-lg">
          <p className="text-red-800">
            {result.error || 'Parcel not found in registry'}
          </p>
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * ReportTemplateEditor — Drag-and-drop document layout designer
 *
 * Inspired by QGIS Print Composer. Lets surveyors design custom document
 * templates by placing elements on a canvas:
 * - Map view (auto-scaled to fit)
 * - Text blocks (titles, labels, surveyor info)
 * - Tables (beacon schedule, area schedule)
 * - North arrow
 * - Scale bar
 * - Company logo
 * - Grid overlay
 *
 * Features:
 * - Drag elements from palette to canvas
 * - Resize/move elements with mouse
 * - Per-element styling (font, color, position, size)
 * - Template presets (deed plan, mutation, traverse sheet)
 * - Save/load templates to localStorage
 * - Preview before generating PDF
 * - Lock elements to prevent accidental moves
 *
 * This gives surveyors full control over document layout without
 * needing a developer to modify templates.
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  Type, Map as MapIcon, Table, Navigation, Ruler,
  Image, Grid3x3, Save, FolderOpen, Eye, Trash2,
  Lock, Unlock, Copy, Download, Plus, Settings2,
  Move, Maximize2,
} from 'lucide-react'

type ElementType = 'text' | 'map' | 'table' | 'north_arrow' | 'scale_bar' | 'logo' | 'grid'

interface TemplateElement {
  id: string
  type: ElementType
  x: number      // mm from left
  y: number      // mm from top
  width: number  // mm
  height: number // mm
  locked: boolean
  // Type-specific properties
  text?: string
  fontSize?: number
  fontWeight?: 'normal' | 'bold'
  align?: 'left' | 'center' | 'right'
  color?: string
  // Table
  tableData?: Array<Array<string>>
  // Map
  scale?: number
  // Logo
  logoUrl?: string
}

interface ReportTemplate {
  id: string
  name: string
  paperSize: 'A4' | 'A3' | 'A2' | 'A1'
  orientation: 'portrait' | 'landscape'
  elements: TemplateElement[]
}

// ---------------------------------------------------------------------------
// Paper sizes (mm)
// ---------------------------------------------------------------------------

const PAPER_DIMENSIONS = {
  A4: { width: 210, height: 297 },
  A3: { width: 297, height: 420 },
  A2: { width: 420, height: 594 },
  A1: { width: 594, height: 841 },
}

// ---------------------------------------------------------------------------
// Element palette
// ---------------------------------------------------------------------------

const ELEMENT_PALETTE: Array<{
  type: ElementType
  label: string
  icon: typeof Type
  defaultSize: { width: number; height: number }
}> = [
  { type: 'text', label: 'Text', icon: Type, defaultSize: { width: 80, height: 10 } },
  { type: 'map', label: 'Map', icon: MapIcon, defaultSize: { width: 150, height: 100 } },
  { type: 'table', label: 'Table', icon: Table, defaultSize: { width: 120, height: 60 } },
  { type: 'north_arrow', label: 'North Arrow', icon: Navigation, defaultSize: { width: 15, height: 20 } },
  { type: 'scale_bar', label: 'Scale Bar', icon: Ruler, defaultSize: { width: 50, height: 8 } },
  { type: 'logo', label: 'Logo', icon: Image, defaultSize: { width: 30, height: 15 } },
  { type: 'grid', label: 'Grid', icon: Grid3x3, defaultSize: { width: 150, height: 100 } },
]

// ---------------------------------------------------------------------------
// Template presets
// ---------------------------------------------------------------------------

const TEMPLATE_PRESETS: Array<{
  name: string
  description: string
  paperSize: 'A4' | 'A3' | 'A2' | 'A1'
  orientation: 'portrait' | 'landscape'
  elements: Omit<TemplateElement, 'id'>[]
}> = [
  {
    name: 'Deed Plan (A1 Landscape)',
    description: 'Standard SoK deed plan layout',
    paperSize: 'A1',
    orientation: 'landscape',
    elements: [
      { type: 'text', x: 297, y: 10, width: 297, height: 15, locked: false, text: 'REPUBLIC OF KENYA — DEED PLAN', fontSize: 8, fontWeight: 'bold', align: 'center' },
      { type: 'map', x: 20, y: 40, width: 400, height: 300, locked: false, scale: 2500 },
      { type: 'north_arrow', x: 410, y: 50, width: 15, height: 20, locked: false },
      { type: 'scale_bar', x: 30, y: 340, width: 50, height: 8, locked: false },
      { type: 'table', x: 440, y: 100, width: 130, height: 200, locked: false, tableData: [['BEACON', 'E', 'N'], ['MB/001', '534850.123', '9574220.456']] },
      { type: 'text', x: 440, y: 40, width: 130, height: 8, locked: false, text: 'LR No: ___________', fontSize: 4 },
      { type: 'text', x: 440, y: 320, width: 130, height: 20, locked: false, text: 'Surveyor: ___________\nLicense: ___________', fontSize: 3 },
    ],
  },
  {
    name: 'Mutation Form (A3 Landscape)',
    description: 'Subdivision mutation layout',
    paperSize: 'A3',
    orientation: 'landscape',
    elements: [
      { type: 'text', x: 148.5, y: 10, width: 297, height: 12, locked: false, text: 'MUTATION FORM', fontSize: 7, fontWeight: 'bold', align: 'center' },
      { type: 'map', x: 20, y: 40, width: 200, height: 150, locked: false, scale: 2500 },
      { type: 'north_arrow', x: 220, y: 50, width: 12, height: 16, locked: false },
      { type: 'scale_bar', x: 25, y: 195, width: 40, height: 6, locked: false },
      { type: 'table', x: 240, y: 60, width: 100, height: 120, locked: false, tableData: [['PARCEL', 'AREA (ha)'], ['001', '0.5000'], ['002', '0.7500']] },
      { type: 'text', x: 20, y: 260, width: 200, height: 15, locked: false, text: 'Surveyor: ___________  License: ___________', fontSize: 3 },
    ],
  },
  {
    name: 'Traverse Sheet (A4 Portrait)',
