      curveLength: lengthMode === 'L' ? (parseFloat(L) || 0) : undefined,
      kValue: lengthMode === 'K' ? (parseFloat(K) || 0) : undefined,
      interval: parseInt(interval) || 20,
    }
    try {
      setResult(verticalCurve(input))
