            ))}
          </div>

          <VerticalCurveProfile
            rows={result.rows.map(r => ({ chainage: r.chainage, x: r.x, RL: r.rl, grade: 0 }))}
            bvcChainage={result.bvcChainage}
            evcChainage={result.evcChainage}
            vpiChainage={parseFloat(vpiCh)}
            bvcRL={result.bvcRL}
            evcRL={result.evcRL}
            vpiRL={parseFloat(vpiRL)}
            g1={parseFloat(g1)}
            g2={parseFloat(g2)}
            isCrest={result.isCrest}
            peakPoint={{ chainage: result.chainagePeak, RL: result.rlPeak }}
          />

          <div className="overflow-x-auto">
            <table className="w-full text-xs font-mono border-collapse">
              <thead>
                <tr className="bg-[var(--bg-tertiary)]">
                  {['Chainage', 'RL (m)', 'x (m)', 'y (m)', 'Point'].map((h: any) => (
                    <th key={h} className="px-3 py-2 text-left text-[var(--text-muted)] font-medium border border-[var(--border-color)]">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {result.rows.map((row, i) => (
                  <tr key={`${row}-${i}`} className="border border-[var(--border-color)]/50 hover:bg-[var(--bg-tertiary)]/50">
                    <td className="px-3 py-1.5 text-[var(--text-primary)]">{fmtCh(row.chainage)}</td>
                    <td className="px-3 py-1.5 text-[var(--text-primary)] text-right">{row.rl.toFixed(3)}</td>
                    <td className="px-3 py-1.5 text-[var(--text-secondary)] text-right">{row.x.toFixed(3)}</td>
                    <td className="px-3 py-1.5 text-[var(--text-secondary)] text-right">{row.y.toFixed(3)}</td>
                    <td className="px-3 py-1.5">
                      {row.isBVC && <span className="text-[var(--accent)] font-bold">BVC</span>}
                      {row.isEVC && <span className="text-[var(--accent)] font-bold">EVC</span>}
                      {row.isPeak && !row.isBVC && !row.isEVC && <span className="text-yellow-400">PEAK</span>}
                      {row.isSag && !row.isBVC && !row.isEVC && !row.isPeak && <span className="text-blue-400">SAG</span>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  )
}

'use client';

import { useState, useRef, useCallback } from 'react'
import {
  Upload, X, FileSpreadsheet, AlertCircle, CheckCircle2,
  Loader2, Info
} from 'lucide-react'

interface ImportResult {
  total_rows: number
  created: number
  skipped: number
  errors: string[]
}

export default function CsvImportPanel({ projectId, blockId, blockName, onImportComplete }: {
  projectId: number | string
  blockId: number | string
  blockName: string
  onImportComplete?: () => void
}) {
  const fileRef = useRef<HTMLInputElement>(null)
  const [dragging, setDragging] = useState(false)
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<ImportResult | null>(null)
  const [error, setError] = useState('')
  const [fileName, setFileName] = useState('')

  const doImport = async (file: File) => {
    setLoading(true)
    setError('')
    setResult(null)
    setFileName(file.name)

    const formData = new FormData()
    formData.append('project_id', String(projectId))
    formData.append('block_id', String(blockId))
    formData.append('file', file)

    try {
      const res = await fetch('/api/scheme/import', {
        method: 'POST',
        body: formData,
      })
      const json = await res.json()
      if (!res.ok) throw new Error(json.error || 'Import failed')

      setResult(json.data)
      if (json.data.created > 0 && onImportComplete) {
        onImportComplete()
      }
    } catch (err: unknown) {
      setError((err as Error).message)
    } finally {
      setLoading(false)
    }
  }

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) doImport(file)
  }

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragging(false)
    const file = e.dataTransfer.files?.[0]
    if (file) doImport(file)
  }, [])

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    setDragging(true)
  }

  const handleDragLeave = () => setDragging(false)

  // Sample CSV data for download
  const downloadSample = () => {
    const csv = `parcel_number,lr_number_proposed,area_ha,notes
1,MN/III/1001,0.0625,Northwest corner
2,MN/III/1002,0.1250,Central portion
3,MN/III/1003,0.0875,East boundary
4,MN/III/1004,0.1500,South section
5,MN/III/1005,0.1000,Road reserve
6,MN/III/1006,0.0750,Adjoining river
7,MN/III/1007,0.0500,Corner plot
8,MN/III/1008,0.2000,Large subdivision
9,MN/III/1009,0.1100,Commercial zone
10,MN/III/1010,0.0800,Public utility`
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `sample_parcels_${blockName}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="border border-[var(--border-color)] rounded-xl overflow-hidden bg-[var(--bg-card)]">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <span className="text-sm font-semibold text-[var(--text-primary)] flex items-center gap-2">
          <FileSpreadsheet className="w-4 h-4 text-blue-400" />
          Bulk Import Parcels
        </span>
        <button
          onClick={downloadSample}
          className="text-xs text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors flex items-center gap-1"
        >
          <Info className="w-3 h-3" />
          Download Sample CSV
        </button>
      </div>

      <div className="px-4 py-3 space-y-3">
        {/* Upload Zone */}
        <div
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onClick={() => fileRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-all ${
            dragging
              ? 'border-[var(--accent)] bg-[var(--accent)]/5'
              : 'border-[var(--border-color)] hover:border-[var(--accent)]/50 hover:bg-[var(--bg-secondary)]'
          }`}
        >
          <input
            ref={fileRef}
            type="file"
            accept=".csv,text/csv"
            onChange={handleFileChange}
            className="hidden"
          />
          {loading ? (
            <div className="flex flex-col items-center gap-2">
              <Loader2 className="w-8 h-8 animate-spin text-[var(--accent)]" />
              <p className="text-sm text-[var(--text-secondary)]">Importing {fileName}...</p>
            </div>
          ) : (
            <div className="flex flex-col items-center gap-2">
              <Upload className="w-8 h-8 text-[var(--text-muted)]" />
              <p className="text-sm text-[var(--text-secondary)]">
                Drop CSV here or <span className="text-[var(--accent)] underline">browse</span>
              </p>
              <p className="text-[10px] text-[var(--text-muted)]">
                Required columns: parcel_number | Optional: lr_number_proposed, area_ha, notes
              </p>
            </div>
          )}
        </div>

        {/* Error */}
        {error && (
          <div className="p-2.5 bg-red-900/20 border border-red-500/30 rounded-lg text-xs text-red-400 flex items-start gap-2">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        )}

        {/* Result */}
        {result && (
          <div className="space-y-2">
            <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                <span className="text-sm font-medium text-emerald-400">
                  Import complete
                </span>
              </div>
              <div className="grid grid-cols-3 gap-3 text-xs">
                <div>
                  <span className="text-emerald-300 font-bold">{result.created}</span>
                  <span className="text-[var(--text-muted)]"> created</span>
                </div>
                <div>
                  <span className="text-yellow-300 font-bold">{result.skipped}</span>
                  <span className="text-[var(--text-muted)]"> skipped/updated</span>
                </div>
                <div>
                  <span className="text-[var(--text-secondary)]">{result.total_rows}</span>
                  <span className="text-[var(--text-muted)]"> total rows</span>
                </div>
              </div>
            </div>

            {result.errors.length > 0 && (
              <div className="p-2.5 bg-yellow-500/10 border border-yellow-500/20 rounded-lg">
                <p className="text-[10px] font-medium text-yellow-400 mb-1">
                  {result.errors.length} warning(s):
                </p>
                <div className="max-h-24 overflow-y-auto space-y-0.5">
                  {result.errors.map((e, i) => (
                    <p key={`${e}-${i}`} className="text-[10px] text-yellow-300/80">{e}</p>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

/**
 * CommandPalette — Global search and navigation (Cmd+K / Ctrl+K)
 *
 * Features:
 * - Press Cmd+K (Mac) or Ctrl+K (Windows/Linux) to open
 * - Search across: projects, parcels, beacons, tools, pages, documents
 * - Keyboard navigation (arrow keys, enter, escape)
 * - Recent items shown when query is empty
 * - Quick navigation shortcuts
 *
 * Integrates with:
 * - /api/search (existing backend search)
 * - Static page navigation (tools, docs, settings)
 */

import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import {
  Search, Command, ArrowRight, ArrowLeft, CornerDownLeft,
  FolderKanban, Wrench, Map, FileText, Settings, LayoutDashboard,
  Calculator, Ruler, Compass, Users, CreditCard, BarChart3,
  BookOpen, HelpCircle, Loader2,
} from 'lucide-react'
import { useDebounceValue } from '@/lib/performance'

interface SearchResult {
  id: string
  type: string
  title: string
  subtitle?: string
  href?: string
  meta?: Record<string, unknown>
}

interface StaticNavItem {
  title: string
  subtitle: string
  href: string
  icon: typeof LayoutDashboard
  category: string
  keywords: string[]
}

// Static navigation items (always available)
const STATIC_NAV: StaticNavItem[] = [
  { title: 'Dashboard', subtitle: 'Your project overview', href: '/dashboard', icon: LayoutDashboard, category: 'Pages', keywords: ['home', 'main', 'overview'] },
  { title: 'Map', subtitle: 'Global survey map', href: '/map', icon: Map, category: 'Pages', keywords: ['openlayers', 'gis'] },
  { title: 'Field Book', subtitle: 'Digital field notes', href: '/fieldbook', icon: FileText, category: 'Pages', keywords: ['notes', 'observations', 'leveling', 'traverse'] },
  { title: 'Documents', subtitle: 'Generated documents', href: '/documents', icon: FileText, category: 'Pages', keywords: ['pdf', 'deed', 'plan'] },
  { title: 'Analytics', subtitle: 'Usage statistics', href: '/analytics', icon: BarChart3, category: 'Pages', keywords: ['stats', 'reports'] },
  { title: 'Community', subtitle: 'Surveyor network', href: '/community', icon: Users, category: 'Pages', keywords: ['network', 'peer', 'review'] },
  { title: 'Settings', subtitle: 'Account preferences', href: '/settings', icon: Settings, category: 'Pages', keywords: ['profile', 'account', 'preferences'] },
  { title: 'Pricing', subtitle: 'Subscription plans', href: '/pricing', icon: CreditCard, category: 'Pages', keywords: ['upgrade', 'plan', 'subscription'] },

  // Tools
  { title: 'COGO Calculator', subtitle: 'Coordinate geometry', href: '/tools/cogo', icon: Calculator, category: 'Tools', keywords: ['cogo', 'coordinate', 'geometry', 'intersection'] },
  { title: 'Traverse', subtitle: 'Traverse computation', href: '/tools/traverse', icon: Compass, category: 'Tools', keywords: ['bowditch', 'adjustment', 'closure'] },
  { title: 'Leveling', subtitle: 'Rise & fall computation', href: '/tools/leveling', icon: Ruler, category: 'Tools', keywords: ['level', 'rl', 'benchmark'] },
  { title: 'Distance Calculator', subtitle: 'Point-to-point distance', href: '/tools/distance', icon: Ruler, category: 'Tools', keywords: ['length', 'measure'] },
  { title: 'Area Calculator', subtitle: 'Polygon area', href: '/tools/area', icon: Calculator, category: 'Tools', keywords: ['acre', 'hectare', 'parcel'] },
  { title: 'Coordinate Transform', subtitle: 'Datum conversion', href: '/tools/coordinates', icon: Compass, category: 'Tools', keywords: ['utm', 'wgs84', 'arc 1960', 'cassini'] },
  { title: 'Curve Calculator', subtitle: 'Horizontal/vertical curves', href: '/tools/curves', icon: Compass, category: 'Tools', keywords: ['radius', 'arc', 'transition'] },
  { title: 'Cassini-UTM Conversion', subtitle: 'Legacy grid transform', href: '/tools/cassini-utm', icon: Compass, category: 'Tools', keywords: ['cassini', 'soldner', 'colonial'] },

  // Docs
  { title: 'Documentation', subtitle: 'User manuals & guides', href: '/docs', icon: BookOpen, category: 'Help', keywords: ['manual', 'guide', 'help', 'docs'] },
  { title: 'Quick Start Guide', subtitle: 'Get started in 5 minutes', href: '/docs/quick-start', icon: BookOpen, category: 'Help', keywords: ['begin', 'tutorial', 'setup'] },
  { title: 'API Documentation', subtitle: 'Developer reference', href: '/api-docs', icon: BookOpen, category: 'Help', keywords: ['api', 'developer', 'rest'] },
]

export function CommandPalette() {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [selectedIndex, setSelectedIndex] = useState(0)
  const [searching, setSearching] = useState(false)
  const [apiResults, setApiResults] = useState<SearchResult[]>([])
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLDivElement>(null)

  // Open/close with Cmd+K / Ctrl+K
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setOpen(prev => !prev)
      }
      if (e.key === 'Escape' && open) {
        setOpen(false)
      }
    }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [open])

  // Focus input when opened
  useEffect(() => {
    if (open) {
      setTimeout(() => inputRef.current?.focus(), 50)
      setQuery('')
      setApiResults([])
      setSelectedIndex(0)
    }
  }, [open])

  // Debounced query using performance utility
  const debouncedQuery = useDebounceValue(query, 200)

  // Search API when debounced query changes
  useEffect(() => {
    if (!debouncedQuery.trim() || debouncedQuery.length < 2) {
      setApiResults([])
      return
    }

    setSearching(true)
    let cancelled = false

    async function doSearch() {
      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}&limit=10`)
        if (cancelled || !res.ok) return
        const data = await res.json()
        if (cancelled) return
        const results: SearchResult[] = []
        if (data.data?.groups) {
          for (const group of data.data.groups) {
            for (const hit of group.hits || []) {
              results.push({
                id: hit.id,
                type: group.type,
                title: hit.title,
                subtitle: hit.subtitle,
                href: getHrefForType(group.type, hit.id, hit.meta),
              })
            }
          }
        }
        setApiResults(results)
      } catch {
        // Silent fail
      } finally {
        if (!cancelled) setSearching(false)
      }
    }

    doSearch()

    return () => { cancelled = true }
  }, [debouncedQuery])

  // Filter static nav by query
  const filteredNav = useMemo(() => {
    if (!query.trim()) return STATIC_NAV.slice(0, 8)
    const q = query.toLowerCase()
    return STATIC_NAV.filter(item =>
      item.title.toLowerCase().includes(q) ||
      item.subtitle.toLowerCase().includes(q) ||
      item.keywords.some(k => k.includes(q))
    )
  }, [query])

  // Combine results
  const allResults = useMemo(() => {
    const combined: (StaticNavItem | SearchResult)[] = []
    if (apiResults.length > 0) combined.push(...apiResults)
    combined.push(...filteredNav)
    return combined.slice(0, 20)
  }, [apiResults, filteredNav])

  // Reset selected index when results change
  useEffect(() => {
    setSelectedIndex(0)
  }, [allResults.length])

  // Keyboard navigation
  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setSelectedIndex(prev => Math.min(prev + 1, allResults.length - 1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setSelectedIndex(prev => Math.max(prev - 1, 0))
    } else if (e.key === 'Enter') {
      e.preventDefault()
      const item = allResults[selectedIndex]
      if (item) handleSelect(item)
    }
  }, [allResults, selectedIndex])

  const handleSelect = useCallback((item: StaticNavItem | SearchResult) => {
    const href = 'href' in item ? item.href : undefined
    if (href) {
      router.push(href)
      setOpen(false)
    }
  }, [router])

  // Scroll selected item into view
  useEffect(() => {
    const el = listRef.current?.children[selectedIndex] as HTMLElement
    if (el) el.scrollIntoView({ block: 'nearest' })
  }, [selectedIndex])

  if (!open) return null

  return (
    <>
      {/* Backdrop */}
      <div
        className="fixed inset-0 z-[9998] bg-black/60 backdrop-blur-sm"
        onClick={() => setOpen(false)}
      />

      {/* Palette */}
      <div className="fixed top-[15vh] left-1/2 -translate-x-1/2 z-[9999] w-[640px] max-w-[calc(100vw-2rem)] bg-[#0d0d14]/95 backdrop-blur-2xl border border-white/[0.1] rounded-2xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
        {/* Search input */}
        <div className="flex items-center gap-3 px-4 py-3.5 border-b border-white/[0.06]">
          {searching ? (
            <Loader2 className="w-5 h-5 text-gray-500 animate-spin shrink-0" />
          ) : (
            <Search className="w-5 h-5 text-gray-500 shrink-0" />
          )}
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            aria-label="Search projects, parcels, tools, pages..." placeholder="Search projects, parcels, tools, pages..."
            className="flex-1 bg-transparent text-white text-sm placeholder-gray-600 focus:outline-none"
          />
          <kbd className="hidden sm:flex items-center gap-1 px-1.5 py-0.5 rounded bg-white/[0.06] border border-white/[0.1] text-[9px] text-gray-500 font-mono">
            ESC
          </kbd>
        </div>

        {/* Results */}
        <div ref={listRef} className="max-h-[400px] overflow-y-auto p-2">
          {allResults.length === 0 && query.length >= 2 && !searching && (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Search className="w-8 h-8 text-gray-600 mb-2" />
              <p className="text-sm text-gray-500">No results for &quot;{query}&quot;</p>
              <p className="text-[10px] text-gray-600 mt-1">Try a different search term</p>
            </div>
          )}

          {allResults.length === 0 && query.length < 2 && (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <Command className="w-8 h-8 text-gray-600 mb-2" />
              <p className="text-sm text-gray-500">Start typing to search</p>
              <p className="text-[10px] text-gray-600 mt-1">
                Search across projects, parcels, beacons, tools, and pages
              </p>
            </div>
          )}

          {/* API results section */}
          {apiResults.length > 0 && (
            <div className="mb-2">
              <div className="px-2 py-1 text-[9px] text-gray-600 uppercase tracking-wider font-semibold">
                Database Results
              </div>
              {apiResults.map((item, idx) => (
                <ResultRow
                  key={`api-${item.id}`}
                  selected={idx === selectedIndex}
                  onClick={() => handleSelect(item)}
                  onHover={() => setSelectedIndex(idx)}
                  icon={getResultIcon(item.type)}
                  title={item.title}
                  subtitle={item.subtitle || item.type}
                  href={item.href}
                />
              ))}
            </div>
          )}

          {/* Static nav section */}
          {filteredNav.length > 0 && (
            <div>
              {apiResults.length > 0 && (
                <div className="px-2 py-1 text-[9px] text-gray-600 uppercase tracking-wider font-semibold">
                  Pages & Tools
                </div>
              )}
              {filteredNav.map((item, idx) => {
                const actualIndex = apiResults.length + idx
                return (
                  <ResultRow
                    key={`nav-${item.href}`}
                    selected={actualIndex === selectedIndex}
                    onClick={() => handleSelect(item)}
                    onHover={() => setSelectedIndex(actualIndex)}
                    icon={item.icon}
                    title={item.title}
                    subtitle={item.subtitle}
                    category={item.category}
                  />
                )
              })}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-4 py-2 border-t border-white/[0.06] bg-[#0d0d14]/60">
          <div className="flex items-center gap-3 text-[9px] text-gray-600">
            <span className="flex items-center gap-1">
              <kbd className="px-1 py-0.5 rounded bg-white/[0.06] border border-white/[0.1] font-mono">↑↓</kbd>
              Navigate
            </span>
            <span className="flex items-center gap-1">
              <kbd className="px-1 py-0.5 rounded bg-white/[0.06] border border-white/[0.1] font-mono">
                <CornerDownLeft className="w-2.5 h-2.5" />
              </kbd>
              Select
            </span>
          </div>
          <span className="text-[9px] text-gray-600">METARDU Search</span>
        </div>
      </div>
    </>
  )
}

// ─── Helper components ──────────────────────────────────────────────────

function ResultRow({
  selected, onClick, onHover, icon: Icon, title, subtitle, href, category,
}: {
  selected: boolean
  onClick: () => void
  onHover: () => void
  icon: typeof LayoutDashboard
  title: string
  subtitle: string
  href?: string
  category?: string
}) {
  return (
    <div
      onClick={onClick}
      onMouseEnter={onHover}
      className={`flex items-center gap-3 px-3 py-2.5 rounded-lg cursor-pointer transition-colors ${
        selected ? 'bg-[#D17B47]/10' : 'hover:bg-white/[0.03]'
      }`}
    >
      <div className={`shrink-0 w-8 h-8 rounded-lg flex items-center justify-center ${
        selected ? 'bg-[#D17B47]/15' : 'bg-white/[0.04]'
      }`}>
        <Icon className={`w-4 h-4 ${selected ? 'text-[#D17B47]' : 'text-gray-400'}`} />
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-xs font-medium text-white truncate">{title}</div>
        <div className="text-[10px] text-gray-500 truncate">{subtitle}</div>
      </div>
      {category && (
        <span className="text-[9px] text-gray-600 px-1.5 py-0.5 rounded bg-white/[0.04] shrink-0">
          {category}
        </span>
      )}
      {selected && <ArrowRight className="w-3 h-3 text-[#D17B47] shrink-0" />}
    </div>
  )
}

function getResultIcon(type: string): typeof LayoutDashboard {
  switch (type) {
    case 'projects': return FolderKanban
    case 'tools': return Wrench
    case 'surveyors': return Users
    case 'documents': return FileText
    default: return Search
  }
}

function getHrefForType(type: string, id: string, meta?: Record<string, unknown>): string {
  switch (type) {
    case 'projects': return `/project/${id}`
    case 'surveyors': return `/community/directory?id=${id}`
    case 'documents': return `/documents?id=${id}`
    default: return `/search?q=${id}`
  }
}

'use client';

import { useState, useRef, useEffect, useId } from 'react'
import { Download } from 'lucide-react'
import { computeSettingOut, checkCoordinate, parseSettingOutCSV, type InstrumentStation, type Backsight, type DesignPoint, type ReObservation, type SettingOutResult } from '@/lib/computations/settingOutEngine'
import SettingOutTable from './SettingOutTable'
import StakeOutSheet from './StakeOutSheet'
import ChainageOffsetTable from './ChainageOffsetTable'
import { generatePDF, downloadCSV, toCSV } from '@/lib/export/helpers'

type PointRow = {
  id: string
  e: string
  n: string
  rl: string
  th: string
  desc: string
}

const pointFields: Array<keyof PointRow> = ['id', 'e', 'n', 'rl', 'th', 'desc']
const pointHeaders = ['ID', 'Easting', 'Northing', 'RL', 'TH', 'Description', ''] as const

export default function SettingOutCalculator() {
  const [station, setStation] = useState({ e: '', n: '', rl: '', ih: '' })
  const [bs, setBs] = useState({ e: '', n: '' })
  const [points, setPoints] = useState<PointRow[]>([])
  const [result, setResult] = useState<SettingOutResult | null>(null)
  const [checkResults, setCheckResults] = useState<{ pointId: string; obsHz: string; obsHD: string; obsRL: string }>({ pointId: '', obsHz: '', obsHD: '', obsRL: '' })
  const [checkResult, setCheckResult] = useState<ReturnType<typeof checkCoordinate> | null>(null)
  const [activeTab, setActiveTab] = useState<'table' | 'chainage' | 'check'>('table')
  const [csvError, setCsvError] = useState('')
  const [showStakeOutSheet, setShowStakeOutSheet] = useState(false)
  const fileRef = useRef<HTMLInputElement>(null)

  // Close the stake-out sheet on Escape (document-level, works regardless of focus)
  useEffect(() => {
    if (!showStakeOutSheet) return
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') setShowStakeOutSheet(false) }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [showStakeOutSheet])

  function compute() {
    const stationVal: InstrumentStation = {
      e: parseFloat(station.e),
      n: parseFloat(station.n),
      rl: parseFloat(station.rl),
      ih: parseFloat(station.ih),
    }
    const bsVal: Backsight = { e: parseFloat(bs.e), n: parseFloat(bs.n) }
    const pts: DesignPoint[] = points
      .filter(p => p.e && p.n && p.rl)
      .map(p => ({
        id: p.id || crypto.randomUUID(),
        e: parseFloat(p.e),
        n: parseFloat(p.n),
        rl: parseFloat(p.rl),
        th: parseFloat(p.th) || 2.0,
        description: p.desc,
      }))

    if (pts.length === 0) return
    const r = computeSettingOut(stationVal, bsVal, pts)
    setResult(r)
  }

  function runCheck() {
    if (!result || !checkResults.pointId) return
    const pt = result.rows.find((r: any) => r.id === checkResults.pointId)
    if (!pt) return
    const obs: ReObservation = {
      observedHz: parseFloat(checkResults.obsHz) || 0,
      observedHD: parseFloat(checkResults.obsHD) || 0,
      observedRL: checkResults.obsRL ? parseFloat(checkResults.obsRL) : undefined,
    }
    const designPt: DesignPoint = {
      id: pt.id,
      e: pt.designE,
      n: pt.designN,
      rl: pt.designRL,
      th: pt.TH,
    }
    const r = checkCoordinate(
      { e: parseFloat(station.e), n: parseFloat(station.n), rl: parseFloat(station.rl), ih: parseFloat(station.ih) },
      result.bsBearingDecimal,
      obs,
      designPt
    )
    setCheckResult(r)
  }

  function handleCSV(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    setCsvError('')
    const reader = new FileReader()
    reader.onload = ev => {
      try {
        const text = ev.target?.result as string
        const parsed = parseSettingOutCSV(text)
        if (parsed.length === 0) { setCsvError('No valid points found'); return }
        setPoints(parsed.map(p => ({
          id: p.id, e: p.e.toString(), n: p.n.toString(),
          rl: p.rl.toString(), th: p.th.toString(), desc: p.description || '',
        })))
      } catch {
        setCsvError('Failed to parse CSV')
      }
    }
    reader.readAsText(file)
  }

  function addPoint() {
    setPoints(prev => [...prev, { id: '', e: '', n: '', rl: '', th: '2.000', desc: '' }])
  }

  function removePoint(i: number) {
    setPoints(prev => prev.filter((_, idx) => idx !== i))
  }

  function updatePoint(i: number, field: keyof PointRow, value: string) {
    setPoints(prev => prev.map((p, idx) => idx === i ? { ...p, [field]: value } : p))
  }

  return (
    <div className="space-y-6">
      {/* Instrument Setup */}
      <div className="bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg p-4">
        <h3 className="text-sm font-semibold mb-3">Instrument Station Setup</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <Field label="Station E" value={station.e} onChange={v => setStation(s => ({ ...s, e: v }))} />
          <Field label="Station N" value={station.n} onChange={v => setStation(s => ({ ...s, n: v }))} />
          <Field label="Station RL (m)" value={station.rl} onChange={v => setStation(s => ({ ...s, rl: v }))} />
          <Field label="IH (m)" value={station.ih} onChange={v => setStation(s => ({ ...s, ih: v }))} />
          <Field label="BS E" value={bs.e} onChange={v => setBs(b => ({ ...b, e: v }))} />
          <Field label="BS N" value={bs.n} onChange={v => setBs(b => ({ ...b, n: v }))} />
        </div>
        {result && (
          <p className="text-xs font-mono mt-2 text-[var(--accent)]">
            BS Bearing: <span className="font-bold">{result.bsBearing}</span>
          </p>
        )}
      </div>

      {/* Design Points */}
      <div>
        <div className="flex items-center justify-between mb-2">
          <h3 className="text-sm font-semibold">Design Points</h3>
          <div className="flex gap-2">
            <input ref={fileRef} type="file" accept=".csv" onChange={handleCSV} className="hidden" />
            <button onClick={() => fileRef.current?.click()} className="px-3 py-1.5 text-xs border border-[var(--border-color)] rounded text-[var(--text-muted)]">Import CSV</button>
            <button onClick={addPoint} className="px-3 py-1.5 text-xs bg-[var(--accent)] text-white rounded">+ Add Point</button>
          </div>
        </div>
        {csvError && <p className="text-xs text-red-400 mb-2">{csvError}</p>}
        <p className="text-xs text-[var(--text-muted)] mb-2">Format: point_id, easting, northing, rl, TH, description</p>
        <div className="overflow-x-auto">
          <table className="w-full text-xs font-mono border-collapse">
            <thead>
                <tr className="bg-[var(--bg-tertiary)]">
                  {pointHeaders.map(h => (
                    <th key={h} className="px-2 py-2 text-left border border-[var(--border-color)] text-[var(--text-muted)] font-medium">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {points.map((p, i) => (
                  <tr key={`${p}-${i}`} className="hover:bg-[var(--bg-tertiary)]/30">
                    {pointFields.map(f => (
                      <td key={f} className="px-1 py-1 border border-[var(--border-color)]/50">
                        <input aria-label={pointHeaders[pointFields.indexOf(f)] ?? f} value={p[f]} onChange={e => updatePoint(i, f, e.target.value)}
                          className="w-full px-2 py-1 bg-transparent text-[var(--text-primary)]" />
                    </td>
                  ))}
                  <td className="px-1 py-1 border border-[var(--border-color)]/50">
                    <button onClick={() => removePoint(i)} className="text-red-400 hover:text-red-300 text-xs px-1">[x]</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Compute */}
      <div className="flex flex-wrap gap-3">
        <button onClick={compute} className="px-6 py-2 bg-[var(--accent)] text-white rounded font-medium hover:opacity-90">
          Compute Setting Out
        </button>
        {result && (
          <button onClick={() => setShowStakeOutSheet(true)} className="px-4 py-2 border border-[var(--border-color)] rounded text-sm hover:bg-[var(--bg-tertiary)]">
            Generate Stake Out Sheet
          </button>
        )}
        {result && (
          <>
            <button
              onClick={() => {
                generatePDF(
                  { title: 'Setting Out Schedule', reference: 'Ghilani & Wolf Ch.23 | RDM 1.1 Table 5.2' },
                  [
                    { title: 'Instrument Station', rows: [
                      { label: 'Station E', value: station.e || '—' },
                      { label: 'Station N', value: station.n || '—' },
                      { label: 'Station RL', value: `${station.rl || '—'} m` },
                      { label: 'IH', value: `${station.ih || '—'} m` },
                      { label: 'BS Bearing', value: result.bsBearing },
                    ]},
                  ],
                  [
                    { title: 'Setting Out Table', headers: ['Point ID', 'Hz Angle', 'HD (m)', 'ΔRL (m)', 'Design E', 'Design N', 'Design RL'], rows: result.rows.map((r: any) => [
                      r.id, r.horizontalAngle || '—', r.horizontalDistance?.toFixed(4) || '—',
                      r.deltaRL?.toFixed(4) || '—', r.designE?.toFixed(3) || '—',
                      r.designN?.toFixed(3) || '—', r.designRL?.toFixed(3) || '—',
                    ]) },
                  ],
                )
              }}
              className="px-4 py-2 border border-[var(--border-color)] rounded text-sm inline-flex items-center gap-2 hover:bg-[var(--bg-tertiary)]"
            >
              <Download className="w-4 h-4" /> Download PDF
            </button>
            <button
              onClick={() => {
                const csv = toCSV(
                  ['Point ID', 'Hz Angle', 'HD (m)', 'Delta RL (m)', 'Design E', 'Design N', 'Design RL'],
                  result.rows.map((r: any) => [
                    r.id, r.horizontalAngle || '', r.horizontalDistance?.toFixed(4) || '',
                    r.deltaRL?.toFixed(4) || '', r.designE?.toFixed(3) || '',
                    r.designN?.toFixed(3) || '', r.designRL?.toFixed(3) || '',
                  ]),
                )
                downloadCSV(csv, 'setting-out-data')
              }}
              className="px-4 py-2 border border-[var(--border-color)] rounded text-sm inline-flex items-center gap-2 hover:bg-[var(--bg-tertiary)]"
            >
              <Download className="w-4 h-4" /> Download CSV
            </button>
          </>
        )}
      </div>

      {/* Tabs */}
      {result && (
        <div className="flex gap-1 border-b border-[var(--border-color)]">
          {(['table', 'chainage', 'check'] as const).map((tab: any) => (
            <button key={tab} onClick={() => setActiveTab(tab)}
              className={`px-4 py-2 text-sm font-medium border-b-2 rounded-t ${activeTab === tab ? 'border-[var(--accent)] text-[var(--accent)]' : 'border-transparent text-[var(--text-muted)]'}`}>
              {tab === 'table' ? 'Setting Out Table' : tab === 'chainage' ? 'Chainage & Offset' : 'Re-Observation Check'}
            </button>
          ))}
        </div>
      )}

      {result && activeTab === 'table' && <SettingOutTable result={result} />}

      {result && activeTab === 'chainage' && <ChainageOffsetTable points={result.rows} />}

      {result && activeTab === 'check' && (
        <div className="bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-lg p-6 space-y-4">
          <h3 className="text-sm font-semibold">Re-Observation Check</h3>
          <p className="text-xs text-[var(--text-muted)]">Source: RDM 1.1 Table 5.2 — Construction tolerance: ±25mm horizontal, ±15mm vertical</p>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div>
              <label className="text-xs text-[var(--text-muted)] mb-1 block" htmlFor="point-id">Point ID</label>
              <select id="point-id" value={checkResults.pointId} onChange={e => setCheckResults(r => ({ ...r, pointId: e.target.value }))}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm">
                <option value="">Select point</option>
                {result.rows.map((r: any) => <option key={r.id} value={r.id}>{r.id} — {r.designE.toFixed(3)}/{r.designN.toFixed(3)}</option>)}
              </select>
            </div>
            <Field label="Observed Hz (°)" value={checkResults.obsHz} onChange={v => setCheckResults(r => ({ ...r, obsHz: v }))} />
            <Field label="Observed HD (m)" value={checkResults.obsHD} onChange={v => setCheckResults(r => ({ ...r, obsHD: v }))} />
            <Field label="Observed RL (m)" value={checkResults.obsRL} onChange={v => setCheckResults(r => ({ ...r, obsRL: v }))} />
          </div>
          <button onClick={runCheck} className="px-5 py-2 bg-[var(--accent)] text-white rounded text-sm font-medium">Check</button>

          {checkResult && (
            <div className={`border rounded-lg p-4 ${checkResult.isCompliant ? 'border-green-800 bg-green-900/20' : 'border-red-800 bg-red-900/20'}`}>
              <div className="flex items-center gap-2 mb-2">
                <span className={`text-lg font-bold ${checkResult.isCompliant ? 'text-green-400' : 'text-red-400'}`}>
                  {checkResult.isCompliant ? ' PASS — Within Tolerance' : '[x] FAIL — Re-set Required'}
                </span>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs font-mono">
                <div><span className="text-[var(--text-muted)]">ΔE: </span><span className={checkResult.deltaE > checkResult.hTolerance ? 'text-red-400' : 'text-green-400'}>{checkResult.deltaE.toFixed(4)}m</span></div>
                <div><span className="text-[var(--text-muted)]">ΔN: </span><span className={checkResult.deltaN > checkResult.hTolerance ? 'text-red-400' : 'text-green-400'}>{checkResult.deltaN.toFixed(4)}m</span></div>
                {checkResult.deltaRL !== null && (
                  <div><span className="text-[var(--text-muted)]">ΔRL: </span><span className={checkResult.vAccuracy === 'RED' ? 'text-red-400' : 'text-green-400'}>{checkResult.deltaRL.toFixed(4)}m</span></div>
                )}
                <div><span className="text-[var(--text-muted)]">Tolerance: </span><span>±{(checkResult.hTolerance * 1000).toFixed(0)}mm H / ±{(checkResult.vTolerance * 1000).toFixed(0)}mm V</span></div>
              </div>
              {checkResult.messages.map((m, i) => <p key={`${m}-${i}`} className="text-xs mt-1 text-[var(--text-secondary)]">{m}</p>)}
            </div>
          )}
        </div>
      )}

      {/* Stake Out Sheet Modal */}
      {showStakeOutSheet && result && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
          <button type="button" aria-label="Close dialog" tabIndex={-1} className="absolute inset-0 cursor-pointer border-0 p-0" onClick={() => setShowStakeOutSheet(false)} />
          <div className="relative bg-[var(--bg-primary)] max-w-2xl w-full rounded-lg overflow-hidden max-h-[90vh] overflow-y-auto border border-[var(--border-color)]" role="dialog" aria-modal="true" aria-label="Setting Out Schedule">
            <div className="p-4 border-b border-[var(--border-color)] flex justify-between items-center">
              <h2 className="font-bold text-[var(--text-primary)]">Setting Out Schedule</h2>
              <button onClick={() => setShowStakeOutSheet(false)} className="text-gray-500 hover:text-black">[x] Close</button>
            </div>
            <div className="p-4">
              <StakeOutSheet result={result} station={station} />
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

function Field({ label, value, onChange }: { label: string; value: string; onChange: (v: string) => void }) {
  const id = useId()
  return (
    <div>
      <label htmlFor={id} className="text-xs text-[var(--text-muted)] mb-1 block">{label}</label>
      <input id={id} value={value} onChange={e => onChange(e.target.value)} type="number" step="0.001"
        className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-[var(--text-primary)] text-sm" />
    </div>
  )
}

'use client'

/**
 * AccessibilityAudit — ARIA labels and keyboard navigation for screen readers
 *
 * This component wraps children and provides:
 * - Skip links to main content
 * - ARIA live regions for dynamic updates
 * - Keyboard focus management
 * - Screen reader announcements
 *
 * Per Kenya Constitution Article 54 — persons with disabilities
 * have the right to access information.
 */

import { useEffect, useRef, useCallback, ReactNode } from 'react'

interface AccessibilityWrapperProps {
  children: ReactNode
  /** Announcements for screen readers */
  announcements?: string[]
}

export function AccessibilityWrapper({ children, announcements = [] }: AccessibilityWrapperProps) {
  const liveRegionRef = useRef<HTMLDivElement>(null)

  // Announce changes to screen readers
  useEffect(() => {
    if (liveRegionRef.current && announcements.length > 0) {
      liveRegionRef.current.textContent = announcements.join('. ')
    }
  }, [announcements])

  return (
    <>
      {children}
      {/* ARIA live region for screen reader announcements */}
      <div
        ref={liveRegionRef}
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      />
    </>
  )
}

/**
 * Hook for managing focus trap (for modals, drawers)
 */
export function useFocusTrap(isActive: boolean) {
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!isActive || !containerRef.current) return

    const container = containerRef.current
    const focusableElements = container.querySelectorAll<HTMLElement>(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    )
    const firstElement = focusableElements[0]
    const lastElement = focusableElements[focusableElements.length - 1]

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return

      if (e.shiftKey) {
        if (document.activeElement === firstElement) {
          e.preventDefault()
          lastElement?.focus()
        }
      } else {
        if (document.activeElement === lastElement) {
          e.preventDefault()
          firstElement?.focus()
        }
      }
    }

    container.addEventListener('keydown', handleKeyDown)
    firstElement?.focus()

    return () => container.removeEventListener('keydown', handleKeyDown)
  }, [isActive])

  return containerRef
}

/**
 * Common ARIA props for interactive elements
 */
export const ARIA_PROPS = {
  // Map controls
  mapContainer: {
    role: 'application',
    'aria-label': 'Survey map — use arrow keys to pan, plus/minus to zoom',
  },
  zoomIn: {
    'aria-label': 'Zoom in',
    'aria-keyshortcuts': '+',
  },
  zoomOut: {
    'aria-label': 'Zoom out',
    'aria-keyshortcuts': '-',
  },
  // Tool dock
  toolDock: {
    role: 'toolbar',
    'aria-label': 'Survey tools',
    'aria-orientation': 'vertical',
  },
  // Fieldbook
  fieldbookTable: {
    role: 'grid',
    'aria-label': 'Field book observations',
  },
  fieldbookRow: {
    role: 'row',
  },
  fieldbookCell: {
    role: 'gridcell',
  },
  // Status
  loading: {
    'aria-live': 'polite',
    'aria-busy': 'true',
  },
  error: {
    role: 'alert',
    'aria-live': 'assertive',
  },
  // Navigation
  nav: {
    role: 'navigation',
    'aria-label': 'Main navigation',
  },
  // Buttons
  closeButton: {
    'aria-label': 'Close',
  },
  menuButton: {
    'aria-label': 'Open menu',
    'aria-expanded': false,
  },
}

/**
 * Announce a message to screen readers
 */
export function announce(message: string) {
  const liveRegion = document.createElement('div')
  liveRegion.setAttribute('aria-live', 'polite')
  liveRegion.setAttribute('aria-atomic', 'true')
  liveRegion.className = 'sr-only'
  liveRegion.textContent = message
  document.body.appendChild(liveRegion)

  setTimeout(() => {
    document.body.removeChild(liveRegion)
  }, 1000)
}

'use client'

import { useEffect } from 'react'
import Link from 'next/link'

interface AppErrorBoundaryProps {
  /** The error object from Next.js error boundary */
  error: Error & { digest?: string }
  /** Reset function from Next.js error boundary */
  reset: () => void
  /** Optional context label for area-specific messages (e.g. "Map failed to load") */
  context?: string
}

/**
 * Shared error boundary UI component used across all error.tsx pages.
 *
 * Features:
 * - Consistent error UI with project CSS variables
 * - Reports to Sentry via captureError
 * - Shows error digest for support reference
 * - "Try again" button calls reset()
 * - "Go to dashboard" fallback link
 * - Supports a context prop for area-specific messages
 */
export default function AppErrorBoundary({ error, reset, context }: AppErrorBoundaryProps) {
  useEffect(() => {
    // Report to Sentry via dynamic import
    import('@/lib/monitoring/sentry').then(({ captureError }) => {
      captureError(error, { context: context ?? 'global' })
    }).catch(() => {
      // Sentry not available — fall back to console
      console.error('[error-boundary]', error.message, error.digest ? `ref=${error.digest}` : '')
    })
  }, [error, context])

  return (
    <div
      className="min-h-[60vh] flex items-center justify-center px-4"
      style={{ background: 'var(--bg-primary)' }}
      role="alert"
      aria-live="assertive"
    >
      <div className="text-center max-w-md">
        {/* Error icon */}
        <div className="w-14 h-14 rounded-xl flex items-center justify-center mx-auto mb-5" style={{ background: 'rgba(239, 68, 68, 0.1)', border: '1px solid rgba(239, 68, 68, 0.2)' }}>
          <svg
            className="w-7 h-7"
            style={{ color: 'var(--error)' }}
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            strokeWidth={1.5}
          >
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
          </svg>
        </div>

        <h2
          className="text-xl font-semibold mb-2"
          style={{ color: 'var(--text-primary)', fontFamily: "'Geist', sans-serif" }}
        >
          {context || 'Something went wrong'}
        </h2>

        <p className="text-sm mb-6" style={{ color: 'var(--text-muted)' }}>
          {error.message || 'An unexpected error occurred. This is usually a temporary issue.'}
        </p>

        <div className="flex gap-3 justify-center flex-wrap">
          <button
            onClick={reset}
            className="px-5 py-2.5 rounded-lg font-semibold text-sm transition-colors"
            style={{ background: 'var(--accent)', color: '#000' }}
          >
            Try again
          </button>
          <Link
            href="/dashboard"
            className="px-5 py-2.5 rounded-lg font-semibold text-sm transition-colors inline-flex items-center gap-1.5"
            style={{ border: '1px solid var(--border-color)', color: 'var(--text-secondary)' }}
          >
            Go to dashboard
          </Link>
        </div>

        {error.digest && (
          <p
            className="text-xs mt-4 font-mono"
            style={{ color: 'var(--text-muted)' }}
          >
            Error ref: {error.digest}
          </p>
        )}
      </div>
    </div>
  )
}

'use client';

import { useEffect, useState } from 'react';
import { Wifi, WifiOff, CloudOff, Cloud } from 'lucide-react';

/**
 * Connectivity State Indicator
 * Surveyors need to know whether data is saved locally vs. synced to server.
 * Critical for field use where connectivity is intermittent.
 */
export function ConnectivityIndicator() {
  const [isOnline, setIsOnline] = useState(true);
  const [pendingOps, setPendingOps] = useState(0);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    setIsOnline(navigator.onLine);

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Check pending sync operations periodically
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const checkPending = async () => {
      try {
        const { getPendingOperations } = await import('@/lib/offline/syncQueue');
        const ops = await getPendingOperations();
        setPendingOps(ops.length);
      } catch {
        // Offline module not available — ignore
      }
    };

    checkPending();
    const interval = setInterval(checkPending, 30000);
    return () => clearInterval(interval);
  }, []);

  if (isOnline && pendingOps === 0) {
    return (
      <div className="flex items-center gap-1.5 text-xs text-green-600">
        <Cloud className="h-3.5 w-3.5" />
        <span className="hidden sm:inline">All data synced</span>
      </div>
    );
  }

  if (isOnline && pendingOps > 0) {
    return (
      <div className="flex items-center gap-1.5 text-xs text-yellow-600">
        <Wifi className="h-3.5 w-3.5 animate-pulse" />
        <span className="hidden sm:inline">Syncing {pendingOps} item{pendingOps !== 1 ? 's' : ''}...</span>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-1.5 text-xs text-orange-600">
      <CloudOff className="h-3.5 w-3.5" />
      <span className="hidden sm:inline">Offline — data saved locally</span>
    </div>
  );
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { Sun, Eye } from 'lucide-react'
import { useUIStore } from '@/stores/uiStore'
import { useLanguage } from '@/lib/i18n/LanguageContext'

/* ── Types ─────────────────────────────────────────────────────────────── */
type DisplayMode = 'dark' | 'field'

const STORAGE_KEY = 'metardu_display_mode'
const SENSOR_OPT_IN_KEY = 'metardu_auto_field_sensor'

/* ── Helpers ───────────────────────────────────────────────────────────── */

function getStoredMode(): DisplayMode {
  if (typeof window === 'undefined') return 'dark'
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === 'field' || stored === 'dark') return stored
  } catch { /* ignore */ }
  return 'dark'
}

function applyMode(mode: DisplayMode) {
  const html = document.documentElement
  // v0.3: set data-theme for new theming system + keep field-mode class for backward compat
  if (mode === 'field') {
    html.setAttribute('data-theme', 'field')
    html.classList.add('field-mode')
  } else {
    html.setAttribute('data-theme', 'dark')
    html.classList.remove('field-mode')
  }
}

function isSensorOptIn(): boolean {
  if (typeof window === 'undefined') return false
  try {
    return localStorage.getItem(SENSOR_OPT_IN_KEY) === 'true'
  } catch { return false }
}

/* ── Component ─────────────────────────────────────────────────────────── */

export default function FieldModeToggle() {
  const [mode, setMode] = useState<DisplayMode>('dark')
  const [mounted, setMounted] = useState(false)
  const [showTooltip, setShowTooltip] = useState(false)
  const [sensorEnabled, setSensorEnabled] = useState(false)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const sensorRef = useRef<any>(null)
  const tooltipDismissed = useRef(false)
  const addNotification = useUIStore((s) => s.addNotification)
  const { t } = useLanguage()

  /* ── Hydration-safe mount ───────────────────────────────────────────── */
  useEffect(() => {
    const stored = getStoredMode()
    setMode(stored)
    applyMode(stored)
    setSensorEnabled(isSensorOptIn())
    setMounted(true)
  }, [])

  /* ── First-use tooltip ──────────────────────────────────────────────── */
  useEffect(() => {
    if (!mounted) return
    try {
      const hasSeenTooltip = localStorage.getItem('metardu_field_tooltip_seen')
      if (!hasSeenTooltip && !tooltipDismissed.current) {
        const timer = setTimeout(() => setShowTooltip(true), 800)
        return () => clearTimeout(timer)
      }
    } catch { /* ignore */ }
  }, [mounted])

  /* ── Ambient light sensor (opt-in) ─────────────────────────────────── */
  useEffect(() => {
    if (!mounted || !sensorEnabled) return

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let sensor: any = null

    try {
      // The AmbientLightSensor API is only available in some browsers
      // and requires the 'ambient-light-sensor' permission.
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const AmbientLightSensorCtor = (window as any).AmbientLightSensor
      if (!AmbientLightSensorCtor) return

      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      sensor = new AmbientLightSensorCtor()
      sensorRef.current = sensor

      // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
      sensor.addEventListener('reading', () => {
        // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access
        const lux = sensor.illuminance
        if (typeof lux !== 'number') return

        // Auto-switch: bright sunlight is typically > 10,000 lux
        // Shade/overcast outdoor is 1,000–10,000; indoor is 100–500
        const currentStored = getStoredMode()
        if (lux > 10000 && currentStored === 'dark') {
          setMode('field')
          applyMode('field')
          localStorage.setItem(STORAGE_KEY, 'field')
          addNotification({
            type: 'info',
            title: t('fieldMode.autoActivated'),
            message: t('fieldMode.autoActivatedDesc'),
            duration: 4000,
          })
        } else if (lux < 3000 && currentStored === 'field') {
          setMode('dark')
          applyMode('dark')
          localStorage.setItem(STORAGE_KEY, 'dark')
          addNotification({
            type: 'info',
            title: t('fieldMode.darkRestored'),
            message: t('fieldMode.darkRestoredDesc'),
            duration: 4000,
          })
        }
      })

      // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-member-access
      sensor.addEventListener('error', () => {
        // Permission denied or sensor unavailable — silently disable
      })

      // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
      sensor.start()
    } catch {
      // Sensor API not available — no-op
    }

    return () => {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-member-access
      try { sensor?.stop?.() } catch { /* ignore */ }
      sensorRef.current = null
    }
  }, [mounted, sensorEnabled, addNotification, t])

  /* ── Toggle handler ────────────────────────────────────────────────── */
  const toggleMode = useCallback(() => {
    const next: DisplayMode = mode === 'dark' ? 'field' : 'dark'
    setMode(next)
    applyMode(next)
    localStorage.setItem(STORAGE_KEY, next)

    addNotification({
      type: next === 'field' ? 'success' : 'info',
      title: next === 'field' ? t('fieldMode.fieldEnabled') : t('fieldMode.darkEnabled'),
      message: next === 'field' ? t('fieldMode.fieldEnabledDesc') : t('fieldMode.darkEnabledDesc'),
      duration: 3000,
    })
  }, [mode, addNotification, t])

  /* ── Dismiss tooltip ───────────────────────────────────────────────── */
  const dismissTooltip = useCallback(() => {
    setShowTooltip(false)
    tooltipDismissed.current = true
    try { localStorage.setItem('metardu_field_tooltip_seen', 'true') } catch { /* ignore */ }
  }, [])

  /* ── Toggle sensor opt-in ──────────────────────────────────────────── */
  const toggleSensor = useCallback(() => {
    const next = !sensorEnabled
    setSensorEnabled(next)
    try { localStorage.setItem(SENSOR_OPT_IN_KEY, String(next)) } catch { /* ignore */ }
  }, [sensorEnabled])

  /* ── Prevent hydration mismatch ────────────────────────────────────── */
  if (!mounted) {
    return (
      <div className="w-10 h-10 rounded-lg bg-[var(--bg-tertiary)]/50 animate-pulse" />
    )
  }

  const isField = mode === 'field'

  return (
    <div className="relative">
      {/* Toggle button */}
      <button
        onClick={toggleMode}
        aria-label={isField ? t('fieldMode.switchToDark') : t('fieldMode.switchToField')}
        title={isField ? t('fieldMode.switchToDark') : t('fieldMode.tooltip')}
        className={`
          relative flex items-center justify-center
          w-10 h-10 rounded-lg
          transition-all duration-200 ease-out
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--bg-primary)]
          group
          ${isField
            ? 'bg-[var(--accent)] text-white shadow-lg shadow-[var(--accent)]/25'
            : 'bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)] text-[var(--text-secondary)] hover:text-[var(--accent)] hover:border-[var(--accent)]/40'
          }
        `}
      >
        {isField ? (
          <Eye className="w-5 h-5" strokeWidth={2} />
        ) : (
          <Sun className="w-5 h-5 group-hover:rotate-45 transition-transform duration-300" strokeWidth={2} />
        )}

        {/* Field mode active indicator dot */}
        {isField && (
          <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-white rounded-full border-2 border-[var(--accent)]" />
        )}
      </button>

      {/* First-use tooltip */}
      {showTooltip && (
        <div className="absolute top-full right-0 mt-2 z-50 w-64 animate-in fade-in slide-in-from-top-1 duration-200">
          <div className="bg-[var(--bg-secondary)] border border-[var(--accent)]/30 rounded-xl p-3 shadow-xl">
            <div className="flex items-start gap-2.5">
              <Sun className="w-5 h-5 text-[var(--accent)] flex-shrink-0 mt-0.5" strokeWidth={2} />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-[var(--text-primary)]">{t('field.fieldMode')}</p>
                <p className="text-xs text-[var(--text-secondary)] mt-1 leading-relaxed">
                  {t('fieldMode.fieldEnabledDesc')}
                </p>
              </div>
              <button
                onClick={dismissTooltip}
                className="text-[var(--text-muted)] hover:text-[var(--text-primary)] p-0.5 -mt-0.5 -mr-0.5"
                aria-label="Dismiss tooltip"
              >
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            {/* Sensor opt-in toggle */}
            <div className="mt-3 pt-2 border-t border-[var(--border-color)]">
              <label className="flex items-center gap-2 cursor-pointer select-none">
                <div
                  className={`
                    relative w-8 h-[18px] rounded-full transition-colors duration-200
                    ${sensorEnabled ? 'bg-[var(--accent)]' : 'bg-[var(--bg-tertiary)]'}
                  `}
                  onClick={toggleSensor}
                  role="switch"
                  aria-checked={sensorEnabled}
                  tabIndex={0}
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleSensor() } }}
                >
                  <div
                    className={`
                      absolute top-[2px] w-[14px] h-[14px] rounded-full bg-white shadow transition-transform duration-200
                      ${sensorEnabled ? 'translate-x-[17px]' : 'translate-x-[2px]'}
                    `}
                  />
                </div>
                <span className="text-[11px] text-[var(--text-muted)] leading-tight">
                  {t('fieldMode.autoDetectSunlight')}
                </span>
              </label>
            </div>
          </div>

          {/* Arrow */}
          <div className="absolute -top-1.5 right-4 w-3 h-3 bg-[var(--bg-secondary)] border-l border-t border-[var(--accent)]/30 rotate-45" />
        </div>
      )}

      {/* Click-away to dismiss tooltip */}
      {showTooltip && (
        <button type="button" aria-label="Dismiss tooltip" tabIndex={-1} className="fixed inset-0 z-40 cursor-pointer border-0 p-0" onClick={dismissTooltip} />
      )}
    </div>
  )
}

'use client';

/**
 * HotkeyHelpOverlay — Press "?" to see all registered keyboard shortcuts.
 * ──────────────────────────────────────────────────────────────────────
 * Reads the global hotkey registry and renders a searchable overlay.
 * Automatically disappears on Escape or clicking outside.
 */

import { useState, useEffect, useCallback } from 'react';
import { X, Keyboard } from 'lucide-react';
import { useHotkeys, getRegisteredHotkeys, formatHotkey } from '@/hooks/useHotkeys';

export function HotkeyHelpOverlay() {
  const [open, setOpen] = useState(false);

  useHotkeys('?', () => setOpen(prev => !prev), {
    description: 'Show keyboard shortcuts',
    enableInInput: false,
  });

  useHotkeys('escape', () => setOpen(false), {
    description: 'Close dialog',
    enableInInput: true,
  });

  if (!open) return null;

  const hotkeys = getRegisteredHotkeys();

  return (
    <div
      className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[80] flex items-center justify-center p-4"
      onClick={() => setOpen(false)}
    >
      <div
        className="bg-[var(--bg-primary)] border border-[var(--border-color)] rounded-2xl w-full max-w-md max-h-[70vh] overflow-hidden shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="px-5 py-4 border-b border-[var(--border-color)] flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <Keyboard className="w-5 h-5 text-[var(--accent)]" />
            <h2 className="text-base font-semibold text-[var(--text-primary)]">Keyboard Shortcuts</h2>
          </div>
          <button
            onClick={() => setOpen(false)}
            className="p-1.5 rounded-lg hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)]"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Shortcuts list */}
        <div className="overflow-y-auto p-4 space-y-1.5">
          {hotkeys.length === 0 ? (
            <p className="text-sm text-[var(--text-muted)] text-center py-8">
              No shortcuts registered yet. Navigate to a page to see its shortcuts.
            </p>
          ) : (
            hotkeys.map((hk, i) => (
              <div
                key={`${hk.keys}-${i}`}
                className="flex items-center justify-between py-2 px-3 rounded-lg hover:bg-[var(--bg-secondary)] transition-colors"
              >
                <span className="text-sm text-[var(--text-secondary)]">{hk.description}</span>
                <kbd className="px-2 py-1 rounded-md bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs font-mono text-[var(--accent)] whitespace-nowrap">
                  {formatHotkey(hk.keys)}
                </kbd>
              </div>
            ))
          )}
        </div>

        {/* Footer */}
        <div className="px-5 py-3 border-t border-[var(--border-color)] text-xs text-[var(--text-muted)] flex items-center justify-between">
          <span>{hotkeys.length} shortcut{hotkeys.length !== 1 ? 's' : ''}</span>
          <span>Press <kbd className="px-1.5 py-0.5 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] font-mono">?</kbd> to toggle</span>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react'
import { AlertTriangle } from 'lucide-react'
import { 
  parseParcelNumber, 
  lookupRegistrationSection, 
  getUTMZoneForParcel,
  type ParsedParcelNumber 
} from '@/lib/compute/parcelNumber'
import { KENYA_COUNTIES, type RegistrationSection } from '@/lib/data/kenyaLocalities'

interface ParcelNumberInputProps {
  value: string
  onChange: (value: string, parsed: ParsedParcelNumber) => void
  onUTMZoneDetected?: (zone: number, hemisphere: 'N' | 'S') => void
  disabled?: boolean
  required?: boolean
}

export default function ParcelNumberInput({ 
  value, 
  onChange, 
  onUTMZoneDetected,
  disabled,
  required 
}: ParcelNumberInputProps) {
  const [parsed, setParsed] = useState<ParsedParcelNumber>(parseParcelNumber(value))
  const [inputMode, setInputMode] = useState<'free' | 'structured'>('free')
  
  // Structured input fields
  const [selectedCounty, setSelectedCounty] = useState('')
  const [selectedSection, setSelectedSection] = useState('')
  const [blockNumber, setBlockNumber] = useState('')
  const [parcelNumber, setParcelNumber] = useState('')

  const sections = selectedCounty 
    ? KENYA_COUNTIES.find((c: any) => c.code === selectedCounty)?.registrationSections || []
    : []

  const currentSection = sections.find((s: any) => s.code === selectedSection)

  // Parse free-text input
  useEffect(() => {
    const result = parseParcelNumber(value)
    setParsed(result)
    
    // Update structured fields if we have a match
    if (result.registrationSection) {
      const section = lookupRegistrationSection(result.registrationSection)
      if (section) {
        const county = KENYA_COUNTIES.find((c: any) => c.code === section.county)
        if (county) {
          setSelectedCounty(county.code)
          setSelectedSection(section.code)
          if (result.block) setBlockNumber(String(result.block))
          if (result.parcelNumber) setParcelNumber(String(result.parcelNumber))
        }
      }
    }
    
    // Auto-detect UTM zone
    if (result.registrationSection && result.isValid) {
      const { zone, hemisphere } = getUTMZoneForParcel(result.registrationSection)
      onUTMZoneDetected?.(zone, hemisphere)
    }
  }, [value, onUTMZoneDetected])

  const handleFreeTextChange = (text: string) => {
    const result = parseParcelNumber(text)
    setParsed(result)
    onChange(text, result)
    
    if (result.registrationSection && result.isValid) {
      const { zone, hemisphere } = getUTMZoneForParcel(result.registrationSection)
      onUTMZoneDetected?.(zone, hemisphere)
    }
  }

  const handleStructuredChange = useCallback(() => {
    if (!selectedSection || !parcelNumber) return
    
    let rawValue: string
    if (currentSection?.hasBlocks && blockNumber) {
      const sectionName = currentSection.name.split(' ')[0]
      rawValue = `${sectionName} BLOCK ${blockNumber}/${parcelNumber}`
    } else {
      rawValue = `${selectedSection}/${parcelNumber}`
    }
    
    const result = parseParcelNumber(rawValue)
    setParsed(result)
    onChange(rawValue, result)
    
    const { zone, hemisphere } = getUTMZoneForParcel(selectedSection)
    onUTMZoneDetected?.(zone, hemisphere)
  }, [selectedSection, blockNumber, parcelNumber, currentSection, onChange, onUTMZoneDetected])

  return (
    <div className="space-y-4">
      {/* Input mode toggle */}
      <div className="flex gap-2 text-sm">
        <button
          type="button"
          onClick={() => setInputMode('free')}
          className={`px-3 py-1 rounded ${inputMode === 'free' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)]'}`}
        >
          Free Text
        </button>
        <button
          type="button"
          onClick={() => setInputMode('structured')}
          className={`px-3 py-1 rounded ${inputMode === 'structured' ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)]'}`}
        >
          Structured
        </button>
      </div>

      {inputMode === 'free' ? (
        <div>
          <input
            type="text"
            value={value}
            onChange={e => handleFreeTextChange(e.target.value)}
            disabled={disabled}
            required={required}
            aria-label="e.g. NAIROBI BLOCK 2/1234 or KIAMBU/456" placeholder="e.g. NAIROBI BLOCK 2/1234 or KIAMBU/456"
            className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
          />
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="county">County</label>
            <select id="county"
              value={selectedCounty}
              onChange={e => {
                setSelectedCounty(e.target.value)
                setSelectedSection('')
              }}
              disabled={disabled}
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            >
              <option value="">Select County</option>
              {KENYA_COUNTIES.map((c: any) => (
                <option key={c.code} value={c.code}>{c.name}</option>
              ))}
            </select>
          </div>
          
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="section">Section</label>
            <select id="section"
              value={selectedSection}
              onChange={e => {
                setSelectedSection(e.target.value)
                handleStructuredChange()
              }}
              disabled={disabled || !selectedCounty}
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            >
              <option value="">Select Section</option>
              {sections.map((s: any) => (
                <option key={s.code} value={s.code}>{s.name}</option>
              ))}
            </select>
          </div>
          
          {currentSection?.hasBlocks && (
            <div>
              <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="block">Block</label>
              <input id="block"
                type="number"
                value={blockNumber}
                onChange={e => {
                  setBlockNumber(e.target.value)
                  handleStructuredChange()
                }}
                disabled={disabled}
                aria-label="1" placeholder="1"
                className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
              />
            </div>
          )}
          
          <div>
            <label className="block text-xs text-[var(--text-muted)] mb-1" htmlFor="parcel-no">Parcel No.</label>
            <input
              type="number"
              value={parcelNumber}
              onChange={e => {
                setParcelNumber(e.target.value)
                handleStructuredChange()
              }}
              disabled={disabled}
              required={required}
              aria-label="1234" placeholder="1234"
              className="w-full px-2 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-sm"
            />
          </div>
        </div>
      )}

      {/* Validation feedback */}
      {parsed.isValid ? (
        <div className="p-3 bg-green-50 border border-green-200 rounded-lg">
          <div className="flex items-center gap-2 text-green-700 text-sm">
            <span></span>
            <span>Valid parcel number</span>
          </div>
          {parsed.formatted && (
            <div className="mt-2 text-xs space-y-1">
              <div><span className="text-[var(--text-muted)]">Canonical:</span> {parsed.formatted}</div>
              <div><span className="text-[var(--text-muted)]">Short:</span> {parsed.shortForm}</div>
              {parsed.county && (
                <div><span className="text-[var(--text-muted)]">County:</span> {parsed.county}</div>
              )}
              {parsed.registrationSection && (
                <div><span className="text-[var(--text-muted)]">Section:</span> {parsed.registrationSection}</div>
              )}
              <div className="text-[var(--accent)] font-medium mt-1">
                UTM Zone: {getUTMZoneForParcel(parsed.registrationSection || '').zone}
                {getUTMZoneForParcel(parsed.registrationSection || '').hemisphere}
              </div>
            </div>
          )}
        </div>
      ) : (
        parsed.validationErrors.length > 0 && (
          <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
            <div className="flex items-center gap-2 text-red-700 text-sm mb-1">
              <span><AlertTriangle className="w-3.5 h-3.5 inline shrink-0" /></span>
              <span>Invalid</span>
            </div>
            <ul className="text-xs text-red-600 space-y-1">
              {parsed.validationErrors.map((err, i) => (
                <li key={`${err}-${i}`}>{err}</li>
              ))}
            </ul>
          </div>
        )
      )}
    </div>
  )
}

'use client';

import { useState, useRef, useEffect } from 'react'
import { Pen, Type, FileCheck, Check } from 'lucide-react'
import type { DigitalSignature } from '@/types/signature'

interface SignatureCaptureProps {
  documentId: string
  documentType: DigitalSignature['documentType']
  documentContent: string
  onSigned: (sig: DigitalSignature) => void
  surveyorName?: string
  iskNumber?: string
}

export default function SignatureCapture({
  documentId,
  documentType,
  documentContent,
  onSigned,
  surveyorName = '',
  iskNumber = ''
}: SignatureCaptureProps) {
  const [activeTab, setActiveTab] = useState<'draw' | 'type' | 'certificate'>('draw')
  const [signatureData, setSignatureData] = useState<string>('')
  const [typedName, setTypedName] = useState(surveyorName)
  const [typedIsk, setTypedIsk] = useState(iskNumber)
  const [confirmed, setConfirmed] = useState(false)
  const [loading, setLoading] = useState(false)
  const [signed, setSigned] = useState(false)
  const [result, setResult] = useState<{ verificationToken: string; signatureId: string } | null>(null)

  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [isDrawing, setIsDrawing] = useState(false)

  useEffect(() => {
    if (activeTab === 'draw' && canvasRef.current) {
      const canvas = canvasRef.current
      const ctx = canvas.getContext('2d')
      if (ctx) {
        ctx.fillStyle = '#fff'
        ctx.fillRect(0, 0, canvas.width, canvas.height)
        ctx.strokeStyle = '#000'
        ctx.lineWidth = 2
        ctx.lineCap = 'round'
      }
    }
  }, [activeTab])

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    setIsDrawing(true)
    const rect = canvas.getBoundingClientRect()
    const x = ('touches' in e ? e.touches[0].clientX : e.clientX) - rect.left
    const y = ('touches' in e ? e.touches[0].clientY : e.clientY) - rect.top
    ctx.beginPath()
    ctx.moveTo(x, y)
  }

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing) return
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const rect = canvas.getBoundingClientRect()
    const x = ('touches' in e ? e.touches[0].clientX : e.clientX) - rect.left
    const y = ('touches' in e ? e.touches[0].clientY : e.clientY) - rect.top
    ctx.lineTo(x, y)
    ctx.stroke()
  }

  const stopDrawing = () => {
    setIsDrawing(false)
    if (canvasRef.current) {
      setSignatureData(canvasRef.current.toDataURL('image/png'))
    }
  }

  const clearCanvas = () => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    ctx.fillStyle = '#fff'
    ctx.fillRect(0, 0, canvas.width, canvas.height)
    setSignatureData('')
  }

  const handleSign = async () => {
    const method = activeTab === 'draw' ? 'DRAWN' : 'TYPED'
    const data = activeTab === 'draw' ? signatureData : `TYPED:${typedName}:${typedIsk}`

    if (!data && method === 'DRAWN') return
    if (activeTab === 'type' && (!typedName || !confirmed)) return

    setLoading(true)

    try {
      const res = await fetch('/api/signature/sign', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          documentId,
          documentType,
          content: documentContent,
          method,
          signatureData: data
        })
      })

      const responseData = await res.json()

      if (responseData.verificationToken) {
        setResult({
          verificationToken: responseData.verificationToken,
          signatureId: responseData.signatureId
        })
        setSigned(true)
        onSigned({
          id: responseData.signatureId,
          documentId,
          documentType,
          signedBy: '',
          surveyorName,
          iskNumber: iskNumber || typedIsk,
          firmName: '',
          signedAt: new Date().toISOString(),
          documentHash: responseData.documentHash,
          signatureData: data,
          method: method as 'DRAWN' | 'TYPED',
          valid: true,
          verificationToken: responseData.verificationToken
        })
      }
    } catch (error) {
      console.error('Sign error:', error)
    }

    setLoading(false)
  }

  if (signed && result) {
    return (
      <div className="p-6 bg-green-50 border border-green-200 rounded-xl">
        <div className="flex items-center gap-2 mb-4">
          <Check className="w-6 h-6 text-green-600" />
          <h3 className="font-semibold text-green-800">Document Signed Successfully</h3>
        </div>
        <div className="space-y-2 text-sm">
          <p><span className="text-gray-500">Verification Token:</span> <code className="bg-white px-2 py-1 rounded">{result.verificationToken}</code></p>
          <p className="text-gray-600">
            This token can be used to verify the document authenticity via QR code or the verification link.
          </p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex border-b">
        <button
          onClick={() => setActiveTab('draw')}
          className={`flex items-center gap-2 px-4 py-2 ${activeTab === 'draw' ? 'border-b-2 border-sky-600 text-sky-600' : 'text-gray-500'}`}
        >
          <Pen className="w-4 h-4" />
          Draw
        </button>
        <button
          onClick={() => setActiveTab('type')}
          className={`flex items-center gap-2 px-4 py-2 ${activeTab === 'type' ? 'border-b-2 border-sky-600 text-sky-600' : 'text-gray-500'}`}
        >
          <Type className="w-4 h-4" />
          Type
        </button>
        <button
          onClick={() => setActiveTab('certificate')}
          className={`flex items-center gap-2 px-4 py-2 ${activeTab === 'certificate' ? 'border-b-2 border-sky-600 text-sky-600' : 'text-gray-500'}`}
          disabled
        >
          <FileCheck className="w-4 h-4" />
          Certificate
        </button>
      </div>

      {activeTab === 'draw' && (
        <div className="space-y-2">
          <canvas
            ref={canvasRef}
            width={400}
            height={150}
            className="border rounded-lg cursor-crosshair touch-none"
            onMouseDown={startDrawing}
            onMouseMove={draw}
            onMouseUp={stopDrawing}
            onMouseLeave={stopDrawing}
            onTouchStart={startDrawing}
            onTouchMove={draw}
            onTouchEnd={stopDrawing}
          />
          <button onClick={clearCanvas} className="text-sm text-gray-500 hover:text-gray-700">
            Clear
          </button>
        </div>
      )}

      {activeTab === 'type' && (
        <div className="space-y-4">
          <p className="text-sm text-gray-600">
            I, {typedName || '[Name]'}, ISK No. {typedIsk || '[ISK Number]'}, hereby certify this document
            as correct and complete per Survey Act Cap 299 s.17
          </p>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1" htmlFor="full-name">Full Name</label>
            <input id="full-name"
              type="text"
              value={typedName}
              onChange={e => setTypedName(e.target.value)}
              aria-label="Enter your full name" placeholder="Enter your full name"
              className="w-full p-2 border rounded-lg"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1" htmlFor="isk-number">ISK Number</label>
            <input id="isk-number"
              type="text"
              value={typedIsk}
              onChange={e => setTypedIsk(e.target.value)}
              aria-label="e.g., ISK/1234" placeholder="e.g., ISK/1234"
              className="w-full p-2 border rounded-lg"
            />
          </div>
          <label className="flex items-center gap-2">
            <input aria-label="ISK Number"
              type="checkbox"
              checked={confirmed}
              onChange={e => setConfirmed(e.target.checked)}
              className="rounded"
            />
            <span className="text-sm">I confirm this is my legal signature</span>
          </label>
        </div>
      )}

      {activeTab === 'certificate' && (
        <div className="p-4 bg-gray-100 rounded-lg text-center text-gray-500">
          <p>Coming soon — PKI certificate signing</p>
        </div>
      )}

      <button
        onClick={handleSign}
        disabled={loading || (activeTab === 'draw' && !signatureData) || (activeTab === 'type' && (!typedName || !confirmed))}
        className="w-full py-2 bg-sky-600 text-white rounded-lg hover:bg-sky-700 disabled:opacity-50"
      >
        {loading ? 'Signing...' : 'Sign Document'}
      </button>
    </div>
  )
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { ScrollArea } from '@/components/ui/scroll-area'
import {
  Clock,
  ChevronDown,
  RotateCcw,
  User,
  FileText,
  AlertTriangle,
  Loader2,
} from 'lucide-react'

/* ────────────────────────────────────────────────────────────────────────────
   Types
   ──────────────────────────────────────────────────────────────────────────── */

interface VersionEntry {
  id: string
  entity_type: string
  entity_id: string
  version: number
  snapshot: Record<string, unknown>
  delta: Record<string, { old: unknown; new: unknown }> | null
  change_summary: string | null
  created_by: string | null
  created_at: string
}

interface DiffChange {
  field: string
  old_value: unknown
  new_value: unknown
}

interface DiffResponse {
  entity_type: string
  entity_id: string
  from_version: number
  to_version: number
  from_date: string
  to_date: string
  changes: DiffChange[]
  change_count: number
}

interface VersionHistoryPanelProps {
  /** Entity table name, e.g. 'projects', 'parcels' */
  entityType: string
  /** UUID of the entity */
  entityId: string
  /** Optional: max height of the timeline before scrolling */
  maxHeight?: string
  /** Optional: callback after a successful restore */
  onRestored?: () => void
}

/* ────────────────────────────────────────────────────────────────────────────
   Helpers
   ──────────────────────────────────────────────────────────────────────────── */

function formatDate(iso: string): string {
  try {
    return new Date(iso).toLocaleString(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    })
  } catch {
    return iso
  }
}

function formatValue(val: unknown): string {
  if (val === null || val === undefined) return '—'
  if (typeof val === 'object') return JSON.stringify(val)
  return String(val)
}

const ENTITY_LABELS: Record<string, string> = {
  parcels: 'Parcel',
  blocks: 'Block',
  projects: 'Project',
  traverse_results: 'Traverse Result',
  traverse_history: 'Traverse History',
  traverse_observations: 'Traverse Observation',
  project_fieldbook_entries: 'Fieldbook Entry',
  survey_points: 'Survey Point',
}

/* ────────────────────────────────────────────────────────────────────────────
   Component
   ──────────────────────────────────────────────────────────────────────────── */

export function VersionHistoryPanel({
  entityType,
  entityId,
  maxHeight = '24rem',
  onRestored,
}: VersionHistoryPanelProps) {
  const [versions, setVersions] = useState<VersionEntry[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Expanded version diff
  const [expandedId, setExpandedId] = useState<string | null>(null)
  const [diffData, setDiffData] = useState<DiffResponse | null>(null)
  const [diffLoading, setDiffLoading] = useState(false)

  // Restore dialog
  const [restoreTarget, setRestoreTarget] = useState<VersionEntry | null>(null)
  const [restoring, setRestoring] = useState(false)

  /* ── Fetch version history ── */
  const fetchVersions = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const params = new URLSearchParams({
        entity_type: entityType,
        entity_id: entityId,
        limit: '50',
      })
      const res = await fetch(`/api/versions?${params}`)
      if (!res.ok) {
        const body = await res.json().catch(() => ({}))
        throw new Error(body.error || `Failed to load versions (${res.status})`)
      }
      const json = await res.json()
      setVersions(json.data ?? [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error')
    } finally {
      setLoading(false)
    }
  }, [entityType, entityId])

  useEffect(() => {
    fetchVersions()
  }, [fetchVersions])

  /* ── Fetch diff on expand ── */
  const handleToggle = useCallback(
    async (versionId: string) => {
      if (expandedId === versionId) {
        setExpandedId(null)
        setDiffData(null)
        return
      }

      setExpandedId(versionId)
      setDiffData(null)
      setDiffLoading(true)

      try {
        const entry = versions.find((v) => v.id === versionId)
        if (!entry || entry.version <= 1) {
          // Version 1 has no previous version to diff against
          setDiffLoading(false)
          return
        }
        const params = new URLSearchParams({
          compare_with: String(entry.version - 1),
        })
        const res = await fetch(`/api/versions/${versionId}/diff?${params}`)
        if (!res.ok) {
          setDiffLoading(false)
          return
        }
        const json = await res.json()
        setDiffData(json)
      } catch {
        // silently fail — diff is non-critical
      } finally {
        setDiffLoading(false)
      }
    },
    [expandedId, versions]
  )

  /* ── Restore ── */
  const handleRestore = useCallback(async () => {
    if (!restoreTarget) return
    setRestoring(true)
    try {
      const res = await fetch(`/api/versions/${restoreTarget.id}/restore`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ version_id: restoreTarget.id }),
      })
      if (!res.ok) {
        const body = await res.json().catch(() => ({}))
        throw new Error(body.error || `Restore failed (${res.status})`)
      }
      setRestoreTarget(null)
      // Refresh the version list after restore
      await fetchVersions()
      onRestored?.()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Restore failed')
    } finally {
      setRestoring(false)
    }
  }, [restoreTarget, fetchVersions, onRestored])

  /* ────────────────────────────────────────────────────────────────────────
     Render
     ──────────────────────────────────────────────────────────────────────── */

  const entityLabel = ENTITY_LABELS[entityType] ?? entityType

  return (
    <div className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <div className="card-header">
        <div className="flex items-center gap-2 text-sm font-medium text-[var(--text-primary)]">
          <Clock className="h-4 w-4 text-[var(--accent)]" />
          Version History
          <span className="text-[var(--text-muted)] font-normal">
            — {entityLabel}
          </span>
        </div>
        <Badge variant="outline" className="text-[var(--text-muted)]">
          {versions.length} {versions.length === 1 ? 'revision' : 'revisions'}
        </Badge>
      </div>

      {/* Body */}
      <div className="card-body p-0">
        {loading && (
          <div className="flex items-center justify-center py-12 text-[var(--text-muted)]">
            <Loader2 className="h-5 w-5 animate-spin mr-2" />
            Loading history…
          </div>
        )}

        {!loading && error && (
          <div className="flex items-center gap-2 px-4 py-3 text-sm text-[var(--error)] bg-[var(--error)]/10">
            <AlertTriangle className="h-4 w-4 shrink-0" />
            {error}
          </div>
        )}

        {!loading && !error && versions.length === 0 && (
          <div className="px-4 py-8 text-center text-sm text-[var(--text-muted)]">
            No version history recorded yet.
          </div>
        )}

        {!loading && !error && versions.length > 0 && (
          <ScrollArea style={{ maxHeight }}>
            <div className="divide-y divide-[var(--border-color)]">
              {versions.map((v) => {
                const isExpanded = expandedId === v.id
                const isDeleted = v.change_summary === 'DELETED'

                return (
                  <Collapsible
                    key={v.id}
                    open={isExpanded}
                    onOpenChange={() => handleToggle(v.id)}
                  >
                    {/* Timeline entry trigger */}
                    <CollapsibleTrigger asChild>
                      <button
                        className="w-full text-left px-4 py-3 flex items-start gap-3 hover:bg-[var(--glass-bg)] transition-colors duration-150 focus-ring"
                        aria-label={`Version ${v.version} — ${v.change_summary || 'No summary'}`}
                      >
                        {/* Timeline dot */}
                        <div className="mt-1 shrink-0">
                          <span
                            className={`block h-2.5 w-2.5 rounded-full ${
                              isDeleted
                                ? 'bg-[var(--error)]'
                                : v.version === 1
                                ? 'bg-[var(--success)]'
                                : 'bg-[var(--accent)]'
                            }`}
                          />
                        </div>

                        {/* Content */}
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2 flex-wrap">
                            <Badge
                              variant="outline"
                              className="text-xs font-mono"
                            >
                              v{v.version}
                            </Badge>
                            {isDeleted && (
                              <Badge
                                variant="destructive"
                                className="text-xs"
                              >
                                Deleted
                              </Badge>
                            )}
                            {v.version === 1 && !isDeleted && (
                              <Badge className="text-xs bg-[var(--success)]/20 text-[var(--success)] border-[var(--success)]/30">
                                Created
                              </Badge>
                            )}
                            <span className="text-xs text-[var(--text-muted)]">
                              {formatDate(v.created_at)}
                            </span>
                          </div>

                          {/* Summary line */}
                          <p className="mt-1 text-sm text-[var(--text-secondary)] truncate">
                            {v.change_summary ||
                              (v.version === 1
                                ? 'Initial version'
                                : `Revision ${v.version}`)}
                          </p>

                          {/* Who changed it */}
                          {v.created_by && (
                            <p className="mt-0.5 text-xs text-[var(--text-muted)] flex items-center gap-1">
                              <User className="h-3 w-3" />
                              {v.created_by.slice(0, 8)}…
                            </p>
                          )}
                        </div>

                        {/* Expand chevron */}
                        <ChevronDown
                          className={`h-4 w-4 shrink-0 text-[var(--text-muted)] transition-transform duration-200 ${
                            isExpanded ? 'rotate-180' : ''
                          }`}
                        />
                      </button>
                    </CollapsibleTrigger>

                    {/* Expanded diff content */}
                    <CollapsibleContent>
                      <div className="px-4 pb-3 pl-10">
                        {diffLoading && (
                          <div className="flex items-center gap-2 text-xs text-[var(--text-muted)] py-2">
                            <Loader2 className="h-3 w-3 animate-spin" />
                            Loading diff…
                          </div>
                        )}

                        {isExpanded && !diffLoading && v.version === 1 && (
                          <div className="text-xs text-[var(--text-muted)] py-2 flex items-center gap-1">
                            <FileText className="h-3 w-3" />
                            Initial creation — no previous version to compare.
                          </div>
                        )}

                        {isExpanded &&
                          !diffLoading &&
                          diffData &&
                          v.version > 1 && (
                            <div className="space-y-2">
                              {diffData.changes.length === 0 ? (
                                <p className="text-xs text-[var(--text-muted)] py-1">
                                  No field-level changes detected.
                                </p>
                              ) : (
                                <div className="rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] overflow-hidden">
                                  <table className="w-full text-xs">
                                    <thead>
                                      <tr className="table-header">
                                        <th className="px-3 py-2 text-left">
                                          Field
                                        </th>
                                        <th className="px-3 py-2 text-left">
                                          Before
                                        </th>
                                        <th className="px-3 py-2 text-left">
                                          After
                                        </th>
                                      </tr>
                                    </thead>
                                    <tbody>
                                      {diffData.changes.map((c) => (
                                        <tr
                                          key={c.field}
                                          className="table-row"
                                        >
                                          <td className="table-cell font-mono font-medium text-[var(--text-primary)]">
                                            {c.field}
                                          </td>
                                          <td className="table-cell text-[var(--error)]/80">
                                            <span className="line-through opacity-70">
                                              {formatValue(c.old_value)}
                                            </span>
                                          </td>
                                          <td className="table-cell text-[var(--success)]">
                                            {formatValue(c.new_value)}
                                          </td>
                                        </tr>
                                      ))}
                                    </tbody>
                                  </table>
                                </div>
                              )}

                              {/* Restore button — not shown for version 1 or deleted entries */}
                              {!isDeleted && v.version > 1 && (
                                <Button
                                  variant="outline"
                                  size="sm"
                                  className="mt-2 text-xs border-[var(--accent)]/40 text-[var(--accent)] hover:bg-[var(--accent)]/10 hover:text-[var(--accent)]"
                                  onClick={(e) => {
                                    e.stopPropagation()
                                    setRestoreTarget(v)
                                  }}
                                >
                                  <RotateCcw className="h-3 w-3 mr-1" />
                                  Restore this version
                                </Button>
                              )}
                            </div>
                          )}
                      </div>
                    </CollapsibleContent>
                  </Collapsible>
                )
              })}
            </div>
          </ScrollArea>
        )}
      </div>

      {/* ── Restore confirmation dialog ── */}
      <Dialog
        open={!!restoreTarget}
        onOpenChange={(open) => !open && setRestoreTarget(null)}
      >
        <DialogContent className="bg-[var(--bg-card)] border-[var(--border-color)]">
          <DialogHeader>
            <DialogTitle className="text-[var(--text-primary)]">
              Restore to Version {restoreTarget?.version}?
            </DialogTitle>
            <DialogDescription className="text-[var(--text-secondary)]">
              This will revert the {entityLabel} back to the state it was in on{' '}
              {restoreTarget ? formatDate(restoreTarget.created_at) : ''}. A new
              version snapshot will be created for full traceability — no history
              will be lost.
            </DialogDescription>
          </DialogHeader>

          {restoreTarget?.change_summary && (
            <div className="rounded border border-[var(--border-color)] bg-[var(--bg-tertiary)] p-3 text-sm text-[var(--text-secondary)]">
              <span className="font-medium text-[var(--text-primary)]">
                Summary:
              </span>{' '}
              {restoreTarget.change_summary}
            </div>
          )}

          <DialogFooter>
            <Button
              variant="ghost"
              onClick={() => setRestoreTarget(null)}
              disabled={restoring}
              className="text-[var(--text-secondary)]"
            >
              Cancel
            </Button>
            <Button
              onClick={handleRestore}
              disabled={restoring}
              className="bg-[var(--accent)] text-white hover:bg-[var(--accent-dim)]"
            >
              {restoring && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
              <RotateCcw className="h-4 w-4 mr-2" />
              Restore
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client';

import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import {
  VariableSizeList as List,
  type ListChildComponentProps,
} from 'react-window';
import { Checkbox } from '@/components/ui/checkbox';
import { Inbox } from 'lucide-react';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

export interface ColumnDef<T> {
  key: string;
  header: string;
  width: number;
  render?: (row: T) => ReactNode;
  sortable?: boolean;
  align?: 'left' | 'center' | 'right';
}

export interface VirtualizedTableProps<T> {
  rows: T[];
  columns: ColumnDef<T>[];
  /** Fixed row height in px (default 40) */
  rowHeight?: number;
  /** Height of the entire table viewport in px (default 500) */
  tableHeight?: number;
  onRowClick?: (row: T, index: number) => void;
  /** Set of selected row *indices* */
  selectedRows?: Set<number>;
  onSelectionChange?: (selected: Set<number>) => void;
  /** Show the checkbox column (default false) */
  selectable?: boolean;
  /** Stick header row to the top (default true) */
  headerSticky?: boolean;
  /** Unique key per row — defaults to index */
  rowKey?: (row: T, index: number) => string;
  /** Custom empty-state message */
  emptyMessage?: string;
  className?: string;
  /** Accessible label for the table */
  'aria-label'?: string;
}

/* ------------------------------------------------------------------ */
/*  Fallback (non-virtualized) renderer                                */
/* ------------------------------------------------------------------ */

function FallbackTable<T>({
  rows,
  columns,
  rowHeight = 40,
  onRowClick,
  selectedRows,
  onSelectionChange,
  selectable,
  emptyMessage = 'No data',
  rowKey,
}: VirtualizedTableProps<T>) {
  const allSelected = rows.length > 0 && selectedRows && selectedRows.size === rows.length;
  const someSelected = selectedRows && selectedRows.size > 0 && !allSelected;

  const toggleAll = () => {
    if (!onSelectionChange) return;
    if (allSelected) {
      onSelectionChange(new Set());
    } else {
      onSelectionChange(new Set(rows.map((_, i) => i)));
    }
  };

  const toggleRow = (idx: number) => {
    if (!onSelectionChange || !selectedRows) return;
    const next = new Set(selectedRows);
    if (next.has(idx)) next.delete(idx);
    else next.add(idx);
    onSelectionChange(next);
  };

  const totalWidth = columns.reduce((s, c) => s + c.width, 0) + (selectable ? 48 : 0);

  return (
    <div className="overflow-x-auto rounded-lg border border-[var(--border-color)]" style={{ maxHeight: 600 }}>
      <table className="w-full text-sm" style={{ minWidth: totalWidth }}>
        <thead className="sticky top-0 z-10">
          <tr
            className="border-b border-[var(--border-color)] text-left text-xs uppercase tracking-wider text-[var(--text-muted)]"
            style={{ background: 'var(--bg-secondary)' }}
          >
            {selectable && (
              <th className="px-3 py-2 w-12" style={{ width: 48 }}>
                <Checkbox
                  checked={allSelected ? true : someSelected ? 'indeterminate' : false}
                  onCheckedChange={toggleAll}
                  aria-label="Select all rows"
                />
              </th>
            )}
            {columns.map((col) => (
              <th
                key={col.key}
                className="px-3 py-2 font-semibold whitespace-nowrap"
                style={{
                  width: col.width,
                  minWidth: col.width,
                  textAlign: col.align ?? 'left',
                }}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 && (
            <tr>
              <td
                colSpan={columns.length + (selectable ? 1 : 0)}
                className="py-16 text-center text-[var(--text-muted)]"
              >
                <Inbox className="mx-auto mb-2 h-8 w-8 opacity-40" />
                {emptyMessage}
              </td>
            </tr>
          )}
          {rows.map((row, idx) => {
            const isSelected = selectedRows?.has(idx) ?? false;
            return (
              <tr
                key={rowKey ? rowKey(row, idx) : idx}
                className={`
                  border-b border-[var(--border-color)]/30 transition-colors
                  ${idx % 2 === 0 ? 'bg-[var(--bg-primary)]' : 'bg-[var(--bg-secondary)]'}
                  ${isSelected ? 'bg-[var(--accent-subtle)]' : ''}
                  ${onRowClick ? 'cursor-pointer hover:bg-[var(--accent-subtle)]' : ''}
                `}
                style={{ height: rowHeight }}
                onClick={() => onRowClick?.(row, idx)}
                onKeyDown={(e) => {
                  if (onRowClick && (e.key === 'Enter' || e.key === ' ')) {
                    e.preventDefault()
                    onRowClick(row, idx)
                  }
                }}
                tabIndex={onRowClick ? 0 : undefined}
              >
                {selectable && (
                  <td className="px-3 py-2 w-12" onClick={(e) => e.stopPropagation()}>
                    <Checkbox
                      checked={isSelected}
                      onCheckedChange={() => toggleRow(idx)}
                      aria-label={`Select row ${idx + 1}`}
                    />
                  </td>
                )}
                {columns.map((col) => (
                  <td
                    key={col.key}
                    className="px-3 py-2 whitespace-nowrap"
                    style={{ textAlign: col.align ?? 'left' }}
                  >
                    {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? '—')}
                  </td>
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Virtualized Table                                                  */
/* ------------------------------------------------------------------ */

function VirtualizedTableInner<T>(props: VirtualizedTableProps<T>) {
  const {
    rows,
    columns,
    rowHeight = 40,
    tableHeight = 500,
    onRowClick,
    selectedRows = new Set(),
    onSelectionChange,
    selectable = false,
    headerSticky = true,
    rowKey,
    emptyMessage = 'No data to display',
    className,
    'aria-label': ariaLabel,
  } = props;

  const listRef = useRef<List>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [containerWidth, setContainerWidth] = useState(0);

  /* ---- Responsive width ---- */
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const obs = new ResizeObserver((entries) => {
      setContainerWidth(entries[0]?.contentRect.width ?? 0);
    });
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  /* ---- Derived ---- */
  const totalWidth = useMemo(
    () => columns.reduce((s, c) => s + c.width, 0) + (selectable ? 48 : 0),
    [columns, selectable],
  );
  const needsHorizontalScroll = totalWidth > containerWidth && containerWidth > 0;
  const listWidth = needsHorizontalScroll ? totalWidth : containerWidth;

  const allSelected = rows.length > 0 && selectedRows.size === rows.length;
  const someSelected = selectedRows.size > 0 && !allSelected;

  /* ---- Handlers ---- */
  const toggleAll = useCallback(() => {
    if (!onSelectionChange) return;
    if (allSelected) {
      onSelectionChange(new Set());
    } else {
      onSelectionChange(new Set(rows.map((_, i) => i)));
    }
  }, [allSelected, onSelectionChange, rows]);

  const toggleRow = useCallback(
    (idx: number) => {
      if (!onSelectionChange) return;
      const next = new Set(selectedRows);
      if (next.has(idx)) next.delete(idx);
      else next.add(idx);
      onSelectionChange(next);
    },
    [onSelectionChange, selectedRows],
  );

  /* ---- Row height estimator (constant for now, but VariableSizeList ready) ---- */
  const getRowSize = useCallback(() => rowHeight, [rowHeight]);
  const headerHeight = 42;

  /* ---- Row renderer ---- */
  const Row = useCallback(
    ({ index, style }: ListChildComponentProps) => {
      const row = rows[index];
      const isSelected = selectedRows.has(index);
      const bgClass =
        isSelected
          ? 'bg-[var(--accent-subtle)]'
          : index % 2 === 0
            ? 'bg-[var(--bg-primary)]'
            : 'bg-[var(--bg-secondary)]';

      return (
        <div
          style={{
            ...style,
            display: 'flex',
            alignItems: 'center',
            cursor: onRowClick ? 'pointer' : undefined,
          }}
          className={`
            border-b border-[var(--border-color)]/20 transition-colors
            ${bgClass}
            ${onRowClick ? 'hover:bg-[var(--accent-subtle)]' : ''}
          `}
          onClick={() => onRowClick?.(row, index)}
          onKeyDown={(e) => {
            if (onRowClick && (e.key === 'Enter' || e.key === ' ')) {
              e.preventDefault()
              onRowClick(row, index)
            }
          }}
          tabIndex={onRowClick ? 0 : undefined}
          role="row"
        >
          {selectable && (
            <div
              className="flex items-center justify-center shrink-0"
              style={{ width: 48 }}
              onClick={(e) => e.stopPropagation()}
            >
              <Checkbox
                checked={isSelected}
                onCheckedChange={() => toggleRow(index)}
                aria-label={`Select row ${index + 1}`}
              />
            </div>
          )}
          {columns.map((col) => (
            <div
              key={col.key}
              className="px-3 py-2 text-sm whitespace-nowrap overflow-hidden text-ellipsis"
              style={{
                width: col.width,
                minWidth: col.width,
                textAlign: col.align ?? 'left',
              }}
              role="cell"
            >
              {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? '—')}
            </div>
          ))}
        </div>
      );
    },
    [rows, columns, selectable, selectedRows, onRowClick, toggleRow],
  );

  /* ---- Scroll-to-row ---- */
  const scrollToRow = useCallback(
    (index: number) => {
      listRef.current?.scrollToItem(index, 'center');
    },
    [],
  );

  // Expose scrollToRow via ref (imperative handle)
  React.useImperativeHandle(
    (props as VirtualizedTableProps<T> & { ref?: React.Ref<{ scrollToRow: (i: number) => void }> }).ref,
    () => ({ scrollToRow }),
    [scrollToRow],
  );

  /* ---- Empty state ---- */
  if (rows.length === 0) {
    return (
      <div
        ref={containerRef}
        className={`rounded-lg border border-[var(--border-color)] flex flex-col items-center justify-center text-[var(--text-muted)] ${className ?? ''}`}
        style={{ height: tableHeight, background: 'var(--bg-primary)' }}
      >
        <Inbox className="h-10 w-10 mb-2 opacity-40" />
        <p className="text-sm">{emptyMessage}</p>
      </div>
    );
  }

  /* ---- Render ---- */
  return (
    <div
      ref={containerRef}
      className={`rounded-lg border border-[var(--border-color)] overflow-hidden ${className ?? ''}`}
      style={{ background: 'var(--bg-primary)' }}
      role="table"
      aria-label={ariaLabel}
      aria-rowcount={rows.length + 1}
      aria-colcount={columns.length + (selectable ? 1 : 0)}
    >
      {/* Sticky header */}
      {headerSticky && (
        <div
          className="flex items-center border-b border-[var(--border-color)] text-xs uppercase tracking-wider text-[var(--text-muted)] shrink-0"
          style={{
            height: headerHeight,
            background: 'var(--bg-secondary)',
            minWidth: needsHorizontalScroll ? totalWidth : undefined,
          }}
          role="row"
        >
          {selectable && (
            <div className="flex items-center justify-center shrink-0" style={{ width: 48 }} role="columnheader">
              <Checkbox
                checked={allSelected ? true : someSelected ? 'indeterminate' : false}
                onCheckedChange={toggleAll}
                aria-label="Select all rows"
              />
            </div>
          )}
          {columns.map((col) => (
            <div
              key={col.key}
              className="px-3 py-2 font-semibold whitespace-nowrap"
              style={{
                width: col.width,
                minWidth: col.width,
                textAlign: col.align ?? 'left',
              }}
              role="columnheader"
              aria-sort={col.sortable ? 'none' : undefined}
            >
              {col.header}
            </div>
          ))}
        </div>
      )}

      {/* Virtualized body — wrap in scroll container for horizontal scroll */}
      <div className={needsHorizontalScroll ? 'overflow-x-auto' : ''}>
        <List
          ref={listRef}
          height={tableHeight - headerHeight}
          itemCount={rows.length}
          itemSize={getRowSize}
          width={listWidth}
          overscanCount={8}
        >
          {Row}
        </List>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  Export with dynamic import guard                                    */
/* ------------------------------------------------------------------ */

/**
 * VirtualizedTable wraps react-window's VariableSizeList for efficient
 * rendering of large datasets (500+ rows).
 *
 * If react-window fails to load, it falls back to a standard HTML table.
 */
export function VirtualizedTable<T>(props: VirtualizedTableProps<T>) {
  const [useVirtualized, setUseVirtualized] = useState(true);

  useEffect(() => {
    // Verify react-window is actually available at runtime
    try {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const rw = require('react-window');
      if (!rw.VariableSizeList) setUseVirtualized(false);
    } catch {
      setUseVirtualized(false);
    }
  }, []);

  if (!useVirtualized) {
    return <FallbackTable {...props} />;
  }

  return <VirtualizedTableInner {...props} />;
}

export default VirtualizedTable;

'use client';

/**
 * VoiceDictationButton
 * ---------------------
 * Hands-free voice-to-text button designed for surveyors wearing gloves
 * in the field. Uses the browser's Web Speech API to transcribe speech
 * and append it to any text input.
 *
 * Features:
 *   - Pulsing red indicator when recording
 *   - Appends transcribed text (does NOT replace existing text)
 *   - Continuous recognition (keeps listening across sentences)
 *   - Interim results shown in lighter colour
 *   - Auto-detects language from i18n context (useLanguage)
 *   - Gracefully hides on browsers without Web Speech API support
 *   - Fully accessible with aria-label
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { Mic, MicOff } from 'lucide-react';
import { useLanguage } from '@/lib/i18n/LanguageContext';
import type { Language } from '@/lib/i18n/messages';

/* ------------------------------------------------------------------ */
/*  Language mapping: i18n code → Web Speech API BCP-47 code          */
/* ------------------------------------------------------------------ */

const SPEECH_LANG_MAP: Record<string, string> = {
  en: 'en-US',
  sw: 'sw-KE',   // Swahili — Kenya
  ar: 'ar-SA',   // Arabic — Saudi Arabia
  fr: 'fr-FR',
  ha: 'ha-NG',   // Hausa — Nigeria
  pt: 'pt-PT',
  es: 'es-ES',
  zh: 'zh-CN',
  ja: 'ja-JP',
  ru: 'ru-RU',
  hi: 'hi-IN',
  id: 'id-ID',
  am: 'am-ET',   // Amharic — Ethiopia
  de: 'de-DE',
};

function toSpeechLang(i18nCode: Language | string): string {
  return SPEECH_LANG_MAP[i18nCode] ?? `${i18nCode}-${i18nCode.toUpperCase()}`;
}

/* ------------------------------------------------------------------ */
/*  Web Speech API types (not in standard TS lib)                     */
/* ------------------------------------------------------------------ */

interface SpeechRecognitionEvent {
  results: SpeechRecognitionResultList;
  resultIndex: number;
}

interface SpeechRecognitionErrorEvent {
  error: string;
  message?: string;
}

interface SpeechRecognitionInstance {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start(): void;
  stop(): void;
  abort(): void;
  onresult: ((event: SpeechRecognitionEvent) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEvent) => void) | null;
  onend: (() => void) | null;
}

/* ------------------------------------------------------------------ */
/*  Component                                                         */
/* ------------------------------------------------------------------ */

export interface VoiceDictationButtonProps {
  /** Current text value of the input this button is associated with */
  value: string;
  /** Callback to update the text value */
  onChange: (value: string) => void;
  /** Override language; defaults to auto-detect from i18n context */
  language?: string;
  /** Optional additional CSS class on the wrapper */
  className?: string;
}

export function VoiceDictationButton({
  value,
  onChange,
  language,
  className,
}: VoiceDictationButtonProps) {
  /* ── i18n ──────────────────────────────────────────────────────── */
  let i18nLanguage: Language | undefined;
  let t: (key: string, values?: Record<string, string | number>) => string;
  try {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    const ctx = useLanguage();
    i18nLanguage = ctx.language;
    t = ctx.t;
  } catch {
    // LanguageProvider may not be available in all contexts; that's fine
    t = (key: string) => key;
  }

  const speechLang = language ?? (i18nLanguage ? toSpeechLang(i18nLanguage) : 'en-US');

  /* ── State ─────────────────────────────────────────────────────── */
  const [listening, setListening] = useState(false);
  const [interimText, setInterimText] = useState('');
  const [supported, setSupported] = useState(false);

  const recognitionRef = useRef<SpeechRecognitionInstance | null>(null);
  const valueRef = useRef(value);

  // Keep valueRef in sync so the onresult callback always has latest text
  useEffect(() => {
    valueRef.current = value;
  }, [value]);

  /* ── Browser support check ─────────────────────────────────────── */
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const SpeechRecognitionAPI =
      (window as any).SpeechRecognition ?? (window as any).webkitSpeechRecognition;
    setSupported(!!SpeechRecognitionAPI);
  }, []);

  /* ── Cleanup on unmount ────────────────────────────────────────── */
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        try { recognitionRef.current.abort(); } catch { /* ignore */ }
      }
    };
  }, []);

  /* ── Toggle listening ──────────────────────────────────────────── */
  const toggleListening = useCallback(() => {
    if (listening) {
      // Stop
      try { recognitionRef.current?.stop(); } catch { /* ignore */ }
      setListening(false);
      setInterimText('');
      return;
    }

    // Start
    const SpeechRecognitionAPI =
      (window as any).SpeechRecognition ?? (window as any).webkitSpeechRecognition;
    if (!SpeechRecognitionAPI) return;

    const recognition: SpeechRecognitionInstance = new SpeechRecognitionAPI();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = speechLang;

    let finalTranscriptAccumulated = '';

    recognition.onresult = (event: SpeechRecognitionEvent) => {
      let interim = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const transcript = event.results[i][0].transcript;
        if (event.results[i].isFinal) {
          finalTranscriptAccumulated += transcript + ' ';
        } else {
          interim += transcript;
        }
      }

      // Append final results to the actual value
      if (finalTranscriptAccumulated.trim()) {
        const current = valueRef.current;
        const separator = current.trim() ? ' ' : '';
        onChange(current.trimEnd() + separator + finalTranscriptAccumulated.trim());
        finalTranscriptAccumulated = '';
      }

      // Show interim results in lighter colour
      setInterimText(interim);
    };

    recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
      console.warn('VoiceDictation error:', event.error);
      if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
        setListening(false);
        setInterimText('');
      }
    };

    recognition.onend = () => {
      // If still in "listening" state (not manually stopped), restart
      // for continuous behaviour — the API can auto-stop on silence.
      setListening((prev) => {
        if (prev) {
          // Auto-restart for continuous recognition
          try { recognition.start(); } catch { /* already started */ }
        }
        return prev;
      });
    };

    recognitionRef.current = recognition;

    try {
      recognition.start();
      setListening(true);
    } catch (err) {
      console.warn('VoiceDictation failed to start:', err);
      setListening(false);
    }
  }, [listening, speechLang, onChange]);

  /* ── Manual stop when component unmounts or user clicks ────────── */
  const handleStop = useCallback(() => {
    setListening(false);
    setInterimText('');
    try { recognitionRef.current?.stop(); } catch { /* ignore */ }
  }, []);

  /* ── Don't render if browser doesn't support Web Speech API ────── */
  if (!supported) return null;

  /* ── Render ────────────────────────────────────────────────────── */
  return (
    <div className={`inline-flex items-center gap-1.5 ${className ?? ''}`}>
      <button
        type="button"
        onClick={listening ? handleStop : toggleListening}
        className={[
          'relative inline-flex items-center justify-center',
          'w-10 h-10 rounded-lg transition-all touch-manipulation',
          'focus:outline-none focus:ring-2 focus:ring-offset-1',
          listening
            ? 'bg-red-500/15 text-red-500 focus:ring-red-500/40'
            : 'bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:text-[var(--accent)] hover:bg-[var(--accent)]/10 focus:ring-[var(--accent)]/40',
        ].join(' ')}
        aria-label={listening ? t('voiceDictation.stopDictation') : t('voiceDictation.startDictation')}
        title={listening ? t('voiceDictation.listening') : t('voiceDictation.tapToDictate')}
      >
        {/* Pulsing red ring when listening */}
        {listening && (
          <span className="absolute inset-0 rounded-lg ring-2 ring-red-500/60 animate-pulse" />
        )}

        {listening ? (
          <MicOff className="w-5 h-5 relative z-10" />
        ) : (
          <Mic className="w-5 h-5 relative z-10" />
        )}
      </button>

      {/* Listening indicator + interim text */}
      {listening && (
        <span className="flex items-center gap-1.5 text-xs select-none">
          <span className="flex items-center gap-1 text-red-500 font-medium whitespace-nowrap">
            <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
            {t('voiceDictation.listening')}
          </span>
          {interimText && (
            <span className="text-[var(--text-muted)] italic truncate max-w-[140px]">
              {interimText}
            </span>
          )}
        </span>
      )}
    </div>
  );
}

'use client';
/**
 * METARDU Subdivision Panel
 *
 * UI panel for parcel subdivision operations.
 * Supports four methods: Grid, Radial, Area-Based, and Single Split.
 *
 * Style: Tailwind CSS, #1B3A5C primary, white cards, Calibri font.
 * Matches existing METARDU UI patterns from MeasurementTool and ParcelBuilderModal.
 */


import { useState } from 'react'
import {
  Grid3X3,
  Radar,
  Ruler,
  Scissors,
  Play,
  Trash2,
  Download,
  MapPin,
  Loader2,
  AlertCircle,
  ChevronDown,
  Info,
  Road,
  Eye,
  EyeOff,
  Printer,
} from 'lucide-react'
import type { SubdivisionMethod, SubdivisionParams, SubdivisionResult, SubdividedLot } from '@/types/subdivision'
import type { Point2D } from '@/lib/engine/types'
import { useSubdivision } from '@/hooks/useSubdivision'
import { usePrint, PrintButton, PrintHeader } from '@/hooks/usePrint'
import type Map from 'ol/Map'

interface SubdivisionPanelProps {
  /** Parent parcel vertices (EPSG:21037) */
  parentVertices: Point2D[]
  /** OpenLayers map instance */
  map: Map | null
  /** Project name for DXF export */
  projectName?: string
  /** CSS class for panel container */
  className?: string
}

type MethodOption = {
  id: SubdivisionMethod
  label: string
  icon: React.ReactNode
  description: string
}

const METHODS: MethodOption[] = [
  {
    id: 'grid',
    label: 'Grid',
    icon: <Grid3X3 className="w-4 h-4" />,
    description: 'Divide into equal grid cells',
  },
  {
    id: 'radial',
    label: 'Radial',
    icon: <Radar className="w-4 h-4" />,
    description: 'Create sectors from a center point',
  },
  {
    id: 'area',
    label: 'Area',
    icon: <Ruler className="w-4 h-4" />,
    description: 'Split by target lot area',
  },
  {
    id: 'single-split',
    label: 'Split Line',
    icon: <Scissors className="w-4 h-4" />,
    description: 'Cut by drawing a line on the map',
  },
]

function formatAreaHa(ha: number): string {
  if (ha < 0.01) return `${(ha * 10000).toFixed(1)} m²`
  return `${ha.toFixed(4)} ha`
}

function formatPerimeter(m: number): string {
  if (m < 1000) return `${m.toFixed(2)} m`
  return `${(m / 1000).toFixed(3)} km`
}

export default function SubdivisionPanel({
  parentVertices,
  map,
  projectName = 'METARDU_Subdivision',
  className = '',
}: SubdivisionPanelProps) {
  const {
    method,
    params,
    result,
    splitLine,
    isDrawingSplitLine,
    isComputing,
    error,
    roadReserveEnabled,
    roadReserveWidth,
    roadReserveEdges,
    roadReserveAuto,
    roadReservePreview,
    selectMethod,
    updateParams,
    execute,
    clear,
    startSplitLineDrawing,
    pickCenterPoint,
    exportDXF,
    setRoadReserveEnabled,
    setRoadReserveWidth,
    setRoadReserveAuto,
    previewRoadReserve,
    clearRoadReservePreview,
    toggleRoadReserveEdge,
  } = useSubdivision({
    parentVertices,
    map,
    projectName,
  })

  const [isCollapsed, setIsCollapsed] = useState(false)
  const { print, isPrinting, paperSize, setPaperSize, orientation, setOrientation } = usePrint({
    title: 'Subdivision Report',
    subtitle: `Method: ${method} · ${result ? `${result.lots.length} lots` : 'No results'}`,
  })

  // ─── Compute parent area ──────────────────────────────────────────────
  const parentArea = (() => {
    if (parentVertices.length < 3) return 0
    let area = 0
    const n = parentVertices.length
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n
      area += parentVertices[i].easting * parentVertices[j].northing
      area -= parentVertices[j].easting * parentVertices[i].northing
    }
    return Math.abs(area / 2) / 10000
  })()

  return (
    <div className={`bg-white rounded-lg shadow-lg border border-gray-200 ${className}`}>
      <PrintHeader
        title="Subdivision Report"
        subtitle={`Project: ${projectName} · Method: ${method} · ${result ? `${result.lots.length} lots · Total: ${formatAreaHa(result.totalAreaHa)}` : ''}`}
      />
      {/* ─── Header ──────────────────────────────────────────────────── */}
      <div
        className="flex items-center justify-between px-4 py-3 border-b border-gray-200 cursor-pointer select-none"
        onClick={() => setIsCollapsed(!isCollapsed)}
      >
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded bg-[#1B3A5C] flex items-center justify-center text-white">
            <Grid3X3 className="w-4 h-4" />
          </div>
          <div>
            <div className="text-sm font-semibold text-gray-900">Subdivision</div>
            <div className="text-[10px] text-gray-500">
              {parentVertices.length} pts · {formatAreaHa(parentArea)}
            </div>
          </div>
        </div>
        <ChevronDown className={`w-4 h-4 text-gray-400 transition-transform ${isCollapsed ? '-rotate-90' : ''}`} />
      </div>

      {isCollapsed ? null : (
        <div className="divide-y divide-gray-100">
          {/* ─── Road Reserve Section ──────────────────────────────────── */}
          <div className="p-3">
            <div className="flex items-center justify-between mb-2">
              <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium">
                Road Reserve
              </div>
              <button
                onClick={(e) => { e.stopPropagation(); setRoadReserveEnabled(!roadReserveEnabled); if (roadReserveEnabled) clearRoadReservePreview() }}
                className={`relative w-9 h-5 rounded-full transition-colors ${
                  roadReserveEnabled ? 'bg-[#1B3A5C]' : 'bg-gray-300'
                }`}
              >
                <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow transition-transform ${
                  roadReserveEnabled ? 'translate-x-4' : 'translate-x-0'
                }`} />
              </button>
            </div>

            {roadReserveEnabled && (
              <div className="space-y-2.5 mt-2">
                {/* Width input */}
                <div>
                  <label className="text-[10px] text-gray-500 block mb-1" htmlFor="width-m">Width (m)</label>
                  <input id="width-m" aria-label="Width (m)"
                    type="number"
                    min={1}
                    max={100}
                    step={1}
                    value={roadReserveWidth}
                    onChange={(e) => setRoadReserveWidth(Math.max(1, parseFloat(e.target.value) || 1))}
                    className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none font-mono"
                  />
                  <div className="text-[10px] text-gray-400 mt-1">
                    {roadReserveWidth < 8 ? 'Single lane' : roadReserveWidth < 16 ? '2-lane road' : roadReserveWidth < 24 ? '4-lane road' : 'Multi-lane / boulevard'}
                  </div>
                </div>

                {/* Edge selector */}
                <div>
                  <div className="text-[10px] text-gray-500 block mb-1">Edge Selection</div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => setRoadReserveAuto(true)}
                      className={`flex-1 px-2.5 py-1.5 text-[11px] font-medium rounded-md transition-colors ${
                        roadReserveAuto
                          ? 'bg-[#1B3A5C] text-white'
                          : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200'
                      }`}
                    >
                      Auto (longest)
                    </button>
                    <button
                      onClick={() => setRoadReserveAuto(false)}
                      className={`flex-1 px-2.5 py-1.5 text-[11px] font-medium rounded-md transition-colors ${
                        !roadReserveAuto
                          ? 'bg-[#1B3A5C] text-white'
                          : 'bg-gray-100 text-gray-600 hover:bg-gray-200 border border-gray-200'
                      }`}
                    >
                      Manual
                    </button>
                  </div>
                </div>

                {/* Manual edge checkboxes */}
                {!roadReserveAuto && parentVertices.length >= 3 && (
                  <div className="border border-gray-200 rounded-md p-2 max-h-24 overflow-y-auto">
                    <div className="text-[10px] text-gray-400 mb-1">Select edges to apply road reserve:</div>
                    <div className="grid grid-cols-3 gap-1">
                      {parentVertices.map((_, idx) => {
                        if (idx >= parentVertices.length) return null
                        const nextIdx = (idx + 1) % parentVertices.length
                        const dx = parentVertices[nextIdx].easting - parentVertices[idx].easting
                        const dy = parentVertices[nextIdx].northing - parentVertices[idx].northing
                        const len = Math.sqrt(dx * dx + dy * dy)
                        return (
                          <label
                            key={`${_}-${idx}`}
                            className={`flex items-center gap-1 px-1.5 py-1 rounded text-[10px] cursor-pointer transition-colors ${
                              roadReserveEdges.includes(idx)
                                ? 'bg-amber-50 border border-amber-300 text-amber-800'
                                : 'bg-gray-50 border border-gray-200 text-gray-500 hover:bg-gray-100'
                            }`}
                          >
                            <input aria-label="Road reserve"
                              type="checkbox"
                              checked={roadReserveEdges.includes(idx)}
                              onChange={() => toggleRoadReserveEdge(idx)}
                              className="w-3 h-3 accent-[#1B3A5C]"
                            />
                            E{idx} ({len.toFixed(0)}m)
                          </label>
                        )
                      })}
                    </div>
                  </div>
                )}

                {/* Preview & info */}
                <div className="flex items-center gap-2">
                  <button
                    onClick={previewRoadReserve}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-[#1B3A5C] bg-amber-50 border border-amber-200 rounded-md hover:bg-amber-100 transition-colors"
                  >
                    <Eye className="w-3.5 h-3.5" />
                    Preview
                  </button>
                  {roadReservePreview && (
                    <button
                      onClick={clearRoadReservePreview}
                      className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-gray-600 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors"
                    >
                      <EyeOff className="w-3.5 h-3.5" />
                      Hide
                    </button>
                  )}
                </div>

                {roadReservePreview && (
                  <div className="p-2 bg-amber-50 border border-amber-200 rounded-md">
                    <div className="text-[11px] text-amber-800 font-medium mb-1">
                      <Road className="w-3.5 h-3.5 inline mr-1" />
                      Road Reserve Preview
                    </div>
                    <div className="text-[10px] text-amber-700 space-y-0.5">
                      <div>Width: {roadReservePreview.width}m</div>
                      <div>Area: {formatAreaHa(roadReservePreview.areaHa)}</div>
                      <div>Edge{roadReservePreview.clippedEdges.length !== 1 ? 's' : ''}: {roadReservePreview.clippedEdges.join(', ')}</div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* ─── Method Selector ──────────────────────────────────────── */}
          <div className="p-3">
            <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
              Method
            </div>
            <div className="grid grid-cols-2 gap-1.5">
              {METHODS.map((m) => (
                <button
                  key={m.id}
                  onClick={() => selectMethod(m.id)}
                  className={`flex items-center gap-1.5 px-2.5 py-2 rounded-md text-xs font-medium transition-colors ${
                    method === m.id
                      ? 'bg-[#1B3A5C] text-white shadow-sm'
                      : 'bg-gray-50 text-gray-700 hover:bg-gray-100 border border-gray-200'
                  }`}
                  title={m.description}
                >
                  {m.icon}
                  <span>{m.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* ─── Parameters Form ──────────────────────────────────────── */}
          {method && (
            <div className="p-3 bg-gray-50/50">
              <div className="text-[10px] text-gray-500 uppercase tracking-wider font-medium mb-2 block">
                Parameters
              </div>

              {/* Grid params */}
              {method === 'grid' && (
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="rows">Rows</label>
                    <input id="rows" aria-label="Rows"
                      type="number"
                      min={1}
                      max={20}
                      value={params.rows ?? 2}
                      onChange={(e) => updateParams({ rows: Math.max(1, parseInt(e.target.value) || 1) })}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="columns">Columns</label>
                    <input id="columns" aria-label="Columns"
                      type="number"
                      min={1}
                      max={20}
                      value={params.cols ?? 2}
                      onChange={(e) => updateParams({ cols: Math.max(1, parseInt(e.target.value) || 1) })}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                    />
                  </div>
                  <div className="col-span-2 text-[10px] text-gray-400 mt-1">
                    Creates up to {((params.rows ?? 2) * (params.cols ?? 2))} lots
                  </div>
                </div>
              )}

              {/* Radial params */}
              {method === 'radial' && (
                <div className="space-y-3">
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="number-of-lots">Number of Lots</label>
                    <input id="number-of-lots" aria-label="Number of Lots"
                      type="number"
                      min={2}
                      max={36}
                      value={params.numLots ?? 4}
                      onChange={(e) => updateParams({ numLots: Math.max(2, parseInt(e.target.value) || 2) })}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none"
                    />
                  </div>
                  <div>
                    <div className="text-[10px] text-gray-500 block mb-1">Center Point</div>
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() => pickCenterPoint()}
                        className="flex items-center gap-1.5 px-3 py-1.5 text-xs bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors"
                      >
                        <MapPin className="w-3.5 h-3.5 text-[#1B3A5C]" />
                        {params.center
                          ? `E ${params.center.easting.toFixed(0)} N ${params.center.northing.toFixed(0)}`
                          : 'Click map to set'}
                      </button>
                      <span className="text-[10px] text-gray-400">
                        {params.center ? ' Set' : 'Default: centroid'}
                      </span>
                    </div>
                  </div>
                </div>
              )}

              {/* Area params */}
              {method === 'area' && (
                <div className="space-y-3">
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="target-area-ha">Target Area (ha)</label>
                    <input id="target-area-ha" aria-label="Target Area (ha)"
                      type="number"
                      min={0.001}
                      step={0.01}
                      value={params.targetArea ?? (parentArea / 2).toFixed(4)}
                      onChange={(e) => updateParams({ targetArea: Math.max(0.001, parseFloat(e.target.value) || 0.001) })}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none font-mono"
                    />
                    <div className="text-[10px] text-gray-400 mt-1">
                      Parent: {formatAreaHa(parentArea)} → ~{Math.max(1, Math.floor(parentArea / (params.targetArea ?? parentArea / 2)))} lots
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] text-gray-500 block mb-1" htmlFor="preferred-cut-bearing">Preferred Cut Bearing (°)</label>
                    <input id="preferred-cut-bearing"
                      type="number"
                      min={0}
                      max={360}
                      step={1}
                      aria-label="Preferred Cut Bearing (°)" placeholder="Auto (perpendicular)"
                      value={params.preferredBearing ?? ''}
                      onChange={(e) => {
                        const v = parseFloat(e.target.value)
                        updateParams({ preferredBearing: isNaN(v) ? undefined : v })
                      }}
                      className="w-full px-2.5 py-1.5 text-sm border border-gray-300 rounded-md focus:ring-1 focus:ring-[#1B3A5C] focus:border-[#1B3A5C] outline-none font-mono"
                    />
                    <div className="text-[10px] text-gray-400 mt-1">
                      WCB: 0°=N, 90°=E, 180°=S, 270°=W. Leave empty for auto.
                    </div>
                  </div>
                </div>
              )}

              {/* Split line params */}
              {method === 'single-split' && (
                <div className="space-y-2">
                  {!splitLine && !isDrawingSplitLine && (
                    <div className="flex items-start gap-2 p-2.5 bg-blue-50 border border-blue-200 rounded-md">
                      <Info className="w-4 h-4 text-blue-600 mt-0.5 flex-shrink-0" />
                      <div>
                        <p className="text-xs text-blue-800">
                          Click the button below, then click two points on the map to define the split line.
                        </p>
                      </div>
                    </div>
                  )}
                  {isDrawingSplitLine && (
                    <div className="flex items-center gap-2 p-2.5 bg-amber-50 border border-amber-200 rounded-md">
                      <MapPin className="w-4 h-4 text-amber-600" />
                      <span className="text-xs text-amber-800 font-medium">
                        Click on the map to set the first point of the split line
                      </span>
                    </div>
                  )}
                  {splitLine && (
                    <div className="p-2.5 bg-green-50 border border-green-200 rounded-md">
                      <div className="text-xs text-green-800 font-medium mb-1"> Split line defined</div>
                      <div className="text-[10px] text-green-700 font-mono">
                        ({splitLine.startPoint.easting.toFixed(1)}, {splitLine.startPoint.northing.toFixed(1)}) →
                        ({splitLine.endPoint.easting.toFixed(1)}, {splitLine.endPoint.northing.toFixed(1)})
                      </div>
                    </div>
                  )}
                  {!splitLine && (
                    <button
                      onClick={startSplitLineDrawing}
                      className="flex items-center gap-1.5 px-3 py-1.5 text-xs bg-white border border-gray-300 rounded-md hover:bg-gray-50 transition-colors"
                    >
                      <Scissors className="w-3.5 h-3.5 text-[#1B3A5C]" />
                      Draw Split Line on Map
                    </button>
                  )}
                </div>
              )}
            </div>
          )}

          {/* ─── Error Display ────────────────────────────────────────── */}
          {error && (
            <div className="mx-3 mt-2 p-2.5 bg-red-50 border border-red-200 rounded-md flex items-start gap-2">
              <AlertCircle className="w-4 h-4 text-red-600 mt-0.5 flex-shrink-0" />
              <span className="text-xs text-red-800">{error}</span>
            </div>
          )}

          {/* ─── Action Buttons ───────────────────────────────────────── */}
          {method && (
            <div className="px-3 py-3 flex items-center gap-2">
              <button
                onClick={execute}
                disabled={isComputing || (method === 'single-split' && !splitLine)}
                className="flex items-center gap-1.5 px-4 py-2 bg-[#1B3A5C] text-white text-xs font-semibold rounded-md hover:bg-[#142d49] disabled:opacity-50 disabled:cursor-not-allowed transition-colors shadow-sm"
              >
                {isComputing ? (
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                ) : (
                  <Play className="w-3.5 h-3.5" />
                )}
                {isComputing ? 'Computing...' : 'Subdivide'}
              </button>

              <button
                onClick={clear}
                className="flex items-center gap-1.5 px-3 py-2 text-xs text-gray-600 bg-gray-100 rounded-md hover:bg-gray-200 transition-colors"
              >
                <Trash2 className="w-3.5 h-3.5" />
                Clear
              </button>

              {result && result.lots.length > 0 && (
                <div className="flex items-center gap-2 ml-auto no-print print-hide">
                  <button
                    onClick={() => print({ title: 'Subdivision Report', subtitle: `Project: ${projectName} · ${result.lots.length} lots` })}
                    className="flex items-center gap-1.5 px-3 py-2 text-xs text-[#1B3A5C] bg-gray-50 border border-gray-200 rounded-md hover:bg-gray-100 transition-colors"
                  >
                    <Printer className="w-3.5 h-3.5" />
                    Print
                  </button>
                  <button
                    onClick={exportDXF}
                    className="flex items-center gap-1.5 px-3 py-2 text-xs text-[#1B3A5C] bg-blue-50 border border-blue-200 rounded-md hover:bg-blue-100 transition-colors"
                  >
                    <Download className="w-3.5 h-3.5" />
                    Export DXF
                  </button>
                </div>
              )}
            </div>
          )}

          {/* ─── Results Table ────────────────────────────────────────── */}
          {result && result.lots.length > 0 && (
            <div className="px-3 pb-3">
              {/* Road reserve summary in results */}
              {result.roadReserve && (
                <div className="mb-2 p-2 bg-amber-50 border border-amber-200 rounded-md">
                  <div className="text-[11px] text-amber-800 font-medium">
                    <Road className="w-3.5 h-3.5 inline mr-1" />
                    Road Reserve: {formatAreaHa(result.roadReserve.areaHa)}
                  </div>
                  <div className="text-[10px] text-amber-700">
                    {result.roadReserve.width}m width · Edge{result.roadReserve.clippedEdges.length !== 1 ? 's' : ''} {result.roadReserve.clippedEdges.join(', ')}
                  </div>
                </div>
              )}

              <div className="flex items-center justify-between mb-2">
                <label className="text-[10px] text-gray-500 uppercase tracking-wider font-medium">
                  Results — {result.lots.length} Lot{result.lots.length !== 1 ? 's' : ''}
                </label>
                <div className="text-[10px] text-gray-400">
                  Total: {formatAreaHa(result.totalAreaHa)}
                  {result.remainderAreaHa > 0.0001 && (
                    <span className="text-amber-600 ml-1">
                      (Remainder: {formatAreaHa(result.remainderAreaHa)})
                    </span>
                  )}
                </div>
              </div>

              <div className="border border-gray-200 rounded-md overflow-hidden max-h-64 overflow-y-auto">
                <table className="w-full text-xs">
                  <thead className="bg-gray-50 sticky top-0">
                    <tr className="border-b border-gray-200">
                      <th className="text-left py-1.5 px-2.5 text-[10px] text-gray-500 font-medium">Lot</th>
                      <th className="text-right py-1.5 px-2.5 text-[10px] text-gray-500 font-medium">Area (ha)</th>
                      <th className="text-right py-1.5 px-2.5 text-[10px] text-gray-500 font-medium">Perimeter</th>
                      <th className="text-left py-1.5 px-2.5 text-[10px] text-gray-500 font-medium">Centroid</th>
                    </tr>
                  </thead>
                  <tbody>
                    {result.lots.map((lot) => (
                      <LotRow key={lot.lotNumber} lot={lot} />
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* ─── Empty state ──────────────────────────────────────────── */}
          {!method && (
            <div className="px-3 py-6 text-center">
              <div className="text-gray-300 mb-2">
                <Grid3X3 className="w-8 h-8 mx-auto" />
              </div>
              <p className="text-xs text-gray-400">
                Select a subdivision method above to begin
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

/** Individual lot row in the results table. */
function LotRow({ lot }: { lot: SubdividedLot }) {
  return (
    <tr className="border-b border-gray-100 hover:bg-gray-50 transition-colors">
      <td className="py-1.5 px-2.5">
        <span className="inline-flex items-center justify-center w-6 h-6 rounded bg-[#1B3A5C] text-white text-[10px] font-bold">
          {lot.lotNumber}
        </span>
      </td>
      <td className="py-1.5 px-2.5 text-right font-mono font-medium">
        {lot.areaHa.toFixed(4)}
        {lot.areaError !== undefined && Math.abs(lot.areaError) > 0.001 && (
          <span className={`ml-1 text-[9px] ${Math.abs(lot.areaError) < 0.05 ? 'text-green-600' : 'text-amber-600'}`}>
            ({lot.areaError >= 0 ? '+' : ''}{lot.areaError.toFixed(4)})
          </span>
        )}
      </td>
      <td className="py-1.5 px-2.5 text-right font-mono text-gray-600">
        {formatPerimeter(lot.perimeter)}
      </td>
      <td className="py-1.5 px-2.5 font-mono text-gray-500 text-[10px]">
        E {lot.centroid.easting.toFixed(0)} N {lot.centroid.northing.toFixed(0)}
      </td>
    </tr>
  )
}

'use client';

import { useState } from 'react';
import { SubmissionDocument, DocumentStatus, ProjectDocument } from '@/types/submission';

interface Props {
  doc: SubmissionDocument;
  projectId: string;
  existing: ProjectDocument | null;
  onStatusChange: (documentId: string, status: DocumentStatus, fileUrl?: string) => void;
}

const STATUS_CONFIG: Record<DocumentStatus, { label: string; color: string }> = {
  missing: { label: 'Missing', color: 'text-gray-500' },
  pending: { label: 'Not generated', color: 'text-gray-400' },
  generating: { label: 'Generating…', color: 'text-blue-500' },
  ready: { label: 'Ready', color: 'text-green-600' },
  error: { label: 'Failed', color: 'text-red-500' },
};

const FORMAT_BADGE: Record<string, string> = {
  pdf:     'bg-red-100 text-red-700',
  xlsx:    'bg-green-100 text-green-700',
  zip:     'bg-purple-100 text-purple-700',
  dxf:     'bg-yellow-100 text-yellow-700',
  shp:     'bg-blue-100 text-blue-700',
  geojson: 'bg-teal-100 text-teal-700',
};

export default function DocumentCard({ doc, projectId, existing, onStatusChange }: Props) {
  const [loading, setLoading] = useState(false);
  const [localError, setLocalError] = useState<string | null>(null);

  const status: DocumentStatus = existing?.status ?? 'pending';
  const fileUrl = existing?.file_url ?? null;
  const statusConfig = STATUS_CONFIG[status];

  const handleGenerate = async () => {
    setLoading(true);
    setLocalError(null);
    onStatusChange(doc.id, 'generating');

    try {
      const res = await fetch('/api/submission/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ projectId, documentId: doc.id }),
      });

      const data = await res.json();

      if (!res.ok || data.error) {
        throw new Error(data.error ?? 'Generation failed');
      }

      onStatusChange(doc.id, 'ready', data.fileUrl);
    } catch (err: unknown) {
      const message = err instanceof Error ? (err as Error).message : 'Unknown error';
      setLocalError(message);
      onStatusChange(doc.id, 'error');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="rounded-lg border border-gray-200 bg-white p-4 flex flex-col gap-3">
      <div className="flex items-start justify-between gap-2">
        <div>
          <h3 className="font-semibold text-gray-800 text-sm">{doc.label}</h3>
          <p className="text-xs text-gray-500 mt-0.5">{doc.description}</p>
        </div>
        <span className={`text-xs px-2 py-0.5 rounded font-medium whitespace-nowrap ${FORMAT_BADGE[doc.format] ?? 'bg-gray-100 text-gray-600'}`}>
          {doc.format.toUpperCase()}
        </span>
      </div>

      <ul className="text-xs text-gray-400 list-disc list-inside space-y-0.5">
        {doc.requiredData.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>

      <p className={`text-xs font-medium ${statusConfig.color}`}>
        {statusConfig.label}
        {existing?.generated_at && status === 'ready' && (
          <span className="text-gray-400 font-normal ml-1">
            — {new Date(existing.generated_at).toLocaleTimeString()}
          </span>
        )}
      </p>

{(localError || (status === 'error' && existing?.errorMessage)) && (
    <p className="text-xs text-red-500 bg-red-50 rounded p-2 leading-relaxed">
      {localError ?? existing?.errorMessage}
    </p>
      )}

      <div className="flex gap-2 mt-auto">
        <button
          onClick={handleGenerate}
          disabled={loading || status === 'generating'}
          className="flex-1 px-3 py-1.5 text-xs bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50 transition-colors"
        >
          {status === 'ready' ? 'Regenerate' : 'Generate'}
        </button>

        {status === 'ready' && fileUrl && (
          <a
            href={fileUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 px-3 py-1.5 text-xs bg-green-600 text-white rounded hover:bg-green-700 text-center transition-colors"
          >
            Download
          </a>
        )}
      </div>
    </div>
  );
}

'use client'

/**
 * NLIMSExportPanel — UI for generating NLIMS/ArdhiSasa submission payloads
 *
 * Allows the surveyor to:
 * 1. Select submission type (mutation, subdivision, etc.)
 * 2. Enter surveyor info (auto-filled from profile if available)
 * 3. Select parcels to export
 * 4. Run validation
 * 5. Download the NLIMS JSON payload
 *
 * Uses the existing /api/export/nlims endpoint and lib/export/nlimsExporter.
 */

import { useState, useCallback } from 'react'
import {
  FileOutput, Download, Loader2, CheckCircle2, AlertCircle,
  Building2, MapPin, ShieldCheck,
} from 'lucide-react'
import { downloadNLIMSPayload, type NLIMSSubmissionPayload, type NLIMSValidationResult } from '@/lib/export/nlimsExporter'

interface NLIMSExportPanelProps {
  projectId: string
}

export function NLIMSExportPanel({ projectId }: NLIMSExportPanelProps) {
  const [expanded, setExpanded] = useState(false)
  const [generating, setGenerating] = useState(false)
  const [payload, setPayload] = useState<NLIMSSubmissionPayload | null>(null)
  const [validation, setValidation] = useState<NLIMSValidationResult | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Form fields
  const [submissionType, setSubmissionType] = useState<'mutation' | 'subdivision' | 'amalgamation' | 'new_registration' | 'boundary_adjustment'>('subdivision')
  const [registry, setRegistry] = useState('Nairobi')
  const [county, setCounty] = useState('Nairobi')
  const [subCounty, setSubCounty] = useState('')
  const [surveyorName, setSurveyorName] = useState('')
  const [licenseNumber, setLicenseNumber] = useState('')
  const [firm, setFirm] = useState('')

  const handleGenerate = useCallback(async () => {
    setGenerating(true)
    setError(null)
    setPayload(null)
    setValidation(null)

    try {
      const res = await fetch('/api/export/nlims', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          submissionType,
          registry,
          county,
          subCounty,
          surveyor: {
            name: surveyorName,
            licenseNumber,
            firm: firm || undefined,
          },
          resultingParcels: [], // Will be populated from project data
          beacons: [],
          // Parent parcel info would come from the project's existing parcel data
        }),
      })

      const data = await res.json()

      if (!res.ok) {
        if (data.validation) {
          setValidation(data.validation)
          setError('Validation failed — fix the errors below')
        } else {
          setError(data.error || 'Failed to generate NLIMS payload')
        }
        return
      }

      setPayload(data.payload)
      setValidation(data.validation)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Network error')
    } finally {
      setGenerating(false)
    }
  }, [submissionType, registry, county, subCounty, surveyorName, licenseNumber, firm])

  const handleDownload = useCallback(() => {
    if (!payload) return
    downloadNLIMSPayload(payload)
  }, [payload])

  return (
    <div className="mt-6 rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-[var(--bg-tertiary)]/50 transition-colors"
      >
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-blue-500/10 flex items-center justify-center">
            <Building2 className="w-4 h-4 text-blue-400" />
          </div>
          <div className="text-left">
            <span className="text-sm font-semibold text-[var(--text-primary)]">NLIMS / ArdhiSasa Export</span>
            <p className="text-[10px] text-gray-500">Generate registry-ready JSON submission</p>
          </div>
        </div>
        <svg className={`w-4 h-4 text-gray-500 transition-transform ${expanded ? 'rotate-180' : ''}`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <path d="M6 9l6 6 6-6" />
        </svg>
      </button>

      {expanded && (
        <div className="border-t border-[var(--border-color)] p-4 space-y-4">
          {/* Submission type */}
          <div>
            <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="submission-type">Submission Type</label>
            <select id="submission-type"
              value={submissionType}
              onChange={e => setSubmissionType(e.target.value as typeof submissionType)}
              className="input h-10 text-sm"
            >
              <option value="subdivision">Subdivision</option>
              <option value="mutation">Mutation</option>
              <option value="amalgamation">Amalgamation</option>
              <option value="new_registration">New Registration</option>
              <option value="boundary_adjustment">Boundary Adjustment</option>
            </select>
          </div>

          {/* Registry info */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="registry">Registry</label>
              <input id="registry"
                type="text"
                value={registry}
                onChange={e => setRegistry(e.target.value)}
                className="input h-10 text-sm"
                aria-label="Nairobi" placeholder="Nairobi"
              />
            </div>
            <div>
              <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="county">County</label>
              <input id="county"
                type="text"
                value={county}
                onChange={e => setCounty(e.target.value)}
                className="input h-10 text-sm"
                aria-label="Nairobi" placeholder="Nairobi"
              />
            </div>
          </div>

          <div>
            <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="sub-county">Sub-County</label>
            <input id="sub-county"
              type="text"
              value={subCounty}
              onChange={e => setSubCounty(e.target.value)}
              className="input h-10 text-sm"
              aria-label="Westlands" placeholder="Westlands"
            />
          </div>

          {/* Surveyor info */}
          <div className="pt-2 border-t border-[var(--border-color)]">
            <div className="flex items-center gap-1.5 mb-2">
              <ShieldCheck className="w-3.5 h-3.5 text-[var(--accent)]" />
              <span className="text-[10px] text-gray-500 uppercase tracking-wider font-semibold">Surveyor Information</span>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="name">Name</label>
                <input id="name"
                  type="text"
                  value={surveyorName}
                  onChange={e => setSurveyorName(e.target.value)}
                  className="input h-10 text-sm"
                  aria-label="John Doe" placeholder="John Doe"
                />
              </div>
              <div>
                <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="license-no">License No.</label>
                <input id="license-no"
                  type="text"
                  value={licenseNumber}
                  onChange={e => setLicenseNumber(e.target.value)}
                  className="input h-10 text-sm font-mono"
                  aria-label="ISK/LS/2021/0452" placeholder="ISK/LS/2021/0452"
                />
              </div>
            </div>
            <div className="mt-2">
              <label className="block text-[10px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="firm-optional">Firm (optional)</label>
              <input
                type="text"
                value={firm}
                onChange={e => setFirm(e.target.value)}
                className="input h-10 text-sm"
                aria-label="Doe Surveyors Ltd" placeholder="Doe Surveyors Ltd"
              />
            </div>
          </div>

          {/* Generate button */}
          <button
            onClick={handleGenerate}
            disabled={generating || !surveyorName || !licenseNumber}
            className="w-full flex items-center justify-center gap-2 h-10 rounded-lg bg-blue-500 hover:bg-blue-600 text-white text-sm font-semibold transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
          >
            {generating ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileOutput className="w-4 h-4" />}
            {generating ? 'Generating...' : 'Generate NLIMS Payload'}
          </button>

          {/* Validation errors */}
          {validation && !validation.isValid && (
            <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20">
              <div className="flex items-center gap-1.5 mb-1.5">
                <AlertCircle className="w-3.5 h-3.5 text-red-400" />
                <span className="text-xs font-medium text-red-400">Validation Errors</span>
              </div>
              <ul className="text-[11px] text-red-400/80 space-y-0.5 list-disc list-inside">
                {validation.errors.map((e, i) => (
                  <li key={`${e}-${i}`}>{e.message}</li>
                ))}
              </ul>
              {validation.warnings.length > 0 && (
                <div className="mt-2 pt-2 border-t border-red-500/10">
                  <span className="text-[10px] text-amber-400 font-medium">Warnings:</span>
                  <ul className="text-[10px] text-amber-400/70 space-y-0.5 list-disc list-inside mt-0.5">
                    {validation.warnings.map((w, i) => (
                      <li key={`${w}-${i}`}>{w.message}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}

          {/* Success + download */}
          {payload && (
            <div className="p-3 rounded-lg bg-emerald-500/5 border border-emerald-500/20">
              <div className="flex items-center gap-2 mb-2">
                <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                <span className="text-sm font-medium text-emerald-400">Payload Generated</span>
              </div>
              <div className="text-[11px] text-gray-400 space-y-0.5 mb-3">
                <div>Submission ID: <span className="font-mono">{payload.submissionId}</span></div>
                <div>Parcels: {payload.resultingParcels.length}</div>
                <div>Beacons: {payload.beacons.length}</div>
                <div>Integrity: <span className="font-mono">{payload.integrity.hash.substring(0, 16)}...</span></div>
                {payload.areaReconciliation.parentAreaHectares != null && (
                  <div className={payload.areaReconciliation.isWithinTolerance ? 'text-emerald-400' : 'text-red-400'}>
                    Area check: {payload.areaReconciliation.sumOfPartsHectares.toFixed(4)} ha vs parent {payload.areaReconciliation.parentAreaHectares.toFixed(4)} ha
                    ({payload.areaReconciliation.isWithinTolerance ? 'OK' : 'MISMATCH'})
                  </div>
                )}
              </div>
              <button
                onClick={handleDownload}
                className="w-full flex items-center justify-center gap-2 h-9 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-semibold transition-colors"
              >
                <Download className="w-3.5 h-3.5" />
                Download NLIMS JSON
              </button>
            </div>
          )}

          {/* Error */}
          {error && !validation && (
            <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 flex items-start gap-2">
              <AlertCircle className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
              <p className="text-xs text-red-400">{error}</p>
            </div>
          )}

          {/* Info note */}
          <div className="flex items-start gap-2 p-2.5 rounded-lg bg-blue-500/5 border border-blue-500/10">
            <MapPin className="w-3.5 h-3.5 text-blue-400 shrink-0 mt-0.5" />
            <p className="text-[10px] text-blue-400/70 leading-relaxed">
              NLIMS payloads use Arc 1960 / UTM Zone 37S coordinates (EPSG:21037) with 3 decimal places.
              Area reconciliation tolerance: ±0.001 ha (10 m²). SHA-256 integrity hash ensures tamper detection.
            </p>
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/api-client/client'

interface Doc {
  id: string
  type: string
  label: string
  required: boolean
  file_url: string | null
}

export function SupportingDocUpload({ projectId }: { projectId: string }) {
  const [docs, setDocs] = useState<Doc[]>([])
  const [uploading, setUploading] = useState<string | null>(null)
  const dbClient = createClient()

  useEffect(() => {
    loadDocs()
  }, [projectId])

  async function loadDocs() {
    const { data } = await dbClient
      .from('supporting_documents')
      .select('*')
      .eq('project_id', projectId)
    setDocs(data ?? [])
  }

  async function handleUpload(docId: string, docType: string, file: File) {
    setUploading(docId)
    try {
      const formData = new FormData()
      formData.append('file', file)
      formData.append('bucket', `submission-docs/${projectId}/${docType}`)

      const res = await fetch('/api/storage', {
        method: 'POST',
        body: formData
      })

      if (!res.ok) throw new Error('Upload failed')

      const json = await res.json()
      const fileUrl = json.url

      await dbClient
        .from('supporting_documents')
        .update({
          file_url: fileUrl,
          uploaded_at: new Date().toISOString()
        })
        .eq('id', docId)

      await loadDocs()
    } catch (err) {
      console.error('Upload failed:', err)
    } finally {
      setUploading(null)
    }
  }

  return (
    <div className="space-y-4">
      <h3 className="font-semibold text-lg">Supporting Documents</h3>
      {docs.map(doc => (
        <div
          key={doc.id}
          className="flex items-center justify-between border rounded-lg p-4"
        >
          <div>
            <p className="font-medium text-sm">{doc.label}</p>
            <p className="text-xs text-muted-foreground">
              {doc.required ? 'Required' : 'Optional'}
              {doc.file_url && (
                <span className="ml-2 text-green-400"> Uploaded</span>
              )}
            </p>
          </div>
          <label className="cursor-pointer">
            <span className="text-sm bg-secondary px-3 py-1.5 rounded border">
              {uploading === doc.id ? 'Uploading...' : doc.file_url ? 'Replace' : 'Upload PDF'}
            </span>
            <input
              type="file"
              accept=".pdf"
              className="hidden"
              disabled={uploading === doc.id}
              onChange={e => {
                const file = e.target.files?.[0]
                if (file) handleUpload(doc.id, doc.type, file)
              }}
            />
          </label>
        </div>
      ))}
    </div>
  )
}

'use client'

/**
 * BowditchApplyButton — One-tap traverse misclosure distribution
 *
 * The Bowditch (Compass) adjustment engine already exists in
 * src/lib/engine/traverse.ts (bowditchAdjustment function).
 *
 * This component provides the UX: a single button that:
 * 1. Reads the current traverse data from the fieldbook
 * 2. Calls the Bowditch adjustment engine
 * 3. Shows the closure statistics (linear error, precision ratio)
 * 4. Applies the corrections to the coordinates
 * 5. Shows a before/after comparison
 *
 * Survey Act Cap 299 requires:
 * - Urban surveys: precision ≥ 1:10,000
 * - Rural surveys: precision ≥ 1:5,000
 * - Topographic: precision ≥ 1:1,000
 */

import { useState, useCallback } from 'react'
import {
  Calculator, Check, AlertTriangle, Loader2,
  TrendingDown, ArrowRight, X,
} from 'lucide-react'
import { bowditchAdjustment, type TraverseInput } from '@/lib/engine/traverse'
import type { TraverseResult } from '@/lib/engine/types'

interface BowditchApplyButtonProps {
  /** Traverse input data (stations, bearings, distances) */
  traverseInput: TraverseInput
  /** Called when the adjustment is applied — receives adjusted coordinates */
  onApply: (result: TraverseResult) => void
  /** Survey type for precision threshold */
  surveyCategory?: 'urban' | 'rural' | 'topographic'
  /** Compact mode — just the button */
  compact?: boolean
}

const PRECISION_THRESHOLDS = {
  urban: { ratio: 10000, label: '1:10,000 (Urban)' },
  rural: { ratio: 5000, label: '1:5,000 (Rural)' },
  topographic: { ratio: 1000, label: '1:1,000 (Topographic)' },
}

export function BowditchApplyButton({
  traverseInput,
  onApply,
  surveyCategory = 'urban',
  compact = false,
}: BowditchApplyButtonProps) {
  const [result, setResult] = useState<TraverseResult | null>(null)
  const [computing, setComputing] = useState(false)
  const [showDetails, setShowDetails] = useState(false)
  const [applied, setApplied] = useState(false)

  const threshold = PRECISION_THRESHOLDS[surveyCategory]

  const handleCompute = useCallback(() => {
    setComputing(true)
    try {
      const adjResult = bowditchAdjustment(traverseInput)
      setResult(adjResult)
      setShowDetails(true)
    } catch (err) {
      console.error('[BowditchApplyButton] Adjustment failed:', err)
      alert(`Adjustment failed: ${err instanceof Error ? err.message : 'Unknown error'}`)
    } finally {
      setComputing(false)
    }
  }, [traverseInput])

  const handleApply = useCallback(() => {
    if (!result) return
    onApply(result)
    setApplied(true)
    setTimeout(() => {
      setShowDetails(false)
      setApplied(false)
    }, 2000)
  }, [result, onApply])

  // Determine if precision is acceptable
  // TraverseResult has precisionRatio (e.g., 10000 for 1:10000) and precisionGrade
  const precisionRatio = result?.precisionRatio ?? null
  const isAcceptable = precisionRatio != null && precisionRatio >= threshold.ratio

  if (compact) {
    return (
      <button
        onClick={handleCompute}
        disabled={computing}
        className="flex items-center gap-1.5 px-3 h-9 rounded-lg bg-[#D17B47]/10 border border-[#D17B47]/30 text-[#D17B47] text-xs font-medium hover:bg-[#D17B47]/20 transition-colors disabled:opacity-50"
        title="Apply Bowditch adjustment to distribute misclosure"
      >
        {computing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Calculator className="w-3.5 h-3.5" />}
        Bowditch
      </button>
    )
  }

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-3">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <Calculator className="w-4 h-4 text-[var(--accent)]" />
          <span className="text-sm font-medium text-[var(--text-primary)]">Bowditch Adjustment</span>
        </div>
        <button
          onClick={handleCompute}
          disabled={computing}
          className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)] text-black text-xs font-semibold hover:bg-[var(--accent-dim)] transition-colors disabled:opacity-50"
        >
          {computing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Calculator className="w-3.5 h-3.5" />}
          Compute
        </button>
      </div>

      <div className="text-[10px] text-gray-500 mb-2">
        Threshold: {threshold.label} per Survey Act Cap 299
      </div>

      {/* Results */}
      {result && showDetails && (
        <div className="space-y-2 animate-in fade-in duration-200">
          {/* Precision indicator */}
          <div className={`p-2.5 rounded-lg border ${
            isAcceptable
              ? 'bg-emerald-500/10 border-emerald-500/30'
              : 'bg-red-500/10 border-red-500/30'
          }`}>
            <div className="flex items-center gap-2">
              {isAcceptable ? (
                <Check className="w-4 h-4 text-emerald-400 shrink-0" />
              ) : (
                <AlertTriangle className="w-4 h-4 text-red-400 shrink-0" />
              )}
              <div className="flex-1">
                <div className={`text-sm font-semibold ${isAcceptable ? 'text-emerald-400' : 'text-red-400'}`}>
                  Precision: 1:{precisionRatio?.toLocaleString()}
                </div>
                <div className="text-[10px] text-gray-500">
                  {isAcceptable
                    ? 'Within statutory tolerance — safe to apply'
                    : `Below ${threshold.label} — check observations for errors`}
                </div>
              </div>
            </div>
          </div>

          {/* Closure statistics */}
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50">
              <span className="text-[9px] text-gray-500 uppercase tracking-wider">Linear Error</span>
              <div className="font-mono text-gray-300 mt-0.5">
                {result?.linearError != null ? `${result.linearError.toFixed(4)} m` : '—'}
              </div>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50">
              <span className="text-[9px] text-gray-500 uppercase tracking-wider">Total Distance</span>
              <div className="font-mono text-gray-300 mt-0.5">
                {result?.totalDistance != null ? `${result.totalDistance.toFixed(3)} m` : '—'}
              </div>
            </div>
          </div>

          {/* Action buttons */}
          <div className="flex gap-2 pt-1">
            <button
              onClick={() => setShowDetails(false)}
              className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-xs text-gray-400 hover:text-gray-200 transition-colors"
            >
              <X className="w-3.5 h-3.5" /> Cancel
            </button>
            <button
              onClick={handleApply}
              disabled={!isAcceptable || applied}
              className={`flex-1 flex items-center justify-center gap-1.5 px-3 h-8 rounded-lg text-xs font-semibold transition-colors ${
                applied
                  ? 'bg-emerald-500 text-white'
                  : isAcceptable
                    ? 'bg-[var(--accent)] text-black hover:bg-[var(--accent-dim)]'
                    : 'bg-gray-500/20 text-gray-500 cursor-not-allowed'
              }`}
            >
              {applied ? (
                <><Check className="w-3.5 h-3.5" /> Applied</>
              ) : (
                <>Apply Adjustment <ArrowRight className="w-3.5 h-3.5" /></>
              )}
            </button>
          </div>

          {!isAcceptable && (
            <div className="flex items-start gap-1.5 p-2 rounded-lg bg-red-500/5 border border-red-500/20">
              <TrendingDown className="w-3 h-3 text-red-400 shrink-0 mt-0.5" />
              <p className="text-[10px] text-red-400/80">
                Precision is below the statutory threshold. Applying this adjustment
                may result in registry rejection. Verify your observations first.
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * ControlPointRegistry — SoK Control Point Index & Network Search
 *
 * Features:
 * - Search by coordinate + radius to find nearest control points
 * - Shows trig stations, KENCORS stations, and benchmarks
 * - Calculates bearing and distance to each point (for traverse planning)
 * - Filter by type (Trig, CORS, Benchmark)
 * - Click to highlight on map
 *
 * Uses existing:
 * - src/lib/map/kencors.ts (KENCORS_STATIONS + nearestKenCORSStations)
 * - src/lib/online/benchmarks.ts (benchmark database)
 */

import { useState, useCallback, useMemo } from 'react'
import {
  Radio, MapPin, Search, Loader2, Navigation,
  Triangle, Building2, ChevronRight,
} from 'lucide-react'

export interface ControlPoint {
  id: string
  name: string
  type: 'trig' | 'cors' | 'benchmark'
  easting: number
  northing: number
  county?: string
  elevation?: number | null
  distanceM?: number
  bearingDeg?: number
  status?: 'active' | 'inactive'
}

type PointType = 'all' | 'trig' | 'cors' | 'benchmark'

const TYPE_CONFIG: Record<string, { label: string; icon: typeof Radio; color: string; bg: string }> = {
  trig: { label: 'Trig Station', icon: Triangle, color: 'text-red-400', bg: 'bg-red-500/10' },
  cors: { label: 'CORS Station', icon: Radio, color: 'text-blue-400', bg: 'bg-blue-500/10' },
  benchmark: { label: 'Benchmark', icon: Building2, color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
}

/**
 * Calculate bearing from origin to destination (in degrees, 0-360).
 */
function calculateBearing(fromE: number, fromN: number, toE: number, toN: number): number {
  const dE = toE - fromE
  const dN = toN - fromN
  let bearing = Math.atan2(dE, dN) * 180 / Math.PI
  if (bearing < 0) bearing += 360
  return bearing
}

/**
 * Format bearing as DMS (e.g., "45°30'15\"").
 */
function formatBearingDMS(bearing: number): string {
  const deg = Math.floor(bearing)
  const minFull = (bearing - deg) * 60
  const min = Math.floor(minFull)
  const sec = (minFull - min) * 60
  return `${deg}°${min}'${sec.toFixed(0)}"`
}

export function ControlPointRegistry() {
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [radius, setRadius] = useState('10000') // 10km default
  const [typeFilter, setTypeFilter] = useState<PointType>('all')
  const [results, setResults] = useState<ControlPoint[]>([])
  const [loading, setLoading] = useState(false)
  const [searched, setSearched] = useState(false)

  const search = useCallback(async () => {
    const e = parseFloat(easting)
    const n = parseFloat(northing)
    if (!isFinite(e) || !isFinite(n)) {
      alert('Enter valid easting and northing')
      return
    }

    setLoading(true)
    setSearched(true)
    try {
      // 1. Search KENCORS stations (existing module)
      const { KENCORS_STATIONS, nearestKenCORSStations } = await import('@/lib/map/kencors')
      const corsResults: ControlPoint[] = nearestKenCORSStations(e, n, 10).map(s => ({
        id: s.id,
        name: s.name,
        type: 'cors' as const,
        easting: s.easting,
        northing: s.northing,
        county: s.county,
        distanceM: s.distanceKm * 1000,
        bearingDeg: calculateBearing(e, n, s.easting, s.northing),
        status: s.status,
      }))

      // 2. Search benchmarks (existing module)
      let benchmarkResults: ControlPoint[] = []
      try {
        const { searchBenchmarks } = await import('@/lib/online/benchmarks')
        const benchmarks = await searchBenchmarks({
          latitude: 0, // Benchmarks use lat/lng — would need coordinate transform
          longitude: 0,
          radiusKm: parseFloat(radius) / 1000,
          type: 'ALL',
        })
        benchmarkResults = (benchmarks.benchmarks || []).slice(0, 10).map(b => ({
          id: b.id,
          name: b.name,
          type: 'benchmark' as const,
          easting: b.easting || 0,
          northing: b.northing || 0,
          county: b.region,
          elevation: b.elevation,
          distanceM: 0, // Would calculate if coords available
          status: 'active' as const,
        }))
      } catch {}

      // 3. Combine and filter
      let combined = [...corsResults, ...benchmarkResults]
      if (typeFilter !== 'all') {
        combined = combined.filter(p => p.type === typeFilter)
      }

      // Sort by distance
      combined.sort((a, b) => (a.distanceM || 0) - (b.distanceM || 0))

      // Limit to radius
      const radiusM = parseFloat(radius)
      combined = combined.filter(p => (p.distanceM || 0) <= radiusM)

      setResults(combined)
    } catch (err) {
      console.error('[ControlPointRegistry] Search failed:', err)
      setResults([])
    } finally {
      setLoading(false)
    }
  }, [easting, northing, radius, typeFilter])

  // Auto-search with default Nairobi coordinates
  const useDefaultLocation = useCallback(() => {
    setEasting('261518')
    setNorthing('9859340')
  }, [])

  return (
    <div className="space-y-4">
      {/* Search panel */}
      <div className="card p-4 space-y-3">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <Radio className="w-4 h-4 text-[var(--accent)]" />
          </div>
          <div>
            <h2 className="text-sm font-semibold text-[var(--text-primary)]">Control Point Registry</h2>
            <p className="text-[10px] text-gray-500">Find nearest Trig stations, KENCORS, and benchmarks</p>
          </div>
        </div>

        <div className="grid grid-cols-3 gap-2">
          <div>
            <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="easting-m">Easting (m)</label>
            <input id="easting-m" type="number" value={easting} onChange={e => setEasting(e.target.value)} aria-label="261518" placeholder="261518" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
          </div>
          <div>
            <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="northing-m">Northing (m)</label>
            <input id="northing-m" type="number" value={northing} onChange={e => setNorthing(e.target.value)} aria-label="9859340" placeholder="9859340" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none" />
          </div>
          <div>
            <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="radius-m">Radius (m)</label>
            <input aria-label="Radius (m)" type="number" value={radius} onChange={e => setRadius(e.target.value)} className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono focus:border-[var(--accent)]/30 focus:outline-none" />
          </div>
        </div>

        <div className="flex items-center gap-2">
          <select
            value={typeFilter}
            onChange={e => setTypeFilter(e.target.value as PointType)}
            className="h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)]"
          >
            <option value="all">All Types</option>
            <option value="trig">Trig Stations</option>
            <option value="cors">CORS Stations</option>
            <option value="benchmark">Benchmarks</option>
          </select>
          <button
            onClick={useDefaultLocation}
            className="h-9 px-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-gray-400 hover:text-gray-200"
          >
            Use Nairobi
          </button>
          <button
            onClick={search}
            disabled={loading || !easting || !northing}
            className="flex-1 flex items-center justify-center gap-2 h-9 rounded-lg bg-[var(--accent)] text-black text-xs font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40"
          >
            {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Search className="w-3.5 h-3.5" />}
            Find Control Points
          </button>
        </div>
      </div>

      {/* Results */}
      {searched && (
        <div className="card p-4">
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="w-6 h-6 text-gray-500 animate-spin" />
            </div>
          ) : results.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 text-center">
              <MapPin className="w-8 h-8 text-gray-600 mb-2" />
              <p className="text-sm text-gray-500">No control points found in radius</p>
              <p className="text-[10px] text-gray-600 mt-1">Try increasing the search radius</p>
            </div>
          ) : (
            <>
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-medium text-[var(--text-primary)]">
                  {results.length} control point{results.length !== 1 ? 's' : ''} found
                </span>
                <span className="text-[10px] text-gray-500">
                  Sorted by distance from search location
                </span>
              </div>

              <div className="space-y-2">
                {results.map(point => {
                  const cfg = TYPE_CONFIG[point.type]
                  const Icon = cfg.icon
                  return (
                    <div
                      key={point.id}
                      className="flex items-start gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors group"
                    >
                      <div className={`shrink-0 w-10 h-10 rounded-lg ${cfg.bg} flex items-center justify-center`}>
                        <Icon className={`w-4 h-4 ${cfg.color}`} />
                      </div>

                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-sm font-medium text-[var(--text-primary)]">{point.name}</span>
                          <span className={`text-[9px] px-1.5 py-0.5 rounded ${cfg.bg} ${cfg.color} uppercase`}>
                            {cfg.label}
                          </span>
                          {point.status === 'inactive' && (
                            <span className="text-[9px] px-1.5 py-0.5 rounded bg-gray-500/10 text-gray-400 uppercase">
                              Inactive
                            </span>
                          )}
                        </div>

                        <div className="text-[10px] text-gray-500 font-mono mt-0.5">
                          E: {point.easting.toFixed(3)} | N: {point.northing.toFixed(3)}
                          {point.elevation != null && ` | Elev: ${point.elevation.toFixed(2)}m`}
                        </div>

                        {point.county && (
                          <div className="text-[10px] text-gray-600 mt-0.5">{point.county}</div>
                        )}

                        {point.distanceM != null && point.bearingDeg != null && (
                          <div className="flex items-center gap-3 mt-1.5">
                            <span className="flex items-center gap-1 text-[10px] text-[var(--accent)] font-medium">
                              <Navigation className="w-2.5 h-2.5" />
                              {(point.distanceM / 1000).toFixed(2)} km
                            </span>
                            <span className="text-[10px] text-blue-400 font-mono">
                              Bearing: {formatBearingDMS(point.bearingDeg)}
                            </span>
                          </div>
                        )}
                      </div>

                      <ChevronRight className="w-4 h-4 text-gray-600 opacity-0 group-hover:opacity-100 transition-opacity" />
                    </div>
                  )
                })}
              </div>

              {/* Traverse planning note */}
              <div className="mt-3 flex items-start gap-2 p-2.5 rounded-lg bg-blue-500/5 border border-blue-500/10">
                <Navigation className="w-3 h-3 text-blue-400 shrink-0 mt-0.5" />
                <p className="text-[10px] text-blue-400/70 leading-relaxed">
                  Use these control points as reference stations for your traverse.
                  The bearing and distance help plan baseline vectors before field work.
                  Per Survey Act Cap 299, all cadastral traverses must be tied to the national geodetic network.
                </p>
              </div>
            </>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * CoordinateChip — Live multi-datum coordinate display
 *
 * Shows a captured coordinate in multiple Kenya survey datums simultaneously:
 * - WGS84 (lat/lng) — what GNSS rovers record
 * - Arc 1960 / UTM 37S (EPSG:21037) — what registries use
 * - Cassini-Soldner — what legacy RIMs use
 *
 * This eliminates the need for surveyors to export to desktop software
 * just to verify their field points match reference title coordinates.
 */

import { useEffect, useState } from 'react'
import { Globe, MapPin, Layers } from 'lucide-react'

interface CoordinateChipProps {
  lat: number
  lng: number
  /** Show all datums or just WGS84 + UTM (compact mode) */
  showCassini?: boolean
  /** Label for the coordinate (e.g., "Captured Point", "Beacon 04") */
  label?: string
  /** Accuracy in meters (optional) */
  accuracy?: number
  /** Compact mode — smaller text, single line per datum */
  compact?: boolean
  /** T1.5 FIX (2026-07-09): UTM EPSG for the transform (default 'EPSG:21037') */
  epsg?: string
}

interface DatumDisplay {
  wgs84: { lat: number; lng: number } | null
  utm37s: { easting: number; northing: number } | null
  cassini: { easting: number; northing: number; sheet?: string } | null
}

export function CoordinateChip({
  lat,
  lng,
  showCassini = false,
  label,
  accuracy,
  compact = false,
  epsg = 'EPSG:21037',
}: CoordinateChipProps) {
  const [datums, setDatums] = useState<DatumDisplay>({
    wgs84: { lat, lng },
    utm37s: null,
    cassini: null,
  })

  useEffect(() => {
    let cancelled = false

    async function transform() {
      try {
        // Transform to UTM (Arc 1960 / UTM 37S by default)
        let utm37s: { easting: number; northing: number } | null = null
        try {
          const { transform } = await import('ol/proj')
          const [e, n] = transform([lng, lat], 'EPSG:4326', epsg) as [number, number]
          if (!cancelled && isFinite(e) && isFinite(n)) {
            utm37s = { easting: e, northing: n }
          }
        } catch {}

        // Transform to Cassini-Soldner (if requested)
        // Note: Cassini transform requires knowing the specific sheet origin.
        // The cassini module provides feet-to-UTM transforms, not direct WGS84→Cassini.
        // For now, we skip Cassini display unless a sheet-specific transform is available.
        let cassini: { easting: number; northing: number; sheet?: string } | null = null
        if (showCassini) {
          // TODO: Integrate sheet-specific Cassini transform when available
          // For now, display a note that Cassini requires sheet selection
          cassini = null
        }

        if (!cancelled) {
          setDatums({
            wgs84: { lat, lng },
            utm37s,
            cassini,
          })
        }
      } catch (err) {
        console.warn('[CoordinateChip] Transform failed:', err)
      }
    }

    transform()
    return () => { cancelled = true }
  }, [lat, lng, showCassini])

  const fmt = (n: number, decimals: number) => n.toFixed(decimals)

  return (
    <div className={`rounded-lg border border-white/[0.06] bg-[#0d0d14]/60 backdrop-blur-sm ${compact ? 'p-2' : 'p-3'} space-y-1.5`}>
      {label && (
        <div className="flex items-center justify-between mb-1">
          <span className="text-[10px] text-gray-500 uppercase tracking-wider font-semibold">{label}</span>
          {accuracy != null && (
            <span className={`text-[9px] font-mono px-1.5 py-0.5 rounded ${
              accuracy < 3 ? 'bg-emerald-500/15 text-emerald-400' :
              accuracy <= 10 ? 'bg-amber-500/15 text-amber-400' :
              'bg-red-500/15 text-red-400'
            }`}>
              ±{accuracy.toFixed(1)}m
            </span>
          )}
        </div>
      )}

      {/* WGS84 */}
      <div className="flex items-start gap-2">
        <Globe className="w-3 h-3 text-blue-400 shrink-0 mt-0.5" />
        <div className="flex-1 min-w-0">
          <span className="text-[9px] text-gray-600 uppercase tracking-wider">WGS84</span>
          <div className={`font-mono text-gray-300 ${compact ? 'text-[10px]' : 'text-xs'}`}>
            {fmt(datums.wgs84!.lat, 6)}, {fmt(datums.wgs84!.lng, 6)}
          </div>
        </div>
      </div>

      {/* Arc 1960 / UTM 37S */}
      {datums.utm37s && (
        <div className="flex items-start gap-2">
          <MapPin className="w-3 h-3 text-[#D17B47] shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <span className="text-[9px] text-gray-600 uppercase tracking-wider">Arc 1960 / UTM 37S</span>
            <div className={`font-mono text-gray-300 ${compact ? 'text-[10px]' : 'text-xs'}`}>
              E: {fmt(datums.utm37s.easting, 3)}, N: {fmt(datums.utm37s.northing, 3)}
            </div>
          </div>
        </div>
      )}

      {/* Cassini-Soldner */}
      {datums.cassini && (
        <div className="flex items-start gap-2">
          <Layers className="w-3 h-3 text-purple-400 shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <span className="text-[9px] text-gray-600 uppercase tracking-wider">
              Cassini{datums.cassini.sheet ? ` — Sheet ${datums.cassini.sheet}` : ''}
            </span>
            <div className={`font-mono text-gray-300 ${compact ? 'text-[10px]' : 'text-xs'}`}>
              E: {fmt(datums.cassini.easting, 3)}, N: {fmt(datums.cassini.northing, 3)}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * FieldRecordVault — Crowdsourced historic F/R index
 *
 * Search and contribute historic Field Record numbers spatially.
 * Surveyors can find old F/R numbers by searching near their project area,
 * saving days of archival research at Ardhi House.
 *
 * Features:
 * - Text search (F/R number, locality, surveyor name)
 * - Proximity search (by coordinate + radius)
 * - Contribute new records
 * - View results with distance, year, surveyor, parcels
 */

import { useState, useCallback, useEffect } from 'react'
import {
  Search, MapPin, Plus, Loader2, CheckCircle2,
  Calendar, User, FileText, ChevronRight, X,
} from 'lucide-react'
import { VirtualList } from '@/components/shared/VirtualList'

interface FieldRecord {
  id: string
  fr_number: string
  fr_type: string
  easting: number
  northing: number
  county?: string
  locality?: string
  survey_year?: number
  surveyor_name?: string
  parcel_numbers?: string[]
  description?: string
  is_verified: boolean
  distance_m?: number
}

export function FieldRecordVault() {
  const [records, setRecords] = useState<FieldRecord[]>([])
  const [loading, setLoading] = useState(false)
  const [searchMode, setSearchMode] = useState<'text' | 'proximity'>('text')
  const [query, setQuery] = useState('')
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [radius, setRadius] = useState('5000')
  const [showAddForm, setShowAddForm] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const search = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const params = new URLSearchParams()
      if (searchMode === 'text' && query) {
        params.set('q', query)
      } else if (searchMode === 'proximity') {
        if (!easting || !northing) {
          setError('Enter easting and northing for proximity search')
          setLoading(false)
          return
        }
        params.set('easting', easting)
        params.set('northing', northing)
        params.set('radius', radius)
      }
      params.set('limit', '50')

      const res = await fetch(`/api/field-records?${params}`)
      if (!res.ok) throw new Error('Search failed')
      const data = await res.json()
      setRecords(data.data?.records || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Search failed')
    } finally {
      setLoading(false)
    }
  }, [searchMode, query, easting, northing, radius])

  useEffect(() => {
    search()
  }, [])

  return (
    <div className="space-y-4">
      {/* Search header */}
      <div className="card p-4 space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
              <FileText className="w-4 h-4 text-[var(--accent)]" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-[var(--text-primary)]">F/R Index Vault</h2>
              <p className="text-[10px] text-gray-500">Crowdsourced historic field record search</p>
            </div>
          </div>
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className="flex items-center gap-1.5 px-3 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)] text-xs font-medium hover:bg-[var(--accent)]/20"
          >
            <Plus className="w-3.5 h-3.5" />
            Contribute
          </button>
        </div>

        {/* Mode toggle */}
        <div className="flex gap-1 p-1 bg-[var(--bg-tertiary)]/50 rounded-lg">
          <button
            onClick={() => setSearchMode('text')}
            className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
              searchMode === 'text' ? 'bg-[var(--accent)]/15 text-[var(--accent)]' : 'text-gray-400'
            }`}
          >
            <Search className="w-3.5 h-3.5" />
            Search by Text
          </button>
          <button
            onClick={() => setSearchMode('proximity')}
            className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
              searchMode === 'proximity' ? 'bg-[var(--accent)]/15 text-[var(--accent)]' : 'text-gray-400'
            }`}
          >
            <MapPin className="w-3.5 h-3.5" />
            Search by Location
          </button>
        </div>

        {/* Search inputs */}
        {searchMode === 'text' ? (
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
            <input
              type="text"
              value={query}
              onChange={e => setQuery(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && search()}
              aria-label="Search F/R number, locality, surveyor..." placeholder="Search F/R number, locality, surveyor..."
              className="w-full h-10 pl-9 pr-3 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>
        ) : (
          <div className="grid grid-cols-3 gap-2">
            <div>
              <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="easting">Easting</label>
              <input id="easting" type="number" value={easting} onChange={e => setEasting(e.target.value)} aria-label="534850" placeholder="534850" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono" />
            </div>
            <div>
              <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="northing">Northing</label>
              <input id="northing" type="number" value={northing} onChange={e => setNorthing(e.target.value)} aria-label="9574220" placeholder="9574220" className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono" />
            </div>
            <div>
              <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="radius-m">Radius (m)</label>
              <input id="radius-m" aria-label="Radius (m)" type="number" value={radius} onChange={e => setRadius(e.target.value)} className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono" />
            </div>
          </div>
        )}

        <button
          onClick={search}
          disabled={loading}
          className="w-full flex items-center justify-center gap-2 h-9 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-50"
        >
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4" />}
          Search Records
        </button>
      </div>

      {/* Add form */}
      {showAddForm && (
        <AddRecordForm
          onClose={() => setShowAddForm(false)}
          onAdded={() => { setShowAddForm(false); search() }}
        />
      )}

      {/* Error */}
      {error && (
        <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/20 text-xs text-red-400">{error}</div>
      )}

      {/* Results */}
      <div className="card p-4">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 text-gray-500 animate-spin" />
          </div>
        ) : records.length === 0 ? (
          <div className="text-center py-8">
            <FileText className="w-8 h-8 text-gray-600 mx-auto mb-2" />
            <p className="text-sm text-gray-500">No field records found</p>
            <p className="text-[10px] text-gray-600 mt-1">
              Try a different search or contribute a record to the vault
            </p>
          </div>
        ) : (
          <>
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-medium text-[var(--text-primary)]">
                {records.length} record{records.length !== 1 ? 's' : ''} found
              </span>
            </div>
            {records.length > 30 ? (
              <VirtualList
                items={records}
                itemHeight={88}
                height={400}
                renderItem={(record) => (
                  <div className="p-1">
                    <div className="flex items-start gap-3 p-2 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors">
                      <div className="shrink-0 w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
                        <FileText className="w-3.5 h-3.5 text-[var(--accent)]" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-medium font-mono text-[var(--text-primary)]">{record.fr_number}</span>
                          {record.is_verified && <CheckCircle2 className="w-3 h-3 text-emerald-400" />}
                          {record.distance_m != null && (
                            <span className="text-[9px] text-[var(--accent)] font-medium">
                              {record.distance_m < 1000 ? `${record.distance_m.toFixed(0)}m away` : `${(record.distance_m / 1000).toFixed(1)}km away`}
                            </span>
                          )}
                        </div>
                        {record.locality && <div className="text-[10px] text-gray-500 mt-0.5">{record.county ? `${record.county} — ` : ''}{record.locality}</div>}
                        <div className="flex items-center gap-3 mt-1 text-[9px] text-gray-600">
                          {record.survey_year && <span>{record.survey_year}</span>}
                          {record.surveyor_name && <span>{record.surveyor_name}</span>}
                        </div>
                      </div>
                      <ChevronRight className="w-3.5 h-3.5 text-gray-600 shrink-0" />
                    </div>
                  </div>
                )}
              />
            ) : (
            <div className="space-y-2">
              {records.map(record => (
                <div
                  key={record.id}
                  className="flex items-start gap-3 p-3 rounded-lg border border-[var(--border-color)] hover:border-[var(--accent)]/30 transition-colors"
                >
                  <div className="shrink-0 w-9 h-9 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
                    <FileText className="w-4 h-4 text-[var(--accent)]" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-medium font-mono text-[var(--text-primary)]">
                        {record.fr_number}
                      </span>
                      {record.is_verified && (
                        <CheckCircle2 className="w-3 h-3 text-emerald-400" />
                      )}
                      {record.distance_m != null && (
                        <span className="text-[9px] text-[var(--accent)] font-medium">
                          {record.distance_m < 1000
                            ? `${record.distance_m.toFixed(0)}m away`
                            : `${(record.distance_m / 1000).toFixed(1)}km away`}
                        </span>
                      )}
                    </div>
                    {record.locality && (
                      <div className="flex items-center gap-1 text-[10px] text-gray-500 mt-0.5">
                        <MapPin className="w-2.5 h-2.5" />
                        {record.county ? `${record.county} — ` : ''}{record.locality}
                      </div>
                    )}
                    <div className="flex items-center gap-3 mt-1 text-[9px] text-gray-600">
                      {record.survey_year && (
                        <span className="flex items-center gap-0.5">
                          <Calendar className="w-2.5 h-2.5" />
                          {record.survey_year}
                        </span>
                      )}
                      {record.surveyor_name && (
                        <span className="flex items-center gap-0.5">
                          <User className="w-2.5 h-2.5" />
                          {record.surveyor_name}
                        </span>
                      )}
                    </div>
                    {record.parcel_numbers && record.parcel_numbers.length > 0 && (
                      <div className="flex items-center gap-1 mt-1 flex-wrap">
                        {record.parcel_numbers.slice(0, 3).map((pn, i) => (
                          <span key={`${pn}-${i}`} className="text-[8px] px-1 py-0.5 rounded bg-white/[0.04] text-gray-400 font-mono">
                            {pn}
                          </span>
                        ))}
                        {record.parcel_numbers.length > 3 && (
                          <span className="text-[8px] text-gray-600">+{record.parcel_numbers.length - 3} more</span>
                        )}
                      </div>
                    )}
                    {record.description && (
                      <p className="text-[10px] text-gray-600 mt-1">{record.description}</p>
                    )}
                  </div>
                  <ChevronRight className="w-4 h-4 text-gray-600 shrink-0" />
                </div>
              ))}
            </div>
            )}
          </>
        )}
      </div>

      {/* Info */}
      <div className="flex items-start gap-2 p-2.5 rounded-lg bg-blue-500/5 border border-blue-500/10">
        <FileText className="w-3 h-3 text-blue-400 shrink-0 mt-0.5" />
        <p className="text-[10px] text-blue-400/70 leading-relaxed">
          The F/R Index Vault is a crowdsourced spatial archive of historic survey field records.
          Search by area to find old F/R numbers, bearings, and reference markers used in past surveys.
          Contribute records you possess to help the surveying community save archival research time.
        </p>
      </div>
    </div>
  )
}

// ─── Add Record Form ─────────────────────────────────────────────

function AddRecordForm({ onClose, onAdded }: { onClose: () => void; onAdded: () => void }) {
  const [frNumber, setFrNumber] = useState('')
  const [easting, setEasting] = useState('')
  const [northing, setNorthing] = useState('')
  const [county, setCounty] = useState('')
  const [locality, setLocality] = useState('')
  const [surveyYear, setSurveyYear] = useState('')
  const [surveyorName, setSurveyorName] = useState('')
  const [description, setDescription] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSave = useCallback(async () => {
    setSaving(true)
    setError(null)
    try {
      const res = await fetch('/api/field-records', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          frNumber, easting: parseFloat(easting), northing: parseFloat(northing),
          county, locality, surveyYear: surveyYear ? parseInt(surveyYear) : null,
          surveyorName, description,
        }),
      })
      if (!res.ok) {
        const data = await res.json()
        throw new Error(data.error || 'Failed')
      }
      onAdded()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed')
    } finally {
      setSaving(false)
    }
  }, [frNumber, easting, northing, county, locality, surveyYear, surveyorName, description, onAdded])

  return (
    <div className="card p-4 space-y-3">
      <div className="flex items-center justify-between">
        <span className="text-xs font-semibold text-[var(--text-primary)]">Contribute F/R Record</span>
        <button onClick={onClose} className="text-gray-400"><X className="w-3.5 h-3.5" /></button>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="f-r-number">F/R Number *</label>
          <input id="f-r-number" type="text" value={frNumber} onChange={e => setFrNumber(e.target.value)} aria-label="FR/123/456" placeholder="FR/123/456" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white font-mono" />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="survey-year">Survey Year</label>
          <input id="survey-year" type="number" value={surveyYear} onChange={e => setSurveyYear(e.target.value)} aria-label="1995" placeholder="1995" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white font-mono" />
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="easting-2">Easting *</label>
          <input id="easting-2" type="number" value={easting} onChange={e => setEasting(e.target.value)} aria-label="534850" placeholder="534850" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white font-mono" />
        </div>
        <div>
          <label className="block text-[9px] text-gray-500 uppercase mb-0.5" htmlFor="northing-2">Northing *</label>
          <input type="number" value={northing} onChange={e => setNorthing(e.target.value)} aria-label="9574220" placeholder="9574220" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white font-mono" />
        </div>
      </div>
      <input type="text" value={county} onChange={e => setCounty(e.target.value)} aria-label="County" placeholder="County" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white" />
      <input type="text" value={locality} onChange={e => setLocality(e.target.value)} aria-label="Locality" placeholder="Locality" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white" />
      <input type="text" value={surveyorName} onChange={e => setSurveyorName(e.target.value)} aria-label="Original Surveyor" placeholder="Original Surveyor" className="w-full h-8 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white" />
      <textarea value={description} onChange={e => setDescription(e.target.value)} placeholder="Description (bearings, tie points, reference markers)..." rows={2} className="w-full px-2 py-1 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs text-white resize-none" />
      {error && <p className="text-xs text-red-400">{error}</p>}
      <button onClick={handleSave} disabled={saving || !frNumber || !easting || !northing} className="w-full h-8 rounded bg-[var(--accent)] text-black text-xs font-semibold disabled:opacity-40">
        {saving ? 'Saving...' : 'Contribute to Vault'}
      </button>
    </div>
  )
}

'use client'

/**
 * GCPOptimizerPanel — Drone GCP planning and validation
 *
 * Features:
 * - Enter project area dimensions
 * - Auto-generate optimal GCP placement
 * - Validation checklist
 * - Export for Pix4D / WebODM
 * - Track GCP survey status
 */

import { useState, useCallback, useMemo } from 'react'
import {
  Drone, MapPin, CheckCircle2, AlertTriangle, Download,
  Plus, Loader2, Camera,
} from 'lucide-react'
import {
  generateGCPPlan,
  generateValidationChecklist,
  exportForPix4D,
  exportForWebODM,
  DEFAULT_UTM_ZONE,
  DEFAULT_HEMISPHERE,
  type GCPPlan,
  type GCPPoint,
} from '@/lib/engine/gcpOptimizer'

export function GCPOptimizerPanel() {
  const [areaHa, setAreaHa] = useState('')
  const [utmZone, setUtmZone] = useState<number>(DEFAULT_UTM_ZONE)
  const [hemisphere, setHemisphere] = useState<'N' | 'S'>(DEFAULT_HEMISPHERE)
  const [plan, setPlan] = useState<GCPPlan | null>(null)
  const [generating, setGenerating] = useState(false)

  const handleGenerate = useCallback(() => {
    const ha = parseFloat(areaHa)
    if (!isFinite(ha) || ha <= 0) return

    setGenerating(true)
    try {
      // Generate a simple rectangular boundary
      const sideM = Math.sqrt(ha * 10000)
      const boundary = [
        { easting: 0, northing: 0 },
        { easting: sideM, northing: 0 },
        { easting: sideM, northing: sideM },
        { easting: 0, northing: sideM },
      ]
      const newPlan = generateGCPPlan({ boundary, areaHa: ha })
      setPlan(newPlan)
    } finally {
      setGenerating(false)
    }
  }, [areaHa])

  const checklist = useMemo(() => {
    if (!plan) return []
    return generateValidationChecklist(plan)
  }, [plan])

  const handleExport = useCallback((format: 'pix4d' | 'webodm') => {
    if (!plan) return
    const csv = format === 'pix4d'
      ? exportForPix4D(plan.gcps, utmZone, hemisphere)
      : exportForWebODM(plan.gcps, utmZone, hemisphere)
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `gcp-export-${format}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }, [plan, utmZone, hemisphere])

  return (
    <div className="space-y-4">
      {/* Area input */}
      <div className="card p-4">
        <div className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1">Project Area (hectares)</div>
        <div className="flex items-center gap-2">
          <input
            type="number"
            step="0.01"
            value={areaHa}
            onChange={e => setAreaHa(e.target.value)}
            aria-label="Project area in hectares" placeholder="10.5"
            className="flex-1 h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] font-mono"
          />
          <button
            onClick={handleGenerate}
            disabled={!areaHa || generating}
            className="flex items-center gap-1.5 px-4 h-9 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold disabled:opacity-40"
          >
            {generating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Drone className="w-4 h-4" />}
            Plan GCPs
          </button>
        </div>
        {/* UTM zone + hemisphere for export correctness (P0-1) */}
        <div className="flex items-center gap-2 mt-2">
          <label className="text-[9px] text-gray-500 uppercase tracking-wider" htmlFor="utm-zone">UTM Zone</label>
          <input
            type="number"
            min={1}
            max={60}
            value={utmZone}
            onChange={e => {
              const z = parseInt(e.target.value, 10)
              if (z >= 1 && z <= 60) setUtmZone(z)
            }}
            aria-label="UTM zone (1 to 60)"
            className="w-16 h-7 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono text-center"
          />
          <div className="flex rounded-lg border border-[var(--border-color)] overflow-hidden">
            {(['N', 'S'] as const).map(h => (
              <button
                key={h}
                onClick={() => setHemisphere(h)}
                className={`px-3 h-7 text-xs font-mono ${hemisphere === h ? 'bg-[var(--accent)] text-black' : 'bg-[var(--bg-tertiary)] text-gray-400'}`}
                aria-pressed={hemisphere === h}
                aria-label={`Hemisphere ${h === 'N' ? 'North' : 'South'}`}
              >
                {h}
              </button>
            ))}
          </div>
          <span className="text-[9px] text-gray-600">Used for Pix4D/WebODM WGS84 export</span>
        </div>
      </div>

      {/* Plan results */}
      {plan && (
        <>
          {/* Summary */}
          <div className="grid grid-cols-3 gap-2">
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50 text-center">
              <div className="text-lg font-bold text-[var(--accent)]">{plan.totalGCPs}</div>
              <div className="text-[9px] text-gray-500 uppercase">GCPs</div>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50 text-center">
              <div className="text-lg font-bold text-emerald-400">±{plan.estimatedAccuracy}cm</div>
              <div className="text-[9px] text-gray-500 uppercase">Est. Accuracy</div>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50 text-center">
              <div className="text-lg font-bold text-gray-300">{plan.coveragePercent.toFixed(0)}%</div>
              <div className="text-[9px] text-gray-500 uppercase">Coverage</div>
            </div>
          </div>

          {/* GCP list */}
          <div className="card p-4">
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-semibold text-[var(--text-primary)]">GCP Placement</span>
              <div className="flex items-center gap-1">
                <button onClick={() => handleExport('pix4d')} className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400">
                  <Download className="w-3 h-3" /> Pix4D
                </button>
                <button onClick={() => handleExport('webodm')} className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400">
                  <Download className="w-3 h-3" /> WebODM
                </button>
              </div>
            </div>
            <div className="space-y-1.5">
              {plan.gcps.map(gcp => (
                <div key={gcp.id} className="flex items-center gap-3 p-2 rounded-lg bg-white/[0.02] border border-[var(--border-color)]">
                  <div className={`shrink-0 w-7 h-7 rounded flex items-center justify-center ${
                    gcp.status === 'validated' ? 'bg-emerald-500/10' :
                    gcp.status === 'surveyed' ? 'bg-blue-500/10' : 'bg-gray-500/10'
                  }`}>
                    <MapPin className={`w-3.5 h-3.5 ${
                      gcp.status === 'validated' ? 'text-emerald-400' :
                      gcp.status === 'surveyed' ? 'text-blue-400' : 'text-gray-400'
                    }`} />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-xs font-mono text-[var(--text-primary)]">{gcp.name}</div>
                    <div className="text-[9px] text-gray-500 font-mono">E:{gcp.easting.toFixed(1)} N:{gcp.northing.toFixed(1)}</div>
                  </div>
                  <div className="flex items-center gap-1.5">
                    {gcp.rtkFixed && <CheckCircle2 className="w-3 h-3 text-emerald-400" />}
                    {gcp.photoCaptured && <Camera className="w-3 h-3 text-blue-400" />}
                    <span className={`text-[9px] px-1.5 py-0.5 rounded ${
                      gcp.status === 'validated' ? 'bg-emerald-500/10 text-emerald-400' :
                      gcp.status === 'surveyed' ? 'bg-blue-500/10 text-blue-400' :
                      'bg-gray-500/10 text-gray-400'
                    }`}>{gcp.status}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Validation checklist */}
          <div className="card p-4">
            <span className="text-xs font-semibold text-[var(--text-primary)] mb-2 block">Field Validation Checklist</span>
            <div className="space-y-1.5">
              {checklist.map((item, i) => (
                <div key={`${item}-${i}`} className="flex items-center gap-2 p-2 rounded-lg bg-white/[0.02]">
                  {item.completed ? (
                    <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
                  ) : (
                    <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0" />
                  )}
                  <span className={`flex-1 text-xs ${item.completed ? 'text-emerald-400' : 'text-gray-400'}`}>{item.item}</span>
                  <span className="text-[9px] text-gray-500">{item.gcpsCompleted}/{item.totalGCPs}</span>
                </div>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  )
}

'use client'

/**
 * GNSSQualityReport — Comprehensive GNSS quality monitoring
 *
 * Enhances the existing GPSGuardrail with full quality metrics:
 * - Fix quality (RTK Fixed/Float, DGPS, GPS, No Fix)
 * - Satellites tracked (GPS, GLONASS, Galileo, BeiDou)
 * - PDOP (Position Dilution of Precision)
 * - HDOP (Horizontal DOP)
 * - VDOP (Vertical DOP)
 * - Base station distance (for RTK)
 * - Age of differential correction
 *
 * Generates a QA/QC report for ArdhiSasa submission compliance.
 * Warns if PDOP > 4.0 or fix is RTK Float (not acceptable for cadastral).
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import {
  Satellite, AlertTriangle, CheckCircle2, Activity,
  Download, RefreshCw,
} from 'lucide-react'

interface GNSSQuality {
  fixQuality: 'rtk_fixed' | 'rtk_float' | 'dgps' | 'gps' | 'none'
  satellites: number
  satellitesGPS: number
  satellitesGLONASS: number
  satellitesGalileo: number
  satellitesBeiDou: number
  pdop: number
  hdop: number
  vdop: number
  baseDistanceKm: number | null
  correctionAge: number | null  // seconds
  latitude: number
  longitude: number
  altitude: number
  timestamp: Date
}

interface QualityCheck {
  metric: string
  value: string
  threshold: string
  status: 'pass' | 'warning' | 'fail'
  description: string
}

const FIX_QUALITY_LABELS: Record<string, { label: string; color: string; icon: string }> = {
  rtk_fixed: { label: 'RTK Fixed', color: 'text-emerald-400', icon: '' },
  rtk_float: { label: 'RTK Float', color: 'text-amber-400', icon: '' },
  dgps: { label: 'DGPS', color: 'text-blue-400', icon: '' },
  gps: { label: 'GPS Only', color: 'text-amber-400', icon: '[Y]' },
  none: { label: 'No Fix', color: 'text-red-400', icon: '[R]' },
}

export function GNSSQualityReport({ externalPosition }: {
  /** When provided (from GNSS rover), uses NMEA data instead of browser geolocation */
  externalPosition?: { lat: number; lng: number; altitude: number; hdop: number; satellites: number; fixType: string; quality: number } | null
}) {
  const [quality, setQuality] = useState<GNSSQuality | null>(null)
  const [history, setHistory] = useState<GNSSQuality[]>([])
  const [watching, setWatching] = useState(false)
  const watchIdRef = useRef<number | null>(null)

  // Use external rover data when available
  useEffect(() => {
    if (!externalPosition) return

    const q: GNSSQuality = {
      fixQuality: externalPosition.fixType as any || (externalPosition.quality >= 4 ? 'rtk_fixed' : externalPosition.quality >= 2 ? 'dgps' : 'gps'),
      satellites: externalPosition.satellites || 0,
      satellitesGPS: 0,
      satellitesGLONASS: 0,
      satellitesGalileo: 0,
      satellitesBeiDou: 0,
      pdop: 0, // Not available from NMEA GGA
      hdop: externalPosition.hdop || 0,
      vdop: 0, // Not available from NMEA GGA
      baseDistanceKm: null,
      correctionAge: null,
      latitude: externalPosition.lat,
      longitude: externalPosition.lng,
      altitude: externalPosition.altitude,
      timestamp: new Date(),
    }
    setQuality(q)
    setHistory(prev => [...prev.slice(-99), q])
  }, [externalPosition])

  const startWatch = useCallback(() => {
    if (watchIdRef.current != null) return // Already watching
    if (externalPosition) return // Using external data, don't start browser GPS
    setWatching(true)

    if (!('geolocation' in navigator)) {
      setWatching(false)
      return
    }

    watchIdRef.current = navigator.geolocation.watchPosition(
      (pos) => {
        const q: GNSSQuality = {
          fixQuality: pos.coords.accuracy < 0.1 ? 'rtk_fixed' :
                       pos.coords.accuracy < 1 ? 'rtk_float' :
                       pos.coords.accuracy < 5 ? 'dgps' :
                       pos.coords.accuracy < 15 ? 'gps' : 'none',
          satellites: 0,
          satellitesGPS: 0,
          satellitesGLONASS: 0,
          satellitesGalileo: 0,
          satellitesBeiDou: 0,
          pdop: 0,
          hdop: pos.coords.accuracy || 99,
          vdop: pos.coords.altitudeAccuracy || 99,
          baseDistanceKm: null,
          correctionAge: null,
          latitude: pos.coords.latitude,
          longitude: pos.coords.longitude,
          altitude: pos.coords.altitude || 0,
          timestamp: new Date(pos.timestamp),
        }
        setQuality(q)
        setHistory(prev => [...prev.slice(-99), q])
      },
      () => {
        setQuality(null)
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 1000 }
    )
  }, [externalPosition]) // AUDIT FIX: Removed `watching` from deps — caused infinite loop

  const stopWatch = useCallback(() => {
    if (watchIdRef.current != null) {
      navigator.geolocation.clearWatch(watchIdRef.current)
      watchIdRef.current = null
    }
    setWatching(false)
  }, [])

  // AUDIT FIX: Only start on mount, don't re-run when startWatch changes
  useEffect(() => {
    startWatch()
    return () => stopWatch()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Quality checks
  const checks: QualityCheck[] = quality ? [
    {
      metric: 'Fix Quality',
      value: FIX_QUALITY_LABELS[quality.fixQuality].label,
      threshold: 'RTK Fixed (cadastral), DGPS (topo)',
      status: quality.fixQuality === 'rtk_fixed' ? 'pass' :
              quality.fixQuality === 'rtk_float' ? 'warning' :
              quality.fixQuality === 'dgps' ? 'warning' : 'fail',
      description: 'RTK Fixed is required for cadastral surveys. RTK Float and DGPS are acceptable for topographic only.',
    },
    {
      metric: 'PDOP',
      value: quality.pdop > 0 ? quality.pdop.toFixed(2) : 'N/A',
      threshold: '< 4.0 (good), < 2.0 (excellent)',
      status: quality.pdop === 0 ? 'warning' :
              quality.pdop < 2.0 ? 'pass' :
              quality.pdop < 4.0 ? 'pass' : 'fail',
      description: 'Position Dilution of Precision. Lower is better. >4.0 means poor satellite geometry.',
    },
    {
      metric: 'HDOP',
      value: quality.hdop > 0 ? quality.hdop.toFixed(2) : 'N/A',
      threshold: '< 2.0 (good), < 1.0 (excellent)',
      status: quality.hdop === 0 ? 'warning' :
              quality.hdop < 1.0 ? 'pass' :
              quality.hdop < 2.0 ? 'pass' : 'warning',
      description: 'Horizontal Dilution of Precision. Affects Easting/Northing accuracy.',
    },
    {
      metric: 'VDOP',
      value: quality.vdop > 0 ? quality.vdop.toFixed(2) : 'N/A',
      threshold: '< 3.0 (good), < 2.0 (excellent)',
      status: quality.vdop === 0 ? 'warning' :
              quality.vdop < 2.0 ? 'pass' :
              quality.vdop < 3.0 ? 'pass' : 'warning',
      description: 'Vertical Dilution of Precision. Affects elevation accuracy.',
    },
    {
      metric: 'Satellites',
      value: quality.satellites > 0 ? String(quality.satellites) : 'N/A',
      threshold: '≥ 6 (minimum), ≥ 10 (good), ≥ 15 (excellent)',
      status: quality.satellites === 0 ? 'warning' :
              quality.satellites >= 15 ? 'pass' :
              quality.satellites >= 10 ? 'pass' :
              quality.satellites >= 6 ? 'warning' : 'fail',
      description: 'Number of satellites used in position calculation. More satellites = better geometry.',
    },
    {
      metric: 'Base Distance',
      value: quality.baseDistanceKm != null ? `${quality.baseDistanceKm.toFixed(1)} km` : 'N/A',
      threshold: '< 10 km (optimal), < 30 km (acceptable)',
      status: quality.baseDistanceKm == null ? 'warning' :
              quality.baseDistanceKm < 10 ? 'pass' :
              quality.baseDistanceKm < 30 ? 'pass' : 'warning',
      description: 'Distance to base station. RTK accuracy degrades beyond 30km.',
    },
    {
      metric: 'Correction Age',
      value: quality.correctionAge != null ? `${quality.correctionAge.toFixed(1)}s` : 'N/A',
      threshold: '< 5s (good), < 10s (acceptable)',
      status: quality.correctionAge == null ? 'warning' :
              quality.correctionAge < 5 ? 'pass' :
              quality.correctionAge < 10 ? 'pass' : 'fail',
      description: 'Age of differential correction. Stale corrections indicate connection issues.',
    },
  ] : []

  const overallStatus = checks.length > 0
    ? checks.some(c => c.status === 'fail') ? 'fail' :
      checks.some(c => c.status === 'warning') ? 'warning' : 'pass'
    : 'pending'

  const handleExport = useCallback(() => {
    if (!quality) return

    const report = {
      format: 'metardu-gnss-quality-v1',
      exportedAt: new Date().toISOString(),
      overallStatus,
      checks: checks.map(c => ({
        metric: c.metric,
        value: c.value,
        threshold: c.threshold,
        status: c.status,
        description: c.description,
      })),
      rawQuality: {
        fixQuality: quality.fixQuality,
        satellites: quality.satellites,
        pdop: quality.pdop,
        hdop: quality.hdop,
        vdop: quality.vdop,
        baseDistanceKm: quality.baseDistanceKm,
        correctionAge: quality.correctionAge,
        position: {
          latitude: quality.latitude,
          longitude: quality.longitude,
          altitude: quality.altitude,
        },
        timestamp: quality.timestamp.toISOString(),
      },
      history: history.slice(-20).map(h => ({
        timestamp: h.timestamp.toISOString(),
        fixQuality: h.fixQuality,
        hdop: h.hdop,
        satellites: h.satellites,
      })),
    }

    const json = JSON.stringify(report, null, 2)
    const blob = new Blob([json], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `gnss-quality-${Date.now()}.json`
    a.click()
    URL.revokeObjectURL(url)
  }, [quality, checks, overallStatus, history])

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${
            overallStatus === 'pass' ? 'bg-emerald-500/10' :
            overallStatus === 'warning' ? 'bg-amber-500/10' :
            overallStatus === 'fail' ? 'bg-red-500/10' : 'bg-gray-500/10'
          }`}>
            <Satellite className={`w-4 h-4 ${
              overallStatus === 'pass' ? 'text-emerald-400' :
              overallStatus === 'warning' ? 'text-amber-400' :
              overallStatus === 'fail' ? 'text-red-400' : 'text-gray-400'
            }`} />
          </div>
          <div>
            <span className="text-sm font-semibold text-[var(--text-primary)]">GNSS Quality Report</span>
            <p className="text-[10px] text-gray-500">QA/QC for ArdhiSasa submission compliance</p>
          </div>
        </div>
        <div className="flex items-center gap-1.5">
          <button
            onClick={handleExport}
            disabled={!quality}
            className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400 hover:text-gray-200 disabled:opacity-30"
          >
            <Download className="w-3 h-3" />
            Export
          </button>
          <button
            onClick={watching ? stopWatch : startWatch}
            className="flex items-center gap-1 px-2 h-7 rounded bg-[var(--bg-tertiary)] border border-[var(--border-color)] text-[10px] text-gray-400 hover:text-gray-200"
          >
            <RefreshCw className={`w-3 h-3 ${watching ? 'animate-spin' : ''}`} />
            {watching ? 'Stop' : 'Start'}
          </button>
        </div>
      </div>

      {/* Overall status */}
      {quality && (
        <div className={`px-4 py-2 border-b border-[var(--border-color)] ${
          overallStatus === 'pass' ? 'bg-emerald-500/5' :
          overallStatus === 'warning' ? 'bg-amber-500/5' :
          'bg-red-500/5'
        }`}>
          <div className="flex items-center gap-2">
            {overallStatus === 'pass' && <CheckCircle2 className="w-4 h-4 text-emerald-400" />}
            {overallStatus === 'warning' && <AlertTriangle className="w-4 h-4 text-amber-400" />}
            {overallStatus === 'fail' && <AlertTriangle className="w-4 h-4 text-red-400" />}
            <span className={`text-xs font-semibold ${
              overallStatus === 'pass' ? 'text-emerald-400' :
              overallStatus === 'warning' ? 'text-amber-400' : 'text-red-400'
            }`}>
              {overallStatus === 'pass' ? 'ACCEPTABLE FOR SUBMISSION' :
               overallStatus === 'warning' ? 'ACCEPTABLE WITH CAUTION' :
               'NOT ACCEPTABLE — FIX BEFORE SUBMISSION'}
            </span>
          </div>
        </div>
      )}

      {/* Checks list */}
      <div className="p-4 space-y-2">
        {!quality ? (
          <div className="flex flex-col items-center py-6">
            <Activity className="w-8 h-8 text-gray-600 mb-2" />
            <p className="text-xs text-gray-500">Waiting for GNSS data...</p>
          </div>
        ) : (
          checks.map((check, i) => (
            <div
              key={`${check}-${i}`}
              className={`flex items-start gap-3 p-2.5 rounded-lg border ${
                check.status === 'pass' ? 'bg-emerald-500/5 border-emerald-500/20' :
                check.status === 'warning' ? 'bg-amber-500/5 border-amber-500/20' :
                'bg-red-500/5 border-red-500/20'
              }`}
            >
              <div className={`shrink-0 w-5 h-5 rounded flex items-center justify-center ${
                check.status === 'pass' ? 'bg-emerald-500/10' :
                check.status === 'warning' ? 'bg-amber-500/10' :
                'bg-red-500/10'
              }`}>
                {check.status === 'pass' ? <CheckCircle2 className="w-3 h-3 text-emerald-400" /> :
                 <AlertTriangle className={`w-3 h-3 ${check.status === 'warning' ? 'text-amber-400' : 'text-red-400'}`} />}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between">
                  <span className="text-[11px] font-medium text-[var(--text-primary)]">{check.metric}</span>
                  <span className={`text-[11px] font-mono font-bold ${
                    check.status === 'pass' ? 'text-emerald-400' :
                    check.status === 'warning' ? 'text-amber-400' : 'text-red-400'
                  }`}>
                    {check.value}
                  </span>
                </div>
                <p className="text-[9px] text-gray-500 mt-0.5">Threshold: {check.threshold}</p>
                <p className="text-[9px] text-gray-600 mt-0.5">{check.description}</p>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Live position */}
      {quality && (
        <div className="px-4 py-2 border-t border-[var(--border-color)] bg-[var(--bg-tertiary)]/30">
          <div className="grid grid-cols-3 gap-2 text-[10px]">
            <div>
              <span className="text-gray-600">Lat:</span>
              <span className="text-gray-300 font-mono ml-1">{quality.latitude.toFixed(8)}</span>
            </div>
            <div>
              <span className="text-gray-600">Lng:</span>
              <span className="text-gray-300 font-mono ml-1">{quality.longitude.toFixed(8)}</span>
            </div>
            <div>
              <span className="text-gray-600">Alt:</span>
              <span className="text-gray-300 font-mono ml-1">{quality.altitude.toFixed(2)}m</span>
            </div>
          </div>
          <div className="text-[8px] text-gray-600 mt-1">
            Updated: {quality.timestamp.toLocaleTimeString()} · History: {history.length} readings
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

/**
 * GNSSRoverConnection — Direct hardware integration for RTK rovers
 *
 * Connects directly to GNSS receivers via:
 * 1. Web Bluetooth API (CHCNAV, South, EFIX, Stonex, Trimble, Leica)
 * 2. Web Serial API (USB-C OTG cable)
 *
 * Streams live NMEA-0183 sentences ($GNGGA, $GNRMC) into the fieldbook.
 * When the surveyor hits "Capture", it reads the current position from
 * the rover and populates the fieldbook row automatically.
 *
 * Uses existing:
 * - src/lib/gnss/nmea-parser.ts (NMEA parsing)
 * - src/lib/gnss/bluetooth.ts (Web Bluetooth)
 * - src/lib/serial/InstrumentSerialConnection.ts (Web Serial)
 * - src/hooks/useInstrumentConnection.ts (connection hook)
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import {
  Bluetooth, Usb, Wifi, WifiOff, Satellite, Loader2,
  CheckCircle2, AlertTriangle, Crosshair, Radio,
  Power, Activity, MapPin,
} from 'lucide-react'

type ConnectionType = 'bluetooth' | 'serial' | 'internal'
type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'error'

interface RoverPosition {
  latitude: number
  longitude: number
  altitude: number
  hdop: number
  satellites: number
  fixType: string
  timestamp: Date
  quality: number
}

const FIX_TYPE_LABELS: Record<string, string> = {
  none: 'No Fix',
  gps: 'GPS Fix',
  dgps: 'DGPS',
  pps: 'PPS',
  rtk: 'RTK Fixed',
  float: 'RTK Float',
}

const FIX_TYPE_COLORS: Record<string, string> = {
  none: 'text-red-400',
  gps: 'text-amber-400',
  dgps: 'text-blue-400',
  pps: 'text-blue-400',
  rtk: 'text-emerald-400',
  float: 'text-cyan-400',
}

export function GNSSRoverConnection() {
  const [connectionType, setConnectionType] = useState<ConnectionType>('internal')
  const [state, setState] = useState<ConnectionState>('disconnected')
  const [position, setPosition] = useState<RoverPosition | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [nmeaCount, setNmeaCount] = useState(0)
  const watchIdRef = useRef<number | null>(null)
  const bluetoothCleanupRef = useRef<(() => void) | null>(null)

  // Check API support
  const bluetoothSupported = typeof navigator !== 'undefined' && 'bluetooth' in navigator
  const serialSupported = typeof navigator !== 'undefined' && 'serial' in navigator

  // Internal GPS fallback (browser Geolocation API)
  const connectInternal = useCallback(async () => {
    setState('connecting')
    setError(null)
    try {
      if (!('geolocation' in navigator)) {
        throw new Error('Geolocation not supported')
      }
      watchIdRef.current = navigator.geolocation.watchPosition(
        (pos) => {
          setPosition({
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude,
            altitude: pos.coords.altitude || 0,
            hdop: pos.coords.accuracy || 99,
            satellites: 0,
            fixType: pos.coords.accuracy < 3 ? 'rtk' : pos.coords.accuracy < 10 ? 'gps' : 'none',
            timestamp: new Date(pos.timestamp),
            quality: pos.coords.accuracy < 3 ? 4 : 1,
          })
          setNmeaCount(prev => prev + 1)
          setState('connected')
        },
        (err) => {
          setError(err.message)
          setState('error')
        },
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 1000 }
      )
      setState('connected')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to connect')
      setState('error')
    }
  }, [])

  // Web Bluetooth connection
  const connectBluetooth = useCallback(async () => {
    setState('connecting')
    setError(null)
    try {
      if (!bluetoothSupported) {
        throw new Error('Web Bluetooth not supported. Use Chrome or Edge.')
      }

      // Dynamically import the existing bluetooth module
      const { WebBluetoothGNSS } = await import('@/lib/gnss/bluetooth')
      const gnss = new WebBluetoothGNSS()

      // Set up position callback
      gnss.onPosition((nmeaPos: any) => {
        setPosition({
          latitude: nmeaPos.latitude,
          longitude: nmeaPos.longitude,
          altitude: nmeaPos.altitude,
          hdop: nmeaPos.hdop,
          satellites: nmeaPos.satellites,
          fixType: nmeaPos.fixType,
          timestamp: nmeaPos.timestamp,
          quality: nmeaPos.quality,
        })
        setNmeaCount(prev => prev + 1)
      })

      await gnss.connect()
      bluetoothCleanupRef.current = () => { gnss.disconnect() }
      setState('connected')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Bluetooth connection failed')
      setState('error')
    }
  }, [bluetoothSupported])

  // Web Serial connection
  const connectSerial = useCallback(async () => {
    setState('connecting')
    setError(null)
    try {
      if (!serialSupported) {
        throw new Error('Web Serial not supported. Use Chrome or Edge.')
      }

      const port = await (navigator as any).serial.requestPort()
      await port.open({ baudRate: 115200 })

      const reader = port.readable.getReader()
      const decoder = new TextDecoder()
      let buffer = ''

      // Read loop
      const readLoop = async () => {
        try {
          while (true) {
            const { done, value } = await reader.read()
            if (done) break
            buffer += decoder.decode(value, { stream: true })

            // Process complete NMEA sentences
            const lines = buffer.split('\n')
            buffer = lines.pop() || ''

            for (const line of lines) {
              const trimmed = line.trim()
              if (trimmed.startsWith('$')) {
                setNmeaCount(prev => prev + 1)
                // Parse NMEA
                try {
                  const { parseNMEA } = await import('@/lib/gnss/nmea-parser')
                  const parsed = parseNMEA(trimmed)
                  if (parsed && parsed.latitude) {
                    setPosition({
                      latitude: parsed.latitude,
                      longitude: parsed.longitude,
                      altitude: parsed.altitude,
                      hdop: parsed.hdop,
                      satellites: parsed.satellites,
                      fixType: parsed.fixType,
                      timestamp: parsed.timestamp,
                      quality: parsed.quality,
                    })
                  }
                } catch {}
              }
            }
          }
        } catch (err) {
          setError('Serial read error: ' + (err instanceof Error ? err.message : 'unknown'))
          setState('error')
        }
      }

      readLoop()
      setState('connected')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Serial connection failed')
      setState('error')
    }
  }, [serialSupported])

  const handleConnect = useCallback(() => {
    if (connectionType === 'bluetooth') connectBluetooth()
    else if (connectionType === 'serial') connectSerial()
    else connectInternal()
  }, [connectionType, connectBluetooth, connectSerial, connectInternal])

  const handleDisconnect = useCallback(() => {
    if (watchIdRef.current != null && connectionType === 'internal') {
      navigator.geolocation.clearWatch(watchIdRef.current)
      watchIdRef.current = null
    }
    if (bluetoothCleanupRef.current) {
      bluetoothCleanupRef.current()
      bluetoothCleanupRef.current = null
    }
    setState('disconnected')
    setPosition(null)
    setNmeaCount(0)
  }, [connectionType])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (watchIdRef.current != null) {
        navigator.geolocation.clearWatch(watchIdRef.current)
      }
      if (bluetoothCleanupRef.current) {
        bluetoothCleanupRef.current()
      }
    }
  }, [])

  const isConnecting = state === 'connecting'
  const isConnected = state === 'connected'
  const fixColor = position ? FIX_TYPE_COLORS[position.fixType] || 'text-gray-400' : 'text-gray-600'
  const fixLabel = position ? FIX_TYPE_LABELS[position.fixType] || 'Unknown' : 'No Fix'

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${
            isConnected ? 'bg-emerald-500/10' : 'bg-[var(--bg-tertiary)]'
          }`}>
            <Satellite className={`w-4 h-4 ${isConnected ? 'text-emerald-400' : 'text-gray-400'}`} />
          </div>
          <div>
            <span className="text-sm font-semibold text-[var(--text-primary)]">GNSS Rover</span>
            <p className="text-[10px] text-gray-500">Direct hardware connection</p>
          </div>
        </div>
        {/* Status indicator */}
        <div className="flex items-center gap-1.5">
          {isConnecting && <Loader2 className="w-3 h-3 text-amber-400 animate-spin" />}
          {isConnected && <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />}
          <span className={`text-[10px] font-medium ${
            state === 'connected' ? 'text-emerald-400' :
            state === 'connecting' ? 'text-amber-400' :
            state === 'error' ? 'text-red-400' : 'text-gray-500'
          }`}>
            {state === 'connected' ? 'Connected' : state === 'connecting' ? 'Connecting...' : state === 'error' ? 'Error' : 'Disconnected'}
          </span>
        </div>
      </div>

      <div className="p-4 space-y-3">
        {/* Connection type selector */}
        <div>
          <div className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1.5">Connection Method</div>
          <div className="grid grid-cols-3 gap-2">
            <ConnTypeBtn
              active={connectionType === 'bluetooth'}
              onClick={() => setConnectionType('bluetooth')}
              icon={Bluetooth}
              label="Bluetooth"
              supported={bluetoothSupported}
            />
            <ConnTypeBtn
              active={connectionType === 'serial'}
              onClick={() => setConnectionType('serial')}
              icon={Usb}
              label="USB Serial"
              supported={serialSupported}
            />
            <ConnTypeBtn
              active={connectionType === 'internal'}
              onClick={() => setConnectionType('internal')}
              icon={Radio}
              label="Internal GPS"
              supported={true}
