'use client'

/**
 * GPSGuardrail — Real-time GPS accuracy indicator for field work
 *
 * Levels:
 * - HIGH (accuracy < 3m): "High Precision" — safe for cadastral work
 * - MODERATE (3-10m): "Moderate Accuracy" — OK for topo
 * - LOW (> 10m): "Low Precision" — warn user, don't capture
 */

import { useEffect, useState, useRef, useCallback } from 'react'
import { ShieldCheck, ShieldAlert, ShieldQuestion, Satellite, Activity } from 'lucide-react'

type AccuracyLevel = 'high' | 'moderate' | 'low' | 'unknown'

interface GPSReading {
  lat: number
  lng: number
  accuracy: number
  altitude?: number | null
  timestamp: number
}

interface GPSGuardrailProps {
  compact?: boolean
  onAccuracyChange?: (level: AccuracyLevel, reading: GPSReading | null) => void
  useCapacitor?: boolean
  showCoords?: boolean
}

const ACCURACY_CONFIG: Record<AccuracyLevel, {
  label: string
  description: string
  color: string
  bg: string
  border: string
  icon: typeof ShieldCheck
}> = {
  high: { label: 'High Precision', description: 'Safe for cadastral capture', color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', icon: ShieldCheck },
  moderate: { label: 'Moderate Accuracy', description: 'OK for topographic work', color: 'text-amber-400', bg: 'bg-amber-500/10', border: 'border-amber-500/30', icon: ShieldAlert },
  low: { label: 'Low Precision', description: 'Do not capture — poor signal', color: 'text-red-400', bg: 'bg-red-500/10', border: 'border-red-500/30', icon: ShieldAlert },
  unknown: { label: 'No GPS Signal', description: 'Waiting for satellite fix...', color: 'text-gray-400', bg: 'bg-gray-500/10', border: 'border-gray-500/30', icon: ShieldQuestion },
}

function getAccuracyLevel(accuracy: number | null | undefined): AccuracyLevel {
  if (accuracy == null || !isFinite(accuracy)) return 'unknown'
  if (accuracy < 3) return 'high'
  if (accuracy <= 10) return 'moderate'
  return 'low'
}

export function GPSGuardrail({ compact = false, onAccuracyChange, useCapacitor = false, showCoords = false }: GPSGuardrailProps) {
  const [reading, setReading] = useState<GPSReading | null>(null)
  const [level, setLevel] = useState<AccuracyLevel>('unknown')
  const [watching, setWatching] = useState(false)
  const watchIdRef = useRef<string | number | null>(null)
  const lastCallbackRef = useRef<{ level: AccuracyLevel; reading: GPSReading | null }>({ level: 'unknown', reading: null })

  const startWatch = useCallback(async () => {
    if (watching) return
    setWatching(true)
    try {
      if (useCapacitor) {
        const { Geolocation } = await import('@capacitor/geolocation')
        const watchId = await Geolocation.watchPosition(
          { enableHighAccuracy: true, timeout: 10000, maximumAge: 1000 },
          (pos, err) => {
            if (err || !pos) { setLevel('unknown'); setReading(null); return }
            const r: GPSReading = { lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: pos.coords.accuracy, altitude: pos.coords.altitude, timestamp: pos.timestamp }
            setReading(r); setLevel(getAccuracyLevel(r.accuracy))
          }
        )
        watchIdRef.current = watchId
      } else {
        if (!('geolocation' in navigator)) { setLevel('unknown'); setWatching(false); return }
        const watchId = navigator.geolocation.watchPosition(
          (pos) => {
            const r: GPSReading = { lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: pos.coords.accuracy, altitude: pos.coords.altitude, timestamp: pos.timestamp }
            setReading(r); setLevel(getAccuracyLevel(r.accuracy))
          },
          () => { setLevel('unknown'); setReading(null) },
          { enableHighAccuracy: true, timeout: 10000, maximumAge: 1000 }
        )
        watchIdRef.current = watchId
      }
    } catch (err) {
      console.warn('[GPSGuardrail] Failed to start watch:', err)
      setWatching(false)
    }
  }, [useCapacitor, watching])

  const stopWatch = useCallback(async () => {
    if (watchIdRef.current != null) {
      try {
        if (useCapacitor) {
          const { Geolocation } = await import('@capacitor/geolocation')
          await Geolocation.clearWatch({ id: watchIdRef.current as string })
        } else {
          navigator.geolocation.clearWatch(watchIdRef.current as number)
        }
      } catch {}
      watchIdRef.current = null
    }
    setWatching(false)
  }, [useCapacitor])

  useEffect(() => {
    startWatch()
    return () => { stopWatch() }
  }, [startWatch, stopWatch])

  useEffect(() => {
    if (onAccuracyChange) {
      const last = lastCallbackRef.current
      if (last.level !== level || last.reading !== reading) {
        lastCallbackRef.current = { level, reading }
        onAccuracyChange(level, reading)
      }
    }
  }, [level, reading, onAccuracyChange])

  const config = ACCURACY_CONFIG[level]
  const Icon = config.icon

  if (compact) {
    return (
      <div className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-md border ${config.bg} ${config.border} ${config.color}`} title={`${config.label} — ${config.description}`}>
        <Icon className="w-3.5 h-3.5" />
        <span className="text-[10px] font-medium">{reading ? `±${reading.accuracy.toFixed(1)}m` : '—'}</span>
      </div>
    )
  }

  return (
    <div className={`rounded-xl border ${config.bg} ${config.border} p-3`}>
      <div className="flex items-start gap-3">
        <div className={`shrink-0 w-10 h-10 rounded-lg flex items-center justify-center ${config.bg} ${config.border} border`}>
          <Icon className={`w-5 h-5 ${config.color}`} />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className={`text-sm font-semibold ${config.color}`}>{config.label}</span>
            {reading && <span className={`text-[10px] font-mono px-1.5 py-0.5 rounded ${config.bg} ${config.color}`}>±{reading.accuracy.toFixed(2)}m</span>}
          </div>
          <p className="text-[11px] text-gray-500 mt-0.5">{config.description}</p>
          {showCoords && reading && (
            <div className="mt-2 grid grid-cols-2 gap-1 text-[10px] font-mono text-gray-400">
              <div>Lat: {reading.lat.toFixed(6)}</div>
              <div>Lng: {reading.lng.toFixed(6)}</div>
              {reading.altitude != null && <div>Alt: {reading.altitude.toFixed(1)}m</div>}
              <div className="flex items-center gap-1"><Activity className="w-2.5 h-2.5" />{new Date(reading.timestamp).toLocaleTimeString()}</div>
            </div>
          )}
        </div>
        <div className="shrink-0"><Satellite className={`w-4 h-4 ${watching ? 'text-emerald-400 animate-pulse' : 'text-gray-600'}`} /></div>
      </div>
      <div className="mt-2 flex items-center gap-1">
        <div className="flex-1 h-1.5 rounded-full bg-gray-700 overflow-hidden">
          <div className={`h-full rounded-full transition-all duration-500 ${level === 'high' ? 'bg-emerald-500 w-full' : level === 'moderate' ? 'bg-amber-500 w-2/3' : level === 'low' ? 'bg-red-500 w-1/3' : 'bg-gray-600 w-0'}`} />
        </div>
        <span className="text-[9px] text-gray-600 shrink-0">3m | 10m</span>
      </div>
    </div>
  )
}

export type { AccuracyLevel, GPSReading }
export { getAccuracyLevel }

'use client'

/**
 * NTRIPClientPanel — UI for connecting to NTRIP CORS networks
 *
 * Lets surveyors:
 * - Select a Kenya CORS preset (MUYA, AGL, KENCORS, KPLC)
 * - Or enter custom NTRIP caster details
 * - Connect and receive RTCM3 corrections
 * - Stream corrections to connected GNSS rover via Bluetooth
 * - Send GGA position to caster for VRS
 * - Monitor connection quality
 *
 * Uses existing:
 * - src/lib/gnss/ntrip-client.ts (NTRIPClient class)
 * - src/lib/gnss/bluetooth.ts (WebBluetoothGNSS)
 * - ntrip-proxy.js (WebSocket bridge)
 */

import { useState, useCallback, useEffect, useRef } from 'react'
import {
  Radio, Wifi, WifiOff, Loader2, Satellite,
  CheckCircle2, AlertTriangle, Settings2, ChevronDown,
} from 'lucide-react'

type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'error'

interface NTRIPConfig {
  host: string
  port: number
  mountpoint: string
  username: string
  password: string
}

const KENYA_PRESETS: Array<{
  id: string
  name: string
  host: string
  port: number
  mountpoint: string
  notes: string
}> = [
  {
    id: 'MUYA',
    name: 'Muya CORS',
    host: 'muya-cors.com',
    port: 2101,
    mountpoint: 'RTCM32_NR_MUYA',
    notes: 'RTCM 3.2 — Measurement Systems Ltd. (subscription required)',
  },
  {
    id: 'AGL',
    name: 'AGL CORS',
    host: 'aglcors.com',
    port: 2101,
    mountpoint: 'RTCM3_AGL',
    notes: 'RTCM 3.x — Africa Geonetwork Ltd. (subscription required)',
  },
  {
    id: 'KENCORS',
    name: 'Kenya CORS (KENCORS)',
    host: 'kencors.go.ke',
    port: 2101,
    mountpoint: 'KENCORS_RTCM3',
    notes: 'Government CORS network — free for licensed surveyors',
  },
  {
    id: 'KPLC',
    name: 'KPLC CORS',
    host: 'kplc.co.ke',
    port: 2101,
    mountpoint: 'RTCM3_KPLC',
    notes: 'Kenya Power network — limited access',
  },
  {
    id: 'CUSTOM',
    name: 'Custom Caster',
    host: '',
    port: 2101,
    mountpoint: '',
    notes: 'Enter your own NTRIP caster details',
  },
]

export function NTRIPClientPanel() {
  const [selectedPreset, setSelectedPreset] = useState('KENCORS')
  const [config, setConfig] = useState<NTRIPConfig>({
    host: 'kencors.go.ke',
    port: 2101,
    mountpoint: 'KENCORS_RTCM3',
    username: '',
    password: '',
  })
  const [state, setState] = useState<ConnectionState>('disconnected')
  const [error, setError] = useState<string | null>(null)
  const [rtcmMessages, setRtcmMessages] = useState(0)
  const [lastGgaSent, setLastGgaSent] = useState<Date | null>(null)
  const [showAdvanced, setShowAdvanced] = useState(false)
  const ntripClientRef = useRef<any>(null)

  // Update config when preset changes
  const handlePresetChange = useCallback((presetId: string) => {
    setSelectedPreset(presetId)
    const preset = KENYA_PRESETS.find(p => p.id === presetId)
    if (preset && presetId !== 'CUSTOM') {
      setConfig(prev => ({
        ...prev,
        host: preset.host,
        port: preset.port,
        mountpoint: preset.mountpoint,
      }))
    }
  }, [])

  const handleConnect = useCallback(async () => {
    setState('connecting')
    setError(null)
    setRtcmMessages(0)

    try {
      // Dynamic import to avoid SSR issues
      const { NTRIPClient } = await import('@/lib/gnss/ntrip-client')

      const client = new NTRIPClient({
        host: config.host,
        port: config.port,
        mountpoint: config.mountpoint,
        username: config.username || undefined,
        password: config.password || undefined,
        version: 2,
      } as any)

      client.onCorrection((data: Uint8Array) => {
        setRtcmMessages(prev => prev + 1)
      })

      client.onStatus((status: string) => {
        if (status === 'connected') setState('connected')
        if (status === 'error') setState('error')
        if (status === 'disconnected') setState('disconnected')
      })

      await client.connect()
      ntripClientRef.current = client
      setState('connected')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Connection failed')
      setState('error')
    }
  }, [config])

  const handleDisconnect = useCallback(() => {
    if (ntripClientRef.current) {
      ntripClientRef.current.disconnect()
      ntripClientRef.current = null
    }
    setState('disconnected')
    setRtcmMessages(0)
  }, [])

  // Send GGA position to caster (for VRS)
  const sendGGA = useCallback(async (lat: number, lng: number) => {
    if (!ntripClientRef.current || state !== 'connected') return

    // Format NMEA GGA sentence
    const now = new Date()
    const hh = now.getUTCHours().toString().padStart(2, '0')
    const mm = now.getUTCMinutes().toString().padStart(2, '0')
    const ss = now.getUTCSeconds().toString().padStart(2, '0')

    const latDeg = Math.floor(Math.abs(lat))
    const latMin = (Math.abs(lat) - latDeg) * 60
    const latDir = lat >= 0 ? 'N' : 'S'
    const lngDeg = Math.floor(Math.abs(lng))
    const lngMin = (Math.abs(lng) - lngDeg) * 60
    const lngDir = lng >= 0 ? 'E' : 'W'

    const gga = `GPGGA,${hh}${mm}${ss},${latDeg.toString().padStart(2, '0')}${latMin.toFixed(4)},${latDir},${lngDeg.toString().padStart(3, '0')}${lngMin.toFixed(4)},${lngDir},1,08,1.0,0,M,0,M,,*`

    // Calculate checksum
    let checksum = 0
    for (let i = 0; i < gga.length; i++) {
      checksum ^= gga.charCodeAt(i)
    }

    const sentence = `$${gga}${checksum.toString(16).toUpperCase().padStart(2, '0')}`

    try {
      ntripClientRef.current.sendGGA(sentence)
      setLastGgaSent(new Date())
    } catch (err) {
      // Silent fail
    }
  }, [state])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (ntripClientRef.current) {
        ntripClientRef.current.disconnect()
      }
    }
  }, [])

  const selectedPresetData = KENYA_PRESETS.find(p => p.id === selectedPreset)
  const isConnected = state === 'connected'
  const isConnecting = state === 'connecting'

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${
            isConnected ? 'bg-emerald-500/10' : 'bg-[var(--bg-tertiary)]'
          }`}>
            <Radio className={`w-4 h-4 ${isConnected ? 'text-emerald-400' : 'text-gray-400'}`} />
          </div>
          <div>
            <span className="text-sm font-semibold text-[var(--text-primary)]">NTRIP Corrections</span>
            <p className="text-[10px] text-gray-500">RTK correction stream from CORS network</p>
          </div>
        </div>
        {/* Status indicator */}
        <div className="flex items-center gap-1.5">
          {isConnecting && <Loader2 className="w-3 h-3 text-amber-400 animate-spin" />}
          {isConnected && <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />}
          <span className={`text-[10px] font-medium ${
            isConnected ? 'text-emerald-400' :
            isConnecting ? 'text-amber-400' :
            state === 'error' ? 'text-red-400' : 'text-gray-500'
          }`}>
            {isConnected ? 'Streaming' : isConnecting ? 'Connecting...' : state === 'error' ? 'Error' : 'Disconnected'}
          </span>
        </div>
      </div>

      <div className="p-4 space-y-3">
        {/* Preset selector */}
        <div>
          <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1.5" htmlFor="cors-network">CORS Network</label>
          <select id="cors-network"
            value={selectedPreset}
            onChange={e => handlePresetChange(e.target.value)}
            disabled={isConnected}
            className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] disabled:opacity-50"
          >
            {KENYA_PRESETS.map(p => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
          {selectedPresetData && (
            <p className="text-[9px] text-gray-600 mt-1">{selectedPresetData.notes}</p>
          )}
        </div>

        {/* Advanced settings */}
        <button
          onClick={() => setShowAdvanced(!showAdvanced)}
          className="flex items-center gap-1 text-[10px] text-gray-500 hover:text-gray-300"
        >
          <Settings2 className="w-3 h-3" />
          Advanced Settings
          <ChevronDown className={`w-3 h-3 transition-transform ${showAdvanced ? 'rotate-180' : ''}`} />
        </button>

        {showAdvanced && (
          <div className="space-y-2 p-3 rounded-lg bg-[var(--bg-tertiary)]/50 border border-[var(--border-color)]">
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="block text-[8px] text-gray-500 uppercase mb-0.5" htmlFor="host">Host</label>
                <input id="host" aria-label="Host"
                  type="text"
                  value={config.host}
                  onChange={e => setConfig(prev => ({ ...prev, host: e.target.value }))}
                  disabled={isConnected}
                  className="w-full h-7 px-2 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[10px] text-white font-mono disabled:opacity-50"
                />
              </div>
              <div>
                <label className="block text-[8px] text-gray-500 uppercase mb-0.5" htmlFor="port">Port</label>
                <input id="port" aria-label="Port"
                  type="number"
                  value={config.port}
                  onChange={e => setConfig(prev => ({ ...prev, port: parseInt(e.target.value) || 2101 }))}
                  disabled={isConnected}
                  className="w-full h-7 px-2 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[10px] text-white font-mono disabled:opacity-50"
                />
              </div>
            </div>
            <div>
              <label className="block text-[8px] text-gray-500 uppercase mb-0.5" htmlFor="mountpoint">Mountpoint</label>
              <input id="mountpoint" aria-label="Mountpoint"
                type="text"
                value={config.mountpoint}
                onChange={e => setConfig(prev => ({ ...prev, mountpoint: e.target.value }))}
                disabled={isConnected}
                className="w-full h-7 px-2 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[10px] text-white font-mono disabled:opacity-50"
              />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="block text-[8px] text-gray-500 uppercase mb-0.5" htmlFor="username">Username</label>
                <input id="username" aria-label="Username"
                  type="text"
                  value={config.username}
                  onChange={e => setConfig(prev => ({ ...prev, username: e.target.value }))}
                  disabled={isConnected}
                  className="w-full h-7 px-2 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[10px] text-white disabled:opacity-50"
                />
              </div>
              <div>
                <label className="block text-[8px] text-gray-500 uppercase mb-0.5" htmlFor="password">Password</label>
                <input aria-label="Password"
                  type="password"
                  value={config.password}
                  onChange={e => setConfig(prev => ({ ...prev, password: e.target.value }))}
                  disabled={isConnected}
                  className="w-full h-7 px-2 bg-[var(--bg-primary)] border border-[var(--border-color)] rounded text-[10px] text-white disabled:opacity-50"
                />
              </div>
            </div>
          </div>
        )}

        {/* Error */}
        {error && (
          <div className="flex items-start gap-2 p-2.5 rounded-lg bg-red-500/5 border border-red-500/20">
            <AlertTriangle className="w-3.5 h-3.5 text-red-400 shrink-0 mt-0.5" />
            <p className="text-[11px] text-red-400">{error}</p>
          </div>
        )}

        {/* Connection stats */}
        {isConnected && (
          <div className="grid grid-cols-2 gap-2">
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50">
              <span className="text-[9px] text-gray-500 uppercase tracking-wider">RTCM Messages</span>
              <div className="text-sm font-mono text-emerald-400">{rtcmMessages}</div>
            </div>
            <div className="p-2 rounded-lg bg-[var(--bg-tertiary)]/50">
              <span className="text-[9px] text-gray-500 uppercase tracking-wider">Last GGA Sent</span>
              <div className="text-sm font-mono text-gray-300">
                {lastGgaSent ? lastGgaSent.toLocaleTimeString() : '—'}
              </div>
            </div>
          </div>
        )}

        {/* Connect/Disconnect button */}
        {!isConnected ? (
          <button
            onClick={handleConnect}
            disabled={isConnecting || !config.host || !config.mountpoint}
            className="w-full flex items-center justify-center gap-2 h-10 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-50"
          >
            {isConnecting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Wifi className="w-4 h-4" />}
            {isConnecting ? 'Connecting...' : 'Connect to CORS'}
          </button>
        ) : (
          <button
            onClick={handleDisconnect}
            className="w-full flex items-center justify-center gap-2 h-10 rounded-lg bg-red-500/20 border border-red-500/30 text-red-400 text-sm font-semibold hover:bg-red-500/30"
          >
            <WifiOff className="w-4 h-4" />
            Disconnect
          </button>
        )}

        {/* Info */}
        <div className="flex items-start gap-2 p-2.5 rounded-lg bg-blue-500/5 border border-blue-500/10">
          <Satellite className="w-3 h-3 text-blue-400 shrink-0 mt-0.5" />
          <p className="text-[10px] text-blue-400/70 leading-relaxed">
            NTRIP streams RTCM3 corrections from CORS stations to your rover via Bluetooth.
            VRS mode sends your position to the caster for a virtual reference station.
            Requires an active CORS subscription (except KENCORS for licensed surveyors).
          </p>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * NeighborConsensusForm — Geofenced boundary sign-off
 *
 * Lets surveyors capture formal consensus from adjoining property owners:
 * - Neighbor name, National ID, phone, parcel number
 * - Signature on touchscreen canvas
 * - GPS geofence verification (must be within 5m of beacon)
 * - Cryptographic sealing of the consensus record
 *
 * The signature pad is locked until GPS verifies the surveyor is on-site.
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import {
  User, Phone, MapPin, PenTool, CheckCircle2, AlertTriangle,
  Loader2, Lock, ShieldCheck, X,
} from 'lucide-react'
import {
  createConsensusRecord,
  verifyGeofence,
  GEOFENCE_RADIUS_M,
  type NeighborConsensusRecord,
} from '@/lib/survey/neighborConsensus'

interface NeighborConsensusFormProps {
  beaconId: string
  beaconEasting: number
  beaconNorthing: number
  surveyorId: string
  surveyorLicense: string
  onConsensusCaptured?: (record: NeighborConsensusRecord) => void
  onClose?: () => void
  /** T1.5 FIX (2026-07-09): UTM EPSG for GPS→UTM transform (default 'EPSG:21037') */
  epsg?: string
}

export function NeighborConsensusForm({
  beaconId,
  beaconEasting,
  beaconNorthing,
  surveyorId,
  surveyorLicense,
  onConsensusCaptured,
  onClose,
  epsg = 'EPSG:21037',
}: NeighborConsensusFormProps) {
  const [neighborName, setNeighborName] = useState('')
  const [neighborNationalId, setNeighborNationalId] = useState('')
  const [neighborPhone, setNeighborPhone] = useState('')
  const [neighborParcelNumber, setNeighborParcelNumber] = useState('')

  // Geofence state
  const [currentPos, setCurrentPos] = useState<{ easting: number; northing: number } | null>(null)
  const [distanceFromBeacon, setDistanceFromBeacon] = useState<number | null>(null)
  const [geofenceValid, setGeofenceValid] = useState(false)
  const [checkingLocation, setCheckingLocation] = useState(false)

  // Signature state
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [isDrawing, setIsDrawing] = useState(false)
  const [hasSignature, setHasSignature] = useState(false)

  // Saving state
  const [saving, setSaving] = useState(false)
  const [savedRecord, setSavedRecord] = useState<NeighborConsensusRecord | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Check GPS location for geofence
  const checkLocation = useCallback(async () => {
    setCheckingLocation(true)
    if (!('geolocation' in navigator)) {
      setError('Geolocation not supported')
      setCheckingLocation(false)
      return
    }

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        try {
          const { transform } = await import('ol/proj')
          const [e, n] = transform([pos.coords.longitude, pos.coords.latitude], 'EPSG:4326', epsg) as [number, number]
          const position = { easting: e, northing: n }
          setCurrentPos(position)

          const geofence = verifyGeofence(beaconEasting, beaconNorthing, e, n)
          setDistanceFromBeacon(geofence.distance)
          setGeofenceValid(geofence.isValid)
        } catch {
          setError('Failed to transform coordinates')
        }
        setCheckingLocation(false)
      },
      () => {
        setError('Failed to get GPS position')
        setCheckingLocation(false)
      },
      { enableHighAccuracy: true, timeout: 10000 },
    )
  }, [beaconEasting, beaconNorthing])

  // Auto-check location on mount
  useEffect(() => {
    checkLocation()
  }, [checkLocation])

  // Signature pad handlers
  const startDrawing = useCallback((e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!geofenceValid) return
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    setIsDrawing(true)
    const rect = canvas.getBoundingClientRect()
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY
    ctx.beginPath()
    ctx.moveTo(clientX - rect.left, clientY - rect.top)
  }, [geofenceValid])

  const draw = useCallback((e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!isDrawing) return
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const rect = canvas.getBoundingClientRect()
    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY
    ctx.lineTo(clientX - rect.left, clientY - rect.top)
    ctx.stroke()
    ctx.lineWidth = 2
    ctx.lineCap = 'round'
    ctx.strokeStyle = '#000'
    setHasSignature(true)
  }, [isDrawing])

  const stopDrawing = useCallback(() => {
    setIsDrawing(false)
  }, [])

  const clearSignature = useCallback(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    ctx.clearRect(0, 0, canvas.width, canvas.height)
    setHasSignature(false)
  }, [])

  // Save consensus
  const handleSave = useCallback(async () => {
    if (!geofenceValid) {
      setError('Must be within 5m of beacon to sign')
      return
    }
    if (!neighborName.trim() || !neighborNationalId.trim()) {
      setError('Neighbor name and National ID are required')
      return
    }
    if (!hasSignature) {
      setError('Signature is required')
      return
    }

    setSaving(true)
    setError(null)

    try {
      const canvas = canvasRef.current
      const signatureData = canvas?.toDataURL('image/png') || ''

      const record = await createConsensusRecord({
        beaconId,
        beaconEasting,
        beaconNorthing,
        neighborName,
        neighborNationalId,
        neighborPhone,
        neighborParcelNumber,
        signatureData,
        signLocationEasting: currentPos?.easting || 0,
        signLocationNorthing: currentPos?.northing || 0,
        surveyorId,
        surveyorLicense,
      })

      setSavedRecord(record)
      onConsensusCaptured?.(record)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save consensus')
    } finally {
      setSaving(false)
    }
  }, [geofenceValid, neighborName, neighborNationalId, neighborPhone, neighborParcelNumber, hasSignature, beaconId, beaconEasting, beaconNorthing, currentPos, surveyorId, surveyorLicense, onConsensusCaptured])

  if (savedRecord) {
    return (
      <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/5 p-4 text-center">
        <CheckCircle2 className="w-10 h-10 text-emerald-400 mx-auto mb-3" />
        <h3 className="text-sm font-semibold text-emerald-400">Consensus Captured</h3>
        <p className="text-[10px] text-gray-500 mt-1">
          {savedRecord.neighborName} signed at {new Date(savedRecord.signedAt).toLocaleString()}
        </p>
        <p className="text-[10px] text-gray-600 mt-2">
          Distance from beacon: {savedRecord.distanceFromBeacon.toFixed(2)}m ·
          Geofence: {savedRecord.isGeofenceValid ? 'VALID' : 'INVALID'} ·
          Sealed: {savedRecord.seal ? 'YES' : 'NO'}
        </p>
        {onClose && (
          <button onClick={onClose} className="mt-3 px-4 h-8 rounded-lg bg-emerald-500/20 text-emerald-400 text-xs font-medium">
            Done
          </button>
        )}
      </div>
    )
  }

  return (
    <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[var(--border-color)]">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 flex items-center justify-center">
            <ShieldCheck className="w-4 h-4 text-[var(--accent)]" />
          </div>
          <div>
            <span className="text-sm font-semibold text-[var(--text-primary)]">Boundary Consensus</span>
            <p className="text-[10px] text-gray-500">Geofenced sign-off for adjoining owner</p>
          </div>
        </div>
        {onClose && (
          <button onClick={onClose} className="w-7 h-7 flex items-center justify-center rounded text-gray-400 hover:text-white">
            <X className="w-4 h-4" />
          </button>
        )}
      </div>

      <div className="p-4 space-y-3">
        {/* Geofence status */}
        <div className={`p-3 rounded-lg border ${
          geofenceValid ? 'bg-emerald-500/5 border-emerald-500/20' :
          distanceFromBeacon != null ? 'bg-red-500/5 border-red-500/20' :
          'bg-amber-500/5 border-amber-500/20'
        }`}>
          <div className="flex items-center gap-2">
            {checkingLocation ? (
              <Loader2 className="w-4 h-4 text-amber-400 animate-spin" />
            ) : geofenceValid ? (
              <CheckCircle2 className="w-4 h-4 text-emerald-400" />
            ) : (
              <AlertTriangle className={`w-4 h-4 ${distanceFromBeacon != null ? 'text-red-400' : 'text-amber-400'}`} />
            )}
            <div>
              <span className={`text-xs font-medium ${
                geofenceValid ? 'text-emerald-400' :
                distanceFromBeacon != null ? 'text-red-400' : 'text-amber-400'
              }`}>
                {checkingLocation ? 'Checking location...' :
                 geofenceValid ? 'On-site — sign-off enabled' :
                 distanceFromBeacon != null ? `${distanceFromBeacon.toFixed(1)}m from beacon (must be <${GEOFENCE_RADIUS_M}m)` :
                 'Waiting for GPS...'}
              </span>
            </div>
          </div>
          <button
            onClick={checkLocation}
            className="mt-2 text-[10px] text-gray-500 hover:text-gray-300 flex items-center gap-1"
          >
            <MapPin className="w-3 h-3" />
            Re-check location
          </button>
        </div>

        {/* Neighbor info */}
        <div className="space-y-2">
          <div>
            <label className="flex items-center gap-1 text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="neighbor-name">
              <User className="w-3 h-3" />
              Neighbor Name *
            </label>
            <input id="neighbor-name"
              type="text"
              value={neighborName}
              onChange={e => setNeighborName(e.target.value)}
              aria-label="John Doe" placeholder="John Doe"
              className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="national-id">National ID *</label>
              <input id="national-id"
                type="text"
                value={neighborNationalId}
                onChange={e => setNeighborNationalId(e.target.value)}
                aria-label="12345678" placeholder="12345678"
                className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
              />
            </div>
            <div>
              <label className="flex items-center gap-1 text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="phone">
                <Phone className="w-3 h-3" />
                Phone
              </label>
              <input id="phone"
                type="tel"
                value={neighborPhone}
                onChange={e => setNeighborPhone(e.target.value)}
                aria-label="0712 345 678" placeholder="0712 345 678"
                className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
              />
            </div>
          </div>
          <div>
            <label className="block text-[9px] text-gray-500 uppercase tracking-wider mb-1" htmlFor="neighbor-parcel-no">Neighbor Parcel No.</label>
            <input id="neighbor-parcel-no"
              type="text"
              value={neighborParcelNumber}
              onChange={e => setNeighborParcelNumber(e.target.value)}
              aria-label="LR/12345/679" placeholder="LR/12345/679"
              className="w-full h-9 px-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs text-[var(--text-primary)] font-mono placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
            />
          </div>
        </div>

        {/* Signature pad */}
        <div>
          <div className="flex items-center gap-1 text-[9px] text-gray-500 uppercase tracking-wider mb-1">
            <PenTool className="w-3 h-3" />
            Signature *
          </div>
          <div className={`relative ${!geofenceValid ? 'opacity-40 pointer-events-none' : ''}`}>
            <canvas
              ref={canvasRef}
              width={300}
              height={120}
              onMouseDown={startDrawing}
              onMouseMove={draw}
              onMouseUp={stopDrawing}
              onMouseLeave={stopDrawing}
              onTouchStart={startDrawing}
              onTouchMove={draw}
              onTouchEnd={stopDrawing}
              className="w-full h-[120px] bg-white rounded-lg border border-[var(--border-color)] cursor-crosshair touch-none"
            />
            {!geofenceValid && (
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="flex items-center gap-1.5 text-[10px] text-gray-500">
                  <Lock className="w-3 h-3" />
                  Move within {GEOFENCE_RADIUS_M}m of beacon to unlock
                </div>
              </div>
            )}
          </div>
          {hasSignature && geofenceValid && (
            <button
              onClick={clearSignature}
              className="mt-1 text-[9px] text-gray-500 hover:text-red-400"
            >
              Clear signature
            </button>
          )}
        </div>

        {/* Error */}
        {error && (
          <div className="flex items-start gap-2 p-2 rounded-lg bg-red-500/5 border border-red-500/20">
            <AlertTriangle className="w-3.5 h-3.5 text-red-400 shrink-0 mt-0.5" />
            <p className="text-[11px] text-red-400">{error}</p>
          </div>
        )}

        {/* Save button */}
        <button
          onClick={handleSave}
          disabled={!geofenceValid || saving || !neighborName || !neighborNationalId || !hasSignature}
          className="w-full flex items-center justify-center gap-2 h-10 rounded-lg bg-[var(--accent)] text-black text-sm font-semibold hover:bg-[var(--accent-dim)] disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShieldCheck className="w-4 h-4" />}
          {saving ? 'Sealing...' : 'Capture & Seal Consensus'}
        </button>
      </div>
    </div>
  )
}

'use client'

/**
 * RealTimeQCPanel — Live quality control during field work.
 *
 * Shows:
 *   - Running closure (live misclosure as each leg is added)
 *   - Precision ratio with color coding (green/amber/red)
 *   - Setup verification checklist
 *   - Redundant observation alerts
 *   - Outlier detection results
 *
 * Wired to src/lib/survey/realTimeQC.ts
 */

import { useState, useCallback, useMemo } from 'react'
import {
  RunningClosureMonitor,
  detectRedundantObservationDiscrepancies,
  verifySetup,
  formatPrecisionIndicator,
  type Observation,
  type SurveyClass,
} from '@/lib/survey/realTimeQC'
import {
  Activity, AlertTriangle, CheckCircle2, XCircle, Gauge,
  TrendingDown, Layers, ShieldCheck,
} from 'lucide-react'

interface RealTimeQCPanelProps {
  /** Observations from the current traverse (for redundant obs detection) */
  observations?: Observation[]
  /** Current survey class */
  surveyClass?: SurveyClass
  /** Compact mode (for embedding in field book sidebar) */
  compact?: boolean
}

export function RealTimeQCPanel({
  observations = [],
  surveyClass = 'urban',
  compact = false,
}: RealTimeQCPanelProps) {
  const [monitor] = useState(() => new RunningClosureMonitor(surveyClass))
  const [legs, setLegs] = useState<Array<{ bearing: number; distance: number }>>([])
  const [setupData, setSetupData] = useState({
    instrumentHeight: 1.5,
    targetHeight: 1.5,
    temperature: 25,
    pressure: 1013,
    isControlPoint: false,
  })

  const state = monitor.getState()

  const addLeg = useCallback((bearing: number, distance: number) => {
    monitor.addLeg(bearing, distance)
    setLegs(prev => [...prev, { bearing, distance }])
  }, [monitor])

  const undoLeg = useCallback(() => {
    monitor.removeLastLeg()
    setLegs(prev => prev.slice(0, -1))
  }, [monitor])

  const reset = useCallback(() => {
    monitor.reset()
    setLegs([])
  }, [monitor])

  // Redundant observation check
  const discrepancies = useMemo(
    () => detectRedundantObservationDiscrepancies(observations),
    [observations]
  )

  // Setup verification
  const setupChecks = useMemo(
    () => verifySetup(setupData),
    [setupData]
  )

  const precisionInfo = formatPrecisionIndicator(state.precisionRatio ?? null, surveyClass)

  if (compact) {
    return (
      <div className="space-y-2">
        {/* Precision indicator */}
        <div className="flex items-center justify-between">
          <span className="text-[10px] text-[var(--text-muted)] uppercase">Precision</span>
          <span className={`font-mono text-xs font-bold ${
            precisionInfo.color === 'green' ? 'text-emerald-400'
            : precisionInfo.color === 'amber' ? 'text-amber-400'
            : 'text-red-400'
          }`}>
            {precisionInfo.label}
          </span>
        </div>
        {/* Misclosure */}
        <div className="flex items-center justify-between">
          <span className="text-[10px] text-[var(--text-muted)] uppercase">Misclosure</span>
          <span className="font-mono text-xs text-[var(--text-primary)]">
            {state.linearMisclosure.toFixed(3)}m
          </span>
        </div>
        {/* Warnings */}
        {state.warnings.map((w, i) => (
          <div key={i} className="flex items-start gap-1 text-[10px] text-amber-400">
            <AlertTriangle className="w-3 h-3 shrink-0 mt-0.5" />
            <span>{w}</span>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-4">
      {/* ── Running Closure Monitor ── */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-4">
        <div className="flex items-center gap-2 mb-3">
          <Gauge className="w-4 h-4 text-[var(--accent)]" />
          <h3 className="text-sm font-bold text-[var(--text-primary)]">Running Closure</h3>
        </div>

        {/* Stats grid */}
        <div className="grid grid-cols-3 gap-2 mb-3">
          <div className="text-center">
            <p className="text-lg font-bold text-[var(--text-primary)]">{state.legCount}</p>
            <p className="text-[10px] text-[var(--text-muted)] uppercase">Legs</p>
          </div>
          <div className="text-center">
            <p className="text-lg font-bold text-[var(--text-primary)]">
              {state.linearMisclosure.toFixed(3)}m
            </p>
            <p className="text-[10px] text-[var(--text-muted)] uppercase">Misclosure</p>
          </div>
          <div className="text-center">
            <p className={`text-lg font-bold ${
              precisionInfo.color === 'green' ? 'text-emerald-400'
              : precisionInfo.color === 'amber' ? 'text-amber-400'
              : 'text-red-400'
            }`}>
              {precisionInfo.label}
            </p>
            <p className="text-[10px] text-[var(--text-muted)] uppercase">Precision</p>
          </div>
        </div>

        {/* Distance bar */}
        <div className="mb-2">
          <div className="flex justify-between text-[10px] text-[var(--text-muted)] mb-1">
            <span>Total: {state.totalDistance.toFixed(1)}m</span>
            <span>Required: 1:{state.minRequired.toLocaleString()}</span>
          </div>
          <div className="h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div
              className={`h-full transition-all ${
                state.meetsStandard ? 'bg-emerald-500' : 'bg-amber-500'
              }`}
              style={{
                width: state.totalDistance > 0 && state.precisionRatio
                  ? `${Math.min(100, (state.precisionRatio / state.minRequired) * 100)}%`
                  : '0%'
              }}
            />
          </div>
        </div>

        {/* Warnings */}
        {state.warnings.map((w, i) => (
          <div key={i} className="flex items-start gap-2 text-xs text-amber-400 bg-amber-500/10 rounded-lg p-2 mb-2">
            <AlertTriangle className="w-3.5 h-3.5 shrink-0 mt-0.5" />
            <span>{w}</span>
          </div>
        ))}

        {/* Quick add leg (for testing/manual entry) */}
        <div className="flex gap-2">
          <button
            onClick={() => addLeg(45, 50)}
            className="text-[10px] px-2 py-1 bg-[var(--bg-tertiary)] rounded text-[var(--text-secondary)] hover:bg-[var(--border-color)]"
          >
            + Test Leg (45°, 50m)
          </button>
          {legs.length > 0 && (
            <button
              onClick={undoLeg}
              className="text-[10px] px-2 py-1 bg-[var(--bg-tertiary)] rounded text-[var(--text-secondary)] hover:bg-[var(--border-color)]"
            >
              ↶ Undo
            </button>
          )}
          {legs.length > 0 && (
            <button
              onClick={reset}
              className="text-[10px] px-2 py-1 bg-red-500/10 text-red-400 rounded hover:bg-red-500/20"
            >
              Reset
            </button>
          )}
        </div>
      </div>

      {/* ── Setup Verification ── */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-4">
        <div className="flex items-center gap-2 mb-3">
          <ShieldCheck className="w-4 h-4 text-[var(--accent)]" />
          <h3 className="text-sm font-bold text-[var(--text-primary)]">Setup Check</h3>
        </div>

        <div className="space-y-2">
          {setupChecks.map((check, i) => (
            <div key={i} className="flex items-center gap-2 text-xs">
              {check.passed
                ? <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
                : <XCircle className="w-3.5 h-3.5 text-red-400 shrink-0" />
              }
              <span className={`flex-1 ${check.passed ? 'text-[var(--text-secondary)]' : 'text-red-400'}`}>
                {check.message}
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* ── Redundant Observation Alerts ── */}
      {discrepancies.length > 0 && (
        <div className="rounded-xl border border-red-500/20 bg-red-500/5 p-4">
          <div className="flex items-center gap-2 mb-3">
            <AlertTriangle className="w-4 h-4 text-red-400" />
            <h3 className="text-sm font-bold text-[var(--text-primary)]">
              Observation Discrepancies ({discrepancies.length})
            </h3>
          </div>
          <div className="space-y-2">
            {discrepancies.map((d, i) => (
              <div
                key={i}
                className={`text-xs rounded-lg p-2 ${
                  d.severity === 'error' ? 'bg-red-500/10 text-red-400' : 'bg-amber-500/10 text-amber-400'
                }`}
              >
                {d.message}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Survey Class selector ── */}
      <div className="flex items-center gap-2">
        <span className="text-[10px] text-[var(--text-muted)] uppercase">Class:</span>
        {(['control', 'urban', 'rural', 'topographic'] as SurveyClass[]).map(cls => (
          <button
            key={cls}
            onClick={() => monitor.setSurveyClass(cls)}
            className={`text-[10px] px-2 py-1 rounded ${
              surveyClass === cls
                ? 'bg-[var(--accent)] text-black font-semibold'
                : 'bg-[var(--bg-tertiary)] text-[var(--text-muted)]'
            }`}
          >
            {cls}
          </button>
        ))}
      </div>
    </div>
  )
}

'use client'

/**
 * StakeoutRadar — Hot/Cold directional guidance for beacon recovery + AR Mode
 *
 * Features:
 * - Radar-style circular display
 * - Augmented Reality (AR) Camera overlay mode
 * - Directional arrow pointing to target
 * - Distance countdown (large, color-coded)
 * - Color shifts: Red (far) → Amber (close) → Green (on target)
 * - Bearing display in DMS
 * - Vibration feedback when within 1m (mobile)
 * - Audio beep that speeds up as you approach
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { Target, Navigation, Crosshair, Volume2, VolumeX, X, Camera, Compass } from 'lucide-react'

interface StakeoutRadarProps {
  targetE: number
  targetN: number
  onClose?: () => void
  epsg?: string
}

interface Position {
  lat: number
  lng: number
  accuracy: number
  easting: number
  northing: number
}

export function StakeoutRadar({ targetE, targetN, onClose, epsg = 'EPSG:21037' }: StakeoutRadarProps) {
  const [position, setPosition] = useState<Position | null>(null)
  const [distance, setDistance] = useState<number | null>(null)
  const [bearing, setBearing] = useState<number | null>(null)
  const [soundOn, setSoundOn] = useState(true)
  const [watching, setWatching] = useState(false)
  
  // AR State
  const [viewMode, setViewMode] = useState<'radar' | 'ar'>('radar')
  const [compassHeading, setCompassHeading] = useState<number | null>(null)
  const [cameraError, setCameraError] = useState<string | null>(null)
  
  const watchIdRef = useRef<number | null>(null)
  const audioCtxRef = useRef<AudioContext | null>(null)
  const lastBeepRef = useRef<number>(0)
  const videoRef = useRef<HTMLVideoElement>(null)
  const streamRef = useRef<MediaStream | null>(null)

  // Transform WGS84 to UTM
  const transformToUTM = useCallback(async (lat: number, lng: number): Promise<{ easting: number; northing: number }> => {
    try {
      const { transform } = await import('ol/proj')
      const [e, n] = transform([lng, lat], 'EPSG:4326', epsg) as [number, number]
      return { easting: e, northing: n }
    } catch {
      return { easting: 0, northing: 0 }
    }
  }, [epsg])

  // GPS Watch
  const startWatch = useCallback(() => {
    if (watching) return
    setWatching(true)
    if (!('geolocation' in navigator)) {
      setWatching(false)
      return
    }
    watchIdRef.current = navigator.geolocation.watchPosition(
      async (pos) => {
        const { easting, northing } = await transformToUTM(pos.coords.latitude, pos.coords.longitude)
        setPosition({
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          accuracy: pos.coords.accuracy,
          easting,
          northing,
        })
        const dE = targetE - easting
        const dN = targetN - northing
        const dist = Math.sqrt(dE * dE + dN * dN)
        let brg = Math.atan2(dE, dN) * 180 / Math.PI
        if (brg < 0) brg += 360

        setDistance(dist)
        setBearing(brg)

        if (soundOn && dist < 10) {
          const now = Date.now()
          const interval = dist < 0.5 ? 200 : dist < 2 ? 500 : 1000
          if (now - lastBeepRef.current > interval) {
            lastBeepRef.current = now
            playBeep(dist < 0.5 ? 880 : dist < 2 ? 660 : 440)
          }
        }
        if (dist < 1 && 'vibrate' in navigator) {
          navigator.vibrate(100)
        }
      },
      () => {},
      { enableHighAccuracy: true, timeout: 5000, maximumAge: 1000 }
    )
  }, [watching, targetE, targetN, transformToUTM, soundOn])

  const stopWatch = useCallback(() => {
    if (watchIdRef.current != null) {
      navigator.geolocation.clearWatch(watchIdRef.current)
      watchIdRef.current = null
    }
    setWatching(false)
  }, [])

  useEffect(() => {
    startWatch()
    return () => stopWatch()
  }, [startWatch, stopWatch])

  const playBeep = useCallback((frequency: number) => {
    if (!soundOn) return
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)()
      }
      const ctx = audioCtxRef.current
      const oscillator = ctx.createOscillator()
      const gainNode = ctx.createGain()
      oscillator.connect(gainNode)
      gainNode.connect(ctx.destination)
      oscillator.frequency.value = frequency
      oscillator.type = 'sine'
      gainNode.gain.setValueAtTime(0.1, ctx.currentTime)
      gainNode.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15)
      oscillator.start(ctx.currentTime)
      oscillator.stop(ctx.currentTime + 0.15)
    } catch {}
  }, [soundOn])

  // --- AR Camera & Compass Integration ---
  
  const handleOrientation = useCallback((e: DeviceOrientationEvent) => {
    let heading = null
    if (typeof (e as any).webkitCompassHeading === 'number') {
      // iOS
      heading = (e as any).webkitCompassHeading
    } else if (e.alpha !== null) {
      // Android
      // Note: DeviceOrientationEvent uses alpha = 0 for North (if absolute) in some specs, 
      // but commonly compass heading is 360 - alpha.
      heading = 360 - e.alpha
      if (heading === 360) heading = 0
    }
    if (heading !== null) {
      setCompassHeading(heading)
    }
  }, [])

  const startAR = async () => {
    setCameraError(null)
    
    // 1. Camera
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' }
      })
      streamRef.current = stream
      if (videoRef.current) {
        videoRef.current.srcObject = stream
      }
    } catch (err) {
      setCameraError('Camera access denied or unavailable.')
      return
    }

    // 2. Compass
    try {
      if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
        const permissionState = await (DeviceOrientationEvent as any).requestPermission()
        if (permissionState === 'granted') {
          window.addEventListener('deviceorientation', handleOrientation, true)
        } else {
          setCameraError('Compass access denied.')
        }
      } else {
        window.addEventListener('deviceorientationabsolute', handleOrientation, true)
        // Fallback for non-absolute browsers
        window.addEventListener('deviceorientation', handleOrientation, true)
      }
    } catch (err) {
      setCameraError('Compass not supported on this device.')
    }
  }

  const stopAR = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop())
      streamRef.current = null
    }
    window.removeEventListener('deviceorientationabsolute', handleOrientation, true)
    window.removeEventListener('deviceorientation', handleOrientation, true)
  }

  const toggleViewMode = () => {
    if (viewMode === 'radar') {
      setViewMode('ar')
      startAR()
    } else {
      setViewMode('radar')
      stopAR()
    }
  }

  // Cleanup AR on unmount
  useEffect(() => {
    return () => {
      stopAR()
    }
  }, [handleOrientation])

  // --- Rendering ---
  
  const getColor = (dist: number | null) => {
    if (dist == null) return { ring: '#6b7280', text: 'text-gray-400', bg: 'bg-gray-500/10' }
    if (dist < 0.1) return { ring: '#10b981', text: 'text-emerald-400', bg: 'bg-emerald-500/10' }
    if (dist < 0.5) return { ring: '#10b981', text: 'text-emerald-400', bg: 'bg-emerald-500/10' }
    if (dist < 2) return { ring: '#84cc16', text: 'text-lime-400', bg: 'bg-lime-500/10' }
    if (dist < 5) return { ring: '#eab308', text: 'text-amber-400', bg: 'bg-amber-500/10' }
    if (dist < 15) return { ring: '#f97316', text: 'text-orange-400', bg: 'bg-orange-500/10' }
    return { ring: '#ef4444', text: 'text-red-400', bg: 'bg-red-500/10' }
  }

  const colors = getColor(distance)
  const isOnTarget = distance != null && distance < 0.5

  const formatBearing = (brg: number) => {
    const deg = Math.floor(brg)
    const minFull = (brg - deg) * 60
    const min = Math.floor(minFull)
    const sec = (minFull - min) * 60
    return `${deg}°${min}'${sec.toFixed(0)}"`
  }

  // Calculate AR target X position (-50vw to +50vw)
  // Assuming 60 degrees horizontal field of view
  let arTargetLeft = '50%'
  let arTargetVisible = false
  if (bearing != null && compassHeading != null) {
    let diff = bearing - compassHeading
    if (diff > 180) diff -= 360
    if (diff < -180) diff += 360
    
    if (Math.abs(diff) < 90) {
      arTargetVisible = true
      // Linear mapping: 30 degrees = 50vw offset
      const offsetVw = (diff / 30) * 50
      arTargetLeft = `calc(50% + ${offsetVw}vw)`
    }
  }

  // Scale target marker by distance (closer = bigger)
  let arScale = 1
  if (distance != null && distance > 0) {
    arScale = Math.max(0.2, Math.min(2.0, 10 / distance))
  }

  return (
    <div className={`fixed inset-0 z-[9999] flex flex-col items-center justify-center p-4 overflow-hidden ${viewMode === 'radar' ? 'bg-[#0a0a0f]' : 'bg-black'}`}>
      
      {/* AR Video Background */}
      {viewMode === 'ar' && (
        <div className="absolute inset-0 overflow-hidden">
          <video 
            ref={videoRef}
            autoPlay 
            playsInline 
            muted 
            className="absolute inset-0 w-full h-full object-cover opacity-80"
          />
          {cameraError && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/80 p-8 text-center text-red-400">
              {cameraError}
            </div>
          )}
        </div>
      )}

      {/* AR Target Marker */}
      {viewMode === 'ar' && !cameraError && (
        <div className="absolute inset-0 pointer-events-none">
          {arTargetVisible ? (
            <div 
              className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 transition-all duration-75 ease-linear"
              style={{ 
                left: arTargetLeft, 
                transform: `translate(-50%, -50%) scale(${arScale})` 
              }}
            >
              <div className="flex flex-col items-center drop-shadow-xl">
                <Target className="w-16 h-16 transition-colors duration-300 animate-pulse" style={{ color: colors.ring }} />
                <div className="mt-2 px-3 py-1 rounded bg-black/60 backdrop-blur text-white font-mono text-xl font-bold border border-white/20">
                  {distance?.toFixed(2)}m
                </div>
              </div>
            </div>
          ) : (
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-white/50 bg-black/40 px-4 py-2 rounded-full backdrop-blur-md">
              Turn towards target...
            </div>
          )}
        </div>
      )}

      {/* Header */}
      <div className="absolute top-4 left-4 right-4 flex items-center justify-between z-10">
        <div className="flex items-center gap-2 bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10">
          <Target className="w-4 h-4 text-[#D17B47]" />
          <span className="text-sm font-semibold text-white">
            {viewMode === 'radar' ? 'Stakeout Radar' : 'AR Stakeout'}
          </span>
        </div>
        <div className="flex items-center gap-2">
          {/* View Toggle */}
          <button
            onClick={toggleViewMode}
            className="w-10 h-10 flex items-center justify-center rounded-full bg-black/40 backdrop-blur-md border border-white/10 text-gray-300 hover:text-white transition-all hover:bg-white/10"
            title={viewMode === 'radar' ? 'Switch to AR Camera' : 'Switch to 2D Radar'}
          >
            {viewMode === 'radar' ? <Camera className="w-4 h-4" /> : <Compass className="w-4 h-4" />}
          </button>
          
          <button
            onClick={() => setSoundOn(!soundOn)}
            className="w-10 h-10 flex items-center justify-center rounded-full bg-black/40 backdrop-blur-md border border-white/10 text-gray-300 hover:text-white transition-all hover:bg-white/10"
          >
            {soundOn ? <Volume2 className="w-4 h-4" /> : <VolumeX className="w-4 h-4" />}
          </button>
          
          {onClose && (
            <button
              onClick={onClose}
              className="w-10 h-10 flex items-center justify-center rounded-full bg-red-500/20 backdrop-blur-md border border-red-500/30 text-red-400 hover:bg-red-500/40 hover:text-red-300 transition-all"
            >
              <X className="w-5 h-5" />
            </button>
          )}
        </div>
      </div>

      {/* 2D Radar display */}
      {viewMode === 'radar' && (
        <div className="relative w-72 h-72 mb-8 z-10">
          <div className="absolute inset-0 rounded-full border-2 transition-colors duration-300" style={{ borderColor: colors.ring, opacity: 0.3 }} />
          <div className="absolute inset-8 rounded-full border transition-colors duration-300" style={{ borderColor: colors.ring, opacity: 0.2 }} />
          <div className="absolute inset-16 rounded-full border transition-colors duration-300" style={{ borderColor: colors.ring, opacity: 0.4 }} />
          <div className="absolute top-1/2 left-0 right-0 h-px" style={{ backgroundColor: colors.ring, opacity: 0.2 }} />
          <div className="absolute left-1/2 top-0 bottom-0 w-px" style={{ backgroundColor: colors.ring, opacity: 0.2 }} />
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
            <div className={`w-4 h-4 rounded-full ${isOnTarget ? 'animate-ping' : ''}`} style={{ backgroundColor: colors.ring }} />
          </div>
          {bearing != null && (
            <div className="absolute top-1/2 left-1/2 origin-bottom" style={{ transform: `translate(-50%, -100%) rotate(${bearing}deg)`, height: '50%' }}>
              <div className="flex flex-col items-center">
                <Navigation className="w-8 h-8 transition-colors duration-300" style={{ color: colors.ring }} fill="currentColor" />
              </div>
            </div>
          )}
          <div className="absolute top-1 left-1/2 -translate-x-1/2 text-[10px] font-bold text-gray-500">N</div>
          <div className="absolute bottom-1 left-1/2 -translate-x-1/2 text-[10px] font-bold text-gray-500">S</div>
          <div className="absolute left-1 top-1/2 -translate-y-1/2 text-[10px] font-bold text-gray-500">W</div>
          <div className="absolute right-1 top-1/2 -translate-y-1/2 text-[10px] font-bold text-gray-500">E</div>
        </div>
      )}

      {/* Distance display (bottom center) */}
      <div className={`absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center z-10 ${viewMode === 'ar' ? 'bg-black/40 backdrop-blur-xl px-8 py-4 rounded-3xl border border-white/10' : ''}`}>
        <div className={`text-6xl font-bold font-mono ${colors.text} transition-colors duration-300`}>
          {distance != null ? distance.toFixed(2) : '—'}
        </div>
        <div className="text-xs text-gray-400 mt-1 uppercase tracking-widest font-semibold">Meters to target</div>
        
        {bearing != null && (
          <div className="flex items-center gap-2 mt-4 text-gray-300 bg-white/5 px-3 py-1.5 rounded-lg border border-white/10">
            <Crosshair className="w-4 h-4 opacity-50" />
            <span className="text-sm font-mono">Bearing: {formatBearing(bearing)}</span>
            {compassHeading != null && (
              <span className="text-sm font-mono ml-2 border-l border-white/20 pl-3">HDG: {Math.round(compassHeading)}°</span>
            )}
          </div>
        )}

        <div className={`mt-4 px-4 py-2 rounded-xl ${colors.bg} border ${colors.text} border-current/20 backdrop-blur-md w-full`}>
          <p className="text-sm font-medium text-center">
            {isOnTarget ? 'ON TARGET — Dig here!' :
             distance == null ? 'Waiting for GPS...' :
             distance < 2 ? 'Almost there — slow down' :
             distance < 5 ? 'Getting close' :
             distance < 15 ? 'Approaching target' :
             'Follow the beacon'}
          </p>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * TopologyGuardrail — Real-time topology validation UI for cadastral surveys
 *
 * Displays topology issues as they're detected during parcel drawing.
 * Shows:
 * - Error count and warning count badges
 * - Expandable list of issues with severity colors
 * - Map highlight integration (passes issue coordinates back to parent)
 *
 * Integrates with:
 * - lib/survey/topologyChecker.ts (the validation engine)
 * - Map drawing interactions (parent passes drawn vertices)
 * - Existing parcel data (parent passes neighboring parcels)
 */

import { useState, useEffect, useCallback, useMemo } from 'react'
import {
  AlertTriangle, AlertCircle, Info, CheckCircle2,
  ChevronDown, ChevronUp, MapPin, ShieldAlert, ShieldCheck,
} from 'lucide-react'
import {
  runTopologyCheck,
  type TopologyIssue,
  type TopologyCheckResult,
  type ExistingParcel,
  type RoadReserve,
} from '@/lib/survey/topologyChecker'
import type { SurveyPoint } from '@/lib/map/turfHelpers'

interface TopologyGuardrailProps {
  /** Vertices of the parcel currently being drawn/edited */
  vertices: SurveyPoint[]
  /** Existing neighboring parcels to check against */
  existingParcels?: ExistingParcel[]
  /** Road reserves to check encroachment against */
  roadReserves?: RoadReserve[]
  /** Beacon positions (for duplicate detection) */
  beacons?: SurveyPoint[]
  /** Called when issues are detected — parent can highlight on map */
  onIssuesChange?: (issues: TopologyIssue[]) => void
  /** Whether to show the panel expanded by default */
  defaultExpanded?: boolean
  /** Compact mode (for inline display) */
  compact?: boolean
}

const SEVERITY_CONFIG = {
  error: {
    icon: AlertCircle,
    color: 'text-red-400',
    bg: 'bg-red-500/10',
    border: 'border-red-500/30',
    label: 'Error',
  },
  warning: {
    icon: AlertTriangle,
    color: 'text-amber-400',
    bg: 'bg-amber-500/10',
    border: 'border-amber-500/30',
    label: 'Warning',
  },
  info: {
    icon: Info,
    color: 'text-blue-400',
    bg: 'bg-blue-500/10',
    border: 'border-blue-500/30',
    label: 'Info',
  },
}

const ISSUE_TYPE_LABELS: Record<string, string> = {
  overlap: 'Parcel Overlap',
  sliver: 'Sliver Gap',
  self_intersection: 'Self-Intersection',
  road_encroachment: 'Road Reserve',
  duplicate_beacon: 'Duplicate Beacon',
  unclosed_polygon: 'Unclosed Polygon',
  insufficient_vertices: 'Insufficient Vertices',
}

export function TopologyGuardrail({
  vertices,
  existingParcels = [],
  roadReserves = [],
  beacons = [],
  onIssuesChange,
  defaultExpanded = true,
  compact = false,
}: TopologyGuardrailProps) {
  const [result, setResult] = useState<TopologyCheckResult | null>(null)
  const [expanded, setExpanded] = useState(defaultExpanded)
  const [checking, setChecking] = useState(false)

  // Run topology check when vertices change (debounced)
  useEffect(() => {
    if (vertices.length < 2) {
      setResult(null)
      onIssuesChange?.([])
      return
    }

    setChecking(true)
    const timer = setTimeout(async () => {
      try {
        const checkResult = await runTopologyCheck({
          newVertices: vertices,
          existingParcels,
          roadReserves,
          beacons,
        })
        setResult(checkResult)
        onIssuesChange?.(checkResult.issues)
      } catch (err) {
        console.error('[TopologyGuardrail] Check failed:', err)
      } finally {
        setChecking(false)
      }
    }, 300) // 300ms debounce

    return () => clearTimeout(timer)
  }, [vertices, existingParcels, roadReserves, beacons, onIssuesChange])

  const errorCount = useMemo(
    () => result?.issues.filter(i => i.severity === 'error').length ?? 0,
    [result]
  )
  const warningCount = useMemo(
    () => result?.issues.filter(i => i.severity === 'warning').length ?? 0,
    [result]
  )

  // Don't render if no vertices or all clear
  if (vertices.length < 2) {
    return null
  }

  if (result && result.issues.length === 0 && !checking) {
    return (
      <div className={`rounded-xl border border-emerald-500/30 bg-emerald-500/5 p-3 ${compact ? '' : 'p-4'}`}>
        <div className="flex items-center gap-2">
          <ShieldCheck className="w-4 h-4 text-emerald-400 shrink-0" />
          <span className="text-sm text-emerald-400 font-medium">Topology Valid</span>
        </div>
        {!compact && (
          <p className="text-[11px] text-emerald-400/70 mt-1">
            No overlaps, slivers, or encroachments detected. Safe for registry submission.
          </p>
        )}
      </div>
    )
  }

  return (
    <div className={`rounded-xl border ${errorCount > 0 ? 'border-red-500/30 bg-red-500/5' : 'border-amber-500/30 bg-amber-500/5'} overflow-hidden`}>
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-white/[0.02] transition-colors"
      >
        <div className="flex items-center gap-2">
          {errorCount > 0 ? (
            <ShieldAlert className="w-4 h-4 text-red-400 shrink-0" />
          ) : (
            <AlertTriangle className="w-4 h-4 text-amber-400 shrink-0" />
          )}
          <span className={`text-sm font-medium ${errorCount > 0 ? 'text-red-400' : 'text-amber-400'}`}>
            Topology Issues
          </span>
          {checking && (
            <span className="text-[10px] text-gray-500 animate-pulse">checking...</span>
          )}
        </div>
        <div className="flex items-center gap-1.5">
          {errorCount > 0 && (
            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-red-500/15 text-red-400 border border-red-500/30">
              <AlertCircle className="w-3 h-3" />
              {errorCount}
            </span>
          )}
          {warningCount > 0 && (
            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-amber-500/15 text-amber-400 border border-amber-500/30">
              <AlertTriangle className="w-3 h-3" />
              {warningCount}
            </span>
          )}
          {expanded ? <ChevronUp className="w-3.5 h-3.5 text-gray-500" /> : <ChevronDown className="w-3.5 h-3.5 text-gray-500" />}
        </div>
      </button>

      {/* Issue list */}
      {expanded && result && (
        <div className="border-t border-white/[0.06] max-h-[300px] overflow-y-auto">
          {result.issues.map((issue, idx) => {
            const cfg = SEVERITY_CONFIG[issue.severity]
            const Icon = cfg.icon
            return (
              <div
                key={issue.id || idx}
                className={`px-3 py-2.5 border-b border-white/[0.04] last:border-b-0 ${cfg.bg}`}
              >
                <div className="flex items-start gap-2">
                  <Icon className={`w-3.5 h-3.5 ${cfg.color} shrink-0 mt-0.5`} />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className={`text-xs font-medium ${cfg.color}`}>
                        {ISSUE_TYPE_LABELS[issue.type] || issue.type}
                      </span>
                    </div>
                    <p className="text-xs text-gray-300 mt-0.5">{issue.message}</p>
                    {issue.details && (
                      <p className="text-[10px] text-gray-500 mt-1 leading-relaxed">{issue.details}</p>
                    )}
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      )}

      {/* Footer summary */}
      {!compact && expanded && result && (
        <div className="px-3 py-2 border-t border-white/[0.06] bg-[#0d0d14]/40">
          <p className="text-[10px] text-gray-500">
            {result.isValid
              ? 'No blocking errors — parcel can be saved.'
              : `${errorCount} error(s) must be fixed before registry submission.`}
          </p>
        </div>
      )}
    </div>
  )
}

'use client';

import { useState, useEffect, useCallback, useMemo, useRef } from 'react'
import { createClient } from '@/lib/api-client/client'
import { sanitizeHtml } from '@/lib/security/sanitize'
import { usePrint, PrintButton, PrintHeader } from '@/hooks/usePrint'
import { buildSubmissionNumber, normaliseRegistrationNo, validateSubmissionNumber } from '@/lib/submission/format'
import { z } from 'zod'
import { apiPost, ApiError } from '@/lib/api/client'
// import { PHASE13_DEMO_PROJECTS } from '@/lib/standards/rdm11'
import type { 
  SurveyReportInput, 
  SectionContent, 
  ReportSection,
  ReportCompletenessResult,
  EquipmentItem,
  PersonnelItem,
  ControlPoint
} from '@/types/surveyReport'

interface SurveyReportBuilderProps {
  projectId: string
  existingReportId?: string
}

const SECTION_INFO: { section: ReportSection; number: number; title: string; autoGenerated: boolean }[] = [
  { section: 'TITLE_PAGE', number: 1, title: 'Title Page', autoGenerated: false },
  { section: 'TABLE_OF_CONTENTS', number: 2, title: 'Table of Contents', autoGenerated: true },
  { section: 'INTRODUCTION', number: 3, title: 'Introduction', autoGenerated: false },
  { section: 'SCOPE_OF_WORK', number: 4, title: 'Scope of Work', autoGenerated: false },
  { section: 'EQUIPMENT_AND_PERSONNEL', number: 5, title: 'Equipment and Personnel', autoGenerated: false },
  { section: 'CONTROL_SURVEY', number: 6, title: 'Control Survey', autoGenerated: false },
  { section: 'TOPOGRAPHIC_SURVEY', number: 7, title: 'Topographic Survey', autoGenerated: false },
  { section: 'DATA_PROCESSING', number: 8, title: 'Data Processing', autoGenerated: true },
  { section: 'RESULTS_AND_ACCURACY', number: 9, title: 'Results and Accuracy', autoGenerated: false },
  { section: 'COORDINATE_REGISTER', number: 10, title: 'Coordinate Register', autoGenerated: true },
  { section: 'BENCHMARK_REGISTER', number: 11, title: 'Benchmark Register', autoGenerated: true },
  { section: 'TRAVERSE_COMPUTATIONS', number: 12, title: 'Traverse Computations', autoGenerated: true },
  { section: 'LEVELLING_COMPUTATIONS', number: 13, title: 'Levelling Computations', autoGenerated: true },
  { section: 'CONCLUSIONS_AND_RECOMMENDATIONS', number: 14, title: 'Conclusions and Recommendations', autoGenerated: false },
  { section: 'DECLARATION', number: 15, title: 'Surveyor\'s Declaration', autoGenerated: false },
]

const DEFAULT_SCOPE_ITEMS = [
  'Establishment of survey control network',
  'Topographic survey of the project area',
  'Traverse computation and adjustment',
  'Levelling and reduced levels',
  'Survey plan production per Survey Regulations 1994',
  'Survey report per RDM 1.1 Table 5.4'
]

// ─── API response schemas (Zod) ────────────────────────────────────────────
const generateReportResponseSchema = z.object({
  sections: z.array(z.object({}).passthrough()),
  completeness: z.object({}).passthrough(),
  input: z.object({}).passthrough(),
}).passthrough()

const saveReportResponseSchema = z.object({
  id: z.string().optional(),
  saved: z.boolean().optional(),
  created: z.boolean().optional(),
}).passthrough()

export default function SurveyReportBuilder({ projectId, existingReportId }: SurveyReportBuilderProps) {
  const [activeSection, setActiveSection] = useState<ReportSection>('TITLE_PAGE')
  const [reportInput, setReportInput] = useState<Partial<SurveyReportInput>>({})
  const [generatedSections, setGeneratedSections] = useState<SectionContent[]>([])
  const [completeness, setCompleteness] = useState<ReportCompletenessResult | null>(null)
  const [mode, setMode] = useState<'edit' | 'preview'>('edit')
  const [isSaving, setIsSaving] = useState(false)
  const [isGenerating, setIsGenerating] = useState(false)
  const [isDirty, setIsDirty] = useState(false)
  const [reportId, setReportId] = useState(existingReportId || '')
  const [error, setError] = useState<string | null>(null)
  const [editingAutoSection, setEditingAutoSection] = useState<string | null>(null)
  const [autoSectionDraft, setAutoSectionDraft] = useState('')
  const { print, isPrinting, paperSize, setPaperSize, orientation, setOrientation } = usePrint({ title: 'Survey Report' })

  const dbClient = createClient()

  const generateReport = useCallback(async (input: Partial<SurveyReportInput>) => {
    setIsGenerating(true)
    setError(null)
    try {
      const data = await apiPost(
        '/api/survey-report/generate',
        generateReportResponseSchema,
        { projectId, input }
      )
      setReportInput(data.input as Partial<SurveyReportInput>)
      setGeneratedSections(data.sections as unknown as SectionContent[])
      setCompleteness(data.completeness as unknown as ReportCompletenessResult)
      setIsDirty(false)
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message)
      } else {
        setError(err instanceof Error ? err.message : 'Generation failed')
      }
    } finally {
      setIsGenerating(false)
    }
  }, [projectId])

  const loadReport = useCallback(async () => {
    if (existingReportId) {
      try {
        const { getSurveyReportById } = await import('@/lib/api-client/surveyReports')
        const report = await getSurveyReportById(existingReportId)
        if (report) {
          setReportInput({
            ...report,
            projectId
          } as SurveyReportInput)
          setGeneratedSections(report.sections)
          setReportId(existingReportId)
          // Reconstruct completeness from saved data so auto-save works
          const savedPercent = report.completeness || 0
          setCompleteness({
            overallPercent: savedPercent,
            sectionsComplete: report.sections?.filter((s: any) => s.completeness >= 100).length || 0,
            sectionsIncomplete: report.sections?.filter((s: any) => s.completeness < 100).map((s: any) => ({
              section: s.section,
              sectionNumber: s.sectionNumber,
              missingFields: [],
              completeness: s.completeness,
            })) || [],
            readyToFinalise: savedPercent >= 100,
          })
          return
        }
      } catch (err) {
        console.error('Failed to load report:', err)
      }
    }
    // Only generate fresh report when creating new (no existingReportId)
    await generateReport({ projectId } as SurveyReportInput)
  }, [existingReportId, projectId, generateReport])

  useEffect(() => {
    loadReport()
  }, [loadReport])

  const saveReport = useCallback(async () => {
    if (!completeness) return
    
    setIsSaving(true)
    try {
      const data = await apiPost(
        '/api/survey-report/save',
        saveReportResponseSchema,
        {
          reportId: reportId || undefined,
          projectId,
          input: reportInput,
          sections: generatedSections,
          completeness: completeness.overallPercent
        }
      )
      if (data.id) {
        setReportId(data.id)
      }
      setIsDirty(false)
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message)
      } else {
        setError(err instanceof Error ? err.message : 'Save failed')
      }
    } finally {
      setIsSaving(false)
    }
  }, [completeness, reportId, projectId, reportInput, generatedSections])

  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null)

  useEffect(() => {
    if (isDirty && reportInput.projectId && completeness) {
      if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current)
      saveTimeoutRef.current = setTimeout(() => {
        saveReport().catch(() => {})
      }, 2000)
    }
    return () => {
      if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current)
    }
  }, [reportInput, generatedSections, isDirty, saveReport, completeness])

  const updateInput = (field: keyof SurveyReportInput, value: any) => {
    setReportInput(prev => ({ ...prev, [field]: value }))
    setIsDirty(true)
  }

  // Demo removed — function no longer needed

  const DEFAULT_DECLARATION = `I, the undersigned, being a Registered Surveyor under the Survey Act (Cap. 299), do hereby declare that:

1. The survey described in this report was carried out under my direct supervision in accordance with the Survey Act (Cap. 299), the Survey Regulations 1994, and the Road Design Manual Part 1 (RDM 1.1, 2025).

2. All field observations, computations, and plans contained herein are accurate and correct to the best of my knowledge and professional belief.

3. The instruments used were in proper adjustment and calibrated within the period specified by the manufacturer and applicable standards.

4. The coordinates, levels, and areas stated in this report have been computed and checked, and are fit for the purpose described in Section 4 (Scope of Work).

Signed: ___________________________    Date: _______________

Name: ___________________________    ISK No: _______________

Firm: ___________________________    Stamp: _______________`

  const exportReport = async (format: 'pdf' | 'docx') => {
    if (!reportId) {
      await saveReport()
    }
    
    try {
      // ponytail: binary download bypasses typed client
      const response = await fetch('/api/survey-report/export', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reportId: reportId || existingReportId, format })
      })
      
      if (!response.ok) {
        throw new Error('Export failed')
      }
      
      const blob = await response.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `${reportInput.reportNumber || 'survey_report'}.${format}`
      a.click()
      URL.revokeObjectURL(url)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Export failed')
    }
  }

  const getCompletenessForSection = (section: ReportSection): number => {
    if (!completeness) return 0
    const gap = completeness.sectionsIncomplete.find((g: any) => g.section === section)
    return gap ? gap.completeness : 100
  }

  const isSectionComplete = (section: ReportSection): boolean => {
    return getCompletenessForSection(section) >= 100
  }

  const getSectionBadge = (info: typeof SECTION_INFO[0]) => {
    if (info.autoGenerated) {
      return <span className="text-[10px] px-1.5 py-0.5 bg-gray-200 text-gray-600 rounded">AUTO</span>
    }
    const comp = getCompletenessForSection(info.section)
    if (comp >= 100) {
      return <span className="w-2 h-2 bg-green-500 rounded-full" />
    } else if (comp >= 50) {
      return <span className="w-2 h-2 bg-amber-500 rounded-full" />
    } else {
      return <span className="w-2 h-2 bg-red-500 rounded-full" />
    }
  }

  const renderSectionForm = () => {
    const sectionInfo = SECTION_INFO.find((s: any) => s.section === activeSection)
    if (!sectionInfo) return null

    if (sectionInfo.autoGenerated) {
      const section = generatedSections.find((s: any) => s.section === activeSection)
      const isEditing = editingAutoSection === activeSection

      const startEditing = () => {
        setEditingAutoSection(activeSection)
        // Strip HTML tags for textarea editing
        const raw = section?.content?.replace(/<[^>]*>/g, '\n').replace(/\n{3,}/g, '\n\n').trim() || ''
        setAutoSectionDraft(raw)
      }

      const saveEditing = () => {
        if (!section) return
        const updated = generatedSections.map((s: any) =>
          s.section === activeSection
            ? { ...s, content: autoSectionDraft.split('\n').filter((l: string) => l.trim()).map((l: string) => `<p>${l}</p>`).join('') }
            : s
        )
        setGeneratedSections(updated)
        setEditingAutoSection(null)
        setAutoSectionDraft('')
        setIsDirty(true)
      }

      const cancelEditing = () => {
        setEditingAutoSection(null)
        setAutoSectionDraft('')
      }

      return (
        <div className="space-y-4">
          <div className="bg-gray-50 border border-gray-200 rounded-lg p-4 text-sm text-gray-600">
            <p className="flex items-center gap-2">
              <span>(i)</span>
              This section is auto-generated from your project data.
            </p>
          </div>
          {isEditing ? (
            <div className="space-y-3">
              <textarea
                value={autoSectionDraft}
                onChange={e => setAutoSectionDraft(e.target.value)}
                rows={20}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm font-mono"
                placeholder="Edit section content..."
              />
              <div className="flex gap-2">
                <button
                  onClick={saveEditing}
                  className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium"
                >
                  Save Changes
                </button>
                <button
                  onClick={cancelEditing}
                  className="px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                >
                  Cancel
                </button>
              </div>
            </div>
          ) : (
            <div
              className="bg-gray-50 border border-gray-200 rounded-lg p-6 prose prose-sm max-w-none"
              dangerouslySetInnerHTML={{ __html: sanitizeHtml(section?.content || '<p class="text-gray-400">No content generated yet. Click Regenerate to populate this section.</p>') }}
            />
          )}
          <div className="flex gap-2">
            {!isEditing && (
              <button
                onClick={startEditing}
                className="px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm font-medium hover:border-[var(--accent)]"
              >
                Edit Content
              </button>
            )}
            <button
              onClick={() => generateReport(reportInput as SurveyReportInput)}
              disabled={isGenerating}
              className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium disabled:opacity-50"
            >
              {isGenerating ? 'Regenerating...' : 'Regenerate'}
            </button>
          </div>
        </div>
      )
    }

    switch (activeSection) {
      case 'TITLE_PAGE':
        return (
          <div className="space-y-4">
            <div>
              <label htmlFor="sr-report-title" className="block text-sm font-medium mb-1">Report Title</label>
              <input
                id="sr-report-title"
                type="text"
                value={reportInput.reportTitle || ''}
                onChange={e => updateInput('reportTitle', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="Topographic Survey Report"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-report-number" className="block text-sm font-medium mb-1">Report Number</label>
                <input id="sr-report-number"
                  type="text"
                  value={reportInput.reportNumber || ''}
                  onChange={e => updateInput('reportNumber', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-revision" className="block text-sm font-medium mb-1">Revision</label>
                <input id="sr-revision"
                  type="text"
                  value={reportInput.revisionNumber || 'Rev 0'}
                  onChange={e => updateInput('revisionNumber', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-submission-number" className="block text-sm font-medium mb-1">Submission Number (SRVY2025-1)</label>
              <div className="flex gap-2">
                <input
                  id="sr-submission-number"
                  type="text"
                  value={reportInput.submissionNumber || ''}
                  onChange={e => updateInput('submissionNumber', e.target.value.toUpperCase())}
                  className={`flex-1 px-3 py-2 bg-[var(--bg-tertiary)] border rounded-lg text-sm font-mono ${
                    reportInput.submissionNumber && !validateSubmissionNumber(reportInput.submissionNumber)
                      ? 'border-red-500'
                      : 'border-[var(--border-color)]'
                  }`}
                  aria-label="RS149_2026_001_R00" placeholder="RS149_2026_001_R00"
                />
                <button
                  onClick={() => {
                    const reg = normaliseRegistrationNo(reportInput.surveyorRegistrationNumber || 'RS149')
                    updateInput('submissionNumber', buildSubmissionNumber({
                      registrationNo: reg,
                      year: new Date().getFullYear(),
                      sequence: 1,
                      revision: 0,
                    }))
                  }}
                  className="px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs"
                >
                  Generate
                </button>
              </div>
              <p className="text-xs text-gray-500 mt-1">Format: registration_year_sequence_revision, e.g. RS149_2026_002_R00.</p>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-client-name" className="block text-sm font-medium mb-1">Client Name</label>
                <input id="sr-client-name"
                  type="text"
                  value={reportInput.clientName || ''}
                  onChange={e => updateInput('clientName', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-report-date" className="block text-sm font-medium mb-1">Report Date</label>
                <input id="sr-report-date"
                  type="date"
                  value={reportInput.reportDate || ''}
                  onChange={e => updateInput('reportDate', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-client-address" className="block text-sm font-medium mb-1">Client Address</label>
              <textarea
                id="sr-client-address"
                value={reportInput.clientAddress || ''}
                onChange={e => updateInput('clientAddress', e.target.value)}
                rows={2}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-firm-name" className="block text-sm font-medium mb-1">Firm Name</label>
                <input id="sr-firm-name"
                  type="text"
                  value={reportInput.firmName || ''}
                  onChange={e => updateInput('firmName', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-firm-isk" className="block text-sm font-medium mb-1">ISK Number</label>
                <input id="sr-firm-isk"
                  type="text"
                  value={reportInput.firmIskNumber || ''}
                  onChange={e => updateInput('firmIskNumber', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-surveyor-name" className="block text-sm font-medium mb-1">Surveyor Name</label>
                <input id="sr-surveyor-name"
                  type="text"
                  value={reportInput.surveyorName || ''}
                  onChange={e => updateInput('surveyorName', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-surveyor-isk" className="block text-sm font-medium mb-1">Surveyor ISK Number</label>
                <input id="sr-surveyor-isk"
                  type="text"
                  value={reportInput.surveyorIskNumber || ''}
                  onChange={e => updateInput('surveyorIskNumber', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-surveyor-reg" className="block text-sm font-medium mb-1">Surveyor Registration Number</label>
              <input
                id="sr-surveyor-reg"
                type="text"
                value={reportInput.surveyorRegistrationNumber || ''}
                onChange={e => updateInput('surveyorRegistrationNumber', normaliseRegistrationNo(e.target.value))}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm font-mono"
                placeholder="RS149"
              />
            </div>
          </div>
        )

      case 'INTRODUCTION':
        return (
          <div className="space-y-4">
            <div>
              <label htmlFor="sr-project-location" className="block text-sm font-medium mb-1">Project Location</label>
              <input
                id="sr-project-location"
                type="text"
                value={reportInput.projectLocation || ''}
                onChange={e => updateInput('projectLocation', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="e.g., Kiserian, Kajiado County"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-county" className="block text-sm font-medium mb-1">County</label>
                <input id="sr-county"
                  type="text"
                  value={reportInput.county || ''}
                  onChange={e => updateInput('county', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-constituency" className="block text-sm font-medium mb-1">Constituency (optional)</label>
                <input id="sr-constituency"
                  type="text"
                  value={reportInput.constituency || ''}
                  onChange={e => updateInput('constituency', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-project-purpose" className="block text-sm font-medium mb-1">Project Purpose</label>
              <textarea
                id="sr-project-purpose"
                value={reportInput.projectPurpose || ''}
                onChange={e => updateInput('projectPurpose', e.target.value)}
                rows={4}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="Describe why this survey was commissioned..."
              />
            </div>
            <div>
              <label htmlFor="sr-site-description" className="block text-sm font-medium mb-1">Site Description</label>
              <textarea
                id="sr-site-description"
                value={reportInput.siteDescription || ''}
                onChange={e => updateInput('siteDescription', e.target.value)}
                rows={4}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="Describe terrain, land use, vegetation, access..."
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-survey-start" className="block text-sm font-medium mb-1">Survey Start Date</label>
                <input id="sr-survey-start"
                  type="date"
                  value={reportInput.surveyPeriodStart || ''}
                  onChange={e => updateInput('surveyPeriodStart', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
              <div>
                <label htmlFor="sr-survey-end" className="block text-sm font-medium mb-1">Survey End Date</label>
                <input id="sr-survey-end"
                  type="date"
                  value={reportInput.surveyPeriodEnd || ''}
                  onChange={e => updateInput('surveyPeriodEnd', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
          </div>
        )

      case 'SCOPE_OF_WORK':
        return (
          <div className="space-y-4">
            <div className="block text-sm font-medium mb-1">Scope Items</div>
            {(reportInput.scopeItems || []).map((item, idx) => (
              <div key={`${item}-${idx}`} className="flex gap-2">
                <input aria-label={`Scope item ${idx + 1}`}
                  type="text"
                  value={item}
                  onChange={e => {
                    const newItems = [...(reportInput.scopeItems || [])]
                    newItems[idx] = e.target.value
                    updateInput('scopeItems', newItems)
                  }}
                  className="flex-1 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
                <button
                  onClick={() => {
                    const newItems = (reportInput.scopeItems || []).filter((_, i) => i !== idx)
                    updateInput('scopeItems', newItems)
                  }}
                  className="px-3 py-2 text-red-500 hover:bg-red-50 rounded-lg text-sm"
                >
                  Remove
                </button>
              </div>
            ))}
            <button
              onClick={() => updateInput('scopeItems', [...(reportInput.scopeItems || []), ''])}
              className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium"
            >
              + Add Scope Item
            </button>
          </div>
        )

      case 'EQUIPMENT_AND_PERSONNEL':
        return (
          <div className="space-y-6">
            <div>
              <h4 className="text-sm font-medium mb-2">Equipment</h4>
              {(reportInput.equipment || []).map((eq, idx) => (
                <div key={`${eq}-${idx}`} className="grid grid-cols-6 gap-2 mb-2">
                  <input
                    type="text"
                    aria-label="Equipment Type" placeholder="e.g. Total Station"
                    value={eq.type}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], type: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Make" placeholder="e.g. Leica"
                    value={eq.make}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], make: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Serial No" placeholder="e.g. SN-12345"
                    value={eq.serialNumber}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], serialNumber: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input aria-label="Calibration Date"
                    type="date"
                    value={eq.calibrationDate}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], calibrationDate: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Cert No" placeholder="e.g. CERT-2026-01"
                    value={eq.calibrationCert}
                    onChange={e => {
                      const newEq = [...(reportInput.equipment || [])]
                      newEq[idx] = { ...newEq[idx], calibrationCert: e.target.value }
                      updateInput('equipment', newEq)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <button
                    onClick={() => {
                      const newEq = (reportInput.equipment || []).filter((_, i) => i !== idx)
                      updateInput('equipment', newEq)
                    }}
                    className="text-red-500 text-xs"
                  >
                    [x]
                  </button>
                </div>
              ))}
              <button
                onClick={() => updateInput('equipment', [...(reportInput.equipment || []), { type: '', make: '', serialNumber: '', calibrationDate: '', calibrationCert: '' }])}
                className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs"
              >
                + Add Equipment
              </button>
            </div>
            <div>
              <h4 className="text-sm font-medium mb-2">Personnel</h4>
              {(reportInput.personnel || []).map((p, idx) => (
                <div key={p.name} className="grid grid-cols-4 gap-2 mb-2">
                  <input
                    type="text"
                    aria-label="Personnel Name" placeholder="e.g. J. Mwangi"
                    value={p.name}
                    onChange={e => {
                      const newP = [...(reportInput.personnel || [])]
                      newP[idx] = { ...newP[idx], name: e.target.value }
                      updateInput('personnel', newP)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Role" placeholder="e.g. Surveyor"
                    value={p.role}
                    onChange={e => {
                      const newP = [...(reportInput.personnel || [])]
                      newP[idx] = { ...newP[idx], role: e.target.value }
                      updateInput('personnel', newP)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <input
                    type="text"
                    aria-label="Qualification" placeholder="e.g. BSc Geomatics"
                    value={p.qualification}
                    onChange={e => {
                      const newP = [...(reportInput.personnel || [])]
                      newP[idx] = { ...newP[idx], qualification: e.target.value }
                      updateInput('personnel', newP)
                    }}
                    className="col-span-1 px-2 py-1.5 bg-[var(--bg-tertiary)] border rounded text-xs"
                  />
                  <button
                    onClick={() => {
                      const newP = (reportInput.personnel || []).filter((_, i) => i !== idx)
                      updateInput('personnel', newP)
                    }}
                    className="text-red-500 text-xs"
                  >
                    [x]
                  </button>
                </div>
              ))}
              <button
                onClick={() => updateInput('personnel', [...(reportInput.personnel || []), { name: '', role: '', qualification: '' }])}
                className="px-3 py-1.5 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded text-xs"
              >
                + Add Personnel
              </button>
            </div>
          </div>
        )

      case 'CONTROL_SURVEY':
        return (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-datum" className="block text-sm font-medium mb-1">Datum</label>
                <select
                  id="sr-datum"
                  value={reportInput.datum || 'ARC1960'}
                  onChange={e => updateInput('datum', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                >
                  <option value="ARC1960">ARC1960</option>
                  <option value="WGS84">WGS84</option>
                </select>
              </div>
              <div>
                <label htmlFor="sr-projection" className="block text-sm font-medium mb-1">Projection</label>
                <input
                  id="sr-projection"
                  type="text"
                  value={reportInput.projection || ''}
                  onChange={e => updateInput('projection', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  placeholder="e.g., UTM Zone 37S"
                />
              </div>
            </div>
            <div>
              <label htmlFor="sr-gnss-method" className="block text-sm font-medium mb-1">GNSS Method (optional)</label>
              <input
                id="sr-gnss-method"
                type="text"
                value={reportInput.gnssMethod || ''}
                onChange={e => updateInput('gnssMethod', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="e.g., Static GNSS, RTK"
              />
            </div>
            <div>
              <div className="block text-sm font-medium mb-1">Control Points ({reportInput.controlPoints?.length || 0})</div>
              <p className="text-xs text-gray-500 mb-2">Control points are imported from your project survey points.</p>
            </div>
          </div>
        )

      case 'TOPOGRAPHIC_SURVEY':
        return (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-survey-method" className="block text-sm font-medium mb-1">Survey Method</label>
                <select
                  id="sr-survey-method"
                  value={reportInput.surveyMethod || 'GNSS_RTK'}
                  onChange={e => updateInput('surveyMethod', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                >
                  <option value="TOTAL_STATION">Total Station</option>
                  <option value="GNSS_RTK">GNSS RTK</option>
                  <option value="LEVEL">Level</option>
                  <option value="COMBINED">Combined Methods</option>
                </select>
              </div>
              <div>
                <label htmlFor="sr-instrument" className="block text-sm font-medium mb-1">Instrument Used</label>
                <input
                  id="sr-instrument"
                  type="text"
                  value={reportInput.instrumentUsed || ''}
                  onChange={e => updateInput('instrumentUsed', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  placeholder="e.g., Trimble S7, Leica GS18"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="sr-point-density" className="block text-sm font-medium mb-1">Point Density (optional)</label>
                <input
                  id="sr-point-density"
                  type="text"
                  value={reportInput.pointDensity || ''}
                  onChange={e => updateInput('pointDensity', e.target.value)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  placeholder="e.g., 1 point per 10m²"
                />
              </div>
              <div>
                <label htmlFor="sr-area" className="block text-sm font-medium mb-1">Area (hectares)</label>
                <input id="sr-area"
                  type="number"
                  value={reportInput.areaHectares || ''}
                  onChange={e => updateInput('areaHectares', parseFloat(e.target.value) || undefined)}
                  className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                />
              </div>
            </div>
          </div>
        )

      case 'RESULTS_AND_ACCURACY':
        return (
          <div className="space-y-4">
            <div>
              <label htmlFor="sr-traverse-accuracy" className="block text-sm font-medium mb-1">Traverse Accuracy</label>
              <input
                id="sr-traverse-accuracy"
                type="text"
                value={reportInput.traverseAccuracy || ''}
                onChange={e => updateInput('traverseAccuracy', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="e.g., 1:10,000"
              />
              <p className="text-xs text-gray-500 mt-1">Auto-populated from traverse computations if available.</p>
            </div>
            <div>
              <label htmlFor="sr-levelling-misclosure" className="block text-sm font-medium mb-1">Levelling Misclosure</label>
              <input
                id="sr-levelling-misclosure"
                type="text"
                value={reportInput.levellingMisclosure || ''}
                onChange={e => updateInput('levellingMisclosure', e.target.value)}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                placeholder="e.g., 12.5 mm"
              />
            </div>
          </div>
        )

      case 'CONCLUSIONS_AND_RECOMMENDATIONS':
        return (
          <div className="space-y-4">
            <div>
              <div className="block text-sm font-medium mb-2">Conclusions</div>
              {(reportInput.conclusions || []).map((c, idx) => (
                <div key={`${c}-${idx}`} className="flex gap-2 mb-2">
                  <textarea
                    aria-label={`Conclusion ${idx + 1}`}
                    value={c}
                    onChange={e => {
                      const newC = [...(reportInput.conclusions || [])]
                      newC[idx] = e.target.value
                      updateInput('conclusions', newC)
                    }}
                    rows={2}
                    className="flex-1 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  />
                  <button
                    onClick={() => updateInput('conclusions', (reportInput.conclusions || []).filter((_, i) => i !== idx))}
                    className="px-2 text-red-500 hover:bg-red-50 rounded"
                  >
                    [x]
                  </button>
                </div>
              ))}
              <button
                onClick={() => updateInput('conclusions', [...(reportInput.conclusions || []), ''])}
                className="px-3 py-1.5 bg-[var(--accent)] text-black rounded text-xs font-medium"
              >
                + Add Conclusion
              </button>
            </div>
            <div>
              <div className="block text-sm font-medium mb-2">Recommendations</div>
              {(reportInput.recommendations || []).map((r, idx) => (
                <div key={`${r}-${idx}`} className="flex gap-2 mb-2">
                  <textarea
                    aria-label={`Recommendation ${idx + 1}`}
                    value={r}
                    onChange={e => {
                      const newR = [...(reportInput.recommendations || [])]
                      newR[idx] = e.target.value
                      updateInput('recommendations', newR)
                    }}
                    rows={2}
                    className="flex-1 px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm"
                  />
                  <button
                    onClick={() => updateInput('recommendations', (reportInput.recommendations || []).filter((_, i) => i !== idx))}
                    className="px-2 text-red-500 hover:bg-red-50 rounded"
                  >
                    [x]
                  </button>
                </div>
              ))}
              <button
                onClick={() => updateInput('recommendations', [...(reportInput.recommendations || []), ''])}
                className="px-3 py-1.5 bg-[var(--accent)] text-black rounded text-xs font-medium"
              >
                + Add Recommendation
              </button>
            </div>
          </div>
        )

      case 'DECLARATION':
        return (
          <div className="space-y-4">
            <div className="p-3 border border-amber-700/40 bg-amber-950/20 rounded-lg text-xs text-amber-200 leading-6">
              <strong>Survey Regulations 1994, Reg. 3(2)</strong> — Every survey report submitted to the Director of Surveys
              must contain a signed declaration by the licensed surveyor who supervised the work.
            </div>
            <div>
              <label htmlFor="sr-declaration" className="block text-sm font-medium mb-1">Declaration Statement</label>
              <textarea
                id="sr-declaration"
                value={reportInput.declarationStatement || ''}
                onChange={e => updateInput('declarationStatement', e.target.value)}
                rows={14}
                className="w-full px-3 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm font-mono leading-6"
                placeholder="I, the undersigned, being a Registered Surveyor under the Survey Act (Cap. 299)..."
              />
            </div>
            <button
              onClick={() => updateInput('declarationStatement', DEFAULT_DECLARATION)}
              className="px-4 py-2 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-xs font-medium hover:border-[var(--accent)]"
            >
              Load Standard Declaration Template
            </button>
          </div>
        )

      default:
        return <p className="text-gray-500">No editing available for this section.</p>
    }
  }

  const renderPreview = () => {
    return (
      <div className="bg-white text-black p-8 max-w-[794px] mx-auto shadow-lg min-h-[1123px]">
        {generatedSections.map((section: any) => (
          <div key={section.section} className={section.sectionNumber > 1 ? 'mt-8' : ''}>
            {section.sectionNumber === 1 ? (
              <div dangerouslySetInnerHTML={{ __html: sanitizeHtml(section.content) }} />
            ) : (
              <>
                <h2 className="text-lg font-bold border-b border-gray-300 pb-2 mb-4">
                  {section.sectionNumber}. {section.title}
                </h2>
                <div dangerouslySetInnerHTML={{ __html: sanitizeHtml(section.content) }} />
              </>
            )}
          </div>
        ))}
      </div>
    )
  }

  if (isGenerating && !generatedSections.length) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="w-8 h-8 border-2 border-[var(--accent)] border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-[var(--text-muted)]">Generating report...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="flex h-screen overflow-hidden">
      {/* Left Sidebar */}
      <div className="w-72 border-r border-[var(--border-color)] bg-[var(--bg-card)] flex flex-col overflow-hidden">
        <div className="p-4 border-b border-[var(--border-color)]">
          <h1 className="text-lg font-semibold">Survey Report</h1>
          <div className="flex gap-1 mt-3 bg-[var(--bg-tertiary)] p-1 rounded-lg">
            <button
              onClick={() => setMode('edit')}
              className={`flex-1 py-1.5 text-xs font-medium rounded ${mode === 'edit' ? 'bg-[var(--accent)] text-black' : 'text-[var(--text-muted)]'}`}
            >
              Edit
            </button>
            <button
              onClick={() => setMode('preview')}
              className={`flex-1 py-1.5 text-xs font-medium rounded ${mode === 'preview' ? 'bg-[var(--accent)] text-black' : 'text-[var(--text-muted)]'}`}
            >
              Preview
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-2">
          {SECTION_INFO.map((info: any) => (
            <button
              key={info.section}
              onClick={() => setActiveSection(info.section)}
              className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm mb-1 ${
                activeSection === info.section 
                  ? 'bg-blue-50 text-blue-700 border border-blue-200' 
                  : 'hover:bg-[var(--bg-tertiary)]'
              }`}
            >
              <span className="flex items-center gap-2">
                <span className="text-xs text-[var(--text-muted)]">{info.number}.</span>
                <span className="truncate">{info.title}</span>
              </span>
              {getSectionBadge(info)}
            </button>
          ))}
        </div>

        <div className="p-4 border-t border-[var(--border-color)]">
          <div className="text-xs text-[var(--text-muted)] mb-2">
            Report Completeness
          </div>
          <div className="w-full h-2 bg-[var(--bg-tertiary)] rounded-full overflow-hidden">
            <div 
              className="h-full bg-green-500 transition-all"
              style={{ width: `${completeness?.overallPercent || 0}%` }}
            />
          </div>
          <div className="flex justify-between text-xs mt-1">
            <span className="text-[var(--text-muted)]">{completeness?.overallPercent || 0}% complete</span>
            <span className="text-[var(--text-muted)]">{completeness?.sectionsComplete || 0} of 15 sections</span>
          </div>
        </div>

        <div className="p-4 border-t border-[var(--border-color)] space-y-2">
          <button
            onClick={saveReport}
            disabled={isSaving}
            className="w-full px-4 py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--border-hover)] border border-[var(--border-color)] rounded-lg text-sm font-medium disabled:opacity-50"
          >
            {isSaving ? 'Saving...' : 'Save Draft'}
          </button>
          <button
            onClick={saveReport}
            disabled={!completeness?.readyToFinalise || isSaving}
            className="w-full px-4 py-2 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-black rounded-lg text-sm font-medium disabled:opacity-40 disabled:cursor-not-allowed"
            title={!completeness?.readyToFinalise ? 'Complete all required sections to finalise' : ''}
          >
            Finalise Report
          </button>
        </div>
      </div>

      {/* Right Panel */}
      <div className="flex-1 overflow-y-auto p-8 bg-[var(--bg-primary)]">
        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
            {error}
          </div>
        )}

        {mode === 'edit' ? (
          <div className="max-w-2xl mx-auto">
            <div className="mb-6">
              <h2 className="text-xl font-semibold">
                Section {SECTION_INFO.find((s: any) => s.section === activeSection)?.number} — {SECTION_INFO.find((s: any) => s.section === activeSection)?.title}
              </h2>
            </div>
            {renderSectionForm()}
          </div>
        ) : (
          <div>
            <div className="sticky top-0 bg-[var(--bg-primary)] py-4 border-b border-[var(--border-color)] mb-6 flex gap-2 no-print print-hide">
              <PrintButton
                print={print}
                isPrinting={isPrinting}
                paperSize={paperSize}
                setPaperSize={setPaperSize}
                orientation={orientation}
                setOrientation={setOrientation}
                printTitle="Survey Report"
              />
              <button
                onClick={() => exportReport('pdf')}
                className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium"
              >
                Download PDF
              </button>
              <button
                onClick={() => exportReport('docx')}
                className="px-4 py-2 bg-[var(--accent)] text-black rounded-lg text-sm font-medium"
              >
                Download Word
              </button>
            </div>
            <PrintHeader title="Survey Report" />
            {renderPreview()}
          </div>
        )}
      </div>
    </div>
  )
}

