const CATEGORIES = ['All', 'Calculations', 'Coordinates', 'Engineering', 'Volumes', 'Documents', 'Field Books', 'Validation']

const CATEGORY_ICONS: Record<string, typeof Calculator> = {
  All: Layers,
  Calculations: Calculator,
  Coordinates: Compass,
  Engineering: Building2,
  Volumes: Mountain,
  Documents: FileText,
  'Field Books': FileText,
  Validation: Ruler,
}

export function ProcessingToolbox({ compact = false }: { compact?: boolean }) {
  const router = useRouter()
  const [query, setQuery] = useState('')
  const [activeCategory, setActiveCategory] = useState('All')
  const [favorites, setFavorites] = useState<string[]>([])
  const [recent, setRecent] = useState<string[]>([])

  // Load favorites and recent from localStorage.
  // P1-4 (2026-07-24): Unified with /tools catalog page storage keys.
  // Read from both old (metardu-tool-*) and canonical (metardu-*-tools)
  // keys for backward compat, write only to canonical.
  useEffect(() => {
    const canonicalFav = JSON.parse(localStorage.getItem('metardu-fav-tools') || '[]')
    const oldFav = JSON.parse(localStorage.getItem('metardu-tool-favorites') || '[]')
    const fav = Array.from(new Set([...canonicalFav, ...oldFav])) as string[]

    const canonicalRec = JSON.parse(localStorage.getItem('metardu-recent-tools') || '[]')
    const oldRec = JSON.parse(localStorage.getItem('metardu-tool-recent') || '[]')
    const rec = Array.from(new Set([...canonicalRec, ...oldRec])) as string[]

    setFavorites(fav)
    setRecent(rec)
  }, [])

  const toggleFavorite = useCallback((toolId: string) => {
    setFavorites(prev => {
      const next = prev.includes(toolId)
        ? prev.filter(id => id !== toolId)
        : [...prev, toolId]
      // Write to canonical key only
      localStorage.setItem('metardu-fav-tools', JSON.stringify(next))
      return next
    })
  }, [])

  const handleToolClick = useCallback((tool: Tool) => {
    // Add to recent
    setRecent(prev => {
      const next = [tool.id, ...prev.filter(id => id !== tool.id)].slice(0, 8)
      // Write to canonical key only
      localStorage.setItem('metardu-recent-tools', JSON.stringify(next))
      return next
    })
    router.push(tool.href)
  }, [router])

  // Filter tools
  const filteredTools = useMemo(() => {
    let result = TOOLS
    if (activeCategory !== 'All') {
      result = result.filter(t => t.category === activeCategory)
    }
    if (query.trim()) {
      const q = query.toLowerCase()
      result = result.filter(t =>
        t.name.toLowerCase().includes(q) ||
        t.description.toLowerCase().includes(q) ||
        t.keywords.some(k => k.includes(q))
      )
    }
    return result
  }, [query, activeCategory])

  // Group by category
  const grouped = useMemo(() => {
    const groups: Record<string, Tool[]> = {}
    for (const tool of filteredTools) {
      if (!groups[tool.category]) groups[tool.category] = []
      groups[tool.category].push(tool)
    }
    return groups
  }, [filteredTools])

  const recentTools = useMemo(() => {
    return recent
      .map(id => TOOLS.find(t => t.id === id))
      .filter((t): t is Tool => t !== undefined)
  }, [recent])

  const favoriteTools = useMemo(() => {
    return favorites
      .map(id => TOOLS.find(t => t.id === id))
      .filter((t): t is Tool => t !== undefined)
  }, [favorites])

  return (
    <div className={`flex flex-col ${compact ? 'h-full' : 'h-[600px]'} bg-[var(--bg-card)] rounded-xl border border-[var(--border-color)] overflow-hidden`}>
      {/* Search bar */}
      <div className="p-3 border-b border-[var(--border-color)]">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
          <input
            type="text"
            value={query}
            onChange={e => setQuery(e.target.value)}
            aria-label="Search 60+ tools..." placeholder="Search 60+ tools..."
            className="w-full h-9 pl-9 pr-8 bg-[var(--bg-tertiary)] border border-[var(--border-color)] rounded-lg text-sm text-[var(--text-primary)] placeholder-gray-600 focus:border-[var(--accent)]/30 focus:outline-none"
          />
          {query && (
            <button
              onClick={() => setQuery('')}
              className="absolute right-2 top-1/2 -translate-y-1/2 w-5 h-5 flex items-center justify-center rounded text-gray-500 hover:text-white"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
      </div>

      {/* Category filter */}
      <div className="px-3 py-2 border-b border-[var(--border-color)] flex items-center gap-1.5 overflow-x-auto">
        {CATEGORIES.map(cat => {
          const Icon = CATEGORY_ICONS[cat]
          return (
            <button
              key={cat}
              onClick={() => setActiveCategory(cat)}
              className={`flex items-center gap-1 px-2.5 py-1 rounded-lg text-[10px] font-medium whitespace-nowrap transition-colors ${
                activeCategory === cat
                  ? 'bg-[var(--accent)]/10 border border-[var(--accent)]/30 text-[var(--accent)]'
                  : 'text-gray-400 hover:text-gray-300 hover:bg-white/[0.04]'
              }`}
            >
              {Icon && <Icon className="w-3 h-3" />}
              {cat}
            </button>
          )
        })}
      </div>

      {/* Tool list */}
      <div className="flex-1 overflow-y-auto">
        {/* Recent tools */}
        {recentTools.length > 0 && !query && activeCategory === 'All' && (
          <div className="p-3 border-b border-[var(--border-color)]">
            <div className="flex items-center gap-1.5 mb-2">
              <Clock className="w-3 h-3 text-gray-500" />
              <span className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider">Recent</span>
            </div>
            <div className="space-y-1">
              {recentTools.slice(0, 4).map(tool => (
                <ToolRow
                  key={tool.id}
                  tool={tool}
                  isFavorite={favorites.includes(tool.id)}
                  onToggleFavorite={() => toggleFavorite(tool.id)}
                  onClick={() => handleToolClick(tool)}
                />
              ))}
            </div>
          </div>
        )}

        {/* Favorites */}
        {favoriteTools.length > 0 && !query && activeCategory === 'All' && (
          <div className="p-3 border-b border-[var(--border-color)]">
            <div className="flex items-center gap-1.5 mb-2">
              <Star className="w-3 h-3 text-amber-400" />
              <span className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider">Favorites</span>
            </div>
            <div className="space-y-1">
              {favoriteTools.map(tool => (
                <ToolRow
                  key={tool.id}
                  tool={tool}
                  isFavorite={true}
                  onToggleFavorite={() => toggleFavorite(tool.id)}
                  onClick={() => handleToolClick(tool)}
                />
              ))}
            </div>
          </div>
        )}

        {/* All tools grouped by category */}
        {Object.entries(grouped).map(([cat, tools]) => (
          <div key={cat} className="p-3 border-b border-[var(--border-color)]/50">
            <div className="flex items-center gap-1.5 mb-2">
              {(() => {
                const Icon = CATEGORY_ICONS[cat] || Calculator
                return <Icon className="w-3 h-3 text-gray-500" />
              })()}
              <span className="text-[10px] font-semibold text-gray-500 uppercase tracking-wider">{cat}</span>
              <span className="text-[9px] text-gray-600">({tools.length})</span>
            </div>
            <div className="space-y-1">
              {tools.map(tool => (
                <ToolRow
                  key={tool.id}
                  tool={tool}
                  isFavorite={favorites.includes(tool.id)}
                  onToggleFavorite={() => toggleFavorite(tool.id)}
                  onClick={() => handleToolClick(tool)}
                />
              ))}
            </div>
          </div>
        ))}

        {/* No results */}
        {filteredTools.length === 0 && (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <Search className="w-8 h-8 text-gray-600 mb-2" />
            <p className="text-sm text-gray-500">No tools found for &quot;{query}&quot;</p>
            <p className="text-[10px] text-gray-600 mt-1">Try a different search term</p>
          </div>
        )}
      </div>
    </div>
  )
}

function ToolRow({
  tool,
  isFavorite,
  onToggleFavorite,
  onClick,
}: {
  tool: Tool
  isFavorite: boolean
  onToggleFavorite: () => void
  onClick: () => void
}) {
  const Icon = tool.icon
  return (
    <div
      onClick={onClick}
      className="group flex items-center gap-2.5 p-2 rounded-lg cursor-pointer hover:bg-white/[0.04] transition-colors"
    >
      <div className="shrink-0 w-8 h-8 rounded-lg bg-[var(--accent)]/5 border border-[var(--accent)]/10 flex items-center justify-center">
        <Icon className="w-4 h-4 text-[var(--accent)]" />
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-xs font-medium text-[var(--text-primary)] truncate">{tool.name}</div>
        <div className="text-[10px] text-gray-500 truncate">{tool.description}</div>
      </div>
      <button
        onClick={(e) => { e.stopPropagation(); onToggleFavorite() }}
        className="shrink-0 w-6 h-6 flex items-center justify-center rounded opacity-0 group-hover:opacity-100 transition-opacity"
      >
        <Star className={`w-3.5 h-3.5 ${isFavorite ? 'fill-amber-400 text-amber-400' : 'text-gray-500 hover:text-amber-400'}`} />
      </button>
      <ChevronRight className="w-3.5 h-3.5 text-gray-600 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity" />
    </div>
  )
}

'use client';

/**
 * SpiralAlignmentTab — Tier 2 UI for the spiral-to-curve alignment engine.
 *
 * Roadmap reference: docs/ROADMAP.md → Tier 2 → "Spiral-to-curve alignment
 * engine". Renders as a 5th tab on `/tools/curves`.
 *
 * Inputs:  radius, intersection angle, spiral length, PI chainage,
 *          optional PI coordinates + approach bearing for world coords.
 * Outputs: TS/SC/CS/ST stations, T/Lc/p/k/θs, SVG plan diagram,
 *          station table, CSV export.
 */

import { useState, useMemo } from 'react';
import { PageHeader } from '@/components/shared/PageHeader';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Download, Spline, AlertTriangle, MapPin, Copy } from 'lucide-react';
import { downloadCSV } from '@/lib/export/helpers';
import {
  computeSpiralAlignment,
  stationSpiralAlignment,
  alignmentToCoordinateArray,
  spiralAlignmentToCSV,
  type SpiralAlignmentResult,
} from '@/lib/survey/curves/spiralAlignment';

export function SpiralAlignmentTab() {
  const [input, setInput] = useState({
    radius: '300',
    intersectionAngleDeg: '30',
    spiralLength: '60',
    piChainage: '1000',
    approachBearingDeg: '0',
    piEasting: '',
    piNorthing: '',
  });
  const [result, setResult] = useState<SpiralAlignmentResult | null>(null);
  const [error, setError] = useState('');

  const compute = () => {
    setError('');
    try {
      const r = computeSpiralAlignment({
        radius: Number(input.radius),
        intersectionAngleDeg: Number(input.intersectionAngleDeg),
        spiralLength: Number(input.spiralLength),
        piChainage: Number(input.piChainage),
        approachBearingDeg: input.approachBearingDeg
          ? Number(input.approachBearingDeg)
          : undefined,
        piEasting: input.piEasting ? Number(input.piEasting) : undefined,
        piNorthing: input.piNorthing ? Number(input.piNorthing) : undefined,
      });
      setResult(r);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setResult(null);
    }
  };

  const stations = useMemo(() => {
    if (!result) return [];
    return stationSpiralAlignment(result, 10);
  }, [result]);

  const exportCSV = () => {
    if (stations.length === 0) return;
    downloadCSV(spiralAlignmentToCSV(stations), `spiral-alignment-${Date.now()}.csv`);
  };

  const exportGeoJSON = () => {
    if (!result) return;
    const coords = alignmentToCoordinateArray(result, 2);
    if (coords.length < 2) return;
    const gj = {
      type: 'FeatureCollection',
      features: [
        {
          type: 'Feature' as const,
          geometry: { type: 'LineString' as const, coordinates: coords },
          properties: {
            type: 'spiral-alignment',
            radius: result.input.radius,
            intersection_angle_deg: result.input.intersectionAngleDeg,
            spiral_length: result.input.spiralLength,
            total_length: result.totalLength,
            ts_chainage: result.tsChainage,
            sc_chainage: result.scChainage,
            cs_chainage: result.csChainage,
            st_chainage: result.stChainage,
          },
        },
        // Key station points as separate Features
        ...(
          [
            ['TS', result.tsChainage, result.tsCoord],
            ['SC', result.scChainage, result.scCoord],
            ['CS', result.csChainage, result.csCoord],
            ['ST', result.stChainage, result.stCoord],
            ['PI', result.input.piChainage, result.piCoord],
          ] as const
        )
          .filter(([, , coord]) => coord !== null)
          .map(([label, chainage, coord]) => ({
            type: 'Feature' as const,
            geometry: {
              type: 'Point' as const,
              coordinates: [coord!.easting, coord!.northing],
            },
            properties: { label, chainage },
          })),
      ],
    };
    const blob = new Blob([JSON.stringify(gj, null, 2)], {
      type: 'application/geo+json',
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `spiral-alignment-${Date.now()}.geojson`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const copyCoords = async () => {
    if (!result) return;
    const coords = alignmentToCoordinateArray(result, 2);
    if (coords.length < 2) return;
    // Format as JSON array for direct paste into OpenLayers code:
    //   new LineString([[e, n], [e, n], ...])
    const text = JSON.stringify(coords);
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      // Fallback for browsers without clipboard API
      const ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
    }
  };

  return (
    <div className="space-y-6">
      {/* Inputs */}
      <div className="bg-[var(--bg-card)] border border-[var(--border-color)] rounded-lg p-5">
        <div className="flex items-center gap-2 mb-4">
