// ─── Plan Diagram ───────────────────────────────────────────────────────────

function SpiralPlanDiagram({ result }: { result: SpiralAlignmentResult }) {
  const WIDTH = 800;
  const HEIGHT = 400;
  const PAD = 40;

  // Get alignment coordinates (local frame if no PI)
  const coords = useMemo(
    () => alignmentToCoordinateArray(result, 2),
    [result]
  );

  if (coords.length < 2) {
    return <p className="text-xs text-[var(--text-muted)]">No coordinates to plot.</p>;
  }

  // Compute scale to fit
  const xs = coords.map(c => c[0]);
  const ys = coords.map(c => c[1]);
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);
  const dx = maxX - minX || 1;
  const dy = maxY - minY || 1;
  const scale = Math.min((WIDTH - 2 * PAD) / dx, (HEIGHT - 2 * PAD) / dy);
  const offsetX = (WIDTH - dx * scale) / 2;
  const offsetY = (HEIGHT - dy * scale) / 2;

  const tx = (x: number) => offsetX + (x - minX) * scale;
  // Invert Y because SVG Y grows downward
  const ty = (y: number) => HEIGHT - offsetY - (y - minY) * scale;

  const pathD = coords
    .map((c, i) => `${i === 0 ? 'M' : 'L'} ${tx(c[0]).toFixed(1)} ${ty(c[1]).toFixed(1)}`)
    .join(' ');

  // Tangent lines (approach and departure)
  const ts = coords[0];
  const st = coords[coords.length - 1];
  // Approach tangent: extend backward from TS
  const approachDx = (coords[1][0] - ts[0]) * 5;
  const approachDy = (coords[1][1] - ts[1]) * 5;
  const approachEnd = [ts[0] - approachDx, ts[1] - approachDy];
  // Departure tangent: extend forward from ST
  const depDx = (st[0] - coords[coords.length - 2][0]) * 5;
  const depDy = (st[1] - coords[coords.length - 2][1]) * 5;
  const depStart = [st[0] + depDx, st[1] + depDy];

  // PI = intersection of tangents
  // Simplified: assume PI is somewhere "above" the alignment center
  // For visualization, just mark SC and CS
  const scIdx = Math.floor(result.spiral.spiralLength / 2); // approx index for SC
  const sc = coords[Math.min(scIdx, coords.length - 1)];
  const cs = coords[Math.max(coords.length - 1 - scIdx, 0)];

  return (
    <svg
      viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
      className="w-full h-auto"
      style={{ minWidth: 500 }}
    >
      {/* Approach tangent */}
      <line
        x1={tx(ts[0])}
        y1={ty(ts[1])}
        x2={tx(approachEnd[0])}
        y2={ty(approachEnd[1])}
        stroke="#71717a"
        strokeWidth="1"
        strokeDasharray="4,3"
        opacity="0.6"
      />
      {/* Departure tangent */}
      <line
        x1={tx(st[0])}
        y1={ty(st[1])}
        x2={tx(depStart[0])}
        y2={ty(depStart[1])}
        stroke="#71717a"
        strokeWidth="1"
        strokeDasharray="4,3"
        opacity="0.6"
      />
      {/* Alignment */}
      <path d={pathD} fill="none" stroke="var(--accent)" strokeWidth="2.5" />

      {/* TS marker */}
      <g>
        <circle cx={tx(ts[0])} cy={ty(ts[1])} r="6" fill="#fbbf24" stroke="#1A1816" strokeWidth="1" />
        <text x={tx(ts[0])} y={ty(ts[1]) - 12} textAnchor="middle" fontSize="11" fill="#fbbf24" fontFamily="monospace">
          TS
        </text>
      </g>
      {/* SC marker */}
      <g>
        <circle cx={tx(sc[0])} cy={ty(sc[1])} r="5" fill="#22d3ee" stroke="#1A1816" strokeWidth="1" />
        <text x={tx(sc[0])} y={ty(sc[1]) - 10} textAnchor="middle" fontSize="10" fill="#22d3ee" fontFamily="monospace">
          SC
        </text>
      </g>
      {/* CS marker */}
      <g>
        <circle cx={tx(cs[0])} cy={ty(cs[1])} r="5" fill="#22d3ee" stroke="#1A1816" strokeWidth="1" />
        <text x={tx(cs[0])} y={ty(cs[1]) - 10} textAnchor="middle" fontSize="10" fill="#22d3ee" fontFamily="monospace">
          CS
        </text>
      </g>
      {/* ST marker */}
      <g>
        <circle cx={tx(st[0])} cy={ty(st[1])} r="6" fill="#fbbf24" stroke="#1A1816" strokeWidth="1" />
        <text x={tx(st[0])} y={ty(st[1]) - 12} textAnchor="middle" fontSize="11" fill="#fbbf24" fontFamily="monospace">
          ST
        </text>
      </g>
    </svg>
  );
}

'use client';

/**
 * OrthophotoOverlay — renders an orthophoto image as background layer
 * on the topo canvas, under contours and spot heights.
 *
 * The surveyor uploads a GeoTIFF/PNG orthophoto from their drone
 * processing software (Pix4D, DroneDeploy, Agisoft). The image is
 * georeferenced using corner coordinates and rendered as a canvas
 * background layer.
 *
 * The topo canvas then shows:
 *   [orthophoto image] → [contour lines] → [spot heights] → [labels]
 *
 * This gives the surveyor a real-world visual reference for their
 * contour plan — they can see if contours follow the actual terrain.
 */

import { useState, useCallback, useRef, useEffect } from 'react'

export interface OrthophotoBounds {
  minEasting: number
  maxEasting: number
  minNorthing: number
  maxNorthing: number
}

interface OrthophotoOverlayProps {
  imageUrl: string | null          // data URL or blob URL
  bounds: OrthophotoBounds | null  // geo bounds of the image
  canvasWidth: number
  canvasHeight: number
  viewBounds: OrthophotoBounds     // current view bounds
  opacity?: number                 // 0-1, default 0.6
}

export function OrthophotoOverlay({
  imageUrl,
  bounds,
  canvasWidth,
  canvasHeight,
  viewBounds,
  opacity = 0.6,
}: OrthophotoOverlayProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [imgLoaded, setImgLoaded] = useState(false)
  const imgRef = useRef<HTMLImageElement | null>(null)

  // Load image
  useEffect(() => {
    if (!imageUrl) {
      setImgLoaded(false)
      return
    }

    const img = new Image()
    img.onload = () => {
      imgRef.current = img
      setImgLoaded(true)
    }
    img.onerror = () => {
      console.error('[OrthophotoOverlay] Failed to load image')
      setImgLoaded(false)
    }
    img.src = imageUrl
  }, [imageUrl])

  // Render to canvas
  useEffect(() => {
    if (!imgLoaded || !imgRef.current || !bounds || !canvasRef.current) return

    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    canvas.width = canvasWidth
    canvas.height = canvasHeight

    // Calculate scale: how many pixels per meter
    const viewWidthM = viewBounds.maxEasting - viewBounds.minEasting
    const viewHeightM = viewBounds.maxNorthing - viewBounds.minNorthing
    const scaleX = canvasWidth / viewWidthM
    const scaleY = canvasHeight / viewHeightM

    // Calculate image position on canvas
    const imgMinX = (bounds.minEasting - viewBounds.minEasting) * scaleX
    const imgMaxX = (bounds.maxEasting - viewBounds.minEasting) * scaleX
    // Y is inverted (canvas Y goes down, northing goes up)
    const imgMinY = canvasHeight - (bounds.maxNorthing - viewBounds.minNorthing) * scaleY
    const imgMaxY = canvasHeight - (bounds.minNorthing - viewBounds.minNorthing) * scaleY

    const destX = Math.max(0, imgMinX)
    const destY = Math.max(0, imgMinY)
    const destW = Math.min(canvasWidth, imgMaxX) - destX
    const destH = Math.min(canvasHeight, imgMaxY) - destY

    if (destW <= 0 || destH <= 0) return

    // Source crop (which part of the image is visible)
    const imgW = imgRef.current.width
    const imgH = imgRef.current.height
    const srcMinX = Math.max(0, (viewBounds.minEasting - bounds.minEasting) / (bounds.maxEasting - bounds.minEasting)) * imgW
    const srcMaxX = Math.min(1, (viewBounds.maxEasting - bounds.minEasting) / (bounds.maxEasting - bounds.minEasting)) * imgW
    const srcMinY = Math.max(0, (bounds.maxNorthing - viewBounds.maxNorthing) / (bounds.maxNorthing - bounds.minNorthing)) * imgH
    const srcMaxY = Math.min(1, (bounds.maxNorthing - viewBounds.minNorthing) / (bounds.maxNorthing - bounds.minNorthing)) * imgH

    const srcW = srcMaxX - srcMinX
    const srcH = srcMaxY - srcMinY

    if (srcW <= 0 || srcH <= 0) return

    ctx.globalAlpha = opacity
    ctx.drawImage(imgRef.current, srcMinX, srcMinY, srcW, srcH, destX, destY, destW, destH)
    ctx.globalAlpha = 1
  }, [imgLoaded, bounds, canvasWidth, canvasHeight, viewBounds, opacity])

  if (!imageUrl || !bounds) return null

  return (
    <canvas
      ref={canvasRef}
      width={canvasWidth}
      height={canvasHeight}
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        pointerEvents: 'none',
      }}
    />
  )
}

/**
 * Helper: load a GeoTIFF file and extract bounds + image data.
 * ponytail: uses the browser's built-in Image API for PNG/JPEG.
 * For GeoTIFF, use a library like geotiff.js (not installed yet).
 * For now, the surveyor provides the image + bounds manually.
 */
export async function loadOrthophoto(
  file: File,
  bounds: OrthophotoBounds,
): Promise<{ url: string; bounds: OrthophotoBounds }> {
  const url = URL.createObjectURL(file)
  return { url, bounds }
}

