                    <span className="text-xs text-zinc-300">Include spot height labels</span>
                  </div>
                  <div className="flex items-center gap-2 cursor-pointer">
                    <Checkbox
                      aria-label="Include title block"
                      checked={settings.includeTitleBlock}
                      onCheckedChange={v => setSettings(prev => ({ ...prev, includeTitleBlock: !!v }))}
                      className="border-zinc-600"
                    />
                    <span className="text-xs text-zinc-300">Include title block</span>
                  </div>
                  <div className="flex items-center gap-2 cursor-pointer">
                    <Checkbox
                      aria-label="Include point labels"
                      checked={settings.includeLabels}
                      onCheckedChange={v => setSettings(prev => ({ ...prev, includeLabels: !!v }))}
                      className="border-zinc-600"
                    />
                    <span className="text-xs text-zinc-300">Include point labels</span>
                  </div>
                  <div className="flex items-center gap-2 cursor-pointer">
                    <Checkbox
                      aria-label="Include legend"
                      checked={settings.includeLegend}
                      onCheckedChange={v => setSettings(prev => ({ ...prev, includeLegend: !!v }))}
                      className="border-zinc-600"
                    />
                    <span className="text-xs text-zinc-300">Include legend</span>
                  </div>
                </div>

                {/* Contour & Grid intervals */}
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label htmlFor="tdc-contour-interval" className="text-[10px] uppercase tracking-wider text-zinc-500 font-medium">Contour Interval (m)</label>
                    <Input
                      id="tdc-contour-interval"
                      type="number"
                      step="0.5"
                      min="0.25"
                      value={settings.contourInterval}
                      onChange={e => setSettings(prev => ({ ...prev, contourInterval: parseFloat(e.target.value) || 1 }))}
                      className="h-8 mt-1 text-xs bg-zinc-800 border-zinc-700 text-zinc-300"
                    />
                  </div>
                  <div>
                    <label htmlFor="tdc-grid-tick" className="text-[10px] uppercase tracking-wider text-zinc-500 font-medium">Grid Tick (m)</label>
                    <Input
                      id="tdc-grid-tick"
                      type="number"
                      step="10"
                      min="10"
                      value={settings.gridTickInterval}
                      onChange={e => setSettings(prev => ({ ...prev, gridTickInterval: parseFloat(e.target.value) || 50 }))}
                      className="h-8 mt-1 text-xs bg-zinc-800 border-zinc-700 text-zinc-300"
                    />
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Stats */}
          <div className="border border-zinc-700 rounded-lg bg-zinc-900 overflow-hidden">
            <button
              onClick={() => setShowStats(!showStats)}
              className="flex items-center justify-between w-full px-4 py-3 text-sm font-medium text-zinc-200 hover:bg-zinc-800/50 transition-colors"
            >
              <span className="flex items-center gap-2">
                <BarChart3 size={14} className="text-zinc-400" />
                Statistics
              </span>
              {showStats ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
            </button>
            {showStats && (
              <div className="px-4 pb-4 border-t border-zinc-800 pt-3 space-y-2">
                <div className="grid grid-cols-3 gap-2">
                  <div className="text-center p-2 rounded bg-zinc-800/50">
                    <div className="text-lg font-bold text-blue-400">{stats.totalPoints}</div>
                    <div className="text-[10px] text-zinc-500">Points</div>
                  </div>
                  <div className="text-center p-2 rounded bg-zinc-800/50">
                    <div className="text-lg font-bold text-emerald-400">{stats.totalLayers}</div>
                    <div className="text-[10px] text-zinc-500">Layers</div>
                  </div>
                  <div className="text-center p-2 rounded bg-zinc-800/50">
                    <div className="text-lg font-bold text-amber-400">{stats.joinableLineCount}</div>
                    <div className="text-[10px] text-zinc-500">Lines</div>
                  </div>
                </div>

                {Object.keys(stats.pointsByCategory).length > 0 && (
                  <div className="space-y-1 mt-2">
                    <div className="text-[10px] uppercase tracking-wider text-zinc-500 font-medium">Points by Category</div>
                    {Object.entries(stats.pointsByCategory)
                      .sort(([, a], [, b]) => b - a)
                      .map(([cat, count]) => (
                        <div key={cat} className="flex items-center gap-2">
                          <span className="text-xs text-zinc-400 capitalize flex-1">{cat}</span>
                          <div className="w-16 h-1.5 bg-zinc-800 rounded-full overflow-hidden">
                            <div
                              className="h-full bg-blue-500/60 rounded-full"
                              style={{ width: `${Math.min(100, (count / stats.totalPoints) * 100)}%` }}
                            />
                          </div>
                          <span className="text-xs text-zinc-500 font-mono w-6 text-right">{count}</span>
                        </div>
                      ))}
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Layer Preview Summary */}
          {showLayerPreview && layerResults.length > 0 && (
            <div className="border border-zinc-700 rounded-lg bg-zinc-900 overflow-hidden">
              <div className="px-4 py-3">
                <div className="flex items-center gap-2 mb-2">
                  <Layers size={14} className="text-zinc-400" />
                  <span className="text-sm font-medium text-zinc-200">Layer Preview</span>
                  <Badge variant="secondary" className="text-[9px] h-4 px-1.5 bg-zinc-800 text-zinc-400 ml-auto">
                    {layerResults.length} layers
                  </Badge>
                </div>
                <ScrollArea className="max-h-[300px]">
                  <div className="space-y-1 pr-2">
                    {layerResults.map(lr => (
                      <div key={lr.layer} className="flex items-center gap-2 text-xs">
                        <span
                          className="w-2 h-2 rounded-sm shrink-0"
                          style={{
                            backgroundColor:
                              aciToHex(lr.color) === '#FFFFFF' ? '#52525b' : aciToHex(lr.color),
                          }}
                        />
                        <span className="font-mono text-zinc-400 flex-1 truncate">{lr.layer}</span>
                        <span className="text-zinc-600">{lr.points.length}</span>
                      </div>
                    ))}
                    
                  </div>
                </ScrollArea>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* ─── Code picker dialog ──────────────────────────────────────── */}
      <Dialog open={codeDialogOpen} onOpenChange={setCodeDialogOpen}>
        <DialogContent className="sm:max-w-[520px] bg-zinc-900 border-zinc-700 p-0">
          <DialogHeader className="p-4 pb-0">
            <DialogTitle className="text-zinc-100">Select Feature Code</DialogTitle>
            <DialogDescription className="text-zinc-500 text-xs">
              Choose a feature code to assign to the selected point
            </DialogDescription>
          </DialogHeader>
          <div className="p-4">
            <FeatureCodeBrowser
              onSelect={handleCodeSelect}
              selectedCode={editingPointId ? points.find(p => p.id === editingPointId)?.code : undefined}
              compact={false}
            />
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client';

/**
 * TraverseDiagram — SVG visualisation of an adjusted traverse.
 *
 * Roadmap reference: docs/ROADMAP.md → Tool page deep refits →
 * "field-book table + output diagram pattern". Renders alongside the
 * existing tabular output on `/tools/traverse`.
 *
 * Draws:
 *   - Adjusted traverse as a solid accent-coloured polyline
 *   - Raw (unadjusted) traverse as a dashed muted polyline, showing the
 *     misclosure graphically
 *   - Closing error vector (red) from raw end back to the start
 *   - Station markers (filled circles) with labels
 *   - North arrow + scale bar
 *
 * Accepts the same `result` object shape that the traverse page's
 * tabular output already consumes (cast to `any` to match the existing
 * pattern — the runtime shape differs slightly from the TS type).
 */

import { useMemo } from 'react';

interface TraverseDiagramProps {
  result: any;
}

interface Point {
  name: string;
  easting: number;
  northing: number;
}

export function TraverseDiagram({ result }: TraverseDiagramProps) {
  const WIDTH = 800;
  const HEIGHT = 500;
  const PAD = 50;

  const { adjustedPath, rawPath, closingError } = useMemo(() => {
    const legs: any[] = result.legs || [];
    if (legs.length === 0) {
      return { adjustedPath: [], rawPath: [], closingError: 0 };
    }

    // Adjusted path: use adjEasting / adjNorthing from each leg's "to" point,
    // prepend the first leg's "from" point (initial coords).
    const adjustedPath: Point[] = [];
    // The first leg's "from" station's coordinates are the known starting
    // coords. We can derive them as: adjEasting(leg[0]) - adjDeltaE(leg[0])
    // But the page's result object has `adjEasting`/`adjNorthing` on each
    // leg = the "to" station's adjusted coords. So the start point is
    // leg[0].adjEasting - leg[0].correctedDeparture (or similar).
    // Simpler: walk from the end backwards using corrected deltas.
    // Even simpler: use the raw input coords for the first point.
    // The page stores the initial N/E on the leg input; the result legs
    // only carry the "to" coords. We'll back-compute the start.
    const firstLeg = legs[0];
    const startE = firstLeg.adjEasting - (firstLeg.correctedDeparture ?? firstLeg.adjDeltaE ?? 0);
    const startN = firstLeg.adjNorthing - (firstLeg.correctedLatitude ?? firstLeg.adjDeltaN ?? 0);
    adjustedPath.push({ name: firstLeg.from, easting: startE, northing: startN });
    for (const leg of legs) {
      adjustedPath.push({
        name: leg.to,
        easting: leg.adjEasting,
        northing: leg.adjNorthing,
      });
    }

    // Raw path: walk from the same start, accumulating raw deltas.
    const rawPath: Point[] = [adjustedPath[0]];
    let curE = startE;
    let curN = startN;
    for (const leg of legs) {
      const dE = leg.departure ?? leg.rawDeltaE ?? 0;
      const dN = leg.latitude ?? leg.rawDeltaN ?? 0;
      curE += dE;
      curN += dN;
      rawPath.push({ name: leg.to, easting: curE, northing: curN });
    }

    // Closing error = distance between raw end and start
    const rawEnd = rawPath[rawPath.length - 1];
    const closingError = Math.sqrt(
      Math.pow(rawEnd.easting - startE, 2) +
      Math.pow(rawEnd.northing - startN, 2)
    );

    return { adjustedPath, rawPath, closingError };
  }, [result]);

  if (adjustedPath.length < 2) {
    return (
      <p className="text-xs text-[var(--text-muted)] py-4 text-center">
        Not enough data to plot diagram.
      </p>
    );
  }

  // Compute bounds from all points (adjusted + raw)
  const allPoints = [...adjustedPath, ...rawPath];
  const es = allPoints.map(p => p.easting);
  const ns = allPoints.map(p => p.northing);
  const minE = Math.min(...es);
  const maxE = Math.max(...es);
  const minN = Math.min(...ns);
  const maxN = Math.max(...ns);
  const dx = maxE - minE || 1;
  const dy = maxN - minN || 1;
  // Maintain aspect ratio
  const scale = Math.min((WIDTH - 2 * PAD) / dx, (HEIGHT - 2 * PAD) / dy);
  const offsetX = (WIDTH - dx * scale) / 2;
  const offsetY = (HEIGHT - dy * scale) / 2;

  const tx = (e: number) => offsetX + (e - minE) * scale;
  // Invert Y because SVG Y grows downward but Northing grows upward
  const ty = (n: number) => HEIGHT - offsetY - (n - minN) * scale;

  // Build SVG path strings
  const adjustedD = adjustedPath
    .map((p, i) => `${i === 0 ? 'M' : 'L'} ${tx(p.easting).toFixed(1)} ${ty(p.northing).toFixed(1)}`)
    .join(' ');
  const rawD = rawPath
    .map((p, i) => `${i === 0 ? 'M' : 'L'} ${tx(p.easting).toFixed(1)} ${ty(p.northing).toFixed(1)}`)
    .join(' ');

  // Closing error vector (from raw end back to start)
  const rawEnd = rawPath[rawPath.length - 1];
  const start = adjustedPath[0];

  // Scale bar: pick a round number that's about 1/4 of the diagram width
  const diagramWidthM = dx;
  const scaleBarM = niceRoundNumber(diagramWidthM / 4);
  const scaleBarPx = scaleBarM * scale;
  const scaleBarX = PAD;
  const scaleBarY = HEIGHT - 20;

  // North arrow position (top-right corner)
  const northX = WIDTH - 40;
  const northY = 40;

  return (
    <div className="w-full overflow-x-auto">
      <svg
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        className="w-full h-auto"
        style={{ minWidth: 600 }}
      >
        {/* Grid background */}
        <defs>
          <pattern id="traverse-grid" width="40" height="40" patternUnits="userSpaceOnUse">
            <path d="M 40 0 L 0 0 0 40" fill="none" stroke="var(--border-color)" strokeWidth="0.3" opacity="0.4" />
          </pattern>
        </defs>
        <rect x={PAD} y={PAD} width={WIDTH - 2 * PAD} height={HEIGHT - 2 * PAD} fill="url(#traverse-grid)" opacity="0.5" />

        {/* Raw (unadjusted) traverse — dashed muted */}
        <path
          d={rawD}
          fill="none"
          stroke="#71717a"
          strokeWidth="1.5"
          strokeDasharray="5,3"
          opacity="0.6"
        />

        {/* Closing error vector — red dashed */}
        {closingError > 0.001 && (
          <line
            x1={tx(rawEnd.easting)}
            y1={ty(rawEnd.northing)}
            x2={tx(start.easting)}
            y2={ty(start.northing)}
            stroke="#ef4444"
            strokeWidth="1.5"
            strokeDasharray="3,3"
            opacity="0.7"
          />
        )}

        {/* Adjusted traverse — solid accent */}
        <path
          d={adjustedD}
          fill="none"
          stroke="var(--accent)"
          strokeWidth="2.5"
          strokeLinejoin="round"
          strokeLinecap="round"
        />

        {/* Station markers + labels */}
        {adjustedPath.map((p, i) => {
          const isStart = i === 0;
          const isEnd = i === adjustedPath.length - 1;
          const fill = isStart ? '#22c55e' : isEnd ? '#fbbf24' : 'var(--accent)';
          return (
            <g key={`stn-${i}`}>
              <circle
                cx={tx(p.easting)}
                cy={ty(p.northing)}
                r="5"
                fill={fill}
                stroke="#1A1816"
                strokeWidth="1.5"
              />
              <text
                x={tx(p.easting) + 8}
                y={ty(p.northing) - 8}
                fontSize="11"
                fill="var(--text-primary)"
                fontFamily="monospace"
                fontWeight="600"
              >
                {p.name}
              </text>
              {isStart && (
                <text
                  x={tx(p.easting) + 8}
                  y={ty(p.northing) + 4}
                  fontSize="9"
                  fill="#22c55e"
                  fontFamily="monospace"
                >
                  START
                </text>
              )}
              {isEnd && !isStart && (
                <text
                  x={tx(p.easting) + 8}
                  y={ty(p.northing) + 4}
                  fontSize="9"
                  fill="#fbbf24"
