'use client';

/**
 * VersionDiffViewer — visual comparison of two survey plan versions
 *
 * Shows side-by-side:
 * - Beacon coordinate changes (highlighted in red/green)
 * - Boundary bearing/distance changes
 * - Area changes
 * - Metadata changes (LR number, client, etc.)
 *
 * The surveyor can see exactly what changed between revisions
 * and restore a previous version with one click.
 */

import { useState, useEffect, useCallback } from 'react'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { RotateCcw, GitCompare, ArrowRight, Check } from 'lucide-react'

interface VersionData {
  version: number
  createdAt: string
  createdBy: string
  data: {
    beacons?: Array<{ id: string; label: string; easting: number; northing: number }>
    boundaries?: Array<{ id: string; fromId: string; toId: string; bearing: string; distance: string }>
    area?: number
    lrNumber?: string
    clientName?: string
  }
}

interface DiffResult {
  beaconChanges: Array<{
    id: string; label: string
    oldEasting?: number; newEasting?: number
    oldNorthing?: number; newNorthing?: number
    deltaE: number; deltaN: number
    status: 'added' | 'removed' | 'moved' | 'unchanged'
  }>
  boundaryChanges: Array<{
    id: string
    oldBearing?: string; newBearing?: string
    oldDistance?: string; newDistance?: string
    status: 'added' | 'removed' | 'changed' | 'unchanged'
  }>
  metadataChanges: Array<{ field: string; oldValue: string; newValue: string }>
  areaChange: { old: number; new: number; delta: number }
}

interface VersionDiffViewerProps {
  entityType: string
  entityId: string
  onRestore?: (version: number) => void
}

export function VersionDiffViewer({ entityType, entityId, onRestore }: VersionDiffViewerProps) {
  const [versions, setVersions] = useState<VersionData[]>([])
  const [selectedOld, setSelectedOld] = useState<number | null>(null)
  const [selectedNew, setSelectedNew] = useState<number | null>(null)
  const [diff, setDiff] = useState<DiffResult | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    async function loadVersions() {
      try {
        const res = await fetch(`/api/versions?entity_type=${entityType}&entity_id=${entityId}&limit=50`)
        const data = await res.json()
        if (data.data) {
          setVersions(data.data)
          if (data.data.length >= 2) {
            setSelectedOld(data.data[data.data.length - 2].version)
            setSelectedNew(data.data[data.data.length - 1].version)
          }
        }
      } catch (err) {
        console.error('Failed to load versions:', err)
      } finally {
        setLoading(false)
      }
    }
    loadVersions()
  }, [entityType, entityId])

  useEffect(() => {
    if (selectedOld === null || selectedNew === null) return
    const oldVer = versions.find(v => v.version === selectedOld)
    const newVer = versions.find(v => v.version === selectedNew)
    if (!oldVer || !newVer) return
    setDiff(computeDiff(oldVer, newVer))
  }, [selectedOld, selectedNew, versions])

  const handleRestore = useCallback(() => {
    if (selectedOld !== null && onRestore) onRestore(selectedOld)
  }, [selectedOld, onRestore])

  if (loading) return <div className="text-sm text-gray-500 p-4">Loading version history...</div>

  if (versions.length < 2) {
    return (
      <div className="text-sm text-gray-500 p-4 text-center">
        <GitCompare className="w-8 h-8 mx-auto mb-2 opacity-30" />
        Need at least 2 versions to compare. Current: {versions.length} version(s).
      </div>
    )
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <select value={selectedOld ?? ''} onChange={(e) => setSelectedOld(Number(e.target.value))} className="bg-gray-800 text-white text-xs rounded px-2 py-1 border border-gray-700">
          {versions.map(v => <option key={v.version} value={v.version}>v{v.version} — {new Date(v.createdAt).toLocaleDateString()}</option>)}
        </select>
        <ArrowRight className="w-4 h-4 text-gray-500" />
        <select value={selectedNew ?? ''} onChange={(e) => setSelectedNew(Number(e.target.value))} className="bg-gray-800 text-white text-xs rounded px-2 py-1 border border-gray-700">
          {versions.map(v => <option key={v.version} value={v.version}>v{v.version} — {new Date(v.createdAt).toLocaleDateString()}</option>)}
        </select>
        <Button variant="outline" size="sm" onClick={handleRestore} className="text-xs ml-auto">
          <RotateCcw className="w-3 h-3 mr-1" /> Restore v{selectedOld}
        </Button>
      </div>

      {diff && (
        <div className="space-y-3">
          <div className="flex gap-2 flex-wrap">
            <Badge variant={diff.beaconChanges.filter(c => c.status !== 'unchanged').length > 0 ? 'destructive' : 'secondary'} className="text-xs">
              {diff.beaconChanges.filter(c => c.status === 'moved').length} moved beacons
            </Badge>
            <Badge variant={diff.metadataChanges.length > 0 ? 'destructive' : 'secondary'} className="text-xs">
              {diff.metadataChanges.length} metadata changes
            </Badge>
            <Badge variant="outline" className="text-xs">
              Area: {diff.areaChange.old.toFixed(4)} → {diff.areaChange.new.toFixed(4)} ha ({diff.areaChange.delta > 0 ? '+' : ''}{diff.areaChange.delta.toFixed(6)})
            </Badge>
          </div>

          {diff.beaconChanges.filter(c => c.status !== 'unchanged').length > 0 && (
            <Card className="p-3 bg-gray-900 border-gray-800">
              <h3 className="text-xs font-semibold text-gray-400 uppercase mb-2">Beacon Changes</h3>
              <table className="w-full text-xs">
                <thead><tr className="text-gray-500 border-b border-gray-700">
                  <th className="text-left py-1">Beacon</th><th className="text-right">Old E</th><th className="text-right">New E</th><th className="text-right">ΔE</th><th className="text-right">Old N</th><th className="text-right">New N</th><th className="text-right">ΔN</th><th className="text-center">Status</th>
                </tr></thead>
                <tbody>
                  {diff.beaconChanges.filter(c => c.status !== 'unchanged').map(c => (
                    <tr key={c.id} className="border-b border-gray-800">
                      <td className="py-1 font-mono">{c.label}</td>
                      <td className="text-right text-gray-500">{c.oldEasting?.toFixed(3) ?? '—'}</td>
                      <td className="text-right text-gray-300">{c.newEasting?.toFixed(3) ?? '—'}</td>
                      <td className={`text-right ${c.deltaE !== 0 ? 'text-yellow-400' : 'text-gray-600'}`}>{c.deltaE !== 0 ? `${c.deltaE > 0 ? '+' : ''}${c.deltaE.toFixed(3)}` : '—'}</td>
                      <td className="text-right text-gray-500">{c.oldNorthing?.toFixed(3) ?? '—'}</td>
                      <td className="text-right text-gray-300">{c.newNorthing?.toFixed(3) ?? '—'}</td>
                      <td className={`text-right ${c.deltaN !== 0 ? 'text-yellow-400' : 'text-gray-600'}`}>{c.deltaN !== 0 ? `${c.deltaN > 0 ? '+' : ''}${c.deltaN.toFixed(3)}` : '—'}</td>
                      <td className="text-center">{c.status === 'added' && <span className="text-green-400">+added</span>}{c.status === 'removed' && <span className="text-red-400">-removed</span>}{c.status === 'moved' && <span className="text-yellow-400">→moved</span>}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </Card>
          )}

          {diff.metadataChanges.length > 0 && (
            <Card className="p-3 bg-gray-900 border-gray-800">
              <h3 className="text-xs font-semibold text-gray-400 uppercase mb-2">Metadata Changes</h3>
              <div className="space-y-1">
                {diff.metadataChanges.map((c, i) => (
                  <div key={c.field} className="flex items-center gap-2 text-xs">
                    <span className="text-gray-500 w-32">{c.field}:</span>
                    <span className="text-red-400 line-through">{c.oldValue || '—'}</span>
                    <ArrowRight className="w-3 h-3 text-gray-600" />
                    <span className="text-green-400">{c.newValue || '—'}</span>
                  </div>
                ))}
              </div>
            </Card>
          )}

          {diff.beaconChanges.every(c => c.status === 'unchanged') && diff.metadataChanges.length === 0 && diff.areaChange.delta === 0 && (
            <div className="text-center py-8 text-gray-500 text-sm">
              <Check className="w-8 h-8 mx-auto mb-2 text-green-500" />
              No changes between these versions.
            </div>
          )}
        </div>
      )}
    </div>
  )
}

function computeDiff(oldVer: VersionData, newVer: VersionData): DiffResult {
  const oldBeacons = oldVer.data.beacons ?? []
  const newBeacons = newVer.data.beacons ?? []
  const oldMap = new Map(oldBeacons.map(b => [b.id, b]))
  const newMap = new Map(newBeacons.map(b => [b.id, b]))
  const beaconChanges: DiffResult['beaconChanges'] = []
  const allIds = new Set([...oldMap.keys(), ...newMap.keys()])
  for (const id of allIds) {
    const old = oldMap.get(id); const nw = newMap.get(id)
    if (!old && nw) beaconChanges.push({ id, label: nw.label, newEasting: nw.easting, newNorthing: nw.northing, deltaE: 0, deltaN: 0, status: 'added' })
    else if (old && !nw) beaconChanges.push({ id, label: old.label, oldEasting: old.easting, oldNorthing: old.northing, deltaE: 0, deltaN: 0, status: 'removed' })
    else if (old && nw) {
      const dE = nw.easting - old.easting; const dN = nw.northing - old.northing
      beaconChanges.push({ id, label: nw.label, oldEasting: old.easting, newEasting: nw.easting, oldNorthing: old.northing, newNorthing: nw.northing, deltaE: dE, deltaN: dN, status: Math.abs(dE) > 0.001 || Math.abs(dN) > 0.001 ? 'moved' : 'unchanged' })
    }
  }
  const oldBoundaries = oldVer.data.boundaries ?? []
  const newBoundaries = newVer.data.boundaries ?? []
  const oldBMap = new Map(oldBoundaries.map(b => [b.id, b]))
  const newBMap = new Map(newBoundaries.map(b => [b.id, b]))
  const boundaryChanges: DiffResult['boundaryChanges'] = []
  for (const id of new Set([...oldBMap.keys(), ...newBMap.keys()])) {
    const old = oldBMap.get(id); const nw = newBMap.get(id)
    if (!old && nw) boundaryChanges.push({ id, newBearing: nw.bearing, newDistance: nw.distance, status: 'added' })
    else if (old && !nw) boundaryChanges.push({ id, oldBearing: old.bearing, oldDistance: old.distance, status: 'removed' })
    else if (old && nw) boundaryChanges.push({ id, oldBearing: old.bearing, newBearing: nw.bearing, oldDistance: old.distance, newDistance: nw.distance, status: old.bearing !== nw.bearing || old.distance !== nw.distance ? 'changed' : 'unchanged' })
  }
  const metadataChanges: DiffResult['metadataChanges'] = []
  if (oldVer.data.lrNumber !== newVer.data.lrNumber) metadataChanges.push({ field: 'LR Number', oldValue: oldVer.data.lrNumber ?? '', newValue: newVer.data.lrNumber ?? '' })
  if (oldVer.data.clientName !== newVer.data.clientName) metadataChanges.push({ field: 'Client', oldValue: oldVer.data.clientName ?? '', newValue: newVer.data.clientName ?? '' })
  return { beaconChanges, boundaryChanges, metadataChanges, areaChange: { old: oldVer.data.area ?? 0, new: newVer.data.area ?? 0, delta: (newVer.data.area ?? 0) - (oldVer.data.area ?? 0) } }
}

'use client';

/**
 * TIN3DViewer — 3D terrain visualization using Three.js
 *
 * AUDIT FIX (2026-07-03): The main map is 2D (OpenLayers). This component
 * adds a 3D perspective for TIN surfaces and point clouds — critical for
 * engineering and drone surveys where the surveyor needs to see terrain
 * shape, not just planimetric position.
 *
 * Features:
 *   - Renders a TIN surface as a 3D wireframe + filled mesh
 *   - Orbit controls (rotate, zoom, pan)
 *   - Color-coded elevation (blue=low → red=high)
 *   - Grid helper for scale reference
 *   - Auto-fit camera to data bounds
 *
 * Dependencies: three (already in package.json)
 *
 * Usage:
 *   <TIN3DViewer surface={tinSurface} />
 *   <TIN3DViewer points={spotHeights} />
 */

import { useEffect, useRef } from 'react'
import type * as THREE from 'three'
import type { TINSurface, SpotHeight } from '@/lib/engine/contours'

interface TIN3DViewerProps {
  surface?: TINSurface | null
  points?: SpotHeight[]
  width?: number
  height?: number
}

export function TIN3DViewer({ surface, points, width = 800, height = 500 }: TIN3DViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!containerRef.current || (!surface && !points)) return

    let cleanup = () => {}

    // Dynamic import Three.js (keeps the main bundle smaller)
    import('three').then((THREE) => {
      import('three/examples/jsm/controls/OrbitControls.js').then(({ OrbitControls }) => {
        const container = containerRef.current
        if (!container) return

        // ─── Scene setup ──────────────────────────────────────────────────
        const scene = new THREE.Scene()
        scene.background = new THREE.Color(0x0a0e14)

        const camera = new THREE.PerspectiveCamera(60, width / height, 0.1, 100000)
        camera.position.set(100, 100, 100)

        const renderer = new THREE.WebGLRenderer({ antialias: true })
        renderer.setSize(width, height)
        renderer.setPixelRatio(window.devicePixelRatio)
        container.innerHTML = ''
        container.appendChild(renderer.domElement)

        // Controls
        const controls = new OrbitControls(camera, renderer.domElement)
        controls.enableDamping = true
        controls.dampingFactor = 0.1

        // ─── Compute bounds ────────────────────────────────────────────────
        const pts = surface?.points || points || []
        if (pts.length === 0) return

        const minE = Math.min(...pts.map(p => p.easting))
        const maxE = Math.max(...pts.map(p => p.easting))
        const minN = Math.min(...pts.map(p => p.northing))
        const maxN = Math.max(...pts.map(p => p.northing))
        const minZ = Math.min(...pts.map(p => p.elevation || 0))
        const maxZ = Math.max(...pts.map(p => p.elevation || 0))
        const centerE = (minE + maxE) / 2
        const centerN = (minN + maxN) / 2
        const centerZ = (minZ + maxZ) / 2
        const rangeE = maxE - minE || 1
        const rangeN = maxN - minN || 1
        const rangeZ = maxZ - minZ || 1
        const maxRange = Math.max(rangeE, rangeN)

        // ─── Color function (blue→green→yellow→red by elevation) ──────────
        const colorForElevation = (z: number): THREE.Color => {
          const t = (z - minZ) / (maxZ - minZ || 1)
          const hue = (1 - t) * 0.67  // 0.67=blue → 0=red
          return new THREE.Color().setHSL(hue, 0.8, 0.5)
        }

        // ─── Render TIN surface as mesh ────────────────────────────────────
        let geometry: any
        if (surface && surface.triangles.length > 0) {
          geometry = new THREE.BufferGeometry()
          const vertices: number[] = []
          const colors: number[] = []

          for (const tri of surface.triangles) {
            for (const p of [tri.p1, tri.p2, tri.p3]) {
              vertices.push(
                p.easting - centerE,
                p.elevation - centerZ,
                p.northing - centerN,
              )
              const c = colorForElevation(p.elevation || 0)
              colors.push(c.r, c.g, c.b)
            }
          }

          geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3))
          geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3))
          geometry.computeVertexNormals()

          const material = new THREE.MeshBasicMaterial({
            vertexColors: true,
            side: THREE.DoubleSide,
            transparent: true,
            opacity: 0.7,
          })
          scene.add(new THREE.Mesh(geometry, material))

          // Wireframe overlay
          const wireframe = new THREE.LineSegments(
            new THREE.WireframeGeometry(geometry),
            new THREE.LineBasicMaterial({ color: 0x333333, linewidth: 1 })
          )
          scene.add(wireframe)
        }

        // ─── Render points (if no TIN, or as overlay) ─────────────────────
        if (points && points.length > 0 && !surface) {
          const pointGeom = new THREE.BufferGeometry()
          const pointVerts: number[] = []
          const pointColors: number[] = []

          for (const p of points) {
            pointVerts.push(p.easting - centerE, (p.elevation || 0) - centerZ, p.northing - centerN)
            const c = colorForElevation(p.elevation || 0)
            pointColors.push(c.r, c.g, c.b)
          }

          pointGeom.setAttribute('position', new THREE.Float32BufferAttribute(pointVerts, 3))
          pointGeom.setAttribute('color', new THREE.Float32BufferAttribute(pointColors, 3))

          scene.add(new THREE.Points(pointGeom, new THREE.PointsMaterial({
            size: maxRange * 0.003,
            vertexColors: true,
            sizeAttenuation: true,
          })))
        }

        // ─── Grid helper ───────────────────────────────────────────────────
        const gridSize = Math.ceil(maxRange * 1.2)
        const grid = new THREE.GridHelper(gridSize, 10, 0x444444, 0x222222)
        grid.rotation.x = Math.PI / 2
        scene.add(grid)

        // ─── Camera position (auto-fit) ────────────────────────────────────
        const dist = maxRange * 1.5
        camera.position.set(dist, dist * 0.7, dist)
        camera.lookAt(0, 0, 0)
        controls.target.set(0, 0, 0)
        controls.update()

        // ─── Animate ───────────────────────────────────────────────────────
        let frameId = 0
        const animate = () => {
          frameId = requestAnimationFrame(animate)
          controls.update()
          renderer.render(scene, camera)
        }
        animate()

        // ─── Cleanup ───────────────────────────────────────────────────────
        cleanup = () => {
          cancelAnimationFrame(frameId)
          controls.dispose()
          renderer.dispose()
          geometry?.dispose?.()
          if (container.contains(renderer.domElement)) {
            container.removeChild(renderer.domElement)
          }
        }
      })
    }).catch(() => {
      if (containerRef.current) {
        containerRef.current.innerHTML = '<div class="p-8 text-center text-zinc-500 text-sm">3D viewer requires Three.js. Run <code class="bg-zinc-800 px-1 rounded">npm install</code> to install dependencies.</div>'
      }
    })

    return () => cleanup()
  }, [surface, points, width, height])

  return (
    <div className="relative">
      <div ref={containerRef} className="rounded-lg overflow-hidden border border-[var(--border-color)]" style={{ width, height }} />
      <div className="absolute bottom-2 left-2 text-[10px] text-zinc-500 bg-black/50 px-2 py-1 rounded">
        Drag: rotate · Scroll: zoom · Right-drag: pan
      </div>
    </div>
  )
}

'use client';
import React, { useRef } from 'react'
import type { WorkingDiagram, BoundaryType, SubArea } from '@/lib/working-diagram/types'
import { computePositions, normalizeToViewport, polygonCentroid } from '@/lib/working-diagram/traverse'
import { formatLegacy } from '@/lib/working-diagram/units'
import { NorthArrow } from './NorthArrow'
import { DiagramTitleBlock } from './DiagramTitleBlock'

interface Props {
  diagram: WorkingDiagram
  width?: number
  height?: number
}

export default function DiagramCanvas({ diagram, width = 1122, height = 794 }: Props) {
  const svgRef = useRef<SVGSVGElement>(null)
  const PADDING = 90
  const TITLE_H = 80

  const drawH = height - TITLE_H

  const rawPositions = computePositions(diagram.beacons, diagram.boundaries)
  const positions = normalizeToViewport(rawPositions, width, drawH, PADDING)

  const linePath = (fromId: string, toId: string) => {
    const a = positions.get(fromId)
    const b = positions.get(toId)
    if (!a || !b) return ''
    return `M ${a.x} ${a.y} L ${b.x} ${b.y}`
  }

  const midpoint = (fromId: string, toId: string) => {
    const a = positions.get(fromId)
    const b = positions.get(toId)
    if (!a || !b) return { x: 0, y: 0 }
    return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 }
  }

  const lineAngleDeg = (fromId: string, toId: string) => {
    const a = positions.get(fromId)
    const b = positions.get(toId)
    if (!a || !b) return 0
    const angle = Math.atan2(b.y - a.y, b.x - a.x) * (180 / Math.PI)
    return angle > 90 || angle < -90 ? angle + 180 : angle
  }

  const subAreaPolygon = (area: SubArea): string => {
    return area.beaconIds
      .map(id => {
        const p = positions.get(id)
        return p ? `${p.x},${p.y}` : ''
      })
      .filter(Boolean)
      .join(' ')
  }

  const STROKE_STYLES: Record<BoundaryType, React.SVGProps<SVGPathElement>> = {
    standard:         { stroke: '#111', strokeWidth: 1.5, strokeDasharray: 'none' },
    surveyed_road:    { stroke: '#555', strokeWidth: 1.2, strokeDasharray: 'none' },
    unsurveyed_road:  { stroke: '#555', strokeWidth: 1.2, strokeDasharray: '8 4' },
    water:            { stroke: '#4a90d9', strokeWidth: 1.5, strokeDasharray: '2 2' },
    fence:            { stroke: '#333', strokeWidth: 1, strokeDasharray: '4 2 1 2' },
  }

  return (
    <svg
      ref={svgRef}
      id="working-diagram-svg"
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      xmlns="http://www.w3.org/2000/svg"
      style={{ background: '#fff', fontFamily: 'monospace' }}
    >
      <defs>
        <pattern id="hatch" width="6" height="6" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
          <line x1="0" y1="0" x2="0" y2="6" stroke="#aaa" strokeWidth="0.8" />
        </pattern>
        <pattern id="cross_hatch" width="6" height="6" patternUnits="userSpaceOnUse">
          <line x1="0" y1="0" x2="0" y2="6" stroke="#aaa" strokeWidth="0.6" />
          <line x1="0" y1="0" x2="6" y2="0" stroke="#aaa" strokeWidth="0.6" />
        </pattern>
        <pattern id="dots" width="5" height="5" patternUnits="userSpaceOnUse">
          <circle cx="2.5" cy="2.5" r="0.8" fill="#aaa" />
        </pattern>
      </defs>

      {diagram.subAreas.map(area => (
        <polygon
          key={area.id}
          points={subAreaPolygon(area)}
          fill={
            area.fillPattern === 'none'
              ? area.fillColor
              : `url(#${area.fillPattern})`
          }
          fillOpacity={0.35}
          stroke="none"
        />
      ))}

      {diagram.boundaries.map(line => {
        const style = STROKE_STYLES[line.boundaryType]
        const mid = midpoint(line.fromBeaconId, line.toBeaconId)
        const angle = lineAngleDeg(line.fromBeaconId, line.toBeaconId)

        return (
          <g key={line.id}>
            <path
              d={linePath(line.fromBeaconId, line.toBeaconId)}
              fill="none"
              {...style}
            />
            {line.boundaryType === 'surveyed_road' && (
              <path
                d={linePath(line.fromBeaconId, line.toBeaconId)}
                fill="none"
                stroke="#555"
                strokeWidth={1.2}
                transform={`translate(0, 5)`}
              />
            )}

            <text
              x={mid.x}
              y={mid.y - 10}
              textAnchor="middle"
              fontSize={9}
              fill="#111"
              fontFamily="monospace"
              transform={`rotate(${angle}, ${mid.x}, ${mid.y})`}
            >
              {line.bearingDMS}
            </text>

            <text
              x={mid.x}
              y={mid.y + 16}
              textAnchor="middle"
              fontSize={9}
              fill="#111"
              fontFamily="monospace"
              transform={`rotate(${angle}, ${mid.x}, ${mid.y})`}
            >
              {line.distanceMeters.toFixed(2)}m
              {line.showLegacy && line.legacyUnit && line.legacyDistance !== undefined
                ? ` / ${formatLegacy(line.legacyDistance, line.legacyUnit)}`
                : ''}
            </text>

            {line.boundaryType === 'unsurveyed_road' && line.roadLabel && (
              <text
                x={mid.x}
                y={mid.y + 28}
                textAnchor="middle"
                fontSize={8}
                fill="#555"
                fontStyle="italic"
                transform={`rotate(${angle}, ${mid.x}, ${mid.y})`}
              >
                {line.roadLabel}
              </text>
            )}
            {line.boundaryType === 'surveyed_road' && line.roadLabel && (
              <text
                x={mid.x}
                y={mid.y + 28}
                textAnchor="middle"
                fontSize={8}
                fill="#555"
                transform={`rotate(${angle}, ${mid.x}, ${mid.y})`}
              >
                {line.roadLabel}
              </text>
            )}
          </g>
        )
      })}

      {diagram.beacons.map(beacon => {
        const p = positions.get(beacon.id)
        if (!p) return null
        return (
          <g key={beacon.id}>
            {beacon.symbol === 'concrete_beacon' && (
              <>
                <circle cx={p.x} cy={p.y} r={5} fill="#fff" stroke="#111" strokeWidth={1.5} />
                <circle cx={p.x} cy={p.y} r={2} fill="#111" />
              </>
            )}
            {beacon.symbol === 'iron_peg' && (
              <rect x={p.x - 3} y={p.y - 3} width={6} height={6} fill="#fff" stroke="#111" strokeWidth={1.5} />
            )}
            {beacon.symbol === 'old_beacon' && (
              <>
                <circle cx={p.x} cy={p.y} r={5} fill="none" stroke="#111" strokeWidth={1.5} strokeDasharray="2 1" />
                <circle cx={p.x} cy={p.y} r={2} fill="#111" />
              </>
            )}
            {(beacon.symbol === 'reference_mark' || beacon.symbol === 'intersection_beacon') && (
              <>
                <line x1={p.x - 6} y1={p.y} x2={p.x + 6} y2={p.y} stroke="#111" strokeWidth={1.2} />
                <line x1={p.x} y1={p.y - 6} x2={p.x} y2={p.y + 6} stroke="#111" strokeWidth={1.2} />
              </>
            )}
            {beacon.symbol === 'nail' && (
              <circle cx={p.x} cy={p.y} r={2} fill="#111" />
            )}
            {beacon.symbol === 'none' && (
              <circle cx={p.x} cy={p.y} r={2} fill="none" stroke="#111" strokeWidth={1} />
            )}
            <text
              x={p.x + 7}
              y={p.y - 5}
              fontSize={9}
              fontWeight="bold"
              fill="#111"
              fontFamily="monospace"
            >
              {beacon.label}
            </text>
          </g>
        )
      })}

      {diagram.subAreas.map((area: any) => {
        const centroid = polygonCentroid(area.beaconIds, positions)
        return (
          <g key={area.id}>
            <text
              x={centroid.x}
              y={centroid.y - 8}
              textAnchor="middle"
              fontSize={11}
              fontWeight="bold"
              fill="#222"
              fontFamily="monospace"
            >
              {area.label}
            </text>
            <text
              x={centroid.x}
              y={centroid.y + 8}
              textAnchor="middle"
              fontSize={10}
              fill="#222"
              fontFamily="monospace"
            >
              {area.areaHa.toFixed(4)} Ha
            </text>
            {area.areaAcres !== undefined && (
              <text
                x={centroid.x}
                y={centroid.y + 22}
                textAnchor="middle"
                fontSize={9}
                fill="#555"
                fontFamily="monospace"
              >
                ({area.areaAcres.toFixed(3)} Ac)
              </text>
            )}
          </g>
        )
      })}

      <NorthArrow
        x={width - 70}
        y={40}
        bearing={diagram.north.bearing}
        type={diagram.north.type}
      />

      <DiagramTitleBlock
        y={drawH}
        width={width}
        height={TITLE_H}
        titleBlock={diagram.titleBlock}
      />

      <rect
        x={4} y={4}
        width={width - 8}
        height={height - 8}
        fill="none"
        stroke="#111"
        strokeWidth={2}
      />
      <rect
        x={8} y={8}
        width={width - 16}
        height={height - 16}
        fill="none"
        stroke="#111"
        strokeWidth={0.5}
      />
    </svg>
  )
}

'use client';
import type { LegacyUnit } from '@/lib/working-diagram/types'
import { metersToLegacy, formatLegacy } from '@/lib/working-diagram/units'

interface Props {
  showLegacy: boolean
  onShowLegacyChange: (show: boolean) => void
  legacyUnit: LegacyUnit | undefined
  onLegacyUnitChange: (unit: LegacyUnit) => void
  distanceMeters: number
  legacyDistance?: number
  onLegacyDistanceChange?: (distance: number) => void
}

const UNIT_OPTIONS: { value: LegacyUnit; label: string }[] = [
  { value: 'perches', label: 'Perches (P)' },
  { value: 'links', label: 'Links (Lk)' },
  { value: 'chains', label: 'Chains (Ch)' },
  { value: 'feet', label: 'Feet (ft)' },
]

export function LegacyUnitBadge({
  showLegacy,
  onShowLegacyChange,
  legacyUnit,
  onLegacyUnitChange,
  distanceMeters,
  legacyDistance,
  onLegacyDistanceChange,
}: Props) {
  const autoCalculated = legacyUnit ? metersToLegacy(distanceMeters, legacyUnit) : 0

  return (
    <div className="space-y-2 border p-2 rounded bg-gray-50">
      <label className="flex items-center gap-2 text-sm">
        <input aria-label="Showlegacy"
          type="checkbox"
          checked={showLegacy}
          onChange={(e) => onShowLegacyChange(e.target.checked)}
          className="rounded"
        />
        Show legacy units
      </label>

      {showLegacy && (
        <div className="space-y-2">
          <select
            value={legacyUnit || 'perches'}
            onChange={(e) => onLegacyUnitChange(e.target.value as LegacyUnit)}
            className="w-full px-2 py-1.5 border border-gray-300 rounded text-sm"
          >
            {UNIT_OPTIONS.map((opt: any) => (
              <option key={opt.value} value={opt.value}>{opt.label}</option>
            ))}
          </select>
          
          <div className="flex items-center gap-2">
            <label className="text-xs text-gray-500" htmlFor="legacy">Legacy:</label>
            <input aria-label="Legacy:"
              type="number"
              step="0.01"
              value={legacyDistance ?? autoCalculated}
              onChange={(e) => onLegacyDistanceChange?.(parseFloat(e.target.value))}
              className="flex-1 px-2 py-1 border border-gray-300 rounded text-sm"
            />
            <span className="text-xs text-gray-500">
              {legacyUnit ? formatLegacy(legacyDistance ?? autoCalculated, legacyUnit) : ''}
            </span>
          </div>
          
          <div className="text-xs text-gray-400">
            Auto: {autoCalculated.toFixed(3)} {legacyUnit}
          </div>
        </div>
      )}
    </div>
  )
}

'use client';
import type { BoundaryType } from '@/lib/working-diagram/types'

interface Props {
  value: BoundaryType
  onChange: (value: BoundaryType) => void
  roadLabel?: string
  onRoadLabelChange?: (label: string) => void
}

const BOUNDARY_OPTIONS: { value: BoundaryType; label: string; preview: string }[] = [
  { value: 'standard', label: 'Standard boundary', preview: '————————' },
  { value: 'surveyed_road', label: 'Surveyed road', preview: '══════════' },
  { value: 'unsurveyed_road', label: 'Unsurveyed road', preview: '- - - - - -' },
  { value: 'water', label: 'Water boundary', preview: '≈≈≈≈≈≈≈≈' },
  { value: 'fence', label: 'Fence', preview: '—·—·—·—·' },
]

export function RoadBoundarySelector({ value, onChange, roadLabel, onRoadLabelChange }: Props) {
  return (
    <div className="space-y-2">
      <label className="block text-sm font-medium text-gray-700" htmlFor="boundary-type">Boundary Type</label>
      <select id="boundary-type"
        value={value}
        onChange={(e) => onChange(e.target.value as BoundaryType)}
        className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
      >
        {BOUNDARY_OPTIONS.map((opt: any) => (
          <option key={opt.value} value={opt.value}>
            {opt.label}
          </option>
        ))}
      </select>
      <div className="flex gap-2 mt-2">
        {BOUNDARY_OPTIONS.map((opt: any) => (
          value === opt.value && (
            <span key={opt.value} className="text-xs text-gray-500 font-mono">
              {opt.preview}
            </span>
          )
        ))}
      </div>
      {(value === 'surveyed_road' || value === 'unsurveyed_road') && (
        <div className="mt-2">
          <label className="block text-xs text-gray-500" htmlFor="road-label">Road Label</label>
          <input aria-label="Road Label"
            type="text"
            value={roadLabel || ''}
            onChange={(e) => onRoadLabelChange?.(e.target.value)}
            placeholder={value === 'unsurveyed_road' ? 'Unsurveyed road' : 'ZLde road'}
            className="w-full px-3 py-1.5 border border-gray-300 rounded-md text-sm mt-1"
          />
        </div>
      )}
    </div>
  )
}

'use client';
import type { SubArea, BeaconPoint } from '@/lib/working-diagram/types'

interface Props {
  subAreas: SubArea[]
  beacons: BeaconPoint[]
  onAdd: () => void
  onUpdate: (id: string, updates: Partial<SubArea>) => void
  onRemove: (id: string) => void
}

const FILL_PATTERNS = [
  { value: 'none', label: 'None' },
  { value: 'hatch', label: 'Hatch' },
  { value: 'cross_hatch', label: 'Cross Hatch' },
  { value: 'dots', label: 'Dots' },
]

const FILL_COLORS = [
  '#f0f4e8', '#e8f4f0', '#f4e8f0', '#e8f0f4', '#f0e8f4',
]

export function SubAreaPanel({ subAreas, beacons, onAdd, onUpdate, onRemove }: Props) {
  const nextId = String.fromCharCode(65 + subAreas.length)

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="font-medium">Sub-Areas</h3>
        <button
          onClick={onAdd}
          className="px-3 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700"
        >
          + Add Area {nextId}
        </button>
      </div>

      {subAreas.length === 0 && (
        <p className="text-sm text-gray-500">No sub-areas defined. Click Add to create one.</p>
      )}

      {subAreas.map((area, idx) => (
        <div key={area.id} className="border rounded p-3 space-y-2 bg-white">
          <div className="flex items-center justify-between">
            <span className="font-medium text-sm">Area {area.id}</span>
            <button
              onClick={() => onRemove(area.id)}
              className="text-red-500 text-xs hover:underline"
            >
              Remove
            </button>
          </div>

          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-xs text-gray-500" htmlFor="label">Label</label>
              <input id="label" aria-label="Label"
                type="text"
                value={area.label}
                onChange={(e) => onUpdate(area.id, { label: e.target.value })}
                className="w-full px-2 py-1 border rounded text-sm"
              />
            </div>
            <div>
              <label className="block text-xs text-gray-500" htmlFor="area-ha">Area (Ha)</label>
              <input id="area-ha" aria-label="Areaha"
                type="number"
                step="0.0001"
                value={area.areaHa}
                onChange={(e) => onUpdate(area.id, { 
                  areaHa: parseFloat(e.target.value),
                  areaAcres: parseFloat(e.target.value) * 2.47105
                })}
                className="w-full px-2 py-1 border rounded text-sm"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs text-gray-500" htmlFor="beacons-ordered">Beacons (ordered)</label>
            <select id="beacons-ordered"
              multiple
              value={area.beaconIds}
              onChange={(e) => {
                const selected = Array.from(e.target.selectedOptions, opt => opt.value)
                onUpdate(area.id, { beaconIds: selected })
              }}
              className="w-full px-2 py-1 border rounded text-sm h-20"
            >
              {beacons.map((b: any) => (
                <option key={b.id} value={b.id}>{b.label}</option>
              ))}
            </select>
            <p className="text-xs text-gray-400">Hold Ctrl/Cmd to select multiple</p>
          </div>

          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="block text-xs text-gray-500" htmlFor="fill-pattern">Fill Pattern</label>
              <select id="fill-pattern"
                value={area.fillPattern}
                onChange={(e) => onUpdate(area.id, { fillPattern: e.target.value as SubArea['fillPattern'] })}
                className="w-full px-2 py-1 border rounded text-sm"
              >
                {FILL_PATTERNS.map((p: any) => (
                  <option key={p.value} value={p.value}>{p.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs text-gray-500" htmlFor="fill-color">Fill Color</label>
              <input aria-label="Fillcolor"
                type="color"
                value={area.fillColor}
                onChange={(e) => onUpdate(area.id, { fillColor: e.target.value })}
                className="w-full h-7 border rounded"
              />
            </div>
          </div>

          <div className="text-xs text-gray-500">
            {area.areaAcres !== undefined && `(${area.areaAcres.toFixed(3)} Ac)`}
          </div>
        </div>
      ))}
    </div>
  )
}

'use client';
import { useState, useRef } from 'react'
import dynamic from 'next/dynamic'
import type { WorkingDiagram, BeaconPoint, BoundaryLine, SubArea, BoundaryType, LegacyUnit } from '@/lib/working-diagram/types'
import { metersToLegacy, degToDMS, dmsToDeg } from '@/lib/working-diagram/units'
import { RoadBoundarySelector } from './RoadBoundarySelector'
import { LegacyUnitBadge } from './LegacyUnitBadge'
import { SubAreaPanel } from './SubAreaPanel'

const DiagramCanvas = dynamic(() => import('./DiagramCanvas'), { ssr: false })

const createEmptyDiagram = (): WorkingDiagram => ({
  id: crypto.randomUUID(),
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
  titleBlock: {
    drawingTitle: 'WORKING DIAGRAM',
    surveyorName: '',
    surveyorRegNo: '',
    county: '',
    subcounty: '',
    scaleNote: 'Dimensions in Metres',
    utmZone: '37S',
    date: new Date().toISOString().split('T')[0],
  },
  north: {
    bearing: '0° 00\' 00\'\'',
    type: 'grid',
  },
  beacons: [],
  boundaries: [],
  subAreas: [],
})

type TabType = 'title' | 'beacons' | 'boundaries' | 'subareas' | 'north'

export default function WorkingDiagramClient() {
  const [diagram, setDiagram] = useState<WorkingDiagram>(createEmptyDiagram)
  const [activeTab, setActiveTab] = useState<TabType>('title')
  const svgRef = useRef<HTMLDivElement>(null)

  const addBeacon = () => {
    const id = `B${diagram.beacons.length + 1}`
    const newBeacon: BeaconPoint = {
      id,
      label: id,
      symbol: 'concrete_beacon',
    }
    setDiagram(d => ({ ...d, beacons: [...d.beacons, newBeacon] }))
  }

  const updateBeacon = (id: string, updates: Partial<BeaconPoint>) => {
    setDiagram(d => ({
      ...d,
      beacons: d.beacons.map((b: any) => b.id === id ? { ...b, ...updates } : b),
    }))
  }

  const removeBeacon = (id: string) => {
    setDiagram(d => ({
      ...d,
      beacons: d.beacons.filter((b: any) => b.id !== id),
      boundaries: d.boundaries.filter((b: any) => b.fromBeaconId !== id && b.toBeaconId !== id),
    }))
  }

  const addBoundary = () => {
    if (diagram.beacons.length < 2) return
    const idx = diagram.boundaries.length
    const fromBeacon = diagram.beacons[idx]?.id || diagram.beacons[0].id
    const toBeacon = diagram.beacons[idx + 1]?.id || diagram.beacons[1].id
    const newBoundary: BoundaryLine = {
      id: `L${idx + 1}`,
      fromBeaconId: fromBeacon,
      toBeaconId: toBeacon,
      bearingDeg: 0,
      bearingDMS: '0° 00\' 00\'\'',
      distanceMeters: 0,
      showLegacy: false,
      boundaryType: 'standard',
    }
    setDiagram(d => ({ ...d, boundaries: [...d.boundaries, newBoundary] }))
  }

  const updateBoundary = (id: string, updates: Partial<BoundaryLine>) => {
    setDiagram(d => {
      const boundaries = d.boundaries.map((b: any) => {
        if (b.id !== id) return b
        const updated = { ...b, ...updates }
        if (updates.bearingDMS !== undefined) {
          updated.bearingDeg = dmsToDeg(updates.bearingDMS)
        }
        if (updates.distanceMeters !== undefined && updated.showLegacy && updated.legacyUnit) {
          updated.legacyDistance = metersToLegacy(updates.distanceMeters, updated.legacyUnit)
        }
        return updated
      })
      return { ...d, boundaries }
    })
  }

  const removeBoundary = (id: string) => {
    setDiagram(d => ({ ...d, boundaries: d.boundaries.filter((b: any) => b.id !== id) }))
  }

  const addSubArea = () => {
    const id = String.fromCharCode(65 + diagram.subAreas.length)
    const newArea: SubArea = {
      id,
      label: `AREA ${id}`,
      areaHa: 0,
      beaconIds: [],
      fillPattern: 'none',
      fillColor: '#f0f4e8',
    }
    setDiagram(d => ({ ...d, subAreas: [...d.subAreas, newArea] }))
  }

  const updateSubArea = (id: string, updates: Partial<SubArea>) => {
    setDiagram(d => ({
      ...d,
      subAreas: d.subAreas.map((a: any) => a.id === id ? { ...a, ...updates } : a),
    }))
  }

  const removeSubArea = (id: string) => {
    setDiagram(d => ({ ...d, subAreas: d.subAreas.filter((a: any) => a.id !== id) }))
  }

  const exportSVG = () => {
    const svg = document.getElementById('working-diagram-svg')
    if (!svg) return
    const svgData = new XMLSerializer().serializeToString(svg)
    const blob = new Blob([svgData], { type: 'image/svg+xml' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `working-diagram-${diagram.titleBlock.parcelRef || 'export'}.svg`
    a.click()
    URL.revokeObjectURL(url)
  }

  const tabs: { id: TabType; label: string }[] = [
    { id: 'title', label: 'Title Block' },
    { id: 'beacons', label: 'Beacons' },
    { id: 'boundaries', label: 'Boundaries' },
    { id: 'subareas', label: 'Sub-Areas' },
    { id: 'north', label: 'North / Units' },
  ]

  return (
    <div className="flex flex-col h-screen">
      <div className="flex items-center justify-between px-4 py-3 bg-white border-b">
        <h1 className="text-xl font-semibold">Working Diagram</h1>
        <div className="flex gap-2">
          <button onClick={() => setDiagram(createEmptyDiagram())} className="px-3 py-1.5 text-sm border rounded hover:bg-gray-50">New</button>
          <button onClick={exportSVG} className="px-3 py-1.5 text-sm border rounded hover:bg-gray-50">Export SVG</button>
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        <div className="w-[320px] md:w-[380px] border-r bg-white overflow-y-auto p-4">
          <div className="flex border-b mb-4">
            {tabs.map((tab: any) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`px-3 py-2 text-sm font-medium ${activeTab === tab.id ? 'border-b-2 border-blue-600 text-blue-600' : 'text-gray-500'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>

          {activeTab === 'title' && (
            <div className="space-y-3">
              <div>
                <label className="block text-xs text-gray-500" htmlFor="drawing-title">Drawing Title</label>
                <input id="drawing-title" type="text" value={diagram.titleBlock.drawingTitle} onChange={e => setDiagram(d => ({ ...d, titleBlock: { ...d.titleBlock, drawingTitle: e.target.value } }))} className="w-full px-2 py-1 border rounded text-sm" />
              </div>
              <div>
                <label className="block text-xs text-gray-500" htmlFor="surveyor-name">Surveyor Name</label>
