                      {diagram.beacons.map((b: any) => <option key={b.id} value={b.id}>{b.label}</option>)}
                    </select>
                    <select value={boundary.toBeaconId} onChange={e => updateBoundary(boundary.id, { toBeaconId: e.target.value })} className="w-full px-2 py-1 border rounded text-sm">
                      {diagram.beacons.map((b: any) => <option key={b.id} value={b.id}>{b.label}</option>)}
                    </select>
                  </div>
                  <input type="text" value={boundary.bearingDMS} onChange={e => updateBoundary(boundary.id, { bearingDMS: e.target.value })} aria-label="0° 00' 00''" placeholder="0° 00' 00''" className="w-full px-2 py-1 border rounded text-sm" />
                  <input type="number" step="0.01" value={boundary.distanceMeters} onChange={e => updateBoundary(boundary.id, { distanceMeters: parseFloat(e.target.value) })} aria-label="Distance (m)" placeholder="Distance (m)" className="w-full px-2 py-1 border rounded text-sm" />
                  <RoadBoundarySelector value={boundary.boundaryType} onChange={v => updateBoundary(boundary.id, { boundaryType: v })} roadLabel={boundary.roadLabel} onRoadLabelChange={v => updateBoundary(boundary.id, { roadLabel: v })} />
                  <LegacyUnitBadge showLegacy={boundary.showLegacy} onShowLegacyChange={v => updateBoundary(boundary.id, { showLegacy: v })} legacyUnit={boundary.legacyUnit} onLegacyUnitChange={v => updateBoundary(boundary.id, { legacyUnit: v, legacyDistance: metersToLegacy(boundary.distanceMeters, v) })} distanceMeters={boundary.distanceMeters} legacyDistance={boundary.legacyDistance} onLegacyDistanceChange={v => updateBoundary(boundary.id, { legacyDistance: v })} />
                </div>
              ))}
            </div>
          )}

          {activeTab === 'subareas' && (
            <SubAreaPanel subAreas={diagram.subAreas} beacons={diagram.beacons} onAdd={addSubArea} onUpdate={updateSubArea} onRemove={removeSubArea} />
          )}

          {activeTab === 'north' && (
            <div className="space-y-3">
              <div>
                <label className="block text-xs text-gray-500" htmlFor="north-bearing">North Bearing</label>
                <input id="north-bearing" type="text" value={diagram.north.bearing} onChange={e => setDiagram(d => ({ ...d, north: { ...d.north, bearing: e.target.value } }))} className="w-full px-2 py-1 border rounded text-sm" aria-label="0° 00' 00''" placeholder="0° 00' 00''" />
              </div>
              <div>
                <label className="block text-xs text-gray-500" htmlFor="north-type">North Type</label>
                <select id="north-type" value={diagram.north.type} onChange={e => setDiagram(d => ({ ...d, north: { ...d.north, type: e.target.value as 'grid' | 'true' | 'magnetic' } }))} className="w-full px-2 py-1 border rounded text-sm">
                  <option value="grid">Grid North</option>
                  <option value="true">True North</option>
                  <option value="magnetic">Magnetic North</option>
                </select>
              </div>
              <div>
                <label className="block text-xs text-gray-500" htmlFor="scale-note">Scale Note</label>
                <select value={diagram.titleBlock.scaleNote} onChange={e => setDiagram(d => ({ ...d, titleBlock: { ...d.titleBlock, scaleNote: e.target.value } }))} className="w-full px-2 py-1 border rounded text-sm">
                  <option value="Dimensions in Metres">Dimensions in Metres</option>
                  <option value="Dimensions in Metres and Perches">Dimensions in Metres and Perches</option>
                  <option value="Dimensions in Metres and Links">Dimensions in Metres and Links</option>
                  <option value="Dimensions in Metres and Chains">Dimensions in Metres and Chains</option>
                </select>
              </div>
            </div>
          )}
        </div>

        <div className="flex-1 overflow-auto p-4 bg-gray-100" ref={svgRef}>
          <div className="bg-white shadow-lg inline-block">
            <DiagramCanvas diagram={diagram} />
          </div>
        </div>
      </div>
    </div>
  )
}

'use client'

/**
 * AutomationPanel — Shows what's been auto-computed in the project.
 *
 * Displays the automation chain for the current project type, showing:
 *   - Which computations have run automatically
 *   - Which are pending (waiting for data)
 *   - Which failed (need attention)
 *   - Which are blocking export
 *
 * This replaces the need to visit 73 separate tool pages — everything
 * runs from the project workspace automatically.
 */

import { useState, useEffect } from 'react'
import {
  getAutomationChains,
  getAutomationSummary,
  type AutomationTrigger,
  type AutomationStep,
} from '@/lib/workflows/workflowAutomation'
import type { SurveyType } from '@/types/project'
import {
  CheckCircle2, XCircle, Loader2, Clock, AlertTriangle,
  Zap, ChevronDown, ChevronRight,
} from 'lucide-react'

interface AutomationPanelProps {
  surveyType: SurveyType
  /** Current workflow step (1-5) — determines which automations are active */
  currentStep?: number
}

const TRIGGER_LABELS: Record<AutomationTrigger, string> = {
  fieldbook_saved: 'When Field Book is Saved',
  points_imported: 'When Points are Imported',
  alignment_entered: 'When Alignment is Entered',
  drone_processed: 'When Drone Processing Completes',
  pre_export: 'Before Export (Final Checks)',
}

const STEP_TO_TRIGGER: Record<number, AutomationTrigger[]> = {
  1: [], // Setup — no automations
  2: ['fieldbook_saved', 'points_imported', 'alignment_entered'], // Field Book
  3: ['fieldbook_saved'], // Compute
  4: [], // Review
  5: [], // Topo
  6: ['pre_export'], // Submission
}

export function AutomationPanel({ surveyType, currentStep = 1 }: AutomationPanelProps) {
  const [expandedTriggers, setExpandedTriggers] = useState<Set<AutomationTrigger>>(new Set())
  const chains = getAutomationChains(surveyType)
  const summary = getAutomationSummary(surveyType)

  // Filter to only show triggers relevant to the current step
  const relevantTriggers = STEP_TO_TRIGGER[currentStep] || []
  const activeTriggers = relevantTriggers.length > 0
    ? relevantTriggers
    : Object.keys(chains) as AutomationTrigger[]

  const toggleTrigger = (trigger: AutomationTrigger) => {
    setExpandedTriggers(prev => {
      const next = new Set(prev)
      if (next.has(trigger)) next.delete(trigger)
      else next.add(trigger)
      return next
    })
  }

  const allSteps = activeTriggers.flatMap(t => chains[t] || [])
  const totalSteps = allSteps.length
  const blockingSteps = allSteps.filter(s => s.blocking)

  return (
    <div className="rounded-2xl border border-[var(--border-color)] bg-[var(--bg-card)] p-4">
      {/* Header */}
      <div className="flex items-center gap-3 mb-4">
        <div className="w-8 h-8 rounded-lg bg-[var(--accent)]/10 border border-[var(--accent)]/20 flex items-center justify-center">
          <Zap className="w-4 h-4 text-[var(--accent)]" />
        </div>
        <div className="flex-1">
          <h3 className="text-sm font-bold text-[var(--text-primary)]">Workflow Automation</h3>
          <p className="text-[10px] text-[var(--text-muted)]">
            {totalSteps} steps · {blockingSteps.length} blocking · runs automatically
          </p>
        </div>
      </div>

      {/* Summary banner */}
      <div className="bg-[var(--accent)]/5 border border-[var(--accent)]/15 rounded-lg p-3 mb-4">
        <p className="text-xs text-[var(--text-secondary)] leading-relaxed">
          {summary}
        </p>
      </div>

      {/* Automation chains */}
      <div className="space-y-2">
        {activeTriggers.map(trigger => {
          const steps = chains[trigger] || []
          if (steps.length === 0) return null

          const isExpanded = expandedTriggers.has(trigger)
          const completedCount = steps.filter(s => s.status === 'completed').length
          const failedCount = steps.filter(s => s.status === 'failed').length

          return (
            <div key={trigger} className="rounded-lg border border-[var(--border-color)] overflow-hidden">
              {/* Trigger header */}
              <button
                onClick={() => toggleTrigger(trigger)}
                className="w-full flex items-center justify-between p-3 hover:bg-[var(--bg-tertiary)] transition-colors"
              >
                <div className="flex items-center gap-2">
                  {isExpanded
                    ? <ChevronDown className="w-3.5 h-3.5 text-[var(--text-muted)]" />
                    : <ChevronRight className="w-3.5 h-3.5 text-[var(--text-muted)]" />
                  }
                  <span className="text-xs font-semibold text-[var(--text-primary)]">
                    {TRIGGER_LABELS[trigger]}
                  </span>
                </div>
                <div className="flex items-center gap-2 text-[10px]">
                  {completedCount > 0 && (
                    <span className="text-emerald-400">{completedCount} </span>
                  )}
                  {failedCount > 0 && (
                    <span className="text-red-400">{failedCount} </span>
                  )}
                  <span className="text-[var(--text-muted)]">{steps.length} steps</span>
                </div>
              </button>

              {/* Steps (expanded) */}
              {isExpanded && (
                <div className="border-t border-[var(--border-color)] divide-y divide-[var(--border-color)]">
                  {steps.map(step => (
                    <div key={step.id} className="flex items-start gap-2 p-2.5">
                      {/* Status icon */}
                      <div className="shrink-0 mt-0.5">
                        {step.status === 'completed' && <CheckCircle2 className="w-4 h-4 text-emerald-400" />}
                        {step.status === 'failed' && <XCircle className="w-4 h-4 text-red-400" />}
                        {step.status === 'running' && <Loader2 className="w-4 h-4 text-amber-400 animate-spin" />}
                        {step.status === 'pending' && <Clock className="w-4 h-4 text-[var(--text-muted)]" />}
                        {step.status === 'skipped' && <div className="w-4 h-4 rounded-full border border-[var(--text-muted)] opacity-30" />}
                      </div>

                      {/* Step info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-1.5">
                          <span className="text-xs font-medium text-[var(--text-primary)] truncate">
                            {step.name}
                          </span>
                          {step.blocking && (
                            <span className="text-[8px] px-1 py-0.5 rounded bg-red-500/10 text-red-400 font-semibold uppercase">
                              Blocking
                            </span>
                          )}
                        </div>
                        <p className="text-[10px] text-[var(--text-muted)] mt-0.5">
                          {step.description}
                        </p>
                        {step.result && (
                          <p className="text-[10px] text-emerald-400 mt-1">{step.result}</p>
                        )}
                        {step.error && (
                          <p className="text-[10px] text-red-400 mt-1 flex items-start gap-1">
                            <AlertTriangle className="w-2.5 h-2.5 shrink-0 mt-0.5" />
                            {step.error}
                          </p>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )
        })}
      </div>

      {/* Export readiness */}
      {currentStep >= 5 && (
        <div className="mt-4 p-3 rounded-lg border border-[var(--border-color)] bg-[var(--bg-tertiary)]/50">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-[var(--text-primary)]">Export Readiness</span>
            <span className="text-[10px] text-[var(--text-muted)]">
              {blockingSteps.length} blocking step(s) must pass
            </span>
          </div>
          <div className="mt-2 h-2 bg-[var(--bg-primary)] rounded-full overflow-hidden">
            <div
              className="h-full bg-emerald-500 transition-all duration-500"
              style={{ width: `${Math.max(0, 100 - (blockingSteps.length * 20))}%` }}
            />
          </div>
        </div>
      )}
    </div>
  )
}

'use client';

import { useEffect, useState } from 'react';
import { Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { runTraverseComputation, TraverseComputationResult } from '@/lib/compute/traverseRunner';
import { FieldBookRow } from '@/types/fieldbook';

export default function CadastralComputeIntegration({ projectId }: { projectId: string }) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<TraverseComputationResult | null>(null);
  const [rows, setRows] = useState<FieldBookRow[]>([]);

  useEffect(() => {
    async function loadAndCompute() {
      try {
        setLoading(true);
        const res = await fetch(`/api/project/${projectId}/fieldbook`);
        if (!res.ok) throw new Error('Failed to fetch field book data');
        const json = await res.json();
        
        if (!json.data || json.data.length === 0) {
          setError('No field book data found. Please complete Step 2 first.');
          setLoading(false);
          return;
        }

        const rawRows: FieldBookRow[] = json.data.map((r: any) => ({
          ...r.raw_data,
          station: r.station || r.raw_data?.station,
          distance: r.raw_data?.distance,
          bearing: r.raw_data?.bearing,
        }));
        
        setRows(rawRows);

        // Attempt computation
        try {
          const computation = runTraverseComputation({
            rows: rawRows,
            startPoint: { name: 'ST1', easting: 250000, northing: 9800000 },
            surveyType: 'cadastral',
            method: 'bowditch'
          });
          setResult(computation);

          // Save computation to project boundary_data for the Map
          const { createClient } = await import('@/lib/api-client/client');
          const dbClient = createClient();
          
          const adjustedStations = computation.adjustedStations.legs.map((leg: any) => ({
            pointName: leg.to,
            originalEasting: leg.adjEasting - leg.correctionE,
            originalNorthing: leg.adjNorthing - leg.correctionN,
            adjustedEasting: leg.adjEasting,
            adjustedNorthing: leg.adjNorthing,
          }));

          // Ensure the start point is included
          adjustedStations.unshift({
             pointName: 'ST1',
             originalEasting: 250000,
             originalNorthing: 9800000,
             adjustedEasting: 250000,
             adjustedNorthing: 9800000,
          });

          await dbClient
            .from('projects')
            .update({ boundary_data: { adjustedStations } })
            .eq('id', projectId);

        } catch (compErr: any) {
          setError(compErr.message || 'Failed to compute traverse from field book data. Ensure distances and bearings are entered correctly.');
        }

      } catch (err: unknown) {
        setError((err as Error).message);
      } finally {
        setLoading(false);
      }
    }

    loadAndCompute();
  }, [projectId]);

  if (loading) {
    return (
      <div className="rounded-lg border border-[var(--border-color)] bg-[var(--bg-card)] p-8 text-center">
        <Loader2 className="w-6 h-6 animate-spin mx-auto text-[var(--accent)] mb-3" />
        <p className="text-sm text-[var(--text-muted)]">Loading Field Book & Running Computations...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 p-5">
        <div className="flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
          <div>
            <h3 className="font-semibold text-amber-500 mb-1">Computation Warning</h3>
            <p className="text-sm text-amber-500/80">{error}</p>
          </div>
        </div>
      </div>
    );
  }

  if (!result) return null;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg">
          <div className="text-[10px] text-[var(--text-muted)]">Precision Grade</div>
          <div className="text-sm font-bold text-[var(--text-primary)] uppercase">{result.adjustedStations.precisionGrade}</div>
        </div>
        <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg">
          <div className="text-[10px] text-[var(--text-muted)]">Precision Ratio</div>
          <div className="text-sm font-bold text-[var(--text-primary)]">1 : {Math.round(1 / result.adjustedStations.precisionRatio)}</div>
        </div>
        <div className="p-3 bg-[var(--bg-tertiary)] rounded-lg">
          <div className="text-[10px] text-[var(--text-muted)]">Linear Misclosure</div>
          <div className="text-sm font-bold text-[var(--text-primary)]">{result.linearMisclosure.toFixed(4)} m</div>
        </div>
        <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-lg">
          <div className="text-[10px] text-emerald-400">Computed Area</div>
          <div className="text-sm font-bold text-emerald-400">{(result.adjustedAreaM2 / 10000).toFixed(6)} ha</div>
        </div>
      </div>

      <div className="border border-[var(--border-color)] rounded-xl overflow-hidden bg-[var(--bg-card)]">
        <div className="px-4 py-3 border-b border-[var(--border-color)] bg-[var(--bg-secondary)]">
          <h4 className="text-sm font-semibold text-[var(--text-primary)]">Table 1 — Bowditch Adjusted Coordinates</h4>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="text-left text-[10px] text-[var(--text-muted)] border-b border-[var(--border-color)]">
                <th className="px-3 py-2">Station</th>
                <th className="px-3 py-2 text-right">Raw Easting (m)</th>
                <th className="px-3 py-2 text-right">Raw Northing (m)</th>
                <th className="px-3 py-2 text-right">Adj Easting (m)</th>
                <th className="px-3 py-2 text-right">Adj Northing (m)</th>
              </tr>
            </thead>
            <tbody>
              {result.adjustedStations.legs.map((c, i) => (
                <tr key={`${c}-${i}`} className="border-b border-[var(--border-color)]/30 hover:bg-[var(--bg-secondary)]">
                  <td className="px-3 py-2 font-mono text-[var(--accent)]">{c.to}</td>
                  <td className="px-3 py-2 font-mono text-right text-[var(--text-muted)]">{(c.adjEasting - c.correctionE).toFixed(4)}</td>
                  <td className="px-3 py-2 font-mono text-right text-[var(--text-muted)]">{(c.adjNorthing - c.correctionN).toFixed(4)}</td>
                  <td className="px-3 py-2 font-mono text-right font-semibold">{c.adjEasting.toFixed(4)}</td>
                  <td className="px-3 py-2 font-mono text-right font-semibold">{c.adjNorthing.toFixed(4)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      
      <div className="flex items-center gap-2 text-xs text-emerald-400 bg-emerald-500/10 p-3 rounded-lg border border-emerald-500/20">
        <CheckCircle2 className="w-4 h-4" />
        Traverse automatically computed from Step 2 (Field Book). Area updated.
      </div>
    </div>
  );
}

'use client';

import React, { useRef, useEffect, useState, useCallback, memo } from 'react';
import {
  ChevronUp,
  ChevronDown,
  Trash2,
  Activity,
  Loader2,
  AlertCircle,
  CheckCircle2,
  AlertTriangle,
  Info,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import {
  useWorkspaceBridge,
  type ComputationLogEntry,
} from '@/hooks/useWorkspaceBridge';

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

/** Color tokens mapped from log level to Tailwind utilities */
const LEVEL_STYLES: Record<
  ComputationLogEntry['level'],
  { dot: string; text: string; border: string; badge: string }
> = {
  info: {
    dot: 'bg-sky-400',
    text: 'text-sky-300',
    border: 'border-sky-500/20',
    badge: 'bg-sky-500/10 text-sky-400',
  },
  success: {
    dot: 'bg-emerald-400',
    text: 'text-emerald-300',
    border: 'border-emerald-500/20',
    badge: 'bg-emerald-500/10 text-emerald-400',
  },
  warning: {
    dot: 'bg-amber-400',
    text: 'text-amber-300',
    border: 'border-amber-500/20',
    badge: 'bg-amber-500/10 text-amber-400',
  },
  error: {
    dot: 'bg-red-400',
    text: 'text-red-300',
    border: 'border-red-500/20',
    badge: 'bg-red-500/10 text-red-400',
  },
};

const PHASE_STYLES: Record<
  ComputationLogEntry['phase'],
  { badge: string }
> = {
  input: { badge: 'bg-violet-500/10 text-violet-400' },
  compute: { badge: 'bg-cyan-500/10 text-cyan-400' },
  adjustment: { badge: 'bg-orange-500/10 text-orange-400' },
  output: { badge: 'bg-emerald-500/10 text-emerald-400' },
};

function formatTime(d: Date): string {
  return d.toLocaleTimeString('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });
}

/* ------------------------------------------------------------------ */
/*  Single log entry (memoised)                                        */
/* ------------------------------------------------------------------ */

interface LogEntryRowProps {
  entry: ComputationLogEntry;
}

const LogEntryRow = memo(function LogEntryRow({ entry }: LogEntryRowProps) {
  const [expanded, setExpanded] = useState(false);
  const levelStyle = LEVEL_STYLES[entry.level];
  const phaseStyle = PHASE_STYLES[entry.phase];

  return (
    <div
      className={cn(
        'group flex items-start gap-2 px-3 py-1.5 border-l-2 transition-colors',
        levelStyle.border,
        'hover:bg-[var(--bg-tertiary)]',
      )}
    >
      {/* Timestamp */}
      <span className="flex-shrink-0 text-xs font-mono text-[var(--text-muted)] pt-0.5 select-none w-16">
        {formatTime(entry.timestamp)}
      </span>

      {/* Level dot */}
      <span
        className={cn('flex-shrink-0 w-1.5 h-1.5 rounded-full mt-1.5', levelStyle.dot)}
        title={entry.level}
      />

      {/* Phase badge */}
      <span
        className={cn(
          'flex-shrink-0 text-[9px] font-semibold uppercase tracking-wider px-1.5 py-0.5 rounded',
          phaseStyle.badge,
        )}
      >
        {entry.phase}
      </span>

      {/* Message */}
      <span
        className={cn('flex-1 text-xs leading-relaxed min-w-0', levelStyle.text)}
      >
        {entry.message}
      </span>

      {/* Expand toggle for detail */}
      {entry.detail && (
        <button
          onClick={() => setExpanded((v) => !v)}
          className="flex-shrink-0 p-0.5 rounded hover:bg-[var(--bg-card)] text-[var(--text-muted)] hover:text-[var(--text-secondary)] transition-colors opacity-0 group-hover:opacity-100"
          aria-label={expanded ? 'Hide detail' : 'Show detail'}
        >
          {expanded ? (
            <ChevronUp className="w-3 h-3" />
          ) : (
            <ChevronDown className="w-3 h-3" />
          )}
        </button>
      )}
    </div>
  );
});

/* ------------------------------------------------------------------ */
/*  Computation Log Component                                          */
/* ------------------------------------------------------------------ */

export default function ComputationLog() {
  const { computationLogs, isComputing, clearLogs } = useWorkspaceBridge();
  const scrollRef = useRef<HTMLDivElement>(null);
  const [collapsed, setCollapsed] = useState(false);

  // Auto-scroll to bottom on new entries
  useEffect(() => {
    if (!collapsed && scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [computationLogs.length, collapsed]);

  const handleClear = useCallback(() => {
    clearLogs();
  }, [clearLogs]);

  const toggleCollapse = useCallback(() => {
    setCollapsed((v) => !v);
  }, []);

  return (
    <div
      className={cn(
        'flex flex-col overflow-hidden bg-[var(--bg-secondary)] transition-all duration-200',
        collapsed ? 'h-8' : 'h-full',
      )}
    >
      {/* ---- Header bar ---- */}
      <div className="flex items-center justify-between flex-shrink-0 h-8 px-3 border-b border-[var(--border-color)] bg-[var(--bg-card)]">
        <div className="flex items-center gap-2.5 min-w-0">
          {/* Computing pulse indicator */}
          {isComputing && (
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-[var(--accent)] opacity-75" />
              <span className="relative inline-flex rounded-full h-2 w-2 bg-[var(--accent)]" />
            </span>
          )}

          <span className="text-xs font-semibold text-[var(--text-primary)] tracking-tight">
            Computation Log
          </span>

          {/* Entry count badge */}
          {computationLogs.length > 0 && (
            <span className="text-xs font-medium tabular-nums bg-[var(--bg-tertiary)] text-[var(--text-secondary)] px-1.5 py-0.5 rounded">
              {computationLogs.length}
            </span>
          )}

          {/* Level summary icons */}
          {computationLogs.length > 0 && (
            <div className="flex items-center gap-1 ml-1">
              {computationLogs.some((e) => e.level === 'error') && (
                <AlertCircle className="w-3 h-3 text-red-400" />
              )}
              {computationLogs.some(
                (e) => e.level === 'warning' && !computationLogs.some((l) => l.level === 'error'),
              ) && (
                <AlertTriangle className="w-3 h-3 text-amber-400" />
              )}
              {computationLogs.every(
                (e) => e.level === 'info' || e.level === 'success',
              ) && (
                <CheckCircle2 className="w-3 h-3 text-emerald-400" />
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-1 flex-shrink-0">
          {/* Clear button */}
          {computationLogs.length > 0 && (
            <button
              onClick={handleClear}
              className="flex items-center gap-1 px-2 py-1.5 rounded text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] transition-colors min-h-[36px]"
              title="Clear all logs"
            >
              <Trash2 className="w-3 h-3" />
              <span>Clear</span>
            </button>
          )}

          {/* Collapse toggle */}
          <button
            onClick={toggleCollapse}
            aria-label={collapsed ? 'Expand log' : 'Collapse log'}
            className="flex-shrink-0 p-2 min-w-[36px] min-h-[36px] flex items-center justify-center rounded hover:bg-[var(--bg-tertiary)] text-[var(--text-muted)] hover:text-[var(--text-secondary)] transition-colors"
          >
            {collapsed ? (
              <ChevronUp className="w-3.5 h-3.5" />
            ) : (
              <ChevronDown className="w-3.5 h-3.5" />
            )}
          </button>
        </div>
      </div>

      {/* ---- Log list (hidden when collapsed) ---- */}
      {!collapsed && (
        <div
          ref={scrollRef}
          className="flex-1 overflow-y-auto min-h-0 custom-scrollbar"
        >
          {computationLogs.length === 0 ? (
            /* Empty state */
            <div className="flex flex-col items-center justify-center h-full py-6 text-center select-none">
              <Info className="w-5 h-5 text-[var(--text-muted)] mb-2" />
              <p className="text-xs text-[var(--text-muted)]">
                No computation entries yet.
              </p>
              <p className="text-xs text-[var(--text-muted)] mt-0.5 opacity-70">
                Run a computation to see results here.
              </p>
            </div>
          ) : (
            <div className="divide-y divide-[var(--border-color)]/50">
              {computationLogs.map((entry) => (
                <LogEntryRow key={entry.id} entry={entry} />
              ))}
            </div>
          )}

          {/* Computing overlay */}
          {isComputing && (
            <div className="absolute bottom-0 left-0 right-0 h-8 bg-gradient-to-t from-[var(--bg-secondary)] to-transparent flex items-center justify-center pointer-events-none">
              <Loader2 className="w-3.5 h-3.5 text-[var(--accent)] animate-spin" />
              <span className="text-xs text-[var(--accent)] ml-1.5 font-medium">
                Computing…
              </span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { createClient } from '@/lib/api-client/client';
import { usePrint, PrintButton, PrintHeader } from '@/hooks/usePrint';
import { SurveyType } from '@/types/project';
import { FieldBookColumn, FieldBookRow } from '@/types/fieldbook';
import { getFieldBookTemplate } from '@/lib/workflows/fieldBookTemplates';
import { applyAutoCalculations, validateFieldBook, FieldBookWarning } from '@/lib/workflows/autoCalculate';
import { runLevelingComputation, getLevelingClosureStatus } from '@/lib/compute/levelingRunner';
import { runBowditchAdjustment, getTraversePrecisionStatus } from '@/lib/compute/traverseRunner';
import { computeCutFillVolume, getCutFillSummary } from '@/lib/compute/volumeRunner';

interface Props {
  projectId: string;
  surveyType: SurveyType;
  initialRows?: FieldBookRow[];
  openingRL?: number;
  closingRL?: number;
  startPoint?: { name: string; easting: number; northing: number };
}

const FIXED_COLUMNS = new Set([
  'station', 'bs', 'is', 'fs', 'rl', 'instrument_height', 'remark',
]);

function emptyRow(columns: FieldBookColumn[]): FieldBookRow {
  return Object.fromEntries(columns.map((c) => [c.key, '']));
}

function rowToDbRecord(
  row: FieldBookRow,
  rowIndex: number,
  projectId: string,
  surveyType: string,
  columns: FieldBookColumn[]
) {
  const fixed: Record<string, unknown> = {
    project_id: projectId,
    row_index: rowIndex,
    survey_type: surveyType,
    updated_at: new Date().toISOString(),
  };

  const rawData: Record<string, unknown> = {};

  for (const col of columns) {
    const value = row[col.key] ?? null;
    const targetColumn = col.fixedColumn ?? (FIXED_COLUMNS.has(col.key) ? col.key : null);

    if (targetColumn) {
      if (['bs', 'is', 'fs', 'rl', 'instrument_height'].includes(targetColumn)) {
        fixed[targetColumn] = value !== '' && value !== null ? Number(value) : null;
      } else {
        fixed[targetColumn] = value !== '' ? value : null;
      }
    } else {
      rawData[col.key] = value !== '' ? value : null;
    }
  }

  fixed['raw_data'] = rawData;
  return fixed;
}

export default function DynamicFieldBook({ projectId, surveyType, initialRows = [], openingRL, closingRL, startPoint }: Props) {
  const { print, isPrinting, paperSize, setPaperSize, orientation, setOrientation } = usePrint({ title: 'Field Book' });
  // AUDIT FIX (H-007, 2026-07-27): useMemo prevents infinite loop.
  const dbClient = useMemo(() => createClient(), []);
  const template = getFieldBookTemplate(surveyType);

  const [rows, setRows] = useState<FieldBookRow[]>(
    initialRows.length > 0 ? initialRows : [emptyRow(template.columns)]
  );
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [computeResult, setComputeResult] = useState<string | null>(null);
  const [warnings, setWarnings] = useState<FieldBookWarning[]>([]);
  const [deleteConfirm, setDeleteConfirm] = useState<number | null>(null);

  const saveTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const rowsRef = useRef(rows);
  rowsRef.current = rows;

  const addRow = () => setRows((prev) => [...prev, emptyRow(template.columns)]);

  const removeRow = (idx: number) => {
    if (deleteConfirm === idx) {
      setRows((prev) => prev.filter((_, i) => i !== idx));
      setDeleteConfirm(null);
    } else {
      setDeleteConfirm(idx);
      setTimeout(() => setDeleteConfirm(null), 3000);
    }
  };

  const updateCell = useCallback((rowIdx: number, key: string, value: string) => {
    setRows((prev) => {
      const updated = prev.map((row, i) => (i === rowIdx ? { ...row, [key]: value } : row));
      const recalculated = applyAutoCalculations(surveyType, updated, rowIdx);
      const newWarnings = validateFieldBook(surveyType, recalculated);
      setWarnings(newWarnings);
      return recalculated;
    });

    if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);
    saveTimeoutRef.current = setTimeout(async () => {
      setSaving(true);
      const records = rowsRef.current.map((row: any, idx: any) =>
        rowToDbRecord(row, idx, projectId, surveyType, template.columns)
      );
      const { error: dbError } = await dbClient
        .from('project_fieldbook_entries')
        .upsert(records, { onConflict: 'project_id,row_index' });
      if (!dbError) setLastSaved(new Date());
      setSaving(false);
    }, 500);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [surveyType, projectId, template.columns, dbClient]);

  const handleCompute = useCallback(() => {
    try {
      if (surveyType === 'engineering') {
        if (openingRL) {
          const result = runLevelingComputation({
            rows,
            openingRL,
            closingRL: closingRL ? Number(closingRL) : undefined,
            method: 'rise_and_fall',
          });
          const status = getLevelingClosureStatus(result);
          setComputeResult(status.message);
        } else {
          setComputeResult('Please provide opening RL in project settings');
        }
      } else if (surveyType === 'cadastral') {
        if (startPoint) {
          const result = runBowditchAdjustment({
            rows,
            startPoint,
          });
          const status = getTraversePrecisionStatus(result);
          setComputeResult(status.message);
        } else {
          setComputeResult('Please provide start point coordinates in project settings');
        }
      } else if (surveyType === 'topographic') {
        const sections = rows
          .filter((r) => r.chainage && r.area)
          .map((r) => ({ chainage: Number(r.chainage), area: Number(r.area) }))
          .sort((a: any, b: any) => a.chainage - b.chainage);
        
        if (sections.length >= 2) {
          const result = computeCutFillVolume(sections);
          const summary = getCutFillSummary(result);
          setComputeResult(`Cut: ${summary.cut} | Fill: ${summary.fill} | Net: ${summary.net}`);
        } else {
          setComputeResult('Need at least 2 rows with chainage and area for volume calculation');
        }
      } else if (surveyType === 'geodetic') {
        setComputeResult('Geodetic baseline processing — enter control points and observed baselines to compute adjustments');
      } else if (surveyType === 'drone') {
        setComputeResult('Drone survey processing — import ground control points and process aerial imagery');
      } else if (surveyType === 'deformation') {
        const epochs = new Set(rows.map((r) => r.epoch).filter(Boolean));
        if (epochs.size < 2) {
          setComputeResult('Minimum 2 epochs required for comparison');
        } else {
          setComputeResult('Deformation epoch comparison — enter coordinates for each monitoring epoch');
        }
      }
    } catch (e) {
      setComputeResult(`Error: ${e instanceof Error ? e.message : 'Unknown error'}`);
    }
  }, [rows, surveyType, openingRL, closingRL, startPoint]);

  const handleSave = async () => {
    setSaving(true);
    setError(null);

    const records = rows.map((row: any, idx: any) =>
      rowToDbRecord(row, idx, projectId, surveyType, template.columns)
    );

    const { error: dbError } = await dbClient
      .from('project_fieldbook_entries')
      .upsert(records, { onConflict: 'project_id,row_index' });

    if (dbError) {
      setError('Save failed: ' + dbError.message);
    } else {
      setLastSaved(new Date());
    }
    setSaving(false);
  };

  const renderCell = (col: FieldBookColumn, row: FieldBookRow, rowIdx: number) => {
    const value = String(row[col.key] ?? '');
    const base = 'w-full text-sm outline-none bg-transparent px-1 py-0.5';

    if (col.type === 'select' && col.options) {
      return (
        <select
          value={value}
          onChange={(e) => updateCell(rowIdx, col.key, e.target.value)}
          className={base}
        >
          <option value="">—</option>
          {col.options.map((o) => (
            <option key={o} value={o}>{o}</option>
          ))}
        </select>
      );
    }

    return (
      <input aria-label={col.label}
        type={col.type === 'number' ? 'number' : col.type === 'date' ? 'date' : 'text'}
        value={value}
        placeholder={col.placeholder ?? ''}
        step={col.type === 'number' ? 'any' : undefined}
        onChange={(e) => updateCell(rowIdx, col.key, e.target.value)}
        className={base}
      />
    );
  };

  const requiredKeys = template.columns.filter((c) => c.required).map((c) => c.key);
  const hasEmptyRequired = rows.some((row) => requiredKeys.some((k) => !row[k]));

  const getComputeButtonLabel = () => {
    switch (surveyType) {
      case 'cadastral': return 'Adjust Traverse (Bowditch)';
      case 'engineering': return 'Reduce Levels';
      case 'topographic': return 'Generate DTM';
      case 'geodetic': return 'Process Baselines';
      case 'drone': return 'Process GCPs';
      case 'deformation': return 'Compare Epochs';
      default: return 'Compute';
    }
  };

  return (
    <div className="rounded-lg border border-gray-200 bg-white overflow-hidden">
      <PrintHeader title="Field Book" />
      <div className="px-4 py-3 border-b border-gray-100 flex items-start justify-between gap-4">
        <div>
          <h3 className="font-semibold text-gray-900 text-sm">{template.title}</h3>
          <p className="text-xs text-gray-500 mt-0.5">{template.description}</p>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0 no-print print-hide">
          {lastSaved && <span className="text-xs text-green-600">Saved {lastSaved.toLocaleTimeString()}</span>}
          <button onClick={handleCompute} disabled={saving} className="px-3 py-1.5 text-xs bg-green-600 text-white rounded hover:bg-green-700 disabled:opacity-50">
            {getComputeButtonLabel()}
          </button>
          <button onClick={handleSave} disabled={saving} className="px-3 py-1.5 text-xs bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50">
            {saving ? 'Saving…' : 'Save'}
          </button>
          <PrintButton
            print={print}
            isPrinting={isPrinting}
            paperSize={paperSize}
            setPaperSize={setPaperSize}
            orientation={orientation}
            setOrientation={setOrientation}
            printTitle="Field Book"
            compact
          />
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm border-collapse min-w-max">
          <thead>
            <tr className="bg-gray-50 border-b border-gray-200">
              <th className="w-8 px-2 py-1.5 text-left text-xs font-medium text-gray-500">#</th>
              {template.columns.map((col) => (
                <th key={col.key} className={`px-2 py-1.5 text-left text-xs font-medium text-gray-600 w-${col.width ?? '28'}`}>
                  {col.label}{col.required && <span className="text-red-400 ml-0.5">*</span>}
                </th>
              ))}
              <th className="w-8" />
            </tr>
          </thead>
          <tbody>
            {rows.map((row, rowIdx) => (
              <tr key={rowIdx} className="border-b border-gray-100 hover:bg-gray-50">
                <td className="px-2 py-1 text-xs text-gray-400 text-right select-none">{rowIdx + 1}</td>
                {template.columns.map((col) => (
                  <td key={col.key} className={`border-l border-gray-100 px-1 py-0.5 ${col.required && !row[col.key] ? 'bg-red-50' : ''}`}>
                    {renderCell(col, row, rowIdx)}
                  </td>
                ))}
                <td className="border-l border-gray-100 px-1 py-0.5 text-center">
                  <button
                    onClick={() => removeRow(rowIdx)}
                    disabled={rows.length === 1}
                    className={`text-xs ${deleteConfirm === rowIdx ? 'text-red-600 font-medium' : 'text-gray-300 hover:text-red-400'} disabled:opacity-0`}
                    title={deleteConfirm === rowIdx ? 'Click again to confirm' : 'Delete row'}
                  >
                    {deleteConfirm === rowIdx ? '' : '[x]'}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="px-4 py-2 border-t border-gray-100 flex items-center justify-between">
        <button onClick={addRow} className="text-xs text-blue-600 hover:text-blue-800 font-medium">+ Add Row</button>
        <div className="flex items-center gap-3">
          {hasEmptyRequired && <span className="text-xs text-amber-600">Required fields (*) must be filled.</span>}
          <span className="text-xs text-gray-400">{rows.length} row{rows.length !== 1 ? 's' : ''}</span>
        </div>
      </div>

      {warnings.length > 0 && (
        <div className="px-4 py-2 bg-amber-50 border-t border-amber-100 flex flex-wrap gap-2">
          {warnings.map((w, idx) => (
            <span
              key={`${w}-${idx}`}
              className={`inline-flex items-center px-2 py-0.5 rounded text-xs ${
                w.severity === 'error' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
              }`}
            >
              {w.rowIndex !== undefined && <span className="mr-1">Row {w.rowIndex + 1}:</span>}
              {w.message}
            </span>
          ))}
        </div>
      )}

      {error && <div className="px-4 py-2 bg-red-50 border-t border-red-100 text-xs text-red-600">{error}</div>}
      {computeResult && (
        <div className={`px-4 py-2 border-t text-xs ${computeResult.startsWith('Error') ? 'bg-red-50 border-red-100 text-red-600' : 'bg-green-50 border-green-100 text-green-700'}`}>
          {computeResult}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { type ReactNode } from 'react';
import {
  ResizablePanelGroup,
  ResizablePanel,
  ResizableHandle,
} from '@/components/ui/resizable';
import {
  ChevronUp,
  ChevronDown,
  Activity,
  Crosshair,
  AlertTriangle,
  CheckCircle2,
  PanelBottomClose,
  PanelBottomOpen,
  SquareSlash,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useWorkspaceBridge } from '@/hooks/useWorkspaceBridge';
import { useUIStore } from '@/stores/uiStore';

// Re-use the type from the existing layout (don't use the component itself)
import type { StatusBarEntry } from './SplitWorkspaceLayout';

/* ------------------------------------------------------------------ */
/*  Props                                                              */
/* ------------------------------------------------------------------ */

export interface EnhancedSplitLayoutProps {
  /** Workflow stepper + step content */
  leftPanel: ReactNode;
  /** Map */
  rightPanel: ReactNode;
  /** ComputationLog component */
  logPanel: ReactNode;
  /** Optional pre-built status bar entries */
  statusBarEntries?: StatusBarEntry[];
  /** Optional class applied to the outermost wrapper */
  className?: string;
}

/* ------------------------------------------------------------------ */
/*  Status icon (mirrors the one in SplitWorkspaceLayout)              */
/* ------------------------------------------------------------------ */

function StatusIcon({ status }: { status?: StatusBarEntry['status'] }) {
  switch (status) {
    case 'ok':
      return <CheckCircle2 className="w-3 h-3 text-emerald-400" />;
    case 'warning':
      return <AlertTriangle className="w-3 h-3 text-amber-400" />;
    case 'error':
      return <AlertTriangle className="w-3 h-3 text-red-400" />;
    default:
      return <Activity className="w-3 h-3 text-[var(--text-muted)]" />;
  }
}

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

export default function EnhancedSplitLayout({
  leftPanel,
  rightPanel,
  logPanel,
  statusBarEntries = [],
  className,
}: EnhancedSplitLayoutProps) {
  const logCollapsed = !useUIStore(s => s.bottomPanelOpen);
  const toggleBottomPanel = useUIStore(s => s.toggleBottomPanel);
  const {
    misclosureValue,
    precisionValue,
    areaValue,
    selection,
  } = useWorkspaceBridge();

  // Derive status for bridge values
  const misclosureStatus: StatusBarEntry['status'] =
    misclosureValue !== '—' ? 'ok' : 'idle';
  const precisionStatus: StatusBarEntry['status'] =
    precisionValue !== '—' ? 'ok' : 'idle';
  const areaStatus: StatusBarEntry['status'] =
    areaValue !== '—' ? 'ok' : 'idle';

  // Selection display for status bar
  const selectionDisplay =
    selection.type !== 'none'
      ? `${selection.stationName ?? `#${selection.index ?? '—'}`}`
      : 'None';

  return (
    <div
      className={cn(
        'flex flex-col h-[calc(100vh-48px)] overflow-x-clip',
        className,
      )}
    >
      {/* ================================================================ */}
      {/*  Main resizable area: top = horizontal split, bottom = log       */}
      {/* ================================================================ */}
      <div className="flex-1 min-h-0">
        {/* Desktop: resizable panels */}
        <div className="hidden md:block h-full">
          <ResizablePanelGroup orientation="vertical" className="h-full">
            {/* ---- Top section: Left workflow + Right map ---- */}
            <ResizablePanel defaultSize={logCollapsed ? 100 : 75} minSize={40}>
              <div className="h-full overflow-hidden">
                <ResizablePanelGroup orientation="horizontal" className="h-full">
                  {/* Left panel — workflow content (55 %) */}
                  <ResizablePanel defaultSize={55} minSize={30}>
                    <div className="h-full overflow-y-auto scroll-smooth">
                      {leftPanel}
                    </div>
                  </ResizablePanel>

                  <ResizableHandle withHandle />

                  {/* Right panel — map (45 %) */}
                  <ResizablePanel defaultSize={45} minSize={25}>
                    <div className="h-full overflow-hidden bg-[var(--bg-tertiary)]">
                      {rightPanel}
                    </div>
                  </ResizablePanel>
                </ResizablePanelGroup>
              </div>
            </ResizablePanel>

            {/* ---- Horizontal divider ---- */}
            <ResizableHandle withHandle />

            {/* ---- Bottom section: Computation log ---- */}
            <ResizablePanel
              defaultSize={logCollapsed ? 0 : 25}
              minSize={logCollapsed ? 0 : 15}
              maxSize={logCollapsed ? 0 : 50}
              collapsible
              collapsedSize={0}
            >
              <div className="h-full overflow-hidden">{logPanel}</div>
            </ResizablePanel>
          </ResizablePanelGroup>
        </div>

        {/* Mobile: stacked layout */}
        <div className="md:hidden flex flex-col h-full">
          <div className="flex-1 min-h-0 overflow-y-auto scroll-smooth">
            {leftPanel}
          </div>
          <div className="h-[35vh] border-t border-[var(--border-color)] bg-[var(--bg-tertiary)] overflow-hidden">
            {rightPanel}
          </div>
        </div>
      </div>

      {/* ================================================================ */}
      {/*  Compact status bar (28px)                                       */}
      {/* ================================================================ */}
      <div className="flex-shrink-0 h-7 border-t border-[var(--border-color)] bg-[var(--bg-secondary)] overflow-x-clip">
        <div className="flex items-center justify-between h-full px-2 sm:px-3 gap-2 sm:gap-3">
          {/* Left section: user-provided entries */}
          <div className="flex items-center gap-2 sm:gap-4 min-w-0 overflow-x-auto scrollbar-none">
            {statusBarEntries.map((entry, idx) => (
              <div
                key={entry.label}
                className="flex items-center gap-1 text-xs whitespace-nowrap flex-shrink-0"
              >
                <StatusIcon status={entry.status} />
                <span className="text-[var(--text-muted)]">
                  {entry.label}:
                </span>
                <span
                  className={cn(
                    'font-medium tabular-nums',
                    entry.status === 'ok' && 'text-emerald-400',
                    entry.status === 'warning' && 'text-amber-400',
                    entry.status === 'error' && 'text-red-400',
                    (!entry.status || entry.status === 'idle') &&
                      'text-[var(--text-secondary)]',
                  )}
                >
                  {entry.value}
                </span>
              </div>
            ))}
          </div>

          {/* Right section: bridge-derived values + log toggle */}
          <div className="flex items-center gap-1.5 sm:gap-3 flex-shrink-0">
            {/* Selection */}
            <div className="flex items-center gap-1 text-xs">
              <Crosshair className="w-3 h-3 text-[var(--accent)]" />
              <span className="text-[var(--text-muted)]">Sel:</span>
              <span className="font-medium text-[var(--text-secondary)] tabular-nums">
                {selectionDisplay}
              </span>
            </div>

            {/* Misclosure */}
            <div className="hidden sm:flex items-center gap-1 text-xs">
              <StatusIcon status={misclosureStatus} />
              <span className="text-[var(--text-muted)]">Misc:</span>
              <span
                className={cn(
                  'font-medium tabular-nums',
                  misclosureStatus === 'ok'
                    ? 'text-emerald-400'
                    : 'text-[var(--text-secondary)]',
                )}
              >
                {misclosureValue}
              </span>
            </div>

            {/* Precision */}
            <div className="hidden sm:flex items-center gap-1 text-xs">
              <StatusIcon status={precisionStatus} />
              <span className="text-[var(--text-muted)]">Prec:</span>
              <span
                className={cn(
                  'font-medium tabular-nums',
                  precisionStatus === 'ok'
                    ? 'text-emerald-400'
                    : 'text-[var(--text-secondary)]',
                )}
              >
                {precisionValue}
              </span>
            </div>

            {/* Area */}
            <div className="hidden md:flex items-center gap-1 text-xs">
              <SquareSlash className="w-3 h-3 text-[var(--text-muted)]" />
              <span className="text-[var(--text-muted)]">Area:</span>
              <span
                className={cn(
                  'font-medium tabular-nums',
                  areaStatus === 'ok'
                    ? 'text-emerald-400'
                    : 'text-[var(--text-secondary)]',
                )}
              >
                {areaValue}
              </span>
            </div>

            {/* Separator */}
            <div className="w-px h-3 bg-[var(--border-color)]" />

            {/* Log collapse toggle */}
            <button
              onClick={toggleBottomPanel}
              aria-label={logCollapsed ? 'Show log' : 'Hide log'}
              className="flex items-center gap-1 px-2 py-1.5 rounded text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] transition-colors min-h-[36px]"
            >
              {logCollapsed ? (
                <>
                  <PanelBottomOpen className="w-3 h-3" />
                  <span>Log</span>
                </>
              ) : (
                <>
                  <PanelBottomClose className="w-3 h-3" />
                  <span>Log</span>
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client'

import { useState, useCallback } from 'react'
import { z } from 'zod'
import { Loader2, FileText, Download, MapPin, Activity, Upload } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Tooltip,
  TooltipTrigger,
  TooltipContent,
} from '@/components/ui/tooltip'
import { apiPost, ApiError } from '@/lib/api/client'
import { realtimeService } from '@/lib/realtime'
import * as Y from 'yjs'

// ponytail: response schemas — Phase 4 wave 2 will move these to src/lib/api/schemas/

const traverseLegSchema = z.object({
  from: z.string(),
  to: z.string(),
  bearing: z.number(),
  distance: z.number(),
  adjEasting: z.number(),
  adjNorthing: z.number(),
  rawDeltaE: z.number().optional(),
  rawDeltaN: z.number().optional(),
  correctionE: z.number().optional(),
  correctionN: z.number().optional(),
}).passthrough()

const traverseResultSchema = z.object({
  legs: z.array(traverseLegSchema),
  closingErrorE: z.number(),
  closingErrorN: z.number(),
  linearError: z.number(),
  precisionRatio: z.number(),
  adjustedAreaM2: z.number(),
  adjustedAreaHa: z.number(),
  angularMisclosureSec: z.number().optional(),
  angularToleranceSec: z.number().optional(),
  linearMisclosureM: z.number().optional(),
  perimeterM: z.number().optional(),
}).passthrough()

const dxfExportSchema = z.object({
  kind: z.string(),
  filename: z.string(),
  dxf: z.string(),
}).passthrough()

const geojsonExportSchema = z.object({
  kind: z.string(),
  filename: z.string(),
  geojson: z.any(),
}).passthrough()

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

interface ExportToolbarProps {
  projectId: string
  projectName: string
  lrNumber?: string
  surveyType?: string
  hasTraverseData: boolean
  hasAdjustedCoords: boolean
  onAdjustmentComplete?: (result: any) => void
}

interface TraverseResult {
  legs: Array<{
    from: string
    to: string
    bearing: number
    distance: number
    adjEasting: number
    adjNorthing: number
    rawDeltaE: number
    rawDeltaN: number
    correctionE: number
    correctionN: number
  }>
  closingErrorE: number
  closingErrorN: number
  linearError: number
  precisionRatio: number
  adjustedAreaM2: number
  adjustedAreaHa: number
  angularMisclosureSec?: number
  angularToleranceSec?: number
  linearMisclosureM?: number
  perimeterM?: number
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function ExportToolbar({
  projectId,
  projectName,
  lrNumber = '',
  surveyType = 'cadastral',
  hasTraverseData,
  hasAdjustedCoords,
  onAdjustmentComplete,
}: ExportToolbarProps) {
  const [adjustLoading, setAdjustLoading] = useState(false)
  const [formC22Loading, setFormC22Loading] = useState(false)
  const [dxfLoading, setDxfLoading] = useState(false)
  const [geojsonLoading, setGeojsonLoading] = useState(false)
  const [traverseResult, setTraverseResult] = useState<TraverseResult | null>(null)
  const [error, setError] = useState<string | null>(null)

  // -----------------------------------------------------------------------
  // Helpers
  // -----------------------------------------------------------------------

  const downloadBlob = useCallback((blob: Blob, filename: string) => {
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = filename
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)
  }, [])

  const handleExportProject = useCallback(() => {
    try {
      const doc = realtimeService.getDoc(projectId)
      const stateUpdate = Y.encodeStateAsUpdate(doc)
      const blob = new Blob([stateUpdate as unknown as BlobPart], { type: 'application/octet-stream' })
      downloadBlob(blob, `${projectName.replace(/[^a-z0-9]/gi, '_')}.metardu`)
    } catch (err) {
      setError('Failed to export project: ' + (err as Error).message)
    }
  }, [projectId, projectName, downloadBlob])

  const handleImportProject = useCallback(() => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = '.metardu'
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0]
      if (!file) return
      try {
        const arrayBuffer = await file.arrayBuffer()
        const update = new Uint8Array(arrayBuffer)
        const doc = realtimeService.getDoc(projectId)
        Y.applyUpdate(doc, update)
      } catch (err) {
        setError('Failed to import project: ' + (err as Error).message)
      }
    }
    input.click()
  }, [projectId])

  const clearError = useCallback(() => setError(null), [])

  // -----------------------------------------------------------------------
  // 1. Run Adjustment
  // -----------------------------------------------------------------------

  const handleRunAdjustment = useCallback(async () => {
    try {
      setAdjustLoading(true)
      clearError()

      const result = await apiPost(
        '/api/compute/traverse',
        traverseResultSchema,
        {
          task: 'adjust',
          method: 'bowditch',
          surveyType,
          startPoint: { name: 'ST1', easting: 0, northing: 0 },
          legs: [], // caller should provide legs via project data
          closingPoint: { easting: 0, northing: 0 },
        },
      )

      setTraverseResult(result as unknown as TraverseResult)
      onAdjustmentComplete?.(result)
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message || 'Adjustment failed')
      } else {
        setError((err as Error).message || 'Adjustment failed')
      }
    } finally {
      setAdjustLoading(false)
    }
  }, [surveyType, onAdjustmentComplete, clearError])

  // -----------------------------------------------------------------------
  // 2. Download Form C22
  // -----------------------------------------------------------------------

  const handleDownloadFormC22 = useCallback(async () => {
    try {
      setFormC22Loading(true)
      clearError()

      const legs = traverseResult?.legs || []

      // ponytail: binary download bypasses typed client (PDF response, not JSON)
      const res = await fetch('/api/submission/form-c22', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          projectName,
          lrNumber,
          legs: legs.map((l) => ({
            from: l.from,
            to: l.to,
            bearing: l.bearing,
            distance: l.distance,
            adjEasting: l.adjEasting,
            adjNorthing: l.adjNorthing,
            rawDeltaE: l.rawDeltaE || 0,
            rawDeltaN: l.rawDeltaN || 0,
            correctionE: l.correctionE || 0,
            correctionN: l.correctionN || 0,
          })),
          startPoint: {
            easting: legs[0]?.adjEasting || 0,
            northing: legs[0]?.adjNorthing || 0,
          },
          angularMisclosureSec: traverseResult?.angularMisclosureSec || 0,
          angularToleranceSec: traverseResult?.angularToleranceSec || 0,
          linearMisclosureM: traverseResult?.linearMisclosureM || traverseResult?.linearError || 0,
          perimeterM: traverseResult?.perimeterM || 0,
          precisionRatio: traverseResult?.precisionRatio || 0,
        }),
      })

      if (!res.ok) {
        const errData = await res.json().catch(() => ({}))
        throw new Error(errData.error || 'Failed to generate Form C22')
      }

      const blob = await res.blob()
      const filename = lrNumber || 'draft'
      downloadBlob(blob, `Form_C22_${filename}.pdf`)
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message || 'Failed to download Form C22')
      } else {
        setError((err as Error).message || 'Failed to download Form C22')
      }
    } finally {
      setFormC22Loading(false)
    }
  }, [projectName, lrNumber, traverseResult, downloadBlob, clearError])

  // -----------------------------------------------------------------------
  // 3. Export DXF
  // -----------------------------------------------------------------------

  const handleExportDXF = useCallback(async () => {
    try {
      setDxfLoading(true)
      clearError()

      const legs = traverseResult?.legs || []
      const points = legs.map((l, i) => ({
        name: l.to || `PT${i + 1}`,
        easting: l.adjEasting,
        northing: l.adjNorthing,
        is_control: i === 0,
      }))

      const data = await apiPost(
        '/api/compute/export/dxf',
        dxfExportSchema,
        {
          projectName,
          points,
          traverseLegs: legs.map((l) => ({
            from: l.from,
            to: l.to,
            bearing: l.bearing,
            distance: l.distance,
          })),
        },
      )

      const blob = new Blob([data.dxf], { type: 'application/dxf' })
      downloadBlob(blob, data.filename)
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message || 'DXF export failed')
      } else {
        setError((err as Error).message || 'DXF export failed')
      }
    } finally {
      setDxfLoading(false)
    }
  }, [projectName, traverseResult, downloadBlob, clearError])

  // -----------------------------------------------------------------------
  // 4. Export GeoJSON
  // -----------------------------------------------------------------------

  const handleExportGeoJSON = useCallback(async () => {
    try {
      setGeojsonLoading(true)
      clearError()

      const legs = traverseResult?.legs || []
      const points = legs.map((l, i) => ({
        name: l.to || `PT${i + 1}`,
        easting: l.adjEasting,
        northing: l.adjNorthing,
        is_control: i === 0,
      }))

      const data = await apiPost(
        '/api/compute/export/geojson',
        geojsonExportSchema,
        {
          projectName,
          points,
        },
      )

      const blob = new Blob([JSON.stringify(data.geojson, null, 2)], {
        type: 'application/geo+json',
      })
      downloadBlob(blob, data.filename)
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.message || 'GeoJSON export failed')
      } else {
        setError((err as Error).message || 'GeoJSON export failed')
      }
    } finally {
      setGeojsonLoading(false)
    }
  }, [projectName, traverseResult, downloadBlob, clearError])

  // -----------------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------------

  return (
    <div className="flex items-center gap-1.5">
      {/* Error banner */}
      {error && (
        <div className="mr-2 flex items-center gap-2 rounded-md border border-red-500/30 bg-red-500/10 px-3 py-1.5 text-xs text-red-500">
          <span>{error}</span>
          <button
            onClick={clearError}
            className="ml-1 font-medium text-red-400 hover:text-red-300"
          >
            ×
          </button>
        </div>
      )}

      {/* Run Adjustment */}
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            onClick={handleImportProject}
            className="gap-1.5"
          >
            <Upload className="size-3.5" />
            <span className="hidden xl:inline">Load Project</span>
          </Button>
        </TooltipTrigger>
        <TooltipContent>Load offline .metardu file</TooltipContent>
      </Tooltip>

      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            onClick={handleExportProject}
            className="gap-1.5"
          >
            <Download className="size-3.5" />
            <span className="hidden xl:inline">Save Project</span>
          </Button>
        </TooltipTrigger>
        <TooltipContent>Save to offline .metardu file</TooltipContent>
      </Tooltip>

      <div className="w-px h-6 bg-white/10 mx-1" />

      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            disabled={adjustLoading || !hasTraverseData}
            onClick={handleRunAdjustment}
            className="gap-1.5"
          >
            {adjustLoading ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <Activity className="size-3.5" />
            )}
            <span className="hidden sm:inline">Run Adjustment</span>
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {hasTraverseData
            ? 'Run Bowditch traverse adjustment'
            : 'Add traverse legs first'}
        </TooltipContent>
      </Tooltip>

      {/* Download Form C22 */}
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            disabled={formC22Loading || !hasAdjustedCoords}
            onClick={handleDownloadFormC22}
            className="gap-1.5"
          >
            {formC22Loading ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <FileText className="size-3.5" />
            )}
            <span className="hidden sm:inline">Form C22</span>
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {hasAdjustedCoords
            ? 'Download Form C22 computation sheet PDF'
            : 'Run adjustment first'}
        </TooltipContent>
      </Tooltip>

      {/* Export DXF */}
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            disabled={dxfLoading || !hasAdjustedCoords}
            onClick={handleExportDXF}
            className="gap-1.5"
          >
            {dxfLoading ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <Download className="size-3.5" />
            )}
            <span className="hidden sm:inline">DXF</span>
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {hasAdjustedCoords
            ? 'Export traverse plan as DXF'
            : 'Run adjustment first'}
        </TooltipContent>
      </Tooltip>

      {/* Export GeoJSON */}
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            disabled={geojsonLoading || !hasAdjustedCoords}
            onClick={handleExportGeoJSON}
            className="gap-1.5"
          >
            {geojsonLoading ? (
              <Loader2 className="size-3.5 animate-spin" />
            ) : (
              <MapPin className="size-3.5" />
            )}
            <span className="hidden sm:inline">GeoJSON</span>
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {hasAdjustedCoords
            ? 'Export adjusted coordinates as GeoJSON'
            : 'Run adjustment first'}
        </TooltipContent>
      </Tooltip>
    </div>
  )
}

'use client';

import React, { useEffect, useState, useMemo, useCallback } from 'react';
import {
  BookOpen,
  ExternalLink,
  Crosshair,
  Loader2,
  AlertCircle,
  TableProperties,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { createClient } from '@/lib/api-client/client';
import { SurveyType } from '@/types/project';
import { type FieldBookColumn, type FieldBookRow } from '@/types/fieldbook';
import { getFieldBookTemplate } from '@/lib/workflows/fieldBookTemplates';
import { useWorkspaceBridge } from '@/hooks/useWorkspaceBridge';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

interface FieldBookWithSelectionProps {
  projectId: string;
  surveyType: SurveyType;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

/** Identify which column represents the "station name" for selection */
function stationColumnFor(columns: FieldBookColumn[]): string {
  const fixed = columns.find(
    (c) =>
      c.fixedColumn === 'station' ||
      c.key === 'station' ||
      c.key === 'gcp_no' ||
      c.key === 'point_no',
  );
  return fixed?.key ?? columns[0]?.key ?? '';
}

/** Identify easting/northing column keys (if present) */
function coordColumnsFor(
  columns: FieldBookColumn[],
): { easting: string; northing: string } {
  let easting = '';
  let northing = '';

  for (const c of columns) {
    const k = c.key.toLowerCase();
    if (k === 'easting' || k === 'e') easting = c.key;
    if (k === 'northing' || k === 'n') northing = c.key;
  }

  return { easting, northing };
}

/** Safely format a number for display */
function fmtNum(v: string | number | null | undefined): string {
  if (v == null || v === '') return '—';
  const n = Number(v);
  return isNaN(n) ? String(v) : n.toFixed(3);
}

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

export default function FieldBookWithSelection({
  projectId,
  surveyType,
}: FieldBookWithSelectionProps) {
  const { selection, setSelection, clearSelection, addLog } =
    useWorkspaceBridge();

  const template = getFieldBookTemplate(surveyType);
  const columns = template.columns;

  const stationCol = useMemo(() => stationColumnFor(columns), [columns]);
  const { easting: eastingCol, northing: northingCol } = useMemo(
    () => coordColumnsFor(columns),
    [columns],
  );

  const [rows, setRows] = useState<FieldBookRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  /* ---- Load data from DB ---- */
  useEffect(() => {
    let cancelled = false;

    async function load() {
      setLoading(true);
      setError(null);

      try {
        const db = createClient();
        const { data, error: fetchError } = await db
          .from('project_fieldbook_entries')
          .select('*')
          .eq('project_id', projectId)
          .eq('survey_type', surveyType)
          .order('row_index', { ascending: true });

        if (cancelled) return;

        if (fetchError) {
          setError('Failed to load entries: ' + fetchError.message);
          addLog({
            phase: 'input',
            level: 'warning',
            message: `Failed to load field book entries: ${fetchError.message}`,
          });
          setLoading(false);
          return;
        }

        if (data && data.length > 0) {
          const loaded = data.map((r: Record<string, any>) => {
            const raw = (r.raw_data ?? {}) as Record<string, any>;
            const row: FieldBookRow = {} as FieldBookRow;
            for (const [k, v] of Object.entries(raw)) {
              row[k] = v as string | number | null;
            }
            // Also merge fixed columns from the top level
            for (const fixed of [
              'station',
              'bs',
              'is',
              'fs',
              'rl',
              'instrument_height',
              'remark',
            ] as const) {
              if (r[fixed] != null && !(fixed in row)) {
                row[fixed] = r[fixed];
              }
            }
            return row;
          });
          setRows(loaded);
          addLog({
            phase: 'input',
            level: 'success',
            message: `Loaded ${loaded.length} field book entries`,
          });
        } else {
          setRows([]);
        }
      } catch (err: unknown) {
        if (!cancelled) {
          const msg =
            err instanceof Error ? (err as Error).message : 'Unknown error';
          setError(msg);
          addLog({
            phase: 'input',
            level: 'error',
            message: `Error loading entries: ${msg}`,
          });
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    load();

    return () => {
      cancelled = true;
    };
  }, [projectId, surveyType, addLog]);

  /* ---- Row click handler ---- */
  const handleRowClick = useCallback(
    (rowIdx: number) => {
      const row = rows[rowIdx];
      if (!row) return;

      const stationName = String(row[stationCol] ?? `Row ${rowIdx + 1}`);
      const easting = eastingCol ? Number(row[eastingCol]) : undefined;
      const northing = northingCol ? Number(row[northingCol]) : undefined;

      if (
        selection.type === 'station' &&
        selection.index === rowIdx
      ) {
        // Toggle off
        clearSelection();
      } else {
        setSelection({
          type: 'station',
          index: rowIdx,
          stationName,
          easting: isNaN(easting as number) ? undefined : (easting as number),
          northing: isNaN(northing as number) ? undefined : (northing as number),
        });
      }
    },
    [rows, stationCol, eastingCol, northingCol, selection, setSelection, clearSelection],
  );

  /* ---- Navigate to full field book ---- */
  const handleGoToFieldBook = useCallback(() => {
    // Use Next.js router soft navigation
    window.location.hash = '#fieldbook';
  }, []);

  /* ---- Columns to display in the compact view ---- */
  // Show only the first 5 most relevant columns for the compact viewer
  const displayColumns = useMemo(() => {
    return columns.slice(0, 6);
  }, [columns]);

  return (
    <div className="flex flex-col h-full bg-[var(--bg-secondary)]">
      {/* ---- Header ---- */}
      <div className="flex items-center justify-between px-3 py-2 border-b border-[var(--border-color)] bg-[var(--bg-card)] flex-shrink-0">
        <div className="flex items-center gap-2 min-w-0">
          <TableProperties className="w-4 h-4 text-[var(--accent)] flex-shrink-0" />
          <h3 className="text-xs font-semibold text-[var(--text-primary)] truncate">
            {template.title}
          </h3>
          {!loading && !error && (
            <span className="text-xs font-medium tabular-nums bg-[var(--bg-tertiary)] text-[var(--text-secondary)] px-1.5 py-0.5 rounded flex-shrink-0">
              {rows.length} {rows.length === 1 ? 'entry' : 'entries'}
            </span>
          )}
        </div>

        <div className="flex items-center gap-1 flex-shrink-0">
          <button
            onClick={handleGoToFieldBook}
            className="flex items-center gap-1 px-2 py-1 rounded text-xs text-[var(--accent)] hover:bg-[var(--accent)]/10 transition-colors font-medium"
          >
            <BookOpen className="w-3 h-3" />
            <span>Go to Field Book</span>
            <ExternalLink className="w-2.5 h-2.5 opacity-60" />
          </button>
        </div>
      </div>

      {/* ---- Table ---- */}
      <div className="flex-1 overflow-auto min-h-0 custom-scrollbar">
        {/* Loading state */}
        {loading && (
          <div className="flex items-center justify-center h-32">
            <Loader2 className="w-4 h-4 text-[var(--accent)] animate-spin" />
            <span className="text-xs text-[var(--text-muted)] ml-2">
              Loading entries…
            </span>
          </div>
        )}

        {/* Error state */}
        {!loading && error && (
          <div className="flex items-start gap-2 p-3 m-2 rounded-md bg-red-500/5 border border-red-500/20">
            <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
            <div>
              <p className="text-xs text-red-300">Failed to load field book entries</p>
              <p className="text-xs text-[var(--text-muted)] mt-0.5">{error}</p>
            </div>
          </div>
        )}

        {/* Empty state */}
        {!loading && !error && rows.length === 0 && (
          <div className="flex flex-col items-center justify-center h-32 text-center select-none">
            <TableProperties className="w-5 h-5 text-[var(--text-muted)] mb-2" />
            <p className="text-xs text-[var(--text-muted)]">
              No observations recorded yet.
            </p>
            <p className="text-xs text-[var(--text-muted)] mt-0.5 opacity-70">
              Open the full Field Book to add entries.
            </p>
          </div>
        )}

        {/* Data table */}
        {!loading && !error && rows.length > 0 && (
          <table className="w-full text-xs border-collapse">
            <thead className="sticky top-0 z-10">
              <tr className="bg-[var(--bg-card)]">
                {/* Row number */}
                <th className="w-7 px-1 py-1.5 text-left text-xs font-medium text-[var(--text-muted)] border-b border-[var(--border-color)]">
                  #
                </th>
                {/* Station selection indicator */}
                <th className="w-5 py-1.5 border-b border-[var(--border-color)]" />
                {displayColumns.map((col) => (
                  <th
                    key={col.key}
                    className="px-2 py-1.5 text-left text-xs font-medium text-[var(--text-muted)] border-b border-[var(--border-color)] whitespace-nowrap"
                  >
                    {col.label}
                  </th>
                ))}
                {/* Extra column count */}
                {columns.length > 6 && (
                  <th className="px-2 py-1.5 text-left text-xs font-medium text-[var(--text-muted)] border-b border-[var(--border-color)]">
                    +{columns.length - 6}
                  </th>
                )}
              </tr>
            </thead>
            <tbody>
              {rows.map((row, rowIdx) => {
                const isSelected =
                  selection.type === 'station' &&
                  selection.index === rowIdx;

                return (
                  <tr
                    key={rowIdx}
                    onClick={() => handleRowClick(rowIdx)}
                    className={cn(
                      'cursor-pointer transition-colors border-b border-[var(--border-color)]/40',
                      isSelected
                        ? 'bg-[var(--accent)]/10 border-l-2 border-l-[var(--accent)]'
                        : 'hover:bg-[var(--bg-tertiary)] border-l-2 border-l-transparent',
                    )}
                  >
                    {/* Row number */}
                    <td className="px-1 py-1 text-xs text-[var(--text-muted)] text-right select-none font-mono">
                      {rowIdx + 1}
                    </td>
                    {/* Selection dot */}
                    <td className="py-1 text-center">
                      {isSelected && (
                        <Crosshair className="w-3 h-3 text-[var(--accent)] mx-auto" />
                      )}
                    </td>
                    {/* Data cells */}
                    {displayColumns.map((col) => {
                      const val = row[col.key];
                      const display = fmtNum(val as string | number | null | undefined);
                      const isCoordCol =
                        col.key === eastingCol || col.key === northingCol;

                      return (
                        <td
                          key={col.key}
                          className={cn(
                            'px-2 py-1 whitespace-nowrap max-w-[120px] truncate',
                            isCoordCol && 'font-mono text-xs',
                            isSelected
                              ? 'text-[var(--text-primary)]'
                              : 'text-[var(--text-secondary)]',
                          )}
                          title={display}
                        >
                          {display}
                        </td>
                      );
                    })}
                    {/* Extra indicator */}
                    {columns.length > 6 && (
                      <td className="px-2 py-1 text-xs text-[var(--text-muted)]">
                        …
                      </td>
                    )}
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {/* ---- Footer ---- */}
      {!loading && !error && rows.length > 0 && (
        <div className="flex items-center justify-between px-3 py-1.5 border-t border-[var(--border-color)] bg-[var(--bg-card)] flex-shrink-0">
          <span className="text-xs text-[var(--text-muted)]">
            Click a row to select it on the map
          </span>
          {selection.type !== 'none' && (
            <button
              onClick={clearSelection}
              className="text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)] transition-colors"
            >
              Clear selection
            </button>
          )}
        </div>
      )}
    </div>
  );
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Field-to-Finish Button
// ──────────────────────────────────────────────────────────────────────────
// One-click button that runs the complete pipeline:
//   EDM corrections → traverse adjustment → closure check → area → pre-submit
//
// Shows results inline — the surveyor sees everything in one place.
// ──────────────────────────────────────────────────────────────────────────

'use client';

import { useState } from 'react';
import { Zap, CheckCircle2, XCircle, AlertTriangle, Loader2, Ruler, MapPin, FileText, ChevronDown, ChevronUp } from 'lucide-react';

interface FieldToFinishResult {
  status: 'ready' | 'warning' | 'failed';
  instantFeedback: {
    closingErrorE: number;
    closingErrorN: number;
    linearMisclosure: number;
    perimeter: number;
    precisionRatio: number;
    precisionFormatted: string;
    passes: boolean;
    standard: string;
    grade: string;
    message: string;
  };
  area: {
    squareMetres: number;
    hectares: number;
    acres: number;
  };
  closureCheck: {
    closingErrorE: number;
    closingErrorN: number;
    perimeter: number;
    precisionRatio: string;
    passes: boolean;
  };
  corrections: Array<{
    from: string;
    to: string;
    rawSlopeDistance: number;
    correctedDistance: number;
    horizontalDistance: number;
    gridDistance: number;
    atmosphericPPM: number;
    curvatureRefractionMM: number;
    scaleFactor: number;
  }>;
  adjustedPoints: Array<{
    name: string;
    easting: number;
    northing: number;
  }>;
  deedPlanData: {
    boundaryPoints: Array<{ id: string; easting: number; northing: number }>;
    boundaryLegs: Array<{ from: string; to: string; bearing: string; distance: number }>;
    area: number;
  } | null;
  preSubmit: {
    ready: boolean;
    score: number;
    summary: string;
    blockers: number;
    warnings: number;
    categories: Array<{
      name: string;
      icon: string;
      items: Array<{
        label: string;
        status: 'pass' | 'fail' | 'warning' | 'skip';
        detail?: string;
        blocking: boolean;
      }>;
      passed: number;
      total: number;
    }>;
  };
  errors: string[];
  warnings: string[];
  processingTimeMs: number;
}

interface FieldToFinishButtonProps {
  projectId: string;
  disabled?: boolean;
}

export function FieldToFinishButton({ projectId, disabled }: FieldToFinishButtonProps) {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<FieldToFinishResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [expanded, setExpanded] = useState(false);

  const runPipeline = async () => {
    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const res = await fetch(`/api/project/${projectId}/field-to-finish`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || `Pipeline failed (${res.status})`);
      }

      const data = await res.json();
      setResult(data);
      setExpanded(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setLoading(false);
    }
  };

  const gradeColors: Record<string, string> = {
    excellent: 'text-emerald-400',
    good: 'text-green-400',
    acceptable: 'text-yellow-400',
    poor: 'text-orange-400',
    unacceptable: 'text-red-400',
  };

  return (
    <div className="space-y-3">
      {/* Main Button */}
      <button
        onClick={runPipeline}
        disabled={disabled || loading}
        className="w-full flex items-center justify-center gap-2 px-4 py-3 rounded-lg bg-gradient-to-r from-amber-600 to-amber-500 hover:from-amber-500 hover:to-amber-400 text-black font-semibold text-sm transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-amber-500/20"
      >
        {loading ? (
          <>
            <Loader2 className="w-4 h-4 animate-spin" />
            Running pipeline...
          </>
        ) : (
          <>
            <Zap className="w-4 h-4" />
            Field to Finish — One Click
          </>
        )}
      </button>

      {/* Error */}
      {error && (
        <div className="flex items-start gap-2 p-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-400 text-sm">
          <XCircle className="w-4 h-4 shrink-0 mt-0.5" />
          <span>{error}</span>
        </div>
      )}

      {/* Results */}
      {result && (
        <div className="rounded-lg border border-[var(--border-color)] overflow-hidden">
          {/* Header */}
          <div className={`p-3 flex items-center justify-between ${
            result.status === 'ready' ? 'bg-emerald-500/10' :
            result.status === 'warning' ? 'bg-yellow-500/10' :
            'bg-red-500/10'
          }`}>
            <div className="flex items-center gap-2">
              {result.status === 'ready' ? (
                <CheckCircle2 className="w-5 h-5 text-emerald-400" />
              ) : result.status === 'warning' ? (
                <AlertTriangle className="w-5 h-5 text-yellow-400" />
              ) : (
                <XCircle className="w-5 h-5 text-red-400" />
              )}
              <span className={`font-semibold text-sm ${
                result.status === 'ready' ? 'text-emerald-400' :
                result.status === 'warning' ? 'text-yellow-400' :
                'text-red-400'
              }`}>
                {result.status === 'ready' ? 'Ready for Submission' :
                 result.status === 'warning' ? 'Ready with Warnings' :
                 'Issues Found'}
              </span>
            </div>
            <span className="text-xs text-[var(--text-muted)]">{result.processingTimeMs}ms</span>
          </div>

          {/* Quick Stats */}
          <div className="grid grid-cols-3 gap-2 p-3 bg-[var(--bg-primary)]/40">
            <div className="text-center">
              <div className="text-xs text-[var(--text-muted)]">Precision</div>
              <div className={`font-mono font-bold text-sm ${gradeColors[result.instantFeedback.grade] || 'text-red-400'}`}>
                {result.instantFeedback.precisionFormatted}
              </div>
            </div>
            <div className="text-center">
              <div className="text-xs text-[var(--text-muted)]">Area</div>
              <div className="font-mono font-bold text-sm text-[var(--text-primary)]">
                {result.area.hectares > 0 ? `${result.area.hectares} ha` : '—'}
              </div>
            </div>
            <div className="text-center">
              <div className="text-xs text-[var(--text-muted)]">Pre-Submit</div>
              <div className={`font-bold text-sm ${result.preSubmit.ready ? 'text-emerald-400' : 'text-red-400'}`}>
                {result.preSubmit.score}%
              </div>
            </div>
          </div>

          {/* Expandable Details */}
          <button
            onClick={() => setExpanded(!expanded)}
            className="w-full flex items-center justify-between px-3 py-2 text-xs text-[var(--text-muted)] hover:bg-[var(--bg-secondary)]/40 transition-colors border-t border-[var(--border-color)]"
          >
            <span>Details & Pre-Submission Check</span>
            {expanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
          </button>

          {expanded && (
            <div className="p-3 space-y-3 border-t border-[var(--border-color)]">
              {/* Closure Detail */}
              <div className="grid grid-cols-2 gap-2 text-xs">
                <div className="flex items-center gap-1.5">
                  <Ruler className="w-3 h-3 text-muted-foreground" />
                  <div>
                    <div className="text-muted-foreground">Misclosure</div>
                    <div className="font-mono">{result.instantFeedback.linearMisclosure.toFixed(4)} m</div>
                  </div>
                </div>
                <div className="flex items-center gap-1.5">
                  <MapPin className="w-3 h-3 text-muted-foreground" />
                  <div>
                    <div className="text-muted-foreground">Perimeter</div>
                    <div className="font-mono">{result.instantFeedback.perimeter.toFixed(1)} m</div>
                  </div>
                </div>
              </div>

              {/* EDM Corrections Summary */}
              {result.corrections.length > 0 && (
                <div className="text-xs">
                  <div className="font-medium text-[var(--text-secondary)] mb-1">EDM Corrections Applied</div>
                  <div className="text-muted-foreground">
                    {result.corrections.length} observation(s) corrected — atmospheric, C&R, grid scale factor
                  </div>
                </div>
              )}

              {/* Pre-Submission Categories */}
              {result.preSubmit.categories.map((cat) => (
                <div key={cat.name} className="text-xs">
                  <div className="flex items-center gap-1.5 mb-1">
                    <span>{cat.icon}</span>
                    <span className="font-medium text-[var(--text-secondary)]">{cat.name}</span>
                    <span className="text-muted-foreground">({cat.passed}/{cat.total})</span>
                  </div>
                  <div className="space-y-0.5 ml-5">
                    {cat.items.map((item) => (
                      <div key={item.label} className="flex items-center gap-1.5">
                        {item.status === 'pass' ? (
                          <CheckCircle2 className="w-3 h-3 text-emerald-400" />
                        ) : item.status === 'fail' ? (
                          <XCircle className="w-3 h-3 text-red-400" />
                        ) : (
                          <AlertTriangle className="w-3 h-3 text-yellow-400" />
                        )}
                        <span className={item.status === 'pass' ? 'text-emerald-400' : item.status === 'fail' ? 'text-red-400' : 'text-yellow-400'}>
                          {item.label}
                        </span>
                        {item.detail && <span className="text-muted-foreground">— {item.detail}</span>}
                      </div>
                    ))}
                  </div>
                </div>
              ))}

              {/* Deed Plan Data */}
              {result.deedPlanData && (
                <div className="text-xs">
                  <div className="flex items-center gap-1.5 mb-1">
                    <FileText className="w-3 h-3 text-muted-foreground" />
                    <span className="font-medium text-[var(--text-secondary)]">Deed Plan Data Ready</span>
                  </div>
                  <div className="text-muted-foreground ml-5">
                    {result.deedPlanData.boundaryLegs.length} boundary legs, area: {(result.deedPlanData.area / 10000).toFixed(4)} ha
                  </div>
                </div>
              )}

              {/* Warnings */}
              {result.warnings.length > 0 && (
                <div className="space-y-1">
                  {result.warnings.map((w, i) => (
                    <div key={i} className="flex items-start gap-1.5 text-xs text-yellow-400">
                      <AlertTriangle className="w-3 h-3 shrink-0 mt-0.5" />
                      <span>{w}</span>
                    </div>
                  ))}
                </div>
              )}

              {/* Summary */}
              <div className={`text-xs p-2 rounded ${result.preSubmit.ready ? 'bg-emerald-500/10 text-emerald-400' : 'bg-red-500/10 text-red-400'}`}>
                {result.preSubmit.summary}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useId } from 'react';
import {
  FileText,
  Loader2,
  Download,
  AlertCircle,
  CheckCircle2,
  Info,
  RefreshCw,
} from 'lucide-react';
import { createClient, type BrowserSession } from '@/lib/api-client/client';
import { z } from 'zod';
import { apiPost, ApiError } from '@/lib/api/client';

// ─── API response schemas (Zod) ────────────────────────────────────────────
const formC22JsonResponseSchema = z.object({
  success: z.boolean().optional(),
  metadata: z.object({}).passthrough().optional(),
}).passthrough()

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ProjectData {
  id: string;
  name: string;
  lr_number: string | null;
  registration_district: string | null;
  locality: string | null;
  survey_type: string | null;
  area_ha: number | null;
  ref_no: string | null;
  surveyor_name: string | null;
  surveyor_isk: string | null;
  surveyor_firm: string | null;
}

interface C22Metadata {
  projectName: string;
  lrNumber: string;
  county: string;
  stationCount: number;
  areaHa: number;
  precisionRatio: number;
  angularMisclosureSec: number;
  linearMisclosureM: number;
}

interface Props {
  projectId: string;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function FormC22Generator({ projectId }: Props) {
  // Editable form state
  const [project, setProject] = useState<ProjectData | null>(null);
  const [lrNumber, setLrNumber] = useState('');
  const [county, setCounty] = useState('');
  const [division, setDivision] = useState('');
  const [district, setDistrict] = useState('');
  const [locality, setLocality] = useState('');
  const [surveyType, setSurveyType] = useState('');
  const [surveyorName, setSurveyorName] = useState('');
  const [iskNumber, setIskNumber] = useState('');
  const [firmName, setFirmName] = useState('');
  const [referenceNumber, setReferenceNumber] = useState('');
  const [revision, setRevision] = useState('');

  // UI state
  const [loadingProject, setLoadingProject] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [metadata, setMetadata] = useState<C22Metadata | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  // ── Load project data on mount ─────────────────────────────────────────
  useEffect(() => {
    async function loadProject() {
      try {
        setLoadingProject(true);
        const dbClient = createClient();

        const { data, error: dbError } = await dbClient
          .from('projects')
          .select('id, name, lr_number, registration_district, locality, survey_type, area_ha, ref_no')
          .eq('id', projectId)
          .maybeSingle();

        if (dbError) throw dbError;
        if (!data) {
          setError('Project not found');
          return;
        }

        const proj = data as unknown as ProjectData;

        // Also fetch surveyor profile
        const { data: sData } = await dbClient.auth.getSession();
        const session = sData?.session as BrowserSession | null | undefined;
        const userId = session?.user?.id;

        let surveyorNameVal = '';
        let iskNumberVal = '';
        let firmNameVal = '';

        if (userId) {
          const { data: spData } = await dbClient
            .from('surveyor_profiles')
            .select('isk_number, firm_name')
            .eq('user_id', userId)
            .maybeSingle();

          if (spData) {
            iskNumberVal = (spData as Record<string, unknown>).isk_number as string || '';
            firmNameVal = (spData as Record<string, unknown>).firm_name as string || '';
          }

          surveyorNameVal = session?.user?.user_metadata?.full_name || '';
        }

        const enriched: ProjectData = {
          ...proj,
          surveyor_name: surveyorNameVal,
          surveyor_isk: iskNumberVal,
          surveyor_firm: firmNameVal,
        };

        setProject(enriched);

        // Populate form fields from DB
        setLrNumber(enriched.lr_number || '');
        setCounty(enriched.registration_district || '');
        setLocality(enriched.locality || '');
        setSurveyType(enriched.survey_type || '');
        setSurveyorName(surveyorNameVal);
        setIskNumber(iskNumberVal);
        setFirmName(firmNameVal);
        setReferenceNumber(enriched.ref_no || '');
      } catch (err: unknown) {
        const msg = err instanceof Error ? (err as Error).message : 'Failed to load project data';
        setError(msg);
      } finally {
        setLoadingProject(false);
      }
    }

    loadProject();
  }, [projectId]);

  // ── Handle generate ───────────────────────────────────────────────────
  const handleGenerate = useCallback(async (format?: 'pdf' | 'json') => {
    setGenerating(true);
    setError(null);
    setSuccess(false);
    setMetadata(null);

    const requestBody = {
      projectId,
      county,
      division,
      district,
      locality,
      surveyType,
      revision,
      parcelNumber: '',
      referenceNumber,
    };

    try {
      if (format === 'json') {
        const json = await apiPost(
          '/api/submission/form-c22?format=json',
          formC22JsonResponseSchema,
          requestBody,
        );
        if (json.metadata) {
          setMetadata(json.metadata as unknown as C22Metadata);
        }
        return;
      }

      // PDF binary — auto-download
      // ponytail: binary download bypasses typed client
      const response = await fetch('/api/submission/form-c22', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestBody),
      });

      if (!response.ok) {
        const errBody = await response.json().catch(() => ({}));
        throw new Error(errBody.error || `Request failed (${response.status})`);
      }

      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;

      const safeName = (lrNumber || project?.name || 'form-c22')
        .replace(/[^a-zA-Z0-9_\- ]/g, '')
        .replace(/\s+/g, '_')
        .toLowerCase();
      a.download = `form-c22-${safeName}.pdf`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      setSuccess(true);

      // Also fetch metadata for the summary panel
      try {
        const metaJson = await apiPost(
          '/api/submission/form-c22?format=json',
          formC22JsonResponseSchema,
          requestBody,
        );
        if (metaJson.metadata) {
          setMetadata(metaJson.metadata as unknown as C22Metadata);
        }
      } catch {
        // Best-effort — PDF already downloaded successfully
      }
    } catch (err: unknown) {
      if (err instanceof ApiError) {
        setError(err.message);
      } else {
        const msg = err instanceof Error ? (err as Error).message : 'Failed to generate Form C22';
        setError(msg);
      }
    } finally {
      setGenerating(false);
    }
  }, [projectId, lrNumber, project?.name, county, division, district, locality, surveyType, revision, referenceNumber]);

  // ── Loading skeleton ──────────────────────────────────────────────────
  if (loadingProject) {
    return (
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-6 space-y-4">
        <div className="flex items-center gap-3">
          <Loader2 className="w-5 h-5 animate-spin text-[var(--accent)]" />
          <span className="text-sm text-[var(--text-muted)]">Loading project data…</span>
        </div>
      </div>
    );
  }

  if (error && !project) {
    return (
      <div className="rounded-xl border border-red-500/30 bg-red-500/5 p-6">
        <div className="flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-red-400 shrink-0 mt-0.5" />
          <div>
            <h3 className="font-semibold text-red-400 text-sm">Load Error</h3>
            <p className="text-sm text-red-400/80 mt-1">{error}</p>
          </div>
        </div>
      </div>
    );
  }

  // ── Main layout ───────────────────────────────────────────────────────
  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-5">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="flex items-center justify-center w-9 h-9 rounded-lg bg-[var(--accent)]/10 text-[var(--accent)]">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h2 className="font-semibold text-[var(--text-primary)] text-base">
                Form C22 — Computation Sheet
              </h2>
              <p className="text-xs text-[var(--text-muted)] mt-0.5">
                Generate a Republic of Kenya Form C22 PDF from traverse data
              </p>
            </div>
          </div>
          <span className="text-xs font-medium uppercase tracking-wider text-[var(--text-muted)] bg-[var(--bg-secondary)] px-2.5 py-1 rounded-full">
            Survey Act Cap 299
          </span>
        </div>
      </div>

      {/* Editable fields — two-column grid */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
        <div className="px-5 py-3 border-b border-[var(--border-color)] bg-[var(--bg-secondary)]">
          <h3 className="text-xs font-semibold uppercase tracking-wider text-[var(--text-muted)]">
            Project Information
          </h3>
        </div>
        <div className="p-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-5 gap-y-4">
          <FormField label="Project Name" value={project?.name || ''} disabled />
          <FormField label="LR Number" value={lrNumber} onChange={setLrNumber} />
          <FormField label="County / District" value={county} onChange={setCounty} />
          <FormField label="Division" value={division} onChange={setDivision} />
          <FormField label="District" value={district} onChange={setDistrict} />
          <FormField label="Locality" value={locality} onChange={setLocality} />
          <FormField label="Survey Type" value={surveyType} onChange={setSurveyType} />
          <FormField label="Reference No." value={referenceNumber} onChange={setReferenceNumber} />
          <FormField label="Revision" value={revision} onChange={setRevision} />
        </div>
      </div>

      {/* Surveyor fields */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
        <div className="px-5 py-3 border-b border-[var(--border-color)] bg-[var(--bg-secondary)]">
          <h3 className="text-xs font-semibold uppercase tracking-wider text-[var(--text-muted)]">
            Surveyor Information
          </h3>
        </div>
        <div className="p-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-x-5 gap-y-4">
          <FormField label="Surveyor Name" value={surveyorName} onChange={setSurveyorName} />
          <FormField label="ISK Number" value={iskNumber} onChange={setIskNumber} />
          <FormField label="Firm Name" value={firmName} onChange={setFirmName} />
        </div>
      </div>

      {/* Generate button */}
      <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] p-5 space-y-3">
        <div className="flex flex-col sm:flex-row flex-wrap items-start sm:items-center gap-3">
          <button
            onClick={() => handleGenerate('pdf')}
            disabled={generating}
            className="inline-flex items-center gap-2 px-5 py-2.5 bg-[var(--accent)] hover:bg-[var(--accent-dim)] text-white text-sm font-medium rounded-lg transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {generating ? (
              <Loader2 className="w-4 h-4 animate-spin" />
            ) : (
              <Download className="w-4 h-4" />
            )}
            {generating ? 'Generating C22…' : 'Generate C22 PDF'}
          </button>

          <button
            onClick={() => handleGenerate('json')}
            disabled={generating}
            className="inline-flex items-center gap-2 px-4 py-2.5 border border-[var(--border-color)] text-[var(--text-secondary)] text-sm font-medium rounded-lg hover:bg-[var(--bg-secondary)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {generating ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <Info className="w-3.5 h-3.5" />
            )}
            Preview Metadata
          </button>
        </div>

        {/* Success banner */}
        {success && (
          <div className="flex items-center gap-2 text-xs text-emerald-400 bg-emerald-500/10 p-3 rounded-lg border border-emerald-500/20">
            <CheckCircle2 className="w-4 h-4 shrink-0" />
            Form C22 PDF generated and downloaded successfully.
          </div>
        )}

        {/* Error banner */}
        {error && (
          <div className="flex items-start gap-2 text-xs text-red-400 bg-red-500/10 p-3 rounded-lg border border-red-500/20">
            <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
            <div>
              <span className="font-medium">Generation failed: </span>
              {error}
            </div>
          </div>
        )}

        {/* Info hint */}
        {!success && !error && !generating && (
          <div className="flex items-center gap-2 text-xs text-[var(--text-muted)] bg-[var(--bg-secondary)] p-3 rounded-lg">
            <Info className="w-3.5 h-3.5 shrink-0" />
            Ensure traverse data has been computed (Step 3) before generating. The C22 sheet uses adjusted coordinates and closure data.
          </div>
        )}
      </div>

      {/* Metadata summary (shown after preview or generation) */}
      {metadata && (
        <div className="rounded-xl border border-[var(--border-color)] bg-[var(--bg-card)] overflow-hidden">
          <div className="px-5 py-3 border-b border-[var(--border-color)] bg-[var(--bg-secondary)] flex items-center justify-between">
            <h3 className="text-xs font-semibold uppercase tracking-wider text-[var(--text-muted)]">
              C22 Sheet Metadata
            </h3>
            <button
              onClick={() => handleGenerate('json')}
              className="inline-flex items-center gap-1 text-xs text-[var(--text-muted)] hover:text-[var(--accent)] transition-colors"
            >
              <RefreshCw className="w-3 h-3" />
              Refresh
            </button>
          </div>
          <div className="p-5 grid grid-cols-2 sm:grid-cols-4 gap-4">
            <StatBox label="Stations" value={String(metadata.stationCount)} />
            <StatBox label="Area" value={`${metadata.areaHa.toFixed(4)} Ha`} />
            <StatBox
              label="Precision"
              value={metadata.precisionRatio > 0 ? `1 : ${Math.round(metadata.precisionRatio).toLocaleString()}` : '—'}
            />
            <StatBox
              label="Linear Misclosure"
              value={`${metadata.linearMisclosureM.toFixed(4)} m`}
            />
          </div>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
