import React, { type ReactNode, useState, useCallback } from 'react';
import {
  ResizablePanelGroup,
  ResizablePanel,
  ResizableHandle,
} from '@/components/ui/resizable';
import {
  ChevronDown,
  ChevronUp,
  Activity,
  Crosshair,
  AlertTriangle,
  CheckCircle2,
