/**
 * apiHandler — Standardized API route wrapper for METARDU.
 *
 * Solves G1 (auth enforcement), G2 (Zod validation), G7 (error handling)
 * in a single composable function that every API route uses.
 *
 * When auth:true, automatically sets RLS context via setCurrentUserId()
 * so that PostgreSQL row-level security policies work correctly.
 *
 * Usage:
 * export const GET = apiHandler({ auth: true }, async (req, ctx) => { ... })
 * export const POST = apiHandler({ auth: true, schema: CreateProjectSchema }, async (req, ctx) => { ... })
 * export const POST = apiHandler({ auth: false, rateLimit: { max: 3, windowMs: 60000 } }, async (req, ctx) => { ... })
 * export const POST = apiHandler({ auth: true, rawBody: true }, async (req, ctx) => { ... })  // no JSON parse
 *
 * Method-level overrides (different auth/validation per HTTP method):
 * export const GET = apiHandler({ auth: false }, async (req, ctx) => { ... })
 * export const POST = apiHandler({ auth: true, schema }, async (req, ctx) => { ... })
 * export const PATCH = apiHandler({ auth: true, schema, optimisticLock: true }, async (req, ctx) => { ... })
 */

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { rateLimit, getClientIdentifier } from '@/lib/security/rateLimit'
import { auditLog } from '@/lib/logger'
import { setCurrentUserId, setCurrentOrgId } from '@/lib/db'
import { db } from '@/lib/db'
import { captureError } from '@/lib/monitoring/sentry'
import { appendAuditEntry } from '@/lib/audit/auditLog'
import type { AuditEntityType, AuditAction } from '@/lib/audit/auditHash'
import type { ZodSchema } from 'zod'
import type { Session } from 'next-auth'

export interface ApiHandlerContext {
  session: Session | null
  userId: string
  body: unknown
  params: Record<string, string>
}

/**
 * Tamper-evident audit chain configuration for a route.
 *
 * AUDIT FIX (C3, 2026-07-02): The audit_chain table and appendAuditEntry()
 * function existed but were only called in 4 files. This option lets any
 * route opt into the tamper-evident log with one line:
 *
 *   export const POST = apiHandler({
 *     auth: true,
 *     auditChain: {
 *       entityType: 'parcel',
 *       action: 'update',
 *       entityIdParam: 'id',         // URL param name
 *       projectIdFromBody: 'projectId', // optional: body field name
 *     },
 *     schema: UpdateParcelSchema,
 *   }, async (req, ctx) => { ... })
 *
 * The entry is appended AFTER the handler returns a 2xx response, so
 * failed mutations are not recorded. Audit chain failures are logged
 * but do NOT block the response — the mutation has already happened.
 */
export interface AuditChainConfig {
  /** Entity type for the audit entry (e.g., 'parcel', 'traverse', 'document'). */
  entityType: AuditEntityType
  /** Action for the audit entry (e.g., 'create', 'update', 'delete', 'generate'). */
  action: AuditAction
  /**
   * Name of the URL parameter containing the entity ID.
   * For /api/parcels/[id], this is 'id'.
   * If not found in params, falls back to body.id.
   */
  entityIdParam?: string
  /**
   * Name of the body field containing the project ID (optional).
   * If not found, projectId is omitted from the audit entry.
   */
  projectIdFromBody?: string
  /**
   * Name of the URL parameter containing the project ID (optional).
   * Takes precedence over projectIdFromBody.
   */
  projectIdFromParam?: string
  /**
   * Optional reason text for the audit entry (e.g., "boundary adjustment").
   * Defaults to `${method} ${pathname}`.
   */
  reason?: string
}

export interface ApiHandlerOptions {
  auth?: boolean
  schema?: ZodSchema
  rateLimit?: { max: number; windowMs: number }
  audit?: string
  roles?: string[]
  rawBody?: boolean
  /**
   * Enable optimistic locking for PATCH/PUT requests.
   * Requires the request body to include an `updated_at` field.
   * The handler should check that the DB's updated_at matches the submitted value.
   * If there's a mismatch, returns 409 Conflict.
   */
  optimisticLock?: boolean
  /**
   * Tamper-evident audit chain configuration. When set, the handler
   * appends an entry to the audit_chain table after a successful (2xx)
   * response. See AuditChainConfig for details.
   */
  auditChain?: AuditChainConfig
  /**
   * Attach an X-Request-Id header to the response for distributed tracing.
   * Defaults to true (audit H3 fix, 2026-07-02). Set to false to opt out.
   */
  requestId?: boolean
  /**
   * Emit structured JSON log lines for errors (level, message, timestamp,
   * requestId, userId, path, method). Defaults to true. Set to false to
   * keep the legacy `console.error('[apiHandler] ...')` format.
   */
  structuredLogs?: boolean
}

type HandlerFn = (
  req: NextRequest,
  ctx: ApiHandlerContext
) => Promise<NextResponse>

export function apiHandler(
  options: ApiHandlerOptions,
  handler: HandlerFn
): (req: NextRequest, context?: { params?: Record<string, string | string[]> }) => Promise<NextResponse> {
  const {
    auth = true,
    schema,
    rateLimit: rlConfig,
    audit: auditAction,
    roles,
    rawBody,
    auditChain,
    requestId: enableRequestId = true,
    structuredLogs = true,
  } = options

  // AUDIT FIX (H3, 2026-07-02): Generate a per-request ID for distributed
  // tracing. Added to the response as X-Request-Id header and to error logs.
  const generateRequestId = (): string => {
    return `req_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`
  }

  return async (req, context) => {
    const reqId = enableRequestId ? generateRequestId() : undefined
    let userId = 'anonymous'
    try {
      if (rlConfig) {
        const identifier = getClientIdentifier(req)
        const { allowed, remaining } = await rateLimit(identifier, rlConfig.max, rlConfig.windowMs)
        if (!allowed) {
          return NextResponse.json(
            { error: 'Too many requests. Please try again later.', code: 'RATE_LIMITED' },
            { status: 429, headers: { 'X-RateLimit-Remaining': String(remaining) } }
          )
        }
      }

      let session: Session | null = null
      if (auth) {
        const s = await getServerSession(authOptions)
        if (!s?.user) {
          return NextResponse.json(
            { error: 'Authentication required', code: 'UNAUTHORIZED' },
            { status: 401 }
          )
        }
        session = s

        // Set RLS context so PostgreSQL current_user_id() works
        const uid = (s.user as { id?: string }).id
        if (uid) {
          setCurrentUserId(String(uid))

          // AUDIT FIX (C6, 2026-07-02): Look up the user's active organization
          // and set the org RLS context. A user can be a member of multiple
          // orgs; we pick the most recently active one. Routes can override
          // this by calling setCurrentOrgId() explicitly (e.g. after the
          // user switches orgs via the UI).
          try {
            const orgResult = await db.query(
              `SELECT om.organization_id
               FROM organization_members om
               WHERE om.user_id = $1 AND om.is_active = TRUE
               ORDER BY om.accepted_at DESC NULLS LAST, om.invited_at DESC
               LIMIT 1`,
              [uid]
            )
            if (orgResult.rows.length > 0) {
              setCurrentOrgId(String(orgResult.rows[0].organization_id))
            }
          } catch {
            // Organizations table may not exist yet (pre-migration 028).
            // Silent fail — org context stays null, RLS falls back to user_id.
          }
        }

        if (roles && roles.length > 0) {
          const userRole = (session.user as { role?: string }).role ?? 'surveyor'
          if (!roles.includes(userRole)) {
            return NextResponse.json(
              { error: 'Insufficient permissions', code: 'FORBIDDEN' },
              { status: 403 }
            )
          }
        }
      }

      userId = (session?.user as { id?: string })?.id ?? 'anonymous'

      let body: unknown = undefined
      if (req.method !== 'GET' && req.method !== 'HEAD' && req.method !== 'DELETE' && !rawBody) {
        try {
          body = await req.json()
        } catch {
          return NextResponse.json(
            { error: 'Invalid JSON body', code: 'INVALID_BODY' },
            { status: 400 }
          )
        }

        if (schema) {
          const parsed = schema.safeParse(body)
          if (!parsed.success) {
            return NextResponse.json(
              { error: 'Validation failed', code: 'VALIDATION_ERROR', issues: parsed.error.issues },
              { status: 400 }
            )
          }
          body = parsed.data
        }

        // Optimistic locking check for PATCH/PUT
        if (options.optimisticLock && (req.method === 'PATCH' || req.method === 'PUT')) {
          const bodyObj = body as Record<string, unknown>
          if (!bodyObj.updated_at) {
            return NextResponse.json(
              { error: 'Optimistic locking requires updated_at field', code: 'CONFLICT_CHECK_REQUIRED' },
              { status: 400 }
            )
          }
        }
      }

      const rawParams = context?.params || {}
      const params: Record<string, string> = {}
      for (const [key, val] of Object.entries(rawParams)) {
        params[key] = Array.isArray(val) ? val[0] : val
      }

      const ctx: ApiHandlerContext = {
        // When auth: false, session is null — callers must handle this
        session: session as Session,
        userId,
        body,
        params,
      }

      const result = await handler(req, ctx)

      if (auditAction && auth) {
        auditLog(userId, auditAction, `${req.method} ${req.nextUrl.pathname}`)
      }

      // Tamper-evident audit chain (audit C3 fix, 2026-07-02).
      // Only append for 2xx responses — failed mutations are not audited
      // in the chain (they're still in the audit_logs table via DB triggers).
      if (auditChain && auth && result.status >= 200 && result.status < 300) {
        try {
          const entityId =
            (auditChain.entityIdParam && params[auditChain.entityIdParam]) ||
            (body as Record<string, unknown> | undefined)?.id as string | undefined ||
            'unknown'

          let projectId: string | undefined
          if (auditChain.projectIdFromParam && params[auditChain.projectIdFromParam]) {
            projectId = params[auditChain.projectIdFromParam]
          } else if (auditChain.projectIdFromBody) {
            const bodyObj = body as Record<string, unknown> | undefined
            const pid = bodyObj?.[auditChain.projectIdFromBody]
            if (typeof pid === 'string') projectId = pid
          }

          await appendAuditEntry({
            projectId,
            userId,
            entityType: auditChain.entityType,
            entityId: String(entityId),
            action: auditChain.action,
            payload: {
              metadata: {
                method: req.method,
                path: req.nextUrl.pathname,
                reason: auditChain.reason,
                status: result.status,
                timestamp: new Date().toISOString(),
              },
            },
          })
        } catch (auditErr) {
          // Audit chain failure should NOT block the response — the
          // mutation has already happened. Log and continue.
          console.warn(
            `[apiHandler] appendAuditEntry failed for ${req.method} ${req.nextUrl.pathname}:`,
            auditErr instanceof Error ? auditErr.message : auditErr
          )
        }
      }

      // AUDIT FIX (H3, 2026-07-02): Attach X-Request-Id to successful
      // responses too (not just errors) for end-to-end tracing.
      if (reqId && result.headers) {
        result.headers.set('X-Request-Id', reqId)
      }

      return result
    } catch (err: unknown) {
      // AUDIT FIX (H3, 2026-07-02): Structured JSON logging (opt-in by default).
      // Includes requestId, userId, path, method for distributed tracing.
      if (structuredLogs) {
        console.error(JSON.stringify({
          level: 'error',
          message: err instanceof Error ? err.message : String(err),
          timestamp: new Date().toISOString(),
          requestId: reqId,
          userId,
          path: req.nextUrl.pathname,
          method: req.method,
          stack: err instanceof Error ? err.stack : undefined,
        }))
      } else {
        console.error('[apiHandler] Unhandled error:', err)
      }

      // Send to Sentry (only in production, key scrubbed by beforeSend)
      captureError(err instanceof Error ? err : new Error(String(err)), {
        path: req.nextUrl.pathname,
        method: req.method,
        userId,
        requestId: reqId,
      })

      const pgCode = (err as { code?: string })?.code
      const errorResponse = (status: number, error: string, code: string) => {
        const headers: Record<string, string> = {}
        if (reqId) headers['X-Request-Id'] = reqId
        return NextResponse.json({ error, code, ...(reqId ? { requestId: reqId } : {}) }, { status, headers })
      }

      if (pgCode === '23505') {
        return errorResponse(409, 'This record already exists', 'DUPLICATE')
      }
      if (pgCode === '23503') {
        return errorResponse(400, 'Referenced record not found', 'FOREIGN_KEY_VIOLATION')
      }
      if (pgCode === '42501') {
        return errorResponse(403, 'Permission denied', 'PERMISSION_DENIED')
      }

      return errorResponse(500, 'Internal server error', 'INTERNAL_ERROR')
    }
  }
}

/**
 * Check optimistic locking conflict inside a handler.
 * Call this after fetching the current DB row but before applying updates.
 *
 * @returns NextResponse (409) if conflict detected, null if no conflict
 *
 * @example
 * const conflict = checkOptimisticLock(ctx.body, dbRow)
 * if (conflict) return conflict
 */
export function checkOptimisticLock(
  requestBody: Record<string, unknown>,
  dbRow: { updated_at: string | Date | null }
): NextResponse | null {
  const clientUpdatedAt = requestBody.updated_at as string | undefined
  if (!clientUpdatedAt || !dbRow.updated_at) return null

  const clientTime = new Date(clientUpdatedAt).getTime()
  const dbTime = new Date(dbRow.updated_at).getTime()

  // Allow 1-second tolerance for clock drift / rounding
  if (Math.abs(clientTime - dbTime) > 1000) {
    return NextResponse.json(
      {
        error: 'This record was modified by another user. Please refresh and try again.',
        code: 'CONFLICT',
        db_updated_at: dbRow.updated_at,
      },
      { status: 409 }
    )
  }
  return null
}

/**
 * Standardized success response helpers
 */
export function apiSuccess(data: unknown, status = 200) {
  return NextResponse.json(data, { status })
}

export function apiCreated(data: unknown) {
  return NextResponse.json(data, { status: 201 })
}

export function apiNoContent() {
  return new NextResponse(null, { status: 204 })
}

'use client'

/**
 * QueryProvider — v0.3 redesign
 *
 * Adds offline-first configuration per native-data-fetching skill:
 * - onlineManager integration with navigator.onLine + window online/offline events
 * - Smarter retry: only retry on 5xx and network errors, not 4xx
 * - Longer staleTime for calculator results (deterministic, cacheable)
 * - Deduped queries per default
 *
 * Also wraps children with OnlineStatusProvider for the OfflineIndicator.
 */

import { useState, useEffect } from 'react'
import { QueryClient, QueryClientProvider, onlineManager } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import { ApiError } from './client'

// ─── Online status integration ──────────────────────────────────────────────

let onlineManagerInitialized = false

function initOnlineManager() {
  if (onlineManagerInitialized || typeof window === 'undefined') return
  onlineManagerInitialized = true

  // Set initial state
  onlineManager.setOnline(navigator.onLine)

  // Listen to browser online/offline events
  window.addEventListener('online', () => onlineManager.setOnline(true))
  window.addEventListener('offline', () => onlineManager.setOnline(false))

  // If Capacitor Network plugin is available (mobile), use it for richer events
  // This is optional — on web we fall back to navigator.onLine
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const capacitor = (window as any).Capacitor
  if (capacitor?.Plugins?.Network) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const Network = capacitor.Plugins.Network
    Network.addListener('networkStatusChange', (status: any) => {
      onlineManager.setOnline(status.connected)
    })
      .catch(() => { /* plugin not ready, ignore — navigator.onLine still works */ })
  }
}

// ─── Retry logic ────────────────────────────────────────────────────────────

/**
 * Retry only on network errors and 5xx. Don't retry 4xx (client error).
 * Per native-data-fetching skill: exponential backoff 2^attempt × 1000ms.
 */
function retryFunction(failureCount: number, error: unknown): boolean {
  // Don't retry 4xx client errors
  if (error instanceof ApiError) {
    if (error.status >= 400 && error.status < 500) return false
    if (error.code === 'UNAUTHORIZED' || error.code === 'FORBIDDEN') return false
  }
  // Retry network errors (status 0) and 5xx, max 3 attempts
  return failureCount < 3
}

// ─── Provider ───────────────────────────────────────────────────────────────

export default function QueryProvider({ children }: { children: React.ReactNode }) {
  useEffect(() => {
    initOnlineManager()
  }, [])

  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            staleTime: 5 * 60 * 1000, // 5 min default
            gcTime: 30 * 60 * 1000,   // 30 min garbage collection
            retry: retryFunction,
            refetchOnWindowFocus: false,
            // Don't refetch on reconnect if data is fresh — avoids hammering
            // the server when coming back online with a queue of pending work
            refetchOnReconnect: 'always',
          },
          mutations: {
            retry: retryFunction,
          },
        },
      })
  )

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      {process.env.NODE_ENV === 'development' && (
        <ReactQueryDevtools initialIsOpen={false} />
      )}
    </QueryClientProvider>
  )
}

// ─── Network status hook (for OfflineIndicator component) ───────────────────

export function useOnlineStatus(): boolean {
  const [isOnline, setIsOnline] = useState(
    typeof navigator !== 'undefined' ? navigator.onLine : true
  )

  useEffect(() => {
    const handleOnline = () => setIsOnline(true)
    const handleOffline = () => setIsOnline(false)
    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)
    return () => {
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
    }
  }, [])

  return isOnline
}

/**
 * Self-check for the API client.
 * ponytail: one runnable check, the smallest thing that fails if logic breaks.
 * Run:  npx tsx src/lib/api/__tests__/client.selfcheck.ts
 */

import { api, apiGet, apiPost, apiDelete, apiInvalidate, apiInvalidateAll, ApiError } from '../client'
import { z } from 'zod'
import assert from 'node:assert'

const ProjectSchema = z.object({ id: z.string(), name: z.string() })
type Project = z.infer<typeof ProjectSchema>

const origFetch = globalThis.fetch

function installMock(opts: { status: number; body: unknown; headers?: Record<string, string> }) {
  globalThis.fetch = (async (_input: RequestInfo | URL, _init?: RequestInit) => {
    // ponytail: 204 No Content MUST NOT have a body per HTTP spec
    if (opts.status === 204) {
      return new Response(null, {
        status: 204,
        headers: { 'Content-Type': 'application/json', ...opts.headers },
      })
    }
    return new Response(JSON.stringify(opts.body), {
      status: opts.status,
      headers: { 'Content-Type': 'application/json', ...opts.headers },
    })
  }) as typeof fetch
}

function restoreFetch() { globalThis.fetch = origFetch }

let pass = 0
let fail = 0
async function check(name: string, fn: () => void | Promise<void>) {
  try {
    const r = fn()
    if (r instanceof Promise) await r
    pass++
    console.log(`   ${name}`)
  } catch (err) {
    fail++
    console.error(`   ${name}: ${(err as Error).message}`)
  }
}

async function main() {
  console.log('API client self-check\n')

  await check('200 OK with valid schema returns parsed body', async () => {
    installMock({ status: 200, body: { id: 'p1', name: 'FR 583' } })
    const result = await api('/api/projects/p1', ProjectSchema)
    assert.equal(result.id, 'p1')
    assert.equal(result.name, 'FR 583')
    restoreFetch()
  })

  await check('204 No Content returns undefined', async () => {
    installMock({ status: 204, body: null })
    const result = await api<null | undefined>('/api/projects/p1', z.null().optional())
    assert.equal(result, undefined)
    restoreFetch()
  })

  await check('401 throws ApiError with code UNAUTHORIZED', async () => {
    installMock({ status: 401, body: { error: 'Authentication required', code: 'UNAUTHORIZED' } })
    await assert.rejects(
      () => api('/api/projects/p1', ProjectSchema),
      (err: unknown) => {
        assert.ok(err instanceof ApiError)
        assert.equal(err.status, 401)
        assert.equal(err.code, 'UNAUTHORIZED')
        assert.equal(err.isUnauthorized, true)
        return true
      },
    )
    restoreFetch()
  })

  await check('400 VALIDATION_ERROR includes issues array', async () => {
    installMock({
      status: 400,
      body: { error: 'Validation failed', code: 'VALIDATION_ERROR',
              issues: [{ path: ['name'], message: 'Required' }] },
    })
    await assert.rejects(
      () => api('/api/projects', ProjectSchema, { method: 'POST', body: {} as BodyInit }),
      (err: unknown) => {
        assert.ok(err instanceof ApiError)
        assert.equal(err.code, 'VALIDATION_ERROR')
        assert.ok(err.issues && err.issues.length > 0)
        assert.equal(err.isValidation, true)
        return true
      },
    )
    restoreFetch()
  })

  await check('Response schema mismatch throws ApiError', async () => {
    installMock({ status: 200, body: { id: 'p1' } })
    await assert.rejects(
      () => api('/api/projects/p1', ProjectSchema),
      (err: unknown) => {
        assert.ok(err instanceof ApiError)
        assert.equal(err.code, 'INTERNAL_ERROR')
        assert.match(err.message, /schema mismatch/)
        return true
      },
    )
    restoreFetch()
  })

  await check('apiGet caches responses within TTL', async () => {
    let callCount = 0
    globalThis.fetch = (async () => {
      callCount++
      return new Response(JSON.stringify({ id: 'p1', name: `call-${callCount}` }), {
        status: 200, headers: { 'Content-Type': 'application/json' },
      })
    }) as typeof fetch
    apiInvalidateAll()
    const r1 = await apiGet('/api/projects/p1', ProjectSchema, { ttlMs: 5000 })
    const r2 = await apiGet('/api/projects/p1', ProjectSchema, { ttlMs: 5000 })
    assert.equal(callCount, 1)
    assert.deepEqual(r1, r2)
    restoreFetch()
  })

  await check('apiInvalidate forces next apiGet to re-fetch', async () => {
    let callCount = 0
    globalThis.fetch = (async () => {
      callCount++
      return new Response(JSON.stringify({ id: 'p1', name: 'X' }), {
        status: 200, headers: { 'Content-Type': 'application/json' },
      })
    }) as typeof fetch
    apiInvalidateAll()
    await apiGet('/api/projects/p2', ProjectSchema, { ttlMs: 5000 })
    apiInvalidate('/api/projects/p2')
    await apiGet('/api/projects/p2', ProjectSchema, { ttlMs: 5000 })
    assert.equal(callCount, 2)
    restoreFetch()
  })

  await check('apiPost sends JSON body with Content-Type header', async () => {
    let capturedInit: RequestInit | undefined
    globalThis.fetch = (async (_input, init) => {
      capturedInit = init
      return new Response(JSON.stringify({ id: 'p2', name: 'new' }), {
        status: 201, headers: { 'Content-Type': 'application/json' },
      })
    }) as typeof fetch
    await apiPost('/api/projects', ProjectSchema, { name: 'new' })
    assert.equal(capturedInit?.method, 'POST')
    assert.equal((capturedInit?.headers as Record<string, string>)?.['Content-Type'], 'application/json')
    assert.equal(capturedInit?.body, JSON.stringify({ name: 'new' }))
    restoreFetch()
  })

  await check('apiDelete without schema accepts 204', async () => {
    installMock({ status: 204, body: null })
    await apiDelete('/api/projects/p3')
    restoreFetch()
  })

  await check('Server with no code field falls back to status-based guess', async () => {
    installMock({ status: 404, body: { error: 'Not found' } })
    await assert.rejects(
      () => api('/api/projects/missing', ProjectSchema),
      (err: unknown) => {
        assert.ok(err instanceof ApiError)
        assert.equal(err.code, 'NOT_FOUND')
        assert.equal(err.isNotFound, true)
        return true
      },
    )
    restoreFetch()
  })

  console.log(`\n${pass} passed, ${fail} failed`)
  if (fail > 0) process.exit(1)
}

main().catch((err) => { console.error('Self-check crashed:', err); process.exit(1) })

const AI_BASE_URL = process.env.NEXT_PUBLIC_AI_SERVICE_URL || 'https://metardu-ai.up.railway.app'

export interface AICallOptions {
  endpoint: string
  body: Record<string, unknown>
  requirePro?: boolean
}

export interface AIResponse<T> {
  success: boolean
  data: T | null
  error: string | null
  tier: string | null
  callsRemaining: number | null
}

/**
 * Check if the current user has a paid subscription.
 * Uses the /api/subscription endpoint which includes admin email detection
 * and correctly reads from user_subscriptions (not profiles.tier).
 */
async function checkSubscriptionAccess(): Promise<{ allowed: boolean; plan: string; isAdmin: boolean }> {
  try {
    const res = await fetch('/api/subscription', {
      cache: 'no-store',
      credentials: 'same-origin',
    })
    if (!res.ok) return { allowed: false, plan: 'free', isAdmin: false }

    const data = await res.json()
    const plan = data.plan || 'free'
    const isAdmin = data.isAdmin === true

    // Admin always has access; paid plans (pro, team, firm, enterprise) have access
    const allowed = isAdmin || ['pro', 'team', 'firm', 'enterprise'].includes(plan)
    return { allowed, plan, isAdmin }
  } catch {
    return { allowed: false, plan: 'free', isAdmin: false }
  }
}

export async function callAI<T>(options: AICallOptions): Promise<AIResponse<T>> {
  const { endpoint, body, requirePro = true } = options

  if (requirePro) {
    const access = await checkSubscriptionAccess()
    if (!access.allowed) {
      return {
        success: false,
        data: null,
        error: 'PRO_REQUIRED',
        tier: access.plan,
        callsRemaining: null,
      }
    }
  }

  try {
    const response = await fetch(`${AI_BASE_URL}${endpoint}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    })

    if (response.status === 403) {
      return {
        success: false,
        data: null,
        error: 'PRO_REQUIRED',
        tier: null,
        callsRemaining: null,
      }
    }

    if (!response.ok) {
      const errorText = await response.text()
      return {
        success: false,
        data: null,
        error: `AI_SERVICE_ERROR: ${response.status}`,
        tier: null,
        callsRemaining: null,
      }
    }

    const data = await response.json()
    return {
      success: true,
      data: data as T,
      error: null,
      tier: null,
      callsRemaining: null,
    }
  } catch (err) {
    return {
      success: false,
      data: null,
      error: err instanceof Error ? err.message : 'UNKNOWN_ERROR',
      tier: null,
      callsRemaining: null,
    }
  }
}

export function isProError(response: AIResponse<unknown>): boolean {
  return !response.success && response.error === 'PRO_REQUIRED'
}

/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * METARDU — Central API Client
 * ═══════════════════════════════════════════════════════════════════════════════
 *
 * ponytail: native fetch + Zod parse, no axios. One error path, one place to
 * add retry / cache / telemetry. Replaces the ~217 inline `fetch()` calls
 * scattered across client components.
 *
 * Server-side: apiHandler (src/lib/apiHandler.ts) already enforces auth,
 * validates the request body with Zod, and returns a uniform error envelope:
 *   { error: string, code: string, issues?: ZodIssue[] }
 *
 * Client-side: this `api()` function mirrors that contract. Use the SAME Zod
 * schema on both sides — the server validates input, the client validates
 * output. One source of truth.
 */

import type { ZodSchema, ZodIssue } from 'zod'
import { z } from 'zod'

// ─── Error Types ───────────────────────────────────────────────────────────

export type ApiErrorCode =
  | 'UNAUTHORIZED'
  | 'FORBIDDEN'
  | 'VALIDATION_ERROR'
  | 'RATE_LIMITED'
  | 'DUPLICATE'
  | 'FOREIGN_KEY_VIOLATION'
  | 'PERMISSION_DENIED'
  | 'INTERNAL_ERROR'
  | 'CONFLICT'
  | 'CONFLICT_CHECK_REQUIRED'
  | 'INVALID_BODY'
  | 'NOT_FOUND'
  | 'BAD_REQUEST'
  | (string & {})

export class ApiError extends Error {
  readonly code: ApiErrorCode
  readonly status: number
  readonly issues?: ZodIssue[]
  readonly body?: unknown

  constructor(
    status: number,
    code: ApiErrorCode,
    message: string,
    opts?: { issues?: ZodIssue[]; body?: unknown },
  ) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.code = code
    this.issues = opts?.issues
    this.body = opts?.body
  }

  get isUnauthorized(): boolean { return this.code === 'UNAUTHORIZED' || this.status === 401 }
  get isForbidden(): boolean { return this.code === 'FORBIDDEN' || this.code === 'PERMISSION_DENIED' || this.status === 403 }
  get isValidation(): boolean { return this.code === 'VALIDATION_ERROR' }
  get isNotFound(): boolean { return this.code === 'NOT_FOUND' || this.status === 404 }
  get isRateLimited(): boolean { return this.code === 'RATE_LIMITED' || this.status === 429 }
}

// ─── Core `api()` Function ─────────────────────────────────────────────────

export async function api<T>(
  path: string,
  schema: ZodSchema<T>,
  init?: RequestInit,
): Promise<T> {
  const bodyIsObj = init?.body !== undefined && typeof init.body === 'object' && !(init.body instanceof FormData) && !(init.body instanceof Blob)
  const r = await fetch(path, {
    ...init,
    body: bodyIsObj ? JSON.stringify(init.body) : init?.body,
    headers: {
      ...(init?.body !== undefined && bodyIsObj ? { 'Content-Type': 'application/json' } : {}),
      ...init?.headers,
    },
  })

  if (r.status === 204) {
    return undefined as unknown as T
  }

  const text = await r.text()
  let parsed: unknown = undefined
  if (text) {
    try { parsed = JSON.parse(text) }
    catch { parsed = text }
  }

  if (!r.ok) {
    const errBody = (parsed && typeof parsed === 'object' && parsed !== null) ? parsed as Record<string, unknown> : {}
    const code = (errBody.code as ApiErrorCode) ?? guessCodeFromStatus(r.status)
    const message = (errBody.error as string) ?? r.statusText ?? 'API request failed'
    const issues = errBody.issues as ZodIssue[] | undefined
    throw new ApiError(r.status, code, message, { issues, body: parsed })
  }

  const result = schema.safeParse(parsed)
  if (!result.success) {
    if (process.env.NODE_ENV !== 'production') {
      console.error(`[api] Response schema mismatch for ${path}:`, result.error.issues)
    }
    throw new ApiError(r.status, 'INTERNAL_ERROR', `Response schema mismatch for ${path}`, {
      issues: result.error.issues,
      body: parsed,
    })
  }

  return result.data
}

function guessCodeFromStatus(status: number): ApiErrorCode {
  switch (status) {
    case 400: return 'BAD_REQUEST'
    case 401: return 'UNAUTHORIZED'
    case 403: return 'FORBIDDEN'
    case 404: return 'NOT_FOUND'
    case 409: return 'CONFLICT'
    case 429: return 'RATE_LIMITED'
    case 500: return 'INTERNAL_ERROR'
    default: return 'INTERNAL_ERROR'
  }
}

// ─── `apiGet()` — Cached GET helper ────────────────────────────────────────

const _cache = new Map<string, { t: number; v: unknown; promise: Promise<unknown> | null }>()

export async function apiGet<T>(
  path: string,
  schema: ZodSchema<T>,
  opts?: { ttlMs?: number; signal?: AbortSignal; init?: RequestInit },
): Promise<T> {
  const ttl = opts?.ttlMs ?? 30_000
  if (ttl > 0) {
    const hit = _cache.get(path)
    if (hit) {
      if (Date.now() - hit.t < ttl) return hit.v as T
      if (hit.promise) return hit.promise as Promise<T>
    }
  }

  const promise = api<T>(path, schema, { ...opts?.init, signal: opts?.signal })
  if (ttl > 0) {
    _cache.set(path, { t: Date.now(), v: undefined as unknown, promise })
    try {
      const v = await promise
      _cache.set(path, { t: Date.now(), v, promise: null })
      return v
    } catch (err) {
      _cache.delete(path)
      throw err
    }
  }
  return promise
}

export function apiInvalidate(pathOrPrefix: string): void {
  _cache.delete(pathOrPrefix)
  for (const key of _cache.keys()) {
    if (key.startsWith(pathOrPrefix)) _cache.delete(key)
  }
}

export function apiInvalidateAll(): void {
  _cache.clear()
}

// ─── Convenience helpers ───────────────────────────────────────────────────

export async function apiPost<T>(
  path: string,
  schema: ZodSchema<T>,
  body: unknown,
  init?: RequestInit,
): Promise<T> {
  return api(path, schema, { ...init, method: 'POST', body: body as BodyInit })
}

export async function apiPatch<T>(
  path: string,
  schema: ZodSchema<T>,
  body: unknown,
  init?: RequestInit,
): Promise<T> {
  return api(path, schema, { ...init, method: 'PATCH', body: body as BodyInit })
}

export async function apiPut<T>(
  path: string,
  schema: ZodSchema<T>,
  body: unknown,
  init?: RequestInit,
): Promise<T> {
  return api(path, schema, { ...init, method: 'PUT', body: body as BodyInit })
}

export async function apiDelete<T = void>(
  path: string,
  schema?: ZodSchema<T>,
  init?: RequestInit,
): Promise<T | void> {
  if (schema) {
    return api<T>(path, schema, { ...init, method: 'DELETE' })
  }
  const zNullable = z.null().optional() as ZodSchema<null | undefined>
  await api<null | undefined>(path, zNullable, { ...init, method: 'DELETE' })
}

/**
 * apiHandler — Next-generation standardized API route wrapper for METARDU.
 *
 * @deprecated (audit H3, 2026-07-02): Use `@/lib/apiHandler` (v1) instead.
 *   The v1 handler now has feature parity with this v2:
 *     - X-Request-Id header (opt-in via `requestId: true`, default true)
 *     - Structured JSON error logging (opt-in via `structuredLogs: true`, default true)
 *     - Tamper-evident audit chain (opt-in via `auditChain` option)
 *     - Optimistic locking support
 *     - Org-aware RLS context
 *   This v2 file is kept for the 5 routes that import it, but new routes
 *   should use v1. A future cleanup will migrate the 5 v2 consumers and
 *   delete this file.
 *
 * This is the v2 handler that builds on lessons from the original
 * `@/lib/apiHandler`. It provides:
 *
 *   - Automatic try/catch with standardized error response format
 *   - Consistent error-to-HTTP-status mapping (Zod → 422, AppError subclasses → proper codes)
 *   - PostgreSQL error code mapping (23505 → 409, 23503 → 400)
 *   - Optional `requireAuth` with automatic session checking and RLS context
 *   - Optional `requiredRole` for role-based access control
 *   - Optional Zod schema validation for request bodies with validated `ctx.input`
 *   - X-Request-Id header on every response for distributed tracing
 *   - Structured error logging with request context
 *
 * Usage:
 *   export const GET = apiHandler({
 *     requireAuth: true,
 *     handler: async (ctx) => { ... }
 *   })
 *
 *   export const POST = apiHandler({
 *     requireAuth: true,
 *     requiredRole: ['admin', 'super_admin'],
 *     schema: createProjectSchema,
 *     handler: async (ctx) => { ... }
 *   })
 *
 * Backward compatibility:
 *   The original `@/lib/apiHandler` is untouched. Existing routes that import
 *   from `@/lib/apiHandler` continue to work without changes. New and
 *   refactored routes should import from `@/lib/api/handler`.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { setCurrentUserId } from '@/lib/db'
import { captureError } from '@/lib/monitoring/sentry'
import { rateLimit, getClientIdentifier } from '@/lib/security/rateLimit'
import { auditLog } from '@/lib/logger'
import type { ZodSchema } from 'zod'
import type { Session } from 'next-auth'
import {
  AppError,
  AuthenticationError,
  AuthorizationError,
  NotFoundError,
  ConflictError,
  ValidationError,
  RateLimitError,
} from './errors'

// ─── Types ─────────────────────────────────────────────────────────────────────

/**
 * Context object passed to every handler function.
 * Provides request, validated input, auth info, and route params.
 */
export interface ApiContext<TInput = unknown> {
  /** The original Next.js request object */
  req: NextRequest
  /** Route parameters extracted from the URL (e.g. [id]) */
  params: Record<string, string>
  /** Validated request body — typed when a Zod schema is provided */
  input: TInput
  /** Authenticated user ID (set when requireAuth is true) */
  userId: string
  /** Authenticated user email (set when requireAuth is true) */
  userEmail: string
  /** Authenticated user role (set when requireAuth is true) */
  userRole: string
  /** Full NextAuth session (available when requireAuth is true) */
  session: Session | null
}

/**
 * Configuration for an apiHandler-wrapped route.
 */
export interface ApiHandlerConfig<TInput = unknown> {
  /** Whether to require authentication. Defaults to false. */
  requireAuth?: boolean
  /** Roles allowed to access this route. Requires requireAuth: true. */
  requiredRole?: string[]
  /** Zod schema for request body validation. Validated data becomes ctx.input. */
  schema?: ZodSchema<TInput>
  /** Rate limiting configuration */
  rateLimit?: { max: number; windowMs: number }
  /** Audit action name — logged via auditLog when auth is present */
  audit?: string
  /**
   * Enable optimistic locking for PATCH/PUT requests.
   * Requires ctx.input to include an `updated_at` field.
   */
  optimisticLock?: boolean
  /**
   * Skip JSON body parsing (e.g. for file uploads or raw body handling).
   * ctx.input will be undefined.
   */
  rawBody?: boolean
  /** The actual route handler logic */
  handler: (ctx: ApiContext<TInput>) => Promise<NextResponse>
}

/** Standardized error response shape */
interface ErrorResponse {
  error: string
  code?: string
  details?: unknown
}

// ─── Request ID generation ─────────────────────────────────────────────────────

let _requestCounter = 0

function generateRequestId(): string {
  _requestCounter++
  // Combine timestamp + counter + random for uniqueness across instances
  const ts = Date.now().toString(36)
  const rand = Math.random().toString(36).slice(2, 8)
  return `req_${ts}_${_requestCounter}_${rand}`
}

// ─── Zod error formatting ──────────────────────────────────────────────────────

interface ZodIssue {
  path: (string | number)[]
  message: string
  code: string
}

interface ZodErrorLike {
  issues: ZodIssue[]
  flatten?: () => { fieldErrors: Record<string, string[]> }
}

function formatZodDetails(err: ZodErrorLike): Record<string, string[]> {
  // Prefer flatten() if available (structured per-field)
  if (typeof err.flatten === 'function') {
    return err.flatten().fieldErrors
  }
  // Fallback: group issues by path
  const grouped: Record<string, string[]> = {}
  for (const issue of err.issues) {
    const key = issue.path.join('.') || '_root'
    if (!grouped[key]) grouped[key] = []
    grouped[key].push(issue.message)
  }
  return grouped
}

// ─── Error response builder ────────────────────────────────────────────────────

function buildErrorResponse(
  error: unknown,
  requestId: string
): NextResponse {
  const headers = { 'X-Request-Id': requestId }

  // 1. Our custom AppError hierarchy — direct mapping
  if (error instanceof AppError) {
    return NextResponse.json(
      {
        error: error.message,
        code: error.code,
        details: error.details,
      } satisfies ErrorResponse,
      { status: error.statusCode, headers }
    )
  }

  // 2. ZodError — 422 with structured validation details
  if (error && typeof error === 'object' && 'issues' in error && Array.isArray((error as ZodErrorLike).issues)) {
    const zodErr = error as ZodErrorLike
    return NextResponse.json(
      {
        error: 'Validation failed',
        code: 'VALIDATION_ERROR',
        details: formatZodDetails(zodErr),
      } satisfies ErrorResponse,
      { status: 422, headers }
    )
  }

  // 3. PostgreSQL error codes
  const pgCode = (error as { code?: string })?.code
  if (pgCode === '23505') {
    return NextResponse.json(
      { error: 'This record already exists', code: 'DUPLICATE' } satisfies ErrorResponse,
      { status: 409, headers }
    )
  }
  if (pgCode === '23503') {
    return NextResponse.json(
      { error: 'Referenced record not found', code: 'FOREIGN_KEY_VIOLATION' } satisfies ErrorResponse,
      { status: 400, headers }
    )
  }
  if (pgCode === '42501') {
    return NextResponse.json(
      { error: 'Permission denied', code: 'PERMISSION_DENIED' } satisfies ErrorResponse,
      { status: 403, headers }
    )
  }

  // 4. Generic fallback — 500, no information leakage
  return NextResponse.json(
    { error: 'Internal server error', code: 'INTERNAL_ERROR' } satisfies ErrorResponse,
    { status: 500, headers }
  )
}

// ─── Structured error logger ───────────────────────────────────────────────────

function logError(
  error: unknown,
  context: {
    method: string
    path: string
    userId: string
    requestId: string
  }
) {
  const isAppError = error instanceof AppError
  const status = isAppError ? error.statusCode : 500
  const code = isAppError ? error.code : 'INTERNAL_ERROR'
  const message = error instanceof Error ? error.message : String(error)

  const logLevel = status >= 500 ? 'error' : 'warn'

  if (logLevel === 'error') {
    console.error(
      JSON.stringify({
        level: 'error',
        message: `[apiHandler] ${context.method} ${context.path} → ${status}`,
        timestamp: new Date().toISOString(),
        requestId: context.requestId,
        userId: context.userId,
        errorCode: code,
        errorMessage: message,
        stack: error instanceof Error ? error.stack : undefined,
      })
    )
  } else {
    console.warn(
      JSON.stringify({
        level: 'warn',
        message: `[apiHandler] ${context.method} ${context.path} → ${status}`,
        timestamp: new Date().toISOString(),
        requestId: context.requestId,
        userId: context.userId,
        errorCode: code,
        errorMessage: message,
      })
    )
  }
}

// ─── Main apiHandler function ──────────────────────────────────────────────────

/**
 * Higher-order function that wraps a Next.js API route handler with
 * standardized error handling, auth checking, validation, and response formatting.
 *
 * @example
 * // Simple authenticated GET
 * export const GET = apiHandler({
 *   requireAuth: true,
 *   handler: async (ctx) => {
 *     const data = await db.query('SELECT * FROM projects WHERE user_id = $1', [ctx.userId])
 *     return NextResponse.json({ data: data.rows })
 *   },
 * })
 *
 * @example
 * // POST with Zod validation and role check
 * export const POST = apiHandler({
 *   requireAuth: true,
 *   requiredRole: ['admin'],
 *   schema: createProjectSchema,
 *   handler: async (ctx) => {
 *     // ctx.input is fully typed and validated
 *     const project = await createProject(ctx.input)
 *     return NextResponse.json({ data: project }, { status: 201 })
 *   },
 * })
 */
export function apiHandler<TInput = unknown>(
  config: ApiHandlerConfig<TInput>
): (req: NextRequest, context?: { params?: Record<string, string | string[]> }) => Promise<NextResponse> {
  const {
    requireAuth = false,
    requiredRole,
    schema,
    rateLimit: rlConfig,
    audit: auditAction,
    optimisticLock,
    rawBody,
    handler,
  } = config

  return async (req, context) => {
    const requestId = generateRequestId()
    // ByteByteGo audit: distributed tracing — extract/generate trace context
    let traceId = ''
    try {
      const { getTraceContext } = await import('@/lib/monitoring/tracing')
      const traceCtx = getTraceContext(req)
      traceId = traceCtx.traceId
    } catch {}
    let userId = 'anonymous'
    let userEmail = ''
    let userRole = ''

    try {
      // ─── Rate limiting ─────────────────────────────────────────────────
      if (rlConfig) {
        const identifier = getClientIdentifier(req)
        const { allowed, remaining } = await rateLimit(identifier, rlConfig.max, rlConfig.windowMs)
        if (!allowed) {
          throw new RateLimitError('Too many requests. Please try again later.', {
            remaining,
          })
        }
      }

      // ─── Authentication ────────────────────────────────────────────────
      let session: Session | null = null

      if (requireAuth) {
        const s = await getServerSession(authOptions)
        if (!s?.user) {
          throw new AuthenticationError('Authentication required')
        }
        session = s

        userId = String((s.user as { id?: string }).id ?? 'anonymous')
        userEmail = String(s.user.email ?? '')
        userRole = String((s.user as { role?: string }).role ?? 'surveyor')

        // Set RLS context so PostgreSQL current_user_id() works
        if (userId && userId !== 'anonymous') {
          setCurrentUserId(userId)
        }

        // Role-based access control
        if (requiredRole && requiredRole.length > 0) {
          if (!requiredRole.includes(userRole)) {
            throw new AuthorizationError(
              `Insufficient permissions. Required: ${requiredRole.join(' or ')}, got: ${userRole}`
            )
          }
        }
      }

      // ─── Request body parsing & validation ─────────────────────────────
      let input: TInput = undefined as TInput

      if (req.method !== 'GET' && req.method !== 'HEAD' && req.method !== 'DELETE' && !rawBody) {
        try {
          const rawBody = await req.json()

          if (schema) {
            const parsed = schema.safeParse(rawBody)
            if (!parsed.success) {
              throw new ValidationError('Validation failed', formatZodDetails(parsed.error as unknown as ZodErrorLike))
            }
            input = parsed.data as TInput
          } else {
            input = rawBody as TInput
          }
        } catch (err) {
          // If it's already a ValidationError from schema parsing, re-throw
          if (err instanceof ValidationError) throw err
          // JSON parse failure
          throw new ValidationError('Invalid JSON body', { parseError: true })
        }

        // Optimistic locking check for PATCH/PUT
        if (optimisticLock && (req.method === 'PATCH' || req.method === 'PUT')) {
          const bodyObj = input as Record<string, unknown>
          if (!bodyObj.updated_at) {
            throw new ValidationError('Optimistic locking requires updated_at field', {
              field: 'updated_at',
            })
          }
        }
      }

      // ─── Route params ──────────────────────────────────────────────────
      const rawParams = context?.params || {}
      const params: Record<string, string> = {}
      for (const [key, val] of Object.entries(rawParams)) {
        params[key] = Array.isArray(val) ? val[0] : val ?? ''
      }

      // ─── Build context and call handler ────────────────────────────────
      const ctx: ApiContext<TInput> = {
        req,
        params,
        input,
        userId,
        userEmail,
        userRole,
        session,
      }

      const result = await handler(ctx)

      // ─── Audit logging ─────────────────────────────────────────────────
      if (auditAction && requireAuth && userId !== 'anonymous') {
        auditLog(userId, auditAction, `${req.method} ${req.nextUrl.pathname}`)
      }

      // ─── Attach X-Request-Id to successful responses ──────────────────
      result.headers.set('X-Request-Id', requestId)
      if (traceId) result.headers.set('X-Trace-Id', traceId)
      return result
    } catch (err: unknown) {
      // ─── Structured logging ────────────────────────────────────────────
      logError(err, {
        method: req.method,
        path: req.nextUrl.pathname,
        userId,
        requestId,
      })

      // ─── Sentry capture ────────────────────────────────────────────────
      captureError(
        err instanceof Error ? err : new Error(String(err)),
        {
          path: req.nextUrl.pathname,
          method: req.method,
          userId,
          requestId,
        }
      )

      // ─── Build standardized error response ─────────────────────────────
      const response = buildErrorResponse(err, requestId)
      return response
    }
  }
}

// ─── Convenience response helpers ──────────────────────────────────────────────

/**
 * Return a success JSON response with optional status code.
 */
export function apiSuccess(data: unknown, status = 200, headers?: Record<string, string>): NextResponse {
  return NextResponse.json(data, { status, headers })
}

/**
 * Return a 201 Created response.
 */
export function apiCreated(data: unknown): NextResponse {
  return NextResponse.json(data, { status: 201 })
}

/**
 * Return a 204 No Content response.
 */
export function apiNoContent(): NextResponse {
  return new NextResponse(null, { status: 204 })
}

/**
 * Check optimistic locking conflict inside a handler.
 * Call this after fetching the current DB row but before applying updates.
 *
 * @returns NextResponse (409) if conflict detected, null if no conflict
 *
 * @example
 * const conflict = checkOptimisticLock(ctx.input, dbRow)
 * if (conflict) return conflict
 */
export function checkOptimisticLock(
  requestBody: Record<string, unknown>,
  dbRow: { updated_at: string | Date | null }
): NextResponse | null {
  const clientUpdatedAt = requestBody.updated_at as string | undefined
  if (!clientUpdatedAt || !dbRow.updated_at) return null

  const clientTime = new Date(clientUpdatedAt).getTime()
  const dbTime = new Date(dbRow.updated_at).getTime()

  // Allow 1-second tolerance for clock drift / rounding
  if (Math.abs(clientTime - dbTime) > 1000) {
    return NextResponse.json(
      {
        error: 'This record was modified by another user. Please refresh and try again.',
        code: 'CONFLICT',
        db_updated_at: dbRow.updated_at,
      },
      { status: 409 }
    )
  }
  return null
}

// Re-export error classes for convenience
export {
  AppError,
  AuthenticationError,
  AuthorizationError,
  NotFoundError,
  ConflictError,
  ValidationError,
  RateLimitError,
} from './errors'

/**
 * Offline Mutation Queue — v0.3 redesign
 *
 * Per native-data-fetching + system-design skills:
 * - Stores pending mutations in IndexedDB when offline
 * - Generates client UUIDs for optimistic inserts
 * - Syncs FIFO when reconnects (oldest first)
 * - Handles conflicts by UUID (server reconciles)
 *
 * Usage:
 *   import { offlineQueue } from '@/lib/api/offline-queue'
 *
 *   // When a mutation fails because we're offline:
 *   await offlineQueue.enqueue({
 *     url: '/api/v1/projects/123/observations',
 *     method: 'POST',
 *     body: { station: 'T1', bearing: '87°14\'22"', distance: 124.83 },
 *     clientUuid: crypto.randomUUID(),
 *   })
 *
 *   // The queue auto-syncs on reconnect. Subscribe to know when it drains:
 *   const unsubscribe = offlineQueue.onSyncComplete(() => refetchData())
 */

import { onlineManager } from '@tanstack/react-query'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface QueuedMutation {
  id: string                  // client-generated UUID, primary key
  url: string                 // API endpoint, e.g. '/api/v1/projects/123/observations'
  method: 'POST' | 'PUT' | 'PATCH' | 'DELETE'
  body?: unknown              // request body (JSON-serializable)
  createdAt: number           // epoch ms, for FIFO ordering
  attempts: number            // retry counter
  lastError?: string          // last error message, for debugging
  // Optional: which query keys to invalidate after this mutation syncs
  invalidateQueries?: string[][]
}

// ─── IndexedDB storage (lazy-initialized) ───────────────────────────────────

const DB_NAME = 'metardu-offline'
const STORE_NAME = 'mutations'
const DB_VERSION = 1

let dbPromise: Promise<IDBDatabase> | null = null

function getDb(): Promise<IDBDatabase> {
  if (typeof indexedDB === 'undefined') {
    return Promise.reject(new Error('IndexedDB not available'))
  }
  if (dbPromise) return dbPromise

  dbPromise = new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION)
    req.onerror = () => reject(req.error)
    req.onsuccess = () => resolve(req.result)
    req.onupgradeneeded = () => {
      const db = req.result
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' })
        store.createIndex('createdAt', 'createdAt', { unique: false })
      }
    }
  })
  return dbPromise
}

async function dbAdd(mutation: QueuedMutation): Promise<void> {
  const db = await getDb()
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite')
    tx.objectStore(STORE_NAME).add(mutation)
    tx.oncomplete = () => resolve()
    tx.onerror = () => reject(tx.error)
  })
}

async function dbGetAll(): Promise<QueuedMutation[]> {
  const db = await getDb()
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly')
    const req = tx.objectStore(STORE_NAME).getAll()
    req.onsuccess = () => resolve(req.result as QueuedMutation[])
    req.onerror = () => reject(req.error)
  })
}

async function dbDelete(id: string): Promise<void> {
  const db = await getDb()
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite')
    tx.objectStore(STORE_NAME).delete(id)
    tx.oncomplete = () => resolve()
    tx.onerror = () => reject(tx.error)
  })
}

async function dbUpdate(mutation: QueuedMutation): Promise<void> {
  const db = await getDb()
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite')
    tx.objectStore(STORE_NAME).put(mutation)
    tx.oncomplete = () => resolve()
    tx.onerror = () => reject(tx.error)
  })
}

// ─── Queue class ────────────────────────────────────────────────────────────

class OfflineMutationQueue {
  private syncing = false
  private listeners = new Set<() => void>()

  /** Subscribe to sync-complete events. Returns unsubscribe fn. */
  onSyncComplete(fn: () => void): () => void {
    this.listeners.add(fn)
    return () => this.listeners.delete(fn)
  }

  private notifySyncComplete() {
    this.listeners.forEach(fn => {
      try { fn() } catch { /* listener error — don't break sync */ }
    })
  }

  /** Returns true if IndexedDB is available (i.e. we're in a browser). */
  isAvailable(): boolean {
    return typeof indexedDB !== 'undefined'
  }

  /** Enqueue a mutation for later sync. Generates a UUID if not provided. */
  async enqueue(m: Omit<QueuedMutation, 'id' | 'createdAt' | 'attempts'> & { id?: string }): Promise<QueuedMutation> {
    const mutation: QueuedMutation = {
      id: m.id || (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID()! : `mut-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      url: m.url,
      method: m.method,
      body: m.body,
      createdAt: Date.now(),
      attempts: 0,
      invalidateQueries: m.invalidateQueries,
    }
    await dbAdd(mutation)
    return mutation
  }

  /** Returns the count of pending mutations (0 if unavailable). */
  async pendingCount(): Promise<number> {
    if (!this.isAvailable()) return 0
    try {
      const all = await dbGetAll()
      return all.length
    } catch {
      return 0
    }
  }

  /** Returns all pending mutations, ordered oldest-first. */
  async pending(): Promise<QueuedMutation[]> {
    if (!this.isAvailable()) return []
    try {
      const all = await dbGetAll()
      return all.sort((a, b) => a.createdAt - b.createdAt)
    } catch {
      return []
    }
  }

  /**
   * Sync all pending mutations. Called automatically on reconnect.
   * Returns the number of successfully synced mutations.
   *
   * Stops on first failure to preserve order (FIFO). Failed mutation
   * gets attempts++ and lastError set; will be retried next sync.
   */
  async sync(): Promise<{ synced: number; failed: number; remaining: number }> {
    if (this.syncing) return { synced: 0, failed: 0, remaining: 0 }
    if (!this.isAvailable()) return { synced: 0, failed: 0, remaining: 0 }
    if (!onlineManager.isOnline()) return { synced: 0, failed: 0, remaining: 0 }

    this.syncing = true
    let synced = 0
    let failed = 0

    try {
      const queue = await this.pending()
      for (const mutation of queue) {
        try {
          const response = await fetch(mutation.url, {
            method: mutation.method,
            headers: {
              'Content-Type': 'application/json',
              'X-Client-UUID': mutation.id,
            },
            body: mutation.body ? JSON.stringify(mutation.body) : undefined,
          })
          if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`)
          }
          await dbDelete(mutation.id)
          synced++
        } catch (err) {
          // Don't retry 4xx — those are client errors, will fail again
          if (err instanceof Error && /HTTP 4\d\d/.test(err.message)) {
            await dbDelete(mutation.id)
            failed++
            console.warn(`[offline-queue] dropping 4xx mutation ${mutation.id}:`, err.message)
          } else {
            // Network error or 5xx — increment attempts, will retry next sync
            mutation.attempts++
            mutation.lastError = err instanceof Error ? err.message : String(err)
            await dbUpdate(mutation)
            // Stop sync on first network failure to preserve order
            break
          }
        }
      }

      const remaining = await this.pendingCount()
      if (synced > 0) this.notifySyncComplete()
      return { synced, failed, remaining }
    } finally {
      this.syncing = false
    }
  }
}

// ─── Singleton ──────────────────────────────────────────────────────────────

export const offlineQueue = new OfflineMutationQueue()

// ─── Auto-sync on reconnect ─────────────────────────────────────────────────

if (typeof window !== 'undefined') {
  // Sync when browser comes back online
  window.addEventListener('online', () => {
    offlineQueue.sync().catch(err => {
      console.error('[offline-queue] sync failed on reconnect:', err)
    })
  })

  // Also subscribe to React Query's onlineManager (covers Capacitor Network plugin)
  onlineManager.subscribe(() => {
    if (onlineManager.isOnline()) {
      offlineQueue.sync().catch(err => {
        console.error('[offline-queue] sync failed on onlineManager event:', err)
      })
    }
  })

  // On page load, if we're online, try to drain any pending mutations from last session
  setTimeout(() => {
    if (navigator.onLine) {
      offlineQueue.sync().catch(() => { /* silent — will retry on next online event */ })
    }
  }, 2000)
}

/**
 * Tests for the Audit Chain — tamper-evident append-only log.
 *
 * Coverage:
 *   - Pure functions: computeEntryHash, canonicalJSON
 *   - Hash determinism (same input → same hash)
 *   - Hash sensitivity (any field change → different hash)
 *   - Chain linking (each entry's hash includes the previous)
 *   - Tamper detection (modified entry → verification fails)
 *   - Broken link detection (inserted/deleted entry → verification fails)
 *   - Canonical JSON key ordering (insertion order doesn't matter)
 *
 * The DB-dependent functions (appendAuditEntry, verifyChain, queryAuditEntries)
 * require a live PostgreSQL instance and are not unit-tested here.
 * They're covered by integration tests in the e2e suite.
 */

import {
  computeEntryHash,
  canonicalJSON,
  type AuditPayload,
} from '../auditHash'

// ─── Helpers ────────────────────────────────────────────────────────────

const baseParams = {
  previousHash: null,
  sequence: 1,
  projectId: 'proj-1',
  userId: 'user-1',
  entityType: 'control_point' as const,
  entityId: 'CP1',
  action: 'update' as const,
  payload: {
    old: { easting: 250000, northing: 9945000 },
    new: { easting: 250050, northing: 9945050 },
    reason: 'Helmert recalibration',
  },
  createdAt: '2026-07-01T12:00:00.000Z',
}

// ─── Hash determinism ──────────────────────────────────────────────────

describe('computeEntryHash', () => {
  it('produces a 64-character hex string', async () => {
    const hash = await computeEntryHash(baseParams)
    expect(hash).toMatch(/^[0-9a-f]{64}$/)
  })

  it('is deterministic — same input always produces the same hash', async () => {
    const hash1 = await computeEntryHash(baseParams)
    const hash2 = await computeEntryHash(baseParams)
    expect(hash1).toBe(hash2)
  })

  it('produces different hashes for different previousHash', async () => {
    const hash1 = await computeEntryHash(baseParams)
    const hash2 = await computeEntryHash({
      ...baseParams,
      previousHash: 'abc123',
    })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different sequence numbers', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, sequence: 1 })
    const hash2 = await computeEntryHash({ ...baseParams, sequence: 2 })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different entity ids', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, entityId: 'CP1' })
    const hash2 = await computeEntryHash({ ...baseParams, entityId: 'CP2' })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different actions', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, action: 'create' })
    const hash2 = await computeEntryHash({ ...baseParams, action: 'update' })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different payloads', async () => {
    const hash1 = await computeEntryHash({
      ...baseParams,
      payload: { ...baseParams.payload, reason: 'reason A' },
    })
    const hash2 = await computeEntryHash({
      ...baseParams,
      payload: { ...baseParams.payload, reason: 'reason B' },
    })
    expect(hash1).not.toBe(hash2)
  })

  it('produces different hashes for different timestamps', async () => {
    const hash1 = await computeEntryHash({
      ...baseParams,
      createdAt: '2026-07-01T12:00:00.000Z',
    })
    const hash2 = await computeEntryHash({
      ...baseParams,
      createdAt: '2026-07-01T12:00:01.000Z',
    })
    expect(hash1).not.toBe(hash2)
  })

  it('treats null and empty string previousHash the same (genesis entry)', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, previousHash: null })
    const hash2 = await computeEntryHash({ ...baseParams, previousHash: '' })
    // Both produce the same hash because null ?? '' = '' in the canonical form
    expect(hash1).toBe(hash2)
  })

  it('treats null and undefined projectId the same', async () => {
    const hash1 = await computeEntryHash({ ...baseParams, projectId: null })
    const hash2 = await computeEntryHash({ ...baseParams, projectId: undefined as unknown as null })
    // undefined coalesces to '' via ??, null also coalesces to ''
    expect(hash1).toBe(hash2)
  })
})

// ─── Canonical JSON ────────────────────────────────────────────────────

describe('canonical JSON serialization (via hash behavior)', () => {
  it('produces the same hash regardless of payload key insertion order', async () => {
