/**
 * Ownership check helpers — IDOR protection.
 *
 * Shared utilities for verifying that a project belongs to the
 * requesting user. Used by API routes that take a project_id or
 * entity id parameter to prevent IDOR (Insecure Direct Object
 * Reference) attacks.
 *
 * Why this exists
 * ---------------
 * Migration 011 disabled PostgreSQL RLS, so authorization must
 * happen in the application layer. Before this helper, many routes
 * fetched project data by id without checking user_id — any
 * authenticated user could read or modify any other user's projects.
 *
 * Usage
 * -----
 *   import { requireProjectOwnership } from '@/lib/auth/ownership'
 *
 *   export const GET = apiHandler(
 *     { auth: true },
 *     async (req, ctx) => {
 *       const ownership = await requireProjectOwnership(ctx.params.id, ctx.userId)
 *       if (ownership.error) return ownership.error  // 403 or 404
 *       // ... route logic ...
 *     }
 *   )
 */

import { db } from '@/lib/db'
import { NextResponse } from 'next/server'

export interface OwnershipResult {
  /** True if the user owns the project. If false, `error` is set. */
  ok: boolean
  /** Pre-built NextResponse (403 or 404) to return if ok is false. */
  error?: NextResponse
  /** The project's user_id (may be null for legacy projects). */
  projectUserId?: string | null
}

/**
 * Verify that the requesting user owns the project.
 *
 * Returns { ok: true } if the project exists and belongs to the user
 * (or has no user_id — legacy projects are accessible to all).
 * Returns { ok: false, error } with a 404 if the project doesn't exist,
 * or a 403 if it belongs to another user.
 *
 * Callers should return early on error:
 *   const own = await requireProjectOwnership(id, userId)
 *   if (!own.ok) return own.error!
 */
export async function requireProjectOwnership(
  projectId: string,
  userId: string | undefined | null
): Promise<OwnershipResult> {
  const result = await db.query(
    'SELECT user_id FROM projects WHERE id = $1',
    [projectId]
  )

  if (result.rows.length === 0) {
    return {
      ok: false,
      error: NextResponse.json(
        { error: 'Project not found', code: 'NOT_FOUND' },
        { status: 404 }
      ),
    }
  }

  const projectUserId = result.rows[0].user_id as string | null

  // Legacy projects with no user_id are accessible to all authenticated users.
  // (Prevents lockout for data created before user_id was added.)
  if (projectUserId && userId && projectUserId !== userId) {
    return {
      ok: false,
      projectUserId,
      error: NextResponse.json(
        { error: 'Forbidden: project belongs to another user', code: 'FORBIDDEN' },
        { status: 403 }
      ),
    }
  }

  return { ok: true, projectUserId }
}

/**
 * Verify ownership of a survey point by walking up to its project.
 *
 * survey_points → projects (via project_id) → user_id
 *
 * Use this for routes like /api/survey-points/[id] that take a
 * resource id which belongs to a project indirectly.
 */
export async function requireSurveyPointOwnership(
  surveyPointId: string,
  userId: string | undefined | null
): Promise<OwnershipResult> {
  const result = await db.query(
    `SELECT p.user_id
     FROM survey_points sp
     JOIN projects p ON p.id = sp.project_id
     WHERE sp.id = $1`,
    [surveyPointId]
  )

  if (result.rows.length === 0) {
    return {
      ok: false,
      error: NextResponse.json(
        { error: 'Survey point not found', code: 'NOT_FOUND' },
        { status: 404 }
      ),
    }
  }

  const projectUserId = result.rows[0].user_id as string | null

  if (projectUserId && userId && projectUserId !== userId) {
    return {
      ok: false,
      projectUserId,
      error: NextResponse.json(
        { error: 'Forbidden: resource belongs to another user', code: 'FORBIDDEN' },
        { status: 403 }
      ),
    }
  }

  return { ok: true, projectUserId }
}

/**
 * Verify ownership of a versioned entity by walking up to its project.
 *
 * entity_versions → projects (via project_id) → user_id
 *
 * Use this for /api/versions/[id]/* routes.
 */
export async function requireVersionOwnership(
  versionId: string,
  userId: string | undefined | null
): Promise<OwnershipResult> {
  const result = await db.query(
    `SELECT p.user_id
     FROM entity_versions ev
     LEFT JOIN projects p ON p.id = ev.project_id
     WHERE ev.id = $1`,
    [versionId]
  )

  if (result.rows.length === 0) {
    return {
      ok: false,
      error: NextResponse.json(
        { error: 'Version not found', code: 'NOT_FOUND' },
        { status: 404 }
      ),
    }
  }

  const projectUserId = result.rows[0].user_id as string | null

  if (projectUserId && userId && projectUserId !== userId) {
    return {
      ok: false,
      projectUserId,
      error: NextResponse.json(
        { error: 'Forbidden: resource belongs to another user', code: 'FORBIDDEN' },
        { status: 403 }
      ),
    }
  }

  return { ok: true, projectUserId }
}

/**
 * RBAC — Role-Based Access Control for Metardu
 *
 * Hierarchical roles: super_admin > org_admin > project_manager > surveyor > viewer
 * - super_admin: full system access, can manage all organizations and users
 * - org_admin: organization-level management, can manage users within their org
 * - project_manager: can create/edit projects, manage project members
 * - surveyor: create/edit own projects, assigned scheme work
 * - viewer: read-only access to shared projects
 *
 * Backed by PostgreSQL tables:
 * - user_roles: role assignments per user (with organization scope)
 * - resource_permissions: fine-grained resource-level permissions
 */

import { db } from '@/lib/db'
import { NextResponse } from 'next/server'

// ---------------------------------------------------------------------------
// Role types & constants
// ---------------------------------------------------------------------------

export type Role = 'super_admin' | 'org_admin' | 'project_manager' | 'surveyor' | 'viewer'

export const ROLES = {
  SUPER_ADMIN: 'super_admin' as Role,
  ORG_ADMIN: 'org_admin' as Role,
  PROJECT_MANAGER: 'project_manager' as Role,
  SURVEYOR: 'surveyor' as Role,
  VIEWER: 'viewer' as Role,
} as const

/**
 * Role hierarchy — index 0 is the highest privilege.
 * Used by assignRole() to enforce that a caller can only assign
 * roles at or below their own level.
 */
export const ROLE_HIERARCHY: Role[] = [
  ROLES.SUPER_ADMIN,
  ROLES.ORG_ADMIN,
  ROLES.PROJECT_MANAGER,
  ROLES.SURVEYOR,
  ROLES.VIEWER,
]

/** Roles that can create/edit projects */
export const PROJECT_WRITE_ROLES: Role[] = [
  ROLES.SUPER_ADMIN,
  ROLES.ORG_ADMIN,
  ROLES.PROJECT_MANAGER,
  ROLES.SURVEYOR,
]

/** Roles that can approve submissions and manage scheme status */
export const SCHEME_ADMIN_ROLES: Role[] = [ROLES.SUPER_ADMIN, ROLES.ORG_ADMIN]

/** Roles that can manage users and system settings */
export const SYSTEM_ADMIN_ROLES: Role[] = [ROLES.SUPER_ADMIN, ROLES.ORG_ADMIN]

/** Default role for new users */
export const DEFAULT_ROLE: Role = ROLES.SURVEYOR

// ---------------------------------------------------------------------------
// Role-check helpers
// ---------------------------------------------------------------------------

/**
 * Check if a user's role includes any of the allowed roles.
 * Falls back to 'surveyor' if role is not set.
 */
export function hasRole(userRole: string | null | undefined, allowedRoles: Role[]): boolean {
  const role = (userRole || DEFAULT_ROLE) as Role
  return allowedRoles.includes(role)
}

/**
 * Check if user is an admin (super_admin or org_admin). Convenience wrapper.
 */
export function isAdmin(userRole: string | null | undefined): boolean {
  return hasRole(userRole, [ROLES.SUPER_ADMIN, ROLES.ORG_ADMIN])
}

/**
 * Check if user is a super_admin. Convenience wrapper.
 */
export function isSuperAdmin(userRole: string | null | undefined): boolean {
  return hasRole(userRole, [ROLES.SUPER_ADMIN])
}

// ---------------------------------------------------------------------------
// assignRole — Insert a role into the user_roles table
// ---------------------------------------------------------------------------

/**
 * Assign a role to a user by inserting into the `user_roles` table.
 *
 * If an active (non-revoked) role already exists for the same user+org,
 * it is revoked first before the new role is inserted.
 *
 * @param userId    The UUID of the target user
 * @param role      The role to assign
 * @param grantedBy The UUID of the user performing the assignment
 * @param organizationId Optional organization scope (null = platform-wide)
 */
export async function assignRole(
  userId: string,
  role: Role,
  grantedBy: string,
  organizationId?: string | null,
): Promise<void> {
  await db.transaction(async (client) => {
    // Revoke any existing active role for this user+org
    await client.query(
      `UPDATE user_roles
       SET revoked_at = NOW()
       WHERE user_id = $1
         AND (organization_id = $2 OR (organization_id IS NULL AND $2 IS NULL))
         AND revoked_at IS NULL`,
      [userId, organizationId ?? null],
    )

    // Insert the new role
    await client.query(
      `INSERT INTO user_roles (user_id, organization_id, role, granted_by, granted_at)
       VALUES ($1, $2, $3, $4, NOW())`,
      [userId, organizationId ?? null, role, grantedBy],
    )

    // Also update the users table role column for quick lookups
    await client.query(
      `UPDATE users SET role = $1, updated_at = NOW() WHERE id = $2`,
      [role, userId],
    )

    // Also update surveyor_profiles role if exists
    await client.query(
      `UPDATE surveyor_profiles SET role = $1 WHERE user_id = $2`,
      [role, userId],
    )
  })
}

// ---------------------------------------------------------------------------
// requirePermissionAsync — Check resource_permissions table
// ---------------------------------------------------------------------------

interface PermissionCheckResult {
  /** If true, the permission check failed and `response` contains the 403 */
  denied: boolean
  /** The NextResponse to return (403) if denied, or null if allowed */
  response: NextResponse | null
}

/**
 * Check if a user has a specific permission in the `resource_permissions` table.
 *
 * Super_admin and org_admin roles bypass permission checks.
 *
 * Returns an object with `denied: true` and a 403 NextResponse if the
 * user does NOT have the permission, or `denied: false` if allowed.
 *
 * Usage:
 * ```ts
 * const permCheck = await requirePermissionAsync(userId, 'users.invite')
 * if (permCheck.denied) return permCheck.response
 * ```
 */
export async function requirePermissionAsync(
  userId: string,
  permission: string,
  resourceType?: string,
  resourceId?: string,
): Promise<PermissionCheckResult> {
  // First, check the user's role — super_admin and org_admin bypass all checks
  const { rows: roleRows } = await db.query(
    `SELECT role FROM user_roles
     WHERE user_id = $1 AND revoked_at IS NULL
     ORDER BY granted_at DESC
     LIMIT 1`,
    [userId],
  )

  // Also check the users table role as a fallback
  const { rows: userRows } = await db.query(
    `SELECT role FROM users WHERE id = $1`,
    [userId],
  )

  const userRole = (roleRows[0]?.role || userRows[0]?.role || 'surveyor') as Role

  // super_admin and org_admin bypass permission checks
  if (userRole === ROLES.SUPER_ADMIN || userRole === ROLES.ORG_ADMIN) {
    return { denied: false, response: null }
  }

  // Check the resource_permissions table
  const conditions: string[] = [
    'user_id = $1',
    'permission = $2',
    'revoked_at IS NULL',
  ]
  const params: unknown[] = [userId, permission]
  let paramIdx = 3

  if (resourceType) {
    conditions.push(`resource_type = $${paramIdx++}`)
    params.push(resourceType)
  }
  if (resourceId) {
    conditions.push(`resource_id = $${paramIdx++}`)
    params.push(resourceId)
  }

  const { rows } = await db.query(
    `SELECT id FROM resource_permissions WHERE ${conditions.join(' AND ')} LIMIT 1`,
    params,
  )

  if (rows.length > 0) {
    return { denied: false, response: null }
  }

  // Permission denied
  return {
    denied: true,
    response: NextResponse.json(
      { error: `Permission denied: '${permission}' required`, code: 'FORBIDDEN' },
      { status: 403 },
    ),
  }
}

// ─── Organization-level helpers (audit C6 fix, 2026-07-02) ────────────────

/**
 * Get the user's role within a specific organization.
 * Returns the role from `organization_members`, or null if the user is
 * not a member of the org.
 *
 * A user with role 'org_admin' in an org can manage its members and
 * projects. 'project_manager' can create/edit projects. 'surveyor' can
 * read/write project data. 'viewer' is read-only.
 */
export async function getOrgRole(
  userId: string,
  organizationId: string,
): Promise<Role | null> {
  try {
    const { rows } = await db.query(
      `SELECT role FROM organization_members
       WHERE user_id = $1 AND organization_id = $2 AND is_active = TRUE`,
      [userId, organizationId],
    )
    return (rows[0]?.role as Role) ?? null
  } catch {
    // organization_members table may not exist yet (pre-migration 028)
    return null
  }
}

/**
 * Check if a user can access a project — either as the project owner
 * (user_id match) or as a member of the project's organization.
 *
 * Returns the access level: 'owner', 'org_admin', 'project_manager',
 * 'surveyor', 'viewer', or null (no access).
 *
 * Usage:
 * ```ts
 * const access = await canAccessProject(userId, projectId)
 * if (!access) return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
 * if (access === 'viewer' && req.method !== 'GET') {
 *   return NextResponse.json({ error: 'Read-only' }, { status: 403 })
 * }
 * ```
 */
export async function canAccessProject(
  userId: string,
  projectId: string,
): Promise<Role | 'owner' | null> {
  // 1. Check if user is the project owner
  const { rows: projectRows } = await db.query(
    `SELECT user_id, organization_id FROM projects WHERE id = $1`,
    [projectId],
  )
  if (projectRows.length === 0) return null

  const project = projectRows[0]
  if (project.user_id === userId) return 'owner'

  // 2. Check org membership if the project belongs to an org
  if (project.organization_id) {
    const orgRole = await getOrgRole(userId, project.organization_id)
    if (orgRole) return orgRole
  }

  // 3. Check project_members table (legacy per-project membership)
  const { rows: memberRows } = await db.query(
    `SELECT role FROM project_members WHERE user_id = $1 AND project_id = $2`,
    [userId, projectId],
  )
  return (memberRows[0]?.role as Role) ?? null
}

/**
 * Get all organizations the user is a member of.
 * Useful for the org-switcher UI.
 */
export async function getUserOrganizations(userId: string): Promise<
  Array<{
    organization_id: string
    organization_name: string
    organization_slug: string
    role: Role
    is_active: boolean
  }>
> {
  try {
    const { rows } = await db.query(
      `SELECT
         om.organization_id,
         o.name AS organization_name,
         o.slug AS organization_slug,
         om.role,
         om.is_active
       FROM organization_members om
       JOIN organizations o ON o.id = om.organization_id
       WHERE om.user_id = $1 AND om.is_active = TRUE AND o.is_active = TRUE
       ORDER BY om.accepted_at DESC NULLS LAST, om.invited_at DESC`,
      [userId],
    )
    return rows
  } catch {
    // organizations table may not exist yet
    return []
  }
}

/**
 * requireAuth / requireRole — Server-side auth guards for API routes.
 *
 * [!] DEPRECATED: New routes should use `apiHandler()` from '@/lib/apiHandler'
 * instead of calling requireAuth/requireRole directly. apiHandler provides
 * auth, Zod validation, optimistic locking, rate limiting, error handling,
 * and Sentry integration in a single composable wrapper.
 *
 * These functions are kept for backward compatibility with existing routes
 * that haven't been migrated yet.
 *
 * Migration guide:
 *   BEFORE: const { session, error } = await requireAuth()
 *           if (error) return error
 *   AFTER:  export const GET = apiHandler({ auth: true }, async (req, ctx) => { ... })
 */
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { NextResponse } from 'next/server'
import { db, setCurrentUserId } from '@/lib/db'

/**
 * @deprecated Use apiHandler({ auth: true }) instead
 */
export async function requireAuth() {
  try {
    const session = await getServerSession(authOptions)
    if (!session?.user) {
      return {
        session: null,
        error: NextResponse.json(
          { error: 'Authentication required', code: 'UNAUTHORIZED' },
          { status: 401 }
        ),
      }
    }
    // Set the user ID for RLS policies (current_user_id() in PostgreSQL)
    const userId = (session.user as any).id
    if (userId) {
      setCurrentUserId(String(userId))
    }
    return { session, error: null }
  } catch (err) {
    console.error('[requireAuth] Session check failed:', err)
    return {
      session: null,
      error: NextResponse.json(
        { error: 'Authentication check failed', code: 'AUTH_ERROR' },
        { status: 401 }
      ),
    }
  }
}

/**
 * @deprecated Use apiHandler({ auth: true, roles: [...] }) instead
 */
export type UserRole = 'surveyor' | 'admin' | 'enterprise' | 'university' | 'government_auditor'

/**
 * @deprecated Use apiHandler({ auth: true, roles: [...] }) instead
 */
export async function requireRole(allowedRoles: UserRole[], userId: string) {
  // Ensure RLS context is set for this request
  setCurrentUserId(String(userId))

  const { rows } = await db.query(
    'SELECT role, is_suspended FROM surveyor_profiles WHERE user_id = $1',
    [userId]
  )
  
  if (rows.length === 0) {
    return { allowed: false, error: 'Profile not found' }
  }
  
  const profile = rows[0]
  if (profile.is_suspended) {
    return { allowed: false, error: 'Account suspended' }
  }
  if (!allowedRoles.includes(profile.role)) {
    return { allowed: false, error: 'Insufficient permissions' }
  }
  
  return { allowed: true, role: profile.role }
}

/**
 * API Route Caching Layer
 * Cache GET requests automatically
 */

import { NextRequest, NextResponse } from 'next/server'
import redisCache, { RedisCache } from './redis'

interface CacheConfig {
  ttl?: number // seconds
  keyGenerator?: (req: NextRequest) => string
  tags?: string[] // for cache invalidation
}

export function withApiCache(
  handler: (req: NextRequest) => Promise<NextResponse>,
  config: CacheConfig = {}
) {
  const { ttl = 60, keyGenerator, tags = [] } = config

  return async function cachedHandler(req: NextRequest): Promise<NextResponse> {
    // Only cache GET requests
    if (req.method !== 'GET') {
      return handler(req)
    }

    const cacheKey = keyGenerator
      ? keyGenerator(req)
      : `api:${req.nextUrl.pathname}:${req.nextUrl.search}`

    // Try cache
    const cached = await redisCache.get<{ data: any; headers: Record<string, string> }>(cacheKey)
    
    if (cached) {
      return NextResponse.json(cached.data, {
        headers: {
          ...cached.headers,
          'X-Cache': 'HIT',
          'X-Cache-Key': cacheKey,
        },
      })
    }

    // Execute handler
    const response = await handler(req)

    // Cache successful responses
    if (response.status === 200) {
      try {
        const data = await response.json()
        const headers: Record<string, string> = {}
        response.headers.forEach((value, key) => {
          headers[key] = value
        })

        await redisCache.set(cacheKey, { data, headers, tags }, ttl)

        return NextResponse.json(data, {
          headers: {
            ...headers,
            'X-Cache': 'MISS',
            'X-Cache-Key': cacheKey,
          },
        })
      } catch {
        // If we can't cache, just return the response
        return response
      }
    }

    return response
  }
}

// Cache invalidation helpers
export async function invalidateCache(tags: string[]): Promise<void> {
  // In production, use Redis KEYS to find and delete by pattern
  // For now, we'll just delete specific known keys
  for (const tag of tags) {
    await redisCache.delPattern(`*:${tag}:*`)
  }
}

export async function invalidateProjectCache(projectId: string): Promise<void> {
  await redisCache.del(RedisCache.keys.project(projectId))
  await redisCache.del(RedisCache.keys.surveyPoints(projectId))
  await redisCache.del(RedisCache.keys.submissions(projectId))
  await redisCache.delPattern(`count:*"project_id":"${projectId}"*`)
}

// Revalidate tag for Next.js ISR
export async function revalidateTag(tag: string): Promise<void> {
  try {
    await fetch(`/api/revalidate?tag=${tag}`, { method: 'POST' })
  } catch {
    // Ignore errors
  }
}

/**
 * Redis Cache Layer for METARDU
 * Enterprise-grade caching for API responses and session data
 */

import { createClient } from 'redis'

const REDIS_URL = process.env.REDIS_URL || 'redis://localhost:6379'
const IS_NEXT_BUILD = process.env.NEXT_PHASE === 'phase-production-build'

class RedisCache {
  private client: ReturnType<typeof createClient> | null = null
  private isConnected = false
  private connectionAttempted = false
  private disabled = false

  async connect(): Promise<void> {
    if (this.isConnected || this.disabled || IS_NEXT_BUILD) return

    try {
      this.connectionAttempted = true
      this.client = createClient({
        url: REDIS_URL,
        socket: {
          reconnectStrategy: false,
        },
      })
      this.client.on('error', () => {
        this.disabled = true
      })
      await this.client.connect()
      this.isConnected = true
    } catch (error) {
      this.disabled = true
      this.client = null
      if (process.env.NODE_ENV !== 'production') {
        console.warn('[Redis] Cache disabled; Redis is not reachable.')
      }
    }
  }

  async get<T>(key: string): Promise<T | null> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return null

    try {
      const value = await this.client.get(key)
      return value ? JSON.parse(value as string) : null
    } catch {
      return null
    }
  }

  async set<T>(key: string, value: T, ttlSeconds = 300): Promise<void> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return

    try {
      await this.client.setEx(key, ttlSeconds, JSON.stringify(value))
    } catch {
      // Silently fail - app continues working
    }
  }

  async del(key: string): Promise<void> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return

    try {
      await this.client.del(key)
    } catch {
      // Silently fail
    }
  }

  async delPattern(pattern: string): Promise<void> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return

    try {
      // ByteByteGo audit fix: use SCAN instead of KEYS to avoid blocking Redis
      // in production. KEYS * scans the entire keyspace and blocks the event loop.
      // SCAN is non-blocking and returns { cursor, keys } for iteration.
      let cursor = '0'
      do {
        const result = await this.client.scan(cursor, { MATCH: pattern, COUNT: 100 })
        cursor = result.cursor
        const keys = result.keys
        if (keys.length > 0) {
          await this.client.del(keys)
        }
      } while (cursor !== '0')
    } catch {
      // Silently fail
    }
  }

  async getOrSet<T>(key: string, factory: () => Promise<T>, ttlSeconds = 300): Promise<T> {
    const cached = await this.get<T>(key)
    if (cached) return cached

    const value = await factory()
    await this.set(key, value, ttlSeconds)
    return value
  }

  async increment(key: string, amount = 1): Promise<number> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return 0

    try {
      return await this.client.incrBy(key, amount) as number
    } catch {
      return 0
    }
  }

  async expire(key: string, seconds: number): Promise<void> {
    if (!this.connectionAttempted) await this.connect()
    if (!this.isConnected || !this.client) return

    try {
      await this.client.expire(key, seconds)
    } catch {
      // Silently fail
    }
  }

  // Cache keys generators
  static keys = {
    project: (id: string) => `project:${id}`,
    projectList: (userId: string) => `projects:list:${userId}`,
    surveyPoints: (projectId: string) => `survey_points:${projectId}`,
    submissions: (projectId: string) => `submissions:${projectId}`,
    surveyTool: (tool: string, params: string) => `tool:${tool}:${params}`,
    userSession: (sessionId: string) => `session:${sessionId}`,
    rateLimit: (key: string) => `ratelimit:${key}`,
  }
}

// Singleton instance
const redisCache = new RedisCache()
export default redisCache
export { RedisCache }

// Helper for API route caching
export function withCache<T>(
  fn: () => Promise<T>,
  key: string,
  ttlSeconds = 300
): Promise<T> {
  return redisCache.getOrSet(key, fn, ttlSeconds)
}

// Cache middleware for Next.js API routes
export async function cacheMiddleware(
  request: Request,
  cacheKey: string,
  ttlSeconds = 60
): Promise<Response | null> {
  // Only cache GET requests
  if (request.method !== 'GET') return null

  const cached = await redisCache.get<ResponseCache>(cacheKey)
  if (cached) {
    return new Response(JSON.stringify(cached.data), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'X-Cache': 'HIT',
        'X-Cache-TTL': ttlSeconds.toString(),
      },
    })
  }

  return null
}

interface ResponseCache {
  data: any
  timestamp: number
}

