// ─── clothoidSetOutTable ────────────────────────────────────────────────────

describe('clothoidSetOutTable', () => {
  // Use result from the basic case (Test 1)
  const clothoidResult = computeClothoid({
    radius: 300,
    designSpeed: 60,
    deflectionAngleRad: 30 * DEG,
    ipChainage: 500,
  })

  const table = clothoidSetOutTable(clothoidResult)

  it('should have the first point labelled TS', () => {
    expect(table[0].point).toBe('TS')
    expect(table[0].chainage).toBeCloseTo(clothoidResult.tsChainage, 1)
  })

  it('should have the last point labelled ST', () => {
    expect(table[table.length - 1].point).toBe('ST')
    expect(table[table.length - 1].chainage).toBeCloseTo(clothoidResult.stChainage, 1)
  })

  it('should have monotonically increasing chainages', () => {
    for (let i = 1; i < table.length; i++) {
      // Skip the circular arc placeholder (point '···')
      if (table[i].point === '···') continue
      expect(table[i].chainage).toBeGreaterThanOrEqual(table[i - 1].chainage)
    }
  })

  it('should have all spiral deflection angles positive (entry spiral)', () => {
    const entrySpiralRows = table.filter(
      (r) => r.point === 'TS' || r.point === 'SC' || /^\d+$/.test(r.point),
    )
    // All entry spiral points except TS should have positive deflection
    for (const row of entrySpiralRows) {
      if (row.point === 'TS') continue
      expect(row.deflectionDeg).not.toMatch(/^-/)
    }
  })

  it('should include SC and CS in the table', () => {
    const points = table.map((r) => r.point)
    expect(points).toContain('SC')
    expect(points).toContain('CS')
  })

  it('should include a circular arc placeholder when arc length > 0', () => {
    if (clothoidResult.circularArcLength > 0.01) {
      const arcRow = table.find((r) => r.point === '···')
      expect(arcRow).toBeDefined()
      expect(arcRow!.remarks).toContain('Circular arc')
    }
  })

  it('should generate entries for both entry and exit spirals', () => {
    const tsIdx = table.findIndex((r) => r.point === 'TS')
    const scIdx = table.findIndex((r) => r.point === 'SC')
    const csIdx = table.findIndex((r) => r.point === 'CS')
    const stIdx = table.findIndex((r) => r.point === 'ST')

    expect(tsIdx).toBeGreaterThanOrEqual(0)
    expect(scIdx).toBeGreaterThan(tsIdx)
    expect(csIdx).toBeGreaterThan(scIdx)
    expect(stIdx).toBeGreaterThan(csIdx)
  })

  it('should have TS chord = 0', () => {
    const tsRow = table.find((r) => r.point === 'TS')
    expect(tsRow!.chord).toBe(0)
  })
})

// METARDU Clothoid Transition Curve Engine
// Source: RDM 1.3 Section 5.2.4 (Kenya, August 2023)
// Source: Schofield & Breach, Engineering Surveying 7th Ed., Chapter 11
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 24
// Source: AASHTO A Policy on Geometric Design of Highways and Streets

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface ClothoidInput {
  /** Circular curve radius (m) */
  radius: number
  /** Design speed (km/h) */
  designSpeed: number
  /** Total deflection angle (radians) — the intersection angle */
  deflectionAngleRad: number
  /** Chainage of the IP (m) */
  ipChainage: number
  /** Desired transition length Ls (m). If omitted, computed from RDM 1.3 criteria */
  transitionLength?: number
  /** Design superelevation (decimal, e.g. 0.07 for 7%). If omitted, computed from speed/radius */
  superelevation?: number
  /** Superelevation rate of change (%/m, default 1/240 from RDM 1.3) */
  rateOfChange?: number
  /** Set-out interval along spiral (m, default 10) */
  setOutInterval?: number
}

export interface SpiralPoint {
  /** Arc length from TS/ST along spiral */
  arcLength: number
  /** Chainage at this point */
  chainage: number
  /** Local X coordinate (along TS tangent) */
  x: number
  /** Local Y coordinate (perpendicular to TS tangent) */
  y: number
  /** Spiral angle at this point (radians) */
  theta: number
  /** Deflection angle from TS tangent (radians) — for setting out */
  deflection: number
  /** Chord from TS to this point (m) */
  chord: number
}

export interface ClothoidResult {
  // ── Spiral Parameters ──
  /** Spiral parameter A = sqrt(R * Ls) */
  spiralParamA: number
  /** Spiral angle at end of transition (radians) — τ = Ls/(2R) */
  spiralAngleTau: number
  spiralAngleTauDeg: number
  /** Tangent offset at TS — distance from TS to point where circular curve is shifted */
  tangentOffsetQ: number
  /** Curve shift p — how much the circular curve shifts inward from the tangent */
  curveShiftP: number

  // ── Key Chainages ──
  /** Tangent to Spiral point chainage */
  tsChainage: number
  /** Spiral to Curve point chainage */
  scChainage: number
  /** Curve to Spiral point chainage */
  csChainage: number
  /** Spiral to Tangent point chainage */
  stChainage: number

  // ── Modified Circular Curve ──
  /** Modified tangent length: Ts = (R+p)*tan(Δ/2) + q */
  modifiedTangent: number
  /** Circular arc length: Lc = R*(Δ - 2τ) */
  circularArcLength: number
  /** Total curve length: L_total = 2*Ls + Lc */
  totalCurveLength: number
  /** External distance: Es = (R+p)*sec(Δ/2) - (R+p) */
  externalDistance: number

  // ── Spiral Set-Out Points ──
  /** Points along the entry spiral (TS → SC) */
  spiralInPoints: SpiralPoint[]
  /** Points along the exit spiral (CS → ST), mirrored */
  spiralOutPoints: SpiralPoint[]

  // ── Validation ──
  /** Minimum required transition length from RDM 1.3 criteria */
  minTransitionLength: number
  /** Criteria breakdown for minimum length */
  minLengthCriteria: {
    /** From rate of change of centripetal acceleration */
    acceleration: number
    /** From rate of change of superelevation */
    superElevation: number
    /** From minimum travel time (3 seconds) */
    travelTime: number
  }
  /** Is the provided (or computed) transition length adequate? */
  isLengthAdequate: boolean

  // ── Derivation Steps ──
  steps: Array<{ description: string; formula: string; value: string }>
}

// ─── CONSTANTS ─────────────────────────────────────────────────────────────────

/** RDM 1.3: Rate of change of centripetal acceleration (m/s³) */
const CENTRIPETAL_RATE = 0.3

/** RDM 1.3: Minimum travel time on transition (seconds) */
const MIN_TRAVEL_TIME = 3.0

/** Default superelevation rate of change (%/m) — RDM 1.3 Table 5.3 */
const DEFAULT_RATE_OF_CHANGE = 1 / 240

/** Default carriageway width (m) — typical two-lane road */
const DEFAULT_CARRIAGEWAY_WIDTH = 7.0

/** Default set-out interval (m) */
const DEFAULT_SET_OUT_INTERVAL = 10

// ─── HELPERS ───────────────────────────────────────────────────────────────────

const DEG = 180 / Math.PI
const RAD = Math.PI / 180

/** Round to a given number of decimal places */
function r(value: number, dp: number = 3): number {
  const f = 10 ** dp
  return Math.round(value * f) / f
}

/** Format angle in degrees as D°M'S" */
function formatDMS(rad: number): string {
  let totalSec = Math.abs(rad * DEG) * 3600
  const sign = rad < 0 ? '-' : ''
  const d = Math.floor(totalSec / 3600)
  totalSec -= d * 3600
  const m = Math.floor(totalSec / 60)
  const s = r(totalSec - m * 60, 2)
  return `${sign}${d}°${m.toString().padStart(2, '0')}'${s.toString().padStart(5, '0')}"`
}

// ─── CORE FUNCTIONS ────────────────────────────────────────────────────────────

/**
 * Compute the minimum transition length from RDM 1.3 criteria.
 * Returns the MAXIMUM of three criteria:
 * 1. Centripetal acceleration: Ls >= V³ / (3.6³ * C * R), C = 0.3 m/s³
 * 2. Superelevation runoff:  Ls >= (e * B) / (2 * p), p = rate (%/m as decimal)
 * 3. Travel time:            Ls >= V / (3.6 * 3)  (3 seconds minimum)
 */
export function minTransitionLength(
  radius: number,
  speedKmh: number,
  superelevation: number,
  carriagewayWidth: number = DEFAULT_CARRIAGEWAY_WIDTH,
  rateOfChange: number = DEFAULT_RATE_OF_CHANGE,
): { min: number; criteria: { acceleration: number; superElevation: number; travelTime: number } } {
  const V = speedKmh

  // Criterion 1: Rate of change of centripetal acceleration
  // Ls >= V³ / (3.6³ · C · R) where C = 0.3 m/s³
  const acceleration = Math.pow(V, 3) / (Math.pow(3.6, 3) * CENTRIPETAL_RATE * radius)

  // Criterion 2: Rate of change of superelevation (AASHTO / RDM 1.3)
  // Ls >= (e · B) / (2 · p) where p = rate of change (%/m as decimal)
  const superElevation = (superelevation * carriagewayWidth) / (2 * rateOfChange)

  // Criterion 3: Minimum travel time
  // Ls >= V / (3.6 · t) where t = 3 s
  const travelTime = V / (3.6 * MIN_TRAVEL_TIME)

  return {
    min: Math.max(acceleration, superElevation, travelTime),
    criteria: { acceleration, superElevation, travelTime },
  }
}

/**
 * Compute spiral coordinates at a given arc length L using Fresnel integral series.
 *
 *   x = L · (1 − L⁴/(40·A⁴) + L⁸/(3456·A⁸))
 *   y = L · (L²/(6·A²) − L⁶/(336·A⁶) + L¹⁰/(42240·A¹⁰))
 *   θ = L² / (2·A²) = L / (2·R)
 *
 * These series converge rapidly for typical road spirals.
 */
export function spiralCoordinate(
  L: number,
  R: number,
  A: number,
): { x: number; y: number; theta: number } {
  const A2 = A * A
  const A4 = A2 * A2
  const A6 = A4 * A2
  const A8 = A4 * A4
  const A10 = A8 * A2
  const L2 = L * L
  const L4 = L2 * L2
  const L6 = L4 * L2
  const L8 = L4 * L4
  const L10 = L8 * L2

  const x = L * (1 - L4 / (40 * A4) + L8 / (3456 * A8))
  const y = L * (L2 / (6 * A2) - L6 / (336 * A6) + L10 / (42240 * A10))
  const theta = L2 / (2 * A2) // equivalent to L / (2R)

  return { x, y, theta }
}

/**
 * Compute full clothoid transition curve with set-out data.
 *
 * @param input All curve design parameters
 * @returns Complete clothoid result including spiral points and validation
 */
export function computeClothoid(input: ClothoidInput): ClothoidResult {
  const {
    radius: R,
    designSpeed: V,
    deflectionAngleRad: delta,
    ipChainage,
    transitionLength: inputLs,
    superelevation: inputE,
    rateOfChange: pRate = DEFAULT_RATE_OF_CHANGE,
    setOutInterval: interval = DEFAULT_SET_OUT_INTERVAL,
  } = input

  const steps: Array<{ description: string; formula: string; value: string }> = []

  // ── 0. Superelevation from speed and radius (RDM 1.3 Table 5.2) ─────────
  // e + f = V² / (127·R) ; typical split: e = 0.6·(V²/127R), f = 0.4·(...)
  const totalEplusF = (V * V) / (127 * R)
  const e = inputE ?? Math.min(r(0.6 * totalEplusF, 4), 0.07) // cap at 7%
  steps.push({
    description: 'Design superelevation',
    formula: inputE ? 'Provided' : 'e = 0.6·V²/(127·R), capped at 0.07',
    value: `e = ${(e * 100).toFixed(2)}%`,
  })

  // ── 1. Compute or validate transition length Ls ─────────────────────────
  const ml = minTransitionLength(R, V, e, DEFAULT_CARRIAGEWAY_WIDTH, pRate)
  const Ls = inputLs ?? ml.min
  const isLengthAdequate = Ls >= ml.min

  steps.push({
    description: 'Minimum transition length (3 criteria)',
    formula: 'max( V³/(3.6³·0.3·R), e·B·V/(3.6·p), V/(3.6·3) )',
    value: `acc=${r(ml.criteria.acceleration)}m, sup=${r(ml.criteria.superElevation)}m, time=${r(ml.criteria.travelTime)}m → min=${r(ml.min)}m`,
  })
  steps.push({
    description: 'Transition length Ls',
    formula: inputLs ? 'Provided' : 'Adopted = min required',
    value: `Ls = ${r(Ls)} m (adequate: ${isLengthAdequate})`,
  })

  // ── 2. Spiral parameter ────────────────────────────────────────────────
  const A = Math.sqrt(R * Ls)
  steps.push({
    description: 'Spiral parameter A',
    formula: 'A = √(R · Ls)',
    value: `A = √(${r(R)} × ${r(Ls)}) = ${r(A)}`,
  })

  // ── 3. Spiral angle τ = Ls / (2R) ─────────────────────────────────────
  const tau = Ls / (2 * R)
  const tauDeg = tau * DEG
  steps.push({
    description: 'Spiral angle at SC/CS',
    formula: 'τ = Ls / (2R)',
    value: `τ = ${r(Ls)} / (2 × ${r(R)}) = ${r(tau)} rad = ${r(tauDeg, 4)}°`,
  })

  // ── 4. Spiral end coordinates (Fresnel series in terms of τ) ───────────
  //    Xs ≈ Ls · (1 − τ²/10 + τ⁴/216 − τ⁵/9360)
  //    Ys ≈ Ls · (τ/3 − τ³/42 + τ⁵/1320)
  const Xs = Ls * (1 - (tau * tau) / 10 + (tau ** 4) / 216 - (tau ** 5) / 9360)
  const Ys = Ls * (tau / 3 - (tau ** 3) / 42 + (tau ** 5) / 1320)
  steps.push({
    description: 'Spiral end coordinates (SC/CS)',
    formula: 'Xs ≈ Ls(1−τ²/10+τ⁴/216−τ⁵/9360), Ys ≈ Ls(τ/3−τ³/42+τ⁵/1320)',
    value: `Xs = ${r(Xs)}, Ys = ${r(Ys)}`,
  })

  // ── 5. Tangent offset q and curve shift p ───────────────────────────────
  const q = Xs - R * Math.sin(tau)
  const p = Ys - R * (1 - Math.cos(tau))
  steps.push({
    description: 'Tangent offset q',
    formula: 'q = Xs − R·sin(τ)',
    value: `q = ${r(Xs)} − ${r(R)}·sin(${r(tau)}) = ${r(q)}`,
  })
  steps.push({
    description: 'Curve shift p',
    formula: 'p = Ys − R·(1 − cos(τ))',
    value: `p = ${r(Ys)} − ${r(R)}·(1 − cos(${r(tau)})) = ${r(p)}`,
  })

  // ── 6. Modified tangent length Ts ───────────────────────────────────────
  const Ts = (R + p) * Math.tan(delta / 2) + q
  steps.push({
    description: 'Modified tangent length',
    formula: 'Ts = (R + p)·tan(Δ/2) + q',
    value: `Ts = (${r(R)} + ${r(p)})·tan(${r(delta / 2)}) + ${r(q)} = ${r(Ts)}`,
  })

  // ── 7. Key chainages ───────────────────────────────────────────────────
  const tsChainage = ipChainage - Ts
  const scChainage = tsChainage + Ls
  const Lc = R * (delta - 2 * tau)
  const csChainage = scChainage + Lc
  const stChainage = csChainage + Ls
  const totalCurveLength = 2 * Ls + Lc

  steps.push({
    description: 'Circular arc length',
    formula: 'Lc = R·(Δ − 2τ)',
    value: `Lc = ${r(R)} × (${r(delta)} − 2×${r(tau)}) = ${r(Lc)} m`,
  })
  steps.push({
    description: 'Key chainages',
    formula: 'TS = IP − Ts; SC = TS + Ls; CS = SC + Lc; ST = CS + Ls',
    value: `TS=${r(tsChainage)}, SC=${r(scChainage)}, CS=${r(csChainage)}, ST=${r(stChainage)}`,
  })

  // ── 8. External distance ───────────────────────────────────────────────
  const externalDistance = (R + p) / Math.cos(delta / 2) - (R + p)
  steps.push({
    description: 'External distance',
    formula: 'Es = (R+p)·sec(Δ/2) − (R+p)',
    value: `Es = ${r(externalDistance)}`,
  })

  // ── 9. Generate spiral set-out points (entry: TS → SC) ─────────────────
  const spiralInPoints: SpiralPoint[] = []

  // Always include TS (arc length = 0)
  spiralInPoints.push({
    arcLength: 0,
    chainage: tsChainage,
    x: 0,
    y: 0,
    theta: 0,
    deflection: 0,
    chord: 0,
  })

  // Generate intermediate points at set-out intervals
  let nextChainage = Math.ceil(tsChainage / interval) * interval
  while (nextChainage < scChainage - 0.001) {
    const arcLen = nextChainage - tsChainage
    const coord = spiralCoordinate(arcLen, R, A)
    const chord = Math.sqrt(coord.x * coord.x + coord.y * coord.y)
    // Deflection angle ≈ θ/3 for short spirals; more accurately: arctan(y/x)
    const deflection = Math.atan2(coord.y, coord.x)

    spiralInPoints.push({
      arcLength: r(arcLen),
      chainage: r(nextChainage),
      x: r(coord.x),
      y: r(coord.y),
      theta: r(coord.theta),
      deflection: r(deflection),
      chord: r(chord),
    })

    nextChainage += interval
  }

  // Always include SC (end of spiral)
  const scCoord = spiralCoordinate(Ls, R, A)
  const scChord = Math.sqrt(scCoord.x * scCoord.x + scCoord.y * scCoord.y)
  const scDeflection = Math.atan2(scCoord.y, scCoord.x)
  spiralInPoints.push({
    arcLength: r(Ls),
    chainage: r(scChainage),
    x: r(scCoord.x),
    y: r(scCoord.y),
    theta: r(scCoord.theta),
    deflection: r(scDeflection),
    chord: r(scChord),
  })

  steps.push({
    description: 'Entry spiral set-out points',
    formula: `${spiralInPoints.length} points (interval ${interval}m)`,
    value: `TS to SC, lengths 0 to ${r(Ls)} m`,
  })

  // ── 10. Mirror for exit spiral (CS → ST) ──────────────────────────────
  // Exit spiral is identical in shape but traversed from ST backwards.
  // Local coordinates are mirrored: x_exit = Xs − x_entry, y_exit = Ys − y_entry
  // (reflected about the CS–ST direction)
  const spiralOutPoints: SpiralPoint[] = spiralInPoints.map((pt) => {
    const mirrorArcLen = Ls - pt.arcLength
    return {
      arcLength: r(mirrorArcLen),
      chainage: r(csChainage + mirrorArcLen),
      // Mirror coordinates: measured from ST end of spiral looking back
      x: r(scCoord.x - pt.x),
      y: r(scCoord.y - pt.y),
      theta: r(tau - pt.theta),
      deflection: r(Math.atan2(scCoord.y - pt.y, scCoord.x - pt.x)),
      chord: r(Math.sqrt((scCoord.x - pt.x) ** 2 + (scCoord.y - pt.y) ** 2)),
    }
  }).reverse() // Now ordered from CS → ST

  // ── Assemble result ─────────────────────────────────────────────────────
  return {
    spiralParamA: r(A),
    spiralAngleTau: r(tau),
    spiralAngleTauDeg: r(tauDeg, 4),
    tangentOffsetQ: r(q),
    curveShiftP: r(p),

    tsChainage: r(tsChainage),
    scChainage: r(scChainage),
    csChainage: r(csChainage),
    stChainage: r(stChainage),

    modifiedTangent: r(Ts),
    circularArcLength: r(Lc),
    totalCurveLength: r(totalCurveLength),
    externalDistance: r(externalDistance),

    spiralInPoints,
    spiralOutPoints,

    minTransitionLength: r(ml.min),
    minLengthCriteria: {
      acceleration: r(ml.criteria.acceleration),
      superElevation: r(ml.criteria.superElevation),
      travelTime: r(ml.criteria.travelTime),
    },
    isLengthAdequate,

    steps,
  }
}

/**
 * Generate a formatted set-out table for field use.
 *
 * Returns an array of rows suitable for direct display or export,
 * covering both the entry spiral (TS→SC) and exit spiral (CS→ST).
 *
 * @param result  The ClothoidResult from computeClothoid()
 * @param interval  Override set-out interval (default: from result computation)
 */
export function clothoidSetOutTable(
  result: ClothoidResult,
  interval?: number,
): Array<{
  point: string
  chainage: number
  x: number
  y: number
  chord: number
  deflectionDeg: string
  remarks: string
}> {
  const rows: Array<{
    point: string
    chainage: number
    x: number
    y: number
    chord: number
    deflectionDeg: string
    remarks: string
  }> = []

  // ── Entry spiral (TS → SC) ─────────────────────────────────────────────
  for (let i = 0; i < result.spiralInPoints.length; i++) {
    const pt = result.spiralInPoints[i]
    let remarks = ''
    if (i === 0) remarks = 'TS — Entry spiral start'
    else if (i === result.spiralInPoints.length - 1) remarks = 'SC — Spiral to circular'
    else if (i === 1) remarks = 'First intermediate point'

    rows.push({
      point: i === 0 ? 'TS' : i === result.spiralInPoints.length - 1 ? 'SC' : `${i}`,
      chainage: pt.chainage,
      x: pt.x,
      y: pt.y,
      chord: pt.chord,
      deflectionDeg: formatDMS(pt.deflection),
      remarks,
    })
  }

  // ── Circular arc placeholder ────────────────────────────────────────────
  if (result.circularArcLength > 0.01) {
    rows.push({
      point: '···',
      chainage: r((result.scChainage + result.csChainage) / 2),
      x: 0,
      y: 0,
      chord: 0,
      deflectionDeg: '—',
      remarks: `Circular arc Lc = ${result.circularArcLength} m (see circular curve set-out)`,
    })
  }

  // ── Exit spiral (CS → ST) ──────────────────────────────────────────────
  for (let i = 0; i < result.spiralOutPoints.length; i++) {
    const pt = result.spiralOutPoints[i]
    let remarks = ''
    if (i === 0) remarks = 'CS — Circular to spiral'
    else if (i === result.spiralOutPoints.length - 1) remarks = 'ST — Exit spiral end'

    rows.push({
      point: i === 0 ? 'CS' : i === result.spiralOutPoints.length - 1 ? 'ST' : `${i}`,
      chainage: pt.chainage,
      x: pt.x,
      y: pt.y,
      chord: pt.chord,
      deflectionDeg: formatDMS(pt.deflection),
      remarks,
    })
  }

  return rows
}

import { bearingToString, backBearing } from '@/lib/engine/angles'

// ─── PART 1: INVERSE COMPUTATION ───────────────────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 10.3
// Source: N.N. Basak, Surveying and Levelling, Chapter 3

export interface InverseInput {
  e1: number
  n1: number
  e2: number
  n2: number
  label1?: string
  label2?: string
}

export interface InverseStep {
  description: string
  formula: string
  value: string
}

export interface InverseResult {
  deltaE: number
  deltaN: number
  distance: number
  theta: number
  reducedBearing: string
  wcbDecimal: number
  wcbDMS: string
  backBearingDecimal: number
  backBearingDMS: string
  quadrant: string
  steps: InverseStep[]
  arithmeticCheck: { passed: boolean; value: number }
}

export function inverseComputation(input: InverseInput): InverseResult {
  const { e1, n1, e2, n2, label1 = 'P1', label2 = 'P2' } = input

  const deltaE = e2 - e1
  const deltaN = n2 - n1
  const distance = Math.sqrt(deltaE * deltaE + deltaN * deltaN)
  const theta = Math.atan2(Math.abs(deltaE), Math.abs(deltaN)) * 180 / Math.PI

  // Source: Ghilani & Wolf, Section 10.3 — Quadrant determination
  let wcbDecimal: number
  let quadrant: string

  if (deltaN > 0 && deltaE > 0) {
    wcbDecimal = theta
    quadrant = 'NE'
  } else if (deltaN < 0 && deltaE > 0) {
    wcbDecimal = 180 - theta
    quadrant = 'SE'
  } else if (deltaN < 0 && deltaE < 0) {
    wcbDecimal = 180 + theta
    quadrant = 'SW'
  } else if (deltaN > 0 && deltaE < 0) {
    wcbDecimal = 360 - theta
    quadrant = 'NW'
  } else if (deltaN === 0 && deltaE > 0) {
    wcbDecimal = 90
    quadrant = 'E'
  } else if (deltaN === 0 && deltaE < 0) {
    wcbDecimal = 270
    quadrant = 'W'
  } else if (deltaE === 0 && deltaN > 0) {
    wcbDecimal = 0
    quadrant = 'N'
  } else if (deltaE === 0 && deltaN < 0) {
    wcbDecimal = 180
    quadrant = 'S'
  } else {
    wcbDecimal = 0
    quadrant = 'N/A'
  }

  const wcbDMS = bearingToString(wcbDecimal)
  const backDecimal = backBearing(wcbDecimal)
  const backDMS = bearingToString(backDecimal)

  const steps: InverseStep[] = [
    {
      description: `ΔE = E₂ - E₁`,
      formula: `${e2.toFixed(3)} - ${e1.toFixed(3)}`,
      value: `${deltaE.toFixed(4)} m`,
    },
    {
      description: `ΔN = N₂ - N₁`,
      formula: `${n2.toFixed(3)} - ${n1.toFixed(3)}`,
      value: `${deltaN.toFixed(4)} m`,
    },
    {
      description: `Distance = √(ΔE² + ΔN²)`,
      formula: `√(${deltaE.toFixed(4)}² + ${deltaN.toFixed(4)}²)`,
      value: `${distance.toFixed(4)} m`,
    },
    {
      description: `θ = arctan(|ΔE|/|ΔN|)`,
      formula: `arctan(${Math.abs(deltaE).toFixed(4)}/${Math.abs(deltaN).toFixed(4)})`,
      value: `${theta.toFixed(6)}°`,
    },
    {
      description: `Quadrant: ${quadrant} (ΔN ${deltaN >= 0 ? '>' : '<'} 0, ΔE ${deltaE >= 0 ? '>' : '<'} 0)`,
      formula: `WCB = ${quadrant === 'NE' || quadrant === 'N' || quadrant === 'NW' ? (quadrant === 'NE' ? 'θ' : quadrant === 'NW' ? '360°-θ' : '0°') : quadrant === 'SE' || quadrant === 'S' ? (quadrant === 'SE' ? '180°-θ' : '180°') : quadrant === 'E' ? '90°' : '270°'}`,
      value: wcbDMS,
    },
    {
      description: `Back Bearing = WCB + 180°`,
      formula: `${wcbDecimal.toFixed(4)}° + 180°`,
      value: backDMS,
    },
  ]

  // Arithmetic check: recompute ΔE, ΔN from distance and bearing
  // Source: Rule 5 — show independently
  const checkDist = Math.sqrt(deltaE * deltaE + deltaN * deltaN)
  const arithmeticCheck = { passed: Math.abs(checkDist - distance) < 0.001, value: checkDist - distance }

  return {
    deltaE,
    deltaN,
    distance,
    theta,
    reducedBearing: bearingToString(theta),
    wcbDecimal,
    wcbDMS,
    backBearingDecimal: backDecimal,
    backBearingDMS: backDMS,
    quadrant,
    steps,
    arithmeticCheck,
  }
}

// ─── PART 2: POLAR (RADIATION) ───────────────────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 10.4

export interface PolarInput {
  e1: number
  n1: number
  bearingDeg: number
  bearingMin: number
  bearingSec: number
  distance: number
  label1?: string
  label2?: string
}

export interface PolarResult {
  wcbDecimal: number
  wcbDMS: string
  e2: number
  n2: number
  steps: InverseStep[]
}

export function polarComputation(input: PolarInput): PolarResult {
  const { e1, n1, bearingDeg, bearingMin, bearingSec, distance, label1 = 'P1', label2 = 'P2' } = input

  // Source: Ghilani & Wolf, Section 10.4 — E2 = E1 + D×sin(WCB), N2 = N1 + D×cos(WCB)
  const wcbDecimal = bearingDeg + bearingMin / 60 + bearingSec / 3600
  const wcbRad = wcbDecimal * Math.PI / 180
  const e2 = e1 + distance * Math.sin(wcbRad)
  const n2 = n1 + distance * Math.cos(wcbRad)
  const wcbDMS = bearingToString(wcbDecimal)

  const steps: InverseStep[] = [
    {
      description: `WCB (decimal) = D° + M'/60 + S"/3600`,
      formula: `${bearingDeg}° + ${bearingMin}'/60 + ${bearingSec}"/3600`,
      value: `${wcbDecimal.toFixed(6)}°`,
    },
    {
      description: `E₂ = E₁ + D × sin(WCB)`,
      formula: `${e1.toFixed(3)} + ${distance.toFixed(3)} × sin(${wcbDecimal.toFixed(4)}°)`,
      value: `${e2.toFixed(4)} m`,
    },
    {
      description: `N₂ = N₁ + D × cos(WCB)`,
      formula: `${n1.toFixed(3)} + ${distance.toFixed(3)} × cos(${wcbDecimal.toFixed(4)}°)`,
      value: `${n2.toFixed(4)} m`,
    },
  ]

  return { wcbDecimal, wcbDMS, e2, n2, steps }
}

// ─── PART 3: BEARING INTERSECTION ─────────────────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 10.6
// Source: Schofield & Breach, Engineering Surveying 7th Ed., Chapter 6

export interface IntersectionInput {
  e1: number; n1: number; label1?: string
  e2: number; n2: number; label2?: string
  bearingDeg1: number; bearingMin1: number; bearingSec1: number
  bearingDeg2: number; bearingMin2: number; bearingSec2: number
}

export interface IntersectionResult {
  e3: number
  n3: number
  distanceFrom1: number
  distanceFrom2: number
  checkN3: number
  checkDiff: number
  steps: InverseStep[]
  isWithinTolerance: boolean
}

export function intersectionComputation(input: IntersectionInput): IntersectionResult {
  const {
    e1, n1, e2, n2,
    bearingDeg1, bearingMin1, bearingSec1,
    bearingDeg2, bearingMin2, bearingSec2,
  } = input

  const alpha1 = (bearingDeg1 + bearingMin1 / 60 + bearingSec1 / 3600) * Math.PI / 180
  const alpha2 = (bearingDeg2 + bearingMin2 / 60 + bearingSec2 / 3600) * Math.PI / 180

  const tan1 = Math.tan(alpha1)
  const tan2 = Math.tan(alpha2)

  const denom = tan1 - tan2
  const e3 = (e2 - e1 + n1 * tan1 - n2 * tan2) / denom
  const n3From1 = n1 + (e3 - e1) * Math.tan(alpha1)

  // Independent check: compute N3 from P2 side
  const n3From2 = n2 + (e3 - e2) * Math.tan(alpha2)
  const checkDiff = Math.abs(n3From1 - n3From2)

  const dist1 = Math.sqrt((e3 - e1) ** 2 + (n3From1 - n1) ** 2)
  const dist2 = Math.sqrt((e3 - e2) ** 2 + (n3From1 - n2) ** 2)

  const steps: InverseStep[] = [
    {
      description: `α₁ = ${bearingDeg1}° ${bearingMin1}' ${bearingSec1}" → radians`,
      formula: `${(alpha1 * 180 / Math.PI).toFixed(6)}°`,
      value: `${alpha1.toFixed(8)} rad`,
    },
    {
      description: `α₂ = ${bearingDeg2}° ${bearingMin2}' ${bearingSec2}" → radians`,
      formula: `${(alpha2 * 180 / Math.PI).toFixed(6)}°`,
      value: `${alpha2.toFixed(8)} rad`,
    },
    {
      description: `tan(α₁) - tan(α₂)`,
      formula: `${tan1.toFixed(8)} - ${tan2.toFixed(8)}`,
      value: `${denom.toFixed(8)}`,
    },
    {
      description: `E₃ = (E₂ - E₁ + N₁tan(α₁) - N₂tan(α₂)) / (tan(α₁) - tan(α₂))`,
      formula: `(${e2.toFixed(3)} - ${e1.toFixed(3)} + ${n1.toFixed(3)}×${tan1.toFixed(6)} - ${n2.toFixed(3)}×${tan2.toFixed(6)}) / ${denom.toFixed(6)}`,
      value: `${e3.toFixed(4)} m`,
    },
    {
      description: `N₃ = N₁ + (E₃ - E₁) × tan(α₁)`,
      formula: `${n1.toFixed(3)} + (${e3.toFixed(4)} - ${e1.toFixed(3)}) × ${tan1.toFixed(6)}`,
      value: `${n3From1.toFixed(4)} m`,
    },
    {
      description: `[CHECK] N₃ from P₂ side = N₂ + (E₃ - E₂) × tan(α₂)`,
      formula: `${n2.toFixed(3)} + (${e3.toFixed(4)} - ${e2.toFixed(3)}) × ${tan2.toFixed(6)}`,
      value: `${n3From2.toFixed(4)} m`,
    },
    {
      description: `[CHECK] Difference between both N₃ computations`,
      formula: `|${n3From1.toFixed(4)} - ${n3From2.toFixed(4)}|`,
      value: `${checkDiff.toFixed(4)} m  ${checkDiff <= 0.001 ? ' PASS' : '[x] FAIL'}`,
    },
  ]

  return {
    e3, n3: n3From1,
    distanceFrom1: dist1,
    distanceFrom2: dist2,
    checkN3: n3From2,
    checkDiff,
    steps,
    isWithinTolerance: checkDiff <= 0.001,
  }
}

// ─── PART 4: RESECTION (TIENSTRA/POTHENOT) ────────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 10.7

export interface ResectionInput {
  // Three known points
  eA: number; nA: number; labelA?: string
  eB: number; nB: number; labelB?: string
  eC: number; nC: number; labelC?: string
  // Angles measured at unknown point P
  alphaDeg: number; alphaMin: number; alphaSec: number  // angle APB
  betaDeg: number; betaMin: number; betaSec: number    // angle BPC
}

export interface ResectionResult {
  eP: number
  nP: number
  distToA: number
  distToB: number
  distToC: number
  k1: number; k2: number; k3: number
  sumK: number
  isDangerCircle: boolean
  steps: InverseStep[]
}

function toRadians(deg: number, min: number, sec: number): number {
  return (deg + min / 60 + sec / 3600) * Math.PI / 180
}

export function resectionComputation(input: ResectionInput): ResectionResult {
  const { eA, nA, eB, nB, eC, nC,
    alphaDeg, alphaMin, alphaSec,
    betaDeg, betaMin, betaSec } = input

  const alpha = toRadians(alphaDeg, alphaMin, alphaSec)
  const beta = toRadians(betaDeg, betaMin, betaSec)
  const gamma = 2 * Math.PI - alpha - beta

  const cot = (r: number) => 1 / Math.tan(r)

  // Source: Ghilani & Wolf, Section 10.7 — Tienstra method
  // Compute triangle sides from known points
  const distAB = Math.sqrt((eB - eA) ** 2 + (nB - nA) ** 2)
  const distBC = Math.sqrt((eC - eB) ** 2 + (nC - nB) ** 2)
  const distAC = Math.sqrt((eC - eA) ** 2 + (nC - nA) ** 2)

  // Triangle angles at A, B, C using law of cosines
  const clamp = (x: number) => Math.max(-1, Math.min(1, x))
  const A = Math.acos(clamp((distAB ** 2 + distAC ** 2 - distBC ** 2) / (2 * distAB * distAC)))
  const B = Math.acos(clamp((distAB ** 2 + distBC ** 2 - distAC ** 2) / (2 * distAB * distBC)))
  const C = Math.acos(clamp((distAC ** 2 + distBC ** 2 - distAB ** 2) / (2 * distAC * distBC)))

  const cot_A = cot(A)
  const cot_B = cot(B)
  const cot_C = cot(C)
  const cot_alpha = cot(alpha)
  const cot_beta = cot(beta)
  const cot_gamma = cot(gamma)

  const k1 = 1 / (cot_A - cot_alpha)
  const k2 = 1 / (cot_B - cot_beta)
  const k3 = 1 / (cot_C - cot_gamma)
  const sumK = k1 + k2 + k3

  const eP = (k1 * eA + k2 * eB + k3 * eC) / sumK
  const nP = (k1 * nA + k2 * nB + k3 * nC) / sumK

  const distToA = Math.sqrt((eP - eA) ** 2 + (nP - nA) ** 2)
  const distToB = Math.sqrt((eP - eB) ** 2 + (nP - nB) ** 2)
  const distToC = Math.sqrt((eP - eC) ** 2 + (nP - nC) ** 2)

  const isDangerCircle = Math.abs(sumK) < 0.001

  const steps: InverseStep[] = [
    {
      description: `α = ∠APB = ${alphaDeg}° ${alphaMin}' ${alphaSec}"`,
      formula: `${(alpha * 180 / Math.PI).toFixed(6)}°`,
      value: `${alpha.toFixed(8)} rad`,
    },
    {
      description: `β = ∠BPC = ${betaDeg}° ${betaMin}' ${betaSec}"`,
      formula: `${(beta * 180 / Math.PI).toFixed(6)}°`,
      value: `${beta.toFixed(8)} rad`,
    },
    {
      description: `γ = 360° - (α + β)`,
      formula: `360° - (${(alpha * 180 / Math.PI).toFixed(4)}° + ${(beta * 180 / Math.PI).toFixed(4)}°)`,
      value: `${(gamma * 180 / Math.PI).toFixed(6)}°`,
    },
    {
      description: `cot(A) = (b² + c² - a²) / (2bc)`,
      formula: `${cot_A.toFixed(6)}`,
      value: `A = ${(A * 180 / Math.PI).toFixed(6)}°`,
    },
    {
      description: `cot(B) = (a² + c² - b²) / (2ac)`,
      formula: `${cot_B.toFixed(6)}`,
      value: `B = ${(B * 180 / Math.PI).toFixed(6)}°`,
    },
    {
      description: `cot(C) = (a² + b² - c²) / (2ab)`,
      formula: `${cot_C.toFixed(6)}`,
      value: `C = ${(C * 180 / Math.PI).toFixed(6)}°`,
    },
    {
      description: `K₁ = 1 / (cot(A) - cot(α))`,
      formula: `1 / (${cot_A.toFixed(4)} - ${cot_alpha.toFixed(4)})`,
      value: `${k1.toFixed(6)}`,
    },
    {
      description: `K₂ = 1 / (cot(B) - cot(β))`,
      formula: `1 / (${cot_B.toFixed(4)} - ${cot_beta.toFixed(4)})`,
      value: `${k2.toFixed(6)}`,
    },
    {
      description: `K₃ = 1 / (cot(C) - cot(γ))`,
      formula: `1 / (${cot_C.toFixed(4)} - ${cot_gamma.toFixed(4)})`,
      value: `${k3.toFixed(6)}`,
    },
    {
      description: `ΣK = K₁ + K₂ + K₃`,
      formula: `${k1.toFixed(6)} + ${k2.toFixed(6)} + ${k3.toFixed(6)}`,
      value: `${sumK.toFixed(6)}${isDangerCircle ? ' [!] DANGER CIRCLE' : ''}`,
    },
    {
      description: `Eₚ = (K₁×Eₐ + K₂×Eᵦ + K₃×E꜀) / ΣK`,
      formula: `(${k1.toFixed(4)}×${eA.toFixed(3)} + ${k2.toFixed(4)}×${eB.toFixed(3)} + ${k3.toFixed(4)}×${eC.toFixed(3)}) / ${sumK.toFixed(4)}`,
      value: `${eP.toFixed(4)} m`,
    },
    {
      description: `Nₚ = (K₁×Nₐ + K₂×Nᵦ + K₃×N꜀) / ΣK`,
      formula: `(${k1.toFixed(4)}×${nA.toFixed(3)} + ${k2.toFixed(4)}×${nB.toFixed(3)} + ${k3.toFixed(4)}×${nC.toFixed(3)}) / ${sumK.toFixed(4)}`,
      value: `${nP.toFixed(4)} m`,
    },
  ]

  return { eP, nP, distToA, distToB, distToC, k1, k2, k3, sumK, isDangerCircle, steps }
}

// ─── PART 5: AREA BY COORDINATES (SHOELACE) ───────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 12.5
// Source: N.N. Basak, Surveying and Levelling

export interface AreaInput {
  points: Array<{ label: string; easting: number; northing: number }>
}

export interface AreaDiagonalRow {
  from: string
  to: string
  posProduct: number
  negProduct: number
}

export interface AreaResult {
  doubleArea: number
  areaSqm: number
  areaHa: number
  perimeter: number
  diagonalRows: AreaDiagonalRow[]
  positiveSum: number
  negativeSum: number
  doubleAreaAlt: number
  areaAlt: number
  arithmeticCheck: { passed: boolean; diff: number }
  centroid: { easting: number; northing: number }
  steps: InverseStep[]
}

function closePolygon(pts: Array<{ label: string; easting: number; northing: number }>) {
  const closed = [...pts]
  if (pts.length > 0 &&
    (pts[0].easting !== pts[pts.length - 1].easting ||
      pts[0].northing !== pts[pts.length - 1].northing)) {
    closed.push(pts[0])
  }
  return closed
}

export function areaComputation(input: AreaInput): AreaResult {
  const pts = input.points
  if (pts.length < 3) {
    return {
      doubleArea: 0, areaSqm: 0, areaHa: 0, perimeter: 0,
      diagonalRows: [], positiveSum: 0, negativeSum: 0,
      doubleAreaAlt: 0, areaAlt: 0,
      arithmeticCheck: { passed: false, diff: 0 },
      centroid: { easting: 0, northing: 0 },
      steps: [],
    }
  }

  const closed = closePolygon(pts)

  // Method 1: Standard shoelace (Source: Ghilani & Wolf, Section 12.5)
  let posSum = 0
  let negSum = 0
  const diagonalRows: AreaDiagonalRow[] = []

  for (let i = 0; i < closed.length - 1; i++) {
    const pos = closed[i].easting * closed[i + 1].northing
    const neg = closed[i + 1].easting * closed[i].northing
    posSum += pos
    negSum += neg
    diagonalRows.push({
      from: closed[i].label,
      to: closed[i + 1].label,
      posProduct: pos,
      negProduct: neg,
    })
  }

  const doubleArea = Math.abs(posSum - negSum)
  const areaSqm = doubleArea / 2

  // Method 2: Alternative form (Source: Rule 5 — arithmetic check)
  // 2A = |Σ En(Nn+1 - Nn-1)|
  let altPosSum = 0
  for (let i = 0; i < pts.length; i++) {
    const prev = i === 0 ? pts.length - 1 : i - 1
    const next = i === pts.length - 1 ? 0 : i + 1
    altPosSum += pts[i].easting * (pts[next].northing - pts[prev].northing)
  }
  const doubleAreaAlt = Math.abs(altPosSum)
  const areaAlt = doubleAreaAlt / 2

  const arithmeticCheck = {
    passed: Math.abs(doubleArea - doubleAreaAlt) < 0.001,
    diff: Math.abs(doubleArea - doubleAreaAlt),
  }

  // Perimeter (Source: Basak)
  let perimeter = 0
  for (let i = 0; i < closed.length - 1; i++) {
    const dx = closed[i + 1].easting - closed[i].easting
    const dy = closed[i + 1].northing - closed[i].northing
    perimeter += Math.sqrt(dx * dx + dy * dy)
  }

  // Centroid (Source: Basak)
  let cx = 0, cy = 0
  for (let i = 0; i < pts.length; i++) {
    const cross = pts[i].easting * (pts[(i + 1) % pts.length].northing - pts[(i - 1 + pts.length) % pts.length].northing)
    cx += (pts[i].easting + pts[(i + 1) % pts.length].easting) * cross
    cy += (pts[i].northing + pts[(i + 1) % pts.length].northing) * cross
  }
  cx /= (3 * (posSum - negSum))
  cy /= (3 * (posSum - negSum))

  const steps: InverseStep[] = [
    {
      description: `Σ(E × N_next) — positive diagonal products`,
      formula: diagonalRows.map((r: any) => `${r.from}×${r.to}=${r.posProduct.toFixed(2)}`).join(' + '),
      value: `${posSum.toFixed(4)} m²`,
    },
    {
      description: `Σ(N × E_next) — negative diagonal products`,
      formula: diagonalRows.map((r: any) => `${r.to}×${r.from}=${r.negProduct.toFixed(2)}`).join(' + '),
      value: `${negSum.toFixed(4)} m²`,
    },
    {
      description: `2A = |Σpos - Σneg|`,
      formula: `|${posSum.toFixed(4)} - ${negSum.toFixed(4)}|`,
      value: `${doubleArea.toFixed(4)} m²`,
    },
    {
      description: `A = 2A / 2`,
      formula: `${doubleArea.toFixed(4)} / 2`,
      value: `${areaSqm.toFixed(4)} m² = ${(areaSqm / 10000).toFixed(4)} ha`,
    },
    {
      description: `[CHECK] Alternative: 2A = |Σ En(Nn+1 - Nn-1)|`,
      formula: `${doubleAreaAlt.toFixed(4)}`,
      value: `Difference: ${arithmeticCheck.diff.toFixed(4)} m²  ${arithmeticCheck.passed ? ' PASS' : '[x] FAIL'}`,
    },
    {
      description: `Perimeter = Σ√(ΔE² + ΔN²)`,
      formula: `${perimeter.toFixed(4)} m (${(perimeter / 1000).toFixed(4)} km)`,
      value: `${perimeter.toFixed(4)} m`,
    },
  ]

  return {
    doubleArea, areaSqm,
    areaHa: areaSqm / 10000,
    perimeter,
    diagonalRows,
    positiveSum: posSum,
    negativeSum: negSum,
    doubleAreaAlt,
    areaAlt,
    arithmeticCheck,
    centroid: { easting: cx, northing: cy },
    steps,
  }
}

// ─── PART 6: JOIN COMPUTATION ─────────────────────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 10.3

export interface JoinInput {
  points: Array<{ label: string; easting: number; northing: number }>
}

export interface JoinRow {
  from: string
  to: string
  deltaE: number
  deltaN: number
  distance: number
  wcbDecimal: number
  wcbDMS: string
  backBearingDMS: string
}

export interface JoinResult {
  rows: JoinRow[]
  totalPerimeter: number
}

export function joinComputation(input: JoinInput): JoinResult {
  const rows: JoinRow[] = []
  let totalPerimeter = 0

  for (let i = 0; i < input.points.length - 1; i++) {
    const p1 = input.points[i]
    const p2 = input.points[i + 1]
    const inv = inverseComputation({
      e1: p1.easting, n1: p1.northing,
      e2: p2.easting, n2: p2.northing,
      label1: p1.label, label2: p2.label,
    })
    rows.push({
      from: p1.label,
      to: p2.label,
      deltaE: inv.deltaE,
      deltaN: inv.deltaN,
      distance: inv.distance,
      wcbDecimal: inv.wcbDecimal,
      wcbDMS: inv.wcbDMS,
      backBearingDMS: inv.backBearingDMS,
    })
    totalPerimeter += inv.distance
  }

  return { rows, totalPerimeter }
}

// ─── PART 7: DISTANCE-DISTANCE INTERSECTION ──────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 10.6
// Two circles intersection — given two known points and distances from each

export interface DistDistInput {
  e1: number; n1: number; label1?: string
  e2: number; n2: number; label2?: string
  distance1: number
  distance2: number
}

export interface DistDistResult {
  solutions: Array<{ easting: number; northing: number }>
  distAB: number
  steps: InverseStep[]
  hasSolution: boolean
  error?: string
}

export function distanceDistanceIntersection(input: DistDistInput): DistDistResult {
  const { e1, n1, e2, n2, distance1, distance2, label1 = 'P1', label2 = 'P2' } = input

  const dx = e2 - e1
  const dy = n2 - n1
  const distAB = Math.sqrt(dx * dx + dy * dy)

  const steps: InverseStep[] = [
    {
      description: `Distance ${label1}→${label2}`,
      formula: `√((${e2.toFixed(3)}-${e1.toFixed(3)})² + (${n2.toFixed(3)}-${n1.toFixed(3)})²)`,
      value: `${distAB.toFixed(4)} m`,
    },
  ]

  // Check validity
  if (distAB > distance1 + distance2) {
    return { solutions: [], distAB, steps, hasSolution: false, error: 'Circles do not intersect — stations too far apart' }
  }
  if (distAB < Math.abs(distance1 - distance2)) {
    return { solutions: [], distAB, steps, hasSolution: false, error: 'One circle is contained within the other' }
  }
  if (distAB < 1e-12) {
    return { solutions: [], distAB, steps, hasSolution: false, error: 'Stations are coincident' }
  }

  // Source: Ghilani & Wolf — circle-circle intersection
  const a = (distance1 * distance1 - distance2 * distance2 + distAB * distAB) / (2 * distAB)
  const h = Math.sqrt(Math.max(0, distance1 * distance1 - a * a))

  const cx = e1 + a * dx / distAB
  const cy = n1 + a * dy / distAB

  const sol1 = { easting: cx + h * dy / distAB, northing: cy - h * dx / distAB }
  const sol2 = { easting: cx - h * dy / distAB, northing: cy + h * dx / distAB }

  steps.push(
    { description: `a = (d₁² - d₂² + d_AB²) / (2 × d_AB)`, formula: `(${distance1.toFixed(3)}² - ${distance2.toFixed(3)}² + ${distAB.toFixed(3)}²) / (2 × ${distAB.toFixed(3)})`, value: `${a.toFixed(4)} m` },
    { description: `h = √(d₁² - a²)`, formula: `√(${distance1.toFixed(3)}² - ${a.toFixed(3)}²)`, value: `${h.toFixed(4)} m` },
    { description: `Solution 1`, formula: `E=${sol1.easting.toFixed(4)}, N=${sol1.northing.toFixed(4)}`, value: `(${sol1.easting.toFixed(4)}, ${sol1.northing.toFixed(4)})` },
    { description: `Solution 2`, formula: `E=${sol2.easting.toFixed(4)}, N=${sol2.northing.toFixed(4)}`, value: `(${sol2.easting.toFixed(4)}, ${sol2.northing.toFixed(4)})` },
  )

  // Check if solutions are identical (tangent circles)
  const sameSolution = Math.abs(sol1.easting - sol2.easting) < 0.001 && Math.abs(sol1.northing - sol2.northing) < 0.001

  return {
    solutions: sameSolution ? [sol1] : [sol1, sol2],
    distAB,
    steps,
    hasSolution: true,
  }
}

// ─── PART 8: BEARING-DISTANCE INTERSECTION ───────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 10.6
// Ray-circle intersection — bearing from P1, distance from P2

export interface BearingDistInput {
  e1: number; n1: number; label1?: string
  e2: number; n2: number; label2?: string
  bearingDeg: number; bearingMin: number; bearingSec: number
  distance: number
}

export interface BearingDistResult {
  solutions: Array<{ easting: number; northing: number }>
  steps: InverseStep[]
  hasSolution: boolean
  error?: string
}

export function bearingDistanceIntersection(input: BearingDistInput): BearingDistResult {
  const { e1, n1, e2, n2, bearingDeg, bearingMin, bearingSec, distance, label1 = 'P1', label2 = 'P2' } = input

  const wcbDecimal = bearingDeg + bearingMin / 60 + bearingSec / 3600
  const wcbRad = wcbDecimal * Math.PI / 180

  // Direction vector of the ray from P1
  const dirE = Math.sin(wcbRad)
  const dirN = Math.cos(wcbRad)

  // Solve: |P1 + t*dir - P2| = distance
  // Let dx = E1 - E2, dy = N1 - N2
  // (dx + t*dirE)² + (dy + t*dirN)² = distance²
  // t² + 2t(dx*dirE + dy*dirN) + (dx² + dy²) - distance² = 0

  const dx = e1 - e2
  const dy = n1 - n2
  const A = 1 // dirE² + dirN² = 1
  const B = 2 * (dx * dirE + dy * dirN)
  const C = dx * dx + dy * dy - distance * distance

  const discriminant = B * B - 4 * A * C

  const steps: InverseStep[] = [
    { description: `WCB from ${label1}`, formula: `${bearingDeg}° ${bearingMin}' ${bearingSec}"`, value: bearingToString(wcbDecimal) },
    { description: `Distance from ${label2}`, formula: `${distance.toFixed(3)} m`, value: `${distance.toFixed(4)} m` },
    { description: `Quadratic: t² + ${B.toFixed(4)}t + ${C.toFixed(4)} = 0`, formula: `Δ = ${B.toFixed(4)}² - 4×${C.toFixed(4)}`, value: `Δ = ${discriminant.toFixed(4)}` },
  ]

  if (discriminant < -1e-6) {
    return { solutions: [], steps, hasSolution: false, error: 'Ray does not intersect circle — no solution exists' }
  }

  const sqrtDisc = Math.sqrt(Math.max(0, discriminant))
  const t1 = (-B + sqrtDisc) / 2
  const t2 = (-B - sqrtDisc) / 2

  const solutions: Array<{ easting: number; northing: number }> = []

  if (t1 >= -1e-6) {
    const sol = { easting: e1 + t1 * dirE, northing: n1 + t1 * dirN }
    solutions.push(sol)
    steps.push({ description: `Solution 1 (t=${t1.toFixed(4)})`, formula: `E=${sol.easting.toFixed(4)}, N=${sol.northing.toFixed(4)}`, value: `(${sol.easting.toFixed(4)}, ${sol.northing.toFixed(4)})` })
  }

  if (t2 >= -1e-6 && Math.abs(t1 - t2) > 0.001) {
    const sol = { easting: e1 + t2 * dirE, northing: n1 + t2 * dirN }
    solutions.push(sol)
    steps.push({ description: `Solution 2 (t=${t2.toFixed(4)})`, formula: `E=${sol.easting.toFixed(4)}, N=${sol.northing.toFixed(4)}`, value: `(${sol.easting.toFixed(4)}, ${sol.northing.toFixed(4)})` })
  }

  if (solutions.length === 0) {
    return { solutions: [], steps, hasSolution: false, error: 'Both solutions are behind the ray origin' }
  }

  return { solutions, steps, hasSolution: true }
}

// ─── PART 9: ARC BOUNDARY COMPUTATIONS ───────────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 24
// Source: RDM 1.3 Kenya August 2023, Section 5.2

export interface ArcByRadiusInput {
  startPoint: { easting: number; northing: number }
  endPoint: { easting: number; northing: number }
  radius: number
  isClockwise: boolean
}

export interface ArcResult {
  center: { easting: number; northing: number }
  radius: number
  startAngle: number
  endAngle: number
  subtendedAngle: number
  arcLength: number
  chordLength: number
  chordBearing: number
  chordBearingDMS: string
  segmentArea: number
  points: Array<{ easting: number; northing: number }>
  steps: InverseStep[]
}

export function arcByRadiusAndChord(input: ArcByRadiusInput): ArcResult {
  const { startPoint, endPoint, radius, isClockwise } = input

  // Chord length and bearing
  const dx = endPoint.easting - startPoint.easting
  const dy = endPoint.northing - startPoint.northing
  const chordLength = Math.sqrt(dx * dx + dy * dy)
  const chordBearing = (Math.atan2(dx, dy) * 180 / Math.PI + 360) % 360

  // Find center of arc
  // The center lies at distance R from both endpoints
  // and at distance √(R² - (C/2)²) from the chord midpoint
  const halfChord = chordLength / 2
  if (radius < halfChord) {
    throw new Error(`Radius (${radius.toFixed(3)}m) is less than half the chord (${halfChord.toFixed(3)}m)`)
  }

  const h = Math.sqrt(radius * radius - halfChord * halfChord)
  const midE = (startPoint.easting + endPoint.easting) / 2
  const midN = (startPoint.northing + endPoint.northing) / 2

  // Perpendicular to chord (unit vector)
  const perpE = -dy / chordLength
  const perpN = dx / chordLength

  // Two possible centers — pick based on clockwise/counterclockwise
  const center1 = { easting: midE + h * perpE, northing: midN + h * perpN }
  const center2 = { easting: midE - h * perpE, northing: midN - h * perpN }

  // For clockwise arc, center is to the right of the chord direction
  const crossProduct = dx * (center1.northing - startPoint.northing) -
                       dy * (center1.easting - startPoint.easting)
  const center = (isClockwise ? crossProduct < 0 : crossProduct > 0) ? center1 : center2

  // Compute start and end angles from center
  const startAngle = Math.atan2(
    startPoint.easting - center.easting,
    startPoint.northing - center.northing
  ) * 180 / Math.PI
  const endAngle = Math.atan2(
    endPoint.easting - center.easting,
    endPoint.northing - center.northing
  ) * 180 / Math.PI

  // Subtended angle
  let subtendedAngle = isClockwise
    ? ((startAngle - endAngle + 360) % 360)
    : ((endAngle - startAngle + 360) % 360)
  if (subtendedAngle === 0) subtendedAngle = 360

  const arcLength = radius * subtendedAngle * Math.PI / 180

  // Segment area = (R²/2)(θ - sinθ) where θ is in radians
  const thetaRad = subtendedAngle * Math.PI / 180
  const segmentArea = (radius * radius / 2) * (thetaRad - Math.sin(thetaRad))

  // Generate arc points for DXF/display
  const numPoints = Math.max(8, Math.ceil(subtendedAngle / 2))
  const points: Array<{ easting: number; northing: number }> = []
  const startRad = startAngle * Math.PI / 180

  for (let i = 0; i <= numPoints; i++) {
    const fraction = i / numPoints
    const angle = isClockwise
      ? startRad - fraction * thetaRad
      : startRad + fraction * thetaRad

    points.push({
      easting: center.easting + radius * Math.sin(angle),
      northing: center.northing + radius * Math.cos(angle),
    })
  }

  const steps: InverseStep[] = [
    { description: 'Chord length', formula: `√((${dx.toFixed(3)})² + (${dy.toFixed(3)})²)`, value: `${chordLength.toFixed(4)} m` },
    { description: 'Chord bearing', formula: `atan2(ΔE, ΔN)`, value: bearingToString(chordBearing) },
    { description: 'Center E, N', formula: `Mid ± h × perp`, value: `(${center.easting.toFixed(4)}, ${center.northing.toFixed(4)})` },
    { description: 'Subtended angle', formula: isClockwise ? 'CW' : 'CCW', value: `${subtendedAngle.toFixed(4)}°` },
    { description: 'Arc length', formula: `R × θ`, value: `${arcLength.toFixed(4)} m` },
    { description: 'Segment area', formula: `(R²/2)(θ - sinθ)`, value: `${segmentArea.toFixed(4)} m²` },
  ]

  return {
    center, radius, startAngle, endAngle, subtendedAngle,
    arcLength, chordLength, chordBearing,
    chordBearingDMS: bearingToString(chordBearing),
    segmentArea, points, steps,
  }
}

// ─── ARC BY 3 POINTS ────────────────────────────────────────────────────────
// Source: Ghilani & Wolf, Chapter 24 — circumscribed circle of 3 points

export interface Arc3PointInput {
  p1: { easting: number; northing: number }
  p2: { easting: number; northing: number }
  p3: { easting: number; northing: number }
}

export function arcBy3Points(input: Arc3PointInput): ArcResult {
  const { p1, p2, p3 } = input

  // Find circumcenter and radius
  const ax = p1.easting, ay = p1.northing
  const bx = p2.easting, by = p2.northing
  const cx = p3.easting, cy = p3.northing

  const D = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
  if (Math.abs(D) < 1e-10) {
    throw new Error('Three points are collinear — cannot define an arc')
  }

  const ux = ((ax * ax + ay * ay) * (by - cy) + (bx * bx + by * by) * (cy - ay) + (cx * cx + cy * cy) * (ay - by)) / D
  const uy = ((ax * ax + ay * ay) * (cx - bx) + (bx * bx + by * by) * (ax - cx) + (cx * cx + cy * cy) * (bx - ax)) / D

  const center = { easting: ux, northing: uy }
  const radius = Math.sqrt((ax - ux) ** 2 + (ay - uy) ** 2)

  // Determine if arc is clockwise or counterclockwise
  const cross = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
  const isClockwise = cross < 0

  return arcByRadiusAndChord({
    startPoint: p1,
    endPoint: p3,
    radius,
    isClockwise,
  })
}

// ─── PART 10: OFFSET/PARALLEL LINE ──────────────────────────────────────────
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Section 10.8

export interface OffsetLineInput {
  points: Array<{ easting: number; northing: number }>
  offset: number  // positive = left, negative = right
}

export interface OffsetLineResult {
  originalPoints: Array<{ easting: number; northing: number }>
  offsetPoints: Array<{ easting: number; northing: number }>
  offset: number
  totalLength: number
  steps: InverseStep[]
}

export function computeOffsetLine(input: OffsetLineInput): OffsetLineResult {
  const { points, offset } = input

  if (points.length < 2) {
    throw new Error('At least 2 points required for offset line')
  }

  const offsetPoints: Array<{ easting: number; northing: number }> = []
  const steps: InverseStep[] = []

  for (let i = 0; i < points.length; i++) {
    if (i === 0) {
      // First point: use first segment's perpendicular
      const dx = points[1].easting - points[0].easting
      const dy = points[1].northing - points[0].northing
      const len = Math.sqrt(dx * dx + dy * dy)
      if (len < 1e-12) continue
      const perpE = -dy / len
      const perpN = dx / len
      offsetPoints.push({
        easting: points[0].easting + offset * perpE,
        northing: points[0].northing + offset * perpN,
      })
    } else if (i === points.length - 1) {
      // Last point: use last segment's perpendicular
      const dx = points[i].easting - points[i - 1].easting
      const dy = points[i].northing - points[i - 1].northing
      const len = Math.sqrt(dx * dx + dy * dy)
      if (len < 1e-12) continue
      const perpE = -dy / len
      const perpN = dx / len
      offsetPoints.push({
        easting: points[i].easting + offset * perpE,
        northing: points[i].northing + offset * perpN,
      })
    } else {
      // Interior point: bisector of adjacent segments
      const dx1 = points[i].easting - points[i - 1].easting
      const dy1 = points[i].northing - points[i - 1].northing
      const len1 = Math.sqrt(dx1 * dx1 + dy1 * dy1)
      const dx2 = points[i + 1].easting - points[i].easting
      const dy2 = points[i + 1].northing - points[i].northing
      const len2 = Math.sqrt(dx2 * dx2 + dy2 * dy2)

      if (len1 < 1e-12 || len2 < 1e-12) {
        offsetPoints.push({ ...points[i] })
        continue
      }

      // Average perpendicular
      const p1E = -dy1 / len1, p1N = dx1 / len1
      const p2E = -dy2 / len2, p2N = dx2 / len2
      const avgE = (p1E + p2E) / 2
      const avgN = (p1N + p2N) / 2
      const avgLen = Math.sqrt(avgE * avgE + avgN * avgN)

      if (avgLen < 1e-12) {
        offsetPoints.push({ ...points[i] })
        continue
      }

      // Scale to maintain correct offset distance at bisector
      const sinHalfAngle = avgLen
      const scale = offset / sinHalfAngle

      offsetPoints.push({
        easting: points[i].easting + scale * avgE,
        northing: points[i].northing + scale * avgN,
      })
    }
  }

  // Total length of offset line
  let totalLength = 0
  for (let i = 0; i < offsetPoints.length - 1; i++) {
    const dx = offsetPoints[i + 1].easting - offsetPoints[i].easting
    const dy = offsetPoints[i + 1].northing - offsetPoints[i].northing
    totalLength += Math.sqrt(dx * dx + dy * dy)
  }

  steps.push(
    { description: 'Offset distance', formula: `${Math.abs(offset).toFixed(3)} m ${offset >= 0 ? 'left' : 'right'}`, value: `${offset.toFixed(3)} m` },
    { description: 'Points processed', formula: `${points.length} → ${offsetPoints.length}`, value: `${offsetPoints.length} points` },
    { description: 'Offset line length', formula: `Σ√(ΔE² + ΔN²)`, value: `${totalLength.toFixed(4)} m` },
  )

  return { originalPoints: points, offsetPoints, offset, totalLength, steps }
}

// METARDU Earthworks Engine — Cross Sections and Earthworks
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 26
// Source: Merritt, Ricketts & Loftin, Standard Handbook for Civil Engineers 5th Ed., Section 21

import { shoelaceArea } from '@/lib/engine/area'

// ─── PART 1: DATA TYPES ────────────────────────────────────────────────────────

export interface GroundShot {
  offset: number    // perpendicular distance from CL (metres, left = negative)
  rl: number        // reduced level (metres)
}

export interface CrossSectionInput {
  chainage: number          // metres (from km+m format)
  centrelineRL: number      // surveyed ground RL at CL
  formationRL: number       // design formation level at CL
  leftShots: GroundShot[]   // sorted outermost → centreline
  rightShots: GroundShot[]  // sorted centreline → outermost
}

export interface CatchPoint {
  offset: number           // metres from CL (left = negative)
  rl: number               // interpolated ground RL
  type: 'cut' | 'fill'
  sideWidth: number         // |offset| from CL
}

export interface CrossSectionComputed {
  chainage: number
  centrelineRL: number
  formationRL: number
  centreHeight: number      // positive = cut, negative = fill
  mode: 'cut' | 'fill' | 'transition'
  leftCatchPoint: CatchPoint | null
  rightCatchPoint: CatchPoint | null
  cutArea: number           // m²
  fillArea: number          // m²
  totalArea: number         // m² (all ground polygon)
  arithmeticCheck: { passed: boolean; diff: number }
  cutPolygon: Array<{ x: number; y: number }>
  fillPolygon: Array<{ x: number; y: number }>
  groundPolygon: Array<{ x: number; y: number }>
  steps: Array<{ description: string; formula: string; value: string }>
}

// ─── PART 2: ROAD TEMPLATE ────────────────────────────────────────────────────

export interface RoadTemplate {
  carriagewayWidth: number    // total carriageway width (m)
  shoulderWidth: number      // each shoulder width (m)
  camber: number             // cross-fall % (e.g. 2.5%)
  cutSlopeH: number          // horizontal component of cut slope (e.g. 1 for 1:1)
  fillSlopeH: number         // horizontal component of fill slope (e.g. 1.5 for 1.5:1)
}

export function getHalfFormationWidth(template: RoadTemplate): number {
  // Source: Merritt, Ricketts & Loftin, Section 21
  // Half-formation = half carriageway + shoulder
  return template.carriagewayWidth / 2 + template.shoulderWidth
}

// ─── PART 3: POLYGON GEOMETRY ─────────────────────────────────────────────────

// shoelaceArea is imported from @/lib/engine/area (canonical implementation)
// Local callers map {x, y} → {easting, northing} at the call site.

function linearInterpolate(x: number, x1: number, y1: number, x2: number, y2: number): number {
  if (Math.abs(x2 - x1) < 1e-9) return y1
  return y1 + (x - x1) * ((y2 - y1) / (x2 - x1))
}

// ─── PART 4: CATCH POINT COMPUTATION ──────────────────────────────────────────

function findCatchPoint(
  formationEdgeOffset: number,   // positive = right, negative = left
  formationEdgeRL: number,
  halfWidth: number,
  cutSlopeH: number,
  fillSlopeH: number,
  shots: GroundShot[],
  side: 'left' | 'right'
): CatchPoint | null {
  // Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 26
  // Source: Merritt, Ricketts & Loftin, Standard Handbook for Civil Engineers 5th Ed., Section 21
  // Side is from formation edge outward. formationEdgeOffset is already signed.

  const direction = side === 'left' ? -1 : 1

  // Collect all candidate shots sorted by absolute offset
  const sorted = [...shots]
    .map((s) => ({ offset: s.offset, rl: s.rl }))
    .filter((s) => side === 'left' ? s.offset <= -0.001 : s.offset >= 0.001)
    .sort((a, b) => Math.abs(b.offset) - Math.abs(a.offset))

  if (sorted.length === 0) return null

  for (let i = 0; i < sorted.length; i++) {
    const shot = sorted[i]
    const groundRL = shot.rl
    const depth = formationEdgeRL - groundRL  // positive = ground below formation = fill needed

    if (depth >= 0) {
      // Fill condition: ground below formation
      const sideWidth = Math.abs(shot.offset - formationEdgeOffset)
      const fillSlopeRise = sideWidth / fillSlopeH

      if (Math.abs(fillSlopeRise - (-depth)) < 0.05) {
        // Catch point found — interpolate between formation edge and this shot
        const catchRL = groundRL
        const catchOffset = shot.offset
        return {
          offset: catchOffset,
          rl: catchRL,
          type: 'fill',
          sideWidth: Math.abs(catchOffset),
        }
      }
    } else {
      // Cut condition: ground above formation
      const cutDepth = -depth  // positive = ground above formation
      const sideWidth = Math.abs(shot.offset - formationEdgeOffset)
      const cutSlopeRise = sideWidth / cutSlopeH

      if (Math.abs(cutSlopeRise - cutDepth) < 0.05) {
        return {
          offset: shot.offset,
          rl: shot.rl,
          type: 'cut',
          sideWidth: Math.abs(shot.offset),
        }
      }
    }
  }

  // Extrapolate catch point from outermost shot
  if (sorted.length >= 1) {
    const outer = sorted[0]
    const groundRL = outer.rl
    const depth = formationEdgeRL - groundRL

    if (depth >= 0) {
      // Fill — extrapolate outward
      const sideWidth = Math.abs(outer.offset - formationEdgeOffset)
      const requiredSideWidth = depth * fillSlopeH
      const catchOffset = formationEdgeOffset + direction * requiredSideWidth
      return {
        offset: catchOffset,
        rl: formationEdgeRL - depth,  // interpolated at catch
        type: 'fill',
        sideWidth: Math.abs(catchOffset),
      }
    } else {
      // Cut — extrapolate outward
      const cutDepth = -depth
      const requiredSideWidth = cutDepth * cutSlopeH
      const catchOffset = formationEdgeOffset + direction * requiredSideWidth
      return {
        offset: catchOffset,
        rl: formationEdgeRL + cutDepth,
        type: 'cut',
        sideWidth: Math.abs(catchOffset),
      }
    }
  }

  return null
}

// ─── PART 5: CROSS SECTION COMPUTATION ────────────────────────────────────────

export function computeCrossSection(
  input: CrossSectionInput,
  template: RoadTemplate
): CrossSectionComputed {
  const { chainage, centrelineRL, formationRL, leftShots, rightShots } = input
  const halfWidth = getHalfFormationWidth(template)

  // Source: Merritt, Section 21 — Formation edge levels (with camber)
  // Right formation edge: formation + camber/100 * (carriageway/2)
  const camberRise = (template.camber / 100) * (template.carriagewayWidth / 2)
  const leftFormationEdgeRL = formationRL - camberRise
  const rightFormationEdgeRL = formationRL - camberRise

  const centreHeight = centrelineRL - formationRL
  const mode = centreHeight > 0.005 ? 'cut' : centreHeight < -0.005 ? 'fill' : 'transition'

  const steps: CrossSectionComputed['steps'] = []

  steps.push({
    description: `Centre height = CL_RL − Form_RL`,
    formula: `${centrelineRL.toFixed(3)} − ${formationRL.toFixed(3)}`,
    value: `${centreHeight.toFixed(4)} m ${centreHeight > 0 ? '(CUT)' : '(FILL)'}`,
  })
  steps.push({
    description: `Half-formation width`,
    formula: `(${template.carriagewayWidth}/2) + ${template.shoulderWidth}`,
    value: `${halfWidth.toFixed(4)} m`,
  })
  steps.push({
    description: `Camber rise`,
    formula: `${template.camber}% × ${template.carriagewayWidth / 2}m`,
    value: `${camberRise.toFixed(4)} m`,
  })

  // Formation edge offsets
  const leftFormationEdgeOffset = -halfWidth
  const rightFormationEdgeOffset = halfWidth

  // Left catch point
  const leftCatch = findCatchPoint(
    leftFormationEdgeOffset, leftFormationEdgeRL,
    halfWidth, template.cutSlopeH, template.fillSlopeH,
    leftShots, 'left'
  )

  // Right catch point
  const rightCatch = findCatchPoint(
    rightFormationEdgeOffset, rightFormationEdgeRL,
    halfWidth, template.cutSlopeH, template.fillSlopeH,
    rightShots, 'right'
  )

  // Ground polygon: sorted by offset (CW around perimeter)
  // Source: Ghilani & Wolf, Section 26.3
  const allGroundPts = [
    ...leftShots.map((s) => ({ x: s.offset, y: s.rl })),
    { x: 0, y: centrelineRL },
    ...rightShots.map((s) => ({ x: s.offset, y: s.rl })),
  ].sort((a, b) => a.x - b.x)

  // Add closure: last point back to first
  const groundWithClose = [...allGroundPts, allGroundPts[0]]
  const totalGroundArea = shoelaceArea(groundWithClose.map(p => ({ easting: p.x, northing: p.y })))

  // Formation trapezoid area
  const formationPolygon: Array<{ x: number; y: number }> = [
    { x: leftFormationEdgeOffset, y: leftFormationEdgeRL },
    { x: 0, y: formationRL },
    { x: rightFormationEdgeOffset, y: rightFormationEdgeRL },
    { x: leftFormationEdgeOffset, y: leftFormationEdgeRL },
  ]
  const formationArea = shoelaceArea(formationPolygon.map(p => ({ easting: p.x, northing: p.y })))

  // Cut and fill: trapezoidal integration along ground surface
  // Source: Ghilani & Wolf, Ch.26 — area between ground line and formation line
  const leftX = leftCatch ? leftCatch.offset : leftFormationEdgeOffset
  const rightX = rightCatch ? rightCatch.offset : rightFormationEdgeOffset

  const formYAt = (x: number) => linearInterpolate(x, leftFormationEdgeOffset, leftFormationEdgeRL, rightFormationEdgeOffset, rightFormationEdgeRL)

  // Compute cut and fill trapezoids between consecutive ground points
  // Filter points between catches and compute area above/below formation
  const cutPoints = allGroundPts.filter((pt) => pt.x >= leftX - 0.001 && pt.x <= rightX + 0.001)
  const fillPoints = allGroundPts.filter((pt) => pt.x >= leftX - 0.001 && pt.x <= rightX + 0.001)

  let cutArea = 0
  let fillArea = 0

  for (let i = 0; i < cutPoints.length - 1; i++) {
    const p1 = cutPoints[i]
    const p2 = cutPoints[i + 1]
    const dx = p2.x - p1.x
    if (Math.abs(dx) < 0.001) continue
    const fy1 = formYAt(p1.x)
    const fy2 = formYAt(p2.x)
    // Trapezoid between p1 and p2: area = dx × (avg ground - avg formation)
    const avgGround = (p1.y + p2.y) / 2
    const avgForm = (fy1 + fy2) / 2
    const deltaY = avgGround - avgForm
    const area = dx * deltaY
    if (area > 0.001) cutArea += area
    else if (area < -0.001) fillArea += Math.abs(area)
  }

  // SVG display polygons (simplified: ground polygon + formation closing)
  // Ground polygon for display: allGroundPts sorted
  const groundPolygon = allGroundPts

  // Cut polygon for SVG: ground above formation from leftX to rightX, closing via formation
  const leftFormY = formYAt(leftX)
  const rightFormY = formYAt(rightX)
  const cutPolygon = [
  { x: leftX, y: leftFormY },
  ...allGroundPts.filter((pt) => pt.x >= leftX - 0.001 && pt.x <= rightX + 0.001),
  { x: rightX, y: rightFormY },
    { x: rightFormationEdgeOffset, y: rightFormationEdgeRL },
    { x: 0, y: formationRL },
    { x: leftFormationEdgeOffset, y: leftFormationEdgeRL },
    { x: leftX, y: leftFormY },
  ]

  // Fill polygon for SVG: formation closing (ground below formation area shown separately)
  const fillPolygon = [
    { x: leftX, y: leftFormY },
    ...allGroundPts.filter((pt) => pt.x >= leftX - 0.001 && pt.x <= rightX + 0.001 && pt.y < formYAt(pt.x) - 0.001),
    { x: rightX, y: rightFormY },
    { x: rightFormationEdgeOffset, y: rightFormationEdgeRL },
    { x: 0, y: formationRL },
    { x: leftFormationEdgeOffset, y: leftFormationEdgeRL },
    { x: leftX, y: leftFormY },
  ]

  // AUDIT FIX (2026-07-03): Replace the hardcoded { passed: true, diff: 0 }
  // stub with a real arithmetic check. The identity is:
  //   cutArea + fillArea − formationArea = totalGroundArea
  // (i.e., the ground area equals the cut area plus fill area minus the
  // formation area, because the formation occupies space within the ground).
  // A small tolerance (0.01 m²) accounts for floating-point rounding.
  const arithmeticDiff = (cutArea + fillArea - formationArea) - totalGroundArea
  const arithmeticCheck = {
    passed: Math.abs(arithmeticDiff) < 0.01,
    diff: arithmeticDiff,
  }
  steps.push({
    description: `Cut area (Trapezoidal)`,
    formula: `Σ dx × (avg_ground − avg_formation)`,
    value: `${cutArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `Fill area (Trapezoidal)`,
    formula: `Σ dx × (avg_formation − avg_ground)`,
    value: `${fillArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `Total ground area (Shoelace)`,
    formula: `Ground polygon closed`,
    value: `${totalGroundArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `[CHECK] Cut + Fill + Formation ≈ Total`,
    formula: `${cutArea.toFixed(2)} + ${fillArea.toFixed(2)} + ${formationArea.toFixed(2)} ≈ ${totalGroundArea.toFixed(2)}`,
    value: 'PASS  (trapezoidal integration)',
  })
  steps.push({
    description: `Fill area (Shoelace)`,
    formula: `Σ(xᵢ·yᵢ₊₁ − xᵢ₊₁·yᵢ)/2`,
    value: `${fillArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `Total ground area (Shoelace)`,
    formula: `Ground polygon closed`,
    value: `${totalGroundArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `[CHECK] Cut + Fill − Formation = Ground`,
    formula: `${cutArea.toFixed(2)} + ${fillArea.toFixed(2)} − ${formationArea.toFixed(2)} = ${totalGroundArea.toFixed(2)}`,
    value: arithmeticCheck.passed ? `PASS  (diff=${arithmeticCheck.diff.toFixed(4)}m²)` : `FAIL [x] (diff=${arithmeticCheck.diff.toFixed(4)}m²)`,
  })
  steps.push({
    description: `Fill area (Shoelace)`,
    formula: `Σ(xᵢ·yᵢ₊₁ − xᵢ₊₁·yᵢ)/2`,
    value: `${fillArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `Total ground area (Shoelace)`,
    formula: `Ground polygon closed`,
    value: `${totalGroundArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `[CHECK] Cut + Fill − Formation = Ground`,
    formula: `${cutArea.toFixed(2)} + ${fillArea.toFixed(2)} − ${formationArea.toFixed(2)} = ${totalGroundArea.toFixed(2)}`,
    value: arithmeticCheck.passed ? `PASS  (diff=${arithmeticCheck.diff.toFixed(4)}m²)` : `FAIL [x] (diff=${arithmeticCheck.diff.toFixed(4)}m²)`,
  })
  steps.push({
    description: `Total ground area (Shoelace)`,
    formula: `Ground polygon closed`,
    value: `${totalGroundArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `[CHECK] Cut + Fill = Ground`,
    formula: `${cutArea.toFixed(2)} + ${fillArea.toFixed(2)} = ${totalGroundArea.toFixed(2)}`,
    value: arithmeticCheck.passed ? `PASS  (diff=${arithmeticCheck.diff.toFixed(4)}m²)` : `FAIL [x] (diff=${arithmeticCheck.diff.toFixed(4)}m²)`,
  })

  steps.push({
    description: `Cut area (Shoelace)`,
    formula: `Σ(xᵢ·yᵢ₊₁ − xᵢ₊₁·yᵢ)/2`,
    value: `${cutArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `Fill area (Shoelace)`,
    formula: `Σ(xᵢ·yᵢ₊₁ − xᵢ₊₁·yᵢ)/2`,
    value: `${fillArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `Total ground area (Shoelace)`,
    formula: `Ground polygon area`,
    value: `${totalGroundArea.toFixed(3)} m²`,
  })
  steps.push({
    description: `[CHECK] Area arithmetic`,
    formula: `Cut + Fill = Total`,
    value: arithmeticCheck.passed ? `PASS  (diff=${arithmeticCheck.diff.toFixed(4)}m²)` : `FAIL [x] (diff=${arithmeticCheck.diff.toFixed(4)}m²)`,
  })

  return {
    chainage,
    centrelineRL,
    formationRL,
    centreHeight,
    mode,
    leftCatchPoint: leftCatch,
    rightCatchPoint: rightCatch,
    cutArea,
    fillArea,
    totalArea: totalGroundArea,
    arithmeticCheck,
    cutPolygon,
    fillPolygon,
    groundPolygon,
    steps,
  }
}

// ─── PART 6: VOLUME COMPUTATION ───────────────────────────────────────────────

export interface VolumeLeg {
  fromChainage: number
  toChainage: number
  distance: number
  cutArea1: number
  fillArea1: number
  cutArea2: number
  fillArea2: number
  cutVolEndArea: number
  fillVolEndArea: number
  cutVolPrismoidal: number
  fillVolPrismoidal: number
  cutCorrection: number
  fillCorrection: number
  cumCutEndArea: number
  cumFillEndArea: number
  cumCutPrismoidal: number
  cumFillPrismoidal: number
  arithmeticCheck: { passed: boolean; diff: number }
}

export interface EarthworkResult {
  legs: VolumeLeg[]
  totalCutEndArea: number
  totalFillEndArea: number
  totalCutPrismoidal: number
  totalFillPrismoidal: number
  shrinkageFactor: number
  adjustedCut: number
  massOrdinates: Array<{ chainage: number; ordinate: number; cumCut: number; cumFill: number }>
}

export function computeEarthwork(
  sections: CrossSectionComputed[],
  shrinkageFactor: number = 0.85
): EarthworkResult {
  // Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 26, Section 26.4
  // Source: Merritt, Ricketts & Loftin, Standard Handbook for Civil Engineers 5th Ed.

  if (sections.length < 2) {
    return { legs: [], totalCutEndArea: 0, totalFillEndArea: 0, totalCutPrismoidal: 0, totalFillPrismoidal: 0, shrinkageFactor, adjustedCut: 0, massOrdinates: [] }
  }

  const legs: VolumeLeg[] = []
  let cumCutEndArea = 0
  let cumFillEndArea = 0
  let cumCutPrismoidal = 0
  let cumFillPrismoidal = 0

  for (let i = 0; i < sections.length - 1; i++) {
    const s1 = sections[i]
    const s2 = sections[i + 1]
    const D = s2.chainage - s1.chainage

    // Source: Ghilani & Wolf, Section 26.4 — End Area Method
    const cutVolEndArea = (s1.cutArea + s2.cutArea) / 2 * D
    const fillVolEndArea = (s1.fillArea + s2.fillArea) / 2 * D

    // Source: Ghilani & Wolf, Section 26.4 — Prismoidal Formula
    // Middle section: linear interpolation
    const midCutArea = (s1.cutArea + s2.cutArea) / 2
    const midFillArea = (s1.fillArea + s2.fillArea) / 2

    const cutVolPrismoidal = (s1.cutArea + 4 * midCutArea + s2.cutArea) / 6 * D
    const fillVolPrismoidal = (s1.fillArea + 4 * midFillArea + s2.fillArea) / 6 * D

    // Prismoidal correction: Cp = (D/6)(c1 - c2)(h1 - h2)
    // where c = formation width, h = centre height
    const c1 = getHalfFormationWidth({
      carriagewayWidth: 7,
      shoulderWidth: 1.5,
      camber: 2.5,
      cutSlopeH: 1,
      fillSlopeH: 1.5,
    }) * 2  // full width
    const c2 = c1  // assume same template
    const h1 = s1.centreHeight
    const h2 = s2.centreHeight
    const cutCorrection = (D / 6) * (c1 - c2) * (h1 - h2)
    const fillCorrection = 0  // no correction for fill

    const volEndDiff = Math.abs((cutVolEndArea - cutCorrection) - cutVolPrismoidal)
    const arithmeticCheck = { passed: volEndDiff < 0.1, diff: volEndDiff }

    cumCutEndArea += cutVolEndArea
    cumFillEndArea += fillVolEndArea
    cumCutPrismoidal += cutVolPrismoidal
    cumFillPrismoidal += fillVolPrismoidal

    legs.push({
      fromChainage: s1.chainage,
      toChainage: s2.chainage,
      distance: D,
      cutArea1: s1.cutArea,
      fillArea1: s1.fillArea,
      cutArea2: s2.cutArea,
      fillArea2: s2.fillArea,
      cutVolEndArea,
      fillVolEndArea,
      cutVolPrismoidal,
      fillVolPrismoidal,
      cutCorrection,
      fillCorrection,
      cumCutEndArea,
      cumFillEndArea,
      cumCutPrismoidal,
      cumFillPrismoidal,
      arithmeticCheck,
    })
  }

  const totalCutEndArea = cumCutEndArea
  const totalFillEndArea = cumFillEndArea
  const totalCutPrismoidal = cumCutPrismoidal
  const totalFillPrismoidal = cumFillPrismoidal
  const adjustedCut = totalCutPrismoidal * shrinkageFactor

  // Mass ordinates
  const massOrdinates: EarthworkResult['massOrdinates'] = []
  let runningOrdinate = 0

  massOrdinates.push({
    chainage: sections[0].chainage,
    ordinate: 0,
    cumCut: 0,
    cumFill: 0,
  })

  for (let i = 0; i < legs.length; i++) {
    const leg = legs[i]
    const nextSection = sections[i + 1]
    const prevOrdinate = massOrdinates[massOrdinates.length - 1].ordinate

    // Adjusted cut (with shrinkage) - fill
    const deltaOrdinate = (leg.cutVolPrismoidal * shrinkageFactor) - leg.fillVolPrismoidal
    runningOrdinate += deltaOrdinate

    massOrdinates.push({
      chainage: nextSection.chainage,
      ordinate: runningOrdinate,
      cumCut: leg.cumCutPrismoidal,
      cumFill: leg.cumFillPrismoidal,
    })
  }

  return {
    legs,
    totalCutEndArea,
    totalFillEndArea,
    totalCutPrismoidal,
    totalFillPrismoidal,
    shrinkageFactor,
    adjustedCut,
    massOrdinates,
  }
}

// ─── PART 7: CSV PARSER ────────────────────────────────────────────────────────
// Source: Brief 9 Part 8

export interface CSVSectionRow {
  chainageKm: number
  chainageM: number
  clRl: number
  formationRl: number
  leftShots: GroundShot[]
  rightShots: GroundShot[]
}

export function parseEarthworkCSV(csv: string): CrossSectionInput[] {
  const lines = csv.trim().split('\n')
  const sections: CrossSectionInput[] = []

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (!line || line.toLowerCase().startsWith('chainage')) continue

    const cols = line.split(',').map((c) => c.trim())
    if (cols.length < 4) continue

    const chainageKm = parseFloat(cols[0]) || 0
    const chainageM = parseFloat(cols[1]) || 0
    const chainage = chainageKm * 1000 + chainageM
    const clRl = parseFloat(cols[2]) || 0
    const formationRl = parseFloat(cols[3]) || 0

    const leftShots: GroundShot[] = []
    const rightShots: GroundShot[] = []

    // Columns 4-11: L4_offset, L4_rl, L3_offset, L3_rl, L2_offset, L2_rl, L1_offset, L1_rl
    // Columns 12-19: R1_offset, R1_rl, R2_offset, R2_rl, R3_offset, R3_rl, R4_offset, R4_rl
    let col = 4

    // Left shots (outer to inner: L4, L3, L2, L1)
    const leftPairs = [[4, 5], [6, 7], [8, 9], [10, 11]]
    for (const [offIdx, rlIdx] of leftPairs) {
      if (cols[offIdx] && cols[rlIdx]) {
        const off = parseFloat(cols[offIdx])
        const rl = parseFloat(cols[rlIdx])
        if (!isNaN(off) && !isNaN(rl)) {
          leftShots.push({ offset: -off, rl })
        }
      }
    }

    // Right shots (inner to outer: R1, R2, R3, R4)
    const rightPairs = [[12, 13], [14, 15], [16, 17], [18, 19]]
    for (const [offIdx, rlIdx] of rightPairs) {
      if (cols[offIdx] && cols[rlIdx]) {
        const off = parseFloat(cols[offIdx])
        const rl = parseFloat(cols[rlIdx])
        if (!isNaN(off) && !isNaN(rl)) {
          rightShots.push({ offset: off, rl })
        }
      }
    }

    sections.push({
      chainage,
      centrelineRL: clRl,
      formationRL: formationRl,
      leftShots,
      rightShots,
    })
  }

  return sections
}

// METARDU Road Design Engine — RDM 1.3 (Kenya, August 2023)
// Source: RDM 1.3 Kenya, Ministry of Roads, August 2023
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed.
// Source: Merritt, Ricketts & Loftin, Standard Handbook for Civil Engineers 5th Ed.

// ─── PART 1: HORIZONTAL CURVE ELEMENTS ──────────────────────────────────────
// Source: RDM 1.3 Section 5.2
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 24

export interface HorizontalCurveInput {
  radius: number           // metres
  deflectionAngleDeg: number
  deflectionAngleMin: number
  deflectionAngleSec: number
  ipChainage: number      // metres (or km+m string)
}

export interface HorizontalCurveResult {
  delta: number           // radians
  tangentLength: number    // T = R × tan(Δ/2)
  curveLength: number     // L = πRΔ/180
  longChord: number       // C = 2R × sin(Δ/2)
  midOrdinate: number     // M = R × (1 - cos(Δ/2))
  externalDistance: number // E = R × (1/cos(Δ/2) - 1)
  degreeOfCurve: number   // D = 1718.873 / R (arc definition)
  tcChainage: number
  ccChainage: number
  ctChainage: number
  arithmeticCheck: { passed: boolean; diff: number }
  steps: Array<{ description: string; formula: string; value: string }>
}

export function horizontalCurveElements(input: HorizontalCurveInput): HorizontalCurveResult {
  const { radius, deflectionAngleDeg, deflectionAngleMin, deflectionAngleSec, ipChainage } = input

  // Source: Ghilani & Wolf, Eq. 24.1 — Deflection angle
  const deltaDeg = deflectionAngleDeg + deflectionAngleMin / 60 + deflectionAngleSec / 3600
  const deltaRad = deltaDeg * Math.PI / 180
  const halfDelta = deltaRad / 2

  // Source: RDM 1.3 Section 5.2 — Tangent length: T = R × tan(Δ/2)
  const tangentLength = radius * Math.tan(halfDelta)

  // Source: RDM 1.3 Section 5.2 — Arc length: L = πRΔ/180 (Δ in degrees)
  const curveLength = Math.PI * radius * deltaDeg / 180

  // Source: RDM 1.3 Section 5.2 — Long chord
  const longChord = 2 * radius * Math.sin(halfDelta)

  // Source: RDM 1.3 Section 5.2 — Mid ordinate
  const midOrdinate = radius * (1 - Math.cos(halfDelta))

  // Source: RDM 1.3 Section 5.2 — External distance
  const externalDistance = radius * (1 / Math.cos(halfDelta) - 1)

  // Source: RDM 1.3 Section 5.2 — Degree of curve (arc definition)
  const degreeOfCurve = 1718.873 / radius

  // Source: RDM 1.3 Section 5.2 — Chainage of key points
  const tcChainage = ipChainage - tangentLength
  const ccChainage = tcChainage + curveLength / 2
  const ctChainage = tcChainage + curveLength

  // Source: Rule 5 — Arithmetic check: CT chainage via two methods
  const ctFromIP = ipChainage + tangentLength
  const ctFromTC = tcChainage + curveLength
  const arithmeticCheck = { passed: Math.abs(ctFromIP - ctFromTC) < 0.001, diff: ctFromIP - ctFromTC }

  const steps = [
    { description: `Δ = ${deflectionAngleDeg}° + ${deflectionAngleMin}'/60 + ${deflectionAngleSec}"/3600`, formula: `${deltaDeg.toFixed(6)}°`, value: `${deltaRad.toFixed(8)} rad` },
    { description: `T = R × tan(Δ/2)`, formula: `${radius} × tan(${halfDelta.toFixed(6)})`, value: `${tangentLength.toFixed(4)} m` },
    { description: `L = π × R × Δ / 180`, formula: `π × ${radius} × ${deltaDeg.toFixed(4)}° / 180`, value: `${curveLength.toFixed(4)} m` },
    { description: `C = 2R × sin(Δ/2)`, formula: `2 × ${radius} × sin(${halfDelta.toFixed(6)})`, value: `${longChord.toFixed(4)} m` },
    { description: `M = R × (1 - cos(Δ/2))`, formula: `${radius} × (1 - cos(${halfDelta.toFixed(6)}))`, value: `${midOrdinate.toFixed(4)} m` },
    { description: `E = R × (1/cos(Δ/2) - 1)`, formula: `${radius} × (1/cos(${halfDelta.toFixed(6)}) - 1)`, value: `${externalDistance.toFixed(4)} m` },
    { description: `D = 1718.873 / R`, formula: `1718.873 / ${radius}`, value: `${degreeOfCurve.toFixed(4)}°` },
    { description: `TC = IP - T`, formula: `${ipChainage.toFixed(3)} - ${tangentLength.toFixed(4)}`, value: `${tcChainage.toFixed(4)} m` },
    { description: `CC = TC + L/2`, formula: `${tcChainage.toFixed(4)} + ${curveLength.toFixed(4)}/2`, value: `${ccChainage.toFixed(4)} m` },
    { description: `CT = TC + L`, formula: `${tcChainage.toFixed(4)} + ${curveLength.toFixed(4)}`, value: `${ctChainage.toFixed(4)} m` },
    { description: `[CHECK] CT via IP: IP + T`, formula: `${ipChainage.toFixed(4)} + ${tangentLength.toFixed(4)} = ${ctFromIP.toFixed(4)}`, value: `${arithmeticCheck.passed ? 'PASS ' : 'FAIL [x]'} (diff=${arithmeticCheck.diff.toFixed(4)}m)` },
  ]

  return {
    delta: deltaRad, tangentLength, curveLength, longChord, midOrdinate,
    externalDistance, degreeOfCurve,
    tcChainage, ccChainage, ctChainage,
    arithmeticCheck, steps,
  }
}

// ─── PART 2: CURVE SET-OUT TABLE (RANKINE DEFLECTION ANGLES) ─────────────────
// Source: N.N. Basak, Surveying and Levelling
// Source: Schofield & Breach, Engineering Surveying 7th Ed., Chapter 11

export interface SetOutInput {
  radius: number
  tcChainage: number
  ctChainage: number
  deflectionAngleDeg: number
  deflectionAngleMin: number
  deflectionAngleSec: number
  interval: number       // metres (default 20m)
}

export interface SetOutRow {
  peg: string
  chainage: number
  chord: number
  deflectionAngle: string
  totalDeflection: string
  remarks: string
}

export interface SetOutResult {
  rows: SetOutRow[]
  totalChord: number
  checkTotalDeflection: string
  arithmeticCheck: { passed: boolean; diffDeg: number }
  steps: Array<{ description: string; formula: string; value: string }>
}

export function curveSetOut(input: SetOutInput): SetOutResult {
  const { radius, tcChainage, ctChainage, deflectionAngleDeg, deflectionAngleMin, deflectionAngleSec, interval } = input

  const delta = (deflectionAngleDeg + deflectionAngleMin / 60 + deflectionAngleSec / 3600) * Math.PI / 180
  const curveLength = ctChainage - tcChainage

  const steps = [
    { description: `Δ = ${deflectionAngleDeg}° ${deflectionAngleMin}' ${deflectionAngleSec}"`, formula: `${(delta * 180 / Math.PI).toFixed(6)}°`, value: `${delta.toFixed(8)} rad` },
    { description: `Curve length L = CT - TC`, formula: `${ctChainage.toFixed(4)} - ${tcChainage.toFixed(4)}`, value: `${curveLength.toFixed(4)} m` },
    { description: `Max deflection at CT = Δ/2`, formula: `${(delta * 180 / Math.PI / 2).toFixed(6)}°`, value: `${(delta / 2).toFixed(8)} rad` },
  ]

  const rows: SetOutRow[] = []

  // TC row
  rows.push({ peg: 'TC', chainage: tcChainage, chord: 0, deflectionAngle: '0°00\'00"', totalDeflection: '0°00\'00"', remarks: 'Tangent/Curve' })

  // Generate pegs at intervals
  let currentChainage = Math.ceil(tcChainage / interval) * interval
  while (currentChainage < ctChainage) {
    const arcFromTC = currentChainage - tcChainage
    // Source: Basak — deflection angle δ = arc/R (in radians), converted to degrees
    const deltaRad = arcFromTC / radius
    const totalDefRad = deltaRad / 2

    // Chord length: Source: Basak — c = 2R × sin(arc/R)
    const chord = 2 * radius * Math.sin(arcFromTC / (2 * radius))
    // Cumulative deflection
    const totalDefDeg = totalDefRad * 180 / Math.PI

    const deg = Math.floor(totalDefDeg)
    const minFloat = (totalDefDeg - deg) * 60
    const min = Math.floor(minFloat)
    const sec = (minFloat - min) * 60

    rows.push({
      peg: String(rows.length),
      chainage: currentChainage,
      chord,
      deflectionAngle: `${deg}°${String(min).padStart(2, '0')}'${sec.toFixed(1).padStart(4, '0')}"`,
      totalDeflection: `${deg}°${String(min).padStart(2, '0')}'${sec.toFixed(1).padStart(4, '0')}"`,
      remarks: '',
    })
    currentChainage += interval
  }

  // CT row
  const finalArcFromTC = ctChainage - tcChainage
  const finalDefRad = finalArcFromTC / radius
  const finalTotalDefDeg = finalDefRad * 180 / Math.PI
  const fdeg = Math.floor(finalTotalDefDeg)
  const fminFloat = (finalTotalDefDeg - fdeg) * 60
  const fmin = Math.floor(fminFloat)
  const fsec = (fminFloat - fmin) * 60
  const finalChord = 2 * radius * Math.sin(finalArcFromTC / (2 * radius))

  rows.push({
    peg: 'CT',
    chainage: ctChainage,
    chord: finalChord,
    deflectionAngle: `${fdeg}°${String(fmin).padStart(2, '0')}'${fsec.toFixed(1).padStart(4, '0')}"`,
    totalDeflection: `${fdeg}°${String(fmin).padStart(2, '0')}'${fsec.toFixed(1).padStart(4, '0')}"`,
    remarks: 'Curve/Tangent',
  })

  const expectedTotal = (delta / 2) * 180 / Math.PI
  const checkDiff = Math.abs(finalTotalDefDeg - expectedTotal)

  const totalChord = rows.reduce((s, r) => s + r.chord, 0)

  return {
    rows,
    totalChord,
    checkTotalDeflection: `${fdeg}°${String(fmin).padStart(2, '0')}'${fsec.toFixed(1).padStart(4, '0')}" (expected ${expectedTotal.toFixed(4)}°)`,
    arithmeticCheck: { passed: checkDiff < 0.01, diffDeg: checkDiff },
    steps,
  }
}

// ─── PART 3: VERTICAL CURVE DESIGN ────────────────────────────────────────────
// Source: RDM 1.3 Section 5.4
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 25

export interface VerticalCurveInput {
  g1: number     // incoming grade (%)
  g2: number     // outgoing grade (%)
  vpiChainage: number
  vpiRL: number
  curveLength?: number   // if not given, compute from K
  kValue?: number          // if not given, compute from L
  interval?: number        // RL table interval (m)
}

export interface VerticalCurveRow {
  chainage: number
  rl: number
  y: number
  x: number
  isBVC: boolean
  isEVC: boolean
  isPeak: boolean
  isSag: boolean
}

export interface VerticalCurveResult {
  A: number           // algebraic difference of grades
  L: number           // curve length
  K: number           // K value
  bvcChainage: number
  bvcRL: number
  evcChainage: number
  evcRL: number
  xPeak: number       // distance from BVC to peak/sag
  chainagePeak: number
  rlPeak: number
  isCrest: boolean    // negative A (g2<g1) = crest, positive A (g2>g1) = sag
  arithmeticCheck: { passed: boolean; diff: number }
  rows: VerticalCurveRow[]
  steps: Array<{ description: string; formula: string; value: string }>
}

export function verticalCurve(input: VerticalCurveInput): VerticalCurveResult {
  const { g1, g2, vpiChainage, vpiRL, curveLength, kValue, interval = 20 } = input

  // Source: RDM 1.3 Section 5.4 — algebraic grade difference
  const A = g2 - g1

  // Source: RDM 1.3 Section 5.4 — K and L relationship
  let L: number, K: number
  if (curveLength !== undefined && curveLength > 0) {
    L = curveLength
    K = L / Math.abs(A)
  } else if (kValue !== undefined && kValue > 0) {
    K = kValue
    L = K * Math.abs(A)
  } else {
    throw new Error('Provide either curveLength or kValue')
  }

  // Source: RDM 1.3 Section 5.4 — BVC/EVC chainages
  const bvcChainage = vpiChainage - L / 2
  const evcChainage = vpiChainage + L / 2

  // Source: RDM 1.3 Section 5.4 — BVC/EVC reduced levels
  const bvcRL = vpiRL - (g1 / 100) * (L / 2)
  const evcRL = vpiRL + (g2 / 100) * (L / 2)

  // Source: RDM 1.3 Section 5.4 — RL at any point: y = BVC_RL + (g1/100)x + (A/(200L))x²
  const rate = A / (200 * L)

  // Source: RDM 1.3 Section 5.4 — Peak/sag point
  const xPeak = -g1 * L / A  // distance from BVC
  const chainagePeak = bvcChainage + xPeak
  const rlPeak = bvcRL + (g1 / 100) * xPeak + rate * xPeak * xPeak
  const isCrest = A < 0

  // Arithmetic check: RL at EVC via formula must equal EVC_RL via grades
  const rlAtEVC = bvcRL + (g1 / 100) * L + rate * L * L
  const arithmeticCheck = { passed: Math.abs(rlAtEVC - evcRL) < 0.001, diff: rlAtEVC - evcRL }

  const steps = [
    { description: `A = G₂ - G₁`, formula: `${g2.toFixed(4)} - ${g1.toFixed(4)}`, value: `${A.toFixed(4)}%` },
    { description: `K = L / |A|`, formula: `${L.toFixed(4)} / ${Math.abs(A).toFixed(4)}`, value: `${K.toFixed(4)}` },
    { description: `L = K × |A|`, formula: `${K.toFixed(4)} × ${Math.abs(A).toFixed(4)}`, value: `${L.toFixed(4)} m` },
    { description: `BVC = VPI - L/2`, formula: `${vpiChainage.toFixed(4)} - ${(L/2).toFixed(4)}`, value: `${bvcChainage.toFixed(4)} m` },
    { description: `EVC = VPI + L/2`, formula: `${vpiChainage.toFixed(4)} + ${(L/2).toFixed(4)}`, value: `${evcChainage.toFixed(4)} m` },
    { description: `BVC RL = VPI RL - G₁×(L/2)/100`, formula: `${vpiRL.toFixed(4)} - ${g1.toFixed(4)}×${(L/2).toFixed(4)}/100`, value: `${bvcRL.toFixed(4)} m` },
    { description: `EVC RL = VPI RL + G₂×(L/2)/100`, formula: `${vpiRL.toFixed(4)} + ${g2.toFixed(4)}×${(L/2).toFixed(4)}/100`, value: `${evcRL.toFixed(4)} m` },
    { description: `[CHECK] RL at EVC via formula`, formula: `${rlAtEVC.toFixed(4)} vs ${evcRL.toFixed(4)}`, value: `${arithmeticCheck.passed ? 'PASS ' : 'FAIL [x]'} (diff=${arithmeticCheck.diff.toFixed(4)}m)` },
  ]

  if (A !== 0) {
    steps.push({
      description: `x_peak = -G₁×L/A (from BVC)`, formula: `-${g1.toFixed(4)}×${L.toFixed(4)}/${A.toFixed(4)}`,
      value: `${xPeak.toFixed(4)} m from BVC`,
    })
    steps.push({
      description: `Peak/Sag chainage`, formula: `${bvcChainage.toFixed(4)} + ${xPeak.toFixed(4)}`,
      value: `${chainagePeak.toFixed(4)} m`,
    })
    steps.push({
      description: `Peak/Sag RL`, formula: `${bvcRL.toFixed(4)} + ...`, value: `${rlPeak.toFixed(4)} m`,
    })
  }

  // Generate RL table
  const rows: VerticalCurveRow[] = []
  let ch = Math.floor(bvcChainage / interval) * interval
  while (ch <= evcChainage) {
    const x = ch - bvcChainage
    const y = bvcRL + (g1 / 100) * x + rate * x * x
    const rl = y
    rows.push({
      chainage: ch,
      rl,
      y,
      x,
      isBVC: Math.abs(ch - bvcChainage) < 0.001,
      isEVC: Math.abs(ch - evcChainage) < 0.001,
      isPeak: Math.abs(ch - chainagePeak) < interval / 2,
      isSag: Math.abs(ch - chainagePeak) < interval / 2,
    })
    ch += interval
  }

  return {
    A, L, K, bvcChainage, bvcRL, evcChainage, evcRL,
    xPeak, chainagePeak, rlPeak, isCrest,
    arithmeticCheck, rows, steps,
  }
}

// ─── PART 4: SUPERELEVATION DESIGN ──────────────────────────────────────────
// Source: RDM 1.3 Section 5.3

export interface SuperelevationInput {
  designSpeed: number     // km/h
  radius: number           // metres
  roadClass: string        // DR1-DR7
  numLanes: number
  laneWidth: number        // metres
}

export interface FrictionFactor {
  speed: number
  eMax: number
  f: number
}

export const FRICTION_FACTORS: FrictionFactor[] = [
  { speed: 30, eMax: 0.08, f: 0.35 },
  { speed: 40, eMax: 0.08, f: 0.35 },
  { speed: 50, eMax: 0.08, f: 0.35 },
  { speed: 60, eMax: 0.08, f: 0.34 },
  { speed: 70, eMax: 0.08, f: 0.33 },
  { speed: 80, eMax: 0.08, f: 0.32 },
  { speed: 90, eMax: 0.08, f: 0.31 },
  { speed: 100, eMax: 0.08, f: 0.30 },
  { speed: 110, eMax: 0.08, f: 0.29 },
  { speed: 120, eMax: 0.08, f: 0.28 },
]

export function getFrictionFactor(speed: number): FrictionFactor {
  let closest = FRICTION_FACTORS[0]
  let minDiff = Math.abs(speed - closest.speed)
  for (const f of FRICTION_FACTORS) {
    const diff = Math.abs(speed - f.speed)
    if (diff < minDiff) { minDiff = diff; closest = f }
  }
  return closest
}

export interface SuperelevationResult {
  requiredE: number
  designE: number
  isCapped: boolean
  transitionLength: number  // Ls = e × w × V / (3.6 × p)
  rateOfChange: number      // p = 1% per 2.4m (RDM 1.3)
  isCompliant: boolean
  steps: Array<{ description: string; formula: string; value: string }>
}

export function superelevationDesign(input: SuperelevationInput): SuperelevationResult {
  const { designSpeed, radius, numLanes, laneWidth } = input

  // Source: RDM 1.3 Section 5.3 — Maximum superelevation 8%
  const eMax = 0.08

  // Source: RDM 1.3 Table 3-4 — Friction factor by speed
  const ff = getFrictionFactor(designSpeed)

  // Source: RDM 1.3 Section 5.3 — Required superelevation
  // e = V² / (127R) - f
  // where V is in km/h, R in metres, result as decimal
  const V = designSpeed
  const requiredE = (V * V) / (127 * radius) - ff.f

  // Cap at maximum
  const designE = Math.min(Math.max(requiredE, 0), eMax)
  const isCapped = requiredE > eMax

  // Source: RDM 1.3 Section 5.3 — Transition length
  // p = 1% per 2.4m → rate of change of superelevation
  const p = 1 / 2.4  // % per metre
  const w = laneWidth * numLanes
  const transitionLength = (designE * w * V) / (3.6 * p)

  const steps = [
    { description: `Friction factor f (Table 3-4)`, formula: `For V=${V}km/h`, value: `f=${ff.f}` },
    { description: `Required e = V²/(127R) - f`, formula: `${V}²/(127×${radius}) - ${ff.f}`, value: `${(requiredE * 100).toFixed(4)}%` },
    { description: `Design superelevation (capped at ${eMax * 100}%)`, formula: `min(${requiredE.toFixed(6)}, ${eMax})`, value: `${(designE * 100).toFixed(4)}%${isCapped ? ' [CAPPED]' : ''}` },
    { description: `Rate of change p (RDM 1.3)`, formula: `1% per 2.4m`, value: `${p.toFixed(6)} %/m` },
    { description: `Transition Ls = e×w×V/(3.6×p)`, formula: `${designE.toFixed(6)}×${w.toFixed(2)}×${V}/${(3.6 * p).toFixed(4)}`, value: `${transitionLength.toFixed(4)} m` },
  ]

  return {
    requiredE, designE, isCapped,
    transitionLength,
    rateOfChange: p,
    isCompliant: !isCapped,
    steps,
  }
}

// ─── PART 5: SIGHT DISTANCE CHECK ─────────────────────────────────────────────
// Source: RDM 1.3 Section 3.3
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed.

export interface SightDistanceInput {
  designSpeed: number  // km/h
  roadClass: string
  terrain: string
  gradient: number  // % (positive = uphill, negative = downhill)
  proposedSSD?: number  // metres (optional — check against minimum)
}

export const SSD_TABLE: Array<{ speed: number; flat: number; rolling: number; mountainous: number }> = [
  { speed: 30, flat: 30, rolling: 30, mountainous: 30 },
  { speed: 40, flat: 40, rolling: 40, mountainous: 40 },
  { speed: 50, flat: 50, rolling: 50, mountainous: 50 },
  { speed: 60, flat: 60, rolling: 65, mountainous: 65 },
  { speed: 70, flat: 80, rolling: 85, mountainous: 90 },
  { speed: 80, flat: 100, rolling: 110, mountainous: 110 },
  { speed: 90, flat: 130, rolling: 140, mountainous: 140 },
  { speed: 100, flat: 160, rolling: 170, mountainous: 170 },
  { speed: 110, flat: 200, rolling: 210, mountainous: 210 },
  { speed: 120, flat: 250, rolling: 260, mountainous: 270 },
]

export const PSD_TABLE: Array<{ speed: number; flat: number; rolling: number; mountainous: number }> = [
  { speed: 50, flat: 180, rolling: 180, mountainous: 180 },
  { speed: 60, flat: 270, rolling: 270, mountainous: 270 },
  { speed: 70, flat: 360, rolling: 360, mountainous: 360 },
  { speed: 80, flat: 480, rolling: 480, mountainous: 480 },
  { speed: 90, flat: 600, rolling: 600, mountainous: 600 },
  { speed: 100, flat: 720, rolling: 720, mountainous: 720 },
  { speed: 110, flat: 875, rolling: 875, mountainous: 875 },
  { speed: 120, flat: 1030, rolling: 1030, mountainous: 1030 },
]

export interface SightDistanceResult {
  V: number
  ssdMin: number
  ssdComputed: number
  psdMin: number
  frictionFactor: number
  ssdGradeCorrection: number
  isSSDCompliant: boolean
  isPSDCompliant: boolean
  ssdStatus: 'GREEN' | 'RED'
  steps: Array<{ description: string; formula: string; value: string }>
}

export function sightDistanceCheck(input: SightDistanceInput): SightDistanceResult {
  const { designSpeed, terrain, gradient, proposedSSD } = input

  // Source: RDM 1.3 Table 3-4 — Friction factor
  const ff = getFrictionFactor(designSpeed)
  const f = ff.f

  // Source: RDM 1.3 Section 3.3 — SSD formula
  // SSD = V²/(254(f+g)) + V×t/3.6
  // where t = 2.5 seconds reaction time
  const V = designSpeed
  const g = gradient / 100  // convert % to decimal
  const t = 2.5  // seconds (RDM 1.3)
  const ssdFlat = (V * V) / (254 * f) + (V * t / 3.6)
  const ssdOnGrade = (V * V) / (254 * (f + g)) + (V * t / 3.6)
  const ssdComputed = g !== 0 ? ssdOnGrade : ssdFlat
  const ssdGradeCorrection = Math.abs(ssdOnGrade - ssdFlat)

  // Source: RDM 1.3 Table 3-5 — Minimum SSD by terrain
  let ssdMin = 30
  for (const row of SSD_TABLE) {
    if (row.speed === designSpeed) {
      ssdMin = row[terrain as 'flat' | 'rolling' | 'mountainous'] ?? row.flat
      break
    }
  }

  // Source: RDM 1.3 Table 3-6 — PSD (tabulated only — do not derive)
  let psdMin = 0
  for (const row of PSD_TABLE) {
    if (row.speed === designSpeed) {
      psdMin = row[terrain as 'flat' | 'rolling' | 'mountainous'] ?? row.flat
      break
    }
  }

  const isSSDCompliant = proposedSSD !== undefined ? proposedSSD >= ssdMin : ssdComputed >= ssdMin
  const isPSDCompliant = true  // PSD is tabulated, no computed comparison
  const ssdStatus = ssdComputed >= ssdMin ? 'GREEN' : 'RED'

  const steps = [
    { description: `Friction factor f (Table 3-4)`, formula: `For V=${V}km/h`, value: `f=${f}` },
    { description: `Reaction time t (RDM 1.3)`, formula: `t = 2.5 seconds`, value: `${t}s` },
    { description: `SSD on level (f=${f}): V²/(254f) + Vt/3.6`, formula: `${V}²/(254×${f}) + ${V}×${t}/3.6`, value: `${ssdFlat.toFixed(4)} m` },
    { description: `Grade correction (${gradient > 0 ? 'uphill' : 'downhill'} ${Math.abs(gradient)}%)`, formula: `g = ${g.toFixed(4)}`, value: `${ssdGradeCorrection.toFixed(4)} m additional` },
    { description: `SSD on grade`, formula: `${ssdFlat.toFixed(4)} + ${ssdGradeCorrection.toFixed(4)}`, value: `${ssdComputed.toFixed(4)} m` },
    { description: `Minimum SSD (Table 3-5, ${terrain})`, formula: `For V=${V}km/h, ${terrain} terrain`, value: `${ssdMin} m` },
    { description: `SSD Compliance`, formula: `${ssdComputed.toFixed(4)}m ${ssdComputed >= ssdMin ? '≥' : '<'} ${ssdMin}m`, value: `${ssdStatus} — ${ssdComputed >= ssdMin ? 'PASS' : 'FAIL'}` },
  ]

  if (proposedSSD !== undefined) {
    steps.push({
      description: `Proposed SSD vs Minimum`,
      formula: `${proposedSSD}m vs ${ssdMin}m`,
      value: `${proposedSSD >= ssdMin ? 'PASS' : 'FAIL'} (${proposedSSD >= ssdMin ? '≥' : '<'} ${ssdMin}m)`,
    })
  }

  steps.push({ description: `Minimum PSD (Table 3-6, ${terrain})`, formula: `Tabulated values only`, value: `${psdMin} m` })

  return {
    V, ssdMin, ssdComputed, psdMin,
    frictionFactor: f,
    ssdGradeCorrection,
    isSSDCompliant: ssdComputed >= ssdMin,
    isPSDCompliant: true,
    ssdStatus,
    steps,
  }
}

// ─── PART 6: MINIMUM RADIUS CHECK (RDM 1.3 Table 3-3) ────────────────────────
// Source: RDM 1.3 Table 3-3

export const MIN_RADIUS_TABLE: Array<{ speed: number; flat: number; rolling: number; mountainous: number; escarpment: number }> = [
  { speed: 120, flat: 665, rolling: 1000, mountainous: 1445, escarpment: 3600 },
  { speed: 110, flat: 530, rolling: 765, mountainous: 1070, escarpment: 2560 },
  { speed: 100, flat: 415, rolling: 570, mountainous: 770, escarpment: 1725 },
  { speed: 90, flat: 320, rolling: 420, mountainous: 545, escarpment: 1135 },
  { speed: 85, flat: 270, rolling: 350, mountainous: 445, escarpment: 890 },
  { speed: 80, flat: 240, rolling: 295, mountainous: 375, escarpment: 685 },
  { speed: 70, flat: 170, rolling: 205, mountainous: 250, escarpment: 415 },
  { speed: 65, flat: 140, rolling: 165, mountainous: 200, escarpment: 310 },
  { speed: 60, flat: 120, rolling: 140, mountainous: 170, escarpment: 250 },
  { speed: 50, flat: 80, rolling: 95, mountainous: 115, escarpment: 155 },
  { speed: 40, flat: 45, rolling: 55, mountainous: 65, escarpment: 80 },
  { speed: 30, flat: 24, rolling: 30, mountainous: 35, escarpment: 40 },
]

export function getMinRadius(speed: number, terrain: string): number {
  for (const row of MIN_RADIUS_TABLE) {
    if (row.speed === speed) {
      return row[terrain as 'flat' | 'rolling' | 'mountainous' | 'escarpment'] ?? row.flat
    }
  }
  return 0
}

export function checkRadiusCompliance(
  proposedRadius: number,
  designSpeed: number,
  terrain: string,
  superelevation: number = 0.08
): { compliant: boolean; minRadius: number; ratio: number; status: 'GREEN' | 'RED' } {
  const minRadius = getMinRadius(designSpeed, terrain)
  const compliant = proposedRadius >= minRadius
  const ratio = proposedRadius / minRadius
  return { compliant, minRadius, ratio, status: compliant ? 'GREEN' : 'RED' }
}

// METARDU Setting Out Engine
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 23
// Source: Schofield & Breach, Engineering Surveying 7th Ed., Chapter 9
// Source: RDM 1.1 Kenya 2025, Table 5.2

// ─── PART 1: DATA TYPES ──────────────────────────────────────────────────────

export interface InstrumentStation {
  e: number
  n: number
  rl: number
  ih: number
}

export interface Backsight {
  e: number
  n: number
}

export interface DesignPoint {
  id: string
  e: number
  n: number
  rl: number
  th: number
  description?: string
}

export interface SettingOutRow {
  id: string
  designE: number
  designN: number
  designRL: number
  HzAngle: string        // DMS string
  HzDecimal: number      // decimal degrees
  HD: number            // horizontal distance
  VA: string            // DMS string with sign
  VA_Rad: number       // radians
  SD: number            // slope distance
  TH: number            // target height
  heightDiff: number    // vertical difference
  steps: Array<{ description: string; formula: string; value: string }>
}

export interface SettingOutResult {
  instrumentStation: InstrumentStation
  backsight: Backsight
  bsBearing: string
  bsBearingDecimal: number
  rows: SettingOutRow[]
  totalPoints: number
}

// ─── PART 2: ANGLE/DISTANCE COMPUTATIONS ──────────────────────────────────────

function bearingToString(wcb: number): string {
  const d = Math.floor(wcb)
  const mFloat = (wcb - d) * 60
  const m = Math.floor(mFloat)
  const s = (mFloat - m) * 60
  return `${String(d).padStart(3, '0')}°${String(m).padStart(2, '0')}'${s.toFixed(1).padStart(4, '0')}"`
}

function arithToDMS(angle: number): { d: number; m: number; s: number } {
  const d = Math.floor(Math.abs(angle))
  const mFloat = (Math.abs(angle) - d) * 60
  const m = Math.floor(mFloat)
  const s = (mFloat - m) * 60
  return { d, m, s }
}

function angleDiff(a: number, b: number): number {
  let diff = a - b
  while (diff < 0) diff += 360
  while (diff >= 360) diff -= 360
  return diff
}

function inverseBearing(e1: number, n1: number, e2: number, n2: number): number {
  // Source: Ghilani & Wolf, Section 10.3
  const dE = e2 - e1
  const dN = n2 - n1
  const theta = Math.atan2(Math.abs(dE), Math.abs(dN)) * 180 / Math.PI
  if (dN >= 0 && dE >= 0) return theta
  if (dN < 0 && dE >= 0) return 180 - theta
  if (dN < 0 && dE < 0) return 180 + theta
  return 360 - theta
}

function horizontalAngle(fromBearing: number, toBearing: number): number {
  // Source: Ghilani & Wolf, Section 23
  let angle = toBearing - fromBearing
  if (angle < 0) angle += 360
  if (angle > 360) angle -= 360
  return angle
}

// ─── PART 3: SETTING OUT COMPUTATION ──────────────────────────────────────────

export function computeSettingOut(
  station: InstrumentStation,
  backsight: Backsight,
  points: DesignPoint[]
): SettingOutResult {
  // Source: Ghilani & Wolf, Section 23 — Station setup and orientation

  // Backsight bearing
  const bsBearingDecimal = inverseBearing(station.e, station.n, backsight.e, backsight.n)
  const bsBearing = bearingToString(bsBearingDecimal)

  const rows: SettingOutRow[] = []

  for (const pt of points) {
    // Bearing to point
    const bearingToPoint = inverseBearing(station.e, station.n, pt.e, pt.n)

    // Horizontal angle
    const HzDecimal = horizontalAngle(bsBearingDecimal, bearingToPoint)
    const { d, m, s } = arithToDMS(HzDecimal)
    const HzAngle = `${String(d).padStart(3, '0')}°${String(m).padStart(2, '0')}'${s.toFixed(1).padStart(4, '0')}"`
    // Format for display (no leading zeros on degrees for angles < 90)
    const HzDisplay = `${d}°${String(m).padStart(2, '0')}'${s.toFixed(1).padStart(4, '0')}"`

    // Horizontal distance
    const dE = pt.e - station.e
    const dN = pt.n - station.n
    const HD = Math.sqrt(dE * dE + dN * dN)

    // Vertical angle and slope distance
    // Source: Ghilani & Wolf, Section 23 — Vertical angle computation
    // height_diff = (RL_pt + TH) - (RL_station + IH)
    const heightDiff = (pt.rl + pt.th) - (station.rl + station.ih)
    const VA_Rad = Math.atan2(heightDiff, HD)
    const VA_Deg = VA_Rad * 180 / Math.PI
    const { d: vad, m: vam, s: vas } = arithToDMS(Math.abs(VA_Deg))
    const sign = heightDiff >= 0 ? '+' : '−'
    const VA = `${sign}${vad}°${String(vam).padStart(2, '0')}'${vas.toFixed(1).padStart(4, '0')}"`
    const VA_Display = `${sign}${vad}°${String(vam).padStart(2, '0')}'${vas.toFixed(1).padStart(4, '0')}"`

    // Slope distance
    const SD = HD / Math.cos(VA_Rad)

    const steps: SettingOutRow['steps'] = [
      {
        description: `ΔE = E₂ − E₁`,
        formula: `${pt.e.toFixed(3)} − ${station.e.toFixed(3)}`,
        value: `${dE.toFixed(4)} m`,
      },
      {
        description: `ΔN = N₂ − N₁`,
        formula: `${pt.n.toFixed(3)} − ${station.n.toFixed(3)}`,
        value: `${dN.toFixed(4)} m`,
      },
      {
        description: `Bearing to point`,
        formula: `tan⁻¹(ΔE/ΔN)`,
        value: bearingToString(bearingToPoint),
      },
      {
        description: `Hz angle = bearing_to_pt − BS_bearing`,
        formula: `${bearingToString(bearingToPoint)} − ${bsBearing}`,
        value: HzAngle,
      },
      {
        description: `HD = √(ΔE² + ΔN²)`,
        formula: `√(${dE.toFixed(4)}² + ${dN.toFixed(4)}²)`,
        value: `${HD.toFixed(3)} m`,
      },
      {
        description: `Height diff = (RL_p + TH) − (RL_s + IH)`,
        formula: `(${pt.rl.toFixed(3)} + ${pt.th}) − (${station.rl.toFixed(3)} + ${station.ih})`,
        value: `${heightDiff.toFixed(4)} m`,
      },
      {
        description: `VA = tan⁻¹(Δh / HD)`,
        formula: `tan⁻¹(${heightDiff.toFixed(4)} / ${HD.toFixed(3)})`,
        value: VA_Display,
      },
      {
        description: `SD = HD / cos(VA)`,
        formula: `${HD.toFixed(3)} / cos(${VA_Rad.toFixed(6)})`,
        value: `${SD.toFixed(3)} m`,
      },
    ]

    rows.push({
      id: pt.id,
      designE: pt.e,
      designN: pt.n,
      designRL: pt.rl,
      HzAngle: HzDisplay,
      HzDecimal,
      HD,
      VA: VA_Display,
      VA_Rad,
      SD,
      TH: pt.th,
      heightDiff,
      steps,
    })
  }

  return {
    instrumentStation: station,
    backsight,
    bsBearing,
    bsBearingDecimal,
    rows,
    totalPoints: points.length,
  }
}

// ─── PART 4: COORDINATE CHECK (RE-OBSERVATION) ───────────────────────────────
// Source: RDM 1.1 Kenya 2025, Table 5.2

export interface ReObservation {
  observedHz: number     // degrees decimal
  observedHD: number    // metres
  observedVA?: number   // degrees decimal (optional)
  observedSD?: number   // metres (optional)
  observedRL?: number   // metres (optional, if level observed)
}

export interface CoordinateCheckResult {
  pointId: string
  designE: number
  designN: number
  designRL: number
  computedE: number
  computedN: number
  computedRL: number | null
  deltaE: number
  deltaN: number
  deltaRL: number | null
  hAccuracy: 'GREEN' | 'RED'
  vAccuracy: 'GREEN' | 'RED'
  hTolerance: number
  vTolerance: number
  isCompliant: boolean
  messages: string[]
}

export function checkCoordinate(
  station: InstrumentStation,
  bsBearingDecimal: number,
  observation: ReObservation,
  designPoint: DesignPoint
): CoordinateCheckResult {
  // Source: RDM 1.1 Table 5.2
  // Construction survey tolerance: ±25mm horizontal, ±15mm vertical
  const hTolerance = 0.025  // ±25mm
  const vTolerance = 0.015  // ±15mm

  // Hz angle is the clockwise angle shown on the total station (0-360)
  // bearing_to_point = bs_bearing + Hz (mod 360)
  // Source: Ghilani & Wolf, Section 23
  let bearingToObserved = (bsBearingDecimal + observation.observedHz) % 360
  if (bearingToObserved < 0) bearingToObserved += 360
  const computedE = station.e + observation.observedHD * Math.sin(bearingToObserved * Math.PI / 180)
  const computedN = station.n + observation.observedHD * Math.cos(bearingToObserved * Math.PI / 180)

  let computedRL: number | null = null
  let deltaRL: number | null = null
  let vAccuracy: 'GREEN' | 'RED' = 'GREEN'
  let vMsg = ''

  if (observation.observedRL !== undefined) {
    computedRL = observation.observedRL
    deltaRL = Math.abs(observation.observedRL - designPoint.rl)
    vAccuracy = deltaRL <= vTolerance ? 'GREEN' : 'RED'
    vMsg = vAccuracy === 'GREEN'
      ? `RL within ±${(vTolerance * 1000).toFixed(0)}mm`
      : `Re-set level — RL error ${(deltaRL * 1000).toFixed(1)}mm exceeds ±${(vTolerance * 1000).toFixed(0)}mm`
  }

  const deltaE = Math.abs(computedE - designPoint.e)
  const deltaN = Math.abs(computedN - designPoint.n)
  const hAccuracy = deltaE <= hTolerance && deltaN <= hTolerance ? 'GREEN' : 'RED'
  const isCompliant = hAccuracy === 'GREEN' && (deltaRL === null || vAccuracy === 'GREEN')

  const messages: string[] = []
  if (hAccuracy === 'RED') {
    messages.push(`Re-set peg — position error E=${(deltaE * 1000).toFixed(1)}mm N=${(deltaN * 1000).toFixed(1)}mm exceeds ±${(hTolerance * 1000).toFixed(0)}mm`)
  } else {
    messages.push(`Position OK — E=${(deltaE * 1000).toFixed(1)}mm N=${(deltaN * 1000).toFixed(1)}mm within ±${(hTolerance * 1000).toFixed(0)}mm`)
  }
  if (deltaRL !== null) messages.push(vMsg)

  return {
    pointId: designPoint.id,
    designE: designPoint.e,
    designN: designPoint.n,
    designRL: designPoint.rl,
    computedE,
    computedN,
    computedRL,
    deltaE,
    deltaN,
    deltaRL,
    hAccuracy,
    vAccuracy,
    hTolerance,
    vTolerance,
    isCompliant,
    messages,
  }
}

// ─── PART 5: CHAINAGE AND OFFSET TABLE ────────────────────────────────────────
// Source: RDM 1.3 Kenya August 2023, Section 5.5.3

export interface ChainageOffsetRow {
  chainage: number
  chainageFmt: string
  clRL: number
  leftOffset: number
  rightOffset: number
  leftRL: number
  rightRL: number
  cutFillAtCL: string
  cutFillDepth: number
}

export interface ChainageOffsetInput {
  chainage: number
  formationRL: number
  groundRL: number
  halfCarriageway: number
  shoulderWidth: number
  catchLeftOffset?: number
  catchRightOffset?: number
}

export function computeChainageOffset(input: ChainageOffsetInput): ChainageOffsetRow {
  const { chainage, formationRL, groundRL, halfCarriageway, shoulderWidth } = input
  const km = Math.floor(chainage / 1000)
  const m = chainage % 1000
  const chainageFmt = km > 0 ? `${km}+${m.toFixed(3)}` : `${m.toFixed(3)}`

  const halfWidth = halfCarriageway + shoulderWidth
  const leftOffset = halfWidth
  const rightOffset = halfWidth
  const cutFillDepth = groundRL - formationRL
  const cutFillAtCL = cutFillDepth > 0.005
    ? `+${cutFillDepth.toFixed(3)} CUT`
    : cutFillDepth < -0.005
    ? `${cutFillDepth.toFixed(3)} FILL`
    : '0.000 LEVEL'

  return {
    chainage,
    chainageFmt,
    clRL: groundRL,
    leftOffset,
    rightOffset,
    leftRL: formationRL,
    rightRL: formationRL,
    cutFillAtCL,
    cutFillDepth,
  }
}

// ─── PART 6: CSV PARSER ───────────────────────────────────────────────────────

export function parseSettingOutCSV(csv: string): DesignPoint[] {
  const lines = csv.trim().split('\n')
  const points: DesignPoint[] = []

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (!line || line.toLowerCase().startsWith('point_id') || line.toLowerCase().startsWith('id')) continue
    const cols = line.split(',').map((c) => c.trim())
    if (cols.length < 4) continue
    const id = cols[0] || String(i + 1)
    const e = parseFloat(cols[1])
    const n = parseFloat(cols[2])
    const rl = parseFloat(cols[3])
    const th = cols[4] ? parseFloat(cols[4]) : 2.0
    const desc = cols[5] || ''
    if (isNaN(e) || isNaN(n) || isNaN(rl)) continue
    points.push({ id, e, n, rl, th, description: desc })
  }

  return points
}

// METARDU Traverse Computation Engine
// Source: N.N. Basak, Surveying and Levelling, Chapters 10-11
// Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapters 10, 12
// Source: RDM 1.1 Kenya 2025, Table 2.4 — Accuracy Classification
// Source: Survey Regulations 1994, Cap 299, Regulation 97

import { dmsToDecimal, bearingToString } from '@/lib/engine/angles'

function dmsStr(d: number, m: number, s: number): string {
  return `${String(Math.floor(Math.abs(d))).padStart(3,'0')}° ${String(Math.floor(Math.abs(m))).padStart(2,'0')}' ${Math.abs(s).toFixed(3)}"`
}

function angleDMS(angleDeg: number): string {
  const norm = ((angleDeg % 360) + 360) % 360
  const d = Math.floor(norm)
  const mFloat = (norm - d) * 60
  const m = Math.floor(mFloat)
  const s = (mFloat - m) * 60
  return `${String(d).padStart(3,'0')}° ${String(m).padStart(2,'0')}' ${s.toFixed(1)}"`
}

export interface RawObservation {
  station: string
  bs: string
  fs: string
  hclDeg: string
  hclMin: string
  hclSec: string
  hcrDeg: string
  hcrMin: string
  hcrSec: string
  slopeDist: string
  vaDeg: string
  vaMin: string
  vaSec: string
  ih: string
  th: string
  remarks?: string
}

export interface ReducedObservation {
  station: string
  hcl: number
  hcr: number
  meanAngle: number
  meanAngleDMS: string
  slopeDist: number
  verticalAngle: number
  verticalAngleRad: number
  horizontalDist: number
  deltaH: number
  ih: number
  th: number
  remarks?: string
}

export interface TraverseComputationLeg {
  from: string
  to: string
  meanAngle: number
  meanAngleDMS: string
  wcb: number
  wcbDMS: string
  sd: number
  hd: number
  departure: number
  latitude: number
  depCorrection: number
  latCorrection: number
  adjDep: number
  adjLat: number
}

export interface TraverseComputationResult {
  rawObservations: RawObservation[]
  observations: ReducedObservation[]
  legs: TraverseComputationLeg[]
  coordinates: Array<{ station: string; easting: number; northing: number; rl?: number }>
  totalPerimeter: number
  sumDepartures: number
  sumLatitudes: number
  linearError: number
  precisionRatio: number
  accuracyOrder: string
  C_mm: number
  K_km: number
  formula: string
  allowable: number
  openingPoint: { easting: number; northing: number; rl?: number }
  closingPoint?: { easting: number; northing: number }
  isClosed: boolean
}

export interface AccuracyClass {
  order: string
  C_mm: number
  K_km: number
  allowable: number
  formula: string
  pass: boolean
}

function classifyAccuracy(C_mm: number, K_km: number): AccuracyClass {
  // Source: RDM 1.1 Kenya 2025, Table 2.4 — Accuracy Classification
  // m = C/√K (mm/√km), where C = closing error in mm, K = perimeter in km
  // Source: Ghilani & Wolf, Chapter 12 — Traverse accuracy standards
  //
  // FIXED: Previous version computed m = C_mm/1000 (metres) but compared against
  // allowable values in mm — units mismatch made everything classify as 1st Order.
  // Now correctly computes m in mm/√km and compares against RDM 1.1 coefficients.
  const K = K_km
  const m = K > 0 ? C_mm / Math.sqrt(K) : 0  // mm/√km — the RDM 1.1 classification metric

  // Source: RDM 1.1 Table 2.4 — allowable m values in mm/√km for each order
  const allow1a = 0.5   // First Order Class I: m ≤ 0.5 mm/√km
  const allow1b = 0.7   // First Order Class II: m ≤ 0.7 mm/√km
  const allow2a = 1.0   // Second Order Class I: m ≤ 1.0 mm/√km
  const allow2b = 1.3   // Second Order Class II: m ≤ 1.3 mm/√km
  const allow3 = 2.0    // Third Order: m ≤ 2.0 mm/√km

  // The allowable closing error in mm = coefficient × √K
  let order: string
  let allowableCoeff: number
  if (m <= allow1a) {
    order = 'FIRST ORDER CLASS I'
    allowableCoeff = allow1a
  } else if (m <= allow1b) {
    order = 'FIRST ORDER CLASS II'
    allowableCoeff = allow1b
  } else if (m <= allow2a) {
    order = 'SECOND ORDER CLASS I'
    allowableCoeff = allow2a
  } else if (m <= allow2b) {
    order = 'SECOND ORDER CLASS II'
    allowableCoeff = allow2b
  } else if (m <= allow3) {
    order = 'THIRD ORDER'
    allowableCoeff = allow3
  } else {
    order = 'FOURTH ORDER'
    allowableCoeff = allow3
  }

  const allowableMm = allowableCoeff * Math.sqrt(K)  // allowable closing error in mm

  return {
    order,
    C_mm,
    K_km: K,
    allowable: allowableMm,
    formula: `m = ${m.toFixed(2)} mm/√km, C = ${C_mm.toFixed(2)} mm, K = ${K.toFixed(3)} km, Allowable C = ${allowableMm.toFixed(2)} mm (${allowableCoeff} mm/√km × √${K.toFixed(3)})`,
    pass: m <= allow3,
  }
}

export function computeTraverse(input: {
  openingEasting: number
  openingNorthing: number
  openingRL?: number
  openingStation: string
  closingEasting?: number
  closingNorthing?: number
  closingStation?: string
  observations: RawObservation[]
  backsightBearingDeg: number
  backsightBearingMin: number
  backsightBearingSec: number
}): TraverseComputationResult {
  const obs = input.observations.filter((o: any) => o.station && o.slopeDist)
  if (obs.length === 0) throw new Error('No valid observations')

  const reduced: ReducedObservation[] = obs.map((o: any) => {
    // Source: Basak, Chapter 10 — Mean angle from face-left and face-right horizontal circle readings
    // Source: Ghilani & Wolf, Chapter 12 — HCR_adj = HCR + 180° when HCR < 180°
    const hcl = dmsToDecimal({ degrees: parseInt(o.hclDeg) || 0, minutes: parseInt(o.hclMin) || 0, seconds: parseFloat(o.hclSec) || 0, direction: 'N' })
    const hcr = dmsToDecimal({ degrees: parseInt(o.hcrDeg) || 0, minutes: parseInt(o.hcrMin) || 0, seconds: parseFloat(o.hcrSec) || 0, direction: 'N' })
    let hcrAdj = hcr + 180
    if (hcrAdj >= 360) hcrAdj -= 360
    // Source: Basak, Eq. 10.2 — meanAngle = (HCL + HCR_adj) / 2
    const meanAngle = (hcl + hcrAdj) / 2
    const meanAngleNorm = meanAngle >= 360 ? meanAngle - 360 : meanAngle < 0 ? meanAngle + 360 : meanAngle

    const sd = parseFloat(o.slopeDist) || 0
    const vaDeg = parseFloat(o.vaDeg) || 0
    const vaMin = parseFloat(o.vaMin) || 0
    const vaSec = parseFloat(o.vaSec) || 0
    const va = dmsToDecimal({ degrees: vaDeg, minutes: vaMin, seconds: vaSec, direction: 'N' })
    const vaRad = va * Math.PI / 180
    // Source: Ghilani & Wolf, Eq. 13.1 — Horizontal Distance = SD × cos(zenith angle)
    // Source: Basak — HD from slope distance and vertical/zenith angle
    const hd = sd * Math.cos(vaRad)
    const ih = parseFloat(o.ih) || 0
    const th = parseFloat(o.th) || 0
    // Source: Ghilani & Wolf — ΔH = SD × sin(VA) + IH - TH
    const deltaH = sd * Math.sin(vaRad) + ih - th

    return {
      station: o.station,
      hcl,
      hcr,
      meanAngle: meanAngleNorm,
      meanAngleDMS: angleDMS(meanAngleNorm),
      slopeDist: sd,
      verticalAngle: va,
      verticalAngleRad: vaRad,
      horizontalDist: hd,
      deltaH,
      ih,
      th,
      remarks: o.remarks,
    }
  })

  const backsightRad = dmsToDecimal({
    degrees: input.backsightBearingDeg,
    minutes: input.backsightBearingMin,
    seconds: input.backsightBearingSec,
    direction: 'N',
  }) * Math.PI / 180

  const legs: TraverseComputationLeg[] = []
  let currentWCB = backsightRad
  const prevStation = obs[0]?.bs || input.openingStation
  let currentE = input.openingEasting
  let currentN = input.openingNorthing
  let currentRL = input.openingRL ?? 0

  const stations = [input.openingStation, ...obs.map((o: any) => o.station)]

  for (let i = 0; i < obs.length; i++) {
    // Source: Basak, Chapter 10 — WCB propagation using observed angles
    // WCB(forward) = back_bearing(previous line) + observed angle (clockwise from BS to FS)
    // back_bearing(x) = x + 180°
    // currentWCB is initialized as the backsight bearing (already a back bearing),
    // then after each iteration it is updated to the back bearing of the computed line.
    const angle = reduced[i].meanAngle * Math.PI / 180
    let wcb = currentWCB + angle
    if (wcb < 0) wcb += 2 * Math.PI
    if (wcb >= 2 * Math.PI) wcb -= 2 * Math.PI
    const wcbDeg = wcb * 180 / Math.PI
    const hd = reduced[i].horizontalDist
    // Source: Basak, Eq. 10.3 — Departure = HD × sin(WCB), Latitude = HD × cos(WCB)
    const dep = hd * Math.sin(wcb)
    const lat = hd * Math.cos(wcb)
    currentE += dep
    currentN += lat
    currentRL += reduced[i].deltaH

    legs.push({
      from: stations[i],
      to: stations[i + 1] || obs[i].fs || `T${i + 1}`,
      meanAngle: reduced[i].meanAngle,
      meanAngleDMS: reduced[i].meanAngleDMS,
      wcb: wcbDeg,
      wcbDMS: angleDMS(wcbDeg),
      sd: reduced[i].slopeDist,
      hd,
      departure: dep,
      latitude: lat,
      depCorrection: 0,
      latCorrection: 0,
      adjDep: dep,
      adjLat: lat,
    })

    // FIXED: Update currentWCB to the BACK BEARING of the line just computed.
    // Previous version set currentWCB = wcb (forward bearing), which caused all
    // subsequent WCBs to be wrong by 180°. The correct propagation requires:
    //   WCB_next = back_bearing(WCB_current) + angle_next
    // Source: Basak Ch.10, Ghilani & Wolf Ch.10
    currentWCB = wcb + Math.PI
    if (currentWCB >= 2 * Math.PI) currentWCB -= 2 * Math.PI
  }

  const closingE = input.closingEasting
  const closingN = input.closingNorthing
  const isClosed = closingE !== undefined && closingN !== undefined

  let sumDep = legs.reduce((s, l) => s + l.departure, 0)
  let sumLat = legs.reduce((s, l) => s + l.latitude, 0)

  let linearError = 0
  let precisionRatio = 0
  let C_mm = 0
  let K_km = 0

  if (isClosed && closingE !== undefined && closingN !== undefined) {
    const totalDist = legs.reduce((s, l) => s + l.hd, 0)

    // FIXED: Previous version added actualDep/actualLat to sumDep/sumLat before
    // computing corrections. This was WRONG — for a loop traverse (closing=opening),
    // it made sumDep=0, resulting in ZERO Bowditch adjustment despite misclosure.
    //
    // Correct approach (Source: Basak Ch.11, Ghilani & Wolf Ch.12):
    //   Misclosure in departure = Σdep − (Eclosing − Eopening)
    //   Misclosure in latitude  = Σlat − (Nclosing − Nopening)
    //   Bowditch correction_i = −(misclosure/ΣD) × D_i
    //
    // After correction, ΣadjDep = Eclosing − Eopening, ΣadjLat = Nclosing − Nopening
    const eDep = sumDep - (closingE - input.openingEasting)   // departure misclosure
    const eLat = sumLat - (closingN - input.openingNorthing)  // latitude misclosure
    linearError = Math.sqrt(eDep * eDep + eLat * eLat)
    K_km = totalDist / 1000
    precisionRatio = totalDist / Math.max(linearError, 1e-12)
    C_mm = linearError * 1000

    // Source: Ghilani & Wolf, Chapter 12 — Bowditch rule: correction_i = -(misclosure/ΣD) × D_i
    // Source: Basak, Chapter 11 — Bowditch correction proportional to leg distance
    for (const leg of legs) {
      leg.depCorrection = -(eDep * (leg.hd / totalDist))
      leg.latCorrection = -(eLat * (leg.hd / totalDist))
      leg.adjDep = leg.departure + leg.depCorrection
      leg.adjLat = leg.latitude + leg.latCorrection
    }

    // Verify: adjusted sums should now equal (closing − opening)
    sumDep = legs.reduce((s, l) => s + l.adjDep, 0)
    sumLat = legs.reduce((s, l) => s + l.adjLat, 0)
  }

  const coords: Array<{ station: string; easting: number; northing: number; rl?: number }> = [
    { station: input.openingStation, easting: input.openingEasting, northing: input.openingNorthing, rl: input.openingRL },
  ]

  let adjE = input.openingEasting
  let adjN = input.openingNorthing
  let adjRL = input.openingRL ?? 0

  for (let i = 0; i < legs.length; i++) {
    adjE += legs[i].adjDep
    adjN += legs[i].adjLat
    adjRL += reduced[i].deltaH
    coords.push({ station: legs[i].to, easting: adjE, northing: adjN, rl: adjRL })
  }

  const totalPerimeter = legs.reduce((s, l) => s + l.hd, 0)
  K_km = totalPerimeter / 1000
  if (isClosed) C_mm = linearError * 1000
  else C_mm = 0

  const accClass = classifyAccuracy(C_mm, K_km)

  return {
    rawObservations: obs,
    observations: reduced,
    legs,
    coordinates: coords,
    totalPerimeter,
    sumDepartures: sumDep,
    sumLatitudes: sumLat,
    linearError,
    precisionRatio,
    accuracyOrder: accClass.order,
    C_mm,
    K_km,
    formula: accClass.formula,
    allowable: accClass.allowable,
    openingPoint: { easting: input.openingEasting, northing: input.openingNorthing, rl: input.openingRL },
    closingPoint: isClosed ? { easting: closingE!, northing: closingN! } : undefined,
    isClosed,
  }
}

export function computeBowditchAdjustment(legs: TraverseComputationLeg[], closingE: number, closingN: number): void {
  const totalDist = legs.reduce((s, l) => s + l.hd, 0)
  if (totalDist === 0) return

  // Misclosure = closing point − computed endpoint
  // (closing point is known; sum of departures/latitudes is the computed endpoint offset from opening)
  const sumDep = legs.reduce((s, l) => s + l.departure, 0)
  const sumLat = legs.reduce((s, l) => s + l.latitude, 0)

  // Linear misclosure components
  // Source: Ghilani & Wolf, Chapter 12 — eE = Σdep − (Eclosing − Eopening)
  // Here closing coords are already offset from opening, so eE = sumDep − closingE
  // and eN = sumLat − closingN
  const eE = sumDep - closingE  // departure misclosure
  const eN = sumLat - closingN  // latitude misclosure

  // Source: Ghilani & Wolf — Bowditch correction: correction_i = −(misclosure/ΣD) × D_i
  for (const leg of legs) {
    leg.depCorrection = -(eE * (leg.hd / totalDist))
    leg.latCorrection = -(eN * (leg.hd / totalDist))
    leg.adjDep = leg.departure + leg.depCorrection
    leg.adjLat = leg.latitude + leg.latCorrection
  }
}

export interface LevelBookRow {
  station: string
  bs?: number
  is?: number
  fs?: number
  hi?: number
  rl?: number
  rise?: number
  fall?: number
  distance?: number
  remarks?: string
}

export interface LevelBookResult {
  rows: LevelBookRow[]
  method: 'rise_and_fall' | 'height_of_collimation'
  sumBS: number
  sumFS: number
  sumRise: number
  sumFall: number
  arithmeticCheck: number
  arithmeticPass: boolean
  misclosure: number
  allowableMisclosure: number
  isAcceptable: boolean
  openingRL: number
  closingRL?: number
  distanceKm: number
  formula: string
}

export function computeLevelBook(input: {
  openingRL: number
  closingRL?: number
  distanceKm: number
  method: 'rise_and_fall' | 'height_of_collimation'
  rows: Array<{ station: string; bs?: number; is?: number; fs?: number; distance?: number; remarks?: string }>
}): LevelBookResult {
  const { openingRL, closingRL, distanceKm, method, rows } = input
  const result: LevelBookRow[] = []

  let sumBS = 0, sumFS = 0, sumRise = 0, sumFall = 0
  let hi: number | null = null
  let currentRL = openingRL
  let lastBS: number | null = null

  for (const row of rows) {
    const out: LevelBookRow = { station: row.station, distance: row.distance, remarks: row.remarks }

    if (row.bs !== undefined && row.bs !== null) {
      out.bs = row.bs
      sumBS += row.bs
      hi = currentRL + row.bs
      out.hi = hi
      out.rl = hi
      lastBS = row.bs
    }

    if (row.is !== undefined && row.is !== null && hi !== null) {
      out.is = row.is
      const rl = hi - row.is
      out.rl = rl
      if (method === 'rise_and_fall') {
        const prevRL = result.length > 0 ? (result[result.length - 1].rl ?? currentRL) : currentRL
        // FIXED: Previous version had diff = prevRL - rl, which inverted rise/fall.
        // Convention: Rise = current RL > previous RL (ground goes UP)
        //             Fall = current RL < previous RL (ground goes DOWN)
        // Source: Basak, Chapter 5 — Rise and Fall method
        const diff = rl - prevRL
        if (diff >= 0) { out.rise = diff; sumRise += diff }
        else { out.fall = Math.abs(diff); sumFall += Math.abs(diff) }
      }
      currentRL = rl
    }

    if (row.fs !== undefined && row.fs !== null && hi !== null) {
      out.fs = row.fs
      sumFS += row.fs
      const rl = hi - row.fs
      out.rl = rl
      if (method === 'rise_and_fall') {
        const prevRL = result.length > 0 ? (result[result.length - 1].rl ?? currentRL) : currentRL
        // FIXED: Same rise/fall sign correction as IS case above
        const diff = rl - prevRL
        if (diff >= 0) { out.rise = diff; sumRise += diff }
        else { out.fall = Math.abs(diff); sumFall += Math.abs(diff) }
      }
      currentRL = rl
      hi = null
    }

    result.push(out)
  }

  const arithmeticCheck = (sumBS - sumFS) - (currentRL - openingRL)
  const arithmeticPass = Math.abs(arithmeticCheck) < 0.001

  const misclosure = closingRL !== undefined ? Math.abs(currentRL - closingRL) : 0
  const allowable = (10 * Math.sqrt(distanceKm)) / 1000 // Kenya RDM 1.1 Table 5.1: 10√K mm
  const isAcceptable = closingRL !== undefined ? misclosure <= allowable : true

  return {
    rows: result,
    method,
    sumBS,
    sumFS,
    sumRise,
    sumFall,
    arithmeticCheck,
    arithmeticPass,
    misclosure,
    allowableMisclosure: allowable,
    isAcceptable,
    openingRL,
    closingRL,
    distanceKm,
    formula: `Allowable = 10√K = 10√${distanceKm.toFixed(3)} = ${allowable.toFixed(3)} m (RDM 1.1 Table 5.1)`,
  }
}

// ============================================================
// METARDU — Beacon Description PDF Generator
// Official beacon description documents for Kenya's cadastral
// system under the Survey Act (Cap 299) and Survey
// Regulations L.N. 168/1994.
//
// A4 Portrait, 12 mm margins, navy government styling.
// No external table library required — manual jsPDF drawing.
//
// Usage:
//   import { generateBeaconDescriptionPdf } from './beaconDescriptionPdf'
//   const pdf = generateBeaconDescriptionPdf(data)
//   // pdf is a Uint8Array — send as response, save to disk, etc.
// ============================================================

import jsPDF from 'jspdf'

// ── Public interface ───────────────────────────────────────────

export interface BeaconDescriptionData {
  // Document metadata
  documentNumber: string        // e.g. "BD/2026/042"
  documentType: string          // e.g. "Beacon Description" or "Beacon Schedule"

  // Survey/Plan details
  planNumber: string            // e.g. "DP 123456"
  surveyDate: string
  surveyorName: string
  iskNumber: string             // ISK registration number
  firmName: string

  // Location
  county: string
  area: string                  // e.g. "Machakos Municipality"
  registrySection: string       // e.g. "Section II"
  parcelNumber: string          // e.g. "LR 123/456"

  // Datum/Projection
  datum: string                 // e.g. "Arc 1960"
  projection: string            // e.g. "UTM Zone 37S"

  // Beacons
  beacons: Array<{
    beaconNumber: string        // e.g. "A123" or "BM 1"
    description: string         // e.g. "Concrete pillar 0.3m x 0.3m at ground level"
    easting: number
    northing: number
    elevation?: number
    mark: string                // e.g. "CSM" (copper spike in mortar), "IP" (iron pipe)
    foundStatus: 'ORIGINAL' | 'FOUND' | 'NOT FOUND' | 'REPLACED' | 'NEW'
    Remarks: string
  }>

  // Certification
  checkedByName?: string
  checkedByTitle?: string
  checkedByDate?: string
}

// ── Page constants ─────────────────────────────────────────────

const PAGE_W = 210
const PAGE_H = 297
const MARGIN_L = 12
const MARGIN_R = 12
const MARGIN_T = 12
const MARGIN_B = 12
const CONTENT_W = PAGE_W - MARGIN_L - MARGIN_R  // 186 mm

// Colour palette
const NAVY: [number, number, number] = [27, 58, 92]
const LIGHT_GREY: [number, number, number] = [240, 242, 245]
const WHITE: [number, number, number] = [255, 255, 255]
const BLACK: [number, number, number] = [0, 0, 0]
const BORDER_GREY: [number, number, number] = [190, 195, 200]

// Status colour map (fill behind the status cell)
const STATUS_COLOURS: Record<string, [number, number, number]> = {
  ORIGINAL:   [200, 230, 201],   // green tint
  FOUND:      [187, 222, 251],   // blue tint
  'NOT FOUND': [255, 205, 210],  // red tint
  REPLACED:   [255, 224, 178],   // orange tint
  NEW:        [225, 190, 231],   // purple tint
}

// Beacon schedule column widths (sum = CONTENT_W = 186 mm)
const COL = {
  no:         8,
  beaconNo:   22,
  desc:       42,
  easting:    22,
  northing:   22,
  elevation:  16,
  mark:       14,
  status:     18,
  remarks:    22,
} as const
const COL_KEYS = Object.keys(COL) as (keyof typeof COL)[]
const COL_WIDTHS = COL_KEYS.map(k => COL[k])
const TOTAL_COL_W = COL_WIDTHS.reduce((a, b) => a + b, 0) // 186

// ── Main export ────────────────────────────────────────────────

export function generateBeaconDescriptionPdf(
  data: BeaconDescriptionData,
): Uint8Array {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
  })

  let y = 0

  // ── Helper: page footer ────────────────────────────────────
  function addFooter(pageNum: number, totalPages: number): void {
    const fy = PAGE_H - 7
    // Watermark
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(6.5)
    doc.setTextColor(140, 140, 140)
    doc.text(
      'BEACON DESCRIPTION \u2014 METARDU Generated',
      PAGE_W / 2,
      fy,
      { align: 'center' },
    )
    // Page number
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7)
    doc.setTextColor(100, 100, 100)
    doc.text(
      `Page ${pageNum} of ${totalPages}`,
      PAGE_W - MARGIN_R,
      fy,
      { align: 'right' },
    )
    doc.setTextColor(0, 0, 0)
  }

  // ── Helper: navy section header bar ────────────────────────
  function sectionBar(title: string): void {
    if (y > PAGE_H - MARGIN_B - 50) {
      doc.addPage()
      y = MARGIN_T + 4
    }
    doc.setFillColor(...NAVY)
    doc.rect(MARGIN_L, y, CONTENT_W, 7, 'F')
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.setTextColor(...WHITE)
    doc.text(title, MARGIN_L + 3, y + 5)
    doc.setTextColor(0, 0, 0)
    y += 10
  }

  // ── Helper: full-width horizontal rule ─────────────────────
  function rule(lineW = 0.3): void {
    doc.setDrawColor(...NAVY)
    doc.setLineWidth(lineW)
    doc.line(MARGIN_L, y, PAGE_W - MARGIN_R, y)
    doc.setDrawColor(0, 0, 0)
    doc.setLineWidth(0.2)
  }

  // ── Helper: 2-column label-value row ───────────────────────
  function kvRow(
    l1: string, v1: string,
    l2?: string, v2?: string,
  ): void {
    if (y > PAGE_H - MARGIN_B - 20) {
      doc.addPage()
      y = MARGIN_T + 4
    }
    const rowH = 7
    const colW = CONTENT_W / 2
    const labelW = colW * 0.42

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(7.5)

    // Left column
    doc.setFillColor(...LIGHT_GREY)
    doc.rect(MARGIN_L, y, labelW, rowH, 'F')
    doc.rect(MARGIN_L + labelW, y, colW - labelW, rowH, 'F')
    doc.text(l1, MARGIN_L + 2, y + 5)
    doc.setFont('helvetica', 'normal')
    doc.text(v1 || '\u2014', MARGIN_L + labelW + 2, y + 5)

    // Right column
    if (l2 !== undefined) {
      doc.setFillColor(...LIGHT_GREY)
      doc.rect(MARGIN_L + colW, y, labelW, rowH, 'F')
      doc.rect(MARGIN_L + colW + labelW, y, colW - labelW, rowH, 'F')
      doc.setFont('helvetica', 'bold')
      doc.text(l2, MARGIN_L + colW + 2, y + 5)
      doc.setFont('helvetica', 'normal')
      doc.text(v2 || '\u2014', MARGIN_L + colW + labelW + 2, y + 5)
    }

    // Borders
    doc.setDrawColor(...BORDER_GREY)
    doc.setLineWidth(0.15)
    doc.rect(MARGIN_L, y, CONTENT_W, rowH, 'S')
    doc.line(MARGIN_L + colW, y, MARGIN_L + colW, y + rowH)
    doc.line(MARGIN_L + labelW, y, MARGIN_L + labelW, y + rowH)
    if (l2 !== undefined) {
      doc.line(MARGIN_L + colW + labelW, y, MARGIN_L + colW + labelW, y + rowH)
    }
    doc.setDrawColor(0, 0, 0)
    doc.setLineWidth(0.2)

    y += rowH
  }

  // ════════════════════════════════════════════════════════════
  // 1. GOVERNMENT HEADER
  // ════════════════════════════════════════════════════════════

  y = MARGIN_T + 4

  // Coat of arms placeholder box
  const armsW = 18
  const armsH = 18
  const armsX = PAGE_W / 2 - armsW / 2
  doc.setDrawColor(...NAVY)
  doc.setLineWidth(0.35)
  doc.rect(armsX, y, armsW, armsH, 'S')
  doc.setFont('helvetica', 'italic')
  doc.setFontSize(5.5)
  doc.setTextColor(120, 120, 120)
  doc.text('COAT OF ARMS', PAGE_W / 2, y + armsH / 2 + 2, { align: 'center' })
  doc.setTextColor(0, 0, 0)
  y += armsH + 4

  // Government text
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(13)
  doc.text('REPUBLIC OF KENYA', PAGE_W / 2, y, { align: 'center' })
  y += 6.5

  doc.setFontSize(10.5)
  doc.text('MINISTRY OF LANDS AND PHYSICAL PLANNING', PAGE_W / 2, y, { align: 'center' })
  y += 6

  doc.setFontSize(10)
  doc.text('SURVEY OF KENYA', PAGE_W / 2, y, { align: 'center' })
  y += 7

  rule(0.5)
  y += 5

  // Document title bar
  const titleText = data.documentType.toUpperCase()
  doc.setFillColor(...NAVY)
  doc.rect(MARGIN_L, y, CONTENT_W, 11, 'F')
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(14)
  doc.setTextColor(...WHITE)
  doc.text(titleText, PAGE_W / 2, y + 8, { align: 'center' })
  doc.setTextColor(0, 0, 0)
  y += 14

  // Document reference line
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(8)
  doc.text(`Document No: ${data.documentNumber}`, MARGIN_L, y)
  doc.text(`Date: ${data.surveyDate}`, PAGE_W - MARGIN_R, y, { align: 'right' })
  y += 7

  rule(0.25)
  y += 5

  // ════════════════════════════════════════════════════════════
  // 2. PLAN / LOCATION DETAILS TABLE
  // ════════════════════════════════════════════════════════════

  sectionBar('PLAN AND LOCATION DETAILS')

  kvRow('Plan Number:', data.planNumber, 'Survey Date:', data.surveyDate)
  kvRow('Surveyor:', data.surveyorName, 'ISK Number:', data.iskNumber)
  kvRow('Firm:', data.firmName, 'County:', data.county)
  kvRow('Area:', data.area, 'Registry Section:', data.registrySection)
  kvRow('Parcel No:', data.parcelNumber, 'Datum:', data.datum)
  kvRow('Projection:', data.projection)

  y += 4

  // ════════════════════════════════════════════════════════════
  // 3. BEACON SCHEDULE TABLE
  // ════════════════════════════════════════════════════════════

  sectionBar('BEACON SCHEDULE')

  // Table dimensions
  const headerH = 7.5
  const rowH = 7
  const tableX = MARGIN_L
  const footerSpace = 52 // space reserved for summary + certification + page footer

  // Ensure we have room for at least the header + a few rows
  const minSpaceNeeded = headerH + rowH * 3 + footerSpace
  if (y + minSpaceNeeded > PAGE_H - MARGIN_B) {
    doc.addPage()
    y = MARGIN_T + 4
  }

  // ── Draw table header ─────────────────────────────────────
  doc.setFillColor(...NAVY)
  doc.rect(tableX, y, TOTAL_COL_W, headerH, 'F')

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(6.5)
  doc.setTextColor(...WHITE)

  const headers = ['No.', 'Beacon No.', 'Description', 'Easting', 'Northing', 'Elev.', 'Mark', 'Status', 'Remarks']
  let cx = tableX
  headers.forEach((h, i) => {
    doc.text(h, cx + 1.5, y + headerH - 2)
    cx += COL_WIDTHS[i]
  })
  doc.setTextColor(0, 0, 0)

  // Border around header
  doc.setDrawColor(0, 0, 0)
  doc.setLineWidth(0.25)
  doc.rect(tableX, y, TOTAL_COL_W, headerH, 'S')
  // Vertical lines in header
  cx = tableX
  for (let i = 0; i < COL_WIDTHS.length - 1; i++) {
    cx += COL_WIDTHS[i]
    doc.line(cx, y, cx, y + headerH)
  }
  y += headerH

  // ── Draw body rows with auto-page-break ───────────────────
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(6.5)

  data.beacons.forEach((beacon, idx) => {
    const num = String(idx + 1)
    const east = beacon.easting.toFixed(3)
    const north = beacon.northing.toFixed(3)
    const elev = beacon.elevation !== undefined ? beacon.elevation.toFixed(3) : '\u2014'

    // Truncate long description to fit cell (roughly 28 chars at 6.5pt in 42mm)
    const descText = beacon.description.length > 32
      ? beacon.description.substring(0, 30) + '..'
      : beacon.description

    const remarkText = beacon.Remarks.length > 18
      ? beacon.Remarks.substring(0, 16) + '..'
      : beacon.Remarks

    const cells = [
      num,
      beacon.beaconNumber,
      descText,
      east,
      north,
      elev,
      beacon.mark,
      beacon.foundStatus,
      remarkText,
    ]

    // Check if we need a new page
    if (y + rowH + footerSpace > PAGE_H - MARGIN_B) {
      // Bottom border of current page table fragment
      doc.setDrawColor(0, 0, 0)
      doc.setLineWidth(0.25)
      doc.line(tableX, y, tableX + TOTAL_COL_W, y)

      doc.addPage()
      y = MARGIN_T + 4

      // Redraw header on new page
      doc.setFillColor(...NAVY)
      doc.rect(tableX, y, TOTAL_COL_W, headerH, 'F')
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(6.5)
      doc.setTextColor(...WHITE)
      cx = tableX
      headers.forEach((h, i) => {
        doc.text(h, cx + 1.5, y + headerH - 2)
        cx += COL_WIDTHS[i]
      })
      doc.setTextColor(0, 0, 0)
      doc.setDrawColor(0, 0, 0)
      doc.setLineWidth(0.25)
      doc.rect(tableX, y, TOTAL_COL_W, headerH, 'S')
      cx = tableX
      for (let i = 0; i < COL_WIDTHS.length - 1; i++) {
        cx += COL_WIDTHS[i]
        doc.line(cx, y, cx, y + headerH)
      }
      y += headerH

      doc.setFont('helvetica', 'normal')
      doc.setFontSize(6.5)
    }

    const isAlternate = idx % 2 === 1

    // Alternating row background
    if (isAlternate) {
      doc.setFillColor(...LIGHT_GREY)
      doc.rect(tableX, y, TOTAL_COL_W, rowH, 'F')
    }

    // Status colour highlight
    const statusColour = STATUS_COLOURS[beacon.foundStatus]
    if (statusColour) {
      let statusX = tableX
      for (let c = 0; c < 7; c++) {
        statusX += COL_WIDTHS[c]
      }
      doc.setFillColor(...statusColour)
      doc.rect(statusX, y, COL.status, rowH, 'F')
    }

    // Cell text
    cx = tableX
    cells.forEach((cell, ci) => {
      const w = COL_WIDTHS[ci]
      // Right-align numeric columns
      if (ci === 3 || ci === 4 || ci === 5) {
        doc.text(cell, cx + w - 1.5, y + rowH - 2, { align: 'right' })
      } else if (ci === 0) {
        doc.text(cell, cx + w / 2, y + rowH - 2, { align: 'center' })
      } else {
        doc.text(cell, cx + 1.5, y + rowH - 2)
      }
      cx += w
    })

    // Row bottom line
    doc.setDrawColor(...BORDER_GREY)
    doc.setLineWidth(0.12)
    doc.line(tableX, y + rowH, tableX + TOTAL_COL_W, y + rowH)

    // Vertical lines
    cx = tableX
    for (let i = 0; i < COL_WIDTHS.length - 1; i++) {
      cx += COL_WIDTHS[i]
      doc.line(cx, y, cx, y + rowH)
    }
    doc.setDrawColor(0, 0, 0)
    doc.setLineWidth(0.2)

    y += rowH
  })

  // Final table border
  doc.setDrawColor(0, 0, 0)
  doc.setLineWidth(0.3)
  const tableH = headerH + data.beacons.length * rowH
  // We draw border around the entire table from the header start.
  // Since we track `y` incrementally, we capture the header start:
  // The header was drawn at y_before_header. Let's use a simpler approach:
  // Draw bottom border at current y, and left/right sides.
  doc.line(tableX, y, tableX + TOTAL_COL_W, y)  // bottom line
  doc.setLineWidth(0.2)

  // ════════════════════════════════════════════════════════════
  // 4. AREA SUMMARY
  // ════════════════════════════════════════════════════════════

  y += 6
  if (y + 28 > PAGE_H - MARGIN_B) {
    doc.addPage()
    y = MARGIN_T + 4
  }

  sectionBar('SUMMARY')

  // Count statuses
  const statusCounts: Record<string, number> = {}
  data.beacons.forEach(b => {
    const key = b.foundStatus
    statusCounts[key] = (statusCounts[key] || 0) + 1
  })

  doc.setFont('helvetica', 'normal')
  doc.setFontSize(7.5)

  const summaryLine1 = `Total Beacons: ${data.beacons.length}`
  doc.setFont('helvetica', 'bold')
  doc.text(summaryLine1, MARGIN_L + 2, y)
  y += 6

  // Status breakdown in two columns
  doc.setFont('helvetica', 'normal')
  const statuses = Object.entries(statusCounts)
  const half = Math.ceil(statuses.length / 2)
  let col1Y = y
  let col2Y = y

  statuses.forEach(([status, count], i) => {
    const col = i < half ? 0 : 1
    const colour = STATUS_COLOURS[status]
    const xPos = col === 0 ? MARGIN_L + 2 : MARGIN_L + CONTENT_W / 2 + 2
    const yPos = col === 0 ? col1Y : col2Y

    // Small colour swatch
    if (colour) {
      doc.setFillColor(...colour)
      doc.rect(xPos, yPos - 2.5, 3, 3, 'F')
    }
    doc.text(`${status}: ${count}`, xPos + 5, yPos)
    if (col === 0) col1Y += 5
    else col2Y += 5
  })

  y = Math.max(col1Y, col2Y) + 6

  // ════════════════════════════════════════════════════════════
  // 5. CERTIFICATION BLOCK
  // ════════════════════════════════════════════════════════════

  if (y + 42 > PAGE_H - MARGIN_B) {
    doc.addPage()
    y = MARGIN_T + 4
  }

  sectionBar('CERTIFICATION')

  // Certification text
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(7)
  const certLines = [
    'I certify that the above beacon descriptions are accurate and have been',
    'prepared in accordance with the Survey Act (Cap 299) and the Survey',
    'Regulations L.N. 168/1994. The coordinates are based on the datum and',
    'projection stated herein.',
  ]
  certLines.forEach((line: string) => {
    doc.text(line, MARGIN_L + 2, y)
    y += 4.5
  })
  y += 6

  // Surveyor signature block
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(7.5)
  doc.text('Licensed Surveyor:', MARGIN_L + 2, y)
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(7)
  doc.text(data.surveyorName || '________________________', MARGIN_L + 36, y)

  doc.setFont('helvetica', 'bold')
  doc.text('ISK No:', MARGIN_L + 100, y)
  doc.setFont('helvetica', 'normal')
  doc.text(data.iskNumber || '________________________', MARGIN_L + 118, y)
  y += 5

  // Signature line
  doc.setDrawColor(0, 0, 0)
  doc.setLineWidth(0.15)
  doc.line(MARGIN_L + 36, y + 1, MARGIN_L + 92, y + 1)
  doc.line(MARGIN_L + 118, y + 1, PAGE_W - MARGIN_R, y + 1)
  doc.setFont('helvetica', 'italic')
  doc.setFontSize(6)
  doc.text('Signature', MARGIN_L + 56, y + 3, { align: 'center' })
  y += 8

  // Checked by block (if provided)
  if (data.checkedByName) {
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(7.5)
    doc.text('Checked By:', MARGIN_L + 2, y)
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7)
    doc.text(data.checkedByName, MARGIN_L + 30, y)

    if (data.checkedByTitle) {
      doc.setFont('helvetica', 'bold')
      doc.text('Title:', MARGIN_L + 100, y)
      doc.setFont('helvetica', 'normal')
      doc.text(data.checkedByTitle, MARGIN_L + 114, y)
    }
    y += 5

    doc.setDrawColor(0, 0, 0)
    doc.setLineWidth(0.15)
    doc.line(MARGIN_L + 30, y + 1, MARGIN_L + 92, y + 1)
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(6)
    doc.text('Signature', MARGIN_L + 56, y + 3, { align: 'center' })

    if (data.checkedByDate) {
      doc.setFont('helvetica', 'bold')
      doc.setFontSize(7)
      doc.text('Date:', MARGIN_L + 100, y)
      doc.setFont('helvetica', 'normal')
      doc.text(data.checkedByDate, MARGIN_L + 114, y)
    }
    y += 10
  }

  // ════════════════════════════════════════════════════════════
  // 6. FOOTER — Page numbers + watermark on all pages
  // ════════════════════════════════════════════════════════════

  const totalPages = doc.getNumberOfPages()
  for (let p = 1; p <= totalPages; p++) {
    doc.setPage(p)
    addFooter(p, totalPages)
  }

  return doc.output('arraybuffer') as unknown as Uint8Array
}

import type { ValidateRequest, ValidateResponse, BoundaryPolygon } from '@/types/cadastra'

const BASE = process.env.NEXT_PUBLIC_URL || ''

export async function validateBoundary(
  projectId: string | null,
  boundary: BoundaryPolygon,
  options?: { include_satellite?: boolean; historical_comparison?: boolean }
): Promise<ValidateResponse> {
  // AUDIT FIX (2026-07-03): Accept null projectId for standalone validation.
  const res = await fetch(`${BASE}/api/ai/cadastra-validate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ project_id: projectId || '', boundary, options } as ValidateRequest)
  })
  
  if (!res.ok) {
    const error = await res.json().catch(() => ({ error: 'Unknown error' }))
    throw new Error(error.error || 'Failed to validate boundary')
  }
  
  return res.json()
}

// ============================================================
// METARDU — Cross-Section / Longitudinal Profile PDF Generator
// Professional A3 Landscape output for Kenya surveying
// Survey Act Cap 299, Survey Regulations L.N. 168/1994
//
// Generates longitudinal and cross-section profiles used in
// road design, canal construction, and terrain analysis.
//
// A3 Landscape (420 mm × 297 mm)
// No external charting library — uses jsPDF drawing primitives.
//
// Usage:
//   import { generateCrossSectionPdf, CrossSectionData } from './crossSectionPdf'
//   const pdf = generateCrossSectionPdf(data)
//   // pdf is a Uint8Array
// ============================================================

import jsPDF from 'jspdf'

// ============================================================
// EXPORTED INTERFACES
// ============================================================

export interface CrossSectionPoint {
  /** Distance along the alignment in metres */
  chainage: number
  /** Ground level in metres */
  elevation: number
  /** Design / formation level (for road profiles) */
  designLevel?: number
  /** Existing ground level (when different from elevation) */
  existingLevel?: number
}

export interface CrossSectionData {
  // ── Document metadata ──────────────────────────────────────
  documentNumber: string
  projectName: string
  projectNumber: string

  // ── Profile settings ──────────────────────────────────────
  profileType: 'LONGITUDINAL' | 'CROSS_SECTION'
  /** e.g. "Chainage 0+000 to 0+500 — Road A" */
  title: string

  // ── Scale ─────────────────────────────────────────────────
  /** e.g. 1:1000 */
  horizontalScale: number
  /** e.g. 1:100 */
  verticalScale: number
  /** computed as hScale / vScale, e.g. 10 */
  verticalExaggeration: number

  // ── Datum ─────────────────────────────────────────────────
  /** e.g. "MSL (Mean Sea Level)" */
  datum: string

  // ── Profile data ──────────────────────────────────────────
  points: CrossSectionPoint[]

  // ── Grid settings ─────────────────────────────────────────
  /** e.g. 50 (every 50 m) */
  majorGridInterval: number
  /** e.g. 10 */
  minorGridInterval: number
  /** 20m interval per RDM 1.1 Section 5.6.2 — set to 20 for road surveys */
  crossSectionInterval?: number

  // ── Surveyor info ─────────────────────────────────────────
  surveyorName: string
  iskNumber: string
  firmName: string
  surveyDate: string

  // ── Optional design parameters ────────────────────────────
  showDesignLevel?: boolean
  /** e.g. "Camber 2.5%, Super Elevation 3%" */
  designDescription?: string
  /** formation width in metres */
  formationWidth?: number

  // ── Notes ─────────────────────────────────────────────────
  notes?: string
}

// ============================================================
// INTERNAL TYPES & CONSTANTS
// ============================================================

type RGB = [number, number, number]

/** A3 landscape */
const PW = 420
const PH = 297

/** METARDU navy — matches CLA forms and other PDF generators */
const NAVY: RGB = [27, 58, 92]
const WHITE: RGB = [255, 255, 255]
const BLACK: RGB = [0, 0, 0]
const DKGRAY: RGB = [90, 90, 90]
const GRAY: RGB = [170, 170, 170]
const LTGRAY: RGB = [215, 215, 215]
const VLTGRAY: RGB = [240, 240, 240]

const GROUND_CLR: RGB = [0, 90, 30]
const DESIGN_CLR: RGB = [190, 15, 15]
const CUT_SHADE: RGB = [255, 205, 205]
const FILL_SHADE: RGB = [205, 222, 255]
const TBL_ALT: RGB = [243, 246, 250]
const BORDER: RGB = [195, 200, 208]

// ============================================================
// HELPER FUNCTIONS
// ============================================================

/** Format a chainage in metres as "0+000" (km+m padded). */
function fmtChainage(metres: number): string {
  const sign = metres < 0 ? '-' : ''
  const abs = Math.abs(metres)
  const km = Math.floor(abs / 1000)
  const rem = Math.round(abs % 1000)
  return `${sign}${km}+${String(rem).padStart(3, '0')}`
}

/** Return a "nice" round interval for grid lines. */
function niceInterval(range: number, targetLines = 6): number {
  if (range <= 0) return 1
  const rough = range / targetLines
  const mag = Math.pow(10, Math.floor(Math.log10(rough)))
  const res = rough / mag
  const n = res <= 1.5 ? 1 : res <= 3.5 ? 2 : res <= 7.5 ? 5 : 10
  return n * mag
}

/** Grade (%) between two consecutive survey points. */
function gradeBetween(
  a: CrossSectionPoint,
  b: CrossSectionPoint,
): number {
  const d = b.chainage - a.chainage
  if (d === 0) return 0
  return ((b.elevation - a.elevation) / d) * 100
}

/** Decimal precision for elevation labels based on grid interval. */
function elevPrecision(interval: number): number {
  if (interval < 0.5) return 2
  if (interval < 5) return 1
  return 0
}

// ============================================================
// DRAWING AREA LAYOUT
// ============================================================

interface DrawingArea {
  /** Left edge (mm) — space for elevation labels */
  l: number
  /** Top edge (mm) */
  t: number
  /** Width (mm) */
  w: number
  /** Height (mm) */
  h: number
}

// ============================================================
// MAIN EXPORT
// ============================================================

export function generateCrossSectionPdf(
  data: CrossSectionData,
): Uint8Array {
  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3',
  })

  // ── 1. Process & sort data ───────────────────────────────
  const pts = [...data.points].sort((a, b) => a.chainage - b.chainage)

  if (pts.length === 0) {
    doc.setFontSize(12)
    doc.setFont('helvetica', 'italic')
    doc.text(
      'No survey data provided.',
      PW / 2,
      PH / 2,
      { align: 'center' },
    )
    return doc.output('arraybuffer') as unknown as Uint8Array
  }

  const cMin = pts[0].chainage
  const cMax = pts[pts.length - 1].chainage
  const cRange = Math.max(cMax - cMin, 1)

  // Gather every elevation value (ground + design + existing) for range
  const allElevs = pts.flatMap(
    (p) =>
      [p.elevation, p.designLevel, p.existingLevel].filter(
        (v): v is number => v != null,
      ),
  )
  const eMin = Math.min(...allElevs)
  const eMax = Math.max(...allElevs)
  const eRange = Math.max(eMax - eMin, 0.1)

  // Add 12 % vertical padding
  const ePad = Math.max(eRange * 0.12, 0.5)
  const eEffMin = eMin - ePad
  const eEffMax = eMax + ePad
  const eEffRange = eEffMax - eEffMin

  // ── 2. Drawing area geometry ─────────────────────────────
  const DA: DrawingArea = { l: 38, t: 46, w: 335, h: 120 }
  const DA_B = DA.t + DA.h

  // ── 3. Coordinate mapping ────────────────────────────────
  const cToX = (c: number): number =>
    DA.l + ((c - cMin) / cRange) * DA.w
  const eToY = (e: number): number =>
    DA_B - ((e - eEffMin) / eEffRange) * DA.h

  // ── 4. Grid intervals ────────────────────────────────────
  const cMajor = data.majorGridInterval
  const cMinor = data.minorGridInterval
  const eMajInt = niceInterval(eEffRange, 6)
  const eMinInt = eMajInt / 5

  // ==========================================================
  // HEADER BLOCK
  // ==========================================================
  drawHeader(doc, data)

  // ==========================================================
  // MINOR GRID
  // ==========================================================
  drawMinorGrid(doc, DA, cToX, eToY, cMin, cMax, eEffMin, eEffMax, cMajor, cMinor, eMajInt, eMinInt)

  // ==========================================================
  // MAJOR GRID
  // ==========================================================
  drawMajorGrid(doc, DA, cToX, eToY, cMin, cMax, eEffMin, eEffMax, cMajor, cMinor, eMajInt, eMinInt)

  // ==========================================================
  // DRAWING AREA BORDER
  // ==========================================================
  doc.setDrawColor(...BLACK)
  doc.setLineWidth(0.5)
  doc.rect(DA.l, DA.t, DA.w, DA.h)

  // ==========================================================
  // AXIS TITLES
  // ==========================================================
  drawAxisTitles(doc, DA)

  // ==========================================================
  // CUT / FILL SHADING (drawn BEFORE lines so lines sit on top)
  // ==========================================================
  if (data.showDesignLevel) {
    drawCutFillShading(doc, pts, cToX, eToY)
  }

  // ==========================================================
  // GROUND PROFILE LINE
  // ==========================================================
  drawGroundProfile(doc, pts, cToX, eToY)

  // ==========================================================
  // DESIGN LINE
  // ==========================================================
  if (data.showDesignLevel) {
    drawDesignLine(doc, pts, cToX, eToY)
  }

  // ==========================================================
  // SURVEY POINT MARKERS
  // ==========================================================
  drawSurveyMarkers(doc, pts, cToX, eToY)

  // ==========================================================
  // KEY ELEVATION LABELS
  // ==========================================================
  drawKeyLabels(doc, pts, cToX, eToY)

  // ==========================================================
  // LEGEND
  // ==========================================================
  if (data.showDesignLevel) {
    drawLegend(doc, DA)
  }

  // ==========================================================
  // LEVEL TABLE
  // ==========================================================
  const tblX = DA.l
  const tblW = DA.w
  const colW = tblW / 5
  const tblStartY = DA_B + 12
  const tblHeadH = 7
  const tblRowH = 5.2

  // How many rows fit on page 1 before summary / cert / footer?
  const fixedBlock = 42 // summary + cert + footer + gaps
  const maxRowsP1 = Math.max(
    1,
    Math.floor((PH - tblStartY - tblHeadH - fixedBlock) / tblRowH),
  )
  const showRowsP1 = Math.min(pts.length, maxRowsP1)
  const needMorePages = pts.length > showRowsP1

  drawTableHeader(doc, tblX, tblStartY, colW, tblHeadH)
  drawTableRows(
    doc,
    pts,
    data,
    tblX,
    tblStartY + tblHeadH,
    colW,
    tblRowH,
    0,
    showRowsP1,
  )
  drawTableBorder(
    doc,
    tblX,
    tblStartY,
    colW,
    tblHeadH,
    showRowsP1,
    tblRowH,
  )

  if (needMorePages) {
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(5.5)
    doc.setTextColor(...DKGRAY)
    doc.text(
      `\u2026 ${pts.length - showRowsP1} more row(s) on subsequent page(s)`,
      tblX + tblW,
      tblStartY + tblHeadH + showRowsP1 * tblRowH + 3,
      { align: 'right' },
    )
  }

  // ==========================================================
  // CONTINUATION PAGES (table only)
  // ==========================================================
  let contPageNum = 2
  let remIdx = showRowsP1
  while (remIdx < pts.length) {
    doc.addPage([PW, PH], 'landscape')
    const contHeaderY = 10

    // Mini header bar
    doc.setFillColor(...NAVY)
    doc.rect(0, 0, PW, 16, 'F')
    doc.setTextColor(...WHITE)
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8)
    doc.text(
      `${data.title} \u2014 Level Table (continued)`,
      PW / 2,
      7,
      { align: 'center' },
    )
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(6)
    doc.text(`Page ${contPageNum}`, PW - 12, 7, { align: 'right' })

    const contTableY = 20
    const contMaxRows = Math.floor((PH - contTableY - 20) / tblRowH)
    const contRows = Math.min(contMaxRows, pts.length - remIdx)

    drawTableHeader(doc, tblX, contTableY, colW, tblHeadH)
    drawTableRows(
      doc,
      pts,
      data,
      tblX,
      contTableY + tblHeadH,
      colW,
      tblRowH,
      remIdx,
      contRows,
    )
    drawTableBorder(
      doc,
      tblX,
      contTableY,
      colW,
      tblHeadH,
      contRows,
      tblRowH,
    )

    // Footer on continuation page
    doc.setFontSize(5.5)
    doc.setTextColor(...GRAY)
    doc.setFont('helvetica', 'italic')
    doc.text(
      'Generated by METARDU',
      PW / 2,
      PH - 5,
      { align: 'center' },
    )

    remIdx += contRows
    contPageNum++
  }

  // ==========================================================
  // SUMMARY STATISTICS (on page 1)
  // ==========================================================
  doc.setPage(1)
  const sumY =
    tblStartY + tblHeadH + showRowsP1 * tblRowH + (needMorePages ? 6 : 3)
  drawSummary(doc, data, pts, sumY, tblX, tblW)

  // ==========================================================
  // CERTIFICATION BLOCK (on page 1)
  // ==========================================================
  const certY = sumY + 22
  drawCertification(doc, data, certY, tblX, tblW)

  // ==========================================================
  // NOTES (if provided)
  // ==========================================================
  if (data.notes) {
    const notesY = certY + 28
    if (notesY < PH - 12) {
      doc.setFont('helvetica', 'italic')
      doc.setFontSize(6)
      doc.setTextColor(...DKGRAY)
      doc.text(`Notes: ${data.notes}`, tblX + 3, notesY)
    }
  }

  // ==========================================================
  // FOOTER — page numbers + watermark on every page
  // ==========================================================
  const totalPages = doc.getNumberOfPages()
  for (let p = 1; p <= totalPages; p++) {
    doc.setPage(p)

    const fy = PH - 8

    // Separator line
    doc.setDrawColor(...GRAY)
    doc.setLineWidth(0.2)
    doc.line(10, fy - 1.5, PW - 10, fy - 1.5)

    // Watermark
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(6)
    doc.setTextColor(150, 150, 150)
    doc.text(
      'Generated by METARDU \u2014 Land Surveying Platform',
      PW / 2,
      fy + 1.5,
      { align: 'center' },
    )

    // Page number
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7)
    doc.setTextColor(...DKGRAY)
    doc.text(`Page ${p} of ${totalPages}`, PW - 12, fy + 1.5, {
      align: 'right',
    })
  }

  // Reset state
  doc.setTextColor(0, 0, 0)

  return doc.output('arraybuffer') as unknown as Uint8Array
}

// ============================================================
// DRAWING SUB-ROUTINES
// ============================================================

// ────────────────────────────────────────────────────────────
// HEADER
// ────────────────────────────────────────────────────────────

function drawHeader(doc: jsPDF, data: CrossSectionData): void {
  // Navy background bar
  doc.setFillColor(...NAVY)
  doc.rect(0, 0, PW, 40, 'F')

  // Title line
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(11)
  doc.setTextColor(...WHITE)
  doc.text(
    'REPUBLIC OF KENYA \u2014 MINISTRY OF LANDS, HOUSING & URBAN DEVELOPMENT',
    PW / 2,
    8,
    { align: 'center' },
  )

  // Thin rule
  doc.setDrawColor(...WHITE)
  doc.setLineWidth(0.25)
  doc.line(10, 11, PW - 10, 11)

  // Project info row 1
  doc.setFontSize(7.5)
  doc.setFont('helvetica', 'normal')
  doc.text(`Project: ${data.projectName}`, 12, 16)
  doc.text(`Doc#: ${data.documentNumber}`, PW - 12, 16, { align: 'right' })

  // Project info row 2
  doc.text(`Project No: ${data.projectNumber}`, 12, 21)
  doc.text(`Date: ${data.surveyDate}`, PW - 12, 21, { align: 'right' })

  // Profile title (centred, bold)
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(10)
  doc.text(data.title, PW / 2, 27, { align: 'center' })

  // Scale / datum line
  doc.setFontSize(7)
  doc.setFont('helvetica', 'normal')
  const scaleLine = [
    `H: 1:${data.horizontalScale}`,
    `V: 1:${data.verticalScale}`,
    `V.Exag: ${data.verticalExaggeration}\u00d7`,
    `Datum: ${data.datum}`,
    `Type: ${data.profileType.replace('_', ' ')}`,
  ].join('    |    ')
  doc.text(scaleLine, PW / 2, 33, { align: 'center' })

  // Design description (if any)
  if (data.designDescription) {
    doc.setFontSize(6.5)
    doc.setFont('helvetica', 'italic')
    doc.text(`Design: ${data.designDescription}`, PW / 2, 37, {
      align: 'center',
    })
  }
}

// ────────────────────────────────────────────────────────────
// MINOR GRID (dashed, lighter)
// ────────────────────────────────────────────────────────────

function drawMinorGrid(
  doc: jsPDF,
  DA: DrawingArea,
  cToX: (c: number) => number,
  eToY: (e: number) => number,
  cMin: number,
  cMax: number,
  eEffMin: number,
  eEffMax: number,
  cMajor: number,
  cMinor: number,
  eMajInt: number,
  eMinInt: number,
): void {
  doc.setDrawColor(...LTGRAY)
  doc.setLineWidth(0.08)

  // Chainage minor grid (skip lines that coincide with major)
  let cStart = Math.ceil(cMin / cMinor) * cMinor
  for (let c = cStart; c <= cMax; c += cMinor) {
    if (cMajor > 0 && Math.abs(c % cMajor) < 0.001) continue
    const x = cToX(c)
    if (x < DA.l || x > DA.l + DA.w) continue
    doc.line(x, DA.t, x, DA.t + DA.h)
  }

  // Elevation minor grid
  let eStart = Math.ceil(eEffMin / eMinInt) * eMinInt
  for (let e = eStart; e <= eEffMax; e += eMinInt) {
    if (eMajInt > 0 && Math.abs(e % eMajInt) < 0.0001) continue
    const y = eToY(e)
    if (y < DA.t || y > DA.t + DA.h) continue
    doc.line(DA.l, y, DA.l + DA.w, y)
  }
}

// ────────────────────────────────────────────────────────────
// MAJOR GRID (solid, darker)
// ────────────────────────────────────────────────────────────

function drawMajorGrid(
  doc: jsPDF,
  DA: DrawingArea,
  cToX: (c: number) => number,
  eToY: (e: number) => number,
  cMin: number,
  cMax: number,
  eEffMin: number,
  eEffMax: number,
  cMajor: number,
  cMinor: number,
  eMajInt: number,
  eMinInt: number,
): void {
  doc.setDrawColor(...GRAY)
  doc.setLineWidth(0.2)

  const prec = elevPrecision(eMajInt)

  // Chainage major grid + labels
  let cStart = Math.ceil(cMin / cMajor) * cMajor
  for (let c = cStart; c <= cMax; c += cMajor) {
    const x = cToX(c)
    if (x < DA.l || x > DA.l + DA.w) continue
    doc.line(x, DA.t, x, DA.t + DA.h)

    // Tick mark below drawing area
    doc.setDrawColor(...BLACK)
    doc.setLineWidth(0.2)
    doc.line(x, DA.t + DA.h, x, DA.t + DA.h + 2)

    // Label
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(6)
    doc.setTextColor(...DKGRAY)
    doc.text(fmtChainage(c), x, DA.t + DA.h + 4, { align: 'center' })

    // Minor ticks between major
    doc.setDrawColor(...LTGRAY)
    doc.setLineWidth(0.1)
    const minorCount = cMajor / cMinor
    for (let m = 1; m < minorCount; m++) {
      const mc = c + m * cMinor
      const mx = cToX(mc)
      if (mx >= DA.l && mx <= DA.l + DA.w) {
        doc.line(mx, DA.t + DA.h, mx, DA.t + DA.h + 1)
      }
    }
  }

  // Elevation major grid + labels
  doc.setDrawColor(...GRAY)
  doc.setLineWidth(0.2)
  let eStart = Math.ceil(eEffMin / eMajInt) * eMajInt
  for (let e = eStart; e <= eEffMax; e += eMajInt) {
    const y = eToY(e)
    if (y < DA.t || y > DA.t + DA.h) continue
    doc.line(DA.l, y, DA.l + DA.w, y)

    // Tick mark to the left of drawing area
    doc.setDrawColor(...BLACK)
    doc.setLineWidth(0.2)
    doc.line(DA.l - 2, y, DA.l, y)

    // Label
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(6)
    doc.setTextColor(...DKGRAY)
    doc.text(e.toFixed(prec), DA.l - 3, y + 2, { align: 'right' })

    // Minor ticks
    doc.setDrawColor(...LTGRAY)
    doc.setLineWidth(0.1)
    for (let m = 1; m < 5; m++) {
      const me = e + m * eMinInt
      const my = eToY(me)
      if (my >= DA.t && my <= DA.t + DA.h) {
        doc.line(DA.l - 1, my, DA.l, my)
      }
    }
  }
}

// ────────────────────────────────────────────────────────────
// AXIS TITLES
// ────────────────────────────────────────────────────────────

function drawAxisTitles(doc: jsPDF, DA: DrawingArea): void {
