// Migration script for indexes
export async function applyRecommendedIndexes(): Promise<{ applied: string[]; skipped: string[] }> {
  const dbClient = createClient()
  const applied: string[] = []
  const skipped: string[] = []
  
  for (const [table, indexes] of Object.entries(recommendedIndexes)) {
    for (const sql of indexes) {
      try {
        await dbClient.rpc('execute_sql', { sql })
        applied.push(sql)
      } catch (error) {
        skipped.push(sql)
        console.error(`[DB] Failed to apply index: ${sql}`, error)
      }
    }
  }

  return { applied, skipped }
}

/** Named export for the recommended indexes (returns the static object) */
export function getRecommendedIndexes() {
  return recommendedIndexes
}

/** Get slow queries from the optimizer stats */
export async function getSlowQueries(): Promise<{ query: string; avgDuration: number; count: number }[]> {
  const stats = dbOptimizer.getQueryStats()
  return Object.entries(stats)
    .filter(([, s]) => s.avg > SLOW_QUERY_THRESHOLD)
    .map(([query, s]) => ({ query, avgDuration: s.avg, count: s.count }))
}

// Export singleton
export const dbOptimizer = new DatabaseOptimizer()
export default dbOptimizer

/**
 * Pagination utility for API routes.
 * Standardizes limit/offset pagination across all list endpoints.
 *
 * Usage in an apiHandler route:
 *   const { limit, offset, page } = parsePagination(req.url)
 *   const { rows } = await db.query('SELECT * FROM parcels LIMIT $1 OFFSET $2', [limit, offset])
 *   const { rows: countRows } = await db.query('SELECT COUNT(*) FROM parcels')
 *   return NextResponse.json(paginateResponse(rows, countRows[0].count, limit, offset))
 */

export interface PaginationParams {
  limit: number
  offset: number
  page: number
}

export interface PaginatedResponse<T> {
  data: T[]
  pagination: {
    total: number
    page: number
    limit: number
    offset: number
    totalPages: number
    hasNextPage: boolean
    hasPrevPage: boolean
  }
}

const DEFAULT_LIMIT = 50
const MAX_LIMIT = 500

/**
 * Parse pagination parameters from a URL's search params.
 * Supports: ?limit=20&page=2 or ?limit=20&offset=40
 */
export function parsePagination(url: string): PaginationParams {
  const { searchParams } = new URL(url)

  let limit = Math.min(
    Math.max(parseInt(searchParams.get('limit') || String(DEFAULT_LIMIT)), 1),
    MAX_LIMIT
  )

  const pageParam = parseInt(searchParams.get('page') || '0')
  const offsetParam = parseInt(searchParams.get('offset') || '0')

  let offset: number
  let page: number

  if (pageParam > 0) {
    // Page-based: page=2 with limit=20 → offset=20
    page = pageParam
    offset = (page - 1) * limit
  } else {
    // Offset-based: offset=40 with limit=20
    offset = Math.max(offsetParam, 0)
    page = Math.floor(offset / limit) + 1
  }

  return { limit, offset, page }
}

/**
 * Build a standardized paginated response
 */
export function paginateResponse<T>(
  data: T[],
  total: number | string,
  limit: number,
  offset: number
): PaginatedResponse<T> {
  const totalNum = typeof total === 'string' ? parseInt(total) : total
  const totalPages = Math.ceil(totalNum / limit)
  const currentPage = Math.floor(offset / limit) + 1

  return {
    data,
    pagination: {
      total: totalNum,
      page: currentPage,
      limit,
      offset,
      totalPages,
      hasNextPage: currentPage < totalPages,
      hasPrevPage: currentPage > 1,
    },
  }
}

/**
 * SQL LIMIT/OFFSET clause values for parameterized queries
 */
export function paginationSql(limit: number, offset: number): [number, number] {
  return [limit, offset]
}

/**
 * Audit Trail Database Queries
 *
 * Every survey operation must be logged for legal compliance.
 * This creates an immutable record of all computations and corrections.
 *
 * AUDIT FIX (H1, 2026-07-02): Rewrote from Prisma client to raw SQL.
 *
 * T1.9 FIX (2026-07-09): Fixed silent failure — the INSERT referenced columns
 * `entity_type`, `entity_id`, `user_name`, `changes` which DON'T EXIST in the
 * actual `audit_logs` table (migration 000_canonical_schema.sql:521). The real
 * columns are `table_name`, `record_id`, `details`. The catch block was silently
 * swallowing the Postgres error, so 4 admin routes believed they were audited
 * when nothing was being written. Now uses the correct column names.
 *
 * Real schema:
 *   CREATE TABLE audit_logs (
 *     id            UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
 *     action        VARCHAR(255),
 *     table_name    VARCHAR(255),
 *     record_id     UUID,
 *     user_id       UUID REFERENCES users(id),
 *     details       JSONB,
 *     ip_address    VARCHAR(45),
 *     created_at    TIMESTAMPTZ DEFAULT NOW()
 *   );
 */

import { db } from '@/lib/db'

export interface CreateAuditEntry {
  entityType: string
  entityId: string
  action: string
  userId: string
  userName: string
  changes?: string
}

export interface AuditLogRow {
  id: string
  action: string | null
  table_name: string | null
  record_id: string | null
  user_id: string | null
  details: Record<string, unknown> | null
  ip_address: string | null
  created_at: string
}

/**
 * Create an audit log entry.
 * This is fire-and-forget — it should never block the main operation.
 *
 * T1.9: `userName` is stored inside `details` JSONB (no dedicated column).
 * `entityType` → `table_name`, `entityId` → `record_id`, `changes` → `details`.
 */
export async function createAuditLog(entry: CreateAuditEntry): Promise<AuditLogRow | null> {
  try {
    // Build details JSONB — stores userName + changes since there's no
    // dedicated column for them in the real schema.
    const details: Record<string, unknown> = {
      user_name: entry.userName,
    }
    if (entry.changes) {
      try {
        details.changes = JSON.parse(entry.changes)
      } catch {
        details.changes = entry.changes // store as string if not valid JSON
      }
    }

    const { rows } = await db.query(
      `INSERT INTO audit_logs (action, table_name, record_id, user_id, details)
       VALUES ($1, $2, $3, $4, $5)
       RETURNING id, action, table_name, record_id, user_id, details, ip_address, created_at`,
      [
        entry.action,
        entry.entityType,
        entry.entityId, // UUID — will fail if not a valid UUID, caught below
        entry.userId,
        JSON.stringify(details),
      ]
    )
    return rows[0] as AuditLogRow
  } catch (error) {
    // Audit logging should never fail the main operation — but it MUST be
    // visible when it fails so we can fix it. Log with full context.
    console.error('[audit] createAuditLog FAILED (silent swallow was the old behavior):', {
      error: error instanceof Error ? error.message : String(error),
      entityType: entry.entityType,
      entityId: entry.entityId,
      action: entry.action,
      userId: entry.userId,
    })
    return null
  }
}

/**
 * Get audit trail for an entity.
 */
export async function getAuditTrail(
  entityType: string,
  entityId: string
): Promise<AuditLogRow[]> {
  const { rows } = await db.query(
    `SELECT id, action, table_name, record_id, user_id, details, ip_address, created_at
     FROM audit_logs
     WHERE table_name = $1 AND record_id = $2
     ORDER BY created_at DESC`,
    [entityType, entityId]
  )
  return rows as AuditLogRow[]
}

/**
 * Get recent audit entries for a user.
 */
export async function getRecentAuditEntries(
  userId: string,
  limit: number = 50
): Promise<AuditLogRow[]> {
  const { rows } = await db.query(
    `SELECT id, action, table_name, record_id, user_id, details, ip_address, created_at
     FROM audit_logs
     WHERE user_id = $1
     ORDER BY created_at DESC
     LIMIT $2`,
    [userId, limit]
  )
  return rows as AuditLogRow[]
}

/**
 * Observation Database Queries
 *
 * Handles observation CRUD and batch operations for offline-to-server sync.
 *
 * AUDIT FIX (H1, 2026-07-02): Rewrote from Prisma client to raw SQL.
 * The Prisma schema declared an `observations` table that doesn't exist
 * in the actual database. The real tables are `traverse_observations`
 * (linked to `parcel_traverses`) and `level_observations`. This module
 * now uses the actual schema via the `db` Pool singleton.
 *
 * NOTE: The "surveyId" parameter in the input types historically referred
 * to a Prisma `Survey` model that doesn't exist in the SQL schema. In
 * practice, the sync route passes a project ID. We now treat `surveyId`
 * as `projectId` and insert into `traverse_observations` with the
 * `traverse_id` resolved from the project's most recent traverse (or
 * created on demand). This is a transitional design — a proper refactor
 * would change the input type to `projectId` + `traverseId` explicitly.
 */

import { db } from '@/lib/db'
import { computationCache, CacheKeys } from '../../cache/memory-cache'

// ─── Types ───────────────────────────────────────────────────────

export interface CreateObservationInput {
  /** Project ID (historically called surveyId) */
  surveyId: string
  fromStationId: string
  toStationId: string
  rawHorizontalAngle?: number
  rawVerticalAngle?: number
  rawSlopeDistance?: number
  edmConstant?: number
  ppmSetting?: number
  temperature?: number
  pressure?: number
  humidity?: number
  instrumentHeight?: number
  targetHeight?: number
  observationDate?: Date
}

export interface BatchObservationInput {
  surveyId: string
  observations: CreateObservationInput[]
}

export interface ObservationRow {
  id: string
  traverse_id: string
  station_from: string | null
  station_to: string | null
  bearing: number | null
  distance: number | null
  face: string | null
  created_at: string
}

// ─── Queries ─────────────────────────────────────────────────────

/**
 * Get all observations for a survey/project.
 * Resolves the project's most recent traverse and returns its observations.
 */
export async function getObservations(surveyId: string): Promise<ObservationRow[]> {
  const result = await computationCache.getOrCompute(
    CacheKeys.surveyObservations(surveyId),
    async () => {
      // Find the most recent traverse for this project
      const traverseResult = await db.query(
        `SELECT id FROM parcel_traverses
         WHERE project_id = $1
         ORDER BY created_at DESC
         LIMIT 1`,
        [surveyId]
      )
      if (traverseResult.rows.length === 0) return [] as ObservationRow[]

      const traverseId = traverseResult.rows[0].id
      const { rows } = await db.query(
        `SELECT id, traverse_id, station_from, station_to, bearing, distance, face, created_at
         FROM traverse_observations
         WHERE traverse_id = $1
         ORDER BY created_at ASC`,
        [traverseId]
      )
      return rows as ObservationRow[]
    },
    10 * 60 * 1000
  )
  return result as ObservationRow[]
}

/**
 * Create a single observation.
 */
export async function createObservation(input: CreateObservationInput): Promise<ObservationRow> {
  computationCache.invalidate(CacheKeys.surveyObservations(input.surveyId))

  // Resolve or create a traverse for this project
  const traverseId = await resolveOrCreateTraverse(input.surveyId)

  const { rows } = await db.query(
    `INSERT INTO traverse_observations
       (traverse_id, station_from, station_to, bearing, distance, face)
     VALUES ($1, $2, $3, $4, $5, $6)
     RETURNING id, traverse_id, station_from, station_to, bearing, distance, face, created_at`,
    [
      traverseId,
      input.fromStationId,
      input.toStationId,
      input.rawHorizontalAngle ?? null,
      input.rawSlopeDistance ?? null,
      null, // face — not in the input type yet; default null
    ]
  )
  return rows[0] as ObservationRow
}

/**
 * Batch create observations (for offline sync).
 *
 * This is the primary way observations are created — surveyors collect
 * data offline and sync in one batch. Uses a single multi-row INSERT
 * for efficiency.
 */
export async function batchCreateObservations(
  input: BatchObservationInput
): Promise<{ count: number }> {
  computationCache.invalidate(CacheKeys.surveyObservations(input.surveyId))

  if (input.observations.length === 0) return { count: 0 }

  // Resolve or create a traverse for this project
  const traverseId = await resolveOrCreateTraverse(input.surveyId)

  // Build a multi-row INSERT with parameterised values
  const values: unknown[] = []
  const placeholders: string[] = []
  let paramIdx = 1
  for (const obs of input.observations) {
    placeholders.push(
      `($${paramIdx}, $${paramIdx + 1}, $${paramIdx + 2}, $${paramIdx + 3}, $${paramIdx + 4})`
    )
    values.push(
      traverseId,
      obs.fromStationId,
      obs.toStationId,
      obs.rawHorizontalAngle ?? null,
      obs.rawSlopeDistance ?? null
    )
    paramIdx += 5
  }

  const result = await db.query(
    `INSERT INTO traverse_observations
       (traverse_id, station_from, station_to, bearing, distance)
     VALUES ${placeholders.join(', ')}
     RETURNING id`,
    values
  )

  return { count: result.rowCount ?? 0 }
}

/**
 * Resolve the most recent traverse for a project, or create one if none exists.
 * Used by batch sync when a project has no traverse yet.
 */
async function resolveOrCreateTraverse(projectId: string): Promise<string> {
  const existing = await db.query(
    `SELECT id FROM parcel_traverses
     WHERE project_id = $1
     ORDER BY created_at DESC
     LIMIT 1`,
    [projectId]
  )
  if (existing.rows.length > 0) return existing.rows[0].id as string

  // Create a new traverse record
  const created = await db.query(
    `INSERT INTO parcel_traverses (project_id, name)
     VALUES ($1, 'Synced observations')
     RETURNING id`,
    [projectId]
  )
  return created.rows[0].id as string
}

/**
 * Update corrected values on an observation.
 * Called after the correction pipeline processes the observation.
 *
 * NOTE: The `traverse_observations` table only has `bearing` and `distance`
 * columns (no corrected_* columns). This function updates those in place.
 * A proper audit trail would store both raw and corrected values — that's
 * a schema change for a future migration.
 */
export async function updateCorrectedValues(
  id: string,
  corrected: {
    correctedDistance?: number
    correctedHd?: number
    correctedVd?: number
    correctedBearing?: number
    correctionsLog?: string
    stdDevDistance?: number
    stdDevAngle?: number
  }
): Promise<void> {
  const updates: string[] = []
  const values: unknown[] = []
  let paramIdx = 1

  if (corrected.correctedBearing !== undefined) {
    updates.push(`bearing = $${paramIdx++}`)
    values.push(corrected.correctedBearing)
  }
  if (corrected.correctedDistance !== undefined || corrected.correctedHd !== undefined) {
    updates.push(`distance = $${paramIdx++}`)
    values.push(corrected.correctedDistance ?? corrected.correctedHd)
  }

  if (updates.length === 0) return

  values.push(id)
  await db.query(
    `UPDATE traverse_observations SET ${updates.join(', ')} WHERE id = $${paramIdx}`,
    values
  )
}

/**
 * Delete all observations for a survey/project.
 */
export async function deleteObservationsBySurvey(surveyId: string): Promise<void> {
  computationCache.invalidate(CacheKeys.surveyObservations(surveyId))

  // Delete via the traverse_id FK
  await db.query(
    `DELETE FROM traverse_observations
     WHERE traverse_id IN (
       SELECT id FROM parcel_traverses WHERE project_id = $1
     )`,
    [surveyId]
  )
}

/**
 * Project Database Queries
 *
 * All project-related database operations with cache integration.
 *
 * AUDIT FIX (H1, 2026-07-02): Rewrote from Prisma client to raw SQL.
 * The Prisma schema declared a `Project` model with camelCase fields
 * (surveyorLicense, surveyType, etc.) that don't exist in the actual
 * `projects` table (which uses snake_case: no surveyor_license column,
 * survey_type as VARCHAR, user_id as the owner FK). Now uses the real
 * schema. Surveyor info comes from the `users` + `surveyor_profiles`
 * tables, not from project columns.
 */

import { db } from '@/lib/db'
import { projectCache, CacheKeys } from '../../cache/memory-cache'

// ─── Types ───────────────────────────────────────────────────────

export interface CreateProjectInput {
  name: string
  description?: string
  surveyType?: string
  surveyOrder?: number
  county?: string
  subCounty?: string
  lrNumber?: string
  datum?: string
  projection?: string
  zone?: number
  surveyorName: string
  surveyorLicense: string
}

// ─── Queries ─────────────────────────────────────────────────────

/**
 * Get a project by ID (with caching).
 */
export async function getProject(id: string) {
  return projectCache.getOrCompute(
    CacheKeys.project(id),
    async () => {
      const { rows } = await db.query(
        `SELECT p.*,
                u.full_name AS owner_name,
                u.email AS owner_email,
                sp.firm_name,
                sp.license_number AS surveyor_license
         FROM projects p
         LEFT JOIN users u ON u.id = p.user_id
         LEFT JOIN surveyor_profiles sp ON sp.user_id = p.user_id
         WHERE p.id = $1`,
        [id]
      )
      return rows[0] ?? null
    },
    5 * 60 * 1000 // 5 min TTL
  )
}

/**
 * List projects for a surveyor (with caching).
 *
 * NOTE: The Prisma version filtered by `surveyorLicense` on the project
 * row. The real schema has no such column — projects are owned by a
 * user (user_id FK), and the surveyor's license is on surveyor_profiles.
 * This version joins through user_id → surveyor_profiles.license_number.
 */
export async function listProjects(
  surveyorLicense: string,
  page: number = 1,
  pageSize: number = 20
) {
  return projectCache.getOrCompute(
    CacheKeys.projectList(surveyorLicense, page),
    async () => {
      const offset = (page - 1) * pageSize
      const [projectsResult, countResult] = await Promise.all([
        db.query(
          `SELECT p.*, u.full_name AS owner_name
           FROM projects p
           JOIN surveyor_profiles sp ON sp.user_id = p.user_id
           LEFT JOIN users u ON u.id = p.user_id
           WHERE sp.license_number = $1
           ORDER BY p.updated_at DESC
           LIMIT $2 OFFSET $3`,
          [surveyorLicense, pageSize, offset]
        ),
        db.query(
          `SELECT COUNT(*)::INTEGER AS total
           FROM projects p
           JOIN surveyor_profiles sp ON sp.user_id = p.user_id
           WHERE sp.license_number = $1`,
          [surveyorLicense]
        ),
      ])
      return {
        projects: projectsResult.rows,
        total: countResult.rows[0]?.total ?? 0,
        page,
        pageSize,
      }
    },
    2 * 60 * 1000 // 2 min TTL
  )
}

/**
 * Create a new project.
 *
 * NOTE: The input type includes surveyorName + surveyorLicense for
 * backward compat with callers, but the real `projects` table has no
 * such columns. We resolve the user_id from surveyor_profiles.license_number
 * and store the project under that user. If no matching surveyor is
 * found, the project is created without an owner (user_id = NULL) and
 * a warning is logged.
 */
export async function createProject(input: CreateProjectInput) {
  // Resolve user_id from surveyor license
  const surveyorResult = await db.query(
    `SELECT user_id FROM surveyor_profiles WHERE license_number = $1`,
    [input.surveyorLicense]
  )
  const userId = surveyorResult.rows[0]?.user_id ?? null

  if (!userId) {
    console.warn(
      `[createProject] No surveyor found with license "${input.surveyorLicense}". ` +
        `Project will be created without an owner.`
    )
  }

  const { rows } = await db.query(
    `INSERT INTO projects
       (name, survey_type, client_name, lr_number, locality,
        utm_zone, hemisphere, datum, user_id)
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
     RETURNING *`,
    [
      input.name,
      input.surveyType ?? 'CADASTRAL',
      input.surveyorName, // stored in client_name (closest column)
      input.lrNumber ?? null,
      input.county ?? null,
      input.zone ?? 37,
      'S',
      input.datum ?? 'Arc 1960',
      userId,
    ]
  )

  // Invalidate project list cache
  projectCache.invalidatePattern(`projects:${input.surveyorLicense}:`)

  return rows[0]
}

/**
 * Update a project.
 */
export async function updateProject(
  id: string,
  data: Partial<CreateProjectInput> & { status?: string }
) {
  const updates: string[] = []
  const values: unknown[] = []
  let paramIdx = 1

  // Map input fields to actual columns
  if (data.name !== undefined) {
    updates.push(`name = $${paramIdx++}`)
    values.push(data.name)
  }
  if (data.surveyType !== undefined) {
    updates.push(`survey_type = $${paramIdx++}`)
    values.push(data.surveyType)
  }
  if (data.lrNumber !== undefined) {
    updates.push(`lr_number = $${paramIdx++}`)
    values.push(data.lrNumber)
  }
  if (data.county !== undefined) {
    updates.push(`locality = $${paramIdx++}`)
    values.push(data.county)
  }
  if (data.zone !== undefined) {
    updates.push(`utm_zone = $${paramIdx++}`)
    values.push(data.zone)
  }
  if (data.datum !== undefined) {
    updates.push(`datum = $${paramIdx++}`)
    values.push(data.datum)
  }

  if (updates.length === 0) {
    // Nothing to update — return current row
    const { rows } = await db.query(`SELECT * FROM projects WHERE id = $1`, [id])
    return rows[0] ?? null
  }

  updates.push(`updated_at = NOW()`)
  values.push(id)

  const { rows } = await db.query(
    `UPDATE projects SET ${updates.join(', ')} WHERE id = $${paramIdx} RETURNING *`,
    values
  )

  // Invalidate cache
  projectCache.invalidate(CacheKeys.project(id))

  return rows[0] ?? null
}

/**
 * Delete a project and all related data.
 */
export async function deleteProject(id: string) {
  const { rows } = await db.query(
    `DELETE FROM projects WHERE id = $1 RETURNING user_id`,
    [id]
  )

  if (rows.length > 0) {
    // Invalidate cache
    projectCache.invalidate(CacheKeys.project(id))
    // We don't have surveyorLicense here; invalidate all project list caches
    projectCache.invalidatePattern(`projects:`)
  }

  return rows[0] ?? null
}

/**
 * PostgreSQL Query Builder — DbClient-Compatible API
 *
 * Drop-in replacement for the legacy DbClient's `.from().select().eq()` chain.
 * Uses the existing `pg` Pool from db.ts for direct PostgreSQL queries.
 * Returns { data, error, count } matching the legacy response shape.
 *
 * ponytail: Phase 6 — replaced 43 `any` types with `unknown`, proper FilterOp
 * union, and typed generics. No behavior change.
 */

import { Pool } from 'pg'

// ponytail: Phase 6 Batch 3 — flipped default to Record<string, unknown> for
// type safety. Consumer files now cast explicitly via `as unknown as Type`.
// This surfaces previously-hidden type assumptions (real bugs fixed in this batch).
export interface QueryResult<T = Record<string, unknown>> {
  data: T | null
  error: { message: string; code: string; details?: string } | null
  count?: number | null
}

// ponytail: explicit FilterOp union — was string + `as any` casts
type FilterOp = '=' | '!=' | '>' | '>=' | '<' | '<=' | 'LIKE' | 'ILIKE' | 'IN' | 'NOT_IN' | 'IS' | 'IS NOT' | '@>'

interface Filter {
  column: string
  op: FilterOp
  value: unknown
}

interface OrderClause {
  column: string
  ascending: boolean
}

// ponytail: Phase 6 Batch 3 — see QueryResult note above
export class QueryBuilder<T = Record<string, unknown>> {
  private pool: Pool
  private table: string
  private operation: 'select' | 'insert' | 'update' | 'delete' | 'upsert' = 'select'
  private selectColumns: string = '*'
  private filters: Filter[] = []
  private orFilters: string[] = []
  private orderClauses: OrderClause[] = []
  private limitCount: number | null = null
  private offsetCount: number | null = null
  private singleRow: boolean = false
  private maybeSingleRow: boolean = false
  private countOnly: boolean = false
  private headOnly: boolean = false
  // ponytail: payload shapes are Record<string, unknown> — builder doesn't need to know column types
  private insertPayload: Record<string, unknown> | Record<string, unknown>[] | null = null
  private updatePayload: Record<string, unknown> | null = null
  private upsertConflict: string = 'id'
  private returningColumns: string = '*'

  /**
   * Validate a SQL identifier (column or table name) against a strict
   * allowlist pattern. Prevents SQL injection via column-name
   * interpolation — e.g. an attacker posting
   * `{"column":"x\" = \"y\" OR \"user_id"}` to /api/db would otherwise
   * break out of the quoted identifier and inject arbitrary SQL.
   *
   * Allowed: letters, digits, underscores. Optionally a single dot
   * for schema-qualified names (e.g. "public.users"). Rejects
   * anything containing quotes, semicolons, spaces, or special chars.
   *
   * @throws {Error} if the identifier contains anything outside
   *   [A-Za-z0-9_.]
   */
  private validateIdentifier(name: string, kind: 'column' | 'table'): string {
    if (typeof name !== 'string' || name.length === 0) {
      throw new Error(`Invalid ${kind} identifier: empty or non-string`)
    }
    // Allow schema.table (one dot max), alphanumeric + underscore only
    if (!/^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)?$/.test(name)) {
      throw new Error(
        `Invalid ${kind} identifier "${name}": only letters, digits, underscores, and an optional schema-qualifying dot are allowed`
      )
    }
    return name
  }

  constructor(pool: Pool, table: string) {
    this.pool = pool
    this.table = this.validateIdentifier(table, 'table')
  }

  select(columns: string = '*', options?: { count?: string; head?: boolean }): this {
    this.operation = 'select'
    this.selectColumns = columns
    if (options?.count === 'exact') this.countOnly = true
    if (options?.head) this.headOnly = true
    return this
  }

  insert(data: Record<string, unknown> | Record<string, unknown>[]): this {
    this.operation = 'insert'
    this.insertPayload = data
    return this
  }

  update(data: Record<string, unknown>): this {
    this.operation = 'update'
    this.updatePayload = data
    return this
  }

  upsert(data: Record<string, unknown> | Record<string, unknown>[], options?: { onConflict?: string }): this {
    this.operation = 'upsert'
    this.insertPayload = data
    if (options?.onConflict) {
      // ON CONFLICT supports comma-separated multi-column targets
      // (e.g. 'user_id,parcel_number', 'project_id,row_index'). Validate
      // EVERY identifier so an injection like `id"; DROP TABLE x; --` is
      // still rejected synchronously, while legitimate multi-column
      // conflict targets keep working. VULN-002 regression fix (2026-08-03):
      // previously the whole string was run through validateIdentifier(),
      // which rejected commas and threw on every multi-column conflict.
      this.upsertConflict = options.onConflict
        .split(',')
        .map((c) => this.validateIdentifier(c.trim(), 'column'))
        .join(',')
    }
    return this
  }

  delete(): this {
    this.operation = 'delete'
    return this
  }

  // ponytail: filter values are `unknown` — the builder just serializes them to SQL params
  eq(column: string, value: unknown): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: '=', value })
    return this
  }

  neq(column: string, value: unknown): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: '!=', value })
    return this
  }

  gt(column: string, value: unknown): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: '>', value })
    return this
  }

  gte(column: string, value: unknown): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: '>=', value })
    return this
  }

  lt(column: string, value: unknown): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: '<', value })
    return this
  }

  lte(column: string, value: unknown): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: '<=', value })
    return this
  }

  like(column: string, pattern: string): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: 'LIKE', value: pattern })
    return this
  }

  ilike(column: string, pattern: string): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: 'ILIKE', value: pattern })
    return this
  }

  in(column: string, values: unknown[]): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: 'IN', value: values })
    return this
  }

  is(column: string, value: unknown): this {
    const col = this.validateIdentifier(column, 'column')
    if (value === null) {
      this.filters.push({ column: col, op: 'IS', value: null })
    } else {
      this.filters.push({ column: col, op: 'IS NOT', value: null })
    }
    return this
  }

  not(column: string, op: string, value: unknown): this {
    const col = this.validateIdentifier(column, 'column')
    if (op === 'eq') this.filters.push({ column: col, op: '!=', value })
    else if (op === 'is') this.filters.push({ column: col, op: 'IS NOT', value })
    else if (op === 'in') {
      this.filters.push({ column: col, op: 'NOT_IN', value })
    }
    return this
  }

  or(filter: string): this {
    // NOTE: `filter` is a raw SQL fragment. Callers must not interpolate
    // user input into it. This is the one escape hatch for complex OR
    // conditions; use sparingly and never with untrusted column names.
    this.orFilters.push(filter)
    return this
  }

  contains(column: string, value: unknown): this {
    this.filters.push({ column: this.validateIdentifier(column, 'column'), op: '@>', value })
    return this
  }

  order(column: string, options?: { ascending?: boolean }): this {
    this.orderClauses.push({ column: this.validateIdentifier(column, 'column'), ascending: options?.ascending ?? true })
    return this
  }

  limit(count: number): this {
    this.limitCount = this.coerceNonNegativeInt(count, 'LIMIT')
    return this
  }

  range(from: number, to: number): this {
    this.offsetCount = this.coerceNonNegativeInt(from, 'OFFSET')
    this.limitCount = this.coerceNonNegativeInt(to - from + 1, 'LIMIT')
    return this
  }

  // ponytail: single()/maybeSingle() return `this` so chaining works, but also
  // need to be thenable. The `as unknown as` cast is the minimum needed —
  // the builder is thenable via the `then` method below.
  single(): PromiseLike<QueryResult<T>> & this {
    this.singleRow = true
    return this as unknown as PromiseLike<QueryResult<T>> & this
  }

  maybeSingle(): PromiseLike<QueryResult<T | null>> & this {
    this.maybeSingleRow = true
    return this as unknown as PromiseLike<QueryResult<T | null>> & this
  }

  // Make the builder thenable so `await dbClient.from('x').select('*')` works
  then<TResult1 = QueryResult<T>, TResult2 = never>(
    resolve?: ((value: QueryResult<T>) => TResult1 | PromiseLike<TResult1>) | null,
    reject?: ((reason: unknown) => TResult2 | PromiseLike<TResult2>) | null,
  ): Promise<TResult1 | TResult2> {
    return this.execute().then(resolve, reject)
  }

  private buildWhereClause(params: unknown[]): string {
    if (this.filters.length === 0 && this.orFilters.length === 0) return ''

    const conditions: string[] = []

    for (const f of this.filters) {
      if (f.op === 'IS') {
        conditions.push(`"${f.column}" IS NULL`)
      } else if (f.op === 'IS NOT') {
        conditions.push(`"${f.column}" IS NOT NULL`)
      } else if (f.op === 'IN' || f.op === 'NOT_IN') {
        const values = (f.value as unknown[]).map((v) => {
          params.push(v)
          return `$${params.length}`
        })
        const operator = f.op === 'IN' ? 'IN' : 'NOT IN'
        conditions.push(`"${f.column}" ${operator} (${values.join(', ')})`)
      } else if (f.op === '@>') {
        params.push(JSON.stringify(f.value))
        conditions.push(`"${f.column}" @> $${params.length}::jsonb`)
      } else {
        params.push(f.value)
        conditions.push(`"${f.column}" ${f.op} $${params.length}`)
      }
    }

    // Handle raw OR filters (legacy-style: "col.eq.val,col2.eq.val2")
    for (const orFilter of this.orFilters) {
      const parsed = this.parseOrFilter(orFilter, params)
      if (parsed) conditions.push(`(${parsed})`)
    }

    return conditions.length > 0 ? ` WHERE ${conditions.join(' AND ')}` : ''
  }

  private parseOrFilter(filter: string, params: unknown[]): string | null {
    const parts = filter.split(',')
    const orParts: string[] = []

    for (const part of parts) {
      const match = part.trim().match(/^(\w+)\.(\w+)\.(.+)$/)
      if (match) {
        const [, col, op, val] = match
        if (op === 'eq') {
          params.push(val === 'null' ? null : val)
          if (val === 'null') {
            orParts.push(`"${col}" IS NULL`)
          } else {
            orParts.push(`"${col}" = $${params.length}`)
          }
        } else if (op === 'neq') {
          params.push(val)
          orParts.push(`"${col}" != $${params.length}`)
        } else if (op === 'gt') {
          params.push(val)
          orParts.push(`"${col}" > $${params.length}`)
        } else if (op === 'lt') {
          params.push(val)
          orParts.push(`"${col}" < $${params.length}`)
        } else if (op === 'ilike') {
          params.push(val)
          orParts.push(`"${col}" ILIKE $${params.length}`)
        }
      }
    }

    return orParts.length > 0 ? orParts.join(' OR ') : null
  }

  /**
   * Build the SELECT column list from a comma-separated string, validating
   * every identifier against the strict allowlist.
   *
   * VULN-001 FIX (security review 2026-08-03): Previously the columns were
   * only wrapped in double quotes with no validation, so a payload like
   * `id" FROM users; DROP TABLE projects; --` broke out of the quoted
   * identifier and executed arbitrary SQL (simple query protocol allows
   * multi-statement when no params are bound).
   *
   * Supported shapes (each identifier validated):
   *   - `*`
   *   - `col` (single-arg function calls like `count(*)`, `max(easting)` are
   *     also accepted; multi-arg calls like `count(a, b)` are rejected since
   *     no current caller needs them and splitting on commas is unsafe)
   *   - `col AS alias` (used by TraverseModal)
   *
   * NOTE: the allowlist permits one dot ("schema.col"), but the emitted SQL
   * quotes the whole token as a single identifier (`"public.id"`), so it is
   * a literal column name — same as the pre-fix behavior.
   *
   * @throws {Error} on any invalid identifier
   */
  private buildSelectColumns(columns: string): string {
    if (columns === '*') return '*'
    return columns.split(',').map((c) => {
      const trimmed = c.trim()
      if (trimmed === '') throw new Error('Invalid column: empty column in select list')
      if (trimmed === '*') return '*'

      // Handle `col AS alias` (e.g. "point_name as name" in TraverseModal)
      const asMatch = trimmed.match(/^([A-Za-z_][A-Za-z0-9_.]*)\s+AS\s+([A-Za-z_][A-Za-z0-9_]*)$/i)
      if (asMatch) {
        const col = this.validateIdentifier(asMatch[1].trim(), 'column')
        const alias = this.validateIdentifier(asMatch[2].trim(), 'column')
        return `"${col}" AS "${alias}"`
      }

      // Handle function calls: count(*), max(easting), etc.
      if (trimmed.includes('(')) {
        const fnMatch = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*\((.*)\)$/)
        if (!fnMatch) {
          throw new Error(`Invalid column "${trimmed}": malformed expression`)
        }
        const fnName = this.validateIdentifier(fnMatch[1].trim(), 'column')
        const inner = fnMatch[2].trim()
        if (inner === '') {
          throw new Error(`Invalid column "${trimmed}": empty function arguments`)
        }
        const args = inner.split(',').map((a) => {
          const arg = a.trim()
          if (arg === '') throw new Error(`Invalid column "${trimmed}": empty argument`)
          if (arg === '*') return '*'
          return `"${this.validateIdentifier(arg, 'column')}"`
        })
        return `${fnName.toUpperCase()}(${args.join(', ')})`
      }

      return `"${this.validateIdentifier(trimmed, 'column')}"`
    }).join(', ')
  }

  /**
   * VULN-001 FIX: coerce LIMIT/OFFSET values to a non-negative integer.
   * The /api/db proxy typed these as `number` but the raw JSON body can
   * carry anything (e.g. `"1; DROP TABLE users"` or `1.5`) — interpolating
   * those raw would be SQL injection / invalid SQL.
   *
   * @throws {Error} if the value is not a non-negative integer
   */
  private coerceNonNegativeInt(value: unknown, label: 'LIMIT' | 'OFFSET'): number {
    const n = typeof value === 'number' ? value : Number(value)
    if (!Number.isFinite(n) || !Number.isInteger(n) || n < 0) {
      throw new Error(`Invalid ${label}: must be a non-negative integer`)
    }
    return n
  }

  private buildOrderClause(): string {
    if (this.orderClauses.length === 0) return ''
    const parts = this.orderClauses.map((o) => `"${o.column}" ${o.ascending ? 'ASC' : 'DESC'}`)
    return ` ORDER BY ${parts.join(', ')}`
  }

  private buildLimitOffset(): string {
    let sql = ''
    // Defense-in-depth: re-validate even though the setters already coerce,
    // so any future code path that writes limitCount/offsetCount is safe too.
    if (this.limitCount !== null) sql += ` LIMIT ${this.coerceNonNegativeInt(this.limitCount, 'LIMIT')}`
    if (this.offsetCount !== null) sql += ` OFFSET ${this.coerceNonNegativeInt(this.offsetCount, 'OFFSET')}`
    return sql
  }

  private async execute(): Promise<QueryResult<T>> {
    try {
      switch (this.operation) {
        case 'select': return await this.executeSelect()
        case 'insert': return await this.executeInsert()
        case 'update': return await this.executeUpdate()
        case 'delete': return await this.executeDelete()
        case 'upsert': return await this.executeUpsert()
        default: return { data: null, error: { message: `Unknown operation: ${this.operation}`, code: 'UNKNOWN_OP' } }
      }
    } catch (err: unknown) {
      // ponytail: was `catch (err: unknown)` — now properly narrowed
      const pgErr = err as { message?: string; code?: string; detail?: string }
      return {
        data: null,
        error: {
          message: pgErr.message || 'Database query failed',
          code: pgErr.code || 'QUERY_ERROR',
          details: pgErr.detail,
        },
      }
    }
  }

  private async executeSelect(): Promise<QueryResult<T>> {
    const params: unknown[] = []

    if (this.headOnly && this.countOnly) {
      // NOTE: head+count (used by e.g. community.ts, optimization.ts) never
      // touches selectColumns, so buildSelectColumns() is intentionally
      // skipped here — nothing user-controlled is interpolated into SQL.
      const sql = `SELECT COUNT(*) as count FROM "${this.table}"${this.buildWhereClause(params)}`
      const result = await this.pool.query(sql, params as unknown[])
      const count = parseInt(result.rows[0]?.count ?? '0', 10)
      return { data: null, error: null, count }
    }

    // VULN-001 FIX: validate every select column (throws → caught by execute()
    // and returned as a structured { data: null, error } instead of executing
    // attacker-controlled SQL).
    const columns = this.buildSelectColumns(this.selectColumns)

    let sql = `SELECT ${columns} FROM "${this.table}"`
    sql += this.buildWhereClause(params)
    sql += this.buildOrderClause()
    sql += this.buildLimitOffset()

    if (this.singleRow || this.maybeSingleRow) {
      sql += this.limitCount === null ? ' LIMIT 1' : ''
    }

    const result = await this.pool.query(sql, params as unknown[])

    if (this.countOnly) {
      const countParams: unknown[] = []
      const countSql = `SELECT COUNT(*) as count FROM "${this.table}"${this.buildWhereClause(countParams)}`
      const countResult = await this.pool.query(countSql, countParams as unknown[])
      const count = parseInt(countResult.rows[0]?.count ?? '0', 10)

      if (this.singleRow) {
        if (result.rows.length === 0) {
          return { data: null, error: { message: 'Row not found', code: 'PGRST116' }, count }
        }
        return { data: result.rows[0] as T, error: null, count }
      }

      return { data: result.rows as T, error: null, count }
    }

    if (this.singleRow) {
      if (result.rows.length === 0) {
        return { data: null, error: { message: 'Row not found', code: 'PGRST116' } }
      }
      return { data: result.rows[0] as T, error: null }
    }

    if (this.maybeSingleRow) {
      return { data: (result.rows[0] ?? null) as T, error: null }
    }

    return { data: result.rows as T, error: null }
  }

  private async executeInsert(): Promise<QueryResult<T>> {
    if (!this.insertPayload) return { data: null, error: null }
    const rows = Array.isArray(this.insertPayload) ? this.insertPayload : [this.insertPayload]
    if (rows.length === 0) return { data: null, error: null }

    const columns = Object.keys(rows[0]).map((c) => this.validateIdentifier(c, 'column'))
    const params: unknown[] = []
    const valuesList: string[] = []

    for (const row of rows) {
      const placeholders: string[] = []
      for (const col of columns) {
        params.push(row[col] !== undefined ? row[col] : null)
        placeholders.push(`$${params.length}`)
      }
      valuesList.push(`(${placeholders.join(', ')})`)
    }

    const quotedColumns = columns.map((c) => `"${c}"`).join(', ')
    const sql = `INSERT INTO "${this.table}" (${quotedColumns}) VALUES ${valuesList.join(', ')} RETURNING ${this.returningColumns}`

    const result = await this.pool.query(sql, params as unknown[])
    const data = Array.isArray(this.insertPayload) ? result.rows : (result.rows[0] ?? null)
    return { data: data as T, error: null }
  }

  private async executeUpdate(): Promise<QueryResult<T>> {
    if (!this.updatePayload) return { data: null, error: { message: 'No data to update', code: 'NO_DATA' } }

    const params: unknown[] = []
    const setClauses: string[] = []

    for (const [key, value] of Object.entries(this.updatePayload)) {
      const col = this.validateIdentifier(key, 'column')
      params.push(value)
      setClauses.push(`"${col}" = $${params.length}`)
    }

    let sql = `UPDATE "${this.table}" SET ${setClauses.join(', ')}`
    sql += this.buildWhereClause(params)
    sql += ` RETURNING ${this.returningColumns}`

    const result = await this.pool.query(sql, params as unknown[])

    if (this.singleRow || this.maybeSingleRow) {
      return { data: (result.rows[0] ?? null) as T, error: null }
    }
    return { data: result.rows as T, error: null }
  }

  private async executeDelete(): Promise<QueryResult<T>> {
    const params: unknown[] = []
    let sql = `DELETE FROM "${this.table}"`
    sql += this.buildWhereClause(params)
    sql += ` RETURNING ${this.returningColumns}`

    const result = await this.pool.query(sql, params as unknown[])
    return { data: result.rows as T, error: null }
  }

  private async executeUpsert(): Promise<QueryResult<T>> {
    if (!this.insertPayload) return { data: null, error: null }
    const rows = Array.isArray(this.insertPayload) ? this.insertPayload : [this.insertPayload]
    if (rows.length === 0) return { data: null, error: null }

    // VULN-002 hardening (upsert path): validate every payload column key —
    // previously only insert()/update() validated, so a malicious key like
    // `id" = "1" OR "owner_id` broke out of the quoted identifier in both the
    // column list and the EXCLUDED.* update set. The onConflict column is
    // already validated at the upsert() setter.
    const columns = Object.keys(rows[0]).map((c) => this.validateIdentifier(c, 'column'))
    const params: unknown[] = []
    const valuesList: string[] = []

    for (const row of rows) {
      const placeholders: string[] = []
      for (const col of columns) {
        params.push(row[col] !== undefined ? row[col] : null)
        placeholders.push(`$${params.length}`)
      }
      valuesList.push(`(${placeholders.join(', ')})`)
    }

    const quotedColumns = columns.map((c) => `"${c}"`).join(', ')
    // The conflict target may be multi-column ('a,b') — split and quote each
    // identifier separately so the emitted SQL is `ON CONFLICT ("a", "b")`
    // rather than one quoted identifier containing commas.
    const conflictCols = this.upsertConflict.split(',').map((c) => c.trim())
    const quotedConflict = conflictCols.map((c) => `"${c}"`).join(', ')
    const conflictSet = new Set(conflictCols)
    const updateCols = columns.filter((c) => !conflictSet.has(c))
    const updateSet = updateCols.map((c) => `"${c}" = EXCLUDED."${c}"`).join(', ')
    // Degenerate case: every payload column is a conflict column — DO NOTHING
    // is valid SQL where `DO UPDATE SET ` (empty) would not be.
    const conflictAction = updateSet ? `DO UPDATE SET ${updateSet}` : 'DO NOTHING'

    const sql = `INSERT INTO "${this.table}" (${quotedColumns}) VALUES ${valuesList.join(', ')} ON CONFLICT (${quotedConflict}) ${conflictAction} RETURNING ${this.returningColumns}`

    const result = await this.pool.query(sql, params as unknown[])
    const data = Array.isArray(this.insertPayload) ? result.rows : (result.rows[0] ?? null)
    return { data: data as T, error: null }
  }
}

export function createQueryBuilder(pool: Pool) {
  return {
    from(table: string): QueryBuilder {
      return new QueryBuilder(pool, table)
    },
  }
}

/**
 * Deed Plan Generator
 * 
 * Generates a complete vector PDF deed plan that meets Kenya
 * Survey Department standards for submission to Ardhi House.
 * 
 * Requirements:
 * - Paper: A1 (594 × 841mm) or A2
 * - Scale: 1:500, 1:1000, or 1:2500
 * - Vector-only lines and text
 * - Coordinate grid with UTM ticks
 * - Standard title block
 * - North arrow with convergence
 * - Scale bar (graphical + representative fraction)
 * - Beacon symbols per Kenya standards
 * - Line weights per Kenya standards
 * - PDF/A-1b compliant (archival)
 */

import PDFDocument from 'pdfkit';
import {
  createSurveyDocument,
  drawLine,
  drawRect,
  drawText,
  drawBeaconSymbol,
  drawNorthArrow,
  drawScaleBar,
  drawDigitalSignatureStamp,
  PAPER_SIZES,
  LINE_WEIGHTS,
  TEXT_SIZES,
  type PaperSizeName,
  type DocumentMetadata,
} from '../pdf-engine';
import { drawTitleBlock, type TitleBlockData } from './title-block';
import { drawGridOverlay, type GridOverlayInput } from './grid-overlay';
import { drawBoundaryLine, drawBeacon } from './symbology';

// ─── Types ───────────────────────────────────────────────────────

export interface DeedPlanPoint {
  easting: number;
  northing: number;
  label: string;
  beaconType: 'control' | 'beacon' | 'benchmark';
}

export interface DeedPlanBoundary {
  fromIndex: number;
  toIndex: number;
  type: 'scheme' | 'parcel' | 'road' | 'river' | 'dimension';
  bearing?: string;
  distance?: string;
}

export interface DeedPlanInput {
  /** Points defining the parcel boundary */
  points: DeedPlanPoint[];
  /** Boundary lines connecting points */
  boundaries: DeedPlanBoundary[];
  /** Paper size (A1 or A2) */
  paperSize: PaperSizeName;
  /** Map scale (e.g., 1000 for 1:1000) */
  scale: number;
  /** Title block data */
  titleData: TitleBlockData;
  /** Document metadata */
  metadata: DocumentMetadata;
  /** Grid convergence at map center (decimal degrees) */
  convergence?: number;
  /** Grid interval in meters (default: auto) */
  gridInterval?: number;
  /** Margin around map area (mm) */
  mapMargin?: number;
}

// ─── Constants ───────────────────────────────────────────────────

const TITLE_BLOCK_RESERVE = 55; // mm reserved for title block at bottom
const MARGIN = 15; // mm margin around the page

// ─── Core Function ───────────────────────────────────────────────

/**
 * Generate a complete deed plan PDF.
 * 
 * Returns a Buffer containing the PDF data.
 */
export async function generateDeedPlan(input: DeedPlanInput): Promise<Buffer> {
  const {
    points,
    boundaries,
    paperSize,
    scale,
    titleData,
    metadata,
    convergence,
    gridInterval,
    mapMargin = 10,
  } = input;
  
  const paper = PAPER_SIZES[paperSize];
  const mmToPt = 2.8346;
  
  // Create PDF document (landscape orientation for deed plans)
  const doc = createSurveyDocument({
    paperSize,
    orientation: 'landscape',
    scale,
    metadata,
  });
  
  // Collect PDF data into a buffer
  const chunks: Buffer[] = [];
  doc.on('data', (chunk: Buffer) => chunks.push(chunk));
  
  const pdfPromise = new Promise<Buffer>((resolve) => {
    doc.on('end', () => resolve(Buffer.concat(chunks)));
  });
  
  // ─── Compute map area ──────────────────────────────────────
  // Map area is the portion of the page where the survey drawing goes
  const pageW = paper.height; // Landscape
  const pageH = paper.width;
  
  const mapAreaX = MARGIN;
  const mapAreaY = MARGIN;
  const mapAreaW = pageW - 2 * MARGIN;
  const mapAreaH = pageH - 2 * MARGIN - TITLE_BLOCK_RESERVE;
  
  // ─── Compute coordinate extent of the survey ───────────────
  const eastings = points.map(p => p.easting);
  const northings = points.map(p => p.northing);
  
  const minE = Math.min(...eastings);
  const maxE = Math.max(...eastings);
  const minN = Math.min(...northings);
  const maxN = Math.max(...northings);
  
  // Add 10% padding around the survey area
  const rangeE = maxE - minE || 100;
  const rangeN = maxN - minN || 100;
  const paddingE = rangeE * 0.1;
  const paddingN = rangeN * 0.1;
  
  const originE = minE - paddingE;
  const originN = minN - paddingN;
  const extentE = rangeE + 2 * paddingE;
  const extentN = rangeN + 2 * paddingN;
  
  // mm per meter on the plan
  const mmPerMeter = 1000 / scale;
  
  // ─── Draw map border ───────────────────────────────────────
  drawRect(doc, mapAreaX, mapAreaY, mapAreaW, mapAreaH, LINE_WEIGHTS.titleBorder);
  
  // ─── Draw coordinate grid ──────────────────────────────────
  drawGridOverlay(doc, {
    originEasting: originE,
    originNorthing: originN,
    groundWidth: extentE,
    groundHeight: extentN,
    paperOriginX: mapAreaX + mapMargin,
    paperOriginY: mapAreaY + mapMargin,
    paperWidth: mapAreaW - 2 * mapMargin,
    paperHeight: mapAreaH - 2 * mapMargin,
    scale,
    gridInterval,
  });
  
  // ─── Coordinate transform: ground (meters) → paper (mm) ────
  const groundToPaperX = (easting: number) => {
    return mapAreaX + mapMargin + (easting - originE) * mmPerMeter;
  };
  const groundToPaperY = (northing: number) => {
    return mapAreaY + mapMargin + (maxN + paddingN - northing) * mmPerMeter; // Y inverted
  };
  
  // ─── Draw boundary lines ───────────────────────────────────
  for (const boundary of boundaries) {
    const fromPt = points[boundary.fromIndex];
    const toPt = points[boundary.toIndex];
    
    const paperPoints = [
      { x: groundToPaperX(fromPt.easting), y: groundToPaperY(fromPt.northing) },
      { x: groundToPaperX(toPt.easting), y: groundToPaperY(toPt.northing) },
    ];
    
    drawBoundaryLine(doc, paperPoints, boundary.type);
    
    // Draw bearing and distance labels
    if (boundary.bearing || boundary.distance) {
      const midX = (paperPoints[0].x + paperPoints[1].x) / 2;
      const midY = (paperPoints[0].y + paperPoints[1].y) / 2;
      
      // Offset label perpendicular to the line
      const dx = paperPoints[1].x - paperPoints[0].x;
      const dy = paperPoints[1].y - paperPoints[0].y;
      const length = Math.sqrt(dx * dx + dy * dy);
      const nx = -dy / length * 3;
      const ny = dx / length * 3;
      
      if (boundary.bearing) {
        drawText(doc, boundary.bearing, midX + nx, midY + ny, TEXT_SIZES.bearing, { align: 'center' });
      }
      if (boundary.distance) {
        drawText(doc, boundary.distance, midX + nx, midY + ny + 2, TEXT_SIZES.dimension, { align: 'center' });
      }
    }
  }
  
  // ─── Draw beacon symbols ───────────────────────────────────
  for (const point of points) {
    const px = groundToPaperX(point.easting);
    const py = groundToPaperY(point.northing);
    
    drawBeacon(doc, px, py, 3, point.label);
    
    // Coordinate label
    const coordText = `E ${point.easting.toFixed(1)}  N ${point.northing.toFixed(1)}`;
    drawText(doc, coordText, px + 3, py - 1, TEXT_SIZES.coordinate);
  }
  
  // ─── Draw title block ──────────────────────────────────────
  drawTitleBlock(doc, pageW - MARGIN, pageH - MARGIN, titleData);
  
  // ─── Digital Signature Stamp ───────────────────────────────
  if (titleData.surveyorName && titleData.surveyorLicense) {
    const stampX = pageW - MARGIN - 160 - 35; // 160 is title block width, 35 for stamp width+margin
    const stampY = pageH - MARGIN - 35; // Bottom aligned with title block
    drawDigitalSignatureStamp(
      doc,
      stampX,
      stampY,
      titleData.surveyorName,
      titleData.surveyorLicense,
      titleData.date,
      30 // 30mm diameter
    );
  }

  // ─── Finalize PDF ──────────────────────────────────────────
  doc.end();
  
  return pdfPromise;
}

/**
 * Kenya Standard Symbology for Survey Plans
 * 
 * All symbols defined as drawing functions that render vector paths.
 * Follows Kenya Survey Department standards for beacon types,
 * boundary types, and cartographic features.
 */

import type PDFKit from 'pdfkit';
import { drawLine, drawCircle, drawRect, drawText } from '../pdf-engine';

// ─── Beacon Symbols ──────────────────────────────────────────────

/**
 * Draw a control beacon — cross in circle with square.
 */
export function drawControlBeacon(
  doc: PDFKit.PDFDocument,
  cx: number, cy: number,
  diameter: number = 4,
  label?: string
): void {
  const r = diameter / 2;
  
  // Outer circle
  drawCircle(doc, cx, cy, r, 0.3);
  
  // Inner cross
  const cs = r * 0.6;
  drawLine(doc, cx - cs, cy, cx + cs, cy, 0.2);
  drawLine(doc, cx, cy - cs, cx, cy + cs, 0.2);
  
  // Outer square (rotated 45° — draw as diamond)
  const ds = r * 1.2;
  drawLine(doc, cx, cy - ds, cx + ds, cy, 0.2);
  drawLine(doc, cx + ds, cy, cx, cy + ds, 0.2);
  drawLine(doc, cx, cy + ds, cx - ds, cy, 0.2);
  drawLine(doc, cx - ds, cy, cx, cy - ds, 0.2);
  
  if (label) {
    drawText(doc, label, cx, cy + r + 1, 1.5, { align: 'center' });
  }
}

/**
 * Draw a beacon — cross in circle.
 */
export function drawBeacon(
  doc: PDFKit.PDFDocument,
  cx: number, cy: number,
  diameter: number = 3,
  label?: string
): void {
  const r = diameter / 2;
  
  // Circle
  drawCircle(doc, cx, cy, r, 0.2);
  
  // Cross
  const cs = r * 0.5;
  drawLine(doc, cx - cs, cy, cx + cs, cy, 0.15);
  drawLine(doc, cx, cy - cs, cx, cy + cs, 0.15);
  
  if (label) {
    drawText(doc, label, cx, cy + r + 1, 1.5, { align: 'center' });
  }
}

/**
 * Draw a benchmark — triangle with dot.
 */
export function drawBenchmark(
  doc: PDFKit.PDFDocument,
  cx: number, cy: number,
  size: number = 3,
  elevation?: number
): void {
  const h = size * 0.866; // Height of equilateral triangle
  
  // Triangle
  drawLine(doc, cx, cy - h * 2 / 3, cx - size / 2, cy + h / 3, 0.2);
  drawLine(doc, cx - size / 2, cy + h / 3, cx + size / 2, cy + h / 3, 0.2);
  drawLine(doc, cx + size / 2, cy + h / 3, cx, cy - h * 2 / 3, 0.2);
  
  // Center dot
  drawCircle(doc, cx, cy, 0.3, 0.1);
  
  if (elevation !== undefined) {
    drawText(doc, `BM ${elevation.toFixed(2)}m`, cx, cy + h / 3 + 1, 1.5, { align: 'center' });
  }
}

// ─── Boundary Line Styles ────────────────────────────────────────

export type BoundaryType = 'scheme' | 'parcel' | 'road' | 'river' | 'railway' | 'dimension';

/**
 * Draw a boundary line with the correct Kenya standard style.
 */
export function drawBoundaryLine(
  doc: PDFKit.PDFDocument,
  points: { x: number; y: number }[],
  type: BoundaryType
): void {
  if (points.length < 2) return;
  
  const config: Record<BoundaryType, { weight: number; color: string; dash?: number[] }> = {
    scheme: { weight: 0.5, color: 'black' },
    parcel: { weight: 0.3, color: 'black' },
    road: { weight: 0.4, color: 'black' },
    river: { weight: 0.3, color: '#0066CC' },
    railway: { weight: 0.3, color: 'black', dash: [3, 1.5] },
    dimension: { weight: 0.15, color: 'black', dash: [1, 0.5] },
  };
  
  const style = config[type];
  const mmToPt = 2.8346;
  
  doc.save();
  doc.lineWidth(style.weight * mmToPt).strokeColor(style.color);
  
  if (style.dash) {
    doc.dash(style.dash[0] * mmToPt, { space: style.dash[1] * mmToPt });
  }
  
  doc.moveTo(points[0].x * mmToPt, points[0].y * mmToPt);
  for (let i = 1; i < points.length; i++) {
    doc.lineTo(points[i].x * mmToPt, points[i].y * mmToPt);
  }
  doc.stroke();
  doc.undash();
  doc.restore();
}

// ─── Vegetation & Feature Symbols ────────────────────────────────

/**
 * Draw a tree symbol (circle with dot).
 */
export function drawTreeSymbol(
  doc: PDFKit.PDFDocument,
  cx: number, cy: number,
  size: number = 2
): void {
  drawCircle(doc, cx, cy, size / 2, 0.15);
  drawCircle(doc, cx, cy, 0.3, 0.1); // Center dot
}

/**
 * Draw a fence symbol (line with perpendicular ticks).
 */
export function drawFenceLine(
  doc: PDFKit.PDFDocument,
  x1: number, y1: number,
  x2: number, y2: number,
  tickSpacing: number = 3
): void {
  // Main line
  drawLine(doc, x1, y1, x2, y2, 0.15);
  
  // Ticks
  const dx = x2 - x1;
  const dy = y2 - y1;
  const length = Math.sqrt(dx * dx + dy * dy);
  const numTicks = Math.floor(length / tickSpacing);
  
  // Direction perpendicular to the line
  const nx = -dy / length;
  const ny = dx / length;
  const tickLen = 1;
  
  for (let i = 1; i <= numTicks; i++) {
    const t = i / (numTicks + 1);
    const px = x1 + dx * t;
    const py = y1 + dy * t;
    drawLine(doc, px, py, px + nx * tickLen, py + ny * tickLen, 0.1);
  }
}

/**
 * Draw a building footprint with hatching.
 */
export function drawBuilding(
  doc: PDFKit.PDFDocument,
  x: number, y: number,
  width: number, height: number,
  angle: number = 0
): void {
  // Building outline
  drawRect(doc, x, y, width, height, 0.25);
  
  // Hatching (45° lines)
  const mmToPt = 2.8346;
  const spacing = 1.5; // mm between hatch lines
  
  doc.save();
  doc.lineWidth(0.1 * mmToPt).strokeColor('#666666');
  
  // Clip to building rectangle
  doc
    .rect(x * mmToPt, y * mmToPt, width * mmToPt, height * mmToPt)
    .clip();
  
  for (let d = -Math.max(width, height); d < Math.max(width, height) * 2; d += spacing) {
    doc
      .moveTo((x + d) * mmToPt, y * mmToPt)
      .lineTo((x + d + height) * mmToPt, (y + height) * mmToPt)
    ;
  }
  doc.stroke();
  doc.restore();
}

/**
 * PDF Engine — Vector PDF Generation for Survey Documents
 * 
 * Generates professional vector PDFs for deed plans, traverse sheets,
 * and other Kenya survey documents. All lines, arcs, and text are
 * vector paths — no raster elements except for aerial photos.
 * 
 * Line weights follow Kenya Survey Department standards:
 * - Boundary lines: 0.5mm
 * - Plot boundaries: 0.3mm
 * - Dimension lines: 0.15mm
 * - Grid lines: 0.1mm
 * - Contour index: 0.5mm
 * - Contour intermediate: 0.15mm
 * 
 * Text sizes:
 * - Title block: 5mm caps
 * - Coordinates: 2.5mm
 * - Bearings: 2mm
 * - North arrow label: 3mm
 */

import PDFDocument from 'pdfkit';

// ─── Paper Size Constants (mm) ───────────────────────────────────

export const PAPER_SIZES = {
  A4: { width: 210, height: 297 },
  A3: { width: 297, height: 420 },
  A2: { width: 420, height: 594 },
  A1: { width: 594, height: 841 },
  A0: { width: 841, height: 1189 },
} as const;

export type PaperSizeName = keyof typeof PAPER_SIZES;

// ─── Kenya Standard Line Weights (mm) ────────────────────────────

export const LINE_WEIGHTS = {
  schemeBoundary: 0.5,
  parcelBoundary: 0.3,
  dimensionLine: 0.15,
  gridLine: 0.1,
  contourIndex: 0.5,
  contourIntermediate: 0.15,
  titleBorder: 0.7,
  buildingOutline: 0.25,
  waterLine: 0.3,
  roadLine: 0.4,
} as const;

// ─── Kenya Standard Text Sizes (mm) ──────────────────────────────

export const TEXT_SIZES = {
  titleBlock: 5,
  subTitle: 4,
  coordinate: 2.5,
  bearing: 2,
  dimension: 2,
  northArrow: 3,
  gridLabel: 2,
  legend: 2.5,
  small: 1.5,
} as const;

// ─── Types ───────────────────────────────────────────────────────

export interface DocumentMetadata {
  title: string;
  surveyorName: string;
  surveyorLicense: string;
  projectReference: string;
  date: string;
  county?: string;
  lrNumber?: string;
}

export interface PDFGenerationOptions {
  paperSize: PaperSizeName;
  orientation: 'portrait' | 'landscape';
  scale: number;
  metadata: DocumentMetadata;
  dpi?: number;
  /** Company logo buffer for paid plans. If provided, rendered in title block. */
  companyLogo?: Buffer | null;
  /** User subscription plan. Controls watermark behavior. */
  plan?: 'free' | 'pro' | 'team' | 'firm' | 'enterprise';
}

// ─── Core PDF Engine ─────────────────────────────────────────────

/**
 * Create a new PDF document configured for survey document output.
 * 
 * Uses mm units internally for precision, converts to PDF points (1pt = 0.3528mm).
 * All vector operations use exact coordinates for plotting accuracy.
 */
export function createSurveyDocument(options: PDFGenerationOptions): PDFKit.PDFDocument {
  const paper = PAPER_SIZES[options.paperSize];
  const isLandscape = options.orientation === 'landscape';
  
  const width = isLandscape ? paper.height : paper.width;
  const height = isLandscape ? paper.width : paper.height;
  
  // Convert mm to points (1mm = 2.8346 pt)
  const mmToPt = 2.8346;
  const pageWidthPt = width * mmToPt;
  const pageHeightPt = height * mmToPt;
  
  const doc = new PDFDocument({
    size: [pageWidthPt, pageHeightPt],
    margins: {
      top: 10 * mmToPt,
      bottom: 10 * mmToPt,
      left: 10 * mmToPt,
      right: 10 * mmToPt,
    },
    info: {
      Title: options.metadata.title,
      Author: `${options.metadata.surveyorName} (License: ${options.metadata.surveyorLicense})`,
      Subject: options.metadata.projectReference,
      Creator: 'METARDU Survey Engine',
      CreationDate: new Date(),
    },
  });
  
  return doc;
}

/**
 * Draw a line with a specific weight in mm.
 */
export function drawLine(
  doc: PDFKit.PDFDocument,
  x1: number, y1: number,
  x2: number, y2: number,
  weightMm: number,
  color: string = 'black'
): void {
  const mmToPt = 2.8346;
  
  doc
    .save()
    .lineWidth(weightMm * mmToPt)
    .strokeColor(color)
    .moveTo(x1 * mmToPt, y1 * mmToPt)
    .lineTo(x2 * mmToPt, y2 * mmToPt)
    .stroke()
    .restore();
}

/**
 * Draw text with a specific size in mm.
 */
export function drawText(
  doc: PDFKit.PDFDocument,
  text: string,
  x: number, y: number,
  sizeMm: number,
  options: {
    align?: 'left' | 'center' | 'right';
    color?: string;
    bold?: boolean;
  } = {}
): void {
  const mmToPt = 2.8346;
  const fontSizePt = sizeMm * mmToPt;
  
  doc
    .save()
    .fontSize(fontSizePt)
    .fillColor(options.color ?? 'black')
    .font(options.bold ? 'Helvetica-Bold' : 'Helvetica')
    .text(text, x * mmToPt, y * mmToPt, {
      align: options.align ?? 'left',
      lineBreak: false,
    })
    .restore();
}

/**
 * Draw a rectangle with specific line weight.
 */
export function drawRect(
  doc: PDFKit.PDFDocument,
  x: number, y: number,
  width: number, height: number,
  weightMm: number,
  color: string = 'black',
  fill?: string
): void {
  const mmToPt = 2.8346;
  
  doc
    .save()
    .lineWidth(weightMm * mmToPt)
    .strokeColor(color)
    .rect(x * mmToPt, y * mmToPt, width * mmToPt, height * mmToPt);
  
  if (fill) {
    doc.fillAndStroke(fill, color);
  } else {
    doc.stroke();
  }
  
  doc.restore();
}

/**
 * Draw a circle (beacon symbol).
 */
export function drawCircle(
  doc: PDFKit.PDFDocument,
  cx: number, cy: number,
  radiusMm: number,
  weightMm: number,
  color: string = 'black'
): void {
  const mmToPt = 2.8346;
  
  doc
    .save()
    .lineWidth(weightMm * mmToPt)
    .strokeColor(color)
    .circle(cx * mmToPt, cy * mmToPt, radiusMm * mmToPt)
    .stroke()
    .restore();
}

/**
 * Draw a cross inside a circle (Kenya beacon symbol).
 */
export function drawBeaconSymbol(
  doc: PDFKit.PDFDocument,
  cx: number, cy: number,
  diameterMm: number = 3,
  weightMm: number = 0.15,
  color: string = 'black'
): void {
  const radius = diameterMm / 2;
  
  // Circle
  drawCircle(doc, cx, cy, radius, weightMm, color);
  
  // Cross inside circle
  const crossSize = radius * 0.6;
  drawLine(doc, cx - crossSize, cy, cx + crossSize, cy, weightMm, color);
  drawLine(doc, cx, cy - crossSize, cx, cy + crossSize, weightMm, color);
}

/**
 * Draw a north arrow at specified position.
 */
export function drawNorthArrow(
  doc: PDFKit.PDFDocument,
  x: number, y: number,
  sizeMm: number = 15,
  convergence?: number
): void {
  const mmToPt = 2.8346;
  const s = sizeMm * mmToPt;
  const cx = x * mmToPt;
  const cy = y * mmToPt;
  
  doc.save();
  doc.strokeColor('black').lineWidth(0.3 * mmToPt).fillColor('black');
  
  // Arrow body (triangle pointing up)
  doc
    .moveTo(cx, cy - s / 2)           // Top point
    .lineTo(cx - s / 4, cy + s / 4)   // Bottom left
    .lineTo(cx, cy + s / 8)            // Bottom center indent
    .lineTo(cx + s / 4, cy + s / 4)   // Bottom right
    .closePath()
    .fillAndStroke('black', 'black');
  
  // Right half lighter
  doc
    .moveTo(cx, cy - s / 2)
    .lineTo(cx + s / 4, cy + s / 4)
    .lineTo(cx, cy + s / 8)
    .closePath()
    .fillAndStroke('white', 'black');
  
  // N label
  doc
    .fontSize(3 * mmToPt)
    .font('Helvetica-Bold')
    .text('N', cx - 2 * mmToPt, cy - s / 2 - 4 * mmToPt, {
      align: 'center',
      width: 4 * mmToPt,
    });
  
  // Convergence notation if provided
  if (convergence !== undefined && Math.abs(convergence) > 0.001) {
    const convStr = `γ = ${convergence.toFixed(1)}°`;
    doc
      .fontSize(1.5 * mmToPt)
      .font('Helvetica')
      .text(convStr, cx - 10 * mmToPt, cy + s / 2 + 2 * mmToPt, {
        width: 20 * mmToPt,
        align: 'center',
      });
  }
  
  doc.restore();
}

/**
 * Draw a company logo in the title block area.
 *
 * The logo is rendered at a maximum of 200×60mm (document coordinates)
 * while preserving aspect ratio. Supports PNG, JPG, and SVG formats.
 *
 * @param doc - PDFKit document
 * @param logoBuffer - Image data as Buffer
 * @param x - Top-left X position (mm)
 * @param y - Top-left Y position (mm)
 * @param maxWidth - Maximum width in mm (default: 200)
 * @param maxHeight - Maximum height in mm (default: 60)
 */
export function drawCompanyLogo(
  doc: PDFKit.PDFDocument,
  logoBuffer: Buffer,
  x: number,
  y: number,
  maxWidth: number = 200,
  maxHeight: number = 60
): void {
  const mmToPt = 2.8346;

  try {
    // PDFKit image method handles PNG, JPG, and SVG natively
    // We size it to fit within the given bounds maintaining aspect ratio
    doc.save();
    doc.image(logoBuffer, x * mmToPt, y * mmToPt, {
      width: maxWidth * mmToPt,
      height: maxHeight * mmToPt,
    });
    doc.restore();
  } catch (error) {
    console.error('[pdf-engine] Failed to render company logo:', error);
    // Fall back to text if image rendering fails
    drawText(doc, 'LOGO', x, y, 5, { color: '#999999', bold: true });
  }
}

/**
 * Draw a digital signature stamp.
 * Represents a digital seal for a licensed surveyor.
 */
export function drawDigitalSignatureStamp(
  doc: PDFKit.PDFDocument,
  x: number, y: number,
  surveyorName: string,
  licenseNumber: string,
  date: string,
  sizeMm: number = 30
): void {
  const mmToPt = 2.8346;
  const s = sizeMm * mmToPt;
  const cx = x * mmToPt + s / 2;
  const cy = y * mmToPt + s / 2;
  
  doc.save();
  
  // Outer circle
  doc
    .lineWidth(0.5 * mmToPt)
    .strokeColor('#1B3A5C')
    .circle(cx, cy, s / 2)
    .stroke();
    
  // Inner circle
  doc
    .lineWidth(0.2 * mmToPt)
    .circle(cx, cy, s / 2 - 2 * mmToPt)
    .stroke();
    
  // Text
  doc
    .fontSize(2.5 * mmToPt)
    .fillColor('#1B3A5C')
    .font('Helvetica-Bold')
    .text('LICENSED SURVEYOR', cx - s / 2, cy - s / 6, {
      width: s,
      align: 'center'
    });
    
  doc
    .fontSize(1.8 * mmToPt)
    .font('Helvetica')
    .text(surveyorName.toUpperCase(), cx - s / 2, cy + 1 * mmToPt, {
      width: s,
      align: 'center'
    });
    
  doc
    .fontSize(1.5 * mmToPt)
    .text(`LSK No: ${licenseNumber}`, cx - s / 2, cy + 4 * mmToPt, {
      width: s,
      align: 'center'
    });
    
  // Signature path
  doc
    .lineWidth(0.4 * mmToPt)
    .strokeColor('#2563EB') // Blue ink
    .moveTo(cx - s / 3, cy + s / 4)
    .bezierCurveTo(cx - s / 6, cy + s / 2, cx + s / 6, cy, cx + s / 3, cy + s / 4)
    .stroke();
    
  doc
    .fontSize(1.2 * mmToPt)
    .fillColor('#1B3A5C')
    .text(`Signed: ${date}`, cx - s / 2, cy + s / 2 + 1 * mmToPt, {
      width: s,
      align: 'center'
    });

  doc.restore();
}

/**
 * Draw the METARDU watermark diagonally across the document.
 * Applied only for free-tier users.
 *
 * The watermark is rendered as a large, semi-transparent, rotated text
 * that does not obscure the document content but clearly indicates
 * the free-tier origin.
 *
 * @param doc - PDFKit document
 * @param pageWidthMm - Page width in mm
 * @param pageHeightMm - Page height in mm
 */
export function drawMetarduWatermark(
  doc: PDFKit.PDFDocument,
  pageWidthMm: number,
  pageHeightMm: number
): void {
  const mmToPt = 2.8346;
  const centerX = (pageWidthMm / 2) * mmToPt;
  const centerY = (pageHeightMm / 2) * mmToPt;
  const fontSize = 60 * mmToPt; // Large watermark

  doc.save();
  doc
    .fontSize(fontSize)
    .font('Helvetica-Bold')
    .fillColor('rgba(0, 0, 0, 0.06)')
    .rotate(-45, { origin: [centerX, centerY] })
    .text('METARDU', centerX - 200 * mmToPt, centerY - fontSize / 2, {
      width: 400 * mmToPt,
      align: 'center',
      lineBreak: false,
    });
  doc.restore();
}

/**
 * Draw a graphical scale bar.
 * Must be verified to ±0.5mm accuracy on paper.
 */
export function drawScaleBar(
  doc: PDFKit.PDFDocument,
  x: number, y: number,
  scale: number,
  paperSizeMm: number,
  groundDistanceM: number,
  weightMm: number = 0.3
): void {
  const barLengthMm = (groundDistanceM / scale) * 1000; // Convert to mm on paper
  
  // Main bar
  drawLine(doc, x, y, x + barLengthMm, y, weightMm);
  
  // End ticks
  const tickHeight = 2;
  drawLine(doc, x, y - tickHeight / 2, x, y + tickHeight / 2, weightMm);
  drawLine(doc, x + barLengthMm, y - tickHeight / 2, x + barLengthMm, y + tickHeight / 2, weightMm);
  
  // Intermediate ticks
  const numDivisions = 4;
  for (let i = 1; i < numDivisions; i++) {
    const dx = (barLengthMm * i) / numDivisions;
    drawLine(doc, x + dx, y - tickHeight / 4, x + dx, y + tickHeight / 4, weightMm * 0.7);
  }
  
  // Labels
  drawText(doc, '0', x, y + 3, 1.5, { align: 'center' });
  drawText(doc, `${groundDistanceM}m`, x + barLengthMm, y + 3, 1.5, { align: 'center' });
  drawText(doc, `1:${scale}`, x + barLengthMm / 2, y + 6, 2, { align: 'center' });
}

/**
 * Logo Resolution Utility
 *
 * Resolves the company logo to use on generated documents.
 *
 * - Free plan: returns null → METARDU watermark will be applied by the PDF engine
 * - Pro/Team/Firm/Enterprise: looks up the user's uploaded logo from the database
 *   - If found, returns the logo Buffer
 *   - If not found, returns null (no watermark, no logo)
 */

import { db } from '@/lib/db';
import type { PlanId } from '@/lib/subscription/catalog';

export interface ResolvedLogo {
  /** The logo image data as a Buffer */
  data: Buffer;
  /** MIME type of the logo (image/png, image/jpeg, image/svg+xml) */
  mimeType: string;
  /** Original filename */
  filename: string;
}

/**
 * Resolve the company logo for a given user and plan.
 *
 * @param userId - The user's ID
 * @param plan - The user's subscription plan
 * @returns The resolved logo, or null if no logo should be shown
 */
export async function resolveCompanyLogo(
  userId: string,
  plan: PlanId
): Promise<ResolvedLogo | null> {
  // Free tier always gets METARDU watermark — no custom logo
  if (plan === 'free') {
    return null;
  }

  // Paid plans: look up the user's uploaded logo
  try {
    const { rows } = await db.query(
      'SELECT logo_data, mime_type, filename FROM company_logos WHERE user_id = $1',
      [userId]
    );

    if (rows.length === 0 || !rows[0].logo_data) {
      return null;
    }

    return {
      data: rows[0].logo_data as Buffer,
      mimeType: rows[0].mime_type as string,
      filename: rows[0].filename as string,
    };
  } catch (error) {
    console.error('[resolve-logo] Error fetching logo:', error);
    return null;
  }
}

/**
 * Determine the watermark strategy for document generation.
 *
 * - Free plan + no logo → METARDU watermark
 * - Paid plan + logo → Company logo in title block
 * - Paid plan + no logo → Blank (no watermark, no logo)
 */
export type WatermarkStrategy = 'metardu' | 'company_logo' | 'none';

export function getWatermarkStrategy(
  plan: PlanId,
  logo: ResolvedLogo | null
): WatermarkStrategy {
  if (plan === 'free') {
    return 'metardu';
  }
  if (logo) {
    return 'company_logo';
  }
  return 'none';
}

/**
 * @module sokStandards
 *
 * Survey of Kenya (SoK) Standards Compliance Module
 *
 * Implements the exact rendering standards required by the Director of Surveys:
 *
 * 1. LINE WEIGHTS (per SoK Drafting Manual, 2020 edition)
 *    - National/framework boundaries: 0.6mm
 *    - Scheme/parcel boundaries: 0.5mm
 *    - Plot/subdivision boundaries: 0.3mm
 *    - Dimension/leader lines: 0.15mm
 *    - Grid lines (major): 0.2mm
 *    - Grid lines (minor): 0.1mm
 *    - Contour index: 0.4mm
 *    - Contour intermediate: 0.12mm
 *    - Building outlines: 0.25mm
 *    - Road edges: 0.4mm
 *    - Water features: 0.3mm
 *    - Title block border: 0.7mm (double line)
 *
 * 2. TEXT SIZES (per SoK Cartographic Standards)
 *    - Title block heading: 6mm (uppercase, bold)
 *    - Subtitle: 4mm (uppercase)
 *    - Parcel numbers: 3mm (uppercase)
 *    - Coordinates: 2.5mm (monospace)
 *    - Bearings: 2mm (monospace)
 *    - Distances: 2mm (monospace)
 *    - Area labels: 2.5mm
 *    - Grid labels: 2mm
 *    - Legend: 2.5mm
 *    - North arrow: 4mm (uppercase "N")
 *    - Scale bar labels: 2mm
 *
 * 3. TYPOGRAPHY
 *    - All bearings/distances in UPRIGHT OPEN STYLE (vertical text)
 *    - Parcel numbers in CAPITAL LETTERS
 *    - Coordinates in MONOSPACE font
 *    - No italic or decorative fonts on legal documents
 *
 * 4. HATCH PATTERNS (for area delineation)
 *    - Road reserve: diagonal hatching 45° at 2mm spacing
 *    - Water bodies: horizontal dashed lines at 1.5mm spacing
 *    - Built-up areas: cross-hatching at 3mm spacing
 *    - Reserved land: dotted pattern at 2mm spacing
 *
 * 5. COORDINATE PRECISION
 *    - Easting/Northing: 3 decimal places (mm precision)
 *    - Bearings: DDD°MM'SS.SS" format (centisec precision)
 *    - Distances: 3 decimal places (mm precision)
 *    - Areas: 4 decimal places for hectares, 2 for m²
 *    - Elevations: 3 decimal places
 */

// ---------------------------------------------------------------------------
// Enhanced Line Weights (SoK 2020)
// ---------------------------------------------------------------------------

export const SOK_LINE_WEIGHTS = {
  // Boundaries
  nationalBoundary: 0.6,
  schemeBoundary: 0.5,
  parcelBoundary: 0.3,
  subdivisionBoundary: 0.25,

  // Dimension lines
  dimensionLine: 0.15,
  leaderLine: 0.12,

  // Grid
  gridMajor: 0.2,
  gridMinor: 0.1,

  // Contours
  contourIndex: 0.4,
  contourIntermediate: 0.12,

  // Features
  buildingOutline: 0.25,
  roadEdge: 0.4,
  roadCenterline: 0.15,
  waterLine: 0.3,
  vegetationLine: 0.2,

  // Administrative
  titleBorder: 0.7,
  titleBorderInner: 0.2,
  tableBorder: 0.3,
  tableInner: 0.1,
} as const

// ---------------------------------------------------------------------------
// Enhanced Text Sizes (SoK Cartographic)
// ---------------------------------------------------------------------------

export const SOK_TEXT_SIZES = {
