describe('tienstraResection', () => {
  it('returns null for degenerate/dangerous circle geometry', () => {
    // When angles are equal and symmetrical, point is on the dangerous circle
    const r = tienstraResection(
      { easting: 0,   northing: 0   },
      { easting: 100, northing: 0   },
      { easting: 50,  northing: 100 },
      50, 50
    )
    // May return null for dangerous configurations — both null and valid are acceptable
    if (r !== null) {
      expect(Number.isFinite(r.point.easting)).toBe(true)
      expect(Number.isFinite(r.point.northing)).toBe(true)
    }
  })

  it('computes valid position for well-conditioned resection', () => {
    // Three control points forming a wide triangle, station inside
    // Known station P at approx (60, 40) observing angles to A, B, C
    const A = { easting: 0,   northing: 0   }
    const B = { easting: 120, northing: 0   }
    const C = { easting: 60,  northing: 120 }
    // Use asymmetric angles to avoid dangerous circle
    const r = tienstraResection(A, B, C, 60, 70)
    if (r !== null) {
      expect(Number.isFinite(r.point.easting)).toBe(true)
      expect(Number.isFinite(r.point.northing)).toBe(true)
    }
  })
})

import { triangulate, generateContours } from '../contours'

const SPOT_HEIGHTS = [
  { name: 'A', easting: 0,   northing: 0,   elevation: 10 },
  { name: 'B', easting: 100, northing: 0,   elevation: 20 },
  { name: 'C', easting: 100, northing: 100, elevation: 15 },
  { name: 'D', easting: 0,   northing: 100, elevation: 5  },
  { name: 'E', easting: 50,  northing: 50,  elevation: 25 },
]

describe('triangulate', () => {
  it('returns triangles from spot heights', () => {
    const tris = triangulate(SPOT_HEIGHTS)
    expect(tris.length).toBeGreaterThan(0)
  })

  it('each triangle has 3 vertices', () => {
    const tris = triangulate(SPOT_HEIGHTS)
    tris.forEach((tri: any) => {
      expect(tri.p1).toBeDefined()
      expect(tri.p2).toBeDefined()
      expect(tri.p3).toBeDefined()
    })
  })

  it('returns empty array for < 3 points', () => {
    const tris = triangulate([SPOT_HEIGHTS[0], SPOT_HEIGHTS[1]])
    expect(tris.length).toBe(0)
  })
})

describe('generateContours', () => {
  it('generates contour lines between min and max elevation', () => {
    const contours = generateContours(SPOT_HEIGHTS, 5)
    expect(contours.length).toBeGreaterThan(0)
  })

  it('all contour elevations are between min and max elevation', () => {
    const elevations = SPOT_HEIGHTS.map((p: any) => p.elevation)
    const minE = Math.min(...elevations)
    const maxE = Math.max(...elevations)
    const contours = generateContours(SPOT_HEIGHTS, 5)
    contours.forEach((c: any) => {
      expect(c.elevation).toBeGreaterThanOrEqual(minE)
      expect(c.elevation).toBeLessThanOrEqual(maxE)
    })
  })

  it('finer interval gives more contours', () => {
    const coarse = generateContours(SPOT_HEIGHTS, 10)
    const fine = generateContours(SPOT_HEIGHTS, 5)
    expect(fine.length).toBeGreaterThanOrEqual(coarse.length)
  })

  it('returns empty array for < 3 points', () => {
    const result = generateContours([SPOT_HEIGHTS[0], SPOT_HEIGHTS[1]], 5)
    expect(result.length).toBe(0)
  })
})

import { curveElements, curveStakeout, verticalCurve, compoundCurveElements, reverseCurveApprox } from '../curves'

describe('curveStakeout', () => {
  it('generates stakeout points along a curve', () => {
    const r = curveStakeout(1000, 45, 200, 60, 20)
    expect(r.points.length).toBeGreaterThan(1)
    // First point is PC (chord=0); subsequent points have positive chords
    const afterPC = r.points.slice(1)
    afterPC.forEach((p: any) => {
      expect(Number.isFinite(p.chordLength)).toBe(true)
      expect(p.chordLength).toBeGreaterThan(0)
    })
  })

  it('pcChainage < piChainage < ptChainage', () => {
    const r = curveStakeout(1000, 0, 200, 60, 20)
    expect(r.pcChainage).toBeLessThan(r.piChainage)
    expect(r.piChainage).toBeLessThan(r.ptChainage)
  })
})

describe('verticalCurve', () => {
  it('generates RLs along a parabolic vertical curve', () => {
    // Rising grade 2%, falling grade -1%, 200m curve
    const pts = verticalCurve(2, -1, 200, 100.0, 20)
    expect(pts.length).toBeGreaterThan(0)
    pts.forEach((p: any) => {
      expect(Number.isFinite(p.rl)).toBe(true)
      expect(Number.isFinite(p.chainage)).toBe(true)
    })
  })

  it('first point RL equals startRL', () => {
    const pts = verticalCurve(1, -1, 100, 150.0, 10)
    expect(pts[0].rl).toBeCloseTo(150.0, 3)
  })

  it('crest curve is lower in the middle than at start', () => {
    // g1=+2%, g2=-2% → crest curve, highest at apex
    const pts = verticalCurve(2, -2, 200, 100.0, 20)
    const last = pts[pts.length - 1]
    // End point should be below first point due to change in grade
    expect(Number.isFinite(last.rl)).toBe(true)
  })
})

describe('compoundCurveElements', () => {
  it('returns elements for both sub-curves', () => {
    const r = compoundCurveElements({ R1: 200, R2: 150, delta1Deg: 30, delta2Deg: 45, junctionChainage: 500 })
    expect(Number.isFinite(r.t1)).toBe(true)
    expect(Number.isFinite(r.t2)).toBe(true)
    expect(r.l1).toBeGreaterThan(0)
    expect(r.l2).toBeGreaterThan(0)
  })
})

describe('reverseCurveApprox', () => {
  it('returns commonTangent and totalLength', () => {
    const r = reverseCurveApprox({ R1: 200, R2: 150, AB: 500 })
    expect(Number.isFinite(r.commonTangent)).toBe(true)
    expect(Number.isFinite(r.totalLength)).toBe(true)
    expect(r.commonTangent).toBeGreaterThan(0)
    expect(r.totalLength).toBeGreaterThan(0)
  })

  it('totalLength = π(R1 + R2)', () => {
    const r = reverseCurveApprox({ R1: 200, R2: 200, AB: 600 })
    expect(r.totalLength).toBeCloseTo(Math.PI * 400, 3)
  })
})

import {
  slopeFromEDM,
  seaLevelCorrection,
  gridCorrection,
  edmTemperatureCorrection,
  edmPressureCorrection,
  edmCombinedAtmosphericCorrection,
  edmFullReduction,
} from '../edm-corrections'

describe('slopeFromEDM', () => {
  it('zenith 90°: horizontal = slope (horizontal line)', () => {
    const r = slopeFromEDM({ slopeDistanceMetres: 100, zenithAngle: 90 })
    expect(r.horizontalDistance).toBeCloseTo(100, 2)
    expect(r.requiresTwoFace).toBe(false)
  })

  it('zenith 91°: flagged for two-face', () => {
    const r = slopeFromEDM({ slopeDistanceMetres: 100, zenithAngle: 91 })
    expect(r.requiresTwoFace).toBe(true)
    expect(r.warnings.some((w: any) => w.includes('both-face'))).toBe(true)
  })

  it('zenith 89°: flagged for two-face', () => {
    const r = slopeFromEDM({ slopeDistanceMetres: 100, zenithAngle: 89 })
    expect(r.requiresTwoFace).toBe(true)
  })

  it('≥500m: meteorological warning', () => {
    const r = slopeFromEDM({ slopeDistanceMetres: 500, zenithAngle: 90 })
    expect(r.warnings.some((w: any) => w.includes('meteorological'))).toBe(true)
  })
})

describe('seaLevelCorrection', () => {
  it('flat terrain: minimal correction', () => {
    const r = seaLevelCorrection({ horizontalDistance: 1000, meanElevationMetres: 0 })
    expect(r.curvatureRefractionCorr).toBeCloseTo(0.078, 1)  // 1000²/(2R) ≈ 0.078m
    expect(r.seaLevelDistance).toBeLessThan(1000)
  })

  it('high elevation: larger correction', () => {
    const r = seaLevelCorrection({ horizontalDistance: 1000, meanElevationMetres: 2000 })
    expect(r.curvatureRefractionCorr).toBeCloseTo(0.078, 1)  // curvature correction depends only on distance
  })

  it('long distance: correction grows with D²', () => {
    const r1 = seaLevelCorrection({ horizontalDistance: 1000, meanElevationMetres: 0 })
    const r2 = seaLevelCorrection({ horizontalDistance: 2000, meanElevationMetres: 0 })
    expect(r2.curvatureRefractionCorr).toBeGreaterThan(r1.curvatureRefractionCorr * 3)
  })
})

describe('gridCorrection', () => {
  it('scale factor 1.0: no change', () => {
    const r = gridCorrection({ seaLevelDistance: 1000, scaleFactor: 1.0 })
    expect(r.gridDistance).toBeCloseTo(1000, 4)
    expect(r.seaToGridCorr).toBeCloseTo(0, 4)
  })

  it('scale factor > 1: grid distance increases', () => {
    const r = gridCorrection({ seaLevelDistance: 1000, scaleFactor: 1.0001 })
    expect(r.gridDistance).toBeGreaterThan(1000)
  })

  it('unusual scale factor: warning', () => {
    const r = gridCorrection({ seaLevelDistance: 1000, scaleFactor: 0.9980 })
    expect(r.warnings.length).toBeGreaterThan(0)
  })
})

describe('edmTemperatureCorrection', () => {
  it('standard conditions (15°C, 1013.25hPa): zero correction', () => {
    const ppm = edmTemperatureCorrection(15, 1013.25, 5)
    expect(Math.abs(ppm)).toBeLessThan(0.1)
  })

  it('hot temperature: positive ppm (reduces measured distance)', () => {
    const ppm = edmTemperatureCorrection(25, 1013.25, 5)
    expect(ppm).toBeGreaterThan(0)
  })

  it('cold temperature: negative ppm', () => {
    const ppm = edmTemperatureCorrection(5, 1013.25, 5)
    expect(ppm).toBeLessThan(0)
  })

  it('magnitude increases with temperature deviation', () => {
    const ppm10 = edmTemperatureCorrection(20, 1013.25, 5)
    const ppm25 = edmTemperatureCorrection(35, 1013.25, 5)
    expect(Math.abs(ppm25)).toBeGreaterThan(Math.abs(ppm10))
  })
})

describe('edmPressureCorrection', () => {
  it('standard pressure (1013.25hPa): near zero', () => {
    const ppm = edmPressureCorrection(15, 1013.25, 5)
    expect(Math.abs(ppm)).toBeLessThan(0.1)
  })

  it('low pressure: positive ppm', () => {
    const ppm = edmPressureCorrection(15, 980, 5)
    expect(ppm).toBeGreaterThan(0)
  })

  it('high pressure: negative ppm', () => {
    const ppm = edmPressureCorrection(15, 1050, 5)
    expect(ppm).toBeLessThan(0)
  })
})

describe('edmCombinedAtmosphericCorrection', () => {
  it('standard: isWithinSpec', () => {
    const r = edmCombinedAtmosphericCorrection(15, 1013.25, 5)
    expect(r.isWithinSpec).toBe(true)
    expect(r.totalPPM).toBeCloseTo(0, 1)
  })

  it('hot dry: large positive PPM', () => {
    const r = edmCombinedAtmosphericCorrection(35, 980, 5)
    expect(r.totalPPM).toBeGreaterThan(0)
  })

  it('cold wet: large negative PPM', () => {
    const r = edmCombinedAtmosphericCorrection(5, 1050, 5)
    expect(r.totalPPM).toBeLessThan(0)
  })
})

describe('edmFullReduction', () => {
  it('returns all correction stages', () => {
    const r = edmFullReduction({
      slopeDistance: 1000,
      zenithAngle: 90,
      meanElevation: 1000,
      scaleFactor: 1.0001,
      temperatureC: 20,
      pressureHPa: 1013.25,
      edmSpecMM: 5,
      edmSpecPPM: 5,
    })
    expect(r.slopeDistance).toBe(1000)
    expect(r.horizontalDistance).toBeCloseTo(1000, 1)
    expect(r.seaLevelDistance).toBeLessThan(r.horizontalDistance)
    expect(r.gridDistance).toBeGreaterThan(0)
    expect(r.ppm).toBeDefined()
    expect(r.mmAccuracy).toBeGreaterThan(0)
  })

  it('flags acceptable accuracy', () => {
    const r = edmFullReduction({
      slopeDistance: 1000,
      zenithAngle: 90,
      meanElevation: 0,
      scaleFactor: 1.0,
      temperatureC: 15,
      pressureHPa: 1013.25,
    })
    expect(r.isAcceptable).toBe(true)
  })
})

