    // Our distanceBearing uses To-From convention. We verify magnitudes match.

    const rd21_rda1 = distanceBearing(STATIONS.RD21, STATIONS.RDa1);
    // Spreadsheet ΔN = -250.80 (From-To), our ΔN = +250.80 (To-From)
