      {
        type: 'gnss_baseline',
        from: 'A',
        to: 'B',
        value: 0,
        sigma: 0.005,
        deltaE: 50,
        deltaN: 50,
        deltaU: 0,
        // Correlated covariance: positive correlation between E and N
        covariance3x3: [
          0.000025,  // C_EE
          0.000015,  // C_EN (positive correlation)
          0.000025,  // C_NN
          0,         // C_EU
          0,         // C_NU
          0.000025,  // C_UU
        ],
      },
    ]

    const result = adjustNetwork(points, observations, {
      dimension: '3D',
      convergenceMm: 0.01,
    })

    expect(result.ok).toBe(true)
