      deltaE: 50, deltaN: 50, deltaU: 0,
      covariance3x3: [0.000025, 0, 0.000025, 0, 0, 0.000025],
    }
    const obs_B_P: NetworkObservation = {
      type: 'gnss_baseline',
      from: 'B', to: 'P', value: 0, sigma: 0.005,
