    }
    const obs_C_P: NetworkObservation = {
      type: 'gnss_baseline',
      from: 'C', to: 'P', value: 0, sigma: 0.005,
      deltaE: 0, deltaN: -50, deltaU: 0,
      covariance3x3: [0.000025, 0, 0.000025, 0, 0, 0.000025],
