  })
})

/**
 * Automated breakline extraction from a TIN mesh.
 *
 * Roadmap reference: docs/ROADMAP.md → Tier 2 → "Automated breakline
 * extraction". Algorithm: compute triangle normal vectors, flag sharp
 * dihedral-angle changes along shared edges, stitch candidate edges into
 * MultiLineStrings.
 *
 * Surveyors typically digitise breaklines in the field (toe-of-slope,
 * top-of-bank, kerb line, etc.), but for legacy data or photogrammetric
 * point clouds, automatic extraction saves hours of manual work.
 *
 * Algorithm:
 *   1. Build the TIN via `buildTINSurface` (or accept a pre-built one).
 *   2. For each triangle, compute the 3D unit normal vector.
 *   3. Build an edge → triangle(s) adjacency map.
 *   4. For each INTERIOR edge (shared by exactly 2 triangles):
 *        - Compute the dihedral angle = angle between the two normals
 *        - If dihedral > threshold, mark the edge as a breakline candidate
 *   5. Stitch candidate edges into ordered polylines (chains).
 *
 * Output: an array of polylines, each an array of {easting, northing}
 * points. Suitable for direct rendering on OpenLayers or for export as
 * GeoJSON LineStrings.
 *
 * References:
 *   - Sciutto, S. (2010) "Automatic breakline detection from TIN"
 *   - Yoshimura, T. (2016) "Feature line extraction from triangle meshes"
 */

import {
  buildTINSurface,
  type SpotHeight,
  type Breakline,
  type Triangle,
  type TINSurface,
} from '@/lib/engine/contours'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface Vec3 {
  x: number
  y: number
  z: number
}

export interface BreaklineExtractionOptions {
  /**
   * Dihedral angle threshold in degrees. Edges where the dihedral angle
   * between adjacent triangle normals exceeds this value are flagged as
   * breakline candidates. Default: 30°.
   *
   * Lower → more sensitive (more breaklines). Higher → stricter (fewer).
   * Common presets:
   *   15° — ridge detection (sharp terrain)
   *   30° — general purpose (default)
   *   45° — only major slope changes (toe-of-bank)
   */
  thresholdDegrees?: number
  /**
   * Minimum polyline length in metres. Shorter polylines are discarded
   * as noise. Default: 0 (keep all).
   */
  minPolylineLength?: number
  /**
   * Maximum gap (in metres) between two candidate edge endpoints for them
   * to be stitched into the same polyline. Default: 0.01 m (1 cm).
   */
  stitchTolerance?: number
}

export interface ExtractedBreakline {
  /** Ordered polyline points (easting, northing). */
  points: Array<{ easting: number; northing: number }>
  /** Dihedral angle (degrees) — maximum along the polyline. */
  maxDihedral: number
  /** Mean dihedral angle (degrees) along the polyline. */
  meanDihedral: number
  /** Number of edges stitched into this polyline. */
  edgeCount: number
  /** Polyline length in metres (sum of segment lengths). */
  length: number
  /** Suggested classification based on dihedral angle. */
  classification: 'ridge' | 'slope-change' | 'minor'
}

export interface BreaklineExtractionResult {
  /** Stitched breaklines sorted by max dihedral (descending). */
  breaklines: ExtractedBreakline[]
  /** Total candidate edges (before stitching). */
  candidateEdgeCount: number
  /** Total interior edges examined. */
  interiorEdgeCount: number
  /** Total edges in the TIN (including boundary). */
  totalEdgeCount: number
  /** Threshold used (degrees). */
  threshold: number
}

// ─── Vector Math ────────────────────────────────────────────────────────────

function subtract(a: Vec3, b: Vec3): Vec3 {
  return { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z }
}

function cross(a: Vec3, b: Vec3): Vec3 {
  return {
    x: a.y * b.z - a.z * b.y,
    y: a.z * b.x - a.x * b.z,
    z: a.x * b.y - a.y * b.x,
  }
}

function dot(a: Vec3, b: Vec3): number {
  return a.x * b.x + a.y * b.y + a.z * b.z
}

function length(a: Vec3): number {
  return Math.sqrt(a.x * a.x + a.y * a.y + a.z * a.z)
}

function normalize(a: Vec3): Vec3 {
  const len = length(a)
  if (len < 1e-12) return { x: 0, y: 0, z: 0 }
  return { x: a.x / len, y: a.y / len, z: a.z / len }
}

/**
 * Compute the unit normal vector of a triangle (right-hand rule).
 * Returns (0,0,0) for degenerate triangles.
 */
export function triangleNormal(tri: Triangle): Vec3 {
  const p1 = toVec3(tri.p1)
  const p2 = toVec3(tri.p2)
  const p3 = toVec3(tri.p3)
  const u = subtract(p2, p1)
  const v = subtract(p3, p1)
  return normalize(cross(u, v))
}

function toVec3(p: SpotHeight): Vec3 {
  return { x: p.easting, y: p.northing, z: p.elevation }
}

/**
 * Compute the angle (degrees) between two triangle normals — i.e., the
 * "bend angle" of the surface along their shared edge.
 *
 *   0°   → normals are parallel → triangles are coplanar (flat terrain)
 *   90°  → normals are perpendicular → surface folds 90° (sharp ridge)
 *   180° → normals are anti-parallel → surface folds back on itself
 *
 * Note: this is the angle between normals, NOT the interior dihedral
 * angle (which is the supplementary, π − θ). For breakline detection
 * we want the bend angle: 0° = flat, larger = more folded.
 *
 * Callers should orient normals consistently (e.g., flip to point
 * upward) before calling this function to avoid false positives from
 * inconsistent triangle winding.
 */
export function dihedralAngle(n1: Vec3, n2: Vec3): number {
  const d = dot(n1, n2)
  // Clamp to [-1, 1] to avoid NaN from floating-point error
  const clamped = Math.max(-1, Math.min(1, d))
  return (Math.acos(clamped) * 180) / Math.PI
}

/**
 * Flip a normal so its Z component is non-negative. Used to give
 * inconsistently-wound triangles a consistent orientation before
 * computing dihedral angles.
 */
export function orientUpward(n: Vec3): Vec3 {
  return n.z < 0 ? { x: -n.x, y: -n.y, z: -n.z } : n
}

// ─── Edge Adjacency ─────────────────────────────────────────────────────────

interface EdgeKey {
  /** Canonical key: smaller index first, joined by '|'. */
  key: string
  a: SpotHeight
  b: SpotHeight
  triangleIndices: number[]
}

function edgeKey(p1: SpotHeight, p2: SpotHeight, pointIndex: Map<SpotHeight, number>): string {
  const i1 = pointIndex.get(p1) ?? -1
  const i2 = pointIndex.get(p2) ?? -1
  const lo = Math.min(i1, i2)
  const hi = Math.max(i1, i2)
  return `${lo}|${hi}`
}

function buildEdgeAdjacency(
  triangles: Triangle[],
  points: SpotHeight[]
): { edges: Map<string, EdgeKey>; pointIndex: Map<SpotHeight, number> } {
  const pointIndex = new Map<SpotHeight, number>()
  points.forEach((p, i) => pointIndex.set(p, i))

  const edges = new Map<string, EdgeKey>()
  for (let tIdx = 0; tIdx < triangles.length; tIdx++) {
    const tri = triangles[tIdx]
    const ePairs: [SpotHeight, SpotHeight][] = [
      [tri.p1, tri.p2],
      [tri.p2, tri.p3],
      [tri.p3, tri.p1],
    ]
    for (const [a, b] of ePairs) {
      const key = edgeKey(a, b, pointIndex)
      const existing = edges.get(key)
      if (existing) {
        existing.triangleIndices.push(tIdx)
      } else {
        edges.set(key, { key, a, b, triangleIndices: [tIdx] })
      }
    }
  }
  return { edges, pointIndex }
}

// ─── Extraction ─────────────────────────────────────────────────────────────

/** A single TIN edge flagged as a breakline candidate. */
interface CandidateEdge {
  a: { easting: number; northing: number }
  b: { easting: number; northing: number }
  dihedral: number
}

/**
 * Extract breaklines from a TIN mesh.
 *
 * @param surface  - TIN surface (use `buildTINSurface` to construct)
 * @param options  - Extraction options (threshold, min length, etc.)
 */
export function extractBreaklines(
  surface: TINSurface,
  options: BreaklineExtractionOptions = {}
): BreaklineExtractionResult {
  const threshold = options.thresholdDegrees ?? 30
  const minLen = options.minPolylineLength ?? 0
  const stitchTol = options.stitchTolerance ?? 0.01

  const { triangles, points } = surface
  if (triangles.length === 0) {
    return {
      breaklines: [],
      candidateEdgeCount: 0,
      interiorEdgeCount: 0,
      totalEdgeCount: 0,
      threshold,
    }
  }

  // 1. Compute triangle normals (oriented upward for consistent winding)
  const normals = triangles.map(t => orientUpward(triangleNormal(t)))

  // 2. Build edge adjacency
  const { edges } = buildEdgeAdjacency(triangles, points)
  const allEdges = Array.from(edges.values())
  const interiorEdges = allEdges.filter(e => e.triangleIndices.length === 2)

  // 3. For each interior edge, compute dihedral angle, collect candidates
  const candidates: CandidateEdge[] = []

  for (const edge of interiorEdges) {
    const [t1, t2] = edge.triangleIndices
    const angle = dihedralAngle(normals[t1], normals[t2])
    if (angle > threshold) {
      candidates.push({
        a: { easting: edge.a.easting, northing: edge.a.northing },
        b: { easting: edge.b.easting, northing: edge.b.northing },
        dihedral: angle,
      })
    }
  }

  // 4. Stitch candidate edges into polylines
  const breaklines = stitchCandidates(candidates, stitchTol)

  // 5. Filter by minimum length
  const filtered = breaklines.filter(bl => bl.length >= minLen)

  // 6. Sort by max dihedral (descending)
  filtered.sort((a, b) => b.maxDihedral - a.maxDihedral)

  return {
    breaklines: filtered,
    candidateEdgeCount: candidates.length,
    interiorEdgeCount: interiorEdges.length,
    totalEdgeCount: allEdges.length,
    threshold,
  }
}

/**
 * Convenience wrapper: build a TIN from raw points and extract breaklines.
 */
export function extractBreaklinesFromPoints(
  points: SpotHeight[],
  options: BreaklineExtractionOptions = {}
): BreaklineExtractionResult {
  const surface = buildTINSurface(points)
  return extractBreaklines(surface, options)
}

// ─── Stitching ──────────────────────────────────────────────────────────────

/**
 * Stitch candidate edges into ordered polylines.
 *
 * Uses a spatial hash on edge endpoints to find connected components.
 * Each connected component becomes one polyline. Branches (3+ edges
 * meeting at a point) are split into separate polylines.
 */
function stitchCandidates(
  candidates: CandidateEdge[],
  tolerance: number
): ExtractedBreakline[] {
  if (candidates.length === 0) return []

  const ptKey = (p: { easting: number; northing: number }): string =>
    `${Math.round(p.easting / tolerance)},${Math.round(p.northing / tolerance)}`

  // Build endpoint → candidate indices map
  const endpointMap = new Map<string, number[]>()
  candidates.forEach((c, i) => {
    const k1 = ptKey(c.a)
    const k2 = ptKey(c.b)
    if (!endpointMap.has(k1)) endpointMap.set(k1, [])
    if (!endpointMap.has(k2)) endpointMap.set(k2, [])
    endpointMap.get(k1)!.push(i)
    endpointMap.get(k2)!.push(i)
  })

  const used = new Array(candidates.length).fill(false)
  const polylines: ExtractedBreakline[] = []

  function tryExtend(
    polyline: Array<{ easting: number; northing: number }>,
    dihedrals: number[],
    fromStart: boolean
  ): void {
    let extended = true
    while (extended) {
      extended = false
      const endpoint = fromStart ? polyline[0] : polyline[polyline.length - 1]
      const key = ptKey(endpoint)
      const candidateIndices = endpointMap.get(key) || []
      for (const ci of candidateIndices) {
        if (used[ci]) continue
        const c = candidates[ci]
        // Match either endpoint
        const aMatches = ptsClose(c.a, endpoint, tolerance)
        const bMatches = ptsClose(c.b, endpoint, tolerance)
        if (aMatches) {
          if (fromStart) polyline.unshift(c.b)
          else polyline.push(c.b)
          dihedrals.push(c.dihedral)
          used[ci] = true
          extended = true
          break
        } else if (bMatches) {
          if (fromStart) polyline.unshift(c.a)
          else polyline.push(c.a)
          dihedrals.push(c.dihedral)
          used[ci] = true
          extended = true
          break
        }
      }
    }
  }

  for (let i = 0; i < candidates.length; i++) {
    if (used[i]) continue
    used[i] = true
    const polyline = [candidates[i].a, candidates[i].b]
    const dihedrals = [candidates[i].dihedral]

    // Extend forward (from end)
    tryExtend(polyline, dihedrals, false)
    // Extend backward (from start)
    tryExtend(polyline, dihedrals, true)

    // Compute stats
    const maxDihedral = Math.max(...dihedrals)
    const meanDihedral = dihedrals.reduce((a, b) => a + b, 0) / dihedrals.length
    const length = polylineLength(polyline)
    const classification: ExtractedBreakline['classification'] =
      maxDihedral >= 60 ? 'ridge' : maxDihedral >= 40 ? 'slope-change' : 'minor'

    polylines.push({
      points: polyline,
      maxDihedral,
      meanDihedral,
      edgeCount: dihedrals.length,
      length,
      classification,
    })
  }

  return polylines
}

function ptsClose(
  a: { easting: number; northing: number },
  b: { easting: number; northing: number },
  tol: number
): boolean {
  return (
    Math.abs(a.easting - b.easting) < tol * 100 &&
    Math.abs(a.northing - b.northing) < tol * 100
  )
}

function polylineLength(polyline: Array<{ easting: number; northing: number }>): number {
  let total = 0
  for (let i = 1; i < polyline.length; i++) {
    const dx = polyline[i].easting - polyline[i - 1].easting
    const dy = polyline[i].northing - polyline[i - 1].northing
    total += Math.sqrt(dx * dx + dy * dy)
  }
  return total
}

// ─── Conversion Helpers ─────────────────────────────────────────────────────

/**
 * Convert extracted breaklines to the Breakline[] format used by
 * `src/lib/engine/contours.ts` for use in further TIN re-computation.
 *
 * Note: extracted breaklines have 2D points only — elevation is set to
 * NaN because the extraction algorithm works in the XY plane. To use as
 * TIN constraints, the caller must interpolate elevations from the
 * original TIN surface.
 */
export function toBreaklineArray(
  result: BreaklineExtractionResult,
  elevations?: (easting: number, northing: number) => number | null
): Breakline[] {
  const out: Breakline[] = []
  for (const bl of result.breaklines) {
    if (bl.points.length < 2) continue
    for (let i = 0; i < bl.points.length - 1; i++) {
      const a = bl.points[i]
      const b = bl.points[i + 1]
      const z1 = elevations?.(a.easting, a.northing) ?? 0
      const z2 = elevations?.(b.easting, b.northing) ?? 0
      out.push({
        start: {
          name: `BL_${out.length}_a`,
          easting: a.easting,
          northing: a.northing,
          elevation: z1,
        },
        end: {
          name: `BL_${out.length}_b`,
          easting: b.easting,
          northing: b.northing,
          elevation: z2,
        },
      })
    }
  }
  return out
}

/**
 * Convert extracted breaklines to GeoJSON FeatureCollection of LineStrings.
 */
export function toGeoJSON(
  result: BreaklineExtractionResult
): {
  type: 'FeatureCollection'
  features: Array<{
    type: 'Feature'
    geometry: {
      type: 'LineString'
      coordinates: Array<[number, number]>
    }
    properties: {
      maxDihedral: number
      meanDihedral: number
      edgeCount: number
      length: number
      classification: string
    }
  }>
} {
  return {
    type: 'FeatureCollection',
    features: result.breaklines.map(bl => ({
      type: 'Feature' as const,
      geometry: {
        type: 'LineString' as const,
        coordinates: bl.points.map(p => [p.easting, p.northing] as [number, number]),
      },
      properties: {
        maxDihedral: Math.round(bl.maxDihedral * 100) / 100,
        meanDihedral: Math.round(bl.meanDihedral * 100) / 100,
        edgeCount: bl.edgeCount,
        length: Math.round(bl.length * 1000) / 1000,
        classification: bl.classification,
      },
    })),
  }
}

/**
 * Calculation standard: N.N. Basak — Surveying and Levelling
 * - No intermediate rounding
 * - Full floating point precision throughout
 * - Round only at final display layer
 * - Bearings: WCB 0-360° clockwise from North
 */

// METARDU Engine - COGO (Coordinate Geometry)

import { Point2D, COGOIntersection, COGORadiation, COOResection } from './types';
import { toRadians, toDegrees } from './angles';
import { distanceBearing } from './distance';

export function bearingIntersection(
  stationA: Point2D,
  bearingA: number,
  stationB: Point2D,
  bearingB: number
): COGOIntersection | null {
  // Intersection of two rays defined by station + bearing (WCB from North)
  // A + t*vA = B + u*vB
  const radA = toRadians(bearingA);
  const radB = toRadians(bearingB);

  const vAx = Math.sin(radA);
  const vAy = Math.cos(radA);
  const vBx = Math.sin(radB);
  const vBy = Math.cos(radB);

  const dx = stationB.easting - stationA.easting;
  const dy = stationB.northing - stationA.northing;

  const det = vAx * (-vBy) - vAy * (-vBx); // = vAy*vBx - vAx*vBy
  if (Math.abs(det) < 1e-12) return null; // parallel / nearly parallel

  // Solve:
  // t*vAx - u*vBx = dx
  // t*vAy - u*vBy = dy
  const t = (dx * (-vBy) - dy * (-vBx)) / det;
  const u = (vAx * dy - vAy * dx) / det;

  const point: Point2D = {
    easting: stationA.easting + t * vAx,
    northing: stationA.northing + t * vAy,
  };
  
  return {
    point,
    distanceFromA: t,
    distanceFromB: u
  };
}

export function distanceIntersection(
  stationA: Point2D,
  distanceA: number,
  stationB: Point2D,
  distanceB: number
): [Point2D, Point2D] | null {
  // Circle-circle intersection
  const dx = stationB.easting - stationA.easting;
  const dy = stationB.northing - stationA.northing;
  const distAB = Math.sqrt(dx * dx + dy * dy);
  
  // Check if circles intersect
  if (distAB > distanceA + distanceB || distAB < Math.abs(distanceA - distanceB) || distAB === 0) {
    return null;
  }
  
  const a = (distanceA * distanceA - distanceB * distanceB + distAB * distAB) / (2 * distAB);
  const h = Math.sqrt(distanceA * distanceA - a * a);
  
  const cx = stationA.easting + a * dx / distAB;
  const cy = stationA.northing + a * dy / distAB;
  
  const point1: Point2D = {
    easting: cx + h * dy / distAB,
    northing: cy - h * dx / distAB
  };
  
  const point2: Point2D = {
    easting: cx - h * dy / distAB,
    northing: cy + h * dx / distAB
  };
  
  return [point1, point2];
}

export function tienstraResection(
  p1: Point2D,
  p2: Point2D,
  p3: Point2D,
  angle12: number,  // Angle at unknown station between rays to P1 and P2 (degrees)
  angle23: number   // Angle at unknown station between rays to P2 and P3 (degrees)
): COOResection | null {
  // Tienstra's method for three-point resection (planimetric)
  // Assumption for inputs:
  // - angle12 = angle between lines P->P1 and P->P2
  // - angle23 = angle between lines P->P2 and P->P3
  // Then angle31 = 360° - (angle12 + angle23)

  const angle31 = 360 - (angle12 + angle23)
  if (angle12 <= 0 || angle23 <= 0 || angle31 <= 0) return null

  // Triangle angles at control points A=p1, B=p2, C=p3
  const a = distanceBearing(p2, p3).distance // side a opposite p1
  const b = distanceBearing(p3, p1).distance // side b opposite p2
  const c = distanceBearing(p1, p2).distance // side c opposite p3

  const clamp = (x: number) => Math.max(-1, Math.min(1, x))

  const A = Math.acos(clamp((b * b + c * c - a * a) / (2 * b * c))) // at p1
  const B = Math.acos(clamp((a * a + c * c - b * b) / (2 * a * c))) // at p2
  const C = Math.acos(clamp((a * a + b * b - c * c) / (2 * a * b))) // at p3

  // Map observed angles at unknown station P to α, β, γ:
  // α = ∠(P2 P P3) = angle23 (opposite p1)
  // γ = ∠(P1 P P2) = angle12 (opposite p3)
  // β = ∠(P3 P P1) = angle31 (opposite p2)
  const alpha = toRadians(angle23)
  const beta = toRadians(angle31)
  const gamma = toRadians(angle12)

  const cot = (r: number) => 1 / Math.tan(r)

  const aW = 1 / (cot(alpha) - cot(A))
  const bW = 1 / (cot(beta) - cot(B))
  const cW = 1 / (cot(gamma) - cot(C))

  const sum = aW + bW + cW
  if (!isFinite(sum) || Math.abs(sum) < 1e-12) return null

  const point: Point2D = {
    easting: (aW * p1.easting + bW * p2.easting + cW * p3.easting) / sum,
    northing: (aW * p1.northing + bW * p2.northing + cW * p3.northing) / sum,
  }

  const d1 = distanceBearing(point, p1).distance
  const d2 = distanceBearing(point, p2).distance
  const d3 = distanceBearing(point, p3).distance

  return { point, distanceToP1: d1, distanceToP2: d2, distanceToP3: d3 }
}

export function radiation(
  from: Point2D,
  bearing: number,
  distance: number
): COGORadiation {
  const rad = toRadians(bearing);
  const point: Point2D = {
    easting: from.easting + distance * Math.sin(rad),
    northing: from.northing + distance * Math.cos(rad)
  };
  
  return {
    point,
    distance,
    bearing
  };
}

export function offsetPoint(
  point: Point2D,
  bearing: number,
  offset: number
): Point2D {
  const rad = toRadians(bearing);
  return {
    easting: point.easting + offset * Math.sin(rad),
    northing: point.northing + offset * Math.cos(rad)
  };
}

/**
 * METARDU Contour Engine — Delaunay TIN + Marching Triangles
 *
 * Phase 25 upgrade: replaces O(n³) brute-force triangulation with
 * Delaunator-based Delaunay triangulation. Handles 10,000+ points.
 *
 * Features:
 *  - Delaunay triangulation via Delaunator (O(n log n))
 *  - Breakline enforcement via edge constraint (flip edges that cross breaklines)
 *  - Contour line threading (ordered polylines, not loose pairs)
 *  - TIN surface interpolation at any (E, N) point
 *  - Index contour marking (every 5th contour)
 *
 * Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapter 17
 * Source: USACE EM 1110-1-1005 — Topographic Survey Standards
 */

import Delaunator from 'delaunator'

export interface SpotHeight {
  name: string
  easting: number
  northing: number
  elevation: number
}

export interface ContourLine {
  elevation: number
  points: Array<{ easting: number; northing: number }>
  isIndex: boolean
}

export interface Triangle {
  p1: SpotHeight
  p2: SpotHeight
  p3: SpotHeight
}

export interface Breakline {
  start: SpotHeight
  end: SpotHeight
}

export interface TINSurface {
  triangles: Triangle[]
  points: SpotHeight[]
  bounds: { minE: number; maxE: number; minN: number; maxN: number }
}

// ─── Delaunay Triangulation ─────────────────────────────────────────────────

/**
 * Build a Delaunay TIN from spot heights using Delaunator.
 * O(n log n) — handles thousands of points efficiently.
 */
export function triangulate(points: SpotHeight[]): Triangle[] {
  if (points.length < 3) return []

  // Delaunator expects flat coordinate array [x0,y0, x1,y1, ...]
  const coords = new Float64Array(points.length * 2)
  for (let i = 0; i < points.length; i++) {
    coords[2 * i] = points[i].easting
    coords[2 * i + 1] = points[i].northing
  }

  let delaunay: Delaunator<Float64Array>
  try {
    delaunay = new Delaunator(coords)
  } catch {
    // Fallback: all points may be collinear
    return []
  }

  const triangles: Triangle[] = []
  const triIndices = delaunay.triangles

  for (let i = 0; i < triIndices.length; i += 3) {
    const a = triIndices[i]
    const b = triIndices[i + 1]
    const c = triIndices[i + 2]

    // Skip degenerate triangles (zero area)
    const area = Math.abs(
      (points[b].easting - points[a].easting) * (points[c].northing - points[a].northing) -
      (points[c].easting - points[a].easting) * (points[b].northing - points[a].northing)
    )
    if (area < 1e-10) continue

    triangles.push({
      p1: points[a],
      p2: points[b],
      p3: points[c],
    })
  }

  return triangles
}

/**
 * Build a full TIN surface object with bounds metadata.
 */
export function buildTINSurface(points: SpotHeight[], breaklines?: Breakline[]): TINSurface {
  let triangles = triangulate(points)

  // Apply breakline constraints if provided
  if (breaklines && breaklines.length > 0) {
    triangles = enforceBreaklines(triangles, breaklines, points)
  }

  let minE = Infinity, maxE = -Infinity
  let minN = Infinity, maxN = -Infinity
  for (const p of points) {
    if (p.easting < minE) minE = p.easting
    if (p.easting > maxE) maxE = p.easting
    if (p.northing < minN) minN = p.northing
    if (p.northing > maxN) maxN = p.northing
  }

  return {
    triangles,
    points,
    bounds: { minE, maxE, minN, maxN },
  }
}

// ─── Breakline Enforcement ──────────────────────────────────────────────────

/**
 * Enforce breaklines by removing triangles whose edges cross breaklines
 * and rebuilding with breakline vertices inserted.
 *
 * Simple approach: for each breakline, check if any triangle edge crosses it.
 * If so, split the crossing edge at the intersection and re-triangulate the
 * affected region. This is a simplified constrained Delaunay approach.
 */
function enforceBreaklines(
  triangles: Triangle[],
  breaklines: Breakline[],
  points: SpotHeight[]
): Triangle[] {
  // For each breakline, check triangle edges
  // If a triangle edge crosses a breakline, flip it if the resulting
  // triangulation would not violate the breakline constraint
  let result = [...triangles]

  for (const bl of breaklines) {
    const newTriangles: Triangle[] = []

    for (const tri of result) {
      const edges: [SpotHeight, SpotHeight][] = [
        [tri.p1, tri.p2],
        [tri.p2, tri.p3],
        [tri.p3, tri.p1],
      ]

      let crosses = false
      for (const [a, b] of edges) {
        if (edgesCross(a, b, bl.start, bl.end)) {
          crosses = true
          break
        }
      }

      if (!crosses) {
        newTriangles.push(tri)
      } else {
        // Split triangle along breakline intersection
        const split = splitTriangleByBreakline(tri, bl, points)
        newTriangles.push(...split)
      }
    }

    result = newTriangles
  }

  return result
}

/** Check if two line segments cross (proper intersection, not touching). */
function edgesCross(
  a1: SpotHeight, a2: SpotHeight,
  b1: SpotHeight, b2: SpotHeight
): boolean {
  const d1 = cross2D(b1, b2, a1)
  const d2 = cross2D(b1, b2, a2)
  const d3 = cross2D(a1, a2, b1)
  const d4 = cross2D(a1, a2, b2)

  if (((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) &&
      ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0))) {
    return true
  }

  return false
}

function cross2D(o: SpotHeight, a: SpotHeight, b: SpotHeight): number {
  return (a.easting - o.easting) * (b.northing - o.northing) -
         (a.northing - o.northing) * (b.easting - o.easting)
}

/**
 * Split a triangle that is crossed by a breakline.
 * Finds the intersection point and creates sub-triangles.
 */
function splitTriangleByBreakline(
  tri: Triangle,
  bl: Breakline,
  points: SpotHeight[]
): Triangle[] {
  const edges: [SpotHeight, SpotHeight, SpotHeight][] = [
    [tri.p1, tri.p2, tri.p3],
    [tri.p2, tri.p3, tri.p1],
    [tri.p3, tri.p1, tri.p2],
  ]

  for (const [a, b, c] of edges) {
    if (edgesCross(a, b, bl.start, bl.end)) {
      const inter = lineLineIntersection(a, b, bl.start, bl.end)
      if (!inter) continue

      // Interpolate elevation at intersection point
      const t = Math.sqrt(
        (inter.easting - a.easting) ** 2 + (inter.northing - a.northing) ** 2
      ) / Math.sqrt(
        (b.easting - a.easting) ** 2 + (b.northing - a.northing) ** 2
      )
      const elev = a.elevation + t * (b.elevation - a.elevation)

      const interPt: SpotHeight = {
        name: `BL_${points.length}`,
        easting: inter.easting,
        northing: inter.northing,
        elevation: elev,
      }

      // Create two sub-triangles
      return [
        { p1: a, p2: interPt, p3: c },
        { p1: interPt, p2: b, p3: c },
      ]
    }
  }

  // No crossing found (edge case) — return original
  return [tri]
}

function lineLineIntersection(
  a1: SpotHeight, a2: SpotHeight,
  b1: SpotHeight, b2: SpotHeight
): { easting: number; northing: number } | null {
  const dx1 = a2.easting - a1.easting
  const dy1 = a2.northing - a1.northing
  const dx2 = b2.easting - b1.easting
  const dy2 = b2.northing - b1.northing

  const denom = dx1 * dy2 - dy1 * dx2
  if (Math.abs(denom) < 1e-12) return null

  const t = ((b1.easting - a1.easting) * dy2 - (b1.northing - a1.northing) * dx2) / denom

  return {
    easting: a1.easting + t * dx1,
    northing: a1.northing + t * dy1,
  }
}

// ─── Contour Generation (Marching Triangles) ────────────────────────────────

function interpolateEdge(
  p1: SpotHeight,
  p2: SpotHeight,
  contourElev: number
): { easting: number; northing: number } | null {
  const minElev = Math.min(p1.elevation, p2.elevation)
  const maxElev = Math.max(p1.elevation, p2.elevation)

  if (contourElev <= minElev || contourElev >= maxElev) return null

  const t = (contourElev - p1.elevation) / (p2.elevation - p1.elevation)

  return {
    easting: p1.easting + t * (p2.easting - p1.easting),
    northing: p1.northing + t * (p2.northing - p1.northing)
  }
}

/**
 * Generate contour lines from spot heights using Delaunay TIN.
 *
 * Algorithm: Marching Triangles
 * 1. Build Delaunay triangulation
 * 2. For each contour elevation, walk through all triangles
 * 3. Find edge crossings and collect contour segments
 * 4. Thread segments into ordered polylines
 *
 * @param points - Array of spot heights
 * @param interval - Contour interval in metres
 * @param indexInterval - Index contour interval (default: 5× interval)
 * @param breaklines - Optional breaklines to constrain the TIN
 */
export function generateContours(
  points: SpotHeight[],
  interval: number,
  indexInterval?: number,
  breaklines?: Breakline[]
): ContourLine[] {
  if (points.length < 3) return []

  const effectiveIndexInterval = indexInterval ?? interval * 5

  // Build TIN
  let triangles: Triangle[]
  if (breaklines && breaklines.length > 0) {
    const surface = buildTINSurface(points, breaklines)
    triangles = surface.triangles
  } else {
    triangles = triangulate(points)
  }

  if (triangles.length === 0) return []

  const elevations = points.map(p => p.elevation)
  const minElev = Math.min(...elevations)
  const maxElev = Math.max(...elevations)

  const firstContour = Math.ceil(minElev / interval) * interval
  const contourElevations: number[] = []
  for (let e = firstContour; e <= maxElev; e += interval) {
    contourElevations.push(Math.round(e * 1e6) / 1e6) // avoid floating point drift
  }

  const contourLines: ContourLine[] = []

  for (const contourElev of contourElevations) {
    // Collect contour segments from all triangles
    const segments: Array<[
      { easting: number; northing: number },
      { easting: number; northing: number }
    ]> = []

    for (const tri of triangles) {
      const edges: [SpotHeight, SpotHeight][] = [
        [tri.p1, tri.p2],
        [tri.p2, tri.p3],
        [tri.p3, tri.p1]
      ]

      const crossings: Array<{ easting: number; northing: number }> = []

      for (const [a, b] of edges) {
        const crossing = interpolateEdge(a, b, contourElev)
        if (crossing) crossings.push(crossing)
      }

      if (crossings.length === 2) {
        segments.push([crossings[0], crossings[1]])
      }
    }

    if (segments.length > 0) {
      // Thread segments into ordered polylines
      const polylines = threadSegments(segments)

      for (const polyline of polylines) {
        if (polyline.length >= 2) {
          const isIndex = Math.abs(contourElev % effectiveIndexInterval) < interval * 0.01

          contourLines.push({
            elevation: contourElev,
            points: polyline,
            isIndex,
          })
        }
      }
    }
  }

  return contourLines
}

/**
 * Thread unordered line segments into ordered polylines.
 *
 * Uses a spatial hash to efficiently find matching endpoints.
 * Produces continuous polylines by connecting segments whose
 * endpoints are within a small tolerance.
 */
function threadSegments(
  segments: Array<[
    { easting: number; northing: number },
    { easting: number; northing: number }
  ]>
): Array<Array<{ easting: number; northing: number }>> {
  if (segments.length === 0) return []

  const TOLERANCE = 1e-6
  const used = new Array(segments.length).fill(false)
  const polylines: Array<Array<{ easting: number; northing: number }>> = []

  function ptKey(p: { easting: number; northing: number }): string {
    return `${Math.round(p.easting / TOLERANCE)},${Math.round(p.northing / TOLERANCE)}`
  }

  function ptsMatch(
    a: { easting: number; northing: number },
    b: { easting: number; northing: number }
  ): boolean {
    return Math.abs(a.easting - b.easting) < TOLERANCE * 100 &&
           Math.abs(a.northing - b.northing) < TOLERANCE * 100
  }

  // Build spatial index: endpoint key → segment indices
  const endpointMap = new Map<string, number[]>()
  for (let i = 0; i < segments.length; i++) {
    const k0 = ptKey(segments[i][0])
    const k1 = ptKey(segments[i][1])
    if (!endpointMap.has(k0)) endpointMap.set(k0, [])
    if (!endpointMap.has(k1)) endpointMap.set(k1, [])
    endpointMap.get(k0)!.push(i)
    endpointMap.get(k1)!.push(i)
  }

  for (let startIdx = 0; startIdx < segments.length; startIdx++) {
    if (used[startIdx]) continue

    used[startIdx] = true
    const polyline = [segments[startIdx][0], segments[startIdx][1]]

    // Extend forward from end
    let extended = true
    while (extended) {
      extended = false
      const endPt = polyline[polyline.length - 1]
      const key = ptKey(endPt)
      const candidates = endpointMap.get(key) || []

      for (const ci of candidates) {
        if (used[ci]) continue
        const seg = segments[ci]

        if (ptsMatch(seg[0], endPt)) {
          polyline.push(seg[1])
          used[ci] = true
          extended = true
          break
        }
        if (ptsMatch(seg[1], endPt)) {
          polyline.push(seg[0])
          used[ci] = true
          extended = true
          break
        }
      }
    }

    // Extend backward from start
    extended = true
    while (extended) {
      extended = false
      const startPt = polyline[0]
      const key = ptKey(startPt)
      const candidates = endpointMap.get(key) || []

      for (const ci of candidates) {
        if (used[ci]) continue
        const seg = segments[ci]

        if (ptsMatch(seg[0], startPt)) {
          polyline.unshift(seg[1])
          used[ci] = true
          extended = true
          break
        }
        if (ptsMatch(seg[1], startPt)) {
          polyline.unshift(seg[0])
          used[ci] = true
          extended = true
          break
        }
      }
    }

    polylines.push(polyline)
  }

  return polylines
}

// ─── TIN Surface Interpolation ──────────────────────────────────────────────

/**
 * Interpolate elevation at a point (E, N) using the TIN surface.
 * Uses barycentric coordinates within the containing triangle.
 *
 * Returns null if the point falls outside the TIN.
 */
export function interpolateElevation(
  surface: TINSurface,
  easting: number,
  northing: number
): number | null {
  for (const tri of surface.triangles) {
    const elev = barycentricInterpolation(tri, easting, northing)
    if (elev !== null) return elev
  }
  return null
}

/**
 * Barycentric interpolation within a triangle.
 * Returns the interpolated elevation if point is inside, null otherwise.
 */
function barycentricInterpolation(
  tri: Triangle,
  e: number,
  n: number
): number | null {
  const { p1, p2, p3 } = tri

  const denom = (p2.northing - p3.northing) * (p1.easting - p3.easting) +
                (p3.easting - p2.easting) * (p1.northing - p3.northing)

  if (Math.abs(denom) < 1e-12) return null

  const w1 = ((p2.northing - p3.northing) * (e - p3.easting) +
              (p3.easting - p2.easting) * (n - p3.northing)) / denom

  const w2 = ((p3.northing - p1.northing) * (e - p3.easting) +
              (p1.easting - p3.easting) * (n - p3.northing)) / denom

  const w3 = 1 - w1 - w2

  // Check if point is inside triangle (with small tolerance for edges)
  const eps = -1e-8
  if (w1 < eps || w2 < eps || w3 < eps) return null

  return w1 * p1.elevation + w2 * p2.elevation + w3 * p3.elevation
}

// ─── Volume Computation from TIN ────────────────────────────────────────────

/**
 * Compute the volume between a TIN surface and a reference plane.
 *
 * @param surface - TIN surface
 * @param referencePlane - Elevation of the reference plane (m)
 * @returns { cut, fill, net } volumes in cubic metres
 */
export function computeVolumeFromTIN(
  surface: TINSurface,
  referencePlane: number
): { cut: number; fill: number; net: number } {
  let cut = 0
  let fill = 0

  for (const tri of surface.triangles) {
    // Average elevation of triangle
    const avgElev = (tri.p1.elevation + tri.p2.elevation + tri.p3.elevation) / 3

    // Triangle area (horizontal projection)
    const area = Math.abs(
      (tri.p2.easting - tri.p1.easting) * (tri.p3.northing - tri.p1.northing) -
      (tri.p3.easting - tri.p1.easting) * (tri.p2.northing - tri.p1.northing)
    ) / 2

    // Prismoidal volume for this triangle
    const diff = avgElev - referencePlane
    const vol = area * Math.abs(diff)

    if (diff > 0) {
      cut += vol
    } else {
      fill += vol
    }
  }

  return { cut, fill, net: cut - fill }
}

/**
 * Compute volume between two TIN surfaces (e.g., before/after for earthworks).
 *
 * Samples the difference at a grid and integrates numerically.
 */
export function computeVolumeBetweenSurfaces(
  surface1: TINSurface,
  surface2: TINSurface,
  gridSpacing: number = 1.0
): { cut: number; fill: number; net: number } {
  const minE = Math.max(surface1.bounds.minE, surface2.bounds.minE)
  const maxE = Math.min(surface1.bounds.maxE, surface2.bounds.maxE)
  const minN = Math.max(surface1.bounds.minN, surface2.bounds.minN)
  const maxN = Math.min(surface1.bounds.maxN, surface2.bounds.maxN)

  if (minE >= maxE || minN >= maxN) return { cut: 0, fill: 0, net: 0 }

  let cut = 0
  let fill = 0
  const cellArea = gridSpacing * gridSpacing

  for (let e = minE; e <= maxE; e += gridSpacing) {
    for (let n = minN; n <= maxN; n += gridSpacing) {
      const z1 = interpolateElevation(surface1, e, n)
      const z2 = interpolateElevation(surface2, e, n)

      if (z1 === null || z2 === null) continue

      const diff = z1 - z2
      if (diff > 0) {
        cut += diff * cellArea
      } else {
        fill += Math.abs(diff) * cellArea
      }
    }
  }

  return { cut, fill, net: cut - fill }
}

/**
 * Generate a small demo set of spot heights for the 3D viewer
 * (a 10x10 grid with a smooth bump + noise around an origin).
 */
export function generateDemoData(): SpotHeight[] {
  const points: SpotHeight[] = []
  const cx = 500000
  const cy = 0
  const step = 5
  const n = 10
  let idx = 0
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const easting = cx + (i - n / 2) * step
      const northing = cy + (j - n / 2) * step
      const r = Math.sqrt((i - n / 2) ** 2 + (j - n / 2) ** 2)
      const bump = Math.max(0, 20 - r * 2)
      const elevation = 100 + bump + Math.sin(i * 0.6) * 0.5 + Math.cos(j * 0.5) * 0.5
      points.push({ name: `P${idx++}`, easting, northing, elevation })
    }
  }
  return points
}

/**
 * Cross-Section Volume Calculations — Volume between sequential cross-sections.
 *
 * Calculation standards:
 *   - N.N. Basak, Surveying and Levelling, Ch. 8 — End Area and Prismoidal methods
 *   - Ghilani & Wolf, Elementary Surveying, 16th Ed., §26.3 — Earthwork computation
 *   - RDM 1.1 Kenya 2025, §8 — Volume computation for road/earthwork design
 *
 * Conventions:
 *   - No intermediate rounding; full floating point throughout.
 *   - Positive volume = cut (existing above design).
 *   - Negative volume = fill (existing below design).
 *   - Prismoidal formula used when 3 consecutive sections available with ~equal spacing.
 *   - End-area formula used as fallback or when chainage spacing > 10 m.
 *
 * End-Area Method (Basak §8.2):
 *   V = (L / 2) × (A1 + A2)
 *   where L = distance between sections, A = cross-section area above/below design.
 *
 * Prismoidal Formula (Basak §8.3):
 *   V = (L / 6) × (A1 + 4×Am + A2)
 *   where Am = mid-section area, L = distance between end sections.
 */

// ─── TYPES ─────────────────────────────────────────────────────────────────────

export interface CrossSectionPoint {
  offset: number // horizontal offset from centreline (m)
  rl: number // reduced level (m)
}

export interface CrossSection {
  chainage: number // chainage along centreline (m)
  points: CrossSectionPoint[]
}

export interface SectionVolumeSegment {
  fromChainage: number
  toChainage: number
  distance: number // metres between sections
  endAreaFrom: number // m² (signed: +cut, -fill)
  endAreaTo: number // m² (signed: +cut, -fill)
  midArea?: number // m² (for prismoidal)
  cutVolumeM3: number // positive cut volume
  fillVolumeM3: number // positive fill volume
  netVolumeM3: number // cut − fill (signed)
  method: 'prismoidal' | 'end-area'
}

export interface SectionVolumeResult {
  totalCutVolumeM3: number
  totalFillVolumeM3: number
  netVolumeM3: number
  sections: SectionVolumeSegment[]
  totalLength: number
}

export interface CrossSectionAreaResult {
  chainage: number
  cutArea: number // m² above design
  fillArea: number // m² below design
  netArea: number // signed (+cut, -fill)
  groundLevelRange: { min: number; max: number }
}

// ─── CROSS-SECTION AREA COMPUTATION ───────────────────────────────────────────

/**
 * Compute the area between a cross-section profile and a design level.
 *
 * For each consecutive pair of points in the cross-section:
 *   - If both above design → area is trapezoidal (cut).
 *   - If both below design → area is trapezoidal (fill).
 *   - If one above and one below → split at the design intersection.
 *
 * The area is computed as the integral of the absolute difference between
 * the ground profile and the design level:
 *
 *   Area = Σ |ΔRL| × average_offset_step
 *
 * This uses the trapezoidal rule between consecutive section points.
 *
 * Ref: Ghilani & Wolf, Elementary Surveying, §26.3 — Earthwork cross-section areas.
 *
 * @param section - Cross-section with chainage and profile points
 * @param designLevel - Design formation RL
 * @returns CrossSectionAreaResult with cut, fill, and net areas
 */
export function computeSectionArea(
  section: CrossSection,
  designLevel: number
): CrossSectionAreaResult {
  const points = section.points
  if (points.length < 2) {
    return {
      chainage: section.chainage,
      cutArea: 0,
      fillArea: 0,
      netArea: 0,
      groundLevelRange: { min: designLevel, max: designLevel },
    }
  }

  // Sort by offset
  const sorted = [...points].sort((a, b) => a.offset - b.offset)

  let cutArea = 0
  let fillArea = 0
  let minRL = Infinity
  let maxRL = -Infinity

  for (let i = 0; i < sorted.length - 1; i++) {
    const p1 = sorted[i]
    const p2 = sorted[i + 1]
    const dOffset = p2.offset - p1.offset

    if (dOffset === 0) continue

    minRL = Math.min(minRL, p1.rl, p2.rl)
    maxRL = Math.max(maxRL, p1.rl, p2.rl)

    const h1 = p1.rl - designLevel // + above design, - below
    const h2 = p2.rl - designLevel

    if (h1 >= 0 && h2 >= 0) {
      // Both above design — cut area (trapezoid)
      cutArea += ((h1 + h2) / 2) * dOffset
    } else if (h1 <= 0 && h2 <= 0) {
      // Both below design — fill area (trapezoid)
      fillArea += ((Math.abs(h1) + Math.abs(h2)) / 2) * dOffset
    } else {
      // One above, one below — split at intersection
      // Intersection offset: linear interpolation to find where RL = designLevel
      const t = Math.abs(h1) / (Math.abs(h1) + Math.abs(h2))
      const splitOffset = p1.offset + t * dOffset

      if (h1 > 0 && h2 < 0) {
        // p1 above, p2 below
        cutArea += (h1 / 2) * (splitOffset - p1.offset)
        fillArea += (Math.abs(h2) / 2) * (p2.offset - splitOffset)
      } else {
        // p1 below, p2 above
        fillArea += (Math.abs(h1) / 2) * (splitOffset - p1.offset)
        cutArea += (h2 / 2) * (p2.offset - splitOffset)
      }
    }
  }

  return {
    chainage: section.chainage,
    cutArea,
    fillArea,
    netArea: cutArea - fillArea,
    groundLevelRange: { min: minRL, max: maxRL },
  }
}

// ─── CROSS-SECTION VOLUME COMPUTATION ─────────────────────────────────────────

/**
 * Compute volumes between sequential cross-sections.
 *
 * For each pair of consecutive sections:
 *   - If spacing > 10m OR no mid-section: use End-Area method.
 *     V = (L/2) × (A1 + A2)  — Basak §8.2
 *
 *   - If 3 sections available with roughly equal spacing (±30%): use Prismoidal.
 *     V = (L/6) × (A1 + 4×Am + A2)  — Basak §8.3
 *
 * Cut and fill are separated:
 *   - Cut volume from cut areas of both sections.
 *   - Fill volume from fill areas of both sections.
 *
 * Ref: RDM 1.1 Kenya 2025 §8 — "Volume computation shall use the prismoidal
 *      formula where possible, end-area as fallback."
 *
 * @param sections - Array of cross-sections sorted by chainage
 * @param designLevel - Design formation RL
 * @returns SectionVolumeResult with total and per-segment volumes
 */
export function computeCrossSectionVolumes(
  sections: CrossSection[],
  designLevel: number
): SectionVolumeResult {
  if (sections.length < 2) {
    throw new Error('At least 2 cross-sections required for volume computation.')
  }

  // Sort by chainage
  const sorted = [...sections].sort((a, b) => a.chainage - b.chainage)

  // Compute areas for all sections
  const areaResults = sorted.map(s => computeSectionArea(s, designLevel))

  const segments: SectionVolumeSegment[] = []
  let totalCut = 0
  let totalFill = 0

  let i = 0
  while (i < sorted.length - 1) {
    const s1 = areaResults[i]
    const s2 = areaResults[i + 1]
    const L = s2.chainage - s1.chainage

    if (L <= 0) {
      i++
      continue
    }

    // Check if we can use prismoidal (need a mid-section with ~equal spacing)
    let usePrismoidal = false
    let midResult: CrossSectionAreaResult | null = null
    let s3Result: CrossSectionAreaResult | null = null

    if (i + 2 < sorted.length) {
      const s3 = areaResults[i + 2]
      const L2 = s3.chainage - s2.chainage
      // Check if spacing is roughly equal (within 30%)
      if (Math.abs(L - L2) / Math.max(L, L2) < 0.3 && L <= 10) {
        usePrismoidal = true
        midResult = s2
        s3Result = s3
      }
    }

    let cutVol: number
    let fillVol: number

    if (usePrismoidal && midResult && s3Result) {
      // Prismoidal formula: V = (L_total / 6) × (A1 + 4×Am + A3)
      // s1 = from section, midResult = mid section, s3Result = end section
      const LTotal = s3Result.chainage - s1.chainage
      cutVol = (LTotal / 6) * (s1.cutArea + 4 * midResult.cutArea + s3Result.cutArea)
      fillVol = (LTotal / 6) * (s1.fillArea + 4 * midResult.fillArea + s3Result.fillArea)

      segments.push({
        fromChainage: s1.chainage,
        toChainage: s3Result.chainage,
        distance: LTotal,
        endAreaFrom: s1.netArea,
        endAreaTo: s3Result.netArea,
        midArea: midResult.netArea,
        cutVolumeM3: cutVol,
        fillVolumeM3: fillVol,
        netVolumeM3: cutVol - fillVol,
        method: 'prismoidal',
      })

      i += 2 // Skip the mid-section and end-section (both consumed)
    } else {
      // End-Area method: V = (L / 2) × (A1 + A2)
      cutVol = (L / 2) * (s1.cutArea + s2.cutArea)
      fillVol = (L / 2) * (s1.fillArea + s2.fillArea)

      segments.push({
        fromChainage: s1.chainage,
        toChainage: s2.chainage,
        distance: L,
        endAreaFrom: s1.netArea,
        endAreaTo: s2.netArea,
        cutVolumeM3: cutVol,
        fillVolumeM3: fillVol,
        netVolumeM3: cutVol - fillVol,
        method: 'end-area',
      })

      i += 1
    }

    totalCut += cutVol
    totalFill += fillVol
  }

  const totalLength = sorted[sorted.length - 1].chainage - sorted[0].chainage

  return {
    totalCutVolumeM3: totalCut,
    totalFillVolumeM3: totalFill,
    netVolumeM3: totalCut - totalFill,
    sections: segments,
    totalLength,
  }
}

// ─── CSV PARSING ───────────────────────────────────────────────────────────────

/**
 * Parse CSV text into CrossSection array.
 * Format: chainage,offset,rl (one row per point, grouped by chainage).
 */
export function parseCrossSectionCSV(csv: string): CrossSection[] {
  const lines = csv.trim().split(/\r?\n/)
  const sectionMap = new Map<number, CrossSectionPoint[]>()

  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#') || trimmed.toLowerCase().startsWith('chainage')) continue

    const parts = trimmed.split(/[,\t;]+/)
    if (parts.length >= 3) {
      const chainage = parseFloat(parts[0].trim())
      const offset = parseFloat(parts[1].trim())
      const rl = parseFloat(parts[2].trim())
      if (!isNaN(chainage) && !isNaN(offset) && !isNaN(rl)) {
        if (!sectionMap.has(chainage)) sectionMap.set(chainage, [])
        sectionMap.get(chainage)!.push({ offset, rl })
      }
    }
  }

  return Array.from(sectionMap.entries())
    .sort(([a], [b]) => a - b)
    .map(([chainage, points]) => ({ chainage, points }))
}

/**
 * Export section volume results to CSV.
 */
export function sectionVolumesToCSV(result: SectionVolumeResult): string {
  const header = 'From (m),To (m),Distance (m),From Area (m²),To Area (m²),Cut (m³),Fill (m³),Net (m³),Method'
  const rows = result.sections.map(s =>
    `${s.fromChainage.toFixed(2)},${s.toChainage.toFixed(2)},${s.distance.toFixed(2)},${s.endAreaFrom.toFixed(3)},${s.endAreaTo.toFixed(3)},${s.cutVolumeM3.toFixed(3)},${s.fillVolumeM3.toFixed(3)},${s.netVolumeM3.toFixed(3)},${s.method}`
  )
  return [header, ...rows].join('\n')
}

/**
 * Calculation standard: N.N. Basak — Surveying and Levelling
 * Source: N.N. Basak, Surveying and Levelling, Chapters 14-16
 * Source: Ghilani & Wolf, Elementary Surveying 16th Ed., Chapters 24-25
 * Source: RDM 1.3 Kenya August 2023, Sections 5.2-5.4
 * - No intermediate rounding
 * - Full floating point precision throughout
 * - Round only at final display layer
 */

// METARDU Engine - Curve calculations

import { CurveElements, CurveStakeoutResult, CurveStakeoutPoint } from './types';
import { toRadians, toDegrees, bearingToString } from './angles';

export function curveElements(
  radius: number,
  deflectionAngle: number,
  isExternal?: boolean
): CurveElements {
  const delta = toRadians(deflectionAngle);
  const halfDelta = delta / 2;
  
  // Source: RDM 1.3 Section 5.2 / Basak Chapter 14
  // Tangent length: T = R × tan(Δ/2)
  const T = radius * Math.tan(halfDelta);

  // Arc length: L = R × Δ (radians)
  const L = radius * delta;

  // Long chord: C = 2R × sin(Δ/2)
  const C = 2 * radius * Math.sin(halfDelta);

  // External distance: E = R × (sec(Δ/2) - 1)
  const E = radius * (1 / Math.cos(halfDelta) - 1);

  // Mid-ordinate: M = R × (1 - cos(Δ/2))
  const M = radius * (1 - Math.cos(halfDelta));

  // Degree of curve (arc definition): D = 1718.873/R
  const D = 1718.873 / radius;
  
  return {
    radius,
    deflectionAngle,
    tangentLength: T,
    arcLength: L,
    longChord: C,
    externalDistance: E,
    midOrdinate: M,
    degreeOfCurve: D
  };
}

export function curveStakeout(
  piChainage: number,
  bearingIn: number,
  radius: number,
  deflectionAngle: number,
  interval: number = 20
): CurveStakeoutResult {
  const elements = curveElements(radius, deflectionAngle);
  const delta = toRadians(deflectionAngle);
  
  // Calculate chainages
  const pcChainage = piChainage - elements.tangentLength;
  const ptChainage = pcChainage + elements.arcLength;
  
  const points: CurveStakeoutPoint[] = [];
  
  // Generate stakeout points
  const numPoints = Math.floor(elements.arcLength / interval);
  
  for (let i = 0; i <= numPoints; i++) {
    const arcLength = Math.min(i * interval, elements.arcLength);
    const chainage = pcChainage + arcLength;
    
    // Deflection angle to this point
    const deflectionToPoint = (arcLength / elements.arcLength) * deflectionAngle;
    const totalDeflection = deflectionToPoint / 2;
    
    // Chord length to this point
    const chordLength = 2 * radius * Math.sin(toRadians(deflectionToPoint / 2));
    
    points.push({
      chainage,
      deflectionAngle: bearingToString(deflectionToPoint),
      totalDeflection: bearingToString(totalDeflection),
      chordLength
    });
  }
  
  return {
    elements,
    points,
    pcChainage,
    piChainage,
    ptChainage
  };
}

export function verticalCurve(
  incomingGrade: number,
  outgoingGrade: number,
  curveLength: number,
  startRL: number,
  interval: number = 10
): Array<{ chainage: number; rl: number; cutFill: number }> {
  // Parabolic vertical curve: y = (g2 - g1) * x^2 / (2L)
  // where x is distance from start of curve
  
  const gradeDiff = outgoingGrade - incomingGrade;
  const results: Array<{ chainage: number; rl: number; cutFill: number }> = [];
  
  const numPoints = Math.floor(curveLength / interval);
  
  for (let i = 0; i <= numPoints; i++) {
    const x = i * interval;
    const chainage = x;
    
    // Height of curve at this point
    const y = (gradeDiff * x * x) / (2 * curveLength);
    
    // RL at this point
    const rl = startRL + (incomingGrade * x / 100) + y;
    
    results.push({
      chainage,
      rl,
      cutFill: y
    });
  }
  
  // Find highest/lowest point
  if (gradeDiff !== 0) {
    const apexDistance = (incomingGrade * curveLength) / gradeDiff;
    if (apexDistance > 0 && apexDistance < curveLength) {
      // Add apex point
      const apexY = (gradeDiff * apexDistance * apexDistance) / (2 * curveLength);
      const apexRL = startRL + (incomingGrade * apexDistance / 100) + apexY;
      results.push({
        chainage: apexDistance,
        rl: apexRL,
        cutFill: apexY
      });
    }
  }
  
  return results.sort((a: any, b: any) => a.chainage - b.chainage);
}

export type CompoundCurveElements = {
  R1: number
  R2: number
  delta1Deg: number
  delta2Deg: number
  t1: number
  t2: number
  l1: number
  l2: number
  totalLength: number
  chainT1: number
  chainJ: number
  chainT2: number
}

/**
 * Compound curve elements (basic).
 * Uses standard simple-curve element formulas for each arc.
 */
export function compoundCurveElements(input: {
  R1: number
  R2: number
  delta1Deg: number
  delta2Deg: number
  junctionChainage: number
}): CompoundCurveElements {
  const toRad = (deg: number) => toRadians(deg)

  const t1 = input.R1 * Math.tan(toRad(input.delta1Deg) / 2)
  const t2 = input.R2 * Math.tan(toRad(input.delta2Deg) / 2)
  const l1 = input.R1 * toRad(input.delta1Deg)
  const l2 = input.R2 * toRad(input.delta2Deg)

  const chainJ = input.junctionChainage
  const chainT1 = chainJ - t1
  const chainT2 = chainJ + t2

  return {
    R1: input.R1,
    R2: input.R2,
    delta1Deg: input.delta1Deg,
    delta2Deg: input.delta2Deg,
    t1,
    t2,
    l1,
    l2,
    totalLength: l1 + l2,
    chainT1,
    chainJ,
    chainT2,
  }
}

export type ReverseCurveApprox = {
  R1: number
  R2: number
  AB: number
  commonTangent: number
  totalLength: number
  /** True when the total length is the rigorous value (deflection angles supplied); false when it's the 180°-arc approximation. */
  isApprox: boolean
}

/**
 * Reverse curve (approx.) helper used by the UI tool.
 *
 * AUDIT FIX (M3, 2026-07-02):
 *   The previous implementation computed `totalLength = π·R1 + π·R2`,
 *   which assumes both arcs deflect by 180°. That's wrong for the
 *   general case where Δ1 ≠ Δ2. The correct formula is
 *   `L = R1·Δ1 + R2·Δ2` (radians). When deflection angles are supplied
 *   via the optional `delta1`/`delta2` parameters (decimal degrees),
 *   the rigorous length is returned and `isApprox = false`. When angles
 *   are not supplied, the old 180° approximation is preserved for
 *   backward compatibility, and `isApprox = true` flags it.
 *
 * @param input.R1     Radius of first arc (metres)
 * @param input.R2     Radius of second arc (metres)
 * @param input.AB     Distance between PIs of the two curves (metres)
 * @param input.delta1 Optional deflection angle of first arc (decimal degrees)
 * @param input.delta2 Optional deflection angle of second arc (decimal degrees)
 */
export function reverseCurveApprox(input: {
  R1: number
  R2: number
  AB: number
  delta1?: number
  delta2?: number
}): ReverseCurveApprox {
  const diff = input.R2 - input.R1
  const commonTangent = Math.sqrt(Math.max(0, input.AB * input.AB - diff * diff))

  let totalLength: number
  let isApprox: boolean

  if (
    typeof input.delta1 === 'number' &&
    typeof input.delta2 === 'number' &&
    !isNaN(input.delta1) &&
    !isNaN(input.delta2)
  ) {
    // Rigorous: L = R1·Δ1 + R2·Δ2 (angles in radians)
    const d1Rad = (input.delta1 * Math.PI) / 180
    const d2Rad = (input.delta2 * Math.PI) / 180
    totalLength = input.R1 * Math.abs(d1Rad) + input.R2 * Math.abs(d2Rad)
    isApprox = false
  } else {
    // Approximation: assumes both arcs are 180° (semicircles).
    // Flagged via isApprox = true so callers can warn the user.
    totalLength = Math.PI * input.R1 + Math.PI * input.R2
    isApprox = true
  }

  return { ...input, commonTangent, totalLength, isApprox }
}

/**
 * @module deformationTracker
 *
 * Deformation & Monitoring Survey Engine
 *
 * Tracks structural displacement over time (epochs):
 * 1. Establish Epoch 0 (baseline) coordinates for monitoring points
 * 2. Import subsequent epoch measurements
 * 3. Compute 3D displacement vectors (ΔX, ΔY, ΔZ)
 * 4. Calculate total displacement and velocity
 * 5. Flag points exceeding safety thresholds
 *
 * Applications:
 * - Mining zone deformation
 * - Structural foundation monitoring
 * - Landslide-prone embankment tracking
 * - Dam and retaining wall monitoring
 *
 * Reference: "Engineering Surveying" by Schofield & Breach (Chapter 14)
 */

export interface MonitoringStation {
  id: string
  stationName: string
  baseX: number  // Epoch 0 baseline (Easting)
  baseY: number  // Epoch 0 baseline (Northing)
  baseZ: number  // Epoch 0 baseline (Elevation)
  description?: string
}

export interface EpochReading {
  id: string
  stationId: string
  epochNumber: number
  observedAt: string  // ISO date
  currentX: number
  currentY: number
  currentZ: number
  deltaX: number  // current - baseline
  deltaY: number
  deltaZ: number
  totalDisplacement: number  // 3D displacement
  horizontalDisplacement: number
  velocityMmPerWeek: number  // rate of change
  status: 'stable' | 'warning' | 'critical'
}

export interface DeformationReport {
  stations: MonitoringStation[]
  readings: EpochReading[]
  flaggedStations: EpochReading[]
  maxDisplacement: number
  maxVelocity: number
  epochCount: number
  monitoringPeriod: {
    start: string
    end: string
    durationDays: number
  }
}

// Safety thresholds (configurable)
export const DEFAULT_THRESHOLDS = {
  warningDisplacement: 5.0,    // mm — flag as warning
  criticalDisplacement: 10.0,  // mm — flag as critical
  warningVelocity: 1.0,        // mm/week
  criticalVelocity: 2.0,       // mm/week
}

/**
 * Compute displacement for a single epoch reading.
 */
export function computeDisplacement(
  station: MonitoringStation,
  currentX: number,
  currentY: number,
  currentZ: number,
  epochNumber: number,
  observedAt: string,
  previousReading?: EpochReading,
): EpochReading {
  const deltaX = currentX - station.baseX
  const deltaY = currentY - station.baseY
  const deltaZ = currentZ - station.baseZ

  const horizontalDisplacement = Math.sqrt(deltaX * deltaX + deltaY * deltaY)
  const totalDisplacement = Math.sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ)

  // Convert to mm
  const totalDispMm = totalDisplacement * 1000

  // Compute velocity (mm per week)
  let velocityMmPerWeek = 0
  if (previousReading) {
    const prevDate = new Date(previousReading.observedAt)
    const currDate = new Date(observedAt)
    const daysDiff = (currDate.getTime() - prevDate.getTime()) / 86400000
    if (daysDiff > 0) {
      const prevDispMm = previousReading.totalDisplacement * 1000
      const dispDiff = totalDispMm - prevDispMm
      velocityMmPerWeek = (dispDiff / daysDiff) * 7
    }
  }

  // Determine status
  let status: 'stable' | 'warning' | 'critical' = 'stable'
  if (totalDispMm >= DEFAULT_THRESHOLDS.criticalDisplacement ||
      velocityMmPerWeek >= DEFAULT_THRESHOLDS.criticalVelocity) {
    status = 'critical'
  } else if (totalDispMm >= DEFAULT_THRESHOLDS.warningDisplacement ||
             velocityMmPerWeek >= DEFAULT_THRESHOLDS.warningVelocity) {
    status = 'warning'
  }

  return {
    id: crypto.randomUUID(),
    stationId: station.id,
    epochNumber,
    observedAt,
    currentX,
    currentY,
    currentZ,
    deltaX,
    deltaY,
    deltaZ,
    totalDisplacement,
    horizontalDisplacement,
    velocityMmPerWeek,
    status,
  }
}

/**
 * Generate a full deformation report from multiple epochs.
 */
export function generateDeformationReport(
  stations: MonitoringStation[],
  readings: EpochReading[],
): DeformationReport {
  const flaggedStations = readings.filter(
    r => r.status === 'warning' || r.status === 'critical'
  )

  const maxDisplacement = Math.max(0, ...readings.map(r => r.totalDisplacement * 1000))
  const maxVelocity = Math.max(0, ...readings.map(r => r.velocityMmPerWeek))

  const epochNumbers = [...new Set(readings.map(r => r.epochNumber))].sort((a, b) => a - b)
  const dates = readings.map(r => new Date(r.observedAt)).sort((a, b) => a.getTime() - b.getTime())

  return {
    stations,
    readings: readings.sort((a, b) => {
      if (a.stationId !== b.stationId) return a.stationId.localeCompare(b.stationId)
      return a.epochNumber - b.epochNumber
    }),
    flaggedStations,
    maxDisplacement,
    maxVelocity,
    epochCount: epochNumbers.length,
    monitoringPeriod: {
      start: dates[0]?.toISOString() || new Date().toISOString(),
      end: dates[dates.length - 1]?.toISOString() || new Date().toISOString(),
      durationDays: dates.length > 1
        ? (dates[dates.length - 1].getTime() - dates[0].getTime()) / 86400000
        : 0,
    },
  }
}

/**
 * Generate a deformation alert for a critical station.
 */
export function generateAlert(reading: EpochReading, station: MonitoringStation): {
  severity: 'warning' | 'critical'
  stationName: string
  message: string
  timestamp: string
} {
  const dispMm = (reading.totalDisplacement * 1000).toFixed(2)
  const velMm = reading.velocityMmPerWeek.toFixed(2)

  return {
    severity: reading.status as 'warning' | 'critical',
    stationName: station.stationName,
    message: `Station ${station.stationName} has ${reading.status === 'critical' ? 'CRITICAL' : 'WARNING'} displacement: ${dispMm}mm total, ${velMm}mm/week velocity`,
    timestamp: reading.observedAt,
  }
}

// ─── Congruence Testing (Pelzer's Method) ──────────────────────────────────
//
// AUDIT FIX (H11, 2026-07-02): Added congruence testing for statistically
// rigorous deformation analysis. Previously the tracker used fixed
// thresholds (5mm/10mm) with no statistical significance test — a 5mm
// displacement is meaningless without knowing the σ of the coordinate.
//
// The Pelzer global congruence test answers: "Is the deformation between
// two epochs statistically significant, or could it be explained by
// measurement noise alone?"
//
// Method (Pelzer 1971, Caspary 1988):
//   1. Compute coordinate differences: d = X₁ - X₀
//   2. Compute cofactor of differences: Q_dd = Q₀ + Q₁ (pooled)
//   3. Compute quadratic form: Ω = dᵀ · Q_dd⁺ · d (pseudoinverse for singular Q)
//   4. Test statistic: T = Ω / (h · s₀²) where h = rank(Q_dd)
//   5. Compare T against F(h, f_rest, 1-α) — if T > F_crit, deformation
//      is statistically significant
//
// References:
//   - Pelzer, H. (1971) "Zur Analyse geodätischer Deformationsmessungen"
//   - Caspary, W. (1988) "Concepts of Network and Deformation Analysis"
//   - Schofield & Breach (2007) "Engineering Surveying" Ch. 14

export interface CongruenceTestResult {
  /** True if the deformation is statistically significant at the chosen α. */
  significant: boolean
  /** Test statistic T = Ω / (h · s₀²) */
  testStatistic: number
  /** Critical value from F-distribution: F(h, f_rest, 1-α) */
  criticalValue: number
  /** Significance level (default 0.05 = 95% confidence) */
  alpha: number
  /** Degrees of freedom: h = rank of Q_dd */
  degreesOfFreedom: number
  /** Quadratic form Ω = dᵀ · Q_dd⁺ · d */
  quadraticForm: number
  /** Reference variance s₀² (pooled from both epochs) */
  referenceVariance: number
  /** Human-readable summary */
  summary: string
}

export interface DisplacementConfidenceEllipse {
  stationId: string
  /** Semi-major axis (mm) */
  semiMajor: number
  /** Semi-minor axis (mm) */
  semiMinor: number
  /** Orientation of major axis (degrees from North, clockwise) */
  orientation: number
  /** Confidence level (default 0.95 = 95%) */
  confidenceLevel: number
  /** True if the displacement is statistically significant (ellipse does not contain origin) */
  significant: boolean
}

/**
 * Perform a Pelzer global congruence test between two epochs.
 *
 * @param displacements  Coordinate differences d = X₁ - X₀ for each station (2D: [dE, dN] per station)
 * @param cofactorMatrix  Q_dd = Q₀ + Q₁ (pooled cofactor matrix, 2n × 2n for n stations)
 * @param referenceVariance  Pooled reference variance s₀² (from both epochs' adjustments)
 * @param residualDegreesOfFreedom  f_rest (degrees of freedom of the combined adjustment)
 * @param alpha  Significance level (default 0.05 = 95% confidence)
 */
export function congruenceTest(
  displacements: number[],
  cofactorMatrix: number[][],
  referenceVariance: number,
  residualDegreesOfFreedom: number,
  alpha: number = 0.05
): CongruenceTestResult {
  const n = displacements.length
  if (n === 0 || cofactorMatrix.length === 0) {
    return {
      significant: false,
      testStatistic: 0,
      criticalValue: 0,
      alpha,
      degreesOfFreedom: 0,
      quadraticForm: 0,
      referenceVariance,
      summary: 'No displacement data provided',
    }
  }

  // Compute the pseudoinverse of Q_dd (Moore-Penrose via SVD approximation).
  // For a full-rank square matrix, this is just the regular inverse.
  // For singular matrices (free networks), we use a regularized inverse.
  let QddInv: number[][]
  try {
    QddInv = matrixInvert(cofactorMatrix)
  } catch {
    // Matrix is singular — add a small Tikhonov regularization
    const lambda = 1e-10 * Math.max(...diagonal(cofactorMatrix).map(Math.abs))
    const regularized = cofactorMatrix.map((row, i) =>
      row.map((v, j) => v + (i === j ? lambda : 0))
    )
    QddInv = matrixInvert(regularized)
  }

  // Compute quadratic form: Ω = dᵀ · Q_dd⁺ · d
  let omega = 0
  for (let i = 0; i < n; i++) {
    let rowProduct = 0
    for (let j = 0; j < n; j++) {
      rowProduct += QddInv[i][j] * displacements[j]
    }
    omega += displacements[i] * rowProduct
  }

  // Effective degrees of freedom (rank of Q_dd)
  // For a non-singular matrix, h = n. For singular, h < n.
  // We approximate h as n (the dimension of the displacement vector).
  const h = n

  // Test statistic: T = Ω / (h · s₀²)
  const testStatistic = omega / (h * Math.max(referenceVariance, 1e-15))

  // F-distribution critical value: F(h, f_rest, 1-α)
  // Approximation using the Fisher-Snedecor relationship with chi-square:
  // F(h, f) ≈ (χ²_h / h) / (χ²_f / f) where χ² are independent
  // For large f_rest, F(h, ∞, 1-α) ≈ χ²_h / h
  const chiSqH = chiSquareQuantileApprox(1 - alpha, h)
  const fRest = Math.max(residualDegreesOfFreedom, 1)
  const chiSqF = chiSquareQuantileApprox(1 - alpha, fRest)
  const criticalValue = (chiSqH / h) / (chiSqF / fRest)

  const significant = testStatistic > criticalValue

  const summary = significant
    ? `Deformation is statistically significant at α=${alpha}. ` +
      `T=${testStatistic.toFixed(4)} > F_crit=${criticalValue.toFixed(4)} ` +
      `(Ω=${omega.toFixed(4)}, h=${h}, s₀²=${referenceVariance.toFixed(6)}). ` +
      `The network has moved beyond what measurement noise can explain.`
    : `Deformation is NOT statistically significant at α=${alpha}. ` +
      `T=${testStatistic.toFixed(4)} ≤ F_crit=${criticalValue.toFixed(4)}. ` +
      `Observed displacements are consistent with measurement noise.`

  return {
    significant,
    testStatistic,
    criticalValue,
    alpha,
    degreesOfFreedom: h,
    quadraticForm: omega,
    referenceVariance,
    summary,
  }
}

/**
 * Compute confidence ellipses for displacement vectors.
 *
 * For each station, the 2D displacement (dE, dN) has a covariance
 * matrix Σ = s₀² · Q_dd (extracted from the pooled cofactor). The
 * confidence ellipse at level (1-α) has semi-axes:
 *   a = √(λ₁ · s₀² · F_quantile)
 *   b = √(λ₂ · s₀² · F_quantile)
 * where λ₁, λ₂ are the eigenvalues of the 2×2 cofactor sub-matrix.
 *
 * The displacement is statistically significant if the ellipse does NOT
 * contain the origin (i.e., zero displacement is outside the confidence
 * region).
 *
 * @param stationIds  Array of station IDs
 * @param displacements  Flat array [dE_1, dN_1, dE_2, dN_2, ...] in metres
 * @param cofactorDiagonals  Per-station 2×2 cofactor sub-matrices: [[qEE, qEN], [qNE, qNN]]
 * @param referenceVariance  Pooled s₀²
 * @param confidenceLevel  Default 0.95 (95%)
 */
export function computeDisplacementConfidenceEllipses(
  stationIds: string[],
  displacements: number[],
  cofactorDiagonals: number[][][],
  referenceVariance: number,
  confidenceLevel: number = 0.95
): DisplacementConfidenceEllipse[] {
  const alpha = 1 - confidenceLevel
  // F-quantile for 2 and ∞ degrees of freedom at (1-α)
  // F(2, ∞, 0.95) ≈ 3.00 (chi²₂/2 = 5.991/2 = 2.996)
  const fQuantile = chiSquareQuantileApprox(confidenceLevel, 2) / 2

  const results: DisplacementConfidenceEllipse[] = []

  for (let i = 0; i < stationIds.length; i++) {
    const dE = displacements[i * 2] ?? 0
    const dN = displacements[i * 2 + 1] ?? 0
    const Q = cofactorDiagonals[i] ?? [[1, 0], [0, 1]]

    // Scale by reference variance to get covariance
    const s2 = Math.max(referenceVariance, 1e-15)
    const c11 = Q[0][0] * s2
    const c12 = Q[0][1] * s2
    const c22 = Q[1][1] * s2

    // Eigenvalues of 2×2 covariance matrix
    const trace = c11 + c22
    const det = c11 * c22 - c12 * c12
    const discriminant = Math.sqrt(Math.max(trace * trace / 4 - det, 0))
    const lambda1 = trace / 2 + discriminant // larger eigenvalue
    const lambda2 = trace / 2 - discriminant // smaller eigenvalue

    // Semi-axes (in mm)
    const semiMajor = Math.sqrt(Math.max(lambda1, 0) * fQuantile) * 1000
    const semiMinor = Math.sqrt(Math.max(lambda2, 0) * fQuantile) * 1000

    // Orientation of major axis (degrees from North, clockwise)
    const orientation = (Math.atan2(2 * c12, c11 - c22) * 180 / Math.PI / 2 + 360) % 360

    // Significance: does the ellipse contain the origin?
    // The origin is inside the ellipse if: dᵀ · Σ⁻¹ · d ≤ fQuantile
    const detSigma = c11 * c22 - c12 * c12
    let testStat = 0
    if (Math.abs(detSigma) > 1e-15) {
      const inv11 = c22 / detSigma
      const inv12 = -c12 / detSigma
      const inv22 = c11 / detSigma
      testStat = dE * dE * inv11 + 2 * dE * dN * inv12 + dN * dN * inv22
    }
    const significant = testStat > fQuantile

    results.push({
      stationId: stationIds[i],
      semiMajor,
      semiMinor,
      orientation,
      confidenceLevel,
      significant,
    })
  }

  return results
}

// ─── Linear algebra helpers ────────────────────────────────────────────────

function diagonal(m: number[][]): number[] {
  return m.map((row, i) => row[i] ?? 0)
}

function matrixInvert(m: number[][]): number[][] {
  const n = m.length
  if (n === 0) return []

  // Augmented matrix [m | I]
  const aug = m.map((row, i) => [
    ...row,
    ...Array.from({ length: n }, (_, j) => (i === j ? 1 : 0))
  ])

  // Gaussian elimination with partial pivoting
  for (let col = 0; col < n; col++) {
    // Find pivot
    let maxRow = col
    for (let row = col + 1; row < n; row++) {
      if (Math.abs(aug[row][col]) > Math.abs(aug[maxRow][col])) {
        maxRow = row
      }
    }
    if (Math.abs(aug[maxRow][col]) < 1e-14) {
      throw new Error('Matrix is singular')
    }

    // Swap rows
    [aug[col], aug[maxRow]] = [aug[maxRow], aug[col]]

    // Scale pivot row
    const pivot = aug[col][col]
    for (let j = 0; j < 2 * n; j++) {
      aug[col][j] /= pivot
    }

    // Eliminate column
    for (let row = 0; row < n; row++) {
      if (row === col) continue
      const factor = aug[row][col]
      for (let j = 0; j < 2 * n; j++) {
        aug[row][j] -= factor * aug[col][j]
      }
    }
  }

  // Extract inverse
  return aug.map(row => row.slice(n))
}

function chiSquareQuantileApprox(p: number, dof: number): number {
  if (dof <= 0) return 0
  // Wilson-Hilferty transformation
  const z = invNormalCDFApprox(p)
  const t = z * Math.sqrt(2 / (9 * dof)) + 1 - 1 / (9 * dof)
  return dof * t * t * t
}

function invNormalCDFApprox(p: number): number {
  // Acklam's algorithm
  const a = [-3.969683028665376e+01, 2.209460984245205e+02,
             -2.759285104469687e+02, 1.383577518672690e+02,
             -3.066479806614716e+01, 2.506628277459239e+00]
  const b = [-5.447609879822406e+01, 1.615858368580409e+02,
             -1.556989798598866e+02, 6.680131188771972e+01,
             -1.328068155288572e+01]
  const c = [-7.784894002430293e-03, -3.223964580411365e-01,
             -2.400758277161838e+00, -2.549732539343734e+00,
              4.374664141464968e+00, 2.938163982698783e+00]
  const d = [7.784695709041462e-03, 3.224671290700398e-01,
             2.445134137142996e+00, 3.754408661907416e+00]
  const pLow = 0.02425
  const pHigh = 1 - pLow
  let q: number
  if (p < pLow) {
    q = Math.sqrt(-2 * Math.log(p))
    return (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) /
           ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)
  } else if (p <= pHigh) {
    q = p - 0.5
    const r = q * q
    return (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q /
           (((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1)
  } else {
    q = Math.sqrt(-2 * Math.log(1 - p))
    return -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) /
            ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)
  }
}

/**
 * EDM Reduction Pipeline — full meter-to-grid correction chain.
 *
 * Stage 1: Slope → Horizontal  (vertical angle + zenith angle)
 * Stage 2: Horizontal → Sea Level  (earth curvature + refraction)
 * Stage 3: Sea Level → Grid  (scale factor + convergence)
 * Stage 4: Atmospheric correction  (temperature + pressure)
 *
 * Reference: USACE EM 1110-1-1005 §3-5 (EDM specifications)
 *            USACE EM 1110-1-1005 §5-15 (grid/sea level reduction)
 *            NOAA Manual NOS NGS 5 (geodetic EDM reductions)
 */

import type { SurveyingCountry } from '@/lib/country/standards'
import { getCountryStandard } from '@/lib/country/standards'

// ─── STAGE 1: SLOPE → HORIZONTAL ─────────────────────────────────────────────

export interface SlopeCorrectionInput {
  slopeDistanceMetres: number
  verticalAngle?: number      // degrees (zenith if null)
  zenithAngle?: number        // degrees (use instead of verticalAngle)
  temperatureC?: number
  pressureHPa?: number
  edmManufacturer?: string
  edmSpecMM?: number          // mm — manufacturer spec (default ±5mm)
  edmSpecPPM?: number         // ppm — manufacturer spec (default ±5ppm)
}

export interface SlopeCorrectionOutput {
  horizontalDistance: number   // metres
  slopeDistance: number
  verticalAngle: number        // degrees (zenith)
  requiresTwoFace: boolean
  temperaturePPM: number       // ppm correction
  pressurePPM: number          // ppm correction
  totalAtmosphericPPM: number  // combined ppm
  warnings: string[]
  regulation: string
}

export function slopeFromEDM(input: SlopeCorrectionInput): SlopeCorrectionOutput {
  const {
    slopeDistanceMetres,
    verticalAngle: va,
    zenithAngle: za,
    temperatureC = 15,
    pressureHPa = 1013.25,
    edmSpecMM = 5,
    edmSpecPPM = 5,
  } = input

  const zenith = za ?? (va !== undefined ? 90 - va : 90)
  const zenithRad = zenith * Math.PI / 180

  const horizontalDistance = slopeDistanceMetres * Math.sin(zenithRad)
  const requiresTwoFace = zenith > 90.5 || zenith < 89.5  // flag any non-horizontal shot

  const tempPPM = edmTemperatureCorrection(temperatureC, pressureHPa, edmSpecPPM)
  const pressPPM = edmPressureCorrection(temperatureC, pressureHPa, edmSpecPPM)
  const totalPPM = tempPPM + pressPPM

  const warnings: string[] = []
  if (requiresTwoFace) {
    warnings.push('Zenith angle >10° from horizontal — both-face measurement recommended.')
  }
  if (slopeDistanceMetres >= 500) {
    warnings.push('EDM ≥500m: meteorological correction mandatory per USACE EM 1110-1-1005 §3-5.')
  }
  if (temperatureC < 0 || temperatureC > 40) {
    warnings.push(`Temperature ${temperatureC}°C is outside normal range — verify EDM calibration.`)
  }

  return {
    horizontalDistance,
    slopeDistance: slopeDistanceMetres,
    verticalAngle: 90 - zenith,  // return as elevation angle
    requiresTwoFace,
    temperaturePPM: tempPPM,
    pressurePPM: pressPPM,
    totalAtmosphericPPM: totalPPM,
    warnings,
    regulation: 'USACE EM 1110-1-1005 §3-5',
  }
}

// ─── STAGE 2: SEA LEVEL CORRECTION ───────────────────────────────────────────

export interface SeaLevelCorrectionInput {
  horizontalDistance: number    // metres
  meanElevationMetres: number  // average elevation of ends
  latitudeDegrees?: number      // needed for gravity correction
  refractCoeff?: number         // k = 0.13 default for clear air
}

export interface SeaLevelCorrectionOutput {
  seaLevelDistance: number      // metres
  curvatureRefractionCorr: number  // metres (subtract this)
  meanSeaLevelRadius: number   // metres
  warnings: string[]
  regulation: string
}

export function seaLevelCorrection(input: SeaLevelCorrectionInput): SeaLevelCorrectionOutput {
  const {
    horizontalDistance,
    meanElevationMetres,
    latitudeDegrees = 0,
    refractCoeff = 0.13,
  } = input

  const R = 6_378_137  // mean Earth radius, metres (WGS84)
  const k = refractCoeff

  // Combined curvature + refraction: ΔD = D²/(2R) · (1 + k)
  const deltaD = (horizontalDistance * horizontalDistance) / (2 * R) * (1 + k)
  const seaLevelDistance = horizontalDistance - deltaD

  const warnings: string[] = []
  if (meanElevationMetres > 3000) {
    warnings.push('Elevation >3000m: verify Earth radius approximation is adequate.')
  }

  return {
    seaLevelDistance,
    curvatureRefractionCorr: deltaD,
    meanSeaLevelRadius: R,
    warnings,
    regulation: 'USACE EM 1110-1-1005 §5-15 / NOAA NOS NGS 5',
  }
}

// ─── STAGE 3: GRID CORRECTION ─────────────────────────────────────────────────

export interface GridCorrectionInput {
  seaLevelDistance: number
  scaleFactor: number       // local scale factor (from geoid model or known values)
  convergenceAngle?: number  // arc-seconds (meridian convergence at midpoint)
  easting?: number          // for auto-convergence calculation
}

export interface GridCorrectionOutput {
  gridDistance: number
  seaToGridCorr: number    // metres to add
  combinedScaleFactor: number  // sea-to-grid ratio
  convergenceAngle: number  // arc-seconds (0 if not computed)
  warnings: string[]
  regulation: string
}

export function gridCorrection(input: GridCorrectionInput): GridCorrectionOutput {
  const { seaLevelDistance, scaleFactor, convergenceAngle = 0, easting } = input

  const combinedSF = scaleFactor
  const gridDistance = seaLevelDistance * scaleFactor
  const seaToGridCorr = gridDistance - seaLevelDistance

  const warnings: string[] = []
  if (Math.abs(convergenceAngle) > 300) {
    warnings.push('Convergence angle >5° — verify zone selection is correct.')
  }
  if (scaleFactor < 0.9995 || scaleFactor > 1.0015) {
    warnings.push(`Scale factor ${scaleFactor.toFixed(6)} is unusual — verify geoid model or projection parameters.`)
  }

  return {
    gridDistance,
    seaToGridCorr,
    combinedScaleFactor: combinedSF,
    convergenceAngle,
    warnings,
    regulation: 'USACE EM 1110-1-1005 §5-15 / projection authority documentation',
  }
}

// ─── STAGE 4: ATMOSPHERIC CORRECTION ─────────────────────────────────────────

export function edmTemperatureCorrection(
  tempC: number,
  _pressureHPa: number,
  _basePPM: number
): number {
  // Barrel & Sears atmospheric correction — temperature component only
  // ppm = K × P0 × (1/T0 - 1/T), where T0 = 288.15 K (15°C standard)
  const K  = 281.8
  const P0 = 1013.25
  const T0 = 288.15   // 15°C in Kelvin
  const T  = tempC + 273.15
  return K * P0 * (1 / T0 - 1 / T)
}

export function edmPressureCorrection(
  _tempC: number,
  pressureHPa: number,
  _basePPM: number
): number {
  // Barrel & Sears atmospheric correction — pressure component only
  // ppm = K / T0 × (P0 - P), where T0 = 288.15 K, P0 = 1013.25 hPa
  const K  = 281.8
  const P0 = 1013.25
  const T0 = 288.15
  return (K / T0) * (P0 - pressureHPa)
}

export function edmCombinedAtmosphericCorrection(
  tempC: number,
  pressureHPa: number,
  edmSpecPPM: number = 5
): { totalPPM: number; tempPPM: number; pressurePPM: number; isWithinSpec: boolean } {
  const tempPPM = edmTemperatureCorrection(tempC, pressureHPa, edmSpecPPM)
  const pressPPM = edmPressureCorrection(tempC, pressureHPa, edmSpecPPM)
  const totalPPM = tempPPM + pressPPM
  const standardPPM = 0

  return {
    totalPPM,
    tempPPM,
    pressurePPM: pressPPM,
    isWithinSpec: Math.abs(totalPPM - standardPPM) <= edmSpecPPM,
  }
}

// ─── FULL EDM REDUCTION PIPELINE ─────────────────────────────────────────────

export interface EDMReductionInput {
  slopeDistance: number
  zenithAngle: number
  meanElevation: number
  scaleFactor: number
  temperatureC: number
  pressureHPa: number
  edmSpecMM?: number
  edmSpecPPM?: number
  country?: SurveyingCountry
}

export interface EDMReductionResult {
  slopeDistance: number
  horizontalDistance: number
  seaLevelDistance: number
  gridDistance: number
  totalCorrSeaLevel: number
  totalCorrGrid: number
  totalCorrAtmospheric: number
  scaleFactor: number
  convergenceAngle: number
  ppm: number
  mmAccuracy: number
  isAcceptable: boolean
  warnings: string[]
  regulation: string
}

export function edmFullReduction(input: EDMReductionInput): EDMReductionResult {
  const {
    slopeDistance,
    zenithAngle,
    meanElevation,
    scaleFactor,
    temperatureC = 15,
    pressureHPa = 1013.25,
    edmSpecMM = 5,
    edmSpecPPM = 5,
    country,
  } = input

  const slope = slopeFromEDM({ slopeDistanceMetres: slopeDistance, zenithAngle, temperatureC, pressureHPa, edmSpecMM, edmSpecPPM })
  const sea = seaLevelCorrection({ horizontalDistance: slope.horizontalDistance, meanElevationMetres: meanElevation })
  const grid = gridCorrection({ seaLevelDistance: sea.seaLevelDistance, scaleFactor })

  const atm = edmCombinedAtmosphericCorrection(temperatureC, pressureHPa, edmSpecPPM)
  const correctedDist = grid.gridDistance * (1 + atm.totalPPM / 1_000_000)
  const atmosphericCorr = correctedDist - grid.gridDistance

  const mmAccuracy = edmSpecMM + edmSpecPPM * slopeDistance / 1000

  const warnings = [
    ...slope.warnings,
    ...sea.warnings,
    ...grid.warnings,
  ]

  const std = country ? getCountryStandard(country) : null
  const defaultSlopeRule = std?.slopeCorrection.maxSlopeSingleFace ?? 10

  return {
    slopeDistance,
    horizontalDistance: slope.horizontalDistance,
    seaLevelDistance: sea.seaLevelDistance,
    gridDistance: correctedDist,
    totalCorrSeaLevel: sea.curvatureRefractionCorr,
    totalCorrGrid: grid.seaToGridCorr,
    totalCorrAtmospheric: Math.abs(atmosphericCorr),
    scaleFactor: grid.combinedScaleFactor,
    convergenceAngle: grid.convergenceAngle,
    ppm: atm.totalPPM,
    mmAccuracy,
    isAcceptable: mmAccuracy < 20,
    warnings,
    regulation: 'USACE EM 1110-1-1005 §3-5 / §5-15',
  }
}

/**
 * Calculation standard: N.N. Basak — Surveying and Levelling
 * - No intermediate rounding
 * - Full floating point precision throughout
 * - Round only at final display layer
 * - Bearings: WCB 0-360° clockwise from North
 */

// METARDU Engine - Geometry utilities

import { Point2D, SurveyResult } from './types';
import { toRadians, toDegrees, normalizeBearing } from './angles';
import { distanceBearing } from './distance';

export interface AngularMisclosureResult {
  sumObservedAngles: number;
  theoreticalSum: number;
  misclosure: number;
  correctionPerStation: number;
  correctedAngles: number[];
}

export interface LineIntersectionResult {
  point: Point2D;
  tA: number;
  tB: number;
  withinSegmentA: boolean;
  withinSegmentB: boolean;
}

export function midpoint(a: Point2D, b: Point2D): Point2D {
  return {
    easting: (a.easting + b.easting) / 2,
    northing: (a.northing + b.northing) / 2,
  };
}

// Source: Basak, Chapter 10 — Angular misclosure for n-sided polygon: (n-2)×180°
// Source: Ghilani & Wolf, Chapter 10 — Correction per angle = -misclosure/n
export function angularMisclosureFromAngles(observedAngles: number[]): SurveyResult<AngularMisclosureResult> {
  const n = observedAngles.length;
  if (n < 3) return { ok: false, error: 'Need at least 3 angles.' };
  const sumObserved = observedAngles.reduce((s, a) => s + a, 0);
  const theoretical = (n - 2) * 180;
  const misclosure = sumObserved - theoretical;
  const corrPerStation = misclosure / n;
  return {
    ok: true,
    value: {
      sumObservedAngles: sumObserved,
      theoreticalSum: theoretical,
      misclosure,
      correctionPerStation: corrPerStation,
      correctedAngles: observedAngles.map((a: any) => a - corrPerStation),
    }
  };
}

// Source: Basak/Ghilani & Wolf — Point-in-polygon by ray casting (Jordan curve theorem)
export function pointInPolygon(point: Point2D, polygon: Point2D[]): boolean {
  const { easting: px, northing: py } = point;
  const n = polygon.length;
  let inside = false;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = polygon[i].easting, yi = polygon[i].northing;
    const xj = polygon[j].easting, yj = polygon[j].northing;
    const intersects = yi > py !== yj > py &&
      px < ((xj - xi) * (py - yi)) / (yj - yi) + xi;
    if (intersects) inside = !inside;
  }
  return inside;
}

// Source: Basak — Line intersection by simultaneous equations (determinant method)
export function lineIntersection(
  a1: Point2D, a2: Point2D,
  b1: Point2D, b2: Point2D
): SurveyResult<LineIntersectionResult> {
  const dAe = a2.easting - a1.easting;
  const dAn = a2.northing - a1.northing;
  const dBe = b2.easting - b1.easting;
  const dBn = b2.northing - b1.northing;
  const denom = dAe * dBn - dAn * dBe;
  if (Math.abs(denom) < 1e-10) return { ok: false, error: 'Lines are parallel.' };
  const dx = b1.easting - a1.easting;
  const dy = b1.northing - a1.northing;
  const tA = (dx * dBn - dy * dBe) / denom;
  const tB = (dx * dAn - dy * dAe) / denom;
  return {
    ok: true,
    value: {
      point: { easting: a1.easting + tA * dAe, northing: a1.northing + tA * dAn },
      tA, tB,
      withinSegmentA: tA >= 0 && tA <= 1,
      withinSegmentB: tB >= 0 && tB <= 1,
    }
  };
}

export function circularBuffer(centre: Point2D, radius: number, segments = 64): SurveyResult<Point2D[]> {
  if (radius <= 0) return { ok: false, error: 'Radius must be positive.' };
  const points: Point2D[] = [];
  for (let i = 0; i < segments; i++) {
    const angle = (2 * Math.PI * i) / segments;
    points.push({
      easting: centre.easting + radius * Math.sin(angle),
      northing: centre.northing + radius * Math.cos(angle),
    });
  }
  return { ok: true, value: points };
}

/**
 * @deprecated P1-5 (2026-07-24): Use `@/lib/engine/networkAdjustment.ts`
 *   (the `adjustNetwork` function) instead. That module is the canonical
 *   enterprise-grade LSA: sparse Cholesky, free-network inner constraints,
 *   Huber robust estimation, full Baarda reliability, 2D/3D, 6 observation
 *   types. This dense 2D-only module is kept for the `leastSquares3d.test.ts`
 *   KAT suite and the `traverseToLSQ` bridge, but new code should not
 *   import from here.
 *
 * Least Squares Adjustment (2D) — Weighted, iterative
 * References: standard surveying adjustment (Ghilani/Wolf; Ghilani "Adjustment Computations")
 *
 * This implementation supports mixed observation sets of:
 * - horizontal distances (m)
 * - whole-circle bearings (degrees, WCB from North)
 *
 * Notes:
 * - All computations keep full floating-point precision (no intermediate rounding).
 * - Observations use `weight = 1/σ²` (per-observation), where σ is in the observation's units.
 * - Bearings are internally handled in radians; residuals are wrapped to (-π, π].
 */

export type ObservationType = 'distance' | 'bearing' | 'angle' | 'slope_distance' | 'zenith_angle' | 'height_difference'

export interface Observation {
  type?: ObservationType
  from: string
  to: string
  distance?: number
  bearing?: number
  weight?: number
  distanceSigma?: number
  bearingSigmaArcSec?: number
  occupied?: string
  backsight?: string
  foresight?: string
  angle?: number
  angleSigmaArcSec?: number
  slopeDistance?: number
  slopeDistanceSigma?: number
  zenithAngle?: number
  zenithAngleSigmaArcSec?: number
  heightDifference?: number
  heightDiffSigma?: number
}

export interface LSAdjustmentResult {
  ok: boolean
  adjustedPoints: Array<{
    name: string
    easting: number
    northing: number
    sigmaEasting: number
    sigmaNorthing: number
    rl?: number
    sigmaRL?: number
  }>
  residuals: Array<{
    observation: string
    residual: number
    standardizedResidual: number
  }>
  referenceVariance: number
  chiSquare: number
  degreesOfFreedom: number
  globalTest?: {
    alpha: number
    lower: number
    upper: number
    passed: boolean
  }
  // ─── Baarda Reliability Analysis (H13, 2026-07-03) ───────────────────────
  // Added per audit finding H13. Each observation gets:
  //   - redundancy number r_i  (0 ≤ r_i ≤ 1; sum of r_i = degrees of freedom)
  //   - internal reliability / MDB (Minimal Detectable Bias) — the smallest
  //     bias in observation i that would be detected by the w-test at the
  //     chosen significance level
  //   - external reliability — the effect of an undetected MDB-sized bias
  //     on the adjusted coordinates (max |∇x| in meters)
  //   - w-test statistic (data snooping) — |v_i| / σ_v_i
  //
  // References:
  //   - Baarda, W. (1968) "A Testing Procedure for Use in Geodetic Networks"
  //   - Förstner, W. (1979) "On Internal and External Reliability of
  //     Photogrammetric Coordinates"
  //   - Ghilani & Wolf "Adjustment Computations" Ch. 21 (Reliability)
  reliability?: {
    observations: Array<{
      observation: string
      /** Redundancy number r_i = q_vv_i × p_i  (0=no redundancy, 1=full) */
      redundancyNumber: number
      /** Internal reliability: MDB in observation units (m or arcsec) */
      minimalDetectableBias: number
      /** External reliability: max effect on adjusted coords (m) */
      externalReliability: number
      /** w-test statistic (data snooping): |v_i| / σ_v_i */
      wTestStatistic: number
      /** True if w-test exceeds critical value (outlier suspected) */
      isOutlier: boolean
    }>
    /** Critical value for the w-test (standard normal, default 3.29 = α=0.001) */
    wTestCriticalValue: number
    /** Significance level used for MDB computation */
    alpha: number
    /** Power of test (1-β, default 0.80) */
    power: number
    /** Non-centrality parameter λ₀ for α, β */
    nonCentralityParameter: number
  }
  passed: boolean
  error?: string
}

export interface LSAdjustmentInput {
  fixedPoints: Array<{ name: string; easting: number; northing: number; rl?: number }>
  adjustablePoints: Array<{ name: string; easting: number; northing: number; rl?: number }>
  observations: Observation[]
  dimension?: '2D' | '3D'
  maxIterations?: number
  convergenceMm?: number
  standardizedResidualLimit?: number
  globalTestAlpha?: number
}

type Point = { easting: number; northing: number }

function toRadians(deg: number) {
  return (deg * Math.PI) / 180
}

function wrapAngleRad(rad: number) {
  let a = rad
  while (a <= -Math.PI) a += 2 * Math.PI
  while (a > Math.PI) a -= 2 * Math.PI
  return a
}

function zeros(rows: number, cols: number) {
  return Array.from({ length: rows }, () => Array.from({ length: cols }, () => 0))
}

function transpose(A: number[][]) {
  const rows = A.length
  const cols = A[0]?.length ?? 0
  const T = zeros(cols, rows)
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) T[j][i] = A[i][j]
  }
  return T
}

function matMul(A: number[][], B: number[][]) {
  const r = A.length
  const k = A[0]?.length ?? 0
  const c = B[0]?.length ?? 0
  const out = zeros(r, c)
  for (let i = 0; i < r; i++) {
    for (let j = 0; j < c; j++) {
      let s = 0
      for (let t = 0; t < k; t++) s += A[i][t] * B[t][j]
      out[i][j] = s
    }
  }
  return out
}

function matVecMul(A: number[][], v: number[]) {
  const r = A.length
  const c = A[0]?.length ?? 0
  const out = new Array(r).fill(0)
  for (let i = 0; i < r; i++) {
    let s = 0
    for (let j = 0; j < c; j++) s += A[i][j] * v[j]
    out[i] = s
  }
  return out
}

function gaussianSolve(A: number[][], b: number[]) {
  const n = A.length
  const M = A.map((row, i) => [...row, b[i]])

  for (let k = 0; k < n; k++) {
    // pivot
    let pivotRow = k
    let max = Math.abs(M[k][k])
    for (let i = k + 1; i < n; i++) {
      const v = Math.abs(M[i][k])
      if (v > max) {
        max = v
        pivotRow = i
      }
    }
    if (max === 0 || !isFinite(max)) throw new Error('Normal matrix is singular or ill-conditioned')
    if (pivotRow !== k) {
      const tmp = M[k]
      M[k] = M[pivotRow]
      M[pivotRow] = tmp
    }

    // eliminate
    const pivot = M[k][k]
    for (let j = k; j <= n; j++) M[k][j] /= pivot

    for (let i = 0; i < n; i++) {
      if (i === k) continue
      const factor = M[i][k]
      if (factor === 0) continue
      for (let j = k; j <= n; j++) M[i][j] -= factor * M[k][j]
    }
  }

  return M.map((row: any) => row[n])
}

function invertMatrix(A: number[][]) {
  const n = A.length
  const I = zeros(n, n)
  for (let i = 0; i < n; i++) I[i][i] = 1

  // Solve A * X = I column-by-column
  const inv = zeros(n, n)
  for (let col = 0; col < n; col++) {
    const e = I.map((row: any) => row[col])
    const x = gaussianSolve(A.map((r) => [...r]), [...e])
    for (let i = 0; i < n; i++) inv[i][col] = x[i]
  }
  return inv
}

function dot(a: number[], b: number[]) {
  let s = 0
  for (let i = 0; i < a.length; i++) s += a[i] * b[i]
  return s
}

function normalQuantile(p: number) {
  // Acklam's inverse normal CDF approximation (sufficient for chi-square quantile approximation).
  if (!(p > 0 && p < 1) || !Number.isFinite(p)) return NaN

  const a = [
    -3.969683028665376e+01,
    2.209460984245205e+02,
    -2.759285104469687e+02,
    1.383577518672690e+02,
    -3.066479806614716e+01,
    2.506628277459239e+00,
  ]
  const b = [
    -5.447609879822406e+01,
    1.615858368580409e+02,
    -1.556989798598866e+02,
    6.680131188771972e+01,
    -1.328068155288572e+01,
  ]
  const c = [
    -7.784894002430293e-03,
    -3.223964580411365e-01,
    -2.400758277161838e+00,
    -2.549732539343734e+00,
    4.374664141464968e+00,
    2.938163982698783e+00,
  ]
  const d = [
    7.784695709041462e-03,
    3.224671290700398e-01,
    2.445134137142996e+00,
    3.754408661907416e+00,
  ]

  const plow = 0.02425
  const phigh = 1 - plow

  if (p < plow) {
    const q = Math.sqrt(-2 * Math.log(p))
    return (
      (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
    )
  }

  if (p > phigh) {
    const q = Math.sqrt(-2 * Math.log(1 - p))
    return -(
      (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
    )
  }

  const q = p - 0.5
  const r = q * q
  return (
    (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q /
    (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1)
  )
}

function chiSquareQuantileApprox(p: number, dof: number) {
  // Wilson–Hilferty transform approximation.
  if (!(dof > 0) || !(p > 0 && p < 1)) return NaN
  const z = normalQuantile(p)
  const a = 2 / (9 * dof)
  return dof * Math.pow(1 - a + z * Math.sqrt(a), 3)
}

export function leastSquaresAdjustment(
  fixedPoints: Array<{ name: string; easting: number; northing: number }>,
  unknownPoints: Array<{ name: string; eastingApprox: number; northingApprox: number }>,
  observations: Observation[],
  options?: {
    maxIterations?: number
    convergenceMm?: number
    standardizedResidualLimit?: number
    globalTestAlpha?: number
  }
): LSAdjustmentResult {
  const maxIterations = options?.maxIterations ?? 20
  const convergenceMm = options?.convergenceMm ?? 0.001
  const standardizedResidualLimit = options?.standardizedResidualLimit ?? 3.0
  const globalTestAlpha = options?.globalTestAlpha ?? 0.05

  if (fixedPoints.length < 1) {
    return {
      ok: false,
      adjustedPoints: [],
      residuals: [],
      referenceVariance: 0,
      chiSquare: 0,
      degreesOfFreedom: 0,
      passed: false,
      error: 'Least squares requires at least 1 fixed control point'
    }
  }

  // Warn if only 1 fixed point — cadastral surveys require 2 per Survey Regulations Reg 60 & 67
  const lsqWarnings: string[] = []
  if (fixedPoints.length < 2) {
    lsqWarnings.push('Only 1 fixed control point provided. Per Survey Regulations Reg. 60(2)(c) and Reg. 67, cadastral traverses must close between two previously fixed stations. A single fixed point creates a swinging traverse — prohibited for cadastral surveys.')
  }

  const hasAtLeastOneBearing = observations.some((o) => typeof o.bearing === 'number')
  if (!hasAtLeastOneBearing && fixedPoints.length < 2) {
    return {
      ok: false,
      adjustedPoints: [],
      residuals: [],
      referenceVariance: 0,
      chiSquare: 0,
      degreesOfFreedom: 0,
      passed: false,
      error: 'With distance-only observations, at least 2 fixed points are required to prevent rotation'
    }
  }

  const unknownIndex = new Map<string, number>()
  unknownPoints.forEach((p, i) => unknownIndex.set(p.name, i))

  const fixed = new Map<string, Point>()
  fixedPoints.forEach((p) => fixed.set(p.name, { easting: p.easting, northing: p.northing }))

  const x: number[] = new Array(unknownPoints.length * 2)
  for (let i = 0; i < unknownPoints.length; i++) {
    x[2 * i] = unknownPoints[i].eastingApprox
    x[2 * i + 1] = unknownPoints[i].northingApprox
  }

  const getPoint = (name: string): Point | null => {
    const f = fixed.get(name)
    if (f) return f
    const idx = unknownIndex.get(name)
    if (idx === undefined) return null
    return { easting: x[2 * idx], northing: x[2 * idx + 1] }
  }

  const activeObservations = observations.filter((o) => o.distance !== undefined || o.bearing !== undefined)
  const m = activeObservations.length
  const n = unknownPoints.length * 2
  if (m <= n) {
    return {
      ok: false,
      adjustedPoints: [],
      residuals: [],
      referenceVariance: 0,
      chiSquare: 0,
      degreesOfFreedom: 0,
      passed: false,
      error: `Insufficient redundancy: observations=${m}, unknowns=${n}`
    }
  }

  let lastDxMax = Infinity

  let A: number[][] = []
  let w: number[] = []
  let Pdiag: number[] = []
  let computedResiduals: Array<{ key: string; residual: number; weight: number; aRow: number[] }> = []

  for (let iter = 0; iter < maxIterations; iter++) {
    A = zeros(m, n)
    w = new Array(m).fill(0)
    Pdiag = new Array(m).fill(0)
    computedResiduals = []

    for (let i = 0; i < m; i++) {
      const obs = activeObservations[i]
      const from = getPoint(obs.from)
      const to = getPoint(obs.to)
      if (!from || !to) {
        return {
          ok: false,
          adjustedPoints: [],
          residuals: [],
          referenceVariance: 0,
          chiSquare: 0,
          degreesOfFreedom: 0,
          passed: false,
          error: `Unknown point referenced in observation: ${obs.from} -> ${obs.to}`
        }
      }

      const dE = to.easting - from.easting
      const dN = to.northing - from.northing
      const r2 = dE * dE + dN * dN
      const r = Math.sqrt(r2)

      const fromUnknown = unknownIndex.get(obs.from)
      const toUnknown = unknownIndex.get(obs.to)

      let row = new Array(n).fill(0)
      let residual = 0

      if (obs.distance !== undefined) {
        if (r === 0) {
          return {
            ok: false,
            adjustedPoints: [],
            residuals: [],
            referenceVariance: 0,
            chiSquare: 0,
            degreesOfFreedom: 0,
            passed: false,
            error: `Zero distance geometry in observation: ${obs.from} -> ${obs.to}`
          }
        }

        // f = sqrt(dE^2 + dN^2)
        // partials w.r.t coords of from/to
        const dfdE = dE / r
        const dfdN = dN / r

        if (fromUnknown !== undefined) {
          row[2 * fromUnknown] = -dfdE
          row[2 * fromUnknown + 1] = -dfdN
        }
        if (toUnknown !== undefined) {
          row[2 * toUnknown] = dfdE
          row[2 * toUnknown + 1] = dfdN
        }

        residual = obs.distance - r
      } else if (obs.bearing !== undefined) {
        if (r2 === 0) {
          return {
            ok: false,
            adjustedPoints: [],
            residuals: [],
            referenceVariance: 0,
            chiSquare: 0,
            degreesOfFreedom: 0,
            passed: false,
            error: `Zero bearing geometry in observation: ${obs.from} -> ${obs.to}`
          }
        }

        const theta = Math.atan2(dE, dN) // WCB, radians
        const l = toRadians(obs.bearing)
        residual = wrapAngleRad(l - theta)

        // θ = atan2(dE, dN)
        // ∂θ/∂dE = dN / (dE^2 + dN^2)
        // ∂θ/∂dN = -dE / (dE^2 + dN^2)
        const dtdE = dN / r2
        const dtdN = -dE / r2

        if (fromUnknown !== undefined) {
          row[2 * fromUnknown] = -(-dtdE) // because dE = E_to - E_from
          row[2 * fromUnknown + 1] = -(-dtdN) // dN = N_to - N_from
          // Simplify: θ depends on dE,dN; with respect to E_from: ∂θ/∂E_from = -∂θ/∂dE
          row[2 * fromUnknown] = -dtdE
          row[2 * fromUnknown + 1] = -dtdN
        }
        if (toUnknown !== undefined) {
          row[2 * toUnknown] = dtdE
          row[2 * toUnknown + 1] = dtdN
        }
      }

      A[i] = row
      w[i] = residual
      const weightFromSigmas = () => {
        if (obs.distance !== undefined && typeof obs.distanceSigma === 'number' && obs.distanceSigma > 0) {
          return 1 / (obs.distanceSigma * obs.distanceSigma)
        }
        if (obs.bearing !== undefined && typeof obs.bearingSigmaArcSec === 'number' && obs.bearingSigmaArcSec > 0) {
          const sigmaRad = (obs.bearingSigmaArcSec * Math.PI) / (180 * 3600)
          return 1 / (sigmaRad * sigmaRad)
        }
        return 1
      }

      const weight = typeof obs.weight === 'number' && obs.weight > 0 ? obs.weight : weightFromSigmas()
      Pdiag[i] = weight

      computedResiduals.push({
        key: `${obs.from}->${obs.to}:${obs.distance !== undefined ? 'D' : 'B'}`,
        residual,
        weight,
        aRow: row,
      })
    }

    // Build normal equations: N = A^T P A, u = A^T P w
    const At = transpose(A)

    const PA = zeros(m, n)
    const Pw = new Array(m).fill(0)
    for (let i = 0; i < m; i++) {
      const p = Pdiag[i]
      Pw[i] = p * w[i]
      for (let j = 0; j < n; j++) PA[i][j] = p * A[i][j]
    }

    const Nmat = matMul(At, PA)
    const u = matVecMul(At, Pw)

    let dx: number[]
    try {
      dx = gaussianSolve(Nmat.map((r) => [...r]), u)
    } catch (e: unknown) {
      return {
        ok: false,
        adjustedPoints: [],
        residuals: [],
        referenceVariance: 0,
        chiSquare: 0,
        degreesOfFreedom: 0,
        passed: false,
        error: (e instanceof Error ? (e as Error).message : String(e)),
      }
    }

    let dxMax = 0
    for (let i = 0; i < dx.length; i++) {
      x[i] += dx[i]
      dxMax = Math.max(dxMax, Math.abs(dx[i]))
    }

    lastDxMax = dxMax
    if (dxMax * 1000 <= convergenceMm) break
    if (!isFinite(dxMax)) break
  }

  if (!isFinite(lastDxMax)) {
    return {
      ok: false,
      adjustedPoints: [],
      residuals: [],
      referenceVariance: 0,
      chiSquare: 0,
      degreesOfFreedom: 0,
      passed: false,
      error: 'Adjustment diverged',
    }
  }

  // Rebuild design matrix at final estimates (for covariance + residual tests).
  A = zeros(m, n)
  w = new Array(m).fill(0)
  Pdiag = new Array(m).fill(0)
  computedResiduals = []

  for (let i = 0; i < m; i++) {
    const obs = activeObservations[i]
    const from = getPoint(obs.from)
    const to = getPoint(obs.to)
    if (!from || !to) {
      return {
        ok: false,
        adjustedPoints: [],
        residuals: [],
        referenceVariance: 0,
        chiSquare: 0,
        degreesOfFreedom: 0,
        passed: false,
        error: `Unknown point referenced in observation: ${obs.from} -> ${obs.to}`,
      }
    }

    const dE = to.easting - from.easting
    const dN = to.northing - from.northing
    const r2 = dE * dE + dN * dN
    const r = Math.sqrt(r2)

    const fromUnknown = unknownIndex.get(obs.from)
    const toUnknown = unknownIndex.get(obs.to)

    let row = new Array(n).fill(0)
    let residual = 0

    if (obs.distance !== undefined) {
      if (r === 0) {
        return {
          ok: false,
          adjustedPoints: [],
          residuals: [],
          referenceVariance: 0,
          chiSquare: 0,
          degreesOfFreedom: 0,
          passed: false,
          error: `Zero distance geometry in observation: ${obs.from} -> ${obs.to}`,
        }
      }

      const dfdE = dE / r
      const dfdN = dN / r

      if (fromUnknown !== undefined) {
        row[2 * fromUnknown] = -dfdE
        row[2 * fromUnknown + 1] = -dfdN
      }
      if (toUnknown !== undefined) {
        row[2 * toUnknown] = dfdE
        row[2 * toUnknown + 1] = dfdN
      }

      residual = obs.distance - r
    } else if (obs.bearing !== undefined) {
      if (r2 === 0) {
        return {
          ok: false,
          adjustedPoints: [],
          residuals: [],
          referenceVariance: 0,
          chiSquare: 0,
          degreesOfFreedom: 0,
          passed: false,
          error: `Zero bearing geometry in observation: ${obs.from} -> ${obs.to}`,
        }
      }

      const theta = Math.atan2(dE, dN)
      const l = toRadians(obs.bearing)
      residual = wrapAngleRad(l - theta)

      const dtdE = dN / r2
      const dtdN = -dE / r2

      if (fromUnknown !== undefined) {
        row[2 * fromUnknown] = -dtdE
        row[2 * fromUnknown + 1] = -dtdN
      }
      if (toUnknown !== undefined) {
        row[2 * toUnknown] = dtdE
        row[2 * toUnknown + 1] = dtdN
      }
    }

      A[i] = row
      w[i] = residual
      const weightFromSigmas = () => {
        if (obs.distance !== undefined && typeof obs.distanceSigma === 'number' && obs.distanceSigma > 0) {
          return 1 / (obs.distanceSigma * obs.distanceSigma)
        }
        if (obs.bearing !== undefined && typeof obs.bearingSigmaArcSec === 'number' && obs.bearingSigmaArcSec > 0) {
          const sigmaRad = (obs.bearingSigmaArcSec * Math.PI) / (180 * 3600)
          return 1 / (sigmaRad * sigmaRad)
        }
        return 1
      }

      const weight = typeof obs.weight === 'number' && obs.weight > 0 ? obs.weight : weightFromSigmas()
      Pdiag[i] = weight
      computedResiduals.push({
        key: `${obs.from}->${obs.to}:${obs.distance !== undefined ? 'D' : 'B'}`,
        residual,
        weight,
        aRow: row,
      })
  }

  // Compute final residuals:
  // w_final = l - f(x̂); v = -w_final.
  const v = new Array(m).fill(0)
  const obsLabel: string[] = new Array(m).fill('')
  for (let i = 0; i < m; i++) {
    const obs = activeObservations[i]
    const from = getPoint(obs.from)!
    const to = getPoint(obs.to)!
    const dE = to.easting - from.easting
    const dN = to.northing - from.northing
    const r2 = dE * dE + dN * dN
    const r = Math.sqrt(r2)

    if (obs.distance !== undefined) {
      v[i] = -(obs.distance - r)
      obsLabel[i] = `${obs.from}→${obs.to} distance`
    } else if (obs.bearing !== undefined) {
      const theta = Math.atan2(dE, dN)
      const l = toRadians(obs.bearing)
      v[i] = -wrapAngleRad(l - theta)
      obsLabel[i] = `${obs.from}→${obs.to} bearing`
    }
  }

  const dof = m - n
  const vPv = v.reduce((sum, vi, i) => sum + Pdiag[i] * vi * vi, 0)
  const referenceVariance = dof > 0 ? vPv / dof : 0

  // Parameter covariance: Σxx = σ0^2 * N^{-1}
  let Ninv: number[][]
  try {
    // Rebuild N at final for covariance
    const At = transpose(A)
    const PA = zeros(m, n)
    for (let i = 0; i < m; i++) {
      const p = Pdiag[i]
      for (let j = 0; j < n; j++) PA[i][j] = p * A[i][j]
    }
    const Nmat = matMul(At, PA)
    Ninv = invertMatrix(Nmat)
  } catch {
    Ninv = zeros(n, n)
  }

  const adjustedPoints = unknownPoints.map((p, i) => {
    const varE = referenceVariance * (Ninv[2 * i]?.[2 * i] ?? 0)
    const varN = referenceVariance * (Ninv[2 * i + 1]?.[2 * i + 1] ?? 0)
    return {
      name: p.name,
      easting: x[2 * i],
      northing: x[2 * i + 1],
      sigmaEasting: varE > 0 ? Math.sqrt(varE) : 0,
      sigmaNorthing: varN > 0 ? Math.sqrt(varN) : 0,
    }
  })

  // Residual covariance diagonal: qvv_i = 1/weight - a_i^T Qxx a_i
  const residuals = computedResiduals.map((r, i) => {
    const a = r.aRow
    const Qxx = Ninv
    const Qa = matVecMul(Qxx, a)
    const aTQa = dot(a, Qa)

    const qll = 1 / r.weight
    const qvv = Math.max(0, qll - aTQa)
    const denom = Math.sqrt((referenceVariance || 1) * (qvv || qll || 1))

    return {
      observation: obsLabel[i] || r.key,
      residual: v[i],
      standardizedResidual: denom > 0 ? v[i] / denom : 0,
    }
  })

  const passed = residuals.every(r => Math.abs(r.standardizedResidual) <= standardizedResidualLimit)

  const globalTest =
    dof > 0 && globalTestAlpha > 0 && globalTestAlpha < 1
      ? (() => {
          const lower = chiSquareQuantileApprox(globalTestAlpha / 2, dof)
          const upper = chiSquareQuantileApprox(1 - globalTestAlpha / 2, dof)
          const globalPassed = Number.isFinite(lower) && Number.isFinite(upper) ? vPv >= lower && vPv <= upper : true
          return { alpha: globalTestAlpha, lower, upper, passed: globalPassed }
        })()
      : undefined

  return {
    ok: true,
    adjustedPoints,
    residuals,
    referenceVariance,
    chiSquare: vPv,
    degreesOfFreedom: dof,
    globalTest,
    passed,
  }
}

/**
 * Unified 2D/3D Least Squares Network Adjustment
 *
 * Supports 6 observation types: distance, bearing, angle, slope_distance,
 * zenith_angle, height_difference. Angle observations are modeled as
 * the difference of two direction observations (Ghilani/Wolf Ch.14).
 *
 * 3D mode adds RL as a third unknown per point and handles slope distances,
 * zenith angles, and height differences.
 */
export function adjustNetwork(input: LSAdjustmentInput): LSAdjustmentResult {
  const is3D = input.dimension === '3D'
  const dim = is3D ? 3 : 2
  const maxIter = input.maxIterations ?? 20
  const convMm = input.convergenceMm ?? 0.001
  const stdResLimit = input.standardizedResidualLimit ?? 3.0
  const globalAlpha = input.globalTestAlpha ?? 0.05

  if (input.fixedPoints.length < 1) {
    return failResult('At least 1 fixed control point required')
  }

  const unknownIdx = new Map<string, number>()
  input.adjustablePoints.forEach((p, i) => unknownIdx.set(p.name, i))

  const fixedCoords = new Map<string, { e: number; n: number; h: number }>()
  for (const fp of input.fixedPoints) {
    fixedCoords.set(fp.name, { e: fp.easting, n: fp.northing, h: fp.rl ?? 0 })
  }

  // Working coordinate array: per unknown point, [E, N, (RL)]
  const nPts = input.adjustablePoints.length
  const nUnknowns = nPts * dim
  const x = new Array(nUnknowns).fill(0)
  for (let i = 0; i < nPts; i++) {
    x[dim * i] = input.adjustablePoints[i].easting
    x[dim * i + 1] = input.adjustablePoints[i].northing
    if (is3D) x[dim * i + 2] = input.adjustablePoints[i].rl ?? 0
  }

  function getCoord(name: string): { e: number; n: number; h: number } | null {
    const f = fixedCoords.get(name)
    if (f) return f
    const idx = unknownIdx.get(name)
    if (idx === undefined) return null
    return { e: x[dim * idx], n: x[dim * idx + 1], h: is3D ? x[dim * idx + 2] : 0 }
  }

  // Classify observations into active set
  const active = input.observations.filter((o) => {
    if (o.type === 'angle') return o.occupied && o.backsight && o.foresight && typeof o.angle === 'number'
    if (o.type === 'slope_distance') return o.from && o.to && typeof o.slopeDistance === 'number'
    if (o.type === 'zenith_angle') return o.from && o.to && typeof o.zenithAngle === 'number'
    if (o.type === 'height_difference') return o.from && o.to && typeof o.heightDifference === 'number'
    return (typeof o.distance === 'number') || (typeof o.bearing === 'number')
  })

  const m = active.length
  if (m < 1) {
    return failResult('No valid observations')
  }

  // Under-determined systems (m < nUnknowns) are handled via Tikhonov regularization.
  // This produces the minimum-norm solution (free network / inner constraint adjustment).
  // It keeps adjusted values close to their initial approximations for unconstrained params.

  let lastDxMax = Infinity
  let finalA: number[][] = zeros(m, nUnknowns)
  let finalW: number[] = new Array(m).fill(0)
  let finalP: number[] = new Array(m).fill(0)
  let finalLabels: string[] = new Array(m).fill('')
  let finalObsList: unknown[] = []

  for (let iter = 0; iter < maxIter; iter++) {
    const A = zeros(m, nUnknowns)
    const w = new Array(m).fill(0)
    const P = new Array(m).fill(0)
    let hasNaN = false

    for (let i = 0; i < m; i++) {
      const obs = active[i]
      const result = buildObservationRow(obs, getCoord, unknownIdx, dim, is3D)
      if (!result) { hasNaN = true; break }

      A[i] = result.row
      w[i] = result.residual
      P[i] = result.weight
    }

    if (hasNaN) break

    // Normal equations: N = A^T P A, u = A^T P w
    const At = transpose(A)
    const PA = zeros(m, nUnknowns)
    const Pw = new Array(m).fill(0)
    for (let i = 0; i < m; i++) {
      Pw[i] = P[i] * w[i]
      for (let j = 0; j < nUnknowns; j++) PA[i][j] = P[i] * A[i][j]
    }
    const Nmat = matMul(At, PA)
    const u = matVecMul(At, Pw)

    // Tikhonov regularization for near-singular or under-determined systems.
    // Adds a tiny diagonal term so the matrix is always positive-definite.
    // This implements free-network (inner constraint) adjustment per Ghilani Ch.15.
    const regAlpha = 1e-10
    for (let i = 0; i < nUnknowns; i++) {
      Nmat[i][i] += regAlpha
    }

    let dx: number[]
    try {
      dx = gaussianSolve(Nmat.map((r) => [...r]), u)
    } catch {
      return failResult('Normal matrix singular or ill-conditioned')
    }

    let dxMax = 0
    for (let i = 0; i < dx.length; i++) {
      x[i] += dx[i]
      if (isFinite(dx[i])) dxMax = Math.max(dxMax, Math.abs(dx[i]))
    }
    lastDxMax = dxMax
    if (dxMax * 1000 <= convMm) break
    if (!isFinite(dxMax)) break

    // Save final iteration data
    finalA = A
    finalW = w
    finalP = P
    finalObsList = active
    for (let i = 0; i < m; i++) {
      const obs = active[i]
      finalLabels[i] = obsLabel(obs)
    }
  }

  if (!isFinite(lastDxMax)) {
    return failResult('Adjustment diverged')
  }

  // Rebuild at final estimates for residuals and covariance
  const A = zeros(m, nUnknowns)
  const w = new Array(m).fill(0)
  const P = new Array(m).fill(0)

  for (let i = 0; i < m; i++) {
    const obs = active[i]
    const result = buildObservationRow(obs, getCoord, unknownIdx, dim, is3D)
    if (!result) continue
    A[i] = result.row
    w[i] = result.residual
    P[i] = result.weight
    finalLabels[i] = obsLabel(obs)
  }

  // Compute residuals v = -w (misclosure at final estimate)
  const v = w.map(wi => -wi)
  const dof = m - nUnknowns
  const vPv = v.reduce((s, vi, i) => s + P[i] * vi * vi, 0)
  const refVar = dof > 0 ? vPv / dof : 0

  // Covariance
  let Ninv: number[][] = zeros(nUnknowns, nUnknowns)
  try {
    const At = transpose(A)
    const PA = zeros(m, nUnknowns)
    for (let i = 0; i < m; i++) {
      for (let j = 0; j < nUnknowns; j++) PA[i][j] = P[i] * A[i][j]
    }
    Ninv = invertMatrix(matMul(At, PA))
  } catch {
    // Ninv stays as zeros
  }

  // Build adjusted points with sigmas
  const adjustedPoints = input.adjustablePoints.map((p, i) => {
    const varE = refVar * (Ninv[dim * i]?.[dim * i] ?? 0)
    const varN = refVar * (Ninv[dim * i + 1]?.[dim * i + 1] ?? 0)
    const pt: any = {
      name: p.name,
      easting: x[dim * i],
      northing: x[dim * i + 1],
      sigmaEasting: varE > 0 ? Math.sqrt(varE) : 0,
      sigmaNorthing: varN > 0 ? Math.sqrt(varN) : 0,
    }
    if (is3D) {
      const varH = refVar * (Ninv[dim * i + 2]?.[dim * i + 2] ?? 0)
      pt.rl = x[dim * i + 2]
      pt.sigmaRL = varH > 0 ? Math.sqrt(varH) : 0
    }
    return pt
  })

  // Standardized residuals
  const residuals = v.map((vi, i) => {
    const aRow = A[i]
    const Qa = matVecMul(Ninv, aRow)
    const aTQa = dot(aRow, Qa)
    const qll = P[i] > 0 ? 1 / P[i] : 1
    const qvv = Math.max(0, qll - aTQa)
    const denom = Math.sqrt((refVar || 1) * (qvv || qll || 1))
    return {
      observation: finalLabels[i],
      residual: vi,
      standardizedResidual: denom > 0 ? vi / denom : 0,
    }
  })

  const passed = residuals.every(r => Math.abs(r.standardizedResidual) <= stdResLimit)

  const globalTest =
    dof > 0 && globalAlpha > 0 && globalAlpha < 1
      ? (() => {
          const lower = chiSquareQuantileApprox(globalAlpha / 2, dof)
          const upper = chiSquareQuantileApprox(1 - globalAlpha / 2, dof)
          const gp = Number.isFinite(lower) && Number.isFinite(upper) ? vPv >= lower && vPv <= upper : true
          return { alpha: globalAlpha, lower, upper, passed: gp }
        })()
      : undefined

  // ─── Baarda Reliability Analysis (H13, 2026-07-03) ───────────────────────
  //
  // For each observation i, compute:
  //   1. Redundancy number:  r_i = q_vv_i × p_i = 1 - (a_iᵀ · Qxx · a_i) × p_i
  //      where q_vv_i is the diagonal of Qvv = P⁻¹ - A·Qxx·Aᵀ
  //   2. w-test (data snooping):  w_i = |v_i| / √(σ̂₀² · q_vv_i)
  //      Reject H0 if w_i > z_{1-α/2}  (critical value from standard normal)
  //   3. Internal reliability (MDB):  ∇₀_i = (σ̂₀ · √(λ₀)) / √(p_i · r_i)
  //      where λ₀ is the non-centrality parameter for α, β
  //   4. External reliability:  ∇x_i = (Aᵀ·P·A)⁻¹ · a_iᵀ · p_i · ∇₀_i
  //      (max absolute coordinate effect)
  //
  // The non-centrality parameter λ₀ depends on α (significance) and β (power):
  //   λ₀ = (z_{1-α/2} + z_{1-β})²
  // For α=0.001, β=0.20 (power=0.80):  λ₀ = (3.29 + 0.84)² ≈ 17.07
  const reliability = (() => {
    if (dof <= 0 || !A || A.length === 0) return undefined

    const alpha = 0.001  // Baarda's standard α for the w-test
    const beta = 0.20    // 1-β = 0.80 power
    const power = 1 - beta
    // normalQuantile is the inverse standard normal CDF (Acklam's approx)
    const zAlpha = normalQuantile(1 - alpha / 2)  // ≈ 3.2905
    const zBeta = normalQuantile(power)            // ≈ 0.8416
    const lambda0 = Math.pow(zAlpha + zBeta, 2)    // ≈ 17.075
    const s0 = Math.sqrt(Math.max(refVar, 1e-15))

    const obsReliability = v.map((vi, i) => {
      const aRow = A[i]
      const pi = P[i]
      const qll = pi > 0 ? 1 / pi : 1
      const Qa = matVecMul(Ninv, aRow)
      const aTQa = dot(aRow, Qa)
      const qvv = Math.max(0, qll - aTQa)

      // 1. Redundancy number
      const r_i = qvv * pi

      // 2. w-test statistic
      const sigmaVi = Math.sqrt(Math.max(refVar, 1e-15) * qvv)
      const w_i = sigmaVi > 0 ? Math.abs(vi) / sigmaVi : 0

      // 3. Internal reliability (MDB) — guard against r_i → 0
      const mdb = r_i > 1e-10
        ? (s0 * Math.sqrt(lambda0)) / Math.sqrt(pi * r_i)
        : Infinity

      // 4. External reliability — max coordinate effect
      //    ∇x = Qxx · a_iᵀ · p_i · ∇₀_i, take max abs component
      let extRel = 0
      if (r_i > 1e-10 && isFinite(mdb)) {
        const gradX = matVecMul(Ninv, aRow).map(c => c * pi * mdb)
        extRel = Math.max(...gradX.map(Math.abs))
      }

      return {
        observation: finalLabels[i],
        redundancyNumber: Math.max(0, Math.min(1, r_i)),
        minimalDetectableBias: isFinite(mdb) ? mdb : Infinity,
        externalReliability: isFinite(extRel) ? extRel : Infinity,
        wTestStatistic: w_i,
        isOutlier: w_i > zAlpha,
      }
    })

    return {
      observations: obsReliability,
      wTestCriticalValue: zAlpha,
      alpha,
      power,
      nonCentralityParameter: lambda0,
    }
  })()

  return {
    ok: true,
    adjustedPoints,
    residuals,
    referenceVariance: refVar,
    chiSquare: vPv,
    degreesOfFreedom: dof,
    globalTest,
    reliability,
    passed,
  }
}

// ─── Internal helpers for adjustNetwork ──────────────────────────────────────

function failResult(error: string): LSAdjustmentResult {
  return {
    ok: false, adjustedPoints: [], residuals: [],
    referenceVariance: 0, chiSquare: 0, degreesOfFreedom: 0,
    passed: false, error,
  }
}

interface ObsRowResult {
  row: number[]
  residual: number
  weight: number
}

function buildObservationRow(
  obs: any,
  getCoord: (name: string) => { e: number; n: number; h: number } | null,
  unknownIdx: Map<string, number>,
  dim: number,
  is3D: boolean,
): ObsRowResult | null {
  const type = obs.type
  const row = new Array(unknownIdx.size * dim).fill(0)
  let residual = 0
  let weight = 1

  if (type === 'angle') {
    return buildAngleRow(obs, getCoord, unknownIdx, dim)
  }

  if (type === 'slope_distance') {
    const from = getCoord(obs.from)
    const to = getCoord(obs.to)
    if (!from || !to) return null

    const dE = to.e - from.e
    const dN = to.n - from.n
    const dH = to.h - from.h
    const SD = Math.sqrt(dE * dE + dN * dN + dH * dH)
    if (SD === 0) return null

    const fromU = unknownIdx.get(obs.from)
    const toU = unknownIdx.get(obs.to)

    if (fromU !== undefined) {
      row[dim * fromU] = -dE / SD
      row[dim * fromU + 1] = -dN / SD
      if (is3D) row[dim * fromU + 2] = -dH / SD
    }
    if (toU !== undefined) {
      row[dim * toU] = dE / SD
      row[dim * toU + 1] = dN / SD
      if (is3D) row[dim * toU + 2] = dH / SD
    }

    residual = obs.slopeDistance - SD
    if (typeof obs.slopeDistanceSigma === 'number' && obs.slopeDistanceSigma > 0) {
      weight = 1 / (obs.slopeDistanceSigma * obs.slopeDistanceSigma)
    }
    return { row, residual, weight }
  }

  if (type === 'zenith_angle') {
    const from = getCoord(obs.from)
    const to = getCoord(obs.to)
    if (!from || !to) return null

    const dE = to.e - from.e
    const dN = to.n - from.n
    const dH = to.h - from.h
    const horiz = Math.sqrt(dE * dE + dN * dN)
    const SD = Math.sqrt(dE * dE + dN * dN + dH * dH)
    if (SD === 0) return null

    // Zenith angle from vertical: Z = atan2(horiz, dH) (radians)
    const Z = Math.atan2(horiz, dH)
    const obsZ = toRadians(obs.zenithAngle)
    residual = wrapAngleRad(obsZ - Z)

    // Partials of Z w.r.t. dE, dN, dH
    // Z = atan2(horiz, dH)
    // ∂Z/∂dH = -horiz / SD²
    // ∂Z/∂horiz = dH / SD²
    // ∂Z/∂dE = (dH / SD²) * (dE / horiz)
    // ∂Z/∂dN = (dH / SD²) * (dN / horiz)

    const fromU = unknownIdx.get(obs.from)
    const toU = unknownIdx.get(obs.to)

    const dZdE = horiz > 1e-12 ? (dH / (SD * SD)) * (dE / horiz) : 0
    const dZdN = horiz > 1e-12 ? (dH / (SD * SD)) * (dN / horiz) : 0
    const dZdH = -horiz / (SD * SD)

    if (fromU !== undefined) {
      row[dim * fromU] = -dZdE
      row[dim * fromU + 1] = -dZdN
      if (is3D) row[dim * fromU + 2] = -dZdH
    }
    if (toU !== undefined) {
      row[dim * toU] = dZdE
      row[dim * toU + 1] = dZdN
      if (is3D) row[dim * toU + 2] = dZdH
    }

    if (typeof obs.zenithAngleSigmaArcSec === 'number' && obs.zenithAngleSigmaArcSec > 0) {
      const sigmaRad = (obs.zenithAngleSigmaArcSec * Math.PI) / (180 * 3600)
      weight = 1 / (sigmaRad * sigmaRad)
    }
    return { row, residual, weight }
  }

  if (type === 'height_difference') {
    const from = getCoord(obs.from)
    const to = getCoord(obs.to)
    if (!from || !to) return null

    const dH = to.h - from.h
    residual = obs.heightDifference - dH

    const fromU = unknownIdx.get(obs.from)
    const toU = unknownIdx.get(obs.to)

    if (fromU !== undefined && is3D) {
      row[dim * fromU + 2] = -1
    }
    if (toU !== undefined && is3D) {
      row[dim * toU + 2] = 1
    }

    if (typeof obs.heightDiffSigma === 'number' && obs.heightDiffSigma > 0) {
      weight = 1 / (obs.heightDiffSigma * obs.heightDiffSigma)
    }
    return { row, residual, weight }
  }

  // Legacy: distance or bearing (no explicit type)
  if (typeof obs.distance === 'number') {
    const from = getCoord(obs.from)
    const to = getCoord(obs.to)
    if (!from || !to) return null

    const dE = to.e - from.e
    const dN = to.n - from.n
    const r = Math.sqrt(dE * dE + dN * dN)
    if (r === 0) return null

    const fromU = unknownIdx.get(obs.from)
    const toU = unknownIdx.get(obs.to)

    if (fromU !== undefined) {
      row[dim * fromU] = -dE / r
      row[dim * fromU + 1] = -dN / r
    }
    if (toU !== undefined) {
      row[dim * toU] = dE / r
      row[dim * toU + 1] = dN / r
    }

    residual = obs.distance - r
    if (typeof obs.distanceSigma === 'number' && obs.distanceSigma > 0) {
      weight = 1 / (obs.distanceSigma * obs.distanceSigma)
    }
    return { row, residual, weight }
  }

  if (typeof obs.bearing === 'number') {
    const from = getCoord(obs.from)
    const to = getCoord(obs.to)
    if (!from || !to) return null

    const dE = to.e - from.e
    const dN = to.n - from.n
    const r2 = dE * dE + dN * dN
    if (r2 === 0) return null

    const theta = Math.atan2(dE, dN)
    const obsRad = toRadians(obs.bearing)
    residual = wrapAngleRad(obsRad - theta)

    const dtdE = dN / r2
    const dtdN = -dE / r2

    const fromU = unknownIdx.get(obs.from)
    const toU = unknownIdx.get(obs.to)

    if (fromU !== undefined) {
      row[dim * fromU] = -dtdE
      row[dim * fromU + 1] = -dtdN
    }
    if (toU !== undefined) {
      row[dim * toU] = dtdE
      row[dim * toU + 1] = dtdN
    }

    if (typeof obs.bearingSigmaArcSec === 'number' && obs.bearingSigmaArcSec > 0) {
      const sigmaRad = (obs.bearingSigmaArcSec * Math.PI) / (180 * 3600)
      weight = 1 / (sigmaRad * sigmaRad)
    }
    return { row, residual, weight }
  }

  return null
}

function buildAngleRow(
  obs: any,
  getCoord: (name: string) => { e: number; n: number; h: number } | null,
  unknownIdx: Map<string, number>,
  dim: number,
): ObsRowResult | null {
  const occ = getCoord(obs.occupied)
  const bs = getCoord(obs.backsight)
  const fs = getCoord(obs.foresight)
  if (!occ || !bs || !fs) return null

  // Direction vectors
  const dE_OF = fs.e - occ.e
  const dN_OF = fs.n - occ.n
  const r2_OF = dE_OF * dE_OF + dN_OF * dN_OF
  if (r2_OF === 0) return null

  const dE_OB = bs.e - occ.e
  const dN_OB = bs.n - occ.n
  const r2_OB = dE_OB * dE_OB + dN_OB * dN_OB
  if (r2_OB === 0) return null

  // Computed angle (radians)
  const theta_OF = Math.atan2(dE_OF, dN_OF)
  const theta_OB = Math.atan2(dE_OB, dN_OB)
  const computedAngle = wrapAngleRad(theta_OF - theta_OB)
  const obsAngle = toRadians(obs.angle)
  const residual = wrapAngleRad(obsAngle - computedAngle)

  const row = new Array(unknownIdx.size * dim).fill(0)

  // Direction partials: ∂θ_OP/∂E_P = dN / r², ∂θ_OP/∂N_P = -dE / r²
  // ∂θ_OP/∂E_O = -dN / r², ∂θ_OP/∂N_O = dE / r²
  const dtdE_OF = dN_OF / r2_OF  // ∂θ_OF/∂E_F = ∂θ_OF/∂E_occ
  const dtdN_OF = -dE_OF / r2_OF
  const dtdE_OB = dN_OB / r2_OB
  const dtdN_OB = -dE_OB / r2_OB

  // angle = θ_OF - θ_OB
  // ∂angle/∂E_occ = -dtdE_OF + dtdE_OB
  // ∂angle/∂N_occ = -dtdN_OF + dtdN_OB
  // ∂angle/∂E_bs = -dtdE_OB (affects only backsight)
  // ∂angle/∂N_bs = -dtdN_OB
  // ∂angle/∂E_fs = dtdE_OF (affects only foresight)
  // ∂angle/∂N_fs = dtdN_OF

  const occU = unknownIdx.get(obs.occupied)
  const bsU = unknownIdx.get(obs.backsight)
  const fsU = unknownIdx.get(obs.foresight)

  if (occU !== undefined) {
    row[dim * occU] = -dtdE_OF + dtdE_OB
    row[dim * occU + 1] = -dtdN_OF + dtdN_OB
  }
  if (bsU !== undefined) {
    row[dim * bsU] = -dtdE_OB
    row[dim * bsU + 1] = -dtdN_OB
  }
  if (fsU !== undefined) {
    row[dim * fsU] = dtdE_OF
    row[dim * fsU + 1] = dtdN_OF
  }

  let weight = 1
  if (typeof obs.angleSigmaArcSec === 'number' && obs.angleSigmaArcSec > 0) {
    const sigmaRad = (obs.angleSigmaArcSec * Math.PI) / (180 * 3600)
    weight = 1 / (sigmaRad * sigmaRad)
  }

  return { row, residual, weight }
}

function obsLabel(obs: any): string {
  const t = obs.type
  if (t === 'angle') return `${obs.occupied}: ${obs.backsight}→${obs.foresight} angle`
  if (t === 'slope_distance') return `${obs.from}→${obs.to} slope_dist`
  if (t === 'zenith_angle') return `${obs.from}→${obs.to} zenith`
  if (t === 'height_difference') return `${obs.from}→${obs.to} ΔH`
  if (typeof obs.distance === 'number') return `${obs.from}→${obs.to} distance`
  if (typeof obs.bearing === 'number') return `${obs.from}→${obs.to} bearing`
  return `${obs.from}→${obs.to} ?`
}

export function calculateRedundancy(unknowns: number, observations: number): number {
  return observations - unknowns * 2
}

export function getPrecisionGrade(ratio: number): string {
  if (ratio >= 5000) return 'excellent'
  if (ratio >= 3000) return 'good'
  if (ratio >= 1000) return 'acceptable'
  return 'poor'
}

/**
 * @deprecated P1-5 (2026-07-24): Use `@/lib/engine/networkAdjustment.ts`
 *   (the `adjustNetwork` function) instead. That module is the canonical
 *   enterprise-grade LSA with sparse Cholesky, free-network inner
 *   constraints, Huber robust estimation, and full Baarda reliability.
 *   This older parametric-LSA module lacks those features and is kept
 *   only because `/tools/lsa` imports `adjustTraverseLSA` from here.
 *   New code should not import from this module.
 *
 * @module leastSquaresAdjustment
 *
 * Least Squares Adjustment for survey control networks
 *
 * Implements parametric (indirect observations) least squares adjustment:
 * 1. Set up observation equations: L + V = A·X
 * 2. Form normal equations: (AᵀP A)·X = AᵀP L
 * 3. Solve for corrections: X = (AᵀP A)⁻¹ · AᵀP L
 * 4. Compute residuals, standard error, confidence ellipses
 *
 * For traverse networks:
 * - Observations: angles, distances
 * - Parameters: station coordinates (E, N)
 * - Weight matrix: P = diag(1/σ²)
 *
 * Reference: "Adjustment Computations" by Ghilani & Wolf (6th edition)
 *
 * This is needed for high-precision control surveys where Bowditch
 * (compass rule) is insufficient — it doesn't properly weight
 * different observation types.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ControlStation {
  id: string
  name: string
  easting: number
  northing: number
  isFixed: boolean  // known control point (not adjusted)
}

export interface AngleObservation {
  id: string
  fromStationId: string
  toStationId: string
  /**
   * The station at the vertex of the angle (where the instrument is set up).
   * The angle is measured clockwise from the backsight (fromStation) to the
   * foresight (toStation), as observed at the atStation.
   *
   * If atStationId is omitted, the observation is treated as a bearing
   * (direction) from fromStation to toStation — NOT an interior angle.
   *
   * AUDIT FIX (2026-07-03): Added atStationId so the engine can compute
   * true interior angles (θ = α_BC − α_BA) instead of treating every
   * "angle" as a bearing. The page collects from/at/to for a reason.
   */
  atStationId?: string
  angle: number  // decimal degrees
  stdDev: number // seconds
}

export interface DistanceObservation {
  id: string
  fromStationId: string
  toStationId: string
  distance: number  // meters
  stdDev: number    // meters (e.g., 0.002 + 2ppm)
}

export interface TraverseObservations {
  stations: ControlStation[]
  angles: AngleObservation[]
  distances: DistanceObservation[]
}

export interface AdjustedStation {
  id: string
  name: string
  adjustedEasting: number
  adjustedNorthing: number
  correctionE: number  // adjustment in Easting
  correctionN: number  // adjustment in Northing
  stdDevE: number     // standard error in E
  stdDevN: number     // standard error in N
  errorEllipse: {
    semiMajor: number  // meters
    semiMinor: number  // meters
    orientation: number  // degrees from N
  }
}

export interface Residual {
  observationId: string
  type: 'angle' | 'distance'
  observed: number
  computed: number
  residual: number  // observed - computed
  standardized: number  // v / √(q_vv · σ₀²)
  /** AUDIT FIX (H13, 2026-07-02): Baarda redundancy number r_i = q_vv_i × P_i.
   * Range [0, 1]. r_i = 0 means fully controlled (no check), r_i = 1 means
   * fully redundant. Observations with r_i < 0.1 are weakly controlled. */
  redundancy?: number
  /** AUDIT FIX (H13, 2026-07-02): Minimal Detectable Bias (MDB).
   * The smallest blunder that can be detected at the chosen α/β.
   * In the same units as the observation (metres for distance, degrees for angle). */
  mdb?: number
}

export interface LSAResult {
  adjustedStations: AdjustedStation[]
  residuals: Residual[]
  referenceVariance: number  // σ₀²
  degreesOfFreedom: number
  standardError: number  // σ₀ (a posteriori)
  passed: boolean  // chi-square test
  chiSquareValue: number
  chiSquareCritical: number
  report: string
}

// ---------------------------------------------------------------------------
// Matrix operations (minimal implementation)
// ---------------------------------------------------------------------------

type Matrix = number[][]
type Vector = number[]

function transpose(A: Matrix): Matrix {
  const rows = A.length
  const cols = A[0].length
  const result: Matrix = Array(cols).fill(null).map(() => Array(rows).fill(0))
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      result[j][i] = A[i][j]
    }
  }
  return result
}

function multiply(A: Matrix, B: Matrix): Matrix {
  const rowsA = A.length
  const colsA = A[0].length
  const colsB = B[0].length
  const result: Matrix = Array(rowsA).fill(null).map(() => Array(colsB).fill(0))
  for (let i = 0; i < rowsA; i++) {
    for (let j = 0; j < colsB; j++) {
      for (let k = 0; k < colsA; k++) {
        result[i][j] += A[i][k] * B[k][j]
      }
    }
  }
  return result
}

function multiplyVector(A: Matrix, v: Vector): Vector {
  const rows = A.length
  const cols = A[0].length
  const result: Vector = Array(rows).fill(0)
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      result[i] += A[i][j] * v[j]
    }
  }
  return result
}

function multiplyDiagonal(A: Matrix, diag: Vector): Matrix {
  // Multiply Aᵀ · P where P is diagonal
  const rows = A.length
  const cols = A[0].length
  const result: Matrix = Array(rows).fill(null).map(() => Array(cols).fill(0))
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      result[i][j] = A[i][j] * diag[i]
    }
  }
  return result
}

/**
 * Gauss-Jordan elimination to solve Ax = b and compute A⁻¹.
 */
function solveAndInvert(A: Matrix, b: Vector): { solution: Vector; inverse: Matrix } {
  const n = A.length
  // Augmented matrix [A | I | b]
  const aug: Matrix = A.map((row, i) => [...row, ...Array(n).fill(0).map((_, j) => (j === i ? 1 : 0)), b[i]])

  // Forward elimination
  for (let col = 0; col < n; col++) {
    // Pivot
    let maxRow = col
    for (let row = col + 1; row < n; row++) {
      if (Math.abs(aug[row][col]) > Math.abs(aug[maxRow][col])) {
        maxRow = row
      }
    }
    [aug[col], aug[maxRow]] = [aug[maxRow], aug[col]]

    const pivot = aug[col][col]
    if (Math.abs(pivot) < 1e-15) {
      throw new Error('Matrix is singular — check for redundant observations')
    }

    for (let j = 0; j < aug[col].length; j++) {
      aug[col][j] /= pivot
    }

    for (let row = 0; row < n; row++) {
      if (row === col) continue
      const factor = aug[row][col]
      for (let j = 0; j < aug[row].length; j++) {
        aug[row][j] -= factor * aug[col][j]
      }
    }
  }

  // Extract solution and inverse
  const solution: Vector = aug.map(row => row[row.length - 1])
  const inverse: Matrix = aug.map(row => row.slice(n, 2 * n))

  return { solution, inverse }
}

// ---------------------------------------------------------------------------
// Geometry helpers
// ---------------------------------------------------------------------------

function computeBearing(fromE: number, fromN: number, toE: number, toN: number): number {
  const dE = toE - fromE
  const dN = toN - fromN
  let bearing = Math.atan2(dE, dN) * 180 / Math.PI
  if (bearing < 0) bearing += 360
  return bearing
}

function computeDistance(fromE: number, fromN: number, toE: number, toN: number): number {
  const dE = toE - fromE
  const dN = toN - fromN
  return Math.sqrt(dE * dE + dN * dN)
}

// ---------------------------------------------------------------------------
// Main Adjustment Function
// ---------------------------------------------------------------------------

/**
 * Perform least squares adjustment on a traverse network.
 *
 * @param observations - Stations, angles, and distances
 * @returns Adjustment results with adjusted coordinates, residuals, and statistics
 */
export function adjustTraverseLSA(observations: TraverseObservations): LSAResult {
  const { stations, angles, distances } = observations

  // Identify adjustable stations (not fixed)
  const adjustableStations = stations.filter(s => !s.isFixed)
  const paramCount = adjustableStations.length * 2  // E, N per station

  // Total observations
  const obsCount = angles.length + distances.length
  const degreesOfFreedom = obsCount - paramCount

  if (degreesOfFreedom <= 0) {
    throw new Error(`Insufficient observations: ${obsCount} observations for ${paramCount} parameters (${degreesOfFreedom} DOF)`)
  }

  // Build coefficient matrix A, observation vector L, and weight matrix P
  const A: Matrix = []
  const L: Vector = []
  const P: Vector = []  // diagonal weights

  const stationMap = new Map(stations.map(s => [s.id, s]))
  const adjStationMap = new Map(adjustableStations.map((s, i) => [s.id, i]))

  // Angle observation equations
  for (const angle of angles) {
    const from = stationMap.get(angle.fromStationId)  // backsight
    const to = stationMap.get(angle.toStationId)      // foresight
    if (!from || !to) continue

    const row: Vector = Array(paramCount).fill(0)

    // AUDIT FIX (2026-07-03): If atStationId is provided, compute a true
    // interior angle θ = α_BC − α_BA (bearing from vertex to foresight
    // minus bearing from vertex to backsight). If not, fall back to the
    // old bearing-only behavior for backward compatibility.
    let computedAngle: number
    let dAngle_dE_from: number, dAngle_dN_from: number
    let dAngle_dE_to: number, dAngle_dN_to: number
    let dAngle_dE_at = 0, dAngle_dN_at = 0

    if (angle.atStationId) {
      // ── True interior angle at vertex ──
      const at = stationMap.get(angle.atStationId)
      if (!at) continue

      // Bearing from vertex to backsight (BA)
      const dE_BA = from.easting - at.easting
      const dN_BA = from.northing - at.northing
      const dist_BA = Math.sqrt(dE_BA * dE_BA + dN_BA * dN_BA)
      if (dist_BA < 0.001) continue

      // Bearing from vertex to foresight (BC)
      const dE_BC = to.easting - at.easting
      const dN_BC = to.northing - at.northing
      const dist_BC = Math.sqrt(dE_BC * dE_BC + dN_BC * dN_BC)
      if (dist_BC < 0.001) continue

      // Computed bearings (degrees, 0-360)
      const alpha_BA = computeBearing(at.easting, at.northing, from.easting, from.northing)
      const alpha_BC = computeBearing(at.easting, at.northing, to.easting, to.northing)

      // Interior angle = BC − BA (normalized to 0-360)
      computedAngle = alpha_BC - alpha_BA
      while (computedAngle < 0) computedAngle += 360
      while (computedAngle >= 360) computedAngle -= 360

      // Partial derivatives of θ = α_BC − α_BA w.r.t. E/N at each station
      // ∂α/∂E_from = dN/dist²   ∂α/∂N_from = −dE/dist²  (for BA direction)
      // ∂α/∂E_to   = −dN/dist²  ∂α/∂N_to   = dE/dist²   (for BC direction)
      // ∂α/∂E_at   = (dE_BC terms − dE_BA terms) / respective dist²
      const RAD = 180 / Math.PI
      const dist_BA2 = dist_BA * dist_BA
      const dist_BC2 = dist_BC * dist_BC

      // θ = α_BC − α_BA
      // ∂θ/∂E_at = ∂α_BC/∂E_at − ∂α_BA/∂E_at = (−dN_BC/dist_BC²) − (dN_BA/dist_BA²)
      dAngle_dE_at = ((-dN_BC / dist_BC2) - (dN_BA / dist_BA2)) * RAD
      dAngle_dN_at = ((dE_BC / dist_BC2) - (-dE_BA / dist_BA2)) * RAD  // fix signs
      dAngle_dN_at = ((dE_BC / dist_BC2) + (dE_BA / dist_BA2)) * RAD

      // ∂θ/∂E_from (backsight) = dN_BA / dist_BA² (from the BA bearing derivative)
      dAngle_dE_from = (dN_BA / dist_BA2) * RAD
      dAngle_dN_from = (-dE_BA / dist_BA2) * RAD

      // ∂θ/∂E_to (foresight) = −dN_BC / dist_BC²
      dAngle_dE_to = (-dN_BC / dist_BC2) * RAD
      dAngle_dN_to = (dE_BC / dist_BC2) * RAD

    } else {
      // ── Bearing-only (backward compatible) ──
      const dist = computeDistance(from.easting, from.northing, to.easting, to.northing)
      if (dist < 0.001) continue

      computedAngle = computeBearing(from.easting, from.northing, to.easting, to.northing)

      dAngle_dE_from = (to.northing - from.northing) / (dist * dist) * 180 / Math.PI
      dAngle_dN_from = -(to.easting - from.easting) / (dist * dist) * 180 / Math.PI
      dAngle_dE_to = -(to.northing - from.northing) / (dist * dist) * 180 / Math.PI
      dAngle_dN_to = (to.easting - from.easting) / (dist * dist) * 180 / Math.PI
    }

    // Fill coefficient matrix for adjustable stations
    if (!from.isFixed) {
      const idx = adjStationMap.get(from.id)
      if (idx != null) {
        row[idx * 2] = dAngle_dE_from
        row[idx * 2 + 1] = dAngle_dN_from
      }
    }
    if (!to.isFixed) {
      const idx = adjStationMap.get(to.id)
      if (idx != null) {
        row[idx * 2] = dAngle_dE_to
        row[idx * 2 + 1] = dAngle_dN_to
      }
    }
    // Vertex station (if provided and adjustable)
    if (angle.atStationId) {
      const at = stationMap.get(angle.atStationId)
      if (at && !at.isFixed) {
        const idx = adjStationMap.get(at.id)
        if (idx != null) {
          row[idx * 2] = dAngle_dE_at
          row[idx * 2 + 1] = dAngle_dN_at
        }
      }
    }

    A.push(row)
    L.push(angle.angle - computedAngle)  // misclosure
    P.push(1 / (angle.stdDev * angle.stdDev))  // weight = 1/σ²
  }

  // Distance observation equations
  for (const dist of distances) {
    const from = stationMap.get(dist.fromStationId)
    const to = stationMap.get(dist.toStationId)
    if (!from || !to) continue

    const row: Vector = Array(paramCount).fill(0)
    const computedDist = computeDistance(from.easting, from.northing, to.easting, to.northing)

    if (computedDist < 0.001) continue

    const dDist_dE_from = -(to.easting - from.easting) / computedDist
    const dDist_dN_from = -(to.northing - from.northing) / computedDist
    const dDist_dE_to = (to.easting - from.easting) / computedDist
    const dDist_dN_to = (to.northing - from.northing) / computedDist

    if (!from.isFixed) {
      const idx = adjStationMap.get(from.id)
      if (idx != null) {
        row[idx * 2] = dDist_dE_from
        row[idx * 2 + 1] = dDist_dN_from
      }
    }
    if (!to.isFixed) {
      const idx = adjStationMap.get(to.id)
      if (idx != null) {
        row[idx * 2] = dDist_dE_to
        row[idx * 2 + 1] = dDist_dN_to
      }
    }

    A.push(row)
    L.push(dist.distance - computedDist)
    P.push(1 / (dist.stdDev * dist.stdDev))
  }

  // Form normal equations: N = Aᵀ P A, t = Aᵀ P L
  const AtP = multiplyDiagonal(transpose(A), P)
  const N = multiply(AtP, A)
  const t = multiplyVector(AtP, L)

  // Solve for corrections: X = N⁻¹ · t
  const { solution: corrections, inverse: Ninv } = solveAndInvert(N, t)

  // Compute residuals: V = A·X - L
  const computedL = multiplyVector(A, corrections)
  const residuals: Residual[] = []
  let sumPVV = 0

  // AUDIT FIX (M7, 2026-07-02): Standardized residual computation.
  // Previously: v / √(1/P) = v·√P — this is the a priori standardized
  // residual, which does NOT account for the adjustment's effect on the
  // observation. The correct form is:
  //   w_i = v_i / √(q_vv_i · σ₀²)
  // where q_vv_i is the i-th diagonal of the residual cofactor matrix
  //   Q_vv = Q_ll - A · Q_xx · Aᵀ
  // and σ₀² is the a posteriori reference variance.
  // This requires computing A · Ninv · Aᵀ for each observation.

  // First pass: compute sumPVV and raw residuals
  for (let i = 0; i < L.length; i++) {
    const v = computedL[i] - L[i]
    sumPVV += P[i] * v * v
  }

  // Reference variance (a posteriori)
  const referenceVariance = sumPVV / degreesOfFreedom
  const standardError = Math.sqrt(referenceVariance)

  // Compute Q_vv diagonal: q_vv_i = 1/P_i - (A · Ninv · Aᵀ)_ii
  // For efficiency, compute (A · Ninv) once, then for each row i,
  // q_vv_i = 1/P_i - Σ_j (A·Ninv)[i][j] · A[i][j]
  const ANinv: number[][] = []
  for (let i = 0; i < A.length; i++) {
    const row: number[] = new Array(A[i].length).fill(0)
    for (let j = 0; j < A[i].length; j++) {
      let sum = 0
      for (let k = 0; k < A[i].length; k++) {
        sum += A[i][k] * (Ninv[k]?.[j] ?? 0)
      }
      row[j] = sum
    }
    ANinv.push(row)
  }

  for (let i = 0; i < L.length; i++) {
    const v = computedL[i] - L[i]

    // Compute q_vv_i = 1/P_i - A[i] · Ninv · A[i]ᵀ
    let qvv = 1 / P[i]
    for (let j = 0; j < A[i].length; j++) {
      qvv -= ANinv[i][j] * A[i][j]
    }

    // Standardized residual: w = v / √(q_vv · σ₀²)
    // Clamp q_vv to avoid division by zero (can happen for fully constrained obs)
    const qvvClamped = Math.max(qvv, 1e-15)
    const standardized = v / Math.sqrt(qvvClamped * referenceVariance)

    // AUDIT FIX (H13, 2026-07-02): Baarda reliability analysis.
    // Redundancy number: r_i = q_vv_i × P_i
    // Range [0, 1]. Low r_i means the observation is weakly controlled.
    const redundancy = qvvClamped * P[i]

    // Minimal Detectable Bias (MDB): the smallest blunder detectable
    // at significance level α and power β.
    //   ∇₀l = δ₀ × σ_l / √(r_i)
    // where δ₀ is the non-centrality parameter (4.13 for α=0.001, β=0.80),
    // σ_l = √(1/P_i) is the a priori standard deviation of the observation.
    const delta0 = 4.13  // Baarda's non-centrality parameter (α=0.001, β=0.80)
    const sigmaL = Math.sqrt(1 / P[i])  // a priori σ of the observation
    const mdb = delta0 * sigmaL / Math.sqrt(Math.max(redundancy, 1e-15))

    residuals.push({
      observationId: i < angles.length ? angles[i].id : distances[i - angles.length].id,
      type: i < angles.length ? 'angle' : 'distance',
      observed: L[i],
      computed: L[i] + v,
      residual: v,
      standardized,
      redundancy,
      mdb,
    })
  }

  // Chi-square test
  const chiSquareValue = sumPVV
  // Critical value at 5% significance (Wilson-Hilferty approximation — more
  // accurate than the old μ+2σ approximation)
  const chiSquareCritical = chiSquareQuantileWH(0.95, degreesOfFreedom)
  const passed = chiSquareValue <= chiSquareCritical

  // Build adjusted stations with error ellipses
  const adjustedStations: AdjustedStation[] = adjustableStations.map((station, i) => {
    const corrE = corrections[i * 2]
    const corrN = corrections[i * 2 + 1]

    // Cofactor matrix for this station
    const qEE = Ninv[i * 2][i * 2]
    const qNN = Ninv[i * 2 + 1][i * 2 + 1]
    const qEN = Ninv[i * 2][i * 2 + 1]

    const stdDevE = Math.sqrt(qEE * referenceVariance)
    const stdDevN = Math.sqrt(qNN * referenceVariance)

    // Error ellipse
    const qMax = (qEE + qNN) / 2 + Math.sqrt(((qEE - qNN) / 2) ** 2 + qEN ** 2)
    const qMin = (qEE + qNN) / 2 - Math.sqrt(((qEE - qNN) / 2) ** 2 + qEN ** 2)
    const semiMajor = Math.sqrt(qMax * referenceVariance * 2.448)  // 95% confidence
    const semiMinor = Math.sqrt(qMin * referenceVariance * 2.448)

    let orientation = Math.atan2(2 * qEN, qEE - qNN) / 2 * 180 / Math.PI
    if (orientation < 0) orientation += 180

    return {
      id: station.id,
      name: station.name,
      adjustedEasting: station.easting + corrE,
      adjustedNorthing: station.northing + corrN,
      correctionE: corrE,
      correctionN: corrN,
      stdDevE,
      stdDevN,
      errorEllipse: { semiMajor, semiMinor, orientation },
    }
  })

  // Generate report
  let report = `Least Squares Adjustment Report\n`
  report += `═══════════════════════════════\n`
  report += `Observations: ${obsCount} (${angles.length} angles, ${distances.length} distances)\n`
  report += `Parameters: ${paramCount} (${adjustableStations.length} stations × 2)\n`
  report += `Degrees of freedom: ${degreesOfFreedom}\n`
  report += `Reference variance (σ₀²): ${referenceVariance.toFixed(6)}\n`
  report += `Standard error (σ₀): ${standardError.toFixed(4)}\n`
  report += `Chi-square test: ${chiSquareValue.toFixed(2)} vs ${chiSquareCritical.toFixed(2)} → ${passed ? 'PASS' : 'FAIL'}\n`
  report += `\nAdjusted Stations:\n`
  for (const s of adjustedStations) {
    report += `  ${s.name}: E:${s.adjustedEasting.toFixed(4)} N:${s.adjustedNorthing.toFixed(4)}`
    report += ` (ΔE:${s.correctionE.toFixed(4)} ΔN:${s.correctionN.toFixed(4)})`
    report += ` σE:${s.stdDevE.toFixed(4)} σN:${s.stdDevN.toFixed(4)}\n`
  }

  return {
    adjustedStations,
    residuals,
    referenceVariance,
    degreesOfFreedom,
    standardError,
    passed,
    chiSquareValue,
    chiSquareCritical,
    report,
  }
}

/**
 * Chi-square quantile function using the Wilson-Hilferty approximation.
 *
 * AUDIT FIX (M7, 2026-07-02): Replaced the crude μ+2σ approximation
 * (dof + 2·√(2·dof)) with the Wilson-Hilferty transformation, which
 * is accurate to ~0.1% for dof ≥ 3.
 *
 * Reference: Wilson, E.B. & Hilferty, M.M. (1931)
 */
function invNormalCDF(p: number): number {
  // Inverse normal CDF (Acklam's algorithm — same as in leastSquares.ts)
  const a = [-3.969683028665376e+01, 2.209460984245205e+02,
             -2.759285104469687e+02, 1.383577518672690e+02,
             -3.066479806614716e+01, 2.506628277459239e+00]
  const b = [-5.447609879822406e+01, 1.615858368580409e+02,
             -1.556989798598866e+02, 6.680131188771972e+01,
             -1.328068155288572e+01]
  const c = [-7.784894002430293e-03, -3.223964580411365e-01,
             -2.400758277161838e+00, -2.549732539343734e+00,
              4.374664141464968e+00, 2.938163982698783e+00]
  const d = [7.784695709041462e-03, 3.224671290700398e-01,
             2.445134137142996e+00, 3.754408661907416e+00]
  const pLow = 0.02425
  const pHigh = 1 - pLow
  let q: number
  if (p < pLow) {
    q = Math.sqrt(-2 * Math.log(p))
    return (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) /
           ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)
  } else if (p <= pHigh) {
    q = p - 0.5
    const r = q * q
    return (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q /
           (((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1)
  } else {
    q = Math.sqrt(-2 * Math.log(1 - p))
    return -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5]) /
            ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1)
  }
}

// Wilson-Hilferty transformation: χ²_p ≈ dof · (z_p · √(2/(9·dof)) + 1 - 1/(9·dof))³
function chiSquareQuantileWH(p: number, dof: number): number {
  if (dof <= 0) return 0
  const z = invNormalCDF(p)
  const t = z * Math.sqrt(2 / (9 * dof)) + 1 - 1 / (9 * dof)
  return dof * t * t * t
}

/**
 * Level Network Adjustment Engine (Least Squares)
 * Phase A3 — Metardu Professional Engine
 *
 * Performs a 1D least squares adjustment of interconnected leveling loops.
 *
 * Observation Equation:
 * v = h_j - h_i - \Delta h_{ij}
 * where:
 *   h_i, h_j are the unknown elevations of stations i and j
 *   \Delta h_{ij} is the observed elevation difference from i to j
 *
 * Weighting:
 * w = 1 / L  (where L is distance in km) OR w = 1 / \sigma^2
 */

import { z } from 'zod'

export const LevelStationSchema = z.object({
  id: z.string().min(1, 'Station ID is required'),
  elevation: z.number().finite().default(0), // Approx if free, fixed if isFixed
  isFixed: z.boolean().default(false),
})

export type LevelStation = z.infer<typeof LevelStationSchema>

export const LevelObservationSchema = z.object({
  from: z.string().min(1, 'From station is required'),
  to: z.string().min(1, 'To station is required'),
  deltaH: z.number().finite(),
  distanceKm: z.number().positive().default(1),
})

export type LevelObservation = z.infer<typeof LevelObservationSchema>

export interface AdjustedLevelStation extends LevelStation {
  adjustedElevation: number
  residual: number
  stdDev: number
}

export interface LevelAdjustmentResult {
  adjustedStations: AdjustedLevelStation[]
  sigmaZero: number
  degreesOfFreedom: number
  passed: boolean
  warnings: string[]
  residuals: Array<{
    from: string
    to: string
    observedDelta: number
    adjustedDelta: number
    residual: number
    standardizedResidual: number
  }>
}

export function adjustLevelNetwork(
  stations: LevelStation[],
  observations: LevelObservation[]
): LevelAdjustmentResult {
  const stationValidation = LevelStationSchema.array().safeParse(stations)
  if (!stationValidation.success) {
    throw new Error('Invalid stations: ' + stationValidation.error.message)
  }
  const obsValidation = LevelObservationSchema.array().safeParse(observations)
  if (!obsValidation.success) {
    throw new Error('Invalid observations: ' + obsValidation.error.message)
  }

  const warnings: string[] = []

  const fixed = stations.filter(s => s.isFixed)
  if (fixed.length === 0) {
    throw new Error('At least one fixed benchmark is required.')
  }

  const free = stations.filter(s => !s.isFixed)
  const n = free.length
  const m = observations.length
  const dof = m - n

  if (dof < 0) {
    throw new Error(`Insufficient observations. Need at least ${n} runs for ${n} free stations.`)
  }

  const stationIndex = new Map<string, number>()
  free.forEach((s, i) => stationIndex.set(s.id, i))

  const elevations = new Map<string, number>()
  stations.forEach(s => elevations.set(s.id, s.elevation))

  // Estimate initial elevations if missing (using a simple spanning tree approach could be better, but we assume approximations or 0 are provided)
  // The system is linear, so initial approximations don't affect convergence, only the size of dx.

  const A: number[][] = []
  const W: number[] = []
  const l: number[] = []

  for (const obs of observations) {
    const fromH = elevations.get(obs.from) ?? 0
    const toH = elevations.get(obs.to) ?? 0
    
    // Weight inversely proportional to distance (km)
    // Variance is proportional to distance, so w = 1/var \propto 1/L
    const w = 1 / obs.distanceKm

    const row = new Array(n).fill(0)
    if (stationIndex.has(obs.to)) row[stationIndex.get(obs.to)!] = 1
    if (stationIndex.has(obs.from)) row[stationIndex.get(obs.from)!] = -1

    const obsH = toH - fromH
    A.push(row)
    W.push(w)
    l.push(obs.deltaH - obsH)
  }

  const N = multiplyAtWA(A, W, n)
  const t = multiplyAtWl(A, W, l, n)
  
  let x: number[]
  try {
    x = solveLinearSystem(N, t)
  } catch (err: unknown) {
    throw new Error('Failed to solve network equations: ' + (err as Error).message)
  }

  free.forEach((s, i) => {
    elevations.set(s.id, (elevations.get(s.id) ?? 0) + x[i])
  })

  const v: number[] = []
  for (let i = 0; i < m; i++) {
    let ax = 0
    for (let j = 0; j < n; j++) ax += A[i][j] * x[j]
    v.push(ax - l[i])
  }

  const vWv = v.reduce((sum, res, i) => sum + W[i] * res * res, 0)
  const sigmaZero = dof > 0 ? Math.sqrt(vWv / dof) : 0

  if (dof === 0) {
    warnings.push('Zero degrees of freedom — cannot compute reliable error estimates.')
  }

  const Qxx = invertMatrix(N, n)

  const residualsOut = observations.map((obs, i) => {
    const qll = 1 / W[i]
    let aTQa = 0
    const aRow = A[i]
    for (let row = 0; row < n; row++) {
      let sum = 0
      for (let col = 0; col < n; col++) {
        sum += Qxx[row][col] * aRow[col]
      }
      aTQa += aRow[row] * sum
    }
    const qvv = Math.max(0, qll - aTQa)
    const stdRes = qvv > 0 ? v[i] / (sigmaZero * Math.sqrt(qvv)) : 0

    return {
      from: obs.from,
      to: obs.to,
      observedDelta: obs.deltaH,
      adjustedDelta: obs.deltaH + v[i],
      residual: v[i],
      standardizedResidual: stdRes
    }
  })

  const passed = residualsOut.every(r => Math.abs(r.standardizedResidual) < 3.0)
  if (!passed) {
    warnings.push('One or more standardized residuals exceed 3.0. Check for blunders in leveling runs.')
  }

  const adjustedStations: AdjustedLevelStation[] = stations.map(s => {
    const adjH = elevations.get(s.id)!
    let stdDev = 0
    let res = 0

    if (!s.isFixed) {
      const idx = stationIndex.get(s.id)!
      res = x[idx]
      const qHH = Qxx[idx][idx]
      stdDev = sigmaZero * Math.sqrt(Math.max(qHH, 0))
    }

    return {
      ...s,
      adjustedElevation: adjH,
      residual: res,
      stdDev
    }
  })

  return {
    adjustedStations,
    sigmaZero,
    degreesOfFreedom: dof,
    passed,
    warnings,
    residuals: residualsOut
  }
}

// Re-using matrix functions
function multiplyAtWA(A: number[][], W: number[], n: number): number[][] {
  const result = Array.from({ length: n }, () => new Array(n).fill(0))
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++)
      for (let k = 0; k < A.length; k++)
        result[i][j] += A[k][i] * W[k] * A[k][j]
  return result
}

function multiplyAtWl(A: number[][], W: number[], l: number[], n: number): number[] {
  const result = new Array(n).fill(0)
  for (let i = 0; i < n; i++)
    for (let k = 0; k < A.length; k++)
      result[i] += A[k][i] * W[k] * l[k]
  return result
}

function solveLinearSystem(A: number[][], b: number[]): number[] {
  const n = b.length
  const M = A.map((row, i) => [...row, b[i]])
  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++)
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]
    if (Math.abs(M[col][col]) < 1e-12)
      throw new Error('Singular normal equation matrix — check network geometry.')
    for (let row = col + 1; row < n; row++) {
      const factor = M[row][col] / M[col][col]
      for (let k = col; k <= n; k++) M[row][k] -= factor * M[col][k]
    }
  }
  const x = new Array(n).fill(0)
  for (let i = n - 1; i >= 0; i--) {
    x[i] = M[i][n]
    for (let j = i + 1; j < n; j++) x[i] -= M[i][j] * x[j]
    x[i] /= M[i][i]
  }
  return x
}

function invertMatrix(A: number[][], n: number): number[][] {
  const M = A.map((row, i) => {
    const aug = [...row, ...new Array(n).fill(0)]
    aug[n + i] = 1
    return aug
  })
  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++)
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]
    const pivot = M[col][col]
    if (Math.abs(pivot) < 1e-12) return Array.from({ length: n }, () => new Array(n).fill(0))
    for (let k = 0; k < 2 * n; k++) M[col][k] /= pivot
    for (let row = 0; row < n; row++) {
      if (row === col) continue
      const factor = M[row][col]
      for (let k = 0; k < 2 * n; k++) M[row][k] -= factor * M[col][k]
    }
  }
  return M.map(row => row.slice(n))
}

/**
 * Country-aware leveling standards — closures, C-factor, two-peg test.
 *
 * Reference:
 *   USACE EM 1110-1-1005 Table 4-2 (leveling closure)
 *   USACE EM 1110-1-1005 §3-4 (C-factor tables)
 *   USACE EM 1110-1-1005 §3-6 (two-peg test — 30" threshold)
 *   Kenya Survey Reg 63 (direct/indirect leveling tolerances)
 *   Bahrain CSD (field round tolerances)
 */

import type { SurveyingCountry } from '@/lib/country/standards'
import { getCountryStandard } from '@/lib/country/standards'
import { twoPegTest } from './twoPegTest'

// ─── LEVELING CLOSURE ORDERS (USACE Table 4-2) ────────────────────────────────

export interface LevelingOrder {
  order: string
  closureFormula: string   // e.g. "0.013·√M ft" or "3·√K mm/km"
  closureMetres: number    // per km (mm√km expressed in metres)
  closureFeet: number      // per mile
  description: string
  regulation: string
}

export const LEVELING_ORDERS: LevelingOrder[] = [
  {
    order: 'first_order',
    closureFormula: '0.013·√M ft  |  3·√K mm/km',
    closureMetres: 0.003,  // 3mm/√km
    closureFeet: 0.017,    // 0.013ft/√mile
    description: 'First Order — benchmarks, reference frames',
    regulation: 'USACE EM 1110-1-1005 Table 4-2 / FGCC 1984',
  },
  {
    order: 'second_order_class_i',
    closureFormula: '0.017·√M ft  |  6·√K mm/km',
