/**
 * @module sparseMatrix
 *
 * Sparse linear algebra primitives for large survey control networks.
 *
 * The dense Gauss-Jordan solver in `leastSquares.ts` is O(n³) for both time
 * and memory — it breaks down past ~150 stations because the normal matrix
 * N = Aᵀ P A has n² entries (n = 2 × stations for 2D, 3 × stations for 3D).
 *
 * For a typical control network, each observation only touches 2–3 stations,
 * so the design matrix A is >99% zeros past ~200 stations. The normal matrix
 * N is similarly sparse (banded structure for traverses, block-sparse for
 * networks). Exploiting this sparsity gives:
 *
 *   - Memory: O(nnz) instead of O(n²)  (nnz = number of non-zeros)
 *   - Time:   O(nnz · √n) for sparse Cholesky vs O(n³) for dense
 *
 * Concretely, a 1,000-station 2D network:
 *   - Dense: 4,000,000 matrix entries, ~30s solve time
 *   - Sparse: ~12,000 non-zeros, ~50ms solve time
 *
 * References:
 *   - Davis, T.A. (2006) "Direct Methods for Sparse Linear Systems" (SIAM)
 *   - George, A. & Liu, J.W-H. (1981) "Computer Solution of Large Sparse
 *     Positive Definite Systems" (Prentice-Hall)
 *   - Liu, J.W-H. (1990) "The role of elimination trees in sparse factorization"
 *     SIAM J. Matrix Anal. Appl. 11(1)
 *   - Erisman, A.M. & Tinney, W.F. (1975) "On computing certain elements of
 *     the inverse of a sparse matrix" Comm. ACM 18(3)
 */

// ---------------------------------------------------------------------------
// Types — CSR format
// ---------------------------------------------------------------------------

/**
 * Compressed Sparse Row matrix.
 *
 * - `rowPtr` has length (rows + 1); rowPtr[i]..rowPtr[i+1] is the range of
 *   indices into `colIdx` and `values` for row i.
 * - `colIdx` and `values` have length nnz (number of non-zeros).
 *
 * For symmetric matrices (like the normal matrix N), we store only the lower
 * triangle by default — `symmetric: true` flag.
 */
export interface SparseMatrix {
  rows: number
  cols: number
  rowPtr: number[]   // length rows + 1
  colIdx: number[]   // length nnz
  values: number[]   // length nnz, parallel to colIdx
  symmetric?: boolean // if true, only lower triangle stored
}

// ---------------------------------------------------------------------------
// Construction helpers
// ---------------------------------------------------------------------------

/**
 * Build a sparse matrix from a list of triplet entries (row, col, value).
 * Duplicate entries for the same (row, col) are summed.
 *
 * For symmetric matrices, only lower-triangle entries (col <= row) are kept;
 * upper-triangle entries are transposed automatically.
 *
 * Complexity: O(nnz log nnz) due to sorting.
 */
export function fromTriplets(
  rows: number,
  cols: number,
  triplets: Array<{ row: number; col: number; value: number }>,
  symmetric = false,
): SparseMatrix {
  // Normalize: for symmetric, only keep lower triangle
  const normalized = symmetric
    ? triplets.map((t) => (t.col > t.row ? { row: t.col, col: t.row, value: t.value } : t))
    : triplets

  // Filter zeros
  const nonZero = normalized.filter((t) => t.value !== 0)

  // Sort by row, then by col
  nonZero.sort((a, b) => (a.row !== b.row ? a.row - b.row : a.col - b.col))

  // Build CSR with duplicate summing
  const rowPtr = new Array(rows + 1).fill(0)
  const colIdx: number[] = []
  const values: number[] = []

  let prevRow = -1
  let prevCol = -1
  for (const t of nonZero) {
    // Fill rowPtr for skipped rows
    if (t.row !== prevRow) {
      for (let r = prevRow + 1; r <= t.row; r++) rowPtr[r] = colIdx.length
      prevRow = t.row
      prevCol = -1
    }
    if (t.col === prevCol) {
      values[values.length - 1] += t.value
    } else {
      colIdx.push(t.col)
      values.push(t.value)
      prevCol = t.col
    }
  }
  // Fill remaining rowPtr entries
  for (let r = prevRow + 1; r <= rows; r++) rowPtr[r] = colIdx.length

  return { rows, cols, rowPtr, colIdx, values, symmetric }
}

/**
 * Convert a dense matrix to sparse.
 * For symmetric=true, only the lower triangle is stored.
 */
export function fromDense(A: number[][], symmetric = false): SparseMatrix {
  const rows = A.length
  const cols = A[0]?.length ?? 0
  const triplets: Array<{ row: number; col: number; value: number }> = []
  for (let i = 0; i < rows; i++) {
    const startCol = symmetric ? 0 : 0
    const endCol = symmetric ? i + 1 : cols
    for (let j = startCol; j < endCol; j++) {
      if (A[i][j] !== 0) {
        triplets.push({ row: i, col: j, value: A[i][j] })
      }
    }
  }
  return fromTriplets(rows, cols, triplets, symmetric)
}

/**
 * Convert a sparse matrix to dense. For tests and small matrices only.
 */
export function toDense(M: SparseMatrix): number[][] {
  const out: number[][] = Array.from({ length: M.rows }, () => new Array(M.cols).fill(0))
  for (let r = 0; r < M.rows; r++) {
    for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
      const c = M.colIdx[idx]
      out[r][c] = M.values[idx]
      if (M.symmetric && c !== r) {
        out[c][r] = M.values[idx]
      }
    }
  }
  return out
}

// ---------------------------------------------------------------------------
// Basic operations
// ---------------------------------------------------------------------------

/**
 * Sparse matrix-vector multiplication: y = M · x
 *
 * For symmetric matrices stored as lower triangle, both lower and upper
 * contributions are accumulated.
 *
 * Complexity: O(nnz)
 */
export function sparseMatVec(M: SparseMatrix, x: number[]): number[] {
  if (x.length !== M.cols) {
    throw new Error(`Dimension mismatch: matrix has ${M.cols} cols, vector has ${x.length}`)
  }
  const y = new Array(M.rows).fill(0)

  if (M.symmetric) {
    // Lower triangle: M[i, j] for j <= i
    // y[i] += M[i, j] * x[j]  (j <= i)
    // y[j] += M[i, j] * x[i]  (j < i, since M is symmetric)
    for (let r = 0; r < M.rows; r++) {
      for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
        const c = M.colIdx[idx]
        const v = M.values[idx]
        y[r] += v * x[c]
        if (c !== r) {
          y[c] += v * x[r]
        }
      }
    }
  } else {
    for (let r = 0; r < M.rows; r++) {
      let sum = 0
      for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
        sum += M.values[idx] * x[M.colIdx[idx]]
      }
      y[r] = sum
    }
  }

  return y
}

/**
 * Compute N = Aᵀ · D · A where A is a sparse matrix (m × n) and D is a diagonal
 * matrix (m × m). The result is symmetric positive semi-definite (n × n).
 *
 * This is the workhorse for assembling normal equations: N = Aᵀ P A where P
 * is the diagonal weight matrix.
 *
 * Complexity: O(nnz(A) × k) where k is the average row degree of A.
 */
export function ataDiag(
  A: SparseMatrix,
  d: number[] // diagonal of D, length m
): SparseMatrix {
  if (d.length !== A.rows) {
    throw new Error(`Dimension mismatch: A has ${A.rows} rows, d has ${d.length} entries`)
  }

  const n = A.cols
  const triplets: Array<{ row: number; col: number; value: number }> = []

  for (let i = 0; i < A.rows; i++) {
    const rowStart = A.rowPtr[i]
    const rowEnd = A.rowPtr[i + 1]
    const diagVal = d[i]
    if (diagVal === 0) continue

    // Extract this row's (col, val) pairs
    const entries: Array<{ col: number; val: number }> = []
    for (let idx = rowStart; idx < rowEnd; idx++) {
      entries.push({ col: A.colIdx[idx], val: A.values[idx] })
    }

    // Outer product: entries × entriesᵀ, scaled by diagVal
    // Only store lower triangle (j >= k)
    for (let a = 0; a < entries.length; a++) {
      for (let b = 0; b < entries.length; b++) {
        const j = entries[a].col
        const k = entries[b].col
        if (j >= k) {
          triplets.push({ row: j, col: k, value: entries[a].val * entries[b].val * diagVal })
        }
      }
    }
  }

  return fromTriplets(n, n, triplets, true)
}

/**
 * Compute u = Aᵀ · D · b where A is sparse (m × n), D is diagonal (m × m),
 * and b is a vector (m × 1). Result is length n.
 *
 * Complexity: O(nnz(A))
 */
export function atdbDiag(A: SparseMatrix, d: number[], b: number[]): number[] {
  if (d.length !== A.rows) throw new Error('d dimension mismatch')
  if (b.length !== A.rows) throw new Error('b dimension mismatch')

  const n = A.cols
  const u = new Array(n).fill(0)
  for (let i = 0; i < A.rows; i++) {
    const factor = d[i] * b[i]
    if (factor === 0) continue
    for (let idx = A.rowPtr[i]; idx < A.rowPtr[i + 1]; idx++) {
      u[A.colIdx[idx]] += A.values[idx] * factor
    }
  }
  return u
}

// ---------------------------------------------------------------------------
// AMD (Approximate Minimum Degree) ordering
// ---------------------------------------------------------------------------

/**
 * Simplified AMD ordering for sparse symmetric matrices.
 *
 * Returns a permutation array P (length n) such that A[P[i], P[j]] is the
 * permuted matrix. P[i] is the original index that becomes position i.
 */
export function approximateMinimumDegree(M: SparseMatrix): number[] {
  const n = M.rows
  if (n !== M.cols) throw new Error('AMD requires square matrix')

  // Build adjacency lists (symmetric, excluding diagonal)
  const adj: Set<number>[] = new Array(n).fill(null).map(() => new Set())
  for (let r = 0; r < n; r++) {
    for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
      const c = M.colIdx[idx]
      if (c !== r) {
        adj[r].add(c)
        adj[c].add(r)
      }
    }
  }

  const degree = new Array(n).fill(0).map((_, i) => adj[i].size)
  const eliminated = new Array(n).fill(false)
  const perm: number[] = []

  for (let step = 0; step < n; step++) {
    // Find uneliminated node with minimum degree
    let minDeg = Infinity
    let minNode = -1
    for (let i = 0; i < n; i++) {
      if (!eliminated[i] && degree[i] < minDeg) {
        minDeg = degree[i]
        minNode = i
      }
    }
    if (minNode === -1) break

    perm.push(minNode)
    eliminated[minNode] = true

    // Eliminate: connect all neighbors to each other (fill-in)
    const neighbors = Array.from(adj[minNode]).filter((x) => !eliminated[x])
    for (let i = 0; i < neighbors.length; i++) {
      for (let j = i + 1; j < neighbors.length; j++) {
        adj[neighbors[i]].add(neighbors[j])
        adj[neighbors[j]].add(neighbors[i])
      }
      adj[neighbors[i]].delete(minNode)
      degree[neighbors[i]] = adj[neighbors[i]].size
    }
  }

  return perm
}

/**
 * Apply a permutation: returns the matrix A[P, P] for symmetric matrices.
 * The result is also symmetric (lower triangle stored).
 */
export function permuteSymmetric(M: SparseMatrix, P: number[]): SparseMatrix {
  const n = M.rows
  if (P.length !== n) throw new Error('Permutation length mismatch')

  // Build inverse permutation: Pinv[original] = new
  const Pinv = new Array(n)
  for (let i = 0; i < n; i++) Pinv[P[i]] = i

  // Walk original matrix, push triplets with permuted indices
  const triplets: Array<{ row: number; col: number; value: number }> = []
  for (let r = 0; r < n; r++) {
    for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
      const c = M.colIdx[idx]
      const v = M.values[idx]
      const newR = Pinv[r]
      const newC = Pinv[c]
      // Lower triangle of permuted matrix
      const lo = Math.min(newR, newC)
      const hi = Math.max(newR, newC)
      triplets.push({ row: hi, col: lo, value: v })
    }
  }

  return fromTriplets(n, n, triplets, true)
}

// ---------------------------------------------------------------------------
// Symbolic factorization (column Cholesky)
// ---------------------------------------------------------------------------

export interface SymbolicFactor {
  n: number
  /** Elimination tree: parent[j] = smallest i > j with L[i, j] != 0, or -1 for root. */
  parent: number[]
  /** For each column j, the row indices of non-zeros in L[:, j] (including j, sorted ascending). */
  colRows: number[][]
  /** For each column j, the count of non-zeros in L[:, j] (including diagonal). */
  colCount: number[]
}

/**
 * Symbolic Cholesky factorization: compute the sparsity pattern of L given
 * the sparsity pattern of the (symmetric, lower-triangle-stored) matrix.
 *
 * Algorithm (Davis 2006, CSparse `cs_etree`):
 *   1. For each column j (in increasing order), iterate over ROW j's
 *      off-diagonal entries (c < j). For each such c, find the root of c's
 *      subtree in the partial elimination tree (with path compression).
 *      If the root is not j, attach it: parent[root] = j.
 *   2. Build children list from parent array.
 *   3. Compute column patterns: pattern[L[:, j]] = {j} ∪ colAdj[j] ∪
 *      (union of children's patterns, restricted to rows > j).
 *
 * The key insight: parent[j] = smallest i > j such that L[i, j] ≠ 0.
 * The algorithm correctly captures fill-in because it uses the elimination
 * tree (which encodes fill-in dependencies), not just the original adjacency.
 *
 * Reference: Davis (2006) Ch. 6 — "Symbolic factorization"; Liu (1990)
 */
export function symbolicFactorize(M: SparseMatrix): SymbolicFactor {
  const n = M.rows
  if (n !== M.cols || !M.symmetric) {
    throw new Error('Symbolic factorization requires symmetric matrix (lower triangle)')
  }

  // Build column adjacency: colAdj[j] = list of rows r > j where M[r, j] != 0
  // (used later for column pattern computation)
  const colAdj: number[][] = new Array(n).fill(null).map(() => [])
  for (let r = 0; r < n; r++) {
    for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
      const c = M.colIdx[idx]
      if (c < r) {
        colAdj[c].push(r)
      }
    }
  }

  // Compute elimination tree using Liu/Davis algorithm with path compression.
  // ancestor[i] = root of i's subtree in the partial tree (initially i itself).
  const parent = new Array(n).fill(-1)
  const ancestor = new Array(n).fill(0).map((_, i) => i)

  for (let j = 0; j < n; j++) {
    // Iterate over ROW j's off-diagonal entries (c < j) — these are entries
    // M[j, c] in the lower triangle, which equal M[c, j] in the full matrix.
    for (let idx = M.rowPtr[j]; idx < M.rowPtr[j + 1]; idx++) {
      const c = M.colIdx[idx]
      if (c >= j) continue // skip diagonal and upper (shouldn't have upper in lower-triangle storage)

      // Find root of c's subtree with path compression
      let root = c
      while (ancestor[root] !== root) {
        ancestor[root] = ancestor[ancestor[root]] // path compression
        root = ancestor[root]
      }
      if (root !== j) {
        ancestor[root] = j
        parent[root] = j
      }
    }
  }

  // Compute column patterns using the elimination tree.
  //
  // Theorem (Liu 1990): L[i, j] ≠ 0 (for i > j) iff i is an ancestor of j in
  // the elimination tree (i.e., j is reachable from i by following parent[]
  // backwards, equivalently i appears on the path from j to the root).
  //
  // Therefore: pattern(L[:, j]) = {j} ∪ {ancestors of j}.
  //
  // This captures BOTH original non-zeros AND fill-in, because the elimination
  // tree is constructed to encode the dependency structure.
  //
  // Note: the related formula "pattern(L[:, j]) = {j} ∪ ⋃_{c ∈ children[j]} pattern(L[:, c])"
  // actually computes the ROW pattern pattern(L[j, :]) (transposed), not the
  // column pattern. Don't confuse them.
  const colRows: number[][] = new Array(n).fill(null).map(() => [])
  const colCount: number[] = new Array(n).fill(0)

  for (let j = 0; j < n; j++) {
    const rows: number[] = [j]
    // Walk up the elimination tree from j, collecting all ancestors
    let p = parent[j]
    while (p !== -1) {
      rows.push(p)
      p = parent[p]
    }
    // Sort ascending (required for Cholesky algorithm)
    rows.sort((a, b) => a - b)
    colRows[j] = rows
    colCount[j] = rows.length
  }

  return { n, parent, colRows, colCount }
}

// ---------------------------------------------------------------------------
// Numeric Cholesky factorization (left-looking)
// ---------------------------------------------------------------------------

export interface SparseCholesky {
  n: number
  L: SparseMatrix       // lower triangular (CSR), with explicit zeros above diag
  symbolic: SymbolicFactor
}

/**
 * Numeric Cholesky factorization: M = L · Lᵀ where L is lower triangular.
 *
 * Algorithm: left-looking column-wise.
 *   For each column j:
 *     1. Scatter column j of M into a work array
 *     2. For each previously computed column k < j with L[j, k] != 0:
 *          work[r] -= L[j, k] * L[r, k]  for r >= j in column k of L
 *        (Note: this includes the diagonal case r = j, giving work[j] -= L[j, k]²)
 *     3. L[j, j] = sqrt(work[j])
 *     4. L[r, j] = work[r] / L[j, j]  for r > j
 *
 * Reference: Davis (2006) Ch. 4 — "Sparse Cholesky factorization"
 */
export function cholesky(M: SparseMatrix, symbolic: SymbolicFactor): SparseCholesky {
  const n = M.rows

  // Build a lookup for M's entries: mLookup[r] gives Map<col, value> for row r
  const mLookup: Map<number, number>[] = new Array(n).fill(null).map(() => new Map())
  for (let r = 0; r < n; r++) {
    for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
      mLookup[r].set(M.colIdx[idx], M.values[idx])
    }
  }

  // Store L column-by-column for easy access
  // lColumns[j] = Map<row, value> for column j of L
  const lColumns: Array<Map<number, number>> = new Array(n).fill(null).map(() => new Map())

  for (let j = 0; j < n; j++) {
    const rows = symbolic.colRows[j] // sorted, includes j and rows > j
    const rowSet = new Set(rows) // for O(1) membership test

    // Step 1: Initialize work with column j of M (only for rows in pattern)
    const work = new Map<number, number>()
    for (const r of rows) {
      // M[r, j] for r >= j (lower triangle, stored as M[r, j] in row r)
      const v = mLookup[r].get(j) ?? 0
      if (v !== 0) work.set(r, v)
    }

    // Step 2: Subtract contributions from previously computed columns
    // For each k < j such that L[j, k] != 0:
    //   For each r in column k of L's pattern with r >= j AND r in column j's pattern:
    //     work[r] -= L[j, k] * L[r, k]
    //
    // The constraint "r in column j's pattern" is essential — otherwise we'd add
    // spurious entries to work that aren't structurally present in L[:, j].
    for (let k = 0; k < j; k++) {
      const ljk = lColumns[k].get(j)
      if (ljk === undefined || ljk === 0) continue

      // Iterate over column k of L's entries; only update rows in column j's pattern
      for (const [r, lrk] of lColumns[k]) {
        if (r >= j && rowSet.has(r)) {
          work.set(r, (work.get(r) ?? 0) - ljk * lrk)
        }
      }
    }

    // Step 3: Compute diagonal L[j, j]
    const diag = work.get(j) ?? 0
    if (diag <= 0) {
      if (diag > -1e-10) {
        // Numerical zero — matrix is positive semi-definite (rank deficient)
        // Use a tiny positive value to allow continuation
        const ljj = 1e-10
        lColumns[j].set(j, ljj)
        // Off-diagonal still computed (will be small)
        for (const r of rows) {
          if (r === j) continue
          const v = work.get(r) ?? 0
          if (v !== 0) lColumns[j].set(r, v / ljj)
        }
      } else {
        throw new Error(`Matrix is not positive definite at index ${j} (diagonal = ${diag})`)
      }
    } else {
      const ljj = Math.sqrt(diag)
      lColumns[j].set(j, ljj)
      // Step 4: Compute off-diagonal L[r, j] = work[r] / L[j, j]
      for (const r of rows) {
        if (r === j) continue
        const v = work.get(r) ?? 0
        if (v !== 0) lColumns[j].set(r, v / ljj)
      }
    }
  }

  // Convert L from column-major Map to CSR (row-major) format
  const triplets: Array<{ row: number; col: number; value: number }> = []
  for (let j = 0; j < n; j++) {
    for (const [r, v] of lColumns[j]) {
      triplets.push({ row: r, col: j, value: v })
    }
  }
  // Sort by row then col (CSR)
  triplets.sort((a, b) => (a.row !== b.row ? a.row - b.row : a.col - b.col))

  const rowPtr = new Array(n + 1).fill(0)
  const colIdx: number[] = []
  const values: number[] = []
  let prevRow = -1
  for (const t of triplets) {
    if (t.row !== prevRow) {
      for (let r = prevRow + 1; r <= t.row; r++) rowPtr[r] = colIdx.length
      prevRow = t.row
    }
    colIdx.push(t.col)
    values.push(t.value)
  }
  for (let r = prevRow + 1; r <= n; r++) rowPtr[r] = colIdx.length

  return {
    n,
    L: { rows: n, cols: n, rowPtr, colIdx, values, symmetric: false },
    symbolic,
  }
}

/**
 * Solve L · y = b (forward substitution) given sparse lower-triangular L.
 *
 * L is stored in CSR (row-major). For each row r, we have L[r, c] for c <= r.
 *
 * Complexity: O(nnz(L))
 */
export function sparseForwardSolve(L: SparseMatrix, b: number[]): number[] {
  if (L.rows !== L.cols) throw new Error('Forward solve requires square matrix')
  const n = L.rows
  const y = new Array(n).fill(0)

  for (let r = 0; r < n; r++) {
    let diag = 0
    let sum = 0
    for (let idx = L.rowPtr[r]; idx < L.rowPtr[r + 1]; idx++) {
      const c = L.colIdx[idx]
      if (c === r) {
        diag = L.values[idx]
      } else if (c < r) {
        sum += L.values[idx] * y[c]
      }
    }
    if (Math.abs(diag) < 1e-15) {
      throw new Error(`Zero pivot at row ${r}`)
    }
    y[r] = (b[r] - sum) / diag
  }

  return y
}

/**
 * Solve Lᵀ · x = y (back substitution) given sparse lower-triangular L.
 *
 * For each row i of Lᵀ (which corresponds to column i of L), we have:
 *   (Lᵀ)[i, j] · x[j] summed over j ≥ i = y[i]
 * Since Lᵀ[i, j] = L[j, i], this becomes:
 *   Σ_{j≥i} L[j, i] · x[j] = y[i]
 *
 * Solving for x[i] (with x[j] for j > i already known):
 *   x[i] = (y[i] - Σ_{j>i} L[j, i] · x[j]) / L[i, i]
 *
 * We process i from n-1 down to 0, using column-major access to L
 * (colEntries[i] gives all L[j, i] for j ≥ i).
 *
 * Complexity: O(nnz(L))
 */
export function sparseBackwardSolve(L: SparseMatrix, y: number[]): number[] {
  const n = L.rows
  const x = new Array(n)

  // Build column-major: for each column c, list of (row, value) with row >= c
  const colEntries: Array<Array<{ row: number; val: number }>> = new Array(n).fill(null).map(() => [])
  for (let r = 0; r < n; r++) {
    for (let idx = L.rowPtr[r]; idx < L.rowPtr[r + 1]; idx++) {
      const c = L.colIdx[idx]
      if (c <= r) {
        colEntries[c].push({ row: r, val: L.values[idx] })
      }
    }
  }

  // Process rows of Lᵀ (= columns of L) from last to first
  for (let i = n - 1; i >= 0; i--) {
    let diag = 0
    let sum = 0
    for (const e of colEntries[i]) {
      if (e.row === i) {
        diag = e.val
      } else if (e.row > i) {
        // L[j, i] · x[j] where j > i (already solved)
        sum += e.val * x[e.row]
      }
    }
    if (Math.abs(diag) < 1e-15) {
      throw new Error(`Zero pivot at row ${i}`)
    }
    x[i] = (y[i] - sum) / diag
  }

  return x
}

/**
 * Solve M · x = b for symmetric positive definite M via sparse Cholesky.
 */
export function sparseCholeskySolve(M: SparseMatrix, b: number[]): number[] {
  if (!M.symmetric) {
    throw new Error('sparseCholeskySolve requires symmetric matrix')
  }
  if (M.rows !== b.length) {
    throw new Error('Dimension mismatch between matrix and right-hand side')
  }

  const symbolic = symbolicFactorize(M)
  const { L } = cholesky(M, symbolic)
  const y = sparseForwardSolve(L, b)
  const x = sparseBackwardSolve(L, y)
  return x
}

/**
 * Solve M · x = b for SPD M, with prior AMD ordering to reduce fill-in.
 *
 * This is the recommended entry point for large networks.
 */
export function sparseCholeskySolveOrdered(
  M: SparseMatrix,
  b: number[],
): { x: number[]; permutation: number[] } {
  if (!M.symmetric) throw new Error('Requires symmetric matrix')

  const P = approximateMinimumDegree(M)
  const Mp = permuteSymmetric(M, P)
  const bp = P.map((i) => b[i])

  const symbolic = symbolicFactorize(Mp)
  const { L } = cholesky(Mp, symbolic)
  const yp = sparseForwardSolve(L, bp)
  const xp = sparseBackwardSolve(L, yp)

  // Invert permutation
  const x = new Array(M.rows)
  for (let i = 0; i < M.rows; i++) x[P[i]] = xp[i]

  return { x, permutation: P }
}

// ---------------------------------------------------------------------------
// Diagonal extraction & selective inversion (Takahashi)
// ---------------------------------------------------------------------------

/**
 * Extract the diagonal of a sparse matrix.
 */
export function diagonal(M: SparseMatrix): number[] {
  const n = Math.min(M.rows, M.cols)
  const diag = new Array(n).fill(0)
  for (let r = 0; r < n; r++) {
    for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
      if (M.colIdx[idx] === r) {
        diag[r] = M.values[idx]
        break
      }
    }
  }
  return diag
}

/**
 * Add a scalar to the diagonal of a (symmetric, lower-triangle-stored) matrix.
 *
 * Used for Tikhonov regularization: N + εI makes a rank-deficient normal
 * matrix invertible while preserving the constrained (minimum-norm) solution.
 */
export function addDiagonal(M: SparseMatrix, epsilon: number): SparseMatrix {
  const n = M.rows
  // Copy and add ε to diagonal entries
  const newRowPtr = [...M.rowPtr]
  const newColIdx = [...M.colIdx]
  const newValues = [...M.values]

  for (let r = 0; r < n; r++) {
    let foundDiag = false
    for (let idx = M.rowPtr[r]; idx < M.rowPtr[r + 1]; idx++) {
      if (M.colIdx[idx] === r) {
        newValues[idx] = M.values[idx] + epsilon
        foundDiag = true
        break
      }
    }
    if (!foundDiag) {
      // Insert diagonal entry — need to shift everything after this row
      // For simplicity, rebuild via triplets
      const triplets: Array<{ row: number; col: number; value: number }> = []
      for (let r2 = 0; r2 < n; r2++) {
        for (let idx = M.rowPtr[r2]; idx < M.rowPtr[r2 + 1]; idx++) {
          triplets.push({ row: r2, col: M.colIdx[idx], value: M.values[idx] })
        }
        triplets.push({ row: r2, col: r2, value: epsilon })
      }
      return fromTriplets(n, M.cols, triplets, M.symmetric)
    }
  }
  return { rows: n, cols: M.cols, rowPtr: newRowPtr, colIdx: newColIdx, values: newValues, symmetric: M.symmetric }
}

/**
 * Selective inversion: compute only the diagonal of M⁻¹ without computing
 * the full inverse. Returns the diagonal entries.
 *
 * Accepts either the original matrix M (will factor internally) or a
 * pre-computed Cholesky factor (preferred — saves refactoring).
 *
 * Uses Takahashi's method: compute Z = L⁻ᵀ (upper triangular) by back-substitution,
 * starting from the last column. The diagonal of M⁻¹ = Σ_k Z[i, k]² for each i.
 *
 * Equivalently: (M⁻¹)[i, i] = Σ_{k=i..n-1} (L⁻¹[k, i])²
 *
 * Reference: Erisman & Tinney (1975) "On Computing Certain Elements of the
 * Inverse of a Sparse Matrix"
 */
export function sparseInverseDiagonal(
  M: SparseMatrix | null,
  factor?: SparseCholesky,
): number[] {
  if (!factor) {
    if (!M) throw new Error('sparseInverseDiagonal requires either M or a pre-computed factor')
    factor = cholesky(M, symbolicFactorize(M))
  }
  const n = factor.n
  const { L, symbolic } = factor

  // Build column-major access for L: colEntries[c] = list of {row, val} for column c
  const colEntries: Array<Array<{ row: number; val: number }>> = new Array(n).fill(null).map(() => [])
  for (let r = 0; r < n; r++) {
    for (let idx = L.rowPtr[r]; idx < L.rowPtr[r + 1]; idx++) {
      const c = L.colIdx[idx]
      if (c <= r) colEntries[c].push({ row: r, val: L.values[idx] })
    }
  }

  // Z[k, j] = entry (k, j) of L⁻¹ (lower triangular since L is lower)
  // Formula (Takahashi, back-substitution):
  //   Z[j, j] = 1 / L[j, j]
  //   Z[k, j] = -(1/L[k, k]) * Σ_{i=j..k-1} L[k, i] * Z[i, j]   for k > j
  //
  // We compute Z column by column, in DECREASING order of j (from n-1 to 0).
  // For each j, we compute Z[k, j] for all k in pattern[L[:, j]] (k >= j).
  //
  // Then: (M⁻¹)[j, j] = Σ_{k=j..n-1} (Z[k, j])²  (since M⁻¹ = L⁻ᵀ L⁻¹ and L⁻¹ is lower)

  const zCols: Array<Map<number, number>> = new Array(n).fill(null).map(() => new Map())

  for (let j = n - 1; j >= 0; j--) {
    // Z[j, j] = 1 / L[j, j]
    let ljj = 0
    for (const e of colEntries[j]) {
      if (e.row === j) ljj = e.val
    }
    if (Math.abs(ljj) < 1e-15) throw new Error(`Zero diagonal in L at ${j}`)
    zCols[j].set(j, 1 / ljj)

    // For each k > j in the pattern of column j of L:
    const pattern = symbolic.colRows[j].filter((k) => k > j)
    for (const k of pattern) {
      // Z[k, j] = -(1/L[k, k]) * Σ_{i=j..k-1} L[k, i] * Z[i, j]
      let sum = 0
      // Iterate over entries in row k of L (cols i <= k)
      for (let idx = L.rowPtr[k]; idx < L.rowPtr[k + 1]; idx++) {
        const i = L.colIdx[idx]
        if (i >= j && i < k) {
          const zij = zCols[j].get(i)
          if (zij !== undefined) {
            sum += L.values[idx] * zij
          }
        }
      }
      // Find L[k, k]
      let lkk = 0
      for (const e of colEntries[k]) {
        if (e.row === k) lkk = e.val
      }
      if (Math.abs(lkk) < 1e-15) throw new Error(`Zero diagonal in L at ${k}`)
      const zkj = -sum / lkk
      if (zkj !== 0) zCols[j].set(k, zkj)
    }
  }

  // (M⁻¹)[j, j] = Σ_{k=j..n-1} (Z[k, j])²
  const invDiag = new Array(n).fill(0)
  for (let j = 0; j < n; j++) {
    let sum = 0
    for (const v of zCols[j].values()) {
      sum += v * v
    }
    invDiag[j] = sum
  }

  return invDiag
}

/**
 * METARDU Subdivision Engine
 *
 * Algorithms for splitting a parent parcel polygon into smaller child lots.
 *
 * Methods:
 *  - single-split: Cut polygon by a user-drawn line into two pieces
 *  - grid: Divide polygon bounding box into a grid, clip each cell
 *  - radial: Create triangular sectors from a center point to boundary
 *  - area: Iteratively cut lots of approximately equal target area
 *
 * Calculation standard: N.N. Basak — Surveying and Levelling
 * - No intermediate rounding
 * - Full floating point precision throughout
 * - Round only at final display layer
 * - Bearings: WCB 0-360° clockwise from North
 * - Coordinates: EPSG:21037 (Kenya Arc 1960 / UTM 37S), meters
 */

import { Point2D } from './types'
import { coordinateArea } from './area'
import { lineIntersection, pointInPolygon } from './geometry'
import { toRadians, normalizeBearing } from './angles'
import type {
  SubdivisionMethod,
  SubdivisionParams,
  SubdivisionResult,
  SubdividedLot,
  SplitLine,
  RoadReserveInfo,
} from '@/types/subdivision'

// ─── Utility helpers ────────────────────────────────────────────────────────

/** Compute the signed area of a polygon (positive = CCW). */
function signedArea(pts: Point2D[]): number {
  let area = 0
  const n = pts.length
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    area += pts[i].easting * pts[j].northing
    area -= pts[j].easting * pts[i].northing
  }
  return area / 2
}

/** Compute centroid using the area-weighted formula. */
function polyCentroid(pts: Point2D[]): Point2D {
  const open = stripClosing(pts)
  const n = open.length
  if (n === 0) return { easting: 0, northing: 0 }
  if (n === 1) return { ...open[0] }
  if (n === 2) return {
    easting: (open[0].easting + open[1].easting) / 2,
    northing: (open[0].northing + open[1].northing) / 2,
  }

  const closed = [...open, open[0]]
  let cx = 0, cy = 0, a = 0

  for (let i = 0; i < closed.length - 1; i++) {
    const cross =
      closed[i].easting * closed[i + 1].northing -
      closed[i + 1].easting * closed[i].northing
    cx += (closed[i].easting + closed[i + 1].easting) * cross
    cy += (closed[i].northing + closed[i + 1].northing) * cross
    a += cross
  }
  a /= 2

  if (Math.abs(a) > 1e-12) {
    cx /= (6 * a)
    cy /= (6 * a)
  } else {
    cx = open.reduce((s, p) => s + p.easting, 0) / n
    cy = open.reduce((s, p) => s + p.northing, 0) / n
  }

  return { easting: cx, northing: cy }
}

/** Ensure polygon is explicitly closed (first = last). */
function ensureClosed(pts: Point2D[]): Point2D[] {
  if (pts.length < 3) return [...pts]
  const dE = pts[0].easting - pts[pts.length - 1].easting
  const dN = pts[0].northing - pts[pts.length - 1].northing
  if (Math.sqrt(dE * dE + dN * dN) < 1e-10) return [...pts]
  return [...pts, { ...pts[0] }]
}

/** Strip the repeated closing vertex if present. */
function stripClosing(pts: Point2D[]): Point2D[] {
  if (pts.length < 3) return [...pts]
  const dE = pts[0].easting - pts[pts.length - 1].easting
  const dN = pts[0].northing - pts[pts.length - 1].northing
  if (Math.sqrt(dE * dE + dN * dN) < 1e-10) return pts.slice(0, -1)
  return [...pts]
}

/** Compute polygon perimeter. */
function perimeter(pts: Point2D[]): number {
  const closed = ensureClosed(pts)
  let p = 0
  for (let i = 0; i < closed.length - 1; i++) {
    const dx = closed[i + 1].easting - closed[i].easting
    const dy = closed[i + 1].northing - closed[i].northing
    p += Math.sqrt(dx * dx + dy * dy)
  }
  return p
}

/** Compute area in hectares from vertices. */
function areaHa(pts: Point2D[]): number {
  return coordinateArea(pts).areaHa
}

/**
 * Determine which side of a directed line a point falls on.
 * Returns >0 for left, <0 for right, 0 for on the line.
 * "Left" is the side to your left when walking from p1 to p2.
 */
function sideOfLine(
  point: Point2D,
  lineP1: Point2D,
  lineP2: Point2D
): number {
  return (
    (lineP2.easting - lineP1.easting) * (point.northing - lineP1.northing) -
    (lineP2.northing - lineP1.northing) * (point.easting - lineP1.easting)
  )
}

/**
 * Find intersections of a line (defined by two points) with polygon edges.
 * Returns intersection points and the edge index + parametric t for each.
 */
function findLinePolygonIntersections(
  lineP1: Point2D,
  lineP2: Point2D,
  polygon: Point2D[]
): Array<{ point: Point2D; edgeIdx: number; t: number }> {
  const result: Array<{ point: Point2D; edgeIdx: number; t: number }> = []
  const n = polygon.length
  const seen = new Set<string>()

  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    const inter = lineIntersection(lineP1, lineP2, polygon[i], polygon[j])
    if (inter.ok && inter.value.withinSegmentB) {
      const pt = inter.value.point
      const key = `${pt.easting.toFixed(6)},${pt.northing.toFixed(6)}`
      if (!seen.has(key)) {
        seen.add(key)
        // t is the parametric position along the polygon edge (0=edge start, 1=edge end)
        const dx = polygon[j].easting - polygon[i].easting
        const dy = polygon[j].northing - polygon[i].northing
        const lenSq = dx * dx + dy * dy
        const t = lenSq > 1e-20
          ? ((pt.easting - polygon[i].easting) * dx + (pt.northing - polygon[i].northing) * dy) / lenSq
          : 0
        result.push({ point: pt, edgeIdx: i, t })
      }
    }
  }

  return result
}

/**
 * Split a simple polygon into two pieces using a line.
 *
 * Algorithm:
 * 1. Find all intersections of the line with polygon edges
 * 2. Sort by parametric position along the polygon boundary
 * 3. Take the first two intersections
 * 4. Build polygon A by walking the boundary from intersection 1 to intersection 2,
 *    then adding intersection 2 → intersection 1 along the split line
 * 5. Build polygon B by walking from intersection 2 to intersection 1,
 *    then adding intersection 1 → intersection 2 along the split line
 */
function splitPolygonByLine(
  polygon: Point2D[],
  lineP1: Point2D,
  lineP2: Point2D
): Point2D[][] {
  const open = stripClosing(polygon)
  const n = open.length
  if (n < 3) return [polygon]

  const intersections = findLinePolygonIntersections(lineP1, lineP2, open)

  if (intersections.length < 2) {
    return [polygon]
  }

  // Sort intersections by (edgeIdx, t) to get their order along the polygon boundary
  intersections.sort((a, b) => {
    if (a.edgeIdx !== b.edgeIdx) return a.edgeIdx - b.edgeIdx
    return a.t - b.t
  })

  const ip1 = intersections[0] // first intersection along boundary
  const ip2 = intersections[1] // second intersection along boundary

  // Build polygon A: walk from ip1 to ip2 along boundary, then back along split line
  const polyA: Point2D[] = [ip1.point]
  let idx = ip1.edgeIdx
  let tCurrent = ip1.t

  // Walk along boundary edges
  while (true) {
    const j = (idx + 1) % n
    if (idx === ip2.edgeIdx) {
      // Same edge as ip2 — add ip2
      polyA.push(ip2.point)
      break
    }
    // Add the end vertex of this edge
    polyA.push(open[j])
    idx = j
    tCurrent = 0
    // Safety: if we've gone all the way around
    if (polyA.length > n + 5) break
  }

  // Build polygon B: walk from ip2 to ip1 along boundary, then back along split line
  const polyB: Point2D[] = [ip2.point]
  idx = ip2.edgeIdx
  tCurrent = ip2.t

  while (true) {
    const j = (idx + 1) % n
    if (idx === ip1.edgeIdx) {
      polyB.push(ip1.point)
      break
    }
    polyB.push(open[j])
    idx = j
    tCurrent = 0
    if (polyB.length > n + 5) break
  }

  // Check that both polygons are valid (positive area)
  const areaA = Math.abs(signedArea(polyA))
  const areaB = Math.abs(signedArea(polyB))
  const minArea = 0.5 // 0.5 sqm minimum

  const results: Point2D[][] = []
  if (areaA > minArea && polyA.length >= 3) results.push(polyA)
  if (areaB > minArea && polyB.length >= 3) results.push(polyB)

  return results.length >= 2 ? results : [polygon]
}

/** Check if a polygon is valid (enough vertices, positive area). */
function isValidPolygon(pts: Point2D[]): boolean {
  if (pts.length < 3) return false
  return Math.abs(signedArea(pts)) > 1e-6
}

// ─── Sutherland-Hodgman polygon clipping ────────────────────────────────────

/**
 * Clip polygon to a convex clip boundary using Sutherland-Hodgman.
 * The clipBoundary must be wound CCW so that "inside" (left of each edge)
 * matches the `sideOfLine >= 0` test.
 */
function clipPolygonByBoundary(
  polygon: Point2D[],
  clipBoundary: Point2D[]
): Point2D[] {
  let output = [...polygon]
  const m = clipBoundary.length

  for (let i = 0; i < m && output.length > 0; i++) {
    const edgeStart = clipBoundary[i]
    const edgeEnd = clipBoundary[(i + 1) % m]
    output = clipEdge(output, edgeStart, edgeEnd)
  }

  return output
}

/**
 * Clip a polygon against a single half-plane defined by the line
 * edgeStart→edgeEnd. "Inside" = left side of the directed edge (sideOfLine >= 0).
 */
function clipEdge(
  polygon: Point2D[],
  edgeStart: Point2D,
  edgeEnd: Point2D
): Point2D[] {
  if (polygon.length === 0) return []

  const result: Point2D[] = []

  for (let i = 0; i < polygon.length; i++) {
    const current = polygon[i]
    const previous = polygon[(i + polygon.length - 1) % polygon.length]

    const currInside = sideOfLine(current, edgeStart, edgeEnd) >= -1e-10
    const prevInside = sideOfLine(previous, edgeStart, edgeEnd) >= -1e-10

    if (currInside) {
      if (!prevInside) {
        const inter = segIntersection(previous, current, edgeStart, edgeEnd)
        if (inter) result.push(inter)
      }
      result.push(current)
    } else if (prevInside) {
      const inter = segIntersection(previous, current, edgeStart, edgeEnd)
      if (inter) result.push(inter)
    }
  }

  return result
}

/** Line-segment intersection (returns point or null). */
function segIntersection(
  p1: Point2D, p2: Point2D,
  p3: Point2D, p4: Point2D
): Point2D | null {
  const result = lineIntersection(p1, p2, p3, p4)
  if (!result.ok) return null
  return result.value.point
}

// ─── Closest-point helpers ─────────────────────────────────────────────────

function closestPointOnPolygonBoundary(
  polygon: Point2D[],
  target: Point2D
): Point2D {
  const n = polygon.length
  let minDist = Infinity
  let closest: Point2D = polygon[0]

  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    const pt = closestPointOnSegment(polygon[i], polygon[j], target)
    const dx = pt.easting - target.easting
    const dy = pt.northing - target.northing
    const dist = dx * dx + dy * dy
    if (dist < minDist) {
      minDist = dist
      closest = pt
    }
  }

  return closest
}

function closestPointOnSegment(
  a: Point2D,
  b: Point2D,
  p: Point2D
): Point2D {
  const dx = b.easting - a.easting
  const dy = b.northing - a.northing
  const lenSq = dx * dx + dy * dy

  if (lenSq < 1e-12) return { ...a }

  let t = ((p.easting - a.easting) * dx + (p.northing - a.northing) * dy) / lenSq
  t = Math.max(0, Math.min(1, t))

  return {
    easting: a.easting + t * dx,
    northing: a.northing + t * dy,
  }
}

function pickClosest(points: Point2D[], reference: Point2D): Point2D {
  let minDist = Infinity
  let closest = points[0]
  for (const pt of points) {
    const dx = pt.easting - reference.easting
    const dy = pt.northing - reference.northing
    const dist = dx * dx + dy * dy
    if (dist < minDist) {
      minDist = dist
      closest = pt
    }
  }
  return closest
}

// ─── Road Reserve Generation ──────────────────────────────────────────────────

/**
 * Create a road reserve corridor along selected edges of a parent polygon.
 *
 * Algorithm:
 * 1. For each selected edge, compute the inward parallel offset at `width` distance
 * 2. Use line-line intersection to compute road corridor corners
 * 3. Clip the parent polygon (Sutherland-Hodgman) to remove the road corridor,
 *    leaving the developable area
 *
 * @param parentVertices - Parent parcel polygon (closed or open)
 * @param width - Road reserve width in meters (e.g., 12 for a 2-lane road)
 * @param edgeIndices - Edge indices to apply road reserve; empty = auto-detect longest
 * @returns Road corridor polygon, remaining developable polygon, and clipped edge indices
 */
export function createRoadReserve(
  parentVertices: Point2D[],
  width: number,
  edgeIndices: number[]
): {
  roadPolygon: Point2D[]       // the road corridor polygon
  remainingPolygon: Point2D[]  // the developable area (parent minus road)
  clippedEdges: number[]       // which edges were used
} {
  const polygon = stripClosing(parentVertices)
  const n = polygon.length

  if (n < 3 || width <= 0) {
    return { roadPolygon: [], remainingPolygon: polygon, clippedEdges: [] }
  }

  // Auto-detect longest edge if none specified
  let edges = [...edgeIndices]
  if (edges.length === 0) {
    let maxLen = 0
    let maxIdx = 0
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n
      const dx = polygon[j].easting - polygon[i].easting
      const dy = polygon[j].northing - polygon[i].northing
      const len = Math.sqrt(dx * dx + dy * dy)
      if (len > maxLen) {
        maxLen = len
        maxIdx = i
      }
    }
    edges = [maxIdx]
  }

  // Sort and deduplicate, wrap to valid range
  edges = Array.from(new Set(edges.map(e => ((e % n) + n) % n))).sort((a, b) => a - b)

  // Compute centroid for inward direction determination
  const centroid = polyCentroid(polygon)

  // For each road edge, compute the inward normal and offset points
  const edgeData: Array<{
    idx: number
    start: Point2D
    end: Point2D
    normalX: number
    normalY: number
    offsetStart: Point2D
    offsetEnd: Point2D
  }> = []

  for (const edgeIdx of edges) {
    const j = (edgeIdx + 1) % n
    const A = polygon[edgeIdx]
    const B = polygon[j]

    const dx = B.easting - A.easting
    const dy = B.northing - A.northing
    const edgeLen = Math.sqrt(dx * dx + dy * dy)

    if (edgeLen < 1e-10) continue

    // Two candidate perpendiculars: (-dy/len, dx/len) and (dy/len, -dx/len)
    const nx1 = -dy / edgeLen
    const ny1 = dx / edgeLen

    // Pick the one pointing inward (towards centroid)
    const mid = { easting: (A.easting + B.easting) / 2, northing: (A.northing + B.northing) / 2 }
    const p1 = { easting: mid.easting + nx1 * 10, northing: mid.northing + ny1 * 10 }
    const d1 = Math.sqrt((p1.easting - centroid.easting) ** 2 + (p1.northing - centroid.northing) ** 2)
    const dOrig = Math.sqrt((mid.easting - centroid.easting) ** 2 + (mid.northing - centroid.northing) ** 2)

    const inx = d1 < dOrig ? nx1 : -nx1
    const iny = d1 < dOrig ? ny1 : -ny1

    const offsetStart = { easting: A.easting + width * inx, northing: A.northing + width * iny }
    const offsetEnd = { easting: B.easting + width * inx, northing: B.northing + width * iny }

    edgeData.push({
      idx: edgeIdx,
      start: A,
      end: B,
      normalX: inx,
      normalY: iny,
      offsetStart,
      offsetEnd,
    })
  }

  // ─── Compute remaining polygon by clipping against each offset line ────
  let remaining = [...polygon]

  for (const edge of edgeData) {
    // Clip against the offset line, keeping the centroid (interior) side
    // clipEdge keeps points on LEFT of directed edge (edgeStart → edgeEnd)
    // We need centroid to be on the LEFT of the clip edge
    const side = sideOfLine(centroid, edge.offsetStart, edge.offsetEnd)
    if (side >= 0) {
      remaining = clipEdge(remaining, edge.offsetStart, edge.offsetEnd)
    } else {
      remaining = clipEdge(remaining, edge.offsetEnd, edge.offsetStart)
    }
  }

  // ─── Build road corridor polygon ──────────────────────────────────────
  const roadPolygon = buildRoadCorridor(polygon, edges, edgeData, n, width)

  return {
    roadPolygon: roadPolygon.length >= 3 ? stripClosing(roadPolygon) : [],
    remainingPolygon: remaining.length >= 3 ? stripClosing(remaining) : polygon,
    clippedEdges: edgeData.map(e => e.idx),
  }
}

/**
 * Build the road corridor polygon from edge data.
 *
 * Groups consecutive road edges into runs. For each run:
 * - Outer boundary: original polygon vertices along the run
 * - Inner boundary: offset vertices along the run (reversed)
 * - Connected at ends by perpendicular caps
 *
 * For non-consecutive edges, each run produces a separate corridor segment;
 * they are merged into a single polygon using connecting segments.
 */
function buildRoadCorridor(
  polygon: Point2D[],
  edges: number[],
  edgeData: Array<{
    idx: number
    start: Point2D
    end: Point2D
    normalX: number
    normalY: number
    offsetStart: Point2D
    offsetEnd: Point2D
  }>,
  n: number,
  width: number
): Point2D[] {
  if (edgeData.length === 0) return []

  // Build a map from edge index to edge data
  const edgeMap = new Map<number, typeof edgeData[0]>()
  for (const ed of edgeData) {
    edgeMap.set(ed.idx, ed)
  }

  // Group edges into runs of consecutive edges (modular)
  const runs: number[][] = []
  let currentRun: number[] = []

  for (let i = 0; i < edges.length; i++) {
    if (i === 0) {
      currentRun = [edges[i]]
    } else if (edges[i] === (edges[i - 1] + 1) % n || edges[i] === edges[i - 1] + 1) {
      currentRun.push(edges[i])
    } else {
      runs.push(currentRun)
      currentRun = [edges[i]]
    }
  }
  runs.push(currentRun)

  // Build each run's corridor polygon
  const corridorParts: Point2D[][] = []

  for (const run of runs) {
    const firstEdge = edgeMap.get(run[0])
    const lastEdge = edgeMap.get(run[run.length - 1])
    if (!firstEdge || !lastEdge) continue

    const corridor: Point2D[] = []

    // ── Outer boundary: walk along original polygon vertices ──
    corridor.push({ ...firstEdge.start })
    for (const edgeIdx of run) {
      const ed = edgeMap.get(edgeIdx)
      if (!ed) continue
      corridor.push({ ...ed.end })
    }

    // ── End cap: perpendicular from last edge endpoint to offset ──
    corridor.push({ ...lastEdge.offsetEnd })

    // ── Inner boundary: walk back along offset lines (reversed) ──
    for (let i = run.length - 1; i >= 0; i--) {
      const edgeIdx = run[i]
      const ed = edgeMap.get(edgeIdx)
      if (!ed) continue

      // If there's a next edge in the run (i.e., a corner), add bevel point
      if (i < run.length - 1) {
        const nextEdge = edgeMap.get(run[i + 1])
        if (nextEdge) {
          // The bevel connects offsetStart of next edge to offsetEnd of current edge
          // But we're going backwards, so we add offsetEnd of current edge first,
          // then offsetStart of the next edge is already added
          // Actually: at the shared vertex, the two offset points are:
          // ed.offsetEnd (end of current edge's offset) and nextEdge.offsetStart (start of next edge's offset)
          // The bevel connects them: ed.offsetEnd → nextEdge.offsetStart
          // But since we're reversed, we encounter nextEdge first, then ed
        }
      }
      corridor.push({ ...ed.offsetStart })
    }

    if (corridor.length >= 3) {
      corridorParts.push(corridor)
    }
  }

  // If only one corridor part, return it directly
  if (corridorParts.length === 1) {
    return corridorParts[0]
  }

  // For multiple parts, merge them by finding shortest connecting segment
  // Simple approach: connect end of part i to start of part i+1
  if (corridorParts.length > 1) {
    const merged: Point2D[] = []
    for (const part of corridorParts) {
      if (merged.length > 0) {
        merged.push(part[0])
      }
      merged.push(...part)
    }
    return merged
  }

  return []
}

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Subdivide a parent parcel polygon using the specified method and parameters.
 * If road reserve parameters are provided, the road corridor is carved out first
 * and subdivision is applied to the remaining developable area.
 */
export function subdivide(
  parentVertices: Point2D[],
  method: SubdivisionMethod,
  params: SubdivisionParams
): SubdivisionResult {
  const parent = stripClosing(parentVertices)
  const parentArea = areaHa(parent)

  const result: SubdivisionResult = {
    method,
    parentParcel: {
      vertices: parent,
      areaHa: parentArea,
    },
    lots: [],
    totalAreaHa: 0,
    remainderAreaHa: 0,
  }

  // ─── Apply road reserve if configured ─────────────────────────────────
  const rrWidth = params.roadReserveWidth
  const rrEdges = params.roadReserveEdges
  let effectiveParent = parent

  if (rrWidth && rrWidth > 0 && rrEdges !== undefined) {
    const rr = createRoadReserve(parent, rrWidth, rrEdges)
    if (rr.roadPolygon.length >= 3) {
      result.roadReserve = {
        roadPolygon: rr.roadPolygon,
        width: rrWidth,
        clippedEdges: rr.clippedEdges,
        areaHa: areaHa(rr.roadPolygon),
      }
      if (rr.remainingPolygon.length >= 3) {
        effectiveParent = rr.remainingPolygon
      }
    }
  }

  let lots: SubdividedLot[]

  switch (method) {
    case 'single-split':
      lots = subdivideSingleSplit(effectiveParent, params.splitLine!)
      break
    case 'grid':
      lots = subdivideGrid(effectiveParent, params.rows ?? 2, params.cols ?? 2)
      break
    case 'radial':
      lots = subdivideRadial(effectiveParent, params.center, params.numLots ?? 4)
      break
    case 'area':
      lots = subdivideByArea(effectiveParent, params.targetArea ?? parentArea / 2, params.preferredBearing)
      break
    default:
      throw new Error(`Unknown subdivision method: ${method}`)
  }

  result.lots = lots
  result.totalAreaHa = lots.reduce((s, l) => s + l.areaHa, 0)
  const effectiveArea = areaHa(effectiveParent)
  result.remainderAreaHa = Math.max(0, effectiveArea - result.totalAreaHa)

  return result
}

// ─── Method 1: Single Split ─────────────────────────────────────────────────

function subdivideSingleSplit(
  polygon: Point2D[],
  splitLine: SplitLine
): SubdividedLot[] {
  if (!splitLine) return []

  const pieces = splitPolygonByLine(
    polygon,
    splitLine.startPoint,
    splitLine.endPoint
  )

  if (pieces.length < 2) {
    return [{
      lotNumber: 1,
      vertices: polygon,
      areaHa: areaHa(polygon),
      perimeter: perimeter(polygon),
      centroid: polyCentroid(polygon),
    }]
  }

  return pieces.map((piece, i) => ({
    lotNumber: i + 1,
    vertices: stripClosing(piece),
    areaHa: areaHa(piece),
    perimeter: perimeter(piece),
    centroid: polyCentroid(piece),
  }))
}

// ─── Method 2: Grid Subdivision ─────────────────────────────────────────────

function subdivideGrid(
  polygon: Point2D[],
  rows: number,
  cols: number
): SubdividedLot[] {
  if (rows < 1 || cols < 1) return []

  // Compute bounding box of the polygon
  let minE = Infinity, maxE = -Infinity
  let minN = Infinity, maxN = -Infinity

  for (const pt of polygon) {
    minE = Math.min(minE, pt.easting)
    maxE = Math.max(maxE, pt.easting)
    minN = Math.min(minN, pt.northing)
    maxN = Math.max(maxN, pt.northing)
  }

  const cellW = (maxE - minE) / cols
  const cellH = (maxN - minN) / rows

  const lots: SubdividedLot[] = []
  let lotNum = 1

  // Number lots left-to-right, top-to-bottom
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const cellMinE = minE + c * cellW
      const cellMaxE = minE + (c + 1) * cellW
      const cellMinN = minN + r * cellH
      const cellMaxN = minN + (r + 1) * cellH

      // Cell rectangle wound COUNTER-CLOCKWISE so that "inside" (left side of
      // each directed edge) matches the Sutherland-Hodgman clip test.
      // CCW: BL → BR → TR → TL
      const cellRect: Point2D[] = [
        { easting: cellMinE, northing: cellMinN }, // bottom-left
        { easting: cellMaxE, northing: cellMinN }, // bottom-right
        { easting: cellMaxE, northing: cellMaxN }, // top-right
        { easting: cellMinE, northing: cellMaxN }, // top-left
      ]

      // Clip polygon to the cell
      const clipped = clipPolygonByBoundary(polygon, cellRect)

      if (clipped.length >= 3 && isValidPolygon(clipped)) {
        const a = areaHa(clipped)
        // Skip tiny slivers (< 1 sqm)
        if (a * 10000 < 1) continue

        lots.push({
          lotNumber: lotNum++,
          vertices: stripClosing(clipped),
          areaHa: a,
          perimeter: perimeter(clipped),
          centroid: polyCentroid(clipped),
        })
      }
    }
  }

  return lots
}

// ─── Method 3: Radial Subdivision ───────────────────────────────────────────

function subdivideRadial(
  polygon: Point2D[],
  center: Point2D | undefined,
  numLots: number
): SubdividedLot[] {
  if (!center) {
    center = polyCentroid(polygon)
  }
  if (numLots < 2) return []

  // Project center onto polygon boundary if it's outside
  if (!pointInPolygon(center, polygon)) {
    center = closestPointOnPolygonBoundary(polygon, center)
  }

  // Create equal angular divisions
  const sectorAngle = (2 * Math.PI) / numLots
  const lots: SubdividedLot[] = []

  for (let s = 0; s < numLots; s++) {
    const startAngle = s * sectorAngle - Math.PI
    const endAngle = (s + 1) * sectorAngle - Math.PI

    // Find intersection points of the two radial lines with polygon boundary
    const farPoint1: Point2D = {
      easting: center.easting + 100000 * Math.sin(startAngle),
      northing: center.northing + 100000 * Math.cos(startAngle),
    }
    const farPoint2: Point2D = {
      easting: center.easting + 100000 * Math.sin(endAngle),
      northing: center.northing + 100000 * Math.cos(endAngle),
    }

    const startInters = findLinePolygonIntersections(center, farPoint1, polygon)
    const endInters = findLinePolygonIntersections(center, farPoint2, polygon)

    const startPt = startInters.length > 0
      ? pickClosest(startInters.map(i => i.point), center)
      : null
    const endPt = endInters.length > 0
      ? pickClosest(endInters.map(i => i.point), center)
      : null

    if (!startPt || !endPt) continue

    // Build sector polygon:
    // center → startPt → boundary walk → endPt → center
    const sectorVerts = buildSectorPolygon(polygon, center, startPt, endPt)

    if (sectorVerts.length >= 3) {
      const a = areaHa(sectorVerts)
      if (a * 10000 < 1) continue

      lots.push({
        lotNumber: s + 1,
        vertices: stripClosing(sectorVerts),
        areaHa: a,
        perimeter: perimeter(sectorVerts),
        centroid: polyCentroid(sectorVerts),
      })
    }
  }

  return lots
}

/**
 * Build a sector polygon by walking the boundary from startPt to endPt,
 * including the center point and both intersection points.
 */
function buildSectorPolygon(
  polygon: Point2D[],
  center: Point2D,
  startPt: Point2D,
  endPt: Point2D
): Point2D[] {
  const n = polygon.length
  const verts: Point2D[] = []

  // Find which edges the start and end intersection points lie on
  let startEdge = -1
  let endEdge = -1

  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    const closest = closestPointOnSegment(polygon[i], polygon[j], startPt)
    const dx = closest.easting - startPt.easting
    const dy = closest.northing - startPt.northing
    if (dx * dx + dy * dy < 1.0) {
      startEdge = i
      break
    }
  }

  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    const closest = closestPointOnSegment(polygon[i], polygon[j], endPt)
    const dx = closest.easting - endPt.easting
    const dy = closest.northing - endPt.northing
    if (dx * dx + dy * dy < 1.0) {
      endEdge = i
      break
    }
  }

  // Build: startPt → polygon vertices from startEdge+1 to endEdge → endPt
  verts.push({ ...startPt })

  if (startEdge >= 0 && endEdge >= 0 && startEdge !== endEdge) {
    let idx = (startEdge + 1) % n
    const visited = new Set<number>()
    while (idx !== endEdge && !visited.has(idx)) {
      visited.add(idx)
      verts.push(polygon[idx])
      idx = (idx + 1) % n
    }
  }

  verts.push({ ...endPt })

  return verts
}

// ─── Method 4: Area-Based Subdivision ───────────────────────────────────────

function subdivideByArea(
  polygon: Point2D[],
  targetAreaHa: number,
  preferredBearing?: number
): SubdividedLot[] {
  if (targetAreaHa <= 0) return []

  const targetSqm = targetAreaHa * 10000
  const lots: SubdividedLot[] = []
  let remaining = [...polygon]
  let lotNumber = 1
  const maxIterations = 50

  for (let iter = 0; iter < maxIterations; iter++) {
    const currentArea = Math.abs(signedArea(remaining))

    if (currentArea < targetSqm * 0.05) break
    if (remaining.length < 3) break

    // If remaining area is close to target, add as last lot
    if (currentArea <= targetSqm * 1.15) {
      lots.push(makeLot(lotNumber++, remaining, targetAreaHa))
      break
    }

    // Find the longest edge of the remaining polygon
    const n = remaining.length
    let longestEdge = 0
    let longestLen = 0
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n
      const dx = remaining[j].easting - remaining[i].easting
      const dy = remaining[j].northing - remaining[i].northing
      const len = Math.sqrt(dx * dx + dy * dy)
      if (len > longestLen) {
        longestLen = len
        longestEdge = i
      }
    }

    const edgeStart = remaining[longestEdge]
    const edgeEnd = remaining[(longestEdge + 1) % n]
    const dx = edgeEnd.easting - edgeStart.easting
    const dy = edgeEnd.northing - edgeStart.northing

    // Determine cut bearing
    const edgeBearing = normalizeBearing(Math.atan2(dx, dy) * 180 / Math.PI)
    const cutBearing = preferredBearing !== undefined
      ? preferredBearing
      : normalizeBearing(edgeBearing + 90)

    // Try the preferred (or auto-perpendicular) bearing first.
    // If that fails (e.g. bearing parallel to polygon), try the opposite direction.
    let successfulCut = false

    for (let bearingAttempt = 0; bearingAttempt < 2 && !successfulCut; bearingAttempt++) {
      let effectiveBearing: number
      if (bearingAttempt === 0) {
        effectiveBearing = cutBearing
      } else {
        // Flip 90° — the perpendicular of the perpendicular
        effectiveBearing = normalizeBearing(cutBearing + 90)
      }

      const effectiveRad = toRadians(effectiveBearing)

      // Binary search for the cut distance along the edge
      let lo = 0
      let hi = longestLen
      let cutDist = longestLen / 2

      for (let bIter = 0; bIter < 30; bIter++) {
        cutDist = (lo + hi) / 2

        const cutPt: Point2D = {
          easting: edgeStart.easting + (dx / longestLen) * cutDist,
          northing: edgeStart.northing + (dy / longestLen) * cutDist,
        }

        const perpPt: Point2D = {
          easting: cutPt.easting + 100000 * Math.sin(effectiveRad),
          northing: cutPt.northing + 100000 * Math.cos(effectiveRad),
        }

        const pieces = splitPolygonByLine(remaining, cutPt, perpPt)

        if (pieces.length < 2) {
          hi = cutDist
          continue
        }

        // Find the smaller piece (the "cut-off" lot)
        const lotPiece = pieces.reduce((smaller, p) => {
          const a = Math.abs(signedArea(p))
          const sA = Math.abs(signedArea(smaller))
          return a < sA ? p : smaller
        }, pieces[0])

        const lotArea = Math.abs(signedArea(lotPiece))

        if (lotArea < targetSqm) {
          lo = cutDist
        } else {
          hi = cutDist
        }
      }

      // Perform final cut
      const finalCutPt: Point2D = {
        easting: edgeStart.easting + (dx / longestLen) * cutDist,
        northing: edgeStart.northing + (dy / longestLen) * cutDist,
      }

      const finalPerpPt: Point2D = {
        easting: finalCutPt.easting + 100000 * Math.sin(effectiveRad),
        northing: finalCutPt.northing + 100000 * Math.cos(effectiveRad),
      }

      const finalPieces = splitPolygonByLine(remaining, finalCutPt, finalPerpPt)

      if (finalPieces.length < 2) continue

      // Identify lot piece (smaller area) and remainder (larger area)
      const lotPiece = finalPieces.reduce((smaller, p) => {
        const a = Math.abs(signedArea(p))
        const sA = Math.abs(signedArea(smaller))
        return a < sA ? p : smaller
      }, finalPieces[0])

      const remainderPiece = finalPieces.find(p => p !== lotPiece) ?? finalPieces[1]

      lots.push(makeLot(lotNumber++, lotPiece, targetAreaHa))
      remaining = remainderPiece
      successfulCut = true
    }

    if (!successfulCut) {
      lots.push(makeLot(lotNumber++, remaining, targetAreaHa))
      break
    }
  }

  return lots
}

function makeLot(num: number, verts: Point2D[], target?: number): SubdividedLot {
  const a = areaHa(verts)
  return {
    lotNumber: num,
    vertices: stripClosing(verts),
    areaHa: a,
    perimeter: perimeter(verts),
    centroid: polyCentroid(verts),
    areaTarget: target,
    areaError: target !== undefined ? a - target : undefined,
  }
}

