/**
 * Export audit logs matching the query as a CSV string.
 */
export async function exportAuditCSV(query: AuditQuery): Promise<string> {
  const exportQuery: AuditQuery = {
    ...query,
    limit: Math.min(query.limit ?? 10000, 10000),
    offset: 0,
  };

  const { events } = await queryAuditLogs(exportQuery);

  const headers = [
    'id',
    'timestamp',
    'user_id',
    'action',
    'resource_type',
    'resource_id',
    'details',
    'ip_address',
    'user_agent',
  ];

  const rows = events.map((e) => {
    const detailsStr = e.details ? JSON.stringify(e.details) : '';
    return [
      String(e.id),
      e.timestamp.toISOString(),
      e.userId,
      csvEscape(e.action),
      csvEscape(e.resourceType),
      e.resourceId ? csvEscape(e.resourceId) : '',
      csvEscape(detailsStr),
      e.ipAddress ?? '',
      csvEscape(e.userAgent ?? ''),
    ].join(',');
  });

  return [headers.join(','), ...rows].join('\n');
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function csvEscape(value: string): string {
  if (!value) return '""';
  const escaped = value.replace(/"/g, '""');
  return `"${escaped}"`;
}

/**
 * Cloud Rendering Service
 * Phase 10 - Enterprise Features
 * Server-side rendering for large survey projects
 */

export interface CloudRenderJob {
  id: string
  projectId: string
  projectName: string
  userId: string
  status: 'queued' | 'processing' | 'completed' | 'failed'
  progress: number
  createdAt: number
  completedAt?: number
  renderType: '2d_plan' | '3d_model' | 'contour_map' | 'cross_section' | 'orthomosaic'
  parameters: RenderParameters
  result?: RenderResult
  error?: string
}

export interface RenderParameters {
  format: 'png' | 'pdf' | 'svg' | 'dwg'
  resolution: 'standard' | 'high' | 'ultra'
  scale?: string
  layers?: string[]
  showLabels: boolean
  showGrid: boolean
  backgroundColor: string
}

export interface RenderResult {
  url: string
  fileSize: number
  width: number
  height: number
  renderTime: number
}

export interface CloudProject {
  id: string
  name: string
  ownerId: string
  size: number
  pointCount: number
  lastRendered?: number
  storageUsed: number
  storageLimit: number
}

const renderQueue: CloudRenderJob[] = []
const cloudProjects: CloudProject[] = []

export function submitCloudRender(
  projectId: string,
  projectName: string,
  userId: string,
  renderType: CloudRenderJob['renderType'],
  parameters: RenderParameters
): CloudRenderJob {
  const job: CloudRenderJob = {
    id: `render-${Date.now()}`,
    projectId,
    projectName,
    userId,
    status: 'queued',
    progress: 0,
    createdAt: Date.now(),
    renderType,
    parameters,
  }
  renderQueue.push(job)
  
  setTimeout(() => {
    job.status = 'processing'
    const interval = setInterval(() => {
      job.progress += 20
      if (job.progress >= 100) {
        job.status = 'completed'
        job.completedAt = Date.now()
        job.result = {
          url: `https://cdn.metardu.app/renders/${job.id}.${parameters.format}`,
          fileSize: 0,
          width: parameters.resolution === 'ultra' ? 8000 : parameters.resolution === 'high' ? 4000 : 2000,
          height: parameters.resolution === 'ultra' ? 6000 : parameters.resolution === 'high' ? 3000 : 1500,
          renderTime: 0,
        }
        clearInterval(interval)
      }
    }, 500)
  }, 100)
  
  return job
}

export function getRenderJob(jobId: string): CloudRenderJob | undefined {
  return renderQueue.find((j: any) => j.id === jobId)
}

export function getUserRenderJobs(userId: string): CloudRenderJob[] {
  return renderQueue.filter((j: any) => j.userId === userId)
}

export function createCloudProject(
  name: string,
  ownerId: string,
  pointCount: number
): CloudProject {
  const project: CloudProject = {
    id: `cloud-${Date.now()}`,
    name,
    ownerId,
    size: pointCount * 100,
    pointCount,
    storageUsed: pointCount * 100,
    storageLimit: 1000000000, // 1GB
  }
  cloudProjects.push(project)
  return project
}

export function getCloudProject(projectId: string): CloudProject | undefined {
  return cloudProjects.find((p: any) => p.id === projectId)
}

export function getRenderTypes() {
  return [
    { id: '2d_plan', name: '2D Survey Plan', icon: '[Compass]' },
    { id: '3d_model', name: '3D Surface Model', icon: '' },
    { id: 'contour_map', name: 'Contour Map', icon: '[Mtn]' },
    { id: 'cross_section', name: 'Cross Section', icon: '[Cut]' },
    { id: 'orthomosaic', name: 'Orthomosaic', icon: '[Map]' },
  ]
}

export function estimateRenderTime(
  renderType: CloudRenderJob['renderType'],
  pointCount: number,
  resolution: RenderParameters['resolution']
): number {
  const baseTime = {
    '2d_plan': 10,
    '3d_model': 30,
    'contour_map': 20,
    'cross_section': 15,
    'orthomosaic': 45,
  }[renderType] || 20
  
  const pointMultiplier = Math.ceil(pointCount / 10000)
  const resolutionMultiplier = resolution === 'ultra' ? 3 : resolution === 'high' ? 2 : 1
  
  return baseTime * pointMultiplier * resolutionMultiplier
}

