/**
 * METARDU Topographic Auto-Draw DXF Export
 * Phase B3 — Topo Auto-Draw
 *
 * Takes feature-coded points and auto-generates a DXF plan with:
 * - Layers mapped from the feature code library
 * - Polylines joining sequential points of the same code
 * - Point symbols (blocks or basic CAD entities)
 * - Point labels (elevation / point number)
 */

import Drawing from 'dxf-writer'
import { KENYA_TOPO_CODES, FeatureCodeDef } from '@/lib/topo/featureCodes'
import { initialiseSokDXFLayers, DXF_LAYERS } from '@/lib/drawing/dxfLayers'

export interface TopoPoint {
  easting: number
  northing: number
  elevation?: number
  code?: string
  pointNumber?: string
}

export interface TopoAutoDrawOptions {
  projectName?: string
  drawElevations?: boolean
  drawPointNumbers?: boolean
  defaultLayer?: string
}

export function generateTopoDXF(
  points: TopoPoint[],
  options?: TopoAutoDrawOptions
): string {
  if (!points || points.length === 0) return ''

  const drawing = new Drawing()
  initialiseSokDXFLayers(drawing)
  drawing.setUnits('Meters')

  // Register linetypes
  drawing.addLineType('DASHED', 'Dashed', [-5.0, 2.5])
  drawing.addLineType('CENTER', 'Center', [10.0, -2.5, 2.5, -2.5])
  drawing.addLineType('DOTTED', 'Dotted', [0, -2.5])

  // Build code lookup map
  const codeMap = new Map<string, FeatureCodeDef>()
  for (const def of KENYA_TOPO_CODES) {
    codeMap.set(def.code.toUpperCase(), def)
  }

  // Register layers dynamically based on codes present
  const usedCodes = new Set<string>()
  for (const pt of points) {
    if (pt.code) {
      const baseCode = pt.code.split(/\s+/)[0].toUpperCase()
      usedCodes.add(baseCode)
    }
  }

  const registeredLayers = new Set<string>()
  for (const code of Array.from(usedCodes)) {
    const def = codeMap.get(code)
    if (def && !registeredLayers.has(def.dxfLayer)) {
      drawing.addLayer(def.dxfLayer, def.color, def.lineType)
      registeredLayers.add(def.dxfLayer)
    }
  }

  // Group points by code for polyline generation
  // Format: MAP<code, Array<Array<TopoPoint>>>
  // Some field practices use string suffixes (e.g., RD1, RD2) to separate multiple strings of the same code.
  const lineStrings = new Map<string, TopoPoint[]>()
  
  for (const pt of points) {
    if (!pt.code) continue

    // The raw code might be "RD 1" or "RD1"
    const parts = pt.code.trim().split(/\s+/)
    const rawCode = parts[0].toUpperCase()
    
    // Attempt to extract base code (e.g., RD from RD1)
    const match = rawCode.match(/^([A-Z\-]+)(\d*)$/)
    const baseCode = match ? match[1] : rawCode
    const stringId = rawCode // unique identifier for the string, e.g., RD1

    const def = codeMap.get(baseCode)
    if (!def) {
      // Fallback: draw as point on default layer
      drawPoint(drawing, pt, options?.defaultLayer ?? 'TOPO-UNKNOWN')
      continue
    }

    if (def.joinLines) {
      const arr = lineStrings.get(stringId) ?? []
      arr.push(pt)
      lineStrings.set(stringId, arr)
    } else {
      drawFeaturePoint(drawing, pt, def, options)
    }
  }

  // Draw Polylines
  for (const [stringId, pts] of Array.from(lineStrings.entries())) {
    const match = stringId.match(/^([A-Z\-]+)(\d*)$/)
    const baseCode = match ? match[1] : stringId
    const def = codeMap.get(baseCode)!

    drawing.setActiveLayer(def.dxfLayer)
    
    // Draw lines
    for (let i = 0; i < pts.length - 1; i++) {
      const p1 = pts[i]
      const p2 = pts[i + 1]
      drawing.drawLine(p1.easting, p1.northing, p2.easting, p2.northing)
    }

    // Draw individual symbols/labels if needed
    for (const pt of pts) {
      drawFeaturePoint(drawing, pt, def, options, false) // false = don't set layer again
    }
  }

  return drawing.toDxfString()
}

function drawFeaturePoint(
  drawing: Drawing,
  pt: TopoPoint,
  def: FeatureCodeDef,
  options?: TopoAutoDrawOptions,
  setLayer: boolean = true
) {
  if (setLayer) {
    drawing.setActiveLayer(def.dxfLayer)
  }

  const sSize = 1.0 // symbol size
  
  // Draw Symbol
  if (def.symbol === 'circle') {
    drawing.drawCircle(pt.easting, pt.northing, sSize / 2)
  } else if (def.symbol === 'square') {
    const r = sSize / 2
    drawing.drawLine(pt.easting - r, pt.northing - r, pt.easting + r, pt.northing - r)
    drawing.drawLine(pt.easting + r, pt.northing - r, pt.easting + r, pt.northing + r)
    drawing.drawLine(pt.easting + r, pt.northing + r, pt.easting - r, pt.northing + r)
    drawing.drawLine(pt.easting - r, pt.northing + r, pt.easting - r, pt.northing - r)
  } else if (def.symbol === 'cross') {
    const r = sSize / 2
    drawing.drawLine(pt.easting - r, pt.northing, pt.easting + r, pt.northing)
    drawing.drawLine(pt.easting, pt.northing - r, pt.easting, pt.northing + r)
  } else if (def.symbol === 'triangle') {
    const r = sSize / 2
    drawing.drawLine(pt.easting - r, pt.northing - r, pt.easting + r, pt.northing - r)
    drawing.drawLine(pt.easting + r, pt.northing - r, pt.easting, pt.northing + r)
    drawing.drawLine(pt.easting, pt.northing + r, pt.easting - r, pt.northing - r)
  } else {
    // just a small tick
    drawing.drawPoint(pt.easting, pt.northing)
  }

  // Draw Labels
  if (def.pointLabel || options?.drawElevations || options?.drawPointNumbers) {
    let label = ''
    if ((def.pointLabel || options?.drawElevations) && pt.elevation !== undefined) {
      label += pt.elevation.toFixed(2)
    }
    if ((def.pointLabel || options?.drawPointNumbers) && pt.pointNumber) {
      label += (label ? ' / ' : '') + pt.pointNumber
    }

    if (label) {
      // Put labels on a generic ANNOTATIONS layer to keep them manageable, or the same layer
      // For now we keep them on the feature layer but shifted slightly
      drawing.drawText(pt.easting + 1, pt.northing + 1, 1.0, 0, label)
    }
  }
}

function drawPoint(drawing: Drawing, pt: TopoPoint, layerName: string) {
  drawing.setActiveLayer(layerName)
  drawing.drawPoint(pt.easting, pt.northing)
  drawing.drawText(pt.easting + 1, pt.northing + 1, 1.0, 0, pt.code ?? '?')
}

/**
 * Traverse-Specific DXF Export Generator
 *
 * Produces a professional traverse plan DXF using the `dxf-writer` library.
 * Designed for Kenyan cadastral surveys — includes control point markers,
 * raw/adjusted traverse lines, parcel boundary, coordinate grid, and a
 * Kenya Survey Regulations-compliant title block.
 *
 * Layers:
 *   CONTROL_POINTS   — Point markers (cross + circle) at each station
 *   CONTROL_LABELS   — Station name labels with coordinates
 *   TRAVERSE_RAW     — Raw traverse legs (dashed, red)
 *   TRAVERSE_ADJUSTED— Adjusted traverse legs (solid, green)
 *   PARCEL_BOUNDARY  — Closed polygon boundary (if applicable)
 *   GRID             — Coordinate grid at 1 km intervals
 *   TITLE_BLOCK      — Title block text and border
 *   BORDER           — Sheet border
 *   NORTH_ARROW      — North arrow symbol
 *   SCALE_BAR        — Scale bar
 *
 * Reference standards:
 * - Survey of Kenya Drawing Standards
 * - Kenya Survey Regulations 1994
 * - ISO 5457 (Technical product documentation — Sizes and layout of drawing sheets)
 * - ISO 7200 (Technical product documentation — Title blocks)
 */

import Drawing from 'dxf-writer'
import { DXF_LAYERS, formatBearingDMS, initialiseSokDXFLayers } from '@/lib/drawing/dxfLayers'

// ─── Public Types ────────────────────────────────────────────────────────────

export interface TraverseStation {
  name: string
  easting: number
  northing: number
  /** Adjusted easting (after traverse computation) */
  adjustedEasting?: number
  /** Adjusted northing (after traverse computation) */
  adjustedNorthing?: number
}

export interface TraverseLeg {
  from: string
  to: string
  bearing: number
  distance: number
}

export interface TraverseMisclosure {
  angular: number
  linear: number
  precisionRatio: number
}

export interface TraverseProjectInfo {
  name: string
  lrNumber: string
  county: string
  datum: string
  surveyor: string
}

export interface TraverseDXFOptions {
  stations: TraverseStation[]
  legs: TraverseLeg[]
  misclosure: TraverseMisclosure
  projectInfo: TraverseProjectInfo
  /** Sheet size for layout (default: 'A3') */
  sheetSize?: 'A0' | 'A1' | 'A2' | 'A3' | 'A4'
  /** Scale denominator e.g. 1000 for 1:1000 (default: auto-computed) */
  scale?: number
  /** Grid interval in meters (default: 1000 for 1km) */
  gridInterval?: number
}

// ─── Constants ───────────────────────────────────────────────────────────────

/** ACI colour index for traverse-specific layers */
const ACI = {
  WHITE: 7,
  RED: 1,
  GREEN: 3,
  YELLOW: 2,
  CYAN: 4,
  MAGENTA: 6,
  GREY: 8,
  BLUE: 5,
}

/** Sheet dimensions in mm (width, height) — landscape orientation */
const SHEET_DIMS: Record<string, [number, number]> = {
  A0: [1189, 841],
  A1: [841, 594],
  A2: [594, 420],
  A3: [420, 297],
  A4: [297, 210],
}

/** Title block height in mm per sheet size */
const TB_HEIGHT: Record<string, number> = {
  A0: 40,
  A1: 40,
  A2: 30,
  A3: 30,
  A4: 25,
}

/** Border inset from sheet edge in mm */
const BORDER_INSET = 2

/** Inner margin for drawing area in mm */
const INNER_MARGIN = 15

/** Cross marker size for control points (in model units / meters) */
const CROSS_SIZE = 2.0

/** Circle radius for control point markers (in model units / meters) */
const CIRCLE_RADIUS = 1.5

/** Default text height for station labels (model units / meters) */
const LABEL_HEIGHT = 2.0

/** Coordinate label height (model units / meters) */
const COORD_LABEL_HEIGHT = 1.2

/** North arrow size in mm */
const NORTH_ARROW_SIZE = 12

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Format number to fixed decimals for DXF */
function f(value: number, decimals = 4): string {
  return value.toFixed(decimals)
}

/** Format an ISO date for display (dd/mm/yyyy) */
function formatPlanDate(date: string | Date): string {
  const d = typeof date === 'string' ? new Date(date) : date
  const dd = String(d.getDate()).padStart(2, '0')
  const mm = String(d.getMonth() + 1).padStart(2, '0')
  const yyyy = d.getFullYear()
  return `${dd}/${mm}/${yyyy}`
}

/**
 * Compute a sensible scale denominator that fits the traverse data on the sheet.
 * Returns a "nice" number from a standard scale series.
 */
function computeAutoScale(
  stations: TraverseStation[],
  sheetSize: string,
): number {
  if (stations.length === 0) return 1000

  let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity
  for (const s of stations) {
    const e = s.adjustedEasting ?? s.easting
    const n = s.adjustedNorthing ?? s.northing
    if (e < minE) minE = e
    if (e > maxE) maxE = e
    if (n < minN) minN = n
    if (n > maxN) maxN = n
  }

  const rangeE = maxE - minE || 100
  const rangeN = maxN - minN || 100

  // Add 20% padding
  const paddedE = rangeE * 1.2
  const paddedN = rangeN * 1.2

  const [sheetW, sheetH] = SHEET_DIMS[sheetSize]
  const drawW = sheetW - 2 * INNER_MARGIN - 40  // mm available for drawing
  const drawH = sheetH - 2 * INNER_MARGIN - TB_HEIGHT[sheetSize] - 20

  // Scale = real_meters / paper_mm * 1000  (to get denominator)
  const scaleE = (paddedE / drawW) * 1000
  const scaleN = (paddedN / drawH) * 1000
  const required = Math.max(scaleE, scaleN)

  // Round up to the nearest "nice" scale from standard series
  const niceScales = [
    50, 100, 200, 250, 500,
    1000, 2000, 2500, 5000,
    10000, 20000, 25000, 50000,
    100000,
  ]
  for (const s of niceScales) {
    if (s >= required) return s
  }
  return niceScales[niceScales.length - 1]
}

/**
 * Build station coordinate lookup (preferring adjusted coordinates).
 */
function buildStationMap(stations: TraverseStation[]): Map<string, { e: number; n: number }> {
  const map = new Map<string, { e: number; n: number }>()
  for (const s of stations) {
    map.set(s.name, {
      e: s.adjustedEasting ?? s.easting,
      n: s.adjustedNorthing ?? s.northing,
    })
  }
  return map
}

// ─── Raw DXF String Building ─────────────────────────────────────────────────

/**
 * Build a north arrow symbol using raw DXF entities.
 * Places a triangular arrow at (x, y) pointing up with a circle and "N" label.
 */
function buildNorthArrow(x: number, y: number): string[] {
  const s = NORTH_ARROW_SIZE
  const parts: string[] = []

  // Shaft
  parts.push(
    '0', 'LINE', '8', 'NORTHARROW',
    '10', f(x), '20', f(y - s * 0.6),
    '11', f(x), '21', f(y + s * 0.4),
  )
  // Arrowhead left
  parts.push(
    '0', 'LINE', '8', 'NORTHARROW',
    '10', f(x), '20', f(y + s * 0.4),
    '11', f(x - s * 0.25), '21', f(y + s * 0.05),
  )
  // Arrowhead right
  parts.push(
    '0', 'LINE', '8', 'NORTHARROW',
    '10', f(x), '20', f(y + s * 0.4),
    '11', f(x + s * 0.25), '21', f(y + s * 0.05),
  )
  // Crossbar base
  parts.push(
    '0', 'LINE', '8', 'NORTHARROW',
    '10', f(x - s * 0.2), '20', f(y - s * 0.6),
    '11', f(x + s * 0.1), '21', f(y - s * 0.6),
  )
  // Circle
  parts.push(
    '0', 'CIRCLE', '8', 'NORTHARROW',
    '10', f(x), '20', f(y - s * 0.1), '30', '0',
    '40', f(s * 0.75),
  )
  // "N" label
  parts.push(
    '0', 'TEXT', '8', 'NORTHARROW',
    '10', f(x), '20', f(y + s * 0.7),
    '40', f(s * 0.4),
    '1', 'N',
    '72', '1',   // horizontal center
    '11', f(x), '21', f(y + s * 0.7),
  )

  return parts
}

/**
 * Build a scale bar using raw DXF entities.
 * Segments are sized based on the scale and sheet size.
 */
function buildScaleBar(x: number, y: number, scale: number, sheetSize: string): string[] {
  const parts: string[] = []
  const barH = 3 // mm

  // Target ~60mm per segment on paper
  const targetRealMeters = 60 * scale / 1000

  // Pick a nice step
  const niceSteps = [1, 2, 5, 10, 20, 25, 50, 100, 200, 250, 500, 1000, 2000, 5000]
  let segmentMeters = niceSteps[0]
  for (const step of niceSteps) {
    const segmentMm = (step / scale) * 1000
    if (segmentMm >= 25 && segmentMm <= 120) {
      segmentMeters = step
      break
    }
    segmentMeters = step
  }

  const segmentMm = (segmentMeters / scale) * 1000
  const numSegments = 4

  // Draw segments
  for (let i = 0; i < numSegments; i++) {
    const x0 = x + i * segmentMm
    const x1 = x + (i + 1) * segmentMm
    parts.push(
      '0', 'LWPOLYLINE', '8', 'SCALEBAR',
      '90', '4', '70', '1',
      '10', f(x0), '20', f(y),
      '10', f(x0), '20', f(y + barH),
      '10', f(x1), '20', f(y + barH),
      '10', f(x1), '20', f(y),
    )
  }

  // Outer outline
  const totalW = numSegments * segmentMm
  parts.push(
    '0', 'LWPOLYLINE', '8', 'SCALEBAR',
    '90', '4', '70', '1',
    '10', f(x), '20', f(y),
    '10', f(x), '20', f(y + barH),
    '10', f(x + totalW), '20', f(y + barH),
    '10', f(x + totalW), '20', f(y),
  )

  // Labels
  const labelH = barH * 0.8
  for (let i = 0; i <= numSegments; i++) {
    const px = x + i * segmentMm
    const totalM = i * segmentMeters
    const label = totalM >= 1000
      ? `${(totalM / 1000).toFixed(totalM % 1000 === 0 ? 0 : 1)}km`
      : `${totalM}m`
    parts.push(
      '0', 'TEXT', '8', 'SCALEBAR',
      '10', f(px), '20', f(y - 2.5),
      '40', f(labelH),
      '1', label,
      '72', '1',
      '11', f(px), '21', f(y - 2.5),
    )
  }

  // Per-division label
  const segLabel = segmentMeters >= 1000
    ? `${(segmentMeters / 1000).toFixed(segmentMeters % 1000 === 0 ? 0 : 1)}km`
    : `${segmentMeters}m`
  parts.push(
    '0', 'TEXT', '8', 'SCALEBAR',
    '10', f(x + totalW / 2), '20', f(y - 2.5 - labelH - 1),
    '40', f(labelH),
    '1', `${segLabel} / div`,
    '72', '1',
    '11', f(x + totalW / 2), '21', f(y - 2.5 - labelH - 1),
  )

  return parts
}

// ─── Main Generator ──────────────────────────────────────────────────────────

/**
 * Generate a professional traverse plan DXF file.
 *
 * Uses the `dxf-writer` library for the core drawing, and appends raw DXF
 * strings for the title block, north arrow, scale bar, grid, and border
 * (following the `dxfSheetLayout.ts` pattern for maximum CAD compatibility).
 *
 * The resulting DXF is fully compatible with AutoCAD, LibreCAD, DraftSight,
 * and QCAD.
 *
 * @param options - Traverse data and project metadata
 * @returns Complete DXF file as a string
 */
export function generateTraverseDXF(options: TraverseDXFOptions): string {
  const {
    stations,
    legs,
    misclosure,
    projectInfo,
    sheetSize = 'A3',
    scale: userScale,
    gridInterval = 1000,
  } = options

  // ── Compute scale ───────────────────────────────────────────────────────
  const scale = userScale ?? computeAutoScale(stations, sheetSize)

  // ── Build station coordinate maps ────────────────────────────────────────
  const adjMap = buildStationMap(stations)      // adjusted (or raw if no adj)
  const rawMap = new Map<string, { e: number; n: number }>()
  for (const s of stations) {
    rawMap.set(s.name, { e: s.easting, n: s.northing })
  }

  // ── Compute coordinate extents ──────────────────────────────────────────
  let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity
  for (const s of stations) {
    const e = s.adjustedEasting ?? s.easting
    const n = s.adjustedNorthing ?? s.northing
    if (e < minE) minE = e
    if (e > maxE) maxE = e
    if (n < minN) minN = n
    if (n > maxN) maxN = n
  }

  // Add padding for labels and markers
  const padding = Math.max((maxE - minE) * 0.1, 10)
  minE -= padding; maxE += padding
  minN -= padding; maxN += padding

  // ── Create dxf-writer Drawing ───────────────────────────────────────────
  const drawing = new Drawing()
  drawing.setUnits('Meters')

  // Register standard layers from dxfLayers.ts
  initialiseSokDXFLayers(drawing)

  // Register traverse-specific layers
  drawing.addLayer('CONTROL_POINTS', ACI.MAGENTA, 'CONTINUOUS')
  drawing.addLayer('CONTROL_LABELS', ACI.WHITE, 'CONTINUOUS')
  drawing.addLayer('TRAVERSE_RAW', ACI.RED, 'DASHED')
  drawing.addLayer('TRAVERSE_ADJUSTED', ACI.GREEN, 'CONTINUOUS')
  drawing.addLayer('PARCEL_BOUNDARY', ACI.YELLOW, 'CONTINUOUS')
  drawing.addLayer('GRID', ACI.GREY, 'DASHED')
  drawing.addLayer('TITLE_BLOCK', ACI.WHITE, 'CONTINUOUS')
  drawing.addLayer('BORDER', ACI.WHITE, 'CONTINUOUS')

  // Register line types
  drawing.addLineType('DASHED', 'Dashed', [-1.0, 0.5])
  drawing.addLineType('DASHDOT', 'DashDot', [-2.0, 0.5, 0.1, 0.5])

  // ── Draw Coordinate Grid ───────────────────────────────────────────────
  drawing.setActiveLayer('GRID')
  const startE = Math.floor(minE / gridInterval) * gridInterval
  const startN = Math.floor(minN / gridInterval) * gridInterval

  for (let e = startE; e <= maxE; e += gridInterval) {
    drawing.drawLine(e, minN, e, maxN)
  }
  for (let n = startN; n <= maxN; n += gridInterval) {
    drawing.drawLine(minE, n, maxE, n)
  }

  // Grid labels
  drawing.setActiveLayer('CONTROL_LABELS')
  for (let e = startE; e <= maxE; e += gridInterval) {
    drawing.drawText(
      e, minN - LABEL_HEIGHT * 1.2,
      COORD_LABEL_HEIGHT, 0, String(e),
      'center', 'top',
    )
    drawing.drawText(
      e, maxN + COORD_LABEL_HEIGHT * 0.5,
      COORD_LABEL_HEIGHT, 0, String(e),
      'center', 'baseline',
    )
  }
  for (let n = startN; n <= maxN; n += gridInterval) {
    drawing.drawText(
      minE - LABEL_HEIGHT * 0.5, n,
      COORD_LABEL_HEIGHT, 90, String(n),
      'right', 'middle',
    )
    drawing.drawText(
      maxE + COORD_LABEL_HEIGHT * 0.5, n,
      COORD_LABEL_HEIGHT, 90, String(n),
      'left', 'middle',
    )
  }

  // ── Draw Raw Traverse Lines (dashed, red) ───────────────────────────────
  drawing.setActiveLayer('TRAVERSE_RAW')
  for (const leg of legs) {
    const from = rawMap.get(leg.from)
    const to = rawMap.get(leg.to)
    if (!from || !to) continue
    drawing.drawLine(from.e, from.n, to.e, to.n)
  }

  // ── Draw Adjusted Traverse Lines (solid, green) ─────────────────────────
  const hasAdjusted = stations.some(s => s.adjustedEasting !== undefined)
  if (hasAdjusted) {
    drawing.setActiveLayer('TRAVERSE_ADJUSTED')
    for (const leg of legs) {
      const from = adjMap.get(leg.from)
      const to = adjMap.get(leg.to)
      if (!from || !to) continue
      drawing.drawLine(from.e, from.n, to.e, to.n)
    }
  }

  // ── Draw Parcel Boundary (closed polygon if traverse closes) ────────────
  const closes = legs.length >= 3 &&
    legs[0].from === legs[legs.length - 1].to
  if (closes && adjMap.size >= 3) {
    drawing.setActiveLayer('PARCEL_BOUNDARY')
    const orderedStations: [number, number][] = []
    // Follow legs order to construct polygon vertices
    const visited = new Set<string>()
    let current = legs[0].from
    for (let i = 0; i <= legs.length; i++) {
      if (visited.has(current)) break
      visited.add(current)
      const pt = adjMap.get(current)
      if (pt) orderedStations.push([pt.e, pt.n])
      // Find the next station
      const leg = legs.find(l => l.from === current)
      if (!leg) break
      current = leg.to
    }

    if (orderedStations.length >= 3) {
      drawing.drawPolyline(orderedStations, true)
    }
  }

  // ── Draw Control Point Markers (cross + circle) ─────────────────────────
  drawing.setActiveLayer('CONTROL_POINTS')
  for (const s of stations) {
    const e = s.adjustedEasting ?? s.easting
    const n = s.adjustedNorthing ?? s.northing

    // Cross marker
    drawing.drawLine(e - CROSS_SIZE, n, e + CROSS_SIZE, n)
    drawing.drawLine(e, n - CROSS_SIZE, e, n + CROSS_SIZE)

    // Circle
    drawing.drawCircle(e, n, CIRCLE_RADIUS)
  }

  // ── Draw Station Labels ─────────────────────────────────────────────────
  drawing.setActiveLayer('CONTROL_LABELS')
  for (const s of stations) {
    const e = s.adjustedEasting ?? s.easting
    const n = s.adjustedNorthing ?? s.northing

    // Station name
    drawing.drawText(
      e + CIRCLE_RADIUS + 1,
      n + CIRCLE_RADIUS + 1,
      LABEL_HEIGHT, 0, s.name,
    )

    // Coordinates label (E/N)
    const coordText = `E: ${e.toFixed(3)}  N: ${n.toFixed(3)}`
    drawing.drawText(
      e + CIRCLE_RADIUS + 1,
      n + CIRCLE_RADIUS + 1 - LABEL_HEIGHT * 1.5,
      COORD_LABEL_HEIGHT, 0, coordText,
    )
  }

  // ── Build dxf-writer core output ────────────────────────────────────────
  const coreDxf = drawing.toDxfString()

  // ── Build title block, north arrow, scale bar, border via raw DXF ──────
  const rawParts: string[] = []

  const [sheetW, sheetH] = SHEET_DIMS[sheetSize]
  const tbH = TB_HEIGHT[sheetSize]

  // Inner drawing area bounds (in mm)
  const innerLeft = INNER_MARGIN
  const innerBottom = INNER_MARGIN + tbH
  const innerRight = sheetW - INNER_MARGIN
  const innerTop = sheetH - INNER_MARGIN

  // ── Outer border ──
  rawParts.push(
    '0', 'LWPOLYLINE', '8', 'BORDER',
    '90', '4', '70', '1',
    '10', f(BORDER_INSET), '20', f(BORDER_INSET),
    '10', f(sheetW - BORDER_INSET), '20', f(BORDER_INSET),
    '10', f(sheetW - BORDER_INSET), '20', f(sheetH - BORDER_INSET),
    '10', f(BORDER_INSET), '20', f(sheetH - BORDER_INSET),
  )

  // ── Inner border ──
  rawParts.push(
    '0', 'LWPOLYLINE', '8', 'BORDER',
    '90', '4', '70', '1',
    '10', f(innerLeft), '20', f(innerBottom),
    '10', f(innerRight), '20', f(innerBottom),
    '10', f(innerRight), '20', f(innerTop),
    '10', f(innerLeft), '20', f(innerTop),
  )

  // ── Title Block ─────────────────────────────────────────────────────────
  const tbLeft = BORDER_INSET
  const tbRight = sheetW - BORDER_INSET
  const tbTop = INNER_MARGIN + tbH
  const tbBottom = BORDER_INSET

  // Title block outer rectangle
  rawParts.push(
    '0', 'LWPOLYLINE', '8', 'TITLE_BLOCK',
    '90', '4', '70', '1',
    '10', f(tbLeft), '20', f(tbBottom),
    '10', f(tbRight), '20', f(tbBottom),
    '10', f(tbRight), '20', f(tbTop),
    '10', f(tbLeft), '20', f(tbTop),
  )

  // Row divider (top ~45% vs bottom ~55%)
  const rowDivY = tbBottom + tbH * 0.45
  rawParts.push(
    '0', 'LINE', '8', 'TITLE_BLOCK',
    '10', f(tbLeft), '20', f(rowDivY),
    '11', f(tbRight), '21', f(rowDivY),
  )

  // Column dividers in top row
  const col1W = (tbRight - tbLeft) * 0.45
  const col2W = (tbRight - tbLeft) * 0.20
  const col3W = (tbRight - tbLeft) * 0.15
  const col4W = (tbRight - tbLeft) * 0.10
  const col1R = tbLeft + col1W
  const col2R = col1R + col2W
  const col3R = col2R + col3W
  const col4R = col3R + col4W

  for (const x of [col1R, col2R, col3R, col4R]) {
    rawParts.push(
      '0', 'LINE', '8', 'TITLE_BLOCK',
      '10', f(x), '20', f(rowDivY),
      '11', f(x), '21', f(tbTop),
    )
  }

  // Column dividers in bottom row
  const bCol1R = tbLeft + (tbRight - tbLeft) * 0.40
  const bCol2R = tbLeft + (tbRight - tbLeft) * 0.65
  for (const x of [bCol1R, bCol2R]) {
    rawParts.push(
      '0', 'LINE', '8', 'TITLE_BLOCK',
      '10', f(x), '20', f(tbBottom),
      '11', f(x), '21', f(rowDivY),
    )
  }

  // ── Title Block Text ────────────────────────────────────────────────────
  const isLarge = sheetSize === 'A0' || sheetSize === 'A1'
  const titleH = isLarge ? 5 : 3.5
  const subtitleH = isLarge ? 3 : 2.5
  const bodyH = isLarge ? 2.5 : 2
  const smallH = isLarge ? 2 : 1.8

  // Helper: centred text
  function addT(layer: string, text: string, x: number, y: number, h: number) {
    rawParts.push(
      '0', 'TEXT', '8', layer,
      '10', f(x), '20', f(y), '30', f(0),
      '40', f(h),
      '1', text,
      '72', '1',
      '11', f(x), '21', f(y), '31', f(0),
    )
  }

  // Top row — Col 1: Republic of Kenya / Project name
  addT('TITLE_BLOCK', 'REPUBLIC OF KENYA',
    (tbLeft + col1R) / 2, rowDivY + tbH * 0.65, subtitleH)
  addT('TITLE_BLOCK', projectInfo.name,
    (tbLeft + col1R) / 2, rowDivY + tbH * 0.30, titleH)
  addT('TITLE_BLOCK', `LR No: ${projectInfo.lrNumber}`,
    (tbLeft + col1R) / 2, rowDivY + tbH * 0.08, bodyH)

  // Top row — Col 2: Scale
  addT('TITLE_BLOCK', `SCALE 1:${scale}`,
    (col1R + col2R) / 2, rowDivY + tbH * 0.50, subtitleH)
  addT('TITLE_BLOCK', 'METRIC',
    (col1R + col2R) / 2, rowDivY + tbH * 0.20, smallH)

  // Top row — Col 3: Coordinate System
  addT('TITLE_BLOCK', 'COORD SYSTEM',
    (col2R + col3R) / 2, rowDivY + tbH * 0.60, smallH)
  const cs = projectInfo.datum || 'Arc 1960 / UTM Zone 37S'
  addT('TITLE_BLOCK', cs,
    (col2R + col3R) / 2, rowDivY + tbH * 0.25, bodyH)

  // Top row — Col 4: Sheet / Revision
  addT('TITLE_BLOCK', 'Sheet 1 of 1',
    (col3R + col4R) / 2, rowDivY + tbH * 0.40, bodyH)

  // Top row — Col 5: METARDU branding
  addT('TITLE_BLOCK', 'METARDU',
    (col4R + tbRight) / 2, rowDivY + tbH * 0.60, bodyH)
  addT('TITLE_BLOCK', 'Traverse Plan',
    (col4R + tbRight) / 2, rowDivY + tbH * 0.35, smallH)

  // Bottom row text
  const botMidY = (tbBottom + rowDivY) / 2
  const botTopY = rowDivY - tbH * 0.12
  const botBotY = tbBottom + tbH * 0.12

  // Bottom Col A: Surveyor
  addT('TITLE_BLOCK', 'Licensed Surveyor:',
    (tbLeft + bCol1R) / 2, botTopY, smallH)
  addT('TITLE_BLOCK', projectInfo.surveyor || '—',
    (tbLeft + bCol1R) / 2, botMidY, bodyH)

  // Bottom Col B: County
  addT('TITLE_BLOCK', 'County:',
    (bCol1R + bCol2R) / 2, botTopY, smallH)
  addT('TITLE_BLOCK', projectInfo.county || '—',
    (bCol1R + bCol2R) / 2, botMidY, bodyH)

  // Bottom Col C: Date + misclosure
  addT('TITLE_BLOCK', `Date: ${formatPlanDate(new Date())}`,
    (bCol2R + tbRight) / 2, botTopY, bodyH)

  // Misclosure info
  if (misclosure) {
    const miscText = `Misclosure: L=${misclosure.linear.toFixed(4)}m  1:${misclosure.precisionRatio.toFixed(0)}`
    addT('TITLE_BLOCK', miscText,
      (bCol2R + tbRight) / 2, botMidY, smallH)
  }

  addT('TITLE_BLOCK', 'As per Kenya Survey Regulations 1994',
    (bCol2R + tbRight) / 2, botBotY, smallH)

  // ── North Arrow ─────────────────────────────────────────────────────────
  const arrowX = innerRight - NORTH_ARROW_SIZE * 1.5
  const arrowY = innerTop - NORTH_ARROW_SIZE * 1.5
  rawParts.push(...buildNorthArrow(arrowX, arrowY))

  // ── Scale Bar ───────────────────────────────────────────────────────────
  rawParts.push(...buildScaleBar(innerLeft + 10, innerBottom + 8, scale, sheetSize))

  // ── Traverse Summary Table (raw DXF text above title block) ─────────────
  const summaryY = innerBottom + 25
  addT('CONTROL_LABELS', 'TRAVERSE SUMMARY', innerLeft + 5, summaryY + 18, subtitleH)
  addT('CONTROL_LABELS', `Stations: ${stations.length}  |  Legs: ${legs.length}`,
    innerLeft + 5, summaryY + 14, bodyH)
  if (misclosure) {
    addT('CONTROL_LABELS',
      `Angular Misclosure: ${formatBearingDMS(misclosure.angular)}`,
      innerLeft + 5, summaryY + 10, bodyH)
    addT('CONTROL_LABELS',
      `Linear Misclosure: ${misclosure.linear.toFixed(4)} m`,
      innerLeft + 5, summaryY + 6, bodyH)
    addT('CONTROL_LABELS',
      `Precision Ratio: 1 : ${misclosure.precisionRatio.toFixed(0)}`,
      innerLeft + 5, summaryY + 2, bodyH)
  }

  // ── Merge raw entities into the dxf-writer output ───────────────────────
  // Insert before EOF in the dxf-writer output
  const eofMarker = '0\nEOF'
  const eofIdx = coreDxf.lastIndexOf(eofMarker)
  if (eofIdx !== -1) {
    return (
      coreDxf.substring(0, eofIdx) +
      rawParts.join('\n') + '\n' +
      coreDxf.substring(eofIdx)
    )
  }

  // Fallback: append
  return coreDxf + '\n' + rawParts.join('\n') + '\n0\nEOF\n'
}

/**
 * Initialise standard DXF layers on a dxf-writer Drawing instance.
 * Re-exports the standard layer definitions from dxfLayers.ts and also
 * registers traverse-specific layers.
 * @deprecated Use initialiseSokDXFLayers() from dxfLayers.ts instead.
 */
function initialiseDXFLayers(drawing: Drawing): void {
  initialiseSokDXFLayers(drawing)
}

/**
 * Feedback collection system for beta testing.
 *
 * Collects user feedback, errors, and usage data into sessionStorage
 * so the FeedbackWidget can package and submit them together.
 */

export type FeedbackCategory = 'bug' | 'feature' | 'general' | 'performance'

export interface FeedbackEntry {
  id: string
  type: FeedbackCategory
  message: string
  email?: string
  pageUrl: string
  timestamp: string
  metadata?: {
    userAgent: string
    screenWidth: number
    screenHeight: number
    language: string
    connectionType?: string
  }
  screenshotDataUrl?: string
  errorEntries?: CollectedError[]
}

export interface CollectedError {
  message: string
  stack?: string
  componentStack?: string
  url: string
  timestamp: string
}

const STORAGE_KEY_ERRORS = 'metardu_feedback_errors'
const STORAGE_KEY_FEEDBACK = 'metardu_feedback_submitted'
const MAX_STORED_ERRORS = 20

/** Generate a short unique ID */
function uid(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8)
}

/** Collect device metadata */
function collectMetadata() {
  if (typeof window === 'undefined') return undefined
  const nav = navigator as Navigator & { connection?: { effectiveType?: string } }
  return {
    userAgent: navigator.userAgent,
    screenWidth: window.screen.width,
    screenHeight: window.screen.height,
    language: navigator.language,
    connectionType: nav.connection?.effectiveType,
  }
}

/** Store a caught error for later reporting */
export function captureError(error: Error) {
  try {
    const entries: CollectedError[] = JSON.parse(
      sessionStorage.getItem(STORAGE_KEY_ERRORS) || '[]'
    )
    entries.push({
      message: error.message,
      stack: error.stack?.slice(0, 500),
      url: typeof window !== 'undefined' ? window.location.href : '',
      timestamp: new Date().toISOString(),
    })
    sessionStorage.setItem(
      STORAGE_KEY_ERRORS,
      JSON.stringify(entries.slice(-MAX_STORED_ERRORS))
    )
  } catch {
    // sessionStorage may be unavailable
  }
}

/** Retrieve all stored errors and clear them */
export function drainStoredErrors(): CollectedError[] {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY_ERRORS)
    sessionStorage.removeItem(STORAGE_KEY_ERRORS)
    return raw ? JSON.parse(raw) : []
  } catch {
    return []
  }
}

/** Record that feedback was submitted (for rate-limiting) */
export function markFeedbackSubmitted() {
  try {
    sessionStorage.setItem(STORAGE_KEY_FEEDBACK, new Date().toISOString())
  } catch {
    // ignore
  }
}

/** Check if user submitted feedback recently (within 30s) */
export function canSubmitFeedback(): boolean {
  try {
    const last = sessionStorage.getItem(STORAGE_KEY_FEEDBACK)
    if (!last) return true
    return Date.now() - new Date(last).getTime() > 30_000
  } catch {
    return true
  }
}

/** Build a complete feedback payload */
export function buildFeedbackPayload(
  type: FeedbackCategory,
  message: string,
  email?: string,
  screenshotDataUrl?: string
): FeedbackEntry {
  return {
    id: uid(),
    type,
    message,
    email,
    pageUrl: typeof window !== 'undefined' ? window.location.href : '',
    timestamp: new Date().toISOString(),
    metadata: collectMetadata(),
    screenshotDataUrl,
    errorEntries: drainStoredErrors(),
  }
}

/**
 * Attempt to capture a screenshot of the current page using native browser APIs.
 * Falls back to null if unavailable.
 */
export async function captureScreenshot(): Promise<string | null> {
  if (typeof window === 'undefined') return null

  // Try html2canvas if available (may be loaded dynamically)
  try {
    const mod = await import('html2canvas' as string).catch(() => null)
    if (mod) {
      const canvas = await mod.default(document.body, {
        backgroundColor: '#0a0a0a',
        scale: 0.5,
        logging: false,
        useCORS: true,
      })
      return canvas.toDataURL('image/jpeg', 0.6)
    }
  } catch {
    // html2canvas not available
  }

  return null
}

/** Log feedback to console (fallback when no backend is available).
 *  SECURITY: Does NOT log email or full user agent — those are PII.
 *  Logs only type, id, message length, and timestamp. */
export function logFeedbackToConsole(entry: FeedbackEntry) {
  console.warn(`[METARDU Feedback] type=${entry.type} id=${entry.id} msgLen=${entry.message.length} ts=${entry.timestamp}`)
}

import { FieldProject, FieldExportOptions } from '@/types/field';

export function projectToGeoJSON(project: FieldProject): GeoJSON.FeatureCollection {
  const features: GeoJSON.Feature[] = [];

  project.beacons.forEach(b => {
    features.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [b.coordinate.lng, b.coordinate.lat] },
      properties: {
        label: b.label,
        beaconType: b.beaconType,
        notes: b.notes ?? '',
        capturedAt: new Date(b.capturedAt).toISOString(),
      },
    });
  });

  project.parcels.forEach(p => {
    if (p.walkPoints.length < 3) return;
    const coords = p.walkPoints.map(wp => [wp.coordinate.lng, wp.coordinate.lat]);
    coords.push(coords[0]); // close ring
    features.push({
      type: 'Feature',
      geometry: { type: 'Polygon', coordinates: [coords] },
      properties: {
        label: p.label,
        areaM2: p.computedAreaM2,
        areaHa: p.computedAreaM2 ? (p.computedAreaM2 / 10000).toFixed(4) : null,
        perimeterM: p.computedPerimeterM,
      },
    });
  });

  return { type: 'FeatureCollection', features };
}

function escapeXml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

export function exportToKML(project: FieldProject): string {
  const lines: string[] = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<kml xmlns="http://www.opengis.net/kml/2.2">',
    '<Document>',
    `  <name>${escapeXml(project.name)}</name>`,
    '  <description>Field data exported from Metardu</description>',
    '',
    '  <!-- Beacon Styles -->',
    '  <Style id="beaconStyle">',
    '    <IconStyle><color>ff00aaff</color><scale>1.2</scale>',
    '      <Icon><href>http://maps.google.com/mapfiles/kml/paddle/ylw-circle.png</href></Icon>',
    '    </IconStyle>',
    '    <LabelStyle><color>ff00aaff</color><scale>0.9</scale></LabelStyle>',
    '  </Style>',
    '  <Style id="parcelStyle">',
    '    <LineStyle><color>ff00cc44</color><width>2</width></LineStyle>',
    '    <PolyStyle><color>4400cc44</color></PolyStyle>',
    '  </Style>',
    '',
  ];

  // Beacons folder
  if (project.beacons.length > 0) {
    lines.push('  <Folder>');
    lines.push('    <name>Beacons</name>');
    project.beacons.forEach(b => {
      lines.push('    <Placemark>');
      lines.push(`      <name>${escapeXml(b.label)}</name>`);
      lines.push(`      <description>Type: ${b.beaconType}${b.notes ? '\n' + escapeXml(b.notes) : ''}\nAccuracy: ±${b.coordinate.accuracy?.toFixed(1) ?? '?'}m\nCaptured: ${new Date(b.capturedAt).toISOString()}</description>`);
      lines.push('      <styleUrl>#beaconStyle</styleUrl>');
      lines.push(`      <Point><coordinates>${b.coordinate.lng},${b.coordinate.lat},${b.coordinate.altitude ?? 0}</coordinates></Point>`);
      lines.push('    </Placemark>');
    });
    lines.push('  </Folder>');
  }

  // Parcels folder
  if (project.parcels.length > 0) {
    lines.push('  <Folder>');
    lines.push('    <name>Parcels</name>');
    project.parcels.forEach(p => {
      if (p.walkPoints.length < 3) return;
      const coordStr = p.walkPoints
        .map(wp => `${wp.coordinate.lng},${wp.coordinate.lat},${wp.coordinate.altitude ?? 0}`)
        .join(' ');
      // Close the ring
      const first = p.walkPoints[0];
      const closed = coordStr + ` ${first.coordinate.lng},${first.coordinate.lat},${first.coordinate.altitude ?? 0}`;

      lines.push('    <Placemark>');
      lines.push(`      <name>${escapeXml(p.label)}</name>`);
      lines.push(`      <description>Area: ${p.computedAreaM2 ? (p.computedAreaM2 / 10000).toFixed(4) + ' ha' : 'N/A'}\nPerimeter: ${p.computedPerimeterM?.toFixed(1) ?? 'N/A'} m\nPoints: ${p.walkPoints.length}</description>`);
      lines.push('      <styleUrl>#parcelStyle</styleUrl>');
      lines.push('      <Polygon>');
      lines.push('        <outerBoundaryIs><LinearRing>');
      lines.push(`          <coordinates>${closed}</coordinates>`);
      lines.push('        </LinearRing></outerBoundaryIs>');
      lines.push('      </Polygon>');
      lines.push('    </Placemark>');
    });
    lines.push('  </Folder>');
  }

  lines.push('</Document>');
  lines.push('</kml>');
  return lines.join('\n');
}

export function exportToCSV(project: FieldProject): string {
  const rows: string[] = ['Label,Latitude,Longitude,Altitude,Accuracy,Type,Notes,CapturedAt'];
  project.beacons.forEach(b => {
    rows.push([
      b.label,
      b.coordinate.lat.toFixed(8),
      b.coordinate.lng.toFixed(8),
      b.coordinate.altitude?.toFixed(3) ?? '',
      b.coordinate.accuracy?.toFixed(2) ?? '',
      b.beaconType,
      `"${(b.notes ?? '').replace(/"/g, '""')}"`,
      new Date(b.capturedAt).toISOString(),
    ].join(','));
  });
  return rows.join('\n');
}

export function downloadBlob(content: string, filename: string, mime: string): void {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

/**
 * Field Session Manager — orchestrates the field data collection workflow
 *
 * Ties together: instrumentStore (connection) + fieldBookDB (persistence)
 * + liveToleranceChecker (QC) + syncQueue (sync) + stakeout (navigation)
 *
 * Works offline-first: all measurements saved locally, synced when online.
 */

import { useInstrumentStore } from '@/stores/instrumentStore'
import { checkTolerance, type ToleranceCheckResult } from '@/lib/survey/liveToleranceChecker'

// ─── Types ──────────────────────────────────────────────────────────────────

export type SurveyType = 'cadastral' | 'engineering' | 'topographic' | 'control' | 'leveling'
export type InstrumentType = 'total_station' | 'gnss_rover' | 'gnss_static' | 'level'
export type MeasurementMode = 'traverse' | 'radiation' | 'stakeout' | 'leveling' | 'walk'

export interface StationSetup {
  stationName: string
  instrumentHeight: number
  targetHeight: number
  backsightStation?: string
  backsightBearing?: { deg: number; min: number; sec: number }
  temperature?: number
  pressure?: number
  isControlPoint: boolean
  easting?: number
  northing?: number
  elevation?: number
}

export interface FieldMeasurement {
  id: string
  timestamp: number
  pointId: string
  stationFrom: string
  stationTo?: string
  // GNSS observations (from StreamedPoint)
  latitude?: number
  longitude?: number
  elevation?: number
  fixQuality?: string
  satellites?: number
  hdop?: number
  // Total station observations (from GSI parser — future)
  slopeDistance?: number
  horizontalAngle?: { deg: number; min: number; sec: number }
  verticalAngle?: { deg: number; min: number; sec: number }
  // Reduced coordinates
  easting?: number
  northing?: number
  // Metadata
  instrumentType: InstrumentType
  mode: MeasurementMode
  notes?: string
  synced: boolean
}

export interface FieldSessionState {
  projectId: string
  surveyType: SurveyType
  setup: StationSetup | null
  measurements: FieldMeasurement[]
  stakeoutTarget: { easting: number; northing: number; elevation: number } | null
  toleranceStatus: ToleranceCheckResult | null
  isOnline: boolean
  isSyncing: boolean
  pendingSyncCount: number
  lastSyncAt: number | null
}

// ─── Field Session Class ────────────────────────────────────────────────────

class FieldSession {
  private state: FieldSessionState
  private listeners: Set<(state: FieldSessionState) => void> = new Set()

  constructor(projectId: string, surveyType: SurveyType) {
    this.state = {
      projectId,
      surveyType,
      setup: null,
      measurements: [],
      stakeoutTarget: null,
      toleranceStatus: null,
      isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
      isSyncing: false,
      pendingSyncCount: 0,
      lastSyncAt: null,
    }
  }

  subscribe = (listener: (state: FieldSessionState) => void): (() => void) => {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  getSnapshot = (): FieldSessionState => this.state

  private setState(updates: Partial<FieldSessionState>) {
    this.state = { ...this.state, ...updates }
    this.listeners.forEach(l => l(this.state))
  }

  // ─── Station Setup ────────────────────────────────────────────────────────

  setupStation(setup: StationSetup) {
    this.setState({ setup })
  }

  isReady(): boolean {
    return this.state.setup !== null
  }

  // ─── Measurement Capture ──────────────────────────────────────────────────

  /**
   * Capture a measurement from the connected instrument.
   * Reads the latest reading from the instrument store and saves it.
   */
  async captureMeasurement(params: {
    pointId: string
    stationTo?: string
    targetHeight?: number
    notes?: string
  }): Promise<FieldMeasurement | null> {
    if (!this.state.setup) {
      console.warn('[field-session] Cannot capture — station not set up')
      return null
    }

    const instrumentStore = useInstrumentStore.getState()
    const latestPoint = instrumentStore.latestPoint

    if (!latestPoint) {
      console.warn('[field-session] No instrument reading available')
      return null
    }

    // Determine instrument type from the reading source
    const instrumentType: InstrumentType = latestPoint.source === 'nmea'
      ? 'gnss_rover'
      : latestPoint.source === 'gsi'
        ? 'total_station'
        : 'gnss_rover'

    // Build the measurement from the StreamedPoint
    const measurement: FieldMeasurement = {
      id: `obs-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      timestamp: Date.now(),
      pointId: params.pointId,
      stationFrom: this.state.setup.stationName,
      stationTo: params.stationTo,
      // GNSS fields (from StreamedPoint)
      latitude: latestPoint.latitude,
      longitude: latestPoint.longitude,
      elevation: latestPoint.elevation ?? undefined,
      fixQuality: latestPoint.quality != null
        ? (latestPoint.quality >= 4 ? 'fixed' : latestPoint.quality >= 2 ? 'float' : 'single')
        : undefined,
      satellites: latestPoint.satellites,
      hdop: latestPoint.hdop,
      // Reduced coordinates (StreamedPoint has easting/northing)
      easting: latestPoint.easting,
      northing: latestPoint.northing,
      // Metadata
      instrumentType,
      mode: this.state.surveyType === 'leveling' ? 'leveling' : 'traverse',
      notes: params.notes,
      synced: false,
    }

    // Save to IndexedDB (offline-first)
    try {
      const { saveObservation } = await import('@/lib/offline/fieldBookDB')
      await saveObservation({
        id: measurement.id,
        projectId: this.state.projectId,
        surveyType: measurement.mode as 'traverse' | 'leveling' | 'topo' | 'gnss' | 'hydro' | 'mining',
        station: measurement.stationFrom,
        backsight: this.state.setup.backsightStation,
        foresight: measurement.stationTo,
        // GNSS fields
        latitude: measurement.latitude,
        longitude: measurement.longitude,
        // Coordinates
        easting: measurement.easting,
        northing: measurement.northing,
        elevation: measurement.elevation,
        // Metadata
        notes: measurement.notes,
        createdAt: new Date(measurement.timestamp).toISOString(),
        syncedAt: null,
      })
    } catch (err) {
      console.error('[field-session] Failed to save offline:', err)
    }

    // Add to session state
    const measurements = [...this.state.measurements, measurement]
    this.setState({ measurements, pendingSyncCount: this.state.pendingSyncCount + 1 })

    // Trigger haptic feedback (mobile)
    this.hapticFeedback()

    return measurement
  }

  /**
   * Trigger haptic feedback on measurement capture.
   */
  private hapticFeedback() {
    if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
      navigator.vibrate(50)
    }
  }

  // ─── Stakeout ─────────────────────────────────────────────────────────────

  activateStakeout(target: { easting: number; northing: number; elevation: number }) {
    this.setState({ stakeoutTarget: target })
  }

  deactivateStakeout() {
    this.setState({ stakeoutTarget: null })
  }

  // ─── Sync ─────────────────────────────────────────────────────────────────

  async syncNow(): Promise<{ synced: number; failed: number }> {
    if (this.state.isSyncing) return { synced: 0, failed: 0 }

    this.setState({ isSyncing: true })

    try {
      const { syncObservations } = await import('@/lib/offline/fieldBookDB')
      const result = await syncObservations()

      const syncedCount = result.synced || 0
      const failedCount = result.failed || 0

      // Mark synced measurements
      const measurements = this.state.measurements.map(m => ({
        ...m,
        synced: m.synced || (syncedCount > 0 && !this.state.measurements.find(x => x.id === m.id && !x.synced)),
      }))

      this.setState({
        isSyncing: false,
        measurements,
        pendingSyncCount: Math.max(0, this.state.pendingSyncCount - syncedCount),
        lastSyncAt: Date.now(),
        isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
      })

      return { synced: syncedCount, failed: failedCount }
    } catch (err) {
      console.error('[field-session] Sync failed:', err)
      this.setState({ isSyncing: false })
      return { synced: 0, failed: this.state.pendingSyncCount }
    }
  }

  /**
   * Load existing measurements from IndexedDB (for session resume).
   */
  async loadMeasurements() {
    try {
      const { getObservations } = await import('@/lib/offline/fieldBookDB')
      const observations = await getObservations(this.state.projectId)
      const measurements: FieldMeasurement[] = observations.map((obs: any) => ({
        id: obs.id,
        timestamp: new Date(obs.createdAt).getTime(),
        pointId: '',
        stationFrom: obs.station || '',
        stationTo: obs.foresight || undefined,
        latitude: obs.latitude,
        longitude: obs.longitude,
        elevation: obs.elevation ?? undefined,
        easting: obs.easting,
        northing: obs.northing,
        instrumentType: obs.latitude ? 'gnss_rover' : 'total_station',
        mode: (obs.surveyType as MeasurementMode) || 'traverse',
        notes: obs.notes,
        synced: obs.syncedAt != null,
      }))
      this.setState({
        measurements,
        pendingSyncCount: measurements.filter(m => !m.synced).length,
      })
    } catch (err) {
      console.warn('[field-session] Failed to load measurements:', err)
    }
  }

  /**
   * Clear all measurements.
   */
  clearMeasurements() {
    this.setState({ measurements: [], pendingSyncCount: 0, toleranceStatus: null })
  }
}

// ─── Session Registry ───────────────────────────────────────────────────────

const sessions = new Map<string, FieldSession>()

export function getFieldSession(projectId: string, surveyType: SurveyType = 'cadastral'): FieldSession {
  const key = `${projectId}:${surveyType}`
  if (!sessions.has(key)) {
    sessions.set(key, new FieldSession(projectId, surveyType))
  }
  return sessions.get(key)!
}

// ─── React Hook ─────────────────────────────────────────────────────────────

export function useFieldSession(options: {
  projectId: string
  surveyType?: SurveyType
}): FieldSession {
  const { projectId, surveyType = 'cadastral' } = options
  return getFieldSession(projectId, surveyType)
}

// pdfjs-dist v5 API — note: GlobalWorkerOptions must be set before getDocument()
import type { PDFDocumentProxy, PDFPageProxy } from 'pdfjs-dist';
import { GeoPDFLayer } from '@/types/field';

let pdfjsLib: typeof import('pdfjs-dist') | null = null;

async function getPDFJS() {
  if (pdfjsLib) return pdfjsLib;
  pdfjsLib = await import('pdfjs-dist');
  // v5: worker is bundled separately — point to the CDN build
  pdfjsLib.GlobalWorkerOptions.workerSrc =
    `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;
  return pdfjsLib;
}

export interface RenderedPDF {
  dataUrl: string;   // PNG base64
  widthPx: number;
  heightPx: number;
}

export async function renderPDFPageToDataURL(
  file: File,
  pageNumber = 1,
  scale = 2.0            // 2x for retina — keeps map overlay sharp at zoom
): Promise<RenderedPDF> {
  const lib = await getPDFJS();
  const arrayBuffer = await file.arrayBuffer();
  const pdf: PDFDocumentProxy = await lib.getDocument({ data: arrayBuffer }).promise;
  const page: PDFPageProxy = await pdf.getPage(pageNumber);
  const viewport = page.getViewport({ scale });

  const canvas = document.createElement('canvas');
  canvas.width = viewport.width;
  canvas.height = viewport.height;
  const ctx = canvas.getContext('2d')!;

  await page.render({ canvasContext: ctx, viewport } as any).promise;

  return {
    dataUrl: canvas.toDataURL('image/png'),
    widthPx: viewport.width,
    heightPx: viewport.height,
  };
}

// Build an OpenLayers ImageStatic layer from a GeoPDFLayer with 4 GCPs.
// GCPs define the bounding box: min/max lat/lng of the 4 corners.
// OL imports are done via require() since this function is only called
// inside MapViewer's browser-only useEffect via dynamic import.
export function buildOLGeoPDFLayer(layer: GeoPDFLayer) {
  const { default: ImageLayer } = require('ol/layer/Image');
  const { default: ImageStatic } = require('ol/source/ImageStatic');
  const { transformExtent } = require('ol/proj');

  const lats = layer.gcps.map((g: any) => g.lat);
  const lngs = layer.gcps.map((g: any) => g.lng);
  const extent4326: [number, number, number, number] = [
    Math.min(...lngs),
    Math.min(...lats),
    Math.max(...lngs),
    Math.max(...lats),
  ];
  // Convert extent from WGS84 → EPSG:3857 for OpenLayers
  const extent3857 = transformExtent(extent4326, 'EPSG:4326', 'EPSG:3857');

  return new ImageLayer({
    source: new ImageStatic({
      url: layer.dataUrl,
      imageExtent: extent3857,
      projection: 'EPSG:3857',
    }),
    opacity: 0.75,
    visible: layer.visible,
  });
}

import { MBTilesSession } from '@/types/field';

export async function uploadMBTiles(file: File): Promise<MBTilesSession> {
  const form = new FormData();
  form.append('file', file);
  const res = await fetch('/api/field/mbtiles/upload', { method: 'POST', body: form });
  if (!res.ok) {
    const err = await res.json();
    throw new Error(err.error ?? 'Upload failed');
  }
  return res.json() as Promise<MBTilesSession>;
}

// buildOLMBTilesLayer is only called inside MapViewer useEffect (browser-only)
// so the OL imports are safe here — this function is dynamically imported
export function buildOLMBTilesLayer(session: MBTilesSession) {
  // Dynamic require to keep top-level clean for SSR
  const { default: XYZ } = require('ol/source/XYZ');
  const { default: TileLayer } = require('ol/layer/Tile');
  
  return new TileLayer({
    source: new XYZ({
      url: `/api/field/mbtiles/tiles/${session.key}/{z}/{x}/{y}`,
      minZoom: session.minZoom,
      maxZoom: session.maxZoom,
    }),
    opacity: 1.0,
  });
}

import JSZip from 'jszip';
import db from '@/lib/db';
import { computeDeedPlanGeometry, loadPreAdjustedFromDB } from './deedPlanGeometry';

export async function generateBoundaryShapefile(
  projectId: string
): Promise<Buffer> {
  const projectRes = await db.query(
    'SELECT name, utm_zone, hemisphere FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  if (!project) throw new Error('Project not found');

  // Use Bowditch-adjusted coordinates from traverse engine — single source of truth
  const preAdjusted = await loadPreAdjustedFromDB(projectId);
  const geom = await computeDeedPlanGeometry(projectId, {
    preAdjustedCoordinates: preAdjusted?.stations,
    preAdjustedClosure: preAdjusted?.closure,
  });

  const beacons = geom.stations.map((s, i) => ({
    name: s.station,
    e: s.easting,
    n: s.northing,
    beaconNo: s.beaconNo,
  }));

  const zip = new JSZip();

  const geoJson = {
    type: 'FeatureCollection',
    features: [{
      type: 'Feature',
      geometry: {
        type: 'Polygon',
        coordinates: [beacons.map((b: any) => [b.e, b.n]).concat([[beacons[0].e, beacons[0].n]])]
      },
      properties: {
        project: project.name,
        area_m2: geom.areaM2,
        area_ha: geom.areaHa,
        surveyed_date: new Date().toISOString().split('T')[0],
        rdm_compliant: true
      }
    }]
  };

  zip.file(`${project.name}_Boundary.geojson`, JSON.stringify(geoJson, null, 2));

  const zone = project.utm_zone || 37;
  const hemisphere = project.hemisphere || 'S';
  const prjContent = `PROJCS["Arc 1960 / UTM zone ${zone}${hemisphere}",GEOGCS["Arc 1960",DATUM["Arc_1960",SPHEROID["Clarke_1880_RGS",6378249.145,293.465]],PRIMEM["Greenwich",0],UNIT["degree",0.0174532925199433]],PROJECTION["Transverse_Mercator"],PARAMETER["latitude_of_origin",0],PARAMETER["central_meridian",${zone * 6 - 183}],PARAMETER["scale_factor",0.9996],PARAMETER["false_easting",500000],PARAMETER["false_northing",${hemisphere === 'S' ? 10000000 : 0}],UNIT["metre",1]]`;

  zip.file(`${project.name}_Boundary.prj`, prjContent);

  const blob = await zip.generateAsync({ type: 'nodebuffer' });
  return Buffer.from(blob);
}

import ExcelJS from 'exceljs';
import db from '@/lib/db';

export async function generateCoordinateSchedule(
  projectId: string
): Promise<Buffer> {

  const projectRes = await db.query(
    'SELECT name, survey_type, ref_no FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  const beaconsRes = await db.query(
    'SELECT * FROM project_beacons WHERE project_id = $1 ORDER BY beacon_no ASC',
    [projectId]
  );
  const beacons = beaconsRes.rows;

  const wb = new ExcelJS.Workbook();
  wb.creator = 'Metardu';

  const ws = wb.addWorksheet('Coordinate Schedule', {
    pageSetup: { paperSize: 9, orientation: 'portrait' },
  });

  ws.mergeCells('A1:G1');
  const title = ws.getCell('A1');
  title.value = `COORDINATE SCHEDULE — ${project?.name ?? 'Project'}`;
  title.font = { bold: true, size: 12, color: { argb: 'FF1E5064' } };
  title.alignment = { horizontal: 'center', vertical: 'middle' };
  ws.getRow(1).height = 24;

  ws.mergeCells('A2:D2');
  ws.getCell('A2').value = `Survey Type: ${project?.survey_type ?? '—'} | Ref: ${project?.ref_no ?? '—'}`;
  ws.mergeCells('E2:G2');
  ws.getCell('E2').value = `Date: ${new Date().toLocaleDateString('en-KE')}`;
  ws.getCell('E2').alignment = { horizontal: 'right' };

  const headers = ['Beacon No.', 'Easting (m)', 'Northing (m)', 'RL (m)', 'Description', 'Monument Type', 'Remark'];
  const headerRow = ws.addRow(headers);
  headerRow.eachCell((cell) => {
    cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E5064' } };
    cell.alignment = { horizontal: 'center' };
    cell.border = { top: { style: 'thin' }, bottom: { style: 'thin' }, left: { style: 'thin' }, right: { style: 'thin' } };
  });
  ws.getRow(3).height = 18;

  (beacons ?? []).forEach((beacon: Record<string, unknown>, idx: number) => {
    const row = ws.addRow([
      beacon.beacon_no,
      beacon.easting,
      beacon.northing,
      beacon.rl ?? '',
      beacon.description ?? '',
      beacon.monument_type ?? '',
      '',
    ]);

    if (idx % 2 === 0) {
      row.eachCell((cell) => {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF0F5F8' } };
      });
    }

    [2, 3, 4].forEach((colIdx) => {
      const cell = row.getCell(colIdx);
      cell.numFmt = '#,##0.000';
    });
  });

  ws.getColumn(1).width = 14;
  ws.getColumn(2).width = 16;
  ws.getColumn(3).width = 16;
  ws.getColumn(4).width = 12;
  ws.getColumn(5).width = 24;
  ws.getColumn(6).width = 18;
  ws.getColumn(7).width = 20;

  ws.views = [{ state: 'frozen', xSplit: 0, ySplit: 3, topLeftCell: 'A4', activeCell: 'A4' }];

  const buffer = await wb.xlsx.writeBuffer();
  return Buffer.from(buffer);
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import db from '@/lib/db';
import { computeDeedPlanGeometry, loadPreAdjustedFromDB, type PreAdjustedCoordinate, type PreAdjustedClosure } from './deedPlanGeometry';
import { renderBoundaryPlan, drawRevisionHistory, type RoadSegment } from './deedPlanRenderer';
import { addPageFooter } from './pdfTitleBlock';

const A3_W = 420;
const A3_H = 297;
const MARGIN = 8;
const PLAN_WIDTH = Math.round(A3_W * 0.63);
const SCHEDULE_X = PLAN_WIDTH + MARGIN;
const SCHEDULE_W = A3_W - PLAN_WIDTH - MARGIN * 1.5;

function getBeaconDescription(monument: string): { type: string; material: string; dimensions: string } {
