  doc.setDrawColor(0, 0, 0);
  doc.setLineWidth(0.4);
  doc.rect(SCHEDULE_X, certY, SCHEDULE_W, certH);

  doc.setFontSize(7);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
