  doc.setFontSize(6.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(30, 30, 30);

  let lineY = certY + 10;
  certText.forEach((line) => {
    doc.text(line, SCHEDULE_X + 3, lineY);
    lineY += 4;
  });

  const sigY = certY + certH - 10;
  doc.setLineWidth(0.2);
  doc.setDrawColor(0);
  doc.line(SCHEDULE_X + 3, sigY, SCHEDULE_X + SCHEDULE_W - 3, sigY);
  doc.setFontSize(6);
  doc.setTextColor(80);
  doc.text('Signature / Date', SCHEDULE_X + 3, sigY + 3.5);

  addPageFooter(doc, 1, 1, project.name ?? '');

  return Buffer.from(doc.output('arraybuffer'));
}

import db from '@/lib/db';
import { coordinateArea } from '@/lib/engine/area';
import { bowditchAdjustment } from '@/lib/engine/traverse';
import { bearingToString } from '@/lib/engine/angles';
import type { NamedPoint2D } from '@/lib/engine/types';
import { computeLineScaleFactor, computeUTMPointScaleFactor } from '@/lib/survey/adapter';
import type { LineScaleFactorResult } from '@/lib/survey/adapter';

export interface TraverseStation {
  station: string;
  bearing: number;
  distance: number;
  beaconNo?: string;
  monument?: string;
  markStatus?: string;
}

export interface AdjustedStation {
  station: string;
  easting: number;
  northing: number;
  beaconNo?: string;
  monument?: string;
  markStatus?: string;
}

export interface BearingLeg {
  from: string;
  to: string;
  bearing: string;
  distance: string;
}

export interface DeedPlanGeometry {
  stations: AdjustedStation[];
  bearingSchedule: BearingLeg[];
  areaM2: number;
  areaHa: number;
  areaAcres: number;
  misclosureMm: number;
  precisionRatio: string;
  closureStatus: 'PASS' | 'FAIL' | 'UNVERIFIED';
  minE: number;
  maxE: number;
  minN: number;
  maxN: number;
  /** Source of the coordinates — tracks whether pre-adjusted or independently computed */
  coordinateSource: 'pre_adjusted' | 'computed';
  /** Line scale factor for each boundary leg (survey engine, Simpson's rule) */
  lineScaleFactors?: Array<{
    from: string;
    to: string;
    scaleFactor: number;
    ppmFromUnity: number;
    gridDistance: number;
    ellipsoidalDistance: number;
  }>;
  /** UTM projection used for scale factor computation */
  projection?: 'UTM36S' | 'UTM37S';
}

/**
 * Pre-adjusted coordinates from an external source (e.g. traverse_coordinates
 * table, or a TraverseComputationResult). When provided to
 * computeDeedPlanGeometry(), the function skips independent Bowditch
 * computation and uses these coordinates directly — guaranteeing 100%
 * consistency with the traverse computation sheet.
 */
export interface PreAdjustedCoordinate {
  station: string;
  easting: number;
  northing: number;
  beaconNo?: string;
  monument?: string;
  markStatus?: string;
}

export interface PreAdjustedClosure {
  misclosureMm: number;
  precisionRatio: number;
}

export interface ComputeDeedPlanGeometryOptions {
  /**
   * Pre-adjusted traverse coordinates from an authoritative source.
   * When provided, computeDeedPlanGeometry() will use these coordinates
   * directly instead of recomputing from raw field book entries.
   * This ensures single-source-of-truth consistency with the traverse
   * computation sheet and all other output documents.
   */
  preAdjustedCoordinates?: PreAdjustedCoordinate[];
  /** Closure metrics corresponding to the pre-adjusted coordinates */
  preAdjustedClosure?: PreAdjustedClosure;
}

function parseBearing(raw: string | number): number {
  if (typeof raw === 'number') return raw;
  const dmsMatch = String(raw).match(/(\d+)[°\-\s](\d+)['\-\s](\d+\.?\d*)/);
  if (dmsMatch) {
    const [, d, m, s] = dmsMatch.map(Number);
    return d + m / 60 + s / 3600;
  }
  return parseFloat(String(raw)) || 0;
}


export async function computeDeedPlanGeometry(
  projectId: string,
  options?: ComputeDeedPlanGeometryOptions
): Promise<DeedPlanGeometry> {
  // ── Path A: Use pre-adjusted coordinates from an authoritative source ──
  // When the caller has already computed adjusted traverse coordinates (e.g.
  // from the traverse computation sheet or the traverse_coordinates table),
  // use them directly. This guarantees 100% consistency between all output
  // documents — the deed plan, computation sheet, Form C22, and DXF all
  // derive from the same adjusted coordinates.
  if (options?.preAdjustedCoordinates && options.preAdjustedCoordinates.length >= 3) {
    return buildFromPreAdjusted(options.preAdjustedCoordinates, options.preAdjustedClosure);
  }

  // ── Path B: Try to load pre-adjusted coordinates from the DB ──
  // If the project has a saved traverse with adjusted coordinates in the
  // traverse_coordinates table, use those instead of recomputing.
  const savedCoords = await loadPreAdjustedFromDB(projectId);
  if (savedCoords) {
    return buildFromPreAdjusted(savedCoords.stations, savedCoords.closure);
  }

  // ── Path C: Compute from raw field book entries (fallback) ──
  return computeFromFieldBook(projectId);
}

/**
 * Build DeedPlanGeometry from pre-adjusted coordinates.
 * Bearings and distances are RECOMPUTED from the adjusted coordinates to
 * ensure the bearing schedule is consistent with the coordinate schedule.
 */
function buildFromPreAdjusted(
  coords: PreAdjustedCoordinate[],
  closure?: PreAdjustedClosure
): DeedPlanGeometry {
  const adjusted: AdjustedStation[] = coords.map(c => ({
    station: c.station,
    easting: c.easting,
    northing: c.northing,
    beaconNo: c.beaconNo,
    monument: c.monument,
    markStatus: c.markStatus,
  }));

  // Compute area from adjusted coordinates (Shoelace formula)
  const pts = adjusted.map((s) => ({ easting: s.easting, northing: s.northing }));
  const areaResult = coordinateArea(pts);

  // Bearing schedule recomputed from adjusted positions — ensures consistency
  // Now includes grid scale factors from the survey engine (Simpson's rule)
  const projection: 'UTM36S' | 'UTM37S' = 'UTM37S'; // Default for Kenya
  const bearingSchedule: BearingLeg[] = adjusted.map((st, i) => {
    const next = adjusted[(i + 1) % adjusted.length];
    const dE = next.easting - st.easting;
    const dN = next.northing - st.northing;
    let brg = (Math.atan2(dE, dN) * 180) / Math.PI;
    if (brg < 0) brg += 360;
    const dist = Math.sqrt(dE ** 2 + dN ** 2);
    return {
      from: st.station,
      to: next.station,
      bearing: bearingToString(brg),
      distance: dist.toFixed(3),
    };
  });

  // Compute line scale factors using the survey engine's Simpson's rule
  const lineScaleFactors = adjusted.map((st, i) => {
    const next = adjusted[(i + 1) % adjusted.length];
    try {
      const sfResult = computeLineScaleFactor(
        st.easting, st.northing,
        next.easting, next.northing,
        projection
      );
      return {
        from: st.station,
        to: next.station,
        scaleFactor: sfResult.lineScaleFactor,
        ppmFromUnity: sfResult.ppmCorrection,
        gridDistance: sfResult.gridDistance,
        ellipsoidalDistance: sfResult.ellipsoidalDistance,
      };
    } catch {
      return {
        from: st.station,
        to: next.station,
        scaleFactor: 1.0,
        ppmFromUnity: 0,
        gridDistance: 0,
        ellipsoidalDistance: 0,
      };
    }
  });

  const eastings = adjusted.map((s) => s.easting);
  const northings = adjusted.map((s) => s.northing);

  const misclosureMm = closure?.misclosureMm ?? 0;
  const ratio = closure?.precisionRatio ?? Infinity;
  const precisionRatio = ratio === Infinity ? '1:∞' : `1:${Math.round(ratio).toLocaleString()}`;
  const closureStatus: 'PASS' | 'FAIL' | 'UNVERIFIED' =
    ratio >= 5000 ? 'PASS' : ratio > 0 && ratio < Infinity ? 'FAIL' : 'UNVERIFIED';

  return {
    stations: adjusted,
    bearingSchedule,
    areaM2: areaResult.areaSqm,
    areaHa: areaResult.areaHa,
    areaAcres: areaResult.areaAcres,
    misclosureMm,
    precisionRatio,
    closureStatus,
    minE: Math.min(...eastings),
    maxE: Math.max(...eastings),
    minN: Math.min(...northings),
    maxN: Math.max(...northings),
    coordinateSource: 'pre_adjusted',
    lineScaleFactors,
    projection,
  };
}

/**
 * Attempt to load pre-adjusted coordinates from the traverse_coordinates
 * table. Returns null if no saved traverse exists.
 *
 * Also queries the field book entries for beacon descriptions (monument type,
 * mark status, beacon number) so that the DeedPlanGeometry includes rich
 * beacon metadata — matching the behaviour of the external helper in
 * deedPlan.ts.
 */
export async function loadPreAdjustedFromDB(
  projectId: string
): Promise<{ stations: PreAdjustedCoordinate[]; closure: PreAdjustedClosure } | null> {
  try {
    // Find the most recent traverse for this project via parcels
    const traverseRes = await db.query(
      `SELECT pt.id, pt.linear_misclosure, pt.precision_ratio
       FROM parcel_traverses pt
       JOIN parcels p ON p.id = pt.parcel_id
       JOIN blocks b ON b.id = p.block_id
       WHERE b.project_id = $1
       ORDER BY pt.created_at DESC LIMIT 1`,
      [projectId]
    );

    if (traverseRes.rows.length === 0) return null;

    const traverse = traverseRes.rows[0];
    const traverseId = traverse.id;

    const coordsRes = await db.query(
      'SELECT station, easting, northing, rl FROM traverse_coordinates WHERE traverse_id = $1 ORDER BY station',
      [traverseId]
    );

    if (coordsRes.rows.length < 3) return null;

    // Also try to get beacon info from field book entries for richer metadata
    let beaconLookup = new Map<string, { beaconNo: string; monument: string; markStatus: string }>();
    try {
      const fbRes = await db.query(
        'SELECT station, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
        [projectId]
      );
      for (const row of fbRes.rows) {
        const raw = row.raw_data as Record<string, unknown> | null;
        if (row.station && raw) {
          beaconLookup.set(String(row.station), {
            beaconNo: String(raw.beacon_no ?? ''),
            monument: String(raw.monument_type ?? ''),
            markStatus: String(raw.mark_status ?? raw.monument_status ?? 'FOUND'),
          });
        }
      }
    } catch {
      // Field book table may not exist — proceed with defaults
    }

    const stations: PreAdjustedCoordinate[] = coordsRes.rows.map((c: Record<string, unknown>) => {
      const stn = String(c.station);
      const beacon = beaconLookup.get(stn);
      return {
        station: stn,
        easting: parseFloat(String(c.easting)),
        northing: parseFloat(String(c.northing)),
        beaconNo: beacon?.beaconNo || stn,
        monument: beacon?.monument || 'psc found',
        markStatus: beacon?.markStatus || 'FOUND',
      };
    });

    const closure: PreAdjustedClosure = {
      misclosureMm: parseFloat(String(traverse.linear_misclosure ?? 0)) * 1000,
      precisionRatio: parseFloat(String(traverse.precision_ratio ?? 0)) || Infinity,
    };

    return { stations, closure };
  } catch {
    // Table may not exist in all deployments — fall back gracefully
    return null;
  }
}

/**
 * Compute DeedPlanGeometry from raw field book entries using Bowditch
 * adjustment. This is the fallback path when no pre-adjusted coordinates
 * are available.
 */
async function computeFromFieldBook(projectId: string): Promise<DeedPlanGeometry> {
  const entriesRes = await db.query(
    'SELECT row_index, station, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
    [projectId]
  );
  const entries = entriesRes.rows;

  if (!entries || entries.length < 3) {
    throw new Error('Deed Plan requires at least 3 traverse stations. Add observations in the Field Book panel.');
  }

  const projectRes = await db.query(
    'SELECT boundary_data, utm_zone, hemisphere FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  const legs: TraverseStation[] = entries
    .map((e: { row_index: number; station: string; raw_data: Record<string, unknown> }) => ({
      station: String(e.station ?? e.raw_data?.station ?? ''),
      bearing: parseBearing(String(e.raw_data?.bearing ?? e.raw_data?.bs ?? 0)),
      distance: parseFloat(String(e.raw_data?.distance ?? e.raw_data?.hd ?? '0')) || 0,
      beaconNo: String(e.raw_data?.beacon_no ?? ''),
      monument: String(e.raw_data?.monument_type ?? ''),
      markStatus: String(e.raw_data?.mark_status ?? e.raw_data?.monument_status ?? 'FOUND'),
    }))
    .filter((l) => l.distance > 0);

  if (legs.length < 3) {
    throw new Error('Insufficient traverse data. Ensure bearing and distance are entered for each leg.');
  }

  // Use boundary seed as starting coordinate
  const seed = project?.boundary_data as { startE?: number; startN?: number } | null;
  const startE = seed?.startE ?? 0;
  const startN = seed?.startN ?? 0;

  // Build the traverse input for the engine's Bowditch adjustment
  // This ensures the deed plan uses the SAME adjusted coordinates as the
  // traverse computation sheet — single source of truth for all outputs.
  // Source: Ghilani & Wolf Ch.12 — Bowditch (Compass) Rule
  const startPoint: NamedPoint2D = { name: legs[0].station, easting: startE, northing: startN };
  const traversePoints: NamedPoint2D[] = legs.map(l => ({ name: l.station, easting: 0, northing: 0 }));

  const traverseResult = bowditchAdjustment({
    points: [startPoint, ...traversePoints],
    distances: legs.map(l => l.distance),
    bearings: legs.map(l => l.bearing),
    closingPoint: { easting: startE, northing: startN },
  });

  // Extract adjusted coordinates from the engine result
  const adjusted: AdjustedStation[] = traverseResult.legs.map((leg, i) => ({
    station: legs[i].station,
    easting: leg.adjEasting,
    northing: leg.adjNorthing,
    beaconNo: legs[i].beaconNo,
    monument: legs[i].monument,
    markStatus: legs[i].markStatus,
  }));

  // Compute area from adjusted coordinates (Shoelace formula)
  const pts = adjusted.map((s) => ({ easting: s.easting, northing: s.northing }));
  const areaResult = coordinateArea(pts);
  const areaM2 = areaResult.areaSqm;
  const areaHa = areaResult.areaHa;
  const areaAcres = areaResult.areaAcres;

  // Closure metrics from the engine result
  const misclosureMm = traverseResult.linearError * 1000;
  const ratio = traverseResult.precisionRatio;
  const precisionRatio = `1:${Math.round(ratio).toLocaleString()}`;
  const closureStatus: 'PASS' | 'FAIL' | 'UNVERIFIED' =
    ratio >= 5000 ? 'PASS' : ratio > 0 ? 'FAIL' : 'UNVERIFIED';

  // Bearing schedule from adjusted coordinates — bearings are recomputed from
  // the adjusted positions to ensure consistency with the coordinate schedule
  // Now includes grid scale factors from the survey engine (Simpson's rule)
  const projection: 'UTM36S' | 'UTM37S' = 'UTM37S'; // Default for Kenya
  const bearingSchedule: BearingLeg[] = adjusted.map((st, i) => {
    const next = adjusted[(i + 1) % adjusted.length];
    const dE = next.easting - st.easting;
    const dN = next.northing - st.northing;
    let brg = (Math.atan2(dE, dN) * 180) / Math.PI;
    if (brg < 0) brg += 360;
    const dist = Math.sqrt(dE ** 2 + dN ** 2);
    return {
      from: st.station,
      to: next.station,
      bearing: bearingToString(brg),
      distance: dist.toFixed(3),
    };
  });

  // Compute line scale factors using the survey engine's Simpson's rule
  const lineScaleFactors = adjusted.map((st, i) => {
    const next = adjusted[(i + 1) % adjusted.length];
    try {
      const sfResult = computeLineScaleFactor(
        st.easting, st.northing,
        next.easting, next.northing,
        projection
      );
      return {
        from: st.station,
        to: next.station,
        scaleFactor: sfResult.lineScaleFactor,
        ppmFromUnity: sfResult.ppmCorrection,
        gridDistance: sfResult.gridDistance,
        ellipsoidalDistance: sfResult.ellipsoidalDistance,
      };
    } catch {
      return {
        from: st.station,
        to: next.station,
        scaleFactor: 1.0,
        ppmFromUnity: 0,
        gridDistance: 0,
        ellipsoidalDistance: 0,
      };
    }
  });

  const eastings = adjusted.map((s) => s.easting);
  const northings = adjusted.map((s) => s.northing);

  return {
    stations: adjusted,
    bearingSchedule,
    areaM2,
    areaHa,
    areaAcres,
    misclosureMm,
    precisionRatio,
    closureStatus,
    minE: Math.min(...eastings),
    maxE: Math.max(...eastings),
    minN: Math.min(...northings),
    maxN: Math.max(...northings),
    coordinateSource: 'computed',
    lineScaleFactors,
    projection,
  };
}

import { createHash } from 'crypto';
import { jsPDF } from 'jspdf';
import { DeedPlanGeometry } from './deedPlanGeometry';
import { getRoadReserveWidth } from '../reports/surveyPlan/types';

interface PanelBounds {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Road segment descriptor for truncation line rendering */
export interface RoadSegment {
  /** Index of the boundary segment that abuts a road */
  segmentIndex: number;
  /** From point (easting, northing) */
  from: { easting: number; northing: number };
  /** To point (easting, northing) */
  to: { easting: number; northing: number };
}

/** Revision entry for the revision history table */
export interface RevisionEntry {
  rev: string;
  date: string;
  description: string;
  by: string;
}

/** Extended options for the boundary plan renderer */
export interface BoundaryPlanOptions {
  /** Road segments that abut the parcel — used for truncation lines */
  roadSegments?: RoadSegment[];
  /** Surveyor name for stamp area */
  surveyorName?: string;
  /** Surveyor licence number */
  surveyorLicence?: string;
  /** ISK registration number */
  iskRegNo?: string;
  /** Firm name */
  firmName?: string;
  /** Revision entries for history table */
  revisions?: RevisionEntry[];
  /** Road classification code (e.g. 'A', 'K', 'P') for road reserve width */
  roadClass?: string;
}

const MONUMENT_SIZE = 2.5;

function drawMonumentSymbol(doc: jsPDF, px: number, py: number, type: string) {
  const s = MONUMENT_SIZE;
  doc.setLineWidth(0.3);

  switch (type?.toLowerCase()) {
    case 'psc found':
      doc.setDrawColor(0);
      doc.circle(px, py, s, 'S');
      doc.setFillColor(0, 0, 0);
      doc.circle(px, py, 0.5, 'F');
      break;
    case 'psc set':
      doc.setFillColor(0, 0, 0);
      doc.circle(px, py, s, 'F');
      break;
    case 'ssc':
      doc.setDrawColor(0);
      doc.rect(px - s, py - s, s * 2, s * 2, 'S');
      break;
    case 'masonry nail':
      doc.setDrawColor(0);
      doc.line(px - s, py, px + s, py);
      doc.line(px, py - s, px, py + s);
      break;
    case 'indicatory':
      doc.setDrawColor(0);
      doc.lines([[s * 2, 0], [-s, s * 1.5], [-s, -s * 1.5]], px - s, py, [1, 1], 'S', true);
      break;
    case 'bm':
      doc.setDrawColor(0, 80, 160);
      doc.lines([[s, s], [s, -s], [-s, -s], [-s, s]], px, py - s, [1, 1], 'S', true);
      break;
    default:
      doc.setDrawColor(100);
      doc.circle(px, py, s * 0.8, 'S');
  }
}

function drawNorthArrow(doc: jsPDF, cx: number, cy: number) {
  const h = 10;
  const w = 3;
  doc.setFillColor(0, 0, 0);
  doc.setDrawColor(0);
  doc.setLineWidth(0.3);
  doc.lines([[w, h / 2], [-w * 2, 0], [w, -h / 2]], cx - w / 2, cy + h / 2, [1, 1], 'F', true);
  doc.setFontSize(7);
  doc.setFont('helvetica', 'bold');
  doc.text('N', cx, cy - h / 2 - 1.5, { align: 'center' });
}

/**
 * Draw a decorative compass rose with GN/TN/MN bearings.
 * ponytail: added per audit — real deed plans have a compass rose
 * showing Grid North, True North, and Magnetic North bearings.
 */
function drawCompassRose(doc: jsPDF, cx: number, cy: number, radius: number = 8) {
  // Outer circle
  doc.setDrawColor(0);
  doc.setLineWidth(0.3);
  doc.circle(cx, cy, radius, 'S');

  // Inner circle
  doc.circle(cx, cy, radius * 0.7, 'S');

  // North arrow (filled triangle)
  doc.setFillColor(0, 0, 0);
  doc.lines([[1.5, radius * 0.6], [-3, 0], [1.5, -radius * 0.6]], cx - 1.5, cy - radius * 0.3, [1, 1], 'F', true);

  // South arrow (outline)
  doc.lines([[1.5, -radius * 0.6], [-3, 0], [1.5, radius * 0.6]], cx - 1.5, cy + radius * 0.3, [1, 1], 'S', true);

  // Labels
  doc.setFontSize(5);
  doc.setFont('helvetica', 'bold');
  doc.text('N', cx, cy - radius - 1, { align: 'center' });
  doc.text('S', cx, cy + radius + 3, { align: 'center' });

  // GN / TN / MN labels (ponytail: simplified — only GN shown by default)
  doc.setFontSize(4);
  doc.setFont('helvetica', 'normal');
  doc.text('GN', cx + radius * 0.8, cy - 1, { align: 'left' });
}

function drawScaleBar(doc: jsPDF, x: number, y: number, scaleRatio: number, barLengthMm: number) {
  const groundDist = (barLengthMm * scaleRatio) / 1000;
  doc.setDrawColor(0);
  doc.setLineWidth(0.4);
  doc.rect(x, y, barLengthMm, 2);
  const half = barLengthMm / 2;
  doc.setFillColor(0, 0, 0);
  doc.rect(x, y, half, 2, 'F');
  doc.setFillColor(255, 255, 255);
  doc.rect(x + half, y, half, 2, 'F');
  doc.setFontSize(6);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(0);
  doc.text('0', x, y + 4.5, { align: 'center' });
  doc.text(`${(groundDist / 2).toFixed(0)} m`, x + half, y + 4.5, { align: 'center' });
  doc.text(`${groundDist.toFixed(0)} m`, x + barLengthMm, y + 4.5, { align: 'center' });
  doc.text(`Scale 1:${scaleRatio.toLocaleString()}`, x + barLengthMm / 2, y + 7.5, { align: 'center' });
}

/**
 * Draw road truncation lines (perpendicular tick marks) on boundary
 * segments that abut roads, with road width annotation.
 * Per Kenya cadastral practice, road boundaries are shown with short
 * perpendicular tick marks at regular intervals. Road reserve width
 * is shown as a text annotation along the road segment.
 * Source: Survey Act Cap. 299, Form No. 3 & 4
 */
function drawRoadTruncationLines(
  doc: jsPDF,
  roadSegments: RoadSegment[],
  worldToMm: (e: number, n: number) => [number, number],
  scaleRatio: number,
  centroidX: number,
  centroidY: number,
  roadWidth?: number
): void {
  if (!roadSegments || roadSegments.length === 0) return;

  // Convert centroid to mm for direction checking
  const [cmmX, cmmY] = worldToMm(centroidX, centroidY);

  for (const seg of roadSegments) {
    const [x1, y1] = worldToMm(seg.from.easting, seg.from.northing);
    const [x2, y2] = worldToMm(seg.to.easting, seg.to.northing);

    const dxMm = x2 - x1;
    const dyMm = y2 - y1;
    const segLenMm = Math.sqrt(dxMm * dxMm + dyMm * dyMm);
    if (segLenMm < 1) continue;

    // Perpendicular direction
    let perpX = -dyMm / segLenMm;
    let perpY = dxMm / segLenMm;

    // Ensure perpendicular points AWAY from centroid
    const midX = (x1 + x2) / 2;
    const midY = (y1 + y2) / 2;
    const toMidX = midX - cmmX;
    const toMidY = midY - cmmY;
    if (perpX * toMidX + perpY * toMidY < 0) {
      perpX = -perpX;
      perpY = -perpY;
    }

    const tickSpacing = 5; // mm
    const tickLength = 3;  // mm
    const numTicks = Math.max(2, Math.floor(segLenMm / tickSpacing));

    doc.setDrawColor(0);
    doc.setLineWidth(0.2);

    for (let t = 1; t < numTicks; t++) {
      const frac = t / numTicks;
      const baseX = x1 + dxMm * frac;
      const baseY = y1 + dyMm * frac;
      const endX = baseX + perpX * tickLength;
      const endY = baseY + perpY * tickLength;

      doc.line(baseX, baseY, endX, endY);
    }

    // Road width annotation text next to truncation tick marks
    if (roadWidth && roadWidth > 0) {
      const labelOffset = tickLength + 1.5; // Place text just beyond tick ends
      const labelX = midX + perpX * labelOffset;
      const labelY = midY + perpY * labelOffset;
      const widthLabel = `${roadWidth.toFixed(2)}m`;

      // Rotate label to align with road segment direction
      const angle = Math.atan2(dyMm, dxMm) * (180 / Math.PI);
      let textAngle = -(angle > 90 || angle < -90 ? angle + 180 : angle);

      doc.setFontSize(4.5);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(100);
      doc.text(widthLabel, labelX, labelY, { angle: textAngle, align: 'center' });
    }
  }
}

/**
 * Draw stamp and seal area in the bottom-left of the boundary plan panel.
 * Includes ISK rubber stamp placeholder and surveyor's corporate seal circle.
 */
function drawStampAndSealArea(
  doc: jsPDF,
  panel: PanelBounds,
  options: BoundaryPlanOptions
): void {
  const margin = 8;
  const stampX = panel.x + margin;
  const stampY = panel.y + panel.height - margin - 28;
  const stampW = 50;
  const stampH = 24;

  // Outer rectangle
  doc.setDrawColor(0);
  doc.setLineWidth(0.3);
  doc.rect(stampX, stampY, stampW, stampH);

  // Header
  doc.setFontSize(3.5);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0);
  doc.text('STAMP & SEAL AREA', stampX + stampW / 2, stampY + 2.5, { align: 'center' });

  doc.setLineWidth(0.15);
  doc.line(stampX, stampY + 3.5, stampX + stampW, stampY + 3.5);

  // Left: ISK rubber stamp placeholder
  const iskX = stampX + 1;
  const iskY = stampY + 5;
  const iskW = 28;
  const iskH = 12;

  doc.setDrawColor(150);
  doc.setLineDashPattern([1.5, 0.75], 0);
  doc.rect(iskX, iskY, iskW, iskH);
  doc.setLineDashPattern([], 0);

  doc.setFontSize(2.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(170);
  doc.text('ISK ASSOCIATION', iskX + iskW / 2, iskY + 4, { align: 'center' });
  doc.text('RUBBER STAMP', iskX + iskW / 2, iskY + 6.5, { align: 'center' });

  if (options.firmName) {
    doc.setFontSize(2);
    doc.setTextColor(190);
    doc.text(options.firmName, iskX + iskW / 2, iskY + 9, { align: 'center' });
  }

  doc.setFontSize(2);
  doc.setTextColor(200);
  doc.text('Approved: ____________', iskX + iskW / 2, iskY + 11, { align: 'center' });

  // Right: Surveyor's seal circle
  const sealCX = stampX + stampW - 10;
  const sealCY = iskY + iskH / 2;

  doc.setDrawColor(180);
  doc.setLineDashPattern([1, 0.5], 0);
  doc.circle(sealCX, sealCY, 4);
  doc.setLineDashPattern([], 0);

  doc.setFontSize(2.5);
  doc.setTextColor(170);
  doc.text('SURVEYOR', sealCX, sealCY - 1, { align: 'center' });
  doc.text('SEAL', sealCX, sealCY + 2, { align: 'center' });

  // Surveyor credentials below stamp area
  const credY = stampY + 18.5;

  // Signature line above surveyor credentials
  doc.setDrawColor(0);
  doc.setLineWidth(0.3);
  doc.line(stampX + 1, credY - 2, stampX + stampW - 1, credY - 2);

  doc.setFontSize(3);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0);
  if (options.surveyorName) {
    doc.text(options.surveyorName, stampX + 1, credY);
  }
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100);
  if (options.surveyorLicence) {
    doc.text(`LS/${options.surveyorLicence}`, stampX + 1, credY + 2.5);
  }
  if (options.iskRegNo) {
    doc.text(`ISK Reg. ${options.iskRegNo}`, stampX + 1, credY + 5);
  }

  // Date line below surveyor credentials
  doc.setTextColor(100);
  doc.text('Date: ___________', stampX + 1, credY + 7.5);
}

/**
 * Draw print verification text at the bottom of the boundary plan panel.
 * Uses SHA-256 cryptographic hash for production-grade verification.
 */
function drawPrintVerification(
  doc: jsPDF,
  panel: PanelBounds,
  geom: DeedPlanGeometry,
  scaleRatio: number,
  options?: BoundaryPlanOptions
): void {
  const coordString = geom.stations
    .map(s => `${s.easting.toFixed(4)},${s.northing.toFixed(4)}`)
    .join('|');
  const areaVal = geom.areaM2.toFixed(4);
  const dateStr = new Date().toISOString().split('T')[0];
  const surveyorLicence = options?.surveyorLicence || '';
  const revisionsCount = (options?.revisions || []).length;

  // SHA-256 cryptographic hash
  const rawString = `${coordString}|${areaVal}|${scaleRatio}|${dateStr}|${surveyorLicence}|${revisionsCount}`;
  const verCode = createHash('sha256').update(rawString).digest('hex').toUpperCase().slice(0, 16);

  const verifyX = panel.x + panel.width / 2;
  const verifyY = panel.y + panel.height - 1;

  doc.setFontSize(3);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(160);
  doc.text(
    `Verification: ${verCode} | Generated: ${dateStr} | Scale: 1:${scaleRatio}`,
    verifyX,
    verifyY,
    { align: 'center' }
  );
  doc.setFontSize(2.2);
  doc.setTextColor(190);
  doc.text(
    'Alteration invalidates verification — Per Survey Act Cap. 299, Sec. 23',
    verifyX,
    verifyY + 1.5,
    { align: 'center' }
  );
}

export function renderBoundaryPlan(
  doc: jsPDF,
  geom: DeedPlanGeometry,
  panel: PanelBounds,
  options?: BoundaryPlanOptions
) {
  const margin = 8;
  const drawX = panel.x + margin;
  const drawY = panel.y + margin;
  const drawW = panel.width - margin * 2;
  const drawH = panel.height - margin * 2 - 20;

  doc.setDrawColor(60, 60, 60);
  doc.setLineWidth(0.5);
  doc.rect(panel.x, panel.y, panel.width, panel.height);

  doc.setFontSize(8);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('SURVEY PLAN', panel.x + panel.width / 2, panel.y + 5, { align: 'center' });

  const spanE = geom.maxE - geom.minE || 1;
  const spanN = geom.maxN - geom.minN || 1;

  const scaleFromE = spanE / (drawW / 1000);
  const scaleFromN = spanN / (drawH / 1000);
  const rawScale = Math.max(scaleFromE, scaleFromN) * 1.15;

  const standardScales = [100, 200, 250, 500, 1000, 1250, 2000, 2500, 5000];
  const scaleRatio = standardScales.find((s) => s >= rawScale) ?? 10000

  const centreE = (geom.minE + geom.maxE) / 2;
  const centreN = (geom.minN + geom.maxN) / 2;

  const worldToMm = (e: number, n: number): [number, number] => {
    const px = drawX + drawW / 2 + ((e - centreE) / scaleRatio) * 1000;
    const py = drawY + drawH / 2 - ((n - centreN) / scaleRatio) * 1000;
    return [px, py];
  };

  const pts = geom.stations.map((s) => worldToMm(s.easting, s.northing))

  doc.setDrawColor(0, 0, 0);
  doc.setLineWidth(0.5);

  for (let i = 0; i < pts.length; i++) {
    const [x1, y1] = pts[i];
    const [x2, y2] = pts[(i + 1) % pts.length];
    doc.line(x1, y1, x2, y2);

    const mx = (x1 + x2) / 2;
    const my = (y1 + y2) / 2;
    const leg = geom.bearingSchedule[i];
    if (leg) {
      const angle = Math.atan2(y2 - y1, x2 - x1) * (180 / Math.PI);
      doc.setFontSize(5.5);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(0, 60, 120);
      doc.text(
        `${leg.bearing}  ${leg.distance}m`,
        mx, my,
        { angle: -(angle > 90 || angle < -90 ? angle + 180 : angle), align: 'center' }
      );
    }
  }

  geom.stations.forEach((st, i) => {
    const [px, py] = pts[i];
    drawMonumentSymbol(doc, px, py, st.monument ?? '');

    doc.setFontSize(6);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(0);
    const label = st.beaconNo ? `${st.station}\n(${st.beaconNo})` : st.station;
    doc.text(label, px + MONUMENT_SIZE + 1, py - 1);
  });

  // ── Phase 2: Road truncation lines with road width annotation ──
  if (options?.roadSegments && options.roadSegments.length > 0) {
    // Compute road reserve width from road class
    const roadWidth = options.roadClass ? getRoadReserveWidth(options.roadClass) : undefined;
    drawRoadTruncationLines(doc, options.roadSegments, worldToMm, scaleRatio, centreE, centreN, roadWidth);
  }

  drawNorthArrow(doc, panel.x + margin + 8, panel.y + panel.height - 20);

  // ponytail: draw compass rose at top-right corner of the plan panel
  drawCompassRose(doc, panel.x + panel.width - margin - 10, panel.y + margin + 10);

  // ponytail: draw adjoining properties labels (if provided in options)
  if ((options as Record<string, unknown>)?.adjoiningProperties) {
    const adjoining = (options as Record<string, unknown>).adjoiningProperties as Array<{ fromStation: string; toStation: string; lrNumber: string }>
    doc.setFontSize(5)
    doc.setFont('helvetica', 'italic')
    doc.setTextColor(80, 80, 80)
    for (const adj of adjoining) {
      const from = geom.stations.find(s => s.station === adj.fromStation)
      const to = geom.stations.find(s => s.station === adj.toStation)
      if (from && to) {
        const midX = (from.easting + to.easting) / 2
        const midY = (from.northing + to.northing) / 2
        const [mx, my] = worldToMm(midX, midY)
        doc.text(`LR ${adj.lrNumber}`, mx + 2, my - 1, { align: 'left' })
      }
    }
    doc.setTextColor(0, 0, 0)
    doc.setFont('helvetica', 'normal')
  }

  const barLen = 30;
  drawScaleBar(doc, panel.x + panel.width / 2 - barLen / 2, panel.y + panel.height - 18, scaleRatio, barLen);

  // ── Phase 2: Stamp & Seal Area ──
  if (options?.surveyorName || options?.firmName) {
    drawStampAndSealArea(doc, panel, options);
  }

  // ── Phase 2: Print Verification (SHA-256) ──
  drawPrintVerification(doc, panel, geom, scaleRatio, options);

  return scaleRatio;
}

/**
 * Draw revision history table using jsPDF.
 * Per Survey Act Cap. 299, every amendment to a registered plan must
 * be recorded with a revision entry.
 */
export function drawRevisionHistory(
  doc: jsPDF,
  x: number,
  y: number,
  w: number,
  revisions: RevisionEntry[],
  surveyorName?: string
): number {
  const rows = revisions.length > 0 ? revisions.slice(0, 5) : [
    { rev: 'A', date: new Date().toLocaleDateString('en-GB'), description: 'Initial issue', by: surveyorName || '' }
  ];

  const headerH = 5;
  const rowH = 4;
  const tableH = headerH + rows.length * rowH;

  // Table border
  doc.setDrawColor(0);
  doc.setLineWidth(0.3);
  doc.rect(x, y, w, tableH);

  // Header
  doc.setFontSize(5);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0);
  doc.text('REVISION HISTORY', x + 2, y + 3.5);

  doc.setLineWidth(0.15);
  doc.line(x, y + headerH, x + w, y + headerH);

  // Column headers
  const colWidths = [w * 0.1, w * 0.2, w * 0.45, w * 0.25];
  let colX = x;
  const colHeaders = ['Rev', 'Date', 'Description', 'By'];
  doc.setFontSize(4.5);
  doc.setTextColor(100);
  colHeaders.forEach((h, i) => {
    doc.text(h, colX + 1, y + headerH + 3);
    colX += colWidths[i];
  });

  doc.setLineWidth(0.1);
  doc.line(x, y + headerH + 4, x + w, y + headerH + 4);

  // Data rows
  doc.setFontSize(4.5);
  doc.setTextColor(0);
  rows.forEach((row, i) => {
    const rowY = y + headerH + 4 + (i + 1) * rowH;
    if (i > 0) {
      doc.setDrawColor(200);
      doc.setLineWidth(0.05);
      doc.line(x, rowY - rowH + 1, x + w, rowY - rowH + 1);
    }
    let cx = x;
    const cells = [
      row.rev,
      row.date,
      row.description.length > 30 ? row.description.slice(0, 28) + '..' : row.description,
      row.by,
    ];
    cells.forEach((cell, ci) => {
      doc.text(String(cell), cx + 1, rowY - 1);
      cx += colWidths[ci];
    });
  });

  return tableH;
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import db from '@/lib/db';

export async function generateDeformationReport(
  projectId: string
): Promise<Buffer> {
  const projectRes = await db.query('SELECT name FROM projects WHERE id = $1', [projectId]);
  const project = projectRes.rows[0];
  if (!project) throw new Error('Project not found');

  const entriesRes = await db.query(
    'SELECT row_index, station, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
    [projectId]
  );
  const entries = entriesRes.rows;

  if (!entries || entries.length === 0) {
    throw new Error('No deformation monitoring data found.');
  }

  const epochData = entries
    .map((e: { row_index: number; station: string; raw_data: Record<string, unknown> }) => ({
      point: e.station || `P${e.row_index}`,
      easting: parseFloat(String(e.raw_data?.easting ?? e.raw_data?.e ?? 0)),
      northing: parseFloat(String(e.raw_data?.northing ?? e.raw_data?.n ?? 0)),
      elevation: parseFloat(String(e.raw_data?.elevation ?? e.raw_data?.rl ?? e.raw_data?.z ?? 0)),
      epoch: String(e.raw_data?.epoch ?? 'current'),
    }))
    .filter((p) => p.easting !== 0)

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });

  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('DEFORMATION / MONITORING REPORT', 105, 15, { align: 'center' });

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Project: ${project.name}`, 14, 25);
  doc.text(`Date: ${new Date().toLocaleDateString('en-KE')}`, 196, 25, { align: 'right' });

  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.text('MONITORING POINTS', 14, 35);

  const tableData = epochData.map((p) => [
    p.point,
    p.epoch,
    p.easting.toFixed(3),
    p.northing.toFixed(3),
    p.elevation.toFixed(3),
  ]);

  autoTable(doc, {
    startY: 40,
    head: [['Point', 'Epoch', 'Easting (m)', 'Northing (m)', 'Elevation (m)']],
    body: tableData,
    styles: { fontSize: 8, cellPadding: 2 },
    headStyles: { fillColor: [0, 0, 0], textColor: 255 },
    alternateRowStyles: { fillColor: [245, 248, 250] },
  });

  const finalY = (doc as unknown as { lastAutoTable: { finalY: number } }).lastAutoTable.finalY;

  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.text('INTERPRETATION NOTES', 14, finalY + 10);
  doc.setFont('helvetica', 'normal');
  doc.text('This report shows point positions at different epochs for deformation analysis.', 14, finalY + 18);
  doc.text('Compare epochs to identify displacement vectors and rates of change.', 14, finalY + 25);

  return Buffer.from(doc.output('arraybuffer'));
}

import ExcelJS from 'exceljs';
import db from '@/lib/db';

export async function generateFieldBookExcel(
  projectId: string
): Promise<Buffer> {

  const projectRes = await db.query(
    'SELECT name, survey_type, ref_no FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  const entriesRes = await db.query(
    'SELECT row_index, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
    [projectId]
  );
  const entries = entriesRes.rows;

  const rows = (entries ?? []).map((e: { row_index: number; raw_data: Record<string, unknown> }) => e.raw_data)

  const wb = new ExcelJS.Workbook();
  wb.creator = 'Metardu';
  wb.created = new Date();

  const ws = wb.addWorksheet('Field Book', {
    pageSetup: { paperSize: 9, orientation: 'landscape' },
  });

  ws.mergeCells('A1:J1');
  const titleCell = ws.getCell('A1');
  titleCell.value = `FIELD BOOK — ${project?.name ?? 'Project'} — ${project?.survey_type?.toUpperCase() ?? ''}`;
  titleCell.font = { bold: true, size: 13, color: { argb: 'FF1E5064' } };
  titleCell.alignment = { horizontal: 'center', vertical: 'middle' };
  ws.getRow(1).height = 28;

  ws.mergeCells('A2:E2');
  ws.getCell('A2').value = `Ref: ${project?.ref_no ?? '—'}`;
  ws.mergeCells('F2:J2');
  ws.getCell('F2').value = `Generated: ${new Date().toLocaleDateString('en-KE')}`;
  ws.getCell('F2').alignment = { horizontal: 'right' };

  const allKeys = rows.length > 0
    ? Object.keys(rows[0]).filter((k) => !k.startsWith('_'))
    : ['station', 'bs', 'is', 'fs', 'rl', 'remark'];

  const headerRow = ws.addRow(allKeys.map((k) => k.replace(/_/g, ' ').toUpperCase()));
  headerRow.eachCell((cell) => {
    cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E5064' } };
    cell.alignment = { horizontal: 'center', vertical: 'middle' };
    cell.border = {
      top: { style: 'thin' }, bottom: { style: 'thin' },
      left: { style: 'thin' }, right: { style: 'thin' },
    };
  });
  ws.getRow(3).height = 20;

  rows.forEach((row: Record<string, unknown>, idx: number) => {
    const dataRow = ws.addRow(allKeys.map((k) => row[k] ?? ''));
    if (idx % 2 === 0) {
      dataRow.eachCell((cell) => {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF0F5F8' } };
      });
    }
    dataRow.eachCell((cell) => {
      cell.border = {
        top: { style: 'hair' }, bottom: { style: 'hair' },
        left: { style: 'thin' }, right: { style: 'thin' },
      };
    });
  });

  ws.columns.forEach((col) => {
    col.width = 16;
  });

  ws.views = [{ state: 'frozen', xSplit: 0, ySplit: 3, topLeftCell: 'A4', activeCell: 'A4' }];

  const buffer = await wb.xlsx.writeBuffer();
  return Buffer.from(buffer);
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { addPageFooter } from './pdfTitleBlock';
import { shoelaceArea as computePolygonArea } from '@/lib/engine/area';

// ---------------------------------------------------------------------------
// Input interface
// ---------------------------------------------------------------------------

export interface FormC22Input {
  projectName: string;
  lrNumber: string;
  parcelNumber: string;
  county: string;
  division: string;
  district: string;
  locality: string;
  surveyType: string;
  surveyorName: string;
  iskNumber: string;
  firmName: string;
  referenceNumber: string;
  revision: string;
  stations: Array<{
    label: string;
    observedBearing: number; // degrees
    observedDistance: number; // metres
    easting: number;
    northing: number;
    adjustedEasting: number;
    adjustedNorthing: number;
    departureRaw: number;
    latitudeRaw: number;
    departureCorrection: number;
    latitudeCorrection: number;
  }>;
  angularMisclosureSec: number;
  angularToleranceSec: number;
  linearMisclosureM: number;
  perimeterM: number;
  precisionRatio: number;
  areaM2: number;
  areaHa: number;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Convert decimal degrees to DMS string e.g. 45°30'15.2" */
function decimalToDMS(deg: number): string {
  const absolute = Math.abs(deg);
  const d = Math.floor(absolute);
  const minFloat = (absolute - d) * 60;
  const m = Math.floor(minFloat);
  const s = (minFloat - m) * 60;
  return `${d}°${String(m).padStart(2, '0')}'${s.toFixed(1)}"`;
}

/** Convert decimal degrees to WCB (Whole Circle Bearing) quadrant string e.g. N 45°30'15.2" E */
function decimalToWCB(deg: number): string {
  const normalised = ((deg % 360) + 360) % 360;
  if (normalised <= 90) {
    return `N ${decimalToDMS(normalised)} E`;
  } else if (normalised <= 180) {
    return `S ${decimalToDMS(180 - normalised)} E`;
  } else if (normalised <= 270) {
    return `S ${decimalToDMS(normalised - 180)} W`;
  } else {
    return `N ${decimalToDMS(360 - normalised)} W`;
  }
}

// computeShoelaceArea removed — now uses canonical shoelaceArea from @/lib/engine/area
// Call sites map adjustedEasting/adjustedNorthing → easting/northing.

/** Format a precision ratio like "1:12500" */
function formatPrecisionRatio(ratio: number): string {
  if (ratio <= 0 || !isFinite(ratio)) return '—';
  return `1:${Math.round(ratio).toLocaleString()}`;
}

// ---------------------------------------------------------------------------
// Page dimensions — A3 landscape
// ---------------------------------------------------------------------------

const PAGE_W = 420;
const PAGE_H = 297;
const MARGIN = 10;
const CONTENT_W = PAGE_W - MARGIN * 2;

// ---------------------------------------------------------------------------
// Main generator
// ---------------------------------------------------------------------------

export function generateFormC22Pdf(input: FormC22Input): Buffer {
  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3',
  });

  const today = new Date().toLocaleDateString('en-KE', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  });

  // Track pages for numbering — we add footer at the end for all pages
  let currentPage = 1;
  const totalPages = estimateTotalPages(input.stations.length);

  // =========================================================================
  // PAGE 1 — Header + Info + Tables 1 & 2
  // =========================================================================
  drawPageHeader(doc, input, today);
  drawProjectInfoBlock(doc, input, today);
  drawSurveyorInfoBlock(doc, input);

  let y = 56;

  // --- Table 1: Observed Bearings and Distances ---
  y = drawObservedBearingsTable(doc, input, y);
  y += 4;

  // --- Table 2: Traverse Adjustment ---
  y = drawTraverseAdjustmentTable(doc, input, y);
  y += 4;

  // Check if we need a new page for Table 3 & 4
  if (y > PAGE_H - 100) {
    addPageFooter(doc, currentPage, totalPages, input.projectName);
    doc.addPage();
    currentPage++;
    y = MARGIN;
  }

  // --- Table 3: Area Computation ---
  y = drawAreaComputationTable(doc, input, y);
  y += 4;

  // --- Table 4: Closure Summary ---
  y = drawClosureSummaryTable(doc, input, y);
  y += 6;

  // Check if we need a new page for certificate
  if (y > PAGE_H - 70) {
    addPageFooter(doc, currentPage, totalPages, input.projectName);
    doc.addPage();
    currentPage++;
    y = MARGIN;
  }

  // --- Surveyor's Certificate ---
  drawSurveyorCertificate(doc, input, y, today);

  // --- Professional Disclaimer ---
  drawDisclaimer(doc);

  // Finalize page footers on all pages
  const actualTotal = doc.getNumberOfPages();
  for (let p = 1; p <= actualTotal; p++) {
    doc.setPage(p);
    // Remove any previously drawn footer on this page by overwriting with white
    // Actually, addPageFooter draws a line + text; we just call it for every page
    addPageFooter(doc, p, actualTotal, input.projectName);
  }

  return Buffer.from(doc.output('arraybuffer'));
}

// ---------------------------------------------------------------------------
// Estimate page count
// ---------------------------------------------------------------------------

function estimateTotalPages(stationCount: number): number {
  // Rough heuristic: up to ~15 stations fit on 1 page, more needs 2
  if (stationCount <= 15) return 1;
  if (stationCount <= 30) return 2;
  return 3;
}

// ---------------------------------------------------------------------------
// Draw the Republic of Kenya / DoLS header
// ---------------------------------------------------------------------------

function drawPageHeader(doc: jsPDF, input: FormC22Input, _today: string): void {
  const cx = PAGE_W / 2;

  doc.setDrawColor(0, 0, 0);
  doc.setLineWidth(1.0);
  doc.rect(MARGIN, MARGIN, CONTENT_W, 36);

  // Double border effect
  doc.setLineWidth(0.3);
  doc.rect(MARGIN + 1.5, MARGIN + 1.5, CONTENT_W - 3, 33);

  doc.setFontSize(12);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('REPUBLIC OF KENYA', cx, MARGIN + 10, { align: 'center' });

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(40, 40, 40);
  doc.text('DEPARTMENT OF LAND SERVICES', cx, MARGIN + 17, { align: 'center' });

  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('FORM NO. C22 — COMPUTATION SHEET', cx, MARGIN + 26, { align: 'center' });

  doc.setFontSize(7);
  doc.setFont('helvetica', 'italic');
  doc.setTextColor(80, 80, 80);
  doc.text(
    'Survey Act Cap 299 — Survey Regulations 1994 — Arc 1960 / UTM Zone 37S (EPSG:21037)',
    cx,
    MARGIN + 33,
    { align: 'center' }
  );
}

// ---------------------------------------------------------------------------
// Draw project information block (left column)
