import JSZip from 'jszip';
import db from '@/lib/db';

export async function generateFullPackage(
  projectId: string
): Promise<Buffer> {

  const readyDocsRes = await db.query(
    "SELECT document_id, file_url FROM submission_documents WHERE project_id = $1 AND status = 'ready' AND document_id != 'full-package'",
    [projectId]
  );
  const readyDocs = readyDocsRes.rows;

  if (!readyDocs || readyDocs.length === 0) {
    throw new Error('No ready documents found. Generate individual documents before creating the full package.');
  }

  const zip = new JSZip();
  const folder = zip.folder('submission') ?? zip;

  for (const doc of readyDocs) {
    if (!doc.file_url) continue;
    try {
      const res = await fetch(doc.file_url);
      if (!res.ok) continue;
      const blob = await res.arrayBuffer();
      const ext = doc.file_url.split('.').pop() ?? 'bin';
      folder.file(`${doc.document_id}.${ext}`, blob);
    } catch {
      // Skip failed fetches
    }
  }

  folder.file('README.txt', [
    'METARDU SUBMISSION PACKAGE',
    '===========================',
    `Generated: ${new Date().toISOString()}`,
    `Documents included: ${readyDocs.length}`,
    '',
    'Contents:',
    ...readyDocs.map((d: { document_id: string; file_url: string }) => `  - ${d.document_id}`),
    '',
    'Prepared by Metardu — Professional Survey Platform',
  ].join('\n'));

  const buffer = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
  return Buffer.from(buffer);
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import db from '@/lib/db';

export async function generateGcpReport(
  projectId: string
): Promise<Buffer> {
  const projectRes = await db.query('SELECT name FROM projects WHERE id = $1', [projectId]);
  const project = projectRes.rows[0];
  if (!project) throw new Error('Project not found');

  const entriesRes = await db.query(
    'SELECT row_index, station, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
    [projectId]
  );
  const entries = entriesRes.rows;

  if (!entries || entries.length === 0) {
    throw new Error('No GCP data found. Add fieldbook entries first.');
  }

  const gcpData = entries
    .map((e: { row_index: number; station: string; raw_data: Record<string, unknown> }) => ({
      name: e.station || `GCP${e.row_index}`,
      easting: parseFloat(String(e.raw_data?.easting ?? e.raw_data?.e ?? 0)),
      northing: parseFloat(String(e.raw_data?.northing ?? e.raw_data?.n ?? 0)),
      elevation: parseFloat(String(e.raw_data?.elevation ?? e.raw_data?.rl ?? e.raw_data?.z ?? 0)),
      accuracy: parseFloat(String(e.raw_data?.accuracy ?? e.raw_data?.rms ?? 0)),
    }))
    .filter((g) => g.easting !== 0 && g.northing !== 0);

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });

  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('GROUND CONTROL POINT (GCP) ACCURACY REPORT', 105, 15, { align: 'center' });

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Project: ${project.name}`, 14, 25);
  doc.text(`Date: ${new Date().toLocaleDateString('en-KE')}`, 196, 25, { align: 'right' });

  const tableData = gcpData.map((g) => [
    g.name,
    g.easting.toFixed(3),
    g.northing.toFixed(3),
    g.elevation.toFixed(3),
    g.accuracy > 0 ? g.accuracy.toFixed(3) : '—',
  ])

  autoTable(doc, {
    startY: 30,
    head: [['GCP Name', 'Easting (m)', 'Northing (m)', 'Elevation (m)', 'RMS Error (m)']],
    body: tableData,
    styles: { fontSize: 8, cellPadding: 2 },
    headStyles: { fillColor: [0, 0, 0], textColor: 255 },
    alternateRowStyles: { fillColor: [245, 248, 250] },
  })

  const finalY = (doc as unknown as { lastAutoTable: { finalY: number } }).lastAutoTable.finalY

  const avgAccuracy = gcpData.reduce((s, g) => s + g.accuracy, 0) / gcpData.length
  const maxAccuracy = Math.max(...gcpData.map((g) => g.accuracy))

  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.text('SUMMARY', 14, finalY + 10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Total GCPs: ${gcpData.length}`, 14, finalY + 18);
  doc.text(`Average RMS Error: ${avgAccuracy.toFixed(3)} m`, 14, finalY + 25);
  doc.text(`Maximum RMS Error: ${maxAccuracy.toFixed(3)} m`, 14, finalY + 32);

  return Buffer.from(doc.output('arraybuffer'));
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import db from '@/lib/db';
import { drawTitleBlock, addPageFooter } from './pdfTitleBlock';

export async function generateLevellingReport(
  projectId: string
): Promise<Buffer> {

  const projectRes = await db.query(
    'SELECT name, survey_type, ref_no FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  const entriesRes = await db.query(
    'SELECT row_index, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
    [projectId]
  );
  const entries = entriesRes.rows;

  const rows = (entries ?? []).map((e: { row_index: number; raw_data: Record<string, unknown> }) => e.raw_data)

  const bsReadings = rows.filter((r) => r.bs).map((r) => parseFloat(String(r.bs)) || 0)
  const fsReadings = rows.filter((r) => r.fs).map((r) => parseFloat(String(r.fs)) || 0)
  const sumBS = bsReadings.reduce((a, b) => a + b, 0)
  const sumFS = fsReadings.reduce((a, b) => a + b, 0)
  const misclosureMm = Math.abs(sumBS - sumFS) * 1000;

  const totalDistanceM = rows.length * 50;
  const totalDistanceKm = totalDistanceM / 1000;
  const toleranceMm = 10 * Math.sqrt(totalDistanceKm);

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const today = new Date().toLocaleDateString('en-KE');

  let y = drawTitleBlock(doc, {
    projectName: project?.name ?? 'Unknown Project',
    surveyType: project?.survey_type ?? '',
    reportTitle: 'LEVELLING REPORT',
    date: today,
    refNo: project?.ref_no,
  });

  doc.setFontSize(9);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('1. LEVEL BOOK (HEIGHT OF COLLIMATION METHOD)', 15, y);
  y += 6;

  autoTable(doc, {
    startY: y,
    head: [['Station', 'BS (m)', 'IS (m)', 'FS (m)', 'HPC (m)', 'RL (m)', 'Remark']],
    body: rows.map((r) => [
      String(r.station ?? ''),
      String(r.bs ?? ''),
      String(r.is ?? ''),
      String(r.fs ?? ''),
      String(r.instrument_height ?? ''),
      String(r.rl ?? ''),
      String(r.remark ?? ''),
    ]),
    styles: { fontSize: 8, cellPadding: 2 },
    headStyles: { fillColor: [0, 0, 0], textColor: 255 },
    alternateRowStyles: { fillColor: [245, 248, 250] },
    margin: { left: 15, right: 15 },
    theme: 'grid',
    didDrawPage: (data) => {
      addPageFooter(doc, data.pageNumber, doc.getNumberOfPages(), project?.name ?? '');
    },
  });

  y = (doc as unknown as { lastAutoTable: { finalY: number } }).lastAutoTable.finalY + 10;

  doc.setFontSize(9);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('2. CLOSURE CHECK', 15, y);
  y += 6;

  const closureStatus = misclosureMm <= toleranceMm ? 'PASS ' : 'FAIL [x]';
  const closureColor: [number, number, number] = misclosureMm <= toleranceMm ? [0, 120, 60] : [180, 0, 0];

  autoTable(doc, {
    startY: y,
    head: [['Parameter', 'Value']],
    body: [
      ['Sum of BS readings', `${sumBS.toFixed(4)} m`],
      ['Sum of FS readings', `${sumFS.toFixed(4)} m`],
      ['Misclosure', `${misclosureMm.toFixed(1)} mm`],
      ['Allowable tolerance (10√K mm)', `${toleranceMm.toFixed(1)} mm`],
      ['Closure status', closureStatus],
      ['Standard reference', 'RDM 1.1 (2025) Table 5.1 — 10√K mm'],
      ['Adjustment method', 'Proportional to distance (Bowditch)'],
    ],
    styles: { fontSize: 8, cellPadding: 2 },
    headStyles: { fillColor: [0, 0, 0], textColor: 255 },
    columnStyles: { 0: { fontStyle: 'bold', cellWidth: 80 } },
    margin: { left: 15, right: 15 },
    theme: 'grid',
    didParseCell: (data) => {
      if (data.row.index === 4 && data.column.index === 1) {
        data.cell.styles.textColor = closureColor;
        data.cell.styles.fontStyle = 'bold';
      }
    },
  });

  addPageFooter(doc, 1, doc.getNumberOfPages(), project?.name ?? '');

  return Buffer.from(doc.output('arraybuffer'));
}

