import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import db from '@/lib/db';

interface CrossSection {
  chainage: number;
  area: number;
  description?: string;
}

/** End-Area Method: V = (L/2) * (A1 + A2) */
function computeVolumeTrapezoidal(sections: CrossSection[]): number {
  let total = 0;
  for (let i = 0; i < sections.length - 1; i++) {
    const L = sections[i + 1].chainage - sections[i].chainage;
    total += (L / 2) * (sections[i].area + sections[i + 1].area);
  }
  return total;
}

/** Prismoidal Formula: V = (L/6) * (A1 + 4*Am + A2) */
function computeVolumePrismoidal(sections: CrossSection[]): number {
  if (sections.length < 3 || sections.length % 2 === 0) {
    throw new Error('Prismoidal requires odd number of sections (>= 3)');
  }
  let total = 0;
  for (let i = 0; i < sections.length - 1; i += 2) {
    const L = sections[i + 2].chainage - sections[i].chainage;
    total += (L / 6) * (sections[i].area + 4 * sections[i + 1].area + sections[i + 2].area);
  }
  return total;
}

export async function generateVolumetricReport(
  projectId: string
): Promise<Buffer> {
  const projectRes = await db.query('SELECT name FROM projects WHERE id = $1', [projectId]);
  const project = projectRes.rows[0];
  if (!project) throw new Error('Project not found');

  const entriesRes = await db.query(
    'SELECT row_index, station, raw_data FROM project_fieldbook_entries WHERE project_id = $1 ORDER BY row_index ASC',
    [projectId]
  );
  const entries = entriesRes.rows;

  if (!entries || entries.length < 2) {
    throw new Error('Insufficient cross-section data. Add at least 2 sections.');
  }

  const sections: CrossSection[] = entries
    .map((e: { row_index: number; raw_data: Record<string, unknown> }) => ({
      chainage: parseFloat(String(e.raw_data?.chainage ?? e.row_index * 10)),
      area: parseFloat(String(e.raw_data?.area ?? e.raw_data?.cross_section_area ?? 0)),
    }))
    .filter((s) => s.area > 0)
    .sort((a, b) => a.chainage - b.chainage);

  if (sections.length < 2) {
    throw new Error('Need at least 2 sections with area > 0');
  }

  const trapezoidal = computeVolumeTrapezoidal(sections);
  let prismoidal = 0;
  let method = 'Trapezoidal Rule';

  try {
    prismoidal = computeVolumePrismoidal(sections);
    method = 'Prismoidal Formula';
  } catch {
    // Not enough sections for prismoidal
  }

  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });

  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('VOLUMETRIC / EARTHWORKS REPORT', 105, 15, { align: 'center' });

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text(`Project: ${project.name}`, 14, 25);
  doc.text(`Date: ${new Date().toLocaleDateString('en-KE')}`, 196, 25, { align: 'right' });

  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.text('CROSS SECTIONS', 14, 35);

  const tableData = sections.map((s) => [
    s.chainage.toFixed(2),
    s.area.toFixed(2),
    s.description || '',
  ]);

  autoTable(doc, {
    startY: 38,
    head: [['Chainage (m)', 'Area (m²)', 'Remark']],
    body: tableData,
    styles: { fontSize: 8, cellPadding: 2 },
    headStyles: { fillColor: [0, 0, 0], textColor: 255 },
  });

  const finalY = (doc as unknown as { lastAutoTable: { finalY: number } }).lastAutoTable.finalY;

  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.text('VOLUME SUMMARY', 14, finalY + 10);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');

  const summaryData = [
    ['Method Used', method],
    ['Trapezoidal Volume', `${trapezoidal.toFixed(2)} m³`],
    ['Prismoidal Volume', prismoidal > 0 ? `${prismoidal.toFixed(2)} m³` : 'N/A'],
    ['Final Volume (recommended)', `${(prismoidal || trapezoidal).toFixed(2)} m³`],
    ['Number of Sections', sections.length.toString()],
    ['Total Length', `${(sections[sections.length - 1].chainage - sections[0].chainage).toFixed(2)} m`],
  ];

  autoTable(doc, {
    startY: finalY + 15,
    body: summaryData,
    styles: { fontSize: 10, cellPadding: 3 },
    columnStyles: { 0: { fontStyle: 'bold' }, 1: { halign: 'right' } },
    theme: 'plain',
  });

  return Buffer.from(doc.output('arraybuffer'));
}

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import db from '@/lib/db';
import { computeDeedPlanGeometry, loadPreAdjustedFromDB } from './deedPlanGeometry';
import { renderBoundaryPlan } from './deedPlanRenderer';
import { addPageFooter } from './pdfTitleBlock';

const A4_W = 297;
const A4_H = 210;
const MARGIN = 8;
const PLAN_W = Math.round(A4_W * 0.60);
const TABLE_X = PLAN_W + MARGIN;
const TABLE_W = A4_W - PLAN_W - MARGIN * 1.5;

export async function generateWorkingDiagramPdf(
  projectId: string
): Promise<Buffer> {

  const projectRes = await db.query(
    'SELECT name, survey_type, lr_number, utm_zone, hemisphere, datum, field_book_no, computations_no FROM projects WHERE id = $1',
    [projectId]
  );
  const project = projectRes.rows[0];

  if (!project) throw new Error('Project not found.');

  // Use Bowditch-adjusted coordinates from traverse engine — single source of truth
  const preAdjusted = await loadPreAdjustedFromDB(projectId);
  const geom = await computeDeedPlanGeometry(projectId, {
    preAdjustedCoordinates: preAdjusted?.stations,
    preAdjustedClosure: preAdjusted?.closure,
  });

  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });

  const today = new Date().toLocaleDateString('en-KE', {
    day: '2-digit', month: 'long', year: 'numeric',
  });

  doc.setDrawColor(0);
  doc.setLineWidth(0.8);
  doc.rect(MARGIN, MARGIN, A4_W - MARGIN * 2, A4_H - MARGIN * 2);

  doc.setLineWidth(0.4);
  doc.line(PLAN_W, MARGIN, PLAN_W, A4_H - MARGIN);

  renderBoundaryPlan(doc, geom, {
    x: MARGIN,
    y: MARGIN,
    width: PLAN_W - MARGIN,
    height: A4_H - MARGIN * 2,
  });

  let ry = MARGIN + 4;

  doc.setFontSize(8.5);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text('WORKING DIAGRAM', TABLE_X + TABLE_W / 2, ry + 3, { align: 'center' });

  doc.setFontSize(6.5);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(80, 80, 80);
  doc.text(project.name ?? '', TABLE_X + TABLE_W / 2, ry + 8, { align: 'center' });

  if (project.lr_number) {
    doc.text(`LR No: ${project.lr_number}`, TABLE_X + TABLE_W / 2, ry + 12, { align: 'center' });
  }

  doc.text(`Date: ${today}`, TABLE_X + TABLE_W / 2, ry + 16, { align: 'center' });
  ry += 20;

  doc.setDrawColor(180);
  doc.setLineWidth(0.2);
  doc.line(TABLE_X, ry, TABLE_X + TABLE_W, ry);
  ry += 3;

  doc.setFontSize(7);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 0, 0);
  doc.text("GALE'S TABLE", TABLE_X, ry);
  ry += 3;

  const galeBody = geom.bearingSchedule.map((leg, i) => {
    const st = geom.stations[i];
    const next = geom.stations[(i + 1) % geom.stations.length];
    const dE = next.easting - st.easting;
    const dN = next.northing - st.northing;
    return [
      st.station,
      leg.bearing,
      leg.distance,
      dE.toFixed(3),
      dN.toFixed(3),
      st.easting.toFixed(3),
      st.northing.toFixed(3),
    ];
  });

  const totalDist = geom.bearingSchedule.reduce((s, l) => s + parseFloat(l.distance), 0);
  const lastSt = geom.stations[geom.stations.length - 1];
  const firstSt = geom.stations[0];

  autoTable(doc, {
    startY: ry,
    head: [['Stn', 'Bearing', 'Dist (m)', 'ΔE (m)', 'ΔN (m)', 'Adj E', 'Adj N']],
    body: galeBody,
    foot: [
      ['Σ', '', totalDist.toFixed(3), lastSt.easting - firstSt.easting, lastSt.northing - firstSt.northing, '', '']
    ],
    styles: { fontSize: 6, cellPadding: 1.2 },
    headStyles: { fillColor: [0, 0, 0], textColor: 255 },
    footStyles: { fillColor: [0, 0, 0], textColor: 255, fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [245, 248, 250] },
    columnStyles: {
      0: { cellWidth: 10 },
      1: { cellWidth: 25, font: 'courier', fontSize: 5.5 },
      2: { cellWidth: 16, halign: 'right' },
      3: { cellWidth: 16, halign: 'right' },
      4: { cellWidth: 16, halign: 'right' },
      5: { cellWidth: 18, halign: 'right' },
      6: { cellWidth: TABLE_W - 103, halign: 'right' },
    },
    margin: { left: TABLE_X, right: MARGIN },
    tableWidth: TABLE_W,
    theme: 'grid',
  });

  ry = (doc as unknown as { lastAutoTable: { finalY: number } }).lastAutoTable.finalY + 4;

  const statusColor: [number, number, number] =
    geom.closureStatus === 'PASS' ? [0, 120, 60] : [180, 0, 0];

  autoTable(doc, {
    startY: ry,
    head: [['Closure Check', 'Value']],
    body: [
      ['Misclosure (mm)', `${geom.misclosureMm.toFixed(1)} mm`],
      ['Precision ratio', geom.precisionRatio],
      ['Status', geom.closureStatus],
      ['Standard (Cap 299)', '1:5000 minimum'],
      ['Adj. method', 'Bowditch (Compass Rule)'],
    ],
    styles: { fontSize: 6, cellPadding: 1.2 },
    headStyles: { fillColor: [0, 0, 0], textColor: 255 },
    columnStyles: {
      0: { fontStyle: 'bold', cellWidth: 32 },
      1: { cellWidth: TABLE_W - 34 },
    },
    margin: { left: TABLE_X, right: MARGIN },
    tableWidth: TABLE_W,
    theme: 'grid',
    didParseCell: (data) => {
      if (data.section === 'body' && data.row.index === 2 && data.column.index === 1) {
        data.cell.styles.textColor = statusColor;
        data.cell.styles.fontStyle = 'bold';
      }
    },
  });

  addPageFooter(doc, 1, 1, project.name ?? '');

  return Buffer.from(doc.output('arraybuffer'));
}

/**
 * Tests for the Epoch Manager — plate velocity and epoch propagation
 *
 * Verifies that the Somali plate velocity model produces sensible numbers
 * for Kenya and that epoch propagation works correctly.
 */

import {
  computePlateVelocity,
  geodeticToEcef,
  ecefToGeodetic,
  propagateToEpoch,
  compareCoordinates,
  dateToDecimalYear,
  decimalYearToDate,
  currentEpoch,
  validateEpoch,
  SOMALI_PLATE_OMEGA,
} from '../epochManager'

// ─── ECEF Conversions ───────────────────────────────────────────────────────

describe('geodeticToEcef / ecefToGeodetic', () => {
  it('round-trips Nairobi coordinates correctly', () => {
    const lat = -1.2921
    const lon = 36.8219
    const h = 1795 // Nairobi elevation ~1795m

    const [X, Y, Z] = geodeticToEcef(lat, lon, h)
    const result = ecefToGeodetic(X, Y, Z)

    expect(result.latitude).toBeCloseTo(lat, 6)
    expect(result.longitude).toBeCloseTo(lon, 6)
    expect(result.height).toBeCloseTo(h, 2)
  })

  it('round-trips Mombasa coordinates correctly', () => {
    const lat = -4.0435
    const lon = 39.6682
    const h = 50

    const [X, Y, Z] = geodeticToEcef(lat, lon, h)
    const result = ecefToGeodetic(X, Y, Z)

    expect(result.latitude).toBeCloseTo(lat, 6)
    expect(result.longitude).toBeCloseTo(lon, 6)
    expect(result.height).toBeCloseTo(h, 2)
  })

  it('produces sensible ECEF values for Nairobi', () => {
    const [X, Y, Z] = geodeticToEcef(-1.2921, 36.8219, 1795)
    // Nairobi is ~6.3Mm from Earth center, mostly X (near equator, 37°E)
    expect(Math.sqrt(X * X + Y * Y + Z * Z)).toBeCloseTo(6378137 + 1795, -3)
    expect(X).toBeGreaterThan(0)
    expect(Y).toBeGreaterThan(0)
    expect(Z).toBeLessThan(0) // southern hemisphere
  })
})

// ─── Plate Velocity ─────────────────────────────────────────────────────────

describe('computePlateVelocity', () => {
  it('produces a northeast velocity for Kenya (Somali plate moves NNE)', () => {
    const v = computePlateVelocity(-1.2921, 36.8219)
    expect(v.ve).toBeGreaterThan(0) // eastward
    expect(v.vn).toBeGreaterThan(0) // northward
    const horizontalVel = Math.sqrt(v.ve ** 2 + v.vn ** 2)
    expect(horizontalVel).toBeGreaterThan(0.005) // > 5mm/year
    expect(horizontalVel).toBeLessThan(0.05)     // < 5cm/year
  })

  it('produces a small vertical velocity (plates move mostly horizontally)', () => {
    const v = computePlateVelocity(-1.2921, 36.8219)
    const horizontalVel = Math.sqrt(v.ve ** 2 + v.vn ** 2)
    expect(Math.abs(v.vu)).toBeLessThan(horizontalVel)
  })

  it('produces consistent velocities across Kenya (same plate)', () => {
    const nairobi = computePlateVelocity(-1.2921, 36.8219)
    const mombasa = computePlateVelocity(-4.0435, 39.6682)
    const kisumu = computePlateVelocity(-0.0917, 34.7680)

    const magnitudes = [nairobi, mombasa, kisumu].map(v => Math.sqrt(v.ve ** 2 + v.vn ** 2))
    const maxMag = Math.max(...magnitudes)
    const minMag = Math.min(...magnitudes)
    expect(maxMag / minMag).toBeLessThan(2.5)
  })

  it('uses the Somali plate omega by default', () => {
    const v = computePlateVelocity(-1.2921, 36.8219)
    const vExplicit = computePlateVelocity(-1.2921, 36.8219, 0, SOMALI_PLATE_OMEGA)
    expect(v.ve).toBeCloseTo(vExplicit.ve, 15)
    expect(v.vn).toBeCloseTo(vExplicit.vn, 15)
  })
})

// ─── Epoch Propagation ──────────────────────────────────────────────────────

describe('propagateToEpoch', () => {
  it('returns the same coordinate when source and target epochs are equal', () => {
    const coord = {
      latitude: -1.2921,
      longitude: 36.8219,
      height: 1795,
      frame: 'ITRF2014' as const,
      epoch: 2025.0,
    }
    const result = propagateToEpoch(coord, 2025.0)
    expect(result.latitude).toBeCloseTo(coord.latitude, 10)
    expect(result.longitude).toBeCloseTo(coord.longitude, 10)
    expect(result.dtYears).toBeCloseTo(0, 10)
    expect(result.displacement.de).toBeCloseTo(0, 10)
  })

  it('propagates Nairobi 10 years forward with measurable displacement', () => {
    const coord = {
      latitude: -1.2921,
      longitude: 36.8219,
      height: 1795,
      frame: 'ITRF2014' as const,
      epoch: 2015.0,
    }
    const result = propagateToEpoch(coord, 2025.0)

    const totalDisplacement = Math.sqrt(
      result.displacement.de ** 2 + result.displacement.dn ** 2,
    )
    expect(totalDisplacement).toBeGreaterThan(0.005) // > 5mm over 10 years
    expect(totalDisplacement).toBeLessThan(0.50)     // < 50cm
    expect(result.dtYears).toBeCloseTo(10, 1)
  })

  it('propagates backwards in time (negative dt)', () => {
    const coord = {
      latitude: -1.2921,
      longitude: 36.8219,
      height: 1795,
      frame: 'ITRF2014' as const,
      epoch: 2025.0,
    }
    const result = propagateToEpoch(coord, 2015.0)
    expect(result.dtYears).toBeCloseTo(-10, 1)
    expect(Math.abs(result.displacement.de)).toBeGreaterThan(0.0001)
  })

  it('includes provenance with source and target epochs', () => {
    const coord = {
      latitude: -1.2921,
      longitude: 36.8219,
      height: 1795,
      frame: 'ITRF2014' as const,
      epoch: 2015.0,
    }
    const result = propagateToEpoch(coord, 2025.0)
    expect(result.provenance).toContain('2015')
    expect(result.provenance).toContain('2025')
    expect(result.provenance).toContain('Somali plate')
    expect(result.provenance).toContain('ITRF2014')
  })
})

// ─── Coordinate Comparison ──────────────────────────────────────────────────

describe('compareCoordinates', () => {
  it('returns zero distance for identical coordinates at the same epoch', () => {
    const coord = {
      latitude: -1.2921,
      longitude: 36.8219,
      height: 1795,
      frame: 'ITRF2014' as const,
      epoch: 2025.0,
    }
    const result = compareCoordinates(coord, coord, 0.05)
    expect(result.distanceM).toBeCloseTo(0, 5)
    expect(result.agrees).toBe(true)
  })

  it('detects disagreement when coordinates differ by > tolerance', () => {
    const coord1 = {
      latitude: -1.2921,
      longitude: 36.8219,
      height: 1795,
      frame: 'ITRF2014' as const,
      epoch: 2025.0,
    }
    const coord2 = {
      latitude: -1.2920, // ~11m south — way beyond 5cm tolerance
      longitude: 36.8219,
      height: 1795,
      frame: 'ITRF2014' as const,
      epoch: 2025.0,
    }
    const result = compareCoordinates(coord1, coord2, 0.05)
    expect(result.distanceM).toBeGreaterThan(5) // ~11m
    expect(result.agrees).toBe(false)
  })

  it('propagates both coordinates to a common epoch before comparing', () => {
    // Same physical point, observed 10 years apart. The 2025 observation
    // gives a DIFFERENT lat/lon (because the plate moved ~10cm NNE over
    // 10 years). After propagation to a common epoch, the distance should
    // be near zero (sub-mm with the rigorous Rodrigues' rotation formula).
    const coord2015 = {
      latitude: -1.2921,
      longitude: 36.8219,
      height: 1795,
      frame: 'ITRF2014' as const,
      epoch: 2015.0,
    }

    // The 2025 observation is of the SAME monument, so its lat/lon reflects
    // 10 years of plate motion. Compute this with the rigorous propagator.
    // We need to import it here to construct the test data.
    const { propagateToEpochRigorous } = require('../epochManagerRigorous')
    const propagated = propagateToEpochRigorous(coord2015, 2025.0)

    const coord2025 = {
      latitude: propagated.latitude,
      longitude: propagated.longitude,
      height: propagated.height,
      frame: 'ITRF2014' as const,
      epoch: 2025.0,
    }

    const result = compareCoordinates(coord2015, coord2025, 0.05)
    expect(result.commonEpoch).toBeCloseTo(2025.0, 1)
    // Rigorous Rodrigues' rotation has zero accumulated error — these are
    // the same physical point, so distance should be sub-mm.
    expect(result.distanceM).toBeLessThan(0.001)
    expect(result.agrees).toBe(true)  // PASSES within 5cm tolerance
  })
})

