  points: Array<{
    name: string
    easting: number
    northing: number
    elevation: number
    sigmaEasting: number
    sigmaNorthing: number
    sigmaElevation: number
  }>
  baselines: BaselineResult[]
  adjustmentStats: {
    rms: number
    maxResidual: number
    degreesOfFreedom: number
  }
}

/**
 * Convert Geodetic (lat, lon, height) to ECEF (X, Y, Z)
 * WGS84 ellipsoid
 */
export function geodeticToECEF(lat: number, lon: number, h: number): GNSSBaseStation {
  const a = 6378137.0  // WGS84 semi-major axis
  const f = 1 / 298.257223563  // WGS84 flattening
  const e2 = 2 * f - f * f
  
  const latRad = toRadians(lat)
  const lonRad = toRadians(lon)
  
  const N = a / Math.sqrt(1 - e2 * Math.sin(latRad) * Math.sin(latRad))
  
  const x = (N + h) * Math.cos(latRad) * Math.cos(lonRad)
  const y = (N + h) * Math.cos(latRad) * Math.sin(lonRad)
  const z = (N * (1 - e2) + h) * Math.sin(latRad)
  
  return { name: '', x, y, z }
}

/**
 * Convert ECEF (X, Y, Z) to Geodetic (lat, lon, height)
 * Iterative solution, WGS84
 */
export function ecefToGeodetic(x: number, y: number, z: number): { lat: number; lon: number; h: number } {
  const a = 6378137.0
  const f = 1 / 298.257223563
  const e2 = 2 * f - f * f
  
  const lon = Math.atan2(y, x)
  
  const p = Math.sqrt(x * x + y * y)
  const lat0 = Math.atan2(z, p * (1 - e2))
  
  let lat = lat0
  for (let i = 0; i < 10; i++) {
    const N = a / Math.sqrt(1 - e2 * Math.sin(lat) * Math.sin(lat))
    const h = p / Math.cos(lat) - N
    lat = Math.atan2(z, p * (1 - e2 * N / (N + h)))
  }
  
  const N = a / Math.sqrt(1 - e2 * Math.sin(lat) * Math.sin(lat))
  const h = p / Math.cos(lat) - N
  
  return {
    lat: toDegrees(lat),
    lon: toDegrees(lon),
    h
  }
}

/**
 * Convert ECEF to local ENU (Easting, Northing, Up)
 * Returns ENU coordinates relative to origin point
 */
export function ecefToENU(
  x: number, y: number, z: number,
  originLat: number, originLon: number, originH: number
): { easting: number; northing: number; up: number } {
  const origin = geodeticToECEF(originLat, originLon, originH)
  
  const latRad = toRadians(originLat)
  const lonRad = toRadians(originLon)
  
  const dx = x - origin.x
  const dy = y - origin.y
  const dz = z - origin.z
  
  const easting = -Math.sin(lonRad) * dx + Math.cos(lonRad) * dy
  const northing = -Math.sin(latRad) * Math.cos(lonRad) * dx - Math.sin(latRad) * Math.sin(lonRad) * dy + Math.cos(latRad) * dz
  const up = Math.cos(latRad) * Math.cos(lonRad) * dx + Math.cos(latRad) * Math.sin(lonRad) * dy + Math.sin(latRad) * dz
  
  return { easting, northing, up }
}

/**
 * Compute baseline vector between two GNSS points
 */
export function computeBaseline(from: GNSSObservation, to: GNSSObservation): BaselineResult {
  const deltaX = to.x - from.x
  const deltaY = to.y - from.y
  const deltaZ = to.z - from.z
  
  const distance3D = Math.sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ)
  const distance2D = Math.sqrt(deltaX * deltaX + deltaY * deltaY)
  
  // Azimuth from North (0-360 degrees, WCB)
  let azimuth = toDegrees(Math.atan2(deltaX, deltaY))
  if (azimuth < 0) azimuth += 360
  
  // Elevation angle (angle above horizontal)
  const elevationAngle = toDegrees(Math.atan2(deltaZ, distance2D))
  
  // Combined uncertainty based on DOP and measurement precision
  let sigma = 0.01  // Base uncertainty 1cm
  if (from.sigmaX !== undefined && to.sigmaX !== undefined) {
    sigma = Math.sqrt(
      (from.sigmaX || 0.01) ** 2 + 
      (to.sigmaX || 0.01) ** 2 +
      (from.sigmaY || 0.01) ** 2 + 
      (to.sigmaY || 0.01) ** 2 +
      (from.sigmaZ || 0.01) ** 2 + 
      (to.sigmaZ || 0.01) ** 2
    ) / Math.sqrt(3)
  }
  
  return {
    from: from.pointName,
    to: to.pointName,
    deltaX,
    deltaY,
    deltaZ,
    distance3D,
    distance2D,
    azimuth,
    elevationAngle,
    sigma
  }
}

/**
 * Process GNSS network from base station and rover observations
 * Returns adjusted coordinates in local projection
 */
export function processGNSSNetwork(
  baseStation: GNSSBaseStation,
  observations: GNSSObservation[],
  originLat: number,
  originLon: number,
  originH: number
): GNSSNetworkResult {
  const baselines: BaselineResult[] = []
  const points: GNSSNetworkResult['points'] = []
  
  // Compute baselines from base station
  const baseECEF = { x: baseStation.x, y: baseStation.y, z: baseStation.z }
  
  for (const obs of observations) {
    const baseline = computeBaseline(
      { pointName: baseStation.name, ...baseECEF },
      obs
    )
    baselines.push(baseline)
    
    // Convert to local ENU
    const obsECEF = geodeticToECEF(0, 0, 0)  // placeholder
    const enu = ecefToENU(obs.x, obs.y, obs.z, originLat, originLon, originH)
    
    // Calculate uncertainties (simplified)
    const sigmaE = obs.sigmaX || 0.01
    const sigmaN = obs.sigmaY || 0.01
    const sigmaU = obs.sigmaZ || 0.02
    
    points.push({
      name: obs.pointName,
      easting: enu.easting,
      northing: enu.northing,
      elevation: enu.up,
      sigmaEasting: sigmaE,
      sigmaNorthing: sigmaN,
      sigmaElevation: sigmaU
    })
  }
  
  // Calculate network statistics
  const residuals = baselines.map((b: any) => b.sigma)
  const rms = Math.sqrt(residuals.reduce((sum, r) => sum + r * r, 0) / residuals.length) || 0
  
  return {
    points,
    baselines,
    adjustmentStats: {
      rms,
      maxResidual: Math.max(...residuals, 0),
      degreesOfFreedom: Math.max(observations.length - 3, 1)
    }
  }
}

/**
 * Convert UTM coordinates to/from Geodetic
 */
export function utmToGeodetic(easting: number, northing: number, zone: number, hemisphere: 'N' | 'S'): { lat: number; lon: number } {
  const a = 6378137.0
  const f = 1 / 298.257223563
  const e = Math.sqrt(2 * f - f * f)
  const e1 = (1 - Math.sqrt(1 - e * e)) / (1 + Math.sqrt(1 - e * e))
  
  const x = easting - 500000
  const y = hemisphere === 'S' ? northing - 10000000 : northing
  
  const M0 = 0
  const mu = M0 / (a * (1 - e * e / 4 - 3 * e * e * e * e / 64))
  
  const phi1 = mu + (3 * e1 / 2 - 27 * e1 * e1 * e1 / 32) * Math.sin(2 * mu)
    + (21 * e1 * e1 / 16 - 55 * e1 * e1 * e1 * e1 / 32) * Math.sin(4 * mu)
    + (151 * e1 * e1 * e1 / 96) * Math.sin(6 * mu)
  
  const N1 = a / Math.sqrt(1 - e * e * Math.sin(phi1) * Math.sin(phi1))
  const T1 = Math.tan(phi1) * Math.tan(phi1)
  const C1 = (e * e / (1 - e * e)) * Math.cos(phi1) * Math.cos(phi1)
  const R1 = a * (1 - e * e) / Math.pow(1 - e * e * Math.sin(phi1) * Math.sin(phi1), 1.5)
  const D = x / (N1 * Math.cos(phi1))
  
  let lat = phi1 - (N1 * Math.tan(phi1) / R1) * (
    D * D / 2
    - (5 + 3 * T1 + 10 * C1 - 4 * C1 * C1 - 9 * e * e) * D * D * D * D / 24
    + (61 + 90 * T1 + 298 * C1 + 45 * T1 * T1 - 252 * e * e - 3 * C1 * C1) * D * D * D * D * D * D / 720
  )
  
  let lon = (D - (1 + 2 * T1 + C1) * D * D * D / 6 + 
    (5 - 2 * C1 + 28 * T1 - 3 * C1 * C1 + 8 * e * e + 24 * T1 * T1) * D * D * D * D * D / 120) / Math.cos(phi1)
  
  lat = toDegrees(lat)
  lon = toDegrees(lon) + zone * 6 - 180 + 3
  
  return { lat, lon }
}

/**
 * Calculate PDOP (Position Dilution of Precision) from geometry
 */
export function calculatePDOP(satellites: Array<{ x: number; y: number; z: number }>, userPosition: { x: number; y: number; z: number }): number {
  if (satellites.length < 4) return Infinity
  
  // Build design matrix
  const G: number[][] = []
  
  for (const sat of satellites) {
    const dx = sat.x - userPosition.x
    const dy = sat.y - userPosition.y
    const dz = sat.z - userPosition.z
    const range = Math.sqrt(dx * dx + dy * dy + dz * dz)
    
    G.push([
      -dx / range,
      -dy / range,
      -dz / range,
      1
    ])
  }
  
  // Q = (G'G)^-1
  const GT = transpose(G)
  const GTG = multiply(GT, G)
  const Q = inverse(GTG)
  
  if (!Q) return Infinity
  
  // PDOP = sqrt(Q[0][0] + Q[1][1] + Q[2][2])
  const pdop = Math.sqrt(Q[0][0] + Q[1][1] + Q[2][2])
  
  return pdop
}

// Matrix utilities
function transpose(m: number[][]): number[][] {
  return m[0].map((_, i) => m.map((row: any) => row[i]))
}

function multiply(a: number[][], b: number[][]): number[][] {
  const result: number[][] = []
  for (let i = 0; i < a.length; i++) {
    result[i] = []
    for (let j = 0; j < b[0].length; j++) {
      let sum = 0
      for (let k = 0; k < a[0].length; k++) {
        sum += a[i][k] * b[k][j]
      }
      result[i][j] = sum
    }
  }
  return result
}

function inverse(m: number[][]): number[][] | null {
  const n = m.length
  const aug = m.map((row, i) => [...row, ...Array(n).fill(0).map((_, j) => i === j ? 1 : 0)])
  
  for (let i = 0; i < n; i++) {
    let maxRow = i
    for (let k = i + 1; k < n; k++) {
      if (Math.abs(aug[k][i]) > Math.abs(aug[maxRow][i])) maxRow = k
    }
    [aug[i], aug[maxRow]] = [aug[maxRow], aug[i]]
    
    if (Math.abs(aug[i][i]) < 1e-12) return null
    
    const factor = aug[i][i]
    for (let j = 0; j < 2 * n; j++) aug[i][j] /= factor
    
    for (let k = 0; k < n; k++) {
      if (k !== i) {
        const factor2 = aug[k][i]
        for (let j = 0; j < 2 * n; j++) aug[k][j] -= factor2 * aug[i][j]
      }
    }
  }
  
  return aug.map((row: any) => row.slice(n))
}

/**
 * Combined Scale Factor (CSF) Engine — v0.3
 *
 * Solves the grid-vs-ground area discrepancy that is a legal timebomb in Kenya.
 * Nairobi is at ~1,600m elevation. UTM Zone 37S central meridian is at 39°E.
 * A 100ha parcel can have a 0.3-0.5ha discrepancy between grid area and
 * physical ground area. The deed plan must state the correct area.
 *
 * CSF = k × Fh
 *   k  = Grid Scale Factor (UTM projection distortion at the given longitude)
 *   Fh = Elevation Factor (height above ellipsoid / Earth radius)
 *
 * Ground Area = Grid Area / CSF²
 *
 * Sources:
 * - UTM grid scale factor: k = 0.9996 / cosh(asinh(tan(φ)) - atanh(e·sin(φ))·e) ... simplified
 *   For practical purposes, k ≈ 0.9996 + (x_offset / R)² / 2 where x_offset is
 *   distance from central meridian in metres.
 * - Elevation factor: Fh = R / (R + h) where R = 6,371,000m, h = ellipsoidal height
 *
 * For Kenya UTM zones:
 *   Zone 36S: central meridian = 33°E
 *   Zone 37S: central meridian = 39°E
 */

import { shoelaceArea } from '@/lib/engine/area'

// ─── Constants ──────────────────────────────────────────────────────────────

const EARTH_RADIUS_M = 6_371_000 // Mean Earth radius (spherical approximation)
const UTM_SCALE_AT_CENTRAL_MERIDIAN = 0.9996 // Standard UTM scale factor

// ─── Types ──────────────────────────────────────────────────────────────────

export interface ScaleFactorInput {
  /** Latitude in decimal degrees */
  latitude: number
  /** Longitude in decimal degrees */
  longitude: number
  /** UTM zone (36 or 37 for Kenya) */
  utmZone: number
  /** Ellipsoidal height in metres (from GNSS, NOT orthometric) */
  ellipsoidalHeight: number
}

export interface ScaleFactorResult {
  /** Grid scale factor (UTM projection distortion) */
  gridScaleFactor: number
  /** Elevation factor (height above ellipsoid) */
  elevationFactor: number
  /** Combined scale factor = grid × elevation */
  combinedScaleFactor: number
  /** Distance from central meridian in metres */
  distanceFromCentralMeridian: number
  /** Central meridian longitude in degrees */
  centralMeridian: number
  /** Scale factor as a ratio (e.g., 1:1.0004) */
  scaleRatio: string
  /** Percentage distortion */
  percentDistortion: number
}

export interface AreaConversionResult {
  /** Area computed from grid coordinates (shoelace formula) */
  gridAreaSqM: number
  /** Area converted to ground (physical surface) */
  groundAreaSqM: number
  /** Area in hectares (ground) */
  groundAreaHa: number
  /** Area in acres (ground) */
  groundAreaAcres: number
  /** The CSF used for conversion */
  csf: number
  /** Difference in m² */
  differenceSqM: number
  /** Difference in hectares */
  differenceHa: number
  /** Percentage difference */
  percentDifference: number
}

// ─── Scale factor computation ───────────────────────────────────────────────

/**
 * Compute the Combined Scale Factor for a point at a given location and elevation.
 *
 * @param input Location + elevation
 * @returns Scale factor breakdown
 */
export function computeCombinedScaleFactor(input: ScaleFactorInput): ScaleFactorResult {
  const { latitude, longitude, utmZone, ellipsoidalHeight } = input

  // AUDIT FIX (M5, 2026-07-02): Replaced spherical approximation with
  // the rigorous ellipsoidal point scale factor formula. The old code
  // used EARTH_RADIUS_M = 6,371,000 (mean sphere) and
  // mPerDegLon = 111,320 × cos(φ) — both spherical approximations that
  // introduce ~0.1-0.3 ppm error at Nairobi distances. The rigorous
  // formula uses the ellipsoidal meridional and prime-vertical radii.

  // WGS84 / Arc 1960 ellipsoid parameters (Clarke 1880 for Arc 1960
  // is very close to WGS84 for scale factor purposes — the difference
  // is sub-ppm at Kenya latitudes)
  const a = 6_378_137.0           // Semi-major axis (metres)
  const f = 1 / 298.257223563     // Inverse flattening (WGS84)
  const e2 = 2 * f - f * f        // First eccentricity squared
  const ePrime2 = e2 / (1 - e2)   // Second eccentricity squared

  const latRad = (latitude * Math.PI) / 180
  const sinLat = Math.sin(latRad)
  const cosLat = Math.cos(latRad)
  const sinLat2 = sinLat * sinLat
  const cosLat2 = cosLat * cosLat

  // Radii of curvature (ellipsoidal)
  // ρ = a(1-e²) / (1-e²sin²φ)^(3/2)  — meridional radius
  // ν = a / √(1-e²sin²φ)              — prime vertical radius
  // Rm = √(ρ·ν)                        — geometric mean radius
  const oneMinusE2Sin2 = 1 - e2 * sinLat2
  const rho = (a * (1 - e2)) / Math.pow(oneMinusE2Sin2, 1.5)
  const nu = a / Math.sqrt(oneMinusE2Sin2)
  const Rm = Math.sqrt(rho * nu)

  // Central meridian for this UTM zone
  const centralMeridian = utmZone * 6 - 183 // Zone 36 → 33°, Zone 37 → 39°

  // Distance from central meridian in metres — use the ellipsoidal
  // prime-vertical radius (not the spherical 111,320 m/°):
  // dE = (λ - λ₀) × ν × cos(φ)   (in radians)
  const lonDiffRad = ((longitude - centralMeridian) * Math.PI) / 180
  const distanceFromCM = Math.abs(lonDiffRad * nu * cosLat)

  // Grid scale factor (UTM projection) — rigorous 2nd-order formula:
  // k = k₀ × (1 + E'²/(2Rm²) × (1 + e'²cos²φ) + E'⁴/(24Rm⁴))
  // where E' is the distance from the central meridian
  const Eprime2 = distanceFromCM * distanceFromCM
  const Eprime4 = Eprime2 * Eprime2
  const Rm2 = Rm * Rm
  const Rm4 = Rm2 * Rm2

  const gridScaleFactor = UTM_SCALE_AT_CENTRAL_MERIDIAN * (
    1 +
    (Eprime2 / (2 * Rm2)) * (1 + ePrime2 * cosLat2) +
    (Eprime4 / (24 * Rm4))
  )

  // Elevation factor — use the ellipsoidal prime-vertical radius (not
  // the mean Earth radius). At 1800m elevation (Nairobi), this gives
  // Fh = ν / (ν + h) ≈ 0.99972 (vs 0.99972 for spherical — the
  // difference is sub-ppm at this elevation, but it's the correct formula).
  const elevationFactor = nu / (nu + ellipsoidalHeight)

  // Combined scale factor
  const combinedScaleFactor = gridScaleFactor * elevationFactor

  // Scale ratio (e.g., 1:1.0004 → "1 : 1.0004")
  const scaleRatio = `1 : ${combinedScaleFactor.toFixed(6)}`

  // Percentage distortion
  const percentDistortion = ((combinedScaleFactor - 1) * 100)

  return {
    gridScaleFactor,
    elevationFactor,
    combinedScaleFactor,
    distanceFromCentralMeridian: distanceFromCM,
    centralMeridian,
    scaleRatio,
    percentDistortion,
  }
}

// ─── Area conversion ────────────────────────────────────────────────────────

/**
 * Convert grid area (from UTM coordinates) to ground area (physical surface).
 *
 * Ground Area = Grid Area / CSF²
 *
 * This is the critical calculation for deed plan accuracy. The grid area
 * from the shoelace formula on UTM coordinates is NOT the physical area
 * on the ground. At Nairobi (1,600m, Zone 37S), the difference can be
 * 0.3-0.5 hectares on a 100ha parcel.
 *
 * @param gridAreaSqM Area from coordinate shoelace formula (m²)
 * @param csf Combined scale factor
 * @returns Ground area + difference
 */
export function convertGridAreaToGround(
  gridAreaSqM: number,
  csf: number,
): AreaConversionResult {
  const groundAreaSqM = gridAreaSqM / (csf * csf)
  const groundAreaHa = groundAreaSqM / 10_000
  const groundAreaAcres = groundAreaSqM / 4_046.86

  const differenceSqM = groundAreaSqM - gridAreaSqM
  const differenceHa = differenceSqM / 10_000
  const percentDifference = gridAreaSqM > 0 ? ((differenceSqM / gridAreaSqM) * 100) : 0

  return {
    gridAreaSqM,
    groundAreaSqM,
    groundAreaHa,
    groundAreaAcres,
    csf,
    differenceSqM,
    differenceHa,
    percentDifference,
  }
}

// ─── Convenience: compute area with scale factor ────────────────────────────

/**
 * Compute the shoelace area of a polygon, then apply the combined scale factor
 * to get the true ground area.
 *
 * @param coords Array of [easting, northing] UTM coordinates
 * @param csf Combined scale factor
 * @returns Both grid and ground area
 */
export function computeAreaWithScaleFactor(
  coords: [number, number][],
  csf: number,
): AreaConversionResult {
  const gridAreaSqM = shoelaceArea(coords.map(([e, n]) => ({ easting: e, northing: n })))
  return convertGridAreaToGround(gridAreaSqM, csf)
}

