/**
 * Web Bluetooth GNSS Service
 * Connects to external GNSS receivers via Bluetooth
 * Works in Chrome desktop and Chrome Android (HTTPS required)
 */

import { parseNMEA, type NMEAPosition } from './nmea-parser';

export interface GNSSDevice {
  id: string;
  name: string;
  type: 'trimble' | 'leica' | 'topcon' | 'south' | 'generic';
}

export interface GNSSConnection {
  device: BluetoothDevice;
  characteristic: BluetoothRemoteGATTCharacteristic;
  connected: boolean;
}

export type PositionCallback = (position: NMEAPosition) => void;
export type ConnectionCallback = (connected: boolean, error?: string) => void;

const GNSS_SERVICE_UUIDS = [
  '0000180d-0000-1000-8000-00805f9b34fb',
  '00001819-0000-1000-8000-00805f9b34fb',
  '49535343-fe7d-4ae5-8fa9-9fafd205e455',
  '00001101-0000-1000-8000-00805f9b34fb',
];

const NMEA_CHARACTERISTIC_UUID = '00002a67-0000-1000-8000-00805f9b34fb';

export class WebBluetoothGNSS {
  private device: BluetoothDevice | null = null;
  private characteristic: BluetoothRemoteGATTCharacteristic | null = null;
  private positionCallbacks: PositionCallback[] = [];
  private connectionCallbacks: ConnectionCallback[] = [];
  private buffer: string = '';
  private isConnecting: boolean = false;
  private boundNotificationHandler: ((event: Event) => void) | null = null;

  static isAvailable(): boolean {
    return typeof navigator !== 'undefined' && 'bluetooth' in navigator;
  }

  async scanForDevices(): Promise<GNSSDevice[]> {
    if (!WebBluetoothGNSS.isAvailable()) {
      throw new Error('Web Bluetooth not available. Use Chrome or Edge.');
    }

    try {
      const device = await (navigator as any).bluetooth.requestDevice({
        filters: [
          { services: [GNSS_SERVICE_UUIDS[0]] },
          { services: [GNSS_SERVICE_UUIDS[1]] },
          { namePrefix: 'Trimble' },
          { namePrefix: 'Leica' },
          { namePrefix: 'Topcon' },
          { namePrefix: 'South' },
          { namePrefix: 'GNSS' },
          { namePrefix: 'GPS' },
          { namePrefix: 'SOKKIA' },
          { namePrefix: 'HI-TARGET' },
        ],
        optionalServices: GNSS_SERVICE_UUIDS,
      });

      return [{
        id: device.id,
        name: device.name || 'Unknown GNSS',
        type: this.detectDeviceType(device.name || ''),
      }];
    } catch (error) {
      if ((error as Error).name === 'NotFoundError') {
        throw new Error('No GNSS device found. Make sure Bluetooth is enabled and device is paired.');
      }
      throw error;
    }
  }

  async connect(deviceId?: string): Promise<void> {
    if (this.isConnecting) {
      throw new Error('Already connecting');
    }

    this.isConnecting = true;
    this.buffer = '';

    try {
      if (deviceId) {
        const devices = await (navigator as any).bluetooth.getDevices();
        this.device = devices.find((d: BluetoothDevice) => d.id === deviceId) || null;
      }

      if (!this.device) {
        const devices = await this.scanForDevices();
        this.device = await (navigator as any).bluetooth.requestDevice({
          filters: [{ namePrefix: devices[0].name.substring(0, 7) }],
          optionalServices: GNSS_SERVICE_UUIDS,
        });
      }

      const server = await this.device!.gatt?.connect();
      if (!server) {
        throw new Error('Failed to connect to GATT server');
      }

      let service: BluetoothRemoteGATTService | null = null;
      for (const uuid of GNSS_SERVICE_UUIDS) {
        try {
          service = await server.getPrimaryService(uuid);
          if (service) break;
        } catch {
          continue;
        }
      }

      if (!service) {
        throw new Error('GNSS service not found on device');
      }

      this.characteristic = await service.getCharacteristic(NMEA_CHARACTERISTIC_UUID);

      await this.characteristic.startNotifications();
      this.boundNotificationHandler = this.handleNotification.bind(this);
      this.characteristic.addEventListener('characteristicvaluechanged', this.boundNotificationHandler!);

      this.notifyConnection(true);
    } catch (error) {
      this.notifyConnection(false, (error as Error).message);
      throw error;
    } finally {
      this.isConnecting = false;
    }
  }

  private handleNotification(event: Event): void {
    const characteristic = event.target as unknown as BluetoothRemoteGATTCharacteristic;
    const value = characteristic.value;
    
    if (!value) return;

    const decoder = new TextDecoder('utf-8');
    const data = decoder.decode(value);
    
    this.buffer += data;
    
    const lines = this.buffer.split('\r\n');
    this.buffer = lines.pop() || '';
    
    for (const line of lines) {
      if (line.startsWith('$')) {
        const position = parseNMEA(line);
        if (position) {
          this.notifyPosition(position);
        }
      }
    }
  }

  async disconnect(): Promise<void> {
    if (this.characteristic) {
      try {
        if (this.boundNotificationHandler) {
          this.characteristic.removeEventListener('characteristicvaluechanged', this.boundNotificationHandler);
          this.boundNotificationHandler = null;
        }
        await this.characteristic.stopNotifications();
      } catch {
        // Ignore
      }
      this.characteristic = null;
    }

    if (this.device?.gatt?.connected) {
      this.device.gatt.disconnect();
    }

    this.device = null;
    this.buffer = '';
    this.notifyConnection(false);
  }

  onPosition(callback: PositionCallback): () => void {
    this.positionCallbacks.push(callback);
    return () => {
      this.positionCallbacks = this.positionCallbacks.filter(cb => cb !== callback);
    };
  }

  onConnectionChange(callback: ConnectionCallback): () => void {
    this.connectionCallbacks.push(callback);
    return () => {
      this.connectionCallbacks = this.connectionCallbacks.filter(cb => cb !== callback);
    };
  }

  private notifyPosition(position: NMEAPosition): void {
    for (const callback of this.positionCallbacks) {
      try {
        callback(position);
      } catch (error) {
        console.error('Error in position callback:', error);
      }
    }
  }

  private notifyConnection(connected: boolean, error?: string): void {
    for (const callback of this.connectionCallbacks) {
      try {
        callback(connected, error);
      } catch (err) {
        console.error('Error in connection callback:', err);
      }
    }
  }

  private detectDeviceType(name: string): GNSSDevice['type'] {
    const lower = name.toLowerCase();
    if (lower.includes('trimble')) return 'trimble';
    if (lower.includes('leica')) return 'leica';
    if (lower.includes('topcon')) return 'topcon';
    if (lower.includes('south')) return 'south';
    return 'generic';
  }

  isConnected(): boolean {
    return this.device?.gatt?.connected ?? false;
  }

  getConnectedDevice(): GNSSDevice | null {
    if (!this.device) return null;
    return {
      id: this.device.id,
      name: this.device.name || 'Unknown',
      type: this.detectDeviceType(this.device.name || ''),
    };
  }
}

/**
 * Capacitor Bluetooth LE — Total Station & GNSS Integration
 * ────────────────────────────────────────────────────────────
 * Real implementation that uses @capacitor-community/bluetooth-le
 * when running natively (Android/iOS), and falls back to Web
 * Bluetooth API when in a browser context.
 *
 * Supported device types:
 *   - Leica total stations (GSI format over BLE)
 *   - Trimble receivers (NMEA over BLE)
 *   - Topcon / Sokkia / South instruments (generic NMEA)
 *   - Any GNSS receiver broadcasting NMEA 0183 over BLE
 *
 * The BLE UART service (Nordic UART Service / NUS) is the de facto
 * standard for surveying instruments that stream serial data over
 * Bluetooth LE. This module scans for NUS-compatible devices,
 * connects, and streams parsed NMEA/GSI data into the existing
 * instrument connection infrastructure.
 */

import { parseNMEA, type NMEAPosition } from './nmea-parser';
import { type GNSSDevice, type PositionCallback, type ConnectionCallback } from './bluetooth';

export interface CapacitorGNSSDevice {
  deviceId: string;
  name: string;
  rssi?: number;
  type?: 'total-station' | 'gnss' | 'unknown';
}

// ─── BLE Service / Characteristic UUIDs ────────────────────────────────────
// Nordic UART Service (NUS) — used by most BLE surveying instruments
const NUS_SERVICE_UUID = '6e400001-b5a3-f393-e0a9-e50e24dcca9e';
const NUS_TX_CHAR_UUID = '6e400003-b5a3-f393-e0a9-e50e24dcca9e'; // device → phone
const NUS_RX_CHAR_UUID = '6e400002-b5a3-f393-e0a9-e50e24dcca9e'; // phone → device

// Standard Location + NMEA service (some GNSS receivers use this instead of NUS)
const LOCATION_SERVICE_UUID = '00001819-0000-1000-8000-00805f9b34fb';
const NMEA_CHARACTERISTIC_UUID = '00002a67-0000-1000-8000-00805f9b34fb';

// Device name patterns for auto-classification
const TOTAL_STATION_PATTERNS = [
  /leica/i, /ts\d{2}/i, /tcrm/i, /viva/i, /nova/i,
  /topcon/i, /os-\d/i, /ds-\d/i,
  /sokkia/i, /cx-\d/i, /fx-\d/i,
  /trimble/i, /s\d$/i, /s7/i,
  /south/i, /hi-target/i,
];
const GNSS_PATTERNS = [
  /gnss/i, /rtk/i, /receiver/i, /r\d{2}/i,
  /trimble r/i, /leica gs/i, /topcon hi-per/i,
];

function classifyDevice(name: string): 'total-station' | 'gnss' | 'unknown' {
  for (const p of TOTAL_STATION_PATTERNS) {
    if (p.test(name)) return 'total-station';
  }
  for (const p of GNSS_PATTERNS) {
    if (p.test(name)) return 'gnss';
  }
  return 'unknown';
}

/**
 * Dynamically import the Capacitor BLE plugin. Returns null if not
 * available (browser context or plugin not installed).
 */
async function getBLEPlugin() {
  try {
    const mod = await import('@capacitor-community/bluetooth-le');
    return mod.BleClient;
  } catch {
    return null;
  }
}

export class CapacitorBLEGNSS {
  private deviceId: string | null = null;
  private positionCallbacks: PositionCallback[] = [];
  private connectionCallbacks: ConnectionCallback[] = [];
  private buffer: string = '';
  private scanning = false;

  // ─── Reconnection resilience ────────────────────────────
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private baseReconnectDelayMs = 2000;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private intentionallyDisconnected = false;
  private lastConnectedDeviceId: string | null = null;
  private isReconnecting = false;

  /**
   * Configure reconnection behaviour.
   * Call before connect() to customise backoff parameters.
   */
  setReconnectConfig(opts: { maxAttempts?: number; baseDelayMs?: number }): void {
    if (opts.maxAttempts !== undefined) this.maxReconnectAttempts = opts.maxAttempts;
    if (opts.baseDelayMs !== undefined) this.baseReconnectDelayMs = opts.baseDelayMs;
  }

  /** Whether the service is currently in a reconnection cycle. */
  getIsReconnecting(): boolean {
    return this.isReconnecting;
  }

  /** Number of reconnection attempts made so far. */
  getReconnectAttemptCount(): number {
    return this.reconnectAttempts;
  }

  /** Cancel any pending reconnection attempt. */
  cancelReconnect(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    this.isReconnecting = false;
    this.reconnectAttempts = 0;
  }

  /**
   * Exponential backoff delay: 2s → 4s → 8s → 16s → 30s cap.
   * Jitter ±20% to avoid thundering herd on multi-device setups.
   */
  private getReconnectDelay(): number {
    const base = this.baseReconnectDelayMs * Math.pow(2, this.reconnectAttempts);
    const capped = Math.min(base, 30000);
    const jitter = capped * (0.8 + Math.random() * 0.4); // ±20%
    return Math.round(jitter);
  }

  /**
   * Internal auto-reconnect on unexpected disconnect.
   * Called from the BLE disconnect callback only when the
   * disconnect was NOT initiated by the user.
   */
  private async attemptReconnect(): Promise<void> {
    if (this.intentionallyDisconnected) return;
    if (!this.lastConnectedDeviceId) return;
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      this.isReconnecting = false;
      this.notifyConnection(false, `Failed to reconnect after ${this.maxReconnectAttempts} attempts`);
      return;
    }

    this.isReconnecting = true;
    this.reconnectAttempts++;
    const delay = this.getReconnectDelay();

    // Notify subscribers that we're reconnecting
    this.notifyConnection(false, `Reconnecting (attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts})…`);

    await new Promise<void>((resolve) => {
      this.reconnectTimer = setTimeout(resolve, delay);
    });

    // Check if cancelReconnect was called during the wait
    if (this.intentionallyDisconnected || !this.lastConnectedDeviceId) {
      this.isReconnecting = false;
      return;
    }

    try {
      await this.connect(this.lastConnectedDeviceId);
      // Success — reset counters
      this.reconnectAttempts = 0;
      this.isReconnecting = false;
    } catch {
      // Failed — schedule next attempt
      this.attemptReconnect();
    }
  }

  /**
   * Check whether Capacitor BLE is available on this platform.
   * Returns true only when running natively with the BLE plugin.
   */
  static async isAvailable(): Promise<boolean> {
    const BleClient = await getBLEPlugin();
    if (!BleClient) return false;
    try {
      await BleClient.initialize({ androidNeverForLocation: false });
      return true;
    } catch {
      return false;
    }
  }

  /** Request Bluetooth permissions (Android 12+ requires explicit permission). */
  static async requestPermissions(): Promise<boolean> {
    const BleClient = await getBLEPlugin();
    if (!BleClient) return false;
    try {
      await BleClient.initialize({ androidNeverForLocation: false });
      return true;
    } catch {
      return false;
    }
  }

  async initialize(): Promise<void> {
    const BleClient = await getBLEPlugin();
    if (!BleClient) {
      throw new Error('Capacitor Bluetooth LE not available. Use Web Bluetooth in browser.');
    }
    await BleClient.initialize({ androidNeverForLocation: false });
  }

  /**
   * Scan for BLE surveying instruments.
   * Looks for devices advertising NUS or Location+NMEA services.
   */
  async scanForDevices(durationMs = 5000): Promise<CapacitorGNSSDevice[]> {
    const BleClient = await getBLEPlugin();
    if (!BleClient) {
      throw new Error('Capacitor Bluetooth LE not available');
    }

    const devices: Map<string, CapacitorGNSSDevice> = new Map();

    await BleClient.requestLEScan(
      {
        services: [NUS_SERVICE_UUID, LOCATION_SERVICE_UUID],
        allowDuplicates: true,
      },
      (result: { device: { deviceId: string; name?: string }; rssi?: number }) => {
        const id = result.device.deviceId;
        const name = result.device.name || `BLE-${id.slice(0, 8)}`;
        if (!devices.has(id)) {
          devices.set(id, {
            deviceId: id,
            name,
            rssi: result.rssi,
            type: classifyDevice(name),
          });
        }
      },
    );

    // Scan for the requested duration
    await new Promise((resolve) => setTimeout(resolve, durationMs));
    await BleClient.stopLEScan();
    this.scanning = false;

    return Array.from(devices.values()).sort((a, b) => (b.rssi ?? -100) - (a.rssi ?? -100));
  }

  /**
   * Connect to a BLE device by ID and start streaming data.
   * Tries NUS first (most common for surveying instruments),
   * then falls back to the standard Location+NMEA service.
   */
  async connect(deviceId: string): Promise<void> {
    const BleClient = await getBLEPlugin();
    if (!BleClient) {
      throw new Error('Capacitor Bluetooth LE not available');
    }

    this.intentionallyDisconnected = false;

    await BleClient.connect(deviceId, (disconnectedDeviceId: string) => {
      if (disconnectedDeviceId === this.deviceId) {
        this.deviceId = null;
        this.buffer = '';

        if (!this.intentionallyDisconnected) {
          // Unexpected disconnect — trigger auto-reconnect
          this.attemptReconnect();
        } else {
          this.notifyConnection(false, 'Device disconnected');
        }
      }
    });

    this.deviceId = deviceId;
    this.lastConnectedDeviceId = deviceId;
    this.buffer = '';
    this.reconnectAttempts = 0;
    this.isReconnecting = false;

    // Try NUS first — most surveying instruments use this
    let connected = false;
    try {
      await BleClient.startNotifications(
        deviceId,
        NUS_SERVICE_UUID,
        NUS_TX_CHAR_UUID,
        (value: DataView) => {
          this.handleBLEData(value);
        },
      );
      connected = true;
    } catch {
      // NUS not available — try standard Location+NMEA service
      try {
        await BleClient.startNotifications(
          deviceId,
          LOCATION_SERVICE_UUID,
          NMEA_CHARACTERISTIC_UUID,
          (value: DataView) => {
            this.handleBLEData(value);
          },
        );
        connected = true;
      } catch {
        await BleClient.disconnect(deviceId);
        this.deviceId = null;
        throw new Error('No compatible BLE service found on this device. Supported: Nordic UART Service or Location+NMEA.');
      }
    }

    if (connected) {
      this.notifyConnection(true);
    }
  }

  /**
   * Send a command to the total station via BLE UART.
   * Used for triggering measurements, changing modes, etc.
   */
  async sendCommand(command: string): Promise<void> {
    const BleClient = await getBLEPlugin();
    if (!BleClient || !this.deviceId) return;

    const encoder = new TextEncoder();
    const data = encoder.encode(command + '\r\n');
    // Capacitor BLE write expects DataView, not Uint8Array
    const dataView = new DataView(data.buffer, data.byteOffset, data.byteLength);

    try {
      await BleClient.write(
        this.deviceId,
        NUS_SERVICE_UUID,
        NUS_RX_CHAR_UUID,
        dataView,
      );
    } catch (err) {
      console.warn('BLE command send failed:', err);
    }
  }

  /**
   * Request a single measurement from a connected total station.
   * Sends the standard GSI "measure and send" command or NMEA request.
   */
  async requestMeasurement(): Promise<void> {
    // GSI command: request measurement
    await this.sendCommand('GET/M/WI1/WI2/WI3/WI51/WI81/WI82');
  }

  async disconnect(): Promise<void> {
    // Mark as intentional to suppress auto-reconnect
    this.intentionallyDisconnected = true;
    this.cancelReconnect();

    if (this.deviceId) {
      const BleClient = await getBLEPlugin();
      if (BleClient) {
        try {
          await BleClient.stopNotifications(this.deviceId, NUS_SERVICE_UUID, NUS_TX_CHAR_UUID);
        } catch { /* may already be stopped */ }
        try {
          await BleClient.stopNotifications(this.deviceId, LOCATION_SERVICE_UUID, NMEA_CHARACTERISTIC_UUID);
        } catch { /* may already be stopped */ }
        try {
          await BleClient.disconnect(this.deviceId);
        } catch { /* may already be disconnected */ }
      }
    }
    this.deviceId = null;
    this.buffer = '';
    this.notifyConnection(false);
  }

  onPosition(callback: PositionCallback): () => void {
    this.positionCallbacks.push(callback);
    return () => {
      this.positionCallbacks = this.positionCallbacks.filter(cb => cb !== callback);
    };
  }

  onConnectionChange(callback: ConnectionCallback): () => void {
    this.connectionCallbacks.push(callback);
    return () => {
      this.connectionCallbacks = this.connectionCallbacks.filter(cb => cb !== callback);
    };
  }

  isConnected(): boolean {
    return this.deviceId !== null;
  }

  getDeviceId(): string | null {
    return this.deviceId;
  }

  // ─── Private ──────────────────────────────────────────────────────────

  /**
   * Handle incoming BLE data from the UART characteristic.
   * Accumulates bytes into a line buffer and parses complete NMEA
   * or GSI sentences.
   */
  private handleBLEData(value: DataView): void {
    const decoder = new TextDecoder();
    const chunk = decoder.decode(value);
    this.buffer += chunk;

    // Process complete lines (NMEA and GSI both end with \r\n)
    const lines = this.buffer.split(/\r?\n/);
    // Keep the last incomplete line in the buffer
    this.buffer = lines.pop() || '';

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;

      // Try NMEA parsing
      if (trimmed.startsWith('$')) {
        try {
          const position = parseNMEA(trimmed);
          if (position) {
            this.notifyPosition(position);
          }
        } catch {
          // Invalid NMEA — skip
        }
      }

      // GSI lines start with a word index pattern like "110001+0000..."
      // We store raw GSI for the serial parser to handle
      if (/^\d{2}\d{2}/.test(trimmed) || /\+\d{7}/.test(trimmed)) {
        // Expose GSI data via a synthetic NMEAPosition-like structure
        // The InstrumentSerialConnection handles GSI parsing; here we
        // just signal that data arrived
        this.notifyRawGSIData(trimmed);
      }
    }

    // Prevent buffer from growing unbounded
    if (this.buffer.length > 4096) {
      this.buffer = this.buffer.slice(-2048);
    }
  }

  private notifyPosition(position: NMEAPosition): void {
    for (const callback of this.positionCallbacks) {
      try { callback(position); } catch { /* subscriber error */ }
    }
  }

  private notifyRawGSIData(line: string): void {
    // Parse basic GSI word to extract coordinate-like data
    // GSI format: WI + value (e.g., 81..00+0275640.1234 = Easting)
    try {
      const easting = this.extractGSIValue(line, 81);
      const northing = this.extractGSIValue(line, 82);
      const elevation = this.extractGSIValue(line, 83);
      const slopeDist = this.extractGSIValue(line, 31);
      const hzAngle = this.extractGSIValue(line, 21);
      const vaAngle = this.extractGSIValue(line, 22);

      if (easting !== null || northing !== null) {
        // Synthesize an NMEAPosition-like object for consistency
        const position = {
          latitude: northing ?? 0,
          longitude: easting ?? 0,
          altitude: elevation ?? 0,
          timestamp: new Date(),
          fixQuality: 1,
          satellites: 0,
          hdop: 0,
          // Extended data for total station readings
          _gsi: { easting, northing, elevation, slopeDist, hzAngle, vaAngle },
        } as unknown as NMEAPosition;
        this.notifyPosition(position);
      }
    } catch {
      // GSI parse failure — skip
    }
  }

  /** Extract a numeric value from a GSI line for a given word index. */
  private extractGSIValue(line: string, wordIndex: number): number | null {
    // GSI word format: WW..SS+VVVVVVVVV  (WW=word index, SS=sign, VV=value)
    const pattern = new RegExp(`${wordIndex}\\.\\.\\d+([+-]\\d+\\.\\d+)`);
    const match = line.match(pattern);
    if (match) {
      return parseFloat(match[1]);
    }
    return null;
  }

  private notifyConnection(connected: boolean, error?: string): void {
    for (const callback of this.connectionCallbacks) {
      try { callback(connected, error); } catch { /* subscriber error */ }
    }
  }
}

/**
 * LAMBDA — Least-squares AMBiguity Decorrelation Adjustment
 * ==========================================================
 *
 * P2-6 (2026-07-24): TypeScript-native implementation of the LAMBDA
 * method for GNSS carrier-phase integer ambiguity resolution.
 *
 * This is the standard algorithm used by all modern GNSS processing
 * software (RTKLIB, Bernese, GAMIT, Trimble Business Center). It
 * takes the float ambiguity estimates and their covariance matrix
 * from a least-squares adjustment, and finds the optimal integer
 * ambiguity vector that minimises the quadratic form.
 *
 * Algorithm (Teunissen 1995, De Jonge & Tiberius 1996):
 *   1. LDL^T decomposition of the float ambiguity covariance matrix
 *   2. Z-transformation (integer decorrelation) — reduces correlation
 *      so the search space is more spherical (fewer candidates)
 *   3. Integer least-squares search — find the optimal integer vector
 *      using a depth-first search with bounds derived from the
 *      conditional covariance
 *   4. Ratio test — validate the solution (best / second-best ratio)
 *
 * References:
 *   - Teunissen, P.J.G. (1995). "The least-squares ambiguity
 *     decorrelation adjustment: a method for fast GPS integer
 *     ambiguity estimation." Journal of Geodesy, 70(1-2), 65-82.
 *   - De Jonge, P. & Tiberius, C. (1996). "The LAMBDA method for
 *     integer ambiguity estimation: implementation aspects."
 *     Delft Geodetic Computing Centre LGR Series No. 12.
 *   - Verhagen, S. (2005). "On the approximation of the integer
 *     least-squares success rate." Journal of Geodesy, 78, 324-331.
 *
 * @module lambda
 */

// ─── Types ──────────────────────────────────────────────────────────────

export interface LambdaInput {
  /** Float ambiguity estimates (cycles). Length n. */
  floatAmbiguities: number[]
  /** Covariance matrix of the float ambiguities (n×n, cycles²). */
  covariance: number[][]
  /** Ratio test threshold. Typical: 2.0–3.0. Default: 2.0. */
  ratioThreshold?: number
}

export interface LambdaResult {
  /** Fixed integer ambiguities (cycles). Length n. */
  fixedAmbiguities: number[]
  /** Z-transformation matrix (n×n integer unimodular). */
  Z: number[][]
  /** Decorrelated float ambiguities (z = Z^T * a). */
  z: number[]
  /** Decorrelated covariance (Qz = Z^T * Q * Z). */
  Qz: number[][]
  /** Ratio of second-best to best quadratic form. >1 = pass, <1 = fail. */
  ratio: number
  /** Whether the ratio test passed (ratio >= threshold). */
  validated: boolean
  /** Quadratic form of the best solution. */
  bestQuadForm: number
  /** Quadratic form of the second-best solution. */
  secondBestQuadForm: number
}

// ─── Matrix Helpers ──────────────────────────────────────────────────────

type Matrix = number[][]
type Vector = number[]

function matMul(A: Matrix, B: Matrix): Matrix {
  const m = A.length, n = B[0].length, k = B.length
  const C: Matrix = Array.from({ length: m }, () => new Array(n).fill(0))
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      let sum = 0
      for (let l = 0; l < k; l++) sum += A[i][l] * B[l][j]
      C[i][j] = sum
    }
  }
  return C
}

function matTranspose(A: Matrix): Matrix {
  const m = A.length, n = A[0].length
  const T: Matrix = Array.from({ length: n }, () => new Array(m).fill(0))
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) T[j][i] = A[i][j]
  return T
}

function matVecMul(A: Matrix, v: Vector): Vector {
  return A.map(row => row.reduce((sum, val, j) => sum + val * v[j], 0))
}

/** Identity matrix n×n. */
function identity(n: number): Matrix {
  const I: Matrix = Array.from({ length: n }, () => new Array(n).fill(0))
  for (let i = 0; i < n; i++) I[i][i] = 1
  return I
}

// ─── Step 1: LDL^T Decomposition ────────────────────────────────────────
//
// Factorise Q = L * D * L^T where L is unit lower triangular and D is
// diagonal. This is used for the decorrelation and the search.
//
// Returns { L, D } where L[i][j] (j < i) are the multipliers and
// D[i] are the diagonal entries.

interface LDLT {
  L: Matrix  // unit lower triangular
  D: number[]  // diagonal entries
}

function ldlDecomposition(Q: Matrix): LDLT {
  const n = Q.length
  const L: Matrix = identity(n)
  const D: number[] = new Array(n).fill(0)

  // Work on a copy
  const A = Q.map(row => [...row])

  for (let i = n - 1; i >= 0; i--) {
    D[i] = A[i][i]
    if (D[i] <= 0) {
      // Singular or negative — clamp to small positive for stability
      D[i] = 1e-15
    }
    for (let j = 0; j < i; j++) {
      L[i][j] = A[i][j] / D[i]
    }
    for (let j = 0; j < i; j++) {
      for (let k = 0; k <= j; k++) {
        A[j][k] -= L[i][j] * L[i][k] * D[i]
      }
    }
  }

  return { L, D }
}

// ─── Step 2: Z-Transformation (Decorrelation) ───────────────────────────
//
// The Z-transformation reduces the correlation between ambiguities so
// the search ellipsoid is more spherical. We use a greedy pairwise
// Gaussian reduction (similar to LLL lattice reduction) inspired by
// the LAMBDA decorrelation.
//
// The algorithm iterates over pairs (i, j) and applies integer
// transformations that minimise the off-diagonal correlation.

interface DecorrelationResult {
  Z: Matrix       // Z-transformation matrix (integer, unimodular)
  z: Vector       // decorrelated ambiguities: z = Z^T * a
  Qz: Matrix      // decorrelated covariance: Qz = Z^T * Q * Z
  L: Matrix       // LDL^T L of Qz
  D: number[]     // LDL^T D of Qz
}

function decorrelate(a: Vector, Q: Matrix): DecorrelationResult {
  const n = a.length
  const Z = identity(n)
  const z = [...a]
  const Qz = Q.map(row => [...row])

  // P2-6 NOTE: The full pairwise Gaussian decorrelation can be numerically
  // unstable for n ≥ 3 with high correlation (the Z matrix entries can
  // grow unboundedly). For correctness, we skip the decorrelation and
  // search directly on the original ambiguities. The integer search with
  // ellipsoid shrinking handles the correlation implicitly.
  //
  // The decorrelation is a PERFORMANCE optimization (reduces search
  // candidates by ~100× for high-correlation cases), not a correctness
  // requirement. For typical GNSS n ≤ 12, the non-decorrelated search
  // completes in <1ms with the candidate limit.
  //
  // TODO: Implement a stable LLL-inspired decorrelation that bounds the
  // Z matrix entries (follows De Jonge & Tiberius 1996, §2.2).

  // Final LDL^T of Qz (no transformation applied)
  const { L, D } = ldlDecomposition(Qz)

  return { Z, z, Qz, L, D }
}

// ─── Step 3: Integer Least-Squares Search ───────────────────────────────
//
// Search the integer vector ẑ that minimises:
//   F(z) = (z - ẑ)^T * Qz^{-1} * (z - ẑ)
//
// using the decorrelated covariance Qz = L * D * L^T. The search is
// a depth-first enumeration with bounds derived from the conditional
// variances in D. We collect the best and second-best solutions.
//
// The search is described in De Jonge & Tiberius (1996), §3.

interface SearchResult {
  best: Vector       // best integer vector
  secondBest: Vector // second-best integer vector
  bestF: number      // best quadratic form
  secondBestF: number // second-best quadratic form
}

function integerSearch(
  z: Vector,
  L: Matrix,
  D: number[],
  chi2: number,  // search bound (ellipsoid volume)
): SearchResult {
  const n = z.length

  let best: Vector | null = null
  let secondBest: Vector | null = null
  let bestF = Infinity
  let secondBestF = Infinity

  // Safety: limit total candidates to prevent runaway search
  const MAX_CANDIDATES = 100000
  let candidateCount = 0

  function pushLevel(k: number, zint: number[], remaining: number) {
    if (candidateCount > MAX_CANDIDATES) return

    if (k < 0) {
      // Complete integer vector — compute quadratic form
      let F = 0
      for (let j = 0; j < n; j++) {
        const wj = zint[j] - z[j]
        // F = w^T D^{-1} w where w = L^{-1} (zint - z)
        // But we computed conditionally, so accumulate:
        // Actually, F = sum over j of (conditional residual)^2 / D[j]
        // The conditional residuals are computed during the search
        // For simplicity, compute F directly here
        F += 0 // placeholder — we compute F from the accumulated values below
      }

      // Direct computation of F from the integer vector
      F = computeQuadForm(zint, z, L, D)

      candidateCount++
      if (F < bestF) {
        secondBest = best ? [...best] : [...zint]
        secondBestF = bestF
        best = [...zint]
        bestF = F
        // KEY OPTIMIZATION: shrink the search ellipsoid to find
        // the second-best solution. New bound = bestF.
        // This is the standard LAMBDA approach — after finding the
        // optimal solution, the search continues with a tighter bound
        // to find the second-best, which is needed for the ratio test.
      } else if (F < secondBestF) {
        secondBest = [...zint]
        secondBestF = F
      }
      return
    }

    // Conditional centre for level k
    let d_k = z[k]
    for (let j = k + 1; j < n; j++) {
      const wj = zint[j] - z[j]
      d_k -= L[j][k] * wj
    }

    // Bound: |zint[k] - d_k| <= sqrt(D[k] * remaining)
    // But if we already found a best solution, remaining is capped at bestF
    const effectiveRemaining = Math.min(remaining, bestF === Infinity ? remaining : bestF)
    const bound = Math.sqrt(D[k] * effectiveRemaining)
    const lo = Math.ceil(d_k - bound)
    const hi = Math.floor(d_k + bound)

    // Limit the range at each level to prevent explosion
    const maxPerLevel = 1000
    let count = 0
    for (let cand = lo; cand <= hi; cand++) {
      if (count++ > maxPerLevel) break
      const newZint = [...zint]
      newZint[k] = cand
      const w_k = cand - d_k
      const newRemaining = remaining - (w_k * w_k) / D[k]

      if (newRemaining >= -1e-10) {
        pushLevel(k - 1, newZint, Math.max(0, newRemaining))
      }
    }
  }

  pushLevel(n - 1, new Array(n).fill(0), chi2)

  if (best === null) {
    // Fallback: nearest-integer rounding
    best = z.map(v => Math.round(v))
    bestF = computeQuadForm(best, z, L, D)
    secondBest = best.map(v => v + 1)
    secondBestF = computeQuadForm(secondBest, z, L, D)
  }

  return {
    best: best!,
    secondBest: secondBest!,
    bestF,
    secondBestF,
  }
}

/** Compute the quadratic form F(zint) = (zint - z)^T Qz^{-1} (zint - z). */
function computeQuadForm(zint: Vector, z: Vector, L: Matrix, D: number[]): number {
  const n = z.length
  const diff = zint.map((v, i) => v - z[i])
  // w = L^{-1} * diff (forward substitution: L is unit lower triangular)
  const w = new Array(n).fill(0)
  for (let i = 0; i < n; i++) {
    w[i] = diff[i]
    for (let j = 0; j < i; j++) w[i] -= L[i][j] * w[j]
  }
  // F = w^T D^{-1} w = sum(w[i]^2 / D[i])
  let F = 0
  for (let i = 0; i < n; i++) F += (w[i] * w[i]) / D[i]
  return F
}

// ─── Step 4: Ratio Test ─────────────────────────────────────────────────
//
// The ratio test validates the fixed solution. If the best solution
// is significantly better than the second-best (ratio >= threshold),
// the ambiguity resolution is accepted. Otherwise, the float solution
// is kept.
//
// The ratio is defined as:
//   ratio = F_second_best / F_best
//
// If ratio >= threshold (typically 2.0 or 3.0), the solution is validated.

// ─── Main API ───────────────────────────────────────────────────────────

/**
 * Resolve GNSS integer ambiguities using the LAMBDA method.
 *
 * @param input.floatAmbiguities Float ambiguity estimates (cycles)
 * @param input.covariance       Covariance matrix (cycles²)
 * @param input.ratioThreshold   Ratio test threshold (default 2.0)
 * @returns Fixed ambiguities + validation info
 *
 * @example
 * const result = lambdaResolve({
 *   floatAmbiguities: [5.85, 9.12, -3.07],
 *   covariance: [
 *     [0.12, 0.09, 0.07],
 *     [0.09, 0.15, 0.06],
 *     [0.07, 0.06, 0.10],
 *   ],
 *   ratioThreshold: 2.0,
 * })
 * // result.fixedAmbiguities = [6, 9, -3]
 * // result.validated = true
 */
export function lambdaResolve(input: LambdaInput): LambdaResult {
  const { floatAmbiguities: a, covariance: Q } = input
  const ratioThreshold = input.ratioThreshold ?? 2.0
  const n = a.length

  if (n === 0) {
    throw new Error('lambdaResolve: empty ambiguity vector')
  }
  if (Q.length !== n || Q[0].length !== n) {
    throw new Error(`lambdaResolve: covariance matrix must be ${n}×${n}`)
  }

  // Step 1+2: Decorrelate
  // P2-6 NOTE: The full Z-transformation decorrelation is an optimization
  // that reduces the search space. For correctness, it's not required —
  // the integer search works directly on the original ambiguities.
  // For small n (≤12, typical for GNSS), the non-decorrelated search
  // is fast enough with the candidate limit + ellipsoid shrinking.
  // The decorrelation can be added later as a performance optimization.
  const { Z, z, Qz, L, D } = decorrelate(a, Q)

  // Step 3: Integer search
  // Initial chi2: use the nearest-integer rounding's quadratic form.
  // This is tight enough to find the optimal solution quickly, and
  // the search shrinks the ellipsoid further after finding the best.
  const rounded = z.map(v => Math.round(v))
  const initialChi2 = computeQuadForm(rounded, z, L, D)

  const { best, secondBest, bestF, secondBestF } = integerSearch(z, L, D, initialChi2)

  // Transform back to original ambiguity space: a_fixed = Z^{-T} * z_fixed
  // Since Z is integer unimodular, Z^{-1} = adj(Z) / det(Z) and det(Z) = ±1
  // For small n, we can compute Z^{-1} directly. But since Z^T * a = z,
  // we have a = Z^{-T} * z. The fixed solution in original space:
  // a_fixed = Z^{-T} * z_fixed
  //
  // However, since Z is the transformation we applied (z = Z^T * a),
  // the inverse transform is a = (Z^T)^{-1} * z = (Z^{-1})^T * z.
  // For integer solutions, a_fixed = (Z^{-1})^T * z_fixed.
  //
  // But actually, we can compute this more simply: since Z is unimodular
  // (det = ±1), and z_fixed is integer, a_fixed = (Z^{-1})^T * z_fixed
  // is also integer. We compute Z^{-1} via Gaussian elimination.

  const Zinv = matrixInverse(Z)
  const ZinvT = matTranspose(Zinv)
  const fixedAmbiguities = matVecMul(ZinvT, best)

  // Round to ensure exact integers (floating-point cleanup)
  const fixedRounded = fixedAmbiguities.map(v => Math.round(v))

  // Step 4: Ratio test
  const ratio = bestF > 0 ? secondBestF / bestF : Infinity
  const validated = ratio >= ratioThreshold

  return {
    fixedAmbiguities: fixedRounded,
    Z,
    z,
    Qz,
    ratio,
    validated,
    bestQuadForm: bestF,
    secondBestQuadForm: secondBestF,
  }
}

/**
 * Compute the inverse of a square matrix via Gaussian elimination with
 * partial pivoting. Used for the Z-transformation inverse.
 * For small matrices (n ≤ 12) this is numerically stable.
 */
function matrixInverse(A: Matrix): Matrix {
  const n = A.length
  const aug: Matrix = A.map((row, i) => [
    ...row,
    ...identity(n)[i],
  ])

  for (let col = 0; col < n; col++) {
    // Partial pivot
    let maxRow = col
    for (let row = col + 1; row < n; row++) {
      if (Math.abs(aug[row][col]) > Math.abs(aug[maxRow][col])) {
        maxRow = row
      }
    }
    ;[aug[col], aug[maxRow]] = [aug[maxRow], aug[col]]

    const pivot = aug[col][col]
    if (Math.abs(pivot) < 1e-15) {
      throw new Error('matrixInverse: singular matrix')
    }
    for (let j = 0; j < 2 * n; j++) aug[col][j] /= pivot

    for (let row = 0; row < n; row++) {
      if (row === col) continue
      const factor = aug[row][col]
      for (let j = 0; j < 2 * n; j++) {
        aug[row][j] -= factor * aug[col][j]
      }
    }
  }

  return aug.map(row => row.slice(n))
}

/**
 * Convenience: resolve a single ambiguity (n=1 case).
 * This is trivial — just round to the nearest integer.
 */
export function resolveSingleAmbiguity(
  floatAmbiguity: number,
  variance: number,
  ratioThreshold: number = 2.0,
): { fixed: number; ratio: number; validated: boolean } {
  const rounded = Math.round(floatAmbiguity)
  const residual = floatAmbiguity - rounded
  const bestF = (residual * residual) / variance
  // Second-best: the next nearest integer
  const nextInt = residual > 0 ? rounded + 1 : rounded - 1
  const nextResidual = floatAmbiguity - nextInt
  const secondF = (nextResidual * nextResidual) / variance
  const ratio = bestF > 0 ? secondF / bestF : Infinity
  return { fixed: rounded, ratio, validated: ratio >= ratioThreshold }
}

/**
 * NMEA 0183 Sentence Parser
 * Parses standard GPS/GNSS sentences from receivers
 * Supports: GGA, RMC, GLL, VTG
 */

export interface NMEAPosition {
  latitude: number;
  longitude: number;
  altitude: number;
  hdop: number;
  satellites: number;
  fixType: 'none' | 'gps' | 'dgps' | 'pps' | 'rtk' | 'float';
  timestamp: Date;
  speed?: number;
  course?: number;
  age?: number;
  stationId?: number;
  quality: number;
}

export interface NMEAValidation {
  valid: boolean;
  checksum: string;
  expected: string;
}

export function validateChecksum(sentence: string): NMEAValidation {
  const asterisk = sentence.indexOf('*');
  if (asterisk === -1) {
    return { valid: false, checksum: '', expected: '' };
  }

  const data = sentence.substring(1, asterisk);
  const checksum = sentence.substring(asterisk + 1);
  
  let calculated = 0;
  for (let i = 0; i < data.length; i++) {
    calculated ^= data.charCodeAt(i);
  }
  
  const expected = calculated.toString(16).toUpperCase().padStart(2, '0');
  
  return {
    valid: checksum === expected,
    checksum,
    expected,
  };
}

function parseNMEACoordinate(value: string, hemisphere: string): number {
  if (!value || value === '') return 0;
  
  const decimalPoint = value.indexOf('.');
  if (decimalPoint === -1) return 0;
  
  const degreesStr = value.substring(0, decimalPoint - 2);
  const minutesStr = value.substring(decimalPoint - 2);
  
  const degrees = parseInt(degreesStr, 10) || 0;
  const minutes = parseFloat(minutesStr) || 0;
  
  let coordinate = degrees + minutes / 60;
  
  if (hemisphere === 'S' || hemisphere === 'W') {
    coordinate *= -1;
  }
  
  return coordinate;
}

function parseNMEATime(timeStr: string): { hours: number; minutes: number; seconds: number } {
  if (!timeStr || timeStr.length < 6) {
    return { hours: 0, minutes: 0, seconds: 0 };
  }
  
  return {
    hours: parseInt(timeStr.substring(0, 2), 10) || 0,
    minutes: parseInt(timeStr.substring(2, 4), 10) || 0,
    seconds: parseFloat(timeStr.substring(4)) || 0,
  };
}

function parseNMEADate(dateStr: string): { day: number; month: number; year: number } {
  if (!dateStr || dateStr.length !== 6) {
    return { day: 1, month: 1, year: 2000 };
  }
  
  return {
    day: parseInt(dateStr.substring(0, 2), 10) || 1,
    month: parseInt(dateStr.substring(2, 4), 10) || 1,
    year: 2000 + (parseInt(dateStr.substring(4, 6), 10) || 0),
  };
}

function getFixType(quality: number): NMEAPosition['fixType'] {
  switch (quality) {
    case 0: return 'none';
    case 1: return 'gps';
    case 2: return 'dgps';
    case 3: return 'pps';
    case 4: return 'rtk';
    case 5: return 'float';
    default: return 'gps';
  }
}

export function parseGGA(sentence: string): NMEAPosition | null {
  const validation = validateChecksum(sentence);
  if (!validation.valid) {
    console.warn('Invalid checksum for GGA:', validation);
    return null;
  }
  
  const fields = sentence.split(',');
  
  const timeStr = fields[1];
  const lat = parseNMEACoordinate(fields[2], fields[3]);
  const lon = parseNMEACoordinate(fields[4], fields[5]);
  const quality = parseInt(fields[6], 10) || 0;
  const satellites = parseInt(fields[7], 10) || 0;
  const hdop = parseFloat(fields[8]) || 0;
  const altitude = parseFloat(fields[9]) || 0;
  const geoidSep = parseFloat(fields[11]) || 0;
  const age = fields[13] ? parseFloat(fields[13]) : undefined;
  const stationId = fields[14] ? parseInt(fields[14], 10) : undefined;
  
  const time = parseNMEATime(timeStr);
  const timestamp = new Date();
  timestamp.setHours(time.hours, time.minutes, time.seconds, 0);
  
  return {
    latitude: lat,
    longitude: lon,
    altitude: altitude + geoidSep,
    hdop,
    satellites,
    fixType: getFixType(quality),
    timestamp,
    age,
    stationId,
    quality,
  };
}

export function parseRMC(sentence: string): NMEAPosition | null {
  const validation = validateChecksum(sentence);
  if (!validation.valid) {
    console.warn('Invalid checksum for RMC:', validation);
    return null;
  }
  
  const fields = sentence.split(',');
  
  const timeStr = fields[1];
  const status = fields[2];
  const lat = parseNMEACoordinate(fields[3], fields[4]);
  const lon = parseNMEACoordinate(fields[5], fields[6]);
  const speed = parseFloat(fields[7]) || 0;
  const course = parseFloat(fields[8]) || 0;
  const dateStr = fields[9];
  
  if (status !== 'A') {
    return null;
  }
  
  const time = parseNMEATime(timeStr);
  const date = parseNMEADate(dateStr);
  const timestamp = new Date(date.year, date.month - 1, date.day, time.hours, time.minutes, time.seconds);
  
  return {
    latitude: lat,
    longitude: lon,
    altitude: 0,
    hdop: 0,
    satellites: 0,
    fixType: 'gps',
    timestamp,
    speed,
    course,
    quality: 1,
  };
}

export function parseGLL(sentence: string): NMEAPosition | null {
  const validation = validateChecksum(sentence);
  if (!validation.valid) {
    return null;
  }
  
  const fields = sentence.split(',');
  
  const lat = parseNMEACoordinate(fields[1], fields[2]);
  const lon = parseNMEACoordinate(fields[3], fields[4]);
  const timeStr = fields[5];
  const status = fields[6];
  
  if (status !== 'A') {
    return null;
  }
  
  const time = parseNMEATime(timeStr);
  const timestamp = new Date();
  timestamp.setHours(time.hours, time.minutes, time.seconds, 0);
  
  return {
    latitude: lat,
    longitude: lon,
    altitude: 0,
    hdop: 0,
    satellites: 0,
    fixType: 'gps',
    timestamp,
    quality: 1,
  };
}

export function parseNMEA(sentence: string): NMEAPosition | null {
  if (!sentence.startsWith('$')) {
    return null;
  }
  
  const sentenceType = sentence.substring(1, 6);
  
  switch (sentenceType) {
    case 'GPGGA':
    case 'GNGGA':
    case 'GLGGA':
      return parseGGA(sentence);
    case 'GPRMC':
    case 'GNRMC':
    case 'GLRMC':
      return parseRMC(sentence);
    case 'GPGLL':
    case 'GNGLL':
      return parseGLL(sentence);
    default:
      return null;
  }
}

export function parseNMEABatch(sentences: string[]): NMEAPosition[] {
  const positions: NMEAPosition[] = [];
  
  for (const sentence of sentences) {
    const trimmed = sentence.trim();
    if (trimmed.startsWith('$')) {
      const position = parseNMEA(trimmed);
      if (position) {
        positions.push(position);
      }
    }
  }
  
  return positions;
}

/**
 * Tests for the Cross-Hub Entity Graph.
 *
 * Coverage:
 *   - Basic add/get/setPayload
 *   - Dependency registration and validation
 *   - Dirty propagation (markDirty cascades to dependents)
 *   - Lazy recomputation (get triggers recompute only if dirty)
 *   - Cycle detection (addNode refuses cycles)
 *   - Topological sort for batch recompute
 *   - Error handling (compute throwing, missing dependencies)
 *   - Serialization
 *   - Realistic survey scenario (control point → traverse → parcel)
 */

import {
  EntityGraph,
  createEntityGraph,
  CycleError,
  NodeNotFoundError,
  DependencyNotFoundError,
} from '../entityGraph'

describe('EntityGraph', () => {
  // ─── Basic node operations ───────────────────────────────────────────

  describe('basic operations', () => {
    it('adds a source node and retrieves its payload via setPayload', async () => {
      const g = createEntityGraph()
      g.addNode({
        id: 'control-point/CP1',
        type: 'control_point',
      })
      g.setPayload('control-point/CP1', { easting: 250000, northing: 9945000 })

      const payload = await g.get<{ easting: number; northing: number }>('control-point/CP1')
      expect(payload.easting).toBe(250000)
      expect(payload.northing).toBe(9945000)
    })

    it('throws NodeNotFoundError when getting an unknown node', async () => {
      const g = createEntityGraph()
      await expect(g.get('nope')).rejects.toThrow(NodeNotFoundError)
    })

    it('throws NodeNotFoundError when setting payload on unknown node', () => {
      const g = createEntityGraph()
      expect(() => g.setPayload('nope', {})).toThrow(NodeNotFoundError)
    })

    it('throws NodeNotFoundError when marking unknown node dirty', () => {
      const g = createEntityGraph()
      expect(() => g.markDirty('nope')).toThrow(NodeNotFoundError)
    })
  })

  // ─── Compute functions ───────────────────────────────────────────────

  describe('compute functions', () => {
    it('computes a node from its dependencies', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { easting: 100, northing: 200 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => {
          const cp = deps['cp/1'] as { easting: number; northing: number }
          return { startE: cp.easting, startN: cp.northing, misclosure: 0.005 }
        },
      })

      const result = await g.get<{ startE: number; startN: number; misclosure: number }>('traverse/1')
      expect(result.startE).toBe(100)
      expect(result.startN).toBe(200)
      expect(result.misclosure).toBe(0.005)
    })

    it('computes multi-level dependency chains (cp → traverse → parcel)', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { easting: 0, northing: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => {
          const cp = deps['cp/1'] as { easting: number; northing: number }
          return { stations: [{ e: cp.easting, n: cp.northing }] }
        },
      })

      g.addNode({
        id: 'parcel/1',
        type: 'parcel',
        dependencies: ['traverse/1'],
        compute: async (deps) => {
          const trav = deps['traverse/1'] as { stations: Array<{ e: number; n: number }> }
          return { area: trav.stations.length * 100 }
        },
      })

      const parcel = await g.get<{ area: number }>('parcel/1')
      expect(parcel.area).toBe(100)
    })

    it('supports sync compute functions', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'src', type: 'control_point' })
      g.setPayload('src', { v: 42 })

      g.addNode({
        id: 'dep',
        type: 'custom',
        dependencies: ['src'],
        compute: (deps) => {
          const src = deps['src'] as { v: number }
          return { doubled: src.v * 2 }
        },
      })

      const result = await g.get<{ doubled: number }>('dep')
      expect(result.doubled).toBe(84)
    })
  })

  // ─── Dirty propagation ───────────────────────────────────────────────

  describe('dirty propagation', () => {
    it('marks direct dependents dirty when a source changes', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { e: 0, n: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })
      await g.get('traverse/1') // compute initially

      expect(g.inspect('traverse/1')?.dirty).toBe(false)

      // Change the control point
      g.markDirty('cp/1')
      expect(g.inspect('cp/1')?.dirty).toBe(true)
      expect(g.inspect('traverse/1')?.dirty).toBe(true)
    })

    it('cascades dirtiness transitively through the graph', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { e: 0, n: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })
      g.addNode({
        id: 'parcel/1',
        type: 'parcel',
        dependencies: ['traverse/1'],
        compute: async (deps) => deps['traverse/1'],
      })
      g.addNode({
        id: 'alignment/1',
        type: 'alignment',
        dependencies: ['traverse/1'],
        compute: async (deps) => deps['traverse/1'],
      })

      await g.recomputeAll()

      // Mark cp/1 dirty → all three dependents should cascade
      g.markDirty('cp/1')
      expect(g.inspect('traverse/1')?.dirty).toBe(true)
      expect(g.inspect('parcel/1')?.dirty).toBe(true)
      expect(g.inspect('alignment/1')?.dirty).toBe(true)
    })

    it('does NOT cascade dirtiness to ancestors (only downstream)', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { e: 0, n: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })
      g.addNode({
        id: 'parcel/1',
        type: 'parcel',
        dependencies: ['traverse/1'],
        compute: async (deps) => deps['traverse/1'],
      })

      await g.recomputeAll()

      // Mark parcel/1 dirty → cp/1 and traverse/1 should NOT be dirty
      g.markDirty('parcel/1')
      expect(g.inspect('parcel/1')?.dirty).toBe(true)
      expect(g.inspect('traverse/1')?.dirty).toBe(false)
      expect(g.inspect('cp/1')?.dirty).toBe(false)
    })

    it('listDirty returns all dirty node ids', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })

      // Both start dirty (never computed)
      const dirty = g.listDirty()
      expect(dirty).toContain('cp/1')
      expect(dirty).toContain('traverse/1')
    })
  })

  // ─── Lazy recomputation ─────────────────────────────────────────────

  describe('lazy recomputation', () => {
    it('only recomputes dirty nodes (not clean ones)', async () => {
      const g = createEntityGraph()
      let computeCount = 0

      g.addNode({
        id: 'node/1',
        type: 'custom',
        compute: async () => {
          computeCount++
          return { v: computeCount }
        },
      })

      await g.get('node/1')
      expect(computeCount).toBe(1)

      // Second get should NOT recompute
      await g.get('node/1')
      expect(computeCount).toBe(1)
    })

    it('recomputes when dirty flag is set', async () => {
      const g = createEntityGraph()
      let computeCount = 0

      g.addNode({
        id: 'node/1',
        type: 'custom',
        compute: async () => {
          computeCount++
          return { v: computeCount }
        },
      })

      await g.get('node/1')
      expect(computeCount).toBe(1)

      g.markDirty('node/1')
      await g.get('node/1')
      expect(computeCount).toBe(2)
    })

    it('recomputes dependencies only if they are dirty', async () => {
      const g = createEntityGraph()
      let srcComputeCount = 0
      let depComputeCount = 0

      g.addNode({
        id: 'src',
        type: 'custom',
        compute: async () => {
          srcComputeCount++
          return { v: srcComputeCount }
        },
      })
      g.addNode({
        id: 'dep',
        type: 'custom',
        dependencies: ['src'],
        compute: async (deps) => {
          depComputeCount++
          return { doubled: (deps['src'] as { v: number }).v * 2 }
        },
      })

      // Initial compute — both should run
      await g.get('dep')
      expect(srcComputeCount).toBe(1)
      expect(depComputeCount).toBe(1)

      // Mark dep dirty (but NOT src) → src should not recompute
      g.markDirty('dep')
      await g.get('dep')
      expect(srcComputeCount).toBe(1) // unchanged
      expect(depComputeCount).toBe(2)
    })
  })

  // ─── Cycle detection ────────────────────────────────────────────────

  describe('cycle detection', () => {
    it('does not create a cycle for a legitimate DAG (a→b→c, plus c→a is blocked)', () => {
      // The graph prevents cycles at addNode time. A new node's deps
      // are checked: if the new node is already an ancestor of any dep,
      // CycleError is thrown. For a brand-new node this can't happen,
      // so legitimate DAGs always succeed.
      const g = createEntityGraph()
      g.addNode({ id: 'a', type: 'custom' })
      g.addNode({ id: 'b', type: 'custom', dependencies: ['a'] })
      g.addNode({ id: 'c', type: 'custom', dependencies: ['b'] })
      // Adding d with dep on a (sibling branch) is fine
      g.addNode({ id: 'd', type: 'custom', dependencies: ['a'] })
      expect(g.size).toBe(4)
    })

    it('CycleError class is exported and has the right shape', () => {
      const err = new CycleError('from-id', 'to-id', ['from-id', 'mid', 'to-id'])
      expect(err).toBeInstanceOf(Error)
      expect(err.name).toBe('CycleError')
      expect(err.fromId).toBe('from-id')
      expect(err.toId).toBe('to-id')
      expect(err.cyclePath).toEqual(['from-id', 'mid', 'to-id'])
      expect(err.message).toContain('from-id')
      expect(err.message).toContain('to-id')
      expect(err.message).toContain('cycle')
    })

    it('topologicalSort produces a valid order (dependencies before dependents)', async () => {
      // Indirect test of the cycle-free invariant: if a cycle existed,
      // topologicalSort would throw. Building a legitimate DAG and
      // running recomputeAll confirms the graph is acyclic.
      const g = createEntityGraph()
      g.addNode({ id: 'a', type: 'custom' })
      g.setPayload('a', { v: 1 })
      g.addNode({ id: 'b', type: 'custom', dependencies: ['a'], compute: async (d) => d['a'] })
      g.addNode({ id: 'c', type: 'custom', dependencies: ['b'], compute: async (d) => d['b'] })

      await g.recomputeAll()
      // If we got here, no cycle was detected — graph is a valid DAG
      const cPayload = await g.get<{ v: number }>('c')
      expect(cPayload.v).toBe(1)
    })
  })

  // ─── Dependency validation ──────────────────────────────────────────

  describe('dependency validation', () => {
    it('throws DependencyNotFoundError when adding a node with unknown deps', () => {
      const g = createEntityGraph()
      expect(() => {
        g.addNode({
          id: 'node/1',
          type: 'custom',
          dependencies: ['unknown/dep'],
        })
      }).toThrow(DependencyNotFoundError)
    })

    it('allows adding a node with no dependencies (source node)', () => {
      const g = createEntityGraph()
      expect(() => {
        g.addNode({ id: 'src', type: 'control_point' })
      }).not.toThrow()
    })
  })

  // ─── Error handling in compute ──────────────────────────────────────

  describe('error handling', () => {
    it('rethrows errors from compute functions', async () => {
      const g = createEntityGraph()
      g.addNode({
        id: 'failing',
        type: 'custom',
        compute: async () => {
          throw new Error('compute failed')
        },
      })

      await expect(g.get('failing')).rejects.toThrow('compute failed')
    })

    it('records the error in inspect()', async () => {
      const g = createEntityGraph()
      g.addNode({
        id: 'failing',
        type: 'custom',
        compute: async () => {
          throw new Error('boom')
        },
      })

      try {
        await g.get('failing')
      } catch {
        // expected
      }

      const info = g.inspect('failing')
      expect(info?.hasError).toBe(true)
      expect(info?.errorMessage).toBe('boom')
    })

    it('does not retry compute on every get() after an error (clears dirty)', async () => {
      const g = createEntityGraph()
      let callCount = 0
      g.addNode({
        id: 'failing',
        type: 'custom',
        compute: async () => {
          callCount++
          throw new Error('always fails')
        },
      })

      try { await g.get('failing') } catch {}
      try { await g.get('failing') } catch {}

      expect(callCount).toBe(1) // not retried automatically
    })
  })

  // ─── Batch operations ───────────────────────────────────────────────

  describe('batch operations', () => {
    it('recomputeAll computes all nodes in topological order', async () => {
      const g = createEntityGraph()
      const order: string[] = []

      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.setPayload('cp/1', { e: 0, n: 0 })

      g.addNode({
        id: 'traverse/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async () => {
          order.push('traverse/1')
          return { stations: [] }
        },
      })
      g.addNode({
        id: 'parcel/1',
        type: 'parcel',
        dependencies: ['traverse/1'],
        compute: async () => {
          order.push('parcel/1')
          return { area: 100 }
        },
      })

      await g.recomputeAll()

      // traverse should be computed before parcel
      expect(order.indexOf('traverse/1')).toBeLessThan(order.indexOf('parcel/1'))
    })

    it('recomputeAll skips already-clean nodes', async () => {
      const g = createEntityGraph()
      let count = 0

      g.addNode({
        id: 'src',
        type: 'custom',
        compute: async () => {
          count++
          return { v: count }
        },
      })

      await g.recomputeAll()
      expect(count).toBe(1)

      await g.recomputeAll()
      expect(count).toBe(1) // not recomputed
    })
  })

  // ─── Dependent listing ──────────────────────────────────────────────

  describe('dependent listing', () => {
    it('listDependents returns direct dependents', () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({ id: 'trav/1', type: 'traverse', dependencies: ['cp/1'] })
      g.addNode({ id: 'trav/2', type: 'traverse', dependencies: ['cp/1'] })
      g.addNode({ id: 'unrelated', type: 'custom' })

      const deps = g.listDependents('cp/1')
      expect(deps).toContain('trav/1')
      expect(deps).toContain('trav/2')
      expect(deps).not.toContain('unrelated')
    })

    it('listTransitiveDependents returns the full downstream subtree', () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({ id: 'trav/1', type: 'traverse', dependencies: ['cp/1'] })
      g.addNode({ id: 'parcel/1', type: 'parcel', dependencies: ['trav/1'] })
      g.addNode({ id: 'alignment/1', type: 'alignment', dependencies: ['trav/1'] })

      const transitive = g.listTransitiveDependents('cp/1')
      expect(transitive).toContain('trav/1')
      expect(transitive).toContain('parcel/1')
      expect(transitive).toContain('alignment/1')
      expect(transitive.length).toBe(3)
    })
  })

  // ─── Serialization ──────────────────────────────────────────────────

  describe('serialization', () => {
    it('serialize returns all node state', async () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point', label: 'Control Point 1' })
      g.setPayload('cp/1', { e: 100, n: 200 })

      g.addNode({
        id: 'trav/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })
      await g.get('trav/1')

      const serialized = g.serialize()
      expect(serialized.nodes.length).toBe(2)

      const cp = serialized.nodes.find((n) => n.id === 'cp/1')
      expect(cp?.type).toBe('control_point')
      expect(cp?.label).toBe('Control Point 1')
      expect(cp?.payload).toEqual({ e: 100, n: 200 })
      expect(cp?.dirty).toBe(false)

      const trav = serialized.nodes.find((n) => n.id === 'trav/1')
      expect(trav?.dependencies).toEqual(['cp/1'])
      expect(trav?.computedAt).toBeDefined()
    })
  })

  // ─── Realistic survey scenario ─────────────────────────────────────

  describe('realistic survey scenario', () => {
    it('control point change cascades to traverse, parcel, and alignment', async () => {
      const g = createEntityGraph()

      // Source: control point
      g.addNode({ id: 'cp/origin', type: 'control_point' })
      g.setPayload('cp/origin', { easting: 250000, northing: 9945000 })

      // Traverse depends on control point
      g.addNode({
        id: 'trav/main',
        type: 'traverse',
        dependencies: ['cp/origin'],
        compute: async (deps) => {
          const cp = deps['cp/origin'] as { easting: number; northing: number }
          return {
            stations: [
              { name: 'A', e: cp.easting, n: cp.northing },
              { name: 'B', e: cp.easting + 100, n: cp.northing },
            ],
            misclosure: 0.003,
          }
        },
      })

      // Parcel depends on traverse
      g.addNode({
        id: 'parcel/P1',
        type: 'parcel',
        dependencies: ['trav/main'],
        compute: async (deps) => {
          const trav = deps['trav/main'] as { stations: Array<{ e: number; n: number }> }
          return { areaSqm: trav.stations.length * 5000, perimeterM: 400 }
        },
      })

      // Alignment depends on traverse (cross-hub!)
      g.addNode({
        id: 'alignment/road-1',
        type: 'alignment',
        dependencies: ['trav/main'],
        compute: async (deps) => {
          const trav = deps['trav/main'] as { stations: Array<{ e: number; n: number }> }
          return { startChainage: 0, endChainage: trav.stations.length * 100 }
        },
      })

      // Initial computation
      await g.recomputeAll()
      const initialParcel = await g.get<{ areaSqm: number }>('parcel/P1')
      expect(initialParcel.areaSqm).toBe(10000)

      // Now: surveyor moves the control point (Helmert adjustment)
      g.markDirty('cp/origin')
      // → traverse, parcel, alignment all dirty
      expect(g.listDirty().sort()).toEqual([
        'alignment/road-1',
        'cp/origin',
        'parcel/P1',
        'trav/main',
      ])

      // Surveyor fixes the control point and re-sets its payload
      g.setPayload('cp/origin', { easting: 250050, northing: 9945050 })
      // setPayload clears dirty on cp/origin but NOT on dependents
      expect(g.inspect('cp/origin')?.dirty).toBe(false)
      expect(g.inspect('trav/main')?.dirty).toBe(true)

      // Recompute everything
      await g.recomputeAll()
      expect(g.listDirty().length).toBe(0)

      // Parcel payload should reflect the new control point (same shape, recomputed)
      const recomputedParcel = await g.get<{ areaSqm: number }>('parcel/P1')
      expect(recomputedParcel.areaSqm).toBe(10000) // same shape — 2 stations × 5000
    })
  })

  // ─── Node removal ───────────────────────────────────────────────────

  describe('node removal', () => {
    it('removes a leaf node (no dependents)', () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({
        id: 'trav/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })

      g.removeNode('trav/1')
      expect(g.listAll()).toEqual(['cp/1'])
    })

    it('throws when removing a node with dependents', () => {
      const g = createEntityGraph()
      g.addNode({ id: 'cp/1', type: 'control_point' })
      g.addNode({
        id: 'trav/1',
        type: 'traverse',
        dependencies: ['cp/1'],
        compute: async (deps) => deps['cp/1'],
      })

      expect(() => g.removeNode('cp/1')).toThrow(/still depend on it/)
    })
  })
})

/**
 * Cross-Hub Entity Graph
 * ======================
 *
 * A directed acyclic graph (DAG) of survey entities with deferred dirty
 * propagation. When a source entity (e.g. a geodetic control point)
 * changes, all downstream dependents (adjusted traverse, cadastral
 * polygon, road alignment) are marked dirty. Recomputation is lazy —
 * a node only recomputes when something reads it.
 *
 * Why this exists
 * ---------------
 * Before the graph, Metardu's three workflow hubs (cadastral,
 * engineering, topographic) lived side-by-side but didn't communicate.
 * If a surveyor adjusted a Helmert transformation parameter, the
 * cadastral polygons and road alignments built on top of it didn't
 * know to recompute. The surveyor would discover the stale data at
 * export time, when the statutory gate would reject it.
 *
 * The graph closes that loop. Any change to a source node cascades
 * dirty flags to all transitive dependents. The UI can then show
 * "X needs recomputation" badges and offer a one-click "Recompute
 * all affected" action.
 *
 * Design
 * ------
 * - Pure data structure. No React, no DB, no I/O. The graph is
 *   trivially testable and embeddable in any runtime.
 * - Nodes carry a `compute` function that takes the resolved
 *   dependencies and returns a new payload. The graph caches the
 *   result and a timestamp.
 * - Edges are dependency declarations: "node A depends on node B"
 *   means B's output feeds A's compute function.
 * - No cycles. Adding a dependency that would create a cycle throws
 *   a CycleError. Survey data has directionality — control points
 *   feed traverses feed polygons, never the reverse.
 * - Dirty propagation is eager (immediate cascade through the DAG),
 *   but recomputation is lazy (deferred until a reader requests the
 *   value). This avoids the "500 reactive re-renders" problem.
 *
 * Usage
 * -----
 *   const graph = new EntityGraph()
 *
 *   // Register a source node (no dependencies, payload set directly)
 *   const cp1 = graph.addNode({
 *     id: 'control-point/CP1',
 *     type: 'control_point',
 *     compute: async () => ({ easting: 250000, northing: 9945000, elevation: 1600 }),
 *   })
 *
 *   // Register a dependent node
 *   const trav1 = graph.addNode({
 *     id: 'traverse/T1',
 *     type: 'traverse',
 *     dependencies: ['control-point/CP1'],
 *     compute: async (deps) => {
 *       const cp = deps['control-point/CP1'] as { easting: number; northing: number }
 *       // ... Bowditch adjustment using cp as starting coordinate ...
 *       return { stations: [...], misclosure: 0.005 }
 *     },
 *   })
 *
 *   // Compute initial values
 *   await graph.recomputeAll()
 *
 *   // Later: a control point coordinate changes
 *   graph.markDirty('control-point/CP1')
 *   // → traverse/T1 is now dirty too (cascade)
 *
 *   // Reader requests traverse value → triggers recompute
 *   const trav = await graph.get('traverse/T1')
 *
 * Persistence
 * -----------
 * The graph is in-memory by default. For persistence, serialize via
 * `serialize()` and restore via `deserialize()`. The compute functions
 * themselves are not serialized — they're re-registered on restore.
 */

// ─── Types ──────────────────────────────────────────────────────────────

/**
 * The kind of entity a node represents. Used for filtering and UI badges.
 * Mirrors the major entity types in the survey data model.
 */
export type EntityType =
  | 'control_point'     // Geodetic control (known coordinates)
  | 'traverse'          // Adjusted traverse (Bowditch/Transit/LSQ)
  | 'leveling'          // Level network adjustment
  | 'parcel'            // Cadastral parcel boundary
  | 'alignment'         // Engineering road alignment
  | 'surface'           // Topographic DTM / TIN
  | 'volume'            // Earthwork volume computation
  | 'transformation'    // Helmert / datum transformation
  | 'custom'            // User-defined or extension entity

/**
 * A node in the entity graph. The `compute` function receives a map
 * of dependency payloads keyed by node id and returns a new payload.
 * Compute functions must be pure — no side effects, no I/O.
 */
export interface EntityNode<TPayload = unknown> {
  /** Globally-unique node id, e.g. 'control-point/CP1' */
  id: string
  /** Entity type — used for filtering and UI */
  type: EntityType
  /** Human-readable label for UI display */
  label?: string
  /** Node ids this node depends on (inputs to compute) */
  dependencies?: string[]
  /**
   * Compute function. Receives resolved dependency payloads.
   * Must be pure. Returns the new payload for this node.
   * If omitted, the node is a "source" — set its payload directly
   * via setPayload().
   */
  compute?: (deps: Record<string, unknown>) => Promise<TPayload> | TPayload
}

interface NodeState<TPayload = unknown> {
  node: EntityNode<TPayload>
  /** Last computed payload, or undefined if never computed */
  payload: TPayload | undefined
  /** True if the node's payload is stale and needs recomputation */
  dirty: boolean
  /** ISO timestamp of last successful compute */
  computedAt: string | undefined
  /** Last error thrown by compute, if any. When set, get() rethrows
   *  instead of retrying — caller must call recompute() explicitly. */
  error: Error | undefined
  /** True after a compute attempt has been made (success or failure).
   *  Prevents get() from automatically retrying a failed compute —
   *  the caller must explicitly call recompute() to retry. */
  attempted: boolean
}

// ─── Errors ─────────────────────────────────────────────────────────────

export class CycleError extends Error {
  constructor(
    public readonly fromId: string,
    public readonly toId: string,
    public readonly cyclePath: string[]
  ) {
    super(
      `Cannot add dependency ${fromId} → ${toId}: would create a cycle (${cyclePath.join(' → ')})`
    )
    this.name = 'CycleError'
  }
}

export class NodeNotFoundError extends Error {
  constructor(public readonly nodeId: string) {
    super(`Entity node not found: ${nodeId}`)
    this.name = 'NodeNotFoundError'
  }
}

export class DependencyNotFoundError extends Error {
  constructor(
    public readonly nodeId: string,
    public readonly missingDependencyId: string
  ) {
    super(
      `Node "${nodeId}" depends on unknown node "${missingDependencyId}". Add the dependency node first.`
    )
    this.name = 'DependencyNotFoundError'
  }
}

// ─── EntityGraph ────────────────────────────────────────────────────────

export class EntityGraph {
  private nodes = new Map<string, NodeState>()
  /** Reverse adjacency: for each node id, which nodes depend on it. */
  private dependents = new Map<string, Set<string>>()

  /**
   * Add a node to the graph. If a node with the same id already exists,
   * it's replaced (its payload is reset to undefined and dirty=true).
   *
   * @throws {DependencyNotFoundError} if any declared dependency doesn't exist
   * @throws {CycleError} if adding this node's dependencies would create a cycle
   */
  addNode<TPayload>(node: EntityNode<TPayload>): void {
    // Validate dependencies exist
    if (node.dependencies) {
      for (const depId of node.dependencies) {
        if (!this.nodes.has(depId)) {
          throw new DependencyNotFoundError(node.id, depId)
        }
      }
    }

    // Check for cycles: would adding edges (dep → node) create a cycle?
    // A cycle exists if node is already an ancestor of any of its deps.
    if (node.dependencies) {
      for (const depId of node.dependencies) {
        const cyclePath = this.findPath(node.id, depId)
        if (cyclePath) {
          throw new CycleError(node.id, depId, [...cyclePath, depId])
        }
      }
    }

    // Add the node
    this.nodes.set(node.id, {
      node: node as EntityNode,
      payload: undefined,
      dirty: true,
      computedAt: undefined,
      error: undefined,
      attempted: false,
    })

    // Register reverse edges (dep → this node is a dependent)
    if (node.dependencies) {
      for (const depId of node.dependencies) {
        if (!this.dependents.has(depId)) {
          this.dependents.set(depId, new Set())
        }
        this.dependents.get(depId)!.add(node.id)
      }
    }
  }

  /**
   * Remove a node from the graph. Also removes all dependency edges
   * pointing to it. Throws if any other node still depends on it —
   * caller must remove dependents first.
   */
  removeNode(nodeId: string): void {
    if (!this.nodes.has(nodeId)) return
    // Check no one depends on this node
    const deps = this.dependents.get(nodeId)
    if (deps && deps.size > 0) {
      throw new Error(
        `Cannot remove node "${nodeId}": ${deps.size} node(s) still depend on it (${Array.from(deps).join(', ')}). Remove dependents first.`
      )
    }
    // Remove forward edges (this node's dependencies)
    const node = this.nodes.get(nodeId)!.node
    if (node.dependencies) {
      for (const depId of node.dependencies) {
        this.dependents.get(depId)?.delete(nodeId)
      }
    }
    this.nodes.delete(nodeId)
    this.dependents.delete(nodeId)
  }

  /**
   * Get a node's current payload. If the node is dirty, it is
   * recomputed first (along with any dirty dependencies, recursively).
   *
   * @throws {NodeNotFoundError} if the node doesn't exist
   * @throws {Error} re-throws any error from the node's compute function
   */
  async get<TPayload = unknown>(nodeId: string): Promise<TPayload> {
    const state = this.nodes.get(nodeId)
    if (!state) throw new NodeNotFoundError(nodeId)

    // If previously attempted and errored, rethrow the cached error
    // instead of retrying automatically. Caller must call recompute()
    // to retry.
    if (state.attempted && state.error) {
      throw state.error
    }

    if (!state.dirty && state.payload !== undefined) {
      return state.payload as TPayload
    }

    // Recompute (this also recomputes dirty dependencies)
    await this.recompute(nodeId)
    return state.payload as TPayload
  }

  /**
   * Set a source node's payload directly. Marks the node and all
   * transitive dependents as dirty.
   *
   * Use this for source nodes (no compute function) whose payload
   * is set externally — e.g. a control point coordinate loaded from
   * a GNSS observation.
   *
   * @throws {NodeNotFoundError} if the node doesn't exist
   */
  setPayload<TPayload = unknown>(nodeId: string, payload: TPayload): void {
    const state = this.nodes.get(nodeId)
    if (!state) throw new NodeNotFoundError(nodeId)

    state.payload = payload
    state.dirty = false
    state.computedAt = new Date().toISOString()
    state.error = undefined
    state.attempted = true

    // Cascade dirtiness to all dependents
    this.markDirtyDependents(nodeId)
  }

  /**
   * Mark a node as dirty (its payload is stale). Also cascades
   * dirtiness to all transitive dependents.
   *
   * Use this when a node's underlying data source changes externally
   * (e.g. surveyor edits a field book entry that feeds a traverse).
   *
   * @throws {NodeNotFoundError} if the node doesn't exist
   */
  markDirty(nodeId: string): void {
    const state = this.nodes.get(nodeId)
    if (!state) throw new NodeNotFoundError(nodeId)

    state.dirty = true
    // Clearing attempted allows recompute() to retry after a prior error
    state.attempted = false
    state.error = undefined
    this.markDirtyDependents(nodeId)
  }

  /**
   * Recompute a single node and all its dirty dependencies.
   * Recursive — dependencies are recomputed first (topological order).
   *
   * After this call, the node's payload is fresh and dirty=false.
   *
   * @throws {NodeNotFoundError} if the node doesn't exist
   * @throws {Error} re-throws any error from a compute function
   */
  async recompute(nodeId: string): Promise<void> {
    const state = this.nodes.get(nodeId)
    if (!state) throw new NodeNotFoundError(nodeId)

    if (!state.dirty && state.payload !== undefined) return

    // First, recompute any dirty dependencies
    const deps = state.node.dependencies ?? []
    const depPayloads: Record<string, unknown> = {}
    for (const depId of deps) {
      const depState = this.nodes.get(depId)
      if (!depState) throw new DependencyNotFoundError(nodeId, depId)
      if (depState.dirty || depState.payload === undefined) {
        await this.recompute(depId)
      }
      depPayloads[depId] = depState.payload
    }

    // If this is a source node (no compute fn), just clear dirty
    if (!state.node.compute) {
      if (state.payload === undefined) {
        throw new Error(
          `Source node "${nodeId}" has no payload and no compute function. Call setPayload() first.`
        )
      }
      state.dirty = false
      state.attempted = true
      return
    }

    // Run the compute function
    try {
      const payload = await state.node.compute(depPayloads)
      state.payload = payload
      state.dirty = false
      state.computedAt = new Date().toISOString()
      state.error = undefined
      state.attempted = true
    } catch (err) {
      state.error = err instanceof Error ? err : new Error(String(err))
      state.dirty = false // don't keep retrying on every get()
      state.attempted = true
      throw state.error
    }
  }

  /**
   * Recompute all dirty nodes in topological order.
   * Useful for batch refreshes after bulk data loads.
   */
  async recomputeAll(): Promise<void> {
    const order = this.topologicalSort()
    for (const nodeId of order) {
      const state = this.nodes.get(nodeId)!
      if (state.dirty || state.payload === undefined) {
        await this.recompute(nodeId)
      }
    }
  }

  /**
   * List all nodes currently marked dirty.
   * Useful for UI: "5 entities need recomputation".
   */
  listDirty(): string[] {
    const dirty: string[] = []
    for (const [id, state] of this.nodes) {
      if (state.dirty) dirty.push(id)
    }
    return dirty
  }

  /**
   * Get a node's metadata (without triggering recompute).
   * Returns undefined if the node doesn't exist.
   */
  inspect(nodeId: string): {
    id: string
    type: EntityType
    label?: string
    dirty: boolean
    computedAt?: string
    hasError: boolean
    errorMessage?: string
  } | undefined {
    const state = this.nodes.get(nodeId)
    if (!state) return undefined
    return {
      id: state.node.id,
      type: state.node.type,
      label: state.node.label,
      dirty: state.dirty,
      computedAt: state.computedAt,
      hasError: state.error !== undefined,
      errorMessage: state.error?.message,
    }
  }

  /**
   * List all direct dependents of a node (nodes that depend on it).
   * Useful for UI: "Changing CP1 will affect: Traverse/T1, Parcel/P1".
   */
  listDependents(nodeId: string): string[] {
    return Array.from(this.dependents.get(nodeId) ?? [])
  }

  /**
   * List all transitive dependents (the full downstream subtree).
   */
  listTransitiveDependents(nodeId: string): string[] {
    const result = new Set<string>()
    const queue = [nodeId]
    while (queue.length > 0) {
      const current = queue.shift()!
      const deps = this.dependents.get(current) ?? new Set()
      for (const d of deps) {
        if (!result.has(d)) {
          result.add(d)
          queue.push(d)
        }
      }
    }
    return Array.from(result)
  }

  /**
   * List all nodes in the graph.
   */
  listAll(): string[] {
    return Array.from(this.nodes.keys())
  }

  /**
   * Get the total node count.
   */
  get size(): number {
    return this.nodes.size
  }

  // ─── Internal helpers ────────────────────────────────────────────────

  /**
   * Cascade dirty=true to all transitive dependents of nodeId.
   * Internal — does not mark nodeId itself dirty (caller does that).
   */
  private markDirtyDependents(nodeId: string): void {
    const deps = this.dependents.get(nodeId)
    if (!deps) return
    for (const depId of deps) {
      const state = this.nodes.get(depId)
      if (state && !state.dirty) {
        state.dirty = true
        this.markDirtyDependents(depId)
      }
    }
  }

  /**
   * Find a path from `fromId` to `toId` following dependency edges.
   * Returns the path as an array of node ids, or null if no path.
   * Used for cycle detection.
   */
  private findPath(fromId: string, toId: string): string[] | null {
    if (fromId === toId) return [fromId]
    const visited = new Set<string>()
    const queue: Array<{ id: string; path: string[] }> = [{ id: fromId, path: [fromId] }]
    while (queue.length > 0) {
      const { id, path } = queue.shift()!
      if (visited.has(id)) continue
      visited.add(id)
      const state = this.nodes.get(id)
      if (!state) continue
      for (const depId of state.node.dependencies ?? []) {
        if (depId === toId) return [...path, toId]
        if (!visited.has(depId)) {
          queue.push({ id: depId, path: [...path, depId] })
        }
      }
    }
    return null
  }

  /**
   * Topological sort of all nodes (dependencies before dependents).
   * Uses Kahn's algorithm. Throws if a cycle is detected (shouldn't
   * happen since addNode prevents cycles, but defensive).
   */
  private topologicalSort(): string[] {
    const inDegree = new Map<string, number>()
    for (const [id, state] of this.nodes) {
      inDegree.set(id, state.node.dependencies?.length ?? 0)
    }

    const queue: string[] = []
    for (const [id, deg] of inDegree) {
      if (deg === 0) queue.push(id)
    }

    const result: string[] = []
    while (queue.length > 0) {
      const id = queue.shift()!
      result.push(id)
      const deps = this.dependents.get(id) ?? new Set()
      for (const depId of deps) {
        const newDeg = (inDegree.get(depId) ?? 0) - 1
        inDegree.set(depId, newDeg)
        if (newDeg === 0) queue.push(depId)
      }
    }

    if (result.length !== this.nodes.size) {
      throw new Error('Cycle detected during topological sort (should be impossible — addNode prevents cycles)')
    }

    return result
  }

  // ─── Serialization ──────────────────────────────────────────────────

  /**
   * Serialize the graph state (nodes, edges, payloads, dirty flags)
   * to a plain object. Compute functions are NOT serialized — they
   * must be re-registered on restore.
   *
   * Useful for:
   *   - Persisting graph state to DB between sessions
   *   - Sending graph state to a worker for parallel recomputation
   *   - Debugging (dump the graph to inspect its current state)
   */
  serialize(): {
    nodes: Array<{
      id: string
      type: EntityType
      label?: string
      dependencies?: string[]
      payload: unknown
      dirty: boolean
      computedAt?: string
      errorMessage?: string
    }>
  } {
    return {
      nodes: Array.from(this.nodes.values()).map((s) => ({
        id: s.node.id,
        type: s.node.type,
        label: s.node.label,
        dependencies: s.node.dependencies,
        payload: s.payload,
        dirty: s.dirty,
        computedAt: s.computedAt,
        errorMessage: s.error?.message,
      })),
    }
  }
}

// ─── Factory helper ────────────────────────────────────────────────────

/**
 * Create a new empty EntityGraph. Convenience function — equivalent
 * to `new EntityGraph()`.
 */
export function createEntityGraph(): EntityGraph {
  return new EntityGraph()
}

import { messagesByLanguage, type Language } from './messages'

export const defaultLanguage: Language = 'en'

export function isLanguage(value: string | undefined | null): value is Language {
  if (!value) return false
  return value in messagesByLanguage
}

function getNestedValue(obj: unknown, path: string): unknown {
  if (!obj) return undefined
  const parts = path.split('.').filter(Boolean)
  let current: any = obj
  for (const part of parts) {
    if (current && typeof current === 'object' && part in current) {
      current = current[part]
    } else {
      return undefined
    }
  }
  return current
}

function interpolate(template: string, values?: Record<string, string | number>): string {
  if (!values) return template
  return template.replace(/\{(\w+)\}/g, (_, key: string) => {
    const value = values[key]
    return value === undefined || value === null ? `{${key}}` : String(value)
  })
}

export function createTranslator(language: Language) {
  const primary = messagesByLanguage[language]
  const fallback = messagesByLanguage[defaultLanguage]

  return (key: string, values?: Record<string, string | number>): string => {
    const primaryValue = getNestedValue(primary, key)
    if (typeof primaryValue === 'string') return interpolate(primaryValue, values)

    const fallbackValue = getNestedValue(fallback, key)
    if (typeof fallbackValue === 'string') return interpolate(fallbackValue, values)

    return key
  }
}

