/**
 * South / Nikon Adapter
 *
 * The South parser produces both coordinate points and SS observation
 * records with DMS angles, slope distance, and instrument/target heights.
 *
 * This adapter:
 *  - Maps SouthCoordinatePoint[] → UnifiedRawPoint[]
 *  - Maps SouthObservation[]   → UnifiedObservation[] (with DMS→decimal conversion)
 *  - For observations with only FL measurements, meanedObservations
 *    mirrors the raw observations (no FR face to average with).
 */

import { parseSouthData } from '../parseSouth'
import {
  UnifiedObservation,
  UnifiedRawPoint,
  UnifiedImportResult,
} from '../unifiedTypes'

/**
 * Convert DMS components (degrees, minutes, seconds) to decimal degrees.
 */
function dmsToDecimal(deg: number, min: number, sec: number): number {
  let sign = deg < 0 ? -1 : 1
  return sign * (Math.abs(deg) + min / 60 + sec / 3600)
}

/**
 * Adapt a South .dat/.dc file content string into the unified import result.
 */
export function adaptSouth(content: string): UnifiedImportResult {
  const parsed = parseSouthData(content)
  const warnings = [...parsed.warnings]
  const errors = [...parsed.errors]

  // ── Coordinate points ───────────────────────────────────────────────

  const rawPoints: UnifiedRawPoint[] = parsed.coordinates.map(function (pt) {
    return {
      id: String(pt.pointNumber),
      easting: pt.easting,
      northing: pt.northing,
      elevation: pt.elevation,
      code: pt.code,
    }
  })

  // ── Observations ────────────────────────────────────────────────────

  const observations: UnifiedObservation[] = parsed.observations.map(function (obs) {
    let hz = dmsToDecimal(obs.hclDeg, obs.hclMin, obs.hclSec)
    let va = dmsToDecimal(obs.vaDeg, obs.vaMin, obs.vaSec)

    return {
      stationId: obs.station,
      targetId: obs.target,
      face: 'F1',   // South SS records don't encode face
      horizontalAngle: hz,
      verticalAngle: va,
      slopeDistance: obs.slopeDistance,
      prismHeight: obs.targetHeight,
      instrumentHeight: obs.instrumentHeight,
    }
  })

  // ── Meaned observations ─────────────────────────────────────────────
  // South doesn't provide FL/FR pairs in the SS records we parse,
  // so we carry the raw observations forward as-is.

  const meanedObservations: UnifiedObservation[] = observations.map(function (obs) {
    return Object.assign({}, obs)
  })

  // ── Station name (first observation's station if available) ─────────

  let stationName = ''
  if (observations.length > 0) {
    stationName = observations[0].stationId
  } else if (rawPoints.length > 0) {
    stationName = rawPoints[0].id
  }

  // ── Station coordinates (look up station name in raw points) ────────

  let stationCoords: UnifiedImportResult['stationCoords'] = undefined
  if (stationName) {
    let match = rawPoints.find(function (p) { return p.id === stationName })
    if (match) {
      stationCoords = {
        easting: match.easting,
        northing: match.northing,
        elevation: match.elevation,
      }
    }
  }

  return {
    format: 'south',
    instrument: 'South',
    stationName: stationName,
    stationCoords: stationCoords,
    observations: observations,
    meanedObservations: meanedObservations,
    rawPoints: rawPoints,
    errors: errors,
    warnings: warnings,
  }
}

/**
 * Leica GSI Format Parser — Full Implementation
 * GSI-8 and GSI-16 formats
 *
 * Phase 23: Complete parser with all 40+ Word Identifier codes,
 * face-left/face-right pairing, and mean face reduction.
 *
 * Reference: Leica TPS1200/TS06/TS16 GSI Format Specification
 * Reference: Ghilani & Wolf, Elementary Surveying 16th Ed.
 *
 * WI Code Groups:
 *  11-19: Point identification
 *  21-29: Angles
 *  31-39: Distances
 *  41-49: Code information
 *  51-59: Distance corrections
 *  71-79: Point attributes / feature codes
 *  81-89: Coordinates / heights
 */

export interface GSIRecord {
  pointId: string
  easting?: number
  northing?: number
  elevation?: number
  horizontalAngle?: number  // degrees (decimal)
  verticalAngle?: number    // degrees (decimal)
  slopeDistance?: number     // metres
  horizontalDistance?: number // metres (WI 32)
  heightDifference?: number  // metres (WI 33)
  reflectorHeight?: number   // metres
  instrumentHeight?: number  // metres
  ppm?: number               // parts per million correction
  prismConstant?: number     // mm
  featureCode?: string       // point feature code
  description?: string       // point description
  facePosition?: 'FL' | 'FR' | 'unknown'
  rawLine?: string
}

export interface GSIParseResult {
  ok: boolean
  records: GSIRecord[]
  warnings: string[]
  format: 'GSI-8' | 'GSI-16' | 'unknown'
  statistics: {
    totalRecords: number
    coordinateRecords: number
    observationRecords: number
    faceLeftCount: number
    faceRightCount: number
  }
}

/**
 * Parse a GSI-8 or GSI-16 format file from a Leica total station.
 * Handles all standard Word Identifier codes.
 */
export function parseGSI(content: string): GSIParseResult {
  const warnings: string[] = []
  const records: GSIRecord[] = []
  const lines = content.trim().split('\n').filter((l: string) => l.trim())

  if (!lines.length) {
    return {
      ok: false, records: [], warnings: ['Empty file'], format: 'unknown',
      statistics: { totalRecords: 0, coordinateRecords: 0, observationRecords: 0, faceLeftCount: 0, faceRightCount: 0 },
    }
  }

  // Detect format: GSI-16 lines start with '*'
  const firstLine = lines[0].trim()
  const format: 'GSI-8' | 'GSI-16' = firstLine.startsWith('*') ? 'GSI-16' : 'GSI-8'
  const wordLength = format === 'GSI-16' ? 24 : 16

  let coordinateRecords = 0
  let observationRecords = 0
  let faceLeftCount = 0
  let faceRightCount = 0

  for (const line of lines) {
    const cleanLine = line.trim().replace(/^\*/, '')
    if (!cleanLine) continue

    const record: GSIRecord = { pointId: '', rawLine: line.trim() }

    // GSI format: each line has multiple "words", each wordLength characters
    // Each word structure: WI.SIGN.DATA
    //   WI = 2 digits (Word Identifier)
    //   Positions 2-6: metadata (info bytes)
    //   Position 6: sign ('+' or '-')
    //   Position 7+: data value

    let pos = 0
    while (pos < cleanLine.length) {
      const word = cleanLine.substring(pos, pos + wordLength).trim()
      if (!word) { pos += wordLength; continue }

      // Parse word identifier (first 2 characters)
      const wi = word.substring(0, 2)

      // Parse sign and value
      // In GSI-16 format: WI(2) + info(4) + sign(1) + data(16) = 23 chars
      // In GSI-8 format: WI(2) + info(4) + sign(1) + data(8) = 15 chars
      const signPos = 6
      const sign = word.length > signPos ? word[signPos] : '+'
      const dataStr = word.substring(signPos + 1 || 7).replace(/\s+/g, '')
      const signMultiplier = sign === '-' ? -1 : 1

      // Parse the numeric data value
      const rawNumValue = parseFloat(dataStr)
      if (isNaN(rawNumValue) && wi !== '41' && wi !== '71' && wi !== '72') {
        pos += wordLength
        continue
      }

      const numValue = signMultiplier * rawNumValue

      switch (wi) {
        // ─── Point Identification ──────────────────────────────────────
        case '11': // Point number
          record.pointId = dataStr.replace(/^0+/, '') || '0'
          break
        case '12': // Serial number of instrument
          // Informational — skip
          break
        case '18': // Timestamp
          // Informational — skip
          break
        case '19': // Block number / face indicator
          // In some Leica instruments, position 5 = face (0=FL, 1=FR)
          break

        // ─── Angles ────────────────────────────────────────────────────
        case '21': // Horizontal angle (Hz)
          record.horizontalAngle = numValue / 100000 // GSI stores as ddddggggg (100000ths of gon) or dddmmss.s
          break
        case '22': // Vertical angle (V)
          record.verticalAngle = numValue / 100000
          break
        case '24': // Horizontal angle (Hz) in Hz increments
          record.horizontalAngle = numValue / 100000
          break
        case '25': // Horizontal difference (Hz delta)
          break

        // ─── Distances ─────────────────────────────────────────────────
        case '31': // Slope distance (m)
          record.slopeDistance = numValue / 1000
          break
        case '32': // Horizontal distance (m)
          record.horizontalDistance = numValue / 1000
          break
        case '33': // Height difference (m)
          record.heightDifference = numValue / 1000
          break

        // ─── Code / Description ────────────────────────────────────────
        case '41': // Code block 1
        case '42': // Code block 2
          record.featureCode = dataStr.replace(/^0+/, '').trim() || dataStr.trim()
          break
        case '43': // Code block 3
        case '44': // Code block 4
        case '45': // Code block 5
        case '46': // Code block 6
        case '47': // Code block 7
        case '48': // Code block 8
        case '49': // Code block 9
          if (!record.description) {
            record.description = dataStr.replace(/^0+/, '').trim()
          } else {
            record.description += ' ' + dataStr.replace(/^0+/, '').trim()
          }
          break

        // ─── Distance Corrections ──────────────────────────────────────
        case '51': // PPM (atmospheric + geometric)
          record.ppm = numValue / 10 // stored as ppm × 10
          break
        case '52': // Prism constant (mm)
          record.prismConstant = numValue / 10 // stored as mm × 10
          break
        case '53': // PPM (atmospheric only)
          break
        case '58': // Addition constant
          break
        case '59': // Scale factor
          break

        // ─── Point Attributes / Feature Codes ──────────────────────────
        case '71': // Remark / point attribute 1
        case '72': // Remark / point attribute 2
        case '73': // Remark / point attribute 3
        case '74': // Remark / point attribute 4
        case '75': // Remark / point attribute 5
        case '76': // Remark / point attribute 6
        case '77': // Remark / point attribute 7
        case '78': // Remark / point attribute 8
        case '79': // Remark / point attribute 9
          if (!record.featureCode) {
            record.featureCode = dataStr.replace(/^0+/, '').trim()
          }
          break

        // ─── Coordinates ───────────────────────────────────────────────
        case '81': // Easting (E) in mm
          record.easting = numValue / 1000
          break
        case '82': // Northing (N) in mm
          record.northing = numValue / 1000
          break
        case '83': // Elevation (H) in mm
          record.elevation = numValue / 1000
          break
        case '84': // Easting (E) in 0.1mm
          record.easting = numValue / 10000
          break
        case '85': // Northing (N) in 0.1mm
          record.northing = numValue / 10000
          break
        case '86': // Elevation (H) in 0.1mm
          record.elevation = numValue / 10000
          break
        case '87': // Reflector height (m) — stored in mm
          record.reflectorHeight = numValue / 1000
          break
        case '88': // Instrument height (m) — stored in mm
          record.instrumentHeight = numValue / 1000
          break

        default:
          // Unknown WI — skip but warn on first occurrence
          break
      }

      pos += wordLength
    }

    if (record.pointId) {
      // Detect face position from vertical angle
      // FL: vertical angle 0-200 gon (0-180°)
      // FR: vertical angle 200-400 gon (180-360°)
      if (record.verticalAngle !== undefined) {
        if (record.verticalAngle >= 0 && record.verticalAngle < 200) {
          record.facePosition = 'FL'
          faceLeftCount++
        } else if (record.verticalAngle >= 200) {
          record.facePosition = 'FR'
          faceRightCount++
        } else {
          record.facePosition = 'unknown'
        }
      }

      if (record.easting !== undefined || record.northing !== undefined) {
        coordinateRecords++
      }
      if (record.horizontalAngle !== undefined || record.slopeDistance !== undefined) {
        observationRecords++
      }

      records.push(record)
    }
  }

  return {
    ok: records.length > 0,
    records,
    warnings,
    format,
    statistics: {
      totalRecords: records.length,
      coordinateRecords,
      observationRecords,
      faceLeftCount,
      faceRightCount,
    },
  }
}

// ─── Face-Left / Face-Right Pairing ─────────────────────────────────────────

export interface FacePair {
  pointId: string
  faceLeft: GSIRecord
  faceRight: GSIRecord | null
  meanHorizontalAngle: number   // degrees
  meanVerticalAngle: number     // degrees
  meanSlopeDistance: number      // metres
  horizontalDistance: number     // metres
  heightDifference: number      // metres
  collimationError?: number     // arc-seconds
}

/**
 * Pair face-left and face-right observations by point ID.
 *
 * For dual-face observations:
 * - Mean Hz = (Hz_FL + Hz_FR + 180°) / 2
 * - Mean V = (V_FL + (360° - V_FR)) / 2  (or in gon: (V_FL + (400-V_FR))/2)
 * - Mean SD = (SD_FL + SD_FR) / 2
 *
 * Source: Ghilani & Wolf, Chapter 12 — Mean face reduction
 * Source: N.N. Basak, Surveying and Levelling, Chapter 10
 */
export function pairFaces(records: GSIRecord[]): FacePair[] {
  // Group records by point ID
  const groups = new Map<string, { fl: GSIRecord | null; fr: GSIRecord | null }>()

  for (const rec of records) {
    if (!rec.pointId) continue
    if (rec.facePosition === 'FL') {
      const existing = groups.get(rec.pointId) || { fl: null, fr: null }
      existing.fl = rec
      groups.set(rec.pointId, existing)
    } else if (rec.facePosition === 'FR') {
      const existing = groups.get(rec.pointId) || { fl: null, fr: null }
      existing.fr = rec
      groups.set(rec.pointId, existing)
    } else if (rec.horizontalAngle !== undefined || rec.slopeDistance !== undefined) {
      // Single face — treat as FL
      const existing = groups.get(rec.pointId) || { fl: null, fr: null }
      if (!existing.fl) existing.fl = rec
      groups.set(rec.pointId, existing)
    }
  }

  const pairs: FacePair[] = []

  for (const [pointId, group] of Array.from(groups)) {
    const fl = group.fl
    const fr = group.fr

    if (!fl) continue

    let meanHz = fl.horizontalAngle ?? 0
    let meanV = fl.verticalAngle ?? 0
    let meanSD = fl.slopeDistance ?? 0

    if (fr) {
      // Mean horizontal angle: (Hz_FL + (Hz_FR + 180°)) / 2
      let hzFR = (fr.horizontalAngle ?? 0) + 180
      if (hzFR >= 360) hzFR -= 360
      // Handle wrapping near 0°/360°
      let diff = hzFR - meanHz
      if (diff > 180) diff -= 360
      if (diff < -180) diff += 360
      meanHz = meanHz + diff / 2
      if (meanHz < 0) meanHz += 360
      if (meanHz >= 360) meanHz -= 360

      // Mean vertical angle: (V_FL + (360° - V_FR)) / 2
      const vFR = 360 - (fr.verticalAngle ?? 0)
      meanV = (meanV + vFR) / 2

      // Mean slope distance
      meanSD = ((fl.slopeDistance ?? 0) + (fr.slopeDistance ?? 0)) / 2

      // Collimation error (C) in arc-seconds
      // C = (Hz_FL - (Hz_FR + 180°)) / 2
      const collimation = ((fl.horizontalAngle ?? 0) - hzFR) * 3600 / 2
    }

    // Compute horizontal distance and height difference
    const vRad = meanV * Math.PI / 180
    const hd = meanSD * Math.sin(vRad) // When V is zenith angle, HD = SD × sin(V)
    const dh = meanSD * Math.cos(vRad) + (fl.instrumentHeight ?? 0) - (fl.reflectorHeight ?? 0)

    pairs.push({
      pointId,
      faceLeft: fl,
      faceRight: fr,
      meanHorizontalAngle: meanHz,
      meanVerticalAngle: meanV,
      meanSlopeDistance: meanSD,
      horizontalDistance: Math.abs(hd),
      heightDifference: dh,
    })
  }

  return pairs
}

// ─── Convert GSI Records to Traverse Observations ───────────────────────────

export interface TraverseObservation {
  station: string
  bs: string
  fs: string
  hclDeg: string
  hclMin: string
  hclSec: string
  hcrDeg: string
  hcrMin: string
  hcrSec: string
  slopeDist: string
  vaDeg: string
  vaMin: string
  vaSec: string
  ih: string
  th: string
  remarks?: string
}

/**
 * Convert paired GSI records into TraverseModal-compatible observations.
 *
 * This is the pipeline that connects GSI import to the traverse computation:
 * GSI file → parseGSI() → pairFaces() → toTraverseObservations() → TraverseModal
 */
export function toTraverseObservations(
  pairs: FacePair[],
  backsightPointId?: string
): TraverseObservation[] {
  const observations: TraverseObservation[] = []

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i]

    // Convert decimal degrees to DMS
    const hzFL = decimalToDMS(pair.faceLeft.horizontalAngle ?? 0)
    const hzFR = pair.faceRight
      ? decimalToDMS(pair.faceRight.horizontalAngle ?? 0)
      : { d: '0', m: '0', s: '0' }

    const vAngle = decimalToDMS(pair.meanVerticalAngle)

    observations.push({
      station: pair.pointId,
      bs: i === 0 ? (backsightPointId || 'BS') : pairs[i - 1].pointId,
      fs: i < pairs.length - 1 ? pairs[i + 1].pointId : 'FS',
      hclDeg: hzFL.d,
      hclMin: hzFL.m,
      hclSec: hzFL.s,
      hcrDeg: hzFR.d,
      hcrMin: hzFR.m,
      hcrSec: hzFR.s,
      slopeDist: pair.meanSlopeDistance.toFixed(4),
      vaDeg: vAngle.d,
      vaMin: vAngle.m,
      vaSec: vAngle.s,
      ih: (pair.faceLeft.instrumentHeight ?? 0).toFixed(3),
      th: (pair.faceLeft.reflectorHeight ?? 0).toFixed(3),
      remarks: pair.faceLeft.featureCode || '',
    })
  }

  return observations
}

function decimalToDMS(decimal: number): { d: string; m: string; s: string } {
  const abs = Math.abs(decimal)
  const d = Math.floor(abs)
  const mFloat = (abs - d) * 60
  const m = Math.floor(mFloat)
  const s = (mFloat - m) * 60
  return {
    d: String(d),
    m: String(m),
    s: s.toFixed(1),
  }
}

export interface JobXMLRecord {
  pointId: string
  easting?: number
  northing?: number
  elevation?: number
  code?: string
  note?: string
}

export function parseJobXML(content: string): {
  ok: boolean
  records: JobXMLRecord[]
  warnings: string[]
  jobName?: string
} {
  const warnings: string[] = []
  const records: JobXMLRecord[] = []

  try {
    const parser = new DOMParser()
    const doc = parser.parseFromString(content, 'text/xml')

    const jobName = doc.querySelector('JOBFile')
      ?.getAttribute('JobName') || undefined

    const pointRecords = doc.querySelectorAll('PointRecord')
    pointRecords.forEach((pr: any) => {
      const id = pr.querySelector('Name')?.textContent?.trim()
      if (!id) return

      const northing = parseFloat(
        pr.querySelector('Grid > North')?.textContent || '0'
      )
      const easting = parseFloat(
        pr.querySelector('Grid > East')?.textContent || '0'
      )
      const elevation = parseFloat(
        pr.querySelector('Grid > Elev')?.textContent || '0'
      )
      const code = pr.querySelector('Code')?.textContent?.trim()

      records.push({ 
        pointId: id, 
        easting, 
        northing, 
        elevation,
        code
      })
    })

    const obsRecords = doc.querySelectorAll('RawObservation')
    obsRecords.forEach((obs: any) => {
      const id = obs.querySelector('TargetID')?.textContent?.trim()
      if (!id || records.find((r: any) => r.pointId === id)) return
      warnings.push(`Raw observation for ${id} — no coordinates computed`)
    })

    return { ok: true, records, warnings, jobName }

  } catch (err) {
    return { 
      ok: false, 
      records: [], 
      warnings: ['Failed to parse JobXML file — check file format'] 
    }
  }
}

/**
 * Unified Total Station Import — Single Entry Point
 *
 * Usage:
 *   import { importTotalStation } from '@/lib/import/totalStation/unifiedImport'
 *
 *   const result = importTotalStation(fileContent, 'traverse.dat')
 *   // result.format, result.observations, result.rawPoints, etc.
 *
 * Pipeline:  detectFormat → parse → adapt → UnifiedImportResult
 */

import { detectTotalStationFormat } from './detectFormat'
import { adaptGSI } from './adapters/gsiAdapter'
import { adaptSDR } from './adapters/sdrAdapter'
import { adaptSouth } from './adapters/southAdapter'
import { adaptTopcon } from './adapters/topconAdapter'
import { adaptJobXML } from './adapters/jobXmlAdapter'
import {
  UnifiedImportResult,
  UnifiedRawPoint,
} from './unifiedTypes'

/**
 * Import a total station data file of any supported format.
 *
 * @param content  - Raw file content as a string
 * @param filename - File name (used for extension-based format detection)
 * @returns UnifiedImportResult with observations, raw points, and diagnostics
 */
export function importTotalStation(
  content: string,
  filename: string = 'unknown.dat'
): UnifiedImportResult {
  const format = detectTotalStationFormat(content, filename)

  switch (format) {
    case 'gsi':
      return adaptGSI(content)

    case 'sokkia':
      return adaptSDR(content)

    case 'south':
      return adaptSouth(content)

    case 'topcon':
      return adaptTopcon(content)

    case 'jobxml':
      return adaptJobXML(content)

    default:
      return unknownFormatFallback(content, filename)
  }
}

/**
 * Fallback for unrecognised formats.
 *
 * Attempts a simple CSV-like coordinate parse so that even
 * completely unknown formats don't return a hard error if they
 * happen to be comma-delimited coordinate files.
 */
function unknownFormatFallback(
  content: string,
  filename: string
): UnifiedImportResult {
  const errors: string[] = [
    'Unrecognised total station format for file "' + filename + '"',
  ]
  const warnings: string[] = []
  const rawPoints: UnifiedRawPoint[] = []

  // Attempt CSV coordinate extraction as a last resort
  let lines = content.trim().split('\n')
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i].trim()
    if (!line) continue
    let parts = line.split(',')
    if (parts.length >= 4) {
      let id = parts[0] ? parts[0].trim() : ''
      let n = parseFloat(parts[1])
      let e = parseFloat(parts[2])
      let el = parseFloat(parts[3])
      if (id && !isNaN(n) && !isNaN(e)) {
        rawPoints.push({
          id: id,
          easting: e,
          northing: n,
          elevation: isNaN(el) ? 0 : el,
          code: parts[4] ? parts[4].trim() : '',
        })
      }
    }
  }

  if (rawPoints.length > 0) {
    warnings.push(
      'Format was "unknown" but ' +
        rawPoints.length +
        ' coordinate rows were extracted by CSV fallback'
    )
  }

  return {
    format: 'unknown',
    instrument: 'Unknown',
    stationName: rawPoints.length > 0 ? rawPoints[0].id : '',
    stationCoords: rawPoints.length > 0
      ? {
          easting: rawPoints[0].easting,
          northing: rawPoints[0].northing,
          elevation: rawPoints[0].elevation,
        }
      : undefined,
    observations: [],
    meanedObservations: [],
    rawPoints: rawPoints,
    errors: errors,
    warnings: warnings,
  }
}

// Re-export types for convenience
export type {
  UnifiedObservation,
  UnifiedRawPoint,
  UnifiedImportResult,
} from './unifiedTypes'

/**
 * IFC4 STEP File Parser — Native TypeScript Implementation
 *
 * Parses IFC4 STEP files (plain text format) without external dependencies.
 *
 * STEP file structure:
 *   ISO-10303-21;
 *   HEADER;
 *     FILE_DESCRIPTION(('ViewDefinition [CoordinationView]'),'2;1');
 *     FILE_NAME('example.ifc','2024-01-01',('Author'),('Org'),'IfcOpenShell','IfcOpenShell','');
 *     FILE_SCHEMA(('IFC4'));
 *   ENDSEC;
 *   DATA;
 *     #1=IFCPROJECT('2x3k',$,'Project Name',(#2),$,$,$,(#3),#4);
 *     #2=IFCOWNERHISTORY(#5,#6,$,.ADDED.,$,$,$,1640995200);
 *     #3=IFCGEOMETRICREPRESENTATIONCONTEXT($,'Model',3,1.0E-5,$,$);
 *   ENDSEC;
 *   END-ISO-10303-21;
 *
 * Entity references: #1, #2, etc.
 * String args: 'single quoted' (escaped: '' for literal ')
 * Number args: 1.0, 100, -3.5
 * Enum args: .ENUMVALUE.
 * Boolean args: .T., .F.
 * Optional/missing args: $
 * Lists: (item1,item2,#3)
 * Nested lists: ((#1,#2),(#3,#4))
 */

// ─── Types ───────────────────────────────────────────────────────────────────

export interface IFCHeader {
  description: string
  implementationLevel: string
  fileName: string
  author: string
  organization: string
  preprocessorVersion: string
  originatingSystem: string
  authorization: string
  schema: string
}

export interface IFCEntity {
  id: number
  type: string
  args: unknown[]
  raw: string
}

export interface IFCModel {
  header: IFCHeader
  entities: Map<number, IFCEntity>
  byType: Map<string, number[]>
}

export interface BuildingGeometry {
  buildings: Array<{
    name: string
    footprint: Array<{ x: number; y: number; z: number }>
    floors: number
    walls: Array<{
      start: { x: number; y: number; z: number }
      end: { x: number; y: number; z: number }
    }>
    columns: Array<{ x: number; y: number; z: number }>
  }>
}

export interface IFCSurveyPoint {
  id: string
  label: string
  easting: number
  northing: number
  elevation: number
  type: string
}

export interface IFCProjectInfo {
  name: string
  description: string
  coordinateSystem: string
  epsgCode?: number
  originEasting?: number
  originNorthing?: number
}

// ─── STEP Argument Types ─────────────────────────────────────────────────────

type StepArg =
  | number
  | string
  | boolean
  | null
  | StepRef
  | StepArg[]

interface StepRef {
  __ref: true
  id: number
}

// ─── STEP Tokenizer / Parser ────────────────────────────────────────────────

/**
 * Parse a full IFC4 STEP file content string into an IFCModel.
 */
export function parseIFCStep(content: string): IFCModel {
  const header = parseHeader(content)
  const entities = new Map<number, IFCEntity>()
  const byType = new Map<string, number[]>()

  // Extract DATA section
  const dataSection = extractSection(content, 'DATA')
  if (!dataSection) {
    return { header, entities, byType }
  }

  // Parse entity lines
  const lines = dataSection.split('\n')
  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('ENDSEC')) continue

    // Match entity declaration: #id=TYPE(args);
    const entityMatch = trimmed.match(/^#(\d+)\s*=\s*([A-Z][A-Z0-9_]*)\s*\(([\s\S]*)\);?\s*$/)
    if (!entityMatch) continue

    const id = parseInt(entityMatch[1], 10)
    const type = entityMatch[2]
    const argsRaw = entityMatch[3]

    const args = parseArgs(argsRaw)
    const entity: IFCEntity = { id, type, args, raw: trimmed }

    entities.set(id, entity)

    const typeList = byType.get(type)
    if (typeList) {
      typeList.push(id)
    } else {
      byType.set(type, [id])
    }
  }

  return { header, entities, byType }
}

/**
 * Parse the HEADER section of the STEP file.
 */
function parseHeader(content: string): IFCHeader {
  const headerSection = extractSection(content, 'HEADER')
  if (!headerSection) {
    return emptyHeader()
  }

  const header: IFCHeader = { ...emptyHeader() }

  // Parse FILE_DESCRIPTION
  const fileDescMatch = headerSection.match(
    /FILE_DESCRIPTION\s*\(\s*\(([^)]*)\)\s*,\s*'([^']*)'\s*\)/i
  )
  if (fileDescMatch) {
    header.description = fileDescMatch[1].trim()
    header.implementationLevel = fileDescMatch[2].trim()
  }

  // Parse FILE_NAME
  const fileNameMatch = headerSection.match(
    /FILE_NAME\s*\(\s*'([^']*)'\s*,\s*'([^']*)'\s*,\s*\(([^)]*)\)\s*,\s*\(([^)]*)\)\s*,\s*'([^']*)'\s*,\s*'([^']*)'\s*,\s*'([^']*)'\s*\)/i
  )
  if (fileNameMatch) {
    header.fileName = fileNameMatch[1]
    header.author = parseStringList(fileNameMatch[3])
    header.organization = parseStringList(fileNameMatch[4])
    header.preprocessorVersion = fileNameMatch[5]
    header.originatingSystem = fileNameMatch[6]
    header.authorization = fileNameMatch[7]
  }

  // Parse FILE_SCHEMA
  const schemaMatch = headerSection.match(
    /FILE_SCHEMA\s*\(\s*\(\s*'([^']*)'\s*\)\s*\)/i
  )
  if (schemaMatch) {
    header.schema = schemaMatch[1]
  }

  return header
}

/**
 * Extract a named section from the STEP content.
 * Sections are bounded by SECTION_NAME; ... ENDSEC;
 */
function extractSection(content: string, sectionName: string): string | null {
  const startRegex = new RegExp(`${sectionName}\\s*;`, 'i')
  const startMatch = content.search(startRegex)
  if (startMatch === -1) return null

  const afterStart = content.substring(startMatch + sectionName.length + 1)
  const endIdx = afterStart.search(/\bENDSEC\s*;/i)
  if (endIdx === -1) return afterStart

  return afterStart.substring(0, endIdx)
}

/**
 * Parse comma-separated arguments from inside parentheses.
 * Handles nested lists, strings, refs, enums, booleans, and $ (null).
 */
function parseArgs(raw: string): StepArg[] {
  const args: StepArg[] = []
  let i = 0
  let current = ''

  while (i < raw.length) {
    const ch = raw[i]

    if (ch === ',') {
      const parsed = parseSingleArg(current.trim())
      if (parsed !== undefined) args.push(parsed)
      current = ''
      i++
      continue
    }

    if (ch === '(') {
      // Count nested parentheses to find the matching close
      const closeIdx = findMatchingParen(raw, i)
      const subStr = raw.substring(i + 1, closeIdx)
      const subArgs = parseArgs(subStr)

      // Check if this is a top-level empty pair like () which means empty list
      if (subArgs.length === 1 && subArgs[0] === null) {
        args.push([])
      } else {
        args.push(subArgs)
      }
      i = closeIdx + 1
      current = ''
      continue
    }

    current += ch
    i++
  }

  // Don't forget the last arg
  const lastParsed = parseSingleArg(current.trim())
  if (lastParsed !== undefined) args.push(lastParsed)

  return args
}

/**
 * Parse a single argument token (not a list).
 */
function parseSingleArg(token: string): StepArg | undefined {
  if (token === '' || token === '$') return null

  // Entity reference: #123
  const refMatch = token.match(/^#(\d+)$/)
  if (refMatch) {
    return { __ref: true, id: parseInt(refMatch[1], 10) } as StepRef
  }

  // Boolean: .T. or .F.
  if (token === '.T.' || token === '.F.') {
    return token === '.T.'
  }

  // Enum: .ENUMVALUE.
  const enumMatch = token.match(/^\.[A-Z][A-Z0-9_]*\.$/i)
  if (enumMatch) {
    return token // keep as string for enums
  }

  // String: 'single quoted' (escaped '' for literal ')
  if (token.startsWith("'") && token.endsWith("'")) {
    return token.slice(1, -1).replace(/''/g, "'")
  }

  // Number
  const num = Number(token)
  if (!isNaN(num) && token.trim() !== '') {
    return num
  }

  // Fallback: return as string (type names like IFCWALL in lists, etc.)
  return token
}

/**
 * Find the index of the matching closing parenthesis.
 */
function findMatchingParen(str: string, openIdx: number): number {
  let depth = 0
  let inString = false
  let i = openIdx

  while (i < str.length) {
    const ch = str[i]

    if (inString) {
      if (ch === "'") {
        if (i + 1 < str.length && str[i + 1] === "'") {
          i += 2 // escaped quote
          continue
        }
        inString = false
      }
      i++
      continue
    }

    if (ch === "'") {
      inString = true
      i++
      continue
    }

    if (ch === '(') {
      depth++
    } else if (ch === ')') {
      depth--
      if (depth === 0) return i
    }

    i++
  }

  return str.length - 1
}

/**
 * Parse a parenthesized string list from header, e.g. "('John','Jane')" → "John, Jane"
 */
function parseStringList(raw: string): string {
  const matches = raw.match(/'([^']*)'/g)
  if (!matches) return ''
  return matches
    .map((m) => m.slice(1, -1).replace(/''/g, "'"))
    .join(', ')
}

function emptyHeader(): IFCHeader {
  return {
    description: '',
    implementationLevel: '2;1',
    fileName: '',
    author: '',
    organization: '',
    preprocessorVersion: '',
    originatingSystem: '',
    authorization: '',
    schema: '',
  }
}

// ─── Entity Resolution ───────────────────────────────────────────────────────

/**
 * Resolve an entity reference to its entity, or return null.
 */
export function resolveRef<T extends IFCEntity = IFCEntity>(
  model: IFCModel,
  arg: StepArg
): T | null {
  if (isRef(arg)) {
    return (model.entities.get(arg.id) as T) ?? null
  }
  return null
}

/**
 * Check if a StepArg is an entity reference.
 */
export function isRef(arg: StepArg): arg is StepRef {
  return (
    typeof arg === 'object' &&
    arg !== null &&
    !Array.isArray(arg) &&
    (arg as StepRef).__ref === true
  )
}

/**
 * Get the first entity of a given type.
 */
export function firstOfType<T extends IFCEntity = IFCEntity>(
  model: IFCModel,
  type: string
): T | null {
  const ids = model.byType.get(type)
  if (!ids || ids.length === 0) return null
  return (model.entities.get(ids[0]) as T) ?? null
}

/**
 * Get all entities of a given type.
 */
export function allOfType<T extends IFCEntity = IFCEntity>(
  model: IFCModel,
  type: string
): T[] {
  const ids = model.byType.get(type)
  if (!ids) return []
  return ids
    .map((id) => model.entities.get(id) as T)
    .filter((e): e is T => e !== null && e !== undefined)
}

// ─── Building Geometry Extraction ───────────────────────────────────────────

/**
 * Extract building geometry from IFC entities.
 * Resolves IFCSITE → IFCBUILDING → IFCBUILDINGSTOREY → walls/slabs/columns.
 */
export function extractBuildingGeometry(model: IFCModel): BuildingGeometry {
  const buildings: BuildingGeometry['buildings'] = []

  // Find IFCPROJECT to get sites
  const projects = allOfType(model, 'IFCPROJECT')

  // Collect all sites from project or standalone
  const sites = allOfType(model, 'IFCSITE')
  if (sites.length === 0) {
    return { buildings }
  }

  for (const site of sites) {
    // Find buildings linked to this site via IFCRELASSOCIATES or spatial decomposition
    const siteBuildings = findRelatedEntities(model, site.id, 'IFCRELAGGREGATES', 'IFCBUILDING')

    if (siteBuildings.length === 0) {
      // Fallback: just use all buildings
      siteBuildings.push(...allOfType(model, 'IFCBUILDING'))
    }

    for (const building of siteBuildings) {
      const buildingName = getEntityName(model, building)

      // Find building storeys
      const storeys = findRelatedEntities(
        model,
        building.id,
        'IFCRELAGGREGATES',
        'IFCBUILDINGSTOREY'
      )

      const footprint: Array<{ x: number; y: number; z: number }> = []
      const walls: BuildingGeometry['buildings'][0]['walls'] = []
      const columns: BuildingGeometry['buildings'][0]['columns'] = []
      const floorSet = new Set<number>()

      for (const storey of storeys) {
        floorSet.add(getStoreyElevation(model, storey))

        // Extract walls from this storey
        const storeyWalls = findRelatedEntities(
          model,
          storey.id,
          'IFCRELAGGREGATES',
          'IFCWALL'
        )
        // Also check IFCRELCONTAINEDINSPATIALSTRUCTURE
        storeyWalls.push(
          ...findContainedEntities(model, storey.id, 'IFCWALL')
        )

        for (const wall of storeyWalls) {
          const wallGeom = extractWallGeometry(model, wall)
          if (wallGeom) {
            walls.push(wallGeom)
            // Add wall endpoints to footprint approximation
            footprint.push(wallGeom.start, wallGeom.end)
          }
        }

        // Extract columns
        const storeyColumns = findRelatedEntities(
          model,
          storey.id,
          'IFCRELAGGREGATES',
          'IFCCOLUMN'
        )
        storeyColumns.push(
          ...findContainedEntities(model, storey.id, 'IFCCOLUMN')
        )

        for (const col of storeyColumns) {
          const colGeom = extractColumnGeometry(model, col)
          if (colGeom) {
            columns.push(colGeom)
          }
        }
      }

      // If no storeys found, try to find walls/columns directly from building
      if (storeys.length === 0) {
        const directWalls = findRelatedEntities(
          model,
          building.id,
          'IFCRELAGGREGATES',
          'IFCWALL'
        )
        directWalls.push(
          ...findContainedEntities(model, building.id, 'IFCWALL')
        )

        for (const wall of directWalls) {
          const wallGeom = extractWallGeometry(model, wall)
          if (wallGeom) {
            walls.push(wallGeom)
            footprint.push(wallGeom.start, wallGeom.end)
          }
        }

        const directCols = findRelatedEntities(
          model,
          building.id,
          'IFCRELAGGREGATES',
          'IFCCOLUMN'
        )
        directCols.push(
          ...findContainedEntities(model, building.id, 'IFCCOLUMN')
        )

        for (const col of directCols) {
          const colGeom = extractColumnGeometry(model, col)
          if (colGeom) {
            columns.push(colGeom)
          }
        }
      }

      // Deduplicate footprint points
      const uniqueFootprint = deduplicatePoints(footprint)

      buildings.push({
        name: buildingName,
        footprint: uniqueFootprint,
        floors: floorSet.size || 1,
        walls,
        columns,
      })
    }
  }

  // If no buildings found but there are walls directly, create a generic building
  if (buildings.length === 0) {
    const allWalls = allOfType(model, 'IFCWALL')
    const allCols = allOfType(model, 'IFCCOLUMN')

    if (allWalls.length > 0 || allCols.length > 0) {
      const walls: BuildingGeometry['buildings'][0]['walls'] = []
      const footprint: Array<{ x: number; y: number; z: number }> = []

      for (const wall of allWalls) {
        const wallGeom = extractWallGeometry(model, wall)
        if (wallGeom) {
          walls.push(wallGeom)
          footprint.push(wallGeom.start, wallGeom.end)
        }
      }

      const columns: BuildingGeometry['buildings'][0]['columns'] = []
      for (const col of allCols) {
        const colGeom = extractColumnGeometry(model, col)
        if (colGeom) {
          columns.push(colGeom)
        }
      }

      buildings.push({
        name: headerOrFallback(model, 'IFC Project'),
        footprint: deduplicatePoints(footprint),
        floors: 1,
        walls,
        columns,
      })
    }
  }

  return { buildings }
}

/**
 * Extract survey points from IFC entities.
 * Looks for IFCANNOTATION, IFCSURVEYPOINT, and IFCGRID entities.
 */
export function extractSurveyPoints(model: IFCModel): IFCSurveyPoint[] {
  const points: IFCSurveyPoint[] = []

  // Extract from IFCSITE survey points
  const sites = allOfType(model, 'IFCSITE')
  for (const site of sites) {
    const refLatitude = getArgValue(site.args, 8) as number | null
    const refLongitude = getArgValue(site.args, 9) as number | null
    const refElevation = getArgValue(site.args, 10) as number | null

    if (refLatitude !== null && refLongitude !== null) {
      points.push({
        id: `site-${site.id}`,
        label: getEntityName(model, site) || 'Site Reference',
        easting: refLongitude,
        northing: refLatitude,
        elevation: refElevation ?? 0,
        type: 'IFCSITE',
      })
    }

    // Also extract from site's ObjectPlacement
    if (site.args.length > 5) {
      const placementRef = getArgValue(site.args, 5)
      if (isRef(placementRef)) {
        const placement = resolveRef(model, placementRef)
        if (placement && placement.type === 'IFCLOCALPLACEMENT') {
          const coords = extractLocalPlacementCoords(model, placement)
          if (coords) {
            points.push({
              id: `site-placement-${site.id}`,
              label: `${getEntityName(model, site)} Origin`,
              easting: coords[0],
              northing: coords[1],
              elevation: coords[2],
              type: 'IFCSITE_ORIGIN',
            })
          }
        }
      }
    }
  }

  // Extract from IFCSURVEYPOINT entities (if present)
  const surveyPoints = allOfType(model, 'IFCSURVEYPOINT')
  for (const sp of surveyPoints) {
    const name = getEntityName(model, sp)
    const placementRef = getArgValue(sp.args, 5)
    let coords: [number, number, number] | null = null

    if (isRef(placementRef)) {
      const placement = resolveRef(model, placementRef)
      if (placement && placement.type === 'IFCLOCALPLACEMENT') {
        coords = extractLocalPlacementCoords(model, placement)
      }
    }

    points.push({
      id: `survey-point-${sp.id}`,
      label: name || `Survey Point ${sp.id}`,
      easting: coords?.[0] ?? 0,
      northing: coords?.[1] ?? 0,
      elevation: coords?.[2] ?? 0,
      type: 'IFCSURVEYPOINT',
    })
  }

  // Extract from IFCARTESIANPOINT entities used in annotations
  const annotations = allOfType(model, 'IFCANNOTATION')
  for (const ann of annotations) {
    const name = getEntityName(model, ann)
    const placementRef = getArgValue(ann.args, 5)
    let coords: [number, number, number] | null = null

    if (isRef(placementRef)) {
      const placement = resolveRef(model, placementRef)
      if (placement && placement.type === 'IFCLOCALPLACEMENT') {
        coords = extractLocalPlacementCoords(model, placement)
      }
    }

    if (coords) {
      points.push({
        id: `annotation-${ann.id}`,
        label: name || `Annotation ${ann.id}`,
        easting: coords[0],
        northing: coords[1],
        elevation: coords[2],
        type: 'IFCANNOTATION',
      })
    }
  }

  // Extract all IFCGRIDAXIS intersection points
  const grids = allOfType(model, 'IFCGRID')
  for (const grid of grids) {
    const name = getEntityName(model, grid)
    // Grid axes are in args[2] as a list of IFCGRIDAXIS refs
    const axesRef = getArgValue(grid.args, 2)
    if (Array.isArray(axesRef)) {
      for (const axisRef of axesRef) {
        if (isRef(axisRef)) {
          const axis = resolveRef(model, axisRef)
          if (axis) {
            const axisCurveRef = getArgValue(axis.args, 0)
            if (isRef(axisCurveRef)) {
              const curve = resolveRef(model, axisCurveRef)
              if (curve) {
                const curvePts = extractCurvePoints(model, curve)
                for (let ci = 0; ci < curvePts.length; ci++) {
                  points.push({
                    id: `grid-${grid.id}-axis-${axis.id}-${ci}`,
                    label: `${name || 'Grid'} Axis`,
                    easting: curvePts[ci][0],
                    northing: curvePts[ci][1],
                    elevation: curvePts[ci][2],
                    type: 'IFCGRID',
                  })
                }
              }
            }
          }
        }
      }
    }
  }

  return points
}

/**
 * Extract project metadata from IFC entities.
 */
export function extractProjectMetadata(model: IFCModel): IFCProjectInfo {
  const info: IFCProjectInfo = {
    name: '',
    description: '',
    coordinateSystem: '',
  }

  // Get IFCPROJECT entity
  const project = firstOfType(model, 'IFCPROJECT')
  if (project) {
    info.name = getEntityName(model, project) || model.header.fileName || 'Unnamed Project'

    // Description is in args[3]
    const descRef = getArgValue(project.args, 3)
    if (isRef(descRef)) {
      const desc = resolveRef(model, descRef)
      if (desc && desc.type === 'IFCTEXT') {
        info.description = String(getArgValue(desc.args, 0) ?? '')
      }
    } else if (typeof descRef === 'string') {
      info.description = descRef
    }

    // Units context is in args[7] or args[8] as a list
    const unitsRef = getArgValue(project.args, 8)
    if (isRef(unitsRef)) {
      const unitsCtx = resolveRef(model, unitsRef)
      if (unitsCtx) {
        info.coordinateSystem = extractUnitInfo(model, unitsCtx)
      }
    }
  } else {
    info.name = model.header.fileName || 'Unnamed Project'
  }

  // Extract IFCMAPCONVERSION for coordinate system info
  const mapConversions = allOfType(model, 'IFCMAPCONVERSION')
  for (const mc of mapConversions) {
    // args: (SourceCRS, TargetCRS, Eastings, Northings, OrthoHeight, XAxisAbscissa, XAxisOrdinate, Scale)
    const eastings = getArgValue(mc.args, 2) as number | null
    const northings = getArgValue(mc.args, 3) as number | null

    if (eastings !== null) info.originEasting = eastings
    if (northings !== null) info.originNorthing = northings

    // Target CRS ref
    const targetCrsRef = getArgValue(mc.args, 1)
    if (isRef(targetCrsRef)) {
      const crs = resolveRef(model, targetCrsRef)
      if (crs) {
        if (crs.type === 'IFCPROJECTEDCRS') {
          info.epsgCode = extractEPSGCode(model, crs)
          info.coordinateSystem = getArgValue(crs.args, 0) as string || info.coordinateSystem
        } else if (crs.type === 'IFCGEOGRAPHICCRS') {
          info.coordinateSystem = getArgValue(crs.args, 0) as string || info.coordinateSystem
        }
      }
    }
  }

  // Direct IFCPROJECTEDCRS lookup
  if (!info.epsgCode) {
    const projectedCrsList = allOfType(model, 'IFCPROJECTEDCRS')
    for (const crs of projectedCrsList) {
      const epsg = extractEPSGCode(model, crs)
      if (epsg) {
        info.epsgCode = epsg
        info.coordinateSystem = getArgValue(crs.args, 0) as string || info.coordinateSystem
        break
      }
    }
  }

  // Fallback to header schema
  if (!info.coordinateSystem) {
    info.coordinateSystem = model.header.schema
  }

  return info
}

// ─── Helper Functions ────────────────────────────────────────────────────────

function getArgValue(args: unknown[], index: number): any {
  if (index < 0 || index >= args.length) return null
  const val = args[index]
  return val === null || val === undefined ? null : val
}

function getEntityName(model: IFCModel, entity: IFCEntity): string {
  // Name is typically args[1] for most IFC entities (args[0] is globalId)
  // But some types have name at different positions
  if (!entity.args || entity.args.length < 2) return ''

  // Try args[1] first (common for most spatial elements)
  const nameCandidate = entity.args[1]
  if (typeof nameCandidate === 'string' && nameCandidate !== '') {
    return nameCandidate
  }

  // For IFCPROJECT, name might be at args[2]
  if (entity.type === 'IFCPROJECT' && entity.args.length > 2) {
    const pName = entity.args[2]
    if (typeof pName === 'string' && pName !== '') return pName
  }

  return ''
}

function getStoreyElevation(model: IFCModel, storey: IFCEntity): number {
  // Try to get elevation from ObjectPlacement
  const placementRef = getArgValue(storey.args, 5)
  if (isRef(placementRef)) {
    const placement = resolveRef(model, placementRef)
    if (placement && placement.type === 'IFCLOCALPLACEMENT') {
      const coords = extractLocalPlacementCoords(model, placement)
      if (coords) return coords[2]
    }
  }

  // Fallback: try from Elevation property
  if (storey.args.length > 7) {
    const elevRef = getArgValue(storey.args, 7)
    if (typeof elevRef === 'number') return elevRef
  }

  return 0
}

function extractLocalPlacementCoords(
  model: IFCModel,
  placement: IFCEntity
): [number, number, number] | null {
  // IFCLOCALPLACEMENT args: (PlacementRelTo, RelativePlacement)
  // RelativePlacement is IFCAXIS2PLACEMENT3D
  const relPlacementRef = getArgValue(placement.args, 1)
  if (!isRef(relPlacementRef)) return null

  const axis2Placement = resolveRef(model, relPlacementRef)
  if (!axis2Placement) return null

  // IFCAXIS2PLACEMENT3D args: (Location, Axis, RefDirection)
  const locationRef = getArgValue(axis2Placement.args, 0)
  if (!isRef(locationRef)) return null

  const cartPoint = resolveRef(model, locationRef)
  if (!cartPoint || cartPoint.type !== 'IFCCARTESIANPOINT') return null

  // IFCARTESIANPOINT args: (Coordinates) — a list of numbers
  const coordsList = getArgValue(cartPoint.args, 0)
  if (Array.isArray(coordsList) && coordsList.length >= 2) {
    return [
      Number(coordsList[0]) || 0,
      Number(coordsList[1]) || 0,
      Number(coordsList[2]) || 0,
    ]
  }

  return null
}

function extractWallGeometry(
  model: IFCModel,
  wall: IFCEntity
): BuildingGeometry['buildings'][0]['walls'][0] | null {
  // Try to get geometry from representation
  const repRef = getArgValue(wall.args, 3)
  if (!isRef(repRef)) return null

  const rep = resolveRef(model, repRef)
  if (!rep || rep.type !== 'IFCPRODUCTDEFINITIONSHAPE') return null

  // Look for body representation
  const repList = getArgValue(rep.args, 2)
  if (!Array.isArray(repList)) return null

  for (const shapeRepRef of repList) {
    if (!isRef(shapeRepRef)) continue
    const shapeRep = resolveRef(model, shapeRepRef)
    if (!shapeRep || shapeRep.type !== 'IFCSHAPEREPRESENTATION') continue

    // Check if this is a body representation
    const repIdRef = getArgValue(shapeRep.args, 0)
    if (isRef(repIdRef)) {
      const repId = resolveRef(model, repIdRef)
      const repIdStr = repId ? getArgValue(repId.args, 0) : null
      if (repIdStr !== 'Body') continue
    } else if (typeof repIdRef === 'string' && repIdRef !== 'Body') {
      continue
    }

    // Get items
    const items = getArgValue(shapeRep.args, 2)
    if (!Array.isArray(items)) continue

    for (const itemRef of items) {
      if (!isRef(itemRef)) continue
      const item = resolveRef(model, itemRef)
      if (!item) continue

      // For extruded area solids, extract footprint
      if (item.type === 'IFCEXTRUDEDAREASOLID') {
        return extractExtrudedSolidWall(model, item)
      }

      // For polyline-based geometry
      if (item.type === 'IFCPOLYLINE') {
        return extractPolylineWall(model, item)
      }
    }
  }

  return null
}

function extractExtrudedSolidWall(
  model: IFCModel,
  solid: IFCEntity
): BuildingGeometry['buildings'][0]['walls'][0] | null {
  // IFCEXTRUDEDAREASOLID args: (SweptArea, Position, ExtrudedDirection, Depth)
  const profileRef = getArgValue(solid.args, 0)
  if (!isRef(profileRef)) return null

  const profile = resolveRef(model, profileRef)
  if (!profile) return null

  // Extract profile points
  let points: Array<{ x: number; y: number; z: number }> = []

  if (profile.type === 'IFCRECTANGLEPROFILEDEF') {
    // args: (ProfileType, ProfileName, XDim, YDim)
    const xDim = getArgValue(profile.args, 2) as number
    const yDim = getArgValue(profile.args, 3) as number
    const hx = (xDim || 0) / 2
    const hy = (yDim || 0) / 2
    points = [
      { x: -hx, y: -hy, z: 0 },
      { x: hx, y: -hy, z: 0 },
      { x: hx, y: hy, z: 0 },
      { x: -hx, y: hy, z: 0 },
    ]
  } else if (profile.type === 'IFCARBITRARYCLOSEDPROFILEDEF') {
    const outerCurveRef = getArgValue(profile.args, 2)
    if (isRef(outerCurveRef)) {
      const curve = resolveRef(model, outerCurveRef)
      if (curve) {
        points = extractCurvePoints2D(model, curve)
      }
    }
  }

  if (points.length < 2) return null

  // Get placement
  const posRef = getArgValue(solid.args, 1)
  let offsetX = 0, offsetY = 0, offsetZ = 0
  if (isRef(posRef)) {
    const placement = resolveRef(model, posRef)
    if (placement && placement.type === 'IFCAXIS2PLACEMENT3D') {
      const locRef = getArgValue(placement.args, 0)
      if (isRef(locRef)) {
        const cp = resolveRef(model, locRef)
        if (cp && cp.type === 'IFCCARTESIANPOINT') {
          const coords = getArgValue(cp.args, 0)
          if (Array.isArray(coords)) {
            offsetX = Number(coords[0]) || 0
            offsetY = Number(coords[1]) || 0
            offsetZ = Number(coords[2]) || 0
          }
        }
      }
    }
  }

  return {
    start: { x: points[0].x + offsetX, y: points[0].y + offsetY, z: points[0].z + offsetZ },
    end: { x: points[1].x + offsetX, y: points[1].y + offsetY, z: points[1].z + offsetZ },
  }
}

function extractPolylineWall(
  model: IFCModel,
  polyline: IFCEntity
): BuildingGeometry['buildings'][0]['walls'][0] | null {
  // IFCPOLYLINE args: (Points) — list of IFCCARTESIANPOINT refs
  const pointsRef = getArgValue(polyline.args, 0)
  if (!Array.isArray(pointsRef)) return null

  const pts: Array<{ x: number; y: number; z: number }> = []
  for (const ptRef of pointsRef) {
    if (!isRef(ptRef)) continue
    const cp = resolveRef(model, ptRef)
    if (!cp || cp.type !== 'IFCCARTESIANPOINT') continue

    const coords = getArgValue(cp.args, 0)
    if (Array.isArray(coords) && coords.length >= 2) {
      pts.push({
        x: Number(coords[0]) || 0,
        y: Number(coords[1]) || 0,
        z: Number(coords[2]) || 0,
      })
    }
  }

  if (pts.length < 2) return null

  return { start: pts[0], end: pts[1] }
}

function extractColumnGeometry(
  model: IFCModel,
  column: IFCEntity
): { x: number; y: number; z: number } | null {
  // Get from object placement
  const placementRef = getArgValue(column.args, 5)
  if (!isRef(placementRef)) return null

  const placement = resolveRef(model, placementRef)
  if (!placement || placement.type !== 'IFCLOCALPLACEMENT') return null

  const coords = extractLocalPlacementCoords(model, placement)
  if (!coords) return null

  return { x: coords[0], y: coords[1], z: coords[2] }
}

function extractCurvePoints(
  model: IFCModel,
  curve: IFCEntity
): [number, number, number][] {
  if (curve.type === 'IFCPOLYLINE') {
    const pointsRef = getArgValue(curve.args, 0)
    if (!Array.isArray(pointsRef)) return []
    return pointsRef
      .filter(isRef)
      .map((ref) => {
        const cp = resolveRef(model, ref)
        if (!cp || cp.type !== 'IFCCARTESIANPOINT') return null
        const coords = getArgValue(cp.args, 0)
        if (Array.isArray(coords) && coords.length >= 2) {
          return [Number(coords[0]) || 0, Number(coords[1]) || 0, Number(coords[2]) || 0] as [number, number, number]
        }
        return null
      })
      .filter((p): p is [number, number, number] => p !== null)
  }

  if (curve.type === 'IFCLINE') {
    const startRef = getArgValue(curve.args, 0)
    const endRef = getArgValue(curve.args, 1)
    const startPt = isRef(startRef) ? resolveRef(model, startRef) : null
    const endPt = isRef(endRef) ? resolveRef(model, endRef) : null

    const pts: [number, number, number][] = []
    if (startPt && startPt.type === 'IFCCARTESIANPOINT') {
      const coords = getArgValue(startPt.args, 0)
      if (Array.isArray(coords) && coords.length >= 2) {
        pts.push([Number(coords[0]) || 0, Number(coords[1]) || 0, Number(coords[2]) || 0])
      }
    }
    if (endPt && endPt.type === 'IFCCARTESIANPOINT') {
      const coords = getArgValue(endPt.args, 0)
      if (Array.isArray(coords) && coords.length >= 2) {
        pts.push([Number(coords[0]) || 0, Number(coords[1]) || 0, Number(coords[2]) || 0])
      }
    }
    return pts
  }

  return []
}

function extractCurvePoints2D(
  model: IFCModel,
  curve: IFCEntity
): Array<{ x: number; y: number; z: number }> {
  const pts3d = extractCurvePoints(model, curve)
  return pts3d.map(([x, y, z]) => ({ x, y, z }))
}

function extractEPSGCode(model: IFCModel, crs: IFCEntity): number | undefined {
  // IFCPROJECTEDCRS: args include Name, GeodeticDatum, MapProjection, MapZone, MapUnit
  // The EPSG code is sometimes in args[6] or can be found from the Name

  // Check if Name contains EPSG code pattern
  const name = getArgValue(crs.args, 0) as string | null
  if (name) {
    const epsgMatch = name.match(/EPSG[:\s]*(\d+)/i)
    if (epsgMatch) return parseInt(epsgMatch[1], 10)
  }

  // Check MapZone (arg[3]) for EPSG
  const mapZone = getArgValue(crs.args, 3)
  if (typeof mapZone === 'string') {
    const zoneMatch = mapZone.match(/EPSG[:\s]*(\d+)/i)
    if (zoneMatch) return parseInt(zoneMatch[1], 10)
  }

  // Check if there's a Name attribute (args might vary)
  if (crs.args.length > 6) {
    const identRef = getArgValue(crs.args, 6)
    if (typeof identRef === 'number') return identRef
  }

  return undefined
}

function extractUnitInfo(model: IFCModel, unitsCtx: IFCEntity): string {
  // IFcUNITASSIGNMENT or similar — look for length unit
  const unitsList = getArgValue(unitsCtx.args, 0)
  if (!Array.isArray(unitsList)) return ''

  for (const unitRef of unitsList) {
    if (!isRef(unitRef)) continue
    const unit = resolveRef(model, unitRef)
    if (!unit) continue

    if (
      unit.type === 'IFCSIUNIT' ||
      unit.type === 'IFCCONVERSIONBASEDUNIT' ||
      unit.type === 'IFCDERIVEDUNIT'
    ) {
      const unitType = getArgValue(unit.args, 0) as string
      if (unitType === 'LENGTHUNIT') {
        const name = getArgValue(unit.args, 1) as string
        return name || unit.type
      }
    }
  }

  return ''
}

function findRelatedEntities(
  model: IFCModel,
  parentId: number,
  relType: string,
  targetType: string
): IFCEntity[] {
  const results: IFCEntity[] = []

  // Find all IFCRELASSOCIATES / IFCRELCONTAINEDINSPATIALSTRUCTURE that reference the parent
  const rels = allOfType(model, relType)
  for (const rel of rels) {
    // RelatedObjects is typically args[4] for IFCRELASSIGNSTOGROUP
    // and args[5] for IFCRELAGGREGATES
    // IFCRELAGGREGATES: (GlobalId, OwnerHistory, Name, Description, RelatingObject, RelatedObjects)
    // IFCRELCONTAINEDINSPATIALSTRUCTURE: (GlobalId, OwnerHistory, Name, Description, RelatingStructure, RelatedElements)

    let relObjects: StepArg | null = null

    if (rel.type === 'IFCRELAGGREGATES') {
      // Check if parent is the RelatingObject (args[4])
      const relatingObj = getArgValue(rel.args, 4)
      if (isRef(relatingObj) && relatingObj.id === parentId) {
        relObjects = getArgValue(rel.args, 5)
      }
    } else if (rel.type === 'IFCRELCONTAINEDINSPATIALSTRUCTURE') {
      const relatingObj = getArgValue(rel.args, 4)
      if (isRef(relatingObj) && relatingObj.id === parentId) {
        relObjects = getArgValue(rel.args, 5)
      }
    } else if (rel.type === 'IFCRELASSIGNSTOGROUP') {
      const relatingObj = getArgValue(rel.args, 4)
      if (isRef(relatingObj) && relatingObj.id === parentId) {
        relObjects = getArgValue(rel.args, 5)
      }
    }

    if (Array.isArray(relObjects)) {
      for (const objRef of relObjects) {
        if (!isRef(objRef)) continue
        const entity = resolveRef(model, objRef)
        if (entity && (targetType === '*' || entity.type === targetType)) {
          results.push(entity)
        }
      }
    }
  }

  // Also check inverse: some IFC files use the parent as a related object
  if (results.length === 0) {
    for (const rel of rels) {
      let relObjects: StepArg | null = null
      let relatingObj: StepArg | null = null

      if (rel.type === 'IFCRELAGGREGATES') {
        relObjects = getArgValue(rel.args, 5)
        relatingObj = getArgValue(rel.args, 4)
      } else if (rel.type === 'IFCRELCONTAINEDINSPATIALSTRUCTURE') {
        relObjects = getArgValue(rel.args, 5)
        relatingObj = getArgValue(rel.args, 4)
      }

      if (!Array.isArray(relObjects)) continue

      // Check if parent is in RelatedObjects
      const parentInRelated = relObjects.some(
        (r) => isRef(r) && r.id === parentId
      )
      if (parentInRelated && isRef(relatingObj)) {
        const relating = resolveRef(model, relatingObj)
        if (relating && (targetType === '*' || relating.type === targetType)) {
          results.push(relating)
        }
      }
    }
  }

  return results
}

function findContainedEntities(
  model: IFCModel,
  parentId: number,
  targetType: string
): IFCEntity[] {
  return findRelatedEntities(model, parentId, 'IFCRELCONTAINEDINSPATIALSTRUCTURE', targetType)
}

function deduplicatePoints(
  pts: Array<{ x: number; y: number; z: number }>
): Array<{ x: number; y: number; z: number }> {
  const seen = new Set<string>()
  return pts.filter((p) => {
    const key = `${p.x.toFixed(4)},${p.y.toFixed(4)},${p.z.toFixed(4)}`
    if (seen.has(key)) return false
    seen.add(key)
    return true
  })
}

function headerOrFallback(model: IFCModel, fallback: string): string {
  return model.header.fileName || fallback
}

