import { ParsedSurveyData } from '../droneTypes';

/**
 * LAS/LAZ Point Cloud Parser
 *
 * AUDIT FIX (2026-07-03): Upgraded from a minimal parser that only supported
 * LAS point format 0 (20 bytes, no RGB, no GPS-time) with a hardcoded 28-byte
 * record length and 50K point cap.
 *
 * Now properly reads the LAS header to support:
 *   - LAS 1.2, 1.3, 1.4 (version major.minor at bytes 24-25)
 *   - Point data formats 0-3 (LAS 1.2-1.3) and 6-8 (LAS 1.4)
 *   - Variable point record length (read from header, not hardcoded)
 *   - RGB data (formats 2, 3, 7, 8)
 *   - GPS time (formats 1, 3, 6, 7, 8)
 *   - Variable header size with VLRs (offset to point data from bytes 96-99)
 *   - 100K point cap (was 50K)
 *
 * References:
 *   - LAS Specification 1.4-r15 (ASPRS, 2019)
 *   - LAS 1.2/1.3 point data record formats
 */

interface LasHeader {
  versionMajor: number
  versionMinor: number
  pointDataFormatId: number
  pointDataRecordLength: number
  pointDataOffset: number
  numberOfPointRecords: number
  scaleX: number
  scaleY: number
  scaleZ: number
  offsetX: number
  offsetY: number
  offsetZ: number
}

function readHeader(view: DataView): LasHeader {
  // File signature ("LASF")
  const sig = String.fromCharCode(
    view.getUint8(0), view.getUint8(1),
    view.getUint8(2), view.getUint8(3),
  )
  if (sig !== 'LASF') {
    throw new Error(`Invalid LAS file signature: "${sig}" (expected "LASF")`)
  }

  const versionMajor = view.getUint8(24)
  const versionMinor = view.getUint8(25)

  if (versionMajor < 1 || (versionMajor === 1 && versionMinor < 2)) {
    throw new Error(`Unsupported LAS version: ${versionMajor}.${versionMinor} (minimum 1.2)`)
  }

  // Header size (offset to first VLR) — typically 227 for LAS 1.2-1.3, 375 for LAS 1.4
  const headerSize = view.getUint16(94, true)

  // Offset to point data (may be larger than headerSize if VLRs exist)
  const pointDataOffset = view.getUint32(96, true)

  // Point data format ID (low 4 bits of byte 104; high 4 bits reserved in 1.4)
  const pointDataFormatId = view.getUint8(104) & 0x0F

  // Point data record length (bytes 105-106)
  const pointDataRecordLength = view.getUint16(105, true)

  // Number of point records (bytes 107-110 in 1.2-1.3; in 1.4 may be 0 if using extended counts)
  const numberOfPointRecords = view.getUint32(107, true)

  // Scale factors and offsets
  const scaleX = view.getFloat64(131, true)
  const scaleY = view.getFloat64(139, true)
  const scaleZ = view.getFloat64(147, true)
  const offsetX = view.getFloat64(155, true)
  const offsetY = view.getFloat64(163, true)
  const offsetZ = view.getFloat64(171, true)

  return {
    versionMajor,
    versionMinor,
    pointDataFormatId,
    pointDataRecordLength,
    pointDataOffset: pointDataOffset || headerSize,
    numberOfPointRecords,
    scaleX, scaleY, scaleZ,
    offsetX, offsetY, offsetZ,
  }
}

/**
 * Parse a single point record based on the point data format.
 *
 * LAS Point Data Record Formats:
 *   Format 0 (20 bytes): X, Y, Z, intensity, return info, classification, etc. (no GPS, no RGB)
 *   Format 1 (28 bytes): Format 0 + GPS time (8 bytes)
 *   Format 2 (26 bytes): Format 0 + RGB (2+2+2 bytes)
 *   Format 3 (34 bytes): Format 0 + GPS time + RGB
 *   Format 6 (30 bytes): LAS 1.4 — X, Y, Z, intensity, return info, classification, GPS time (no RGB)
 *   Format 7 (36 bytes): Format 6 + RGB
 *   Format 8 (38 bytes): Format 7 + NIR
 */
function parsePoint(
  view: DataView,
  offset: number,
  format: number,
  header: LasHeader,
): { x: number; y: number; z: number; r?: number; g?: number; b?: number; gpsTime?: number; classification?: number } {
  // X, Y, Z are always the first 12 bytes (3 × int32) in all formats
  const x = view.getInt32(offset, true) * header.scaleX + header.offsetX
  const y = view.getInt32(offset + 4, true) * header.scaleY + header.offsetY
  const z = view.getInt32(offset + 8, true) * header.scaleZ + header.offsetZ

  // Intensity (uint16 at offset 12)
  const intensity = view.getUint16(offset + 12, true)

  // Classification (offset 20 for formats 0-5, offset 18 for formats 6-8 in LAS 1.4)
  let classification = 0
  let gpsTime: number | undefined
  let r: number | undefined, g: number | undefined, b: number | undefined

  if (format <= 5) {
    classification = view.getUint8(offset + 20) & 0x1F  // low 5 bits

    // GPS time (format 1, 3, 4, 5) at offset 20
    if (format === 1 || format === 3 || format === 4 || format === 5) {
      gpsTime = view.getFloat64(offset + 20, true)
    }

    // RGB (format 2, 3, 5) — at the end of the record
    if (format === 2 || format === 3 || format === 5) {
      const rgbOffset = format === 2 ? offset + 20 : offset + 28
      r = view.getUint16(rgbOffset, true)
      g = view.getUint16(rgbOffset + 2, true)
      b = view.getUint16(rgbOffset + 4, true)
    }
  } else {
    // LAS 1.4 formats 6-8
    classification = view.getUint8(offset + 18) & 0x1F

    // GPS time at offset 22 for all 1.4 formats (6, 7, 8)
    gpsTime = view.getFloat64(offset + 22, true)

    // RGB (format 7, 8) at offset 30
    if (format === 7 || format === 8) {
      r = view.getUint16(offset + 30, true)
      g = view.getUint16(offset + 32, true)
      b = view.getUint16(offset + 34, true)
    }
  }

  return { x, y, z, r, g, b, gpsTime, classification }
}

export async function parseLas(file: File): Promise<ParsedSurveyData> {
  const arrayBuffer = await file.arrayBuffer();
  const view = new DataView(arrayBuffer);

  try {
    const header = readHeader(view)

    // Cap at 100K points (was 50K) for browser memory
    const maxPoints = Math.min(header.numberOfPointRecords, 100000)
    const recordLen = header.pointDataRecordLength

    const points: ParsedSurveyData['points'] = [];
    let hasRgb = false
    let hasGpsTime = false

    for (let i = 0; i < maxPoints; i++) {
      const offset = header.pointDataOffset + i * recordLen;
      if (offset + recordLen > arrayBuffer.byteLength) break;

      const pt = parsePoint(view, offset, header.pointDataFormatId, header)

      if (pt.r !== undefined) hasRgb = true
      if (pt.gpsTime !== undefined) hasGpsTime = true

      // Map LAS classification codes to feature codes
      let code = 'DRONE-PC'
      if (pt.classification === 2) code = 'GROUND'
      else if (pt.classification === 3) code = 'LOW-VEG'
      else if (pt.classification === 4) code = 'MED-VEG'
      else if (pt.classification === 5) code = 'HIGH-VEG'
      else if (pt.classification === 6) code = 'BUILDING'
      else if (pt.classification === 8) code = 'MODEL-KEY'
      else if (pt.classification === 9) code = 'WATER'

      points.push({
        easting: Number(pt.x.toFixed(3)),
        northing: Number(pt.y.toFixed(3)),
        rl: Number(pt.z.toFixed(3)),
        code,
      });
    }

    return {
      points,
      metadata: {
        source: 'LAS Point Cloud',
        format: `LAS ${header.versionMajor}.${header.versionMinor} (point format ${header.pointDataFormatId})`,
        totalPoints: header.numberOfPointRecords,
        droneSpecific: {
          flightDate: new Date().toISOString(),
          hasRgb,
          hasGpsTime,
          pointDataFormat: header.pointDataFormatId,
          recordLength: recordLen,
        },
      },
    };
  } catch (err) {
    throw new Error(
      `Failed to parse LAS file: ${err instanceof Error ? err.message : 'invalid format'}`
    );
  }
}

export async function parseLaz(file: File): Promise<ParsedSurveyData> {
  // LAZ is LASzip-compressed LAS — requires server-side decompression
  // (laszip-python or PDAL). The /api/compute/parse-laz route would
  // call PDAL or laszip to decompress, then parse the result.
  const formData = new FormData();
  formData.append('file', file);
  formData.append('type', 'parse-laz');

  const res = await fetch('/api/compute/parse-laz', {
    method: 'POST',
    body: formData,
  });

  if (!res.ok) {
    throw new Error(
      'LAZ parsing requires server-side processing (PDAL/laszip). ' +
      'The /api/compute/parse-laz endpoint is not yet configured. ' +
      'Convert your LAZ file to LAS using laszip or PDAL, then upload the .las file.'
    );
  }

  return res.json();
}

import { ParsedSurveyData } from '../droneTypes';

export async function parsePix4dCsv(file: File): Promise<ParsedSurveyData> {
  const text = await file.text();
  const rows = text.trim().split('\n').filter((row: any) => !row.startsWith('#') && row.trim());

  const points: ParsedSurveyData['points'] = rows.map((row: any) => {
    const cols = row.split(',').map((c: any) => c.trim());
    return {
      easting: parseFloat(cols[0]) || 0,
      northing: parseFloat(cols[1]) || 0,
      rl: parseFloat(cols[2]) || 0,
      code: cols[3] || 'GCP',
      description: cols[4] || '',
    };
  }).filter((p: any) => p.easting !== 0 || p.northing !== 0);

  return {
    points,
    metadata: {
      source: 'Pix4D CSV',
      format: 'CSV',
      totalPoints: points.length,
      droneSpecific: {
        gcpCount: points.length,
      },
    },
  };
}

export async function parsePix4dXml(file: File): Promise<ParsedSurveyData> {
  const text = await file.text();
  
  const gcpMatches = text.match(/<GCP[^>]*>(.*?)<\/GCP>/g) || [];
  
  const points: ParsedSurveyData['points'] = gcpMatches.map((match, i) => {
    const eastingMatch = match.match(/x[^0-9.-]*([-0-9.]+)/);
    const northingMatch = match.match(/y[^0-9.-]*([-0-9.]+)/);
    const zMatch = match.match(/z[^0-9.-]*([-0-9.]+)/);
    
    return {
      easting: parseFloat(eastingMatch?.[1] || '0'),
      northing: parseFloat(northingMatch?.[1] || '0'),
      rl: parseFloat(zMatch?.[1] || '0'),
      code: 'GCP',
      station: `GCP${i + 1}`,
    };
  });

  const errorMatch = text.match(/averageError[^0-9.-]*([-0-9.]+)/);
  const averageError = errorMatch ? parseFloat(errorMatch[1]) : undefined;

  return {
    points,
    metadata: {
      source: 'Pix4D Report',
      format: 'XML',
      totalPoints: points.length,
      droneSpecific: {
        averageError,
        gcpCount: points.length,
      },
    },
  };
}

/**
 * METARDU — RINEX Parser (v2 / v3 / v4)
 * Phase C1: RINEX Observation File Parser for GNSS data
 *
 * Parses RINEX 2.x (GPS/GLONASS), 3.x (multi-GNSS), and 4.x observation files.
 * Extracts header metadata AND observation epoch records (pseudorange, carrier phase,
 * SNR, doppler) for all satellite systems.
 *
 * References:
 *   - RINEX 2.11: IGS RINEX Working Group
 *   - RINEX 3.04: IGS RINEX Working Group, 2018
 *   - RINEX 4.00: IGS RINEX Working Group, 2023
 */

import { registerParser } from '../registry'
import { ParseResult, ParsedPoint } from '@/types/importer'

// ─── Header Types ────────────────────────────────────────────────────────────

export interface RinexHeader {
  version: string
  fileType: string
  markerName: string
  markerNumber?: string
  observer?: string
  agency?: string
  receiverType?: string
  receiverSn?: string
  antennaType?: string
  antennaSn?: string
  approxPosECEF?: { x: number; y: number; z: number }
  antennaDelta?: { h: number; e: number; n: number }
  timeOfFirstObs?: string
  // Extended fields for v3/v4
  systems?: string[] // e.g. ['G', 'R', 'E', 'C']
  rinexDate?: string // date of file creation
  interval?: number // observation interval in seconds
  /**
   * AUDIT FIX (C9/M2, 2026-07-02): Observation type list per system.
   * Maps system char → ordered list of obs type codes (e.g. ['C1C','L1C','S1C','C2W','L2W','S2W']).
   * Used to correctly assign observation values by position instead of
   * the magnitude heuristic that was previously used.
   */
  obsTypes?: Record<string, string[]>
}

// ─── Observation Types ───────────────────────────────────────────────────────

export interface RinexObservation {
  epoch: Date
  satellite: string    // e.g. 'G01', 'R12', 'E05'
  system: 'GPS' | 'GLONASS' | 'GALILEO' | 'SBAS' | 'QZSS' | 'BDS' | 'IRNSS' | 'unknown'
  pseudorangeL1?: number   // metres
  pseudorangeL2?: number
  carrierPhaseL1?: number  // cycles
  carrierPhaseL2?: number
  snrL1?: number          // dB-Hz (signal-to-noise ratio)
  snrL2?: number
  dopplerL1?: number      // Hz
  dopplerL2?: number      // Hz
  lossOfLockL1?: number   // 0=ok, 1=cycle slip
  lossOfLockL2?: number
}

// ─── Parse Result ────────────────────────────────────────────────────────────

export interface RinexParseResult extends ParseResult {
  format: 'rinex'
  header: RinexHeader
  observations: RinexObservation[]
  version: string
  systems: string[]
  epochCount: number
  errors: string[]
}

// ─── Satellite System Map ───────────────────────────────────────────────────

const SYSTEM_MAP: Record<string, string> = {
  G: 'GPS',
  R: 'GLONASS',
  E: 'GALILEO',
  S: 'SBAS',
  J: 'QZSS',
  C: 'BDS',
  I: 'IRNSS',
}

function identifySystem(satId: string): RinexObservation['system'] {
  const sysChar = satId.charAt(0).toUpperCase()
  return (SYSTEM_MAP[sysChar] || 'unknown') as RinexObservation['system']
}

// ─── Header Parsing ──────────────────────────────────────────────────────────

export function parseRinexHeader(content: string): RinexHeader {
  const lines = content.split('\n')
  const header: any = {}

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trimEnd()
    // Pad line to at least 80 chars so column extraction works
    const padded = line.padEnd(80, ' ')

    const label = padded.substring(60).trim()

    if (label === 'RINEX VERSION / TYPE') {
      header.version = padded.substring(0, 9).trim()
      // RINEX 2/3: file type character (O/N/M/G/R/E) appears after version number
      // Use regex to find the first valid file type char after the version
      let ftMatch = padded.substring(0, 40).match(/\d+\.\d+\s+([ONMGRE])/)
      if (ftMatch) {
        header.fileType = ftMatch[1]
      }
    } else if (label === 'MARKER NAME') {
      header.markerName = padded.substring(0, 60).trim()
    } else if (label === 'MARKER NUMBER') {
      header.markerNumber = padded.substring(0, 20).trim()
    } else if (label === 'OBSERVER / AGENCY') {
      header.observer = padded.substring(0, 20).trim()
      header.agency = padded.substring(20, 60).trim()
    } else if (label === 'REC # / TYPE / VERS') {
      header.receiverSn = padded.substring(0, 20).trim()
      // Extract receiver type as the second whitespace-delimited field group
      const recContent = padded.substring(0, 60).trim()
      const recParts = recContent.split(/\s{2,}/)
      if (recParts.length >= 2) {
        header.receiverType = recParts[1].trim()
      } else {
        header.receiverType = padded.substring(20, 40).trim()
      }
    } else if (label === 'ANT # / TYPE') {
      header.antennaSn = padded.substring(0, 20).trim()
      const antContent = padded.substring(0, 60).trim()
      const antParts = antContent.split(/\s{2,}/)
      if (antParts.length >= 2) {
        header.antennaType = antParts[1].trim()
      } else {
        header.antennaType = padded.substring(20, 40).trim()
      }
    } else if (label === 'APPROX POSITION XYZ') {
      const x = parseFloat(padded.substring(0, 14))
      const y = parseFloat(padded.substring(14, 28))
      const z = parseFloat(padded.substring(28, 42))
      if (isFinite(x) && isFinite(y) && isFinite(z)) {
        header.approxPosECEF = { x, y, z }
      }
    } else if (label === 'ANTENNA: DELTA H/E/N') {
      const h = parseFloat(padded.substring(0, 14))
      const e = parseFloat(padded.substring(14, 28))
      const n = parseFloat(padded.substring(28, 42))
      if (isFinite(h) && isFinite(e) && isFinite(n)) {
        header.antennaDelta = { h, e, n }
      }
    } else if (label === 'TIME OF FIRST OBS') {
      header.timeOfFirstObs = padded.substring(0, 43).trim()
    } else if (label === 'INTERVAL') {
      header.interval = parseFloat(padded.substring(0, 10))
    } else if (label === 'SYS / # / OBS TYPES' || label === '# / TYPES OF OBSERV') {
      // AUDIT FIX (C9/M2, 2026-07-02): Parse the actual observation type
      // codes so observation lines can be assigned by position instead of
      // magnitude heuristic. Previously only the system char was recorded.
      //
      // RINEX 3: "G    4 C1C L1C S1C C2W" — sys char, count, then type codes
      // RINEX 2: "     4    C1    L1    L2    P2    S1    S2" — count, then types
      if (!header.systems) header.systems = []
      if (!header.obsTypes) header.obsTypes = {}

      const sysChar = padded.substring(0, 1).trim()
      if (sysChar && SYSTEM_MAP[sysChar]) {
        if (!header.systems.includes(sysChar)) header.systems.push(sysChar)

        // Parse the type codes from the rest of the line
        // RINEX 3 format: after sys char + count, types are space-separated 3-char codes
        // RINEX 2 format: after count, types are space-separated 2-char codes
        const afterSys = padded.substring(1).trim()
        // First token is the count; remaining tokens are the type codes
        const tokens = afterSys.split(/\s+/).filter(Boolean)
        if (tokens.length > 1) {
          // tokens[0] = count, tokens[1:] = type codes
          (header?.obsTypes)[sysChar] = tokens.slice(1)
        }
      } else if (!sysChar) {
        // RINEX 2: "# / TYPES OF OBSERV" — no system char, types apply to GPS
        const tokens = padded.trim().split(/\s+/).filter(Boolean)
        if (tokens.length > 1) {
          const count = parseInt(tokens[0])
          if (isFinite(count) && count > 0) {
            (header?.obsTypes)['G'] = tokens.slice(1, 1 + count)
            if (!header.systems.includes('G')) header.systems.push('G')
          }
        }
      }
    } else if (label === 'END OF HEADER') {
      break
    }
  }

  return header as RinexHeader
}

// ─── RINEX Version Detection ────────────────────────────────────────────

function detectRinexVersion(content: string): number {
  const firstLine = content.split('\n')[0]
  if (!firstLine) return 2
  const match = firstLine.match(/^\s*(\d+\.?\d*)/)
  if (match) {
    return parseFloat(match[1])
  }
  return 2
}

// ─── Observation Parsing Helpers ─────────────────────────────────────────────

/**
 * Map a RINEX observation type code to a field on RinexObservation.
 *
 * AUDIT FIX (C9/M2, 2026-07-02): Replaces the magnitude heuristic with
 * proper type-code-based assignment. RINEX obs type codes:
 *   C1, C1C, C1W → pseudorange L1
 *   C2, C2C, C2W, C2L → pseudorange L2
 *   P1, P2 → pseudorange L1/L2 (P-code)
 *   L1, L1C, L1W → carrier phase L1
 *   L2, L2C, L2W, L2L → carrier phase L2
 *   S1, S1C, S1W → SNR L1
 *   S2, S2C, S2W, S2L → SNR L2
 *   D1, D1C → doppler L1
 *   D2, D2C → doppler L2
 *
 * @param obsType  RINEX observation type code (2 or 3 chars)
 * @param value    The parsed numeric value
 * @param obs      The observation object to populate
 */
function assignObsByType(obsType: string, value: number, obs: RinexObservation): void {
  const t = obsType.toUpperCase()

  // Pseudorange
  if (t === 'C1' || t === 'C1C' || t === 'C1W' || t === 'C1L' || t === 'P1') {
    if (!obs.pseudorangeL1) obs.pseudorangeL1 = value
  } else if (t === 'C2' || t === 'C2C' || t === 'C2W' || t === 'C2L' || t === 'C2X' || t === 'P2') {
    if (!obs.pseudorangeL2) obs.pseudorangeL2 = value
  }
  // Carrier phase
  else if (t === 'L1' || t === 'L1C' || t === 'L1W' || t === 'L1L') {
    if (!obs.carrierPhaseL1) obs.carrierPhaseL1 = value
  } else if (t === 'L2' || t === 'L2C' || t === 'L2W' || t === 'L2L' || t === 'L2X') {
    if (!obs.carrierPhaseL2) obs.carrierPhaseL2 = value
  }
  // SNR
  else if (t === 'S1' || t === 'S1C' || t === 'S1W') {
    if (!obs.snrL1) obs.snrL1 = value
  } else if (t === 'S2' || t === 'S2C' || t === 'S2W') {
    if (!obs.snrL2) obs.snrL2 = value
  }
  // Doppler
  else if (t === 'D1' || t === 'D1C') {
    if (!obs.dopplerL1) obs.dopplerL1 = value
  } else if (t === 'D2' || t === 'D2C') {
    obs.dopplerL2 = value
  }
  // Unknown type — silently skip (the value is stored but not mapped)
}

/**
 * Parse a RINEX 2.x epoch header line.
 * Format: " YY MM DD HH MM SS.sss  #sat  flag  ...  sat1 sat2 ..."
 */
function parseRinex2Epoch(line: string): { epoch: Date; satCount: number; sats: string[] } | null {
  // RINEX 2 epoch format: " YY MM DD HH MM SS.sss  flag  #sat  sat1 sat2 ..."
  // Supports both column-based (80-char) and space-separated formats.
  let year: number, month: number, day: number, hour: number, minute: number, second: number
  let satCount: number
  const sats: string[] = []

  // Try column-based parsing first (for full 80-char records)
  if (line.length >= 32) {
    year = parseInt(line.substring(0, 3).trim())
    month = parseInt(line.substring(3, 6).trim())
    day = parseInt(line.substring(6, 9).trim())
    hour = parseInt(line.substring(9, 12).trim())
    minute = parseInt(line.substring(12, 15).trim())
    second = parseFloat(line.substring(15, 26).trim())
    satCount = parseInt(line.substring(29, 32).trim())
  } else {
    // Fallback: space-separated tokens
    const parts = line.trim().split(/\s+/)
    if (parts.length < 7) return null
    year = parseInt(parts[0])
    month = parseInt(parts[1])
    day = parseInt(parts[2])
    hour = parseInt(parts[3])
    minute = parseInt(parts[4])
    second = parseFloat(parts[5])
    // parts[6] = epoch flag, parts[7] = sat count
    satCount = parts.length > 7 ? parseInt(parts[7]) : 0
  }

  if (!isFinite(year) || !isFinite(month) || !isFinite(day)) return null

  // RINEX 2 uses 2-digit year (80-99 = 1980-1999, 0-79 = 2000-2079)
  const fullYear = year >= 80 ? 1900 + year : 2000 + year

  const epoch = new Date(Date.UTC(fullYear, month - 1, day, hour, minute, isFinite(second) ? second : 0))

  if (!isFinite(satCount)) satCount = 0

  // Satellite PRNs: try column-based first (3-char fields from pos 32), then token-based fallback
  if (satCount > 0 && line.length >= 32) {
    const columnSats: string[] = []
    for (let i = 0; i < satCount && 32 + i * 3 + 2 < line.length; i++) {
      const prn = line.substring(32 + i * 3, 32 + i * 3 + 3).trim()
      if (prn.length > 0 && /^\d+$/.test(prn)) {
        columnSats.push('G' + prn.padStart(2, '0'))
      } else if (prn.length > 0) {
        columnSats.push(prn)
      }
    }
    if (columnSats.length === satCount) {
      return { epoch, satCount, sats: columnSats }
    }
  }

  // Fallback: parse remaining tokens as satellite PRNs
  if (satCount > 0) {
    const parts = line.trim().split(/\s+/)
    // Tokens after the first 8 (YY MM DD HH MM SS flag #sat) are satellite PRNs
    const satTokens = parts.slice(8)
    for (let i = 0; i < Math.min(satCount, satTokens.length); i++) {
      const prn = satTokens[i]
      if (/^\d+$/.test(prn)) {
        sats.push('G' + prn.padStart(2, '0'))
      } else {
        sats.push(prn)
      }
    }
  }

  return { epoch, satCount, sats }
}

/**
 * Parse a RINEX 3.x epoch header line.
 * Format: "> 2024 01 15 08 30  0.0000000  0  4 G07G12G19G24"
 */
function parseRinex3Epoch(line: string): { epoch: Date; satCount: number; sats: string[] } | null {
  // Skip the ">" marker
  const rest = line.substring(1).trim()

  const parts = rest.split(/\s+/)
  if (parts.length < 7) return null

  const year = parseInt(parts[0])
  const month = parseInt(parts[1])
  const day = parseInt(parts[2])
  const hour = parseInt(parts[3])
  const minute = parseInt(parts[4])
  const second = parseFloat(parts[5])
  const epochFlag = parseInt(parts[6])

  if (!isFinite(year) || !isFinite(month) || !isFinite(day)) return null
  if (epochFlag !== 0) return null // skip event/header records

  const epoch = new Date(Date.UTC(year, month - 1, day, hour, minute, isFinite(second) ? second : 0))

  const satCount = parts.length > 7 ? parseInt(parts[7]) : 0
  const sats: string[] = []

  // Remaining parts are satellite IDs (3-char in v3: G07, R12, E05)
  if (isFinite(satCount) && satCount > 0) {
    for (let i = 0; i < satCount && i + 8 < parts.length; i++) {
      const satId = parts[8 + i].trim()
      if (satId.length >= 2) {
        // Normalize: G7 -> G07
        const sys = satId.charAt(0).toUpperCase()
        const num = parseInt(satId.substring(1))
        if (isFinite(num)) {
          sats.push(sys + String(num).padStart(2, '0'))
        } else {
          sats.push(satId)
        }
      }
    }
  }

  return { epoch, satCount: isFinite(satCount) ? satCount : 0, sats }
}

/**
 * Parse a RINEX 4.x epoch header line.
 * Format: "> 2024 01 15 08 30  0.0000000  0  4 G007G012G019G024"
 * Similar to v3 but with 4-character satellite IDs.
 */
function parseRinex4Epoch(line: string): { epoch: Date; satCount: number; sats: string[] } | null {
  // Same basic structure as v3, but satellite IDs are 4 chars (G001, R001, E001, C001)
  const result = parseRinex3Epoch(line)
  if (!result) return null

  // Normalize 4-char IDs: G007 -> G07 (internal normalization)
  const sats = result.sats.map(function(satId) {
    const sys = satId.charAt(0).toUpperCase()
    const num = parseInt(satId.substring(1))
    if (isFinite(num)) {
      return sys + String(num).padStart(2, '0')
    }
    return satId
  })

  return { epoch: result.epoch, satCount: result.satCount, sats: sats }
}

/**
 * Parse a RINEX 2 observation line.
 * Format: "PRN L1 L2 ... P1 P2 ... S1 S2 ..."
 * Values are 14 characters wide each.
 */
function parseRinex2ObsLine(
  line: string,
  epoch: Date,
  satId: string,
  obsTypes?: string[]  // AUDIT FIX (C9/M2): from (header?.obsTypes)['G']
): RinexObservation | null {
  const prn = line.substring(0, 3).trim()
  if (!prn || prn.length === 0) return null

  const fullSatId = /^\d+$/.test(prn) ? 'G' + prn.padStart(2, '0') : prn
  const obs: RinexObservation = {
    epoch: epoch,
    satellite: fullSatId,
    system: identifySystem(fullSatId),
  }

  const fieldWidth = 14
  const maxFields = Math.floor((line.length - 3) / fieldWidth)

  for (let i = 0; i < maxFields; i++) {
    const start = 3 + i * fieldWidth
    const valStr = line.substring(start, start + fieldWidth).trim()
    if (!valStr || valStr === '              ') continue

    const val = parseFloat(valStr)
    if (!isFinite(val)) continue

    // AUDIT FIX (C9/M2, 2026-07-02): Use obsTypes from header when available.
    // Fall back to magnitude heuristic only when header is missing.
    if (obsTypes && obsTypes[i]) {
      assignObsByType(obsTypes[i], val, obs)
    } else {
      // Fallback heuristic (for malformed RINEX without proper header)
      if (i === 0 && Math.abs(val) > 100) {
        obs.carrierPhaseL1 = val
      } else if (i === 1 && Math.abs(val) > 100) {
        obs.carrierPhaseL2 = val
      } else if (i === 2 && Math.abs(val) > 1e4) {
        obs.pseudorangeL1 = val
      } else if (i === 3 && Math.abs(val) > 1e4) {
        obs.pseudorangeL2 = val
      } else if (i === 4 && Math.abs(val) > 1e4) {
        obs.pseudorangeL1 = val
      } else if (i === 5 && Math.abs(val) > 1e4) {
        obs.pseudorangeL2 = val
      } else if (val >= 1 && val <= 60 && i >= 6) {
        if (!obs.snrL1) obs.snrL1 = val
        else obs.snrL2 = val
      }
    }
  }

  return obs
}

/**
 * Parse a RINEX 3 observation line.
 * Format: "G07  12345678.012  -9876543.210  23456789.012  ..."
 * Satellite ID is 3 chars, then observation values (14 chars each).
 */
function parseRinex3ObsLine(
  line: string,
  epoch: Date,
  obsTypesBySys?: Record<string, string[]>
): RinexObservation | null {
  const satId = line.substring(0, 3).trim()
  if (!satId || satId.length < 2) return null

  const sys = satId.charAt(0).toUpperCase()
  const num = parseInt(satId.substring(1))
  const fullSatId = isFinite(num) ? sys + String(num).padStart(2, '0') : satId

  const obs: RinexObservation = {
    epoch: epoch,
    satellite: fullSatId,
    system: identifySystem(fullSatId),
  }

  const sysObsTypes = obsTypesBySys?.[sys]

  const fieldWidth = 14
  const maxFields = Math.floor((line.length - 3) / fieldWidth)

  for (let i = 0; i < maxFields; i++) {
    const start = 3 + i * fieldWidth
    const valStr = line.substring(start, start + fieldWidth).trim()
    if (!valStr || valStr.length === 0) continue

    const val = parseFloat(valStr)
    if (!isFinite(val)) continue

    if (sysObsTypes && sysObsTypes[i]) {
      assignObsByType(sysObsTypes[i], val, obs)
    } else {
      if (Math.abs(val) > 1e4) {
        if (!obs.pseudorangeL1) obs.pseudorangeL1 = val
        else if (!obs.pseudorangeL2) obs.pseudorangeL2 = val
      } else if (Math.abs(val) > 100) {
        if (!obs.carrierPhaseL1) obs.carrierPhaseL1 = val
        else if (!obs.carrierPhaseL2) obs.carrierPhaseL2 = val
      } else if (val >= 1 && val <= 60) {
        if (!obs.snrL1) obs.snrL1 = val
        else obs.snrL2 = val
      }
    }
  }

  return obs
}

/**
 * Parse a RINEX 4 observation line.
 * Format: "G007  12345678.012  -9876543.210  ..."
 * Satellite ID is 4 chars, then observation values (16 chars each in v4).
 */
function parseRinex4ObsLine(
  line: string,
  epoch: Date,
  obsTypesBySys?: Record<string, string[]>
): RinexObservation | null {
  const satId = line.substring(0, 4).trim()
  if (!satId || satId.length < 3) return null

  const sys = satId.charAt(0).toUpperCase()
  const num = parseInt(satId.substring(1))
  const fullSatId = isFinite(num) ? sys + String(num).padStart(2, '0') : satId

  const obs: RinexObservation = {
    epoch: epoch,
    satellite: fullSatId,
    system: identifySystem(fullSatId),
  }

  const sysObsTypes = obsTypesBySys?.[sys]

  const fieldWidth = 16
  const maxFields = Math.floor((line.length - 4) / fieldWidth)

  for (let i = 0; i < maxFields; i++) {
    const start = 4 + i * fieldWidth
    const valStr = line.substring(start, start + fieldWidth).trim()
    if (!valStr || valStr.length === 0) continue

    const val = parseFloat(valStr)
    if (!isFinite(val)) continue

    if (sysObsTypes && sysObsTypes[i]) {
      assignObsByType(sysObsTypes[i], val, obs)
    } else {
      if (Math.abs(val) > 1e4) {
        if (!obs.pseudorangeL1) obs.pseudorangeL1 = val
        else if (!obs.pseudorangeL2) obs.pseudorangeL2 = val
      } else if (Math.abs(val) > 100) {
        if (!obs.carrierPhaseL1) obs.carrierPhaseL1 = val
        else if (!obs.carrierPhaseL2) obs.carrierPhaseL2 = val
      } else if (val >= 1 && val <= 60) {
        if (!obs.snrL1) obs.snrL1 = val
        else obs.snrL2 = val
      }
    }
  }

  return obs
}

// ─── Main Observation Block Parsing ──────────────────────────────────────────

/**
 * Parse observation blocks from RINEX data.
 * Handles v2 (column-formatted epochs), v3 (> marker epochs), and v4.
 */
function parseObservationBlocks(
  content: string,
  version: number,
  header?: RinexHeader  // AUDIT FIX (C9/M2): pass header for obsTypes
): { observations: RinexObservation[]; epochCount: number; errors: string[] } {
  const lines = content.split('\n')
  const observations: RinexObservation[] = []
  const errors: string[] = []
  let epochCount = 0

  // Find END OF HEADER to start observation parsing
  let startIdx = 0
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].substring(60).trim() === 'END OF HEADER') {
      startIdx = i + 1
      break
    }
  }

  let i = startIdx
  while (i < lines.length) {
    const line = lines[i]

    if (version >= 3) {
      // RINEX 3/4: epoch lines start with ">"
      if (!line.startsWith('>')) {
        i++
        continue
      }

      const epochInfo = version >= 4
        ? parseRinex4Epoch(line)
        : parseRinex3Epoch(line)

      if (!epochInfo) {
        i++
        continue
      }

      epochCount++
      i++

      // Read observation lines for this epoch
      // Use satCount (numeric) not sats.length since inline satellite IDs may be absent
      const satCount = epochInfo.satCount
      for (let s = 0; s < satCount && i < lines.length; s++) {
        const obsLine = lines[i]
        if (obsLine.trim().length === 0 || obsLine.startsWith('>')) break

        if (version >= 4) {
          const obs = parseRinex4ObsLine(obsLine, epochInfo.epoch, (header?.obsTypes))
          if (obs) observations.push(obs)
        } else {
          const obs = parseRinex3ObsLine(obsLine, epochInfo.epoch, (header?.obsTypes))
          if (obs) observations.push(obs)
        }
        i++
      }
    } else {
      // RINEX 2: epoch lines have epoch flag at position 28-29
      const trimmed = line.trim()
      if (trimmed.length < 28) {
        i++
        continue
      }

      // Check if this looks like an epoch header line
      // RINEX 2 epoch format: YY MM DD HH MM SS.sss  flag  #sat  sat1 sat2...
      // After trimming, it should start with a digit pair (year)
      if (!/^\d{2}\s/.test(trimmed)) {
        i++
        continue
      }

      // Check if position 26-27 looks like a space + flag (typical epoch line)
      // Also verify it looks like a date (first char is digit or space)
      if (!/^\s*\d{2}/.test(trimmed)) {
        i++
        continue
      }

      const epochInfo = parseRinex2Epoch(trimmed)
      if (!epochInfo) {
        i++
        continue
      }

      epochCount++
      i++

      // Read observation lines for this epoch
      for (let s = 0; s < epochInfo.satCount && i < lines.length; s++) {
        const obsLine = lines[i]
        if (obsLine.trim().length < 3) break

        const obs = parseRinex2ObsLine(obsLine, epochInfo.epoch, epochInfo.sats[s] || '', (header?.obsTypes)?.['G'])
        if (obs) observations.push(obs)
        i++
      }

      // Skip any continuation lines (if sats > expected, skip remaining)
      // RINEX 2 also has event/skip records which we skip
    }
  }

  return { observations, epochCount, errors }
}

// ─── Main Parser ─────────────────────────────────────────────────────────────

export function parseRinex(content: string): RinexParseResult {
  const header = parseRinexHeader(content)
  const version = detectRinexVersion(content)
  const points: ParsedPoint[] = []
  const parseErrors: string[] = []

  // Parse observation blocks
  const obsResult = parseObservationBlocks(content, version, header)

  // Collect unique satellite systems
  const systemsSet = new Set<string>()
  for (const obs of obsResult.observations) {
    const sysChar = obs.satellite.charAt(0).toUpperCase()
    if (SYSTEM_MAP[sysChar]) systemsSet.add(sysChar)
  }
  const systems = Array.from(systemsSet)

  // If we have an approximate position, export as a point
  if (header.approxPosECEF) {
    points.push({
      point_no: header.markerName || 'UNKNOWN',
      feature_code: 'GNSS_STATIC',
      instrument_height: header.antennaDelta ? header.antennaDelta.h : 0,
      raw: {
        ecef_x: header.approxPosECEF.x,
        ecef_y: header.approxPosECEF.y,
        ecef_z: header.approxPosECEF.z,
        receiver: header.receiverType,
        antenna: header.antennaType,
        epoch_count: obsResult.epochCount,
        observation_count: obsResult.observations.length,
        systems: systems,
        version: String(version),
      }
    })
  }

  return {
    format: 'rinex',
    header,
    points,
    warnings: [],
    observations: obsResult.observations,
    version: String(version),
    systems,
    epochCount: obsResult.epochCount,
    errors: [...parseErrors, ...obsResult.errors],
  }
}

// ─── Parser Registration ─────────────────────────────────────────────────────

registerParser({
  format: 'rinex',
  label: 'RINEX Observation File (v2/v3/v4)',
  extensions: ['rnx', 'obs', 'O', 'o', '21O', '22O', '23O'],
  detect: function(content) {
    return content.includes('RINEX VERSION / TYPE') && content.includes('END OF HEADER')
  },
  parse: function(content): ParseResult {
    return parseRinex(content)
  }
})

import { registerParser } from '../registry';
import { ParseResult, ParsedPoint } from '@/types/importer';
import { parseSouthData } from '@/lib/import/totalStation/parseSouth';

/**
 * South total station .dat/.dc format registration.
 *
 * Detection strategy:
 * 1. If file starts with "South," header — confirmed South
 * 2. If file contains SS observation rows with South-style DMS angles — likely South
 * 3. If .dat/.dc extension and coordinate rows match pattern — South coordinate export
 *
 * Note: .dc is also used by Trimble RW5. The detect function checks content to
 * disambiguate. Trimble detection runs first if file contains "--Trimble" markers.
 */
registerParser({
  format: 'south',
  label: 'South Total Station (.dat/.dc)',
  extensions: ['dat', 'dc'],
  detect: (content) => {
    const trimmed = content.trim();
    const firstLine = trimmed.split('\n')[0]?.trim() ?? '';

    // Explicit South header
    if (firstLine.toLowerCase().startsWith('south,')) return true;

    // SS observation rows (South format: SS,obs#,station,target,HCL_DMS,...)
    // Distinguished from Trimble SS by key=value absence and numeric DMS angle
    const ssLineMatch = /^(SS,)\d+,/.test(firstLine) &&
      !firstLine.includes('=') &&
      /\d{2,3}\.\d{4}/.test(firstLine);

    if (ssLineMatch) return true;

    // Coordinate-only South file: integer pt#, name, numeric E, N, RL, quoted code, type
    // Pattern: 1,BM1,984321.456,1234567.890,1542.345,"BM1",0
    const coordLineMatch = /^\s*\d+\s*,/.test(firstLine) &&
      !/^\s*\d+\s*,\s*[\d.]+\s*,\s*[\d.]+\s*,\s*[\d.]+/.test(firstLine.replace(/"[^"]*"/g, '').replace(/'[^']*'/g, '')) === false;

    // More reliable: check if any line matches the full South coordinate pattern
    const lines = trimmed.split('\n').slice(0, 10);
    const southCoordRegex = /^\s*\d+\s*,\s*\w+\s*,\s*[\d.]+\s*,\s*[\d.]+\s*,\s*[\d.]+/;
    const hasSouthCoord = lines.some((l) => southCoordRegex.test(l.trim()));

    // Must NOT be Trimble (Trimble uses key=value pairs)
    const hasTrimbleMarkers = trimmed.includes('--Trimble') || /[A-Z]{2}=/i.test(trimmed);

    if (hasSouthCoord && !hasTrimbleMarkers) return true;

    return false;
  },
  parse: (content): ParseResult => {
    const result = parseSouthData(content);
    const points: ParsedPoint[] = [];
    const warnings: string[] = [...result.warnings];

    // Convert coordinate points to ParsedPoint format
    for (const coord of result.coordinates) {
      const point: ParsedPoint = {
        point_no: String(coord.pointNumber),
        easting: coord.easting,
        northing: coord.northing,
        rl: coord.elevation,
        code: coord.code || undefined,
        remark: coord.pointName !== String(coord.pointNumber) ? coord.pointName : undefined,
        raw: {
          pointNumber: coord.pointNumber,
          pointName: coord.pointName,
          pointType: coord.pointType,
        } as Record<string, unknown>,
      };
      points.push(point);
    }

    // Convert observations to ParsedPoint entries
    for (const obs of result.observations) {
      const point: ParsedPoint = {
        point_no: obs.target,
        bearing:
          obs.hclDeg + obs.hclMin / 60 + obs.hclSec / 3600,
        distance: obs.slopeDistance,
        code: `${obs.station}→${obs.target}`,
        raw: {
          observationNumber: obs.observationNumber,
          station: obs.station,
          target: obs.target,
          hcl: `${obs.hclDeg}°${obs.hclMin}'${obs.hclSec}"`,
          targetHeight: obs.targetHeight,
          slopeDistance: obs.slopeDistance,
          va: `${obs.vaDeg}°${obs.vaMin}'${obs.vaSec}"`,
          instrumentHeight: obs.instrumentHeight,
        } as Record<string, unknown>,
      };
      points.push(point);
    }

    // Pass through errors as warnings (registry parsers use warnings, not errors)
    for (const err of result.errors) {
      warnings.push(err);
    }

    if (points.length === 0) {
      warnings.push(
        'No valid South coordinate or observation records parsed. Verify the file format.'
      );
    }

    return {
      format: 'south',
      points,
      warnings,
      metadata: {
        fileType: result.type,
        coordinateCount: result.coordinates.length,
        observationCount: result.observations.length,
      },
    };
  },
});

import { registerParser } from '../registry';
import { ParseResult, ParsedPoint } from '@/types/importer';
import { bearingDistanceToDelta } from '@/lib/geodesy/coordinates';

registerParser({
  format: 'csv',
  label: 'Traverse CSV (Bearing + Distance)',
  extensions: ['csv'],
  detect: (content) => {
    const lines = content.trim().split('\n');
    if (lines.length < 2) return false;
    const headers = lines[0].split(',').map((h: any) => h.trim().toLowerCase());
    const hasBearing = headers.some((h: any) => ['bearing', 'azimuth', 'brg', 'bear'].includes(h));
    const hasDistance = headers.some((h: any) => ['distance', 'dist', 'hd', 'length'].includes(h));
    return hasBearing && hasDistance;
  },
  parse: (content): ParseResult => {
    const lines = content.trim().split('\n');
    const headers = lines[0].split(',').map((h: any) => h.trim().toLowerCase());
    const points: ParsedPoint[] = [];
    const warnings: string[] = [];

    for (let i = 1; i < lines.length; i++) {
      const values = lines[i].split(',').map((v: any) => v.trim());
      if (values.length < 2) continue;

      const raw: Record<string, unknown> = {};
      headers.forEach((h, idx) => { raw[h] = values[idx]; });

      const bearing = parseFloat(String(raw['bearing'] ?? raw['azimuth'] ?? raw['brg'] ?? raw['bear'] ?? ''));
      const distance = parseFloat(String(raw['distance'] ?? raw['dist'] ?? raw['hd'] ?? raw['length'] ?? ''));

      if (isNaN(bearing) || isNaN(distance) || distance <= 0) {
        warnings.push(`Row ${i + 1}: invalid or missing bearing/distance`);
        continue;
      }

      const normalizedBearing = (bearing + 360) % 360;
      const { deltaE, deltaN } = bearingDistanceToDelta(normalizedBearing, distance);

      points.push({
        point_no: String(raw['station'] ?? raw['stn'] ?? raw['from'] ?? raw['point'] ?? `P${i}`),
        bearing: normalizedBearing,
        distance: Number(distance.toFixed(3)),
        code: String(raw['code'] ?? raw['description'] ?? raw['desc'] ?? ''),
        remark: String(raw['remark'] ?? raw['notes'] ?? ''),
        raw,
        raw_data: { deltaE, deltaN }
      });
    }

    if (points.length < 3) {
      warnings.push('Fewer than 3 legs — closure check may not be meaningful');
    }

    return { format: 'csv', points, warnings };
  },
});

import { detectFormat, getParser } from './registry';
import { bowditchAdjustment } from '@/lib/engine/traverse';
import { ParseResult, SupportedFormat, ParsedPoint } from '@/types/importer';

export { detectFormat, getParser } from './registry';

interface FieldbookEntry {
  station: string;
  bearing: number;
  distance: number;
  deltaE?: number;
  deltaN?: number;
}

interface AdjustedLeg {
  from: string;
  to: string;
  adjEasting: number;
  adjNorthing: number;
  bearing: number;
  distance: number;
}

export interface SmartImportResult {
  success: boolean;
  entries: FieldbookEntry[];
  errors: string[];
  warnings: string[];
  totalEntries: number;
  parserUsed?: string;
  processed?: boolean;
  adjustedLegs?: AdjustedLeg[];
  relativePrecision?: string;
  message?: string;
}

export const smartImport = async (file: File): Promise<SmartImportResult> => {
  const content = await file.text();
  const format = detectFormat(file.name, content);

  if (format === 'unknown') {
    return {
      success: false,
      entries: [],
      errors: ['Unknown file format'],
      warnings: [],
      totalEntries: 0,
      parserUsed: 'unknown'
    };
  }

  const parser = getParser(format);
  if (!parser) {
    return {
      success: false,
      entries: [],
      errors: [`No parser for format: ${format}`],
      warnings: [],
      totalEntries: 0,
      parserUsed: format
    };
  }

  const parseResult = parser.parse(content);
  const points = parseResult.points || [];

  if (points.length < 3) {
    return {
      success: false,
      entries: [],
      errors: [...(parseResult.errors || []), 'Insufficient data - need at least 3 stations'],
      warnings: parseResult.warnings,
      totalEntries: points.length,
      parserUsed: format
    };
  }

  const entries: FieldbookEntry[] = points.map((p: ParsedPoint) => ({
    station: p.point_no || 'UNKNOWN',
    bearing: p.bearing || 0,
    distance: p.distance || 0,
    deltaE: (p.raw_data as Record<string, number>)?.deltaE || 0,
    deltaN: (p.raw_data as Record<string, number>)?.deltaN || 0,
  }));

  // Build engine-compatible traverse input
  const bowditchInput = {
    points: entries.map((e) => ({
      name: e.station,
      easting: 0,
      northing: 0,
    })),
    distances: entries.map((e) => e.distance),
    bearings: entries.map((e) => e.bearing),
  };

  const result = bowditchAdjustment(bowditchInput);

  const adjustedLegs: AdjustedLeg[] = result.legs.map((leg) => ({
    from: leg.from,
    to: leg.to,
    adjEasting: leg.adjEasting,
    adjNorthing: leg.adjNorthing,
    bearing: leg.bearing,
    distance: leg.distance,
  }));

  const precisionStr = result.linearError > 0 && result.totalDistance > 0
    ? `1:${Math.round(result.totalDistance / result.linearError).toLocaleString()}`
    : '1:Perfect';

  return {
    success: true,
    entries,
    errors: parseResult.errors || [],
    warnings: parseResult.warnings,
    totalEntries: entries.length,
    parserUsed: format,
    processed: true,
    adjustedLegs,
    relativePrecision: precisionStr,
    message: `Imported ${entries.length} legs. Bowditch applied (${precisionStr})`
  };
};

/**
 * @module gnssBleConnection
 *
 * Web Bluetooth API integration for GNSS rover connections.
 *
 * Connects to GNSS rovers (Emlid Reach, Topcon HiPer, Leica GS18, etc.)
 * via Bluetooth Low Energy (BLE). Streams RTCM3 correction messages
 * from an NTRIP caster to the rover, and receives NMEA position data
 * back for real-time display on the map.
 *
 * Protocol flow:
 *   1. User selects a BLE device (navigator.bluetooth.requestDevice)
 *   2. Connect to the GATT server
 *   3. Subscribe to NMEA position notifications (RX characteristic)
 *   4. Send RTCM3 corrections to the rover (TX characteristic)
 *   5. Parse NMEA sentences → position updates
 *
 * Browser support:
 *   - Chrome/Edge 56+ (full support)
 *   - Safari 16+ (partial)
 *   - Firefox: NOT supported (use Capacitor mobile app)
 *   - On Android (Capacitor): uses @capacitor-community/bluetooth-le
 */

export interface GNSSPosition {
  latitude: number
  longitude: number
  elevation: number
  /** Horizontal accuracy in metres (CEP) */
  accuracy: number
  /** Fix quality: 0=invalid, 1=GPS fix, 2=DGPS, 4=RTK fixed, 5=RTK float */
  fixQuality: number
  /** Fix quality as human-readable string */
  fixLabel: string
  /** Number of satellites used */
  satellites: number
  /** HDOP (horizontal dilution of precision) */
  hdop: number
  /** Timestamp of the position */
  timestamp: string
}

export interface GNSSConnectionState {
  connected: boolean
  deviceName?: string
  receivingData: boolean
  positionsReceived: number
  lastPosition?: GNSSPosition
  correctionsSent: number
}

// BLE UUIDs for common GNSS receivers
// These are the standard NMEA-over-BLE service/characteristic UUIDs
const BLE_SERVICE_NMEA = '0000ffe0-0000-1000-8000-00805f9b34fb' // common HM-10 UART service
const BLE_CHAR_NMEA_RX = '0000ffe1-0000-1000-8000-00805f9b34fb' // receive NMEA
const BLE_CHAR_NMEA_TX = '0000ffe2-0000-1000-8000-00805f9b34fb' // send RTCM3

// Emlid Reach specific UUIDs
const EMLID_SERVICE = '0000ee01-0000-1000-8000-00805f9b34fb'
const EMLID_CHAR_POSITION = '0000ee02-0000-1000-8000-00805f9b34fb'
const EMLID_CHAR_CORRECTIONS = '0000ee03-0000-1000-8000-00805f9b34fb'

export class GNSSBleConnection {
  private device: any = null
  private server: any = null
  private rxCharacteristic: any = null
  private txCharacteristic: any = null
  private connected = false
  private state: GNSSConnectionState = {
    connected: false,
    receivingData: false,
    positionsReceived: 0,
    correctionsSent: 0,
  }
  private nmeaBuffer = ''
  private onPosition?: (pos: GNSSPosition) => void
  private onStateChange?: (state: GNSSConnectionState) => void
  private decoder = new TextDecoder()

  constructor(
    onPosition?: (pos: GNSSPosition) => void,
    onStateChange?: (state: GNSSConnectionState) => void,
  ) {
    this.onPosition = onPosition
    this.onStateChange = onStateChange
  }

  static isSupported(): boolean {
    return typeof navigator !== 'undefined' && 'bluetooth' in navigator
  }

  /**
   * Request a BLE device and connect.
   * Must be called from a user gesture (button click).
   */
  async connect(): Promise<void> {
    if (!GNSSBleConnection.isSupported()) {
      throw new Error(
        'Web Bluetooth API is not supported. Use Chrome/Edge 56+ or the METARDU mobile app.'
      )
    }

    // @ts-ignore
    this.device = await navigator.bluetooth.requestDevice({
      filters: [
        { services: [BLE_SERVICE_NMEA] },
        { services: [EMLID_SERVICE] },
        { namePrefix: 'Reach' },     // Emlid Reach
        { namePrefix: 'HiPer' },     // Topcon HiPer
        { namePrefix: 'GS' },        // Leica GS18/GS16
        { namePrefix: 'STONEX' },    // Stonex
        { namePrefix: 'CHC' },       // CHCNAV
      ],
      optionalServices: [BLE_SERVICE_NMEA, EMLID_SERVICE, 'generic_access'],
    })

    this.device.addEventListener('gattserverdisconnected', () => {
      this.connected = false
      this.state.connected = false
      this.state.receivingData = false
      this.notifyStateChange()
    })

    this.server = await this.device.gatt.connect()

    // Try standard NMEA service first, then Emlid
    let service
    try {
      service = await this.server.getPrimaryService(BLE_SERVICE_NMEA)
      this.rxCharacteristic = await service.getCharacteristic(BLE_CHAR_NMEA_RX)
      this.txCharacteristic = await service.getCharacteristic(BLE_CHAR_NMEA_TX)
    } catch {
      service = await this.server.getPrimaryService(EMLID_SERVICE)
      this.rxCharacteristic = await service.getCharacteristic(EMLID_CHAR_POSITION)
      this.txCharacteristic = await service.getCharacteristic(EMLID_CHAR_CORRECTIONS)
    }

    // Subscribe to NMEA notifications
    await this.rxCharacteristic.startNotifications()
    this.rxCharacteristic.addEventListener('characteristicvaluechanged', (event: any) => {
      this.handleNmeaData(event.target.value)
    })

    this.connected = true
    this.state.connected = true
    this.state.deviceName = this.device.name || 'Unknown GNSS'
    this.notifyStateChange()
  }

  async disconnect(): Promise<void> {
    if (this.device && this.device.gatt.connected) {
      try { await this.rxCharacteristic?.stopNotifications() } catch {}
      this.device.gatt.disconnect()
    }
    this.connected = false
    this.state.connected = false
    this.state.receivingData = false
    this.notifyStateChange()
  }

  /**
   * Send RTCM3 correction data to the rover.
   * Called repeatedly by the NTRIP client (which receives corrections
   * from the caster and forwards them to the rover via BLE).
   *
   * @param rtcmData Raw RTCM3 bytes (from NTRIP caster)
   */
  async sendCorrections(rtcmData: Uint8Array): Promise<void> {
    if (!this.connected || !this.txCharacteristic) return

    // BLE has a max MTU of ~512 bytes. RTCM3 messages are typically
    // 100-500 bytes, but some (like MSM7) can be larger.
    // Split into chunks if needed.
    const MAX_CHUNK = 180 // safe BLE chunk size

    for (let offset = 0; offset < rtcmData.length; offset += MAX_CHUNK) {
      const chunk = rtcmData.slice(offset, offset + MAX_CHUNK)
      await this.txCharacteristic.writeValueWithoutResponse(chunk)
    }

    this.state.correctionsSent++
    // Throttle state updates (don't call on every correction)
    if (this.state.correctionsSent % 10 === 0) {
      this.notifyStateChange()
    }
  }

  isConnected(): boolean { return this.connected }
  getState(): GNSSConnectionState { return { ...this.state } }

  // ─── Private: handle incoming NMEA data ───

  private handleNmeaData(dataView: DataView) {
    const text = this.decoder.decode(dataView)
    this.nmeaBuffer += text

    // NMEA sentences end with \r\n
    const lines = this.nmeaBuffer.split(/\r\n|\n/)
    this.nmeaBuffer = lines.pop() || ''

    for (const line of lines) {
      if (line.startsWith('$')) {
        const pos = parseNMEAPosition(line)
        if (pos) {
          this.state.positionsReceived++
          this.state.receivingData = true
          this.state.lastPosition = pos
          this.onPosition?.(pos)
          if (this.state.positionsReceived % 5 === 0) {
            this.notifyStateChange()
          }
        }
      }
    }
  }

  private notifyStateChange() {
    this.onStateChange?.({ ...this.state })
  }
}

// ─── NMEA Parser ────────────────────────────────────────────────────────────

/**
 * Parse an NMEA sentence into a GNSS position.
 * Supports: GGA, RMC, GNS sentences.
 */
export function parseNMEAPosition(sentence: string): GNSSPosition | null {
  if (!sentence.startsWith('$')) return null

  const parts = sentence.substring(1).split('*')[0].split(',')

  if (parts[0] === 'GPGGA' || parts[0] === 'GNGGA') {
    return parseGGA(parts)
  }

  return null
}

function parseGGA(parts: string[]): GNSSPosition | null {
  try {
    // $GPGGA,hhmmss.ss,llll.ll,a,yyyyy.yy,a,x,xx,x.x,x.x,M,x.x,M,x.x,xxxx*hh
    // parts[1] = UTC time
    // parts[2,3] = latitude + N/S
    // parts[4,5] = longitude + E/W
    // parts[6] = fix quality
    // parts[7] = satellites
    // parts[8] = HDOP
    // parts[9,10] = elevation + unit
    // parts[11,12] = geoid separation + unit

    if (parts.length < 10) return null

    const lat = parseNMEACoordinate(parts[2], parts[3])
    const lon = parseNMEACoordinate(parts[4], parts[5])
    if (lat == null || lon == null) return null

    const fixQuality = parseInt(parts[6], 10) || 0
    const satellites = parseInt(parts[7], 10) || 0
    const hdop = parseFloat(parts[8]) || 0
    const elevation = parseFloat(parts[9]) || 0

    // Accuracy estimate from HDOP
    // Typical GPS: ~3m * HDOP
    const accuracy = hdop * 3.0

    const fixLabels: Record<number, string> = {
      0: 'No Fix',
      1: 'GPS',
      2: 'DGPS',
      3: 'PPS',
      4: 'RTK Fixed',
      5: 'RTK Float',
      6: 'Dead Reckoning',
      7: 'Manual',
      8: 'Simulation',
    }

    return {
      latitude: lat,
      longitude: lon,
      elevation,
      accuracy,
      fixQuality,
      fixLabel: fixLabels[fixQuality] || 'Unknown',
      satellites,
      hdop,
      timestamp: new Date().toISOString(),
    }
  } catch {
    return null
  }
}

/**
 * Parse NMEA coordinate format (ddmm.mmmm + hemisphere).
 * Returns decimal degrees.
 */
function parseNMEACoordinate(value: string, hemi: string): number | null {
  if (!value || !hemi) return null

  const num = parseFloat(value)
  if (isNaN(num)) return null

  // Latitude: ddmm.mmmm (2 digits degrees)
  // Longitude: dddmm.mmmm (3 digits degrees)
  const isLat = hemi === 'N' || hemi === 'S'
  const degDigits = isLat ? 2 : 3

  const deg = Math.floor(num / Math.pow(10, degDigits))
  const min = num - deg * Math.pow(10, degDigits)
  const decimal = deg + min / 60

  return hemi === 'S' || hemi === 'W' ? -decimal : decimal
}

/**
 * @module totalStationSerial
 *
 * Web Serial API integration for total station instruments.
 *
 * Connects directly to total stations via USB or Bluetooth (using
 * Web Serial API on Chrome/Edge). Eliminates the need for manufacturer
 * software — surveyors can stream observations directly into METARDU.
 *
 * Supported instruments (via their serial protocols):
 *   - Topcon: GSI format (raw data) + RC-100 commands
 *   - Leica: GSI-8 / GSI-16 format
 *   - Sokkia: SDR format
 *   - Trimble: RAW format
 *   - Pentax: PENTAX RAW format
 *   - South: NMEA-0183 compatible
 *
 * Browser support:
 *   - Chrome/Edge 89+ (full support)
 *   - Safari/Firefox: NOT supported (use the Capacitor mobile app
 *     which has a polyfill via @capacitor-community/serial)
 */

export type InstrumentBrand = 'topcon' | 'leica' | 'sokkia' | 'trimble' | 'pentax' | 'south' | 'generic'

export interface InstrumentConfig {
  brand: InstrumentBrand
  model?: string
  baudRate: number
  dataBits: 7 | 8
  stopBits: 1 | 2
  parity: 'none' | 'even' | 'odd'
  measureCommand: string
  autoSend: boolean
}

export interface RawObservation {
  raw: string
  parsed: ParsedObservation | null
  timestamp: string
}

export interface ParsedObservation {
  pointId?: string
  horizontalAngle?: number
  verticalAngle?: number
  slopeDistance?: number
  horizontalDistance?: number
  easting?: number
  northing?: number
  elevation?: number
  instrumentHeight?: number
  targetHeight?: number
  temperature?: number
  pressure?: number
}

export const INSTRUMENT_PRESETS: Record<InstrumentBrand, InstrumentConfig> = {
  topcon: { brand: 'topcon', baudRate: 9600, dataBits: 8, stopBits: 1, parity: 'none', measureCommand: '061', autoSend: false },
  leica: { brand: 'leica', baudRate: 9600, dataBits: 7, stopBits: 1, parity: 'even', measureCommand: 'GET/M/WI81/22', autoSend: false },
  sokkia: { brand: 'sokkia', baudRate: 9600, dataBits: 8, stopBits: 1, parity: 'none', measureCommand: 'M', autoSend: false },
  trimble: { brand: 'trimble', baudRate: 9600, dataBits: 8, stopBits: 1, parity: 'none', measureCommand: 'ST', autoSend: false },
  pentax: { brand: 'pentax', baudRate: 9600, dataBits: 8, stopBits: 1, parity: 'none', measureCommand: 'M', autoSend: false },
  south: { brand: 'south', baudRate: 9600, dataBits: 8, stopBits: 1, parity: 'none', measureCommand: 'M', autoSend: false },
  generic: { brand: 'generic', baudRate: 9600, dataBits: 8, stopBits: 1, parity: 'none', measureCommand: '', autoSend: false },
}

export class TotalStationConnection {
  private port: any = null
  private reader: any = null
  private writer: any = null
  private config: InstrumentConfig
  private connected = false
  private decoder: TextDecoder
  private buffer: string = ''
  private onObservation?: (obs: RawObservation) => void

  constructor(config: InstrumentConfig, onObservation?: (obs: RawObservation) => void) {
    this.config = config
    this.onObservation = onObservation
    this.decoder = new TextDecoder()
  }

  static isSupported(): boolean {
    return typeof navigator !== 'undefined' && 'serial' in navigator
  }

  async connect(): Promise<void> {
    if (!TotalStationConnection.isSupported()) {
      throw new Error('Web Serial API is not supported. Use Chrome/Edge 89+ or the METARDU mobile app.')
    }
    // @ts-ignore
    this.port = await navigator.serial.requestPort()
    await this.port.open({
      baudRate: this.config.baudRate,
      dataBits: this.config.dataBits,
      stopBits: this.config.stopBits,
      parity: this.config.parity,
    })
    this.reader = this.port.readable.getReader()
    this.writer = this.port.writable.getWriter()
    this.connected = true
    this.readLoop()
  }

  async disconnect(): Promise<void> {
    this.connected = false
    if (this.reader) { try { await this.reader.cancel() } catch {} try { this.reader.releaseLock() } catch {} this.reader = null }
    if (this.writer) { try { this.writer.releaseLock() } catch {} this.writer = null }
    if (this.port) { try { await this.port.close() } catch {} this.port = null }
  }

  async measure(): Promise<void> {
    if (!this.connected || !this.writer) throw new Error('Not connected to instrument')
    const cmd = this.config.measureCommand
    if (!cmd) return
    const data = new TextEncoder().encode(cmd + '\r\n')
    await this.writer.write(data)
  }

  isConnected(): boolean { return this.connected }
  getConfig(): InstrumentConfig { return this.config }

  private async readLoop() {
    if (!this.reader) return
    try {
      while (this.connected) {
        const { value, done } = await this.reader.read()
        if (done) break
        this.buffer += this.decoder.decode(value, { stream: true })
        const lines = this.buffer.split(/\r\n|\n|\r/)
        this.buffer = lines.pop() || ''
        for (const line of lines) {
          if (line.trim().length === 0) continue
          const parsed = parseInstrumentData(line, this.config.brand)
          this.onObservation?.({ raw: line, parsed, timestamp: new Date().toISOString() })
        }
      }
    } catch (err) {
      if (this.connected) console.error('[TotalStation] Read error:', err)
    }
  }
}

export function parseInstrumentData(raw: string, brand: InstrumentBrand): ParsedObservation | null {
  switch (brand) {
    case 'topcon':
    case 'leica':
      return parseGSI(raw)
    case 'sokkia':
      return parseSDR(raw)
    case 'trimble':
      return parseTrimbleRAW(raw)
    default:
      return parseGeneric(raw)
  }
}

function parseGSI(raw: string): ParsedObservation | null {
  try {
    const result: ParsedObservation = {}
    const words = raw.trim().split(/\s+/)
    for (const word of words) {
      if (word.length < 7) continue
      const wi = word.substring(0, 2)
      const sign = word.charAt(5) === '-' ? -1 : 1
      const val = sign * parseFloat(word.substring(6))
      if (isNaN(val)) continue
      switch (wi) {
        case '21': result.horizontalAngle = val / 100000 * 0.00001 * 180 / Math.PI; break
        case '22': result.verticalAngle = val / 100000 * 0.00001 * 180 / Math.PI; break
        case '31': result.slopeDistance = val / 10000; break
        case '32': result.horizontalDistance = val / 10000; break
        case '81': result.easting = val / 1000; break
        case '82': result.northing = val / 1000; break
        case '83': result.elevation = val / 1000; break
        case '87': result.targetHeight = val / 100000; break
        case '88': result.instrumentHeight = val / 100000; break
      }
    }
    if (result.horizontalAngle == null && result.slopeDistance == null && result.easting == null) return null
    return result
  } catch { return null }
}

function parseSDR(raw: string): ParsedObservation | null {
  try {
    const parts = raw.trim().split(',')
    if (parts.length < 2) return null
    const rt = parts[0].substring(0, 2)
    if (rt === '09' && parts.length >= 7) {
      return { pointId: parts[1]?.trim(), horizontalAngle: parseFloat(parts[2]) || undefined, verticalAngle: parseFloat(parts[3]) || undefined, slopeDistance: parseFloat(parts[4]) || undefined, targetHeight: parseFloat(parts[5]) || undefined, instrumentHeight: parseFloat(parts[6]) || undefined }
    }
    if (rt === '08' && parts.length >= 5) {
      return { pointId: parts[1]?.trim(), easting: parseFloat(parts[2]) || undefined, northing: parseFloat(parts[3]) || undefined, elevation: parseFloat(parts[4]) || undefined }
    }
    return null
  } catch { return null }
}

function parseTrimbleRAW(raw: string): ParsedObservation | null {
  try {
    const parts = raw.trim().split(',')
    if (parts.length < 4) return null
    const result: ParsedObservation = { pointId: parts[0]?.trim() || undefined, horizontalAngle: parseFloat(parts[1]) || undefined, verticalAngle: parseFloat(parts[2]) || undefined, slopeDistance: parseFloat(parts[3]) || undefined }
    if (parts.length > 4) result.targetHeight = parseFloat(parts[4]) || undefined
    if (parts.length > 5) result.instrumentHeight = parseFloat(parts[5]) || undefined
    return result
  } catch { return null }
}

function parseGeneric(raw: string): ParsedObservation | null {
  try {
    const parts = raw.trim().split(/[,;\t]/)
    const numbers = parts.map(p => parseFloat(p)).filter(n => !isNaN(n))
    if (numbers.length >= 3) {
      return { horizontalAngle: numbers[0], verticalAngle: numbers[1], slopeDistance: numbers[2], targetHeight: numbers[3] || undefined }
    }
    return null
  } catch { return null }
}

