}

/**
 * Digital Signature & QR Verification Service
 * Uses Web Crypto API (SubtleCrypto) — zero bundle cost, works in browsers natively
 */

const ALGORITHM = { name: 'HMAC', hash: 'SHA-256' }
const enc = new TextEncoder()
const dec = new TextDecoder()

export interface SignedDocument {
  documentId: string
  documentHash: string
  signature: string
  timestamp: number
  signerId: string
  metadata: Record<string, string>
}

export interface QRVerificationResult {
  valid: boolean
  document?: SignedDocument
  message: string
  verifiedAt: number
}

export interface SignatureRecord {
  signerId: string
  signerName: string
  licenseNumber: string
  timestamp: number
  documentId: string
  signature: string
  documentHash: string
}

async function deriveKey(secret: string): Promise<CryptoKey> {
  const keyMaterial = await crypto.subtle.importKey('raw', enc.encode(secret), 'PBKDF2', false, ['deriveKey'])
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt: enc.encode('metardu-salt'), iterations: 100000, hash: 'SHA-256' },
    keyMaterial,
    ALGORITHM,
    false,
    ['sign', 'verify']
  )
}

async function hashContent(content: string): Promise<string> {
  const buf = await crypto.subtle.digest('SHA-256', enc.encode(content))
  return Array.from(new Uint8Array(buf)).map((b: any) => b.toString(16).padStart(2, '0')).join('')
}

async function hmacSign(key: CryptoKey, data: string): Promise<string> {
  const buf = await crypto.subtle.sign('HMAC', key, enc.encode(data))
  return Array.from(new Uint8Array(buf)).map((b: any) => b.toString(16).padStart(2, '0')).join('')
}

export async function signDocument(
  documentId: string,
  content: string,
  signerId: string,
  secret: string,
  metadata: Record<string, string> = {}
): Promise<SignedDocument> {
  const documentHash = await hashContent(content)
  const key = await deriveKey(secret)
  const signature = await hmacSign(key, documentHash)
  return { documentId, documentHash, signature, timestamp: Date.now(), signerId, metadata }
}

export async function verifySignature(
  signedDoc: SignedDocument,
  originalContent: string,
  secret: string
): Promise<QRVerificationResult> {
  const computedHash = await hashContent(originalContent)
  if (computedHash !== signedDoc.documentHash) {
    return { valid: false, message: 'Document content has been modified', verifiedAt: Date.now() }
  }
  const key = await deriveKey(secret)
  const expectedSig = await hmacSign(key, signedDoc.documentHash)
  if (expectedSig !== signedDoc.signature) {
    return { valid: false, message: 'Invalid signature', verifiedAt: Date.now() }
  }
  return { valid: true, document: signedDoc, message: 'Document signature verified successfully', verifiedAt: Date.now() }
}

export function generateQRPayload(signedDoc: SignedDocument): string {
  const payload = { id: signedDoc.documentId, h: signedDoc.documentHash, s: signedDoc.signature, t: signedDoc.timestamp, si: signedDoc.signerId }
  return btoa(JSON.stringify(payload))
}

export function parseQRPayload(payload: string): SignedDocument | null {
  try {
    const decoded = JSON.parse(atob(payload))
    return { documentId: decoded.id, documentHash: decoded.h, signature: decoded.s, timestamp: decoded.t, signerId: decoded.si, metadata: {} }
  } catch { return null }
}

export async function createSurveyReportSignature(
  surveyId: string,
  surveyorLicense: string,
  measurements: Record<string, number>,
  secret: string
): Promise<SignedDocument> {
  const content = JSON.stringify({ surveyId, surveyorLicense, measurements }, Object.keys(measurements).sort())
  return signDocument(surveyId, content, surveyorLicense, secret, { type: 'survey_report' })
}

export function buildVerificationBlock(sig: SignatureRecord): string {
  const date = new Date(sig.timestamp).toLocaleDateString('en-GB', {
    day: '2-digit', month: 'short', year: 'numeric'
  })
  const w = 55  // mm
  const h = 12  // mm
  const px = 3.7795275591
  return (
    `<rect x="0" y="0" width="${w * px}" height="${h * px}" fill="#f8f9fa" stroke="#dee2e6" stroke-width="0.3"/>` +
    `<text x="${2 * px}" y="${4 * px}" font-family="Arial,sans-serif" font-size="2.5" fill="#212529">Signed: ${sig.signerName}</text>` +
    `<text x="${2 * px}" y="${7 * px}" font-family="Arial,sans-serif" font-size="2" fill="#6c757d">Lic: ${sig.licenseNumber} | ${date}</text>` +
    `<text x="${2 * px}" y="${10 * px}" font-family="Courier New,monospace" font-size="1.8" fill="#495057">ID: ${sig.documentId.slice(0,12)}...</text>`
  )
}

/**
 * Equipment Calibration Tracker
 * User-owned data — persisted in localStorage, keyed by user session.
 * No mock data. Users register their own instruments.
 */

export type EquipmentType = 'total_station' | 'gnss' | 'level' | 'theodolite' | 'edm' | 'prism_pole' | 'accessory'

export interface Equipment {
  id: string
  name: string
  type: EquipmentType
  brand: string
  model: string
  serialNumber: string
  purchaseDate: string         // ISO date string YYYY-MM-DD
  lastCalibrationDate: string  // ISO date string — user sets this on registration or after calibration
  intervalDays: number         // calibration interval in days (e.g. 365 = annual, 180 = 6-monthly)
  location: string
  notes: string
  createdAt: string
}

export interface CalibrationLog {
  id: string
  equipmentId: string
  date: string          // ISO date string
  result: 'passed' | 'failed' | 'adjusted'
  technician: string
  certificate: string
  notes: string
}

export type CalibrationStatus = 'ok' | 'due_soon' | 'overdue'

export interface EquipmentWithStatus extends Equipment {
  nextCalibrationDate: string
  daysUntilDue: number       // negative = overdue
  status: CalibrationStatus
  percentUsed: number        // 0–100, how far through the interval
}

const STORAGE_KEY = 'metardu_equipment'
const LOG_KEY = 'metardu_calibration_logs'

// ── Storage helpers ──────────────────────────────────────────────────────────

function load(): Equipment[] {
  if (typeof window === 'undefined') return []
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]')
  } catch { return [] }
}

function save(items: Equipment[]): void {
  if (typeof window === 'undefined') return
  localStorage.setItem(STORAGE_KEY, JSON.stringify(items))
}

function loadLogs(): CalibrationLog[] {
  if (typeof window === 'undefined') return []
  try {
    return JSON.parse(localStorage.getItem(LOG_KEY) || '[]')
  } catch { return [] }
}

function saveLogs(logs: CalibrationLog[]): void {
  if (typeof window === 'undefined') return
  localStorage.setItem(LOG_KEY, JSON.stringify(logs))
}

// ── Status calculation ───────────────────────────────────────────────────────

export function calcStatus(eq: Equipment): EquipmentWithStatus {
  const lastCal = new Date(eq.lastCalibrationDate)
  const nextCal = new Date(lastCal.getTime() + eq.intervalDays * 86_400_000)
  const today = new Date()
  today.setHours(0, 0, 0, 0)
  const daysUntilDue = Math.ceil((nextCal.getTime() - today.getTime()) / 86_400_000)

  let status: CalibrationStatus = 'ok'
  if (daysUntilDue < 0) status = 'overdue'
  else if (daysUntilDue <= 30) status = 'due_soon'

  const elapsed = today.getTime() - lastCal.getTime()
  const total = nextCal.getTime() - lastCal.getTime()
  const percentUsed = Math.min(100, Math.max(0, Math.round((elapsed / total) * 100)))

  return {
    ...eq,
    nextCalibrationDate: nextCal.toISOString().split('T')[0],
    daysUntilDue,
    status,
    percentUsed,
  }
}

// ── CRUD ─────────────────────────────────────────────────────────────────────

export function getAll(): EquipmentWithStatus[] {
  return load().map(calcStatus).sort((a: any, b: any) => a.daysUntilDue - b.daysUntilDue)
}

export function addEquipment(data: Omit<Equipment, 'id' | 'createdAt'>): Equipment {
  const items = load()
  const item: Equipment = { ...data, id: `EQ_${Date.now()}`, createdAt: new Date().toISOString() }
  save([...items, item])
  return item
}

export function updateEquipment(id: string, updates: Partial<Omit<Equipment, 'id' | 'createdAt'>>): boolean {
  const items = load()
  const idx = items.findIndex(e => e.id === id)
  if (idx === -1) return false
  items[idx] = { ...items[idx], ...updates }
  save(items)
  return true
}

export function deleteEquipment(id: string): void {
  save(load().filter((e: any) => e.id !== id))
  saveLogs(loadLogs().filter((l: any) => l.equipmentId !== id))
}

export function logCalibration(data: Omit<CalibrationLog, 'id'>): CalibrationLog {
  const log: CalibrationLog = { ...data, id: `LOG_${Date.now()}` }
  saveLogs([...loadLogs(), log])
  // Update the equipment's lastCalibrationDate
  updateEquipment(data.equipmentId, { lastCalibrationDate: data.date })
  return log
}

export function getLogsFor(equipmentId: string): CalibrationLog[] {
  return loadLogs().filter((l: any) => l.equipmentId === equipmentId).sort((a: any, b: any) => b.date.localeCompare(a.date))
}

