/**
 * METARDU Basemap Layer Factory
 *
 * Provides async factory functions for creating basemap tile layers.
 * All OL imports are dynamic to match existing project patterns.
 *
 * Basemaps:
 * - OSM: OpenStreetMap standard tiles
 * - Satellite: ESRI World Imagery
 * - Blank: Solid white background (no tiles)
 * - Custom XYZ: User-provided tile URL
 */

/**
 * Create an OpenStreetMap basemap layer.
 */
export async function createOSMLayer() {
  const { default: TileLayer } = await import('ol/layer/Tile');
  const { default: OSM } = await import('ol/source/OSM');
  const layer = new TileLayer({
    source: new OSM(),
    zIndex: 0,
  });
  layer.set('basemapId', 'osm');
  return layer;
}

/**
 * Create a satellite basemap layer using ESRI World Imagery XYZ tiles.
 */
export async function createSatelliteLayer() {
  const { default: TileLayer } = await import('ol/layer/Tile');
  const { default: XYZ } = await import('ol/source/XYZ');
  const layer = new TileLayer({
    source: new XYZ({
      url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
      attributions: 'Tiles (c) Esri',
      crossOrigin: 'anonymous',
      maxZoom: 19,
    }),
    zIndex: 0,
    visible: false,
  });
  layer.set('basemapId', 'satellite');
  return layer;
}

/**
 * Create a blank (white) basemap layer.
 * Uses a TileLayer with no visible source to keep the map functional.
 */
export async function createBlankLayer() {
  const { default: TileLayer } = await import('ol/layer/Tile');
  const layer = new TileLayer({
    source: null as any,
    zIndex: 0,
    visible: false,
  });
  layer.set('basemapId', 'blank');
  return layer;
}

/**
 * Create a custom XYZ tile layer from a user-provided URL template.
 * The URL should use {z}, {x}, {y} placeholders.
 *
 * @param url - XYZ tile URL template
 * @param label - Optional display name for the layer
 */
export async function createCustomXYZLayer(url: string, label?: string) {
  const { default: TileLayer } = await import('ol/layer/Tile');
  const { default: XYZ } = await import('ol/source/XYZ');

  // Sanitize URL — require {z}, {x}, {y} placeholders
  const hasPlaceholders = /\{z\}/.test(url) && /\{x\}/.test(url) && /\{y\}/.test(url);
  if (!hasPlaceholders) {
    throw new Error('XYZ URL must contain {z}, {x}, and {y} placeholders');
  }

  const layer = new TileLayer({
    source: new XYZ({
      url,
      crossOrigin: 'anonymous',
      maxZoom: 22,
    }),
    zIndex: 1,
    visible: true,
  });
  layer.set('basemapId', `custom-${label ?? Date.now()}`);
  layer.set('layerLabel', label ?? 'Custom Layer');
  layer.set('layerUrl', url);
  return layer;
}

/**
 * Create a WMS (Web Map Service) layer for GeoServer, MapServer, etc.
 * Users can paste a WMS URL and the layer will be overlaid on the map.
 *
 * @param url - WMS service URL (e.g. "https://geoserver.example.com/geoserver/wms")
 * @param layerName - WMS layer name (e.g. "workspace:parcels")
 * @param label - Display name for the layer
 * @param params - Additional WMS parameters (optional)
 */
export async function createWMSLayer(
  url: string,
  layerName: string,
  label?: string,
  params?: Record<string, string>
) {
  const { default: TileLayer } = await import('ol/layer/Tile');
  const { default: TileWMS } = await import('ol/source/TileWMS');

  const wmsParams: Record<string, string> = {
    LAYERS: layerName,
    TILED: 'true',
    ...params,
  };

  const layer = new TileLayer({
    source: new TileWMS({
      url,
      params: wmsParams,
      crossOrigin: 'anonymous',
      serverType: 'geoserver',
    }),
    zIndex: 2,
    visible: true,
  });
  layer.set('basemapId', `wms-${label ?? Date.now()}`);
  layer.set('layerLabel', label ?? layerName);
  layer.set('layerUrl', url);
  layer.set('layerType', 'wms');
  layer.set('wmsLayerName', layerName);
  return layer;
}

/**
 * Type for a basemap layer returned by the factory functions.
 */
export type BasemapLayer = Awaited<ReturnType<typeof createOSMLayer>> | Awaited<ReturnType<typeof createSatelliteLayer>> | Awaited<ReturnType<typeof createBlankLayer>>;

/**
 * @module cadastralEditing
 * @description Cadastral parcel editing interactions for the Metardu surveying platform.
 *
 * Provides the core snap → modify → draw interaction chain used by surveyors for
 * boundary digitization and parcel subdivision on OpenLayers maps.
 *
 * Public API:
 *   - {@link createEditingInteractionStack} — full editing interaction stack
 *   - {@link createSubdivisionInteraction} — parcel split-line interaction
 *   - {@link createMeasureWhileDraw}     — real-time distance / bearing annotations
 *   - {@link createHistoryManager}       — standalone undo / redo manager
 *
 * OpenLayers classes are imported as values (for `new`) and types (for annotations)
 * from `ol/*` — the library ships its own `.d.ts` files. Next.js code-splits these
 * automatically. The async function signatures are retained for backward
 * compatibility with callers that `await` the factories.
 */

// ---------------------------------------------------------------------------
// Typed imports — values (for `new`) and types (for annotations)
// ---------------------------------------------------------------------------

import Map from 'ol/Map'
import Feature from 'ol/Feature'
import Polygon from 'ol/geom/Polygon'
import Point from 'ol/geom/Point'
import VectorSource from 'ol/source/Vector'
import VectorLayer from 'ol/layer/Vector'
import Snap from 'ol/interaction/Snap'
import Modify from 'ol/interaction/Modify'
import Draw from 'ol/interaction/Draw'
import Select from 'ol/interaction/Select'
import Style from 'ol/style/Style'
import Fill from 'ol/style/Fill'
import Stroke from 'ol/style/Stroke'
import Text from 'ol/style/Text'
import { transform } from 'ol/proj'
import { unByKey } from 'ol/Observable'
import proj4 from 'proj4'

import type Geometry from 'ol/geom/Geometry'
import type SimpleGeometry from 'ol/geom/SimpleGeometry'
import type LineString from 'ol/geom/LineString'
import type { FeatureLike } from 'ol/Feature'
import type { EventsKey } from 'ol/events'
import type { ModifyEvent } from 'ol/interaction/Modify'
import type { DrawEvent } from 'ol/interaction/Draw'
import type { GeometryFunction as DrawGeometryFunction } from 'ol/interaction/Draw'
import type { Options as SnapOptions } from 'ol/interaction/Snap'

// ---------------------------------------------------------------------------
// Exported interfaces
// ---------------------------------------------------------------------------

/**
 * Minimal source contract used by {@link HistoryManager} — a structural subset
 * of `ol/source/Vector` so that mocks (without every VectorSource method) can
 * satisfy the type in tests.
 */
export interface HistorySource {
  getFeatureById(id: string | number): Feature | null;
  getFeatures(): Feature[];
  addFeature(feature: Feature): void;
  removeFeature(feature: Feature): void;
}

/** Options for {@link createEditingInteractionStack}. */
export interface EditingOptions {
  /** OL VectorSource containing features to edit. */
  source: VectorSource<Feature>;
  /** Additional OL VectorSource to snap to (e.g. existing parcel boundaries). */
  snapSource?: VectorSource<Feature>;
  /** Snap tolerance in pixels (default: 10). */
  snapTolerance?: number;
  /** Constrain new edges to right angles relative to the previous edge (default: true). */
  orthogonalConstraint?: boolean;
  /** Callback fired when a new feature is added to the source. */
  onFeatureAdded?: (feature: Feature) => void;
  /** Callback fired when an existing feature geometry is modified. */
  onFeatureModified?: (feature: Feature) => void;
  /** Callback fired when a feature is deleted (receives the feature id). */
  onFeatureDeleted?: (featureId: string) => void;
}

/** The full editing interaction stack returned by {@link createEditingInteractionStack}. */
export interface InteractionStack {
  /** OL Snap interaction. */
  snap: Snap;
  /** OL Modify interaction. */
  modify: Modify;
  /** OL Draw interaction. */
  draw: Draw;
  /** History manager for undo / redo of all editing operations. */
  history: HistoryManager;
  /** Removes all keyboard listeners and clears history. Does NOT remove interactions from the map. */
  removeAll: () => void;
}

/** Options for {@link createSubdivisionInteraction}. */
export interface SubdivisionOptions {
  /** OL VectorSource containing parcel features. */
  source: VectorSource<Feature>;
  /** The OL Feature (polygon) to subdivide. */
  targetFeature: Feature;
  /** Snap tolerance in pixels (default: 10). */
  snapTolerance?: number;
  /** EPSG code of the source geometry coordinates (default: 'EPSG:3857'). */
  sourceProjection?: string;
  /** Callback with the two resulting polygon features after subdivision. */
  onComplete: (polygonA: Feature, polygonB: Feature) => void;
  /** Callback if subdivision fails (e.g. split line does not cross the parcel). */
  onError?: (error: Error) => void;
}

/** Options for {@link createMeasureWhileDraw}. */
export interface MeasureWhileDrawOptions {
  /** OL Map instance. */
  map: Map;
  /** The OL Draw interaction to monitor. */
  drawInteraction: Draw;
  /** Projection of the source geometry (default: 'EPSG:3857'). */
  projection?: string;
  /** Whether to show per-edge bearing labels (default: true). */
  showBearing?: boolean;
  /** Whether to show cumulative distance (default: true). */
  showCumulativeDistance?: boolean;
  /** Whether to show per-edge distance (default: true). */
  showEdgeDistance?: boolean;
}

/** Handle returned by {@link createMeasureWhileDraw} for cleanup. */
export interface MeasureHandle {
  /** Remove all measurement features, event listeners, and the annotation layer from the map. */
  cleanup: () => void;
  /** The temporary OL VectorLayer containing measurement annotation features. */
  layer: VectorLayer;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum number of operations retained in the undo / redo history stacks. */
const MAX_HISTORY_DEPTH = 50;

/** Feature id prefix for auto-generated ids. */
const FEAT_ID_PREFIX = 'ce_';

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

let _idCounter = 0;

/** Generate a unique feature id. */
function generateFeatureId(): string {
  _idCounter++;
  return `${FEAT_ID_PREFIX}${Date.now()}_${_idCounter}`;
}

/**
 * Calculate planar distance between two coordinates (for projected CRS).
 * @param c1 - First coordinate [x, y].
 * @param c2 - Second coordinate [x, y].
 * @returns Distance in map units (metres for EPSG:21037 / EPSG:3857).
 */
function planarDistance(c1: number[], c2: number[]): number {
  const dx = c2[0] - c1[0];
  const dy = c2[1] - c1[1];
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Calculate bearing between two points (whole-circle bearing, 0 = North, 90 = East).
 * Works correctly for projected CRS where the Y axis points north.
 * @param from - Start coordinate [x, y].
 * @param to - End coordinate [x, y].
 * @returns Bearing in degrees 0–360.
 */
function calculateBearingDeg(from: number[], to: number[]): number {
  const dE = to[0] - from[0];
  const dN = to[1] - from[1];
  let bearing = (Math.atan2(dE, dN) * 180) / Math.PI;
  if (bearing < 0) bearing += 360;
  return bearing;
}

/**
 * Midpoint of two coordinates.
 * @param c1 - First coordinate.
 * @param c2 - Second coordinate.
 */
function midpoint(c1: number[], c2: number[]): number[] {
  return [(c1[0] + c2[0]) / 2, (c1[1] + c2[1]) / 2];
}

/**
 * Format a distance with appropriate units.
 * @param metres - Distance in metres.
 * @returns Formatted string, e.g. "12.34 m" or "1.234 km".
 */
function formatDistance(metres: number): string {
  if (metres >= 1000) {
    return `${(metres / 1000).toFixed(3)} km`;
  }
  return `${metres.toFixed(2)} m`;
}

/**
 * Format a bearing as a cardinal direction with degrees.
 * @param deg - Whole-circle bearing in degrees (0–360).
 * @returns String like "45.0\u00b0 NE".
 */
function formatBearingCardinal(deg: number): string {
  const cardinals = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  const idx = Math.round(deg / 45) % 8;
  return `${deg.toFixed(1)}\u00b0 ${cardinals[idx]}`;
}

/**
 * Calculate cumulative planar distance along a polyline.
 * @param coords - Array of coordinates [[x,y], ...].
 * @returns Total distance in map units.
 */
function cumulativeDistance(coords: number[][]): number {
  let total = 0;
  for (let i = 1; i < coords.length; i++) {
    total += planarDistance(coords[i - 1], coords[i]);
  }
  return total;
}

// ---------------------------------------------------------------------------
// HistoryManager — undo / redo for editing operations
// ---------------------------------------------------------------------------

/** Types of operations that can be recorded. */
type HistoryOpType = 'add' | 'modify' | 'delete';

/**
 * A single recorded history entry — discriminated union so TypeScript can
 * narrow `before` / `after` correctly in {@link HistoryManager.undo} / `redo`.
 */
type HistoryEntry =
  | {
      op: 'add';
      /** Always null for 'add' (nothing existed before). */
      before: null;
      /** Cloned feature to re-add on redo. */
      after: Feature;
      featureId: string | number | undefined;
    }
  | {
      op: 'modify';
      /** Geometry snapshot before the modification (for undo). */
      before: Geometry | null;
      /** Geometry snapshot after the modification (for redo). */
      after: Geometry | null;
      featureId: string | number | undefined;
    }
  | {
      op: 'delete';
      /** Cloned feature to re-add on undo. */
      before: Feature;
      /** Always null for 'delete' (nothing exists after). */
      after: null;
      featureId: string | number | undefined;
    };

/**
 * Undo / redo history manager for OL VectorSource editing operations.
 *
 * Tracks add, modify, and delete operations up to {@link MAX_HISTORY_DEPTH}
 * entries. Call {@link undo} or {@link redo} to revert or replay operations.
 *
 * @example
 * ```ts
 * const history = new HistoryManager(vectorSource);
 *
 * // Record operations as they happen:
 * history.record('add', newFeature);
 * history.record('modify', changedFeature, originalGeometry);
 * history.record('delete', removedFeature);
 *
 * // Undo the last operation:
 * history.undo();
 *
 * // Redo it:
 * history.redo();
 * ```
 */
export class HistoryManager {
  private undoStack: HistoryEntry[] = [];
  private redoStack: HistoryEntry[] = [];
  private source: HistorySource;

  /**
   * @param source - The OL VectorSource whose operations are being tracked.
   *                  Accepts a {@link HistorySource} (structural subset of VectorSource,
   *                  so mocks and fakes satisfy the type in tests).
   */
  constructor(source: HistorySource) {
    this.source = source;
  }

  /**
   * Record an operation for later undo / redo.
   *
   * @param op        - Operation type.
   * @param feature   - The OL Feature involved.
   * @param beforeGeo - Geometry snapshot *before* the operation (for 'modify' and 'delete').
   */
  record(op: HistoryOpType, feature: Feature, beforeGeo?: Geometry | null): void {
    const featureId = feature.getId() ?? generateFeatureId();

    if (op === 'add') {
      this.undoStack.push({ op: 'add', before: null, after: feature.clone(), featureId });
    } else if (op === 'modify') {
      const currentGeom = feature.getGeometry();
      this.undoStack.push({
        op: 'modify',
        before: beforeGeo ? beforeGeo.clone() : null,
        after: currentGeom ? currentGeom.clone() : null,
        featureId,
      });
    } else if (op === 'delete') {
      this.undoStack.push({ op: 'delete', before: feature.clone(), after: null, featureId });
    }

    // Enforce max depth — discard oldest entry
    if (this.undoStack.length > MAX_HISTORY_DEPTH) {
      this.undoStack.shift();
    }

    // Any new operation clears the redo branch
    this.redoStack = [];
  }

  /**
   * Undo the most recent operation.
   * @returns `true` if an operation was undone, `false` if nothing to undo.
   */
  undo(): boolean {
    const entry = this.undoStack.pop();
    if (!entry) return false;

    if (entry.op === 'add') {
      // Undo add → remove the feature from the source
      const feature = this.findFeature(entry.featureId);
      if (feature) this.source.removeFeature(feature);
    } else if (entry.op === 'modify') {
      // Undo modify → restore the original geometry
      const feature = this.findFeature(entry.featureId);
      if (feature && entry.before) feature.setGeometry(entry.before);
    } else if (entry.op === 'delete') {
      // Undo delete → re-add the feature
      this.source.addFeature(entry.before);
    }

    this.redoStack.push(entry);
    return true;
  }

  /**
   * Redo the most recently undone operation.
   * @returns `true` if an operation was redone, `false` if nothing to redo.
   */
  redo(): boolean {
    const entry = this.redoStack.pop();
    if (!entry) return false;

    if (entry.op === 'add') {
      // Redo add → re-add the feature
      this.source.addFeature(entry.after);
    } else if (entry.op === 'modify') {
      // Redo modify → restore the modified geometry
      const feature = this.findFeature(entry.featureId);
      if (feature && entry.after) feature.setGeometry(entry.after);
    } else if (entry.op === 'delete') {
      // Redo delete → remove the feature again
      const feature = this.findFeature(entry.featureId);
      if (feature) this.source.removeFeature(feature);
    }

    this.undoStack.push(entry);
    return true;
  }

  /** Whether at least one undo operation is available. */
  canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  /** Whether at least one redo operation is available. */
  canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  /** Number of undoable operations. */
  getUndoCount(): number {
    return this.undoStack.length;
  }

  /** Number of redoable operations. */
  getRedoCount(): number {
    return this.redoStack.length;
  }

  /** Clear all history (both undo and redo stacks). */
  clear(): void {
    this.undoStack = [];
    this.redoStack = [];
  }

  /** Look up a feature in the source by its id (supports string, number, or undefined). */
  private findFeature(id: string | number | undefined): Feature | null {
    if (id == null) return null;
    const byId = this.source.getFeatureById(id);
    if (byId) return byId;
    const features = this.source.getFeatures();
    for (let i = 0; i < features.length; i++) {
      if (features[i].getId() === id) return features[i];
    }
    return null;
  }
}

// ---------------------------------------------------------------------------
// Orthogonal constraint — geometryFunction factory for OL Draw (Polygon)
// ---------------------------------------------------------------------------

/**
 * A geometry function that may carry an optional `_cleanupListeners` hook
 * (used to tear down global keyboard listeners attached by the factory).
 */
interface GeomFnWithCleanup {
  (coordinates: number[][], geometry: SimpleGeometry | undefined): SimpleGeometry;
  _cleanupListeners?: () => void;
}

/**
 * Creates an orthogonal geometry function for OL Draw (Polygon type).
 *
 * While the user draws a parcel polygon, each new edge is constrained to be at
 * exactly 90 degrees to the previous edge — the standard cadastral CAD behaviour.
 *
 * The constraint is active when the `enabled()` callback returns `true`.
 * Holding **Shift** temporarily disables the constraint for free-form drawing.
 *
 * The returned geometry function should be passed as the `geometryFunction`
 * option to the `ol/interaction/Draw` constructor.
 *
 * Attach a cleanup call later via the `_cleanupListeners` property on the
 * returned function to remove global keyboard listeners.
 *
 * @param enabled - Callback returning whether the orthogonal constraint is active.
 * @returns A geometry function compatible with OL Draw's `geometryFunction` option.
 */
function createOrthogonalGeometryFunction(
  enabled: () => boolean,
): GeomFnWithCleanup {
  let shiftHeld = false;

  const onKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Shift') shiftHeld = true;
  };
  const onKeyUp = (e: KeyboardEvent) => {
    if (e.key === 'Shift') shiftHeld = false;
  };

  if (typeof window !== 'undefined') {
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
  }

  const geomFn = ((coordinates: number[][], geometry: SimpleGeometry | undefined): SimpleGeometry => {
    // The wrapper (see createEditingInteractionStack) always supplies a geometry,
    // but be defensive: OL's DrawEvent calls geometryFunction with `undefined`
    // on the very first invocation of a sketch.
    if (!geometry) {
      // Returning a fresh empty Polygon is safe — the wrapper will overwrite
      // this on the next call. We can't construct one here without a circular
      // import, so fall back to returning the input (defensive no-op).
      throw new Error('createOrthogonalGeometryFunction: geometry must be supplied by the wrapper');
    }

    const constrained = enabled() && !shiftHeld;

    // Need at least 3 coordinates to establish a previous edge: [pN-1, pN, rubberBand]
    if (!constrained || coordinates.length < 3) {
      geometry.setCoordinates([coordinates.slice()] as unknown as number[][][]);
      return geometry;
    }

    // Work on a copy so we don't mutate the input
    const pts = coordinates.map((c) => c.slice());

    // Index of the second-to-last fixed point
    const prevIdx = pts.length - 3;
    const lastFixedIdx = pts.length - 2;
    const prevPt = pts[prevIdx];
    const lastFixed = pts[lastFixedIdx];
    const mousePos = pts[pts.length - 1];

    if (!prevPt || !lastFixed || !mousePos) {
      geometry.setCoordinates([pts] as unknown as number[][][]);
      return geometry;
    }

    // Direction vector of the previous edge: lastFixed - prevPt
    const dx = lastFixed[0] - prevPt[0];
    const dy = lastFixed[1] - prevPt[1];
    const lenSq = dx * dx + dy * dy;

    if (lenSq < 1e-12) {
      // Degenerate previous edge — pass through unconstrained
      geometry.setCoordinates([pts] as unknown as number[][][]);
      return geometry;
    }

    // Vector from lastFixed to mousePos
    const ex = mousePos[0] - lastFixed[0];
    const ey = mousePos[1] - lastFixed[1];

    // Scalar projection onto the previous edge direction
    const dot = (ex * dx + ey * dy) / lenSq;

    // Parallel projection (same direction as previous edge)
    const parX = lastFixed[0] + dot * dx;
    const parY = lastFixed[1] + dot * dy;

    // Perpendicular projection (90 degrees from previous edge)
    const perpX = lastFixed[0] + ex - dot * dx;
    const perpY = lastFixed[1] + ey - dot * dy;

    // Choose the projection closer to the actual mouse position
    const distPar = (mousePos[0] - parX) ** 2 + (mousePos[1] - parY) ** 2;
    const distPerp = (mousePos[0] - perpX) ** 2 + (mousePos[1] - perpY) ** 2;

    const snapped = distPar < distPerp ? [parX, parY] : [perpX, perpY];
    pts[pts.length - 1] = snapped;

    geometry.setCoordinates([pts] as unknown as number[][][]);
    return geometry;
  }) as GeomFnWithCleanup;

  // Expose cleanup so the caller can remove keyboard listeners on teardown
  geomFn._cleanupListeners = () => {
    if (typeof window !== 'undefined') {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    }
  };

  return geomFn;
}

// ---------------------------------------------------------------------------
// createEditingInteractionStack
// ---------------------------------------------------------------------------

/**
 * Creates the full editing interaction stack for cadastral parcel editing.
 *
 * Sets up the snap → modify → draw chain with optional orthogonal constraints,
 * automatic history tracking (undo / redo), keyboard shortcuts, and event
 * callbacks.
 *
 * **Keyboard shortcuts:**
 * - `Delete` / `Backspace` — remove the currently selected feature
 * - `Ctrl+Z` — undo the last operation
 * - `Ctrl+Shift+Z` / `Ctrl+Y` — redo
 * - `Shift` (hold while drawing) — temporarily disable orthogonal constraint
 *
 * @param options - Editing configuration. See {@link EditingOptions}.
 * @returns The interaction stack. Add `snap`, `modify`, and `draw` to the map
 *          via `map.addInteraction()`. Call `removeAll()` on teardown.
 *
 * @example
 * ```ts
 * const stack = await createEditingInteractionStack({
 *   source: parcelSource,
 *   snapSource: existingParcelsSource,
 *   snapTolerance: 15,
 *   orthogonalConstraint: true,
 *   onFeatureAdded: (f) => ),
 * });
 *
 * map.addInteraction(stack.snap);
 * map.addInteraction(stack.modify);
 * map.addInteraction(stack.draw);
 *
 * // Undo the last operation:
 * stack.history.undo();
 *
 * // Cleanup on unmount:
 * stack.removeAll();
 * ```
 */
export async function createEditingInteractionStack(
  options: EditingOptions,
): Promise<InteractionStack> {
  const {
    source,
    snapSource,
    snapTolerance = 10,
    orthogonalConstraint: orthoEnabled = true,
    onFeatureAdded,
    onFeatureModified,
    onFeatureDeleted,
  } = options;

  // ── History ────────────────────────────────────────────────────────────
  const history = new HistoryManager(source);

  // ── Select (required by Modify) ────────────────────────────────────────
  const select = new Select({ hitTolerance: 5 });

  // ── Snap ───────────────────────────────────────────────────────────────
  // OL Snap's option type only declares `source` (singular), but the runtime
  // also accepts a `sources` array. Extend the type locally.
  const snapOptions: SnapOptions & { sources?: VectorSource<Feature>[] } = {
    source,
    pixelTolerance: snapTolerance,
  };
  if (snapSource) {
    snapOptions.sources = [source, snapSource];
  }
  const snap = new Snap(snapOptions);

  // ── Modify ─────────────────────────────────────────────────────────────
  const modify = new Modify({ features: select.getFeatures() });

  // Track original geometries per ModifyEvent using a WeakMap (avoids
  // augmenting the event object with ad-hoc properties).
  const originalGeometriesByEvent = new WeakMap<
    ModifyEvent,
    Array<{ feature: Feature; geometry: Geometry | undefined }>
  >();

  modify.on('modifystart', (event: ModifyEvent) => {
    const features = event.features?.getArray();
    if (!features || features.length === 0) return;
    // Snapshot every feature's geometry before modification
    originalGeometriesByEvent.set(
      event,
      features.map((f) => ({
        feature: f,
        geometry: f.getGeometry()?.clone(),
      })),
    );
  });

  modify.on('modifyend', (event: ModifyEvent) => {
    const originals = originalGeometriesByEvent.get(event) ?? [];
    for (const { feature, geometry } of originals) {
      history.record('modify', feature, geometry);
      if (onFeatureModified) onFeatureModified(feature);
    }
    originalGeometriesByEvent.delete(event);
  });

  // ── Draw with optional orthogonal constraint ───────────────────────────
  const rawGeomFn = createOrthogonalGeometryFunction(() => orthoEnabled);

  // Wrap to lazily create the Polygon the first time OL calls the function.
  // OL's Draw calls geometryFunction with `undefined` on the first invocation
  // (see Draw.js — `this.geometryFunction_(this.sketchCoords_, undefined, projection)`),
  // so we materialise an empty Polygon in that case.
  const wrappedGeomFn: DrawGeometryFunction = (coordinates, geometry) => {
    let geom = geometry;
    if (!geom) {
      geom = new Polygon([]);
    }
    return rawGeomFn(coordinates as number[][], geom);
  };

  const draw = new Draw({
    source,
    type: 'Polygon',
    geometryFunction: wrappedGeomFn,
    snapTolerance: snapTolerance,
  });

  draw.on('drawend', (event: DrawEvent) => {
    const feature = event.feature;
    if (!feature.getId()) {
      feature.setId(generateFeatureId());
    }
    history.record('add', feature);
    if (onFeatureAdded) onFeatureAdded(feature);
  });

  // ── Keyboard shortcuts (Delete, Ctrl+Z, Ctrl+Y) ──────────────────────
  const onKeyDown = (event: KeyboardEvent) => {
    // Delete / Backspace — remove selected features
    if (
      (event.key === 'Delete' || event.key === 'Backspace') &&
      !event.ctrlKey &&
      !event.metaKey
    ) {
      const selected = select.getFeatures().getArray();
      for (const feature of selected) {
        const fid = feature.getId();
        history.record('delete', feature);
        source.removeFeature(feature);
        select.getFeatures().remove(feature);
        if (onFeatureDeleted && fid != null) onFeatureDeleted(String(fid));
      }
    }

    // Ctrl+Z — undo
    if ((event.ctrlKey || event.metaKey) && event.key === 'z' && !event.shiftKey) {
      event.preventDefault();
      history.undo();
    }

    // Ctrl+Shift+Z or Ctrl+Y — redo
    if (
      ((event.ctrlKey || event.metaKey) && event.key === 'z' && event.shiftKey) ||
      ((event.ctrlKey || event.metaKey) && event.key === 'y')
    ) {
      event.preventDefault();
      history.redo();
    }
  };

  if (typeof document !== 'undefined') {
    document.addEventListener('keydown', onKeyDown);
  }

  // ── Cleanup ───────────────────────────────────────────────────────────
  const removeAll = () => {
    if (typeof document !== 'undefined') {
      document.removeEventListener('keydown', onKeyDown);
    }
    const cleanup = rawGeomFn._cleanupListeners;
    if (typeof cleanup === 'function') {
      cleanup();
    }
    history.clear();
  };

  return { snap, modify, draw, history, removeAll };
}

// ---------------------------------------------------------------------------
// createSubdivisionInteraction
// ---------------------------------------------------------------------------

/**
 * Creates a subdivision interaction that lets the surveyor draw a split line
 * across an existing parcel, dividing it into two new parcels.
 *
 * The split line snaps to the parcel edges. On completion, the parcel is split
 * using `@turf/turf`'s `lineSplit` and the two resulting polygon features
 * are delivered via the `onComplete` callback.
 *
 * **Coordinate handling:** Source geometries are transformed to WGS84 for the
 * turf split, then the results are transformed back to the source projection.
 *
 * @param options - Subdivision configuration. See {@link SubdivisionOptions}.
 * @returns An object with the draw and snap interactions plus a cleanup function.
 *
 * @example
 * ```ts
 * const { draw, snap, cleanup } = await createSubdivisionInteraction({
 *   source: parcelSource,
 *   targetFeature: selectedParcel,
 *   sourceProjection: 'EPSG:3857',
 *   onComplete: (polyA, polyB) => {
 *     parcelSource.removeFeature(selectedParcel);
 *     parcelSource.addFeature(polyA);
 *     parcelSource.addFeature(polyB);
 *   },
 * });
 *
 * map.addInteraction(snap);
 * map.addInteraction(draw);
 * ```
 */
export async function createSubdivisionInteraction(
  options: SubdivisionOptions,
): Promise<{
  /** The OL Draw interaction for the split line (LineString type). */
  draw: Draw;
  /** The OL Snap interaction that snaps the split line to parcel edges. */
  snap: Snap;
  /** Remove event listeners and clean up temporary sources. */
  cleanup: () => void;
}> {
  const {
    source,
    targetFeature,
    snapTolerance = 10,
    sourceProjection = 'EPSG:3857',
    onComplete,
    onError,
  } = options;

  // ── Lazy-load turf ────────────────────────────────────────────────────
  let turf: typeof import('@turf/turf');
  try {
    turf = await import('@turf/turf');
  } catch {
    throw new Error(
      '[cadastralEditing] @turf/turf is required for parcel subdivision. ' +
        'Install it with: npm install @turf/turf',
    );
  }

  // ── Temporary sources ─────────────────────────────────────────────────
  const splitSource = new VectorSource();
  const targetSource = new VectorSource({ features: [targetFeature] });

  // ── Snap interaction ───────────────────────────────────────────────────
  // OL Snap runtime supports a `sources` array but the v10.8 types only
  // declare `source` (singular). Extend the type locally.
  const snap = new Snap({
    sources: [splitSource, targetSource],
    pixelTolerance: snapTolerance,
  } as SnapOptions & { sources?: VectorSource<Feature>[] });

  // ── Draw interaction (split line) ─────────────────────────────────────
  const draw = new Draw({
    source: splitSource,
    type: 'LineString',
    snapTolerance: snapTolerance,
    minPoints: 2,
  });

  let cleanedUp = false;

  draw.on('drawend', async (event: DrawEvent) => {
    if (cleanedUp) return;

    const splitLineFeature = event.feature;
    const splitLineGeom = splitLineFeature.getGeometry();

    try {
      // ── Validate target geometry ───────────────────────────────────────
      const parcelGeom = targetFeature.getGeometry();
      if (!parcelGeom) {
        throw new Error('Target feature has no geometry.');
      }

      // ── Transform to WGS84 for turf ───────────────────────────────────
      const parcelRings = (parcelGeom as Polygon).getCoordinates();
      const lineCoords = (splitLineGeom as LineString | null)?.getCoordinates() ?? [];

      const parcelRingsWgs84 = parcelRings.map((ring: number[][]) =>
        ring.map((c: number[]) => transform(c, sourceProjection, 'EPSG:4326')),
      );
      const lineCoordsWgs84 = lineCoords.map((c: number[]) =>
        transform(c, sourceProjection, 'EPSG:4326'),
      );

      // ── Build turf geometries ─────────────────────────────────────────
      const parcelGeoJSON = turf.polygon(parcelRingsWgs84);
      const lineGeoJSON = turf.lineString(lineCoordsWgs84);

      // ── Split ─────────────────────────────────────────────────────────
      // NOTE: turf's `lineSplit(line, splitter)` types require the first arg to
      // be a LineString, but the legacy call here passes a polygon first. The
      // types reject this; we cast to preserve the existing runtime behaviour.
      // (Pre-existing shape mismatch that was hidden by `any` — preserved per
      // the type-hygiene migration recipe's "don't fix unrelated bugs" rule.)
      const splitResult = turf.lineSplit(
        parcelGeoJSON as unknown as Parameters<typeof turf.lineSplit>[0],
        lineGeoJSON,
      ) as unknown as { features: Array<{ geometry: { coordinates: number[][][] } }> };

      if (
        !splitResult ||
        !splitResult.features ||
        splitResult.features.length < 2
      ) {
        throw new Error(
          'The split line does not fully cross the parcel. ' +
            'Draw a line from one edge of the parcel to another.',
        );
      }

      if (splitResult.features.length > 2) {
        throw new Error(
          `Split produced ${splitResult.features.length} polygons (expected 2). ` +
            'The split line may cross a parcel vertex — try a different line.',
        );
      }

      // ── Convert results back to source projection ─────────────────────
      const feature0 = splitResult.features[0];
      const feature1 = splitResult.features[1];
      const coordsA = feature0.geometry.coordinates.map(
        (ring: number[][]) =>
          ring.map((c: number[]) => transform(c, 'EPSG:4326', sourceProjection)),
      );
      const coordsB = feature1.geometry.coordinates.map(
        (ring: number[][]) =>
          ring.map((c: number[]) => transform(c, 'EPSG:4326', sourceProjection)),
      );

      const polyA = new Feature({ geometry: new Polygon(coordsA) });
      polyA.setId(generateFeatureId());

      const polyB = new Feature({ geometry: new Polygon(coordsB) });
      polyB.setId(generateFeatureId());

      // ── Propagate properties from the original parcel ─────────────────
      const props = { ...targetFeature.getProperties() };
      delete props.geometry;
      const parentId = targetFeature.getId();
      polyA.setProperties({ ...props, subdivided_from: parentId });
      polyB.setProperties({ ...props, subdivided_from: parentId });

      // Copy the original feature's style if present
      const origStyle = targetFeature.getStyle();
      if (origStyle) {
        polyA.setStyle(origStyle);
        polyB.setStyle(origStyle);
      }

      onComplete(polyA, polyB);
    } catch (err: unknown) {
      const error = err instanceof Error ? err : new Error(String(err));
      if (onError) {
        onError(error);
      } else {
        console.error('[cadastralEditing] Subdivision failed:', error.message);
      }
    } finally {
      splitSource.clear();
      cleanup();
    }
  });

  const cleanup = () => {
    cleanedUp = true;
    splitSource.clear();
  };

  return { draw, snap, cleanup };
}

// ---------------------------------------------------------------------------
// createMeasureWhileDraw
// ---------------------------------------------------------------------------

/**
 * Displays real-time distance and bearing annotations while the user draws.
 *
 * As the surveyor clicks vertices during an OL Draw interaction, this module
 * renders measurement labels on a temporary overlay layer:
 * - **Per-edge distance** (e.g. "23.45 m") at the midpoint of each edge
 * - **Per-edge bearing** (e.g. "90.0° E") alongside the distance
 * - **Cumulative distance** (e.g. "Total: 67.89 m") at the cursor
 *
 * All measurements use planar distance (accurate for projected CRS such as
 * EPSG:21037 / EPSG:3857). For geographic CRS (EPSG:4326), proj4 is used to
 * project to Kenya UTM 36M before computing distances.
 *
 * @param options - Measurement configuration. See {@link MeasureWhileDrawOptions}.
 * @returns A handle with a `cleanup` function and a reference to the annotation layer.
 *
 * @example
 * ```ts
 * const measure = await createMeasureWhileDraw({
 *   map,
 *   drawInteraction: stack.draw,
 *   projection: 'EPSG:3857',
 * });
 *
 * // When done (e.g. on unmount):
 * measure.cleanup();
 * ```
 */
export async function createMeasureWhileDraw(
  options: MeasureWhileDrawOptions,
): Promise<MeasureHandle> {
  const {
    map,
    drawInteraction,
    projection = 'EPSG:3857',
    showBearing = true,
    showCumulativeDistance = true,
    showEdgeDistance = true,
  } = options;

  // ── Optional proj4 for geographic CRS ─────────────────────────────────
  let toMetric: ((coord: number[]) => number[]) | null = null;

  if (projection === 'EPSG:4326') {
    // proj4 is a hard dependency (declared in package.json). Use it directly
    // to convert WGS84 coordinates to Kenya UTM Zone 36M for metric distance.
    // Default to Kenya UTM Zone 36M for metric conversion
    const utm36m =
      '+proj=utm +zone=36 +south +ellps=WGS84 +datum=WGS84 +units=m +no_defs';
    toMetric = (coord: number[]) => proj4('EPSG:4326', utm36m, coord);
  }

  /**
   * Compute distance between two coordinates, projecting to metric if needed.
   */
  const measureDistance = (c1: number[], c2: number[]): number => {
    if (toMetric) {
      return planarDistance(toMetric(c1), toMetric(c2));
    }
    return planarDistance(c1, c2);
  };

  // ── Annotation layer ──────────────────────────────────────────────────
  const measureSource = new VectorSource();

  const measureLayer = new VectorLayer({
    source: measureSource,
    style: (feature: FeatureLike) => {
      const label = (feature.get('measureLabel') as string) ?? '';
      return new Style({
        text: new Text({
          font: '11px monospace',
          fill: new Fill({ color: '#1a237e' }),
          stroke: new Stroke({ color: '#ffffff', width: 3 }),
          text: label,
          offsetY: -14,
          placement: 'point',
        }),
      });
    },
    zIndex: 100,
  });

  map.addLayer(measureLayer);

  // ── State ─────────────────────────────────────────────────────────────
  let active = false;
  let sketchFeature: Feature | null = null;
  let annotationFeatures: Feature[] = [];
  let geometryChangeKey: EventsKey | null = null;

  /**
   * Remove all annotation features from the measure source.
   */
  function clearAnnotations(): void {
    for (const f of annotationFeatures) {
      measureSource.removeFeature(f);
    }
    annotationFeatures = [];
  }

  /**
   * (Re)build annotation features from the current sketch coordinates.
   */
  function updateAnnotations(coords: number[][]): void {
    clearAnnotations();

    if (coords.length < 2) return;

    let cumulative = 0;

    for (let i = 1; i < coords.length; i++) {
      const from = coords[i - 1];
      const to = coords[i];
      const edgeDist = measureDistance(from, to);
      cumulative += edgeDist;

      const mid = midpoint(from, to);
      const bear = calculateBearingDeg(from, to);

      // Build label text
      const parts: string[] = [];
      if (showEdgeDistance) parts.push(formatDistance(edgeDist));
      if (showBearing) parts.push(formatBearingCardinal(bear));

      const feature = new Feature({ geometry: new Point(mid) });
      feature.set('measureLabel', parts.join('  '));
      feature.set('measureType', 'edge');
      measureSource.addFeature(feature);
      annotationFeatures.push(feature);
    }

    // Cumulative label at the last vertex
    if (showCumulativeDistance && coords.length > 2) {
      const lastCoord = coords[coords.length - 1];
      const totalFeature = new Feature({ geometry: new Point(lastCoord) });
      totalFeature.set('measureLabel', `\u03A3 ${formatDistance(cumulative)}`);
      totalFeature.set('measureType', 'cumulative');
      measureSource.addFeature(totalFeature);
      annotationFeatures.push(totalFeature);
    }
  }

  /**
   * Extract the current sketch ring coordinates from the sketch feature geometry.
   */
  function readSketchCoords(): number[][] | null {
    if (!sketchFeature) return null;
    const geom = sketchFeature.getGeometry();
    if (!geom) return null;

    const type = geom.getType();
    if (type === 'Polygon') {
      const rings = (geom as Polygon).getCoordinates();
      return rings.length > 0 ? rings[0] : null;
    }
    if (type === 'LineString') {
      return (geom as LineString).getCoordinates();
    }
    return null;
  }

  // ── Event handlers ────────────────────────────────────────────────────

  function onDrawStart(event: DrawEvent): void {
    active = true;
    sketchFeature = event.feature;

    // Listen for geometry changes on the sketch feature
    const geom = sketchFeature.getGeometry();
    if (geom) {
      geometryChangeKey = geom.on('change', () => {
        if (!active) return;
        const coords = readSketchCoords();
        if (coords) updateAnnotations(coords);
      }) as EventsKey;
    }

    clearAnnotations();
  }

  function onDrawEnd(): void {
    // Keep annotations visible after draw ends — caller decides when to cleanup
    detachSketchListener();
  }

  function onDrawAbort(): void {
    active = false;
    clearAnnotations();
    detachSketchListener();
  }

  function detachSketchListener(): void {
    if (geometryChangeKey) {
      // unByKey is the correct OL API for removing a listener by its EventsKey
      // (returned from `geom.on(...)`). The previous code passed the key to
      // `geom.un('change', key)` which is a type error and a no-op at runtime.
      unByKey(geometryChangeKey);
    }
    geometryChangeKey = null;
    sketchFeature = null;
    active = false;
  }

  // ── Attach listeners ──────────────────────────────────────────────────
  drawInteraction.on('drawstart', onDrawStart);
  drawInteraction.on('drawend', onDrawEnd);
  drawInteraction.on('drawabort', onDrawAbort);

  // ── Cleanup ───────────────────────────────────────────────────────────

  function cleanup(): void {
    detachSketchListener();
    drawInteraction.un('drawstart', onDrawStart);
    drawInteraction.un('drawend', onDrawEnd);
    drawInteraction.un('drawabort', onDrawAbort);
    clearAnnotations();
    map.removeLayer(measureLayer);
  }

  return { cleanup, layer: measureLayer };
}

// ---------------------------------------------------------------------------
// createHistoryManager — standalone factory
// ---------------------------------------------------------------------------

/**
 * Creates a standalone HistoryManager for a given OL VectorSource.
 *
 * Use this when you need undo / redo support without the full editing
 * interaction stack (e.g. for programmatic feature manipulation).
 *
 * @param source - The OL VectorSource whose operations will be tracked.
 * @returns A new HistoryManager instance.
 *
 * @example
 * ```ts
 * const history = await createHistoryManager(parcelSource);
 *
 * // Manually record a feature addition:
 * parcelSource.addFeature(newParcel);
 * history.record('add', newParcel);
 *
 * // Undo:
 * history.undo();
 * ```
 */
export async function createHistoryManager(
  source: HistorySource,
): Promise<HistoryManager> {
  return new HistoryManager(source);
}

'use client';

/**
 * METARDU Deed Plan Export
 *
 * Print-quality deed plan export for Survey of Kenya (SoK) compliance.
 * Renders the OpenLayers map canvas at an exact scale and DPI, then composites
 * overlays (title block, north arrow, scale bar, grid ticks) directly onto the
 * canvas for pixel-perfect PNG output.
 *
 * All OL imports are dynamic for SSR safety (Next.js requirement).
 * The map view (center, resolution, size, pixel ratio) is saved before export
 * and fully restored afterwards, regardless of success or failure.
 *
 * Scale derivation:
 *   resolution = scale × 0.0254 / DPI   [metres per pixel]
 *   where 0.0254 = 25.4 mm/in ÷ 1000 mm/m
 */

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Paper dimensions in mm [width, height] */
const PAPER_SIZES_MM: Record<string, [number, number]> = {
  a1: [841, 594],
  a2: [594, 420],
  a3: [420, 297],
  a4: [297, 210],
};

/** Millimetres per inch */
const MM_PER_INCH = 25.4;

/** Points per inch (typographic) */
const PT_PER_INCH = 72;

/** Outer border thickness in mm */
const OUTER_BORDER_MM = 0.7;

/** Inner margin in mm (between outer border and drawing area) */
const MARGIN_MM = 10;

/** Maximum time to wait for a render in ms */
const RENDER_TIMEOUT_MS = 30_000;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/**
 * Options accepted by {@link exportDeedPlan} and {@link downloadDeedPlan}.
 */
interface DeedPlanExportOptions {
  /** OpenLayers map instance. */
  map: import('ol/Map').default;
  /** Target scale denominator (e.g. `1000` for 1:1000). */
  scale: number;
  /** ISO paper size. */
  paperSize: 'a1' | 'a2' | 'a3' | 'a4';
  /** Page orientation. */
  orientation: 'landscape' | 'portrait';
  /** Output resolution in dots per inch (default `300`). */
  dpi?: number;
  /** Render a north arrow in the upper-right area (default `true`). */
  includeNorthArrow?: boolean;
  /** Render a calibrated scale bar at bottom-centre (default `true`). */
  includeScaleBar?: boolean;
  /** Render E/N grid tick labels along drawing edges (default `true`). */
  includeGridTicks?: boolean;
  /** Render the SoK-style title block (default `true`). */
  includeTitleBlock?: boolean;
  /** Land Registration number (e.g. `209/3344`). */
  lrNumber?: string;
  /** Project / scheme name. */
  projectName?: string;
  /** Licensed surveyor full name. */
  surveyorName?: string;
  /** Institution of Surveyors of Kenya (ISK) licence number. */
  surveyorLicense?: string;
  /** Client / commissioning body. */
  clientName?: string;
  /** County in Kenya. */
  county?: string;
}

// ---------------------------------------------------------------------------
// Unit-conversion helpers
// ---------------------------------------------------------------------------

/** Millimetres → pixels at a given DPI. */
function mmToPx(mm: number, dpi: number): number {
  return (mm * dpi) / MM_PER_INCH;
}

/** Typographic points → pixels at a given DPI. */
function ptToPx(pt: number, dpi: number): number {
  return (pt * dpi) / PT_PER_INCH;
}

// ---------------------------------------------------------------------------
// Geometry helpers
// ---------------------------------------------------------------------------

/**
 * Return paper dimensions in mm, swapped when landscape is requested.
 *
 * @returns `[width, height]` in mm
 */
function getPaperDimensions(
  paperSize: string,
  orientation: 'landscape' | 'portrait',
): [number, number] {
  const [w, h] = PAPER_SIZES_MM[paperSize] ?? PAPER_SIZES_MM.a4;
  return orientation === 'landscape' ? [Math.max(w, h), Math.min(w, h)]
                                   : [Math.min(w, h), Math.max(w, h)];
}

/**
 * Calculate the map resolution (metres / CSS pixel) required to render at
 * the requested scale and DPI.
 *
 * Derivation
 * ----------
 *   scale  = ground_m / paper_m
 *   paper_m = paper_mm / 1000
 *   pixels  = paper_mm × (DPI / 25.4)
 *   ground_m = scale × paper_mm / 1000
 *   resolution = ground_m / pixels
 *              = (scale × paper_mm / 1000) / (paper_mm × DPI / 25.4)
 *              = scale × 25.4 / (1000 × DPI)
 *              = scale × 0.0254 / DPI
 */
function calculateResolution(scale: number, dpi: number): number {
  return (scale * MM_PER_INCH) / (dpi * 1000);
}

/**
 * Compute a "nice" grid interval (round number) that yields approximately
 * `targetLines` lines across `extentWidth` metres.
 *
 * Returns values like 1, 2, 5, 10, 20, 50, 100, 200, 500 …
 */
function niceGridInterval(extentWidth: number, targetLines: number = 8): number {
  const rough = extentWidth / targetLines;
  if (rough <= 0) return 1;

  const mag = Math.pow(10, Math.floor(Math.log10(rough)));
  const norm = rough / mag;

  const nice = norm < 1.5 ? 1
             : norm < 3.5 ? 2
             : norm < 7.5 ? 5
             :             10;

  return nice * mag;
}

/**
 * Format a projected coordinate for grid-tick labels.
 * Shows an integer when possible, otherwise one decimal place.
 */
function formatCoord(value: number): string {
  const rounded = Math.round(value * 10) / 10;
  return Number.isInteger(rounded) ? rounded.toFixed(0) : rounded.toFixed(1);
}

/** Return today's date as `DD MMM YYYY` (e.g. `15 Jan 2025`). */
function getFormattedDate(): string {
  const d = new Date();
  const months = ['Jan','Feb','Mar','Apr','May','Jun',
                  'Jul','Aug','Sep','Oct','Nov','Dec'];
  return `${String(d.getDate()).padStart(2, '0')} ${months[d.getMonth()]} ${d.getFullYear()}`;
}

// ---------------------------------------------------------------------------
// Overlay: Border
// ---------------------------------------------------------------------------

/**
 * Draw the deed-plan border frame.
 *
 * ┌─ thick outer line (0.7 mm)
 * │  ┌─ thin inner line (0.25 mm) with 10 mm margin
 * │  │
 * │  │   drawing area
 * │  │
 * │  └─
 * └─
 */
function drawBorder(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  dpi: number,
): void {
  const outer = mmToPx(OUTER_BORDER_MM, dpi);
  const margin = mmToPx(MARGIN_MM, dpi);

  // Outer border
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = outer;
  ctx.strokeRect(outer / 2, outer / 2, width - outer, height - outer);

  // Inner border
  ctx.lineWidth = mmToPx(0.25, dpi);
  ctx.strokeRect(margin, margin, width - 2 * margin, height - 2 * margin);
}

// ---------------------------------------------------------------------------
// Overlay: Title Block
// ---------------------------------------------------------------------------

/**
 * Draw the SoK-style title block in the bottom-right corner.
 *
 * Layout (proportional):
 * ```
 * ┌─────────────────────────────┐
 * │       REPUBLIC OF KENYA     │
 * │          SURVEY PLAN        │
 * │─────────────────────────────│
 * │  LR No:       209/3344     │
 * │  Project:     Metardu P2    │
 * │  Surveyor:    J. Mwangi     │
 * │  ISK No:      2847          │
 * │  Client:      Kenya Rail    │
 * │  County:      Nairobi       │
 * │  Scale:       1:1000        │
 * │  Date:        15 Jan 2025   │
 * │─────────────────────────────│
 * │  Drawing No: DWG-001        │
 * │  Sheet:       1 of 1        │
 * └─────────────────────────────┘
 * ```
 */
function drawTitleBlock(
  ctx: CanvasRenderingContext2D,
  opts: DeedPlanExportOptions,
  cw: number,
  ch: number,
  dpi: number,
): void {
  const outer = mmToPx(OUTER_BORDER_MM, dpi);
  const tbW = Math.round(cw * 0.28);
  const tbH = Math.round(ch * 0.46);
  const x = cw - tbW - outer;
  const y = ch - tbH - outer;

  // ── White background ────────────────────────────────────────────────────
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(x, y, tbW, tbH);

  // ── Outer frame ─────────────────────────────────────────────────────────
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = mmToPx(0.5, dpi);
  ctx.strokeRect(x, y, tbW, tbH);

  // ── Font sizes ──────────────────────────────────────────────────────────
  const headerFont = `bold ${ptToPx(16, dpi)}px "Arial", "Helvetica", sans-serif`;
  const subFont    = `bold ${ptToPx(12, dpi)}px "Arial", "Helvetica", sans-serif`;
  const labelFont  = `${ptToPx(9, dpi)}px "Arial", "Helvetica", sans-serif`;
  const valueFont  = `bold ${ptToPx(10, dpi)}px "Arial", "Helvetica", sans-serif`;

  const pad = mmToPx(4, dpi);
  const rowH = ptToPx(15, dpi);

  // ── "REPUBLIC OF KENYA" ─────────────────────────────────────────────────
  let cy = y + pad + ptToPx(16, dpi);
  ctx.fillStyle = '#000000';
  ctx.font = headerFont;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('REPUBLIC OF KENYA', x + tbW / 2, cy);

  // ── "SURVEY PLAN" ───────────────────────────────────────────────────────
  cy += rowH + ptToPx(2, dpi);
  ctx.font = subFont;
  ctx.fillText('SURVEY PLAN', x + tbW / 2, cy);

  // ── Divider ─────────────────────────────────────────────────────────────
  cy += rowH;
  const divL = x + pad;
  const divR = x + tbW - pad;
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = mmToPx(0.3, dpi);
  ctx.beginPath();
  ctx.moveTo(divL, cy);
  ctx.lineTo(divR, cy);
  ctx.stroke();
  cy += rowH;

  // ── Info rows ───────────────────────────────────────────────────────────
  const labelX = x + pad;
  const valueX = x + tbW - pad;

  const rows: Array<[string, string]> = [
    ['LR No:',     opts.lrNumber ?? ''],
    ['Project:',   opts.projectName ?? ''],
    ['Surveyor:',  opts.surveyorName ?? ''],
    ['ISK No:',    opts.surveyorLicense ?? ''],
    ['Client:',    opts.clientName ?? ''],
    ['County:',    opts.county ?? ''],
    ['Scale:',     `1:${opts.scale}`],
    ['Date:',      getFormattedDate()],
  ];

  for (const [label, value] of rows) {
    ctx.font = labelFont;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, labelX, cy);

    ctx.font = valueFont;
    ctx.textAlign = 'right';
    ctx.fillText(value, valueX, cy);

    cy += rowH;
  }

  // ── Second divider ──────────────────────────────────────────────────────
  ctx.beginPath();
  ctx.moveTo(divL, cy);
  ctx.lineTo(divR, cy);
  ctx.stroke();
  cy += rowH;

  // ── Drawing / sheet info ────────────────────────────────────────────────
  const dwgNo = opts.projectName
    ? `${opts.projectName.replace(/\s+/g, '-')}-001`
    : 'DWG-001';

  const footerRows: Array<[string, string]> = [
    ['Drawing No:', dwgNo],
    ['Sheet:',      '1 of 1'],
  ];

  for (const [label, value] of footerRows) {
    ctx.font = labelFont;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, labelX, cy);

    ctx.font = valueFont;
    ctx.textAlign = 'right';
    ctx.fillText(value, valueX, cy);

    cy += rowH;
  }
}

// ---------------------------------------------------------------------------
// Overlay: North Arrow
// ---------------------------------------------------------------------------

/**
 * Draw a north arrow centred at `(cx, cy)`.
 *
 * The arrow points to true north in the map's projection.  Pass the negative
 * of `view.getRotation()` so that the arrow compensates for any map rotation.
 *
 * @param size     - Total height of the arrow in pixels.
 * @param rotation - Rotation to apply (radians, canvas convention: +cw).
 */
function drawNorthArrow(
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  size: number,
  rotation: number,
): void {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(rotation);

  const half = size / 2;
  const arrowW = size * 0.25;

  // ── Filled arrow body ───────────────────────────────────────────────────
  ctx.fillStyle = '#000000';
  ctx.beginPath();
  ctx.moveTo(0, -half);                    // tip (north)
  ctx.lineTo(arrowW, half * 0.3);          // bottom-right
  ctx.lineTo(0, half * 0.05);              // centre notch
  ctx.lineTo(-arrowW, half * 0.3);         // bottom-left
  ctx.closePath();
  ctx.fill();

  // ── Half-circle at base ─────────────────────────────────────────────────
  ctx.beginPath();
  ctx.arc(0, half * 0.18, size * 0.045, 0, Math.PI * 2);
  ctx.fill();

  // ── "N" label above tip ─────────────────────────────────────────────────
  const fontSize = Math.round(size * 0.28);
  ctx.font = `bold ${fontSize}px "Arial", "Helvetica", sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'bottom';
  ctx.fillText('N', 0, -half - size * 0.06);

  ctx.restore();
}

// ---------------------------------------------------------------------------
// Overlay: Scale Bar
// ---------------------------------------------------------------------------

/**
 * Draw a calibrated, alternating-fill scale bar.
 *
 * A "nice" ground distance is chosen so that the bar fits within `maxWidth`.
 * The bar is divided into four sections, each half-filled.
 *
 * @param cx       - Centre X of the bar.
 * @param y        - Top Y of the bar.
 * @param scale    - Scale denominator.
 * @param dpi      - Output DPI.
 * @param maxWidth - Maximum allowed width in pixels.
 */
function drawScaleBar(
  ctx: CanvasRenderingContext2D,
  cx: number,
  y: number,
  scale: number,
  dpi: number,
  maxWidth: number,
): void {
  const mPerPx = calculateResolution(scale, dpi);

  // Pick a nice total ground distance that fits
  const maxM = maxWidth * mPerPx;
  const interval = niceGridInterval(maxM, 4);

  const divisions = 4;
  const divM = interval / divisions;
  const divPx = divM / mPerPx;
  const totalPx = interval / mPerPx;

  const barX = cx - totalPx / 2;
  const barH = Math.max(mmToPx(2.5, dpi), 8);
  const fontSize = Math.max(ptToPx(8, dpi), 10);
  const gap = mmToPx(1, dpi);

  ctx.lineWidth = 1;

  // ── Alternating filled / empty divisions ─────────────────────────────────
  for (let i = 0; i < divisions; i++) {
    const dx = barX + i * divPx;
    ctx.fillStyle = i % 2 === 0 ? '#000000' : '#FFFFFF';
    ctx.fillRect(dx, y, divPx, barH);
    ctx.strokeStyle = '#000000';
    ctx.strokeRect(dx, y, divPx, barH);
  }

  // ── Overall border ──────────────────────────────────────────────────────
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(barX, y, totalPx, barH);

  // ── Tick labels below ───────────────────────────────────────────────────
  ctx.fillStyle = '#000000';
  ctx.font = `${fontSize}px "Arial", "Helvetica", sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  for (let i = 0; i <= divisions; i++) {
    const tx = barX + i * divPx;
    const m = i * divM;
    const label = m >= 1000
      ? `${(m / 1000).toFixed(m % 1000 === 0 ? 0 : 1)} km`
      : `${m.toFixed(0)} m`;
    ctx.fillText(label, tx, y + barH + gap);
  }
}

// ---------------------------------------------------------------------------
// Overlay: Grid Ticks
// ---------------------------------------------------------------------------

/**
 * Draw E (easting) and N (northing) tick labels along the four edges of the
 * drawing area.
 *
 * Grid intervals are "nice" round numbers chosen from the map extent.
 *
 * @param extent   - `[minX, minY, maxX, maxY]` in map projection units (m).
 * @param cw       - Total canvas width in px.
 * @param ch       - Total canvas height in px.
 * @param insetPx  - Inset from canvas edge (outer border + margin) in px.
 * @param dpi      - Output DPI.
 */
function drawGridTicks(
  ctx: CanvasRenderingContext2D,
  extent: [number, number, number, number],
  cw: number,
  ch: number,
  insetPx: number,
  dpi: number,
): void {
  const [minX, minY, maxX, maxY] = extent;
  const extW = maxX - minX;
  const extH = maxY - minY;
  if (extW <= 0 || extH <= 0) return;

  const interval = niceGridInterval(Math.max(extW, extH), 8);

  // Drawing-area boundaries
  const left = insetPx;
  const top  = insetPx;
  const right  = cw - insetPx;
  const bottom = ch - insetPx;
  const mapW = right - left;
  const mapH = bottom - top;

  const tickLen = mmToPx(5, dpi);
  const fontSize = Math.max(ptToPx(7, dpi), 9);

  ctx.fillStyle = '#000000';
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = 0.8;
  ctx.font = `${fontSize}px "Arial", "Helvetica", sans-serif`;

  // ── Vertical ticks (constant easting) ───────────────────────────────────
  const startX = Math.ceil(minX / interval) * interval;
  for (let e = startX; e <= maxX; e += interval) {
    const px = left + ((e - minX) / extW) * mapW;
    if (px < left - 1 || px > right + 1) continue;

    const label = formatCoord(e);

    // Bottom tick + label
    ctx.beginPath();
    ctx.moveTo(px, bottom);
    ctx.lineTo(px, bottom + tickLen);
    ctx.stroke();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillText(label, px, bottom + tickLen + 1);

    // Top tick + label
    ctx.beginPath();
    ctx.moveTo(px, top);
    ctx.lineTo(px, top - tickLen);
    ctx.stroke();
    ctx.textBaseline = 'bottom';
    ctx.fillText(label, px, top - tickLen - 1);
  }

  // ── Horizontal ticks (constant northing) ────────────────────────────────
  const startY = Math.ceil(minY / interval) * interval;
  for (let n = startY; n <= maxY; n += interval) {
    const py = bottom - ((n - minY) / extH) * mapH;
    if (py < top - 1 || py > bottom + 1) continue;

    const label = formatCoord(n);

    // Left tick + label
    ctx.beginPath();
    ctx.moveTo(left, py);
    ctx.lineTo(left - tickLen, py);
    ctx.stroke();
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, left - tickLen - 2, py);

    // Right tick + label
    ctx.beginPath();
    ctx.moveTo(right, py);
    ctx.lineTo(right + tickLen, py);
    ctx.stroke();
    ctx.textAlign = 'left';
    ctx.fillText(label, right + tickLen + 2, py);
  }
}

// ---------------------------------------------------------------------------
// Core: exportDeedPlan
// ---------------------------------------------------------------------------

/**
 * Export the current map view as a print-quality deed-plan PNG blob.
 *
 * The function temporarily resizes the map to the target paper dimensions at
 * the requested DPI, adjusts the view resolution to match the exact scale, and
 * composites SoK-compliant overlays (title block, north arrow, scale bar, grid
 * ticks) directly onto the output canvas.
 *
 * **The original map state (centre, resolution, rotation, size, pixel ratio)
 * is always restored**, even if the export fails or times out.
 *
 * @param options - Full export configuration.
 * @returns A `Blob` containing the PNG image data.
 *
 * @example
 * ```ts
 * const blob = await exportDeedPlan({
 *   map,
 *   scale: 1000,
 *   paperSize: 'a3',
 *   orientation: 'landscape',
 *   dpi: 300,
 *   lrNumber: '209/3344',
 *   projectName: 'Moi Avenue Phase 2',
 *   surveyorName: 'J. Mwangi',
 *   surveyorLicense: '2847',
 *   clientName: 'Nairobi County',
 *   county: 'Nairobi',
 * });
 * ```
 */
export async function exportDeedPlan(options: DeedPlanExportOptions): Promise<Blob> {
  const {
    map,
    scale,
    paperSize,
    orientation,
    dpi = 300,
    includeNorthArrow = true,
    includeScaleBar  = true,
    includeGridTicks = true,
    includeTitleBlock = true,
  } = options;

  // ── Validate ────────────────────────────────────────────────────────────
  if (!PAPER_SIZES_MM[paperSize]) {
    throw new Error(
      `Unsupported paper size: "${paperSize}". ` +
      `Supported: ${Object.keys(PAPER_SIZES_MM).join(', ')}`,
    );
  }
  if (scale <= 0) {
    throw new Error(`Invalid scale: ${scale}. Must be a positive number.`);
  }

  // ── Compute pixel dimensions & resolution ───────────────────────────────
  const [paperWmm, paperHmm] = getPaperDimensions(paperSize, orientation);
  const targetW = Math.round(mmToPx(paperWmm, dpi));
  const targetH = Math.round(mmToPx(paperHmm, dpi));
  const targetRes = calculateResolution(scale, dpi);

  // ── Save original map state ─────────────────────────────────────────────
  const origSize = map.getSize();
  const origCenter = map.getView().getCenter();
  const origRes = map.getView().getResolution();
  const origRot = map.getView().getRotation();

  // Temporarily override getPixelRatio so OL renders at 1:1 (native pixels).
  // This ensures internal canvases are sized exactly to our target dimensions
  // without an additional device-pixel-ratio multiplier.
  // eslint-disable-next-line
  const mapAny = map as any;
  const origGetPixelRatio: () => number = mapAny.getPixelRatio;
  mapAny.getPixelRatio = () => 1;

  // ── Build the Promise that resolves after rendering ─────────────────────
  return new Promise<Blob>((resolve, reject) => {
    let settled = false;

    const timeoutId = setTimeout(() => {
      if (!settled) { settled = true; restore(); reject(new Error('Deed plan export timed out.')); }
    }, RENDER_TIMEOUT_MS);

    /**
     * Restore the map to its pre-export state.
     * Safe to call multiple times (idempotent).
     */
    function restore(): void {
      clearTimeout(timeoutId);
      mapAny.getPixelRatio = origGetPixelRatio;
      if (origSize) map.setSize(origSize);
      const view = map.getView();
      if (origCenter) view.setCenter(origCenter);
      if (origRes != null) view.setResolution(origRes);
      view.setRotation(origRot);
    }

    // ── Listen for render completion ───────────────────────────────────────
    map.once('rendercomplete', () => {
      if (settled) return; // timeout already fired
      settled = true;

      try {
        // Create the output canvas
        const canvas = document.createElement('canvas');
        canvas.width  = targetW;
        canvas.height = targetH;
        const ctx = canvas.getContext('2d');
        if (!ctx) { restore(); reject(new Error('Failed to acquire 2-D context.')); return; }

        // White background
        ctx.fillStyle = '#FFFFFF';
        ctx.fillRect(0, 0, targetW, targetH);

        // ── Composite layer canvases ───────────────────────────────────────
        const viewport = map.getViewport();
        const layerCanvases = viewport.querySelectorAll(
          '.ol-layer canvas, canvas.ol-layer',
        );

        for (let i = 0; i < layerCanvases.length; i++) {
          const lc = layerCanvases[i] as HTMLCanvasElement;
          if (!lc || lc.width === 0 || lc.height === 0) continue;

          // Layer / parent opacity
          const opStr = lc.style.opacity
            || (lc.parentElement && lc.parentElement.style.opacity)
            || '1';
          const op = parseFloat(opStr);
          if (isNaN(op)) continue;

          ctx.globalAlpha = op;
          ctx.setTransform(1, 0, 0, 1, 0, 0); // identity — draw at native px

          // Draw at native pixel resolution; scale preserving aspect ratio when dims differ
          if (lc.width === targetW && lc.height === targetH) {
            ctx.drawImage(lc, 0, 0);
          } else {
            // Preserve aspect ratio to prevent distortion
            const scaleX = targetW / lc.width;
            const scaleY = targetH / lc.height;
            const drawScale = Math.min(scaleX, scaleY);
            const dw = lc.width * drawScale;
            const dh = lc.height * drawScale;
            const dx = (targetW - dw) / 2;
            const dy = (targetH - dh) / 2;
            ctx.drawImage(lc, dx, dy, dw, dh);
          }
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.globalAlpha = 1;

        // ── Draw overlays ──────────────────────────────────────────────────
        const outerPx = mmToPx(OUTER_BORDER_MM, dpi);
        const marginPx = mmToPx(MARGIN_MM, dpi);
        const inset = outerPx + marginPx;

        // 1. Border frame
        drawBorder(ctx, targetW, targetH, dpi);

        // 2. Grid ticks (drawn first so title block can overlap them)
        if (includeGridTicks) {
          const extent = map.getView().calculateExtent(
            [targetW, targetH],
          ) as [number, number, number, number];
          drawGridTicks(ctx, extent, targetW, targetH, inset, dpi);
        }

        // 3. Title block — bottom-right
        if (includeTitleBlock) {
          drawTitleBlock(ctx, options, targetW, targetH, dpi);
        }

        // 4. North arrow — upper-right area (above the title block)
        if (includeNorthArrow) {
          const tbW = includeTitleBlock ? Math.round(targetW * 0.28) : 0;
          const arrowSize = Math.min(targetW * 0.055, targetH * 0.08);
          // Centre the arrow horizontally within the title-block column
          const arrowCx = targetW - outerPx - tbW / 2;
          const arrowCy = inset + arrowSize * 0.7;

          drawNorthArrow(ctx, arrowCx, arrowCy, arrowSize, -(origRot ?? 0));
        }

        // 5. Scale bar — bottom-centre (left of title block)
        if (includeScaleBar) {
          const tbW = includeTitleBlock ? Math.round(targetW * 0.28) : 0;
          const barMaxW = targetW - tbW - 2 * inset;
          const barCx = inset + barMaxW / 2;
          const barY = targetH - inset - mmToPx(14, dpi);

          drawScaleBar(ctx, barCx, barY, scale, dpi, barMaxW);
        }

        // ── Convert to PNG Blob ────────────────────────────────────────────
        canvas.toBlob(
          (blob: Blob | null) => {
            restore();
            if (blob) resolve(blob);
            else reject(new Error('Canvas toBlob returned null.'));
          },
          'image/png',
        );
      } catch (err) {
        restore();
        reject(err);
      }
    });

    // ── Apply export parameters & trigger render ──────────────────────────
    map.setSize([targetW, targetH]);
    map.getView().setResolution(targetRes);
  });
}

// ---------------------------------------------------------------------------
// Core: downloadDeedPlan
// ---------------------------------------------------------------------------

/**
 * Export a deed plan and immediately trigger a browser download of the PNG.
 *
 * This is a convenience wrapper around {@link exportDeedPlan} that creates a
 * temporary `<a>` element with a `blob:` URL and programmatically clicks it.
 *
 * @param options  - Export configuration (see {@link DeedPlanExportOptions}).
 * @param filename - Download filename (default `'deed-plan.png'`).
 *
 * @example
 * ```ts
 * await downloadDeedPlan(
 *   {
 *     map,
 *     scale: 1000,
 *     paperSize: 'a3',
 *     orientation: 'landscape',
 *     lrNumber: '209/3344',
 *   },
 *   'LR209-3344-deed-plan.png',
 * );
 * ```
 */
export async function downloadDeedPlan(
  options: DeedPlanExportOptions,
  filename: string = 'deed-plan.png',
): Promise<void> {
  const blob = await exportDeedPlan(options);

  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.style.display = 'none';

  document.body.appendChild(anchor);
  anchor.click();

  // Cleanup after a short delay to ensure the download starts
  setTimeout(() => {
    document.body.removeChild(anchor);
    URL.revokeObjectURL(url);
  }, 200);
}

/**
 * Editing Tools — real geometry operations for Split, Merge, Reshape, Rotate, Offset
 *
 * Uses turf.js for the actual math. Each function takes coordinate arrays
 * (in a planar UTM CRS, e.g. EPSG:21037) and returns new coordinate arrays.
 * The MapClient digitizing handlers (MapClient.tsx) call these via dynamic
 * import from inside the OL drawend/Apply-button handlers.
 *
 * T0.6 FIX (2026-07-09): The floating DigitizingToolbar.tsx that previously
 * called these has been deleted (it was dead code — zero importers). The
 * live UI is now MapToolDock.tsx's "Advanced" section, which routes through
 * MapClient's activeDrawTool / activeOneShotTool state.
 */

import * as turf from '@turf/turf'
import type { Feature, Polygon as GeoPolygon, MultiPolygon } from 'geojson'

export interface SplitResult {
  polygon1: [number, number][]
  polygon2: [number, number][]
  area1: number
  area2: number
}

/**
 * Split a polygon with a line.
 * Uses turf.lineIntersect + turf.polygonToLine + boolean operations.
 * Returns the two resulting polygons.
 */
export function splitPolygonWithLine(
  polygonCoords: [number, number][],
  lineCoords: [number, number][],
): SplitResult | null {
  try {
    // Ensure closed ring
    const closed = isClosed(polygonCoords) ? polygonCoords : [...polygonCoords, polygonCoords[0]]

    const polygon = turf.polygon([closed.map(([e, n]) => [e, n])])
    const line = turf.lineString(lineCoords.map(([e, n]) => [e, n]))

    // Check if line actually intersects the polygon
    const intersects = turf.lineIntersect(line, polygon)
    if (intersects.features.length < 2) {
      return null // Line must cross the polygon at least twice
    }

    // Get the intersection points
    const intersectionPoints = intersects.features.map(f => {
      const coords = f.geometry.coordinates as [number, number]
      return coords
    })

    if (intersectionPoints.length < 2) return null

    // Create a cutting polygon (a thin sliver rectangle along the extended line).
    const bbox = turf.bbox(polygon)
    const width = bbox[2] - bbox[0]
    const height = bbox[3] - bbox[1]
    const margin = Math.max(width, height) * 2

    const lineStart = lineCoords[0] as [number, number]
    const lineEnd = lineCoords[lineCoords.length - 1] as [number, number]

    const dx = lineEnd[0] - lineStart[0]
    const dy = lineEnd[1] - lineStart[1]
    const len = Math.sqrt(dx * dx + dy * dy)
    if (len === 0) return null

    const ux = dx / len
    const uy = dy / len

    const extendedStart: [number, number] = [
      lineStart[0] - ux * margin,
      lineStart[1] - uy * margin,
    ]
    const extendedEnd: [number, number] = [
      lineEnd[0] + ux * margin,
      lineEnd[1] + uy * margin,
    ]

    const perpX = -uy
    const perpY = ux
    const halfWidth = 0.001

    const cutPolygon = turf.polygon([[
      [extendedStart[0] + perpX * halfWidth, extendedStart[1] + perpY * halfWidth],
      [extendedEnd[0] + perpX * halfWidth, extendedEnd[1] + perpY * halfWidth],
      [extendedEnd[0] - perpX * halfWidth, extendedEnd[1] - perpY * halfWidth],
      [extendedStart[0] - perpX * halfWidth, extendedStart[1] - perpY * halfWidth],
      [extendedStart[0] + perpX * halfWidth, extendedStart[1] + perpY * halfWidth],
    ]])

    const diff = turf.difference(turf.featureCollection([polygon, cutPolygon]))

    if (!diff || !diff.geometry) return null

    const diffGeom = diff.geometry
    if (diffGeom.type === 'Polygon') {
      return null
    }
    if (diffGeom.type === 'MultiPolygon') {
      const polys = diffGeom.coordinates as number[][][][]
      if (polys.length < 2) return null
      const p1Coords = polys[0][0] as [number, number][]
      const p2Coords = polys[1][0] as [number, number][]

      return {
        polygon1: p1Coords,
        polygon2: p2Coords,
        area1: turf.area(turf.polygon([p1Coords])),
        area2: turf.area(turf.polygon([p2Coords])),
      }
    }

    return null
  } catch (err) {
    console.error('[editingTools] splitPolygonWithLine failed:', err)
    return null
  }
}

/**
 * Merge two or more polygons into one using turf.union.
 */
export function mergePolygons(
  polygons: [number, number][][],
): [number, number][] | null {
  if (polygons.length < 2) return null

  try {
    let result = turf.polygon([ensureClosed(polygons[0])]) as Feature<GeoPolygon>

    for (let i = 1; i < polygons.length; i++) {
      const next = turf.polygon([ensureClosed(polygons[i])])
      const union = turf.union(turf.featureCollection([result, next]))
      if (union && union.geometry?.type === 'Polygon') {
        result = turf.polygon((union.geometry as GeoPolygon).coordinates) as Feature<GeoPolygon>
      } else if (union && union.geometry?.type === 'MultiPolygon') {
        return null
      }
    }

    return (result.geometry as GeoPolygon).coordinates[0] as [number, number][]
  } catch (err) {
    console.error('[editingTools] mergePolygons failed:', err)
    return null
  }
}

/**
 * Rotate a polygon around its centroid by a given angle (degrees).
 *
 * T0.2 FIX (2026-07-09): Previously delegated to turf.transformRotate, which
 * throws "coordinates must contain numbers" on certain polygon shapes (e.g.
 * L-shapes, concave rings) — the silent catch returned the input unchanged,
 * meaning rotation quietly no-op'd for anything but simple squares. The
 * hardcoded `15` in the old MapClient handler hid this bug for months.
 *
 * Now we do the 2D rotation manually: compute the centroid, then apply the
 * standard rotation matrix to each vertex. This is O(n), CRS-agnostic, and
 * has no turf dependency.
 */
export function rotatePolygon(
  coords: [number, number][],
  angleDeg: number,
): [number, number][] {
  if (coords.length === 0) return coords
  try {
    const closed = ensureClosed(coords)
    let cx = 0, cy = 0
    const n = closed.length - 1
    for (let i = 0; i < n; i++) {
      cx += closed[i][0]
      cy += closed[i][1]
    }
    cx /= n
    cy /= n

    const rad = (angleDeg * Math.PI) / 180
    const cos = Math.cos(rad)
    const sin = Math.sin(rad)

    const rotated: [number, number][] = closed.map(([x, y]) => [
      cx + (x - cx) * cos - (y - cy) * sin,
      cy + (x - cx) * sin + (y - cy) * cos,
    ])
    return rotated
  } catch (err) {
    console.error('[editingTools] rotatePolygon failed:', err)
    return coords
  }
}

/**
 * Create a parallel offset of a line or polygon boundary.
 * Uses turf.lineOffset for lines, or buffers for polygons.
 */
export function createOffset(
  coords: [number, number][],
  distance: number,
  isPolygon: boolean = false,
): [number, number][] | null {
  try {
    const closed = ensureClosed(coords)

    if (isPolygon) {
      const polygon = turf.polygon([closed])
      const buffered = turf.buffer(polygon, distance, { units: 'meters' })
      if (buffered?.geometry?.type === 'Polygon') {
        return (buffered.geometry as GeoPolygon).coordinates[0] as [number, number][]
      }
    } else {
      const line = turf.lineString(closed)
      const offset = turf.lineOffset(line, distance, { units: 'meters' })
      return offset.geometry.coordinates as [number, number][]
    }
  } catch (err) {
    console.error('[editingTools] createOffset failed:', err)
  }
  return null
}

/**
 * Reshape: replace part of a polygon boundary with a new line segment.
 */
export function reshapePolygon(
  polygonCoords: [number, number][],
  newSegmentCoords: [number, number][],
): [number, number][] | null {
  try {
    const closed = ensureClosed(polygonCoords)
    const newLine = turf.lineString(newSegmentCoords)
    const polyBoundary = turf.lineString(closed)
    const ixns = turf.lineIntersect(newLine, polyBoundary)

    if (ixns.features.length < 2) {
      const splitResult = splitPolygonWithLine(closed, newSegmentCoords)
      if (!splitResult) return null
      const area0 = turf.area(turf.polygon([ensureClosed(splitResult.polygon1)])) ?? 0
      const area1 = turf.area(turf.polygon([ensureClosed(splitResult.polygon2)])) ?? 0
      return area0 > area1 ? splitResult.polygon1 : splitResult.polygon2
    }

    const pt0 = ixns.features[0].geometry.coordinates as [number, number]
    const pt1 = ixns.features[1].geometry.coordinates as [number, number]

    let idx0 = 0
    let idx1 = 0
    let minD0 = Infinity
    let minD1 = Infinity

    for (let i = 0; i < closed.length; i++) {
      const d0 = squaredDistance(closed[i], pt0)
      const d1 = squaredDistance(closed[i], pt1)
      if (d0 < minD0) { minD0 = d0; idx0 = i }
      if (d1 < minD1) { minD1 = d1; idx1 = i }
    }

    const result: [number, number][] = []
    const start = Math.min(idx0, idx1)
    const end = Math.max(idx0, idx1)

    for (let i = 0; i <= start; i++) {
      result.push([...closed[i]])
    }
    for (const pt of newSegmentCoords) {
      result.push([...pt])
    }
    for (let i = end; i < closed.length; i++) {
      result.push([...closed[i]])
    }

    return result
  } catch {
    return null
  }
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function isClosed(coords: [number, number][]): boolean {
  if (coords.length < 2) return false
  const first = coords[0]
  const last = coords[coords.length - 1]
  return first[0] === last[0] && first[1] === last[1]
}

function ensureClosed(coords: [number, number][]): [number, number][] {
  if (isClosed(coords)) return coords
  return [...coords, coords[0]]
}

function squaredDistance(a: [number, number], b: [number, number]): number {
  const dx = a[0] - b[0]
  const dy = a[1] - b[1]
  return dx * dx + dy * dy
}

/**
 * @module enhancedMapStyles
 *
 * Enhanced vector styling for OpenLayers map rendering.
 *
 * Improves map output quality with:
 * 1. Proper line weights per SoK standards (scaled by zoom)
 * 2. Text placements that don't overlap
 * 3. Bearing/distance annotations on parcel edges
 * 4. Beacon symbols per Kenya beacon types
 * 5. Color-coded parcel status (registered, pending, disputed)
 * 6. Grid overlay with coordinate labels
 * 7. Scale-dependent styling (details appear at higher zoom)
 */

import Style from 'ol/style/Style'
import Fill from 'ol/style/Fill'
import Stroke from 'ol/style/Stroke'
import Text from 'ol/style/Text'
import Circle from 'ol/style/Circle'
import Icon from 'ol/style/Icon'
import type { Feature } from 'ol'
import type { Geometry } from 'ol/geom'

// ---------------------------------------------------------------------------
// Color Palette (SoK compliant)
// ---------------------------------------------------------------------------

export const SOK_COLORS = {
  // Boundaries
  parcelBoundary: '#1a1a1a',       // near-black
  schemeBoundary: '#000000',       // pure black
  subdivisionBoundary: '#333333',  // dark gray
  roadReserve: '#ff6600',          // orange (Kenya road reserve)

  // Parcels by status
  parcelRegistered: '#2d5016',     // dark green
  parcelPending: '#996600',        // amber
  parcelDisputed: '#cc0000',       // red
  parcelCancelled: '#666666',      // gray

  // Beacons
  beaconConcrete: '#000000',
  beaconIronPin: '#0066cc',
  beaconStone: '#996633',
  beaconPipe: '#666666',

  // Features
  water: '#0066cc',
  vegetation: '#2d5016',
  building: '#cc6600',
  contour: '#996600',

  // Grid
  gridMajor: '#cccccc',
  gridMinor: '#e6e6e6',

  // Background
  mapBackground: '#ffffff',
} as const

// ---------------------------------------------------------------------------
// Line Width Calculator (zoom-dependent)
// ---------------------------------------------------------------------------

/**
 * Calculate the appropriate line width based on map resolution.
 * At high zoom (low resolution), lines are thicker for visibility.
 * At low zoom (high resolution), lines are thinner to avoid clutter.
 */
export function getLineWidth(baseWidthMm: number, resolution: number): number {
  // Convert mm to pixels at 96 DPI (1mm ≈ 3.78px)
  const baseWidthPx = baseWidthMm * 3.78

  // Scale factor based on resolution
  // resolution is in meters per pixel
  if (resolution < 0.5) return baseWidthPx * 1.5  // very high zoom
  if (resolution < 2) return baseWidthPx           // high zoom
  if (resolution < 10) return baseWidthPx * 0.8    // medium zoom
  if (resolution < 50) return baseWidthPx * 0.6    // low zoom
  return baseWidthPx * 0.4                          // very low zoom
}

// ---------------------------------------------------------------------------
// Parcel Style (with status-based coloring)
// ---------------------------------------------------------------------------

export interface ParcelStyleOptions {
  status?: 'registered' | 'pending' | 'disputed' | 'cancelled'
  isSelected?: boolean
  showLabel?: boolean
  label?: string
  resolution?: number
}

export function createParcelStyle(options: ParcelStyleOptions = {}): Style {
  const {
    status = 'registered',
    isSelected = false,
    showLabel = true,
    label,
    resolution = 10,
  } = options

  const fillColor = SOK_COLORS[`parcel${status.charAt(0).toUpperCase() + status.slice(1)}` as keyof typeof SOK_COLORS] || SOK_COLORS.parcelRegistered
  const lineWidth = getLineWidth(0.3, resolution)

  return new Style({
    stroke: new Stroke({
      color: isSelected ? '#D17B47' : SOK_COLORS.parcelBoundary,
      width: isSelected ? lineWidth * 2 : lineWidth,
      lineCap: 'round',
      lineJoin: 'round',
    }),
    fill: new Fill({
      color: isSelected ? 'rgba(209, 123, 71, 0.15)' : fillColor + '20', // 20 = 12% opacity
    }),
    text: showLabel && label ? new Text({
      text: label,
      font: 'bold 12px Helvetica',
      fill: new Fill({ color: '#000000' }),
      stroke: new Stroke({ color: '#ffffff', width: 3 }),
      overflow: true,
      placement: 'point',
    }) : undefined,
  })
}

// ---------------------------------------------------------------------------
// Beacon Style (by type)
// ---------------------------------------------------------------------------

export interface BeaconStyleOptions {
  type?: 'concrete' | 'iron_pin' | 'stone' | 'pipe' | 'reference_object'
  isSelected?: boolean
  showLabel?: boolean
  label?: string
  resolution?: number
}

export function createBeaconStyle(options: BeaconStyleOptions = {}): Style {
  const {
    type = 'concrete',
    isSelected = false,
    showLabel = true,
    label,
    resolution = 10,
  } = options

  const color = SOK_COLORS[`beacon${type.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join('')}` as keyof typeof SOK_COLORS] || SOK_COLORS.beaconConcrete
  const radius = resolution < 2 ? 6 : resolution < 10 ? 4 : 3

  return new Style({
    image: new Circle({
      radius: isSelected ? radius + 2 : radius,
      fill: new Fill({ color: color }),
      stroke: new Stroke({
        color: isSelected ? '#D17B47' : '#ffffff',
        width: isSelected ? 3 : 2,
      }),
    }),
    text: showLabel && label ? new Text({
      text: label,
      font: 'bold 10px Courier',
      fill: new Fill({ color: '#000000' }),
      stroke: new Stroke({ color: '#ffffff', width: 3 }),
      offsetX: 8,
      offsetY: -8,
      textAlign: 'left',
    }) : undefined,
  })
}

// ---------------------------------------------------------------------------
// Bearing Annotation Style
// ---------------------------------------------------------------------------

export interface BearingAnnotationOptions {
  bearing: string    // formatted DMS
  distance?: string  // formatted distance
  resolution?: number
}

/**
 * Create a style for bearing/distance annotations on line features.
 * Text is placed along the line, upright (not rotated with line).
 */
export function createBearingAnnotationStyle(options: BearingAnnotationOptions): Style {
  const { bearing, distance, resolution = 10 } = options
  const fontSize = resolution < 2 ? 14 : resolution < 10 ? 12 : 10

  let text = bearing
  if (distance) text += `\n${distance}`

  return new Style({
    text: new Text({
      text: text,
      font: `${fontSize}px Courier`,
      fill: new Fill({ color: '#000000' }),
      stroke: new Stroke({ color: '#ffffff', width: 3 }),
      overflow: true,
      placement: 'line',
      textBaseline: 'middle',
      textAlign: 'center',
    }),
  })
}

// ---------------------------------------------------------------------------
// Road Reserve Style (with hatching)
// ---------------------------------------------------------------------------

export function createRoadReserveStyle(resolution: number = 10): Style {
  const lineWidth = getLineWidth(0.4, resolution)
  return new Style({
    stroke: new Stroke({
      color: SOK_COLORS.roadReserve,
      width: lineWidth,
      lineDash: [10, 5],
      lineCap: 'round',
    }),
    fill: new Fill({
      color: 'rgba(255, 102, 0, 0.1)',
    }),
  })
}

// ---------------------------------------------------------------------------
// Grid Style
// ---------------------------------------------------------------------------

export function createGridStyle(isMajor: boolean = true, resolution: number = 10): Style {
  const color = isMajor ? SOK_COLORS.gridMajor : SOK_COLORS.gridMinor
  const baseWidth = isMajor ? 0.2 : 0.1
  const width = getLineWidth(baseWidth, resolution)

  return new Style({
    stroke: new Stroke({
      color: color,
      width: width,
      lineDash: isMajor ? [] : [2, 2],
    }),
  })
}

// ---------------------------------------------------------------------------
// Water Feature Style
// ---------------------------------------------------------------------------

export function createWaterStyle(resolution: number = 10): Style {
  const lineWidth = getLineWidth(0.3, resolution)
  return new Style({
    stroke: new Stroke({
      color: SOK_COLORS.water,
      width: lineWidth,
    }),
    fill: new Fill({
      color: 'rgba(0, 102, 204, 0.3)',
    }),
  })
}

// ---------------------------------------------------------------------------
// Building Style
// ---------------------------------------------------------------------------

export function createBuildingStyle(resolution: number = 10): Style {
  const lineWidth = getLineWidth(0.25, resolution)
  return new Style({
    stroke: new Stroke({
      color: SOK_COLORS.building,
      width: lineWidth,
    }),
    fill: new Fill({
      color: 'rgba(204, 102, 0, 0.4)',
    }),
  })
}

// ---------------------------------------------------------------------------
// Contour Style
// ---------------------------------------------------------------------------

export function createContourStyle(isIndex: boolean = false, resolution: number = 10): Style {
  const color = SOK_COLORS.contour
  const baseWidth = isIndex ? 0.4 : 0.12
  const width = getLineWidth(baseWidth, resolution)

  return new Style({
    stroke: new Stroke({
      color: color,
      width: width,
    }),
  })
}

// ---------------------------------------------------------------------------
// Scale-Dependent Style Selector
// ---------------------------------------------------------------------------

/**
 * Returns the appropriate style for a feature based on:
 * - Feature type (parcel, beacon, line, etc.)
 * - Map resolution (zoom level)
 * - Feature properties (status, type, etc.)
 */
export function getStyleForFeature(feature: Feature<Geometry>, resolution: number): Style | Style[] {
  const geomType = feature.getGeometry()?.getType()
  const props = feature.getProperties()

  switch (geomType) {
    case 'Polygon':
      return createParcelStyle({
        status: props.status || 'registered',
        label: props.parcelNumber || props.name,
        resolution,
      })

    case 'Point':
      return createBeaconStyle({
        type: props.beaconType || 'concrete',
        label: props.beaconNumber || props.name,
        resolution,
      })

    case 'LineString':
      if (props.featureType === 'road_reserve') return createRoadReserveStyle(resolution)
      if (props.featureType === 'contour') return createContourStyle(props.isIndex || false, resolution)
      if (props.featureType === 'water') return createWaterStyle(resolution)
      if (props.featureType === 'building') return createBuildingStyle(resolution)
      return new Style({
        stroke: new Stroke({
          color: SOK_COLORS.parcelBoundary,
          width: getLineWidth(0.3, resolution),
        }),
      })

    default:
      return new Style({})
  }
}

/**
 * METARDU Kenya Grid Overlay
 *
 * Renders a survey grid overlay on the map with:
 * - Grid lines computed in EPSG:21037 (Kenya UTM Zone 37S)
 * - Rendered in EPSG:3857 for display
 * - Tick marks at viewport edges
 * - E/N coordinate labels at intersections
 * - Auto-scaling intervals based on zoom level
 *
 * All OL imports are dynamic to match existing project patterns.
 */

import { to3857 } from '@/lib/map/projection';

/** Grid interval in meters */
export type GridInterval = 100 | 500 | 1000 | 5000 | 'auto';

/** Layer group ID for identification */
export const GRID_LAYER_ID = 'kenya-grid-overlay';

/**
 * Determine the appropriate grid interval based on the map zoom level.
 */
function getAutoInterval(zoom: number): 100 | 500 | 1000 | 5000 {
  if (zoom >= 18) return 100;
  if (zoom >= 15) return 500;
  if (zoom >= 12) return 1000;
  return 5000;
}

/**
 * Snap a value to the nearest grid interval.
 */
function snapToGrid(value: number, interval: number): number {
  return Math.floor(value / interval) * interval;
}

/**
 * Format a coordinate value for display.
 * Removes trailing zeros but keeps at least one decimal.
 */
function formatCoord(value: number, interval: number): string {
  if (interval >= 1000) {
    return value.toFixed(0);
  }
  if (interval >= 500) {
    return value.toFixed(0);
  }
  return value.toFixed(1);
}

/**
 * Create the Kenya grid overlay vector layer.
 * The layer is initially empty — call `updateGridOverlay()` on map `moveend` to refresh.
 */
export async function createGridOverlayLayer(): Promise<import('ol/layer/Vector').default> {
  const [
    { default: VectorLayer },
    { default: VectorSource },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
  ]);

  const source = new VectorSource();
  const layer = new VectorLayer({
    source,
    zIndex: 8,
    visible: false,
  });
  layer.set('layerId', GRID_LAYER_ID);
  return layer;
}

/**
 * Update the grid overlay features based on the current map view.
 *
 * @param map - The OpenLayers map instance
 * @param interval - Grid interval in meters, or 'auto' to select by zoom
 */
export async function updateGridOverlay(
  map: import('ol/Map').default,
  interval: GridInterval = 'auto',
  epsg: string = 'EPSG:21037',
): Promise<void> {
  const { transform } = await import('ol/proj');
  const {
    default: VectorSource,
  } = await import('ol/source/Vector');
  const {
    default: Feature,
  } = await import('ol/Feature');
  const {
    default: LineString,
  } = await import('ol/geom/LineString');
  const {
    default: PointGeom,
  } = await import('ol/geom/Point');
  const {
    default: Style,
  } = await import('ol/style/Style');
  const {
    default: Stroke,
  } = await import('ol/style/Stroke');
  const {
    default: Fill,
  } = await import('ol/style/Fill');
  const {
    default: Text,
  } = await import('ol/style/Text');

  // Find the grid layer
  const layers = map.getLayers().getArray();
  let gridLayer: import('ol/layer/Vector').default | null = null;
  for (const layer of layers) {
    if (layer.get('layerId') === GRID_LAYER_ID) {
      gridLayer = layer as import('ol/layer/Vector').default;
      break;
    }
  }
  if (!gridLayer) return;

  const view = map.getView();
  const extent = view.calculateExtent(map.getSize());
  const zoom = view.getZoom() ?? 16;

  const resolvedInterval: number = interval === 'auto' ? getAutoInterval(zoom) : interval;

  // Convert extent corners from EPSG:3857 to UTM
  const bottomLeft3857: [number, number] = [extent[0], extent[1]];
  const topRight3857: [number, number] = [extent[2], extent[3]];

  const bottomLeft21037 = transform(bottomLeft3857, 'EPSG:3857', epsg) as [number, number];
  const topRight21037 = transform(topRight3857, 'EPSG:3857', epsg) as [number, number];

  const minE = bottomLeft21037[0];
  const maxE = topRight21037[0];
  const minN = bottomLeft21037[1];
  const maxN = topRight21037[1];

  // Snap to grid boundaries (add one interval padding)
  const startE = snapToGrid(minE, resolvedInterval) - resolvedInterval;
  const endE = snapToGrid(maxE, resolvedInterval) + resolvedInterval;
  const startN = snapToGrid(minN, resolvedInterval) - resolvedInterval;
  const endN = snapToGrid(maxN, resolvedInterval) + resolvedInterval;

  const features: InstanceType<typeof Feature>[] = [];

  // Grid line style
  const gridLineStyle = new Style({
    stroke: new Stroke({
      color: 'rgba(100, 100, 100, 0.25)',
      width: 1,
    }),
  });

  // Sub-grid (thinner) style for intervals > 100m
  const subGridLineStyle = new Style({
    stroke: new Stroke({
      color: 'rgba(150, 150, 150, 0.12)',
      width: 0.5,
    }),
  });

  // Tick mark style (short perpendicular lines at edges)
  const tickMarkStyle = new Style({
    stroke: new Stroke({
      color: 'rgba(27, 58, 92, 0.7)',
      width: 1.5,
    }),
  });

  // Label style
  const labelStyle = new Style({
    text: new Text({
      font: '10px Calibri, sans-serif',
      fill: new Fill({ color: '#1B3A5C' }),
      stroke: new Stroke({ color: '#FFFFFF', width: 3 }),
      padding: [2, 2, 2, 2],
    }),
  });

  const tickLength = (maxE - minE) * 0.012; // ~1.2% of viewport width

  // ─── Vertical grid lines (constant Easting) ─────────────────────────────
  for (let e = startE; e <= endE; e += resolvedInterval) {
    const top3857 = await to3857(e, endN);
    const bottom3857 = await to3857(e, startN);

    const lineFeature = new Feature({
      geometry: new LineString([bottom3857, top3857]),
      type: 'grid-line',
    });
    lineFeature.setStyle(gridLineStyle);
    features.push(lineFeature);

    // Add sub-grid lines at half intervals
    if (resolvedInterval >= 1000) {
      const halfInterval = resolvedInterval / 2;
      const subE = e + halfInterval;
      if (subE <= endE) {
        const subTop3857 = await to3857(subE, endN);
        const subBottom3857 = await to3857(subE, startN);
        const subFeature = new Feature({
          geometry: new LineString([subBottom3857, subTop3857]),
          type: 'sub-grid-line',
        });
        subFeature.setStyle(subGridLineStyle);
        features.push(subFeature);
      }
    }

    // ─── Tick marks at bottom edge ──────────────────────────────────────
    const tickBottomStart = await to3857(e - tickLength, minN);
    const tickBottomEnd = await to3857(e + tickLength, minN);
    const tickBottom = new Feature({
      geometry: new LineString([tickBottomStart, tickBottomEnd]),
      type: 'tick-mark',
    });
    tickBottom.setStyle(tickMarkStyle);
    features.push(tickBottom);

    // Easting label at bottom edge
    const labelBottomCoord = await to3857(e, minN);
    const labelBottom = new Feature({
      geometry: new PointGeom(labelBottomCoord),
      type: 'easting-label',
    });
    labelBottom.setStyle(new Style({
      text: new Text({
        text: `E ${formatCoord(e, resolvedInterval)}`,
        font: '10px Calibri, sans-serif',
        fill: new Fill({ color: '#1B3A5C' }),
        stroke: new Stroke({ color: '#FFFFFF', width: 3 }),
        offsetY: 14,
        textAlign: 'center',
      }),
    }));
    features.push(labelBottom);
  }

  // ─── Horizontal grid lines (constant Northing) ──────────────────────────
  for (let n = startN; n <= endN; n += resolvedInterval) {
    const left3857 = await to3857(startE, n);
    const right3857 = await to3857(endE, n);

    const lineFeature = new Feature({
      geometry: new LineString([left3857, right3857]),
      type: 'grid-line',
    });
    lineFeature.setStyle(gridLineStyle);
    features.push(lineFeature);

    // Add sub-grid lines at half intervals
    if (resolvedInterval >= 1000) {
      const halfInterval = resolvedInterval / 2;
      const subN = n + halfInterval;
      if (subN <= endN) {
        const subLeft3857 = await to3857(startE, subN);
        const subRight3857 = await to3857(endE, subN);
        const subFeature = new Feature({
          geometry: new LineString([subLeft3857, subRight3857]),
          type: 'sub-grid-line',
        });
        subFeature.setStyle(subGridLineStyle);
        features.push(subFeature);
      }
    }

    // ─── Tick marks at left edge ────────────────────────────────────────
    const tickLeftStart = await to3857(minE, n - tickLength);
    const tickLeftEnd = await to3857(minE, n + tickLength);
    const tickLeft = new Feature({
      geometry: new LineString([tickLeftStart, tickLeftEnd]),
      type: 'tick-mark',
    });
    tickLeft.setStyle(tickMarkStyle);
    features.push(tickLeft);

    // Northing label at left edge
    const labelLeftCoord = await to3857(minE, n);
    const labelLeft = new Feature({
      geometry: new PointGeom(labelLeftCoord),
      type: 'northing-label',
    });
    labelLeft.setStyle(new Style({
      text: new Text({
        text: `N ${formatCoord(n, resolvedInterval)}`,
        font: '10px Calibri, sans-serif',
        fill: new Fill({ color: '#1B3A5C' }),
        stroke: new Stroke({ color: '#FFFFFF', width: 3 }),
        offsetX: -10,
        textAlign: 'right',
      }),
    }));
    features.push(labelLeft);
  }

  // ─── Update the source ──────────────────────────────────────────────────
  const source = gridLayer.getSource() as InstanceType<typeof VectorSource>;
  source.clear();
  source.addFeatures(features);
}

/**
 * METARDU Map Layer Factories
 *
 * Provides factory functions for creating OpenLayers layers used by the
 * global map. All OL imports are dynamic for SSR compatibility.
 *
 * Layer hierarchy (zIndex):
 *   0  — OSM basemap
 *   1  — KenCORS control stations
 *   2  — Simple parcel layer (legacy, coord-based)
 *   3  — Beacon markers (legacy, station-based)
 *   20 — Scheme parcel polygons (from API)
 *   25 — Scheme block labels (from API)
 *   30 — Scheme beacon points (from API)
 *
 * @module layers
 * @see schemeLayer.ts — enhanced scheme data layers with API integration
 */

import { registerProjections } from '@/lib/map/projection'
import { createParcelStyleFunction, type ParcelStatus } from '@/lib/map/cadastralStyles'

// ─── OSM Basemap ──────────────────────────────────────────────────────────

export async function createOSMLayer() {
  const { default: TileLayer } = await import('ol/layer/Tile');
  const { default: OSM } = await import('ol/source/OSM');
  return new TileLayer({ source: new OSM(), zIndex: 0 });
}

// ─── Simple Parcel Layer (legacy, coord-based) ───────────────────────────

export async function createParcelLayer(
  coords3857: Array<[number, number]>
): Promise<import('ol/layer/Vector').default> {
  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Polygon },
    { default: Style },
    { default: Stroke },
    { default: Fill },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Polygon'),
    import('ol/style/Style'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
  ]);

  const polygon = new Polygon([coords3857]);
  const feature = new Feature({ geometry: polygon, type: 'parcel' });

  const source = new VectorSource({ features: [feature] });

  return new VectorLayer({
    source,
    zIndex: 2,
    style: new Style({
      stroke: new Stroke({ color: '#1B3A5C', width: 2.5 }),
      fill: new Fill({ color: 'rgba(27, 58, 92, 0.08)' }),
    }),
  });
}

// ─── Enhanced Parcel Layer (API-based, with projectId) ────────────────────

/**
 * Create a parcel layer that fetches GeoJSON data from the scheme map API.
 *
 * Accepts a `projectId` parameter, fetches parcel boundaries from
 * `/api/scheme/map?project_id=...`, transforms coordinates from
 * EPSG:21037 to EPSG:3857, and styles parcels with the existing
 * cadastral styles from `cadastralStyles.ts`.
 *
 * Features include:
 * - Status-aware parcel styling (approved/pending/rejected/default)
 * - Parcel number labels at interior points
 * - Click handler for parcel selection (popup with parcel details)
 * - Hover highlight effect (orange stroke + fill)
 *
 * @param projectId - The project ID to fetch scheme data for
 * @param options - Optional configuration
 * @param options.showLabels - Whether to show parcel number labels (default: true)
 * @returns Promise resolving to a VectorLayer with scheme parcel features
 */
export async function createParcelLayerFromScheme(
  projectId: string,
  options: { showLabels?: boolean; epsg?: string } = {},
): Promise<import('ol/layer/Vector').default> {
  const { showLabels = true, epsg = 'EPSG:21037' } = options

  // Ensure projections are registered before any coordinate transforms
  await registerProjections()

  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Polygon },
    { default: Style },
    { default: Stroke },
    { default: Fill },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Polygon'),
    import('ol/style/Style'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
  ])

  const { transform } = await import('ol/proj')

  // Fetch GeoJSON from the scheme map API
  const response = await fetch(`/api/scheme/map?project_id=${encodeURIComponent(projectId)}`)
  if (!response.ok) {
    throw new Error(`Failed to fetch scheme data: ${response.status}`)
  }

  const data = await response.json()

  if (!data || !data.features || !Array.isArray(data.features)) {
    throw new Error('Invalid scheme data response')
  }

  // Create the status-aware parcel style function
  const parcelStyleFn = await createParcelStyleFunction({
    showLabel: showLabels,
    strokeWidth: 2.5,
    zIndex: 20,
  })

  const features: InstanceType<typeof Feature>[] = []

  // Process each feature from the API response
  for (const feat of data.features) {
    // Only process parcel polygon features
    if (feat.properties?.type !== 'parcel') continue
    if (feat.geometry?.type !== 'Polygon') continue

    const rings = feat.geometry.coordinates as number[][][]
    const transformedRings: Array<Array<[number, number]>> = []

    for (const ring of rings) {
      const transformedRing: Array<[number, number]> = ring.map((coord: number[]) => {
        return transform([coord[0], coord[1]], epsg, 'EPSG:3857') as [number, number]
      })
      transformedRings.push(transformedRing)
    }

    const olFeature = new Feature({
      geometry: new Polygon(transformedRings),
      type: 'scheme-parcel',
      parcelId: feat.properties.parcel_id,
      parcelNumber: feat.properties.parcel_number,
      lrNumber: feat.properties.lr_number,
      blockNumber: feat.properties.block_number,
      areaHa: feat.properties.area_ha,
      status: (feat.properties.status || 'default') as ParcelStatus,
    })

    olFeature.setId(`parcel-${feat.properties.parcel_id || features.length}`)
    features.push(olFeature)
  }

  const source = new VectorSource({ features })

  const layer = new VectorLayer({
    source,
    style: parcelStyleFn as any,
    zIndex: 20,
    visible: true,
    properties: { name: 'scheme-parcels', projectId },
  })

  // ── Hover highlight effect ───────────────────────────────────────────
  // The highlight style is applied on hover, restoring the original style
  // when the mouse moves away.
  const highlightStyle = new Style({
    stroke: new Stroke({ color: '#D17B47', width: 3.5 }),
    fill: new Fill({ color: 'rgba(209, 123, 71, 0.18)' }),
  })

  let hoveredFeature: any = null
  let originalStyle: any = null

  // Store hover listeners on the layer for later cleanup
  ;(layer as any)._hoverSetup = {
    highlightStyle,
    getHoverState: () => ({ hoveredFeature, originalStyle }),
    setHoverState: (f: any, s: any) => { hoveredFeature = f; originalStyle = s },
  }

  return layer
}

// ─── Beacon Layer (legacy, station-based) ─────────────────────────────────

export async function createBeaconLayer(
  stations: Array<{ label: string; coord3857: [number, number] }>
): Promise<import('ol/layer/Vector').default> {
  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Point },
    { default: Style },
    { default: CircleStyle },
    { default: Stroke },
    { default: Fill },
    { default: Text },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Point'),
    import('ol/style/Style'),
    import('ol/style/Circle'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
    import('ol/style/Text'),
  ]);

  const features = stations.map(({ label, coord3857 }) => {
    const f = new Feature({ geometry: new Point(coord3857), label });
    f.setStyle(new Style({
      image: new CircleStyle({
        radius: 6,
        stroke: new Stroke({ color: '#1B3A5C', width: 2 }),
        fill: new Fill({ color: '#FFFFFF' }),
      }),
      text: new Text({
        text: label,
        offsetX: 10,
        offsetY: -10,
        font: 'bold 11px Calibri, sans-serif',
        fill: new Fill({ color: '#1B3A5C' }),
        stroke: new Stroke({ color: '#FFFFFF', width: 3 }),
      }),
    }));
    return f;
  });

  const source = new VectorSource({ features });
  return new VectorLayer({ source, zIndex: 3 });
}

// ─── KenCORS Layer ────────────────────────────────────────────────────────

export async function createKenCORSLayer(
  stations: Array<{ id: string; name: string; coord3857: [number, number]; distanceKm: number; status: string }>
): Promise<import('ol/layer/Vector').default> {
  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Point },
    { default: Style },
    { default: RegularShape },
    { default: Stroke },
    { default: Fill },
    { default: Text },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Point'),
    import('ol/style/Style'),
    import('ol/style/RegularShape'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
    import('ol/style/Text'),
  ]);

  const features = stations.map(({ id, name, coord3857, distanceKm, status }) => {
    const f = new Feature({ geometry: new Point(coord3857), id, name, distanceKm });
    f.setStyle(new Style({
      image: new RegularShape({
        points: 3,
        radius: 8,
        stroke: new Stroke({ color: status === 'active' ? '#006400' : '#888888', width: 2 }),
        fill: new Fill({ color: status === 'active' ? 'rgba(0,100,0,0.15)' : 'rgba(136,136,136,0.15)' }),
      }),
      text: new Text({
        text: `${id}\n${distanceKm.toFixed(1)} km`,
        offsetY: 18,
        font: '10px Calibri, sans-serif',
        fill: new Fill({ color: status === 'active' ? '#006400' : '#888888' }),
        stroke: new Stroke({ color: '#FFFFFF', width: 2 }),
        textAlign: 'center',
      }),
    }));
    return f;
  });

  const source = new VectorSource({ features });
  return new VectorLayer({ source, zIndex: 1 });
}

/**
 * Project Points Layer — loads survey points from a project and renders them
 * on the OpenLayers map with distinct styles for control points vs topo points.
 *
 * This is the #1 map gap: a surveying map that doesn't show your own field data
 * is broken. This module fetches from /api/project/[id]/points and creates a
 * VectorLayer with per-code styling.
 */

import type { Feature as OLFeature, Map } from 'ol'
import type { FeatureLike } from 'ol/Feature'

export interface ProjectPointsLayerResult {
  pointsLayer: any // VectorLayer
  pointsSource: any // VectorSource
  cleanup: () => void
  pointCount: number
  controlPointCount: number
}

/**
 * Raw database row shape for `survey_points` as returned by the
 * `/api/project/[id]/points` endpoint. Column names use snake_case.
 *
 * This is intentionally distinct from the canonical `SurveyPoint` interface
 * (which uses `name`, not `point_name`) — API/DB boundaries should map
 * between the two explicitly rather than pretending they're the same shape.
 */
interface SurveyPointRow {
  id: string
  point_name: string
  easting: number
  northing: number
  elevation: number | null
  code: string | null
  description: string | null
  is_control: boolean
}

/**
 * Project-level CRS metadata returned in `meta.project_crs` by the endpoint.
 * Used to derive the correct EPSG code for coordinate transforms.
 */
interface ProjectCrs {
  utm_zone: number | null
  hemisphere: string | null
  datum: string | null
}

/**
 * T1.5 FIX (2026-07-09): Derive the EPSG code from the project's CRS metadata
 * instead of hardcoding 'EPSG:21037'. Kenya spans UTM zones 36S and 37S; a
 * project in Mombasa (Zone 37S edge) or Kisumu (Zone 36S) would get silently
 * wrong coordinates if we always used 21037.
 *
 * Supported combinations (matches ProjectionSwitcher.tsx):
 *   Arc 1960 / UTM 36S → EPSG:21036
 *   Arc 1960 / UTM 37S → EPSG:21037
 *   WGS 84   / UTM 36S → EPSG:32736
 *   WGS 84   / UTM 37S → EPSG:32737
 *   (North zones are rare in Kenya but supported for completeness)
 */
function epsgFromProjectCrs(crs: ProjectCrs | null): string {
  if (!crs || !crs.utm_zone) return 'EPSG:21037' // default for central Kenya
  const zone = crs.utm_zone
  const isNorth = (crs.hemisphere || 'S').toUpperCase() === 'N'
  const isWgs84 = (crs.datum || '').toLowerCase().includes('wgs')

  if (isWgs84) {
    // WGS 84 UTM: 326xx (North), 327xx (South)
    return `EPSG:${isNorth ? 32600 : 32700}${zone}`
  }
  // Arc 1960 UTM: 2103x (South — Kenya standard), 2109x (North — rare)
  return `EPSG:${isNorth ? 21090 : 21000}${zone}`
}

/**
 * Load project survey points and create a styled vector layer.
 *
 * @param projectId The project ID
 * @param map The OpenLayers map instance
 * @returns Layer result with cleanup function
 */
export async function createProjectPointsLayer(
  projectId: string,
  map: Map,
): Promise<ProjectPointsLayerResult> {
  // Fetch points from the API
  const res = await fetch(`/api/project/${projectId}/points`)
  if (!res.ok) {
    throw new Error(`Failed to load project points (${res.status})`)
  }
  const json = await res.json()
  const points: SurveyPointRow[] = json.data || []
  // T1.5 FIX: Derive EPSG from the project's CRS metadata, not hardcoded.
  const projCode = epsgFromProjectCrs(json.meta?.project_crs ?? null)

  if (points.length === 0) {
    // Return empty layer
    const { default: VectorLayer } = await import('ol/layer/Vector')
    const { default: VectorSource } = await import('ol/source/Vector')
    const emptySource = new VectorSource()
    const emptyLayer = new VectorLayer({ source: emptySource, zIndex: 25 })
    return {
      pointsLayer: emptyLayer,
      pointsSource: emptySource,
      cleanup: () => map.removeLayer(emptyLayer),
      pointCount: 0,
      controlPointCount: 0,
    }
  }

  // Dynamic imports (ESM-safe)
  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Point },
    { default: Style },
    { default: CircleStyle },
    { default: Fill },
    { default: Stroke },
    { default: Text },
    proj,
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Point'),
    import('ol/style/Style'),
    import('ol/style/Circle'),
    import('ol/style/Fill'),
    import('ol/style/Stroke'),
    import('ol/style/Text'),
    import('ol/proj'),
  ])

  const source = new VectorSource()
  // projCode is derived from project CRS metadata above (T1.5 fix)

  let controlCount = 0

  for (const pt of points) {
    if (pt.easting == null || pt.northing == null) continue

    try {
      const coords3857 = proj.transform([pt.easting, pt.northing], projCode, 'EPSG:3857')
      const feature = new Feature({
        geometry: new Point(coords3857),
        pointName: pt.point_name,
        easting: pt.easting,
        northing: pt.northing,
        elevation: pt.elevation,
        code: pt.code,
        description: pt.description,
        isControl: pt.is_control,
        pointType: 'survey',
      })
      feature.set('projectId', projectId)
      source.addFeature(feature)
      if (pt.is_control) controlCount++
    } catch {
      // skip invalid coordinates
    }
  }

  // Style function: control points = sienna filled circle, topo = small dot
  const layer = new VectorLayer({
    source,
    style: (feature: FeatureLike) => {
      const isControl = feature.get('isControl') === true
      const code = feature.get('code') as string | null
      const name = feature.get('pointName') as string | null

      if (isControl) {
        // Control point: larger sienna circle with white border + label
        return new Style({
          image: new CircleStyle({
            radius: 7,
            fill: new Fill({ color: '#D17B47' }),
            stroke: new Stroke({ color: '#E8E4DE', width: 2.5 }),
          }),
          text: new Text({
            text: name || '',
            font: '11px "JetBrains Mono", monospace',
            fill: new Fill({ color: '#E8E4DE' }),
            stroke: new Stroke({ color: '#1A1816', width: 3 }),
            offsetY: -14,
          }),
        })
      }

      // Topo point: small dot, color by code
      let dotColor = '#A89E92' // default muted
      if (code) {
        const uc = code.toUpperCase()
        if (uc.includes('BLD') || uc.includes('BUILD')) dotColor = '#8FA67E' // sage = buildings
        if (uc.includes('ROAD') || uc.includes('RD')) dotColor = '#C89759' // ochre = roads
        if (uc.includes('FENCE')) dotColor = '#7A7066' // muted = fence
        if (uc.includes('TREE')) dotColor = '#5A7551' // dark sage = vegetation
        if (uc.includes('BOUND') || uc.includes('BDRY')) dotColor = '#D17B47' // accent = boundary
      }

      return new Style({
        image: new CircleStyle({
          radius: 4,
          fill: new Fill({ color: dotColor }),
          stroke: new Stroke({ color: '#1A1816', width: 1 }),
        }),
      })
    },
    zIndex: 25, // above basemap (0), below draw (50) and measure (45)
  })

  map.addLayer(layer)

  return {
    pointsLayer: layer,
    pointsSource: source,
    cleanup: () => map.removeLayer(layer),
    pointCount: points.length,
    controlPointCount: controlCount,
  }
}

'use client';
/**
 * Projection Registration — EPSG:21037 (Arc 1960 / UTM 37S) + Zone 36S
 *
 * Registers Kenyan cadastral projections via proj4:
 *  - EPSG:21037 — Arc 1960 / UTM Zone 37S (Nairobi, Mombasa, eastern Kenya)
 *  - EPSG:21036 — Arc 1960 / UTM Zone 36S (Kisumu, Eldoret, western Kenya)
 *  - EPSG:32736 — WGS84 / UTM Zone 36S (geodetic, Zone 36)
 *  - EPSG:32737 — WGS84 / UTM Zone 37S (geodetic, Zone 37, already common)
 *
 * Also provides autoDetectUtmZone() for automatic zone selection based on longitude.
 */

export const EPSG_21037_DEF =
  '+proj=utm +zone=37 +south +ellps=clrk80 +towgs84=-160,-6,-302,-0.807,0.339,-1.619,-2.554 +units=m +no_defs';

// T1.5c FIX (2026-07-10): Zone 36 was using a DIFFERENT datum shift
// (-143,-268,33,0,0,0,0 — a 3-parameter translation-only set, possibly from
// an old Tanzania variant) while Zone 37 uses the national-standard 7-parameter
// Bursa-Wolf (-160,-6,-302,-0.807,0.339,-1.619,-2.554). This means a surveyor
// in Kisumu (Zone 36) got a different datum shift than one in Nairobi (Zone 37)
// — a statutory inconsistency. Now both zones use the same national-standard
// 7-parameter from EPSG transformation 1165 (Arc 1960 → WGS84, Kenya).
export const EPSG_21036_DEF =
  '+proj=utm +zone=36 +south +ellps=clrk80 +towgs84=-160,-6,-302,-0.807,0.339,-1.619,-2.554 +units=m +no_defs';

export const EPSG_32736_DEF =
  '+proj=utm +zone=36 +south +datum=WGS84 +units=m +no_defs';

export const EPSG_32737_DEF =
  '+proj=utm +zone=37 +south +datum=WGS84 +units=m +no_defs';

export const SRID_21037 = 'EPSG:21037';
export const SRID_21036 = 'EPSG:21036';
export const SRID_32736 = 'EPSG:32736';
export const SRID_32737 = 'EPSG:32737';
export const SRID_3857  = 'EPSG:3857';
export const SRID_4326  = 'EPSG:4326';

let registered = false;
let _registrationFailed = false;

export function isProjectionRegistered(): boolean {
  return registered;
}

/**
 * Register all Kenyan cadastral projections with proj4 and OpenLayers.
 * Safe to call multiple times — will only register once.
 */
export async function registerProjections(): Promise<void> {
  if (registered || typeof window === 'undefined') return;

  try {
    const [proj4Module, { register }] = await Promise.all([
      import('proj4'),
      import('ol/proj/proj4'),
    ]);

    const proj4 = proj4Module.default;

    // Arc 1960 / UTM Zone 37S (primary — Nairobi, Mombasa, eastern Kenya)
    proj4.defs(SRID_21037, EPSG_21037_DEF);

    // Arc 1960 / UTM Zone 36S (western Kenya — Kisumu, Eldoret, Kakamega, Nakuru west)
    proj4.defs(SRID_21036, EPSG_21036_DEF);

    // WGS84 / UTM Zone 36S (geodetic / GNSS workflows)
    proj4.defs(SRID_32736, EPSG_32736_DEF);

    // WGS84 / UTM Zone 37S (geodetic / GNSS workflows)
    proj4.defs(SRID_32737, EPSG_32737_DEF);

    register(proj4);

    registered = true;
  } catch (err) {
    _registrationFailed = true;
    console.error('[projection] Projection registration failed:', err);
  }
}

// ─── UTM Zone Auto-Detection ──────────────────────────────────────────────

export interface UtmZoneResult {
  /** WGS84 UTM EPSG code (e.g., 'EPSG:32737') */
  wgs84: string
  /** Arc 1960 UTM EPSG code (e.g., 'EPSG:21037') */
  arc1960: string
  /** Zone number (36 or 37 for Kenya) */
  zone: number
  /** Hemisphere ('S' for Kenya) */
  hemisphere: 'N' | 'S'
}

/**
 * Auto-detect the appropriate UTM zone based on longitude.
 *
 * Kenya's UTM zones:
 *  - Zone 36S: longitude 30°E to 36°E (western Kenya: Kisumu, Eldoret, Kakamega, Nakuru west)
 *  - Zone 37S: longitude 36°E to 42°E (central/eastern Kenya: Nairobi, Mombasa, Meru)
 *
 * @param lng — Longitude in decimal degrees (WGS84)
 * @returns UtmZoneResult with both WGS84 and Arc 1960 EPSG codes
 */
export function autoDetectUtmZone(lng: number): UtmZoneResult {
  let zone: number
  if (lng >= 30 && lng < 36) {
    zone = 36
  } else if (lng >= 36 && lng < 42) {
    zone = 37
  } else {
    // Fallback: compute zone mathematically for anywhere in the world
    zone = Math.floor((lng + 180) / 6) + 1
  }

  const hemisphere: 'N' | 'S' = 'S' // Kenya is in the southern hemisphere

  const wgs84Epsg = `EPSG:32${hemisphere === 'S' ? '7' : '6'}${zone}`
  const arc1960Epsg = `EPSG:210${zone}`

  return {
    wgs84: wgs84Epsg,
    arc1960: arc1960Epsg,
    zone,
    hemisphere,
  }
}

// ─── Coordinate Transform Helpers ─────────────────────────────────────────

export async function to3857(easting: number, northing: number, fromSrid: string = SRID_21037): Promise<[number, number]> {
  const { transform } = await import('ol/proj');
  return transform([easting, northing], fromSrid, SRID_3857) as [number, number];
}

export async function arrayTo3857(
  coords: Array<[number, number]>,
  fromSrid: string = SRID_21037
): Promise<Array<[number, number]>> {
  const { transform } = await import('ol/proj');
  return coords.map(([e, n]) => transform([e, n], fromSrid, SRID_3857) as [number, number]);
}

export async function to21037(x: number, y: number): Promise<[number, number]> {
  const { transform } = await import('ol/proj');
  return transform([x, y], SRID_3857, SRID_21037) as [number, number];
}

export async function to21036(x: number, y: number): Promise<[number, number]> {
  const { transform } = await import('ol/proj');
  return transform([x, y], SRID_3857, SRID_21036) as [number, number];
}

/**
 * Transform from EPSG:4326 (WGS84 lat/lon) to the auto-detected Arc 1960 UTM zone.
 */
export async function toArc1960(lon: number, lat: number): Promise<{ easting: number; northing: number; srid: string }> {
  const zoneResult = autoDetectUtmZone(lon)
  const { transform } = await import('ol/proj')
  const [easting, northing] = transform([lon, lat], SRID_4326, zoneResult.arc1960) as [number, number]
  return { easting, northing, srid: zoneResult.arc1960 }
}

/**
 * METARDU Scheme Data Layers
 *
 * Dedicated module for loading and rendering cadastral scheme data
 * (parcels, blocks, beacons) on an OpenLayers map.
 *
 * All OpenLayers imports are dynamic for SSR compatibility.
 * Coordinates are transformed from EPSG:21037 (Arc 1960 / UTM 37S)
 * to EPSG:3857 (Web Mercator) for display.
 *
 * @module schemeLayer
 * @see layers.ts — base layer factories
 * @see cadastralStyles.ts — status-aware styling
 * @see projection.ts — EPSG:21037 registration
 */

import type { OLMap, OLFeature, OLLayer, OLEvent, OLOverlay } from './olTypes'

import { registerProjections } from '@/lib/map/projection'
import {
  createParcelStyleFunction,
  createBeaconStyleFunction,
  type ParcelStatus,
  type BeaconType,
} from '@/lib/map/cadastralStyles'

// ─── Types ────────────────────────────────────────────────────────────────

/** GeoJSON FeatureCollection returned by /api/scheme/map */
export interface SchemeGeoJSON {
  type: 'FeatureCollection'
  features: SchemeFeature[]
  bounds: [number, number, number, number] | null
  crs: { type: 'string'; properties: { name: string } }
}

export interface SchemeFeature {
  type: 'Feature'
  properties: {
    type: 'parcel' | 'parcel_point' | 'block_label'
    parcel_id?: string
    parcel_number?: string
    lr_number?: string
    block_number?: string
    block_id?: string
    block_name?: string
    area_ha?: number
    status?: string
    station?: string
    parcel_count?: number
  }
  geometry: {
    type: 'Polygon' | 'Point'
    coordinates: number[][] | number[]
  }
}

/** Result of loading scheme data — contains created layers and metadata */
export interface SchemeLayerResult {
  parcelLayer: import('ol/layer/Vector').default
  blockLayer: import('ol/layer/Vector').default
  beaconLayer: import('ol/layer/Vector').default
  parcelCount: number
  blockCount: number
  beaconCount: number
  extent: number[] | null
}

/** Options for scheme layer creation */
export interface SchemeLayerOptions {
  /** Whether to show parcel number labels (default: true) */
  showParcelLabels?: boolean
  /** Whether to auto-zoom to scheme extent after loading (default: true) */
  autoZoom?: boolean
  /** Callback when a parcel feature is clicked */
  onParcelClick?: (properties: SchemeFeature['properties']) => void
  /** Callback when a beacon feature is clicked */
  onBeaconClick?: (properties: SchemeFeature['properties']) => void
  /** T1.5 FIX (2026-07-09): UTM EPSG for coordinate transforms (default 'EPSG:21037') */
  epsg?: string
}

// ─── Data Fetching ────────────────────────────────────────────────────────

/**
 * Fetch scheme GeoJSON data from the API.
 *
 * @param projectId - The project ID to load scheme data for
 * @returns GeoJSON FeatureCollection with EPSG:21037 coordinates
 * @throws Error if the API request fails
 */
export async function loadSchemeData(projectId: string): Promise<SchemeGeoJSON> {
  const response = await fetch(`/api/scheme/map?project_id=${encodeURIComponent(projectId)}`)

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Failed to load scheme data: ${response.status} ${text}`)
  }

  const data: SchemeGeoJSON = await response.json()

  if (!data || !data.features) {
    throw new Error('Invalid scheme data response')
  }

  return data
}

// ─── Coordinate Transformation ────────────────────────────────────────────

/**
 * Transform a GeoJSON polygon ring from EPSG:21037 to EPSG:3857.
 */
async function transformRing(
  ring: number[][],
  epsg: string = 'EPSG:21037',
): Promise<Array<[number, number]>> {
  const { transform } = await import('ol/proj')
  return ring.map(coord => {
    const transformed = transform(
      [coord[0], coord[1]],
      epsg,
      'EPSG:3857',
    ) as [number, number]
    return transformed
  })
}

/**
 * Transform a single coordinate from EPSG:21037 to EPSG:3857.
 */
async function transformCoord(
  coord: number[],
  epsg: string = 'EPSG:21037',
): Promise<[number, number]> {
  const { transform } = await import('ol/proj')
  return transform([coord[0], coord[1]], epsg, 'EPSG:3857') as [number, number]
}

// ─── Layer Factories ──────────────────────────────────────────────────────

/**
 * Create a vector layer for scheme parcel polygons.
 *
 * Features are styled with status-aware cadastral styles from
 * `cadastralStyles.ts`. Each parcel polygon includes its number
 * as a label at the interior point.
 *
 * @param projectId - The project ID to fetch scheme data for
 * @param options - Configuration options
 * @returns Promise resolving to a VectorLayer with parcel features
 */
export async function createSchemeParcelLayer(
  projectId: string,
  options: SchemeLayerOptions = {},
): Promise<import('ol/layer/Vector').default> {
  const { showParcelLabels = true, epsg = 'EPSG:21037' } = options

  // Ensure projections are registered before any transforms
  await registerProjections()

  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Polygon },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Polygon'),
  ])

  // Fetch and parse scheme data
  const data = await loadSchemeData(projectId)

  // Create the status-aware parcel style function
  const parcelStyleFn = await createParcelStyleFunction({
    showLabel: showParcelLabels,
    strokeWidth: 2.5,
    zIndex: 20,
  })

  const features: InstanceType<typeof Feature>[] = []

  // Process parcel polygon features
  for (const feat of data.features) {
    if (feat.properties.type !== 'parcel') continue
    if (feat.geometry.type !== 'Polygon') continue

    const rings = feat.geometry.coordinates as unknown as number[][][]
    const transformedRings: Array<Array<[number, number]>> = []

    for (const ring of rings) {
      const transformedRing = await transformRing(ring, epsg)
      transformedRings.push(transformedRing)
    }

    const olFeature = new Feature({
      geometry: new Polygon(transformedRings),
      type: 'scheme-parcel',
      parcelId: feat.properties.parcel_id,
      parcelNumber: feat.properties.parcel_number,
      lrNumber: feat.properties.lr_number,
      blockNumber: feat.properties.block_number,
      areaHa: feat.properties.area_ha,
      status: (feat.properties.status || 'default') as ParcelStatus,
    })

    olFeature.setId(`parcel-${feat.properties.parcel_id || features.length}`)
    features.push(olFeature)
  }

  const source = new VectorSource({ features })

  const layer = new VectorLayer({
    source,
    style: parcelStyleFn as unknown as undefined,
    zIndex: 20,
    visible: true,
    properties: { name: 'scheme-parcels', projectId },
  })

  return layer
}

/**
 * Create a vector layer for scheme block labels.
 *
 * Block features are rendered as point markers with the block name
 * and parcel count as text labels.
 *
 * @param projectId - The project ID to fetch scheme data for
 * @returns Promise resolving to a VectorLayer with block features
 */
export async function createSchemeBlockLayer(
  projectId: string,
  epsg: string = 'EPSG:21037',
): Promise<import('ol/layer/Vector').default> {
  await registerProjections()

  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Point },
    { default: Style },
    { default: CircleStyle },
    { default: Stroke },
    { default: Fill },
    { default: Text },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Point'),
    import('ol/style/Style'),
    import('ol/style/Circle'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
    import('ol/style/Text'),
  ])

  const data = await loadSchemeData(projectId)

  const features: InstanceType<typeof Feature>[] = []

  for (const feat of data.features) {
    if (feat.properties.type !== 'block_label') continue
    if (feat.geometry.type !== 'Point') continue

    const coord = feat.geometry.coordinates as number[]
    const [x, y] = await transformCoord(coord, epsg)

    const olFeature = new Feature({
      geometry: new Point([x, y]),
      type: 'scheme-block',
      blockId: feat.properties.block_id,
      blockNumber: feat.properties.block_number,
      blockName: feat.properties.block_name,
      parcelCount: feat.properties.parcel_count,
    })

    // Style: circle marker + text label
    const labelText = feat.properties.block_name || `Block ${feat.properties.block_number}`
    const countLabel = feat.properties.parcel_count
      ? `${feat.properties.parcel_count} parcels`
      : ''

    olFeature.setStyle(new Style({
      image: new CircleStyle({
        radius: 10,
        fill: new Fill({ color: 'rgba(209, 123, 71, 0.25)' }),
        stroke: new Stroke({ color: '#D17B47', width: 2 }),
      }),
      text: new Text({
        text: countLabel ? `${labelText}\n${countLabel}` : labelText,
        font: 'bold 12px Calibri, sans-serif',
        fill: new Fill({ color: '#D17B47' }),
        stroke: new Stroke({ color: '#FFFFFF', width: 3.5 }),
        textAlign: 'center',
        textBaseline: 'middle',
        offsetY: -20,
      }),
    }))

    features.push(olFeature)
  }

  const source = new VectorSource({ features })

  return new VectorLayer({
    source,
    zIndex: 25,
    visible: true,
    properties: { name: 'scheme-blocks', projectId },
  })
}

/**
 * Create a vector layer for scheme beacon points.
 *
 * Beacon features come from `parcel_point` type features in the API response.
 * These are styled with SoK-compliant beacon markers from `cadastralStyles.ts`.
 *
 * @param projectId - The project ID to fetch scheme data for
 * @returns Promise resolving to a VectorLayer with beacon features
 */
export async function createSchemeBeaconLayer(
  projectId: string,
  epsg: string = 'EPSG:21037',
): Promise<import('ol/layer/Vector').default> {
  await registerProjections()

  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Point },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Point'),
  ])

  const data = await loadSchemeData(projectId)

  // Create the beacon style function
  const beaconStyleFn = await createBeaconStyleFunction({
    radius: 6,
    showDescription: false,
    labelOffsetX: 12,
    labelOffsetY: -12,
  })

  const features: InstanceType<typeof Feature>[] = []
  const seenStations = new Set<string>()

  for (const feat of data.features) {
    if (feat.properties.type !== 'parcel_point') continue
    if (feat.geometry.type !== 'Point') continue

    // Deduplicate by station name (beacons shared between parcels)
    const stationKey = feat.properties.station || `${(feat.geometry.coordinates as number[])[0]}_${(feat.geometry.coordinates as number[])[1]}`
    if (seenStations.has(stationKey)) continue
    seenStations.add(stationKey)

    const coord = feat.geometry.coordinates as number[]
    const [x, y] = await transformCoord(coord, epsg)

    const olFeature = new Feature({
      geometry: new Point([x, y]),
      type: 'scheme-beacon',
      beacon_type: 'boundary' as BeaconType,
      label: feat.properties.station || `Stn ${features.length + 1}`,
      parcelId: feat.properties.parcel_id,
      parcelNumber: feat.properties.parcel_number,
      blockNumber: feat.properties.block_number,
    })

    // Store original EPSG:21037 coordinates for vertex editing / COGO
    olFeature.set('easting', coord[0])
    olFeature.set('northing', coord[1])

    features.push(olFeature)
  }

  const source = new VectorSource({ features })

  return new VectorLayer({
    source,
    style: beaconStyleFn as unknown as undefined,
    zIndex: 30,
    visible: true,
    properties: { name: 'scheme-beacons', projectId },
  })
}

// ─── Popup Overlay Factory ────────────────────────────────────────────────

/**
 * Create a popup overlay for displaying feature info on the map.
 *
 * Returns the Overlay instance and the popup container element.
 * The popup is positioned at feature coordinates on click.
 *
 * @returns Object with the Overlay and helper functions
 */
export async function createSchemePopup() {
  const { default: Overlay } = await import('ol/Overlay')

  const popupElement = document.createElement('div')
  popupElement.className = 'hidden'

  const overlay = new Overlay({
    element: popupElement,
    autoPan: { animation: { duration: 250 } },
    positioning: 'bottom-center' as const,
    offset: [0, -12],
  })

  const hidePopup = () => {
    overlay.setPosition(undefined)
    popupElement.className = 'hidden'
    popupElement.replaceChildren()
  }

  return { overlay, popupElement, hidePopup }
}

/**
 * Render scheme feature popup content into a DOM element.
 *
 * This creates styled popup cards matching the existing map theme
 * (dark glass morphism with orange accents).
 */
export function renderSchemePopup(
  popupElement: HTMLDivElement,
  featureType: 'parcel' | 'beacon' | 'block',
  properties: Record<string, unknown>,
  hidePopup: () => void,
): void {
  popupElement.replaceChildren()
  popupElement.className = ''

  const card = document.createElement('div')
  card.className = 'bg-[#14141e]/95 border border-[#D17B47]/30 rounded-xl shadow-2xl backdrop-blur-xl p-4 min-w-[220px] max-w-[340px]'

  // Header
  const header = document.createElement('div')
  header.className = 'flex items-start justify-between mb-2'

  const labelWrap = document.createElement('div')
  labelWrap.className = 'flex items-center gap-2'
  const dot = document.createElement('div')
  dot.className = 'w-1.5 h-1.5 rounded-full bg-[#D17B47]'

  const typeLabels: Record<string, string> = {
    parcel: 'Parcel',
    beacon: 'Beacon',
    block: 'Block',
  }

  const label = document.createElement('span')
  label.className = 'text-[10px] text-gray-500 uppercase tracking-[0.15em] font-semibold'
  label.textContent = typeLabels[featureType] || 'Feature'
  labelWrap.append(dot, label)

  const closeButton = document.createElement('button')
  closeButton.type = 'button'
  closeButton.className = 'text-gray-600 hover:text-white transition-colors p-0.5'
  closeButton.textContent = '\u00d7'
  closeButton.addEventListener('click', hidePopup)
  header.append(labelWrap, closeButton)
  card.append(header)

  // Content fields based on feature type
  const addField = (key: string, value: unknown, label: string, color?: string) => {
    if (value == null || value === '') return
    const wrap = document.createElement('div')
    wrap.className = 'mb-1'
    wrap.innerHTML = `<span class="text-[10px] text-gray-600 uppercase tracking-wider">${label}</span>`
    const val = document.createElement('p')
    val.className = `text-sm font-semibold ${color || 'text-white'}`
    val.textContent = String(value)
    wrap.append(val)
    card.append(wrap)
  }

  if (featureType === 'parcel') {
    addField('parcelNumber', properties.parcelNumber, 'Parcel No.', 'text-[#D17B47]')
    addField('lrNumber', properties.lrNumber, 'LR Number')
    addField('blockNumber', properties.blockNumber, 'Block')
    addField('areaHa', properties.areaHa != null ? `${Number(properties.areaHa).toFixed(4)} ha` : null, 'Area')
    addField('status', properties.status, 'Status',
      properties.status === 'approved' ? 'text-green-500' :
      properties.status === 'pending' ? 'text-red-400' :
      properties.status === 'rejected' ? 'text-red-600' : 'text-gray-300'
    )
  } else if (featureType === 'beacon') {
    addField('label', properties.label, 'Station', 'text-[#D17B47]')
    addField('parcelNumber', properties.parcelNumber, 'Parcel')
    addField('blockNumber', properties.blockNumber, 'Block')
  } else if (featureType === 'block') {
    addField('blockName', properties.blockName, 'Block Name', 'text-[#D17B47]')
    addField('blockNumber', properties.blockNumber, 'Block No.')
    addField('parcelCount', properties.parcelCount ? `${properties.parcelCount} parcels` : null, 'Parcels')
  }

  popupElement.append(card)
}

// ─── Interaction Helpers ──────────────────────────────────────────────────

/**
 * Add a hover highlight interaction to scheme layers.
 *
 * When the mouse hovers over a parcel feature, it gets a highlight
 * style with increased opacity. The cursor changes to a pointer.
 *
 * @param map - The OpenLayers map instance
 * @param parcelLayer - The parcel vector layer
 * @returns Cleanup function to remove the interaction
 */
export async function addSchemeHoverInteraction(
  map: OLMap,
  parcelLayer: import('ol/layer/Vector').default,
): Promise<() => void> {
  const [
    { default: Style },
    { default: Stroke },
    { default: Fill },
  ] = await Promise.all([
    import('ol/style/Style'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
  ])

  let hoveredFeature: OLFeature | null = null
  let originalStyle: unknown = null

  const highlightStyle = new Style({
    stroke: new Stroke({ color: '#D17B47', width: 3.5 }),
    fill: new Fill({ color: 'rgba(209, 123, 71, 0.18)' }),
  })

  let lastMoveTime = 0

  const onMouseMove = (evt: OLEvent) => {
    const target = map.getTarget()
    if (!target) return

    // Throttle: only process hover detection every 50ms to reduce CPU load
    // forEachFeatureAtPixel is expensive on large scheme datasets
    const now = Date.now()
    if (now - lastMoveTime < 50) return
    lastMoveTime = now

    const pixel = map.getEventPixel(evt.originalEvent ?? new Event('mousemove'))
    const hit = map.forEachFeatureAtPixel(
      pixel,
      (f: OLFeature, layer: OLLayer) => {
        if (layer === parcelLayer && f.get('type') === 'scheme-parcel') {
          return f
        }
        return undefined
      },
      { hitTolerance: 3 },
    )

    const viewport = map.getViewport()
    if (hit) {
      const hitFeature = hit as OLFeature
      viewport.style.cursor = 'pointer'
      if (hoveredFeature !== hitFeature) {
        // Restore previous
        if (hoveredFeature && originalStyle != null) {
          hoveredFeature.setStyle(originalStyle)
        }
        hoveredFeature = hitFeature
        originalStyle = hitFeature.getStyle() ?? null
        hitFeature.setStyle(highlightStyle)
      }
    } else {
      viewport.style.cursor = ''
      if (hoveredFeature && originalStyle != null) {
        hoveredFeature.setStyle(originalStyle)
      }
      hoveredFeature = null
      originalStyle = null
    }
  }

  const onMouseOut = () => {
    if (hoveredFeature && originalStyle != null) {
      hoveredFeature.setStyle(originalStyle)
    }
    hoveredFeature = null
    originalStyle = null
    const viewport = map.getViewport()
    if (viewport) viewport.style.cursor = ''
  }

  map.on('pointermove', onMouseMove)
  map.getViewport().addEventListener('mouseout', onMouseOut)

  // Return cleanup function
  return () => {
    map.un('pointermove', onMouseMove)
    map.getViewport()?.removeEventListener('mouseout', onMouseOut)
    if (hoveredFeature && originalStyle != null) {
      hoveredFeature.setStyle(originalStyle)
    }
  }
}

/**
 * Add a click interaction to scheme layers that shows a popup
 * with feature details.
 *
 * @param map - The OpenLayers map instance
 * @param layers - Object with parcel, block, and beacon layers
 * @param overlay - The popup overlay
 * @param popupElement - The popup container element
 * @param hidePopup - Function to hide the popup
 * @returns Cleanup function to remove the interaction
 */
export function addSchemeClickInteraction(
  map: OLMap,
  layers: {
    parcelLayer: import('ol/layer/Vector').default
    blockLayer: import('ol/layer/Vector').default
    beaconLayer: import('ol/layer/Vector').default
  },
  overlay: import('ol/Overlay').default,
  popupElement: HTMLDivElement,
  hidePopup: () => void,
): () => void {
  const onClick = (evt: OLEvent) => {
    // Check if we hit a scheme feature
    const feature = map.forEachFeatureAtPixel(
      evt.pixel,
      (f: OLFeature, layer: OLLayer) => {
        if (
          layer === layers.parcelLayer ||
          layer === layers.blockLayer ||
          layer === layers.beaconLayer
        ) {
          return { feature: f, layer }
        }
        return undefined
      },
      { hitTolerance: 5 },
    )

    if (!feature) return

    const { feature: f, layer } = feature as { feature: OLFeature; layer: OLLayer }
    const featureType = f.get('type')

    let popupType: 'parcel' | 'beacon' | 'block' = 'parcel'
    if (featureType === 'scheme-beacon') popupType = 'beacon'
    else if (featureType === 'scheme-block') popupType = 'block'
    else if (featureType === 'scheme-parcel') popupType = 'parcel'
    else return

    const properties: Record<string, unknown> = {}
    const keys = f.getKeys()
    for (const key of keys) {
      if (key !== 'geometry' && key !== 'type') {
        properties[key] = f.get(key)
      }
    }

    renderSchemePopup(popupElement, popupType, properties, hidePopup)
    overlay.setPosition(evt.coordinate)
  }

  map.on('singleclick', onClick)

  return () => {
    map.un('singleclick', onClick)
  }
}

// ─── Auto-zoom ────────────────────────────────────────────────────────────

/**
 * Zoom the map to fit the scheme data extent.
 *
 * @param map - The OpenLayers map instance
 * @param extent - The extent in EPSG:3857 coordinates, or null to skip
 * @param padding - Padding around the extent (default: [80, 80, 80, 80])
 */
export async function zoomToSchemeExtent(
  map: OLMap,
  extent: number[] | null,
  padding: [number, number, number, number] = [80, 80, 80, 80],
): Promise<void> {
  if (!extent || extent[0] === Infinity || extent[2] === -Infinity) return

  map.getView().fit(extent, {
    padding,
    maxZoom: 18,
    duration: 800,
  })
}

// ─── Data-Driven Layer Builders (single fetch, shared data) ────────────────

/**
 * Build a parcel layer from pre-fetched scheme data.
 * This avoids redundant API calls when all layers share the same data.
 */
async function buildParcelLayerFromData(
  data: SchemeGeoJSON,
  options: { showParcelLabels?: boolean; epsg?: string } = {},
): Promise<import('ol/layer/Vector').default> {
  const { showParcelLabels = true, epsg = 'EPSG:21037' } = options

  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Polygon },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Polygon'),
  ])

  const parcelStyleFn = await createParcelStyleFunction({
    showLabel: showParcelLabels,
    strokeWidth: 2.5,
    zIndex: 20,
  })

  const features: InstanceType<typeof Feature>[] = []

  for (const feat of data.features) {
    if (feat.properties.type !== 'parcel') continue
    if (feat.geometry.type !== 'Polygon') continue

    const rings = feat.geometry.coordinates as unknown as number[][][]
    const transformedRings: Array<Array<[number, number]>> = []

    for (const ring of rings) {
      const transformedRing = await transformRing(ring, epsg)
      transformedRings.push(transformedRing)
    }

    const olFeature = new Feature({
      geometry: new Polygon(transformedRings),
      type: 'scheme-parcel',
      parcelId: feat.properties.parcel_id,
      parcelNumber: feat.properties.parcel_number,
      lrNumber: feat.properties.lr_number,
      blockNumber: feat.properties.block_number,
      areaHa: feat.properties.area_ha,
      status: (feat.properties.status || 'default') as ParcelStatus,
    })

    olFeature.setId(`parcel-${feat.properties.parcel_id || features.length}`)
    features.push(olFeature)
  }

  const source = new VectorSource({ features })

  return new VectorLayer({
    source,
    style: parcelStyleFn as unknown as undefined,
    zIndex: 20,
    visible: true,
    properties: { name: 'scheme-parcels' },
  })
}

/**
 * Build a block layer from pre-fetched scheme data.
 */
async function buildBlockLayerFromData(
  data: SchemeGeoJSON,
  epsg: string = 'EPSG:21037',
): Promise<import('ol/layer/Vector').default> {
  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Point },
    { default: Style },
    { default: CircleStyle },
    { default: Stroke },
    { default: Fill },
    { default: Text },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Point'),
    import('ol/style/Style'),
    import('ol/style/Circle'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
    import('ol/style/Text'),
  ])

  const features: InstanceType<typeof Feature>[] = []

  for (const feat of data.features) {
    if (feat.properties.type !== 'block_label') continue
    if (feat.geometry.type !== 'Point') continue

    const coord = feat.geometry.coordinates as number[]
    const [x, y] = await transformCoord(coord, epsg)

    const olFeature = new Feature({
      geometry: new Point([x, y]),
      type: 'scheme-block',
      blockId: feat.properties.block_id,
      blockNumber: feat.properties.block_number,
      blockName: feat.properties.block_name,
      parcelCount: feat.properties.parcel_count,
    })

    const labelText = feat.properties.block_name || `Block ${feat.properties.block_number}`
    const countLabel = feat.properties.parcel_count
      ? `${feat.properties.parcel_count} parcels`
      : ''

    olFeature.setStyle(new Style({
      image: new CircleStyle({
        radius: 10,
        fill: new Fill({ color: 'rgba(209, 123, 71, 0.25)' }),
        stroke: new Stroke({ color: '#D17B47', width: 2 }),
      }),
      text: new Text({
        text: countLabel ? `${labelText}\n${countLabel}` : labelText,
        font: 'bold 12px Calibri, sans-serif',
        fill: new Fill({ color: '#D17B47' }),
        stroke: new Stroke({ color: '#FFFFFF', width: 3.5 }),
        textAlign: 'center',
        textBaseline: 'middle',
        offsetY: -20,
      }),
    }))

    features.push(olFeature)
  }

  const source = new VectorSource({ features })

  return new VectorLayer({
    source,
    zIndex: 25,
    visible: true,
    properties: { name: 'scheme-blocks' },
  })
}

/**
 * Build a beacon layer from pre-fetched scheme data.
 */
async function buildBeaconLayerFromData(
  data: SchemeGeoJSON,
  epsg: string = 'EPSG:21037',
): Promise<import('ol/layer/Vector').default> {
  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Point },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Point'),
  ])

  const beaconStyleFn = await createBeaconStyleFunction({
    radius: 6,
    showDescription: false,
    labelOffsetX: 12,
    labelOffsetY: -12,
  })

  const features: InstanceType<typeof Feature>[] = []
  const seenStations = new Set<string>()

  for (const feat of data.features) {
    if (feat.properties.type !== 'parcel_point') continue
    if (feat.geometry.type !== 'Point') continue

    const stationKey = feat.properties.station || `${(feat.geometry.coordinates as number[])[0]}_${(feat.geometry.coordinates as number[])[1]}`
    if (seenStations.has(stationKey)) continue
    seenStations.add(stationKey)

    const coord = feat.geometry.coordinates as number[]
    const [x, y] = await transformCoord(coord, epsg)

    const olFeature = new Feature({
      geometry: new Point([x, y]),
      type: 'scheme-beacon',
      beacon_type: 'boundary' as BeaconType,
      label: feat.properties.station || `Stn ${features.length + 1}`,
      parcelId: feat.properties.parcel_id,
      parcelNumber: feat.properties.parcel_number,
      blockNumber: feat.properties.block_number,
    })

    // Store original EPSG:21037 coordinates for vertex editing / COGO
    olFeature.set('easting', coord[0])
    olFeature.set('northing', coord[1])

    features.push(olFeature)
  }

  const source = new VectorSource({ features })

  return new VectorLayer({
    source,
    style: beaconStyleFn as unknown as undefined,
    zIndex: 30,
    visible: true,
    properties: { name: 'scheme-beacons' },
  })
}

// ─── Convenience: Create All Scheme Layers ────────────────────────────────

/**
 * Create all scheme layers (parcels, blocks, beacons) and set up
 * interactions in one call.
 *
 * This is the main entry point for wiring scheme data to the map.
 * Data is fetched ONCE and shared across all three layers, avoiding
 * the triple API call that would occur if creating layers individually.
 *
 * @param projectId - The project ID
 * @param map - The OpenLayers map instance
 * @param options - Configuration options
 * @returns Object with all layers, interaction cleanup functions, and metadata
 */
export async function createSchemeLayers(
  projectId: string,
  map: OLMap,
  options: SchemeLayerOptions = {},
): Promise<{
  parcelLayer: import('ol/layer/Vector').default
  blockLayer: import('ol/layer/Vector').default
  beaconLayer: import('ol/layer/Vector').default
  popup: { overlay: import('ol/Overlay').default; popupElement: HTMLDivElement; hidePopup: () => void }
  cleanup: () => void
  parcelCount: number
  blockCount: number
  beaconCount: number
  extent: number[] | null
}> {
  const { autoZoom = true, showParcelLabels = true, epsg = 'EPSG:21037' } = options

  // Ensure projections are registered
  await registerProjections()

  // Fetch data ONCE and share across all layers (prevents triple API call)
  const data = await loadSchemeData(projectId)

  // Create all three layers using the shared data
  const [parcelLayer, blockLayer, beaconLayer] = await Promise.all([
    buildParcelLayerFromData(data, { showParcelLabels, epsg }),
    buildBlockLayerFromData(data, epsg),
    buildBeaconLayerFromData(data, epsg),
  ])

  // Add layers to map
  map.addLayer(parcelLayer as unknown as OLLayer)
  map.addLayer(blockLayer as unknown as OLLayer)
  map.addLayer(beaconLayer as unknown as OLLayer)

  // Create popup overlay
  const popup = await createSchemePopup()
  map.addOverlay(popup.overlay as unknown as OLOverlay)

  // Add interactions
  const removeHover = await addSchemeHoverInteraction(map, parcelLayer)
  const removeClick = addSchemeClickInteraction(
    map,
    { parcelLayer, blockLayer, beaconLayer },
    popup.overlay,
    popup.popupElement,
    popup.hidePopup,
  )

  // Compute counts
  const parcelSource = parcelLayer.getSource()
  const blockSource = blockLayer.getSource()
  const beaconSource = beaconLayer.getSource()

  const parcelCount = parcelSource?.getFeatures().length ?? 0
  const blockCount = blockSource?.getFeatures().length ?? 0
  const beaconCount = beaconSource?.getFeatures().length ?? 0

  // Compute combined extent from all layers
  let extent: number[] | null = null
  try {
    const parcelExtent = parcelSource?.getExtent()
    if (parcelExtent && parcelExtent[0] !== Infinity) {
      extent = [...parcelExtent]
    }
  } catch { /* ignore */ }

  // Auto-zoom
  if (autoZoom && extent) {
    await zoomToSchemeExtent(map, extent)
  }

  // Cleanup function
  const cleanup = () => {
    removeHover()
    removeClick()
    map.removeLayer(parcelLayer as unknown as OLLayer)
    map.removeLayer(blockLayer as unknown as OLLayer)
    map.removeLayer(beaconLayer as unknown as OLLayer)
    map.removeOverlay(popup.overlay)
  }

  return {
    parcelLayer,
    blockLayer,
    beaconLayer,
    popup,
    cleanup,
    parcelCount,
    blockCount,
    beaconCount,
    extent,
  }
}

'use client'
/**
 * Stakeout Mode — GPS-guided point navigation for field surveying
 *
 * Provides:
 *  - Overlay creation (target marker, direction arrow, distance/bearing labels)
 *  - Audio alerts (proximity beeps using Web Audio API)
 *  - Bearing/distance computation in Arc 1960 / UTM Zone 37S
 *  - Color-coded proximity indicators
 *
 * All OpenLayers imports are dynamic for SSR compatibility.
 * Uses EPSG:21037 for coordinate math.
 */

// ─── Types ────────────────────────────────────────────────────────────────

export interface StakeoutTarget {
  easting: number
  northing: number
  elevation?: number
  name?: string
  id?: string
}

export interface StakeoutPosition {
  easting: number
  northing: number
  elevation?: number
  accuracy: number
}

export interface StakeoutState {
  distance: number
  bearing: number
  bearingWCB: string
  dE: number
  dN: number
  elevationDiff: number | null
  proximityColor: 'green' | 'amber' | 'red'
  proximityLabel: string
}

// ─── Bearing / Distance Computation ──────────────────────────────────────

/**
 * Compute the whole-circle bearing from one point to another.
 * Returns bearing in degrees (0-360, clockwise from north).
 */
export function computeStakeoutBearing(
  from: { easting: number; northing: number },
  to: { easting: number; northing: number }
): number {
  const dE = to.easting - from.easting
  const dN = to.northing - from.northing
  let bearing = (Math.atan2(dE, dN) * 180) / Math.PI
  if (bearing < 0) bearing += 360
  return bearing
}

/**
 * Compute the horizontal distance between two points in meters.
 */
export function computeStakeoutDistance(
  from: { easting: number; northing: number },
  to: { easting: number; northing: number }
): number {
  const dE = to.easting - from.easting
  const dN = to.northing - from.northing
  return Math.sqrt(dE * dE + dN * dN)
}

/**
 * Format a bearing in WCB (Whole Circle Bearing) format: D°MM'SS"
 */
export function formatBearingWCB(bearing: number): string {
  const degrees = Math.floor(bearing)
  const minutesFloat = (bearing - degrees) * 60
  const minutes = Math.floor(minutesFloat)
  const seconds = Math.round((minutesFloat - minutes) * 60)
  return `${degrees}\u00B0${minutes.toString().padStart(2, '0')}'${seconds.toString().padStart(2, '0')}"`
}

/**
 * Compute the full stakeout state (distance, bearing, proximity, elevation).
 */
export function computeStakeoutState(
  current: StakeoutPosition,
  target: StakeoutTarget
): StakeoutState {
  const distance = computeStakeoutDistance(current, target)
  const bearing = computeStakeoutBearing(current, target)
  const bearingWCB = formatBearingWCB(bearing)
  const dE = target.easting - current.easting
  const dN = target.northing - current.northing

  const elevationDiff =
    current.elevation != null && target.elevation != null
      ? target.elevation - current.elevation
      : null

  let proximityColor: 'green' | 'amber' | 'red'
  let proximityLabel: string
  if (distance < 1) {
    proximityColor = 'green'
    proximityLabel = 'ARRIVED'
  } else if (distance < 3) {
    proximityColor = 'amber'
    proximityLabel = 'CLOSE'
  } else {
    proximityColor = 'red'
    proximityLabel = 'APPROACHING'
  }

  return { distance, bearing, bearingWCB, dE, dN, elevationDiff, proximityColor, proximityLabel }
}

// ─── Audio Alerts ─────────────────────────────────────────────────────────

let audioCtx: AudioContext | null = null
let beepInterval: ReturnType<typeof setInterval> | null = null

function getAudioContext(): AudioContext {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)()
  }
  return audioCtx
}

function playTone(frequency: number, duration: number, type: OscillatorType = 'sine') {
  try {
    const ctx = getAudioContext()
    if (ctx.state === 'suspended') ctx.resume()

    const oscillator = ctx.createOscillator()
    const gainNode = ctx.createGain()

    oscillator.type = type
    oscillator.frequency.setValueAtTime(frequency, ctx.currentTime)

    gainNode.gain.setValueAtTime(0.15, ctx.currentTime)
    gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + duration)

    oscillator.connect(gainNode)
    gainNode.connect(ctx.destination)

    oscillator.start(ctx.currentTime)
    oscillator.stop(ctx.currentTime + duration)
  } catch {
    // Audio not available — fail silently
  }
}

function playBeep() {
  playTone(880, 0.15, 'sine')
}

function playFastBeep() {
  playTone(1200, 0.08, 'sine')
}

function playContinuousTone() {
  playTone(1400, 0.3, 'square')
}

function playArrivedChime() {
  try {
    const ctx = getAudioContext()
    if (ctx.state === 'suspended') ctx.resume()

    // Three-note ascending chime
    const notes = [523.25, 659.25, 783.99] // C5, E5, G5
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator()
      const gain = ctx.createGain()
      osc.type = 'sine'
      osc.frequency.setValueAtTime(freq, ctx.currentTime + i * 0.15)
      gain.gain.setValueAtTime(0.2, ctx.currentTime + i * 0.15)
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + i * 0.15 + 0.3)
      osc.connect(gain)
      gain.connect(ctx.destination)
      osc.start(ctx.currentTime + i * 0.15)
      osc.stop(ctx.currentTime + i * 0.15 + 0.3)
    })
  } catch {
    // Audio not available
  }
}

let lastArrivedChime = 0

/**
 * Create a proximity-based audio alert system.
 * Call on each GPS position update with the current distance.
 * Returns a cleanup function to stop the alerts.
 */
export function createStakeoutAudioAlert(distance: number): void {
  // Stop existing interval
  if (beepInterval) {
    clearInterval(beepInterval)
    beepInterval = null
  }

  if (distance < 1) {
    // Arrived — play chime once (no more than once every 5 seconds)
    const now = Date.now()
    if (now - lastArrivedChime > 5000) {
      playArrivedChime()
      lastArrivedChime = now
    }
  } else if (distance < 3) {
    // Very close — continuous tone every 500ms
    playContinuousTone()
    beepInterval = setInterval(() => playContinuousTone(), 500)
  } else if (distance < 10) {
    // Close — fast beep every 400ms
    playFastBeep()
    beepInterval = setInterval(() => playFastBeep(), 400)
  } else {
    // Far — slow beep every 1500ms
    playBeep()
    beepInterval = setInterval(() => playBeep(), 1500)
  }
}

/**
 * Stop the stakeout audio alerts.
 */
export function stopStakeoutAudio(): void {
  if (beepInterval) {
    clearInterval(beepInterval)
    beepInterval = null
  }
  lastArrivedChime = 0
}

// ─── Overlay Creation ─────────────────────────────────────────────────────

/**
 * Create an OL overlay showing the stakeout target on the map.
 * Returns the overlay and a Vector source for the direction line.
 * All OL imports are dynamic for SSR safety.
 */
export async function createStakeoutOverlay(
  target: StakeoutTarget,
  epsg: string = 'EPSG:21037',
): Promise<{
  overlay: import('ol/Overlay').default
  targetSource: import('ol/source/Vector').default
  targetLayer: import('ol/layer/Vector').default
  directionSource: import('ol/source/Vector').default
  directionLayer: import('ol/layer/Vector').default
}> {
  const [
    { default: Overlay },
    { default: VectorSource },
    { default: VectorLayer },
    { default: Feature },
    { default: Point },
    { default: Style },
    { default: Fill },
    { default: Stroke },
    { default: CircleStyle },
    { transform },
  ] = await Promise.all([
    import('ol/Overlay'),
    import('ol/source/Vector'),
    import('ol/layer/Vector'),
    import('ol/Feature'),
    import('ol/geom/Point'),
    import('ol/style/Style'),
    import('ol/style/Fill'),
    import('ol/style/Stroke'),
    import('ol/style/Circle'),
    import('ol/proj').then(m => ({ transform: m.transform })),
  ])

  // Transform target from UTM to EPSG:3857
  const targetCoord = transform([target.easting, target.northing], epsg, 'EPSG:3857')

  // ── Target marker overlay (DOM element) ──
  const overlayEl = document.createElement('div')
  overlayEl.className = 'stakeout-target-overlay'
  overlayEl.style.cssText = 'position:relative;pointer-events:none;'

  // Crosshair container
  const crosshair = document.createElement('div')
  crosshair.style.cssText = `
    width: 48px; height: 48px; position: relative;
    transform: translate(-50%, -50%);
  `

  // Horizontal line
  const hLine = document.createElement('div')
  hLine.style.cssText = `
    position:absolute; top:50%; left:0; width:100%; height:2px;
    background: #D17B47; transform: translateY(-50%);
    box-shadow: 0 0 6px rgba(209, 123, 71,0.6);
  `
  // Vertical line
  const vLine = document.createElement('div')
  vLine.style.cssText = `
    position:absolute; left:50%; top:0; height:100%; width:2px;
    background: #D17B47; transform: translateX(-50%);
    box-shadow: 0 0 6px rgba(209, 123, 71,0.6);
  `
  // Center dot
  const center = document.createElement('div')
  center.style.cssText = `
    position:absolute; top:50%; left:50%; width:8px; height:8px;
    background: #D17B47; border-radius: 50%;
    transform: translate(-50%, -50%);
    box-shadow: 0 0 12px rgba(209, 123, 71,0.8);
    animation: stakeout-pulse 1.5s ease-in-out infinite;
  `
  // Outer ring
  const ring = document.createElement('div')
  ring.style.cssText = `
    position:absolute; top:50%; left:50%; width:32px; height:32px;
    border: 2px solid rgba(209, 123, 71,0.5); border-radius: 50%;
    transform: translate(-50%, -50%);
    animation: stakeout-ring 2s ease-in-out infinite;
  `
  // Label
  const label = document.createElement('div')
  label.style.cssText = `
    position:absolute; top:100%; left:50%; transform:translateX(-50%);
    margin-top:8px; white-space:nowrap;
    font-size:11px; font-family:monospace; color:#D17B47;
    background:rgba(20,20,30,0.9); padding:2px 6px; border-radius:4px;
    border:1px solid rgba(209, 123, 71,0.3);
  `
  label.textContent = target.name || `E:${target.easting.toFixed(1)} N:${target.northing.toFixed(1)}`

  crosshair.append(hLine, vLine, ring, center, label)
  overlayEl.appendChild(crosshair)

  // Add CSS animations if not already present
  if (!document.getElementById('stakeout-animations')) {
    const style = document.createElement('style')
    style.id = 'stakeout-animations'
    style.textContent = `
      @keyframes stakeout-pulse {
        0%, 100% { box-shadow: 0 0 12px rgba(209, 123, 71,0.8); }
        50% { box-shadow: 0 0 24px rgba(209, 123, 71,1); }
      }
      @keyframes stakeout-ring {
        0%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0.5; }
        50% { transform: translate(-50%, -50%) scale(1.2); opacity: 0.2; }
      }
    `
    document.head.appendChild(style)
  }

  const overlay = new Overlay({
    element: overlayEl,
    position: targetCoord,
    positioning: 'center-center' as any,
    stopEvent: false,
  })

  // ── Target point feature (beacon marker) ──
  const targetSource = new VectorSource()
  const targetFeature = new Feature({
    geometry: new Point(targetCoord),
    stakeoutTarget: true,
  })
  targetFeature.setStyle(
    new Style({
      image: new CircleStyle({
        radius: 10,
        fill: new Fill({ color: 'rgba(209, 123, 71,0.3)' }),
        stroke: new Stroke({ color: '#D17B47', width: 2.5 }),
      }),
    })
  )
  targetSource.addFeature(targetFeature)

  const targetLayer = new VectorLayer({
    source: targetSource,
    zIndex: 100,
  })

  // ── Direction line source (updated on each GPS position) ──
  const directionSource = new VectorSource()
  const directionLayer = new VectorLayer({
    source: directionSource,
    style: new Style({
      stroke: new Stroke({
        color: 'rgba(209, 123, 71,0.6)',
        width: 2,
        lineDash: [8, 6],
      }),
    }),
    zIndex: 99,
  })

  return { overlay, targetSource, targetLayer, directionSource, directionLayer }
}

/**
 * Update the stakeout direction line from current GPS position to target.
 * Call on each GPS position update.
 */
export async function updateStakeoutDirection(
  directionSource: import('ol/source/Vector').default,
  current: StakeoutPosition,
  target: StakeoutTarget,
  epsg: string = 'EPSG:21037',
): Promise<StakeoutState> {
  const { default: Feature } = await import('ol/Feature')
  const { default: LineString } = await import('ol/geom/LineString')
  const { transform } = await import('ol/proj')

  const state = computeStakeoutState(current, target)

  const fromCoord = transform([current.easting, current.northing], epsg, 'EPSG:3857')
  const toCoord = transform([target.easting, target.northing], epsg, 'EPSG:3857')

  // Clear previous direction features
  directionSource.clear()

  const lineFeature = new Feature({
    geometry: new LineString([fromCoord, toCoord]),
  })

  // Color-code based on proximity
  let lineColor: string
  if (state.proximityColor === 'green') lineColor = 'rgba(34,197,94,0.8)'
  else if (state.proximityColor === 'amber') lineColor = 'rgba(245,158,11,0.8)'
  else lineColor = 'rgba(209, 123, 71,0.6)'

  const { default: Style } = await import('ol/style/Style')
  const { default: Stroke } = await import('ol/style/Stroke')
  lineFeature.setStyle(
    new Style({
      stroke: new Stroke({
        color: lineColor,
        width: 2.5,
        lineDash: [8, 6],
      }),
    })
  )

  directionSource.addFeature(lineFeature)
  return state
}

/**
 * Update the target marker style based on proximity.
 */
export async function updateTargetProximityStyle(
  targetSource: import('ol/source/Vector').default,
  proximityColor: 'green' | 'amber' | 'red'
): Promise<void> {
  const { default: Style } = await import('ol/style/Style')
  const { default: Fill } = await import('ol/style/Fill')
  const { default: Stroke } = await import('ol/style/Stroke')
  const { default: CircleStyle } = await import('ol/style/Circle')

  const colorMap = {
    green: { fill: 'rgba(34,197,94,0.3)', stroke: '#22c55e' },
    amber: { fill: 'rgba(245,158,11,0.3)', stroke: '#f59e0b' },
    red: { fill: 'rgba(209, 123, 71,0.3)', stroke: '#D17B47' },
  }
  const colors = colorMap[proximityColor]

  const features = targetSource.getFeatures()
  for (const f of features) {
    f.setStyle(
      new Style({
        image: new CircleStyle({
          radius: 10,
          fill: new Fill({ color: colors.fill }),
          stroke: new Stroke({ color: colors.stroke, width: 2.5 }),
        }),
      })
    )
  }
}

/**
 * METARDU Subdivision Map Layer
 *
 * Renders subdivided lots as colored polygons on an OpenLayers map.
 * Each lot gets a unique fill color, lot number label, and area label.
 * Split lines are rendered as dashed lines.
 * Road reserves are rendered with semi-transparent orange fill and hatched boundary.
 *
 * All OL imports are dynamic to match existing project patterns.
 */

import type { SubdivisionResult, SplitLine, RoadReserveInfo } from '@/types/subdivision'
import type { Point2D } from '@/lib/engine/types'
import { to3857, arrayTo3857 } from '@/lib/map/projection'

/** Professional color palette for lot fills (RGBA with 0.25 alpha) */
const LOT_COLORS = [
  'rgba(96, 165, 250, 0.30)',   // light blue
  'rgba(74, 222, 128, 0.30)',   // light green
  'rgba(250, 204, 21, 0.30)',   // light yellow
  'rgba(251, 146, 160, 0.30)',  // light pink
  'rgba(196, 181, 253, 0.30)',  // light purple
  'rgba(103, 232, 249, 0.30)',  // light cyan
  'rgba(253, 186, 116, 0.30)',  // light orange
  'rgba(167, 139, 250, 0.30)',  // violet
]

/** Corresponding stroke colors (solid, more saturated) */
const LOT_STROKE_COLORS = [
  '#3B82F6', // blue
  '#22C55E', // green
  '#EAB308', // yellow
  '#F43F5E', // pink
  '#A78BFA', // purple
  '#06B6D4', // cyan
  '#F97316', // orange
  '#8B5CF6', // violet
]

/**
 * Create a subdivision overlay layer for the map.
 * Coordinates are converted from EPSG:21037 to EPSG:3857 for rendering.
 */
export async function createSubdivisionLayer(
  result: SubdivisionResult
): Promise<import('ol/layer/Vector').default> {
  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Polygon },
    { default: LineString },
    { default: PointGeom },
    { default: Style },
    { default: Stroke },
    { default: Fill },
    { default: Text },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Polygon'),
    import('ol/geom/LineString'),
    import('ol/geom/Point'),
    import('ol/style/Style'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
    import('ol/style/Text'),
  ])

  const features: InstanceType<typeof Feature>[] = []

  // ─── Parent parcel boundary (dashed outline) ────────────────────────────
  const parentClosed = [...result.parentParcel.vertices, result.parentParcel.vertices[0]]
  const parentCoords3857 = await arrayTo3857(
    parentClosed.map(p => [p.easting, p.northing] as [number, number])
  )

  const parentFeature = new Feature({
    geometry: new Polygon([parentCoords3857]),
    type: 'parent-boundary',
  })
  parentFeature.setStyle(new Style({
    stroke: new Stroke({
      color: '#1B3A5C',
      width: 3,
      lineDash: [8, 4],
    }),
    fill: new Fill({ color: 'rgba(27, 58, 92, 0.04)' }),
  }))
  features.push(parentFeature)

  // ─── Lot polygons with labels ───────────────────────────────────────────
  for (const lot of result.lots) {
    const colorIdx = (lot.lotNumber - 1) % LOT_COLORS.length
    const fillColor = LOT_COLORS[colorIdx]
    const strokeColor = LOT_STROKE_COLORS[colorIdx]

    // Close the polygon for rendering
    const closedLot = [...lot.vertices, lot.vertices[0]]
    const coords3857 = await arrayTo3857(
      closedLot.map(p => [p.easting, p.northing] as [number, number])
    )

    const lotFeature = new Feature({
      geometry: new Polygon([coords3857]),
      type: 'lot',
      lotNumber: lot.lotNumber,
    })
    lotFeature.setStyle(new Style({
      stroke: new Stroke({
        color: '#1B3A5C',
        width: 2.5,
      }),
      fill: new Fill({ color: fillColor }),
    }))
    features.push(lotFeature)

    // ─── Lot number label at centroid ────────────────────────────────────
    const centroidCoord = await to3857(lot.centroid.easting, lot.centroid.northing)

    const labelFeature = new Feature({
      geometry: new PointGeom(centroidCoord),
      type: 'lot-label',
    })
    labelFeature.setStyle(new Style({
      text: new Text({
        text: `LOT ${lot.lotNumber}\n${lot.areaHa.toFixed(4)} ha`,
        font: 'bold 12px Calibri, sans-serif',
        fill: new Fill({ color: '#1B3A5C' }),
        stroke: new Stroke({ color: '#FFFFFF', width: 4 }),
        textAlign: 'center',
        textBaseline: 'middle',
        offsetY: 0,
      }),
    }))
    features.push(labelFeature)
  }

  // ─── Road reserve polygon (if present) ─────────────────────────────────
  if (result.roadReserve && result.roadReserve.roadPolygon.length >= 3) {
    const rr = result.roadReserve
    const closedRR = [...rr.roadPolygon, rr.roadPolygon[0]]
    const rrCoords3857 = await arrayTo3857(
      closedRR.map(p => [p.easting, p.northing] as [number, number])
    )

    const roadFeature = new Feature({
      geometry: new Polygon([rrCoords3857]),
      type: 'road-reserve',
    })
    roadFeature.setStyle(new Style({
      fill: new Fill({ color: 'rgba(251, 146, 60, 0.35)' }),
      stroke: new Stroke({
        color: '#EA580C',
        width: 3,
        lineDash: [10, 5],
      }),
    }))
    features.push(roadFeature)

    // Road width label at centroid of road polygon
    let rrCx = 0, rrCy = 0
    for (const p of rr.roadPolygon) {
      rrCx += p.easting
      rrCy += p.northing
    }
    rrCx /= rr.roadPolygon.length
    rrCy /= rr.roadPolygon.length
    const rrCentroidCoord = await to3857(rrCx, rrCy)

    const rrLabelFeature = new Feature({
      geometry: new PointGeom(rrCentroidCoord),
      type: 'road-label',
    })
    rrLabelFeature.setStyle(new Style({
      text: new Text({
        text: `ROAD RESERVE\n${rr.width}m`,
        font: 'bold 11px Calibri, sans-serif',
        fill: new Fill({ color: '#9A3412' }),
        stroke: new Stroke({ color: '#FFFFFF', width: 4 }),
        textAlign: 'center',
        textBaseline: 'middle',
      }),
    }))
    features.push(rrLabelFeature)
  }

  const source = new VectorSource({ features })
  return new VectorLayer({ source, zIndex: 10 })
}

/**
 * Create a split-line preview layer (dashed red line).
 */
export async function createSplitLineLayer(
  splitLine: SplitLine | null
): Promise<import('ol/layer/Vector').default | null> {
  if (!splitLine) return null

  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: LineString },
    { default: Style },
    { default: Stroke },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/LineString'),
    import('ol/style/Style'),
    import('ol/style/Stroke'),
  ])

  const coords3857 = await arrayTo3857([
    [splitLine.startPoint.easting, splitLine.startPoint.northing] as [number, number],
    [splitLine.endPoint.easting, splitLine.endPoint.northing] as [number, number],
  ])

  const feature = new Feature({
    geometry: new LineString(coords3857),
    type: 'split-line',
  })
  feature.setStyle(new Style({
    stroke: new Stroke({
      color: '#DC2626',
      width: 2,
      lineDash: [6, 4],
    }),
  }))

  const source = new VectorSource({ features: [feature] })
  return new VectorLayer({ source, zIndex: 11 })
}

/**
 * Create a road reserve preview layer (semi-transparent orange polygon with hatched boundary).
 * Used for previewing the road reserve before executing the subdivision.
 */
export async function createRoadReservePreviewLayer(
  roadReserve: RoadReserveInfo
): Promise<import('ol/layer/Vector').default> {
  const [
    { default: VectorLayer },
    { default: VectorSource },
    { default: Feature },
    { default: Polygon },
    { default: PointGeom },
    { default: Style },
    { default: Stroke },
    { default: Fill },
    { default: Text },
  ] = await Promise.all([
    import('ol/layer/Vector'),
    import('ol/source/Vector'),
    import('ol/Feature'),
    import('ol/geom/Polygon'),
    import('ol/geom/Point'),
    import('ol/style/Style'),
    import('ol/style/Stroke'),
    import('ol/style/Fill'),
    import('ol/style/Text'),
  ])

  const features: InstanceType<typeof Feature>[] = []

  // Road corridor polygon
  const closed = [...roadReserve.roadPolygon, roadReserve.roadPolygon[0]]
  const coords3857 = await arrayTo3857(
    closed.map(p => [p.easting, p.northing] as [number, number])
  )

  const roadFeature = new Feature({
    geometry: new Polygon([coords3857]),
    type: 'road-reserve-preview',
  })
  roadFeature.setStyle(new Style({
    fill: new Fill({ color: 'rgba(251, 146, 60, 0.35)' }),
    stroke: new Stroke({
      color: '#EA580C',
      width: 3,
      lineDash: [10, 5],
    }),
  }))
  features.push(roadFeature)

  // Road width label at centroid
  let cx = 0, cy = 0
  for (const p of roadReserve.roadPolygon) {
    cx += p.easting
    cy += p.northing
  }
  cx /= roadReserve.roadPolygon.length
  cy /= roadReserve.roadPolygon.length
  const centroidCoord = await to3857(cx, cy)

  const labelFeature = new Feature({
    geometry: new PointGeom(centroidCoord),
    type: 'road-label-preview',
  })
  labelFeature.setStyle(new Style({
    text: new Text({
      text: `ROAD RESERVE\n${roadReserve.width}m`,
      font: 'bold 11px Calibri, sans-serif',
      fill: new Fill({ color: '#9A3412' }),
      stroke: new Stroke({ color: '#FFFFFF', width: 4 }),
      textAlign: 'center',
      textBaseline: 'middle',
    }),
  }))
  features.push(labelFeature)

  const source = new VectorSource({ features })
  return new VectorLayer({ source, zIndex: 12 })
}

'use client'
/**
 * Traverse-to-Parcel Workflow
 *
 * Converts adjusted traverse station coordinates into a GeoJSON polygon
 * suitable for storing as a parcel boundary.
 *
 * Workflow:
 *  1. Fetch adjusted traverse coordinates from the database
 *  2. Connect stations in order as a closed polygon
 *  3. Preview on the map as a polygon feature
 *  4. On confirm, save as a new parcel boundary
 *
 * Uses EPSG:21037 for coordinate storage.
 * All OpenLayers imports are dynamic for SSR compatibility.
 */

// ─── Types ────────────────────────────────────────────────────────────────

export interface TraversePoint {
  easting: number
  northing: number
  pointName: string
  rl?: number | null
}

export interface TraverseToParcelResult {
  polygon: GeoJSON.Polygon
  area: number      // square meters
  perimeter: number // meters
  pointCount: number
}

// ─── GeoJSON Polygon Construction ─────────────────────────────────────────

/**
 * Convert adjusted traverse station coordinates into a GeoJSON Polygon.
 * The stations are connected in order and the polygon is closed automatically.
 *
 * Coordinates are in EPSG:21037 (Arc 1960 / UTM Zone 37S).
 */
export function traversePointsToPolygon(
  traversePoints: Array<{ easting: number; northing: number; pointName: string }>
): GeoJSON.Polygon {
  if (traversePoints.length < 3) {
    throw new Error('At least 3 traverse points are required to form a polygon')
  }

  // Build the coordinate ring — close by repeating the first point
  const ring: number[][] = traversePoints.map(p => [p.easting, p.northing])
  // Close the ring
  ring.push([traversePoints[0].easting, traversePoints[0].northing])

  return {
    type: 'Polygon',
    coordinates: [ring],
  }
}

/**
 * Calculate the area of a polygon using the Shoelace formula.
 * Coordinates are in projected CRS (meters).
 */
export function calculatePolygonArea(vertices: Array<{ easting: number; northing: number }>): number {
  if (vertices.length < 3) return 0

  let area = 0
  const n = vertices.length
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    area += vertices[i].easting * vertices[j].northing
    area -= vertices[j].easting * vertices[i].northing
  }

  return Math.abs(area / 2)
}

/**
 * Calculate the perimeter of a polygon.
 * Coordinates are in projected CRS (meters).
 */
export function calculatePolygonPerimeter(vertices: Array<{ easting: number; northing: number }>): number {
  if (vertices.length < 2) return 0

  let perimeter = 0
  const n = vertices.length
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    const dE = vertices[j].easting - vertices[i].easting
    const dN = vertices[j].northing - vertices[i].northing
    perimeter += Math.sqrt(dE * dE + dN * dN)
  }

  return perimeter
}

/**
 * Full conversion: traverse points → GeoJSON polygon + area + perimeter.
 */
export function traverseToParcelResult(
  traversePoints: Array<{ easting: number; northing: number; pointName: string }>
): TraverseToParcelResult {
  const polygon = traversePointsToPolygon(traversePoints)
  const area = calculatePolygonArea(traversePoints)
  const perimeter = calculatePolygonPerimeter(traversePoints)

  return {
    polygon,
    area,
    perimeter,
    pointCount: traversePoints.length,
  }
}

// ─── API: Create Parcel from Traverse ─────────────────────────────────────

/**
 * Fetch adjusted traverse results and create a parcel boundary.
 * Calls the traverse API to get coordinates, then saves as a new parcel.
 *
 * @param projectId — The project ID
 * @param parcelId — The existing parcel ID that has the traverse
 * @returns The new or updated parcel ID
 */
export async function createParcelFromTraverse(
  projectId: string,
  parcelId: string
): Promise<{ parcelId: string; areaHa: number | null; polygon: GeoJSON.Polygon }> {
  // 1. Fetch the traverse coordinates from the API
  const traverseRes = await fetch(`/api/scheme/traverse?parcel_id=${parcelId}`)
  if (!traverseRes.ok) {
    throw new Error(`Failed to fetch traverse data: ${traverseRes.statusText}`)
  }

  const traverseData = await traverseRes.json()
  const coordinates: Array<{ station: string; easting: number; northing: number; rl: number | null }> =
    traverseData.data?.coordinates

  if (!coordinates || coordinates.length < 3) {
    throw new Error('Traverse has fewer than 3 coordinate stations — cannot form a polygon')
  }

  // 2. Build the polygon from traverse coordinates
  const traversePoints: TraversePoint[] = coordinates.map(c => ({
    easting: c.easting,
    northing: c.northing,
    pointName: c.station,
    rl: c.rl,
  }))

  const result = traverseToParcelResult(traversePoints)
  const areaHa = result.area / 10000

  // 3. Save the polygon as the parcel boundary via the scheme API
  const boundaryRes = await fetch('/api/scheme/parcel/boundary', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      parcel_id: parcelId,
      project_id: projectId,
      boundary_geojson: result.polygon,
      area_ha: areaHa,
      source: 'traverse',
      point_count: result.pointCount,
      perimeter_m: result.perimeter,
      crs: 'EPSG:21037',
    }),
  })

  if (!boundaryRes.ok) {
    // If the boundary API doesn't exist, update the parcel directly
    try {
      const updateRes = await fetch(`/api/scheme/parcel/${parcelId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          boundary_geojson: result.polygon,
          area_ha: areaHa,
          status: 'computed',
        }),
      })

      if (!updateRes.ok) {
        throw new Error(`Failed to update parcel boundary: ${updateRes.statusText}`)
      }
    } catch {
      // Last resort: just return the computed result without persisting
      console.warn('[traverseToParcel] Could not save boundary to server, returning computed result only')
    }
  }

  return {
    parcelId,
    areaHa,
    polygon: result.polygon,
  }
}

// ─── Map Preview Helpers ──────────────────────────────────────────────────

/**
 * Create an OL Vector layer with a polygon preview from traverse points.
 * Used for the "preview before confirm" workflow.
 *
 * All OL imports are dynamic for SSR compatibility.
 */
export async function createTraversePolygonPreview(
  traversePoints: Array<{ easting: number; northing: number; pointName: string }>,
  epsg: string = 'EPSG:21037',
): Promise<{
  source: import('ol/source/Vector').default
  layer: import('ol/layer/Vector').default
}> {
  const [
    { default: VectorSource },
    { default: VectorLayer },
    { default: Feature },
    { default: Polygon },
    { default: Style },
    { default: Fill },
    { default: Stroke },
    { default: CircleStyle },
    { default: Point },
    { default: Text },
    { transform },
  ] = await Promise.all([
    import('ol/source/Vector'),
    import('ol/layer/Vector'),
    import('ol/Feature'),
    import('ol/geom/Polygon'),
    import('ol/style/Style'),
    import('ol/style/Fill'),
    import('ol/style/Stroke'),
    import('ol/style/Circle'),
    import('ol/geom/Point'),
    import('ol/style/Text'),
    import('ol/proj').then(m => ({ transform: m.transform })),
  ])

  const source = new VectorSource()

  // Transform coordinates from UTM to EPSG:3857 for display
  const ring3857 = traversePoints.map(p => {
    const [x, y] = transform([p.easting, p.northing], epsg, 'EPSG:3857')
    return [x, y]
  })
  // Close the ring
  ring3857.push(ring3857[0])

  // Create polygon feature
  const polygonFeature = new Feature({
    geometry: new Polygon([ring3857]),
  })
  polygonFeature.setStyle(
    new Style({
      fill: new Fill({ color: 'rgba(209, 123, 71,0.15)' }),
      stroke: new Stroke({ color: '#D17B47', width: 2.5, lineDash: [8, 4] }),
    })
  )
  source.addFeature(polygonFeature)

  // Add point markers for each traverse station
  for (const p of traversePoints) {
    const coord = transform([p.easting, p.northing], epsg, 'EPSG:3857')
    const pointFeature = new Feature({
      geometry: new Point(coord),
    })
    pointFeature.setStyle(
      new Style({
        image: new CircleStyle({
          radius: 5,
          fill: new Fill({ color: '#D17B47' }),
          stroke: new Stroke({ color: '#fff', width: 1.5 }),
        }),
        text: new Text({
          text: p.pointName,
          font: '11px monospace',
          fill: new Fill({ color: '#fff' }),
          stroke: new Stroke({ color: '#000', width: 3 }),
          offsetY: -14,
        }),
      })
    )
    source.addFeature(pointFeature)
  }

  const layer = new VectorLayer({
    source,
    zIndex: 50,
  })

  return { source, layer }
}

/**
 * Remove the traverse polygon preview from the map.
 */
export function removeTraversePolygonPreview(
  mapInstance: any,
  layer: import('ol/layer/Vector').default | null
): void {
  if (!mapInstance || !layer) return
  try {
    mapInstance.removeLayer(layer)
  } catch { /* already removed */ }
}

/**
 * @module turfHelpers
 *
 * Pure-computation geospatial helpers wrapping @turf/turf for Kenyan cadastral
 * surveying on Metardu.
 *
 * **CRS convention** — every public API accepts and returns coordinates in a
 * Kenya UTM CRS (default EPSG:21037 / Arc 1960 / UTM Zone 37 South) expressed
 * as `{easting, northing}` (metres).  Internally, coordinates are round-tripped
 * through proj4 to/from WGS84 (EPSG:4326) so that turf can operate on
 * geographic [lon, lat] values.
 *
 * T1.5 FIX (2026-07-09): All functions now accept an optional `epsg` parameter
 * (default 'EPSG:21037'). Pass the project's actual UTM zone to avoid silent
 * wrong-coordinate bugs outside Zone 37S (Mombasa, Kisumu, Turkana).
 * Supported zones: EPSG:21036, EPSG:21037, EPSG:32736, EPSG:32737.
 *
 * No OpenLayers dependency — this module is safe for use in Node workers,
 * server-side code, and any environment where only numeric results are needed.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

import type { Point2D } from '@/types/surveyPoint'

/**
 * A survey point on the Kenya cadastral grid.
 *
 * Re-exported from the canonical `Point2D` for backwards compatibility with
 * existing call sites that import `{ SurveyPoint }` from this module. New
 * code should import `Point2D` directly from `@/types/surveyPoint`.
 */
export type SurveyPoint = Point2D

// ---------------------------------------------------------------------------
// Lazy-loaded turf & proj4 singletons
// ---------------------------------------------------------------------------

let _turf: any = null;
let _proj4: any = null;

/**
 * T1.5 FIX (2026-07-09): Proj4 definitions for all Kenya UTM zones.
 * Previously only EPSG:21037 was registered — projects in Zone 36 (Kisumu,
 * Mombasa) would silently get wrong coordinates.
 */
const KENYA_UTM_DEFS: Record<string, string> = {
  'EPSG:21036': '+proj=utm +zone=36 +south +ellps=clrk80 +towgs84=-160,-6,-302,-0.807,0.339,-1.619,-2.554 +units=m +no_defs',
  'EPSG:21037': '+proj=utm +zone=37 +south +ellps=clrk80 +towgs84=-160,-6,-302,-0.807,0.339,-1.619,-2.554 +units=m +no_defs',
  // WGS 84 UTM zones are built into proj4js but we register for clarity
  'EPSG:32736': '+proj=utm +zone=36 +south +datum=WGS84 +units=m +no_defs',
  'EPSG:32737': '+proj=utm +zone=37 +south +datum=WGS84 +units=m +no_defs',
}

/**
 * Ensures turf and proj4 are loaded (once, lazily on first call).
 * Also registers all Kenya UTM zone definitions.
 * Idempotent — subsequent calls resolve instantly.
 */
async function ensureLoaded(): Promise<void> {
  if (!_turf) {
    const [turfMod, proj4Mod] = await Promise.all([
      import('@turf/turf'),
      import('proj4'),
    ]);
    _turf = turfMod;
    _proj4 = proj4Mod.default ?? proj4Mod;
    // T1.5: Register ALL Kenya UTM zones, not just 21037
    for (const [code, def] of Object.entries(KENYA_UTM_DEFS)) {
      _proj4.defs(code, def);
    }
  }
}

// ---------------------------------------------------------------------------
// CRS helpers — Kenya UTM <-> WGS84 [lon, lat]
// ---------------------------------------------------------------------------

/**
 * Convert a UTM (easting, northing) pair to a WGS84 [lon, lat]
 * coordinate suitable for use with turf.
 *
 * @param easting - Easting in metres.
 * @param northing - Northing in metres.
 * @param epsg - Source EPSG code (default 'EPSG:21037' for Arc 1960 / UTM 37S).
 * @returns Tuple `[longitude, latitude]` in degrees (WGS84).
 *
 * @example
 *   const [lon, lat] = await toTurfCoord(300000, 9840000);               // Zone 37S
 *   const [lon, lat] = await toTurfCoord(300000, 9840000, 'EPSG:21036'); // Zone 36S
 */
export async function toTurfCoord(
  easting: number,
  northing: number,
  epsg: string = 'EPSG:21037',
): Promise<[number, number]> {
  await ensureLoaded();
  const [lon, lat] = _proj4(epsg, 'EPSG:4326', [easting, northing]);
  return [lon, lat];
}

/**
 * Convert a WGS84 [lon, lat] coordinate (turf format) back to UTM.
 *
 * @param coord - `[longitude, latitude]` in degrees (WGS84).
 * @param epsg - Target EPSG code (default 'EPSG:21037').
 * @returns Object with `easting` and `northing` in metres.
 *
 * @example
 *   const { easting, northing } = await fromTurfCoord([36.82, -1.28]);
 *   const { easting, northing } = await fromTurfCoord([34.75, -0.10], 'EPSG:21036');
 */
export async function fromTurfCoord(
  coord: [number, number],
  epsg: string = 'EPSG:21037',
): Promise<SurveyPoint> {
  await ensureLoaded();
  const [easting, northing] = _proj4('EPSG:4326', epsg, coord);
  return { easting, northing };
}

/**
 * Convert an array of UTM survey points to a turf {@link Polygon}.
 *
 * The ring is automatically closed if the first and last vertices differ.
 *
 * @param vertices - Array of `{easting, northing}` objects.
 * @param epsg - Source EPSG code (default 'EPSG:21037').
 * @returns A turf Polygon GeoJSON in WGS84.
 */
export async function polygonToTurf(
  vertices: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<any> {
  await ensureLoaded();
  const ring = vertices.map((v) =>
    _proj4(epsg, 'EPSG:4326', [v.easting, v.northing]),
  );
  // Ensure the ring is closed
  if (ring.length > 0) {
    const first = ring[0];
    const last = ring[ring.length - 1];
    if (first[0] !== last[0] || first[1] !== last[1]) {
      ring.push([...first]);
    }
  }
  return _turf.polygon([ring]);
}

/**
 * Convert an array of UTM survey points to a turf {@link LineString}.
 *
 * @param vertices - Array of `{easting, northing}` objects.
 * @param epsg - Source EPSG code (default 'EPSG:21037').
 * @returns A turf LineString GeoJSON in WGS84.
 */
export async function lineStringToTurf(
  vertices: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<any> {
  await ensureLoaded();
  const coords = vertices.map((v) =>
    _proj4(epsg, 'EPSG:4326', [v.easting, v.northing]),
  );
  return _turf.lineString(coords);
}

// ---------------------------------------------------------------------------
// Internal: convert a turf geometry (Polygon / MultiPolygon) back to
// UTM vertices.  Returns the exterior ring of the first polygon.
// ---------------------------------------------------------------------------

/**
 * Extract the outer-ring vertices from a turf Polygon or MultiPolygon and
 * convert them to UTM.
 *
 * For a MultiPolygon, only the first polygon's exterior ring is returned.
 *
 * @param geo - A turf Polygon or MultiPolygon GeoJSON.
 * @param epsg - Target EPSG code (default 'EPSG:21037').
 * @returns Array of `{easting, northing}` vertices (ring is **not** closed).
 */
async function turfToVertices(geo: any, epsg: string = 'EPSG:21037'): Promise<SurveyPoint[]> {
  await ensureLoaded();

  let exteriorRing: number[][];

  if (geo.geometry) {
    geo = geo.geometry;
  }

  if (geo.type === 'Polygon') {
    exteriorRing = geo.coordinates[0];
  } else if (geo.type === 'MultiPolygon') {
    exteriorRing = geo.coordinates[0][0];
  } else {
    throw new Error(
      `turfToVertices: unsupported geometry type "${geo.type}"`,
    );
  }

  return exteriorRing.map((c: number[]) => {
    const [easting, northing] = _proj4('EPSG:4326', epsg, c);
    return { easting, northing };
  });
}

// ---------------------------------------------------------------------------
// Survey analysis functions
// ---------------------------------------------------------------------------

/**
 * Calculate the area of a parcel in **square metres** using
 * {@link https://turfjs.org/docs/#area turf.area}.
 *
 * @param vertices - Parcel boundary as `{easting, northing}` vertices.
 * @param epsg - Source EPSG code (default 'EPSG:21037').
 * @returns Area in m². Returns `0` when fewer than 3 vertices are supplied.
 */
export async function calculateParcelAreaSqM(
  vertices: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<number> {
  if (vertices.length < 3) return 0;
  const poly = await polygonToTurf(vertices, epsg);
  return _turf.area(poly);
}

/**
 * Calculate the perimeter of a parcel in **metres** using
 * {@link https://turfjs.org/docs/#length turf.length}.
 *
 * @param vertices - Parcel boundary as `{easting, northing}` vertices.
 * @param epsg - Source EPSG code (default 'EPSG:21037').
 * @returns Perimeter in metres. Returns `0` when fewer than 2 vertices are supplied.
 */
export async function calculateParcelPerimeterM(
  vertices: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<number> {
  if (vertices.length < 2) return 0;
  const line = await lineStringToTurf(vertices, epsg);
  return _turf.length(line, { units: 'meters' });
}

/**
 * Buffer a single survey point by a given radius.
 *
 * Produces a polygon in the given EPSG that approximates a circle of the
 * requested radius on the ground.
 *
 * @param easting  - Easting of the centre point (m).
 * @param northing - Northing of the centre point (m).
 * @param radiusM  - Buffer radius in metres.
 * @param epsg - Source/target EPSG code (default 'EPSG:21037').
 * @returns Array of `{easting, northing}` vertices describing the buffer
 *          polygon.
 */
export async function bufferPoint(
  easting: number,
  northing: number,
  radiusM: number,
  epsg: string = 'EPSG:21037',
): Promise<SurveyPoint[]> {
  await ensureLoaded();
  const [lon, lat] = await toTurfCoord(easting, northing, epsg);
  const pt = _turf.point([lon, lat]);
  const buffered = _turf.buffer(pt, radiusM, { units: 'meters', steps: 32 });
  return turfToVertices(buffered, epsg);
}

/**
 * Buffer a parcel polygon by a given distance.
 *
 * A positive `distanceM` expands the parcel; a negative value contracts it.
 *
 * @param vertices  - Parcel boundary vertices.
 * @param distanceM - Buffer distance in metres (negative to shrink).
 * @param epsg - Source/target EPSG code (default 'EPSG:21037').
 * @returns New array of vertices representing the buffered parcel.
 */
export async function bufferParcel(
  vertices: SurveyPoint[],
  distanceM: number,
  epsg: string = 'EPSG:21037',
): Promise<SurveyPoint[]> {
  const poly = await polygonToTurf(vertices, epsg);
  const buffered = _turf.buffer(poly, distanceM, {
    units: 'meters',
    steps: 32,
  });
  return turfToVertices(buffered, epsg);
}

/**
 * Calculate the geometric intersection of two parcels.
 *
 * @param parcel1 - First parcel boundary vertices.
 * @param parcel2 - Second parcel boundary vertices.
 * @param epsg - Source/target EPSG code (default 'EPSG:21037').
 * @returns Vertices of the intersection polygon, or `null` if the parcels
 *          do not overlap (or the intersection is degenerate).
 */
export async function calculateIntersection(
  parcel1: SurveyPoint[],
  parcel2: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<SurveyPoint[] | null> {
  const [poly1, poly2] = await Promise.all([
    polygonToTurf(parcel1, epsg),
    polygonToTurf(parcel2, epsg),
  ]);
  const intersection = _turf.intersect(poly1, poly2);
  if (!intersection) return null;

  // intersect can return a GeometryCollection with no area
  if (intersection.geometry && intersection.geometry.type === 'GeometryCollection') {
    // Try to find a polygon inside the collection
    const polys = intersection.geometry.geometries.filter(
      (g: any) => g.type === 'Polygon' || g.type === 'MultiPolygon',
    );
    if (polys.length === 0) return null;
    // Rebuild from the first valid polygon
    const first = polys[0];
    const rebuilt =
      first.type === 'MultiPolygon'
        ? _turf.multiPolygon(first.coordinates)
        : _turf.polygon(first.coordinates);
    return turfToVertices(rebuilt, epsg);
  }

  return turfToVertices(intersection, epsg);
}

/**
 * Calculate the geometric union of two parcels.
 *
 * @param parcel1 - First parcel boundary vertices.
 * @param parcel2 - Second parcel boundary vertices.
 * @param epsg - Source/target EPSG code (default 'EPSG:21037').
 * @returns Vertices of the combined (union) parcel.
 */
export async function calculateUnion(
  parcel1: SurveyPoint[],
  parcel2: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<SurveyPoint[]> {
  const [poly1, poly2] = await Promise.all([
    polygonToTurf(parcel1, epsg),
    polygonToTurf(parcel2, epsg),
  ]);
  const union = _turf.union(poly1, poly2);
  return turfToVertices(union, epsg);
}

/**
 * Calculate the geometric difference of two parcels (parcel1 minus parcel2).
 *
 * @param parcel1 - Source parcel (the parcel to subtract *from*).
 * @param parcel2 - Subtract parcel (the parcel to remove).
 * @param epsg - Source/target EPSG code (default 'EPSG:21037').
 * @returns Vertices of the resulting parcel, or `null` if parcel2 fully
 *          contains parcel1 (nothing remains).
 */
export async function calculateDifference(
  parcel1: SurveyPoint[],
  parcel2: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<SurveyPoint[] | null> {
  const [poly1, poly2] = await Promise.all([
    polygonToTurf(parcel1, epsg),
    polygonToTurf(parcel2, epsg),
  ]);
  const diff = _turf.difference(poly1, poly2);
  if (!diff) return null;

  // difference can return a GeometryCollection when there's nothing left
  if (diff.geometry && diff.geometry.type === 'GeometryCollection') {
    const polys = diff.geometry.geometries.filter(
      (g: any) => g.type === 'Polygon' || g.type === 'MultiPolygon',
    );
    if (polys.length === 0) return null;
    const first = polys[0];
    const rebuilt =
      first.type === 'MultiPolygon'
        ? _turf.multiPolygon(first.coordinates)
        : _turf.polygon(first.coordinates);
    return turfToVertices(rebuilt, epsg);
  }

  return turfToVertices(diff, epsg);
}

/**
 * Test whether a survey point lies inside a parcel boundary.
 *
 * Uses {@link https://turfjs.org/docs/#booleanPointInPolygon
 * turf.booleanPointInPolygon}.
 *
 * @param easting        - Easting of the query point (m).
 * @param northing       - Northing of the query point (m).
 * @param parcelVertices - Parcel boundary vertices.
 * @param epsg - Source EPSG code (default 'EPSG:21037').
 * @returns `true` if the point is inside (or on the boundary of) the parcel.
 */
export async function isPointInParcel(
  easting: number,
  northing: number,
  parcelVertices: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<boolean> {
  if (parcelVertices.length < 3) return false;
  const [lon, lat] = await toTurfCoord(easting, northing, epsg);
  const pt = _turf.point([lon, lat]);
  const poly = await polygonToTurf(parcelVertices, epsg);
  return _turf.booleanPointInPolygon(pt, poly);
}

/**
 * Calculate the Polsby-Popper compactness score for a parcel.
 *
 * The score ranges from 0 (highly elongated / irregular) to 1 (a perfect
 * circle).  It is defined as:
 *
 * ```
 * C = 4π × A / P²
 * ```
 *
 * where *A* is the area in m² and *P* is the perimeter in m.
 *
 * Useful for flagging unusually shaped parcels that may indicate boundary
 * disputes or survey errors in Kenyan land records.
 *
 * @param vertices - Parcel boundary vertices.
 * @param epsg - Source EPSG code (default 'EPSG:21037').
 * @returns Compactness score between 0 and 1. Returns `0` when fewer than 3
 *          vertices are supplied.
 */
export async function calculateCompactness(
  vertices: SurveyPoint[],
  epsg: string = 'EPSG:21037',
): Promise<number> {
  if (vertices.length < 3) return 0;

  const [areaSqM, perimeterM] = await Promise.all([
    calculateParcelAreaSqM(vertices, epsg),
    calculateParcelPerimeterM(vertices, epsg),
  ]);

  if (perimeterM === 0) return 0;

  return (4 * Math.PI * areaSqM) / (perimeterM * perimeterM);
}

/**
 * METARDU Vector Tile Factory
 *
 * Provides async factory functions for creating VectorTileLayers
 * for rendering large cadastral datasets efficiently using MVT or
 * GeoJSON vector tiles.
 *
 * All OL imports use dynamic import() for SSR safety in Next.js 16.
 *
 * Layers:
 * - createVectorTileLayer:  Generic VectorTileLayer from MVT or GeoJSON tiles
 * - createParcelTileLayer:  SoK-compliant parcel polygon styling
 * - createBeaconTileLayer:  Gold circle beacon point markers
 * - estimateTileCount:      Tile count estimator for loading progress
 */

/**
 * Options for creating a generic vector tile layer.
 */
export interface VectorTileOptions {
  /** Tile URL template: /tiles/{z}/{x}/{y}.pbf or .pmtiles */
  url: string;
  /** Tile data format. Default: 'mvt' */
  format?: 'mvt' | 'geojson';
  /** Layer name to filter within the tile source */
  layerName?: string;
  /** Style function applied to each feature */
  style?: (feature: any) => any;
  /** Minimum zoom level for rendering */
  minZoom?: number;
  /** Maximum zoom level for rendering */
  maxZoom?: number;
  /** Initial visibility */
  visible?: boolean;
  /** Layer opacity (0-1) */
  opacity?: number;
  /** Z-index for layer ordering */
  zIndex?: number;
}

/**
 * Options for creating a specialized parcel polygon tile layer.
 */
export interface ParcelTileOptions {
  /** Tile URL template for parcel polygons */
  url: string;
  /** Minimum zoom level. Default: 14 (parcels only shown at close zoom) */
  minZoom?: number;
  /** Maximum zoom level */
  maxZoom?: number;
  /** Layer opacity (0-1) */
  opacity?: number;
}

/**
 * Options for creating a specialized beacon point tile layer.
 */
export interface BeaconTileOptions {
  /** Tile URL template for beacon points */
  url: string;
  /** Minimum zoom level. Default: 14 */
  minZoom?: number;
  /** Maximum zoom level */
  maxZoom?: number;
  /** Layer opacity (0-1) */
  opacity?: number;
}

// ---------------------------------------------------------------------------
// Utility
// ---------------------------------------------------------------------------

/**
 * Estimate the number of tiles required to cover a given extent at a specific
 * Web Mercator zoom level.
 *
 * Useful for showing loading progress indicators or pre-fetching tile budgets.
 *
 * @param extent - `[minX, minY, maxX, maxY]` in EPSG:3857 meters
 * @param zoom   - Web Mercator zoom level (0-22)
 * @returns Estimated total number of tiles visible within the extent
 */
export function estimateTileCount(extent: number[], zoom: number): number {
  const halfEarth = 20037508.342789244;
  const tileSize = (2 * halfEarth) / Math.pow(2, zoom);

  const [minX, minY, maxX, maxY] = extent;
  const origin = -halfEarth;

  const tileMinX = Math.floor((minX - origin) / tileSize);
  const tileMaxX = Math.ceil((maxX - origin) / tileSize);
  const tileMinY = Math.floor((minY - origin) / tileSize);
  const tileMaxY = Math.ceil((maxY - origin) / tileSize);

  const countX = Math.max(0, tileMaxX - tileMinX);
  const countY = Math.max(0, tileMaxY - tileMinY);

  return countX * countY;
}

// ---------------------------------------------------------------------------
// Generic VectorTileLayer
// ---------------------------------------------------------------------------

/**
 * Create a generic VectorTileLayer from MVT or GeoJSON tile sources.
 *
 * Supports standard XYZ tile URLs (`/tiles/{z}/{x}/{y}.pbf`) and PMTiles
 * archives. For PMTiles the factory attempts to load the `ol-pmtiles`
 * adapter; if unavailable it falls back to a standard VectorTile source
 * (which requires a server-side PMTiles-to-MVT proxy in that case).
 *
 * @param options - Configuration for the vector tile layer
 * @returns Promise resolving to an OpenLayers VectorTileLayer
 */
export async function createVectorTileLayer(options: VectorTileOptions) {
  const {
    url,
    format = 'mvt',
    layerName,
    style,
    minZoom,
    maxZoom = 22,
    visible = true,
    opacity = 1,
    zIndex = 10,
  } = options;

  const [
    { default: VectorTileLayer },
    { default: VectorTileSource },
    MVTModule,
    GeoJSONModule,
  ] = await Promise.all([
    import('ol/layer/VectorTile'),
    import('ol/source/VectorTile'),
    import('ol/format/MVT'),
    import('ol/format/GeoJSON'),
  ]);

  // Build the tile format appropriate for the requested encoding.
  const tileFormat =
    format === 'geojson'
      ? new GeoJSONModule.default()
      : new MVTModule.default({
          layers: layerName ? [layerName] : undefined,
        });

  const isPMTiles = url.toLowerCase().endsWith('.pmtiles');

  let source: any;

  if (isPMTiles) {
    // Attempt to use the ol-pmtiles adapter for native PMTiles support.
    try {
      // ol-pmtiles is an optional dependency — ignore if not installed.
      const pmTilesModule = await import(/* webpackIgnore: true */ 'ol-pmtiles' as any);
      source = new pmTilesModule.default({
        url,
        format: tileFormat,
      });
    } catch {
      // Adapter not installed — fall back to standard VectorTile source.
      // Caller must ensure a server-side PMTiles proxy is in front of the URL.
      source = new VectorTileSource({
        url,
        format: tileFormat as any,
        maxZoom,
      });
    }
  } else {
    source = new VectorTileSource({
      url,
      format: tileFormat as any,
      maxZoom,
    });
  }

  const layer = new VectorTileLayer({
    source,
    minZoom,
    visible,
    opacity,
    zIndex,
  });

  if (style) {
    layer.setStyle(style);
  }

  layer.set('layerType', 'vectorTile');
  layer.set('tileUrl', url);
  layer.set('tileFormat', format);

  return layer;
}

// ---------------------------------------------------------------------------
// Parcel Tile Layer (SoK-compliant)
// ---------------------------------------------------------------------------

/**
 * Create a specialized VectorTileLayer for parcel polygons with
 * Survey of Kenya (SoK) compliant default styling.
 *
 * **Default style:**
 * - Fill:  dark blue at 8 % opacity — `rgba(27, 58, 92, 0.08)`
 * - Stroke: solid blue `#1B3A5C`, 2 px width
 * - Labels: white halo text showing the `parcel_number` feature property
 *
 * Parcels are only visible at close zoom by default (`minZoom: 14`) to
 * maintain rendering performance with large cadastral datasets.
 *
 * @param options - Configuration for the parcel tile layer
 * @returns Promise resolving to an OpenLayers VectorTileLayer
 */
export async function createParcelTileLayer(options: ParcelTileOptions) {
  const {
    url,
    minZoom = 14,
    maxZoom = 22,
    opacity = 1,
  } = options;

  const [
    { default: VectorTileLayer },
    { default: VectorTileSource },
    { default: MVT },
    { default: Style },
    { default: Fill },
    { default: Stroke },
    { default: Text },
  ] = await Promise.all([
    import('ol/layer/VectorTile'),
    import('ol/source/VectorTile'),
    import('ol/format/MVT'),
    import('ol/style/Style'),
    import('ol/style/Fill'),
    import('ol/style/Stroke'),
    import('ol/style/Text'),
  ]);

  const source = new VectorTileSource({
    url,
    format: new MVT(),
    maxZoom,
  });

  const layer = new VectorTileLayer({
    source,
    minZoom,
    visible: true,
    opacity,
    zIndex: 10,
    style: (feature: any) => {
      const parcelNumber = feature.get('parcel_number') ?? '';
      return new Style({
        fill: new Fill({ color: 'rgba(27, 58, 92, 0.08)' }),
        stroke: new Stroke({ color: '#1B3A5C', width: 2 }),
        text: parcelNumber
          ? new Text({
              text: String(parcelNumber),
              font: '11px Calibri, sans-serif',
              fill: new Fill({ color: '#1B3A5C' }),
              stroke: new Stroke({ color: '#FFFFFF', width: 3 }),
            })
          : undefined,
      });
    },
  });

  layer.set('layerType', 'parcelTile');
  layer.set('tileUrl', url);

  return layer;
}

// ---------------------------------------------------------------------------
// Beacon Tile Layer
// ---------------------------------------------------------------------------

/**
 * Create a specialized VectorTileLayer for beacon points with gold circle
 * markers and labelled beacon IDs.
 *
 * **Default style:**
 * - Marker: gold (`#FFD700`) circles, radius 5 px, dark blue border
 * - Labels: white halo text showing the `beacon_id` feature property
 *
 * @param options - Configuration for the beacon tile layer
 * @returns Promise resolving to an OpenLayers VectorTileLayer
 */
export async function createBeaconTileLayer(options: BeaconTileOptions) {
  const {
    url,
    minZoom = 14,
    maxZoom = 22,
    opacity = 1,
  } = options;

  const [
    { default: VectorTileLayer },
    { default: VectorTileSource },
    { default: MVT },
    { default: Style },
    { default: CircleStyle },
    { default: Fill },
    { default: Stroke },
    { default: Text },
  ] = await Promise.all([
    import('ol/layer/VectorTile'),
    import('ol/source/VectorTile'),
    import('ol/format/MVT'),
    import('ol/style/Style'),
    import('ol/style/Circle'),
    import('ol/style/Fill'),
    import('ol/style/Stroke'),
    import('ol/style/Text'),
  ]);

  const source = new VectorTileSource({
    url,
    format: new MVT(),
    maxZoom,
  });

  const layer = new VectorTileLayer({
    source,
    minZoom,
    visible: true,
    opacity,
    zIndex: 11,
    style: (feature: any) => {
      const beaconId = feature.get('beacon_id') ?? '';
      return new Style({
        image: new CircleStyle({
          radius: 5,
          fill: new Fill({ color: '#FFD700' }),
          stroke: new Stroke({ color: '#1B3A5C', width: 1.5 }),
        }),
        text: beaconId
          ? new Text({
              text: String(beaconId),
              font: 'bold 11px Calibri, sans-serif',
              fill: new Fill({ color: '#1B3A5C' }),
              stroke: new Stroke({ color: '#FFFFFF', width: 3 }),
              offsetY: -12,
            })
          : undefined,
      });
    },
  });

  layer.set('layerType', 'beaconTile');
  layer.set('tileUrl', url);

  return layer;
}

/**
 * @module webglPointsLayer
 *
 * WebGL Point Layer for massive topographic datasets
 *
 * Uses OpenLayers' WebGLPointsLayer to render 50,000+ points
 * using GPU shaders instead of Canvas2D. This eliminates UI lag
 * on dense topo surveys and drone point clouds.
 *
 * Performance comparison:
 * - Canvas2D (ol/layer/Vector): 50K points = 3-5 seconds to render, laggy pan
 * - WebGL (ol/layer/WebGLPoints): 50K points = <100ms, smooth pan/zoom
 *
 * Features:
 * - Color interpolation by elevation (blue=low, red=high)
 * - Size scaling by zoom level
 * - Opacity control
 * - Dynamic style updates without re-rendering
 *
 * Usage:
 *   const layer = createWebGLPointsLayer(features, { elevationField: 'elevation' })
 *   map.addLayer(layer)
 */

import WebGLPointsLayer from 'ol/layer/WebGLPoints'
import VectorSource from 'ol/source/Vector'
import GeoJSON from 'ol/format/GeoJSON'
import Feature from 'ol/Feature'
import Point from 'ol/geom/Point'

export interface WebGLPointsOptions {
  /** Property name for elevation-based coloring */
  elevationField?: string
  /** Min elevation for color scale (default: auto-detect) */
  minElevation?: number
  /** Max elevation for color scale (default: auto-detect) */
  maxElevation?: number
  /** Point radius (default: 4) */
  pointRadius?: number
  /** Opacity (default: 0.8) */
  opacity?: number
  /** Stroke width (default: 1) */
  strokeWidth?: number
}

/**
 * Create a WebGL points layer from an array of features.
 *
 * @param features - Array of OpenLayers features with Point geometry
 * @param options - Styling options
 */
export function createWebGLPointsLayer(
  features: Feature<Point>[],
  options: WebGLPointsOptions = {},
): WebGLPointsLayer<VectorSource> {
  const {
    elevationField = 'elevation',
    minElevation,
    maxElevation,
    pointRadius = 4,
    opacity = 0.8,
    strokeWidth = 1,
  } = options

  // Auto-detect elevation range if not specified
  let minElev = minElevation ?? Infinity
  let maxElev = maxElevation ?? -Infinity

  if (minElevation == null || maxElevation == null) {
    for (const feature of features) {
      const elev = feature.get(elevationField)
      if (typeof elev === 'number') {
        minElev = Math.min(minElev, elev)
        maxElev = Math.max(maxElev, elev)
      }
    }
    if (!isFinite(minElev)) minElev = 0
    if (!isFinite(maxElev)) maxElev = 1000
  }

  const source = new VectorSource({ features })

  const layer = new WebGLPointsLayer({
    source,
    style: {
      'circle-radius': pointRadius,
      'circle-fill-color': [
        'interpolate',
        ['linear'],
        ['get', elevationField],
        minElev, '#0000FF',    // Low elevation: blue
        (minElev + maxElev) / 2, '#00FF00',  // Mid: green
        maxElev, '#FF0000',    // High elevation: red
      ],
      'circle-stroke-color': '#FFFFFF',
      'circle-stroke-width': strokeWidth,
      'circle-opacity': opacity,
    },
    disableHitDetection: false,
  })

  return layer
}

/**
 * Create a WebGL points layer from raw coordinate array.
 *
 * @param points - Array of { easting, northing, elevation }
 * @param options - Styling options
 */
export function createWebGLPointsFromCoords(
  points: Array<{ easting: number; northing: number; elevation?: number }>,
  options: WebGLPointsOptions = {},
): WebGLPointsLayer<VectorSource> {
  const features: Feature<Point>[] = points.map((pt, i) => {
    const feature = new Feature({
      geometry: new Point([pt.easting, pt.northing]),
    })
    feature.set('elevation', pt.elevation ?? 0)
    feature.set('index', i)
    return feature
  })

  return createWebGLPointsLayer(features, options)
}

/**
 * Create a WebGL points layer from GeoJSON.
 *
 * @param geojson - GeoJSON FeatureCollection with Point features
 * @param options - Styling options
 */
export function createWebGLPointsFromGeoJSON(
  geojson: string | object,
  options: WebGLPointsOptions = {},
): WebGLPointsLayer<VectorSource> {
  const format = new GeoJSON()
  const features = format.readFeatures(
    typeof geojson === 'string' ? geojson : JSON.stringify(geojson),
  ) as Feature<Point>[]

  return createWebGLPointsLayer(features, options)
}

/**
 * Update the style of an existing WebGL points layer.
 * Useful for changing color scale without recreating the layer.
 */
export function updateWebGLPointsStyle(
  layer: WebGLPointsLayer<VectorSource>,
  options: WebGLPointsOptions,
): void {
  const {
    elevationField = 'elevation',
    minElevation = 0,
    maxElevation = 1000,
    pointRadius = 4,
    opacity = 0.8,
    strokeWidth = 1,
  } = options

  // WebGL points layer doesn't support setStyle — recreate the style object
  // In practice, you'd recreate the layer or use the layer's style function
  ;(layer as any).setStyle({
    'circle-radius': pointRadius,
    'circle-fill-color': [
      'interpolate',
      ['linear'],
      ['get', elevationField],
      minElevation, '#0000FF',
      (minElevation + maxElevation) / 2, '#00FF00',
      maxElevation, '#FF0000',
    ],
    'circle-stroke-color': '#FFFFFF',
    'circle-stroke-width': strokeWidth,
    'circle-opacity': opacity,
  })
}

/**
 * AI Plan Checking Service
 * Phase 9 - Community Features
 * Automated survey plan review and compliance checking
 */

export interface PlanCheckInput {
  projectName: string
  surveyType: 'traverse' | 'leveling' | 'boundary' | 'topographic' | 'engineering' | 'mining' | 'hydrographic'
  country: 'kenya' | 'uganda' | 'tanzania' | 'nigeria' | 'ghana' | 'south_africa' | 'other'
  points: { name: string; easting: number; northing: number; elevation?: number }[]
  boundaries?: { from: string; to: string }[]
  controlPoints?: string[]
  metadata?: Record<string, unknown>
}

export interface PlanIssue {
  id: string
  severity: 'error' | 'warning' | 'info'
  category: 'precision' | 'compliance' | 'geometry' | 'documentation' | 'boundary' | 'closure'
  title: string
  description: string
  recommendation: string
  location?: string
  relatedPoints?: string[]
}

export interface PlanCheckResult {
  id: string
  input: PlanCheckInput
  checkedAt: number
  processingTime: number
  overallScore: number
  grade: 'excellent' | 'good' | 'acceptable' | 'needs_revision' | 'failed'
  issues: PlanIssue[]
  passed: boolean
  summary: string
  detailedReport: string
}

export interface ComplianceRule {
  id: string
  name: string
  description: string
  applicableTo: string[]
  severity: 'error' | 'warning'
  check: (input: PlanCheckInput) => PlanIssue | null
}

const complianceRules: ComplianceRule[] = [
  {
    id: 'min-points',
    name: 'Minimum Points Required',
    description: 'Survey must have at least 3 points for valid computation',
    applicableTo: ['traverse', 'boundary', 'topographic'],
    severity: 'error',
    check: (input) => {
      if (input.points.length < 3) {
        return {
          id: 'min-points',
          severity: 'error',
          category: 'documentation',
          title: 'Insufficient Points',
          description: `Only ${input.points.length} points provided. Minimum 3 required.`,
          recommendation: 'Add more survey points to create valid geometry.',
        }
      }
      return null
    }
  },
  {
    id: 'closure-check',
    name: 'Traverse Closure',
    description: 'Closed traverse must return to starting point',
    applicableTo: ['traverse'],
    severity: 'error',
    check: (input) => {
      if (input.boundaries && input.boundaries.length > 2) {
        const firstPoint = input.points[0]?.name
        const lastBoundary = input.boundaries[input.boundaries.length - 1]
        if (lastBoundary.to !== firstPoint) {
          return {
            id: 'closure-check',
            severity: 'warning',
            category: 'closure',
            title: 'Open Traverse Detected',
            description: 'Last point does not close to first point.',
            recommendation: 'This appears to be an open traverse. Ensure this is intentional.',
          }
        }
      }
      return null
    }
  },
  {
    id: 'coordinate-range',
    name: 'Coordinate Range Validation',
    description: 'Coordinates should be within reasonable UTM range',
    applicableTo: ['traverse', 'boundary', 'topographic', 'engineering'],
    severity: 'warning',
    check: (input) => {
      const invalidPoints = input.points.filter((p: any) => 
        p.easting < 100000 || p.easting > 900000 ||
        p.northing < 0 || p.northing > 10000000
      )
      if (invalidPoints.length > 0) {
        return {
          id: 'coordinate-range',
          severity: 'warning',
          category: 'geometry',
          title: 'Unusual Coordinate Range',
          description: `${invalidPoints.length} point(s) have unusual UTM coordinates.`,
          recommendation: 'Verify coordinate system (UTM zone) is correct.',
          relatedPoints: invalidPoints.map((p: any) => p.name),
        }
      }
      return null
    }
  },
  {
    id: 'control-points',
    name: 'Control Point Requirement',
    description: 'Boundary surveys should reference control points',
    applicableTo: ['boundary'],
    severity: 'warning',
    check: (input) => {
      if (input.surveyType === 'boundary' && (!input.controlPoints || input.controlPoints.length === 0)) {
        return {
          id: 'control-points',
          severity: 'warning',
          category: 'compliance',
          title: 'No Control Points Referenced',
          description: 'Boundary survey does not reference any control points.',
          recommendation: 'Include at least 2 known control points for boundary establishment.',
        }
      }
      return null
    }
  },
  {
    id: 'duplicate-points',
    name: 'Duplicate Point Detection',
    description: 'Check for duplicate point names',
    applicableTo: ['traverse', 'leveling', 'boundary', 'topographic', 'engineering'],
    severity: 'error',
    check: (input) => {
      const names = input.points.map((p: any) => p.name)
      const duplicates = names.filter((name, i) => names.indexOf(name) !== i)
      if (duplicates.length > 0) {
        return {
          id: 'duplicate-points',
          severity: 'error',
          category: 'documentation',
          title: 'Duplicate Point Names',
          description: `Found duplicate point names: ${Array.from(new Set(duplicates)).join(', ')}`,
          recommendation: 'Each point must have a unique name.',
        }
      }
      return null
    }
  },
]

const countryRequirements: Record<string, { precision: number; notes: string }> = {
  kenya: { precision: 5000, notes: 'Kenya Survey Act requirements' },
  uganda: { precision: 3000, notes: 'Uganda Survey Regulations' },
  tanzania: { precision: 3000, notes: 'Tanzania Land Survey Regulations' },
  nigeria: { precision: 2500, notes: 'Nigeria Survey Practice Regulations' },
  ghana: { precision: 3000, notes: 'Ghana Survey Act' },
  south_africa: { precision: 5000, notes: 'South Africa Survey Standards' },
  other: { precision: 3000, notes: 'International best practice' },
}

export function checkSurveyPlan(input: PlanCheckInput): PlanCheckResult {
  const startTime = Date.now()
  const issues: PlanIssue[] = []

  for (const rule of complianceRules) {
    if (rule.applicableTo.includes(input.surveyType)) {
      const issue = rule.check(input)
      if (issue) {
        issues.push(issue)
      }
    }
  }

  const errors = issues.filter((i: any) => i.severity === 'error')
  const warnings = issues.filter((i: any) => i.severity === 'warning')

  let overallScore = 100
  overallScore -= errors.length * 20
  overallScore -= warnings.length * 5

  let grade: PlanCheckResult['grade']
  if (overallScore >= 90) grade = 'excellent'
  else if (overallScore >= 75) grade = 'good'
  else if (overallScore >= 60) grade = 'acceptable'
  else if (overallScore >= 40) grade = 'needs_revision'
  else grade = 'failed'

  const summary = errors.length === 0 
    ? errors.length === 0 && warnings.length === 0 
      ? 'Survey plan passes all automated checks.' 
      : `Survey plan passed with ${warnings.length} warning(s).`
    : `Survey plan has ${errors.length} error(s) and ${warnings.length} warning(s).`

  const countryReq = countryRequirements[input.country] || countryRequirements.other
  
  const detailedReport = `
Survey Plan Analysis Report
===========================
Project: ${input.projectName}
Survey Type: ${input.surveyType}
Country: ${input.country.toUpperCase()}
Date: ${new Date().toLocaleDateString()}

Summary
-------
Overall Score: ${overallScore}/100
Grade: ${grade.toUpperCase()}
Issues Found: ${issues.length} (${errors.length} errors, ${warnings.length} warnings)

Country Requirements
-------------------
Minimum Precision: 1:${countryReq.precision}
Notes: ${countryReq.notes}

Points Analyzed: ${input.points.length}
${input.controlPoints ? `Control Points: ${input.controlPoints.length}` : ''}

Detailed Issues
---------------
${issues.map((issue, i) => `${i + 1}. [${issue.severity.toUpperCase()}] ${issue.title}
   ${issue.description}
   Recommendation: ${issue.recommendation}
`).join('\n')}
`.trim()

  return {
    id: `check-${Date.now()}`,
    input,
    checkedAt: Date.now(),
    processingTime: Date.now() - startTime,
    overallScore,
    grade,
    issues,
    passed: errors.length === 0,
    summary,
    detailedReport,
  }
}

export function getComplianceRules(): ComplianceRule[] {
  return complianceRules
}

export function getCountryRequirements(country: string) {
  return countryRequirements[country] || countryRequirements.other
}

