/**
 * Sync Service for Mobile Field Data
 * Handles upload when connectivity returns
 */

import { offlineStorage, SyncQueueItem, SyncStatus } from './offlineStorage'
import { createClient } from '@/lib/api-client/client'

class SyncService {
  private isOnline = typeof navigator !== 'undefined' ? navigator.onLine : true
  private syncInterval: NodeJS.Timeout | null = null
  private isSyncing = false

  constructor() {
    if (typeof window !== 'undefined') {
      window.addEventListener('online', () => this.handleOnline())
      window.addEventListener('offline', () => this.handleOffline())
    }
  }

  startAutoSync(intervalMs = 30000) {
    if (this.syncInterval) return

    this.syncInterval = setInterval(() => {
      if (this.isOnline && !this.isSyncing) {
        this.syncPending()
      }
    }, intervalMs)
  }

  stopAutoSync() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval)
      this.syncInterval = null
    }
  }

  private handleOnline() {
    this.isOnline = true
    this.syncPending()
  }

  private handleOffline() {
    this.isOnline = false
  }

  async syncPending(): Promise<{ synced: number; failed: number }> {
    if (this.isSyncing) return { synced: 0, failed: 0 }
    if (!this.isOnline) return { synced: 0, failed: 0 }

    this.isSyncing = true
    const items = await offlineStorage.getPendingSyncItems()

    let synced = 0
    let failed = 0

    for (const item of items) {
      try {
        await this.syncItem(item)
        synced++
      } catch (error) {
        failed++
        console.error('[Sync] Failed to sync item:', item.id, error)

        // Mark as failed after 3 retries
        if ((item.retryCount || 0) >= 3) {
          await offlineStorage.updateSyncStatus(
            item.id!,
            'failed',
            error instanceof Error ? error.message : 'Unknown error'
          )
        } else {
          await offlineStorage.updateSyncStatus(item.id!, 'pending')
        }
      }
    }

    this.isSyncing = false
    return { synced, failed }
  }

  private async syncItem(item: SyncQueueItem): Promise<void> {
    const dbClient = createClient()

    await offlineStorage.updateSyncStatus(item.id!, 'syncing')

    switch (item.type) {
      case 'field_observation':
        await this.syncObservation(dbClient, item)
        break
      case 'photo':
        await this.syncPhoto(dbClient, item)
        break
      case 'survey_point':
        await this.syncSurveyPoint(dbClient, item)
        break
    }

    await offlineStorage.updateSyncStatus(item.id!, 'synced')
    await offlineStorage.removeFromSyncQueue(item.id!)
  }

  private async syncObservation(dbClient: any, item: SyncQueueItem): Promise<void> {
    const { data, error } = await dbClient.from('survey_observations').insert({
      project_id: item.data.projectId,
      point_name: item.data.pointName,
      point_id: item.data.pointId,
      observation_type: item.data.observationType,
      northing: item.data.northing,
      easting: item.data.easting,
      elevation: item.data.elevation,
      latitude: item.data.latitude,
      longitude: item.data.longitude,
      accuracy: item.data.accuracy,
      satellites: item.data.satellites,
      solution_type: item.data.solutionType,
      hdop: item.data.hdop,
      vdop: item.data.vdop,
      pdop: item.data.pdop,
      instrument_height: item.data.instrumentHeight,
      rod_height: item.data.rodHeight,
      backsight: item.data.backsight,
      foresight: item.data.foresight,
      horizontal_angle: item.data.horizontalAngle,
      vertical_angle: item.data.verticalAngle,
      slope_distance: item.data.slopeDistance,
      temperature: item.data.temperature,
      pressure: item.data.pressure,
      humidity: item.data.humidity,
      weather: item.data.weather,
      notes: item.data.notes,
      observed_at: new Date(item.data.timestamp).toISOString(),
    })

    if (error) throw error

    // Mark observation as synced
    await offlineStorage.update('field_observations', item.data.id, { synced: true })
  }

  private async syncPhoto(dbClient: any, item: SyncQueueItem): Promise<void> {
    // First upload the image to storage
    const fileName = `field_photos/${item.data.projectId}/${item.data.id}.jpg`
    const base64Data = item.data.data.split(',')[1]
    const blob = Buffer.from(base64Data, 'base64')

    const { error: uploadError } = await dbClient.storage.from('survey-photos').upload(fileName, blob, {
      contentType: 'image/jpeg',
      upsert: false,
    })

    if (uploadError) throw uploadError

    // Then create the database record
    const { data: photoData, error } = await dbClient.from('field_photos').insert({
      project_id: item.data.projectId,
      point_id: item.data.pointId,
      point_name: item.data.pointName,
      storage_path: fileName,
      thumbnail: item.data.thumbnail,
      caption: item.data.caption,
      orientation: item.data.orientation,
      captured_at: new Date(item.data.timestamp).toISOString(),
    }).select().single()

    if (error) throw error

    await offlineStorage.update('photos', item.data.id, { synced: true, storagePath: fileName })
  }

  private async syncSurveyPoint(dbClient: any, item: SyncQueueItem): Promise<void> {
    const { error } = await dbClient.from('survey_points').upsert({
      id: item.data.id,
      project_id: item.data.projectId,
      name: item.data.name,
      easting: item.data.easting,
      northing: item.data.northing,
      elevation: item.data.elevation,
      is_control: item.data.isControl,
      description: item.data.description,
      observed_at: new Date(item.data.timestamp).toISOString(),
    })

    if (error) throw error
  }

  async forceSync(): Promise<{ synced: number; failed: number }> {
    return this.syncPending()
  }

  getSyncStatus(): { isOnline: boolean; isSyncing: boolean } {
    return { isOnline: this.isOnline, isSyncing: this.isSyncing }
  }
}

export const syncService = new SyncService()
export default syncService

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Instrumented Database Pool
// ──────────────────────────────────────────────────────────────────────────
// Wraps the pg Pool with Prometheus metrics tracking.
// Drop-in replacement for the standard Pool — all queries are automatically
// tracked for duration, status, and connection pool health.
//
// Usage:
//   // In src/lib/db/pool.ts, replace:
//   import { Pool } from 'pg';
//   // With:
//   import { createInstrumentedPool } from '@/lib/monitoring/instrumented-pool';
// ──────────────────────────────────────────────────────────────────────────

import { Pool, PoolClient, QueryResult, PoolConfig, QueryConfig } from 'pg';
import {
  dbQueryDuration,
  dbQueryTotal,
  dbPoolActiveConnections,
  dbPoolIdleConnections,
  dbPoolWaitingRequests,
} from './metrics';

export class InstrumentedPool {
  private pool: Pool;
  private metricsInterval: ReturnType<typeof setInterval> | null = null;

  constructor(config?: PoolConfig) {
    this.pool = new Pool(config);

    // Update pool gauges every 15 seconds
    this.metricsInterval = setInterval(() => {
      this.updatePoolGauges();
    }, 15000);

    // Track pool errors
    this.pool.on('error', (err) => {
      console.error('[InstrumentedPool] Unexpected error:', err);
      dbQueryTotal.inc({ operation: 'pool_error', table: 'unknown', status: 'error' });
    });
  }

  // ─── Query with Metrics ───────────────────────────────────────────────

  async query<T extends Record<string, unknown> = Record<string, unknown>>(
    text: string | QueryConfig,
    params?: unknown[]
  ): Promise<QueryResult<T>> {
    const operation = this.extractOperation(text);
    const table = this.extractTable(text);
    const labels = { operation, table };

    const timer = dbQueryDuration.startTimer(labels);
    const startTime = performance.now();

    try {
      const result = await this.pool.query<T>(text, params);
      const duration = (performance.now() - startTime) / 1000;

      timer();
      dbQueryTotal.inc({ ...labels, status: 'success' });

      // Log slow queries (> 250ms)
      if (duration > 0.25) {
        console.warn(`[SLOW QUERY] ${duration.toFixed(3)}s`, {
          operation,
          table,
          query: typeof text === 'string' ? text.substring(0, 200) : text.text?.substring(0, 200),
        });
      }

      return result;
    } catch (err) {
      timer();
      dbQueryTotal.inc({ ...labels, status: 'error' });
      throw err;
    }
  }

  // ─── Connection with Metrics ──────────────────────────────────────────

  async connect(): Promise<InstrumentedClient> {
    const client = await this.pool.connect();
    return new InstrumentedClient(client, this);
  }

  // ─── Pool Proxy Methods ───────────────────────────────────────────────

  get totalCount(): number {
    return this.pool.totalCount;
  }

  get idleCount(): number {
    return this.pool.idleCount;
  }

  get waitingCount(): number {
    return this.pool.waitingCount;
  }

  async end(): Promise<void> {
    if (this.metricsInterval) {
      clearInterval(this.metricsInterval);
      this.metricsInterval = null;
    }
    await this.pool.end();
  }

  on(event: 'error', listener: (err: Error, client: PoolClient) => void): this;
  on(event: 'connect' | 'acquire' | 'remove', listener: (client: PoolClient) => void): this;
  on(event: string, listener: (...args: any[]) => void): this {
    this.pool.on(event as any, listener);
    return this;
  }

  // ─── Internal ─────────────────────────────────────────────────────────

  private updatePoolGauges(): void {
    dbPoolActiveConnections.set(this.pool.totalCount - this.pool.idleCount);
    dbPoolIdleConnections.set(this.pool.idleCount);
    dbPoolWaitingRequests.set(this.pool.waitingCount);
  }

  private extractOperation(text: string | QueryConfig): string {
    const sql = typeof text === 'string' ? text : text.text || '';
    const trimmed = sql.trim().toUpperCase();

    if (trimmed.startsWith('SELECT')) return 'select';
    if (trimmed.startsWith('INSERT')) return 'insert';
    if (trimmed.startsWith('UPDATE')) return 'update';
    if (trimmed.startsWith('DELETE')) return 'delete';
    if (trimmed.startsWith('CREATE')) return 'create';
    if (trimmed.startsWith('ALTER')) return 'alter';
    if (trimmed.startsWith('DROP')) return 'drop';
    if (trimmed.startsWith('BEGIN')) return 'transaction';
    if (trimmed.startsWith('COMMIT')) return 'transaction';
    if (trimmed.startsWith('ROLLBACK')) return 'transaction';
    return 'other';
  }

  private extractTable(text: string | QueryConfig): string {
    const sql = typeof text === 'string' ? text : text.text || '';
    const trimmed = sql.trim().toUpperCase();

    // Common patterns: FROM table, INTO table, UPDATE table, JOIN table
    const patterns = [
      /(?:FROM|INTO|UPDATE|JOIN)\s+(?:"?(\w+)"?\.")?(\w+)/i,
    ];

    for (const pattern of patterns) {
      const match = trimmed.match(pattern);
      if (match) {
        return (match[2] || match[1]).toLowerCase();
      }
    }

    return 'unknown';
  }
}

// ─── Instrumented Client ─────────────────────────────────────────────────

export class InstrumentedClient {
  constructor(
    private client: PoolClient,
    private pool: InstrumentedPool,
  ) {}

  async query<T extends Record<string, unknown> = Record<string, unknown>>(
    text: string | QueryConfig,
    params?: unknown[]
  ): Promise<QueryResult<T>> {
    return this.pool.query<T>(text, params);
  }

  release(err?: Error): void {
    this.client.release(err);
  }

  // Removed invalid rowCount proxy
}

// ─── Factory ─────────────────────────────────────────────────────────────

let instance: InstrumentedPool | null = null;

export function createInstrumentedPool(config?: PoolConfig): InstrumentedPool {
  if (!instance) {
    instance = new InstrumentedPool(config);
  }
  return instance;
}

export function getInstrumentedPool(): InstrumentedPool | null {
  return instance;
}

type LogLevel = 'debug' | 'info' | 'warn' | 'error'

interface LogEntry {
  level: LogLevel
  message: string
  timestamp: string
  context?: Record<string, unknown>
  userId?: string
  error?: string
}

const LOG_ENDPOINT = process.env.NEXT_PUBLIC_LOG_ENDPOINT

class Logger {
  private logs: LogEntry[] = []
  private maxLogs = 100

  private createEntry(level: LogLevel, message: string, context?: Record<string, unknown>, userId?: string): LogEntry {
    const entry: LogEntry = {
      level,
      message,
      timestamp: new Date().toISOString(),
      context,
      userId
    }

    if (level === 'error' && context?.error) {
      entry.error = String(context.error)
    }

    return entry
  }

  private addEntry(entry: LogEntry) {
    this.logs.push(entry)
    if (this.logs.length > this.maxLogs) {
      this.logs.shift()
    }
  }

  public log(level: LogLevel, message: string, context?: Record<string, unknown>, userId?: string) {
    const entry = this.createEntry(level, message, context, userId)
    this.addEntry(entry)

    if (LOG_ENDPOINT && process.env.NODE_ENV === 'production') {
      this.sendToEndpoint(entry)
    }

    const prefix = `[${level.toUpperCase()}]`
    const msg = `${prefix} ${message}`
    switch (level) {
      case 'debug':
        break
      case 'info':
        console.info(msg, context || '')
        break
      case 'warn':
        console.warn(msg, context || '')
        break
      case 'error':
        console.error(msg, context || '')
        break
    }
  }

  private async sendToEndpoint(entry: LogEntry) {
    if (!LOG_ENDPOINT) return
    try {
      await fetch(LOG_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(entry),
        signal: AbortSignal.timeout(5000)
      })
    } catch {
      // Silently fail
    }
  }

  debug(message: string, context?: Record<string, unknown>) {
    this.log('debug', message, context)
  }

  info(message: string, context?: Record<string, unknown>) {
    this.log('info', message, context)
  }

  warn(message: string, context?: Record<string, unknown>) {
    this.log('warn', message, context)
  }

  error(message: string, context?: Record<string, unknown>) {
    this.log('error', message, context)
  }

  getLogs(): LogEntry[] {
    return [...this.logs]
  }

  clearLogs() {
    this.logs = []
  }
}

export const logger = new Logger()

export function logApiRequest(
  method: string,
  path: string,
  statusCode: number,
  duration: number,
  userId?: string
) {
  const level: LogLevel = statusCode >= 500 ? 'error' : statusCode >= 400 ? 'warn' : 'info'
  
  logger.log(level, `${method} ${path}`, {
    statusCode,
    duration,
    userId
  })
}

export function logUserAction(
  action: string,
  details: Record<string, unknown>,
  userId?: string
) {
  logger.info(`User action: ${action}`, details)
}

export function logError(
  error: Error | unknown,
  context?: Record<string, unknown>
) {
  logger.error('Error occurred', {
    error: error instanceof Error ? error.message : String(error),
    stack: error instanceof Error ? error.stack : undefined,
    ...context
  })
}

