// ──────────────────────────────────────────────────────────────────────────
// METARDU — Middleware Metrics Tracker
// ──────────────────────────────────────────────────────────────────────────
// Integrates with Next.js middleware to track HTTP request metrics.
//
// Usage — add to your existing middleware.ts:
//
//   import { withMetrics } from '@/lib/monitoring/middleware-tracker';
//
//   export async function middleware(request: NextRequest) {
//     return withMetrics(request, async () => {
//       // ... your existing middleware logic ...
//       return NextResponse.next();
//     });
//   }
// ──────────────────────────────────────────────────────────────────────────

import { NextRequest, NextResponse } from 'next/server';
import {
  httpRequestsTotal,
  httpRequestDuration,
  httpActiveRequests,
  httpRequestSize,
  httpResponseSize,
} from './metrics';

/**
 * Wrap a middleware handler with Prometheus metrics tracking.
 *
 * @param request - The incoming Next.js request
 * @param handler - Your middleware logic (must return a NextResponse)
 * @returns The response from the handler, with metrics recorded
 */
export async function withMetrics(
  request: NextRequest,
  handler: () => Promise<NextResponse>,
): Promise<NextResponse> {
  const method = request.method;
  const pathname = request.nextUrl.pathname;

  // Normalize path to avoid high cardinality labels
  // e.g., /projects/abc123 → /projects/[id]
  const normalizedPath = normalizePath(pathname);

  // Skip metrics for static assets and the metrics endpoint itself
  if (shouldSkipMetrics(pathname)) {
    return handler();
  }

  httpActiveRequests.inc();

  // Track request body size
  const contentLength = request.headers.get('content-length');
  if (contentLength) {
    httpRequestSize.observe({ method, path: normalizedPath }, parseInt(contentLength, 10));
  }

  const startTime = performance.now();

  try {
    const response = await handler();

    const duration = (performance.now() - startTime) / 1000;
    const statusCode = String(response.status);

    httpRequestsTotal.inc({ method, path: normalizedPath, status_code: statusCode });
    httpRequestDuration.observe({ method, path: normalizedPath, status_code: statusCode }, duration);

    // Track response size if available
    const responseContentLength = response.headers.get('content-length');
    if (responseContentLength) {
      httpResponseSize.observe({ method, path: normalizedPath }, parseInt(responseContentLength, 10));
    }

    return response;
  } catch (err) {
    const duration = (performance.now() - startTime) / 1000;

    httpRequestsTotal.inc({ method, path: normalizedPath, status_code: '500' });
    httpRequestDuration.observe({ method, path: normalizedPath, status_code: '500' }, duration);

    throw err;
  } finally {
    httpActiveRequests.dec();
  }
}

// ─── Path Normalization ──────────────────────────────────────────────────

/**
 * Normalize dynamic route segments to avoid high cardinality.
 *
 * Examples:
 *   /projects/abc123       → /projects/[id]
 *   /projects/abc123/edit  → /projects/[id]/edit
 *   /api/survey/audit?id=x → /api/survey/audit
 *   /users/123/profile     → /users/[id]/profile
 */
function normalizePath(pathname: string): string {
  // Skip static assets
  if (
    pathname.startsWith('/_next/') ||
    pathname.startsWith('/favicon') ||
    pathname.match(/\.(js|css|png|jpg|jpeg|gif|svg|ico|woff2?|ttf|eot)$/)
  ) {
    return '/_next/static';
  }

  // Normalize dynamic segments
  const segments = pathname.split('/').filter(Boolean);
  const normalized = segments.map((segment, index) => {
    // UUID pattern
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(segment)) {
      return '[id]';
    }
    // CUID pattern (starts with 'c')
    if (/^c[a-z0-9]{24,}$/i.test(segment)) {
      return '[id]';
    }
    // Pure numeric
    if (/^\d+$/.test(segment)) {
      return '[id]';
    }
    // Looks like a hash or encoded ID (long alphanumeric)
    if (segment.length > 20 && /^[a-zA-Z0-9_-]+$/.test(segment)) {
      return '[id]';
    }
    return segment;
  });

  return '/' + normalized.join('/');
}

// ─── Skip Conditions ─────────────────────────────────────────────────────

function shouldSkipMetrics(pathname: string): boolean {
  return (
    pathname === '/api/public/metrics' ||    // Don't track the metrics endpoint itself
    pathname.startsWith('/_next/') ||         // Static assets
    pathname.startsWith('/favicon') ||
    pathname.match(/\.(js|css|png|jpg|jpeg|gif|svg|ico|woff2?|ttf|eot)$/) !== null
  );
}

/**
 * Sentry monitoring integration for Metardu.
 *
 * In production (NEXT_PUBLIC_SENTRY_DSN set), errors are sent to Sentry.
 * In development, all capture functions log to console instead.
 *
 * Special tags:
 * - ai_error: NVIDIA API errors
 * - db_error: PostgreSQL errors
 * - payment_error: Payment processing errors
 */

import * as Sentry from '@sentry/nextjs'

const SENTRY_DSN = process.env.NEXT_PUBLIC_SENTRY_DSN
const SENTRY_ENVIRONMENT = process.env.NEXT_PUBLIC_SENTRY_ENVIRONMENT || 'production'

const isProduction = () => !!SENTRY_DSN && !SENTRY_DSN.includes('mockup')

export function initSentry() {
  if (isProduction() && process.env.NODE_ENV === 'production') {
    Sentry.init({
      dsn: SENTRY_DSN,
      environment: SENTRY_ENVIRONMENT,
      tracesSampleRate: 0.1,
      replaysSessionSampleRate: 0.1,
      replaysOnErrorSampleRate: 1.0,
      beforeSend(event) {
        // Scrub any API keys that might leak into error messages
        if (event.request?.headers) {
          delete event.request.headers['Authorization']
          delete event.request.headers['authorization']
        }
        // Scrub from exception messages
        if (event.exception?.values) {
          for (const exc of event.exception.values) {
            if (exc.value) {
              exc.value = exc.value
                .replace(/nvapi-[A-Za-z0-9_-]+/g, 'nvapi-[REDACTED]')
                .replace(/Bearer [A-Za-z0-9_-]+/g, 'Bearer [REDACTED]')
            }
          }
        }
        return event
      },
    })
  }
}

export function captureError(error: Error, context?: Record<string, unknown>) {
  if (isProduction()) {
    Sentry.captureException(error, { extra: context })
  } else {
    console.error('[sentry] Error captured:', error, context)
  }
}

export function captureMessage(message: string, level: Sentry.SeverityLevel = 'info') {
  if (isProduction()) {
    Sentry.captureMessage(message, level)
  } else {
  }
}

export function setUser(user: { id: string; email?: string; username?: string } | null) {
  if (isProduction()) {
    Sentry.setUser(user)
  }
}

export function addBreadcrumb(breadcrumb: {
  category?: string
  message: string
  level?: Sentry.SeverityLevel
  data?: Record<string, unknown>
}) {
  if (isProduction()) {
    Sentry.addBreadcrumb(breadcrumb)
  }
}

/** Capture AI-specific errors with structured context */
export function captureAiError(error: Error, context: {
  action: string
  model?: string
  userId?: string
  latencyMs?: number
  httpStatus?: number
}) {
  if (isProduction()) {
    Sentry.withScope((scope) => {
      scope.setTag('ai_error', 'true')
      scope.setTag('ai_action', context.action)
      if (context.model) scope.setTag('ai_model', context.model)
      if (context.httpStatus) scope.setTag('http_status', String(context.httpStatus))
      scope.setExtra('latencyMs', context.latencyMs)
      if (context.userId) scope.setUser({ id: context.userId })
      Sentry.captureException(error)
    })
  } else {
    console.error(`[sentry] AI error (${context.action}):`, error.message, context)
  }
}

export { Sentry }

/**
 * Distributed Tracing — OpenTelemetry-style trace context propagation
 *
 * ByteByteGo audit fix: Add distributed tracing between Next.js and Python worker.
 *
 * WHAT THIS DOES
 * --------------
 * 1. Generates a trace ID for every incoming request (if not from upstream)
 * 2. Propagates the trace ID to the Python worker via X-Trace-Id header
 * 3. Propagates the trace ID to outbound fetch calls (Stripe, M-Pesa, etc.)
 * 4. The Python worker logs the trace ID, enabling end-to-end request tracing
 * 5. Sentry is configured with the same trace ID for cross-referencing
 *
 * This implements the W3C Trace Context standard (traceparent header):
 *   traceparent: 00-{trace-id}-{span-id}-{flags}
 *
 * USAGE
 * -----
 * // In API routes:
 * import { getTraceContext, traceFetch } from '@/lib/monitoring/tracing'
 * const trace = getTraceContext(request)
 * const response = await traceFetch('https://api.stripe.com/...', { ... }, trace)
 *
 * // In Python worker calls:
 * const response = await traceFetch(`${PYTHON_WORKER_URL}/osm/features`, { ... }, trace)
 */

import { randomUUID } from 'crypto'
import type { NextRequest } from 'next/server'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface TraceContext {
  traceId: string
  spanId: string
  parentSpanId?: string
  sampled: boolean
}

// ─── Trace Context Extraction & Generation ──────────────────────────────────

/**
 * Extract trace context from an incoming request.
 *
 * Checks for W3C traceparent header first, then falls back to X-Trace-Id.
 * If no trace context is found, generates a new one.
 */
export function getTraceContext(request?: NextRequest | Request): TraceContext {
  // Try W3C traceparent header first
  const traceparent = request?.headers.get('traceparent')
  if (traceparent) {
    const parts = traceparent.split('-')
    if (parts.length === 4 && parts[0] === '00') {
      return {
        traceId: parts[1],
        spanId: randomUUID().replace(/-/g, '').slice(0, 16),
        parentSpanId: parts[2],
        sampled: parts[3] === '01',
      }
    }
  }

  // Fall back to X-Trace-Id (simpler, used by our Python worker)
  const existingTraceId = request?.headers.get('x-trace-id')
  if (existingTraceId) {
    return {
      traceId: existingTraceId,
      spanId: randomUUID().replace(/-/g, '').slice(0, 16),
      sampled: true,
    }
  }

  // Generate new trace context
  return {
    traceId: randomUUID().replace(/-/g, ''),
    spanId: randomUUID().replace(/-/g, '').slice(0, 16),
    sampled: true,
  }
}

/**
 * Format a traceparent header for outbound requests.
 */
export function formatTraceparent(trace: TraceContext): string {
  return `00-${trace.traceId}-${trace.spanId}-${trace.sampled ? '01' : '00'}`
}

/**
 * Get trace headers to add to outbound requests.
 */
export function getTraceHeaders(trace: TraceContext): Record<string, string> {
  return {
    'traceparent': formatTraceparent(trace),
    'x-trace-id': trace.traceId,
    'x-span-id': trace.spanId,
  }
}

// ─── Traced Fetch Wrapper ───────────────────────────────────────────────────

/**
 * Fetch with trace context propagation.
 *
 * Automatically adds traceparent and X-Trace-Id headers to outbound requests.
 * If no trace context is provided, generates a new one (root span).
 *
 * Usage:
 *   const trace = getTraceContext(request)
 *   const res = await traceFetch('https://api.stripe.com/...', { method: 'POST', ... }, trace)
 */
export async function traceFetch(
  url: string,
  options: RequestInit = {},
  trace?: TraceContext,
): Promise<Response> {
  const ctx = trace || getTraceContext()

  const headers = new Headers(options.headers)
  const traceHeaders = getTraceHeaders(ctx)
  for (const [key, value] of Object.entries(traceHeaders)) {
    headers.set(key, value)
  }

  const startTime = performance.now()

  try {
    const response = await fetch(url, { ...options, headers })

    // Record metrics for this outbound call
    const duration = performance.now() - startTime
    recordOutboundSpan(url, ctx, response.status, duration)

    return response
  } catch (err) {
    const duration = performance.now() - startTime
    recordOutboundSpan(url, ctx, 0, duration, err instanceof Error ? err.message : 'Unknown')
    throw err
  }
}

// ─── Span Recording (for /metrics endpoint) ─────────────────────────────────

interface SpanRecord {
  url: string
  traceId: string
  spanId: string
  status: number
  durationMs: number
  error?: string
  timestamp: number
}

const recentSpans: SpanRecord[] = []
const MAX_SPANS = 1000

function recordOutboundSpan(
  url: string,
  trace: TraceContext,
  status: number,
  durationMs: number,
  error?: string,
) {
  recentSpans.push({
    url: url.substring(0, 200),  // truncate long URLs
    traceId: trace.traceId,
    spanId: trace.spanId,
    status,
    durationMs,
    error,
    timestamp: Date.now(),
  })

  if (recentSpans.length > MAX_SPANS) {
    recentSpans.shift()
  }
}

/**
 * Get recent outbound spans (for debugging / /metrics endpoint).
 */
export function getRecentSpans(): SpanRecord[] {
  return [...recentSpans].reverse()  // most recent first
}

/**
 * Get span statistics for /metrics endpoint.
 */
export function getSpanStats(): {
  totalSpans: number
  errorSpans: number
  avgDurationMs: number
  p90DurationMs: number
  p99DurationMs: number
} {
  if (recentSpans.length === 0) {
    return { totalSpans: 0, errorSpans: 0, avgDurationMs: 0, p90DurationMs: 0, p99DurationMs: 0 }
  }

  const durations = recentSpans.map(s => s.durationMs).sort((a, b) => a - b)
  const errors = recentSpans.filter(s => s.status >= 400 || s.error).length
  const avg = durations.reduce((s, v) => s + v, 0) / durations.length
  const p90 = durations[Math.floor(durations.length * 0.9)]
  const p99 = durations[Math.floor(durations.length * 0.99)]

  return {
    totalSpans: recentSpans.length,
    errorSpans: errors,
    avgDurationMs: Math.round(avg),
    p90DurationMs: Math.round(p90),
    p99DurationMs: Math.round(p99),
  }
}

// ─── Sentry Integration ─────────────────────────────────────────────────────

/**
 * Set the trace context on Sentry for cross-referencing.
 */
export function setSentryTraceContext(trace: TraceContext) {
  try {
    import('@/lib/monitoring/sentry').then(({ setUser, addBreadcrumb }) => {
      addBreadcrumb({
        category: 'trace',
        message: `Trace ${trace.traceId}`,
        level: 'info',
        data: { traceId: trace.traceId, spanId: trace.spanId },
      })
    }).catch(() => {})
  } catch {}
}

/**
 * Africa's Talking SMS/WhatsApp notification service for METARDU.
 *
 * SMS and WhatsApp notifications via Africa's Talking API (africastalking.com).
 * Used for:
 *   - Survey lock/approval alerts
 *   - Submission status updates
 *   - Peer review notifications
 *   - System alerts (subscription expiry, etc.)
 *
 * Environment variables:
 *   AFRICASTALKING_USERNAME    — Africa's Talking username
 *   AFRICASTALKING_API_KEY    — Africa's Talking API key
 *   AFRICASTALKING_SENDER_ID  — Registered sender ID (or defaults to sandbox)
 *   AFRICASTALKING_ENABLED    — 'true' to enable, any other value to disable
 */

import { env } from '@/lib/env'

// ── Types ──────────────────────────────────────────────────────

export type NotificationChannel = 'sms' | 'whatsapp'

export interface NotificationPayload {
  to: string           // Phone number in E.164 format (e.g. +254712345678)
  channel: NotificationChannel
  message: string
  reference?: string   // Optional reference ID for tracking (e.g. projectId)
}

export interface NotificationResult {
  success: boolean
  messageId?: string
  cost?: string
  error?: string
}

export type NotificationEventType =
  | 'project:locked'
  | 'project:submitted'
  | 'peer_review:assigned'
  | 'peer_review:completed'
  | 'subscription:expiring'
  | 'subscription:expired'
  | 'system:maintenance'

// ── Templates ──────────────────────────────────────────────────

const TEMPLATES: Record<NotificationEventType, (data: Record<string, string>) => string> = {
  'project:locked': (d) =>
    `METARDU: Project "${d.projectName}" (LR ${d.lrNumber || 'N/A'}) has been approved and locked by ${d.surveyorName}. Seal: ${d.seal?.substring(0, 12)}...`,

  'project:submitted': (d) =>
    `METARDU: Submission for "${d.projectName}" (LR ${d.lrNumber || 'N/A'}) has been submitted for review.`,

  'peer_review:assigned': (d) =>
    `METARDU: You have been assigned a peer review for "${d.projectName}" by ${d.surveyorName}. Please log in to review.`,

  'peer_review:completed': (d) =>
    `METARDU: Peer review for "${d.projectName}" is complete. Verdict: ${d.verdict}.`,

  'subscription:expiring': (d) =>
    `METARDU: Your ${d.plan} subscription expires in ${d.daysRemaining} days. Renew to avoid service interruption.`,

  'subscription:expired': (d) =>
    `METARDU: Your ${d.plan} subscription has expired. Your data is safe — renew to regain full access.`,

  'system:maintenance': (d) =>
    `METARDU: Scheduled maintenance on ${d.date} from ${d.startTime} to ${d.endTime}. Expect brief downtime.`,
}

// ── Service ────────────────────────────────────────────────────

function isConfigured(): boolean {
  return !!(env.AFRICASTALKING_USERNAME && env.AFRICASTALKING_API_KEY)
}

function isEnabled(): boolean {
  if (env.AFRICASTALKING_ENABLED === 'true' && isConfigured()) return true
  // In development, allow when configured but not explicitly enabled
  if (process.env.NODE_ENV === 'development' && isConfigured()) return true
  return false
}

/**
 * Send an SMS via Africa's Talking.
 */
export async function sendSMS(to: string, message: string): Promise<NotificationResult> {
  if (!isEnabled()) {
    return { success: true, messageId: 'dev-skip', error: 'Notifications disabled' }
  }

  try {
    const username = env.AFRICASTALKING_USERNAME!
    const apiKey = env.AFRICASTALKING_API_KEY!
    const senderId = env.AFRICASTALKING_SENDER_ID || 'METARDU'

    // Africa's Talking SMS API v1
    const response = await fetch('https://api.africastalking.com/v1/messaging', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'apikey': apiKey,
        'Accept': 'application/json',
      },
      body: new URLSearchParams({
        username,
        to,
        message,
        from: senderId,
      }).toString(),
    })

    const data = await response.json()

    if (data.SMSMessageData?.Recipients?.length > 0) {
      const recipient = data.SMSMessageData.Recipients[0]
      return {
        success: recipient.status === 'Success',
        messageId: recipient.messageId,
        cost: recipient.cost,
        error: recipient.status !== 'Success' ? recipient.status : undefined,
      }
    }

    return { success: false, error: JSON.stringify(data) }
  } catch (err: unknown) {
    const msg = err instanceof Error ? (err as Error).message : 'Unknown error'
    console.error('[Notification] SMS send failed:', msg)
    return { success: false, error: msg }
  }
}

/**
 * Send a WhatsApp message via Africa's Talking.
 */
export async function sendWhatsApp(to: string, message: string): Promise<NotificationResult> {
  if (!isEnabled()) {
    return { success: true, messageId: 'dev-skip', error: 'Notifications disabled' }
  }

  try {
    const username = env.AFRICASTALKING_USERNAME!
    const apiKey = env.AFRICASTALKING_API_KEY!

    // Africa's Talking WhatsApp sandbox API
    const response = await fetch(`https://api.africastalking.com/v1/africastalking/${username}/messages`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'apikey': apiKey,
        'Accept': 'application/json',
      },
      body: JSON.stringify({
        to: `whatsapp:${to}`,
        type: 'text',
        message,
      }),
    })

    const data = await response.json()
    const msgId = (data as Record<string, unknown>).messageId as string | undefined

    if ((data as Record<string, unknown>).status === 'Success' || msgId) {
      return {
        success: true,
        messageId: msgId,
      }
    }

    return { success: false, error: JSON.stringify(data) }
  } catch (err: unknown) {
    const msg = err instanceof Error ? (err as Error).message : 'Unknown error'
    console.error('[Notification] WhatsApp send failed:', msg)
    return { success: false, error: msg }
  }
}

/**
 * Send a notification through the specified channel.
 */
export async function sendNotification(payload: NotificationPayload): Promise<NotificationResult> {
  if (payload.channel === 'whatsapp') {
    return sendWhatsApp(payload.to, payload.message)
  }
  return sendSMS(payload.to, payload.message)
}

/**
 * Convenience: send a templated notification.
 */
export async function sendTemplatedNotification(
  eventType: NotificationEventType,
  to: string,
  channel: NotificationChannel = 'sms',
  templateData: Record<string, string> = {},
): Promise<NotificationResult> {
  const templateFn = TEMPLATES[eventType]
  if (!templateFn) {
    return { success: false, error: `Unknown notification event type: ${eventType}` }
  }

  const message = templateFn(templateData)
  return sendNotification({ to, channel, message, reference: templateData.projectId })
}

/**
 * Notify project team when a project is approved & locked.
 * Sends to the project surveyor's phone number if available.
 */
export async function notifyProjectLocked(data: {
  projectName: string
  lrNumber?: string
  surveyorName: string
  surveyorPhone?: string
  seal?: string
  projectId?: string
}): Promise<void> {
  if (!data.surveyorPhone) return

  await sendTemplatedNotification('project:locked', data.surveyorPhone, 'sms', {
    projectName: data.projectName,
    lrNumber: data.lrNumber || '',
    surveyorName: data.surveyorName,
    seal: data.seal || '',
    projectId: data.projectId || '',
  })
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Offline IndexedDB Database Layer
// ──────────────────────────────────────────────────────────────────────────
// Provides persistent offline storage for field book data when surveyors
// work in areas without connectivity (rural Kenya, underground mines, etc).
//
// Stores: observations, stations, measurements, project snapshots
// Syncs: queued entries pushed to server when back online
// ──────────────────────────────────────────────────────────────────────────

import { openDB, IDBPDatabase, DBSchema } from 'idb';

// ─── Schema Definition ───────────────────────────────────────────────────

export interface OfflineObservation {
  id: string;
  surveyId: string;
  projectId: string;
  fromStationId: string;
  toStationId: string;
  rawHorizontalAngle: number | null;
  rawVerticalAngle: number | null;
  rawSlopeDistance: number | null;
  temperature: number | null;
  pressure: number | null;
  humidity: number | null;
  instrumentHeight: number | null;
  targetHeight: number | null;
  edmConstant: number | null;
  ppmSetting: number | null;
  observationDate: string | null;
  createdAt: number;       // epoch ms — when recorded offline
  updatedAt: number;
  synced: boolean;
  syncAttempts: number;
  lastSyncError: string | null;
}

export interface OfflineStation {
  id: string;
  surveyId: string;
  projectId: string;
  name: string;
  type: 'TRAVERSE' | 'CONTROL' | 'BEACON' | 'BENCHMARK';
  order: number;
  createdAt: number;
  synced: boolean;
}

export interface OfflineProjectSnapshot {
  projectId: string;
  data: unknown;
  cachedAt: number;
  expiresAt: number;
}

export interface OfflineMediaAttachment {
  id: string;
  observationId: string;
  type: 'beacon_photo' | 'field_sketch' | 'gnss_log';
  blob: Blob;
  filename: string;
  mimeType: string;
  createdAt: number;
  synced: boolean;
}

export interface SyncQueueEntry {
  id: string;
  operation: 'create' | 'update' | 'delete';
  entity: 'observation' | 'station' | 'media';
  entityId: string;
  payload: unknown;
  createdAt: number;
  attempts: number;
  lastError: string | null;
  priority: number; // lower = higher priority
}

interface MetarduOfflineDB extends DBSchema {
  observations: {
    key: string;
    value: OfflineObservation;
    indexes: {
      'by-survey': string;
      'by-project': string;
      'by-synced': number;
      'by-created': number;
    };
  };
  stations: {
    key: string;
    value: OfflineStation;
    indexes: {
      'by-survey': string;
      'by-synced': number;
    };
  };
  cache: {
    key: string;
    value: OfflineProjectSnapshot;
    indexes: {
      'by-expiry': number;
    };
  };
  media: {
    key: string;
    value: OfflineMediaAttachment;
    indexes: {
      'by-observation': string;
      'by-synced': number;
    };
  };
  syncQueue: {
    key: string;
    value: SyncQueueEntry;
    indexes: {
      'by-priority': [number, number]; // [priority, createdAt]
      'by-entity': string;
    };
  };
  meta: {
    key: string;
    value: { key: string; value: unknown };
  };
}

// ─── Database Singleton ──────────────────────────────────────────────────

const DB_NAME = 'metardu-offline';
const DB_VERSION = 2;

let dbInstance: IDBPDatabase<MetarduOfflineDB> | null = null;

export async function getOfflineDB(): Promise<IDBPDatabase<MetarduOfflineDB>> {
  if (dbInstance) return dbInstance;

  dbInstance = await openDB<MetarduOfflineDB>(DB_NAME, DB_VERSION, {
    upgrade(db, oldVersion, newVersion) {
      // ── Version 1: Core stores ──
      if (oldVersion < 1) {
        const obsStore = db.createObjectStore('observations', { keyPath: 'id' });
        obsStore.createIndex('by-survey', 'surveyId');
        obsStore.createIndex('by-project', 'projectId');
        obsStore.createIndex('by-synced', 'synced');
        obsStore.createIndex('by-created', 'createdAt');

        const stationStore = db.createObjectStore('stations', { keyPath: 'id' });
        stationStore.createIndex('by-survey', 'surveyId');
        stationStore.createIndex('by-synced', 'synced');

        const cacheStore = db.createObjectStore('cache', { keyPath: 'projectId' });
        cacheStore.createIndex('by-expiry', 'expiresAt');

        const syncStore = db.createObjectStore('syncQueue', { keyPath: 'id' });
        syncStore.createIndex('by-priority', ['priority', 'createdAt']);
        syncStore.createIndex('by-entity', 'entity');

        db.createObjectStore('meta', { keyPath: 'key' });
      }

      // ── Version 2: Media attachments ──
      if (oldVersion < 2) {
        if (!db.objectStoreNames.contains('media')) {
          const mediaStore = db.createObjectStore('media', { keyPath: 'id' });
          mediaStore.createIndex('by-observation', 'observationId');
          mediaStore.createIndex('by-synced', 'synced');
        }
      }
    },
  });

  return dbInstance;
}

// ─── Cleanup Utilities ───────────────────────────────────────────────────

/**
 * Purge expired cache entries and already-synced data older than maxAgeDays.
 */
export async function purgeStaleData(maxAgeDays: number = 30): Promise<{
  purgedObservations: number;
  purgedCache: number;
  purgedMedia: number;
}> {
  const db = await getOfflineDB();
  const cutoff = Date.now() - maxAgeDays * 24 * 60 * 60 * 1000;
  let purgedObservations = 0;
  let purgedCache = 0;
  let purgedMedia = 0;

  // Purge synced observations older than cutoff
  const tx = db.transaction(['observations', 'cache', 'media'], 'readwrite');

  const syncedObs = await tx.objectStore('observations').index('by-synced').getAll(IDBKeyRange.bound(0, 1));
  for (const obs of syncedObs) {
    if (obs.synced && obs.createdAt < cutoff) {
      await tx.objectStore('observations').delete(obs.id);
      purgedObservations++;
    }
  }

  // Purge expired cache
  const allCache = await tx.objectStore('cache').index('by-expiry').getAll();
  for (const entry of allCache) {
    if (entry.expiresAt < Date.now()) {
      await tx.objectStore('cache').delete(entry.projectId);
      purgedCache++;
    }
  }

  // Purge synced media older than cutoff
  const syncedMedia = await tx.objectStore('media').index('by-synced').getAll(IDBKeyRange.bound(0, 1));
  for (const m of syncedMedia) {
    if (m.synced && m.createdAt < cutoff) {
      await tx.objectStore('media').delete(m.id);
      purgedMedia++;
    }
  }

  await tx.done;

  return { purgedObservations, purgedCache, purgedMedia };
}

/**
 * Get storage usage estimate (navigator.storage API).
 */
export async function getStorageEstimate(): Promise<{
  usageMB: number;
  quotaMB: number;
  percentUsed: number;
} | null> {
  if (!navigator.storage?.estimate) return null;
  const { usage = 0, quota = 0 } = await navigator.storage.estimate();
  return {
    usageMB: Math.round(usage / 1024 / 1024 * 100) / 100,
    quotaMB: Math.round(quota / 1024 / 1024),
    percentUsed: quota > 0 ? Math.round((usage / quota) * 10000) / 100 : 0,
  };
}

/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * METARDU Offline Field Book — IndexedDB-backed field data collection
 * ═══════════════════════════════════════════════════════════════════════════════
 *
 * Works offline in rural Kenya (no 4G). Observations are stored in IndexedDB
 * and synced to PostgreSQL when connectivity returns.
 *
 * The surveyor's workflow becomes:
 *   1. Open field book on phone/tablet in the field (offline)
 *   2. Record observations (traverse stations, levels, topo points)
 *   3. Return to office → data auto-syncs to METARDU server
 *   4. Compute → Review → Submit
 *
 * No instrument software needed. No pen-and-paper. No Excel.
 */

import { openDB, type IDBPDatabase } from 'idb'

const DB_NAME = 'metardu-fieldbook'
const DB_VERSION = 1

// ─── Types ─────────────────────────────────────────────────────────────────

export type ObservationType = 'traverse' | 'leveling' | 'topo' | 'gnss' | 'hydro' | 'mining'

export interface OfflineObservation {
  id: string                  // UUID generated client-side
  projectId: string
  surveyType: ObservationType
  station: string             // Station name/number
  backsight?: string          // BS station
  foresight?: string          // FS station
  // Traverse fields
  bearingDeg?: number
  bearingMin?: number
  bearingSec?: number
  slopeDistance?: number
  horizontalDistance?: number
  verticalAngle?: number
  // Leveling fields
  backsightReading?: number   // BS staff reading
  foresightReading?: number   // FS staff reading
  // Topo fields
  easting?: number
  northing?: number
  elevation?: number
  // GNSS fields
  latitude?: number
  longitude?: number
  // Metadata
  notes?: string
  photoUrl?: string           // local blob URL (stored separately in IndexedDB)
  createdAt: string           // ISO timestamp
  syncedAt: string | null     // null = not yet synced
  syncError?: string          // last sync error message
}

export interface OfflineProject {
  id: string
  name: string
  surveyType: ObservationType
  createdAt: string
  lastModifiedAt: string
}

// ─── Database Schema ───────────────────────────────────────────────────────

interface FieldBookDB {
  observations: OfflineObservation[]
  projects: OfflineProject[]
  photos: { id: string; blob: Blob }
}

let dbPromise: Promise<IDBPDatabase<FieldBookDB>> | null = null

function getDB(): Promise<IDBPDatabase<FieldBookDB>> {
  if (!dbPromise) {
    dbPromise = openDB<FieldBookDB>(DB_NAME, DB_VERSION, {
      upgrade(db) {
        const obsStore = db.createObjectStore('observations', { keyPath: 'id' })
        obsStore.createIndex('byProject', 'projectId')
        obsStore.createIndex('bySync', 'syncedAt')
        obsStore.createIndex('byProjectType', ['projectId', 'surveyType'])

        const projStore = db.createObjectStore('projects', { keyPath: 'id' })
        projStore.createIndex('byModified', 'lastModifiedAt')

        db.createObjectStore('photos', { keyPath: 'id' })
      },
    })
  }
  return dbPromise
}

// ─── Observation CRUD ──────────────────────────────────────────────────────

export async function saveObservation(obs: OfflineObservation): Promise<void> {
  const db = await getDB()
  await db.put('observations', obs)
}

export async function getObservations(projectId: string, surveyType?: ObservationType): Promise<OfflineObservation[]> {
  const db = await getDB()
  if (surveyType) {
    return db.getAllFromIndex('observations', 'byProjectType', [projectId, surveyType])
  }
  return db.getAllFromIndex('observations', 'byProject', projectId)
}

export async function deleteObservation(id: string): Promise<void> {
  const db = await getDB()
  await db.delete('observations', id)
}

export async function getUnsyncedObservations(): Promise<OfflineObservation[]> {
  const db = await getDB()
  // ponytail: getAllFromIndex with null — IndexedDB doesn't support querying
  // for null values directly. Get all and filter. For a few hundred observations
  // this is fine; for thousands, add a separate 'unsynced' store.
  const all = await db.getAll('observations')
  return all.filter(o => o.syncedAt === null)
}

// ─── Photo Storage ─────────────────────────────────────────────────────────

export async function savePhoto(id: string, blob: Blob): Promise<void> {
  const db = await getDB()
  await db.put('photos', { id, blob })
}

export async function getPhoto(id: string): Promise<Blob | null> {
  const db = await getDB()
  const result = await db.get('photos', id)
  return result?.blob ?? null
}

// ─── Sync ──────────────────────────────────────────────────────────────────

export async function syncObservations(): Promise<{ synced: number; failed: number; errors: string[] }> {
  const unsynced = await getUnsyncedObservations()
  if (unsynced.length === 0) return { synced: 0, failed: 0, errors: [] }

  let synced = 0
  let failed = 0
  const errors: string[] = []

  for (const obs of unsynced) {
    try {
      const res = await fetch('/api/fieldbook/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(obs),
      })

      if (res.ok) {
        obs.syncedAt = new Date().toISOString()
        obs.syncError = undefined
        await saveObservation(obs)
        synced++
      } else {
        const err = await res.json().catch(() => ({ error: 'Unknown error' }))
        obs.syncError = err.error || `HTTP ${res.status}`
        await saveObservation(obs)
        failed++
        errors.push(`${obs.station}: ${obs.syncError}`)
      }
    } catch (err) {
      // Network error — will retry on next sync cycle
      obs.syncError = err instanceof Error ? err.message : 'Network error'
      await saveObservation(obs)
      failed++
      errors.push(`${obs.station}: ${obs.syncError}`)
    }
  }

  return { synced, failed, errors }
}

// ─── Connectivity ──────────────────────────────────────────────────────────

export function isOnline(): boolean {
  return navigator.onLine
}

export function onConnectivityChange(callback: (online: boolean) => void): () => void {
  const handleOnline = () => callback(true)
  const handleOffline = () => callback(false)
  window.addEventListener('online', handleOnline)
  window.addEventListener('offline', handleOffline)
  return () => {
    window.removeEventListener('online', handleOnline)
    window.removeEventListener('offline', handleOffline)
  }
}

// ─── Auto-sync ─────────────────────────────────────────────────────────────

let syncInterval: ReturnType<typeof setInterval> | null = null

export function startAutoSync(intervalMs = 30000): void {
  if (syncInterval) return

  // Sync immediately on start
  syncObservations().catch(console.error)

  // Sync on connectivity restore
  const unsubscribe = onConnectivityChange((online) => {
    if (online) syncObservations().catch(console.error)
  })

  // Sync periodically
  syncInterval = setInterval(() => {
    if (isOnline()) {
      syncObservations().catch(console.error)
    }
  }, intervalMs)

  // Store unsubscribe for cleanup
  ;(startAutoSync as unknown as { _unsubscribe?: () => void })._unsubscribe = unsubscribe
}

export function stopAutoSync(): void {
  if (syncInterval) {
    clearInterval(syncInterval)
    syncInterval = null
  }
  const unsub = (startAutoSync as unknown as { _unsubscribe?: () => void })._unsubscribe
  if (unsub) {
    unsub()
    ;(startAutoSync as unknown as { _unsubscribe?: () => void })._unsubscribe = undefined
  }
}

// ─── Utility ───────────────────────────────────────────────────────────────

export function generateId(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID()
  }
  return `obs-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`
}

export async function getSyncStatus(): Promise<{ total: number; unsynced: number; synced: number }> {
  const db = await getDB()
  const all = await db.getAll('observations')
  const unsynced = all.filter(o => o.syncedAt === null)
  return {
    total: all.length,
    unsynced: unsynced.length,
    synced: all.length - unsynced.length,
  }
}

