// ──────────────────────────────────────────────────────────────────────────
// METARDU — Offline Sync Manager
// ──────────────────────────────────────────────────────────────────────────
// Handles:
//   - Queueing field data for offline storage
//   - Background sync when connectivity returns
//   - Conflict detection and resolution
//   - Retry with exponential backoff
//   - Sync status events for UI updates
//
// Usage:
//   const sync = getSyncManager();
//   await sync.saveObservation(observation);  // saves locally + queues sync
//   sync.forceSyncNow();                      // manual sync trigger
//   sync.onStatusChange((status) => { ... }); // listen for status
// ──────────────────────────────────────────────────────────────────────────

import {
  getOfflineDB,
  OfflineObservation,
  OfflineStation,
  SyncQueueEntry,
  type OfflineMediaAttachment,
} from './db';

// ─── Types ───────────────────────────────────────────────────────────────

export type SyncStatus = 'idle' | 'syncing' | 'error' | 'offline';

export interface SyncState {
  status: SyncStatus;
  pendingCount: number;
  lastSyncAt: number | null;
  lastError: string | null;
  isOnline: boolean;
}

export interface SyncResult {
  synced: number;
  failed: number;
  conflicts: number;
  duration: number;
}

type StatusListener = (state: SyncState) => void;

// ─── Constants ───────────────────────────────────────────────────────────

const MAX_RETRY_ATTEMPTS = 5;
const BASE_RETRY_DELAY_MS = 1000;
const SYNC_DEBOUNCE_MS = 3000;
const BATCH_SIZE = 20;

// ─── Sync Manager Singleton ──────────────────────────────────────────────

class SyncManager {
  private state: SyncState = {
    status: 'idle',
    pendingCount: 0,
    lastSyncAt: null,
    lastError: null,
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
  };

  private listeners: Set<StatusListener> = new Set();
  private syncTimer: ReturnType<typeof setTimeout> | null = null;
  private isSyncing = false;

  constructor() {
    if (typeof window !== 'undefined') {
      // Listen for online/offline events
      window.addEventListener('online', () => this.handleOnline());
      window.addEventListener('offline', () => this.handleOffline());

      // Listen for visibility change (sync when user returns to tab)
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible' && this.state.isOnline) {
          this.scheduleSync();
        }
      });

      // Initial pending count
      this.refreshPendingCount();
    }
  }

  // ─── Public API: Save Data ───────────────────────────────────────────

  /**
   * Save an observation locally and queue for sync.
   */
  async saveObservation(obs: Omit<OfflineObservation, 'synced' | 'syncAttempts' | 'lastSyncError' | 'createdAt' | 'updatedAt'>): Promise<string> {
    const db = await getOfflineDB();
    const now = Date.now();

    const record: OfflineObservation = {
      ...obs,
      createdAt: now,
      updatedAt: now,
      synced: false,
      syncAttempts: 0,
      lastSyncError: null,
    };

    await db.put('observations', record);

    // Queue sync entry
    await this.enqueue({
      operation: 'create',
      entity: 'observation',
      entityId: record.id,
      payload: record,
      priority: 1,
    });

    this.scheduleSync();
    await this.refreshPendingCount();

    return record.id;
  }

  /**
   * Update an existing observation locally and queue for sync.
   */
  async updateObservation(id: string, updates: Partial<OfflineObservation>): Promise<void> {
    const db = await getOfflineDB();
    const existing = await db.get('observations', id);
    if (!existing) throw new Error(`Observation ${id} not found in offline store`);

    const updated: OfflineObservation = {
      ...existing,
      ...updates,
      id, // ensure id is not overwritten
      updatedAt: Date.now(),
      synced: false,
      syncAttempts: 0,
      lastSyncError: null,
    };

    await db.put('observations', updated);

    await this.enqueue({
      operation: 'update',
      entity: 'observation',
      entityId: id,
      payload: updated,
      priority: 1,
    });

    this.scheduleSync();
    await this.refreshPendingCount();
  }

  /**
   * Save a station locally and queue for sync.
   */
  async saveStation(station: Omit<OfflineStation, 'synced' | 'createdAt'>): Promise<void> {
    const db = await getOfflineDB();
    const record: OfflineStation = {
      ...station,
      createdAt: Date.now(),
      synced: false,
    };

    await db.put('stations', record);

    await this.enqueue({
      operation: 'create',
      entity: 'station',
      entityId: record.id,
      payload: record,
      priority: 2,
    });

    this.scheduleSync();
    await this.refreshPendingCount();
  }

  /**
   * Save a media attachment (photo, sketch) for later sync.
   */
  async saveMedia(media: Omit<OfflineMediaAttachment, 'synced' | 'createdAt'>): Promise<void> {
    const db = await getOfflineDB();
    const record: OfflineMediaAttachment = {
      ...media,
      createdAt: Date.now(),
      synced: false,
    };

    await db.put('media', record);

    await this.enqueue({
      operation: 'create',
      entity: 'media',
      entityId: record.id,
      payload: { ...record, blob: undefined }, // Don't queue blob in sync entry
      priority: 3,
    });

    this.scheduleSync();
    await this.refreshPendingCount();
  }

  // ─── Public API: Read Data ───────────────────────────────────────────

  /**
   * Get all unsynced observations for a survey.
   */
  async getUnsyncedObservations(surveyId: string): Promise<OfflineObservation[]> {
    const db = await getOfflineDB();
    const all = await db.getAllFromIndex('observations', 'by-survey', surveyId);
    return all.filter((obs) => !obs.synced);
  }

  /**
   * Get all observations for a survey (both synced and unsynced).
   */
  async getAllObservations(surveyId: string): Promise<OfflineObservation[]> {
    const db = await getOfflineDB();
    return db.getAllFromIndex('observations', 'by-survey', surveyId);
  }

  /**
   * Get a single observation by id.
   */
  async getObservation(id: string): Promise<OfflineObservation | undefined> {
    const db = await getOfflineDB();
    return db.get('observations', id);
  }

  /**
   * Delete an observation locally.
   */
  async deleteObservation(id: string): Promise<void> {
    const db = await getOfflineDB();
    await db.delete('observations', id);

    await this.enqueue({
      operation: 'delete',
      entity: 'observation',
      entityId: id,
      payload: { id },
      priority: 1,
    });

    this.scheduleSync();
    await this.refreshPendingCount();
  }

  /**
   * Get the count of pending (unsynced) items.
   */
  async getPendingCount(): Promise<number> {
    const db = await getOfflineDB();
    const queue = await db.getAll('syncQueue');
    return queue.length;
  }

  // ─── Public API: Sync Control ────────────────────────────────────────

  /**
   * Force an immediate sync attempt.
   */
  async forceSyncNow(): Promise<SyncResult> {
    if (this.syncTimer) {
      clearTimeout(this.syncTimer);
      this.syncTimer = null;
    }
    return this.executeSync();
  }

  /**
   * Get current sync state.
   */
  getState(): SyncState {
    return { ...this.state };
  }

  /**
   * Subscribe to sync status changes.
   */
  onStatusChange(listener: StatusListener): () => void {
    this.listeners.add(listener);
    // Emit current state immediately
    listener(this.state);
    return () => this.listeners.delete(listener);
  }

  // ─── Internal: Sync Execution ────────────────────────────────────────

  private async executeSync(): Promise<SyncResult> {
    if (this.isSyncing) {
      return { synced: 0, failed: 0, conflicts: 0, duration: 0 };
    }

    if (!this.state.isOnline) {
      this.updateState({ status: 'offline' });
      return { synced: 0, failed: 0, conflicts: 0, duration: 0 };
    }

    this.isSyncing = true;
    this.updateState({ status: 'syncing', lastError: null });

    const startTime = performance.now();
    let synced = 0;
    let failed = 0;
    let conflicts = 0;

    try {
      const db = await getOfflineDB();

      // Get sync queue sorted by priority
      const queue = await db.getAllFromIndex('syncQueue', 'by-priority');

      // Process in batches
      for (let i = 0; i < queue.length; i += BATCH_SIZE) {
        const batch = queue.slice(i, i + BATCH_SIZE);

        for (const entry of batch) {
          try {
            const result = await this.syncEntry(entry);

            if (result === 'conflict') {
              conflicts++;
              // Keep in queue but mark conflict
              await db.put('syncQueue', {
                ...entry,
                attempts: entry.attempts + 1,
                lastError: 'CONFLICT: Server version differs',
              });
            } else {
              // Success — remove from queue
              await db.delete('syncQueue', entry.id);
              synced++;
            }
          } catch (err) {
            const attempts = entry.attempts + 1;
            const errorMsg = err instanceof Error ? err.message : String(err);

            if (attempts >= MAX_RETRY_ATTEMPTS) {
              // Max retries reached — remove from queue, mark as failed
              await db.delete('syncQueue', entry.id);
              await this.markEntitySyncFailed(entry.entity, entry.entityId, errorMsg);
              failed++;
            } else {
              // Update retry count
              await db.put('syncQueue', {
                ...entry,
                attempts,
                lastError: errorMsg,
              });
              failed++;
            }
          }
        }
      }

      const duration = Math.round(performance.now() - startTime);
      const pendingCount = await this.getPendingCount();

      this.updateState({
        status: 'idle',
        pendingCount,
        lastSyncAt: Date.now(),
        lastError: null,
      });

      return { synced, failed, conflicts, duration };
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : String(err);
      this.updateState({
        status: 'error',
        lastError: errorMsg,
      });
      return { synced, failed, conflicts, duration: Math.round(performance.now() - startTime) };
    } finally {
      this.isSyncing = false;
    }
  }

  /**
   * Sync a single queue entry to the server.
   */
  private async syncEntry(entry: SyncQueueEntry): Promise<'ok' | 'conflict'> {
    const endpoint = this.getEndpoint(entry.entity);
    const method = entry.operation === 'delete' ? 'DELETE' : entry.operation === 'update' ? 'PUT' : 'POST';

    const res = await fetch(endpoint, {
      method,
      headers: {
        'Content-Type': 'application/json',
        'X-Sync-Source': 'offline',
        'X-Sync-Entry-Id': entry.id,
      },
      body: JSON.stringify(entry.payload),
    });

    if (res.status === 409) {
      return 'conflict';
    }

    if (!res.ok) {
      throw new Error(`Sync failed: ${res.status} ${res.statusText}`);
    }

    // Mark entity as synced in local DB
    await this.markEntitySynced(entry.entity, entry.entityId);

    return 'ok';
  }

  private getEndpoint(entity: SyncQueueEntry['entity']): string {
    switch (entity) {
      case 'observation':
        return '/api/sync/observations';
      case 'station':
        return '/api/sync/stations';
      case 'media':
        return '/api/sync/media';
      default:
        throw new Error(`Unknown entity type: ${entity}`);
    }
  }

  private async markEntitySynced(entity: SyncQueueEntry['entity'], entityId: string): Promise<void> {
    const db = await getOfflineDB();

    if (entity === 'observation') {
      const obs = await db.get('observations', entityId);
      if (obs) {
        await db.put('observations', { ...obs, synced: true, lastSyncError: null });
      }
    } else if (entity === 'station') {
      const station = await db.get('stations', entityId);
      if (station) {
        await db.put('stations', { ...station, synced: true });
      }
    } else if (entity === 'media') {
      const media = await db.get('media', entityId);
      if (media) {
        await db.put('media', { ...media, synced: true });
      }
    }
  }

  private async markEntitySyncFailed(entity: SyncQueueEntry['entity'], entityId: string, error: string): Promise<void> {
    const db = await getOfflineDB();

    if (entity === 'observation') {
      const obs = await db.get('observations', entityId);
      if (obs) {
        await db.put('observations', { ...obs, lastSyncError: error });
      }
    }
  }

  // ─── Internal: Queue Management ──────────────────────────────────────

  private async enqueue(entry: Omit<SyncQueueEntry, 'id' | 'createdAt' | 'attempts' | 'lastError'>): Promise<void> {
    const db = await getOfflineDB();
    const record: SyncQueueEntry = {
      ...entry,
      id: `sync_${entry.entity}_${entry.entityId}_${Date.now()}`,
      createdAt: Date.now(),
      attempts: 0,
      lastError: null,
    };
    await db.put('syncQueue', record);
  }

  // ─── Internal: Connectivity ──────────────────────────────────────────

  private handleOnline(): void {
    this.updateState({ isOnline: true, status: 'idle' });
    this.scheduleSync();
  }

  private handleOffline(): void {
    this.updateState({ isOnline: false, status: 'offline' });
    if (this.syncTimer) {
      clearTimeout(this.syncTimer);
      this.syncTimer = null;
    }
  }

  private scheduleSync(): void {
    if (this.syncTimer) {
      clearTimeout(this.syncTimer);
    }
    this.syncTimer = setTimeout(() => {
      this.executeSync();
    }, SYNC_DEBOUNCE_MS);
  }

  // ─── Internal: State Management ──────────────────────────────────────

  private updateState(partial: Partial<SyncState>): void {
    this.state = { ...this.state, ...partial };
    for (const listener of this.listeners) {
      try {
        listener(this.state);
      } catch (err) {
        console.error('[SyncManager] Listener error:', err);
      }
    }
  }

  private async refreshPendingCount(): Promise<void> {
    try {
      const count = await this.getPendingCount();
      this.updateState({ pendingCount: count });
    } catch {
      // DB might not be available during SSR
    }
  }
}

// ─── Singleton Export ────────────────────────────────────────────────────

let instance: SyncManager | null = null;

export function getSyncManager(): SyncManager {
  if (!instance) {
    instance = new SyncManager();
  }
  return instance;
}

/**
 * @deprecated This module is a thin compatibility layer over syncQueue.ts (v2).
 * Import from './syncQueue' directly for new code.
 *
 * The v1 sync functions operated on the observations store which no longer
 * exists in DB_VERSION=3. All sync operations now go through the priority
 * queue in syncQueue.ts.
 */

import {
  getDB,
  syncPendingOperations,
  isOnline as isOnlineV2,
  setupOnlineListener,
  clearOfflineData,
  type SyncOperation,
} from './syncQueue'

export interface SyncResult {
  success: boolean
  synced: number
  failed: number
  errors: string[]
}

export interface SyncProgress {
  total: number
  current: number
  status: 'idle' | 'syncing' | 'complete' | 'error'
  message: string
}

export type SyncProgressCallback = (progress: SyncProgress) => void

/**
 * @deprecated Use syncPendingOperations from syncQueue.ts directly.
 * This wrapper exists for backward compatibility.
 */
export async function syncProject(
  projectId: string,
  onProgress?: SyncProgressCallback
): Promise<SyncResult> {
  const { getPendingOperations } = await import('./syncQueue')
  const pending = await getPendingOperations(projectId)

  if (pending.length === 0) {
    return { success: true, synced: 0, failed: 0, errors: [] }
  }

  onProgress?.({
    total: pending.length,
    current: 0,
    status: 'syncing',
    message: 'Starting sync...',
  })

  // Use a simple fetch-based sync (v1 style) as fallback
  let synced = 0
  let failed = 0
  const errors: string[] = []

  for (let i = 0; i < pending.length; i++) {
    const op = pending[i]

    onProgress?.({
      total: pending.length,
      current: i + 1,
      status: 'syncing',
      message: `Syncing operation ${i + 1} of ${pending.length}...`,
    })

    try {
      const response = await fetch('/api/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(op),
      })

      if (response.ok) {
        if (op.id) {
          const { removeSyncedOperation } = await import('./syncQueue')
          await removeSyncedOperation(op.id)
        }
        synced++
      } else {
        const error = await response.text()
        errors.push(`Operation ${op.type} on ${op.table}: ${error}`)
        failed++
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unknown error'
      errors.push(`Operation ${op.type} on ${op.table}: ${message}`)
      failed++
    }
  }

  // Update project last_sync timestamp
  if (failed === 0) {
    const db = await getDB()
    const project = await db.get('projects', projectId)
    if (project) {
      ;(project as any).last_sync = new Date().toISOString()
      ;(project as any).dirty = false
      await db.put('projects', project)
    }
  }

  onProgress?.({
    total: pending.length,
    current: pending.length,
    status: failed === 0 ? 'complete' : 'error',
    message: failed === 0
      ? `Synced ${synced} operations`
      : `Synced ${synced}, failed ${failed}`,
  })

  return {
    success: failed === 0,
    synced,
    failed,
    errors,
  }
}

/**
 * @deprecated Use isOnline from syncQueue.ts directly.
 */
export function isOnline(): boolean {
  return isOnlineV2()
}

/**
 * @deprecated Use setupOnlineListener from syncQueue.ts directly.
 */
export function registerNetworkListeners(
  onOnline: () => void,
  onOffline: () => void
): () => void {
  return setupOnlineListener(onOnline)
}

/**
 * @deprecated Use startBackgroundSync from syncQueue.ts directly.
 */
export function enableAutoSync(projectId: string): () => void {
  let syncing = false

  const handleOnline = async () => {
    if (syncing) return
    syncing = true
    try {
      await syncProject(projectId)
    } finally {
      syncing = false
    }
  }

  return setupOnlineListener(handleOnline)
}

import { openDB, DBSchema, IDBPDatabase } from 'idb'

const DB_NAME = 'metardu-offline'
const DB_VERSION = 3
const MAX_RETRIES = 3
const SYNC_INTERVAL = 30000 // 30 seconds

// ponytail: Phase 6 Batch 7 — typed minimal DB client interface for the
// offline sync queue. Mirrors the legacy DB proxy client surface (see
// src/lib/api-client/client.ts). The queue only uses .from()/.select()/.insert()
// .update()/.delete()/.eq()/.single(), so a structural interface is enough.
// Fields are required (but nullable) to match the QueryResult shape exactly,
// and `single()` returns PromiseLike (not Promise) so that the legacy
// ClientQueryBuilder — whose single() returns PromiseLike<...> & this — is
// structurally assignable.
interface SyncDbResult {
  data: Record<string, unknown> | null
  error: { message: string; code: string; details?: string } | null
  count?: number | null
}

interface SyncDbQuery {
  select(columns?: string, options?: { count?: string; head?: boolean }): SyncDbQuery
  insert(data: Record<string, unknown> | Record<string, unknown>[]): SyncDbQuery
  update(data: Record<string, unknown>): SyncDbQuery
  delete(): SyncDbQuery
  eq(column: string, value: unknown): SyncDbQuery
  single(): PromiseLike<SyncDbResult>
  // ponytail: thenable — `await dbClient.from(t).insert(d)` resolves to SyncDbResult
  then<TResult1 = SyncDbResult, TResult2 = never>(
    resolve?: ((v: SyncDbResult) => TResult1 | PromiseLike<TResult1>) | null,
    reject?: ((e: unknown) => TResult2 | PromiseLike<TResult2>) | null,
  ): Promise<TResult1 | TResult2>
}

interface SyncDbClient {
  from(table: string): SyncDbQuery
}

interface METARDUDB extends DBSchema {
  sync_queue: {
    key: number
    value: SyncOperation
    indexes: { 'by-project': string; 'by-timestamp': string }
  }
  projects: {
    key: string
    value: Record<string, unknown>
  }
  survey_points: {
    key: string
    value: Record<string, unknown>
    indexes: { 'by-project': string }
  }
  traverse_obs: {
    key: string
    value: Record<string, unknown>
    indexes: { 'by-project': string }
  }
  leveling_obs: {
    key: string
    value: Record<string, unknown>
    indexes: { 'by-project': string }
  }
  fieldbooks: {
    key: string
    value: Record<string, unknown>
  }
  conflicts: {
    key: number
    value: ConflictRecord
  }
}

let dbPromise: Promise<IDBPDatabase<METARDUDB>> | null = null

export async function getDB(): Promise<IDBPDatabase<METARDUDB>> {
  if (!dbPromise) {
    dbPromise = openDB<METARDUDB>(DB_NAME, DB_VERSION, {
      upgrade(db, oldVersion, newVersion) {
        // Sync queue with indexes
        if (!db.objectStoreNames.contains('sync_queue')) {
          const store = db.createObjectStore('sync_queue', { keyPath: 'id', autoIncrement: true })
          store.createIndex('by-project', 'projectId')
          store.createIndex('by-timestamp', 'timestamp')
        }
        // Projects store
        if (!db.objectStoreNames.contains('projects')) {
          db.createObjectStore('projects', { keyPath: 'id' })
        }
        // Survey points with project index
        if (!db.objectStoreNames.contains('survey_points')) {
          const store = db.createObjectStore('survey_points', { keyPath: 'id' })
          store.createIndex('by-project', 'project_id')
        }
        // Traverse observations
        if (!db.objectStoreNames.contains('traverse_obs')) {
          const store = db.createObjectStore('traverse_obs', { keyPath: 'id' })
          store.createIndex('by-project', 'project_id')
        }
        // Leveling observations
        if (!db.objectStoreNames.contains('leveling_obs')) {
          const store = db.createObjectStore('leveling_obs', { keyPath: 'id' })
          store.createIndex('by-project', 'project_id')
        }
        // Field books
        if (!db.objectStoreNames.contains('fieldbooks')) {
          db.createObjectStore('fieldbooks', { keyPath: 'id' })
        }
        // Conflict resolution store
        if (!db.objectStoreNames.contains('conflicts')) {
          db.createObjectStore('conflicts', { keyPath: 'id', autoIncrement: true })
        }
      }
    })
  }
  return dbPromise
}

export interface SyncOperation {
  id?: number
  type: 'INSERT' | 'UPDATE' | 'DELETE'
  table: string
  data: Record<string, unknown>
  timestamp: string
  projectId: string
  retries: number
  priority: 'high' | 'normal' | 'low'
}

export interface ConflictRecord {
  id?: number
  localOp: SyncOperation
  remoteData: Record<string, unknown> | null
  /** Common-ancestor snapshot (the state of the row when the local edit began). */
  baseData?: Record<string, unknown> | null
  resolved: boolean
  resolution?: 'local' | 'remote' | 'merged' | 'manual'
  /** After three-way merge, which fields need manual resolution (both sides changed them). */
  conflictingFields?: string[]
  /** After three-way merge, the proposed merged data (auto-resolvable fields only). */
  mergedData?: Record<string, unknown> | null
  createdAt: string
}

// Queue operations with priority
export async function queueOperation(op: Omit<SyncOperation, 'id' | 'retries'>): Promise<void> {
  const db = await getDB()
  await db.add('sync_queue', { 
    ...op, 
    retries: 0,
    priority: op.priority || 'normal'
  })
}

// Get pending operations sorted by priority and timestamp
export async function getPendingOperations(projectId?: string): Promise<SyncOperation[]> {
  const db = await getDB()
  let operations = await db.getAll('sync_queue')

  if (projectId) {
    operations = operations.filter((op) => op.projectId === projectId)
  }
  
  // Sort by priority (high first) then by timestamp
  const priorityOrder: Record<SyncOperation['priority'], number> = { high: 0, normal: 1, low: 2 }
  return operations.sort((a, b) => {
    const pDiff = priorityOrder[a.priority] - priorityOrder[b.priority]
    if (pDiff !== 0) return pDiff
    return new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
  })
}

// Remove synced operation
export async function removeSyncedOperation(id: number): Promise<void> {
  const db = await getDB()
  await db.delete('sync_queue', id)
}

// Exponential backoff retry
async function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms))
}

// Enhanced sync with conflict resolution
export async function syncPendingOperations(
  dbClient: SyncDbClient,
  options: { onConflict?: (conflict: ConflictRecord) => Promise<'local' | 'remote' | 'merged'> } = {}
): Promise<{ synced: number; failed: number; conflicts: number }> {
  const pending = await getPendingOperations()
  const results = { synced: 0, failed: 0, conflicts: 0 }

  for (const op of pending) {
    try {
      if (op.retries >= MAX_RETRIES) {
        results.failed++
        continue
      }

      // Check for conflicts using timestamp
      const timestamp = op.data.updated_at || op.timestamp
      const existing = await checkRemoteVersion(dbClient, op.table, String(op.data.id), String(timestamp))

      if (existing.hasConflict && options.onConflict) {
        // AUDIT FIX (H4, 2026-07-02): Retrieve the base snapshot for
        // three-way merge. Without it, we can only do naive LWW.
        const baseData = await getBaseSnapshot(op.table, String(op.data.id))

        const conflict: ConflictRecord = {
          localOp: op,
          remoteData: existing.data ?? null,
          baseData,
          resolved: false,
          createdAt: new Date().toISOString()
        }

        // If we have a base snapshot, attempt automatic three-way merge first.
        // Only surface to the user if there are genuine field-level conflicts.
        if (baseData) {
          const mergeResult = threeWayMerge(baseData, op.data, existing.data ?? null)
          conflict.mergedData = mergeResult.merged
          conflict.conflictingFields = mergeResult.conflictingFields

          if (mergeResult.conflictingFields.length === 0) {
            // No conflicts — auto-apply the merge, don't bother the user
            await applyMergedUpdate(dbClient, op, existing.data ?? null, baseData)
            results.synced++
            await removeSyncedOperation(op.id!)
            continue
          }
        }

        const resolution = await options.onConflict(conflict)

        if (resolution === 'local') {
          // Force local — UPDATE (not delete+insert, which was destructive)
          await forceLocalUpdate(dbClient, op)
        } else if (resolution === 'merged') {
          // Use three-way merged data
          await applyMergedUpdate(dbClient, op, existing.data ?? null, baseData)
        } else {
          // Keep remote - skip local
          if (op.id) await removeSyncedOperation(op.id)
          results.synced++
          continue
        }

        results.conflicts++
      }

      // Attempt sync
      const success = await attemptSync(dbClient, op)

      if (success) {
        if (op.id) await removeSyncedOperation(op.id)
        results.synced++
      } else {
        // Increment retry count
        op.retries++
        const db = await getDB()
        await db.put('sync_queue', op)
        results.failed++
      }

    } catch {
      results.failed++
    }
  }

  return results
}

async function checkRemoteVersion(dbClient: SyncDbClient, table: string, id: string, localTimestamp: string): Promise<{ hasConflict: boolean; data: Record<string, unknown> | null }> {
  try {
    const result = await dbClient
      .from(table)
      .select('id, updated_at')
      .eq('id', id)
      .single()

    const data = result.data ?? null
    const error = result.error
    if (error || !data) return { hasConflict: false, data: null }

    const remoteUpdatedAt = data.updated_at
    const remoteTime = new Date((remoteUpdatedAt as string | number) || 0).getTime()
    const localTime = new Date(localTimestamp).getTime()

    return {
      hasConflict: remoteTime > localTime,
      data
    }
  } catch {
    return { hasConflict: false, data: null }
  }
}

async function attemptSync(dbClient: SyncDbClient, op: SyncOperation): Promise<boolean> {
  try {
    if (op.type === 'INSERT') {
      const { error } = await dbClient.from(op.table).insert(op.data)
      return !error
    }
    if (op.type === 'UPDATE') {
      const { error } = await dbClient.from(op.table).update(op.data).eq('id', op.data.id)
      return !error
    }
    if (op.type === 'DELETE') {
      const { error } = await dbClient.from(op.table).delete().eq('id', op.data.id)
      return !error
    }
    return false
  } catch {
    return false
  }
}

async function forceLocalUpdate(dbClient: SyncDbClient, op: SyncOperation): Promise<void> {
  // AUDIT FIX (H4, 2026-07-02): This is the "local wins" resolution.
  // Previously it DELETEd the remote row then re-INSERTed — that
  // destroyed concurrent edits from other surveyors AND bypassed DB
  // triggers (audit_chain). Now it does an UPDATE with the local data,
  // preserving the row identity and triggering audit properly.
  await dbClient.from(op.table).update(op.data).eq('id', op.data.id)
}

/**
 * Three-way merge of local and remote changes against a common ancestor.
 *
 * AUDIT FIX (H4, 2026-07-02): Replaced the naive `{...remote, ...local}`
 * merge (which silently overwrote remote-only fields) with a proper
 * three-way merge:
 *
 *   - If a field changed locally but not remotely → take local value
 *   - If a field changed remotely but not locally → take remote value
 *   - If both changed (and differ) → field needs manual resolution
 *   - If neither changed → take either (they're identical)
 *
 * Returns the merged data and the list of conflicting field names.
 * The caller decides whether to auto-apply the merge (if no conflicts)
 * or surface the conflicts to the user for manual resolution.
 */
export function threeWayMerge(
  base: Record<string, unknown> | null,
  local: Record<string, unknown>,
  remote: Record<string, unknown> | null
): { merged: Record<string, unknown>; conflictingFields: string[] } {
  const merged: Record<string, unknown> = {}
  const conflictingFields: string[] = []

  // Collect all field names across base/local/remote
  const allKeys = new Set<string>([
    ...Object.keys(base ?? {}),
    ...Object.keys(local),
    ...Object.keys(remote ?? {}),
  ])

  // System fields that should always come from the latest (remote) version
  const SYSTEM_FIELDS = new Set(['created_at', 'updated_at', 'id'])

  for (const key of allKeys) {
    if (SYSTEM_FIELDS.has(key)) {
      merged[key] = remote?.[key] ?? local[key]
      continue
    }

    const baseVal = base?.[key]
    const localVal = local[key]
    const remoteVal = remote?.[key]

    const localChanged = !deepEqual(baseVal, localVal)
    const remoteChanged = !deepEqual(baseVal, remoteVal)

    if (localChanged && remoteChanged) {
      // Both sides changed this field
      if (deepEqual(localVal, remoteVal)) {
        // Same change — no conflict
        merged[key] = localVal
      } else {
        // Genuine conflict — flag for manual resolution.
        // Default to remote (most recent) but record the conflict.
        merged[key] = remoteVal
        conflictingFields.push(key)
      }
    } else if (localChanged) {
      merged[key] = localVal
    } else if (remoteChanged) {
      merged[key] = remoteVal
    } else {
      // Neither changed — take either
      merged[key] = localVal ?? remoteVal ?? baseVal
    }
  }

  return { merged, conflictingFields }
}

/** Deep equality check (handles primitives, arrays, plain objects). */
function deepEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true
  if (a === null || b === null) return false
  if (typeof a !== typeof b) return false
  if (typeof a !== 'object') return a === b
  if (Array.isArray(a) !== Array.isArray(b)) return false
  if (Array.isArray(a)) {
    if (a.length !== (b as unknown[]).length) return false
    return a.every((v, i) => deepEqual(v, (b as unknown[])[i]))
  }
  const aKeys = Object.keys(a as Record<string, unknown>)
  const bKeys = Object.keys(b as Record<string, unknown>)
  if (aKeys.length !== bKeys.length) return false
  return aKeys.every(k => deepEqual(
    (a as Record<string, unknown>)[k],
    (b as Record<string, unknown>)[k]
  ))
}

/**
 * Apply a merged update to the remote DB.
 * If the merge has no conflicting fields, auto-applies. If there are
 * conflicts, stores the conflict for manual resolution and applies the
 * non-conflicting fields.
 */
async function applyMergedUpdate(
  dbClient: SyncDbClient,
  op: SyncOperation,
  remoteData: Record<string, unknown> | null,
  baseData?: Record<string, unknown> | null
): Promise<{ conflictingFields: string[] }> {
  // Perform three-way merge
  const { merged, conflictingFields } = threeWayMerge(
    baseData ?? null,
    op.data,
    remoteData
  )

  // Apply the merged data (even with conflicts — the conflicting fields
  // default to remote, and the user can override later via manual resolution)
  await dbClient.from(op.table).update(merged).eq('id', op.data.id)

  return { conflictingFields }
}

/**
 * Capture a base snapshot of a row when it's first edited offline.
 * This enables three-way merge later. Call this BEFORE the user's edit
 * is applied to the local store.
 *
 * AUDIT FIX (H4, 2026-07-02): Without a base snapshot, three-way merge
 * is impossible — you can't tell whether a field was changed locally or
 * not. This function stores the original server state in IndexedDB so
 * the sync queue can access it at conflict-resolution time.
 */
export async function captureBaseSnapshot(
  table: string,
  id: string,
  data: Record<string, unknown>
): Promise<void> {
  const db = await getDB()
  // Store in the 'projects' store under a synthetic key to avoid schema
  // changes. Key format: `${table}:${id}`
  // (A dedicated `base_snapshots` store would be cleaner but requires a
  // DB_VERSION bump; this is the pragmatic interim solution.)
  await db.put('projects', {
    id: `__base__${table}_${id}`,
    __isBaseSnapshot: true,
    table,
    rowId: id,
    data,
    capturedAt: new Date().toISOString(),
  })
}

/**
 * Retrieve a previously-captured base snapshot.
 */
export async function getBaseSnapshot(
  table: string,
  id: string
): Promise<Record<string, unknown> | null> {
  const db = await getDB()
  const snapshot = await db.get('projects', `__base__${table}_${id}`)
  if (snapshot && snapshot.__isBaseSnapshot) {
    return snapshot.data as Record<string, unknown>
  }
  return null
}

/**
 * Get all unresolved conflicts for UI display.
 * Returns conflicts from the IndexedDB 'conflicts' store.
 */
export async function getPendingConflicts(): Promise<ConflictRecord[]> {
  const db = await getDB()
  const all = await db.getAll('conflicts')
  return all.filter(c => !c.resolved)
}

/**
 * Resolve a conflict manually (after user review).
 * Applies the user-chosen merged data to the remote DB.
 */
export async function resolveConflict(
  dbClient: SyncDbClient,
  conflictId: number,
  resolution: 'local' | 'remote' | 'merged',
  mergedData?: Record<string, unknown>
): Promise<void> {
  const db = await getDB()
  const conflict = await db.get('conflicts', conflictId)
  if (!conflict) throw new Error(`Conflict ${conflictId} not found`)

  if (resolution === 'local') {
    await forceLocalUpdate(dbClient, conflict.localOp)
  } else if (resolution === 'remote') {
    // Do nothing — remote already has the latest
  } else if (resolution === 'merged') {
    if (!mergedData) throw new Error('mergedData required for merged resolution')
    await dbClient.from(conflict.localOp.table).update(mergedData).eq('id', conflict.localOp.data.id)
  }

  // Mark conflict as resolved
  conflict.resolved = true
  conflict.resolution = resolution
  await db.put('conflicts', conflict)
}

// Background sync service
let syncInterval: ReturnType<typeof setInterval> | null = null

export function startBackgroundSync(dbClient: SyncDbClient, options?: { interval?: number; onConflict?: (conflict: ConflictRecord) => Promise<'local' | 'remote' | 'merged'> }) {
  if (syncInterval) return

  const interval = options?.interval || SYNC_INTERVAL
  
  syncInterval = setInterval(async () => {
    if (!isOnline()) return
    
    const results = await syncPendingOperations(dbClient, { onConflict: options?.onConflict })
    
    if (results.synced > 0) {
      if (process.env.NODE_ENV !== 'production') console.log(`[Sync] Synced ${results.synced} operations`)
    }
    if (results.conflicts > 0) {
      if (process.env.NODE_ENV !== 'production') console.log(`[Sync] Resolved ${results.conflicts} conflicts`)
    }
  }, interval)
}

export function stopBackgroundSync() {
  if (syncInterval) {
    clearInterval(syncInterval)
    syncInterval = null
  }
}

