export function calculateConfidence(data: ExtractedBuildingData): number {
  let score = 0.5

  if (data.walls.length > 0) score += 0.15
  if (data.rooms.length > 0) score += 0.15
  if (data.annotations.length > 0) score += 0.1
  if (data.metadata.projectName) score += 0.05
  if (data.metadata.scale) score += 0.05

  return Math.min(1, score)
}

import type { ParsedInput, ExtractedBuildingData, ExtractedWall, ExtractedFloor, BoundingBox2D, ExtractedAnnotation } from './types'
import { calculateConfidence } from './fileRouter'

export async function parseGLTFFile(file: File): Promise<ParsedInput> {
  try {
    const THREE = await import('three')
    const { GLTFLoader } = await import('three/examples/jsm/loaders/GLTFLoader.js')

    const arrayBuffer = await file.arrayBuffer()
    const loader = new GLTFLoader()

    return new Promise((resolve) => {
      loader.parse(arrayBuffer, '', (gltf) => {
        const scene = gltf.scene
        const box = new THREE.Box3().setFromObject(scene)
        const size = box.getSize(new THREE.Vector3())
        const center = box.getCenter(new THREE.Vector3())

        const boundingBox: BoundingBox2D = {
          minEasting: center.x - size.x / 2,
          maxEasting: center.x + size.x / 2,
          minNorthing: center.y - size.y / 2,
          maxNorthing: center.y + size.y / 2,
        }

        const floors = Math.ceil(size.z / 3)
        const extractedFloors: ExtractedFloor[] = []
        
        for (let i = 0; i < Math.max(1, floors); i++) {
          extractedFloors.push({
            id: `floor_${i}`,
            level: i,
            name: i === 0 ? 'Ground Floor' : `Floor ${i}`,
            elevation: i * 3,
            boundingBox,
          })
        }

        const walls: ExtractedWall[] = []
        scene.traverse((child: any) => {
          if (child.isMesh) {
            const geom = child.geometry
            if (geom?.boundingBox) {
              const meshBox = new THREE.Box3().copy(geom.boundingBox)
              const position = child.position
              
              const width = meshBox.max.x - meshBox.min.x
              const height = meshBox.max.z - meshBox.min.z
              
              if (width > 0.1 && height > 2) {
                walls.push({
                  id: `wall_${walls.length}`,
                  type: 'unknown',
                  startPoint: { easting: position.x + meshBox.min.x, northing: position.z + meshBox.min.z },
                  endPoint: { easting: position.x + meshBox.max.x, northing: position.z + meshBox.max.z },
                  thickness: 0.2,
                  height: height,
                  level: Math.floor(position.y / 3),
                })
              }
            }
          }
        })

        const building: ExtractedBuildingData = {
          floors: extractedFloors,
          walls,
          rooms: [],
          doors: [],
          windows: [],
          columns: [],
          beams: [],
          annotations: [],
          boundingBox,
          metadata: {
            units: 'meters',
            projectName: file.name.replace(/\.[^/.]+$/, ''),
          },
        }

        const confidence = calculateConfidence(building) * 0.75

        resolve({
          type: 'GLTF',
          sourceFileName: file.name,
          sourceFileSize: file.size,
          sourceFileLastModified: file.lastModified,
          parsedAt: new Date().toISOString(),
          version: '1.0.0',
          building,
          errors: [],
          warnings: ['3D model geometry extracted. For full semantic analysis, use AI enhancement.'],
          confidence,
        })
      }, (error) => {
        resolve({
          type: 'GLTF',
          sourceFileName: file.name,
          sourceFileSize: file.size,
          sourceFileLastModified: file.lastModified,
          parsedAt: new Date().toISOString(),
          version: '1.0.0',
          errors: [`GLTF parse error: ${error}`],
          warnings: [],
          confidence: 0,
        })
      })
    })
  } catch (error) {
    return {
      type: 'GLTF',
      sourceFileName: file.name,
      sourceFileSize: file.size,
      sourceFileLastModified: file.lastModified,
      parsedAt: new Date().toISOString(),
      version: '1.0.0',
      errors: [error instanceof Error ? error.message : 'GLTF parsing failed'],
      warnings: ['Ensure three.js is installed and GLTFLoader is available'],
      confidence: 0,
    }
  }
}

export async function parseOBJFile(file: File): Promise<ParsedInput> {
  try {
    const content = await file.text()
    const lines = content.split('\n')
    
    const vertices: number[] = []
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity, minZ = Infinity, maxZ = -Infinity

    for (const line of lines) {
      const parts = line.trim().split(/\s+/)
      if (parts[0] === 'v' && parts.length >= 4) {
        const x = parseFloat(parts[1])
        const y = parseFloat(parts[2])
        const z = parseFloat(parts[3])
        vertices.push(x, y, z)
        
        if (x < minX) minX = x
        if (x > maxX) maxX = x
        if (y < minY) minY = y
        if (y > maxY) maxY = y
        if (z < minZ) minZ = z
        if (z > maxZ) maxZ = z
      }
    }

    const boundingBox: BoundingBox2D = minX === Infinity
      ? { minEasting: 0, maxEasting: 10, minNorthing: 0, maxNorthing: 10 }
      : { minEasting: minX, maxEasting: maxX, minNorthing: minZ, maxNorthing: maxZ }

    const floors = Math.ceil((maxY - minY) / 3)
    const extractedFloors: ExtractedFloor[] = []
    
    for (let i = 0; i < Math.max(1, floors); i++) {
      extractedFloors.push({
        id: `floor_${i}`,
        level: i,
        name: i === 0 ? 'Ground Floor' : `Floor ${i}`,
        elevation: minY + i * 3,
        boundingBox,
      })
    }

    const building: ExtractedBuildingData = {
      floors: extractedFloors,
      walls: [],
      rooms: [],
      doors: [],
      windows: [],
      columns: [],
      beams: [],
      annotations: [],
      boundingBox,
      metadata: {
        units: 'meters',
        projectName: file.name.replace(/\.[^/.]+$/, ''),
      },
    }

    const confidence = 0.5

    return {
      type: 'OBJ',
      sourceFileName: file.name,
      sourceFileSize: file.size,
      sourceFileLastModified: file.lastModified,
      parsedAt: new Date().toISOString(),
      version: '1.0.0',
      building,
      errors: [],
      warnings: ['OBJ is mesh-only format. No semantic wall/room data available.'],
      confidence,
    }
  } catch (error) {
    return {
      type: 'OBJ',
      sourceFileName: file.name,
      sourceFileSize: file.size,
      sourceFileLastModified: file.lastModified,
      parsedAt: new Date().toISOString(),
      version: '1.0.0',
      errors: [error instanceof Error ? error.message : 'OBJ parsing failed'],
      warnings: [],
      confidence: 0,
    }
  }
}

import type { ParsedInput, BOQData, BOQItem } from './types'

export async function parseBOQSpreadsheet(file: File): Promise<ParsedInput> {
  try {
    const ExcelJS = await import('exceljs')

    const arrayBuffer = await file.arrayBuffer()
    const workbook = new ExcelJS.Workbook()
    await workbook.xlsx.load(arrayBuffer)

    const firstSheet = workbook.worksheets[0]
    if (!firstSheet) {
      return {
        type: 'BOQ',
        sourceFileName: file.name,
        sourceFileSize: file.size,
        sourceFileLastModified: file.lastModified,
        parsedAt: new Date().toISOString(),
        version: '1.0.0',
        errors: ['BOQ file appears empty or has no sheets'],
        warnings: [],
        confidence: 0,
      }
    }

    // Convert worksheet rows to a 2D array (similar to sheet_to_json with header: 1)
    const jsonData: any[][] = []
    firstSheet.eachRow({ includeEmpty: false }, (row) => {
      const rowArray: any[] = []
      for (let col = 1; col <= row.cellCount; col++) {
        const cell = row.getCell(col)
        rowArray.push(cell.value ?? '')
      }
      jsonData.push(rowArray)
    })

    if (jsonData.length < 2) {
      return {
        type: 'BOQ',
        sourceFileName: file.name,
        sourceFileSize: file.size,
        sourceFileLastModified: file.lastModified,
        parsedAt: new Date().toISOString(),
        version: '1.0.0',
        errors: ['BOQ file appears empty or has no data rows'],
        warnings: [],
        confidence: 0,
      }
    }

    const headers = jsonData[0].map((h: string) => String(h || '').toLowerCase().trim())

    const findColumn = (patterns: string[]): number => {
      return headers.findIndex(h => patterns.some((p: any) => h.includes(p)))
    }

    const descCol = findColumn(['description', 'item', 'work', 'description', 'particular'])
    const qtyCol = findColumn(['quantity', 'qty', 'amount', 'num', 'no.'])
    const unitCol = findColumn(['unit', 'units', 'measure'])
    const rateCol = findColumn(['rate', 'price', 'unit rate', 'u.rate', 'unit price'])
    const catCol = findColumn(['category', 'group', 'section', 'type'])

    if (descCol === -1 || qtyCol === -1) {
      return {
        type: 'BOQ',
        sourceFileName: file.name,
        sourceFileSize: file.size,
        sourceFileLastModified: file.lastModified,
        parsedAt: new Date().toISOString(),
        version: '1.0.0',
        errors: ['Could not find required columns (Description, Quantity)'],
        warnings: ['Ensure BOQ has proper column headers'],
        confidence: 0,
      }
    }

    const items: BOQItem[] = []
    let subtotal = 0
    let currency = 'KES'

    for (let i = 1; i < jsonData.length; i++) {
      const row = jsonData[i]
      if (!row || !row[descCol]) continue

      const description = String(row[descCol] || '')
      const quantity = parseFloat(row[qtyCol]) || 0
      const unit = String(row[unitCol] || 'item')
      const unitRate = parseFloat(row[rateCol]) || 0
      const totalRate = quantity * unitRate
      const category = catCol !== -1 ? String(row[catCol] || 'General') : 'General'

      if (description && quantity > 0) {
        items.push({
          id: `boq_${i}`,
          description,
          unit,
          quantity,
          unitRate,
          totalRate,
          category,
        })
        subtotal += totalRate
      }
    }

    const boq: BOQData = {
      items,
      currency,
      subtotal,
      tax: subtotal * 0.16,
      total: subtotal * 1.16,
      sourceFileName: file.name,
    }

    return {
      type: 'BOQ',
      sourceFileName: file.name,
      sourceFileSize: file.size,
      sourceFileLastModified: file.lastModified,
      parsedAt: new Date().toISOString(),
      version: '1.0.0',
      boq,
      errors: [],
      warnings: [],
      confidence: 0.85,
    }
  } catch (error) {
    return {
      type: 'BOQ',
      sourceFileName: file.name,
      sourceFileSize: file.size,
      sourceFileLastModified: file.lastModified,
      parsedAt: new Date().toISOString(),
      version: '1.0.0',
      errors: [error instanceof Error ? error.message : 'BOQ parsing failed'],
      warnings: ['Ensure exceljs is properly installed'],
      confidence: 0,
    }
  }
}

import { readFileSync } from 'fs'
import type { ParsedInput, ExtractedBuildingData, ExtractedWall, ExtractedRoom, ExtractedAnnotation, ExtractedFloor, BoundingBox2D, Point2D } from './types'
import { calculateConfidence } from './fileRouter'

interface DXFEntity {
  type: string
  layer?: string
  x?: number
  y?: number
  x1?: number
  y1?: number
  x2?: number
  y2?: number
  thickness?: number
  elevation?: number
  text?: string
  height?: number
}

interface DXFParseResult {
  entities: DXFEntity[]
  units: string
  layers: string[]
  boundingBox: BoundingBox2D
}

function parseDXFFile(content: string): DXFParseResult {
  const entities: DXFEntity[] = []
  const layers = new Set<string>()
  const lines = content.split('\n')
  
  let i = 0
  let currentEntity: Record<string, string> = {}
  
  while (i < lines.length) {
    const line = lines[i]?.trim()
    if (!line) {
      i++
      continue
    }
    
    const code = parseInt(line, 10)
    const nextLine = lines[i + 1]?.trim() || ''
    
    if (code >= 0 && code <= 999) {
      currentEntity[code] = nextLine
      
      if (code === 0 && nextLine) {
        if (Object.keys(currentEntity).length > 1) {
          const entity = convertToEntity(currentEntity)
          if (entity) {
            entities.push(entity)
            if (entity.layer) layers.add(entity.layer)
          }
        }
        currentEntity = { 0: nextLine }
      }
    }
    i += 2
  }
  
  if (Object.keys(currentEntity).length > 1) {
    const entity = convertToEntity(currentEntity)
    if (entity) {
      entities.push(entity)
      if (entity.layer) layers.add(entity.layer)
    }
  }
  
  let units = 'meters'
  const unitsEntity = entities.find((e: any) => e.type === 'INSUNITS')
  if (unitsEntity && unitsEntity.text) {
    const unitCode = parseInt(unitsEntity.text)
    const unitMap: Record<number, string> = {
      1: 'units', 2: 'inches', 3: 'feet', 4: 'miles',
      5: 'millimeters', 6: 'centimeters', 7: 'meters', 8: 'kilometers',
    }
    units = unitMap[unitCode] || 'meters'
  }
  
  let minE = Infinity, maxE = -Infinity, minN = Infinity, maxN = -Infinity
  entities.forEach((e: any) => {
    const coords = getEntityCoordinates(e)
    coords.forEach((p: any) => {
      if (p.easting < minE) minE = p.easting
      if (p.easting > maxE) maxE = p.easting
      if (p.northing < minN) minN = p.northing
      if (p.northing > maxN) maxN = p.northing
    })
  })
  
  const boundingBox: BoundingBox2D = minE === Infinity 
    ? { minEasting: 0, maxEasting: 0, minNorthing: 0, maxNorthing: 0 }
    : { minEasting: minE, maxEasting: maxE, minNorthing: minN, maxNorthing: maxN }
  
  return { entities, units, layers: Array.from(layers), boundingBox }
}

function convertToEntity(data: Record<string, string>): DXFEntity | null {
  const type = data[0]
  if (!type) return null
  
  const entity: DXFEntity = { type, layer: data[8] }
  
  switch (type) {
    case 'LINE':
      entity.x1 = parseFloat(data[10])
      entity.y1 = parseFloat(data[20])
      entity.x2 = parseFloat(data[11])
      entity.y2 = parseFloat(data[21])
      entity.thickness = parseFloat(data[39])
      entity.elevation = parseFloat(data[30])
      break
    case 'POLYLINE':
    case 'LWPOLYLINE':
      entity.x = parseFloat(data[10])
      entity.y = parseFloat(data[20])
      break
    case 'CIRCLE':
      entity.x = parseFloat(data[10])
      entity.y = parseFloat(data[20])
      entity.thickness = parseFloat(data[40])
      break
    case 'ARC':
      entity.x = parseFloat(data[10])
      entity.y = parseFloat(data[20])
      entity.thickness = parseFloat(data[40])
      break
    case 'TEXT':
    case 'MTEXT':
      entity.x = parseFloat(data[10])
      entity.y = parseFloat(data[20])
      entity.text = data[1] || data[3]
      entity.height = parseFloat(data[40])
      break
    case 'DIMENSION':
      entity.x = parseFloat(data[10])
      entity.y = parseFloat(data[20])
      entity.text = data[1]
      break
    case 'INSERT':
      entity.x = parseFloat(data[10])
      entity.y = parseFloat(data[20])
      break
    case 'POINT':
      entity.x = parseFloat(data[10])
      entity.y = parseFloat(data[20])
      break
  }
  
  return entity
}

function getEntityCoordinates(entity: DXFEntity): Point2D[] {
  const points: Point2D[] = []
  
  if (entity.x1 !== undefined && entity.y1 !== undefined) {
    points.push({ easting: entity.x1, northing: entity.y1 })
  }
  if (entity.x2 !== undefined && entity.y2 !== undefined) {
    points.push({ easting: entity.x2, northing: entity.y2 })
  }
  if (entity.x !== undefined && entity.y !== undefined) {
    points.push({ easting: entity.x, northing: entity.y })
  }
  
  return points
}

function inferWalls(entities: DXFEntity[], boundingBox: BoundingBox2D): ExtractedWall[] {
  const walls: ExtractedWall[] = []
  const wallLayers = ['WALLS', 'WALL', 'A-WALL', 'STRUCTURAL', 'MAIN', 'PARTITION']
  const lineEntities = entities.filter((e: any) => 
    e.type === 'LINE' && 
    e.x1 !== undefined && e.y1 !== undefined &&
    e.x2 !== undefined && e.y2 !== undefined
  )
  
  lineEntities.forEach((line, idx) => {
    const length = Math.sqrt(
      Math.pow((line.x2 || 0) - (line.x1 || 0), 2) + 
      Math.pow((line.y2 || 0) - (line.y1 || 0), 2)
    )
    
    if (length > 0.5) {
      const layer = line.layer?.toUpperCase() || ''
      const isLoadBearing = wallLayers.some((l: any) => 
        layer.includes('MAIN') || layer.includes('STRUCTURAL') || layer.includes('BEARING')
      )
      
      walls.push({
        id: `wall_${idx}`,
        type: isLoadBearing ? 'load-bearing' : 'partition',
        startPoint: { easting: line.x1 || 0, northing: line.y1 || 0 },
        endPoint: { easting: line.x2 || 0, northing: line.y2 || 0 },
        thickness: 0.2,
        height: 3.0,
        material: 'concrete',
        level: 0,
      })
    }
  })
  
  return walls
}

function extractAnnotations(entities: DXFEntity[]): ExtractedAnnotation[] {
  const annotations: ExtractedAnnotation[] = []
  const textEntities = entities.filter((e: any) => 
    (e.type === 'TEXT' || e.type === 'MTEXT') && 
    e.text && e.x !== undefined && e.y !== undefined
  )
  
  textEntities.forEach((text, idx) => {
    annotations.push({
      id: `annotation_${idx}`,
      type: 'text',
      position: { easting: text.x || 0, northing: text.y || 0 },
      content: text.text || '',
      level: 0,
    })
  })
  
  return annotations
}

function inferRoomsFromWalls(walls: ExtractedWall[], boundingBox: BoundingBox2D): ExtractedRoom[] {
  const rooms: ExtractedRoom[] = []
  
  const centerE = (boundingBox.minEasting + boundingBox.maxEasting) / 2
  const centerN = (boundingBox.minNorthing + boundingBox.maxNorthing) / 2
  
  rooms.push({
    id: 'room_1',
    name: 'Living Room',
    floor: 0,
    boundary: [
      { easting: boundingBox.minEasting, northing: boundingBox.minNorthing },
      { easting: boundingBox.maxEasting, northing: boundingBox.minNorthing },
      { easting: boundingBox.maxEasting, northing: boundingBox.maxNorthing },
      { easting: boundingBox.minEasting, northing: boundingBox.maxNorthing },
    ],
    area: (boundingBox.maxEasting - boundingBox.minEasting) * (boundingBox.maxNorthing - boundingBox.minNorthing),
    perimeter: 2 * ((boundingBox.maxEasting - boundingBox.minEasting) + (boundingBox.maxNorthing - boundingBox.minNorthing)),
    height: 3.0,
    function: 'living',
  })
  
  return rooms
}

export async function parseDXFFileContent(content: string, filename: string): Promise<ParsedInput> {
  const parseResult = parseDXFFile(content)
  
  const walls = inferWalls(parseResult.entities, parseResult.boundingBox)
  const annotations = extractAnnotations(parseResult.entities)
  const rooms = inferRoomsFromWalls(walls, parseResult.boundingBox)
  
  const building: ExtractedBuildingData = {
    floors: [{
      id: 'floor_0',
      level: 0,
      name: 'Ground Floor',
      elevation: 0,
      boundingBox: parseResult.boundingBox,
    }],
    walls,
    rooms,
    doors: [],
    windows: [],
    columns: [],
    beams: [],
    annotations,
    boundingBox: parseResult.boundingBox,
    metadata: {
      units: parseResult.units as 'meters' | 'centimeters' | 'millimeters',
      projectName: filename.replace(/\.[^/.]+$/, ''),
    },
  }
  
  const confidence = calculateConfidence(building)
  
  return {
    type: 'DXF',
    sourceFileName: filename,
    sourceFileSize: Buffer.byteLength(content, 'utf8'),
    sourceFileLastModified: Date.now(),
    parsedAt: new Date().toISOString(),
    version: '1.0.0',
    building,
    errors: [],
    warnings: [
      parseResult.units !== 'meters' ? `Detected units: ${parseResult.units}` : '',
    ].filter(Boolean),
    confidence,
  }
}

export function parseDXFBuffer(buffer: Buffer, filename: string): Promise<ParsedInput> {
  const content = buffer.toString('utf8')
  return parseDXFFileContent(content, filename)
}

import type { ParsedInput, ExtractedBuildingData, ExtractedAnnotation, BoundingBox2D, ExtractedWall, ExtractedRoom, ExtractedFloor, Point2D } from './types'
