import { SurveyDataset } from '../workflows/workflowEngine'

export function detectSurveyType(
  headers: string[], 
  rows: Record<string, string>[]
): SurveyDataset['surveyType'] {
  
  const h = headers.map((h: any) => h.toLowerCase().trim())
  
  // Leveling detection
  if (h.includes('bs') || h.includes('fs') || h.includes('is')) {
    return 'leveling'
  }
  
  // Traverse detection  
  if (
    (h.includes('bearing') || h.includes('wcb')) && 
    (h.includes('distance') || h.includes('length'))
  ) {
    return 'traverse'
  }
  
  // Radiation detection
  if (
    h.includes('angle') && h.includes('distance') &&
    !h.includes('bearing')
  ) {
    return 'radiation'
  }
  
  // Coordinate data
  if (h.includes('easting') && h.includes('northing')) {
    return 'coordinates'
  }
  
  return 'unknown'
}

export interface ParsedPoint {
  pointId: string
  easting?: number
  northing?: number
  elevation?: number
  code?: string
  rawData: Record<string, string>
}

export interface ParseResult {
  format: 'gsi' | 'jobxml' | 'topcon' | 'csv' | 'unknown'
  points: ParsedPoint[]
  errors: string[]
  warnings: string[]
  metadata: Record<string, string>
}

function detectFormat(content: string, filename: string): string {
  const ext = filename.toLowerCase().split('.').pop() || ''
  if (ext === 'gsi' || ext === 'xml') {
    const trimmed = content.trim()
    if (trimmed.startsWith('*') && trimmed.includes('21.') && trimmed.includes('22.')) return 'gsi'
    if (trimmed.startsWith('<')) return 'jobxml'
  }
  if (ext === 'csv' || ext === 'txt') {
    const lines = content.split('\n').filter((l) => l.trim())
    if (lines[0]?.toLowerCase().includes('pt') && lines[0]?.toLowerCase().includes('n')) return 'topcon'
    if (lines[0]?.toLowerCase().includes('point') || lines[0]?.toLowerCase().includes('easting')) return 'csv'
  }
  const trimmed = content.trim()
  if (trimmed.startsWith('*') && trimmed.includes('21.') && trimmed.includes('22.')) return 'gsi'
  if (trimmed.startsWith('<')) return 'jobxml'
  return 'unknown'
}

function parseGSI(content: string): ParseResult {
  const points: ParsedPoint[] = []
  const errors: string[] = []
  const warnings: string[] = []
  const metadata: Record<string, string> = { format: 'Leica GSI' }

  const lines = content.split('\n').filter((l) => l.trim())
  let pointCount = 0

  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed.startsWith('*')) continue

    const words = trimmed.split(/\s+/)
    const pointData: Record<string, string> = {}

    for (const word of words) {
      if (!word.includes('.')) continue
      const dotIdx = word.indexOf('.')
      const key = word.substring(0, dotIdx)
      const value = word.substring(dotIdx + 1)
      pointData[key] = value
    }

    if (Object.keys(pointData).length === 0) continue

    const pointId = pointData['1']?.replace(/^0+/, '') || `P${pointCount + 1}`
    const easting = parseFloat(pointData['21']) / 10000
    const northing = parseFloat(pointData['22']) / 10000
    const elevation = pointData['23'] ? parseFloat(pointData['23']) / 10000 : undefined
    const code = pointData['33']?.replace(/\+/g, ' ').trim() || undefined

    if (!isNaN(easting) && !isNaN(northing)) {
      points.push({ pointId, easting, northing, elevation, code, rawData: pointData })
      pointCount++
    } else {
      warnings.push(`Point ${pointId}: Missing or invalid coordinates — skipped`)
    }
  }

  if (points.length === 0) {
    errors.push('No valid coordinate points found in GSI file. Ensure file contains GSI-8 or GSI-16 format with 21/22 word codes.')
  }

  return { format: 'gsi', points, errors, warnings, metadata }
}

function parseJobXML(content: string): ParseResult {
  const points: ParsedPoint[] = []
  const errors: string[] = []
  const warnings: string[] = []
  const metadata: Record<string, string> = { format: 'Trimble JobXML' }

  try {
    const parser = new DOMParser()
    const doc = parser.parseFromString(content, 'text/xml')

    const jobName = doc.querySelector('Job')?.getAttribute('name') || doc.querySelector('Name')?.textContent || ''
    metadata['job'] = jobName

    const obsElements = doc.querySelectorAll('Obs, Point, Observation')
    let pointCount = 0

    for (const obs of Array.from(obsElements)) {
      const getAttr = (el: Element, name: string) =>
        el.getAttribute(name) || el.querySelector(name)?.textContent || ''

      const pointId = getAttr(obs as Element, 'name') || getAttr(obs as Element, 'id') || getAttr(obs as Element, 'pt') || `P${pointCount + 1}`
      const rawEl = obs as Element

      const easting = parseFloat(getAttr(rawEl, 'east') || getAttr(rawEl, 'easting') || rawEl.querySelector('Easting')?.textContent || '')
      const northing = parseFloat(getAttr(rawEl, 'north') || getAttr(rawEl, 'northing') || rawEl.querySelector('Northing')?.textContent || '')
      const elevation = parseFloat(getAttr(rawEl, 'z') || getAttr(rawEl, 'elev') || rawEl.querySelector('Elevation')?.textContent || '')
      const code = getAttr(rawEl, 'code') || getAttr(rawEl, 'desc') || undefined

      if (!isNaN(easting) && !isNaN(northing)) {
        points.push({
          pointId: String(pointId),
          easting,
          northing,
          elevation: isNaN(elevation) ? undefined : elevation,
          code: code || undefined,
          rawData: {},
        })
        pointCount++
      }
    }
  } catch {
    errors.push('Failed to parse JobXML. Ensure valid XML format.')
  }

  if (points.length === 0) {
    errors.push('No valid coordinate points found in JobXML file.')
  }

  return { format: 'jobxml', points, errors, warnings, metadata }
}

function parseTopconGTS(content: string): ParseResult {
  const points: ParsedPoint[] = []
  const errors: string[] = []
  const warnings: string[] = []
  const metadata: Record<string, string> = { format: 'Topcon GTS' }

  const lines = content.split('\n').filter((l) => l.trim())
  const header = lines[0]?.toLowerCase() || ''
  const hasHeader = header.includes('pt') || header.includes('n') || header.includes('e')

  const dataLines = hasHeader ? lines.slice(1) : lines
  let pointCount = 0

  for (const line of dataLines) {
    const parts = line.split(/[,\t\s]+/).filter((p) => p.trim())
    if (parts.length < 3) continue

    const pointId = parts[0].trim()
    const n = parseFloat(parts[1])
    const e = parseFloat(parts[2])
    const z = parts[3] ? parseFloat(parts[3]) : undefined
    const code = parts[4]?.trim() || undefined

    if (!isNaN(n) && !isNaN(e)) {
      points.push({
        pointId,
        easting: e,
        northing: n,
        elevation: z && !isNaN(z) ? z : undefined,
        code,
        rawData: {},
      })
      pointCount++
    } else {
      warnings.push(`Line "${line}": Invalid numeric data — skipped`)
    }
  }

  if (points.length === 0) {
    errors.push('No valid coordinate points found. Expected format: PT, N, E, Z, CD (comma or tab separated).')
  }

  return { format: 'topcon', points, errors, warnings, metadata }
}

function parseCSV(content: string): ParseResult {
  const points: ParsedPoint[] = []
  const errors: string[] = []
  const warnings: string[] = []
  const metadata: Record<string, string> = { format: 'Generic CSV' }

  const lines = content.split('\n').filter((l) => l.trim())
  if (lines.length < 2) {
    errors.push('CSV file must have at least a header row and one data row.')
    return { format: 'csv', points, errors, warnings, metadata }
  }

  const header = lines[0].toLowerCase()
  const cols = lines[0].split(/[,\t]+/).map((c) => c.trim().toLowerCase().replace(/[^a-z0-9_]/g, ''))

  const pidIdx = cols.findIndex(c => c.includes('id') || c.includes('label') || c === 'pt' || c === 'point')
  const eIdx = cols.findIndex(c => c.includes('east') || c === 'e' || c === 'x')
  const nIdx = cols.findIndex(c => c.includes('north') || c === 'n' || c === 'y')
  const zIdx = cols.findIndex(c => c.includes('elev') || c.includes('z') || c.includes('height') || c === 'rl')
  const codeIdx = cols.findIndex(c => c.includes('code') || c.includes('desc') || c.includes('cd'))

  if (eIdx === -1 || nIdx === -1) {
    errors.push('CSV must contain at least Easting (E) and Northing (N) columns.')
    return { format: 'csv', points, errors, warnings, metadata }
  }

  for (let i = 1; i < lines.length; i++) {
    const parts = lines[i].split(/[,\t]+/).map((p) => p.trim())
    const pointId = pidIdx >= 0 ? (parts[pidIdx] || `P${i}`) : `P${i}`
    const easting = parseFloat(parts[eIdx])
    const northing = parseFloat(parts[nIdx])
    const elevation = zIdx >= 0 && parts[zIdx] ? parseFloat(parts[zIdx]) : undefined
    const code = codeIdx >= 0 ? parts[codeIdx] : undefined

    if (!isNaN(easting) && !isNaN(northing)) {
      points.push({
        pointId,
        easting,
        northing,
        elevation: elevation && !isNaN(elevation) ? elevation : undefined,
        code: code || undefined,
        rawData: {},
      })
    } else {
      warnings.push(`Row ${i + 1}: Invalid coordinates — skipped`)
    }
  }

  metadata['pointCount'] = String(points.length)
  return { format: 'csv', points, errors, warnings, metadata }
}

export function parseTotalStationFile(content: string, filename: string): ParseResult {
  const format = detectFormat(content, filename)
  switch (format) {
    case 'gsi': return parseGSI(content)
    case 'jobxml': return parseJobXML(content)
    case 'topcon': return parseTopconGTS(content)
    case 'csv': return parseCSV(content)
    default: {
      const csvResult = parseCSV(content)
      if (csvResult.points.length > 0) return csvResult
      return {
        format: 'unknown',
        points: [],
        errors: ['Unknown file format. Supported formats: Leica GSI, Trimble JobXML, Topcon GTS, and Generic CSV.'],
        warnings: [],
        metadata: {},
      }
    }
  }
}

export function parseTraverseCSV(content: string): {
  headers: string[]
  rows: string[][]
  errors: string[]
} {
  const lines = content.split('\n').filter((l) => l.trim())
  if (lines.length < 2) return { headers: [], rows: [], errors: ['File is empty or has no data rows'] }

  const headers = lines[0].split(/[,\t]+/).map((h) => h.trim().toLowerCase().replace(/\s+/g, '_'))
  const rows = lines.slice(1).map((line: any) =>
    line.split(/[,\t]+/).map((cell: any) => cell.trim())
  ).filter((r) => r.some((c: any) => c.length > 0))

  const errors: string[] = []
  if (!headers.some((h) => h.includes('station'))) errors.push('Missing "station" column')
  if (!headers.some((h) => h.includes('slope_dist') || h.includes('dist') || h.includes('sd'))) {
    errors.push('Missing slope distance column (slope_dist, dist, or sd)')
  }

  return { headers, rows, errors }
}

/**
 * P0-4 verification: M-Pesa parseCallback + amount-verification logic.
 *
 * The callback route itself requires a running DB + mocked Next.js
 * Request, so it's tested via integration. This unit test covers the
 * critical fraud-prevention pieces:
 *
 * 1. parseCallback correctly extracts Amount + MpesaReceiptNumber
 *    from the Safaricom STK Push callback payload
 * 2. parseCallback returns null for malformed payloads (no
 *    CallbackMetadata)
 * 3. parseCallback correctly marks failed transactions (ResultCode != 0)
 *
 * The amount-verification logic in the callback route (step 7) is the
 * critical fraud check: it compares the ACTUAL paid amount (from
 * parseCallback) against the EXPECTED plan price (from getPlan).
 * Previously this compared expected vs expected (both from the DB row),
 * so a user could pay KES 1 for a Pro plan and it would succeed.
 */
import { MpesaService } from '@/lib/payments/mpesa'
import { getPlan } from '@/lib/subscription/catalog'

describe('P0-4: M-Pesa callback parsing + amount verification', () => {
  // Minimal MpesaService instance — parseCallback is a pure method
  // that doesn't use any instance state, so empty config is fine.
  const mpesa = new MpesaService({
    consumerKey: '',
    consumerSecret: '',
    shortCode: '',
    initiatorName: '',
    securityCredential: '',
    environment: 'sandbox',
  })

  // Real Safaricom STK Push callback payload (success case)
  const successPayload = {
    Body: {
      stkCallback: {
        MerchantRequestID: '29115-34620561-1',
        CheckoutRequestID: 'ws_CO_191220191020363925',
        ResultCode: 0,
        ResultDesc: 'The service request is processed successfully.',
        CallbackMetadata: {
          Item: [
            { Name: 'Amount', Value: 500 },
            { Name: 'MpesaReceiptNumber', Value: 'NLJ7RT61SV' },
            { Name: 'Balance' },
            { Name: 'TransactionDate', Value: 20191219102115 },
            { Name: 'PhoneNumber', Value: 254708374149 },
          ],
        },
      },
    },
  }

  // Failed callback (user cancelled / insufficient funds)
  const failedPayload = {
    Body: {
      stkCallback: {
        MerchantRequestID: '29115-34620561-1',
        CheckoutRequestID: 'ws_CO_191220191020363925',
        ResultCode: 1032, // "Request cancelled by user"
        ResultDesc: 'Request cancelled by user',
      },
    },
  }

  describe('parseCallback', () => {
    test('extracts amount + receipt number from success payload', () => {
      const result = mpesa.parseCallback(successPayload)
      expect(result).not.toBeNull()
      expect(result!.amount).toBe(500)
      expect(result!.transactionId).toBe('NLJ7RT61SV')
      expect(result!.phone).toBe('254708374149')
      expect(result!.status).toBe('completed')
    })

    test('returns null for failed callback (no CallbackMetadata)', () => {
      const result = mpesa.parseCallback(failedPayload)
      expect(result).toBeNull()
    })

    test('returns null for malformed payload (missing Body)', () => {
      expect(mpesa.parseCallback({} as Record<string, unknown>)).toBeNull()
      expect(mpesa.parseCallback({ Body: {} } as Record<string, unknown>)).toBeNull()
      expect(mpesa.parseCallback({ Body: { stkCallback: {} } } as Record<string, unknown>)).toBeNull()
    })

    test('handles missing Amount gracefully (returns 0)', () => {
      const payload = {
        Body: {
          stkCallback: {
            ResultCode: 0,
            CallbackMetadata: {
              Item: [{ Name: 'MpesaReceiptNumber', Value: 'ABC123' }],
            },
          },
        },
      }
      const result = mpesa.parseCallback(payload as Record<string, unknown>)
      expect(result).not.toBeNull()
      expect(result!.amount).toBe(0)
      expect(result!.transactionId).toBe('ABC123')
    })
  })

  describe('amount verification logic (callback route step 7)', () => {
    // This mirrors the logic in callback/route.ts lines 140-168:
    //   const plan = getPlan(planId)
    //   const expectedAmount = plan?.prices?.KES ?? Number(paymentRow.amount) ?? 0
    //   if (paidAmount > 0 && expectedAmount > 0 &&
    //       Math.round(paidAmount) !== Math.round(expectedAmount)) {
    //     // → mark as failed, fraudFlag = 'amount_mismatch'
    //   }

    test('Pro plan has a KES price that can be looked up', () => {
      const plan = getPlan('pro')
      expect(plan).toBeDefined()
      expect(plan!.prices?.KES).toBeDefined()
      expect(plan!.prices!.KES).toBeGreaterThan(0)
    })

    test('matching amount passes verification', () => {
      const plan = getPlan('pro')
      const expectedAmount = plan!.prices!.KES
      const paidAmount = expectedAmount // exact match

      const matches =
        Number.isFinite(expectedAmount) &&
        expectedAmount > 0 &&
        Number.isFinite(paidAmount) &&
        paidAmount > 0 &&
        Math.round(paidAmount) !== Math.round(expectedAmount)

      expect(matches).toBe(false) // false = no mismatch = pass
    })

    test('underpayment (KES 1 for Pro plan) is flagged as mismatch', () => {
      const plan = getPlan('pro')
      const expectedAmount = plan!.prices!.KES
      const paidAmount = 1 // user pays KES 1 instead of the Pro price

      const isMismatch =
        Number.isFinite(expectedAmount) &&
        expectedAmount > 0 &&
        Number.isFinite(paidAmount) &&
        paidAmount > 0 &&
        Math.round(paidAmount) !== Math.round(expectedAmount)

      expect(isMismatch).toBe(true) // true = mismatch = fraud flag
    })

    test('overpayment is also flagged (defensive)', () => {
      const plan = getPlan('pro')
      const expectedAmount = plan!.prices!.KES
      const paidAmount = expectedAmount * 2

      const isMismatch =
        Number.isFinite(expectedAmount) &&
        expectedAmount > 0 &&
        Number.isFinite(paidAmount) &&
        paidAmount > 0 &&
        Math.round(paidAmount) !== Math.round(expectedAmount)

      expect(isMismatch).toBe(true)
    })

    test('zero paid amount does not trigger mismatch (graceful — lets manual review handle it)', () => {
      // This mirrors the route logic: if paidAmount is 0 (parseCallback
      // failed to extract), the check is skipped to avoid false positives.
      // The route still marks the payment as completed in this case,
      // which is a known limitation — but better than blocking legit
      // payments where Safaricom's payload was malformed.
      const plan = getPlan('pro')
      const expectedAmount = plan!.prices!.KES
      const paidAmount = 0

      const isMismatch =
        Number.isFinite(expectedAmount) &&
        expectedAmount > 0 &&
        Number.isFinite(paidAmount) &&
        paidAmount > 0 && // ← this short-circuits to false when paidAmount is 0
        Math.round(paidAmount) !== Math.round(expectedAmount)

      expect(isMismatch).toBe(false)
    })
  })
})

/**
 * M-Pesa Mobile Money Integration
 * Supports Kenya M-Pesa, Uganda Airtel Money, Tanzania M-Pesa
 */

import { mpesaBreaker } from '@/lib/resilience/circuitBreaker'

export interface MpesaConfig {
  consumerKey: string
  consumerSecret: string
  shortCode: string
  initiatorName: string
  securityCredential: string
  environment: 'sandbox' | 'production'
}

export interface STKPushParams {
  phoneNumber: string
  amount: number
  reference: string
  description?: string
  callbackUrl?: string
}

export interface MpesaTransaction {
  transactionId: string
  amount: number
  phone: string
  reference: string
  status: 'pending' | 'completed' | 'failed'
  timestamp: string
}

export class MpesaService {
  private consumerKey: string
  private consumerSecret: string
  private shortCode: string
  private initiatorName: string
  private securityCredential: string
  private environment: 'sandbox' | 'production'

  constructor(config: MpesaConfig) {
    this.consumerKey = config.consumerKey
    this.consumerSecret = config.consumerSecret
    this.shortCode = config.shortCode
    this.initiatorName = config.initiatorName
    this.securityCredential = config.securityCredential
    this.environment = config.environment
  }

  private get baseUrl(): string {
    return this.environment === 'sandbox'
      ? 'https://sandbox.safaricom.co.ke'
      : 'https://api.safaricom.co.ke'
  }

  private async getAccessToken(): Promise<string> {
    const credentials = Buffer.from(`${this.consumerKey}:${this.consumerSecret}`).toString('base64')

    const response = await fetch(`${this.baseUrl}/oauth/v1/generate?grant_type=client_credentials`, {
      headers: {
        'Authorization': `Basic ${credentials}`
      }
    })

    if (!response.ok) {
      // AUDIT FIX (M15, 2026-07-02): Actionable error message.
      const errorBody = await response.text().catch(() => 'unknown')
      throw new Error(
        'Could not obtain M-Pesa access token from Safaricom Daraja API. ' +
        'Check: (1) MPESA_CONSUMER_KEY and MPESA_CONSUMER_SECRET are set correctly, ' +
        '(2) MPESA_ENV is "sandbox" or "production" and matches your credentials, ' +
        '(3) Safaricom Daraja API is reachable (check network/firewall). ' +
        `HTTP ${response.status}: ${errorBody}`
      )
    }

    const data = await response.json()
    return data.access_token
  }

  async initiateSTKPush(params: STKPushParams): Promise<{ checkoutRequestId: string; responseCode: string }> {
    const accessToken = await this.getAccessToken()

    const timestamp = new Date().toISOString().replace(/[-:T.Z]/g, '').slice(0, 14)
    const password = Buffer.from(`${this.shortCode}${process.env.MPESA_PASSKEY || ''}${timestamp}`).toString('base64')

    const response = await mpesaBreaker.execute(() => fetch(`${this.baseUrl}/mpesa/stkpush/v1/processrequest`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        BusinessShortCode: this.shortCode,
        Password: password,
        Timestamp: timestamp,
        TransactionType: 'CustomerBuyGoodsOnline',
        Amount: Math.round(params.amount),
        PartyA: params.phoneNumber,
        PartyB: this.shortCode,
        PhoneNumber: params.phoneNumber,
        CallBackURL: params.callbackUrl || `${process.env.NEXT_PUBLIC_APP_URL}/api/payments/mpesa/callback`,
        AccountReference: params.reference,
        TransactionDesc: params.description || 'METARDU Payment'
      })
    }))

    if (!response.ok) {
      const error = await response.json()
      // AUDIT FIX (M15, 2026-07-02): Translate Safaricom internal error codes.
      const safaricomErrors: Record<string, string> = {
        'DS090.301.BF00002': 'Invalid phone number — the phone must be a registered M-Pesa number in the format 2547XXXXXXXX',
        'DS090.301.BF00003': 'Insufficient funds — the user does not have enough M-Pesa balance',
        'DS090.301.BF00004': 'Transaction cancelled by user',
        'DS090.301.BF00005': 'Transaction timed out — the user did not respond to the STK prompt within 60 seconds',
      }
      const translated = error.errorMessage
        ? safaricomErrors[error.errorMessage] ?? `Safaricom error: ${error.errorMessage}`
        : 'STK Push failed — Safaricom did not accept the payment request'
      throw new Error(translated)
    }

    const data = await response.json()
    return {
      checkoutRequestId: data.CheckoutRequestID,
      responseCode: data.ResponseCode
    }
  }

  async checkTransactionStatus(checkoutRequestId: string): Promise<{ status: string; amount?: number; phone?: string; resultCode?: number; resultDesc?: string }> {
    const accessToken = await this.getAccessToken()

    const timestamp = new Date().toISOString().replace(/[-:T.Z]/g, '').slice(0, 14)
    const password = Buffer.from(`${this.shortCode}${process.env.MPESA_PASSKEY || ''}${timestamp}`).toString('base64')

    const response = await fetch(`${this.baseUrl}/mpesa/stkpushquery/v1/query`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        BusinessShortCode: this.shortCode,
        Password: password,
        Timestamp: timestamp,
        CheckoutRequestID: checkoutRequestId
      })
    })

    if (!response.ok) {
      // AUDIT FIX (CRITICAL 2, 2026-07-02): Actionable error message.
      const errBody = await response.text().catch(() => 'unknown')
      throw new Error(
        `Failed to check M-Pesa transaction status (HTTP ${response.status}). ${errBody}. ` +
        `Check MPESA_CONSUMER_KEY/SECRET and MPESA_PASSKEY are correct.`
      )
    }

    const data = await response.json()
    // AUDIT FIX (CRITICAL 2, 2026-07-02): Check ResultCode, not ResponseCode.
    // ResponseCode === '0' means the *query API call* succeeded — it does NOT
    // mean the payment was completed. The actual payment status is in
    // ResultCode: 0 = success, anything else = failure.
    // Reference: Safaricom Daraja API docs — STK Push Query
    return {
      status: data.ResultCode === 0 ? 'completed' : 'failed',
      amount: data.Amount ? parseFloat(data.Amount) : undefined,
      phone: data.PhoneNumber,
      resultCode: data.ResultCode,
      resultDesc: data.ResultDesc,
    }
  }

  async registerC2BUrls(): Promise<boolean> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/mpesa/c2b/v1/registerurl`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        ShortCode: this.shortCode,
        ResponseType: 'Completed',
        ConfirmationURL: `${process.env.NEXT_PUBLIC_APP_URL}/api/payments/mpesa/c2b/confirm`,
        ValidationURL: `${process.env.NEXT_PUBLIC_APP_URL}/api/payments/mpesa/c2b/validate`
      })
    })

    return response.ok
  }

  parseCallback(payload: Record<string, unknown>): MpesaTransaction | null {
    const body = payload.Body as { stkCallback?: { ResultCode: number; CallbackMetadata?: { Item: { Name: string; Value: string | number }[] } } }
    
    if (!body?.stkCallback?.CallbackMetadata) return null

    const items = body.stkCallback.CallbackMetadata.Item
    const getValue = (name: string): string | number | undefined =>
      items.find((i) => i.Name === name)?.Value

    return {
      transactionId: String(getValue('MpesaReceiptNumber') || ''),
      amount: Number(getValue('Amount')) || 0,
      phone: String(getValue('PhoneNumber') || ''),
      reference: String(getValue('AccountReference') || ''),
      status: body.stkCallback.ResultCode === 0 ? 'completed' : 'failed',
      timestamp: new Date().toISOString()
    }
  }
}

export class AirtelMoneyService {
  private clientId: string
  private clientSecret: string
  private environment: 'sandbox' | 'production'

  constructor(clientId: string, clientSecret: string, environment: 'sandbox' | 'production' = 'sandbox') {
    this.clientId = clientId
    this.clientSecret = clientSecret
    this.environment = environment
  }

  private get baseUrl(): string {
    return this.environment === 'sandbox'
      ? 'https://api.sandbox.airtel.africa'
      : 'https://api.airtel.africa'
  }

  async initiatePayment(phone: string, amount: number, reference: string): Promise<{ transactionId: string }> {
    const credentials = Buffer.from(`${this.clientId}:${this.clientSecret}`).toString('base64')

    const response = await fetch(`${this.baseUrl}/merchant/v1/payments`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${credentials}`,
        'Content-Type': 'application/json',
        'X-Country': 'UGA',
        'X-Currency': 'UGX'
      },
      body: JSON.stringify({
        reference,
        subscriber: {
          country: 'UG',
          msisdn: phone.replace(/^256/, '')
        },
        transaction: {
          amount,
          currency: 'UGX',
          description: 'METARDU Payment'
        }
      })
    })

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || 'Airtel payment failed')
    }

    const data = await response.json()
    return {
      transactionId: data.data?.transaction?.id || ''
    }
  }
}

export function getMpesaService(): MpesaService | null {
  const consumerKey = process.env.MPESA_CONSUMER_KEY
  const consumerSecret = process.env.MPESA_CONSUMER_SECRET

  if (!consumerKey || !consumerSecret) return null

  // AUDIT FIX (HIGH 10, 2026-07-02): Use MPESA_ENV, not NODE_ENV.
  // NODE_ENV=production does NOT mean M-Pesa is in production mode —
  // the app can run in production with M-Pesa still in sandbox for testing.
  // MPESA_ENV explicitly controls the M-Pesa environment.
  return new MpesaService({
    consumerKey,
    consumerSecret,
    shortCode: process.env.MPESA_SHORT_CODE || '',
    initiatorName: process.env.MPESA_INITIATOR_NAME || '',
    securityCredential: process.env.MPESA_SECURITY_CREDENTIAL || '',
    environment: (process.env.MPESA_ENV as 'sandbox' | 'production') || 'sandbox'
  })
}

/**
 * PayPal Payment Integration
 * Processes PayPal payments
 */

export interface PayPalConfig {
  clientId: string
  clientSecret: string
  mode: 'sandbox' | 'live'
}

export interface PayPalOrder {
  id: string
  status: string
  links: { rel: string; href: string }[]
}

export interface PayPalCaptureResult {
  id: string
  status: string
  purchase_units: {
    payments: {
      captures: { id: string; status: string; amount: { value: string; currency_code: string } }[]
    }[]
  }[]
}

export class PayPalService {
  private clientId: string
  private clientSecret: string
  private mode: 'sandbox' | 'live'
  private accessToken: string | null = null
  private tokenExpiry: number = 0

  constructor(config: PayPalConfig) {
    this.clientId = config.clientId
    this.clientSecret = config.clientSecret
    this.mode = config.mode
  }

  private get baseUrl(): string {
    return this.mode === 'sandbox'
      ? 'https://api-m.sandbox.paypal.com'
      : 'https://api-m.paypal.com'
  }

  private async getAccessToken(): Promise<string> {
    if (this.accessToken && Date.now() < this.tokenExpiry) {
      return this.accessToken
    }

    const credentials = Buffer.from(`${this.clientId}:${this.clientSecret}`).toString('base64')
    
    const response = await fetch(`${this.baseUrl}/v1/oauth2/token`, {
      method: 'POST',
      headers: {
        'Authorization': `Basic ${credentials}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: 'grant_type=client_credentials'
    })

    if (!response.ok) {
      const errorBody = await response.text().catch(() => 'unknown')
      console.error(`[PayPal] Token request failed: ${response.status} ${response.statusText} | mode=${this.mode} | body=${errorBody}`)
      throw new Error(`Failed to obtain PayPal access token (${response.status}). Mode: ${this.mode}. Check PAYPAL_MODE, CLIENT_ID and CLIENT_SECRET.`)
    }

    const data = await response.json()
    this.accessToken = data.access_token
    this.tokenExpiry = Date.now() + (data.expires_in * 1000) - 60000

    return this.accessToken!
  }

  private currencyMinorUnitDigits(currency: string): number {
    try {
      const nf = new Intl.NumberFormat('en-US', { style: 'currency', currency: currency.toUpperCase() })
      return nf.resolvedOptions().maximumFractionDigits ?? 2
    } catch {
      return 2
    }
  }

  async createOrder(input: {
    amount: number
    currency?: string
    description?: string
    returnUrl?: string
    cancelUrl?: string
  }): Promise<PayPalOrder> {
    const accessToken = await this.getAccessToken()
    const currency = input.currency || 'USD'
    const digits = this.currencyMinorUnitDigits(currency)
    const value = input.amount.toFixed(digits)

    const response = await fetch(`${this.baseUrl}/v2/checkout/orders`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        intent: 'CAPTURE',
        purchase_units: [{
          amount: {
            currency_code: currency,
            value
          },
          ...(input.description && { description: input.description })
        }],
        ...(input.returnUrl || input.cancelUrl
          ? {
              application_context: {
                return_url: input.returnUrl,
                cancel_url: input.cancelUrl,
                brand_name: 'METARDU',
                landing_page: 'NO_PREFERENCE',
                user_action: 'PAY_NOW',
              },
            }
          : {}),
      })
    })

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || 'Failed to create PayPal order')
    }

    return response.json()
  }

  async captureOrder(orderId: string): Promise<PayPalCaptureResult> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v2/checkout/orders/${orderId}/capture`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      }
    })

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || 'Failed to capture PayPal order')
    }

    return response.json()
  }

  async getOrderDetails(orderId: string): Promise<PayPalOrder> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v2/checkout/orders/${orderId}`, {
      headers: {
        'Authorization': `Bearer ${accessToken}`
      }
    })

    if (!response.ok) {
      throw new Error('Failed to get PayPal order details')
    }

    return response.json()
  }

  async createSubscription(planId: string, subscriber: { email: string; name?: string }): Promise<{ subscriptionId: string; approvalUrl: string }> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v1/billing/subscriptions`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        plan_id: planId,
        subscriber: {
          email_address: subscriber.email,
          ...(subscriber.name && {
            name: { given_name: subscriber.name.split(' ')[0], surname: subscriber.name.split(' ').slice(1).join(' ') }
          })
        },
        application_context: {
          brand_name: 'METARDU',
          landing_page: 'NO_PREFERENCE',
          user_action: 'SUBSCRIBE_NOW',
          return_url: `${process.env.NEXT_PUBLIC_APP_URL}/subscription/success`,
          cancel_url: `${process.env.NEXT_PUBLIC_APP_URL}/subscription/cancel`
        }
      })
    })

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.message || 'Failed to create subscription')
    }

    const data = await response.json()
    const approveLink = data.links?.find((l: { rel: string }) => l.rel === 'approve')

    return {
      subscriptionId: data.id,
      approvalUrl: approveLink?.href || ''
    }
  }

  async activateSubscription(subscriptionId: string): Promise<boolean> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v1/billing/subscriptions/${subscriptionId}/activate`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      }
    })

    return response.ok
  }

  async cancelSubscription(subscriptionId: string): Promise<boolean> {
    const accessToken = await this.getAccessToken()

    const response = await fetch(`${this.baseUrl}/v1/billing/subscriptions/${subscriptionId}/cancel`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ reason: 'User requested cancellation' })
    })

    return response.ok
  }
}

export function getPayPalService(): PayPalService | null {
  const clientId = process.env.PAYPAL_CLIENT_ID
  const clientSecret = process.env.PAYPAL_CLIENT_SECRET
  
  if (!clientId || !clientSecret) {
    console.warn('[PayPal] PAYPAL_CLIENT_ID or PAYPAL_CLIENT_SECRET not set — PayPal disabled')
    return null
  }

  // Default to sandbox unless PAYPAL_MODE=live is explicitly set.
  // NEVER auto-detect from NODE_ENV — prevents sandbox credentials hitting live API.
  const mode = (process.env.PAYPAL_MODE as 'sandbox' | 'live') || 'sandbox'

  return new PayPalService({
    clientId,
    clientSecret,
    mode
  })
}

/**
 * Stripe Payment Integration
 * Processes card payments via Stripe API
 */

import { createHmac, timingSafeEqual, randomUUID } from 'crypto'
import { stripeBreaker } from '@/lib/resilience/circuitBreaker'

export interface StripeConfig {
  secretKey: string
  publishableKey: string
  webhookSecret: string
}

export interface CreatePaymentIntentParams {
  amount: number
  currency: string
  customerId?: string
  metadata?: Record<string, string>
}

export interface StripePaymentIntent {
  id: string
  clientSecret: string
  amount: number
  currency: string
  status: string
}

export interface CreateCheckoutSessionParams {
  mode: 'payment' | 'subscription'
  amount: number
  currency: string
  name: string
  successUrl: string
  cancelUrl: string
  metadata?: Record<string, string>
}

export interface StripeCheckoutSession {
  id: string
  url: string
  paymentStatus?: string
  amountTotal?: number
  currency?: string
}

const STRIPE_API_VERSION = '2023-10-16'

export class StripeService {
  private secretKey: string

  constructor(config: StripeConfig) {
    this.secretKey = config.secretKey
  }

  private currencyMinorUnitDigits(currency: string): number {
    try {
      const nf = new Intl.NumberFormat('en-US', { style: 'currency', currency: currency.toUpperCase() })
      return nf.resolvedOptions().maximumFractionDigits ?? 2
    } catch {
      return 2
    }
  }

  private toMinorUnits(amount: number, currency: string): number {
    const digits = this.currencyMinorUnitDigits(currency)
    const factor = Math.pow(10, digits)
    return Math.round(amount * factor)
  }

  private fromMinorUnits(amountMinor: number, currency: string): number {
    const digits = this.currencyMinorUnitDigits(currency)
    const factor = Math.pow(10, digits)
    return amountMinor / factor
  }

  private buildMetadataParams(metadata?: Record<string, string>) {
    if (!metadata) return {}
    const out: Record<string, string> = {}
    for (const [k, v] of Object.entries(metadata)) {
      out[`metadata[${k}]`] = v
    }
    return out
  }

  async createPaymentIntent(params: CreatePaymentIntentParams): Promise<StripePaymentIntent> {
    const response = await stripeBreaker.execute(() => fetch('https://api.stripe.com/v1/payment_intents', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.secretKey}`,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Stripe-Version': STRIPE_API_VERSION
      },
      body: new URLSearchParams({
        amount: String(this.toMinorUnits(params.amount, params.currency)),
        currency: params.currency.toLowerCase(),
        ...(params.customerId && { customer: params.customerId }),
        ...this.buildMetadataParams(params.metadata),
      }),
    }))

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.error?.message || 'Payment failed')
    }

    const data = await response.json()
    return {
      id: data.id,
      clientSecret: data.client_secret,
      amount: this.fromMinorUnits(data.amount, data.currency),
      currency: data.currency,
      status: data.status
    }
  }

  async confirmPayment(paymentIntentId: string): Promise<boolean> {
    const response = await fetch(`https://api.stripe.com/v1/payment_intents/${paymentIntentId}`, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${this.secretKey}`,
        'Stripe-Version': STRIPE_API_VERSION
      }
    })

    if (!response.ok) return false
    const data = await response.json()
    return data.status === 'succeeded'
  }

  async createCustomer(email: string, name: string): Promise<string> {
    const response = await fetch('https://api.stripe.com/v1/customers', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.secretKey}`,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Stripe-Version': STRIPE_API_VERSION
      },
      body: new URLSearchParams({
        email,
        name
      })
    })

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.error?.message || 'Customer creation failed')
    }

    const data = await response.json()
    return data.id
  }

  async createSubscription(
    customerId: string,
    priceId: string,
    metadata?: Record<string, string>,
    idempotencyKey?: string,
  ): Promise<{ subscriptionId: string; clientSecret: string }> {
    const params = new URLSearchParams()
    params.append('customer', customerId)
    params.append('items[0][price]', priceId)
    params.append('payment_behavior', 'default_incomplete')
    params.append('payment_settings[save_default_payment_method]', 'on_subscription')
    params.append('expand', 'latest_invoice.payment_intent')

    // AUDIT FIX (CRITICAL 3, 2026-07-02): Add metadata so webhook sync
    // handlers can find the user. Without this, subscription update/delete
    // webhooks silently no-op because sub.metadata.user_id is undefined.
    if (metadata) {
      for (const [key, value] of Object.entries(metadata)) {
        params.append(`metadata[${key}]`, value)
      }
    }

    // ByteByteGo audit fix: use a stable client-supplied idempotency key (UUID)
    // instead of Date.now() which defeats idempotency on retries within the same second.
    // Also wrap the call in a circuit breaker to prevent cascading failures.
    const key = idempotencyKey || randomUUID()

    const response = await stripeBreaker.execute(() => fetch('https://api.stripe.com/v1/subscriptions', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.secretKey}`,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Stripe-Version': STRIPE_API_VERSION,
        'Idempotency-Key': key,
      },
      body: params
    }))

    if (!response.ok) {
      const error = await response.json()
      throw new Error(error.error?.message || 'Subscription creation failed')
    }

    const data = await response.json()
    const invoice = data.latest_invoice as { payment_intent?: { client_secret?: string } }

    return {
      subscriptionId: data.id,
      clientSecret: invoice.payment_intent?.client_secret || ''
    }
  }

  verifyWebhookSignature(payload: string, signature: string): boolean {
    const parts = String(signature ?? '').split(',')
    const tPart = parts.find((p) => p.startsWith('t='))
    const v1Parts = parts.filter((p) => p.startsWith('v1='))
    const timestamp = tPart?.slice(2)
    const signatures = v1Parts.map((p) => p.slice(3)).filter(Boolean)

    if (!timestamp || signatures.length === 0) return false

    // AUDIT FIX (HIGH 9, 2026-07-02): Timestamp freshness check.
    // Reject webhooks older than 5 minutes to prevent replay attacks.
    const webhookTime = parseInt(timestamp, 10) * 1000
    const now = Date.now()
    const maxAge = 5 * 60 * 1000 // 5 minutes
    if (isNaN(webhookTime) || Math.abs(now - webhookTime) > maxAge) {
      console.warn(`[stripe] Webhook timestamp outside 5min window: ${timestamp} (now: ${now})`)
      return false
    }

    const secret = process.env.STRIPE_WEBHOOK_SECRET
    if (!secret) return false

    const expected = createHmac('sha256', secret)
      .update(`${timestamp}.${payload}`)
      .digest('hex')

    try {
      const expectedBuf = Buffer.from(expected, 'utf8')
      return signatures.some((s) => {
        const sigBuf = Buffer.from(s, 'utf8')
        return sigBuf.length === expectedBuf.length && timingSafeEqual(sigBuf, expectedBuf)
      })
    } catch {
      return false
    }
  }

  async createCheckoutSession(params: CreateCheckoutSessionParams): Promise<StripeCheckoutSession> {
    const body = new URLSearchParams({
      mode: params.mode,
      success_url: params.successUrl,
      cancel_url: params.cancelUrl,
      'line_items[0][quantity]': '1',
      'line_items[0][price_data][currency]': params.currency.toLowerCase(),
      'line_items[0][price_data][product_data][name]': params.name,
      'line_items[0][price_data][unit_amount]': String(this.toMinorUnits(params.amount, params.currency)),
      ...this.buildMetadataParams(params.metadata),
    })

    const response = await fetch('https://api.stripe.com/v1/checkout/sessions', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${this.secretKey}`,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Stripe-Version': STRIPE_API_VERSION,
      },
      body,
    })

    if (!response.ok) {
      const error = await response.json().catch(() => ({}))
      throw new Error(error?.error?.message || 'Stripe checkout session failed')
    }

    const data = await response.json()
    return { id: data.id, url: data.url }
  }

  async getCheckoutSession(sessionId: string): Promise<{ id: string; paymentStatus: string; amountTotal: number; currency: string }> {
    const response = await fetch(`https://api.stripe.com/v1/checkout/sessions/${sessionId}`, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${this.secretKey}`,
        'Stripe-Version': STRIPE_API_VERSION,
      },
    })

    if (!response.ok) {
      const error = await response.json().catch(() => ({}))
      throw new Error(error?.error?.message || 'Failed to fetch Stripe session')
    }

    const data = await response.json()
    return {
      id: data.id,
      paymentStatus: data.payment_status,
      amountTotal: this.fromMinorUnits(data.amount_total ?? 0, data.currency),
      currency: data.currency,
    }
  }
}

export function getStripeService(): StripeService | null {
  const secretKey = process.env.STRIPE_SECRET_KEY
  if (!secretKey) return null
  
  return new StripeService({
    secretKey,
    publishableKey: process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY || '',
    webhookSecret: process.env.STRIPE_WEBHOOK_SECRET || ''
  })
}

/**
 * Server-side PDF generation using Puppeteer
 * Generates print-ready PDFs from survey report HTML
 */

import puppeteer from 'puppeteer'
import type { SectionContent } from '@/types/surveyReport'

export interface PdfGenerationOptions {
  title: string
  sections: SectionContent[]
  paperSize?: 'A4' | 'A3'
  orientation?: 'portrait' | 'landscape'
}

export async function generatePdf(options: PdfGenerationOptions): Promise<Buffer> {
  const {
    title,
    sections,
    paperSize = 'A4',
    orientation = 'portrait',
  } = options

  const browser = await puppeteer.launch({
    headless: true,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
    ],
  })

  try {
    const page = await browser.newPage()

    // Generate HTML content
    const html = generateReportHtml(title, sections)

    // Set HTML content
    await page.setContent(html, {
      waitUntil: 'networkidle0',
    })

    // Wait for fonts and images to load
    await new Promise(resolve => setTimeout(resolve, 1000))

  // Generate PDF
  const pdfBuffer = await page.pdf({
    format: paperSize as any,
    printBackground: true,
    margin: {
      top: '10mm',
      right: '10mm',
      bottom: '10mm',
      left: '10mm',
    },
    displayHeaderFooter: false,
    preferCSSPageSize: true,
  })

    return Buffer.from(pdfBuffer)
  } finally {
    await browser.close()
  }
}

