    padding-bottom: 3px;
  }
  .certificate-text {
    font-size: 8.5pt;
    line-height: 1.6;
    margin-bottom: 14px;
    font-style: italic;
  }
  .sig-grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 14px;
    margin-top: 6px;
  }
  .sig-item { margin-bottom: 10px; }
  .sig-line {
    border-bottom: 1px solid #000;
    height: 30px;
    margin-bottom: 4px;
  }
  .sig-label {
    font-size: 7.5pt;
    text-transform: uppercase;
    color: #555;
    letter-spacing: 0.3px;
  }

  /* ── DISCLAIMER FOOTER ──────────────────────────── */
  .disclaimer-footer {
    margin-top: 14px;
    padding: 6px 10px;
    border: 1px solid #bbb;
    background: #f5f5f0;
    font-size: 7pt;
    color: #555;
    line-height: 1.5;
    page-break-inside: avoid;
  }
  .disclaimer-footer strong {
    color: #333;
    font-size: 7pt;
  }

  /* ── PRINT / PAGE ────────────────────────────────── */
  @page { margin: 0; size: A4 portrait; }
  @media print {
    body { padding: 8mm 14mm; }
    .no-print { display: none !important; }
  }
</style>
</head>
