/**
 * METARDU — GNSS Observation Log / Baseline Report
 *
 * Produces a formal GNSS observation log suitable for submission
 * to the Director of Surveys or project record-keeping.
 *
 * Includes:
 *   - Session header (project, equipment, date, operator)
 *   - Occupation schedule table (start/end, duration, satellites, PDOP)
 *   - Baseline vectors table (from/to, ΔE/ΔN/ΔU, distance, RMS)
 *   - Quality assessment summary
 *   - Surveyor's Certificate
 *
 * References:
 *   Survey Act Cap 299, s.22 (survey records)
 *   Survey Regulations 1994, Reg. 21 (instrument records)
 *   ISK — GNSS Best Practice Guidelines (2019)
 *   ISO 17123-8: GNSS field procedures
 */

import { buildPrintDocument, openPrint } from './buildPrintDocument'
import type { PrintMeta } from './buildPrintDocument'

// ── Types ─────────────────────────────────────────────────────────────────────

export interface GNSSObservationEntry {
  /** Point ID e.g. "BM_101" */
  pointId: string
  /** Session start time ISO string */
  startTime: string
  /** Session end time ISO string */
  endTime: string
  /** Duration in minutes */
  durationMin: number
  /** Number of satellites tracked */
  satellites: number
  /** Position Dilution of Precision */
  pdop: number
  /** Horizontal DOP */
  hdop: number
  /** Vertical DOP */
  vdop: number
  /** Fix type */
  fixType: 'FIX' | 'FLOAT' | 'DGNSS' | 'AUTONOMOUS' | 'RTK_FIX' | 'RTK_FLOAT'
  /** Antenna height in metres */
  antennaHeight: number
  /** Antenna measurement method */
  antennaMeasurement: 'SLANT' | 'VERTICAL' | 'ARP'
  /** Easting (projected) */
  easting?: number
  /** Northing (projected) */
  northing?: number
  /** Ellipsoidal height */
  ellHeight?: number
  /** Orthometric height */
  orthoHeight?: number
  /** RMS horizontal error (metres) */
  rmsH?: number
  /** RMS vertical error (metres) */
  rmsV?: number
  /** Notes */
  notes?: string
}

export interface GNSSBaselineEntry {
  /** From station */
  from: string
  /** To station */
  to: string
  /** Delta Easting (metres) */
  deltaE: number
  /** Delta Northing (metres) */
  deltaN: number
  /** Delta Elevation (metres) */
  deltaU: number
  /** Slope distance (metres) */
  distance: number
  /** Azimuth WCB (degrees) */
  azimuth: number
  /** Solution type */
  solution: 'FIX' | 'FLOAT' | 'DGNSS'
  /** Ratio (fix quality indicator) */
  ratio?: number
  /** RMS of baseline solution (metres) */
  rms: number
}

export interface GNSSLogInput {
  observations: GNSSObservationEntry[]
  baselines: GNSSBaselineEntry[]
  /** Equipment details */
  receiverModel: string
  receiverSerial: string
  antennaModel: string
  antennaSerial: string
  /** Reference station */
  baseStationId: string
  baseStationSource: 'OWN_BASE' | 'CORS' | 'VRS' | 'THIRD_PARTY'
  /** Coordinate system / datum */
  datum: string
  projection: string
  geoidModel: string
  /** Cutoff angle in degrees */
  elevationMask: number
  /** Epoch interval in seconds */
  epochInterval: number
  /** RINEX version if applicable */
  rinexVersion?: string
  /** Processing software */
  processingSoftware?: string
  /** Meta for header */
  meta: PrintMeta
}

// ── Formatting helpers ────────────────────────────────────────────────────────

function fmtTime(iso: string): string {
  try {
    const d = new Date(iso)
    return d.toLocaleTimeString('en-KE', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })
  } catch { return iso }
}

function fmtDate(iso: string): string {
  try {
    const d = new Date(iso)
    return d.toLocaleDateString('en-KE', { day: '2-digit', month: 'short', year: 'numeric' })
  } catch { return iso }
}

function fixClass(fix: string): string {
  if (fix === 'FIX' || fix === 'RTK_FIX') return 'pass'
  if (fix === 'FLOAT' || fix === 'RTK_FLOAT') return 'warn'
  return 'fail'
}

function dmsFromDec(deg: number): string {
  const d = Math.floor(deg)
  const minDec = (deg - d) * 60
  const m = Math.floor(minDec)
  const s = (minDec - m) * 60
  return `${String(d).padStart(3, '0')}°${String(m).padStart(2, '0')}'${s.toFixed(1).padStart(4, '0')}"`
}

// ── Body HTML builder ─────────────────────────────────────────────────────────

function esc(value: string | number | undefined | null): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function blank(value: string | number | undefined | null): string {
  const text = String(value ?? '').trim()
  return text ? esc(text) : '&mdash;'
}

function buildBody(inp: GNSSLogInput): string {
  const obs = inp.observations
  const bsl = inp.baselines

  // ── Equipment box ────────────────────────────────────────────
  const equipmentBox = `
<div class="summary-box" style="display:grid;grid-template-columns:1fr 1fr;gap:0;">
  <div class="summary-row"><span class="summary-label">Receiver</span><span class="summary-value">${blank(inp.receiverModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Receiver S/N</span><span class="summary-value">${blank(inp.receiverSerial)}</span></div>
  <div class="summary-row"><span class="summary-label">Antenna</span><span class="summary-value">${blank(inp.antennaModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Antenna S/N</span><span class="summary-value">${blank(inp.antennaSerial)}</span></div>
  <div class="summary-row"><span class="summary-label">Base Station</span><span class="summary-value">${blank(inp.baseStationId)} (${blank(inp.baseStationSource.replace(/_/g, ' '))})</span></div>
  <div class="summary-row"><span class="summary-label">Elevation Mask</span><span class="summary-value">${inp.elevationMask}°</span></div>
  <div class="summary-row"><span class="summary-label">Epoch Interval</span><span class="summary-value">${inp.epochInterval}s</span></div>
  <div class="summary-row"><span class="summary-label">Datum / Projection</span><span class="summary-value">${blank(inp.datum)} / ${blank(inp.projection)}</span></div>
  <div class="summary-row"><span class="summary-label">Geoid Model</span><span class="summary-value">${blank(inp.geoidModel)}</span></div>
  <div class="summary-row"><span class="summary-label">Processing Software</span><span class="summary-value">${blank(inp.processingSoftware || 'N/A')}</span></div>
</div>`

  // ── Observation schedule table ──────────────────────────────
  const obsRows = obs.map((o, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(o.pointId)}</td>
  <td class="mono">${fmtTime(o.startTime)}</td>
  <td class="mono">${fmtTime(o.endTime)}</td>
  <td class="right mono">${o.durationMin.toFixed(0)}</td>
  <td class="center">${o.satellites}</td>
  <td class="right mono">${o.pdop.toFixed(1)}</td>
  <td class="right mono">${o.hdop.toFixed(1)}</td>
  <td class="center"><span class="${fixClass(o.fixType)}">${o.fixType.replace(/_/g, ' ')}</span></td>
  <td class="right mono">${o.antennaHeight.toFixed(3)}</td>
  <td class="center" style="font-size:7.5pt">${o.antennaMeasurement}</td>
</tr>`).join('')

  const obsTable = `
<h2>1. Occupation Schedule</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:10%">Point</th>
      <th style="width:8%">Start</th>
      <th style="width:8%">End</th>
      <th class="right" style="width:6%">Min</th>
      <th style="width:5%">Sats</th>
      <th class="right" style="width:6%">PDOP</th>
      <th class="right" style="width:6%">HDOP</th>
      <th style="width:10%">Fix</th>
      <th class="right" style="width:8%">Ant H (m)</th>
      <th style="width:5%">Meas</th>
    </tr>
  </thead>
  <tbody>
    ${obsRows || '<tr><td colspan="11" class="center" style="color:#999;font-style:italic;">No observations entered</td></tr>'}
  </tbody>
</table>`

  // ── Coordinate results table ────────────────────────────────
  const coordRows = obs.filter(o => o.easting && o.northing).map((o, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(o.pointId)}</td>
  <td class="right mono">${o.easting!.toFixed(3)}</td>
  <td class="right mono">${o.northing!.toFixed(3)}</td>
  <td class="right mono">${o.ellHeight?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.orthoHeight?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.rmsH?.toFixed(3) ?? '—'}</td>
  <td class="right mono">${o.rmsV?.toFixed(3) ?? '—'}</td>
</tr>`).join('')

  const coordTable = coordRows ? `
<h2>2. Coordinate Results — ${blank(inp.datum)}</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:10%">Point</th>
      <th class="right" style="width:14%">Easting (m)</th>
      <th class="right" style="width:14%">Northing (m)</th>
      <th class="right" style="width:12%">Ell. Ht (m)</th>
      <th class="right" style="width:12%">Ortho Ht (m)</th>
      <th class="right" style="width:10%">RMS H (m)</th>
      <th class="right" style="width:10%">RMS V (m)</th>
    </tr>
  </thead>
  <tbody>${coordRows}</tbody>
</table>` : ''

  // ── Baseline vectors table ──────────────────────────────────
  const bslRows = bsl.map((b, i) => `
<tr>
  <td class="center">${i + 1}</td>
  <td class="bold mono">${blank(b.from)}</td>
  <td class="bold mono">${blank(b.to)}</td>
  <td class="right mono">${b.deltaE.toFixed(3)}</td>
  <td class="right mono">${b.deltaN.toFixed(3)}</td>
  <td class="right mono">${b.deltaU.toFixed(3)}</td>
  <td class="right mono">${b.distance.toFixed(3)}</td>
  <td class="mono">${dmsFromDec(b.azimuth)}</td>
  <td class="center"><span class="${b.solution === 'FIX' ? 'pass' : b.solution === 'FLOAT' ? 'warn' : 'fail'}">${b.solution}</span></td>
  <td class="right mono">${b.ratio?.toFixed(1) ?? '—'}</td>
  <td class="right mono">${b.rms.toFixed(4)}</td>
</tr>`).join('')

  const bslTable = bsl.length > 0 ? `
<h2>${coordRows ? '3' : '2'}. Baseline Vectors</h2>
<table>
  <thead>
    <tr>
      <th style="width:4%">No.</th>
      <th style="width:8%">From</th>
      <th style="width:8%">To</th>
      <th class="right" style="width:10%">ΔE (m)</th>
      <th class="right" style="width:10%">ΔN (m)</th>
      <th class="right" style="width:10%">ΔU (m)</th>
      <th class="right" style="width:10%">Dist (m)</th>
      <th style="width:12%">Azimuth</th>
      <th style="width:6%">Sol</th>
      <th class="right" style="width:6%">Ratio</th>
      <th class="right" style="width:8%">RMS (m)</th>
    </tr>
  </thead>
  <tbody>${bslRows}</tbody>
</table>` : ''

  // ── Quality assessment ──────────────────────────────────────
  const fixCount = obs.filter(o => o.fixType === 'FIX' || o.fixType === 'RTK_FIX').length
  const floatCount = obs.filter(o => o.fixType === 'FLOAT' || o.fixType === 'RTK_FLOAT').length
  const avgPdop = obs.length > 0 ? obs.reduce((a, o) => a + o.pdop, 0) / obs.length : 0
  const avgSats = obs.length > 0 ? obs.reduce((a, o) => a + o.satellites, 0) / obs.length : 0
  const maxRms = bsl.length > 0 ? Math.max(...bsl.map(b => b.rms)) : 0
  const avgRms = bsl.length > 0 ? bsl.reduce((a, b) => a + b.rms, 0) / bsl.length : 0
  const allFixed = fixCount === obs.length
  const minSats = obs.length > 0 ? Math.min(...obs.map(o => o.satellites)) : 0

  const qualitySection = `
<h2>${coordRows ? '4' : bsl.length > 0 ? '3' : '2'}. Quality Assessment</h2>
<div class="summary-box">
  <div class="summary-row"><span class="summary-label">Total observations</span><span class="summary-value">${obs.length}</span></div>
  <div class="summary-row"><span class="summary-label">Fixed solutions</span><span class="summary-value ${allFixed ? 'pass' : 'warn'}">${fixCount} / ${obs.length} (${obs.length > 0 ? ((fixCount / obs.length) * 100).toFixed(0) : 0}%)</span></div>
  <div class="summary-row"><span class="summary-label">Float solutions</span><span class="summary-value">${floatCount}</span></div>
  <div class="summary-row"><span class="summary-label">Avg PDOP</span><span class="summary-value ${avgPdop <= 3 ? 'pass' : avgPdop <= 6 ? 'warn' : 'fail'}">${avgPdop.toFixed(2)}</span></div>
  <div class="summary-row"><span class="summary-label">Avg satellites</span><span class="summary-value">${avgSats.toFixed(1)}</span></div>
  <div class="summary-row"><span class="summary-label">Min satellites</span><span class="summary-value ${minSats >= 5 ? 'pass' : 'fail'}">${minSats}</span></div>
  ${bsl.length > 0 ? `
  <div class="summary-row"><span class="summary-label">Total baselines</span><span class="summary-value">${bsl.length}</span></div>
  <div class="summary-row"><span class="summary-label">Avg baseline RMS</span><span class="summary-value ${avgRms <= 0.01 ? 'pass' : avgRms <= 0.05 ? 'warn' : 'fail'}">${avgRms.toFixed(4)} m</span></div>
  <div class="summary-row"><span class="summary-label">Max baseline RMS</span><span class="summary-value ${maxRms <= 0.02 ? 'pass' : maxRms <= 0.1 ? 'warn' : 'fail'}">${maxRms.toFixed(4)} m</span></div>
  ` : ''}
  <div class="summary-row"><span class="summary-label">Overall quality</span><span class="summary-value ${allFixed && avgPdop <= 3 ? 'pass' : 'warn'}">${allFixed && avgPdop <= 3 ? 'EXCELLENT' : fixCount > obs.length / 2 ? 'ACCEPTABLE' : 'REVIEW REQUIRED'}</span></div>
</div>`

  // ── Field notes ─────────────────────────────────────────────
  const obsWithNotes = obs.filter(o => o.notes)
  const notesSection = obsWithNotes.length > 0 ? `
<h2>Field Notes</h2>
<table>
  <thead>
    <tr>
      <th style="width:15%">Point</th>
      <th>Notes</th>
    </tr>
  </thead>
  <tbody>
    ${obsWithNotes.map(o => `<tr><td class="bold mono">${blank(o.pointId)}</td><td>${blank(o.notes)}</td></tr>`).join('')}
  </tbody>
</table>` : ''

  return `
${equipmentBox}
${obsTable}
${coordTable}
${bslTable}
${qualitySection}
${notesSection}
`
}

// ── Public API ────────────────────────────────────────────────────────────────

export function generateGNSSObservationLog(inp: GNSSLogInput): string {
  const meta: PrintMeta = {
    ...inp.meta,
    title: inp.meta.title || 'GNSS Observation Log',
    reference: 'Survey Act Cap 299 | Survey Regulations 1994, Reg. 21 | ISK GNSS Guidelines 2019 | ISO 17123-8',
  }
  return buildPrintDocument(buildBody(inp), meta)
}

export function printGNSSObservationLog(inp: GNSSLogInput): void {
  openPrint(generateGNSSObservationLog(inp))
}

/**
 * Quality Scoring — Per-Surveyor Metrics
 * ======================================
 *
 * Aggregates audit chain data + project outcomes into per-surveyor
 * quality metrics. Turns Metardu from a tool into a practice
 * management system: surveyors can see their closure rates,
 * ArdhiSasa rejection rates, and average precision — useful for
 * ISK/EBK compliance audits.
 *
 * What it computes
 * ----------------
 * - Total surveys completed (by survey type)
 * - Statutory gate pass rate (% of submissions that passed the gate
 *   without block violations)
 * - Average precision ratio achieved (e.g. 1:8234 across all traverses)
 * - ArdhiSasa rejection proxy (gate block count = would-have-been
 *   rejections)
 * - Activity over time (surveys per month, trend)
 *
 * Data sources
 * ------------
 * - audit_chain table — every document generation, gate run, and
 *   submission is logged with user + timestamp + payload
 * - projects table — survey type, status, dates
 * - statutory gate results — embedded in audit payload metadata
 *
 * The metrics are computed on-demand (not pre-aggregated) from the
 * audit chain. This keeps the source of truth append-only and lets
 * us recompute metrics retroactively when rules change.
 *
 * Usage
 * -----
 *   import { computeSurveyorMetrics } from '@/lib/quality/scoring'
 *
 *   const metrics = await computeSurveyorMetrics({
 *     userId: 'user-123',
 *     dateFrom: '2026-01-01',
 *     dateTo: '2026-07-01',
 *   })
 *
 *   console.log(`Pass rate: ${metrics.gatePassRate.toFixed(1)}%`)
 */

import { db } from '@/lib/db'
// ─── Types ──────────────────────────────────────────────────────────────

export interface SurveyorMetricsQuery {
  userId: string
  /** ISO date. If omitted, no lower bound. */
  dateFrom?: string
  /** ISO date. If omitted, no upper bound (now). */
  dateTo?: string
}

export interface SurveyorMetrics {
  userId: string
  dateRange: { from: string | null; to: string | null }

  /** Total surveys (projects) the surveyor has worked on in the range. */
  totalSurveys: number

  /** Breakdown by survey type. */
  surveysByType: Record<string, number>

  /** Total audit chain entries by the surveyor. */
  totalAuditEntries: number

  /** Audit entries broken down by action. */
  auditEntriesByAction: Record<string, number>

  /**
   * Statutory gate pass rate (0-100).
   * Computed from audit entries with action='validate' or 'generate'
   * where payload.metadata.gatePassed is true.
   * Returns null if no gate runs were logged.
   */
  gatePassRate: number | null

  /** Total gate runs (validate or generate actions with gate metadata). */
  totalGateRuns: number

  /** Gate runs that passed (no block violations). */
  gatePasses: number

  /** Gate runs that failed (≥1 block violation). */
  gateFailures: number

  /**
   * Average precision ratio across all traverses (e.g. 8234 means 1:8234).
   * Computed from audit entries where payload carries traverse metadata.
   * Returns null if no traverse data.
   */
  averagePrecisionRatio: number | null

  /**
   * ArdhiSasa rejection proxy — the count of gate failures that would
   * have resulted in ArdhiSasa rejections if submitted. Lower is better.
   */
  estimatedRejectionsAvoided: number

  /** First activity timestamp. */
  firstActivityAt: string | null

  /** Last activity timestamp. */
  lastActivityAt: string | null

  /** Surveyor's name (denormalized from the most recent audit entry). */
  surveyorName: string | null

  /** Time the metrics computation took, in milliseconds. */
  elapsedMs: number
}

// ─── Public API ─────────────────────────────────────────────────────────

/**
 * Compute quality metrics for a surveyor from the audit chain.
 *
 * This is a read-only aggregation — no writes, no side effects.
 * The computation scans the audit_chain table filtered by user_id
 * and date range, then aggregates the results in-memory.
 *
 * For large audit chains (>10k entries) this could be optimized with
 * materialized views or pre-aggregation. For now, on-demand is fine.
 */
export async function computeSurveyorMetrics(
  query: SurveyorMetricsQuery
): Promise<SurveyorMetrics> {
  const startTime = Date.now()
  const { userId, dateFrom, dateTo } = query

  // Build the date filter
  const dateConditions: string[] = []
  const params: unknown[] = [userId]
  let paramIdx = 2
  if (dateFrom) {
    dateConditions.push(`created_at >= $${paramIdx++}`)
    params.push(dateFrom)
  }
  if (dateTo) {
    dateConditions.push(`created_at <= $${paramIdx++}`)
    params.push(dateTo)
  }
  const dateClause = dateConditions.length > 0
    ? 'AND ' + dateConditions.join(' AND ')
    : ''

  // Fetch all audit entries for this user in the date range
  const auditResult = await db.query(
    `SELECT * FROM audit_chain WHERE user_id = $1 ${dateClause} ORDER BY created_at ASC`,
    params
  )
  const auditEntries = auditResult.rows

  // Fetch projects this user worked on
  const projectsResult = await db.query(
    `SELECT survey_type, created_at FROM projects WHERE user_id = $1 ${dateClause}`,
    params
  )
  const projects = projectsResult.rows

  // Aggregate
  const surveysByType: Record<string, number> = {}
  for (const p of projects) {
    const st = String(p.survey_type ?? 'unknown')
    surveysByType[st] = (surveysByType[st] ?? 0) + 1
  }

  const auditEntriesByAction: Record<string, number> = {}
  let gatePasses = 0
  let gateFailures = 0
  let totalGateRuns = 0
  let precisionSum = 0
  let precisionCount = 0
  let surveyorName: string | null = null

  for (const entry of auditEntries) {
    const action = String(entry.action)
    auditEntriesByAction[action] = (auditEntriesByAction[action] ?? 0) + 1

    if (entry.user_name && !surveyorName) {
      surveyorName = String(entry.user_name)
    }

    // Parse payload (JSONB comes back as object in pg, but be defensive)
    let payload: any = entry.payload
    if (typeof payload === 'string') {
      try { payload = JSON.parse(payload) } catch { payload = {} }
    }

    // Gate pass/fail tracking
    const metadata = payload?.metadata
    if (metadata && typeof metadata.gatePassed === 'boolean') {
      totalGateRuns++
      if (metadata.gatePassed) {
        gatePasses++
      } else {
        gateFailures++
      }
    }

    // Precision ratio tracking (from traverse adjustments)
    if (action === 'adjust' && payload?.new?.precisionRatio) {
      const ratio = Number(payload.new.precisionRatio)
      if (!Number.isNaN(ratio) && ratio > 0) {
        precisionSum += ratio
        precisionCount++
      }
    }
  }

  const gatePassRate = totalGateRuns > 0
    ? (gatePasses / totalGateRuns) * 100
    : null

  const averagePrecisionRatio = precisionCount > 0
    ? precisionSum / precisionCount
    : null

  const firstEntry = auditEntries[0]
  const lastEntry = auditEntries[auditEntries.length - 1]
  const toIso = (v: any): string | null => {
    if (!v) return null
    if (v instanceof Date) return v.toISOString()
    return String(v)
  }

  return {
    userId,
    dateRange: { from: dateFrom ?? null, to: dateTo ?? null },
    totalSurveys: projects.length,
    surveysByType,
    totalAuditEntries: auditEntries.length,
    auditEntriesByAction,
    gatePassRate,
    totalGateRuns,
    gatePasses,
    gateFailures,
    averagePrecisionRatio,
    estimatedRejectionsAvoided: gateFailures,
    firstActivityAt: toIso(firstEntry?.created_at),
    lastActivityAt: toIso(lastEntry?.created_at),
    surveyorName,
    elapsedMs: Date.now() - startTime,
  }
}

/**
 * Format surveyor metrics as a human-readable summary.
 * Useful for display in a dashboard or a compliance audit report.
 */
export function formatSurveyorMetrics(metrics: SurveyorMetrics): string {
  const lines: string[] = [
    `Surveyor: ${metrics.surveyorName ?? metrics.userId}`,
    `Date range: ${metrics.dateRange.from ?? 'beginning'} to ${metrics.dateRange.to ?? 'now'}`,
    `Computed in ${metrics.elapsedMs}ms`,
    '',
    `Total surveys: ${metrics.totalSurveys}`,
    `Survey breakdown: ${Object.entries(metrics.surveysByType).map(([t, n]) => `${t}=${n}`).join(', ') || 'none'}`,
    '',
    `Audit entries: ${metrics.totalAuditEntries}`,
    `Action breakdown: ${Object.entries(metrics.auditEntriesByAction).map(([a, n]) => `${a}=${n}`).join(', ') || 'none'}`,
    '',
    `Statutory gate pass rate: ${metrics.gatePassRate !== null ? metrics.gatePassRate.toFixed(1) + '%' : 'no data'}`,
    `  Total gate runs: ${metrics.totalGateRuns}`,
    `  Passes: ${metrics.gatePasses}`,
    `  Failures: ${metrics.gateFailures}`,
    `  Estimated rejections avoided: ${metrics.estimatedRejectionsAvoided}`,
    '',
    `Average precision ratio: ${metrics.averagePrecisionRatio !== null ? '1:' + Math.round(metrics.averagePrecisionRatio) : 'no data'}`,
    '',
    `First activity: ${metrics.firstActivityAt ?? 'none'}`,
    `Last activity: ${metrics.lastActivityAt ?? 'none'}`,
  ]
  return lines.join('\n')
}

/**
 * Compute a simple quality score (0-100) from the metrics.
 *
 * Weighting:
 *   - 50% gate pass rate (higher is better)
 *   - 30% precision ratio (1:10000+ = 100, 1:5000 = 50, 1:1000 = 10)
 *   - 20% activity volume (log-scaled)
 *
 * Returns null if insufficient data (no gate runs AND no precision data).
 */
export function computeQualityScore(metrics: SurveyorMetrics): number | null {
  let gateScore: number | null = null
  if (metrics.gatePassRate !== null) {
    gateScore = metrics.gatePassRate
  }

  let precisionScore: number | null = null
  if (metrics.averagePrecisionRatio !== null) {
    precisionScore = Math.min(100, (metrics.averagePrecisionRatio / 10000) * 100)
  }

  let activityScore: number | null = null
  if (metrics.totalSurveys > 0) {
    activityScore = Math.min(100, 25 + 25 * Math.log10(metrics.totalSurveys + 1))
  }

  if (gateScore === null && precisionScore === null) return null

  let total = 0
  let weight = 0
  if (gateScore !== null) { total += gateScore * 0.5; weight += 0.5 }
  if (precisionScore !== null) { total += precisionScore * 0.3; weight += 0.3 }
  if (activityScore !== null) { total += activityScore * 0.2; weight += 0.2 }

  return weight > 0 ? Math.round(total / weight) : null
}

/**
 * @module collaborationServer
 *
 * Real-time collaboration server using WebSocket.
 *
 * Features:
 * - Live presence (who's online in a project)
 * - Cursor sharing (see other users' mouse position on the map)
 * - Live feature editing (see when others draw/edit features)
 * - Conflict resolution via last-write-wins (LWW) with timestamp comparison.
 *   AUDIT FIX (M17, 2026-07-02): Previous docstring claimed "operational
 *   transforms" — that was inaccurate. The actual implementation is LWW:
 *   incoming edits with an older timestamp than the server's copy are
 *   rejected with a `conflict_rejected` message. Three-way merge is
 *   available in the offline sync queue (src/lib/offline/syncQueue.ts)
 *   but is NOT used by the realtime collaboration server.
 *
 * This module sets up a WebSocket server that can be integrated
 * with Next.js custom server or run as a separate process.
 *
 * For Docker deployment, this runs alongside the Next.js app
 * on a separate port (3001) or as a serverless WebSocket.
 */

import { WebSocketServer, WebSocket } from 'ws'
import { createServer, IncomingMessage } from 'http'
import { parse } from 'url'
import { createVerify } from 'crypto'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface Collaborator {
  id: string
  userId: string
  userName: string
  projectId: string
  cursor?: { lat: number; lng: number }
  color: string
  lastSeen: number
  ws: WebSocket
}

interface CollaborationMessage {
  type: 'join' | 'leave' | 'cursor' | 'feature_edit' | 'feature_delete' | 'chat' | 'presence'
  userId?: string
  userName?: string
  projectId?: string
  cursor?: { lat: number; lng: number }
  feature?: {
    id: string
    type: 'Point' | 'LineString' | 'Polygon'
    geometry: unknown
    properties?: Record<string, unknown>
  }
  featureId?: string
  message?: string
  timestamp: number
}

// ---------------------------------------------------------------------------
// JWT Authentication
// ---------------------------------------------------------------------------

/**
 * Verify a JWT token (NextAuth-compatible).
 *
 * NextAuth uses HS256 by default with AUTH_SECRET as the key.
 * This verifies the token signature without importing NextAuth
 * (keeps the WebSocket server lightweight).
 */
function verifyToken(token: string, secret: string): { userId?: string; email?: string; name?: string } | null {
  try {
    const parts = token.split('.')
    if (parts.length !== 3) return null

    const [headerB64, payloadB64, signatureB64] = parts
    const signedContent = `${headerB64}.${payloadB64}`

    // Verify signature
    const verify = createVerify('RSA-SHA256')
    verify.update(signedContent)
    verify.end()

    // NextAuth uses HS256 (HMAC), not RSA
    // For HMAC verification, we need crypto.createHmac
    const crypto = require('crypto')
    const expectedSig = crypto.createHmac('sha256', secret)
      .update(signedContent)
      .digest('base64url')

    if (expectedSig !== signatureB64) {
      return null
    }

    // Decode payload
    const payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString())
    return {
      userId: payload.sub || payload.userId,
      email: payload.email,
      name: payload.name || payload.fullName,
    }
  } catch {
    return null
  }
}

/**
 * Authenticate a WebSocket connection request.
 * Returns the user info if valid, null otherwise.
 */
function authenticateRequest(req: IncomingMessage): { userId: string; userName: string } | null {
  const url = parse(req.url || '', true)
  const token = url.query.token as string
  const userId = url.query.userId as string
  const userName = url.query.userName as string

  // If AUTH_SECRET is set, require valid token
  const secret = process.env.AUTH_SECRET || process.env.NEXTAUTH_SECRET
  if (secret) {
    if (!token) return null
    const decoded = verifyToken(token, secret)
    if (!decoded || !decoded.userId) return null
    return {
      userId: decoded.userId,
      userName: decoded.name || userName || `User ${decoded.userId.substring(0, 6)}`,
    }
  }

  // Fallback: no secret set, allow unauthenticated (development only)
  if (!userId) return null
  return { userId, userName: userName || `User ${userId.substring(0, 6)}` }
}

// ---------------------------------------------------------------------------
// Conflict Resolution (Last-Write-Wins with timestamps)
// ---------------------------------------------------------------------------

interface FeatureVersion {
  featureId: string
  version: number
  timestamp: number
  userId: string
  data: unknown
}

class ConflictResolver {
  private versions: Map<string, FeatureVersion> = new Map()

  /**
   * Attempt to apply an update. Returns true if accepted, false if rejected
   * (stale version).
   */
  applyUpdate(featureId: string, data: unknown, timestamp: number, userId: string): boolean {
    const existing = this.versions.get(featureId)

    if (existing && timestamp < existing.timestamp) {
      // Stale update — reject
      return false
    }

    this.versions.set(featureId, {
      featureId,
      version: (existing?.version || 0) + 1,
      timestamp,
      data,
      userId,
    })

    return true
  }

  delete(featureId: string): void {
    this.versions.delete(featureId)
  }

  getVersion(featureId: string): FeatureVersion | undefined {
    return this.versions.get(featureId)
  }
}

// ---------------------------------------------------------------------------
// Collaboration Server
// ---------------------------------------------------------------------------

export class CollaborationServer {
  private wss: WebSocketServer | null = null
  private collaborators: Map<string, Collaborator> = new Map()
  private projectRooms: Map<string, Set<string>> = new Map() // projectId -> set of collaborator IDs
  private conflictResolvers: Map<string, ConflictResolver> = new Map() // projectId -> resolver

  // User colors for cursor display
  private readonly COLORS = [
    '#D17B47', '#3B82F6', '#10B981', '#8B5CF6',
    '#F59E0B', '#EF4444', '#06B6D4', '#EC4899',
  ]

  start(port: number = 3001) {
    const server = createServer((req, res) => {
      // Tiny HTTP listener for health checks. The collaboration server's
      // real traffic is WebSocket on /ws/collaboration; this endpoint only
      // exists so orchestrators (docker-compose healthcheck, k8s liveness)
      // can confirm the process is alive.
      if ((req.url || '').split('?')[0] === '/health') {
        res.writeHead(200, { 'content-type': 'application/json' })
        res.end(JSON.stringify({
          status: 'healthy',
          collaborators: this.collaborators.size,
          projects: this.projectRooms.size,
          uptime: process.uptime(),
        }))
        return
      }
      res.writeHead(404, { 'content-type': 'text/plain' })
      res.end('Not Found')
    })
    this.wss = new WebSocketServer({ server, path: '/ws/collaboration' })

    this.wss.on('connection', (ws: WebSocket, req: IncomingMessage) => {
      // Authenticate the connection
      const auth = authenticateRequest(req)
      if (!auth) {
        ws.close(1008, 'Authentication failed')
        return
      }

      const url = parse(req.url || '', true)
      const projectId = url.query.projectId as string

      if (!projectId) {
        ws.close(1008, 'Missing projectId')
        return
      }

      const { userId, userName } = auth
      const collaboratorId = `${userId}-${Date.now()}`
      const color = this.COLORS[this.collaborators.size % this.COLORS.length]

      const collaborator: Collaborator = {
        id: collaboratorId,
        userId,
        userName: userName || `User ${userId.substring(0, 6)}`,
        projectId,
        color,
        lastSeen: Date.now(),
        ws,
      }

      this.collaborators.set(collaboratorId, collaborator)

      // Add to project room
      if (!this.projectRooms.has(projectId)) {
        this.projectRooms.set(projectId, new Set())
      }
      this.projectRooms.get(projectId)!.add(collaboratorId)

      // Notify room of new collaborator
      this.broadcastToProject(projectId, {
        type: 'join',
        userId,
        userName: collaborator.userName,
        projectId,
        timestamp: Date.now(),
      }, collaboratorId)

      // Send current presence to new collaborator
      this.sendPresence(ws, projectId)

      ws.on('message', (data: Buffer) => {
        try {
          const msg: CollaborationMessage = JSON.parse(data.toString())
          collaborator.lastSeen = Date.now()

          switch (msg.type) {
            case 'cursor':
              collaborator.cursor = msg.cursor
              this.broadcastToProject(projectId, {
                type: 'cursor',
                userId,
                userName: collaborator.userName,
                cursor: msg.cursor,
                timestamp: Date.now(),
              }, collaboratorId)
              break

            case 'feature_edit': {
              // Conflict resolution: last-write-wins with timestamps
              const resolver = this.getResolver(projectId)
              const featureId = msg.feature?.id
              if (!featureId) break

              const accepted = resolver.applyUpdate(
                featureId,
                msg.feature,
                msg.timestamp,
                userId,
              )

              if (accepted) {
                this.broadcastToProject(projectId, {
                  type: 'feature_edit',
                  userId,
                  userName: collaborator.userName,
                  feature: msg.feature,
                  timestamp: msg.timestamp,
                }, collaboratorId)
              } else {
                // Reject stale update — notify sender
                ws.send(JSON.stringify({
                  type: 'conflict_rejected',
                  featureId,
                  message: 'Update rejected — newer version exists',
                  timestamp: Date.now(),
                }))
              }
              break
            }

            case 'feature_delete': {
              const resolver = this.getResolver(projectId)
              if (msg.featureId) {
                resolver.delete(msg.featureId)
              }
              this.broadcastToProject(projectId, {
                type: 'feature_delete',
                userId,
                userName: collaborator.userName,
                featureId: msg.featureId,
                timestamp: Date.now(),
              }, collaboratorId)
              break
            }

            case 'chat':
              this.broadcastToProject(projectId, {
                type: 'chat',
                userId,
                userName: collaborator.userName,
                message: msg.message,
                timestamp: Date.now(),
              }, collaboratorId)
              break
          }
        } catch (err) {
          console.error('[CollaborationServer] Message parse error:', err)
        }
      })

      ws.on('close', () => {
        this.collaborators.delete(collaboratorId)
        this.projectRooms.get(projectId)?.delete(collaboratorId)

        this.broadcastToProject(projectId, {
          type: 'leave',
          userId,
          userName: collaborator.userName,
          timestamp: Date.now(),
        })
      })

      ws.on('error', (err) => {
        console.error('[CollaborationServer] WebSocket error:', err)
      })
    })

    // Heartbeat — remove stale connections
    setInterval(() => {
      const now = Date.now()
      for (const [id, collab] of this.collaborators) {
        if (now - collab.lastSeen > 60000) { // 60s timeout
          collab.ws.terminate()
          this.collaborators.delete(id)
          this.projectRooms.get(collab.projectId)?.delete(id)
        }
      }
    }, 30000)

    server.listen(port, () => {
    })
  }

  private broadcastToProject(projectId: string, msg: CollaborationMessage, excludeId?: string) {
    const room = this.projectRooms.get(projectId)
    if (!room) return

    const data = JSON.stringify(msg)
    for (const collabId of room) {
      if (collabId === excludeId) continue
      const collab = this.collaborators.get(collabId)
      if (collab && collab.ws.readyState === WebSocket.OPEN) {
        collab.ws.send(data)
      }
    }
  }

  private getResolver(projectId: string): ConflictResolver {
    if (!this.conflictResolvers.has(projectId)) {
      this.conflictResolvers.set(projectId, new ConflictResolver())
    }
    return this.conflictResolvers.get(projectId)!
  }

  private sendPresence(ws: WebSocket, projectId: string) {
    const room = this.projectRooms.get(projectId)
    if (!room) return

    const presence = Array.from(room)
      .map(id => this.collaborators.get(id))
      .filter((c): c is Collaborator => c !== undefined)
      .map(c => ({
        userId: c.userId,
        userName: c.userName,
        color: c.color,
        cursor: c.cursor,
      }))

    ws.send(JSON.stringify({
      type: 'presence',
      timestamp: Date.now(),
      payload: presence,
    }))
  }

  stop() {
    this.wss?.close()
    this.collaborators.clear()
    this.projectRooms.clear()
    this.conflictResolvers.clear()
  }
}

// ---------------------------------------------------------------------------
// Singleton instance
// ---------------------------------------------------------------------------

let serverInstance: CollaborationServer | null = null

export function getCollaborationServer(): CollaborationServer {
  if (!serverInstance) {
    serverInstance = new CollaborationServer()
  }
  return serverInstance
}

/**
 * METARDU Enterprise Yjs Offline Mesh Network
 * ===========================================
 * Replaces HTTP polling with true Peer-to-Peer CRDTs using WebRTC.
 * Allows surveyors to sync GNSS points locally over Wi-Fi without internet.
 */

import * as Y from 'yjs'
import { WebrtcProvider } from 'y-webrtc'
import { IndexeddbPersistence } from 'y-indexeddb'

export interface PresenceUser {
  userId: string
  userName: string
  color: string
  cursor?: { lat: number; lng: number }
  onlineAt?: string
}

class YjsMeshNetwork {
  private docs: Map<string, Y.Doc> = new Map()
  private providers: Map<string, WebrtcProvider> = new Map()
  private persistences: Map<string, IndexeddbPersistence> = new Map()

  public getDoc(projectId: string): Y.Doc {
    if (this.docs.has(projectId)) return this.docs.get(projectId)!

    const doc = new Y.Doc()
    this.docs.set(projectId, doc)

    // Offline persistence
    const persistence = new IndexeddbPersistence(`metardu-sync-${projectId}`, doc)
    this.persistences.set(projectId, persistence)

    // WebRTC Provider for P2P Local LAN sync (using public/local signaling)
    const provider = new WebrtcProvider(`metardu-mesh-${projectId}`, doc, {
      signaling: ['wss://signaling.yjs.dev', 'ws://localhost:4444'], // Add local fallback if deployed offline
      password: 'metardu-secure-field'
    })
    this.providers.set(projectId, provider)

    return doc
  }

  public getProvider(projectId: string): WebrtcProvider | undefined {
    return this.providers.get(projectId)
  }

  public async unsubscribe(projectId: string): Promise<void> {
    const provider = this.providers.get(projectId)
    if (provider) {
      provider.disconnect()
      provider.destroy()
      this.providers.delete(projectId)
    }

    const persistence = this.persistences.get(projectId)
    if (persistence) {
      persistence.destroy()
      this.persistences.delete(projectId)
    }

    const doc = this.docs.get(projectId)
    if (doc) {
      doc.destroy()
      this.docs.delete(projectId)
    }
  }

  public async unsubscribeAll(): Promise<void> {
    for (const projectId of Array.from(this.docs.keys())) {
      await this.unsubscribe(projectId)
    }
  }
}

export const realtimeService = new YjsMeshNetwork()

export function subscribeToProjectChanges(
  projectId: string,
  user: { id: string; email?: string; name?: string },
  callbacks: {
    onPointsChange?: (payload: any) => void
    onTraverseChange?: (payload: any) => void
    onLevelingChange?: (payload: any) => void
    onPresenceChange?: (users: PresenceUser[]) => void
  }
): { unsubscribe: () => Promise<void> } {
  // This is a compatibility layer for the old HTTP polling interface.
  // In the new architecture, Zustand automatically syncs with Yjs via the sync layer.
  // We just handle presence here.

  const provider = realtimeService.getProvider(projectId)
  if (!provider) {
    // Force init
    realtimeService.getDoc(projectId)
  }
  
  const activeProvider = realtimeService.getProvider(projectId)
  if (activeProvider && callbacks.onPresenceChange) {
    const awareness = activeProvider.awareness

    // Set local presence
    awareness.setLocalStateField('user', {
      userId: user.id,
      userName: user.name || user.email || 'Unknown Surveyor',
      color: '#' + Math.floor(Math.random()*16777215).toString(16),
      onlineAt: new Date().toISOString()
    })

    const handleAwarenessChange = () => {
      const states = Array.from(awareness.getStates().values())
      const users = states
        .filter(state => state.user && state.user.userId !== user.id)
        .map(state => state.user as PresenceUser)
      callbacks.onPresenceChange!(users)
    }

    awareness.on('change', handleAwarenessChange)
    
    // Initial emit
    handleAwarenessChange()

    return {
      unsubscribe: async () => {
        awareness.off('change', handleAwarenessChange)
      }
    }
  }

  return {
    unsubscribe: async () => {}
  }
}

'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import { subscribeToProjectChanges, PresenceUser, realtimeService } from './index'
import { initProjectSync } from './zustand-yjs-sync'

export interface Collaborator {
  userId: string
  userName: string
  color: string
  cursor?: { lat: number; lng: number }
}

interface UseCollaborationProps {
  projectId: string | null
  userId?: string
  userName?: string
}

interface UseCollaborationReturn {
  collaborators: Collaborator[]
  isConnected: boolean
  conflictWarnings: string[]
  sendCursor: (lat: number, lng: number) => void
  sendFeatureEdit: (feature: any) => void
  sendFeatureDelete: (featureId: string) => void
  sendChat: (message: string) => void
  onFeatureEdit?: (feature: any, userId: string) => void
  onFeatureDelete?: (featureId: string, userId: string) => void
  onChat?: (message: string, userName: string, userId: string) => void
}

export function useCollaboration({
  projectId,
  userId,
  userName,
}: UseCollaborationProps): UseCollaborationReturn {
  const [collaborators, setCollaborators] = useState<Collaborator[]>([])
  const [isConnected, setIsConnected] = useState(false)
  const [conflictWarnings] = useState<string[]>([])
  
  const callbacksRef = useRef<{
    onFeatureEdit?: (feature: any, userId: string) => void
    onFeatureDelete?: (featureId: string, userId: string) => void
    onChat?: (message: string, userName: string, userId: string) => void
  }>({})

  useEffect(() => {
    if (!projectId || !userId) return

    // 1. Initialize Zustand-Yjs Data Sync
    initProjectSync(projectId)

    // 2. Initialize Presence via Yjs Awareness
    const subscription = subscribeToProjectChanges(
      projectId,
      { id: userId, name: userName },
      {
        onPresenceChange: (users: PresenceUser[]) => {
          setCollaborators(users.map(u => ({
            userId: u.userId,
            userName: u.userName,
            color: u.color,
            cursor: u.cursor
          })))
        }
      }
    )

    // Monitor WebRTC connection state
    const provider = realtimeService.getProvider(projectId)
    if (provider) {
      provider.on('status', ({ connected }: { connected: boolean }) => {
        setIsConnected(connected)
      })
      // If already connected before listener was attached
      setIsConnected(provider.connected)
    }

    return () => {
      subscription.unsubscribe()
    }
  }, [projectId, userId, userName])

  // Real-time Chat via Yjs Array
  const sendChat = useCallback((message: string) => {
    if (!projectId || !userId) return
    const doc = realtimeService.getDoc(projectId)
    const yChat = doc.getArray('chat')
    yChat.push([{
      userId,
      userName: userName || 'Unknown',
      message,
      timestamp: Date.now()
    }])
  }, [projectId, userId, userName])

  // Setup Chat Observer
  useEffect(() => {
    if (!projectId) return
    const doc = realtimeService.getDoc(projectId)
    const yChat = doc.getArray('chat')
    
    const observer = (event: any) => {
      event.changes.added.forEach((item: any) => {
        item.content.getContent().forEach((msg: any) => {
          if (msg.userId !== userId) {
            callbacksRef.current.onChat?.(msg.message, msg.userName, msg.userId)
          }
        })
      })
    }
    
    yChat.observe(observer)
    return () => yChat.unobserve(observer)
  }, [projectId, userId])

  // Mouse Cursor Sharing via Yjs Awareness
  const sendCursor = useCallback((lat: number, lng: number) => {
    if (!projectId || !userId) return
    const provider = realtimeService.getProvider(projectId)
    if (provider) {
      const awareness = provider.awareness
      const localState = awareness.getLocalState()
      awareness.setLocalState({
        ...localState,
        user: { ...localState?.user, cursor: { lat, lng } }
      })
    }
  }, [projectId, userId])

  // Feature Edits are now handled automatically by the Zustand-Yjs sync layer.
  // These are kept as no-ops to satisfy the component prop types.
  const sendFeatureEdit = useCallback(() => {}, [])
  const sendFeatureDelete = useCallback(() => {}, [])

  return {
    collaborators,
    isConnected,
    conflictWarnings,
    sendCursor,
    sendFeatureEdit,
    sendFeatureDelete,
    sendChat,
    ...callbacksRef.current,
  }
}

import { useProjectStore, ProjectData } from '@/stores/projectStore'
import { realtimeService } from './index'
import * as Y from 'yjs'

// Track active syncs to avoid duplicate listeners
const activeSyncs = new Set<string>()

export function initProjectSync(projectId: string) {
  if (activeSyncs.has(projectId)) return
  activeSyncs.add(projectId)

  const doc = realtimeService.getDoc(projectId)
  const yProject = doc.getMap<any>('project')

  // 1. Initial Load: If Yjs has data, push it to Zustand
  if (Array.from(yProject.keys()).length > 0) {
    const projectData = yProject.toJSON() as ProjectData
    useProjectStore.getState().loadProject(projectData)
  } else {
    // If Yjs is empty, initialize it from Zustand
    const state = useProjectStore.getState()
    const project = state.projects[projectId]
    if (project) {
      doc.transact(() => {
        Object.entries(project).forEach(([key, value]) => {
          yProject.set(key, value)
        })
      })
    }
  }

  // 2. Yjs -> Zustand (Observe changes from other tablets)
  yProject.observe((event) => {
    // Prevent echo loops by checking if we caused this change
    if (event.transaction.local) return

    const updatedData = yProject.toJSON() as ProjectData
    useProjectStore.getState().loadProject(updatedData)
  })

  // 3. Zustand -> Yjs (Observe local changes and push to mesh)
  useProjectStore.subscribe(
    (state) => state.projects[projectId],
    (project, prevProject) => {
      if (!project) return
      
      // We only want to push to Yjs if this change came from the local user
      // A simple way to check is to diff the objects.
      // But since Yjs handles merges cleanly, we can just dump it in.
      
      doc.transact(() => {
        // We do a naive replace of the top-level keys
        // For a production app, we would observe nested properties (ControlPoints Map, etc.)
        // But Y.Map set() overwrites cleanly.
        Object.entries(project).forEach(([key, value]) => {
          const currentY = yProject.get(key)
          // Naive deep equality check to avoid unnecessary writes
          if (JSON.stringify(currentY) !== JSON.stringify(value)) {
            yProject.set(key, value)
          }
        })
      })
    },
    { equalityFn: (a, b) => JSON.stringify(a) === JSON.stringify(b) }
  )
}

import { computeTraverseAccuracy, getAccuracyBadgeLabel } from '../traverseAccuracy'

describe('computeTraverseAccuracy', () => {
