    const r = computeTraverseAccuracy(0.001, 4000)
    expect(r).not.toBeNull()
    expect(r!.order).toBe('FIRST ORDER CLASS I')
    expect(r!.m_mm).toBe(0.5)
    expect(r!.C_mm).toBe(1.0)
    expect(r!.K_km).toBe(4.0)
    expect(r!.allowed).toBeCloseTo(0.5, 1)
  })
  it('returns null for zero perimeter', () => {
    const r = computeTraverseAccuracy(0.001, 0)
    expect(r).toBeNull()
  })
  it('classifies 2mm error on 1km perimeter as Third Order', () => {
    const r = computeTraverseAccuracy(0.002, 1000)
    expect(r).not.toBeNull()
    expect(r!.order).toBe('THIRD ORDER')
  })
})

export interface ConvertedCoordinate {
  id?: string
  easting: number
  northing: number
  datum: string
  epsg: number
}

export interface ConversionResult {
  success: boolean
  coordinates: ConvertedCoordinate[]
  error?: string
}

export async function convertToArc1960(
  coordinates: Array<{ id?: string; easting: number; northing: number }>
): Promise<ConversionResult> {
  try {
    const response = await fetch('/api/convert-datum', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        coords: coordinates,
        fromDatum: 'WGS84',
        toDatum: 'ARC1960'
      })
    })
    const data = await response.json()
    if (response.ok && data.data) {
      const coords = data.data.map((c: any) => ({
        id: c.id,
        easting: c.easting,
        northing: c.northing,
        datum: c.datum || 'ARC1960',
        epsg: 21037
      }))
      return { success: true, coordinates: coords }
    }
    return { success: false, coordinates: [], error: data.error || 'Conversion failed' }
  } catch (err) {
    return { success: false, coordinates: [], error: 'Network error' }
  }
}

