/**
 * Circuit Breaker — protects outbound calls from cascading failures
 *
 * After N consecutive failures, the circuit "opens" — subsequent calls
 * fail immediately without hitting the network. After a cooldown period,
 * the circuit "half-opens" — one trial request is allowed.
 *
 * States: CLOSED → OPEN → HALF_OPEN → CLOSED (or back to OPEN)
 *
 * References: ByteByteGo system-design-101 Resiliency Patterns, Shopify Semian
 */

import { log } from '@/lib/logger'

export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN'

export interface CircuitBreakerOptions {
  name: string
  failureThreshold?: number  // default: 5
  cooldownMs?: number        // default: 30000
  timeoutMs?: number         // default: 10000
  onOpen?: (name: string, failureCount: number) => void
  onClose?: (name: string) => void
}

export class CircuitOpenError extends Error {
  constructor(public readonly circuitName: string) {
    super(`Circuit breaker OPEN for "${circuitName}" — failing fast`)
    this.name = 'CircuitOpenError'
  }
}

export class CircuitTimeoutError extends Error {
  constructor(public readonly circuitName: string, timeoutMs: number) {
    super(`Circuit "${circuitName}" timed out after ${timeoutMs}ms`)
    this.name = 'CircuitTimeoutError'
  }
}

class CircuitBreaker {
  private state: CircuitState = 'CLOSED'
  private failureCount = 0
  private lastFailureTime = 0
  private halfOpenInProgress = false

  constructor(private readonly options: CircuitBreakerOptions) {}

  async execute<T>(fn: () => Promise<T>): Promise<T> {
    if (this.state === 'OPEN') {
      const elapsed = Date.now() - this.lastFailureTime
      if (elapsed < (this.options.cooldownMs ?? 30000)) {
        throw new CircuitOpenError(this.options.name)
      }
      this.state = 'HALF_OPEN'
      this.halfOpenInProgress = false
      log({ level: 'info', message: `[circuit-breaker] ${this.options.name}: OPEN → HALF_OPEN` })
    }

    if (this.state === 'HALF_OPEN' && this.halfOpenInProgress) {
      throw new CircuitOpenError(this.options.name)
    }

    if (this.state === 'HALF_OPEN') {
      this.halfOpenInProgress = true
    }

    const timeoutMs = this.options.timeoutMs ?? 10000
    try {
      const result = await this.executeWithTimeout(fn, timeoutMs)
      this.onSuccess()
      return result
    } catch (err) {
      this.onFailure(err)
      throw err
    }
  }

  private async executeWithTimeout<T>(fn: () => Promise<T>, timeoutMs: number): Promise<T> {
    let timeoutId: any
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutId = setTimeout(() => {
        reject(new CircuitTimeoutError(this.options.name, timeoutMs))
      }, timeoutMs)
    })

    try {
      return await Promise.race([fn(), timeoutPromise])
    } finally {
      clearTimeout(timeoutId)
    }
  }

  private onSuccess(): void {
    const wasOpen = this.state !== 'CLOSED'
    this.failureCount = 0
    this.state = 'CLOSED'
    this.halfOpenInProgress = false
    if (wasOpen) {
      log({ level: 'info', message: `[circuit-breaker] ${this.options.name}: → CLOSED (recovered)` })
      this.options.onClose?.(this.options.name)
    }
  }

  private onFailure(error: unknown): void {
    this.failureCount++
    this.lastFailureTime = Date.now()
    const threshold = this.options.failureThreshold ?? 5

    if (this.state === 'HALF_OPEN') {
      this.state = 'OPEN'
      this.halfOpenInProgress = false
      log({ level: 'warn', message: `[circuit-breaker] ${this.options.name}: HALF_OPEN → OPEN` })
    } else if (this.failureCount >= threshold) {
      this.state = 'OPEN'
      log({
        level: 'warn',
        message: `[circuit-breaker] ${this.options.name}: CLOSED → OPEN (${this.failureCount} failures, last: ${error instanceof Error ? error.message : String(error)})`,
      })
      this.options.onOpen?.(this.options.name, this.failureCount)
    }
  }

  getState() {
    return {
      name: this.options.name,
      state: this.state,
      failureCount: this.failureCount,
      lastFailureTime: this.lastFailureTime,
    }
  }

  reset(): void {
    this.state = 'CLOSED'
    this.failureCount = 0
    this.lastFailureTime = 0
    this.halfOpenInProgress = false
  }
}

// ─── Registry ───────────────────────────────────────────────────────────────

const breakers = new Map<string, CircuitBreaker>()

export function getCircuitBreaker(name: string, options?: Partial<CircuitBreakerOptions>): CircuitBreaker {
  if (!breakers.has(name)) {
    breakers.set(name, new CircuitBreaker({ name, ...options }))
  }
  return breakers.get(name)!
}

export function getAllCircuitStates() {
  return Array.from(breakers.values()).map(b => b.getState())
}

// ─── Pre-configured Breakers ────────────────────────────────────────────────

export const stripeBreaker = getCircuitBreaker('stripe', { failureThreshold: 5, cooldownMs: 30000, timeoutMs: 15000 })
export const mpesaBreaker = getCircuitBreaker('mpesa', { failureThreshold: 5, cooldownMs: 60000, timeoutMs: 30000 })
export const paypalBreaker = getCircuitBreaker('paypal', { failureThreshold: 5, cooldownMs: 30000, timeoutMs: 15000 })
export const nlimsBreaker = getCircuitBreaker('nlims', { failureThreshold: 3, cooldownMs: 300000, timeoutMs: 30000 })
export const ardhisasaBreaker = getCircuitBreaker('ardhisasa', { failureThreshold: 3, cooldownMs: 300000, timeoutMs: 30000 })
export const kencorsBreaker = getCircuitBreaker('kencors', { failureThreshold: 5, cooldownMs: 120000, timeoutMs: 10000 })
export const webodmBreaker = getCircuitBreaker('webodm', { failureThreshold: 3, cooldownMs: 300000, timeoutMs: 120000 })
export const nvidiaBreaker = getCircuitBreaker('nvidia', { failureThreshold: 5, cooldownMs: 60000, timeoutMs: 30000 })
export const pythonWorkerBreaker = getCircuitBreaker('python-worker', { failureThreshold: 5, cooldownMs: 30000, timeoutMs: 60000 })

/**
 * Wrap an async function with circuit breaker protection.
 */
export async function withCircuit<T>(
  breakerName: string,
  fn: () => Promise<T>,
  options?: Partial<CircuitBreakerOptions>,
): Promise<T> {
  const breaker = getCircuitBreaker(breakerName, options)
  return breaker.execute(fn)
}

/**
 * RIM Overlap Detection
 * =====================
 *
 * Detects boundary overlaps between a new survey parcel and existing
 * parcels on the same Registry Index Map (RIM) sheet. ArdhiSasa
 * rejects overlapping parcels; catching this in-office saves a
 * rejection cycle.
 *
 * How it works
 * ------------
 * Given a new parcel's vertices and a list of existing parcels (from
 * the RIM database, filtered by map sheet), compute the geometric
 * intersection of the new parcel with each existing one. If any
 * intersection has non-zero area, it's an overlap.
 *
 * The actual geometry uses turf's intersect() via turfHelpers.ts.
 * This module wraps it with survey-specific logic:
 *   - Filter by map sheet (parcels on different sheets can't overlap)
 *   - Report overlap area + percentage of the new parcel
 *   - Threshold: any overlap > 0.01 m² is flagged (sub-centimeter
 *     overlaps are numerical noise, not real conflicts)
 *
 * Integration
 * -----------
 * - Statutory gate: a new rule 'ardhisasa.rim_overlap' blocks
 *   submission if any overlap is detected
 * - UI: a pre-submission check button on the submission page calls
 *   /api/rim/overlap-check to show overlaps before export
 *
 * Usage
 * -----
 *   import { detectOverlaps } from '@/lib/rim/overlapDetection'
 *
 *   const result = await detectOverlaps({
 *     newParcel: { parcelNumber: 'LR 123/456', vertices: [...] },
 *     existingParcels: [
 *       { parcelNumber: 'LR 123/455', vertices: [...] },
 *       { parcelNumber: 'LR 123/457', vertices: [...] },
 *     ],
 *   })
 *
 *   if (result.hasOverlaps) {
 *     for (const overlap of result.overlaps) {
 *       console.warn(`${overlap.existingParcelNumber}: ${overlap.overlapAreaSqm.toFixed(1)} m²`)
 *     }
 *   }
 */

import { calculateIntersection } from '@/lib/map/turfHelpers'
import { shoelaceArea } from '@/lib/engine/area'

// ─── Types ──────────────────────────────────────────────────────────────

/** A parcel with boundary vertices in projected CRS (EPSG:21037). */
export interface ParcelForOverlap {
  parcelNumber: string
  /** Boundary vertices — minimum 3 for a valid polygon. */
  vertices: Array<{ easting: number; northing: number; name?: string }>
}

/** A single overlap between the new parcel and an existing one. */
export interface OverlapResult {
  /** Parcel number of the existing parcel that overlaps. */
  existingParcelNumber: string
  /** Vertices of the overlap polygon (the intersection area). */
  overlapVertices: Array<{ easting: number; northing: number }>
  /** Overlap area in square metres. */
  overlapAreaSqm: number
  /** Overlap area as a percentage of the new parcel's total area. */
  overlapPercent: number
}

/** Result of an overlap detection check. */
export interface OverlapDetectionResult {
  /** True if any overlap was found. */
  hasOverlaps: boolean
  /** List of all overlaps found (empty if none). */
  overlaps: OverlapResult[]
  /** The new parcel's area in m², for context. */
  newParcelAreaSqm: number
  /** Total time spent on the check, in milliseconds. */
  elapsedMs: number
  /** Number of existing parcels checked. */
  checkedCount: number
  /** Number of existing parcels skipped (invalid geometry). */
  skippedCount: number
}

// ─── Thresholds ─────────────────────────────────────────────────────────

/**
 * Overlap areas below this threshold are treated as numerical noise
 * and ignored. 0.01 m² = 100 cm² — sub-centimeter slivers from
 * coordinate rounding, not real boundary conflicts.
 */
const MIN_OVERLAP_AREA_SQM = 0.01

// shoelaceArea is imported from @/lib/engine/area (canonical implementation)

// ─── Public API ─────────────────────────────────────────────────────────

/**
 * Detect overlaps between a new parcel and a list of existing parcels.
 *
 * This is the core detection function. It's async because turf's
 * intersect() is loaded lazily (heavy dependency).
 *
 * @param newParcel - The parcel being submitted (new survey)
 * @param existingParcels - Existing parcels on the same RIM sheet
 * @returns Overlap detection result
 */
export async function detectOverlaps(params: {
  newParcel: ParcelForOverlap
  existingParcels: ParcelForOverlap[]
}): Promise<OverlapDetectionResult> {
  const startTime = Date.now()
  const { newParcel, existingParcels } = params

  const newParcelAreaSqm = shoelaceArea(newParcel.vertices)
  const overlaps: OverlapResult[] = []
  let skippedCount = 0

  for (const existing of existingParcels) {
    // Skip parcels with invalid geometry
    if (existing.vertices.length < 3) {
      skippedCount++
      continue
    }

    try {
      const intersection = await calculateIntersection(
        newParcel.vertices as any,
        existing.vertices as any
      )

      if (!intersection || intersection.length < 3) {
        continue
      }

      const overlapAreaSqm = shoelaceArea(intersection)

      // Ignore sub-threshold overlaps (numerical noise)
      if (overlapAreaSqm < MIN_OVERLAP_AREA_SQM) {
        continue
      }

      const overlapPercent = newParcelAreaSqm > 0
        ? (overlapAreaSqm / newParcelAreaSqm) * 100
        : 0

      overlaps.push({
        existingParcelNumber: existing.parcelNumber,
        overlapVertices: intersection,
        overlapAreaSqm,
        overlapPercent,
      })
    } catch (err) {
      // Turf can throw on degenerate polygons. Skip and continue.
      skippedCount++
      console.warn(
        `[overlapDetection] Failed to check against ${existing.parcelNumber}:`,
        err instanceof Error ? err.message : String(err)
      )
    }
  }

  // Sort overlaps by area descending — biggest conflicts first
  overlaps.sort((a, b) => b.overlapAreaSqm - a.overlapAreaSqm)

  return {
    hasOverlaps: overlaps.length > 0,
    overlaps,
    newParcelAreaSqm,
    elapsedMs: Date.now() - startTime,
    checkedCount: existingParcels.length,
    skippedCount,
  }
}

/**
 * Quick boolean check: does the new parcel overlap ANY existing parcel?
 *
 * Faster than detectOverlaps() because it returns as soon as the first
 * overlap is found, without computing all overlaps. Use this for
 * real-time validation (e.g. as the surveyor draws the boundary).
 */
export async function hasAnyOverlap(params: {
  newParcel: ParcelForOverlap
  existingParcels: ParcelForOverlap[]
}): Promise<boolean> {
  const { newParcel, existingParcels } = params

  for (const existing of existingParcels) {
    if (existing.vertices.length < 3) continue

    try {
      const intersection = await calculateIntersection(
        newParcel.vertices as any,
        existing.vertices as any
      )
      if (intersection && intersection.length >= 3) {
        const area = shoelaceArea(intersection)
        if (area >= MIN_OVERLAP_AREA_SQM) {
          return true // early exit
        }
      }
    } catch {
      // skip
    }
  }

  return false
}

/**
 * Format an overlap detection result as a human-readable summary.
 * Useful for display in the UI or inclusion in a validation report.
 */
export function formatOverlapResult(result: OverlapDetectionResult): string {
  if (!result.hasOverlaps) {
    return `No overlaps detected. Checked ${result.checkedCount} existing parcel(s) in ${result.elapsedMs}ms.`
  }

  const lines: string[] = [
    `Found ${result.overlaps.length} overlap(s) in ${result.elapsedMs}ms:`,
    '',
  ]

  for (const overlap of result.overlaps) {
    lines.push(
      `  ${overlap.existingParcelNumber}: ${overlap.overlapAreaSqm.toFixed(1)} m² (${overlap.overlapPercent.toFixed(2)}% of new parcel)`
    )
  }

  return lines.join('\n')
}

// ============================================================
// METARDU — RIM PDF Generator (Resurvey and Index Map)
// Professional A3 Landscape output for Kenya cadastral use
// Survey Act Cap 299, Survey Regulations L.N. 168/1994
//
// Uses A3 Landscape (420mm × 297mm) as a close substitute for
// A1/A0 RIM sheets. jsPDF has limited large-format support;
// A3 landscape provides sufficient space for RIM content while
// remaining printable on standard large-format plotters.
//
// Styling aligns with CLA form patterns:
//   - Dark navy section headers: rgb(27, 58, 92)
//   - 15mm margins
//   - Professional border framing
// ============================================================

import jsPDF from 'jspdf'
import type { RimSection, RimParcel, RimBeacon } from './db'

// A3 Landscape dimensions in mm (420 × 297)
const PAGE_W = 420
const PAGE_H = 297
const MARGIN = 15

// Navy colour used across CLA forms and RIM headers
const NAVY: [number, number, number] = [27, 58, 92]

export function generateRimPdf(
  section: RimSection,
  parcels: RimParcel[],
  beacons: RimBeacon[],
): Uint8Array {
  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3',
  })

  const contentW = PAGE_W - MARGIN * 2
  let y = MARGIN

  // ── Outer & inner border ────────────────────────────────────
  doc.setDrawColor(0)
  doc.setLineWidth(0.6)
  doc.rect(MARGIN, MARGIN, contentW, PAGE_H - MARGIN * 2)
  doc.setLineWidth(0.25)
  doc.rect(MARGIN + 1.5, MARGIN + 1.5, contentW - 3, PAGE_H - MARGIN * 2 - 3)

  const left = MARGIN + 4
  const right = PAGE_W - MARGIN - 4
  const innerW = right - left

  // ────────────────────────────────────────────────────────────
  // 1. HEADER BLOCK
  // ────────────────────────────────────────────────────────────

  y = MARGIN + 10

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(16)
  doc.setTextColor(0, 0, 0)
  doc.text('REPUBLIC OF KENYA', PAGE_W / 2, y, { align: 'center' })

  y += 7
  doc.setFontSize(11)
  doc.setFont('helvetica', 'normal')
  doc.text('Ministry of Lands and Physical Planning', PAGE_W / 2, y, { align: 'center' })

  y += 7
  doc.setDrawColor(0)
  doc.setLineWidth(0.4)
  doc.line(left, y, right, y)

  y += 7
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(14)
  doc.setTextColor(...NAVY)
  doc.text('RESURVEY AND INDEX MAP', PAGE_W / 2, y, { align: 'center' })

  // Reset text colour
  doc.setTextColor(0, 0, 0)

  y += 9
  doc.setFontSize(9)
  doc.setFont('helvetica', 'bold')
  doc.text(`Section: ${section.section_name || '\u2014'}`, left, y)
  doc.text(`Registry: ${section.registry || '\u2014'}`, left + 130, y)
  doc.text(`District / County: ${section.district || '\u2014'}`, left + 230, y)

  y += 6
  doc.text(`Map Sheet No: ${section.map_sheet_number || '\u2014'}`, left, y)
  doc.text(`Scale: ${section.scale || '\u2014'}`, left + 130, y)
  doc.text(`Datum: ${section.datum || '\u2014'}`, left + 230, y)

  y += 6
  doc.text(`Projection: ${section.projection || '\u2014'}`, left, y)
  const today = new Date().toLocaleDateString('en-GB', {
    day: '2-digit', month: 'short', year: 'numeric',
  })
  doc.text(`Date: ${today}`, left + 130, y)
  doc.text(`Total Area: ${section.total_area.toFixed(4)} Ha`, left + 230, y)

  y += 3
  doc.setDrawColor(...NAVY)
  doc.setLineWidth(0.5)
  doc.line(left, y, right, y)

  // ────────────────────────────────────────────────────────────
  // 2. PARCEL REGISTER TABLE
  // ────────────────────────────────────────────────────────────

  y += 6
  sectionHeader(doc, 'PARCEL REGISTER', left, y, innerW)
  y += 10

  if (parcels.length > 0) {
    const head = [['No.', 'Parcel Number', 'Area (Ha)', 'Land Use', 'Owner', 'Beacons']]

    const body: string[][] = parcels.map((p, i) => [
      String(i + 1),
      p.parcel_number,
      p.area.toFixed(4),
      p.land_use || '\u2014',
      p.owner_name || '\u2014',
      String(p.beacon_count),
    ])

    // Total row
    const totalArea = parcels.reduce((sum, p) => sum + p.area, 0)
    const totalBeacons = parcels.reduce((sum, p) => sum + p.beacon_count, 0)
    body.push(['', 'TOTAL', totalArea.toFixed(4), '', '', String(totalBeacons)])

    // Column widths (total = innerW ≈ 386mm)
    const colW = [12, 80, 45, 70, 110, 25] // remainder fills last column

    drawTable(doc, {
      head,
      body,
      startY: y,
      columnWidths: colW,
      fontSize: 8,
      headerBg: NAVY,
      alternateRowColor: [240, 244, 248] as [number, number, number],
      highlightLastRow: true,
    })

    // Get final Y position after table
    y = (doc as any).lastAutoTable?.finalY
      ? (doc as any).lastAutoTable.finalY + 6
      : y + parcels.length * 7 + 10
  } else {
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(9)
    doc.setTextColor(120)
    doc.text('No parcels recorded for this RIM section.', left + 4, y)
    doc.setTextColor(0)
    y += 10
  }

  // ────────────────────────────────────────────────────────────
  // 3. BEACON SCHEDULE
  // ────────────────────────────────────────────────────────────

  // Check if there's enough space; if not, add new page
  if (y > PAGE_H - MARGIN - 80) {
    doc.addPage()
    y = MARGIN + 10
  }

  sectionHeader(doc, 'BEACON SCHEDULE', left, y, innerW)
  y += 10

  if (beacons.length > 0) {
    const head = [['No.', 'Beacon No.', 'Easting', 'Northing', 'Type', 'Description', 'Status']]

    const body: string[][] = beacons.map((b, i) => [
      String(i + 1),
      b.beacon_number,
      b.easting.toFixed(3),
      b.northing.toFixed(3),
      b.type || 'Pillar',
      b.description || '\u2014',
      b.survey_status || 'Original',
    ])

    const colW = [12, 45, 55, 55, 35, 110, 50]

    drawTable(doc, {
      head,
      body,
      startY: y,
      columnWidths: colW,
      fontSize: 7.5,
      headerBg: NAVY,
      alternateRowColor: [240, 244, 248] as [number, number, number],
      // Highlight beacons with "Not Found" or "Replaced" status
      statusHighlight: {
        column: 6,
        values: ['Not Found', 'Replaced'],
        color: [255, 230, 230] as [number, number, number],
      },
    })

    y = (doc as any).lastAutoTable?.finalY
      ? (doc as any).lastAutoTable.finalY + 6
      : y + beacons.length * 7 + 10
  } else {
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(9)
    doc.setTextColor(120)
    doc.text('No beacons recorded for this RIM section.', left + 4, y)
    doc.setTextColor(0)
    y += 10
  }

  // ────────────────────────────────────────────────────────────
  // 4. NOTES SECTION
  // ────────────────────────────────────────────────────────────

  if (y > PAGE_H - MARGIN - 65) {
    doc.addPage()
    y = MARGIN + 10
  }

  sectionHeader(doc, 'NOTES AND REMARKS', left, y, innerW)
  y += 10

  doc.setFont('helvetica', 'normal')
  doc.setFontSize(8)
  doc.setTextColor(40)

  const notes = section.notes || 'No additional notes for this RIM section.'
  const notesLines = doc.splitTextToSize(notes, innerW - 8)
  notesLines.forEach((line: string) => {
    if (y > PAGE_H - MARGIN - 55) {
      doc.addPage()
      y = MARGIN + 10
    }
    doc.text(line, left + 4, y)
    y += 5
  })

  doc.setTextColor(0)

  // ────────────────────────────────────────────────────────────
  // 5. FOOTER
  // ────────────────────────────────────────────────────────────

  // Position footer at fixed location near page bottom
  const footerY = PAGE_H - MARGIN - 40

  // Separator line
  doc.setDrawColor(...NAVY)
  doc.setLineWidth(0.4)
  doc.line(left, footerY, right, footerY)

  // Surveyor certification block
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  doc.text('SURVEYOR CERTIFICATION', left, footerY + 7)

  doc.setFontSize(8)
  doc.setFont('helvetica', 'normal')

  // Name and ISK fields
  const certY = footerY + 14
  doc.text('Name: ____________________________', left, certY)
  doc.text('ISK Registration No: ____________________________', left + 180, certY)

  const sigY = certY + 10
  doc.text('Signature: ____________________________', left, sigY)
  doc.text('Date: ____________________________', left + 180, sigY)

  // Watermark / generated-by line
  doc.setFont('helvetica', 'italic')
  doc.setFontSize(7)
  doc.setTextColor(130)
  doc.text(
    'This RIM has been prepared using METARDU',
    PAGE_W / 2,
    PAGE_H - MARGIN - 6,
    { align: 'center' },
  )

  // Page number
  const totalPages = doc.getNumberOfPages()
  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i)
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(7)
    doc.setTextColor(100)
    doc.text(`Page ${i} of ${totalPages}`, right, PAGE_H - MARGIN - 6, { align: 'right' })
  }

  return doc.output('arraybuffer') as unknown as Uint8Array
}

// ────────────────────────────────────────────────────────────
// Helper: Navy section header bar
// ────────────────────────────────────────────────────────────

function sectionHeader(
  doc: jsPDF,
  title: string,
  x: number,
  y: number,
  w: number,
) {
  doc.setFillColor(...NAVY)
  doc.rect(x, y, w, 7, 'F')
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  doc.setTextColor(255, 255, 255)
  doc.text(title, x + 3, y + 5)
  doc.setTextColor(0, 0, 0)
}

// ────────────────────────────────────────────────────────────
// Helper: Draw a styled table with optional features
//
// NOTE: This is a manual table renderer to avoid requiring
// jspdf-autotable as a dependency. If autotable is available,
// this can be swapped out for autoTable() calls.
// ────────────────────────────────────────────────────────────

interface TableOptions {
  head: string[][]
  body: string[][]
  startY: number
  columnWidths: number[]
  fontSize: number
  headerBg: [number, number, number]
  alternateRowColor: [number, number, number]
  highlightLastRow?: boolean
  statusHighlight?: {
    column: number
    values: string[]
    color: [number, number, number]
  }
}

function drawTable(doc: jsPDF, opts: TableOptions) {
  const { head, body, startY, columnWidths, fontSize, headerBg, alternateRowColor } = opts
  const x = MARGIN + 4 // left edge of content
  const rowH = 6.5
  const headerH = 7
  let currentY = startY

  // ── Header row ────────────────────────────────────────────
  doc.setFillColor(...headerBg)
  doc.rect(x, currentY, columnWidths.reduce((a, b) => a + b, 0), headerH, 'F')

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(fontSize)
  doc.setTextColor(255, 255, 255)

  let colX = x
  head[0].forEach((cell, ci) => {
    const w = columnWidths[ci] || 40
    doc.text(cell, colX + 2, currentY + headerH - 2)
    colX += w
  })

  doc.setTextColor(0, 0, 0)
  currentY += headerH

  // ── Body rows ─────────────────────────────────────────────
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(fontSize)

  body.forEach((row, ri) => {
    const isLast = opts.highlightLastRow && ri === body.length - 1
    const isAlternate = ri % 2 === 1

    // Row background
    if (isLast) {
      doc.setFillColor(220, 230, 241)
      doc.rect(x, currentY, columnWidths.reduce((a, b) => a + b, 0), rowH, 'F')
      doc.setFont('helvetica', 'bold')
    } else if (isAlternate) {
      doc.setFillColor(...alternateRowColor)
      doc.rect(x, currentY, columnWidths.reduce((a, b) => a + b, 0), rowH, 'F')
    }

    // Check for status highlight
    const statusCol = opts.statusHighlight?.column
    if (statusCol !== undefined && opts.statusHighlight) {
      const cellVal = row[statusCol]
      if (cellVal && opts.statusHighlight.values.includes(cellVal)) {
        // Calculate position of the status column cell
        let cellX = x
        for (let c = 0; c < statusCol; c++) {
          cellX += columnWidths[c] || 40
        }
        const cellW = columnWidths[statusCol] || 40
        doc.setFillColor(...opts.statusHighlight.color)
        doc.rect(cellX, currentY, cellW, rowH, 'F')
      }
    }

    // Row text
    colX = x
    row.forEach((cell, ci) => {
      const w = columnWidths[ci] || 40
      const isFirstCol = ci === 0
      const isNumericCol = ci === 2 || ci === 3 || ci === 5 // area, northing, beacons
      doc.text(cell, colX + (isFirstCol ? 2 : 2), currentY + rowH - 2, {
        align: isFirstCol || isNumericCol ? 'center' : 'left',
      })
      colX += w
    })

    // Row border
    doc.setDrawColor(200)
    doc.setLineWidth(0.15)
    doc.line(x, currentY + rowH, x + columnWidths.reduce((a, b) => a + b, 0), currentY + rowH)

    if (isLast) {
      doc.setFont('helvetica', 'normal')
    }

    currentY += rowH
  })

  // Outer table border
  doc.setDrawColor(0)
  doc.setLineWidth(0.3)
  const tableH = headerH + body.length * rowH
  const tableW = columnWidths.reduce((a, b) => a + b, 0)
  doc.rect(x, startY, tableW, tableH)

  // Store final Y for caller reference
  ;(doc as any).lastAutoTable = { finalY: currentY + 2 }
}

/**
 * Job Scheduling Library
 * Database-backed scheduling for survey jobs with reminders.
 * Uses the job_schedule table via DbClient/postgres proxy.
 */

import { createClient } from '@/lib/api-client/client'

export type SchedulePriority = 'low' | 'normal' | 'high' | 'urgent'
export type ScheduleStatus = 'upcoming' | 'in_progress' | 'completed' | 'cancelled' | 'postponed'

export interface JobSchedule {
  id: string
  user_id: string
  job_id?: string | null
  marketplace_job_id?: string | null
  title: string
  description?: string | null
  scheduled_date: string
  scheduled_time?: string | null
  location?: string | null
  client_name?: string | null
  client_contact?: string | null
  estimated_duration_hours: number
  status: ScheduleStatus
  reminder_enabled: boolean
  reminder_days_before: number[]
  reminder_notes?: string | null
  survey_type?: string | null
  equipment_needed: string[]
  team_members: string[]
  priority: SchedulePriority
  notes?: string | null
  created_at: string
  updated_at: string
  completed_at?: string | null
}

export interface JobScheduleWithAlerts extends JobSchedule {
  isReminderDue: boolean
  daysUntil: number
  isOverdue: boolean
  isToday: boolean
}

const STATUS_LABELS: Record<ScheduleStatus, string> = {
  upcoming: 'Upcoming',
  in_progress: 'In Progress',
  completed: 'Completed',
  cancelled: 'Cancelled',
  postponed: 'Postponed',
}

const PRIORITY_COLORS: Record<SchedulePriority, string> = {
  low: 'bg-blue-500/20 text-blue-300 border-blue-500/30',
  normal: 'bg-gray-500/20 text-gray-300 border-gray-500/30',
  high: 'bg-amber-500/20 text-amber-300 border-amber-500/30',
  urgent: 'bg-red-500/20 text-red-300 border-red-500/30',
}

export { STATUS_LABELS, PRIORITY_COLORS }

// ── Helpers ────────────────────────────────────────────────────────────────

function daysBetween(dateStr: string): number {
  const today = new Date()
  today.setHours(0, 0, 0, 0)
  const target = new Date(dateStr)
  target.setHours(0, 0, 0, 0)
  return Math.ceil((target.getTime() - today.getTime()) / 86_400_000)
}

export function enrichWithAlerts(schedule: JobSchedule): JobScheduleWithAlerts {
  const daysUntil = daysBetween(schedule.scheduled_date)
  const isToday = daysUntil === 0
  const isOverdue = daysUntil < 0 && schedule.status === 'upcoming'
  const isReminderDue = schedule.reminder_enabled &&
    schedule.status === 'upcoming' &&
    schedule.reminder_days_before.some(d => d === daysUntil)

  return { ...schedule, isReminderDue, daysUntil, isOverdue, isToday }
}

// ── CRUD Operations (via DbClient client proxy) ───────────────────────────

export async function getSchedules(userId: string): Promise<JobSchedule[]> {
  const sb = createClient()
  const { data, error } = await sb
    .from('job_schedule')
    .select('*')
    .eq('user_id', userId)
    .order('scheduled_date', { ascending: true })
    .order('scheduled_time', { ascending: true })
  if (error) throw new Error(error.message)
  return data ?? []
}

export async function getUpcomingSchedules(userId: string): Promise<JobScheduleWithAlerts[]> {
  const all = await getSchedules(userId)
  return all
    .filter(s => s.status === 'upcoming')
    .map(enrichWithAlerts)
}

export async function getScheduleById(id: string): Promise<JobSchedule | null> {
  const sb = createClient()
  const { data, error } = await sb.from('job_schedule').select('*').eq('id', id).maybeSingle()
  if (error) throw new Error(error.message)
  return data
}

export async function createSchedule(data: Omit<JobSchedule, 'id' | 'created_at' | 'updated_at' | 'completed_at'>): Promise<JobSchedule> {
  const sb = createClient()
  const { data: result, error } = await sb
    .from('job_schedule')
    .insert(data)
    .select()
    .single()
  if (error) throw new Error(error.message)
  return result
}

export async function updateSchedule(id: string, updates: Partial<JobSchedule>): Promise<JobSchedule> {
  const sb = createClient()
  const { data: result, error } = await sb
    .from('job_schedule')
    .update({ ...updates, updated_at: new Date().toISOString() })
    .eq('id', id)
    .select()
    .single()
  if (error) throw new Error(error.message)
  return result
}

export async function deleteSchedule(id: string): Promise<void> {
  const sb = createClient()
  const { error } = await sb.from('job_schedule').delete().eq('id', id)
  if (error) throw new Error(error.message)
}

export async function markScheduleCompleted(id: string): Promise<JobSchedule> {
  return updateSchedule(id, {
    status: 'completed',
    completed_at: new Date().toISOString(),
  })
}

export async function markScheduleCancelled(id: string): Promise<JobSchedule> {
  return updateSchedule(id, { status: 'cancelled' })
}

export async function getDueReminders(userId: string): Promise<JobScheduleWithAlerts[]> {
  const upcoming = await getUpcomingSchedules(userId)
  return upcoming.filter(s => s.isReminderDue)
}

// ── Statistics ─────────────────────────────────────────────────────────────

export async function getScheduleStats(userId: string) {
  const all = await getSchedules(userId)
  const today = new Date().toISOString().split('T')[0]
  const weekFromNow = new Date(Date.now() + 7 * 86_400_000).toISOString().split('T')[0]

  return {
    total: all.length,
    upcoming: all.filter(s => s.status === 'upcoming').length,
    completed: all.filter(s => s.status === 'completed').length,
    inProgress: all.filter(s => s.status === 'in_progress').length,
    today: all.filter(s => s.scheduled_date === today && s.status === 'upcoming').length,
    thisWeek: all.filter(s => s.scheduled_date >= today && s.scheduled_date <= weekFromNow && s.status === 'upcoming').length,
    overdue: all.filter(s => {
      const d = daysBetween(s.scheduled_date)
      return d < 0 && s.status === 'upcoming'
    }).length,
  }
}

// ── Format Helpers ────────────────────────────────────────────────────────

export function formatDate(dateStr: string): string {
  const d = new Date(dateStr)
  return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
}

export function formatTime(timeStr: string | null): string {
  if (!timeStr) return ''
  const [h, m] = timeStr.split(':')
  const hour = parseInt(h)
  const ampm = hour >= 12 ? 'PM' : 'AM'
  const h12 = hour % 12 || 12
  return `${h12}:${m} ${ampm}`
}

export function getRelativeDate(dateStr: string): string {
  const days = daysBetween(dateStr)
  if (days === 0) return 'Today'
  if (days === 1) return 'Tomorrow'
  if (days === -1) return 'Yesterday'
  if (days > 0 && days <= 7) return `In ${days} days`
  if (days < 0 && days >= -7) return `${Math.abs(days)} days ago`
  return formatDate(dateStr)
}

