/**
 * @module cryptoSealing
 *
 * Cryptographic Digital Sealing for Field Records
 *
 * Implements PKI-based signing of survey observations:
 * 1. Generate ECDSA P-256 key pair per surveyor (stored in IndexedDB)
 * 2. Sign each beacon observation with private key
 * 3. Embed signature in exported data files
 * 4. Verify signature on import (tamper detection)
 *
 * Uses Web Crypto API (available in browsers and Node.js 18+):
 * - ECDSA with P-256 curve (FIPS 186-4)
 * - SHA-256 for hashing
 * - Base64 encoding for storage
 *
 * Legal significance:
 * - Signed records are admissible as evidence under Kenya Evidence Act
 * - Tampered files fail verification instantly
 * - Private key never leaves the device (non-repudiation)
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface SurveyorKeyPair {
  surveyorId: string
  publicKeyJwk: JsonWebKey
  privateKeyJwk: JsonWebKey
  createdAt: string
  fingerprint: string  // SHA-256 hash of public key (for verification)
}

export interface SealedRecord {
  /** The original data that was signed */
  data: {
    pointId: string
    wgs84Lat: number
    wgs84Lng: number
    arc1960Easting: number
    arc1960Northing: number
    gpsAccuracy: number
    capturedAt: string
    surveyorId: string
    surveyorLicense: string
  }
  /** ECDSA signature (base64) */
  signature: string
  /** Algorithm used */
  algorithm: 'ECDSA-SHA256'
  /** Public key fingerprint for verification */
  publicKeyFingerprint: string
  /** When the seal was created */
  sealedAt: string
}

export interface VerificationResult {
  isValid: boolean
  error?: string
  surveyorId?: string
  sealedAt?: string
  dataHash?: string
}

// ---------------------------------------------------------------------------
// Key Pair Management
// ---------------------------------------------------------------------------

const DB_NAME = 'metardu-crypto'
const DB_VERSION = 1
const STORE_NAME = 'keypairs'

async function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION)
    request.onerror = () => reject(request.error)
    request.onsuccess = () => resolve(request.result)
    request.onupgradeneeded = () => {
      const db = request.result
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'surveyorId' })
      }
    }
  })
}

/**
 * Generate a new ECDSA P-256 key pair for a surveyor.
 * The private key never leaves the browser.
 */
export async function generateKeyPair(surveyorId: string): Promise<SurveyorKeyPair> {
  const keyPair = await crypto.subtle.generateKey(
    {
      name: 'ECDSA',
      namedCurve: 'P-256',
    },
    true,  // extractable (needed to export for storage)
    ['sign', 'verify'],
  )

  const publicKeyJwk = await crypto.subtle.exportKey('jwk', keyPair.publicKey)
  const privateKeyJwk = await crypto.subtle.exportKey('jwk', keyPair.privateKey)

  // Compute fingerprint (SHA-256 of public key)
  const publicKeyBytes = new TextEncoder().encode(JSON.stringify(publicKeyJwk))
  const fingerprintBuffer = await crypto.subtle.digest('SHA-256', publicKeyBytes)
  const fingerprint = Array.from(new Uint8Array(fingerprintBuffer))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')

  const keyPairRecord: SurveyorKeyPair = {
    surveyorId,
    publicKeyJwk,
    privateKeyJwk,
    createdAt: new Date().toISOString(),
    fingerprint,
  }

  // Store in IndexedDB
  const db = await openDB()
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite')
    tx.objectStore(STORE_NAME).put(keyPairRecord)
    tx.oncomplete = () => resolve()
    tx.onerror = () => reject(tx.error)
  })

  return keyPairRecord
}

/**
 * Retrieve the surveyor's key pair from IndexedDB.
 */
export async function getKeyPair(surveyorId: string): Promise<SurveyorKeyPair | null> {
  const db = await openDB()
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly')
    const request = tx.objectStore(STORE_NAME).get(surveyorId)
    request.onsuccess = () => resolve(request.result || null)
    request.onerror = () => reject(request.error)
  })
}

/**
 * Delete the surveyor's key pair (for account deletion).
 */
export async function deleteKeyPair(surveyorId: string): Promise<void> {
  const db = await openDB()
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite')
    tx.objectStore(STORE_NAME).delete(surveyorId)
    tx.oncomplete = () => resolve()
    tx.onerror = () => reject(tx.error)
  })
}

// ---------------------------------------------------------------------------
// Sealing (Signing)
// ---------------------------------------------------------------------------

/**
 * Create a sealed record by signing the observation data.
 *
 * @param data - The observation data to seal
 * @param surveyorId - Surveyor's ID (must have a key pair)
 * @returns The sealed record with signature
 */
export async function sealRecord(
  data: SealedRecord['data'],
  surveyorId: string,
): Promise<SealedRecord> {
  // Get private key
  const keyPair = await getKeyPair(surveyorId)
  if (!keyPair) {
    throw new Error('No key pair found. Generate a key pair first.')
  }

  // Import private key
  const privateKey = await crypto.subtle.importKey(
    'jwk',
    keyPair.privateKeyJwk,
    { name: 'ECDSA', namedCurve: 'P-256' },
    false,
    ['sign'],
  )

  // Sign the data
  const dataBytes = new TextEncoder().encode(JSON.stringify(data))
  const signatureBuffer = await crypto.subtle.sign(
    { name: 'ECDSA', hash: 'SHA-256' },
    privateKey,
    dataBytes,
  )

  // Convert signature to base64
  const signature = btoa(
    String.fromCharCode(...new Uint8Array(signatureBuffer)),
  )

  return {
    data,
    signature,
    algorithm: 'ECDSA-SHA256',
    publicKeyFingerprint: keyPair.fingerprint,
    sealedAt: new Date().toISOString(),
  }
}

/**
 * Seal multiple records (batch signing for field book export).
 */
export async function sealRecords(
  records: SealedRecord['data'][],
  surveyorId: string,
): Promise<SealedRecord[]> {
  const sealed: SealedRecord[] = []
  for (const record of records) {
    sealed.push(await sealRecord(record, surveyorId))
  }
  return sealed
}

// ---------------------------------------------------------------------------
// Verification
// ---------------------------------------------------------------------------

/**
 * Verify a sealed record's signature.
 *
 * @param sealedRecord - The sealed record to verify
 * @param publicKeyJwk - The surveyor's public key (JWK format)
 * @returns Verification result
 */
export async function verifySealedRecord(
  sealedRecord: SealedRecord,
  publicKeyJwk: JsonWebKey,
): Promise<VerificationResult> {
  try {
    // Import public key
    const publicKey = await crypto.subtle.importKey(
      'jwk',
      publicKeyJwk,
      { name: 'ECDSA', namedCurve: 'P-256' },
      false,
      ['verify'],
    )

    // Decode signature from base64
    const signatureBytes = Uint8Array.from(
      atob(sealedRecord.signature),
      c => c.charCodeAt(0),
    )

    // Verify
    const dataBytes = new TextEncoder().encode(JSON.stringify(sealedRecord.data))
    const isValid = await crypto.subtle.verify(
      { name: 'ECDSA', hash: 'SHA-256' },
      publicKey,
      signatureBytes,
      dataBytes,
    )

    // Compute data hash for reference
    const hashBuffer = await crypto.subtle.digest('SHA-256', dataBytes)
    const dataHash = Array.from(new Uint8Array(hashBuffer))
      .map(b => b.toString(16).padStart(2, '0'))
      .join('')

    return {
      isValid,
      surveyorId: sealedRecord.data.surveyorId,
      sealedAt: sealedRecord.sealedAt,
      dataHash,
      error: isValid ? undefined : 'Signature verification failed — data may have been tampered with',
    }
  } catch (err) {
    return {
      isValid: false,
      error: err instanceof Error ? err.message : 'Verification failed',
    }
  }
}

/**
 * Verify a batch of sealed records.
 */
export async function verifySealedRecords(
  sealedRecords: SealedRecord[],
  publicKeyJwk: JsonWebKey,
): Promise<VerificationResult[]> {
  const results: VerificationResult[] = []
  for (const record of sealedRecords) {
    results.push(await verifySealedRecord(record, publicKeyJwk))
  }
  return results
}

// ---------------------------------------------------------------------------
// Export/Import with Embedded Signatures
// ---------------------------------------------------------------------------

/**
 * Create a tamper-evident export file with cryptographic seals.
 * The output JSON contains both the data and the signatures.
 */
export async function createSealedExport(
  records: SealedRecord['data'][],
  surveyorId: string,
  metadata?: Record<string, unknown>,
): Promise<{
  format: 'metardu-sealed-v1'
  exportedAt: string
  surveyorId: string
  metadata?: Record<string, unknown>
  records: SealedRecord[]
}> {
  const sealedRecords = await sealRecords(records, surveyorId)

  return {
    format: 'metardu-sealed-v1',
    exportedAt: new Date().toISOString(),
    surveyorId,
    metadata,
    records: sealedRecords,
  }
}

/**
 * Verify an imported sealed export file.
 */
export async function verifySealedExport(
  exportData: {
    format: string
    records: SealedRecord[]
  },
  publicKeyJwk: JsonWebKey,
): Promise<{
  isValid: boolean
  totalRecords: number
  validRecords: number
  invalidRecords: number
  errors: string[]
}> {
  if (exportData.format !== 'metardu-sealed-v1') {
    return {
      isValid: false,
      totalRecords: 0,
      validRecords: 0,
      invalidRecords: 0,
      errors: ['Unknown export format'],
    }
  }

  const results = await verifySealedRecords(exportData.records, publicKeyJwk)
  const validCount = results.filter(r => r.isValid).length
  const invalidCount = results.length - validCount

  return {
    isValid: invalidCount === 0,
    totalRecords: results.length,
    validRecords: validCount,
    invalidRecords: invalidCount,
    errors: results.filter(r => !r.isValid).map(r => r.error || 'Unknown error'),
  }
}

// ---------------------------------------------------------------------------
// Utility
// ---------------------------------------------------------------------------

/**
 * Compute a SHA-256 hash of any data (for integrity checking).
 */
export async function computeHash(data: unknown): Promise<string> {
  const bytes = new TextEncoder().encode(JSON.stringify(data))
  const hashBuffer = await crypto.subtle.digest('SHA-256', bytes)
  return Array.from(new Uint8Array(hashBuffer))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
}

/**
 * Check if the browser supports Web Crypto API.
 */
export function isCryptoSupported(): boolean {
  return typeof crypto !== 'undefined' &&
    typeof crypto.subtle !== 'undefined' &&
    typeof crypto.subtle.generateKey === 'function'
}

export function getErrorMessage(error: any): string {
  const code = error?.code || ''
  const message = error?.message || ''

  if (code === '23505') return 'This name already exists. Please use a different name.'
  if (code === '23503') return 'Related record not found. Please refresh and try again.'
  if (code === '42501') return 'Permission denied. Please sign in again.'
  if (message.includes('JWT')) return 'Session expired. Please sign in again.'
  if (message.includes('network')) return 'Network error. Check your connection.'
  if (message.includes('fetch')) return 'Cannot reach server. Check your connection.'
  if (message.includes('duplicate')) return 'This already exists. Please use a different name.'
  if (message.includes('not found')) return 'The requested item was not found.'
  
  return message || 'Something went wrong. Please try again.'
}

export function getAuthErrorMessage(error: any): string {
  const message = error?.message || ''
  
  if (message.includes('Invalid login credentials')) return 'Invalid email or password.'
  if (message.includes('User already registered')) return 'This email is already registered.'
  if (message.includes('Password should be at least')) return 'Password must be at least 6 characters.'
  if (message.includes('Email rate limit')) return 'Too many attempts. Please try again later.'
  
  return getErrorMessage(error)
}

export function getValidationError(field: string, type: string): string {
  const errors: Record<string, Record<string, string>> = {
    email: {
      required: 'Email is required',
      invalid: 'Please enter a valid email address'
    },
    password: {
      required: 'Password is required',
      minLength: 'Password must be at least 6 characters'
    },
    name: {
      required: 'Name is required',
      invalid: 'Please enter a valid name'
    },
    coordinate: {
      invalid: 'Please enter a valid coordinate',
      range: 'Coordinate out of valid range'
    }
  }
  
  return errors[field]?.[type] || 'Invalid input'
}

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * Login brute-force protection for METARDU.
 *
 * Distinction from rateLimit.ts:
 *   • This module tracks failed login attempts per email+IP and locks
 *     accounts after too many failures (5 failures → 30-min lockout).
 *   • rateLimit.ts handles general per-IP request quotas for API routes.
 * ─────────────────────────────────────────────────────────────────────────────
 *
 * Login Brute-Force Protection for METARDU
 *
 * Tracks failed login attempts per email+IP combination.
 * After MAX_FAILED_ATTEMPTS failures within the LOCKOUT_WINDOW,
 * the account is temporarily locked out.
 *
 * Uses Upstash Redis when UPSTASH_REDIS_REST_URL + UPSTASH_REDIS_REST_TOKEN
 * are set (production). Falls back to in-memory for local development.
 */

interface LoginAttempt {
  count: number
  firstAttemptAt: number
  lockedUntil: number | null
}

const MAX_FAILED_ATTEMPTS = 5
const LOCKOUT_WINDOW_MS = 15 * 60 * 1000   // 15 minutes — count failures within this window
const LOCKOUT_DURATION_MS = 30 * 60 * 1000  // 30 minutes — how long the lockout lasts
const REDIS_KEY_PREFIX = 'metardu_login:'
const REDIS_TTL_SEC = Math.ceil(LOCKOUT_WINDOW_MS / 1000) + Math.ceil(LOCKOUT_DURATION_MS / 1000)

// ─── In-memory fallback (local dev only) ─────────────────────────────────────

const attemptStore = new Map<string, LoginAttempt>()

// Periodic cleanup of expired entries (every 10 minutes)
setInterval(() => {
  const now = Date.now()
  const keysToDelete: string[] = []
  attemptStore.forEach((record, key) => {
    const lockoutExpired = !record.lockedUntil || record.lockedUntil < now
    const windowExpired = record.firstAttemptAt + LOCKOUT_WINDOW_MS < now
    if (lockoutExpired && windowExpired) {
      keysToDelete.push(key)
    }
  })
  keysToDelete.forEach(key => attemptStore.delete(key))
}, 10 * 60 * 1000)

function getKey(email: string, ip: string): string {
  return `${email.toLowerCase()}:${ip}`
}

// ─── Upstash Redis helpers ───────────────────────────────────────────────────

function hasUpstashConfig(): boolean {
  return !!(process.env.UPSTASH_REDIS_REST_URL && process.env.UPSTASH_REDIS_REST_TOKEN)
}

async function upstashGet(key: string): Promise<LoginAttempt | null> {
  const url = process.env.UPSTASH_REDIS_REST_URL!
  const token = process.env.UPSTASH_REDIS_REST_TOKEN!

  const res = await fetch(`${url}/GET`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify([key]),
  })

  const data = await res.json()
  const raw: string | null = data?.result
  if (!raw) return null
  try {
    return JSON.parse(raw) as LoginAttempt
  } catch {
    return null
  }
}

async function upstashSet(key: string, record: LoginAttempt): Promise<void> {
  const url = process.env.UPSTASH_REDIS_REST_URL!
  const token = process.env.UPSTASH_REDIS_REST_TOKEN!

  await fetch(`${url}/SET`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify([key, JSON.stringify(record), 'EX', REDIS_TTL_SEC]),
  })
}

async function upstashDel(key: string): Promise<void> {
  const url = process.env.UPSTASH_REDIS_REST_URL!
  const token = process.env.UPSTASH_REDIS_REST_TOKEN!

  await fetch(`${url}/DEL`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify([key]),
  })
}

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Check if a login attempt is allowed.
 * Returns { allowed, reason } — if not allowed, reason explains why.
 */
export async function checkLoginAllowed(email: string, ip: string): Promise<{ allowed: boolean; reason?: string; retryAfterMs?: number }> {
  const memKey = getKey(email, ip)
  const now = Date.now()

  if (hasUpstashConfig()) {
    const redisKey = `${REDIS_KEY_PREFIX}${memKey}`
    const record = await upstashGet(redisKey)

    if (!record) return { allowed: true }

    if (record.lockedUntil && record.lockedUntil > now) {
      const retryAfterMs = record.lockedUntil - now
      return {
        allowed: false,
        reason: `Account temporarily locked due to too many failed login attempts. Try again in ${Math.ceil(retryAfterMs / 60000)} minutes.`,
        retryAfterMs,
      }
    }

    if (record.firstAttemptAt + LOCKOUT_WINDOW_MS < now) return { allowed: true }

    return { allowed: true }
  }

  // In-memory fallback
  const record = attemptStore.get(memKey)
  if (!record) return { allowed: true }

  if (record.lockedUntil && record.lockedUntil > now) {
    const retryAfterMs = record.lockedUntil - now
    return {
      allowed: false,
      reason: `Account temporarily locked due to too many failed login attempts. Try again in ${Math.ceil(retryAfterMs / 60000)} minutes.`,
      retryAfterMs,
    }
  }

  if (record.firstAttemptAt + LOCKOUT_WINDOW_MS < now) {
    attemptStore.delete(memKey)
    return { allowed: true }
  }

  return { allowed: true }
}

/**
 * Record a failed login attempt.
 * After MAX_FAILED_ATTEMPTS, triggers a lockout.
 */
export async function recordFailedLogin(email: string, ip: string): Promise<void> {
  const memKey = getKey(email, ip)
  const now = Date.now()

  if (hasUpstashConfig()) {
    const redisKey = `${REDIS_KEY_PREFIX}${memKey}`
    const record = await upstashGet(redisKey)

    if (!record || record.firstAttemptAt + LOCKOUT_WINDOW_MS < now) {
      await upstashSet(redisKey, { count: 1, firstAttemptAt: now, lockedUntil: null })
      return
    }

    record.count += 1

    if (record.count >= MAX_FAILED_ATTEMPTS) {
      record.lockedUntil = now + LOCKOUT_DURATION_MS
      console.warn(`[loginLimiter] Account locked: ${email} from ${ip} after ${record.count} failed attempts. Locked for ${LOCKOUT_DURATION_MS / 60000} minutes.`)
    }

    await upstashSet(redisKey, record)
    return
  }

  // In-memory fallback
  const record = attemptStore.get(memKey)

  if (!record || record.firstAttemptAt + LOCKOUT_WINDOW_MS < now) {
    attemptStore.set(memKey, { count: 1, firstAttemptAt: now, lockedUntil: null })
    return
  }

  record.count += 1

  if (record.count >= MAX_FAILED_ATTEMPTS) {
    record.lockedUntil = now + LOCKOUT_DURATION_MS
    console.warn(`[loginLimiter] Account locked: ${email} from ${ip} after ${record.count} failed attempts. Locked for ${LOCKOUT_DURATION_MS / 60000} minutes.`)
  }
}

/**
 * Record a successful login — clears the failure count.
 */
export async function recordSuccessfulLogin(email: string, ip: string): Promise<void> {
  const memKey = getKey(email, ip)

  if (hasUpstashConfig()) {
    await upstashDel(`${REDIS_KEY_PREFIX}${memKey}`)
    return
  }

  attemptStore.delete(memKey)
}

/**
 * Get the current failure count for an email+IP (useful for warnings).
 */
export async function getFailedAttemptCount(email: string, ip: string): Promise<number> {
  const memKey = getKey(email, ip)
  const now = Date.now()

  if (hasUpstashConfig()) {
    const record = await upstashGet(`${REDIS_KEY_PREFIX}${memKey}`)
    if (!record) return 0
    if (record.firstAttemptAt + LOCKOUT_WINDOW_MS < now) return 0
    return record.count
  }

  const record = attemptStore.get(memKey)
  if (!record) return 0
  if (record.firstAttemptAt + LOCKOUT_WINDOW_MS < now) return 0
  return record.count
}

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * General-purpose rate limiter for METARDU API routes.
 *
 * Distinction from loginLimiter.ts:
 *   • This module enforces per-IP request quotas (e.g., "max 60 req/min").
 *   • loginLimiter.ts handles login brute-force protection — it tracks
 *     failed attempts per email+IP and issues account lockouts.
 * ─────────────────────────────────────────────────────────────────────────────
 *
 * Rate limiter for METARDU API routes.
 *
 * Uses Upstash Redis when UPSTASH_REDIS_REST_URL + UPSTASH_REDIS_REST_TOKEN
 * are set (required in production — serverless functions don't share memory).
 *
 * Falls back to in-memory for local development only.
 * To set up: https://upstash.com → create Redis DB → copy REST URL & token.
 * Add to Vercel: Settings → Environment Variables.
 */

// ─── Upstash implementation (production) ─────────────────────────────────────

async function upstashRateLimit(
  identifier: string,
  maxRequests: number,
  windowMs: number
): Promise<{ allowed: boolean; remaining: number }> {
  const url = process.env.UPSTASH_REDIS_REST_URL!
  const token = process.env.UPSTASH_REDIS_REST_TOKEN!
  const windowSec = Math.ceil(windowMs / 1000)
  const key = `metardu_rl:${identifier}`

  const res = await fetch(`${url}/pipeline`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify([
      ['INCR', key],
      ['EXPIRE', key, windowSec],
    ]),
  })

  const data = await res.json()
  const count: number = data[0]?.result ?? 1
  const remaining = Math.max(0, maxRequests - count)
  return { allowed: count <= maxRequests, remaining }
}

// ─── In-memory fallback (development only) ───────────────────────────────────
// WARNING: Resets on every cold start. Do NOT rely on this in production.

const _devStore = new Map<string, { count: number; resetTime: number }>()

function inMemoryRateLimit(
  identifier: string,
  maxRequests: number,
  windowMs: number
): { allowed: boolean; remaining: number } {
  const now = Date.now()
  const record = _devStore.get(identifier)

  if (!record || now > record.resetTime) {
    _devStore.set(identifier, { count: 1, resetTime: now + windowMs })
    return { allowed: true, remaining: maxRequests - 1 }
  }

  if (record.count >= maxRequests) {
    return { allowed: false, remaining: 0 }
  }

  record.count++
  return { allowed: true, remaining: maxRequests - record.count }
}

// ─── Public API ───────────────────────────────────────────────────────────────

// Rate limit categories — referenced by middleware.ts to pick the right
// quota per route family. Values are { max, windowMs }.
//
// AUDIT FIX (2026-07-05): These exports were referenced by middleware.ts
// since 2026-05-29 (commit 39158da) but never actually defined here. The
// middleware silently threw TypeError: Cannot read properties of
// undefined (reading api) on every API request, which was masked
// because:
//   1. tsconfig.json include only covered src/**/*.ts — middleware.ts
//      at the project root was never type-checked by tsc --noEmit.
//   2. next build uses webpack, which does not do strict typechecking.
//
// The fix: define the exports AND add middleware.ts to tsconfig include.
export type RateLimitCategory =
  | 'api'
  | 'auth'
  | 'submission'
  | 'upload'
  | 'mpesa'
  | 'export'

export const RATE_LIMITS: Record<RateLimitCategory, { max: number; windowMs: number }> = {
  // Default for all /api/* routes — 120 req/min per IP
  api: { max: 120, windowMs: 60_000 },
  // Auth routes (login, register, password reset) — tighter to slow brute force
  auth: { max: 20, windowMs: 60_000 },
  // Submission/NLIMS export — heavy work, 10/min
  submission: { max: 10, windowMs: 60_000 },
  // File uploads — 20/min (each upload is a separate request)
  upload: { max: 20, windowMs: 60_000 },
  // M-Pesa STK push initiation — 10/min (Safaricom also rate-limits server-side)
  mpesa: { max: 10, windowMs: 60_000 },
  // Export endpoints (DXF/Shapefile/PDF generation) — 30/min
  export: { max: 30, windowMs: 60_000 },
}

export async function rateLimit(
  identifier: string,
  maxRequests = 60,
  windowMs = 60000
): Promise<{ allowed: boolean; remaining: number }> {
  if (
    process.env.UPSTASH_REDIS_REST_URL &&
    process.env.UPSTASH_REDIS_REST_TOKEN
  ) {
    return await upstashRateLimit(identifier, maxRequests, windowMs)
  }

  if (process.env.NODE_ENV === 'production') {
    // ByteByteGo audit fix: in-memory rate limiting is NOT acceptable in production.
    // It silently fails in multi-instance deployments (each instance gets its own
    // counter, so attackers get N×the limit). Fail loudly instead.
    console.error(
      '[rate-limit] PRODUCTION ERROR: UPSTASH_REDIS_REST_URL and UPSTASH_REDIS_REST_TOKEN ' +
      'must be set in production. In-memory rate limiting is disabled. ' +
      'Set these env vars or set NODE_ENV=development for local dev.'
    )
    // Fail OPEN (allow the request) but log the error — failing closed would lock everyone out
    return Promise.resolve({ allowed: true, remaining: 0 })
  }

  return Promise.resolve(inMemoryRateLimit(identifier, maxRequests, windowMs))
}

export function getClientIdentifier(request: Request): string {
  const forwarded = request.headers.get('x-forwarded-for')
  return forwarded ? forwarded.split(',')[0].trim() : 'unknown'
}

/**
 * Sanitize HTML content using DOMPurify to prevent XSS attacks.
 * Safe for use with dangerouslySetInnerHTML.
 */
export function sanitizeHtml(dirty: string): string {
  // DOMPurify requires `window` — use synchronous client-side loading
  if (typeof window !== 'undefined') {
    const createDOMPurify = require('dompurify');
    const DOMPurify = createDOMPurify.default || createDOMPurify;
    return DOMPurify.sanitize(dirty, {
      ALLOWED_TAGS: [
        'div', 'span', 'p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
        'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td',
        'ul', 'ol', 'li', 'a', 'strong', 'em', 'b', 'i', 'u',
        'br', 'hr', 'img', 'svg', 'style', 'blockquote', 'pre', 'code',
        'sub', 'sup', 'section', 'article', 'header', 'footer', 'nav',
      ],
      ALLOWED_ATTR: [
        'class', 'id', 'style', 'href', 'src', 'alt', 'title',
        'width', 'height', 'viewBox', 'xmlns', 'd', 'fill', 'stroke',
        'stroke-width', 'transform', 'x', 'y', 'cx', 'cy', 'r',
        'border', 'cellpadding', 'cellspacing', 'colspan', 'rowspan',
        'text-align', 'font-size', 'font-weight', 'font-style',
        'background', 'color', 'padding', 'margin', 'vertical-align',
      ],
    });
  }
  // Server-side fallback: strip all tags
  return dirty.replace(/<[^>]*>/g, '');
}

export function sanitizeText(input: string): string {
  return input
    .trim()
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/[<>]/g, '')
    .substring(0, 500)
}

export function sanitizeNumber(
  input: string | number, 
  min?: number, 
  max?: number
): number | null {
  const num = parseFloat(String(input))
  if (isNaN(num)) return null
  if (min !== undefined && num < min) return null
  if (max !== undefined && num > max) return null
  return num
}

export function sanitizeCoordinate(
  easting: any, 
  northing: any
): { easting: number; northing: number } | null {
  const e = sanitizeNumber(easting, 100000, 900000)
  const n = sanitizeNumber(northing, 0, 10000000)
  if (e === null || n === null) return null
  return { easting: e, northing: n }
}

export function sanitizeBearing(input: string): string | null {
  const cleaned = String(input).trim().replace(/\s/g, '')
  const dmsMatch = cleaned.match(/^(\d{1,3})°?(\d{1,2})'?(\d{1,2}(?:\.\d+)?)"?$/)
  if (dmsMatch) {
    const degrees = parseInt(dmsMatch[1])
    const minutes = parseInt(dmsMatch[2])
    const seconds = parseFloat(dmsMatch[3])
    if (degrees >= 0 && degrees <= 360 && minutes < 60 && seconds < 60) {
      return `${degrees}°${minutes}'${seconds}"`
    }
  }
  const decMatch = cleaned.match(/^(\d+(?:\.\d+)?)$/)
  if (decMatch) {
    const dec = parseFloat(decMatch[1])
    if (dec >= 0 && dec <= 360) {
      return String(dec)
    }
  }
  return null
}

export function sanitizeEmail(input: string): string | null {
  const cleaned = sanitizeText(input).toLowerCase()
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
  if (emailRegex.test(cleaned)) {
    return cleaned
  }
  return null
}

export function sanitizePointName(input: string): string {
  return sanitizeText(input).replace(/[^a-zA-Z0-9_-]/g, '').substring(0, 50)
}

/**
 * Centralized input validation for all API routes.
 * Uses Zod schemas + custom sanitizers for defense in depth.
 *
 * Every API route should validate its input through this module
 * rather than trusting raw request bodies/params directly.
 */
import { z } from 'zod'

// ─── Common reusable schemas ──────────────────────────────────────────────────

export const schemas = {
  /** UUID v4 validation */
  uuid: z.string().uuid(),

  /** RFC 5321 compliant email (max 254 chars) */
  email: z.string().email().max(254),

  /** Project / submission name */
  projectName: z.string().min(1).max(200).trim(),

  /** Kenya county code: 3-digit string */
  countyCode: z.string().regex(/^\d{3}$/).length(3),

  /** Land parcel number — free-form, max 50 chars */
  parcelNumber: z.string().max(50).trim(),

  /** Strictly positive number (> 0) */
  positiveNumber: z.number().positive(),

  /** Non-negative number (>= 0) */
  nonNegativeNumber: z.number().nonnegative(),

  /** Geographic coordinate: longitude or latitude range */
  coordinate: z.number().min(-180).max(180),

  /** Surveying bearing: 0–360 degrees */
  bearing: z.number().min(0).max(360),

  /** Pagination controls with sensible defaults */
  pagination: z.object({
    page: z.coerce.number().int().positive().default(1),
    perPage: z.coerce.number().int().positive().max(500).default(50),
    sortBy: z.string().optional(),
    sortOrder: z.enum(['asc', 'desc']).default('asc'),
  }),

  /** ISO 8601 date range filter */
  dateRange: z.object({
    startDate: z.string().datetime().optional(),
    endDate: z.string().datetime().optional(),
  }),
} as const

// ─── ValidationError ──────────────────────────────────────────────────────────

/**
 * Thrown by `validateInput` when Zod parsing fails.
 * Carries structured field-level details for the API response.
 */
export class ValidationError extends Error {
  details: Array<{ field: string; message: string }>

  constructor(
    message: string,
    details?: Array<{ field: string; message: string }>
  ) {
    super(message)
    this.name = 'ValidationError'
    this.details = details || []
  }
}

// ─── validateInput ────────────────────────────────────────────────────────────

/**
 * Validate unknown input against a Zod schema.
 *
 * @throws {ValidationError} with field-level details on the first failure.
 * @returns The fully typed & parsed output of the schema.
 */
export function validateInput<T>(
  schema: z.ZodSchema<T>,
  input: unknown
): T {
  const result = schema.safeParse(input)
  if (!result.success) {
    const firstError = result.error.issues[0]
    throw new ValidationError(
      firstError?.message || 'Invalid input',
      result.error.issues.map((i) => ({
        field: i.path.join('.'),
        message: i.message,
      }))
    )
  }
  return result.data
}

// ─── sanitizeObject ───────────────────────────────────────────────────────────

/**
 * Recursively sanitize all string values in a plain object.
 *
 * Strips:
 *  - `<script>` tags (including content between open/close)
 *  - HTML event-handler attributes (`onclick=`, `onerror=`, …)
 *  - Null bytes (`\0`) which can cause downstream issues
 *  - Leading/trailing whitespace
 *
 * Non-string values (numbers, booleans, nested objects/arrays) are
 * recursed into without modification.
 *
 * @returns A new sanitized object — the input is never mutated.
 */
export function sanitizeObject<T extends Record<string, unknown>>(
  obj: T
): T {
  if (obj === null || typeof obj !== 'object') {
    return obj
  }

  // Handle arrays
  if (Array.isArray(obj)) {
    return obj.map((item) =>
      typeof item === 'object' && item !== null && !Array.isArray(item)
        ? sanitizeObject(item as Record<string, unknown>)
        : typeof item === 'string'
          ? sanitizeString(item)
          : item
    ) as unknown as T
  }

  const sanitized: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(obj)) {
    if (value === null || value === undefined) {
      sanitized[key] = value
    } else if (typeof value === 'string') {
      sanitized[key] = sanitizeString(value)
    } else if (Array.isArray(value)) {
      sanitized[key] = value.map((item) =>
        typeof item === 'object' && item !== null && !Array.isArray(item)
          ? sanitizeObject(item as Record<string, unknown>)
          : typeof item === 'string'
            ? sanitizeString(item)
            : item
      )
    } else if (typeof value === 'object') {
      sanitized[key] = sanitizeObject(value as Record<string, unknown>)
    } else {
      sanitized[key] = value
    }
  }
  return sanitized as T
}

/** Internal: sanitize a single string value. */
function sanitizeString(str: string): string {
  return str
    .replace(/\0/g, '')                                           // Remove null bytes
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '') // Strip script tags + content
    .replace(/<\s*\/?script[^>]*>/gi, '')                          // Catch edge-case broken tags
    .replace(/\bon\w+\s*=\s*[^>]*>/gi, '')                        // Strip inline event handlers
    .replace(/javascript\s*:/gi, '')                              // Strip javascript: URIs
    .trim()
}

// ─── CSP nonce generator ──────────────────────────────────────────────────────

/**
 * Generate a cryptographically random nonce for Content-Security-Policy headers.
 *
 * Usage in middleware:
 *   const nonce = generateNonce()
 *   response.headers.set('x-nonce', nonce)
 *
 * In layout / page `<head>`:
 *   <script nonce={headers.get('x-nonce')} ...>
 */
export function generateNonce(): string {
  const array = new Uint8Array(16)
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    crypto.getRandomValues(array)
  } else {
    // Fallback — only used in environments without Web Crypto API
    for (let i = 0; i < 16; i++) array[i] = Math.floor(Math.random() * 256)
  }
  return Buffer.from(array).toString('base64')
}

/**
 * METARDU Instrument Serial Connection Manager
 * =============================================
 * Manages direct serial connections to surveying instruments
 * via the Web Serial API (Chrome/Edge desktop browsers).
 *
 * Supported instruments:
 * - Leica TS16 / TS60 / Viva series (GSI format, 9600-115200 baud)
 * - Trimble R10 / R12i / S7 (SSV/NMEA, 9600-38400 baud)
 * - Topcon OS / DS series (TOPCON, 9600 baud)
 * - Sokkia CX / FX series (SDR, 9600-115200 baud)
