}

// ─── Serial Connection Manager ──────────────────────────────────────────

export class InstrumentSerialConnection {
  private port: SerialPort | null = null
  private reader: ReadableStreamDefaultReader<Uint8Array> | null = null
  private writer: WritableStreamDefaultWriter<Uint8Array> | null = null
  private parser: InstrumentStreamParser | null = null
  private readLoopActive = false
  private reconnectAttempts = 0
  private maxReconnectAttempts = 3
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null
  private healthCheckTimer: ReturnType<typeof setInterval> | null = null

  // State
  private _status: ConnectionStatus = 'disconnected'
  private _config: SerialConnectionConfig
  private _instrumentInfo: InstrumentInfo | null = null
  private _stats: ConnectionStats | null = null

  // Callbacks
  private onDataCallbacks: Set<DataCallback> = new Set()
  private onStatusCallbacks: Set<StatusCallback> = new Set()
  private onErrorCallbacks: Set<ErrorCallback> = new Set()
  
  // Capacitor Native
  private nativePortId: string | null = null
  private nativeDataListener: any = null

  constructor(config: Partial<SerialConnectionConfig> = {}) {
    this._config = { ...DEFAULT_CONFIG, ...config }
  }

  // ─── Getters ─────────────────────────────────────────────────────────

  get status(): ConnectionStatus { return this._status }
  get config(): SerialConnectionConfig { return this._config }
  get instrumentInfo(): InstrumentInfo | null { return this._instrumentInfo }
  get stats(): ConnectionStats | null { return this._stats }
  get isConnected(): boolean {
    return this._status === 'connected' || this._status === 'streaming'
  }

  // ─── Event Handlers ─────────────────────────────────────────────────

  onData(callback: DataCallback): () => void {
    this.onDataCallbacks.add(callback)
    return () => this.onDataCallbacks.delete(callback)
  }

  onStatus(callback: StatusCallback): () => void {
    this.onStatusCallbacks.add(callback)
    return () => this.onStatusCallbacks.delete(callback)
  }

  onError(callback: ErrorCallback): () => void {
    this.onErrorCallbacks.add(callback)
    return () => this.onErrorCallbacks.delete(callback)
  }

  // ─── Connection Lifecycle ───────────────────────────────────────────

  async connect(): Promise<void> {
    this.setStatus('connecting')

    try {
      if (Capacitor.isNativePlatform()) {
        // --- NATIVE ANDROID MODE ---
        const devicesResult = await UsbSerial.listDevices()
        const devices = devicesResult.devices
        
        if (!devices || devices.length === 0) {
          throw new Error('No USB serial devices found. Please connect an instrument via OTG.')
        }

        const deviceId = devices[0].deviceId
        await UsbSerial.requestPermission({ deviceId })

        const openResult = await UsbSerial.open({ deviceId })
        this.nativePortId = openResult.portId

        // Note: The plugin types use DataBits, StopBits, Parity enums
        // For simplicity we cast our numbers to any/expected types if needed
        await UsbSerial.setParameters({
          portId: this.nativePortId,
          baudRate: this._config.baudRate,
          dataBits: this._config.dataBits as any,
          stopBits: this._config.stopBits as any,
          parity: (this._config.parity === 'none' ? 0 : this._config.parity === 'odd' ? 1 : 2) as any,
        })

        // Ensure DTR/RTS is active
        await UsbSerial.setDTR({ portId: this.nativePortId, value: true }).catch(() => {})
        await UsbSerial.setRTS({ portId: this.nativePortId, value: true }).catch(() => {})

        this.parser = createStreamParser()
        this._stats = {
          bytesReceived: 0,
          messagesParsed: 0,
          errors: 0,
          connectedAt: new Date(),
          lastDataAt: new Date(),
        }

        this.setStatus('connected')
        this.reconnectAttempts = 0
        this.startHealthCheck()
        
        // Listen for data natively
        this.nativeDataListener = await UsbSerial.addListener('data', (data: any) => {
          if (!this.parser || !this.readLoopActive) return
          // Native plugin returns base64
          const text = atob(data.data)
          
          if (this._stats) {
            this._stats.bytesReceived += text.length
            this._stats.lastDataAt = new Date()
          }
          
          const results = this.parser.feed(text)
          for (const result of results) {
            this.processParsedResult(result)
          }
        })

        await UsbSerial.startReading({ portId: this.nativePortId })
        this.readLoopActive = true
        this.setStatus('streaming')
        
      } else {
        // --- WEB BROWSER MODE ---
        if (!('serial' in navigator)) {
          throw new Error('Web Serial API is not supported in this browser. Please use Chrome or Edge.')
        }

        const serial = (navigator as any).serial as Serial
        this.port = await serial.requestPort()

        await this.port.open({
          baudRate: this._config.baudRate,
          dataBits: this._config.dataBits,
          stopBits: this._config.stopBits,
          parity: this._config.parity,
          flowControl: this._config.flowControl,
        })

        this.parser = createStreamParser()
        this._stats = {
          bytesReceived: 0,
          messagesParsed: 0,
          errors: 0,
          connectedAt: new Date(),
          lastDataAt: new Date(),
        }

        if (this.port.writable) {
          this.writer = this.port.writable.getWriter()
        }

        this.setStatus('connected')
        this.reconnectAttempts = 0
        this.startReadLoop()
        this.startHealthCheck()
      }

    } catch (error) {
      if ((error as Error).name === 'NotFoundError') {
        // User cancelled port selection
        this.setStatus('disconnected')
        return
      }
      this.setStatus('error')
      const err = error instanceof Error ? error : new Error(String(error))
      this.emitError(err)
      throw err
    }
  }

  /**
   * Disconnect from the instrument
   */
  async disconnect(): Promise<void> {
    this.stopReadLoop()
    this.stopHealthCheck()
    this.stopReconnect()

    try {
      if (Capacitor.isNativePlatform() && this.nativePortId) {
        if (this.nativeDataListener) {
          await this.nativeDataListener.remove().catch(() => {})
          this.nativeDataListener = null
        }
        await UsbSerial.stopReading({ portId: this.nativePortId }).catch(() => {})
        await UsbSerial.close({ portId: this.nativePortId }).catch(() => {})
        this.nativePortId = null
      } else {
        if (this.writer) {
          await this.writer.close().catch(() => {})
          this.writer = null
        }
        if (this.reader) {
          await this.reader.cancel().catch(() => {})
          this.reader = null
        }
        if (this.port) {
          await this.port.close().catch(() => {})
          this.port = null
        }
      }
    } catch {
      // Ignore close errors
    }

    this._instrumentInfo = null
    this.parser = null
    this.setStatus('disconnected')
  }

  /**
   * Update connection configuration (must reconnect)
   */
  updateConfig(config: Partial<SerialConnectionConfig>): void {
    this._config = { ...this._config, ...config }
  }

  /**
   * Connect using a preset instrument configuration
   */
  async connectWithPreset(presetKey: string): Promise<void> {
    const preset = INSTRUMENT_PRESETS[presetKey]
    if (!preset) throw new Error(`Unknown instrument preset: ${presetKey}`)
    this._config = { ...preset.config }
    await this.connect()
  }

  // ─── Data Transmission ─────────────────────────────────────────────

  async send(data: Uint8Array): Promise<void> {
    if (Capacitor.isNativePlatform()) {
      if (!this.nativePortId) throw new Error('Not connected natively')
      const b64 = btoa(String.fromCharCode.apply(null, Array.from(data)))
      await UsbSerial.write({ portId: this.nativePortId, data: b64 })
    } else {
      if (!this.writer) throw new Error('Not connected')
      await this.writer.write(data)
    }
  }

  /**
   * Send a string command to the instrument
   */
  async sendCommand(command: string): Promise<void> {
    const encoder = new TextEncoder()
    await this.send(encoder.encode(command + '\r\n'))
  }

  /**
   * Request measurement from Leica total station (legacy convenience method)
   */
  async requestLeicaMeasurement(): Promise<void> {
    // Standard Leica GSI measurement trigger commands
    const commands = [
      '%R1Q,5002:1,0,0,0,0\r\n',  // Request distance + angle
      '%R1Q,2008:1,0\r\n',         // Trigger measurement
    ]
    for (const cmd of commands) {
      await this.sendCommand(cmd)
    }
  }

  /**
   * Send a brand-specific instrument command
   * Uses the multi-brand command protocol system (Leica, Topcon, Trimble, Sokkia)
   *
   * @example
   * // Measure with a Topcon total station
   * await connection.sendInstrumentCommand('topcon', 'measureAndRecord')
   *
   * // Set prism target on a Trimble S7
   * await connection.sendInstrumentCommand('trimble', 'setPrismTarget', 0)
   *
   * // Set station on a Sokkia CX
   * await connection.sendInstrumentCommand('sokkia', 'setStation', stationSetup)
   */
  async sendInstrumentCommand(
    brand: 'leica' | 'topcon' | 'trimble' | 'sokkia',
    commandType: string,
    ...args: unknown[]
  ): Promise<void> {
    // Dynamic import to avoid circular dependency
    const { getInstrumentCommand } = await import('./instrumentCommands')
    const cmd = getInstrumentCommand(brand, commandType as any, ...args)
    await this.sendCommand(cmd.command)
  }

  /**
   * Get the brand for the currently connected instrument based on preset
   */
  getCurrentBrand(): 'leica' | 'topcon' | 'trimble' | 'sokkia' | null {
    // Try to determine from detected protocol and preset
    if (this._instrumentInfo) {
      if (this._instrumentInfo.manufacturer?.toLowerCase().includes('leica')) return 'leica'
      if (this._instrumentInfo.manufacturer?.toLowerCase().includes('topcon')) return 'topcon'
      if (this._instrumentInfo.manufacturer?.toLowerCase().includes('trimble')) return 'trimble'
      if (this._instrumentInfo.manufacturer?.toLowerCase().includes('sokkia')) return 'sokkia'
    }
    return null
  }

  // ─── Private Methods ───────────────────────────────────────────────

  private setStatus(status: ConnectionStatus) {
    this._status = status
    this.onStatusCallbacks.forEach(cb => {
      try { cb(status) } catch { /* ignore callback errors */ }
    })
  }

  private emitError(error: Error) {
    this.onErrorCallbacks.forEach(cb => {
      try { cb(error) } catch { /* ignore callback errors */ }
    })
  }

  private emitData(data: ParsedInstrumentData) {
    this.onDataCallbacks.forEach(cb => {
      try { cb(data) } catch { /* ignore callback errors */ }
    })
  }

  private async startReadLoop(): Promise<void> {
    if (!this.port?.readable || this.readLoopActive) return
    this.readLoopActive = true

    this.setStatus('streaming')

    while (this.readLoopActive && this.port.readable) {
      try {
        this.reader = this.port.readable.getReader()

        while (this.readLoopActive && this.reader) {
          const { value, done } = await this.reader.read()

          if (done) break
          if (!value || !this.parser) continue

          // Update stats
          if (this._stats) {
            this._stats.bytesReceived += value.length
            this._stats.lastDataAt = new Date()
          }

          // Decode bytes to string and feed to parser
          const decoder = new TextDecoder()
          const text = decoder.decode(value, { stream: true })
          const results = this.parser.feed(text)

          // Emit parsed data
          for (const result of results) {
            this.processParsedResult(result)
          }
        }
      } catch (error) {
        if (this.readLoopActive) {
          if (this._stats) { this._stats.errors++ }

          if (this.reconnectAttempts < this.maxReconnectAttempts) {
            this.setStatus('reconnecting')
            this.reconnectAttempts++
            this.scheduleReconnect()
          } else {
            this.setStatus('error')
            this.emitError(error instanceof Error ? error : new Error(String(error)))
          }
        }
      } finally {
        if (this.reader) {
          try { this.reader.releaseLock() } catch { /* ignore */ }
          this.reader = null
        }
      }
    }

    this.readLoopActive = false
  }

  private stopReadLoop() {
    this.readLoopActive = false
    if (this.reader) {
      try { this.reader.cancel() } catch { /* ignore */ }
      try { this.reader.releaseLock() } catch { /* ignore */ }
      this.reader = null
    }
  }

  private scheduleReconnect() {
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer)
    const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 10000)

    this.reconnectTimer = setTimeout(async () => {
      try {
        // Try to reopen the port
        if (this.port) {
          await this.port.open({
            baudRate: this._config.baudRate,
            dataBits: this._config.dataBits,
            stopBits: this._config.stopBits,
            parity: this._config.parity,
            flowControl: this._config.flowControl,
          })

          if (this.port.writable) {
            this.writer = this.port.writable.getWriter()
          }

          this.parser = createStreamParser()
          this.startReadLoop()
        }
      } catch {
        this.setStatus('error')
      }
    }, delay)
  }

  private stopReconnect() {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
  }

  private startHealthCheck() {
    this.stopHealthCheck()
    this.healthCheckTimer = setInterval(() => {
      if (this._stats) {
        const timeSinceData = Date.now() - this._stats.lastDataAt.getTime()
        // If no data for 30 seconds, consider connection stale
        if (timeSinceData > 30000 && this._status === 'streaming') {
          this._stats.errors++
        }
      }
    }, 10000)
  }

  private stopHealthCheck() {
    if (this.healthCheckTimer) {
      clearInterval(this.healthCheckTimer)
      this.healthCheckTimer = null
    }
  }

  private processParsedResult(result: ParsedInstrumentData) {
    if (result.type !== 'unknown') {
      if (this._stats) this._stats.messagesParsed++
      this.emitData(result)

      if (!this._instrumentInfo) {
        this._instrumentInfo = {
          manufacturer: 'Unknown',
          protocol: result.type,
          detectedAt: new Date(),
        }

        if (result.type === 'gsi') {
          this._instrumentInfo.manufacturer = 'Leica / Leica Geosystems'
        } else if (result.type === 'nmea') {
          this._instrumentInfo.manufacturer = 'GNSS Receiver'
        } else if (result.type === 'topcon') {
          this._instrumentInfo.manufacturer = 'Topcon'
        } else if (result.type === 'trimble') {
          this._instrumentInfo.manufacturer = 'Trimble'
        } else if (result.type === 'sokkia') {
          this._instrumentInfo.manufacturer = 'Sokkia'
        }
      }
    }
  }
}

// ─── Helper: Check Web Serial Support ───────────────────────────────────

export function isSerialSupported(): boolean {
  return typeof navigator !== 'undefined' && 'serial' in navigator
}

// ─── Helper: Get Available Ports (if previously granted) ─────────────────

export async function getPreviouslyAuthorizedPorts(): Promise<SerialPort[]> {
  if (!isSerialSupported()) return []
  try {
    return await ((navigator as any).serial as Serial).getPorts()
  } catch {
    return []
  }
}

/**
 * METARDU Total Station Command Protocols
 * ========================================
 * Command sets for controlling total stations from multiple manufacturers:
 *
 * - Leica: GSI-8/GSI-16 + GeoCOM (ASCII) commands
 * - Topcon: TOPCON ASCII commands (RC-232 / ExtLink)
 * - Trimble: Trimble Communications Protocol (TCP) + SSV commands
 * - Sokkia: SDR33 command set
 *
 * Each brand has its own command syntax for:
 * - Triggering measurements (angle + distance)
 * - Setting target (prism/prismless)
 * - Changing face (Face I / Face II)
 * - Setting instrument station
 * - Starting/stopping tracking mode
 * - Recording points
 */

export type InstrumentBrand = 'leica' | 'topcon' | 'trimble' | 'sokkia';

export interface MeasurementCommand {
  /** Human-readable description */
  description: string;
  /** Raw command string to send (with CRLF appended by sendCommand) */
  command: string;
  /** Expected response pattern (regex) */
  responsePattern?: RegExp;
  /** Timeout in ms */
  timeout?: number;
}

export interface StationSetup {
  pointName: string;
  easting: number;
  northing: number;
  elevation: number;
  instrumentHeight: number;
  backsightPointName?: string;
  backsightEasting?: number;
  backsightNorthing?: number;
  backsightElevation?: number;
}

// ═══════════════════════════════════════════════════════════════════════
// LEICA — GeoCOM ASCII + GSI Commands
// ═══════════════════════════════════════════════════════════════════════

export const LEICA_COMMANDS = {
  /**
   * Trigger distance + angle measurement (standard)
   * GeoCOM: %R1Q,5002:1 — Measure and Record
   */
  measureAndRecord: (): MeasurementCommand => ({
    description: 'Measure and record (Leica GeoCOM)',
    command: '%R1Q,5002:1,0,0,0,0',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 30000,
  }),

  /**
   * Measure distance only (no recording)
   * GeoCOM: %R1Q,2008:1 — Measure Distance
   */
  measureDistance: (): MeasurementCommand => ({
    description: 'Measure distance only (Leica GeoCOM)',
    command: '%R1Q,2008:1,0',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 15000,
  }),

  /**
   * Get current angle readings
   * GeoCOM: %R1Q,2003 — Get Angle
   */
  getAngles: (): MeasurementCommand => ({
    description: 'Get current angles (Leica GeoCOM)',
    command: '%R1Q,2003:',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 5000,
  }),

  /**
   * Get coordinate of target point
   * GeoCOM: %R1Q,5003 — Get Coordinate
   */
  getCoordinate: (): MeasurementCommand => ({
    description: 'Get target coordinate (Leica GeoCOM)',
    command: '%R1Q,5003:1',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 15000,
  }),

  /**
   * Set target type to prism
   * GeoCOM: %R1Q,2022:1,0 — Set Prism Target
   */
  setPrismTarget: (prismConstant: number = 0): MeasurementCommand => ({
    description: 'Set prism target (Leica GeoCOM)',
    command: `%R1Q,2022:1,0,${prismConstant}`,
    responsePattern: /^%R1P,0,0:0/,
    timeout: 3000,
  }),

  /**
   * Set target type to reflectorless (RL)
   * GeoCOM: %R1Q,2022:0,0 — Set RL Target
   */
  setRLTarget: (): MeasurementCommand => ({
    description: 'Set reflectorless target (Leica GeoCOM)',
    command: '%R1Q,2022:0,0,0',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 3000,
  }),

  /**
   * Change to Face I (normal)
   * GeoCOM: %R1Q,2021:0 — Set Face I
   */
  setFaceI: (): MeasurementCommand => ({
    description: 'Set Face I (Leica GeoCOM)',
    command: '%R1Q,2021:0',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 3000,
  }),

  /**
   * Change to Face II
   * GeoCOM: %R1Q,2021:1 — Set Face II
   */
  setFaceII: (): MeasurementCommand => ({
    description: 'Set Face II (Leica GeoCOM)',
    command: '%R1Q,2021:1',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 3000,
  }),

  /**
   * Set instrument station (orientation)
   * GeoCOM: %R1Q,2023 — Set Station
   */
  setStation: (setup: StationSetup): MeasurementCommand => ({
    description: 'Set instrument station (Leica GeoCOM)',
    command: `%R1Q,2023:${setup.easting},${setup.northing},${setup.elevation},${setup.instrumentHeight}`,
    responsePattern: /^%R1P,0,0:0/,
    timeout: 5000,
  }),

  /**
   * Set orientation to backsight
   * GeoCOM: %R1Q,2024 — Set Orientation
   */
  setOrientation: (hzAngle: number): MeasurementCommand => ({
    description: 'Set orientation angle (Leica GeoCOM)',
    command: `%R1Q,2024:${hzAngle}`,
    responsePattern: /^%R1P,0,0:0/,
    timeout: 5000,
  }),

  /**
   * Start tracking mode (continuous measurement)
   * GeoCOM: %R1Q,2025:1 — Start Tracking
   */
  startTracking: (): MeasurementCommand => ({
    description: 'Start tracking mode (Leica GeoCOM)',
    command: '%R1Q,2025:1',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 5000,
  }),

  /**
   * Stop tracking mode
   * GeoCOM: %R1Q,2025:0 — Stop Tracking
   */
  stopTracking: (): MeasurementCommand => ({
    description: 'Stop tracking mode (Leica GeoCOM)',
    command: '%R1Q,2025:0',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 5000,
  }),

  /**
   * GSI command: Measure point and output GSI block
   * Works on older Leica instruments (TC, TCR, TPS series)
   */
  gsiMeasure: (pointNumber: number): MeasurementCommand => ({
    description: 'GSI measure point (Leica legacy)',
    command: `W${pointNumber.toString().padStart(4, '0')}`,
    responsePattern: /^W/,
    timeout: 15000,
  }),

  /**
   * Get instrument info
   * GeoCOM: %R1Q,5001 — Get Instrument Name
   */
  getInstrumentInfo: (): MeasurementCommand => ({
    description: 'Get instrument name (Leica GeoCOM)',
    command: '%R1Q,5001:',
    responsePattern: /^%R1P,0,0:0/,
    timeout: 5000,
  }),
};

// ═══════════════════════════════════════════════════════════════════════
// TOPCON — ASCII Command Protocol (RC-232 / ExtLink)
// ═══════════════════════════════════════════════════════════════════════

export const TOPCON_COMMANDS = {
  /**
   * Measure angle and distance
   * Command: MD<mode> — Measure Distance
   * Mode: 0=stop, 1=repeat, 2=single, 3=average, 4=tracking
   */
  measureAndRecord: (): MeasurementCommand => ({
    description: 'Measure angle + distance (Topcon)',
    command: 'MD2',
    responsePattern: /^MD/,
    timeout: 30000,
  }),

  /**
   * Single distance measurement
   */
  measureDistance: (): MeasurementCommand => ({
    description: 'Single distance measurement (Topcon)',
    command: 'MD2',
    responsePattern: /^MD/,
    timeout: 15000,
  }),

  /**
   * Get angle readings
   * Command: VA — Read Vertical/Horizonta angle
   */
  getAngles: (): MeasurementCommand => ({
    description: 'Read angles (Topcon)',
    command: 'VA',
    responsePattern: /^VA/,
    timeout: 5000,
  }),

  /**
   * Get coordinate of target
   * Command: CO — Coordinate Output
   */
  getCoordinate: (): MeasurementCommand => ({
    description: 'Get coordinate (Topcon)',
    command: 'CO',
    responsePattern: /^CO/,
    timeout: 15000,
  }),

  /**
   * Set target type to prism
   * Command: RM,1 — Reflector Mode: Prism
   */
  setPrismTarget: (prismConstant: number = 0): MeasurementCommand => ({
    description: 'Set prism target (Topcon)',
    command: `RM,1,${prismConstant}`,
    responsePattern: /^RM/,
    timeout: 3000,
  }),

  /**
   * Set target type to reflectorless (RL)
   * Command: RM,0 — Reflector Mode: Non-Prism
   */
  setRLTarget: (): MeasurementCommand => ({
    description: 'Set reflectorless target (Topcon)',
    command: 'RM,0,0',
    responsePattern: /^RM/,
    timeout: 3000,
  }),

  /**
   * Change to Face I
   * Command: PI — Position Index (Face I)
   */
  setFaceI: (): MeasurementCommand => ({
    description: 'Set Face I (Topcon)',
    command: 'PI',
    responsePattern: /^PI/,
    timeout: 3000,
  }),

  /**
   * Change to Face II
   * Command: PII — Position Index (Face II)
   */
  setFaceII: (): MeasurementCommand => ({
    description: 'Set Face II (Topcon)',
    command: 'PII',
    responsePattern: /^PII/,
    timeout: 3000,
  }),

  /**
   * Set instrument station
   * Command: SP,<easting>,<northing>,<elevation>,<IH>
   */
  setStation: (setup: StationSetup): MeasurementCommand => ({
    description: 'Set instrument station (Topcon)',
    command: `SP,${setup.easting},${setup.northing},${setup.elevation},${setup.instrumentHeight}`,
    responsePattern: /^SP/,
    timeout: 5000,
  }),

  /**
   * Set orientation / backsight
   * Command: SO,<azimuth> — Set Orientation
   */
  setOrientation: (hzAngle: number): MeasurementCommand => ({
    description: 'Set orientation angle (Topcon)',
    command: `SO,${hzAngle.toFixed(6)}`,
    responsePattern: /^SO/,
    timeout: 5000,
  }),

  /**
   * Start tracking mode
   * Command: MD4 — Tracking measurement
   */
  startTracking: (): MeasurementCommand => ({
    description: 'Start tracking mode (Topcon)',
    command: 'MD4',
    responsePattern: /^MD/,
    timeout: 5000,
  }),

  /**
   * Stop tracking mode
   * Command: MD0 — Stop measurement
   */
  stopTracking: (): MeasurementCommand => ({
    description: 'Stop tracking mode (Topcon)',
