// ── Helper: Fetch surveyor profile data from the project owner ────────────
async function fetchSurveyorProfile(projectId: string): Promise<{
  surveyorName: string;
  iskNumber: string;
  firmName: string;
  referenceNumber: string;
}> {
  try {
    const projRes = await db.query(
      'SELECT user_id, surveyor_name, surveyor_license FROM projects WHERE id = $1',
      [projectId]
    );
    const proj = projRes.rows[0];

    // First try project-level surveyor fields
    if (proj?.surveyor_name) {
      return {
        surveyorName: proj.surveyor_name || '',
        iskNumber: proj.surveyor_license || '',
        firmName: '',
        referenceNumber: '',
      };
    }

    // Fall back to surveyor profile (correct table: surveyor_profiles, not profiles)
    if (proj?.user_id) {
      const userRes = await db.query(
        'SELECT full_name, isk_number, firm_name FROM surveyor_profiles WHERE user_id = $1',
        [proj.user_id]
      );
      const user = userRes.rows[0];
      if (user) {
        return {
          surveyorName: user.full_name || '',
          iskNumber: user.isk_number || '',
          firmName: user.firm_name || '',
          referenceNumber: '',
        };
      }
    }
  } catch (err) {
    console.warn('[assembleDocument] Failed to fetch surveyor profile:', err);
  }
  return { surveyorName: '', iskNumber: '', firmName: '', referenceNumber: '' };
}

// ── Helper: Parse a DMS bearing string like "045°30'15\"" to decimal degrees ──
function parseDMSBearing(dms: string): number {
  if (!dms || typeof dms !== 'string') return 0;
  const match = dms.match(/(\d+)[°\s]*(\d+)?['\s]*(\d+\.?\d*)?["\s]*/);
  if (match) {
    const d = parseFloat(match[1]) || 0;
    const m = parseFloat(match[2]) || 0;
    const s = parseFloat(match[3]) || 0;
    return d + m / 60 + s / 3600;
  }
  const num = parseFloat(dms);
  return isNaN(num) ? 0 : num;
}

// ── Helper: Compute departure/latitude/correction from traverse data ──────
function computeTraverseAdjustment(
  stations: Array<{ station: string; easting: number; northing: number }>,
  bearingSchedule: Array<{ from: string; to: string; bearing: string; distance: string }>,
  misclosureMm: number,
  perimeterM: number,
): Array<{
  label: string;
  observedBearing: number;
  observedDistance: number;
  easting: number;
  northing: number;
  adjustedEasting: number;
  adjustedNorthing: number;
  departureRaw: number;
  latitudeRaw: number;
  departureCorrection: number;
  latitudeCorrection: number;
}> {
  // Compute misclosure in E and N from the adjusted vs. raw coordinates
  const n = stations.length;
  if (n < 2) return [];

  // Total misclosure (assumes Bowditch adjustment distributes proportionally)
  const closureE = (misclosureMm / 1000); // This is the linear misclosure magnitude
  // For Bowditch, correction is proportional to leg distance / perimeter
  const ratio = perimeterM > 0 ? closureE / perimeterM : 0;

  let cumDist = 0;
  return stations.map((st, i) => {
    const leg = bearingSchedule[i];
    if (!leg) {
      return {
        label: st.station,
        observedBearing: 0,
        observedDistance: 0,
        easting: st.easting,
        northing: st.northing,
        adjustedEasting: st.easting,
        adjustedNorthing: st.northing,
        departureRaw: 0,
        latitudeRaw: 0,
        departureCorrection: 0,
        latitudeCorrection: 0,
      };
    }

    const dist = parseFloat(leg.distance) || 0;
    const bearing = parseDMSBearing(leg.bearing);
    const bearingRad = (bearing * Math.PI) / 180;
    const departureRaw = dist * Math.sin(bearingRad);
    const latitudeRaw = dist * Math.cos(bearingRad);

    // Bowditch correction proportional to cumulative distance
    cumDist += dist;
    const correctionFraction = perimeterM > 0 ? cumDist / perimeterM : 0;
    const departureCorrection = -(closureE * correctionFraction * (departureRaw / (Math.abs(departureRaw) + Math.abs(latitudeRaw) + 1e-10)));
    const latitudeCorrection = -(closureE * correctionFraction * (latitudeRaw / (Math.abs(departureRaw) + Math.abs(latitudeRaw) + 1e-10)));

    return {
      label: st.station,
      observedBearing: bearing,
      observedDistance: dist,
      easting: st.easting,
      northing: st.northing,
      adjustedEasting: st.easting,
      adjustedNorthing: st.northing,
      departureRaw,
      latitudeRaw,
      departureCorrection,
      latitudeCorrection,
    };
  });
}

/**
 * Load pre-adjusted traverse coordinates from the database.
 * Delegates to the shared loadPreAdjustedFromDB() from deedPlanGeometry.ts
 * which now includes field book beacon enrichment.
 */

interface GenerateDocumentInput {
  projectId: string;
  documentId: string;
  surveyType: string;
  /** userId from session — for tamper-evident audit chain attribution */
  userId?: string;
}

interface GenerateDocumentResult {
  fileUrl: string;
}

export async function generateDocument(
  input: GenerateDocumentInput
): Promise<GenerateDocumentResult> {
  const { projectId, documentId, surveyType, userId } = input;

  let buffer: Buffer;
  let fileName: string;
  let mimeType: string;

  switch (documentId) {
    case 'traverse-report': {
      const { generateTraverseReport } = await import('../generators/traverseReport');
      buffer = await generateTraverseReport(projectId);
      fileName = `traverse-report-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'levelling-report': {
      const { generateLevellingReport } = await import('../generators/levellingReport');
      buffer = await generateLevellingReport(projectId);
      fileName = `levelling-report-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'field-book': {
      const { generateFieldBookExcel } = await import('../generators/fieldBookExcel');
      buffer = await generateFieldBookExcel(projectId);
      fileName = `field-book-${projectId}.xlsx`;
      mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      break;
    }
    case 'control-schedule': {
      const { generateCoordinateSchedule } = await import('../generators/coordinateSchedule');
      buffer = await generateCoordinateSchedule(projectId);
      fileName = `coordinate-schedule-${projectId}.xlsx`;
      mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      break;
    }
    case 'full-package': {
      const { generateFullPackage } = await import('../generators/fullPackage');
      buffer = await generateFullPackage(projectId);
      fileName = `submission-package-${projectId}.zip`;
      mimeType = 'application/zip';
      break;
    }
    case 'deed-plan': {
      if (surveyType !== 'cadastral') {
        throw new Error('Deed Plan is only available for cadastral surveys.');
      }

      // Statutory Validation Gate — refuse to produce a deed plan that
      // ArdhiSasa will reject. See src/lib/validation/statutoryGate.ts.
      const { loadGateInputForProject, mergeGateInput } = await import('../validation/statutoryGateLoader');
      const { runStatutoryGate, formatGateResult } = await import('../validation/statutoryGate');
      const profile = await fetchSurveyorProfile(projectId);
      const loadedInput = await loadGateInputForProject(projectId);
      if (loadedInput) {
        const gateInput = mergeGateInput(loadedInput, {
          surveyor: {
            name: profile.surveyorName || loadedInput.surveyor.name,
            licenseNumber: profile.iskNumber || loadedInput.surveyor.licenseNumber,
          },
          submissionType: 'mutation',
        });
        const gateResult = runStatutoryGate(gateInput);
        if (!gateResult.passed) {
          const blockCount = gateResult.summary.block;
          const detail = formatGateResult(gateResult);
          throw new Error(
            `Statutory validation failed — ${blockCount} blocking violation(s) prevent deed plan generation.\n\n${detail}`
          );
        }
      }

      const { generateDeedPlan } = await import('../generators/deedPlan');
      buffer = await generateDeedPlan(projectId);
      fileName = `deed-plan-${projectId}.pdf`;
      mimeType = 'application/pdf';

      // Audit chain — record that a deed plan was generated.
      // This is the tamper-evident log entry that proves the plan
      // left the system in a known state. See src/lib/audit/auditLog.ts.
      try {
        const { appendAuditEntry } = await import('../audit/auditLog');
        await appendAuditEntry({
          projectId,
          userId: userId ?? null,
          userName: profile.surveyorName || undefined,
          entityType: 'document',
          entityId: `deed-plan/${projectId}`,
          action: 'generate',
          payload: {
            new: { fileName, mimeType, sizeBytes: buffer.length },
            reason: 'Deed plan generated after statutory gate passed',
            metadata: { gateRuleVersion: '1.1.0' },
          },
        });
      } catch (auditErr) {
        // Audit failure should NOT block the document generation —
        // the surveyor needs their plan. Log and continue.
        console.warn('[assembleDocument] Audit chain append failed:', auditErr);
      }
      break;
    }
    case 'working-diagram': {
      const { generateWorkingDiagramPdf } = await import('../generators/workingDiagram');
      buffer = await generateWorkingDiagramPdf(projectId);
      fileName = `working-diagram-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'boundary-shapefile': {
      const { generateBoundaryShapefile } = await import('../generators/boundaryShapefile');
      buffer = await generateBoundaryShapefile(projectId);
      fileName = `boundary-shapefile-${projectId}.zip`;
      mimeType = 'application/zip';
      break;
    }
    case 'setting-out-dxf': {
      const { generateSettingOutDxf } = await import('../generators/settingOutDxf');
      buffer = await generateSettingOutDxf(projectId);
      fileName = `setting-out-${projectId}.dxf`;
      mimeType = 'application/dxf';
      break;
    }
    case 'longitudinal-section': {
      const { generateLongitudinalSection } = await import('../generators/longitudinalSection');
      buffer = await generateLongitudinalSection(projectId);
      fileName = `longitudinal-section-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'volumetric-report': {
      const { generateVolumetricReport } = await import('../generators/volumetricReport');
      buffer = await generateVolumetricReport(projectId);
      fileName = `volumetric-report-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'gcp-report': {
      const { generateGcpReport } = await import('../generators/gcpReport');
      buffer = await generateGcpReport(projectId);
      fileName = `gcp-report-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'orthophoto-plan': {
      const { generateOrthophotoPlan } = await import('../generators/orthophotoPlan');
      buffer = await generateOrthophotoPlan(projectId);
      fileName = `orthophoto-plan-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'deformation-report': {
      const { generateDeformationReport } = await import('../generators/deformationReport');
      buffer = await generateDeformationReport(projectId);
      fileName = `deformation-report-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'form-c22': {
      const { generateFormC22Pdf } = await import('../generators/formC22');
      const { computeDeedPlanGeometry } = await import('../generators/deedPlanGeometry');
      const [projectRes, surveyorProfile, preAdjusted] = await Promise.all([
        db.query(
          'SELECT name, lr_number, parcel_number, county, division, district, locality, survey_type, survey_subtype FROM projects WHERE id = $1',
          [projectId]
        ),
        fetchSurveyorProfile(projectId),
        loadPreAdjustedFromDB(projectId),
      ]);
      const proj = projectRes.rows[0];
      const geom = await computeDeedPlanGeometry(projectId, {
        preAdjustedCoordinates: preAdjusted?.stations,
        preAdjustedClosure: preAdjusted?.closure,
      });
      const perimeterM = geom.bearingSchedule.reduce((s: number, l: any) => s + parseFloat(l.distance), 0);
      const adjustedStations = computeTraverseAdjustment(
        geom.stations, geom.bearingSchedule, geom.misclosureMm, perimeterM
      );
      buffer = generateFormC22Pdf({
        projectName: proj?.name || '',
        lrNumber: proj?.lr_number || '',
        parcelNumber: proj?.parcel_number || '',
        county: proj?.county || '',
        division: proj?.division || '',
        district: proj?.district || '',
        locality: proj?.locality || '',
        surveyType: proj?.survey_type || 'cadastral',
        surveyorName: surveyorProfile.surveyorName,
        iskNumber: surveyorProfile.iskNumber,
        firmName: surveyorProfile.firmName,
        referenceNumber: surveyorProfile.referenceNumber,
        revision: 'R00',
        stations: adjustedStations,
        angularMisclosureSec: 0,
        angularToleranceSec: 60,
        linearMisclosureM: geom.misclosureMm / 1000,
        perimeterM,
        precisionRatio: parseInt(geom.precisionRatio.replace(/[^\d]/g, '')) || 5000,
        areaM2: geom.areaM2 || 0,
        areaHa: (geom.areaM2 || 0) / 10000,
      });
      fileName = `form-c22-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'area-computation': {
      const { generateAreaComputationSheet } = await import('../generators/areaComputationSheet');
      const { computeDeedPlanGeometry } = await import('../generators/deedPlanGeometry');
      const [projectRes, surveyorProfile, preAdjusted] = await Promise.all([
        db.query(
          'SELECT name, lr_number FROM projects WHERE id = $1',
          [projectId]
        ),
        fetchSurveyorProfile(projectId),
        loadPreAdjustedFromDB(projectId),
      ]);
      const proj = projectRes.rows[0];
      const geom = await computeDeedPlanGeometry(projectId, {
        preAdjustedCoordinates: preAdjusted?.stations,
        preAdjustedClosure: preAdjusted?.closure,
      });
      buffer = generateAreaComputationSheet({
        projectName: proj?.name || '',
        lrNumber: proj?.lr_number || '',
        surveyorName: surveyorProfile.surveyorName,
        iskNumber: surveyorProfile.iskNumber,
        firmName: surveyorProfile.firmName,
        referenceNumber: surveyorProfile.referenceNumber,
        stations: geom.stations.map((st: any) => ({
          label: st.station,
          easting: st.easting,
          northing: st.northing,
        })),
        precisionRatio: geom.precisionRatio,
        perimeterM: geom.bearingSchedule.reduce((s: number, l: any) => s + parseFloat(l.distance), 0),
        adjustmentMethod: 'Bowditch (Compass Rule)',
      });
      fileName = `area-computation-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'traverse-computation-sheet': {
      const { generateTraverseComputationSheet } = await import('../generators/traverseComputationSheet');
      const { computeDeedPlanGeometry } = await import('../generators/deedPlanGeometry');
      const [projectRes, surveyorProfile, preAdjusted] = await Promise.all([
        db.query(
          'SELECT name, lr_number, parcel_number, county, division, district, locality, survey_type FROM projects WHERE id = $1',
          [projectId]
        ),
        fetchSurveyorProfile(projectId),
        loadPreAdjustedFromDB(projectId),
      ]);
      const proj = projectRes.rows[0];
      const geom = await computeDeedPlanGeometry(projectId, {
        preAdjustedCoordinates: preAdjusted?.stations,
        preAdjustedClosure: preAdjusted?.closure,
      });
      const perimeterM = geom.bearingSchedule.reduce((s: number, l: any) => s + parseFloat(l.distance), 0);
      const adjustedStations = computeTraverseAdjustment(
        geom.stations, geom.bearingSchedule, geom.misclosureMm, perimeterM
      );
      const precisionRatioNum = parseInt(geom.precisionRatio.replace(/[^\d]/g, '')) || 5000;

      // Compute observations and legs from adjusted stations
      const observations = adjustedStations.map((st, i) => {
        const next = adjustedStations[(i + 1) % adjustedStations.length];
        const dE = next.adjustedEasting - st.adjustedEasting;
        const dN = next.adjustedNorthing - st.adjustedNorthing;
        const wcb = ((Math.atan2(dE, dN) * 180) / Math.PI + 360) % 360;
        const hd = Math.sqrt(dE * dE + dN * dN);
        return {
          station: st.label,
          hclDeg: wcb,
          hcrDeg: (wcb + 180) % 360,
          meanAngleDeg: wcb,
          slopeDistance: hd,
          verticalAngle: 0,
          horizontalDistance: hd,
          deltaH: 0,
        };
      });

      const legs = adjustedStations.map((st, i) => {
        const next = adjustedStations[(i + 1) % adjustedStations.length];
        return {
          from: st.label,
          to: next.label,
          includedAngleDeg: 180,
          wcbDeg: st.observedBearing,
          hd: st.observedDistance,
          departure: st.departureRaw,
          latitude: st.latitudeRaw,
          depCorrection: st.departureCorrection,
          latCorrection: st.latitudeCorrection,
          adjDep: st.departureRaw + st.departureCorrection,
          adjLat: st.latitudeRaw + st.latitudeCorrection,
        };
      });

      buffer = generateTraverseComputationSheet({
        projectName: proj?.name || '',
        lrNumber: proj?.lr_number || '',
        parcelNumber: proj?.parcel_number || '',
        county: proj?.county || '',
        division: proj?.division || '',
        district: proj?.district || '',
        locality: proj?.locality || '',
        surveyType: proj?.survey_type || 'cadastral',
        surveyorName: surveyorProfile.surveyorName,
        iskNumber: surveyorProfile.iskNumber,
        firmName: surveyorProfile.firmName,
        referenceNumber: surveyorProfile.referenceNumber,
        revision: 'R00',
        observations,
        legs,
        coordinates: geom.stations.map((st: any) => ({
          station: st.station,
          easting: st.easting,
          northing: st.northing,
        })),
        isClosed: true,
        totalPerimeter: perimeterM,
        sumDepartures: adjustedStations.reduce((s, st) => s + st.departureRaw, 0),
        sumLatitudes: adjustedStations.reduce((s, st) => s + st.latitudeRaw, 0),
        linearErrorM: geom.misclosureMm / 1000,
        precisionRatio: precisionRatioNum,
        accuracyOrder: precisionRatioNum >= 20000 ? '1st Order' : precisionRatioNum >= 10000 ? '2nd Order' : precisionRatioNum >= 5000 ? '3rd Order' : precisionRatioNum >= 2000 ? '4th Order' : 'Below Standard',
        allowableMisclosureM: 0.025 * Math.sqrt(perimeterM / 1000),
      });
      fileName = `traverse-computation-sheet-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    case 'mutation-form': {
      const { generateMutationForm } = await import('./generators/mutationForm');
      const [projectRes, surveyorProfile] = await Promise.all([
        db.query(
          'SELECT name, lr_number, county, division, district, locality, boundary_data FROM projects WHERE id = $1',
          [projectId]
        ),
        fetchSurveyorProfile(projectId),
      ]);
      const proj = projectRes.rows[0];
      const bd = proj?.boundary_data || {};

      // Get resulting parcels from scheme data if available
      const { rows: parcels } = await db.query(
        'SELECT parcel_number, lr_number_proposed, area_ha FROM parcels p JOIN blocks b ON b.id = p.block_id WHERE b.project_id = $1 ORDER BY parcel_number',
        [projectId]
      );

      buffer = Buffer.from(generateMutationForm({
        parentLRNumber: proj?.lr_number || '',
        parentParcelNumber: bd.parcelNumber || '',
        parentAreaHa: bd.areaHa || 0,
        resultingParcels: parcels.map((p: any) => ({
          parcelNumber: p.parcel_number,
          areaHa: p.area_ha || 0,
        })),
        county: proj?.county || '',
        division: proj?.division || '',
        district: proj?.district || '',
        locality: proj?.locality || '',
        registryMapSheet: bd.registryMapSheet || '',
        mutationType: 'subdivision',
        reasonForMutation: 'Subdivision of parent parcel',
        affectedBeacons: (bd.adjustedStations || []).map((s: any) => ({
          beaconId: s.pointName || s.station || '',
          action: 'adopted' as const,
          easting: s.adjustedEasting || s.easting || 0,
          northing: s.adjustedNorthing || s.northing || 0,
        })),
        surveyorName: surveyorProfile.surveyorName,
        iskNumber: surveyorProfile.iskNumber,
        firmName: surveyorProfile.firmName,
        surveyDate: new Date().toISOString().slice(0, 10),
        referenceNumber: surveyorProfile.referenceNumber,
      }));
      fileName = `mutation-form-${projectId}.pdf`;
      mimeType = 'application/pdf';
      break;
    }
    default:
      throw new Error(`Generator not yet implemented for: ${documentId}. This document type is coming in a future phase.`);
  }

  const storagePath = `submissions/${projectId}/${fileName}`;
  const publicUrl = await uploadFile(buffer, fileName, mimeType, storagePath);

  const signedUrl = await getSignedUrl(storagePath, 60 * 60 * 24 * 7);

  return { fileUrl: signedUrl };
}

import JSZip from 'jszip'
import { createClient } from '@/lib/api-client/server'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { db } from '@/lib/db'
import { getActiveSurveyorProfile } from './surveyorProfile'
import { generateSubmissionRef } from './revisionNumber'
import { validateSubmission } from './validateSubmission'
import { generateFormNo4DXF } from './generators/formNo4'
import { generateStatutoryWorkbook } from './workbook/statutoryWorkbook'
import { generateWorkingDiagramDXF } from './generators/workingDiagram'
import { generatePPA2Form } from './generators/ppa2Form'
import { generateLCBConsent } from './generators/lcbConsent'
import { generateMutationForm } from './generators/mutationForm'
import type { PPA2Input } from './generators/ppa2Form'
import type { LCBConsentInput } from './generators/lcbConsent'
import type { MutationFormInput } from './generators/mutationForm'
import { coordinateArea } from '@/lib/engine/area'
import { angularClosureTolerance } from '@/lib/engine/traverse'
import type { SubmissionPackage, QAGateResult, SurveySubtype } from './types'

interface ProjectData {
  id: string
  lr_number: string
  parcel_number: string
  division: string
  county: string
  district: string
  locality: string
  area_m2: number
  perimeter_m: number
  subtype: SurveySubtype
  survey_points: unknown[]
  supporting_documents: unknown[]
  angular_misclosure: number
  linear_misclosure: number
  precision_ratio: string
  closing_error_e: number
  closing_error_n: number
  client_name: string
  survey_type?: string
}

export async function assembleSubmissionPackage(
  projectId: string
): Promise<{ zipBuffer: Buffer; ref: string; qa: QAGateResult }> {
  const dbClient = await createClient()
  const surveyor = await getActiveSurveyorProfile()
  if (!surveyor) {
    // AUDIT FIX (H-010, 2026-07-27): guard against missing surveyor profile.
    throw new Error('Surveyor profile not found — please complete your profile before generating a submission.')
  }
  const asNum = (value: unknown, fallback = 0): number => {
    const parsed = Number(value)
    return Number.isFinite(parsed) ? parsed : fallback
  }

  // QueryBuilder does not support DbClient-style nested relation selects,
  // so fetch project, points, and docs in separate queries.
  const { data: project, error: projectError } = await dbClient
    .from('projects')
    .select('*')
    .eq('id', projectId)
    .single()

  if (projectError || !project) throw new Error('Project not found')

  const { data: surveyPoints, error: pointsError } = await dbClient
    .from('survey_points')
    .select('*')
    .eq('project_id', projectId)
    .limit(50_000) // hard cap: 50k points per project (~50MB RAM for dense surveys).
                    // Exceeding this requires project splitting or cursor pagination.

  if (pointsError) {
    throw new Error(`Failed to load survey points: ${pointsError.message}`)
  }

  const { data: supportingDocuments, error: docsError } = await dbClient
    .from('supporting_documents')
    .select('*')
    .eq('project_id', projectId)

  if (docsError) {
    throw new Error(`Failed to load supporting documents: ${docsError.message}`)
  }

  const proj = {
    ...(project as Record<string, unknown>),
    survey_points: Array.isArray(surveyPoints) ? surveyPoints : [],
    supporting_documents: Array.isArray(supportingDocuments) ? supportingDocuments : []
  } as unknown as ProjectData

  const adjustedCoordinates = (proj.survey_points || [])
    .filter((pt: any) => pt.adjusted_easting != null && pt.adjusted_northing != null)
    .map((pt: any) => ({
      label: pt.point_name ?? pt.name ?? `P${pt.idx}`,
      easting: asNum(pt.adjusted_easting),
      northing: asNum(pt.adjusted_northing)
    }));

  let computedAreaM2 = 0;
  if (adjustedCoordinates.length >= 3) {
    const areaResult = coordinateArea(adjustedCoordinates);
    computedAreaM2 = areaResult.areaSqm;
  } else if (proj.survey_points && proj.survey_points.length >= 3) {
    const rawCoordinates = (proj.survey_points || []).map((pt: any) => ({
      easting: asNum(pt.easting),
      northing: asNum(pt.northing)
    }));
    const areaResult = coordinateArea(rawCoordinates);
    computedAreaM2 = areaResult.areaSqm;
  }

  if (adjustedCoordinates.length < 3 && proj.survey_points && proj.survey_points.length >= 3) {
    console.warn('No adjusted coordinates found - using raw coordinates for area computation');
  }

  if (adjustedCoordinates.length < 3 && (!proj.survey_points || proj.survey_points.length < 3)) {
    throw new Error(
      'Cannot assemble submission: traverse must have at least 3 points to compute area. ' +
      'Complete traverse computation before submitting.'
    );
  }

  const { ref, revision } = await generateSubmissionRef(
    projectId,
    surveyor.registration_number
  )

  const supportingDocs = (proj.supporting_documents ?? []).map((doc: any) => ({
    type: doc.type,
    label: doc.label,
    required: doc.required,
    fileUrl: doc.file_url ?? null,
    uploadedAt: doc.uploaded_at ?? null
  }))

  const pkg: SubmissionPackage = {
    submissionRef: ref,
    projectId,
    surveyor: { ...surveyor, registrationNumber: surveyor.registration_number } as any,
    subtype: (proj.survey_type || 'cadastral_subdivision') as SurveySubtype,
    parcel: {
      lrNumber: proj.lr_number || '',
      parcelNumber: proj.parcel_number || proj.lr_number || '',
      county: proj.county || '',
      division: proj.division || '',
      district: proj.district || '',
      locality: proj.locality || '',
      areaM2: computedAreaM2,
      perimeterM: asNum(proj.perimeter_m),
      clientName: proj.client_name || ''
    },
    traverse: {
      points: (proj.survey_points || []).map((pt: any) => ({
        pointName: pt.name || pt.point_name || `P${pt.id}`,
        easting: asNum(pt.easting),
        northing: asNum(pt.northing),
        adjustedEasting: asNum(pt.adjusted_easting, asNum(pt.easting)),
        adjustedNorthing: asNum(pt.adjusted_northing, asNum(pt.northing)),
        observedBearing: asNum(pt.observed_bearing),
        observedDistance: asNum(pt.observed_distance, asNum(pt.distance))
      })),
      angularMisclosure: asNum(proj.angular_misclosure),
      linearMisclosure: asNum(proj.linear_misclosure),
      precisionRatio: proj.precision_ratio || '1:1',
      closingErrorE: asNum(proj.closing_error_e),
      closingErrorN: asNum(proj.closing_error_n),
      adjustmentMethod: 'bowditch',
      areaM2: computedAreaM2,
      perimeterM: asNum(proj.perimeter_m)
    },
    supportingDocs,
    generatedAt: new Date().toISOString(),
    revision
  }

  const qa = validateSubmission(pkg)
  if (!qa.passed) {
    return { zipBuffer: Buffer.alloc(0), ref, qa }
  }

  const formNo4Dxf = generateFormNo4DXF(pkg)
  const firstPt = pkg.traverse.points[0]
  const workbook = await generateStatutoryWorkbook({
    project: {
      name: String(project.name ?? ''),
      lrNumber: String(project.lr_number ?? ''),
      parcelNumber: String(project.parcel_number ?? ''),
      county: String(project.county ?? ''),
      division: String(project.division ?? ''),
      district: String(project.district ?? ''),
      locality: String(project.locality ?? ''),
      surveyType: 'cadastral',
      surveyDate: String(project.survey_date ?? new Date().toISOString()),
      scaleDenominator: 2500,
    },
    surveyor: {
      name: surveyor.full_name,
      iskNumber: surveyor.registration_number,
      firmName: surveyor.firm_name ?? '',
    },
    submission: {
      referenceNumber: ref,
      revision,
      status: 'submitted',
    },
    fieldObservations: pkg.traverse.points.map((pt, i) => ({
      stationFrom: pt.pointName,
      stationTo: pkg.traverse.points[(i + 1) % pkg.traverse.points.length]?.pointName ?? '',
      observedBearingDeg: pt.observedBearing,
      observedDistanceM: pt.observedDistance,
    })),
    traverse: {
      method: pkg.traverse.adjustmentMethod,
      stations: pkg.traverse.points.map(pt => ({
        label: pt.pointName,
        observedBearing: pt.observedBearing,
        observedDistance: pt.observedDistance,
        departureRaw: pt.easting - (firstPt?.easting ?? 0),
        latitudeRaw: pt.northing - (firstPt?.northing ?? 0),
        departureCorrected: pt.adjustedEasting - pt.easting,
        latitudeCorrected: pt.adjustedNorthing - pt.northing,
        easting: pt.adjustedEasting,
        northing: pt.adjustedNorthing,
      })),
      angularMisclosureSec: pkg.traverse.angularMisclosure,
      angularToleranceSec: angularClosureTolerance(pkg.traverse.points.length),
      angularPassesQA: pkg.traverse.angularMisclosure <= angularClosureTolerance(pkg.traverse.points.length),
      linearMisclosureM: pkg.traverse.linearMisclosure,
      perimeterM: pkg.traverse.perimeterM,
      precisionRatio: parseInt(pkg.traverse.precisionRatio.replace('1:', '')),
      precisionMinimum: 5000,
      linearPassesQA: true,
    },
    adjustedStations: pkg.traverse.points.map(pt => ({
      label: pt.pointName,
      easting: pt.adjustedEasting,
      northing: pt.adjustedNorthing,
    })),
    levelling: null,
    areaComputation: {
      stations: pkg.traverse.points.map(pt => ({
        label: pt.pointName,
        easting: pt.adjustedEasting,
        northing: pt.adjustedNorthing,
      })),
      areaM2: pkg.traverse.areaM2,
      areaHa: pkg.traverse.areaM2 / 10000,
      perimeterM: pkg.traverse.perimeterM,
    },
    legs: pkg.traverse.points.map((pt, i) => ({
      fromLabel: pt.pointName,
      toLabel: pkg.traverse.points[(i + 1) % pkg.traverse.points.length]?.pointName ?? '',
      bearing: pt.observedBearing,
      distance: pt.observedDistance,
    })),
    cogoResults: null,
  })
  const workingDiagram = generateWorkingDiagramDXF(pkg)

  const zip = new JSZip()
  zip.file('form_no_4.dxf', formNo4Dxf)
  zip.file('computation_workbook.xlsx', workbook)
  zip.file('working_diagram.dxf', workingDiagram)

  // Supporting documents - PPA2 (always included)
  // ponytail: cast via unknown — the query result `project` is typed as
  // Record<string, unknown> after the Phase 6 queryBuilder tightening, so each
  // property access yields `unknown`. The PDF generator handles stringification
  // at runtime; the cast preserves the legacy `any`-typed behavior.
  const ppa2Input = {
    lrNumber: project.lr_number,
    parcelNumber: project.parcel_number,
    county: project.county,
    division: project.division,
    district: project.district,
    locality: project.locality,
    areaHa: computedAreaM2 / 10000,
    surveyType: project.survey_subtype ?? project.survey_type ?? 'Cadastral',
    applicantName: project.client_name ?? '',
    applicantAddress: project.client_address ?? '',
    applicantIdNumber: project.client_id_number,
    surveyorName: surveyor.full_name,
    iskNumber: surveyor.registration_number,
    firmName: surveyor.firm_name ?? '',
    surveyDate: project.survey_date ?? new Date().toISOString(),
    referenceNumber: ref,
  } as unknown as PPA2Input
  zip.file('supporting_docs/ppa2_form.pdf', generatePPA2Form(ppa2Input))

  // Supporting documents - LCB Consent (always included)
  // ponytail: same as PPA2 above — cast via unknown to preserve legacy runtime.
  const lcbInput = {
    lrNumber: project.lr_number,
    parcelNumber: project.parcel_number,
    county: project.county,
    division: project.division,
    district: project.district,
    areaHa: computedAreaM2 / 10000,
    landUse: project.land_use ?? 'Agricultural',
    transferorName: project.owner_name ?? '',
    transfereeName: project.client_name ?? '',
    transferorIdNumber: project.owner_id_number,
    transfereeIdNumber: project.client_id_number,
    surveyorName: surveyor.full_name,
    iskNumber: surveyor.registration_number,
    surveyDate: project.survey_date ?? new Date().toISOString(),
    referenceNumber: ref,
    lbcApplicationNumber: project.lbc_application_number,
  } as unknown as LCBConsentInput
  zip.file('supporting_docs/lcb_consent.pdf', generateLCBConsent(lcbInput))

  // Supporting documents - Mutation Form (only for mutation subtype)
  if (project.survey_subtype === 'mutation') {
    // ponytail: same as PPA2 above — cast via unknown to preserve legacy runtime.
    const mutationInput = {
      parentLRNumber: project.lr_number,
      parentParcelNumber: project.parcel_number,
      parentAreaHa: project.parent_area_ha ?? computedAreaM2 / 10000,
      resultingParcels: project.resulting_parcels ?? [],
      county: project.county,
      division: project.division,
      district: project.district,
      locality: project.locality,
      registryMapSheet: project.registry_map_sheet ?? '',
      mutationType: 'subdivision' as const,
      reasonForMutation: project.mutation_reason ?? 'Subdivision',
      affectedBeacons: adjustedCoordinates.map((st, i) => ({
        beaconId: st.label,
        action: 'new' as const,
        easting: st.easting,
        northing: st.northing,
      })),
      surveyorName: surveyor.full_name,
      iskNumber: surveyor.registration_number,
      firmName: surveyor.firm_name ?? '',
      surveyDate: project.survey_date ?? new Date().toISOString(),
      referenceNumber: ref,
      mutationNumber: project.mutation_number,
    } as unknown as MutationFormInput
    zip.file('supporting_docs/mutation_form.pdf', generateMutationForm(mutationInput))
  }

  const manifest = {
    submissionRef: ref,
    generatedAt: pkg.generatedAt,
    surveyor: pkg.surveyor.registrationNumber || (pkg.surveyor as any).registration_number,
    lrNumber: pkg.parcel.lrNumber,
    areaHa: (pkg.parcel.areaM2 / 10000).toFixed(4),
    areaM2: pkg.parcel.areaM2.toFixed(2),
    perimeterM: pkg.traverse.perimeterM.toFixed(3),
    precisionRatio: pkg.traverse.precisionRatio,
    adjustmentMethod: pkg.traverse.adjustmentMethod,
    files: ['form_no_4.dxf', 'computation_workbook.xlsx', 'working_diagram.dxf', 'manifest.json'],
    supportingDocuments: pkg.supportingDocs.map(d => d.type).filter(Boolean),
    qaResult: qa
  }
  zip.file('manifest.json', JSON.stringify(manifest, null, 2))

  const zipBuffer = await zip.generateAsync({ type: 'nodebuffer' })

  // Get user from NextAuth session
  const authSession = await getServerSession(authOptions)
  const userId = (authSession?.user as any)?.id ?? ''
  
  const { rows: profileRows } = await db.query(
    'SELECT id, user_id, isk_number, verified_isk FROM surveyor_profiles WHERE user_id = $1 LIMIT 1',
    [userId]
  )
  const profile = profileRows[0]

  if (!profile) {
    throw new Error('Surveyor profile not found')
  }

  const currentYear = new Date().getFullYear()
  const { rows: existingRows } = await db.query(
    'SELECT revision_number FROM project_submissions WHERE project_id = $1 ORDER BY revision_number DESC LIMIT 1',
    [projectId]
  )

  const revisionNumber = (existingRows[0]?.revision_number ?? -1) + 1

  // Direct SQL replaces dbClient.rpc('increment_submission_sequence')
  const { rows: seqRows } = await db.query(
    `INSERT INTO submission_sequences (surveyor_profile_id, year, current_sequence)
     VALUES ($1, $2, 1)
     ON CONFLICT (surveyor_profile_id, year)
     DO UPDATE SET current_sequence = submission_sequences.current_sequence + 1
     RETURNING current_sequence`,
    [profile.id, currentYear]
  )

  const sequence = seqRows[0]?.current_sequence ?? 1
  const submissionNumber = `${profile.isk_number}_${currentYear}_${String(sequence).padStart(3, '0')}_R${String(revisionNumber).padStart(2, '0')}`

  await db.query(
    `INSERT INTO project_submissions (project_id, surveyor_profile_id, submission_number, revision_code, submission_year, package_status, generated_artifacts, validation_results)
     VALUES ($1, $2, $3, $4, $5, 'ready', $6, $7)`,
    [
      projectId,
      profile.id,
      submissionNumber,
      `R${String(revisionNumber).padStart(2, '0')}`,
      currentYear,
      JSON.stringify({
        form_no_4: 'form_no_4.dxf',
        computation_workbook: 'computation_workbook.xlsx',
        working_diagram: 'working_diagram.dxf'
      }),
      JSON.stringify(qa)
    ]
  )

  return { zipBuffer, ref, qa }
}

// ============================================================
// METARDU — CLA Form 11: Notice of Variation of Community Land Rights
// Community Land Act No. 27 of 2016, Section 40
// ============================================================

import jsPDF from 'jspdf'

/** Row in the variation comparison table */
export interface VariationRow {
  /** Description of the attribute being varied */
  description: string
  /** Value before the variation */
  before: string
  /** Value after the variation */
  after: string
}

/**
 * Input interface for CLA Form 11 — Notice of Variation of Community Land Rights.
 * All fields correspond to requirements under Section 40 of the Community Land Act 2016.
 */
export interface CLA11Input {
  /** Variation reference number */
  variationReference: string
  /** Date of the variation notice */
  date: string
  /** Registered name of the community */
  communityName: string
  /** County */
  county: string
  /** Land reference number */
  landReference: string
  /** Parcel number */
  parcelNumber: string
  /** Current right holder name */
  currentRightHolderName: string
  /** Current right holder ID number */
  currentRightHolderId: string
  /** Nature of the current right */
  natureOfCurrentRight: 'lease' | 'license' | 'customary'
  /** Current term description (e.g. "99 years", "5 years remaining") */
  currentTerm: string
  /** Reason for the variation */
  reasonForVariation: 'extension' | 'reduction' | 'surrender' | 'subdivision' | 'other'
  /** Additional details if reason is "other" */
  otherReasonDescription?: string
  /** Detailed description of the proposed variation */
  proposedVariationDetails: string
  /** Date from which the variation takes effect */
  effectiveDate: string
  /** Compensation payable (if any), in KES */
  compensationPayable?: number
  /** Comparison table rows showing before and after values */
  variationTable: VariationRow[]
  /** Surveyor details (required if boundary change) */
  surveyor?: {
    name: string
    iskNumber: string
    firmName?: string
  }
  /** Land registrar details */
  registrar?: {
    name: string
    designation: string
  }
  /** Status of the variation notice */
  status?: 'DRAFT' | 'NOTIFIED' | 'UNDER_REVIEW' | 'APPROVED' | 'REJECTED'
}

/**
 * Generates CLA Form 11: Notice of Variation of Community Land Rights.
 *
 * This form provides official notice of a proposed variation to existing
 * community land rights, including extension, reduction, surrender, or
 * subdivision of interests, under Section 40 of the Community Land Act 2016.
 *
 * @param input - Structured data conforming to {@link CLA11Input}
 * @returns PDF document as a Uint8Array
 */
export function generateCLAForm11(input: CLA11Input): Uint8Array {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })
  const W = 210
  const margin = 20

  // ── Header ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(13)
  doc.text('REPUBLIC OF KENYA', W / 2, 22, { align: 'center' })
  doc.setFontSize(11)
  doc.text('COMMUNITY LAND ACT No. 27 OF 2016', W / 2, 30, { align: 'center' })
  doc.text('CLA FORM 11 — NOTICE OF VARIATION OF COMMUNITY LAND RIGHTS', W / 2, 38, { align: 'center' })
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(9)
  doc.text('(Section 40)', W / 2, 45, { align: 'center' })

  doc.setLineWidth(0.5)
  doc.line(margin, 49, W - margin, 49)

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  doc.text(`Variation Ref.: ${input.variationReference}`, margin, 56)
  doc.text(`Date: ${input.date}`, W - margin, 56, { align: 'right' })
  if (input.status) {
    doc.setTextColor(27, 58, 92)
    doc.text(`Status: ${input.status.replace(/_/g, ' ')}`, W / 2, 56, { align: 'center' })
    doc.setTextColor(0, 0, 0)
  }

  let y = 64
  const lineH = 8

  // ── Helper functions ────────────────────────────────────────
  function sectionHeader(title: string) {
    if (y > 260) {
      doc.addPage()
      y = 20
    }
    doc.setFillColor(27, 58, 92)
    doc.rect(margin, y, W - margin * 2, 7, 'F')
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(9)
    doc.setTextColor(255, 255, 255)
    doc.text(title, margin + 3, y + 5)
    doc.setTextColor(0, 0, 0)
    y += 10
  }

  function field(label: string, value: string, labelWidth = 55) {
    if (y > 275) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    doc.setFont('helvetica', 'normal')
    doc.text(value || '\u2014', margin + labelWidth, y)
    doc.setLineWidth(0.1)
    doc.line(margin + labelWidth, y + 1, W - margin, y + 1)
    y += lineH
  }

  function signatureBlock(label: string) {
    if (y > 255) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    y += 6
    doc.setFont('helvetica', 'normal')
    doc.setLineWidth(0.1)
    doc.line(margin, y, margin + 90, y)
    doc.text('Signature', margin, y + 4)
    doc.line(margin + 105, y, W - margin, y)
    doc.text('Date', margin + 105, y + 4)
    y += 12
  }

  // ── Section A: Community and Land Details ───────────────────
  sectionHeader('PART A — COMMUNITY AND LAND DETAILS')
  field('Community Name:', input.communityName)
  field('County:', input.county)
  field('Land Reference:', input.landReference)
  field('Parcel Number:', input.parcelNumber)
  y += 2

  // ── Section B: Current Right Holder ─────────────────────────
  sectionHeader('PART B — CURRENT RIGHT HOLDER')
  field('Right Holder Name:', input.currentRightHolderName)
  field('ID Number:', input.currentRightHolderId)
  field('Nature of Right:', input.natureOfCurrentRight.toUpperCase())
  field('Current Term:', input.currentTerm)
  y += 2

  // ── Section C: Variation Details ────────────────────────────
  sectionHeader('PART C — VARIATION DETAILS')
  const reasonDisplay = input.reasonForVariation === 'other'
    ? `OTHER: ${input.otherReasonDescription ?? ''}`
    : input.reasonForVariation.toUpperCase()
  field('Reason for Variation:', reasonDisplay)
  field('Effective Date:', input.effectiveDate)
  field('Compensation (if any):', input.compensationPayable ? `KES ${input.compensationPayable.toLocaleString()}` : 'None')
  y += 2

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(8.5)
  doc.text('Details of Proposed Variation:', margin, y)
  y += 5
  doc.setFont('helvetica', 'normal')
  const detailLines = doc.splitTextToSize(input.proposedVariationDetails, W - margin * 2)
  detailLines.forEach((line: string) => {
    if (y > 275) { doc.addPage(); y = 20 }
    doc.text(line, margin, y)
    y += 5
  })
  y += 4

  // ── Section D: Comparison Table ─────────────────────────────
  sectionHeader('PART D — VARIATION COMPARISON TABLE')

  const colX = [margin, margin + 60, margin + 125, margin + 160]
  const headers = ['Description', 'Before Variation', 'After Variation', 'Remarks']
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(7.5)
  headers.forEach((h, i) => doc.text(h, colX[i], y))
  doc.setLineWidth(0.2)
  doc.line(margin, y + 2, W - margin, y + 2)
  y += 6

  doc.setFont('helvetica', 'normal')
  doc.setFontSize(7.5)
  input.variationTable.forEach((row) => {
    if (y > 270) {
      doc.addPage()
      y = 20
      doc.setFont('helvetica', 'bold')
      headers.forEach((h, i) => doc.text(h, colX[i], y))
      doc.line(margin, y + 2, W - margin, y + 2)
      y += 6
      doc.setFont('helvetica', 'normal')
    }

    doc.text(row.description, colX[0], y)
    doc.text(row.before, colX[1], y)
    doc.text(row.after, colX[2], y)
    doc.line(margin, y + 2, W - margin, y + 2)
    y += 6
  })
  y += 4

  // ── Section E: Surveyor Certification (if boundary change) ──
  if (input.surveyor) {
    sectionHeader('PART E — LICENSED SURVEYOR CERTIFICATION')
    field('Surveyor Name:', input.surveyor.name)
    field('ISK Number:', input.surveyor.iskNumber)
    field('Firm / Company:', input.surveyor.firmName ?? '')
    y += 2
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8.5)
    doc.text(
      `I, ${input.surveyor.name} (ISK ${input.surveyor.iskNumber}), Licensed Surveyor, hereby certify`,
      margin, y
    )
    y += 5
    doc.text(
      'that the variation described in this notice has been surveyed and the modified boundaries',
      margin, y
    )
    y += 5
    doc.text(
      'accurately reflect the new extent of the community land interest.',
      margin, y
    )
    y += 10
  }

  // ── Signature Blocks ────────────────────────────────────────
  sectionHeader('PART F — SIGNATURES')
  signatureBlock('1. Current Right Holder:')
  signatureBlock('2. Community Assembly Chairman (Seal):')
  if (input.surveyor) {
    signatureBlock('3. Licensed Surveyor:')
  }
  signatureBlock('4. Land Registrar:')
  if (input.registrar) {
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8)
    doc.text(`   Name: ${input.registrar.name}, ${input.registrar.designation}`, margin, y)
    y += 5
  }

  // ── Footer ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'italic')
  doc.setFontSize(7.5)
  doc.setTextColor(100, 100, 100)
  doc.text(
    'Generated by Metardu Survey Platform \u2014 Community Land Act 2016 Compliant',
    W / 2,
    285,
    { align: 'center' }
  )

  return doc.output('arraybuffer') as unknown as Uint8Array
}

// ============================================================
// METARDU — CLA Form 12: Community Land Dispute Resolution Form
// Community Land Act No. 27 of 2016, Sections 38 & 39
// ============================================================

import jsPDF from 'jspdf'

/** Witness details for a dispute resolution */
export interface Witness {
  /** Full name of the witness */
  name: string
  /** National ID number */
  idNumber: string
  /** Contact phone number */
  phone: string
}

/** Dispute Resolution Committee hearing details */
export interface DisputeResolutionCommittee {
  /** Date of the hearing */
  hearingDate: string
  /** Names of committee members present */
  committeeMembersPresent: string[]
  /** Summary of the decision reached */
  decisionSummary: string
  /** Date the decision was issued */
  decisionDate: string
  /** Whether the decision was appealed */
  appealed: 'Yes' | 'No'
  /** Appeal reference number (if appealed) */
  appealReference?: string
}

/**
 * Input interface for CLA Form 12 — Community Land Dispute Resolution Form.
 * All fields correspond to requirements under Sections 38 & 39 of the Community Land Act 2016.
 */
export interface CLA12Input {
  /** Dispute reference number */
  disputeReferenceNumber: string
  /** Date the dispute was filed */
  dateFiled: string
  /** Registered name of the community */
  communityName: string
  /** County */
  county: string
  /** Land reference number */
  landReference: string
  /** Parcel number */
  parcelNumber: string
  /** Complainant details */
  complainant: {
    name: string
    idNumber: string
    address: string
    phone?: string
  }
  /** Respondent details */
  respondent: {
    name: string
    idNumber: string
    address?: string
  }
  /** Nature of the dispute */
  natureOfDispute: 'boundary' | 'ownership' | 'allocation' | 'access' | 'use' | 'other'
  /** Additional description if nature is "other" */
  otherNatureDescription?: string
  /** Detailed description of the dispute */
  disputeDescription: string
  /** Date the dispute arose */
  dateDisputeArose: string
  /** Previous attempts at resolution */
  previousResolutionAttempts?: string
  /** Witnesses (up to 4) */
  witnesses: Witness[]
  /** Relief sought by the complainant */
  reliefSought: string
  /** List of documents attached */
  documentsAttached?: string
  /** Mediator or arbitrator details (if appointed) */
  mediator?: {
    name: string
    designation: string
    appointmentDate: string
  }
  /** Dispute Resolution Committee details */
  disputeCommittee?: DisputeResolutionCommittee
  /** Status of the dispute */
  status?: 'FILED' | 'UNDER_MEDIATION' | 'UNDER_ARBITRATION' | 'RESOLVED' | 'APPEALED' | 'DISMISSED'
}

/**
 * Generates CLA Form 12: Community Land Dispute Resolution Form.
 *
 * This form records community land disputes and their resolution process,
 * including complainant and respondent details, witness information,
 * mediation/arbitration proceedings, and committee decisions under
 * Sections 38 & 39 of the Community Land Act 2016.
 *
 * @param input - Structured data conforming to {@link CLA12Input}
 * @returns PDF document as a Uint8Array
 */
export function generateCLAForm12(input: CLA12Input): Uint8Array {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })
  const W = 210
  const margin = 20

  // ── Header ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(13)
  doc.text('REPUBLIC OF KENYA', W / 2, 22, { align: 'center' })
  doc.setFontSize(11)
  doc.text('COMMUNITY LAND ACT No. 27 OF 2016', W / 2, 30, { align: 'center' })
  doc.text('CLA FORM 12 — COMMUNITY LAND DISPUTE RESOLUTION FORM', W / 2, 38, { align: 'center' })
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(9)
  doc.text('(Sections 38 & 39)', W / 2, 45, { align: 'center' })

  doc.setLineWidth(0.5)
  doc.line(margin, 49, W - margin, 49)

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  doc.text(`Dispute Ref.: ${input.disputeReferenceNumber}`, margin, 56)
  doc.text(`Date Filed: ${input.dateFiled}`, W - margin, 56, { align: 'right' })
  if (input.status) {
    doc.setTextColor(27, 58, 92)
    doc.text(`Status: ${input.status.replace(/_/g, ' ')}`, W / 2, 56, { align: 'center' })
    doc.setTextColor(0, 0, 0)
  }

  let y = 64
  const lineH = 8

  // ── Helper functions ────────────────────────────────────────
  function sectionHeader(title: string) {
    if (y > 260) {
      doc.addPage()
      y = 20
    }
    doc.setFillColor(27, 58, 92)
    doc.rect(margin, y, W - margin * 2, 7, 'F')
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(9)
    doc.setTextColor(255, 255, 255)
    doc.text(title, margin + 3, y + 5)
    doc.setTextColor(0, 0, 0)
    y += 10
  }

  function field(label: string, value: string, labelWidth = 50) {
    if (y > 275) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    doc.setFont('helvetica', 'normal')
    doc.text(value || '\u2014', margin + labelWidth, y)
    doc.setLineWidth(0.1)
    doc.line(margin + labelWidth, y + 1, W - margin, y + 1)
    y += lineH
  }

  function signatureBlock(label: string) {
    if (y > 255) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    y += 6
    doc.setFont('helvetica', 'normal')
    doc.setLineWidth(0.1)
    doc.line(margin, y, margin + 90, y)
    doc.text('Signature', margin, y + 4)
    doc.line(margin + 105, y, W - margin, y)
    doc.text('Date', margin + 105, y + 4)
    y += 12
  }

  // ── Section A: Dispute Details ──────────────────────────────
  sectionHeader('PART A — DISPUTE DETAILS')
  field('Dispute Ref. No.:', input.disputeReferenceNumber)
  field('Date Filed:', input.dateFiled)
  field('Community Name:', input.communityName)
  field('County:', input.county)
  field('Land Reference:', input.landReference)
  field('Parcel Number:', input.parcelNumber)
  y += 2

  // ── Section B: Nature of Dispute ────────────────────────────
  sectionHeader('PART B — NATURE OF DISPUTE')
  const natureDisplay = input.natureOfDispute === 'other'
    ? `OTHER: ${input.otherNatureDescription ?? ''}`
    : input.natureOfDispute.toUpperCase()
  field('Nature of Dispute:', natureDisplay)
  field('Date Dispute Arose:', input.dateDisputeArose)
  y += 2

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(8.5)
  doc.text('Description of Dispute:', margin, y)
  y += 5
  doc.setFont('helvetica', 'normal')
  const descLines = doc.splitTextToSize(input.disputeDescription, W - margin * 2)
  descLines.forEach((line: string) => {
    if (y > 275) { doc.addPage(); y = 20 }
    doc.text(line, margin, y)
    y += 5
  })
  y += 4

  // ── Section C: Complainant ──────────────────────────────────
  sectionHeader('PART C — COMPLAINANT')
  field('Full Name:', input.complainant.name)
  field('ID Number:', input.complainant.idNumber)
  field('Address:', input.complainant.address)
  field('Phone:', input.complainant.phone ?? '')
  y += 2

  // ── Section D: Respondent ───────────────────────────────────
  sectionHeader('PART D — RESPONDENT')
  field('Full Name:', input.respondent.name)
  field('ID Number:', input.respondent.idNumber)
  field('Address:', input.respondent.address ?? '')
  y += 2

  // ── Section E: Previous Resolution Attempts ─────────────────
  sectionHeader('PART E — PREVIOUS RESOLUTION ATTEMPTS')
  if (input.previousResolutionAttempts) {
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8.5)
    const attemptLines = doc.splitTextToSize(input.previousResolutionAttempts, W - margin * 2)
    attemptLines.forEach((line: string) => {
      if (y > 275) { doc.addPage(); y = 20 }
      doc.text(line, margin, y)
      y += 5
    })
  } else {
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(8.5)
    doc.text('No previous attempts at resolution.', margin, y)
    y += lineH
  }
  y += 4

  // ── Section F: Witnesses ────────────────────────────────────
  sectionHeader('PART F — WITNESSES')
  const witnessCols = [margin, margin + 60, margin + 120]
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(7.5)
  doc.text('Name', witnessCols[0], y)
  doc.text('ID Number', witnessCols[1], y)
  doc.text('Phone', witnessCols[2], y)
  doc.line(margin, y + 2, W - margin, y + 2)
  y += 6

  doc.setFont('helvetica', 'normal')
  if (input.witnesses.length === 0) {
    doc.text('No witnesses listed.', margin, y)
    y += lineH
  } else {
    input.witnesses.slice(0, 4).forEach((w) => {
      if (y > 275) { doc.addPage(); y = 20 }
      doc.text(w.name, witnessCols[0], y)
      doc.text(w.idNumber, witnessCols[1], y)
      doc.text(w.phone, witnessCols[2], y)
      doc.line(margin, y + 2, W - margin, y + 2)
      y += 6
    })
  }
  y += 4

  // ── Section G: Relief Sought ────────────────────────────────
  sectionHeader('PART G — RELIEF SOUGHT BY COMPLAINANT')
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(8.5)
  const reliefLines = doc.splitTextToSize(input.reliefSought, W - margin * 2)
  reliefLines.forEach((line: string) => {
    if (y > 275) { doc.addPage(); y = 20 }
    doc.text(line, margin, y)
    y += 5
  })
  y += 4

  // ── Section H: Documents Attached ───────────────────────────
  if (input.documentsAttached) {
    sectionHeader('PART H — DOCUMENTS ATTACHED')
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8.5)
    const docLines = doc.splitTextToSize(input.documentsAttached, W - margin * 2)
    docLines.forEach((line: string) => {
      if (y > 275) { doc.addPage(); y = 20 }
      doc.text(line, margin, y)
      y += 5
    })
    y += 4
  }

  // ── Section I: Signatures ───────────────────────────────────
  sectionHeader('PART I — SIGNATURES')
  signatureBlock('1. Complainant:')
  signatureBlock('2. Community Assembly Representative:')
  if (input.mediator) {
    signatureBlock('3. Mediator / Arbitrator:')
  }

  // ── Section J: Dispute Resolution Committee ─────────────────
  if (input.disputeCommittee) {
    sectionHeader('PART J — DISPUTE RESOLUTION COMMITTEE')
    field('Hearing Date:', input.disputeCommittee.hearingDate)
    field('Decision Date:', input.disputeCommittee?.decisionDate ?? "—")
    field('Appealed:', input.disputeCommittee?.appealed ?? "—")
    if (input.disputeCommittee.appealReference) {
      field('Appeal Reference:', input.disputeCommittee.appealReference)
    }
    y += 2

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text('Committee Members Present:', margin, y)
    y += 5
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8)
    input.disputeCommittee.committeeMembersPresent.forEach((member) => {
      if (y > 275) { doc.addPage(); y = 20 }
      doc.text(`\u2022  ${member}`, margin + 5, y)
      y += 5
    })
    y += 4

    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text('Decision Summary:', margin, y)
    y += 5
    doc.setFont('helvetica', 'normal')
    const decisionLines = doc.splitTextToSize(input.disputeCommittee?.decisionSummary ?? "—", W - margin * 2)
    decisionLines.forEach((line: string) => {
      if (y > 275) { doc.addPage(); y = 20 }
      doc.text(line, margin, y)
      y += 5
    })
    y += 8

    // Committee chairperson signature
    signatureBlock('Committee Chairperson:')
  }

  // ── Footer ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'italic')
  doc.setFontSize(7.5)
  doc.setTextColor(100, 100, 100)
  doc.text(
    'Generated by Metardu Survey Platform \u2014 Community Land Act 2016 Compliant',
    W / 2,
    285,
    { align: 'center' }
  )

  return doc.output('arraybuffer') as unknown as Uint8Array
}

// ============================================================
// METARDU — CLA Form 3: Community Land Rights Allocation Record
// Community Land Act No. 27 of 2016, Section 16
// ============================================================

import jsPDF from 'jspdf'

/** Single allocation entry within the allocation record */
export interface AllocationEntry {
  /** Allottee full name */
  allotteeName: string
  /** Allottee national ID or PIN number */
  allotteeId: string
  /** Type of interest allocated */
  interestType: 'lease' | 'license' | 'customary_right'
  /** Area allocated in hectares */
  areaHa: number
  /** Term of the lease in years (if applicable) */
  termYears?: number
  /** Commencement date of the interest */
  commencementDate: string
  /** Annual rent in KES (if applicable) */
  annualRentKes?: number
  /** One-time premium in KES (if applicable) */
  premiumKes?: number
  /** Special conditions attached to the allocation */
  specialConditions?: string
}

/**
 * Input interface for CLA Form 3 — Community Land Rights Allocation Record.
 * Supports multiple allocation entries per form, as required under Section 16.
 */
export interface CLA3Input {
  /** Allocation reference number */
  allocationReference: string
  /** Date of the allocation record */
  date: string
  /** Registered name of the community */
  communityName: string
  /** County */
  county: string
  /** Land reference number */
  landReference: string
  /** Parcel number */
  parcelNumber: string
  /** Community Assembly resolution reference authorizing these allocations */
  assemblyResolutionRef: string
  /** County approval reference */
  countyApprovalRef?: string
  /** Array of individual allocation entries */
  allocations: AllocationEntry[]
  /** Surveyor certification details */
  surveyor: {
    name: string
    iskNumber: string
    firmName?: string
  }
  /** Status of the allocation record */
  status?: 'DRAFT' | 'SUBMITTED' | 'APPROVED' | 'REJECTED'
}

/**
 * Generates CLA Form 3: Community Land Rights Allocation Record.
 *
 * Records the allocation of community land rights to individuals or entities,
 * including lease, license, and customary rights, under Section 16 of the
 * Community Land Act 2016. Supports multiple allocation entries per record.
 *
 * @param input - Structured data conforming to {@link CLA3Input}
 * @returns PDF document as a Uint8Array
 */
export function generateCLAForm3(input: CLA3Input): Uint8Array {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })
  const W = 210
  const margin = 20

  // ── Header ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(13)
  doc.text('REPUBLIC OF KENYA', W / 2, 22, { align: 'center' })
  doc.setFontSize(11)
  doc.text('COMMUNITY LAND ACT No. 27 OF 2016', W / 2, 30, { align: 'center' })
  doc.text('CLA FORM 3 — COMMUNITY LAND RIGHTS ALLOCATION RECORD', W / 2, 38, { align: 'center' })
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(9)
  doc.text('(Section 16)', W / 2, 45, { align: 'center' })

  doc.setLineWidth(0.5)
  doc.line(margin, 49, W - margin, 49)

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  doc.text(`Allocation Ref.: ${input.allocationReference}`, margin, 56)
  doc.text(`Date: ${input.date}`, W - margin, 56, { align: 'right' })
  if (input.status) {
    doc.setTextColor(27, 58, 92)
    doc.text(`Status: ${input.status}`, W / 2, 56, { align: 'center' })
    doc.setTextColor(0, 0, 0)
  }

  let y = 64
  const lineH = 8

  // ── Helper functions ────────────────────────────────────────
  function sectionHeader(title: string) {
    if (y > 260) {
      doc.addPage()
      y = 20
    }
    doc.setFillColor(27, 58, 92)
    doc.rect(margin, y, W - margin * 2, 7, 'F')
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(9)
    doc.setTextColor(255, 255, 255)
    doc.text(title, margin + 3, y + 5)
    doc.setTextColor(0, 0, 0)
    y += 10
  }

  function field(label: string, value: string, labelWidth = 50) {
    if (y > 275) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    doc.setFont('helvetica', 'normal')
    doc.text(value || '\u2014', margin + labelWidth, y)
    doc.setLineWidth(0.1)
    doc.line(margin + labelWidth, y + 1, W - margin, y + 1)
    y += lineH
  }

  function signatureBlock(label: string) {
    if (y > 255) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    y += 6
    doc.setFont('helvetica', 'normal')
    doc.setLineWidth(0.1)
    doc.line(margin, y, margin + 90, y)
    doc.text('Signature', margin, y + 4)
    doc.line(margin + 105, y, W - margin, y)
    doc.text('Date', margin + 105, y + 4)
    y += 12
  }

  // ── Section A: Record Details ───────────────────────────────
  sectionHeader('PART A — ALLOCATION RECORD DETAILS')
  field('Allocation Ref. No.:', input.allocationReference)
  field('Date:', input.date)
  field('Community Name:', input.communityName)
  field('County:', input.county)
  field('Land Reference:', input.landReference)
  field('Parcel Number:', input.parcelNumber)
  field('Assembly Resolution Ref.:', input.assemblyResolutionRef)
  field('County Approval Ref.:', input.countyApprovalRef ?? '')
  y += 2

  // ── Section B: Table of Allocations ─────────────────────────
  sectionHeader('PART B — TABLE OF ALLOCATIONS')

  // Table headers
  const cols = [margin, margin + 38, margin + 72, margin + 100, margin + 120, margin + 142, margin + 164]
  const headers = ['Allottee Name', 'ID Number', 'Interest', 'Area (Ha)', 'Term (Yr)', 'Rent (KES)', 'Start Date']
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(7.5)
  headers.forEach((h, i) => doc.text(h, cols[i], y))
  doc.setLineWidth(0.2)
  doc.line(margin, y + 2, W - margin, y + 2)
  y += 6

  // Table rows
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(7.5)
  input.allocations.forEach((entry) => {
    if (y > 270) {
      doc.addPage()
      y = 20
      // Reprint headers on new page
      doc.setFont('helvetica', 'bold')
      headers.forEach((h, i) => doc.text(h, cols[i], y))
      doc.line(margin, y + 2, W - margin, y + 2)
      y += 6
      doc.setFont('helvetica', 'normal')
    }

    const nameLines = doc.splitTextToSize(entry.allotteeName, 34)
    doc.text(nameLines[0], cols[0], y)
    doc.text(entry.allotteeId, cols[1], y)
    doc.text(entry.interestType.replace(/_/g, ' ').toUpperCase(), cols[2], y)
    doc.text(entry.areaHa.toFixed(2), cols[3], y)
    doc.text(entry.termYears?.toString() ?? '\u2014', cols[4], y)
    doc.text(entry.annualRentKes ? entry.annualRentKes.toLocaleString() : '\u2014', cols[5], y)
    doc.text(entry.commencementDate, cols[6], y)
    doc.line(margin, y + 2, W - margin, y + 2)

    // Special conditions on sub-row
    if (entry.specialConditions) {
      y += 5
      doc.setFont('helvetica', 'italic')
      doc.setFontSize(7)
      doc.text(`Conditions: ${entry.specialConditions}`, cols[0], y)
      doc.setFont('helvetica', 'normal')
      doc.setFontSize(7.5)
    }
    y += 6
  })

  // Summary row
  if (input.allocations.length > 0) {
    const totalArea = input.allocations.reduce((sum, a) => sum + a.areaHa, 0)
    y += 2
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8)
    doc.text(`Total Allocations: ${input.allocations.length}`, margin, y)
    doc.text(`Total Area: ${totalArea.toFixed(2)} Ha`, margin + 70, y)
    y += lineH
  }
  y += 4

  // ── Section C: Surveyor Certification ───────────────────────
  sectionHeader('PART C — SURVEYOR CERTIFICATION')
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(8.5)
  doc.text(
    `I, ${input.surveyor.name} (ISK ${input.surveyor.iskNumber}), Licensed Surveyor of ${input.surveyor.firmName ?? 'N/A'},`,
    margin, y
  )
  y += 5
  doc.text(
    'hereby certify that the land described in this allocation record has been surveyed and',
    margin, y
  )
  y += 5
  doc.text(
    'demarcated in accordance with the Survey Act (Cap 299) and the Community Land Act 2016.',
    margin, y
  )
  y += 5
  doc.text(
    'The boundaries and areas stated herein accurately reflect the survey on the ground.',
    margin, y
  )
  y += 10

  field('Surveyor Name:', input.surveyor.name)
  field('ISK Number:', input.surveyor.iskNumber)
  field('Firm / Company:', input.surveyor.firmName ?? '')
  y += 4

  // ── Signature Blocks ────────────────────────────────────────
  sectionHeader('PART D — SIGNATURES')
  signatureBlock('1. Community Assembly Chairman (Seal):')
  signatureBlock('2. Licensed Surveyor:')
  signatureBlock('3. County Director of Land:')

  // ── Footer ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'italic')
  doc.setFontSize(7.5)
  doc.setTextColor(100, 100, 100)
  doc.text(
    'Generated by Metardu Survey Platform \u2014 Community Land Act 2016 Compliant',
    W / 2,
    285,
    { align: 'center' }
  )

  return doc.output('arraybuffer') as unknown as Uint8Array
}

