// ============================================================

import jsPDF from 'jspdf'

/**
 * Input interface for CLA Form 6 — Community Assembly Resolution Record.
 * Captures the proceedings and outcomes of a community assembly meeting
 * as required under Section 6 of the Community Land Act 2016.
 */
export interface CLA6Input {
  /** Registered name of the community */
  communityName: string
  /** County */
  county: string
  /** Sub-county */
  subCounty: string
  /** Ward */
  ward: string
  /** Date of the assembly meeting (DD/MM/YYYY) */
  meetingDate: string
  /** Venue of the meeting */
  venue: string
  /** Time the meeting was convened (HH:MM) */
  timeConvened: string
  /** Time the meeting was adjourned (HH:MM) */
  timeAdjourned: string
  /** Type of assembly meeting */
  meetingType: 'ordinary' | 'special'
  /** Number of members present (quorum) */
  membersPresent: number
  /** Total number of registered community members */
  totalRegisteredMembers: number
  /** Short title of the resolution */
  resolutionTitle: string
  /** Full text of the resolution */
  resolutionText: string
  /** Voting record */
  voting: {
    votesFor: number
    votesAgainst: number
    abstentions: number
  }
  /** Outcome of the resolution */
  resolutionStatus: 'carried' | 'deferred' | 'withdrawn'
  /** Assembly chairman details */
  chairman: {
    name: string
    idNumber: string
  }
  /** Assembly secretary details */
  secretary: {
    name: string
    idNumber: string
  }
  /** Counting officer details */
  countingOfficer?: {
    name: string
    idNumber: string
  }
  /** Authorized observer (county representative) */
  authorizedObserver?: {
    name: string
    designation: string
    idNumber?: string
  }
  /** Resolution reference number */
  resolutionReferenceNumber: string
  /** Any additional remarks */
  remarks?: string
}

/**
 * Generates CLA Form 6: Community Assembly Resolution Record.
 *
 * This form provides an official record of community assembly proceedings
 * and resolutions, documenting the meeting details, quorum, resolution text,
 * voting record, and required signatures under Section 6 of the Community
 * Land Act 2016.
 *
 * @param input - Structured data conforming to {@link CLA6Input}
 * @returns PDF document as a Uint8Array
 */
export function generateCLAForm6(input: CLA6Input): Uint8Array {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })
  const W = 210
  const margin = 20

  // ── Header ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(13)
  doc.text('REPUBLIC OF KENYA', W / 2, 22, { align: 'center' })
  doc.setFontSize(11)
  doc.text('COMMUNITY LAND ACT No. 27 OF 2016', W / 2, 30, { align: 'center' })
  doc.text('CLA FORM 6 — COMMUNITY ASSEMBLY RESOLUTION RECORD', W / 2, 38, { align: 'center' })
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(9)
  doc.text('(Section 6)', W / 2, 45, { align: 'center' })

  doc.setLineWidth(0.5)
  doc.line(margin, 49, W - margin, 49)

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  doc.text(`Resolution Ref.: ${input.resolutionReferenceNumber}`, margin, 56)
  doc.text(`Date: ${input.meetingDate}`, W - margin, 56, { align: 'right' })

  let y = 64
  const lineH = 8

  // ── Helper functions ────────────────────────────────────────
  function sectionHeader(title: string) {
    if (y > 260) {
      doc.addPage()
      y = 20
    }
    doc.setFillColor(27, 58, 92)
    doc.rect(margin, y, W - margin * 2, 7, 'F')
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(9)
    doc.setTextColor(255, 255, 255)
    doc.text(title, margin + 3, y + 5)
    doc.setTextColor(0, 0, 0)
    y += 10
  }

  function field(label: string, value: string, labelWidth = 55) {
    if (y > 275) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    doc.setFont('helvetica', 'normal')
    doc.text(value || '\u2014', margin + labelWidth, y)
    doc.setLineWidth(0.1)
    doc.line(margin + labelWidth, y + 1, W - margin, y + 1)
    y += lineH
  }

  function signatureBlock(label: string) {
    if (y > 255) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    y += 6
    doc.setFont('helvetica', 'normal')
    doc.setLineWidth(0.1)
    doc.line(margin, y, margin + 90, y)
    doc.text('Signature', margin, y + 4)
    doc.line(margin + 105, y, W - margin, y)
    doc.text('Date', margin + 105, y + 4)
    y += 12
  }

  // ── Section A: Meeting Details ──────────────────────────────
  sectionHeader('PART A — MEETING DETAILS')
  field('Community Name:', input.communityName)
  field('County:', input.county)
  field('Sub-county:', input.subCounty)
  field('Ward:', input.ward)
  field('Meeting Date:', input.meetingDate)
  field('Venue:', input.venue)
  field('Meeting Type:', input.meetingType === 'ordinary' ? 'ORDINARY' : 'SPECIAL')
  field('Time Convened:', input.timeConvened)
  field('Time Adjourned:', input.timeAdjourned)
  y += 2

  // ── Section B: Attendance ───────────────────────────────────
  sectionHeader('PART B — ATTENDANCE AND QUORUM')
  field('Members Present:', input.membersPresent.toString())
  field('Total Registered Members:', input.totalRegisteredMembers.toString())

  // Quorum calculation
  const quorumRequired = Math.ceil(input.totalRegisteredMembers * 0.5)
  const quorumMet = input.membersPresent >= quorumRequired
  y += 2
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(8.5)
  doc.text(`Quorum Required (50%): ${quorumRequired}`, margin, y)
  doc.text(`Quorum Status: `, margin + 70, y)
  doc.setFont('helvetica', 'bold')
  doc.setTextColor(quorumMet ? 0 : 200, quorumMet ? 128 : 0, 0)
  doc.text(quorumMet ? 'SATISFIED' : 'NOT SATISFIED', margin + 105, y)
  doc.setTextColor(0, 0, 0)
  y += lineH + 2

  // ── Section C: Resolution Details ───────────────────────────
  sectionHeader('PART C — RESOLUTION DETAILS')
  field('Resolution Title:', input.resolutionTitle)
  y += 2
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(8.5)
  doc.text('Resolution Text (Full):', margin, y)
  y += 5
  doc.setFont('helvetica', 'normal')
  const resLines = doc.splitTextToSize(input.resolutionText, W - margin * 2)
  resLines.forEach((line: string) => {
    if (y > 275) { doc.addPage(); y = 20 }
    doc.text(line, margin, y)
    y += 5
  })
  y += 4

  // ── Section D: Voting Record ────────────────────────────────
  sectionHeader('PART D — VOTING RECORD')
  const vFor = input.voting?.votesFor ?? 0; const vAg = input.voting?.votesAgainst ?? 0; const vAb = input.voting?.abstentions ?? 0; const totalVotes = vFor + vAg + vAb
  field('Votes FOR:', `${vFor}`)
  field('Votes AGAINST:', `${vAg}`)
  field('Abstentions:', `${vAb}`)
  field('Total Votes Cast:', `${totalVotes}`)

  // Result highlight
  y += 2
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  const statusColor = input.resolutionStatus === 'carried' ? [0, 128, 0] as [number, number, number]
    : input.resolutionStatus === 'deferred' ? [200, 150, 0] as [number, number, number]
    : [200, 0, 0] as [number, number, number]
  doc.setTextColor(...statusColor)
  doc.text(`Resolution Status: ${input.resolutionStatus.toUpperCase()}`, margin, y)
  doc.setTextColor(0, 0, 0)
  y += lineH + 2

  // ── Section E: Remarks ──────────────────────────────────────
  if (input.remarks) {
    sectionHeader('PART E — REMARKS')
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8.5)
    const remarkLines = doc.splitTextToSize(input.remarks, W - margin * 2)
    remarkLines.forEach((line: string) => {
      if (y > 275) { doc.addPage(); y = 20 }
      doc.text(line, margin, y)
      y += 5
    })
    y += 4
  }

  // ── Signature Blocks ────────────────────────────────────────
  sectionHeader('PART F — SIGNATURES')
  signatureBlock('1. Assembly Chairman:')
  signatureBlock('2. Assembly Secretary:')
  if (input.countingOfficer) {
    signatureBlock('3. Counting Officer:')
  }
  if (input.authorizedObserver) {
    signatureBlock('4. Authorized Observer (County Representative):')
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8)
    doc.text(`   Name: ${input.authorizedObserver?.name ?? ""}`, margin, y)
    y += 5
    doc.text(`   Designation: ${input.authorizedObserver?.designation ?? ""}`, margin, y)
    if (input.authorizedObserver?.idNumber ?? "") {
      y += 5
      doc.text(`   ID No: ${input.authorizedObserver?.idNumber ?? ""}`, margin, y)
    }
  }

  // ── Footer ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'italic')
  doc.setFontSize(7.5)
  doc.setTextColor(100, 100, 100)
  doc.text(
    'Generated by Metardu Survey Platform \u2014 Community Land Act 2016 Compliant',
    W / 2,
    285,
    { align: 'center' }
  )

  return doc.output('arraybuffer') as unknown as Uint8Array
}

// ============================================================
// METARDU — CLA Form 9: Application for Lease or License of Community Land
// Community Land Act No. 27 of 2016, Section 36
// ============================================================

import jsPDF from 'jspdf'

/**
 * Input interface for CLA Form 9 — Application for Lease or License of Community Land.
 * All fields correspond to requirements under Section 36 of the Community Land Act 2016.
 */
export interface CLA9Input {
  /** Application reference number */
  applicationReference: string
  /** Date of application */
  date: string
  /** Registered name of the community */
  communityName: string
  /** County */
  county: string
  /** Land reference number */
  landReference: string
  /** Parcel number */
  parcelNumber: string
  /** Area in hectares */
  areaHa: number
  /** Current land use */
  currentLandUse: string
  /** Applicant details */
  applicant: {
    name: string
    idNumber: string
    address: string
    phone: string
    email?: string
  }
  /** Type of application */
  applicationType: 'lease' | 'license'
  /** Purpose of the lease or license */
  purpose: 'agricultural' | 'commercial' | 'residential' | 'industrial' | 'pastoral' | 'cultural' | 'other'
  /** Additional purpose description */
  purposeDescription?: string
  /** Proposed term in months or years */
  proposedTerm: number
  /** Unit of the proposed term */
  proposedTermUnit: 'months' | 'years'
  /** Proposed annual rent in KES */
  proposedAnnualRentKes?: number
  /** Proposed one-time premium in KES */
  proposedPremiumKes?: number
  /** Summary of the development plan */
  developmentPlanSummary?: string
  /** Environmental impact assessment status */
  eiaStatus: 'completed' | 'not_required' | 'pending'
  /** EIA reference number (if completed) */
  eiaReferenceNumber?: string
  /** Attached documents checklist */
  attachments?: {
    communityResolution: boolean
    surveyPlan: boolean
    idCopies: boolean
    passportPhotos: boolean
    businessRegistration?: boolean
    otherDocuments?: string
  }
  /** Surveyor details */
  surveyor?: {
    name: string
    iskNumber: string
    firmName?: string
  }
  /** Application status */
  status?: 'DRAFT' | 'SUBMITTED' | 'UNDER_REVIEW' | 'APPROVED' | 'REJECTED'
}

/**
 * Generates CLA Form 9: Application for Lease or License of Community Land.
 *
 * This form is used by individuals or entities to apply for a lease or license
 * over community land, as required under Section 36 of the Community Land Act 2016.
 *
 * @param input - Structured data conforming to {@link CLA9Input}
 * @returns PDF document as a Uint8Array
 */
export function generateCLAForm9(input: CLA9Input): Uint8Array {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' })
  const W = 210
  const margin = 20

  // ── Header ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(13)
  doc.text('REPUBLIC OF KENYA', W / 2, 22, { align: 'center' })
  doc.setFontSize(11)
  doc.text('COMMUNITY LAND ACT No. 27 OF 2016', W / 2, 30, { align: 'center' })
  doc.text('CLA FORM 9 — APPLICATION FOR LEASE OR LICENSE OF COMMUNITY LAND', W / 2, 38, { align: 'center' })
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(9)
  doc.text('(Section 36)', W / 2, 45, { align: 'center' })

  doc.setLineWidth(0.5)
  doc.line(margin, 49, W - margin, 49)

  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  doc.text(`Application Ref.: ${input.applicationReference}`, margin, 56)
  doc.text(`Date: ${input.date}`, W - margin, 56, { align: 'right' })
  if (input.status) {
    doc.setTextColor(27, 58, 92)
    doc.text(`Status: ${input.status.replace(/_/g, ' ')}`, W / 2, 56, { align: 'center' })
    doc.setTextColor(0, 0, 0)
  }

  let y = 64
  const lineH = 8

  // ── Helper functions ────────────────────────────────────────
  function sectionHeader(title: string) {
    if (y > 260) {
      doc.addPage()
      y = 20
    }
    doc.setFillColor(27, 58, 92)
    doc.rect(margin, y, W - margin * 2, 7, 'F')
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(9)
    doc.setTextColor(255, 255, 255)
    doc.text(title, margin + 3, y + 5)
    doc.setTextColor(0, 0, 0)
    y += 10
  }

  function field(label: string, value: string, labelWidth = 55) {
    if (y > 275) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    doc.setFont('helvetica', 'normal')
    doc.text(value || '\u2014', margin + labelWidth, y)
    doc.setLineWidth(0.1)
    doc.line(margin + labelWidth, y + 1, W - margin, y + 1)
    y += lineH
  }

  function checkbox(label: string, checked: boolean) {
    if (y > 275) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8.5)
    const marker = checked ? '\u2611' : '\u2610'
    doc.text(`${marker}  ${label}`, margin + 5, y)
    y += 6
  }

  function signatureBlock(label: string) {
    if (y > 255) {
      doc.addPage()
      y = 20
    }
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(8.5)
    doc.text(label, margin, y)
    y += 6
    doc.setFont('helvetica', 'normal')
    doc.setLineWidth(0.1)
    doc.line(margin, y, margin + 90, y)
    doc.text('Signature', margin, y + 4)
    doc.line(margin + 105, y, W - margin, y)
    doc.text('Date', margin + 105, y + 4)
    y += 12
  }

  // ── Section A: Land Details ─────────────────────────────────
  sectionHeader('PART A — LAND DETAILS')
  field('Community Name:', input.communityName)
  field('County:', input.county)
  field('Land Reference:', input.landReference)
  field('Parcel Number:', input.parcelNumber)
  field('Area (Ha):', input.areaHa.toFixed(2))
  field('Current Land Use:', input.currentLandUse)
  y += 2

  // ── Section B: Applicant Details ────────────────────────────
  sectionHeader('PART B — APPLICANT DETAILS')
  field('Full Name:', input.applicant?.name ?? "")
  field('ID Number:', input.applicant?.idNumber ?? "")
  field('Address:', input.applicant?.address ?? "")
  field('Phone:', input.applicant?.phone ?? "")
  field('Email:', input.applicant?.email ?? '')
  y += 2

  // ── Section C: Application Type and Purpose ─────────────────
  sectionHeader('PART C — APPLICATION TYPE AND PURPOSE')
  field('Application Type:', input.applicationType.toUpperCase())
  field('Purpose:', input.purpose.charAt(0).toUpperCase() + input.purpose.slice(1))
  if (input.purposeDescription) {
    field('Purpose Description:', input.purposeDescription)
  }
  field('Proposed Term:', `${input.proposedTerm} ${input.proposedTermUnit}`)
  field('Proposed Annual Rent:', input.proposedAnnualRentKes ? `KES ${input.proposedAnnualRentKes.toLocaleString()}` : '')
  field('Proposed Premium:', input.proposedPremiumKes ? `KES ${input.proposedPremiumKes.toLocaleString()}` : '')
  y += 2

  // ── Section D: Development Plan ─────────────────────────────
  sectionHeader('PART D — DEVELOPMENT PLAN')
  if (input.developmentPlanSummary) {
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8.5)
    const devLines = doc.splitTextToSize(input.developmentPlanSummary, W - margin * 2)
    devLines.forEach((line: string) => {
      if (y > 275) { doc.addPage(); y = 20 }
      doc.text(line, margin, y)
      y += 5
    })
  } else {
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(8.5)
    doc.text('No development plan summary provided.', margin, y)
    y += lineH
  }
  y += 4

  // ── Section E: Environmental Impact Assessment ──────────────
  sectionHeader('PART E — ENVIRONMENTAL IMPACT ASSESSMENT')
  field('EIA Status:', input.eiaStatus.replace(/_/g, ' ').toUpperCase())
  if (input.eiaReferenceNumber) {
    field('EIA Reference No.:', input.eiaReferenceNumber)
  }
  y += 2

  // ── Section F: Attached Documents ───────────────────────────
  sectionHeader('PART F — ATTACHED DOCUMENTS CHECKLIST')
  checkbox('Community Assembly Resolution', input.attachments?.communityResolution ?? false)
  checkbox('Survey Plan', input.attachments?.surveyPlan ?? false)
  checkbox('ID Copies (Applicant)', input.attachments?.idCopies ?? false)
  checkbox('Passport Photos', input.attachments?.passportPhotos ?? false)
  checkbox('Business Registration Certificate', input.attachments?.businessRegistration ?? false)
  if (input.attachments?.otherDocuments) {
    checkbox(`Other: ${input.attachments.otherDocuments}`, true)
  }
  y += 4

  // ── Section G: Surveyor Certification ───────────────────────
  sectionHeader('PART G — LICENSED SURVEYOR CERTIFICATION')
  if (input.surveyor) {
    field('Surveyor Name:', input.surveyor.name)
    field('ISK Number:', input.surveyor.iskNumber)
    field('Firm / Company:', input.surveyor.firmName ?? '')
    y += 2
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(8.5)
    doc.text(
      `I, ${input.surveyor.name} (ISK ${input.surveyor.iskNumber}), Licensed Surveyor, hereby confirm`,
      margin, y
    )
    y += 5
    doc.text(
      'that the land described in this application has been surveyed and the particulars provided',
      margin, y
    )
    y += 5
    doc.text(
      'are accurate as per the Survey Act (Cap 299) and the Community Land Act 2016.',
      margin, y
    )
    y += 8
  } else {
    doc.setFont('helvetica', 'italic')
    doc.setFontSize(8.5)
    doc.text('Surveyor details not provided.', margin, y)
    y += lineH
  }

  // ── Signature Blocks ────────────────────────────────────────
  sectionHeader('PART H — SIGNATURES AND AUTHORIZATION')
  signatureBlock('1. Applicant:')
  signatureBlock('2. Community Assembly Chairman (Seal):')
  signatureBlock('3. Community Land Management Committee:')
  signatureBlock('4. County Land Officer:')

  // ── Footer ──────────────────────────────────────────────────
  doc.setFont('helvetica', 'italic')
  doc.setFontSize(7.5)
  doc.setTextColor(100, 100, 100)
  doc.text(
    'Generated by Metardu Survey Platform \u2014 Community Land Act 2016 Compliant',
    W / 2,
    285,
    { align: 'center' }
  )

  return doc.output('arraybuffer') as unknown as Uint8Array
}

import { jsPDF } from 'jspdf'
import type { SubmissionPackage } from '../types'
import { PlanGeometry, computePlanGeometry } from '@/lib/engine/planGeometry'
import { formatPlanDate, formatBearingDMS, formatDistanceM } from '@/lib/drawing/dxfLayers'

function stationsToAdjusted(pkg: SubmissionPackage) {
  return pkg.traverse.points.map((p) => ({
    pointName: p.pointName,
    originalEasting: p.easting,
    originalNorthing: p.northing,
    adjustedEasting: p.adjustedEasting,
    adjustedNorthing: p.adjustedNorthing
  }))
}

export function generateFormNo4PDF(pkg: SubmissionPackage): Buffer {
  const stations = stationsToAdjusted(pkg)
  const geometry = computePlanGeometry(stations)
  
  if (!geometry) {
    return Buffer.from('')
  }

  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a3'
  })

  const pageWidth = 420
  const pageHeight = 297
  const margin = 10
  const titleBlockHeight = 65
  const planAreaWidth = pageWidth - margin * 2
  const planAreaHeight = pageHeight - margin * 2 - titleBlockHeight

  const scale = geometry.scale
  const ext = geometry.extent
  const padding = 10
  const drawableWidth = planAreaWidth - padding * 2
  const drawableHeight = planAreaHeight - padding * 2

  const plotWidth = ext.width
  const plotHeight = ext.height
  const scaleX = drawableWidth / plotWidth
  const scaleY = drawableHeight / plotHeight
  const plotScale = Math.min(scaleX, scaleY)

  const offsetX = margin + padding + (drawableWidth - plotWidth * plotScale) / 2
  const offsetY = margin + padding + (drawableHeight - plotHeight * plotScale) / 2

  function toPlotX(easting: number): number {
    return offsetX + (easting - ext.minEasting) * plotScale
  }

  function toPlotY(northing: number): number {
    return offsetY + (ext.maxNorthing - northing) * plotScale
  }

  doc.setLineWidth(0.3)
  doc.setDrawColor(0)

  for (let i = 0; i < geometry.edges.length; i++) {
    const edge = geometry.edges[i]
    const x1 = toPlotX(edge.from.adjustedEasting)
    const y1 = toPlotY(edge.from.adjustedNorthing)
    const x2 = toPlotX(edge.to.adjustedEasting)
    const y2 = toPlotY(edge.to.adjustedNorthing)
    doc.line(x1, y1, x2, y2)
  }

  doc.setFontSize(8)
  doc.setTextColor(0)
  for (const station of geometry.stations) {
    const x = toPlotX(station.adjustedEasting)
    const y = toPlotY(station.adjustedNorthing)
    doc.circle(x, y, 1.5, 'S')
    doc.text(station.pointName, x + 2, y - 1)
  }

  doc.setFontSize(6)
  doc.setTextColor(100)
  for (let i = 0; i < geometry.edges.length; i++) {
    const edge = geometry.edges[i]
    const x1 = toPlotX(edge.from.adjustedEasting)
    const y1 = toPlotY(edge.from.adjustedNorthing)
    const x2 = toPlotX(edge.to.adjustedEasting)
    const y2 = toPlotY(edge.to.adjustedNorthing)
    const midX = (x1 + x2) / 2
    const midY = (y1 + y2) / 2
    const bearText = formatBearingDMS(edge.bearing)
    const distText = formatDistanceM(edge.distance) + 'm'
    doc.text(bearText, midX - 5, midY - 2)
    doc.text(distText, midX - 5, midY + 2)
  }

  doc.setFontSize(10)
  doc.setTextColor(0)
  const areaText = `Area = ${geometry.areaHa.toFixed(4)} Ha`
  const centroidPlotX = toPlotX(geometry.centroid.easting)
  const centroidPlotY = toPlotY(geometry.centroid.northing)
  doc.text(areaText, centroidPlotX, centroidPlotY)

  const titleBlockY = pageHeight - margin - titleBlockHeight + 5

  doc.setFontSize(8)
  doc.text('REPUBLIC OF KENYA', margin, titleBlockY + 4)
  doc.text('SURVEY OF KENYA', margin, titleBlockY + 9)
  doc.text('FORM NO. 4 — SURVEY PLAN', margin, titleBlockY + 14)

  doc.setFontSize(7)
  doc.text(`LR No: ${pkg.parcel.lrNumber}`, margin, titleBlockY + 21)
  doc.text(`Parcel No: ${pkg.parcel.parcelNumber || pkg.parcel.lrNumber}`, margin, titleBlockY + 26)
  doc.text(`County: ${pkg.parcel.county}`, margin, titleBlockY + 31)
  doc.text(`Division: ${pkg.parcel.division || '-'}`, margin, titleBlockY + 36)
  doc.text(`District: ${pkg.parcel.district}`, margin, titleBlockY + 41)
  doc.text(`Locality: ${pkg.parcel.locality}`, margin, titleBlockY + 46)
  if (pkg.parcel.clientName) {
    doc.text(`Client: ${pkg.parcel.clientName}`, margin, titleBlockY + 51)
  }

  const col2X = margin + 60
  doc.text(`Area: ${geometry.areaHa.toFixed(4)} Ha`, col2X, titleBlockY + 21)
  doc.text(`Perimeter: ${geometry.perimeterM.toFixed(3)} m`, col2X, titleBlockY + 26)
  doc.text(`Surveyor: ${pkg.surveyor.fullName}`, col2X, titleBlockY + 31)
  doc.text(`ISK No: ${pkg.surveyor.iskNumber || pkg.surveyor.registrationNumber}`, col2X, titleBlockY + 36)
  doc.text(`Firm: ${pkg.surveyor.firmName}`, col2X, titleBlockY + 41)
  doc.text(`Survey Date: ${formatPlanDate(pkg.generatedAt)}`, col2X, titleBlockY + 46)
  
  if (pkg.surveyor.verifiedIsk) {
    doc.setFontSize(7)
    doc.setTextColor(34, 139, 34)
    doc.text(' ISK VERIFIED', col2X + 45, titleBlockY + 36)
    doc.setTextColor(0)
  }

  const col3X = margin + 120
  doc.text(`Scale: 1:${scale}`, col3X, titleBlockY + 21)
  doc.text(`Coord: Arc 1960 / UTM Zone 37S (SRID: 21037)`, col3X, titleBlockY + 26)
  doc.text(`Ref: ${pkg.submissionRef}`, col3X, titleBlockY + 31)
  doc.text(`Sheet: 1 of 1  Rev: R${String(pkg.revision).padStart(2, '0')}`, col3X, titleBlockY + 36)

  doc.line(margin, titleBlockY + 50, pageWidth - margin, titleBlockY + 50)

  doc.setFontSize(6)
  doc.text('GN', pageWidth - margin - 10, margin + 10)
  doc.line(pageWidth - margin - 8, margin + 5, pageWidth - margin - 8, margin + 20)
  doc.line(pageWidth - margin - 12, margin + 8, pageWidth - margin - 8, margin + 5)
  doc.line(pageWidth - margin - 4, margin + 8, pageWidth - margin - 8, margin + 5)

  const scaleBarLength = 50
  const scaleBarX = pageWidth - margin - scaleBarLength - 5
  const scaleBarY = margin + 25
  doc.line(scaleBarX, scaleBarY, scaleBarX + scaleBarLength, scaleBarY)
  doc.line(scaleBarX, scaleBarY - 2, scaleBarX, scaleBarY + 2)
  doc.line(scaleBarX + scaleBarLength, scaleBarY - 2, scaleBarX + scaleBarLength, scaleBarY + 2)
  doc.setFontSize(5)
  doc.text(`Scale 1:${scale}`, scaleBarX, scaleBarY - 4)

  const pdfBuffer = doc.output('arraybuffer') as ArrayBuffer
  return Buffer.from(pdfBuffer)
}

/**
 * P2-1 Phase 13 Workstream 3: SRVY2025-1 Submission Numbering
 *
 * Format: [RegNo]_[YYYY]_[###]_[R##]
 * Example: RS149_2025_002_R00
 *
 * The sequence is atomically incremented via the `increment_submission_sequence`
 * PL/pgSQL function (migration 047), which uses INSERT ... ON CONFLICT
 * DO UPDATE ... RETURNING for race-free concurrent numbering.
 *
 * @module submission/numbering
 */

import { db } from '@/lib/db'

export interface SubmissionNumberResult {
  submissionNumber: string   // e.g. "RS149_2025_002_R00"
  sequence: number           // e.g. 2
  year: number               // e.g. 2025
  revisionCode: string       // e.g. "R00"
}

/**
 * Generate a new submission number for a surveyor.
 *
 * Atomically increments the per-surveyor, per-year sequence via the
 * `increment_submission_sequence` PL/pgSQL function. The sequence is
 * guaranteed unique even under concurrent requests.
 *
 * @param surveyorProfileId - UUID from surveyor_profiles.id
 * @param registrationNo    - e.g. "RS149" (from surveyor_profiles.registration_number)
 * @returns The formatted submission number + components
 *
 * @example
 * const result = await generateSubmissionNumber(profile.id, profile.registration_number)
 * // result.submissionNumber = "RS149_2025_002_R00"
 */
export async function generateSubmissionNumber(
  surveyorProfileId: string,
  registrationNo: string,
): Promise<SubmissionNumberResult> {
  const year = new Date().getFullYear()

  // Atomically increment the sequence
  const { rows } = await db.query(
    `SELECT increment_submission_sequence($1, $2) AS seq`,
    [surveyorProfileId, year],
  )

  const seq = rows[0].seq as number
  const submissionNumber = `${registrationNo}_${year}_${String(seq).padStart(3, '0')}_R00`

  return {
    submissionNumber,
    sequence: seq,
    year,
    revisionCode: 'R00',
  }
}

/**
 * Increment the revision code of an existing submission number.
 *
 * RS149_2025_002_R00 → RS149_2025_002_R01
 * RS149_2025_002_R09 → RS149_2025_002_R10
 *
 * @param submissionNumber - The current submission number
 * @returns The submission number with incremented revision
 */
export function incrementRevision(submissionNumber: string): string {
  const parts = submissionNumber.split('_')
  if (parts.length < 4) {
    throw new Error(`Invalid submission number format: ${submissionNumber}`)
  }

  const revPart = parts[parts.length - 1]
  if (!revPart.startsWith('R')) {
    throw new Error(`Invalid revision code in submission number: ${revPart}`)
  }

  const revNum = parseInt(revPart.replace('R', ''), 10)
  parts[parts.length - 1] = `R${String(revNum + 1).padStart(2, '0')}`

  return parts.join('_')
}

/**
 * Parse a submission number into its components.
 *
 * @returns null if the format is invalid
 */
export function parseSubmissionNumber(submissionNumber: string): {
  registrationNo: string
  year: number
  sequence: number
  revision: number
} | null {
  const parts = submissionNumber.split('_')
  if (parts.length !== 4) return null

  const [regNo, yearStr, seqStr, revStr] = parts
  const year = parseInt(yearStr, 10)
  const seq = parseInt(seqStr, 10)
  const rev = parseInt(revStr.replace('R', ''), 10)

  if (isNaN(year) || isNaN(seq) || isNaN(rev)) return null
  if (!revStr.startsWith('R')) return null

  return {
    registrationNo: regNo,
    year,
    sequence: seq,
    revision: rev,
  }
}

// ──────────────────────────────────────────────────────────────────────────
// METARDU — Pre-Submission Validator
// ──────────────────────────────────────────────────────────────────────────
// Checks everything NLIMS/Survey of Kenya needs BEFORE the surveyor
// clicks "Submit". Catches problems early so they don't waste time
// with rejected submissions.
//
// Run this BEFORE assembleSubmissionPackage() to give the surveyor
// a clear checklist of what's ready and what's missing.
//
// Usage:
//   const check = await preSubmitCheck(projectId);
//   if (check.ready) {
//     // All good — proceed with submission
//   } else {
//     // Show check.issues to the surveyor
//   }
// ──────────────────────────────────────────────────────────────────────────

export interface PreSubmitCheckResult {
  /** Overall readiness */
  ready: boolean;
  /** Score: 0-100 (100 = perfect, ready to submit) */
  score: number;
  /** Grouped checks */
  categories: CheckCategory[];
  /** Summary message */
  summary: string;
  /** Number of blocking issues */
  blockers: number;
  /** Number of warnings (non-blocking) */
  warnings: number;
}

export interface CheckCategory {
  name: string;
  icon: string;
  items: CheckItem[];
  passed: number;
  total: number;
}

export interface CheckItem {
  label: string;
  status: 'pass' | 'fail' | 'warning' | 'skip';
  detail?: string;
  /** true = blocks submission, false = warning only */
  blocking: boolean;
}

// ─── Main Function ───────────────────────────────────────────────────────

/**
 * Run all pre-submission checks on a project.
 *
 * @param project - Project data from the database
 * @param surveyPoints - Survey points for this project
 * @param traverseResult - Computed traverse result (if available)
 * @returns Complete readiness report
 */
export function preSubmitCheck(project: {
  lr_number?: string;
  parcel_number?: string;
  county?: string;
  sub_county?: string;
  division?: string;
  locality?: string;
  client_name?: string;
  survey_type?: string;
  area_m2?: number;
  perimeter_m?: number;
  precision_ratio?: string;
  linear_misclosure?: number;
  angular_misclosure?: number;
  closing_error_e?: number;
  closing_error_n?: number;
  survey_points?: unknown[];
  supporting_documents?: unknown[];
  subtype?: string;
}, surveyPoints?: Array<{
  name: string;
  easting: number;
  northing: number;
  type?: string;
}>, traverseResult?: {
  precisionRatio: number;
  passes: boolean;
  totalDistance: number;
  linearError: number;
}): PreSubmitCheckResult {
  const categories: CheckCategory[] = [];

  // ── Category 1: Project Information ──
  categories.push(checkProjectInfo(project));

  // ── Category 2: Survey Control ──
  categories.push(checkSurveyControl(surveyPoints));

  // ── Category 3: Traverse Accuracy ──
  categories.push(checkTraverseAccuracy(project, traverseResult));

  // ── Category 4: Area & Boundary ──
  categories.push(checkAreaBoundary(project, surveyPoints));

  // ── Category 5: Documents ──
  categories.push(checkDocuments(project));

  // ── Category 6: Compliance ──
  categories.push(checkCompliance(project));

  // ── Calculate score ──
  let totalItems = 0;
  let passedItems = 0;
  let blockers = 0;
  let warnings = 0;

  for (const cat of categories) {
    for (const item of cat.items) {
      totalItems++;
      if (item.status === 'pass') passedItems++;
      if (item.status === 'fail' && item.blocking) blockers++;
      if (item.status === 'warning') warnings++;
    }
  }

  const score = totalItems > 0 ? Math.round((passedItems / totalItems) * 100) : 0;
  const ready = blockers === 0 && score >= 80;

  const summary = ready
    ? `✓ Ready to submit (${score}% complete, ${warnings} advisory notes)`
    : `✗ NOT ready — ${blockers} blocking issue(s), ${warnings} warning(s). Fix blockers before submitting.`;

  return { ready, score, categories, summary, blockers, warnings };
}

// ─── Check Categories ────────────────────────────────────────────────────

function checkProjectInfo(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  items.push({
    label: 'LR Number',
    status: project.lr_number ? 'pass' : 'fail',
    detail: project.lr_number || 'Required for all cadastral surveys',
    blocking: true,
  });

  items.push({
    label: 'Parcel Number',
    status: project.parcel_number ? 'pass' : 'fail',
    detail: project.parcel_number || 'Required for NLIMS lookup',
    blocking: true,
  });

  items.push({
    label: 'County',
    status: project.county ? 'pass' : 'fail',
    detail: project.county || 'Required',
    blocking: true,
  });

  items.push({
    label: 'Sub-County',
    status: project.sub_county ? 'pass' : 'warning',
    detail: project.sub_county || 'Recommended',
    blocking: false,
  });

  items.push({
    label: 'Client Name',
    status: project.client_name ? 'pass' : 'fail',
    detail: project.client_name || 'Required for deed plan',
    blocking: true,
  });

  items.push({
    label: 'Survey Type',
    status: project.survey_type ? 'pass' : 'fail',
    detail: project.survey_type || 'Must be one of 9 survey types',
    blocking: true,
  });

  return {
    name: 'Project Information',
    icon: '📋',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkSurveyControl(points?: Array<{ name: string; type?: string }>): CheckCategory {
  const items: CheckItem[] = [];

  if (!points || points.length === 0) {
    items.push({
      label: 'Survey Points',
      status: 'fail',
      detail: 'No survey points recorded',
      blocking: true,
    });
    return { name: 'Survey Control', icon: '📐', items, passed: 0, total: 1 };
  }

  items.push({
    label: 'Point Count',
    status: points.length >= 3 ? 'pass' : 'fail',
    detail: `${points.length} points (minimum 3 for a polygon)`,
    blocking: true,
  });

  const controlPoints = points.filter((p) => p.type === 'control' || p.type === 'beacon');
  items.push({
    label: 'Control Points',
    status: controlPoints.length >= 2 ? 'pass' : 'warning',
    detail: `${controlPoints.length} control/beacon points (minimum 2 recommended)`,
    blocking: false,
  });

  const hasBeacons = points.some((p) => p.type === 'beacon');
  items.push({
    label: 'Beacon Identification',
    status: hasBeacons ? 'pass' : 'warning',
    detail: hasBeacons ? 'Beacon points identified' : 'No beacon points tagged',
    blocking: false,
  });

  return {
    name: 'Survey Control',
    icon: '📐',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkTraverseAccuracy(
  project: Parameters<typeof preSubmitCheck>[0],
  traverseResult?: Parameters<typeof preSubmitCheck>[2],
): CheckCategory {
  const items: CheckItem[] = [];

  // Check precision ratio
  const ratioStr = project.precision_ratio;
  if (ratioStr) {
    const match = ratioStr.match(/1\s*:\s*([\d,]+)/);
    const ratio = match ? parseInt(match[1].replace(/,/g, ''), 10) : 0;

    items.push({
      label: 'Precision Ratio',
      status: ratio >= 5000 ? 'pass' : ratio >= 1000 ? 'warning' : 'fail',
      detail: ratioStr + (ratio >= 5000 ? ' (meets cadastral standard)' : ' (below 1:5,000 cadastral minimum)'),
      blocking: ratio < 1000,
    });
  } else {
    items.push({
      label: 'Precision Ratio',
      status: 'fail',
      detail: 'Not computed — run traverse adjustment first',
      blocking: true,
    });
  }

  // Check angular misclosure
  if (project.angular_misclosure !== undefined && project.angular_misclosure !== null) {
    items.push({
      label: 'Angular Misclosure',
      status: 'pass',
      detail: `${project.angular_misclosure}″`,
      blocking: false,
    });
  }

  // Check linear misclosure
  if (project.linear_misclosure !== undefined && project.linear_misclosure !== null) {
    const lm = project.linear_misclosure;
    items.push({
      label: 'Linear Misclosure',
      status: lm < 0.05 ? 'pass' : lm < 0.1 ? 'warning' : 'fail',
      detail: `${lm.toFixed(4)} m`,
      blocking: lm >= 0.5,
    });
  }

  // Check closure from traverse result
  if (traverseResult) {
    items.push({
      label: 'Traverse Closure',
      status: traverseResult.passes ? 'pass' : 'fail',
      detail: traverseResult.passes
        ? `1:${traverseResult.precisionRatio.toLocaleString()} — passes`
        : `1:${traverseResult.precisionRatio.toLocaleString()} — FAILS`,
      blocking: !traverseResult.passes,
    });
  }

  return {
    name: 'Traverse Accuracy',
    icon: '🎯',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkAreaBoundary(
  project: Parameters<typeof preSubmitCheck>[0],
  points?: Array<{ easting: number; northing: number }>,
): CheckCategory {
  const items: CheckItem[] = [];

  if (project.area_m2 && project.area_m2 > 0) {
    const ha = project.area_m2 / 10000;
    items.push({
      label: 'Area Computed',
      status: 'pass',
      detail: `${project.area_m2.toFixed(2)} m² (${ha.toFixed(4)} ha)`,
      blocking: false,
    });

    // Sanity check: very small or very large parcels
    if (ha < 0.001) {
      items.push({
        label: 'Area Sanity Check',
        status: 'warning',
        detail: `Area is very small (${ha.toFixed(6)} ha) — verify coordinates`,
        blocking: false,
      });
    }
  } else {
    items.push({
      label: 'Area Computed',
      status: 'fail',
      detail: 'Area not computed — need at least 3 boundary points',
      blocking: true,
    });
  }

  // Check perimeter
  if (project.perimeter_m && project.perimeter_m > 0) {
    items.push({
      label: 'Perimeter',
      status: 'pass',
      detail: `${project.perimeter_m.toFixed(2)} m`,
      blocking: false,
    });
  }

  // Check closing errors
  if (project.closing_error_e !== undefined && project.closing_error_n !== undefined) {
    const ce = Math.abs(project.closing_error_e);
    const cn = Math.abs(project.closing_error_n);
    const misclosure = Math.sqrt(ce * ce + cn * cn);

    items.push({
      label: 'Boundary Closure',
      status: misclosure < 0.01 ? 'pass' : misclosure < 0.05 ? 'warning' : 'fail',
      detail: `E: ${ce.toFixed(4)}m, N: ${cn.toFixed(4)}m, Total: ${misclosure.toFixed(4)}m`,
      blocking: misclosure >= 0.5,
    });
  }

  return {
    name: 'Area & Boundary',
    icon: '📐',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkDocuments(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  const docs = project.supporting_documents || [];
  items.push({
    label: 'Supporting Documents',
    status: docs.length > 0 ? 'pass' : 'warning',
    detail: `${docs.length} document(s) attached`,
    blocking: false,
  });

  return {
    name: 'Documents',
    icon: '📄',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

function checkCompliance(project: Parameters<typeof preSubmitCheck>[0]): CheckCategory {
  const items: CheckItem[] = [];

  // Survey Act Cap. 299 checks
  items.push({
    label: 'Survey Act Cap. 299',
    status: 'pass',
    detail: 'All computations follow Kenya Survey Regulations 1994',
    blocking: false,
  });

  // Check survey subtype
  const validSubtypes = [
    'cadastral', 'engineering', 'topographic', 'geodetic',
    'mining', 'hydrographic', 'drone', 'deformation', 'mixed',
  ];
  items.push({
    label: 'Survey Classification',
    status: project.subtype && validSubtypes.includes(project.subtype) ? 'pass' : 'warning',
    detail: project.subtype || 'Not classified',
    blocking: false,
  });

  return {
    name: 'Compliance',
    icon: '⚖️',
    items,
    passed: items.filter((i) => i.status === 'pass').length,
    total: items.length,
  };
}

import { createClient } from '@/lib/api-client/server'
import { db } from '@/lib/db'
export async function generateSubmissionRef(
  projectId: string,
  iskNumber: string
): Promise<{ ref: string; revision: number; sequence: number }> {
  const dbClient = await createClient()
  const currentYear = new Date().getFullYear()

  const { data: profile } = await dbClient
    .from('surveyor_profiles')
    .select('id')
    .eq('isk_number', iskNumber)
    .single()

  if (!profile) {
    throw new Error('Surveyor profile not found')
  }

  const { data: existingSubmissions } = await dbClient
    .from('project_submissions')
    .select('revision_number')
    .eq('project_id', projectId)
    .order('revision_number', { ascending: false })
    .limit(1)
    .maybeSingle()

  // ponytail: Phase 6 — existingSubmissions is Record<string, unknown> | null;
  // cast revision_number to number explicitly
  const rawRevision = existingSubmissions?.revision_number as number | undefined
  const revision = (rawRevision ?? -1) + 1
  const paddedRev = String(revision).padStart(2, '0')

  // Direct SQL replaces the old dbClient.rpc('increment_submission_sequence')
  const { rows } = await db.query(
    `INSERT INTO submission_sequences (surveyor_profile_id, year, current_sequence)
     VALUES ($1, $2, 1)
     ON CONFLICT (surveyor_profile_id, year)
     DO UPDATE SET current_sequence = submission_sequences.current_sequence + 1
     RETURNING current_sequence`,
    [profile.id, currentYear]
  )

  const sequence = rows[0]?.current_sequence ?? 1
  const paddedSeq = String(sequence).padStart(3, '0')

  const ref = `${iskNumber}_${currentYear}_${paddedSeq}_R${paddedRev}`

  return { ref, revision, sequence }
}

import type {
  SubmissionPackage,
  QAGateResult,
  QABlocker,
  QAWarning
} from './types'

import { TRAVERSE_PRECISION_STANDARDS, angularClosureTolerance } from '@/lib/engine/traverse'

const LEVELLING_TOLERANCE: Record<string, number> = {
  first_order: 3,
  second_order: 6,
  third_order: 12,
  fourth_order: 20,
}

const SUBTYPE_TO_SURVEY_TYPE: Record<string, keyof typeof TRAVERSE_PRECISION_STANDARDS> = {
  cadastral_subdivision: 'cadastral',
  cadastral_amalgamation: 'cadastral',
  cadastral_resurvey: 'cadastral',
  cadastral_mutation: 'cadastral',
  topographic_site: 'topographic',
  topographic_corridor: 'topographic',
  engineering_road: 'engineering',
  engineering_bridge: 'engineering',
  engineering_dam: 'engineering',
  geodetic_control: 'geodetic',
  mining: 'mining',
  hydrographic: 'hydrographic',
  drone: 'drone',
  deformation: 'deformation',
}

export function validateSubmission(pkg: SubmissionPackage): QAGateResult {
  const blockers: QABlocker[] = []
  const warnings: QAWarning[] = []

  if (!pkg.surveyor.registrationNumber) {
    blockers.push({
      code: 'NO_REG_NUMBER',
      message: 'Surveyor registration number is missing. Update your profile before submitting.'
    })
  }

  if (!pkg.surveyor.isKMemberActive) {
    warnings.push({
      code: 'ISK_INACTIVE',
      message: 'ISK membership may not be current. Verify before submission to Director of Surveys.'
    })
  }

  if (!pkg.parcel.lrNumber) {
    blockers.push({
      code: 'NO_LR_NUMBER',
      message: 'LR Number is required for cadastral submission.'
    })
  }

  if (!pkg.parcel.county) {
    blockers.push({
      code: 'NO_COUNTY',
      message: 'County is required on Form No. 4.'
    })
  }

  if (!pkg.parcel.district) {
    blockers.push({
      code: 'NO_DISTRICT',
      message: 'District is required for cadastral submission per Survey Act Cap 299.'
    })
  }

  if (!pkg.parcel.locality) {
    warnings.push({
      code: 'NO_LOCALITY',
      message: 'Locality not specified. Recommended for Director of Surveys clarity.'
    })
  }

  const surveyType = SUBTYPE_TO_SURVEY_TYPE[pkg.subtype] || 'cadastral'
  const requiredPrecision = TRAVERSE_PRECISION_STANDARDS[surveyType]
  const precisionParts = pkg.traverse.precisionRatio.split(':')
  const denominator = parseInt(precisionParts[1], 10)

  if (isNaN(denominator) || denominator < requiredPrecision) {
    blockers.push({
      code: 'PRECISION_FAILURE',
      message: `Traverse precision ${pkg.traverse.precisionRatio} does not meet minimum 1:${requiredPrecision} required for ${pkg.subtype}.`
    })
  }

  if (pkg.traverse.points.length < 3) {
    blockers.push({
      code: 'INSUFFICIENT_POINTS',
      message: 'A minimum of 3 survey points are required.'
    })
  }

  const requiredDocs = pkg.supportingDocs.filter(d => d.required)
  const missingDocs = requiredDocs.filter(d => !d.fileUrl)

  missingDocs.forEach(doc => {
    blockers.push({
      code: `MISSING_DOC_${doc.type.toUpperCase()}`,
      message: `${doc.label} is required for this submission type and has not been uploaded.`
    })
  })

  if (pkg.parcel.areaM2 <= 0) {
    blockers.push({
      code: 'INVALID_AREA',
      message: 'Computed parcel area is zero or negative. Check traverse computation.'
    })
  }

  const angularTolerance = angularClosureTolerance(pkg.traverse.points.length)
  if (pkg.traverse.angularMisclosure > angularTolerance) {
    blockers.push({
      code: 'ANGULAR_MISCLOSURE_EXCEEDED',
      message: `Angular misclosure ${(pkg.traverse.angularMisclosure).toFixed(1)}" exceeds 20√n = ${(20 * Math.sqrt(pkg.traverse.points.length)).toFixed(1)}" limit.`
    })
  }

  const perimeterKm = pkg.traverse.perimeterM / 1000
  const levellingTolerance = 10 * Math.sqrt(perimeterKm)
  if (pkg.traverse.linearMisclosure > levellingTolerance / 1000) {
    warnings.push({
      code: 'LEVELLING_TOLERANCE_WARNING',
      message: `Linear misclosure may exceed 10√K mm tolerance. Verify levelling computations per RDM 1.1 Table 5.1.`
    })
  }

  if (pkg.revision > 1) {
    warnings.push({
      code: 'MULTIPLE_REVISIONS',
      message: `This is revision R${pkg.revision.toString().padStart(2, '0')}. Ensure all previous comments from Director of Surveys have been addressed.`
    })
  }

  return {
    passed: blockers.length === 0,
    blockers,
    warnings
  }
}

export function getSubmissionChecklist(subtype: string): { code: string; label: string; required: boolean }[] {
  const surveyType = SUBTYPE_TO_SURVEY_TYPE[subtype] || 'cadastral'
  const minPrecision = TRAVERSE_PRECISION_STANDARDS[surveyType]
  
  const base = [
    { code: 'COORD_SYS', label: 'Coordinate system specified (Arc 1960 / UTM Zone 37S)', required: true },
    { code: 'SURVEYOR_PROFILE', label: 'Licensed surveyor profile complete (ISK Reg. No.)', required: true },
    { code: 'LR_NUMBER', label: 'LR Number specified', required: true },
    { code: 'COUNTY', label: 'County specified', required: true },
    { code: 'DISTRICT', label: 'District specified', required: true },
    { code: 'AREA_COMPUTED', label: 'Parcel area computed and > 0', required: true },
    { code: 'PRECISION', label: `Traverse precision meets 1:${minPrecision}`, required: true },
    { code: 'BEACONS', label: 'Beacon types and positions verified', required: true },
    { code: 'FORM_NO4', label: 'Form No. 4 (Mutation Form) generated', required: true },
    { code: 'DXF_PLAN', label: 'DXF plan with TitleBlock generated', required: true },
  ]

  const cadastralExtras = [
    { code: 'PPA2', label: 'PPA2 (Permission to Amend) attached', required: true },
    { code: 'LCB_CONSENT', label: 'Land Control Board consent attached', required: true },
    { code: 'BEACON_CERT', label: 'Beacon completion certificate attached', required: true },
    { code: 'SEARCH_CERT', label: 'Official search certificate attached', required: false },
  ]

  const topoExtras = [
    { code: 'CONTOURS', label: 'Contour interval matches spec', required: true },
    { code: 'SPOT_HEIGHTS', label: 'Spot heights verified against field book', required: true },
    { code: 'IDW_COMPUTED', label: 'IDW interpolation completed', required: true },
  ]

  const engineeringExtras = [
    { code: 'HORIZONTAL_CURVE', label: 'Horizontal curve computation verified', required: true },
    { code: 'SUPERELEVATION', label: 'Superelevation within RDM 1.1 limits', required: true },
    { code: 'VERTICAL_CURVE', label: 'Vertical curve K-value meets SSD requirements', required: true },
    { code: 'EARTHWORKS', label: 'Cross-section volumes computed', required: false },
  ]

  if (subtype.startsWith('cadastral')) {
    return [...base, ...cadastralExtras]
  }
  if (subtype.startsWith('topographic')) {
    return [...base, ...topoExtras]
  }
  if (subtype.startsWith('engineering')) {
    return [...base, ...engineeringExtras]
  }

  return base
}

/**
 * statutoryWorkbook.ts
 * Generates the 9-sheet statutory computation workbook for Metardu submissions.
 * Compliant with Kenya Survey Regulations 1994 and RDM 1.1 (2025).
 */

import ExcelJS from 'exceljs'
import { formatBearingDMS, formatDistanceM } from '@/lib/drawing/dxfLayers'

type SurveyTypeKey = 'cadastral' | 'engineering' | 'topographic' | 'leveling' | 'control' | 'mining' | 'hydrographic' | 'drone' | 'gnss'

export interface WorkbookInput {
  project: {
    name: string
    lrNumber: string
    parcelNumber: string
    county: string
    division: string
    district: string
    locality: string
    surveyType: SurveyTypeKey
    surveyDate: string
    scaleDenominator: number
  }
  surveyor: {
    name: string
    iskNumber: string
    firmName: string
  }
  submission: {
    referenceNumber: string
    revision: number
    status: string
  }
  fieldObservations: Array<{
    stationFrom: string
    stationTo: string
    observedBearingDeg?: number
    observedDistanceM?: number
    reducedLevelM?: number
    remarks?: string
  }>
  traverse: {
    method: 'bowditch' | 'transit'
    stations: Array<{
      label: string
      observedBearing: number
      observedDistance: number
      departureRaw: number
      latitudeRaw: number
      departureCorrected: number
      latitudeCorrected: number
      easting: number
      northing: number
    }>
    angularMisclosureSec: number
    angularToleranceSec: number
    angularPassesQA: boolean
    linearMisclosureM: number
    perimeterM: number
    precisionRatio: number
    precisionMinimum: number
    linearPassesQA: boolean
  }
  adjustedStations: Array<{
    label: string
    easting: number
    northing: number
    elevation?: number
  }>
  levelling: Array<{
    stationId: string
    backsight?: number
    intermediate?: number
    foresight?: number
    rise?: number
    fall?: number
    reducedLevel: number
    distance?: number
    remarks?: string
  }> | null
  levellingClosureMM?: number
  levellingToleranceMM?: number
  levellingDistanceKm?: number
  areaComputation: {
    stations: Array<{ label: string; easting: number; northing: number }>
    areaM2: number
    areaHa: number
    perimeterM: number
  }
  legs: Array<{
    fromLabel: string
    toLabel: string
    bearing: number
    distance: number
  }>
  cogoResults: Array<{
    type: string
    description: string
    inputs: Record<string, number | string>
    outputs: Record<string, number | string>
  }> | null
}

const STYLE = {
  headerFill: { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1B3A5C' } } as ExcelJS.Fill,
  headerFont: { bold: true, color: { argb: 'FFFFFFFF' }, size: 11, name: 'Calibri' } as ExcelJS.Font,
  titleFont: { bold: true, size: 14, name: 'Calibri' } as ExcelJS.Font,
  subFont: { bold: true, size: 11, name: 'Calibri' } as ExcelJS.Font,
  bodyFont: { size: 10, name: 'Calibri' } as ExcelJS.Font,
  passFont: { bold: true, color: { argb: 'FF006400' }, size: 10, name: 'Calibri' } as ExcelJS.Font,
  failFont: { bold: true, color: { argb: 'FFCC0000' }, size: 10, name: 'Calibri' } as ExcelJS.Font,
  border: {
    top: { style: 'thin' }, left: { style: 'thin' },
    bottom: { style: 'thin' }, right: { style: 'thin' },
  } as ExcelJS.Borders,
  altRowFill: { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF0F4F8' } } as ExcelJS.Fill,
}

function applyHeaderRow(row: ExcelJS.Row, columnCount: number): void {
  row.height = 20
  for (let c = 1; c <= columnCount; c++) {
    const cell = row.getCell(c)
    cell.fill = STYLE.headerFill
    cell.font = STYLE.headerFont
    cell.border = STYLE.border
    cell.alignment = { vertical: 'middle', horizontal: 'center' }
  }
}

function applyDataRow(row: ExcelJS.Row, columnCount: number, rowIndex: number): void {
  row.height = 16
  for (let c = 1; c <= columnCount; c++) {
    const cell = row.getCell(c)
    cell.font = STYLE.bodyFont
    cell.border = STYLE.border
    if (rowIndex % 2 === 0) cell.fill = STYLE.altRowFill
  }
}

function sheetTitle(sheet: ExcelJS.Worksheet, title: string, subtitle: string): void {
  sheet.mergeCells('A1:H1')
  const titleCell = sheet.getCell('A1')
  titleCell.value = title
  titleCell.font = STYLE.titleFont
  titleCell.alignment = { horizontal: 'center', vertical: 'middle' }
  sheet.getRow(1).height = 28

  sheet.mergeCells('A2:H2')
  const subCell = sheet.getCell('A2')
  subCell.value = subtitle
  subCell.font = STYLE.subFont
  subCell.alignment = { horizontal: 'center' }
  sheet.getRow(2).height = 20
}

function buildSheet1_ProjectDetails(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('1. Project Details')
  ws.columns = [{ width: 28 }, { width: 40 }, { width: 28 }, { width: 40 }]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', 'Sheet 1 of 9 — Project Details')
  ws.addRow([])

  const fields: [string, string, string, string][] = [
    ['Project Name', input.project.name, 'Reference No.', input.submission.referenceNumber],
    ['LR Number', input.project.lrNumber, 'Parcel Number', input.project.parcelNumber],
    ['County', input.project.county, 'Division', input.project.division],
    ['District', input.project.district, 'Locality', input.project.locality],
    ['Survey Type', input.project.surveyType.toUpperCase(), 'Survey Date', new Date(input.project.surveyDate).toLocaleDateString('en-GB')],
    ['Plan Scale', `1:${input.project.scaleDenominator}`, 'Revision', `R${String(input.submission.revision).padStart(2, '0')}`],
    ['', '', '', ''],
    ['Surveyor Name', input.surveyor.name, 'ISK Number', input.surveyor.iskNumber],
    ['Firm / Company', input.surveyor.firmName, 'Submission Status', input.submission.status.toUpperCase()],
  ]

  fields.forEach((row) => {
    const wsRow = ws.addRow(row)
    wsRow.height = 18
    ;[1, 3].forEach((col) => {
      wsRow.getCell(col).font = { bold: true, size: 10, name: 'Calibri' }
      wsRow.getCell(col).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE8EDF2' } }
    })
    wsRow.eachCell((cell) => { cell.border = STYLE.border })
  })

  ws.addRow([])
  ws.addRow(['CERTIFICATION'])
  const certRow = ws.lastRow!
  certRow.getCell(1).font = STYLE.subFont
  ws.addRow(['I certify that the computations in this workbook are correct and comply with the Kenya Survey Regulations 1994.'])
  ws.mergeCells(`A${ws.lastRow!.number}:H${ws.lastRow!.number}`)
  ws.addRow([])
  ws.addRow(['Signature: ___________________________', '', 'Date: _______________', ''])
  ws.addRow([`${input.surveyor.name} — ${input.surveyor.iskNumber}`, '', '', ''])
}

function buildSheet2_FieldAbstract(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('2. Field Abstract')
  ws.columns = [
    { key: 'from', width: 16 },
    { key: 'to', width: 16 },
    { key: 'bearing', width: 20 },
    { key: 'distance', width: 18 },
    { key: 'rl', width: 18 },
    { key: 'remarks', width: 30 },
  ]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', 'Sheet 2 of 9 — Field Abstract (Raw Observations)')
  ws.addRow([])

  const headers = ['Station From', 'Station To', 'Observed Bearing', 'Observed Distance (m)', 'Reduced Level (m)', 'Remarks']
  const hRow = ws.addRow(headers)
  applyHeaderRow(hRow, headers.length)

  if (input.fieldObservations.length === 0) {
    const r = ws.addRow(['Not applicable for this survey type'])
    ws.mergeCells(`A${r.number}:F${r.number}`)
    r.getCell(1).font = { ...STYLE.bodyFont, italic: true }
    return
  }

  input.fieldObservations.forEach((obs, i) => {
    const r = ws.addRow([
      obs.stationFrom,
      obs.stationTo,
      obs.observedBearingDeg !== undefined ? formatBearingDMS(obs.observedBearingDeg) : '',
      obs.observedDistanceM !== undefined ? formatDistanceM(obs.observedDistanceM) : '',
      obs.reducedLevelM !== undefined ? obs.reducedLevelM.toFixed(3) : '',
      obs.remarks ?? '',
    ])
    applyDataRow(r, headers.length, i)
  })
}

function buildSheet3_TraverseComputation(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('3. Traverse Computation')
  ws.columns = [
    { width: 12 },
    { width: 18 },
    { width: 16 },
    { width: 16 },
    { width: 16 },
    { width: 18 },
    { width: 18 },
    { width: 18 },
    { width: 18 },
  ]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', `Sheet 3 of 9 — Traverse Computation (${input.traverse.method === 'transit' ? 'Transit' : 'Bowditch'} Method)`)
  ws.addRow([])
  ws.addRow(['ANGULAR MISCLOSURE CHECK'])
  ws.lastRow!.getCell(1).font = STYLE.subFont
  ws.addRow([
    'Misclosure:', `${input.traverse.angularMisclosureSec.toFixed(1)}"`,
    'Tolerance:', `${input.traverse.angularToleranceSec.toFixed(1)}"`,
    'Station Count:', input.traverse.stations.length,
    'Result:', input.traverse.angularPassesQA ? 'PASS ' : 'FAIL [x]',
  ])
  const angRow = ws.lastRow!
  angRow.getCell(8).font = input.traverse.angularPassesQA ? STYLE.passFont : STYLE.failFont
  ws.addRow([])

  const headers = ['Station', 'Observed Bearing', 'Distance (m)', 'Dep. Raw (m)', 'Lat. Raw (m)', 'Dep. Corr. (m)', 'Lat. Corr. (m)', 'Dep. Adj. (m)', 'Lat. Adj. (m)']
  const hRow = ws.addRow(headers)
  applyHeaderRow(hRow, headers.length)

  let sumDepRaw = 0, sumLatRaw = 0, sumDepCorr = 0, sumLatCorr = 0

  input.traverse.stations.forEach((st, i) => {
    const r = ws.addRow([
      st.label,
      formatBearingDMS(st.observedBearing),
      formatDistanceM(st.observedDistance),
      st.departureRaw.toFixed(4),
      st.latitudeRaw.toFixed(4),
      (st.departureCorrected - st.departureRaw).toFixed(4),
      (st.latitudeCorrected - st.latitudeRaw).toFixed(4),
      st.departureCorrected.toFixed(4),
      st.latitudeCorrected.toFixed(4),
    ])
    applyDataRow(r, headers.length, i)
    sumDepRaw += st.departureRaw
    sumLatRaw += st.latitudeRaw
    sumDepCorr += st.departureCorrected
    sumLatCorr += st.latitudeCorrected
  })

  const totRow = ws.addRow([
    'TOTALS', '', formatDistanceM(input.traverse.perimeterM),
    sumDepRaw.toFixed(4), sumLatRaw.toFixed(4),
    '', '',
    sumDepCorr.toFixed(4), sumLatCorr.toFixed(4),
  ])
  totRow.eachCell((c) => { c.font = { bold: true, size: 10, name: 'Calibri' }; c.border = STYLE.border })

  ws.addRow([])
  ws.addRow(['LINEAR MISCLOSURE CHECK'])
  ws.lastRow!.getCell(1).font = STYLE.subFont
  ws.addRow([
    'Linear Misclosure:', `${input.traverse.linearMisclosureM.toFixed(4)} m`,
    'Perimeter:', `${formatDistanceM(input.traverse.perimeterM)} m`,
    'Precision:', `1:${input.traverse.precisionRatio.toLocaleString()}`,
    'Minimum:', `1:${input.traverse.precisionMinimum.toLocaleString()}`,
    'Result:', input.traverse.linearPassesQA ? 'PASS ' : 'FAIL [x]',
  ])
  const linRow = ws.lastRow!
  linRow.getCell(10).font = input.traverse.linearPassesQA ? STYLE.passFont : STYLE.failFont
}

function buildSheet4_Coordinates(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('4. Coordinates')
  ws.columns = [{ width: 14 }, { width: 22 }, { width: 22 }, { width: 18 }]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', 'Sheet 4 of 9 — Adjusted Coordinates (SRID 21037 — Arc 1960 / UTM Zone 37S)')
  ws.addRow([])
  ws.addRow(['Coordinate Reference System: Arc 1960 / UTM Zone 37S  |  EPSG: 21037  |  Units: Metres'])
  ws.mergeCells(`A${ws.lastRow!.number}:D${ws.lastRow!.number}`)
  ws.lastRow!.getCell(1).font = { italic: true, size: 9, name: 'Calibri' }
  ws.addRow([])

  const headers = ['Beacon / Station', 'Easting (m)', 'Northing (m)', 'Elevation (m)']
  const hRow = ws.addRow(headers)
  applyHeaderRow(hRow, headers.length)

  input.adjustedStations.forEach((st, i) => {
    const r = ws.addRow([
      st.label,
      st.easting.toFixed(3),
      st.northing.toFixed(3),
      st.elevation !== undefined ? st.elevation.toFixed(3) : '—',
    ])
    applyDataRow(r, headers.length, i)
    ;[2, 3, 4].forEach((c) => { r.getCell(c).alignment = { horizontal: 'right' } })
  })
}

function buildSheet5_Levelling(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('5. Levelling')
  ws.columns = [
    { width: 16 }, { width: 12 }, { width: 12 }, { width: 12 },
    { width: 12 }, { width: 12 }, { width: 16 }, { width: 14 }, { width: 24 },
  ]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', 'Sheet 5 of 9 — Levelling (Rise & Fall Method)')

  if (!input.levelling || input.levelling.length === 0) {
    ws.addRow([])
    const r = ws.addRow(['Not applicable for this survey type'])
    ws.mergeCells(`A${r.number}:I${r.number}`)
    r.getCell(1).font = { ...STYLE.bodyFont, italic: true }
    return
  }

  ws.addRow([])
  ws.addRow([
    'Distance (K):', `${input.levellingDistanceKm?.toFixed(3) ?? '—'} km`,
    'Tolerance (10√K):', `${input.levellingToleranceMM?.toFixed(1) ?? '—'} mm`,
    'Closure:', `${input.levellingClosureMM?.toFixed(1) ?? '—'} mm`,
    'Result:',
    Math.abs(input.levellingClosureMM ?? 0) <= (input.levellingToleranceMM ?? 0) ? 'PASS ' : 'FAIL [x]',
  ])
  ws.addRow([])

  const headers = ['Station', 'BS', 'IS', 'FS', 'Rise', 'Fall', 'RL (m)', 'Distance (m)', 'Remarks']
  const hRow = ws.addRow(headers)
  applyHeaderRow(hRow, headers.length)

  input.levelling.forEach((lv, i) => {
    const r = ws.addRow([
      lv.stationId,
      lv.backsight?.toFixed(3) ?? '',
      lv.intermediate?.toFixed(3) ?? '',
      lv.foresight?.toFixed(3) ?? '',
      lv.rise?.toFixed(3) ?? '',
      lv.fall?.toFixed(3) ?? '',
      lv.reducedLevel.toFixed(3),
      lv.distance?.toFixed(3) ?? '',
      lv.remarks ?? '',
    ])
    applyDataRow(r, headers.length, i)
  })
}

function buildSheet6_AreaComputation(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('6. Area Computation')
  ws.columns = [{ width: 14 }, { width: 20 }, { width: 20 }, { width: 24 }, { width: 24 }]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', 'Sheet 6 of 9 — Area Computation (Coordinate / Shoelace Method)')
  ws.addRow([])
  ws.addRow(['Method: Coordinate (Shoelace) Method  |  2A = |Σ(Ei × Ni+1) - Σ(Ni × Ei+1)|'])
  ws.mergeCells(`A${ws.lastRow!.number}:E${ws.lastRow!.number}`)
  ws.lastRow!.getCell(1).font = { italic: true, size: 9, name: 'Calibri' }
  ws.addRow([])

  const headers = ['Station', 'Easting (m)', 'Northing (m)', 'E × N(i+1)', 'N × E(i+1)']
  const hRow = ws.addRow(headers)
  applyHeaderRow(hRow, headers.length)

  const pts = input.areaComputation.stations
  const n = pts.length
  let sumENextN = 0, sumNNextE = 0

  pts.forEach((pt, i) => {
    const next = pts[(i + 1) % n]
    const eNextN = pt.easting * next.northing
    const nNextE = pt.northing * next.easting
    sumENextN += eNextN
    sumNNextE += nNextE
    const r = ws.addRow([pt.label, pt.easting.toFixed(3), pt.northing.toFixed(3), eNextN.toFixed(3), nNextE.toFixed(3)])
    applyDataRow(r, headers.length, i)
  })

  ws.addRow(['TOTALS', '', '', sumENextN.toFixed(3), sumNNextE.toFixed(3)])
    .eachCell((c) => { c.font = { bold: true, size: 10, name: 'Calibri' }; c.border = STYLE.border })

  ws.addRow([])
  ws.addRow(['2A =', `|${sumENextN.toFixed(3)} - ${sumNNextE.toFixed(3)}|`, '=', `${(Math.abs(sumENextN - sumNNextE)).toFixed(3)} m²`])
  ws.addRow(['Area =', `${input.areaComputation.areaM2.toFixed(3)} m²`])
  ws.addRow(['Area =', `${input.areaComputation.areaHa.toFixed(4)} Ha`])
  ws.addRow(['Perimeter =', `${formatDistanceM(input.areaComputation.perimeterM)} m`])
}

function buildSheet7_BearingsDistances(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('7. Bearings & Distances')
  ws.columns = [{ width: 16 }, { width: 16 }, { width: 22 }, { width: 20 }]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', 'Sheet 7 of 9 — Bearing & Distance Schedule')
  ws.addRow([])

  const headers = ['From Beacon', 'To Beacon', 'Bearing (DDD°MM\'SS")', 'Distance (m)']
  const hRow = ws.addRow(headers)
  applyHeaderRow(hRow, headers.length)

  input.legs.forEach((leg, i) => {
    const r = ws.addRow([leg.fromLabel, leg.toLabel, formatBearingDMS(leg.bearing), formatDistanceM(leg.distance)])
    applyDataRow(r, headers.length, i)
  })
}

function buildSheet8_COGO(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('8. COGO & Setting Out')
  ws.columns = [{ width: 22 }, { width: 30 }, { width: 28 }, { width: 28 }]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', 'Sheet 8 of 9 — COGO & Setting Out Computations')

  if (!input.cogoResults || input.cogoResults.length === 0) {
    ws.addRow([])
    const r = ws.addRow(['No COGO or setting-out computations recorded for this project.'])
    ws.mergeCells(`A${r.number}:D${r.number}`)
    r.getCell(1).font = { ...STYLE.bodyFont, italic: true }
    return
  }

  ws.addRow([])
  const headers = ['Computation Type', 'Description', 'Inputs', 'Outputs']
  const hRow = ws.addRow(headers)
  applyHeaderRow(hRow, headers.length)

  input.cogoResults.forEach((result, i) => {
    const r = ws.addRow([
      result.type.replace(/_/g, ' ').toUpperCase(),
      result.description,
      Object.entries(result.inputs).map(([k, v]) => `${k}: ${v}`).join('\n'),
      Object.entries(result.outputs).map(([k, v]) => `${k}: ${v}`).join('\n'),
    ])
    applyDataRow(r, headers.length, i)
  })
}

function buildSheet9_QASummary(wb: ExcelJS.Workbook, input: WorkbookInput): void {
  const ws = wb.addWorksheet('9. QA Summary')
  ws.columns = [{ width: 32 }, { width: 22 }, { width: 22 }, { width: 14 }]

  sheetTitle(ws, 'METARDU COMPUTATION WORKBOOK', 'Sheet 9 of 9 — Quality Assurance Summary')
  ws.addRow([])

  const headers = ['Quality Check', 'Computed Value', 'Standard / Tolerance', 'Result']
  const hRow = ws.addRow(headers)
  applyHeaderRow(hRow, headers.length)

  const checks: [string, string, string, boolean | null][] = [
    ['Angular Misclosure', `${input.traverse.angularMisclosureSec.toFixed(1)}"`, `≤ ${input.traverse.angularToleranceSec.toFixed(1)}" (60√n)`, input.traverse.angularPassesQA],
    ['Linear Misclosure Precision', `1:${input.traverse.precisionRatio.toLocaleString()}`, `≥ 1:${input.traverse.precisionMinimum.toLocaleString()} (Kenya Survey Regs 1994)`, input.traverse.linearPassesQA],
    ['Levelling Closure', input.levellingClosureMM !== undefined ? `${input.levellingClosureMM.toFixed(1)} mm` : 'N/A', input.levellingToleranceMM !== undefined ? `≤ ${input.levellingToleranceMM.toFixed(1)} mm (10√K, RDM 1.1)` : 'N/A', input.levellingClosureMM !== undefined && input.levellingToleranceMM !== undefined ? Math.abs(input.levellingClosureMM) <= input.levellingToleranceMM : null],
    ['Adjusted Departure Sum (ΣDep)', `${input.traverse.stations.reduce((s, st) => s + st.departureCorrected, 0).toFixed(4)} m`, '≈ 0.0000 m', Math.abs(input.traverse.stations.reduce((s, st) => s + st.departureCorrected, 0)) < 0.001],
    ['Adjusted Latitude Sum (ΣLat)', `${input.traverse.stations.reduce((s, st) => s + st.latitudeCorrected, 0).toFixed(4)} m`, '≈ 0.0000 m', Math.abs(input.traverse.stations.reduce((s, st) => s + st.latitudeCorrected, 0)) < 0.001],
    ['Coordinate Reference System', 'SRID 21037 — Arc 1960 / UTM Zone 37S', 'SRID 21037 required', true],
    ['Adjustment Method', input.traverse.method === 'transit' ? 'Transit' : 'Bowditch', 'Bowditch or Transit', true],
  ]

  checks.forEach((check, i) => {
    const [label, value, standard, passes] = check
    const r = ws.addRow([label, value, standard, passes === null ? 'N/A' : passes ? 'PASS ' : 'FAIL [x]'])
    applyDataRow(r, headers.length, i)
    if (passes !== null) r.getCell(4).font = passes ? STYLE.passFont : STYLE.failFont
  })

  const allPass = checks.every(([,,,p]) => p === null || p === true)
  ws.addRow([])
  const overallRow = ws.addRow(['OVERALL QA RESULT', '', '', allPass ? 'ALL CHECKS PASS ' : 'ONE OR MORE CHECKS FAIL [x]'])
  overallRow.height = 22
  overallRow.getCell(1).font = { bold: true, size: 12, name: 'Calibri' }
  overallRow.getCell(4).font = { bold: true, size: 12, name: 'Calibri', color: { argb: allPass ? 'FF006400' : 'FFCC0000' } }
  ws.mergeCells(`A${overallRow.number}:C${overallRow.number}`)

  ws.addRow([])
  ws.addRow(['SURVEYOR CERTIFICATION'])
  ws.lastRow!.getCell(1).font = STYLE.subFont
  ws.addRow([`I, ${input.surveyor.name} (${input.surveyor.iskNumber}), certify that the computations in this workbook are correct.`])
  ws.mergeCells(`A${ws.lastRow!.number}:D${ws.lastRow!.number}`)
  ws.addRow([])
  ws.addRow(['Signature: _________________________', '', `Date: ${new Date().toLocaleDateString('en-GB')}`, ''])
}

export async function generateStatutoryWorkbook(input: WorkbookInput): Promise<Buffer> {
  const wb = new ExcelJS.Workbook()
  wb.creator = 'Metardu Platform'
  wb.created = new Date()
  wb.modified = new Date()

  buildSheet1_ProjectDetails(wb, input)
  buildSheet2_FieldAbstract(wb, input)
  buildSheet3_TraverseComputation(wb, input)
  buildSheet4_Coordinates(wb, input)
  buildSheet5_Levelling(wb, input)
  buildSheet6_AreaComputation(wb, input)
  buildSheet7_BearingsDistances(wb, input)
  buildSheet8_COGO(wb, input)
  buildSheet9_QASummary(wb, input)

  const buffer = await wb.xlsx.writeBuffer()
  return Buffer.from(buffer)
}

