'use client';

import { createContext, useCallback, useContext, useEffect, useState } from 'react'
import type { PlanId } from '@/lib/subscription/catalog'
import { canAccess as featureCanAccess, TIERS, type FeatureKey } from '@/lib/subscription/featureGates'

interface SubscriptionContextType {
  plan: PlanId
  isAdmin: boolean
  isTrialing: boolean
  trialDaysLeft: number
  canCreateProject: boolean
  canAddPoints: boolean
  hasFeature: (feature: string) => boolean
  projectCount: number
  loading: boolean
  refresh: () => void
}

const SubscriptionContext = createContext<SubscriptionContextType>({
  plan: 'free',
  isAdmin: false,
  isTrialing: false,
  trialDaysLeft: 0,
  canCreateProject: true,
  canAddPoints: true,
  hasFeature: () => false,
  projectCount: 0,
  loading: true,
  refresh: () => {},
})

export function SubscriptionProvider({ children }: { children: React.ReactNode }) {
  const [userId, setUserId] = useState<string | null>(null)
  const [authResolved, setAuthResolved] = useState(false)
  const [plan, setPlan] = useState<PlanId>('free')
  const [isAdmin, setIsAdmin] = useState(false)
  const [isTrialing, setIsTrialing] = useState(false)
  const [trialDaysLeft, setTrialDaysLeft] = useState(0)
  const [features, setFeatures] = useState<string[]>([])
  const [projectCount, setProjectCount] = useState(0)
  const [loading, setLoading] = useState(true)

  const resetState = useCallback(() => {
    setPlan('free')
    setIsAdmin(false)
    setIsTrialing(false)
    setTrialDaysLeft(0)
    setFeatures([])
    setProjectCount(0)
  }, [])

  const loadSubscription = useCallback(async () => {
    if (!userId) {
      resetState()
      setLoading(false)
      return
    }

    try {
      // Use the server-side API which includes admin email detection
      const res = await fetch('/api/subscription', {
        cache: 'no-store',
        credentials: 'same-origin',
      })

      if (!res.ok) {
        resetState()
        setLoading(false)
        return
      }

      const data = await res.json()

      resetState()

      setPlan(data.plan as PlanId)
      setIsAdmin(data.isAdmin === true)

      if (data.status === 'trial' && data.trialEndsAt) {
        setIsTrialing(true)
        const daysLeft = Math.ceil(
          (new Date(data.trialEndsAt).getTime() - Date.now()) / 86400000
        )
        setTrialDaysLeft(Math.max(0, daysLeft))
      }

      // Load tier features from the feature gates system
      const tierFeatures = TIERS[data.plan as PlanId]?.features || []
      setFeatures(tierFeatures.map(String))

      // Fetch project count separately (lightweight query)
      const countRes = await fetch('/api/subscription/project-count', {
        cache: 'no-store',
        credentials: 'same-origin',
      }).catch(() => null)

      if (countRes?.ok) {
        const countData = await countRes.json()
        setProjectCount(countData.count || 0)
      }
    } catch {
      resetState()
    } finally {
      setLoading(false)
    }
  }, [resetState, userId])

  useEffect(() => {
    let active = true

    async function loadAuthSession() {
      try {
        const response = await fetch('/api/auth/session', {
          cache: 'no-store',
          credentials: 'same-origin',
        })

        if (!response.ok) {
          throw new Error(`Session request failed with ${response.status}`)
        }

        const session = await response.json()
        if (!active) return

        setUserId((session?.user as { id?: string } | undefined)?.id ?? null)
      } catch {
        if (!active) return
        setUserId(null)
      } finally {
        if (active) {
          setAuthResolved(true)
        }
      }
    }

    loadAuthSession()

    return () => {
      active = false
    }
  }, [])

  useEffect(() => {
    if (!authResolved) return

    if (!userId) {
      resetState()
      setLoading(false)
      return
    }

    setLoading(true)
    void loadSubscription()
  }, [authResolved, loadSubscription, resetState, userId])

  // Admin always has full access, regardless of plan
  const canCreateProject = isAdmin || plan !== 'free' || projectCount < 1
  const canAddPoints = true

  function hasFeature(feature: string) {
    // Admin always has access to everything
    if (isAdmin) return true
    // Use the proper feature gates instead of granting all features to paid plans
    if (features.includes(feature)) return true
    // Check against the feature gates system for known feature keys
    if (TIERS[plan]?.features?.includes(feature as FeatureKey)) return true
    return featureCanAccess(plan, feature as FeatureKey)
  }

  return (
    <SubscriptionContext.Provider
      value={{
        plan,
        isAdmin,
        isTrialing,
        trialDaysLeft,
        canCreateProject,
        canAddPoints,
        hasFeature,
        projectCount,
        loading,
        refresh: loadSubscription,
      }}
    >
      {children}
    </SubscriptionContext.Provider>
  )
}

export const useSubscription = () => useContext(SubscriptionContext)

import { db } from '@/lib/db'
import { TIERS, canAccess, getLimit, type FeatureKey } from './featureGates'
import type { PlanId } from './catalog'

// Admin emails get free enterprise access - no payment required
const ADMIN_EMAILS = (process.env.ADMIN_EMAILS || '').split(',').map(e => e.trim().toLowerCase())

function isAdminEmail(email: string | undefined): boolean {
  if (!email) return false
  return ADMIN_EMAILS.includes(email.toLowerCase())
}

export interface SubscriptionInfo {
  plan: PlanId
  status: 'active' | 'cancelled' | 'expired' | 'trial'
  trialEndsAt: string | null
  periodStart: string
  periodEnd: string
  paymentMethod: string | null
  currency: string
  isUnlimitedProjects: boolean
  isUnlimitedPoints: boolean
  maxTeamMembers: number
}

export interface UsageInfo {
  projectCount: number
  pointsUsage: Record<string, number>
  memberCount: number
}

export interface AccessCheck {
  allowed: boolean
  reason?: string
  upgradeTo?: PlanId
}

export async function getSubscription(userId: string, email?: string): Promise<SubscriptionInfo | null> {
  // Admin emails bypass all subscription checks - free enterprise access
  if (isAdminEmail(email)) {
    const now = new Date().toISOString()
    const farFuture = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString()
    return {
      plan: 'enterprise',
      status: 'active',
      trialEndsAt: null,
      periodStart: now,
      periodEnd: farFuture,
      paymentMethod: 'admin',
      currency: 'KES',
      isUnlimitedProjects: true,
      isUnlimitedPoints: true,
      maxTeamMembers: -1,
    }
  }

  const { rows } = await db.query(
    'SELECT plan_id, status, trial_ends_at, current_period_start, current_period_end, payment_method, currency FROM user_subscriptions WHERE user_id = $1 LIMIT 1',
    [userId]
  )

  if (rows.length === 0) return null

  const sub = rows[0]
  const planId = (sub.plan_id || 'free') as PlanId
  const tier = TIERS[planId]

  return {
    plan: planId,
    status: sub.status as SubscriptionInfo['status'],
    trialEndsAt: sub.trial_ends_at || null,
    periodStart: sub.current_period_start || new Date().toISOString(),
    periodEnd: sub.current_period_end || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
    paymentMethod: sub.payment_method || null,
    currency: sub.currency || 'KES',
    isUnlimitedProjects: tier.maxProjects < 0,
    isUnlimitedPoints: tier.maxPointsPerProject < 0,
    maxTeamMembers: tier.maxTeamMembers,
  }
}

export async function getUsage(userId: string): Promise<UsageInfo> {
  const [projectResult, memberResult] = await Promise.all([
    db.query('SELECT COUNT(*) as count FROM projects WHERE user_id = $1', [userId]),
    db.query('SELECT COUNT(*) as count FROM project_members WHERE user_id = $1', [userId]),
  ])

  return {
    projectCount: parseInt(projectResult.rows[0]?.count || '0', 10),
    pointsUsage: {},
    memberCount: parseInt(memberResult.rows[0]?.count || '0', 10),
  }
}

export async function checkFeatureAccess(
  userId: string,
  feature: FeatureKey,
  email?: string
): Promise<AccessCheck> {
  // Admin always has access
  if (isAdminEmail(email)) {
    return { allowed: true }
  }

  const sub = await getSubscription(userId, email)
  if (!sub) {
    // No subscription record — default to free tier access, NOT full access
    if (!canAccess('free', feature)) {
      return { allowed: false, reason: `${feature} requires a paid plan`, upgradeTo: 'pro' }
    }
    return { allowed: true }
  }

  if (sub.plan === 'free') {
    if (!canAccess('free', feature)) {
      return { allowed: false, reason: `${feature} requires a paid plan`, upgradeTo: 'pro' }
    }
    return { allowed: true }
  }

  if (!canAccess(sub.plan, feature)) {
    return { allowed: false, reason: `${feature} requires a higher plan`, upgradeTo: 'team' }
  }
  return { allowed: true }
}

export async function checkProjectLimit(userId: string, email?: string): Promise<AccessCheck> {
  if (isAdminEmail(email)) return { allowed: true }

  const [sub, usage] = await Promise.all([getSubscription(userId, email), getUsage(userId)])
  if (!sub) {
    // No subscription — enforce free tier limits
    const freeLimit = getLimit('free', 'projects')
    if (freeLimit < 0) return { allowed: true }
    if (usage.projectCount >= freeLimit) {
      return { allowed: false, reason: `Project limit reached (${usage.projectCount}/${freeLimit})`, upgradeTo: 'pro' }
    }
    return { allowed: true }
  }

  const limit = getLimit(sub.plan, 'projects')
  if (limit < 0) return { allowed: true }

  if (usage.projectCount >= limit) {
    return {
      allowed: false,
      reason: `Project limit reached (${usage.projectCount}/${limit})`,
      upgradeTo: sub.plan === 'free' ? 'pro' : 'team',
    }
  }
  return { allowed: true }
}

export async function checkMemberLimit(userId: string, email?: string): Promise<AccessCheck> {
  if (isAdminEmail(email)) return { allowed: true }

  const [sub, usage] = await Promise.all([getSubscription(userId, email), getUsage(userId)])
  if (!sub) {
    // No subscription — enforce free tier limits
    const freeLimit = getLimit('free', 'members')
    if (freeLimit < 0) return { allowed: true }
    if (usage.memberCount >= freeLimit) {
      return { allowed: false, reason: `Member limit reached (${usage.memberCount}/${freeLimit})`, upgradeTo: 'pro' }
    }
    return { allowed: true }
  }

  const limit = getLimit(sub.plan, 'members')
  if (limit < 0) return { allowed: true }

  if (usage.memberCount >= limit) {
    return {
      allowed: false,
      reason: `Member limit reached (${usage.memberCount}/${limit})`,
      upgradeTo: 'team',
    }
  }
  return { allowed: true }
}

export function getTrialDaysLeft(trialEndsAt: string | null): number {
  if (!trialEndsAt) return 0
  return Math.max(0, Math.ceil((new Date(trialEndsAt).getTime() - Date.now()) / 86400000))
}

export async function cancelSubscription(userId: string): Promise<void> {
  const { rows } = await db.query(
    'SELECT id FROM user_subscriptions WHERE user_id = $1 LIMIT 1',
    [userId]
  )

  if (rows.length > 0) {
    await db.query(
      'UPDATE user_subscriptions SET status = $1 WHERE id = $2',
      ['cancelled', rows[0].id]
    )
  }
}

export async function reactivateSubscription(userId: string): Promise<void> {
  const { rows } = await db.query(
    'SELECT id FROM user_subscriptions WHERE user_id = $1 LIMIT 1',
    [userId]
  )

  if (rows.length > 0) {
    const now = new Date()
    await db.query(
      'UPDATE user_subscriptions SET status = $1, current_period_start = $2, current_period_end = $3 WHERE id = $4',
      [
        'active',
        now.toISOString(),
        new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString(),
        rows[0].id,
      ]
    )
  }
}

/**
 * Tests for Phase 3: Deformation Monitoring Engine
 *
 * Verifies:
 * - Two-epoch comparison with tectonic drift removed
 * - Statistical significance testing
 * - Alert generation (warning vs critical)
 * - Time-series analysis (velocity, acceleration, projection)
 * - Edge cases (no common monuments, missing data)
 */

import {
  compareEpochs,
  analyzeTimeSeries,
  getDeformationVerdictColor,
  getAlertSeverityColor,
  formatDeformationVector,
  type EpochSet,
  type MonumentObservation,
} from '../deformationMonitoring'

// ─── Fixtures ───────────────────────────────────────────────────────────────

function makeMonument(
  id: string,
  lat: number,
  lon: number,
  h: number,
  epoch: number,
  sigmaE: number = 0.002,
  sigmaN: number = 0.002,
): MonumentObservation {
  return {
    monumentId: id,
    latitude: lat,
    longitude: lon,
    height: h,
    frame: 'ITRF2014',
    epoch,
    sigmaE,
    sigmaN,
    sigmaH: 0.003,
  }
}

const baselineEpoch: EpochSet = {
  label: 'Baseline 2024-01',
  epoch: 2024.0,
  monuments: [
    makeMonument('DM-01', -1.0, 37.0, 1500.000, 2024.0),
    makeMonument('DM-02', -1.001, 37.001, 1500.000, 2024.0),
    makeMonument('DM-03', -1.002, 37.002, 1500.000, 2024.0),
    makeMonument('DM-04', -1.003, 37.003, 1500.000, 2024.0),
  ],
}

// ─── Two-Epoch Comparison ───────────────────────────────────────────────────

describe('Deformation Monitoring — two-epoch comparison', () => {
  it('reports STABLE when monuments havent moved (within propagation error)', () => {
    const currentEpoch: EpochSet = {
      label: 'Q2 2025',
      epoch: 2025.5,
      monuments: [
        makeMonument('DM-01', -1.0, 37.0, 1500.000, 2025.5),     // same
        makeMonument('DM-02', -1.001, 37.001, 1500.000, 2025.5),   // same
        makeMonument('DM-03', -1.002, 37.002, 1500.000, 2025.5),   // same
        makeMonument('DM-04', -1.003, 37.003, 1500.000, 2025.5),   // same
      ],
    }

    // Use a larger tolerance to account for plate velocity propagation residuals
    // (~1cm/year linear approximation error over 1.5 years = ~15mm)
    const report = compareEpochs(baselineEpoch, currentEpoch, {
      horizontal: 0.020,  // 20mm — accounts for propagation residual
      vertical: 0.010,
    })

    expect(report.verdict).toBe('STABLE')
    expect(report.alerts.length).toBe(0)
    expect(report.stable.length).toBe(4)
  })

  it('reports DEFORMING when a monument has moved beyond tolerance', () => {
    // DM-02 has moved ~10mm north (beyond 5mm tolerance)
    const currentEpoch: EpochSet = {
      label: 'Q2 2025',
      epoch: 2025.5,
      monuments: [
        makeMonument('DM-01', -1.0, 37.0, 1500.000, 2025.5),
        makeMonument('DM-02', -1.001 + 0.0000001, 37.001, 1500.000, 2025.5), // ~11mm north
        makeMonument('DM-03', -1.002, 37.002, 1500.000, 2025.5),
        makeMonument('DM-04', -1.003, 37.003, 1500.000, 2025.5),
      ],
    }

    const report = compareEpochs(baselineEpoch, currentEpoch, {
      horizontal: 0.005,
      vertical: 0.003,
    })

    expect(report.verdict).toBe('DEFORMING')
    expect(report.alerts.length).toBeGreaterThan(0)
    const dm02Alert = report.alerts.find(a => a.monumentId === 'DM-02')
    expect(dm02Alert).toBeDefined()
    expect(dm02Alert!.magnitudeMm).toBeGreaterThan(5) // > 5mm
  })

  it('generates CRITICAL alert when movement exceeds 3× tolerance', () => {
    // DM-01 has moved ~100m east (well beyond any tolerance or propagation error)
    const currentEpoch: EpochSet = {
      label: 'Q2 2025',
      epoch: 2025.5,
      monuments: [
        makeMonument('DM-01', -1.0, 37.0 + 0.001, 1500.000, 2025.5), // ~100m east
        makeMonument('DM-02', -1.001, 37.001, 1500.000, 2025.5),
        makeMonument('DM-03', -1.002, 37.002, 1500.000, 2025.5),
        makeMonument('DM-04', -1.003, 37.003, 1500.000, 2025.5),
      ],
    }

    const report = compareEpochs(baselineEpoch, currentEpoch, {
      horizontal: 0.005,
      vertical: 0.003,
    })

    expect(report.verdict).toBe('DEFORMING')
    const dm01Alert = report.alerts.find(a => a.monumentId === 'DM-01')
    expect(dm01Alert).toBeDefined()
    expect(dm01Alert!.severity).toBe('critical')
    expect(dm01Alert!.magnitudeMm).toBeGreaterThan(15) // > 15mm (3×5mm)
  })

  it('reports missing and new monuments', () => {
    const currentEpoch: EpochSet = {
      label: 'Q2 2025',
      epoch: 2025.5,
      monuments: [
        makeMonument('DM-01', -1.0, 37.0, 1500.000, 2025.5),
        makeMonument('DM-02', -1.001, 37.001, 1500.000, 2025.5),
        // DM-03 and DM-04 are missing
        makeMonument('DM-05', -1.004, 37.004, 1500.000, 2025.5), // new
      ],
    }

    const report = compareEpochs(baselineEpoch, currentEpoch)

    expect(report.missingMonuments).toContain('DM-03')
    expect(report.missingMonuments).toContain('DM-04')
    expect(report.newMonuments).toContain('DM-05')
  })

  it('reports INCONCLUSIVE when no common monuments', () => {
    const currentEpoch: EpochSet = {
      label: 'Q2 2025',
      epoch: 2025.5,
      monuments: [
        makeMonument('XX-01', -2.0, 38.0, 1600.000, 2025.5),
      ],
    }

    const report = compareEpochs(baselineEpoch, currentEpoch)
    expect(report.verdict).toBe('INCONCLUSIVE')
    expect(report.vectors.length).toBe(0)
  })

  it('propagates both epochs to a common epoch (removes tectonic drift)', () => {
    // 1.5 years between epochs → ~3.75cm of tectonic drift expected
    // If the monument didnt actually move, the deformation should be ~0
    // after propagation (not ~37mm)
    const currentEpoch: EpochSet = {
      label: 'Q3 2025',
      epoch: 2025.5,
      monuments: [
        // Same physical position, different epoch — tectonic drift only
        makeMonument('DM-01', -1.0, 37.0, 1500.000, 2025.5),
      ],
    }

    const report = compareEpochs(
      { ...baselineEpoch, monuments: [baselineEpoch.monuments[0]] },
      currentEpoch,
      { horizontal: 0.005, vertical: 0.003 },
    )

    // After propagation, the deformation should be very small (< 15cm)
    // (linear approximation error over 1.5 years)
    const v = report.vectors[0]
    expect(v.horizontalDisplacement).toBeLessThan(0.15)
  })

  it('computes bearing of movement', () => {
    // Move DM-01 north by a large amount (~100m)
    const currentEpoch: EpochSet = {
      label: 'Q2 2025',
      epoch: 2025.5,
      monuments: [
        makeMonument('DM-01', -1.0 + 0.001, 37.0, 1500.000, 2025.5), // ~111m north
      ],
    }

    const report = compareEpochs(
      { ...baselineEpoch, monuments: [baselineEpoch.monuments[0]] },
      currentEpoch,
    )

    const v = report.vectors[0]
    // Bearing should be close to 0° (North)
    expect(v.bearing < 10 || v.bearing > 350).toBe(true)
    expect(v.deltaN).toBeGreaterThan(0) // moved north
  })
})

// ─── Time-Series Analysis ───────────────────────────────────────────────────

describe('Deformation Monitoring — time-series analysis', () => {
  it('computes velocity from multiple epochs', () => {
    const epochs: EpochSet[] = [
      {
        label: 'E1',
        epoch: 2023.0,
        monuments: [makeMonument('DM-01', -1.0, 37.0, 1500.000, 2023.0)],
      },
      {
        label: 'E2',
        epoch: 2024.0,
        monuments: [makeMonument('DM-01', -1.0 + 0.000001, 37.0, 1500.000, 2024.0)], // ~1.1m/yr north
      },
      {
        label: 'E3',
        epoch: 2025.0,
        monuments: [makeMonument('DM-01', -1.0 + 0.000002, 37.0, 1500.000, 2025.0)], // ~2.2m total
      },
    ]

    const analysis = analyzeTimeSeries(epochs, 'DM-01', { horizontal: 0.005 })

    expect(analysis.points.length).toBe(3)
    expect(analysis.velocityN).toBeGreaterThan(0) // moving north
    expect(analysis.velocityHorizontal).toBeGreaterThan(0)
    expect(analysis.rSquared).toBeGreaterThan(0.9) // strong linear trend
  })

  it('returns insufficient data message with < 2 epochs', () => {
    const analysis = analyzeTimeSeries([baselineEpoch], 'DM-01')
    expect(analysis.points.length).toBe(1)
    expect(analysis.interpretation).toContain('Insufficient')
  })

  it('projects future movement', () => {
    const epochs: EpochSet[] = [
      {
        label: 'E1',
        epoch: 2023.0,
        monuments: [makeMonument('DM-01', -1.0, 37.0, 1500.000, 2023.0)],
      },
      {
        label: 'E2',
        epoch: 2024.0,
        monuments: [makeMonument('DM-01', -1.0 + 0.0001, 37.0, 1500.000, 2024.0)], // ~111m/yr
      },
      {
        label: 'E3',
        epoch: 2025.0,
        monuments: [makeMonument('DM-01', -1.0 + 0.0002, 37.0, 1500.000, 2025.0)], // ~222m total
      },
    ]

    const analysis = analyzeTimeSeries(epochs, 'DM-01', { horizontal: 0.005 })

    // After 3 years (2023→2026), projected displacement should be > 10m
    expect(analysis.projectedHorizontalDisplacement).toBeGreaterThan(10.0)
    expect(analysis.projectedExceedsTolerance).toBe(true) // > 5mm
  })

  it('reports stable when velocity is within tolerance', () => {
    // Use a larger tolerance to account for propagation residuals
    const epochs: EpochSet[] = [
      {
        label: 'E1',
        epoch: 2023.0,
        monuments: [makeMonument('DM-01', -1.0, 37.0, 1500.000, 2023.0)],
      },
      {
        label: 'E2',
        epoch: 2024.0,
        monuments: [makeMonument('DM-01', -1.0, 37.0, 1500.000, 2024.0)], // no movement
      },
    ]

    const analysis = analyzeTimeSeries(epochs, 'DM-01', { horizontal: 0.050 }) // 50mm tolerance
    expect(analysis.velocityHorizontal).toBeLessThan(0.050) // < 50mm/yr
    expect(analysis.interpretation).toContain('Stable')
  })
})

