/**
 * Circular Curve Calculations
 * 
 * Horizontal circular curve computations for road and railway design.
 * Handles simple curves, compound curves, and reverse curves.
 * 
 * References:
 * - Schofield, W. (2001) "Engineering Surveying"
 * - Meyer, C.F. (1969) "Route Surveying and Design"
 */

// ─── Types ───────────────────────────────────────────────────────

export interface CircularCurveParams {
  /** Intersection angle (decimal degrees) — total deflection */
  intersectionAngle: number;
  /** Radius of the curve (meters) */
  radius: number;
}

export interface CircularCurveResult {
  /** Intersection angle (decimal degrees) */
  intersectionAngle: number;
  /** Radius (meters) */
  radius: number;
  /** Tangent length (meters) — PI to PC or PI to PT */
  tangentLength: number;
  /** Curve length (meters) — arc from PC to PT */
  curveLength: number;
  /** Length of long chord (meters) — straight line PC to PT */
  longChordLength: number;
  /** Mid-ordinate (meters) — distance from midpoint of long chord to curve */
  midOrdinate: number;
  /** External distance (meters) — distance from PI to curve midpoint */
  externalDistance: number;
  /** Degree of curvature (decimal degrees) — based on arc definition */
  degreeOfCurvature: number;
  /** Deflection angle to any point on curve (for setting out) */
  deflectionPerMeter: number; // degrees per meter of arc
}

export interface CurveStationResult {
  /** Chainage/station (meters) */
  chainage: number;
  /** Deflection angle from PC (decimal degrees) */
  deflectionAngle: number;
  /** Chord length from PC (meters) */
  chordLength: number;
  /** Easting coordinate */
  easting?: number;
  /** Northing coordinate */
  northing?: number;
}

// ─── Core Functions ──────────────────────────────────────────────

/**
 * Compute circular curve parameters from intersection angle and radius.
 * 
 * Standard formulas:
 *   T = R × tan(Δ/2)          — Tangent length
 *   L = R × Δ × (π/180)       — Curve length (arc)
 *   LC = 2R × sin(Δ/2)        — Long chord
 *   M = R × (1 - cos(Δ/2))    — Mid-ordinate
 *   E = R × (sec(Δ/2) - 1)    — External distance
 *   D = 5729.578 / R           — Degree of curvature (arc definition, 30m arc)
 */
export function computeCircularCurve(params: CircularCurveParams): CircularCurveResult {
  const { intersectionAngle, radius } = params;
  
  const deltaRad = intersectionAngle * Math.PI / 180;
  const halfDelta = deltaRad / 2;
  
  const tangentLength = radius * Math.tan(halfDelta);
  const curveLength = radius * deltaRad;
  const longChordLength = 2 * radius * Math.sin(halfDelta);
  const midOrdinate = radius * (1 - Math.cos(halfDelta));
  const externalDistance = radius * (1 / Math.cos(halfDelta) - 1);
  const degreeOfCurvature = 5729.578 / radius; // Arc definition (30m arc)
  const deflectionPerMeter = (intersectionAngle / 2) / curveLength; // degrees per meter
  
  return {
    intersectionAngle,
    radius,
    tangentLength: Math.round(tangentLength * 1000) / 1000,
    curveLength: Math.round(curveLength * 1000) / 1000,
    longChordLength: Math.round(longChordLength * 1000) / 1000,
    midOrdinate: Math.round(midOrdinate * 1000) / 1000,
    externalDistance: Math.round(externalDistance * 1000) / 1000,
    degreeOfCurvature: Math.round(degreeOfCurvature * 10000) / 10000,
    deflectionPerMeter: Math.round(deflectionPerMeter * 1000000) / 1000000,
  };
}

/**
 * Compute setting-out data for a circular curve at regular intervals.
 * 
 * Generates deflection angles and chord lengths for each station
 * along the curve, suitable for field stakeout.
 * 
 * @param curve - Circular curve parameters (from computeCircularCurve)
 * @param interval - Station interval (meters), default 10m
 * @param pcChainage - Chainage of PC (Point of Curvature)
 * @param pcEasting - Easting of PI (Point of Intersection)
 * @param pcNorthing - Northing of PI
 * @param backBearing - Bearing from PI to PC (decimal degrees)
 */
export function computeCurveStations(
  curve: CircularCurveResult,
  interval: number = 10,
  pcChainage: number = 0,
  piEasting?: number,
  piNorthing?: number,
  backBearing?: number,
): CurveStationResult[] {
  const stations: CurveStationResult[] = [];
  
  // PC station
  const pcDeflection = 0;
  stations.push({
    chainage: pcChainage,
    deflectionAngle: 0,
    chordLength: 0,
  });
  
  // Intermediate stations
  const numStations = Math.floor(curve.curveLength / interval);
  
  for (let i = 1; i <= numStations; i++) {
    const arcLength = i * interval;
    const deflectionAngle = arcLength * curve.deflectionPerMeter;
    const chordLength = 2 * curve.radius * Math.sin(deflectionAngle * Math.PI / 180);
    
    stations.push({
      chainage: pcChainage + arcLength,
      deflectionAngle: Math.round(deflectionAngle * 1000) / 1000,
      chordLength: Math.round(chordLength * 1000) / 1000,
    });
  }
  
  // PT station (exact)
  const ptArcLength = curve.curveLength;
  const ptDeflection = curve.intersectionAngle / 2;
  const ptChord = curve.longChordLength;
  
  // Only add if not already at an interval station
  const lastStation = stations[stations.length - 1];
  if (Math.abs(lastStation.chainage - (pcChainage + ptArcLength)) > 0.01) {
    stations.push({
      chainage: Math.round((pcChainage + ptArcLength) * 1000) / 1000,
      deflectionAngle: Math.round(ptDeflection * 1000) / 1000,
      chordLength: ptChord,
    });
  }
  
  // Compute coordinates if PI and bearing provided
  if (piEasting !== undefined && piNorthing !== undefined && backBearing !== undefined) {
    computeCurveCoordinates(stations, curve, piEasting, piNorthing, backBearing);
  }
  
  return stations;
}

/**
 * Compute coordinates for curve stations.
 */
function computeCurveCoordinates(
  stations: CurveStationResult[],
  curve: CircularCurveResult,
  piEasting: number,
  piNorthing: number,
  backBearing: number,
): void {
  // PC coordinates
  const pcBearing = backBearing; // Bearing from PI to PC
  const pcE = piEasting - curve.tangentLength * Math.sin(pcBearing * Math.PI / 180);
  const pcN = piNorthing - curve.tangentLength * Math.cos(pcBearing * Math.PI / 180);
  
  stations[0].easting = pcE;
  stations[0].northing = pcN;
  
  // Subsequent stations — compute from PC using deflection angles
  // AUDIT FIX (M6, 2026-07-02): original code was a no-op —
  // `if (tangentBearing >= 360) tangentBearing - 360;` computed the
  // subtraction but discarded the result. Replaced with modulo to wrap
  // to [0, 360). Also changed const → let.
  let tangentBearing = (backBearing + 180) % 360;
  if (tangentBearing < 0) tangentBearing += 360;
  
  for (let i = 1; i < stations.length; i++) {
    const deflRad = stations[i].deflectionAngle * Math.PI / 180;
    const tangentBearingRad = (tangentBearing) * Math.PI / 180;
    
    // Bearing to point on curve
    const bearingToStation = tangentBearingRad + deflRad;
    const chord = stations[i].chordLength;
    
    stations[i].easting = pcE + chord * Math.sin(bearingToStation);
    stations[i].northing = pcN + chord * Math.cos(bearingToStation);
  }
}

/**
 * Compute circular curve from tangent length and intersection angle.
 * Useful when radius is not directly specified.
 */
export function computeCurveFromTangent(
  tangentLength: number,
  intersectionAngle: number
): CircularCurveResult {
  const halfDelta = intersectionAngle * Math.PI / 360;
  const radius = tangentLength / Math.tan(halfDelta);
  
  return computeCircularCurve({ intersectionAngle, radius });
}

/**
 * Compute circular curve from degree of curvature.
 * Degree of curvature (arc definition): D = 5729.578 / R
 */
export function computeCurveFromDegree(
  degreeOfCurvature: number,
  intersectionAngle: number
): CircularCurveResult {
  const radius = 5729.578 / degreeOfCurvature;
  
  return computeCircularCurve({ intersectionAngle, radius });
}

/**
 * Spiral-to-Curve Alignment Engine
 *
 * Roadmap reference: docs/ROADMAP.md → Tier 2 → "Spiral-to-curve alignment
 * engine". Implements a full TS → SC → CS → ST alignment with clothoid
 * transition spirals on both ends of a circular curve.
 *
 * Stationing convention (Schofield / AASHTO):
 *
 *   TS (Tangent-to-Spiral)    start of entry spiral
 *   SC (Spiral-to-Curve)      end of entry spiral / start of circular curve
 *   CS (Curve-to-Spiral)      end of circular curve / start of exit spiral
 *   ST (Spiral-to-Tangent)    end of exit spiral
 *
 * Geometry (per AASHTO Green Book 2018 §3-Exhibit 3-22):
 *
 *   Δ     = intersection angle between approach and departure tangents (rad)
 *   R     = circular curve radius (m)
 *   Ls    = spiral length (m)
 *   θs    = Ls / (2R)              spiral angle (rad)
 *   p     = y - R·(1 - cos θs)     tangent shift (offset of curve from tangent)
 *   k     = x - R·sin θs           tangent extension (TS to shifted PI)
 *   T     = k + (R + p)·tan(Δ/2)   total tangent distance TS → PI
 *   Lc    = R·(Δ - 2θs)            circular curve length (m)
 *
 * The clothoid spiral coordinates (relative to TS, tangent along +X) are
 * computed via the standard series expansion (used by `transition.ts`).
 *
 * Output is a full station table plus a coordinate array that can be fed
 * directly to OpenLayers `LineString` or any other rendering layer.
 *
 * References:
 *   - Schofield, W. (2001) "Engineering Surveying", Chapter 12
 *   - AASHTO Green Book (2018), Chapter 3 — Horizontal Alignment
 *   - KeNHA Road Design Manual, Part 4 — Horizontal Curves
 */

import { computeSpiralCurve, type SpiralCurveInput, type SpiralCurveResult } from './transition'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface SpiralAlignmentInput {
  /** Radius of the circular curve (metres). */
  radius: number
  /**
   * Intersection angle Δ in decimal degrees. This is the deflection
   * between the approach and departure tangents — i.e., 180° minus the
   * interior angle at the PI.
   */
  intersectionAngleDeg: number
  /** Spiral length Ls in metres (both spirals assumed equal). */
  spiralLength: number
  /** Chainage of the PI (Point of Intersection) in metres. */
  piChainage: number
  /**
   * Bearing of the approach tangent in decimal degrees (0° = North, clockwise).
   * Used to compute world coordinates; defaults to 0 (North).
   */
  approachBearingDeg?: number
  /** Easting of the PI (optional, for world-coordinate output). */
  piEasting?: number
  /** Northing of the PI (optional, for world-coordinate output). */
  piNorthing?: number
}

export interface SpiralAlignmentResult {
  /** Echoed input. */
  input: SpiralAlignmentInput
  /** Underlying spiral math (single spiral, applied symmetrically). */
  spiral: SpiralCurveResult
  /** Intersection angle in radians. */
  deltaRad: number
  /** Spiral angle θs in radians. */
  thetaSRad: number
  /** Tangent shift p (m). */
  p: number
  /** Tangent extension k (m, TS to shifted PI). */
  k: number
  /** Total tangent distance T (m, TS to PI). */
  T: number
  /** Circular curve length Lc (m, SC to CS). */
  Lc: number
  /** Total alignment length (m, TS to ST). Ls + Lc + Ls. */
  totalLength: number
  /** Chainage at TS. */
  tsChainage: number
  /** Chainage at SC. */
  scChainage: number
  /** Chainage at CS. */
  csChainage: number
  /** Chainage at ST. */
  stChainage: number
  /** World coordinates of TS (if PI coords supplied). */
  tsCoord: { easting: number; northing: number } | null
  /** World coordinates of SC. */
  scCoord: { easting: number; northing: number } | null
  /** World coordinates of CS. */
  csCoord: { easting: number; northing: number } | null
  /** World coordinates of ST. */
  stCoord: { easting: number; northing: number } | null
  /** World coordinates of PI (echoed). */
  piCoord: { easting: number; northing: number } | null
}

export interface AlignmentStation {
  /** Chainage (m). */
  chainage: number
  /** Distance from TS (m). */
  distanceFromTS: number
  /** Easting (m, world coords if PI supplied, else local). */
  easting: number
  /** Northing (m, world coords if PI supplied, else local). */
  northing: number
  /** Elevation/offset from tangent (m, +left of tangent). */
  offset: number
  /** Current segment. */
  segment: 'entry-spiral' | 'circular' | 'exit-spiral' | 'before' | 'after'
  /** Deflection angle from TS (decimal degrees, clockwise from approach tangent). */
  deflectionDeg: number
}

// ─── Math Helpers ───────────────────────────────────────────────────────────

const DEG = Math.PI / 180

/**
 * Compute a full TS → SC → CS → ST spiral alignment.
 *
 * The approach tangent is assumed to run from TS towards PI along the
 * +X axis (local coordinates). The departure tangent rotates by Δ
 * clockwise (right-hand curve). For a left-hand curve, supply a
 * negative intersection angle.
 */
export function computeSpiralAlignment(
  input: SpiralAlignmentInput
): SpiralAlignmentResult {
  const {
    radius,
    intersectionAngleDeg,
    spiralLength,
    piChainage,
    approachBearingDeg = 0,
    piEasting,
    piNorthing,
  } = input

  if (radius <= 0) throw new Error('Radius must be positive')
  if (spiralLength < 0) throw new Error('Spiral length must be non-negative')
  if (Math.abs(intersectionAngleDeg) < 1e-6) {
    throw new Error('Intersection angle must be non-zero')
  }

  // Single-spiral math (symmetric entry/exit)
  const spiralInput: SpiralCurveInput = {
    radius,
    designSpeed: 80, // placeholder, not used when Ls is derived externally
    c: 0.3,
  }
  const spiral = computeSpiralCurve(spiralInput)
  // Override the spiral length with the user-supplied value
  // (computeSpiralCurve derives Ls from speed; we override for direct control)
  const Ls = spiralLength
  const thetaS = Ls / (2 * radius)
  const deltaRad = Math.abs(intersectionAngleDeg) * DEG

  if (2 * thetaS >= deltaRad) {
    throw new Error(
      `Spiral angle ${thetaS / DEG}° × 2 ≥ intersection angle ${intersectionAngleDeg}° — no room for circular curve. Reduce Ls or increase Δ.`
    )
  }

  // Series expansion coordinates (Schofeld Eq. 12.8)
  const x = Ls * (1 - Math.pow(thetaS, 2) / 10 + Math.pow(thetaS, 4) / 216)
  const y = Ls * (thetaS / 3 - Math.pow(thetaS, 3) / 42 + Math.pow(thetaS, 5) / 1320)

  const p = y - radius * (1 - Math.cos(thetaS))
  const k = x - radius * Math.sin(thetaS)
  const T = k + (radius + p) * Math.tan(deltaRad / 2)
  const Lc = radius * (deltaRad - 2 * thetaS)
  const totalLength = 2 * Ls + Lc

  // Chainages
  const tsChainage = piChainage - T
  const scChainage = tsChainage + Ls
  const csChainage = scChainage + Lc
  const stChainage = csChainage + Ls

  // World coordinates (if PI supplied)
  let tsCoord: { easting: number; northing: number } | null = null
  let scCoord: { easting: number; northing: number } | null = null
  let csCoord: { easting: number; northing: number } | null = null
  let stCoord: { easting: number; northing: number } | null = null
  const piCoord =
    piEasting !== undefined && piNorthing !== undefined
      ? { easting: piEasting, northing: piNorthing }
      : null

  if (piCoord) {
    // Approach tangent direction (from TS to PI): approachBearing reversed
    const approachBrng = approachBearingDeg * DEG
    // TS is "behind" the PI along the approach tangent
    const dx = -T * Math.sin(approachBrng)
    const dy = -T * Math.cos(approachBrng)
    tsCoord = { easting: piCoord.easting + dx, northing: piCoord.northing + dy }

    // SC = TS + (x, y) in local frame, rotated by approachBearing
    // For a right-hand curve (positive Δ), Y points LEFT of the tangent
    scCoord = localToWorld(tsCoord, x, y, approachBrng)

    // CS = SC + circular arc (Δ - 2θs) along R
    // Center of circular curve is at distance (R + p) perpendicular to the
    // approach tangent, on the curve side. For right-hand curve, +Y direction.
    // Center = SC + R * (direction from curve to center)
    // Direction from SC to center: rotate tangent direction by 90° toward curve side
    // For right-hand curve: tangent +X, curve side +Y, center is at angle (90° + θs) from tangent at SC
    // Simpler: compute CS as SC rotated about center by (Δ - 2θs)
    const arcAngle = deltaRad - 2 * thetaS
    // Center of circular curve in local frame:
    // At SC, the tangent direction is rotated by θs from the original tangent.
    // The center is perpendicular to that, at distance R, on the inside of the curve.
    // For right-hand curve: center is at angle (90° + θs) from original tangent at TS.
    const centerLocalX = x - radius * Math.sin(thetaS)
    const centerLocalY = y + radius * Math.cos(thetaS)
    const centerWorld = localToWorld(tsCoord, centerLocalX, centerLocalY, approachBrng)
    // SC relative to center: rotate by -arcAngle to get CS (for right-hand curve, clockwise)
    // Vector from center to SC (local frame)
    const scRelCx = x - centerLocalX
    const scRelCy = y - centerLocalY
    // Rotate by -arcAngle (clockwise for right-hand curve)
    const csRelCx = scRelCx * Math.cos(-arcAngle) - scRelCy * Math.sin(-arcAngle)
    const csRelCy = scRelCx * Math.sin(-arcAngle) + scRelCy * Math.cos(-arcAngle)
    const csLocalX = centerLocalX + csRelCx
    const csLocalY = centerLocalY + csRelCy
    csCoord = localToWorld(tsCoord, csLocalX, csLocalY, approachBrng)

    // ST = CS + exit spiral (mirror of entry spiral)
    // At CS, tangent direction is rotated by (Δ - θs) from original.
    // Exit spiral mirrors entry: it curves in the opposite rotational sense,
    // starting from CS and ending at ST.
    // ST in local frame: reflect entry spiral about the perpendicular bisector.
    // Simplification: ST = PI + T * (departure tangent direction)
    const departureBrng = approachBrng + deltaRad // right-hand
    const stDx = T * Math.sin(departureBrng)
    const stDy = T * Math.cos(departureBrng)
    stCoord = { easting: piCoord.easting + stDx, northing: piCoord.northing + stDy }
  }

  return {
    input,
    spiral: { ...spiral, spiralLength: Ls, spiralAngle: (thetaS * 180) / Math.PI },
    deltaRad,
    thetaSRad: thetaS,
    p,
    k,
    T,
    Lc,
    totalLength,
    tsChainage,
    scChainage,
    csChainage,
    stChainage,
    tsCoord,
    scCoord,
    csCoord,
    stCoord,
    piCoord,
  }
}

/**
 * Transform a local-frame (x, y) point to world coordinates given a TS
 * origin and an approach bearing. Local frame: +X = along approach tangent
 * (toward PI), +Y = LEFT of tangent. Bearing convention: 0° = North, clockwise.
 */
function localToWorld(
  ts: { easting: number; northing: number },
  x: number,
  y: number,
  approachBrngRad: number
): { easting: number; northing: number } {
  // Approach tangent unit vector (TS → PI)
  const tx = Math.sin(approachBrngRad)
  const ty = Math.cos(approachBrngRad)
  // Left perpendicular (for right-hand curve, +Y is left)
  // For bearing 0 (North), tangent is (0, +1). Left of that is (-1, 0) which is West.
  // So left-perp = (-ty, tx)? Let's verify: rotate tangent 90° CCW = (-ty, tx)
  // For (0, 1) tangent, CCW 90° = (-1, 0). Yes that's West = left.
  const lx = -ty
  const ly = tx
  return {
    easting: ts.easting + x * tx + y * lx,
    northing: ts.northing + x * ty + y * ly,
  }
}

// ─── Station Interpolation ──────────────────────────────────────────────────

/**
 * Sample the spiral alignment at a fixed interval and return stations
 * with world coordinates, offsets, deflection angles, and segment labels.
 *
 * @param alignment  - Result of `computeSpiralAlignment`
 * @param interval   - Sample interval in metres (default 10)
 */
export function stationSpiralAlignment(
  alignment: SpiralAlignmentResult,
  interval: number = 10
): AlignmentStation[] {
  const stations: AlignmentStation[] = []
  const { input, thetaSRad, deltaRad, T, tsChainage, totalLength } = alignment
  const { radius, spiralLength: Ls, approachBearingDeg = 0 } = input
  const approachBrng = approachBearingDeg * DEG

  const N = Math.floor(totalLength / interval)
  for (let i = 0; i <= N; i++) {
    const d = i * interval // distance from TS
    if (d > totalLength + 0.01) continue
    const ch = tsChainage + d
    const station = stationAtDistance(alignment, d)
    if (station) stations.push({ ...station, chainage: ch })
  }
  // Ensure final station at ST
  const last = stations[stations.length - 1]
  if (!last || Math.abs(last.distanceFromTS - totalLength) > 0.01) {
    const station = stationAtDistance(alignment, totalLength)
    if (station) stations.push({ ...station, chainage: tsChainage + totalLength })
  }

  return stations
}

/**
 * Compute the station at a given distance from TS.
 *
 * Returns null for distances outside [0, totalLength].
 */
export function stationAtDistance(
  alignment: SpiralAlignmentResult,
  distanceFromTS: number
): AlignmentStation | null {
  const { input, thetaSRad, deltaRad, T, tsChainage, totalLength, tsCoord } = alignment
  const { radius, spiralLength: Ls, approachBearingDeg = 0 } = input
  const approachBrng = approachBearingDeg * DEG

  if (distanceFromTS < -0.01 || distanceFromTS > totalLength + 0.01) return null
  const d = Math.max(0, Math.min(totalLength, distanceFromTS))

  let localX: number
  let localY: number
  let segment: AlignmentStation['segment']
  let deflectionDeg: number

  if (d < Ls) {
    // Entry spiral (TS → SC)
    segment = 'entry-spiral'
    const s = d
    const theta = (s * s) / (2 * radius * Ls) // instantaneous spiral angle at s
    // Clothoid coordinates (series expansion about s)
    localX = s * (1 - Math.pow(theta, 2) / 10 + Math.pow(theta, 4) / 216)
    localY = s * (theta / 3 - Math.pow(theta, 3) / 42 + Math.pow(theta, 5) / 1320)
    deflectionDeg = (theta * 180) / Math.PI / 3 // approximate deflection (1/3 of spiral angle)
  } else if (d < Ls + alignment.Lc) {
    // Circular curve (SC → CS)
    segment = 'circular'
    const s = d - Ls
    const arcAngle = s / radius
    // At SC, the tangent is rotated by θs from the original tangent.
    // The point on the circular curve, measured from SC, is at angle
    // (θs + arcAngle) from the original tangent at TS.
    // Center is at (x_SC - R sin θs, y_SC + R cos θs) — see alignment computation
    const xSC = Ls * (1 - Math.pow(thetaSRad, 2) / 10 + Math.pow(thetaSRad, 4) / 216)
    const ySC = Ls * (thetaSRad / 3 - Math.pow(thetaSRad, 3) / 42 + Math.pow(thetaSRad, 5) / 1320)
    const centerLocalX = xSC - radius * Math.sin(thetaSRad)
    const centerLocalY = ySC + radius * Math.cos(thetaSRad)
    // Vector from center to SC
    const scRelCx = xSC - centerLocalX
    const scRelCy = ySC - centerLocalY
    // Rotate by -arcAngle (clockwise for right-hand curve)
    const relCx = scRelCx * Math.cos(-arcAngle) - scRelCy * Math.sin(-arcAngle)
    const relCy = scRelCx * Math.sin(-arcAngle) + scRelCy * Math.cos(-arcAngle)
    localX = centerLocalX + relCx
    localY = centerLocalY + relCy
    deflectionDeg = ((thetaSRad + arcAngle) * 180) / Math.PI
  } else {
    // Exit spiral (CS → ST) — mirror of entry
    segment = 'exit-spiral'
    const sFromST = totalLength - d // distance from ST, going backwards
    const s = sFromST
    const theta = (s * s) / (2 * radius * Ls)
    // Local coords of ST relative to TS would require rotating the entire
    // exit spiral; simpler to compute ST in local frame and add the reverse
    // spiral displacement
    // ST local: PI is at (T, 0); ST is at (T + T cos Δ, T sin Δ) ... actually
    // ST is reached by traveling T along departure tangent from PI.
    const stLocalX = T + T * Math.cos(deltaRad)
    const stLocalY = T * Math.sin(deltaRad) // right-hand curve: +Y
    // Reverse spiral at ST goes backward, curving opposite to entry spiral
    // For right-hand curve, exit spiral curves from CS (which is to the LEFT
    // of departure tangent) toward ST
    // Entry spiral coords (rotated): rotate (x, y) by Δ, then mirror
    const xSpiral = s * (1 - Math.pow(theta, 2) / 10 + Math.pow(theta, 4) / 216)
    const ySpiral = s * (theta / 3 - Math.pow(theta, 3) / 42 + Math.pow(theta, 5) / 1320)
    // At ST, looking back along the approach direction (departure tangent - 180°),
    // the spiral extends to the LEFT (for right-hand curve). So in the TS-local frame:
    localX = stLocalX - (xSpiral * Math.cos(deltaRad) + ySpiral * Math.sin(deltaRad))
    localY = stLocalY - (xSpiral * Math.sin(deltaRad) - ySpiral * Math.cos(deltaRad))
    deflectionDeg = ((deltaRad - theta) * 180) / Math.PI
  }

  // Offset = perpendicular distance from approach tangent (the Y coordinate in local frame)
  const offset = localY

  // World coordinates
  let easting = localX
  let northing = localY
  if (tsCoord) {
    const world = localToWorld(tsCoord, localX, localY, approachBrng)
    easting = world.easting
    northing = world.northing
  }

  return {
    chainage: tsChainage + d,
    distanceFromTS: Math.round(d * 1000) / 1000,
    easting: Math.round(easting * 1000) / 1000,
    northing: Math.round(northing * 1000) / 1000,
    offset: Math.round(offset * 1000) / 1000,
    segment,
    deflectionDeg: Math.round(deflectionDeg * 10000) / 10000,
  }
}

// ─── OpenLayers Geometry Helper ─────────────────────────────────────────────

/**
 * Produce a coordinate array for use with OpenLayers `LineString` or any
 * other rendering layer that expects [easting, northing] pairs.
 *
 * If the alignment was computed without PI coordinates, returns local-frame
 * coordinates (TS at origin, approach tangent along +X). Otherwise returns
 * world coordinates.
 */
export function alignmentToCoordinateArray(
  alignment: SpiralAlignmentResult,
  interval: number = 2
): Array<[number, number]> {
  const stations = stationSpiralAlignment(alignment, interval)
  return stations.map(s => [s.easting, s.northing])
}

/**
 * Convert stations to CSV for export.
 */
export function spiralAlignmentToCSV(stations: AlignmentStation[]): string {
  const header = 'Chainage_m,Distance_from_TS_m,Easting_m,Northing_m,Offset_m,Segment,Deflection_deg'
  const rows = stations.map(s =>
    [
      s.chainage.toFixed(3),
      s.distanceFromTS.toFixed(3),
      s.easting.toFixed(3),
      s.northing.toFixed(3),
      s.offset.toFixed(3),
      s.segment,
      s.deflectionDeg.toFixed(4),
    ].join(',')
  )
  return [header, ...rows].join('\n')
}

/**
 * Deformation Monitoring Engine — repeat-epoch comparison + alerting
 *
 * THE PROBLEM
 * -----------
 * For dam monitoring, landslide monitoring, and repeat-epoch boundary work,
 * a surveyor needs to compare coordinates from different observation epochs
 * and determine whether a monument has ACTUALLY MOVED — vs. just drifted
 * due to tectonic plate motion or measurement noise.
 *
 * Doing this by hand in Excel across months of readings is exactly the kind
 * of tedious, error-prone work an engineer will pay to never do again. This
 * module automates it.
 *
 * WHAT IT DOES
 * ------------
 * 1. Takes two (or more) adjustment results from different epochs
 * 2. Propagates both to a common epoch (using the epoch manager — plate
 *    velocity propagation) so tectonic drift is removed
 * 3. Computes the deformation vector (dE, dN, dH) per monument
 * 4. Runs a statistical significance test (is the movement real, or just
 *    measurement noise at the monument's accuracy level?)
 * 5. Flags monuments that have moved beyond the project's tolerance
 * 6. Produces a time-series analysis (trend, velocity, acceleration) when
 *    multiple epochs are available
 *
 * USAGE
 * -----
 *   import { compareEpochs, analyzeTimeSeries } from '@/lib/survey/deformationMonitoring'
 *
 *   const report = compareEpochs({
 *     baseline: { epoch: 2024.0, monuments: [...] },
 *     current: { epoch: 2025.5, monuments: [...] },
 *     tolerance: { horizontal: 0.005, vertical: 0.003 }, // 5mm H, 3mm V
 *     confidenceLevel: 0.95,
 *   })
 *
 *   if (report.alerts.length > 0) {
 *     // "Monument DM-07 has moved 8.2mm north (exceeds 5mm tolerance)."
 *   }
 */

import {
  propagateToEpoch,
  type EpochCoordinate,
  type ReferenceFrame,
} from '@/lib/geo/epochManager'
import { propagateToEpochRigorous } from '@/lib/geo/epochManagerRigorous'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface MonumentObservation {
  /** Monument ID (e.g., 'DM-07' for Dam Monument 7) */
  monumentId: string
  /** Latitude (WGS84 degrees) */
  latitude: number
  /** Longitude (WGS84 degrees) */
  longitude: number
  /** Ellipsoidal height (meters) */
  height: number
  /** Reference frame */
  frame: ReferenceFrame
  /** Decimal year epoch (e.g., 2024.5 = July 2024) */
  epoch: number
  /** Standard deviation in East (meters) */
  sigmaE?: number
  /** Standard deviation in North (meters) */
  sigmaN?: number
  /** Standard deviation in Height (meters) */
  sigmaH?: number
  /** Covariance E-N (meters²) */
  sigmaEN?: number
}

export interface EpochSet {
  /** Epoch label (e.g., 'Baseline 2024-01', 'Q2 2025') */
  label: string
  /** Decimal year */
  epoch: number
  /** Monument observations for this epoch */
  monuments: MonumentObservation[]
}

export interface DeformationVector {
  monumentId: string
  /** Displacement East (meters) — positive = eastward movement */
  deltaE: number
  /** Displacement North (meters) — positive = northward movement */
  deltaN: number
  /** Displacement Up (meters) — positive = uplift */
  deltaH: number
  /** Horizontal displacement magnitude (meters) */
  horizontalDisplacement: number
  /** Bearing of movement (degrees, 0=N, 90=E) */
  bearing: number
  /** Whether the movement is statistically significant */
  isSignificant: boolean
  /** Whether the movement exceeds the tolerance */
  exceedsTolerance: boolean
  /** The statistical test result (if sigma values were available) */
  significance?: {
    testStatistic: number
    criticalValue: number
    passed: boolean
    interpretation: string
  }
}

export interface DeformationTolerance {
  /** Horizontal movement tolerance (meters). Default: 0.005 (5mm) */
  horizontal?: number
  /** Vertical movement tolerance (meters). Default: 0.003 (3mm) */
  vertical?: number
}

export interface DeformationAlert {
  monumentId: string
  severity: 'info' | 'warning' | 'critical'
  message: string
  /** Movement magnitude in mm */
  magnitudeMm: number
  /** Direction of movement */
  direction: string
}

export interface DeformationReport {
  /** Per-monument deformation vectors */
  vectors: DeformationVector[]

  /** Monuments that have moved beyond tolerance */
  alerts: DeformationAlert[]

  /** Monuments that are stable (within tolerance) */
  stable: string[]

  /** Monuments present in baseline but missing in current epoch */
  missingMonuments: string[]

  /** Monuments present in current but not in baseline (new monuments) */
  newMonuments: string[]

  /** Epochs compared */
  baselineEpoch: number
  currentEpoch: number
  commonEpoch: number

  /** Tolerances used */
  tolerance: Required<DeformationTolerance>

  /** Overall verdict */
  verdict: 'STABLE' | 'DEFORMING' | 'INCONCLUSIVE'
  /** Human-readable summary */
  summary: string

  /** Timestamp */
  timestamp: string
}

// ─── Time-Series Types ──────────────────────────────────────────────────────

export interface TimeSeriesPoint {
  epoch: number
  /** Position at this epoch (after propagation to common frame) */
  latitude: number
  longitude: number
  height: number
  /** Displacement from the first epoch (meters) */
  deltaE: number
  deltaN: number
  deltaH: number
  horizontalDisplacement: number
}

export interface TimeSeriesAnalysis {
  monumentId: string
  /** All epochs in the series */
  points: TimeSeriesPoint[]

  /** Linear trend (velocity) — meters per year */
  velocityE: number
  velocityN: number
  velocityH: number
  velocityHorizontal: number
  velocityBearing: number

  /** Acceleration (change in velocity) — meters per year² */
  accelerationHorizontal: number

  /** Whether the trend is statistically significant */
  trendSignificant: boolean

  /** R² of the linear fit (0-1) */
  rSquared: number

  /** Projected position 1 year from the last epoch */
  projectedDeltaE: number
  projectedDeltaN: number
  projectedDeltaH: number
  projectedHorizontalDisplacement: number

  /** Whether the projected movement will exceed tolerance */
  projectedExceedsTolerance: boolean

  /** Interpretation for display */
  interpretation: string
}

// ─── Main: Compare Two Epochs ───────────────────────────────────────────────

/**
 * Compare monument positions between two epochs and detect deformation.
 *
 * This is the core function for dam/boundary monitoring. It:
 *   1. Matches monuments by ID between the two epochs
 *   2. Propagates both to a common epoch (removing tectonic plate drift)
 *   3. Computes the deformation vector per monument
 *   4. Runs a statistical significance test (if accuracy data available)
 *   5. Flags monuments that exceed tolerance
 *
 * @returns DeformationReport with per-monument vectors + alerts
 */
export function compareEpochs(
  baseline: EpochSet,
  current: EpochSet,
  tolerance: DeformationTolerance = {},
  confidenceLevel: number = 0.95,
): DeformationReport {
  const tolH = tolerance.horizontal ?? 0.005  // 5mm default
  const tolV = tolerance.vertical ?? 0.003    // 3mm default
  const commonEpoch = Math.max(baseline.epoch, current.epoch)

  // Build lookup maps
  const baselineMap = new Map<string, MonumentObservation>()
  for (const m of baseline.monuments) {
    baselineMap.set(m.monumentId, m)
  }

  const currentMap = new Map<string, MonumentObservation>()
  for (const m of current.monuments) {
    currentMap.set(m.monumentId, m)
  }

  // Find common, missing, and new monuments
  const commonIds = [...baselineMap.keys()].filter(id => currentMap.has(id))
  const missingIds = [...baselineMap.keys()].filter(id => !currentMap.has(id))
  const newIds = [...currentMap.keys()].filter(id => !baselineMap.has(id))

  const vectors: DeformationVector[] = []
  const alerts: DeformationAlert[] = []
  const stable: string[] = []

  for (const id of commonIds) {
    const baseMon = baselineMap.get(id)!
    const currMon = currentMap.get(id)!

    // Propagate both to the common epoch (remove tectonic drift)
    // Use the RIGOROUS Rodrigues' rotation formula (no linearization error)
    // — critical for dam monitoring where sub-mm precision is needed.
    const baseProp = propagateToEpochRigorous(
      {
        latitude: baseMon.latitude,
        longitude: baseMon.longitude,
        height: baseMon.height,
        frame: baseMon.frame,
        epoch: baseMon.epoch,
      },
      commonEpoch,
    )

    const currProp = propagateToEpochRigorous(
      {
        latitude: currMon.latitude,
        longitude: currMon.longitude,
        height: currMon.height,
        frame: currMon.frame,
        epoch: currMon.epoch,
      },
      commonEpoch,
    )

    // Compute deformation vector
    // Convert lat/lon differences to meters (local ENU approximation)
    const lat0 = baseProp.latitude * Math.PI / 180
    const cosLat = Math.cos(lat0)
    const R = 6371000 // Earth radius in meters

    const deltaLat = currProp.latitude - baseProp.latitude
    const deltaLon = currProp.longitude - baseProp.longitude
    const deltaH = currProp.height - baseProp.height

    const deltaN = deltaLat * R * Math.PI / 180
    const deltaE = deltaLon * R * Math.PI / 180 * cosLat
    const horizontalDisplacement = Math.sqrt(deltaE ** 2 + deltaN ** 2)
    const bearing = (Math.atan2(deltaE, deltaN) * 180 / Math.PI + 360) % 360

    // Statistical significance test (if sigma values available)
    let significance: DeformationVector['significance']
    let isSignificant = false

    if (baseMon.sigmaE !== undefined && currMon.sigmaE !== undefined &&
        baseMon.sigmaN !== undefined && currMon.sigmaN !== undefined) {
      // Combined standard deviation (error propagation: σ_diff = √(σ1² + σ2²))
      const sigmaE_combined = Math.sqrt(baseMon.sigmaE ** 2 + currMon.sigmaE ** 2)
      const sigmaN_combined = Math.sqrt(baseMon.sigmaN ** 2 + currMon.sigmaN ** 2)

      // Test statistic: horizontal displacement / combined sigma
      const sigmaH_combined = Math.sqrt(sigmaE_combined ** 2 + sigmaN_combined ** 2)
      const testStatistic = sigmaH_combined > 0 ? horizontalDisplacement / sigmaH_combined : 0

      // Critical value: for 2D, 95% confidence → 2.45 (chi-square 2D)
      const criticalValue = confidenceLevel === 0.99 ? 3.03 : 2.45
      isSignificant = testStatistic > criticalValue

      significance = {
        testStatistic,
        criticalValue,
        passed: !isSignificant,
        interpretation: isSignificant
          ? `Movement is statistically significant at ${(confidenceLevel * 100).toFixed(0)}% confidence (test stat ${testStatistic.toFixed(2)} > ${criticalValue}). This is real movement, not measurement noise.`
          : `Movement is NOT statistically significant at ${(confidenceLevel * 100).toFixed(0)}% confidence (test stat ${testStatistic.toFixed(2)} ≤ ${criticalValue}). Likely measurement noise.`,
      }
    }

    const exceedsTolerance = horizontalDisplacement > tolH || Math.abs(deltaH) > tolV

    const vector: DeformationVector = {
      monumentId: id,
      deltaE,
      deltaN,
      deltaH,
      horizontalDisplacement,
      bearing,
      isSignificant,
      exceedsTolerance,
      significance,
    }
    vectors.push(vector)

    // Generate alert if exceeds tolerance AND is significant (or no sigma data)
    if (exceedsTolerance && (isSignificant || !significance)) {
      const severity = horizontalDisplacement > tolH * 3 || Math.abs(deltaH) > tolV * 3
        ? 'critical'
        : 'warning'

      const directionStr = formatBearing(bearing)
      const magMm = horizontalDisplacement * 1000

      alerts.push({
        monumentId: id,
        severity,
        message: `${id} has moved ${magMm.toFixed(1)}mm ${directionStr}` +
          (Math.abs(deltaH) > tolV ? ` and ${(deltaH * 1000).toFixed(1)}mm ${deltaH > 0 ? 'up' : 'down'}` : '') +
          ` (tolerance: ${tolH * 1000}mm H / ${tolV * 1000}mm V).` +
          (significance ? ` ${significance.interpretation}` : ''),
        magnitudeMm: magMm,
        direction: directionStr,
      })
    } else {
      stable.push(id)
    }
  }

  // Overall verdict
  let verdict: 'STABLE' | 'DEFORMING' | 'INCONCLUSIVE'
  let summary: string

  if (vectors.length === 0) {
    verdict = 'INCONCLUSIVE'
    summary = 'No common monuments between epochs. Cannot compare.'
  } else if (alerts.length === 0) {
    verdict = 'STABLE'
    summary = `All ${stable.length} monuments stable within tolerance (±${tolH * 1000}mm H / ±${tolV * 1000}mm V) between ${baseline.label} and ${current.label}.`
  } else {
    verdict = 'DEFORMING'
    const criticalCount = alerts.filter(a => a.severity === 'critical').length
    summary = `${alerts.length} monument(s) exceeded tolerance between ${baseline.label} and ${current.label}.` +
      (criticalCount > 0 ? ` ${criticalCount} CRITICAL.` : '') +
      ` Affected: ${alerts.map(a => a.monumentId).join(', ')}.`
  }

  return {
    vectors,
    alerts,
    stable,
    missingMonuments: missingIds,
    newMonuments: newIds,
    baselineEpoch: baseline.epoch,
    currentEpoch: current.epoch,
    commonEpoch,
    tolerance: { horizontal: tolH, vertical: tolV },
    verdict,
    summary,
    timestamp: new Date().toISOString(),
  }
}

// ─── Time-Series Analysis ───────────────────────────────────────────────────

/**
 * Analyze a time series of monument positions across multiple epochs.
 *
 * Computes:
 *   - Linear trend (velocity) in E, N, H — meters per year
 *   - Acceleration (change in velocity)
 *   - R² goodness of fit
 *   - 1-year projection
 *   - Whether the projection exceeds tolerance
 *
 * @param epochs - Array of EpochSets (at least 2, ideally 3+ for trend)
 * @param monumentId - Which monument to analyze
 * @param tolerance - Movement tolerance for projection check
 */
export function analyzeTimeSeries(
  epochs: EpochSet[],
  monumentId: string,
  tolerance: DeformationTolerance = {},
): TimeSeriesAnalysis {
  const tolH = tolerance.horizontal ?? 0.005
  const tolV = tolerance.vertical ?? 0.003

  // Collect all observations of this monument across epochs
  const observations: TimeSeriesPoint[] = []
  let firstObs: { lat: number; lon: number; h: number } | null = null

  // Sort epochs chronologically
  const sortedEpochs = [...epochs].sort((a, b) => a.epoch - b.epoch)

  for (const epochSet of sortedEpochs) {
    const mon = epochSet.monuments.find(m => m.monumentId === monumentId)
    if (!mon) continue

    // Propagate to a common reference (the first epoch)
    if (!firstObs) {
      firstObs = { lat: mon.latitude, lon: mon.longitude, h: mon.height }
    }

    const commonEpoch = sortedEpochs[0].epoch
    const prop = propagateToEpochRigorous(
      {
        latitude: mon.latitude,
        longitude: mon.longitude,
        height: mon.height,
        frame: mon.frame,
        epoch: mon.epoch,
      },
      commonEpoch,
    )

    // Compute displacement from first observation
    const lat0 = firstObs.lat * Math.PI / 180
    const cosLat = Math.cos(lat0)
    const R = 6371000

    const deltaLat = prop.latitude - firstObs.lat
    const deltaLon = prop.longitude - firstObs.lon
    const deltaH = prop.height - firstObs.h

    const deltaN = deltaLat * R * Math.PI / 180
    const deltaE = deltaLon * R * Math.PI / 180 * cosLat
    const horizontalDisplacement = Math.sqrt(deltaE ** 2 + deltaN ** 2)

    observations.push({
      epoch: mon.epoch,
      latitude: prop.latitude,
      longitude: prop.longitude,
      height: prop.height,
      deltaE,
      deltaN,
      deltaH,
      horizontalDisplacement,
    })
  }

  if (observations.length < 2) {
    return {
      monumentId,
      points: observations,
      velocityE: 0,
      velocityN: 0,
      velocityH: 0,
      velocityHorizontal: 0,
      velocityBearing: 0,
      accelerationHorizontal: 0,
      trendSignificant: false,
      rSquared: 0,
      projectedDeltaE: 0,
      projectedDeltaN: 0,
      projectedDeltaH: 0,
      projectedHorizontalDisplacement: 0,
      projectedExceedsTolerance: false,
      interpretation: 'Insufficient data for trend analysis (need ≥2 epochs).',
    }
  }

  // Linear regression: displacement vs time
  // y = a + b×t, where t = epoch, y = displacement
  const t0 = observations[0].epoch
  const tValues = observations.map(o => o.epoch - t0) // years from first epoch
  const eValues = observations.map(o => o.deltaE)
  const nValues = observations.map(o => o.deltaN)
  const hValues = observations.map(o => o.deltaH)
  const hDispValues = observations.map(o => o.horizontalDisplacement)

  const { slope: velE, r2: r2E } = linearRegression(tValues, eValues)
  const { slope: velN, r2: r2N } = linearRegression(tValues, nValues)
  const { slope: velH, r2: r2H } = linearRegression(tValues, hValues)
  const { slope: velHdisp, r2: r2Hdisp } = linearRegression(tValues, hDispValues)

  const velocityHorizontal = Math.sqrt(velE ** 2 + velN ** 2)
  const velocityBearing = (Math.atan2(velE, velN) * 180 / Math.PI + 360) % 360

  // Acceleration: difference in velocity between first and second half
  let accelerationHorizontal = 0
  if (observations.length >= 4) {
    const midIdx = Math.floor(observations.length / 2)
    const firstHalf = observations.slice(0, midIdx + 1)
    const secondHalf = observations.slice(midIdx)

    const t1 = firstHalf.map(o => o.epoch - t0)
    const h1 = firstHalf.map(o => o.horizontalDisplacement)
    const t2 = secondHalf.map(o => o.epoch - t0)
    const h2 = secondHalf.map(o => o.horizontalDisplacement)

    const vel1 = linearRegression(t1, h1).slope
    const vel2 = linearRegression(t2, h2).slope

    const dt = (secondHalf[secondHalf.length - 1].epoch - firstHalf[0].epoch) / 2
    if (dt > 0) {
      accelerationHorizontal = (vel2 - vel1) / dt
    }
  }

  // R² for horizontal displacement
  const rSquared = r2Hdisp

  // Trend significance: R² > 0.7 AND velocity > tolerance/year
  const trendSignificant = rSquared > 0.7 && velocityHorizontal > tolH

  // Project 1 year from last epoch
  const lastT = tValues[tValues.length - 1]
  const projectedT = lastT + 1.0
  const projectedDeltaE = velE * projectedT
  const projectedDeltaN = velN * projectedT
  const projectedDeltaH = velH * projectedT
  const projectedHorizontalDisplacement = Math.sqrt(projectedDeltaE ** 2 + projectedDeltaN ** 2)
  const projectedExceedsTolerance = projectedHorizontalDisplacement > tolH || Math.abs(projectedDeltaH) > tolV

  // Interpretation
  let interpretation: string
  if (velocityHorizontal < tolH) {
    interpretation = `Stable: velocity ${(velocityHorizontal * 1000).toFixed(1)}mm/yr is within tolerance. No action needed.`
  } else if (trendSignificant) {
    interpretation = `DEFORMING: velocity ${(velocityHorizontal * 1000).toFixed(1)}mm/yr ${formatBearing(velocityBearing)} (R²=${rSquared.toFixed(2)}).` +
      (projectedExceedsTolerance ? ` Projected to exceed tolerance within 1 year. Investigate.` : ` Trend is significant but projection is within tolerance.`)
  } else {
    interpretation = `Marginal: velocity ${(velocityHorizontal * 1000).toFixed(1)}mm/yr but R²=${rSquared.toFixed(2)} indicates high variability. More epochs needed to confirm trend.`
  }

  return {
    monumentId,
    points: observations,
    velocityE: velE,
    velocityN: velN,
    velocityH: velH,
    velocityHorizontal,
    velocityBearing,
    accelerationHorizontal,
    trendSignificant,
    rSquared,
    projectedDeltaE,
    projectedDeltaN,
    projectedDeltaH,
    projectedHorizontalDisplacement,
    projectedExceedsTolerance,
    interpretation,
  }
}

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Simple linear regression: y = a + b×x
 * Returns slope (b), intercept (a), and R².
 */
function linearRegression(x: number[], y: number[]): { slope: number; intercept: number; r2: number } {
  const n = x.length
  if (n < 2) return { slope: 0, intercept: 0, r2: 0 }

  const sumX = x.reduce((s, v) => s + v, 0)
  const sumY = y.reduce((s, v) => s + v, 0)
  const sumXY = x.reduce((s, v, i) => s + v * y[i], 0)
  const sumX2 = x.reduce((s, v) => s + v * v, 0)
  const sumY2 = y.reduce((s, v) => s + v * v, 0)

  const denom = n * sumX2 - sumX * sumX
  if (Math.abs(denom) < 1e-12) return { slope: 0, intercept: y[0], r2: 0 }

  const slope = (n * sumXY - sumX * sumY) / denom
  const intercept = (sumY - slope * sumX) / n

  // R²
  const meanY = sumY / n
  const ssTot = y.reduce((s, v) => s + (v - meanY) ** 2, 0)
  const ssRes = y.reduce((s, v, i) => s + (v - (intercept + slope * x[i])) ** 2, 0)
  const r2 = ssTot > 0 ? 1 - ssRes / ssTot : 0

  return { slope, intercept, r2 }
}

/**
 * Format a bearing in degrees as a compass direction.
 * e.g., 45° → "NE", 180° → "S", 270° → "W"
 */
function formatBearing(bearing: number): string {
  const dirs = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE',
                'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW']
  const idx = Math.round(bearing / 22.5) % 16
  return `${dirs[idx]} (${bearing.toFixed(1)}°)`
}

// ─── Display Helpers ────────────────────────────────────────────────────────

/**
 * Get the verdict color for deformation status.
 */
export function getDeformationVerdictColor(verdict: 'STABLE' | 'DEFORMING' | 'INCONCLUSIVE'): string {
  switch (verdict) {
    case 'STABLE': return 'green'
    case 'DEFORMING': return 'red'
    case 'INCONCLUSIVE': return 'yellow'
    default: return 'gray'
  }
}

/**
 * Get the alert severity color.
 */
export function getAlertSeverityColor(severity: 'info' | 'warning' | 'critical'): string {
  switch (severity) {
    case 'info': return 'blue'
    case 'warning': return 'yellow'
    case 'critical': return 'red'
    default: return 'gray'
  }
}

/**
 * Format a deformation vector for display.
 */
export function formatDeformationVector(v: DeformationVector): string {
  const parts: string[] = []
  parts.push(`dE=${(v.deltaE * 1000).toFixed(1)}mm`)
  parts.push(`dN=${(v.deltaN * 1000).toFixed(1)}mm`)
  if (v.deltaH !== 0) {
    parts.push(`dH=${(v.deltaH * 1000).toFixed(1)}mm`)
  }
  parts.push(`|H|=${(v.horizontalDisplacement * 1000).toFixed(1)}mm`)
  parts.push(formatBearing(v.bearing))
  if (v.significance) {
    parts.push(v.isSignificant ? 'SIGNIFICANT' : 'not significant')
  }
  if (v.exceedsTolerance) {
    parts.push('⚠ EXCEEDS TOLERANCE')
  }
  return parts.join('  ')
}

import {
  adjustLevelNetwork,
  computeObservations,
} from '../levelNetworkAdjustment'
import {
  allowableMisclosure,
  LevelObservation,
  LevelControlPoint,
} from '../digitalLevelTypes'

describe('adjustLevelNetwork', () => {
  test('adjusts simple leveling run A -> B -> C with 1 fixed', () => {
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'TP1', heightDifference: 0.500, distance: 50, weight: 1 / (0.05 * 0.05) },
      { fromId: 'TP1', toId: 'TP2', heightDifference: -0.300, distance: 40, weight: 1 / (0.04 * 0.04) },
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1500.000, isFixed: true },
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'third')
    expect(result.passed).toBeDefined()
    expect(result.adjustedLevels.length).toBe(3) // BM1, TP1, TP2
    expect(result.adjustedLevels[0].id).toBe('BM1')
    expect(result.adjustedLevels[0].rl).toBeCloseTo(1500.000, 1)
  })

  test('computes misclosure for a closed loop', () => {
    // Triangle: BM1 -> TP1 -> TP2 -> BM1
    // True RLs: BM1=1000, TP1=1001, TP2=1002
    // Obs: +1.000, +1.000, -2.010 (with 10mm misclosure)
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'TP1', heightDifference: 1.000, distance: 100, weight: 1 },
      { fromId: 'TP1', toId: 'TP2', heightDifference: 1.000, distance: 100, weight: 1 },
      { fromId: 'TP2', toId: 'BM1', heightDifference: -2.010, distance: 100, weight: 1 },
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1000.000, isFixed: true },
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'third')
    // Misclosure should be non-zero
    expect(result.misclosure).toBeDefined()
    expect(result.totalDistance).toBeCloseTo(0.3) // 3 x 100m = 300m = 0.3km
    expect(result.degreesOfFreedom).toBeGreaterThan(0)
  })

  test('allowable misclosure per Kenya order standards', () => {
    // 4th order: 20*sqrt(L) mm, L in km
    expect(allowableMisclosure(1.0, 'fourth')).toBeCloseTo(20.0, 1)
    // 1st order: 4*sqrt(L) mm
    expect(allowableMisclosure(1.0, 'first')).toBeCloseTo(4.0, 1)
    // 2nd order: 6*sqrt(L)
    expect(allowableMisclosure(1.0, 'second')).toBeCloseTo(6.0, 1)
    // 3rd order: 10*sqrt(L)
    expect(allowableMisclosure(1.0, 'third')).toBeCloseTo(10.0, 1)
    // For L=4 km, 4th order: 20*sqrt(4) = 40mm
    expect(allowableMisclosure(4.0, 'fourth')).toBeCloseTo(40.0, 1)
  })

  test('throws when no observations provided', () => {
    expect(function() {
      adjustLevelNetwork([], [{ id: 'A', rl: 100, isFixed: true }], 'third')
    }).toThrow('At least one level observation')
  })

  test('throws when no fixed control point', () => {
    const obs: LevelObservation[] = [
      { fromId: 'A', toId: 'B', heightDifference: 1.0, distance: 50, weight: 1 },
    ]
    expect(function() {
      adjustLevelNetwork(obs, [{ id: 'A', rl: 100, isFixed: false }], 'third')
    }).toThrow('At least one fixed control point')
  })

  test('forward propagation gives initial height estimates', () => {
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'TP1', heightDifference: 2.500, distance: 50, weight: 1 },
      { fromId: 'TP1', toId: 'BM2', heightDifference: -1.200, distance: 50, weight: 1 },
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1200.000, isFixed: true },
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'third')
    const tp1 = result.adjustedLevels.find(function(p) { return p.id === 'TP1' })
    expect(tp1).toBeDefined()
    expect(tp1!.rl).toBeCloseTo(1202.5, 0) // initial: 1200 + 2.5
  })

  test('all-fixed-stations edge case returns residuals', () => {
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'BM2', heightDifference: 5.000, distance: 100, weight: 1 },
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1000.000, isFixed: true },
      { id: 'BM2', rl: 1005.010, isFixed: true }, // 10mm misclosure
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'fourth')
    expect(result.adjustedLevels).toHaveLength(2)
    expect(result.residuals).toHaveLength(1)
    // Residual should be non-zero since observed diff != actual diff
    expect(result.residuals[0].residual).toBeDefined()
  })

  test('reference variance is computed', () => {
    const observations: LevelObservation[] = [
      { fromId: 'BM1', toId: 'TP1', heightDifference: 1.000, distance: 30, weight: 1000 },
      { fromId: 'TP1', toId: 'BM2', heightDifference: -0.500, distance: 30, weight: 1000 },
      { fromId: 'BM2', toId: 'BM1', heightDifference: -0.510, distance: 30, weight: 1000 }, // 10mm misclosure
    ]
    const controlPoints: LevelControlPoint[] = [
      { id: 'BM1', rl: 1000.000, isFixed: true },
    ]

    const result = adjustLevelNetwork(observations, controlPoints, 'third')
    expect(result.referenceVariance).toBeGreaterThanOrEqual(0)
    expect(result.degreesOfFreedom).toBeGreaterThan(0)
  })
})

describe('computeObservations', () => {
  test('builds LevelObservation from BS/FS reading pairs', () => {
    const readings = [
      { stationId: 'BM1', type: 'BS', staffReading: 1.500, distance: 30 },
      { stationId: 'TP1', type: 'FS', staffReading: 0.800, distance: 30 },
      { stationId: 'TP1', type: 'BS', staffReading: 1.400, distance: 25 },
      { stationId: 'BM2', type: 'FS', staffReading: 0.700, distance: 25 },
    ]

    const observations = computeObservations(readings)
    expect(observations).toHaveLength(2)
    expect(observations[0].fromId).toBe('BM1')
    expect(observations[0].toId).toBe('TP1')
    expect(observations[0].heightDifference).toBeCloseTo(0.7, 5)
    expect(observations[0].weight).toBeGreaterThan(0)
  })

  test('ignores IS readings', () => {
    const readings = [
      { stationId: 'BM1', type: 'BS', staffReading: 1.500, distance: 30 },
      { stationId: 'TP1', type: 'IS', staffReading: 1.200, distance: 30 },
      { stationId: 'TP1', type: 'FS', staffReading: 0.800, distance: 30 },
    ]

    const observations = computeObservations(readings)
    expect(observations).toHaveLength(1) // IS doesn't create an observation
  })

  test('returns empty for unmatched BS', () => {
    const readings = [
      { stationId: 'BM1', type: 'BS', staffReading: 1.500, distance: 30 },
    ]
    const observations = computeObservations(readings)
    expect(observations).toHaveLength(0)
  })
})

/**
 * Benchmark Sheet Generator
 *
 * Generates a benchmark schedule / control point summary sheet from
 * level network adjustment results. Used for Kenya survey submissions
 * to document known control points and their adjusted RLs.
 */

import {
  LevelAdjustmentResult,
  LevelControlPoint,
  LevelObservation,
  AdjustedLevel,
  LEVEL_ORDER_LIMITS,
} from './digitalLevelTypes'

// ─── Types ───────────────────────────────────────────────────────────────────

export interface BenchmarkRow {
  pointId: string
  description?: string
  rlOriginal?: number
  rlAdjusted: number
  sigmaRL: number
  isFixed: boolean
  order?: string
}

export interface BenchmarkSheet {
  projectName?: string
  surveyor?: string
  date?: string
  order: string
  instrument?: string
  staff?: string
  totalDistanceKm: number
  misclosureMm: number
  allowableMisclosureMm: number
  passed: boolean
  referenceVariance: number
  degreesOfFreedom: number
  benchmarks: BenchmarkRow[]
  remarks?: string
}

// ─── Sheet Generation ────────────────────────────────────────────────────────

/**
 * Generate a benchmark sheet from level network adjustment results.
 *
 * @param adjustmentResult - Output from adjustLevelNetwork()
 * @param controlPoints - Original control point data (for descriptions, original RLs)
 * @param options - Sheet metadata
 */
export function generateBenchmarkSheet(
  adjustmentResult: LevelAdjustmentResult,
  controlPoints: LevelControlPoint[],
  options?: {
    projectName?: string
    surveyor?: string
    date?: string
    instrument?: string
    staff?: string
    remarks?: string
  }
): BenchmarkSheet {
  // Build CP map for descriptions and original RLs
  const cpMap = new Map<string, LevelControlPoint>()
  for (const cp of controlPoints) {
    cpMap.set(cp.id, cp)
  }

  // Build benchmark rows
  const benchmarks: BenchmarkRow[] = adjustmentResult.adjustedLevels.map(function(level: AdjustedLevel) {
    const cp = cpMap.get(level.id)
    return {
      pointId: level.id,
      description: cp ? cp.id : undefined,
      rlOriginal: cp ? cp.rl : undefined,
      rlAdjusted: level.rl,
      sigmaRL: level.sigmaRL,
      isFixed: cp ? cp.isFixed : false,
      order: adjustmentResult.order,
    }
  })

  // Sort: fixed points first, then alphabetical
  benchmarks.sort(function(a, b) {
    if (a.isFixed && !b.isFixed) return -1
    if (!a.isFixed && b.isFixed) return 1
    return a.pointId.localeCompare(b.pointId)
  })

  const orderInfo = LEVEL_ORDER_LIMITS[adjustmentResult.order] || LEVEL_ORDER_LIMITS['fourth']

  return {
    projectName: options?.projectName,
    surveyor: options?.surveyor,
    date: options?.date,
    order: adjustmentResult.order,
    instrument: options?.instrument,
    staff: options?.staff,
    totalDistanceKm: adjustmentResult.totalDistance,
    misclosureMm: adjustmentResult.misclosure,
    allowableMisclosureMm: adjustmentResult.allowableMisclosure,
    passed: adjustmentResult.passed,
    referenceVariance: adjustmentResult.referenceVariance,
    degreesOfFreedom: adjustmentResult.degreesOfFreedom,
    benchmarks,
    remarks: options?.remarks,
  }
}

/**
 * Format a benchmark sheet as plain text (for field notes or CSV export).
 */
export function formatBenchmarkSheetAsText(sheet: BenchmarkSheet): string {
  const lines: string[] = []

  lines.push('BENCHMARK SHEET / CONTROL POINT SUMMARY')
  lines.push('========================================')
  if (sheet.projectName) lines.push('Project: ' + sheet.projectName)
  if (sheet.surveyor) lines.push('Surveyor: ' + sheet.surveyor)
  if (sheet.date) lines.push('Date: ' + sheet.date)
  if (sheet.instrument) lines.push('Instrument: ' + sheet.instrument)
  if (sheet.staff) lines.push('Staff: ' + sheet.staff)
  lines.push('Order: ' + sheet.order + ' (' + (LEVEL_ORDER_LIMITS[sheet.order]?.label || '') + ')')
  lines.push('Total Distance: ' + sheet.totalDistanceKm.toFixed(3) + ' km')
  lines.push('Misclosure: ' + sheet.misclosureMm.toFixed(1) + ' mm')
  lines.push('Allowable: ' + sheet.allowableMisclosureMm.toFixed(1) + ' mm')
  lines.push('Passed: ' + (sheet.passed ? 'YES' : 'NO'))
  lines.push('Reference Variance: ' + sheet.referenceVariance.toFixed(6))
  lines.push('Degrees of Freedom: ' + sheet.degreesOfFreedom)
  lines.push('')

  // Table header
  lines.push('Point        Fixed   RL Orig     RL Adjusted  Sigma RL (m)')
  lines.push('-----------  ------  ----------  -----------  ------------')

  for (const bm of sheet.benchmarks) {
    const fixed = bm.isFixed ? 'Yes' : 'No'
    const orig = bm.rlOriginal !== undefined ? bm.rlOriginal.toFixed(4) : '---'
    const adj = bm.rlAdjusted.toFixed(4)
    const sigma = bm.sigmaRL.toFixed(6)
    lines.push(
      bm.pointId.padEnd(12) + ' ' +
      fixed.padEnd(7) + ' ' +
      orig.padEnd(11) + ' ' +
      adj.padEnd(12) + ' ' +
      sigma
    )
  }

  if (sheet.remarks) {
    lines.push('')
    lines.push('REMARKS: ' + sheet.remarks)
  }

  return lines.join('\n')
}

/**
 * Validate whether a benchmark sheet meets Kenya survey standards
 * for the declared order.
 */
export function validateBenchmarkSheet(sheet: BenchmarkSheet): {
  valid: boolean
  errors: string[]
  warnings: string[]
} {
  const errors: string[] = []
  const warnings: string[] = []

  if (sheet.benchmarks.length === 0) {
    errors.push('No benchmark points in sheet')
  }

  const fixedCount = sheet.benchmarks.filter(function(b) { return b.isFixed }).length
  if (fixedCount === 0) {
    errors.push('At least one fixed control point is required')
  }

  if (!sheet.passed) {
    errors.push(
      'Misclosure (' + sheet.misclosureMm.toFixed(1) + ' mm) exceeds allowable limit (' +
      sheet.allowableMisclosureMm.toFixed(1) + ' mm) for ' + sheet.order + ' order'
    )
  }

  // Check sigma RL for adjusted points
  for (const bm of sheet.benchmarks) {
    if (!bm.isFixed && bm.sigmaRL > 0.1) {
      warnings.push(
        'Point ' + bm.pointId + ' has large sigma RL (' +
        (bm.sigmaRL * 1000).toFixed(1) + ' mm) — check observation quality'
      )
    }
  }

  if (sheet.totalDistanceKm === 0) {
    warnings.push('Total distance is zero — verify observation distances')
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings,
  }
}

// Digital Level Unified Import – Auto-detect Format + Parse
// Supports: Leica DNA03, Leica DiNi 12/22, Topcon DL, Generic CSV

import { LevelFormat, LevelImportResult, LevelObservation } from './digitalLevelTypes'
import { parseDNA03 } from './parseDNA03'
import { parseDiNi } from './parseDiNi'
import { parseTopconDL } from './parseTopconDL'

/**
 * Detect the digital level file format from content and filename.
 */
export function detectLevelFormat(content: string, filename: string): LevelFormat {
  const ext = filename.toLowerCase().split('.').pop() || ''
  const firstLine = content.trim().split(/\r?\n/)[0]?.trim() || ''
  const firstThreeLines = content.trim().split(/\r?\n/).slice(0, 3).join('\n')

  // ── Extension-based detection ─────────────────────────────────
  if (ext === 'rdt' || ext === 'dna') return 'dna03'
  if (ext === 'raw' || ext === 'dat') {
    // Could be DiNi or Topcon – check content
    if (firstThreeLines.includes('DiNi') || content.includes('Staff1:')) return 'dini'
    if (firstThreeLines.match(/topcon/i) || firstThreeLines.match(/dl/i)) return 'topcon-dl'
  }
  if (ext === 'csv' || ext === 'txt') {
    // CSV is the fallback
  }

  // ── Content-based detection ───────────────────────────────────
  // DNA03: header with "DNA03" and "Digital Level"
  if (firstLine.includes('DNA03') && firstLine.includes('Digital Level')) return 'dna03'
  if (firstLine.includes(' DNA03')) return 'dna03'
  if (firstLine.match(/Inst-No:/)) return 'dna03'

  // DiNi: pipe-delimited data, Staff1/Staff2 headers
  if (content.includes('Staff1:') || content.includes('Staff2:')) return 'dini'
  if (firstLine.includes('DiNi')) return 'dini'
  // DiNi RAW: pipe-separated data rows
  if (firstLine.match(/^\d+\|/)) return 'dini'

  // Topcon DL: model identifier
  if (firstLine.match(/topcon/i) && firstLine.match(/dl/i)) return 'topcon-dl'
  if (firstLine.match(/^DL[-]?\d{2,3}/)) return 'topcon-dl'

  // ── CSV detection ─────────────────────────────────────────────
  // Check for CSV header keywords
  const lowerFirst = firstLine.toLowerCase()
  if (
    lowerFirst.includes('station') &&
    (lowerFirst.includes('backsight') || lowerFirst.includes('foresight') || lowerFirst.includes('reading'))
  ) {
    return 'csv'
  }

  // Check if first line has comma-separated values with numeric data
  const csvParts = firstLine.split(',').map(s => s.trim())
  if (csvParts.length >= 3 && csvParts.some(p => !isNaN(parseFloat(p)) && p.length > 0)) {
    return 'csv'
  }

  return 'unknown'
}

/**
 * Parse generic CSV level data.
 *
 * Supported column headers (case-insensitive):
 *   Station, Backsight, Foresight, Distance, InstrumentHeight, StaffHeight, Type, Comment
 *
 * Rows can be:
 *   BM1,,1.65432,0.025,1.600,,BS
 *   BM1,1.65432,0.87654,0.030,1.600,,FS
 *
 * Or simplified:
 *   Station,Reading,Distance,Type
 */
function parseGenericCSV(content: string): LevelImportResult {
  const lines = content.split(/\r?\n/).filter(l => l.trim().length > 0)
  const parseErrors: string[] = []
  const readings: LevelImportResult['readings'] = []

  const metadata: LevelImportResult['metadata'] = {
    rawLineCount: lines.length,
    parseErrors: [],
  }

  if (lines.length === 0) {
    return { format: 'csv', readings: [], observations: [], metadata }
  }

  // Parse header
  const header = lines[0].split(',').map(s => s.trim().toLowerCase())
  const dataLines = lines.slice(1)

  // Find column indices
  const stationIdx = header.findIndex(h =>
    h === 'station' || h === 'point' || h === 'ptid' || h === 'name' || h === 'stationid'
  )
  const bsIdx = header.findIndex(h =>
    h === 'backsight' || h === 'bs' || h === 'bsreading'
  )
  const fsIdx = header.findIndex(h =>
    h === 'foresight' || h === 'fs' || h === 'fsreading'
  )
  const readingIdx = header.findIndex(h =>
    h === 'reading' || h === 'staffreading' || h === 'staff' || h === 'staffreading'
  )
  const distIdx = header.findIndex(h =>
    h === 'distance' || h === 'dist' || h === 'sightdistance'
  )
  const ihIdx = header.findIndex(h =>
    h === 'instrumentheight' || h === 'hi' || h === 'heightofinstrument'
  )
  const typeIdx = header.findIndex(h =>
    h === 'type' || h === 'sighttype'
  )
  const commentIdx = header.findIndex(h =>
    h === 'comment' || h === 'remarks' || h === 'note'
  )

  // We need either station+reading+type, or station+bs+fs columns
  const hasSimpleFormat = stationIdx >= 0 && readingIdx >= 0
  const hasBSFSFormat = stationIdx >= 0 && (bsIdx >= 0 || fsIdx >= 0)

  if (!hasSimpleFormat && !hasBSFSFormat) {
    parseErrors.push('Could not find required columns (Station + Reading or Station + BS/FS)')
    metadata.parseErrors = parseErrors
    return { format: 'csv', readings: [], observations: [], metadata }
  }

  for (let i = 0; i < dataLines.length; i++) {
    const parts = dataLines[i].split(',').map(s => s.trim())
    if (parts.length < 2 || !parts[stationIdx]) continue

    const stationId = parts[stationIdx]

    if (hasSimpleFormat) {
      const staffReading = parseFloat(parts[readingIdx])
      if (isNaN(staffReading)) {
        parseErrors.push(`Line ${i + 2}: Invalid reading at station ${stationId}`)
        continue
      }

      const distance = distIdx >= 0 ? parseFloat(parts[distIdx]) : 30
      const instrumentHeight = ihIdx >= 0 ? parseFloat(parts[ihIdx]) : 1.6
      const typeStr = typeIdx >= 0 ? (parts[typeIdx] || '').toUpperCase() : 'BS'
      const comment = commentIdx >= 0 ? parts[commentIdx] : undefined

      let type: 'BS' | 'FS' | 'IS' = 'BS'
      if (typeStr.includes('FS') || typeStr === 'FORESIGHT') type = 'FS'
      else if (typeStr.includes('IS') || typeStr === 'INTERMEDIATE') type = 'IS'

      readings.push({
        stationId,
        type,
        staffReading,
        distance: isNaN(distance) ? 30 : distance,
        instrumentHeight: isNaN(instrumentHeight) ? 1.6 : instrumentHeight,
        comment,
      })
    } else if (hasBSFSFormat) {
      // BS/FS format: each row has station, BS, FS
      const bs = bsIdx >= 0 ? parseFloat(parts[bsIdx]) : NaN
      const fs = fsIdx >= 0 ? parseFloat(parts[fsIdx]) : NaN
      const distance = distIdx >= 0 ? parseFloat(parts[distIdx]) : 30
      const instrumentHeight = ihIdx >= 0 ? parseFloat(parts[ihIdx]) : 1.6
      const comment = commentIdx >= 0 ? parts[commentIdx] : undefined

      if (!isNaN(bs)) {
        readings.push({
          stationId,
          type: 'BS',
          staffReading: bs,
          distance: isNaN(distance) ? 30 : distance,
          instrumentHeight: isNaN(instrumentHeight) ? 1.6 : instrumentHeight,
          comment,
        })
      }
      if (!isNaN(fs)) {
        readings.push({
          stationId,
          type: 'FS',
          staffReading: fs,
          distance: isNaN(distance) ? 30 : distance,
          instrumentHeight: isNaN(instrumentHeight) ? 1.6 : instrumentHeight,
          comment,
        })
      }
    }
  }

  metadata.parseErrors = parseErrors

  // Build observations from BS/FS pairs
  const observations = buildCSVObservations(readings)

  return { format: 'csv', readings, observations, metadata }
}

/**
 * Build observations from CSV readings (BS/FS pairs).
 */
function buildCSVObservations(readings: LevelImportResult['readings']): LevelImportResult['observations'] {
  const observations: LevelObservation[] = []
  let bsReading: any = null

  for (const r of readings) {
    if (r.type === 'BS') {
      bsReading = r
    } else if (r.type === 'FS' && bsReading) {
      const heightDifference = bsReading.staffReading - r.staffReading
      const distance = (bsReading.distance + r.distance) / 2
      const distKm = distance / 1000
      const weight = distKm > 0 ? 1 / (distKm * distKm) : 1000

      observations.push({
        fromId: bsReading.stationId,
        toId: r.stationId,
        heightDifference,
        distance,
        weight,
      })
      bsReading = null
    }
  }

  return observations
}

/**
 * Unified import: auto-detect format and parse.
 */
export function importDigitalLevel(content: string, filename: string): LevelImportResult {
  const format = detectLevelFormat(content, filename)

  switch (format) {
    case 'dna03':
      return parseDNA03(content, filename)
    case 'dini':
      return parseDiNi(content, filename)
    case 'topcon-dl':
      return parseTopconDL(content, filename)
    case 'csv':
      return parseGenericCSV(content)
    default:
      // Try CSV as last resort
      return parseGenericCSV(content)
  }
}

export { parseGenericCSV }

