import { z } from 'zod'

export const StationSchema = z.object({
  id: z.string().min(1, 'Station ID is required'),
  name: z.string().min(1, 'Station name is required'),
  easting: z.number().finite(),
  northing: z.number().finite(),
  elevation: z.number().finite(),
  isFixed: z.boolean(),
})

export type Station = z.infer<typeof StationSchema>

export const ObservationSchema = z.object({
  from: z.string().min(1, 'From station is required'),
  to: z.string().min(1, 'To station is required'),
  deltaE: z.number().finite(),
  deltaN: z.number().finite(),
  deltaH: z.number().finite(),
  stdDevE: z.number().positive().max(1).default(0.005),
  stdDevN: z.number().positive().max(1).default(0.005),
  stdDevH: z.number().positive().max(1).default(0.010),
})

export type Observation = z.infer<typeof ObservationSchema>

let dbClient: any = null

async function logNetworkAdjustment(stations: Station[], observations: Observation[]) {
  if (typeof window === 'undefined') return
  try {
    const { createClient } = await import('@/lib/api-client/client')
    dbClient = createClient()
    await dbClient.from('network_adjustments').insert({
      stations,
      observations,
      status: 'pending',
    })
  } catch {
    // Non-blocking
  }
}

export interface AdjustedStation extends Station {
  residualE: number
  residualN: number
  residualH: number
  semiMajor: number
  semiMinor: number
  orientation: number
  sigmaE: number
  sigmaN: number
  sigmaH: number
}

export interface AdjustmentResult {
  adjustedStations: AdjustedStation[]
  sigmaZero: number
  degreesOfFreedom: number
  iterations: number
  passedTolerance: boolean
  warnings: string[]
  /** T1.5g: LSA statistical report (global test, w-test, reliability) */
  statisticalReport?: import('./lsaStatisticalTesting').StatisticalReport
}

export function adjustNetwork(
  stationsInput: Station[],
  observationsInput: Observation[]
): AdjustmentResult {
  const stationValidation = StationSchema.array().safeParse(stationsInput)
  if (!stationValidation.success) {
    const issues = stationValidation.error.issues.map(i => `${i.path.join('.')}: ${i.message}`).join('; ')
    throw new Error(`Invalid stations: ${issues}`)
  }
  const stations = stationValidation.data

  const obsValidation = ObservationSchema.array().safeParse(observationsInput)
  if (!obsValidation.success) {
    const issues = obsValidation.error.issues.map(i => `${i.path.join('.')}: ${i.message}`).join('; ')
    throw new Error(`Invalid observations: ${issues}`)
  }
  const observations = obsValidation.data

  const warnings: string[] = []

  logNetworkAdjustment(stations, observations).catch(() => {})

  const fixed = stations.filter(s => s.isFixed)
  if (fixed.length === 0) {
    throw new Error('At least one fixed control station is required.')
  }
  if (fixed.length < 2) {
    warnings.push('Only 1 fixed control station provided. Per Survey Regulations Reg. 60(2)(c) and Reg. 67, cadastral traverses must close between two previously fixed stations. A single fixed point results in an unconstrained network (swinging traverse) — prohibited for cadastral surveys.')
  }
  if (observations.length === 0) {
    throw new Error('At least one baseline observation is required.')
  }

  const free = stations.filter(s => !s.isFixed)
  const n = free.length * 3 // 3D: E, N, H
  const m = observations.length * 3 // 3 equations per baseline
  const dof = m - n

  if (dof < 0) {
    throw new Error(
      `Insufficient observations. Need at least ${Math.ceil(n / 3)} baselines for ${free.length} free stations.`
    )
  }

  const stationIndex = new Map<string, number>()
  free.forEach((s, i) => stationIndex.set(s.id, i))

  const coords = new Map<string, { e: number; n: number; h: number }>()
  stations.forEach(s => coords.set(s.id, { e: s.easting, n: s.northing, h: s.elevation }))

  const A: number[][] = []
  const W: number[] = []
  const l: number[] = []

  for (const obs of observations) {
    const fromCoord = coords.get(obs.from)!
    const toCoord = coords.get(obs.to)!

    const wE = 1 / (obs.stdDevE * obs.stdDevE)
    const wN = 1 / (obs.stdDevN * obs.stdDevN)
    const wH = 1 / (obs.stdDevH * obs.stdDevH)

    // Delta Easting
    const rowE = new Array(n).fill(0)
    if (stationIndex.has(obs.to)) rowE[stationIndex.get(obs.to)! * 3] = 1
    if (stationIndex.has(obs.from)) rowE[stationIndex.get(obs.from)! * 3] = -1
    const obsE = toCoord.e - fromCoord.e
    A.push(rowE)
    W.push(wE)
    l.push(obs.deltaE - obsE)

    // Delta Northing
    const rowN = new Array(n).fill(0)
    if (stationIndex.has(obs.to)) rowN[stationIndex.get(obs.to)! * 3 + 1] = 1
    if (stationIndex.has(obs.from)) rowN[stationIndex.get(obs.from)! * 3 + 1] = -1
    const obsN = toCoord.n - fromCoord.n
    A.push(rowN)
    W.push(wN)
    l.push(obs.deltaN - obsN)

    // Delta Height
    const rowH = new Array(n).fill(0)
    if (stationIndex.has(obs.to)) rowH[stationIndex.get(obs.to)! * 3 + 2] = 1
    if (stationIndex.has(obs.from)) rowH[stationIndex.get(obs.from)! * 3 + 2] = -1
    const obsH = toCoord.h - fromCoord.h
    A.push(rowH)
    W.push(wH)
    l.push(obs.deltaH - obsH)
  }

  const N = multiplyAtWA(A, W, n)
  const t = multiplyAtWl(A, W, l, n)
  
  let x: number[]
  try {
    x = solveLinearSystem(N, t)
  } catch (err: unknown) {
    throw new Error('Failed to solve network equations: ' + (err as Error).message)
  }

  free.forEach((s, i) => {
    const c = coords.get(s.id)!
    coords.set(s.id, { e: c.e + x[i * 3], n: c.n + x[i * 3 + 1], h: c.h + x[i * 3 + 2] })
  })

  const residuals: number[] = []
  for (let i = 0; i < A.length; i++) {
    let ax = 0
    for (let j = 0; j < n; j++) ax += A[i][j] * x[j]
    residuals.push(ax - l[i])
  }

  const vWv = residuals.reduce((sum, v, i) => sum + W[i] * v * v, 0)
  const sigmaZero = dof > 0 ? Math.sqrt(vWv / dof) : 0

  if (dof === 0) {
    warnings.push('Zero degrees of freedom — cannot compute reliable error estimates.')
  }

  const Qxx = invertMatrix(N, n)

  const maxAllowedResidualE = 3 * Math.max(...observations.map(o => o.stdDevE))
  const maxAllowedResidualN = 3 * Math.max(...observations.map(o => o.stdDevN))
  const maxAllowedResidualH = 3 * Math.max(...observations.map(o => o.stdDevH))
  
  const passedTolerance = residuals.every((r, i) => {
    const mod = i % 3
    if (mod === 0) return Math.abs(r) < maxAllowedResidualE
    if (mod === 1) return Math.abs(r) < maxAllowedResidualN
    return Math.abs(r) < maxAllowedResidualH
  })

  if (!passedTolerance) {
    warnings.push('One or more residuals exceed 3σ tolerance. Check for blunders in baseline observations.')
  }
  if (sigmaZero > 2.0) {
    warnings.push(`Reference standard deviation (σ₀ = ${sigmaZero.toFixed(3)}) is high. Network may contain blunders or incorrect standard deviations.`)
  }

  const adjustedStations: AdjustedStation[] = stations.map(s => {
    const adjusted = coords.get(s.id)!
    let residualE = 0
    let residualN = 0
    let residualH = 0
    let semiMajor = 0
    let semiMinor = 0
    let orientation = 0
    let sigmaE = 0
    let sigmaN = 0
    let sigmaH = 0

    if (!s.isFixed) {
      const i = stationIndex.get(s.id)!
      residualE = x[i * 3]
      residualN = x[i * 3 + 1]
      residualH = x[i * 3 + 2]

      const qEE = Qxx[i * 3][i * 3]
      const qNN = Qxx[i * 3 + 1][i * 3 + 1]
      const qHH = Qxx[i * 3 + 2][i * 3 + 2]
      const qEN = Qxx[i * 3][i * 3 + 1]

      sigmaE = sigmaZero * Math.sqrt(Math.max(qEE, 0))
      sigmaN = sigmaZero * Math.sqrt(Math.max(qNN, 0))
      sigmaH = sigmaZero * Math.sqrt(Math.max(qHH, 0))

      const t2 = Math.atan2(2 * qEN, qEE - qNN) / 2
      const A2 = (qEE + qNN) / 2 + Math.sqrt(Math.pow((qEE - qNN) / 2, 2) + qEN * qEN)
      const B2 = (qEE + qNN) / 2 - Math.sqrt(Math.pow((qEE - qNN) / 2, 2) + qEN * qEN)
      semiMajor = sigmaZero * Math.sqrt(Math.max(A2, 0))
      semiMinor = sigmaZero * Math.sqrt(Math.max(B2, 0))
      orientation = (t2 * 180 / Math.PI + 360) % 360
    }

    return {
      ...s,
      easting: adjusted.e,
      northing: adjusted.n,
      elevation: adjusted.h,
      residualE,
      residualN,
      residualH,
      semiMajor,
      semiMinor,
      orientation,
      sigmaE,
      sigmaN,
      sigmaH,
    }
  })

  // T1.5g FIX (2026-07-10): Compute LSA statistical report (global test + w-test + reliability)
  let statisticalReport: AdjustmentResult['statisticalReport']
  if (dof > 0 && residuals.length > 0) {
    try {
      const { computeStatisticalReport, computeQvvDiagonal } = require('./lsaStatisticalTesting')

      // Build observation labels for the w-test
      const observationLabels = observations.flatMap(obs => [
        { from: obs.from, to: obs.to, component: 'E' as const },
        { from: obs.from, to: obs.to, component: 'N' as const },
        { from: obs.from, to: obs.to, component: 'H' as const },
      ])

      // Compute Qvv diagonal (needed for w-test and reliability)
      const QvvDiag = computeQvvDiagonal(A, W, Qxx)

      statisticalReport = computeStatisticalReport(
        sigmaZero,
        dof,
        residuals,
        QvvDiag,
        observationLabels,
        0.05,
      )

      // Add statistical report warnings to the existing warnings
      if (statisticalReport && statisticalReport.warnings.length > 0) {
        warnings.push(...statisticalReport.warnings)
      }
    } catch {
      // Statistical testing is non-blocking — if it fails, the adjustment is still valid
    }
  }

  return {
    adjustedStations,
    sigmaZero,
    degreesOfFreedom: dof,
    iterations: 1,
    passedTolerance,
    warnings,
    statisticalReport,
  }
}

function multiplyAtWA(A: number[][], W: number[], n: number): number[][] {
  const result = Array.from({ length: n }, () => new Array(n).fill(0))
  for (let i = 0; i < n; i++)
    for (let j = 0; j < n; j++)
      for (let k = 0; k < A.length; k++)
        result[i][j] += A[k][i] * W[k] * A[k][j]
  return result
}

function multiplyAtWl(A: number[][], W: number[], l: number[], n: number): number[] {
  const result = new Array(n).fill(0)
  for (let i = 0; i < n; i++)
    for (let k = 0; k < A.length; k++)
      result[i] += A[k][i] * W[k] * l[k]
  return result
}

function solveLinearSystem(A: number[][], b: number[]): number[] {
  const n = b.length
  const M = A.map((row, i) => [...row, b[i]])

  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++)
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]

    if (Math.abs(M[col][col]) < 1e-12)
      throw new Error('Singular normal equation matrix — check network geometry.')

    for (let row = col + 1; row < n; row++) {
      const factor = M[row][col] / M[col][col]
      for (let k = col; k <= n; k++) M[row][k] -= factor * M[col][k]
    }
  }

  const x = new Array(n).fill(0)
  for (let i = n - 1; i >= 0; i--) {
    x[i] = M[i][n]
    for (let j = i + 1; j < n; j++) x[i] -= M[i][j] * x[j]
    x[i] /= M[i][i]
  }
  return x
}

function invertMatrix(A: number[][], n: number): number[][] {
  const M = A.map((row, i) => {
    const aug = [...row, ...new Array(n).fill(0)]
    aug[n + i] = 1
    return aug
  })

  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++)
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]

    const pivot = M[col][col]
    if (Math.abs(pivot) < 1e-12) return Array.from({ length: n }, () => new Array(n).fill(0))

    for (let k = 0; k < 2 * n; k++) M[col][k] /= pivot
    for (let row = 0; row < n; row++) {
      if (row === col) continue
      const factor = M[row][col]
      for (let k = 0; k < 2 * n; k++) M[row][k] -= factor * M[col][k]
    }
  }

  return M.map(row => row.slice(n))
}

import Drawing from 'dxf-writer'
import {
  initialiseSokDXFLayers,
  addStandardTitleBlock,
  DXF_LAYERS,
} from '@/lib/drawing/dxfLayers'
import type { AdjustedStation, Observation } from './networkAdjustment'

export function generateNetworkDXF(params: {
  adjustedStations: AdjustedStation[]
  observations: Observation[]
  projectData: Record<string, any>
  surveyorProfile: { fullName: string; registrationNumber: string; firmName: string }
}): string {
  const { adjustedStations, observations, projectData, surveyorProfile } = params
  const drawing = new Drawing()

  initialiseSokDXFLayers(drawing)

  addStandardTitleBlock(drawing, {
    drawingTitle: 'GPS CONTROL NETWORK DIAGRAM',
    lrNumber: projectData?.lr_number ?? 'N/A',
    county: projectData?.county ?? 'N/A',
    district: projectData?.district ?? 'N/A',
    locality: projectData?.locality ?? 'N/A',
    areaHa: 0,
    perimeterM: 0,
    surveyorName: surveyorProfile.fullName,
    registrationNumber: surveyorProfile.registrationNumber,
    firmName: surveyorProfile.firmName,
    date: new Date().toLocaleDateString('en-KE'),
    submissionRef: 'N/A',
    coordinateSystem: 'Arc 1960 / UTM Zone 37S (SRID: 21037)',
    scale: '1:5000',
    sheetNumber: '1 of 1',
    revision: 'R00',
  })

  const stationMap = new Map(adjustedStations.map(s => [s.id, s]))

  for (const obs of observations) {
    const from = stationMap.get(obs.from)
    const to = stationMap.get(obs.to)
    if (!from || !to) continue
    drawing.setActiveLayer(DXF_LAYERS.CONTROL.name)
    drawing.drawLine(from.easting, from.northing, to.easting, to.northing)
  }

  const symbolSize = 2
  for (const s of adjustedStations) {
    drawing.setActiveLayer(DXF_LAYERS.CONTROL.name)
    drawing.drawLine(s.easting, s.northing + symbolSize, s.easting - symbolSize, s.northing - symbolSize)
    drawing.drawLine(s.easting - symbolSize, s.northing - symbolSize, s.easting + symbolSize, s.northing - symbolSize)
    drawing.drawLine(s.easting + symbolSize, s.northing - symbolSize, s.easting, s.northing + symbolSize)

    drawing.setActiveLayer(DXF_LAYERS.NOTES_TXT.name)
    drawing.drawText(
      s.easting + symbolSize * 1.5,
      s.northing,
      symbolSize * 1.2,
      0,
      `${s.name} (${s.easting.toFixed(3)}E, ${s.northing.toFixed(3)}N)`
    )

    if (!s.isFixed && s.semiMajor > 0) {
drawing.setActiveLayer(DXF_LAYERS.NOTES_TXT.name)
      drawing.drawCircle(s.easting, s.northing, s.semiMajor * 1000)
    }
  }

  return drawing.toDxfString()
}

/**
 * Correction Pipeline — Unified Observation Processing
 * 
 * This is the heart of the survey computation engine. It applies ALL
 * corrections in the correct order to transform raw field observations
 * into corrected, grid-level observations ready for traverse computation.
 * 
 * Processing order (this order matters!):
 * 1. EDM Instrument Constant     → Add constant to raw distance
 * 2. Atmospheric Correction       → Correct slope distance for temp/pressure/humidity
 * 3. Slope Reduction              → Convert slope distance to horizontal
 * 4. Curvature & Refraction       → Correct height difference
 * 5. Sea Level Reduction          → Reduce horizontal distance to ellipsoid
 * 6. Grid Scale Factor            → Scale ellipsoid distance to grid distance
 * 7. Grid Convergence             → Correct bearings for projection convergence
 * 
 * Each stage logs what was applied for the full audit trail.
 */

import { applyAtmosphericCorrection, type AtmosphericConditions, type EDMInstrument } from '../corrections/atmospheric';
import { applyCurvatureRefractionCorrection, type CurvatureRefractionInput, KENYA_REFRACTION_COEFFICIENT } from '../corrections/curvature-refraction';
import { computeLineScaleFactor, applyGridScaleFactor, type ProjectionType } from '../corrections/grid-scale-factor';
import { applySeaLevelReduction, type SeaLevelReductionInput } from '../corrections/sea-level-reduction';
import { reduceSlopeByAngle, reduceSlopeByHeight, type SlopeReductionResult } from '../corrections/slope-reduction';
import { computeConvergence, applyConvergenceToBearing } from '../corrections/projection-convergence';

// ─── Types ───────────────────────────────────────────────────────

export interface RawObservation {
  /** From station name */
  fromStation: string;
  /** To station name */
  toStation: string;
  
  // Raw measurements
  /** Raw slope distance measured by EDM (meters) */
  rawSlopeDistance: number;
  /** Horizontal angle (decimal degrees, measured clockwise from reference) */
  horizontalAngle?: number;
  /** Vertical angle / zenith distance (decimal degrees, 90° = horizontal) */
  verticalAngle?: number;
  
  // EDM data
  /** EDM instrument constant (meters, additive) */
  edmConstant?: number;
  /** PPM setting on instrument */
  ppmSetting?: number;
  /** EDM carrier wavelength (μm): 0.6328 (HeNe) or 0.850 (IR) */
  edmWavelength?: 0.6328 | 0.850 | 0.910;
  
  // Atmospheric conditions at time of measurement
  temperature?: number;      // °C
  pressure?: number;         // hPa
  humidity?: number;         // %
  
  // Heights
  instrumentHeight?: number; // meters
  targetHeight?: number;     // meters
  heightAboveEllipsoid?: number; // Mean height of line (for sea level reduction)
  orthometricHeight?: number;    // Height above MSL
  
  // Coordinates (for scale factor and convergence)
  fromEasting?: number;
  fromNorthing?: number;
  toEasting?: number;
  toNorthing?: number;
  
  // Location
  latitude?: number;         // decimal degrees (for Earth radius)
  longitude?: number;        // decimal degrees (for convergence)
  
  // Bearing data
  trueBearing?: number;      // True (astronomic) bearing if observed
}

export interface CorrectionStageLog {
  stage: string;
  input: number;
  output: number;
  correction: number;
  unit: string;
}

export interface ProcessedObservation {
  /** From station name */
  fromStation: string;
  /** To station name */
  toStation: string;
  
  // Corrected distances
  /** Raw slope distance (meters) */
  rawSlopeDistance: number;
  /** After EDM constant (meters) */
  afterEdmConstant: number;
  /** After atmospheric correction (meters) */
  afterAtmospheric: number;
  /** Horizontal distance after slope reduction (meters) */
  horizontalDistance: number;
  /** After sea level reduction (meters) */
  afterSeaLevel: number;
  /** After grid scale factor — final grid distance (meters) */
  gridDistance: number;
  
  // Corrected angles
  /** Original horizontal angle (decimal degrees) */
  rawHorizontalAngle?: number;
  /** Grid bearing (decimal degrees) */
  gridBearing?: number;
  /** True bearing (decimal degrees) */
  trueBearing?: number;
  
  // Height data
  /** Height difference after C&R correction (meters) */
  heightDifference?: number;
  
  // Correction details
  /** Line scale factor applied */
  lineScaleFactor?: number;
  /** Grid convergence at point (decimal degrees) */
  convergence?: number;
  /** Atmospheric correction ppm */
  atmosphericPPM?: number;
  /** Sea level reduction ppm */
  seaLevelPPM?: number;
  
  // Full audit trail
  correctionLog: CorrectionStageLog[];
  
  // Flags
  /** Whether any correction exceeded significance thresholds */
  warnings: string[];
}

export interface PipelineConfig {
  /** Projection type for grid computations */
  projection: ProjectionType;
  /** Central meridian for convergence computation */
  centralMeridian: number;
  /** Refraction coefficient (default: 0.13 Kenya) */
  refractionCoefficient?: number;
  /** Geoid undulation for Kenya (default: -12m) */
  geoidUndulation?: number;
  /** EDM instrument defaults */
  defaultInstrument?: Partial<EDMInstrument>;
  /** Whether to apply each correction stage */
  applyAtmospheric?: boolean;
  applyCurvatureRefraction?: boolean;
  applySeaLevelReduction?: boolean;
  applyGridScaleFactor?: boolean;
  applyConvergence?: boolean;
  /** Minimum distance (meters) to apply C&R correction */
  crThresholdDistance?: number;
}

// ─── Default Config ──────────────────────────────────────────────

export const KENYA_DEFAULT_CONFIG: PipelineConfig = {
  projection: 'UTM37S',
  centralMeridian: 39,
  refractionCoefficient: KENYA_REFRACTION_COEFFICIENT,
  geoidUndulation: -12,
  defaultInstrument: {
    wavelength: 0.850,
    referenceN: 273.82,
    constant: 0,
    ppmSetting: 0,
  },
  applyAtmospheric: true,
  applyCurvatureRefraction: true,
  applySeaLevelReduction: true,
  applyGridScaleFactor: true,
  applyConvergence: true,
  crThresholdDistance: 200, // Apply C&R for lines > 200m
};

// ─── Pipeline Function ───────────────────────────────────────────

/**
 * Process a raw observation through the full correction pipeline.
 * 
 * This is the main entry point for observation processing. It applies
 * all corrections in the correct order and produces a fully corrected
 * observation with a complete audit trail.
 * 
 * @param observation - Raw field observation
 * @param config - Pipeline configuration
 * @returns Processed observation with all corrections applied
 */
export function processObservation(
  observation: RawObservation,
  config: PipelineConfig = KENYA_DEFAULT_CONFIG
): ProcessedObservation {
  const log: CorrectionStageLog[] = [];
  const warnings: string[] = [];
  
  let currentDistance = observation.rawSlopeDistance;
  
  // ─── Stage 1: EDM Instrument Constant ─────────────────────
  const edmConstant = observation.edmConstant ?? config.defaultInstrument?.constant ?? 0;
  const afterEdmConstant = currentDistance + edmConstant;
  log.push({
    stage: 'EDM Instrument Constant',
    input: currentDistance,
    output: afterEdmConstant,
    correction: edmConstant,
    unit: 'meters',
  });
  currentDistance = afterEdmConstant;
  
  // ─── Stage 2: Atmospheric Correction ──────────────────────
  let afterAtmospheric = currentDistance;
  let atmosphericPPM = 0;
  
  if (config.applyAtmospheric && observation.temperature !== undefined && observation.pressure !== undefined) {
    const conditions: AtmosphericConditions = {
      temperature: observation.temperature,
      pressure: observation.pressure,
      humidity: observation.humidity ?? 50,
    };
    
    const atmResult = applyAtmosphericCorrection(currentDistance, conditions, {
      wavelength: observation.edmWavelength ?? config.defaultInstrument?.wavelength,
      referenceN: config.defaultInstrument?.referenceN,
      ppmSetting: observation.ppmSetting ?? config.defaultInstrument?.ppmSetting,
    });
    
    afterAtmospheric = atmResult.correctedDistance;
    atmosphericPPM = atmResult.ppmCorrection;
    
    log.push({
      stage: 'Atmospheric Correction',
      input: currentDistance,
      output: afterAtmospheric,
      correction: atmResult.correctionMeters,
      unit: 'meters',
    });
    
    if (Math.abs(atmosphericPPM) > 30) {
      warnings.push(`Atmospheric correction of ${atmosphericPPM.toFixed(1)} ppm is large — verify temperature/pressure readings`);
    }
    
    currentDistance = afterAtmospheric;
  } else if (config.applyAtmospheric) {
    warnings.push('Atmospheric correction skipped — missing temperature/pressure data');
  }
  
  // ─── Stage 3: Slope Reduction ─────────────────────────────
  let horizontalDistance = currentDistance;
  let heightDifference: number | undefined;
  let slopeResult: SlopeReductionResult | undefined;
  
  if (observation.verticalAngle !== undefined) {
    slopeResult = reduceSlopeByAngle({
      slopeDistance: currentDistance,
      verticalAngle: observation.verticalAngle,
    });
    horizontalDistance = slopeResult.horizontalDistance;
    heightDifference = slopeResult.verticalComponent;
    
    // Add instrument/target height to height difference
    if (observation.instrumentHeight !== undefined && observation.targetHeight !== undefined) {
      heightDifference += (observation.instrumentHeight - observation.targetHeight);
    }
    
    log.push({
      stage: 'Slope Reduction',
      input: currentDistance,
      output: horizontalDistance,
      correction: currentDistance - horizontalDistance,
      unit: 'meters',
    });
  }
  
  // ─── Stage 4: Curvature & Refraction ─────────────────────
  let correctedHeightDiff = heightDifference;
  
  if (config.applyCurvatureRefraction && observation.verticalAngle !== undefined && slopeResult) {
    const latitude = observation.latitude ?? 0;
    const refractionK = config.refractionCoefficient ?? KENYA_REFRACTION_COEFFICIENT;
    
    const crResult = applyCurvatureRefractionCorrection({
      slopeDistance: afterAtmospheric,
      verticalAngle: observation.verticalAngle,
      instrumentHeight: observation.instrumentHeight ?? 0,
      targetHeight: observation.targetHeight ?? 0,
      latitude,
      refractionCoefficient: refractionK,
    });
    
    correctedHeightDiff = crResult.correctedHeightDifference;
    
    log.push({
      stage: 'Curvature & Refraction',
      input: heightDifference ?? 0,
      output: correctedHeightDiff,
      correction: crResult.crCorrection,
      unit: 'meters',
    });
    
    if (crResult.isSignificant) {
      warnings.push(crResult.warning!);
    }
  }
  
  // ─── Stage 5: Sea Level Reduction ────────────────────────
  let afterSeaLevel = horizontalDistance;
  let seaLevelPPM = 0;
  
  if (config.applySeaLevelReduction) {
    const h = observation.heightAboveEllipsoid ?? (observation.orthometricHeight !== undefined
      ? observation.orthometricHeight + (config.geoidUndulation ?? 0)
      : undefined);
    
    if (h !== undefined) {
      const slrResult = applySeaLevelReduction({
        horizontalDistance,
        heightAboveEllipsoid: h,
        latitude: observation.latitude ?? 0,
        geoidUndulation: config.geoidUndulation ?? 0,
      });
      
      afterSeaLevel = slrResult.ellipsoidalDistance;
      seaLevelPPM = slrResult.reductionPPM;
      
      log.push({
        stage: 'Sea Level Reduction',
        input: horizontalDistance,
        output: afterSeaLevel,
        correction: slrResult.reductionMeters,
        unit: 'meters',
      });
      
      if (slrResult.reductionPPM > 100) {
        warnings.push(`Sea level reduction of ${slrResult.reductionPPM.toFixed(1)} ppm is significant at height ${h.toFixed(0)}m`);
      }
    } else {
      warnings.push('Sea level reduction skipped — no height data provided');
    }
  }
  
  // ─── Stage 6: Grid Scale Factor ──────────────────────────
  let gridDistance = afterSeaLevel;
  let lineScaleFactor: number | undefined;
  
  if (config.applyGridScaleFactor && observation.fromEasting !== undefined && observation.toEasting !== undefined) {
    // Grid scale factor currently supports UTM only
    const utmProjection = config.projection === 'UTM36S' || config.projection === 'UTM37S'
      ? config.projection
      : 'UTM37S'; // Default fallback
    
    const gsfResult = applyGridScaleFactor(
      afterSeaLevel,
      observation.fromEasting,
      observation.fromNorthing ?? 0,
      observation.toEasting,
      observation.toNorthing ?? 0,
      utmProjection
    );
    
    gridDistance = gsfResult.gridDistance;
    lineScaleFactor = gsfResult.lineScaleFactor;
    
    log.push({
      stage: 'Grid Scale Factor',
      input: afterSeaLevel,
      output: gridDistance,
      correction: gridDistance - afterSeaLevel,
      unit: 'meters',
    });
  }
  
  // ─── Stage 7: Grid Convergence (Bearing Correction) ──────
  let gridBearing: number | undefined;
  let convergence: number | undefined;
  
  if (config.applyConvergence && observation.trueBearing !== undefined && observation.longitude !== undefined) {
    const convResult = computeConvergence({
      latitude: observation.latitude ?? 0,
      longitude: observation.longitude,
      centralMeridian: config.centralMeridian,
    });
    
    convergence = convResult.convergence;
    gridBearing = applyConvergenceToBearing(observation.trueBearing, convergence);
    
    log.push({
      stage: 'Grid Convergence',
      input: observation.trueBearing,
      output: gridBearing,
      correction: convergence,
      unit: 'degrees',
    });
    
    if (convResult.isSignificant) {
      warnings.push(`Grid convergence of ${convResult.arcSeconds.toFixed(1)}" exceeds 30" threshold`);
    }
  }
  
  return {
    fromStation: observation.fromStation,
    toStation: observation.toStation,
    rawSlopeDistance: observation.rawSlopeDistance,
    afterEdmConstant,
    afterAtmospheric,
    horizontalDistance,
    afterSeaLevel,
    gridDistance,
    rawHorizontalAngle: observation.horizontalAngle,
    gridBearing,
    trueBearing: observation.trueBearing,
    heightDifference: correctedHeightDiff,
    lineScaleFactor,
    convergence,
    atmosphericPPM,
    seaLevelPPM,
    correctionLog: log,
    warnings,
  };
}

/**
 * Process multiple observations through the pipeline.
 * Applies the same configuration to all observations.
 */
export function processObservations(
  observations: RawObservation[],
  config: PipelineConfig = KENYA_DEFAULT_CONFIG
): ProcessedObservation[] {
  return observations.map(obs => processObservation(obs, config));
}

/**
 * Generate a summary report of all corrections applied.
 * Useful for the computation sheet and audit trail.
 */
export function generateCorrectionReport(
  processed: ProcessedObservation[]
): string {
  const lines: string[] = [];
  lines.push('═══════════════════════════════════════════════');
  lines.push('       CORRECTION PIPELINE AUDIT REPORT        ');
  lines.push('═══════════════════════════════════════════════');
  lines.push('');
  
  for (const obs of processed) {
    lines.push(`─ ${obs.fromStation} → ${obs.toStation} ─`);
    lines.push(`  Raw slope distance:   ${obs.rawSlopeDistance.toFixed(4)} m`);
    
    for (const log of obs.correctionLog) {
      lines.push(`  ${log.stage}:`);
      lines.push(`    Input:     ${log.input.toFixed(6)} ${log.unit}`);
      lines.push(`    Output:    ${log.output.toFixed(6)} ${log.unit}`);
      lines.push(`    Correction:${log.correction >= 0 ? '+' : ''}${log.correction.toFixed(6)} ${log.unit}`);
    }
    
    lines.push(`  Final grid distance:  ${obs.gridDistance.toFixed(4)} m`);
    
    if (obs.warnings.length > 0) {
      lines.push('  [!] WARNINGS:');
      for (const w of obs.warnings) {
        lines.push(`    - ${w}`);
      }
    }
    lines.push('');
  }
  
  return lines.join('\n');
}

/**
 * @module realTimeQC
 *
 * Real-time quality control for survey observations.
 *
 * Catches errors DURING data collection, not after. Previously, a surveyor
 * could spend an entire day in the field only to discover at the end that
 * the traverse doesn't close. This module surfaces problems as they happen.
 *
 * Features:
 *   1. Running closure monitor — shows live misclosure as each leg is added
 *   2. Redundant observation detection — flags same leg measured twice with diff values
 *   3. Setup verification — checks instrument height, target height, temp/pressure
 *   4. Outlier detection — Chauvenet's criterion for statistical outlier rejection
 *   5. Real-time precision indicator — running 1:N ratio as traverse progresses
 *
 * References:
 *   - "Elementary Surveying" by Ghilani & Wolf, 16th Ed., Chapter 3 (errors)
 *   - Chauvenet's criterion: reject if probability < 1/(2n)
 *   - RDM 1.1 (2025) — Kenya tolerance limits
 */

import type { Point2D } from '@/lib/engine/types'

// ─── 1. Running Closure Monitor ─────────────────────────────────────────────

export interface RunningClosureState {
  /** Number of legs observed so far */
  legCount: number
  /** Cumulative easting misclosure (sum of ΔE) */
  cumulativeDE: number
  /** Cumulative northing misclosure (sum of ΔN) */
  cumulativeDN: number
  /** Linear misclosure (sqrt(ΔE² + ΔN²)) */
  linearMisclosure: number
  /** Total distance traversed so far */
  totalDistance: number
  /** Running precision ratio (1:N) — 0 if no distance yet */
  precisionRatio: number | null
  /** Precision ratio as a string ("1:5000") or null */
  precisionLabel: string | null
  /** Whether the current precision meets the minimum standard */
  meetsStandard: boolean
  /** The minimum precision ratio required (based on survey class) */
  minRequired: number
  /** Warnings generated by this leg */
  warnings: string[]
}

export type SurveyClass = 'urban' | 'rural' | 'topographic' | 'control'

const PRECISION_STANDARDS: Record<SurveyClass, number> = {
  urban: 10000,      // 1:10,000
  rural: 5000,       // 1:5,000
  topographic: 1000, // 1:1,000
  control: 20000,    // 1:20,000
}

/**
 * Track the running closure of a traverse as legs are added.
 * Call addLeg() for each new observation. The state updates live.
 */
export class RunningClosureMonitor {
  private legs: Array<{ dE: number; dN: number; distance: number }> = []
  private surveyClass: SurveyClass

  constructor(surveyClass: SurveyClass = 'urban') {
    this.surveyClass = surveyClass
  }

  setSurveyClass(cls: SurveyClass) {
    this.surveyClass = cls
  }

  /**
   * Add a traverse leg (bearing + distance → ΔE, ΔN).
   * Returns the updated closure state.
   */
  addLeg(bearingDeg: number, distance: number): RunningClosureState {
    const bearingRad = (bearingDeg * Math.PI) / 180
    const dE = distance * Math.sin(bearingRad)
    const dN = distance * Math.cos(bearingRad)

    this.legs.push({ dE, dN, distance })

    return this.getState()
  }

  /**
   * Add a leg from raw coordinate differences (for GNSS observations).
   */
  addLegFromCoords(dE: number, dN: number): RunningClosureState {
    const distance = Math.sqrt(dE * dE + dN * dN)
    this.legs.push({ dE, dN, distance })
    return this.getState()
  }

  /** Remove the last leg (undo). */
  removeLastLeg(): RunningClosureState {
    this.legs.pop()
    return this.getState()
  }

  /** Clear all legs. */
  reset() {
    this.legs = []
  }

  /** Get the current closure state. */
  getState(): RunningClosureState {
    const cumulativeDE = this.legs.reduce((s, l) => s + l.dE, 0)
    const cumulativeDN = this.legs.reduce((s, l) => s + l.dN, 0)
    const linearMisclosure = Math.sqrt(cumulativeDE ** 2 + cumulativeDN ** 2)
    const totalDistance = this.legs.reduce((s, l) => s + l.distance, 0)
    const minRequired = PRECISION_STANDARDS[this.surveyClass]

    const precisionRatio = totalDistance > 0 && linearMisclosure > 0
      ? Math.round(totalDistance / linearMisclosure)
      : totalDistance > 0 ? Infinity : 0

    const meetsStandard = precisionRatio >= minRequired
    const precisionLabel = precisionRatio === Infinity
      ? '1:∞ (perfect so far)'
      : precisionRatio > 0 ? `1:${precisionRatio}` : null

    // Generate warnings
    const warnings: string[] = []
    if (this.legs.length >= 3 && !meetsStandard && precisionRatio !== Infinity) {
      warnings.push(
        `Precision ${precisionLabel} is below ${this.surveyClass} standard (1:${minRequired}). ` +
        `Current misclosure: ${linearMisclosure.toFixed(3)}m over ${totalDistance.toFixed(1)}m.`
      )
    }
    if (this.legs.length >= 2 && linearMisclosure > 0.05 && totalDistance < 500) {
      warnings.push(
        `Early misclosure of ${linearMisclosure.toFixed(3)}m detected after only ${this.legs.length} legs. ` +
        `Check the first setup for instrument/target height errors.`
      )
    }

    return {
      legCount: this.legs.length,
      cumulativeDE,
      cumulativeDN,
      linearMisclosure,
      totalDistance,
      precisionRatio: precisionRatio === Infinity ? null : precisionRatio,
      precisionLabel,
      meetsStandard,
      minRequired,
      warnings,
    }
  }
}

// ─── 2. Redundant Observation Detection ─────────────────────────────────────

export interface Observation {
  fromStation: string
  toStation: string
  bearing?: number  // decimal degrees
  distance?: number // metres
  timestamp?: string
}

export interface RedundantObservationResult {
  /** The pair of observations that disagree */
  observations: [Observation, Observation]
  /** Bearing difference in seconds of arc (if both have bearings) */
  bearingDifferenceSec: number | null
  /** Distance difference in mm (if both have distances) */
  distanceDifferenceMm: number | null
  /** Whether the difference exceeds tolerance */
  exceedsTolerance: boolean
  /** Severity: 'error' if > 2× tolerance, 'warn' if > tolerance */
  severity: 'error' | 'warn'
  /** Human-readable message */
  message: string
}

/**
 * Detect redundant observations (same leg measured twice) and check
 * if they agree within tolerance.
 *
 * @param observations All observations in the survey
 * @param bearingToleranceSec Bearing tolerance in arcseconds (default: 30")
 * @param distanceToleranceMm Distance tolerance in mm (default: 10mm)
 * @returns Array of disagreements (empty if all redundant observations agree)
 */
export function detectRedundantObservationDiscrepancies(
  observations: Observation[],
  bearingToleranceSec: number = 30,
  distanceToleranceMm: number = 10,
): RedundantObservationResult[] {
  const results: RedundantObservationResult[] = []

  // Group observations by (from, to) pair
  const groups = new Map<string, Observation[]>()

  for (const obs of observations) {
    const key = `${obs.fromStation}->${obs.toStation}`
    const reverseKey = `${obs.toStation}->${obs.fromStation}`

    // Check if we already have observations for this leg (either direction)
    if (groups.has(key)) {
      groups.get(key)!.push(obs)
    } else if (groups.has(reverseKey)) {
      groups.get(reverseKey)!.push(obs)
    } else {
      groups.set(key, [obs])
    }
  }

  // Check each group with 2+ observations
  for (const [, group] of groups) {
    if (group.length < 2) continue

    for (let i = 0; i < group.length; i++) {
      for (let j = i + 1; j < group.length; j++) {
        const obs1 = group[i]
        const obs2 = group[j]

        let bearingDiffSec: number | null = null
        let distanceDiffMm: number | null = null
        let exceeds = false
        let severity: 'error' | 'warn' = 'warn'

        // Bearing check
        if (obs1.bearing != null && obs2.bearing != null) {
          // For reverse directions, add 180°
          let b1 = obs1.bearing
          let b2 = obs2.bearing
          if (obs1.fromStation !== obs2.fromStation) {
            b2 = (b2 + 180) % 360 // reverse the second bearing
          }
          let diff = Math.abs(b1 - b2)
          if (diff > 180) diff = 360 - diff
          bearingDiffSec = diff * 3600
          if (bearingDiffSec > bearingToleranceSec) {
            exceeds = true
            severity = bearingDiffSec > bearingToleranceSec * 2 ? 'error' : 'warn'
          }
        }

        // Distance check
        if (obs1.distance != null && obs2.distance != null) {
          distanceDiffMm = Math.abs(obs1.distance - obs2.distance) * 1000
          if (distanceDiffMm > distanceToleranceMm) {
            exceeds = true
            severity = distanceDiffMm > distanceToleranceMm * 2 ? 'error' : 'warn'
          }
        }

        if (exceeds) {
          const parts: string[] = []
          if (bearingDiffSec != null) {
            parts.push(`bearing diff ${bearingDiffSec.toFixed(1)}" (tol ${bearingToleranceSec}")`)
          }
          if (distanceDiffMm != null) {
            parts.push(`distance diff ${distanceDiffMm.toFixed(1)}mm (tol ${distanceToleranceMm}mm)`)
          }

          results.push({
            observations: [obs1, obs2],
            bearingDifferenceSec: bearingDiffSec,
            distanceDifferenceMm: distanceDiffMm,
            exceedsTolerance: true,
            severity,
            message: `Redundant observation discrepancy on ${obs1.fromStation}→${obs1.toStation}: ${parts.join(', ')}`,
          })
        }
      }
    }
  }

  return results
}

// ─── 3. Setup Verification ──────────────────────────────────────────────────

export interface SetupCheck {
  field: string
  value: number | null
  expected: string
  passed: boolean
  message: string
}

/**
 * Verify a setup before taking observations.
 * Catches common field mistakes: forgotten instrument height, wrong
 * temperature/pressure units, etc.
 */
export function verifySetup(input: {
  instrumentHeight?: number
  targetHeight?: number
  temperature?: number  // Celsius
  pressure?: number     // hPa/mbar
  isControlPoint?: boolean
}): SetupCheck[] {
  const checks: SetupCheck[] = []

  // Instrument height
  checks.push({
    field: 'instrumentHeight',
    value: input.instrumentHeight ?? null,
    expected: '1.0–2.0 m',
    passed: input.instrumentHeight != null && input.instrumentHeight >= 0.5 && input.instrumentHeight <= 3.0,
    message: input.instrumentHeight == null
      ? 'Instrument height not entered — EDM correction will be wrong'
      : input.instrumentHeight < 0.5
        ? `Instrument height ${input.instrumentHeight}m is unusually low — check measurement`
        : input.instrumentHeight > 3.0
          ? `Instrument height ${input.instrumentHeight}m is unusually high — check measurement`
          : `Instrument height ${input.instrumentHeight}m is within normal range`,
  })

  // Target height
  checks.push({
    field: 'targetHeight',
    value: input.targetHeight ?? null,
    expected: '1.0–2.5 m',
    passed: input.targetHeight != null && input.targetHeight >= 0.3 && input.targetHeight <= 3.5,
    message: input.targetHeight == null
      ? 'Target/prism height not entered — EDM correction will be wrong'
      : input.targetHeight < 0.3
        ? `Target height ${input.targetHeight}m is unusually low`
        : input.targetHeight > 3.5
          ? `Target height ${input.targetHeight}m is unusually high`
          : `Target height ${input.targetHeight}m is within normal range`,
  })

  // Temperature
  if (input.temperature != null) {
    checks.push({
      field: 'temperature',
      value: input.temperature,
      expected: '10–45 °C (Kenya range)',
      passed: input.temperature >= 5 && input.temperature <= 50,
      message: input.temperature < 5
        ? `Temperature ${input.temperature}°C is below Kenya range — check unit (Fahrenheit vs Celsius?)`
        : input.temperature > 50
          ? `Temperature ${input.temperature}°C is above Kenya range — check unit`
          : `Temperature ${input.temperature}°C is normal`,
    })
  }

  // Pressure
  if (input.pressure != null) {
    checks.push({
      field: 'pressure',
      value: input.pressure,
      expected: '700–1050 hPa (sea level to 3000m)',
      passed: input.pressure >= 600 && input.pressure <= 1100,
      message: input.pressure < 600
        ? `Pressure ${input.pressure}hPa is too low — check unit (inHg vs hPa?)`
        : input.pressure > 1100
          ? `Pressure ${input.pressure}hPa is too high — check unit`
          : `Pressure ${input.pressure}hPa is normal`,
    })
  }

  // Control point check
  if (input.isControlPoint) {
    checks.push({
      field: 'isControlPoint',
      value: 1,
      expected: 'verified control point',
      passed: true,
      message: 'Set up on a control point — good practice',
    })
  }

  return checks
}

// ─── 4. Outlier Detection (Chauvenet's Criterion) ──────────────────────────

/**
 * Detect statistical outliers in a set of repeated measurements using
 * Chauvenet's criterion.
 *
 * A measurement is rejected if the probability of its deviation from
 * the mean is less than 1/(2n), where n is the number of measurements.
 *
 * @param values Array of measured values (e.g., repeated distances)
 * @returns Indices of rejected outliers, or empty array if none
 */
export function detectOutliers(values: number[]): {
  outliers: number[]
  mean: number
  stdDev: number
  details: Array<{ index: number; value: number; deviation: number; criticalValue: number; rejected: boolean }>
} {
  const n = values.length
  if (n < 3) {
    return { outliers: [], mean: 0, stdDev: 0, details: [] }
  }

  // Calculate mean
  const mean = values.reduce((s, v) => s + v, 0) / n

  // Calculate standard deviation (sample)
  const variance = values.reduce((s, v) => s + (v - mean) ** 2, 0) / (n - 1)
  const stdDev = Math.sqrt(variance)

  if (stdDev === 0) {
    return { outliers: [], mean, stdDev: 0, details: [] }
  }

  // Chauvenet's critical value: reject if |deviation| / stdDev > t_critical
  // where t_critical corresponds to probability 1 - 1/(2n)
  // For small n, use the t-distribution approximation
  // t_critical ≈ inverse_normal_cdf(1 - 1/(4n))
  const criticalProb = 1 - 1 / (4 * n)
  const tCritical = inverseNormalCdf(criticalProb)

  const details = values.map((value, index) => {
    const deviation = Math.abs(value - mean)
    const tStat = deviation / stdDev
    const rejected = tStat > tCritical
    return { index, value, deviation, criticalValue: tCritical, rejected }
  })

  const outliers = details.filter(d => d.rejected).map(d => d.index)

  return { outliers, mean, stdDev, details }
}

/**
 * Approximation of the inverse normal CDF (probit function).
 * Uses Acklam's algorithm.
 */
function inverseNormalCdf(p: number): number {
  const a = [-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02, 1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00]
  const b = [-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02, 6.680131188771972e+01, -1.328068155288572e+01]
  const c = [-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00, -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00]
  const d = [7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00, 3.754408661907416e+00]

  const pLow = 0.02425
  const pHigh = 1 - pLow

  if (p < pLow) {
    const q = Math.sqrt(-2 * Math.log(p))
    return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
           ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
  } else if (p <= pHigh) {
    const q = p - 0.5
    const r = q * q
    return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q /
           (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1)
  } else {
    const q = Math.sqrt(-2 * Math.log(1 - p))
    return -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
            ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
  }
}

// ─── 5. Real-Time Precision Indicator ───────────────────────────────────────

/**
 * Format a precision ratio for display.
 * @param ratio The 1:N ratio (e.g., 5000 for 1:5000)
 * @param surveyClass The survey class for comparison
 * @returns Formatted string with compliance status
 */
export function formatPrecisionIndicator(
  ratio: number | null,
  surveyClass: SurveyClass = 'urban',
): { label: string; compliant: boolean; color: string } {
  if (ratio === null) {
    return { label: '—', compliant: true, color: 'gray' }
  }

  const minRequired = PRECISION_STANDARDS[surveyClass]
  const compliant = ratio >= minRequired

  let color: string
  if (compliant) {
    color = 'green'
  } else if (ratio >= minRequired * 0.5) {
    color = 'amber'
  } else {
    color = 'red'
  }

  return {
    label: ratio > 0 && Number.isFinite(ratio) ? `1:${ratio.toLocaleString()}` : '—',
    compliant,
    color,
  }
}

/**
 * Residual Diagnostics — validate LSA assumptions
 *
 * PROBLEM
 * -------
 * The w-test (Baarda data snooping) assumes residuals are normally distributed
 * and uncorrelated. If either assumption is violated:
 *   - The w-test flags too many or too few blunders
 *   - The chi-square test gives false positives/negatives
 *   - The MDB (reliability) numbers are wrong
 *
 * Without diagnostic tests, you can't tell whether a "FAILED" global test
 * means real blunders or just non-normal residuals (e.g., from systematic
 * errors like an uncorrected refraction bias).
 *
 * This module implements:
 *   1. Kolmogorov-Smirnov test for normality (compares empirical CDF to
 *      theoretical normal CDF)
 *   2. Anderson-Darling test (more sensitive to tail deviations)
 *   3. Durbin-Watson test for autocorrelation (detects time-correlated
 *      residuals, common in GPS observation sequences)
 *   4. Skewness and kurtosis (3rd and 4th moments)
 *
 * REFERENCES
 * ----------
 * - Kolmogorov, A.N. (1933). "Sulla determinazione empirica di una legge di
 *   distribuzione." Giornale dell'Istituto Italiano degli Attuari, 4.
 * - Smirnov, N.V. (1948). "Table for estimating the goodness of fit of
 *   empirical distributions." Annals of Mathematical Statistics, 19.
 * - Anderson, T.W. & Darling, D.A. (1952). "Asymptotic theory of certain
 *   'goodness of fit' criteria based on stochastic processes." Annals of
 *   Mathematical Statistics, 23.
 * - Durbin, J. & Watson, G.S. (1950). "Testing for serial correlation in
 *   least squares regression, I." Biometrika, 37.
 * - Ghilani, C.D. (2017). Adjustment Computations, 6th ed. Wiley, §5.6.
 */

import { normalCDF } from '../survey/lsaStatisticalTesting'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface NormalityTestResult {
  /** Test name */
  test: 'kolmogorov-smirnov' | 'anderson-darling' | 'shapiro-wilk-approx'
  /** Test statistic */
  statistic: number
  /** Critical value at the chosen significance level */
  criticalValue: number
  /** p-value (approximation) */
  pValue: number
  /** Whether residuals pass the normality test */
  passed: boolean
  /** Significance level */
  alpha: number
  /** Sample size */
  n: number
  /** Interpretation */
  interpretation: string
}

export interface DurbinWatsonResult {
  /** Durbin-Watson statistic (0 ≤ DW ≤ 4) */
  statistic: number
  /** Lower critical value (dL) at alpha */
  dLower: number
  /** Upper critical value (dU) at alpha */
  dUpper: number
  /** Conclusion: 'no_autocorrelation' | 'positive_autocorrelation' | 'negative_autocorrelation' | 'inconclusive' */
  conclusion: 'no_autocorrelation' | 'positive_autocorrelation' | 'negative_autocorrelation' | 'inconclusive'
  /** Interpretation */
  interpretation: string
}

export interface MomentStats {
  mean: number
  standardDeviation: number
  skewness: number
  kurtosis: number      // excess kurtosis (normal = 0)
  min: number
  max: number
  n: number
}

export interface ResidualDiagnostics {
  /** Sample size */
  n: number
  /** Moment statistics */
  moments: MomentStats
  /** Kolmogorov-Smirnov normality test */
  kolmogorovSmirnov: NormalityTestResult
  /** Anderson-Darling normality test */
  andersonDarling: NormalityTestResult
  /** Durbin-Watson autocorrelation test (only if observationOrder is provided) */
  durbinWatson?: DurbinWatsonResult
  /** Overall assessment */
  passed: boolean
  /** Summary */
  summary: string
  /** Warnings */
  warnings: string[]
}

// ─── Moment Statistics ──────────────────────────────────────────────────────

/**
 * Compute mean, standard deviation, skewness, and excess kurtosis.
 *
 * Skewness: γ₁ = (1/n) Σ ((xᵢ - x̄)/s)³
 *   Normal: γ₁ = 0
 *   Positive skew = right tail heavier (e.g., from one-sided blunders)
 *
 * Excess kurtosis: γ₂ = (1/n) Σ ((xᵢ - x̄)/s)⁴ - 3
 *   Normal: γ₂ = 0
 *   Positive = heavy tails (leptokurtic, common with blunders)
 *   Negative = light tails (platykurtic, from over-weighted observations)
 */
export function computeMoments(residuals: number[]): MomentStats {
  const n = residuals.length
  if (n === 0) {
    return { mean: 0, standardDeviation: 0, skewness: 0, kurtosis: 0, min: 0, max: 0, n: 0 }
  }

  const mean = residuals.reduce((s, r) => s + r, 0) / n
  const deviations = residuals.map(r => r - mean)
  const variance = deviations.reduce((s, d) => s + d * d, 0) / n
  const sd = Math.sqrt(variance)

  if (sd === 0) {
    return { mean, standardDeviation: 0, skewness: 0, kurtosis: 0, min: mean, max: mean, n }
  }

  let sumCubed = 0, sumFourth = 0
  for (const d of deviations) {
    const normalized = d / sd
    sumCubed += normalized ** 3
    sumFourth += normalized ** 4
  }

  const skewness = sumCubed / n
  const kurtosis = sumFourth / n - 3  // excess kurtosis

  const min = Math.min(...residuals)
  const max = Math.max(...residuals)

  return { mean, standardDeviation: sd, skewness, kurtosis, min, max, n }
}

// ─── Kolmogorov-Smirnov Test ────────────────────────────────────────────────

/**
 * Kolmogorov-Smirnov test for normality.
 *
 * Compares the empirical CDF of the (standardized) residuals to the
 * theoretical standard normal CDF. The test statistic is the maximum
 * absolute difference:
 *   D = max |F_empirical(x) - F_normal(x)|
 *
 * Critical values (α = 0.05):
 *   D_crit ≈ 1.36 / √n   (large-sample approximation)
 *
 * @param residuals - Residual vector
 * @param alpha - Significance level (default 0.05)
 */
export function kolmogorovSmirnovTest(
  residuals: number[],
  alpha: number = 0.05,
): NormalityTestResult {
  const n = residuals.length
  if (n < 5) {
    return {
      test: 'kolmogorov-smirnov',
      statistic: 0,
      criticalValue: 1,
      pValue: 1,
      passed: true,
      alpha,
      n,
      interpretation: 'Sample too small (n<5) — K-S test inconclusive.',
    }
  }

  // Standardize residuals (subtract mean, divide by SD)
  const mean = residuals.reduce((s, r) => s + r, 0) / n
  const variance = residuals.reduce((s, r) => s + (r - mean) ** 2, 0) / n
  const sd = Math.sqrt(variance)
  if (sd === 0) {
    return {
      test: 'kolmogorov-smirnov',
      statistic: 0,
      criticalValue: 1.36 / Math.sqrt(n),
      pValue: 1,
      passed: true,
      alpha,
      n,
      interpretation: 'All residuals identical (zero variance) — normality trivially satisfied.',
    }
  }

  const standardized = residuals.map(r => (r - mean) / sd)
  standardized.sort((a, b) => a - b)

  // Compute K-S statistic: D = max |F_emp(x) - F_norm(x)|
  let dMax = 0
  for (let i = 0; i < n; i++) {
    // Empirical CDF at standardized[i]: (i+1)/n
    const fEmpiricalHigh = (i + 1) / n
    const fEmpiricalLow = i / n
    const fNormal = normalCDF(standardized[i])

    const diffHigh = Math.abs(fEmpiricalHigh - fNormal)
    const diffLow = Math.abs(fNormal - fEmpiricalLow)
    dMax = Math.max(dMax, diffHigh, diffLow)
  }

  // Critical value: D_crit = c(α) / √n
  // c(0.10) = 1.224, c(0.05) = 1.358, c(0.01) = 1.628
  const cAlpha = alpha === 0.10 ? 1.224 : alpha === 0.01 ? 1.628 : 1.358
  const criticalValue = cAlpha / Math.sqrt(n)

  // p-value approximation (Marsaglia, 2003 — simplified):
  // p = 2 · Σ (-1)^(k-1) · exp(-2·k²·λ²),  λ = (√n + 0.12 + 0.11/√n) · D
  const lambda = (Math.sqrt(n) + 0.12 + 0.11 / Math.sqrt(n)) * dMax
  let pValue = 0
  for (let k = 1; k <= 100; k++) {
    const term = 2 * Math.pow(-1, k - 1) * Math.exp(-2 * k * k * lambda * lambda)
    pValue += term
    if (Math.abs(term) < 1e-10) break
  }
  pValue = Math.max(0, Math.min(1, pValue))

  const passed = dMax <= criticalValue

  let interpretation: string
  if (passed) {
    interpretation = `PASS — Residuals are normally distributed at ${(1 - alpha) * 100}% confidence (D=${dMax.toFixed(4)} ≤ D_crit=${criticalValue.toFixed(4)}, p=${pValue.toFixed(3)}). The w-test and chi-square test assumptions are valid.`
  } else {
    interpretation = `FAIL — Residuals deviate from normal at ${(1 - alpha) * 100}% confidence (D=${dMax.toFixed(4)} > D_crit=${criticalValue.toFixed(4)}, p=${pValue.toFixed(3)}). The w-test may produce false positives/negatives. Investigate: systematic errors, unmodeled refraction, or heavy-tailed observations.`
  }

  return {
    test: 'kolmogorov-smirnov',
    statistic: dMax,
    criticalValue,
    pValue,
    passed,
    alpha,
    n,
    interpretation,
  }
}

// ─── Anderson-Darling Test ──────────────────────────────────────────────────

/**
 * Anderson-Darling test for normality.
 *
 * More sensitive than K-S to deviations in the tails (where blunders show up).
 *
 *   A² = -n - (1/n) Σ [(2i-1)·ln(F(xᵢ)) + (2(n-i)+1)·ln(1-F(xᵢ))]
 *
 * Critical values (α = 0.05): A²_crit = 0.787 (adjusted for estimated parameters: 0.752)
 *
 * @param residuals - Residual vector
 * @param alpha - Significance level (default 0.05)
 */
export function andersonDarlingTest(
  residuals: number[],
  alpha: number = 0.05,
): NormalityTestResult {
  const n = residuals.length
  if (n < 8) {
    return {
      test: 'anderson-darling',
      statistic: 0,
      criticalValue: 0.787,
      pValue: 1,
      passed: true,
      alpha,
      n,
      interpretation: 'Sample too small (n<8) — A-D test inconclusive.',
    }
  }

  const mean = residuals.reduce((s, r) => s + r, 0) / n
  const variance = residuals.reduce((s, r) => s + (r - mean) ** 2, 0) / n
  const sd = Math.sqrt(variance)
  if (sd === 0) {
    return {
      test: 'anderson-darling',
      statistic: 0,
      criticalValue: 0.787,
      pValue: 1,
      passed: true,
      alpha,
      n,
      interpretation: 'All residuals identical — normality trivially satisfied.',
    }
  }

  const standardized = residuals.map(r => (r - mean) / sd)
  standardized.sort((a, b) => a - b)

  let aSquared = 0
  for (let i = 0; i < n; i++) {
    const f = normalCDF(standardized[i])
    const fClamped = Math.max(1e-15, Math.min(1 - 1e-15, f))
    const oneMinusF = 1 - fClamped
    aSquared += (2 * (i + 1) - 1) * Math.log(fClamped) + (2 * (n - i - 1) + 1) * Math.log(oneMinusF)
  }
  aSquared = -n - aSquared / n

  // Adjust for estimated parameters (mean & SD estimated from data):
  // A²* = A² · (1 + 0.75/n + 2.25/n²)
  const aSquaredAdj = aSquared * (1 + 0.75 / n + 2.25 / (n * n))

  // Critical values for adjusted A² (Stephens, 1974):
  // α=0.10: 0.631, α=0.05: 0.752, α=0.025: 0.873, α=0.01: 1.035
  const criticalValue = alpha === 0.10 ? 0.631 : alpha === 0.025 ? 0.873 : alpha === 0.01 ? 1.035 : 0.752

  // p-value approximation (D'Agostino & Stephens, 1986):
  let pValue: number
  if (aSquaredAdj < 0.200) {
    pValue = 1 - Math.exp(-13.436 + 101.14 * aSquaredAdj - 223.73 * aSquaredAdj ** 2)
  } else if (aSquaredAdj < 0.340) {
    pValue = 1 - Math.exp(-8.318 + 42.796 * aSquaredAdj - 59.938 * aSquaredAdj ** 2)
  } else if (aSquaredAdj < 0.600) {
    pValue = Math.exp(0.9177 - 4.279 * aSquaredAdj - 1.38 * aSquaredAdj ** 2)
  } else {
    pValue = Math.exp(1.2937 - 5.709 * aSquaredAdj + 0.0186 * aSquaredAdj ** 2)
  }
  pValue = Math.max(0, Math.min(1, pValue))

  const passed = aSquaredAdj <= criticalValue

  let interpretation: string
  if (passed) {
    interpretation = `PASS — Anderson-Darling test passes at ${(1 - alpha) * 100}% confidence (A²=${aSquaredAdj.toFixed(4)} ≤ A²_crit=${criticalValue}, p=${pValue.toFixed(3)}). Residuals are normally distributed including in the tails.`
  } else {
    interpretation = `FAIL — Anderson-Darling test fails at ${(1 - alpha) * 100}% confidence (A²=${aSquaredAdj.toFixed(4)} > A²_crit=${criticalValue}, p=${pValue.toFixed(3)}). Residuals deviate from normal — likely heavy tails from blunders or systematic errors.`
  }

  return {
    test: 'anderson-darling',
    statistic: aSquaredAdj,
    criticalValue,
    pValue,
    passed,
    alpha,
    n,
    interpretation,
  }
}

// ─── Durbin-Watson Test ─────────────────────────────────────────────────────

/**
 * Durbin-Watson test for autocorrelation in residuals.
 *
 *   DW = Σ (eᵢ - eᵢ₋₁)² / Σ eᵢ²
 *
 * DW ≈ 2 → no autocorrelation
 * DW < 2 → positive autocorrelation (residuals correlated with neighbors)
 * DW > 2 → negative autocorrelation (alternating residuals)
 *
 * Critical values dL and dU depend on n and α. For n > 50, use the
 * approximation: dL ≈ 2 - 2·z_(1-α)·√(n/(n²-1))
 *
 * @param residuals - Residual vector in OBSERVATION ORDER (not sorted)
 * @param alpha - Significance level (default 0.05)
 */
export function durbinWatsonTest(
  residuals: number[],
  alpha: number = 0.05,
): DurbinWatsonResult {
  const n = residuals.length
  if (n < 15) {
    return {
      statistic: 2,
      dLower: 0,
      dUpper: 4,
      conclusion: 'inconclusive',
      interpretation: 'Sample too small (n<15) — Durbin-Watson test inconclusive.',
    }
  }

  // DW = Σ (eᵢ - eᵢ₋₁)² / Σ eᵢ²
  let numerator = 0
  let denominator = 0
  for (let i = 0; i < n; i++) {
    denominator += residuals[i] ** 2
    if (i > 0) {
      numerator += (residuals[i] - residuals[i - 1]) ** 2
    }
  }

  if (denominator === 0) {
    return {
      statistic: 2,
      dLower: 0,
      dUpper: 4,
      conclusion: 'inconclusive',
      interpretation: 'All residuals are zero — cannot compute DW.',
    }
  }

  const dw = numerator / denominator

  // Approximate critical values for large n (Savin & White, 1977):
  // For α=0.05, k=1 (one predictor):
  //   dL ≈ 2 - 2·1.645·√(1 + 1/(n-1))   (approximation)
  // Use the simplified formula: dL = 1.20, dU = 1.41 for n=25;
  // dL = 1.50, dU = 1.59 for n=50; dL = 1.65, dU = 1.69 for n=100
  // Linear interpolation for other n.
  const dLower = interpolateDWCritical(n, 'dL', alpha)
  const dUpper = interpolateDWCritical(n, 'dU', alpha)

  let conclusion: DurbinWatsonResult['conclusion']
  let interpretation: string

  if (dw < dLower) {
    conclusion = 'positive_autocorrelation'
    interpretation = `POSITIVE AUTOCORRELATION detected (DW=${dw.toFixed(3)} < dL=${dLower.toFixed(3)}). Residuals are correlated with their neighbors — likely from time-series observations or unmodeled systematic effects. The LSA assumption of independence is violated; standard deviations are underestimated.`
  } else if (dw > 4 - dLower) {
    conclusion = 'negative_autocorrelation'
    interpretation = `NEGATIVE AUTOCORRELATION detected (DW=${dw.toFixed(3)} > 4-dL=${(4 - dLower).toFixed(3)}). Residuals alternate in sign — possibly from over-correction or oscillating systematic errors.`
  } else if (dw >= dUpper && dw <= 4 - dUpper) {
    conclusion = 'no_autocorrelation'
    interpretation = `PASS — No autocorrelation detected (dU=${dUpper.toFixed(3)} ≤ DW=${dw.toFixed(3)} ≤ 4-dU=${(4 - dUpper).toFixed(3)}). Residuals are independent. LSA assumptions valid.`
  } else {
    conclusion = 'inconclusive'
    interpretation = `INCONCLUSIVE — DW statistic (${dw.toFixed(3)}) is in the inconclusive zone (between dL=${dLower.toFixed(3)} and dU=${dUpper.toFixed(3)} or their mirror). Increase sample size or investigate.`
  }

  return {
    statistic: dw,
    dLower,
    dUpper,
    conclusion,
    interpretation,
  }
}

// Critical value table (Savin & White, 1977) for k=1 (single regression):
// α=0.05:  n=15: dL=1.08, dU=1.36; n=20: dL=1.20, dU=1.41; n=25: dL=1.29, dU=1.45;
//          n=30: dL=1.35, dU=1.49; n=40: dL=1.44, dU=1.54; n=50: dL=1.50, dU=1.59;
//          n=75: dL=1.58, dU=1.64; n=100: dL=1.65, dU=1.69; n=200: dL=1.76, dU=1.78
function interpolateDWCritical(n: number, which: 'dL' | 'dU', alpha: number): number {
  // Use α=0.05 table (most common); for other alphas, scale proportionally
  const table = [
    { n: 15,  dL: 1.08, dU: 1.36 },
    { n: 20,  dL: 1.20, dU: 1.41 },
    { n: 25,  dL: 1.29, dU: 1.45 },
    { n: 30,  dL: 1.35, dU: 1.49 },
    { n: 40,  dL: 1.44, dU: 1.54 },
    { n: 50,  dL: 1.50, dU: 1.59 },
    { n: 75,  dL: 1.58, dU: 1.64 },
    { n: 100, dL: 1.65, dU: 1.69 },
    { n: 200, dL: 1.76, dU: 1.78 },
  ]

  // Linear interpolation in log(n) space
  let val: number
  if (n <= table[0].n) {
    val = which === 'dL' ? table[0].dL : table[0].dU
  } else if (n >= table[table.length - 1].n) {
    val = which === 'dL' ? table[table.length - 1].dL : table[table.length - 1].dU
  } else {
    for (let i = 0; i < table.length - 1; i++) {
      if (n >= table[i].n && n <= table[i + 1].n) {
        const t = (n - table[i].n) / (table[i + 1].n - table[i].n)
        const a = which === 'dL' ? table[i].dL : table[i].dU
        const b = which === 'dL' ? table[i + 1].dL : table[i + 1].dU
        val = a + t * (b - a)
        break
      }
    }
  }

  // Adjust for alpha (rough): α=0.01 widens the inconclusive zone
  const alphaAdjust = alpha === 0.01 ? 0.92 : alpha === 0.10 ? 1.05 : 1.0

  // For α=0.01, dL is lower and dU is also lower; for α=0.10, both higher
  // This is a rough scaling — for production, use exact tables
  return val! * alphaAdjust
}

// ─── Full Diagnostics ───────────────────────────────────────────────────────

/**
 * Compute full residual diagnostics for an LSA adjustment.
 *
 * @param residuals - Residual vector (in observation order for DW test)
 * @param options - Whether to include Durbin-Watson test
 */
export function computeResidualDiagnostics(
  residuals: number[],
  options: {
    includeDurbinWatson?: boolean
    alpha?: number
  } = {},
): ResidualDiagnostics {
  const alpha = options.alpha ?? 0.05
  const n = residuals.length

  const moments = computeMoments(residuals)
  const ks = kolmogorovSmirnovTest(residuals, alpha)
  const ad = andersonDarlingTest(residuals, alpha)
  const dw = options.includeDurbinWatson ? durbinWatsonTest(residuals, alpha) : undefined

  const warnings: string[] = []

  // Skewness check (z-test using SE = √(6/n))
  if (n >= 30) {
    const skewSE = Math.sqrt(6 / n)
    const skewZ = moments.skewness / skewSE
    if (Math.abs(skewZ) > 1.96) {
      warnings.push(`Skewness is significant (γ₁=${moments.skewness.toFixed(3)}, z=${skewZ.toFixed(2)}). Distribution is asymmetric — possible one-sided systematic error.`)
    }
  }

  // Kurtosis check (z-test using SE = √(24/n))
  if (n >= 30) {
    const kurtSE = Math.sqrt(24 / n)
    const kurtZ = moments.kurtosis / kurtSE
    if (Math.abs(kurtZ) > 1.96) {
      warnings.push(`Excess kurtosis is significant (γ₂=${moments.kurtosis.toFixed(3)}, z=${kurtZ.toFixed(2)}). ${moments.kurtosis > 0 ? 'Heavy tails — possible blunders.' : 'Light tails — observations may be over-weighted.'}`)
    }
  }

  if (!ks.passed) {
    warnings.push(`Kolmogorov-Smirnov test failed — residuals are not normally distributed.`)
  }
  if (!ad.passed) {
    warnings.push(`Anderson-Darling test failed — residuals deviate from normal in the tails.`)
  }
  if (dw && (dw.conclusion === 'positive_autocorrelation' || dw.conclusion === 'negative_autocorrelation')) {
    warnings.push(`Durbin-Watson test indicates ${dw.conclusion.replace('_', ' ')} — LSA independence assumption violated.`)
  }

  const passed = ks.passed && ad.passed && (!dw || dw.conclusion === 'no_autocorrelation')

  let summary: string
  if (passed) {
    summary = `Residual diagnostics PASS at ${(1 - alpha) * 100}% confidence. K-S: ${ks.statistic.toFixed(4)}/${ks.criticalValue.toFixed(4)}, A-D: ${ad.statistic.toFixed(4)}/${ad.criticalValue.toFixed(4)}${dw ? `, DW: ${dw.statistic.toFixed(3)}` : ''}. Skewness=${moments.skewness.toFixed(3)}, Kurtosis=${moments.kurtosis.toFixed(3)}. LSA assumptions are valid; the w-test and chi-square test results are trustworthy.`
  } else {
    summary = `Residual diagnostics FAIL at ${(1 - alpha) * 100}% confidence. ${warnings.length} warning(s). The LSA assumption of independent, normally-distributed residuals is violated — statistical test results (w-test, chi-square) may be unreliable.`
  }

  return {
    n,
    moments,
    kolmogorovSmirnov: ks,
    andersonDarling: ad,
    durbinWatson: dw,
    passed,
    summary,
    warnings,
  }
}

/**
 * Robust Estimation — Iteratively Reweighted Least Squares (IRLS)
 *
 * PROBLEM
 * -------
 * Standard least-squares is the BLUE (Best Linear Unbiased Estimator) when
 * residuals are Gaussian — but a single blunder can drag adjusted coordinates
 * by centimeters without being detected by the w-test. Real survey networks
 * often contain 2-5% gross errors (misread angles, swapped face, bust shots,
 * wrong target height, etc.).
 *
 * Robust estimators down-weight observations with large residuals, making
 * the adjustment RESISTANT to blunders. The adjusted coordinates converge
 * to the "clean" solution even when 10-20% of observations are contaminated.
 *
 * THREE WEIGHT FUNCTIONS IMPLEMENTED
 * ----------------------------------
 *
 * 1. HUBER (most common, good default)
 *    w(u) = 1                    if |u| ≤ c
 *    w(u) = c/|u|                if |u| > c
 *    where u = v/σ, c = 1.345 (95% efficiency under normality)
 *
 * 2. IGG3 (Institute of Geodesy and Geophysics, China — used by Chinese
 *    geodetic networks, more aggressive than Huber)
 *    w(u) = 1                       if |u| ≤ k0
 *    w(u) = (k0/|u|)·((k1 - |u|)/(k1 - k0))²  if k0 < |u| ≤ k1
 *    w(u) = 0                       if |u| > k1
 *    where k0 = 1.5, k1 = 2.5 (standard IGG3 constants)
 *
 * 3. TUKEY BIWEIGHT (most aggressive, fully rejects outliers)
 *    w(u) = (1 - (u/c)²)²          if |u| ≤ c
 *    w(u) = 0                       if |u| > c
 *    where c = 4.685 (95% efficiency under normality)
 *
 * ALGORITHM (IRLS)
 * ----------------
 * 1. Start with standard LSA (all weights = 1)
 * 2. Compute residuals v_i and standardize: u_i = v_i / (σ₀·√(q_vv_ii))
 * 3. Compute new weights w_i = f(u_i) using the chosen weight function
 * 4. Re-run LSA with new weights
 * 5. Repeat until weights converge (typically 5-15 iterations)
 *
 * The final weights identify blunders: w_i ≈ 0 means observation i is a blunder.
 *
 * REFERENCES
 * ----------
 * - Huber, P.J. (1964). "Robust Estimation of a Location Parameter."
 *   Annals of Mathematical Statistics, 35(1).
 * - Huber, P.J. (1981). Robust Statistics. Wiley.
 * - Zhou, J. (1989). "Classical theory of robustness and IGG scheme."
 *   Acta Geodaetica et Cartographica Sinica, 18(2). (IGG3 origin)
 * - Beaton, A.E. & Tukey, J.W. (1974). "The Fitting of Power Series,
 *   Meaning Polynomials, Illustrated on Band-Spectroscopic Data."
 *   Technometrics, 16(2). (Tukey biweight)
 * - Ghilani, C.D. (2017). Adjustment Computations, 6th ed. Wiley, §11.
 */

import { adjustNetworkIterative, type NetworkStation, type GenericObservation } from './lsaIterative'

// ─── Types ──────────────────────────────────────────────────────────────────

export type WeightFunction = 'huber' | 'igg3' | 'tukey'

export interface RobustLSAOptions {
  /** Weight function (default: 'huber') */
  weightFunction?: WeightFunction
  /** Tuning constant c for Huber (default: 1.345 — 95% efficiency) */
  huberC?: number
  /** IGG3 lower threshold k0 (default: 1.5) */
  igg3K0?: number
  /** IGG3 upper threshold k1 (default: 2.5) */
  igg3K1?: number
  /** Tukey biweight constant c (default: 4.685 — 95% efficiency) */
  tukeyC?: number
  /** Max IRLS iterations (default: 20) */
  maxIterations?: number
  /** Weight convergence threshold (default: 1e-4) */
  convergenceThreshold?: number
  /** Alpha for statistical tests (default: 0.05) */
  alpha?: number
}

export interface RobustLSAResult {
  /** Adjusted stations (same as standard LSA) */
  adjustedStations: Array<NetworkStation & {
    residualE: number
    residualN: number
    residualH: number
    sigmaE: number
    sigmaN: number
    sigmaH: number
    semiMajor: number
    semiMinor: number
    orientation: number
  }>
  /** Reference standard deviation σ₀ (robust) */
  sigmaZero: number
  /** Degrees of freedom */
  degreesOfFreedom: number
  /** Number of IRLS iterations */
  iterations: number
  /** Whether IRLS converged */
  converged: boolean
  /** Final weights per observation (1 = full weight, 0 = rejected) */
  finalWeights: number[]
  /** Observations flagged as blunders (weight ≈ 0) */
  blunders: Array<{
    index: number
    type: GenericObservation['type']
    from?: string
    to?: string
    component?: string
    residual: number
    standardizedResidual: number
    finalWeight: number
  }>
  /** Number of blunders detected */
  blunderCount: number
  /** Method used ('huber' | 'igg3' | 'tukey') */
  method: WeightFunction
  /** Warnings */
  warnings: string[]
  /** Summary for UI display */
  summary: string
}

// ─── Weight Functions ───────────────────────────────────────────────────────

/**
 * Compute the robust weight for a standardized residual u.
 *
 * @param u - Standardized residual (v / (σ₀·√(q_vv)))
 * @param fn - Weight function name
 * @param params - Tuning constants
 */
export function computeRobustWeight(
  u: number,
  fn: WeightFunction,
  params: { huberC?: number; igg3K0?: number; igg3K1?: number; tukeyC?: number } = {},
): number {
  const absU = Math.abs(u)

  if (fn === 'huber') {
    const c = params.huberC ?? 1.345
    return absU <= c ? 1 : c / absU
  }

  if (fn === 'igg3') {
    const k0 = params.igg3K0 ?? 1.5
    const k1 = params.igg3K1 ?? 2.5
    if (absU <= k0) return 1
    if (absU > k1) return 0
    // w = (k0/|u|) · ((k1 - |u|)/(k1 - k0))²
    return (k0 / absU) * Math.pow((k1 - absU) / (k1 - k0), 2)
  }

  if (fn === 'tukey') {
    const c = params.tukeyC ?? 4.685
    if (absU > c) return 0
    const t = 1 - (u / c) ** 2
    return t * t
  }

  return 1 // fallback
}

// ─── Robust LSA via IRLS ────────────────────────────────────────────────────

/**
 * Iteratively Reweighted Least Squares adjustment.
 *
 * This wraps the existing iterative LSA with an outer IRLS loop that
 * down-weights observations with large residuals. After convergence,
 * observations with weight ≈ 0 are flagged as blunders.
 *
 * @param stations - Network stations (with approximate coords for free, fixed for fixed)
 * @param observations - Mixed observation types
 * @param options - Robust LSA options
 */
export function adjustNetworkRobust(
  stations: NetworkStation[],
  observations: GenericObservation[],
  options: RobustLSAOptions = {},
): RobustLSAResult {
  const fn = options.weightFunction ?? 'huber'
  const maxIter = options.maxIterations ?? 20
  const threshold = options.convergenceThreshold ?? 1e-4
  const alpha = options.alpha ?? 0.05

  const warnings: string[] = []

  // Step 1: Run the standard iterative LSA to get initial residuals
  let lastResult = adjustNetworkIterative(stations, observations, {
    maxIterations: 30,
    convergenceThreshold: 1e-6,
    alpha,
    includeDiagnostics: false,
  })

  // Step 2: IRLS outer loop
  // We modify the observation stdDevs to implement the reweighting:
  // w_i_new = w_robust(u_i) × w_i_old
  // Equivalent to: σ_i_new = σ_i_old / √(w_robust(u_i))
  // (because weight = 1/σ², so w_robust × (1/σ²) = 1/(σ/√w_robust)²)

  let currentWeights = observations.map(() => 1.0)  // per-observation scalar weight multiplier
  let iteration = 0
  let converged = false
  let finalWeights: number[] = []

  // We need to track weights per observation ROW (not per scalar component).
  // For coordinate_diff observations, there are 3 rows (E, N, H) but we
  // apply the same weight to all 3 components.
  for (; iteration < maxIter; iteration++) {
    // Build new observations with adjusted stdDevs based on current weights
    const reweightedObs: GenericObservation[] = observations.map((obs, i) => {
      const w = currentWeights[i]
      const scaleFactor = w > 1e-10 ? 1 / Math.sqrt(w) : 1e6  // huge σ for zero-weight obs
      return {
        ...obs,
        stdDevE: obs.stdDevE ? obs.stdDevE * scaleFactor : undefined,
        stdDevN: obs.stdDevN ? obs.stdDevN * scaleFactor : undefined,
        stdDevH: obs.stdDevH ? obs.stdDevH * scaleFactor : undefined,
        stdDevDistance: obs.stdDevDistance ? obs.stdDevDistance * scaleFactor : undefined,
        stdDevDirection: obs.stdDevDirection ? obs.stdDevDirection * scaleFactor : undefined,
        stdDevZenith: obs.stdDevZenith ? obs.stdDevZenith * scaleFactor : undefined,
      }
    })

    // Re-run LSA with reweighted observations
    lastResult = adjustNetworkIterative(stations, reweightedObs, {
      maxIterations: 30,
      convergenceThreshold: 1e-6,
      alpha,
      includeDiagnostics: false,
    })

    // Compute new weights based on per-observation residuals
    // We re-evaluate residuals from scratch for each observation by comparing
    // the observation's measured value to the predicted value (computed from
    // the adjusted coordinates).
    const newWeights: number[] = []
    const adjustedCoords = new Map<string, { e: number; n: number; h: number }>()
    for (const s of lastResult.adjustedStations) {
      adjustedCoords.set(s.id, { e: s.easting, n: s.northing, h: s.elevation })
    }

    for (let i = 0; i < observations.length; i++) {
      const obs = observations[i]

      // Compute the residual for this observation
      let residual = 0
      let sigma = 0.005

      if (obs.type === 'coordinate_diff' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          // Use the E component residual (could also average all 3)
          const predictedE = toC.e - fromC.e
          residual = obs.deltaE! - predictedE
          sigma = obs.stdDevE ?? 0.005
        }
      } else if (obs.type === 'slope_distance' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          const dE = toC.e - fromC.e
          const dN = toC.n - fromC.n
          const dH = toC.h - fromC.h
          const predicted = Math.sqrt(dE * dE + dN * dN + dH * dH)
          residual = obs.distance! - predicted
          sigma = obs.stdDevDistance ?? 0.003
        }
      } else if (obs.type === 'horizontal_direction' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          const dE = toC.e - fromC.e
          const dN = toC.n - fromC.n
          const predicted = Math.atan2(dE, dN)
          residual = obs.direction! - predicted
          sigma = obs.stdDevDirection ?? 5e-6
        }
      } else if (obs.type === 'zenith_angle' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          const dE = toC.e - fromC.e
          const dN = toC.n - fromC.n
          const dH = toC.h - fromC.h
          const predicted = Math.atan2(Math.sqrt(dE * dE + dN * dN), dH)
          residual = obs.zenith! - predicted
          sigma = obs.stdDevZenith ?? 5e-6
        }
      } else if (obs.type === 'height_difference' && obs.from && obs.to) {
        const fromC = adjustedCoords.get(obs.from)
        const toC = adjustedCoords.get(obs.to)
        if (fromC && toC) {
          const predicted = toC.h - fromC.h
          residual = obs.deltaH! - predicted
          sigma = obs.stdDevH ?? 0.002
        }
      }

      // Standardize: u = residual / (σ₀ × σ)
      const sigmaZero = lastResult.sigmaZero > 1e-10 ? lastResult.sigmaZero : 1.0
      const u = sigma > 0 ? residual / (sigmaZero * sigma) : 0

      const newW = computeRobustWeight(u, fn, {
        huberC: options.huberC,
        igg3K0: options.igg3K0,
        igg3K1: options.igg3K1,
        tukeyC: options.tukeyC,
      })

      newWeights.push(newW)
    }

    // Check convergence: max weight change
    let maxChange = 0
    for (let i = 0; i < currentWeights.length; i++) {
      maxChange = Math.max(maxChange, Math.abs(newWeights[i] - currentWeights[i]))
    }

    currentWeights = newWeights
    finalWeights = newWeights

    if (maxChange < threshold) {
      converged = true
      break
    }
  }

  if (!converged) {
    warnings.push(`IRLS did not converge after ${maxIter} iterations (final weight change: ${threshold.toFixed(4)}). Results may be less reliable.`)
  }

  // Identify blunders (weight < 0.1, i.e., 90% down-weighted)
  const blunders: RobustLSAResult['blunders'] = []
  for (let i = 0; i < observations.length; i++) {
    if (finalWeights[i] < 0.1) {
      const obs = observations[i]
      // Find the residual for this observation (first component for coord_diff)
      const numComponents = obs.type === 'coordinate_diff' ? 3 : 1
      const startIdx = observations.slice(0, i).reduce(
        (sum, o) => sum + (o.type === 'coordinate_diff' ? 3 : 1), 0,
      )
      const residual = lastResult.residuals[startIdx] ?? 0
      const stdRes = lastResult.standardizedResiduals[startIdx] ?? 0

      blunders.push({
        index: i,
        type: obs.type,
        from: obs.from,
        to: obs.to,
        component: obs.type === 'coordinate_diff' ? 'E' : undefined,
        residual,
        standardizedResidual: stdRes,
        finalWeight: finalWeights[i],
      })
    }
  }

  if (blunders.length > 0) {
    warnings.push(`${blunders.length} blunder(s) detected and down-weighted by ${fn} IRLS.`)
  }

  // Build summary
  const summary = buildSummary(fn, iteration + (converged ? 1 : 0), converged, lastResult.sigmaZero, blunders.length, lastResult.degreesOfFreedom)

  return {
    adjustedStations: lastResult.adjustedStations,
    sigmaZero: lastResult.sigmaZero,
    degreesOfFreedom: lastResult.degreesOfFreedom,
    iterations: iteration + (converged ? 1 : 0),
    converged,
    finalWeights,
    blunders,
    blunderCount: blunders.length,
    method: fn,
    warnings,
    summary,
  }
}

function buildSummary(
  method: WeightFunction,
  iterations: number,
  converged: boolean,
  sigmaZero: number,
  blunderCount: number,
  dof: number,
): string {
  const status = converged ? 'converged' : 'did NOT converge'
  const blunderText = blunderCount === 0
    ? 'No blunders detected.'
    : `${blunderCount} blunder(s) detected and down-weighted.`

  return `Robust LSA (${method.toUpperCase()}) ${status} in ${iterations} iterations. σ₀=${sigmaZero.toFixed(4)}, dof=${dof}. ${blunderText}`
}

