/**
 * Check if a project meets the minimum requirements for an elective.
 */
export function checkElectiveRequirement(
  electiveId: string,
  projectData: { areaHa?: number; unitCount?: number; linearLengthKm?: number },
): { met: boolean; details: string } {
  switch (electiveId) {
    case 'sectional':
      const units = projectData.unitCount || 0
      return {
        met: units >= 30,
        details: `${units} units (required ≥ 30)`,
      }
    case 'perimeter':
      const area = projectData.areaHa || 0
      return {
        met: area >= 4,
        details: `${area.toFixed(2)} ha (required ≥ 4 ha, georeferenced)`,
      }
    case 'earth_observation':
      const eoArea = projectData.areaHa || 0
      return {
        met: eoArea >= 20,
        details: `${eoArea.toFixed(2)} ha (required ≥ 20 ha)`,
      }
    case 'setting_out':
      const linear = projectData.linearLengthKm || 0
      const bldgArea = projectData.areaHa || 0
      const met = linear >= 1 || bldgArea >= 0.1
      return {
        met,
        details: met
          ? `${linear >= 1 ? `${linear.toFixed(2)} km linear` : `${bldgArea.toFixed(2)} ha buildings`}`
          : `${linear.toFixed(2)} km linear / ${bldgArea.toFixed(2)} ha (required ≥ 1km OR ≥ 0.1 ha)`,
      }
    default:
      return { met: false, details: 'Unknown elective type' }
  }
}

/**
 * @module topologyChecker
 *
 * Real-time topology validation for cadastral surveying.
 *
 * Detects:
 * 1. Parcel overlap — new boundary intersects an existing parcel
 * 2. Sliver polygons — micro-gaps between adjacent plots (< 0.5m wide)
 * 3. Self-intersection — boundary crosses itself
 * 4. Road reserve encroachment — boundary intersects a road reserve buffer
 * 5. Duplicate beacons — two beacons at nearly the same coordinate
 *
 * Uses @turf/turf for geometric operations, operating on EPSG:21037
 * coordinates via the existing turfHelpers module.
 *
 * All functions are async (turf + proj4 are lazy-loaded).
 */

import {
  polygonToTurf,
  lineStringToTurf,
  toTurfCoord,
  type SurveyPoint,
} from '@/lib/map/turfHelpers'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type TopologyIssueSeverity = 'error' | 'warning' | 'info'

export interface TopologyIssue {
  id: string
  type:
    | 'overlap'
    | 'sliver'
    | 'self_intersection'
    | 'road_encroachment'
    | 'duplicate_beacon'
    | 'unclosed_polygon'
    | 'insufficient_vertices'
  severity: TopologyIssueSeverity
  message: string
  details?: string
  /** Affected coordinates (for map highlighting) */
  coordinates?: SurveyPoint[]
  /** Overlapping parcel identifier (if applicable) */
  conflictingParcelId?: string
}

export interface TopologyCheckResult {
  issues: TopologyIssue[]
  isValid: boolean
  hasErrors: boolean
  hasWarnings: boolean
}

export interface ExistingParcel {
  id: string
  name?: string
  vertices: SurveyPoint[]
}

export interface RoadReserve {
  id: string
  name?: string
  /** Centerline vertices of the road */
  centerline: SurveyPoint[]
  /** Reserve width in meters (total, both sides) */
  widthM: number
}

// ---------------------------------------------------------------------------
// Lazy turf accessor
// ---------------------------------------------------------------------------

let _turf: any = null

async function getTurf(): Promise<any> {
  if (!_turf) {
    const mod = await import('@turf/turf')
    _turf = mod
  }
  return _turf
}

// ---------------------------------------------------------------------------
// Validation Functions
// ---------------------------------------------------------------------------

/**
 * Check if a polygon boundary self-intersects.
 *
 * A self-intersection occurs when two non-adjacent edges of the polygon
 * cross each other. This produces an invalid parcel that will be rejected
 * by the registry.
 *
 * @param vertices - Parcel boundary vertices (EPSG:21037).
 * @returns Array of intersection points (empty if no self-intersection).
 */
export async function checkSelfIntersection(
  vertices: SurveyPoint[],
): Promise<SurveyPoint[]> {
  if (vertices.length < 4) return []

  const turf = await getTurf()

  // Create a linestring from the polygon boundary
  const line = await lineStringToTurf(vertices)

  // Use turf's kinks function to find self-intersections
  const kinks = turf.kinks(line)

  if (!kinks || !kinks.features || kinks.features.length === 0) {
    return []
  }

  // Convert intersection points back to EPSG:21037
  const { fromTurfCoord } = await import('@/lib/map/turfHelpers')
  const intersections: SurveyPoint[] = []
  for (const feature of kinks.features) {
    const [lon, lat] = feature.geometry.coordinates
    const pt = await fromTurfCoord([lon, lat])
    intersections.push(pt)
  }

  return intersections
}

/**
 * Check if a new parcel overlaps any existing parcels.
 *
 * @param newVertices - The new parcel boundary (EPSG:21037).
 * @param existingParcels - Array of existing parcels to check against.
 * @param toleranceSqM - Overlap area threshold in m² (default: 1 m²).
 *                       Overlaps smaller than this are ignored (survey noise).
 * @returns Array of issues, one per conflicting parcel.
 */
export async function checkParcelOverlap(
  newVertices: SurveyPoint[],
  existingParcels: ExistingParcel[],
  toleranceSqM: number = 1,
): Promise<TopologyIssue[]> {
  if (newVertices.length < 3 || existingParcels.length === 0) return []

  const turf = await getTurf()
  const newPoly = await polygonToTurf(newVertices)
  const issues: TopologyIssue[] = []

  for (const existing of existingParcels) {
    if (existing.vertices.length < 3) continue

    try {
      const existingPoly = await polygonToTurf(existing.vertices)
      const intersection = turf.intersect(newPoly, existingPoly)

      if (intersection) {
        const overlapArea = turf.area(intersection)

        if (overlapArea > toleranceSqM) {
          issues.push({
            id: `overlap-${existing.id}`,
            type: 'overlap',
            severity: 'error',
            message: `Parcel overlaps "${existing.name || existing.id}"`,
            details: `Overlap area: ${overlapArea.toFixed(2)} m² (${(overlapArea / 10000).toFixed(4)} ha). This will cause registry rejection.`,
            conflictingParcelId: existing.id,
          })
        }
      }
    } catch (err) {
      // Skip malformed parcels
      continue
    }
  }

  return issues
}

/**
 * Detect sliver polygons — micro-gaps between adjacent parcels.
 *
 * A sliver is a thin strip of unclaimed land between two parcels that
 * should share a boundary. These frequently break automated registration.
 *
 * @param newVertices - The new parcel boundary.
 * @param existingParcels - Adjacent existing parcels.
 * @param thresholdM - Maximum gap width to flag as a sliver (default: 0.5m).
 * @returns Array of sliver issues.
 */
export async function checkSliverPolygons(
  newVertices: SurveyPoint[],
  existingParcels: ExistingParcel[],
  thresholdM: number = 0.5,
): Promise<TopologyIssue[]> {
  if (newVertices.length < 3 || existingParcels.length === 0) return []

  const turf = await getTurf()
  const issues: TopologyIssue[] = []

  // Buffer the new parcel by the threshold distance
  const newPoly = await polygonToTurf(newVertices)
  const bufferedNew = turf.buffer(newPoly, thresholdM, { units: 'meters' })

  for (const existing of existingParcels) {
    if (existing.vertices.length < 3) continue

    try {
      const existingPoly = await polygonToTurf(existing.vertices)

      // Check if the buffered new parcel overlaps the existing parcel
      // but the original doesn't (this indicates a gap < thresholdM)
      const bufferedIntersection = turf.intersect(bufferedNew, existingPoly)
      const directIntersection = turf.intersect(newPoly, existingPoly)

      if (bufferedIntersection && !directIntersection) {
        // There's a gap between the parcels that's smaller than thresholdM
        const gapArea = turf.area(bufferedIntersection)

        if (gapArea > 0.01 && gapArea < thresholdM * 100) {
          issues.push({
            id: `sliver-${existing.id}`,
            type: 'sliver',
            severity: 'warning',
            message: `Sliver gap detected with "${existing.name || existing.id}"`,
            details: `Gap width < ${thresholdM}m. This micro-gap will cause registration issues. Snap boundaries to eliminate the gap.`,
            conflictingParcelId: existing.id,
          })
        }
      }
    } catch (err) {
      continue
    }
  }

  return issues
}

/**
 * Check if a parcel boundary encroaches on a road reserve.
 *
 * Road reserves in Kenya are typically 15m wide (7.5m each side from
 * centerline) for rural roads, and 30m for highways.
 *
 * @param newVertices - The new parcel boundary.
 * @param roadReserves - Array of road reserves to check.
 * @returns Array of encroachment issues.
 */
export async function checkRoadReserveEncroachment(
  newVertices: SurveyPoint[],
  roadReserves: RoadReserve[],
): Promise<TopologyIssue[]> {
  if (newVertices.length < 3 || roadReserves.length === 0) return []

  const turf = await getTurf()
  const issues: TopologyIssue[] = []
  const newPoly = await polygonToTurf(newVertices)

  for (const road of roadReserves) {
    if (road.centerline.length < 2) continue

    try {
      // Create the road reserve polygon by buffering the centerline
      const centerline = await lineStringToTurf(road.centerline)
      const halfWidth = road.widthM / 2
      const reservePoly = turf.buffer(centerline, halfWidth, { units: 'meters' })

      if (!reservePoly) continue

      // Check intersection
      const intersection = turf.intersect(newPoly, reservePoly)

      if (intersection) {
        const encroachmentArea = turf.area(intersection)

        if (encroachmentArea > 0.5) {
          issues.push({
            id: `road-${road.id}`,
            type: 'road_encroachment',
            severity: 'error',
            message: `Encroaches on road reserve "${road.name || road.id}"`,
            details: `Encroachment area: ${encroachmentArea.toFixed(2)} m². Road reserve width: ${road.widthM}m. This is illegal under the Roads Act.`,
            conflictingParcelId: road.id,
          })
        }
      }
    } catch (err) {
      continue
    }
  }

  return issues
}

/**
 * Detect duplicate beacons — two beacons at nearly the same coordinate.
 *
 * Duplicate beacons cause confusion in the registry and may indicate
 * a data entry error or a beacon that was re-established without
 * cancelling the old one.
 *
 * @param beacons - Array of beacon coordinates.
 * @param thresholdM - Maximum distance to consider beacons duplicates (default: 0.1m).
 * @returns Array of duplicate beacon issues.
 */
export async function checkDuplicateBeacons(
  beacons: SurveyPoint[],
  thresholdM: number = 0.1,
): Promise<TopologyIssue[]> {
  if (beacons.length < 2) return []

  const issues: TopologyIssue[] = []
  const thresholdSq = thresholdM * thresholdM

  for (let i = 0; i < beacons.length; i++) {
    for (let j = i + 1; j < beacons.length; j++) {
      const dE = beacons[i].easting - beacons[j].easting
      const dN = beacons[i].northing - beacons[j].northing
      const distSq = dE * dE + dN * dN

      if (distSq < thresholdSq) {
        const dist = Math.sqrt(distSq)
        issues.push({
          id: `dup-beacon-${i}-${j}`,
          type: 'duplicate_beacon',
          severity: 'warning',
          message: `Duplicate beacons detected`,
          details: `Beacons ${i + 1} and ${j + 1} are ${dist.toFixed(3)}m apart. Threshold: ${thresholdM}m. Verify if these are the same physical beacon.`,
          coordinates: [beacons[i], beacons[j]],
        })
      }
    }
  }

  return issues
}

/**
 * Run a comprehensive topology check on a new parcel.
 *
 * This is the main entry point for real-time validation.
 * It runs all checks and returns a combined result.
 *
 * @param params - Check parameters.
 * @returns Combined topology check result.
 */
export async function runTopologyCheck(params: {
  newVertices: SurveyPoint[]
  existingParcels?: ExistingParcel[]
  roadReserves?: RoadReserve[]
  beacons?: SurveyPoint[]
  sliverThresholdM?: number
  overlapToleranceSqM?: number
  duplicateBeaconThresholdM?: number
}): Promise<TopologyCheckResult> {
  const {
    newVertices,
    existingParcels = [],
    roadReserves = [],
    beacons = [],
    sliverThresholdM = 0.5,
    overlapToleranceSqM = 1,
    duplicateBeaconThresholdM = 0.1,
  } = params

  const issues: TopologyIssue[] = []

  // 1. Check minimum vertices
  if (newVertices.length < 3) {
    issues.push({
      id: 'insufficient-vertices',
      type: 'insufficient_vertices',
      severity: 'error',
      message: 'Insufficient vertices',
      details: 'A parcel requires at least 3 vertices to form a valid polygon.',
    })
    return { issues, isValid: false, hasErrors: true, hasWarnings: false }
  }

  // 2. Check if polygon is closed
  if (newVertices.length >= 3) {
    const first = newVertices[0]
    const last = newVertices[newVertices.length - 1]
    const distSq = (first.easting - last.easting) ** 2 + (first.northing - last.northing) ** 2
    if (distSq > 0.01) {
      issues.push({
        id: 'unclosed-polygon',
        type: 'unclosed_polygon',
        severity: 'warning',
        message: 'Polygon is not closed',
        details: 'The first and last vertices differ. The polygon will be auto-closed for computation.',
      })
    }
  }

  // 3. Self-intersection check
  const selfIntersections = await checkSelfIntersection(newVertices)
  if (selfIntersections.length > 0) {
    issues.push({
      id: 'self-intersection',
      type: 'self_intersection',
      severity: 'error',
      message: 'Boundary self-intersects',
      details: `${selfIntersections.length} self-intersection point(s) detected. The boundary crosses itself, producing an invalid parcel.`,
      coordinates: selfIntersections,
    })
  }

  // 4. Overlap check
  const overlapIssues = await checkParcelOverlap(newVertices, existingParcels, overlapToleranceSqM)
  issues.push(...overlapIssues)

  // 5. Sliver check
  const sliverIssues = await checkSliverPolygons(newVertices, existingParcels, sliverThresholdM)
  issues.push(...sliverIssues)

  // 6. Road reserve check
  const roadIssues = await checkRoadReserveEncroachment(newVertices, roadReserves)
  issues.push(...roadIssues)

  // 7. Duplicate beacon check
  if (beacons.length >= 2) {
    const dupIssues = await checkDuplicateBeacons(beacons, duplicateBeaconThresholdM)
    issues.push(...dupIssues)
  }

  const hasErrors = issues.some(i => i.severity === 'error')
  const hasWarnings = issues.some(i => i.severity === 'warning')
  const isValid = !hasErrors

  return { issues, isValid, hasErrors, hasWarnings }
}

/**
 * Total Least Squares (TLS) — errors-in-variables adjustment
 *
 * PROBLEM
 * -------
 * Standard least-squares assumes the design matrix A is known exactly and
 * only the observation vector l has errors:
 *   l = A·x + ε,  E[ε] = 0
 *
 * In reality, both A and l have errors. When you tie a new survey into
 * 1960s-era Cassini control points that were converted to UTM (accumulating
 * transformation errors), standard LSA pretends the control is perfect —
 * but it isn't. The control point coordinates themselves have uncertainties
 * of 0.1-1m.
 *
 * TLS accounts for errors in BOTH A and l. The model is:
 *   (A + ΔA)·x = l + Δl
 *
 * where ΔA and Δl are the corrections to A and l, and we minimize ||[ΔA | Δl]||_F
 * (Frobenius norm of the combined correction matrix).
 *
 * SOLUTION: SVD-based TLS
 * -----------------------
 * The TLS solution is obtained via the SVD of the augmented matrix [A | l]:
 *   [A | l] = U·Σ·V^T
 *
 * If the smallest singular value corresponds to the last column of V, then:
 *   x_TLS = -V(1:n, n+1) / V(n+1, n+1)
 *
 * This requires the "Van Huffel" algorithm for the general case where A
 * has more than one column. For geodetic networks with hundreds of unknowns,
 * we use the iterative TLS algorithm of Schaffrin (2006) instead.
 *
 * APPLICATION IN GEODESY
 * ----------------------
 * For coordinate transformations with uncertain control, TLS gives:
 *   - More accurate transformation parameters
 *   - Honest standard deviations that reflect control uncertainty
 *   - Better residuals (that don't favor the "fixed" control points)
 *
 * For LSA networks with uncertain control, TLS treats fixed stations as
 * "noisy observations" rather than perfect constraints — propagating their
 * uncertainty into the adjusted coordinates.
 *
 * REFERENCES
 * ----------
 * - Golub, G.H. & Van Loan, C.F. (1980). "An Analysis of the Total Least
 *   Squares Problem." SIAM J. Numer. Anal., 17(6).
 * - Van Huffel, S. & Vandewalle, J. (1991). The Total Least Squares
 *   Problem: Computational Aspects and Analysis. SIAM.
 * - Schaffrin, B. (2006). "A note on Computing the TLS Solution in the
 *   Presence of Linear Constraints." Geodetic Theory and Applications.
 * - Schaffrin, B. & Wieser, A. (2008). "On Weighted Total Least-Squares
 *   Adjustment for Linear Regression." Journal of Geodesy, 82(7).
 * - Krystek, M. & Anton, M. (2007). "A weighted total least-squares
 *   algorithm for fitting a straight line." Meas. Sci. Technol., 18.
 */

// ─── Types ──────────────────────────────────────────────────────────────────

export interface TLSInput {
  /** Design matrix A (m × n) — may contain errors */
  A: number[][]
  /** Observation vector l (m × 1) — contains errors */
  l: number[]
  /** Optional: variance-covariance matrix of A's errors (m·n × m·n) — for WTLS */
  /** If not provided, assume A's errors are i.i.d. with unit variance */
  A_variances?: number[]  // per-element variance of A (length = m·n, row-major)
  /** Optional: weights for observations l (m × 1) */
  l_weights?: number[]  // per-row weight of l (length = m)
}

export interface TLSResult {
  /** Adjusted parameter vector x (n × 1) */
  x: number[]
  /** Corrections to A (ΔA, m × n) */
  deltaA: number[][]
  /** Corrections to l (Δl, m × 1) */
  deltal: number[]
  /** Adjusted design matrix A + ΔA */
  A_adjusted: number[][]
  /** Adjusted observation vector l + Δl */
  l_adjusted: number[]
  /** Residuals (l - A·x, the standard LS residuals for comparison) */
  residuals: number[]
  /** Reference standard deviation σ₀ */
  sigmaZero: number
  /** Variance-covariance matrix of x (n × n) */
  Qxx: number[][]
  /** Degrees of freedom (m - n) */
  degreesOfFreedom: number
  /** Method used ('standard_tls' for SVD, 'iterative_wtls' for Schaffrin) */
  method: string
  /** Number of iterations (for iterative methods) */
  iterations: number
  /** Warnings */
  warnings: string[]
}

// ─── Standard TLS via SVD ───────────────────────────────────────────────────

/**
 * Compute the Total Least Squares solution using SVD.
 *
 * This is the classic Golub-Van Loan (1980) algorithm. Suitable for small
 * problems (n < 100). For larger problems, use the iterative WTLS.
 *
 * Algorithm:
 *   1. Form augmented matrix [A | l] (m × (n+1))
 *   2. Compute SVD: [A | l] = U·Σ·V^T
 *   3. Partition V: V = [V11 V12; V21 V22] where V22 is scalar (last column)
 *   4. x_TLS = -V12 / V22 = -V(1:n, n+1) / V(n+1, n+1)
 *   5. ΔA = -A·x·x^T / (1 + x^T·x)  (correction to A)
 *   6. Δl = -l·x^T·x / (1 + x^T·x)  (correction to l) — actually Δl = -l_normalized
 *
 * @param input - TLS input (A, l, optional variances)
 */
export function computeStandardTLS(input: TLSInput): TLSResult {
  const { A, l } = input
  const m = A.length
  const n = A[0].length

  const warnings: string[] = []

  if (m < n + 1) {
    warnings.push(`Insufficient observations for TLS: m=${m} < n+1=${n + 1}. Solution may be unstable.`)
  }

  // Step 1: Form augmented matrix [A | l] (m × (n+1))
  const augmented: number[][] = A.map((row, i) => [...row, l[i]])

  // Step 2: Compute SVD using Jacobi eigendecomposition of [A|l]^T · [A|l]
  // For small problems this is more numerically stable than full SVD.
  // [A|l]^T · [A|l] is (n+1) × (n+1), small enough for Jacobi.
  const AtA = matMul(transpose(augmented), augmented)  // (n+1) × (n+1)

  // Jacobi eigenvalue decomposition
  const { eigenvalues, eigenvectors } = jacobiEigen(AtA)

  // Find the smallest eigenvalue's eigenvector
  let minIdx = 0
  for (let i = 1; i < eigenvalues.length; i++) {
    if (eigenvalues[i] < eigenvalues[minIdx]) minIdx = i
  }

  // The eigenvector corresponding to the smallest eigenvalue is the TLS solution
  // (up to a scale factor). The TLS solution is:
  //   x_TLS = -v(1:n) / v(n+1)  where v is the eigenvector
  const v = eigenvectors.map(row => row[minIdx])
  const vN1 = v[n]  // last element (V22)

  if (Math.abs(vN1) < 1e-15) {
    warnings.push('TLS solution is degenerate (V22 ≈ 0). The system may not have a unique TLS solution. Falling back to standard LS.')
    // Fall back to standard LS
    return computeStandardLSFallback(A, l, warnings)
  }

  const x = v.slice(0, n).map(vi => -vi / vN1)

  // Step 5-6: Compute corrections
  // ΔA and Δl are computed from the TLS error model:
  //   [ΔA | Δl] = -[A | l] · x · x^T / (1 + x^T·x)  ... actually simpler:
  //   [ΔA | Δl] = -[A | l] · v · v^T  (since v is unit-length)
  // But the standard formula is:
  //   ΔA = -A·x·x^T / (1 + x^T·x)
  //   Δl = -l·x^T / (1 + x^T·x)  ... no, this is wrong dimensionally.
  //
  // The correct formulas (Golub-Van Loan, 1980, eq. 4.6-4.7):
  //   The TLS correction is: ΔA = -d·v^T where d = (l - A·x)·v_last / v_last_last
  // But for simplicity, let's use the projection approach:
  //   The corrected system [A+ΔA | l+Δl] has rank n, with [A+ΔA]·x = l+Δl.
  //   The "minimum-norm" correction projects [A|l] onto the closest rank-n matrix.
  const xNorm2 = x.reduce((s, xi) => s + xi * xi, 0)
  const scale = 1 / (1 + xNorm2)

  // Compute predictions A·x
  const Ax = A.map(row => row.reduce((s, a, j) => s + a * x[j], 0))
  // Residuals l - A·x (standard LS residuals)
  const residuals = l.map((li, i) => li - Ax[i])

  // TLS corrections: Δl = l + Δl - l = (A+ΔA)·x - l... use projection formula
  // For each row i: [ΔA_row | Δl_row] = -r_i · v^T  where r_i = (l_i - A_i·x) / (1 + x^T·x)
  // Wait, simpler: the TLS correction to row i is:
  //   [ΔA_i | Δl_i] = -((l_i - A_i·x) / (1 + x^T·x)) · [x^T | 1]
  // (This makes [A_i + ΔA_i | l_i + Δl_i] · [x; -1] = 0, which is the rank-n condition.)

  const deltaA: number[][] = []
  const deltal: number[] = []
  const A_adjusted: number[][] = []
  const l_adjusted: number[] = []

  for (let i = 0; i < m; i++) {
    const r_i = (l[i] - Ax[i]) * scale
    const dA_i = x.map(xj => -r_i * xj)
    const dl_i = -r_i  // the last component v(n+1) = 1 in the normalized form

    deltaA.push(dA_i)
    deltal.push(dl_i)
    A_adjusted.push(A[i].map((a, j) => a + dA_i[j]))
    l_adjusted.push(l[i] + dl_i)
  }

  // Compute σ₀ and Qxx
  // For TLS, the σ₀ computation is different from LS. We use the standard
  // approximation: σ₀² ≈ ||l - A·x||² / (m - n)  (same as LS, approximately)
  const dof = m - n
  const vWv = residuals.reduce((s, r) => s + r * r, 0)
  const sigmaZero = dof > 0 ? Math.sqrt(vWv / dof) : 0

  // Qxx for TLS is also different. The Schaffrin-Wieser (2008) formula:
  //   Qxx_TLS ≈ (1 + x^T·x) · (A^T·A)^(-1)  (approximation)
  const AtA_n = matMul(transpose(A), A)
  const Qxx = invertMatrix(AtA_n, n).map((row, i) =>
    row.map(v => v * (1 + xNorm2)),
  )

  return {
    x,
    deltaA,
    deltal,
    A_adjusted,
    l_adjusted,
    residuals,
    sigmaZero,
    Qxx,
    degreesOfFreedom: dof,
    method: 'standard_tls',
    iterations: 0,
    warnings,
  }
}

// ─── Weighted TLS (Schaffrin-Wieser iterative) ──────────────────────────────

/**
 * Compute the Weighted Total Least Squares solution using the
 * Schaffrin-Wieser (2008) iterative algorithm.
 *
 * This handles the case where:
 *   - Different rows of A have different variances (heteroscedastic)
 *   - Different columns of A have different variances
 *
 * Algorithm (simplified for diagonal weight matrices):
 *   1. Start with standard LS solution: x_0 = (A^T·P·A)^(-1)·A^T·P·l
 *   2. Iterate:
 *      a. Compute residuals: v = l - A·x
 *      b. Compute weight scaling: λ = v^T·P·v / (m - n)
 *      c. Update A's row weights: P_A_i = P_l_i / (1 + x^T·x / λ)
 *      d. Solve WTLS: x = (A^T·P_eff·A)^(-1)·A^T·P_eff·l
 *      e. Repeat until ||x_new - x_old|| < threshold
 *
 * @param input - TLS input with weights
 * @param options - Iteration options
 */
export function computeWeightedTLS(
  input: TLSInput,
  options: { maxIterations?: number; convergenceThreshold?: number } = {},
): TLSResult {
  const { A, l, l_weights } = input
  const m = A.length
  const n = A[0].length
  const maxIter = options.maxIterations ?? 50
  const threshold = options.convergenceThreshold ?? 1e-10

  const warnings: string[] = []

  // Initial weights (default to unit weight)
  const P = l_weights ?? new Array(m).fill(1.0)

  // Step 1: Initial standard LS solution
  // x_0 = (A^T·P·A)^(-1)·A^T·P·l
  const AtPA = matMul(matMul(transpose(A), diag(P)), A)
  const AtPl = matVec(matMul(transpose(A), diag(P)), l)
  const x_initial = solveLinearSystem(AtPA, AtPl, n)

  if (!x_initial) {
    warnings.push('Initial LS solve failed — singular matrix. Try with different data.')
    return computeStandardTLS(input)
  }

  let x: number[] = x_initial

  let iteration = 0
  let converged = false
  let prevX = [...x]

  for (; iteration < maxIter; iteration++) {
    // Compute residuals v = l - A·x
    const Ax = A.map(row => row.reduce((s, a, j) => s + a * x[j], 0))
    const v = l.map((li, i) => li - Ax[i])

    // Compute λ = v^T·P·v / (m - n)
    const vPv = v.reduce((s, vi, i) => s + P[i] * vi * vi, 0)
    const dof = m - n
    const lambda = dof > 0 ? vPv / dof : 1

    if (lambda < 1e-15) {
      converged = true
      break
    }

    // Update effective weights: P_eff_i = P_i / (1 + x^T·x / λ)
    // This accounts for the uncertainty in A being proportional to x
    const xNorm2 = x.reduce((s, xi) => s + xi * xi, 0)
    const Peff = P.map(pi => pi / (1 + xNorm2 / lambda))

    // Solve WTLS: x = (A^T·P_eff·A)^(-1)·A^T·P_eff·l
    const AtPeA = matMul(matMul(transpose(A), diag(Peff)), A)
    const AtPel = matVec(matMul(transpose(A), diag(Peff)), l)
    const newX = solveLinearSystem(AtPeA, AtPel, n)

    if (!newX) {
      warnings.push(`Iteration ${iteration + 1}: singular matrix. Stopping.`)
      break
    }

    // Convergence check
    const correction = Math.sqrt(newX.reduce((s, xi, i) => s + (xi - prevX[i]) ** 2, 0))
    prevX = [...newX]
    x = newX

    if (correction < threshold) {
      converged = true
      break
    }
  }

  if (!converged) {
    warnings.push(`WTLS did not converge after ${maxIter} iterations.`)
  }

  // Compute final residuals and corrections
  const Ax = A.map(row => row.reduce((s, a, j) => s + a * x[j], 0))
  const residuals = l.map((li, i) => li - Ax[i])

  const vPv = residuals.reduce((s, vi, i) => s + P[i] * vi * vi, 0)
  const dof = m - n
  const sigmaZero = dof > 0 ? Math.sqrt(vPv / dof) : 0

  // Compute corrections
  const xNorm2 = x.reduce((s, xi) => s + xi * xi, 0)
  const scale = 1 / (1 + xNorm2)
  const deltaA: number[][] = []
  const deltal: number[] = []
  const A_adjusted: number[][] = []
  const l_adjusted: number[] = []

  for (let i = 0; i < m; i++) {
    const r_i = (l[i] - Ax[i]) * scale
    const dA_i = x.map(xj => -r_i * xj)
    const dl_i = -r_i
    deltaA.push(dA_i)
    deltal.push(dl_i)
    A_adjusted.push(A[i].map((a, j) => a + dA_i[j]))
    l_adjusted.push(l[i] + dl_i)
  }

  // Qxx
  const AtPA_final = matMul(matMul(transpose(A), diag(P)), A)
  const Qxx = invertMatrix(AtPA_final, n)

  return {
    x,
    deltaA,
    deltal,
    A_adjusted,
    l_adjusted,
    residuals,
    sigmaZero,
    Qxx,
    degreesOfFreedom: dof,
    method: 'iterative_wtls',
    iterations: iteration + (converged ? 1 : 0),
    warnings,
  }
}

// ─── Standard LS Fallback ───────────────────────────────────────────────────

function computeStandardLSFallback(A: number[][], l: number[], warnings: string[]): TLSResult {
  const m = A.length
  const n = A[0].length

  const AtA = matMul(transpose(A), A)
  const Atl = matVec(transpose(A), l)
  const x = solveLinearSystem(AtA, Atl, n) || new Array(n).fill(0)

  const Ax = A.map(row => row.reduce((s, a, j) => s + a * x[j], 0))
  const residuals = l.map((li, i) => li - Ax[i])

  const dof = m - n
  const vWv = residuals.reduce((s, r) => s + r * r, 0)
  const sigmaZero = dof > 0 ? Math.sqrt(vWv / dof) : 0

  const Qxx = invertMatrix(AtA, n)

  return {
    x,
    deltaA: A.map(() => new Array(n).fill(0)),
    deltal: new Array(m).fill(0),
    A_adjusted: A,
    l_adjusted: l,
    residuals,
    sigmaZero,
    Qxx,
    degreesOfFreedom: dof,
    method: 'standard_ls_fallback',
    iterations: 0,
    warnings,
  }
}

// ─── Matrix Helpers ─────────────────────────────────────────────────────────

function transpose(A: number[][]): number[][] {
  const rows = A.length
  const cols = A[0].length
  const result: number[][] = Array(cols).fill(null).map(() => Array(rows).fill(0))
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      result[j][i] = A[i][j]
    }
  }
  return result
}

function matMul(A: number[][], B: number[][]): number[][] {
  const rows = A.length
  const cols = B[0].length
  const inner = B.length
  const result: number[][] = Array(rows).fill(null).map(() => Array(cols).fill(0))
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      let sum = 0
      for (let k = 0; k < inner; k++) {
        sum += A[i][k] * B[k][j]
      }
      result[i][j] = sum
    }
  }
  return result
}

function matVec(A: number[][], v: number[]): number[] {
  return A.map(row => row.reduce((s, a, i) => s + a * v[i], 0))
}

function diag(v: number[]): number[][] {
  const n = v.length
  return Array(n).fill(null).map((_, i) =>
    Array(n).fill(null).map((_, j) => (i === j ? v[i] : 0)),
  )
}

function solveLinearSystem(A: number[][], b: number[], n: number): number[] | null {
  const M = A.map((row, i) => [...row, b[i]])
  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++) {
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    }
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]

    if (Math.abs(M[col][col]) < 1e-15) return null

    for (let row = col + 1; row < n; row++) {
      const factor = M[row][col] / M[col][col]
      for (let k = col; k <= n; k++) M[row][k] -= factor * M[col][k]
    }
  }

  const x = new Array(n).fill(0)
  for (let i = n - 1; i >= 0; i--) {
    x[i] = M[i][n]
    for (let j = i + 1; j < n; j++) x[i] -= M[i][j] * x[j]
    x[i] /= M[i][i]
  }
  return x
}

function invertMatrix(A: number[][], n: number): number[][] {
  if (A.length === 0) return Array.from({ length: n }, () => new Array(n).fill(0))
  const M = A.map((row, i) => {
    const aug = [...row, ...new Array(n).fill(0)]
    aug[n + i] = 1
    return aug
  })

  for (let col = 0; col < n; col++) {
    let maxRow = col
    for (let row = col + 1; row < n; row++) {
      if (Math.abs(M[row][col]) > Math.abs(M[maxRow][col])) maxRow = row
    }
    ;[M[col], M[maxRow]] = [M[maxRow], M[col]]

    const pivot = M[col][col]
    if (Math.abs(pivot) < 1e-15) return Array.from({ length: n }, () => new Array(n).fill(0))

    for (let k = 0; k < 2 * n; k++) M[col][k] /= pivot
    for (let row = 0; row < n; row++) {
      if (row === col) continue
      const factor = M[row][col]
      for (let k = 0; k < 2 * n; k++) M[row][k] -= factor * M[col][k]
    }
  }

  return M.map(row => row.slice(n))
}

/**
 * Jacobi eigenvalue algorithm for symmetric matrices.
 *
 * Returns eigenvalues and eigenvectors of a symmetric n×n matrix.
 * Used by TLS to compute the SVD of [A|l] via eigendecomposition of [A|l]^T·[A|l].
 *
 * Algorithm: classic Jacobi rotations (Press et al., Numerical Recipes, §11.1).
 * Converges in ~5-10 sweeps for typical matrices.
 */
function jacobiEigen(A_in: number[][]): { eigenvalues: number[]; eigenvectors: number[][] } {
  const n = A_in.length
  // Copy A (work on a copy)
  const A = A_in.map(row => [...row])
  // V starts as identity
  const V: number[][] = Array(n).fill(null).map((_, i) =>
    Array(n).fill(null).map((_, j) => (i === j ? 1 : 0) as number),
  )

  const maxSweeps = 100
  for (let sweep = 0; sweep < maxSweeps; sweep++) {
    // Compute off-diagonal sum of squares
    let offDiag = 0
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        offDiag += A[i][j] * A[i][j]
      }
    }
    if (offDiag < 1e-20) break  // converged

    for (let p = 0; p < n - 1; p++) {
      for (let q = p + 1; q < n; q++) {
        if (Math.abs(A[p][q]) < 1e-20) continue

        // Compute rotation angle
        const theta = (A[q][q] - A[p][p]) / (2 * A[p][q])
        let t: number
        if (Math.abs(theta) > 1e10) {
          t = 1 / (2 * theta)
        } else {
          t = Math.sign(theta) / (Math.abs(theta) + Math.sqrt(theta * theta + 1))
        }
        const c: number = 1 / Math.sqrt(t * t + 1)
        const s: number = t * c

        // Apply rotation
        const app = A[p][p]
        const aqq = A[q][q]
        const apq = A[p][q]

        A[p][p] = c * c * app - 2 * s * c * apq + s * s * aqq
        A[q][q] = s * s * app + 2 * s * c * apq + c * c * aqq
        A[p][q] = 0
        A[q][p] = 0

        for (let i = 0; i < n; i++) {
          if (i !== p && i !== q) {
            const aip = A[i][p]
            const aiq = A[i][q]
            A[i][p] = c * aip - s * aiq
            A[p][i] = A[i][p]
            A[i][q] = s * aip + c * aiq
            A[q][i] = A[i][q]
          }
          // Update eigenvector matrix
          const vip = V[i][p]
          const viq = V[i][q]
          V[i][p] = c * vip - s * viq
          V[i][q] = s * vip + c * viq
        }
      }
    }
  }

  // Eigenvalues are on the diagonal of A
  const eigenvalues = A.map((row, i) => row[i])

  return { eigenvalues, eigenvectors: V }
}

/**
 * Traverse Computation Engine
 * 
 * Computes adjusted coordinates for a traverse (open or closed)
 * using either the Bowditch/Compass rule or Least Squares adjustment.
 * 
 * For 3rd/4th order: Bowditch adjustment (proportional distribution)
 * For 1st/2nd order: Least Squares adjustment (statistically optimal)
 * 
 * References:
 * - Schofield, W. (2001) "Engineering Surveying"
 * - Anderson & Mikhail (1998) "Surveying: Theory and Practice"
 */

// ─── Types ───────────────────────────────────────────────────────

export interface TraverseStation {
  name: string;
  easting?: number;    // Known for control points
  northing?: number;   // Known for control points
  isFixed: boolean;    // Control/fixed point
}

export interface TraverseLeg {
  fromStation: string;
  toStation: string;
  bearing: number;       // Decimal degrees (0-360)
  distance: number;      // Meters (already corrected through pipeline)
  stdDevBearing?: number; // Standard deviation of bearing (seconds)
  stdDevDistance?: number; // Standard deviation of distance (meters)
}

export interface TraverseResult {
  stations: AdjustedStation[];
  misclosure: {
    easting: number;       // meters
    northing: number;      // meters
    linear: number;        // meters (total linear misclosure)
    angular: number;       // seconds (angular misclosure)
    ratio: string;         // e.g., "1:25000"
    ratioValue: number;    // numeric ratio denominator
  };
  adjustmentMethod: 'bowditch' | 'least_squares';
  order: number;           // 1st, 2nd, 3rd, 4th
  passesOrder: boolean;    // Whether misclosure meets the order requirement
  totalDistance: number;   // meters
  warnings: string[];
}

export interface AdjustedStation {
  name: string;
  easting: number;
  northing: number;
  correctionE: number;     // Correction applied (meters)
  correctionN: number;     // Correction applied (meters)
  isFixed: boolean;
  stdDevE?: number;        // From least squares
  stdDevN?: number;        // From least squares
}

// ─── Accuracy Order Requirements ─────────────────────────────────

/** Minimum misclosure ratio for each survey order */
export const ORDER_REQUIREMENTS: Record<number, number> = {
  1: 100000,   // 1st order: 1:100,000
  2: 20000,    // 2nd order: 1:20,000
  3: 10000,    // 3rd order: 1:10,000 (Kenya cadastral minimum)
  4: 5000,     // 4th order: 1:5,000 (topographic)
};

/** Default standard deviations for each order */
export const ORDER_STDS: Record<number, { angle: number; distPPM: number }> = {
  1: { angle: 1.0, distPPM: 5 },       // 1", 5 ppm
  2: { angle: 2.0, distPPM: 10 },       // 2", 10 ppm
  3: { angle: 5.0, distPPM: 20 },       // 5", 20 ppm
  4: { angle: 10.0, distPPM: 50 },      // 10", 50 ppm
};

// ─── Bowditch (Compass Rule) Adjustment ──────────────────────────

/**
 * Apply Bowditch/Compass rule adjustment to a closed traverse.
 * 
 * The Bowditch rule distributes the misclosure proportionally
 * to the cumulative distance from the start:
 * 
 *   Correction_E(i) = -misclosure_E × (Σd₀→i / Σd_total)
 *   Correction_N(i) = -misclosure_N × (Σd₀→i / Σd_total)
 * 
 * This is the standard method for 3rd and 4th order traverses
 * and is accepted by Kenya Survey Department for cadastral work.
 * 
 * @param stations - Traverse stations (with fixed coordinates for control points)
 * @param legs - Traverse legs with bearings and distances
 * @param order - Required accuracy order (1-4)
 * @returns Traverse result with adjusted coordinates
 */
export function bowditchAdjustment(
  stations: TraverseStation[],
  legs: TraverseLeg[],
  order: number = 3
): TraverseResult {
  const warnings: string[] = [];
  
  // Validate: need at least 2 fixed stations
  const fixedStations = stations.filter(s => s.isFixed && s.easting !== undefined && s.northing !== undefined);
  if (fixedStations.length < 2) {
    throw new Error('Need at least 2 fixed control stations for traverse');
  }
  
  // Compute preliminary coordinates
  const preliminary = computePreliminaryCoordinates(stations, legs);
  
  // Compute misclosure
  const misclosure = computeMisclosure(preliminary, stations, legs);
  
  // Check angular misclosure
  const angularClosure = computeAngularClosure(legs, fixedStations);
  misclosure.angular = angularClosure;
  
  // Compute total traverse distance
  const totalDistance = legs.reduce((sum, leg) => sum + leg.distance, 0);
  
  // Compute misclosure ratio
  const ratioValue = totalDistance / misclosure.linear;
  misclosure.ratioValue = ratioValue;
  misclosure.ratio = `1:${Math.round(ratioValue)}`;
  
  // Check against order requirement
  const requiredRatio = ORDER_REQUIREMENTS[order] ?? ORDER_REQUIREMENTS[3];
  const passesOrder = ratioValue >= requiredRatio;
  
  if (!passesOrder) {
    warnings.push(
      `Traverse closure ${misclosure.ratio} does NOT meet ${order} order requirement (1:${requiredRatio})`
    );
  }
  
  // Apply Bowditch corrections
  const adjusted: AdjustedStation[] = [];
  let cumulativeDistance = 0;
  
  for (let i = 0; i < preliminary.length; i++) {
    const station = preliminary[i];
    
    if (station.isFixed) {
      adjusted.push({
        name: station.name,
        easting: stations.find(s => s.name === station.name)!.easting!,
        northing: stations.find(s => s.name === station.name)!.northing!,
        correctionE: 0,
        correctionN: 0,
        isFixed: true,
      });
    } else {
      // Proportional correction based on cumulative distance
      const proportion = cumulativeDistance / totalDistance;
      const corrE = -misclosure.easting * proportion;
      const corrN = -misclosure.northing * proportion;
      
      adjusted.push({
        name: station.name,
        easting: (station.easting ?? 0) + corrE,
        northing: (station.northing ?? 0) + corrN,
        correctionE: corrE,
        correctionN: corrN,
        isFixed: false,
      });
    }
    
    // Add distance to next leg
    const leg = legs.find(l => l.fromStation === station.name);
    if (leg) {
      cumulativeDistance += leg.distance;
    }
  }
  
  return {
    stations: adjusted,
    misclosure,
    adjustmentMethod: 'bowditch',
    order,
    passesOrder,
    totalDistance,
    warnings,
  };
}

// ─── Helper Functions ────────────────────────────────────────────

/**
 * Compute preliminary (unadjusted) traverse coordinates.
 */
function computePreliminaryCoordinates(
  stations: TraverseStation[],
  legs: TraverseLeg[]
): TraverseStation[] {
  const result: TraverseStation[] = [];
  const coordMap = new Map<string, { easting: number; northing: number }>();
  
  // Initialize with fixed station coordinates
  for (const station of stations) {
    if (station.isFixed && station.easting !== undefined && station.northing !== undefined) {
      coordMap.set(station.name, { easting: station.easting, northing: station.northing });
    }
  }
  
  // Compute coordinates along each leg
  for (const leg of legs) {
    const from = coordMap.get(leg.fromStation);
    if (!from) {
      throw new Error(`No coordinates for station ${leg.fromStation}`);
    }
    
    const bearingRad = leg.bearing * Math.PI / 180;
    const dE = leg.distance * Math.sin(bearingRad);
    const dN = leg.distance * Math.cos(bearingRad);
    
    const toCoord = {
      easting: from.easting + dE,
      northing: from.northing + dN,
    };
    
    coordMap.set(leg.toStation, toCoord);
  }
  
  // Build result preserving order
  for (const station of stations) {
    const coord = coordMap.get(station.name);
    result.push({
      name: station.name,
      easting: coord?.easting,
      northing: coord?.northing,
      isFixed: station.isFixed,
    });
  }
  
  return result;
}

/**
 * Compute linear misclosure of a closed traverse.
 */
function computeMisclosure(
  preliminary: TraverseStation[],
  original: TraverseStation[],
  legs: TraverseLeg[]
): TraverseResult['misclosure'] {
  // For a closed traverse, the last computed position should
  // match the closing fixed point
  const firstFixed = original.find(s => s.isFixed && s.easting !== undefined);
  const lastLeg = legs[legs.length - 1];
  
  // Find the last computed position
  const lastComputed = preliminary.find(s => s.name === lastLeg.toStation);
  const closingPoint = original.find(s => s.name === lastLeg.toStation && s.isFixed);
  
  let dE = 0, dN = 0;
  
  if (closingPoint && closingPoint.easting !== undefined && closingPoint.northing !== undefined) {
    if (lastComputed?.easting !== undefined && lastComputed?.northing !== undefined) {
      dE = lastComputed.easting - closingPoint.easting;
      dN = lastComputed.northing - closingPoint.northing;
    }
  }
  
  const linear = Math.sqrt(dE * dE + dN * dN);
  
  return {
    easting: dE,
    northing: dN,
    linear,
    angular: 0, // Computed separately
    ratio: '',
    ratioValue: 0,
  };
}

