/**
 * TIN Worker Client — Promise-based wrapper around the TIN Web Worker with
 * automatic fallback to the synchronous engine when Workers are unavailable.
 *
 * Roadmap reference: docs/ROADMAP.md → Tier 2 → "Web Worker TIN generator"
 * (auto-fallback mode per user spec).
 *
 * Usage:
 *   const triangles = await triangulateAsync(points, breaklines)
 *   const surface   = await buildTINSurfaceAsync(points, breaklines)
 *   const contours  = await generateContoursAsync(points, 1.0, { onProgress })
 *
 * Behaviour:
 *   - First call lazily spawns the Worker via
 *     `new Worker(new URL('./tinWorker.ts', import.meta.url))`.
 *   - If Worker construction throws (e.g., jsdom test env, CSP blocks,
 *     older browser), the client permanently switches to sync mode and
 *     reuses the synchronous engines from `@/lib/engine/contours`.
 *   - Each call gets a unique id; concurrent calls multiplex over the
 *     single worker via id-keyed response handlers.
 *   - Optional `onProgress` callback fires with 0..1 as the worker reports.
 *   - 30 s default timeout; falls back to sync on timeout.
 */

import {
  triangulate,
  buildTINSurface,
  generateContours,
  type SpotHeight,
  type Breakline,
  type Triangle,
  type TINSurface,
  type ContourLine,
} from '@/lib/engine/contours'
import { getTinWorkerUrl } from '@/lib/workers/tinWorkerUrl'

// ─── Types ──────────────────────────────────────────────────────────────────

export interface AsyncOptions {
  /** Progress callback, fires with 0..1. */
  onProgress?: (p: number) => void
  /** Per-call timeout in milliseconds. Default 30000. */
  timeoutMs?: number
  /** Force sync mode for this call (skips worker). */
  forceSync?: boolean
}

// ─── Worker Singleton ───────────────────────────────────────────────────────

let workerInstance: Worker | null = null
let workerUnavailable = false

/** Pending request handlers keyed by request id. */
interface PendingHandler {
  resolve: (result: unknown) => void
  reject: (err: Error) => void
  onProgress?: (p: number) => void
  timer: ReturnType<typeof setTimeout>
  /** Original op + payload so onerror can re-run via sync fallback. */
  op: string
  payload: Record<string, unknown>
}
const pending = new Map<string, PendingHandler>()

let nextId = 0
function nextRequestId(): string {
  nextId += 1
  return `tin-${Date.now()}-${nextId}`
}

/**
 * Lazily construct the worker. Returns null if Workers are unavailable
 * (server-side render, jsdom test, CSP-blocked, etc.).
 */
function getWorker(): Worker | null {
  if (workerUnavailable) return null
  if (workerInstance) return workerInstance
  if (typeof self === 'undefined' || typeof Worker === 'undefined') {
    workerUnavailable = true
    return null
  }
  try {
    // Webpack 5 detects the `new URL('./tinWorker.ts', import.meta.url)`
    // pattern inside `tinWorkerUrl.ts` and emits a separate worker chunk.
    // In test environments the module is mocked to return null, so we
    // fall back to the synchronous engine.
    const workerUrl = getTinWorkerUrl()
    if (!workerUrl) {
      workerUnavailable = true
      return null
    }
    workerInstance = new Worker(workerUrl)
    workerInstance.onmessage = (e: MessageEvent) => {
      const msg = e.data as {
        id: string
        ok?: boolean
        result?: unknown
        error?: string
        progress?: number
      }
      const handler = pending.get(msg.id)
      if (!handler) return
      if (typeof msg.progress === 'number') {
        handler.onProgress?.(msg.progress)
        return
      }
      clearTimeout(handler.timer)
      pending.delete(msg.id)
      if (msg.ok === true) {
        handler.resolve(msg.result)
      } else {
        handler.reject(new Error(msg.error || 'Worker error'))
      }
    }
    workerInstance.onerror = (err: ErrorEvent) => {
      // Worker crashed — FALLBACK to sync engine for any in-flight calls
      // instead of rejecting. The user gets their result, just on the
      // main thread (slower but correct). Subsequent calls will skip the
      // worker entirely until the page is reloaded.
      const pendingEntries = Array.from(pending.entries())
      pending.clear()
      workerInstance = null
      workerUnavailable = true
      // Surface a console warning so devs can spot this in DevTools
      console.warn('[tinWorkerClient] Web worker crashed; falling back to sync engine:', err.message || err)
      for (const [, handler] of pendingEntries) {
        clearTimeout(handler.timer)
        try {
          // Run the original request through the sync fallback so the
          // caller's promise resolves with the same shape.
          handler.resolve(syncFallback(handler.op, handler.payload))
        } catch (e) {
          handler.reject(e instanceof Error ? e : new Error(String(e)))
        }
      }
    }
    return workerInstance
  } catch {
    workerUnavailable = true
    return null
  }
}

/**
 * Send a request to the worker. Returns a Promise that resolves with the
 * worker's result, or rejects on error / timeout.
 */
function dispatch<T>(
  op: string,
  payload: Record<string, unknown>,
  options: AsyncOptions = {}
): Promise<T> {
  const forceSync = options.forceSync || workerUnavailable
  const worker = forceSync ? null : getWorker()

  if (!worker) {
    // Sync fallback — run the synchronous engine in the current thread.
    return Promise.resolve(syncFallback<T>(op, payload))
  }

  return new Promise<T>((resolve, reject) => {
    const id = nextRequestId()
    const timer = setTimeout(() => {
      pending.delete(id)
      // On timeout, fall back to sync for this call only (don't kill worker)
      try {
        resolve(syncFallback<T>(op, payload))
      } catch (err) {
        reject(err instanceof Error ? err : new Error(String(err)))
      }
    }, options.timeoutMs ?? 30000)

    pending.set(id, {
      resolve: (r: unknown) => resolve(r as T),
      reject,
      onProgress: options.onProgress,
      timer,
      op,
      payload,
    })

    worker.postMessage({ id, op, ...payload })
  })
}

/** Run the equivalent sync engine in-process. */
function syncFallback<T>(op: string, payload: Record<string, unknown>): T {
  switch (op) {
    case 'triangulate': {
      const { points, breaklines } = payload as {
        points: SpotHeight[]
        breaklines?: Breakline[]
      }
      if (breaklines && breaklines.length > 0) {
        const surface = buildTINSurface(points, breaklines)
        return surface.triangles as unknown as T
      }
      return triangulate(points) as unknown as T
    }
    case 'buildTINSurface': {
      const { points, breaklines } = payload as {
        points: SpotHeight[]
        breaklines?: Breakline[]
      }
      return buildTINSurface(points, breaklines) as unknown as T
    }
    case 'generateContours': {
      const { points, interval, indexInterval, breaklines } = payload as {
        points: SpotHeight[]
        interval: number
        indexInterval?: number
        breaklines?: Breakline[]
      }
      return generateContours(points, interval, indexInterval, breaklines) as unknown as T
    }
    default:
      throw new Error(`Unknown op in sync fallback: ${op}`)
  }
}

// ─── Public API ─────────────────────────────────────────────────────────────

/**
 * Triangulate spot heights to a Delaunay TIN. Uses the worker when available;
 * falls back to the synchronous `triangulate` from `@/lib/engine/contours`.
 */
export function triangulateAsync(
  points: SpotHeight[],
  breaklines?: Breakline[],
  options?: AsyncOptions
): Promise<Triangle[]> {
  return dispatch<Triangle[]>('triangulate', { points, breaklines }, options)
}

/**
 * Build a full TIN surface object with bounds metadata and breakline enforcement.
 */
export function buildTINSurfaceAsync(
  points: SpotHeight[],
  breaklines?: Breakline[],
  options?: AsyncOptions
): Promise<TINSurface> {
  return dispatch<TINSurface>('buildTINSurface', { points, breaklines }, options)
}

/**
 * Generate contour lines via marching triangles. Uses the worker when available.
 */
export function generateContoursAsync(
  points: SpotHeight[],
  interval: number,
  options?: { indexInterval?: number; breaklines?: Breakline[] } & AsyncOptions
): Promise<ContourLine[]> {
  const { indexInterval, breaklines, ...asyncOpts } = options ?? {}
  return dispatch<ContourLine[]>(
    'generateContours',
    { points, interval, indexInterval, breaklines },
    asyncOpts
  )
}

// ─── Test Helpers (exported for unit tests) ─────────────────────────────────

/**
 * Returns true if the worker is currently available. Mainly useful for tests
 * and for the UI to display a "running in background" badge.
 */
export function isWorkerAvailable(): boolean {
  return !workerUnavailable && getWorker() !== null
}

/**
 * Force the client into sync mode for the rest of the session. Used in tests
 * to exercise the sync fallback path without spawning real workers.
 */
export function _forceSyncModeForTests(): void {
  workerUnavailable = true
  if (workerInstance) {
    workerInstance.terminate()
    workerInstance = null
  }
  for (const [, handler] of pending) {
    clearTimeout(handler.timer)
    try {
      handler.resolve(syncFallback(handler.op, handler.payload))
    } catch {
      handler.reject(new Error('Forced into sync mode'))
    }
  }
  pending.clear()
}

/**
 * Reset module state (tests only).
 */
export function _resetForTests(): void {
  workerUnavailable = false
  if (workerInstance) {
    workerInstance.terminate()
    workerInstance = null
  }
  pending.clear()
}

import { FieldBookRow } from '@/types/fieldbook';
import { SurveyType } from '@/types/project';

export interface FieldBookWarning {
  rowIndex?: number;
  column?: string;
  message: string;
  severity: 'warning' | 'error';
}

export interface AutoCalculateResult {
  rows: FieldBookRow[];
  warnings: FieldBookWarning[];
}

function parseNumber(value: string | number | null | undefined): number | null {
  if (value === '' || value === null || value === undefined) return null;
  return typeof value === 'number' ? value : Number(value);
}

function calculateEngineeringRL(
  rows: FieldBookRow[],
  changedRowIndex: number
): FieldBookRow[] {
  const updated = [...rows];
  let hpc: number | null = null;

  for (let i = 0; i < updated.length; i++) {
    const row = { ...updated[i] };
    const bs = parseNumber(row.bs);
    const is = parseNumber(row.is);
    const fs = parseNumber(row.fs);
    const prevRL = i > 0 ? parseNumber(updated[i - 1].rl) : null;

    if (bs !== null && (prevRL !== null || i === 0)) {
      const openingRL = parseNumber(rows[0]?.rl) ?? 1000;
      hpc = openingRL + bs;
      row.hpc = hpc;
    }

    if (hpc !== null) {
      if (is !== null) {
        row.rl = hpc - is;
      } else if (fs !== null) {
        row.rl = hpc - fs;
      }
    }

    updated[i] = row;
  }

  return updated;
}

function calculateTopographicRL(
  rows: FieldBookRow[],
  changedRowIndex: number
): FieldBookRow[] {
  const updated = [...rows];

  for (let i = 0; i < updated.length; i++) {
    const row = { ...updated[i] };
    const hd = parseNumber(row.hd);
    const va = parseNumber(row.va);
    const instRL = parseNumber(row.rl);

    if (hd !== null && va !== null && instRL !== null) {
      const vaRad = (va * Math.PI) / 180;
      const vertDist = hd / Math.cos(vaRad);
      row.rl = instRL + vertDist * Math.sin(vaRad);
    }

    updated[i] = row;
  }

  return updated;
}

function calculateMiningVolume(
  rows: FieldBookRow[],
  changedRowIndex: number
): FieldBookRow[] {
  return [...rows];
}

export function applyAutoCalculations(
  surveyType: SurveyType,
  rows: FieldBookRow[],
  changedRowIndex: number
): FieldBookRow[] {
  switch (surveyType) {
    case 'engineering':
      return calculateEngineeringRL(rows, changedRowIndex);
    case 'topographic':
      return calculateTopographicRL(rows, changedRowIndex);
    default:
      return rows;
  }
}

export function validateFieldBook(
  surveyType: SurveyType,
  rows: FieldBookRow[]
): FieldBookWarning[] {
  const warnings: FieldBookWarning[] = [];

  switch (surveyType) {
    case 'cadastral': {
      rows.forEach((row, idx) => {
        const distance = parseNumber(row.distance);
        const bearing = parseNumber(row.bearing);
        if (distance !== null && distance <= 0) {
          warnings.push({ rowIndex: idx, column: 'distance', message: 'Distance must be > 0', severity: 'error' });
        }
        if (bearing !== null && (bearing < 0 || bearing > 360)) {
          warnings.push({ rowIndex: idx, column: 'bearing', message: 'Bearing must be 0-360°', severity: 'error' });
        }
      });
      break;
    }

    case 'engineering': {
      rows.forEach((row, idx) => {
        const bs = parseNumber(row.bs);
        const is = parseNumber(row.is);
        const fs = parseNumber(row.fs);
        if (bs !== null && fs !== null && bs !== 0 && fs !== 0) {
        }
        if (bs !== null && is !== null && bs !== 0 && is !== 0) {
          warnings.push({ rowIndex: idx, column: 'bs', message: 'BS and IS in same row', severity: 'warning' });
        }
      });
      break;
    }

    case 'drone': {
      if (rows.length < 5) {
        warnings.push({ message: 'Minimum 5 GCPs recommended', severity: 'warning' });
      }
      break;
    }

    case 'deformation': {
      const epochs = new Set(rows.map((r) => r.epoch).filter(Boolean));
      if (epochs.size < 2) {
        warnings.push({ message: 'Minimum 2 epochs required for comparison', severity: 'warning' });
      }
      break;
    }
  }

  return warnings;
}

/**
 * Survey Workflow Engine
 * Reads uploaded CSV, detects survey type, runs calculation workflow
 * 
 * METARDU Calculation Standards: N.N. Basak
 * - No intermediate rounding
 * - Full floating point precision
 * - Round only at display layer
 */

import { bowditchAdjustment, TraverseInput } from '../engine/traverse'
import { riseAndFall, LevelingInput } from '../engine/leveling'
import { radiation } from '../engine/cogo'

export type SurveyType = 'traverse' | 'leveling' | 'radiation' | 'coordinates' | 'unknown'

export interface SurveyDataset {
  surveyType: SurveyType
  observations: SurveyObservation[]
  metadata: Record<string, unknown>
}

export interface SurveyObservation {
  station: string
  target?: string
  type: 'BS' | 'IS' | 'FS' | 'BEARING' | 'DISTANCE' | 'ANGLE' | 'COORDINATE' | 'ELEVATION'
  value1?: number
  value2?: number
  value3?: number
}

export interface WorkflowResult {
  success: boolean
  surveyType: SurveyType
  results: any
  validation: ValidationResult
  warnings: string[]
  errors: string[]
}

export interface CoordinateImportResult {
  type: 'coordinates'
  points: Array<{
    name: string
    easting: number
    northing: number
    elevation?: number
  }>
}

export interface ValidationResult {
  passed: boolean
  checks: ValidationCheck[]
  precision?: number
  precisionGrade?: string
  angularMisclosure?: number
  linearMisclosure?: number
}

export interface ValidationCheck {
  name: string
  passed: boolean
  message: string
  value?: number
}

export interface TraverseWorkflowData {
  legs: Array<{
    fromStation: string
    toStation: string
    bearing: number
    distance: number
  }>
  openingPoint?: {
    name: string
    easting: number
    northing: number
  }
  closingPoint?: {
    name: string
    easting: number
    northing: number
  }
}

export interface LevelingWorkflowData {
  readings: Array<{
    station: string
    bs?: number
    is?: number
    fs?: number
  }>
  openingRL: number
  closingRL?: number
}

export interface RadiationWorkflowData {
  station: {
    name: string
    easting: number
    northing: number
    elevation?: number
  }
  observations: Array<{
    pointName: string
    bearing: number
    distance: number
    verticalAngle?: number
    targetHeight?: number
  }>
}

export function detectSurveyType(observations: SurveyObservation[]): SurveyType {
  if (observations.length === 0) return 'unknown'

  const types = new Set(observations.map((o: any) => o.type))
  
  if (types.has('BS') || types.has('IS') || types.has('FS')) {
    return 'leveling'
  }
  
  if (types.has('BEARING') && types.has('DISTANCE')) {
    return 'traverse'
  }
  
  if (types.has('ANGLE') && types.has('DISTANCE')) {
    return 'radiation'
  }
  
  if (types.has('COORDINATE')) {
    return 'coordinates'
  }

  return 'unknown'
}

export function runTraverseWorkflow(data: TraverseWorkflowData): WorkflowResult {
  const warnings: string[] = []
  const errors: string[] = []
  let validation: ValidationResult

  try {
    if (!data.openingPoint) {
      errors.push('Opening point coordinates required for traverse')
      return {
        success: false,
        surveyType: 'traverse',
        results: null,
        validation: { passed: false, checks: [] },
        warnings,
        errors
      }
    }

    const traverseInput: TraverseInput = {
      points: [
        { name: data.openingPoint.name, easting: data.openingPoint.easting, northing: data.openingPoint.northing }
      ],
      distances: data.legs.map((l: any) => l.distance),
      bearings: data.legs.map((l: any) => l.bearing)
    }

    const result = bowditchAdjustment(traverseInput)

    const angularMisclosure = calculateAngularMisclosure(data.legs)
    const linearPrecision = result.precisionRatio > 0 ? 1 / result.precisionRatio : 0

    const precisionGrade = getPrecisionGrade(linearPrecision)

    const checks: ValidationCheck[] = []

    if (angularMisclosure !== null) {
      const angularLimit = 60 * Math.sqrt(data.legs.length)
      checks.push({
        name: 'Angular Misclosure',
        passed: Math.abs(angularMisclosure) <= angularLimit,
        message: angularMisclosure > angularLimit 
          ? `Angular misclosure ${angularMisclosure.toFixed(1)}" exceeds limit ${angularLimit.toFixed(1)}"`
          : 'Angular check passed',
        value: angularMisclosure
      })
    }

    checks.push({
      name: 'Linear Precision',
      passed: linearPrecision >= 1000,
      message: linearPrecision < 1000 
        ? `Precision 1:${linearPrecision.toFixed(0)} below acceptable threshold`
        : `Precision 1:${linearPrecision.toFixed(0)} achieved`,
      value: linearPrecision
    })

    const linearError = Math.sqrt(result.closingErrorE ** 2 + result.closingErrorN ** 2)
    if (linearError > 0) {
      checks.push({
        name: 'Linear Misclosure',
        passed: true,
        message: `Closing error: ${linearError.toFixed(4)} m`,
        value: linearError
      })
    }

    validation = {
      passed: checks.every(c => c.passed),
      checks,
      precision: linearPrecision,
      precisionGrade,
      angularMisclosure: angularMisclosure || undefined,
      linearMisclosure: linearError
    }

    return {
      success: true,
      surveyType: 'traverse',
      results: result,
      validation,
      warnings,
      errors: []
    }

  } catch (e) {
    errors.push(`Traverse calculation failed: ${e}`)
    return {
      success: false,
      surveyType: 'traverse',
      results: null,
      validation: { passed: false, checks: [] },
      warnings,
      errors
    }
  }
}

export function runLevelingWorkflow(data: LevelingWorkflowData): WorkflowResult {
  const warnings: string[] = []
  const errors: string[] = []
  let validation: ValidationResult

  try {
    const levelingInput: LevelingInput = {
      readings: data.readings,
      openingRL: data.openingRL,
      closingRL: data.closingRL,
      method: 'rise_and_fall'
    }

    const result = riseAndFall(levelingInput)

    const arithmeticPassed = result.arithmeticCheck
    const arithmeticDiff = result.misclosure

    const checks: ValidationCheck[] = []

    checks.push({
      name: 'Arithmetic Check',
      passed: arithmeticPassed,
      message: arithmeticPassed 
        ? `Arithmetic check passed (diff: ${Math.abs(arithmeticDiff).toFixed(4)} m)`
        : `Arithmetic check failed (diff: ${arithmeticDiff.toFixed(4)} m)`,
      value: arithmeticDiff
    })

    if (data.closingRL && result.misclosure !== undefined) {
      const closingErrorMm = Math.abs(result.misclosure) * 1000
      const distanceKm = data.readings.length * 0.1
      const allowableMm = 10 * Math.sqrt(distanceKm)
      
      checks.push({
        name: 'Closing Error',
        passed: closingErrorMm <= allowableMm,
        message: `Closing error ${closingErrorMm.toFixed(1)}mm vs allowable ${allowableMm.toFixed(1)}mm`,
        value: closingErrorMm
      })
    }

    validation = {
      passed: checks.every(c => c.passed),
      checks
    }

    if (!arithmeticPassed) {
      errors.push('Arithmetic check failed - results blocked')
      return {
        success: false,
        surveyType: 'leveling',
        results: null,
        validation,
        warnings,
        errors
      }
    }

    return {
      success: true,
      surveyType: 'leveling',
      results: result,
      validation,
      warnings,
      errors: []
    }

  } catch (e) {
    errors.push(`Leveling calculation failed: ${e}`)
    return {
      success: false,
      surveyType: 'leveling',
      results: null,
      validation: { passed: false, checks: [] },
      warnings,
      errors
    }
  }
}

export function runRadiationWorkflow(data: RadiationWorkflowData): WorkflowResult {
  const warnings: string[] = []
  const errors: string[] = []

  try {
    const points = data.observations.map((obs: any) => {
      const rad = radiation(
        { easting: data.station.easting, northing: data.station.northing },
        obs.bearing,
        obs.distance
      )
      return {
        name: obs.pointName,
        easting: rad.point.easting,
        northing: rad.point.northing,
        distance: rad.distance,
        bearing: rad.bearing
      }
    })

    const checks: ValidationCheck[] = []

    checks.push({
      name: 'Observations',
      passed: points.length > 0,
      message: `${points.length} points computed from radiation`,
      value: points.length
    })

    return {
      success: true,
      surveyType: 'radiation',
      results: { points },
      validation: { passed: true, checks },
      warnings,
      errors: []
    }

  } catch (e) {
    errors.push(`Radiation calculation failed: ${e}`)
    return {
      success: false,
      surveyType: 'radiation',
      results: null,
      validation: { passed: false, checks: [] },
      warnings,
      errors
    }
  }
}

export function runCoordinatesWorkflow(observations: SurveyObservation[]): WorkflowResult {
  const warnings: string[] = []
  const errors: string[] = []

  try {
    const points = observations
      .filter((o: any) => o.type === 'COORDINATE' && o.value1 !== undefined && o.value2 !== undefined)
      .map((o: any) => ({
        name: o.station,
        easting: o.value1!,
        northing: o.value2!,
        elevation: o.value3
      }))

    if (points.length === 0) {
      errors.push('No valid coordinate observations found')
      return {
        success: false,
        surveyType: 'coordinates',
        results: null,
        validation: { passed: false, checks: [] },
        warnings,
        errors
      }
    }

    const result = {
      type: 'coordinates' as const,
      points
    }

    return {
      success: true,
      surveyType: 'coordinates',
      results: result,
      validation: { 
        passed: true, 
        checks: [{
          name: 'Points Import',
          passed: true,
          message: `${points.length} points imported successfully`,
          value: points.length
        }] 
      },
      warnings,
      errors: []
    }

  } catch (e) {
    errors.push(`Coordinate import failed: ${e}`)
    return {
      success: false,
      surveyType: 'coordinates',
      results: null,
      validation: { passed: false, checks: [] },
      warnings,
      errors
    }
  }
}

function calculateAngularMisclosure(legs: TraverseWorkflowData['legs']): number | null {
  if (legs.length < 3) return null

  let sumAngle = 0
  for (let i = 0; i < legs.length; i++) {
    const currentBearing = legs[i].bearing
    const nextBearing = legs[(i + 1) % legs.length].bearing
    
    let angle = nextBearing - currentBearing
    if (angle < 0) angle += 360
    if (angle > 180) angle = 360 - angle
    
    sumAngle += angle
  }

  const interiorSum = (legs.length - 2) * 180
  const misclosure = sumAngle - interiorSum

  return misclosure * 3600
}

function getPrecisionGrade(precision: number): string {
  if (precision >= 5000) return 'Excellent (urban cadastral)'
  if (precision >= 3000) return 'Good (suburban)'
  if (precision >= 1000) return 'Acceptable (rural)'
  return 'Poor (rejected)'
}

export function runWorkflow(
  surveyType: SurveyType,
  data: TraverseWorkflowData | LevelingWorkflowData | RadiationWorkflowData
): WorkflowResult {
  switch (surveyType) {
    case 'traverse':
      return runTraverseWorkflow(data as TraverseWorkflowData)
    case 'leveling':
      return runLevelingWorkflow(data as LevelingWorkflowData)
    case 'radiation':
      return runRadiationWorkflow(data as RadiationWorkflowData)
    default:
      return {
        success: false,
        surveyType,
        results: null,
        validation: { passed: false, checks: [] },
        warnings: [],
        errors: [`Unknown survey type: ${surveyType}`]
      }
  }
}

import { dmsToDeg } from './units'
import type { BeaconPoint, BoundaryLine } from './types'

export interface Point2D { x: number; y: number }

export function computePositions(
  beacons: BeaconPoint[],
  boundaries: BoundaryLine[]
): Map<string, Point2D> {
  const hasCoords = beacons.every(b => b.easting !== undefined && b.northing !== undefined)

  if (hasCoords) {
    const map = new Map<string, Point2D>()
    beacons.forEach((b: any) => {
      map.set(b.id, { x: b.easting!, y: b.northing! })
    })
    return map
  }

  const map = new Map<string, Point2D>()
  let cursor: Point2D = { x: 0, y: 0 }

  if (beacons.length === 0) return map
  map.set(beacons[0].id, cursor)

  for (const line of boundaries) {
    if (!map.has(line.fromBeaconId)) continue
    cursor = map.get(line.fromBeaconId)!
    const bearingRad = (dmsToDeg(line.bearingDMS) * Math.PI) / 180
    const next: Point2D = {
      x: cursor.x + line.distanceMeters * Math.sin(bearingRad),
      y: cursor.y + line.distanceMeters * Math.cos(bearingRad),
    }
    if (!map.has(line.toBeaconId)) {
      map.set(line.toBeaconId, next)
    }
  }
  return map
}

export function normalizeToViewport(
  positions: Map<string, Point2D>,
  viewportW: number,
  viewportH: number,
  padding: number = 80
): Map<string, Point2D> {
  const pts = Array.from(positions.values())
  if (pts.length === 0) return positions

  const minX = Math.min(...pts.map((p: any) => p.x))
  const maxX = Math.max(...pts.map((p: any) => p.x))
  const minY = Math.min(...pts.map((p: any) => p.y))
  const maxY = Math.max(...pts.map((p: any) => p.y))

  const rangeX = maxX - minX || 1
  const rangeY = maxY - minY || 1
  const scale = Math.min(
    (viewportW - 2 * padding) / rangeX,
    (viewportH - 2 * padding) / rangeY
  )

  const result = new Map<string, Point2D>()
  positions.forEach((pt, id) => {
    result.set(id, {
      x: padding + (pt.x - minX) * scale,
      y: viewportH - padding - (pt.y - minY) * scale,
    })
  })
  return result
}

export function polygonCentroid(
  beaconIds: string[],
  positions: Map<string, Point2D>
): Point2D {
  const pts = beaconIds.map((id: any) => positions.get(id)).filter(Boolean) as Point2D[]
  if (pts.length === 0) return { x: 0, y: 0 }
  return {
    x: pts.reduce((s, p) => s + p.x, 0) / pts.length,
    y: pts.reduce((s, p) => s + p.y, 0) / pts.length,
  }
}

/**
 * METARDU Global UI State Store (Zustand)
 * ==========================================
 * Lightweight transient UI state — sidebar toggles, selected rows,
 * active panels, modals, theme preferences, etc.
 *
 * This store is intentionally UI-focused. Survey data (points, parcels,
 * observations) lives in dedicated domain stores that interface with
 * Web Workers and Yjs CRDTs for offline-first sync.
 */

import { create } from 'zustand'
import { subscribeWithSelector } from 'zustand/middleware'

// ─── Types ────────────────────────────────────────────────────────────────

export type SidebarPanel = 'none' | 'layers' | 'points' | 'properties' | 'measurements' | 'fieldbook'
export type BottomPanel = 'none' | 'observations' | 'coordinates' | 'journal' | 'console'
export type EditorTool = 'select' | 'point' | 'line' | 'polygon' | 'rectangle' | 'circle' | 'measure'

export interface Notification {
  id: string
  type: 'info' | 'success' | 'warning' | 'error'
  title: string
  message?: string
  duration?: number // ms, 0 = persistent
  createdAt: number
}

export interface MapViewport {
  center: [number, number]
  zoom: number
  rotation: number
  projection: string
}

// ─── UI Store Interface ──────────────────────────────────────────────────

export interface UIState {
  // Sidebar & Panels
  leftSidebarOpen: boolean
  leftSidebarWidth: number
  leftSidebarPanel: SidebarPanel
  rightSidebarOpen: boolean
  rightSidebarWidth: number
  bottomPanelOpen: boolean
  bottomPanelHeight: number
  bottomPanelTab: BottomPanel

  // Active Tool
  activeTool: EditorTool

  // Selection State
  selectedPointIds: string[]
  selectedFeatureId: string | null
  highlightedPointId: string | null

  // Map Viewport (synced from OL map)
  viewport: MapViewport | null

  // Theme
  colorScheme: 'dark' | 'light'
  highContrast: boolean

  // Command Palette
  commandPaletteOpen: boolean

  // Notifications (toast queue)
  notifications: Notification[]

  // Loading States
  globalLoading: boolean
  loadingMessage: string | null

  // ─── Actions ──────────────────────────────────────────────────────────

  // Sidebar
  toggleLeftSidebar: () => void
  setLeftSidebarOpen: (open: boolean) => void
  setLeftSidebarWidth: (width: number) => void
  setLeftSidebarPanel: (panel: SidebarPanel) => void
  toggleRightSidebar: () => void
  setRightSidebarOpen: (open: boolean) => void
  setRightSidebarWidth: (width: number) => void
  toggleBottomPanel: () => void
  setBottomPanelOpen: (open: boolean) => void
  setBottomPanelHeight: (height: number) => void
  setBottomPanelTab: (tab: BottomPanel) => void

  // Tool
  setActiveTool: (tool: EditorTool) => void

  // Selection
  setSelectedPointIds: (ids: string[]) => void
  addSelectedPointId: (id: string) => void
  removeSelectedPointId: (id: string) => void
  clearSelection: () => void
  setSelectedFeatureId: (id: string | null) => void
  setHighlightedPointId: (id: string | null) => void

  // Map
  setViewport: (viewport: MapViewport) => void

  // Theme
  toggleColorScheme: () => void
  setColorScheme: (scheme: 'dark' | 'light') => void
  setHighContrast: (enabled: boolean) => void

  // Command Palette
  openCommandPalette: () => void
  closeCommandPalette: () => void

  // Notifications
  addNotification: (notification: Omit<Notification, 'id' | 'createdAt'>) => string
  removeNotification: (id: string) => void
  clearNotifications: () => void

  // Loading
  setGlobalLoading: (loading: boolean, message?: string | null) => void
}

// ─── Store ───────────────────────────────────────────────────────────────

let notificationCounter = 0

export const useUIStore = create<UIState>()(
  subscribeWithSelector((set, get) => ({
    // ─── Initial State ──────────────────────────────────────────────────

    leftSidebarOpen: true,
    leftSidebarWidth: 300,
    leftSidebarPanel: 'points',
    rightSidebarOpen: false,
    rightSidebarWidth: 320,
    bottomPanelOpen: false,
    bottomPanelHeight: 220,
    bottomPanelTab: 'observations',

    activeTool: 'select',

    selectedPointIds: [],
    selectedFeatureId: null,
    highlightedPointId: null,

    viewport: null,

    colorScheme: 'dark',
    highContrast: false,

    commandPaletteOpen: false,

    notifications: [],

    globalLoading: false,
    loadingMessage: null,

    // ─── Sidebar Actions ────────────────────────────────────────────────

    toggleLeftSidebar: () => set(s => ({ leftSidebarOpen: !s.leftSidebarOpen })),
    setLeftSidebarOpen: (open) => set({ leftSidebarOpen: open }),
    setLeftSidebarWidth: (width) => set({ leftSidebarWidth: Math.max(200, Math.min(500, width)) }),
    setLeftSidebarPanel: (panel) => set(s => ({
      leftSidebarPanel: panel,
      leftSidebarOpen: panel !== 'none'
    })),

    toggleRightSidebar: () => set(s => ({ rightSidebarOpen: !s.rightSidebarOpen })),
    setRightSidebarOpen: (open) => set({ rightSidebarOpen: open }),
    setRightSidebarWidth: (width) => set({ rightSidebarWidth: Math.max(240, Math.min(480, width)) }),

    toggleBottomPanel: () => set(s => ({ bottomPanelOpen: !s.bottomPanelOpen })),
    setBottomPanelOpen: (open) => set({ bottomPanelOpen: open }),
    setBottomPanelHeight: (height) => set({ bottomPanelHeight: Math.max(120, Math.min(500, height)) }),
    setBottomPanelTab: (tab) => set(s => ({
      bottomPanelTab: tab,
      bottomPanelOpen: true
    })),

    // ─── Tool Actions ───────────────────────────────────────────────────

    setActiveTool: (tool) => set({ activeTool: tool }),

    // ─── Selection Actions ──────────────────────────────────────────────

    setSelectedPointIds: (ids) => set({ selectedPointIds: ids }),
    addSelectedPointId: (id) => set(s => ({
      selectedPointIds: s.selectedPointIds.includes(id)
        ? s.selectedPointIds
        : [...s.selectedPointIds, id]
    })),
    removeSelectedPointId: (id) => set(s => ({
      selectedPointIds: s.selectedPointIds.filter(pid => pid !== id)
    })),
    clearSelection: () => set({
      selectedPointIds: [],
      selectedFeatureId: null,
      highlightedPointId: null
    }),
    setSelectedFeatureId: (id) => set({ selectedFeatureId: id }),
    setHighlightedPointId: (id) => set({ highlightedPointId: id }),

    // ─── Map Actions ────────────────────────────────────────────────────

    setViewport: (viewport) => set({ viewport }),

    // ─── Theme Actions ──────────────────────────────────────────────────

    toggleColorScheme: () => set(s => ({ colorScheme: s.colorScheme === 'dark' ? 'light' : 'dark' })),
    setColorScheme: (scheme) => set({ colorScheme: scheme }),
    setHighContrast: (enabled) => set({ highContrast: enabled }),

    // ─── Command Palette ────────────────────────────────────────────────

    openCommandPalette: () => set({ commandPaletteOpen: true }),
    closeCommandPalette: () => set({ commandPaletteOpen: false }),

    // ─── Notification Actions ───────────────────────────────────────────

    addNotification: (notification) => {
      const id = `notif-${Date.now()}-${notificationCounter++}`
      const entry: Notification = {
        ...notification,
        id,
        createdAt: Date.now(),
      }
      set(s => ({ notifications: [...s.notifications, entry] }))

      // Auto-dismiss if duration is set
      if (notification.duration && notification.duration > 0) {
        setTimeout(() => {
          get().removeNotification(id)
        }, notification.duration)
      }

      return id
    },

    removeNotification: (id) => set(s => ({
      notifications: s.notifications.filter(n => n.id !== id)
    })),

    clearNotifications: () => set({ notifications: [] }),

    // ─── Loading Actions ────────────────────────────────────────────────

    setGlobalLoading: (loading, message = null) => set({
      globalLoading: loading,
      loadingMessage: loading ? message : null
    }),
  }))
)

/**
 * Canonical survey point types for Metardu.
 *
 * ─── Why this file exists ───────────────────────────────────────────────
 * Before this consolidation, the codebase had ~12 divergent `SurveyPoint`
 * interfaces scattered across export/, map/, topo/, parcel/, orchestrator/,
 * and generators/. They were structurally compatible (so TypeScript didn't
 * complain) but semantically different — some had `id`, some had `name`,
 * some had `code`, some had `lat/lon`. This made it impossible to pass a
 * point from one module to another without silent field loss.
 *
 * Every module MUST now import from this file. Local declarations of
 * `SurveyPoint` are banned by the eslint rule `no-restricted-syntax` in
 * `.eslintrc.json`.
 *
 * ─── Design principles ─────────────────────────────────────────────────
 * 1. The canonical `SurveyPoint` matches the database row shape — fields
 *    that exist in the `survey_points` table are required or optional
 *    exactly as the schema dictates.
 * 2. Pure-geometry call sites (IDW, turf, area) use `Point2D` or `Point3D`
 *    instead. They have no identity and no database coupling.
 * 3. Specialised variants (`SurveyPointWithCode`, `SurveyPoint3D`) are
 *    standalone (not extending SurveyPoint) because their domains
 *    frequently lack a human-assigned `name`.
 *
 * ─── CRS convention ────────────────────────────────────────────────────
 * `easting`/`northing` are in metres, in the project CRS (typically
 * Arc 1960 / UTM Zone 37 South, EPSG:21037). `lat`/`lon`, when present,
 * are decimal degrees in WGS84 (EPSG:4326). `elevation` is orthometric
 * height in metres above MSL unless explicitly noted otherwise.
 */

// ─── Pure geometry (no identity, no DB coupling) ────────────────────────

/** A 2D coordinate pair in metres (project CRS). */
export interface Point2D {
  easting: number
  northing: number
}

/** A 3D coordinate triple in metres (project CRS). */
export interface Point3D extends Point2D {
  elevation: number
}

// ─── Canonical survey point (database row shape) ───────────────────────

/**
 * A survey point as stored in the `survey_points` table.
 *
 * Field optionality mirrors the DB schema:
 * - `id` is optional because the type is also used for points being
 *   created client-side before insertion.
 * - `elevation` is nullable because some points (e.g. horizontal control)
 *   have no measured height.
 * - `is_control` defaults to `false`; `control_order` only applies when
 *   `is_control` is true.
 * - `code` and `description` are nullable topo feature attributes.
 *
 * AUDIT FIX (C5, 2026-07-02): Added CRS, accuracy, and provenance fields
 * to match migration 027. All new fields are optional for backward
 * compatibility, but new code SHOULD populate them — especially `datum`,
 * `utm_zone`, and `source` — so the chain-of-custody is preserved.
 */
export interface SurveyPoint {
  /** UUID; optional for points not yet persisted */
  id?: string
  /** Human-readable identifier (e.g. "TS1", "BM-12", "P-003") */
  name: string
  /** Easting in metres (project CRS) */
  easting: number
  /** Northing in metres (project CRS) */
  northing: number
  /** Orthometric height in metres above MSL; null if not measured */
  elevation?: number | null
  /** True if this is a control point (traverse station, BM, GCP) */
  is_control?: boolean
  /** Control order, e.g. "1st", "2nd", "3rd" — only when is_control */
  control_order?: string
  /** Topo feature code (e.g. "BUILD", "TREE", "ROAD_EDGE") */
  code?: string | null
  /** Free-text description */
  description?: string | null
  /** WGS84 latitude in decimal degrees (computed, not stored) */
  lat?: number
  /** WGS84 longitude in decimal degrees (computed, not stored) */
  lon?: number
  /** Whether the point is locked from editing (e.g. imported control) */
  locked?: boolean

  // ─── CRS metadata (migration 027) ──────────────────────────────────────
  /** Coordinate datum (Arc 1960, WGS84). Defaults to project datum. */
  datum?: string | null
  /** Map projection (UTM, Cassini-Soldner). Default UTM. */
  projection?: string | null
  /** UTM zone (1-60). Defaults to project utm_zone. */
  utm_zone?: number | null
  /** Hemisphere: 'N' or 'S'. Defaults to project hemisphere. */
  hemisphere?: 'N' | 'S' | null
  /** Coordinate epoch year (for time-dependent reference frames). */
  epoch_year?: number | null

  // ─── Accuracy metadata (migration 027) ─────────────────────────────────
  /** Standard deviation of easting (metres). Null = unknown. */
  std_dev_e?: number | null
  /** Standard deviation of northing (metres). Null = unknown. */
  std_dev_n?: number | null
  /** Standard deviation of elevation (metres). Null = unknown. */
  std_dev_z?: number | null
  /** Semi-major axis of error ellipse at confidence_level (metres). */
  error_ellipse_major?: number | null
  /** Semi-minor axis of error ellipse at confidence_level (metres). */
  error_ellipse_minor?: number | null
  /** Orientation of error ellipse major axis (degrees from North). */
  error_ellipse_orient?: number | null
  /** Confidence level for the error ellipse (95 = 95%). Default 95. */
  confidence_level?: number | null

  // ─── Provenance metadata (migration 027) ───────────────────────────────
  /** Origin of the coordinate: manual, gnss, total_station, imported, adjusted. */
  source?: 'manual' | 'gnss' | 'total_station' | 'imported' | 'adjusted' | 'unknown' | null
  /** FK to equipment table. Null if instrument not recorded. */
  instrument_id?: string | null
  /** FK to users table — who observed this point. Null if unknown. */
  observer_id?: string | null
  /** UUID of the import session that loaded this point (if source = imported). */
  import_session_id?: string | null
  /** Date the point was observed in the field. */
  observation_date?: string | null
}

// ─── Specialised variants ──────────────────────────────────────────────

/**
 * A survey point that carries a feature code, used by topo classification.
 *
 * Does NOT extend `SurveyPoint` because topo point clouds often lack a
 * human-assigned `name` (e.g. raw tacheometry readings). `code` is required
 * because the classifier contract depends on it.
 */
export interface SurveyPointWithCode {
  /** Easting in metres (project CRS) */
  easting: number
  /** Northing in metres (project CRS) */
  northing: number
  /** Orthometric height in metres above MSL; optional for 2D coded points */
  elevation?: number
  /** Topo feature code (e.g. "BUILD", "TREE", "ROAD_EDGE") — required */
  code: string
  /** Sequential point number from the field book (e.g. "1", "2", "3") */
  pointNumber?: string
  /** Optional human-readable identifier if known */
  name?: string
  /** Optional UUID if the point has been persisted */
  id?: string
}

/**
 * A 3D survey point with guaranteed elevation, used by mining/volumetric
 * modules where height is mandatory. Does NOT extend `SurveyPoint` because
 * mining scans frequently lack a `name` field.
 */
export interface SurveyPoint3D {
  id?: string
  easting: number
  northing: number
  elevation: number
  code?: string
}

// ─── Helpers ───────────────────────────────────────────────────────────

/** Type guard: does this object look like a SurveyPoint? */
export function isSurveyPoint(value: unknown): value is SurveyPoint {
  if (typeof value !== 'object' || value === null) return false
  const v = value as Record<string, unknown>
  return (
    (v.id === undefined || typeof v.id === 'string') &&
    typeof v.name === 'string' &&
    typeof v.easting === 'number' &&
    typeof v.northing === 'number' &&
    (v.elevation === undefined ||
      v.elevation === null ||
      typeof v.elevation === 'number')
  )
}

/** Coerce a partial/loose record into a SurveyPoint, throwing on invalid shape. */
export function asSurveyPoint(value: Record<string, unknown>): SurveyPoint {
  if (!isSurveyPoint(value)) {
    throw new Error(
      `Invalid SurveyPoint: missing required fields (name/easting/northing). Got: ${JSON.stringify(value).slice(0, 200)}`
    )
  }
  return value
}

/**
 * METARDU Worker Bridge
 * ======================
 * Client-side wrapper that manages communication with the compute Web Worker.
 * Provides a Promise-based API for all worker operations.
 *
 * Usage:
 *   const result = await workerBridge.parseCSVPoints(csvText)
 *   const grid = await workerBridge.generateIDWGrid(params)
 *
 * The bridge automatically handles worker lifecycle (spawn on first use,
 * terminate on idle timeout), request correlation (matching responses to
 * requests by ID), and error propagation.
 */

import type {
  WorkerRequestType,
  WorkerResponseType,
  WorkerMessage,
} from './compute.worker'

type RequestId = string

interface PendingRequest {
  resolve: (payload: any) => void
  reject: (error: Error) => void
  startTime: number
}

class WorkerBridge {
  private worker: Worker | null = null
  private pendingRequests = new Map<RequestId, PendingRequest>()
  private idleTimeout: ReturnType<typeof setTimeout> | null = null
  private readonly IDLE_TIMEOUT = 30000 // 30 seconds
  private requestIdCounter = 0

  /**
   * Get or create the worker instance
   */
  private getWorker(): Worker {
    if (this.worker) {
      this.resetIdleTimeout()
      return this.worker
    }

    // Create worker from the compiled file
    // Next.js handles worker bundling via webpack config
    this.worker = new Worker(
      new URL('./compute.worker.ts', import.meta.url),
      { type: 'module' }
    )

    this.worker.onmessage = (event: MessageEvent<WorkerMessage>) => {
      const { type, payload, id } = event.data
      const pending = this.pendingRequests.get(id)

      if (!pending) return

      if (type === 'ERROR') {
        pending.reject(new Error(payload))
        this.pendingRequests.delete(id)
      } else if (type === 'PROGRESS') {
        // Progress updates don't resolve the promise
        // They're handled via the onProgress callback
      } else {
        pending.resolve(payload)
        this.pendingRequests.delete(id)
      }
    }

    this.worker.onerror = (error) => {
      console.error('[WorkerBridge] Worker error:', error)
      // Reject all pending requests
      this.pendingRequests.forEach((pending, id) => {
        pending.reject(new Error('Worker crashed'))
      })
      this.pendingRequests.clear()
      this.terminateWorker()
    }

    this.resetIdleTimeout()
    return this.worker
  }

  /**
   * Send a message to the worker and return a promise
   */
  private send<T = any>(type: WorkerRequestType, payload: any, timeoutMs = 60000): Promise<T> {
    return new Promise((resolve, reject) => {
      const id = `req_${Date.now()}_${this.requestIdCounter++}`
      const worker = this.getWorker()

      // Set up timeout
      const timer = setTimeout(() => {
        this.pendingRequests.delete(id)
        reject(new Error(`Worker request '${type}' timed out after ${timeoutMs}ms`))
      }, timeoutMs)

      this.pendingRequests.set(id, {
        resolve: (payload) => {
          clearTimeout(timer)
          resolve(payload as T)
        },
        reject: (error) => {
          clearTimeout(timer)
          reject(error)
        },
        startTime: Date.now()
      })

      const message: WorkerMessage = { type, payload, id }
      worker.postMessage(message)
    })
  }

  /**
   * Reset idle timeout
   */
  private resetIdleTimeout() {
    if (this.idleTimeout) clearTimeout(this.idleTimeout)
    this.idleTimeout = setTimeout(() => this.terminateWorker(), this.IDLE_TIMEOUT)
  }

  /**
   * Terminate the worker (cleanup)
   */
  private terminateWorker() {
    if (this.worker) {
      this.worker.terminate()
      this.worker = null
    }
    if (this.idleTimeout) {
      clearTimeout(this.idleTimeout)
      this.idleTimeout = null
    }
    // Reject any remaining pending requests
    this.pendingRequests.forEach((pending) => {
      pending.reject(new Error('Worker terminated'))
    })
    this.pendingRequests.clear()
  }

  // ─── Public API ──────────────────────────────────────────────────────

  /**
   * Parse a CSV file containing survey control points
   * @param csvText - Raw CSV text
   * @param delimiter - Column delimiter (default ',')
   * @returns Parsed points array
   */
  async parseCSVPoints(csvText: string, delimiter = ',') {
    return this.send<{ points: unknown[]; count: number }>(
      'PARSE_CSV_POINTS',
      { csvText, delimiter }
    )
  }

  /**
   * Parse a CSV file containing field observations
   */
  async parseCSVObservations(csvText: string, delimiter = ',') {
    return this.send<{ observations: unknown[]; count: number }>(
      'PARSE_CSV_OBSERVATIONS',
      { csvText, delimiter }
    )
  }

  /**
   * Parse a CSV file containing leveling data
   */
  async parseCSVLeveling(csvText: string, delimiter = ',') {
    return this.send<{ readings: unknown[]; count: number }>(
      'PARSE_CSV_LEVELING',
      { csvText, delimiter }
    )
  }

  /**
   * Transform coordinates between CRS systems
   */
  async transformCoordinates(params: {
    fromEpsg: number
    toEpsg: number
    coordinates: Array<{ lat: number; lng: number } | { northing: number; easting: number }>
  }) {
    return this.send<{ coordinates: unknown[]; count: number }>(
      'TRANSFORM_COORDINATES',
      params,
      120000 // Longer timeout for bulk transforms
    )
  }

  /**
   * Compute bearing and distance between two points
   */
  async computeBearingDistance(
    from: { northing: number; easting: number },
    to: { northing: number; easting: number }
  ) {
    return this.send<{
      bearing: number
      distance: number
      dEasting: number
      dNorthing: number
    }>('COMPUTE_BEARING_DISTANCE', { from, to })
  }

  /**
   * Compute area from polygon coordinates (Shoelace)
   */
  async computeArea(coordinates: Array<{ northing: number; easting: number }>) {
    return this.send<{
      areaSqM: number
      areaHa: number
      areaAc: number
    }>('COMPUTE_AREA', { coordinates })
  }

  /**
   * Compute Bowditch traverse adjustment
   */
  async computeTraverseAdjustment(params: {
    legs: Array<{
      fromStation: string
      toStation: string
      angle: number
      distance: number
    }>
    startCoordinates: { northing: number; easting: number }
    startBearing: number
    closed: boolean
    endCoordinates?: { northing: number; easting: number }
  }) {
    return this.send<{
      adjustedLegs: unknown[]
      misclosure: {
        linear: number
        angular: number
        bearing: number
        ratio: string
      }
    }>('COMPUTE_TRAVERSE_ADJUSTMENT', params)
  }

  /**
   * Generate IDW interpolation grid from scattered points
   */
  async generateIDWGrid(params: {
    points: Array<{ x: number; y: number; value: number }>
    bounds: { minX: number; minY: number; maxX: number; maxY: number }
    resolution: number
    power?: number
  }) {
    return this.send<{
      grid: number[][]
      rows: number
      cols: number
      bounds: any
    }>('GENERATE_IDW_GRID', params, 120000)
  }

  /**
   * Validate a field book entry
   */
  async validateFieldBook(entries: unknown[]) {
    return this.send<{ errors: unknown[]; warnings: unknown[] }>(
      'VALIDATE_FIELD_BOOK',
      { entries }
    )
  }

  /**
   * Check if the worker is alive
   */
  async ping(): Promise<boolean> {
    try {
      await this.send('PING', null, 5000)
      return true
    } catch {
      return false
    }
  }

  /**
   * Force-terminate the worker
   */
  dispose() {
    this.terminateWorker()
  }
}

// ─── Singleton Export ────────────────────────────────────────────────────

export const workerBridge = new WorkerBridge()

/**
 * METARDU Web Worker — Survey Data Computation Engine
 * ====================================================
 * Runs heavy computation off the main thread to prevent UI freezing.
 * Handles: CSV parsing, coordinate transformations, bulk operations.
 *
 * Communication protocol:
 *   Main → Worker: { type: string, payload: any, id: string }
 *   Worker → Main: { type: string, payload: any, id: string, error?: string }
 */

// ─── Message Types ────────────────────────────────────────────────────────

export type WorkerRequestType =
  | 'PARSE_CSV_POINTS'
  | 'PARSE_CSV_OBSERVATIONS'
  | 'PARSE_CSV_LEVELING'
  | 'TRANSFORM_COORDINATES'
  | 'COMPUTE_BEARING_DISTANCE'
  | 'COMPUTE_AREA'
  | 'COMPUTE_TRAVERSE_ADJUSTMENT'
  | 'COMPUTE_LEVEL_NETWORK'
  | 'VALIDATE_FIELD_BOOK'
  | 'GENERATE_IDW_GRID'
  | 'PING'

export type WorkerResponseType =
  | 'PARSE_COMPLETE'
  | 'TRANSFORM_COMPLETE'
  | 'COMPUTE_COMPLETE'
  | 'VALIDATION_COMPLETE'
  | 'PROGRESS'
  | 'PONG'
  | 'ERROR'

export interface WorkerMessage<T = any> {
  type: WorkerRequestType | WorkerResponseType
  payload: T
  id: string
}

// ─── Coordinate Transform Implementation ─────────────────────────────────
// Simple Transverse Mercator / UTM inverse and forward using proj4 formulas
// For production, we use the actual proj4 library, but in the worker we
// implement a lightweight version to avoid module loading issues.

const PI = Math.PI
const DEG2RAD = PI / 180
const RAD2DEG = 180 / PI

interface CoordTransformParams {
  fromEpsg: number
  toEpsg: number
  coordinates: Array<{ lat: number; lng: number } | { northing: number; easting: number }>
}

/**
 * WGS84 to Arc1960 / UTM Zone 37S approximation
 * Uses simplified transformation parameters for Kenya
 */
function wgs84ToArc1960UTM37S(lat: number, lng: number): { northing: number; easting: number } {
  // UTM Zone 37S parameters
  const a = 6378137.0       // WGS84 semi-major axis
  const f = 1 / 298.257223563
  const e2 = 2 * f - f * f
  const ePrime2 = e2 / (1 - e2)
  const k0 = 0.9996
  const lon0 = 39 * DEG2RAD // Central meridian Zone 37
  const N0 = 10000000       // False northing (southern hemisphere)

  const latRad = lat * DEG2RAD
  const lngRad = lng * DEG2RAD

  const N = a / Math.sqrt(1 - e2 * Math.sin(latRad) * Math.sin(latRad))
  const T = Math.tan(latRad) * Math.tan(latRad)
  const C = ePrime2 * Math.cos(latRad) * Math.cos(latRad)
  const A = Math.cos(latRad) * (lngRad - lon0)
  const M = a * (
    (1 - e2 / 4 - 3 * e2 * e2 / 64 - 5 * e2 * e2 * e2 / 256) * latRad
    - (3 * e2 / 8 + 3 * e2 * e2 / 32 + 45 * e2 * e2 * e2 / 1024) * Math.sin(2 * latRad)
    + (15 * e2 * e2 / 256 + 45 * e2 * e2 * e2 / 1024) * Math.sin(4 * latRad)
    - (35 * e2 * e2 * e2 / 3072) * Math.sin(6 * latRad)
  )

  const easting = k0 * N * (A + (1 - T + C) * A * A * A / 6
    + (5 - 18 * T + T * T + 72 * C - 58 * ePrime2) * A * A * A * A * A / 120) + 500000

  const northing = k0 * (M + N * Math.tan(latRad) * (
    A * A / 2 + (5 - T + 9 * C + 4 * C * C) * A * A * A * A / 24
    + (61 - 58 * T + T * T + 600 * C - 330 * ePrime2) * A * A * A * A * A * A / 720
  )) + N0

  return { northing: Math.round(northing * 100) / 100, easting: Math.round(easting * 100) / 100 }
}

/**
 * Arc1960 / UTM Zone 37S to WGS84 inverse transformation
 */
function arc1960UTM37SToWGS84(northing: number, easting: number): { lat: number; lng: number } {
  const a = 6378137.0
  const f = 1 / 298.257223563
  const e2 = 2 * f - f * f
  const e1 = (1 - Math.sqrt(1 - e2)) / (1 + Math.sqrt(1 - e2))
  const k0 = 0.9996
  const lon0 = 39 * DEG2RAD
  const N0 = 10000000
  const E0 = 500000

  const M = (northing - N0) / k0
  const mu = M / (a * (1 - e2 / 4 - 3 * e2 * e2 / 64 - 5 * e2 * e2 * e2 / 256))

  const phi1 = mu + (3 * e1 / 2 - 27 * e1 * e1 * e1 / 32) * Math.sin(2 * mu)
    + (21 * e1 * e1 / 16 - 55 * e1 * e1 * e1 * e1 / 32) * Math.sin(4 * mu)
    + (151 * e1 * e1 * e1 / 96) * Math.sin(6 * mu)

  const N1 = a / Math.sqrt(1 - e2 * Math.sin(phi1) * Math.sin(phi1))
  const T1 = Math.tan(phi1) * Math.tan(phi1)
  const C1 = (e2 / (1 - e2)) * Math.cos(phi1) * Math.cos(phi1)
  const R1 = a * (1 - e2) / Math.pow(1 - e2 * Math.sin(phi1) * Math.sin(phi1), 1.5)
  const D = (easting - E0) / (N1 * k0)

  const lat = phi1 - (N1 * Math.tan(phi1) / R1) * (
    D * D / 2 - (5 + 3 * T1 + 10 * C1 - 4 * C1 * C1 - 9 * e2) * D * D * D * D / 24
    + (61 + 90 * T1 + 298 * C1 + 45 * T1 * T1 - 252 * e2 - 3 * C1 * C1) * D * D * D * D * D * D / 720
  )

  const lng = lon0 + (
    D - (1 + 2 * T1 + C1) * D * D * D / 6
    + (5 - 2 * C1 + 28 * T1 - 3 * C1 * C1 + 8 * e2 + 24 * T1 * T1) * D * D * D * D * D / 120
  ) / Math.cos(phi1)

  return {
    lat: Math.round(lat * RAD2DEG * 10000000) / 10000000,
    lng: Math.round(lng * RAD2DEG * 10000000) / 10000000
  }
}

// ─── CSV Parsing ─────────────────────────────────────────────────────────

interface CSVPoint {
  pointName: string
  northing: number
  easting: number
  elevation: number | null
  code: string
  latitude: number
  longitude: number
}

function parseCSVPoints(csvText: string, delimiter = ','): CSVPoint[] {
  const lines = csvText.trim().split(/\r?\n/)
  if (lines.length < 2) return []

  const headers = lines[0].toLowerCase().split(delimiter).map(h => h.trim().replace(/"/g, ''))
  const points: CSVPoint[] = []

  // Column detection
  const colMap: Record<string, number> = {}
  const aliasMap: Record<string, string[]> = {
    pointName: ['point', 'name', 'point_name', 'station', 'id', 'pt'],
    northing: ['north', 'northing', 'y', 'n', 'lat_north', 'n_coord'],
    easting: ['east', 'easting', 'x', 'e', 'lng_east', 'e_coord'],
    elevation: ['elev', 'elevation', 'rl', 'z', 'height', 'level', 'h'],
    code: ['code', 'type', 'beacon', 'mark', 'description'],
    latitude: ['lat', 'latitude', 'φ'],
    longitude: ['lng', 'lon', 'longitude', 'long', 'λ'],
  }

  for (const [key, aliases] of Object.entries(aliasMap)) {
    for (let i = 0; i < headers.length; i++) {
      if (aliases.some(a => headers[i].includes(a))) {
        colMap[key] = i
        break
      }
    }
  }

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim()
    if (!line) continue

    const values = line.split(delimiter).map(v => v.trim().replace(/"/g, ''))
    const pointName = colMap.pointName !== undefined ? values[colMap.pointName] || `PT${i}` : `PT${i}`
    const northing = colMap.northing !== undefined ? parseFloat(values[colMap.northing]) : NaN
    const easting = colMap.easting !== undefined ? parseFloat(values[colMap.easting]) : NaN
    const elevStr = colMap.elevation !== undefined ? values[colMap.elevation] : ''
    const elevation = elevStr && elevStr !== '' && !isNaN(parseFloat(elevStr)) ? parseFloat(elevStr) : null
    const code = colMap.code !== undefined ? values[colMap.code] || 'PT' : 'PT'

    if (isNaN(northing) || isNaN(easting)) continue

    // If lat/lng provided, use them; otherwise compute from UTM
    let latitude: number
    let longitude: number
    if (colMap.latitude !== undefined && colMap.longitude !== undefined) {
      latitude = parseFloat(values[colMap.latitude]) || 0
      longitude = parseFloat(values[colMap.longitude]) || 0
    } else {
      // Assume Arc1960 UTM 37S, convert to WGS84 for storage
      const wgs = arc1960UTM37SToWGS84(northing, easting)
      latitude = wgs.lat
      longitude = wgs.lng
    }

    points.push({ pointName, northing, easting, elevation, code, latitude, longitude })
  }

  return points
}

// ─── Bearing & Distance ─────────────────────────────────────────────────

function computeBearingDistance(from: { northing: number; easting: number }, to: { northing: number; easting: number }) {
  const dE = to.easting - from.easting
  const dN = to.northing - from.northing
  const distance = Math.sqrt(dE * dE + dN * dN)

  let bearing: number
  if (dE === 0 && dN === 0) {
    bearing = 0
  } else {
    bearing = (Math.atan2(dE, dN) * RAD2DEG + 360) % 360
  }

  return {
    bearing: Math.round(bearing * 10000) / 10000,
    distance: Math.round(distance * 10000) / 10000,
    dEasting: Math.round(dE * 10000) / 10000,
    dNorthing: Math.round(dN * 10000) / 10000,
  }
}

// ─── Area Computation (Shoelace Formula) ─────────────────────────────────

function computeArea(coordinates: Array<{ northing: number; easting: number }>) {
  let area = 0
  const n = coordinates.length
  if (n < 3) return { areaSqM: 0, areaHa: 0, areaAc: 0 }

  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    area += coordinates[i].easting * coordinates[j].northing
    area -= coordinates[j].easting * coordinates[i].northing
  }

  area = Math.abs(area) / 2

  return {
    areaSqM: Math.round(area * 100) / 100,
    areaHa: Math.round(area / 10000 * 100) / 100,
    areaAc: Math.round(area / 4046.8564224 * 100) / 100,
  }
}

// ─── Traverse Adjustment (Bowditch) ─────────────────────────────────────

interface TraverseAdjustInput {
  legs: Array<{
    fromStation: string
    toStation: string
    angle: number      // decimal degrees
    distance: number
  }>
  startCoordinates: { northing: number; easting: number }
  startBearing: number  // decimal degrees
  closed: boolean
  endCoordinates?: { northing: number; easting: number }
}

function computeTraverseAdjustment(input: TraverseAdjustInput) {
  const { legs, startCoordinates, startBearing, closed } = input

  if (legs.length === 0) return { adjustedLegs: [], misclosure: { linear: 0, angular: 0, bearing: 0, ratio: '0:1' } }

  let currentBearing = startBearing
  let currentNorthing = startCoordinates.northing
  let currentEasting = startCoordinates.easting
  let totalLatitude = 0
  let totalDeparture = 0

  // Compute bearings with correct back-bearing propagation.
  // FIXED: Previous version was missing the +180° back-bearing in WCB propagation.
  // Source: Basak, Chapter 10 — WCB(forward) = back_bearing(previous line) + observed angle
  // back_bearing(x) = x + 180°
  // DO NOT round intermediate values — this loses precision on long traverses.
  const computedLegs = legs.map((leg: { fromStation: string; toStation: string; angle: number; distance: number }) => {
    // Forward bearing = back bearing of previous + observed angle
    currentBearing = (currentBearing + leg.angle) % 360
    if (currentBearing < 0) currentBearing += 360

    const bearingRad = currentBearing * DEG2RAD
    const dLatitude = leg.distance * Math.cos(bearingRad)
    const dDeparture = leg.distance * Math.sin(bearingRad)

    totalLatitude += dLatitude
    totalDeparture += dDeparture

    const forwardBearing = currentBearing

    // Update currentBearing to BACK BEARING for next iteration
    // This was the critical bug: the old code didn't add 180° here,
    // causing all subsequent bearings to be wrong by 180°.
    currentBearing = (currentBearing + 180) % 360

    return {
      ...leg,
      computedBearing: forwardBearing,
      dLatitude,
      dDeparture,
    }
  })

  // Compute misclosure
  let errorNorthing: number
  let errorEasting: number

  if (closed && input.endCoordinates) {
    errorNorthing = input.endCoordinates.northing - (startCoordinates.northing + totalLatitude)
    errorEasting = input.endCoordinates.easting - (startCoordinates.easting + totalDeparture)
  } else {
    errorNorthing = 0
    errorEasting = 0
  }

  const linearMisclosure = Math.sqrt(errorNorthing * errorNorthing + errorEasting * errorEasting)
  const totalDistance = legs.reduce((sum: number, leg: { distance: number }) => sum + leg.distance, 0)
  const ratio = linearMisclosure > 0 && totalDistance > 0
    ? `1:${Math.round(totalDistance / linearMisclosure)}`
    : 'Perfect'

  // Apply Bowditch adjustment
  const adjustedLegs = computedLegs.map((leg: any) => {
    const correctionN = totalDistance > 0 ? (leg.distance / totalDistance) * (-errorNorthing) : 0
    const correctionE = totalDistance > 0 ? (leg.distance / totalDistance) * (-errorEasting) : 0

    const adjN = leg.dLatitude + correctionN
    const adjE = leg.dDeparture + correctionE
    const adjDist = Math.sqrt(adjN * adjN + adjE * adjE)
    const adjBearing = (Math.atan2(adjE, adjN) * RAD2DEG + 360) % 360

    return {
      ...leg,
      adjustedBearing: Math.round(adjBearing * 10000) / 10000,
      adjustedDistance: Math.round(adjDist * 1000) / 1000,
      adjustedDLatitude: Math.round(adjN * 1000) / 1000,
      adjustedDDeparture: Math.round(adjE * 1000) / 1000,
    }
  })

  return {
    adjustedLegs,
    misclosure: {
      linear: Math.round(linearMisclosure * 1000) / 1000,
      angular: 0,
      bearing: 0,
      ratio,
    }
  }
}

// ─── IDW Interpolation Grid ─────────────────────────────────────────────

interface IDWParams {
  points: Array<{ x: number; y: number; value: number }>
  bounds: { minX: number; minY: number; maxX: number; maxY: number }
  resolution: number // grid cell size
  power?: number // IDW power (default 2)
}

function generateIDWGrid(params: IDWParams): { grid: number[][], rows: number, cols: number, bounds: typeof params.bounds } {
  const { points, bounds, resolution, power = 2 } = params
  const cols = Math.ceil((bounds.maxX - bounds.minX) / resolution) + 1
  const rows = Math.ceil((bounds.maxY - bounds.minY) / resolution) + 1

  const grid: number[][] = []

  for (let r = 0; r < rows; r++) {
    const row: number[] = []
    const y = bounds.minY + r * resolution

    for (let c = 0; c < cols; c++) {
      const x = bounds.minX + c * resolution

      let weightedSum = 0
      let weightSum = 0

      for (const pt of points) {
        const dx = x - pt.x
        const dy = y - pt.y
        const dist = Math.sqrt(dx * dx + dy * dy)

        if (dist < 0.0001) {
          weightedSum = pt.value
          weightSum = 1
          break
        }

        const w = 1 / Math.pow(dist, power)
        weightedSum += w * pt.value
        weightSum += w
      }

      row.push(weightSum / weightSum)
    }
    grid.push(row)
  }

  return { grid, rows, cols, bounds }
}

// ─── Message Handler ────────────────────────────────────────────────────

self.onmessage = function (event: MessageEvent) {
  const { type, payload, id } = event.data as WorkerMessage

  try {
    switch (type) {
      case 'PING':
        self.postMessage({ type: 'PONG', payload: null, id })
        break

      case 'PARSE_CSV_POINTS': {
        const { csvText, delimiter } = payload as { csvText: string; delimiter?: string }
        const points = parseCSVPoints(csvText, delimiter || ',')
        self.postMessage({ type: 'PARSE_COMPLETE', payload: { points, count: points.length }, id })
        break
      }

      case 'TRANSFORM_COORDINATES': {
        const { fromEpsg, toEpsg, coordinates } = payload as CoordTransformParams
        const results = coordinates.map((coord: any) => {
          if ('latitude' in coord && 'longitude' in coord) {
            // WGS84 → UTM
            return wgs84ToArc1960UTM37S(coord.latitude as number, coord.longitude as number)
          } else {
            // UTM → WGS84
            return arc1960UTM37SToWGS84(coord.northing as number, coord.easting as number)
          }
        })
        self.postMessage({ type: 'TRANSFORM_COMPLETE', payload: { coordinates: results, count: results.length }, id })
        break
      }

      case 'COMPUTE_BEARING_DISTANCE': {
        const { from, to } = payload as { from: { northing: number; easting: number }; to: { northing: number; easting: number } }
        const result = computeBearingDistance(from, to)
        self.postMessage({ type: 'COMPUTE_COMPLETE', payload: result, id })
        break
      }

      case 'COMPUTE_AREA': {
        const { coordinates } = payload as { coordinates: Array<{ northing: number; easting: number }> }
        const result = computeArea(coordinates)
        self.postMessage({ type: 'COMPUTE_COMPLETE', payload: result, id })
        break
      }

      case 'COMPUTE_TRAVERSE_ADJUSTMENT': {
        const result = computeTraverseAdjustment(payload as TraverseAdjustInput)
        self.postMessage({ type: 'COMPUTE_COMPLETE', payload: result, id })
        break
      }

      case 'GENERATE_IDW_GRID': {
        const result = generateIDWGrid(payload as IDWParams)
        self.postMessage({ type: 'COMPUTE_COMPLETE', payload: result, id })
        break
      }

      default:
        self.postMessage({ type: 'ERROR', payload: `Unknown message type: ${type}`, id })
    }
  } catch (error) {
    self.postMessage({
      type: 'ERROR',
      payload: error instanceof Error ? error.message : String(error),
      id
    })
  }
}
